	-- LFGParentFrame and its pages: loaded with Blizzard_GroupFinder_VanillaStyle.
	local function buildGroupFinder()
		local lfg, lr = wframe(env.UIParent, nil, { name = "LFGParentFrame", hidden = true, width = 458, height = 535 })
		W.win.lfg = lfg
		-- $parentCloseButton has no parentKey.
		closeButton(lfg, nil, "LFGParentFrameCloseButton")
		for index = 1, 3 do
			panelTab(lfg, "LFGParentFrameTab" .. index)
			lr["Tab" .. index] = env["LFGParentFrameTab" .. index]
			raw(env["LFGParentFrameTab" .. index]).shown = false
		end
		local eye = wbutton(lfg, nil, { name = "LFGParentFramePortrait", width = 64, height = 64 })
		wtex(eye, "texture", "groupfinder-eye-frame")
		for _, key in ipairs({ "EyeInitial", "EyeSearchingLoop", "EyeMouseOver", "EyePokeInitial", "EyePokeLoop", "EyePokeEnd" }) do
			wframe(eye, key, { hidden = true })
		end
		local keys, icons = { "ListingTab", "BrowsingTab", "WhoListingTab" }, { "INV_SideTab_GroupFinder_c60", "INV_SideTab_GroupBrowsing_c60", "INV_SideTab_WhoList_c60" }
		for index = 1, 3 do
			sideTab(lfg, keys[index], nil, index, "Interface\\ICONS\\" .. icons[index], 30)
		end

		-- LFGListingFrame (PortraitFrameTemplateNoCloseButton): a textured portrait frame with its own parts.
		local listing, listR = portraitFrame(lfg, nil, { name = "LFGListingFrame", hidden = true }, "textured")
		local roles = wframe(listing, "RolesSection")
		wtex(roles, nil, "groupfinder-roles-background", { name = "LFGListingFrameRoleBackground" })
		local insetFrame = wframe(listing, "Inset")
		wtex(insetFrame, "CustomBG", "groupfinder-background")
		wtex(insetFrame, "Border", "common-insideframe")
		local divider = wframe(listing, "DividerFrame")
		wtex(divider, "Divider", "common-framedivider")
		panelButton(listing, "BackButton", "LFGListingFrameBackButton", 111, 28)
		panelButton(listing, "PostButton", "LFGListingFramePostButton", 109, 28)
		local solo = wframe(listing, "SoloRoleButtons", { name = "LFGListingFrameSoloRoleButtons" })
		raw(solo).RoleButtons = {}
		for index, role in ipairs({ "TANK", "HEALER", "DAMAGER" }) do
			local roleButton = wbutton(solo, nil, { name = "LFGListingFrameSoloRoleButtons" .. role, width = 64, height = 64 })
			wtex(roleButton, "Background", nil)
			raw(raw(roleButton).Background).file = "Interface\\LFGFrame\\UI-LFG-ICONS-ROLEBACKGROUNDS"
			wtex(roleButton, "cover", nil, { alpha = 0.5, hidden = true })
			wstate(roleButton, "Normal", nil)
			checkButton(roleButton, "CheckButton", nil, 24)
			raw(solo).RoleButtons[index] = roleButton
		end
		local group = wframe(listing, "GroupRoleButtons", { name = "LFGListingFrameGroupRoleButtons", hidden = true })
		local icon = wbutton(group, "RoleIcon", { name = "LFGListingFrameGroupRoleButtonsRole", width = 64, height = 64 })
		wtex(icon, "Background", nil, { alpha = 0.6 })
		wtex(icon, "cover", nil, { alpha = 0.5, hidden = true })
		panelButton(group, "RolePollButton", nil, 120, 22)
		dropdown(group, "RoleDropdown", "LFGListingFrameGroupRoleButtonsRoleDropdown")
		local view = wframe(listing, "CategoryView", { name = "LFGListingFrameCategoryView" })
		raw(view).CategoryButtons = {}
		wframe(listing, "ActivityView", { name = "LFGListingFrameActivityView", hidden = true })
		wtex(raw(listing).ActivityView, "BarTop", nil)
		-- The comment box is a UIPanelInputScrollFrameTemplate: nine keyed border textures, an EditBox in the scroll child, and the
		-- old Slider scroll bar with its two buttons and a thumb texture.
		local activity = raw(listing).ActivityView
		local comment, commentRaw = wframe(activity, "Comment", { name = "LFGListingComment", objectType = "ScrollFrame" })
		for _, part in ipairs({ "TopLeftTex", "TopTex", "TopRightTex", "LeftTex", "MiddleTex", "RightTex", "BottomLeftTex", "BottomTex", "BottomRightTex" }) do
			local cap = wtex(comment, part, nil)
			raw(cap).file = "Interface/Common/Common-Input-Border"
		end
		local commentEdit, commentEditRaw = wframe(comment, "EditBox", { objectType = "EditBox" })
		commentEditRaw.HighlightText = function() end
		local slider = wframe(comment, "ScrollBar", { name = "LFGListingCommentScrollBar", objectType = "Slider" })
		wbutton(slider, "ScrollUpButton", { name = "LFGListingCommentScrollBarScrollUpButton", width = 18, height = 16 })
		wbutton(slider, "ScrollDownButton", { name = "LFGListingCommentScrollBarScrollDownButton", width = 18, height = 16 })
		wtex(slider, "ThumbTexture", nil)
		W.win.comment = comment
		scrollBar(listing, "ScrollBar")
		-- LFGBrowseFrame and LFGWhoListFrame.
		local browse = portraitFrame(lfg, nil, { name = "LFGBrowseFrame", hidden = true }, "textured")
		wtex(browse, "BackgroundArt", nil)
		local bi = wframe(browse, "Inset")
		wtex(bi, "CustomBG", "groupfinder-background")
		wtex(bi, "Border", "common-insideframe")
		panelButton(browse, "RefreshButton", "LFGBrowseFrameRefreshButton", 100, 22)
		dropdown(browse, "CategoryDropdown", "LFGBrowseFrameCategoryDropdown", true)
		local who = portraitFrame(lfg, nil, { name = "LFGWhoListFrame", hidden = true }, "textured")
		wtex(who, "BackgroundArt", nil)
		wtex(who, "headerBackground", nil)
		wtex(who, "BarTop", nil)
		wtex(who, "BarMiddle", nil)
		local insideFrame = wframe(who, "insideFrame")
		wtex(insideFrame, nil, "common-insideframe")
		W.win.listing, W.win.browse, W.win.who, W.win.categoryView = listing, browse, who, view
		-- LFGParentFrameMixin:UpdateTabs: the first tab is selected.
		W.blizzard(function()
			for index, key in ipairs(keys) do
				lr[key]:SetChecked(index == 1)
			end
		end)
		return lfg
	end

	-- A button of the Looking For Group category list: made by CreateFrame in Lua when the list is longer than the last time.
	function W.win.newCategoryButton(index)
		local view = W.win.categoryView
		local was = W.group
		W.group = "windows"
		local button, r = wbutton(view, nil, { width = 300, height = 70, hidden = true })
		W.group = was
		wtex(button, "Icon", "groupfinder-button-battlegrounds")
		wtex(button, "Cover", "groupfinder-button-cover")
		wstate(button, "Pushed", "groupfinder-button-cover-down")
		wstate(button, "Highlight", "groupfinder-button-cover-hover", { key = "HighlightTexture" })
		wfont(button, "Label")
		local list = raw(view).CategoryButtons
		list[index] = button
		W.seal()
		return button
	end
	-- LFGListingCategorySelection_UpdateCategoryButtons (Blizzard_LFGVanilla_Listing.lua:692-733): `count` buttons are shown.
	function W.win.defineGroupFinderFunctions()
		function env.LFGListingCategorySelection_AddButton(view, index, categoryID)
			local list = raw(view).CategoryButtons
			local button = list[index]
			if not button then
				button = W.win.newCategoryButton(index)
			end
			local icon = raw(button).Icon
			if icon then
				raw(icon):SetAtlas("groupfinder-button-" .. tostring(categoryID))
			end
			raw(button).shown = true
			return index + 1
		end
		function env.LFGListingCategorySelection_UpdateCategoryButtons(view)
			local count = W.win.categoryCount or 0
			local nextButton = 1
			for id = 1, count do
				nextButton = env.LFGListingCategorySelection_AddButton(view, nextButton, id)
			end
			local list = raw(view).CategoryButtons
			for index = nextButton, #list do
				raw(list[index]).shown = false
			end
		end
	end
	function W.win.updateCategories(count)
		W.win.categoryCount = count
		W.blizzard(function() env.LFGListingCategorySelection_UpdateCategoryButtons(W.win.categoryView) end)
	end

	-- Friends -----------------------------------------------------------------------------------------
	local function buildFriends()
