	-- The calls of the game the addon listens to, as the game makes them: choosing a mode tab ends in the click of the tab, the game's portrait event
	-- sets the portrait again, and every one is followed by the frame the addon waits.
	function W.win.choose(index, cf)
		W.blizzard(function() (cf or env.CharacterFrame):SetSelectedModeTabByFrame(index) end)
		W.fireScript(raw(raw(cf or env.CharacterFrame).ModeTabs).Tabs[index], "OnMouseUp")
		W.flush()
	end
	function W.win.portrait(cf)
		W.blizzard(function() (cf or env.CharacterFrame):UpdateCharacterModeTabPortrait() end)
		W.fire("PORTRAITS_UPDATED")
		W.flush()
	end
	function W.win.collapse(collapsed, cf)
		W.blizzard(function() (cf or env.CharacterFrame):SetRightPaneCollapsed(collapsed) end)
		W.flush()
	end
	function W.win.bankPage()
		W.blizzard(function() env.EventRegistry:TriggerEvent("BankPanelMixin.PageInfoChanged", 1) end)
		W.flush()
	end
	function W.win.updateBags()
		W.blizzard(function() env.ContainerFrame_UpdateAll() end)
		W.flush()
	end
	-- The builders, for a test that makes a window of its own.
	W.win.frame, W.win.tex, W.win.font, W.win.button, W.win.panelButton, W.win.itemButton, W.win.scrollBar = wframe, wtex, wfont, wbutton, panelButton, itemButton, scrollBar
	W.win.checkButton, W.win.editBox, W.win.dropdown, W.win.progressBar, W.win.panelTab, W.win.closeButton, W.win.inset = checkButton, editBox, dropdown, progressBar, panelTab, closeButton, inset
	W.win.portraitFrame, W.win.sideTab, W.win.threeSlice, W.win.state, W.win.mask, W.win.cooldown = portraitFrame, sideTab, threeSlice, wstate, wmask, cooldown
	-- Bags, bank, spell windows and menus: built for opts.windows.second = true. With second = "demand" the windows of
	-- load-on-demand addons come with W.win.loadSpells(addon), which also fires ADDON_LOADED.
	local DIALOG_ATLAS = { "UI-Frame-DiamondMetal-CornerTopLeft", "UI-Frame-DiamondMetal-CornerTopRight", "UI-Frame-DiamondMetal-CornerBottomLeft",
		"UI-Frame-DiamondMetal-CornerBottomRight", "_UI-Frame-DiamondMetal-EdgeTop", "_UI-Frame-DiamondMetal-EdgeBottom",
		"!UI-Frame-DiamondMetal-EdgeLeft", "!UI-Frame-DiamondMetal-EdgeRight" }
	local function nop() end
	-- PortraitFrameFlatTemplate: Bg is a frame of four flat textures. SetBackgroundColor sets their alpha again.
	local function flatWindow(name, more)
		local frame, r = portraitFrame(env.UIParent, nil, { name = name, hidden = true, width = 256, height = 256 }, "base")
		local bg = wframe(frame, "Bg", {})
		for _, part in ipairs({ "BottomLeft", "BottomRight", "BottomEdge", "TopSection" }) do
			wtex(bg, part, nil)
		end
		closeButton(frame, "CloseButton", name .. "CloseButton")
		-- Blizzard_UIPanels_Game/Mainline/ContainerFrame.xml:202-225, 289, 316: the coin box is a frame of three pieces.
		local border = wframe(wframe(frame, "MoneyFrame", {}), "Border", {})
		for _, part in ipairs({ "Left", "Right", "Middle" }) do
			wtex(border, part, "common-coinbox-" .. part:lower())
		end
		r.UpdateItems = nop
		-- ContainerFrameMixin:EnumerateValidItems (Mainline/ContainerFrame.lua:575-577): the item buttons of the bag, in order.
		r.EnumerateValidItems = function()
			local list, at = {}, 0
			for _, child in ipairs(r.children) do
				if raw(child).bagButton then
					list[#list + 1] = child
				end
			end
			return function()
				at = at + 1
				if list[at] then
					return at, list[at]
				end
			end
		end
		r.SetBackgroundColor = function()
			for _, part in ipairs({ "BottomLeft", "BottomRight", "BottomEdge", "TopSection" }) do
				raw(raw(bg)[part]).alpha = 1
			end
		end
		return frame, r
	end
	-- A bag slot: an ItemButton whose icon is a picture of an empty slot when there is no item.
	function W.win.addBagSlot(bag, index)
		local was = W.group
		W.group = "windows"
		local slot, sr = itemButton(bag, nil, raw(bag).fname .. "Item" .. index)
		sr.emptyBackgroundAtlas = "bags-item-slot64"
		-- ContainerFrameItemButtonMixin:GetBagID (Mainline/ContainerFrame.lua:1831-1833).
		sr.slotId, sr.bagButton = index, true
		sr.GetBagID = function() return raw(bag).bagID or 0 end
		W.group = was
		W.seal()
		return slot
	end
	local function dialog(name, width, height)
		local frame = wframe(env.UIParent, nil, { name = name, hidden = true, width = width, height = height })
		local border = wframe(frame, "Border", {})
		for index, piece in ipairs(NINE) do
			wtex(border, piece, DIALOG_ATLAS[index])
		end
		wtex(border, "Bg", nil)
		local header = wframe(frame, "Header", {})
		wtex(header, "LeftBG", "UI-Frame-DiamondMetal-Header-CornerLeft")
		wtex(header, "RightBG", "UI-Frame-DiamondMetal-Header-CornerRight")
		wtex(header, "CenterBG", "_UI-Frame-DiamondMetal-Header-Tile")
		wfont(header, "Text")
		return frame
	end
	-- StaticPopupButtonTemplate: a plate in each state, a flash and a label.
	local function plainButton(parent, key, name)
		local button, r = wbutton(parent, key, { name = name, width = 128, height = 21 })
		r.baseWidth, r.baseHeight = 128, 21
		wtex(button, "Flash", nil, { alpha = 0 })
		wfont(button, "Text")
		for _, which in ipairs({ "Normal", "Pushed", "Disabled", "Highlight" }) do
			wstate(button, which, nil)
		end
		return button
	end
	local function buildBags()
		-- The game's registry, for the bank's page announcement; a world with the menus builds its own over this one.
		if not env.EventRegistry then
			local registry = { callbacks = {} }
			function registry:RegisterCallback(event, func, owner)
				if type(event) ~= "string" or type(func) ~= "function" then
					error("CallbackRegistryMixin::RegisterCallback needs an event and a function", 0)
				end
				registry.callbacks[event] = registry.callbacks[event] or {}
				table.insert(registry.callbacks[event], { owner = owner, func = func })
				return owner
			end
			function registry:TriggerEvent(event, ...)
				for _, entry in ipairs(registry.callbacks[event] or {}) do
					local ok, err = pcall(entry.func, entry.owner, ...)
					if not ok then
						W.errors[#W.errors + 1] = tostring(err)
					end
				end
			end
			env.EventRegistry = registry
		end
		for _, name in ipairs({ "ContainerFrame1", "ContainerFrame2", "ContainerFrameCombinedBags" }) do
			flatWindow(name)
		end
		W.win.addBagSlot(env.ContainerFrame1, 1)
		local bank, br = portraitFrame(env.UIParent, nil, { name = "BankFrame", hidden = true, width = 738, height = 460 }, "textured")
		wtex(bank, "Background", "bank-frame-background")
		closeButton(bank, "CloseButton", "BankFrameCloseButton")
		local panel, pr = wframe(bank, "BankPanel", { name = "BankPanel" })
		pr.layoutType = "InsetFrameTemplate"
		nineSlice(panel, INSET_ATLAS)
		wtex(wframe(panel, "EdgeShadows", {}), "TopShadow", "_bank-frame-horiz-shadow")
		br.RefreshPageTabs, br.RefreshBagButtons = nop, nop
		-- BankPanelMixin:GenerateItemSlotsForSelectedTab announces the page it lays out on the registry before it makes the slots (BankFrameTemplates.lua:1117).
		pr.GenerateItemSlotsForSelectedTab = luaMethod("GenerateItemSlotsForSelectedTab", function()
			if env.EventRegistry then
				env.EventRegistry:TriggerEvent("BankPanelMixin.PageInfoChanged", 1)
			end
		end)
		-- The game's global functions that update the bags (ContainerFrame.lua:1267-1312): UpdateAll updates the items of each bag, and GenerateFrame sets the
		-- background of a bag it opens and updates its items.
		env.ContainerFrame_UpdateAll = luaMethod("ContainerFrame_UpdateAll", function()
			for _, name in ipairs({ "ContainerFrame1", "ContainerFrame2", "ContainerFrameCombinedBags" }) do
				if env[name] then
					env[name]:UpdateItems()
				end
			end
		end)
		env.ContainerFrame_GenerateFrame = luaMethod("ContainerFrame_GenerateFrame", function(frame)
			frame:SetBackgroundColor()
			frame:UpdateItems()
		end)
	end
	local SPELL_WINDOWS = { Blizzard_PlayerSpells = "PlayerSpellsFrame", Blizzard_Professions = "ProfessionsFrame", Blizzard_LegacySystem = "LegacySystemFrame" }
	local function buildSpells(addon)
		local name = SPELL_WINDOWS[addon]
		local frame = portraitFrame(env.UIParent, nil, { name = name, hidden = true, width = 673, height = 594 }, "textured")
		closeButton(frame, "CloseButton", name .. "CloseButton")
		sideTab(frame, "Tab1", nil, 1, "Interface/ICONS/INV_SideTab_Professions_c60", name == "ProfessionsFrame" and 30 or nil)
		panelButton(frame, "ApplyButton", nil, 100, 22)
		-- Blizzard_PlayerSpells/Camelot/Blizzard_PlayerSpellsFrame.xml:33-57 makes the three pages children at frame level 100. The book's art is
		-- SpellBook/Blizzard_SpellBookFrame.xml:10-27, the talent tab's Camelot/ClassTalents/Blizzard_ClassTalentsFrame.xml:177, 186 and 314.
		-- Blizzard_LegacySystem.xml:40-42 makes the pages of the Legacy window, each with a Background: Blizzard_LegacyRewardTrack.xml:81,
		-- Blizzard_LegacyChallenges.xml:41, Blizzard_LegacyTree.xml:295.
		if name == "PlayerSpellsFrame" then
			local book = wframe(frame, "SpellBookFrame", { hidden = true })
			for _, key in ipairs({ "TopBar", "BookBGHalved", "BookBGLeft", "BookBGRight", "BookCornerFlipbook", "Bookmark" }) do
				wtex(book, key, nil)
			end
			local talents = wframe(frame, "TalentsFrame", { hidden = true })
			for _, key in ipairs({ "Background", "ClassBackground", "BackgroundBorder" }) do
				wtex(talents, key, nil)
			end
		elseif name == "LegacySystemFrame" then
			for _, key in ipairs({ "RewardTrackPage", "ChallengesPage", "TreePage" }) do
				wtex(wframe(frame, key, { hidden = true }), "Background", nil)
			end
		end
		W.win.loaded[addon] = true
	end
	function W.win.loadSpells(addon)
		local was = W.group
		W.group = "windows"
		buildSpells(addon)
		W.group = was
		W.seal()
		W.fire("ADDON_LOADED", addon)
	end
	-- The options window replaces the stand-in that the settings of this addon use as SettingsPanel.
	function W.win.addOptions()
