	local function buildMenus()
		local menu = dialog("GameMenuFrame", 260, 300)
		threeSlice(menu, nil, "GameMenuButton1", "128-RedButton")
		threeSlice(menu, nil, "GameMenuButton2", "128-RedButton")
		local picker = dialog("ColorPickerFrame", 388, 210)
		panelButton(wframe(picker, "Footer", {}), "OkayButton", nil, 154, 22)
		local addons = portraitFrame(env.UIParent, nil, { name = "AddonList", hidden = true, width = 500, height = 480 }, "textured")
		closeButton(addons, "CloseButton", "AddonListCloseButton", true)
		inset(addons, "Inset", "AddonListInset")
		for index = 1, 4 do
			local popup = wframe(env.UIParent, nil, { name = "StaticPopup" .. index, hidden = true, width = 320, height = 72 })
			local back = wframe(popup, "BG", {})
			wtex(back, "Top", nil)
			wtex(back, "Bottom", nil)
			plainButton(popup, "Button1", "StaticPopup" .. index .. "Button1")
		end
		-- Blizzard_FrameXML/Camelot/StackSplitFrame.xml:3-14, 56, 65: two background textures, a number and two panel buttons.
		local split = wframe(env.UIParent, nil, { name = "StackSplitFrame", hidden = true, width = 172, height = 96 })
