	-- flight map come with W.win.loadMore(addon), which also fires ADDON_LOADED.
	local TIP_ATLAS = { "Tooltip-NineSlice-CornerTopLeft", "Tooltip-NineSlice-CornerTopRight", "Tooltip-NineSlice-CornerBottomLeft",
		"Tooltip-NineSlice-CornerBottomRight", "_Tooltip-NineSlice-EdgeTop", "_Tooltip-NineSlice-EdgeBottom", "!Tooltip-NineSlice-EdgeLeft", "!Tooltip-NineSlice-EdgeRight" }
	-- A scroll box announces the end of its Update on its callback registry (ScrollBox.lua:557-558, 795): the callbacks of OnUpdate run at the end of Update,
	-- after `before` has made what the update makes.
	function W.win.watchable(box, before)
		local r = raw(box)
		r.callbacks = {}
		r.RegisterCallback = function(_, event, func, owner)
			if type(event) ~= "string" or type(func) ~= "function" or owner == nil then
				bad(W, "RegisterCallback arguments")
			end
			r.callbacks[event] = r.callbacks[event] or {}
			r.callbacks[event][owner] = func
			W.boxCallbacks = (W.boxCallbacks or 0) + 1
		end
		r.Update = luaMethod("Update", function()
			if before then
				before()
			end
			for owner, func in pairs(r.callbacks.OnUpdate or {}) do
				func(owner)
			end
		end)
		return r
	end
	-- A scroll list: the ScrollBox has a ScrollTarget and an Update that makes the rows in view, as the view of the game does.
	local function scrollList(parent, key, make)
		local box, r = wframe(parent, key, {})
		wframe(box, "ScrollTarget", {})
		r.made, r.want = 0, 0
		W.win.watchable(box, function()
			while r.made < r.want do
				r.made = r.made + 1
				make(raw(box).ScrollTarget, r.made)
			end
		end)
		return box, r
	end
	function W.win.updateList(box, count)
		raw(box).want = count
		W.blizzard(function() box:Update() end)
		W.flush()
	end
