	-- BasicFrameTemplate: the border in textures of the frame itself and a close button, and with an inset the inset's border too.
	local BASIC_PIECES = { "TopLeftCorner", "TopRightCorner", "TopBorder", "BotLeftCorner", "BotRightCorner", "BottomBorder", "LeftBorder", "RightBorder",
		"TitleBg", "Bg", "TopTileStreaks" }
	local BASIC_INSET = { "InsetBg", "InsetBorderTopLeft", "InsetBorderTopRight", "InsetBorderBottomLeft", "InsetBorderBottomRight", "InsetBorderTop",
		"InsetBorderBottom", "InsetBorderLeft", "InsetBorderRight" }
	local function basicFrame(name, withInset, width, height)
		local frame = wframe(env.UIParent, nil, { name = name, hidden = true, width = width, height = height })
		for _, key in ipairs(BASIC_PIECES) do
			wtex(frame, key, nil)
		end
		if withInset then
