		end
		-- Blizzard_CompactRaidFrames/Mainline/Blizzard_CompactRaidFrameManager.xml:112-124, 391-403: a Background over the whole frame and two buttons.
		local manager = wframe(env.UIParent, nil, { name = "CompactRaidFrameManager", hidden = true, width = 200, height = 200 })
		wtex(manager, "Background", nil)
		panelButton(wframe(manager, "BottomButtons", {}), nil, "CompactRaidFrameManagerLeavePartyButton", 100, 22)
		-- Menus: frames the game takes from a pool, with a background texture that goes back to the pool when the menu closes.
		local registry = { callbacks = {} }
		function registry:RegisterCallback(event, func, owner)
			if type(event) ~= "string" or type(func) ~= "function" then
				error("CallbackRegistryMixin::RegisterCallback needs an event and a function", 0)
			end
			registry.callbacks[event] = registry.callbacks[event] or {}
			table.insert(registry.callbacks[event], { owner = owner, func = func })
			return owner
		end
		function registry:TriggerEvent(event, ...)
			for _, entry in ipairs(registry.callbacks[event] or {}) do
				local ok, err = pcall(entry.func, entry.owner, ...)
				if not ok then
					W.errors[#W.errors + 1] = tostring(err)
				end
			end
		end
		env.EventRegistry = registry
		W.win.registry = registry
		W.win.menus = {}
		for index = 1, 2 do
			local menu, mr = wframe(env.UIParent, nil, { hidden = true, width = 160, height = 120 })
			-- The game refuses a texture made on a menu frame.
			mr.CreateTexture = function()
				bad(W, "a texture was made on a menu frame")
			end
			wtex(menu, "Background", nil, { layer = "ARTWORK", sublevel = 7 })
			W.win.menus[index] = menu
		end
		-- The game takes a menu from the pool, builds it and shows it: the background gets the picture of the style, then the event comes.
		function W.win.openMenu(index, style)
			local menu = W.win.menus[index]
			local back = raw(raw(menu).Background)
			back.atlas, back.alpha, back.shown = style == 2 and "common-dropdown-c-bg" or "common-dropdown-bg", style == 2 and 1 or 0.925, true
			raw(menu).shown = true
			W.blizzard(function() registry:TriggerEvent("MenuProxy.OnShow", menu) end)
		end
		-- It closes and the pool resets the texture, which is a row icon the next time.
		function W.win.closeMenu(index)
			local menu = W.win.menus[index]
			local back = raw(raw(menu).Background)
			back.atlas, back.alpha, back.shown = nil, 1, false
			raw(menu).shown = false
		end
		-- The frame of the addon's inside a menu.
		function W.win.menuBox(index)
			for _, frame in ipairs(W.addonFrames) do
				if frame.parent == W.win.menus[index] then
					return frame
				end
			end
		end
		if wopts.more ~= "demand" then
			for addon, build in pairs(MORE_LOADED) do
				build()
				W.win.loaded[addon] = true
			end
		end
		env.C_AddOns = env.C_AddOns or {}
		env.C_AddOns.IsAddOnLoaded = env.C_AddOns.IsAddOnLoaded or function(addon) return W.win.loaded[addon] == true end
	end
	function W.win.loadMore(addon)
		local was = W.group
		W.group = "windows"
		MORE_LOADED[addon]()
		W.win.loaded[addon] = true
		W.group = was
		W.seal()
		W.fire("ADDON_LOADED", addon)
	end
	W.win.foldHeader, W.win.sliceHeader, W.win.auctionLine, W.win.scrollList = foldHeader, sliceHeader, auctionLine, scrollList

	-- Everything a client has at login. The Looking For Group addon is load-on-demand.
	local function buildAll()
		local was = W.group
		W.group = "windows"
		local builders = { CharacterFrame = buildCharacter, FriendsFrame = buildFriends, MerchantFrame = buildMerchant, MailFrame = buildMail,
			GossipFrame = buildGossip, QuestFrame = buildQuest }
		W.win.build = builders
		local only
		if wopts.only then
			only = {}
			for _, name in ipairs(wopts.only) do
				only[name] = true
			end
		end
		for _, name in ipairs({ "CharacterFrame", "FriendsFrame", "MerchantFrame", "MailFrame", "GossipFrame", "QuestFrame" }) do
			if not wmissing[name] and (not only or only[name]) then
				builders[name]()
			end
		end
		if wopts.extras then
			buildExtras(W.win.friends or env.UIParent)
		end
		if wopts.lfg == "loaded" then
			W.win.defineGroupFinderFunctions()
			buildGroupFinder()
			W.win.loaded.Blizzard_GroupFinder_VanillaStyle = true
		end
		if wopts.second then
			buildBags()
			buildMenus()
			if wopts.second ~= "demand" then
				for addon in pairs(SPELL_WINDOWS) do
					buildSpells(addon)
				end
			end
			env.C_AddOns = { IsAddOnLoaded = function(addon) return W.win.loaded[addon] == true end, GetAddOnMetadata = W.addOnMetadata }
			function env.StaticPopup_Show() end
		end
		if wopts.more then
			buildMore()
		end
		W.group = was
		W.seal()
	end
	-- The player loads the Looking For Group addon: its frames and global functions appear, then ADDON_LOADED.
	function W.loadGroupFinder()
		local was = W.group
		W.group = "windows"
		W.win.defineGroupFinderFunctions()
		if not wmissing.LFGParentFrame then
			buildGroupFinder()
		end
		W.win.loaded.Blizzard_GroupFinder_VanillaStyle = true
		W.group = was
		W.seal()
		W.fire("ADDON_LOADED", "Blizzard_GroupFinder_VanillaStyle")
	end
	-- Marks a frame, its regions and everything under it as protected.
	function W.win.protect(frame, on)
		local r = raw(frame)
		r.protected = on
		for _, region in ipairs(r.regions) do
			raw(region).protected = on
		end
		for _, state in pairs(r.states or {}) do
			raw(state).protected = on
		end
		for _, child in ipairs(r.children) do
			W.win.protect(child, on)
		end
	end
	if wopts then
		buildAll()
	end

	-- Cooldowns -------------------------------------------------------------------------------------------
	-- Built only for a world that asks for them: opts.cooldowns = true, or a table:
	--   viewers = true (all three) or a list of names: the cooldown manager's frames, each with an item pool of
	--     items built the way Blizzard_CooldownViewer's XML builds them (W.addViewerItem).
	--   noMethods = { Name = true }: methods that the Cooldown frames of this client lack.
	--   secretTimes = true: the start time, duration and rate of a spell cooldown, and the charges left, are withheld.
	-- Spells are added with W.addSpell and the skill lines of the spell book with W.addLine; opts.char is FlatUICharDB.
	-- The functions answer as SpellDocumentation.lua and SpellBookDocumentation.lua say: isActive, isOnGCD and
	-- isEnabled are never withheld, a duration object cannot be read, and a function can be made to fail with
	-- W.sp.fault[name] = "error" | "nothing" | "secret" | "string".
	W.cd, W.cdFrames, W.addonFonts, W.durations, W.cdGroups = nil, {}, {}, setmetatable({}, { __mode = "k" }), {}
	local copts = opts.cooldowns or (opts.trackers and true)
	if copts then
		if copts == true then
			copts = {}
		end
		W.cd = { opts = copts, noMethods = copts.noMethods or {}, fonts = { NumberFontNormalSmall = true, NumberFontNormal = true, NumberFontNormalLarge = true, NumberFontNormalHuge = true,
			NumberFontNormalSmallGray = true, GameFontHighlightSmall = true, GameFontNormalSmall = true } }
		local sp = { data = {}, order = {}, lines = {}, calls = {}, fault = {}, made = {}, secretTimes = copts.secretTimes or false, castTimes = {}, usable = {} }
		W.sp = sp
		local ITEM_TYPES = { None = 0, Spell = 1, FutureSpell = 2, PetAction = 3, Flyout = 4 }
		env.Enum = env.Enum or {}
		env.Enum.SpellBookSpellBank = { Player = 0, Pet = 1 }
		env.Enum.SpellBookItemType = ITEM_TYPES
		-- A spell by ID, or by name (the rank the character uses, whatever the capitals).
		local function lookup(id)
			if isnum(id) then
				return sp.data[id]
			elseif type(id) == "string" then
				local wanted, found = id:lower(), nil
				for _, spellID in ipairs(sp.order) do
					local s = sp.data[spellID]
					if s.name:lower() == wanted and (found == nil or (s.known and not s.lowRank)) then
						found = s
					end
				end
				return found
			end
			bad(W, "a spell identifier is expected")
		end
		local function api(name, fn)
			return function(...)
				sp.calls[name] = (sp.calls[name] or 0) + 1
				local fault = sp.fault[name]
				if fault == "error" then
					error(name .. " failed", 0)
				elseif fault == "nothing" then
					return
				elseif fault == "secret" then
					return SECRET
				elseif fault == "string" then
					return "x"
				end
				return fn(...)
			end
		end
		-- A duration object: opaque, the addon passes it on and reads nothing from it.
		local function newDuration(info)
			local object = setmetatable({}, {
				__index = function(_, key) bad(W, "the addon read " .. tostring(key) .. " of a duration object") end,
				__newindex = function(_, key) bad(W, "the addon wrote " .. tostring(key) .. " to a duration object") end,
			})
			W.durations[object] = info
			sp.made[#sp.made + 1] = object
			return object
		end
		env.C_Spell = {
			GetSpellName = api("GetSpellName", function(id)
				local s = lookup(id)
				return s and s.name
			end),
			GetSpellTexture = api("GetSpellTexture", function(id)
				local s = lookup(id)
				if s then
					return s.icon, s.icon
				end
			end),
			GetSpellSubtext = api("GetSpellSubtext", function(id)
				local s = lookup(id)
				return s and (s.subtext or "")
			end),
			GetSpellInfo = api("GetSpellInfo", function(id)
				local s = lookup(id)
				if s then
					return { name = s.name, iconID = s.icon, originalIconID = s.icon, castTime = sp.castTimes[s.id] or 0, minRange = 0, maxRange = 0, spellID = s.id }
				end
			end),
			GetSpellCooldown = api("GetSpellCooldown", function(id)
				local s = lookup(id)
				if not s then
					return
				end
				local c, times = s.cd, sp.secretTimes
				return { startTime = times and SECRET or c.start, duration = times and SECRET or c.duration, isEnabled = c.enabled, modRate = times and SECRET or 1,
					isActive = sp.secretActive and SECRET or c.active, isOnGCD = c.gcd }
			end),
			GetSpellCooldownDuration = api("GetSpellCooldownDuration", function(id, ignoreGCD)
				if ignoreGCD ~= nil and type(ignoreGCD) ~= "boolean" then
					bad(W, "GetSpellCooldownDuration: ignoreGCD is a boolean")
				end
				local s = lookup(id)
				if s then
					return newDuration({ kind = "cooldown", spell = s.id, ignoreGCD = ignoreGCD == true, zero = not s.cd.active or (ignoreGCD == true and s.cd.gcd) })
				end
			end),
			GetSpellCharges = api("GetSpellCharges", function(id)
				local s = lookup(id)
				if s and s.charges then
					local ch, times = s.charges, sp.secretTimes
					return { currentCharges = times and SECRET or ch.current, maxCharges = ch.max, cooldownStartTime = times and SECRET or 0,
						cooldownDuration = times and SECRET or 0, chargeModRate = times and SECRET or 1, isActive = ch.active }
				end
			end),
			GetSpellChargeDuration = api("GetSpellChargeDuration", function(id)
				local s = lookup(id)
				if s and s.charges then
					return newDuration({ kind = "charge", spell = s.id, zero = not s.charges.active })
				end
			end),
			GetSpellDisplayCount = api("GetSpellDisplayCount", function(id)
				local s = lookup(id)
				if sp.secretCount then
					return SECRET
				end
				return s and s.charges and tostring(s.charges.current) or ""
			end),
		}
		-- The Player bank only; the slots of the skill lines run one after the other.
		local function slotOf(slot, bank)
			if not (isnum(slot) and slot >= 1 and slot == math.floor(slot)) or not isnum(bank) then
				bad(W, "a spell book slot index and a bank are expected")
			end
			if bank ~= 0 then
				return
			end
			local offset = 0
			for index, line in ipairs(sp.lines) do
				if slot <= offset + #line.slots then
					return sp.data[line.slots[slot - offset]], index
				end
				offset = offset + #line.slots
			end
		end
		env.C_SpellBook = {
			GetNumSpellBookSkillLines = api("GetNumSpellBookSkillLines", function() return #sp.lines end),
			GetSpellBookSkillLineInfo = api("GetSpellBookSkillLineInfo", function(index)
				argn(W, "GetSpellBookSkillLineInfo", index)
				local line = sp.lines[index]
				if line then
					local offset = 0
					for i = 1, index - 1 do
						offset = offset + #sp.lines[i].slots
					end
					return { name = line.name, iconID = 1, itemIndexOffset = offset, numSpellBookItems = #line.slots, isGuild = false,
						shouldHide = line.shouldHide == true, specID = line.specID, offSpecID = line.offSpecID }
				end
			end),
			GetSpellBookItemInfo = api("GetSpellBookItemInfo", function(slot, bank)
				local s, index = slotOf(slot, bank)
				if s then
					return { actionID = s.id, spellID = s.override or s.id, itemType = s.itemType, name = s.bookName or s.name, subName = s.subtext or "", iconID = s.icon, isPassive = s.passive == true,
						isOffSpec = s.offSpec == true, skillLineIndex = index }
				end
			end),
			IsSpellBookItemLowRank = api("IsSpellBookItemLowRank", function(slot, bank)
				local s = slotOf(slot, bank)
				return s ~= nil and s.lowRank == true
			end),
			IsSpellKnownOrInSpellBook = api("IsSpellKnownOrInSpellBook", function(id)
				local s = lookup(id)
				return s ~= nil and (s.known == true or s.line ~= nil)
			end),
			IsSpellKnown = api("IsSpellKnown", function(id)
				local s = lookup(id)
				return s ~= nil and s.known == true
			end),
		}
		-- Not in Blizzard's documentation; the client lists it. Milliseconds, then the global cooldown.
		env.GetSpellBaseCooldown = api("GetSpellBaseCooldown", function(id)
			local s = lookup(id)
			if s and s.base ~= nil then
				return s.base, 1500
			end
		end)
		function W.addLine(more)
			more = more or {}
			sp.lines[#sp.lines + 1] = { name = more.name or ("Line " .. (#sp.lines + 1)), shouldHide = more.shouldHide, offSpecID = more.offSpecID, specID = more.specID, slots = {} }
			return #sp.lines
		end
		-- more: name, subtext (the rank the game shows beside the name), bookName (the name the spell book gives, when it differs), override (the ID of the spell that overrides it), icon, base (milliseconds), line (a skill line; known spells go in the first), known, passive, offSpec,
		-- lowRank, itemType ("Spell", "FutureSpell", ...), charges (most).
		function W.addSpell(id, more)
			more = more or {}
			local s = { id = id, name = more.name or ("Spell " .. id), icon = more.icon or (100000 + id), base = more.base, passive = more.passive, offSpec = more.offSpec,
				lowRank = more.lowRank, bookName = more.bookName, subtext = more.subtext, override = more.override, known = more.known ~= false, itemType = ITEM_TYPES[more.itemType or "Spell"], cd = { active = false, gcd = false, enabled = true, start = 0, duration = 0 } }
			if more.charges then
				s.charges = { max = more.charges, current = more.charges, active = false }
			end
			sp.data[id] = s
			sp.order[#sp.order + 1] = id
			local line = more.line
			if line == nil and s.known then
				line = 1
			end
			if line then
				while #sp.lines < line do
					W.addLine()
				end
				local slots = sp.lines[line].slots
				slots[#slots + 1] = id
				s.line = line
			end
			return s
		end
		-- "cooling", "gcd" (the global cooldown only) or "ready".
		function W.setCooldown(id, state)
			local c = sp.data[id].cd
			c.active, c.gcd = state ~= "ready", state == "gcd"
			c.start = state == "ready" and 0 or 100
			c.duration = state == "ready" and 0 or (state == "gcd" and 1.5 or 30)
		end
		function W.setCharges(id, current, recharging)
			local ch = sp.data[id].charges
			ch.current, ch.active = current, recharging == true
		end
		-- The sweep of a spell runs out: the spell is ready and the client runs OnCooldownDone on the frame that showed it.
		function W.finishCooldown(id)
			W.setCooldown(id, "ready")
			for _, frame in ipairs(W.cdFrames) do
				local sweep = frame.cd.sweep
				if sweep and sweep.info and sweep.info.spell == id then
					frame.cd.sweep, frame.shown = nil, false
					local script = frame.scripts and frame.scripts.OnCooldownDone
					if script then
						script(frame)
					end
				end
			end
		end
		-- A frame is drawn: the OnUpdate script of every visible frame of the addon's runs.
		function W.frameUpdate(seconds)
			local function visible(f)
				while f do
					if not f.shown then
						return false
					end
					f = f.parent and W.rawOf[f.parent]
				end
				return true
			end
			for _, frame in ipairs(W.addonFrames) do
				local script = frame.scripts and frame.scripts.OnUpdate
				if script and visible(frame) then
					script(frame, seconds)
				end
			end
		end

		-- The cooldown manager: three viewers, each with a pool of items. Items are built as CooldownViewer.xml builds them:
		-- Icon (masked), an unnamed overlay, OutOfRange (Essential and Utility), and a Cooldown that fills the item.
		if copts.viewers then
			W.cdm = { viewers = {}, items = {} }
			local ROUND = "Interface\\HUD\\UI-HUD-CoolDownManager-Icon-Swipe"
			local shapes = { EssentialCooldownViewer = { range = true, x = 9, y = 8 }, UtilityCooldownViewer = { range = true, x = 6, y = 5 }, BuffIconCooldownViewer = { range = false, x = 8, y = 7 } }
			local names = copts.viewers == true and { "EssentialCooldownViewer", "UtilityCooldownViewer", "BuffIconCooldownViewer" } or copts.viewers
			local was = W.group
			W.group = "cdm"
			for _, name in ipairs(names) do
				local pool, poolRaw = newPool(W)
				local viewer, viewerRaw = B(nil, { itemFramePool = pool }, { forbidden = forbidden[name], name = name })
				W.cdm.viewers[name] = { viewer = viewer, raw = viewerRaw, pool = pool, poolRaw = poolRaw, inactive = {} }
				if not missing[name] then
					env[name] = viewer
				end
			end
			W.group = was
			local function points(raw, rec)
				local out = {}
				for _, p in ipairs(raw.points) do
					out[#out + 1] = p[1] .. ">" .. (p[2] == rec.item and "item" or (p[2] == rec.icon and "icon" or "?")) .. ":" .. p[3] .. "," .. (p[4] == 0 and "0" or g(p[4])) .. "," .. (p[5] == 0 and "0" or g(p[5]))
				end
				return table.concat(out, ";")
			end
			-- Everything the restyle changes on an item, as one line.
			function W.cdm.look(rec)
				local tc = rec.iconRaw.texCoord and table.concat(rec.iconRaw.texCoord, ",") or "-"
				return table.concat({ "icon " .. points(rec.iconRaw, rec), "tc " .. (tc == "0,1,0,1" and "-" or tc),
					"masks " .. #rec.iconRaw.maskList .. (rec.iconRaw.masks[rec.mask] and "+" or "-"), "overlay " .. g(rec.overlayRaw.alpha),
					"sweep " .. tostring(rec.cdRaw.cd.swipeFile), "cooldown " .. points(rec.cdRaw, rec), "range " .. (rec.rangeRaw and points(rec.rangeRaw, rec) or "-") }, " | ")
			end
			-- more: forbidden (the item), cooldownForbidden, noIcon, iconSecret, noMask, maskNotListed (the icon has the mask but the item does not list it),
			-- noOverlay, noRange, noCooldown, maskFault,
			-- inactive (the pool holds it but has not handed it out), regionsError.
			function W.addViewerItem(viewerName, more)
				more = more or {}
				local v, shape = W.cdm.viewers[viewerName], shapes[viewerName]
				local before = W.group
				W.group = "cdm"
				local icon, iconRaw = Rr(nil, nil, { maskFault = more.maskFault })
				local mask = R(nil, ATLAS.mask, { kind = "MaskTexture" })
				local overlay, overlayRaw = Rr(nil, ATLAS.overlay)
				local range, rangeRaw
				if shape.range and not more.noRange then
					range, rangeRaw = Rr(nil, "UI-CooldownManager-OORshadow")
				end
				local cooldown, cdRaw = B(nil, {}, { objectType = "Cooldown", cd = true, forbidden = more.cooldownForbidden })
				cdRaw.cd.swipeFile = ROUND
				local item, inner = B(nil, { Icon = not more.noIcon and (more.iconSecret and SECRET or icon) or nil, OutOfRange = range,
					Cooldown = not more.noCooldown and cooldown or nil }, { forbidden = more.forbidden, regionsError = more.regionsError })
				inner.regions = { icon, not (more.noMask or more.maskNotListed) and mask or nil, not more.noOverlay and overlay or nil, range }
				inner.children = { cooldown }
				for _, part in ipairs({ iconRaw, cdRaw, rangeRaw or iconRaw }) do
					part.points = { { "TOPLEFT", item, "TOPLEFT", 0, 0 }, { "BOTTOMRIGHT", item, "BOTTOMRIGHT", 0, 0 } }
				end
				overlayRaw.points = { { "TOPLEFT", item, "TOPLEFT", -shape.x, shape.y }, { "BOTTOMRIGHT", item, "BOTTOMRIGHT", shape.x, -shape.y } }
				if not more.noMask then
					iconRaw.masks[mask] = true
					iconRaw.maskList[1] = mask
				end
				local list = more.inactive and v.inactive or v.poolRaw.items
				list[#list + 1] = item
				local rec = { item = item, inner = inner, icon = icon, iconRaw = iconRaw, mask = mask, overlay = overlay, overlayRaw = overlayRaw, range = range,
					rangeRaw = rangeRaw, cooldown = cooldown, cdRaw = cdRaw, viewer = viewerName }
				rec.pristine = W.cdm.look(rec)
				W.cdm.items[#W.cdm.items + 1] = rec
				W.group = before
				return rec
			end
			-- The game hands an item back to its pool, or takes it out again.
			function W.cdm.release(rec)
				local v = W.cdm.viewers[rec.viewer]
				for i, item in ipairs(v.poolRaw.items) do
					if item == rec.item then
						table.remove(v.poolRaw.items, i)
						v.inactive[#v.inactive + 1] = item
						return
					end
				end
			end
			function W.cdm.acquire(rec)
				local v = W.cdm.viewers[rec.viewer]
				for i, item in ipairs(v.inactive) do
					if item == rec.item then
						table.remove(v.inactive, i)
						v.poolRaw.items[#v.poolRaw.items + 1] = item
						return
					end
				end
			end
		end
	end


	-- Trackers ---------------------------------------------------------------------------------------------
	-- Built only for a world that asks for them: opts.trackers = true, or a table:
	--   noUnitEvent: frames have no RegisterUnitEvent. noAnimation: textures can make no animation group. noAuraContainer: the client has no
	--   aura container. noAlphaFromBoolean: regions have no SetAlphaFromBoolean.
	-- A world with trackers has the cooldown client as well, for the spell functions. Added to it, as the documentation says
	-- (UnitAuraDocumentation.lua, SecretPredicateAPIDocumentation.lua, TotemDocumentation.lua, ItemDocumentation.lua,
	-- DurationUtilDocumentation.lua, SoundDocumentation.lua):
	--   C_UnitAuras: GetPlayerAuraBySpellID and GetAuraDataBySpellName give nothing, and no error, while W.au.hidden is true and the
	--     spell is not flagged never hidden; the fields of an aura are withheld when W.au.secretFields is true (or lists them);
	--     AddAuraSound and RemoveAuraSound keep W.au.sounds.
	--   C_Secrets: ShouldAurasBeSecret answers W.au.hidden, ShouldSpellAuraBeSecret answers it for a spell that W.au.secrecy[id]
	--     does not flag NeverSecret (1 is AlwaysSecret), ShouldTotemSlotBeSecret answers W.au.totemHidden[slot], ShouldCooldownsBeSecret
	--     answers W.au.cooldownsHidden and ShouldUnitSpellCastBeSecret answers W.au.castHidden[unit].
	--   W.au.enchants[slot] lists { timeLeft (milliseconds), type (Enum.ItemEnchantType; 3 when left out is a stand-in with no client source behind it), has, charges, id, icon } for
	--   GetWeaponEnchantInfo; W.au.single makes the answer one table, W.au.offhand is OffhandHasWeapon and W.au.itemIcons[slot] is GetInventoryItemTexture.
	--   PlaySound, GetTotemInfo, GetTotemDuration, C_Item.GetWeaponEnchantInfo, UnitExists, UnitIsDeadOrGhost, GetTime, and
	--   C_DurationUtil.CreateDuration, whose objects a StatusBar and a Cooldown take.
	-- W.au.fault[name] = "error" | "nothing" | "secret" | "string" | "false" spoils a call, as W.sp.fault[name] spoils a spell call.
	-- W.giveBuff, W.takeBuff, W.unitEvent, W.auraChanged, W.cast, W.restriction, W.beginFight and W.endFight are the player's side.
	W.au = nil
	if opts.trackers then
		local topts = opts.trackers == true and {} or opts.trackers
		local au = { opts = topts, auras = {}, calls = {}, idCalls = {}, fault = {}, hidden = false, secrecy = {}, sounds = {}, soundCount = 0, played = {},
			groups = {}, totems = {}, totemHidden = {}, bindings = {}, castHidden = {}, enchants = {}, itemIcons = {}, offhand = false, pet = false, dead = false, secretFields = false }
		W.au = au
		env.GetTime = function() return W.now end
		env.Enum.AddOnRestrictionType = { Combat = 0, Encounter = 1, ChallengeMode = 2, PvPMatch = 3, Map = 4, Chat = 5 }
		env.Enum.AddOnRestrictionState = { Inactive = 0, Activating = 1, Active = 2 }
		env.Enum.SecrecyLevel = { NeverSecret = 0, AlwaysSecret = 1, ContextuallySecret = 2 }
		env.Enum.UnitAuraSoundTrigger = { Added = 0, ApplicationsIncreased = 1, Removed = 2 }
		env.Enum.WeaponSlot = { MainHand = 0, OffHand = 1, Ranged = 2 }
		local function api(name, fn)
			return function(...)
				au.calls[name] = (au.calls[name] or 0) + 1
				local fault = au.fault[name]
				if fault == "error" then
					error(name .. " failed", 0)
				elseif fault == "nothing" then
					return
				elseif fault == "secret" then
					return SECRET
				elseif fault == "string" then
					return "x"
				elseif fault == "false" then
					return false
				end
				return fn(...)
			end
		end
		local function number(name, v)
			if not isnum(v) then
				bad(W, name .. ": a number is expected")
			end
		end
		-- A duration object that a bar or a cooldown takes: opaque, but for the call that sets its time.
		local function duration(info)
			local object = setmetatable({}, {
				__index = function(_, key)
					if key == "SetTimeFromEnd" then
						return function(_, endTime, length)
							if au.fault.SetTimeFromEnd == "error" then
								error("SetTimeFromEnd failed", 0)
							end
							argn(W, "SetTimeFromEnd", endTime, length)
							info.endTime, info.length = endTime, length
						end
					end
					bad(W, "the addon read " .. tostring(key) .. " of a duration object")
				end,
				__newindex = function(_, key) bad(W, "the addon wrote " .. tostring(key) .. " to a duration object") end,
			})
			W.durations[object] = info
			return object
		end
		local function secrecy(id)
			return au.secrecy[id] or 2
		end
		local function out(key, value)
			if au.secretFields == true or (type(au.secretFields) == "table" and au.secretFields[key]) then
				return SECRET
			end
			return value
		end
		local function auraTable(id)
			local a = au.auras[id]
			if not a then
				return nil
			end
			return { spellId = out("spellId", id), name = out("name", a.name), icon = out("icon", a.icon), applications = out("applications", a.applications or 0),
				charges = out("charges", a.charges or 0), duration = out("duration", a.duration or 0), expirationTime = out("expirationTime", a.expires or 0) }
		end
		local function hiddenFor(id)
			return au.hidden and secrecy(id) ~= 0
		end
		local otherTable
		env.C_UnitAuras = {
			GetPlayerAuraBySpellID = api("GetPlayerAuraBySpellID", function(id)
				number("GetPlayerAuraBySpellID", id)
				au.idCalls[id] = (au.idCalls[id] or 0) + 1
				if hiddenFor(id) then
					return
				end
				return auraTable(id)
			end),
			GetAuraDataBySpellName = api("GetAuraDataBySpellName", function(unit, name, filter)
				if type(unit) ~= "string" or type(name) ~= "string" or (filter ~= nil and type(filter) ~= "string") then
					bad(W, "GetAuraDataBySpellName: a unit, a name and a filter are expected")
				end
				au.nameAsked = { unit = unit, name = name, filter = filter }
				-- Another unit: the first aura of W.au.unitAuras[unit] with the name that the filter takes, nothing while the game hides auras.
				if unit ~= "player" then
					if au.hidden then
						return
					end
					local ids = {}
					for id in pairs(au.unitAuras[unit] or {}) do
						ids[#ids + 1] = id
					end
					table.sort(ids)
					for _, id in ipairs(ids) do
						local a = au.unitAuras[unit][id]
						local takes = (a.name or ("Spell " .. id)) == name
						if filter and filter:find("HARMFUL", 1, true) and a.harmful ~= true then
							takes = false
						elseif filter and filter:find("HELPFUL", 1, true) and a.harmful == true then
							takes = false
						end
						if filter and filter:find("PLAYER", 1, true) and a.mine ~= true then
							takes = false
						end
						if takes then
							return otherTable(id, a)
						end
					end
					return
				end
				local ids = {}
				for id in pairs(au.auras) do
					ids[#ids + 1] = id
				end
				table.sort(ids)
				for _, id in ipairs(ids) do
					if au.auras[id].name == name and not hiddenFor(id) then
						return auraTable(id)
					end
				end
			end),
			AddAuraSound = api("AddAuraSound", function(trigger, info)
				if trigger ~= env.Enum.UnitAuraSoundTrigger.Removed and trigger ~= env.Enum.UnitAuraSoundTrigger.Added and trigger ~= env.Enum.UnitAuraSoundTrigger.ApplicationsIncreased then
					bad(W, "AddAuraSound: a trigger is expected")
				end
				if type(info) ~= "table" or type(info.unitToken) ~= "string" or not isnum(info.spellID) or not (isnum(info.soundFileID) or type(info.soundFileName) == "string")
					or (info.outputChannel ~= nil and type(info.outputChannel) ~= "string") or (info.throttleSeconds ~= nil and not isnum(info.throttleSeconds)) then
					bad(W, "AddAuraSound: a UnitAuraSoundInfo is expected")
				end
				if info.throttleSeconds ~= nil and (info.throttleSeconds < 0 or info.throttleSeconds > 5) then
					return nil
