		-- The buffs of another unit: W.au.unitAuras[token][id] = { name, icon, duration, expires, source }.
		otherTable = function(id, a)
			return { spellId = id, name = a.name or ("Spell " .. id), icon = a.icon or 134400, applications = a.applications or 0, duration = a.duration or 0,
				expirationTime = a.expires or 0, sourceUnit = a.source, isHelpful = a.harmful ~= true, isHarmful = a.harmful == true }
		end
		-- A filter of HARMFUL keeps the auras with harmful = true, HELPFUL the others, PLAYER the ones with mine = true.
		local function filtered(list, filter)
			local keep = {}
			for _, t in ipairs(list) do
				local a = t.record
				local ok = true
				if filter and filter:find("HARMFUL", 1, true) and a.harmful ~= true then
					ok = false
				elseif filter and filter:find("HELPFUL", 1, true) and a.harmful == true then
					ok = false
				end
				if filter and filter:find("PLAYER", 1, true) and a.mine ~= true then
					ok = false
				end
				if ok then
					t.record = nil
					keep[#keep + 1] = t
				end
			end
			return keep
		end
		function au.listOf(unit, filter)
			local list, ids = {}, {}
			if unit == "player" then
				for id in pairs(au.auras) do
					ids[#ids + 1] = id
				end
				table.sort(ids)
				for _, id in ipairs(ids) do
					local t = auraTable(id)
					t.sourceUnit = au.auras[id].source or (au.auras[id].fromPlayer and "player" or nil)
					list[#list + 1] = t
				end
			else
				for id in pairs(au.unitAuras[unit] or {}) do
					ids[#ids + 1] = id
				end
				table.sort(ids)
				for _, id in ipairs(ids) do
					local t = otherTable(id, au.unitAuras[unit][id])
					t.record = au.unitAuras[unit][id]
					list[#list + 1] = t
				end
				list = filtered(list, filter)
			end
			return list
		end
