			end),
			IsAddonMessagePrefixRegistered = api("IsAddonMessagePrefixRegistered", function(prefix)
				return au.chat.prefixes[prefix] == true
			end),
			SendAddonMessage = api("SendAddonMessage", function(prefix, message, chatType, target)
				if type(prefix) ~= "string" or type(message) ~= "string" or (chatType ~= nil and type(chatType) ~= "string") or (target ~= nil and type(target) ~= "string") then
					bad(W, "SendAddonMessage: strings are expected")
