local RELOAD = "Turning this off takes full effect after /reload."
local function S(path, kind, default, label, tip, more)
	local row = { path = path, kind = kind, default = default, label = label, tip = tip }
	for k, v in pairs(more or {}) do
		row[k] = v
	end
	return row
end
