	{ key = "combattext", label = "Combat text", rows = {
		S("combattext.enabled", "bool", true, "Place combat numbers"),
		S("combattext.source", "choice", "front", "Numbers over enemies", "As the game has them shows only your and your pet's hits, behind the nameplate.",
			{ choices = { { "front", "In front of nameplates" }, { "game", "As the game has them" } } }),
		"Scroll areas",
		S("combattext.where", "choice", "both", "Where your hits show", "Scroll area shows hits on your target only. Both shows the numbers over each enemy and scrolls the hits on every enemy with a nameplate.",
			{ choices = { { "scroll", "Scroll area" }, { "over", "Over enemies" }, { "both", "Both" } } }),
		S("combattext.outStyle", "choice", "arc", "Outgoing style", nil,
