		S("combattext.arcWidth", "choice", "wide", "Arc width", "How far an arc number curves out to the side.", { choices = { { "narrow", "Narrow" }, { "wide", "Wide" } } }),
		S("combattext.icons", "choice", "all", "Spell icons", "Shows the icon of your spell, swing or shot. Damage on you shows none.",
			{ needs = "combattext.whose", needsIn = { "one" }, choices = { { "all", "All" }, { "spells", "Spells only" }, { "off", "Off" } } }),
		S("combattext.speed", "choice", "normal", "Speed", "How long a number stays in the scroll areas.", { choices = { { "fast", "Fast" }, { "normal", "Normal" }, { "slow", "Slow" } } }),
		"Look",
		S("combattext.style", "choice", "flat", "Style", "Classic is the game's old floating text: straight up at a steady speed.", { choices = { { "flat", "Flat UI" }, { "classic", "Classic" } } }),
		S("combattext.font", "choice", "friz", "Font", "For numbers in front of nameplates, the Outgoing scroll area and your own text.",
			{ choices = { { "friz", "Friz Quadrata (the game's damage font)" }, { "arial", "Arial Narrow" }, { "skurri", "Skurri" }, { "morpheus", "Morpheus" } } }),
		S("combattext.outline", "choice", "none", "Outline", nil, { choices = { { "thick", "Thick" }, { "thin", "Thin" }, { "none", "None" } } }),
		S("combattext.shadow", "bool", false, "Shadow"),
		S("combattext.pop", "choice", "pop", "How a number appears", "Also the pop of the scroll areas. Classic keeps its own look over enemies.", { choices = { { "pop", "With a pop, larger for critical hits" }, { "plain", "Plainly" } } }),
		S("combattext.partial", "choice", "word", "Partial effects", "Glancing, Crushing, Block, Resist and Absorb.",
			{ choices = { { "word", "Word after the number" }, { "smaller", "Smaller number only" }, { "off", "Off" } } }),
		S("combattext.missWords", "choice", "paren", "Miss words", "Miss, Dodge, Parry, Immune and the other words.", { choices = { { "paren", "In parentheses" }, { "bare", "Bare word" } } }),
		"Position and size",
		S("combattext.height", "number", 60, "Height above the enemy", "With As the game has them, 40 is the game's own height. Also the height over friendly nameplates.", { min = 0, max = 100, step = 5, unit = "" }),
		S("combattext.crit", "choice", "same", "Critical hits", nil, { choices = { { "same", "Same height" }, { "higher", "Higher" } } }),
		S("combattext.size", "number", 140, "Size", "100% is the game's own size.", { min = 40, max = 400, step = 10, unit = "%" }),
