		S("combattext.movement", "choice", "burst", "Movement", "With a pop, Burst starts a critical hit over an enemy large. Every other number rises and falls.", { needs = "combattext.style", needsIn = { "flat" }, choices = { { "fall", "Rise and fall" }, { "up", "Straight up" }, { "burst", "Burst" } } }),
		S("combattext.overlap", "choice", "apart", "Overlapping numbers", "Keep apart starts a number in a free lane, or higher up.", { needs = "combattext.style", needsIn = { "flat" }, choices = { { "apart", "Keep apart" }, { "turn", "Stay in turn" } } }),
