		S("combattext.school", "bool", false, "Colour by school of magic", "Off shows hits of your spells in yellow, and swings and shots in white. Special attacks are yellow unless Physical ability hits is White. On colours each hit by its school."),
		S("combattext.abilityColour", "choice", "spell", "Physical ability hits", "Maul, Heroic Strike and other special attacks: Yellow shows them as spells and White as swings.",
			{ needs = "combattext.whose", needsIn = { "one" }, choices = { { "spell", "Yellow" }, { "white", "White" } } }),
		S("combattext.abilityName", "choice", "off", "Next melee ability names", "Shows the name of Maul, Heroic Strike, Cleave or Raptor Strike after its number.",
			{ needs = "combattext.whose", needsIn = { "one" }, choices = { { "off", "Off" }, { "after", "After the number" } } }),
		"Friendly units",
