		S("combattext.friendUnits", "choice", "all", "Friendly units", nil, { needs = "combattext.friend", needsIn = { "frames", "plates", "both" }, choices = { { "all", "Every friendly unit" }, { "target", "Target only" } } }),
		S("combattext.friendDamage", "bool", true, "Damage friendly units take", nil, { needs = "combattext.friend", needsIn = { "frames", "plates", "both" } }),
