			-- A world with One hit for each of yours: attack speeds main and off (W.attack, "secret" withholds them) and the ranged speed (W.ranged).
			function T.world(options, group)
				local o = { ["combattext.whose"] = "one", ["combattext.group"] = group }
				for key, value in pairs(options or {}) do
					o[key] = value
				end
				local W = mineWorld(nil, o)
				W.attack, W.ranged = { T.SPEED, nil }, T.RANGED
				W.env.UnitAttackSpeed = function(unit)
					if unit ~= "player" then
						error("UnitAttackSpeed: the player is asked for", 0)
					end
					if W.attack == "secret" then
						return SECRET, SECRET
					end
					return W.attack[1], W.attack[2]
				end
				W.env.UnitExists = function(unit)
					return unit == "player" or (unit == "pet" and W.pet == true)
				end
				W.env.UnitRangedDamage = function(unit)
					if unit ~= "player" then
						error("UnitRangedDamage: the player is asked for", 0)
					end
					if W.ranged == "secret" then
						return SECRET, SECRET, SECRET
					end
					return W.ranged, 1, 2
				end
				return W
			end
