			T.N4.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			T.n = T.at(T.N4, { 100.5 }, nil, "CRITICAL", 8)
			check("ctown: a critical hit takes the cast slot and not the aura slot", T.n == "412" and has(T.N4.slash("combat"), "Last hit: yours (cast slot)."), T.N4.slash("combat"):match("Last hit[^%c]*"))
			T.N5 = T.world()
			T.N5.fire("PLAYER_ENTER_COMBAT")
			T.N5.fire("START_AUTOREPEAT_SPELL")
			T.n = T.at(T.N5, { 100.0 }, nil, nil, 1)
			check("ctown: during a shot a physical hit takes the shot slot and not a swing slot", T.n == "412" and has(T.N5.slash("combat"), "Last hit: yours (shot slot)."), T.N5.slash("combat"):match("Last hit[^%c]*"))
			T.N6 = T.world()
			T.N6.attack = "secret"
			T.N6.fire("PLAYER_ENTER_COMBAT")
			T.n = T.at(T.N6, { 100.0, 100.5 }, nil, nil, 1)
			check("ctown: a hit with both hands busy is left out as taken, and a withheld speed is counted once for each hit", T.n == "412,none" and has(T.N6.slash("combat"), "Last hit: left out (slot taken).")
				and has(T.N6.slash("combat"), "tell about: 2."), T.N6.slash("combat"):match("Last hit[^%c]*") .. " " .. T.N6.slash("combat"):match("tell about: %d+"))

			-- The extra attack slot: opens for 0.4 seconds after a hand slot is taken and takes one physical hit. Closed with a pet out, in a group,
			-- with a withheld answer about the pet and with Extra attacks Off.
			T.X = T.world()
			T.X.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X, { 100.0, 100.2, 100.3 })
			T.xf = nil
			T.X2 = T.world()
			T.X2.fire("PLAYER_ENTER_COMBAT")
			T.X2.now = 100.0
			say(T.X2)
			T.X2.now = 100.2
			T.xf = C.hit(T.X2, "nameplate1", "WOUND", "", 412, 1)
			check("extra: one swing at 100.0 gives its slot and one extra hit at 100.2, and a third hit is left out", T.x == "412,412 (Extra attack),none", T.x)
			check("extra: the extra hit is white and the last decision names the extra slot", C.colour(T.xf):match("^1,1,1") ~= nil and has(T.X2.slash("combat"), "Last hit: yours (extra slot)."), C.colour(T.xf))
			T.X3 = T.world()
			T.X3.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X3, { 100.0, 100.5, 101.7, 101.8, 101.9 })
			check("extra: the slot is closed after 0.4 seconds, a new swing slot opens it again, and it takes one hit", T.x == "412,none,412,412 (Extra attack),none", T.x)
			T.X4 = T.world()
			T.X4.attack = { 2.0, 1.5 }
			T.X4.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X4, { 100.0, 100.1, 100.2, 100.3 })
			check("extra: with two weapons the main hand, the off hand and then the extra slot take the hits in that order", T.x == "412,412,412 (Extra attack),none", T.x)
			T.X5 = T.world()
			T.X5.pet = true
			T.X5.fire("PLAYER_ENTER_COMBAT")
			check("extra: with a pet out the slot is closed", T.at(T.X5, { 100.0, 100.2 }) == "412,none")
			T.X6 = T.world(nil, "flat")
			T.X6.grouped = true
			T.X6.fire("PLAYER_ENTER_COMBAT")
			check("extra: in a group the slot is closed", T.at(T.X6, { 100.0, 100.2 }) == "412,none")
			T.X7 = T.world({ ["combattext.extra"] = "off" })
			T.X7.fire("PLAYER_ENTER_COMBAT")
			check("extra: Extra attacks Off closes the slot", T.at(T.X7, { 100.0, 100.2 }) == "412,none")
			T.X8 = T.world()
			T.X8.env.UnitExists = function() return SECRET end
			T.X8.fire("PLAYER_ENTER_COMBAT")
			check("extra: an answer about the pet that the game withholds closes the slot", T.at(T.X8, { 100.0, 100.2 }) == "412,none")
			T.X9 = T.world({ ["combattext.whose"] = "mine" })
			T.X9.fire("PLAYER_ENTER_COMBAT")
			check("extra: Every hit while you attack has no extra slot and labels nothing", T.at(T.X9, { 100.0, 100.2 }) == "412,412")
			T.X10 = T.world()
			T.X10.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X10, { 100.0, 100.2 }, nil, nil, 4)
			check("extra: a hit of a school of magic does not take the extra slot", T.x == "none,none", T.x)
			-- An instant strike that succeeded takes the cast slot, so a hit after it is not an extra attack.
			T.X11 = T.world()
			T.X11.fire("PLAYER_ENTER_COMBAT")
			T.X11.now = 100.0
			say(T.X11)
			T.X11.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			T.x = T.at(T.X11, { 100.2 })
			check("extra: a strike that succeeded after a swing takes the cast slot and is not labelled", T.x == "412" and has(T.X11.slash("combat"), "Last hit: yours (cast slot)."), T.x)
			-- A dodge in the extra slot shows the miss word alone.
			T.X12 = T.world()
			T.X12.fire("PLAYER_ENTER_COMBAT")
			T.X12.now = 100.0
			say(T.X12)
			T.X12.now = 100.2
			T.xf = C.hit(T.X12, "nameplate1", "DODGE", "", 0, 1)
			check("extra: a dodge in the extra slot shows the miss word alone and not in orange", T.xf ~= nil and not has(T.xf.text, "Extra") and has(string.lower(T.xf.text), "dodge") and C.colour(T.xf):match("^1,0%.6,0%.15") == nil and has(T.X12.slash("combat"), "Last hit: yours (extra slot)."), T.xf and (T.xf.text .. " " .. C.colour(T.xf)))
			-- A bleed tick of yours (an aura on the enemy) just after a swing is not an extra attack.
			T.X13 = T.world()
			T.X13.auras.nameplate1 = 1
			T.X13.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X13, { 100.0, 100.2 })
			check("extra: with an aura of yours on the enemy a hit after a swing is not labelled", T.x == "412,412", T.x)
			-- An aura list the game withholds or fails to give is not "no aura": the slot stays closed.
			T.X15, T.X16 = T.world(), T.world()
			T.X15.auras.nameplate1, T.X16.auras.nameplate1 = "error", "secret"
			T.X15.fire("PLAYER_ENTER_COMBAT")
			T.X16.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X15, { 100.0, 100.2 }) .. "," .. T.at(T.X16, { 100.0, 100.2 })
			check("extra: an aura list that errors or is withheld gives 412,none and no extra slot", T.x == "412,none,412,none" and T.x:find("Extra", 1, true) == nil, T.x)
			-- The off hand opens its own slot: weapons 2.0 and 1.5, hits at 100.0, 101.0 and 101.2.
			T.X14 = T.world()
			T.X14.attack = { 2.0, 1.5 }
			T.X14.fire("PLAYER_ENTER_COMBAT")
			T.x = T.at(T.X14, { 100.0, 101.0, 101.2 })
			check("extra: an off hand swing opens its own extra slot", T.x == "412,412,412 (Extra attack)", T.x)
			check("extra: Extra attacks starts as Extra attack", T.X.ns.Get("combattext.extra") == "plain")

			-- The MSBT look: arcs on both sides, the icon of the spell, words in parentheses, the colour of a hit of yours and the next melee ability
			-- (Maul). The values are in one table.
			do
				local M = { ICONS = { [6603] = 132, [75] = 133, [2480] = 139, [5019] = 134, [6807] = 135, [8921] = 136, [8936] = 137, [78] = 138 },
					NAMES = { [6807] = "Maul", [6808] = "Maul", [78] = "Heroic Strike", [285] = "Heroic Strike", [845] = "Cleave", [2973] = "Raptor Strike", [5221] = "Shred",
						[8921] = "Moonfire", [8936] = "Regrowth", [5019] = "Shoot" } }
				-- A world with the Outgoing area (Scroll area), One hit for each of yours, and the spell calls of the game.
				function M.world(options)
					local o = { ["combattext.where"] = "scroll" }
					for key, value in pairs(options or {}) do
						o[key] = value
					end
					local W = T.world(o)
					W.helpful = { [8936] = true }
					W.env.UnitClassBase = function() return W.class or "HUNTER" end
					W.env.C_Spell = {
						GetSpellName = function(id) return M.NAMES[id] end,
						GetSpellTexture = function(id)
							if W.textureFault == "secret" then
								return SECRET
							end
							return M.ICONS[id]
						end,
						IsSpellHelpful = function(id) return W.helpful[id] == true end,
					}
					return W
				end
				-- A hit report for the target at a time: the font that shows it, or nil when nothing shows.
				function M.hit(W, time, flag, amount, school, event)
					W.now = time
					return C.hit(W, "target", event or "WOUND", flag or "", amount or 312, school or 1)
				end
				-- The icon texture of a number, or nil.
				function M.icon(W, font)
					for _, t in ipairs(W.addonTextures) do
						if t.points[1] and t.points[1][2] == font and t.points[1][1] == "RIGHT" then
							return t
						end
					end
				end
				-- The file the icon of a number shows, or "none".
				function M.file(W, font)
					local icon = font and M.icon(W, font)
					return icon and icon.shown and icon.file or "none"
				end
				function M.cast(W, id, unit)
					W.fire("UNIT_SPELLCAST_SUCCEEDED", unit or "player", "guid", id)
				end
				-- The last decision of /flatui combat.
				function M.last(W)
					return W.slash("combat"):match("Last hit: ([^%c]*)")
				end

				-- Arcs.
				M.A = M.world({ ["combattext.whose"] = "all" })
				M.a = M.hit(M.A, 100)
				C.draw(M.A, 101.1)
				M.B = M.world({ ["combattext.arcWidth"] = "narrow", ["combattext.whose"] = "all" })
				M.b = M.hit(M.B, 100)
				C.draw(M.B, 101.1)
				check("msbt arc: Outgoing at u 0.5 is 84 units right and 120 up with Wide, 48 right with Narrow", near(M.a.points[1][4], 1130 + 84, 1e-9) and near(M.a.points[1][5], 510 + 120, 1e-9)
					and near(M.b.points[1][4], 1130 + 48, 1e-9), C.spot(M.a) .. " " .. C.spot(M.b))
				M.I = M.world()
				M.i = C.hit(M.I, "player", "HEAL", "", 300, 1)
				C.draw(M.I, 101.1)
				check("msbt arc: Incoming at u 0.5 is 84 units left and 120 down", near(M.i.points[1][4], 790 - 84, 1e-9) and near(M.i.points[1][5], 510 - 120, 1e-9), C.spot(M.i))
				M.x0, M.y0 = M.A.ns.ScrollPath("arc", 0, 240, 1, 1, 0.35)
				M.x1, M.y1 = M.A.ns.ScrollPath("arc", 1, 240, -1, -1, 0.35)
				M.x2 = M.A.ns.ScrollPath("arc", 0.5, 240, 1, 1)
				check("msbt arc: both ends of an arc are on the start column, and no width is the narrow one", M.x0 == 0 and M.y0 == 0 and near(M.x1, 0, 1e-9) and near(M.y1, -240, 1e-9) and near(M.x2, 48, 1e-9),
					M.x1 .. " " .. M.x2)
				M.N = C.world()
				check("msbt arc: Outgoing style and Incoming style default to Arc and Arc width to Wide", M.N.ns.Get("combattext.outStyle") == "arc" and M.N.ns.Get("combattext.inStyle") == "arc"
					and M.N.ns.Get("combattext.arcWidth") == "wide" and M.N.ns.Get("combattext.icons") == "all" and M.N.ns.Get("combattext.missWords") == "paren"
					and M.N.ns.Get("combattext.abilityColour") == "spell" and M.N.ns.Get("combattext.abilityName") == "off" and M.N.ns.Get("combattext.school") == false)

				-- Icons.
				M.C = M.world()
				M.cast(M.C, 8921)
				M.c = M.hit(M.C, 100.2)
				M.ic = M.icon(M.C, M.c)
				check("msbt icons: a Moonfire cast then its hit shows the Moonfire icon left of the number", M.ic ~= nil and M.ic.shown and M.ic.file == 136 and M.ic.points[1][3] == "LEFT" and M.ic.points[1][4] == -4
					and near(M.ic.texCoord[1], 0.08, 1e-9) and near(M.ic.texCoord[4], 0.92, 1e-9), tostring(M.ic and M.ic.file))
				C.draw(M.C, 102.125)
				M.fade = M.ic.alpha
				C.draw(M.C, 103)
				check("msbt icons: the icon fades with the number and goes when the number goes", near(M.fade, 0.5, 1e-9) and near(M.c.alpha, M.fade, 1e-9) and M.ic.shown == false, tostring(M.fade))
				M.D = M.world()
				M.D.fire("PLAYER_ENTER_COMBAT")
				M.d = { M.file(M.D, M.hit(M.D, 100.0)), M.file(M.D, M.hit(M.D, 100.2)) }
				M.D2 = M.world()
				M.D2.fire("START_AUTOREPEAT_SPELL")
				M.D3 = M.world()
				M.D3.class = "WARRIOR"
				M.D3.fire("START_AUTOREPEAT_SPELL")
				M.d[3], M.d[4] = M.file(M.D2, M.hit(M.D2, 100.0)), M.file(M.D3, M.hit(M.D3, 100.0))
				check("msbt icons: a white swing and an extra attack show the Auto Attack icon, a shot the Auto Shot icon and a wand shot the Shoot icon", table.concat(M.d, ",") == "132,132,133,134",
					table.concat(M.d, ","))
				M.E = M.world({ ["combattext.icons"] = "spells" })
				M.E.fire("PLAYER_ENTER_COMBAT")
				M.e = M.file(M.E, M.hit(M.E, 100.0))
				M.cast(M.E, 8921)
				M.e = M.e .. "," .. M.file(M.E, M.hit(M.E, 100.3))
				M.E2 = M.world({ ["combattext.icons"] = "spells" })
				M.E2.fire("START_AUTOREPEAT_SPELL")
				M.e = M.e .. "," .. M.file(M.E2, M.hit(M.E2, 100.0))
				check("msbt icons: Spells only shows the Moonfire icon and no Auto Attack or Auto Shot icon", M.e == "none,136,none", M.e)
				M.F = M.world()
				M.cast(M.F, 8921)
				M.hit(M.F, 100.0)
				C.draw(M.F, 103)
				M.F.auras.target = 1
				M.f = M.hit(M.F, 103.0)
				check("msbt icons: an aura slot hit shows no icon and the number keeps its centre", M.f ~= nil and M.file(M.F, M.f) == "none" and C.spot(M.f) == "CENTER BOTTOMLEFT 1130 510" and M.last(M.F) == "yours (aura slot).",
					C.spot(M.f))
				M.G = M.world()
				M.cast(M.G, 8921)
				M.g = C.hit(M.G, "player", "WOUND", "", 412, 1)
				check("msbt icons: a hit on you shows no icon", M.g ~= nil and M.file(M.G, M.g) == "none")
				M.H = M.world()
				M.cast(M.H, 8936)
				M.H.now = 100.5
				M.h = { C.hit(M.H, "player", "HEAL", "", 300, 1), C.hit(M.H, "player", "HEAL", "", 300, 1) }
				check("msbt icons: a heal on you 0.5 s after Regrowth shows the Regrowth icon, a second heal shows none", M.file(M.H, M.h[1]) == 137 and M.file(M.H, M.h[2]) == "none",
					M.file(M.H, M.h[1]) .. " " .. M.file(M.H, M.h[2]))
				M.J = M.world()
				M.cast(M.J, 8936, "pet")
				M.J2 = M.world()
				M.cast(M.J2, 8921)
				M.J3 = M.world()
				M.cast(M.J3, 8936)
				M.J3.now = 102
				M.j = { M.file(M.J, C.hit(M.J, "player", "HEAL", "", 300, 1)), M.file(M.J2, C.hit(M.J2, "player", "HEAL", "", 300, 1)), M.file(M.J3, C.hit(M.J3, "player", "HEAL", "", 300, 1)) }
				check("msbt icons: a heal on you after a pet heal, after a spell that is not helpful or 2 s after a helpful cast shows no icon", table.concat(M.j, ",") == "none,none,none", table.concat(M.j, ","))
				M.K = M.world()
				M.cast(M.K, SECRET)
				M.k = { M.file(M.K, M.hit(M.K, 100.2)) }
				M.K2 = M.world()
				M.K2.textureFault = "secret"
				M.K2.slash("combat trace")
				M.cast(M.K2, 8921)
				M.k[2] = M.file(M.K2, M.hit(M.K2, 100.2))
				M.k[3] = table.concat(M.K2.out, "\n"):find("-> yours (cast slot) no icon", 1, true) ~= nil and "traced" or table.concat(M.K2.out, "\n")
				check("msbt icons: a withheld spell id or texture gives no icon and still opens the cast slot", table.concat(M.k, ",") == "none,none,traced" and M.last(M.K) == "yours (cast slot)." and M.last(M.K2) == "yours (cast slot).",
					table.concat(M.k, ","))
				M.L = M.world()
				M.cast(M.L, 8921)
				M.L.now = 100.1
				M.cast(M.L, 8936)
				M.l = { M.file(M.L, M.hit(M.L, 100.2)), M.file(M.L, M.hit(M.L, 100.3)) }
				M.L2 = M.world()
				M.cast(M.L2, 8921)
				M.L2.now = 101.4
				M.cast(M.L2, 8936)
				M.l[3] = M.file(M.L2, M.hit(M.L2, 101.6))
				M.L3 = M.world()
				M.cast(M.L3, 1)
				M.L3.now = 100.1
				M.cast(M.L3, 8936)
				M.l[4], M.l[5] = M.file(M.L3, M.hit(M.L3, 100.2)), M.file(M.L3, M.hit(M.L3, 100.3))
				M.L4 = M.world()
				M.cast(M.L4, 8921)
				M.L4.now = 101.6
				M.cast(M.L4, 8936)
				M.l[6] = M.file(M.L4, M.hit(M.L4, 101.7))
				check("msbt icons: two casts then two hits give each hit the icon of its own cast, also after one slot runs out", table.concat(M.l, ",") == "136,137,137,none,137,137", table.concat(M.l, ","))
				M.P = M.world()
				M.cast(M.P, 8921)
				M.p = M.hit(M.P, 100.1)
				M.P2 = M.world()
				M.cast(M.P2, 8921)
				M.p2 = M.hit(M.P2, 100.1, "CRITICAL", 624)
				check("msbt icons: a crit icon is 1.25 times the size of a hit icon", M.icon(M.P, M.p).width == 35 and near(M.icon(M.P2, M.p2).width, 43.75, 1e-9) and near(M.icon(M.P2, M.p2).height, 43.75, 1e-9),
					tostring(M.icon(M.P, M.p).width) .. " " .. tostring(M.icon(M.P2, M.p2).width))
				M.Q = M.world()
				M.cast(M.Q, 8921)
				M.q = M.hit(M.Q, 100.0)
				M.Q2 = M.world()
				M.Q2.auras.target = 1
				M.q2 = M.hit(M.Q2, 100.0)
				check("msbt icons: the text moves right by half of the icon side plus 4 units, and not without an icon", near(M.q.points[1][4], 1130 + (35 + 4) / 2, 1e-9) and M.q2.points[1][4] == 1130,
					M.q.points[1][4] .. " " .. M.q2.points[1][4])
				M.R = M.world({ ["combattext.icons"] = "off" })
				M.R.fire("PLAYER_ENTER_COMBAT")
				M.cast(M.R, 8921)
				M.r = { M.file(M.R, M.hit(M.R, 100.2)), M.file(M.R, M.hit(M.R, 100.3)) }
				M.R2 = M.world({ ["combattext.whose"] = "mine" })
				M.cast(M.R2, 8921)
				M.r[3] = M.file(M.R2, M.hit(M.R2, 100.2))
				check("msbt icons: Off shows no icon, and Every hit while you attack shows none", table.concat(M.r, ",") == "none,none,none", table.concat(M.r, ","))
				M.S = M.world()
				M.cast(M.S, 8921)
				M.S.fire("PLAYER_ENTERING_WORLD")
				M.cast(M.S, 1)
				check("msbt icons: PLAYER_ENTERING_WORLD clears the cast icons with the cast slots", M.file(M.S, M.hit(M.S, 100.2)) == "none")

				M.T = M.world()
				M.T.slash("combat test")
				M.t1 = nil
				for _, font in ipairs(M.T.addonFonts) do
					if font.shown and font.text == "412" then
						M.t1 = M.file(M.T, font)
					end
				end
				check("msbt icons: /flatui combat test shows the Auto Attack icon on the first Outgoing sample", M.t1 == 132, tostring(M.t1))
				M.H2 = M.world({ ["combattext.icons"] = "off" })
				M.cast(M.H2, 8936)
				check("msbt icons: Off drops the icon of a heal on you too", M.file(M.H2, C.hit(M.H2, "player", "HEAL", "", 300, 1)) == "none")

				-- Words in parentheses.
				M.V = M.world({ ["combattext.whose"] = "all" })
				M.w = { C.say(M.V, "target", "MISS", "", 0), C.say(M.V, "target", "DODGE", "", 0), C.say(M.V, "target", "PARRY", "", 0), C.say(M.V, "target", "IMMUNE", "", 0),
					C.say(M.V, "player", "DODGE", "", 0), C.say(M.V, "player", "IMMUNE", "", 0) }
				M.V2 = C.world()
				M.w[7] = C.say(M.V2, "nameplate1", "MISS", "", 0)
				check("msbt paren: Miss, Dodge, Parry and Immune show as (Miss), (Dodge), (Parry) and (Immune) in Outgoing, Incoming and over enemies",
					table.concat(M.w, "|") == "(Miss)|(Dodge)|(Parry)|(Immune)|(Dodge)|(Immune)|(Miss)", table.concat(M.w, "|"))
				M.V.ns.Set("combattext.missWords", "bare")
				M.V2.ns.Set("combattext.missWords", "bare")
