			say(T.V0)
			T.V0.cvarRefuse.floatingCombatTextCombatDamage_v2 = true
			T.V0.grouped = true
			T.V0.fire("GROUP_ROSTER_UPDATE")
			check("ctown: in a group with the damage row still 0 the status does not say the game's numbers show", C.rows(T.V0) == "0111" and not has(T.V0.status(), "in a group"), C.rows(T.V0) .. " " .. T.V0.status())

			-- Everyone's draws nothing in a group either, with The game's own numbers.
			T.E = T.world({ ["combattext.whose"] = "all" }, "game")
			T.E.grouped = true
			check("ctown: in a group Everyone's draws nothing with The game's own numbers", say(T.E) == "none")

			-- The size of the game's numbers.
			T.Z = T.world(nil, "game")
			T.Z.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			say(T.Z)
			T.z = T.Z.cvars.WorldTextScale_v2
			T.Z.grouped = true
			T.Z.fire("GROUP_ROSTER_UPDATE")
			check("ctown: in a group Size sets the size of the game's numbers, and out of it Size of experience and other gains does", T.z == "1.000000" and T.Z.cvars.WorldTextScale_v2 == "1.4", tostring(T.z) .. " " .. tostring(T.Z.cvars.WorldTextScale_v2))

			-- Casts with no hit to use them: the list of cast slots keeps only the ones not run out.
			T.Q = T.world(nil, "game")
			T.Q.grouped = true
			T.Q.fire("GROUP_ROSTER_UPDATE")
			for index = 1, 3000 do
				T.Q.now = 100 + index * 0.01
				T.Q.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			end
			T.qs = nil
			for index = 1, 60 do
				local name, value = debug.getupvalue(listening(T.Q).script, index)
				if name == nil then
					break
				elseif name == "mine" then
					T.qs = #value.castSlots
				end
			end
			check("ctown: casts in a group with the game's own numbers do not pile up cast slots", T.qs ~= nil and T.qs <= 151, tostring(T.qs))

			-- A group joined in combat: a write the game refuses is tried again after combat.
			T.J = T.world(nil, "game")
			T.J.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			say(T.J)
			T.J.combat = true
			T.J.cvarRefuseInCombat.floatingCombatTextCombatDamage_v2 = true
			T.J.grouped = true
			T.J.fire("GROUP_ROSTER_UPDATE")
			T.j = C.rows(T.J)
			T.J.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			T.jr = say(T.J)
			T.J.combat = false
			T.J.fire("PLAYER_REGEN_ENABLED")
			T.J.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			T.jp = say(T.J)
			check("ctown: a hit while the game still refuses the row is shown, and none once the game's row is back", T.jr == "412" and T.jp == "none", T.jr .. " " .. T.jp)
			check("ctown: a group joined in combat: the row the game refuses stays and is written after combat", T.j == "0111" and C.rows(T.J) == "1111" and not has(T.J.status(), "the game refused"), T.j .. " " .. C.rows(T.J))

			-- Numbers over friendly units are the same with both choices.
			for _, group in ipairs({ "game", "flat" }) do
				T.N = T.world(nil, group)
				T.N.attackable.nameplate1 = false
				T.N.cplate.unitToken, T.N.cplate2.unitToken = "nameplate1", "nameplate2"
				T.N.grouped = true
				T.n = C.say(T.N, "nameplate1", "WOUND", "", 5)
				check("ctown: numbers over a friendly plate in a group are the same with " .. group, T.n == "-5", T.n)
			end

			-- The status names the choice.
			T.L = T.world()
			check("ctown: the status says how One hit for each of yours counts", has(T.L.status(), "Whose hits: one for each of your casts, swings, shots and auras. Left out as not yours: 0."), T.L.status())
			T.L.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 1)
			T.l = T.at(T.L, { 100.1, 100.2, 100.3 })
			check("ctown: and counts the hits left out", T.l == "412,none,none" and has(T.L.status(), "Left out as not yours: 2."), T.L.status())
			T.V = T.world()
			T.V.auras.nameplate2 = 1
			T.v = C.say(T.V, "nameplate2", "WOUND", SECRET, 412, 1)
			check("ctown: a kind of hit the game withholds is left out and counted", T.v == "none" and has(T.V.slash("combat"), "tell about: 1."), T.V.slash("combat"):match("tell about: %d+"))

			-- The signals are not heard with Everyone's.
			T.O.change("combattext.whose", "Everyone's")
			check("ctown: Everyone's stops listening after One hit for each of yours", listening(T.O) == nil)
		end
	end

	-- Units that are not a nameplate, and plates that cannot be used.
	do
		local W = C.world()
		local texts = { C.say(W, "target", "WOUND", "", 1), C.say(W, "player", "WOUND", "", 2), C.say(W, "party1", "WOUND", "", 3), C.say(W, "pet", "WOUND", "", 4) }
		check("combat text, reports for target, player, party1 and pet: only the player's is shown, as the player's own text, so no hit shows twice", table.concat(texts, ",") == "none,-2,none,none" and C.rows(W) == "1111"
			and #W.addonFonts == 2, table.concat(texts, ","))
		check("combat text, those reports are counted: one for target, none for nameplates", has(W.slash("combat"), "Hit reports: 0 for nameplates, 1 for target."), W.slash("combat"))
		check("combat text, a unit that only starts like a nameplate is not one", C.say(W, "namesake", "WOUND", "", 8) == "none" and C.say(W, "nameplat", "WOUND", "", 9) == "none")
		local missing = C.say(W, "nameplate7", "WOUND", "", 5)
		W.units.nameplate8 = W.newPlate({ plateForbidden = true })
		local forbidden = C.say(W, "nameplate8", "WOUND", "", 6)
		W.units.nameplate9 = SECRET
		local withheld = C.say(W, "nameplate9", "WOUND", "", 7)
		local quiet = #W.violations == 0 and #W.errors == 0
		check("combat text, a plate that is missing, forbidden or withheld: nothing is shown and /flatui combat counts it", missing == "none" and forbidden == "none" and withheld == "none"
			and has(W.slash("combat"), "No nameplate: 3.") and C.rows(W) == "1111" and quiet, W.slash("combat"))
	end

	-- Numbers are pooled.
	do
		local W = C.world()
		local first = C.hit(W, "nameplate1", "WOUND", "", 1)
		local t0 = W.now
		C.draw(W, t0 + 1.6)
		local again = C.hit(W, "nameplate1", "WOUND", "", 2)
		check("combat text, a number that has lived its time: the same font string shows the next, and only one was ever made", again == first and #W.addonFonts == 1 and first.text == "2" and first.shown)
		local V = C.world()
		for amount = 1, 41 do
			C.hit(V, "nameplate1", "WOUND", "", amount)
		end
		check("combat text, forty-one reports in one frame: forty font strings, and the newest took the place of the oldest", #V.addonFonts == 40 and V.addonFonts[1].text == "41" and V.addonFonts[2].text == "2"
			and C.shownCount(V) == 40 and C.quiet(V), C.trouble(V))
	end

	-- In combat, on protected plates.
	do
		local W = C.world()
		W.combat = true
		W.cplate.protected, W.cplate2.protected = true, true
		local font = C.hit(W, "nameplate1", "WOUND", "", 412)
		C.hit(W, "nameplate2", "WOUND", "", 413)
		local host = font and font.owner
		local parents = true
		for _, f in ipairs(W.addonFonts) do
			parents = parents and f.owner == host
		end
		check("combat text, hits in combat on protected plates: the numbers are font strings of one frame on UIParent, and nothing was made on a plate", font ~= nil and host.parent == W.env.UIParent and parents
			and #W.addonFonts == 2 and W.cplate.regions == nil and W.cplate2.regions == nil and #W.violations == 0 and #W.errors == 0, C.trouble(W))
	end

	-- Motion.
	do
		local W = C.world()
		W.now = 100
		local font = C.hit(W, "nameplate1", "WOUND", "", 412)
		local t0 = W.now
		C.draw(W, t0 + 0.625)
		check("combat text, rise and fall: 0.625 seconds on, the number is 31.25 units higher", near(font.points[1][5], 20 + 31.25) and near(font.alpha, 1) and #font.points == 1, C.spot(font))
		C.draw(W, t0 + 0.95)
		check("combat text, rise and fall: the number is not faded before the last half second", near(font.alpha, 1) and font.shown)
		C.draw(W, t0 + 1.25)
		check("combat text, rise and fall: it is half faded at 1.25 seconds", near(font.alpha, 0.5, 1e-6) and font.shown, tostring(font.alpha))
		C.draw(W, t0 + 1.49)
		check("combat text, rise and fall: it is still shown just before 1.5 seconds", font.shown)
		C.draw(W, t0 + 1.5)
		check("combat text, rise and fall: it is hidden at 1.5 seconds, and no frame runs a script any more", not font.shown and C.running(W) == 0, tostring(font.shown))
		local U = C.world()
		U.ns.Set("combattext.movement", "up")
		local a = C.hit(U, "nameplate1", "WOUND", "", 1)
		local b = C.hit(U, "nameplate1", "WOUND", "", 2)
		local u0 = U.now
		C.draw(U, u0 + 0.5)
		local mid = { a.points[1][4], a.points[1][5], b.points[1][4], b.points[1][5] }
		C.draw(U, u0 + 1.0)
		check("combat text, straight up: 40 units a second, and a number keeps its x", near(mid[2], 20 + 20) and near(a.points[1][5], 20 + 40) and mid[3] == 20 and b.points[1][4] == 20 and a.points[1][4] == 0
			and near(mid[4], 20 + 20), C.spot(a) .. " " .. C.spot(b))
		C.draw(U, u0 + 1.5001)
		check("combat text, straight up: hidden at 1.5 seconds", not a.shown and not b.shown)
		local D = C.world()
		D.ns.Set("combattext.spread", "loose")
		local c = C.hit(D, "nameplate1", "WOUND", "", 3)
		local d = C.hit(D, "nameplate1", "WOUND", "", 4)
		local d0 = D.now
		C.draw(D, d0 + 1.0)
		check("combat text, rise and fall: a number in a lane drifts sideways, 0.75 units for each unit of its lane every second", near(c.points[1][4], 0) and near(d.points[1][4], 20 + 20 * 0.75 * 1.0), C.spot(d))
		check("combat text, motion: no violations, errors or messages", C.quiet(W) and C.quiet(U) and C.quiet(D), C.trouble(W) .. C.trouble(U))
	end

	-- Lanes, size and height.
	do
		local W = C.world()
		W.ns.Set("combattext.overlap", "turn")
		local xs = {}
		for index = 1, 8 do
			xs[index] = g(C.hit(W, "nameplate1", "WOUND", "", index).points[1][4])
		end
		local other = C.hit(W, "nameplate2", "WOUND", "", 99)
		W.showPlate("nameplate1", W.cplate)
		local restart = g(C.hit(W, "nameplate1", "WOUND", "", 7).points[1][4])
		check("combat text, spread loose: eight numbers start at 0, 20, -20, 40, -40, 0, 20 and -20, and a plate with a new unit starts the order again", table.concat(xs, ",") == "0,20,-20,40,-40,0,20,-20" and restart == "0",
			table.concat(xs, ",") .. " " .. restart)
		check("combat text, a plate that gets a unit: the numbers still on it are gone, and those on another plate are not", C.shownCount(W) == 2 and other.shown and other.points[1][2] == W.cplate2)
		W.ns.Set("combattext.spread", "tight")
		xs = {}
		for index = 1, 4 do
			xs[index] = g(C.hit(W, "nameplate1", "WOUND", "", index).points[1][4])
		end
		check("combat text, spread tight: every number starts at 0", table.concat(xs, ",") == "0,0,0,0", table.concat(xs, ","))
		local sizes = {}
		for _, size in ipairs({ 60, 140, 160, 100 }) do
			W.ns.Set("combattext.size", size)
			sizes[#sizes + 1] = g(C.hit(W, "nameplate1", "WOUND", "", 1).textHeight)
		end
		check("combat text, size 60%, 140%, 160% and 100%: a plain number is 15, 35, 40 and 25 units high", table.concat(sizes, ",") == "15,35,40,25", table.concat(sizes, ","))
		local heights = {}
		for _, height in ipairs({ 0, 40, 100, 60 }) do
			W.ns.Set("combattext.height", height)
			heights[#heights + 1] = g(C.hit(W, "nameplate1", "WOUND", "", 1).points[1][5])
		end
		check("combat text, height 0, 40, 100 and 60: a number starts 40 units below the centre of the plate, at it, 60 above it, and 20 above it", table.concat(heights, ",") == "-40,0,60,20", table.concat(heights, ","))
		check("combat text, lanes, size and height: no violations, errors or messages", C.quiet(W), C.trouble(W))
	end

	-- ctspread: sizes to 400%, Spread width and Keep apart.
	do
		local T = {}
		-- The share of the smaller number the other covers, for two font strings of the mock: their widths, heights and spots over the plate.
		function T.cover(a, b)
			local aw, ah, bw, bh = a.GetStringWidth(), a.textHeight, b.GetStringWidth(), b.textHeight
			local ax, ay, bx, by = a.points[1][4], a.points[1][5], b.points[1][4], b.points[1][5]
			local across = math.min(ax + aw / 2, bx + bw / 2) - math.max(ax - aw / 2, bx - bw / 2)
			local up = math.min(ay + ah / 2, by + bh / 2) - math.max(ay - ah / 2, by - bh / 2)
			if across <= 0 or up <= 0 then
				return 0
			end
			return across * up / math.min(aw * ah, bw * bh)
		end
		-- The greatest cover of any pair of the first n numbers of a list.
		function T.worst(list, n)
			local worst = 0
			for i = 1, n do
				for j = i + 1, n do
					worst = math.max(worst, T.cover(list[i], list[j]))
				end
			end
			return worst
		end
		function T.join(list)
			local out = {}
			for index, value in ipairs(list) do
				out[index] = ("%g"):format(value)
			end
			return table.concat(out, ",")
		end
		function T.burst(W, count)
			local list = {}
			for index = 1, count do
				list[index] = C.hit(W, "nameplate1", "WOUND", "", 412)
				W.now = W.now + 0.1
			end
			return list
		end
		function T.name(W, font)
			return W.fontObjects[font.fontObject or font.template]
		end

		-- Stay in turn at the width of 100 and a size of 140 is the layout of 0.4.46: ten numbers in the lanes 0, 20, -20, 40, -40 twice, 20 units up.
		local W = C.world()
		W.ns.Set("combattext.overlap", "turn")
		W.ns.Set("combattext.pop", "plain")
		local list = {}
		for index = 1, 10 do
			list[index] = C.hit(W, "nameplate1", "WOUND", "", 412)
		end
		local t0 = W.now
		local starts, moved, want, wantMoved = {}, {}, {}, {}
		local order = { 0, 20, -20, 40, -40 }
		for index, font in ipairs(list) do
			starts[index] = ("%g,%g"):format(font.points[1][4], font.points[1][5])
			want[index] = ("%g,20"):format(order[(index - 1) % 5 + 1])
		end
		C.draw(W, t0 + 0.5)
		for index, font in ipairs(list) do
			local lane = order[(index - 1) % 5 + 1]
			moved[index] = ("%.3f,%.3f"):format(font.points[1][4], font.points[1][5])
			wantMoved[index] = ("%.3f,%.3f"):format(lane + lane * 0.75 * 0.5, 20 + 100 * 0.5 - 80 * 0.25)
		end
		check("ctspread: Stay in turn, width 100, size 140: ten hits start where 0.4.46 starts them", table.concat(starts, " ") == table.concat(want, " "), table.concat(starts, " "))
		check("ctspread: Stay in turn, width 100, size 140: half a second on they have moved as 0.4.46 moves them", table.concat(moved, " ") == table.concat(wantMoved, " "), table.concat(moved, " "))

		-- The lanes of a width.
		local N = W.ns
		check("ctspread: widths 50, 100, 130, 150, 200 and 300 give 3, 5, 5, 7, 9 and 13 lanes",
			#N.CombatLanes(50, 1) == 3 and #N.CombatLanes(100, 1) == 5 and #N.CombatLanes(130, 1) == 5 and #N.CombatLanes(150, 1) == 7
			and #N.CombatLanes(200, 1) == 9 and #N.CombatLanes(300, 1) == 13)
		check("ctspread: width 100 gives the lanes 0, 20, -20, 40, -40 and width 50 gives 0, 20, -20", T.join(N.CombatLanes(100, 1)) == "0,20,-20,40,-40" and T.join(N.CombatLanes(50, 1)) == "0,20,-20",
			T.join(N.CombatLanes(100, 1)))
		check("ctspread: width 130 widens the pitch to 26, and widths 200 and 300 reach 80 and 120 at a pitch of 20",
			T.join(N.CombatLanes(130, 1)) == "0,26,-26,52,-52" and N.CombatLanes(200, 1)[8] == 80 and N.CombatLanes(300, 1)[12] == 120 and N.CombatLanes(300, 1)[2] == 20)
		check("ctspread: a grow of 2 doubles the reach, and no width gives the one lane in the middle", T.join(N.CombatLanes(100, 2)) == "0,40,-40,80,-80" and T.join(N.CombatLanes(0, 1)) == "0")

		-- Grow: nothing moves differently up to 160%, and a number moves as far as its height beyond it.
		local rise = function(grow, movement, at)
			local _, y = N.CombatOffsets({ lane = 0, movement = movement, grow = grow }, at)
			return y
		end
		check("ctspread: grow is 1 at 160% and under, 1.25 at 200% and 2.5 at 400%", N.CombatGrow(25 * 1.6) == 1 and N.CombatGrow(25 * 0.4) == 1 and N.CombatGrow(25 * 2) == 1.25 and N.CombatGrow(25 * 4) == 2.5)
		check("ctspread: a number of 400% rises and climbs 2.5 times as far as one of 160%", near(rise(N.CombatGrow(100), "fall", 0.625), 2.5 * rise(N.CombatGrow(40), "fall", 0.625))
			and near(rise(N.CombatGrow(100), "up", 1), 100) and near(rise(N.CombatGrow(40), "up", 1), 40))
		check("ctspread: a number with no grow moves as in 0.4.46", near(rise(nil, "fall", 0.5), 30) and near(rise(nil, "up", 1), 40))

		-- Where a number is put among those on screen.
		local lanes = { 0, 100, -100 }
		local function old(x, y, age)
			return { x = x, y = y, w = 50, h = 30, age = age or 0, lane = x, drift = 0, grow = 1, movement = "up" }
		end
		local function spec(turn, rows, apart)
			return { lanes = lanes, turn = turn, w = 50, h = 30, rows = rows, y0 = 0, apart = apart, grow = 1, movement = "up" }
		end
		local lane, lift = N.CombatChoose({}, spec(2, 3, true))
		check("ctspread: with nothing on screen a number takes the lane in turn, in row 0", lane == 100 and lift == 0)
		lane, lift = N.CombatChoose({ old(100, 0) }, spec(2, 3, true))
		check("ctspread: a young number in the lane in turn sends the next to the next lane", lane == -100 and lift == 0, lane .. " " .. lift)
		lane, lift = N.CombatChoose({ old(0, 0), old(100, 0), old(-100, 0) }, spec(2, 3, true))
		check("ctspread: with every lane busy the number starts in row 1, 1.05 heights up", lane == 100 and near(lift, 31.5), lane .. " " .. lift)
		lane, lift = N.CombatChoose({ old(0, 0), old(100, 0), old(-60, 0) }, spec(1, 1, true))
		check("ctspread: with every row and lane busy the number takes the place that costs least", lane == -100 and lift == 0, lane .. " " .. lift)
		lane, lift = N.CombatChoose({ old(50, 0) }, spec(1, 1, true))
		check("ctspread: numbers a full width apart cost nothing", lane == 0 and lift == 0)
		lane, lift = N.CombatChoose({ old(0, 0) }, spec(1, 3, false))
		check("ctspread: Stay in turn takes the lane in turn whatever is on screen", lane == 0 and lift == 0)
		lane, lift = N.CombatChoose({ old(0, 0, 2), old(100, 0, 2), old(-100, 0, 2) }, spec(1, 2, true))
		check("ctspread: an old number is looked at where it will be: one that has climbed away leaves the lane free", lane == 0 and lift == 0, lane .. " " .. lift)

		-- A burst of six hits 0.1 seconds apart at 140% and a width of 200.
		local B = C.world()
		B.ns.Set("combattext.pop", "plain")
		B.ns.Set("combattext.spreadWidth", 200)
		local fonts = T.burst(B, 6)
		local fourth = B.now - 0.3
		local worst = {}
		for _, after in ipairs({ 0, 0.2, 0.4 }) do
			C.draw(B, fourth + after)
			worst[#worst + 1] = ("%.2f"):format(T.worst(fonts, 4))
		end
		check("ctspread: a burst of six at 140%, width 200 and 4 rows: no two of the first four cover more than a quarter of each other at 0, 0.2 and 0.4 seconds",
			tonumber(worst[1]) <= 0.25 and tonumber(worst[2]) <= 0.25 and tonumber(worst[3]) <= 0.25, table.concat(worst, " "))
		local S = C.world()
		S.ns.Set("combattext.pop", "plain")
		S.ns.Set("combattext.spreadWidth", 200)
		S.ns.Set("combattext.overlap", "turn")
		local turned = T.burst(S, 6)
		C.draw(S, S.now - 0.3)
		check("ctspread: the same burst in turn covers more than a quarter, so the test tells the two apart", T.worst(turned, 4) > 0.25, tostring(T.worst(turned, 4)))

		-- Rows.
		local R = C.world()
		R.ns.Set("combattext.pop", "plain")
		R.ns.Set("combattext.spread", "tight")
		R.ns.Set("combattext.rows", 1)
		local one = T.burst(R, 6)
		local ys = {}
		for index, font in ipairs(one) do
			ys[index] = font.points[1][5]
		end
		check("ctspread: Rows 1 puts every number in row 0", T.join(ys) == "20,20,20,20,20,20", T.join(ys))
		local Q = C.world()
		Q.ns.Set("combattext.pop", "plain")
		Q.ns.Set("combattext.spread", "tight")
		Q.ns.Set("combattext.rows", 3)
		local eight = T.burst(Q, 8)
		local rowsUsed, outside = {}, 0
		for _, font in ipairs(eight) do
			local y = font.points[1][5]
			rowsUsed[("%.2f"):format(y)] = true
			if not (near(y, 20) or near(y, 20 + 36.75) or near(y, 20 + 73.5)) then
				outside = outside + 1
			end
		end
		check("ctspread: Rows 3 with one lane starts eight numbers in the rows 1.05 heights apart and no higher than the third", outside == 0 and rowsUsed["20.00"] and rowsUsed["56.75"] and rowsUsed["93.50"], T.join(ys))

		-- A critical hit swells to 84 at 140% and to 128 at 400%, and every size from 40 to 400 is drawn at its height.
		local P = C.world()
		local peaks = {}
		for _, size in ipairs({ 140, 400 }) do
			P.ns.Set("combattext.size", size)
			local crit = C.hit(P, "nameplate1", "WOUND", "CRITICAL", 824)
			C.draw(P, P.now + 0.05)
			peaks[#peaks + 1] = crit.textHeight
			C.draw(P, P.now + 0.5)
		end
		check("ctspread: the pop of a critical hit peaks at 84 at 140% and at 128 at 400%", T.join(peaks) == "84,128", T.join(peaks))
		local heights, bad = {}, {}
		local Z = C.world()
		for size = 40, 400, 10 do
			Z.ns.Set("combattext.size", size)
			local font = C.hit(Z, "nameplate1", "WOUND", "", 412)
			heights[#heights + 1] = font.textHeight
			if not near(font.textHeight, 25 * size / 100) then
				bad[#bad + 1] = size
			end
			local crit = C.hit(Z, "nameplate1", "WOUND", "CRITICAL", 824)
			C.draw(Z, Z.now + 0.05)
			if crit.textHeight > 128 or crit.textHeight < 25 * size / 100 * 1.2 then
				bad[#bad + 1] = "crit" .. size
			end
			C.draw(Z, Z.now + 2)
		end
		check("ctspread: every size from 40 to 400 draws a plain number at a quarter of it and no critical peak over 128", #heights == 37 and #bad == 0 and heights[1] == 10 and heights[37] == 100 and C.quiet(Z),
			table.concat(bad, ",") .. " " .. C.trouble(Z))
		check("ctspread: sizes 40 and 400 are kept and 30 and 410 are brought into the range", N.Normalised("combattext.size", 40) == 40 and N.Normalised("combattext.size", 400) == 400
			and N.Normalised("combattext.size", 30) == 40 and N.Normalised("combattext.size", 410) == 400 and N.Normalised("combattext.friendSize", 410) == 400 and N.Normalised("combattext.ownSize", 30) == 40
			and N.Normalised("combattext.spreadWidth", 40) == 50 and N.Normalised("combattext.spreadWidth", 310) == 300 and N.Normalised("combattext.rows", 7) == 6 and N.Normalised("combattext.rows", 0) == 1)

		-- The raster of the font objects.
		local F = C.world()
		F.ns.Set("combattext.size", 210)
		local at64 = C.hit(F, "nameplate1", "WOUND", "", 1)
		F.ns.Set("combattext.size", 220)
		local at128 = C.hit(F, "nameplate1", "WOUND", "", 1)
		local o64, o128 = T.name(F, at64), T.name(F, at128)
		check("ctspread: a size of 210 draws on the font object of 64 with the name it always had, and 220 on a second of 128", (at64.fontObject or at64.template) == "FlatUICombat_friz_none_plain" and o64.font[2] == 64
			and (at128.fontObject or at128.template) == "FlatUICombat_friz_none_plain_r128" and o128.font[2] == 128 and #F.madeFonts == 2 and o64 ~= o128, tostring(at128.fontObject))
		local H = C.world()
		H.ns.Set("combattext.ownSize", 220)
		check("ctspread: the size of your own text counts as well: 220 there makes the object of 128", (C.hit(H, "nameplate1", "WOUND", "", 1).fontObject or ""):find("_r128$") ~= nil)
		local calm = C.quiet(F)
		check("ctspread: the report says the raster and the width and height of the last number", has(F.slash("combat"), "Font size made at: 128.\n") and has(F.slash("combat"), "Width of the last number: 27.5. Height drawn: 55.\n"), F.slash("combat"))

		-- The game's own numbers follow the width and the size.
		local G = C.world()
		local seen = {}
		G.ns.Set("combattext.spreadWidth", 200)
		seen[#seen + 1] = G.cvars.WorldTextStartPosRandomness_v2
		G.ns.Set("combattext.spreadWidth", 100)
		seen[#seen + 1] = G.cvars.WorldTextStartPosRandomness_v2
		G.ns.Set("combattext.spreadWidth", 150)
		G.ns.Set("combattext.spread", "tight")
		seen[#seen + 1] = G.cvars.WorldTextStartPosRandomness_v2
		G.ns.Set("combattext.size", 400)
		seen[#seen + 1] = G.cvars.WorldTextScale_v2
		check("ctspread: the game's variables: width 200 writes 2.0, width 100 the game's 1.0, Tight 0.0 and size 400 writes 4.0", table.concat(seen, " ") == "2.0 1.0 0.0 4.0", table.concat(seen, " "))

		-- A number whose plate went is not in the way.
		local L = C.world()
		L.ns.Set("combattext.pop", "plain")
		local gone = C.hit(L, "nameplate1", "WOUND", "", 412)
		L.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		L.showPlate("nameplate1", L.cplate)
		local after = C.hit(L, "nameplate1", "WOUND", "", 412)
		check("ctspread: a number whose plate is gone is left out: the next on the plate starts in lane 0, row 0", gone.shown and C.spot(after) == "CENTER CENTER 0 20", C.spot(after))

		-- The sideways speed has a limit of 30 units a second for each unit of grow.
		local D = C.world()
		D.ns.Set("combattext.overlap", "turn")
		D.ns.Set("combattext.pop", "plain")
		D.ns.Set("combattext.spreadWidth", 300)
		local wide = {}
		for index = 1, 13 do
			wide[index] = C.hit(D, "nameplate1", "WOUND", "", 1)
		end
		C.draw(D, D.now + 1)
		check("ctspread: width 300 puts the 13th number at -120 and its drift is held to 30 a second", near(wide[13].points[1][4], -150) and near(wide[2].points[1][4], 20 + 15) and near(wide[6].points[1][4], 60 + 30),
			g(wide[13].points[1][4]) .. " " .. g(wide[2].points[1][4]) .. " " .. g(wide[6].points[1][4]))
		local E = C.world()
		E.ns.Set("combattext.overlap", "turn")
		E.ns.Set("combattext.pop", "plain")
		E.ns.Set("combattext.size", 300)
		E.ns.Set("combattext.spreadWidth", 300)
		local grown = {}
		for index = 1, 13 do
			grown[index] = C.hit(E, "nameplate1", "WOUND", "", 1)
		end
		C.draw(E, E.now + 1)
		check("ctspread: at 300% the lanes reach 225 and the drift is held to 56.25 a second", near(grown[13].points[1][4], -225 - 56.25), g(grown[13].points[1][4]))
		check("ctspread: no violations, errors or messages", C.quiet(W) and C.quiet(B) and C.quiet(R) and C.quiet(P) and calm and C.quiet(G) and C.quiet(L) and C.quiet(D) and C.quiet(E),
			C.trouble(W) .. C.trouble(B) .. C.trouble(D))
	end

	-- ctspread: how Keep apart weighs the numbers on screen, and what the report and the game's variables say.
	do
		local N
		local function box(x, y, w, h, extra)
			local old = { x = x, y = y, w = w, h = h, age = 0, lane = x, drift = 0, grow = 1, movement = "up" }
			for key, value in pairs(extra or {}) do
				old[key] = value
			end
			return old
		end
		local function spec(lanes, w, h, extra)
			local made = { lanes = lanes, turn = 1, w = w, h = h, rows = 1, y0 = 0, apart = true, grow = 1, movement = "up" }
			for key, value in pairs(extra or {}) do
				made[key] = value
			end
			return made
		end
		local W = C.world()
		N = W.ns
		local lane
		-- Cost is the share of the smaller box covered, so a small box inside a place costs more than a large one covering half of another.
		lane = N.CombatChoose({ box(0, 0, 10, 10), box(200, 0, 200, 30) }, spec({ 0, 100 }, 50, 30))
		check("ctspread: a place half covered by a large number costs less than one with a small number wholly inside it", lane == 100, tostring(lane))
		-- A tie goes to the first place.
		lane = N.CombatChoose({ box(0, 0, 50, 30), box(100, 0, 50, 30), box(-100, 0, 50, 30) }, spec({ 0, 100, -100 }, 50, 30, { turn = 2 }))
		check("ctspread: places that cost the same: the lane in turn", lane == 100, tostring(lane))
		-- An old number is looked at 0.4 seconds on: one that drifts into a lane after 0.4 seconds sends the new number to the other lane.
		local drifting = { drift = 250, movement = "fall" }
		lane = N.CombatChoose({ box(0, 0, 50, 200, drifting) }, spec({ 100, -100 }, 50, 200, { movement = "fall" }))
		check("ctspread: a number that will drift into the lane in 0.4 seconds sends the new one to the other lane", lane == -100, tostring(lane))
		-- A number that has aged is looked at where it is, not where it started.
		lane = N.CombatChoose({ box(0, 0, 50, 200, { drift = 250, movement = "fall", age = 1 }) }, spec({ 100, -100 }, 50, 200, { movement = "fall" }))
		check("ctspread: a number of age 1 has drifted past the lane, so the lane is free", lane == 100, tostring(lane))
		-- The new number moves as the movement says, with its grow and its own drift.
		local still = { movement = "up" }
		lane = N.CombatChoose({ box(64, 0, 20, 60, still) }, spec({ 40, -40 }, 20, 60, { movement = "fall" }))
		check("ctspread: a new number in the lane 40 drifts 12 units by 0.4 seconds and so reaches an old number there, which sends it to the lane -40", lane == -40, tostring(lane))
		lane = N.CombatChoose({ box(0, 40, 20, 10, still) }, spec({ 0, 100 }, 20, 10, { movement = "fall", grow = 2 }))
		check("ctspread: a new number of grow 2 rises 54.4 units by 0.4 seconds and so reaches an old number there, which sends it to the other lane", lane == 100, tostring(lane))
		lane = N.CombatChoose({ box(0, 40, 20, 10, still) }, spec({ 0, 100 }, 20, 10, { movement = "up", grow = 2 }))
		check("ctspread: a new number that only climbs does not reach it", lane == 0, tostring(lane))

		-- What Keep apart is given of the numbers on screen: each one's start, size, age, lane, drift, grow and movement.
		local S = C.world()
		S.ns.Set("combattext.pop", "plain")
		S.ns.Set("combattext.size", 300)
		S.ns.Set("combattext.spreadWidth", 300)
		local real, seen = S.ns.CombatChoose, {}
		S.ns.CombatChoose = function(olds, spec2)
			seen = {}
			for index, old in ipairs(olds) do
				seen[index] = { x = old.x, y = old.y, w = old.w, h = old.h, age = old.age, lane = old.lane, drift = old.drift, grow = old.grow, movement = old.movement }
			end
			return real(olds, spec2)
		end
		local first = C.hit(S, "nameplate1", "WOUND", "CRITICAL", 412)
		S.now = S.now + 0.3
		local second = C.hit(S, "nameplate1", "WOUND", "", 412)
		S.now = S.now + 0.1
		C.hit(S, "nameplate1", "WOUND", "", 412)
		local one, two = seen[1], seen[2]
		check("ctspread: Keep apart is given the first number as it is: where it started, 90 high as a critical hit at 300%, 0.4 seconds old, in lane 0, with the grow of 1.875 and its movement",
			one and one.x == 0 and near(one.y, 20) and one.h == 90 and near(one.age, 0.4) and one.lane == 0 and one.drift == 0 and near(one.grow, 1.875) and one.movement == "fall", one and (one.x .. " " .. one.y .. " " .. one.h .. " " .. one.age) or "none")
		check("ctspread: Keep apart is given the second number as it is: its lane, the drift of that lane held to 56.25, and an age of 0.1",
			two and near(two.x, second.points[1][4]) and near(two.lane, second.points[1][4]) and near(two.age, 0.1) and near(two.drift, N.CombatDrift(two.lane, 1.875)) and near(two.w, second.GetStringWidth()), two and (two.x .. " " .. two.age) or "none")
		check("ctspread: it is given two numbers for the two on screen", #seen == 2 and first.shown)
		-- A number of the player's is not given to it.
		local P = C.world()
		local count = 0
		local realP = P.ns.CombatChoose
		P.ns.CombatChoose = function(olds, spec2)
			count = #olds
			return realP(olds, spec2)
		end
		C.hit(P, "player", "WOUND", "", 5)
		C.hit(P, "nameplate1", "WOUND", "", 6)
		check("ctspread: a number for the player is not one of those a number over an enemy keeps apart from", count == 0, tostring(count))

		-- The width: what the game gives, and three times the height when it gives none, or seven times with a word after it.
		local E = C.world()
		E.widthFault = "error"
		C.hit(E, "nameplate1", "WOUND", "", 412)
		local plain = E.slash("combat")
		C.hit(E, "nameplate1", "WOUND", "GLANCING", 412)
		local worded = E.slash("combat")
		local X = C.world()
		X.widthFault = "secret"
		C.hit(X, "nameplate1", "WOUND", "", 412)
		local hidden = X.slash("combat")
		local K = C.world()
		C.hit(K, "nameplate1", "WOUND", "CRITICAL", 824)
		local critical = K.slash("combat")
		check("ctspread: a width the game will not give is three times the height, four more with a word, and a withheld one the same",
			has(plain, "Width of the last number: 105 (3 times its height when the game gave none). Height drawn: 35.\n") and has(worded, "Width of the last number: 245 (3 times its height when the game gave none). Height drawn: 35.\n")
			and has(hidden, "Width of the last number: 105 (3 times its height when the game gave none). Height drawn: 35.\n"), plain .. worded)
		check("ctspread: the report gives the height a critical number settles at, and the width the game gave it, without the note",
			has(critical, "Width of the last number: 63. Height drawn: 42.\n") and not has(critical, "when the game gave none"), critical)

		-- The pop of a critical hit at 210% peaks at the settled height and 60.
		local Q = C.world()
		Q.ns.Set("combattext.size", 210)
		local crit = C.hit(Q, "nameplate1", "WOUND", "CRITICAL", 824)
		C.draw(Q, Q.now + 0.05)
		check("ctspread: at 210% a critical hit swells to the settled 63 and 60 more, 123", crit.textHeight == 123, tostring(crit.textHeight))

		-- Your own text staggers by its size, and the raster counts the size over friendly units.
		local O = C.world()
		O.ns.Set("combattext.ownSize", 200)
		O.ns.Set("combattext.inStyle", "horizontal")
		local a, b = C.hit(O, "player", "WOUND", "", 1, 1), C.hit(O, "player", "WOUND", "", 2, 1)
		check("ctspread: at 200% the lines of your own text are 52 units apart", near(a.points[1][5] - b.points[1][5], 52), g(a.points[1][5] - b.points[1][5]))
		local R = C.world()
		R.ns.Set("combattext.friendSize", 220)
		check("ctspread: a size of 220 over friendly units makes the object of 128", (C.hit(R, "nameplate1", "WOUND", "", 1).fontObject or ""):find("_r128$") ~= nil)

		-- The game's start of 1.0 is put back, with no record, at a width of 100.
		local G = C.world()
		G.ns.Set("combattext.spreadWidth", 200)
		G.ns.Set("combattext.spreadWidth", 100)
		local cvars = G.env.FlatUIDB.cvars
		check("ctspread: back at a width of 100 the game's own start is put back and nothing is remembered", G.cvars.WorldTextStartPosRandomness_v2 == "1.0" and not (cvars and cvars.WorldTextStartPosRandomness_v2),
			tostring(G.cvars.WorldTextStartPosRandomness_v2))

		-- The rows.
		local items = {}
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == "combattext" then
				for _, item in ipairs(page) do
					if item.key then
						items[item.key] = item
					end
				end
			end
		end
		check("ctspread: Spread width needs Spread on Loose, Rows is 4 by default and has no needs, Overlapping numbers is Keep apart",
			items.spreadWidth.needs == "spread" and table.concat(items.spreadWidth.needsIn, ",") == "loose" and W.ns.Get("combattext.rows") == 4 and items.rows.needs == nil
			and W.ns.Get("combattext.overlap") == "apart" and W.ns.Get("combattext.spreadWidth") == 100)

		check("ctspread: no violations, errors or messages", C.quiet(S) and C.quiet(P) and C.quiet(Q) and C.quiet(O) and C.quiet(R) and C.quiet(G), C.trouble(S) .. C.trouble(P) .. C.trouble(O))
	end

	-- The strata of the frame the numbers are on.
	do
		local function host(strata, fault)
			local W = C.world()
			W.plateStrata, W.strataFault = strata, fault
			local font = C.hit(W, "nameplate1", "WOUND", "", 1)
			return font and font.owner.strata, W
		end
		local low, W1 = host("BACKGROUND")
		local high = host("HIGH")
		local withheld = host("HIGH", "secret")
		local failing = host("HIGH", "error")
		local top = host("DIALOG")
		local world, medium = host("WORLD"), host("LOW")
		check("combat text, the strata of the numbers: one above the plate's, or HIGH when the plate's cannot be read", low == "LOW" and high == "DIALOG" and withheld == "HIGH" and failing == "HIGH" and top == "DIALOG",
			tostring(low) .. " " .. tostring(high) .. " " .. tostring(withheld) .. " " .. tostring(failing) .. " " .. tostring(top))
		check("combat text, the strata of the numbers: a plate in WORLD leaves the frame at LOW, and a plate in LOW raises it to MEDIUM", world == "LOW" and medium == "MEDIUM", tostring(world) .. " " .. tostring(medium))
		local W = C.world()
		W.plateStrata = "HIGH"
		local font = C.hit(W, "nameplate1", "WOUND", "", 1)
		W.plateStrata = "BACKGROUND"
		C.hit(W, "nameplate2", "WOUND", "", 2)
		local quiet = C.quiet(W) and C.quiet(W1)
		check("combat text, a later plate with a lower strata: the frame is not lowered", font.owner.strata == "DIALOG" and has(W.slash("combat"), "Nameplate layer: BACKGROUND. Numbers layer: DIALOG."), W.slash("combat"))
		check("combat text, the strata: no violations, errors or messages", quiet, C.trouble(W))
	end

	-- A plate that goes while its number is in the air.
	do
		local W = C.world()
		local font = C.hit(W, "nameplate1", "WOUND", "", 412)
		local t0 = W.now
		C.draw(W, t0 + 0.25)
		local x, y = W.centre(font)
		W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		local x2, y2 = W.centre(font)
		check("combat text, a plate goes: the number is anchored to UIParent at the spot where it was", font.points[1][2] == W.env.UIParent and font.points[1][3] == "BOTTOMLEFT" and near(x, x2) and near(y, y2) and font.shown
			and has(W.slash("combat"), "Numbers kept after their nameplate went: 1. Removed with it: 0."), C.spot(font))
		C.draw(W, t0 + 0.5)
		local x3, y3 = W.centre(font)
		check("combat text, a plate goes: the number goes on moving, from where it was", near(x3, x) and near(y3, y + (100 * 0.5 - 80 * 0.25) - (100 * 0.25 - 80 * 0.0625)), g(y3))
		C.draw(W, t0 + 1.5001)
		check("combat text, a plate goes: the number ends on time", not font.shown and C.running(W) == 0)
		local V = C.world()
		local gone = C.hit(V, "nameplate1", "WOUND", "", 412)
		V.centreFault = "secret"
		V.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		V.centreFault = nil
		check("combat text, a plate goes and the game withholds the spot: the number is hidden and back in the pool", not gone.shown and C.running(V) == 0 and has(V.slash("combat"), "Numbers kept after their nameplate went: 0. Removed with it: 1."))
		check("combat text, and the pool gives it to the next number", C.hit(V, "nameplate2", "WOUND", "", 1) == gone)
		local N = C.world()
		local nowhere = C.hit(N, "nameplate1", "WOUND", "", 412)
		N.centreFault = "none"
		N.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		check("combat text, a plate goes and the game gives no spot: the number is hidden", not nowhere.shown and C.quiet(N), C.trouble(N))
		local O = C.world()
		local other = C.hit(O, "nameplate2", "WOUND", "", 1)
		O.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		check("combat text, another plate goes: the number stays on its own plate", other.points[1][2] == O.cplate2 and other.shown)
		local R = C.world()
		local mine = C.hit(R, "nameplate1", "WOUND", "", 1)
		R.fire("NAME_PLATE_UNIT_REMOVED", SECRET)
		check("combat text, a plate goes and the unit is withheld: every number on a plate stays where it is", mine.points[1][2] == R.env.UIParent and #R.violations == 0 and #R.errors == 0, C.trouble(R))
		local A = C.world()
		local away = C.hit(A, "nameplate1", "WOUND", "", 412)
		A.fire("NAME_PLATE_UNIT_ADDED", SECRET)
		local off = C.world(nil, { options = { ["combattext.enabled"] = false } })
		off.fire("NAME_PLATE_UNIT_ADDED", SECRET)
		check("combat text, a plate that gets a withheld unit: nothing is hidden, the module asks the game nothing about it and goes on", away.shown and not A.ns.IsStopped("combattext") and #A.errors == 0
			and #A.violations == #off.violations, C.trouble(A))
	end

	-- A plate that stops the numbers from being placed.
	do
		local W = C.world()
		W.pointFault = true
		local font = C.hit(W, "nameplate1", "WOUND", "", 412)
		check("combat text, the game refuses the place of a number: nothing is shown, the status counts it and the module goes on", font == nil and has(W.status(), "Numbers the game would not position: 1.")
			and not W.ns.IsStopped("combattext") and C.rows(W) == "1111", W.status())
		W.pointFault = nil
		check("combat text, and the next number is shown by the font string that was made, and no other", C.say(W, "nameplate1", "WOUND", "", 413) == "413" and C.rows(W) == "0000" and #W.addonFonts == 1)
		local alive = C.hit(W, "nameplate1", "WOUND", "", 414)
		W.pointFault = true
		C.draw(W, W.now + 0.1)
		check("combat text, the game refuses the place of numbers already shown: they are hidden, counted, and the module goes on", not alive.shown and has(W.status(), "Numbers the game would not position: 3.")
			and not W.ns.IsStopped("combattext") and C.running(W) == 0, W.status())
		W.pointFault = nil
	end

	-- Without a clock.
	do
		local W = C.world()
		W.env.GetTime = nil
		C.hit(W, "nameplate1", "WOUND", "", 412)
		check("combat text, a client without GetTime: no number, the rows stay the game's and nothing fails", #W.addonFonts == 0 and C.rows(W) == "1111" and C.writes(W) == 0 and C.quiet(W), C.trouble(W))
	end

	-- The choice of Numbers over enemies and the page's switch, with numbers in the air.
	do
		local W = C.world()
		local one = C.hit(W, "nameplate1", "WOUND", "", 1)
		local two = C.hit(W, "nameplate1", "WOUND", "", 2)
		W.ns.Set("combattext.source", "game")
		check("combat text, As the game has them: the numbers in the air are hidden, the four rows are the game's and later reports show nothing", not one.shown and not two.shown and C.rows(W) == "1111"
			and C.say(W, "nameplate1", "WOUND", "", 3) == "none" and C.noRecords(W) and C.running(W) == 0, C.rows(W))
		check("combat text, As the game has them: the status says nothing about numbers in front", not has(W.status(), "Numbers in front of nameplates") and W.line("Combat text") == "Combat text: on")
		W.ns.Set("combattext.source", "front")
		check("combat text, In front of nameplates again in the same session: the rows are \"0\" at once", C.rows(W) == "0000" and W.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.game == "1", C.rows(W))
		check("combat text, and the next report shows", C.say(W, "nameplate1", "WOUND", "", 4) == "4")
		local P = C.world()
		local shown = { C.hit(P, "nameplate1", "WOUND", "", 1), C.hit(P, "nameplate1", "WOUND", "", 2) }
		P.change("combattext.enabled", false)
		check("combat text, the page off with numbers in the air: they are hidden, the rows are the game's, nothing is remembered and later reports show nothing", not shown[1].shown and not shown[2].shown
			and C.rows(P) == "1111" and C.noRecords(P) and C.say(P, "nameplate1", "WOUND", "", 3) == "none" and P.line("Combat text") == "Combat text: off" and not has(P.status(), "Numbers in front"),
			P.status())
		P.change("combattext.enabled", true)
		check("combat text, and on again: the rows are \"0\" at once and the next report shows", C.rows(P) == "0000" and C.say(P, "nameplate1", "WOUND", "", 4) == "4")
		check("combat text, source and switch: no violations, errors or messages", C.quiet(W) and C.quiet(P), C.trouble(W) .. C.trouble(P))
		local G = C.world()
		G.openPanel()
		G.change("combattext.enabled", false)
		local greyed = true
		for _, key in ipairs({ "source", "font", "outline", "shadow", "pop", "height", "crit", "size", "spread", "movement", "partial", "units", "school", "own", "inStyle", "ownSize" }) do
			greyed = greyed and not G.enabled("combattext." .. key)
		end
		check("combat text, the page's switch is off: every other row of the page is greyed, and the switch is not", greyed and G.enabled("combattext.enabled"))
		G.change("combattext.enabled", true)
		check("combat text, the page's switch is on: the rows can be used", G.enabled("combattext.height") and G.enabled("combattext.school"))
	end

	-- Records of an earlier session.
	do
		local function saved(game, wrote)
			local records = {}
			for _, name in ipairs(C.switch) do
				records[name] = { game = game, wrote = wrote }
			end
			return { options = {}, cvars = records }
		end
		local cvars = {}
		for _, name in ipairs(C.switch) do
			cvars[name] = "0"
		end
		local W = C.world({ cvars = cvars }, saved("1", "0"))
		check("combat text, records with the written values in place: login makes no write, and the rows are \"0\" before any hit", C.writes(W) == 0 and C.rows(W) == "0000"
			and W.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.wrote == "0" and has(W.slash("combat"), "At login: the values written last session"), W.slash("combat"))
		local L = C.world(nil, saved("1", "0"))
		check("combat text, records with the game's values in place (written back at logout): login writes \"0\" before any hit, and remembers the game's value", C.rows(L) == "0000" and C.writes(L) == 4
			and C.write(L, 1).remembered == "1" and L.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.game == "1" and has(L.slash("combat"), "At login: the game's own values"), L.slash("combat"))
		local O = C.world({ cvars = cvars }, (function()
			local db = saved("1", "0")
			db.options["combattext.enabled"] = false
			return db
		end)())
		check("combat text, the page off and the written values in place: the frame of the module's own puts the game's values back at login and drops the records", C.rows(O) == "1111" and C.noRecords(O)
			and C.writes(O) == 4 and O.line("Combat text") == "Combat text: off", C.rows(O))
		local other = {}
		for _, name in ipairs(C.switch) do
			other[name] = "5"
		end
		local X = C.world({ cvars = other }, (function()
			local db = saved("1", "0")
			db.options["combattext.enabled"] = false
			return db
		end)())
		check("combat text, the page off and someone else's values in place: they stay, and the records are dropped", C.rows(X) == "5555" and C.noRecords(X) and C.writes(X) == 0)
		local R = C.world({ cvars = cvars }, (function()
			local db = saved("1", "0")
			db.cvars.junk = "x"
			db.cvars.floatingCombatTextPetMeleeDamage_v2 = { wrote = "0" }
			return db
		end)())
		check("combat text, damaged records are dropped: a text, and a record with no remembered value", R.env.FlatUIDB.cvars.junk == nil and R.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2 ~= nil and C.quiet(R), C.trouble(R))

		-- Which record proves that the rows were written: the first row's.
		local one = C.world({ cvars = cvars }, { options = {}, cvars = { floatingCombatTextCombatDamage_v2 = { game = "1", wrote = "0" } } })
		local two = C.world(nil, { options = {}, cvars = { floatingCombatTextCombatLogPeriodicSpells_v2 = { game = "1", wrote = "0" } } })
		check("combat text, a record of the first row proves the rows were written, and a record of the second does not", C.rows(one) == "0000" and C.rows(two) == "1111" and C.writes(two) == 0, C.rows(one) .. " " .. C.rows(two))

		-- A record whose written value is not the one in place is brought up to date, so that the page going off puts the game's value back.
		local stale = C.world({ cvars = cvars }, { options = {}, cvars = { floatingCombatTextCombatDamage_v2 = { game = "1", wrote = "5" } } })
		stale.ns.Set("combattext.enabled", false)
		check("combat text, a record with an older written value and the wanted value in place: the page off puts the game's value back", stale.cvars.floatingCombatTextCombatDamage_v2 == "1" and C.noRecords(stale),
			tostring(stale.cvars.floatingCombatTextCombatDamage_v2))

		-- A record of the game's own value as the written one has nothing to put back.
		local same = {}
		for _, name in ipairs(C.switch) do
			same[name] = "1"
		end
		local alike = C.world({ cvars = same }, saved("1", "1"))
		check("combat text, records whose written value is the game's: login says the values are the game's, and the rows are written", has(alike.slash("combat"), "At login: the game's own values") and C.rows(alike) == "0000",
			alike.slash("combat"))
		local quiet = C.world({ cvars = same }, (function()
			local db = saved("1", "1")
			db.options["combattext.enabled"] = false
			return db
		end)())
		check("combat text, the page off and records whose written value is the game's: nothing is written back, and the records are dropped", C.writes(quiet) == 0 and C.rows(quiet) == "1111" and C.noRecords(quiet))
	end

	-- Logout, other characters and profiles.
	do
		local W = C.world()
		C.hit(W, "nameplate1", "WOUND", "", 412)
		check("combat text, before logout: the rows are \"0\"", C.rows(W) == "0000")
		W.fire("PLAYER_LOGOUT")
		check("combat text, logout: each row holds the remembered string, and the records stay", C.rows(W) == "1111" and W.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.wrote == "0"
			and W.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.game == "1" and C.quiet(W), C.trouble(W))
		local N = C.world({ cvars = W.cvars }, W.env.FlatUIDB)
		check("combat text, the next login: the rows are \"0\" again before any hit, and the remembered strings are the same", C.rows(N) == "0000" and N.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.game == "1"
			and has(N.slash("combat"), "At login: the game's own values"), N.slash("combat"))
		local hand = C.world()
		C.hit(hand, "nameplate1", "WOUND", "", 412)
		hand.setCVarByPlayer("floatingCombatTextCombatDamage_v2", "7")
		hand.fire("PLAYER_LOGOUT")
		check("combat text, logout with a row changed by hand: that row is left as it is", hand.cvars.floatingCombatTextCombatDamage_v2 == "7" and hand.cvars.floatingCombatTextPetMeleeDamage_v2 == "1")

		-- Two characters share the variables and the saved variables, with two profiles.
		local A = C.world({ character = "Alice - Realm" })
		C.hit(A, "nameplate1", "WOUND", "", 412)
		A.ns.NewProfile("Quiet")
		A.ns.Set("combattext.enabled", false)
		A.ns.UseProfile("Default")
		check("combat text, two characters: the first has the page on and the rows \"0\"", C.rows(A) == "0000")
		local db = A.env.FlatUIDB
		db.profileOf["Bob - Realm"] = "Quiet"
		local B = C.world({ character = "Bob - Realm", cvars = A.cvars }, db)
		check("combat text, two characters: the second, with the page off, finds every row restored at login", C.rows(B) == "1111" and C.noRecords(B) and B.line("Combat text") == "Combat text: off", C.rows(B))

		-- A profile with the page off, and one with it on.
		local P = C.world()
		C.hit(P, "nameplate1", "WOUND", "", 412)
		P.ns.NewProfile("Quiet")
		P.ns.Set("combattext.enabled", false)
		check("combat text, the player changes to a profile with the page off: the rows go back, and later reports show nothing", C.rows(P) == "1111" and C.noRecords(P) and C.say(P, "nameplate1", "WOUND", "", 1) == "none")
		P.ns.UseProfile("Default")
		check("combat text, and back to the profile with the page on: the rows are \"0\" at once", C.rows(P) == "0000" and C.say(P, "nameplate1", "WOUND", "", 2) == "2")
		local text
		P.ns.UseProfile("Quiet")
		text = P.ns.ExportProfile()
		P.ns.UseProfile("Default")
		P.ns.UseProfile("Quiet")
		P.ns.Set("combattext.enabled", true)
		check("combat text, the page on in the profile Quiet: the rows are \"0\"", C.rows(P) == "0000")
		local imported, why = P.ns.ImportProfile(text)
		check("combat text, a profile with the page off is imported: every row is back at the remembered string", imported and C.rows(P) == "1111" and C.noRecords(P) and P.line("Combat text") == "Combat text: off", tostring(why) .. C.rows(P))
		P.ns.ResetProfile()
		check("combat text, a profile is reset: the page is on, and the rows are \"0\" again", C.rows(P) == "0000" and P.line("Combat text") == "Combat text: on")
		check("combat text, profiles: no violations, errors or messages", C.quiet(P) and C.quiet(A) and C.quiet(B), C.trouble(P) .. C.trouble(A))
	end

	-- A module that fails puts the game's rows back.
	do
		local W = C.world()
		C.hit(W, "nameplate1", "WOUND", "", 412)
		local font = W.addonFonts[1]
		local describe = W.ns.modules.combattext.events.UNIT_COMBAT
		W.ns.modules.combattext.events.UNIT_COMBAT = function() error("broken", 0) end
		W.fire("UNIT_COMBAT", "nameplate1", "WOUND", "", 1, 1)
		check("combat text, a handler that raises an error: the module stops, the rows are the game's and no number is left on screen", W.ns.IsStopped("combattext") and C.rows(W) == "1111" and not font.shown
			and C.noRecords(W) and has(W.status(), "Combat text: stopped. broken"), W.status())
		W.ns.modules.combattext.events.UNIT_COMBAT = describe
	end

	-- A read that is withheld.
	do
		local W = C.world({}, nil)
		local get = W.env.C_CVar.GetCVar
		W.env.C_CVar.GetCVar = function(name)
			if name == "floatingCombatTextPetMeleeDamage_v2" then
				return SECRET
			end
			return get(name)
		end
		C.hit(W, "nameplate1", "WOUND", "", 412)
		check("combat text, a variable the game withholds: it is skipped, the others are written and nothing fails", W.cvars.floatingCombatTextCombatDamage_v2 == "0" and W.cvars.floatingCombatTextPetMeleeDamage_v2 == "1"
			and W.cvars.floatingCombatTextPetSpellDamage_v2 == "0" and W.env.FlatUIDB.cvars.floatingCombatTextPetMeleeDamage_v2 == nil and C.quiet(W), C.trouble(W))
		local V = C.world()
		V.cvarFault = "secret"
		C.hit(V, "nameplate1", "WOUND", "", 412)
		check("combat text, every answer withheld: nothing is written and nothing fails", C.writes(V) == 0 and C.quiet(V) and C.noRecords(V), C.trouble(V))
	end

	-- A write the game refuses.
	do
		local W = C.world()
		W.combat = true
		W.cvarRefuseInCombat.floatingCombatTextPetMeleeDamage_v2 = true
		C.hit(W, "nameplate1", "WOUND", "", 412)
		local note = "floatingCombatTextPetMeleeDamage_v2: the game refused 0."
		check("combat text, a write refused in combat: the other rows are written and the status says so", C.rows(W) == "0010" and count(W.status(), note) == 1, C.rows(W))
		C.hit(W, "nameplate1", "WOUND", "", 413)
		W.ns.Set("combattext.partial", "off")
		W.ns.Set("combattext.partial", "word")
		check("combat text, and again after more changes: still the one line", count(W.status(), note) == 1 and W.env.FlatUIDB.cvars.floatingCombatTextPetMeleeDamage_v2 == nil, W.status())
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("combat text, after combat: the row is written and the line is gone", C.rows(W) == "0000" and not has(W.status(), "the game refused") and W.env.FlatUIDB.cvars.floatingCombatTextPetMeleeDamage_v2.game == "1",
			W.status())
		-- A second fight: the refusal is tried again at its end too.
		W.combat = true
		W.ns.Set("combattext.source", "game")
		check("combat text, a second write refused in combat: the row the game would not take is the only one left written", C.rows(W) == "1101" and has(W.status(), "floatingCombatTextPetMeleeDamage_v2: the game refused 1."), C.rows(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("combat text, and after that fight too the row is put back and the line is gone", C.rows(W) == "1111" and not has(W.status(), "the game refused"), W.status())
		local O = C.world()
		O.cvarRefuse.floatingCombatTextPetSpellDamage_v2 = true
		C.hit(O, "nameplate1", "WOUND", "", 412)
		check("combat text, a write refused out of combat: the line appears once, nothing waits for combat to end and no record is left for that row", count(O.status(), "floatingCombatTextPetSpellDamage_v2: the game refused 0.") == 1
			and C.writes(O) == 3 and O.env.FlatUIDB.cvars.floatingCombatTextPetSpellDamage_v2 == nil and C.rows(O) == "0001", O.status())
		O.combat = true
		O.combat = false
		O.fire("PLAYER_REGEN_ENABLED")
		check("combat text, and nothing is tried again after the fight", C.writes(O) == 3)
		O.ns.Set("combattext.source", "game")
		check("combat text, a line about a row the page no longer writes is gone", not has(O.status(), "the game refused") and C.rows(O) == "1111", O.status())
		O.ns.Set("combattext.source", "front")
		O.cvarRefuse.floatingCombatTextPetSpellDamage_v2 = nil
		O.ns.Set("combattext.partial", "off")
		check("combat text, and when the game takes it later, the line goes", C.rows(O) == "0000" and not has(O.status(), "the game refused"), O.status())
	end

	-- A value changed by hand.
	do
		local W = C.world()
		C.hit(W, "nameplate1", "WOUND", "", 412)
		W.setCVarByPlayer("floatingCombatTextCombatDamage_v2", "3")
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.fire("PLAYER_REGEN_ENABLED")
		check("combat text, a row changed by hand: nothing writes over it until a setting changes", W.cvars.floatingCombatTextCombatDamage_v2 == "3")
		W.ns.Set("combattext.partial", "off")
		check("combat text, and then the row is written again, with the value set by hand remembered as the one to put back", W.cvars.floatingCombatTextCombatDamage_v2 == "0"
			and W.env.FlatUIDB.cvars.floatingCombatTextCombatDamage_v2.game == "3", tostring(W.cvars.floatingCombatTextCombatDamage_v2))
		W.setCVarByPlayer("floatingCombatTextCombatDamage_v2", "4")
		W.change("combattext.enabled", false)
		check("combat text, a row changed by hand and the page switched off: the value set by hand stays", W.cvars.floatingCombatTextCombatDamage_v2 == "4" and W.cvars.floatingCombatTextPetMeleeDamage_v2 == "1"
			and C.noRecords(W))
	end

	-- Plain words in /flatui combat.
	do
		local W = C.world()
		local report = W.slash("combat")
		local old = { "Forbidden plates", "Aura answers withheld", "Signals heard", "Last decision", "Same hit twice", "Kinds of hit the game withheld", "Target only unchecked",
			"Amounts the game withheld", "No detail", "Raster:", "Nameplate strata", "Outline flags", "WorldFrame is", "No frame or plate", "keeps from interface mods", "would not give the look to" }
		local found = {}
		for _, word in ipairs(old) do
			if has(report, word) then
				found[#found + 1] = word
			end
		end
		check("combat words: /flatui combat uses none of the old labels", #found == 0, table.concat(found, ", ") .. " " .. report)
		check("combat words: the hit lines name your hits, casts and swings seen and the last hit",
			has(report, "Your hits: 0 shown, 0 left out. Casts and swings seen: 0. Auras the game would not tell about: 0. Last hit: none.")
				and has(report, "Friendly numbers: Both. Hit reports: 0 nameplate, 0 party or raid, 0 pet. Shown: 0. No frame or nameplate to show on: 0. Repeated reports skipped: 0. Target check failed: 0. Nameplates the game hides from interface mods: 0."), report)
		check("combat words: the layer, outline and size lines are in plain words",
			has(report, "Nameplate layer: none. Numbers layer: none.") and has(report, "Outline styles from the game:") and has(report, "Font size made at: 64.")
				and has(report, "Game world height is 768: the scroll areas are 240 long."), report)
	end

	-- The commands.
	do
		local W = C.world()
		local before = W.slash("combat")
		check("combat text, /flatui combat before a hit: each row with its value now, the client's default and what is wanted",
			before == table.concat({ "floatingCombatTextCombatDamage_v2: now 1, default 1, wanted no change", "floatingCombatTextCombatLogPeriodicSpells_v2: now 1, default 1, wanted no change",
				"floatingCombatTextPetMeleeDamage_v2: now 1, default 1, wanted no change", "floatingCombatTextPetSpellDamage_v2: now 1, default 1, wanted no change",
				"WorldTextScreenY_v2: now 0.015, default 0.0, wanted 0.015", "WorldTextCritScreenY_v2: now 0.015, default 0.0, wanted 0.015", "WorldTextScale_v2: now 1.4, default 1.000000, wanted 1.4", "Size of experience and other gains: Same as your text, not in use.",
				"WorldTextStartPosRandomness_v2: now 1.0, default 1.0, wanted 1.0", "WorldTextGravity_v2: now 0.500000, default 0.500000, wanted 0.500000",
				"floatingCombatTextCombatHealing_v2: now 1, default 1, wanted no change", "enableFloatingCombatText: now 0, default 0, wanted 0", "classicStyleWorldText: 0",
				"At login: nothing remembered", "Hit reports: 0 for nameplates, 0 for target.", "Shown: 0. No nameplate: 0. On friendly units: 0. Report unreadable: 0.", "Last hit report: none",
				"Your hits: 0 shown, 0 left out. Casts and swings seen: 0. Auras the game would not tell about: 0. Last hit: none.",
				"Friendly numbers: Both. Hit reports: 0 nameplate, 0 party or raid, 0 pet. Shown: 0. No frame or nameplate to show on: 0. Repeated reports skipped: 0. Target check failed: 0. Nameplates the game hides from interface mods: 0.",
				"Last friendly hit report: none", "Friendly nameplate variables: players not known, pets not known, minions not known, NPCs not known.",
				"The game's setting floatingCombatTextCombatHealing_v2 goes to 0 with the first friendly number. Changing Where friendly numbers show or Healing over friendly units, turning the page off, logging out and /flatui combat reset put it back.",
				"Nameplate layer: none. Numbers layer: none.", "Numbers kept after their nameplate went: 0. Removed with it: 0.", "Font: Fonts\\FRIZQT__.TTF, 64, flags none.",
				"Outline styles from the game: thick \"OUTLINE, THICK\", thin \"OUTLINE\".", "Font size made at: 64.", "Width of the last number: no number drawn yet.", "Hit reports for you: 0. Shown: 0.", "Last hit report for you: none", "Hits shown in the Outgoing scroll area: 0.", "Start of your text: 790, 510.",
				"Start of your hits: 1130, 510.", "Game world height is 768: the scroll areas are 240 long." }, "\n"), before)
		local D = C.world(nil, nil, function(X)
			X.cvarDefaults.floatingCombatTextCombatDamage_v2 = "9"
			X.cvarDefaults.floatingCombatTextCombatLogPeriodicSpells_v2 = ""
			X.cvarDefaults.enableFloatingCombatText = ""
		end)
		check("combat text, /flatui combat shows the default the client answers, or the one of its list when it answers nothing", has(D.slash("combat"), "floatingCombatTextCombatDamage_v2: now 1, default 9, wanted no change\n")
			and has(D.slash("combat"), "floatingCombatTextCombatLogPeriodicSpells_v2: now 1, default 1, wanted no change\n") and has(D.slash("combat"), "enableFloatingCombatText: now 0, default 0, wanted 0\n"), D.slash("combat"))
		C.hit(W, "nameplate1", "WOUND", "GLANCING", 412, 1)
		local after = W.slash("combat")
		check("combat text, /flatui combat after a hit: the rows are written, and the report names the last hit",
			has(after, "floatingCombatTextCombatDamage_v2: now 0, default 1, wanted 0\n") and has(after, "Hit reports: 1 for nameplates, 0 for target.") and has(after, "Shown: 1. No nameplate: 0. On friendly units: 0. Report unreadable: 0.")
			and has(after, "Last hit report: nameplate1, WOUND, GLANCING, 412, school 1\n") and has(after, "Nameplate layer: BACKGROUND. Numbers layer: LOW."), after)
		C.hit(W, "nameplate1", "WOUND", SECRET, SECRET, SECRET)
		check("combat text, the last hit report with withheld parts says withheld", has(W.slash("combat"), "Last hit report: nameplate1, WOUND, withheld, withheld, school withheld\n"), W.slash("combat"))
		W.change("combattext.enabled", false)
		check("combat text, /flatui combat with the page off: every row ends with wanted no change", count(W.slash("combat"), "wanted no change") == 11 and has(W.slash("combat"), "default 1, wanted no change\nenableFloatingCombatText: now 0, default 0, wanted no change\nclassicStyleWorldText"))
		check("combat text, /flatui combat anything else prints the four help lines", W.slash("combat bogus") == "/flatui combat - the game's combat number settings: now, default, wanted\n/flatui combat test - sample numbers for you, over your target and over friendly units\n"
			.. "/flatui combat reset - the game's defaults, and Place combat numbers off\n/flatui combat trace - each hit report and signal of yours in chat, until you type it again")
		local N = newWorld()
		N.login()
		check("combat text, /flatui combat in a client without the variables: each row is not in this client", count(N.slash("combat"), "not in this client") == 12, N.slash("combat"))
	end

	-- /flatui combat test.
	do
		-- The number font strings of one layer, in the order they were made: the font strings that hold a word after a number are left out.
		local function numbers(W, strata)
			local list = {}
			for _, font in ipairs(W.addonFonts) do
				local p = font.points[1]
				local word = p and p[1] == "LEFT" and p[3] == "RIGHT" and type(p[2]) == "table" and p[2].kind == "FontString"
				if font.owner.strata == strata and not word then
					list[#list + 1] = font
				end
			end
			return list
		end
		local W = C.world()
		W.units.target = nil
		local said = W.slash("combat test")
		check("combat text, /flatui combat test with no target: the first sample for you is shown at once, and the line says what the rest needs", said == "Target an enemy with a nameplate to see numbers over it.\nTarget a friendly unit with a nameplate, or join a group, to see numbers over friendly units."
			and #numbers(W, "MEDIUM") == 1 and numbers(W, "MEDIUM")[1].text == "-412", said)
		for _ = 1, 4 do
			W.advance(0.25)
		end
		local texts, tall = {}, {}
		for index, font in ipairs(numbers(W, "MEDIUM")) do
			texts[index] = font.text
			tall[index] = font.textHeight
		end
		local own = numbers(W, "MEDIUM")
		check("combat text, /flatui combat test: five samples for you a quarter of a second apart, the second critical and purple, the fourth a dodge and the fifth a gain", table.concat(texts, "|") == "-412|-824|+300|(Dodge)|+20"
			and C.colour(own[2]) == "0.79,0.3,0.85" and own[2].textHeight == 31.25 and C.colour(own[5]) == "0.41,0.8,0.94" and own[1].textHeight == 25, table.concat(texts, "|"))
		check("combat text, /flatui combat test: the samples for you are on the frame for the player, in front of the game's own text", own[1].owner.strata == "MEDIUM" and own[1].owner == own[5].owner)
		local E = C.world()
		check("combat text, /flatui combat test: with a target it prints nothing", E.slash("combat test") == "Target a friendly unit with a nameplate, or join a group, to see numbers over friendly units." and #E.addonFonts == 3
			and numbers(E, "MEDIUM")[1].text == "-412" and numbers(E, "LOW")[1].text == "412" and numbers(E, "MEDIUM")[1].owner.strata == "MEDIUM")
		E.advance(0.25)
		check("combat text, /flatui combat test: a quarter of a second later the second sample of each kind is shown", #numbers(E, "MEDIUM") == 2 and numbers(E, "MEDIUM")[2].text == "-824" and #numbers(E, "LOW") == 2 and numbers(E, "LOW")[2].text == "412 (Glancing)")
		E.advance(0.25)
		E.advance(0.25)
		E.advance(0.25)
		local mine, theirs = {}, {}
		for _, font in ipairs(numbers(E, "MEDIUM")) do
			mine[#mine + 1] = font.text
		end
		for _, font in ipairs(numbers(E, "LOW")) do
			theirs[#theirs + 1] = font.text
		end
		check("combat text, /flatui combat test: five samples for you and four over the target, the third over the target critical", table.concat(mine, "|") == "-412|-824|+300|(Dodge)|+20"
			and table.concat(theirs, "|") == "412|412 (Glancing)|824|(Dodge)" and numbers(E, "LOW")[3].textHeight == 42 and numbers(E, "MEDIUM")[1].textHeight == 25, table.concat(mine, "|") .. " " .. table.concat(theirs, "|"))
		check("combat text, /flatui combat test: the samples are no hit report and the rows stay the game's", C.rows(E) == "1111" and C.writes(E) == 0 and has(E.status(), C.enter) and has(E.status(), C.own)
			and has(E.slash("combat"), "Hit reports: 0 for nameplates, 0 for target.") and has(E.slash("combat"), "Shown: 0.") and has(E.slash("combat"), "Hit reports for you: 0. Shown: 0."), E.status())
		local T = C.world()
		T.ns.Set("combattext.own", "take")
		T.slash("combat test")
		for _ = 1, 4 do
			T.advance(0.25)
		end
		local taken = {}
		for _, font in ipairs(numbers(T, "MEDIUM")) do
			taken[#taken + 1] = font.text
		end
		check("combat text, /flatui combat test with Damage and healing you take: three samples for you", table.concat(taken, "|") == "-412|-824|+300", table.concat(taken, "|"))
		local F = C.world()
		F.ns.Set("combattext.own", "off")
		local off = F.slash("combat test")
		F.advance(0.25)
		check("combat text, /flatui combat test with Combat text for you off: it says so, and the samples over the target are shown", off == "Combat text for you is off.\nTarget a friendly unit with a nameplate, or join a group, to see numbers over friendly units." and #F.addonFonts == 2 and F.addonFonts[1].text == "412"
			and F.addonFonts[1].owner.strata == "LOW", off)
		F.units.target = nil
		check("combat text, and with no target too: both lines", F.slash("combat test") == "Combat text for you is off.\nTarget an enemy with a nameplate to see numbers over it.\nTarget a friendly unit with a nameplate, or join a group, to see numbers over friendly units.")
		F.ns.Set("combattext.own", "more")
		F.ns.Set("combattext.source", "game")
		F.units.target = F.cplate
		check("combat text, /flatui combat test with As the game has them: the samples for you and the line", F.slash("combat test") == "Numbers over enemies is set to As the game has them.\nTarget a friendly unit with a nameplate, or join a group, to see numbers over friendly units." and #numbers(F, "MEDIUM") == 1 and #F.addonFonts == 4)
		F.ns.Set("combattext.enabled", false)
		check("combat text, /flatui combat test with the page off: it says so and shows nothing more", F.slash("combat test") == "Place combat numbers is off." and #F.addonFonts == 4)
		check("combat text, /flatui combat test: no violations or errors", #W.violations == 0 and #W.errors == 0 and #E.violations == 0 and #E.errors == 0 and #T.violations == 0 and #T.errors == 0 and #F.errors == 0, C.trouble(W))
		local V = C.world({}, nil)
		V.env.C_Timer = nil
		V.ns.Set("combattext.friend", "off")
		V.slash("combat TEST")
		check("combat text, /flatui combat test without a timer: the samples are shown at once", #numbers(V, "MEDIUM") == 5 and #numbers(V, "LOW") == 4 and #V.violations == 0 and #V.errors == 0 and table.concat(V.out, "|") == "Where friendly numbers show is Off.", C.trouble(V))
	end

	-- /flatui combat reset.
	do
		local W = C.world({ cvars = { floatingCombatTextPetMeleeDamage_v2 = "0" } })
		C.hit(W, "nameplate1", "WOUND", "", 412)
		local said = W.slash("combat reset")
		check("combat text, /flatui combat reset: the page is off, every row holds the client's default, the records are gone and the lines say what changed",
			said == "floatingCombatTextPetMeleeDamage_v2: 1\nPlace combat numbers: off. The game's defaults are back." and not W.ns.Get("combattext.enabled") and C.rows(W) == "1111"
			and C.noRecords(W) and C.running(W) == 0, said)
		check("combat text, /flatui combat reset: the page shows as off, and later reports show nothing", W.line("Combat text") == "Combat text: off" and C.say(W, "nameplate1", "WOUND", "", 1) == "none")
		check("combat text, /flatui combat reset a second time: only the closing line", W.slash("combat reset") == "Place combat numbers: off. The game's defaults are back.")
		local R = C.world()
		C.hit(R, "nameplate1", "WOUND", "", 412)
		R.cvarRefuse.floatingCombatTextPetSpellDamage_v2 = true
		local refused = R.slash("combat reset")
		check("combat text, /flatui combat reset when the game refuses a row: the line names the row, and the records are dropped all the same", refused == "floatingCombatTextPetSpellDamage_v2: the game refused 1.\nPlace combat numbers: off. The game did not take 1 of the defaults."
			and C.noRecords(R) and R.cvars.floatingCombatTextPetSpellDamage_v2 == "0", refused)
		check("combat text, /flatui combat reset: no violations or errors", #W.violations == 0 and #W.errors == 0, C.trouble(W))
	end

	-- Words on the screen.
	do
		local W = C.world()
		local screen = {}
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == "combattext" then
				screen[#screen + 1] = page.label
				for _, item in ipairs(page) do
					screen[#screen + 1] = item.label or item.section
					screen[#screen + 1] = item.tip
					for _, choice in ipairs(item.choices or {}) do
						-- The name of the one style that is not Classic is the name of the addon, and so is the name of the numbers of the addon in a group.
						if not ((item.key == "style" or item.key == "group") and choice[1] == "flat") then
							screen[#screen + 1] = choice[2]
						end
					end
				end
			end
		end
		local function take(text)
			for line in (text .. "\n"):gmatch("([^\n]*)\n") do
				if not line:find("^Flat UI ") then
					screen[#screen + 1] = line
				end
			end
		end
		W.units.target = nil
		take(W.slash("combat"))
		take(W.slash("combat bogus"))
		take(W.slash("combat test"))
		W.units.target = W.cplate
		C.hit(W, "nameplate1", "WOUND", "GLANCING", SECRET, SECRET)
		W.pointFault = true
		C.hit(W, "nameplate1", "WOUND", "", 1)
		W.pointFault = nil
		W.cvarRefuse.floatingCombatTextPetSpellDamage_v2 = true
		W.ns.Set("combattext.partial", "off")
		W.ns.Set("combattext.partial", "word")
		take(W.status())
		take(W.slash("combat"))
		W.ns.Set("combattext.source", "game")
		take(W.slash("combat test"))
		W.ns.Set("combattext.enabled", false)
		take(W.slash("combat test"))
		take(W.slash("combat reset"))
		local found, banned = {}, { "carries", "carry", "sits", "lives in", "lands", "runs through", "ensure", "simply", "easily", "flat ui", "addon", "the system", "\226\128\148", "\226\128\147" }
		for _, text in ipairs(screen) do
			for _, word in ipairs(banned) do
				-- The name of the choice "Flat UI numbers" is an on-screen name and may stand in a tip.
				if text:gsub("Flat UI numbers", ""):lower():find(word, 1, true) then
					found[#found + 1] = word .. " in " .. text
				end
			end
		end
		check("combat text, every label, tip, choice, line and note: none of the banned words, no dash, and nothing names the addon", #found == 0 and #screen > 60, #screen .. " " .. table.concat(found, " | "))
	end
	-- The game's variables for the position, size and motion of its own numbers follow the page.
	C.names = { "WorldTextScreenY_v2", "WorldTextCritScreenY_v2", "WorldTextScale_v2", "WorldTextStartPosRandomness_v2", "WorldTextGravity_v2" }
	-- The five variables as one text, in order: height, height of critical hits, size, spread, movement.
	function C.wt(W)
		local out = {}
		for index, name in ipairs(C.names) do
			out[index] = tostring(W.cvars[name])
		end
		return table.concat(out, ",")
	end
	C.game = "0.0,0.0,1.000000,1.0,0.500000"
	C.picks = "0.015,0.015,1.4,1.0,0.500000"
	-- The record of a variable as "game wrote", or "none".
	function C.record(W, name)
		local rec = W.env.FlatUIDB.cvars and W.env.FlatUIDB.cvars[name]
		return rec and (tostring(rec.game) .. " " .. tostring(rec.wrote)) or "none"
	end

	-- Login with the picks.
	do
		local W = C.world()
		check("combat text variables, login with the picks (60, 140%, Same height, Loose, Rise and fall): height and size are written, spread and movement are left, and exactly three writes were made",
			C.wt(W) == C.picks and #W.cvarWrites == 3 and W.cvarWrites[1].name == "WorldTextScreenY_v2" and W.cvarWrites[2].name == "WorldTextCritScreenY_v2" and W.cvarWrites[3].name == "WorldTextScale_v2"
			and W.cvarWrites[1].value == "0.015" and W.cvarWrites[3].value == "1.4", C.wt(W))
		check("combat text variables, login with the picks: the four switch rows are still the game's, and spread and movement have no record", C.rows(W) == "1111" and C.record(W, "WorldTextStartPosRandomness_v2") == "none"
			and C.record(W, "WorldTextGravity_v2") == "none" and C.noRecords(W))
		check("combat text variables, login with the picks: each of the three records held the game's string at the moment SetCVar was called",
			W.cvarWrites[1].remembered == "0.0" and W.cvarWrites[2].remembered == "0.0" and W.cvarWrites[3].remembered == "1.000000")
		check("combat text variables, login with the picks: the records are the game's string and the written one", C.record(W, "WorldTextScreenY_v2") == "0.0 0.015" and C.record(W, "WorldTextCritScreenY_v2") == "0.0 0.015"
			and C.record(W, "WorldTextScale_v2") == "1.000000 1.4", C.record(W, "WorldTextScale_v2"))
		check("combat text variables, login with the picks: nothing is said, and the status has no note", C.quiet(W) and has(W.status(), "Combat text: on\n" .. C.enter .. "\n" .. C.friend .. "\n" .. C.own .. "\nAction bars"), W.status())
	end

	-- The game's own values are written as the client's own strings.
	do
		local W = C.world()
		W.ns.Set("combattext.height", 40)
		check("combat text variables, height 40: both rows hold the client's string character for character, and their records are gone", W.cvars.WorldTextScreenY_v2 == "0.0" and W.cvars.WorldTextCritScreenY_v2 == "0.0"
			and C.record(W, "WorldTextScreenY_v2") == "none" and C.record(W, "WorldTextCritScreenY_v2") == "none" and C.record(W, "WorldTextScale_v2") == "1.000000 1.4", C.wt(W))
		W.ns.Set("combattext.size", 100)
		check("combat text variables, size 100%: the row holds the client's string character for character, and no record is left", W.cvars.WorldTextScale_v2 == "1.000000" and W.env.FlatUIDB.cvars == nil and C.wt(W) == C.game, C.wt(W))
		local D = C.world(nil, nil, function(X)
			X.cvarDefaults.WorldTextScreenY_v2 = "0"
		end)
		D.ns.Set("combattext.height", 40)
		check("combat text variables, the client answers \"0\" for the default of the height: height 40 writes \"0\"", D.cvars.WorldTextScreenY_v2 == "0" and D.cvars.WorldTextCritScreenY_v2 == "0.0" and C.record(D, "WorldTextScreenY_v2") == "none", C.wt(D))
		-- A record whose game value is the one the page wants, with that value in place, has nothing to put back.
		local E = C.world(nil, { options = { ["combattext.height"] = 40, ["combattext.size"] = 100 }, cvars = { WorldTextScreenY_v2 = { game = "0.0", wrote = "0.015" } } })
		check("combat text variables, a record whose game value is the wanted one and is in place: the record is dropped at login and nothing is written", E.env.FlatUIDB.cvars == nil and #E.cvarWrites == 0
			and C.wt(E) == C.game, C.wt(E))
		local N = C.world({ without = { ["C_CVar.GetCVarDefault"] = true } })
		N.ns.Set("combattext.height", 40)
		N.ns.Set("combattext.size", 100)
		check("combat text variables, a client with no GetCVarDefault: the strings of its list are used", C.wt(N) == C.game and N.env.FlatUIDB.cvars == nil and C.quiet(N), C.wt(N))
	end

	-- Height above the enemy, at each of its positions.
	do
		local W = C.world()
		local wrong = {}
		for height = 0, 100, 5 do
			W.ns.Set("combattext.height", height)
			local want = (height - 40) / 5 * 0.00375
			if not (near(tonumber(W.cvars.WorldTextScreenY_v2), want, 1e-9) and near(tonumber(W.cvars.WorldTextCritScreenY_v2), want, 1e-9)) then
				wrong[#wrong + 1] = height .. "=" .. tostring(W.cvars.WorldTextScreenY_v2)
			end
		end
		check("combat text variables, height at each of its 21 positions: (height - 40) / 5 x 0.00375 every time", #wrong == 0, table.concat(wrong, " "))
		local text = {}
		for _, height in ipairs({ 0, 5, 35, 40, 45, 60, 100 }) do
			W.ns.Set("combattext.height", height)
			text[#text + 1] = W.cvars.WorldTextScreenY_v2
		end
		check("combat text variables, height 0, 5, 35, 40, 45, 60 and 100 are written as -0.03, -0.02625, -0.00375, 0.0, 0.00375, 0.015 and 0.045", table.concat(text, " ") == "-0.03 -0.02625 -0.00375 0.0 0.00375 0.015 0.045",
			table.concat(text, " "))
		check("combat text variables, every 5 points is the same step across the range", (function()
			local steps = {}
			for height = 0, 95, 5 do
				W.ns.Set("combattext.height", height)
				local low = tonumber(W.cvars.WorldTextScreenY_v2)
				W.ns.Set("combattext.height", height + 5)
				steps[#steps + 1] = tonumber(W.cvars.WorldTextScreenY_v2) - low
			end
			for _, step in ipairs(steps) do
				if not near(step, 0.00375, 1e-9) then
					return false
				end
			end
			return #steps == 20
		end)())
	end

	-- Critical hits.
	do
		local W = C.world()
		local seen = {}
		for _, pair in ipairs({ { 0, "-0.0175" }, { 40, "0.0125" }, { 60, "0.0275" }, { 100, "0.0575" } }) do
			W.ns.Set("combattext.crit", "same")
			W.ns.Set("combattext.height", pair[1])
			local plain = W.cvars.WorldTextScreenY_v2
			W.ns.Set("combattext.crit", "higher")
			seen[#seen + 1] = W.cvars.WorldTextCritScreenY_v2 .. (W.cvars.WorldTextScreenY_v2 == plain and "" or "!")
			W.ns.Set("combattext.crit", "same")
			seen[#seen + 1] = tostring(W.cvars.WorldTextCritScreenY_v2 == W.cvars.WorldTextScreenY_v2)
		end
		check("combat text variables, critical hits on Higher at heights 0, 40, 60 and 100: the row is -0.0175, 0.0125, 0.0275 and 0.0575, the height is unchanged by the choice, and Same height gives the same number",
			table.concat(seen, " ") == "-0.0175 true 0.0125 true 0.0275 true 0.0575 true", table.concat(seen, " "))
	end

	-- Size, spread and movement.
	do
		local W = C.world()
		W.ns.Set("combattext.size", 60)
		local low = W.cvars.WorldTextScale_v2
		W.ns.Set("combattext.size", 160)
		check("combat text variables, size 60% and 160%: 0.6 and 1.6", low == "0.6" and W.cvars.WorldTextScale_v2 == "1.6", low .. " " .. W.cvars.WorldTextScale_v2)
		W.ns.Set("combattext.spread", "tight")
		local tight = W.cvars.WorldTextStartPosRandomness_v2
		check("combat text variables, spread Tight: 0.0, with a record of the game's 1.0", tight == "0.0" and C.record(W, "WorldTextStartPosRandomness_v2") == "1.0 0.0", tight)
		W.ns.Set("combattext.spread", "loose")
		check("combat text variables, and back to Loose: 1.0 and no record left", W.cvars.WorldTextStartPosRandomness_v2 == "1.0" and C.record(W, "WorldTextStartPosRandomness_v2") == "none")
		W.ns.Set("combattext.movement", "up")
		local up = W.cvars.WorldTextGravity_v2
		check("combat text variables, movement Straight up: 0.0, with a record of the game's 0.500000", up == "0.0" and C.record(W, "WorldTextGravity_v2") == "0.500000 0.0", up)
		W.ns.Set("combattext.movement", "fall")
		check("combat text variables, and back to Rise and fall: 0.500000 and no record left", W.cvars.WorldTextGravity_v2 == "0.500000" and C.record(W, "WorldTextGravity_v2") == "none")
		local before = #W.cvarWrites
		local names = {}
		for _, size in ipairs({ 130, 120, 110, 100, 90 }) do
			local was = #W.cvarWrites
			W.change("combattext.size", size)
			names[#names + 1] = (#W.cvarWrites - was) .. W.cvarWrites[#W.cvarWrites].name
		end
		check("combat text variables, a slider dragged through five steps: one write to the variable it drives at each, and none to any other", table.concat(names, " ") == string.rep("1WorldTextScale_v2 ", 4) .. "1WorldTextScale_v2"
			and #W.cvarWrites == before + 5, table.concat(names, " "))
		check("combat text variables, and the last step leaves 0.9", W.cvars.WorldTextScale_v2 == "0.9" and C.record(W, "WorldTextScale_v2") == "1.000000 0.9")
	end

	-- Size of experience and other gains.
	do
		local G = { var = "WorldTextScale_v2" }
		function G.after(W, own, gain, size)
			W.ns.Set("combattext.ownSize", own)
			W.ns.Set("combattext.gainSize", gain)
			W.ns.Set("combattext.size", size)
			C.hit(W, "nameplate1", "WOUND", "", 412)
			return W.cvars[G.var]
		end
		local row
		for _, page in ipairs(C.world().ns.PAGES) do
			if page.key == "combattext" then
				for _, item in ipairs(page) do
					if item.key == "gainSize" then
						row = item
					end
				end
			end
		end
		local words = {}
		for _, choice in ipairs(row and row.choices or {}) do
			words[#words + 1] = choice[1] .. "=" .. choice[2]
		end
		check("gainsize: the row has its key, label, tip, default and show rule", row ~= nil and row.kind == "choice" and row.default == "own" and row.label == "Size of experience and other gains"
			and row.tip == "Text the game draws near you, such as experience." and row.needs == "source" and row.needsIn[1] == "front" and #row.needsIn == 1)
		check("gainsize: the four choices in their words", table.concat(words, "|") == "own=Same as your text|smaller=Smaller than your text|game=The game's own size|enemy=Same as numbers over enemies", table.concat(words, "|"))
		local W = C.world()
		check("gainsize: before a hit at the defaults the variable holds 1.4", W.cvars[G.var] == "1.4" and C.wt(W) == C.picks, C.wt(W))
		local text = W.slash("combat")
		check("gainsize: /flatui combat names the choice before a hit", has(text, "Size of experience and other gains: Same as your text, not in use."), text)
		C.hit(W, "nameplate1", "WOUND", "", 412)
		check("gainsize: after the first hit at the defaults the variable holds the game's string and its record is gone", W.cvars[G.var] == "1.000000" and C.record(W, G.var) == "none", W.cvars[G.var] .. " " .. C.record(W, G.var))
		check("gainsize: /flatui combat names the choice in use", has(W.slash("combat"), "WorldTextScale_v2: now 1.000000, default 1.000000, wanted 1.000000\nSize of experience and other gains: Same as your text.\n"), W.slash("combat"))
		local named = {}
		for _, choice in ipairs(row.choices) do
			W.ns.Set("combattext.gainSize", choice[1])
			named[#named + 1] = has(W.slash("combat"), "Size of experience and other gains: " .. choice[2] .. "." .. "\n") and "yes" or "no"
		end
		check("gainsize: /flatui combat names each of the four choices in the choice's own words", table.concat(named, " ") == "yes yes yes yes", table.concat(named, " "))
		W.ns.Set("combattext.gainSize", "smaller")
		check("gainsize: Smaller than your text writes 0.75", W.cvars[G.var] == "0.75" and C.record(W, G.var) == "1.000000 0.75", W.cvars[G.var])
		W.ns.Set("combattext.ownSize", 150)
		check("gainsize: your text at 150 writes 1.125 with Smaller", W.cvars[G.var] == "1.125", W.cvars[G.var])
		W.ns.Set("combattext.gainSize", "own")
		check("gainsize: your text at 150 writes 1.5 with Same as your text", W.cvars[G.var] == "1.5", W.cvars[G.var])
		W.ns.Set("combattext.gainSize", "game")
		check("gainsize: The game's own size writes the client's string with your text at 150", W.cvars[G.var] == "1.000000" and C.record(W, G.var) == "none", W.cvars[G.var])
		W.ns.Set("combattext.gainSize", "enemy")
		check("gainsize: Same as numbers over enemies writes Size, 1.4", W.cvars[G.var] == "1.4", W.cvars[G.var])
		W.ns.Set("combattext.size", 200)
		check("gainsize: and follows Size, 2.0", W.cvars[G.var] == "2.0", W.cvars[G.var])
		local H = C.world()
		H.ns.Set("combattext.ownSize", 50)
		H.ns.Set("combattext.gainSize", "smaller")
		C.hit(H, "nameplate1", "WOUND", "", 412)
		check("gainsize: a text of 50 with Smaller writes 0.375", H.cvars[G.var] == "0.375", H.cvars[G.var])
		local A = C.world()
		A.ns.Set("combattext.source", "game")
		A.ns.Set("combattext.gainSize", "smaller")
		C.hit(A, "nameplate1", "WOUND", "", 412)
		check("gainsize: Numbers over enemies As the game has them: Size drives the variable whatever the choice holds", A.cvars[G.var] == "1.4", A.cvars[G.var])
		local M = C.world(nil, { options = { ["combattext.whose"] = "mine" } })
		M.ns.Set("combattext.gainSize", "smaller")
		check("gainsize: Whose hits Every hit while you attack with no cast event: Size drives the variable", M.cvars[G.var] == "1.4", M.cvars[G.var])
		local O = C.world()
		C.hit(O, "nameplate1", "WOUND", "", 412)
		O.ns.Set("combattext.enabled", false)
		check("gainsize: the page off puts the game's value back", O.cvars[G.var] == "1.000000" and C.record(O, G.var) == "none", O.cvars[G.var])
	end

	-- The page goes off and on with everything changed.
	do
		local W = C.world()
		C.hit(W, "nameplate1", "WOUND", "", 412)
		W.ns.Set("combattext.height", 20)
		W.ns.Set("combattext.crit", "higher")
		W.ns.Set("combattext.gainSize", "enemy")
		W.ns.Set("combattext.size", 80)
		W.ns.Set("combattext.spread", "tight")
		W.ns.Set("combattext.movement", "up")
		local changed = C.wt(W) .. "|" .. C.rows(W)
		check("combat text variables, every setting changed and the four switch rows written", changed == "-0.015,-0.0025,0.8,0.0,0.0|0000", changed)
		W.ns.Set("combattext.enabled", false)
		check("combat text variables, the page off: all nine variables hold the remembered strings character for character, and the records are gone", C.wt(W) == C.game .. "" and C.rows(W) == "1111"
			and W.env.FlatUIDB.cvars == nil, C.wt(W) .. "|" .. C.rows(W))
		W.ns.Set("combattext.enabled", true)
		check("combat text variables, and on again: the same values are written again", C.wt(W) .. "|" .. C.rows(W) == changed, C.wt(W) .. "|" .. C.rows(W))
		-- Reset page sets every setting of the page to its default.
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == "combattext" then
				for _, item in ipairs(page) do
					if item.key then
						W.ns.Set("combattext." .. item.key, item.default)
					end
				end
			end
		end
		check("combat text variables, Reset page: the variables hold the values of the picks, and the size of the gains is the game's", C.wt(W) == "0.015,0.015,1.000000,1.0,0.500000" and C.rows(W) == "0000", C.wt(W))
	end

	-- A write refused in combat, and out of combat.
	do
		local W = C.world({ combat = true }, nil, function(X)
			X.cvarRefuseInCombat.WorldTextScale_v2 = true
		end)
		local note = "WorldTextScale_v2: the game refused 1.4."
		W.ns.Set("combattext.height", 70)
		W.ns.Set("combattext.spread", "tight")
		check("combat text variables, a write refused in combat: the other variables are written, the status has the line once, and no record of that variable is left", C.wt(W) == "0.0225,0.0225,1.000000,0.0,0.500000"
			and count(W.status(), note) == 1 and C.record(W, "WorldTextScale_v2") == "none", C.wt(W) .. " " .. W.status())
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("combat text variables, after combat: the variable holds 1.4 and the line is gone", W.cvars.WorldTextScale_v2 == "1.4" and not has(W.status(), "the game refused") and C.record(W, "WorldTextScale_v2") == "1.000000 1.4",
			W.status())
		local O = C.world(nil, nil, function(X)
			X.cvarRefuse.WorldTextScale_v2 = true
		end)
		local writes = #O.cvarWrites
		O.fire("PLAYER_REGEN_ENABLED")
		O.ns.Set("combattext.height", 70)
		check("combat text variables, a write refused out of combat: the line appears once, nothing waits for the end of combat and no record is left", count(O.status(), note) == 1 and writes == 2
			and #O.cvarWrites == 4 and C.record(O, "WorldTextScale_v2") == "none", O.status())
		O.ns.Set("combattext.enabled", false)
		check("combat text variables, and with the page off the line is gone and the other variables are back", not has(O.status(), "the game refused") and C.wt(O) == C.game, O.status())
	end

	-- A value the game changes.
	do
		local W = C.world(nil, nil, function(X)
			X.cvarClamp.WorldTextScale_v2 = function(value)
				return tonumber(value) > 1.5 and "1.5" or value
			end
		end)
		local note = "WorldTextScale_v2: the game keeps 1.5 for 1.6."
		W.ns.Set("combattext.size", 160)
		check("combat text variables, the client keeps 1.5 when 1.6 is written: the status says so and the record's written value is 1.5", W.cvars.WorldTextScale_v2 == "1.5" and count(W.status(), note) == 1
			and C.record(W, "WorldTextScale_v2") == "1.000000 1.5", W.status())
		W.ns.Set("combattext.height", 50)
		check("combat text variables, and after another change it is still the same line, not a refusal", count(W.status(), note) == 1 and not has(W.status(), "refused") and C.record(W, "WorldTextScale_v2") == "1.000000 1.5",
			W.status())
		W.ns.Set("combattext.size", 150)
		check("combat text variables, a size the game takes: the line is gone", W.cvars.WorldTextScale_v2 == "1.5" and not has(W.status(), "the game keeps"), W.status())
		W.ns.Set("combattext.size", 160)
		W.ns.Set("combattext.enabled", false)
		check("combat text variables, the page off puts the game's string back", W.cvars.WorldTextScale_v2 == "1.000000" and not has(W.status(), "the game keeps") and C.wt(W) == C.game, C.wt(W))
	end

	-- Profiles.
	do
		local W = C.world()
		W.ns.NewProfile("Quiet")
		W.ns.Set("combattext.enabled", false)
		check("combat text variables, the player changes to a profile whose page is off: every variable is back at its remembered string", C.wt(W) == C.game and W.env.FlatUIDB.cvars == nil)
		W.ns.UseProfile("Default")
		check("combat text variables, and back: the wanted values are written again", C.wt(W) == C.picks)
		W.ns.NewProfile("Far")
		W.ns.Set("combattext.height", 80)
		W.ns.Set("combattext.size", 100)
		check("combat text variables, a profile with height 80 and size 100: 0.03 and the client's string for the size", W.cvars.WorldTextScreenY_v2 == "0.03" and W.cvars.WorldTextScale_v2 == "1.000000"
			and C.record(W, "WorldTextScale_v2") == "none", C.wt(W))
		W.ns.UseProfile("Default")
		check("combat text variables, and back to the first profile: the picks", C.wt(W) == C.picks and C.quiet(W), C.wt(W))
	end

	-- A value changed by hand.
	do
		local W = C.world()
		W.setCVarByPlayer("WorldTextScreenY_v2", "0.03")
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.fire("PLAYER_REGEN_ENABLED")
		check("combat text variables, a variable set by hand: entering the world and the end of combat leave it", W.cvars.WorldTextScreenY_v2 == "0.03")
		W.ns.Set("combattext.spread", "tight")
		check("combat text variables, and a change of Spread writes 0.015 again, with the hand's value remembered", W.cvars.WorldTextScreenY_v2 == "0.015" and C.record(W, "WorldTextScreenY_v2") == "0.03 0.015", C.wt(W))
		W.ns.Set("combattext.enabled", false)
		check("combat text variables, and the page off leaves the hand's value", W.cvars.WorldTextScreenY_v2 == "0.03" and W.cvars.WorldTextScale_v2 == "1.000000" and W.env.FlatUIDB.cvars == nil)
	end

	-- Logout and the next login.
	do
		local W = C.world()
		W.fire("PLAYER_LOGOUT")
		check("combat text variables, logout with three variables written: each holds its remembered string and the three records stay", C.wt(W) == C.game and C.record(W, "WorldTextScreenY_v2") == "0.0 0.015"
			and C.record(W, "WorldTextCritScreenY_v2") == "0.0 0.015" and C.record(W, "WorldTextScale_v2") == "1.000000 1.4", C.wt(W))
		local N = C.world({ cvars = W.cvars }, W.env.FlatUIDB)
		check("combat text variables, a new world from those saved tables: the wanted values are written at login and the remembered strings are unchanged", C.wt(N) == C.picks
			and C.record(N, "WorldTextScreenY_v2") == "0.0 0.015" and C.record(N, "WorldTextScale_v2") == "1.000000 1.4" and has(N.slash("combat"), "At login: the game's own values"), N.slash("combat"))
		local function saved(options)
			return { options = options or {}, cvars = { WorldTextScreenY_v2 = { game = "0.0", wrote = "0.015" }, WorldTextCritScreenY_v2 = { game = "0.0", wrote = "0.015" },
				WorldTextScale_v2 = { game = "1.000000", wrote = "1.4" } } }
		end
		local P = C.world({ cvars = { WorldTextScreenY_v2 = "0.015", WorldTextCritScreenY_v2 = "0.015", WorldTextScale_v2 = "1.4" } }, saved())
		check("combat text variables, saved records with the written values still in place: login makes no write", #P.cvarWrites == 0 and C.wt(P) == C.picks and has(P.slash("combat"), "At login: the values written last session"),
			P.slash("combat"))
		local O = C.world({ cvars = { WorldTextScreenY_v2 = "0.015", WorldTextCritScreenY_v2 = "0.015", WorldTextScale_v2 = "1.4" } }, saved({ ["combattext.enabled"] = false }))
		check("combat text variables, the page off and the records' written values in place: the module's own frame puts the remembered strings back at login", C.wt(O) == C.game and O.env.FlatUIDB.cvars == nil, C.wt(O))
	end

	-- Two characters.
	do
		local A = C.world({ character = "Alice - Realm" })
		A.ns.NewProfile("Quiet")
		A.ns.Set("combattext.enabled", false)
		A.ns.UseProfile("Default")
		local db = A.env.FlatUIDB
		db.profileOf["Bob - Realm"] = "Quiet"
		local B = C.world({ character = "Bob - Realm", cvars = A.cvars }, db)
		check("combat text variables, the first character with the page on and the second with it off: the second's login restores every variable", C.wt(A) == C.picks and C.wt(B) == C.game and B.env.FlatUIDB.cvars == nil, C.wt(B))
	end

	-- A variable the game withholds.
	do
		local V = C.world()
		local get = V.env.C_CVar.GetCVar
		V.env.C_CVar.GetCVar = function(name)
			if name == "WorldTextScale_v2" then
				return SECRET
			end
			return get(name)
		end
		V.ns.Set("combattext.height", 70)
		check("combat text variables, the game withholds one variable: it is skipped, the others are written and nothing fails", V.cvars.WorldTextScreenY_v2 == "0.0225" and V.cvars.WorldTextScale_v2 == "1.4" and C.quiet(V)
			and V.env.FlatUIDB.cvars.WorldTextScale_v2 ~= nil, C.trouble(V))
	end

	-- A write the game does not answer.
	do
		local W = C.world(nil, nil, function(X)
			local set = X.env.C_CVar.SetCVar
			X.env.C_CVar.SetCVar = function(name, value)
				local done = set(name, value)
				if name == "WorldTextScale_v2" then
					X.cvarFault = "silent"
				end
				return done
			end
			local get = X.env.C_CVar.GetCVar
			X.env.C_CVar.GetCVar = function(name)
				if name == "WorldTextScale_v2" and X.cvarFault == "silent" then
					return SECRET
				end
				return get(name)
			end
		end)
		check("combat text variables, a variable the game does not answer after the write: no record is left for it and nothing fails", C.record(W, "WorldTextScale_v2") == "none" and C.quiet(W), C.trouble(W))
	end

	-- ctlook: the look of a number, how a new number appears, and the text for the player's own character.
	do
		local K = {}
		-- The name of the font object a font string shows in: the one it was given, or the game's font it was made on.
		function K.name(font)
			return font.fontObject or font.template
		end
		-- The font object a font string was made on or given, by name.
		function K.object(W, font)
			return W.fontObjects[K.name(font)]
		end
		-- What a made font object holds, as a text: file, height, flags, shadow offset and alpha.
		function K.line(object)
			return table.concat({ object.font and object.font[1] or "none", object.font and g(object.font[2]) or "none", object.font and ("[" .. object.font[3] .. "]") or "none",
				g(object.shadow[1]) .. "," .. g(object.shadow[2]), object.shadowColour and g(object.shadowColour[4]) or "-" }, " ")
		end
		-- The file and the flags of a font object, as one text.
		function K.brief(object)
			return object.font[1] .. "[" .. object.font[3] .. "]"
		end
		K.files = { friz = "Fonts\\FRIZQT__.TTF", arial = "Fonts\\ARIALN.TTF", skurri = "Fonts\\skurri.ttf", morpheus = "Fonts\\MORPHEUS.ttf" }
		K.flags = { thick = "OUTLINE, THICK", thin = "OUTLINE", none = "" }
		-- A hit on the player: the text and colour it shows, or "none".
		function K.own(W, event, flag, amount, school)
			local font = C.hit(W, "player", event, flag, amount, school)
			return font and (font.text .. " " .. C.colour(font)) or "none"
		end
		-- The writes to the variable of the game's own text, as the values written.
		function K.writes(W)
			local out = {}
			for _, write in ipairs(W.cvarWrites) do
				if write.name == "enableFloatingCombatText" then
					out[#out + 1] = write.value .. "<" .. tostring(write.remembered)
				end
			end
			return table.concat(out, ",")
		end
		K.refused = "Skurri: the game refused the font. Numbers show in Friz Quadrata."

		-- The defaults are his picks.
		do
			local W = C.world()
			local picks = {}
			for _, key in ipairs({ "font", "outline", "shadow", "pop", "own", "inStyle", "ownSize" }) do
				picks[#picks + 1] = tostring(W.ns.Get("combattext." .. key))
			end
			check("ctlook: the defaults are Friz Quadrata, no outline, no shadow, a pop, Also misses, dodges and gains, Arc and 100%", table.concat(picks, ",") == "friz,none,false,pop,more,arc,100", table.concat(picks, ","))
			local items = {}
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "combattext" then
					for _, item in ipairs(page) do
						if item.key then
							items[item.key] = item
						end
					end
				end
			end
			check("ctlook: the rows have the choices he saw, in his order, and Incoming style and Size of your text need Combat text for you to be on",
				items.font.choices[1][2] == "Friz Quadrata (the game's damage font)" and #items.font.choices == 4 and items.outline.choices[3][2] == "None" and items.pop.choices[2][2] == "Plainly"
				and items.own.choices[2][2] == "Also misses, dodges and gains" and items.inStyle.choices[3][2] == "Horizontal" and items.ownSize.min == 40 and items.ownSize.max == 400
				and items.inStyle.needs == "own" and table.concat(items.inStyle.needsIn, ",") == "take,more" and items.ownSize.needs == "own" and table.concat(items.ownSize.needsIn, ",") == "take,more"
				and items.own.label == "Combat text for you" and items.pop.label == "How a number appears" and items.ownSize.label == "Size of your text")
			local sections = {}
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "combattext" then
					for _, item in ipairs(page) do
						if item.section then
							sections[#sections + 1] = item.section
						end
					end
				end
			end
			check("ctlook: Combat text for you says what happens to the game's own text, and the sections tell numbers over enemies from the player's text",
				items.own.tip == "While your text shows, Scrolling Combat Text for Self in the game's options is off and its other messages do not show."
				and table.concat(sections, ",") == "Scroll areas,Look,Position and size,Spread and movement,Classic,In front of nameplates,Friendly units,Your character", table.concat(sections, ","))
		end

		-- The look: one font object of the addon's own for each look, with the shadow on the object.
		do
			local W = C.world()
			local font = C.hit(W, "nameplate1", "WOUND", "", 412)
			local object = K.object(W, font)
			check("ctlook: the defaults, a hit on an enemy: one font object is made, Friz Quadrata at 64 with no flags and no shadow, and the font string is made on it",
				#W.madeFonts == 1 and K.name(font) == "FlatUICombat_friz_none_plain" and object == W.madeFonts[1] and K.line(object) == "Fonts\\FRIZQT__.TTF 64 [] 0,0 0", K.line(object))
			check("ctlook: the font string is created on a font of the game's XML for the outline and not on the name of the object the addon made, and is given the made object itself",
				font.template == "CombatTextFont" and rawequal(font.fontObjectValue, W.madeFonts[1]) and type(font.fontObjectValue) == "table", tostring(font.template) .. " " .. type(font.fontObjectValue))
			check("ctlook: the defaults: the font string gets one SetFontObject call and no SetFont or shadow call, and the game's own combat fonts are as they were", font.calls.SetFont == nil and font.calls.SetFontObject == 1
				and font.calls.SetShadowOffset == nil and K.line(W.fontObjects.CombatTextFont) == "Fonts\\FRIZQT__.TTF 64 [] 1,-1 -" and K.line(W.fontObjects.CombatTextFontOutline) == "Fonts\\FRIZQT__.TTF 64 [OUTLINE, THICK] 1,-1 -")
			C.hit(W, "nameplate1", "WOUND", "", 413)
			check("ctlook: a second hit makes no second font object and no second SetFont", #W.madeFonts == 1 and #W.fontSets == 1)
			check("ctlook: the numbers over enemies and the player's own text share the look: a hit on the player is made on the same font object", K.name(C.hit(W, "player", "WOUND", "", 5)) == K.name(font) and #W.madeFonts == 1)
			check("ctlook: a look: no violations, errors or messages", C.quiet(W), C.trouble(W))
		end

		-- Every font, outline and shadow.
		do
			local W = C.world()
			local wrong, names = {}, {}
			for _, face in ipairs({ "friz", "arial", "skurri", "morpheus" }) do
				for _, outline in ipairs({ "thick", "thin", "none" }) do
					for _, shadow in ipairs({ false, true }) do
						W.ns.Set("combattext.font", face)
						W.ns.Set("combattext.outline", outline)
						W.ns.Set("combattext.shadow", shadow)
						local font = C.hit(W, "nameplate1", "WOUND", "", 412)
						local want = ("%s 64 [%s] %s %s"):format(K.files[face], K.flags[outline], shadow and "1,-1" or "0,0", shadow and "1" or "0")
						local got = K.line(K.object(W, font))
						names[K.name(font)] = true
						if got ~= want or K.name(font) ~= ("FlatUICombat_%s_%s_%s"):format(face, outline, shadow and "shadow" or "plain") then
							wrong[#wrong + 1] = face .. "/" .. outline .. "/" .. tostring(shadow) .. ": " .. got .. " on " .. K.name(font)
						end
					end
				end
			end
			local made = 0
			for _ in pairs(names) do
				made = made + 1
			end
			check("ctlook: each of the 24 looks (four fonts, three outlines, shadow on and off) is a font object of its own with its file, 64, its flags and its shadow", #wrong == 0 and made == 24 and #W.madeFonts == 24,
				table.concat(wrong, " | "):sub(1, 300))
			check("ctlook: and the game's own six font objects were never written", K.line(W.fontObjects.CombatTextFont) == "Fonts\\FRIZQT__.TTF 64 [] 1,-1 -" and K.line(W.fontObjects.SystemFont_Huge1_Outline) == "Fonts\\FRIZQT__.TTF 20 [OUTLINE] 1,-1 -"
				and K.line(W.fontObjects.Number12Font) == "Fonts\\ARIALN.TTF 12 [] 1,-1 -" and K.line(W.fontObjects.NumberFont_Outline_Huge) == "Fonts\\skurri.ttf 30 [OUTLINE] 1,-1 -"
				and K.line(W.fontObjects.QuestFont_Super_Huge) == "Fonts\\MORPHEUS.ttf 24 [] 1,-1 -")
			local black = #W.madeFonts == 24
			for _, object in ipairs(W.madeFonts) do
				black = black and object.shadowColour[1] == 0 and object.shadowColour[2] == 0 and object.shadowColour[3] == 0
			end
			check("ctlook: and the shadow colour of every look is black", black)
			check("ctlook: all 24 looks: no violations, errors or messages", C.quiet(W), C.trouble(W))
		end

		-- The file and the flags are the game's where it gives them.
		do
			local F = C.world(nil, nil, function(X)
				X.fontObjects.CombatTextFontOutline.font[3] = "THICKOUTLINE"
				X.fontObjects.SystemFont_Huge1_Outline.font[3] = "OUTLINE, MONOCHROME"
				X.fontObjects.NumberFont_Outline_Huge.font[1] = "Fonts\\K_Damage.ttf"
				X.fontFiles["fonts\\k_damage.ttf"] = true
			end)
			F.ns.Set("combattext.outline", "thick")
			local thick = K.line(K.object(F, C.hit(F, "nameplate1", "WOUND", "", 1)))
			F.ns.Set("combattext.outline", "thin")
			local thin = K.line(K.object(F, C.hit(F, "nameplate1", "WOUND", "", 1)))
			F.ns.Set("combattext.font", "skurri")
			local skurri = K.line(K.object(F, C.hit(F, "nameplate1", "WOUND", "", 1)))
			check("ctlook: the flags passed are the ones the game's own outline fonts give, character for character, and the file is the one the game's face gives",
				thick == "Fonts\\FRIZQT__.TTF 64 [THICKOUTLINE] 0,0 0" and thin == "Fonts\\FRIZQT__.TTF 64 [OUTLINE, MONOCHROME] 0,0 0" and skurri == "Fonts\\K_Damage.ttf 64 [OUTLINE, MONOCHROME] 0,0 0",
				thick .. " | " .. thin .. " | " .. skurri)
			local E = C.world(nil, nil, function(X)
				X.fontObjects.CombatTextFontOutline.font[3] = ""
				X.fontObjects.SystemFont_Huge1_Outline.fault = "secret"
				X.fontObjects.NumberFont_Outline_Huge.fault = "error"
				X.env.Number12Font = nil
				X.env.QuestFont_Super_Huge = nil
			end)
			local got = {}
			for _, pair in ipairs({ { "friz", "thick" }, { "friz", "thin" }, { "skurri", "none" }, { "arial", "none" }, { "morpheus", "none" } }) do
				E.ns.Set("combattext.font", pair[1])
				E.ns.Set("combattext.outline", pair[2])
				got[#got + 1] = K.brief(K.object(E, C.hit(E, "nameplate1", "WOUND", "", 1)))
			end
			check("ctlook: with the game's outline fonts empty, withheld or failing and its face fonts missing or failing, the literal flags and the named files are used",
				table.concat(got, "|") == "Fonts\\FRIZQT__.TTF[OUTLINE, THICK]|Fonts\\FRIZQT__.TTF[OUTLINE]|Fonts\\skurri.ttf[]|Fonts\\ARIALN.TTF[]|Fonts\\MORPHEUS.ttf[]", table.concat(got, "|"))
			check("ctlook: /flatui combat says none read for an outline font that gives no flags, empty, withheld or failing", has(E.slash("combat"), "Outline styles from the game: thick none read, thin none read.\n"), E.slash("combat"))
			-- The file of a face is the one its own game font object gives, in the language of the client, with any outline.
			local Y = C.world(nil, nil, function(X)
				for _, pair in ipairs({ { "CombatTextFont", "Fonts\\FRIZQT___CYR.TTF" }, { "Number12Font", "Fonts\\ARIALN_CYR.TTF" }, { "QuestFont_Super_Huge", "Fonts\\MORPHEUS_CYR.ttf" } }) do
					X.fontObjects[pair[1]].font[1] = pair[2]
					X.fontFiles[pair[2]:lower()] = true
				end
			end)
			local cyr = {}
			for _, pair in ipairs({ { "friz", "thick" }, { "friz", "none" }, { "arial", "none" }, { "morpheus", "thin" } }) do
				Y.ns.Set("combattext.font", pair[1])
				Y.ns.Set("combattext.outline", pair[2])
				cyr[#cyr + 1] = K.brief(K.object(Y, C.hit(Y, "nameplate1", "WOUND", "", 1)))
			end
			check("ctlook: the file of a face is the one the game's font object of that face gives, with the flags of the outline and not the file of the outline's font object",
				table.concat(cyr, "|") == "Fonts\\FRIZQT___CYR.TTF[OUTLINE, THICK]|Fonts\\FRIZQT___CYR.TTF[]|Fonts\\ARIALN_CYR.TTF[]|Fonts\\MORPHEUS_CYR.ttf[OUTLINE]", table.concat(cyr, "|"))
			local Z = C.world(nil, nil, function(X)
				X.fontObjects.Number12Font.font[1] = ""
			end)
			Z.ns.Set("combattext.font", "arial")
			check("ctlook: a face font object that gives an empty file is as good as none, and the named file is used", K.brief(K.object(Z, C.hit(Z, "nameplate1", "WOUND", "", 1))) == "Fonts\\ARIALN.TTF[]" and C.quiet(Z), C.trouble(Z))
		end

		-- A font the game refuses.
		do
			local R = C.world(nil, nil, function(X)
				X.fontFiles["fonts\\skurri.ttf"] = nil
			end)
			R.ns.Set("combattext.font", "skurri")
			R.ns.Set("combattext.outline", "thick")
			R.ns.Set("combattext.shadow", true)
			local first = C.hit(R, "nameplate1", "WOUND", "", 1)
			local sets = #R.fontSets
			local second = C.hit(R, "nameplate1", "WOUND", "", 2)
			check("ctlook: a font the game refuses: the number shows in Friz Quadrata with the same outline and shadow, and the status says so once", K.name(first) == "FlatUICombat_friz_thick_shadow"
				and K.name(second) == "FlatUICombat_friz_thick_shadow" and count(R.status(), K.refused) == 1, K.name(first) .. " " .. R.status())
			check("ctlook: and the next number asks the game for no font again", #R.fontSets == sets and #R.madeFonts == 2 and C.quiet(R), #R.fontSets .. " " .. sets)
			R.ns.Set("combattext.font", "arial")
			local arial = C.hit(R, "nameplate1", "WOUND", "", 3)
			check("ctlook: a change of Font takes the line away", K.name(arial) == "FlatUICombat_arial_thick_shadow" and not has(R.status(), "refused the font"), R.status())
			R.ns.Set("combattext.font", "skurri")
			C.hit(R, "nameplate1", "WOUND", "", 4)
			check("ctlook: and choosing the font again brings the line back, once, and asks the game for no font object again", count(R.status(), K.refused) == 1 and #R.madeFonts == 3 and #R.fontSets == 3 and C.quiet(R),
				R.status() .. " " .. #R.madeFonts .. " " .. #R.fontSets .. " " .. C.trouble(R))
			-- A string used again is put on the look in use, and after a refusal on the font the game would not refuse.
			C.draw(R, R.now + 3)
			R.ns.Set("combattext.font", "morpheus")
			local morpheus = C.hit(R, "nameplate1", "WOUND", "", 5)
			check("ctlook: a font string used again after a change of Font is put on the new font object", morpheus.fontObject == "FlatUICombat_morpheus_thick_shadow", tostring(morpheus.fontObject))
			C.draw(R, R.now + 3)
			R.ns.Set("combattext.font", "skurri")
			local again = C.hit(R, "nameplate1", "WOUND", "", 6)
			check("ctlook: and one used again after the refused font is put on the fallback, not left on the face it had, with the line said once", again == morpheus and again.fontObject == "FlatUICombat_friz_thick_shadow"
				and count(R.status(), K.refused) == 1, tostring(again.fontObject) .. " " .. R.status())
			-- The names of the other two faces are in the line too.
			local A = C.world(nil, nil, function(X)
				X.fontFiles["fonts\\arialn.ttf"] = nil
				X.fontFiles["fonts\\morpheus.ttf"] = nil
			end)
			A.ns.Set("combattext.font", "arial")
			C.hit(A, "nameplate1", "WOUND", "", 1)
			local arialLine = A.status()
			A.ns.Set("combattext.font", "morpheus")
			C.hit(A, "nameplate1", "WOUND", "", 2)
			check("ctlook: the line names the face the game refused: Arial Narrow, and Morpheus after it", has(arialLine, "Arial Narrow: the game refused the font. Numbers show in Friz Quadrata.") and not has(arialLine, "Morpheus")
				and has(A.status(), "Morpheus: the game refused the font. Numbers show in Friz Quadrata.") and not has(A.status(), "Arial Narrow: the game refused"), arialLine .. " | " .. A.status())
			local P = C.world(nil, nil, function(X)
				X.fontFiles["fonts\\skurri.ttf"] = nil
			end)
			P.ns.Set("combattext.font", "skurri")
			local own = C.hit(P, "player", "WOUND", "", 7)
			check("ctlook: a refused font shows the player's own text in Friz Quadrata as well", K.name(own) == "FlatUICombat_friz_none_plain" and count(P.status(), K.refused) == 1)
			-- SetFont says no without raising.
			local N = C.world(nil, nil, function(X)
				X.fontFault = "false"
			end)
			local plain = C.hit(N, "nameplate1", "WOUND", "", 1)
			local plainLine = N.status()
			N.ns.Set("combattext.outline", "thick")
			local thick = C.hit(N, "nameplate1", "WOUND", "", 2)
			N.ns.Set("combattext.outline", "thin")
			local thin = C.hit(N, "nameplate1", "WOUND", "", 3)
			check("ctlook: a font object that holds no file after SetFont is refused, and the number shows on the game's own font for the outline",
				K.name(plain) == "CombatTextFont" and K.name(thick) == "CombatTextFontOutline" and K.name(thin) == "CombatTextFontOutline"
				and C.quiet(N), N.status())
			check("ctlook: and the line says which look the game's combat font has: a shadow for Outline None, a thick outline and a shadow for Thick and Thin",
				has(plainLine, "Friz Quadrata: the game refused the font. Numbers show in the game's combat font, with a shadow.") and not has(plainLine, "thick outline")
				and has(N.status(), "Friz Quadrata: the game refused the font. Numbers show in the game's combat font, with a thick outline and a shadow.") and count(N.status(), "refused the font") == 1, plainLine .. " | " .. N.status())
			local U = C.world(nil, nil, function(X)
				X.fontFault = "empty"
			end)
			local blank = C.hit(U, "nameplate1", "WOUND", "", 1)
			check("ctlook: a font object that holds an empty file after SetFont is refused too", K.name(blank) == "CombatTextFont" and has(U.status(), "Friz Quadrata: the game refused the font. Numbers show in the game's combat font, with a shadow.") and C.quiet(U), U.status())
			local S = C.world(nil, nil, function(X)
				X.fontFault = "silent"
			end)
			local silent = C.hit(S, "nameplate1", "WOUND", "", 1)
			check("ctlook: SetFont says false but the file is held: the look is kept and no line is said", K.name(silent) == "FlatUICombat_friz_none_plain" and not has(S.status(), "refused the font") and C.quiet(S))
			local X = C.world(nil, nil, function(Y)
				Y.fontFault = "error"
			end)
			local errored = C.hit(X, "nameplate1", "WOUND", "", 1)
			check("ctlook: SetFont raises an error for every file: the game's own font, one line, and the module goes on", errored ~= nil and K.name(errored) == "CombatTextFont" and not X.ns.IsStopped("combattext")
				and count(X.status(), "refused the font") == 1 and C.quiet(X), X.status())
			local M = C.world(nil, nil, function(Y)
				Y.env.CreateFont = nil
			end)
			M.ns.Set("combattext.outline", "thick")
			local missing = C.hit(M, "nameplate1", "WOUND", "", 1)
			-- The client makes the object but will not give it to a font string.
			local Fr = C.world(nil, nil, function(Y)
				Y.fontRefuse = true
			end)
			Fr.ns.Set("combattext.outline", "thick")
			Fr.now = 0
			local unstyled = C.hit(Fr, "nameplate1", "WOUND", "", 1)
			C.draw(Fr, 3)
			local ended = unstyled ~= nil and unstyled.shown == false
			local reused = C.hit(Fr, "nameplate1", "WOUND", "", 2)
			check("ctlook: a font object the game will not give to a font string leaves the number in the game's font for the outline, the status counts the string once, and the module goes on",
				unstyled ~= nil and unstyled.fontObject == nil and unstyled.template == "CombatTextFontOutline" and ended and reused == unstyled and reused.shown and has(Fr.status(), "Numbers the game would not set the font on: 1.")
				and not Fr.ns.IsStopped("combattext") and C.quiet(Fr), Fr.status())
			Fr.ns.Set("combattext.shadow", true)
			C.draw(Fr, 6)
			C.hit(Fr, "nameplate1", "WOUND", "", 3)
			check("ctlook: and the string is counted again when the look changes and the game refuses that too", has(Fr.status(), "Numbers the game would not set the font on: 2.") and C.quiet(Fr), Fr.status())
			check("ctlook: a client without CreateFont: the numbers show on the game's own font for the outline and the module goes on", missing ~= nil and K.name(missing) == "CombatTextFontOutline"
				and not M.ns.IsStopped("combattext") and has(M.status(), "Friz Quadrata: the game refused the font. Numbers show in the game's combat font, with a thick outline and a shadow."), M.status())
		end

		-- A change of look reaches the next number and leaves the numbers in the air as they are.
		do
			local W = C.world()
			local first = C.hit(W, "nameplate1", "WOUND", "", 1)
			local air = C.hit(W, "nameplate1", "WOUND", "", 2)
			local t0 = W.now
			W.ns.Set("combattext.shadow", true)
			check("ctlook: a number in the air at a change of Shadow keeps its font object", K.name(air) == "FlatUICombat_friz_none_plain" and air.calls.SetFontObject == 1 and air.shown and #W.madeFonts == 1)
			C.draw(W, t0 + 1.6)
			local again = C.hit(W, "nameplate1", "WOUND", "", 3)
			check("ctlook: a font string used again after the change is put on the new font object and has its height set again", again == first and again.fontObject == "FlatUICombat_friz_none_shadow" and again.calls.SetFontObject == 2
				and #again.heights == 2 and #W.madeFonts == 2, tostring(again.fontObject))
			C.draw(W, t0 + 3.2)
			local third = C.hit(W, "nameplate1", "WOUND", "", 4)
			check("ctlook: and used again with no change, it gets no call", third == first and third.calls.SetFontObject == 2 and #third.heights == 2)
			check("ctlook: a change of look: no violations, errors or messages", C.quiet(W), C.trouble(W))
		end

		-- How a new number appears.
		do
			local W = C.world()
			W.now = 0
			local n = C.hit(W, "nameplate1", "WOUND", "", 412)
			local seen = { g(n.textHeight) }
			for _, t in ipairs({ 0.05, 0.125, 0.2 }) do
				C.draw(W, t)
				seen[#seen + 1] = g(n.textHeight)
			end
			check("ctlook: with a pop, an ordinary number at 140% is 35 high at its start, 45 at 0.05 seconds, 40 at 0.125 and 35 at 0.2", table.concat(seen, ",") == "35,45,40,35", table.concat(seen, ","))
			local F = C.world()
			F.now = 0
			local fine = C.hit(F, "nameplate1", "WOUND", "", 412)
			for step = 1, 30 do
				C.draw(F, step * 0.01)
			end
			local whole, top, repeated = true, 0, false
			for index, h in ipairs(fine.heights) do
				whole = whole and h == math.floor(h)
				top = math.max(top, h)
				repeated = repeated or fine.heights[index - 1] == h
			end
			local calls = fine.calls.SetTextHeight
			C.draw(F, 0.4)
			C.draw(F, 0.9)
			check("ctlook: with a pop, every height is a whole number, the highest is 45, and no SetTextHeight call follows 0.2 seconds", whole and top == 45 and fine.calls.SetTextHeight == calls and fine.textHeight == 35, top .. " " .. calls)
			check("ctlook: and a frame that gives the same height as the one before makes no call", not repeated and calls < 30, #fine.heights .. " " .. calls)
			local E = C.world()
			E.now = 0
			local late = C.hit(E, "nameplate1", "WOUND", "CRITICAL", 5)
			E.now = 0.04999999999
			C.draw(E, 0.04999999999)
			check("ctlook: a frame drawn a hair before 0.05 seconds has the peak, as the sum of two clock readings can come out a hair short", late.textHeight == 84, tostring(late.textHeight))
			local V = C.world()
			V.now = 0
			local crit = C.hit(V, "nameplate1", "WOUND", "CRITICAL", 824)
			local crush = C.hit(V, "nameplate1", "WOUND", "CRUSHING", 600)
			local heal = C.hit(V, "nameplate1", "HEAL", "CRITICAL", 300)
			local kinds = { g(crit.textHeight) .. "/" .. g(crush.textHeight) .. "/" .. g(heal.textHeight) }
			for _, t in ipairs({ 0.05, 0.2, 0.5 }) do
				C.draw(V, t)
				kinds[#kinds + 1] = g(crit.textHeight) .. "/" .. g(crush.textHeight) .. "/" .. g(heal.textHeight)
			end
			check("ctlook: with a pop, a critical hit, a crushing hit and a critical heal at 140% are 42 at the start, 84 at 0.05 seconds and 42 from 0.2 on", table.concat(kinds, " ") == "42/42/42 84/84/84 42/42/42 42/42/42",
				table.concat(kinds, " "))
			local P = C.world()
			P.now = 0
			P.ns.Set("combattext.pop", "plain")
			local plain = C.hit(P, "nameplate1", "WOUND", "", 412)
			local plainCrit = C.hit(P, "nameplate1", "WOUND", "CRITICAL", 824)
			for _, t in ipairs({ 0.05, 0.1, 0.3, 1.0 }) do
				C.draw(P, t)
			end
			check("ctlook: with Plainly, an ordinary number is 35 and a critical hit 42 from the first frame, and each number has exactly one SetTextHeight call over its whole life",
				plain.textHeight == 35 and plainCrit.textHeight == 42 and plain.calls.SetTextHeight == 1 and plainCrit.calls.SetTextHeight == 1, plain.calls.SetTextHeight .. " " .. plainCrit.calls.SetTextHeight)
			local Q = C.world()
			Q.now = 0
			Q.ns.Set("combattext.size", 100)
			local small = C.hit(Q, "nameplate1", "WOUND", "CRITICAL", 5)
			local frames = { g(small.textHeight) }
			for _, t in ipairs({ 0.05, 0.2 }) do
				C.draw(Q, t)
				frames[#frames + 1] = g(small.textHeight)
			end
			check("ctlook: at 100% a critical hit goes from 30 to 60 and back to 30 as the game's own does", table.concat(frames, ",") == "30,60,30", table.concat(frames, ","))
			local J = C.world()
			J.now = 0
			J.ns.Set("combattext.size", 100)
			local hairy = C.hit(J, "nameplate1", "WOUND", "CRITICAL", 5)
			local hairs = {}
			for _, t in ipairs({ 0.01, 0.195, 0.2 }) do
				C.draw(J, t)
				hairs[#hairs + 1] = g(hairy.textHeight)
			end
			check("ctlook: a time that falls a hair short of a whole height still gives it: a critical hit at 100% is 36 high at 0.01 seconds and 31 at 0.195", table.concat(hairs, ",") == "36,31,30", table.concat(hairs, ","))
			local O = C.world()
			O.now = 0
			O.ns.Set("combattext.size", 110)
			local ten = C.hit(O, "nameplate1", "WOUND", "", 5)
			local steps = { g(ten.textHeight) }
			for _, t in ipairs({ 0.05, 0.2 }) do
				C.draw(O, t)
				steps[#steps + 1] = g(ten.textHeight)
			end
			check("ctlook: a settled height that is not a whole number is kept at the start and at the end, and the pop goes up from it in whole numbers", table.concat(steps, ",") == "27.5,35.5,27.5", table.concat(steps, ","))
			check("ctlook: the pop: no violations, errors or messages", C.quiet(W) and C.quiet(V) and C.quiet(P) and C.quiet(Q) and C.quiet(O) and C.quiet(F) and C.quiet(E) and C.quiet(J), C.trouble(W) .. C.trouble(P))
		end

		-- Damage and healing you take, and the rest of what Also misses, dodges and gains adds.
		do
			local W = C.world({ words = true })
			W.ns.Set("combattext.own", "take")
			local take = { K.own(W, "WOUND", "", 412, 1), K.own(W, "WOUND", "", 412, 4), K.own(W, "HEAL", "", 300, 1), K.own(W, "WOUND", "", 0, 1), K.own(W, "HEAL", "", 0, 1),
				K.own(W, "DODGE", "", 0, 1), K.own(W, "MISS", "", 0, 1), K.own(W, "ENERGIZE", "", 20, 1) }
			check("ctlook: Damage and healing you take: 412 of school 1 is -412 in red, of school 4 purple, 300 of healing +300 in green, and 0, a dodge, a miss and a gain show nothing",
				table.concat(take, "|") == "-412 1,0.1,0.1|-412 0.79,0.3,0.85|+300 0.1,1,0.1|none|none|none|none|none", table.concat(take, "|"))
			W.ns.Set("combattext.own", "more")
			local more = { K.own(W, "WOUND", "", 0, 1), K.own(W, "WOUND", "ABSORB", 0, 1), K.own(W, "WOUND", "BLOCK", 0, 1), K.own(W, "WOUND", "RESIST", 0, 1), K.own(W, "ENERGIZE", "", 20, 1),
				K.own(W, "ENERGIZE", "", 0, 1), K.own(W, "ENERGIZE", "", -5, 1), K.own(W, "WOUND", "", 412, 1), K.own(W, "HEAL", "", 300, 1) }
			check("ctlook: Also misses, dodges and gains: a wound of 0 is Miss, or Absorb, Block or Resist by its flag, a gain of 20 is +20 in light blue, and a gain of 0 or less shows nothing",
				table.concat(more, "|") == "(Miss) 1,1,1|(Absorb) 1,1,1|(Block) 1,1,1|(Resist) 1,1,1|+20 0.41,0.8,0.94|none|none|-412 1,0.1,0.1|+300 0.1,1,0.1", table.concat(more, "|"))
			local words = {}
			for _, event in ipairs({ "MISS", "DODGE", "PARRY", "BLOCK", "RESIST", "ABSORB", "IMMUNE", "EVADE", "DEFLECT", "REFLECT", "INTERRUPT" }) do
				words[#words + 1] = K.own(W, event, "", 0, 1)
			end
			check("ctlook: Also misses, dodges and gains: each of the eleven events of the game shows its word in white", table.concat(words, "|") == "(Miss) 1,1,1|(Dodge) 1,1,1|(Parry) 1,1,1|(Block) 1,1,1|(Resist) 1,1,1|(Absorb) 1,1,1|(Immune) 1,1,1|(Evade) 1,1,1|(Deflect) 1,1,1|(Reflect) 1,1,1|(Interrupt) 1,1,1",
				table.concat(words, "|"))
			check("ctlook: and an event that is none of them shows nothing", K.own(W, "NOTHING", "", 20, 1) == "none" and K.own(W, "BLOCK_REDUCED", "", 20, 1) == "none")
			local crit = C.hit(W, "player", "WOUND", "CRITICAL", 824, 1)
			local crush = C.hit(W, "player", "WOUND", "CRUSHING", 824, 1)
			local gain = C.hit(W, "player", "ENERGIZE", "CRITICAL", 20, 1)
			local heal = C.hit(W, "player", "HEAL", "CRITICAL", 20, 1)
			local plain = C.hit(W, "player", "WOUND", "GLANCING", 20, 1)
			check("ctlook: a critical or crushing wound and a critical heal or gain is 31.25 high at 100%, and a glancing hit and the rest 25", crit.textHeight == 31.25 and crush.textHeight == 31.25 and gain.textHeight == 31.25 and heal.textHeight == 31.25
				and plain.textHeight == 25 and plain.text == "-20")
			local magic = { C.hit(W, "player", "WOUND", "CRUSHING", 824, 4), C.hit(W, "player", "WOUND", "CRITICAL", 824, 4), C.hit(W, "player", "WOUND", "", 824, 4) }
			check("ctlook: a crushing or critical hit of magic is purple and 31.25 high at 100%, and other magic damage 25", magic[1].textHeight == 31.25 and magic[2].textHeight == 31.25 and magic[3].textHeight == 25
				and C.colour(magic[1]) == "0.79,0.3,0.85" and C.colour(magic[2]) == "0.79,0.3,0.85")
			check("ctlook: damage to the player: no violations or errors", #W.violations == 0 and #W.errors == 0, C.trouble(W))
			-- Off.
			local F = C.world()
			F.ns.Set("combattext.own", "off")
			local frames = #F.addonFrames
			local off = { K.own(F, "WOUND", "", 412, 1), K.own(F, "HEAL", "", 300, 1), K.own(F, "WOUND", "", 0, 1) }
			check("ctlook: Combat text for you Off: nothing is shown, no frame is made and the count stays 0", table.concat(off, "|") == "none|none|none" and #F.addonFrames == frames and #F.addonFonts == 0
				and has(F.slash("combat"), "Hit reports for you: 0. Shown: 0.") and not has(F.status(), "Combat text for you"), F.slash("combat"))
			check("ctlook: and a hit on an enemy still shows", C.say(F, "nameplate1", "WOUND", "", 5) == "5" and #F.violations == 0 and #F.errors == 0)
			-- Withheld values.
			local V = C.world()
			local secret = C.hit(V, "player", "WOUND", "", SECRET, 1)
			check("ctlook: an amount the game withholds is shown through SetFormattedText with its sign, and counted", secret ~= nil and secret.text == "-<withheld>" and secret.withheld == 1 and secret.calls.SetFormattedText == 1
				and has(V.status(), "Hit amounts the game would not tell: 1."), V.status())
			local gain2 = C.hit(V, "player", "ENERGIZE", "", SECRET, 1)
			local heal2 = C.hit(V, "player", "HEAL", "", SECRET, 1)
			check("ctlook: a withheld gain and a withheld heal are shown the same way", gain2 ~= nil and gain2.text == "+<withheld>" and heal2 ~= nil and heal2.text == "+<withheld>")
			local flagless = C.hit(V, "player", "WOUND", SECRET, 412, 1)
			check("ctlook: a flag the game withholds gives a number of ordinary size, and is counted", flagless.text == "-412" and flagless.textHeight == 25 and has(V.status(), "Hit types the game would not tell: 1."), V.status())
			check("ctlook: a school the game withholds gives red", C.colour(C.hit(V, "player", "WOUND", "", 412, SECRET)) == "1,0.1,0.1")
			local before = #V.addonFonts
			C.hit(V, SECRET, "WOUND", "", 412, 1)
			C.hit(V, "player", SECRET, "", 412, 1)
			check("ctlook: a unit or an event the game withholds shows nothing and fails nowhere", #V.addonFonts == before and C.quiet(V), C.trouble(V))
			check("ctlook: and both are counted as reports with no detail", has(V.slash("combat"), "Report unreadable: 2.\n"), V.slash("combat"))
			-- The vehicle.
			local H = C.world()
			local walking = { K.own(H, "WOUND", "", 1, 1), K.own(H, "WOUND", "", 2, 1) }
			local noVehicle = C.hit(H, "vehicle", "WOUND", "", 3, 1)
			H.vehicle = true
			local driving = C.hit(H, "vehicle", "WOUND", "", 4, 1)
			local player = C.hit(H, "player", "WOUND", "", 5, 1)
			check("ctlook: a report for the player shows while there is no vehicle interface and not while there is, and one for the vehicle only while there is", walking[1]:find("^%-1") and noVehicle == nil
				and driving ~= nil and driving.text == "-4" and player == nil, tostring(noVehicle) .. " " .. tostring(driving and driving.text))
			H.vehicleFault = "secret"
			check("ctlook: and a withheld answer about the vehicle is no vehicle", C.hit(H, "player", "WOUND", "", 6, 1) ~= nil)
			H.ns.Set("combattext.friend", "off")
			local others = { C.say(H, "party1", "WOUND", "", 7), C.say(H, "pet", "WOUND", "", 8), C.say(H, "target", "WOUND", "", 9) }
			check("ctlook: with Where friendly numbers show Off, reports for party1, pet and target show nothing, in a vehicle or out", table.concat(others, ",") == "none,none,none" and C.quiet(H), C.trouble(H))
			-- The rest of the module.
			local M = C.world()
			for index = 1, 3 do
				C.hit(M, "player", "WOUND", "", index, 1)
			end
			check("ctlook: hits on the player leave the four switch rows at 1, write nothing and leave the nameplate counters and the wait for the first hit as they are",
				C.rows(M) == "1111" and C.writes(M) == 0 and has(M.slash("combat"), "Hit reports: 0 for nameplates, 0 for target.") and has(M.status(), C.enter) and has(M.status(), "Combat text for you: 3 shown."), M.status())
			M.ns.Set("combattext.source", "game")
			check("ctlook: and with As the game has them they show all the same", C.say(M, "player", "WOUND", "", 4, 1) == "-4" and C.rows(M) == "1111" and has(M.status(), "Combat text for you: 4 shown."), M.status())
			M.ns.Set("combattext.source", "front")
			check("ctlook: the last hit report for the player is in /flatui combat, in the form of the one for an enemy", has(M.slash("combat"), "Hit reports for you: 4. Shown: 4.\nLast hit report for you: player, WOUND, , 4, school 1\n"), M.slash("combat"))
			check("ctlook: damage and words for the player: no violations or errors", #M.violations == 0 and #M.errors == 0, C.trouble(M))
		end

		-- The Incoming scroll area: where the numbers for the player start, how they move, fade and stack.
		do
			local function spots(list)
				local out = {}
				for _, font in ipairs(list) do
					out[#out + 1] = g(font.points[1][4]) .. "," .. g(font.points[1][5])
				end
				return table.concat(out, " ")
			end
			local function style(name, more)
				local options = { ["combattext.inStyle"] = name }
				for key, value in pairs(more or {}) do
					options[key] = value
				end
				return C.world(nil, { options = options })
			end
			local W = style("horizontal")
			W.now = 0
			local one = C.hit(W, "player", "HEAL", "", 300, 1)
			check("scrolling: Incoming: the first number for the player starts at the middle of the handle: 170 left of and 30 below the middle of the screen",
				C.spot(one) == "CENTER BOTTOMLEFT 790 510" and one.points[1][2] == W.env.UIParent and #one.points == 1, C.spot(one))
			C.draw(W, 0.033)
			check("scrolling: Incoming: a number fades in over the first 3 percent of its 2.2 seconds: half opaque at 0.033", near(one.alpha, 0.5, 1e-9), tostring(one.alpha))
			C.draw(W, 0.95)
			check("scrolling: Incoming: Horizontal: at 0.95 seconds a number is 62.18 units to the left of its start at the same height, and whole",
				near(one.points[1][4], 790 - 144 * 0.95 / 2.2, 1e-9) and near(one.points[1][5], 510) and near(one.alpha, 1), C.spot(one))
			C.draw(W, 1.65)
			check("scrolling: Incoming: and it is whole until three quarters of its life", near(one.alpha, 1, 1e-9) and one.shown)
			C.draw(W, 1.925)
			check("scrolling: Incoming: half faded at 1.925 seconds", near(one.alpha, 0.5, 1e-9), tostring(one.alpha))
			C.draw(W, 2.19)
			check("scrolling: Incoming: still shown just before 2.2 seconds, and a script runs for it", one.shown and C.running(W) == 1)
			C.draw(W, 2.2)
			check("scrolling: Incoming: hidden at 2.2 seconds, and no frame runs a script any more", not one.shown and C.running(W) == 0)
			-- The height of WorldFrame, not of UIParent, scales the way.
			local H = style("horizontal")
			H.worldHeight = 1536
			H.now = 0
			local tall = C.hit(H, "player", "HEAL", "", 300, 1)
			C.draw(H, 0.95)
			check("scrolling: Incoming: the way is scaled by the height of WorldFrame: on 1536 high it is twice as far, whatever UIParent is", near(tall.points[1][4], 790 - 2 * 144 * 0.95 / 2.2, 1e-9), C.spot(tall))
			local odd = {}
			for _, how in ipairs({ "secret", "error" }) do
				local X = style("horizontal")
				X.worldFault = how
				X.now = 0
				local font = C.hit(X, "player", "HEAL", "", 300, 1)
				C.draw(X, 0.95)
				odd[#odd + 1] = near(font.points[1][4], 790 - 144 * 0.95 / 2.2, 1e-9) and C.quiet(X)
			end
			local Gone = C.world(nil, { options = { ["combattext.inStyle"] = "horizontal" } }, function(Z)
				Z.env.WorldFrame = nil
			end)
			Gone.now = 0
			local absent = C.hit(Gone, "player", "HEAL", "", 300, 1)
			C.draw(Gone, 0.95)
			check("scrolling: Incoming: a height of WorldFrame that is withheld, fails or is not there gives the length of a screen 768 high", odd[1] and odd[2] and near(absent.points[1][4], 790 - 144 * 0.95 / 2.2, 1e-9) and C.quiet(Gone), C.trouble(Gone))
			check("scrolling: /flatui combat ends with how high WorldFrame is and how long the scroll areas are, and says so when the height is not known",
				H.slash("combat"):find("\nGame world height is 1536: the scroll areas are 480 long.$") ~= nil and W.slash("combat"):find("\nGame world height is 768: the scroll areas are 240 long.$") ~= nil
				and Gone.slash("combat"):find("\nGame world height is not known: the scroll areas are 240 long.$") ~= nil, H.slash("combat"))
			-- The four styles, 0.95 seconds in.
			local D = style("straight")
			D.now = 0
			local down = C.hit(D, "player", "HEAL", "", 300, 1)
			C.draw(D, 0.95)
			check("scrolling: Incoming: Straight goes down 103.64 units in 0.95 seconds and not sideways", near(down.points[1][5], 510 - 240 * 0.95 / 2.2, 1e-9) and near(down.points[1][4], 790), C.spot(down))
			local A = style("arc", { ["combattext.arcWidth"] = "narrow" })
			A.now = 0
			local arc = C.hit(A, "player", "HEAL", "", 300, 1)
			C.draw(A, 0.95)
			check("scrolling: Incoming: Arc goes down as Straight does and to the left in a half sine, 46.9 units at 0.95 seconds", near(arc.points[1][5], 510 - 240 * 0.95 / 2.2, 1e-9)
				and near(arc.points[1][4], 790 - 48 * math.sin(math.pi * 0.95 / 2.2), 1e-9), C.spot(arc))
			local Sa = style("static")
			Sa.now = 0
			local still = C.hit(Sa, "player", "HEAL", "", 300, 1)
			C.draw(Sa, 1.05)
			local at70 = still.alpha
			C.draw(Sa, 1.275)
			local at85 = still.alpha
			check("scrolling: Incoming: Static stays at its start, whole until 70 percent of its 1.5 seconds and half faded at 85 percent", C.spot(still) == "CENTER BOTTOMLEFT 790 510" and near(at70, 1, 1e-9) and near(at85, 0.5, 1e-9) and still.shown,
				C.spot(still) .. " " .. at70 .. " " .. at85)
			C.draw(Sa, 1.5)
			check("scrolling: Incoming: and Static is gone at 1.5 seconds whatever Speed is", not still.shown)
			local lives = {}
			for _, speed in ipairs({ "fast", "slow" }) do
				local P = style("horizontal", { ["combattext.speed"] = speed })
				P.now = 0
				local font = C.hit(P, "player", "HEAL", "", 300, 1)
				C.draw(P, speed == "fast" and 1.59 or 2.99)
				local before = font.shown
				C.draw(P, speed == "fast" and 1.6 or 3)
				lives[#lives + 1] = tostring(before) .. tostring(font.shown)
			end
			check("scrolling: Speed: Fast lives 1.6 seconds and Slow 3", table.concat(lives, ",") == "truefalse,truefalse", table.concat(lives, ","))
			-- Rows.
			local R = style("straight")
			local lined = {}
			for index = 1, 3 do
				lined[index] = C.hit(R, "player", "HEAL", "", index, 1)
			end
			check("scrolling: Incoming: Straight numbers that come together start 26 units apart, one line, each behind the one before", spots(lined) == "790,510 790,536 790,562", spots(lined))
			local Q = style("straight")
			Q.now = 0
			C.hit(Q, "player", "HEAL", "", 1, 1)
			C.draw(Q, 0.5)
			local later = C.hit(Q, "player", "HEAL", "", 2, 1)
			check("scrolling: Incoming: a number that arrives when the one before has gone a line starts at the handle", C.spot(later) == "CENTER BOTTOMLEFT 790 510", C.spot(later))
			local L = style("straight")
			L.now = 10
			C.hit(L, "player", "HEAL", "", 1, 1)
			C.draw(L, 10.1)
			local close = C.hit(L, "player", "HEAL", "", 2, 1)
			check("scrolling: Incoming: a number that arrives 0.1 seconds after the one before starts the rest of a line behind it", near(close.points[1][5], 510 + (26 - 240 * 0.1 / 2.2), 1e-9), C.spot(close))
			local Hz = style("horizontal")
			local rows = {}
			for index = 1, 7 do
				rows[index] = C.hit(Hz, "player", "HEAL", "", index, 1)
			end
			check("scrolling: Incoming: Horizontal numbers that come together take a row each, 26 units under the one before, five rows, and then the first row again",
				spots(rows) == "790,510 790,484 790,458 790,432 790,406 790,510 790,510", spots(rows))
			local Hz2 = style("horizontal")
			Hz2.now = 0
			C.hit(Hz2, "player", "HEAL", "", 1, 1)
			C.draw(Hz2, 0.9)
			local busy = C.hit(Hz2, "player", "HEAL", "", 2, 1)
			C.draw(Hz2, 1)
			local free = C.hit(Hz2, "player", "HEAL", "", 3, 1)
			check("scrolling: Incoming: a Horizontal number leaves its row after two and a half heights: at 0.9 seconds the next number takes the second row, at 1.0 the first",
				near(busy.points[1][5], 484, 1e-9) and near(free.points[1][5], 510, 1e-9), g(busy.points[1][5]) .. " " .. g(free.points[1][5]))
			local Rr = style("horizontal")
			Rr.now = 0
			for index = 1, 5 do
				C.hit(Rr, "player", "HEAL", "", index, 1)
				C.draw(Rr, 0.1 * index)
			end
			C.draw(Rr, 1)
			local reused = C.hit(Rr, "player", "HEAL", "", 6, 1)
			local oldest = C.hit(Rr, "player", "HEAL", "", 7, 1)
			check("scrolling: Incoming: when every row is busy a Horizontal number takes the row of the oldest number: the sixth takes the first row that has gone, the seventh the second row, whose number is the oldest",
				near(reused.points[1][5], 510, 1e-9) and near(oldest.points[1][5], 484, 1e-9), g(reused.points[1][5]) .. " " .. g(oldest.points[1][5]))
			local St = style("static")
			local still5 = {}
			for index = 1, 3 do
				still5[index] = C.hit(St, "player", "HEAL", "", index, 1)
			end
			check("scrolling: Incoming: Static numbers that come together take a row each too", spots(still5) == "790,510 790,484 790,458", spots(still5))
			local Sz = style("straight", { ["combattext.ownSize"] = 160 })
			local big = C.hit(Sz, "player", "HEAL", "", 1, 1)
			local bigger = C.hit(Sz, "player", "HEAL", "", 2, 1)
			check("scrolling: Incoming: the line grows with Size of your text: 160% is 40 high and the lines are 41.6 apart", big.textHeight == 40 and near(bigger.points[1][5], 510 + 41.6, 1e-9), C.spot(bigger))
			-- Words, partial effects and the pop.
			local function wordOf(world, font)
				for index, other in ipairs(world.addonFonts) do
					if other == font then
						return world.addonFonts[index + 1]
					end
				end
			end
			local P = C.world()
			P.now = 0
			local glancing = C.hit(P, "player", "WOUND", "GLANCING", 20, 1)
			local tail = wordOf(P, glancing)
			check("scrolling: Partial effects: a glancing hit is -20 and its word is a second font string, hidden until the pop is over", glancing.text == "-20" and tail ~= nil and tail.text == "(Glancing)" and not tail.shown, tostring(tail and tail.text))
			C.draw(P, 0.2)
			local p1 = tail.points[1]
			check("scrolling: Partial effects: at 0.2 seconds the word shows, grey, three quarters of the number's height, 4 units to the right of it", tail.shown and C.colour(tail) == "0.7,0.7,0.7" and near(tail.textHeight, 18.75, 1e-9)
				and p1[1] == "LEFT" and p1[2] == glancing and p1[3] == "RIGHT" and p1[4] == 4 and p1[5] == 0 and near(tail.alpha, 1, 1e-9), C.colour(tail) .. " " .. tostring(tail.textHeight))
			check("scrolling: Partial effects: the word has the look of the number", tail.fontObject ~= nil and tail.fontObject == glancing.fontObject, tostring(tail.fontObject) .. " " .. tostring(glancing.fontObject))
			C.draw(P, 1.925)
			check("scrolling: Partial effects: the word fades with the number: half opaque at 1.925 seconds", near(tail.alpha, 0.5, 1e-9) and near(glancing.alpha, 0.5, 1e-9), tostring(tail.alpha))
			local colours = {}
			for _, flag in ipairs({ "CRUSHING", "BLOCK_REDUCED", "ABSORB", "RESIST", "CRITICAL" }) do
				local font = C.hit(P, "player", "WOUND", flag, 20, 1)
				local word = wordOf(P, font)
				C.draw(P, P.now + 0.2)
				colours[#colours + 1] = flag .. "=" .. (word.shown and (word.text .. " " .. C.colour(word)) or "none")
			end
			check("scrolling: Partial effects: Crushing is orange red, Block blue grey, Absorb gold and Resist purple, and a critical hit has no word",
				table.concat(colours, "|") == "CRUSHING=(Crushing) 1,0.4,0.2|BLOCK_REDUCED=(Block) 0.6,0.7,1|ABSORB=(Absorb) 1,0.85,0.4|RESIST=(Resist) 0.79,0.3,0.85|CRITICAL=none", table.concat(colours, "|"))
			local absorbed = C.hit(P, "player", "WOUND", "ABSORB", 0, 1)
			C.draw(P, P.now + 0.2)
			check("scrolling: Partial effects: a word such as Absorb has no second word after it", absorbed.text == "(Absorb)" and not wordOf(P, absorbed).shown, absorbed.text)
			local O = C.world(nil, { options = { ["combattext.partial"] = "off" } })
			O.now = 0
			local plain = C.hit(O, "player", "WOUND", "GLANCING", 20, 1)
			C.draw(O, 0.3)
			check("scrolling: Partial effects: Off gives the number alone, whole size", plain.text == "-20" and plain.textHeight == 25 and not wordOf(O, plain).shown)
			local Sm = C.world(nil, { options = { ["combattext.partial"] = "smaller" } })
			Sm.now = 0
			local small = C.hit(Sm, "player", "WOUND", "GLANCING", 20, 1)
			C.draw(Sm, 0.3)
			check("scrolling: Partial effects: Smaller number only draws a glancing hit at 75 percent with no word", small.text == "-20" and near(small.textHeight, 18.75, 1e-9) and not wordOf(Sm, small).shown)
			local Pw = C.world()
			local popped = C.hit(Pw, "player", "WOUND", "", 20, 1)
			local group = popped.groups and popped.groups[1]
			local steps = group and group.anims or {}
			check("scrolling: the pop: a number scales in Vertex mode, 1 to 1.15 in 0.05 seconds and back in 0.1, and the group is played once",
				group ~= nil and popped.scaleMode == 1 and #steps == 2 and steps[1].order == 1 and steps[1].from[1] == 1 and steps[1].to[1] == 1.15 and steps[1].duration == 0.05
				and steps[2].order == 2 and steps[2].from[1] == 1.15 and steps[2].to[1] == 1 and near(steps[2].duration, 0.1) and group.plays == 1 and popped.justify == "CENTER", tostring(group))
			local Pl = C.world(nil, { options = { ["combattext.pop"] = "plain" } })
			local plainly = C.hit(Pl, "player", "WOUND", "", 20, 1)
			check("scrolling: the pop: How a number appears on Plainly plays no pop in the areas", plainly.groups ~= nil and plainly.groups[1].plays == 0 and plainly.groups[1].stops >= 1, tostring(plainly.groups and plainly.groups[1].plays))
			local Crit = C.world()
			local crit = C.hit(Crit, "player", "WOUND", "CRITICAL", 40, 1)
			check("scrolling: Incoming: a critical hit is a quarter larger: 31.25 at 100%", crit.textHeight == 31.25 and crit.text == "-40", tostring(crit.textHeight))
			-- A font string used again.
			local Re = C.world()
			Re.now = 0
			local first = C.hit(Re, "player", "HEAL", "", 1, 1)
			C.draw(Re, 3)
			local again = C.hit(Re, "player", "HEAL", "", 2, 1)
			check("scrolling: Incoming: a font string is used again after its number has gone, its group is stopped when the number goes and played for the next",
				again == first and first.groups[1].stops >= 1 and first.groups[1].plays == 2 and again.text == "+2")
			-- Where the start comes from.
			local Pool = C.world()
			Pool.now = 0
			Pool.ns.MoverSpot = nil
			local fallback = C.hit(Pool, "player", "HEAL", "", 1, 1)
			check("scrolling: Incoming: with no handle the start is the middle of the screen moved 170 left and 30 down", C.spot(fallback) == "CENTER BOTTOMLEFT 790 510", C.spot(fallback))
			Pool.uiInner.width, Pool.uiInner.height = nil, nil
			local none = C.hit(Pool, "player", "HEAL", "", 2, 1)
			check("scrolling: Incoming: with no handle and no screen size no number shows, and nothing fails", none == nil and C.quiet(Pool), C.trouble(Pool))
			local Err = C.world()
			Err.pointFault = true
			for index = 1, 3 do
				C.hit(Err, "player", "HEAL", "", index, 1)
			end
			check("scrolling: Incoming: a number that raises an error is counted, shows nothing and does not stop the module", has(Err.status(), "Numbers in the Incoming scroll area that raised an error: 3. The first: SetPoint failed")
				and not Err.ns.IsStopped("combattext") and C.shownCount(Err) == 0, Err.status())
			check("scrolling: Incoming: where the numbers for the player start: no violations, errors or messages",
				#W.violations == 0 and #W.errors == 0 and C.quiet(D) and C.quiet(A) and C.quiet(Sa) and C.quiet(R) and C.quiet(Hz) and C.quiet(St) and C.quiet(P) and C.quiet(O) and C.quiet(Re), C.trouble(W))
		end

		-- The Outgoing scroll area: which reports it takes, where it starts and how it moves.
		do
			local function world(where, more)
				local options = { ["combattext.where"] = where }
				for key, value in pairs(more or {}) do
					options[key] = value
				end
				return C.world(nil, { options = options })
			end
			-- The number font strings, with the ones that hold a word after a number left out.
			local function numbers(W)
				local list = {}
				for _, font in ipairs(W.addonFonts) do
					local p = font.points[1]
					local word = p and p[1] == "LEFT" and p[3] == "RIGHT" and type(p[2]) == "table" and p[2].kind == "FontString"
					if not word then
						list[#list + 1] = font
					end
				end
				return list
			end
			local S = world("scroll", { ["combattext.outStyle"] = "straight" })
			S.now = 0
			local viaPlate = C.hit(S, "nameplate1", "WOUND", "", 412)
			local viaTarget = C.hit(S, "target", "WOUND", "", 412)
			check("scrolling: Outgoing: Scroll area takes the report of the target and leaves the nameplate's, so one enemy gives one copy: 412 in white, 35 high, at the handle to the right of the character",
				viaPlate == nil and viaTarget ~= nil and viaTarget.text == "412" and C.colour(viaTarget) == "1,1,1" and viaTarget.textHeight == 35 and C.spot(viaTarget) == "CENTER BOTTOMLEFT 1130 510" and #S.addonFonts == 2,
				C.spot(viaTarget))
			check("scrolling: Outgoing: the first hit switches the game's rows for damage over enemies off, as the numbers over enemies do", C.rows(S) == "0000", C.rows(S))
			C.draw(S, 0.95)
			check("scrolling: Outgoing: Straight goes up 103.64 units in 0.95 seconds and not sideways", near(viaTarget.points[1][5], 510 + 240 * 0.95 / 2.2, 1e-9) and near(viaTarget.points[1][4], 1130), C.spot(viaTarget))
			S.attackable.target = false
			local friendly = C.hit(S, "target", "WOUND", "", 5)
			S.attackable.target = nil
