				friendly == nil and heal == nil and miss ~= nil and miss.text == "(Miss)" and crit.textHeight == 43.75 and C.colour(magic) == "1,1,0", tostring(miss and miss.text))
			local glancing = C.hit(S, "target", "WOUND", "GLANCING", 412)
