			local kept = C.hit(O, "target", "WOUND", "", 2)
			local second = C.hit(O, "target", "WOUND", "", 3)
			check("scrolling: Outgoing: Whose hits applies: with One hit for each of yours a hit with no cast is left out, a cast gives one hit and the next is left out", left == nil and kept ~= nil and second == nil,
				tostring(left) .. " " .. tostring(kept) .. " " .. tostring(second))
			local Z = world("scroll", { ["combattext.outStyle"] = "arc", ["combattext.arcWidth"] = "narrow" })
