			for _, font in ipairs(Q.addonFonts) do
				if font.owner.strata == "MEDIUM" then
					owned = owned + 1
				end
			end
			check("scrolling: five numbers for the player after twenty-five over enemies are five records of their own, and every number is shown", five[5] ~= nil and owned == 10 and #Q.addonFonts == 35 and C.shownCount(Q) == 30 and C.quiet(Q), owned .. " " .. #Q.addonFonts)
			local S = C.world()
			local alive = C.hit(S, "player", "HEAL", "", 1, 1)
			local over = C.hit(S, "nameplate1", "WOUND", "", 2)
			S.ns.Set("combattext.source", "game")
			check("ctlook: Numbers over enemies set to As the game has them takes the numbers over enemies off the screen and leaves the number for the player", alive.shown and not over.shown)
			local G = C.world()
			G.now = 0
			local home = C.hit(G, "player", "HEAL", "", 300, 1)
			local away = C.hit(G, "nameplate1", "WOUND", "", 5)
			G.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
			local gQuiet = C.quiet(G)
			check("ctlook: a nameplate that goes leaves the number for the player where it is, and only the number over the enemy is kept on the screen", home.shown and away.shown and C.spot(home) == "CENTER BOTTOMLEFT 790 510"
				and has(G.slash("combat"), "Numbers kept after their nameplate went: 1. Removed with it: 0."), C.spot(home) .. " " .. G.slash("combat"))
			check("ctlook: /flatui combat after a nameplate goes: no violations or errors", #G.violations == 0 and #G.errors == 0, C.trouble(G))
			local A = C.world()
			local stays = C.hit(A, "player", "HEAL", "", 300, 1)
			local leaves = C.hit(A, "nameplate1", "WOUND", "", 5)
			A.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
			check("ctlook: a nameplate that gets a unit hides the numbers over it and leaves the number for the player", stays.shown and not leaves.shown, tostring(stays.shown) .. " " .. tostring(leaves.shown))
			check("ctlook: the pools and the plates: no violations, errors or messages", C.quiet(P) and C.quiet(Q) and C.quiet(S) and gQuiet and C.quiet(A), C.trouble(P) .. C.trouble(Q) .. C.trouble(S) .. C.trouble(A))
		end

		-- The look, the reports for the player, the page and the handle: what the first tests of 0.4.7 left open.
		do
			local T = {}
			-- The literal file of Friz Quadrata is used where the game's face font gives none.
			T.F = C.world(nil, nil, function(X)
				X.fontObjects.CombatTextFont.font[1] = ""
			end)
			T.fz = C.hit(T.F, "nameplate1", "WOUND", "", 1)
			check("ctlook: a face font object that gives an empty file is as good as none for Friz Quadrata too, and the file named for it is Friz Quadrata's",
				T.fz ~= nil and K.brief(K.object(T.F, T.fz)) == "Fonts\\FRIZQT__.TTF[]" and C.quiet(T.F), C.trouble(T.F))
			-- A refused font is worked out once: later numbers touch no line of the status.
			T.R = C.world(nil, nil, function(X)
				X.fontFiles["fonts\\skurri.ttf"] = nil
			end)
			T.R.ns.Set("combattext.font", "skurri")
			C.hit(T.R, "nameplate1", "WOUND", "", 1)
			T.calls = 0
			for _, name in ipairs({ "Note", "ClearNote" }) do
				local original = T.R.ns[name]
				T.R.ns[name] = function(...)
					T.calls = T.calls + 1
					return original(...)
				end
			end
			C.hit(T.R, "nameplate1", "WOUND", "", 2)
			C.hit(T.R, "player", "HEAL", "", 3, 1)
			check("ctlook: with a refused font the look is not worked out again for the next numbers: the line about it is not taken back and said again", T.calls == 0 and count(T.R.status(), K.refused) == 1, T.calls .. " " .. T.R.status())
			-- The last font is the game's own font object, which a font string is given as an object.
			T.N = C.world(nil, nil, function(X)
				X.fontFault = "false"
			end)
			T.plain = C.hit(T.N, "nameplate1", "WOUND", "", 1)
			T.N.ns.Set("combattext.outline", "thick")
			T.thick = C.hit(T.N, "nameplate1", "WOUND", "", 2)
			check("ctlook: the game's combat font a number falls back to is given to the font string as the font object itself, and not as its name",
				type(T.plain.fontObjectValue) == "table" and rawequal(T.plain.fontObjectValue, T.N.fontObjects.CombatTextFont)
				and type(T.thick.fontObjectValue) == "table" and rawequal(T.thick.fontObjectValue, T.N.fontObjects.CombatTextFontOutline), type(T.plain.fontObjectValue) .. " " .. type(T.thick.fontObjectValue))
			-- The counts for the player: reports and numbers shown are two numbers.
			T.W = C.world()
			C.hit(T.W, "player", "HEAL", "", 300, 1)
			C.hit(T.W, "player", "WOUND", "", 5, 1)
			C.hit(T.W, "vehicle", "WOUND", "", 7, 1)
			T.said = T.W.slash("combat")
			check("ctlook: three hit reports for the player and two numbers shown: the status says 2 shown", has(T.W.status(), "Combat text for you: 2 shown."), T.W.status())
			check("ctlook: and /flatui combat says 3 hit reports and 2 shown, in that order", has(T.said, "Hit reports for you: 3. Shown: 2.\n"), T.said)
			-- The first mistake in the text for the player is the one the status keeps.
			T.B = C.world()
			T.n = 0
			T.B.ns.MoverSpot = function()
				T.n = T.n + 1
				error(T.n == 1 and "first mistake" or "second mistake", 0)
			end
			C.hit(T.B, "player", "HEAL", "", 1, 1)
			C.hit(T.B, "player", "HEAL", "", 2, 1)
			check("ctlook: of two mistakes in the player's text the status counts both and gives the first", has(T.B.status(), "Numbers in the Incoming scroll area that raised an error: 2. The first: first mistake"), T.B.status())
			-- A record whose value is back is dropped by /flatui combat reset.
			T.Q = C.world({ cvars = { enableFloatingCombatText = "1" } })
			T.Q.cvarRefuse.enableFloatingCombatText = true
			T.Q.slash("combat reset")
			T.kept = T.Q.env.FlatUIDB.cvars and T.Q.env.FlatUIDB.cvars.enableFloatingCombatText
			T.Q.cvarRefuse.enableFloatingCombatText = nil
			T.Q.cvars.enableFloatingCombatText = "1"
			T.Q.slash("combat reset")
			check("ctlook: /flatui combat reset drops the record of the game's text once the game's own value is back", T.kept ~= nil and (T.Q.env.FlatUIDB.cvars == nil or T.Q.env.FlatUIDB.cvars.enableFloatingCombatText == nil),
				tostring(T.kept) .. " " .. tostring(T.Q.env.FlatUIDB.cvars and T.Q.env.FlatUIDB.cvars.enableFloatingCombatText))
			-- The page: the steps and the unit of the size of the player's text, and the tip of Font.
			T.items = {}
			for _, page in ipairs(T.W.ns.PAGES) do
				if page.key == "combattext" then
					for _, item in ipairs(page) do
						if item.key then
							T.items[item.key] = item
						end
					end
				end
			end
			check("ctlook: Size of your text goes from 40 to 400 in steps of 10, in percent", T.items.ownSize.step == 10 and T.items.ownSize.unit == "%" and T.items.ownSize.min == 40 and T.items.ownSize.max == 400,
				tostring(T.items.ownSize.step) .. " " .. tostring(T.items.ownSize.unit))
			check("ctlook: Font says it is for numbers in front of nameplates, the Outgoing area and the player's text", T.items.font.tip == "For numbers in front of nameplates, the Outgoing scroll area and your own text.", tostring(T.items.font.tip))
		end

		-- In combat, and with the page or Combat text for you switched off.
		do
			local W = C.world()
			W.combat = true
			W.cplate.protected = true
			local mine = C.hit(W, "player", "WOUND", "", 412, 1)
			local theirs = C.hit(W, "nameplate1", "WOUND", "", 413)
			check("ctlook: in combat a hit on the player shows its number on the frame of the addon's own on UIParent, anchored to UIParent only, and nothing is made on a protected frame",
				mine ~= nil and mine.owner.parent == W.env.UIParent and mine.points[1][2] == W.env.UIParent and #mine.points == 1 and #W.violations == 0 and #W.errors == 0 and W.cplate.regions == nil, C.trouble(W))
			W.combat = false
			W.ns.Set("combattext.own", "off")
			check("ctlook: Combat text for you Off takes the player's numbers off the screen and leaves the numbers over enemies in the air", not mine.shown and theirs.shown and C.running(W) == 1)
			W.ns.Set("combattext.own", "more")
			local again = C.hit(W, "player", "HEAL", "", 5, 1)
			W.ns.Set("combattext.enabled", false)
			check("ctlook: the page off takes both kinds off the screen", not again.shown and not theirs.shown and C.running(W) == 0 and not W.ns.CombatOwnShown())
			W.ns.Set("combattext.enabled", true)
			check("ctlook: CombatOwnShown is true with the page on and Combat text for you not Off", W.ns.CombatOwnShown() == true)
			W.ns.Set("combattext.own", "off")
			check("ctlook: and false with Combat text for you Off", W.ns.CombatOwnShown() == false)
		end

		-- Where the number starts without a spot from the movers.
		do
			local W = C.world()
			W.ns.MoverSpot = nil
			local middle = C.hit(W, "player", "HEAL", "", 1, 1)
			check("ctlook: without a spot from the movers the number starts at the middle of UIParent moved to where the handle starts", middle ~= nil and C.spot(middle) == "CENTER BOTTOMLEFT 790 510", C.spot(middle))
			local V = C.world(nil, nil, function(X)
				X.uiInner.width, X.uiInner.height = nil, nil
			end)
			V.ns.MoverSpot = nil
			local none = C.hit(V, "player", "HEAL", "", 1, 1)
			check("ctlook: and where the screen has no size, no number is shown, the status counts it and the module goes on", none == nil and has(V.status(), "Numbers the game would not position: 1.") and not V.ns.IsStopped("combattext") and C.quiet(V),
				V.status())
			local T0 = C.world()
			T0.ns.MoverSpot = nil
			T0.uiInner.width, T0.uiInner.height = 0, 0
			check("ctlook: and where the screen is 0 by 0, no number is shown either", C.hit(T0, "player", "HEAL", "", 1, 1) == nil and has(T0.status(), "Numbers the game would not position: 1.") and C.quiet(T0), T0.status())
			local P0 = C.world()
			P0.ns.MoverSpot = nil
			P0.uiInner.width, P0.uiInner.height = nil, nil
			local failed = C.hit(P0, "player", "HEAL", "", 1, 1)
			P0.uiInner.width, P0.uiInner.height = 1920, 1080
			local theirs = C.hit(P0, "nameplate1", "WOUND", "", 2)
			local mine = C.hit(P0, "player", "HEAL", "", 3, 1)
			check("ctlook: a number for the player that could not be placed goes back to the pool of the player and not to the pool of the numbers over enemies", failed == nil and theirs ~= nil and theirs.owner.strata == "LOW"
				and mine ~= nil and mine.owner.strata == "MEDIUM" and C.quiet(P0), C.trouble(P0))
			local B = C.world()
			B.ns.MoverSpot = function() error("broken", 0) end
			C.hit(B, "player", "HEAL", "", 1, 1)
			check("ctlook: a mistake in the player's text is counted and does not stop the module or the numbers over enemies", has(B.status(), "Numbers in the Incoming scroll area that raised an error: 1. The first: broken") and not B.ns.IsStopped("combattext")
				and C.say(B, "nameplate1", "WOUND", "", 5) == "5", B.status())
		end

		-- The game's own text for the player.
		do
			local function world(value, saved)
				return C.world({ cvars = { enableFloatingCombatText = value } }, saved)
			end
			local W = world("1")
			check("ctlook: with the game's text for the player on at login and Combat text for you on, the variable is written 0 and the 1 is remembered before the write", W.cvars.enableFloatingCombatText == "0"
				and K.writes(W) == "0<1" and W.env.FlatUIDB.cvars.enableFloatingCombatText.game == "1" and W.env.FlatUIDB.cvars.enableFloatingCombatText.wrote == "0", K.writes(W))
			W.ns.Set("combattext.own", "off")
			check("ctlook: Off puts the 1 back and drops the record", W.cvars.enableFloatingCombatText == "1" and (W.env.FlatUIDB.cvars == nil or W.env.FlatUIDB.cvars.enableFloatingCombatText == nil), tostring(W.cvars.enableFloatingCombatText))
			W.ns.Set("combattext.own", "take")
			check("ctlook: and choosing it again writes 0 once more, with the 1 remembered again", W.cvars.enableFloatingCombatText == "0" and K.writes(W) == "0<1,1<1,0<1", K.writes(W))
			W.ns.Set("combattext.enabled", false)
			check("ctlook: the page off puts the 1 back", W.cvars.enableFloatingCombatText == "1" and (W.env.FlatUIDB.cvars == nil or W.env.FlatUIDB.cvars.enableFloatingCombatText == nil))
			W.ns.Set("combattext.enabled", true)
			W.fire("PLAYER_LOGOUT")
			local rec = W.env.FlatUIDB.cvars and W.env.FlatUIDB.cvars.enableFloatingCombatText
			check("ctlook: logout puts the 1 back and the record stays for the next login", W.cvars.enableFloatingCombatText == "1" and rec ~= nil and rec.game == "1" and rec.wrote == "0", tostring(W.cvars.enableFloatingCombatText))
			local N = C.world({ cvars = { enableFloatingCombatText = W.cvars.enableFloatingCombatText } }, W.env.FlatUIDB)
			check("ctlook: and the next login writes 0 again, with the same 1 remembered", N.cvars.enableFloatingCombatText == "0" and N.env.FlatUIDB.cvars.enableFloatingCombatText.game == "1", tostring(N.cvars.enableFloatingCombatText))
			local Z = world("0")
			check("ctlook: with the variable at 0 at login nothing is written to it and nothing is remembered", K.writes(Z) == "" and Z.cvars.enableFloatingCombatText == "0" and (Z.env.FlatUIDB.cvars == nil or Z.env.FlatUIDB.cvars.enableFloatingCombatText == nil))
			C.hit(Z, "player", "WOUND", "", 5, 1)
			Z.slash("combat reset")
			check("ctlook: /flatui combat reset makes no write to it", K.writes(Z) == "" and Z.cvars.enableFloatingCombatText == "0")
			local R = world("1")
			local said = R.slash("combat reset")
			check("ctlook: /flatui combat reset with the game's text on before: the page goes off, the 1 is back, the line for the variable is not in what it printed and no record is left",
				R.cvars.enableFloatingCombatText == "1" and not has(said, "enableFloatingCombatText") and said == "Place combat numbers: off. The game's defaults are back, except Scrolling Combat Text for Self, which stays as you have it." and (R.env.FlatUIDB.cvars == nil or R.env.FlatUIDB.cvars.enableFloatingCombatText == nil), said)
			local Q = world("1")
			Q.cvarRefuse.enableFloatingCombatText = true
			Q.slash("combat reset")
			local kept = Q.env.FlatUIDB.cvars and Q.env.FlatUIDB.cvars.enableFloatingCombatText
			check("ctlook: and when the game refuses that write, the remembered 1 is kept until it is back", Q.cvars.enableFloatingCombatText == "0" and kept ~= nil and kept.game == "1", tostring(Q.cvars.enableFloatingCombatText))
			local Q2 = world("1")
			-- The record of WorldTextScale_v2 is made at the login, before the game is made to refuse the write back, and it is still there when the page goes off.
			local scale = Q2.env.FlatUIDB.cvars and Q2.env.FlatUIDB.cvars.WorldTextScale_v2
			Q2.cvarRefuse.enableFloatingCombatText = true
			Q2.cvarRefuse.WorldTextScale_v2 = true
			Q2.slash("combat reset")
			local left = Q2.env.FlatUIDB.cvars
			check("ctlook: and it keeps no other record: a variable of the numbers over enemies, written at the login at 1.4, that the game refused to put back is dropped", scale ~= nil and scale.wrote == "1.4" and Q2.cvars.WorldTextScale_v2 == "1.4"
				and left ~= nil and left.enableFloatingCombatText ~= nil and left.WorldTextScale_v2 == nil, tostring(scale and scale.wrote) .. " " .. tostring(Q2.cvars.WorldTextScale_v2) .. " " .. tostring(left and left.WorldTextScale_v2))
			local U = world("1")
			U.cvarFault = "secret"
			U.slash("combat reset")
			local held = U.env.FlatUIDB.cvars and U.env.FlatUIDB.cvars.enableFloatingCombatText
			check("ctlook: /flatui combat reset keeps the remembered 1 when the game does not say what the variable holds now", held ~= nil and held.game == "1", tostring(held))
			Q.cvarRefuse.enableFloatingCombatText = nil
			Q.fire("PLAYER_LOGIN")
			check("ctlook: the next time the module's own frame looks at the variables the 1 is written back and the record goes", Q.cvars.enableFloatingCombatText == "1" and (Q.env.FlatUIDB.cvars == nil or Q.env.FlatUIDB.cvars.enableFloatingCombatText == nil),
				tostring(Q.cvars.enableFloatingCombatText))
			local T = world("0")
			T.setCVarByPlayer("enableFloatingCombatText", "1")
			check("ctlook: the game's text ticked during the session: the status says the numbers show twice and that /reload unticks it", has(T.status(), "Scrolling Combat Text for Self is ticked in the game's options, so your numbers show twice. /reload unticks it."), T.status())
			T.ns.Set("combattext.partial", "off")
			check("ctlook: and the next change of a setting writes 0 again and takes the line away", T.cvars.enableFloatingCombatText == "0" and not has(T.status(), "Scrolling Combat Text for Self"), T.status())
			local O = world("1")
			O.ns.Set("combattext.own", "off")
			O.setCVarByPlayer("enableFloatingCombatText", "1")
			check("ctlook: with Combat text for you Off the variable is the player's and the status says nothing about it", not has(O.status(), "Scrolling Combat Text for Self") and O.cvars.enableFloatingCombatText == "1")
			local C2 = world("1", { options = { ["combattext.enabled"] = false } })
			check("ctlook: with the page off at login nothing is written", K.writes(C2) == "" and C2.cvars.enableFloatingCombatText == "1")
			check("ctlook: the text for the player: no violations or errors", #W.violations + #W.errors + #N.violations + #N.errors + #Z.violations + #Z.errors + #R.violations + #R.errors + #T.violations + #T.errors == 0, C.trouble(W) .. C.trouble(T))
		end

		-- The words on the screen.
		do
			local W = C.world()
			local screen = {}
			local function take(text)
				for line in (text .. "\n"):gmatch("([^\n]*)\n") do
					if not line:find("^Flat UI ") then
						screen[#screen + 1] = line
					end
				end
			end
			W.ns.Set("combattext.font", "skurri")
			W.fontFiles["fonts\\skurri.ttf"] = nil
			C.hit(W, "player", "WOUND", "", SECRET, 1)
			C.hit(W, "player", "WOUND", SECRET, 5, 1)
			W.setCVarByPlayer("enableFloatingCombatText", "1")
			W.ns.MoverSpot = function() error("broken", 0) end
			C.hit(W, "player", "WOUND", "", 5, 1)
			take(W.status())
			take(W.slash("combat"))
			W.ns.Set("combattext.own", "off")
			W.units.target = nil
			take(W.slash("combat test"))
			local found, banned = {}, { "carries", "carry", "sits", "lives in", "lands", "runs through", "ensure", "simply", "easily", "flat ui", "addon", "the system", "\226\128\148", "\226\128\147" }
			for _, text in ipairs(screen) do
				for _, word in ipairs(banned) do
					if text:lower():find(word, 1, true) then
						found[#found + 1] = word .. " in " .. text
					end
				end
			end
			check("ctlook: every line about the look, the text for the player and the game's own text: none of the banned words, no dash and no name of the addon", #found == 0 and #screen > 20, #screen .. " " .. table.concat(found, " | "))
		end
	end


	-- ctfriend: combat numbers over friendly units (research/flatui-combat/friendly-numbers-design.md).
	do
		local F = { HEAL = "floatingCombatTextCombatHealing_v2", ALL = { "frames", "plates", "both" } }
		-- A world where nameplate1 is a friendly unit and nameplate2 an enemy, with the plates' unit tokens.
		function F.world(saved, more)
			local W = C.world(more, saved)
			W.cplate.unitToken, W.cplate2.unitToken = "nameplate1", "nameplate2"
			W.attackable.nameplate1 = false
			return W
		end
		-- Party member frames party1 and party2 (as the game's party frame pool lists them), the pet frame and raid frames raid1 to raid25.
		-- Returns the frames by unit and their raw tables.
		function F.frames(W, withRaid)
			local pool, raw = newPool(W)
			W.env.PartyFrame = W.B(nil, { PartyMemberFramePool = pool }, { name = "PartyFrame" })
			local by, raws = {}, {}
			for _, unit in ipairs({ "party1", "party2" }) do
				by[unit], raws[unit] = W.B(nil, { unit = unit }, { name = "Member" .. unit })
				raw.items[#raw.items + 1] = by[unit]
			end
			by.pet, raws.pet = W.B(nil, { unit = "pet" }, { name = "PetFrame" })
			W.env.PetFrame = by.pet
			if withRaid then
				for index = 1, 25 do
					by["raid" .. index], raws["raid" .. index] = W.B(nil, { unit = "raid" .. index }, { name = "CompactRaidFrame" .. index })
					W.env["CompactRaidFrame" .. index] = by["raid" .. index]
				end
			end
			return by, raws
		end
		function F.col(font)
			if not font then
				return "none"
			end
			local c = font.textColour
			return ("%.2f,%.2f,%.2f"):format(c[1], c[2], c[3])
		end
		function F.heal(W)
			local n = 0
			for _, write in ipairs(W.cvarWrites) do
				if write.name == F.HEAL then
					n = n + 1
				end
			end
			return n
		end
		function F.points(font)
			local p = font and font.points[1]
			return p and p[1] .. " " .. p[3] .. " " .. g(p[4]) .. " " .. g(p[5]) or "none"
		end
		function F.row(W, key)
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "combattext" then
					for _, item in ipairs(page) do
						if item.key == key then
							return item
						end
					end
				end
			end
		end

		-- Defaults and rows.
		do
			local W = C.world()
			local d = {}
			for _, key in ipairs({ "friend", "friendUnits", "friendDamage", "friendHeal", "friendPet", "friendWords", "friendSigns", "friendSize", "friendHeight", "friendDamageColour", "friendHealColour" }) do
				d[#d + 1] = tostring(W.ns.Get("combattext." .. key))
			end
			check("ctfriend: the defaults are Both, Every friendly unit, damage on, Healing they take from anyone, pet on, words off, signs on, 100%, 10 and the two colours",
				table.concat(d, ",") == "both,all,true,taken,true,false,true,100,10,ffff1a1a,ff1aff1a", table.concat(d, ","))
			local labels, kinds = {}, {}
			local last
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "combattext" then
					local on = false
					for _, item in ipairs(page) do
						if item.section == "Friendly units" then
							on = true
						elseif item.section then
							on = false
						elseif on then
							labels[#labels + 1] = item.label
							kinds[#kinds + 1] = item.kind
						end
					end
				end
			end
			check("ctfriend: the rows of Friendly units, in order, with their kinds", table.concat(labels, "|") == "Where friendly numbers show|Friendly units|Damage friendly units take|Healing over friendly units|Your pet|Misses and dodges over friendly units|Plus and minus signs|Friendly damage colour|Friendly healing colour|Size over friendly units|Height above frames"
				and table.concat(kinds, ",") == "choice,choice,bool,choice,bool,bool,bool,colour,colour,number,number", table.concat(labels, "|") .. " " .. table.concat(kinds, ","))
			local row = F.row(W, "friend")
			check("ctfriend: Where friendly numbers show has Off, Party and raid frames, Friendly nameplates and Both",
				#row.choices == 4 and row.choices[1][2] == "Off" and row.choices[2][2] == "Party and raid frames" and row.choices[3][2] == "Friendly nameplates" and row.choices[4][2] == "Both")
			local heal = F.row(W, "friendHeal")
			check("ctfriend: Healing over friendly units has three choices",
				#heal.choices == 3 and heal.choices[1][2] == "Healing they take from anyone" and heal.choices[2][2] == "Healing you do" and heal.choices[3][2] == "Off")
			local needs = true
			for _, key in ipairs({ "friendUnits", "friendDamage", "friendHeal", "friendPet", "friendWords", "friendSigns", "friendDamageColour", "friendHealColour", "friendSize", "friendHeight" }) do
				local item = F.row(W, key)
				local want = key == "friendHeight" and "frames,both" or "frames,plates,both"
				needs = needs and item.needs == "friend" and table.concat(item.needsIn, ",") == want
			end
			check("ctfriend: every row after Where friendly numbers show needs it not Off, and Height above frames needs frames or both", needs and F.row(W, "friend").needs == nil)
			check("ctfriend: Height above the enemy says it is also the height over friendly nameplates",
				F.row(W, "height").tip == "With As the game has them, 40 is the game's own height. Also the height over friendly nameplates.")
			local ok = true
			for _, key in ipairs({ "friendSize", "friendHeight" }) do
				local item = F.row(W, key)
				ok = ok and item.kind == "number"
			end
			check("ctfriend: Size over friendly units goes from 40 to 400 in tens and Height above frames from 0 to 100 in fives",
				ok and F.row(W, "friendSize").min == 40 and F.row(W, "friendSize").max == 400 and F.row(W, "friendSize").step == 10 and F.row(W, "friendHeight").min == 0
				and F.row(W, "friendHeight").max == 100 and F.row(W, "friendHeight").step == 5)
		end

		-- Numbers over a friendly nameplate.
		do
			local W = F.world()
			local hurt = C.hit(W, "nameplate1", "WOUND", "", 412)
			check("ctfriend: damage on a friendly nameplate shows -412 in the damage colour", hurt and hurt.text == "-412" and F.col(hurt) == "1.00,0.10,0.10", hurt and hurt.text)
			W.now = W.now + 0.1
			local healed = C.hit(W, "nameplate1", "HEAL", "", 300)
			check("ctfriend: a heal on a friendly nameplate shows +300 in the healing colour", healed and healed.text == "+300" and F.col(healed) == "0.10,1.00,0.10", healed and healed.text)
			W.ns.Set("combattext.friendSigns", false)
			W.now = W.now + 0.1
			local bare = C.hit(W, "nameplate1", "WOUND", "", 55)
			check("ctfriend: with Plus and minus signs off the number has no sign", bare and bare.text == "55", bare and bare.text)
			W.ns.Set("combattext.friendSigns", true)
			W.ns.Set("combattext.friendDamageColour", "ff0000ff")
			W.now = W.now + 0.1
			local blue = C.hit(W, "nameplate1", "WOUND", "", 56)
			check("ctfriend: Friendly damage colour sets the colour", F.col(blue) == "0.00,0.00,1.00")
			W.ns.Set("combattext.school", true)
			W.now = W.now + 0.1
			local fire = C.hit(W, "nameplate1", "WOUND", "", 57, 4)
			check("ctfriend: Colour by school of magic takes the place of Friendly damage colour", F.col(fire) == "1.00,0.50,0.00")
			W.ns.Set("combattext.school", false)
			W.now = W.now + 0.1
			local crush = C.hit(W, "nameplate1", "WOUND", "CRUSHING", 58)
			check("ctfriend: Kind of hit in parentheses follows over a friendly unit", crush and crush.text == "-58 (Crushing)", crush and crush.text)
			check("ctfriend: friendly numbers raise no violation, error or message", C.quiet(W), C.trouble(W))
		end

		-- Enemies are unchanged.
		do
			local W = F.world()
			local enemy = C.hit(W, "nameplate2", "WOUND", "", 412)
			check("ctfriend: an enemy plate shows 412 with no sign in the enemy colour and size", enemy and enemy.text == "412" and F.col(enemy) == "1.00,1.00,1.00" and enemy.textHeight == 35, enemy and enemy.text)
			W.ns.Set("combattext.units", "target")
			W.units.target = W.cplate2
			local other = { C.say(W, "nameplate2", "WOUND", "", 5), C.say(W, "nameplate1", "WOUND", "", 6) }
			W.units.target = W.cplate
			local second = C.say(W, "nameplate2", "WOUND", "", 7)
			check("ctfriend: Enemies Target only still drops the other enemy, and does not touch a friendly unit", other[1] == "5" and other[2] == "-6" and second == "none", table.concat(other, ",") .. " " .. second)
		end

		-- Modes.
		do
			local W = F.world()
			W.ns.Set("combattext.friend", "off")
			local off = { C.say(W, "nameplate1", "WOUND", "", 1), C.say(W, "party1", "WOUND", "", 2) }
			check("ctfriend: Off shows nothing and the count of friendly plates still counts", off[1] == "none" and off[2] == "none" and has(W.slash("combat"), "On friendly units: 1."), table.concat(off, ","))
			local by = F.frames(W)
			W.ns.Set("combattext.friend", "frames")
			local plate, member = C.hit(W, "nameplate1", "WOUND", "", 3), C.hit(W, "party1", "WOUND", "", 4)
			check("ctfriend: party and raid frames: a friendly plate shows nothing and a party1 report shows over the party frame", plate == nil and member and member.text == "-4" and member.points[1][2] == by.party1, plate and plate.text)
			W.ns.Set("combattext.friend", "plates")
			local gone, shown = C.hit(W, "party1", "WOUND", "", 5), C.hit(W, "nameplate1", "WOUND", "", 6)
			check("ctfriend: friendly nameplates: a party1 report shows nothing and a friendly plate shows", gone == nil and shown and shown.text == "-6")
			W.ns.Set("combattext.friend", "both")
			W.alias.party2 = "nameplate1"
			W.now = W.now + 1
			local viaPlate, viaToken, viaFrame = C.hit(W, "nameplate1", "WOUND", "", 7), C.hit(W, "party2", "WOUND", "", 8), C.hit(W, "party1", "WOUND", "", 9)
			check("ctfriend: both: a unit with a plate and party1 shows once, over the plate, and a unit with no plate shows over its frame",
				viaPlate and viaPlate.text == "-7" and viaToken == nil and viaFrame and viaFrame.text == "-9" and viaFrame.points[1][2] == by.party1 and has(W.slash("combat"), "Repeated reports skipped: 1."), W.slash("combat"))
		end

		-- The other settings.
		do
			local W = F.world()
			W.ns.Set("combattext.source", "game")
			check("ctfriend: Numbers over enemies set to As the game has them still shows friendly numbers and no enemy number", C.say(W, "nameplate1", "WOUND", "", 3) == "-3" and C.say(W, "nameplate2", "WOUND", "", 4) == "none")
			W.change("combattext.enabled", false)
			check("ctfriend: Place combat numbers off shows no friendly number", C.say(W, "nameplate1", "WOUND", "", 5) == "none")
		end

		-- Target only.
		do
			local W = F.world()
			W.attackable.nameplate3 = false
			W.cplate3 = W.newPlate()
			W.cplate3.unitToken = "nameplate3"
			W.showPlate("nameplate3", W.cplate3)
			W.ns.Set("combattext.friendUnits", "target")
			local both = { C.say(W, "nameplate1", "WOUND", "", 1), C.say(W, "nameplate3", "WOUND", "", 2) }
			check("ctfriend: Friendly units Target only: the target's plate shows and another friendly plate shows nothing", both[1] == "-1" and both[2] == "none", table.concat(both, ","))
			check("ctfriend: and an enemy is not touched by it", C.say(W, "nameplate2", "WOUND", "", 3) == "3")
			W.ns.Set("combattext.friend", "frames")
			F.frames(W)
			W.alias.party1 = "nameplate1"
			local group = { C.say(W, "party1", "WOUND", "", 4), C.say(W, "party2", "WOUND", "", 5) }
			check("ctfriend: Target only for a group unit: the one UnitIsUnit says is the target shows, the other does not", group[1] == "-4" and group[2] == "none", table.concat(group, ","))
			W.sameFault = "secret"
			local unknown = C.say(W, "party2", "WOUND", "", 6)
			check("ctfriend: a withheld UnitIsUnit shows the number and counts it, and the status and the report say so", unknown == "-6" and has(W.status(), "Could not tell whether 1 friendly numbers were on your target. They showed anyway.")
				and has(W.slash("combat"), "Target check failed: 1."), W.status())
			W.sameFault = nil
			W.ns.Set("combattext.friendUnits", "all")
			W.ns.Set("combattext.units", "target")
			W.units.target = W.cplate2
			W.ns.Set("combattext.friend", "plates")
			check("ctfriend: Enemies Target only does not touch friendly numbers: a friendly plate that is not the target shows", C.say(W, "nameplate3", "WOUND", "", 7) == "-7")
		end

		-- The pet.
		do
			local W = F.world()
			local by = F.frames(W)
			W.ns.Set("combattext.friend", "frames")
			local pet = C.hit(W, "pet", "WOUND", "", 90)
			check("ctfriend: a pet report shows over the pet frame with Your pet on", pet and pet.text == "-90" and pet.points[1][2] == by.pet)
			W.ns.Set("combattext.friendPet", false)
			W.now = W.now + 1
			check("ctfriend: and nothing with Your pet off", C.say(W, "pet", "WOUND", "", 91) == "none")
			W.ns.Set("combattext.friend", "both")
			W.owned.nameplate1 = true
			check("ctfriend: a friendly plate that is the player's own pet follows Your pet", C.say(W, "nameplate1", "WOUND", "", 92) == "none")
			W.ns.Set("combattext.friendPet", true)
			W.now = W.now + 1
			W.alias.pet = "nameplate1"
			local viaPlate, viaToken = C.hit(W, "nameplate1", "WOUND", "", 93), C.hit(W, "pet", "WOUND", "", 94)
			check("ctfriend: and the pet with a plate shows once, over the plate", viaPlate and viaPlate.text == "-93" and viaToken == nil)
			W.owned.nameplate1 = false
			W.now = W.now + 1
			local notMine = C.hit(W, "pet", "WOUND", "", 95)
			check("ctfriend: a plate of a unit the player does not own is not the pet's, so the pet shows over its frame", notMine and notMine.points[1][2] == by.pet, notMine and F.points(notMine))
		end

		-- Words.
		do
			local W = F.world()
			check("ctfriend: a miss over a friendly unit shows nothing with Misses and dodges over friendly units off", C.say(W, "nameplate1", "WOUND", "", 0) == "none" and C.say(W, "nameplate1", "DODGE", "", 0) == "none")
			W.ns.Set("combattext.friendWords", true)
			W.now = W.now + 1
			local miss = C.hit(W, "nameplate1", "WOUND", "", 0)
			check("ctfriend: and Miss in white with it on", miss and miss.text == "(Miss)" and F.col(miss) == "1.00,1.00,1.00", miss and miss.text)
			check("ctfriend: a heal of 0 shows nothing either way", C.say(W, "nameplate1", "HEAL", "", 0) == "none")
		end

		-- The game's healing number.
		do
			local W = F.world()
			check("ctfriend: before a friendly number the game's healing row is not written", F.heal(W) == 0 and W.cvars[F.HEAL] == "1")
			local damage = C.hit(W, "nameplate1", "WOUND", "", 4)
			check("ctfriend: a friendly number writes the healing row \"0\" once and remembers \"1\"", damage ~= nil and W.cvars[F.HEAL] == "0" and F.heal(W) == 1 and W.env.FlatUIDB.cvars[F.HEAL].game == "1", W.cvars[F.HEAL])
			W.change("combattext.friendHeal", "Healing you do")
			check("ctfriend: Healing you do puts the row back and shows no heal", W.cvars[F.HEAL] == "1" and C.say(W, "nameplate1", "HEAL", "", 8) == "none")
			W.change("combattext.friendHeal", "Healing they take from anyone")
			check("ctfriend: and Healing they take from anyone writes it again", W.cvars[F.HEAL] == "0")
			W.change("combattext.friend", "Off")
			check("ctfriend: Where friendly numbers show Off puts it back", W.cvars[F.HEAL] == "1" and (W.env.FlatUIDB.cvars == nil or W.env.FlatUIDB.cvars[F.HEAL] == nil))
			W.change("combattext.friend", "Both")
			check("ctfriend: and Both writes it again", W.cvars[F.HEAL] == "0")
			W.change("combattext.enabled", false)
			check("ctfriend: the page off puts it back", W.cvars[F.HEAL] == "1")
			W.change("combattext.enabled", true)
			check("ctfriend: and on again writes it", W.cvars[F.HEAL] == "0")
			W.change("combattext.friend", "Off")
			check("ctfriend: Where friendly numbers show Off takes the friendly numbers off the screen", C.shownCount(W) == 0)
			W.change("combattext.friend", "Both")
			W.fire("PLAYER_LOGOUT")
			check("ctfriend: logout puts it back", W.cvars[F.HEAL] == "1")
			local R = F.world()
			C.hit(R, "nameplate1", "WOUND", "", 4)
			R.slash("combat reset")
			check("ctfriend: /flatui combat reset writes the game's default for it", R.cvars[F.HEAL] == "1" and has(R.slash("combat"), F.HEAL .. ": now 1, default 1, wanted no change"), R.slash("combat"))
			local L = F.world({ options = {}, cvars = { [F.HEAL] = { game = "1", wrote = "0" } } })
			check("ctfriend: a record of the row left by an earlier session counts as a friendly number shown: the row is \"0\" from login", L.cvars[F.HEAL] == "0" and has(L.status(), "Numbers over friendly units: 0 shown."), L.cvars[F.HEAL])
			local D = F.world({ options = { ["combattext.friendHeal"] = "done" } })
			C.hit(D, "nameplate1", "WOUND", "", 4)
			check("ctfriend: Healing you do never writes the row and shows no heal", D.cvars[F.HEAL] == "1" and F.heal(D) == 0 and C.say(D, "nameplate1", "HEAL", "", 9) == "none")
			local O = F.world({ options = { ["combattext.friendHeal"] = "off" } })
			C.hit(O, "nameplate1", "WOUND", "", 4)
			check("ctfriend: Healing over friendly units Off never writes the row and shows no heal", O.cvars[F.HEAL] == "1" and F.heal(O) == 0 and C.say(O, "nameplate1", "HEAL", "", 9) == "none")
		end

		-- Withheld values.
		do
			local W = F.world()
			local amount = C.hit(W, "nameplate1", "WOUND", "", SECRET)
			check("ctfriend: a withheld amount is passed to the font string and counted, and raises nothing", #W.errors == 0 and #W.violations == 0 and has(W.status(), "Hit amounts the game would not tell: 1."), W.status())
			W.now = W.now + 1
			local flag = C.hit(W, "nameplate1", "WOUND", SECRET, 77)
			check("ctfriend: a withheld flag shows with no critical and no suffix", flag and flag.text == "-77" and flag.textHeight == 25, flag and flag.text)
			W.now = W.now + 1
			W.fire("UNIT_COMBAT", "nameplate1", SECRET, "", 5, 1)
			check("ctfriend: a withheld event counts as no detail and shows nothing", has(W.slash("combat"), "Report unreadable: 1."))
			check("ctfriend: and none of it makes a violation or an error", #W.violations == 0 and #W.errors == 0, C.trouble(W))
		end

		-- Placement.
		do
			local W = F.world()
			local by = F.frames(W)
			local frame = C.hit(W, "party1", "WOUND", "", 10)
			check("ctfriend: a number over a frame is at BOTTOM of the frame's TOP plus Height above frames", F.points(frame) == "BOTTOM TOP 0 10" and frame.points[1][2] == by.party1, F.points(frame))
			W.ns.Set("combattext.friend", "plates")
			W.now = W.now + 1
			local plate = C.hit(W, "nameplate1", "WOUND", "", 11)
			check("ctfriend: a number over a plate is at the enemy formula: height 60 is 20 above the centre", F.points(plate) == "CENTER CENTER 0 20", F.points(plate))
			W.ns.Set("combattext.overlap", "turn")
			W.now = W.now + 0.1
			local second = C.hit(W, "nameplate1", "WOUND", "", 12)
			W.now = W.now + 0.1
			local third = C.hit(W, "nameplate1", "WOUND", "", 13)
			check("ctfriend: lanes follow LANES: 0, 20, -20", plate.points[1][4] == 0 and second.points[1][4] == 20 and third.points[1][4] == -20, F.points(second) .. " " .. F.points(third))
			W.now = 5
			local fall = C.hit(W, "nameplate1", "WOUND", "", 141)
			C.draw(W, 5.5)
			local rise = F.points(fall)
			W.ns.Set("combattext.movement", "up")
			W.now = 10
			local climb = C.hit(W, "nameplate1", "WOUND", "", 14)
			C.draw(W, 10.5)
			check("ctfriend: Rise and fall and Straight up follow Offsets: after half a second 50 and 40 above the centre", rise:find(" 50$") ~= nil and F.points(climb):find(" 40$") ~= nil, rise .. " " .. F.points(climb))
			W.ns.Set("combattext.movement", "fall")
			W.now = W.now + 1
			local crit = C.hit(W, "nameplate1", "HEAL", "CRITICAL", 540)
			check("ctfriend: a critical heal is 1.2 times the settled height at the start", crit and crit.textHeight == 30, crit and crit.textHeight)
			C.draw(W, W.now + 0.05)
			local peak = crit.textHeight
			C.draw(W, W.now + 0.2)
			check("ctfriend: with the pop it peaks at 2.4 times and settles at 1.2 times", peak == 60 and crit.textHeight == 30, tostring(peak) .. " " .. tostring(crit.textHeight))
			W.ns.Set("combattext.friendSize", 140)
			W.now = W.now + 1
			local big = C.hit(W, "nameplate1", "WOUND", "", 15)
			check("ctfriend: Size over friendly units sets the height: 140% is 35", big and big.textHeight == 35, big and big.textHeight)
			W.ns.Set("combattext.friendSize", 100)
			W.ns.Set("combattext.friendHeight", 30)
			W.ns.Set("combattext.crit", "higher")
			W.ns.Set("combattext.friend", "frames")
			W.now = W.now + 1
			local lifted = C.hit(W, "party2", "WOUND", "CRITICAL", 16)
			check("ctfriend: Height above frames and Critical hits Higher: 30 plus 10 above the frame", F.points(lifted) == "BOTTOM TOP 0 40", F.points(lifted))
		end

		-- Caps.
		do
			local W = F.world()
			local by = F.frames(W, true)
			W.ns.Set("combattext.friend", "frames")
			W.now = W.now + 1
			local enemy = C.hit(W, "nameplate2", "WOUND", "", 4000)
			local mine = C.hit(W, "player", "WOUND", "", 4010)
			for index = 1, 6 do
				W.now = W.now + 0.1
				C.hit(W, "party1", "WOUND", "", index)
			end
			local over = 0
			for _, font in ipairs(W.addonFonts) do
				if font.shown and font.text:find("^%-%d$") then
					over = over + 1
				end
			end
			check("ctfriend: more than four numbers over one unit releases the oldest", over == 4, over)
			for index = 1, 25 do
				W.now = W.now + 0.1
				C.hit(W, "raid" .. index, "WOUND", "", 100 + index)
			end
			local friends = 0
			for _, font in ipairs(W.addonFonts) do
				if font.shown and font.text:find("^%-%d%d%d$") then
					friends = friends + 1
				end
			end
			check("ctfriend: more than twenty friendly numbers release friendly ones, and never an enemy or the player's own", friends == 20 and enemy.shown and mine.shown, friends .. " " .. tostring(enemy.shown) .. " " .. tostring(mine.shown))
		end

		-- The same hit twice.
		do
			local W = F.world()
			local first = C.hit(W, "nameplate1", "WOUND", "", 21)
			local again = C.hit(W, "nameplate1", "WOUND", "", 21)
			check("ctfriend: two reports with the same event, flag and school within 0.02 seconds show once and count", first and again == nil and has(W.slash("combat"), "Repeated reports skipped: 1."), W.slash("combat"))
			W.now = W.now + 0.05
			local later = C.hit(W, "nameplate1", "WOUND", "", 21)
			check("ctfriend: 0.05 seconds apart both show", later ~= nil)
			W.now = W.now + 0.005
			check("ctfriend: a different school is another hit", C.say(W, "nameplate1", "WOUND", "", 21, 4) == "-21")
		end

		-- Roster changes and anchors that go.
		do
			local W = F.world()
			local by, raws = F.frames(W)
			W.ns.Set("combattext.friend", "frames")
			local reads = 0
			local members = W.ns.PartyMembers
			W.ns.PartyMembers = function()
				reads = reads + 1
				return members()
			end
			C.hit(W, "party1", "WOUND", "", 1)
			W.now = W.now + 0.1
			C.hit(W, "party1", "WOUND", "", 2)
			local cached = reads
			W.fire("GROUP_ROSTER_UPDATE")
			W.now = W.now + 0.1
			C.hit(W, "party1", "WOUND", "", 3)
			check("ctfriend: the table of frames is read once for several reports and again after a roster change", cached == 1 and reads == 2, cached .. " " .. reads)
			raws.party1.unit = "party3"
			W.fire("UNIT_PET", "player")
			W.now = W.now + 0.1
			check("ctfriend: a frame whose unit changed gets no number", C.say(W, "party1", "WOUND", "", 4) == "none" and has(W.slash("combat"), "No frame or nameplate to show on: 1."))
			raws.party1.unit = "party1"
			W.fire("GROUP_ROSTER_UPDATE")
			W.ns.Set("combattext.friend", "both")
			W.platesFault = "error"
			W.now = W.now + 0.1
			local both = C.say(W, "party1", "WOUND", "", 5)
			W.ns.Set("combattext.friend", "plates")
			W.now = W.now + 0.1
			local plates = C.say(W, "party1", "WOUND", "", 6)
			W.platesFault = nil
			check("ctfriend: with no plate found, both falls back to the frame and plates shows nothing", both == "-5" and plates == "none", both .. " " .. plates)
			W.attackable.nameplate9 = false
			W.fire("FORBIDDEN_NAME_PLATE_UNIT_ADDED", "nameplate9")
			W.fire("FORBIDDEN_NAME_PLATE_UNIT_ADDED", "nameplate9")
			W.fire("FORBIDDEN_NAME_PLATE_UNIT_ADDED", "nameplate8")
			W.fire("FORBIDDEN_NAME_PLATE_UNIT_REMOVED", "nameplate8")
			W.ns.Set("combattext.friend", "both")
			check("ctfriend: a forbidden friendly plate raises the status line, counted once, and a forbidden enemy plate is not counted", has(W.status(), "Friendly nameplates the game hides from interface mods: 1. Numbers show over party and raid frames there.")
				and has(W.slash("combat"), "Nameplates the game hides from interface mods: 1."), W.status())
			W.ns.Set("combattext.friend", "plates")
			check("ctfriend: and with plates only the line says no number shows there", has(W.status(), "Friendly nameplates the game hides from interface mods: 1. No number shows there."), W.status())
		end

		-- A number over a frame has its own host: the strata of the enemy numbers and the status line do not change.
		do
			local W = F.world()
			local by = F.frames(W)
			by.party1:SetFrameStrata("LOW")
			W.ns.Set("combattext.friend", "frames")
			local enemy = C.hit(W, "nameplate2", "WOUND", "", 5)
			local function line(text)
				return text:match("Nameplate layer: [^\n]*")
			end
			local before = W.slash("combat")
			local member = C.hit(W, "party1", "WOUND", "", 4)
			check("ctfriend: a party1 number is on a host of its own, one strata above the frame, and the enemy host stays where it was",
				member and enemy and member.owner ~= enemy.owner and member.owner.strata == "MEDIUM" and enemy.owner.strata == "LOW", member and member.owner.strata)
			check("ctfriend: a party1 number leaves the Nameplate strata and Numbers line unchanged", line(W.slash("combat")) == line(before) and line(before) ~= nil, line(W.slash("combat")))
			local P = F.world()
			local pby = F.frames(P)
			pby.party1:SetFrameStrata("LOW")
			P.ns.Set("combattext.friend", "frames")
			C.hit(P, "party1", "WOUND", "", 4)
			check("ctfriend: with only a party frame number the line says Nameplate strata: none. Numbers: LOW.", has(P.slash("combat"), "Nameplate layer: none. Numbers layer: LOW."), P.slash("combat"))
			local D = F.world({ options = { ["combattext.friendHeal"] = "done" } })
			local O = F.world({ options = { ["combattext.friend"] = "off" } })
			check("ctfriend: /flatui combat has no line about the game's setting with Healing you do or with Where friendly numbers show Off",
				not has(D.slash("combat"), "goes to 0 with the first friendly number") and not has(O.slash("combat"), "goes to 0 with the first friendly number"), D.slash("combat"))
		end

		-- Status lines.
		do
			local W = F.world()
			check("ctfriend: before a hit the status says it waits, and the game's healing numbers show until then", has(W.status(), C.friend))
			C.hit(W, "nameplate1", "WOUND", "", 3)
			check("ctfriend: after one the status counts the numbers", has(W.status(), "Numbers over friendly units: 1 shown.\nShields over friendly units show in the game's own numbers.") and not has(W.status(), "waiting for the first hit. The game's healing"), W.status())
			local D = F.world({ options = { ["combattext.friendHeal"] = "done" } })
			check("ctfriend: with Healing you do the waiting line has no sentence about the game's healing numbers and there is no line about shields",
				has(D.status(), "Numbers over friendly units: waiting for the first hit.\n") and not has(D.status(), "Shields over friendly units") and not has(D.status(), "healing numbers show until then"), D.status())
			local O = F.world({ options = { ["combattext.friend"] = "off" } })
			check("ctfriend: with Where friendly numbers show Off the status has no line about friendly units", not has(O.status(), "friendly units") and not has(O.status(), "Friendly Player"), O.status())
			local N = F.world()
			N.cvars.nameplateShowFriendlyPlayers = "0"
			check("ctfriend: Friendly Player Nameplates off in the game's options is said with plates and both", has(N.status(), "Friendly Player Nameplates is off in the game's options."))
			N.ns.Set("combattext.friend", "frames")
			check("ctfriend: and not with party and raid frames only", not has(N.status(), "Friendly Player Nameplates"))
			local H = F.world()
			C.hit(H, "nameplate2", "WOUND", "", 3)
			H.grouped = true
			local said = has(H.status(), "The game sent no hit reports for party or raid units. /flatui combat has the counts.")
			H.grouped = false
			local alone = has(H.status(), "The game sent no hit reports")
			H.grouped = true
			F.frames(H)
			C.hit(H, "party1", "WOUND", "", 4)
			check("ctfriend: the no reports line shows in a group with enemy reports and no friendly ones, and not alone or after a friendly report", said and not alone and not has(H.status(), "The game sent no hit reports"), H.status())
		end

		-- /flatui combat test.
		do
			local W = F.world()
			W.ns.Set("combattext.own", "off")
			W.ns.Set("combattext.source", "game")
			W.ns.Set("combattext.friend", "off")
			check("ctfriend: /flatui combat test with Where friendly numbers show Off says so", has(W.slash("combat test"), "Where friendly numbers show is Off."))
			local T = F.world()
			T.ns.Set("combattext.own", "off")
			T.ns.Set("combattext.source", "game")
			T.units.target = T.cplate
			T.attackable.target = false
			T.slash("combat test")
			for _ = 1, 3 do
				T.advance(0.25)
			end
			local texts = {}
			for index, font in ipairs(T.addonFonts) do
				texts[index] = font.text
			end
			check("ctfriend: /flatui combat test with a friendly target shows damage, a heal and a critical heal over its plate, and no miss with misses off",
				table.concat(texts, "|") == "-312|+180|+540" and T.addonFonts[1].points[1][2] == T.cplate and T.addonFonts[3].textHeight == 30, table.concat(texts, "|"))
			check("ctfriend: the samples raise no counter", has(T.slash("combat"), "Shown: 0. No frame or nameplate to show on: 0.") and has(T.slash("combat"), "Hit reports: 0 nameplate, 0 party or raid, 0 pet. Shown: 0."), T.slash("combat"))
			T.ns.Set("combattext.friendWords", true)
			T.ns.Set("combattext.friendHeal", "done")
			T.units.target = nil
			local by = F.frames(T)
			local before = #T.addonFonts
			T.out = {}
			local said = T.slash("combat test")
			for _ = 1, 3 do
				T.advance(0.25)
			end
			local more = {}
			for index = before + 1, #T.addonFonts do
				more[#more + 1] = T.addonFonts[index].text
			end
			check("ctfriend: with no target the samples go over the first party frame, a miss shows with misses on, and with Healing you do the heals are left out and the line says so",
				table.concat(more, "|") == "-312|(Miss)" and T.addonFonts[before + 1].points[1][2] == by.party1
				and has(said, "Healing over friendly units is not Healing they take from anyone: no heal samples."), said .. " " .. table.concat(more, "|"))
			local P = F.world()
			P.ns.Set("combattext.own", "off")
			P.ns.Set("combattext.source", "game")
			P.units.target = nil
			local none = P.slash("combat test")
			check("ctfriend: with nothing to put them over the line says to target a friendly unit or join a group", has(none, "\nTarget a friendly unit with a nameplate, or join a group, to see numbers over friendly units."), none)
			local E = F.world()
			E.ns.Set("combattext.own", "off")
			E.ns.Set("combattext.source", "game")
			E.units.target = nil
			local pet = F.frames(E)
			E.env.PartyFrame = nil
			E.slash("combat test")
			check("ctfriend: and with only the pet frame the samples go over it", #E.addonFonts >= 1 and E.addonFonts[1].points[1][2] == pet.pet)
		end

		-- Whole page quiet.
		do
			local W = F.world()
			local by = F.frames(W)
			C.hit(W, "nameplate1", "WOUND", "", 1)
			C.hit(W, "party1", "HEAL", "CRITICAL", 2)
			C.hit(W, "pet", "WOUND", "", 3)
			W.slash("combat test")
			W.slash("combat")
			W.status()
			check("ctfriend: the numbers, the status, the report and the test make no violation or error", #W.violations == 0 and #W.errors == 0, C.trouble(W))
		end
	end

end
-- <<< combat text (end)

-- 2. Reading and changing options.
do
	local W = newWorld()
	W.login()
	local ns = W.ns
	local function set(path, v)
		ns.Set(path, v)
		return ns.Get(path)
	end
	check("set: a number is rounded to its step and held in range", set("general.thickness", 2.4) == 2 and set("general.thickness", 2.6) == 3 and set("general.thickness", 9) == 3
		and set("general.thickness", -4) == 1 and set("general.thickness", 0) == 1)
	check("set: opacity steps of five", set("general.backdropAlpha", 87) == 85 and set("general.backdropAlpha", 88) == 90 and set("general.backdropAlpha", 101) == 100
		and set("general.backdropAlpha", -1) == 0 and set("general.backdropAlpha", 2) == 0 and set("general.backdropAlpha", 40) == 40)
	check("set: scale from 65 to 115", set("general.scale", 34) == 65 and set("general.scale", 116) == 115 and set("general.scale", 64.6) == 65 and set("general.scale", 64.4) == 65
		and set("general.scale", 1) == 65 and set("general.scale", 200) == 115 and set("general.scaleSmall", 70) == 64 and set("general.scaleSmall", 20) == 35 and set("general.scaleSmall", 50.4) == 50)
	check("set: crop 0 to 15 and target thickness 1 to 4", set("actionbars.crop", 16) == 15 and set("actionbars.crop", -3) == 0 and set("nameplates.targetThickness", 5) == 4
		and set("nameplates.targetThickness", 0) == 1)
	check("set: the wrong type is refused", set("general.thickness", "3") == 1 and set("general.thickness", true) == 1 and set("general.thickness", nil) == 1 and set("general.thickness", {}) == 1)
	check("set: a bool only takes a bool", set("nameplates.dim", "yes") == false and set("nameplates.dim", 1) == false and set("nameplates.dim", nil) == false
		and set("nameplates.dim", true) == true and set("nameplates.dim", false) == false)
	check("set: a colour is eight hex digits, kept in lower case", set("general.border", "ff336699") == "ff336699" and set("general.border", "FF445566") == "ff445566"
		and set("general.border", "ff3366") == "ff445566" and set("general.border", "gg336699") == "ff445566" and set("general.border", 0xff336699) == "ff445566"
		and set("general.border", "ff33669900") == "ff445566" and set("general.border", " ff336699") == "ff445566")
	check("set: a choice must be one of the keys", set("nameplates.level", "text") == "text" and set("nameplates.level", "bogus") == "text" and set("nameplates.level", 2) == "text"
		and set("nameplates.level", "default") == "default" and set("swing.outline", "frame") == "frame" and set("swing.outline", "text") == "frame")
	ns.Set("bogus.value", true)
	ns.Set("general.bogus", 5)
	check("set: an unknown path is ignored and not stored", ns.Get("bogus.value") == nil and W.options()["bogus.value"] == nil and W.options()["general.bogus"] == nil)
	local o = W.options()
	check("set: changes are saved by path", o["general.thickness"] == 1 and o["general.backdropAlpha"] == 40 and o["general.scale"] == 115 and o["general.border"] == "ff445566"
		and o["nameplates.level"] == "default" and o["swing.outline"] == "frame" and o["nameplates.dim"] == false, tostring(o["general.thickness"]))
	check("set: back to the default is saved too", (function() ns.Set("general.backdropAlpha", 85) return o["general.backdropAlpha"] == 85 end)())
	local icon = W.buttons.ActionButton1.parts.icon
	local before = icon.calls.SetTexCoord
	ns.Set("actionbars.crop", 0)
	ns.Set("actionbars.crop", 0)
	ns.Set("actionbars.crop", 0.2)
	check("set: the same value changes nothing", icon.calls.SetTexCoord == before, tostring(icon.calls.SetTexCoord) .. " vs " .. tostring(before))
	-- Colours.
	ns.Set("general.border", "ff336699")
	local r, gg, b = ns.Colour("general.border")
	check("colour: red, green and blue from 0 to 1", near(r, 0.2) and near(gg, 0.4) and near(b, 0.6), g(r) .. " " .. g(gg) .. " " .. g(b))
	ns.Set("nameplates.focusColour", "ffff9900")
	r, gg, b = ns.Colour("nameplates.focusColour")
	check("colour: the default focus orange", near(r, 1) and near(gg, 0.6) and near(b, 0), g(r) .. " " .. g(gg) .. " " .. g(b))
	ns.Set("general.border", "80ff0000")
	r, gg, b = ns.Colour("general.border")
	check("colour: the alpha digits are not a colour", near(r, 1) and near(gg, 0) and near(b, 0))
	-- Dependencies named by the settings.
	check("needs: the setting a setting depends on", ns.Needs("nameplates.targetColour") == "nameplates.target" and ns.Needs("nameplates.target") == "nameplates.health"
		and ns.Needs("nameplates.health") == nil and ns.Needs("general.scale") == "general.scaleOn" and ns.Needs("nameplates.castBackdrop") == "nameplates.cast"
		and ns.Needs("bogus") == nil, tostring(ns.Needs("nameplates.targetColour")))
	check("set: no errors", #W.violations == 0 and #W.errors == 0)
end

-- 3. The options panel: pages, controls in order, kinds, labels, ranges, defaults.
do
	local W = newWorld()
	W.login()
	check("panel: a category with a subcategory for every other page, registered once", W.registered ~= nil and W.registered.name == "Flat UI" and #W.categories == #PAGE_LABELS + 1 and #W.registered.children == #PAGE_LABELS)
	local names = {}
	for i, child in ipairs(W.registered.children) do
		names[i] = child.name
	end
	check("panel: subcategory names", table.concat(names, ",") == table.concat(PAGE_LABELS, ","), table.concat(names, ","))
	check("panel: one control for each setting and each section header", #W.controls == COUNT.controls, #W.controls)
	local categories = { W.registered, unpack(W.registered.children) }
	local registered = {}
	for index, page in ipairs(PAGES) do
		if not page.panelOnly then
			registered[#registered + 1] = page
		end
	end
	check("panel: a page of the window's own is not in the game's options", #categories == #registered and W.layouts[categories[#registered + 1]] == nil)
	for index, page in ipairs(registered) do
		local list = W.layouts[categories[index]]
		check("panel: " .. page.key .. " has " .. #page.rows .. " entries", #list == #page.rows, #list)
		for i, row in ipairs(page.rows) do
			local init = list[i]
			if type(row) == "string" then
				check("panel: " .. page.key .. " section " .. row, init and init.kind == "header" and init.data.name == row, init and init.kind)
			else
				local setting = init and init.data and init.data.setting
				local ok = init and init.kind == CONTROL_KIND[row.kind] and setting and setting:GetName() == row.label and setting:GetVariableType() == VAR_TYPE[row.kind]
					and setting:GetVariable() == "FLATUI_" .. row.path:upper():gsub("%.", "_") and init.data.tooltip == row.tip
				check("panel: " .. row.path .. " is a " .. CONTROL_KIND[row.kind] .. " named " .. row.label .. ", tip " .. tostring(row.tip), ok, init and init.kind)
				if setting then
					if row.kind == "number" then
						local o = init.data.options
						check("panel: " .. row.path .. " slider from " .. row.min .. " to " .. row.max .. " by " .. row.step,
							o.minValue == row.min and o.maxValue == row.max and near(o.steps, (row.max - row.min) / row.step) and o.formatters and o.formatters[2] ~= nil
							and setting:GetDefaultValue() == row.default and setting:GetValue() == row.default, o.steps)
						-- The label to the right of the slider is a function of the value that adds the unit.
						local format = o.formatters and o.formatters[2]
						local shown = {}
						if type(format) == "function" then
							for k = 0, (row.max - row.min) / row.step do
								local v = row.min + k * row.step
								shown[#shown + 1] = (format(v) == v .. row.unit) and "" or (v .. " shows " .. tostring(format(v)))
							end
						end
						check("panel: " .. row.path .. " shows every position with the unit '" .. row.unit .. "'", type(format) == "function" and table.concat(shown) == "", table.concat(shown, "; "))
					elseif row.kind == "choice" then
						local list2 = init.data.options()
						local labels, values = {}, {}
						for k, entry in ipairs(list2) do
							labels[k], values[k] = entry.label, entry.value
						end
						local choiceList = type(row.choices) == "table" and row.choices or W.ns.Choices(row)
						local expected = {}
						for k, choice in ipairs(choiceList) do
							expected[k] = choice[2]
						end
						local defaultIndex
						for k, choice in ipairs(choiceList) do
							if choice[1] == row.default then
								defaultIndex = k
							end
						end
						local wantValues = {}
						for k = 1, #choiceList do
							wantValues[k] = k
						end
						check("panel: " .. row.path .. " offers " .. table.concat(expected, ", "), table.concat(labels, ",") == table.concat(expected, ",") and table.concat(values, ",") == table.concat(wantValues, ","),
							table.concat(labels, ",") .. "/" .. table.concat(values, ","))
						check("panel: " .. row.path .. " default is " .. row.default, setting:GetDefaultValue() == defaultIndex and setting:GetValue() == defaultIndex, setting:GetValue())
					else
						check("panel: " .. row.path .. " default is " .. tostring(row.default), setting:GetDefaultValue() == row.default and setting:GetValue() == row.default, tostring(setting:GetValue()))
					end
				end
			end
		end
	end
	clean(W, "panel")
	W = newWorld()
	W.login()
	-- The dependency chain and the area switch of each page, as the control reports it.
	local function mismatches(W2)
		local list = {}
		for _, row in ipairs(ALL) do
			if W2.enabled(row.path) ~= usable(W2, row) then
				list[#list + 1] = row.path .. (usable(W2, row) and " should be usable" or " should be greyed")
			end
		end
		return table.concat(list, "; ")
	end
	local predicateBad, cvarBad = {}, {}
	for _, row in ipairs(ALL) do
		-- The settings this one waits for: the chain of needs, then the switch of its page (not for that switch itself).
		local chain = {}
		local needs = row.needs
		while needs do
			chain[#chain + 1] = needs
			needs = ROW[needs].needs
		end
		if row.live ~= true and row.page ~= "general" and row.path ~= row.page .. ".enabled" then
			chain[#chain + 1] = row.page .. ".enabled"
		end
		local control = W.control(row.path)
		if #control.predicates ~= #chain then
			predicateBad[#predicateBad + 1] = row.path .. " has " .. #control.predicates .. ", wants " .. #chain
		end
		-- And each of those is also a variable the control looks at again when it changes.
		local want, got = {}, { unpack(control.cvars) }
		for i, path in ipairs(chain) do
			want[i] = W.variable(path)
		end
		table.sort(want)
		table.sort(got)
		if table.concat(got, ",") ~= table.concat(want, ",") then
			cvarBad[#cvarBad + 1] = row.path .. " looks at " .. table.concat(got, ",") .. ", wants " .. table.concat(want, ",")
		end
	end
	check("needs: each control has one predicate for its area and one for each setting in its chain, none for a page's own switch", #predicateBad == 0, table.concat(predicateBad, "; "))
	check("needs: and looks again when the setting of each of them changes", #cvarBad == 0, table.concat(cvarBad, "; "))
	local registered = true
	for _, init in ipairs(W.controls) do
		for _, cvar in ipairs(init.cvars) do
			registered = registered and W.settings[cvar] ~= nil
		end
	end
	check("needs: every variable a control looks at is a registered setting", registered)
	local headerPredicates = 0
	for _, init in ipairs(W.controls) do
		if init.kind == "header" then
			headerPredicates = headerPredicates + #init.predicates + #init.cvars
		end
	end
	check("needs: section headers have no predicate and look at nothing", headerPredicates == 0)
	check("needs: everything usable at the defaults except the scale", mismatches(W) == "" and not W.enabled("general.scale") and W.enabled("nameplates.targetColour"), mismatches(W))
	W.change("general.scaleOn", true)
	check("needs: the scale slider is usable when the custom scale is on", W.enabled("general.scale") and mismatches(W) == "", mismatches(W))
	W.change("general.scaleOn", false)
	check("needs: and greyed again when it is off", not W.enabled("general.scale") and mismatches(W) == "")
	-- A row that needs a choice and not a tick: Icon corner is usable for Both and Icon on the portrait only.
	local corner, flagLabel = {}, { both = "Both", icon = "Icon on the portrait", word = "Word in the name row", off = "Off" }
	for _, flag in ipairs({ "icon", "word", "off", "both" }) do
		W.change("unitframes.pvpFlag", flagLabel[flag])
		corner[#corner + 1] = flag .. "=" .. tostring(W.enabled("unitframes.pvpCorner")) .. (mismatches(W) == "" and "" or "!")
	end
	check("needs: the Icon corner row is usable with the PvP flag on Both or Icon on the portrait, greyed with Word in the name row or Off, and its chain is complete",
		table.concat(corner, " ") == "icon=true word=false off=false both=true", table.concat(corner, " ") .. mismatches(W))
	W.change("unitframes.squarePortrait", false)
	check("needs: and greyed with square portraits off, whatever the choice", not W.enabled("unitframes.pvpCorner") and not W.enabled("unitframes.pvpFlag") and mismatches(W) == "")
	W.change("unitframes.squarePortrait", true)
	W.change("nameplates.health", false)
	check("needs: health off greys its backdrop, dim, target border and the target settings", not W.enabled("nameplates.healthBackdrop") and not W.enabled("nameplates.dim")
		and not W.enabled("nameplates.target") and not W.enabled("nameplates.targetColour") and not W.enabled("nameplates.focusColour")
		and not W.enabled("nameplates.targetThickness") and W.enabled("nameplates.level") and W.enabled("nameplates.cast") and W.enabled("nameplates.auras") and mismatches(W) == "", mismatches(W))
	W.change("nameplates.health", true)
	W.change("nameplates.target", false)
	check("needs: target border off greys only the colours and thickness", W.enabled("nameplates.healthBackdrop") and W.enabled("nameplates.dim") and W.enabled("nameplates.target")
		and not W.enabled("nameplates.targetColour") and not W.enabled("nameplates.focusColour") and not W.enabled("nameplates.targetThickness") and mismatches(W) == "", mismatches(W))
	W.change("nameplates.target", true)
	W.change("nameplates.cast", false)
	check("needs: cast border off greys its backdrop", not W.enabled("nameplates.castBackdrop") and W.enabled("nameplates.healthBackdrop") and mismatches(W) == "")
	W.change("nameplates.cast", true)
	W.change("chat.tooltips", false)
	check("needs: the tooltip switch off greys the tooltip background, opacity and shading and the rows that already needed it, and leaves the chat rows and the health bar usable",
		not W.enabled("chat.tipBackground") and not W.enabled("chat.tipOpacity") and not W.enabled("chat.tipShading") and not W.enabled("chat.quality")
		and W.enabled("chat.opacity") and W.enabled("chat.health") and W.enabled("chat.tooltips") and mismatches(W) == "", mismatches(W))
	W.change("chat.tooltips", true)
	check("needs: the tooltip background, opacity and shading are usable again with the switch on", W.enabled("chat.tipBackground") and W.enabled("chat.tipOpacity") and W.enabled("chat.tipShading") and mismatches(W) == "", mismatches(W))
	for _, area in ipairs(AREAS) do
		W.change(area .. ".enabled", false)
		local greyed = 0
		for _, row in ipairs(ALL) do
			if row.page == area and row.live ~= true and row.path ~= area .. ".enabled" and not W.enabled(row.path) then
				greyed = greyed + 1
			end
		end
		local total = 0
		for _, row in ipairs(ALL) do
			if row.page == area and row.live ~= true and row.path ~= area .. ".enabled" then
				total = total + 1
			end
		end
		check("needs: " .. area .. " off greys all " .. total .. " other controls of its page, its own switch stays usable, nothing else is greyed", greyed == total and W.enabled(area .. ".enabled") and W.enabled("general.thickness")
			and W.enabled("general.border") and mismatches(W) == "", greyed .. " of " .. total .. " " .. mismatches(W))
		W.change(area .. ".enabled", true)
		check("needs: " .. area .. " on again", mismatches(W) == "")
	end
	-- Defaults button: every setting back to its default changes the frames back.
	W.change("nameplates.health", false)
	W.change("actionbars.crop", 3)
	W.change("general.border", "ff336699")
	W.change("swing.outline", "Whole timer")
	W.change("nameplates.level", "Default")
	W.defaults()
	local wrong = {}
	for _, row in ipairs(ALL) do
		-- A row that holds a game setting keeps the game's value: Defaults writes none of them.
		if row.live ~= true and W.ns.Get(row.path) ~= row.default then
			wrong[#wrong + 1] = row.path
		end
	end
	check("panel: the Defaults button restores every setting", #wrong == 0, table.concat(wrong, " "))
	clean(W, "panel use")
end

-- 3b. Every position of every slider is a value the addon keeps exactly, every colour the picker can give is accepted.
do
	local W = newWorld()
	W.login()
	for _, row in ipairs(ALL) do
		if row.kind == "number" and row.live ~= true then
			local wrong = {}
			local steps = (row.max - row.min) / row.step
			for k = 0, steps do
				local v = row.min + k * row.step
				local before = W.ns.Get(row.path)
				W.change(row.path, v)
				if W.ns.Get(row.path) ~= v or W.control(row.path).data.setting:GetValue() ~= v then
					wrong[#wrong + 1] = g(v) .. "->" .. g(W.ns.Get(row.path))
				end
			end
			check("slider: every position of " .. row.path .. " (" .. (steps + 1) .. ") is kept as it is", #wrong == 0, table.concat(wrong, " "))
		end
	end
	W.change("general.border", "ff112233")
	W.change("general.backdrop", "FF445566")
	W.change("nameplates.targetColour", "ffAbCdEf")
	check("swatch: lower or upper case from the picker", W.ns.Get("general.border") == "ff112233" and W.ns.Get("general.backdrop") == "ff445566"
		and W.ns.Get("nameplates.targetColour") == "ffabcdef" and W.read("nameplates.targetColour") == "ffabcdef")
	check("dropdown: shows the label of the current choice", W.read("nameplates.level") == "Thin border" and W.read("swing.outline") == "Bar only")
	W.change("nameplates.level", "Text only")
	W.change("swing.outline", "Whole timer")
	check("dropdown: a choice is saved by its key and shown by its label", W.ns.Get("nameplates.level") == "text" and W.ns.Get("swing.outline") == "frame"
		and W.read("nameplates.level") == "Text only" and W.read("swing.outline") == "Whole timer" and W.control("nameplates.level").data.setting:GetValue() == 2)
	W.change("nameplates.level", "Default")
	check("dropdown: the third choice", W.ns.Get("nameplates.level") == "default" and W.control("nameplates.level").data.setting:GetValue() == 3)
	clean(W, "slider positions")
end

-- 4. The slash command and opening the options.
do
	local W = newWorld()
	W.login()
	check("slash: options opens the page in the game's options", W.slash("options") == "" and W.opened == W.registered.id, tostring(W.opened))
	W.opened = nil
	check("slash: options leaves the window alone", W.slash("options") == "" and W.opened == W.registered.id and #W.violations == 0 and #W.errors == 0)
	W.opened = nil
	check("slash: any case, spaces around", W.slash("  OPTIONS  ") == "" and W.opened == W.registered.id)
	W.combat = true
	W.opened = nil
	check("slash: in combat it says the options open after combat, prints no status, and does not open", W.slash("options") == "Options open after combat."
		and W.slash("  OPTIONS  ") == "Options open after combat." and W.opened == nil, W.slash("options"))
	check("slash: status", has(W.slash("status"), "Action bars: on, 118 styled") and count(W.slash("status"), "\n") == #W.ns.StatusLines() - 1, W.slash("status"))
	W.combat = false
	check("slash: out of combat it opens again", W.slash("options") == "" and W.opened == W.registered.id)
	W.opened = nil
	check("slash: status in any case", has(W.slash(" Status "), "Cast bars: on, 5 styled"))
	check("slash: help: the lines of the command, then the help each module registers, in the order of the modules", W.slash("what") == TOC.allHelp(W), W.slash("what"))
	W.env.Settings.OpenToCategory = function() end
	W.env.SettingsPanel.shown = false
	check("slash: the panel did not open, so the status is printed", has(W.slash("options"), TOC.head(1)))
	W.env.Settings.OpenToCategory = function() error("blocked") end
	check("slash: opening raised, so the status is printed", has(W.slash("options"), "Cast bars: on, 5 styled") and #W.violations == 0)
end

-- 5. Settings saved by version 0.1.0 and values that are not valid.
do
	local W = newWorld({ saved = { nameplates = false, actionbars = true, resource = false, swing = false, castbars = false, thickness = 2 } })
	W.login()
	local o = W.options()
	check("migration: the module switches", o["nameplates.enabled"] == false and o["actionbars.enabled"] == true and o["resource.enabled"] == false
		and o["swing.enabled"] == false and o["castbars.enabled"] == false, tostring(o["nameplates.enabled"]))
	check("migration: the thickness", o["general.thickness"] == 2 and W.ns.Get("general.thickness") == 2)
	local db = W.env.FlatUIDB
	check("migration: the old keys are gone", db.nameplates == nil and db.actionbars == nil and db.resource == nil and db.swing == nil and db.castbars == nil and db.thickness == nil)
	check("migration: status", has(W.status(), TOC.head(2) .. "\nNameplates: off\nCombat text: on\nNumbers in front of nameplates: waiting for the first hit. The game's numbers show until then.\nWhose hits: one for each of your casts, swings, shots and auras. Left out as not yours: 0.\nOutgoing scroll area: 0 shown.\nNumbers over friendly units: waiting for the first hit. The game's healing numbers show until then.\nShields over friendly units show in the game's own numbers.\nCombat text for you: 0 shown.\nAction bars: on, 118 styled\nPersonal resource display: off\nYour buffs: on\nSwing timers: off\nCast bars: off"), W.status())
	check("migration: the panel shows the migrated values", W.control("nameplates.enabled").data.setting:GetValue() == false and W.control("general.thickness").data.setting:GetValue() == 2)
	clean(W, "migration")
	-- A reload with the migrated file changes nothing.
	local W2 = newWorld({ saved = db })
	W2.login()
	check("migration: a second load keeps the values", W2.ns.Get("nameplates.enabled") == false and W2.ns.Get("general.thickness") == 2 and W2.ns.Get("actionbars.enabled") == true
		and W2.env.FlatUIDB.thickness == nil)
	-- Thickness out of range, a switch that is not a boolean.
	local legacy = newWorld({ saved = { thickness = 40, nameplates = "yes", castbars = 1 } })
	legacy.login()
	check("repair: an old thickness out of range", legacy.ns.Get("general.thickness") == 3 and legacy.options()["general.thickness"] == 3)
	check("repair: an old switch that is not a boolean is dropped, the default stays", legacy.ns.Get("nameplates.enabled") == true and legacy.ns.Get("castbars.enabled") == true
		and legacy.env.FlatUIDB.nameplates == nil and legacy.env.FlatUIDB.castbars == nil and legacy.options()["nameplates.enabled"] == nil)
	local odd = newWorld({ saved = { options = {
		["general.thickness"] = 99, ["general.border"] = "red", ["nameplates.level"] = "round", ["bogus.path"] = 1, ["actionbars.crop"] = "8",
		["general.backdropAlpha"] = 87, ["nameplates.health"] = "yes", ["general.backdrop"] = "FF102030", ["swing.outline"] = "frame", ["general.scale"] = 3,
		["nameplates.dim"] = true } } })
	odd.login()
	local ro = odd.options()
	check("repair: numbers go to the nearest valid value", ro["general.thickness"] == 3 and ro["general.backdropAlpha"] == 85 and ro["general.scale"] == 65 and ro["general.scaleSmall"] == 35, g(ro["general.thickness"]) .. " " .. g(ro["general.backdropAlpha"]) .. " " .. g(ro["general.scale"]))
	check("repair: values of the wrong type, and paths nothing uses, are dropped", ro["general.border"] == nil and ro["nameplates.level"] == nil and ro["bogus.path"] == nil
		and ro["actionbars.crop"] == nil and ro["nameplates.health"] == nil)
	check("repair: colours are lower case, valid choices and bools are kept", ro["general.backdrop"] == "ff102030" and ro["swing.outline"] == "frame" and ro["nameplates.dim"] == true)
	check("repair: the addon uses the repaired values", odd.ns.Get("general.border") == "ff000000" and odd.ns.Get("nameplates.level") == "box" and odd.ns.Get("actionbars.crop") == 8
		and odd.ns.Get("nameplates.health") == true and odd.ns.Get("general.backdrop") == "ff102030")
	clean(odd, "repair")
	local weird = newWorld({ saved = { options = "none" } })
	weird.login()
	check("repair: an options field that is not a table is replaced", type(weird.options()) == "table" and weird.ns.Get("general.thickness") == 1)
	clean(weird, "repair of options")
end

local function texcoord(r)
	local t = r.texCoord
	return t and (g(t[1]) .. "," .. g(t[2]) .. "," .. g(t[3]) .. "," .. g(t[4])) or "-"
end
local function rgb(o)
	return o and (string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)) or "-"
end
-- Art alphas and outline states of one plate, as one line.
local function plateLine(W, p)
	local hb, lv, cb = p.healthBar, p.level, p.castBar
	return string.format("bg=%s sel=%s over=%s | lvl=%s,%s | cast=%s,%s | H:%s L:%s C:%s", g(hb.bgTexture.alpha), g(hb.selectedBorder.alpha), g(hb.deselectedOverlay.alpha),
		g(lv.playerLevelDiffIcon.alpha), g(lv.selectedBorder.alpha), g(cb.Background.alpha), g(cb.Border.alpha), W.state(hb), W.state(lv), W.state(cb))
end
local ON = "bg=0 sel=0 over=0 | lvl=0,0 | cast=0,0 | H:SB L:SB C:SB"
local OFF = "bg=1 sel=1 over=1 | lvl=1,1 | cast=1,1 | H:hb L:hb C:hb"
local function auraLine(rec)
	return string.format("tc=%s mask=%s over=%s", texcoord(rec.icon), tostring(rec.icon.masks[rec.mask] ~= nil), g(rec.overlay.alpha))
end
local AURA_ON = "tc=0.08,0.92,0.08,0.92 mask=false over=0"
local AURA_OFF = "tc=0,1,0,1 mask=true over=1"
local AURA_PLAIN = "tc=- mask=true over=1"

-- 2. Nameplates: the band, the gold outline and the level box art are faded and replaced.
do
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	W.tick()
	local hb, level, cast = plate.healthBar, plate.level, plate.castBar
	check("plate: all the art is faded and every outline shown with its backdrop", plateLine(W, plate) == ON, plateLine(W, plate))
	check("plate: the overlay that reaches past the bar is faded, not hidden", hb.deselectedOverlay.alpha == 0 and hb.deselectedOverlay.shown)
	check("plate: nothing is hidden or moved", hb.bgTexture.shown and hb.selectedBorder.shown and #hb.bgTexture.points == 0 and hb.bgTexture.atlas ~= nil and level.playerLevelDiffIcon.shown
		and cast.Background.shown and cast.Border.shown and not hb.bgTexture.allPoints)
	for name, target in pairs({ health = hb, level = level, cast = cast }) do
		local holder = W.holderOn(target)
		check("plate: " .. name .. " has a holder that ignores the plate's scale", holder and holder.parent == target and holder.ignoreParentScale == true and near(holder.scale, PX), holder and holder.scale)
		local ok, detail = ringed(W, holder, 1)
		check("plate: " .. name .. " has four 1 pixel black edges", ok, detail)
		local backdrop = W.backdropOn(target)
		check("plate: " .. name .. " has a dark backdrop behind the fill", backdrop and backdrop.sublevel == -8 and near(backdrop.color[1], 15 / 255) and near(backdrop.color[2], 15 / 255)
			and near(backdrop.color[3], 15 / 255) and near(backdrop.color[4], 0.85) and backdrop.owner == target and backdrop.shown, backdrop and backdrop.color and backdrop.color[4])
		check("plate: " .. name .. " edges are on the holder, drawn over the fill", #W.edgesOn(holder) == 4 and W.edgesOn(holder)[1].owner == holder)
	end
	check("plate: counted", has(W.status(), "Nameplates: on, 1 styled"), W.status())

	-- The same pooled frame shown for another unit gets nothing new.
	local frames, textures = #W.addonFrames, #W.addonTextures
	hb.bgTexture:SetAlpha(1)
	cast.Border:SetAlpha(1)
	W.showPlate("nameplate2", plate)
	W.tick()
	check("plate: reused frame, nothing added, art faded again", #W.addonFrames == frames and #W.addonTextures == textures and plateLine(W, plate) == ON and has(W.status(), "1 styled"))
	clean(W, "plate")
end

-- 2b. A plate with parts missing.
do
	local W = newWorld()
	W.login()
	local bare = W.newPlate({ bareParts = true })
	local noHealth = W.newPlate({ noHealthContainer = true })
	local noLevel = W.newPlate({ noLevel = true })
	local noCast = W.newPlate({ noCastContainer = true })
	for i, p in ipairs({ bare, noHealth, noLevel, noCast }) do
		W.showPlate("nameplate" .. i, p)
	end
	W.tick()
	check("plate parts: art missing is no error and the outlines are still made", W.state(bare.healthBar) == "SB" and W.state(bare.level) == "SB" and W.state(bare.castBar) == "SB")
	check("plate parts: no health bar, the rest is styled", noHealth.level.playerLevelDiffIcon.alpha == 0 and W.state(noHealth.level) == "SB" and noHealth.castBar.Border.alpha == 0)
	check("plate parts: no level frame, the rest is styled", noLevel.healthBar.bgTexture.alpha == 0 and W.state(noLevel.healthBar) == "SB" and noLevel.castBar.Border.alpha == 0)
	check("plate parts: no cast bar, the rest is styled", noCast.healthBar.bgTexture.alpha == 0 and W.state(noCast.level) == "SB")
	check("plate parts: all four counted", has(W.status(), "Nameplates: on, 4 styled"), W.status())
	clean(W, "plate parts")
end

-- 3. The target and the focus are marked by edge colour, found by comparing plate frames.
do
	local W = newWorld({ saved = { options = { ["swing.idle"] = "show" } } })
	W.login()
	local a, b, c = W.newPlate(), W.newPlate(), W.newPlate()
	W.showPlate("nameplate1", a)
	W.showPlate("nameplate2", b)
	W.showPlate("nameplate3", c)
	W.units.target, W.units.focus = b, c
	W.fire("PLAYER_TARGET_CHANGED")
	check("mark: not before Blizzard has handled the event", ringOf(W, b.healthBar, 1) and #W.timers >= 1)
	W.tick()
	check("mark: target white", ringOf(W, b.healthBar, 1, 1, 1, 1) and ringOf(W, b.level, 1, 1, 1, 1))
	check("mark: focus orange", ringOf(W, c.healthBar, 1, 1, 0.6, 0) and ringOf(W, c.level, 1, 1, 0.6, 0))
	check("mark: the rest black, cast bars always black", ringOf(W, a.healthBar, 1) and ringOf(W, a.level, 1) and ringOf(W, b.castBar, 1) and ringOf(W, c.castBar, 1))
	check("mark: the target's gold outline stays faded, the backdrop stays", plateLine(W, b) == ON and plateLine(W, c) == ON)
	-- Blizzard recolours its own markers on a target change.
	b.healthBar.selectedBorder:SetAlpha(1)
	b.level.selectedBorder:SetAlpha(1)
	W.units.target = a
	W.fire("PLAYER_TARGET_CHANGED")
	W.fire("PLAYER_TARGET_CHANGED")
	W.fire("PLAYER_FOCUS_CHANGED")
	check("mark: one timer for the marks and one for the name and health text for a burst of events", #W.timers == 2, #W.timers)
	W.tick()
	check("mark: moves with the target", ringOf(W, a.healthBar, 1, 1, 1, 1) and ringOf(W, b.healthBar, 1) and ringOf(W, b.level, 1))
	check("mark: Blizzard's markers faded again", b.healthBar.selectedBorder.alpha == 0 and b.level.selectedBorder.alpha == 0)
	W.units.target, W.units.focus = nil, nil
	W.fire("PLAYER_FOCUS_CHANGED")
	W.tick()
	check("mark: none", ringOf(W, a.healthBar, 1) and ringOf(W, c.healthBar, 1) and ringOf(W, a.level, 1))
	-- One plate that is both: the target colour wins.
	W.units.target, W.units.focus = c, c
	W.fire("PLAYER_TARGET_CHANGED")
	W.tick()
	check("mark: the target wins over the focus on one plate", ringOf(W, c.healthBar, 1, 1, 1, 1) and ringOf(W, a.healthBar, 1))
	-- A plate that appears already being the target.
	local d = W.newPlate()
	W.units.target, W.units.focus = d, nil
	W.showPlate("nameplate4", d)
	check("mark: a new plate is plain until the next frame", ringOf(W, d.healthBar, 1))
	W.tick()
	check("mark: a new plate that is the target is marked on the next frame", ringOf(W, d.healthBar, 1, 1, 1, 1) and ringOf(W, c.healthBar, 1))
	clean(W, "mark")
end

-- 3b. Colours and thickness of the marks, from the options.
do
	local W = newWorld()
	W.login()
	local a, b, c = W.newPlate(), W.newPlate(), W.newPlate()
	for i, p in ipairs({ a, b, c }) do
		W.showPlate("nameplate" .. i, p)
	end
	W.units.target, W.units.focus = b, c
	W.fire("PLAYER_TARGET_CHANGED")
	W.tick()
	W.change("nameplates.targetColour", "ff00ff00")
	check("mark colour: the target colour is applied on the next frame, not before", ringOf(W, b.healthBar, 1, 1, 1, 1))
	W.tick()
	check("mark colour: target green, level box too", ringOf(W, b.healthBar, 1, 0, 1, 0) and ringOf(W, b.level, 1, 0, 1, 0) and ringOf(W, c.healthBar, 1, 1, 0.6, 0) and ringOf(W, a.healthBar, 1))
	W.change("nameplates.focusColour", "ff0000ff")
	W.tick()
	check("mark colour: focus blue", ringOf(W, c.healthBar, 1, 0, 0, 1) and ringOf(W, c.level, 1, 0, 0, 1) and ringOf(W, b.healthBar, 1, 0, 1, 0))
	W.change("nameplates.targetThickness", 3)
	W.tick()
	check("mark thickness: the health bar border of the target and the focus is 3 pixels, the rest stays at 1", ringOf(W, b.healthBar, 3, 0, 1, 0) and ringOf(W, c.healthBar, 3, 0, 0, 1)
		and ringOf(W, a.healthBar, 1) and ringOf(W, b.castBar, 1) and ringOf(W, b.level, 3, 0, 1, 0))
	W.change("general.thickness", 2)
	check("mark thickness: the general thickness leaves the target's own thickness alone", ringOf(W, b.healthBar, 3, 0, 1, 0) and ringOf(W, c.healthBar, 3, 0, 0, 1)
		and ringOf(W, a.healthBar, 2) and ringOf(W, b.castBar, 2) and ringOf(W, b.level, 3, 0, 1, 0))
	W.units.target = a
	W.fire("PLAYER_TARGET_CHANGED")
	W.tick()
	check("mark thickness: the old target goes back to the general thickness, the new one gets its own", ringOf(W, b.healthBar, 2) and ringOf(W, a.healthBar, 3, 0, 1, 0))
	W.change("general.border", "ff112233")
	check("mark colour: a target keeps its own colour when the border colour changes, the rest follow", ringOf(W, a.healthBar, 3, 0, 1, 0) and ringOf(W, c.healthBar, 3, 0, 0, 1)
		and ringOf(W, b.healthBar, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255) and ringOf(W, b.castBar, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255))
	-- Target border off: no marks, Blizzard's own gold outline comes back.
	W.change("nameplates.target", false)
	W.tick()
	check("target border off: no colours, plain thickness, Blizzard's gold outline is shown", ringOf(W, a.healthBar, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255) and ringOf(W, c.healthBar, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255)
		and a.healthBar.selectedBorder.alpha == 1 and a.level.selectedBorder.alpha == 1 and W.state(a.healthBar) == "SB", plateLine(W, a))
	W.fire("PLAYER_TARGET_CHANGED")
	W.tick()
	check("target border off: stays off after a target change", ringOf(W, a.healthBar, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255) and a.healthBar.selectedBorder.alpha == 1)
	W.change("nameplates.target", true)
	W.tick()
	check("target border on again", ringOf(W, a.healthBar, 3, 0, 1, 0) and a.healthBar.selectedBorder.alpha == 0 and a.level.selectedBorder.alpha == 0)
	-- Border off: nothing is drawn, so there is nothing to colour.
	W.change("nameplates.health", false)
	W.tick()
	check("health border off: Blizzard's art is back, no marks, and the level box keeps Blizzard's target marker", plateLine(W, a) == "bg=1 sel=1 over=1 | lvl=0,1 | cast=0,0 | H:hb L:SB C:SB"
		and ringOf(W, a.level, 2, 0x11 / 255, 0x22 / 255, 0x33 / 255), plateLine(W, a))
	clean(W, "mark options")
end

