-- 4. The level box: thin border, text only, default.
do
	local W = newWorld()
	W.login()
	local a = W.newPlate()
	W.showPlate("nameplate1", a)
	local lv = a.level
	check("level: thin border by default", W.state(lv) == "SB" and lv.playerLevelDiffIcon.alpha == 0 and lv.selectedBorder.alpha == 0)
	local frames = #W.addonFrames
	W.change("nameplates.level", "Text only")
	check("level: text only hides the border and keeps Blizzard's box art faded", W.state(lv) == "hb" and lv.playerLevelDiffIcon.alpha == 0 and lv.selectedBorder.alpha == 0 and lv.playerLevelDiffIcon.shown)
	W.change("nameplates.level", "Default")
	check("level: default puts Blizzard's box art back", W.state(lv) == "hb" and lv.playerLevelDiffIcon.alpha == 1 and lv.selectedBorder.alpha == 1)
	W.change("nameplates.level", "Thin border")
	check("level: thin border again, nothing made twice", W.state(lv) == "SB" and lv.playerLevelDiffIcon.alpha == 0 and #W.addonFrames == frames)
	W.change("nameplates.health", false)
	check("level: it does not depend on the health border", W.state(lv) == "SB" and W.state(a.healthBar) == "hb" and lv.playerLevelDiffIcon.alpha == 0)
	W.change("nameplates.health", true)
	W.change("nameplates.healthBackdrop", false)
	check("level: its backdrop follows the health backdrop", W.state(lv) == "Sb" and W.state(a.healthBar) == "Sb" and W.state(a.castBar) == "SB", plateLine(W, a))
	W.change("nameplates.health", false)
	check("level: with the health border off the switch for the background is greyed, so the box keeps its background", W.state(lv) == "SB" and W.state(a.healthBar) == "hb", plateLine(W, a))
	W.change("nameplates.health", true)
	check("level: and follows that switch again with the border on", W.state(lv) == "Sb", plateLine(W, a))
	W.change("nameplates.healthBackdrop", true)
	for _, style in ipairs({ "Text only", "Default" }) do
		local W2 = newWorld({ saved = { options = { ["nameplates.level"] = style == "Text only" and "text" or "default" } } })
		W2.login()
		local p = W2.newPlate()
		W2.showPlate("nameplate1", p)
		check("level: saved as " .. style .. ", no outline is made for the level box", W2.state(p.level) == "." and W2.holderOn(p.level) == nil)
		check("level: saved as " .. style .. ", the box art", p.level.playerLevelDiffIcon.alpha == (style == "Text only" and 0 or 1) and p.level.selectedBorder.alpha == (style == "Text only" and 0 or 1))
		W2.change("nameplates.level", "Thin border")
		check("level: saved as " .. style .. ", then thin border", W2.state(p.level) == "SB" and p.level.playerLevelDiffIcon.alpha == 0)
		clean(W2, "level " .. style)
	end
	clean(W, "level")
end

-- 5. Aura icons: square, cropped, thin border; found on the next frame.
do
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	local one, two = W.addAura(plate), W.addAura(plate)
	W.showPlate("nameplate1", plate)
	check("auras: not before the next frame", auraLine(one) == AURA_PLAIN and W.holderOn(one.item) == nil, auraLine(one))
	W.tick()
	check("auras: cropped, mask taken off, overlay faded", auraLine(one) == AURA_ON and auraLine(two) == AURA_ON, auraLine(one))
	local o = W.look(one.item)
	check("auras: a thin border without a backdrop", o and o.state == "Sb" and ringed(W, o.anchor, 1) and o.holder.parent == one.item and o.holder.ignoreParentScale == true, o and o.state)
	check("auras: the icon's own frame is untouched", one.item.alpha == 1 and one.item.shown and #one.item.points == 0)
	-- Blizzard hands the same pooled items to other auras: nothing is styled twice.
	local frames, textures = #W.addonFrames, #W.addonTextures
	for _ = 1, 3 do
		W.fire("UNIT_AURA", "nameplate1")
		W.tick()
	end
	W.showPlate("nameplate1", plate)
	W.tick()
	check("auras: pooled items are not styled twice", #W.addonFrames == frames and #W.addonTextures == textures and one.icon.calls.SetTexCoord == 1 and one.icon.calls.RemoveMaskTexture == 1
		and one.overlay.calls.SetAlpha == 1 and one.icon.calls.AddMaskTexture == nil, tostring(one.icon.calls.SetTexCoord))
	-- A new icon appears.
	local three = W.addAura(plate)
	check("auras: a new icon is plain until the next frame after UNIT_AURA", auraLine(three) == AURA_PLAIN)
	W.fire("UNIT_AURA", "nameplate1")
	check("auras: UNIT_AURA queues one timer", #W.timers == 1, #W.timers)
	W.fire("UNIT_AURA", "nameplate1")
	check("auras: and a burst of them still one", #W.timers == 1, #W.timers)
	W.tick()
	check("auras: the new icon is styled", auraLine(three) == AURA_ON and one.icon.calls.SetTexCoord == 1)
	-- Units that are not nameplates are dropped before the handler is called, so nothing is looked up for them.
	local four = W.addAura(plate)
	local lookups = 0
	local lookup = W.env.C_NamePlate.GetNamePlateForUnit
	W.env.C_NamePlate.GetNamePlateForUnit = function(unit)
		lookups = lookups + 1
		return lookup(unit)
	end
	for _, unit in ipairs({ "player", "target", "party1", "focus", "boss1", "arena1" }) do
		W.units[unit] = plate
		W.fire("UNIT_AURA", unit)
	end
	W.fire("UNIT_AURA", 5)
	W.fire("UNIT_AURA", nil)
	check("auras: units that are not nameplates queue nothing and cost no lookup", #W.timers == 0 and lookups == 0, #W.timers .. " " .. lookups)
	W.fire("UNIT_AURA", "nameplate99")
	check("auras: a nameplate unit with no plate queues nothing", #W.timers == 0 and lookups == 1, #W.timers .. " " .. lookups)
	-- A unit the client withholds: every plate the addon knows is looked at.
	W.fire("UNIT_AURA", SECRET)
	check("auras: a unit that is withheld queues the plates the addon knows, once", #W.timers == 1, #W.timers)
	W.fire("UNIT_AURA", SECRET)
	check("auras: and a burst of them is still one timer", #W.timers == 1, #W.timers)
	W.tick()
	check("auras: the new icon is styled from it", auraLine(four) == AURA_ON)
	local five = W.addAura(plate)
	W.fire("UNIT_AURA", "nameplate12")
	W.units.nameplate12 = plate
	W.fire("UNIT_AURA", "nameplate12")
	W.tick()
	check("auras: a nameplate unit with a number is matched", auraLine(five) == AURA_ON)
	-- Turned off: the icons the addon knows are restored at once, and the next frame changes nothing.
	W.change("nameplates.auras", false)
	check("auras: turning them off restores the icons at once: full texture, mask back, overlay shown, border hidden", auraLine(one) == AURA_OFF and auraLine(two) == AURA_OFF and auraLine(four) == AURA_OFF
		and W.state(one.item) == "hb", auraLine(one) .. " " .. W.state(one.item))
	W.tick()
	check("auras: and the next frame changes nothing", auraLine(one) == AURA_OFF and auraLine(five) == AURA_OFF and W.state(one.item) == "hb")
	frames = #W.addonFrames
	W.change("nameplates.auras", true)
	W.tick()
	check("auras: on again, nothing made twice", auraLine(one) == AURA_ON and W.state(one.item) == "Sb" and #W.addonFrames == frames and one.icon.calls.SetTexCoord == 3
		and one.icon.calls.RemoveMaskTexture == 2 and one.icon.calls.AddMaskTexture == 1, tostring(one.icon.calls.SetTexCoord))
	-- The module off puts every icon back, and nothing is styled while it is off.
	W.change("nameplates.enabled", false)
	W.tick()
	check("auras: the module off restores them", auraLine(one) == AURA_OFF and auraLine(three) == AURA_OFF and W.state(one.item) == "hb")
	local late = W.addAura(plate)
	W.fire("UNIT_AURA", "nameplate1")
	W.tick()
	check("auras: nothing is styled while the module is off", auraLine(late) == AURA_PLAIN and W.holderOn(late.item) == nil)
	W.change("nameplates.enabled", true)
	W.tick()
	check("auras: the module on styles every icon again, including the one that arrived meanwhile", auraLine(one) == AURA_ON and auraLine(late) == AURA_ON)
	-- An icon Blizzard has released is on no plate, but the addon knows it and restores it too, since it is used again later.
	W.removeAura(plate, one)
	W.change("nameplates.auras", false)
	W.tick()
	check("auras: an icon no longer in the pool is restored with the others", auraLine(one) == AURA_OFF and auraLine(late) == AURA_OFF and W.state(one.item) == "hb")
	W.change("nameplates.auras", true)
	W.tick()
	check("auras: and styled again with the others when they are switched on, whether it is in the pool or not", auraLine(one) == AURA_ON and auraLine(late) == AURA_ON and W.state(one.item) == "Sb")
	clean(W, "auras")
end

-- 5b. Aura icons the addon may not or cannot style.
do
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	local forbidden = W.addAura(plate, { forbidden = true })
	local noMask = W.addAura(plate, { noMask = true })
	local noOverlay = W.addAura(plate, { noOverlay = true })
	local secretIcon = W.addAura(plate, { iconSecret = true })
	local noIcon = W.addAura(plate, { noIcon = true })
	local ok = W.addAura(plate)
	W.showPlate("nameplate1", plate)
	W.tick()
	check("aura parts: a forbidden icon is not touched, the others are styled", ok.icon.texCoord ~= nil and #W.violations == 0 and #W.out == 0, table.concat(W.violations, "|"))
	check("aura parts: no mask, no overlay: no error and the rest is done", noMask.icon.texCoord ~= nil and noMask.overlay.alpha == 0 and W.state(noMask.item) == "Sb"
		and noOverlay.icon.texCoord ~= nil and noOverlay.icon.masks[noOverlay.mask] == nil and W.state(noOverlay.item) == "Sb")
	check("aura parts: an icon texture that is secret or missing is skipped, the border and overlay are still done", secretIcon.overlay.alpha == 0 and W.state(secretIcon.item) == "Sb"
		and noIcon.overlay.alpha == 0 and W.state(noIcon.item) == "Sb" and secretIcon.icon.texCoord == nil)
	check("aura parts: the aura part was not stopped", not has(W.status(), "Aura icons: stopped"), W.status())
	W.change("nameplates.auras", false)
	W.tick()
	check("aura parts: restored with the same gaps", noMask.icon.texCoord[1] == 0 and noMask.overlay.alpha == 1 and noOverlay.icon.masks[noOverlay.mask] == true and W.state(noMask.item) == "hb")
	clean(W, "aura parts")
	-- Frames of the plate that are forbidden, missing or odd.
	local V = newWorld()
	V.login()
	local pf = V.newPlate({ aurasForbidden = true })
	local pn = V.newPlate({ noAurasFrame = true })
	local pe = V.newPlate({ poolNoEnumerate = true })
	local ps = V.newPlate({ poolSecret = true })
	local ra, rb = V.addAura(pf), V.addAura(pe)
	for i, p in ipairs({ pf, pn, pe, ps }) do
		V.showPlate("nameplate" .. i, p)
	end
	V.tick()
	check("aura frames: a forbidden, missing, odd or secret pool is skipped without a word", ra.icon.texCoord == nil and rb.icon.texCoord == nil and #V.violations == 0 and #V.errors == 0 and #V.out == 0
		and not has(V.status(), "Aura icons") and V.state(pf.healthBar) == "SB" and V.state(pn.healthBar) == "SB" and V.state(ps.healthBar) == "SB", table.concat(V.violations, "|") .. V.status())
end

-- 5c. A pool that fails stops the aura part and nothing else.
do
	local W = newWorld()
	W.login()
	local broken = W.newPlate({ poolErrors = true })
	local good = W.newPlate()
	local ga = W.addAura(good)
	W.showPlate("nameplate1", broken)
	W.showPlate("nameplate2", good)
	W.tick()
	local status = W.status()
	check("aura failure: a note under the module line, said in the status", has(status, "Nameplates: on, 2 styled\nAura icons: stopped. EnumerateActive failed\n"), status)
	check("aura failure: the module itself is still running and says nothing", #W.out == 0 and not has(status, "Nameplates: stopped") and not has(status, "failed. "), status)
	check("aura failure: the plates are styled all the same", plateLine(W, broken) == ON and plateLine(W, good) == ON)
	check("aura failure: icons are not styled after the failure", ga.icon.texCoord == nil or auraLine(ga) == AURA_ON)
	local lookups = 0
	local lookup = W.env.C_NamePlate.GetNamePlateForUnit
	W.env.C_NamePlate.GetNamePlateForUnit = function(unit)
		lookups = lookups + 1
		return lookup(unit)
	end
	W.fire("UNIT_AURA", "nameplate2")
	W.units.nameplate2 = good
	W.fire("UNIT_AURA", "nameplate2")
	W.fire("UNIT_AURA", SECRET)
	check("aura failure: no more aura work is queued, and nothing is looked up for it", #W.timers == 0 and lookups == 0, #W.timers .. " " .. lookups)
	W.env.C_NamePlate.GetNamePlateForUnit = lookup
	local a2 = W.addAura(good)
	W.change("nameplates.level", "Text only")
	check("aura failure: a refresh queues the marks of the two plates and no aura work, and the click area is set at once", #W.timers == 1, #W.timers)
	W.tick()
	check("aura failure: the other options still work", W.state(good.level) == "hb" and good.healthBar.bgTexture.alpha == 0 and auraLine(a2) == AURA_PLAIN)
	W.change("nameplates.auras", false)
	W.tick()
	check("aura failure: the note is said once however often it happens", count(W.status(), "Aura icons: stopped") == 1)
	-- An icon whose regions cannot be read fails the same way.
	local V = newWorld()
	V.login()
	local p = V.newPlate()
	V.addAura(p, { regionsError = true })
	local q = V.newPlate()
	local qa = V.addAura(q)
	V.showPlate("nameplate1", p)
	V.showPlate("nameplate2", q)
	V.tick()
	check("aura failure: an icon that cannot be read stops the aura part with its error", has(V.status(), "Aura icons: stopped. ") and has(V.status(), "GetRegions failed") and #V.out == 0
		and V.state(q.healthBar) == "SB", V.status())
end

-- 6. Plates the addon may not touch, and values the client withholds.
do
	local W = newWorld()
	W.login()
	local before = #W.addonFrames
	local forbidden = W.newPlate({ forbidden = true })
	W.showPlate("nameplate1", forbidden)
	W.units.nameplate2 = SECRET
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate2")
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate3")
	W.units.target = forbidden
	W.fire("PLAYER_TARGET_CHANGED")
	W.units.focus = SECRET
	W.fire("PLAYER_FOCUS_CHANGED")
	W.tick()
	check("forbidden plate: untouched", forbidden.healthBar.bgTexture.alpha == 1 and #W.addonFrames == before and has(W.status(), "Nameplates: on, 0 styled"), #W.addonFrames)
	clean(W, "forbidden plate")
	local V = newWorld()
	local ok = V.newPlate()
	V.platesFault = "error"
	V.login()
	V.platesFault = "secret"
	V.change("nameplates.dim", true)
	V.platesFault = "string"
	V.change("nameplates.dim", false)
	V.platesFault = "number"
	V.change("nameplates.dim", true)
	V.platesFault = nil
	V.change("nameplates.dim", false)
	check("withheld list: GetNamePlates failing, secret or not a table is no error", #V.out == 0 and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), V.status())
	V.showPlate("nameplate1", ok)
	V.tick()
	check("withheld list: and the module works when the list is back", ok.healthBar.bgTexture.alpha == 0)
end

-- 7. Plates already on screen when the addon starts.
do
	local W = newWorld()
	local plate = W.newPlate()
	local aura = W.addAura(plate)
	W.newPlate({ forbidden = true })
	W.login()
	check("existing plates: styled at login", plateLine(W, plate) == ON and has(W.status(), "Nameplates: on, 1 styled"), W.status())
	check("existing plates: and their auras on the next frame", auraLine(aura) == AURA_ON)
	clean(W, "existing plates")
end

-- 8. A plate with no unit frame yet is picked up on the next frame; a frame whose state is withheld is left alone.
do
	local W = newWorld()
	W.login()
	-- The action buttons are styled again on the frame after entering the world.
	W.flush()
	local early = W.newPlate({ noUnitFrame = true })
	local early2 = W.newPlate({ noUnitFrame = true })
	W.showPlate("nameplate1", early)
	W.showPlate("nameplate2", early2)
	check("early plate: nothing yet, no error", early.healthBar.bgTexture.alpha == 1 and #W.out == 0)
	check("early plate: one scan is queued for both, and their marks wait for it", #W.timers == 1, #W.timers)
	early.UnitFrame, early2.UnitFrame = early.later, early2.later
	W.tick()
	check("early plate: styled on the next frame", early.healthBar.bgTexture.alpha == 0 and early2.healthBar.bgTexture.alpha == 0 and has(W.status(), "Nameplates: on, 2 styled"), W.status())
	local later = W.newPlate({ noUnitFrame = true })
	W.showPlate("nameplate5", later)
	later.UnitFrame = later.later
	W.tick()
	check("early plate: and again for a plate that comes later", later.healthBar.bgTexture.alpha == 0 and has(W.status(), "Nameplates: on, 3 styled"), W.status())
	local withheld = W.newPlate({ secretState = true })
	W.showPlate("nameplate3", withheld)
	W.tick()
	check("withheld state: treated as forbidden", withheld.healthBar.bgTexture.alpha == 1 and has(W.status(), "Nameplates: on, 3 styled") and #W.out == 0, W.status())
	clean(W, "early plate")
end

-- 9. A bad plate is skipped and counted once. Five failing frames stop the module.
do
	local W = newWorld()
	W.login()
	local broken = W.newPlate({ breakTextures = true })
	W.showPlate("nameplate1", broken)
	local good = W.newPlate()
	W.showPlate("nameplate2", good)
	W.tick()
	check("skipped: one bad plate does not stop the others", #W.out == 0 and good.healthBar.bgTexture.alpha == 0 and broken.healthBar.bgTexture.alpha == 1, W.status())
	check("skipped: the status counts the good plate as styled and the bad one as failed", has(W.status(), "Nameplates: on, 1 styled, 1 failed. ") and has(W.status(), "CreateTexture failed"), W.line("Nameplates"))
	for i = 1, 8 do
		W.units.target = (i % 2 == 0) and good or broken
		W.fire("PLAYER_TARGET_CHANGED")
		W.tick()
	end
	check("skipped: a bad plate is not held against the module each time the target changes", #W.out == 0 and not has(W.status(), "Nameplates: stopped") and has(W.status(), ", 1 failed. ")
		and good.healthBar.bgTexture.alpha == 0, W.line("Nameplates"))
	W.change("nameplates.dim", true)
	W.change("nameplates.dim", false)
	W.change("nameplates.level", "Text only")
	W.change("nameplates.level", "Thin border")
	check("skipped: nor each time an option changes", #W.out == 0 and not has(W.status(), "Nameplates: stopped") and W.state(good.level) == "SB", W.line("Nameplates"))
end
do
	local W = newWorld()
	W.login()
	local first = W.newPlate({ breakTextures = true })
	W.showPlate("nameplate1", first)
	local good = W.newPlate()
	W.showPlate("nameplate2", good)
	local failing = { first }
	for i = 3, 6 do
		failing[#failing + 1] = W.newPlate({ breakTextures = true })
		W.showPlate("nameplate" .. i, failing[#failing])
	end
	check("stopped: said once, after five failures", #W.out == 1 and W.out[1] == "Flat UI: Nameplates stopped. /flatui status shows why. Type /reload if the look is left half changed.", table.concat(W.out, " | "))
	check("stopped: the plate that was styled has Blizzard's art back and no outline shown", plateLine(W, good) == OFF and #W.diff("nameplate") == 0, plateLine(W, good) .. " " .. table.concat(W.diff("nameplate"), "; "))
	local later = W.newPlate()
	W.showPlate("nameplate7", later)
	failing[#failing + 1] = W.newPlate({ breakTextures = true })
	W.showPlate("nameplate8", failing[#failing])
	W.fire("PLAYER_TARGET_CHANGED")
	W.tick()
	check("stopped: stays stopped", #W.out == 1 and later.healthBar.bgTexture.alpha == 1 and has(W.status(), "Nameplates: stopped. ") and has(W.status(), "CreateTexture failed"), W.status())
	check("stopped: other modules unaffected", has(W.status(), "Cast bars: on, 5 styled") and has(W.status(), "Action bars: on, 118 styled"))
	local ran = false
	check("stopped: its code is not run again", W.ns.Try("nameplates", function() ran = true end) == false and not ran and W.ns.Enabled("nameplates") == false and W.ns.IsStopped("nameplates"))
	W.change("nameplates.health", false)
	W.change("nameplates.health", true)
	check("stopped: the other options do not start it again", #W.out == 1 and later.healthBar.bgTexture.alpha == 1 and has(W.status(), "Nameplates: stopped. "))
	W.change("nameplates.enabled", false)
	check("stopped: switching the page off leaves it as it is", #W.out == 1 and later.healthBar.bgTexture.alpha == 1 and has(W.status(), "Nameplates: stopped. "))
	W.change("nameplates.enabled", true)
	check("stopped: switching it on tries again, and while the plates still fail it stops again, said again", #W.out == 2
		and W.out[2] == "Flat UI: Nameplates stopped. /flatui status shows why. Type /reload if the look is left half changed." and later.healthBar.bgTexture.alpha == 1 and has(W.status(), "Nameplates: stopped. "), table.concat(W.out, " | "))
	for _, plate in ipairs(failing) do
		plate.repair()
	end
	W.change("nameplates.enabled", false)
	W.change("nameplates.enabled", true)
	W.tick()
	check("stopped: switched off and on once the plates work, it runs and its failures are forgotten", #W.out == 2 and not W.ns.IsStopped("nameplates") and W.ns.Enabled("nameplates")
		and later.healthBar.bgTexture.alpha == 0 and plateLine(W, failing[1]) == ON and has(W.status(), "Nameplates: on, ") and not has(W.status(), "failed") and not has(W.status(), "CreateTexture failed"), W.line("Nameplates"))
	check("stopped: nothing said by anything else", #W.violations == 0 and #W.errors == 0)
end
do
	local W = newWorld()
	local broken, good = W.newPlate({ breakTextures = true }), W.newPlate()
	W.login()
	check("skipped at login: a bad plate on screen is skipped and the next one styled", broken.healthBar.bgTexture.alpha == 1 and good.healthBar.bgTexture.alpha == 0
		and has(W.status(), ", 1 failed. ") and #W.out == 0, W.line("Nameplates"))
end

-- 10. A module that is off touches nothing. Turning it on later starts it. Turning it off puts Blizzard's art back exactly.
do
	local W = newWorld({ saved = { nameplates = false, actionbars = false, resource = true, swing = false, castbars = true, thickness = 2 } })
	W.login()
	local plate = W.newPlate()
	local aura = W.addAura(plate)
	W.showPlate("nameplate1", plate)
	W.tick()
	check("off: nameplates untouched, no outline made", plate.healthBar.bgTexture.alpha == 1 and W.state(plate.healthBar) == "." and auraLine(aura) == AURA_PLAIN)
	check("off: action bars untouched, not hooked", W.buttons.ActionButton1.parts.NormalTexture.alpha == 1 and W.bar.BorderArt.alpha == 1 and W.hooks == 0, W.hooks)
	check("off: swing timers untouched", W.swing.SwingTimerMainHandFrame.Border.shown and W.state(W.swing.SwingTimerMainHandFrame.StatusBar) == "." and W.state(W.swing.SwingTimerMainHandFrame.timer) == ".")
	check("off: the rest still styled, at the saved thickness", ringed(W, W.holderOn(W.cast.PlayerCastingBarFrame.bar), 2) and ringed(W, W.holderOn(W.prd.power[1]), 2))
	check("off: status", has(W.status(), TOC.head(2) .. "\nNameplates: off\nCombat text: on\nNumbers in front of nameplates: waiting for the first hit. The game's numbers show until then.\nWhose hits: one for each of your casts, swings, shots and auras. Left out as not yours: 0.\nOutgoing scroll area: 0 shown.\nNumbers over friendly units: waiting for the first hit. The game's healing numbers show until then.\nShields over friendly units show in the game's own numbers.\nCombat text for you: 0 shown.\nAction bars: off\n") and has(W.status(), "Swing timers: off"), W.status())
	W.change("swing.enabled", true)
	check("on: starts at once from the options", W.swing.SwingTimerMainHandFrame.Border.shown == false and W.state(W.swing.SwingTimerMainHandFrame.StatusBar) == "SB" and W.ns.Get("swing.enabled") == true)
	W.change("nameplates.enabled", true)
	W.tick()
	check("on: plates already on screen are styled, with their auras", plateLine(W, plate) == ON and auraLine(aura) == AURA_ON, plateLine(W, plate))
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.change("nameplates.enabled", false)
	local meanwhile = W.newPlate()
	local maura = W.addAura(meanwhile)
	W.showPlate("nameplate2", meanwhile)
	W.tick()
	check("off again: new plates left alone", meanwhile.healthBar.bgTexture.alpha == 1 and W.state(meanwhile.healthBar) == "." and auraLine(maura) == AURA_PLAIN)
	check("off again: Blizzard's art is back exactly, aura icons included", #W.diff("nameplate") == 0, table.concat(W.diff("nameplate"), "; "))
	check("off again: and every outline is hidden", W.state(plate.healthBar) == "hb" and W.state(plate.level) == "hb" and W.state(plate.castBar) == "hb" and W.state(aura.item) == "hb",
		W.state(plate.healthBar) .. W.state(plate.level) .. W.state(plate.castBar) .. W.state(aura.item))
	W.change("nameplates.enabled", true)
	W.tick()
	check("on again: catches up with what appeared meanwhile", plateLine(W, meanwhile) == ON and auraLine(maura) == AURA_ON and plateLine(W, plate) == ON, plateLine(W, meanwhile))
	check("on again: nothing made twice, only the new plate and its icon get outlines", #W.addonFrames == frames + 5 and #W.addonTextures == textures + 20, (#W.addonFrames - frames) .. " " .. (#W.addonTextures - textures))
	check("on again: counted", has(W.status(), "Nameplates: on, 2 styled"), W.status())
	W.change("castbars.enabled", false)
	check("off from the options: saved for the next reload", W.options()["castbars.enabled"] == false and W.control("castbars.enabled").data.setting:GetValue() == false)
	clean(W, "module switches")
end

-- 11. Aura icons switched off at login are not touched, and a pool that fails once stops the aura part for everything queued after it.
do
	local W = newWorld({ saved = { options = { ["nameplates.auras"] = false } } })
	W.login()
	local plate = W.newPlate()
	local one = W.addAura(plate)
	W.showPlate("nameplate1", plate)
	local frames = #W.addonFrames
	W.tick()
	check("auras off at login: icons are not touched and no outline is made", auraLine(one) == AURA_PLAIN and W.holderOn(one.item) == nil and #W.addonFrames == frames and plateLine(W, plate) == ON, auraLine(one))
	W.change("nameplates.auras", true)
	W.tick()
	check("auras off at login: styled once switched on", auraLine(one) == AURA_ON and W.state(one.item) == "Sb")
	clean(W, "auras off at login")
	local V = newWorld()
	V.login()
	local plates, auras = {}, {}
	for i = 1, 4 do
		plates[i] = V.newPlate()
		auras[i] = V.addAura(plates[i])
		V.showPlate("nameplate" .. i, plates[i])
	end
	V.poolFailOnce = true
	V.tick()
	local styled = 0
	for i = 1, 4 do
		if auras[i].icon.texCoord then
			styled = styled + 1
		end
	end
	check("aura failure: the first icon list that fails stops the aura part for the plates queued after it", styled == 0 and has(V.status(), "Aura icons: stopped. EnumerateActive failed") and #V.out == 0, styled)
end

-- 10. Personal resource display.
do
	local W = newWorld({ resourceAtlas = "ui-hud-cooldownmanager-bar-bg" })
	W.login()
	for name, pair in pairs(W.prd) do
		local bar, inner = pair[1], pair[2]
		check("resource: " .. name .. " frame art faded, found by atlas in any case", inner.regions[1].alpha == 0 and inner.regions[2].alpha == 1 and inner.regions[1].shown)
		check("resource: " .. name .. " outlined with a backdrop, a holder that ignores the scale", W.state(bar) == "SB" and ringOf(W, bar, 1) and W.holderOn(bar).ignoreParentScale == true)
	end
	check("resource: three counted", has(W.status(), "Personal resource display: on, 3 styled"), W.status())
	-- Each bar has its own switch, and the backdrop its own.
	local frames, textures = #W.addonFrames, #W.addonTextures
	for _, key in ipairs({ "health", "power", "alt" }) do
		local bar, inner = W.prd[key][1], W.prd[key][2]
		W.change("resource." .. key, false)
		check("resource: " .. key .. " off puts Blizzard's art back, hides the outline, others untouched", inner.regions[1].alpha == 1 and W.state(bar) == "hb"
			and (key == "health" or W.prd.health[2].regions[1].alpha == 0) and (key == "power" or W.prd.power[2].regions[1].alpha == 0) and (key == "alt" or W.prd.alt[2].regions[1].alpha == 0))
		W.change("resource." .. key, true)
		check("resource: " .. key .. " on again, nothing made twice", inner.regions[1].alpha == 0 and W.state(bar) == "SB" and #W.addonFrames == frames and #W.addonTextures == textures)
	end
	W.change("resource.backdrop", false)
	check("resource: backdrop off keeps the edges", W.state(W.prd.health[1]) == "Sb" and W.state(W.prd.power[1]) == "Sb" and W.state(W.prd.alt[1]) == "Sb" and W.prd.health[2].regions[1].alpha == 0)
	W.change("resource.backdrop", true)
	W.change("resource.enabled", false)
	check("resource: the module off restores everything Blizzard drew", #W.diff("resource") == 0 and W.state(W.prd.power[1]) == "hb", table.concat(W.diff("resource"), "; "))
	W.change("resource.health", false)
	W.change("resource.enabled", true)
	check("resource: the module on again re-applies what is switched on, nothing made twice", W.prd.health[2].regions[1].alpha == 1 and W.prd.power[2].regions[1].alpha == 0
		and W.state(W.prd.alt[1]) == "SB" and W.state(W.prd.health[1]) == "hb" and #W.addonFrames == frames and #W.addonTextures == textures and has(W.status(), "Personal resource display: on, 3 styled"), W.status())
	clean(W, "resource")

	local N = newWorld({ noAlternatePower = true })
	N.login()
	check("resource: a missing bar is skipped", has(N.status(), "Personal resource display: on, 2 styled") and #N.out == 0, N.status())
	local M = newWorld({ missing = { PersonalResourceDisplayFrame = true } })
	M.login()
	check("resource: no display at all is no error", has(M.status(), "Personal resource display: on, 0 styled") and #M.out == 0 and #M.errors == 0)
	local F = newWorld({ forbidden = { PersonalResourceDisplayFrame = true } })
	F.login()
	check("resource: a forbidden display is left alone", has(F.status(), "Personal resource display: on, 0 styled") and F.prd.health[2].regions[1].alpha == 1 and #F.violations == 0, table.concat(F.violations, "|"))
	local O = newWorld({ saved = { options = { ["resource.power"] = false } } })
	O.login()
	check("resource: a bar switched off at login is never touched", O.prd.power[2].regions[1].alpha == 1 and O.state(O.prd.power[1]) == "." and O.prd.health[2].regions[1].alpha == 0
		and has(O.status(), "Personal resource display: on, 2 styled"), O.status())
	O.change("resource.power", true)
	check("resource: and styled when switched on", O.prd.power[2].regions[1].alpha == 0 and O.state(O.prd.power[1]) == "SB" and has(O.status(), "Personal resource display: on, 3 styled"), O.status())
	-- Art that cannot be found or read leaves Blizzard's frame, and the outline is still made.
	local A = newWorld({ resourceAtlas = "some-other-atlas" })
	A.login()
	check("resource: without art to fade the outline is drawn and nothing else changes", A.state(A.prd.health[1]) == "SB" and A.prd.health[2].regions[1].alpha == 1 and A.prd.health[2].regions[2].alpha == 1
		and #A.out == 0 and #A.violations == 0)
	local B2 = newWorld()
	for _, pair in pairs(B2.prd) do
		pair[2].regions[1] = B2.Rr(nil, ATLAS.barBackground, { atlasErrors = true })
	end
	B2.login()
	check("resource: an atlas that cannot be read is skipped without an error", B2.state(B2.prd.health[1]) == "SB" and B2.prd.health[2].regions[1].alpha == 1 and #B2.out == 0 and not has(B2.status(), "failed"), B2.status())
	local S2 = newWorld()
	for _, pair in pairs(S2.prd) do
		pair[2].regions[1] = S2.Rr(nil, ATLAS.barBackground, { atlasSecret = true })
	end
	S2.login()
	check("resource: an atlas that is secret is skipped without an error", S2.state(S2.prd.health[1]) == "SB" and S2.prd.health[2].regions[1].alpha == 1 and #S2.out == 0 and not has(S2.status(), "failed"), S2.status())
	-- Regions that cannot be listed fail the bar, not the module, until five have failed.
	local X = newWorld({ breakResource = true })
	X.login()
	check("resource failure: a few failing bars are skipped quietly, the first error is in the status", #X.out == 0 and has(X.status(), "Personal resource display: on, ") and has(X.status(), "3 failed. ")
		and has(X.status(), "GetRegions failed"), X.status())
	check("resource failure: the art is kept, the other modules ran", X.prd.power[2].regions[1].alpha == 1 and has(X.status(), "Action bars: on, 118 styled") and has(X.status(), "Cast bars: on, 5 styled"))
	local Y = newWorld({ breakResourceTextures = true })
	Y.login()
	check("resource failure: a bar that cannot take a replacement keeps its frame art", Y.prd.health[2].regions[1].alpha == 1 and Y.prd.power[2].regions[1].alpha == 1 and has(Y.status(), "3 failed. "), Y.status())
	-- A failure outside a single bar stops the module at once, with its message.
	local Z = newWorld()
	Z.env.PersonalResourceDisplayFrame = Z.B(nil, { HealthBarsContainer = setmetatable({}, { __index = function() error("container failed", 0) end }) })
	Z.login()
	check("resource failure: an error outside a bar stops the module at once and says so once", #Z.out == 1 and Z.out[1] == "Flat UI: Personal resource display stopped. /flatui status shows why. Type /reload if the look is left half changed."
		and has(Z.status(), "Personal resource display: stopped. container failed"), table.concat(Z.out, "|") .. Z.status())
	check("resource failure: the other modules ran", has(Z.status(), "Cast bars: on, 5 styled") and Z.prd.health[2].regions[1].alpha == 1)
	Z.change("resource.health", false)
	Z.change("resource.enabled", false)
	check("resource failure: a stopped module stays stopped", #Z.out == 1 and Z.ns.IsStopped("resource") and not Z.ns.Enabled("resource"))
end

-- 11. Swing timers: hidden, because Blizzard sets their alpha.
do
	-- At the default settings the bar is outlined and the whole timer is not.
	local D = newWorld()
	D.login()
	local p = D.swing.SwingTimerMainHandFrame
	check("swing: the three timers are styled at login with the default settings", has(D.status(), "Swing timers: on, 3 styled") and not has(D.status(), "Swing timers: on, 3 styled, ")
		and p.Border.shown == false and p.Background.shown == false and D.state(p.StatusBar) == "SB", D.line("Swing timers"))
	check("swing: the default settings raise nothing", not has(D.status(), "failed") and not has(D.status(), "Swing timers: stopped") and #D.out == 0 and #D.errors == 0 and #D.violations == 0, D.line("Swing timers"))
	local plain = true
	for _, name in ipairs({ "SwingTimerMainHandFrame", "SwingTimerOffHandFrame", "SwingTimerRangedFrame" }) do
		local t = D.swing[name]
		plain = plain and ringOf(D, t.StatusBar, 1) and D.state(t.StatusBar) == "SB" and D.state(t.timer) == "." and t.Border.shown == false and t.Background.shown == false
	end
	check("swing: at the defaults every timer has an outline and a backdrop around its bar and nothing around the whole timer", plain)
	local frames0, textures0 = #D.addonFrames, #D.addonTextures
	for i = 1, 8 do
		D.change("swing.backdrop", i % 2 == 0)
		D.change("swing.main", i % 2 == 1)
	end
	D.change("swing.main", true)
	D.change("swing.backdrop", true)
	check("swing: option changes at the defaults leave the module running", not D.ns.IsStopped("swing") and not has(D.status(), "failed") and #D.out == 0 and D.state(p.StatusBar) == "SB"
		and #D.addonFrames == frames0 and #D.addonTextures == textures0, D.line("Swing timers"))
	clean(D, "swing defaults")

	local W = newWorld({ missing = { SwingTimerRangedFrame = true }, saved = { options = { ["swing.idle"] = "show" } } })
	W.login()
	local parts = W.swing.SwingTimerMainHandFrame
	check("swing: frame art and background hidden, not faded", parts.Border.shown == false and parts.Background.shown == false and parts.Border.alpha == 1 and parts.Background.alpha == 1
		and parts.Border.calls.SetAlpha == nil and parts.Border.calls.SetShown == 1)
	check("swing: a missing timer is skipped", has(W.status(), "Swing timers: on, 2 styled") and #W.out == 0, W.status())
	check("swing: the bar is outlined, none around the whole timer", W.state(parts.StatusBar) == "SB" and ringOf(W, parts.StatusBar, 1) and W.state(parts.timer) == ".")
	-- Blizzard changes the alpha when the target is out of range: the art stays hidden.
	parts.Border:SetAlpha(0.4)
	parts.Background:SetAlpha(0.4)
	W.fire("PLAYER_TARGET_CHANGED")
	check("swing: Blizzard's alpha changes do not bring the art back", parts.Border.shown == false and parts.Background.shown == false)
	parts.Border:SetAlpha(1)
	parts.Background:SetAlpha(1)
	local off = W.swing.SwingTimerOffHandFrame
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.change("swing.outline", "Whole timer")
	check("swing: the whole timer when asked: it is outlined, the bar is not", W.state(parts.timer) == "SB" and ringOf(W, parts.timer, 1) and W.state(parts.StatusBar) == "hb"
		and parts.Border.shown == false, W.state(parts.StatusBar) .. W.state(parts.timer))
	check("swing: the same for every timer", W.state(off.timer) == "SB" and W.state(off.StatusBar) == "hb")
	check("swing: the whole timer's outline is made the first time it is wanted, one for each timer", #W.addonFrames == frames + 2 and #W.addonTextures == textures + 10,
		(#W.addonFrames - frames) .. " " .. (#W.addonTextures - textures))
	frames, textures = #W.addonFrames, #W.addonTextures
	W.change("swing.outline", "Bar only")
	check("swing: the bar again, the whole timer's outline hidden, nothing made twice", W.state(parts.StatusBar) == "SB" and W.state(parts.timer) == "hb" and #W.addonFrames == frames and #W.addonTextures == textures)
	W.change("swing.outline", "Whole timer")
	check("swing: and the whole timer again", W.state(parts.timer) == "SB" and W.state(parts.StatusBar) == "hb" and #W.addonFrames == frames and #W.addonTextures == textures)
	W.change("swing.backdrop", false)
	check("swing: backdrop off on the whole timer", W.state(parts.timer) == "Sb" and W.state(off.timer) == "Sb" and W.state(parts.StatusBar) == "hb")
	W.change("swing.outline", "Bar only")
	check("swing: backdrop off around the bar too", W.state(parts.StatusBar) == "Sb" and W.state(off.StatusBar) == "Sb" and W.state(parts.timer) == "hb")
	W.change("swing.backdrop", true)
	-- One timer at a time.
	W.change("swing.main", false)
	check("swing: main hand off shows its art and hides its outline, the others stay", parts.Border.shown and parts.Background.shown and W.state(parts.StatusBar) == "hb" and off.Border.shown == false
		and W.state(off.StatusBar) == "SB")
	W.change("swing.main", true)
	W.change("swing.off", false)
	check("swing: off hand off", off.Border.shown and off.Background.shown and W.state(off.StatusBar) == "hb" and parts.Border.shown == false and W.state(parts.StatusBar) == "SB")
	W.change("swing.off", true)
	-- The module off restores every timer. Back on, they are hidden again.
	W.change("swing.enabled", false)
	check("swing: the module off restores every timer", #W.diff("swing") == 0 and W.state(parts.StatusBar) == "hb" and W.state(off.StatusBar) == "hb", table.concat(W.diff("swing"), "; "))
	W.change("swing.outline", "Whole timer")
	W.change("swing.enabled", true)
	check("swing: on again: hidden, the whole timer outlined, nothing made twice", parts.Border.shown == false and W.state(parts.timer) == "SB" and W.state(parts.StatusBar) == "hb"
		and #W.addonFrames == frames and has(W.status(), "Swing timers: on, 2 styled"), W.status())
	clean(W, "swing")

	-- A swing timer saved with the whole timer outlined starts that way and makes no outline around the bar.
	local H = newWorld({ saved = { options = { ["swing.outline"] = "frame" } } })
	H.login()
	check("swing: saved as the whole timer: only that outline is made", H.state(H.swing.SwingTimerMainHandFrame.timer) == "SB" and H.state(H.swing.SwingTimerMainHandFrame.StatusBar) == "." and not has(H.status(), "failed"))

	-- Timers that are forbidden, have no bar, or have no art.
	local F = newWorld({ forbidden = { SwingTimerOffHandFrame = true, ["SwingTimerRangedFrame.StatusBar"] = true } })
	F.login()
	check("swing: a forbidden timer, or one whose bar is forbidden, is left alone", has(F.status(), "Swing timers: on, 1 styled") and F.swing.SwingTimerRangedFrame.Border.shown
		and F.swing.SwingTimerMainHandFrame.Border.shown == false and #F.violations == 0 and #F.out == 0, F.status() .. table.concat(F.violations, "|"))
	-- A switched-off timer at login is never touched.
	local O = newWorld({ saved = { options = { ["swing.ranged"] = false } } })
	O.login()
	check("swing: a timer switched off at login is never touched", O.swing.SwingTimerRangedFrame.Border.shown and O.state(O.swing.SwingTimerRangedFrame.StatusBar) == "." and has(O.status(), "Swing timers: on, 2 styled"), O.status())
	O.change("swing.ranged", true)
	check("swing: and hidden when switched on", O.swing.SwingTimerRangedFrame.Border.shown == false and O.state(O.swing.SwingTimerRangedFrame.StatusBar) == "SB" and has(O.status(), "Swing timers: on, 3 styled"))
end

-- 12. Cast bars: the target and focus bars get edges of their own, with no addon frame attached.
do
	local W = newWorld()
	W.login()
	for name, cast in pairs(W.cast) do
		check("cast: " .. name .. " art faded", cast.parts.Border.alpha == 0 and cast.parts.Background.alpha == 0 and cast.parts.TextBorder.alpha == 0
			and cast.parts.DropShadow.alpha == 0 and cast.parts.Border.shown and W.state(cast.bar) ~= ".")
		local backdrop = W.backdropOn(cast.bar)
		check("cast: " .. name .. " has a backdrop", backdrop and backdrop.shown and near(backdrop.color[4], 0.85))
	end
	check("cast: player bar has a holder", ringed(W, W.holderOn(W.cast.PlayerCastingBarFrame.bar), 1) and W.holderOn(W.cast.PlayerCastingBarFrame.bar).parent == W.cast.PlayerCastingBarFrame.bar)
	check("cast: the overlay player bar and the pet bar too", ringed(W, W.holderOn(W.cast.OverlayPlayerCastingBarFrame.bar), 1) and ringed(W, W.holderOn(W.cast.PetCastingBarFrame.bar), 1))
	local target, focus = W.cast.TargetFrameSpellBar, W.cast.FocusFrameSpellBar
	check("cast: no addon frame on the target and focus bars", W.holderOn(target.bar) == nil and W.holderOn(focus.bar) == nil and #W.addonFrames > 0)
	local ok, t = ringed(W, target.bar, PX / 0.64)
	check("cast: target edges are one pixel in the bar's own units", ok and #target.inner.regions == 5, t)
	ok, t = ringed(W, focus.bar, PX / (0.64 * 0.75))
	check("cast: a scaled bar still gets one pixel", ok, t)
	check("cast: five counted", has(W.status(), "Cast bars: on, 5 styled"), W.status())
	check("cast: the spell name plate is faded by default", W.cast.PlayerCastingBarFrame.parts.TextBorder.alpha == 0)
	-- Options.
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.change("castbars.textPlate", true)
	check("cast: the spell name plate comes back when asked, the rest stays faded", W.cast.PlayerCastingBarFrame.parts.TextBorder.alpha == 1 and W.cast.TargetFrameSpellBar.parts.TextBorder.alpha == 1
		and W.cast.PlayerCastingBarFrame.parts.Border.alpha == 0 and W.cast.PlayerCastingBarFrame.parts.DropShadow.alpha == 0)
	W.change("castbars.textPlate", false)
	W.change("castbars.backdrop", false)
	check("cast: backdrop off keeps the edges", W.state(W.cast.PlayerCastingBarFrame.bar) == "Sb" and W.state(target.bar) == "Sb" and W.state(focus.bar) == "Sb" and W.state(W.cast.PetCastingBarFrame.bar) == "Sb")
	W.change("castbars.backdrop", true)
	for _, case in ipairs({ { "player", { "PlayerCastingBarFrame", "OverlayPlayerCastingBarFrame" } }, { "pet", { "PetCastingBarFrame" } },
		{ "target", { "TargetFrameSpellBar" } }, { "focus", { "FocusFrameSpellBar" } } }) do
		W.change("castbars." .. case[1], false)
		local restored, others = true, true
		local mine = {}
		for _, n in ipairs(case[2]) do
			mine[n] = true
			local c = W.cast[n]
			restored = restored and c.parts.Border.alpha == 1 and c.parts.Background.alpha == 1 and c.parts.TextBorder.alpha == 1 and c.parts.DropShadow.alpha == 1 and W.state(c.bar) == "hb"
		end
		for n, c in pairs(W.cast) do
			if not mine[n] then
				others = others and c.parts.Border.alpha == 0 and W.state(c.bar) == "SB"
			end
		end
		check("cast: " .. case[1] .. " off restores " .. table.concat(case[2], " and ") .. " and nothing else", restored and others)
		W.change("castbars." .. case[1], true)
		local again = true
		for _, n in ipairs(case[2]) do
			again = again and W.cast[n].parts.Border.alpha == 0 and W.state(W.cast[n].bar) == "SB"
		end
		check("cast: " .. case[1] .. " on again, nothing made twice", again and #W.addonFrames == frames and #W.addonTextures == textures)
	end
	W.change("castbars.enabled", false)
	check("cast: the module off restores everything Blizzard drew", #W.diff("castbars") == 0, table.concat(W.diff("castbars"), "; "))
	W.change("castbars.enabled", true)
	check("cast: and on again", W.cast.TargetFrameSpellBar.parts.Border.alpha == 0 and W.state(W.cast.TargetFrameSpellBar.bar) == "SB" and #W.addonFrames == frames and #W.addonTextures == textures
		and ringed(W, W.cast.TargetFrameSpellBar.bar, PX / 0.64))
	clean(W, "cast")

	local M = newWorld({ missing = { PetCastingBarFrame = true, FocusFrameSpellBar = true }, forbidden = { TargetFrameSpellBar = true } })
	M.login()
	check("cast: missing and forbidden bars are skipped", has(M.status(), "Cast bars: on, 2 styled") and #M.out == 0 and #M.violations == 0, M.status() .. table.concat(M.violations, "|"))
	local O = newWorld({ saved = { options = { ["castbars.target"] = false, ["castbars.textPlate"] = true } } })
	O.login()
	check("cast: a bar switched off at login is never touched", O.cast.TargetFrameSpellBar.parts.Border.alpha == 1 and O.state(O.cast.TargetFrameSpellBar.bar) == "." and O.cast.PlayerCastingBarFrame.parts.Border.alpha == 0
		and O.cast.PlayerCastingBarFrame.parts.TextBorder.alpha == 1 and has(O.status(), "Cast bars: on, 4 styled"), O.status())
end

-- 13. Action bars.
local ALL_BUTTONS = {}
do
	for _, entry in ipairs({ { "ActionButton", 12, "main" }, { "MultiBarBottomLeftButton", 12, "extra" }, { "MultiBarBottomRightButton", 12, "extra" }, { "MultiBarLeftButton", 12, "extra" },
		{ "MultiBarRightButton", 12, "extra" }, { "MultiBar5Button", 12, "extra" }, { "MultiBar6Button", 12, "extra" }, { "MultiBar7Button", 12, "extra" },
		{ "PetActionButton", 10, "pet" }, { "StanceButton", 10, "stance" }, { "PossessButton", 2, "stance" } }) do
		for i = 1, entry[2] do
			ALL_BUTTONS[#ALL_BUTTONS + 1] = { name = entry[1] .. i, group = entry[3] }
		end
	end
end
local TINTS = { Border = { 1, 1, 1, 0.35 }, Flash = { 1, 0, 0, 0.3 }, NewActionTexture = { 1, 1, 1, 0.25 }, SpellHighlightTexture = { 1, 0.82, 0, 0.5 },
	HighlightTexture = { 1, 1, 1, 0.2 }, CheckedTexture = { 1, 209 / 255, 0, 0.3 }, PushedTexture = { 1, 1, 1, 0.25 } }
local function tinted(parts, key)
	local region = parts[key] or parts.getterRegions[key]
	local want = TINTS[key]
	local c = region.color
	return c ~= nil and near(c[1], want[1]) and near(c[2], want[2]) and near(c[3], want[3]) and near(c[4], want[4]) and region.allPoints == parts.icon
end
local function buttonLine(W, name)
	local parts = W.buttons[name].parts
	local normal = parts.NormalTexture or parts.getterRegions.NormalTexture
	return string.format("art=%s,%s,%s tc=%s ring=%s", g(normal.alpha), g(parts.SlotArt.alpha), g(parts.SlotBackground.alpha), texcoord(parts.icon), W.state(parts.icon))
end
local BUTTON_ON, BUTTON_OFF = "art=0,0,0 tc=0.08,0.92,0.08,0.92 ring=SB", "art=1,1,1 tc=0,1,0,1 ring=hb"

do
	local W = newWorld()
	W.login()
	local entry = W.buttons.ActionButton3
	local parts, button = entry.parts, entry.button
	check("button: frame and slot art faded, outlined, cropped", buttonLine(W, "ActionButton3") == BUTTON_ON, buttonLine(W, "ActionButton3"))
	local tintBad = {}
	for key in pairs(TINTS) do
		if not tinted(parts, key) then
			tintBad[#tintBad + 1] = key
		end
	end
	check("button: equipped outline, flash, highlights, pushed and checked art are flat tints on the icon", #tintBad == 0, table.concat(tintBad, ","))
	check("button: Blizzard still shows and hides the tints", parts.Border.alpha == 1 and parts.Flash.alpha == 1 and parts.HighlightTexture.alpha == 1 and parts.Border.shown)
	check("button: square icon: the mask is taken off", parts.icon.masks[parts.IconMask] == nil and parts.IconMask.alpha == 1)
	check("button: cooldowns cover the icon", parts.cooldown.allPoints == parts.icon and parts.chargeCooldown.allPoints == parts.icon and parts.lossOfControlCooldown.allPoints == parts.icon)
	local holder = W.holderOn(parts.icon)
	check("button: outlined around the icon", holder and holder.parent == button and ringed(W, holder, 1) and W.backdropOn(parts.icon) ~= nil and W.backdropOn(parts.icon).shown)
	local bad = {}
	for _, b in ipairs(ALL_BUTTONS) do
		if buttonLine(W, b.name) ~= BUTTON_ON or W.holderOn(W.buttons[b.name].parts.icon) == nil then
			bad[#bad + 1] = b.name
		end
	end
	check("button: all 118 are styled", #bad == 0 and has(W.status(), "Action bars: on, 118 styled"), table.concat(bad, ","))

	-- Blizzard updates the art (Edit Mode, bar changes). Nothing is hooked: the look comes back on the next frame after the events that run the update.
	W.flush()
	local frames, textures = #W.addonFrames, #W.addonTextures
	local pushed = parts.PushedTexture.calls.SetColorTexture
	parts.NormalTexture:SetAlpha(1)
	parts.SlotArt:SetAlpha(1)
	W.update("ActionButton3")
	check("button: Blizzard's update still runs and nothing follows it", entry.inner.artUpdates == 1 and parts.SlotArt.shown and buttonLine(W, "ActionButton3") ~= BUTTON_ON, buttonLine(W, "ActionButton3"))
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	check("barkeep: the look is not put back in the event but on the next frame", buttonLine(W, "ActionButton3") ~= BUTTON_ON, buttonLine(W, "ActionButton3"))
	W.flush()
	check("barkeep: after EDIT_MODE_LAYOUTS_UPDATED reset the art, the faded art and the tint come back on the next frame", buttonLine(W, "ActionButton3") == BUTTON_ON and tinted(parts, "PushedTexture"),
		buttonLine(W, "ActionButton3"))
	-- The game applies the layout again on a talent change with no EDIT_MODE_LAYOUTS_UPDATED (EditModeManager.lua:203-206): the art comes back the same way.
	parts.NormalTexture:SetAlpha(1)
	parts.SlotArt:SetAlpha(1)
	W.update("ActionButton3")
	W.fire("PLAYER_SPECIALIZATION_CHANGED")
	check("barkeep: the look is not put back in a specialization change but on the next frame", buttonLine(W, "ActionButton3") ~= BUTTON_ON, buttonLine(W, "ActionButton3"))
	W.flush()
	check("barkeep: after PLAYER_SPECIALIZATION_CHANGED the faded art and the tint come back on the next frame", buttonLine(W, "ActionButton3") == BUTTON_ON and tinted(parts, "PushedTexture"), buttonLine(W, "ActionButton3"))
	check("button: nothing added twice, the tints that Blizzard keeps are not applied again", #W.addonFrames == frames and #W.addonTextures == textures and parts.Border.calls.SetColorTexture == 1
		and parts.icon.calls.RemoveMaskTexture == 1 and has(W.status(), "Action bars: on, 118 styled"), tostring(parts.Border.calls.SetColorTexture))
	check("button: but the pushed art, which Blizzard sets again, is tinted again", parts.PushedTexture.calls.SetColorTexture == pushed + 2, tostring(parts.PushedTexture.calls.SetColorTexture))
	check("barkeep: ActionBars hooks nothing on a button or on MainActionBar", W.hooks == 0, W.hooks)

	-- The bar.
	check("bar: frame art and end caps faded", W.bar.BorderArt.alpha == 0 and W.bar.EndCaps.LeftEndCap.Texture.alpha == 0 and W.bar.EndCaps.RightEndCap.Texture.alpha == 0)
	W.updateDividers()
	check("bar: Blizzard lays a divider out and nothing follows the call", W.bar.hRaw.items[1].alpha ~= 0)
	W.frame(16)
	check("barkeep: the dividers the game makes after a grid change are faded within 0.25 s", W.bar.hRaw.items[1].alpha == 0)
	local v = W.addDivider(true)
	W.updateDividers()
	W.frame(16)
	check("bar: horizontal and vertical dividers", W.bar.hRaw.items[1].alpha == 0 and W.bar.hRaw.items[2].alpha == 0 and v.alpha == 0)
	W.combat = true
	W.updateDividers()
	local w = W.addDivider(false)
	W.frame(16)
	check("barkeep: and in combat, with nothing but SetAlpha called on them", W.bar.hRaw.items[#W.bar.hRaw.items].alpha == 0 and w.alpha == 0 and #W.violations == 0, W.bar.hRaw.items[#W.bar.hRaw.items].alpha)
	W.combat = false
	clean(W, "action bars")
end

-- 13b. Each group, and each option, from the options.
do
	local W = newWorld()
	W.login()
	local d1 = W.addDivider(false)
	local d2 = W.addDivider(true)
	W.change("actionbars.frame", false)
	W.change("actionbars.frame", true)
	check("bar: existing dividers are faded once the bar is refreshed", d1.alpha == 0 and d2.alpha == 0)
	for _, group in ipairs({ "main", "extra", "pet", "stance" }) do
		W.change("actionbars." .. group, false)
		local bad = {}
		for _, b in ipairs(ALL_BUTTONS) do
			local want = b.group == group and BUTTON_OFF or BUTTON_ON
			if buttonLine(W, b.name) ~= want then
				bad[#bad + 1] = b.name .. "=" .. buttonLine(W, b.name)
			end
		end
		check("buttons: " .. group .. " off restores exactly its group", #bad == 0, table.concat(bad, "; "))
		W.change("actionbars." .. group, true)
		bad = {}
		for _, b in ipairs(ALL_BUTTONS) do
			if buttonLine(W, b.name) ~= BUTTON_ON then
				bad[#bad + 1] = b.name
			end
		end
		check("buttons: " .. group .. " on again", #bad == 0, table.concat(bad, "; "))
	end
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.change("actionbars.backdrop", false)
	local backdropBad = 0
	for _, b in ipairs(ALL_BUTTONS) do
		if W.state(W.buttons[b.name].parts.icon) ~= "Sb" then
			backdropBad = backdropBad + 1
		end
	end
	check("buttons: backdrop off keeps the edges on all 118", backdropBad == 0, backdropBad)
	W.change("actionbars.backdrop", true)
	check("buttons: backdrop on, nothing made twice", W.state(W.buttons.PetActionButton4.parts.icon) == "SB" and #W.addonFrames == frames and #W.addonTextures == textures)
	W.change("actionbars.crop", 12)
	local cropBad = {}
	for _, b in ipairs(ALL_BUTTONS) do
		if texcoord(W.buttons[b.name].parts.icon) ~= "0.12,0.88,0.12,0.88" then
			cropBad[#cropBad + 1] = b.name
		end
	end
	check("buttons: the crop reaches every icon", #cropBad == 0, table.concat(cropBad, ","))
	W.change("actionbars.crop", 0)
	check("buttons: no crop is the whole texture", texcoord(W.buttons.ActionButton1.parts.icon) == "0,1,0,1" and W.state(W.buttons.ActionButton1.parts.icon) == "SB")
	W.change("actionbars.crop", 15)
	check("buttons: the largest crop", texcoord(W.buttons.StanceButton10.parts.icon) == "0.15,0.85,0.15,0.85")
	W.change("actionbars.crop", 8)
	W.change("actionbars.main", false)
	W.change("actionbars.crop", 5)
	check("buttons: a group that is off keeps the whole texture when the crop changes", texcoord(W.buttons.ActionButton1.parts.icon) == "0,1,0,1" and texcoord(W.buttons.MultiBarLeftButton1.parts.icon) == "0.05,0.95,0.05,0.95")
	W.change("actionbars.main", true)
	W.change("actionbars.crop", 8)
	-- The bar.
	W.change("actionbars.frame", false)
	check("bar: frame art back, caps and dividers still hidden", W.bar.BorderArt.alpha == 1 and W.bar.EndCaps.LeftEndCap.Texture.alpha == 0 and d1.alpha == 0)
	W.change("actionbars.frame", true)
	W.change("actionbars.caps", false)
	check("bar: gryphons back, frame and dividers still hidden", W.bar.EndCaps.LeftEndCap.Texture.alpha == 1 and W.bar.EndCaps.RightEndCap.Texture.alpha == 1 and W.bar.BorderArt.alpha == 0 and d1.alpha == 0)
	W.change("actionbars.caps", true)
	W.change("actionbars.dividers", false)
	check("bar: dividers back, frame and gryphons still hidden", d1.alpha == 1 and d2.alpha == 1 and W.bar.BorderArt.alpha == 0 and W.bar.EndCaps.LeftEndCap.Texture.alpha == 0)
	W.updateDividers()
	check("bar: dividers Blizzard lays out later are left alone while they are shown", W.bar.hRaw.items[#W.bar.hRaw.items].alpha == 1)
	W.change("actionbars.dividers", true)
	check("bar: and faded again, including the new one", d1.alpha == 0 and W.bar.hRaw.items[#W.bar.hRaw.items].alpha == 0)
	-- The module off puts back everything it faded and hides every outline.
	W.change("actionbars.enabled", false)
	local left = {}
	for _, line in ipairs(W.diff("actionbar")) do
		if not (line:find(" masks: ", 1, true) or line:find(" color: ", 1, true) or line:find(" allPoints: ", 1, true) or line:find(" points: ", 1, true) or line:find(" atlas: ", 1, true)) then
			left[#left + 1] = line
		end
	end
	check("buttons: the module off restores alpha, visibility and texture coordinates of everything Blizzard drew", #left == 0, table.concat(left, "; "):sub(1, 400))
	local hidden = 0
	for _, b in ipairs(ALL_BUTTONS) do
		if W.state(W.buttons[b.name].parts.icon) == "hb" then
			hidden = hidden + 1
		end
	end
	check("buttons: and hides all 118 outlines", hidden == 118, hidden)
	W.update("ActionButton1")
	check("buttons: an art update after that leaves Blizzard's art alone", buttonLine(W, "ActionButton1") == BUTTON_OFF)
	W.updateDividers()
	check("bar: and new dividers", W.bar.hRaw.items[#W.bar.hRaw.items].alpha == 1)
	W.change("actionbars.enabled", true)
	local again = 0
	for _, b in ipairs(ALL_BUTTONS) do
		if buttonLine(W, b.name) == BUTTON_ON then
			again = again + 1
		end
	end
	check("buttons: the module on again styles all 118, nothing made twice", again == 118 and #W.addonFrames == frames and #W.addonTextures == textures and has(W.status(), "Action bars: on, 118 styled")
		and W.hooks == 0, W.status())
	check("bar: and the bar", W.bar.BorderArt.alpha == 0 and d1.alpha == 0 and W.bar.EndCaps.LeftEndCap.Texture.alpha == 0)
	clean(W, "action bar options")
end

-- 13c. Square icons and flat highlights are applied once, and live when turned on.
do
	local W = newWorld({ saved = { options = { ["actionbars.square"] = false, ["actionbars.tints"] = false } } })
	W.login()
	local parts = W.buttons.ActionButton1.parts
	check("square off: icons keep their mask and cooldowns", parts.icon.masks[parts.IconMask] == true and parts.cooldown.allPoints == nil and parts.chargeCooldown.allPoints == nil)
	check("tints off: Blizzard's highlight art is untouched", parts.Border.color == nil and parts.Flash.color == nil and parts.PushedTexture.color == nil and parts.HighlightTexture.color == nil
		and parts.CheckedTexture.color == nil and parts.NewActionTexture.color == nil and parts.SpellHighlightTexture.color == nil and parts.PushedTexture.atlas ~= nil)
	check("square and tints off: the frame art is still replaced", buttonLine(W, "ActionButton1") == BUTTON_ON)
	W.update("ActionButton1")
	check("tints off: and an art update still leaves Blizzard's pushed art", parts.PushedTexture.color == nil)
	W.change("actionbars.square", true)
	check("square on: the mask comes off and the cooldowns cover the icon at once", parts.icon.masks[parts.IconMask] == nil and parts.cooldown.allPoints == parts.icon and parts.chargeCooldown.allPoints == parts.icon
		and parts.lossOfControlCooldown.allPoints == parts.icon and parts.Border.color == nil)
	W.change("actionbars.tints", true)
	local bad = {}
	for key in pairs(TINTS) do
		if not tinted(parts, key) then
			bad[#bad + 1] = key
		end
	end
	check("tints on: every highlight is a flat tint at once", #bad == 0, table.concat(bad, ","))
	W.change("actionbars.crop", 9)
	W.change("actionbars.crop", 8)
	W.change("actionbars.backdrop", false)
	W.change("actionbars.backdrop", true)
	check("square and tints: applied once however often the buttons are refreshed", parts.icon.calls.RemoveMaskTexture == 1 and parts.Border.calls.SetColorTexture == 1 and parts.Flash.calls.SetColorTexture == 1
		and parts.cooldown.calls.SetAllPoints == 1 and parts.cooldown.calls.ClearAllPoints == 1, tostring(parts.Border.calls.SetColorTexture))
	W.change("actionbars.square", false)
	W.change("actionbars.tints", false)
	check("square off again: the mask is back at once, the moved cooldowns and the flat tints wait for /reload, nothing raises", parts.icon.masks[parts.IconMask] == true and parts.cooldown.allPoints == parts.icon
		and tinted(parts, "Border") and #W.violations == 0 and #W.out == 0)
	clean(W, "square and tints")
end

-- 13d. Art reached through getters, and buttons that are missing, forbidden or odd.
do
	local W = newWorld({ getterTextures = true })
	W.login()
	local parts = W.buttons.ActionButton2.parts
	check("getters: the normal texture is found through GetNormalTexture and faded", buttonLine(W, "ActionButton2") == BUTTON_ON, buttonLine(W, "ActionButton2"))
	local bad = {}
	for key in pairs(TINTS) do
		if key == "PushedTexture" or key == "HighlightTexture" or key == "CheckedTexture" then
			if not tinted(parts, key) then
				bad[#bad + 1] = key
			end
		end
	end
	check("getters: highlight, pushed and checked art through their getters", #bad == 0, table.concat(bad, ","))
	W.update("ActionButton2")
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	check("getters: and again after an art update and the next frame", buttonLine(W, "ActionButton2") == BUTTON_ON and tinted(parts, "PushedTexture"))
	clean(W, "getters")
	local M = newWorld({ missing = { ActionButton5 = true, PossessButton1 = true }, forbidden = { ActionButton6 = true, MultiBarLeftButton1 = true } })
	M.login()
	check("buttons: missing and forbidden buttons are skipped", has(M.status(), "Action bars: on, 114 styled") and #M.out == 0 and #M.violations == 0 and M.hooks == 0, M.status() .. " " .. M.hooks)
	local O = newWorld({ saved = { options = { ["actionbars.extra"] = false, ["actionbars.pet"] = false } } })
	O.login()
	check("buttons: groups switched off at login are not touched, not outlined, not counted", buttonLine(O, "MultiBarLeftButton3") == "art=1,1,1 tc=- ring=." and buttonLine(O, "PetActionButton1") == "art=1,1,1 tc=- ring=."
		and buttonLine(O, "ActionButton1") == BUTTON_ON and has(O.status(), "Action bars: on, 24 styled"), O.status())
	check("buttons: and none is hooked", O.hooks == 0, O.hooks)
	O.change("actionbars.extra", true)
	check("buttons: and styled once switched on", buttonLine(O, "MultiBarLeftButton3") == BUTTON_ON and has(O.status(), "Action bars: on, 108 styled"), O.status())
	-- A module that is off at login does not hook anything. Turning it on hooks once.
	local P = newWorld({ saved = { options = { ["actionbars.enabled"] = false } } })
	P.login()
	check("action bars off at login: no button hooked, nothing touched", P.hooks == 0 and buttonLine(P, "ActionButton1") == "art=1,1,1 tc=- ring=." and P.bar.BorderArt.alpha == 1 and has(P.status(), "Action bars: off"), P.status())
	P.change("actionbars.enabled", true)
	check("action bars switched on later: styled, and nothing is hooked", P.hooks == 0 and buttonLine(P, "ActionButton1") == BUTTON_ON and P.bar.BorderArt.alpha == 0 and has(P.status(), "Action bars: on, 118 styled"), P.status())
	P.change("actionbars.crop", 3)
	P.change("actionbars.crop", 8)
	check("action bars: hooks are not added by later refreshes", P.hooks == 0)
	clean(P, "action bars switched on later")
end

-- 13e. Failing buttons: a button that fails is counted once, and five different ones stop the module.
do
	local function broken(W, name)
		W.buttons[name].inner.CreateTexture = function() error("CreateTexture failed", 0) end
	end
	local W = newWorld({ saved = { options = { ["actionbars.pet"] = false } } })
	for i = 1, 3 do
		broken(W, "ActionButton" .. i)
	end
	broken(W, "PetActionButton1")
	broken(W, "PetActionButton2")
	W.login()
	check("buttons failing: three failing buttons are skipped and counted, the rest styled", has(W.status(), "Action bars: on, 105 styled, 3 failed. CreateTexture failed") and #W.out == 0 and buttonLine(W, "ActionButton4") == BUTTON_ON, W.status())
	local kept = true
	for i = 1, 3 do
		local parts = W.buttons["ActionButton" .. i].parts
		kept = kept and parts.NormalTexture.alpha == 1 and parts.SlotArt.alpha == 1 and parts.SlotBackground.alpha == 1 and W.holderOn(parts.icon) == nil
	end
	check("buttons failing: a button that cannot be given a frame of the addon's keeps Blizzard's, not neither", kept)
	W.change("actionbars.crop", 9)
	W.change("actionbars.crop", 10)
	W.change("actionbars.backdrop", false)
	W.change("actionbars.backdrop", true)
	W.update("ActionButton1")
	W.update("ActionButton2")
	W.update("ActionButton3")
	check("buttons failing: the same three buttons failing again and again are still three, and the module runs on", has(W.status(), "Action bars: on, 105 styled, 3 failed. ") and #W.out == 0
		and not W.ns.IsStopped("actionbars") and texcoord(W.buttons.ActionButton4.parts.icon) == "0.1,0.9,0.1,0.9", W.status())
	W.change("actionbars.pet", true)
	check("buttons failing: the module stops at the fifth different button, and says so once", #W.out == 1 and W.out[1] == "Flat UI: Action bars stopped. /flatui status shows why. Type /reload if the look is left half changed."
		and has(W.status(), "Action bars: stopped. CreateTexture failed") and W.ns.IsStopped("actionbars"), table.concat(W.out, "|") .. W.status())
	local left = {}
	for _, line in ipairs(W.diff("actionbar")) do
		if not (line:find(" color: ", 1, true) or line:find(" allPoints: ", 1, true) or line:find(" points: ", 1, true) or line:find(" atlas: ", 1, true)) then
			left[#left + 1] = line
		end
	end
	check("buttons failing: when it stops, Blizzard's art, icon shape and masks come back on the buttons it had styled", #left == 0 and buttonLine(W, "ActionButton4") == BUTTON_OFF and buttonLine(W, "ActionButton12") == BUTTON_OFF
		and W.state(W.buttons.ActionButton4.parts.icon) == "hb" and W.bar.BorderArt.alpha == 1, table.concat(left, "; "):sub(1, 300))
	local before = texcoord(W.buttons.ActionButton10.parts.icon)
	W.change("actionbars.crop", 12)
	W.update("ActionButton10")
	W.updateDividers()
	check("buttons failing: once stopped, an art update or an option changes nothing", texcoord(W.buttons.ActionButton10.parts.icon) == before and buttonLine(W, "ActionButton10") == BUTTON_OFF and #W.out == 1,
		texcoord(W.buttons.ActionButton10.parts.icon))
end

-- 13f. The main bar frame may be forbidden or missing.
do
	local F = newWorld({ forbidden = { MainActionBar = true } })
	F.login()
	check("main bar: a forbidden bar is left alone, the buttons are styled", F.bar.BorderArt.alpha == 1 and buttonLine(F, "ActionButton1") == BUTTON_ON and #F.violations == 0 and #F.out == 0
		and has(F.status(), "Action bars: on, 118 styled") and F.hooks == 0, F.status() .. table.concat(F.violations, "|"))
	local M = newWorld({ missing = { MainActionBar = true } })
	M.login()
	check("main bar: a missing bar is no error, the buttons are styled", buttonLine(M, "ActionButton1") == BUTTON_ON and #M.violations == 0 and #M.out == 0 and has(M.status(), "Action bars: on, 118 styled"))
end

-- 14. The UI scale is the game's own. A change made in the options is written to useUiScale and uiscale 0.3 seconds after the last one, out of combat, and UIParent.SetScale is never called.
do
	local W = newWorld()
	W.login()
	local target = W.cast.TargetFrameSpellBar.bar
	check("scale: off by default, UIParent and the game's variables untouched", W.setScaleCalls == 0 and W.scale() == 0.64 and W.scaleWrites() == 0 and W.ns.Get("general.scaleOn") == false)
	W.change("general.thickness", 2)
	W.change("general.border", "ff112233")
	W.fire("DISPLAY_SIZE_CHANGED")
	W.fire("UI_SCALE_CHANGED")
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.change("general.thickness", 1)
	W.change("general.border", "ff000000")
	W.advance(1)
	check("scale: off, nothing touches UIParent or the variables", W.setScaleCalls == 0 and W.scale() == 0.64 and W.scaleWrites() == 0)
	W.gameScale(0.7)
	check("scale: off, the game's own change is kept", W.scale() == 0.7 and W.setScaleCalls == 0)
	W.gameScale(0.85, "PLAYER_ENTERING_WORLD")
	W.change("general.scaleOn", true)
	W.advance(0.3)
	check("scale on: with no scale saved the slider starts from the scale on screen", W.ns.Get("general.scale") == 85 and W.setScaleCalls == 0 and near(W.scale(), 0.85),
		tostring(W.ns.Get("general.scale")) .. " " .. W.setScaleCalls)
	check("scale on: the first write holds both variables", W.cvars.useUiScale == "1" and W.cvars.uiscale == "0.85" and W.scaleWrites() == 2, W.cvars.uiscale .. " " .. W.scaleWrites())
	check("scale on: and the game's values are kept for the account", W.env.FlatUIDB.scaleGame and W.env.FlatUIDB.scaleGame.use == "0" and W.env.FlatUIDB.scaleGame.scale == "0.64")
	local writes = W.scaleWrites()
	W.change("general.scale", 65)
	check("scale on: a new value is not written at once", W.scaleWrites() == writes and near(W.scale(), 0.85))
	W.advance(0.29)
	check("scale on: nor 0.29 seconds later", W.scaleWrites() == writes and near(W.scale(), 0.85))
	W.advance(0.01)
	check("scale on: but 0.3 seconds later, by the variable and no SetScale, and edges drawn on the bars follow", near(W.scale(), 0.65) and W.cvars.uiscale == "0.65" and W.setScaleCalls == 0
		and ringed(W, target, PX / 0.65), W.scale())
	W.change("general.scale", 115)
	W.advance(0.3)
	check("scale: 115 percent", near(W.scale(), 1.15) and ringed(W, target, PX / 1.15) and W.setScaleCalls == 0, W.scale())
	W.change("general.scale", 80)
	W.advance(0.3)
	writes = W.scaleWrites()
	W.change("general.thickness", 2)
	W.change("general.backdrop", "ff102030")
	W.change("nameplates.dim", true)
	W.advance(1)
	check("scale on: other options write nothing", W.scaleWrites() == writes and near(W.scale(), 0.8) and ringed(W, target, 2 * PX / 0.8), W.scaleWrites())
	W.change("general.thickness", 1)
	for _, e in ipairs({ "UI_SCALE_CHANGED", "DISPLAY_SIZE_CHANGED", "PLAYER_ENTERING_WORLD" }) do
		W.fire(e)
		W.advance(1)
	end
	check("scale on: the game's scale events only read back, nothing is written and UIParent is not set", W.scaleWrites() == writes and W.setScaleCalls == 0)
	W.change("general.scaleOn", false)
	check("scale off: the game's values come back 0.3 seconds later, not at once", W.cvars.uiscale == "0.8" and W.cvars.useUiScale == "1")
	W.advance(0.3)
	check("scale off: useUiScale and uiscale hold what the game had, and the account keeps nothing", W.cvars.useUiScale == "0" and W.cvars.uiscale == "0.64" and W.env.FlatUIDB.scaleGame == nil
		and W.setScaleCalls == 0, W.cvars.uiscale)
	W.change("general.scaleOn", true)
	W.advance(0.3)
	check("scale on again: the scale chosen before, no new start from the screen", W.cvars.uiscale == "0.8" and W.ns.Get("general.scale") == 80 and W.setScaleCalls == 0, W.cvars.uiscale)
	clean(W, "scale")
end

-- 14a. A slider that is dragged writes the variable once, 0.3 seconds after it stops.
do
	local W = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 65 } } })
	W.login()
	W.change("general.scale", 66)
	W.advance(0.3)
	local writes = W.scaleWrites()
	for v = 67, 80 do
		W.change("general.scale", v)
		W.advance(0.05)
	end
	check("scale drag: nothing is written while the slider moves", W.scaleWrites() == writes and near(W.scale(), 0.66), W.scaleWrites() .. " " .. W.scale())
	W.advance(0.24)
	check("scale drag: nor 0.29 seconds after the last step", W.scaleWrites() == writes and near(W.scale(), 0.66))
	local outlines = W.look(W.buttons.ActionButton1.parts.icon).top.calls.SetHeight
	W.advance(0.01)
	check("scale drag: written once, the last value, 0.3 seconds after the last step, with one resize of the outlines", W.scaleWrites() == writes + 1 and near(W.scale(), 0.8)
		and W.look(W.buttons.ActionButton1.parts.icon).top.calls.SetHeight == outlines + 1, W.scaleWrites() .. " " .. W.scale())
	W.advance(5)
	check("scale drag: and no more", W.scaleWrites() == writes + 1 and W.setScaleCalls == 0)
	W.change("general.scale", 70)
	W.advance(0.1)
	W.change("general.scale", 90)
	W.advance(0.3)
	check("scale drag: two changes 0.1 seconds apart give the second value only", near(W.scale(), 0.9) and W.scaleWrites() == writes + 2, W.scaleWrites())
	W.change("general.scaleOn", false)
	W.advance(0.1)
	W.change("general.scaleOn", true)
	W.advance(0.3)
	check("scale drag: off and on again inside the wait leaves the chosen scale", near(W.scale(), 0.9) and W.scaleWrites() == writes + 2, W.scaleWrites() .. " " .. W.scale())
	clean(W, "scale drag")
end

-- 14b. A login writes nothing. The game applies its own variables at every login.
do
	local W = newWorld({ cvars = { useUiScale = "1", uiscale = "0.7200" }, uiScale = 0.72, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	check("scale at login: not before login", W.scale() == 0.72 and W.scaleWrites() == 0)
	W.login()
	check("scale at login: the variables already hold it, so nothing is written and UIParent is not set", W.scaleWrites() == 0 and W.setScaleCalls == 0 and near(W.scale(), 0.72))
	check("scale at login: and the status says so", has(W.status(), "Custom UI scale: 72%.") and not has(W.status(), "asked"), W.status())
	W.change("general.scaleOn", false)
	W.advance(0.3)
	check("scale at login: turned off, the variables the addon never wrote are left alone", W.scaleWrites() == 0 and W.cvars.uiscale == "0.7200")
	local D = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	D.login()
	D.fire("DISPLAY_SIZE_CHANGED")
	D.fire("PLAYER_ENTERING_WORLD", false, false)
	D.advance(1)
	check("scale at login: variables that hold another scale are not written at login or at a screen change", D.scaleWrites() == 0 and D.setScaleCalls == 0 and D.scale() == 0.64 and has(D.status(), "Custom UI scale: 72% asked, the game has 64%."), D.status())
	-- A login in combat, and options changed in combat, wait for combat to end.
	local C = newWorld({ combat = true, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	C.login()
	check("scale in combat: a login in combat writes nothing", C.scale() == 0.64 and C.scaleWrites() == 0 and C.setScaleCalls == 0 and #C.violations == 0, table.concat(C.violations, "|"))
	C.change("general.scale", 75)
	C.advance(0.3)
	check("scale in combat: a new value waits, and the status says so", C.scaleWrites() == 0 and C.scale() == 0.64 and #C.violations == 0 and has(C.status(), "Waiting for combat to end."), C.status())
	C.change("general.scale", 78)
	C.advance(0.3)
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	check("scale in combat: the last value is written once after combat", C.scaleWrites() == 2 and near(C.scale(), 0.78) and ringed(C, C.cast.TargetFrameSpellBar.bar, PX / 0.78), C.scaleWrites() .. " " .. C.scale())
	C.fire("PLAYER_REGEN_ENABLED")
	check("scale in combat: and not again", C.scaleWrites() == 2)
	C.combat = true
	C.change("general.scaleOn", false)
	C.advance(0.3)
	check("scale in combat: turning it off waits", near(C.scale(), 0.78) and C.cvars.useUiScale == "1" and #C.violations == 0)
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	check("scale in combat: and the game's values are written back after combat", C.cvars.useUiScale == "0" and C.cvars.uiscale == "0.64", C.cvars.uiscale)
	clean(C, "scale in combat")
end

-- 14c. A client that fails is no problem, and a write the game does not keep is said once.
do
	for _, fault in ipairs({ "error", "secret", "zero", "string" }) do
		local F = newWorld()
		F.login()
		F.scaleFault = fault
		F.change("general.scaleOn", true)
		F.advance(0.3)
		F.fire("UI_SCALE_CHANGED")
		check("scale fault: GetScale " .. fault .. " is no error and UIParent is not set", F.setScaleCalls == 0 and #F.out == 0 and #F.errors == 0 and #F.violations == 0, F.setScaleCalls)
		F.scaleFault = nil
		F.advance(1)
		check("scale fault: " .. fault .. " gone, the variable holds the scale", F.cvars.uiscale == "0.65" and near(F.scale(), 0.65) and F.setScaleCalls == 0, F.cvars.uiscale)
	end
	local E = newWorld({ saved = { options = { ["general.scale"] = 65 } } })
	E.login()
	E.setScaleFault = true
	E.change("general.scaleOn", true)
	E.change("general.scaleBelow", true)
	E.advance(0.3)
	check("scale fault: a SetScale that raises is no error", #E.out == 0 and #E.errors == 0 and E.scale() == 0.64 and #E.violations == 0)
	E.setScaleFault = nil
	E.fire("UI_SCALE_CHANGED")
	E.advance(0.3)
	check("scale fault: and is tried again at the next event", near(E.scale(), 0.6))
	-- Events this client does not have.
	local M = newWorld({ unknownEvents = { UI_SCALE_CHANGED = true, DISPLAY_SIZE_CHANGED = true, PLAYER_ENTERING_WORLD = true }, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	M.login()
	M.change("general.scale", 80)
	M.advance(0.3)
	check("scale: a client without the scale events writes from the options and checks after the wait", near(M.scale(), 0.8) and #M.errors == 0 and #M.out == 0 and has(M.status(), "Custom UI scale: 80%."), M.status())
end

-- 15. Thickness, and a change of screen size.
do
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	local icon = W.buttons.ActionButton1.parts.icon
	local bar = W.cast.TargetFrameSpellBar.bar
	W.change("general.thickness", 3)
	check("thickness: holders", ringOf(W, plate.healthBar, 3) and ringOf(W, icon, 3))
	check("thickness: edges drawn on the bar itself", ringed(W, bar, 3 * PX / 0.64))
	W.height = 2160
	W.fire("DISPLAY_SIZE_CHANGED")
	local resized = W.holderOn(plate.healthBar)
	check("screen size: one unit of a holder is still one pixel", resized and near(resized.scale, 768 / 2160) and ringed(W, resized, 3))
	check("screen size: edges on the bar itself follow", ringed(W, bar, 3 * 768 / 2160 / 0.64))
	W.gameScale(1)
	check("ui scale: edges on the bar itself follow", ringed(W, bar, 3 * 768 / 2160))
	W.gameScale(0.8)
	W.height = 1440
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	check("edit mode: edges follow", ringed(W, bar, 3 * 768 / 1440 / 0.8) and near(W.holderOn(icon).scale, 768 / 1440))
	W.height = 0
	W.fire("DISPLAY_SIZE_CHANGED")
	check("screen size: an unusable height keeps the last good one", near(W.holderOn(icon).scale, 768 / 1440))
	W.heightFault = "secret"
	W.fire("DISPLAY_SIZE_CHANGED")
	check("screen size: a secret height keeps the last good one", near(W.holderOn(icon).scale, 768 / 1440) and #W.violations == 0)
	W.heightFault = nil
	W.height = 1080
	W.fire("UI_SCALE_CHANGED")
	check("screen size: and back", near(W.holderOn(icon).scale, PX) and ringed(W, bar, 3 * PX / 0.8))
	clean(W, "thickness")
	-- A client where frames cannot ignore their parent's scale: edges are sized from the frame's scale.
	local N = newWorld({ noIgnoreScale = true })
	N.login()
	local holder = N.holderOn(N.cast.PlayerCastingBarFrame.bar)
	check("no ignore scale: edges are one pixel in the holder's units", holder and holder.ignoreParentScale == nil and ringed(N, holder, PX / 0.64))
	check("no ignore scale: no errors", #N.out == 0 and #N.violations == 0, table.concat(N.out, " | "))
	N.height = 2160
	N.fire("DISPLAY_SIZE_CHANGED")
	check("no ignore scale: and a new height", ringed(N, holder, 768 / 2160 / 0.64) and holder.scale == 1)
	-- Before any usable screen height, one unit is one unit.
	local U = newWorld()
	U.heightFault = "secret"
	U.login()
	check("screen size: a secret height from the start uses 1", ringed(U, U.holderOn(U.cast.PlayerCastingBarFrame.bar), 1) and near(U.holderOn(U.cast.PlayerCastingBarFrame.bar).scale, 1) and #U.violations == 0)
end

-- 15b. Resizing waits for combat to end, once, like every other layout.
do
	local W = newWorld()
	W.login()
	local icon = W.buttons.ActionButton1.parts.icon
	local top = W.look(icon).top
	local before = top.calls.SetHeight
	W.combat = true
	W.change("general.thickness", 2)
	W.height = 2160
	W.fire("DISPLAY_SIZE_CHANGED")
	W.fire("UI_SCALE_CHANGED")
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	check("combat resize: nothing moves in combat", ringOf(W, icon, 1) and near(W.holderOn(icon).scale, PX) and W.ns.Get("general.thickness") == 2 and #W.violations == 0, table.concat(W.violations, "|"))
	check("combat resize: colours are applied at once", (function() W.change("general.border", "ff336699") return ringOf(W, icon, 1, 0.2, 0.4, 0.6) end)())
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat resize: applied when combat ends", ringOf(W, icon, 2, 0.2, 0.4, 0.6) and near(W.holderOn(icon).scale, 768 / 2160))
	check("combat resize: one resize for all of it", top.calls.SetHeight == before + 1, tostring(top.calls.SetHeight) .. " vs " .. tostring(before))
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat resize: and not again", top.calls.SetHeight == before + 1)
	W.fire("UI_SCALE_CHANGED")
	W.fire("UI_SCALE_CHANGED")
	check("resize: out of combat each event resizes at once", top.calls.SetHeight == before + 3, top.calls.SetHeight)
	clean(W, "combat resize")
end

-- 16. A login in combat: the bar art fades at once; buttons keep Blizzard's art until they can be laid out.
do
	local W = newWorld({ combat = true })
	W.login()
	local parts = W.buttons.ActionButton1.parts
	check("combat: bar art fades at once, buttons keep Blizzard's art until their outline exists", parts.NormalTexture.alpha == 1 and parts.SlotArt.alpha == 1 and parts.SlotBackground.alpha == 1
		and W.bar.BorderArt.alpha == 0 and W.bar.EndCaps.LeftEndCap.Texture.alpha == 0)
	check("combat: nothing laid out on protected buttons", parts.icon.texCoord == nil and parts.cooldown.allPoints == nil and W.holderOn(parts.icon) == nil and parts.PushedTexture.color == nil
		and parts.Border.color == nil and parts.icon.masks[parts.IconMask] == true)
	check("combat: no violations, nothing styled yet", #W.violations == 0 and #W.errors == 0 and #W.out == 0 and has(W.status(), "Action bars: on, 0 styled"), table.concat(W.violations, "|") .. W.status())
	check("combat: the other modules are styled", W.state(W.prd.health[1]) == "SB" and W.state(W.cast.PlayerCastingBarFrame.bar) == "SB" and has(W.status(), "Cast bars: on, 5 styled"))
	-- Blizzard's art update in combat is followed without touching layout.
	W.update("ActionButton1")
	W.update("ActionButton1")
	W.update("ActionButton2")
	parts.NormalTexture:SetAlpha(1)
	W.update("ActionButton1")
	check("combat: an art update in combat changes nothing and lays nothing out", parts.NormalTexture.alpha == 1 and parts.icon.texCoord == nil and #W.violations == 0 and #W.out == 0)
	W.change("actionbars.crop", 12)
	W.change("actionbars.backdrop", false)
	W.change("actionbars.pet", false)
	check("combat: options changed in combat wait, and a group switched off still has Blizzard's art", parts.icon.texCoord == nil and W.buttons.PetActionButton1.parts.NormalTexture.alpha == 1
		and W.buttons.PetActionButton1.parts.SlotArt.alpha == 1 and parts.NormalTexture.alpha == 1 and #W.violations == 0)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat: laid out when combat ends, with the options chosen meanwhile", texcoord(parts.icon) == "0.12,0.88,0.12,0.88" and parts.cooldown.allPoints == parts.icon and W.state(parts.icon) == "Sb",
		buttonLine(W, "ActionButton1"))
	check("combat: all the buttons of the groups that are on are laid out", has(W.status(), "Action bars: on, 108 styled"), W.status())
	check("combat: a group switched off in combat before its buttons were laid out gets Blizzard's art back", buttonLine(W, "PetActionButton1") == "art=1,1,1 tc=- ring=." and buttonLine(W, "PetActionButton10") == "art=1,1,1 tc=- ring=.",
		buttonLine(W, "PetActionButton1"))
	local sets = parts.icon.calls.SetTexCoord
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat: the queue ran once", parts.icon.calls.SetTexCoord == sets and #W.violations == 0 and #W.errors == 0)
	-- A queue entry that fails does not stop the others.
	W.combat = true
	local ran = {}
	W.ns.OutOfCombat(function() ran[#ran + 1] = 1 end)
	W.ns.OutOfCombat(function() error("queued failure", 0) end)
	W.ns.OutOfCombat(function() ran[#ran + 1] = 3 end)
	check("combat: OutOfCombat holds the work in combat", #ran == 0)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat: in order, a failure reaches the error handler and the rest still runs", table.concat(ran, ",") == "1,3" and #W.errors == 1 and has(W.errors[1], "queued failure"), table.concat(W.errors, "|"))
	W.ns.OutOfCombat(function() ran[#ran + 1] = 4 end)
	check("combat: out of combat OutOfCombat runs the work at once", ran[3] == 4)
	W.errors = {}
	clean(W, "combat")
	-- Turned on from the options in combat.
	local C = newWorld({ saved = { options = { ["actionbars.enabled"] = false } } })
	C.login()
	C.combat = true
	C.change("actionbars.enabled", true)
	check("combat: the module turned on in combat keeps Blizzard's art and lays nothing out", C.buttons.ActionButton1.parts.NormalTexture.alpha == 1 and C.buttons.ActionButton1.parts.icon.texCoord == nil and #C.violations == 0
		and C.hooks == 0)
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	check("combat: and styles after combat", buttonLine(C, "ActionButton1") == BUTTON_ON and #C.violations == 0)
	-- Nameplates, resource display, swing timers and cast bars are not protected.
	local P = newWorld({ combat = true })
	P.login()
	local plate = P.newPlate()
	P.showPlate("nameplate1", plate)
	P.tick()
	check("combat: unprotected frames are styled in combat", plateLine(P, plate) == ON and #P.violations == 0)
end

-- 17. The module runner, as other code of the addon uses it.
do
	local W = newWorld()
	local ns = W.ns
	check("enabled: not before login", ns.Enabled("nameplates") == false and ns.IsStopped("nameplates") == false)
	W.login()
	check("enabled: after login", ns.Enabled("nameplates") and ns.Enabled("actionbars") and ns.Enabled("resource") and ns.Enabled("swing") and ns.Enabled("castbars"))
	W.change("castbars.enabled", false)
	check("enabled: false when the switch is off", ns.Enabled("castbars") == false and not ns.IsStopped("castbars"))
	W.change("castbars.enabled", true)
	local got
	check("Try: runs the function with its arguments", ns.Try("resource", function(a, b) got = a + b end, 1, 2) == true and got == 3 and #W.out == 0)
	check("Try: an error stops the module at once, said once", ns.Try("resource", function() error("boom", 0) end) == false and #W.out == 1
		and W.out[1] == "Flat UI: Personal resource display stopped. /flatui status shows why. Type /reload if the look is left half changed." and has(W.status(), "Personal resource display: stopped. boom"), table.concat(W.out, "|"))
	ns.Try("resource", function() error("again", 0) end)
	check("Try: the first error is kept, nothing more is said", #W.out == 1 and has(W.status(), "stopped. boom") and not has(W.status(), "again"))
	local n = 0
	check("Each: runs the function for one frame with its arguments", ns.Each("castbars", function(a) n = n + a end, 5) == true and n == 5)
	for i = 1, 4 do
		ns.Each("castbars", function() error("bad " .. i, 0) end)
	end
	check("Each: four failures are counted and the first error is kept, the module runs on", has(W.status(), "Cast bars: on, 5 styled, 4 failed. bad 1") and #W.out == 1 and not ns.IsStopped("castbars"), W.status())
	check("Each: a failure returns false, and the fifth stops the module", ns.Each("castbars", function() error("bad 5", 0) end) == false and ns.IsStopped("castbars") and #W.out == 2
		and W.out[2] == "Flat UI: Cast bars stopped. /flatui status shows why. Type /reload if the look is left half changed." and has(W.status(), "Cast bars: stopped. bad 1"), W.status())
	check("Each: nothing runs in a stopped module", ns.Each("castbars", function() n = 100 end) == false and n == 5)
	ns.Count("nameplates", 3)
	check("Count: by the number given", has(W.status(), "Nameplates: on, 3 styled"))
	ns.Count("nameplates")
	check("Count: by one", has(W.status(), "Nameplates: on, 4 styled"))
	ns.Note("nameplates", "First note")
	ns.Note("nameplates", "First note")
	ns.Note("nameplates", "Second note")
	check("Note: a line each under its module, the same one once", has(W.status(), "Nameplates: on, 4 styled\nFirst note\nSecond note\nCombat text: on\nNumbers in front of nameplates: waiting for the first hit. The game's numbers show until then.\nWhose hits: one for each of your casts, swings, shots and auras. Left out as not yours: 0.\nOutgoing scroll area: 0 shown.\nNumbers over friendly units: waiting for the first hit. The game's healing numbers show until then.\nShields over friendly units show in the game's own numbers.\nCombat text for you: 0 shown.\nAction bars: on"), W.status())
	ns.Note("castbars", "A note on a stopped module")
	check("Note: under a stopped module too", has(W.status(), "Cast bars: stopped. bad 1\nA note on a stopped module"), W.status())
	check("status: the lines of the modules in their order", (function()
		local order, wanted = {}, {}
		for _, line in ipairs(ns.StatusLines()) do
			local label = line:match("^([%a ]+):")
			if label and label ~= "Profile" and label ~= "Border thickness" then order[#order + 1] = label end
		end
		for _, module in ipairs(TOC.modules(W)) do wanted[#wanted + 1] = module.label end
		return TOC.inOrder(order, wanted)
	end)())
	-- Forbidden and secret.
	local plain = {}
	local normal = W.B(nil, {})
	local forbidden = W.B(nil, {}, { forbidden = true })
	local odd = setmetatable({}, { __index = function() return function() return SECRET end end })
	local nilish = { IsForbidden = function() return nil end }
	local okay = { IsForbidden = function() return false end }
	local raising = setmetatable({}, { __index = function() error("no access", 0) end })
	check("Forbidden: nil, a secret value, a number, a string, a table with no method", ns.Forbidden(nil) and ns.Forbidden(SECRET) and ns.Forbidden(5) and ns.Forbidden("x") and ns.Forbidden(plain))
	check("Forbidden: a frame that says so, one that answers with a secret, nothing, or an error", ns.Forbidden(forbidden) and ns.Forbidden(odd) and ns.Forbidden(nilish) and ns.Forbidden(raising))
	check("Forbidden: a frame that is not forbidden", ns.Forbidden(normal) == false and ns.Forbidden(okay) == false)
	check("IsSecret: only the secret value", ns.IsSecret(SECRET) == true and ns.IsSecret(1) == false and ns.IsSecret("x") == false and ns.IsSecret(nil) == false and ns.IsSecret({}) == false)
	-- Fading and hiding.
	local region = W.R(nil, "x")
	ns.SetFaded(region, true)
	local a1 = region.alpha
	ns.SetFaded(region, false)
	local a2 = region.alpha
	ns.SetFaded(region, true)
	ns.SetFaded(region, nil)
	check("SetFaded: 0 to hide, 1 to show, nothing is 1", a1 == 0 and a2 == 1 and region.alpha == 1)
	local rraw
	local odd2
	odd2, rraw = W.Rr(nil, "y")
	rraw.SetAlpha = function() error("no", 0) end
	rraw.SetShown = function() error("no", 0) end
	ns.SetFaded(nil, true)
	ns.SetFaded(SECRET, true)
	ns.SetFaded(odd2, true)
	ns.SetHidden(nil, true)
	ns.SetHidden(SECRET, true)
	ns.SetHidden(odd2, true)
	check("SetFaded and SetHidden: nothing, a secret value and a region that raises are no error", #W.violations == 0 and #W.errors == 0)
	ns.SetHidden(region, true)
	local s1 = region.shown
	ns.SetHidden(region, false)
	check("SetHidden: hides and shows", s1 == false and region.shown == true)
	-- Finding art by atlas.
	local atlasFrame, atlasInner = W.B(nil, {})
	atlasInner.regions = { W.R(nil, nil), W.Rr(nil, "Broken", { atlasErrors = true }), W.Rr(nil, "Secret", { atlasSecret = true }), W.R(nil, "UI-Thing-Name"), W.R(nil, "ui-thing-name") }
	check("RegionWithAtlas: the first region with that atlas, in any case", ns.RegionWithAtlas(atlasFrame, "ui-thing-name") == atlasInner.regions[4] and ns.RegionWithAtlas(atlasFrame, "UI-THING-NAME") == atlasInner.regions[4])
	check("RegionWithAtlas: none for an atlas nobody has, a region that raises or answers with a secret", ns.RegionWithAtlas(atlasFrame, "missing") == nil and ns.RegionWithAtlas(atlasFrame, "broken") == nil
		and ns.RegionWithAtlas(atlasFrame, "secret") == nil and #W.violations == 0)
	check("RegionWithAtlas: none on a forbidden frame, nil, or something with no regions", ns.RegionWithAtlas(forbidden, "x") == nil and ns.RegionWithAtlas(nil, "x") == nil and ns.RegionWithAtlas(plain, "x") == nil
		and ns.RegionWithAtlas(SECRET, "x") == nil and #W.violations == 0)
	-- Outlines.
	local frame = W.B(nil, {})
	local frames, textures = #W.addonFrames, #W.addonTextures
	local o = ns.Outline(frame, frame)
	check("Outline: made once for a target, with a holder, four edges and a backdrop", o ~= nil and ns.Outline(frame, frame) == o and #W.addonFrames == frames + 1 and #W.addonTextures == textures + 5 and W.state(frame) == "SB")
	check("Outline: none for a forbidden owner", ns.Outline(forbidden, forbidden) == nil and ns.Outline(forbidden, frame) == o)
	ns.SetOutline(o, true, false)
	local st1 = W.state(frame)
	ns.SetOutline(o, false, true)
	local st2 = W.state(frame)
	ns.SetOutline(o, true, nil)
	local st3 = W.state(frame)
	ns.SetOutline(o, nil, nil)
	local st4 = W.state(frame)
	ns.SetOutline(o, true, true)
	check("SetOutline: edges and backdrop separately, anything else is false", st1 == "Sb" and st2 == "hb" and st3 == "Sb" and st4 == "hb" and W.state(frame) == "SB", st1 .. st2 .. st3 .. st4)
	ns.SetOutline(nil, true, true)
	ns.SetOutlineColour(nil, 1, 1, 1)
	ns.SetOutlineThickness(nil, 2)
	ns.SetOutlineColour(o, 0.1, 0.2, 0.3)
	local c1 = ringOf(W, frame, 1, 0.1, 0.2, 0.3)
	ns.SetOutlineColour(o, nil, nil, nil)
	local c2 = ringOf(W, frame, 1, 0, 0, 0)
	ns.SetOutlineThickness(o, 3)
	local t1 = ringOf(W, frame, 3)
	W.change("general.thickness", 2)
	local t2 = ringOf(W, frame, 3)
	ns.SetOutlineThickness(o, nil)
	local t3 = ringOf(W, frame, 2)
	check("SetOutlineColour and SetOutlineThickness: one outline's own, or the general ones when none", c1 and c2 and t1 and t2 and t3 and #W.violations == 0, tostring(c1) .. tostring(c2) .. tostring(t1) .. tostring(t2) .. tostring(t3))
	W.change("general.thickness", 1)
	W.change("general.backdrop", "ff804020")
	W.change("general.backdropAlpha", 50)
	local back = W.backdropOn(frame)
	check("Paint: the backdrop takes the general colour and opacity", near(back.color[1], 0x80 / 255) and near(back.color[2], 0x40 / 255) and near(back.color[3], 0x20 / 255) and near(back.color[4], 0.5))
end

-- 18. Calls the game refused are listed, since they raise no Lua error.
do
	local W = newWorld()
	W.login()
	W.fire("ADDON_ACTION_BLOCKED", "SomeOtherAddon", "Frame:SetPoint()")
	W.fire("ADDON_ACTION_FORBIDDEN", "SomeOtherAddon", "Frame:Hide()")
	check("blocked: other addons ignored", not has(W.status(), "Blocked by the game"))
	W.fire("ADDON_ACTION_BLOCKED", "FlatUI", "Frame:SetPoint()")
	W.fire("ADDON_ACTION_FORBIDDEN", "FlatUI", "Texture:SetAllPoints()")
	check("blocked: listed in the status, blocked and forbidden alike", has(W.status(), "\nBlocked by the game: Frame:SetPoint() (blocked), Texture:SetAllPoints() (forbidden)"), W.status())
	check("blocked: after the module lines", W.status():match("Blocked by the game[^\n]*$") ~= nil)
	for _ = 1, 10 do
		W.fire("ADDON_ACTION_BLOCKED", "FlatUI", "x")
	end
	local _, n = W.status():gsub(", x", "")
	check("blocked: the list is short", n == 3, n)
	check("blocked: shown by the slash command", has(W.slash("status"), "Blocked by the game: Frame:SetPoint()"))
	W.out = {}
	clean(W, "blocked")
end

-- 19. Clients without part of the Settings API, and with missing events.
do
	local W = newWorld({ noSettings = true, unknownEvents = { EDIT_MODE_LAYOUTS_UPDATED = true, PLAYER_FOCUS_CHANGED = true } })
	W.login()
	check("old client: starts without the missing events and options", #W.errors == 0 and #W.out == 0 and #W.violations == 0 and has(W.status(), "Nameplates: on, 0 styled"), table.concat(W.errors, " | "))
	local out = W.slash("options")
	check("old client: /flatui options prints the status when there are no options", has(out, TOC.head(1)) and has(out, "Cast bars: on, 5 styled"), out)
	check("old client: and the status command prints it too", has(W.slash("status"), "Cast bars: on, 5 styled"))
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	check("old client: the rest of the addon works", plate.healthBar.bgTexture.alpha == 0)
	local V = newWorld({ without = { Settings = true } })
	V.login()
	check("no Settings table at all: no error, status instead of options", #V.errors == 0 and has(V.slash("options"), TOC.head(1)) and #V.violations == 0)
	local V2 = newWorld()
	V2.env.Settings.RegisterVerticalLayoutCategory = nil
	V2.login()
	check("no way to register a category: no error, status instead of options", #V2.errors == 0 and #V2.controls == 0 and has(V2.slash("options"), TOC.head(1)))
	local N = newWorld({ unknownEvents = { NAME_PLATE_UNIT_ADDED = true, PLAYER_TARGET_CHANGED = true, PLAYER_FOCUS_CHANGED = true, UNIT_AURA = true,
		UI_SCALE_CHANGED = true, DISPLAY_SIZE_CHANGED = true, PLAYER_ENTERING_WORLD = true, EDIT_MODE_LAYOUTS_UPDATED = true, ADDON_ACTION_BLOCKED = true,
		ADDON_ACTION_FORBIDDEN = true } })
	local plate2 = N.newPlate()
	N.login()
	check("missing events: the addon still starts, styles what is on screen, and raises nothing", #N.errors == 0 and #N.out == 0 and #N.violations == 0 and plate2.healthBar.bgTexture.alpha == 0
		and has(N.status(), "Action bars: on, 118 styled"), table.concat(N.errors, "|"))
	N.change("nameplates.dim", true)
	check("missing events: and the options work", plate2.healthBar.deselectedOverlay.alpha == 1)
end

do
	-- No subcategories: the first page is built and nothing else.
	local W = newWorld({ without = { ["Settings.RegisterVerticalLayoutSubcategory"] = true } })
	W.login()
	check("no subcategories: only the first page, no error", #W.categories == 1 and #W.controls == COUNT.general and #W.errors == 0 and W.registered == W.categories[1], #W.controls)
	check("no subcategories: its options work", (function() W.change("general.thickness", 2) return W.ns.Get("general.thickness") == 2 end)())
	check("no subcategories: /flatui options opens it", W.slash("options") == "" and W.opened == W.registered.id)
	local R2 = newWorld()
	R2.env.Settings.RegisterVerticalLayoutSubcategory = function() error("not now", 0) end
	R2.login()
	check("subcategories that raise: skipped without a word", #R2.categories == 1 and #R2.controls == COUNT.general and #R2.errors == 0 and R2.registered == R2.categories[1])
	local R3 = newWorld()
	R3.env.Settings.RegisterVerticalLayoutSubcategory = function() return nil end
	R3.login()
	check("subcategories that return nothing: skipped without a word", #R3.controls == COUNT.general and #R3.errors == 0)
	-- No colour swatches: the page goes on without them.
	local C = newWorld({ without = { ["Settings.CreateColorSwatch"] = true } })
	C.login()
	check("no colour swatch: one error for each colour, every other control is built", #C.errors == COUNT.colour and #C.controls == COUNT.controls - COUNT.colour and C.registered ~= nil, #C.errors .. " " .. #C.controls)
	check("no colour swatch: the order of the page is kept and dependencies still work", C.control("general.backdropAlpha") ~= nil and C.control("general.border") == nil and C.control("nameplates.focusColour") == nil
		and C.control("nameplates.targetThickness") ~= nil and #C.control("nameplates.targetThickness").predicates == 3)
	-- No slider formatter.
	local M = newWorld({ without = { MinimalSliderWithSteppersMixin = true } })
	M.login()
	check("no slider label mixin: one error for each slider, every other control is built", #M.errors == COUNT.number and #M.controls == COUNT.controls - COUNT.number, #M.errors .. " " .. #M.controls)
	-- No dropdown.
	local D = newWorld({ without = { ["Settings.CreateDropdown"] = true } })
	D.login()
	check("no dropdown: one error for each choice and each list", #D.errors == COUNT.choice + COUNT.list and #D.controls == COUNT.controls - COUNT.choice - COUNT.list, #D.errors .. " " .. #D.controls)
	local T = newWorld({ without = { ["Settings.CreateControlTextContainer"] = true } })
	T.login()
	check("no text container: the same", #T.errors == COUNT.choice + COUNT.list and #T.controls == COUNT.controls - COUNT.choice - COUNT.list, #T.errors .. " " .. #T.controls)
	-- No section headers.
	local H = newWorld({ without = { CreateSettingsListSectionHeaderInitializer = true } })
	H.login()
	check("no section header initializer: no headers, no error", #H.controls == COUNT.settings and #H.errors == 0)
	local H2 = newWorld({ without = { ["Settings.RegisterInitializer"] = true } })
	H2.login()
	check("no way to register an initializer: no headers, no error", #H2.controls == COUNT.settings and #H2.errors == 0)
	-- No predicates.
	local P = newWorld({ noPredicates = true })
	P.login()
	check("initializers without AddModifyPredicate: everything is built, no error", #P.controls == COUNT.controls and #P.errors == 0)
	local R = newWorld({ noReturn = true })
	R.login()
	check("controls that return nothing: everything is built, no error", #R.controls == COUNT.controls and #R.errors == 0)
	-- No SettingsPanel.
	local S2 = newWorld({ without = { SettingsPanel = true } })
	S2.login()
	check("no SettingsPanel: the status is printed", has(S2.slash("options"), TOC.head(1)))
	-- A setting that cannot be built.
	local B2 = newWorld()
	local original = B2.env.Settings.RegisterProxySetting
	B2.env.Settings.RegisterProxySetting = function(category, variable, ...)
		if variable == "FLATUI_NAMEPLATES_DIM" then
			error("cannot register", 0)
		end
		return original(category, variable, ...)
	end
	B2.login()
	check("one control that cannot be built does not cost the rest of the page", #B2.errors == 1 and B2.errors[1] == "cannot register" and #B2.controls == COUNT.controls - 1 and B2.control("nameplates.target") ~= nil
		and B2.control("nameplates.auras") ~= nil, #B2.errors .. " " .. #B2.controls)
	check("one control that cannot be built: the options are registered all the same", B2.registered ~= nil and B2.slash("options") == "")
end

-- 21. Before the game has logged in nothing is started, and the scale is the game's own.
do
	local W = newWorld()
	local plate = W.newPlate()
	W.fire("ADDON_LOADED", "FlatUI")
	W.showPlate("nameplate1", plate)
	W.tick()
	W.change("castbars.focus", false)
	W.change("actionbars.crop", 12)
	W.change("general.scaleOn", true)
	W.change("general.thickness", 2)
	W.change("resource.health", false)
	W.tick()
	check("before login: nothing is styled or started, UIParent is left alone", plate.healthBar.bgTexture.alpha == 1 and W.cast.PlayerCastingBarFrame.parts.Border.alpha == 1
		and W.buttons.ActionButton1.parts.NormalTexture.alpha == 1 and W.prd.power[2].regions[1].alpha == 1 and W.hooks == 0 and W.setScaleCalls == 0 and near(W.scale(), 0.64)
		and #W.addonFrames == 0 and #W.violations == 0, W.setScaleCalls .. " " .. #W.addonFrames)
	check("before login: the status says not started", has(W.status(), TOC.head(2) .. "\nNameplates: on, not started") and has(W.status(), "Cast bars: on, not started"), W.status())
	W.fire("PLAYER_LOGIN")
	W.fire("PLAYER_ENTERING_WORLD", true, false)
	W.tick()
	check("login after changes made before it: styled with them", ringOf(W, plate.healthBar, 2) and plate.healthBar.bgTexture.alpha == 0 and W.cast.FocusFrameSpellBar.parts.Border.alpha == 1
		and W.cast.TargetFrameSpellBar.parts.Border.alpha == 0 and texcoord(W.buttons.ActionButton1.parts.icon) == "0.12,0.88,0.12,0.88" and W.prd.health[2].regions[1].alpha == 1
		and W.prd.power[2].regions[1].alpha == 0 and near(W.scale(), 0.64) and W.setScaleCalls == 0 and W.scaleWrites() == 0, W.setScaleCalls)
	W.change("general.scaleOn", false)
	W.advance(0.3)
	check("login after changes made before it: the game's scale stays", near(W.scale(), 0.64) and W.scaleWrites() == 0, W.scale())
	clean(W, "before login")
end

-- 22. The game's own values are what turning the scale off writes back, whatever scale the game has meanwhile.
do
	local W = newWorld({ cvars = { useUiScale = "1", uiscale = "0.9000" }, uiScale = 0.9, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 65 } } })
	W.login()
	check("scale: a custom scale that differs from the game's at login writes nothing", W.scaleWrites() == 0 and near(W.scale(), 0.9))
	W.change("general.scale", 80)
	W.advance(0.3)
	check("scale: and is written when the slider moves, the game's values kept", near(W.scale(), 0.8) and W.scaleWrites() == 1 and W.env.FlatUIDB.scaleGame.use == "1" and W.env.FlatUIDB.scaleGame.scale == "0.9000")
	W.change("general.scaleOn", false)
	W.advance(0.3)
	check("scale: off gives back the game's 90 percent", W.cvars.useUiScale == "1" and W.cvars.uiscale == "0.9000" and near(W.scale(), 0.9), W.cvars.uiscale)
	local V = newWorld()
	V.login()
	V.change("general.scale", 70)
	V.change("general.scaleOn", true)
	V.advance(0.3)
	V.gameScale(0.9)
	V.change("general.scale", 90)
	V.advance(0.3)
	V.change("general.scaleOn", false)
	V.advance(0.3)
	check("scale: off gives back what the game held before the first write, not a scale it showed since", V.cvars.useUiScale == "0" and V.cvars.uiscale == "0.64" and V.setScaleCalls == 0, V.cvars.uiscale)
end

-- 23. Odd values.
do
	local W = newWorld()
	W.login()
	local bar = W.cast.TargetFrameSpellBar.bar
	W.cast.TargetFrameSpellBar.inner.scale = 0
	W.fire("UI_SCALE_CHANGED")
	check("edges: a frame whose scale is 0 is sized as if it were 1", ringed(W, bar, PX) and #W.violations == 0, table.concat(W.violations, "|"))
	W.cast.TargetFrameSpellBar.inner.scale = 1
	W.fire("UI_SCALE_CHANGED")
	check("edges: and back", ringed(W, bar, PX / 0.64))
	-- A list of plates with things in it that are not plates.
	local V = newWorld()
	local plate = V.newPlate()
	V.platesFault = "garbage"
	V.login()
	V.change("nameplates.dim", true)
	V.platesFault = nil
	check("plate list: numbers, strings, booleans and secrets in the list are skipped", plate.healthBar.bgTexture.alpha == 0 and #V.out == 0 and #V.violations == 0 and not has(V.status(), "stopped") and not has(V.status(), "failed"),
		V.line("Nameplates"))
	-- Registering the options a second time does nothing.
	local R = newWorld()
	R.login()
	local before = #R.controls
	local ok = pcall(R.ns.RegisterOptions)
	check("options: registered once, not again", ok and #R.controls == before and #R.categories == #PAGE_LABELS + 1 and #R.violations == 0, #R.controls)
	-- The art of a bar is looked up once, not on every refresh.
	local A = newWorld()
	A.login()
	A.change("resource.health", false)
	A.change("resource.health", true)
	A.change("resource.backdrop", false)
	A.change("resource.backdrop", true)
	check("resource: the art is looked up once for each bar", A.prd.health[2].calls.GetRegions == 1 and A.prd.power[2].calls.GetRegions == 1 and A.prd.alt[2].calls.GetRegions == 1,
		tostring(A.prd.health[2].calls.GetRegions))
	-- Marks leave the plates they do not concern alone.
	local M = newWorld()
	M.login()
	local a, b, c = M.newPlate(), M.newPlate(), M.newPlate()
	for i, p in ipairs({ a, b, c }) do
		M.showPlate("nameplate" .. i, p)
	end
	M.units.target, M.units.focus = b, c
	M.fire("PLAYER_TARGET_CHANGED")
	M.tick()
	local topA = M.look(a.healthBar).top
	local sizes, paints = topA.calls.SetHeight, topA.calls.SetColorTexture
	M.fire("PLAYER_TARGET_CHANGED")
	M.fire("PLAYER_FOCUS_CHANGED")
	M.tick()
	M.units.target = c
	M.units.focus = b
	M.fire("PLAYER_TARGET_CHANGED")
	M.tick()
	check("marks: a plate that is neither the target nor the focus is not resized or repainted by a change of target", topA.calls.SetHeight == sizes and topA.calls.SetColorTexture == paints,
		tostring(topA.calls.SetHeight) .. "/" .. tostring(sizes) .. " " .. tostring(topA.calls.SetColorTexture) .. "/" .. tostring(paints))
	local topB = M.look(b.healthBar).top
	check("marks: and the ones that swapped were", ringOf(M, b.healthBar, 1, 1, 0.6, 0) and ringOf(M, c.healthBar, 1, 1, 1, 1) and topB.calls.SetColorTexture ~= nil)
end

-- 24. Buttons without an icon, and a cooldown that is forbidden.
do
	local W = newWorld({ noIcon = { ActionButton4 = true }, forbidden = { ["ActionButton7.chargeCooldown"] = true } })
	W.login()
	local parts = W.buttons.ActionButton7.parts
	check("buttons: one without an icon is skipped and not counted, nothing fails", has(W.status(), "Action bars: on, 117 styled") and not has(W.status(), "failed") and #W.out == 0 and #W.violations == 0, W.line("Action bars"))
	check("buttons: a forbidden cooldown is left, the others of the button are anchored", parts.cooldown.allPoints == parts.icon and parts.lossOfControlCooldown.allPoints == parts.icon and #W.violations == 0
		and buttonLine(W, "ActionButton7") == BUTTON_ON, table.concat(W.violations, "|"))
end

-- 25. A module stopped inside a call that then fails itself is reported once, with the first error.
do
	local W = newWorld()
	W.login()
	local ns = W.ns
	local ok = ns.Try("castbars", function()
		for _ = 1, 5 do
			ns.Each("castbars", function() error("inner", 0) end)
		end
		error("outer", 0)
	end)
	check("stop: a module stopped by its frames and then by the call around them is said once, with the first error", ok == false and #W.out == 1 and has(W.status(), "Cast bars: stopped. inner")
		and not has(W.status(), "outer"), table.concat(W.out, "|") .. W.line("Cast bars"))
end

-- 26. ns.IsSet, ns.Pixels and ns.Each.
do
	local W = newWorld()
	local ns = W.ns
	check("IsSet: nothing is set before the saved settings are loaded", ns.IsSet("general.scale") == false and ns.IsSet("general.thickness") == false and ns.IsSet("bogus") == false)
	W.login()
	check("IsSet: a setting nobody has changed is not set", ns.IsSet("general.scale") == false and ns.IsSet("nameplates.dim") == false)
	W.change("general.thickness", 2)
	check("IsSet: a setting that was changed is set", ns.IsSet("general.thickness") == true and ns.IsSet("general.scale") == false)
	W.change("general.thickness", 1)
	check("IsSet: and stays set when it goes back to the default", ns.IsSet("general.thickness") == true)
	check("IsSet: a path nothing uses is not set", ns.IsSet("bogus.path") == false)
	-- A value equal to the default is saved as the player's choice, and runs nothing since nothing changed.
	local D = newWorld()
	D.login()
	-- The action buttons are styled again on the frame after entering the world.
	D.flush()
	local dp = D.buttons.ActionButton1.parts
	local alphaCalls, paintCalls = dp.NormalTexture.calls.SetAlpha, D.look(dp.icon).top.calls.SetColorTexture
	D.ns.Set("actionbars.crop", 8)
	D.ns.Set("general.thickness", 1)
	D.ns.Set("general.border", "ff000000")
	D.ns.Set("general.scaleOn", false)
	check("Set: a value equal to the default is saved", D.ns.IsSet("actionbars.crop") and D.ns.IsSet("general.thickness") and D.ns.IsSet("general.border") and D.ns.IsSet("general.scaleOn")
		and D.options()["actionbars.crop"] == 8 and D.options()["general.scaleOn"] == false)
	check("Set: and runs no handler: nothing is refreshed, repainted or scheduled", dp.NormalTexture.calls.SetAlpha == alphaCalls and D.look(dp.icon).top.calls.SetColorTexture == paintCalls and #D.timers == 0,
		tostring(dp.NormalTexture.calls.SetAlpha) .. "/" .. tostring(alphaCalls))
	D.ns.Set("actionbars.crop", 5)
	D.ns.Set("actionbars.crop", 8)
	check("Set: a value that differs from the current one runs the handler, back to the default too", dp.NormalTexture.calls.SetAlpha > alphaCalls and texcoord(dp.icon) == "0.08,0.92,0.08,0.92")
	D.ns.Set("actionbars.crop", "no")
	D.ns.Set("bogus.path", 1)
	check("Set: a value that is not valid saves nothing", D.ns.Get("actionbars.crop") == 8 and D.options()["bogus.path"] == nil)
	local saved = newWorld({ saved = { options = { ["general.scale"] = 65, ["nameplates.dim"] = false } } })
	saved.login()
	check("IsSet: a setting saved with its default value is set", saved.ns.IsSet("general.scale") == true and saved.ns.IsSet("nameplates.dim") == true and saved.ns.IsSet("general.border") == false)

	-- ns.Pixels: a length in screen pixels, in the units of a frame.
	local frame, inner = W.B(nil, {})
	check("Pixels: 2 pixels at 1080 pixels high with UIParent at 0.64, none for none", near(ns.Pixels(frame, 2), 2 * PX / 0.64) and near(ns.Pixels(frame, 0), 0), ns.Pixels(frame, 2))
	inner.scale = 2
	check("Pixels: the scale of the frame itself counts", near(ns.Pixels(frame, 2), 2 * PX / (0.64 * 2)))
	inner.scale = 1
	W.height = 2160
	check("Pixels: and the height of the screen", near(ns.Pixels(frame, 3), 3 * 768 / 2160 / 0.64))
	W.height = 1080
	local function pixelsWith(effective)
		inner.GetEffectiveScale = type(effective) == "function" and effective or function() return effective end
		return ns.Pixels(frame, 2)
	end
	check("Pixels: a scale that is zero, negative, text or secret is taken as 1", near(pixelsWith(0), 2 * PX) and near(pixelsWith(-1), 2 * PX) and near(pixelsWith("0.64"), 2 * PX)
		and near(pixelsWith(SECRET), 2 * PX))
	check("Pixels: so is a scale that raises, and something that has no scale", near(pixelsWith(function() error("no", 0) end), 2 * PX) and near(ns.Pixels({}, 2), 2 * PX) and #W.violations == 0)
	inner.GetEffectiveScale = nil

	-- ns.Each: a frame that fails is counted once however often it is tried.
	local f1, f2, f3, f4, f5 = W.B(nil, {}), W.B(nil, {}), W.B(nil, {}), W.B(nil, {}), W.B(nil, {})
	local function fail(arg)
		return ns.Each("swing", function() error("bad", 0) end, arg)
	end
	local result = fail(f1)
	for _ = 1, 5 do
		fail(f1)
	end
	check("Each: a failure returns false, and one frame failing six times is one failure", result == false and has(W.status(), "Swing timers: on, 3 styled, 1 failed. bad") and not ns.IsStopped("swing") and #W.out == 0, W.line("Swing timers"))
	fail(f2)
	fail(f3)
	fail(f4)
	check("Each: four different frames are four failures, the first error is kept", has(W.status(), "Swing timers: on, 3 styled, 4 failed. bad") and not ns.IsStopped("swing") and #W.out == 0, W.line("Swing timers"))
	fail(f1)
	fail(f2)
	fail(f4)
	check("Each: and trying them again counts nothing more", has(W.status(), ", 4 failed. ") and not ns.IsStopped("swing") and #W.out == 0, W.line("Swing timers"))
	fail(f5)
	check("Each: the fifth different frame stops the module, said once", ns.IsStopped("swing") and #W.out == 1 and W.out[1] == "Flat UI: Swing timers stopped. /flatui status shows why. Type /reload if the look is left half changed."
		and has(W.status(), "Swing timers: stopped. bad"), table.concat(W.out, "|") .. W.line("Swing timers"))
	fail(f1)
	check("Each: nothing is said again", #W.out == 1)
	check("Each: when a module stops, Blizzard's art comes back and the outlines are hidden", #W.diff("swing") == 0 and W.state(W.swing.SwingTimerMainHandFrame.StatusBar) == "hb"
		and W.swing.SwingTimerMainHandFrame.Border.shown and W.swing.SwingTimerRangedFrame.Background.shown, table.concat(W.diff("swing"), "; "))

	-- The frame is the first argument after the function: a string or a number works as one, no argument means the function.
	local V = newWorld()
	V.login()
	local vns = V.ns
	local function failWith(arg)
		return vns.Each("castbars", function() error("bad", 0) end, arg)
	end
	failWith("a")
	failWith("a")
	failWith("a")
	failWith(7)
	failWith(7)
	check("Each: a string or a number identifies the failure as a frame does", has(V.status(), "Cast bars: on, 5 styled, 2 failed. bad") and not vns.IsStopped("castbars"), V.line("Cast bars"))
	local same = function() error("alone", 0) end
	vns.Each("castbars", same)
	vns.Each("castbars", same)
	vns.Each("castbars", same, nil)
	vns.Each("castbars", same, false)
	check("Each: with no frame given the function identifies it", has(V.status(), "Cast bars: on, 5 styled, 3 failed. bad") and not vns.IsStopped("castbars"), V.line("Cast bars"))
	local ok = vns.Each("castbars", function(a, b) return a + b end, 1, 2)
	check("Each: a function that works returns true", ok == true and not vns.IsStopped("castbars"))
	clean(V, "Each")
end

-- 27. A general setting repaints every outline and refreshes every started module. The scale touches neither.
do
	local W = newWorld({ saved = { options = { ["castbars.enabled"] = false } } })
	W.login()
	local plate = W.newPlate()
	local aura = W.addAura(plate)
	W.showPlate("nameplate1", plate)
	W.flush()
	local parts = W.buttons.ActionButton1.parts
	local bar = W.cast.PlayerCastingBarFrame.parts
	local function counters()
		return {
			buttons = parts.NormalTexture.calls.SetAlpha, plate = plate.healthBar.bgTexture.calls.SetAlpha, resource = W.prd.health[2].regions[1].calls.SetAlpha,
			swing = W.swing.SwingTimerMainHandFrame.Border.calls.SetShown, paint = W.look(parts.icon).top.calls.SetColorTexture, aura = aura.overlay.calls.SetAlpha,
			castbars = bar.Border.calls.SetAlpha,
		}
	end
	local function same(a, b, names)
		local diff = {}
		for _, name in ipairs(names) do
			if a[name] ~= b[name] then
				diff[#diff + 1] = name .. " " .. tostring(a[name]) .. "->" .. tostring(b[name])
			end
		end
		return #diff == 0, table.concat(diff, ", ")
	end
	local started = { "buttons", "plate", "resource", "swing" }
	local before = counters()
	W.change("general.thickness", 2)
	local after = counters()
	local changed = {}
	for _, name in ipairs({ "buttons", "plate", "resource", "swing", "paint" }) do
		if after[name] == before[name] then
			changed[#changed + 1] = name
		end
	end
	check("general: a change of thickness refreshes every started module and repaints the outlines", #changed == 0, "not touched: " .. table.concat(changed, ","))
	check("general: a module that was off at login and is not started is left alone", bar.Border.alpha == 1 and W.state(W.cast.PlayerCastingBarFrame.bar) == "." and has(W.status(), "Cast bars: off"), W.status())
	before = counters()
	W.change("general.border", "ff336699")
	after = counters()
	changed = {}
	for _, name in ipairs({ "buttons", "plate", "resource", "swing", "paint" }) do
		if after[name] == before[name] then
			changed[#changed + 1] = name
		end
	end
	check("general: so is a change of colour", #changed == 0, "not touched: " .. table.concat(changed, ","))
	W.flush()
	before = counters()
	W.change("general.scaleOn", true)
	W.advance(0.3)
	W.change("general.scale", 70)
	W.advance(0.3)
	W.change("general.scale", 90)
	W.advance(0.3)
	W.change("general.scaleOn", false)
	W.advance(0.3)
	after = counters()
	local ok, detail = same(before, after, { "buttons", "plate", "swing", "paint", "aura" })
	check("general: the scale is written to the game and refreshes no module and repaints nothing", ok, detail)
	check("general: but the resource display, which works out lengths in pixels, is looked at again", after.resource > before.resource, before.resource .. "->" .. after.resource)
	local R = newWorld({ saved = { options = { ["resource.enabled"] = false } } })
	R.login()
	R.change("general.thickness", 3)
	R.gameScale(0.8)
	R.change("general.scaleOn", true)
	R.advance(0.3)
	check("general: a resize does not start a module that is off, nor touch or hook the display it styles", R.state(R.prd.health[1]) == "." and R.prd.health[2].regions[1].alpha == 1 and near(R.gap("power"), 4)
		and has(R.status(), "Personal resource display: off") and R.hooks == 0, R.hooks)
	W.change("castbars.enabled", true)
	W.change("general.thickness", 1)
	check("general: a module switched on later is started and then follows the general settings", bar.Border.alpha == 0 and ringed(W, W.holderOn(W.cast.PlayerCastingBarFrame.bar), 1, 0.2, 0.4, 0.6))
	-- A stopped module is not refreshed, and does not put its art back by itself again.
	for i = 1, 5 do
		W.ns.Each("castbars", function() error("bad", 0) end, "frame" .. i)
	end
	check("general: stopped", W.ns.IsStopped("castbars") and bar.Border.alpha == 1 and W.state(W.cast.PlayerCastingBarFrame.bar) == "hb")
	local calls = bar.Border.calls.SetAlpha
	W.change("general.thickness", 3)
	W.change("castbars.player", false)
	W.change("castbars.player", true)
	check("general: a stopped module stays as it was", bar.Border.calls.SetAlpha == calls and bar.Border.alpha == 1 and W.state(W.cast.PlayerCastingBarFrame.bar) == "hb")
	check("general: and said so once", #W.out == 1 and W.out[1] == "Flat UI: Cast bars stopped. /flatui status shows why. Type /reload if the look is left half changed.", table.concat(W.out, "|"))
	W.out = {}
	clean(W, "general")
end

-- 28. /flatui status has a line for the custom UI scale.
do
	local W = newWorld({ cvars = { useUiScale = "1", uiscale = "0.7200" }, uiScale = 0.72, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	W.login()
	check("scale status: the chosen scale when the game holds it", has(W.status(), "\nCustom UI scale: 72%.") and not has(W.status(), "asked"), W.status())
	W.fire("ADDON_ACTION_BLOCKED", "FlatUI", "Frame:SetPoint()")
	local lines = {}
	for line in (W.status() .. "\n"):gmatch("([^\n]*)\n") do
		lines[#lines + 1] = line
	end
	check("scale status: after the lines of the modules, before the refused calls", lines[#lines] == "Blocked by the game: Frame:SetPoint() (blocked)" and lines[#lines - 1] == "Custom UI scale: 72%."
		and (function()
			local last
			for _, module in ipairs(TOC.modules(W)) do
				for number, line in ipairs(lines) do
					if line:find("^" .. module.label .. ": ") then last = math.max(last or 0, number) end
				end
			end
			return last ~= nil and last < #lines - 1
		end)(), table.concat(lines, "|"))
	check("scale status: shown by the slash command too", has(W.slash("status"), "Custom UI scale: 72%."))
	W.change("general.scale", 80)
	W.advance(0.3)
	check("scale status: a written scale is the game's", has(W.status(), "Custom UI scale: 80%.") and not has(W.status(), "asked"), W.status())
	W.cvarRefuse.uiscale = true
	W.change("general.scale", 90)
	W.advance(0.3)
	W.advance(0.3)
	check("scale status: a write the game does not keep says what the game applied", has(W.status(), "Custom UI scale: 90% asked, the game applied 80%."), W.status())
	W.cvarRefuse.uiscale = nil
	W.combat = true
	W.change("general.scale", 85)
	check("scale status: inside the wait nothing is said about combat", not has(W.status(), "Waiting"), W.status())
	W.advance(0.3)
	check("scale status: once the change waits for combat to end it says so", has(W.status(), "Custom UI scale: 85%. Waiting for combat to end."), W.status())
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("scale status: and not after", has(W.status(), "Custom UI scale: 85%.") and not has(W.status(), "Waiting") and not has(W.status(), "asked"), W.status())
	W.scaleFault = "secret"
	check("scale status: a scale on screen that cannot be read is no error", #W.errors == 0 and has(W.status(), "Custom UI scale: 85%."), W.status())
	W.scaleFault = nil
	W.change("general.scaleOn", false)
	W.advance(0.3)
	check("scale status: with the custom scale off the line says /reload finishes it", has(W.status(), "Custom UI scale: off. /reload to finish.") and not has(W.status(), "85%"), W.status())
	local D = newWorld()
	D.login()
	check("scale status: none by default", not has(D.status(), "Custom UI scale"), D.status())
	W.out = {}
	clean(W, "scale status")
end

-- 29. /flatui scale.
do
	local W = newWorld()
	W.login()
	check("slash scale: 70 prints it, sets it and turns the custom scale on", W.slash("scale 70") == "Custom UI scale: 70%" and W.ns.Get("general.scale") == 70 and W.ns.Get("general.scaleOn") == true)
	check("slash scale: nothing is written at once", W.scaleWrites() == 0 and W.scale() == 0.64)
	W.advance(0.3)
	check("slash scale: 0.3 seconds later the game has it, without SetScale", near(W.scale(), 0.7) and W.cvars.uiscale == "0.7" and W.setScaleCalls == 0)
	check("slash scale: any case, any spaces", W.slash("  SCALE    80 ") == "Custom UI scale: 80%" and W.ns.Get("general.scale") == 80)
	check("slash scale: 65 is the smallest and 115 the largest", W.slash("scale 65") == "Custom UI scale: 65%" and W.ns.Get("general.scale") == 65 and W.slash("scale 115") == "Custom UI scale: 115%" and W.ns.Get("general.scale") == 115)
	for _, text in ipairs({ "scale 64", "scale 116", "scale 0", "scale 1000", "scale 00", "scale 50" }) do
		local out = W.slash(text)
		check("slash scale: '" .. text .. "' is out of range", out == "/flatui scale takes 65 to 115." and W.ns.Get("general.scale") == 115, out)
	end
	for _, text in ipairs({ "scale", "scale abc", "scale 50.5", "scale 50 60", "scale -5", "scale off now", "scales 50" }) do
		local out = W.slash(text)
		check("slash scale: '" .. text .. "' prints the help and changes nothing", out == TOC.allHelp(W)
			and W.ns.Get("general.scale") == 115 and W.ns.Get("general.scaleOn") == true, out)
	end
	W.advance(0.3)
	check("slash scale: the last good value is the one that is written", near(W.scale(), 1.15), W.scale())
	check("slash scale: off prints it and turns the custom scale off", W.slash("scale off") == "Custom UI scale: off" and W.ns.Get("general.scaleOn") == false)
	W.advance(0.3)
	check("slash scale: and the game's variables are back", W.cvars.useUiScale == "0" and W.cvars.uiscale == "0.64", W.cvars.uiscale)
	check("slash scale: off in any case, when it is already off", W.slash("SCALE OFF") == "Custom UI scale: off" and W.ns.Get("general.scaleOn") == false)
	check("slash scale: the choice is saved", W.options()["general.scale"] == 115 and W.options()["general.scaleOn"] == false)
	W.combat = true
	W.slash("scale 70")
	W.advance(0.3)
	check("slash scale: in combat the scale waits", near(W.scale(), 0.64) and #W.violations == 0 and W.cvars.useUiScale == "0")
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("slash scale: and is written when combat ends", near(W.scale(), 0.7), W.scale())
	W.out = {}
	clean(W, "slash scale")
	-- 65 is the default value of the scale, and the command must give 65 all the same.
	local D = newWorld()
	D.login()
	local out = D.slash("scale 65")
	D.advance(0.3)
	check("slash scale: 65 gives 65 percent, the default value included", out == "Custom UI scale: 65%" and D.ns.Get("general.scale") == 65 and near(D.scale(), 0.65), tostring(D.ns.Get("general.scale")) .. " " .. D.scale())
end

-- 30. The game's own values: a scale that is off or never on leaves them alone, and turning the scale off puts back what the game held before the first write.
do
	local function custom()
		return { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } }
	end
	-- Never switched on: login and scale events write nothing, whatever the variables say.
	local O = newWorld({ cvars = { useUiScale = "1", uiscale = "0.9" } })
	O.login()
	O.fire("UI_SCALE_CHANGED")
	O.fire("DISPLAY_SIZE_CHANGED")
	O.fire("PLAYER_ENTERING_WORLD", false, false)
	O.advance(1)
	check("game scale: with the custom scale off and never on, login and scale events write nothing", O.scaleWrites() == 0 and O.setScaleCalls == 0 and near(O.scale(), 0.64), O.scaleWrites() .. " " .. O.scale())
	O.change("general.scale", 70)
	O.advance(1)
	check("game scale: and so does a new value of the slider while the scale is off", O.scaleWrites() == 0 and O.setScaleCalls == 0, O.scaleWrites())
	O.change("general.scaleOn", true)
	O.advance(0.3)
	check("game scale: switched on, the chosen scale is written and the game's values are kept", near(O.scale(), 0.7) and O.scaleWrites() == 1 and O.setScaleCalls == 0
		and O.env.FlatUIDB.scaleGame.use == "1" and O.env.FlatUIDB.scaleGame.scale == "0.9", O.scale())
	O.setCVarByPlayer("uiscale", "0.95")
	O.fire("UI_SCALE_CHANGED")
	O.advance(1)
	check("game scale: a change the player makes by hand is not written over by an event", O.scaleWrites() == 1 and O.cvars.uiscale == "0.95")
	O.change("general.scaleOn", false)
	O.advance(0.3)
	check("game scale: switched off, the game's values from before the first write are back", O.cvars.useUiScale == "1" and O.cvars.uiscale == "0.9" and O.env.FlatUIDB.scaleGame == nil, O.cvars.uiscale)
	clean(O, "game scale")

	-- Variables that cannot be used.
	for _, case in ipairs({ { "0", "0 is not a scale" }, { "abc", "text is not a scale" }, { "-1", "a negative number is not a scale" } }) do
		local V = newWorld({ cvars = { useUiScale = "1", uiscale = case[1] }, uiScale = 0.5, saved = custom() })
		V.login()
		V.change("general.scale", 80)
		V.advance(0.3)
		V.change("general.scaleOn", false)
		V.advance(0.3)
		check("cvars: " .. case[2] .. ", the write and the way back raise nothing", #V.errors == 0 and #V.violations == 0 and V.cvars.uiscale == case[1] and V.cvars.useUiScale == "1", V.cvars.uiscale)
	end
	local N = newWorld({ noCVar = true, uiScale = 0.5, saved = custom() })
	N.login()
	N.change("general.scale", 80)
	N.advance(0.3)
	N.change("general.scaleOn", false)
	N.advance(0.3)
	check("cvars: a client without C_CVar is no problem and UIParent is not set", near(N.scale(), 0.5) and N.setScaleCalls == 0 and #N.errors == 0 and #N.violations == 0, N.scale())
	local X = newWorld({ saved = custom() })
	X.login()
	X.cvarFault = "secret"
	X.change("general.scale", 80)
	X.advance(0.3)
	X.change("general.scaleOn", false)
	X.advance(0.3)
	check("cvars: answers the game withholds are no error", #X.errors == 0 and #X.violations == 0 and X.setScaleCalls == 0, #X.errors)
	clean(N, "cvars")
end

-- 31. The first time Custom UI scale is ticked the scale starts from the scale on screen, and the open panel shows it.
do
	local W = newWorld({ uiScale = 0.8 })
	W.login()
	W.openPanel()
	check("first tick: the panel shows the default before", W.shown("general.scale") == 65 and W.shown("general.scaleOn") == false)
	W.change("general.scaleOn", true)
	check("first tick: the scale starts from the scale on screen", W.ns.Get("general.scale") == 80 and W.ns.IsSet("general.scale"))
	check("first tick: and the open panel shows it", W.shown("general.scale") == 80 and W.shown("general.scaleOn") == true, tostring(W.shown("general.scale")))
	W.advance(1)
	check("first tick: so nothing moves", W.setScaleCalls == 0 and near(W.scale(), 0.8))
	W.change("general.scale", 70)
	W.change("general.scaleOn", false)
	W.change("general.scaleOn", true)
	W.advance(1)
	check("first tick: the second time the saved scale is used", W.ns.Get("general.scale") == 70 and near(W.scale(), 0.7), tostring(W.ns.Get("general.scale")))
	check("first tick: the panel shows the saved scale", W.shown("general.scale") == 70)
	clean(W, "first tick")
	for _, case in ipairs({ { 0.3, 65 }, { 0.349, 65 }, { 0.357, 65 }, { 1.2, 115 }, { 1.15, 115 }, { 0.646, 65 }, { 0.7, 70 } }) do
		local V = newWorld({ uiScale = case[1] })
		V.login()
		V.change("general.scaleOn", true)
		check("first tick: a screen at " .. case[1] .. " starts the scale at " .. case[2], V.ns.Get("general.scale") == case[2], tostring(V.ns.Get("general.scale")))
	end
	-- A start that equals the default is saved all the same, so the second tick does not start again.
	local E = newWorld({ uiScale = 0.65 })
	E.login()
	E.change("general.scaleOn", true)
	check("first tick: a start of 65 is saved", E.ns.Get("general.scale") == 65 and E.ns.IsSet("general.scale"))
	E.change("general.scaleOn", false)
	E.advance(0.3)
	E.gameScale(0.8)
	E.change("general.scaleOn", true)
	E.advance(0.3)
	check("first tick: and the second tick uses it, not the screen's 80", E.ns.Get("general.scale") == 65 and near(E.scale(), 0.65), tostring(E.ns.Get("general.scale")))
	-- Saved with a scale: no new start.
	local S2 = newWorld({ uiScale = 0.8, saved = { options = { ["general.scale"] = 72 } } })
	S2.login()
	S2.change("general.scaleOn", true)
	S2.advance(0.3)
	check("first tick: a scale that is saved is used, not the screen's", S2.ns.Get("general.scale") == 72 and near(S2.scale(), 0.72))
	-- UIParent cannot be read.
	local F = newWorld()
	F.scaleFault = "error"
	F.login()
	F.change("general.scaleOn", true)
	check("first tick: with a scale on screen that cannot be read nothing is stored and nothing raises", not F.ns.IsSet("general.scale") and #F.errors == 0 and #F.violations == 0 and #F.out == 0)

	-- ns.NotifyOption asks the game to read the setting again.
	local N = newWorld()
	N.login()
	local told = {}
	local original = N.env.Settings.NotifyUpdate
	N.env.Settings.NotifyUpdate = function(variable)
		told[#told + 1] = variable
		return original(variable)
	end
	N.ns.NotifyOption("general.scale")
	N.ns.NotifyOption("nameplates.dim")
	N.ns.NotifyOption("bogus.path")
	check("NotifyOption: calls NotifyUpdate with the variable of the setting, and for a path nothing uses not at all", table.concat(told, ",") == "FLATUI_GENERAL_SCALE,FLATUI_NAMEPLATES_DIM" and #N.violations == 0,
		table.concat(told, ",") .. table.concat(N.violations, "|"))
	N.env.Settings.NotifyUpdate = function() error("not now", 0) end
	N.ns.NotifyOption("general.scale")
	check("NotifyOption: a NotifyUpdate that raises is no error", #N.errors == 0 and #N.violations == 0)
	local O = newWorld({ without = { ["Settings.NotifyUpdate"] = true }, uiScale = 0.8 })
	O.login()
	O.change("general.scaleOn", true)
	check("NotifyOption: a client without NotifyUpdate is no problem", O.ns.Get("general.scale") == 80 and #O.errors == 0 and #O.violations == 0)
	local R = newWorld({ noSettings = true, uiScale = 0.8 })
	R.login()
	R.ns.NotifyOption("general.scale")
	R.ns.Set("general.scaleOn", true)
	check("NotifyOption: and so is a client without the options", R.ns.Get("general.scale") == 80 and #R.errors == 0)
end

-- scaletaint: Flat UI never calls UIParent:SetScale for a scale the game takes. A SetScale from addon code changes the layout of every action bar and the game's
-- next secure layout pass runs tainted, so a click on an action button is refused with ADDON_ACTION_FORBIDDEN for UseAction (the report of 2026-10-13).
do
	-- Every value of the row goes to the game's variables, none to UIParent.
	local W = newWorld()
	W.login()
	W.change("general.scaleOn", true)
	local wrong = {}
	for percent = 65, 115 do
		W.change("general.scale", percent)
		W.advance(0.3)
		if W.setScaleCalls ~= 0 or W.cvars.uiscale ~= ("%.10g"):format(percent / 100) or not near(W.scale(), percent / 100) or W.cvars.useUiScale ~= "1" then
			wrong[#wrong + 1] = percent .. ":" .. tostring(W.cvars.uiscale)
		end
	end
	check("scaletaint: every Custom scale from 65 to 115 is written to useUiScale and uiscale and UIParent.SetScale is never called", #wrong == 0 and W.setScaleCalls == 0, table.concat(wrong, " "))
	check("scaletaint: the scale on screen is the game's own after each write, and the status says so", has(W.status(), "Custom UI scale: 115%.") and not has(W.status(), "asked"), W.status())
	W.fire("UI_SCALE_CHANGED")
	W.fire("DISPLAY_SIZE_CHANGED")
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.advance(2)
	check("scaletaint: the game's scale events only read back", W.setScaleCalls == 0 and W.scaleWrites() == 2 + 50, W.scaleWrites())
	check("scaletaint: no call refused and nothing raised", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"))

	-- A login with the variables already holding the scale writes nothing.
	local L = newWorld({ cvars = { useUiScale = "1", uiscale = "0.72" }, uiScale = 0.72, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	L.login()
	L.fire("PLAYER_ENTERING_WORLD", true, false)
	L.advance(1)
	check("scaletaint: a login with the variables already at the saved scale writes nothing and does not set UIParent", L.scaleWrites() == 0 and L.setScaleCalls == 0 and near(L.scale(), 0.72))

	-- The game keeps another value: the check says so once and does not try again.
	local F = newWorld({ engineFloor = 0.7 })
	F.login()
	F.change("general.scaleOn", true)
	F.change("general.scale", 65)
	F.advance(0.3)
	F.advance(0.3)
	check("scaletaint: a read-back of 0.7 against the 0.65 asked marks the write refused, with one status line", has(F.status(), "Custom UI scale: 65% asked, the game applied 70%.") and F.setScaleCalls == 0, F.status())
	local writes = F.scaleWrites()
	F.fire("UI_SCALE_CHANGED")
	F.advance(2)
	check("scaletaint: and no write is repeated", F.scaleWrites() == writes, F.scaleWrites() .. "/" .. writes)
	local H = newWorld({ holdScale = true })
	H.login()
	H.change("general.scaleOn", true)
	H.change("general.scale", 80)
	H.advance(0.3)
	H.advance(0.3)
	check("scaletaint: a variable that holds the scale while UIParent keeps its own is refused, with the scale on screen in the status", has(H.status(), "Custom UI scale: 80% asked, the game applied 64%."), H.status())
	local A = newWorld({ engineFloor = 0.7, scaleLater = true })
	A.login()
	A.change("general.scaleOn", true)
	A.change("general.scale", 65)
	A.advance(0.3)
	A.advance(0.06)
	check("scaletaint: a scale event that comes after the write checks it before the wait is over", has(A.status(), "Custom UI scale: 65% asked, the game applied 70%.") and A.setScaleCalls == 0, A.status())
	local Z = newWorld({ engineFloor = 0.7 })
	Z.env.C_Timer = nil
	Z.login()
	Z.change("general.scaleOn", true)
	Z.change("general.scale", 65)
	check("scaletaint: with no timer the write is checked at once", has(Z.status(), "Custom UI scale: 65% asked, the game applied 70%."), Z.status())
	local N0 = newWorld({ noCVar = true, uiScale = 0.5 })
	N0.login()
	N0.change("general.scaleOn", true)
	N0.change("general.scale", 80)
	N0.advance(0.3)
	check("scaletaint: a client without SetCVar says it was refused and sets nothing", has(N0.status(), "Custom UI scale: 80% asked, the game applied 50%.") and N0.setScaleCalls == 0, N0.status())
	local R = newWorld()
	R.login()
	R.cvarRefuse.uiscale = true
	R.change("general.scaleOn", true)
	R.change("general.scale", 80)
	R.advance(0.3)
	R.advance(0.3)
	check("scaletaint: a variable the game does not write is refused in the status and UIParent is left alone", has(R.status(), "asked, the game applied 64%.") and R.setScaleCalls == 0 and near(R.scale(), 0.64), R.status())

	-- A write in combat waits.
	local C = newWorld()
	C.login()
	C.combat = true
	C.change("general.scaleOn", true)
	C.change("general.scale", 90)
	C.advance(1)
	check("scaletaint: in combat nothing is written and UIParent is not set", C.scaleWrites() == 0 and C.setScaleCalls == 0 and #C.violations == 0 and has(C.status(), "Waiting for combat to end."), C.status())
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	check("scaletaint: and one write is made when combat ends", C.scaleWrites() == 2 and near(C.scale(), 0.9) and C.setScaleCalls == 0, C.scaleWrites())

	-- Turning the scale off writes back what the game held.
	local O = newWorld({ cvars = { useUiScale = "1", uiscale = "0.9" }, uiScale = 0.9 })
	O.login()
	O.change("general.scaleOn", true)
	O.change("general.scale", 70)
	O.advance(0.3)
	O.change("general.scaleOn", false)
	O.advance(0.3)
	check("scaletaint: turning the scale off writes the game's own useUiScale and uiscale back", O.cvars.useUiScale == "1" and O.cvars.uiscale == "0.9" and near(O.scale(), 0.9) and O.setScaleCalls == 0 and O.env.FlatUIDB.scaleGame == nil)

	-- Pixel-perfect goes the same way, inside the game's range.
	local P = newWorld()
	P.login()
	P.change("general.scaleOn", true)
	P.change("general.pixelPerfect", true)
	P.advance(0.3)
	check("scaletaint: pixel-perfect at 1080 lines with 1 px per unit writes 768/1080 and calls no SetScale", near(P.scale(), 768 / 1080) and P.setScaleCalls == 0 and tonumber(P.cvars.uiscale) and near(tonumber(P.cvars.uiscale), 768 / 1080, 1e-9), P.cvars.uiscale)
	P.height = 1440
	P.fire("DISPLAY_SIZE_CHANGED")
	P.advance(0.3)
	local before = P.scaleWrites()
	check("scaletaint: at 1440 lines with 1 px per unit the scale is 53%, under the game's 65%, so the game's values are back and nothing is set", P.setScaleCalls == 0 and P.cvars.useUiScale == "0"
		and has(P.status(), "needs 53%, under the game's 65%, so it is not applied."), P.status())
	P.fire("DISPLAY_SIZE_CHANGED")
	P.advance(1)
	check("scaletaint: and the next event writes nothing more", P.scaleWrites() == before)
	P.change("general.pixelSize", 2)
	P.advance(0.3)
	check("scaletaint: 2 px per unit at 1440 lines is 107%, inside the range, and is written", near(tonumber(P.cvars.uiscale), 2 * 768 / 1440, 1e-9) and P.setScaleCalls == 0, P.cvars.uiscale)
end

-- scaletaint: a scale under what the game takes.
do
	-- The row Scale below 65% is the one route that still calls SetScale, with its warning.
	local B = newWorld()
	B.login()
	B.change("general.scaleOn", true)
	B.change("general.scaleBelow", true)
	B.advance(0.3)
	check("scaletaint: Scale below 65% on gives SetScale 0.6 once and no write to the game's variables", B.setScaleCalls == 1 and near(B.scale(), 0.6) and B.scaleWrites() == 0, B.setScaleCalls)
	check("scaletaint: and the status line warns about action button presses", has(B.status(), "Scale below 65%: 60%. The game can refuse presses of its own action buttons."), B.status())
	B.change("general.scaleSmall", 50)
	B.advance(0.3)
	check("scaletaint: Small scale moves it to 50%", B.setScaleCalls == 2 and near(B.scale(), 0.5), B.setScaleCalls)
	B.fire("UI_SCALE_CHANGED")
	B.advance(0.3)
	check("scaletaint: an event that finds it in place changes nothing", B.setScaleCalls == 2)
	B.gameScale(0.64)
	B.advance(0.3)
	check("scaletaint: and one that puts the game's scale back sets it again", B.setScaleCalls == 3 and near(B.scale(), 0.5), B.setScaleCalls)
	B.change("general.scaleBelow", false)
	B.advance(0.3)
	check("scaletaint: turning the row off sets nothing back and says /reload does", B.setScaleCalls == 3 and has(B.status(), "/reload puts the game's scale back."), B.status())
	local T = newWorld()
	T.login()
	T.change("general.scaleOn", true)
	T.change("general.pixelPerfect", true)
	T.change("general.scaleBelow", true)
	T.height = 1440
	T.fire("DISPLAY_SIZE_CHANGED")
	T.advance(0.3)
	check("scaletaint: pixel-perfect under 65% with the row on is set with SetScale, not written", T.setScaleCalls == 1 and near(T.scale(), 768 / 1440) and T.scaleWrites() == 0, T.setScaleCalls)

	-- A profile saved with a scale under the game's: nothing is applied, and the player is told once.
	local line = "Flat UI: Custom scale 60% is under the game's 65%, so it is not applied. Turn on Custom UI scale and Scale below 65% to use it."
	local O = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 60 } } })
	O.login()
	O.advance(1)
	local told = 0
	for _, text in ipairs(O.out) do
		if text == line then told = told + 1 end
	end
	check("scaletaint: a saved profile at 60% applies nothing at login", O.setScaleCalls == 0 and O.scaleWrites() == 0 and near(O.scale(), 0.64) and O.ns.Get("general.scaleOn") == false, O.setScaleCalls)
	check("scaletaint: and says so once in chat", told == 1, table.concat(O.out, "|"))
	check("scaletaint: and in one status line", has(O.status(), "Custom UI scale: 60% is under the game's 65%, so it is not applied."), O.status())
	check("scaletaint: the 60 is kept as Small scale, Custom scale is 65, Scale below 65% is off", O.ns.Get("general.scaleSmall") == 60 and O.ns.Get("general.scale") == 65 and O.ns.Get("general.scaleBelow") == false)
	O.change("general.scaleOn", true)
	O.change("general.scaleBelow", true)
	O.advance(0.3)
	check("scaletaint: turning Scale below 65% on uses the 60", O.setScaleCalls == 1 and near(O.scale(), 0.6), O.setScaleCalls)
	local E64 = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 64 } } })
	E64.login()
	check("scaletaint: 64% is under the game's 65% too", E64.ns.Get("general.scaleSmall") == 64 and E64.ns.Get("general.scaleOn") == false and has(E64.status(), "Custom UI scale: 64% is under"), E64.status())
	local E65 = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 65 } } })
	E65.login()
	check("scaletaint: 65% is the game's own and is kept", E65.ns.Get("general.scale") == 65 and E65.ns.Get("general.scaleOn") == true and E65.ns.IsSet("general.scaleSmall") == false and #E65.out == 0)
	local M2 = newWorld({ saved = { profiles = { Default = { options = {}, movers = {} }, Other = { options = { ["general.scaleOn"] = true, ["general.scale"] = 60 }, movers = {} } }, profileOf = {} } })
	M2.login()
	check("scaletaint: a profile that is not in use is moved too, and says nothing until it is in use", #M2.out == 0 and not has(M2.status(), "under the game's"), M2.status())
	M2.ns.UseProfile("Other")
	M2.flush()
	check("scaletaint: and the status of that profile says so", has(M2.status(), "Custom UI scale: 60% is under the game's 65%, so it is not applied."), M2.status())
	local Q = newWorld()
	Q.login()
	Q.change("general.scaleOn", true)
	Q.change("general.scaleBelow", true)
	Q.advance(0.3)
	Q.change("general.scaleOn", false)
	Q.advance(0.3)
	check("scaletaint: turning the scale off after a SetScale says /reload puts the game's back and sets nothing", Q.setScaleCalls == 1 and has(Q.status(), "Custom UI scale: off. /reload puts the game's scale back."), Q.status())
	local N = newWorld({ saved = { options = { ["general.scaleOn"] = false, ["general.scale"] = 50 } } })
	N.login()
	check("scaletaint: a scale under 65 saved while the scale was off is moved without a word", N.ns.Get("general.scaleSmall") == 50 and N.ns.Get("general.scale") == 65 and #N.out == 0 and not has(N.status(), "under the game's"))
end

-- scaletaint: after a /reload the variables hold Flat UI's scale and the account holds the game's own. Putting it back does not depend on this session's writes.
do
	local function reloaded(extra)
		local o = { cvars = { useUiScale = "1", uiscale = "0.72" }, uiScale = 0.72,
			saved = { scaleGame = { use = "0", scale = "1" }, options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } }
		for k, v in pairs(extra or {}) do o[k] = v end
		return newWorld(o)
	end
	local R = reloaded()
	R.login()
	R.advance(1)
	check("scaletaint: a login with the saved scale already in the variables writes nothing", R.scaleWrites() == 0 and R.setScaleCalls == 0, R.scaleWrites())
	R.change("general.scaleOn", false)
	R.advance(1)
	check("scaletaint: after a reload, turning the scale off writes the game's own values back", R.cvars.useUiScale == "0" and R.cvars.uiscale == "1" and R.env.FlatUIDB.scaleGame == nil and R.setScaleCalls == 0,
		tostring(R.cvars.useUiScale) .. " " .. tostring(R.cvars.uiscale))
	check("scaletaint: and the status says /reload finishes it", has(R.status(), "Custom UI scale: off. /reload to finish."), tostring(R.status()))
	local S = reloaded()
	S.login()
	S.advance(1)
	S.slash("scale off")
	S.advance(1)
	check("scaletaint: /flatui scale off after a reload writes the game's values back", S.cvars.useUiScale == "0" and S.env.FlatUIDB.scaleGame == nil, tostring(S.cvars.useUiScale))
	local P = newWorld({ cvars = { useUiScale = "1", uiscale = "0.72" }, uiScale = 0.72,
		saved = { scaleGame = { use = "0", scale = "1" }, profiles = { Default = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 }, movers = {} }, Other = { options = {}, movers = {} } }, profileOf = {} } })
	P.login()
	P.advance(1)
	P.ns.UseProfile("Other")
	P.flush()
	P.advance(1)
	check("scaletaint: after a reload, a profile without the scale puts the game's values back", P.cvars.useUiScale == "0" and P.env.FlatUIDB.scaleGame == nil, tostring(P.cvars.useUiScale))
	-- Scale below 65% turned on after a reload gives the game's values back first.
	local B = reloaded()
	B.login()
	B.advance(1)
	B.change("general.scaleBelow", true)
	B.advance(1)
	check("scaletaint: after a reload, Scale below 65% puts the game's values back and sets the small scale", B.cvars.useUiScale == "0" and B.env.FlatUIDB.scaleGame == nil and B.setScaleCalls >= 1 and near(B.scale(), 0.6),
		tostring(B.cvars.useUiScale) .. " " .. B.setScaleCalls .. " " .. tostring(B.scale()))
	-- Pixel-perfect out of range after a display change, in a session that only read the scale back.
	local X = reloaded({ saved = { scaleGame = { use = "0", scale = "1" }, options = { ["general.scaleOn"] = true, ["general.pixelPerfect"] = true } },
		cvars = { useUiScale = "1", uiscale = tostring(768 / 1080) }, uiScale = 768 / 1080 })
	X.login()
	X.advance(1)
	X.height = 1440
	X.fire("DISPLAY_SIZE_CHANGED")
	X.advance(1)
	check("scaletaint: after a reload, pixel-perfect under 65% after a display change puts the game's values back", X.cvars.useUiScale == "0" and X.env.FlatUIDB.scaleGame == nil
		and has(X.status(), "needs 53%, under the game's 65%, so it is not applied."), tostring(X.cvars.useUiScale) .. " " .. tostring(X.status()))
	-- Every live write says /reload finishes it.
	local W = newWorld()
	W.login()
	W.change("general.scaleOn", true)
	W.change("general.scale", 80)
	W.advance(1)
	check("scaletaint: a live write says /reload finishes it", has(W.status(), "Custom UI scale: 80%. /reload to finish."), tostring(W.status()))
	-- Uiscale is written before useUiScale.
	local order = {}
	local V = newWorld()
	V.login()
	local set = V.env.C_CVar.SetCVar
	V.env.C_CVar.SetCVar = function(name, value, ...)
		order[#order + 1] = name
		return set(name, value, ...)
	end
	V.change("general.scaleOn", true)
	V.change("general.scale", 80)
	V.advance(1)
	check("scaletaint: uiscale is written before useUiScale", order[1] == "uiscale" and order[2] == "useUiScale", table.concat(order, ","))
	-- A login whose variables hold another scale writes nothing, and the status names the next step.
	local L = newWorld({ cvars = { useUiScale = "1", uiscale = "0.9" }, uiScale = 0.9, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	L.login()
	L.advance(1)
	check("scaletaint: a login with another scale in the variables writes nothing and says how to write it", L.scaleWrites() == 0 and L.setScaleCalls == 0
		and has(L.status(), "Custom UI scale: 72% asked, the game has 90%. Turn Custom UI scale off and on to write it."), tostring(L.status()))
	-- An imported profile with a scale under 65 moves it to Small scale.
	local J = newWorld()
	J.login()
	local text = J.ns.PackText("FlatUI1:", { "o|general.scaleOn|1", "o|general.scale|60" })
	local imported = J.ns.ImportProfile(text)
	J.advance(1)
	check("scaletaint: an imported scale of 60 becomes Small scale 60, Custom scale 65, with the scale off", imported and J.ns.Get("general.scaleSmall") == 60 and J.ns.Get("general.scale") == 65
		and J.ns.Get("general.scaleOn") == false and J.setScaleCalls == 0 and J.scaleWrites() == 0, tostring(J.ns.Get("general.scale")) .. " " .. tostring(J.ns.Get("general.scaleSmall")))
	check("scaletaint: and the status says it is not applied", has(J.status(), "Custom UI scale: 60% is under the game's 65%, so it is not applied."), tostring(J.status()))
end

-- 32. Personal resource display: Join bars.
do
	local W = newWorld()
	W.login()
	local one = PX / 0.64
	local power, alt = W.prd.power[2], W.prd.alt[2]
	check("join: the power bar and the alternate power bar hang one border thickness below the bar above", near(W.gap("power"), one) and near(W.gap("alt"), one)
		and near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), g(W.gap("power")) .. " " .. g(W.gap("alt")))
	local p, a = power.points[1], alt.points[1]
	check("join: each is still anchored by its TOP to the BOTTOM of the same bar, with the same x", #power.points == 1 and p[1] == "TOP" and p[2] == W.prdContainer and p[3] == "BOTTOM" and p[4] == 0
		and #alt.points == 1 and a[1] == "TOP" and a[2] == W.prd.power[1] and a[3] == "BOTTOM" and a[4] == 0)
	check("join: the health bar is not moved", #W.prd.health[2].points == 0)
	for _, t in ipairs({ 2, 3, 1 }) do
		W.change("general.thickness", t)
		check("join: border thickness " .. t .. " makes the gap " .. t .. " pixels", near(W.gapPixels("power"), t) and near(W.gapPixels("alt"), t), g(W.gapPixels("power")) .. " " .. g(W.gapPixels("alt")))
	end
	W.change("resource.join", false)
	check("join: off gives the game's gap back, 4 units", near(W.gap("power"), 4) and near(W.gap("alt"), 4) and W.prd.power[2].points[1][2] == W.prdContainer, g(W.gap("power")) .. " " .. g(W.gap("alt")))
	W.change("resource.join", true)
	check("join: on again", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	-- The game's gap is what the game set, not the last joined one.
	W.change("general.thickness", 2)
	W.change("resource.join", false)
	check("join: after a change of thickness, off gives the game's gap, not the one that was joined", near(W.gap("power"), 4) and near(W.gap("alt"), 4), g(W.gap("power")) .. " " .. g(W.gap("alt")))
	W.change("general.thickness", 1)
	W.change("resource.join", true)
	W.change("resource.enabled", false)
	check("join: the module off gives the game's gap back", near(W.gap("power"), 4) and near(W.gap("alt"), 4))
	W.change("resource.enabled", true)
	check("join: and on again joins", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	-- The game lays the bars out again: through the two functions it has for it.
	W.prdPadding = 12
	W.layoutResource()
	check("join: after the game lays the bars out again they are joined at once", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	W.change("resource.join", false)
	check("join: and off gives the game's newest gap", near(W.gap("power"), 12) and near(W.gap("alt"), 12), g(W.gap("power")))
	W.prdPadding = 4
	W.change("resource.join", true)
	W.layoutResource()
	W.blizzard(function() W.env.PersonalResourceDisplayFrame:UpdatePowerBarAnchor() end)
	check("join: UpdatePowerBarAnchor alone: nothing follows the call, the next frame after a script of the display joins the power bar", not near(W.gapPixels("power"), 1))
	W.afterLayout()
	check("join: and then the power bar is joined again", near(W.gapPixels("power"), 1))
	W.blizzard(function() W.env.PersonalResourceDisplayFrame:UpdateAdditionalBarAnchors() end)
	W.afterLayout()
	check("join: UpdateAdditionalBarAnchors alone: the alternate power bar is joined again", near(W.gapPixels("alt"), 1))
	W.blizzard(function() W.env.PersonalResourceDisplayFrame:UpdateAdditionalBarAnchors() end)
	W.afterLayout()
	local sets = power.calls.SetPoint
	W.blizzard(function() W.env.PersonalResourceDisplayFrame:UpdateAdditionalBarAnchors() end)
	W.afterLayout()
	check("join: a bar that is already where it should be is not anchored again", power.calls.SetPoint == sets)
	check("join: no method of the display is hooked however often it is refreshed", W.hooks == 0, W.hooks)
	-- Only a bar with a border, under a bar with a border, is joined.
	W.change("resource.power", false)
	check("join: no border on the power bar: it is not joined, nor is the alternate bar that hangs from it", near(W.gap("power"), 4) and near(W.gap("alt"), 4))
	W.change("resource.power", true)
	W.change("resource.health", false)
	check("join: no border on the health bar: the power bar is not joined, the alternate bar is", near(W.gap("power"), 4) and near(W.gapPixels("alt"), 1))
	W.change("resource.health", true)
	W.change("resource.alt", false)
	check("join: no border on the alternate bar: the power bar is joined, the alternate bar is not", near(W.gapPixels("power"), 1) and near(W.gap("alt"), 4))
	W.change("resource.alt", true)
	W.prdInner.hidePower = true
	W.change("resource.power", false)
	check("join: with the power bar hidden the alternate bar needs the health border, not the power border", near(W.gapPixels("alt"), 1) and near(W.gap("power"), 4))
	W.change("resource.health", false)
	check("join: and none without the health border", near(W.gap("alt"), 4))
	W.change("resource.health", true)
	W.prdInner.hidePower = nil
	W.layoutResource()
	check("join: with the power bar shown again the alternate bar needs the power border", near(W.gap("alt"), 4))
	W.change("resource.power", true)
	check("join: all borders on: both joined", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	-- The scale of the game and the size of the screen.
	W.gameScale(1.0)
	check("join: the game's scale changes and the gap is still the thickness in pixels", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), g(W.gapPixels("power")))
	W.height = 2160
	W.fire("DISPLAY_SIZE_CHANGED")
	check("join: so does the size of the screen", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), g(W.gapPixels("power")))
	W.height = 1440
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	check("join: and Edit Mode", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	W.height = 1080
	W.gameScale(0.9)
	W.change("resource.join", false)
	check("join: after the game's scale changed, off still gives the game's gap", near(W.gap("power"), 4) and near(W.gap("alt"), 4), g(W.gap("power")))
	W.change("resource.join", true)
	-- The custom UI scale.
	W.change("general.scaleOn", true)
	W.change("general.scale", 70)
	W.advance(0.3)
	check("join: the custom UI scale is applied, and the gap is still the thickness in pixels", near(W.scale(), 0.7) and near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), g(W.gapPixels("power")))
	W.change("general.scale", 90)
	W.advance(0.3)
	check("join: and when the slider moves", near(W.scale(), 0.9) and near(W.gapPixels("power"), 1), g(W.gapPixels("power")))
	W.change("general.scaleOn", false)
	W.advance(0.3)
	check("join: and when it is switched off", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), g(W.gapPixels("power")))
	-- A change of size in combat waits.
	W.combat = true
	W.gameScale(0.7)
	check("join: a resize in combat waits", not near(W.gapPixels("power"), 1))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("join: and is done when combat ends", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
	-- A module that stopped leaves the game's layout alone.
	for i = 1, 5 do
		W.ns.Each("resource", function() error("bad", 0) end, "frame" .. i)
	end
	check("join: when the module stops the game's gap is back", W.ns.IsStopped("resource") and near(W.gap("power"), 4) and near(W.gap("alt"), 4), g(W.gap("power")))
	W.prdPadding = 6
	W.layoutResource()
	check("join: and the game's next layout is left as it is", near(W.gap("power"), 6) and near(W.gap("alt"), 6), g(W.gap("power")))
	W.gameScale(0.5)
	W.change("general.thickness", 3)
	check("join: and so are a change of scale and of thickness", near(W.gap("power"), 6) and near(W.gap("alt"), 6), g(W.gap("power")))
	W.out = {}
	clean(W, "join")

	-- Custom UI scale already on at login.
	local C = newWorld({ cvars = { useUiScale = "1", uiscale = "0.7200" }, uiScale = 0.72, saved = { options = { ["general.scaleOn"] = true, ["general.scale"] = 72 } } })
	C.login()
	check("join: with a custom UI scale at login the gap is the thickness in pixels", near(C.scale(), 0.72) and near(C.gapPixels("power"), 1) and near(C.gapPixels("alt"), 1), g(C.gapPixels("power")))
	clean(C, "join with custom scale")

	-- The game's own x offset and anchor are kept.
	local X = newWorld()
	X.prd.power[2].points[1][4] = 3
	X.login()
	check("join: the x offset the game set is kept", X.prd.power[2].points[1][4] == 3 and near(X.gapPixels("power"), 1))
	-- A bar that hangs from the display itself is not joined.
	local H = newWorld()
	H.prd.power[1]:ClearAllPoints()
	H.prd.power[1]:SetPoint("TOP", H.prdFrame, "TOP", 0, 0)
	local before = H.prd.power[2].calls.SetPoint
	H.login()
	local hp = H.prd.power[2].points[1]
	check("join: a bar that hangs from the display itself is left alone", #H.prd.power[2].points == 1 and hp[3] == "TOP" and hp[5] == 0 and H.prd.power[2].calls.SetPoint == before and near(H.gapPixels("alt"), 1))
	-- A bar whose point cannot be read.
	local E = newWorld()
	E.prd.power[2].GetPoint = function() error("no", 0) end
	E.prd.alt[2].GetPoint = function() return "TOP", E.prdContainer, "BOTTOM", 0, SECRET end
	E.login()
	check("join: a point that cannot be read, or is secret, is left alone and is no failure", E.prd.power[2].calls.SetPoint == 1 and E.prd.alt[2].calls.SetPoint == 1 and not has(E.status(), "failed") and #E.out == 0
		and #E.violations == 0)
	local E2 = newWorld()
	E2.prd.power[2].GetPoint = function() return "TOP", E2.prdContainer, "BOTTOM", "0", -4 end
	E2.prd.alt[2].GetPoint = function() return end
	E2.login()
	check("join: an x that is no number, or no point at all, is left alone", E2.prd.power[2].calls.SetPoint == 1 and E2.prd.alt[2].calls.SetPoint == 1 and #E2.out == 0 and not has(E2.status(), "failed"))
	-- Anchors that are not the game's TOP to BOTTOM.
	local function oddAnchor(name, point, relativeTo, relativePoint, x, y)
		local O = newWorld()
		O.prd.power[2].GetPoint = function() return point, relativeTo(O), relativePoint, x, y end
		O.login()
		check("join: " .. name .. " is left alone", O.prd.power[2].calls.SetPoint == 1 and not has(O.status(), "failed") and #O.out == 0 and #O.violations == 0, O.line("Personal resource display"))
	end
	oddAnchor("a bar anchored by its BOTTOM to the BOTTOM of another", "BOTTOM", function(O) return O.prdContainer end, "BOTTOM", 0, -4)
	oddAnchor("a bar anchored by its TOPLEFT", "TOPLEFT", function(O) return O.prdContainer end, "BOTTOMLEFT", 0, -4)
	oddAnchor("a bar that hangs from nothing", "TOP", function() return nil end, "BOTTOM", 0, -4)
	oddAnchor("a bar that hangs from something the client withholds", "TOP", function() return SECRET end, "BOTTOM", 0, -4)
	oddAnchor("a bar with a gap that is no number", "TOP", function(O) return O.prdContainer end, "BOTTOM", 0, "abc")
	local FA = newWorld({ forbidden = { ["PRD.alt"] = true } })
	FA.login()
	check("join: an alternate power bar the addon may not touch is left alone, the power bar is still joined", #FA.violations == 0 and FA.prd.alt[2].calls.SetPoint == 1 and near(FA.gapPixels("power"), 1)
		and not has(FA.status(), "failed"), table.concat(FA.violations, "|"))
	local FB = newWorld({ forbidden = { ["PRD.power"] = true } })
	FB.login()
	check("join: a power bar the addon may not touch is left alone, the alternate bar below it still joined", #FB.violations == 0 and FB.prd.power[2].calls.SetPoint == 1 and near(FB.gapPixels("alt"), 1)
		and not has(FB.status(), "failed"), table.concat(FB.violations, "|"))
	-- A client where the display has no layout functions to follow.
	local N = newWorld({ noAnchorMethods = true })
	N.prd.power[1]:SetPoint("TOP", N.prdContainer, "BOTTOM", 0, -4)
	N.login()
	check("join: without the layout functions nothing is hooked, and the bars that have a gap are joined", N.hooks == 0 and near(N.gapPixels("power"), 1) and #N.errors == 0 and #N.violations == 0, N.hooks)
	-- No alternate power bar.
	local A = newWorld({ noAlternatePower = true })
	A.login()
	check("join: without an alternate power bar the power bar is joined and nothing raises", near(A.gapPixels("power"), 1) and #A.errors == 0 and not has(A.status(), "failed"))
end

-- 32b. Notes about art the addon cannot find.
do
	local D = newWorld()
	D.login()
	check("resource: no note when the default frame of every bar is found", not has(D.status(), "was not found"), D.status())
	local A = newWorld({ resourceAtlas = "some-other-atlas" })
	A.login()
	local note = "Personal resource display: the default frame of a bar was not found and is still shown."
	check("resource: a note under the module line when it is not found, once for three bars", count(A.status(), note) == 1 and has(A.status(), "Personal resource display: on, 3 styled\n" .. note), A.status())
end

-- 33. Cast bars: an edge the game refuses to anchor leaves the bar its own frame.
do
	local W = newWorld()
	local target = W.cast.TargetFrameSpellBar
	W.refuse[target.bar] = true
	W.login()
	local p = target.parts
	check("cast refused: the bar keeps its frame, its background, its shadow and its name plate", p.Border.alpha == 1 and p.Background.alpha == 1 and p.DropShadow.alpha == 1 and p.TextBorder.alpha == 1, g(p.Border.alpha))
	local shown = 0
	for _, t in ipairs(W.addonTextures) do
		if t.owner == target.bar and t.shown then
			shown = shown + 1
		end
	end
	check("cast refused: and nothing of the addon's is shown on it", shown == 0 and #W.edgesOn(target.bar) == 0, shown)
	local note = "Cast bars: the game refused a border on one bar, which keeps its default frame."
	check("cast refused: a note under the module line", has(W.status(), "Cast bars: on, 5 styled\n" .. note) and count(W.status(), note) == 1, W.status())
	check("cast refused: the other bars are styled", W.cast.FocusFrameSpellBar.parts.Border.alpha == 0 and W.cast.PlayerCastingBarFrame.parts.Border.alpha == 0 and W.state(W.cast.FocusFrameSpellBar.bar) == "SB")
	W.refuse[target.bar] = nil
	W.change("general.thickness", 2)
	check("cast refused: when the game accepts the anchors the bar gets its border at the next change", p.Border.alpha == 0 and W.state(target.bar) == "SB" and ringed(W, target.bar, 2 * PX / 0.64))
	W.out = {}
	clean(W, "cast refused")

	-- A re-layout that is refused leaves the edges where they were.
	local V = newWorld()
	V.login()
	local bar = V.cast.TargetFrameSpellBar.bar
	local one = PX / 0.64
	V.refuse[bar] = true
	V.change("general.thickness", 3)
	local edges = V.edgesOn(bar)
	local kept = #edges == 4
	for _, edge in ipairs(edges) do
		kept = kept and #edge.points == 2 and edge.calls.ClearAllPoints == nil
	end
	check("cast refused: a refused re-layout leaves every edge its two old anchors and clears none", kept and near(edges[1].points[1][4], -one) and near(edges[1].points[2][4], one), edges[1] and g(edges[1].points[1][4]))
	check("cast refused: the art stays faded since the edges are still anchored", V.cast.TargetFrameSpellBar.parts.Border.alpha == 0 and V.state(bar) == "SB" and not has(V.status(), "refused"))
	V.refuse[bar] = nil
	V.change("general.thickness", 2)
	check("cast refused: and the next layout the game accepts places them", ringed(V, bar, 2 * PX / 0.64))

	-- Whatever GetNumPoints answers that is not a number, the bar is taken as anchored.
	for _, fault in ipairs({ "error", "secret", "string" }) do
		local F = newWorld()
		F.refuse[F.cast.TargetFrameSpellBar.bar] = true
		F.numPointsFault = fault
		F.login()
		check("cast refused: a point count that is " .. fault .. " is taken as anchored: faded, no note", F.cast.TargetFrameSpellBar.parts.Border.alpha == 0 and not has(F.status(), "refused") and #F.out == 0
			and #F.violations == 0)
	end
end

-- 34. Nameplates: the level box's target marker, plates that failed once, and plates restored when the module stops.
do
	-- Blizzard's own target marker on the level box is faded only when the level box has a thin border or text only,
	-- and both the health bar border and the target border are on.
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	W.flush()
	local wrong = {}
	for _, style in ipairs({ "Thin border", "Text only", "Default" }) do
		for _, health in ipairs({ true, false }) do
			for _, target in ipairs({ true, false }) do
				W.change("nameplates.level", style)
				W.change("nameplates.health", health)
				W.change("nameplates.target", target)
				W.flush()
				local want = (style ~= "Default" and health and target) and 0 or 1
				if plate.level.selectedBorder.alpha ~= want then
					wrong[#wrong + 1] = style .. "/health " .. tostring(health) .. "/target " .. tostring(target) .. "=" .. g(plate.level.selectedBorder.alpha)
				end
			end
		end
	end
	check("level marker: faded only with a level style that is not Default and both the health border and the target border on", #wrong == 0, table.concat(wrong, "; "))
	W.change("nameplates.level", "Thin border")
	W.change("nameplates.health", true)
	W.change("nameplates.target", true)
	W.change("nameplates.enabled", false)
	check("level marker: back with the module off", plate.level.selectedBorder.alpha == 1)
	clean(W, "level marker")

	-- A plate whose first styling failed is not counted as styled, and is tried again at the next refresh, whether it is on screen or not.
	local F = newWorld()
	F.login()
	local flaky = F.newPlate({ breakTextures = true, hidden = true })
	F.showPlate("nameplate1", flaky)
	F.units.nameplate1 = nil
	F.flush()
	check("failed plate: not counted as styled, counted as failed, its art left alone", has(F.status(), "Nameplates: on, 0 styled, 1 failed. CreateTexture failed") and flaky.healthBar.bgTexture.alpha == 1, F.line("Nameplates"))
	F.fire("PLAYER_TARGET_CHANGED")
	F.flush()
	F.change("nameplates.dim", true)
	F.change("nameplates.dim", false)
	check("failed plate: and retried without being counted again, the module runs on", has(F.status(), "Nameplates: on, 0 styled, 1 failed. ") and not F.ns.IsStopped("nameplates") and #F.out == 0, F.line("Nameplates"))
	flaky.repair()
	F.change("nameplates.dim", true)
	check("failed plate: when it works again the next refresh styles it, though it is on no screen, and counts it", plateLine(F, flaky) == "bg=0 sel=0 over=1 | lvl=0,0 | cast=0,0 | H:SB L:SB C:SB" and has(F.status(), "Nameplates: on, 1 styled, 1 failed. "),
		plateLine(F, flaky) .. " " .. F.line("Nameplates"))
	F.units.target = flaky
	F.fire("PLAYER_TARGET_CHANGED")
	F.flush()
	check("failed plate: and it takes part in the marks of the target", ringOf(F, flaky.healthBar, 1, 1, 1, 1))
	clean(F, "failed plate")

	-- A plate that got halfway has an outline over Blizzard's art. When the module stops both are put right.
	local H = newWorld()
	H.login()
	local good = H.newPlate()
	H.showPlate("nameplate1", good)
	H.flush()
	local halves = {}
	for i = 1, 5 do
		halves[i] = H.newPlate({ breakLevel = true })
		H.showPlate("nameplate" .. (i + 1), halves[i])
	end
	check("half plate: the module is stopped at the fifth", H.ns.IsStopped("nameplates") and #H.out == 1, table.concat(H.out, "|"))
	local back = true
	for i = 1, 5 do
		back = back and H.state(halves[i].healthBar) == "hb" and halves[i].healthBar.bgTexture.alpha == 1
	end
	check("half plate: the outlines they had got are hidden when the module stops", back and plateLine(H, good) == OFF and #H.diff("nameplate") == 0, plateLine(H, good) .. " " .. table.concat(H.diff("nameplate"), "; "))
	H.out = {}
	local K = newWorld()
	K.login()
	local half = K.newPlate({ breakLevel = true })
	K.showPlate("nameplate1", half)
	K.flush()
	check("half plate: one failure is counted", has(K.status(), "Nameplates: on, 0 styled, 1 failed. "), K.line("Nameplates"))
	K.change("nameplates.enabled", false)
	check("half plate: switched off, the outline is hidden", K.state(half.healthBar) == "hb" and #K.diff("nameplate") == 0, K.state(half.healthBar))
end

-- 35. Aura icons: where the mask is found, notes about what is not found, the loss of control icon.
do
	local cases = {
		{ "the mask is found through the icon and the item does not list it", { maskNotListed = true } },
		{ "the mask is only listed by the item", { maskOnlyListed = true } },
		{ "the icon has no GetMaskTexture", { noGetMask = true, maskOnlyListed = true } },
		{ "GetMaskTexture raises", { maskFault = "error", maskOnlyListed = true } },
		{ "GetMaskTexture answers with a secret value", { maskFault = "secret", maskOnlyListed = true } },
		{ "the mask is found both ways", {} },
	}
	for _, case in ipairs(cases) do
		local W = newWorld()
		W.login()
		local plate = W.newPlate()
		local rec = W.addAura(plate, case[2])
		W.showPlate("nameplate1", plate)
		W.tick()
		check("aura mask: " .. case[1] .. ": the mask comes off and comes back", auraLine(rec) == AURA_ON and not has(W.status(), "mask was not found"), auraLine(rec) .. " " .. W.status())
		W.change("nameplates.auras", false)
		check("aura mask: " .. case[1] .. ": and the icon is restored", auraLine(rec) == AURA_OFF)
		clean(W, "aura mask")
	end
	-- Only the first mask of the icon is taken.
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	local rec = W.addAura(plate)
	local other = W.R(nil, "some-other-mask")
	rec.icon:AddMaskTexture(other)
	W.showPlate("nameplate1", plate)
	W.tick()
	check("aura mask: the first mask of the icon is the one taken off, another stays", rec.icon.masks[rec.mask] == nil and rec.icon.masks[other] == true)
	W.change("nameplates.auras", false)
	check("aura mask: and put back, the other untouched", rec.icon.masks[rec.mask] == true and rec.icon.masks[other] == true)

	-- Notes.
	local N = newWorld()
	N.login()
	local plateN = N.newPlate()
	N.addAura(plateN, { noOverlay = true })
	N.addAura(plateN, { noOverlay = true })
	N.showPlate("nameplate1", plateN)
	N.tick()
	local overlayNote = "Aura icons: the default frame was not found and is still shown."
	check("aura notes: an overlay that is not found is a line under the module line, once however many icons", has(N.status(), "Nameplates: on, 1 styled\n" .. overlayNote) and count(N.status(), overlayNote) == 1
		and not has(N.status(), "mask"), N.status())
	local M = newWorld()
	M.login()
	local plateM = M.newPlate()
	M.addAura(plateM, { noMask = true })
	M.addAura(plateM, { noMask = true })
	M.showPlate("nameplate1", plateM)
	M.tick()
	local maskNote = "Aura icons: the round mask was not found, so corners stay rounded."
	check("aura notes: and so is a mask that is not found", has(M.status(), "Nameplates: on, 1 styled\n" .. maskNote) and count(M.status(), maskNote) == 1 and not has(M.status(), overlayNote), M.status())
	local B = newWorld()
	B.login()
	local plateB = B.newPlate()
	B.addAura(plateB, { noMask = true, noOverlay = true })
	B.showPlate("nameplate1", plateB)
	B.tick()
	check("aura notes: both, in that order", has(B.status(), overlayNote .. "\n" .. maskNote), B.status())
	local G = newWorld()
	G.login()
	local plateG = G.newPlate()
	G.addAura(plateG)
	G.showPlate("nameplate1", plateG)
	G.tick()
	check("aura notes: none when both are found", not has(G.status(), "Aura icons"), G.status())
	local O = newWorld({ saved = { options = { ["nameplates.auras"] = false } } })
	O.login()
	local plateO = O.newPlate()
	O.addAura(plateO, { noMask = true, noOverlay = true })
	O.showPlate("nameplate1", plateO)
	O.tick()
	check("aura notes: none for icons that are not styled", not has(O.status(), "Aura icons"), O.status())
	O.change("nameplates.auras", true)
	O.tick()
	check("aura notes: until they are", has(O.status(), overlayNote) and has(O.status(), maskNote), O.status())

	-- The loss of control icon is not in the pool.
	local L = newWorld()
	L.login()
	local plateL = L.newPlate()
	local loc = L.addAura(plateL, { lossOfControl = true })
	local pooled = L.addAura(plateL)
	L.showPlate("nameplate1", plateL)
	check("loss of control: not before the next frame", auraLine(loc) == AURA_PLAIN)
	L.tick()
	check("loss of control: styled like the icons of the pool: cropped, mask off, overlay faded, thin border", auraLine(loc) == AURA_ON and auraLine(pooled) == AURA_ON and L.state(loc.item) == "Sb" and ringed(L, L.look(loc.item).anchor, 1))
	L.change("nameplates.auras", false)
	check("loss of control: restored with the others when the icons are switched off", auraLine(loc) == AURA_OFF and L.state(loc.item) == "hb")
	L.change("nameplates.auras", true)
	L.change("nameplates.enabled", false)
	check("loss of control: and when the module is switched off", auraLine(loc) == AURA_OFF and #L.diff("nameplate") == 0, table.concat(L.diff("nameplate"), "; "))
	L.change("nameplates.enabled", true)
	check("loss of control: and styled again", auraLine(loc) == AURA_ON)
	clean(L, "loss of control")
	-- Forbidden, secret and missing loss of control frames.
	local X = newWorld()
	X.login()
	local pf = X.newPlate()
	local forbiddenLoc = X.addAura(pf, { lossOfControl = true, forbidden = true })
	local ps = X.newPlate()
	ps.aurasInner.LossOfControlFrame = SECRET
	local pn = X.newPlate()
	pn.aurasInner.LossOfControlFrame = X.B(nil, {})
	X.showPlate("nameplate1", pf)
	X.showPlate("nameplate2", ps)
	X.showPlate("nameplate3", pn)
	X.tick()
	check("loss of control: a forbidden icon, a secret frame and a frame with no icon are skipped without a word", forbiddenLoc.icon.texCoord == nil and #X.violations == 0 and #X.out == 0 and not has(X.status(), "Aura icons"), X.status())

	-- UNIT_AURA with a unit the client withholds, and nothing known yet.
	local U = newWorld()
	U.login()
	U.flush()
	U.fire("UNIT_AURA", SECRET)
	check("secret unit: with no plate known nothing is queued", #U.timers == 0)
	local broken = U.newPlate({ breakTextures = true })
	U.showPlate("nameplate1", broken)
	U.flush()
	U.fire("UNIT_AURA", SECRET)
	check("secret unit: a plate that failed is not a known plate for this", #U.timers == 0)
end

-- 36. Action bars: one layout for each button, the icon mask, and a module that stops.
do
	-- However many art updates and changes there are while combat lasts, a button is laid out once when it ends.
	local W = newWorld({ combat = true })
	W.login()
	local parts = W.buttons.ActionButton1.parts
	for _ = 1, 4 do
		W.update("ActionButton1")
	end
	W.change("actionbars.crop", 12)
	W.change("actionbars.crop", 9)
	W.change("actionbars.backdrop", false)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	local pet = W.buttons.PetActionButton3.parts
	check("layout queue: each button is laid out once when combat ends, whatever happened meanwhile", parts.icon.calls.SetTexCoord == 1 and parts.icon.calls.RemoveMaskTexture == 1
		and parts.cooldown.calls.SetAllPoints == 1 and pet.icon.calls.SetTexCoord == 1, tostring(parts.icon.calls.SetTexCoord) .. " " .. tostring(pet.icon.calls.SetTexCoord))
	check("layout queue: with the options as they ended", texcoord(parts.icon) == "0.09,0.91,0.09,0.91" and W.state(parts.icon) == "Sb" and has(W.status(), "Action bars: on, 118 styled"), buttonLine(W, "ActionButton1"))
	clean(W, "layout queue")

	-- The mask of the icon comes back with Blizzard's rounded frame.
	local M = newWorld()
	M.login()
	local pp, other = M.buttons.ActionButton1.parts, M.buttons.MultiBarLeftButton1.parts
	check("mask: taken off at login", pp.icon.masks[pp.IconMask] == nil and other.icon.masks[other.IconMask] == nil)
	M.change("actionbars.square", false)
	check("mask: Square icons off puts it back at once, on every button", pp.icon.masks[pp.IconMask] == true and other.icon.masks[other.IconMask] == true)
	M.change("actionbars.square", true)
	check("mask: and on takes it off again, once", pp.icon.masks[pp.IconMask] == nil and pp.icon.calls.RemoveMaskTexture == 2 and pp.icon.calls.AddMaskTexture == 1,
		tostring(pp.icon.calls.RemoveMaskTexture) .. " " .. tostring(pp.icon.calls.AddMaskTexture))
	M.change("actionbars.main", false)
	check("mask: a group that is switched off gets it back, the others do not", pp.icon.masks[pp.IconMask] == true and other.icon.masks[other.IconMask] == nil)
	M.change("actionbars.main", true)
	check("mask: and taken off when the group is on again", pp.icon.masks[pp.IconMask] == nil)
	M.change("actionbars.enabled", false)
	local masked = 0
	for _, b in ipairs(ALL_BUTTONS) do
		local bp = M.buttons[b.name].parts
		if bp.icon.masks[bp.IconMask] == true then
			masked = masked + 1
		end
	end
	check("mask: with the module off all 118 buttons have it back", masked == 118, masked)
	M.change("actionbars.enabled", true)
	masked = 0
	for _, b in ipairs(ALL_BUTTONS) do
		local bp = M.buttons[b.name].parts
		if bp.icon.masks[bp.IconMask] == nil then
			masked = masked + 1
		end
	end
	check("mask: and none when it is on again", masked == 118, masked)
	clean(M, "mask")

	-- Buttons laid out before combat get Blizzard's art back at once when their group is switched off in combat.
	local I = newWorld()
	I.login()
	I.combat = true
	I.change("actionbars.pet", false)
	local ip = I.buttons.PetActionButton4.parts
	check("in combat: a group switched off gets Blizzard's art at once, though its buttons were laid out before", ip.NormalTexture.alpha == 1 and ip.SlotArt.alpha == 1 and ip.SlotBackground.alpha == 1
		and I.buttons.ActionButton1.parts.NormalTexture.alpha == 0 and texcoord(ip.icon) == "0.08,0.92,0.08,0.92", g(ip.NormalTexture.alpha))
	I.change("actionbars.pet", true)
	check("in combat: and the art is faded again at once when the group is switched on", ip.NormalTexture.alpha == 0 and ip.SlotArt.alpha == 0)
	I.combat = false
	I.fire("PLAYER_REGEN_ENABLED")
	check("in combat: and the layout of that group is done when combat ends", buttonLine(I, "PetActionButton4") == BUTTON_ON)

	-- A module that stops while layouts wait for combat to end.
	local S = newWorld({ combat = true })
	S.login()
	for i = 1, 5 do
		S.ns.Each("actionbars", function() error("bad", 0) end, "frame" .. i)
	end
	check("stopped while waiting: Blizzard's art is back at once", S.ns.IsStopped("actionbars") and buttonLine(S, "ActionButton1") == "art=1,1,1 tc=- ring=." and S.bar.BorderArt.alpha == 1)
	S.combat = false
	S.fire("PLAYER_REGEN_ENABLED")
	local laid = 0
	for _, b in ipairs(ALL_BUTTONS) do
		if buttonLine(S, b.name) ~= "art=1,1,1 tc=- ring=." then
			laid = laid + 1
		end
	end
	check("stopped while waiting: and nothing is laid out when combat ends", laid == 0 and S.holderOn(S.buttons.ActionButton1.parts.icon) == nil and #S.violations == 0, laid)

	-- A module that stops in combat, after the buttons were laid out.
	local T = newWorld()
	T.login()
	for i = 1, 5 do
		local inner = T.buttons["ActionButton" .. i].inner
		inner.SlotArt = nil
		setmetatable(inner, { __index = function(_, key)
			if key == "SlotArt" then
				error("SlotArt failed", 0)
			end
		end })
	end
	do
		-- One more button, whose icon cannot be reached by the time its layout is done.
		local inner = T.buttons.ActionButton7.inner
		local icon = inner.icon
		inner.icon = nil
		setmetatable(inner, { __index = function(_, key)
			if key == "icon" then
				error("icon failed", 0)
			end
		end })
	end
	T.combat = true
	T.change("actionbars.crop", 12)
	check("stopped in combat: five buttons that fail stop the module", T.ns.IsStopped("actionbars") and #T.out == 1 and has(T.status(), "Action bars: stopped. SlotArt failed"), table.concat(T.out, "|") .. T.line("Action bars"))
	check("stopped in combat: the art of the others is back at once", T.buttons.ActionButton6.parts.NormalTexture.alpha == 1 and T.buttons.StanceButton3.parts.SlotArt.alpha == 1 and T.bar.BorderArt.alpha == 1)
	T.combat = false
	T.fire("PLAYER_REGEN_ENABLED")
	local left = {}
	for _, b in ipairs(ALL_BUTTONS) do
		local number = tonumber(b.name:match("^ActionButton(%d+)$"))
		if not (number and (number <= 5 or number == 7)) and buttonLine(T, b.name) ~= BUTTON_OFF then
			left[#left + 1] = b.name .. "=" .. buttonLine(T, b.name)
		end
	end
	check("stopped in combat: when combat ends their icons are whole, their outlines hidden and their masks back", #left == 0 and T.buttons.ActionButton6.parts.icon.masks[T.buttons.ActionButton6.parts.IconMask] == true,
		table.concat(left, "; "):sub(1, 200))
	check("stopped in combat: a layout that fails then is no error of anybody's", #T.errors == 0 and #T.violations == 0, table.concat(T.errors, "|"))
end

-- 37. Options: a client without AddEvaluateStateCVar, and the Defaults button on an open panel.
do
	local W = newWorld({ noEvaluateCVar = true })
	W.login()
	check("options: a client without AddEvaluateStateCVar: every control is built with its predicates and nothing raises", #W.controls == COUNT.controls and #W.errors == 0 and #W.violations == 0
		and #W.control("nameplates.targetColour").predicates == 3 and #W.control("nameplates.targetColour").cvars == 0)
	local V = newWorld()
	V.login()
	V.openPanel()
	V.change("general.scaleOn", true)
	check("options: ticking Custom UI scale makes the slider usable at once", V.enabled("general.scale") and V.shown("general.scaleOn") == true)
	V.defaults()
	check("options: Defaults on the open panel greys the slider again and unticks the box", not V.enabled("general.scale") and V.shown("general.scaleOn") == false and not V.ns.Get("general.scaleOn"))
	V.change("nameplates.enabled", false)
	check("options: switching a page off greys its controls while the panel is open", not V.enabled("nameplates.health") and not V.enabled("nameplates.targetColour") and V.enabled("nameplates.enabled"))
	V.defaults()
	check("options: and Defaults makes them usable again", V.enabled("nameplates.health") and V.enabled("nameplates.targetColour") and V.ns.Get("nameplates.enabled") == true)
	V.change("nameplates.health", false)
	check("options: a setting in the middle of a chain greys what hangs from it, two levels down", not V.enabled("nameplates.target") and not V.enabled("nameplates.targetColour") and V.enabled("nameplates.level"))
	clean(V, "options")
end

-- 20. Every setting, changed through its control: what the frames look like, and back again.
local function scene(saved, more)
	local world = { saved = saved }
	for key, value in pairs(more or {}) do
		world[key] = value
	end
	-- A world with combat numbers shows every hit unless a probe asks for Whose hits itself: its probes are about the numbers.
	if world.worldText then
		local options = {}
		for key, value in pairs(saved and saved.options or {}) do
			options[key] = value
		end
		if options["combattext.whose"] == nil then
			options["combattext.whose"] = "all"
		end
		if options["combattext.group"] == nil then
			options["combattext.group"] = "flat"
		end
		-- The tests of numbers over enemies keep the scroll area out of the way; the tests of the areas ask for Both or Scroll area.
		if options["combattext.where"] == nil then
			options["combattext.where"] = "over"
		end
		local kept = {}
		for key, value in pairs(saved or {}) do
			kept[key] = value
		end
		kept.options = options
		world.saved = kept
	end
	local W = newWorld(world)
	W.login()
	local S = { W = W }
	S.t, S.f, S.o = W.newPlate(), W.newPlate(), W.newPlate()
	S.ta, S.fa, S.oa = W.addAura(S.t), W.addAura(S.f), W.addAura(S.o)
	W.showPlate("nameplate1", S.t)
	W.showPlate("nameplate2", S.f)
	W.showPlate("nameplate3", S.o)
	W.units.target, W.units.focus = S.t, S.f
	W.fire("PLAYER_TARGET_CHANGED")
	W.updateDividers()
	S.div = W.bar.hRaw.items[1]
	W.flush()
	-- The frame of the action bars that fades the dividers looks at them.
	for _, frame in ipairs(W.eventFrames) do
		if frame.dividers and frame.onUpdate then
			frame.onUpdate(frame, 0.3)
		end
	end
	-- A hit report over a friendly nameplate (nameplate1 is a friendly unit): time moves on first, so the same hit is not taken for a second token's.
	S.fhit = function(unit, event, flag, amount, school, later)
		W.now = W.now + 1
		W.attackable.nameplate1 = false
		return S.hit(unit or "nameplate1", event, flag, amount, school, later)
	end
	-- A hit report for a nameplate unit: the font string that now shows it, or nil when nothing was shown. `later` moves time on and draws a frame.
	S.hit = function(unit, event, flag, amount, school, later)
		local before = {}
		for index, font in ipairs(W.addonFonts) do
			before[index] = font.calls.Show or 0
		end
		W.fire("UNIT_COMBAT", unit or "nameplate1", event or "WOUND", flag or "", amount or 412, school or 1)
		local shown
		for index, font in ipairs(W.addonFonts) do
			if (font.calls.Show or 0) > (before[index] or 0) then
				shown = font
			end
		end
		if shown and later then
			W.now = W.now + later
			for _, frame in ipairs(W.eventFrames) do
				if frame.onUpdate then
					frame.onUpdate(frame, 0)
				end
			end
		end
		return shown
	end
	return S
end
local function ring(S, target)
	return rgb(S.W.look(target))
end
local function thick(S, target)
	return g(S.W.look(target).thick)
end
local function backColour(S, target)
	local c = S.W.backdropOn(target).color
	return string.format("%.3f,%.3f,%.3f,%s", c[1], c[2], c[3], g(c[4]))
end
local function art(S, p)
	return g(p.healthBar.bgTexture.alpha) .. S.W.state(p.healthBar)
end
local function swingLine(S, name)
	local parts = S.W.swing[name]
	return tostring(parts.Border.shown) .. S.W.state(parts.StatusBar)
end
local function swingAll(S)
	return swingLine(S, "SwingTimerMainHandFrame") .. "/" .. swingLine(S, "SwingTimerOffHandFrame") .. "/" .. swingLine(S, "SwingTimerRangedFrame")
end
local function resLine(S, key)
	return g(S.W.prd[key][2].regions[1].alpha) .. S.W.state(S.W.prd[key][1])
end
local function resAll(S)
	return resLine(S, "health") .. "/" .. resLine(S, "power") .. "/" .. resLine(S, "alt")
end
local function castLine(S, name)
	local c = S.W.cast[name]
	return g(c.parts.Border.alpha) .. S.W.state(c.bar)
end
local function castSize(S, name)
	local c = S.W.cast[name].inner
	return g(c.width) .. "x" .. g(c.height)
end
local function btn(S, name)
	return buttonLine(S.W, name)
end
local BTN_ON, BTN_OFF = BUTTON_ON, BUTTON_OFF
-- The simulated client has no window frames, so a setting of the Windows page is read as the addon holds it
-- and as its control shows it.
local function held(path)
	return function(S) return tostring(S.W.ns.Get(path)) .. "/" .. tostring(S.W.read(path)) end
end
