			to = not row.default
			base, changed = tostring(row.default) .. "/" .. tostring(row.default), tostring(to) .. "/" .. tostring(to)
		elseif row.kind == "number" then
			to = row.default ~= row.max and row.max or row.min
			base, changed = ("%g/%g"):format(row.default, row.default), ("%g/%g"):format(to, to)
		elseif row.kind == "colour" then
			to = "ff336699"
			base, changed = row.default .. "/" .. row.default, to .. "/" .. to
		else
			local labelOf = {}
			for _, choice in ipairs(row.choices) do
				labelOf[choice[1]] = choice[2]
			end
			local other
			for _, choice in ipairs(row.choices) do
				if choice[1] ~= row.default then
					other = choice
					break
				end
			end
			to, from = other[2], labelOf[row.default]
			base, changed = row.default .. "/" .. from, other[1] .. "/" .. other[2]
		end
		local probe = { path, to, held(path), base, changed, from = from }
		if row.needs then
			local need = true
			if row.needsIn then
				need = row.needsIn[1]
				for _, choice in ipairs(ROW[row.needs].choices or {}) do
					if choice[1] == need then
						need = choice[2]
					end
				end
			end
			probe.pre = { { row.needs, need } }
		end
		PROBES[#PROBES + 1] = probe
	end
local covered = {}
for _, P in ipairs(PROBES) do
	local path, to, read, base, changed = P[1], P[2], P[3], P[4], P[5]
	covered[path] = true
	local row = ROW[path]
	local S = scene(P.saved, P.world)
	local W = S.W
	for _, pair in ipairs(P.pre or {}) do
		W.change(pair[1], pair[2])
		W.flush()
	end
	local label = path .. (type(to) == "string" and (" " .. to) or "")
	local start = read(S)
	check(label .. ": at the start", start == base, start)
	W.change(path, to)
	W.flush()
	local now = read(S)
	check(label .. ": through its control", now == changed, now)
	if not P.oneWay then
		W.change(path, P.from or row.default)
		W.flush()
		local back = read(S)
		check(label .. ": and back", back == (P.back or base), back)
	end
	check(label .. ": no violations, errors or messages", #W.violations == 0 and #W.errors == 0 and #W.out == 0, table.concat(W.violations, "|") .. table.concat(W.out, "|"))
end
