-- 10b. Every area off at once, then on again: Blizzard's art exactly, and nothing made twice.
do
	local S = scene()
	local W = S.W
	local frames, textures = #W.addonFrames, #W.addonTextures
	for _, area in ipairs(AREAS) do
		W.change(area .. ".enabled", false)
	end
	W.flush()
	local groups = { "nameplate", "resource", "swing", "castbars", "actionbar" }
	local left = {}
	for _, group in ipairs(groups) do
		for _, line in ipairs(W.diff(group)) do
			if not (line:find(" masks: ", 1, true) or line:find(" color: ", 1, true) or line:find(" allPoints: ", 1, true) or line:find(" points: ", 1, true) or line:find(" atlas: ", 1, true)) then
				left[#left + 1] = group .. " " .. line
			end
		end
	end
	check("all areas off: everything Blizzard drew has its alpha, visibility and texture coordinates back", #left == 0, table.concat(left, "; "):sub(1, 400))
	local shownEdges = 0
	for _, t in ipairs(W.addonTextures) do
		if t.shown and (t.layer == "OVERLAY" or t.layer == "BACKGROUND") then
			shownEdges = shownEdges + 1
		end
	end
	check("all areas off: no outline and no backdrop of the addon's is shown", shownEdges == 0, shownEdges)
	local cleared = 0
	for _, t in ipairs(W.addonTextures) do
		if t.calls.ClearAllPoints then
			cleared = cleared + 1
		end
	end
	check("the addon's textures were never cleared of their points, whatever was changed", cleared == 0, cleared)
	check("all areas off: status: the head, then each module off, and no module on", (function()
		local wanted = { TOC.head(1) }
		for _, module in ipairs(TOC.modules(W)) do
			wanted[#wanted + 1] = module.label .. ": off"
		end
		local ok, line = TOC.inOrder(TOC.lines(W.status()), wanted)
		return ok and not has(W.status(), ": on") or line
	end)() == true, W.status())
	for _, area in ipairs(AREAS) do
		W.change(area .. ".enabled", true)
	end
	W.flush()
	check("all areas on again: nothing made twice", #W.addonFrames == frames and #W.addonTextures == textures, #W.addonFrames .. "/" .. frames .. " " .. #W.addonTextures .. "/" .. textures)
	check("all areas on again: styled as before", art(S, S.o) == "0SB" and btn(S, "ActionButton1") == BUTTON_ON and resLine(S, "health") == "0SB" and swingLine(S, "SwingTimerMainHandFrame") == "falseSB"
		and castLine(S, "TargetFrameSpellBar") == "0SB" and auraLine(S.oa) == AURA_ON and ring(S, S.t.healthBar) == "1.00,1.00,1.00" and S.div.alpha == 0)
	check("all areas on again: status", has(W.status(), "Nameplates: on, 3 styled") and has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Personal resource display: on, 3 styled")
		and has(W.status(), "Swing timers: on, 3 styled") and has(W.status(), "Cast bars: on, 5 styled") and has(W.status(), "Windows: on, 0 styled"), W.status())
	clean(W, "all areas")
end



-- 38. Windows: the simulated client builds the windows the way Blizzard's XML does.
-- (Windows are built only in a world that asks for them, so every section above runs as before.)
local function winWorld(extra, saved)
	local W = newWorld({ windows = extra or true, saved = saved })
	W.login()
	W.flush()
	return W
end
local function wraw(W, x) return W.rawOf[x] end
local function wglobal(W, name) return W.env[name] end
-- The alpha of a Blizzard region or frame.
local function wa(W, x) return W.rawOf[x].alpha end
-- Addon textures and lines owned by a frame, in creation order.
local function wowned(W, owner)
	local out = {}
	for _, t in ipairs(W.addonTextures) do
		if t.owner == owner then
			out[#out + 1] = t
		end
	end
	return out
end
-- The invisible rectangles ("boxes") the addon made on a frame as outline targets: BACKGROUND, sublevel -8, clear.
local function wboxes(W, owner)
	local out = {}
	for _, t in ipairs(wowned(W, owner)) do
		if t.layer == "BACKGROUND" and t.sublevel == -8 and t.color and t.color[4] == 0 and not t.allPoints then
			out[#out + 1] = t
		end
	end
	return out
end
-- Flat colour textures the addon put on a frame in one layer.
local function wtints(W, owner, layer)
	local out = {}
	for _, t in ipairs(wowned(W, owner)) do
		if t.layer == layer and t.kind ~= "Line" and t.color and not (t.sublevel == -8) and t.sublevel ~= 7 then
			out[#out + 1] = t
		end
	end
	return out
end
local function wlines(W, owner, layer)
	local out = {}
	for _, t in ipairs(wowned(W, owner)) do
		if t.kind == "Line" and (layer == nil or t.layer == layer) then
			out[#out + 1] = t
		end
	end
	return out
end
local function wfill(W, target)
	local back = W.backdropOn(target)
	return back and back.color
end
local function wcolour(c)
	return c and string.format("%.3f,%.3f,%.3f,%s", c[1], c[2], c[3], g(c[4])) or "none"
end
local WINDOW_FILL = "0.059,0.059,0.059,0.8"
local PANEL_FILL = "0.118,0.118,0.118,1"
-- Every Blizzard frame and region of the windows against the state the client built them in.
local function wdiff(W, skip)
	local left = {}
	for _, line in ipairs(W.diff("windows")) do
		local keep = true
		for _, pattern in ipairs(skip or {}) do
			if line:find(pattern, 1, true) then
				keep = false
			end
		end
		if keep then
			left[#left + 1] = line
		end
	end
	return left
end
-- What the addon did to the Blizzard side of the windows: calls that only a frame-level change would make.
local function wtouched(W)
	local frames, regions = {}, {}
	for _, f in ipairs(W.blizzFrames) do
		if f.group == "windows" and (f.calls.SetAlpha or f.calls.Show or f.calls.Hide or f.alpha ~= (f.sealed and tonumber(f.sealed.alpha) or f.alpha)) then
			frames[#frames + 1] = tostring(f.fname)
		end
	end
	for _, r in ipairs(W.blizzRegions) do
		if r.group == "windows" and (r.calls.Show or r.calls.Hide or r.calls.SetShown) then
			regions[#regions + 1] = tostring(r.fname)
		end
	end
	return frames, regions
end

do
