		if wraw(W, c.NineSlice)[name] ~= nil then
			pieces = pieces + 1
		end
	end
	check("windows world: the NineSlice has its eight pieces by field name", pieces == 8, pieces)
	check("windows world: six mode tabs, four sidebar tabs, twenty item slots", #wraw(W, c.ModeTabs).Tabs == 6 and names.PaperDollSidebarTab4 ~= nil and names.CharacterAmmoSlot ~= nil
		and #W.win.SLOTS == 19)
