	check("windows world: a sidebar tab is a CheckButton with an unkeyed ring and a Selected checked texture", wraw(W, names.PaperDollSidebarTab1).GetCheckedTexture ~= nil
		and wraw(W, names.PaperDollSidebarTab1).GetNormalTexture() == nil and W.rawOf[wraw(W, names.PaperDollSidebarTab1).GetCheckedTexture()].atlas == "UI-Character-Info-StatTab-Selected")
	check("windows world: the ammo slot's NormalTexture has no key, the other slots' has", wraw(W, names.CharacterAmmoSlot).NormalTexture == nil and wraw(W, names.CharacterHeadSlot).NormalTexture ~= nil
		and wraw(W, names.CharacterAmmoSlot).GetNormalTexture() ~= nil)
	check("windows world: a Blizzard frame rejects a field written by the addon", (function()
		local ok = pcall(function() cf.AddonField = 1 end)
		return not ok and #W.violations == 1
	end)())
	W.violations = {}
	W.login()
	W.flush()
	check("windows world: the module styled the windows without a violation, an error or a message", #W.violations == 0 and #W.errors == 0 and #W.out == 0)
	local frames, regions = wtouched(W)
	check("windows world: no Blizzard frame had its alpha, visibility or Show and Hide touched", #frames == 0, table.concat(frames, " "))
	check("windows world: no Blizzard region was shown or hidden by the addon", #regions == 0, table.concat(regions, " "))
end

-- 39. Window frames: eight pieces, Bg, streaks and portrait are faded; the addon's outline and window fill replace them.
do
	local W = winWorld()
	local names = W.win.names
	for _, name in ipairs({ "CharacterFrame", "FriendsFrame", "MerchantFrame", "MailFrame", "OpenMailFrame", "GossipFrame", "QuestFrame" }) do
		local frame = names[name]
		local r = wraw(W, frame)
		check(name .. ": an outline with the window fill replaces the border art", W.state(frame) == "SB" and wcolour(wfill(W, frame)) == WINDOW_FILL, wcolour(wfill(W, frame)))
		local ring, why = ringOf(W, frame, 1, 0, 0, 0)
		check(name .. ": the outline is one pixel and black", ring, why)
		local nine, faded = wraw(W, r.NineSlice), 0
		for _, piece in ipairs({ "TopLeftCorner", "TopRightCorner", "BottomLeftCorner", "BottomRightCorner", "TopEdge", "BottomEdge", "LeftEdge", "RightEdge" }) do
			faded = faded + (wa(W, nine[piece]) == 0 and 1 or 0)
		end
		check(name .. ": all eight NineSlice pieces are transparent", faded == 8, faded)
		check(name .. ": the NineSlice frame itself keeps its alpha", wa(W, r.NineSlice) == 1)
		check(name .. ": the Bg and the top streaks are transparent", name == "CharacterFrame" or (wa(W, r.Bg) == 0 and wa(W, r.TopTileStreaks) == 0))
		check(name .. ": the portrait is transparent, its mask and the title are not touched", wa(W, wraw(W, r.PortraitContainer).portrait) == 0 and wa(W, wraw(W, r.PortraitContainer).CircleMask) == 1
			and wa(W, wraw(W, r.TitleContainer).TitleText) == 1 and wa(W, r.FrameGlow) == 1)
		check(name .. ": the outline hangs from the window itself", W.holderOn(frame) ~= nil and W.holderOn(frame).parent == frame)
	end
	local friends = wraw(W, names.FriendsFrame)
	local inset = friends.Inset
	check("an inset: its Bg and eight pieces are transparent and it gets no outline of its own", wa(W, wraw(W, inset).Bg) == 0 and wa(W, wraw(W, wraw(W, inset).NineSlice).TopEdge) == 0
		and wa(W, wraw(W, wraw(W, inset).NineSlice).BottomRightCorner) == 0 and W.state(inset) == ".")
	check("an inset: its NineSlice frame keeps its alpha", wa(W, wraw(W, inset).NineSlice) == 1)
	local fills = {}
	for _, name in ipairs({ "CharacterFrame", "FriendsFrame", "MerchantFrame", "MailFrame", "OpenMailFrame", "GossipFrame", "QuestFrame" }) do
		fills[#fills + 1] = tostring(W.holderOn(names[name]) ~= nil)
	end
	check("window frames: seven windows and no more outlines with the window fill", count(table.concat(fills, ","), "true") == 7)
	-- The window outline is the first thing styled on a window: it is made before its children are looked at.
	check("a window's outline sits on the BACKGROUND layer at the lowest sublevel, under its other art", W.backdropOn(names.FriendsFrame).sublevel == -8)
	local frames, regions = wtouched(W)
	check("window frames: no Blizzard frame was faded, shown or hidden", #frames == 0 and #regions == 0, table.concat(frames, " ") .. table.concat(regions, " "))
	clean(W, "window frames")
end


-- A region of a frame by the atlas it draws (the raw region), found the way the addon finds an unkeyed one.
local function wregion(W, frame, atlas)
	for _, region in ipairs(wraw(W, frame).regions) do
		local r = W.rawOf[region]
		if r.atlas == atlas then
			return region, r
		end
	end
end
-- Where a line starts and ends relative to the middle of its target, in whole numbers of tenths of a unit.
local function wsegment(line)
	local s, e = line.start, line.stop
	return string.format("%g,%g>%g,%g", s[3], s[4], e[3], e[4])
end
local function wsegments(lines)
	local out = {}
	for _, line in ipairs(lines) do
		out[#out + 1] = wsegment(line)
	end
	return table.concat(out, " ")
end
local X_SHAPE = "-5,5>5,-5 -5,-5>5,5"
local LEFT_SHAPE = "2.5,5>-2.5,0 -2.5,0>2.5,-5"
local RIGHT_SHAPE = "-2.5,5>2.5,0 2.5,0>-2.5,-5"
local UP_SHAPE = "-3,-1.5>0,1.5 0,1.5>3,-1.5"
local DOWN_SHAPE = "-3,1.5>0,-1.5 0,-1.5>3,1.5"
local ACCENT = "0.851,0.851,0.851,1"
local function wc(c)
	return c and string.format("%.3f,%.3f,%.3f,%s", c[1], c[2], c[3], g(c[4])) or "none"
end

-- 40. Close buttons: the four state textures are transparent and a cross is drawn with lines; the Character pane toggle is a chevron.
do
	local W = winWorld()
	local names = W.win.names
	for _, name in ipairs({ "CharacterFrameCloseButton", "FriendsFrameCloseButton", "MerchantFrameCloseButton", "MailFrameCloseButton", "OpenMailFrameCloseButton",
		"GossipFrameCloseButton", "QuestFrameCloseButton" }) do
		local button = names[name]
		local states = wraw(W, button).states
		local alphas = {}
		for _, which in ipairs({ "Normal", "Pushed", "Disabled", "Highlight" }) do
			alphas[#alphas + 1] = g(wa(W, states[which]))
		end
		check(name .. ": Normal, Pushed, Disabled and Highlight are transparent", table.concat(alphas, ",") == "0,0,0,0", table.concat(alphas, ","))
		check(name .. ": no box and no fill, only a cross", W.state(button) == "." and #wtints(W, button, "HIGHLIGHT") == 0 and #wtints(W, button, "OVERLAY") == 0)
		local over, hover = wlines(W, button, "OVERLAY"), wlines(W, button, "HIGHLIGHT")
		check(name .. ": a white cross of two lines at 0.6, 1.5 thick, 10 by 10", #over == 2 and wsegments(over) == X_SHAPE and wc(over[1].color) == "1.000,1.000,1.000,0.6"
			and over[1].thickness == 1.5 and over[2].thickness == 1.5 and over[1].start[2] == button and over[1].start[1] == "CENTER", wsegments(over))
		check(name .. ": the same cross in the highlight colour on the HIGHLIGHT layer", #hover == 2 and wsegments(hover) == X_SHAPE and wc(hover[1].color) == ACCENT and over[1].shown and hover[1].shown)
		check(name .. ": the lines are above the art: sublevel 2", over[1].sublevel == 2 and hover[1].sublevel == 2)
	end
	-- The Looking For Group close button has no key; it is found by its name.
