	W.win.collapse(true, cf)
	check("pane toggle: the lines are moved, never made again", #wlines(W, toggle) == 4)
	check("pane toggle: its lines are redrawn without an outline or fill", W.state(toggle) == "." and #wtints(W, toggle, "HIGHLIGHT") == 0)
	-- The chevron follows the update even when the pane is shown by something else than the toggle.
	W.blizzard(function() wraw(W, wraw(W, cf).RightPaneHost).shown = true cf:UpdateRightPaneToggleButton() end)
	W.fireScript(wraw(W, cf).RightPaneHost, "OnShow")
	W.flush()
	check("pane toggle: it follows the pane's visibility, not the collapsed flag", wsegments(wlines(W, toggle, "OVERLAY")) == LEFT_SHAPE)
	clean(W, "pane toggle")
end

-- 41. Push buttons: the face is transparent, a box with a thin border replaces it, and what is not a push button is left alone.
do
	local W = winWorld({ extras = true })
	local names = W.win.names
	for _, name in ipairs({ "FriendsFrameAddFriendButton", "FriendsFrameSendMessageButton" }) do
		do
			local button = names[name]
			local r = wraw(W, button)
			check(name .. ": Left, Middle, Right and the Highlight slot are transparent", wa(W, r.Left) == 0 and wa(W, r.Middle) == 0 and wa(W, r.Right) == 0 and wa(W, r.states.Highlight) == 0)
			check(name .. ": a box with the button colour and a one pixel border", W.state(button) == "SB" and wcolour(wfill(W, button)) == PANEL_FILL and ringOf(W, button, 1, 0, 0, 0))
			local tint = wtints(W, button, "HIGHLIGHT")
			check(name .. ": a highlight over the whole face in the highlight colour at a quarter", #tint == 1 and wc(tint[1].color) == "0.851,0.851,0.851,0.25" and tint[1].allPoints == button)
			check(name .. ": the label is not touched", wa(W, r.Text) == 1)
		end
	end
	-- The three-slice button: Left, Center and Right instead of Left, Middle and Right.
	local equip = names.PaperDollEquipmentManagerPaneEquipSet
	local e = wraw(W, equip)
	check("three-slice button: Left, Center, Right and the Highlight slot are transparent, a box replaces them", wa(W, e.Left) == 0 and wa(W, e.Center) == 0 and wa(W, e.Right) == 0
		and wa(W, e.states.Highlight) == 0 and W.state(equip) == "SB")
	check("three-slice button: the Controller child is left alone", wa(W, wraw(W, e.Controller)) == 1 and #wowned(W, e.Controller) == 0)
	local renown = wraw(W, names.ReputationDetailFrame).ViewRenownButton
	check("three-slice button: one inside a pane is found too", W.state(renown) == "SB" and wa(W, wraw(W, renown).Center) == 0)
	-- Mistaken for a button: a tab (has Left, Middle, Right and LeftActive), a text box (HighlightText), a button with no Middle.
	local tab = names.FriendsFrameTab1
	check("not a push button: a tab gets no box on the whole button", W.state(tab) == "." and #wboxes(W, tab) == 1)
	local edit = names.SendMailNameEditBox
	check("not a push button: a text box gets no outline of its own", W.state(edit) == "." and #wtints(W, edit, "HIGHLIGHT") == 0)
	local half = W.win.halfButton
	check("not a push button: Left and Right with a label and no Middle is left as it is", W.state(half) == "." and wa(W, wraw(W, half).Left) == 1 and wa(W, wraw(W, half).Right) == 1)
	local drop = names.FriendsFrameStatusDropdown
	check("not a push button: a dropdown is a dropdown", wa(W, wraw(W, drop).Background) == 0 and #wlines(W, drop, "OVERLAY") == 2)
	-- Window panes inside the character window keep their own look: their buttons are found as well.
	check("push buttons: the Back and Post buttons are not in this world until the addon is loaded", W.env.LFGListingFrameBackButton == nil)
	clean(W, "push buttons")
end

-- 42. Tabs: the nine textures are transparent whatever Blizzard shows, and a box with the button colour replaces them.
do
	local W = winWorld({ extras = true })
	local names = W.win.names
	local tab = names.FriendsFrameTab1
	local t = wraw(W, tab)
	local alphas = {}
	for _, region in ipairs(t.TabTextures) do
		alphas[#alphas + 1] = g(wa(W, region))
	end
	check("tab: all nine textures of TabTextures are transparent, including the three highlights", table.concat(alphas, ",") == "0,0,0,0,0,0,0,0,0", table.concat(alphas, ","))
	local boxes = wboxes(W, tab)
	check("tab: one box, three units in on each side, one down from the top, three up from the bottom", #boxes == 1 and boxes[1].points[1][1] == "TOPLEFT" and boxes[1].points[1][4] == 3 and boxes[1].points[1][5] == -1
		and boxes[1].points[2][1] == "BOTTOMRIGHT" and boxes[1].points[2][4] == -3 and boxes[1].points[2][5] == 3 and boxes[1].points[1][2] == tab, #boxes)
	check("tab: the box has the button colour and a thin black border, and the tab itself has no outline", W.state(boxes[1]) == "SB" and wcolour(wfill(W, boxes[1])) == PANEL_FILL and ringOf(W, boxes[1], 1, 0, 0, 0) and W.state(tab) == ".")
	local hover = wtints(W, tab, "HIGHLIGHT")
	check("tab: a quarter-strength highlight over the box", #hover == 1 and hover[1].allPoints == boxes[1] and wc(hover[1].color) == "0.851,0.851,0.851,0.25")
	check("tab: the label is not touched", wa(W, t.Text) == 1)
	-- Blizzard selects and deselects tabs by showing and hiding regions. That changes no alpha.
	W.blizzard(function()
		wraw(W, t.Left).shown, wraw(W, t.Middle).shown, wraw(W, t.Right).shown = false, false, false
		wraw(W, t.LeftActive).shown, wraw(W, t.MiddleActive).shown, wraw(W, t.RightActive).shown = true, true, true
	end)
	check("tab: Blizzard shows the active trio and hides the plain one; all nine are still transparent", wa(W, t.LeftActive) == 0 and wa(W, t.MiddleActive) == 0 and wa(W, t.Left) == 0 and wa(W, t.RightHighlight) == 0)
	-- The same box for every tab, selected or not.
	local second = names.FriendsFrameTab3
	check("tab: the box does not depend on which tab is selected", #wboxes(W, second) == 1 and wboxes(W, second)[1].points[1][4] == 3)
	-- A tab of a TabSystem: the nine in RotatedTextures and the square art.
	local system = names.FlatUITestSystemTab
	local s = wraw(W, system)
	local list = {}
	for _, region in ipairs(s.RotatedTextures) do
		list[#list + 1] = g(wa(W, region))
	end
	check("tab of a TabSystem: RotatedTextures are transparent", #list == 9 and table.concat(list, ",") == "0,0,0,0,0,0,0,0,0", table.concat(list, ","))
	check("tab of a TabSystem: the three square backgrounds are transparent, the icon and its mask are not", wa(W, s.SquareBackground) == 0 and wa(W, s.SquareBackgroundActive) == 0 and wa(W, s.SquareBackgroundActiveGlow) == 0
		and wa(W, s.Icon) == 1 and wa(W, s.IconMask) == 1)
	check("tab of a TabSystem: the same box", #wboxes(W, system) == 1)
	clean(W, "tabs")
end


-- The texture coordinates of a region as "l,r,t,b".
local function wtc(W, region)
	local c = W.rawOf[region].texCoord
	local text = c and table.concat(c, ",") or "-"
	return text == "0,1,0,1" and "-" or text
end
local function wmasked(W, icon, mask)
	return W.rawOf[icon].masks[mask] == true
end

-- 43. Side tabs: a square icon with a thin border, the selected tab marked by Blizzard's SetChecked, and the sidebar tabs of the character window.
do
	local W = winWorld()
	local names = W.win.names
	for index = 1, 6 do
		local tab = names["CharacterFrameModeTab" .. index]
		local t = wraw(W, tab)
		local label = "mode tab " .. index
		check(label .. ": Background, SelectedTexture and HighlightTexture are transparent", wa(W, t.Background) == 0 and wa(W, t.SelectedTexture) == 0 and wa(W, t.HighlightTexture) == 0)
		check(label .. ": TabGlow is left to its animation: never written", wa(W, t.TabGlow) == 0 and not wraw(W, t.TabGlow).calls.SetAlpha)
		check(label .. ": the icon is cropped to 8 percent on each side of the rectangle Blizzard left it", wtc(W, t.Icon) == "0.10625,0.89375,0.10625,0.89375", wtc(W, t.Icon))
		check(label .. ": the icon no longer has its mask, the mask is left in place", not wmasked(W, t.Icon, t.Mask) and wa(W, t.Mask) == 1)
		check(label .. ": a box with the button colour around the icon, not around the tab", W.state(t.Icon) == "SB" and wcolour(wfill(W, t.Icon)) == PANEL_FILL and W.state(tab) == "." and ringOf(W, t.Icon, 1, 0, 0, 0))
		local hover = wtints(W, tab, "HIGHLIGHT")
		check(label .. ": a white hover tint over the icon, added to the colours underneath", #hover == 1 and hover[1].allPoints == t.Icon and hover[1].blend == "ADD" and wc(hover[1].color) == "1.000,1.000,1.000,0.3")
		local selected = wtints(W, tab, "OVERLAY")
		check(label .. ": a white selected tint over the icon, shown only for the selected tab", #selected == 1 and selected[1].allPoints == t.Icon and selected[1].blend == "ADD" and selected[1].shown == (index == 1))
	end
	-- Blizzard selects another tab: SetChecked shows its own SelectedTexture and resets the icon's coordinates and size.
	local cf = names.CharacterFrame
	local tab3 = wraw(W, names.CharacterFrameModeTab3)
	W.win.choose(3, cf)
	check("side tab: SetChecked(true) from Blizzard: the selected tint of the third tab is shown", wowned(W, names.CharacterFrameModeTab3) and wtints(W, names.CharacterFrameModeTab3, "OVERLAY")[1].shown)
	check("side tab: and the first tab's selected tint is hidden", not wtints(W, names.CharacterFrameModeTab1, "OVERLAY")[1].shown)
	check("side tab: Blizzard reset the icon to 0.03125 and 50 by 50, the crop is back and the icon is the 30 by 30 of Small", wtc(W, tab3.Icon) == "0.10625,0.89375,0.10625,0.89375" and wraw(W, tab3.Icon).width == 30 and wraw(W, tab3.Icon).height == 30, wtc(W, tab3.Icon))
	do
		-- With Game's size the icon is left at the 50 by 50 Blizzard sets.
		local G = winWorld(nil, { options = { ["windows.sideTabSize"] = "game" } })
		local game = wraw(G, G.win.names.CharacterFrameModeTab3)
		G.win.choose(3, G.win.names.CharacterFrame)
		check("side tab: Game's size: Blizzard reset the icon to 50 by 50 and the crop is back", wtc(G, game.Icon) == "0.10625,0.89375,0.10625,0.89375" and wraw(G, game.Icon).width == 50 and wraw(G, game.Icon).height == 50, wtc(G, game.Icon))
	end
	check("side tab: Blizzard's own SelectedTexture is shown and stays transparent", wraw(W, tab3.SelectedTexture).shown and wa(W, tab3.SelectedTexture) == 0)
	-- The player's portrait on the first tab is set again by Blizzard from time to time.
	local tab1 = wraw(W, names.CharacterFrameModeTab1)
	W.win.portrait(cf)
	check("side tab: the portrait tab is cropped again after Blizzard sets its portrait", wtc(W, tab1.Icon) == "0.10625,0.89375,0.10625,0.89375", wtc(W, tab1.Icon))
	-- The hook is on the tab itself, and only on the tabs styled: another frame's SetChecked changes nothing.
	W.win.choose(1, cf)
	check("side tab: and back to the first tab", wtints(W, names.CharacterFrameModeTab1, "OVERLAY")[1].shown and not wtints(W, names.CharacterFrameModeTab3, "OVERLAY")[1].shown)
	-- A checked value that is not a boolean is taken as true or false.
	W.blizzard(function() names.CharacterFrameModeTab2:SetChecked(1) end)
	W.fireScript(names.CharacterFrameModeTab2, "OnMouseUp")
	W.flush()
	check("side tab: a value that is not a boolean shows the tint", wtints(W, names.CharacterFrameModeTab2, "OVERLAY")[1].shown)
	W.blizzard(function() names.CharacterFrameModeTab2:SetChecked(nil) end)
	W.fireScript(names.CharacterFrameModeTab2, "OnMouseUp")
	W.flush()
	check("side tab: nil hides it", not wtints(W, names.CharacterFrameModeTab2, "OVERLAY")[1].shown)
	clean(W, "side tabs")
end

-- 43b. Side tab size: the tab and its icon at the chosen size (SharedUIPanelTemplates.lua:309-329, 381-399: a 55 tab around a 50 icon, set again on every
-- SetChecked), the game's sizes back for Game's size, tabs without fillToInterior left alone, and nothing sized in combat on a protected tab.
do
	local T = {}
	-- The sizes of one tab as "tab width x height / icon width x height", read from the simulated frames themselves.
	function T.text(W, name)
		local tab = wraw(W, W.win.names[name])
		local icon = wraw(W, tab.Icon)
		return g(tab.width) .. "x" .. g(tab.height) .. "/" .. g(icon.width) .. "x" .. g(icon.height)
	end
	-- The six mode tabs of the character window: the text they share, or the six texts when they differ.
	function T.all(W)
		local list = {}
		for index = 1, 6 do
			list[index] = T.text(W, "CharacterFrameModeTab" .. index)
		end
		for index = 2, 6 do
			if list[index] ~= list[1] then
				return table.concat(list, " ")
			end
		end
		return list[1]
	end
	function T.tab(W, name) return wraw(W, W.win.names[name]) end
	function T.icon(W, name) return wraw(W, T.tab(W, name).Icon) end
	function T.options(options) return { options = options } end
	function T.vio(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") end

	-- The default is Small, and the choices through the control.
	T.W = winWorld()
	T.cf = T.W.win.names.CharacterFrame
	check("sidetab: the default is Small: all six mode tabs are 35 by 35 around a 30 by 30 icon", T.all(T.W) == "35x35/30x30", T.all(T.W))
	T.tab2, T.icon2 = T.tab(T.W, "CharacterFrameModeTab2"), T.icon(T.W, "CharacterFrameModeTab2")
	check("sidetab: the icon keeps the game's anchor at CENTER -4, 0 and neither it nor the tab is anchored by the addon",
		#T.icon2.points == 1 and T.icon2.points[1][4] == -4 and T.icon2.points[1][5] == 0 and T.icon2.calls.SetPoint == nil and T.icon2.calls.ClearAllPoints == nil
		and T.tab2.calls.SetPoint == nil and T.tab2.calls.ClearAllPoints == nil and T.tab2.calls.SetAllPoints == nil)
	check("sidetab: the tab is sized once", T.tab2.calls.SetSize == 1, g(T.tab2.calls.SetSize))
	T.marks = { T.tab2.calls.SetSize, T.icon2.calls.SetSize }
	T.W.change("windows.opacity", 60)
	T.W.change("windows.opacity", 80)
	T.W.change("windows.buttons", false)
	T.W.change("windows.buttons", true)
	check("sidetab: and neither the tab nor the icon is written again when something else changes", T.tab2.calls.SetSize == T.marks[1] and T.icon2.calls.SetSize == T.marks[2])
	for _, case in ipairs({ { "Large", "47x47/42x42" }, { "Medium", "41x41/36x36" }, { "Small", "35x35/30x30" }, { "Game's size", "55x55/50x50" }, { "Large", "47x47/42x42" } }) do
		T.W.change("windows.sideTabSize", case[1])
		check("sidetab: " .. case[1] .. " gives " .. case[2], T.all(T.W) == case[2], T.all(T.W))
	end
	check("sidetab: the box around the icon and the hover tint are on the icon, which is what shrinks",
		wtints(T.W, T.W.win.names.CharacterFrameModeTab2, "HIGHLIGHT")[1].allPoints == T.tab2.Icon and T.W.state(T.tab2.Icon) == "SB")

	-- The game sets the icon to 50 by 50 on every SetChecked and the addon puts the chosen size back.
	T.W.win.choose(3, T.cf)
	check("sidetab: Large: SetChecked from Blizzard resets the icons to 50 and they are 42 again", T.all(T.W) == "47x47/42x42", T.all(T.W))
	T.W.change("windows.sideTabSize", "Small")
	T.W.win.choose(5, T.cf)
	check("sidetab: Small: and after the next SetChecked 30", T.all(T.W) == "35x35/30x30", T.all(T.W))
	T.W.win.portrait(T.cf)
	check("sidetab: the portrait set again by Blizzard does not change the sizes", T.all(T.W) == "35x35/30x30", T.all(T.W))
	T.W.change("windows.sideTabSize", "Game's size")
	check("sidetab: Game's size after SetChecked gives the game's own sizes, 55 and 50", T.all(T.W) == "55x55/50x50", T.all(T.W))
	T.icon3 = T.icon(T.W, "CharacterFrameModeTab3")
	T.mark = T.icon3.calls.SetSize
	T.W.win.choose(2, T.cf)
	check("sidetab: Game's size: SetChecked is the game's alone, which sizes the icon once and the addon does not", T.icon3.calls.SetSize == T.mark + 1 and T.all(T.W) == "55x55/50x50", T.all(T.W))
	T.kept = { T.tab(T.W, "CharacterFrameModeTab3").calls.SetSize, T.icon3.calls.SetSize }
	T.W.change("windows.opacity", 70)
	T.W.change("windows.opacity", 80)
	check("sidetab: Game's size: nothing is written when something else changes", T.tab(T.W, "CharacterFrameModeTab3").calls.SetSize == T.kept[1] and T.icon3.calls.SetSize == T.kept[2])
	clean(T.W, "sidetab")

	-- Game's size from the start writes nothing: the icons have the writes of a world without the module.
	T.G = winWorld(nil, T.options({ ["windows.sideTabSize"] = "game" }))
	T.O = winWorld(nil, T.options({ ["windows.enabled"] = false }))
	check("sidetab: Game's size from the start: 55 around 50, the tab never sized and the icons written only by the game",
		T.all(T.G) == "55x55/50x50" and T.tab(T.G, "CharacterFrameModeTab4").calls.SetSize == nil
		and T.icon(T.G, "CharacterFrameModeTab4").calls.SetSize == T.icon(T.O, "CharacterFrameModeTab4").calls.SetSize)
	T.L = winWorld(nil, T.options({ ["windows.sideTabSize"] = "large" }))
	check("sidetab: Large from the saved settings: 47 around 42", T.all(T.L) == "47x47/42x42", T.all(T.L))
	T.M = winWorld(nil, T.options({ ["windows.sideTabSize"] = "medium" }))
	check("sidetab: Medium from the saved settings: 41 around 36", T.all(T.M) == "41x41/36x36", T.all(T.M))
	-- A tab that is not square (57 by 53) has its width and height given back each.
	T.R = newWorld({ windows = true })
	T.tab(T.R, "CharacterFrameModeTab6").width, T.tab(T.R, "CharacterFrameModeTab6").height = 57, 53
	T.R.login()
	T.R.flush()
	check("sidetab: a tab of 57 by 53 is 35 by 35 in Small", T.text(T.R, "CharacterFrameModeTab6") == "35x35/30x30", T.text(T.R, "CharacterFrameModeTab6"))
	-- The game gives the tab a size of its own with the width of the size set here: it is the game's, whatever its width.
	T.tab(T.R, "CharacterFrameModeTab6").SetSize(nil, 35, 53)
	T.R.change("windows.opacity", 70)
	check("sidetab: a tab the game made 35 by 53 is 35 by 35 again", T.text(T.R, "CharacterFrameModeTab6") == "35x35/30x30", T.text(T.R, "CharacterFrameModeTab6"))
	T.R.change("windows.sideTabSize", "Game's size")
	check("sidetab: and Game's size gives back the 35 by 53 the game set last, not the 57 by 53 it had at the start", T.text(T.R, "CharacterFrameModeTab6") == "35x53/50x50", T.text(T.R, "CharacterFrameModeTab6"))
	T.R.change("windows.sideTabSize", "Small")
	T.tab(T.R, "CharacterFrameModeTab6").SetSize(nil, 35, 53)
	T.R.change("windows.sideTabSize", "Game's size")
	check("sidetab: and leaves a 35 by 53 that the game set while the width was the one set here", T.text(T.R, "CharacterFrameModeTab6") == "35x53/50x50", T.text(T.R, "CharacterFrameModeTab6"))
	T.R.change("windows.sideTabSize", "Small")
	T.R.change("windows.sideTabSize", "Game's size")
	check("sidetab: and gives back the width and the height each, as 35 by 53", T.text(T.R, "CharacterFrameModeTab6") == "35x53/50x50", T.text(T.R, "CharacterFrameModeTab6"))
	T.tab(T.R, "CharacterFrameModeTab6").SetSize(nil, 57, 53)
	T.R.change("windows.sideTabSize", "Small")
	T.R.change("windows.sideTabSize", "Game's size")
	check("sidetab: a tab of 57 by 53 given back is 57 by 53, width and height each", T.text(T.R, "CharacterFrameModeTab6") == "57x53/50x50", T.text(T.R, "CharacterFrameModeTab6"))

	-- The sizes read before the addon are the ones given back: a Looking For Group tab has the 30 its OnLoad gave the icon (the world has already run
	-- UpdateTabs, whose SetChecked makes it 50, so it is put back to 30 here), and a SetChecked makes it 50.
	T.F = newWorld({ windows = { lfg = "loaded" } })
	T.lfg = wraw(T.F, T.F.win.lfg).BrowsingTab
	T.lfgTab = wraw(T.F, T.lfg)
	T.lfgIcon = wraw(T.F, T.lfgTab.Icon)
	T.lfgIcon.width, T.lfgIcon.height = 30, 30
	T.F.login()
	T.F.flush()
	check("sidetab: a Looking For Group tab is sized too: 35 around 30", T.lfgTab.width == 35 and T.lfgTab.height == 35 and T.lfgIcon.width == 30 and T.lfgIcon.height == 30)
	T.F.change("windows.sideTabSize", "Large")
	check("sidetab: and Large: 47 around 42", T.lfgTab.width == 47 and T.lfgTab.height == 47 and T.lfgIcon.width == 42 and T.lfgIcon.height == 42)
	T.F.change("windows.sideTabSize", "Game's size")
	check("sidetab: Game's size gives it the 55 and the 30 it had before the addon", T.lfgTab.width == 55 and T.lfgTab.height == 55 and T.lfgIcon.width == 30 and T.lfgIcon.height == 30,
		g(T.lfgTab.width) .. "x" .. g(T.lfgTab.height) .. "/" .. g(T.lfgIcon.width) .. "x" .. g(T.lfgIcon.height))
	T.F.blizzard(function() T.lfg:SetChecked(true) end)
	T.F.fireScript(T.lfg, "OnClick")
	T.F.flush()
	check("sidetab: and a SetChecked then makes the icon 50, which the addon leaves", T.lfgIcon.width == 50 and T.lfgIcon.height == 50)
	T.F.change("windows.sideTabSize", "Small")
	T.F.change("windows.sideTabSize", "Game's size")
	check("sidetab: and Game's size after that gives 50, the size the game set last", T.lfgIcon.width == 50 and T.lfgIcon.height == 50 and T.lfgTab.width == 55)
	clean(T.F, "sidetab looking for group")
	-- A Looking For Group icon of 30 is the size of Small already: Small writes nothing to it, and Game's size straight after Small writes nothing more.
	T.E = newWorld({ windows = { lfg = "loaded" } })
	T.eTab = wraw(T.E, wraw(T.E, T.E.win.lfg).BrowsingTab)
	T.eIcon = wraw(T.E, T.eTab.Icon)
	T.eIcon.width, T.eIcon.height = 30, 30
	T.eMark = T.eIcon.calls.SetSize or 0
	T.E.login()
	T.E.flush()
	check("sidetab: Small leaves the 30 of a Looking For Group icon without a write", (T.eIcon.calls.SetSize or 0) == T.eMark and T.eTab.width == 35 and T.eIcon.width == 30,
		g(T.eIcon.calls.SetSize) .. " " .. g(T.eMark))
	T.E.change("windows.sideTabSize", "Game's size")
	T.eMark = T.eIcon.calls.SetSize or 0
	T.E.change("windows.opacity", 70)
	T.E.change("windows.opacity", 80)
	check("sidetab: and Game's size straight after Small, which is the same 30, writes nothing more", (T.eIcon.calls.SetSize or 0) == T.eMark and T.eIcon.width == 30 and T.eTab.width == 55,
		g(T.eIcon.calls.SetSize) .. " " .. g(T.eMark))
	clean(T.E, "sidetab looking for group at 30")

	-- A tab without fillToInterior is not sized: its icon is not set by the game either. The others are.
	T.N = newWorld({ windows = true })
	-- These two never had an icon size from the game, which sizes it only for a tab that fills to the interior.
	T.tab(T.N, "CharacterFrameModeTab4").fillToInterior = nil
	T.tab(T.N, "CharacterFrameModeTab5").fillToInterior = false
	for _, name in ipairs({ "CharacterFrameModeTab4", "CharacterFrameModeTab5" }) do
		T.icon(T.N, name).width, T.icon(T.N, name).height, T.icon(T.N, name).calls.SetSize = nil, nil, nil
	end
	T.N.login()
	T.N.flush()
	check("sidetab: a tab without fillToInterior keeps its 55 by 55 and its icon is not sized", T.text(T.N, "CharacterFrameModeTab4") == "55x55/nilxnil"
		and T.tab(T.N, "CharacterFrameModeTab4").calls.SetSize == nil and T.icon(T.N, "CharacterFrameModeTab4").calls.SetSize == nil, T.text(T.N, "CharacterFrameModeTab4"))
	check("sidetab: nor does one that has it set to false", T.text(T.N, "CharacterFrameModeTab5") == "55x55/nilxnil" and T.tab(T.N, "CharacterFrameModeTab5").calls.SetSize == nil)
	check("sidetab: and the others are sized", T.text(T.N, "CharacterFrameModeTab3") == "35x35/30x30", T.text(T.N, "CharacterFrameModeTab3"))
	T.N.change("windows.sideTabSize", "Large")
	T.N.win.choose(4, T.N.win.names.CharacterFrame)
	check("sidetab: Large and a SetChecked on it change nothing there", T.text(T.N, "CharacterFrameModeTab4") == "55x55/nilxnil" and T.text(T.N, "CharacterFrameModeTab3") == "47x47/42x42")
	check("sidetab: the sidebar tabs of the character window are not sized", T.tab(T.N, "PaperDollSidebarTab1").width == 42 and T.tab(T.N, "PaperDollSidebarTab1").calls.SetSize == nil
		and T.tab(T.N, "PaperDollSidebarTab3").height == 42)
	clean(T.N, "sidetab without fillToInterior")

	-- A tab whose icon has no size yet (the game has not run SetChecked): the tab is sized and the icon waits for the game's size.
	T.P = newWorld({ windows = { extras = true } })
	T.plainTab = wraw(T.P, T.P.win.plainSideTab)
	T.plainIcon = wraw(T.P, T.plainTab.Icon)
	T.plainIcon.width, T.plainIcon.height = 0, 0
	T.P.login()
	T.P.flush()
	check("sidetab: an icon the game has not sized yet (0 by 0) is left alone, and its tab is sized", T.plainTab.width == 35 and T.plainIcon.width == 0 and T.plainIcon.calls.SetSize == nil,
		g(T.plainTab.width) .. " " .. g(T.plainIcon.width))
	T.plainIcon.width, T.plainIcon.height = 50, 50
	T.P.change("windows.sideTabSize", "Large")
	check("sidetab: and once it has one, the next change sizes it", T.plainIcon.width == 42 and T.plainIcon.height == 42 and T.plainTab.width == 47)
	clean(T.P, "sidetab plain")

	-- The module turned off, or the part, or the window: the game's sizes come back.
	T.W = winWorld()
	for _, case in ipairs({ { "windows.sideTabs", "Side tabs" }, { "windows.enabled", "Restyle windows" }, { "windows.character", "Character" } }) do
		T.W.change(case[1], false)
		check("sidetab: " .. case[2] .. " off gives the game's 55 and 50 back", T.all(T.W) == "55x55/50x50", T.all(T.W))
		T.W.change(case[1], true)
		check("sidetab: and on again 35 and 30", T.all(T.W) == "35x35/30x30", T.all(T.W))
	end
	T.W.change("windows.sideTabs", false)
	T.W.change("windows.sideTabSize", "Large")
	check("sidetab: a size chosen while the side tabs are off changes nothing", T.all(T.W) == "55x55/50x50", T.all(T.W))
	T.W.change("windows.sideTabs", true)
	check("sidetab: and applies when they go on", T.all(T.W) == "47x47/42x42", T.all(T.W))
	T.W.change("windows.sideTabSize", "Small")
	T.W.change("windows.sideTabSize", "Large")
	T.tab(T.W, "CharacterFrameModeTab2").fault.size = "secret"
	T.W.change("windows.sideTabs", false)
	check("sidetab: a tab size that cannot be read when the game's comes back is left, and the others are given back", T.text(T.W, "CharacterFrameModeTab2") == "47x47/50x50"
		and T.text(T.W, "CharacterFrameModeTab3") == "55x55/50x50", T.all(T.W))
	T.tab(T.W, "CharacterFrameModeTab2").fault.size = nil
	T.W.change("windows.opacity", 70)
	check("sidetab: and once it can be read the tab is given back", T.text(T.W, "CharacterFrameModeTab2") == "55x55/50x50", T.text(T.W, "CharacterFrameModeTab2"))
	T.W.change("windows.opacity", 80)
	T.W.change("windows.sideTabs", true)
	T.D = winWorld(nil, T.options({ ["windows.sideTabs"] = false }))
	check("sidetab: side tabs off from the start: nothing is sized", T.all(T.D) == "55x55/50x50" and T.tab(T.D, "CharacterFrameModeTab2").calls.SetSize == nil)
	clean(T.W, "sidetab module off")

	-- A size the client withholds, or cannot read: nothing is written on that tab or icon, and nothing raises. A withheld number has the type of a number.
	for _, case in ipairs({ { "secret" }, { "error" }, { "secretFirst" }, { "string" }, { "secret", "number" }, { "secretFirst", "number" } }) do
		local fault, tag = case[1], case[2] and (case[1] .. " as a secret " .. case[2]) or case[1]
		T.X = newWorld({ windows = true })
		T.X.secretType = case[2]
		T.xTab = T.tab(T.X, "CharacterFrameModeTab2")
		T.xTab.fault.size = fault
		T.icon(T.X, "CharacterFrameModeTab3").fault.size = fault
		T.X.login()
		T.X.flush()
		check("sidetab: a tab size that is " .. tag .. " is not written, the others are", T.xTab.calls.SetSize == nil and T.xTab.width == 55 and T.text(T.X, "CharacterFrameModeTab4") == "35x35/30x30",
			T.text(T.X, "CharacterFrameModeTab2"))
		check("sidetab: an icon size that is " .. tag .. " is not written, its tab is", T.icon(T.X, "CharacterFrameModeTab3").width == 50 and T.tab(T.X, "CharacterFrameModeTab3").width == 35
			and T.icon(T.X, "CharacterFrameModeTab3").calls.SetSize == T.icon(T.O, "CharacterFrameModeTab3").calls.SetSize)
		T.X.change("windows.sideTabSize", "Game's size")
		check("sidetab: and Game's size gives the others back (" .. tag .. ")", T.text(T.X, "CharacterFrameModeTab4") == "55x55/50x50", T.text(T.X, "CharacterFrameModeTab4"))
		check("sidetab: and the icon beside a tab that could not be read, and the tab beside an icon that could not be read (" .. tag .. ")",
			T.icon(T.X, "CharacterFrameModeTab2").width == 50 and T.tab(T.X, "CharacterFrameModeTab3").width == 55, T.text(T.X, "CharacterFrameModeTab2") .. " " .. T.text(T.X, "CharacterFrameModeTab3"))
		check("sidetab: a " .. tag .. " size: no error and no violation", #T.X.errors == 0 and #T.X.violations == 0, T.vio(T.X))
	end

	-- Combat: a protected tab is not sized until combat ends, once however often it is asked. A tab that is not protected is sized at once.
	T.C = newWorld({ windows = true })
	T.C.win.protect(T.C.win.names.CharacterFrame, true)
	T.C.login()
	T.C.flush()
	T.cTab = T.tab(T.C, "CharacterFrameModeTab3")
	check("sidetab: the tabs of a protected window are sized out of combat", T.all(T.C) == "35x35/30x30", T.all(T.C))
	T.C.combat = true
	T.C.change("windows.sideTabSize", "Large")
	T.C.flush()
	check("sidetab: protected, in combat: Large waits, and nothing raises", T.all(T.C) == "35x35/30x30" and #T.C.violations == 0, T.vio(T.C))
	T.C.win.choose(3, T.C.win.names.CharacterFrame)
	check("sidetab: the game's own reset in combat stays until combat ends", T.text(T.C, "CharacterFrameModeTab3") == "35x35/50x50" and #T.C.violations == 0, T.vio(T.C))
	T.C.change("windows.sideTabSize", "Medium")
	T.C.combat = false
	T.C.fire("PLAYER_REGEN_ENABLED")
	T.C.flush()
	check("sidetab: when combat ends the size chosen last is set on every tab", T.all(T.C) == "41x41/36x36", T.all(T.C))
	check("sidetab: and the tab is written for Small and Medium only", T.cTab.calls.SetSize == 2, g(T.cTab.calls.SetSize))
	T.C.combat = true
	T.C.change("windows.sideTabs", false)
	T.C.flush()
	check("sidetab: protected, in combat: turning the side tabs off waits too", T.all(T.C) == "41x41/36x36" and #T.C.violations == 0, T.vio(T.C))
	T.C.win.choose(3, T.C.win.names.CharacterFrame)
	T.mark = T.icon(T.C, "CharacterFrameModeTab3").calls.SetSize
	T.C.combat = false
	T.C.fire("PLAYER_REGEN_ENABLED")
	T.C.flush()
	check("sidetab: and the game's sizes come back when combat ends", T.all(T.C) == "55x55/50x50", T.all(T.C))
	check("sidetab: an icon the game reset in combat is already the game's and is not written again", T.icon(T.C, "CharacterFrameModeTab3").calls.SetSize == T.mark, g(T.mark))
	clean(T.C, "sidetab combat")
	T.B = newWorld({ windows = true, combat = true })
	T.B.win.protect(T.B.win.names.CharacterFrame, true)
	T.B.login()
	T.B.flush()
	check("sidetab: login in combat with the window protected: the game's sizes, and no violation", T.all(T.B) == "55x55/50x50" and #T.B.violations == 0, T.vio(T.B))
	T.B.combat = false
	T.B.fire("PLAYER_REGEN_ENABLED")
	T.B.flush()
	check("sidetab: and the chosen size when combat ends", T.all(T.B) == "35x35/30x30", T.all(T.B))
	clean(T.B, "sidetab login in combat")
	T.U = winWorld()
	T.U.combat = true
	T.U.change("windows.sideTabSize", "Large")
	T.U.flush()
	check("sidetab: a tab that is not protected is sized at once in combat", T.all(T.U) == "47x47/42x42" and #T.U.violations == 0, T.vio(T.U))

	-- The mask that rounds the icon (Square side tab icons off) is the game's 55 by 60 at the centre of the tab, with the icon 4 to the left. It is scaled about the
	-- centre of the icon, so a smaller icon is cut as the game cuts the large one: the mask is the icon's side over 50 of 55 by 60, at the icon's place times one minus
	-- that ratio (Mainline/SharedUIPanelTemplates.xml:1026-1033, lua:381-387). With the icons square the mask is not used and is not written.
	function T.mask(W, name)
		local mask = wraw(W, T.tab(W, name).Mask)
		local point = mask.points[1]
		return string.format("%.2fx%.2f at %s %.2f,%.2f", mask.width, mask.height, point[1], point[4], point[5] + 0)
	end
	function T.masks(W)
		local list = {}
		for index = 1, 6 do
			list[index] = T.mask(W, "CharacterFrameModeTab" .. index)
		end
		for index = 2, 6 do
			if list[index] ~= list[1] then
				return table.concat(list, " | ")
			end
		end
		return list[1]
	end
	function T.maskRaw(W, name) return wraw(W, T.tab(W, name).Mask) end
	function T.round(setup, options)
		local W = newWorld({ windows = true, saved = T.options(options or { ["windows.squareTabs"] = false }) })
		if setup then
			setup(W)
		end
		W.login()
		W.flush()
		return W
	end
	T.GAME, T.SMALL, T.MEDIUM, T.LARGE = "55.00x60.00 at CENTER 0.00,0.00", "33.00x36.00 at CENTER -1.60,0.00", "39.60x43.20 at CENTER -1.12,0.00", "46.20x50.40 at CENTER -0.64,0.00"
	T.W = winWorld()
	check("sidetab mask: with Square side tab icons on the mask is the game's 55 by 60 at the centre and is never written", T.masks(T.W) == T.GAME
		and T.maskRaw(T.W, "CharacterFrameModeTab2").calls.SetSize == nil and T.maskRaw(T.W, "CharacterFrameModeTab2").calls.SetPoint == nil, T.masks(T.W))
	T.W.change("windows.sideTabSize", "Large")
	check("sidetab mask: and Large changes nothing there", T.masks(T.W) == T.GAME and T.maskRaw(T.W, "CharacterFrameModeTab2").calls.SetSize == nil and T.maskRaw(T.W, "CharacterFrameModeTab2").calls.SetPoint == nil)
	-- The mask comes off the icon before the icon is cropped, so a crop never meets a masked icon.
	T.order = {}
	T.O = T.round(function(W)
		local icon = T.icon(W, "CharacterFrameModeTab2")
		for _, name in ipairs({ "RemoveMaskTexture", "SetTexCoord" }) do
			local method = icon[name]
			icon[name] = function(...)
				T.order[#T.order + 1] = name
				return method(...)
			end
		end
	end, {})
	check("sidetab: the mask is off before the icon is cropped", T.order[1] == "RemoveMaskTexture" and T.order[2] == "SetTexCoord", table.concat(T.order, " "))
	T.Q = T.round()
	T.m2 = T.maskRaw(T.Q, "CharacterFrameModeTab2")
	check("sidetab mask: round icons in Small: the mask is 33 by 36, 1.6 to the left of the centre of the tab", T.masks(T.Q) == T.SMALL, T.masks(T.Q))
	check("sidetab mask: and written once in size and once in place", T.m2.calls.SetSize == 1 and T.m2.calls.SetPoint == 1, g(T.m2.calls.SetSize) .. " " .. g(T.m2.calls.SetPoint))
	check("sidetab mask: the point it moves is the game's CENTER of the tab, which is replaced and not cleared", #T.m2.points == 1 and T.m2.calls.ClearAllPoints == nil and T.m2.points[1][1] == "CENTER"
		and T.m2.points[1][2] == T.Q.win.names.CharacterFrameModeTab2 and T.m2.points[1][3] == "CENTER")
	T.marks = { T.m2.calls.SetSize, T.m2.calls.SetPoint }
	T.Q.change("windows.opacity", 60)
	T.Q.change("windows.opacity", 80)
	T.Q.win.choose(3, T.Q.win.names.CharacterFrame)
	check("sidetab mask: and not written again by another change or a SetChecked", T.m2.calls.SetSize == T.marks[1] and T.m2.calls.SetPoint == T.marks[2])
	for _, case in ipairs({ { "Large", T.LARGE }, { "Medium", T.MEDIUM }, { "Small", T.SMALL }, { "Game's size", T.GAME }, { "Large", T.LARGE } }) do
		T.Q.change("windows.sideTabSize", case[1])
		check("sidetab mask: " .. case[1] .. " gives " .. case[2], T.masks(T.Q) == case[2], T.masks(T.Q))
	end
	T.Q.change("windows.squareTabs", true)
	check("sidetab mask: Square side tab icons on gives the game's mask back", T.masks(T.Q) == T.GAME, T.masks(T.Q))
	T.marks = { T.m2.calls.SetSize, T.m2.calls.SetPoint }
	T.Q.change("windows.opacity", 60)
	T.Q.change("windows.opacity", 80)
	check("sidetab mask: and the game's mask is not written again", T.m2.calls.SetSize == T.marks[1] and T.m2.calls.SetPoint == T.marks[2])
	T.Q.change("windows.squareTabs", false)
	check("sidetab mask: and off again scales it", T.masks(T.Q) == T.LARGE, T.masks(T.Q))
	T.Q.change("windows.sideTabs", false)
	check("sidetab mask: Side tabs off gives the mask back with the sizes", T.masks(T.Q) == T.GAME and T.all(T.Q) == "55x55/50x50", T.masks(T.Q))
	clean(T.Q, "sidetab mask")
	-- The mask follows the place the game gave the icon: an icon 2 to the left and 1 down gives a mask 0.8 to the left and 0.4 down in Small.
	T.Y = T.round(function(W)
		for index = 1, 6 do
			wraw(W, T.tab(W, "CharacterFrameModeTab" .. index).Icon).points = { { "CENTER", W.win.names["CharacterFrameModeTab" .. index], "CENTER", -2, -1 } }
		end
	end)
	check("sidetab mask: an icon at -2, -1 gives a mask at -0.8, -0.4 in Small", T.masks(T.Y) == "33.00x36.00 at CENTER -0.80,-0.40", T.masks(T.Y))
	-- A place or a size the addon cannot read or does not know: the mask is left as the game made it, and the tab and the icon are sized.
	for _, case in ipairs({
		{ "an icon point that is withheld", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return SECRET, SECRET, SECRET, SECRET, SECRET end end },
		{ "an icon point that is withheld as numbers", function(W) W.secretType = "number" wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return "CENTER", W.win.names.CharacterFrameModeTab2, "CENTER", SECRET, SECRET end end },
		{ "a place of the icon with its left offset withheld", function(W) W.secretType = "number" wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return "CENTER", W.win.names.CharacterFrameModeTab2, "CENTER", SECRET, 0 end end },
		{ "a place of the icon with its top offset withheld", function(W) W.secretType = "number" wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return "CENTER", W.win.names.CharacterFrameModeTab2, "CENTER", -4, SECRET end end },
		{ "a place of the icon that is not numbers", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return "CENTER", W.win.names.CharacterFrameModeTab2, "CENTER", "-4", "0" end end },
		{ "an icon point that raises", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() error("GetPoint failed", 0) end end },
		{ "an icon anchored to the top left", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).points = { { "TOPLEFT", W.win.names.CharacterFrameModeTab2, "TOPLEFT", 2, -2 } } end },
		{ "an icon anchored by its top left corner to the middle of the tab", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).points = { { "TOPLEFT", W.win.names.CharacterFrameModeTab2, "CENTER", -4, 0 } } end },
		{ "an icon anchored to the middle of another frame", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).points = { { "CENTER", W.env.UIParent, "CENTER", -4, 0 } } end },
		{ "an icon anchored to the middle of the left edge", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).points = { { "CENTER", W.win.names.CharacterFrameModeTab2, "LEFT", 5, 0 } } end },
		{ "an icon with no point", function(W) wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).points = {} end },
		{ "a mask size that is withheld", function(W) T.maskRaw(W, "CharacterFrameModeTab2").fault.size = "secret" end },
		{ "a mask size that raises", function(W) T.maskRaw(W, "CharacterFrameModeTab2").fault.size = "error" end },
		{ "a mask size that is not a number", function(W) T.maskRaw(W, "CharacterFrameModeTab2").fault.size = "string" end },
	}) do
		T.Z = T.round(case[2])
		check("sidetab mask: " .. case[1] .. ": the mask is left as the game made it and the tab and the icon are sized", T.maskRaw(T.Z, "CharacterFrameModeTab2").calls.SetSize == nil
			and T.maskRaw(T.Z, "CharacterFrameModeTab2").calls.SetPoint == nil and T.text(T.Z, "CharacterFrameModeTab2") == "35x35/30x30" and T.mask(T.Z, "CharacterFrameModeTab3") == T.SMALL,
			T.text(T.Z, "CharacterFrameModeTab2") .. " " .. T.mask(T.Z, "CharacterFrameModeTab3"))
		check("sidetab mask: " .. case[1] .. ": no error and no violation, and the box of the tab is drawn", #T.Z.errors == 0 and #T.Z.violations == 0 and T.Z.state(T.tab(T.Z, "CharacterFrameModeTab2").Icon) == "SB", T.vio(T.Z))
	end
	-- Once the place can be read, the next change fits the mask.
	T.V = T.round(function(W)
		T.getPoint = wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint
		wraw(W, T.tab(W, "CharacterFrameModeTab2").Icon).GetPoint = function() return SECRET, SECRET, SECRET, SECRET, SECRET end
	end)
	wraw(T.V, T.tab(T.V, "CharacterFrameModeTab2").Icon).GetPoint = T.getPoint
	T.V.change("windows.opacity", 70)
	check("sidetab mask: and once the place of the icon can be read the mask is fitted", T.mask(T.V, "CharacterFrameModeTab2") == T.SMALL, T.mask(T.V, "CharacterFrameModeTab2"))
	-- A protected tab: the mask waits for the end of combat with the tab and the icon.
	T.K = T.round(function(W) W.win.protect(W.win.names.CharacterFrame, true) end)
	T.K.combat = true
	T.K.change("windows.sideTabSize", "Large")
	T.K.flush()
	check("sidetab mask: protected, in combat: the mask waits too, and nothing raises", T.masks(T.K) == T.SMALL and T.all(T.K) == "35x35/30x30" and #T.K.violations == 0, T.masks(T.K) .. " " .. T.vio(T.K))
	T.K.combat = false
	T.K.fire("PLAYER_REGEN_ENABLED")
	T.K.flush()
	check("sidetab mask: and is scaled when combat ends", T.masks(T.K) == T.LARGE and T.all(T.K) == "47x47/42x42", T.masks(T.K))
	clean(T.K, "sidetab mask in combat")

	-- A part that stops: the art of every frame it styled is given back, in combat on a protected window when combat ends. Three tabs whose box cannot be hidden fail when the
	-- side tabs are switched off, which stops the part, with the sizes of all six still waiting for the end of combat.
	for _, round in ipairs({ false, true }) do
		local label = "sidetab release" .. (round and " with round icons" or "")
		T.S = T.round(function(W) W.win.protect(W.win.names.CharacterFrame, true) end, { ["windows.squareTabs"] = not round })
		for index = 1, 3 do
			T.S.look(T.tab(T.S, "CharacterFrameModeTab" .. index).Icon).top.SetShown = function() error("SetShown failed", 0) end
		end
		T.S.combat = true
		T.S.change("windows.sideTabs", false)
		T.S.flush()
		check(label .. ": three tabs fail and the part stops, with its line in the status", has(T.S.status(), "Windows: side tabs stopped. SetShown failed"), T.S.status())
		check(label .. ": in combat on a protected window the sizes stay until combat ends", T.all(T.S) == "35x35/30x30" and #T.S.violations == 0 and #T.S.errors == 0, T.all(T.S) .. " " .. T.vio(T.S))
		T.S.combat = false
		T.S.fire("PLAYER_REGEN_ENABLED")
		T.S.flush()
		check(label .. ": and are the game's when it ends, though the part has stopped", T.all(T.S) == "55x55/50x50" and T.masks(T.S) == T.GAME, T.all(T.S) .. " " .. T.masks(T.S))
		check(label .. ": no violation and no error", #T.S.violations == 0 and #T.S.errors == 0, T.vio(T.S))
		T.S.change("windows.sideTabs", true)
		T.S.change("windows.sideTabSize", "Large")
		check(label .. ": a stopped part sizes nothing more", T.all(T.S) == "55x55/50x50", T.all(T.S))
	end
	-- A size chosen while the part waits, and the part stopped before combat ends.
	T.S = newWorld({ windows = true })
	T.S.win.protect(T.S.win.names.CharacterFrame, true)
	T.S.login()
	T.S.flush()
	for index = 1, 3 do
		T.S.look(T.tab(T.S, "CharacterFrameModeTab" .. index).Icon).top.SetShown = function() error("SetShown failed", 0) end
	end
	T.S.combat = true
	T.S.change("windows.sideTabSize", "Large")
	T.S.change("windows.sideTabs", false)
	T.S.change("windows.sideTabSize", "Medium")
	T.S.combat = false
	T.S.fire("PLAYER_REGEN_ENABLED")
	T.S.flush()
	check("sidetab release: a size chosen after the part stopped is not applied when combat ends", T.all(T.S) == "55x55/50x50", T.all(T.S))

	-- A bank page tab is made by the game after login, from a pool (Blizzard_UIPanels_Game/Camelot/BankFrame.lua:104-130), and met when the bank lists its pages: it has the
	-- size of that moment, and the same tab taken from the pool again after a change has the size of the new one.
	for _, start in ipairs({ { "large", "47x47/42x42" }, { "game", "55x55/50x50" } }) do
		T.P = newWorld({ windows = { second = true }, saved = T.options({ ["windows.sideTabSize"] = start[1] }) })
		T.P.login()
		T.P.flush()
		T.bank = T.P.win.names.BankFrame
		T.was, T.P.group = T.P.group, "windows"
		T.page = T.P.win.sideTab(T.bank, nil, nil, 1, "Interface/ICONS/INV_SideTab_Bank_c60")
		T.P.group = T.was
		T.P.seal()
		T.P.blizzard(function() T.page:SetChecked(false) end)
		T.P.win.bankPage()
		T.pageText = function() return g(wraw(T.P, T.page).width) .. "x" .. g(wraw(T.P, T.page).height) .. "/" .. g(wraw(T.P, wraw(T.P, T.page).Icon).width) .. "x" .. g(wraw(T.P, wraw(T.P, T.page).Icon).height) end
		check("sidetab bank page: a tab the bank lists after login is " .. start[2] .. " when the setting is " .. start[1], T.pageText() == start[2] and T.P.state(wraw(T.P, T.page).Icon) == "SB", T.pageText())
		T.P.change("windows.sideTabSize", "Small")
		T.P.blizzard(function() T.page:SetChecked(true) end)
		T.P.win.bankPage()
		check("sidetab bank page: and the next setting, Small, 35x35/30x30, also after the game sets its icon again", T.pageText() == "35x35/30x30", T.pageText())
		T.P.change("windows.sideTabSize", "Game's size")
		check("sidetab bank page: Game's size gives the 55 and the 50 of the game", T.pageText() == "55x55/50x50", T.pageText())
		check("sidetab bank page: no violation and no error", #T.P.violations == 0 and #T.P.errors == 0, T.vio(T.P))
	end
end

do
	-- The sidebar tabs of the character window: CheckButtons with a ring drawn by an unkeyed texture.
	local W = winWorld()
	local names = W.win.names
	for index = 1, 4 do
		local tab = names["PaperDollSidebarTab" .. index]
		local t = wraw(W, tab)
		local ring = wregion(W, tab, "UI-Character-Info-StatTab")
		local checked = wraw(W, t.states.Checked)
		local label = "sidebar tab " .. index
		check(label .. ": the ring is found by its atlas and is transparent", ring ~= nil and wa(W, ring) == 0)
		check(label .. ": the icon is outlined with the button colour and cropped, the tab itself has no outline", W.state(t.Icon) == "SB" and W.state(tab) == "." and wtc(W, t.Icon) == "0.08,0.92,0.08,0.92")
		check(label .. ": the checked texture is a white tint of 0.3 over the icon", checked.color and wc(checked.color) == "1.000,1.000,1.000,0.3" and checked.allPoints == t.Icon and checked.atlas == nil, wc(checked.color))
		check(label .. ": a hover tint over the icon and no selected tint of the addon's own", #wtints(W, tab, "HIGHLIGHT") == 1 and #wtints(W, tab, "OVERLAY") == 0)
		check(label .. ": the icon is a texture of its own: its alpha is not touched", wa(W, t.Icon) == 1)
	end
	local tab = names.PaperDollSidebarTab2
	W.blizzard(function() wraw(W, tab).SetChecked(tab, true) end)
	check("sidebar tab: the client shows the checked texture by itself when the tab is checked", wraw(W, wraw(W, tab).states.Checked).shown == true)
	check("sidebar tab: the ring of the pet tab, which is hidden, is faded as well", wa(W, wregion(W, names.PaperDollSidebarTab4, "UI-Character-Info-StatTab")) == 0)
	clean(W, "sidebar tabs")
end

do
	-- A sidebar tab whose ring is not among the regions is reported, and the rest of the tab is still done.
	local W = newWorld({ windows = true })
	for _, name in ipairs({ "PaperDollSidebarTab1", "PaperDollSidebarTab2" }) do
		local _, ring = wregion(W, W.win.names[name], "UI-Character-Info-StatTab")
		ring.atlas = "UI-Character-Info-StatTab-Renamed"
	end
	W.login()
	W.flush()
	check("sidebar tab without a ring: the module says so once for the window and the tab is still outlined", has(W.status(), "Windows: the default border of a sidebar tab was not found and is still shown.")
		and count(W.status(), "the default border of a sidebar tab") == 1 and W.state(wraw(W, W.win.names.PaperDollSidebarTab1).Icon) == "SB")
	check("sidebar tab without a ring: the tabs that have one are faded", wa(W, wregion(W, W.win.names.PaperDollSidebarTab3, "UI-Character-Info-StatTab")) == 0)
	clean(W, "sidebar tab without a ring")
end

-- 43c. Side tabs when the right pane closes or opens: RefreshDisplay gives every mode tab icon 50 (CharacterFrame.lua:300-301, 265-271, 217-229)
-- and the tabs are sized again on the next frame.
do
	local T = {}
	function T.text(W, name)
		local tab = wraw(W, W.win.names[name])
		local icon = wraw(W, tab.Icon)
		return g(tab.width) .. "x" .. g(tab.height) .. "/" .. g(icon.width) .. "x" .. g(icon.height)
	end
	function T.all(W)
		local list = {}
		for index = 1, 6 do
			list[index] = T.text(W, "CharacterFrameModeTab" .. index)
		end
		for index = 2, 6 do
			if list[index] ~= list[1] then
				return table.concat(list, " ")
			end
		end
		return list[1]
	end
	T.W = winWorld()
	T.cf = T.W.win.names.CharacterFrame
	T.W.win.choose(3, T.cf)
	T.W.win.collapse(true, T.cf)
	check("sidetab pane: Small, the default: closing the pane leaves all six mode tabs 35 around 30", T.all(T.W) == "35x35/30x30", T.all(T.W))
	check("sidetab pane: the simulated window keeps the tab chosen before selected", wtints(T.W, T.W.win.names.CharacterFrameModeTab3, "OVERLAY")[1].shown
		and not wtints(T.W, T.W.win.names.CharacterFrameModeTab2, "OVERLAY")[1].shown)
	T.W.win.collapse(false, T.cf)
	check("sidetab pane: and opening it again", T.all(T.W) == "35x35/30x30", T.all(T.W))
	T.hooks = T.W.hooks
	T.W.win.collapse(true, T.cf)
	T.W.win.collapse(false, T.cf)
	check("sidetab pane: no hook is added", T.W.hooks == T.hooks, T.W.hooks)
	for _, case in ipairs({ { "Large", "47x47/42x42" }, { "Medium", "41x41/36x36" }, { "Game's size", "55x55/50x50" } }) do
		T.W.change("windows.sideTabSize", case[1])
		T.W.win.collapse(true, T.cf)
		check("sidetab pane: " .. case[1] .. ": closing the pane gives " .. case[2], T.all(T.W) == case[2], T.all(T.W))
		T.W.win.collapse(false, T.cf)
		check("sidetab pane: " .. case[1] .. ": and opening it again", T.all(T.W) == case[2], T.all(T.W))
	end
	T.W.change("windows.sideTabSize", "Small")
	T.W.blizzard(function() T.cf:SetRightPaneCollapsed(true) end)
	T.icon2 = wraw(T.W, wraw(T.W, T.W.win.names.CharacterFrameModeTab2).Icon)
	check("sidetab pane: inside the game's call the icons are the game's 50", T.icon2.width == 50 and T.icon2.height == 50, g(T.icon2.width))
	T.W.flush()
	check("sidetab pane: and the chosen size on the next frame", T.icon2.width == 30 and T.icon2.height == 30, g(T.icon2.width))
	T.W.change("windows.sideTabSize", "Game's size")
	T.icon3 = wraw(T.W, wraw(T.W, T.W.win.names.CharacterFrameModeTab3).Icon)
	T.mark = T.icon3.calls.SetSize
	T.W.win.collapse(false, T.cf)
	check("sidetab pane: Game's size: opening the pane sizes each icon once, the game's write", T.icon3.calls.SetSize == T.mark + 1, g(T.icon3.calls.SetSize) .. " " .. g(T.mark))
	clean(T.W, "sidetab pane")
end

-- 44. Item slots: a box with a thin border, the quality colour as its edge, Blizzard's art transparent, and the item functions followed.
do
	local W = winWorld()
	local names = W.win.names
	local ammo = names.CharacterAmmoSlot
	for _, name in ipairs(W.win.SLOTS) do
		local slot = names[name] or W.env[name]
		local s = wraw(W, slot)
		local label = name
		check(label .. ": NormalTexture, IconBorder and the ornate frame behind the icon are transparent", wa(W, s.NormalTexture) == 0 and wa(W, s.IconBorder) == 0
			and wa(W, wraw(W, wraw(W, s.BorderFrame).regions[1])) == 0 and wa(W, s.BorderFrame) == 1)
		check(label .. ": a box with the button colour and a black one pixel edge", W.state(slot) == "SB" and wcolour(wfill(W, slot)) == PANEL_FILL and ringOf(W, slot, 1, 0, 0, 0))
		check(label .. ": the icon is cropped, its texture and alpha are kept", wtc(W, s.icon) == "0.08,0.92,0.08,0.92" and wa(W, s.icon) == 1)
		check(label .. ": the hover slot is a white tint over the button, the pressed slot a yellow one", wc(wraw(W, s.states.Highlight).color) == "1.000,1.000,1.000,0.3" and wraw(W, s.states.Highlight).allPoints == slot
			and wc(wraw(W, s.states.Pushed).color) == "0.900,0.800,0.100,0.3" and wraw(W, s.states.Pushed).allPoints == slot)
		check(label .. ": icon overlays, count, cooldown, popout button and search overlay are not touched", wa(W, s.IconOverlay) == 1 and wa(W, s.searchOverlay) == 1 and wa(W, wraw(W, s.Cooldown).regions[1]) == 1
			and wa(W, wraw(W, s.popoutButton).states.Normal) == 1 and wa(W, s.Count) == 1)
		check(label .. ": the hover is the recoloured Highlight slot, so no tint texture is added", #wtints(W, slot, "HIGHLIGHT") == 0 and #wtints(W, slot, "OVERLAY") == 0)
	end
	local a = wraw(W, ammo)
	local arrowFrame = wraw(W, ammo).children[2]
	check("ammo slot: the unkeyed ring, the normal texture and the border are transparent, the arrow is not", wa(W, wregion(W, ammo, "UI-Character-Info-GearSlotSmall")) == 0 and wa(W, a.states.Normal) == 0
		and wa(W, a.IconBorder) == 0 and wa(W, wregion(W, arrowFrame, "UI-Character-Info-GearSlot-Arrow")) == 1)
	check("ammo slot: found by name, with its ring faded even though its NormalTexture has no key", W.state(ammo) == "SB" and wa(W, a.states.Normal) == 0)
	-- Quality colour from the three functions Blizzard calls on every update.
	local head = names.CharacterHeadSlot
	local h = wraw(W, head)
	local function edge()
		local o = W.look(head)
		return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)
	end
	check("quality: an empty slot has the border colour", edge() == "0.00,0.00,0.00", edge())
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	check("quality: an epic item gives the edge its colour", edge() == "0.64,0.21,0.93", edge())
	check("quality: Blizzard shows IconBorder, which stays transparent", wraw(W, h.IconBorder).shown == true and wa(W, h.IconBorder) == 0)
	W.updateSlot("CharacterHeadSlot", { quality = 2 })
	check("quality: another item, another colour", edge() == "0.12,1.00,0.00", edge())
	W.updateSlot("CharacterHeadSlot", { quality = 4, broken = true })
	check("quality: broken gear has a red edge whatever its quality", edge() == "0.90,0.00,0.00", edge())
	check("quality: the red is on the normal texture's colour, which Blizzard set", wraw(W, h.NormalTexture).vertex[1] == 0.9)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	check("quality: repaired, the quality colour is back", edge() == "0.64,0.21,0.93", edge())
	W.updateSlot("CharacterHeadSlot", {})
	check("quality: the item is taken off: the border colour again", edge() == "0.00,0.00,0.00", edge())
	check("quality: IconBorder was hidden by Blizzard and is still transparent", wraw(W, h.IconBorder).shown == false and wa(W, h.IconBorder) == 0)
	-- Each of the three functions alone.
	W.blizzard(function()
		W.env.SetItemButtonBorder(head, [[Interface\Common\WhiteIconFrame]])
		W.env.SetItemButtonBorderVertexColor(head, 0, 0.44, 0.87)
	end)
	check("quality: SetItemButtonBorder and the colour that follows it", edge() == "0.00,0.44,0.87", edge())
	W.blizzard(function() W.env.SetItemButtonBorderVertexColor(head, 1, 0.5, 0) end)
	check("quality: the colour alone", edge() == "1.00,0.50,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonBorder(head) end)
	check("quality: SetItemButtonBorder without a border takes the colour away", edge() == "0.00,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 0.9, 0, 0) end)
	check("worn: SetItemButtonNormalTextureVertexColor with red gives a red edge", edge() == "0.90,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, 1) end)
	check("worn: and white takes the red away", edge() == "0.00,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, 0.99) end)
	check("worn: almost white is not red", edge() == "0.00,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 0.5, 0, 0) end)
	check("worn: the dark red of an item the character cannot use is red", edge() == "0.90,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 0.5, 0.5, 0.5) end)
	check("worn: the grey of an item that is sold out is not red", edge() == "0.00,0.00,0.00", edge())
	W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, 1) end)
	-- A button that is not a styled slot: the stranger of another window.
	clean(W, "item slots")
end

do
	local W = winWorld({ extras = true })
	local names = W.win.names
	local stranger = W.win.stranger
	local before = #W.addonTextures
	W.blizzard(function()
		W.env.SetItemButtonBorder(stranger, [[Interface\Common\WhiteIconFrame]])
		W.env.SetItemButtonBorderVertexColor(stranger, 1, 0, 0)
		W.env.SetItemButtonNormalTextureVertexColor(stranger, 0.9, 0, 0)
	end)
	check("a button the addon never styled: the item functions are followed for it without a result", #W.addonTextures == before and W.state(stranger) == "." and wa(W, wraw(W, stranger).IconBorder) == 1
		and wa(W, wraw(W, stranger).states.Normal) == 1)
	W.blizzard(function() W.env.SetItemButtonBorder(nil) W.env.SetItemButtonBorderVertexColor(nil, 1, 1, 1) end)
	clean(W, "stranger")
end

do
	-- The hooks are handed arguments they cannot trust.
	local W = winWorld({ hollowItems = true })
	local names = W.win.names
	local head = names.CharacterHeadSlot
	local function edge()
		local o = W.look(head)
		return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)
	end
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	check("item hooks: the colour is taken from the arguments", edge() == "0.20,0.40,0.60", edge())
	W.env.SetItemButtonBorderVertexColor(head, SECRET, 0.4, 0.6)
	check("item hooks: a withheld red component takes the quality away", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, 0.2, SECRET, 0.6)
	check("item hooks: a withheld green component too", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, SECRET)
	check("item hooks: and a withheld blue component", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, "0.2", 0.4, 0.6)
	check("item hooks: a component that is a string is no colour either", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorder(head, SECRET)
	check("item hooks: a withheld border asset leaves the colour as it was", edge() == "0.20,0.40,0.60", edge())
	W.env.SetItemButtonBorder(head)
	check("item hooks: no asset takes the colour away", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, SECRET, SECRET, SECRET)
	check("item hooks: a withheld normal texture colour changes nothing", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, 1)
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, SECRET, 1)
	check("item hooks: a withheld component among white ones does not make the item look worn", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, 0.9, 0, 0)
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, SECRET, 1)
	check("item hooks: and after a red one it leaves the red", edge() == "0.90,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(SECRET, 1, 1, 1)
	W.env.SetItemButtonNormalTextureVertexColor(nil, 1, 1, 1)
	W.env.SetItemButtonBorder(SECRET, "x")
	W.env.SetItemButtonBorderVertexColor("a string", 1, 1, 1)
	W.env.SetItemButtonBorderVertexColor(5, 1, 1, 1)
	check("item hooks: a button that is withheld, nil, a string or a number is ignored", #W.errors == 0 and #W.violations == 0, table.concat(W.errors, "|"))
	clean(W, "item hooks")
end


-- 45. Scroll bars: track, thumb and steppers lose their art; a flat track, thumb and two chevrons replace it.
do
	local W = winWorld()
	local names = W.win.names
	local bars = { { "character stats", wraw(W, names.CharacterStatsPaneScrollBox).ScrollBar }, { "pet stats", wraw(W, names.CharacterStatsPanePetScrollBox).ScrollBar },
		{ "reputation", wraw(W, names.ReputationFrame).ScrollBar }, { "friends", wraw(W, names.FriendsFrame).ScrollBar }, { "gossip", wraw(W, names.GossipFrame).GreetingPanel and wraw(W, wraw(W, names.GossipFrame).GreetingPanel).ScrollBar } }
	for _, entry in ipairs(bars) do
		local label, bar = "scroll bar of " .. entry[1], entry[2]
		local b = wraw(W, bar)
		local track = wraw(W, b.Track)
		local thumb = wraw(W, track.Thumb)
		local faded = {}
		for _, part in ipairs({ "Begin", "Middle", "End" }) do
			faded[#faded + 1] = g(wa(W, track[part]))
			faded[#faded + 1] = g(wa(W, thumb[part]))
		end
		faded[#faded + 1] = g(wa(W, wraw(W, b.Back).Texture))
		faded[#faded + 1] = g(wa(W, wraw(W, b.Forward).Texture))
		check(label .. ": the track, the thumb and both steppers are transparent", table.concat(faded, ",") == "0,0,0,0,0,0,0,0", table.concat(faded, ","))
		local trackTints = wtints(W, b.Track, "BACKGROUND")
		check(label .. ": a black track at 0.3 over the whole track", #trackTints == 1 and trackTints[1].allPoints == b.Track and wc(trackTints[1].color) == "0.000,0.000,0.000,0.3")
		local thumbBack, thumbHover = wtints(W, track.Thumb, "ARTWORK"), wtints(W, track.Thumb, "HIGHLIGHT")
		check(label .. ": a thumb in the highlight colour at a quarter, and at a half under the mouse", #thumbBack == 1 and wc(thumbBack[1].color) == "0.851,0.851,0.851,0.25" and thumbBack[1].allPoints == track.Thumb
			and #thumbHover == 1 and wc(thumbHover[1].color) == "0.851,0.851,0.851,0.5" and thumbHover[1].allPoints == track.Thumb)
		check(label .. ": a chevron up on Back and down on Forward, white and in the highlight colour", wsegments(wlines(W, b.Back, "OVERLAY")) == UP_SHAPE and wsegments(wlines(W, b.Forward, "OVERLAY")) == DOWN_SHAPE
			and wsegments(wlines(W, b.Back, "HIGHLIGHT")) == UP_SHAPE and wsegments(wlines(W, b.Forward, "HIGHLIGHT")) == DOWN_SHAPE
			and wc(wlines(W, b.Back, "OVERLAY")[1].color) == "1.000,1.000,1.000,0.6" and wc(wlines(W, b.Back, "HIGHLIGHT")[1].color) == ACCENT)
		check(label .. ": no outline on the bar, no change to the bar's own frame", W.state(bar) == "." and wa(W, bar) == 1)
	end
	-- Blizzard changes the atlas of the steppers on every hover. That changes no alpha.
	local back = wraw(W, wraw(W, wraw(W, names.FriendsFrame).ScrollBar).Back)
	W.blizzard(function() wraw(W, back.Texture):SetAtlas("minimal-scrollbar-arrow-top-over") end)
	check("scroll bar: Blizzard sets the stepper's atlas on hover and it stays transparent", wa(W, back.Texture) == 0)
	clean(W, "scroll bars")
end

-- 46. Check boxes: about the size of one, no picture of their own; the box, the check and the hover are flat.
do
	local W = winWorld({ extras = true })
	local names = W.win.names
	local rep = wraw(W, names.ReputationDetailFrame)
	local boxes = { { "at war box", rep.AtWarCheckbox }, { "inactive box", rep.MakeInactiveCheckbox }, { "watch box", rep.WatchFactionCheckbox }, { "friends box", names.FriendsFrameOfflineCheck } }
	for _, entry in ipairs(boxes) do
		local label, box = entry[1], entry[2]
		local b = wraw(W, box)
		local own = wboxes(W, box)
		check(label .. ": Normal and Pushed are transparent", wa(W, b.states.Normal) == 0 and wa(W, b.states.Pushed) == 0)
		check(label .. ": an inner box four units in on each side with the button colour and a thin border", #own == 1 and own[1].points[1][4] == 4 and own[1].points[1][5] == -4 and own[1].points[2][4] == -4 and own[1].points[2][5] == 4
			and W.state(own[1]) == "SB" and wcolour(wfill(W, own[1])) == PANEL_FILL and W.state(box) == ".")
		local checked, disabled, hover = wraw(W, b.states.Checked), wraw(W, b.states.DisabledChecked), wraw(W, b.states.Highlight)
		check(label .. ": the check is a gold square inside the box, six units in", wc(checked.color) == "1.000,0.820,0.000,0.8" and checked.points[1][1] == "TOPLEFT" and checked.points[1][2] == box and checked.points[1][4] == 6
			and checked.points[1][5] == -6 and checked.points[2][4] == -6 and checked.points[2][5] == 6 and #checked.points == 2 and not checked.allPoints, wc(checked.color))
		check(label .. ": the disabled check is grey", wc(disabled.color) == "0.600,0.600,0.600,0.8" and disabled.points[1][4] == 6)
		check(label .. ": the hover is white at 0.3 over the inner box", wc(hover.color) == "1.000,1.000,1.000,0.3" and hover.allPoints == own[1])
	end
	-- What is not a check box.
	check("not a check box: a radio button of 16 units", W.state(W.win.radio) == "." and #wboxes(W, W.win.radio) == 0 and wa(W, wraw(W, W.win.radio).states.Normal) == 1)
	check("not a check box: a check button with a picture of its own", #wboxes(W, W.win.pictureCheck) == 0 and wa(W, wraw(W, W.win.pictureCheck).states.Normal) == 1)
	check("not a check box: a check button of 40 units", #wboxes(W, W.win.bigCheck) == 0 and wa(W, wraw(W, W.win.bigCheck).states.Normal) == 1)
	check("not a check box: a check button 24 wide and 30 high", #wboxes(W, W.win.tallCheck) == 0 and wa(W, wraw(W, W.win.tallCheck).states.Normal) == 1)
	clean(W, "check boxes")
end

do
	-- The size window: 20 to 32 units, within 2 of each other.
	local W = newWorld({ windows = { only = {} } })
	local root = W.win.frame(W.env.UIParent, nil, { name = "TradeFrame" })
	local sizes = { { 19, 19, false }, { 20, 20, true }, { 32, 32, true }, { 33, 33, false }, { 26, 24, true }, { 26, 23, false }, { 24, 26, true }, { 24, 27, false }, { 20, 22, true }, { 20, 22.5, false }, { 19, 20, false }, { 33, 32, false }, { 20, 19, false }, { 32, 33, false }, { 21, 20, true }, { 31, 32, true } }
	local made = {}
	for _, size in ipairs(sizes) do
		local box = W.win.checkButton(root, nil, nil, size[1])
		W.rawOf[box].height = size[2]
		made[#made + 1] = box
	end
	W.login()
	W.flush()
	for index, size in ipairs(sizes) do
		check(("check box size %g by %g: %s"):format(size[1], size[2], size[3] and "a check box" or "left alone"), (#wboxes(W, made[index]) == 1) == size[3])
	end
	clean(W, "check box sizes")
end

-- 47. Text boxes: the caps are transparent, the outline is on the parent, and nothing is created on an edit box.
do
	local W = winWorld({ extras = true })
	local names = W.win.names
	local box = W.win.editBox
	local b = wraw(W, box)
	local parent = W.rawOf[box].parent
	check("text box: Left, Middle and Right are transparent", wa(W, b.Left) == 0 and wa(W, b.Middle) == 0 and wa(W, b.Right) == 0)
	check("text box: nothing was created on the edit box", #wowned(W, box) == 0 and #b.children == 0 and not W.holderOn(box) and W.state(box) == ".")
	local boxes = wboxes(W, parent)
	check("text box: a box on the parent from five units left of the edit box to its right edge", #boxes == 1 and boxes[1].points[1][2] == box and boxes[1].points[1][1] == "TOPLEFT" and boxes[1].points[1][4] == -5
		and boxes[1].points[1][5] == 0 and boxes[1].points[2][1] == "BOTTOMRIGHT" and boxes[1].points[2][2] == box and boxes[1].points[2][4] == 0 and boxes[1].points[2][5] == 0)
	check("text box: the box has the button colour and a thin black border, and belongs to the parent", W.state(boxes[1]) == "SB" and wcolour(wfill(W, boxes[1])) == PANEL_FILL and ringOf(W, boxes[1], 1, 0, 0, 0)
		and W.holderOn(boxes[1]).parent == parent)
	local scroll = W.win.inputScroll
	local s = wraw(W, scroll)
	local faded = {}
	for _, part in ipairs({ "TopLeftTex", "TopTex", "TopRightTex", "LeftTex", "MiddleTex", "RightTex", "BottomLeftTex", "BottomTex", "BottomRightTex" }) do
		faded[#faded + 1] = g(wa(W, s[part]))
	end
	check("a box with several lines: the nine border textures are transparent", table.concat(faded, ",") == "0,0,0,0,0,0,0,0,0", table.concat(faded, ","))
	check("a box with several lines: it is outlined itself, with the button colour and a thin border", W.state(scroll) == "SB" and wcolour(wfill(W, scroll)) == PANEL_FILL and ringOf(W, scroll, 1, 0, 0, 0))
	check("a box with several lines: the edit box inside is not touched and gets no outline", #wowned(W, s.EditBox) == 0 and wa(W, s.EditBox) == 1 and W.state(s.EditBox) == ".")
	check("a box with several lines: its scroll bar is styled like any other", wa(W, wraw(W, wraw(W, s.ScrollBar).Track).Begin) == 0 and #wlines(W, wraw(W, s.ScrollBar).Back, "OVERLAY") == 2)
	-- The comment box of Looking For Group has the same nine textures and the old Slider scroll bar.
	W.loadGroupFinder()
	W.flush()
	local comment = W.win.comment
	check("a box with several lines: the comment box of Looking For Group is outlined and its textures are transparent", W.state(comment) == "SB" and wa(W, wraw(W, comment).MiddleTex) == 0 and wa(W, wraw(W, comment).TopLeftTex) == 0)
	check("a box with several lines: the old scroll bar of the comment box is not a MinimalScrollBar and is left as it is", W.state(wraw(W, comment).ScrollBar) == "." and #wowned(W, wraw(W, comment).ScrollBar) == 0)
	clean(W, "text boxes")
end

do
	-- The mail window's recipient and subject boxes draw their edge with textures that have names but no keys.
	local W = winWorld()
	local names = W.win.names
	for _, name in ipairs({ "SendMailNameEditBox", "SendMailSubjectEditBox" }) do
		local box = names[name]
		check(name .. ": the box has no Left, Middle or Right field, as in Blizzard's XML", wraw(W, box).Left == nil and wraw(W, box).Middle == nil and wraw(W, box).Right == nil)
		check(name .. ": its edge textures are transparent", wa(W, W.env[name .. "Left"]) == 0 and wa(W, W.env[name .. "Middle"]) == 0 and wa(W, W.env[name .. "Right"]) == 0,
			g(wa(W, W.env[name .. "Left"])))
		check(name .. ": and a box with a thin border replaces them", #wboxes(W, names.SendMailFrame) >= 1)
	end
	local body = names.SendMailScrollFrame
	check("mail body: the scroll frame is a plain ScrollFrame whose scroll bar is a MinimalScrollBar, and it is styled", wa(W, wraw(W, wraw(W, wraw(W, body).ScrollBar).Track).Begin) == 0
		and #wlines(W, wraw(W, wraw(W, body).ScrollBar).Forward, "OVERLAY") == 2)
	check("mail body: the edit box inside it is left alone and so is the stationery", #wowned(W, names.SendMailBodyEditBox) == 0 and wa(W, W.env.SendStationeryBackgroundLeft) == 1)
	clean(W, "mail text boxes")
end

-- 48. Dropdowns: the button's art is transparent, a box and a chevron replace it, and the menu that opens is left alone.
do
	local W = winWorld()
	local names = W.win.names
	for _, name in ipairs({ "FriendsFrameStatusDropdown", "ReputationFrameFilterDropdown" }) do
		local drop = names[name]
		local d = wraw(W, drop)
		check(name .. ": Background and Arrow are transparent, the label is not", wa(W, d.Background) == 0 and wa(W, d.Arrow) == 0 and wa(W, d.Text) == 1)
		check(name .. ": a box with the button colour and a thin border, and a hover tint at a quarter", W.state(drop) == "SB" and wcolour(wfill(W, drop)) == PANEL_FILL and ringOf(W, drop, 1, 0, 0, 0)
			and #wtints(W, drop, "HIGHLIGHT") == 1 and wc(wtints(W, drop, "HIGHLIGHT")[1].color) == "0.851,0.851,0.851,0.25")
		local lines = wlines(W, drop, "OVERLAY")
		check(name .. ": a white chevron down, eight units, twelve units from the right edge", #lines == 2 and wc(lines[1].color) == "1.000,1.000,1.000,0.8" and lines[1].start[1] == "RIGHT" and lines[1].start[2] == drop
			and wsegment(lines[1]) == "-16,2>-12,-2" and wsegment(lines[2]) == "-12,-2>-8,2", wsegments(lines))
	end
	-- The filter dropdown has a reset button instead of an arrow.
end
do
	local W = winWorld({ extras = true })
	local filter = W.win.filterDropdown
	local f = wraw(W, filter)
	check("dropdown: the Filter style has a reset button and no Arrow; its Background is transparent and it is still outlined", f.Arrow == nil and wa(W, f.Background) == 0 and W.state(filter) == "SB")
	check("dropdown: the reset button of the Filter style is not touched", W.state(f.ResetButton) == "." and #wlines(W, f.ResetButton) == 0)
	clean(W, "dropdowns")
end

-- 49. Progress bars: the background is transparent, the fill loses its mask, a window-coloured box 15 high replaces the art.
do
	local W = winWorld()
	local names = W.win.names
	for _, name in ipairs({ "ReputationBar1", "SkillBar1" }) do
		local bar = names[name]
		local b = wraw(W, bar)
		local back = wregion(W, bar, "common-stat-bar-BG")
		check(name .. ": the unkeyed background is found by its atlas and is transparent", back ~= nil and wa(W, back) == 0)
		check(name .. ": the fill is not masked any more, the mask stays", not wmasked(W, b.Fill, b.Mask) and wa(W, b.Mask) == 1 and wa(W, b.Fill) == 1 and wa(W, b.Text) == 1)
		local own = wboxes(W, bar)
		check(name .. ": a box across the bar, 15 high, centred", #own == 1 and own[1].height == 15 and own[1].points[1][1] == "LEFT" and own[1].points[1][4] == 0 and own[1].points[2][1] == "RIGHT" and own[1].points[2][4] == 0)
		check(name .. ": the box has the window colour and a thin border", W.state(own[1]) == "SB" and wcolour(wfill(W, own[1])) == WINDOW_FILL and ringOf(W, own[1], 1, 0, 0, 0) and W.state(bar) == ".")
	end
	-- Blizzard changes the fill's width, coordinates and atlas. That changes nothing the addon did.
	local bar = wraw(W, names.ReputationBar1)
	W.blizzard(function() names.ReputationBar1:SetFillPercent(0.5) names.ReputationBar1:SetFillTextureByColorType(2) end)
	check("progress bar: Blizzard sets the fill's width and atlas and the mask stays off", not wmasked(W, bar.Fill, bar.Mask) and wraw(W, bar.Fill).width == 80)
	clean(W, "progress bars")
end

do
	-- A bar whose background is not among the regions: said once, and the rest of the bar is done.
	local W = newWorld({ windows = true })
	local _, back = wregion(W, W.win.names.ReputationBar1, "common-stat-bar-BG")
	back.atlas = "something-else"
	W.login()
	W.flush()
	check("progress bar without its background: the note is in the status, once", count(W.status(), "the default background of a progress bar was not found") == 1)
	check("progress bar without its background: the box and the unmasked fill are still done", #wboxes(W, W.win.names.ReputationBar1) == 1 and not wmasked(W, wraw(W, W.win.names.ReputationBar1).Fill, wraw(W, W.win.names.ReputationBar1).Mask))
	check("progress bar without its background: the other bar, which has it, is faded", wa(W, wregion(W, W.win.names.SkillBar1, "common-stat-bar-BG")) == 0)
	clean(W, "progress bar without background")
end

-- 50. The divider between the two panes of the character window: one line in the border colour, one pixel wide.
do
	local W = winWorld()
	local names = W.win.names
	local pane = names.CharacterFrameRightPaneHost
	local lines = {}
	for _, t in ipairs(wowned(W, pane)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 then
			lines[#lines + 1] = t
		end
	end
	check("divider: one OVERLAY line down the left edge of the right pane, from one unit below the top", #lines == 1 and lines[1].points[1][1] == "TOPLEFT" and lines[1].points[1][2] == pane and lines[1].points[1][4] == 0
		and lines[1].points[1][5] == -1 and lines[1].points[2][1] == "BOTTOMLEFT" and lines[1].points[2][5] == 0)
	local expect = 768 / 1080 / W.scale()
	check("divider: one screen pixel wide in the units of the pane", near(lines[1].width, expect, 1e-6), g(lines[1].width) .. " " .. g(expect))
	check("divider: in the border colour", wc(lines[1].color) == "0.000,0.000,0.000,1" and lines[1].shown)
	check("divider: Blizzard's own divider art, which sits one level into the pane, is transparent", wa(W, wregion(W, wraw(W, pane).children[1], "common-framedivider")) == 0)
	W.gameScale(0.5)
	W.flush()
	check("divider: a new UI scale gives it a new width", near(lines[1].width, 768 / 1080 / 0.5, 1e-6), g(lines[1].width))
	W.change("general.thickness", 3)
	W.flush()
	check("divider: a border thickness of three pixels makes it three pixels wide", near(lines[1].width, 3 * 768 / 1080 / 0.5, 1e-6), g(lines[1].width))
	W.change("general.border", "ff336699")
	W.flush()
	check("divider: and takes the border colour", wc(lines[1].color) == "0.200,0.400,0.600,1", wc(lines[1].color))
	clean(W, "divider")
end

-- 51. Panels with art that has no field: every texture on the frame is transparent, the rest is not.
do
	local W = winWorld()
	local names = W.win.names
	local left, right = names.CharacterFrameLeftPaneHost, names.CharacterFrameRightPaneHost
	check("art: the left pane's background is transparent", wa(W, wraw(W, left).regions[1]) == 0)
	check("art: the right pane's background and stone header are transparent, and the divider art one frame down", wa(W, wraw(W, right).regions[1]) == 0 and wa(W, wraw(W, right).StoneBg) == 0
		and wa(W, wraw(W, wraw(W, right).children[1]).regions[1]) == 0)
	check("art: frames are never made transparent, only their textures", wa(W, left) == 1 and wa(W, right) == 1 and wa(W, wraw(W, right).children[1]) == 1)
	local level = names.PaperDollLevelInfo
	check("art: the level text's background is transparent, its text is not", wa(W, wraw(W, level).regions[1]) == 0 and wa(W, wraw(W, level).regions[2]) == 1)
	local box = names.CharacterStatsPaneScrollBox
	check("art: the stats list loses its border, its scroll line and its class picture", wa(W, wraw(W, box).Border) == 0 and wa(W, wraw(W, box).ClassBackground) == 0 and wa(W, wraw(W, box).regions[2]) == 0)
	check("art: the frames inside the stats list are not stripped", wa(W, wraw(W, wraw(W, box).ScrollBar).Track) == 1)
	local pane = wraw(W, names.PaperDollFrame).EquipmentManagerPane
	check("art: a pane that was not listed keeps its border", wa(W, wraw(W, pane).Border) == 1)
	-- Race art is a picture, not a border.
	local scene = wraw(W, names.CharacterModelScene)
	local list = {}
	for _, part in ipairs({ "BackgroundTopLeft", "BackgroundTopRight", "BackgroundBotLeft", "BackgroundBotRight", "BackgroundOverlay" }) do
		list[#list + 1] = g(wa(W, scene[part]))
	end
	check("race art: the four pictures and the overlay are transparent by default, the scene is not", table.concat(list, ",") == "0,0,0,0,0" and wa(W, names.CharacterModelScene) == 1)
	check("race art: the model scene's controls are not touched", wa(W, wraw(W, wraw(W, scene.ControlFrame).children[1]).states.Normal) == 1)
	clean(W, "panels")
end


-- 52. Looking For Group: three pages inside one frame, tabs down the side, category buttons made by Lua, role buttons with art, an eye.
do
	local W = winWorld({ lfg = "loaded" })
	local names = W.win.names
	local lfg = names.LFGParentFrame
	local l = wraw(W, lfg)
	check("looking for group: the frame has an outline with the window fill and no NineSlice of its own", W.state(lfg) == "SB" and wcolour(wfill(W, lfg)) == WINDOW_FILL and l.NineSlice == nil)
	check("looking for group: the close button has no key and is found by its name; its states are transparent and a cross is drawn", wa(W, wraw(W, names.LFGParentFrameCloseButton).states.Normal) == 0
		and wsegments(wlines(W, names.LFGParentFrameCloseButton, "OVERLAY")) == X_SHAPE)
	for _, page in ipairs({ "LFGListingFrame", "LFGBrowseFrame", "LFGWhoListFrame" }) do
		local p = wraw(W, names[page])
		local nine = wraw(W, p.NineSlice)
		local faded = 0
		for _, piece in ipairs({ "TopLeftCorner", "TopRightCorner", "BottomLeftCorner", "BottomRightCorner", "TopEdge", "BottomEdge", "LeftEdge", "RightEdge" }) do
			faded = faded + (wa(W, nine[piece]) == 0 and 1 or 0)
		end
		check(page .. ": its eight pieces, Bg, streaks and portrait are transparent", faded == 8 and wa(W, p.Bg) == 0 and wa(W, p.TopTileStreaks) == 0 and wa(W, wraw(W, p.PortraitContainer).portrait) == 0)
		check(page .. ": a page fills the window and has no outline or box of its own", W.state(names[page]) == "." and #wboxes(W, names[page]) == 0)
		check(page .. ": every texture of its own is transparent", (function()
			for _, region in ipairs(p.regions) do
				if W.rawOf[region].kind == "Texture" and not W.rawOf[region].addon and W.rawOf[region].alpha ~= 0 then
					return false
				end
			end
			return true
		end)())
	end
	local listing = wraw(W, names.LFGListingFrame)
	check("looking for group: the roles background, the inset's picture and border, the divider and the activity bar are transparent",
		wa(W, wraw(W, listing.RolesSection).regions[1]) == 0 and wa(W, wraw(W, listing.Inset).CustomBG) == 0 and wa(W, wraw(W, listing.Inset).Border) == 0
		and wa(W, wraw(W, listing.DividerFrame).Divider) == 0 and wa(W, wraw(W, listing.ActivityView).BarTop) == 0)
	check("looking for group: the browse page's inset is transparent too", wa(W, wraw(W, wraw(W, names.LFGBrowseFrame).Inset).CustomBG) == 0 and wa(W, wraw(W, wraw(W, names.LFGBrowseFrame).Inset).Border) == 0)
	-- Side tabs and the old tabs.
	for index, key in ipairs({ "ListingTab", "BrowsingTab", "WhoListingTab" }) do
		local tab = l[key]
		local t = wraw(W, tab)
		check(key .. ": a side tab: transparent background, cropped icon without its mask, a box around the icon", wa(W, t.Background) == 0 and wtc(W, t.Icon) == "0.10625,0.89375,0.10625,0.89375" and not wmasked(W, t.Icon, t.Mask) and W.state(t.Icon) == "SB")
		check(key .. ": only the first is selected", wtints(W, tab, "OVERLAY")[1].shown == (index == 1))
	end
	for index = 1, 3 do
		local old = names["LFGParentFrameTab" .. index]
		check("old tab " .. index .. ": hidden by Blizzard, styled like any tab all the same", wraw(W, old).shown == false and wa(W, wraw(W, old).Left) == 0 and #wboxes(W, old) == 1)
	end
	-- Buttons, role check boxes, dropdowns.
	check("looking for group: the Back and Post buttons are push buttons", W.state(names.LFGListingFrameBackButton) == "SB" and W.state(names.LFGListingFramePostButton) == "SB"
		and wa(W, wraw(W, names.LFGListingFrameBackButton).Left) == 0)
	local solo = wraw(W, names.LFGListingFrameSoloRoleButtons).RoleButtons
	for index, roleButton in ipairs(solo) do
		local rb = wraw(W, roleButton)
		check("role button " .. index .. ": its background art is transparent, the dim cover and the normal texture are not", wa(W, rb.Background) == 0 and wa(W, rb.cover) == 0.5 and wa(W, rb.states.Normal) == 1)
		check("role button " .. index .. ": the 24 unit check button inside is a check box, the role button is not outlined", #wboxes(W, rb.CheckButton) == 1 and W.state(roleButton) == "." and #wboxes(W, roleButton) == 0)
	end
	local icon = wraw(W, names.LFGListingFrameGroupRoleButtonsRole)
	check("role icon of a group: its background, which Blizzard set to 0.6, is transparent", wa(W, icon.Background) == 0)
	check("looking for group: the role poll button and the role dropdown are done", W.state(wraw(W, names.LFGListingFrameGroupRoleButtons).RolePollButton) == "SB" and W.state(names.LFGListingFrameGroupRoleButtonsRoleDropdown) == "SB")
	check("looking for group: the browse page's refresh button and its filter dropdown are done", W.state(names.LFGBrowseFrameRefreshButton) == "SB" and W.state(names.LFGBrowseFrameCategoryDropdown) == "SB"
		and wa(W, wraw(W, names.LFGBrowseFrameCategoryDropdown).Background) == 0)
	-- The eye.
	local eye = names.LFGParentFramePortrait
	check("eye: the texture with the ring and the eye is transparent by default, the animation frames are not touched", wa(W, wraw(W, eye).texture) == 0 and W.state(eye) == "." and #wowned(W, eye) == 0
		and #wowned(W, wraw(W, eye).EyeInitial) == 0)
	-- Category buttons: made by Blizzard in Lua, one at a time.
	W.win.updateCategories(3)
	W.flush()
	local view = W.win.categoryView
	local buttons = wraw(W, view).CategoryButtons
	check("category buttons: three buttons were made and all are styled", #buttons == 3 and W.state(wraw(W, buttons[1]).Icon) == "SB" and W.state(wraw(W, buttons[2]).Icon) == "SB" and W.state(wraw(W, buttons[3]).Icon) == "SB")
	for index, button in ipairs(buttons) do
		local b = wraw(W, button)
		check("category button " .. index .. ": the cover and the pushed and highlight textures are transparent, the picture is not", wa(W, b.Cover) == 0 and wa(W, b.states.Pushed) == 0 and wa(W, b.states.Highlight) == 0 and wa(W, b.Icon) == 1)
		check("category button " .. index .. ": a box around the picture only, with the button colour, and a faint white hover over the picture", wcolour(wfill(W, b.Icon)) == PANEL_FILL and W.state(button) == "."
			and #wtints(W, button, "HIGHLIGHT") == 1 and wtints(W, button, "HIGHLIGHT")[1].allPoints == b.Icon and wc(wtints(W, button, "HIGHLIGHT")[1].color) == "1.000,1.000,1.000,0.1"
			and wtints(W, button, "HIGHLIGHT")[1].blend == "ADD")
		check("category button " .. index .. ": nothing added reaches outside the picture: every part is anchored to it, the label is not touched", W.holderOn(b.Icon) ~= nil and W.holderOn(b.Icon).parent == button
			and #wboxes(W, button) == 0 and wa(W, b.Label) == 1)
	end
	W.win.updateCategories(5)
	W.flush()
	check("category buttons: two more are made when the list grows, and styled when Blizzard has filled them", #wraw(W, view).CategoryButtons == 5 and W.state(wraw(W, wraw(W, view).CategoryButtons[5]).Icon) == "SB"
		and wa(W, wraw(W, wraw(W, view).CategoryButtons[5]).Cover) == 0)
	local before = #W.addonTextures
	W.win.updateCategories(2)
	W.win.updateCategories(5)
	check("category buttons: the list shrinks and grows without making anything again", #W.addonTextures == before)
	check("category buttons: a button Blizzard hides is still styled", wraw(W, wraw(W, view).CategoryButtons[5]).shown == true)
	clean(W, "looking for group")
end

-- 53. Vendor: the art behind each item and the repair buttons.
do
	local W = winWorld()
	local names = W.win.names
	for index = 1, 13 do
		local name = index == 13 and "MerchantBuyBackItem" or ("MerchantItem" .. index)
		local cell = names[name]
		local c = wraw(W, cell)
		check(name .. ": the slot and the name frame behind the item are transparent, the name is not", wa(W, c.SlotTexture) == 0 and wa(W, W.env[name .. "NameFrame"]) == 0 and wa(W, c.Name) == 1)
		check(name .. ": the cell is not outlined, but the item button in it is a slot", W.state(cell) == "." and W.state(c.ItemButton) == "SB" and wa(W, wraw(W, c.ItemButton).NormalTexture) == 0)
		check(name .. ": the frames inside the cell are not made transparent", wa(W, c.ItemButton) == 1 and wa(W, W.env[name .. "MoneyFrame"]) == 1)
	end
	for _, name in ipairs({ "MerchantSellAllJunkButton", "MerchantRepairAllButton", "MerchantRepairItemButton", "MerchantGuildBankRepairButton" }) do
		local button = names[name]
		local b = wraw(W, button)
		check(name .. ": the empty slot art behind the icon is transparent, the icon is not", wa(W, b.regions[1]) == 0 and wa(W, b.Icon) == 1)
		check(name .. ": a box with the button colour and a thin border, and a white hover tint at 0.3 added over the button", W.state(button) == "SB" and wcolour(wfill(W, button)) == PANEL_FILL
			and #wtints(W, button, "HIGHLIGHT") == 1 and wtints(W, button, "HIGHLIGHT")[1].blend == "ADD" and wc(wtints(W, button, "HIGHLIGHT")[1].color) == "1.000,1.000,1.000,0.3")
		check(name .. ": the Pushed and Highlight slots are transparent as well", wa(W, b.states.Pushed) == 0 and wa(W, b.states.Highlight) == 0)
	end
	check("vendor: the two tabs below the window are tabs", #wboxes(W, names.MerchantFrameTab1) == 1 and #wboxes(W, names.MerchantFrameTab2) == 1)
	check("vendor: the page buttons keep their arrows", wa(W, wraw(W, names.MerchantNextPageButton).states.Normal) == 1 and W.state(names.MerchantNextPageButton) == ".")
	check("vendor: the portrait is transparent by default and so is the bronze strip along the bottom", wa(W, W.env.MerchantFramePortrait) == 0 and wa(W, W.env.MerchantFrameBottomLeftBorder) == 0)
	clean(W, "vendor")
end

do
	-- A client whose GetRegions does not list the state textures of a button.
	local W = winWorld({ stateRegions = false })
	local names = W.win.names
	local button = names.MerchantRepairAllButton
	check("vendor button when GetRegions lists no state texture: the slot art is transparent and the button is done", wa(W, wraw(W, button).regions[1]) == 0 and W.state(button) == "SB")
	check("vendor button when GetRegions lists no state texture: the slots are then left as they are", wa(W, wraw(W, button).states.Pushed) == 1 and wa(W, wraw(W, button).states.Highlight) == 1)
	check("vendor button when GetRegions lists no state texture: nothing raised", #W.violations == 0 and #W.errors == 0)
	clean(W, "state textures not in regions")
end

-- 54. The hooks: how many, on what, and that none is made twice.
do
	local base = newWorld()
	base.login()
	local W = winWorld()
	check("hooks: the windows add five hooks on globals and none on methods", W.hooks - base.hooks == 5, W.hooks - base.hooks)
	local count = W.hooks
	W.change("windows.opacity", 60)
	W.change("windows.buttons", false)
	W.change("windows.buttons", true)
	W.change("general.thickness", 2)
	W.flush()
	check("hooks: refreshing after option changes hooks nothing again", W.hooks == count, W.hooks - count)
	local L = winWorld()
	local sofar = L.hooks
	L.loadGroupFinder()
	L.flush()
	check("hooks: loading the Looking For Group addon adds the hook on the category list and nothing else", L.hooks - sofar == 1, L.hooks - sofar)
	L.fire("ADDON_LOADED", "Blizzard_GroupFinder_VanillaStyle")
	L.flush()
	check("hooks: the addon announcing itself twice hooks nothing twice", L.hooks - sofar == 1, L.hooks - sofar)
	local off = newWorld({ windows = true, saved = { options = { ["windows.enabled"] = false } } })
	off.login()
	check("hooks: with the module off at login nothing is hooked", off.hooks == base.hooks, off.hooks - base.hooks)
end


-- 55. Walk: what each handler recognises, and what it must not mistake for its control.
-- A window of our own (a listed name no other test builds) holds one control built from Blizzard's templates, then altered.
local function wsynth(build, group)
	local W = newWorld({ windows = { only = {} } })
	W.group = "windows"
	local root = W.win.frame(W.env.UIParent, nil, { name = group or "ItemTextFrame" })
	local made = build(W, root)
	W.group = "static"
	W.seal()
	W.login()
	W.flush()
	return W, root, made
end
local function wbaseline()
	local W = wsynth(function() end)
	return #W.addonTextures, #W.addonFrames
end
local BASE_TEXTURES, BASE_FRAMES = wbaseline()
-- Whether the addon made anything for what `build` made.
local function wstyled(build)
	local W, root, made = wsynth(build)
	local faded = 0
	for _, r in ipairs(W.blizzRegions) do
		if r.group == "windows" and r.sealed and r.sealed.alpha ~= g(r.alpha) then
			faded = faded + 1
		end
	end
	return (#W.addonTextures > BASE_TEXTURES or #W.addonFrames > BASE_FRAMES or faded > 0), W, made
end

do
	local cases = {
		{ "a scroll bar with Track, Thumb, Back and Forward", true, function(W, root) return W.win.scrollBar(root, "Bar") end },
		{ "a scroll bar without Forward", false, function(W, root) local bar = W.win.scrollBar(root, "Bar") W.rawOf[bar].Forward = nil return bar end },
		{ "a scroll bar without Back", false, function(W, root) local bar = W.win.scrollBar(root, "Bar") W.rawOf[bar].Back = nil return bar end },
		{ "a scroll bar without Thumb", false, function(W, root) local bar = W.win.scrollBar(root, "Bar") W.rawOf[W.rawOf[bar].Track].Thumb = nil return bar end },
		{ "a scroll bar without Track", false, function(W, root) local bar = W.win.scrollBar(root, "Bar") W.rawOf[bar].Track = nil return bar end },
		{ "a side tab with all five fields", true, function(W, root) return W.win.sideTab(root, "Tab", nil, 1, "icon") end },
		{ "a side tab without TabGlow", false, function(W, root) local tab = W.win.sideTab(root, "Tab", nil, 1, "icon") W.rawOf[tab].TabGlow = nil return tab end },
		{ "a side tab without SelectedTexture", false, function(W, root) local tab = W.win.sideTab(root, "Tab", nil, 1, "icon") W.rawOf[tab].SelectedTexture = nil return tab end },
		{ "a side tab without Mask", false, function(W, root) local tab = W.win.sideTab(root, "Tab", nil, 1, "icon") W.rawOf[tab].Mask = nil return tab end },
		{ "a side tab without Background", false, function(W, root) local tab = W.win.sideTab(root, "Tab", nil, 1, "icon") W.rawOf[tab].Background = nil return tab end },
		{ "a side tab without Icon", false, function(W, root) local tab = W.win.sideTab(root, "Tab", nil, 1, "icon") W.rawOf[tab].Icon = nil return tab end },
		{ "a bottom tab", true, function(W, root) return W.win.panelTab(root, nil) end },
		{ "a bottom tab without LeftActive is taken for a push button: Left, Middle, Right and Text", true, function(W, root) local tab = W.win.panelTab(root, nil) W.rawOf[tab].LeftActive = nil return tab end },
		{ "a bottom tab without a texture list", false, function(W, root) local tab = W.win.panelTab(root, nil) W.rawOf[tab].TabTextures = nil return tab end },
		{ "a bottom tab with RotatedTextures instead of TabTextures", true, function(W, root) local tab = W.win.panelTab(root, nil) local r = W.rawOf[tab] r.RotatedTextures, r.TabTextures = r.TabTextures, nil return tab end },
		{ "a bottom tab without Left", false, function(W, root) local tab = W.win.panelTab(root, nil) W.rawOf[tab].Left = nil return tab end },
		{ "an item button with icon", true, function(W, root) return W.win.itemButton(root, "Slot", nil) end },
		{ "an item button with Icon in capitals", true, function(W, root) local b = W.win.itemButton(root, "Slot", nil) local r = W.rawOf[b] r.Icon, r.icon = r.icon, nil return b end },
		{ "an item button without IconBorder", false, function(W, root) local b = W.win.itemButton(root, "Slot", nil) W.rawOf[b].IconBorder = nil return b end },
		{ "an item button without an icon", false, function(W, root) local b = W.win.itemButton(root, "Slot", nil) W.rawOf[b].icon = nil return b end },
		{ "an item button without NormalTexture", false, function(W, root) local b = W.win.itemButton(root, "Slot", nil) W.rawOf[b].NormalTexture = nil return b end },
		{ "a push button", true, function(W, root) return W.win.panelButton(root, "Button", nil) end },
		{ "a push button without Text", false, function(W, root) local b = W.win.panelButton(root, "Button", nil) W.rawOf[b].Text = nil return b end },
		{ "a push button without Middle", false, function(W, root) local b = W.win.panelButton(root, "Button", nil) W.rawOf[b].Middle = nil return b end },
		{ "a push button without Right", false, function(W, root) local b = W.win.panelButton(root, "Button", nil) W.rawOf[b].Right = nil return b end },
		{ "a push button without Left", false, function(W, root) local b = W.win.panelButton(root, "Button", nil) W.rawOf[b].Left = nil return b end },
		{ "a three-slice button", true, function(W, root) return W.win.threeSlice(root, "Button", nil, "128-RedButton") end },
		{ "a three-slice button whose atlasName is a number", false, function(W, root) local b = W.win.threeSlice(root, "Button", nil, "128-RedButton") W.rawOf[b].atlasName = 5 return b end },
		{ "a three-slice button without atlasName", false, function(W, root) local b = W.win.threeSlice(root, "Button", nil, "128-RedButton") W.rawOf[b].atlasName = nil return b end },
		{ "a three-slice button without Center", false, function(W, root) local b = W.win.threeSlice(root, "Button", nil, "128-RedButton") W.rawOf[b].Center = nil return b end },
		{ "a progress bar", true, function(W, root) return W.win.progressBar(root, "Bar", nil) end },
		{ "a progress bar without SetFillPercent", false, function(W, root) local b = W.win.progressBar(root, "Bar", nil) W.rawOf[b].SetFillPercent = nil return b end },
		{ "a progress bar without Fill", false, function(W, root) local b = W.win.progressBar(root, "Bar", nil) W.rawOf[b].Fill = nil return b end },
		{ "a progress bar without Mask", false, function(W, root) local b = W.win.progressBar(root, "Bar", nil) W.rawOf[b].Mask = nil return b end },
		{ "a progress bar without Text", false, function(W, root) local b = W.win.progressBar(root, "Bar", nil) W.rawOf[b].Text = nil return b end },
		{ "a dropdown", true, function(W, root) return W.win.dropdown(root, "Drop", nil) end },
		{ "a dropdown without SetupMenu", false, function(W, root) local b = W.win.dropdown(root, "Drop", nil) W.rawOf[b].SetupMenu = nil return b end },
		{ "a dropdown without Background", false, function(W, root) local b = W.win.dropdown(root, "Drop", nil) W.rawOf[b].Background = nil return b end },
		{ "a dropdown without Text", false, function(W, root) local b = W.win.dropdown(root, "Drop", nil) W.rawOf[b].Text = nil return b end },
		{ "a dropdown with neither Arrow nor ResetButton", false, function(W, root) local b = W.win.dropdown(root, "Drop", nil) W.rawOf[b].Arrow = nil return b end },
		{ "a filter dropdown", true, function(W, root) return W.win.dropdown(root, "Drop", nil, true) end },
		{ "a check box", true, function(W, root) return W.win.checkButton(root, "Check", nil, 26) end },
		{ "a check box without a checked texture", false, function(W, root) local b = W.win.checkButton(root, "Check", nil, 26) W.rawOf[b].states.Checked = nil return b end },
		{ "a check box with an Icon", false, function(W, root) local b = W.win.checkButton(root, "Check", nil, 26) W.win.tex(b, "Icon", nil) return b end },
		{ "a check box with a lower-case icon", false, function(W, root) local b = W.win.checkButton(root, "Check", nil, 26) W.win.tex(b, "icon", nil) return b end },
		{ "a check box with a Name", false, function(W, root) local b = W.win.checkButton(root, "Check", nil, 26) W.win.font(b, "Name") return b end },
		{ "a text box", true, function(W, root) return W.win.editBox(root, "Edit", nil) end },
		{ "a text box without HighlightText", false, function(W, root) local b = W.win.editBox(root, "Edit", nil) W.rawOf[b].HighlightText = nil return b end },
		{ "a text box without Middle", false, function(W, root) local b = W.win.editBox(root, "Edit", nil) W.rawOf[b].Middle = nil return b end },
		{ "a text box without Left", false, function(W, root) local b = W.win.editBox(root, "Edit", nil) W.rawOf[b].Left = nil return b end },
		{ "a text box without Right", false, function(W, root) local b = W.win.editBox(root, "Edit", nil) W.rawOf[b].Right = nil return b end },
		{ "an inset", true, function(W, root) return W.win.inset(root, "Inset", nil) end },
		{ "an inset with another layoutType", false, function(W, root) local b = W.win.inset(root, "Inset", nil) W.rawOf[b].layoutType = "Dialog" return b end },
		{ "an inset without Bg", false, function(W, root) local b = W.win.inset(root, "Inset", nil) W.rawOf[b].Bg = nil return b end },
		{ "an inset without NineSlice", false, function(W, root) local b = W.win.inset(root, "Inset", nil) W.rawOf[b].NineSlice = nil return b end },
		{ "a close button known by its key alone", true, function(W, root) local b = W.win.closeButton(root, "CloseButton", nil) W.rawOf[W.rawOf[b].states.Normal].atlas = "other-art" return b end },
		{ "a close button known by its name alone", true, function(W, root) local b = W.win.closeButton(root, nil, "SomethingCloseButton") W.rawOf[W.rawOf[b].states.Normal].atlas = "other-art" return b end },
		{ "a close button known by its art alone", true, function(W, root) local b = W.win.closeButton(root, nil, nil) return b end },
		{ "a button with a normal texture that only contains the name of a close button's art", false, function(W, root) local b = W.win.closeButton(root, nil, nil) W.rawOf[W.rawOf[b].states.Normal].atlas = "Foo-RedButton-Exit" return b end },
		{ "a push button with a Center and no atlasName", false, function(W, root) local b = W.win.panelButton(root, "Button", nil) W.win.tex(b, "Center", nil) return b end },
		{ "a button whose name merely contains CloseButton", false, function(W, root) local b = W.win.closeButton(root, nil, "CloseButtonHolder") W.rawOf[b].states.Normal = nil return b end },
	}
	for _, case in ipairs(cases) do
		local styled, W = wstyled(function(W, root) return case[3](W, root) end)
		check("recognition: " .. case[1] .. (case[2] and " is styled" or " is left alone"), styled == case[2])
		check("recognition: " .. case[1] .. ": no error and no violation", #W.violations == 0 and #W.errors == 0 and #W.out == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end
end

do
	-- A window nested in a window is styled as a window, and what is in it is found.
	local styled, W, nested = wstyled(function(W, root)
		local frame = W.win.portraitFrame(root, "Nested", { name = "FlatUITestNested" }, "button")
		W.win.panelButton(frame, "Button", "FlatUITestNestedButton")
		return frame
	end)
	check("nested window: styled as a window with an outline and the window fill, its pieces transparent", W.state(nested) == "SB" and wa(W, wraw(W, wraw(W, nested).NineSlice).TopEdge) == 0)
	check("nested window: and the walk goes on inside it", W.state(W.env.FlatUITestNestedButton) == "SB")
	-- A NineSlice with seven pieces is not a window.
	local _, W2, partial = wstyled(function(W, root)
		local frame = W.win.portraitFrame(root, "Nested", { name = "FlatUITestNested" }, "button")
		W.rawOf[W.rawOf[frame].NineSlice].RightEdge = nil
		W.win.panelButton(frame, "Button", "FlatUITestNestedButton")
		return frame
	end)
	check("nested window: a NineSlice with seven pieces is not a window, but what is in it is still found", W2.state(partial) == "." and W2.state(W2.env.FlatUITestNestedButton) == "SB")
	local _, W3, bare = wstyled(function(W, root)
		local frame = W.win.portraitFrame(root, "Nested", { name = "FlatUITestNested" }, "base")
		local r = W.rawOf[frame]
		r.TitleContainer, r.CloseButton, r.PortraitContainer = nil, nil, nil
		return frame
	end)
	check("nested window: eight pieces and no title, close button or portrait is not a window", W3.state(bare) == ".")
	for _, field in ipairs({ "TitleContainer", "CloseButton", "PortraitContainer" }) do
		local _, W4, alone = wstyled(function(W, root)
			local frame = W.win.portraitFrame(root, "Nested", { name = "FlatUITestNested" }, "button")
			W.win.closeButton(frame, "CloseButton", nil)
			local r = W.rawOf[frame]
			for _, other in ipairs({ "TitleContainer", "CloseButton", "PortraitContainer" }) do
				if other ~= field then
					r[other] = nil
				end
			end
			return frame
		end)
		check("nested window: the NineSlice and " .. field .. " alone make a window", W4.state(alone) == "SB")
	end
end

-- 56. Controls the walk must not enter, and the limits of a sweep.
do
	local styled, W, made = wstyled(function(W, root)
		local cd = W.win.cooldown(root, "Cooldown", "FlatUITestCooldown")
		W.win.panelButton(cd, "Button", "FlatUITestInCooldown")
		local model, mr = W.win.frame(root, "Model", { name = "FlatUITestModel" })
		mr.SetDisplayInfo = function() end
		W.win.panelButton(model, "Button", "FlatUITestInModel")
		local scene, sr = W.win.frame(root, "Scene", { name = "FlatUITestScene" })
		sr.CreateActor = function() end
		W.win.panelButton(scene, "Button", "FlatUITestInScene")
		W.win.tex(scene, "Art", "UI-Character-Info-General-BG")
		W.win.tex(cd, "Art", "UI-HUD-ActionBar-Cooldown-Swipe")
		return cd
	end)
	check("walk: nothing is styled inside a Cooldown, a Model or a ModelScene, and their own art is not touched", not styled and W.state(W.env.FlatUITestInCooldown) == "." and W.state(W.env.FlatUITestInModel) == "."
		and W.state(W.env.FlatUITestInScene) == "." and wa(W, wraw(W, W.env.FlatUITestScene).Art) == 1)
	-- An edit box is not entered either: its children are its own business.
	local _, W2 = wstyled(function(W, root)
		local edit = W.win.editBox(root, "Edit", "FlatUITestEdit")
		W.win.panelButton(edit, "Button", "FlatUITestInEdit")
		return edit
	end)
	check("walk: an edit box is not entered", W2.state(W2.env.FlatUITestInEdit) == ".")
	-- A control is not entered either: only windows and insets hold other controls.
	local _, W3 = wstyled(function(W, root)
		local button = W.win.panelButton(root, "Button", "FlatUITestHolderButton")
		W.win.panelButton(button, "Inner", "FlatUITestInnerButton")
		local inset = W.win.inset(root, "Inset", "FlatUITestInset")
		W.win.panelButton(inset, "Inner", "FlatUITestInInset")
		return button
	end)
	check("walk: a push button is not entered, an inset is", W3.state(W3.env.FlatUITestInnerButton) == "." and W3.state(W3.env.FlatUITestInInset) == "SB")
end

do
	-- Depth: Walk(frame, depth) does nothing beyond depth 10, so a control that is a child of the tenth frame down is the last one found.
	local W = newWorld({ windows = { only = {} } })
	local root = W.win.frame(W.env.UIParent, nil, { name = "TradeFrame" })
	local parent = root
	local buttons = {}
	for level = 0, 12 do
		buttons[level] = W.win.panelButton(parent, nil, nil)
		parent = W.win.frame(parent, nil, {})
	end
	W.login()
	W.flush()
	local line = {}
	for level = 0, 12 do
		line[#line + 1] = W.state(buttons[level]) == "SB" and "x" or "."
	end
	check("depth: a button at each of thirteen levels, the first ten are found and the last three are not", table.concat(line) == "xxxxxxxxxx...", table.concat(line))
	check("depth: nothing raised", #W.violations == 0 and #W.errors == 0)
end

do
	-- Frames per sweep: the 1500th child is the last one visited.
	local function sweep(fillers, buttonsAfter)
		local W = newWorld({ windows = { only = {} } })
		local root = W.win.frame(W.env.UIParent, nil, { name = "TradeFrame" })
		local first = W.win.panelButton(root, nil, nil)
		local filler = {}
		for index = 1, fillers do
			filler[index] = W.win.frame(root, nil, {})
		end
		local after = {}
		for index = 1, buttonsAfter do
			after[index] = W.win.panelButton(root, nil, nil)
		end
		W.login()
		W.flush()
		local visited = 0
		for _, f in ipairs(filler) do
			if W.rawOf[f].calls.IsForbidden then
				visited = visited + 1
			end
		end
		local styledAfter = {}
		for index, b in ipairs(after) do
			styledAfter[index] = W.state(b) == "SB" and "x" or "."
		end
		return W, W.state(first), visited, table.concat(styledAfter)
	end
	local W, first, visited, after = sweep(1498, 3)
	check("limit: the first child is a button, 1498 plain frames follow, then three buttons: the 1500th child is visited and the 1501st is not", first == "SB" and visited == 1498 and after == "x..", first .. " " .. visited .. " " .. after)
	local W2, first2, visited2, after2 = sweep(1600, 2)
	check("limit: with 1600 frames only 1499 of them are visited and no button after them is found", first2 == "SB" and visited2 == 1499 and after2 == "..", visited2 .. " " .. after2)
	local W3, first3, visited3, after3 = sweep(1497, 3)
	check("limit: and one frame fewer, the first two buttons after them are found", visited3 == 1497 and after3 == "xx.", visited3 .. " " .. after3)
	check("limit: a sweep that ends at the limit raises nothing", #W.violations == 0 and #W.errors == 0 and #W2.violations == 0 and #W2.errors == 0)
	-- The limit is for one sweep of one window.
	local W4 = newWorld({ windows = { only = {} } })
	local a = W4.win.frame(W4.env.UIParent, nil, { name = "TradeFrame" })
	local b = W4.win.frame(W4.env.UIParent, nil, { name = "ItemTextFrame" })
	for _, root in ipairs({ a, b }) do
		for index = 1, 900 do
			W4.win.frame(root, nil, {})
		end
	end
	local last = W4.win.panelButton(a, nil, nil)
	local last2 = W4.win.panelButton(b, nil, nil)
	W4.login()
	W4.flush()
	check("limit: two windows of 900 frames each are both swept to the end", W4.state(last) == "SB" and W4.state(last2) == "SB")
end

do
	-- The addon's own frames and textures are never styled or faded when the sweep runs again.
	local W = winWorld({ lfg = "loaded" })
	local textures, frames = #W.addonTextures, #W.addonFrames
	local snapshot = {}
	for _, t in ipairs(W.addonTextures) do
		snapshot[t] = { t.calls.SetAlpha, t.alpha }
	end
	W.change("windows.opacity", 55)
	W.change("windows.opacity", 80)
	W.flush()
	W.fire("ADDON_LOADED", "Blizzard_GroupFinder_VanillaStyle")
	W.win.updateCategories(2)
	W.flush()
	local touched = 0
	for _, t in ipairs(W.addonTextures) do
		if t.calls.SetAlpha or t.alpha ~= 1 then
			touched = touched + 1
		end
	end
	check("own frames: no texture of the addon's had its alpha set, however often the windows were swept", touched == 0, touched)
	check("own frames: sweeping again made nothing new (two category buttons only)", #W.addonFrames - frames <= 2 * 1 and #W.addonTextures - textures <= 14, (#W.addonFrames - frames) .. " " .. (#W.addonTextures - textures))
	local holders = 0
	for _, f in ipairs(W.addonFrames) do
		if W.holderOn(f) then
			holders = holders + 1
		end
	end
	check("own frames: no outline was laid over any of the addon's own frames", holders == 0, holders)
	local dividerHost = W.win.names.CharacterFrameRightPaneHost
	local lines = 0
	for _, t in ipairs(wowned(W, dividerHost)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 and t.alpha == 1 then
			lines = lines + 1
		end
	end
	check("own frames: the divider the addon put on a stripped pane is not made transparent by the strip", lines == 1)
	clean(W, "own frames")
end

-- 57. A window opened with ShowUIPanel after login, a window that is loaded later, one that does not exist, and a global that does not exist.
do
	local W = winWorld()
	local names = W.win.names
	local friends = names.FriendsFrame
	-- Blizzard makes a button while the window opens, before the hook runs.
	local early = W.win.panelButton(friends, nil, "FlatUITestEarly")
	local late
	W.showPanel(friends, function()
		late = W.win.panelButton(friends, nil, "FlatUITestLate")
	end)
	check("ShowUIPanel: a button made while the window opens is styled by the hook at once", W.state(early) == "SB")
	check("ShowUIPanel: a button made after the hook ran is not styled yet", W.state(late) == ".")
	W.tick()
	check("ShowUIPanel: on the next frame the second sweep finds it", W.state(late) == "SB")
	local textures = #W.addonTextures
	W.showPanel(friends)
	W.tick()
	W.showPanel(friends)
	W.flush()
	check("ShowUIPanel: opening the window again makes nothing twice", #W.addonTextures == textures)
	-- A frame the module does not list.
	local before = #W.addonTextures
	local stray = W.win.frame(W.env.UIParent, nil, { name = "FlatUITestStrayWindow" })
	local strayButton = W.win.panelButton(stray, nil, nil)
	W.showPanel(stray)
	W.flush()
	check("ShowUIPanel: a frame that is not a listed window is not swept", W.state(strayButton) == "." and #W.addonTextures == before)
	-- The second sweep does not run once the module is off.
	local late2
	W.showPanel(friends, function() late2 = W.win.panelButton(friends, nil, "FlatUITestLate2") end)
	W.change("windows.enabled", false)
	W.tick()
	check("ShowUIPanel: the second sweep of a module that was switched off in between does nothing", W.state(late2) == ".")
	W.change("windows.enabled", true)
	check("ShowUIPanel: switched on again, the button is found at once", W.state(late2) == "SB")
	local count = #W.addonTextures
	W.change("windows.enabled", false)
	local late3
	W.showPanel(friends, function() late3 = W.win.panelButton(friends, nil, "FlatUITestLate3") end)
	W.flush()
	check("ShowUIPanel: with the module off the hook sweeps nothing", W.state(late3) == "." and #W.addonTextures == count)
	clean(W, "ShowUIPanel")
end

do
	-- Arguments the hook cannot trust.
	local W = winWorld({ hollowPanel = true })
	local before = #W.addonTextures
	W.env.ShowUIPanel(nil)
	W.env.ShowUIPanel(SECRET)
	W.env.ShowUIPanel("CharacterFrame")
	W.env.ShowUIPanel(5)
	W.env.ShowUIPanel(true)
	W.env.ShowUIPanel({})
	W.flush()
	check("ShowUIPanel: nil, a withheld value, a string, a number, a boolean and a table are ignored", #W.addonTextures == before and #W.errors == 0 and #W.violations == 0, table.concat(W.errors, "|"))
	W.env.ShowUIPanel(W.win.names.FriendsFrame)
	W.flush()
	check("ShowUIPanel: and a real window is still swept", #W.timers == 0 and #W.errors == 0)
end

do
	-- Load on demand: nothing exists at login, then the addon loads.
	local W = winWorld()
	check("load on demand: at login the frames of Looking For Group do not exist and nothing about them is made", W.env.LFGParentFrame == nil and W.env.LFGListingCategorySelection_UpdateCategoryButtons == nil)
	local hooks = W.hooks
	W.fire("ADDON_LOADED", "Blizzard_SomethingElse")
	W.fire("ADDON_LOADED", "Blizzard_TrainerUI")
	W.flush()
	check("load on demand: another addon's ADDON_LOADED is ignored, and the trainer's, whose window does not exist, does nothing", W.hooks == hooks and #W.errors == 0 and #W.violations == 0
		and not has(W.status(), "failed"))
	W.loadGroupFinder()
	W.flush()
	local lfg = W.env.LFGParentFrame
	check("load on demand: when the addon loads, the window is styled before it is ever opened", W.state(lfg) == "SB" and W.state(wraw(W, lfg).ListingTab and wraw(W, wraw(W, lfg).ListingTab).Icon) == "SB"
		and wa(W, wraw(W, W.env.LFGListingFrame).Bg) == 0)
	check("load on demand: and the hook on the category list was installed then", W.hooks - hooks == 1, W.hooks - hooks)
	W.win.updateCategories(2)
	check("load on demand: so the category buttons Blizzard makes are styled", W.state(wraw(W, wraw(W, W.win.categoryView).CategoryButtons[1]).Icon) == "SB")
	W.showPanel(lfg)
	W.flush()
	check("load on demand: and opening it afterwards changes nothing that was done", W.state(lfg) == "SB")
	-- The trainer, once it exists.
	local T = winWorld()
	local trainer = T.win.portraitFrame(T.env.UIParent, nil, { name = "ClassTrainerFrame" }, "button")
	local trainerButton = T.win.panelButton(trainer, nil, nil)
	T.fire("ADDON_LOADED", "Blizzard_TrainerUI")
	T.flush()
	check("load on demand: the trainer window is styled when its addon loads, with the group Vendor, mail, quest and trainer", T.state(trainer) == "SB" and T.state(trainerButton) == "SB")
	T.change("windows.npc", false)
	check("load on demand: and the trainer follows that group", T.state(trainer) == "hb")
	clean(W, "load on demand")
end

do
	-- Windows that do not exist, and globals that do not exist.
	local W = winWorld({ missing = { "MailFrame", "QuestFrame" } })
	check("a listed window that does not exist: the others are styled and there is no error and no failure", W.state(W.win.names.FriendsFrame) == "SB" and W.env.MailFrame == nil and W.env.QuestFrame == nil
		and #W.errors == 0 and #W.violations == 0 and not has(W.status(), "failed"))
	local N = winWorld({ only = { "CharacterFrame" } })
	check("a window that exists alone: the character window is styled by itself", N.state(N.win.names.CharacterFrame) == "SB" and #N.errors == 0)
	local G = newWorld({ windows = true })
	G.env.SetItemButtonBorder = nil
	G.env.SetItemButtonNormalTextureVertexColor = nil
	G.login()
	G.flush()
	local head = G.win.names.CharacterHeadSlot
	G.blizzard(function() G.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6) end)
	local o = G.look(head)
	check("a global that does not exist: the other item hooks are still made and work", o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) == "0.20,0.40,0.60" and #G.errors == 0 and #G.violations == 0)
	local base = newWorld()
	base.login()
	check("a global that does not exist: two of the five global hooks are missing, so the others are 5 - 2", G.hooks - base.hooks == 3, G.hooks - base.hooks)
	local P = newWorld({ windows = true })
	P.env.ShowUIPanel = nil
	P.login()
	P.flush()
	check("a global that does not exist: without ShowUIPanel the windows are still styled at login", P.state(P.win.names.FriendsFrame) == "SB" and #P.errors == 0 and #P.violations == 0)
	local H = newWorld({ windows = true, without = { hooksecurefunc = true } })
	H.login()
	H.flush()
	check("a client without hooksecurefunc: the windows are still styled and nothing raises", H.state(H.win.names.FriendsFrame) == "SB" and H.state(wraw(H, H.win.names.CharacterFrameModeTab2).Icon) == "SB" and #H.errors == 0
		and not has(H.line("Windows"), "stopped"), table.concat(H.errors, "|") .. tostring(H.line("Windows")))
end


-- 58. Every option of the Windows page, changed through its control: the look, and Blizzard's look back exactly when it is off.
local function wscene(saved, more, prep)
	local W = newWorld({ windows = { extras = true, lfg = "loaded", second = true, more = more }, saved = saved })
	if prep then
		prep(W)
	end
	W.login()
	W.win.updateCategories(3)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	W.updateSlot("CharacterChestSlot", { quality = 2, broken = true })
	W.updateSlot("CharacterNeckSlot", { quality = 3 })
	W.flush()
	return { W = W, N = W.win.names }
end
local function wN(S, name) return S.N[name] or S.W.env[name] end
local function wst(S, name) return S.W.state(wN(S, name)) end
local function walpha(S, frame, key) return g(wa(S.W, wraw(S.W, wN(S, frame))[key])) end
local function wnine(S, frame) return g(wa(S.W, wraw(S.W, wraw(S.W, wN(S, frame)).NineSlice).TopEdge)) end
local function wfillAlpha(S, target) local c = wfill(S.W, target) return c and g(c[4]) or "none" end
local function wedge(S, name)
	local o = S.W.look(wN(S, name))
	return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) or "none"
end
local function wlineShown(S, name, layer)
	local lines = wlines(S.W, wN(S, name), layer)
	local shown = 0
	for _, l in ipairs(lines) do
		shown = shown + (l.shown and 1 or 0)
	end
	return shown .. "/" .. #lines
end
local function wlineShownOf(S, owner)
	local shown, all = 0, wlines(S.W, owner, "OVERLAY")
	for _, l in ipairs(all) do
		shown = shown + (l.shown and 1 or 0)
	end
	return shown .. "/" .. #all
end
local function wcategory(S, index)
	local button = wraw(S.W, S.W.win.categoryView).CategoryButtons[index]
	return button, wraw(S.W, button)
end

do local IP = {}
-- The items of the probes of Window titles and item slots: an epic weapon in the first bag slot and an epic head piece.
function IP.prep(W)
	W.items.bag["0:1"] = { hyperlink = "item:bag1", quality = 4, hasNoValue = false, stackCount = 1 }
	W.items.class["item:bag1"], W.items.level["item:bag1"], W.items.quality["item:bag1"] = 4, 215, 4
	W.items.equipped[1] = "item:head"
	W.items.class["item:head"], W.items.level["item:head"], W.items.quality["item:head"] = 4, 200, 4
end
function IP.junk(W)
	W.items.bag["0:1"] = { hyperlink = "item:junk", quality = 0, hasNoValue = false, stackCount = 1 }
end
-- The new item glow and its flash on the first bag slot, shown by the game each time the bag updates its items.
function IP.glow(W)
	local slot, bag = W.win.names.ContainerFrame1Item1, W.win.names.ContainerFrame1
	local was = W.group
	W.group = "windows"
	W.win.tex(slot, "NewItemTexture", nil, { hidden = true })
	W.win.tex(slot, "flash", nil, {})
	W.group = was
	W.seal()
	wraw(W, bag).UpdateItems = function() wraw(W, wraw(W, slot).NewItemTexture).shown = true end
end
function IP.title(S, name) return wraw(S.W, wraw(S.W, wraw(S.W, wN(S, name)).TitleContainer).TitleText) end
function IP.size(raw) return g(raw.font and raw.font[2] or 12) end
function IP.colour(raw)
	local c = raw.textColour or { 1, 1, 1 }
	return string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3])
end
function IP.text(S, name)
	for _, t in ipairs(S.W.addonFonts) do
		if t.owner == wN(S, name) then
			return t
		end
	end
end
function IP.level(S, name)
	local t = IP.text(S, name)
	return t and t.shown and t.text or "none"
end
