-- The button of a bag window or the bank: its point, its offset and whether it is shown, or "none" when the window has no button.
function TOC.sortLine(S, name)
	local parent = S.W.env[name]
	for _, f in ipairs(S.W.addonFrames) do
		local raw = S.W.rawOf[f]
		if raw.parent == parent and raw.mouse and raw.width == 16 and raw.height == 16 then
			local p = raw.points[1]
			return (p and (p[1] .. "/" .. g(p[4]) .. "," .. g(p[5])) or "unplaced") .. "/" .. (raw.shown and "shown" or "hidden")
		end
	end
	return "none"
end
local WPROBED = {}
for _, P in ipairs(W_PROBES) do
	local path, to, read, base, changed = P[1], P[2], P[3], P[4], P[5]
	WPROBED[path] = true
	local row = ROW[path]
	local S = wscene(P.saved, P.more, P.prep)
	local W = S.W
	local label = path .. (type(to) == "string" and (" " .. to) or (" " .. tostring(to)))
	local ok, start = pcall(read, S)
	check(label .. ": at the start", ok and start == base, start)
	W.change(path, to)
	W.flush()
	local _, now = pcall(read, S)
	check(label .. ": through its control", now == changed, now)
	W.change(path, P.from or row.default)
	W.flush()
	local _, back = pcall(read, S)
	check(label .. ": and back", back == base, back)
	W.change(path, to)
	W.flush()
	local _, again = pcall(read, S)
	check(label .. ": and again", again == changed, again)
	check(label .. ": no violations, errors or messages", #W.violations == 0 and #W.errors == 0 and #W.out == 0, table.concat(W.violations, "|") .. table.concat(W.out, "|"))
end
for _, row in ipairs(ALL) do
	if row.page == "windows" and row.path ~= "windows.slotTints" and row.live ~= true then
		check("window probes: " .. row.path .. " has one", WPROBED[row.path] == true)
	end
end end


-- 59. The dependencies of the page, and an option turned off through its control gives Blizzard's look exactly as if it had been off from the start.
do
	local S = wscene()
	local W = S.W
	local function agree(label)
		local wrong = {}
		for _, row in ipairs(ALL) do
			if row.page == "windows" and W.enabled(row.path) ~= usable(W, row) then
				wrong[#wrong + 1] = row.path .. "=" .. tostring(W.enabled(row.path))
			end
		end
		check("dependencies: " .. label, #wrong == 0, table.concat(wrong, " "))
	end
	W.openPanel()
	agree("every control is usable at the start")
	check("dependencies: the quality, crop and flat highlight settings and the square tab setting are usable", W.enabled("windows.quality") and W.enabled("windows.crop") and W.enabled("windows.slotTints") and W.enabled("windows.squareTabs"))
	check("sidetab: Side tab size is usable while the side tabs are on", W.enabled("windows.sideTabSize") == true)
	W.change("windows.slots", false)
	agree("item slots off")
	check("dependencies: quality colour and flat highlights are greyed with the slots, icon crop and the others are not", not W.enabled("windows.quality") and W.enabled("windows.crop") and not W.enabled("windows.slotTints")
		and W.enabled("windows.squareTabs") and W.enabled("windows.buttons"))
	W.change("windows.sideTabs", false)
	agree("item slots and side tabs off")
	check("dependencies: square tab icons are greyed with the side tabs", not W.enabled("windows.squareTabs"))
	check("sidetab: Side tab size is greyed with the side tabs", W.enabled("windows.sideTabSize") == false)
	W.change("windows.slots", true)
	check("dependencies: and the slot settings are usable again as soon as the slots are on", W.enabled("windows.quality") and W.enabled("windows.crop") and W.enabled("windows.slotTints") and not W.enabled("windows.squareTabs"))
	W.change("windows.sideTabs", true)
	W.change("windows.enabled", false)
	agree("the whole page off")
	local usableCount = 0
	for _, row in ipairs(ALL) do
		if row.page == "windows" and row.live ~= true and W.enabled(row.path) then
			usableCount = usableCount + 1
		end
	end
	check("dependencies: with the page off only its own switch is usable", usableCount == 1 and W.enabled("windows.enabled"), usableCount)
	W.change("windows.enabled", true)
	agree("the page on again")
	W.change("windows.slots", false)
	W.change("windows.enabled", false)
	W.change("windows.enabled", true)
	agree("the page switched off and on with the slots off")
	check("dependencies: and the slot settings are still greyed", not W.enabled("windows.quality"))
	W.defaults()
	agree("after Defaults")
	check("dependencies: a control of another page stays usable: the general settings", W.enabled("general.thickness") and W.enabled("general.backdrop"))
end

-- What the Blizzard side of the windows looks like, region by region, and how many of the addon's textures are visible.
local function wdump(W, ignore)
	local map = {}
	for _, r in ipairs(W.blizzRegions) do
		if r.group == "windows" and r.fname then
			local c = {}
			c[#c + 1] = "a=" .. g(r.alpha)
			c[#c + 1] = "s=" .. tostring(r.shown)
			local tc = r.texCoord and table.concat(r.texCoord, ",") or "-"
			c[#c + 1] = "t=" .. (tc == "0,1,0,1" and "-" or tc)
			c[#c + 1] = "v=" .. (r.vertex and table.concat(r.vertex, ",") or "-")
			c[#c + 1] = "b=" .. tostring(r.blend)
			local masks = {}
			for mask in pairs(r.masks or {}) do
				masks[#masks + 1] = tostring(W.rawOf[mask].fname)
			end
			table.sort(masks)
			c[#c + 1] = "m=" .. table.concat(masks, "+")
			c[#c + 1] = "w=" .. g(r.width) .. "x" .. g(r.height)
			if not ignore then
				c[#c + 1] = "c=" .. (r.color and table.concat(r.color, ",") or "-")
				c[#c + 1] = "p=" .. #r.points .. tostring(r.allPoints ~= nil)
			end
			map[r.fname] = table.concat(c, " ")
		end
	end
	for _, f in ipairs(W.blizzFrames) do
		if f.group == "windows" and f.fname then
			map["frame " .. f.fname] = "a=" .. g(f.alpha) .. " s=" .. tostring(f.shown)
		end
	end
	return map
end
local function wvisible(W)
	local n = 0
	for _, t in ipairs(W.addonTextures) do
		if t.shown and not (t.color and t.color[4] == 0) then
			n = n + 1
		end
	end
	return n
end
local function wsame(a, b)
	local wrong = {}
	for name, text in pairs(a) do
		if b[name] ~= text then
			wrong[#wrong + 1] = name .. ": " .. text .. " | " .. tostring(b[name])
		end
	end
	for name in pairs(b) do
		if a[name] == nil then
			wrong[#wrong + 1] = name .. ": missing"
		end
	end
	table.sort(wrong)
	return wrong
end

do
	-- The module off: Blizzard's regions are exactly what they would be if the module had never been on.
	local never = wscene({ options = { ["windows.enabled"] = false } })
	local S = wscene()
	S.W.change("windows.enabled", false)
	S.W.flush()
	local wrong = wsame(wdump(never.W, true), wdump(S.W, true))
	check("module off through its switch: every Blizzard region has the alpha, visibility, coordinates, colour, masks and size it would have had with the module off from the start", #wrong == 0,
		#wrong .. " " .. table.concat(wrong, "; "):sub(1, 500))
	check("module off through its switch: the same number of the addon's textures is visible as with the module off from the start", wvisible(S.W) == wvisible(never.W), wvisible(S.W))
	local residue = wsame(wdump(never.W), wdump(S.W))
	check("module off through its switch: what is left is the recolouring of state textures, which only /reload undoes", #residue > 0 and #residue < 200, #residue)
	-- On again: the same as before it was turned off.
	local again = wscene()
	again.W.change("windows.enabled", false)
	again.W.change("windows.enabled", true)
	again.W.flush()
	local first = wscene()
	local wrongOn = wsame(wdump(first.W), wdump(again.W))
	check("module on again: every Blizzard region is as it was when the module first started", #wrongOn == 0, #wrongOn .. " " .. table.concat(wrongOn, "; "):sub(1, 400))
	check("module on again: nothing was made twice", #again.W.addonTextures == #first.W.addonTextures and #again.W.addonFrames == #first.W.addonFrames)
end

do
	for _, row in ipairs(ALL) do
		if row.page == "windows" and row.kind == "bool" and row.path ~= "windows.enabled" and row.live ~= true then
			local never, S
			if row.default then
				never = wscene({ options = { [row.path] = false } })
				S = wscene()
				S.W.change(row.path, false)
			else
				never = wscene()
				S = wscene({ options = { [row.path] = true } })
				S.W.change(row.path, false)
			end
			S.W.flush()
			local wrong = wsame(wdump(never.W, true), wdump(S.W, true))
			check(row.path .. " off through its control: Blizzard's regions are as if it had been off from the start", #wrong == 0, #wrong .. " " .. table.concat(wrong, "; "):sub(1, 400))
			check(row.path .. " off through its control: the addon's visible textures are the same", wvisible(S.W) == wvisible(never.W), wvisible(S.W) .. " " .. wvisible(never.W))
		end
	end
end

do
	-- Flat highlights apply once: switched off later, they stay until /reload; switched on later, they are applied.
	local S = wscene({ options = { ["windows.slotTints"] = false } })
	local W = S.W
	local head = wN(S, "CharacterHeadSlot")
	local h = wraw(W, head)
	check("flat highlights off at login: the Highlight and Pushed slots are left as they are", wraw(W, h.states.Highlight).color == nil and wraw(W, h.states.Pushed).color == nil)
	W.change("windows.slotTints", true)
	check("flat highlights switched on: the Highlight slot is a white tint over the button, the Pushed slot a yellow one", wc(wraw(W, h.states.Highlight).color) == "1.000,1.000,1.000,0.3" and wc(wraw(W, h.states.Pushed).color) == "0.900,0.800,0.100,0.3"
		and wraw(W, h.states.Highlight).allPoints == head)
	W.change("windows.slotTints", false)
	check("flat highlights switched off again: they stay until the interface is reloaded", wraw(W, h.states.Highlight).color ~= nil)
	local calls = wraw(W, h.states.Highlight).calls.SetColorTexture
	W.change("windows.slotTints", true)
	W.change("windows.opacity", 55)
	check("flat highlights: switching on again does not recolour them again", wraw(W, h.states.Highlight).calls.SetColorTexture == calls)
	clean(W, "flat highlights")
end


-- 60. The module off at login, turned on later, and turned off again.
do
	local base = newWorld()
	base.login()
	local W = newWorld({ windows = { extras = true, lfg = "loaded" }, saved = { options = { ["windows.enabled"] = false } } })
	W.login()
	W.win.updateCategories(3)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	W.flush()
	local names = W.win.names
	local owned = 0
	for _, t in ipairs(W.addonTextures) do
		local o = t.owner and W.rawOf[t.owner]
		if o and o.group == "windows" then
			owned = owned + 1
		end
	end
	local ownedFrames = 0
	for _, f in ipairs(W.addonFrames) do
		local o = f.parent and W.rawOf[f.parent]
		if o and o.group == "windows" then
			ownedFrames = ownedFrames + 1
		end
	end
	check("module off at login: the addon made no texture and no frame on any window", owned == 0 and ownedFrames == 0, owned .. " " .. ownedFrames)
	local changed = {}
	for _, line in ipairs(wdiff(W)) do
		if line:find(" alpha: ", 1, true) or line:find(" texCoord: ", 1, true) or line:find(" masks: ", 1, true) or line:find(" color: ", 1, true) or line:find(" allPoints: ", 1, true) or line:find(" points: ", 1, true) then
			changed[#changed + 1] = line
		end
	end
	check("module off at login: not one Blizzard region has a different alpha, coordinates, masks, colour or anchor than the client gave it", #changed == 0, table.concat(changed, "; "):sub(1, 300))
	check("module off at login: nothing is hooked", W.hooks == base.hooks, W.hooks - base.hooks)
	check("module off at login: the status says off", W.line("Windows") == "Windows: off", W.line("Windows"))
	local made = #W.addonTextures
	W.win.choose(3, names.CharacterFrame)
	W.showPanel(names.FriendsFrame)
	W.flush()
	check("module off at login: Blizzard going about its work, and a window being opened, make nothing and change nothing of the addon's", #W.addonTextures == made and #W.addonFrames == #W.addonFrames and #W.errors == 0
		and #W.violations == 0)
	local before = #W.addonTextures
	W.change("windows.enabled", true)
	W.flush()
	local styled = tonumber(W.status():match("Windows: on, (%d+) styled"))
	check("turned on later: the windows are styled, and the status counts them", styled and styled > 100 and W.state(names.CharacterFrame) == "SB" and W.state(names.LFGParentFrame) == "SB", W.line("Windows"))
	check("turned on later: the item functions, the tabs and the panel are followed from then on", W.hooks - base.hooks == 6, W.hooks - base.hooks)
	check("turned on later: the quality colour of an item that was on before is picked up", (function()
		local o = W.look(names.CharacterHeadSlot)
		return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) == "0.64,0.21,0.93"
	end)())
	check("turned on later: the selected tab is the one Blizzard selected", wtints(W, names.CharacterFrameModeTab3, "OVERLAY")[1].shown and not wtints(W, names.CharacterFrameModeTab1, "OVERLAY")[1].shown)
	W.win.updateCategories(4)
	check("turned on later: the category buttons Blizzard makes afterwards are styled", W.state(wraw(W, wraw(W, W.win.categoryView).CategoryButtons[4]).Icon) == "SB")
	check("turned on later: it did not run twice", #W.addonTextures > before and #W.errors == 0 and #W.violations == 0)
	local textures = #W.addonTextures
	W.change("windows.enabled", false)
	W.flush()
	local tab4 = wraw(W, names.CharacterFrameModeTab4)
	W.win.choose(4, names.CharacterFrame)
	W.updateSlot("CharacterHeadSlot", { quality = 2 })
	W.updateSlot("CharacterNeckSlot", { quality = 5, broken = true })
	W.showPanel(names.FriendsFrame)
	W.win.updateCategories(5)
	W.flush()
	check("turned off again: a tab Blizzard selects later keeps its crop-free icon and shows its own selection, with no tint of the addon's", wtc(W, tab4.Icon) == "0.03125,0.96875,0.03125,0.96875"
		and wraw(W, tab4.SelectedTexture).shown and wa(W, tab4.SelectedTexture) == 1 and not wtints(W, names.CharacterFrameModeTab4, "OVERLAY")[1].shown)
	check("turned off again: an item Blizzard updates later shows its own border, with no coloured edge", wa(W, wraw(W, names.CharacterHeadSlot).IconBorder) == 1 and W.state(names.CharacterHeadSlot) == "hb"
		and (function() local o = W.look(names.CharacterNeckSlot) return o and o.hidden end)())
	check("turned off again: a category button made later is left as Blizzard drew it", wa(W, wraw(W, wraw(W, W.win.categoryView).CategoryButtons[5]).Cover) == 1 and #wowned(W, wraw(W, W.win.categoryView).CategoryButtons[5]) == 0)
	check("turned off again: nothing new was made", #W.addonTextures == textures)
	W.change("windows.enabled", true)
	W.flush()
	check("turned on again: the windows are styled again and the item that changed has its new colour", W.state(names.CharacterFrame) == "SB" and (function()
		local o = W.look(names.CharacterHeadSlot)
		return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) == "0.12,1.00,0.00"
	end)() and wtints(W, names.CharacterFrameModeTab4, "OVERLAY")[1].shown, W.state(names.CharacterFrame) .. " " .. (function() local o = W.look(names.CharacterHeadSlot) return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) or "nil" end)() .. " " .. tostring(wtints(W, names.CharacterFrameModeTab4, "OVERLAY")[1].shown))
	check("turned on again: only the category button made in the meantime is new", #W.addonTextures - textures <= 8, #W.addonTextures - textures)
	clean(W, "module lifecycle")
end

-- 61. Combat: nothing is created or anchored on a protected frame until combat ends; what is allowed in combat still happens.
do
	local function combatWorld(extra)
		local o = { windows = extra or true, combat = true }
		local W = newWorld(o)
		return W
	end
	-- Login in combat with the character window protected.
	local W = newWorld({ windows = true, combat = true })
	local cf = W.win.names.CharacterFrame
	W.win.protect(cf, true)
	W.login()
	W.flush()
	local names = W.win.names
	check("login in combat: a protected window is not given an outline, a box or a line until combat ends, and nothing raises", W.state(cf) == "." and #wowned(W, cf) == 0 and #W.violations == 0, table.concat(W.violations, "|"):sub(1, 300))
	check("login in combat: the windows that are not protected are styled at once", W.state(names.FriendsFrame) == "SB" and W.state(names.MerchantFrame) == "SB")
	check("login in combat: the controls of a protected window are not styled either", W.state(names.CharacterHeadSlot) == "." and #wowned(W, names.CharacterFrameCloseButton) == 0 and #wboxes(W, names.PaperDollSidebarTab1) == 0)
	check("login in combat: the art of a protected window becomes transparent at once, since that is allowed", wa(W, wraw(W, wraw(W, cf).NineSlice).TopEdge) == 0 and wa(W, wraw(W, names.CharacterHeadSlot).NormalTexture) == 0,
		"the design says fading does not wait")
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("combat ends: the protected window and its controls are styled", W.state(cf) == "SB" and W.state(names.CharacterHeadSlot) == "SB" and #wlines(W, names.CharacterFrameCloseButton, "OVERLAY") == 2)
	check("combat ends: with no violation and nothing made twice", #W.violations == 0 and #W.errors == 0 and #wowned(W, cf) == 1)
	local textures = #W.addonTextures
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("combat ends again: nothing more happens", #W.addonTextures == textures)
	clean(W, "combat at login")
end

do
	-- Combat starts after the windows are styled.
	local W = newWorld({ windows = { extras = true }, saved = { options = { ["windows.slotTints"] = false } } })
	W.win.protect(W.win.names.CharacterFrame, true)
	W.login()
	W.flush()
	local names = W.win.names
	local button = names.PaperDollEquipmentManagerPaneEquipSet
	local head = names.CharacterHeadSlot
	W.combat = true
	W.change("windows.buttons", false)
	W.flush()
	check("an option changed in combat: the protected button gives its art back at once and its box is hidden", wa(W, wraw(W, button).Left) == 1 and W.state(button) == "hb", W.state(button))
	W.change("windows.buttons", true)
	W.flush()
	check("an option changed in combat: and takes it away again at once", wa(W, wraw(W, button).Left) == 0 and W.state(button) == "SB")
	W.change("windows.opacity", 30)
	W.change("windows.panel", "ff336699")
	W.change("windows.accent", "ff994422")
	W.flush()
	check("an option changed in combat: colours change on protected frames too", wcolour(wfill(W, button)) == "0.200,0.400,0.600,1" and wcolour(wfill(W, names.CharacterFrame)):find(",0.3$") ~= nil)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	local o = W.look(head)
	check("an item updated in combat: the edge of a protected slot takes the colour at once", o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) == "0.64,0.21,0.93")
	W.change("windows.slotTints", true)
	W.flush()
	check("flat highlights switched on in combat: a protected slot waits for the end of combat", wraw(W, wraw(W, head).states.Highlight).color == nil)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("flat highlights: and gets them when combat ends", wc(wraw(W, wraw(W, head).states.Highlight).color) == "1.000,1.000,1.000,0.3")
	W.combat = true
	local tab3 = names.CharacterFrameModeTab3
	W.win.choose(3, names.CharacterFrame)
	check("a tab selected in combat: the selected tint moves at once and the icon is cropped again", wtints(W, tab3, "OVERLAY")[1].shown and wtc(W, wraw(W, tab3).Icon) == "0.10625,0.89375,0.10625,0.89375")
	W.win.collapse(true, names.CharacterFrame)
	check("the pane toggle in combat: the chevron follows", wsegments(wlines(W, names.CharacterFrameRightPaneToggleButton, "OVERLAY")) == RIGHT_SHAPE)
	local divider
	for _, t in ipairs(wowned(W, names.CharacterFrameRightPaneHost)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 then
			divider = t
		end
	end
	local widthBefore = divider.width
	W.gameScale(0.5)
	W.flush()
	check("a new UI scale in combat: lengths are worked out when combat ends, as everywhere else in the addon", divider.width == widthBefore)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("a new UI scale in combat: and the divider has its new width then", near(divider.width, 768 / 1080 / 0.5, 1e-6), g(divider.width))
	check("combat: no violation anywhere", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"):sub(1, 300))
end

do
	-- A window opened in combat after it was swept: what is not protected is styled, what is waits.
	local W = winWorld()
	local names = W.win.names
	local friends = names.FriendsFrame
	local protectedButton = W.win.panelButton(friends, nil, "FlatUITestProtectedButton")
	W.win.protect(protectedButton, true)
	local openButton = W.win.panelButton(friends, nil, "FlatUITestOpenButton")
	W.combat = true
	W.showPanel(friends)
	W.flush()
	check("ShowUIPanel in combat: a new protected button is not styled yet, a new button that is not protected is", W.state(protectedButton) == "." and W.state(openButton) == "SB" and #W.violations == 0, table.concat(W.violations, "|"):sub(1, 300))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("ShowUIPanel in combat: and the protected one is styled when combat ends", W.state(protectedButton) == "SB")
end

do
	-- Protected pieces: the divider, check boxes, a tab whose parent is protected.
	local W = newWorld({ windows = true, combat = true })
	local names = W.win.names
	W.win.protect(names.CharacterFrameRightPaneHost, true)
	W.win.protect(names.ReputationFrameFilterDropdown, true)
	W.login()
	W.flush()
	local pane = names.CharacterFrameRightPaneHost
	local dividers = 0
	for _, t in ipairs(wowned(W, pane)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 then
			dividers = dividers + 1
		end
	end
	check("login in combat: a divider on a protected pane is not made until combat ends", dividers == 0 and #W.violations == 0, table.concat(W.violations, "|"):sub(1, 300))
	check("login in combat: a protected dropdown waits and one that is not protected does not", W.state(names.ReputationFrameFilterDropdown) == "." and W.state(names.FriendsFrameStatusDropdown) == "SB")
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	dividers = 0
	for _, t in ipairs(wowned(W, pane)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 then
			dividers = dividers + 1
		end
	end
	check("combat ends: the divider is made, once", dividers == 1 and W.state(names.ReputationFrameFilterDropdown) == "SB")
	clean(W, "protected pieces")
end

do
	-- A text box is outlined by its parent. When the box is not protected and its parent is, nothing may be created on the parent in combat.
	local W = newWorld({ windows = { extras = true }, combat = true })
	local box = W.win.editBox
	local parent = W.rawOf[box].parent
	W.win.protect(parent, true)
	W.win.protect(box, false)
	W.login()
	W.flush()
	check("text box in combat: the parent is protected, so no box and no outline are made on it until combat ends", #wboxes(W, parent) == 0 and #W.violations == 0, table.concat(W.violations, "|"):sub(1, 300))
end

do
	-- The order and the errors of what waited for combat.
	local W = newWorld({ windows = true, combat = true })
	W.win.protect(W.win.names.CharacterFrame, true)
	W.login()
	W.flush()
	local queued = 0
	W.ns.OutOfCombat(function() queued = queued + 1 end)
	W.ns.OutOfCombat(function() error("a queued call failed", 0) end)
	W.ns.OutOfCombat(function() queued = queued + 10 end)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("combat ends: a queued call that fails is reported and the ones after it still run", queued == 11 and #W.errors == 1 and W.errors[1] == "a queued call failed" and W.state(W.win.names.CharacterFrame) == "SB", table.concat(W.errors, "|"))
end


-- 62. Forbidden frames: skipped, and never read.
-- A world with the windows built; `prep` marks things before the addon starts.
local function fw(opts, prep)
	local W = newWorld({ windows = opts or true })
	if prep then
		prep(W, W.win.names)
	end
	W.login()
	W.flush()
	return W, W.win.names
end
local function wf(W, x) return W.rawOf[x] end
local function wvio(W) return table.concat(W.violations, " | "):sub(1, 400) end

do
	local W, names = fw(true, function(W, n) wf(W, n.CharacterFrame).forbidden = true end)
	check("forbidden window: the window is not styled and nothing of it was read", W.state(names.CharacterFrame) == "." and #W.violations == 0, wvio(W))
	check("forbidden window: the other windows are styled", W.state(names.FriendsFrame) == "SB" and W.state(names.MerchantFrame) == "SB" and W.state(names.CharacterHeadSlot) == ".")
	check("forbidden window: and nothing of the character window's controls was styled through the globals", #wowned(W, names.PaperDollSidebarTab1) == 0 and #wowned(W, names.CharacterAmmoSlot) == 0)
	check("forbidden window: no error, no failure counted", #W.errors == 0 and not has(W.line("Windows"), "failed"), W.line("Windows"))
end

do
	local W, names = fw(true, function(W, n)
		wf(W, n.FriendsFrameAddFriendButton).forbidden = true
		wf(W, n.FriendsFrameTab1).forbidden = true
		wf(W, n.FriendsFrameCloseButton).forbidden = true
		wf(W, n.FriendsFrameStatusDropdown).forbidden = true
		wf(W, wf(W, n.FriendsFrame).Inset).forbidden = true
		wf(W, wf(W, n.FriendsFrame).ScrollBar).forbidden = true
		wf(W, n.CharacterHeadSlot).forbidden = true
		wf(W, n.PaperDollSidebarTab2).forbidden = true
		wf(W, n.CharacterFrameModeTab3).forbidden = true
		wf(W, wf(W, n.ReputationDetailFrame).AtWarCheckbox).forbidden = true
		wf(W, n.ReputationBar1).forbidden = true
		wf(W, n.MerchantItem2).forbidden = true
		wf(W, n.MerchantRepairAllButton).forbidden = true
		wf(W, n.CharacterFrameRightPaneToggleButton).forbidden = true
		wf(W, n.CharacterAmmoSlot).forbidden = true
	end)
	check("forbidden controls: no read of any of them", #W.violations == 0, wvio(W))
	check("forbidden controls: a forbidden button, tab, close button, dropdown, inset, scroll bar, slot, side tab, check box, bar, vendor cell and button are skipped",
		W.state(names.FriendsFrameAddFriendButton) == "." and #wboxes(W, names.FriendsFrameTab1) == 0 and #wowned(W, names.FriendsFrameCloseButton) == 0 and W.state(names.FriendsFrameStatusDropdown) == "."
		and W.state(names.CharacterHeadSlot) == "." and #wowned(W, names.ReputationBar1) == 0 and W.state(names.MerchantRepairAllButton) == ".")
	check("forbidden controls: a forbidden vendor cell keeps the art behind its item, the next cell does not", wa(W, wf(W, names.MerchantItem2).SlotTexture) == 1 and wa(W, wf(W, names.MerchantItem1).SlotTexture) == 0)
	check("forbidden controls: their neighbours are styled", W.state(names.FriendsFrameSendMessageButton) == "SB" and #wboxes(W, names.FriendsFrameTab3) == 1 and W.state(names.CharacterNeckSlot) == "SB"
		and W.state(wraw(W, names.PaperDollSidebarTab1).Icon) == "SB" and W.state(wraw(W, names.PaperDollSidebarTab3).Icon) == "SB" and W.state(names.MerchantItem1) == "." and W.state(wf(W, names.MerchantItem1).ItemButton) == "SB")
	check("forbidden controls: the window around them is styled", W.state(names.FriendsFrame) == "SB" and W.state(names.CharacterFrame) == "SB")
	check("forbidden controls: not one of them counts as a failure", not has(W.line("Windows"), "failed") and #W.errors == 0 and not has(W.status(), "stopped"), W.line("Windows"))
end

do
	-- A forbidden page: the strips reach the page's children through a path that begins at the page.
	local W, names = fw({ lfg = "loaded" }, function(W, n) wf(W, n.LFGListingFrame).forbidden = true end)
	check("forbidden page: it is skipped", W.state(names.LFGListingFrame) == "." and W.state(names.LFGParentFrame) == "SB")
	check("forbidden page: and none of its fields is read to get at its parts", #W.violations == 0, wvio(W))
	check("forbidden page: the other pages are done", wa(W, wraw(W, wraw(W, names.LFGBrowseFrame).NineSlice).TopEdge) == 0)
end

do
	-- A forbidden frame in the middle of a path.
	local W, names = fw(true, function(W, n) wf(W, n.CharacterFrameLeftPaneHost).forbidden = true wf(W, n.CharacterFrameRightPaneHost).forbidden = true end)
	check("forbidden pane: a pane that is forbidden is skipped by the strips and the divider, nothing is read", #W.violations == 0 and #wowned(W, names.CharacterFrameRightPaneHost) == 0, wvio(W))
end

-- 63. Values the client withholds, at every read the module makes.
do
	-- GetChildren: a withheld value, a list with garbage in it, an error.
	for _, fault in ipairs({ "secret", "garbage", "error", "string" }) do
		local W, names = fw(true, function(W, n) wf(W, n.FriendsFrame).fault.children = fault end)
		check("children " .. fault .. ": no violation, no error", #W.violations == 0 and #W.errors == 0 and not has(W.status(), "stopped"), wvio(W) .. table.concat(W.errors, "|"))
		check("children " .. fault .. ": the window itself is styled and the others are", W.state(names.FriendsFrame) == "SB" and W.state(names.MerchantFrame) == "SB" and W.state(names.MerchantRepairAllButton) == "SB")
		if fault == "garbage" then
			check("children garbage: the frames among the garbage are walked", W.state(names.FriendsFrameAddFriendButton) == "SB" and #wboxes(W, names.FriendsFrameTab1) == 1)
		else
			check("children " .. fault .. ": what could not be listed is not styled", W.state(names.FriendsFrameAddFriendButton) == "." and #wboxes(W, names.FriendsFrameTab1) == 0)
		end
	end
	-- GetRegions: a strip over a frame whose regions are withheld.
	for _, fault in ipairs({ "secret", "garbage", "error" }) do
		local W, names = fw(true, function(W, n) wf(W, n.CharacterFrameLeftPaneHost).fault.regions = fault end)
		check("regions " .. fault .. ": no violation", #W.violations == 0, wvio(W))
		check("regions " .. fault .. ": the rest of the window is styled and the module goes on", W.state(names.CharacterFrame) == "SB" and wa(W, wraw(W, names.CharacterFrameRightPaneHost).StoneBg) == 0 and not has(W.status(), "stopped"))
		check("regions " .. fault .. ": the strip of the pane whose regions cannot be read is not counted as a failure of the module", not has(W.line("Windows"), "failed"), W.line("Windows"))
	end
end

do
	-- Alpha: a region whose alpha is withheld stays as it is; nothing is recorded that would be put back wrongly.
	for _, fault in ipairs({ "secret", "error", "string" }) do
		local W, names = fw(true, function(W, n)
			local nine = wraw(W, wf(W, n.FriendsFrame).NineSlice)
			W.rawOf[nine.TopEdge].fault.alpha = fault
			W.rawOf[wf(W, n.FriendsFrameAddFriendButton).Left].fault.alpha = fault
		end)
		check("alpha " .. fault .. ": no violation and no error", #W.violations == 0 and #W.errors == 0, wvio(W))
		check("alpha " .. fault .. ": the region whose alpha cannot be read is not changed, its neighbours are", wa(W, wraw(W, wraw(W, names.FriendsFrame).NineSlice).TopEdge) == 1 and wa(W, wraw(W, wraw(W, names.FriendsFrame).NineSlice).BottomEdge) == 0
			and wa(W, wraw(W, names.FriendsFrameAddFriendButton).Left) == 1 and wa(W, wraw(W, names.FriendsFrameAddFriendButton).Right) == 0)
		check("alpha " .. fault .. ": the module is not stopped and no frame is counted as failed", not has(W.status(), "stopped") and not has(W.line("Windows"), "failed"))
		W.change("windows.enabled", false)
		check("alpha " .. fault .. ": switched off, what was faded has its alpha back", wa(W, wraw(W, names.FriendsFrameAddFriendButton).Right) == 1)
	end
end

do
	-- Atlas: the regions found by their atlas.
	for _, fault in ipairs({ "secret", "error", "string" }) do
		local W, names = fw(true, function(W, n)
			for _, tab in ipairs({ "PaperDollSidebarTab1" }) do
				local _, ring = wregion(W, n[tab], "UI-Character-Info-StatTab")
				ring.fault.atlas = fault
			end
			local _, back = wregion(W, n.ReputationBar1, "common-stat-bar-BG")
			back.fault.atlas = fault
			local _, ammoRing = wregion(W, n.CharacterAmmoSlot, "UI-Character-Info-GearSlotSmall")
			ammoRing.fault.atlas = fault
		end)
		check("atlas " .. fault .. ": no violation and no error", #W.violations == 0 and #W.errors == 0, wvio(W))
		check("atlas " .. fault .. ": the tab, the bar and the ammo slot whose atlas cannot be read are still styled, with their art that cannot be found left", W.state(wraw(W, W.win.names.PaperDollSidebarTab1).Icon) == "SB"
			and #wboxes(W, W.win.names.ReputationBar1) == 1 and W.state(W.win.names.CharacterAmmoSlot) == "SB" and wa(W, wregion(W, W.win.names.CharacterAmmoSlot, "UI-Character-Info-GearSlotSmall") or 0) == 1)
		check("atlas " .. fault .. ": the notes say what was not found", has(W.status(), "sidebar tab was not found") and has(W.status(), "progress bar was not found"), W.status())
	end
end

do
	-- Size, name, parent, protection, shown, vertex colour, texture coordinates, scale: each withheld.
	local W, names = fw({ extras = true }, function(W, n)
		local boxes = { wf(W, wf(W, n.ReputationDetailFrame).AtWarCheckbox), wf(W, wf(W, n.ReputationDetailFrame).MakeInactiveCheckbox), wf(W, wf(W, n.ReputationDetailFrame).WatchFactionCheckbox) }
		boxes[1].fault.size = "secret"
		boxes[2].fault.size = "string"
		boxes[3].fault.size = "error"
	end)
	local rep = wraw(W, names.ReputationDetailFrame)
	check("size withheld, wrong or raising: those check buttons are not taken for check boxes, nothing raises", #wboxes(W, rep.AtWarCheckbox) == 0 and #wboxes(W, rep.MakeInactiveCheckbox) == 0 and #wboxes(W, rep.WatchFactionCheckbox) == 0
		and #W.violations == 0 and #W.errors == 0, wvio(W))
	check("size withheld: the check box next to them, with its size, is a check box", #wboxes(W, names.FriendsFrameOfflineCheck) == 1)
end

do
	local W, names = fw(true, function(W, n)
		wf(W, n.CharacterAmmoSlot).fault.name = "secret"
		wf(W, n.FriendsFrameCloseButton).fault.name = "secret"
		wf(W, n.FriendsFrameCloseButton).fault.parent = "secret"
		wf(W, n.MerchantFrameCloseButton).fault.name = "error"
		wf(W, n.MailFrameCloseButton).fault.parent = "error"
	end)
	check("name and parent withheld: no violation, no error", #W.violations == 0 and #W.errors == 0, wvio(W))
	check("name withheld: the ammo slot is still a slot, but it is not known to be the ammo slot, so its ring stays", W.state(names.CharacterAmmoSlot) == "SB" and wa(W, wregion(W, names.CharacterAmmoSlot, "UI-Character-Info-GearSlotSmall")) == 1)
	check("name and parent withheld: a close button known by the key of its parent is still found when only its name is withheld", wa(W, wraw(W, names.MerchantFrameCloseButton).states.Normal) == 0 and wa(W, wraw(W, names.MailFrameCloseButton).states.Normal) == 0)
	check("name and parent withheld together: a close button known by neither is not found by those, and its art says what it is", wa(W, wraw(W, names.FriendsFrameCloseButton).states.Normal) == 0)
end

do
	local W, names = fw(true, function(W, n)
		local head = wf(W, n.CharacterHeadSlot)
		W.rawOf[head.IconBorder].fault.vertex = "secret"
		W.rawOf[head.NormalTexture].fault.vertex = "secret"
		W.rawOf[wf(W, n.CharacterNeckSlot).IconBorder].fault.vertex = "error"
	end)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	local o = W.look(names.CharacterHeadSlot)
	check("vertex colour withheld: the quality comes from the arguments of the hook, not from the region", o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) == "0.64,0.21,0.93" and #W.violations == 0 and #W.errors == 0)
end

do
	-- Only the first read of the vertex colour is withheld: at start, an item that is already coloured.
	local W = newWorld({ windows = true })
	local names = W.win.names
	W.updateSlot("CharacterHeadSlot", { quality = 4, broken = true })
	W.updateSlot("CharacterNeckSlot", { quality = 3 })
	W.rawOf[wf(W, names.CharacterHeadSlot).IconBorder].fault.vertex = "secret"
	W.rawOf[wf(W, names.CharacterHeadSlot).NormalTexture].fault.vertex = "secret"
	W.rawOf[wf(W, names.CharacterNeckSlot).IconBorder].fault.vertex = "string"
	W.login()
	W.flush()
	local head, neck = W.look(names.CharacterHeadSlot), W.look(names.CharacterNeckSlot)
	check("vertex colour withheld at start: an item that was already coloured has the border colour until Blizzard updates it", head and neck and string.format("%.2f,%.2f,%.2f", head.r, head.g, head.b) == "0.00,0.00,0.00"
		and string.format("%.2f,%.2f,%.2f", neck.r, neck.g, neck.b) == "0.00,0.00,0.00" and #W.violations == 0 and #W.errors == 0)
	W.updateSlot("CharacterNeckSlot", { quality = 3 })
	check("vertex colour withheld at start: and the next update gives it", string.format("%.2f,%.2f,%.2f", W.look(names.CharacterNeckSlot).r, W.look(names.CharacterNeckSlot).g, W.look(names.CharacterNeckSlot).b) == "0.00,0.44,0.87")
end

do
	-- Texture coordinates withheld before a crop: the icon goes back to the full texture.
	local W = newWorld({ windows = true })
	local names = W.win.names
	local icon = wraw(W, names.CharacterFrameModeTab2).Icon
	W.rawOf[icon].fault.texcoord = "secret"
	local slotIcon = wraw(W, names.CharacterHeadSlot).icon
	W.rawOf[slotIcon].fault.texcoord = "error"
	W.login()
	W.flush()
	check("texture coordinates withheld: the icons are cropped all the same", wtc(W, icon) == "0.08,0.92,0.08,0.92" and wtc(W, slotIcon) == "0.08,0.92,0.08,0.92" and #W.violations == 0 and #W.errors == 0)
	W.change("windows.slots", false)
	check("texture coordinates withheld: and go back to the whole texture", wtc(W, slotIcon) == "-")
end

do
	-- Shown, protected and forbidden answered with a withheld value.
	local W, names = fw(true, function(W, n)
		for _, tab in ipairs({ "CharacterFrameModeTab1", "CharacterFrameModeTab2" }) do
			W.rawOf[wraw(W, n[tab]).SelectedTexture].fault.shown = "secret"
		end
		wf(W, n.FriendsFrameAddFriendButton).fault.protected = "secret"
		wf(W, n.FriendsFrameSendMessageButton).IsForbidden = function() return SECRET end
		W.rawOf[wraw(W, n.CharacterFrame).RightPaneHost].fault.shown = "secret"
	end)
	check("shown withheld: a side tab does not know whether it is selected, so it shows no selected tint; no error", not wtints(W, names.CharacterFrameModeTab1, "OVERLAY")[1].shown and #W.errors == 0 and #W.violations == 0)
	check("shown withheld: the pane toggle, which cannot tell whether its pane is shown, points right", wsegments(wlines(W, names.CharacterFrameRightPaneToggleButton, "OVERLAY")) == RIGHT_SHAPE)
	check("protected withheld: the button is styled at once out of combat", W.state(names.FriendsFrameAddFriendButton) == "SB")
	check("forbidden withheld: the button is skipped", W.state(names.FriendsFrameSendMessageButton) == ".")
end

do
	-- A frame whose protection cannot be read is treated as protected in combat.
	local W = newWorld({ windows = true, combat = true })
	local names = W.win.names
	wf(W, names.FriendsFrameAddFriendButton).fault.protected = "secret"
	W.login()
	W.flush()
	check("protected withheld in combat: the button is treated as protected and waits", W.state(names.FriendsFrameAddFriendButton) == "." and #W.violations == 0, wvio(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("protected withheld in combat: and is styled when combat ends", W.state(names.FriendsFrameAddFriendButton) == "SB")
end

do
	-- Field values withheld: a key that holds a secret value is not a frame.
	local W, names = fw(true, function(W, n)
		wf(W, n.FriendsFrameAddFriendButton).Left = SECRET
		wf(W, n.FriendsFrameTab1).LeftActive = SECRET
		wf(W, wf(W, n.FriendsFrame).ScrollBar).Track = SECRET
		wf(W, n.CharacterHeadSlot).IconBorder = SECRET
		wf(W, wf(W, n.FriendsFrame).Inset).layoutType = SECRET
		wf(W, n.FriendsFrameStatusDropdown).Background = SECRET
		wf(W, n.ReputationBar1).Fill = SECRET
		wf(W, n.FriendsFrame).NineSlice = SECRET
	end)
	check("field withheld: no violation and no error", #W.violations == 0 and #W.errors == 0 and not has(W.status(), "stopped"), wvio(W))
	check("field withheld: a control whose key field is withheld is not recognised and nothing is done to it", W.state(names.FriendsFrameAddFriendButton) == "." and W.state(names.CharacterHeadSlot) == "." and W.state(names.FriendsFrameStatusDropdown) == "."
		and #wowned(W, names.ReputationBar1) == 0)
	check("field withheld: a window whose NineSlice is withheld still gets its outline", W.state(names.FriendsFrame) == "SB")
end

do
	-- The scale of a frame withheld: the divider is made all the same.
	local W = newWorld({ windows = true })
	local pane = W.win.names.CharacterFrameRightPaneHost
	W.rawOf[pane].GetEffectiveScale = function() return SECRET end
	W.login()
	W.flush()
	local divider
	for _, t in ipairs(wowned(W, pane)) do
		if t.layer == "OVERLAY" and t.sublevel == 7 then
			divider = t
		end
	end
	check("scale withheld: the divider is one screen pixel at scale 1", divider and near(divider.width, 768 / 1080, 1e-6) and #W.violations == 0 and #W.errors == 0, divider and g(divider.width))
end

do
	-- Object type: the addon recognises controls by their fields and never asks for the type of a frame.
	local W, names = fw(true, function(W, n)
		for _, frame in ipairs(W.blizzFrames) do
			frame.fault.objectType = "secret"
		end
		for _, region in ipairs(W.blizzRegions) do
			region.fault.objectType = "secret"
		end
	end)
	local reference = winWorld()
	check("object type withheld on every frame and region: the windows are styled exactly as when it can be read", #W.addonTextures == #reference.addonTextures and #W.addonFrames == #reference.addonFrames and #W.violations == 0 and #W.errors == 0)
end


-- 64. Failures: one bad frame is skipped and counted once, a part that keeps failing is stopped alone, a module that fails is stopped and gives Blizzard's look back.
do
	-- Two bad push buttons: skipped, counted once each, the part goes on.
	local W = newWorld({ windows = true })
	local n = W.win.names
	wf(W, n.FriendsFrameAddFriendButton).fault.createTexture = true
	wf(W, n.FriendsFrameSendMessageButton).fault.createTexture = true
	W.login()
	W.flush()
	check("two bad buttons: each is skipped, its art is left as it is and nothing of the addon's shows on it", W.state(n.FriendsFrameAddFriendButton) == "." and wa(W, wraw(W, n.FriendsFrameAddFriendButton).Left) == 1
		and wa(W, wraw(W, n.FriendsFrameSendMessageButton).Left) == 1)
	check("two bad buttons: the buttons after them are styled", W.state(n.PaperDollEquipmentManagerPaneEquipSet) == "SB" and W.state(n.SendMailMailButton) == "SB")
	check("two bad buttons: the module is not stopped and no part is stopped", not has(W.status(), "stopped") and #W.errors == 0)
	for _ = 1, 5 do
		W.change("windows.opacity", 55)
		W.change("windows.opacity", 80)
	end
	W.flush()
	check("two bad buttons: however often the windows are swept, the same two frames count as two failures: the part still goes on", not has(W.status(), "stopped") and W.state(n.SendMailMailButton) == "SB")
	W.win.panelButton(n.FriendsFrame, nil, "FlatUITestGoodButton")
	W.showPanel(n.FriendsFrame)
	W.flush()
	check("two bad buttons: a later button is styled", W.state(W.env.FlatUITestGoodButton) == "SB")
	local third = W.win.panelButton(n.FriendsFrame, nil, "FlatUITestThirdButton")
	wf(W, third).fault.createTexture = true
	W.showPanel(n.FriendsFrame)
	W.flush()
	check("three bad buttons: the part is stopped alone and the status says why, once", count(W.status(), "Windows: buttons stopped. CreateTexture failed") == 1 and not has(W.line("Windows"), "stopped"), W.status())
	check("three bad buttons: every button the part had styled is given back to Blizzard", wa(W, wraw(W, n.PaperDollEquipmentManagerPaneEquipSet).Left) == 1 and W.state(n.PaperDollEquipmentManagerPaneEquipSet) == "hb"
		and W.state(n.SendMailMailButton) == "hb" and wa(W, wraw(W, W.env.FlatUITestGoodButton).Left) == 1)
	local late = W.win.panelButton(n.FriendsFrame, nil, "FlatUITestLateButton")
	W.showPanel(n.FriendsFrame)
	W.flush()
	check("three bad buttons: no button is styled after that", W.state(late) == ".")
	check("three bad buttons: the other parts go on: tabs, slots, close buttons, the window", #wboxes(W, n.FriendsFrameTab1) == 1 and W.state(n.CharacterHeadSlot) == "SB" and #wlines(W, n.FriendsFrameCloseButton, "OVERLAY") == 2 and W.state(n.FriendsFrame) == "SB")
	check("three bad buttons: the module itself is on", has(W.line("Windows"), "Windows: on,") and not has(W.line("Windows"), "stopped"))
	W.change("windows.enabled", false)
	W.change("windows.enabled", true)
	W.flush()
	check("three bad buttons: turning the module off and on arms the part again", not W.ns.PartStopped("windows", "buttons") and not has(W.status(), "buttons stopped"), W.status())
	W.showPanel(n.FriendsFrame)
	W.flush()
	check("three bad buttons: and the button it had not reached is styled", W.state(late) == "SB" and not has(W.status(), "buttons stopped"), W.state(late) .. W.status())
end

do
	-- A failure part way through making a button leaves nothing visible.
	local W = newWorld({ windows = true })
	local n = W.win.names
	wf(W, n.FriendsFrameAddFriendButton).fault.createTextureAfter = 1
	W.login()
	W.flush()
	local look = W.look(n.FriendsFrameAddFriendButton)
	check("a button that fails after its outline was made: the outline is hidden again and the art is Blizzard's", look and look.hidden and look.backShown == false and wa(W, wraw(W, n.FriendsFrameAddFriendButton).Left) == 1 and wa(W, wraw(W, n.FriendsFrameAddFriendButton).states.Highlight) == 1,
		look and look.state)
end

do
	-- Three different kinds of bad frames each stop their own part.
	local W = newWorld({ windows = true })
	local n = W.win.names
	for _, name in ipairs({ "FriendsFrameTab1", "FriendsFrameTab3", "FriendsFrameTab4" }) do
		wf(W, n[name]).fault.createTexture = true
	end
	W.login()
	W.flush()
	check("three bad tabs: the tabs are stopped alone, with a line in the status, and given back", has(W.status(), "Windows: tabs stopped. CreateTexture failed") and wa(W, wraw(W, n.MerchantFrameTab1).Left) == 1
		and #wboxes(W, n.MerchantFrameTab1) <= 1 and W.state(n.FriendsFrameAddFriendButton) == "SB")
	check("three bad tabs: the tabs that were styled before the third failure are hidden again", (function()
		for _, name in ipairs({ "MerchantFrameTab1", "MerchantFrameTab2", "MailFrameTab1", "MailFrameTab2" }) do
			local boxes = wboxes(W, n[name])
			if #boxes > 0 and W.state(boxes[1]) ~= "hb" then
				return false
			end
		end
		return true
	end)())
end

do
	-- A part stopped by errors that happen when its frames are turned off: the frames not yet turned off must be given back too.
	local W = newWorld({ windows = true })
	local n = W.win.names
	W.login()
	W.flush()
	local buttons = { "FriendsFrameAddFriendButton", "FriendsFrameSendMessageButton", "SendMailMailButton", "SendMailCancelButton", "PaperDollEquipmentManagerPaneEquipSet",
		"PaperDollEquipmentManagerPaneSaveSet", "GossipFrameGreetingGoodbyeButton", "OpenMailReplyButton", "InboxPrevPageButton", "QuestFrameRewardButton", "QuestFrameProgressButton",
		"QuestFrameDetailButton", "QuestFrameGreetingButton" }
	local failing, failed = {}, 0
	for _, name in ipairs(buttons) do
		local look = W.look(n[name])
		look.top.SetShown = function()
			if not failing[name] and failed < 3 then
				failing[name] = true
				failed = failed + 1
			end
			if failing[name] then
				error("SetShown failed", 0)
			end
			look.top.shown = false
		end
	end
	W.change("windows.buttons", false)
	W.flush()
	check("a part that fails while its frames are turned off: stopped alone after three frames, and the status says why", has(W.status(), "Windows: buttons stopped. SetShown failed") and not has(W.line("Windows"), "stopped"), W.status())
	local left = {}
	for _, name in ipairs(buttons) do
		if wa(W, wraw(W, n[name]).Left) ~= 1 then
			left[#left + 1] = name
		end
	end
	check("a part that fails while its frames are turned off: every button it had styled has Blizzard's art back, including the ones it had not reached", #left == 0, table.concat(left, " "))
	local before = {}
	for _, name in ipairs(buttons) do
		before[name] = g(wa(W, wraw(W, n[name]).Left)) .. W.state(n[name])
	end
	W.change("windows.buttons", true)
	W.flush()
	local woken = {}
	for _, name in ipairs(buttons) do
		if before[name] ~= g(wa(W, wraw(W, n[name]).Left)) .. W.state(n[name]) then
			woken[#woken + 1] = name
		end
	end
	check("a part that fails while its frames are turned off: a stopped part is not woken by turning its option on again", #woken == 0, table.concat(woken, " "))
end

do
	-- The search for controls: three frames that raise stop the search; two do not.
	local function crooked(count)
		local W = newWorld({ windows = true })
		local n = W.win.names
		local list = { n.FriendsFrameAddFriendButton, n.FriendsFrameSendMessageButton, n.MerchantFrameTab1 }
		for index = 1, count do
			wf(W, list[index]).indexError = true
		end
		W.login()
		W.flush()
		return W, n
	end
	local W2, n2 = crooked(2)
	check("two frames that raise when their fields are read: skipped, the rest of the window is styled, the search goes on", not has(W2.status(), "search for controls stopped") and W2.state(n2.PaperDollEquipmentManagerPaneEquipSet) == "SB"
		and W2.state(n2.MerchantItem1 and wf(W2, n2.MerchantItem1).ItemButton) == "SB")
	for _ = 1, 4 do
		W2.change("windows.opacity", 55)
		W2.change("windows.opacity", 80)
	end
	check("two frames that raise: swept again and again they are two failures, not more", not has(W2.status(), "search for controls stopped"))
	local W3, n3 = crooked(3)
	check("three frames that raise: the search for controls is stopped, with a line in the status", has(W3.status(), "Windows: search for controls stopped."), W3.status())
	check("three frames that raise: the windows are still styled as windows", W3.state(n3.CharacterFrame) == "SB" and W3.state(n3.FriendsFrame) == "SB")
end

do
	-- A stop at the first start: hooksecurefunc raises.
	local W = newWorld({ windows = true })
	local real = W.env.hooksecurefunc
	W.env.hooksecurefunc = function(object, name, hook)
		if name == "ShowUIPanel" then
			error("hooksecurefunc failed", 0)
		end
		return real(object, name, hook)
	end
	W.login()
	W.flush()
	local n = W.win.names
	check("a module that fails at its start: it is stopped with the reason, and says so once", has(W.status(), "Windows: stopped. hooksecurefunc failed") and count(table.concat(W.out, "\n"), "Flat UI: Windows stopped.") == 1, W.status())
	check("a module that fails at its start: nothing of the addon is shown on a window", W.state(n.CharacterFrame) == "." and wa(W, wraw(W, wraw(W, n.CharacterFrame).NineSlice).TopEdge) == 1)
	check("a module that fails at its start: the other modules are on", has(W.status(), "Action bars: on,") and has(W.status(), "Cast bars: on,") and has(W.status(), "Swing timers: on,"), W.status())
	W.change("windows.enabled", false)
	check("a module that fails at its start: switched off it stays as it is", has(W.status(), "Windows: stopped.") and W.state(n.CharacterFrame) == ".")
	W.change("windows.enabled", true)
	W.flush()
	check("a module that fails at its start: switched on again it is started again", not W.ns.IsStopped("windows") and not has(W.status(), "Windows: stopped.") and has(W.status(), "Windows: on, "), W.status())
end

do
	-- A stop after the windows were styled: Blizzard's look is back, exactly.
	local function load(on)
		local saved = nil
		if not on then
			saved = { options = { ["windows.enabled"] = false } }
		end
		local W = newWorld({ windows = true, saved = saved })
		W.login()
		W.updateSlot("CharacterHeadSlot", { quality = 4 })
		W.updateSlot("CharacterChestSlot", { quality = 2, broken = true })
		W.win.choose(2, W.win.names.CharacterFrame)
		W.flush()
		return W
	end
	local never, W = load(false), load(true)
	local real = W.env.hooksecurefunc
	W.env.hooksecurefunc = function(object, name, hook)
		if name == "LFGListingCategorySelection_UpdateCategoryButtons" then
			error("hooksecurefunc failed", 0)
		end
		return real(object, name, hook)
	end
	W.loadGroupFinder()
	never.loadGroupFinder()
	W.flush()
	never.flush()
	check("a module that fails after the windows were styled: it is stopped with the reason, and the player is told once", has(W.status(), "Windows: stopped. hooksecurefunc failed") and count(table.concat(W.out, string.char(10)), "Flat UI: Windows stopped.") == 1, W.status())
	local wrong = wsame(wdump(never, true), wdump(W, true))
	check("a module that fails after the windows were styled: Blizzard's regions are as if the module had never run", #wrong == 0, #wrong .. " " .. table.concat(wrong, "; "):sub(1, 300))
	check("a module that fails after the windows were styled: none of its textures is visible", wvisible(W) == wvisible(never), wvisible(W) .. " " .. wvisible(never))
	check("a module that fails after the windows were styled: the other modules still work", has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Cast bars: on,"))
	W.win.choose(5, W.win.names.CharacterFrame)
	W.updateSlot("CharacterHeadSlot", { quality = 5 })
	W.win.updateCategories(2)
	W.showPanel(W.win.names.FriendsFrame)
	W.flush()
	check("a module that fails after the windows were styled: Blizzard's later changes are left alone", wraw(W, wraw(W, W.win.names.CharacterFrameModeTab5).SelectedTexture).shown and not wtints(W, W.win.names.CharacterFrameModeTab5, "OVERLAY")[1].shown
		and W.look(W.win.names.CharacterHeadSlot).hidden and #wboxes(W, W.win.names.FriendsFrameTab1) == 1 and W.state(wboxes(W, W.win.names.FriendsFrameTab1)[1]) == "hb")
	W.plates = W.plates
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	W.flush()
	check("a module that fails after the windows were styled: the nameplates are still styled", W.state(plate.healthBar) == "SB")
end

do
	-- Another module that fails does not stop the windows.
	local W = newWorld({ windows = true, breakResource = true })
	W.login()
	W.flush()
	check("another module that fails: the windows are styled and on", W.state(W.win.names.CharacterFrame) == "SB" and has(W.line("Windows"), "Windows: on,") and not has(W.line("Windows"), "stopped"))
	W.change("windows.enabled", false)
	check("another module that fails: and the windows can be switched off", W.state(W.win.names.CharacterFrame) == "hb")
end

-- 65. General settings reach window outlines; the window opacity and the two colours belong to this page.
do
	local S = wscene()
	local W = S.W
	local N = S.N
	local function ringAll(px, r, g_, b)
		local ok = true
		for _, target in ipairs({ N.CharacterFrame, N.FriendsFrameAddFriendButton, N.CharacterShirtSlot, N.FriendsFrameStatusDropdown, wraw(W, N.CharacterFrameModeTab2).Icon }) do
			local a, why = ringOf(W, target, px, r, g_, b)
			ok = ok and a
		end
		return ok
	end
	check("general settings: the outlines of a window, a button, a slot, a dropdown and a side tab icon are one pixel and black", ringAll(1, 0, 0, 0))
	W.change("general.thickness", 3)
	W.flush()
	check("general thickness 3: every outline of the windows is three pixels", (function()
		for _, target in ipairs({ N.CharacterFrame, N.FriendsFrameAddFriendButton, N.FriendsFrameStatusDropdown, wraw(W, N.CharacterFrameModeTab2).Icon, N.MerchantFrame }) do
			local o = W.look(target)
			if not o or o.thick ~= 3 then
				return false
			end
		end
		return true
	end)())
	W.change("general.thickness", 1)
	W.change("general.border", "ff336699")
	W.flush()
	check("general border colour: the edge of every outline takes it, a slot with a quality colour keeps its own", (function()
		for _, target in ipairs({ N.CharacterFrame, N.FriendsFrameAddFriendButton, N.FriendsFrameStatusDropdown, N.MerchantFrame, N.CharacterShirtSlot }) do
			local o = W.look(target)
			if not o or string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b) ~= "0.20,0.40,0.60" then
				return false
			end
		end
		return string.format("%.2f,%.2f,%.2f", W.look(N.CharacterHeadSlot).r, W.look(N.CharacterHeadSlot).g, W.look(N.CharacterHeadSlot).b) == "0.64,0.21,0.93"
	end)())
	W.change("general.backdrop", "ff102030")
	W.flush()
	check("general background colour: the window fill takes it, at the window's opacity", wcolour(wfill(W, N.CharacterFrame)) == "0.063,0.125,0.188,0.8" and wcolour(wfill(W, N.MerchantFrame)) == "0.063,0.125,0.188,0.8"
		and wcolour(wfill(W, wboxes(W, N.ReputationBar1)[1])) == "0.063,0.125,0.188,0.8", wcolour(wfill(W, N.CharacterFrame)))
	check("general background colour: the fill of buttons and slots is the button colour of this page, not the general one", wcolour(wfill(W, N.FriendsFrameAddFriendButton)) == PANEL_FILL and wcolour(wfill(W, N.CharacterNeckSlot)) == PANEL_FILL)
	W.change("general.backdropAlpha", 10)
	W.flush()
	check("general background opacity: windows keep the opacity of this page", wcolour(wfill(W, N.CharacterFrame)) == "0.063,0.125,0.188,0.8")
	W.change("windows.opacity", 35)
	W.flush()
	check("window opacity: sets the alpha of every window fill and of the bars", wcolour(wfill(W, N.CharacterFrame)) == "0.063,0.125,0.188,0.35" and wcolour(wfill(W, wboxes(W, N.ReputationBar1)[1])) == "0.063,0.125,0.188,0.35")
	W.change("general.backdrop", "ff0f0f0f")
	W.change("general.border", "ff000000")
	W.flush()
	check("general colours back: the fills and edges follow", wcolour(wfill(W, N.CharacterFrame)) == "0.059,0.059,0.059,0.35" and string.format("%.2f", W.look(N.CharacterFrame).r) == "0.00")
	-- The general settings do not touch the nameplates' own fill.
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	W.flush()
	check("general settings: an outline without a fill of its own (a nameplate) still follows the general background", wcolour(wfill(W, plate.healthBar)) == "0.059,0.059,0.059,0.1", wcolour(wfill(W, plate.healthBar)))
	clean(W, "general settings")
end

-- 66. /flatui status for the module, and the settings of earlier versions.
do
	local W = newWorld({ windows = true })
	W.login()
	W.flush()
	local line = W.line("Windows")
	local styled = tonumber(line:match("^Windows: on, (%d+) styled$"))
	check("status: the module has a line of its own, after the cooldowns, counting what it styled", styled and styled > 100 and select(2, W.status():gsub("\n", "")) == #W.ns.StatusLines() - 1 and W.status():match("Cooldowns: on, %d+ styled\nCooldown icons: [^\n]*\nTrackers: on, %d+ shown\nDefensives on you: on\nParty cooldowns: on\nEnemy cooldowns: on\nWindows: on"), line)
	W.change("windows.enabled", false)
	check("status: off", W.line("Windows") == "Windows: off")
	W.change("windows.enabled", true)
	check("status: on again, the same count", W.line("Windows") == line, W.line("Windows"))
	local out = W.slash("status")
	check("status: /flatui status prints it", has(out, "Windows: on, ") and count(out, "\n") == #W.ns.StatusLines() - 1)
	-- The start of a login: on, but not started.
	local E = newWorld({ windows = true })
	E.fire("ADDON_LOADED", "FlatUI")
	check("status: before the player has logged in the module is on and has not started", E.line("Windows") == "Windows: on, not started", E.line("Windows"))
end

do
	-- Settings saved by 0.1.0 and 0.2.0 load unchanged.
	local old1 = { nameplates = false, actionbars = true, resource = false, swing = true, castbars = false, thickness = 2 }
	local W1 = newWorld({ windows = true, saved = old1 })
	W1.login()
	W1.flush()
	check("saved by 0.1.0: the five switches and the thickness are taken over", W1.ns.Get("nameplates.enabled") == false and W1.ns.Get("actionbars.enabled") == true and W1.ns.Get("resource.enabled") == false
		and W1.ns.Get("swing.enabled") == true and W1.ns.Get("castbars.enabled") == false and W1.ns.Get("general.thickness") == 2)
	check("saved by 0.1.0: the windows module, which 0.1.0 did not have, is on with its defaults", W1.ns.Get("windows.enabled") == true and W1.ns.Get("windows.opacity") == 80 and W1.state(W1.win.names.CharacterFrame) == "SB")
	check("saved by 0.1.0: the old keys are gone from the saved variable", W1.env.FlatUIDB.nameplates == nil and W1.env.FlatUIDB.thickness == nil and W1.options()["nameplates.enabled"] == false)
	local ring, why = ringOf(W1, W1.win.names.CharacterFrame, 2, 0, 0, 0)
	check("saved by 0.1.0: and the thickness of 2 reaches the windows", ring, why)
	local W1b = newWorld({ windows = true, saved = { windows = false, nameplates = true } })
	W1b.login()
	check("saved by 0.1.0: a stray key called windows is not read as a switch and is left where it is", W1b.ns.Get("windows.enabled") == true and W1b.env.FlatUIDB.windows == false)
	local old2 = { options = { ["nameplates.health"] = false, ["actionbars.crop"] = 12, ["general.scale"] = 80, ["general.scaleOn"] = true, ["castbars.textPlate"] = true, ["swing.outline"] = "frame" } }
	local W2 = newWorld({ windows = true, saved = old2 })
	W2.login()
	W2.flush()
	local same = true
	for path, value in pairs({ ["nameplates.health"] = false, ["actionbars.crop"] = 12, ["general.scale"] = 80, ["general.scaleOn"] = true, ["castbars.textPlate"] = true, ["swing.outline"] = "frame" }) do
		same = same and W2.ns.Get(path) == value
	end
	check("saved by 0.2.0: every setting of the older pages is as it was saved", same)
	check("saved by 0.2.0: the windows page, which 0.2.0 did not have, has its defaults and the windows are styled", W2.ns.Get("windows.opacity") == 80 and W2.ns.Get("windows.panel") == "ff1e1e1e" and W2.ns.Get("windows.slots") == true
		and W2.state(W2.win.names.FriendsFrame) == "SB")
	check("saved by 0.2.0: nothing is written to the saved variable for the settings that were never chosen", W2.options()["windows.opacity"] == nil and W2.options()["windows.enabled"] == nil)
	-- This version's own settings.
	local new = { options = { ["windows.opacity"] = 52, ["windows.panel"] = "FF336699", ["windows.accent"] = "xyz", ["windows.crop"] = 40, ["windows.slots"] = "yes", ["windows.enabled"] = true, ["windows.nothing"] = 5 } }
	local W3 = newWorld({ windows = true, saved = new })
	W3.login()
	check("saved by this version: values are read back as the page allows them: a step of 5, lower-case colours, a limit of 15, a boolean", W3.ns.Get("windows.opacity") == 50 and W3.ns.Get("windows.panel") == "ff336699" and W3.ns.Get("windows.accent") == "ffd9d9d9"
		and W3.ns.Get("windows.crop") == 15 and W3.ns.Get("windows.slots") == true and W3.ns.Get("windows.enabled") == true)
	check("saved by this version: a setting that does not exist is dropped", W3.options()["windows.nothing"] == nil)
	local ring3 = wcolour(wfill(W3, W3.win.names.FriendsFrameAddFriendButton))
	check("saved by this version: and the windows use them", ring3 == "0.200,0.400,0.600,1" and wcolour(wfill(W3, W3.win.names.CharacterFrame)):find(",0.5$") ~= nil, ring3)
end

-- 67. The Core.lua changes on their own.
do
	-- ADDON_LOADED of another addon reaches the modules that listen, without disturbing this addon's own load.
	local W = newWorld({ windows = true })
	W.fire("ADDON_LOADED", "SomeOtherAddon")
	W.fire("ADDON_LOADED", "FlatUI")
	W.fire("ADDON_LOADED", "AnotherAddon")
	W.fire("PLAYER_LOGIN")
	W.fire("ADDON_LOADED", "Blizzard_GroupFinder_VanillaStyle")
	W.flush()
	check("ADDON_LOADED: before this addon's own, it is ignored; this addon's own loads the settings and the options once; one after is passed on", #W.categories == #PAGE_LABELS + 1 and W.ns.Get("windows.enabled") == true and #W.errors == 0)
end

do
	-- The listeners of ADDON_LOADED get the name, and the filter keeps the module from running for every addon.
	local W = winWorld()
	local hooks = W.hooks
	local textures = #W.addonTextures
	for index = 1, 30 do
		W.fire("ADDON_LOADED", "SomeAddon" .. index)
	end
	W.fire("ADDON_LOADED", SECRET)
	W.fire("ADDON_LOADED", nil)
	W.fire("ADDON_LOADED", 5)
	W.fire("ADDON_LOADED", "FlatUI")
	W.flush()
	check("ADDON_LOADED: thirty other addons, a withheld name, nil and a number: nothing happens, nothing is made, nothing raises", W.hooks == hooks and #W.addonTextures == textures and #W.errors == 0 and #W.violations == 0, W.hooks - hooks)
	local sweeps = 0
	for _, f in ipairs(W.blizzFrames) do
		sweeps = sweeps + (f.calls.GetChildren or 0)
	end
	W.fire("ADDON_LOADED", "Blizzard_TrainerUI")
	local after = 0
	for _, f in ipairs(W.blizzFrames) do
		after = after + (f.calls.GetChildren or 0)
	end
	check("ADDON_LOADED: and a listed load-on-demand addon sweeps its window, which does not exist here, and the others not at all", after == sweeps)
	W.fire("ADDON_LOADED", "FlatUI")
	check("ADDON_LOADED: this addon's own name reaches no module", W.hooks == hooks and #W.addonTextures == textures)
end

do
	-- The fill of one outline: its own colour and opacity, or the general background.
	local W = newWorld()
	W.login()
	local plate = W.newPlate()
	W.showPlate("nameplate1", plate)
	W.flush()
	local outline = W.ns.Outline(plate.healthBar, plate.healthBar)
	local back = W.backdropOn(plate.healthBar)
	check("per-outline fill: with none, the outline follows the general background colour and opacity", wcolour(back.color) == "0.059,0.059,0.059,0.85")
	W.ns.SetOutlineFill(outline, 1, 0, 0, 0.5)
	check("per-outline fill: its own colour and opacity", wcolour(back.color) == "1.000,0.000,0.000,0.5")
	local calls = back.calls.SetColorTexture
	W.ns.SetOutlineFill(outline, 1, 0, 0, 0.5)
	check("per-outline fill: the same fill again paints nothing", back.calls.SetColorTexture == calls)
	W.change("general.backdrop", "ff102030")
	W.change("general.backdropAlpha", 40)
	W.change("general.border", "ff336699")
	check("per-outline fill: the general background does not touch it, the general border colour does reach the edges", wcolour(back.color) == "1.000,0.000,0.000,0.5" and string.format("%.2f", W.look(plate.healthBar).r) == "0.20")
	W.ns.SetOutlineFill(outline, 0, 0, 1, 0)
	check("per-outline fill: an opacity of 0 is a fill", wcolour(back.color) == "0.000,0.000,1.000,0" and back.shown)
	W.ns.SetOutlineFill(outline)
	check("per-outline fill: with none given it is the general background again", wcolour(back.color) == "0.063,0.125,0.188,0.4", wcolour(back.color))
	W.ns.SetOutlineFill(nil, 1, 1, 1, 1)
	check("per-outline fill: no outline is ignored", #W.errors == 0 and #W.violations == 0)
	-- Show and hide keep the fill.
	W.ns.SetOutlineFill(outline, 0.5, 0.5, 0.5, 0.5)
	W.ns.SetOutline(outline, false, false)
	W.ns.SetOutline(outline, true, true)
	check("per-outline fill: hiding the outline and showing it again keeps the fill", wcolour(back.color) == "0.500,0.500,0.500,0.5" and back.shown)
	-- The addon's own frames and textures are registered.
	local owner = W.ns.Own
	local o = W.look(plate.healthBar)
	check("ns.Own: the holder, the four edges and the backdrop of an outline are marked as the addon's own", owner[o.holder] == true and owner[o.top] == true and owner[o.bottom] == true and owner[o.left] == true and owner[o.right] == true and owner[back] == true)
	check("ns.Own: the Blizzard frame it belongs to is not", owner[plate.healthBar] == nil)
	-- A direct outline has no holder.
	check("ns.Own: a table nobody registered is not", owner[{}] == nil)
end

do
	-- ns.EachPart, ns.PartStopped, ns.Note on their own.
	local W = newWorld()
	W.login()
	local ns = W.ns
	local a, b, c, d = {}, {}, {}, {}
	check("EachPart: a call that works returns true", ns.EachPart("windows", "probe", function() end, a) == true)
	check("EachPart: a call that fails returns false, once", ns.EachPart("windows", "probe", function() error("boom", 0) end, a) == false)
	check("EachPart: the same frame again is the same failure", ns.EachPart("windows", "probe", function() error("boom", 0) end, a) == false and not ns.PartStopped("windows", "probe"))
	check("EachPart: a call that fails gives its error as the second value, as text", select(2, ns.EachPart("windows", "probe", function() error("boom", 0) end, a)) == "boom"
		and type(select(2, ns.EachPart("windows", "probe", function() error({}, 0) end, a))) == "string")
	check("EachPart: a call that works gives true and nothing else", select("#", ns.EachPart("windows", "probe", function() return "x", "y" end, a)) == 1)
	ns.EachPart("windows", "probe", function() error("boom2", 0) end, b)
	check("EachPart: two frames do not stop a part", not ns.PartStopped("windows", "probe") and ns.EachPart("windows", "probe", function() end, a) == true)
	ns.EachPart("windows", "probe", function() error("boom3", 0) end, c)
	check("EachPart: the third different frame stops the part and notes why, with the first error", ns.PartStopped("windows", "probe") and has(W.status(), "Windows: probe stopped. boom"), W.status())
	check("EachPart: a stopped part runs nothing and returns false", ns.EachPart("windows", "probe", function() error("never", 0) end, d) == false and ns.EachPart("windows", "probe", function() d.ran = true end, d) == false and d.ran == nil)
	check("EachPart: another part of the module is not stopped", not ns.PartStopped("windows", "other") and ns.EachPart("windows", "other", function() end, d) == true)
	check("EachPart: another module is not stopped", not ns.PartStopped("nameplates", "probe"))
	local failing = function() error("x", 0) end
	for _ = 1, 3 do
		ns.EachPart("windows", "nofirst", failing)
	end
	check("EachPart: with no frame given the function itself is the thing counted, so the same function three times is one failure", not ns.PartStopped("windows", "nofirst"))
	check("EachPart: the line in the status is there once", count(W.status(), "Windows: probe stopped.") == 1)
	ns.Note("windows", "Windows: probe stopped. boom")
	ns.Note("windows", "a second note")
	ns.Note("windows", "a second note")
	check("Note: a line is added once", count(W.status(), "a second note") == 1 and count(W.status(), "Windows: probe stopped.") == 1)
	check("Note: and follows the module's line", W.status():find("Windows: on, %d+ styled" .. string.char(10) .. "Windows: probe stopped") ~= nil, W.status())
end

do
	-- Existing modules behave the same in a world that has windows: the numbers of the nameplate and action bar scenes.
	local W0 = newWorld()
	W0.login()
	local A = newWorld({ windows = true })
	A.login()
	local plateA, plate0 = A.newPlate(), W0.newPlate()
	A.showPlate("nameplate1", plateA)
	W0.showPlate("nameplate1", plate0)
	A.flush()
	W0.flush()
	check("existing modules with windows around: a nameplate is styled the same way", g(plateA.healthBar.bgTexture.alpha) == g(plate0.healthBar.bgTexture.alpha) and A.state(plateA.healthBar) == W0.state(plate0.healthBar)
		and A.state(plateA.healthBar) == "SB")
	check("existing modules with windows around: the action bars, resource display, swing timers and cast bars have the same status", (A.status():gsub("\nWindows[^\n]*", "")) == (W0.status():gsub("\nWindows[^\n]*", "")), A.status())
end


-- 68. Window kinds the listed windows do not happen to have, and what Blizzard does to an item button on its own.
do
	local W = winWorld({ extras = true })
	local flat = W.win.flatWindow
	local f = wraw(W, flat)
	local bg = wraw(W, f.Bg)
	check("window with a flat Bg: the four flat textures are transparent, the Bg frame is not", wa(W, bg.BottomLeft) == 0 and wa(W, bg.BottomRight) == 0 and wa(W, bg.BottomEdge) == 0 and wa(W, bg.TopSection) == 0 and wa(W, f.Bg) == 1)
	check("window with a flat Bg: it has the outline of a window", W.state(flat) == "SB" and wcolour(wfill(W, flat)) == WINDOW_FILL)
	W.change("windows.enabled", false)
	check("window with a flat Bg: switched off, the four textures are as they were", wa(W, bg.BottomLeft) == 1 and wa(W, bg.TopSection) == 1)
	W.change("windows.enabled", true)
	check("window with a flat Bg: and transparent again", wa(W, bg.BottomEdge) == 0)
	clean(W, "flat window")
end

do
	-- ItemButtonMixin:SetAlpha hands the alpha to IconBorder: until the next update of the item the border shows.
	local W = winWorld()
	local head = W.win.names.CharacterHeadSlot
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	check("item button: the border of an item is transparent", wa(W, wraw(W, head).IconBorder) == 0)
	W.blizzard(function() head:SetAlpha(1) end)
	check("item button: Blizzard's SetAlpha on the button gives the border its alpha back, which the next update of the item takes away again", wa(W, wraw(W, head).IconBorder) == 1)
	W.updateSlot("CharacterHeadSlot", { quality = 4 })
	check("item button: the next update of the item", wa(W, wraw(W, head).IconBorder) == 0)
	W.change("windows.slots", false)
	check("item button: switched off, the border has the alpha the client gave it", wa(W, wraw(W, head).IconBorder) == 1)
end

do
	-- Core.lua: ADDON_LOADED of another addon goes on to the modules that listen, with its name; this addon's own does not.
	local W = newWorld({ windows = true })
	local seen = {}
	W.ns.modules.windows.filters = nil
	W.ns.modules.windows.events.ADDON_LOADED = function(name) seen[#seen + 1] = tostring(name) end
	W.fire("ADDON_LOADED", "BeforeUs")
	W.fire("ADDON_LOADED", "FlatUI")
	W.fire("PLAYER_LOGIN")
	W.fire("ADDON_LOADED", "AfterUsOne")
	W.fire("ADDON_LOADED", "AfterUsTwo")
	check("ADDON_LOADED: a module hears the addons that load after the player has logged in, by name, and not this addon's own, nor the ones before it", table.concat(seen, ",") == "AfterUsOne,AfterUsTwo", table.concat(seen, ","))
	check("ADDON_LOADED: this addon's own load still read the settings and made the options once", #W.categories == #PAGE_LABELS + 1 and W.registered ~= nil and #W.errors == 0)
	local off = newWorld({ windows = true, saved = { options = { ["windows.enabled"] = false } } })
	local heard = {}
	off.ns.modules.windows.filters = nil
	off.ns.modules.windows.events.ADDON_LOADED = function(name) heard[#heard + 1] = name end
	off.fire("ADDON_LOADED", "FlatUI")
	off.fire("PLAYER_LOGIN")
	off.fire("ADDON_LOADED", "Anything")
	check("ADDON_LOADED: a module that is off hears nothing", #heard == 0)
	local filtered = newWorld({ windows = true })
	local got = {}
	filtered.ns.modules.windows.filters = { ADDON_LOADED = function(name) return name == "Wanted" end }
	filtered.ns.modules.windows.events.ADDON_LOADED = function(name) got[#got + 1] = name end
	filtered.fire("ADDON_LOADED", "FlatUI")
	filtered.fire("PLAYER_LOGIN")
	filtered.fire("ADDON_LOADED", "Unwanted")
	filtered.fire("ADDON_LOADED", "Wanted")
	check("ADDON_LOADED: the filter of a module decides which addons it hears", table.concat(got, ",") == "Wanted", table.concat(got, ","))
end


-- 69. Work the addon does only when something changed, and values Blizzard changes while the module is off.
do
	local S = wscene()
	local W = S.W
	local N = S.N
	local toggle = N.CharacterFrameRightPaneToggleButton
	local lines = wlines(W, toggle, "OVERLAY")
	local before = lines[1].calls.SetStartPoint
	W.blizzard(function() N.CharacterFrame:UpdateRightPaneToggleButton() N.CharacterFrame:UpdateRightPaneToggleButton() end)
	W.fireScript(wraw(W, N.CharacterFrame).RightPaneHost, "OnShow")
	W.flush()
	check("pane toggle: the lines are moved only when the direction changes", lines[1].calls.SetStartPoint == before, tostring(lines[1].calls.SetStartPoint) .. " " .. tostring(before))
	W.win.collapse(true, N.CharacterFrame)
	check("pane toggle: and once when it does", lines[1].calls.SetStartPoint == before + 1 and lines[2].calls.SetEndPoint == before + 1, tostring(lines[1].calls.SetStartPoint))
	-- Masks are taken off once and put back once.
	local tab = wraw(W, N.CharacterFrameModeTab2)
	local icon = wraw(W, tab.Icon)
	W.change("windows.opacity", 60)
	W.change("windows.opacity", 80)
	W.change("windows.buttons", false)
	W.change("windows.buttons", true)
	W.win.choose(2, N.CharacterFrame)
	check("side tab: the mask is taken off the icon once, however often the tab is updated", icon.calls.RemoveMaskTexture == 1, tostring(icon.calls.RemoveMaskTexture))
	W.change("windows.squareTabs", false)
	W.change("windows.squareTabs", false)
	check("side tab: and put back once", icon.calls.AddMaskTexture == 1 and wmasked(W, tab.Icon, tab.Mask), tostring(icon.calls.AddMaskTexture))
	local bar = wraw(W, N.ReputationBar1)
	local fill = wraw(W, bar.Fill)
	W.change("windows.opacity", 60)
	W.change("windows.opacity", 80)
	check("progress bar: the mask is taken off the fill once", fill.calls.RemoveMaskTexture == 1, tostring(fill.calls.RemoveMaskTexture))
	W.change("windows.bars", false)
	W.change("windows.bars", false)
	check("progress bar: and put back once", fill.calls.AddMaskTexture == 1 and wmasked(W, bar.Fill, bar.Mask), tostring(fill.calls.AddMaskTexture))
	clean(W, "work done once")
end

do
	-- Blizzard changes an alpha while the module is off: the next time the module gives art back, it gives back that alpha.
	local S = wscene()
	local W = S.W
	local head = S.N.CharacterHeadSlot
	local border = wraw(W, head).IconBorder
	W.change("windows.slots", false)
	W.blizzard(function() head:SetAlpha(0.7) end)
	check("alpha changed by Blizzard while the module is off: the border has it", near(wa(W, border), 0.7))
	W.change("windows.slots", true)
	check("alpha changed by Blizzard while the module is off: and it is transparent again when the module is on", wa(W, border) == 0)
	W.change("windows.slots", false)
	check("alpha changed by Blizzard while the module is off: and given back is the alpha it had last, not the one before", near(wa(W, border), 0.7), g(wa(W, border)))
	-- The same for texture coordinates.
	local tab = wraw(W, S.N.CharacterFrameModeTab2)
	W.change("windows.squareTabs", false)
	W.blizzard(function() W.rawOf[tab.Icon]:SetTexCoord(0.1, 0.9, 0.1, 0.9) end)
	W.change("windows.squareTabs", true)
	check("texture coordinates changed by Blizzard while the option is off: the icon is cropped inside the new rectangle", wtc(W, tab.Icon) == "0.164,0.836,0.164,0.836", wtc(W, tab.Icon))
	W.change("windows.squareTabs", false)
	check("texture coordinates changed by Blizzard while the option is off: and given back is what Blizzard set last", wtc(W, tab.Icon) == "0.1,0.9,0.1,0.9", wtc(W, tab.Icon))
end

do
	-- The note of a part that stopped is its own line, with the first error.
	local W = newWorld()
	W.login()
	local ns = W.ns
	local frames = { {}, {}, {} }
	local errors = { "first", "second", "third" }
	for index = 1, 3 do
		ns.EachPart("windows", "probe", function() error(errors[index], 0) end, frames[index])
	end
	local found
	for line in (W.status() .. string.char(10)):gmatch("([^" .. string.char(10) .. "]*)" .. string.char(10)) do
		if line:find("probe stopped", 1, true) then
			found = line
		end
	end
	check("a part that stopped: its line in the status names the module, the part and the first error", found == "Windows: probe stopped. first", tostring(found))
	check("a part that stopped: a call after it that would fail changes nothing", ns.EachPart("windows", "probe", function() error("fourth", 0) end, {}) == false)
	check("a part that failed once or twice returns false and goes on", ns.EachPart("windows", "other", function() error("x", 0) end, {}) == false and ns.EachPart("windows", "other", function() end, {}) == true)
end


-- 70. Cases that tell a control from a look-alike, and work that must not be done twice, found by changing the addon on purpose.
do
	local W = winWorld({ extras = true })
	local N = W.win.names
	check("close button: one known by its key alone is a close button", wa(W, wraw(W, W.win.keyedClose).states.Normal) == 0 and #wlines(W, W.win.keyedClose, "OVERLAY") == 2)
	check("close button: one known by its name alone is a close button", wa(W, wraw(W, W.win.namedClose).states.Normal) == 0 and #wlines(W, W.win.namedClose, "OVERLAY") == 2)
	check("close button: art that only contains the name of a close button's is not a close button", #wlines(W, W.win.notClose) == 0 and wa(W, wraw(W, W.win.notClose).states.Normal) == 1)
	local border = wraw(W, N.FriendsFrameCloseButton).Border
	check("close button: its Border texture is transparent, and is given back when the module is off", wa(W, border) == 0)
	W.change("windows.enabled", false)
	check("close button: switched off, the border has its alpha again", wa(W, border) == 1)
	W.change("windows.enabled", true)
	local flat = W.win.flatWindow
	check("window with a flat Bg and a TitleBg: the title background is transparent", wa(W, wraw(W, flat).TitleBg) == 0)
	check("side tab whose frame has no SetChecked: it is styled all the same, nothing raises", W.state(wraw(W, W.win.plainSideTab).Icon) == "SB" and #W.errors == 0 and #W.violations == 0)
	check("an edit box with no caps: not entered, and what is inside it is left alone", W.state(N.FlatUITestInBodyEdit) == "." and W.state(N.FlatUITestBodyEdit) == ".")
	check("a push button with a Center and no atlasName is left alone", W.state(W.win.centredButton) == ".")
	check("a frame with only the corner or only the middle of a multi-line text box's border is left alone", W.state(N.FlatUITestOnlyCorner) == "." and W.state(N.FlatUITestOnlyMiddle) == "."
		and wa(W, wraw(W, N.FlatUITestOnlyCorner).TopLeftTex) == 1 and wa(W, wraw(W, N.FlatUITestOnlyMiddle).MiddleTex) == 1)
	local deep = W.env.FlatUITestDeepArt
	check("strip of a pane one frame deep: what is two frames down from the pane stays", wa(W, deep) == 1 and wa(W, wraw(W, wraw(W, N.CharacterFrameRightPaneHost).children[1]).regions[1]) == 0)
	local pet = N.CharacterStatsPanePetScrollBox
	check("stats list of a pet: its border and scroll line are transparent like the list of the player", wa(W, wraw(W, pet).Border) == 0 and wa(W, wraw(W, pet).regions[2]) == 0)
	local check1 = wraw(W, N.ReputationDetailFrame).AtWarCheckbox
	local mark = wraw(W, wraw(W, check1).states.Checked)
	check("check box: the checked texture, which had an anchor of its own, has only the two anchors the addon gives it", #mark.points == 2 and mark.points[1][1] == "TOPLEFT" and mark.points[2][1] == "BOTTOMRIGHT")
	local disabledMark = wraw(W, wraw(W, check1).states.DisabledChecked)
	check("check box: the same for the disabled check", #disabledMark.points == 2)
	clean(W, "look-alikes")
end

do
	-- Check buttons whose answers cannot be used: the check mark's getter returns a withheld value, and three sizes raise.
	local W = newWorld({ windows = { extras = true } })
	local N = W.win.names
	local rep = wraw(W, N.ReputationDetailFrame)
	wraw(W, rep.AtWarCheckbox).GetCheckedTexture = function() return SECRET end
	local ok = {}
	for _, name in ipairs({ "MakeInactiveCheckbox", "WatchFactionCheckbox" }) do
		wraw(W, rep[name]).fault.size = "error"
	end
	wraw(W, N.FriendsFrameOfflineCheck).fault.size = "error"
	local third = W.win.checkButton(N.FriendsFrame, nil, nil, 26)
	W.login()
	W.flush()
	check("check button whose checked texture is withheld: not a check box", #wboxes(W, rep.AtWarCheckbox) == 0 and #W.violations == 0 and #W.errors == 0)
	check("check buttons whose size raises: each is left alone, the three of them do not stop the search for controls", #wboxes(W, rep.MakeInactiveCheckbox) == 0 and #wboxes(W, N.FriendsFrameOfflineCheck) == 0
		and not has(W.status(), "search for controls stopped") and #wboxes(W, third) == 1 and W.state(N.MerchantRepairAllButton) == "SB", W.status())
end

do
	-- Five windows whose children cannot be listed: each sweep is one failure of the module, and five stop it.
	local W = newWorld({ windows = true })
	local N = W.win.names
	for _, name in ipairs({ "FriendsFrame", "MerchantFrame", "MailFrame", "OpenMailFrame", "GossipFrame" }) do
		wraw(W, N[name]).fault.children = "error"
	end
	W.login()
	W.flush()
	check("children that cannot be listed in five windows: the module is not stopped, the windows are still given their outline", not has(W.status(), "Windows: stopped") and W.state(N.FriendsFrame) == "SB"
		and W.state(N.GossipFrame) == "SB" and W.state(N.CharacterFrame) == "SB" and W.state(N.QuestFrame) == "SB", W.status())
	check("children that cannot be listed in five windows: the window whose children can be listed is walked", W.state(N.PaperDollEquipmentManagerPaneEquipSet) == "SB" and W.state(N.QuestFrameRewardButton) == "SB")
end

do
	-- Specials and the walk are counted apart: two special parts and one control that raise do not stop anything.
	local W = newWorld({ windows = { lfg = "loaded" } })
	local N = W.win.names
	wraw(W, N.CharacterModelScene).indexError = true
