-- 71. A secret value keeps the type of the value it hides: type() of a secret number is "number". Every read is tested with the type a secret has.
do
	-- Item hooks handed secret colours.
	local W = winWorld({ hollowItems = true })
	W.secretType = "number"
	local head = W.win.names.CharacterHeadSlot
	local function edge()
		local o = W.look(head)
		return o and string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)
	end
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, SECRET, 0.4, 0.6)
	check("secret number: a withheld red component takes the quality away", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, 0.2, SECRET, 0.6)
	check("secret number: a withheld green component too", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, 0.6)
	W.env.SetItemButtonBorderVertexColor(head, 0.2, 0.4, SECRET)
	check("secret number: and a withheld blue component", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, 1)
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, SECRET, 1)
	check("secret number: a withheld green component among white ones does not wear the item", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, SECRET, 1, 1)
	check("secret number: nor a withheld red one", edge() == "0.00,0.00,0.00", edge())
	W.env.SetItemButtonNormalTextureVertexColor(head, 1, 1, SECRET)
	check("secret number: nor a withheld blue one", edge() == "0.00,0.00,0.00", edge())
	check("secret number: no violation, no error", #W.violations == 0 and #W.errors == 0, table.concat(W.errors, "|"))
end

