do
-- 75. Fixes to the window module after its review. Each section is about one finding or defect.

-- Side tab icons that show a rectangle of a shared sheet are cropped inside that rectangle.
do
	local W = newWorld({ windows = true })
	local names = W.win.names
	local RECT = { 0.015625, 0.53125, 0.46875, 0.60546875 }
	local icons = {}
	for _, index in ipairs({ 2, 3 }) do
		icons[index] = W.rawOf[wraw(W, names["PaperDollSidebarTab" .. index]).Icon]
		icons[index].texCoord = { RECT[1], RECT[2], RECT[3], RECT[4] }
	end
	W.login()
	W.flush()
	local function inside(icon, fraction)
		local across, down = (RECT[2] - RECT[1]) * fraction, (RECT[4] - RECT[3]) * fraction
		local c = icon.texCoord
		return c and near(c[1], RECT[1] + across) and near(c[2], RECT[2] - across) and near(c[3], RECT[3] + down) and near(c[4], RECT[4] - down)
	end
	check("sidebar tab on a shared sheet: the icon is cropped to 8 percent inside its own rectangle", inside(icons[2], 0.08) and inside(icons[3], 0.08), table.concat(icons[2].texCoord or {}, ","))
	W.change("windows.crop", 0)
	check("sidebar tab on a shared sheet: with no crop the icon shows its rectangle as Blizzard set it", inside(icons[2], 0))
	W.change("windows.crop", 15)
	check("sidebar tab on a shared sheet: a crop of 15 percent is 15 percent of the rectangle", inside(icons[2], 0.15) and inside(icons[3], 0.15))
	W.change("windows.squareTabs", false)
	check("sidebar tab on a shared sheet: with square icons off the rectangle is back exactly", inside(icons[2], 0) and inside(icons[3], 0))
	W.change("windows.squareTabs", true)
	check("sidebar tab on a shared sheet: and square icons on again crop inside it", inside(icons[2], 0.15))
	clean(W, "sidebar tab on a shared sheet")
end

-- The quest log popup has a parchment under the key Bg and the rock under no key: the rock goes, the parchment stays.
local function questLogWorld(saved)
	local W = newWorld({ windows = { only = {} }, saved = saved })
	W.group = "windows"
	local frame = W.win.portraitFrame(W.env.UIParent, nil, { name = "QuestLogPopupDetailFrame", hidden = true, width = 338, height = 496 }, "textured")
	local rock = wraw(W, frame).Bg
	wraw(W, rock).GetDrawLayer = function() return "BACKGROUND", -6 end
	local parchment = W.win.tex(frame, "Bg", "QuestBG-Parchment")
	wraw(W, parchment).GetDrawLayer = function() return "BACKGROUND", 0 end
	local book = W.win.tex(frame, nil, nil)
	wraw(W, book).GetDrawLayer = function() return "OVERLAY", -1 end
	-- Textures that share only the sublevel or only the layer with the rock or the book come first in the list the game gives.
	local sublevel = W.win.tex(frame, nil, nil)
	wraw(W, sublevel).GetDrawLayer = function() return "BORDER", -6 end
	local layer = W.win.tex(frame, nil, nil)
	wraw(W, layer).GetDrawLayer = function() return "OVERLAY", 3 end
	local regions = wraw(W, frame).regions
	for _, region in ipairs({ layer, sublevel, parchment }) do
		for index, found in ipairs(regions) do
			if found == region then
				table.remove(regions, index)
				break
			end
		end
		table.insert(regions, 1, region)
	end
	W.group = "static"
	W.seal()
	W.login()
	W.flush()
	return W, frame, rock, parchment, book, { sublevel, layer }
end

do
