-- The sweep does not go into a list, whose rows are made when it is shown: the rows it has are looked at once, and again after each update.
-- Beside the list, bars and check boxes are styled.
do
	local styledSomething, W = wstyled(function(W, root)
		local list = W.win.frame(root, "List", {})
		local target = W.win.frame(list, "ScrollTarget", {})
		local row = W.win.frame(target, nil, {})
		W.win.progressBar(row, "Bar", "FlatUITestRowBar")
		W.win.checkButton(row, "Check", "FlatUITestRowCheck", 26)
		W.win.progressBar(root, "Bar", "FlatUITestOwnBar")
		W.win.checkButton(root, "Check", "FlatUITestOwnCheck", 26)
		return list
	end)
	local env = W.env
	check("list: the bar and the check box in a row are styled when the list is looked at", #wboxes(W, env.FlatUITestRowBar) == 1 and #wboxes(W, env.FlatUITestRowCheck) == 1
		and wa(W, wregion(W, env.FlatUITestRowBar, "common-stat-bar-BG")) == 0 and wa(W, wraw(W, env.FlatUITestRowCheck).states.Normal) == 0)
	check("list: a bar and a check box beside it are styled", #wboxes(W, env.FlatUITestOwnBar) == 1 and #wboxes(W, env.FlatUITestOwnCheck) == 1 and styledSomething)
	-- A frame that holds the same rows without being a list is entered as before.
	local _, W2 = wstyled(function(W, root)
		local holder = W.win.frame(root, "Holder", {})
		local inner = W.win.frame(holder, "Target", {})
		W.win.progressBar(inner, "Bar", "FlatUITestHeldBar")
		return holder
	end)
	check("list: a frame with no ScrollTarget is still entered", #wboxes(W2, W2.env.FlatUITestHeldBar) == 1)
	clean(W, "list rows")
end

-- A vendor or trade cell: the game sets the colour of its slot and name art again on every update.
local function cellFunctions(W)
	local env = W.env
	function env.SetItemButtonSlotVertexColor(button, r, g, b)
		if button then
			button.SlotTexture:SetVertexColor(r, g, b)
		end
	end
	function env.SetItemButtonNameFrameVertexColor(button, r, g, b)
		if button then
			(button.NameFrame or env[button:GetName() .. "NameFrame"]):SetVertexColor(r, g, b)
		end
	end
end
-- A colour without alpha sets the alpha to 1.
local function resetting(W, region)
	local r = wraw(W, region)
	local set = r.SetVertexColor
	r.SetVertexColor = function(self, ...)
		set(self, ...)
		if select("#", ...) == 3 then
			r.alpha = 1
		end
	end
end

do
	local W = newWorld({ windows = true })
	cellFunctions(W)
	local cell = W.win.names.MerchantItem1
	resetting(W, wraw(W, cell).SlotTexture)
	resetting(W, W.env.MerchantItem1NameFrame)
	W.login()
	W.flush()
	check("vendor cell: the slot art and the name plate are transparent at the start", wa(W, wraw(W, cell).SlotTexture) == 0 and wa(W, W.env.MerchantItem1NameFrame) == 0)
	W.blizzard(function() W.env.SetItemButtonSlotVertexColor(cell, 1, 0, 0) end)
	check("vendor cell: the game sets the colour of the slot art and it is transparent again", wa(W, wraw(W, cell).SlotTexture) == 0, g(wa(W, wraw(W, cell).SlotTexture)))
	W.blizzard(function() W.env.SetItemButtonNameFrameVertexColor(cell, 0.9, 0, 0) end)
	check("vendor cell: the game sets the colour of the name plate and it is transparent again", wa(W, W.env.MerchantItem1NameFrame) == 0, g(wa(W, W.env.MerchantItem1NameFrame)))
	W.blizzard(function()
		W.env.SetItemButtonSlotVertexColor(nil, 1, 0, 0)
		W.env.SetItemButtonNameFrameVertexColor(nil, 1, 0, 0)
	end)
	check("vendor cell: a colour set on nothing changes nothing and raises nothing", #W.violations == 0 and #W.errors == 0)
	W.change("windows.npc", false)
	W.blizzard(function() W.env.SetItemButtonSlotVertexColor(cell, 1, 1, 1) end)
	check("vendor cell: with the vendor switched off the art is Blizzard's and a colour set later leaves it so", wa(W, wraw(W, cell).SlotTexture) == 1 and wa(W, W.env.MerchantItem1NameFrame) == 1)
	W.change("windows.npc", true)
	check("vendor cell: and transparent again when it is switched on", wa(W, wraw(W, cell).SlotTexture) == 0 and wa(W, W.env.MerchantItem1NameFrame) == 0)
	clean(W, "vendor cell colours")
end

do
	-- Arguments that are not a frame: nothing is looked up, nothing raises.
	local W = newWorld({ windows = true })
	W.env.SetItemButtonSlotVertexColor = function() end
	W.env.SetItemButtonNameFrameVertexColor = function() end
	W.login()
	W.flush()
	W.blizzard(function()
		W.env.SetItemButtonSlotVertexColor(SECRET, 1, 0, 0)
		W.env.SetItemButtonNameFrameVertexColor(SECRET, 1, 0, 0)
		W.env.SetItemButtonSlotVertexColor("cell", 1, 0, 0)
		W.env.SetItemButtonNameFrameVertexColor(5, 1, 0, 0)
		W.env.SetItemButtonSlotVertexColor(W.win.names.FriendsFrame, 1, 0, 0)
	end)
	check("vendor cell: a withheld value, a string, a number and a frame with no cell art are ignored", #W.violations == 0 and #W.errors == 0 and not has(W.status(), "failed"), wvio(W))
end

-- The trade window: the other player's portrait and ring, two border pieces, and the art behind its fourteen items.
local function tradeWorld(saved, prep)
	local W = newWorld({ windows = { only = {} }, saved = saved })
	cellFunctions(W)
	W.group = "windows"
	local root = W.win.portraitFrame(W.env.UIParent, nil, { name = "TradeFrame", hidden = true, width = 344, height = 446 }, "textured")
	local overlay = W.win.frame(root, "RecipientOverlay", {})
	W.win.tex(overlay, "portrait", nil)
	W.win.tex(overlay, "portraitFrame", "UI-Frame-PortraitMetal-CornerTopLeft")
	W.win.tex(root, nil, "UI-Frame-BotCornerLeft", { name = "TradeRecipientBotLeftCorner" })
	W.win.tex(root, "leftBorderBar", "!UI-Frame-LeftTile", { name = "TradeRecipientLeftBorder" })
	W.win.tex(root, nil, nil, { name = "TradeRecipientBG" })
	for _, side in ipairs({ "Player", "Recipient" }) do
		for index = 1, 7 do
			local name = "Trade" .. side .. "Item" .. index
			local cell = W.win.frame(root, nil, { name = name, width = 153, height = 37 })
			-- TradeItemTemplate draws all three on BACKGROUND (TradeFrame.xml:34-53).
			W.win.tex(cell, "SlotTexture", nil, { name = name .. "SlotTexture", layer = "BACKGROUND" })
			W.win.tex(cell, nil, nil, { name = name .. "NameFrame", layer = "BACKGROUND" })
			W.win.font(cell, nil, { name = name .. "Name", layer = "BACKGROUND" })
			W.win.itemButton(cell, nil, name .. "ItemButton")
			resetting(W, W.env[name .. "SlotTexture"])
			resetting(W, W.env[name .. "NameFrame"])
		end
	end
	if prep then
		prep(W)
	end
	W.group = "static"
	W.seal()
	W.login()
	W.flush()
	return W, root, overlay
end
local TRADE_CELLS = {}
for _, side in ipairs({ "Player", "Recipient" }) do
	for index = 1, 7 do
		TRADE_CELLS[#TRADE_CELLS + 1] = "Trade" .. side .. "Item" .. index
	end
end

do
	local W, root, overlay = tradeWorld()
	local o = wraw(W, overlay)
	local env = W.env
	check("trade: the other player's portrait and its ring are transparent", wa(W, o.portrait) == 0 and wa(W, o.portraitFrame) == 0)
	check("trade: the two border pieces of the other half are transparent, its tint is not", wa(W, env.TradeRecipientBotLeftCorner) == 0 and wa(W, env.TradeRecipientLeftBorder) == 0 and wa(W, env.TradeRecipientBG) == 1)
	local wrong = {}
	for _, name in ipairs(TRADE_CELLS) do
		local cell = env[name]
		if not (wa(W, env[name .. "SlotTexture"]) == 0 and wa(W, env[name .. "NameFrame"]) == 0 and W.state(env[name .. "ItemButton"]) == "SB" and W.state(cell) == ".") then
			wrong[#wrong + 1] = name
		end
	end
	check("trade: the slot art and the name plate of each of the fourteen items are transparent and the item buttons are slots", #wrong == 0, table.concat(wrong, " "))
	W.blizzard(function() env.SetItemButtonSlotVertexColor(env.TradeRecipientItem3, 1, 0, 0) env.SetItemButtonNameFrameVertexColor(env.TradeRecipientItem3, 0.9, 0, 0) end)
	check("trade: the game colours an item that cannot be used and its art is transparent again", wa(W, env.TradeRecipientItem3SlotTexture) == 0 and wa(W, env.TradeRecipientItem3NameFrame) == 0)
	W.change("windows.portrait", true)
	check("trade: with the portrait shown the other player's portrait and ring are back, the border pieces and the items stay flat",
		wa(W, o.portrait) == 1 and wa(W, o.portraitFrame) == 1 and wa(W, env.TradeRecipientBotLeftCorner) == 0 and wa(W, env.TradePlayerItem1SlotTexture) == 0)
	W.change("windows.portrait", false)
	W.change("windows.npc", false)
	local left = {}
	for _, name in ipairs(TRADE_CELLS) do
		if wa(W, env[name .. "SlotTexture"]) ~= 1 or wa(W, env[name .. "NameFrame"]) ~= 1 then
			left[#left + 1] = name
		end
	end
	check("trade: switched off, every piece of art is as Blizzard drew it", #left == 0 and wa(W, o.portrait) == 1 and wa(W, o.portraitFrame) == 1 and wa(W, env.TradeRecipientLeftBorder) == 1 and wa(W, env.TradeRecipientBotLeftCorner) == 1, table.concat(left, " "))
	W.change("windows.npc", true)
	check("trade: and flat again when it is switched on", wa(W, env.TradePlayerItem7SlotTexture) == 0 and wa(W, o.portraitFrame) == 0)
	clean(W, "trade window")
end

do
	-- A forbidden overlay is not read, and the rest of the window is done.
	local W, root, overlay = tradeWorld(nil, function(W) wf(W, W.env.TradeFrame.RecipientOverlay).forbidden = true end)
	check("trade: a forbidden overlay is not read and the items are still flat", #W.violations == 0 and wa(W, W.env.TradePlayerItem2SlotTexture) == 0 and wa(W, W.env.TradeRecipientLeftBorder) == 0, wvio(W))
end

do
	-- The vendor: the bronze strip along the bottom, the plates the money is on, and the round plates behind the page buttons.
	local W = newWorld({ windows = true })
	local names = W.win.names
	local env = W.env
	W.group = "windows"
	local plates = {}
	for _, name in ipairs({ "MerchantPrevPageButton", "MerchantNextPageButton" }) do
		local plate = W.win.tex(names[name], nil, nil)
		wraw(W, plate).GetDrawLayer = function() return "BACKGROUND", 0 end
		plates[#plates + 1] = plate
	end
	local money = {}
	for _, name in ipairs({ "MerchantMoneyBg", "MerchantExtraCurrencyBg" }) do
		local plate = W.win.frame(names.MerchantFrame, nil, { name = name })
		for _, part in ipairs({ "Left", "Middle", "Right" }) do
			money[#money + 1] = W.win.tex(plate, nil, nil, { name = name .. part })
		end
	end
	W.group = "static"
	W.seal()
	W.login()
	W.flush()
	local function alphas(list)
		local out = {}
		for _, region in ipairs(list) do
			out[#out + 1] = g(wa(W, region))
		end
		return table.concat(out, ",")
	end
	check("vendor: the round plates behind the page buttons are transparent and the arrows are not", alphas(plates) == "0,0" and wa(W, wraw(W, names.MerchantNextPageButton).states.Normal) == 1
		and wa(W, wraw(W, names.MerchantPrevPageButton).states.Highlight) == 1, alphas(plates))
	check("vendor: the six pieces of the two money plates are transparent", alphas(money) == "0,0,0,0,0,0", alphas(money))
	check("vendor: the bronze strip along the bottom is transparent", wa(W, env.MerchantFrameBottomLeftBorder) == 0)
	W.blizzard(function() env.MerchantFrameBottomLeftBorder:Hide() env.MerchantFrameBottomLeftBorder:Show() end)
	check("vendor: and stays so when the game hides and shows it for the buyback tab", wa(W, env.MerchantFrameBottomLeftBorder) == 0)
	W.change("windows.npc", false)
	check("vendor: switched off, the strip, the money plates and the page plates are as Blizzard drew them", alphas(plates) == "1,1" and alphas(money) == "1,1,1,1,1,1" and wa(W, env.MerchantFrameBottomLeftBorder) == 1)
	clean(W, "vendor art")
end

do
	-- The Friends window: the round picture at the top left belongs to the portrait setting.
	local W = newWorld({ windows = true })
