	check("friends: the round picture at the top left is transparent", wa(W, icon) == 0)
	W.blizzard(function() icon:SetTexture("Interface\\LFGFrame\\UI-LFR-PORTRAIT") end)
	check("friends: and stays so when the game sets its file again", wa(W, icon) == 0)
	W.change("windows.portrait", true)
	check("friends: with the portrait shown it is back", wa(W, icon) == 1)
	W.change("windows.portrait", false)
	W.change("windows.social", false)
	check("friends: with the window switched off it is as Blizzard drew it", wa(W, icon) == 1)
