end

do
	-- The ammo slot: the game hides the quality border on this slot, so no quality colour is taken.
	local W = newWorld({ windows = true })
	local names = W.win.names
	local border = W.rawOf[wraw(W, names.CharacterAmmoSlot).IconBorder]
	border.shown = true
	border.vertex = { 0.64, 0.21, 0.93, 1 }
	W.login()
	W.flush()
	local function edge(name)
		local o = W.look(names[name])
		return string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)
	end
	check("ammo slot: a border colour it had at the start is not taken", edge("CharacterAmmoSlot") == "0.00,0.00,0.00", edge("CharacterAmmoSlot"))
	W.setQuality(names.CharacterAmmoSlot, 4)
	check("ammo slot: a quality the game gives it is not taken either", edge("CharacterAmmoSlot") == "0.00,0.00,0.00", edge("CharacterAmmoSlot"))
	W.setQuality(names.CharacterHeadSlot, 4)
	check("ammo slot: another slot takes the colour of its item", edge("CharacterHeadSlot") == "0.64,0.21,0.93", edge("CharacterHeadSlot"))
	W.updateSlot("CharacterAmmoSlot", { broken = true })
	check("ammo slot: a red slot is still red", edge("CharacterAmmoSlot") == "0.90,0.00,0.00", edge("CharacterAmmoSlot"))
