		wa(W, wregion(W, bar, "common-stat-bar-BG")) == 0 and not wmasked(W, b.Fill, b.Mask) and #wboxes(W, bar) == 1 and wcolour(wfill(W, wboxes(W, bar)[1])) == WINDOW_FILL)
	W.change("windows.bars", false)
	check("pet bar: with progress bars switched off it is as Blizzard drew it", wa(W, wregion(W, bar, "common-stat-bar-BG")) == 1 and wmasked(W, b.Fill, b.Mask))
	W.change("windows.bars", true)
	W.change("windows.character", false)
	check("pet bar: with the character window switched off it is as Blizzard drew it too", wa(W, wregion(W, bar, "common-stat-bar-BG")) == 1)
