do
	-- A tab that hangs from the top of its window has its box the other way up.
	local W = newWorld({ windows = { extras = true } })
	local names = W.win.names
	wraw(W, W.env.FlatUITestSystemTab).isTabOnTop = true
	local second = W.win.panelTab(names.FriendsFrame, "FlatUITestTopTab")
	wraw(W, second).isTopTab = true
	W.login()
	W.flush()
	local function insets(tab)
		local p = wboxes(W, tab)[1].points
		return string.format("%g,%g,%g,%g", p[1][4], -p[1][5], -p[2][4], p[2][5])
	end
	check("tab on top: the box is 3 from the top and 1 from the bottom", insets(W.env.FlatUITestSystemTab) == "3,3,3,1", insets(W.env.FlatUITestSystemTab))
	check("tab on top: the key a panel top tab has gives the same", insets(second) == "3,3,3,1", insets(second))
	check("tab on top: a tab that hangs below its window is 1 from the top and 3 from the bottom", insets(names.FriendsFrameTab1) == "3,1,3,3", insets(names.FriendsFrameTab1))
	clean(W, "tab on top")
end

-- A change of look is applied to what is styled and does not sweep the windows again. A switch that goes on does.
do
	local W = newWorld({ windows = true })
	W.login()
	W.flush()
	local friends = W.win.names.FriendsFrame
	local function children() return wraw(W, friends).calls.GetChildren or 0 end
	local before = children()
	W.change("windows.opacity", 55)
	W.change("windows.panel", "ff336699")
	W.change("windows.accent", "ff994422")
	W.change("windows.crop", 12)
	W.change("windows.portrait", true)
	W.change("general.backdropAlpha", 60)
	W.flush()
	check("a change of look: the windows are not searched again", children() == before, children() - before)
	check("a change of look: and what is styled has the new look", wcolour(wfill(W, friends)):find(",0.55$") ~= nil and wcolour(wfill(W, W.win.names.FriendsFrameAddFriendButton)) == "0.200,0.400,0.600,1")
	W.group = "windows"
	local late = W.win.panelButton(friends, nil, "FlatUITestLateButton")
	W.group = "static"
	W.change("windows.buttons", false)
	check("a switch that goes off: the windows are not searched again and the new button is not styled", children() == before and W.state(late) == ".")
	W.change("windows.buttons", true)
	check("a switch that goes on: the windows are searched and the new button is styled", children() > before and W.state(late) == "SB")
	local count = children()
	W.change("windows.enabled", false)
	W.change("windows.enabled", true)
	check("the module switched off and on: the windows are searched again", children() > count)
	clean(W, "refresh")
end

do
	-- A window switched off at login and on later is searched when it goes on.
	local W = newWorld({ windows = true, saved = { options = { ["windows.social"] = false } } })
	W.login()
	W.flush()
	local friends = W.win.names.FriendsFrame
	check("friends switched off at login: nothing of the window is styled", W.state(friends) == "." and W.state(W.win.names.FriendsFrameAddFriendButton) == ".")
	W.change("windows.social", true)
	check("friends switched on later: the window and its buttons are styled", W.state(friends) == "SB" and W.state(W.win.names.FriendsFrameAddFriendButton) == "SB")
	clean(W, "window switched on later")
end

do
	-- The group switches that go on are all looked at, and a switch is looked at once.
	local W = newWorld({ windows = true, saved = { options = { ["windows.slots"] = false, ["windows.scroll"] = false } } })
	W.login()
	W.flush()
	local head = W.win.names.CharacterHeadSlot
	local bar = wraw(W, W.win.names.FriendsFrame).ScrollBar
	check("slots and scroll bars switched off at login: neither is styled", W.state(head) == "." and #wlines(W, wraw(W, bar).Back) == 0)
	W.change("windows.slots", true)
	check("slots switched on later: the slots are styled", W.state(head) == "SB")
	W.change("windows.scroll", true)
	check("scroll bars switched on later: the scroll bars are styled", #wlines(W, wraw(W, bar).Back, "OVERLAY") == 2)
end

-- A forbidden frame inside a window is not read to get at the parts the window has by name.
do
	local W, names = fw(true, function(W, n) wf(W, wraw(W, n.CharacterFrame).ModeTabs).forbidden = true end)
	check("forbidden mode tabs: nothing is read and the rest of the character window is styled", #W.violations == 0 and W.state(names.CharacterFrame) == "SB" and W.state(names.CharacterHeadSlot) == "SB", wvio(W))
	local W2, names2 = fw(true, function(W, n) wf(W, n.CharacterModelScene).forbidden = true end)
	check("forbidden model scene: nothing is read and the race art is left alone", #W2.violations == 0 and W2.state(names2.CharacterFrame) == "SB", wvio(W2))
end

do
	for _, case in ipairs({ { "SoloRoleButtons", function(W, n) return wraw(W, n.LFGListingFrame).SoloRoleButtons end },
		{ "GroupRoleButtons", function(W, n) return wraw(W, n.LFGListingFrame).GroupRoleButtons end },
		{ "CategoryView", function(W, n) return wraw(W, n.LFGListingFrame).CategoryView end },
		{ "the eye", function(W, n) return n.LFGParentFramePortrait end } }) do
		local W, names = fw({ lfg = "loaded" }, function(W, n) wf(W, case[2](W, n)).forbidden = true end)
		check("forbidden " .. case[1] .. ": nothing is read and the page around it is styled", #W.violations == 0 and #W.errors == 0 and W.state(names.LFGParentFrame) == "SB" and wa(W, wraw(W, wraw(W, names.LFGBrowseFrame).NineSlice).TopEdge) == 0, wvio(W))
	end
	local W = fw({ lfg = "loaded" }, function(W, n) wf(W, wraw(W, n.LFGListingFrame).CategoryView).forbidden = true end)
	W.win.updateCategories(2)
	W.flush()
	check("forbidden category list: the buttons the game makes are not looked for", #W.violations == 0 and #W.errors == 0, wvio(W))
end

-- A sweep that is cut short says so in /flatui status, once.
