-- Only a slot that is red in the red channel and nothing else has the red edge.
do
	local W = winWorld()
	local head = W.win.names.CharacterHeadSlot
	local function edge()
		local o = W.look(head)
		return string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)
	end
	for _, c in ipairs({ { 1, 0, 0, true }, { 0.5, 0, 0, true }, { 0, 0, 0, false }, { 0.9, 0.1, 0, false }, { 0.9, 0, 0.1, false }, { 0.5, 0.5, 0.5, false }, { 1, 1, 1, false } }) do
		W.blizzard(function() W.env.SetItemButtonNormalTextureVertexColor(head, c[1], c[2], c[3]) end)
		check(("slot colour %g, %g, %g: %s"):format(c[1], c[2], c[3], c[4] and "the red edge" or "no red edge"), (edge() == "0.90,0.00,0.00") == c[4], edge())
	end
	local H = winWorld({ hollowItems = true })
	local hollow = H.win.names.CharacterHeadSlot
	H.blizzard(function()
		H.env.SetItemButtonNormalTextureVertexColor(hollow, nil, nil, nil)
		H.env.SetItemButtonNormalTextureVertexColor(hollow, "x", 0, 0)
		H.env.SetItemButtonNormalTextureVertexColor(hollow, true, 0, 0)
		H.env.SetItemButtonNormalTextureVertexColor(hollow, 1, "x", 0)
	end)
	local o = H.look(hollow)
	check("slot colour that is not numbers: no red edge and nothing raises", string.format("%.2f", o.r) == "0.00" and #H.errors == 0 and #H.violations == 0, wvio(H))
end

