-- 76. Fixes after the second review of the window module. Each section is about one finding.

-- A protected window first met in combat has its art faded at once. What that pass did stays with the window until combat ends.
local function protectedWorld(saved)
	local W = newWorld({ windows = true, combat = true, saved = saved })
	W.win.protect(W.win.names.CharacterFrame, true)
	W.login()
	W.flush()
	return W
end
local function combatEnds(W)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
end
local function calm(W)
	return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "stopped")
end
local function modeTab(W, index)
	return wraw(W, W.win.names["CharacterFrameModeTab" .. index])
end

do
	-- The module switch is turned off in the combat: the window was never styled, and has Blizzard's art back all the same.
	local W = protectedWorld()
	local n = W.win.names
	local ref = winWorld(nil, { options = { ["windows.enabled"] = false } })
	local cf = wraw(W, n.CharacterFrame)
	check("protected window in combat: its top edge and the frame of its head slot are transparent at once", wa(W, wraw(W, cf.NineSlice).TopEdge) == 0 and wa(W, wraw(W, n.CharacterHeadSlot).NormalTexture) == 0)
	W.change("windows.enabled", false)
	W.flush()
	combatEnds(W)
	check("module switch off before combat ends: the top edge of the window and the frame of the head slot have Blizzard's alpha", wa(W, wraw(W, cf.NineSlice).TopEdge) == 1 and wa(W, wraw(W, n.CharacterHeadSlot).NormalTexture) == 1)
	check("module switch off before combat ends: the mode tab icon has Blizzard's coordinates and its mask", wtc(W, modeTab(W, 2).Icon) == wtc(ref, modeTab(ref, 2).Icon) and wmasked(W, modeTab(W, 2).Icon, modeTab(W, 2).Mask))
	check("module switch off before combat ends: the status says off and nothing was made on the window", W.line("Windows") == "Windows: off" and #wowned(W, n.CharacterFrame) == 0, W.line("Windows"))
	local wrong = wsame(wdump(ref, true), wdump(W, true))
	check("module switch off before combat ends: every Blizzard region is as if the module had been off from the start", #wrong == 0, #wrong .. " " .. table.concat(wrong, "; "):sub(1, 400))
	check("module switch off before combat ends: nothing raises", #W.violations == 0 and #W.errors == 0 and #W.out == 0, W.status())
	W.change("windows.enabled", true)
	W.flush()
	wrong = wsame(wdump(winWorld(), true), wdump(W, true))
	check("module switch on again after combat: the window is styled as if the module had been on all along", W.state(n.CharacterFrame) == "SB" and #wrong == 0, #wrong .. " " .. table.concat(wrong, "; "):sub(1, 400))
end

do
	-- Square side tab icons are turned off in the combat: the round mask the combat pass took off goes back.
	local W = protectedWorld()
	local ref = winWorld(nil, { options = { ["windows.squareTabs"] = false } })
	check("protected window in combat: a mode tab icon has lost its mask at once", not wmasked(W, modeTab(W, 2).Icon, modeTab(W, 2).Mask))
	W.change("windows.squareTabs", false)
	W.flush()
	combatEnds(W)
	local wrong = {}
	for index = 1, 6 do
		local t = modeTab(W, index)
		if not (wmasked(W, t.Icon, t.Mask) and wtc(W, t.Icon) == wtc(ref, modeTab(ref, index).Icon) and W.state(t.Icon) == "SB") then
			wrong[#wrong + 1] = index
		end
	end
	check("square side tab icons off before combat ends: the six mode tabs have their box, Blizzard's coordinates and the round mask", #wrong == 0, table.concat(wrong, " "))
	local diff = wsame(wdump(ref, true), wdump(W, true))
	check("square side tab icons off before combat ends: every Blizzard region is as if they had been off from the start", #diff == 0, #diff .. " " .. table.concat(diff, "; "):sub(1, 400))
	check("square side tab icons off before combat ends: nothing raises", calm(W), W.status())
	W.change("windows.enabled", false)
	W.flush()
	wrong = {}
	for index = 1, 6 do
		if not wmasked(W, modeTab(W, index).Icon, modeTab(W, index).Mask) then
			wrong[#wrong + 1] = index
		end
	end
	check("square side tab icons off before combat ends: and the mask is on after the module is switched off", #wrong == 0, table.concat(wrong, " "))
end

do
	-- Turned off and on again in the combat: the icons end up as they would have without the change.
	local W = protectedWorld()
	W.change("windows.squareTabs", false)
	W.change("windows.squareTabs", true)
	W.flush()
	combatEnds(W)
	local wrong = wsame(wdump(winWorld(), true), wdump(W, true))
	check("square side tab icons off and on before combat ends: every Blizzard region is as if nothing had changed", #wrong == 0, #wrong .. " " .. table.concat(wrong, "; "):sub(1, 400))
	check("square side tab icons off and on before combat ends: the icon is cropped without its mask", wtc(W, modeTab(W, 2).Icon) == "0.10625,0.89375,0.10625,0.89375" and not wmasked(W, modeTab(W, 2).Icon, modeTab(W, 2).Mask), wtc(W, modeTab(W, 2).Icon))
	check("square side tab icons off and on before combat ends: nothing raises", calm(W), W.status())
end

do
	-- Each switch that a kind of the protected window depends on, turned off in the combat.
	for _, path in ipairs({ "windows.character", "windows.buttons", "windows.tabs", "windows.sideTabs", "windows.scroll", "windows.checks", "windows.inputs", "windows.bars", "windows.slots" }) do
		local W = protectedWorld()
		W.change(path, false)
		W.flush()
