do
	-- A kind that is off when the protected window is first met has its art left alone, in the combat as well.
	local W = protectedWorld({ options = { ["windows.buttons"] = false } })
	local n = W.win.names
	local button = wraw(W, n.PaperDollEquipmentManagerPaneEquipSet)
