	check("a kind that is off at login in combat: and nothing differs from a start with it off when combat ends", #wrong == 0 and wa(W, button.Left) == 1 and W.state(n.PaperDollEquipmentManagerPaneEquipSet) == ".", #wrong .. " " .. table.concat(wrong, "; "):sub(1, 400))
end

-- The money plates of Send Mail and of the trade window are stripped like the vendor's.
