-- The seventh item on each side of the trade window is the slot for the item that is not traded: its picture stays.
local function pictureWorld(prep)
	local pictures = {}
	local W = tradeWorld(nil, function(W)
		for _, side in ipairs({ "Player", "Recipient" }) do
			-- The enchant icon is on ARTWORK (TradeFrame.xml:329-336, 386-393).
			pictures[side] = W.win.tex(W.env["Trade" .. side .. "Item7"], nil, nil, { layer = "ARTWORK", sublevel = 0 })
		end
		if prep then
			prep(W)
		end
	end)
	return W, pictures
end

do
	local W, pictures = pictureWorld()
	local env = W.env
	local function art(side)
		local name = "Trade" .. side .. "Item7"
		return g(wa(W, env[name .. "SlotTexture"])) .. g(wa(W, env[name .. "NameFrame"]))
	end
	check("trade: the picture on the seventh item of each side is not transparent", wa(W, pictures.Player) == 1 and wa(W, pictures.Recipient) == 1)
	check("trade: the slot art and the name plate of the seventh items are", art("Player") == "00" and art("Recipient") == "00")
	local wrong = {}
	for _, name in ipairs(TRADE_CELLS) do
		if wa(W, env[name .. "SlotTexture"]) ~= 0 or wa(W, env[name .. "NameFrame"]) ~= 0 then
			wrong[#wrong + 1] = name
		end
	end
	check("trade: the fourteen items are as flat as before", #wrong == 0, table.concat(wrong, " "))
	W.blizzard(function()
		env.SetItemButtonSlotVertexColor(env.TradePlayerItem7, 1, 0, 0)
		env.SetItemButtonNameFrameVertexColor(env.TradePlayerItem7, 0.9, 0, 0)
	end)
	check("trade: the game colours the seventh item and its art is transparent again, its picture is not", art("Player") == "00" and wa(W, pictures.Player) == 1)
	W.change("windows.npc", false)
	check("trade: switched off, the picture and the art are as Blizzard drew them", art("Player") == "11" and art("Recipient") == "11" and wa(W, pictures.Player) == 1 and wa(W, pictures.Recipient) == 1)
	W.change("windows.npc", true)
	check("trade: and the picture still stays when it is switched on", art("Recipient") == "00" and wa(W, pictures.Recipient) == 1 and wa(W, pictures.Player) == 1)
	clean(W, "trade picture")
end

do
	-- In combat on a protected trade window the picture is kept in the same way.
	local W, pictures = pictureWorld(function(W)
		W.combat = true
		W.win.protect(W.env.TradeFrame, true)
	end)
	local env = W.env
	check("trade in combat: the seventh item has its picture and no art behind it", wa(W, pictures.Player) == 1 and wa(W, pictures.Recipient) == 1 and wa(W, env.TradePlayerItem7SlotTexture) == 0 and wa(W, env.TradeRecipientItem7NameFrame) == 0 and #W.violations == 0, wvio(W))
	combatEnds(W)
	check("trade in combat: and when combat ends", wa(W, pictures.Player) == 1 and wa(W, pictures.Recipient) == 1 and wa(W, env.TradePlayerItem7SlotTexture) == 0 and W.state(env.TradePlayerItem7ItemButton) == "SB" and #W.violations == 0, wvio(W))
end

do
	-- A seventh item without the picture is stripped like the others.
	local W = tradeWorld()
	check("trade: a seventh item with no picture has its art transparent", wa(W, W.env.TradePlayerItem7SlotTexture) == 0 and wa(W, W.env.TradeRecipientItem7NameFrame) == 0)
end

-- A window is named in the status as a player knows it, and a frame with nothing below it is not reported.
local TITLES = {
	{ "CharacterFrame", "Character" }, { "LFGParentFrame", "Looking For Group" }, { "FriendsFrame", "Friends" }, { "SocialUIFrame", "Social" },
	{ "ChannelFrame", "Channels" }, { "RaidParentFrame", "Raid" }, { "MerchantFrame", "Vendor" }, { "MailFrame", "Mail" }, { "OpenMailFrame", "Open Mail" },
	{ "GossipFrame", "Gossip" }, { "QuestFrame", "Quest" }, { "QuestLogPopupDetailFrame", "Quest Log" }, { "ItemTextFrame", "Book" },
	{ "TradeFrame", "Trade" }, { "ClassTrainerFrame", "Trainer" },
}
local function tooLarge(title)
	return "Windows: part of the " .. title .. " window is too large and keeps Blizzard's look."
end

do
	local W = newWorld({ windows = { only = {} } })
	for _, case in ipairs(TITLES) do
		local parent = W.win.frame(W.env.UIParent, nil, { name = case[1] })
		for level = 1, 11 do
			parent = W.win.frame(parent, nil, {})
		end
	end
	W.login()
	W.flush()
	local status = W.status()
	local wrong = {}
	for _, case in ipairs(TITLES) do
		if count(status, tooLarge(case[2])) ~= 1 then
			wrong[#wrong + 1] = case[1]
		end
	end
	check("a sweep that goes too deep: every listed window is named in the status as a player knows it, once", #wrong == 0 and count(status, "is too large") == #TITLES, table.concat(wrong, " ") .. "\n" .. status)
	check("a sweep that goes too deep: the status has no frame name, no level and no count of frames", not has(status, "levels") and not has(status, "Frame ") and not has(status, "1500") and not has(status, "10 "), status)
end

do
	local function depth(chain, last)
		local W = newWorld({ windows = { only = {} } })
		local parent = W.win.frame(W.env.UIParent, nil, { name = "TradeFrame" })
		for level = 1, chain do
			parent = W.win.frame(parent, nil, {})
		end
		if last then
			last(W, parent)
		end
		W.login()
		W.flush()
		return W.status(), W
	end
	local status = depth(10)
	check("a frame at the tenth level with nothing below it: nothing is said", not has(status, "keeps Blizzard's look"), status)
	status = depth(11)
	check("a frame at the tenth level with a frame below it: the status says so", count(status, tooLarge("Trade")) == 1, status)
	local W
	status, W = depth(10, function(W, parent)
		wf(W, W.win.frame(parent, nil, {})).forbidden = true
	end)
	check("a frame at the tenth level with only a forbidden frame below it: nothing is said and nothing is read", not has(status, "keeps Blizzard's look") and #W.violations == 0, status .. wvio(W))
	status = depth(9, function(W, parent)
		local box = W.win.frame(parent, nil, {})
		W.win.tex(box, "TopLeftTex", nil)
		W.win.tex(box, "MiddleTex", nil)
	end)
	check("a text box with several lines at the tenth level has only the outline of the addon below it: nothing is said", not has(status, "keeps Blizzard's look"), status)
	status = depth(9, function(W, parent)
		local box = W.win.frame(parent, nil, {})
		W.win.tex(box, "TopLeftTex", nil)
		W.win.tex(box, "MiddleTex", nil)
		W.win.frame(box, nil, {})
	end)
	check("a text box with several lines at the tenth level has a frame of Blizzard's below it: the status says so", count(status, tooLarge("Trade")) == 1, status)
end

do
	-- Both limits reached in one window: one line.
	local W = newWorld({ windows = { only = {} } })
	local root = W.win.frame(W.env.UIParent, nil, { name = "TradeFrame" })
	local parent = root
	for level = 1, 12 do
		parent = W.win.frame(parent, nil, {})
	end
	for index = 1, 1600 do
		W.win.frame(root, nil, {})
	end
	W.login()
	W.flush()
	check("a window that is too deep and has too many frames: the status says so once", count(W.status(), tooLarge("Trade")) == 1 and count(W.status(), "is too large") == 1, W.status())
end
end

-- 75. Nameplates: bar heights, flat health bar, text sizes, level box and class icons.
-- The simulated nameplate is built the way Blizzard's XML and Lua build it for Forever, and only in a world that
-- asks for it (npWorld), so every section above runs as before.
do
	-- Blizzard_NamePlates/Camelot/Blizzard_NamePlateConstants.lua and Blizzard_NamePlates.lua (UpdateNamePlateOptions).
	-- What the sections of this block share is kept in NP: the main chunk allows 200 locals alive at once.
	local NP = {}
	NP.STYLE = { Modern = 0, Thin = 1, Block = 2, HealthFocus = 3, CastFocus = 4, Legacy = 5, Classic = 6 }
	NP.INSIDE, NP.ABOVE, NP.CENTERED = 1, 2, 3
	NP.SCALES = {
		{ horizontal = 0.75, vertical = 0.8, classification = 0.8 },
		{ horizontal = 1, vertical = 1, classification = 1 },
		{ horizontal = 1.25, vertical = 1.25, classification = 1.25 },
		{ horizontal = 1.4, vertical = 1.4, classification = 1.4 },
		{ horizontal = 1.6, vertical = 1.6, classification = 1.6 },
	}
	NP.CLASSIC_SCALES = { { horizontal = 0.8, vertical = 0.8, classification = 0.8 }, NP.SCALES[2], NP.SCALES[3], NP.SCALES[4], NP.SCALES[5] }
	-- GameFonts.xml: the height of the Roman member of each font object, and whether it is outlined.
	NP.FONTS = {
		SystemFont_NamePlate = { height = 9, outline = false },
		SystemFont_NamePlate_Outlined = { height = 9, outline = true },
		SystemFont_NamePlateLevel = { height = 10, outline = true },
	}
	NP.PLAIN, NP.OUTLINED = "SystemFont_NamePlate", "SystemFont_NamePlate_Outlined"
	NP.BAR_ATLAS = "UI-HUD-CoolDownManager-Bar"
	NP.CLASSIC_FILL = "Interface\\TargetingFrame\\UI-TargetingFrame-BarFill"
	-- Blizzard_FrameXMLBase/Camelot/Constants.lua: Forever has nine classes.
	NP.CLASSES = { "WARRIOR", "PALADIN", "PRIEST", "SHAMAN", "DRUID", "ROGUE", "MAGE", "WARLOCK", "HUNTER" }

	function NP.constants()
		return {
			SELECTED_BORDER_ATLAS = "UI-HUD-CoolDownManager-Selected-yellow",
			DEBUFF_PADDING_CVAR = "nameplateDebuffPadding",
			SIZE_CVAR = "nameplateSize",
			STYLE_CVAR = "nameplateStyle",
			SHOW_ONLY_NAME_FOR_FRIENDLY_PLAYER_UNITS_CVAR = "nameplateShowOnlyNameForFriendlyPlayerUnits",
			HEALTH_BAR_FONT_HEIGHT = 14, SMALL_HEALTH_BAR_HEIGHT = 13, LARGE_HEALTH_BAR_HEIGHT = 20,
			SMALL_CAST_BAR_HEIGHT = 6, LARGE_CAST_BAR_HEIGHT = 16, CAST_BAR_ICON_HEIGHT = 10,
			SMALL_LEVEL_INDICATOR_HEIGHT = 16, LARGE_LEVEL_INDICATOR_HEIGHT = 23, LEVEL_INDICATOR_WIDTH = 28, LEVEL_FONT_HEIGHT = 10,
			NAME_ANCHOR_STYLES = { InsideHealthBar = NP.INSIDE, AboveHealthBar = NP.ABOVE, CenteredAboveHealthBar = NP.CENTERED },
		}
	end

	-- What Blizzard writes into NamePlateSetupOptions for a style and a size, as UpdateNamePlateOptions does.
	function NP.setupFor(style, size)
		local classic = style == NP.STYLE.Classic
		local s = (classic and NP.CLASSIC_SCALES or NP.SCALES)[size] or NP.SCALES[2]
		local large = style == NP.STYLE.Modern or style == NP.STYLE.Block
		return {
			horizontalScale = s.horizontal, verticalScale = s.vertical,
			healthBarHeight = (classic and 10 or ((large or style == NP.STYLE.HealthFocus) and 20 or 13)) * s.vertical,
			healthBarFontHeight = (classic and 10 or 14) * s.vertical,
			useClassicHealthBar = classic,
			healthBarToNameAboveSpacing = (classic and 4 or 2) * s.vertical,
			castBarHeight = (classic and 10 or ((style == NP.STYLE.CastFocus or style == NP.STYLE.Block) and 16 or 6)) * s.vertical,
			castBarFontHeight = 10 * s.vertical,
			useClassicCastBar = classic,
			castBarToHealthBarSpacing = (classic and 4 or 2) * s.vertical,
			castIconWidth = 10 * s.vertical, castIconHeight = 10 * s.vertical,
			playerLevelDiffHeight = (large and 23 or 16) * s.classification,
			playerLevelDiffWidth = 28 * s.classification,
			unitNameAnchorStyle = large and NP.INSIDE or (classic and NP.CENTERED or NP.ABOVE),
			spellNameInsideCastBar = style == NP.STYLE.Block or style == NP.STYLE.CastFocus or classic,
			levelFontHeight = 10 * s.vertical,
			levelIconWidth = 15 * s.horizontal, levelIconHeight = 15 * s.vertical,
			insetWidth = 12 * s.horizontal,
			-- Camelot/Blizzard_NamePlateFrameOptionsOverrides.lua
			healthTextInsideBarWhenNameAboveHealthBar = true,
			nameJustificationWhenAboveHealthBar = "CENTER",
			useOutlinedFontWhenAboveHealthBar = true,
		}
	end

	-- GetNamePlateFontObject, Blizzard_NamePlateUnitFrame.lua:13-27.
	function NP.fontObjectFor(o)
		if o.unitNameAnchorStyle == NP.INSIDE or o.unitNameAnchorStyle == NP.CENTERED then
			return NP.OUTLINED
		end
		if o.unitNameAnchorStyle == NP.ABOVE and o.useOutlinedFontWhenAboveHealthBar then
			return NP.OUTLINED
		end
		return NP.PLAIN
	end

	-- A font string takes its height from its font object, and SetTextHeight scales it.
	function NP.addFont(W, r, font)
		r.fontObject, r.textHeight, r.text = font, NP.FONTS[font].height, ""
		function r.SetFontObject(_, object)
			if type(object) ~= "string" or not NP.FONTS[object] then
				bad(W, "SetFontObject: a font object is expected, got " .. tostring(object))
			end
			r.fontObject, r.textHeight = object, NP.FONTS[object].height
		end
		function r.SetTextHeight(_, h)
			if r.textFault and W.inBlizzard == 0 then
				error("SetTextHeight failed", 0)
			end
			argn(W, "SetTextHeight", h)
			if h <= 0 then
				bad(W, "SetTextHeight: not positive")
			end
			r.textHeight = h
		end
		function r.SetFontHeight(_, h)
			argn(W, "SetFontHeight", h)
			r.textHeight = h
		end
		-- Blizzard puts the height back with SetFontHeight(GetLineHeight()). Whether the line height follows SetTextHeight is not in the source.
		function r.GetLineHeight() return W.npLineUnscaled and NP.FONTS[r.fontObject].height or r.textHeight end
	end

	-- Every call on a Blizzard object is kept with who made it: the addon (outside Blizzard's own code) or Blizzard.
	function NP.watch(W, raw, label, names)
		for _, name in ipairs(names) do
			local original = raw[name]
			if original then
				raw[name] = function(self, ...)
					W.npLog[#W.npLog + 1] = { label = label, call = name, addon = W.inBlizzard == 0, n = select("#", ...), ... }
					return original(self, ...)
				end
			end
		end
	end

	-- The calls on one object, from the log position `from`: by the addon (true), by Blizzard (false) or both (nil).
	function NP.calls(W, label, call, addon, from)
		local list = {}
		for i = (from or 0) + 1, #W.npLog do
			local e = W.npLog[i]
			if (label == nil or e.label == label) and (call == nil or e.call == call) and (addon == nil or e.addon == addon) then
				list[#list + 1] = e
			end
		end
		return list
	end

	function NP.colourText(c)
		if c == nil then
			return "none"
		end
		local parts = {}
		for i = 1, 4 do
			parts[i] = rawequal(c[i], SECRET) and "secret" or g(c[i])
		end
		return table.concat(parts, ",")
	end

	-- Adds the nameplate client to a world: Blizzard's globals, a unit frame built from the XML, and Blizzard's own flows.
	function NP.decorate(W, setup)
		local env = W.env
		local ns = W.ns
		W.npLog, W.npUnits, W.npCallbacks, W.npFrames, W.npHookLog, W.npCreated, W.npChecks = {}, {}, {}, {}, {}, {}, 0
		W.npCVars = { nameplateShowOnlyNameForFriendlyPlayerUnits = false }
		W.npAtlases, W.npAtlasCalls, W.npClassCalls, W.npUnitCalls = {}, {}, 0, {}
		for _, class in ipairs(NP.CLASSES) do
			W.npAtlases["classicon-" .. class:lower()] = true
			W.npAtlases["groupfinder-icon-class-" .. class:lower()] = true
		end
		W.npStyle, W.npSize = setup.style or NP.STYLE.Thin, setup.size or 2
		W.castFills, W.npCastBars = {}, setmetatable({}, { __mode = "k" })
		W.npKindCalls = {}

		local function luaMethod(name, fn)
			return function(...)
				if W.inBlizzard == 0 then
					bad(W, "the addon called the Blizzard method " .. name)
				end
				return fn(...)
			end
		end

		-- The restrictions of the client on addon code: whether a protected call is allowed now.
		local function allowed(r)
			local v = W.npAllow
			if type(v) == "function" then
				return v(r)
			elseif v ~= nil then
				return v == true
			end
			return not W.combat
		end
		W.npAllowed = allowed
		local function restricted(r)
			local original = r.SetHeight
			r.SetHeight = function(self, h)
				if r.heightFault and W.inBlizzard == 0 then
					error("SetHeight failed", 0)
				end
				if W.inBlizzard == 0 and not allowed(r) then
					bad(W, "the game refused SetHeight on " .. tostring(r.label))
				end
				return original(self, h)
			end
			-- The level box part sets a size and anchors of the same frames, and the game refuses them in combat too.
			for _, name in ipairs({ "SetSize", "SetPoint" }) do
				local plain = r[name]
				r[name] = function(self, ...)
					if W.inBlizzard == 0 and not allowed(r) then
						bad(W, "the game refused " .. name .. " on " .. tostring(r.label))
					end
					return plain(self, ...)
				end
			end
		end

		-- Globals ------------------------------------------------------------------------------------
		env.NamePlateConstants = NP.constants()
		env.NamePlateSetupOptions = NP.setupFor(W.npStyle, W.npSize)
		if not setup.noRestricted then
			env.C_RestrictedActions = { CheckAllowProtectedFunctions = function(object, silent)
				if type(object) ~= "table" or rawequal(object, SECRET) then
					bad(W, "CheckAllowProtectedFunctions: a frame is expected")
				end
				if silent ~= true then
					W.npLoud = (W.npLoud or 0) + 1
				end
				W.npChecks = W.npChecks + 1
				local fault = W.npCheckFault
				if fault == "error" then
					error("CheckAllowProtectedFunctions failed", 0)
				elseif fault == "secret" then
					return SECRET
				elseif fault == "string" then
					return "no"
				end
				return allowed(W.rawOf[object])
			end }
		end
		env.C_Texture = {
			GetAtlasExists = function(atlas)
				if type(atlas) ~= "string" then
					bad(W, "GetAtlasExists: a name is expected")
				end
				W.npAtlasCalls[atlas] = (W.npAtlasCalls[atlas] or 0) + 1
				local v = W.npAtlases[atlas]
				if v == "error" then
					error("GetAtlasExists failed", 0)
				elseif v == "secret" then
					return SECRET
				end
				return v == true
			end,
			GetAtlasInfo = function(atlas)
				if type(atlas) ~= "string" then
					bad(W, "GetAtlasInfo: a name is expected")
				end
				W.npAtlasCalls[atlas] = (W.npAtlasCalls[atlas] or 0) + 1
				local v = W.npAtlases[atlas]
				if v == "error" then
					error("GetAtlasInfo failed", 0)
				end
				if v == true then
					return { width = 64, height = 64 }
				end
			end,
		}
		-- UnitClassBase: MayReturnNothing, and secret where the unit's identity is restricted.
		env.UnitClassBase = function(unit)
			if type(unit) ~= "string" then
				bad(W, "UnitClassBase: a unit token is expected")
			end
			W.npClassCalls = W.npClassCalls + 1
			W.npUnitCalls[unit] = (W.npUnitCalls[unit] or 0) + 1
			local info = W.npUnits[unit]
			local class = info and info.class
			if type(class) == "function" then
				class = class()
			end
			if class == "error" then
				error("UnitClassBase failed", 0)
			elseif class == "secret" then
				return SECRET, SECRET
			elseif class == nil then
				return
			end
			for i, token in ipairs(NP.CLASSES) do
				if token == class then
					return class, i
				end
			end
			return class, 99
		end

		-- The hook runs as the addon, not as the Blizzard function it follows.
		local baseHook = env.hooksecurefunc
		env.hooksecurefunc = function(object, name, hook)
			W.npHookLog[#W.npHookLog + 1] = { object = object, name = name, hook = hook }
			return baseHook(object, name, function(...)
				local saved = W.inBlizzard
				W.inBlizzard = 0
				local ok, err = pcall(hook, ...)
				W.inBlizzard = saved
				if not ok then
					error(err, 0)
				end
			end)
		end
		-- Frames the addon makes: who shows or hides them.
		local baseCreate = env.CreateFrame
		env.CreateFrame = function(...)
			if W.npCreateFault and W.npCreateFault[select(3, ...)] then
				error("CreateFrame failed", 0)
			end
			local frame = baseCreate(...)
			W.npCreated[#W.npCreated + 1] = frame
			local label = "made" .. #W.npCreated
			frame.label = label
			NP.watch(W, frame, label, { "Show", "Hide", "SetShown" })
			return frame
		end
		-- UnitClassification and UnitIsBossMob answer from the info of the unit (classification, boss); either can be "error", "secret" or a function.
		local function unitAnswer(name, key, normal)
			return function(unit)
				if type(unit) ~= "string" then
					bad(W, name .. ": a unit token is expected")
				end
				W.npKindCalls[name] = (W.npKindCalls[name] or 0) + 1
				local info = W.npUnits[unit]
				local answer = info and info[key]
				if type(answer) == "function" then
					answer = answer()
				end
				if answer == "error" then
					error(name .. " failed", 0)
				elseif answer == "secret" then
					return SECRET
				elseif answer == nil then
					return normal
				end
				return answer
			end
		end
		env.UnitClassification = unitAnswer("UnitClassification", "classification", "normal")
		env.UnitIsBossMob = unitAnswer("UnitIsBossMob", "boss", false)
		if rawget(env, "CreateColor") == nil then
			env.CreateColor = function(r, g, b, a)
				argn(W, "CreateColor", r, g, b)
				return setmetatable({ r = r, g = g, b = b, a = a or 1 }, COLOUR_MT)
			end
		end
		for _, dotted in ipairs(setup.without or {}) do
			local owner, key = dotted:match("^(.-)%.?([%w_]+)$")
			local target = env
			for part in owner:gmatch("[%w_]+") do
				target = target[part]
			end
			target[key] = nil
		end
		if setup.castFill then
			-- Bars.lua defines ns.CastFill and the Cast bars call it for their own bars too: only the calls about the cast bar of a plate
			-- are recorded, the rest go to the real function.
			local real = ns.CastFill
			ns.CastFill = function(key, castBar, flat)
				if W.npCastBars[castBar] then
					W.castFills[#W.castFills + 1] = { key = key, bar = castBar, flat = flat }
				else
					return real(key, castBar, flat)
				end
			end
		elseif setup.castFill == false then
			ns.CastFill = nil
		end

		-- Blizzard's own flows -----------------------------------------------------------------------------
		local frames, plates = 0, 0
		-- A unit frame as the XML builds it: Blizzard_NamePlates.xml:93-365 and Camelot/Blizzard_NamePlateLevelFrame.xml.
		function W.npFrame(o)
			o = o or {}
			frames = frames + 1
			local id = o.id or ("f" .. frames)
			local F = { id = id }
			W.group = "nameplate"
			local B, Rr = W.B, W.Rr
			local function fontString(font, label)
				local p, r = Rr(nil, nil, { kind = "FontString" })
				NP.addFont(W, r, font)
				NP.watch(W, r, id .. "." .. label, { "SetFontObject", "SetTextHeight", "SetFontHeight", "SetAlpha", "SetText", "Show", "Hide", "SetShown" })
				return p, r
			end
			local fill, fillr = Rr(nil, NP.BAR_ATLAS)
			local bg = Rr(nil, "UI-HUD-CoolDownManager-Bar-BG")
			local sel = Rr(nil, "UI-HUD-CoolDownManager-Selected-yellow")
			local over = Rr(nil, "ui-hud-nameplates-deselected-overlay")
			local text, textr = fontString(NP.PLAIN, "Text")
			local right, rightr = fontString(NP.PLAIN, "RightText")
			local left, leftr = fontString(NP.PLAIN, "LeftText")
			local hb, hbr = B(nil, { barTexture = fill, bgTexture = bg, selectedBorder = sel, deselectedOverlay = over, Text = text, RightText = right, LeftText = left },
				{ objectType = "StatusBar" })
			local lIcon = Rr(nil, "ui-hud-nameplates-levelindicator")
			local lSel = Rr(nil, "ui-hud-nameplates-levelindicator-rectangle-selected")
			local lText, lTextr = fontString("SystemFont_NamePlateLevel", "LevelText")
			local lSkull, lSkullr = Rr(nil, "ui-hud-nameplates-levelindicator-skull")
			lSkullr.width, lSkullr.height = 18, 18
			local level, levelr = B(nil, { playerLevelDiffIcon = lIcon, playerLevelDiffText = lText, selectedBorder = lSel, highLevelTexture = lSkull })
			local cBg, cBorder = Rr(nil, "ui-castingbar-background"), Rr(nil, "ui-castingbar-frame")
			local cast, castr
			if o.fillCast then
				-- A cast bar with the fill, spark and shield of Blizzard_NamePlateCastingBar.xml, hidden until a cast shows it: W.fills.castStart(F.castName, "cast").
				F.castName = id .. "CastBar"
				cast, castr = W.fills.newCastBar(F.castName, { objectType = "StatusBar" }, { Background = cBg, Border = cBorder })
			else
				cast, castr = B(nil, { Background = cBg, Border = cBorder }, { objectType = "StatusBar" })
			end
			W.npCastBars[cast] = true
			local hc, hcr = B(nil, { healthBar = hb })
			local cc, ccr = B(nil, { castBar = cast })
			local name, namer = fontString(NP.PLAIN, "name")
			local mIcon = Rr(nil, nil)
			local marker, markerr = B(nil, { RaidTargetIcon = mIcon }, { width = 22, height = 22 })
			markerr.points = { { "RIGHT", hc, "LEFT", 0, 0 } }
			local ccList, ccListr = B(nil)
			local lossList, lossListr = B(nil)
			local aurasFrame = B(nil, { CrowdControlListFrame = ccList, LossOfControlFrame = lossList })
			local uf, u = B(nil, { name = name, HealthBarsContainer = hc, CastBarsContainer = cc, PlayerLevelDiffFrame = level, AurasFrame = aurasFrame, RaidTargetFrame = marker },
				{ forbidden = o.forbidden, objectType = "Button" })
			W.group = "static"
			-- Blizzard's own code reaches a frame the addon may not; the proxy lets nobody in.
			local function call(key, ...)
				if o.forbidden then
					return u[key](uf, ...)
				end
				return uf[key](uf, ...)
			end
			F.call = call
			F.uf, F.u, F.hb, F.hbr, F.fill, F.fillr, F.level, F.levelr, F.cast, F.castr = uf, u, hb, hbr, fill, fillr, level, levelr, cast, castr
			F.hc, F.hcr, F.cc, F.ccr, F.name, F.namer = hc, hcr, cc, ccr, name, namer
			F.skullr, F.ccList, F.ccListr, F.lossList, F.lossListr, F.marker, F.markerr = lSkullr, ccList, ccListr, lossList, lossListr, marker, markerr
			markerr.label = id .. ".RaidTargetFrame"
			ccListr.label, lossListr.label = id .. ".CrowdControlListFrame", id .. ".LossOfControlFrame"
			F.text, F.textr, F.left, F.leftr, F.right, F.rightr, F.lText, F.lTextr = text, textr, left, leftr, right, rightr, lText, lTextr
			F.healthBar, F.castBar = hb, cast
			F.strings = { text, left, right }
			F.stringsr = { textr, leftr, rightr }
			hcr.label, ccr.label, castr.label, levelr.label, hbr.label, u.label = id .. ".HealthBarsContainer", id .. ".CastBarsContainer", id .. ".castBar",
				id .. ".PlayerLevelDiffFrame", id .. ".healthBar", id .. ".UnitFrame"
			-- The level frame is anchored LEFT to the health container's RIGHT at x 5, and sized by ApplyFrameOptions.
			levelr.points = { { "LEFT", hc, "RIGHT", 5, 0 } }
			levelr.width, levelr.height = 28, 16
			hcr.height, ccr.height, castr.height = 13, 16, 6
			-- The bar colour is the vertex colour of the fill. Setting the fill's asset keeps it unless W.npResets names the call that resets it.
			hbr.barColor = { 1, 1, 1, 1 }
			function hbr.GetStatusBarColor()
				if hbr.colorFault == "error" then
					error("GetStatusBarColor failed", 0)
				end
				local c = hbr.barColor
				return c[1], c[2], c[3], c[4]
			end
			function hbr.SetStatusBarColor(_, ...)
				local n = select("#", ...)
				if n < 3 or n > 4 then
					bad(W, "SetStatusBarColor: 3 or 4 colour values expected")
				end
				if hbr.setColorFault and W.inBlizzard == 0 then
					error("SetStatusBarColor failed", 0)
				end
				for i = 1, n do
					local v = (select(i, ...))
					if not rawequal(v, SECRET) and not isnum(v) then
						bad(W, "SetStatusBarColor: a number is expected")
					end
				end
				hbr.barColor = { (select(1, ...)), (select(2, ...)), (select(3, ...)), n == 4 and (select(4, ...)) or hbr.barColor[4] }
			end
			for _, method in ipairs({ "SetColorTexture", "SetAtlas", "SetTexture" }) do
				local original = fillr[method]
				fillr[method] = function(self, ...)
					local result = original(self, ...)
					-- A colour texture replaces the file, as SetAtlas and SetTexture replace each other's.
					if method == "SetColorTexture" then
						fillr.file = nil
					end
					if W.npResets and W.npResets[method] then
						hbr.barColor = { 1, 1, 1, 1 }
					end
					return result
				end
			end
			NP.watch(W, fillr, id .. ".barTexture", { "SetColorTexture", "SetAtlas", "SetTexture", "SetAlpha", "SetVertexColor" })
			NP.watch(W, hbr, id .. ".healthBar", { "SetStatusBarColor", "GetStatusBarColor", "SetPoint", "ClearAllPoints", "SetAlpha", "Show", "Hide" })
			for _, r in ipairs({ hcr, ccr, castr, levelr, ccListr, lossListr }) do
				restricted(r)
			end
			NP.watch(W, hcr, id .. ".HealthBarsContainer", { "SetHeight", "SetSize", "SetPoint", "ClearAllPoints", "Show", "Hide", "SetAlpha", "SetScale" })
			NP.watch(W, ccr, id .. ".CastBarsContainer", { "SetHeight", "SetSize", "SetPoint", "ClearAllPoints", "Show", "Hide", "SetAlpha", "SetScale" })
			NP.watch(W, castr, id .. ".castBar", { "SetHeight", "SetSize", "SetPoint", "ClearAllPoints", "Show", "Hide", "SetAlpha", "SetScale" })
			NP.watch(W, markerr, id .. ".RaidTargetFrame", { "SetPoint", "SetSize", "ClearAllPoints" })
			NP.watch(W, ccListr, id .. ".CrowdControlListFrame", { "SetPoint", "ClearAllPoints" })
			NP.watch(W, lossListr, id .. ".LossOfControlFrame", { "SetPoint", "ClearAllPoints" })
			NP.watch(W, lSkullr, id .. ".highLevelTexture", { "SetSize", "SetPoint" })
			NP.watch(W, levelr, id .. ".PlayerLevelDiffFrame", { "SetSize", "SetWidth", "SetHeight", "SetPoint", "ClearAllPoints", "SetAllPoints", "Show", "Hide", "SetScale", "SetAlpha", "SetShown" })
			NP.watch(W, u, id .. ".UnitFrame", { "SetPoint", "ClearAllPoints", "SetAllPoints", "CreateTexture", "CreateLine", "Show", "Hide", "SetAlpha", "SetScale", "SetSize", "SetHeight", "SetWidth" })

			-- The Lua methods of NamePlateUnitFrameMixin, copied onto the frame. Only Blizzard's own code may call them.
			F.anchorPasses = 0
			local function after()
				if W.npOnLayout then
					W.npOnLayout(F)
				end
			end
			local function method(key, fn)
				u[key] = luaMethod(key, fn)
			end
			-- UpdateAnchors, Blizzard_NamePlateUnitFrame.lua:678-891, for what the addon reads and what it puts back.
			method("UpdateAnchors", function()
				F.anchorPasses = F.anchorPasses + 1
				local options = env.NamePlateSetupOptions
				local displayLevel = u.unit ~= nil and not u.showOnlyName and not F.noRoom
				local levelWidth, levelAnchor = 0, nil
				if displayLevel then
					local _, _, relativePoint, offsetX = levelr.GetPoint(level)
					levelAnchor = relativePoint
					levelWidth = levelr.GetWidth(level) + math.abs(offsetX)
				end
				-- Blizzard's code reaches every part, forbidden or not, so it calls the parts' own functions.
				ccr.ClearAllPoints(cc)
				ccr.SetPoint(cc, "BOTTOMLEFT", uf, "BOTTOMLEFT", options.insetWidth, 0)
				ccr.SetPoint(cc, "BOTTOMRIGHT", uf, "BOTTOMRIGHT", -options.insetWidth, 0)
				hcr.ClearAllPoints(hc)
				hcr.SetPoint(hc, "BOTTOMLEFT", cc, "TOPLEFT", 0, options.castBarToHealthBarSpacing)
				hcr.SetPoint(hc, "BOTTOMRIGHT", cc, "TOPRIGHT", (displayLevel and levelAnchor == "RIGHT") and -levelWidth or 0, options.castBarToHealthBarSpacing)
				hcr.SetHeight(hc, options.healthBarHeight)
				local auraRoom = (displayLevel and levelAnchor == "RIGHT") and levelWidth or 0
				markerr.ClearAllPoints(marker)
				if u.showOnlyName then
					markerr.SetPoint(marker, "BOTTOM", name, "TOP", 0, 10)
				else
					markerr.SetPoint(marker, "RIGHT", hc, "LEFT", 0, 0)
				end
				ccListr.SetPoint(ccList, "LEFT", hc, "RIGHT", 5 + auraRoom, 0)
				lossListr.SetPoint(lossList, "LEFT", hc, "RIGHT", 5 + auraRoom, 0)
				hbr.ClearAllPoints(hb)
				name:ClearAllPoints()
				if options.useClassicHealthBar then
					fill:SetTexture(NP.CLASSIC_FILL)
				else
					fill:SetAtlas(NP.BAR_ATLAS, true)
				end
				hbr.SetPoint(hb, "TOPLEFT", hc, "TOPLEFT", 0, 0)
				hbr.SetPoint(hb, "BOTTOMRIGHT", hc, "BOTTOMRIGHT", 0, 0)
				name:SetPoint("LEFT", hc, "LEFT", 4, 0)
				name:SetFontHeight(name:GetLineHeight())
			end)
			-- Blizzard_NamePlateUnitFrame.lua:213-247
			method("ApplyFrameOptions", function()
				local options = env.NamePlateSetupOptions
				ccr.SetHeight(cc, options.spellNameInsideCastBar and options.castBarHeight or options.castBarHeight + options.castIconHeight)
				castr.SetHeight(cast, options.castBarHeight)
				local font = NP.fontObjectFor(options)
				name:SetFontObject(font)
				name:SetTextHeight(options.healthBarFontHeight)
				for _, s in ipairs({ text, left, right }) do
					s:SetFontObject(font)
					s:SetTextHeight(options.healthBarFontHeight)
				end
				sel:SetAtlas(env.NamePlateConstants.SELECTED_BORDER_ATLAS)
				levelr.SetSize(level, options.playerLevelDiffWidth, options.playerLevelDiffHeight)
				lSkullr.SetSize(lSkull, options.playerLevelDiffHeight, options.playerLevelDiffHeight)
				lText:SetTextHeight(options.levelFontHeight)
				call("UpdateAnchors")
				after()
			end)
			method("IsPlayer", function() return u.isPlayer == true end)
			method("IsFriend", function() return u.isFriend == true end)
			method("UpdateShowOnlyName", function()
				local show = call("IsFriend") and call("IsPlayer") and W.npCVars.nameplateShowOnlyNameForFriendlyPlayerUnits == true
				if u.showOnlyName == show then
					return
				end
				u.showOnlyName = show
				call("UpdateAnchors")
				after()
			end)
			method("UpdateIsPlayer", function()
				local info = u.unit ~= nil and W.npUnits[u.unit] or nil
				local isPlayer = false
				if info then
					isPlayer = info.player == nil and false or info.player
				end
				if u.isPlayer == isPlayer then
					return
				end
				u.isPlayer = isPlayer
				call("UpdateShowOnlyName")
			end)
			method("UpdateIsFriend", function()
				local info = u.unit ~= nil and W.npUnits[u.unit] or nil
				local isFriend = false
				if info then
					isFriend = info.friend == nil and false or info.friend
				end
				if u.isFriend == isFriend then
					return
				end
				u.isFriend = isFriend
				call("UpdateShowOnlyName")
			end)
			method("UpdateWidgetsOnlyMode", function()
				local info = u.unit ~= nil and W.npUnits[u.unit] or nil
				u.widgetsOnlyMode = u.unit ~= nil and ((info and info.widgetsOnly) or false)
			end)
			method("OnUnitFactionChanged", function() call("UpdateIsFriend") end)
			-- OnUnitSet, 131-173: the debuff padding callback keeps the function value UpdateAnchors has now.
			method("OnUnitSet", function()
				local list = W.npCallbacks.nameplateDebuffPadding or {}
				W.npCallbacks.nameplateDebuffPadding = list
				list[#list + 1] = { fn = o.forbidden and u.UpdateAnchors or uf.UpdateAnchors, owner = uf, frame = F }
				call("UpdateIsPlayer")
				call("UpdateIsFriend")
				call("UpdateWidgetsOnlyMode")
				call("UpdateShowOnlyName")
			end)
			method("OnUnitCleared", function()
				local list = W.npCallbacks.nameplateDebuffPadding or {}
				for i = #list, 1, -1 do
					if list[i].frame == F then
						table.remove(list, i)
					end
				end
				u.isPlayer, u.isFriend, u.widgetsOnlyMode, u.showOnlyName = nil, nil, nil, nil
			end)
			-- Blizzard's health update: TextStatusBar.lua:101-123 shows, hides and empties the strings and never sets their alpha.
			function F.healthText(mode)
				W.blizzard(function()
					left:SetText("")
					right:SetText("")
					left:Hide()
					right:Hide()
					if mode == "none" then
						text:SetText("")
						text:Hide()
					elseif mode == "numeric" then
						text:SetText("12.5K")
						text:Show()
					elseif mode == "both" then
						left:SetText("85%")
						left:Show()
						right:SetText("12.5K")
						right:Show()
						text:Hide()
						text:SetText("")
					end
				end)
			end
			-- CompactUnitFrame_UpdateHealthColor
			function F.recolour(c)
				W.blizzard(function()
					hbr.SetStatusBarColor(hb, c[1], c[2], c[3], c[4] or 1)
				end)
			end
			-- Parts that are missing, withheld or forbidden: o.remove and o.secret name fields of the unit frame, o.forbid names parts (hc, hb, cc, cast, level).
			for _, key in ipairs(o.remove or {}) do
				u[key] = nil
			end
			for _, key in ipairs(o.secret or {}) do
				u[key] = SECRET
			end
			for _, key in ipairs(o.forbid or {}) do
				F[key .. "r"].forbidden = true
			end
			W.npFrames[#W.npFrames + 1] = F
			W.seal()
			return F
		end

		function W.npPlate()
			plates = plates + 1
			return { number = plates }
		end

		-- NamePlateDriverMixin:OnNamePlateAdded, then the event the addon listens to. `late`: the unit frame comes after the event.
		function W.npAdd(plate, F, unit, info, o)
			o = o or {}
			info = info or {}
			W.npUnits[unit] = info
			F.unit, F.info, F.plate = unit, info, plate
			plate.F = F
			local function flow()
				W.blizzard(function()
					plate.UnitFrame = F.uf
					F.u.shown = true
					F.call("ApplyFrameOptions")
					F.u.unit = unit
					F.u.displayedUnit = unit
					F.recolour(info.colour or { 0.8, 0.2, 0.2, 1 })
					F.call("OnUnitSet")
					-- CompactUnitFrame_UpdatePlayerLevelDiff: the number shows for a level above 0, a skull for any other.
					F.lTextr.shown = (info.level or 60) > 0
				end)
			end
			W.units[unit] = plate
			local present = false
			for _, p in ipairs(W.plates) do
				present = present or p == plate
			end
			if not present then
				W.plates[#W.plates + 1] = plate
			end
			if o.late then
				W.fire("NAME_PLATE_UNIT_ADDED", unit)
				flow()
			else
				flow()
				if not o.quiet then
					W.fire("NAME_PLATE_UNIT_ADDED", unit)
				end
			end
			return F
		end

		-- A new unit frame and plate for one unit, added.
		function W.npShow(unit, info, o)
			local F = W.npFrame(o)
			local plate = W.npPlate()
			W.npAdd(plate, F, unit, info, o)
			return F
		end

		-- NamePlateDriverMixin:OnNamePlateRemoved: ClearUnit, then the unit frame goes back to its pool.
		function W.npRemove(F)
			local unit, plate = F.unit, F.plate
			W.blizzard(function()
				F.u.unit = nil
				F.u.displayedUnit = nil
				F.call("OnUnitCleared")
				F.u.shown, F.u.points, F.u.allPoints = false, {}, nil
				plate.UnitFrame = nil
			end)
			W.units[unit] = nil
			for i, p in ipairs(W.plates) do
				if p == plate then
					table.remove(W.plates, i)
					break
				end
			end
			W.fire("NAME_PLATE_UNIT_REMOVED", unit)
		end

		-- NamePlateDriverMixin:UpdateNamePlateOptions: the table is filled again and every plate applies it.
		function W.npOptions(style, size)
			W.npStyle, W.npSize = style or W.npStyle, size or W.npSize
			W.blizzard(function() env.NamePlateDriverFrame:UpdateNamePlateOptions() end)
		end
		env.NamePlateDriverFrame.UpdateNamePlateOptions = function()
			local fresh = NP.setupFor(W.npStyle, W.npSize)
			for key, value in pairs(fresh) do
				env.NamePlateSetupOptions[key] = value
			end
			for _, plate in ipairs(W.plates) do
				if plate.UnitFrame then
					plate.F.call("ApplyFrameOptions")
				end
			end
		end

		-- A CVar changes: the callbacks Blizzard registered run, the options are updated for the CVars that change them, then the event.
		function W.npCVar(name, value)
			W.npCVars[name] = value
			W.blizzard(function()
				if name == "nameplateDebuffPadding" then
					for _, cb in ipairs({ unpack(W.npCallbacks.nameplateDebuffPadding or {}) }) do
						cb.fn(cb.owner)
						if W.npOnLayout then
							W.npOnLayout(cb.frame)
						end
					end
				end
				if name == "nameplateStyle" or name == "nameplateSize" then
					W.npOptions(name == "nameplateStyle" and value or nil, name == "nameplateSize" and value or nil)
				end
				if name == "nameplateShowOnlyNameForFriendlyPlayerUnits" then
					for _, plate in ipairs(W.plates) do
						if plate.UnitFrame then
							plate.F.call("UpdateShowOnlyName")
						end
					end
				end
			end)
			W.fire("CVAR_UPDATE", name, tostring(value))
		end

		-- UNIT_FACTION: Blizzard's handler runs, then the addon's.
		function W.npFaction(F, friend)
			F.info.friend = friend
			W.blizzard(function() F.call("OnUnitFactionChanged") end)
			W.fire("UNIT_FACTION", F.unit)
		end

		-- Everything of Blizzard's that the additions can change, as one string.
		function W.npSnap(F)
			local parts = {}
			local function add(label, value) parts[#parts + 1] = label .. "=" .. value end
			local function str(label, r)
				add(label, ("%s/%s/a%s/%s/%s"):format(r.fontObject, g(r.textHeight), g(r.alpha), tostring(r.shown), tostring(r.text)))
			end
			str("name", F.namer)
			str("Text", F.textr)
			str("Left", F.leftr)
			str("Right", F.rightr)
			str("level", F.lTextr)
			local f = F.fillr
			add("fill", ("%s|%s|%s|a%s"):format(tostring(f.atlas), tostring(f.file), f.color and table.concat(f.color, ",") or "-", g(f.alpha)))
			add("colour", NP.colourText(F.hbr.barColor))
			add("heights", ("%s,%s,%s"):format(g(F.hcr.height), g(F.ccr.height), g(F.castr.height)))
			add("level", ("%s,%s,%d"):format(g(F.levelr.width), g(F.levelr.height), #F.levelr.points))
			add("points", ("%d,%d,%d,%d"):format(#F.hcr.points, #F.ccr.points, #F.hbr.points, #F.u.points))
			-- The offsets the level box part sets: the level frame's, the health container's right end and the aura frames'.
			local ends = {}
			for _, p in ipairs(F.hcr.points) do
				ends[#ends + 1] = p[1] .. g(p[4])
			end
			add("room", ("%s|%s|%s|%s"):format(F.levelr.points[1] and g(F.levelr.points[1][4]) or "-", table.concat(ends, ","), g(F.ccListr.points[1] and F.ccListr.points[1][4]), g(F.skullr.width)))
			return table.concat(parts, " ")
		end
		function W.npSnapAll()
			local list = {}
			for i, F in ipairs(W.npFrames) do
				list[i] = F.id .. ": " .. W.npSnap(F)
			end
			return table.concat(list, "\n")
		end
	end

	-- The three settings that are off in a fresh install and change every plate: a flat health bar, a flat cast bar, health text at 80%.
	-- Most of what is tested here is what they do, so a world has them on, as saved options, unless the setup says `defaults`.
	NP.FLAT = { ["nameplates.healthFlat"] = true, ["nameplates.castFlat"] = true, ["nameplates.healthTextSize"] = 80 }
	-- A world with the nameplate client. `setup`: style, size, castFill, noRestricted, without = { "C_Texture.GetAtlasExists" }, noLogin,
	-- defaults (the settings as a fresh install has them).
	-- castFill = true records the calls of ns.CastFill about the cast bar of a plate in W.castFills; castFill = false takes the function away.
	function NP.npWorld(opts, setup)
		setup = setup or {}
		if not setup.defaults then
			opts = opts or {}
			opts.saved = opts.saved or {}
			opts.saved.options = opts.saved.options or {}
			for path, value in pairs(NP.FLAT) do
				if opts.saved.options[path] == nil then
					opts.saved.options[path] = value
				end
			end
		end
		local W = newWorld(opts)
		NP.decorate(W, setup)
		if not setup.noLogin then
			W.login()
		end
		return W
	end

	-- A call, as text: SetTextHeight(21).
	function NP.callText(e)
		local a = {}
		for k = 1, e.n do
			local v = e[k]
			a[k] = rawequal(v, SECRET) and "secret" or (type(v) == "number" and g(v) or tostring(v))
		end
		return e.call .. "(" .. table.concat(a, ",") .. ")"
	end
	function NP.callsText(list)
		local out = {}
		for i, e in ipairs(list) do
			out[i] = NP.callText(e)
		end
		return table.concat(out, " ")
	end
	-- The addon's calls on the parts of one plate since a position in the log, or only on one part and one call.
	function NP.mine(W, F, from, part, call)
		local out = {}
		for i = (from or 0) + 1, #W.npLog do
			local e = W.npLog[i]
			if e.addon and e.label:sub(1, #F.id + 1) == F.id .. "." and (part == nil or e.label == F.id .. "." .. part) and (call == nil or e.call == call) then
				out[#out + 1] = e
			end
		end
		return out
	end

	-- Whether a frame of the world has an OnUpdate script: the poll of the cast bars is the only one a nameplate world has.
	function NP.polling(W)
		for _, frame in ipairs(W.eventFrames) do
			if frame.onUpdate and not frame.dividers then
				return true
			end
		end
		return false
	end

	-- The texture of the addon laid over the fill of the cast bar of a plate made with fillCast.
	function NP.coverOf(W, F)
		local fill = W.rawOf[F.cast].fill
		for _, t in ipairs(W.addonTextures) do
			if t.owner == F.cast and fill ~= nil and t.points[1] and t.points[1][2] == fill then
				return t
			end
		end
	end

	-- How many times a unit frame's UpdateAnchors has been hooked.
	function NP.hooksOn(W, F)
		local n = 0
		for _, h in ipairs(W.npHookLog) do
			if h.object == F.uf then
				n = n + 1
			end
		end
		return n
	end

	-- The class icon of a plate: the art the addon made on its unit frame, the frame holding it and the guide it is placed from.
	function NP.iconOf(W, F)
		local art
		for _, t in ipairs(W.addonTextures) do
			if t.layer == "ARTWORK" and t.owner and t.owner.parent == F.uf then
				art = t
			end
		end
		if not art then
			return nil
		end
		local guide
		for _, frame in ipairs(W.addonFrames) do
			if frame.parent == F.uf and #frame.points == 4 then
				guide = frame
			end
		end
		return { art = art, icon = art.owner, guide = guide, look = W.look(art.owner) }
	end

	-- NPCS --------------------------------------------------------------------------------------------

	-- 75a. The simulated unit frame does what Blizzard's XML and Lua do for it; the addon is off here, so these are Blizzard's own values.
	do
		local W = NP.npWorld({ saved = { options = { ["nameplates.enabled"] = false } } })
		local before, frames, textures, logAt = W.hooks, #W.addonFrames, #W.addonTextures, #W.npLog
		local n = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local O = W.env.NamePlateSetupOptions
		check("simulated plate: Thin style at the middle size gives Blizzard's numbers", near(O.healthBarHeight, 13) and near(O.healthBarFontHeight, 14) and near(O.castBarHeight, 6)
			and near(O.castIconHeight, 10) and O.spellNameInsideCastBar == false and near(O.levelFontHeight, 10) and O.unitNameAnchorStyle == 2 and O.useClassicHealthBar == false
			and O.useOutlinedFontWhenAboveHealthBar == true and near(O.playerLevelDiffHeight, 16) and near(O.playerLevelDiffWidth, 28))
		check("simulated plate: the name and the health text take the outlined font object at the font height", n.namer.fontObject == NP.OUTLINED and near(n.namer.textHeight, 14)
			and n.textr.fontObject == NP.OUTLINED and near(n.leftr.textHeight, 14) and near(n.rightr.textHeight, 14) and near(n.lTextr.textHeight, 10) and n.lTextr.fontObject == "SystemFont_NamePlateLevel")
		check("simulated plate: the bars have Blizzard's heights", near(n.hcr.height, 13) and near(n.ccr.height, 16) and near(n.castr.height, 6) and near(n.levelr.width, 28) and near(n.levelr.height, 16))
		check("simulated plate: the fill is the atlas and the unit is set", n.fillr.atlas == NP.BAR_ATLAS and n.u.unit == "nameplate1" and n.u.isPlayer == true and n.u.isFriend == false
			and n.u.showOnlyName == false and n.u.widgetsOnlyMode == false)
		check("simulated plate: a unit assignment lays the plate out twice, once with no unit and once from UpdateShowOnlyName", n.anchorPasses == 2, n.anchorPasses)
		check("simulated plate: the addon off makes no call, no frame and no hook", #NP.calls(W, nil, nil, true, logAt) == 0 and #W.addonFrames == frames and #W.addonTextures == textures and W.hooks == before and NP.hooksOn(W, n) == 0)
		W.npOptions(NP.STYLE.Modern, 3)
		W.flush()
		check("simulated plate: a new style fills the table and lays every plate out again", near(O.healthBarHeight, 25) and O.unitNameAnchorStyle == 1 and near(n.hcr.height, 25) and near(n.ccr.height, 20)
			and n.anchorPasses == 3, n.hcr.height .. " " .. n.ccr.height .. " " .. n.anchorPasses)
		clean(W, "simulated plate")
	end


	-- 75b. The nameplates page: the settings, their order and their words.
	do
		local W = NP.npWorld()
		local page, items = nil, {}
		-- The page and the sub-pages listed under it, in the order the window shows them.
		for _, p in ipairs(W.ns.PAGES) do
			if p.key == "nameplates" then
				page = p
			end
			if p.key == "nameplates" or p.owner == "nameplates" then
				for _, item in ipairs(p) do
					items[#items + 1] = item
				end
			end
		end
		local keys, sections, settings = {}, {}, 0
		for _, item in ipairs(items) do
			if item.section then
				sections[#sections + 1] = item.section
			else
				settings = settings + 1
				keys[#keys + 1] = item.key
			end
		end
		-- What the page has to offer: the rows of this file for the page and the sub-pages listed under it.
		local want = { sections = {}, keys = {} }
		for _, spec in ipairs(PAGES) do
			if spec.key == "nameplates" or spec.owner == "nameplates" then
				for _, row in ipairs(spec.rows) do
					if type(row) == "string" then want.sections[#want.sections + 1] = row else want.keys[#want.keys + 1] = row.path:match("^nameplates%.(.+)$") end
				end
			end
		end
		check("nameplates page: as many settings and section headers as the rows of this file", settings == #want.keys and #sections == #want.sections and settings > 0, settings .. " " .. #sections)
		check("nameplates page: the sections in order", table.concat(sections, ",") == table.concat(want.sections, ","), table.concat(sections, ","))
		check("nameplates page: the settings in order", table.concat(keys, ",") == table.concat(want.keys, ","),
			table.concat(keys, ","))
		check("nameplates page: the page switch is the first row", page[1].key == "enabled" and page[1].kind == "bool" and page[1].default == true)
		local bad1, bad2, bad3, bad4 = {}, {}, {}, {}
		local byKey = {}
		for _, item in ipairs(items) do
			if item.key then
				byKey[item.key] = item
			end
		end
		for _, item in ipairs(items) do
			if item.kind == "number" and not (type(item.min) == "number" and type(item.max) == "number" and type(item.step) == "number" and item.min < item.max and item.step > 0
				and item.default >= item.min and item.default <= item.max and (item.default - item.min) % item.step == 0) then
				bad1[#bad1 + 1] = item.key
			end
			if item.needs and not (byKey[item.needs] and (byKey[item.needs].kind == "bool" or (item.needsIn and byKey[item.needs].kind == "choice"))) then
				bad2[#bad2 + 1] = item.key
			end
			if item.key then
				for _, text in ipairs({ item.label or "", item.tip or "" }) do
					-- A tip may send the player to a page of the options by the name the page has.
					local lower = text:lower():gsub("the flat ui page", "")
					if lower:find("flat ui", 1, true) or lower:find("flatui", 1, true) or lower:find("addon", 1, true) then
						bad3[#bad3 + 1] = item.key
					end
				end
				-- Sentence case: after the first word, only a single capital letter (X, Y) or the game's own word for a kind of unit (Elite, Rare, Boss) may start with a capital.
				local label = item.label or ""
				if not label:find("^%u") then
					bad4[#bad4 + 1] = item.key
				end
				for word in label:sub(2):gmatch("%s(%S+)") do
					if word:find("^%u%l") and not ({ Elite = true, Rare = true, Boss = true })[word] then
						bad4[#bad4 + 1] = item.key .. ":" .. word
					end
				end
				if item.tip and (not item.tip:find("%.$") or (item.tip:find("%.%s+%u") and item.key ~= "kindBorder" and item.key ~= "colours")) then
					bad4[#bad4 + 1] = item.key .. " tip"
				end
			end
		end
		check("nameplates page: every number has a range, a step and a default on a step", #bad1 == 0, table.concat(bad1, " "))
		check("nameplates page: every needs names a bool on the page", #bad2 == 0, table.concat(bad2, " "))
		check("nameplates page: no label or tip names the addon", #bad3 == 0, table.concat(bad3, " "))
		check("nameplates page: labels are in sentence case and a tip is one sentence, two for the border colour of elite and rare and for reaction colours", #bad4 == 0, table.concat(bad4, " "))
		check("nameplates page: the class icon controls have no needs, only the page switch greys them", byKey.classEnemy.needs == nil and byKey.classFriendly.needs == nil
			and byKey.classPosition.needs == nil and byKey.classFit.needs == nil and byKey.classGap.needs == nil and byKey.classX.needs == nil and byKey.classY.needs == nil and byKey.classBorder.needs == nil)
		check("nameplates page: the text and bar settings that depend on another name it", byKey.healthTextSize.needs == "healthText" and byKey.healthTextOutline.needs == "healthText"
			and byKey.healthBackdrop.needs == "health" and byKey.dim.needs == "health" and byKey.target.needs == "health" and byKey.castBackdrop.needs == "cast"
			and byKey.healthFlat.needs == nil and byKey.healthHeight.needs == nil and byKey.nameSize.needs == nil and byKey.levelSize.needs == nil and byKey.castFlat.needs == nil and byKey.castHeight.needs == nil)
		check("nameplates page: the numbers, as the design gives them", byKey.healthHeight.min == 50 and byKey.healthHeight.max == 200 and byKey.healthHeight.step == 5 and byKey.healthHeight.default == 100
			and byKey.castHeight.min == 50 and byKey.castHeight.max == 200 and byKey.castHeight.step == 10 and byKey.castHeight.default == 100
			and byKey.nameSize.default == 100 and byKey.healthTextSize.default == 80 and byKey.levelSize.default == 100
			and byKey.classSize.min == 8 and byKey.classSize.max == 64 and byKey.classSize.default == 20
			and byKey.classX.min == -60 and byKey.classX.max == 60 and byKey.classX.default == 0 and byKey.classY.min == -60 and byKey.classY.max == 60 and byKey.classY.default == 0)
		check("nameplates page: the class icon position offers four places, left first", #byKey.classPosition.choices == 4 and byKey.classPosition.choices[1][1] == "left"
			and byKey.classPosition.choices[2][1] == "right" and byKey.classPosition.choices[3][1] == "above" and byKey.classPosition.choices[4][1] == "below" and byKey.classPosition.default == "left")
		check("nameplates page: the class icon size is the health bar height until Custom, and the custom size and the two gaps are numbers from 0 to 6", byKey.classFit.default == "bar" and byKey.classFit.choices[1][1] == "bar"
			and byKey.classFit.choices[1][2] == "Health bar height" and byKey.classFit.choices[2][1] == "own" and byKey.classSize.needs == "classFit" and byKey.classSize.needsIn[1] == "own"
			and byKey.classGap.min == 0 and byKey.classGap.max == 6 and byKey.classGap.step == 1 and byKey.classGap.default == 0
			and byKey.levelShape.default == "square" and byKey.levelShape.choices[1][1] == "square" and byKey.levelShape.choices[2][1] == "game" and byKey.levelShape.needs == "level"
			and byKey.levelGap.min == 0 and byKey.levelGap.max == 6 and byKey.levelGap.step == 1 and byKey.levelGap.default == 0 and byKey.levelGap.needs == "level"
			and #byKey.levelShape.needsIn == 2 and byKey.levelShape.needsIn[1] == "box" and byKey.levelShape.needsIn[2] == "text"
			and #byKey.levelGap.needsIn == 2 and byKey.levelGap.needsIn[1] == "box" and byKey.levelGap.needsIn[2] == "text")
		check("nameplates page: the defaults that change the look, as the design gives them", byKey.healthFlat.default == true and byKey.castFlat.default == true and byKey.classEnemy.default == true
			and byKey.classFriendly.default == false and byKey.nameOutline.default == true and byKey.healthText.default == true and byKey.healthTextOutline.default == true and byKey.classBorder.default == true)
		-- The page as the panel shows it: every control of it is named and described without the addon's name.
		local seen = 0
		for _, init in ipairs(W.controls) do
			local setting = init.data and init.data.setting
			if setting and setting:GetVariable():find("^FLATUI_NAMEPLATES_") then
				seen = seen + 1
				for _, text in ipairs({ setting:GetName(), init.data.tooltip or "" }) do
					local lower = text:lower():gsub("the flat ui page", "")
					if lower:find("flat ui", 1, true) or lower:find("addon", 1, true) then
						bad3[#bad3 + 1] = setting:GetVariable()
					end
				end
			end
		end
		check("nameplates page: the panel has a control for every setting and none names the addon", seen == settings and #bad3 == 0, seen .. " " .. table.concat(bad3, " "))
		clean(W, "nameplates page")
	end


	-- The same Blizzard script in a world where the nameplate page is off from the start: Blizzard's own look.
	function NP.twinOff(setup, extra)
		local saved = { options = { ["nameplates.enabled"] = false } }
		for k, v in pairs(extra or {}) do
			saved.options[k] = v
		end
		return NP.npWorld({ saved = saved }, setup)
	end
	-- An enemy mage, an NPC and a friendly priest, with health text and a bar colour.
	function NP.threePlates(W, o)
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, o)
		local b = W.npShow("nameplate2", { player = false, friend = false }, o)
		local c = W.npShow("nameplate3", { player = true, friend = true, class = "PRIEST", colour = { 0.1, 0.8, 0.1, 1 } }, o)
		a.healthText("both")
		b.healthText("numeric")
		c.healthText("none")
		W.flush()
		return { a, b, c }
	end
	function NP.colourOf(F)
		return NP.colourText(F.hbr.barColor)
	end
	function NP.fillText(F)
		local f = F.fillr
		return ("%s|%s|%s"):format(tostring(f.atlas), tostring(f.file), f.color and table.concat(f.color, ",") or "-")
	end
	function NP.stringsText(F)
		local out = {}
		for i, r in ipairs({ F.textr, F.leftr, F.rightr }) do
			out[i] = r.fontObject .. "/" .. g(r.textHeight)
		end
		return table.concat(out, " ")
	end

	-- 75c. Defaults on a fresh plate.
	do
		local R = NP.twinOff()
		local Rp = NP.threePlates(R)
		local W = NP.npWorld(nil, { castFill = true })
		local mark = #W.npLog
		local p = NP.threePlates(W)
		local a, b, c = p[1], p[2], p[3]
		check("fresh plate: the health fill is a white colour texture, not the atlas", NP.fillText(b) == "nil|nil|1,1,1,1" and NP.fillText(Rp[2]) == "UI-HUD-CoolDownManager-Bar|nil|-", NP.fillText(b))
		check("fresh plate: the bar colour is the one Blizzard gave it", NP.colourOf(b) == "0.8,0.2,0.2,1" and NP.colourOf(c) == "0.1,0.8,0.1,1" and NP.colourOf(b) == NP.colourOf(Rp[2]) and NP.colourOf(c) == NP.colourOf(Rp[3]))
		check("fresh plate: the three health text strings are 80 percent of the font height and keep Blizzard's font object", NP.stringsText(b) == NP.OUTLINED .. "/11.2 " .. NP.OUTLINED .. "/11.2 " .. NP.OUTLINED .. "/11.2"
			and NP.stringsText(Rp[2]) == NP.OUTLINED .. "/14 " .. NP.OUTLINED .. "/14 " .. NP.OUTLINED .. "/14", NP.stringsText(b))
		check("fresh plate: the name and the level text are untouched", #NP.mine(W, b, mark, "name") == 0 and #NP.mine(W, b, mark, "LevelText") == 0 and near(b.namer.textHeight, 14) and near(b.lTextr.textHeight, 10)
			and b.namer.fontObject == NP.OUTLINED and b.lTextr.fontObject == "SystemFont_NamePlateLevel")
		check("fresh plate: no height is set by the addon on any bar", #NP.calls(W, nil, "SetHeight", true) == 0 and near(b.hcr.height, 13) and near(b.ccr.height, 16) and near(b.castr.height, 6))
		check("fresh plate: an NPC has no class icon, an enemy player has", NP.iconOf(W, b) == nil and NP.iconOf(W, a) ~= nil and NP.iconOf(W, a).art.shown and NP.iconOf(W, a).art.atlas == "classicon-mage")
		check("fresh plate: a friendly player has none while the friendly switch is off", NP.iconOf(W, c) == nil)
		check("fresh plate: all three are counted and nothing is said about them", has(W.status(), "Nameplates: on, 3 styled") and W.line("Nameplates") == "Nameplates: on, 3 styled", W.status())
		check("fresh plate: the cast bar fill is asked for with the switch's value", #W.castFills > 0 and W.castFills[1].key == "nameplates" and W.castFills[1].flat == true and W.castFills[1].bar == a.cast)
		clean(W, "fresh plate")
		clean(R, "fresh plate, page off")
	end

	-- 75d. The follow: the driver is followed once, no unit frame is hooked, none while the page is off.
	do
		local W = NP.npWorld()
		local driver = W.env.NamePlateDriverFrame
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		check("hook: UpdateNamePlateOptions of the nameplate driver is followed once a plate is styled", NP.hooksOn(W, { uf = driver }) == 1)
		check("insthook: no unit frame has a hook of the addon's, UpdateAnchors included", NP.hooksOn(W, a) == 0 and not INSTHOOK.wrapped(W, a.uf, "UpdateAnchors") and INSTHOOK.wrapped(W, driver, "UpdateNamePlateOptions"))
		local only = true
		for _, h in ipairs(W.npHookLog) do
			if h.object == driver then
				only = only and h.name == "UpdateNamePlateOptions" and type(h.hook) == "function"
			end
		end
		check("hook: it is the only function followed on the driver, with hooksecurefunc on the driver itself", only)
		for i = 1, 4 do
			W.change("nameplates.nameSize", i % 2 == 0 and 100 or 150)
			W.change("nameplates.health", i % 2 == 0)
		end
		W.change("nameplates.health", true)
		W.change("nameplates.enabled", false)
		W.change("nameplates.enabled", true)
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 3)
		W.flush()
		check("hook: still one after the options changed, the page was switched off and on and Blizzard laid the plate out again", NP.hooksOn(W, { uf = driver }) == 1 and NP.hooksOn(W, a) == 0, NP.hooksOn(W, { uf = driver }))
		local plate = a.plate
		W.npRemove(a)
		W.flush()
		W.npAdd(plate, a, "nameplate7", { player = false, friend = false })
		W.flush()
		check("hook: still one when the pooled unit frame is given to another unit", NP.hooksOn(W, { uf = driver }) == 1 and NP.hooksOn(W, a) == 0, NP.hooksOn(W, { uf = driver }))
		local second = W.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		W.npShow("nameplate3", { player = false, friend = false })
		W.flush()
		check("hook: more unit frames add none, and no function of the mixin is followed", NP.hooksOn(W, { uf = driver }) == 1 and NP.hooksOn(W, second) == 0 and NP.hooksOn(W, a) == 0)
		local others = 0
		for _, h in ipairs(W.npHookLog) do
			if h.object ~= driver and (h.name == "UpdateAnchors" or h.name == "ApplyFrameOptions" or h.name == "OnUnitSet" or h.name == "UpdateHitTestArea") then
				others = others + 1
			end
		end
		check("hook: no unit frame function is followed", others == 0)
		clean(W, "hook")

		-- The page off at login: nothing is followed.
		local off = NP.twinOff()
		local o = off.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		off.change("nameplates.healthFlat", false)
		off.change("nameplates.healthFlat", true)
		off.npOptions()
		off.flush()
		check("hook: none while the page is off", NP.hooksOn(off, { uf = off.env.NamePlateDriverFrame }) == 0 and #NP.mine(off, o, 0) == 0)
		clean(off, "hook, page off")

		-- A forbidden unit frame is styled by nothing, and the follow, run with no plate styled, does not raise.
		local fw = NP.npWorld()
		local forbidden = fw.npShow("nameplate1", { player = true, friend = true, class = "MAGE" }, { forbidden = true })
		local normal = fw.npShow("nameplate2", { player = false, friend = false })
		fw.change("nameplates.classFriendly", true)
		fw.flush()
		check("hook: a forbidden unit frame is not read, the driver is followed once", NP.hooksOn(fw, { uf = fw.env.NamePlateDriverFrame }) == 1 and #fw.violations == 0, table.concat(fw.violations, "|"):sub(1, 200))
		local hook
		for _, h in ipairs(fw.npHookLog) do
			if h.object == fw.env.NamePlateDriverFrame then
				hook = h.hook
			end
		end
		local mark = #fw.npLog
		fw.npOptions()
		fw.flush()
		check("hook: the game laying the plates out again reads nothing of a forbidden unit frame", #fw.violations == 0 and #NP.mine(fw, forbidden, mark) == 0 and normal ~= nil, table.concat(fw.violations, "|"):sub(1, 200))
		check("hook: handed nothing, a withheld value, a number or a string it does not raise", pcall(hook) and pcall(hook, SECRET) and pcall(hook, 5) and pcall(hook, "x") and #fw.violations == 0)
		fw.flush()
		clean(fw, "hook, forbidden")

		-- One unit assignment: the game resets the name height, and the addon sets its own when the plate gets its unit.
		local tw = NP.npWorld()
		local t = tw.npShow("nameplate1", { player = false, friend = false })
		tw.change("nameplates.nameSize", 150)
		tw.flush()
		local plate2 = t.plate
		tw.npRemove(t)
		local from = #tw.npLog
		tw.npAdd(plate2, t, "nameplate5", { player = false, friend = false })
		local heights = {}
		for _, e in ipairs(NP.calls(tw, t.id .. ".name", "SetTextHeight", nil, from)) do
			heights[#heights + 1] = (e.addon and "addon " or "Blizzard ") .. g(e[1])
		end
		check("hook: ApplyFrameOptions resets the name height and the addon sets its own when the unit is set", heights[1] == "Blizzard 14" and heights[#heights] == "addon 21", table.concat(heights, ", "))
		check("hook: so the name is the addon's size when the event has run", near(t.namer.textHeight, 21), g(t.namer.textHeight))
		-- If the line height Blizzard reads back is the font's own, its last line leaves the name at the font's height, and the addon ends the name with the same line.
		tw.npLineUnscaled = true
		tw.npOptions()
		tw.npCVar("nameplateDebuffPadding", 4)
		tw.flush()
		check("hook: and when the line height is the font's own the name ends each pass where Blizzard's last line leaves it", near(t.namer.textHeight, 9), g(t.namer.textHeight))
		clean(tw, "hook, passes")
	end

	-- 75d2. insthook: with taintLog 2 the driver is left alone; plates are laid out when they get their unit and when a nameplate CVar changes.
	do
		local W = NP.npWorld()
		W.cvars.taintLog = "2"
		local driver = W.env.NamePlateDriverFrame
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		check("insthook: nameplates, taintLog 2: nothing is hooked on the driver or on a unit frame", NP.hooksOn(W, { uf = driver }) == 0 and NP.hooksOn(W, a) == 0 and not INSTHOOK.wrapped(W, driver, "UpdateNamePlateOptions"))
		check("insthook: nameplates, taintLog 2: the plate is styled when it gets its unit", NP.fillText(a) == "nil|nil|1,1,1,1" and near(a.textr.textHeight, 11.2))
		W.change("nameplates.nameSize", 150)
		check("insthook: nameplates, taintLog 2: a setting still changes the plate", near(a.namer.textHeight, 21), g(a.namer.textHeight))
		W.npCVar("nameplateDebuffPadding", 3)
		W.flush()
		check("insthook: nameplates, taintLog 2: a nameplate CVar lays the plate out again on the next frame", near(a.namer.textHeight, 21) and NP.fillText(a) == "nil|nil|1,1,1,1")
		check("insthook: nameplates, taintLog 2: the status counts the methods not followed", has(W.status(), "taintLog is on: ") and has(W.status(), " game methods not followed"), W.status())
		clean(W, "hook, taintLog")
	end


	-- The different calls in a list, in the order they first appear, as text.
	function NP.uniq(list)
		local seen, out = {}, {}
		for _, e in ipairs(list) do
			local t = NP.callText(e)
			if not seen[t] then
				seen[t] = true
				out[#out + 1] = t
			end
		end
		return table.concat(out, " ")
	end
	-- True when every SetFontObject of the addon is followed at once by a SetTextHeight on the same string: the font object sets the height.
	function NP.fontThenHeight(list)
		for i, e in ipairs(list) do
			if e.call == "SetFontObject" and not (list[i + 1] and list[i + 1].call == "SetTextHeight" and list[i + 1].label == e.label) then
				return false
			end
		end
		return true
	end
	function NP.stateOf(r)
		return r.fontObject .. "/" .. g(r.textHeight)
	end

	-- 75e. The level box: the border follows the level frame's sides and the health bar's top and bottom.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		local span = W.spanOf(a.level)
		local p = span and span.points
		check("level box: a frame of the addon's is anchored to the level frame's sides and the health bar's top and bottom",
			span and #p == 4 and p[1][1] == "LEFT" and p[1][2] == a.level and p[1][3] == "LEFT" and p[2][1] == "RIGHT" and p[2][2] == a.level and p[2][3] == "RIGHT"
			and p[3][1] == "TOP" and p[3][2] == a.hb and p[3][3] == "TOP" and p[4][1] == "BOTTOM" and p[4][2] == a.hb and p[4][3] == "BOTTOM"
			and p[1][4] == 0 and p[1][5] == 0 and p[2][4] == 0 and p[3][5] == 0 and p[4][5] == 0, span and #p)
		check("level box: it is a child of the level frame and has no texture of its own", span and span.parent == a.level and #span.regions == 0)
		local holder, backdrop = W.holderOn(a.level), W.backdropOn(a.level)
		check("level box: the border and the backdrop follow that frame, not the level frame", holder and holder.allPoints == span and backdrop and backdrop.allPoints == span and backdrop.owner == a.level
			and W.state(a.level) == "SB")
		local ok, detail = ringed(W, holder, 1)
		check("level box: four one pixel black edges on the border", ok, detail)
		local forbiddenCalls = {}
		for _, e in ipairs(NP.mine(W, a, 0, "PlayerLevelDiffFrame")) do
			if e.call ~= "SetAlpha" then
				forbiddenCalls[#forbiddenCalls + 1] = e.call
			end
		end
		local setOnly = {}
		for _, call in ipairs(forbiddenCalls) do
			if call ~= "SetSize" and call ~= "SetPoint" then
				setOnly[#setOnly + 1] = call
			end
		end
		check("level box: the addon sets only the size and one anchor of Blizzard's level frame, never its scale or visibility", #setOnly == 0, table.concat(forbiddenCalls, " "))
		check("level box: the level frame is a square the height of the health bar, flush with its right end", near(a.levelr.width, 13) and near(a.levelr.height, 13) and #a.levelr.points == 1
			and a.levelr.points[1][1] == "LEFT" and a.levelr.points[1][2] == a.hc and a.levelr.points[1][3] == "RIGHT" and a.levelr.points[1][4] == 0)
		local frames = #W.addonFrames
		for i = 1, 3 do
			W.change("nameplates.level", i % 2 == 0 and "Thin border" or "Text only")
		end
		W.change("nameplates.level", "Thin border")
		W.npOptions()
		W.flush()
		check("level box: the frame is made once however often the box is switched", #W.addonFrames == frames and W.spanOf(a.level) == span)
		-- A new style: a taller level frame and a taller bar. Nothing is called on the frame or the border.
		local calls0 = span.calls.SetPoint
		local mark = #W.npLog
		W.npOptions(NP.STYLE.Modern, 2)
		W.flush()
		check("level box: after Blizzard's style change, with a taller bar, the level frame is the new square and the border has the same anchors and no new call", near(a.levelr.height, 20) and near(a.levelr.width, 20) and near(a.hcr.height, 20)
			and span.calls.SetPoint == calls0 and span.calls.ClearAllPoints == nil and span.points[3][2] == a.hb and NP.uniq(NP.mine(W, a, mark, "PlayerLevelDiffFrame")):match("^SetSize%(20,20%) SetPoint%(LEFT,.*,RIGHT,0,0%)$") ~= nil, NP.uniq(NP.mine(W, a, mark, "PlayerLevelDiffFrame")))
		clean(W, "level box")

		-- The target takes its thickness and colour on both borders.
		W.units.target = a.plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.change("nameplates.targetThickness", 3)
		W.change("nameplates.targetColour", "ff00ff00")
		W.flush()
		local ok1, d1 = ringOf(W, a.hb, 3, 0, 1, 0)
		local ok2, d2 = ringOf(W, a.level, 3, 0, 1, 0)
		check("level box: on the target the level border and the health border take the target colour and thickness", ok1 and ok2, tostring(d1) .. " " .. tostring(d2))
		W.units.target = nil
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("level box: and give it up when the target changes", ringOf(W, a.hb, 1) and ringOf(W, a.level, 1))

		-- Off: the border is hidden and Blizzard's art shows.
		W.change("nameplates.level", "Default")
		check("level box: default hides the border and puts Blizzard's box art back", W.state(a.level) == "hb" and a.level.playerLevelDiffIcon.alpha == 1 and a.level.selectedBorder.alpha == 1)
		W.change("nameplates.level", "Thin border")
		check("level box: thin border again", W.state(a.level) == "SB" and a.level.playerLevelDiffIcon.alpha == 0 and W.spanOf(a.level) == span)
		W.change("nameplates.enabled", false)
		check("level box: the page switch off hides the border and gives the art back", W.state(a.level) == "hb" and a.level.playerLevelDiffIcon.alpha == 1 and a.level.selectedBorder.alpha == 1)
		clean(W, "level box off")
	end

	-- 75e1. The level box set to text only or to the default from the start: no border and no frame for it are made.
	do
		for _, style in ipairs({ "text", "default" }) do
			local W = NP.npWorld({ saved = { options = { ["nameplates.level"] = style } } })
			local a = W.npShow("nameplate1", { player = false, friend = false })
			W.flush()
			local made = 0
			for _, frame in ipairs(W.addonFrames) do
				made = made + ((frame.parent == a.level) and 1 or 0)
			end
			check("level " .. style .. " from the start: no border and no frame is made for the level box", W.spanOf(a.level) == nil and W.holderOn(a.level) == nil and made == 0 and W.state(a.level) == ".", made)
			W.npOptions()
			W.change("nameplates.healthFlat", false)
			check("level " .. style .. " from the start: and none is made by Blizzard's pass or another setting", W.holderOn(a.level) == nil and W.spanOf(a.level) == nil)
		end
	end

	-- 75e2. The level box when its health bar is missing or forbidden.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false }, { remove = { "HealthBarsContainer" } })
		local b = W.npShow("nameplate2", { player = false, friend = false }, { remove = { "HealthBarsContainer" } })
		W.flush()
		local holder = W.holderOn(a.level)
		check("level box, no health bar: the border follows the level frame itself", W.spanOf(a.level) == nil and holder and holder.allPoints == a.level and W.state(a.level) == "SB")
		check("level box, no health bar: one line in the status says so", count(W.status(), "Level box: its border could not follow the health bar and follows the default box.") == 1, W.status())
		check("level box, no health bar: no error", #W.errors == 0 and #W.violations == 0 and has(W.status(), "Nameplates: on, 2 styled"), W.status() .. table.concat(W.violations, "|"))
		clean(W, "level box, no health bar")

		local F = NP.npWorld()
		local c = F.npShow("nameplate1", { player = false, friend = false }, { forbid = { "hb" } })
		F.flush()
		check("level box, forbidden health bar: the border follows the level frame itself and says so once", F.spanOf(c.level) == nil and F.holderOn(c.level) and F.holderOn(c.level).allPoints == c.level
			and count(F.status(), "Level box: its border could not follow the health bar") == 1, F.status())
		check("level box, forbidden health bar: nothing of the forbidden bar is read", #F.violations == 0, table.concat(F.violations, " | "):sub(1, 300))
		check("level box, forbidden health bar: the plate is still counted as styled", has(F.status(), "Nameplates: on, 1 styled"), F.status())

		local S = NP.npWorld()
		local d = S.npShow("nameplate1", { player = false, friend = false }, { secret = { "HealthBarsContainer" } })
		S.flush()
		check("level box, withheld health container: nothing is indexed, the border follows the level frame", #S.violations == 0 and #S.errors == 0 and S.spanOf(d.level) == nil, table.concat(S.violations, " | "):sub(1, 300))
	end

	-- 75f. Name size and outline, health text size, outline and switch, level size.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		local mark = #W.npLog
		W.change("nameplates.nameSize", 150)
		check("name size 150: the name is set to 150 percent of the font height, then given Blizzard's last line, and nothing else is called on it", near(a.namer.textHeight, 21) and a.namer.fontObject == NP.OUTLINED
			and NP.uniq(NP.mine(W, a, mark, "name")) == "SetTextHeight(21) SetFontHeight(21)", NP.uniq(NP.mine(W, a, mark, "name")))
		local seen = {}
		W.npOnLayout = function(F) seen[#seen + 1] = NP.stateOf(F.namer) end
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 6)
		W.npOnLayout = nil
		check("name size 150: Blizzard's ApplyFrameOptions resets the height", table.concat(seen, ",") == NP.OUTLINED .. "/14," .. NP.OUTLINED .. "/14", table.concat(seen, ","))
		W.flush()
		check("name size 150: and the addon's is set again on the next frame", NP.stateOf(a.namer) == NP.OUTLINED .. "/21", NP.stateOf(a.namer))
		mark = #W.npLog
		W.change("nameplates.nameSize", 100)
		check("name size back to 100: the font height and then Blizzard's last line, once, and the font object is left alone", NP.callsText(NP.mine(W, a, mark, "name")) == "SetTextHeight(14) SetFontHeight(14)"
			and NP.stateOf(a.namer) == NP.OUTLINED .. "/14", NP.callsText(NP.mine(W, a, mark, "name")))
		mark = #W.npLog
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 7)
		W.change("nameplates.healthTextSize", 90)
		W.change("nameplates.health", false)
		W.change("nameplates.health", true)
		check("name size at 100: later passes make no call on the name", #NP.mine(W, a, mark, "name") == 0 and NP.stateOf(a.namer) == NP.OUTLINED .. "/14")
		clean(W, "name size")

		-- Every size and outline the name can have, reached from every other by its controls.
		local combos = {
			{ 100, true, NP.OUTLINED .. "/14" }, { 100, false, NP.PLAIN .. "/14" }, { 150, true, NP.OUTLINED .. "/21" }, { 150, false, NP.PLAIN .. "/21" },
		}
		local V = NP.npWorld()
		local b = V.npShow("nameplate1", { player = false, friend = false })
		local problems = {}
		for _, from in ipairs(combos) do
			for _, to in ipairs(combos) do
				V.change("nameplates.nameSize", from[1])
				V.change("nameplates.nameOutline", from[2])
				local at = #V.npLog
				V.change("nameplates.nameSize", to[1])
				V.change("nameplates.nameOutline", to[2])
				local list = NP.mine(V, b, at, "name")
				if NP.stateOf(b.namer) ~= to[3] or not NP.fontThenHeight(list) then
					problems[#problems + 1] = from[3] .. " to " .. to[3] .. ": " .. NP.stateOf(b.namer) .. " " .. NP.callsText(list)
				end
				-- And the same after Blizzard resets the name and lays it out again.
				V.npOptions()
				V.flush()
				if NP.stateOf(b.namer) ~= to[3] then
					problems[#problems + 1] = to[3] .. " after Blizzard's pass and the next frame: " .. NP.stateOf(b.namer)
				end
			end
		end
		check("name size and outline: all sixteen changes between the four states end in the right font object and height, each font object followed by the height", #problems == 0,
			table.concat(problems, "; "):sub(1, 400))
		clean(V, "name states")

		-- Outline off: the plain font object, then the height.
		local O = NP.npWorld()
		local c = O.npShow("nameplate1", { player = false, friend = false })
		local at = #O.npLog
		O.change("nameplates.nameOutline", false)
		check("name outline off: the plain font object and then the font height", NP.mine(O, c, at, "name")[1].call == "SetFontObject" and NP.mine(O, c, at, "name")[1][1] == NP.PLAIN and NP.mine(O, c, at, "name")[2].call == "SetTextHeight"
			and NP.stateOf(c.namer) == NP.PLAIN .. "/14", NP.callsText(NP.mine(O, c, at, "name")))
		at = #O.npLog
		O.change("nameplates.nameOutline", true)
		check("name outline on again at 100: Blizzard's font object and font height", NP.stateOf(c.namer) == NP.OUTLINED .. "/14" and NP.fontThenHeight(NP.mine(O, c, at, "name")))
		O.change("nameplates.nameSize", 150)
		O.change("nameplates.nameOutline", false)
		at = #O.npLog
		O.change("nameplates.nameOutline", true)
		check("name outline on again at 150: Blizzard's font object, then 150 percent of the font height", NP.stateOf(c.namer) == NP.OUTLINED .. "/21" and NP.fontThenHeight(NP.mine(O, c, at, "name")) and NP.mine(O, c, at, "name")[1][1] == NP.OUTLINED)
		clean(O, "name outline")
	end

	-- 75f2. Health text.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		a.healthText("both")
		W.flush()
		local mark = #W.npLog
		W.change("nameplates.healthTextSize", 150)
		check("health text size: the three strings are set together and the name is not touched", NP.stateOf(a.textr) == NP.OUTLINED .. "/21" and NP.stateOf(a.leftr) == NP.OUTLINED .. "/21" and NP.stateOf(a.rightr) == NP.OUTLINED .. "/21"
			and #NP.mine(W, a, mark, "name") == 0 and NP.stateOf(a.namer) == NP.OUTLINED .. "/14")
		W.change("nameplates.healthTextOutline", false)
		check("health text outline off: the plain font object on all three strings, at the same height, the name unchanged", NP.stateOf(a.textr) == NP.PLAIN .. "/21" and NP.stateOf(a.leftr) == NP.PLAIN .. "/21"
			and NP.stateOf(a.rightr) == NP.PLAIN .. "/21" and #NP.mine(W, a, mark, "name") == 0)
		W.change("nameplates.healthTextSize", 100)
		check("health text outline off at 100: the plain font object at the font height", NP.stateOf(a.textr) == NP.PLAIN .. "/14" and NP.stateOf(a.rightr) == NP.PLAIN .. "/14")
		W.change("nameplates.healthTextOutline", true)
		check("health text back to the outline at 100: Blizzard's own font object and height on all three", NP.stateOf(a.textr) == NP.OUTLINED .. "/14" and NP.stateOf(a.leftr) == NP.OUTLINED .. "/14" and NP.stateOf(a.rightr) == NP.OUTLINED .. "/14")
		W.npOptions()
		W.flush()
		check("health text at 100 with the outline: Blizzard's pass leaves it as it is", NP.stateOf(a.textr) == NP.OUTLINED .. "/14")
		clean(W, "health text size")

		-- Every size and outline of the health text, from every other.
		local combos = { { 80, true, NP.OUTLINED .. "/11.2" }, { 80, false, NP.PLAIN .. "/11.2" }, { 100, true, NP.OUTLINED .. "/14" }, { 100, false, NP.PLAIN .. "/14" }, { 150, false, NP.PLAIN .. "/21" }, { 200, true, NP.OUTLINED .. "/28" } }
		local V = NP.npWorld()
		local b = V.npShow("nameplate1", { player = false, friend = false })
		local problems = {}
		for _, from in ipairs(combos) do
			for _, to in ipairs(combos) do
				V.change("nameplates.healthTextSize", from[1])
				V.change("nameplates.healthTextOutline", from[2])
				local at = #V.npLog
				V.change("nameplates.healthTextSize", to[1])
				V.change("nameplates.healthTextOutline", to[2])
				local list = NP.mine(V, b, at)
				local want = to[3]
				for _, r in ipairs({ b.textr, b.leftr, b.rightr }) do
					if NP.stateOf(r) ~= want then
						problems[#problems + 1] = from[3] .. " to " .. to[3] .. ": " .. NP.stateOf(r)
					end
				end
				if not NP.fontThenHeight(list) then
					problems[#problems + 1] = "font object without a height after " .. from[3] .. " to " .. to[3]
				end
				V.npOptions()
				V.flush()
				if NP.stateOf(b.textr) ~= want or NP.stateOf(b.rightr) ~= want or NP.stateOf(b.leftr) ~= want then
					problems[#problems + 1] = to[3] .. " after Blizzard's pass"
				end
			end
		end
		check("health text size and outline: all thirty-six changes end in the right font object and height on all three strings", #problems == 0, table.concat(problems, "; "):sub(1, 400))
		clean(V, "health text states")

		-- The switch: alpha on the three strings, kept through Blizzard's own showing, hiding and emptying.
		local S = NP.npWorld()
		local s = S.npShow("nameplate1", { player = false, friend = false })
		s.healthText("both")
		S.change("nameplates.healthText", false)
		local function alphas() return g(s.textr.alpha) .. g(s.leftr.alpha) .. g(s.rightr.alpha) end
		check("health text off: the three strings are transparent, and the name is not", alphas() == "000" and s.namer.alpha == 1, alphas())
		s.healthText("numeric")
		s.healthText("both")
		s.healthText("none")
		s.healthText("both")
		S.npOptions()
		S.flush()
		check("health text off: it stays transparent through Blizzard showing, hiding, emptying and laying out the strings", alphas() == "000" and s.textr.shown == false and s.leftr.shown and s.leftr.text == "85%", alphas())
		S.change("nameplates.healthText", true)
		check("health text on again: opaque again", alphas() == "111")
		S.change("nameplates.healthText", false)
		S.change("nameplates.enabled", false)
		check("health text off then the page switch off: opaque", alphas() == "111")
		clean(S, "health text switch")
	end

	-- 75f3. Level text size.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		local mark = #W.npLog
		W.change("nameplates.levelSize", 120)
		check("level size 120: the level text is 120 percent of the level font height", near(a.lTextr.textHeight, 12) and a.lTextr.fontObject == "SystemFont_NamePlateLevel"
			and NP.uniq(NP.mine(W, a, mark, "LevelText")) == "SetTextHeight(12)", NP.uniq(NP.mine(W, a, mark, "LevelText")))
		W.npOptions()
		W.flush()
		check("level size 120: Blizzard's pass resets the level text and the addon sets it again", near(a.lTextr.textHeight, 12))
		W.change("nameplates.levelSize", 50)
		W.change("nameplates.levelSize", 200)
		W.change("nameplates.levelSize", 100)
		check("level size: 50, 200 and back to 100 end at the level font height", near(a.lTextr.textHeight, 10))
		local fonts = 0
		for _, e in ipairs(NP.mine(W, a, 0, "LevelText")) do
			if e.call == "SetFontObject" then
				fonts = fonts + 1
			end
		end
		check("level size: the font object of the level text is never set", fonts == 0 and a.lTextr.fontObject == "SystemFont_NamePlateLevel")
		mark = #W.npLog
		W.npOptions()
		W.flush()
		check("level size at 100: Blizzard's pass makes the addon call nothing on the level text", #NP.mine(W, a, mark, "LevelText") == 0)
		clean(W, "level size")
	end

	-- 75f4. Sizes the client does not give, and withheld ones: the group is left as Blizzard has it.
	do
		local variants = {
			{ "missing", nil }, { "withheld", SECRET }, { "zero", 0 }, { "a string", "14" }, { "negative", -3 }, { "a table", {} },
		}
		for _, v in ipairs(variants) do
			local W = NP.npWorld()
			local a = W.npShow("nameplate1", { player = false, friend = false })
			W.flush()
			W.env.NamePlateSetupOptions.healthBarFontHeight = v[2]
			W.env.NamePlateSetupOptions.levelFontHeight = v[2]
			local mark = #W.npLog
			W.change("nameplates.nameSize", 150)
			W.change("nameplates.nameOutline", false)
			W.change("nameplates.healthTextSize", 150)
			W.change("nameplates.healthTextOutline", false)
			W.change("nameplates.levelSize", 150)
			local got = {}
			for _, part in ipairs({ "name", "Text", "LeftText", "RightText", "LevelText" }) do
				for _, e in ipairs(NP.mine(W, a, mark, part)) do
					if e.call == "SetFontObject" or e.call == "SetTextHeight" then
						got[#got + 1] = part .. ":" .. NP.callText(e)
					end
				end
			end
			check("text with a font height that is " .. v[1] .. ": no font object and no height is set, and nothing raises", #got == 0 and #W.errors == 0 and #W.violations == 0 and not has(W.status(), "stopped"),
				table.concat(got, " ") .. table.concat(W.violations, "|"))
		end
		-- Options that are not there or are withheld as a whole.
		for _, v in ipairs({ { "missing", nil }, { "withheld", SECRET }, { "a string", "x" } }) do
			local W = NP.npWorld()
			local a = W.npShow("nameplate1", { player = false, friend = false })
			W.flush()
			W.env.NamePlateSetupOptions = v[2]
			local mark = #W.npLog
			W.change("nameplates.nameSize", 150)
			W.change("nameplates.healthHeight", 150)
			W.change("nameplates.castHeight", 200)
			W.change("nameplates.nameOutline", false)
			W.fire("CVAR_UPDATE", "nameplateDebuffPadding", "2")
			W.flush()
			check("text and heights with the options table " .. v[1] .. ": nothing is set on the name, the strings or the bars", #NP.mine(W, a, mark, "name") == 0 and #NP.mine(W, a, mark, "HealthBarsContainer") == 0
				and #NP.mine(W, a, mark, "CastBarsContainer") == 0 and #NP.mine(W, a, mark, "castBar") == 0 and #W.errors == 0 and #W.violations == 0 and not has(W.status(), "stopped"),
				NP.callsText(NP.mine(W, a, mark)) .. table.concat(W.violations, "|"))
		end
	end


	-- The addon's calls on the fill and the health bar since a position, as text.
	function NP.fillCalls(W, F, from)
		local out = {}
		for _, e in ipairs(NP.mine(W, F, from)) do
			if e.label == F.id .. ".healthBar" or e.label == F.id .. ".barTexture" then
				out[#out + 1] = e
			end
		end
		return out
	end

	-- 75g. The flat health bar.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 0.9 } })
		W.flush()
		local plate = a.plate
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 0.9 } })
		W.flush()
		local mark = #W.npLog
		local seen = {}
		W.npOnLayout = function(F) seen[#seen + 1] = NP.fillText(F) .. " " .. NP.colourOf(F) end
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 5)
		W.npOnLayout = nil
		check("flat health bar: Blizzard sets the atlas again in each of its passes, and the addon has called nothing yet", table.concat(seen, ",") == NP.BAR_ATLAS .. "|nil|- 0.2,0.4,0.6,0.9," .. NP.BAR_ATLAS .. "|nil|- 0.2,0.4,0.6,0.9"
			and #NP.fillCalls(W, a, mark) == 0, table.concat(seen, ","))
		W.flush()
		check("flat health bar: the colour read first goes back to the bar after the colour texture, the four values unchanged and in order, in one pass on the next frame",
			NP.callsText(NP.fillCalls(W, a, mark)) == "GetStatusBarColor() SetColorTexture(1,1,1,1) SetStatusBarColor(0.2,0.4,0.6,0.9)",
			NP.callsText(NP.fillCalls(W, a, mark)))
		check("flat health bar: after Blizzard sets the atlas again, the fill is flat again on the next frame and the bar has Blizzard's colour",
			NP.fillText(a) == "nil|nil|1,1,1,1" and NP.colourOf(a) == "0.2,0.4,0.6,0.9", NP.fillText(a))
		-- A new colour from Blizzard goes on the flat fill.
		a.recolour({ 0.9, 0.1, 0.1, 1 })
		check("flat health bar: a colour Blizzard gives later is the bar's, on the flat fill", NP.colourOf(a) == "0.9,0.1,0.1,1" and NP.fillText(a) == "nil|nil|1,1,1,1")
		clean(W, "flat health bar")

		-- Withheld colour values go from the getter to the setter and are never looked at.
		for _, variant in ipairs({
			{ "all four withheld", { SECRET, SECRET, SECRET, SECRET } },
			{ "the first withheld", { SECRET, 0.4, 0.6, 0.9 } },
			{ "the third withheld", { 0.2, 0.4, SECRET, 1 } },
			{ "only the alpha withheld", { 0.2, 0.4, 0.6, SECRET } },
		}) do
			local V = NP.npWorld()
			local plates = {}
			for i = 1, 4 do
				plates[i] = V.npShow("nameplate" .. i, { player = false, friend = false })
				plates[i].hbr.barColor = { unpack(variant[2]) }
			end
			local at = #V.npLog
			V.npOptions()
			V.change("nameplates.healthFlat", false)
			V.change("nameplates.healthFlat", true)
			V.flush()
			local all = true
			for _, F in ipairs(plates) do
				local c = F.hbr.barColor
				for k = 1, 4 do
					all = all and rawequal(c[k], variant[2][k])
				end
				local sets = NP.mine(V, F, at, "healthBar", "SetStatusBarColor")
				for _, e in ipairs(sets) do
					for k = 1, 4 do
						all = all and rawequal(e[k], variant[2][k])
					end
				end
				all = all and #sets > 0 and NP.fillText(F) == "nil|nil|1,1,1,1"
			end
			check("flat health bar with " .. variant[1] .. ": the same values reach SetStatusBarColor, the fill is flat, and no plate fails", all and not has(V.status(), "stopped") and #V.errors == 0 and #V.violations == 0,
				V.status() .. table.concat(V.violations, "|"))
		end

		-- Flat off: Blizzard's own line.
		local F = NP.npWorld()
		local b = F.npShow("nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 0.9 } })
		mark = #F.npLog
		F.change("nameplates.healthFlat", false)
		local sets = NP.mine(F, b, mark, "barTexture", "SetAtlas")
		check("flat health bar off: the atlas comes back with SetAtlas(name, true), once", #sets == 1 and sets[1][1] == NP.BAR_ATLAS and sets[1][2] == true and #NP.mine(F, b, mark, "barTexture", "SetTexture") == 0
			and NP.fillText(b) == NP.BAR_ATLAS .. "|nil|-", NP.callsText(NP.mine(F, b, mark, "barTexture")))
		check("flat health bar off: and the bar colour is Blizzard's", NP.colourOf(b) == "0.2,0.4,0.6,0.9")
		mark = #F.npLog
		F.npOptions()
		F.flush()
		check("flat health bar off: Blizzard's pass makes the addon call nothing on the fill", #NP.fillCalls(F, b, mark) == 0)
		F.change("nameplates.healthFlat", true)
		check("flat health bar on again", NP.fillText(b) == "nil|nil|1,1,1,1" and NP.colourOf(b) == "0.2,0.4,0.6,0.9")
		-- The switch off seen only by the hook: Blizzard has just set its own fill, so nothing is called.
		F.options()["nameplates.healthFlat"] = false
		mark = #F.npLog
		F.npOptions()
		F.flush()
		check("flat health bar off seen in the hook: the addon calls nothing on the fill and the fill is Blizzard's", #NP.fillCalls(F, b, mark) == 0 and NP.fillText(b) == NP.BAR_ATLAS .. "|nil|-")
		F.options()["nameplates.healthFlat"] = true
		F.npOptions()
		F.flush()
		check("flat health bar on again after that", NP.fillText(b) == "nil|nil|1,1,1,1")
		clean(F, "flat health bar off")

		-- The Classic style puts a file on the fill, and the switch gives that file back.
		local C = NP.npWorld(nil, { style = NP.STYLE.Classic })
		local c = C.npShow("nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 0.9 } })
		check("flat health bar in the Classic style: flat as well", NP.fillText(c) == "nil|nil|1,1,1,1")
		mark = #C.npLog
		C.change("nameplates.healthFlat", false)
		local files = NP.mine(C, c, mark, "barTexture", "SetTexture")
		check("flat health bar off in the Classic style: SetTexture of the BarFill file, no atlas", #files == 1 and files[1][1] == NP.CLASSIC_FILL and #NP.mine(C, c, mark, "barTexture", "SetAtlas") == 0
			and NP.fillText(c) == "nil|" .. NP.CLASSIC_FILL .. "|-", NP.callsText(NP.mine(C, c, mark, "barTexture")))
		C.change("nameplates.healthFlat", true)
		C.npOptions(NP.STYLE.Thin)
		C.change("nameplates.healthFlat", false)
		check("flat health bar off after the style went back to Thin: the atlas again", NP.fillText(c) == NP.BAR_ATLAS .. "|nil|-")
		clean(C, "flat health bar, classic")

		-- The file or the atlas that comes back is chosen by the health bar's flag alone.
		for _, case in ipairs({ { "useClassicHealthBar", "nil|" .. NP.CLASSIC_FILL .. "|-" }, { "useClassicCastBar", NP.BAR_ATLAS .. "|nil|-" } }) do
			local V = NP.npWorld()
			local v = V.npShow("nameplate1", { player = false, friend = false })
			V.env.NamePlateSetupOptions[case[1]] = true
			V.change("nameplates.healthFlat", false)
			check("flat health bar off with only " .. case[1] .. " set: the fill is " .. case[2], NP.fillText(v) == case[2], NP.fillText(v))
		end

		-- A fill that is missing or withheld: nothing is called.
		for _, variant in ipairs({ { "missing", nil }, { "withheld", SECRET } }) do
			local V = NP.npWorld()
			local d = V.npShow("nameplate1", { player = false, friend = false })
			d.hbr.barTexture = variant[2]
			local at = #V.npLog
			V.npOptions()
			V.change("nameplates.healthFlat", false)
			V.change("nameplates.healthFlat", true)
			check("flat health bar with a fill that is " .. variant[1] .. ": no call on the bar or the fill and no error", #NP.fillCalls(V, d, at) == 0 and not has(V.status(), "stopped") and #V.errors == 0 and #V.violations == 0,
				NP.callsText(NP.fillCalls(V, d, at)))
		end

		-- A bar whose colour is reset by the colour texture still ends with Blizzard's colour.
		local R = NP.npWorld()
		R.npResets = { SetColorTexture = true }
		local r = R.npShow("nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 0.9 } })
		R.npOptions()
		R.flush()
		check("flat health bar when the colour texture resets the bar colour: Blizzard's colour is put back after it", NP.colourOf(r) == "0.2,0.4,0.6,0.9" and NP.fillText(r) == "nil|nil|1,1,1,1", NP.colourOf(r))
		R.change("nameplates.healthFlat", false)
		R.change("nameplates.healthFlat", true)
		check("flat health bar when the colour texture resets the bar colour: and after the switch off and on", NP.colourOf(r) == "0.2,0.4,0.6,0.9")
		clean(R, "flat health bar, colour reset")
	end

	-- 75e2. squared: the level box is a square the height of the health bar, flush with it, and the class icon starts at the same height.
	do
		local T = { gaps = { 0, 3 }, bad = {}, styles = { Thin = NP.STYLE.Thin, Modern = NP.STYLE.Modern } }
		T.cases = { { "Thin", 100, 13 }, { "Thin", 150, 19.5 }, { "Modern", 100, 20 }, { "Modern", 150, 30 } }
		function T.world(set, saved, setup)
			local W = NP.npWorld(saved and { saved = { options = saved } } or nil, setup)
			W.npAllow = true
			for _, row in ipairs(set or {}) do
				W.change(row[1], row[2])
			end
			local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			W.flush()
			return W, a
		end
		function T.pt(raw, point)
			for _, p in ipairs(raw.points) do
				if p[1] == point then
					return p
				end
			end
			return { false, false, false, 1e9, 1e9 }
		end
		-- Where the right end of the box is, when the right end of the cast container is 0.
		function T.right(a)
			local hp, lp = T.pt(a.hcr, "BOTTOMRIGHT"), T.pt(a.levelr, "LEFT")
			return hp[4] + lp[4] + a.levelr.width
		end
		function T.note(key, text)
			T.bad[key] = (T.bad[key] or "") .. text .. " "
		end
		for _, c in ipairs(T.cases) do
			for _, gap in ipairs(T.gaps) do
				local W, a = T.world({ { "nameplates.healthHeight", c[2] }, { "nameplates.levelGap", gap } })
				W.npOptions(T.styles[c[1]], 2)
				W.flush()
				local h, tag = c[3], c[1] .. c[2] .. "/" .. gap
				local lp, hp = T.pt(a.levelr, "LEFT"), T.pt(a.hcr, "BOTTOMRIGHT")
				local spacing = W.env.NamePlateSetupOptions.castBarToHealthBarSpacing
				if not (near(a.levelr.width, h) and near(a.levelr.height, h)) then
					T.note("size", tag .. ":" .. g(a.levelr.width) .. "x" .. g(a.levelr.height))
				end
				if not (#a.levelr.points == 1 and lp[1] == "LEFT" and lp[2] == a.hc and lp[3] == "RIGHT" and lp[4] == gap and lp[5] == 0) then
					T.note("anchor", tag)
				end
				if not (hp[2] == a.cc and hp[3] == "TOPRIGHT" and near(hp[4], -(h + gap)) and hp[5] == spacing) then
					T.note("health", tag .. ":" .. g(hp[4]))
				end
				for _, list in ipairs({ a.ccListr, a.lossListr }) do
					local ap = list.points[1]
					if not (ap and ap[2] == a.hc and ap[3] == "RIGHT" and near(ap[4], 5 + h + gap)) then
						T.note("aura", tag)
					end
				end
				if not (near(a.skullr.width, h) and near(a.skullr.height, h)) then
					T.note("skull", tag)
				end
				if not near(T.right(a), 0) then
					T.note("edge", tag .. ":" .. g(T.right(a)))
				end
				-- A plate the game laid out with no room kept for the box: the next pass of the addon puts the room back.
				a.noRoom = true
				W.npOptions(T.styles[c[1]], 2)
				W.flush()
				if not near(T.right(a), 0) or not near(T.pt(a.hcr, "BOTTOMRIGHT")[4], -(h + gap)) then
					T.note("noroom", tag)
				end
			end
		end
		T.text = {
			size = "the level frame is (h, h) at Thin and Modern, and at bar height 100 and 150",
			anchor = "the level frame hangs LEFT from the right end of the health container at the gap",
			health = "the health container ends h plus the gap before the cast container, at the spacing the game gives",
			aura = "the two aura frames hang at 5 plus h plus the gap",
			skull = "the skull texture is (h, h)",
			edge = "the right end of the box is the right end of the guide",
			noroom = "the right end of the box is the right end of the guide on a plate laid out with no room",
		}
		for _, key in ipairs({ "size", "anchor", "health", "aura", "skull", "edge", "noroom" }) do
			check("squared: " .. T.text[key], T.bad[key] == nil, T.bad[key])
		end

		-- The icon on the right adds its room to the aura frames.
		do
			local W, a = T.world({ { "nameplates.classPosition", "Right" }, { "nameplates.classGap", 2 }, { "nameplates.levelGap", 3 } })
			check("squared: with the class icon on the right the aura frames also clear the icon and its gap", near(a.ccListr.points[1][4], 5 + 13 + 3 + 13 + 2) and near(a.lossListr.points[1][4], 5 + 13 + 3 + 13 + 2),
				g(a.ccListr.points[1][4]))
			W.change("nameplates.classPosition", "Left")
			check("squared: and not with the icon on the left", near(a.ccListr.points[1][4], 5 + 13 + 3))
			check("squared: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"))
		end

		-- Game width, Default, the Classic style, a hidden level frame and the page off: nothing is called.
		do
			local none = {}
			for _, row in ipairs({
				{ "game width", { ["nameplates.levelShape"] = "game" } },
				{ "Default", { ["nameplates.level"] = "default" } },
				{ "the page off", { ["nameplates.enabled"] = false } },
				{ "the Classic style", nil, { style = NP.STYLE.Classic } },
			}) do
				local W, a = T.world(nil, row[2], row[3])
				local n = #NP.mine(W, a, 0, "PlayerLevelDiffFrame") + #NP.mine(W, a, 0, "HealthBarsContainer", "SetPoint") + #NP.mine(W, a, 0, "HealthBarsContainer", "SetSize")
					+ #NP.mine(W, a, 0, "CrowdControlListFrame") + #NP.mine(W, a, 0, "LossOfControlFrame") + #NP.mine(W, a, 0, "highLevelTexture")
				if n ~= 0 then
					none[#none + 1] = row[1] .. "=" .. n
				end
			end
			check("squared: Game width, Default, the page off and the Classic style make no call on the level frame, the health container, the aura frames or the skull", #none == 0, table.concat(none, " "))
			local W, a = T.world({ { "nameplates.levelShape", "Game width" } })
			a.levelr.shown = false
			local mark = #W.npLog
			W.change("nameplates.levelShape", "Square")
			W.flush()
			check("squared: a hidden level frame is left alone", #NP.mine(W, a, mark, "PlayerLevelDiffFrame") == 0 and #NP.mine(W, a, mark, "HealthBarsContainer", "SetPoint") == 0)
			a.levelr.shown = true
			W.change("nameplates.levelGap", 1)
			W.flush()
			check("squared: and set when it is shown", near(a.levelr.width, 13) and T.pt(a.levelr, "LEFT")[4] == 1)
			a.levelr.shown = false
			W.change("nameplates.levelGap", 2)
			W.flush()
			check("squared: shown no longer, the game's size and the full width of the bar come back", near(a.levelr.width, W.env.NamePlateSetupOptions.playerLevelDiffWidth) and near(T.pt(a.hcr, "BOTTOMRIGHT")[4], 0)
				and near(a.ccListr.points[1][4], 5), g(T.pt(a.hcr, "BOTTOMRIGHT")[4]))
		end

		-- The aura frames are protected too: a pass that may not set them sets nothing.
		do
			local W = NP.npWorld()
			W.npAllow = function(r) return not tostring(r.label):find("CrowdControlListFrame", 1, true) end
			local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			W.flush()
			check("squared: when the aura frames may not be set, nothing of the box is set and the status says so", #NP.mine(W, a, 0, "PlayerLevelDiffFrame") == 0
				and #NP.mine(W, a, 0, "HealthBarsContainer", "SetPoint") == 0 and has(W.status(), "Level box: the game does not allow this on nameplates."), W.status())
		end

		-- A client that keeps the box width of the game: one line in the status.
		do
			local W, a = T.world({ { "nameplates.levelGap", 1 } })
			check("squared: a box that takes the size has no line in the status", not has(W.status(), "Level box"), W.status())
			local V, b = T.world({ { "nameplates.levelShape", "Game width" } })
			V.refuse[b.level] = true
			V.change("nameplates.levelShape", "Square")
			V.flush()
			check("squared: a box that keeps the game's width is told in one line of the status", count(V.status(), "Level box: the game keeps its own box width.") == 1, V.status())
			local o = V.env.NamePlateSetupOptions
			check("squared: and the game's layout is back, the health end, the box offset and the aura frames", near(T.pt(b.hcr, "BOTTOMRIGHT")[4], -(o.playerLevelDiffWidth + 5)) and T.pt(b.level, "LEFT")[4] == 5
				and near(b.ccListr.points[1][4], 5 + o.playerLevelDiffWidth + 5) and near(b.lossListr.points[1][4], 5 + o.playerLevelDiffWidth + 5), tostring(T.pt(b.hcr, "BOTTOMRIGHT")[4]))
			local mark = #V.npLog
			V.change("nameplates.levelGap", 2)
			V.flush()
			check("squared: and a later pass leaves the game's layout alone", #NP.mine(V, b, mark, "HealthBarsContainer", "SetPoint") == 0 and #NP.mine(V, b, mark, "PlayerLevelDiffFrame") == 0)
			V.refuse[b.level] = nil
			V.change("nameplates.levelShape", "Game width")
			V.flush()
			V.change("nameplates.levelShape", "Square")
			V.flush()
			check("squared: a box that takes the size later clears the line", not has(V.status(), "Level box:"), V.status())
		end

		-- Turned off, the game's values come back.
		do
			local bad = {}
			for _, how in ipairs({ { "Game width", "nameplates.levelShape" }, { "Default", "nameplates.level" }, { false, "nameplates.enabled" } }) do
				local W, a = T.world({ { "nameplates.levelGap", 3 } })
				local o = W.env.NamePlateSetupOptions
				W.change(how[2], how[1])
				W.flush()
				local lp, hp = T.pt(a.levelr, "LEFT"), T.pt(a.hcr, "BOTTOMRIGHT")
				local width = o.playerLevelDiffWidth
				if not (near(a.levelr.width, width) and near(a.levelr.height, o.playerLevelDiffHeight) and lp[4] == 5 and near(hp[4], -(width + 5))
					and near(a.ccListr.points[1][4], 5 + width + 5) and near(a.lossListr.points[1][4], 5 + width + 5) and near(a.skullr.width, o.playerLevelDiffHeight)) then
					bad[#bad + 1] = tostring(how[2]) .. ":" .. g(a.levelr.width) .. "," .. tostring(lp[4]) .. "," .. g(hp[4]) .. "," .. g(a.ccListr.points[1][4])
				end
			end
			check("squared: turned off, the level frame has the game's size and offset 5, the health container its end, the aura frames their offset", #bad == 0, table.concat(bad, " | "))
		end

		-- In combat nothing is set on the protected frames, and everything is set when combat ends.
		do
			local W = NP.npWorld()
			W.combat = true
			local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			W.flush()
			local o = W.env.NamePlateSetupOptions
			check("squared: in combat the level frame, the health container and the aura frames are not set, and the status says so", #NP.mine(W, a, 0, "PlayerLevelDiffFrame") == 0
				and #NP.mine(W, a, 0, "HealthBarsContainer", "SetPoint") == 0 and #NP.mine(W, a, 0, "CrowdControlListFrame") == 0 and near(a.levelr.width, o.playerLevelDiffWidth)
				and has(W.status(), "Level box: nameplates that appear in combat get it when combat ends."), W.status())
			W.combat = false
			W.fire("PLAYER_REGEN_ENABLED")
			W.flush()
			check("squared: after combat the box is the square and the health container ends before it", near(a.levelr.width, 13) and near(T.right(a), 0) and #W.violations == 0, g(a.levelr.width))
		end
	end

	-- 75h. Bar heights.
	do
		local W = NP.npWorld()
		W.npAllow = true
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		-- The unit frame is hooked now; a new unit makes Blizzard register its callbacks with the function the hook replaced.
		local plate = a.plate
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate1", { player = false, friend = false })
		W.flush()
		local mark = #W.npLog
		W.change("nameplates.healthHeight", 150)
		check("health bar height 150: the health container is 150 percent of Blizzard's height and nothing else is resized", near(a.hcr.height, 19.5) and near(a.ccr.height, 16) and near(a.castr.height, 6)
			and NP.uniq(NP.mine(W, a, mark, "HealthBarsContainer", "SetHeight")) == "SetHeight(19.5)" and #NP.mine(W, a, mark, "CastBarsContainer", "SetHeight") == 0 and #NP.mine(W, a, mark, "castBar", "SetHeight") == 0,
			g(a.hcr.height))
		local seen = {}
		W.npOnLayout = function(F) seen[#seen + 1] = g(F.hcr.height) end
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 6)
		W.npOptions(NP.STYLE.Modern, 2)
		W.npOnLayout = nil
		check("health bar height 150: each of Blizzard's passes returns with Blizzard's own height (13, 13, 20)", table.concat(seen, ",") == "13,13,20", table.concat(seen, ","))
		W.flush()
		check("health bar height 150: and the bar is 150 percent of Blizzard's height again on the next frame", near(a.hcr.height, 30), g(a.hcr.height))
		W.npOptions(NP.STYLE.Thin, 2)
		mark = #W.npLog
		W.change("nameplates.healthHeight", 100)
		check("health bar height back to 100: Blizzard's height is set once", NP.callsText(NP.mine(W, a, mark, "HealthBarsContainer", "SetHeight")) == "SetHeight(13)" and near(a.hcr.height, 13), NP.callsText(NP.mine(W, a, mark, "HealthBarsContainer")))
		mark = #W.npLog
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 7)
		W.change("nameplates.nameSize", 120)
		check("health bar height at 100: later passes set nothing", #NP.mine(W, a, mark, "HealthBarsContainer", "SetHeight") == 0 and near(a.hcr.height, 13))
		clean(W, "health bar height")

		-- Cast bar: the container is the bar and the icon below it, unless the spell name is inside the bar.
		local C = NP.npWorld()
		C.npAllow = true
		local c = C.npShow("nameplate1", { player = false, friend = false })
		mark = #C.npLog
		C.change("nameplates.castHeight", 200)
		check("cast bar height 200 with the spell name below the bar: the container is twice the bar plus the icon, the bar twice Blizzard's", near(c.ccr.height, 22) and near(c.castr.height, 12) and near(c.hcr.height, 13), g(c.ccr.height) .. " " .. g(c.castr.height))
		seen = {}
		C.npOnLayout = function(F) seen[#seen + 1] = g(F.ccr.height) .. "/" .. g(F.castr.height) end
		C.npOptions()
		C.npCVar("nameplateDebuffPadding", 3)
		C.npOnLayout = nil
		check("cast bar height 200: each of Blizzard's passes returns with Blizzard's heights", table.concat(seen, ",") == "16/6,16/6", table.concat(seen, ","))
		C.flush()
		check("cast bar height 200: and the heights are the addon's again on the next frame", near(c.ccr.height, 22) and near(c.castr.height, 12), g(c.ccr.height) .. "/" .. g(c.castr.height))
		mark = #C.npLog
		C.change("nameplates.castHeight", 100)
		check("cast bar height back to 100: Blizzard's two heights are set once", NP.callsText(NP.mine(C, c, mark, "CastBarsContainer")) == "SetHeight(16)" and NP.callsText(NP.mine(C, c, mark, "castBar")) == "SetHeight(6)"
			and near(c.ccr.height, 16) and near(c.castr.height, 6), NP.callsText(NP.mine(C, c, mark)))
		mark = #C.npLog
		C.npOptions()
		C.change("nameplates.healthHeight", 120)
		check("cast bar height at 100: later passes set no cast bar height", #NP.mine(C, c, mark, "CastBarsContainer") == 0 and #NP.mine(C, c, mark, "castBar") == 0)
		C.change("nameplates.healthHeight", 100)
		-- And with the spell name inside the bar (the CastFocus style): container and bar are the same.
		local I = NP.npWorld(nil, { style = NP.STYLE.CastFocus })
		I.npAllow = true
		local i = I.npShow("nameplate1", { player = false, friend = false })
		check("cast bar height at the start in a style with the spell name inside: Blizzard's container and bar are one height", near(i.ccr.height, 16) and near(i.castr.height, 16))
		I.change("nameplates.castHeight", 200)
		check("cast bar height 200 with the spell name inside the bar: container and bar both twice Blizzard's bar height", near(i.ccr.height, 32) and near(i.castr.height, 32), g(i.ccr.height) .. " " .. g(i.castr.height))
		I.change("nameplates.castHeight", 50)
		check("cast bar height 50 with the spell name inside the bar: half", near(i.ccr.height, 8) and near(i.castr.height, 8))
		I.change("nameplates.castHeight", 190)
		check("cast bar height 190 with the spell name inside the bar", near(i.ccr.height, 30.4) and near(i.castr.height, 30.4))
		clean(C, "cast bar height")
		clean(I, "cast bar height, name inside")

		-- The Classic style: both bars are treated as 100, before and after the style changes.
		local K = NP.npWorld(nil, { style = NP.STYLE.Classic })
		K.npAllow = true
		K.change("nameplates.healthHeight", 150)
		K.change("nameplates.castHeight", 200)
		local k = K.npShow("nameplate1", { player = false, friend = false })
		K.npOptions()
		K.flush()
		check("bar heights in the Classic style: no height is set by the addon and Blizzard's heights stand", #NP.calls(K, nil, "SetHeight", true) == 0 and near(k.hcr.height, 10) and near(k.ccr.height, 10) and near(k.castr.height, 10),
			g(k.hcr.height))
		K.npOptions(NP.STYLE.Thin, 2)
		K.flush()
		check("bar heights: when the style leaves Classic the percentages apply", near(k.hcr.height, 19.5) and near(k.castr.height, 12) and near(k.ccr.height, 22), g(k.hcr.height) .. " " .. g(k.castr.height))
		K.npOptions(NP.STYLE.Classic, 2)
		K.flush()
		check("bar heights: and when the style returns to Classic Blizzard's heights stand", near(k.hcr.height, 10) and near(k.castr.height, 10) and near(k.ccr.height, 10), g(k.hcr.height) .. " " .. g(k.castr.height))
		mark = #K.npLog
		K.change("nameplates.healthHeight", 100)
		K.change("nameplates.castHeight", 100)
		check("bar heights: the settings back to 100 in the Classic style set nothing", #NP.mine(K, k, mark, "HealthBarsContainer") == 0 and #NP.mine(K, k, mark, "castBar") == 0)
		clean(K, "bar heights, classic")

		-- Heights at 100 from the start: the addon never sets one, whatever happens.
		local Z = NP.npWorld()
		Z.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		Z.npOptions()
		Z.npOptions(NP.STYLE.Block, 3)
		Z.npCVar("nameplateDebuffPadding", 8)
		Z.change("nameplates.nameSize", 130)
		Z.change("nameplates.health", false)
		Z.change("nameplates.enabled", false)
		Z.change("nameplates.enabled", true)
		Z.combat = true
		Z.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		Z.combat = false
		Z.fire("PLAYER_REGEN_ENABLED")
		Z.flush()
		check("bar heights at 100 from the start: the addon never calls SetHeight", #NP.calls(Z, nil, "SetHeight", true) == 0)
		clean(Z, "bar heights at 100")

		-- A base height that is missing or withheld: no call. Three plates, so a part that fails on each would show.
		for _, key in ipairs({ "healthBarHeight", "castBarHeight", "castIconHeight" }) do
			for _, variant in ipairs({ { "missing", nil }, { "withheld", SECRET }, { "zero", 0 }, { "a string", "13" } }) do
				local V = NP.npWorld()
				V.npAllow = true
				local ps = {}
				for i = 1, 3 do
					ps[i] = V.npShow("nameplate" .. i, { player = false, friend = false })
				end
				V.env.NamePlateSetupOptions[key] = variant[2]
				V.change("nameplates.healthHeight", 150)
				V.change("nameplates.castHeight", 200)
				local sets = {}
				for _, v in ipairs(ps) do
					for _, e in ipairs(NP.mine(V, v, 0)) do
						if e.call == "SetHeight" then
							sets[#sets + 1] = e.label:match("%.(%w+)$") .. ":" .. NP.callText(e)
						end
					end
				end
				local expected = key == "healthBarHeight" and "CastBarsContainer:SetHeight(22) castBar:SetHeight(12)" or "HealthBarsContainer:SetHeight(19.5)"
				local got, seen2 = {}, {}
				for _, t in ipairs(sets) do
					if not seen2[t] then
						seen2[t] = true
						got[#got + 1] = t
					end
				end
				check("bar heights with " .. key .. " " .. variant[1] .. ": only the bar whose number is plain is resized", table.concat(got, " ") == expected and #V.errors == 0 and #V.violations == 0
					and not has(V.status(), "stopped"), table.concat(got, " "))
			end
		end
		-- spellNameInsideCastBar withheld or not a boolean: the cast bar is left alone.
		for _, variant in ipairs({ { "withheld", SECRET }, { "missing", nil }, { "a number", 1 } }) do
			local V = NP.npWorld()
			V.npAllow = true
			local v = V.npShow("nameplate1", { player = false, friend = false })
			V.env.NamePlateSetupOptions.spellNameInsideCastBar = variant[2]
			V.change("nameplates.castHeight", 200)
			check("cast bar height with spellNameInsideCastBar " .. variant[1] .. ": the cast bar is left alone", #NP.mine(V, v, 0, "CastBarsContainer") == 0 and #NP.mine(V, v, 0, "castBar") == 0 and #V.errors == 0 and #V.violations == 0)
		end
	end

	-- 75h2. Bar heights where the client may refuse: in combat, out of it, and when it will not say.
	do
		local function three(W)
			local list = {}
			for i = 1, 3 do
				list[i] = W.npShow("nameplate" .. i, { player = false, friend = false })
			end
			W.flush()
			return list
		end
		local line1 = "Bar height: nameplates that appear in combat get their height when combat ends."
		local line2 = "Bar height: the game does not allow nameplate bars to be resized."
		-- The game refuses in combat.
		local W = NP.npWorld()
		local p = three(W)
		W.combat = true
		W.change("nameplates.healthHeight", 150)
		W.change("nameplates.castHeight", 200)
		W.flush()
		check("heights refused in combat: no height is set and the plates keep Blizzard's", #NP.calls(W, nil, "SetHeight", true) == 0 and near(p[1].hcr.height, 13) and near(p[3].castr.height, 6), g(p[1].hcr.height))
		check("heights refused in combat: the status has one line about it", count(W.status(), line1) == 1 and not has(W.status(), line2), W.status())
		local plate4 = W.npShow("nameplate4", { player = false, friend = false })
		W.npOptions()
		W.flush()
		check("heights refused in combat: a plate added in combat and a layout in combat set none either", #NP.calls(W, nil, "SetHeight", true) == 0 and #W.violations == 0 and #W.errors == 0)
		local mark2 = #W.npLog
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("heights refused in combat: when combat ends the plates are laid out once, three heights on each of four plates", #NP.calls(W, nil, "SetHeight", true, mark2) == 12, #NP.calls(W, nil, "SetHeight", true, mark2))
		check("heights refused in combat: when combat ends every plate is laid out with the percentages", near(p[1].hcr.height, 19.5) and near(p[2].hcr.height, 19.5) and near(p[3].hcr.height, 19.5) and near(plate4.hcr.height, 19.5)
			and near(p[3].castr.height, 12) and near(p[3].ccr.height, 22) and near(plate4.castr.height, 12), g(p[1].hcr.height) .. " " .. g(plate4.hcr.height))
		local made = #NP.calls(W, nil, "SetHeight", true)
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("heights refused in combat: and combat ending again does nothing more", #NP.calls(W, nil, "SetHeight", true) == made)
		clean(W, "heights in combat")

		-- Allowed in combat: set at once, nothing said.
		local A = NP.npWorld()
		A.npAllow = true
		local pa = three(A)
		A.combat = true
		A.change("nameplates.healthHeight", 150)
		check("heights allowed in combat: set at once and not mentioned", near(pa[1].hcr.height, 19.5) and not has(A.status(), "Bar height"), A.status())
		clean(A, "heights allowed in combat")

		-- The game refuses out of combat: nothing is set, nothing waits, one line, and no loop.
		local N = NP.npWorld()
		N.npAllow = false
		three(N)
		local checks0 = N.npChecks
		N.change("nameplates.healthHeight", 150)
		N.change("nameplates.healthHeight", 160)
		N.change("nameplates.castHeight", 200)
		N.flush()
		check("heights refused out of combat: nothing is set and the status says the game does not allow it, once", #NP.calls(N, nil, "SetHeight", true) == 0 and count(N.status(), line2) == 1 and not has(N.status(), line1), N.status())
		check("heights refused out of combat: asking the game is bounded, no loop", N.npChecks - checks0 < 60, N.npChecks - checks0)
		N.npAllow = true
		N.fire("PLAYER_REGEN_ENABLED")
		N.flush()
		check("heights refused out of combat: nothing was queued for when combat ends", #NP.calls(N, nil, "SetHeight", true) == 0)
		check("heights refused out of combat: the game was asked without a report of a blocked action", N.npLoud == nil)
		clean(N, "heights refused out of combat")

		-- A client without the question falls back on whether the player is in combat.
		local M = NP.npWorld(nil, { without = { "C_RestrictedActions" } })
		local pm = three(M)
		M.change("nameplates.healthHeight", 150)
		check("heights without CheckAllowProtectedFunctions: out of combat they are set", near(pm[1].hcr.height, 19.5) and not has(M.status(), "Bar height"))
		M.combat = true
		M.change("nameplates.healthHeight", 130)
		check("heights without CheckAllowProtectedFunctions: in combat they are held back", near(pm[1].hcr.height, 19.5) and count(M.status(), line1) == 1, g(pm[1].hcr.height))
		M.combat = false
		M.fire("PLAYER_REGEN_ENABLED")
		M.flush()
		check("heights without CheckAllowProtectedFunctions: and set when combat ends", near(pm[1].hcr.height, 16.9) and near(pm[3].hcr.height, 16.9), g(pm[1].hcr.height))
		clean(M, "heights without the question")

		-- An answer that is withheld, not a boolean or an error is no answer.
		for _, fault in ipairs({ "secret", "string", "error" }) do
			local V = NP.npWorld()
			local pv = three(V)
			V.npCheckFault = fault
			V.change("nameplates.healthHeight", 150)
			check("heights with an answer that is " .. fault .. ": out of combat the fallback applies and they are set", near(pv[1].hcr.height, 19.5) and #V.errors == 0 and #V.violations == 0, g(pv[1].hcr.height))
			V.combat = true
			V.change("nameplates.healthHeight", 130)
			check("heights with an answer that is " .. fault .. ": in combat the fallback applies and they are held back", near(pv[1].hcr.height, 19.5) and count(V.status(), line1) == 1 and #V.errors == 0 and #V.violations == 0, g(pv[1].hcr.height))
		end
	end


	-- Where the class icon of a plate is: its one point as "POINT RELATIVE RELATIVEPOINT x,y", and its size.
	function NP.iconPlace(W, F)
		local I = NP.iconOf(W, F)
		if not I then
			return "none"
		end
		local p = I.icon.points[1]
		local rel = p and (p[2] == I.guide and "guide" or (p[2] == F.cc and "castContainer" or (p[2] == F.hc and "healthContainer" or "other")))
		return p and ("%s %s %s %s,%s %sx%s n%d"):format(p[1], rel, p[3], g(p[4]), g(p[5]), g(I.icon.width), g(I.icon.height), #I.icon.points) or "unplaced"
	end
	function NP.shownIcon(W, F)
		local I = NP.iconOf(W, F)
		return I ~= nil and I.art.shown == true
	end
	function NP.atlasOf(W, F)
		local I = NP.iconOf(W, F)
		return I and I.art.atlas or "none"
	end

	-- 75i. Class icons: when a plate has one.
	do
		local W = NP.npWorld()
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local I = NP.iconOf(W, e)
		check("class icon: an enemy player's plate has the art of its class, shown", I and I.art.shown and I.art.atlas == "classicon-mage" and I.art.layer == "ARTWORK", NP.atlasOf(W, e))
		check("class icon: and a border of the addon's around it, with its backdrop", I and I.look and I.look.state == "SB", I and I.look and I.look.state)
		local g1 = I.guide and I.guide.points
		check("class icon: the guide is anchored to the cast container's sides and the health container's top and bottom, no offsets",
			g1 and #g1 == 4 and g1[1][1] == "LEFT" and g1[1][2] == e.cc and g1[1][3] == "LEFT" and g1[2][1] == "RIGHT" and g1[2][2] == e.cc and g1[2][3] == "RIGHT"
			and g1[3][1] == "TOP" and g1[3][2] == e.hc and g1[3][3] == "TOP" and g1[4][1] == "BOTTOM" and g1[4][2] == e.hc and g1[4][3] == "BOTTOM"
			and g1[1][4] == 0 and g1[1][5] == 0 and g1[2][4] == 0 and g1[3][5] == 0 and g1[4][5] == 0, g1 and #g1)
		check("class icon: the guide and the icon are children of the unit frame, the art is a texture of the icon", I.guide.parent == e.uf and I.icon.parent == e.uf and I.art.owner == I.icon)
		check("class icon: left of the row by default, the height of the health bar, flush with the guide", NP.iconPlace(W, e) == "RIGHT guide LEFT 0,0 13x13 n1", NP.iconPlace(W, e))
		check("class icon: the addon's own frames are all it made on the unit frame", #NP.mine(W, e, 0, "UnitFrame") == 0, NP.callsText(NP.mine(W, e, 0, "UnitFrame")))
		local icon = I.icon
		local shows = 0
		for _, entry in ipairs(NP.calls(W, icon.label, nil, true)) do
			shows = shows + 1
		end
		check("class icon: the icon frame itself is never shown or hidden", shows == 0 and icon.shown == true, shows)
		clean(W, "class icon")

		-- Every class has its own art.
		local C = NP.npWorld()
		local list = {}
		for i, class in ipairs(NP.CLASSES) do
			list[i] = C.npShow("nameplate" .. i, { player = true, friend = false, class = class })
		end
		C.flush()
		local atlases = {}
		for i, F in ipairs(list) do
			atlases[i] = NP.atlasOf(C, F)
		end
		check("class icon: each of the nine classes gets classicon- and its name in lower case", table.concat(atlases, ",") == "classicon-warrior,classicon-paladin,classicon-priest,classicon-shaman,classicon-druid,classicon-rogue,classicon-mage,classicon-warlock,classicon-hunter",
			table.concat(atlases, ","))
		check("class icon: each plate has its own icon", #C.addonFrames >= 9 * 3)
		clean(C, "class icon, nine classes")
	end

	-- 75i2. Class icons: the friendly and enemy switches.
	do
		local W = NP.npWorld()
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local f = W.npShow("nameplate2", { player = true, friend = true, class = "PRIEST" })
		check("class icon: a friendly player has none while the friendly switch is off", not NP.shownIcon(W, f) and NP.shownIcon(W, e))
		W.change("nameplates.classFriendly", true)
		check("class icon: friendly switched on, the plate that is there shows it without being added again", NP.shownIcon(W, f) and NP.atlasOf(W, f) == "classicon-priest" and NP.shownIcon(W, e))
		W.change("nameplates.classEnemy", false)
		check("class icon: enemy switched off, only the enemy's is hidden", not NP.shownIcon(W, e) and NP.shownIcon(W, f))
		W.change("nameplates.classFriendly", false)
		check("class icon: both off, none is shown, and the borders are hidden too", not NP.shownIcon(W, e) and not NP.shownIcon(W, f) and NP.iconOf(W, e).look.state == "hb" and NP.iconOf(W, f).look.state == "hb")
		W.change("nameplates.classEnemy", true)
		W.change("nameplates.classFriendly", true)
		check("class icon: both on again, both show with their borders", NP.shownIcon(W, e) and NP.shownIcon(W, f) and NP.iconOf(W, e).look.state == "SB" and NP.iconOf(W, f).look.state == "SB")
		local frames = #W.addonFrames
		W.change("nameplates.classEnemy", false)
		W.change("nameplates.classEnemy", true)
		check("class icon: switching again makes no new frame", #W.addonFrames == frames)
		clean(W, "class icon switches")
	end

	-- 75i3. Class icons: position, size and offsets.
	do
		local W = NP.npWorld()
		W.change("nameplates.classFit", "Custom")
		W.change("nameplates.classGap", 3)
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local cases = {
			{ "Left", 20, 0, 0, "RIGHT guide LEFT -3,0 20x20 n1" },
			{ "Left", 32, 10, -5, "RIGHT guide LEFT 7,-5 32x32 n1" },
			{ "Right", 20, 0, 0, "LEFT guide RIGHT 3,0 20x20 n1" },
			{ "Right", 8, -60, 60, "LEFT guide RIGHT -57,60 8x8 n1" },
			-- Above: the spacing above the bar (2) and the name's height (14) sit between the guide and the icon: 16 + 3.
			{ "Above", 20, 0, 0, "BOTTOM guide TOP 0,19 20x20 n1" },
			{ "Above", 64, 5, 7, "BOTTOM guide TOP 5,26 64x64 n1" },
			{ "Below", 20, 0, 0, "TOP castContainer BOTTOM 0,-3 20x20 n1" },
			{ "Below", 16, -12, 4, "TOP castContainer BOTTOM -12,1 16x16 n1" },
		}
		for _, c in ipairs(cases) do
			W.change("nameplates.classPosition", c[1])
			W.change("nameplates.classSize", c[2])
			W.change("nameplates.classX", c[3])
			W.change("nameplates.classY", c[4])
			check("class icon " .. c[1] .. ", size " .. c[2] .. ", offsets " .. c[3] .. " and " .. c[4] .. ": one anchor, as designed", NP.iconPlace(W, e) == c[5], NP.iconPlace(W, e))
		end
		clean(W, "class icon placement")

		-- Above: the name's height times the name size sits between the icon and the bar, unless the name is inside the bar.
		local A = NP.npWorld()
		A.change("nameplates.classFit", "Custom")
		A.change("nameplates.classGap", 3)
		local a = A.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		A.change("nameplates.classPosition", "Above")
		A.change("nameplates.nameSize", 150)
		check("class icon above: a bigger name moves the icon up by the difference (2 + 14 x 1.5 + 3)", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,26 20x20 n1", NP.iconPlace(A, a))
		A.change("nameplates.nameSize", 50)
		check("class icon above: a smaller name moves it down (2 + 14 x 0.5 + 3)", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,12 20x20 n1", NP.iconPlace(A, a))
		A.change("nameplates.nameSize", 100)
		A.npOptions(NP.STYLE.Modern, 2)
		A.flush()
		check("class icon above: with the name inside the bar the icon is three units above the guide", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,3 20x20 n1", NP.iconPlace(A, a))
		A.change("nameplates.nameSize", 200)
		check("class icon above: the name size does not matter while the name is inside the bar", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,3 20x20 n1", NP.iconPlace(A, a))
		A.npOptions(NP.STYLE.Thin, 3)
		A.change("nameplates.nameSize", 100)
		check("class icon above: a larger plate size makes the name taller (2.5 + 17.5 + 3)", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,23 20x20 n1", NP.iconPlace(A, a))
		A.npOptions(NP.STYLE.Classic, 2)
		A.flush()
		check("class icon above: in the Classic style the name is above the bar (4 + 10 + 3)", NP.iconPlace(A, a) == "BOTTOM guide TOP 0,17 20x20 n1", NP.iconPlace(A, a))
		clean(A, "class icon above")

		-- Name-only mode: the icon goes above the name, and returns when the mode ends.
		local N = NP.npWorld()
		N.change("nameplates.classFit", "Custom")
		N.change("nameplates.classGap", 3)
		N.change("nameplates.classFriendly", true)
		local f = N.npShow("nameplate1", { player = true, friend = true, class = "PRIEST" })
		N.change("nameplates.classPosition", "Left")
		check("class icon: a friendly player shows it to the left as set", NP.iconPlace(N, f) == "RIGHT guide LEFT -3,0 20x20 n1", NP.iconPlace(N, f))
		local frames = #N.addonFrames
		N.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", true)
		N.flush()
		check("class icon in name-only mode: above the name whatever the position is (2 + 14 + 3), shown", f.u.showOnlyName == true and NP.iconPlace(N, f) == "BOTTOM guide TOP 0,19 20x20 n1" and NP.shownIcon(N, f), NP.iconPlace(N, f))
		N.change("nameplates.nameSize", 150)
		check("class icon in name-only mode: a bigger name moves it (2 + 21 + 3)", NP.iconPlace(N, f) == "BOTTOM guide TOP 0,26 20x20 n1", NP.iconPlace(N, f))
		N.change("nameplates.nameSize", 100)
		N.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", false)
		N.flush()
		check("class icon: back where the setting puts it when name-only mode ends, on the next frame", f.u.showOnlyName == false and NP.iconPlace(N, f) == "RIGHT guide LEFT -3,0 20x20 n1" and NP.shownIcon(N, f), NP.iconPlace(N, f))
		check("class icon: no new frame for the mode", #N.addonFrames == frames)
		-- The addon's handler of UNIT_FACTION can run before the game's own on the plate: the comparison waits a frame.
		do
			local O = NP.npWorld()
			O.change("nameplates.classFit", "Custom")
			O.change("nameplates.classGap", 3)
			O.change("nameplates.classFriendly", true)
			O.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", true)
			local g = O.npShow("nameplate1", { player = true, friend = false, class = "PRIEST" })
			O.flush()
			g.info.friend = true
			O.fire("UNIT_FACTION", g.unit)
			O.blizzard(function() g.call("OnUnitFactionChanged") end)
			O.flush()
			check("insthook: UNIT_FACTION before the game's handler: the plate that turned name only is laid out on the next frame", g.u.showOnlyName == true and NP.iconPlace(O, g) == "BOTTOM guide TOP 0,19 20x20 n1", NP.iconPlace(O, g))
			clean(O, "insthook faction order")
		end
		N.npOptions(NP.STYLE.Modern, 2)
		N.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", true)
		N.flush()
		check("class icon in name-only mode with the name inside the bar: three units above the guide", NP.iconPlace(N, f) == "BOTTOM guide TOP 0,3 20x20 n1", NP.iconPlace(N, f))
		clean(N, "class icon, name only")

		-- Placement is skipped when nothing changed.
		local P = NP.npWorld()
		P.change("nameplates.classFit", "Custom")
		local p = P.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local icon = NP.iconOf(P, p).icon
		local points = icon.calls.SetPoint
		P.npOptions()
		P.change("nameplates.health", false)
		P.change("nameplates.health", true)
		P.npCVar("nameplateDebuffPadding", 4)
		P.flush()
		check("class icon: placed once while position, size, offsets and lift stay the same", icon.calls.SetPoint == points and icon.calls.ClearAllPoints == 1, tostring(icon.calls.SetPoint) .. " " .. tostring(points))
		P.change("nameplates.classSize", 24)
		check("class icon: a new size places it again", icon.calls.SetPoint == points + 1 and icon.calls.ClearAllPoints == 2 and icon.width == 24)
		clean(P, "class icon, placed once")
	end

	-- 75e3. squared: the class icon at the height of the health bar, with a gap, and the raid marker beside it.
	do
		local T = { bad = {} }
		function T.world(set, info, setup)
			local W = NP.npWorld(nil, setup)
			W.npAllow = true
			for _, row in ipairs(set or {}) do
				W.change(row[1], row[2])
			end
			local a = W.npShow("nameplate1", info or { player = true, friend = false, class = "MAGE" })
			W.flush()
			return W, a
		end
		function T.x(a)
			return a.markerr.points[1] and a.markerr.points[1][4]
		end
		local W, a = T.world({ { "nameplates.classGap", 2 } })
		check("squared: the class icon on the left is the height of the bar and its gap before the guide", NP.iconPlace(W, a) == "RIGHT guide LEFT -2,0 13x13 n1", NP.iconPlace(W, a))
		check("squared: the raid marker moves out past the icon and its gap", near(T.x(a), -15), tostring(T.x(a)))
		W.change("nameplates.classGap", 0)
		check("squared: gap 0 is flush with the guide and the marker moves by the icon alone", NP.iconPlace(W, a) == "RIGHT guide LEFT 0,0 13x13 n1" and near(T.x(a), -13), NP.iconPlace(W, a))
		W.change("nameplates.healthHeight", 150)
		check("squared: a new bar height places the icon again at the new size and moves the marker", NP.iconPlace(W, a) == "RIGHT guide LEFT 0,0 19.5x19.5 n1" and near(T.x(a), -19.5), NP.iconPlace(W, a))
		W.change("nameplates.healthHeight", 100)
		W.change("nameplates.raidMarkerX", 4)
		check("squared: the marker's own offset adds to the move", near(T.x(a), -9), tostring(T.x(a)))
		W.change("nameplates.raidMarkerX", 0)
		W.change("nameplates.classFit", "Custom")
		W.change("nameplates.classSize", 30)
		check("squared: Custom keeps the size set, and the marker moves by it", NP.iconPlace(W, a) == "RIGHT guide LEFT 0,0 30x30 n1" and near(T.x(a), -30), NP.iconPlace(W, a))
		W.change("nameplates.classFit", "Health bar height")
		W.change("nameplates.classPosition", "Right")
		check("squared: the icon on the right is a gap after the guide and the marker has no move", NP.iconPlace(W, a) == "LEFT guide RIGHT 0,0 13x13 n1" and near(T.x(a), 0), NP.iconPlace(W, a))
		W.change("nameplates.classGap", 2)
		check("squared: the right slot adds the gap", NP.iconPlace(W, a) == "LEFT guide RIGHT 2,0 13x13 n1", NP.iconPlace(W, a))
		W.change("nameplates.classPosition", "Above")
		check("squared: above keeps three units, the marker has no move", NP.iconPlace(W, a) == "BOTTOM guide TOP 0,19 13x13 n1" and near(T.x(a), 0), NP.iconPlace(W, a))
		W.change("nameplates.classPosition", "Below")
		check("squared: below keeps three units, the marker has no move", NP.iconPlace(W, a) == "TOP castContainer BOTTOM 0,-3 13x13 n1" and near(T.x(a), 0), NP.iconPlace(W, a))
		W.change("nameplates.classPosition", "Left")
		check("squared: back on the left the marker moves again", near(T.x(a), -15), tostring(T.x(a)))
		-- The Classic style does not resize the bar, so the icon is the bar height the game gives.
		do
			local C, c = T.world({ { "nameplates.healthHeight", 150 } }, nil, { style = NP.STYLE.Classic })
			local size = g(C.env.NamePlateSetupOptions.healthBarHeight)
			check("squared: in the Classic style the icon is the bar height the game gives, whatever Health bar height is", NP.iconPlace(C, c) == ("RIGHT guide LEFT 0,0 %sx%s n1"):format(size, size), NP.iconPlace(C, c))
		end
		-- The plate is used again for a creature: no icon, no move.
		local plate = a.plate
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate1", { player = false, friend = false })
		W.flush()
		check("squared: a plate used again for a creature has no icon and the marker is back at the game's place", not NP.shownIcon(W, a) and near(T.x(a), 0), tostring(T.x(a)))
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		check("squared: and an enemy player on it again moves the marker", NP.shownIcon(W, a) and near(T.x(a), -15), tostring(T.x(a)))
		-- A friendly player in name-only mode has the icon above the name and the marker is not moved.
		local F, f = T.world({ { "nameplates.classFriendly", true } }, { player = true, friend = true, class = "PRIEST" })
		check("squared: a friendly player with the icon on shows the marker moved out", near(T.x(f), -13), tostring(T.x(f)))
		F.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", true)
		F.flush()
		check("squared: in name-only mode the marker is where the game puts it", f.u.showOnlyName == true and near(T.x(f), 0) and #f.markerr.points == 1, tostring(T.x(f)))
		-- A raid marker offset set, in name-only mode: still not moved.
		local N, n = T.world({ { "nameplates.classFriendly", true }, { "nameplates.raidMarkerX", 5 } }, { player = true, friend = true, class = "PRIEST" })
		N.npCVar("nameplateShowOnlyNameForFriendlyPlayerUnits", true)
		N.flush()
		check("squared: name-only mode leaves the marker at the game's place with an offset set", n.u.showOnlyName == true and near(T.x(n), 0) and #n.markerr.points == 1 and n.markerr.points[1][1] == "BOTTOM", tostring(T.x(n)))
		-- A plate used again for a second enemy player: the game put the marker back at the bar.
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate1", { player = true, friend = false, class = "ROGUE" })
		W.flush()
		check("squared: a second enemy player on the same plate has the marker out past the icon", NP.shownIcon(W, a) and near(T.x(a), -15), tostring(T.x(a)))
		-- A change of the game's Debuff padding anchors the marker at the bar again, and the next pass puts it out past the icon.
		W.npCVar("nameplateDebuffPadding", 3)
		W.flush()
		check("squared: a Debuff padding change leaves the marker out past the icon", near(T.x(a), -15), tostring(T.x(a)))
		check("squared: no violation or error", #W.violations == 0 and #W.errors == 0 and #F.violations == 0 and #F.errors == 0, table.concat(W.violations, "|"))
	end

	-- 75i4. Class icons: the border and the art.
	do
		local W = NP.npWorld()
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local icon = NP.iconOf(W, e).icon
		local ok, detail = ringOf(W, icon, 1)
		check("class icon border: four one pixel black edges around the icon", ok, detail)
		W.change("general.border", "ff336699")
		W.change("general.thickness", 2)
		check("class icon border: the general border colour and thickness reach it", ringOf(W, icon, 2, 0.2, 0.4, 0.6))
		W.change("general.backdrop", "ff102030")
		local back = W.backdropOn(icon)
		check("class icon border: and the general background colour", back and near(back.color[1], 0x10 / 255) and near(back.color[3], 0x30 / 255) and back.shown)
		W.change("nameplates.classBorder", false)
		local I = NP.iconOf(W, e)
		check("class icon border off: the art shows with no edges and no backdrop", I.art.shown and I.look.state == "hb" and not I.look.backShown, I.look.state)
		W.change("nameplates.classBorder", true)
		check("class icon border on again", NP.iconOf(W, e).look.state == "SB" and NP.iconOf(W, e).art.shown)
		W.change("nameplates.classEnemy", false)
		W.change("nameplates.classBorder", false)
		W.change("nameplates.classEnemy", true)
		check("class icon border: an icon shown after the border was switched off has none", NP.iconOf(W, e).art.shown and NP.iconOf(W, e).look.state == "hb")
		clean(W, "class icon border")
	end

	-- 75i4b. Class icons: round. The nameplate world makes no masks unless it is built with hud = true.
	do
		local R = {}
		function R.fight(W, on)
			W.combat = on
			W.fire(on and "PLAYER_REGEN_DISABLED" or "PLAYER_REGEN_ENABLED")
		end
		function R.disc(W, icon)
			for _, t in ipairs(W.addonTextures) do
				if (t.owner == icon or (t.owner and t.owner.parent == icon)) and t.layer == "BACKGROUND" and t.sublevel == -7 then
					return t
				end
			end
		end
		-- The disc is on a frame that ignores the scale of the plate and has the pixel scale, so n pixels of border are n * PX / its scale units.
		function R.px() return PX / R.disc1.owner.GetEffectiveScale() end
		function R.world(hud, circle)
			local W = NP.npWorld({ hud = hud })
			W.npAtlases.CircleMaskScalable = circle
			return W
		end
		function R.whole(icon)
			local px = icon.width / (PX / icon.GetEffectiveScale())
			return math.abs(px - math.floor(px + 0.5)) < 0.001
		end
		local W = R.world(true, true)
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local art, icon = NP.iconOf(W, e).art, NP.iconOf(W, e).icon
		check("round class icon: square by default, with no mask and no disc", next(art.masks) == nil and R.disc(W, icon) == nil and NP.iconOf(W, e).look.state == "SB" and #W.addonMasks == 0)
		W.change("general.border", "ff336699")
		W.change("nameplates.classShape", "Round")
		W.flush()
		R.disc1, R.mask = R.disc(W, icon), next(art.masks)
		R.discMask = R.disc1 and next(R.disc1.masks)
		check("round class icon: the art has one mask, the circle atlas on all its points", R.mask ~= nil and next(art.masks, R.mask) == nil and R.mask.atlas == "CircleMaskScalable" and R.mask.allPoints == art)
		check("round class icon: the disc has the other mask and the points minus and plus the border thickness", R.discMask ~= nil and R.discMask ~= R.mask and R.discMask.atlas == "CircleMaskScalable"
			and R.discMask.allPoints == R.disc1 and #R.disc1.points == 2 and near(R.disc1.points[1][4], -R.px(icon)) and near(R.disc1.points[1][5], R.px(icon)) and near(R.disc1.points[2][4], R.px(icon))
			and near(R.disc1.points[2][5], -R.px(icon)), R.disc1 and R.disc1.points[1] and tostring(R.disc1.points[1][4]))
		check("round class icon: the four edges and the backdrop are hidden and the disc shows in the border colour", NP.iconOf(W, e).look.state == "hb" and R.disc1.shown
			and near(R.disc1.color[1], 0.2) and near(R.disc1.color[2], 0.4) and near(R.disc1.color[3], 0.6), NP.iconOf(W, e).look.state)
		check("round class icon: the disc and the masks are the addon's own", #W.addonMasks == 2 and R.disc1.addon == true)
		check("round class icon: the disc is on a frame of its own that ignores the scale of the plate, under the icon", R.disc1.owner ~= icon and R.disc1.owner.ignoreParentScale == true and R.disc1.owner.level < icon.level
			and R.disc1.owner.allPoints == icon, tostring(R.disc1.owner))
		check("round class icon: the icon is a whole number of screen pixels", R.whole(icon) and not near(icon.width, 13), tostring(icon.width))
		W.change("general.thickness", 2)
		check("round class icon: a thicker border moves the disc out", near(R.disc1.points[1][4], -2 * R.px(icon)) and near(R.disc1.points[2][5], -2 * R.px(icon)), tostring(R.disc1.points[1][4]))
		W.change("general.thickness", 1)
		W.change("nameplates.classBorder", false)
		check("round class icon: Class icon border off hides the disc and the art stays masked", not R.disc1.shown and R.mask and art.masks[R.mask] == true)
		W.change("nameplates.classBorder", true)
		W.change("general.borderless", true)
		check("round class icon: Borderless hides the disc", not R.disc1.shown and art.masks[R.mask] == true)
		W.change("general.borderless", false)
		check("round class icon: and the disc is back with it off", R.disc1.shown)
		W.change("nameplates.classShape", "Square")
		W.flush()
		check("round class icon: back to square, the art has no mask, the disc is hidden, the edges and the backdrop show", next(art.masks) == nil and not R.disc1.shown
			and NP.iconOf(W, e).look.state == "SB" and near(icon.width, 13), NP.iconOf(W, e).look.state .. " " .. tostring(icon.width))
		W.change("nameplates.classShape", "Round")
		check("round class icon: and round again takes the same mask and disc, none made twice", art.masks[R.mask] == true and #W.addonMasks == 2 and R.disc(W, icon) == R.disc1)
		clean(W, "round class icon")

		-- The first round icon in combat stays square until combat ends.
		local C = R.world(true, true)
		local c = C.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		R.fight(C, true)
		C.change("nameplates.classShape", "Round")
		C.flush()
		check("round class icon: a first round icon made in combat stays square, nothing is made", #C.addonMasks == 0 and next(NP.iconOf(C, c).art.masks) == nil and NP.iconOf(C, c).look.state == "SB"
			and #C.errors == 0 and #C.violations == 0)
		R.fight(C, false)
		C.flush()
		check("round class icon: after combat it is round", #C.addonMasks == 2 and next(NP.iconOf(C, c).art.masks) ~= nil and NP.iconOf(C, c).look.state == "hb")

		-- A client without masks, or without the circle, keeps the square icon and says so once.
		for _, variant in ipairs({ { "without masks", R.world(false, true) }, { "without the circle", R.world(true, false) } }) do
			local V = variant[2]
			local v = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			V.change("nameplates.classShape", "Round")
			V.flush()
			check("round class icon " .. variant[1] .. ": the icon stays square, no error, and the status says so in one line",
				NP.iconOf(V, v).look.state == "SB" and #V.addonMasks == 0 and count(V.status(), "Round class icons: this client has no circle mask, so they show square.") == 1
				and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), V.status())
		end
		check("round class icon: a client that can make masks says nothing", not has(W.status(), "Round class icons"), W.status())
	end

	-- 75i5. Class icons: the art that exists, and the art that does not.
	do
		local W = NP.npWorld()
		W.npAtlases["classicon-mage"] = nil
		local m = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local r = W.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		check("class icon art: without classicon-mage the group finder art is used, and the other class keeps its own", NP.atlasOf(W, m) == "groupfinder-icon-class-mage" and NP.atlasOf(W, r) == "classicon-rogue")
		check("class icon art: and nothing is said about it", W.line("Nameplates") == "Nameplates: on, 2 styled", W.status())
		W.npAtlases["groupfinder-icon-class-mage"] = nil
		W.npAtlases["classicon-warlock"], W.npAtlases["groupfinder-icon-class-warlock"] = nil, nil
		W.npShow("nameplate4", { player = true, friend = false, class = "WARLOCK" })
		local w3 = W.npShow("nameplate5", { player = true, friend = false, class = "WARLOCK" })
		W.change("nameplates.classSize", 24)
		W.change("nameplates.classSize", 20)
		W.flush()
		check("class icon art: a class with no art at all has no icon", NP.atlasOf(W, w3) == "none" and not NP.shownIcon(W, w3))
		check("class icon art: the status says so in one line, once", count(W.status(), "Class icons: no class art was found for a class, so it has no icon.") == 1, W.status())
		check("class icon art: the lookup for that class is made once for each name, not for every plate or pass", W.npAtlasCalls["classicon-warlock"] == 1 and W.npAtlasCalls["groupfinder-icon-class-warlock"] == 1,
			tostring(W.npAtlasCalls["classicon-warlock"]) .. " " .. tostring(W.npAtlasCalls["groupfinder-icon-class-warlock"]))
		check("class icon art: the plates that have art go on showing it", NP.shownIcon(W, r) and #W.errors == 0 and #W.violations == 0 and not has(W.status(), "stopped"))
		clean(W, "class icon art")

		-- GetAtlasExists is asked first: GetAtlasInfo is not needed while it answers.
		local E = NP.npWorld()
		E.env.C_Texture.GetAtlasInfo = function() error("GetAtlasInfo must not be asked", 0) end
		local e2 = E.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		E.npAtlases["classicon-rogue"] = nil
		local r2 = E.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		check("class icon art: GetAtlasExists is asked first and its answer is the answer", NP.atlasOf(E, e2) == "classicon-mage" and NP.atlasOf(E, r2) == "groupfinder-icon-class-rogue" and #E.errors == 0)

		-- A client without GetAtlasExists asks GetAtlasInfo.
		local I = NP.npWorld(nil, { without = { "C_Texture.GetAtlasExists" } })
		local i = I.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		I.npAtlases["classicon-rogue"] = nil
		local j = I.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		check("class icon art: without GetAtlasExists the answer of GetAtlasInfo is used", NP.atlasOf(I, i) == "classicon-mage" and NP.atlasOf(I, j) == "groupfinder-icon-class-rogue", NP.atlasOf(I, i) .. " " .. NP.atlasOf(I, j))
		clean(I, "class icon art, GetAtlasInfo")

		-- A client with neither, or whose answer is an error or withheld: no art.
		for _, variant in ipairs({ { "without C_Texture", { without = { "C_Texture" } } }, { "without any atlas function", { without = { "C_Texture.GetAtlasExists", "C_Texture.GetAtlasInfo" } } } }) do
			local V = NP.npWorld(nil, variant[2])
			local v = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			V.npOptions()
			V.flush()
			check("class icon art " .. variant[1] .. ": no icon, one line, no error", not NP.shownIcon(V, v) and count(V.status(), "Class icons: no class art") == 1 and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), V.status())
		end
		for _, answer in ipairs({ "error", "secret" }) do
			local V = NP.npWorld()
			V.npAtlases["classicon-mage"], V.npAtlases["groupfinder-icon-class-mage"] = answer, answer
			local v = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			local o = V.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
			check("class icon art when the answer is " .. answer .. ": no icon for that class, the others are shown, nothing stops", not NP.shownIcon(V, v) and NP.shownIcon(V, o) and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), V.status())
		end
	end

	-- 75i6. Class icons: the class the client gives, withholds or does not have yet.
	do
		for _, secretType in ipairs({ "table", "string" }) do
			local W = NP.npWorld()
			W.secretType = secretType
			local plates = {}
			for i = 1, 4 do
				plates[i] = W.npShow("nameplate" .. i, { player = true, friend = false, class = "secret" })
			end
			W.change("nameplates.classPosition", "Above")
			W.flush()
			local any = false
			for _, F in ipairs(plates) do
				any = any or NP.shownIcon(W, F)
			end
			check("class icon with a class that is withheld (a secret " .. secretType .. "): no icon, no string operation on it, no error, nothing stops", not any and #W.errors == 0 and #W.violations == 0
				and not has(W.status(), "stopped") and has(W.status(), "Nameplates: on, 4 styled") and W.npClassCalls > 0, W.status())
			check("class icon with a class that is withheld: the plate has no frame of the addon's for an icon", NP.iconOf(W, plates[1]) == nil)
			-- The text of the other parts is still done.
			check("class icon with a class that is withheld: the rest of the plate is styled", NP.fillText(plates[1]) == "nil|nil|1,1,1,1" and near(plates[1].textr.textHeight, 11.2))
		end

		-- Nothing yet, then UNIT_NAME_UPDATE.
		local W = NP.npWorld()
		local info = { player = true, friend = false }
		local e = W.npShow("nameplate1", info)
		W.flush()
		check("class icon with no class yet: none", not NP.shownIcon(W, e) and NP.iconOf(W, e) == nil and W.npClassCalls > 0)
		info.class = "MAGE"
		W.fire("UNIT_NAME_UPDATE", "nameplate1")
		check("class icon: the name update is not acted on before the next frame", not NP.shownIcon(W, e))
		W.tick()
		check("class icon: the class arrives with UNIT_NAME_UPDATE and the icon shows on the next frame", NP.shownIcon(W, e) and NP.atlasOf(W, e) == "classicon-mage")
		local calls0 = W.npClassCalls
		W.fire("UNIT_NAME_UPDATE", "target")
		W.fire("UNIT_NAME_UPDATE", "party1")
		W.tick()
		check("class icon: a name update of a unit that has no plate asks for nothing", W.npClassCalls == calls0, W.npClassCalls - calls0)
		W.fire("UNIT_NAME_UPDATE", "nameplate9")
		W.tick()
		check("class icon: a name update of a plate unit that has no plate asks for nothing either", W.npClassCalls == calls0, W.npClassCalls - calls0)
		info.class = "secret"
		W.fire("UNIT_NAME_UPDATE", SECRET)
		W.tick()
		check("class icon: a name update for a unit the client withholds looks at every plate, and the icon of a class now withheld is hidden", not NP.shownIcon(W, e) and #W.errors == 0 and #W.violations == 0)
		clean(W, "class icon, name update")

		-- UnitClassBase raises.
		local E = NP.npWorld()
		local good = E.npShow("nameplate1", { player = true, friend = false, class = "ROGUE" })
		local bad1 = E.npShow("nameplate2", { player = true, friend = false, class = "error" })
		E.npShow("nameplate3", { player = true, friend = false, class = "error" })
		E.npShow("nameplate4", { player = true, friend = false, class = "error" })
		local bad4 = E.npShow("nameplate5", { player = true, friend = false, class = "error" })
		E.change("nameplates.classSize", 22)
		E.flush()
		check("class icon when UnitClassBase raises: no icon for those plates, the module and the other icons go on", not NP.shownIcon(E, bad1) and not NP.shownIcon(E, bad4) and NP.shownIcon(E, good)
			and not has(E.status(), "stopped") and has(E.status(), "Nameplates: on, 5 styled"), E.status())
		check("class icon when UnitClassBase raises: no error reaches the client, and no art is looked for under the error's name", #E.errors == 0 and #E.violations == 0 and not has(E.status(), "no class art")
			and (function()
				for name in pairs(E.npAtlasCalls) do
					if name:find("failed", 1, true) then
						return false
					end
				end
				return true
			end)(), E.status())

		-- Not a player, and the flags that are not final.
		local D = NP.npWorld()
		local npc = D.npShow("nameplate1", { player = false, friend = false, class = "MAGE" })
		check("class icon: an NPC has none whatever the client says its class is", not NP.shownIcon(D, npc) and NP.iconOf(D, npc) == nil)
		local variants = {
			{ "isPlayer nil", function(F) F.u.isPlayer = nil end },
			{ "isPlayer withheld", function(F) F.u.isPlayer = SECRET end },
			{ "isPlayer a string", function(F) F.u.isPlayer = "yes" end },
			{ "isFriend nil", function(F) F.u.isFriend = nil end },
			{ "isFriend withheld", function(F) F.u.isFriend = SECRET end },
			{ "isFriend a number", function(F) F.u.isFriend = 1 end },
			{ "unit nil", function(F) F.u.unit = nil end },
			{ "unit withheld", function(F) F.u.unit = SECRET end },
			{ "unit a number", function(F) F.u.unit = 5 end },
			{ "widgets only", function(F) F.u.widgetsOnlyMode = true end },
			{ "widgets only withheld", function(F) F.u.widgetsOnlyMode = SECRET end },
		}
		for k, v in ipairs(variants) do
			local V = NP.npWorld()
			local p = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			local shownBefore = NP.shownIcon(V, p)
			v[2](p)
			V.change("nameplates.classSize", 22)
			V.flush()
			check("class icon with " .. v[1] .. ": the icon is hidden, nothing raises, nothing stops", shownBefore and not NP.shownIcon(V, p) and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), V.status() .. table.concat(V.violations, "|"))
		end
		-- The same flags before the first decision: no icon is ever made.
		for k, v in ipairs(variants) do
			if k ~= 7 and k ~= 8 and k ~= 9 then
				local V = NP.npWorld()
				local p = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, { quiet = true })
				v[2](p)
				V.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
				V.flush()
				check("class icon with " .. v[1] .. " at the first decision: no icon is made", NP.iconOf(V, p) == nil and #V.errors == 0 and #V.violations == 0, V.status())
			end
		end
		-- A plate whose name-only flag is withheld still gets its icon, placed by the setting.
		local S = NP.npWorld()
		S.change("nameplates.classFit", "Custom")
		S.change("nameplates.classGap", 3)
		local p = S.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		p.u.showOnlyName = SECRET
		S.change("nameplates.classPosition", "Left")
		check("class icon with the name-only flag withheld: placed by the setting, no error", NP.iconPlace(S, p) == "RIGHT guide LEFT -3,0 20x20 n1" and #S.errors == 0 and #S.violations == 0 and not has(S.status(), "stopped"), NP.iconPlace(S, p))
		-- A plate whose options are withheld, or whose name style is not known, still gets its icon above the bar by the setting.
		S.change("nameplates.classPosition", "Above")
		S.env.NamePlateConstants = SECRET
		S.change("nameplates.classSize", 21)
		check("class icon above with the name styles withheld: the name is taken to be above the bar (2 + 14 + 3)", NP.iconPlace(S, p) == "BOTTOM guide TOP 0,19 21x21 n1" and #S.errors == 0 and #S.violations == 0, NP.iconPlace(S, p))
		S.env.NamePlateConstants = nil
		S.env.NamePlateSetupOptions = SECRET
		S.change("nameplates.classSize", 22)
		check("class icon above with the options withheld: no lift (the icon sits three above the guide)", NP.iconPlace(S, p) == "BOTTOM guide TOP 0,3 22x22 n1" and #S.errors == 0 and #S.violations == 0, NP.iconPlace(S, p))
	end

	-- 75i7. Class icons on a pooled unit frame, and when the unit frame comes late.
	do
		local W = NP.npWorld()
		local m = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		local plate = m.plate
		local frames = #W.addonFrames
		local textures = #W.addonTextures
		local shown = {}
		W.npOnLayout = function(F) shown[#shown + 1] = tostring(NP.shownIcon(W, F)) end
		W.npRemove(m)
		check("pooled class icon: the plate is released and the icon is still the old unit's until the unit frame is laid out", NP.shownIcon(W, m))
		local other = W.npPlate()
		W.npAdd(other, m, "nameplate2", { player = false, friend = false }, { quiet = true })
		W.npOnLayout = nil
		check("pooled class icon: the addon does nothing during Blizzard's passes, so the old icon is there until the event of the same tick", table.concat(shown, ",") == "true,true", table.concat(shown, ","))
		W.fire("NAME_PLATE_UNIT_ADDED", "nameplate2")
		W.flush()
		check("pooled class icon: or after the event", not NP.shownIcon(W, m) and NP.iconOf(W, m).look.state == "hb")
		-- And back to a rogue: the first pass hides it, the event shows the rogue's art.
		shown = {}
		W.npOnLayout = function(F) shown[#shown + 1] = tostring(NP.shownIcon(W, F)) end
		W.npRemove(m)
		W.npAdd(plate, m, "nameplate3", { player = true, friend = false, class = "ROGUE" })
		W.npOnLayout = nil
		W.flush()
		check("pooled class icon: given to a rogue it is hidden at Blizzard's passes and shows the rogue's art after the event", table.concat(shown, ",") == "false,false" and NP.shownIcon(W, m) and NP.atlasOf(W, m) == "classicon-rogue",
			table.concat(shown, ",") .. NP.atlasOf(W, m))
		check("pooled class icon: the same frames and textures are used again", #W.addonFrames == frames and #W.addonTextures == textures, #W.addonFrames - frames)
		-- A mage again after a mage: the art is not set again.
		local sets = NP.iconOf(W, m).art.calls.SetAtlas
		W.npRemove(m)
		W.npAdd(plate, m, "nameplate4", { player = true, friend = false, class = "ROGUE" })
		W.flush()
		check("pooled class icon: the same class on the next unit keeps the art without setting it again", NP.shownIcon(W, m) and NP.iconOf(W, m).art.calls.SetAtlas == sets)
		clean(W, "pooled class icon")

		-- The unit frame comes after the event: decided on the next frame.
		local L = NP.npWorld()
		local late = L.npFrame()
		local lp = L.npPlate()
		L.npAdd(lp, late, "nameplate1", { player = true, friend = false, class = "MAGE" }, { late = true })
		check("class icon: a plate with no unit frame at its event has no icon yet", not NP.shownIcon(L, late))
		L.tick()
		check("class icon: the next frame decides it", NP.shownIcon(L, late) and NP.atlasOf(L, late) == "classicon-mage")
		clean(L, "class icon, late unit frame")
	end

	-- 75i8. Class icons when the sides change, and when the client changes what it withholds.
	do
		local W = NP.npWorld()
		local info = { player = true, friend = true, class = "MAGE" }
		local p = W.npShow("nameplate1", info)
		W.flush()
		check("class icon: a friendly player is without one while only enemies have them", not NP.shownIcon(W, p))
		W.npFaction(p, false)
		check("class icon: a friendly player turned hostile has none until the next frame", not NP.shownIcon(W, p))
		W.tick()
		check("class icon: and then has one", NP.shownIcon(W, p) and NP.atlasOf(W, p) == "classicon-mage")
		W.npFaction(p, true)
		W.tick()
		check("class icon: turned friendly again it is hidden on the next frame", not NP.shownIcon(W, p) and NP.iconOf(W, p).look.state == "hb")
		W.npFaction(p, false)
		W.fire("UNIT_FACTION", "player")
		W.fire("UNIT_FACTION", "target")
		W.tick()
		check("class icon: UNIT_FACTION for the player looks at every plate, and for a unit that is not a plate it does nothing", NP.shownIcon(W, p))
		check("class icon: and only one timer was set for the burst of events", #W.timers == 0)
		for _, event in ipairs({ "GROUP_ROSTER_UPDATE", "ADDON_RESTRICTION_STATE_CHANGED" }) do
			info.class = "MAGE"
			W.change("nameplates.classSize", 20)
			W.tick()
			check("class icon: before " .. event .. " the icon is shown", NP.shownIcon(W, p))
			info.class = "secret"
			W.fire(event)
			check("class icon: " .. event .. " is not acted on before the next frame", NP.shownIcon(W, p))
			W.tick()
			check("class icon: after " .. event .. " with the class withheld the icon is hidden on the next frame", not NP.shownIcon(W, p) and #W.errors == 0 and #W.violations == 0)
			info.class = "MAGE"
			W.fire(event)
			W.tick()
			check("class icon: and shown again when the class can be read", NP.shownIcon(W, p))
		end
		W.fire("GROUP_ROSTER_UPDATE")
		W.fire("GROUP_ROSTER_UPDATE")
		W.fire("ADDON_RESTRICTION_STATE_CHANGED")
		check("class icon: a burst of events sets one timer", #W.timers == 1, #W.timers)
		W.tick()
		clean(W, "class icon, events")

		-- Events while the page is off do nothing.
		local O = NP.twinOff()
		local o = O.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		O.npFaction(o, true)
		O.fire("GROUP_ROSTER_UPDATE")
		O.fire("UNIT_NAME_UPDATE", "nameplate1")
		O.tick()
		check("class icon: with the page off the events set no timer and make nothing", #O.timers == 0 and NP.iconOf(O, o) == nil and O.npClassCalls == 0, #O.timers .. " " .. O.npClassCalls)
	end

	-- 75i9. Class icons: off, and stopped.
	do
		local W = NP.npWorld()
		local list = {}
		for i = 1, 3 do
			list[i] = W.npShow("nameplate" .. i, { player = true, friend = false, class = NP.CLASSES[i] })
		end
		local function all(shown)
			for _, F in ipairs(list) do
				if NP.shownIcon(W, F) ~= shown or (NP.iconOf(W, F).look.state == "SB") ~= shown then
					return false
				end
			end
			return true
		end
		check("class icons: all three shown with their borders", all(true))
		W.change("nameplates.enabled", false)
		check("class icons: the page switch off hides the art and the borders on every plate", all(false))
		W.change("nameplates.enabled", true)
		check("class icons: and on again shows them", all(true))
		W.ns.Try("nameplates", function() error("a failure in the module", 0) end)
		check("class icons: a module that is stopped hides the art and the borders on every plate", all(false))
		check("class icons: and says it stopped", has(W.status(), "Nameplates: stopped. a failure in the module"), W.status())
		check("class icons: a stop raises no error and breaks no rule", #W.errors == 0 and #W.violations == 0)
	end


	-- 75j. CVars: the plates are laid out again on the next frame for a nameplate CVar, and for no other.
	do
		local W = NP.npWorld()
		W.npAllow = true
		W.change("nameplates.healthHeight", 150)
		local a = W.npShow("nameplate1", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 1 } })
		W.flush()
		check("CVar gap: the plate is the addon's after its unit was set", near(a.hcr.height, 19.5) and NP.fillText(a) == "nil|nil|1,1,1,1")
		-- A nameplate CVar: Blizzard's callbacks lay the plate out and nothing follows them, so Blizzard's bar is back until the next frame.
		W.npCVar("nameplateDebuffPadding", 5)
		check("CVar gap: Blizzard's callback gives Blizzard's bar back for now", near(a.hcr.height, 13) and NP.fillText(a) == NP.BAR_ATLAS .. "|nil|-", g(a.hcr.height) .. " " .. NP.fillText(a))
		check("CVar gap: and one timer waits to lay the plates out again", #W.timers == 1, #W.timers)
		W.npCVar("nameplateDebuffPadding", 6)
		W.npCVar("nameplateStyle", NP.STYLE.Thin)
		check("CVar gap: more CVars before the frame set no more timers", #W.timers == 1, #W.timers)
		W.tick()
		check("CVar gap: on the next frame the plate is the addon's again", near(a.hcr.height, 19.5) and NP.fillText(a) == "nil|nil|1,1,1,1" and NP.colourOf(a) == "0.2,0.4,0.6,1")
		local plate = a.plate
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate2", { player = false, friend = false, colour = { 0.2, 0.4, 0.6, 1 } })
		W.flush()
		W.npCVar("nameplateDebuffPadding", 7)
		W.flush()
		check("CVar: after a later assignment a CVar is laid out the same way, on the next frame", near(a.hcr.height, 19.5) and NP.fillText(a) == "nil|nil|1,1,1,1")
		W.flush()
		-- A style or size CVar: Blizzard fills its table and applies it to every plate.
		W.npCVar("nameplateSize", 3)
		W.flush()
		check("CVar: a size change gives the new plate size, 150 percent of it, on the next frame", near(a.hcr.height, 24.375) and near(W.env.NamePlateSetupOptions.healthBarHeight, 16.25), g(a.hcr.height))
		W.flush()
		-- A layout after a CVar is not taken to follow Blizzard's: a setting that was put right without the options (a saved file edited) is still put right.
		W.options()["nameplates.healthFlat"] = false
		W.options()["nameplates.healthHeight"] = 100
		W.fire("CVAR_UPDATE", "nameplateShowAll", "1")
		W.tick()
		check("CVar: the layout after it gives Blizzard's fill and height back to a plate the saved settings no longer change", NP.fillText(a) == NP.BAR_ATLAS .. "|nil|-" and near(a.hcr.height, 16.25), NP.fillText(a) .. " " .. g(a.hcr.height))
		W.options()["nameplates.healthFlat"] = true
		W.options()["nameplates.healthHeight"] = 150
		W.change("nameplates.healthFlat", false)
		W.change("nameplates.healthFlat", true)
		W.flush()
		-- Any other CVar does nothing at all.
		local mark = #W.npLog
		W.fire("CVAR_UPDATE", "SoftTargetNameplateSize", "1")
		W.fire("CVAR_UPDATE", "autoLootDefault", "1")
		W.fire("CVAR_UPDATE", SECRET, "1")
		W.fire("CVAR_UPDATE", 5, "1")
		check("CVar: a CVar that is not a nameplate one sets no timer and changes nothing", #W.timers == 0 and #NP.calls(W, nil, nil, true, mark) == 0)
		W.fire("CVAR_UPDATE", "NamePlateStyle", "1")
		check("CVar: the name is matched in any case", #W.timers == 1)
		W.flush()
		clean(W, "CVars")

		-- The page off: the CVar sets no timer.
		local O = NP.twinOff()
		O.flush()
		O.npShow("nameplate1", { player = false, friend = false })
		O.npCVar("nameplateDebuffPadding", 3)
		O.flush()
		check("CVar: with the page off no timer is set", #O.timers == 0)

		-- A target change with thirty plates costs the addon no font, height, fill or icon call.
		local T = NP.npWorld()
		T.npAllow = true
		T.change("nameplates.healthHeight", 150)
		T.change("nameplates.nameSize", 150)
		local list = {}
		for i = 1, 30 do
			list[i] = T.npShow("nameplate" .. i, { player = i % 2 == 0, friend = false, class = NP.CLASSES[i % 9 + 1] })
		end
		T.flush()
		local frames, textures = #T.addonFrames, #T.addonTextures
		mark = #T.npLog
		T.units.target = list[7].plate
		T.fire("PLAYER_TARGET_CHANGED")
		T.units.focus = list[12].plate
		T.fire("PLAYER_FOCUS_CHANGED")
		T.flush()
		check("target change with 30 plates: no font, height, fill or icon call and nothing made", #NP.calls(T, nil, nil, true, mark) == 0 and #T.addonFrames == frames and #T.addonTextures == textures,
			NP.callsText(NP.calls(T, nil, nil, true, mark)):sub(1, 200))
		check("target change with 30 plates: the target and the focus are marked", ringOf(T, list[7].hb, 1, 1, 1, 1) and ringOf(T, list[12].hb, 1, 1, 0.6, 0) and ringOf(T, list[7].level, 1, 1, 1, 1))
		clean(T, "target change")
	end

	-- 75k. The cast bar fill of another part of the addon: asked for with the setting, the switch and the state of the module.
	do
		local W = NP.npWorld(nil, { castFill = true })
		local a = W.npShow("nameplate1", { player = false, friend = false })
		local b = W.npShow("nameplate2", { player = true, friend = false, class = "MAGE" })
		W.flush()
		local function lastFor(F)
			for i = #W.castFills, 1, -1 do
				if W.castFills[i].bar == F.cast then
					return W.castFills[i]
				end
			end
		end
		local function allFor(F)
			local out = {}
			for _, e in ipairs(W.castFills) do
				if e.bar == F.cast then
					out[#out + 1] = tostring(e.flat)
				end
			end
			return out
		end
		check("cast fill: each plate's cast bar is passed with the module's key and true while the setting and the switch are on", lastFor(a) and lastFor(a).key == "nameplates" and lastFor(a).flat == true and lastFor(b).flat == true)
		local only = true
		for _, e in ipairs(W.castFills) do
			only = only and e.key == "nameplates" and type(e.flat) == "boolean" and (e.bar == a.cast or e.bar == b.cast)
		end
		check("cast fill: every call has the key, a cast bar of a plate and a boolean", only and #W.castFills > 0)
		W.castFills = {}
		W.change("nameplates.castFlat", false)
		check("cast fill: the setting off passes false for every plate", #allFor(a) > 0 and #allFor(b) > 0 and lastFor(a).flat == false and lastFor(b).flat == false, table.concat(allFor(a), ","))
		local every = true
		for _, e in ipairs(W.castFills) do
			every = every and e.flat == false
		end
		check("cast fill: and never true while it is off", every)
		W.change("nameplates.castFlat", true)
		check("cast fill: the setting on again passes true", lastFor(a).flat == true and lastFor(b).flat == true)
		W.castFills = {}
		W.change("nameplates.enabled", false)
		check("cast fill: the page switch off passes false although the setting is on", lastFor(a).flat == false and lastFor(b).flat == false and W.ns.Get("nameplates.castFlat") == true)
		W.change("nameplates.enabled", true)
		check("cast fill: the page switch on again passes true", lastFor(a).flat == true)
		W.castFills = {}
		W.ns.Try("nameplates", function() error("a failure in the module", 0) end)
		check("cast fill: a module that is stopped passes false for every plate it styled", lastFor(a) and lastFor(a).flat == false and lastFor(b).flat == false and W.ns.Get("nameplates.castFlat") == true)
		local late = W.npShow("nameplate3", { player = false, friend = false })
		W.flush()
		check("cast fill: a stopped module is not asked about a new plate", lastFor(late) == nil)
		-- A plate with no cast bar passes nothing.
		local N = NP.npWorld(nil, { castFill = true })
		N.npShow("nameplate1", { player = false, friend = false }, { remove = { "CastBarsContainer" } })
		N.change("nameplates.castFlat", false)
		check("cast fill: a plate with no cast bar container passes nothing and raises nothing", #N.castFills == 0 and #N.errors == 0 and #N.violations == 0)
		-- A client without it. The Cast bars define it, so that page is off here.
		local X = NP.npWorld({ saved = { options = { ["castbars.enabled"] = false } } }, { castFill = false })
		local x = X.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		X.change("nameplates.castFlat", false)
		X.change("nameplates.enabled", false)
		X.change("nameplates.enabled", true)
		check("cast fill: without a function for it everything else is done and nothing breaks", X.ns.CastFill == nil and NP.shownIcon(X, x) and NP.fillText(x) == "nil|nil|1,1,1,1" and #X.errors == 0 and #X.violations == 0
			and not has(X.status(), "stopped"))
		check("cast fill: no error and no broken rule", #W.errors == 0 and #W.violations == 0)
	end

	-- 75k2. A cast bar leaves the poll when Blizzard takes its plate back, and the poll stops with the last bar. W.npRemove does what
	-- Blizzard_NamePlates.lua:177-181 does before the addon's handler runs: ClearUnit sets the unit to nil (Blizzard_NamePlateBase.lua:41-46,
	-- CompactUnitFrame.lua:241-246) and ReleaseUnitFrame takes the unit frame off the plate (Blizzard_NamePlateBase.lua:24-27), so the plate
	-- the event names has no unit frame to find.
	do
		-- Flat fill of the Cast bars page is off, so that only the bars of the plates are followed.
		local ONLY = { saved = { options = { ["castbars.flat"] = false } }, fills = true }
		local W = NP.npWorld(ONLY)
		local list = {}
		for i = 1, 6 do
			list[i] = W.npShow("nameplate" .. i, { player = false, friend = false }, { fillCast = true })
			NP.watch(W, list[i].castr, list[i].id .. ".polled", { "IsShown" })
		end
		W.flush()
		local function visits(from)
			local n = 0
			for _, F in ipairs(list) do
				n = n + #NP.calls(W, F.id .. ".polled", "IsShown", true, from)
			end
			return n
		end
		local asked = { enabled = 0, stopped = 0 }
		local enabled, stopped = W.ns.Enabled, W.ns.PartStopped
		W.ns.Enabled = function(key)
			asked.enabled = asked.enabled + (key == "nameplates" and 1 or 0)
			return enabled(key)
		end
		W.ns.PartStopped = function(key, part)
			asked.stopped = asked.stopped + (key == "nameplates" and 1 or 0)
			return stopped(key, part)
		end
		local from = #W.npLog
		W.frame(1)
		W.ns.Enabled, W.ns.PartStopped = enabled, stopped
		check("cast poll: the bars of six plates are followed, and the module and its part are asked about once in a poll, not once for each bar",
			NP.polling(W) and visits(from) == 6 and asked.enabled == 1 and asked.stopped == 1, asked.enabled .. " " .. asked.stopped .. " " .. visits(from))
		for i = 1, 4 do
			W.npRemove(list[i])
		end
		W.flush()
		from = #W.npLog
		W.frame(1)
		check("cast poll: the bars of four plates Blizzard has taken back are not visited any more", NP.polling(W) and visits(from) == 2, visits(from))
		W.fills.castStart(list[5].castName, "cast")
		W.frame(1)
		local cover = NP.coverOf(W, list[5])
		check("cast poll: a cast on a plate that is still there gets its cover", cover and cover.shown)
		W.npRemove(list[5])
		W.npRemove(list[6])
		W.flush()
		check("cast poll: the poll stops with the last bar, and the cover of a plate that went is hidden", not NP.polling(W) and cover.shown == false)
		W.npAdd(list[1].plate, list[1], "nameplate7", { player = false, friend = false })
		W.flush()
		W.fills.castStart(list[1].castName, "channel")
		W.frame(1)
		local again = NP.coverOf(W, list[1])
		check("cast poll: a plate that gets a unit again is followed again", NP.polling(W) and again and again.shown)
		W.npRemove(list[1])
		W.npAdd(list[1].plate, list[1], "nameplate8", { player = false, friend = false })
		W.flush()
		from = #W.npLog
		W.frame(1)
		check("cast poll: a plate that is taken back and given a unit before the next frame stays followed", NP.polling(W) and visits(from) == 1, visits(from))
		W.change("nameplates.enabled", false)
		W.npRemove(list[1])
		W.change("nameplates.enabled", true)
		W.flush()
		check("cast poll: a plate taken back while the page was off is not followed when the page comes on", not NP.polling(W))
		check("cast poll: no error and no broken rule", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))

		-- A flat fill that stops in the middle of a poll gives back the bars after it, with the one line and no error.
		local S = NP.npWorld({ saved = { options = { ["castbars.flat"] = false } }, fills = true })
		local six = {}
		for i = 1, 6 do
			six[i] = S.npShow("nameplate" .. i, { player = false, friend = false }, { fillCast = true })
			S.fills.castStart(six[i].castName, "cast")
		end
		S.frame(2)
		for _, F in ipairs(six) do
			NP.coverOf(S, F).SetVertexColor = function() error("paint failed", 0) end
		end
		S.options()["castbars.castColour"] = "ff102030"
		S.frame(3)
		check("cast poll: a fill that stops partway through a poll gives back the bars it has not visited, with one line and no error",
			has(S.status(), "cast bar fill stopped. paint failed") and not NP.polling(S) and #S.errors == 0 and not has(S.status(), "nil") and not S.ns.IsStopped("nameplates"), S.status())
	end

	-- 75k3. A target or focus change styles again only the plates that stop or start being the target or the focus, a new plate only itself,
	-- and a plate Blizzard has taken back not at all. Blizzard's own change of a plate's markers is the same: NamePlateUnitFrameMixin:UpdateIsTarget
	-- (Blizzard_NamePlateUnitFrame.lua:401-412) does nothing on a plate whose state is the same.
	do
		local W = NP.npWorld()
		local list = {}
		for i = 1, 12 do
			list[i] = W.npShow("nameplate" .. i, { player = i % 2 == 0, friend = false, class = NP.CLASSES[i % 9 + 1] })
		end
		W.flush()
		local function counts()
			local out = {}
			for i, F in ipairs(list) do
				out[i] = W.rawOf[F.hb.selectedBorder].calls.SetAlpha or 0
			end
			return out
		end
		local function styled(before)
			local now, out = counts(), {}
			for i = 1, #list do
				if now[i] ~= before[i] then
					out[#out + 1] = i
				end
			end
			return table.concat(out, ",")
		end
		local before = counts()
		W.units.target = list[3].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("target change: the new target is styled again and no other plate", styled(before) == "3" and ringOf(W, list[3].hb, 1, 1, 1, 1), styled(before))
		before = counts()
		W.units.target = list[5].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("target change: the old and the new target are, and no other plate", styled(before) == "3,5" and ringOf(W, list[5].hb, 1, 1, 1, 1) and ringOf(W, list[3].hb, 1), styled(before))
		before = counts()
		W.units.focus = list[8].plate
		W.fire("PLAYER_FOCUS_CHANGED")
		W.flush()
		check("focus change: the new focus is, and no other plate", styled(before) == "8" and ringOf(W, list[8].hb, 1, 1, 0.6, 0), styled(before))
		before = counts()
		W.fire("PLAYER_TARGET_CHANGED")
		W.fire("PLAYER_FOCUS_CHANGED")
		W.flush()
		check("target change: an event that changes nothing styles no plate", styled(before) == "")
		before = counts()
		list[13] = W.npShow("nameplate13", { player = false, friend = false })
		W.flush()
		check("new plate: only that plate is styled, and the target and the focus are not", styled(before) == "13", styled(before))
		W.npRemove(list[1])
		W.npRemove(list[2])
		W.flush()
		before = counts()
		W.units.target = list[6].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("target change: a plate Blizzard has taken back is not styled again", styled(before) == "5,6" and ringOf(W, list[6].hb, 1, 1, 1, 1), styled(before))
		W.change("nameplates.targetColour", "ff00ff00")
		W.flush()
		check("target colour: a change of an option marks every plate again", ringOf(W, list[6].hb, 1, 0, 1, 0) and ringOf(W, list[8].hb, 1, 1, 0.6, 0) and ringOf(W, list[4].hb, 1))
		check("target change: no error and no broken rule", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end

	-- 75l. The page switch: off at login, on later, off again.
	do
		local ref = NP.twinOff()
		NP.threePlates(ref)
		local W = NP.twinOff()
		local frames, textures, hooks, logAt = #W.addonFrames, #W.addonTextures, W.hooks, #W.npLog
		local p = NP.threePlates(W)
		W.change("nameplates.healthFlat", false)
		W.change("nameplates.healthFlat", true)
		W.change("nameplates.nameSize", 150)
		W.change("nameplates.classFriendly", true)
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 4)
		W.units.target = p[1].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("page off at login: nothing is made, followed or called, however the plates, options and events go", #W.addonFrames == frames and #W.addonTextures == textures and W.hooks == hooks
			and #NP.calls(W, nil, nil, true, logAt) == 0 and NP.hooksOn(W, p[1]) == 0, #W.addonFrames - frames)
		check("page off at login: Blizzard's look is exactly what it is in a world where the addon is not there", W.npSnapAll() == ref.npSnapAll(), W.npSnapAll():sub(1, 300))
		check("page off at login: the status says off", W.line("Nameplates") == "Nameplates: off", W.line("Nameplates"))
		W.change("nameplates.nameSize", 100)
		W.change("nameplates.classFriendly", false)
		W.change("nameplates.enabled", true)
		W.flush()
		check("page switched on later: the plates there are styled", NP.fillText(p[1]) == "nil|nil|1,1,1,1" and near(p[1].textr.textHeight, 11.2) and NP.shownIcon(W, p[1]) and has(W.status(), "Nameplates: on, 3 styled"), W.status())
		check("page switched on later: one hook on the driver and none on a unit frame", NP.hooksOn(W, { uf = W.env.NamePlateDriverFrame }) == 1 and NP.hooksOn(W, p[1]) == 0 and NP.hooksOn(W, p[2]) == 0 and NP.hooksOn(W, p[3]) == 0)
		local styled = W.npSnapAll()
		local madeFrames, madeTextures = #W.addonFrames, #W.addonTextures
		local from = #W.npLog
		W.change("nameplates.enabled", false)
		W.flush()
		check("page switched off again: Blizzard's look is back exactly", W.npSnapAll() == ref.npSnapAll(), W.npSnapAll():sub(1, 300))
		check("page switched off again: no class icon and no border of the addon's is shown", not NP.shownIcon(W, p[1]) and NP.iconOf(W, p[1]).look.state == "hb" and W.state(p[1].hb) == "hb" and W.state(p[1].level) == "hb" and W.state(p[1].cast) == "hb")
		check("page switched off again: the art alphas are Blizzard's", plateLine(W, p[2]) == "bg=1 sel=1 over=1 | lvl=1,1 | cast=1,1 | H:hb L:hb C:hb", plateLine(W, p[2]))
		local off = #W.npLog
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 5)
		W.fire("UNIT_FACTION", "nameplate1")
		W.fire("GROUP_ROSTER_UPDATE")
		W.flush()
		check("page off again: Blizzard's passes and events make the addon call nothing on the plates", #NP.calls(W, nil, nil, true, off) == 0 and W.npSnapAll() == ref.npSnapAll(), NP.callsText(NP.calls(W, nil, nil, true, off)):sub(1, 200))
		W.change("nameplates.enabled", true)
		W.flush()
		check("page on again: styled as before, nothing made twice, one hook on the driver and none on a unit frame", W.npSnapAll() == styled and #W.addonFrames == madeFrames and #W.addonTextures == madeTextures
			and NP.hooksOn(W, { uf = W.env.NamePlateDriverFrame }) == 1 and NP.hooksOn(W, p[1]) == 0 and NP.hooksOn(W, p[2]) == 0 and NP.hooksOn(W, p[3]) == 0, #W.addonFrames - madeFrames)
		clean(W, "page switch")
	end

	-- 75l2. Everything off and on again changes the plates back and forth exactly.
	do
		local ref = NP.twinOff()
		NP.threePlates(ref)
		local W = NP.npWorld()
		W.npAllow = true
		local p = NP.threePlates(W)
		-- Every setting of the page that changes a look, away from the default.
		for _, change in ipairs({ { "healthFlat", false }, { "healthHeight", 150 }, { "nameSize", 150 }, { "nameOutline", false }, { "healthText", false }, { "healthTextSize", 120 },
			{ "healthTextOutline", false }, { "levelSize", 130 }, { "castHeight", 200 }, { "classFriendly", true }, { "classPosition", "Above" }, { "classSize", 30 }, { "classBorder", false } }) do
			W.change("nameplates." .. change[1], change[2])
		end
		W.flush()
		local away = W.npSnapAll()
		W.change("nameplates.enabled", false)
		W.flush()
		check("every setting changed and the page off: Blizzard's look exactly", W.npSnapAll() == ref.npSnapAll(), W.npSnapAll():sub(1, 400))
		W.change("nameplates.enabled", true)
		W.flush()
		check("every setting changed and the page on again: the same look as before it was switched off", W.npSnapAll() == away)
		W.ns.Try("nameplates", function() error("a failure in the module", 0) end)
		W.flush()
		check("every setting changed and the module stopped: Blizzard's look exactly", W.npSnapAll() == ref.npSnapAll(), W.npSnapAll():sub(1, 400))
		check("every setting changed and the module stopped: no class icon is shown", not NP.shownIcon(W, p[1]) and not NP.shownIcon(W, p[3]))
		local mark = #W.npLog
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 3)
		W.units.target = p[2].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.npShow("nameplate9", { player = true, friend = false, class = "MAGE" })
		W.flush()
		check("module stopped: Blizzard's passes, events and new plates make the addon call nothing", #NP.calls(W, nil, nil, true, mark) == 0, NP.callsText(NP.calls(W, nil, nil, true, mark)):sub(1, 200))
		check("module stopped: no error reaches the client and the other modules go on", #W.errors == 0 and #W.violations == 0 and has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Cast bars: on, 5 styled"))
	end


	-- The art alphas of a plate and which borders of the addon's are shown: a border that is hidden is the same as one never made.
	function NP.plateLook(W, F)
		local hb, lv, cb = F.hb, F.level, F.cast
		local function shown(t)
			local s = W.state(t)
			return s:sub(1, 1) == "S" and s or "off"
		end
		return ("bg=%s sel=%s over=%s | lvl=%s,%s | cast=%s,%s | H:%s L:%s C:%s"):format(g(hb.bgTexture.alpha), g(hb.selectedBorder.alpha), g(hb.deselectedOverlay.alpha),
			g(lv.playerLevelDiffIcon.alpha), g(lv.selectedBorder.alpha), g(cb.Background.alpha), g(cb.Border.alpha), shown(hb), shown(lv), shown(cb))
	end
	-- Everything visible about the plates of a world: Blizzard's parts, the art alphas and borders, and the class icon.
	function NP.lookAll(W, p)
		local out = {}
		for i, F in ipairs(p) do
			local I = NP.iconOf(W, F)
			out[i] = F.id .. " " .. W.npSnap(F) .. " | " .. NP.plateLook(W, F) .. " | "
				.. (I and I.art.shown and (I.art.atlas .. "," .. I.look.state .. "," .. NP.iconPlace(W, F)) or "no icon shown")
		end
		return table.concat(out, "\n")
	end
	-- Three plates, with a target and a focus, in a world that lets bars be resized.
	function NP.sceneWorld(saved)
		local W = NP.npWorld(saved and { saved = { options = saved } } or nil)
		W.npAllow = true
		local p = NP.threePlates(W)
		W.units.target, W.units.focus = p[1].plate, p[3].plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.fire("PLAYER_FOCUS_CHANGED")
		W.flush()
		return W, p
	end

	-- 75m. Every setting, changed through its control: on, off and on again, and Blizzard's look exactly when it is back.
	do
		local probes = {
			{ "healthFlat", false }, { "healthHeight", 150 }, { "healthHeight", 50 }, { "nameSize", 150 }, { "nameSize", 50 }, { "nameOutline", false }, { "healthText", false },
			{ "healthTextSize", 100 }, { "healthTextSize", 200 }, { "healthTextOutline", false }, { "levelSize", 150 }, { "levelSize", 50 }, { "castHeight", 200 }, { "castHeight", 50 },
			{ "classEnemy", false }, { "classFriendly", true }, { "classPosition", "Right", "right" }, { "classPosition", "Above", "above" }, { "classPosition", "Below", "below" },
			{ "classFit", "Custom", "own" }, { "classGap", 3 }, { "levelShape", "Game width", "game" }, { "levelGap", 3 },
			{ "classSize", 32, nil, { "classFit", "Custom", "own" } }, { "classSize", 8, nil, { "classFit", "Custom", "own" } }, { "classX", 10 }, { "classY", -10 }, { "classBorder", false },
			{ "level", "Text only", "text" }, { "level", "Default", "default" },
		}
		local labels = { classPosition = "Left", level = "Thin border", classFit = "Health bar height", levelShape = "Square" }
		for _, probe in ipairs(probes) do
			local key, value, stored = probe[1], probe[2], probe[3] or probe[2]
			local path = "nameplates." .. key
			local default = labels[key] or ROW[path].default
			-- The world starts with the three settings that are off in a fresh install switched on.
			if NP.FLAT[path] ~= nil then
				default = NP.FLAT[path]
			end
			local pre = probe[4]
			local W, p = NP.sceneWorld(pre and { ["nameplates." .. pre[1]] = pre[3] } or nil)
			local base = NP.lookAll(W, p)
			W.change(path, value)
			W.flush()
			local changed = NP.lookAll(W, p)
			check(path .. " " .. tostring(value) .. ": the plates change", changed ~= base)
			W.npOptions()
			W.npCVar("nameplateDebuffPadding", 9)
			W.flush()
			check(path .. " " .. tostring(value) .. ": Blizzard's passes leave the plates as the setting has them", NP.lookAll(W, p) == changed)
			W.change(path, default)
			W.flush()
			local back = NP.lookAll(W, p)
			check(path .. " " .. tostring(value) .. ": back to the default gives the plates as they were, to the last value", back == base, back ~= base and (back .. "\n" .. base):sub(1, 600) or "")
			W.change(path, value)
			W.flush()
			check(path .. " " .. tostring(value) .. ": and on again gives the same as the first time", NP.lookAll(W, p) == changed)
			local savedMap = { [path] = stored }
			if pre then
				savedMap["nameplates." .. pre[1]] = pre[3]
			end
			local R, rp = NP.sceneWorld(savedMap)
			check(path .. " " .. tostring(value) .. ": saved with that value, the plates are as they are when it is changed live", NP.lookAll(R, rp) == changed)
			check(path .. " " .. tostring(value) .. ": no violation, error or message", #W.violations == 0 and #W.errors == 0 and #W.out == 0 and #R.violations == 0, table.concat(W.violations, "|"))
		end
	end

	-- 75n. Dependencies: what is greyed and what is usable, as the controls show them.
	do
		local W = NP.npWorld()
		local function mismatches()
			local list = {}
			for _, row in ipairs(ALL) do
				if row.page == "nameplates" and W.enabled(row.path) ~= usable(W, row) then
					list[#list + 1] = row.path .. (usable(W, row) and " should be usable" or " should be greyed")
				end
			end
			return table.concat(list, "; ")
		end
		local function on(...)
			for _, key in ipairs({ ... }) do
				if not W.enabled("nameplates." .. key) then
					return false
				end
			end
			return true
		end
		local function off(...)
			for _, key in ipairs({ ... }) do
				if W.enabled("nameplates." .. key) then
					return false
				end
			end
			return true
		end
		check("needs: at the defaults every control of the page is usable", mismatches() == "" and on("healthTextSize", "healthTextOutline", "castBackdrop", "classEnemy", "classBorder", "targetColour"), mismatches())
		W.change("nameplates.healthText", false)
		check("needs: health text off greys its size and outline and nothing else", off("healthTextSize", "healthTextOutline") and on("nameSize", "nameOutline", "healthText", "levelSize", "classEnemy", "healthFlat") and mismatches() == "", mismatches())
		W.change("nameplates.healthText", true)
		check("needs: health text on again makes them usable", on("healthTextSize", "healthTextOutline") and mismatches() == "")
		W.change("nameplates.cast", false)
		check("needs: the cast bar border off greys its background and not the flat fill or the height", off("castBackdrop") and on("castFlat", "castHeight", "cast") and mismatches() == "", mismatches())
		W.change("nameplates.cast", true)
		W.change("nameplates.health", false)
		check("needs: the health border off greys its background, dim, the target border and the target settings, and not the flat bar, the height, text, level or class icons",
			off("healthBackdrop", "dim", "target", "targetColour", "focusColour", "targetThickness") and on("healthFlat", "healthHeight", "nameSize", "healthText", "level", "levelSize", "castFlat", "classEnemy", "classBorder", "auras") and mismatches() == "", mismatches())
		W.change("nameplates.health", true)
		W.change("nameplates.classEnemy", false)
		W.change("nameplates.classFriendly", false)
		check("needs: the class icon controls are all usable whichever of the two switches is on", on("classEnemy", "classFriendly", "classPosition", "classFit", "classGap", "classX", "classY", "classBorder") and off("classSize") and mismatches() == "")
		W.change("nameplates.classEnemy", true)
		W.change("nameplates.enabled", false)
		check("needs: the page switch off greys every other control of the page, class icons included, and not its own", off("health", "healthFlat", "healthHeight", "nameSize", "nameOutline", "healthText", "healthTextSize", "levelSize", "castFlat", "castHeight",
			"classEnemy", "classFriendly", "classPosition", "classFit", "classSize", "classGap", "classX", "classY", "classBorder", "level", "levelShape", "levelGap", "auras") and on("enabled") and mismatches() == "" and W.enabled("general.thickness"), mismatches())
		W.change("nameplates.enabled", true)
		check("needs: and on again makes them usable", mismatches() == "" and on("classFit", "healthTextSize"))
		clean(W, "needs")
	end

	-- 75o. Settings saved by version 0.1.0 and by version 0.2.0 load unchanged.
	do
		-- Version 0.1.0 saved the switches at the top level.
		local W = NP.npWorld({ saved = { nameplates = false, actionbars = true, thickness = 2 } }, { defaults = true })
		local options = W.options()
		check("saved by 0.1.0: the switch and the thickness are read into the options and the old keys are gone", W.ns.Get("nameplates.enabled") == false and W.ns.Get("general.thickness") == 2
			and options["nameplates.enabled"] == false and W.env.FlatUIDB.nameplates == nil and W.env.FlatUIDB.thickness == nil)
		local fresh = {}
		for _, row in ipairs(ALL) do
			if row.page == "nameplates" and row.path ~= "nameplates.enabled" then
				fresh[#fresh + 1] = ((W.ns.Get(row.path) == row.default) and "" or row.path .. " ") .. ((W.ns.IsSet(row.path)) and (row.path .. " set ") or "")
			end
		end
		check("saved by 0.1.0: every setting added since is at its default and not saved", table.concat(fresh) == "", table.concat(fresh))
		local p = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		check("saved by 0.1.0 with the nameplates off: the plate is Blizzard's", NP.fillText(p) == NP.BAR_ATLAS .. "|nil|-" and NP.shownIcon(W, p) == false and NP.hooksOn(W, p) == 0 and #NP.mine(W, p, 0) == 0)
		local V = NP.npWorld({ saved = { nameplates = true, thickness = 3 } }, { defaults = true })
		local v = V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		V.flush()
		check("saved by 0.1.0 with the nameplates on: the new defaults apply", NP.fillText(v) == "nil|nil|1,1,1,1" and near(v.textr.textHeight, 11.2) and NP.shownIcon(V, v) and V.ns.Get("general.thickness") == 3)

		-- Version 0.2.0 saved every setting of the page as it had it.
		local saved = {
			["nameplates.enabled"] = true, ["nameplates.health"] = false, ["nameplates.healthBackdrop"] = false, ["nameplates.dim"] = true, ["nameplates.target"] = false,
			["nameplates.targetColour"] = "ff112233", ["nameplates.focusColour"] = "ff445566", ["nameplates.targetThickness"] = 3, ["nameplates.level"] = "default",
			["nameplates.cast"] = false, ["nameplates.castBackdrop"] = false, ["nameplates.auras"] = false, ["general.thickness"] = 2, ["general.border"] = "ff336699",
		}
		local copy = {}
		for k, val in pairs(saved) do
			copy[k] = val
		end
		local S = NP.npWorld({ saved = { options = saved } }, { defaults = true })
		local same = true
		for k, val in pairs(copy) do
			same = same and S.ns.Get(k) == val and S.options()[k] == val
		end
		local extra = {}
		for k in pairs(S.options()) do
			if copy[k] == nil then
				extra[#extra + 1] = k
			end
		end
		check("saved by 0.2.0: every setting is read as it was saved, and nothing is added to the saved options", same and #extra == 0, table.concat(extra, " "))
		local fresh2 = {}
		for _, key in ipairs({ "healthFlat", "healthHeight", "nameSize", "nameOutline", "healthText", "healthTextSize", "healthTextOutline", "levelSize", "castFlat", "castHeight", "classEnemy", "classFriendly",
			"classPosition", "classSize", "classX", "classY", "classBorder" }) do
			local row = ROW["nameplates." .. key]
			if S.ns.Get(row.path) ~= row.default or S.ns.IsSet(row.path) then
				fresh2[#fresh2 + 1] = key
			end
		end
		check("saved by 0.2.0: the seventeen settings added since are at their defaults and not saved", #fresh2 == 0, table.concat(fresh2, " "))
		local q = S.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		S.flush()
		check("saved by 0.2.0: the plate looks as the saved settings say, with the new defaults", plateLine(S, q) == "bg=1 sel=1 over=1 | lvl=1,1 | cast=1,1 | H:. L:. C:." and NP.fillText(q) == "nil|nil|1,1,1,1"
			and near(q.textr.textHeight, 11.2) and NP.shownIcon(S, q), plateLine(S, q))
		clean(S, "saved by 0.2.0")

		-- Values of the new settings that are not valid are put right when they load.
		local bad = NP.npWorld({ saved = { options = { ["nameplates.classPosition"] = "diagonal", ["nameplates.healthHeight"] = 999, ["nameplates.nameSize"] = 52, ["nameplates.classSize"] = 2,
			["nameplates.classX"] = "5", ["nameplates.castHeight"] = 5, ["nameplates.healthFlat"] = "yes", ["nameplates.classY"] = -75, ["nameplates.levelSize"] = 101 } } }, { defaults = true })
		check("saved with values that are not valid: each goes to its range, its step or its default", bad.ns.Get("nameplates.classPosition") == "left" and bad.ns.Get("nameplates.healthHeight") == 200 and bad.ns.Get("nameplates.nameSize") == 50
			and bad.ns.Get("nameplates.classSize") == 8 and bad.ns.Get("nameplates.classX") == 0 and bad.ns.Get("nameplates.castHeight") == 50 and bad.ns.Get("nameplates.healthFlat") == true
			and bad.ns.Get("nameplates.classY") == -60 and bad.ns.Get("nameplates.levelSize") == 100, bad.ns.Get("nameplates.nameSize") .. " " .. bad.ns.Get("nameplates.levelSize"))
	end


	function NP.newPlateFor(W, unit, info, o)
		local F = W.npFrame(o)
		W.npAdd(W.npPlate(), F, unit, info, o)
		return F
	end
	-- The lines /flatui status gives for the module: its own line and the notes under it.
	function NP.moduleLines(W)
		local lines, inside = {}, false
		for line in (W.status() .. "\n"):gmatch("([^\n]*)\n") do
			if line:find("^Nameplates:") then
				inside = true
			elseif line:find("^Combat text:") or line:find("^Action bars:") or line:find("^Personal resource display:") then
				inside = false
			end
			if inside then
				lines[#lines + 1] = line
			end
		end
		return lines
	end

	-- 75p. Combat: what is allowed happens at once, what is not waits.
	do
		local W = NP.npWorld({ combat = true })
		W.change("nameplates.healthHeight", 150)
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local n = W.npShow("nameplate2", { player = false, friend = false })
		W.flush()
		check("combat: a plate that appears in combat is styled at once: the flat fill, the text, the borders and the class icon", NP.fillText(e) == "nil|nil|1,1,1,1" and near(e.textr.textHeight, 11.2) and NP.shownIcon(W, e)
			and plateLine(W, e) == ON and W.state(e.level) == "SB", plateLine(W, e))
		check("combat: the driver is followed in combat, and no unit frame", NP.hooksOn(W, { uf = W.env.NamePlateDriverFrame }) == 1 and NP.hooksOn(W, e) == 0 and NP.hooksOn(W, n) == 0)
		check("combat: its bar height waits, and the status says so", near(e.hcr.height, 13) and #NP.calls(W, nil, "SetHeight", true) == 0 and count(W.status(), "Bar height: nameplates that appear in combat get their height when combat ends.") == 1, W.status())
		W.change("nameplates.nameSize", 150)
		W.change("nameplates.nameOutline", false)
		W.change("nameplates.levelSize", 120)
		W.change("nameplates.classFit", "Custom")
		W.change("nameplates.classSize", 30)
		W.change("nameplates.classPosition", "Left")
		W.change("nameplates.healthFlat", false)
		check("combat: text, class icon and fill settings changed in combat are applied at once", NP.stateOf(e.namer) == NP.PLAIN .. "/21" and near(e.lTextr.textHeight, 12) and NP.iconPlace(W, e) == "RIGHT guide LEFT 0,0 30x30 n1" and NP.fillText(e) == NP.BAR_ATLAS .. "|nil|-")
		W.npOptions()
		W.flush()
		check("combat: Blizzard's pass in combat leaves them as set", NP.stateOf(e.namer) == NP.PLAIN .. "/21" and near(e.hcr.height, 13))
		W.change("nameplates.healthFlat", true)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: the held back height is set on both plates and nothing else changes", near(e.hcr.height, 19.5) and near(n.hcr.height, 19.5) and NP.stateOf(e.namer) == NP.PLAIN .. "/21" and NP.fillText(e) == "nil|nil|1,1,1,1")
		clean(W, "combat")
	end

	-- 75q. Forbidden frames: skipped and never read.
	do
		local W = NP.npWorld()
		W.npAllow = true
		local forbidden = W.npShow("nameplate1", { player = true, friend = true, class = "MAGE" }, { forbid = {} , forbidden = true })
		local normal = W.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
		W.change("nameplates.classFriendly", true)
		W.change("nameplates.healthHeight", 150)
		W.change("nameplates.nameSize", 150)
		W.change("nameplates.healthFlat", false)
		W.change("nameplates.healthFlat", true)
		W.change("nameplates.enabled", false)
		W.change("nameplates.enabled", true)
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 3)
		W.npFaction(forbidden, false)
		W.fire("UNIT_NAME_UPDATE", "nameplate1")
		W.fire("GROUP_ROSTER_UPDATE")
		W.fire("ADDON_RESTRICTION_STATE_CHANGED")
		W.units.target = forbidden.plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("forbidden unit frame: nothing of it is read at any step, however the options, events and passes go", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "):sub(1, 300))
		check("forbidden unit frame: nothing is made, hooked or called on it, and the plate beside it is styled", NP.hooksOn(W, forbidden) == 0 and #NP.mine(W, forbidden, 0) == 0 and NP.iconOf(W, forbidden) == nil
			and NP.hooksOn(W, normal) == 0 and NP.shownIcon(W, normal) and near(normal.hcr.height, 19.5))
		check("forbidden unit frame: it is not counted", has(W.status(), "Nameplates: on, 1 styled"), W.status())
		check("forbidden unit frame: the class of its unit is never asked for", W.npUnitCalls.nameplate1 == nil, tostring(W.npUnitCalls.nameplate1))

		-- A forbidden part of an allowed unit frame is not read either.
		local list = {}
		for _, part in ipairs({ "hc", "cc", "cast", "level" }) do
			local V = NP.npWorld()
			V.npAllow = true
			V.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, { forbid = { part } })
			V.change("nameplates.classSize", 22)
			V.change("nameplates.healthHeight", 150)
			V.change("nameplates.levelSize", 130)
			V.flush()
			if #V.violations > 0 then
				list[#list + 1] = part .. ": " .. V.violations[1]
			end
		end
		check("forbidden parts of an allowed unit frame (the health container, the cast container, the cast bar, the level frame): none is read", #list == 0, table.concat(list, "; "))
	end

	-- 75r. Values the client withholds, at every read the new code makes.
	do
		local function run(label, setup)
			local W = NP.npWorld()
			W.npAllow = true
			local p = {}
			for i = 1, 3 do
				p[i] = W.npShow("nameplate" .. i, { player = true, friend = false, class = NP.CLASSES[i] })
				p[i].healthText("both")
			end
			W.flush()
			setup(W, p)
			W.change("nameplates.classPosition", "Above")
			W.change("nameplates.classSize", 22)
			W.change("nameplates.nameSize", 150)
			W.change("nameplates.nameOutline", false)
			W.change("nameplates.healthTextSize", 120)
			W.change("nameplates.healthTextOutline", false)
			W.change("nameplates.levelSize", 130)
			W.change("nameplates.healthHeight", 150)
			W.change("nameplates.castHeight", 200)
			W.change("nameplates.healthFlat", false)
			W.change("nameplates.healthFlat", true)
			W.change("nameplates.level", "Default")
			W.change("nameplates.level", "Thin border")
			W.fire("UNIT_NAME_UPDATE", "nameplate1")
			W.fire("UNIT_FACTION", "nameplate2")
			W.fire("GROUP_ROSTER_UPDATE")
			W.fire("CVAR_UPDATE", "nameplateStyle", "1")
			W.flush()
			check("withheld: " .. label .. ": no error, no broken rule, no part stopped and no plate failed", #W.errors == 0 and #W.violations == 0 and not has(W.status(), "stopped") and not has(W.status(), "failed"),
				W.status() .. " | " .. table.concat(W.violations, " | "):sub(1, 200))
			return W, p
		end
		-- A secret keeps the type of what it hides, so each is tried with the type of the value it stands for.
		local function typed(label, secretType, setup)
			return run(label .. " (a secret " .. secretType .. ")", function(W, p)
				W.secretType = secretType
				setup(W, p)
			end)
		end
		typed("the unit", "string", function(W, p) for _, F in ipairs(p) do F.u.unit = SECRET end end)
		typed("isPlayer", "boolean", function(W, p) for _, F in ipairs(p) do F.u.isPlayer = SECRET end end)
		typed("isFriend", "boolean", function(W, p) for _, F in ipairs(p) do F.u.isFriend = SECRET end end)
		typed("widgetsOnlyMode", "boolean", function(W, p) for _, F in ipairs(p) do F.u.widgetsOnlyMode = SECRET end end)
		typed("showOnlyName", "boolean", function(W, p) for _, F in ipairs(p) do F.u.showOnlyName = SECRET end end)
		typed("the class", "string", function(W, p) for _, F in ipairs(p) do F.info.class = "secret" end end)
		typed("the name", "table", function(W, p) for _, F in ipairs(p) do F.u.name = SECRET end end)
		typed("the health text", "table", function(W, p) for _, F in ipairs(p) do F.hbr.Text, F.hbr.LeftText, F.hbr.RightText = SECRET, SECRET, SECRET end end)
		typed("the level text", "table", function(W, p) for _, F in ipairs(p) do F.levelr.playerLevelDiffText = SECRET end end)
		typed("the fill", "table", function(W, p) for _, F in ipairs(p) do F.hbr.barTexture = SECRET end end)
		typed("the bar colour", "number", function(W, p) for _, F in ipairs(p) do F.hbr.barColor = { SECRET, SECRET, SECRET, SECRET } end end)
		typed("the follow function", "table", function(W, p) for _, F in ipairs(p) do F.u.UpdateAnchors = SECRET end end)
		local KINDS = { spellNameInsideCastBar = "boolean", useClassicHealthBar = "boolean", useClassicCastBar = "boolean", useOutlinedFontWhenAboveHealthBar = "boolean" }
		for _, key in ipairs({ "healthBarHeight", "castBarHeight", "castIconHeight", "healthBarFontHeight", "levelFontHeight", "healthBarToNameAboveSpacing", "unitNameAnchorStyle",
			"spellNameInsideCastBar", "useClassicHealthBar", "useClassicCastBar", "useOutlinedFontWhenAboveHealthBar" }) do
			typed("the option " .. key, KINDS[key] or "number", function(W) W.env.NamePlateSetupOptions[key] = SECRET end)
		end
		run("the style names", function(W) W.env.NamePlateConstants.NAME_ANCHOR_STYLES = SECRET end)
		run("all style names", function(W) W.env.NamePlateConstants = SECRET end)
		run("the answer of CheckAllowProtectedFunctions", function(W) W.npCheckFault = "secret" end)
		run("the answer about the atlas", function(W) W.npAtlases["classicon-mage"], W.npAtlases["classicon-priest"] = "secret", "secret" end)
		run("the colour through the getter in part", function(W, p) for _, F in ipairs(p) do F.hbr.barColor = { 0.5, SECRET, 0.5, 1 } end end)
		-- The levels of the frames themselves: the container, the level frame and the cast container.
		local list = {}
		for _, part in ipairs({ "HealthBarsContainer", "PlayerLevelDiffFrame", "CastBarsContainer" }) do
			local W = NP.npWorld()
			W.npAllow = true
			W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, { secret = { part } })
			W.change("nameplates.classSize", 22)
			W.change("nameplates.healthHeight", 150)
			W.flush()
			if has(W.status(), "failed") or #W.errors > 0 then
				list[#list + 1] = part
			end
		end
		check("withheld: the health container, the level frame and the cast container are not indexed", #list == 0, table.concat(list, ", "))
	end


	-- 75s. A part that fails on three plates stops alone, and puts Blizzard's look back on every plate.
	do
		local PARTS = {
			{
				part = "bar fill", error = "SetStatusBarColor failed",
				settings = {},
				fault = function(W, F) F.hbr.setColorFault = true end,
				styled = function(W, F) return NP.fillText(F) == "nil|nil|1,1,1,1" end,
				restored = function(W, F) return NP.fillText(F) == NP.BAR_ATLAS .. "|nil|-" end,
				other = function(W, F) return NP.shownIcon(W, F) and near(F.textr.textHeight, 11.2) end,
			},
			{
				part = "bar height", error = "SetHeight failed",
				settings = { { "healthHeight", 150 }, { "castHeight", 200 } },
				fault = function(W, F) F.castr.heightFault = true end,
				styled = function(W, F) return near(F.hcr.height, 19.5) and near(F.castr.height, 12) and near(F.ccr.height, 22) end,
				restored = function(W, F) return near(F.hcr.height, 13) and near(F.ccr.height, 16) and near(F.castr.height, 6) end,
				other = function(W, F) return NP.shownIcon(W, F) and near(F.textr.textHeight, 11.2) and NP.fillText(F) == "nil|nil|1,1,1,1" end,
			},
			{
				part = "text", error = "SetTextHeight failed",
				settings = { { "nameSize", 150 }, { "levelSize", 130 }, { "healthTextSize", 120 } },
				fault = function(W, F) F.rightr.textFault = true end,
				styled = function(W, F) return NP.stateOf(F.namer) == NP.OUTLINED .. "/21" and NP.stateOf(F.textr) == NP.OUTLINED .. "/16.8" and near(F.lTextr.textHeight, 13) end,
				restored = function(W, F) return NP.stateOf(F.namer) == NP.OUTLINED .. "/14" and NP.stateOf(F.textr) == NP.OUTLINED .. "/14" and NP.stateOf(F.leftr) == NP.OUTLINED .. "/14" and NP.stateOf(F.rightr) == NP.OUTLINED .. "/14"
					and near(F.lTextr.textHeight, 10) end,
				other = function(W, F) return NP.shownIcon(W, F) and NP.fillText(F) == "nil|nil|1,1,1,1" end,
			},
			{
				part = "class icons", error = "CreateFrame failed",
				settings = {},
				fault = function(W, F) W.npCreateFault = W.npCreateFault or {}; W.npCreateFault[F.uf] = true end,
				styled = function(W, F) return NP.shownIcon(W, F) end,
				restored = function(W, F) return not NP.shownIcon(W, F) end,
				other = function(W, F) return NP.fillText(F) == "nil|nil|1,1,1,1" and near(F.textr.textHeight, 11.2) end,
			},
		}
		for _, spec in ipairs(PARTS) do
			local W = NP.npWorld()
			W.npAllow = true
			for _, s in ipairs(spec.settings) do
				W.change("nameplates." .. s[1], s[2])
			end
			local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
			local b = W.npShow("nameplate2", { player = true, friend = false, class = "ROGUE" })
			W.flush()
			local label = "part '" .. spec.part .. "'"
			check(label .. " failing: the plates are styled before anything fails", spec.styled(W, a) and spec.styled(W, b))
			local bad = {}
			local function addBad(i)
				bad[i] = W.npFrame()
				spec.fault(W, bad[i])
				W.npAdd(W.npPlate(), bad[i], "nameplate" .. (2 + i), { player = true, friend = false, class = NP.CLASSES[2 + i] })
				W.flush()
			end
			local function stoppedLines()
				return count(W.status(), spec.part .. " stopped.")
			end
			addBad(1)
			for _ = 1, 5 do
				W.npOptions()
				W.npCVar("nameplateDebuffPadding", 2)
			end
			W.flush()
			check(label .. " failing: one plate that fails however often it is tried is one failure, and the part goes on", stoppedLines() == 0 and spec.styled(W, a))
			addBad(2)
			check(label .. " failing: two plates are not enough to stop it", stoppedLines() == 0 and spec.styled(W, b))
			addBad(3)
			W.flush()
			check(label .. " failing: the third plate stops it with one line in the status that has the first error", stoppedLines() == 1 and has(W.status(), "Nameplates: " .. spec.part .. " stopped. " .. spec.error), W.status())
			check(label .. " failing: the module goes on, and the other parts and the other modules with it", has(W.status(), "Nameplates: on,") and not has(W.status(), "Nameplates: stopped") and spec.other(W, a)
				and has(W.status(), "Action bars: on, 118 styled") and #W.errors == 0 and #W.violations == 0, W.status())
			check(label .. " failing: Blizzard's look is back for that part on the plates that were styled before, without waiting for Blizzard to lay them out again", spec.restored(W, a) and spec.restored(W, b), W.npSnap(a))
			check(label .. " failing: and on the plates where it failed", spec.restored(W, bad[1]) and spec.restored(W, bad[2]) and spec.restored(W, bad[3]), W.npSnap(bad[1]))
			for _ = 1, 3 do
				W.npOptions()
			end
			W.flush()
			check(label .. " failing: after Blizzard lays the plates out again it is still Blizzard's look, and still one line", spec.restored(W, a) and spec.restored(W, bad[1]) and stoppedLines() == 1)
			local late = NP.newPlateFor(W, "nameplate9", { player = true, friend = false, class = "PRIEST" })
			W.flush()
			check(label .. " failing: a plate added after it stopped has Blizzard's look for that part, and the rest styled", spec.restored(W, late) and spec.other(W, late))
		end
	end

	-- 75s2. A frame that fails is skipped and counted once; five frames stop the module and Blizzard's look comes back.
	do
		local ref = NP.twinOff()
		local good = { ref.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }), ref.npShow("nameplate2", { player = false, friend = false }) }
		local W = NP.npWorld(nil, { castFill = true })
		W.npAllow = true
		W.change("nameplates.healthHeight", 150)
		W.change("nameplates.nameSize", 150)
		W.change("nameplates.healthTextOutline", false)
		W.change("nameplates.levelSize", 130)
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local b = W.npShow("nameplate2", { player = false, friend = false })
		local function broken(i)
			local F = W.npFrame()
			F.hbr.CreateTexture = function() error("CreateTexture failed", 0) end
			W.npAdd(W.npPlate(), F, "nameplate" .. (2 + i), { player = true, friend = false, class = "ROGUE" })
			return F
		end
		local x = broken(1)
		for _ = 1, 6 do
			W.units.target = a.plate
			W.fire("PLAYER_TARGET_CHANGED")
			W.npOptions()
			W.change("nameplates.dim", false)
			W.flush()
		end
		check("a frame that fails: skipped and counted once however often it is tried", has(W.status(), "Nameplates: on, 2 styled, 1 failed. CreateTexture failed"), W.status())
		check("a frame that fails: the others are styled and the failing one is untouched", NP.stateOf(a.namer) == NP.OUTLINED .. "/21" and near(a.hcr.height, 19.5) and #NP.mine(W, x, 0) == 0 and NP.fillText(x) == NP.BAR_ATLAS .. "|nil|-")
		broken(2)
		check("a frame that fails: two are two", has(W.status(), "2 failed"), W.status())
		broken(3)
		broken(4)
		check("a frame that fails: four are four, and the module goes on", has(W.status(), "4 failed") and not has(W.status(), "stopped"), W.status())
		broken(5)
		W.flush()
		check("five frames that fail stop the module, with the first error in the status", has(W.status(), "Nameplates: stopped. CreateTexture failed"), W.status())
		check("module stopped: the one line in the chat names the module", #W.out == 1 and W.out[1] == "Flat UI: Nameplates stopped. /flatui status shows why. Type /reload if the look is left half changed.", table.concat(W.out, "|"))
		check("module stopped: Blizzard's look is back on the plates that were styled", W.npSnap(a) == ref.npSnap(good[1]), W.npSnap(a) .. "\n" .. ref.npSnap(good[1]))
		check("module stopped: and on the other one", W.npSnap(b) == ref.npSnap(good[2]))
		check("module stopped: no class icon, no border and the art as Blizzard draws it", not NP.shownIcon(W, a) and plateLine(W, a) == "bg=1 sel=1 over=1 | lvl=1,1 | cast=1,1 | H:hb L:hb C:hb", plateLine(W, a))
		check("module stopped: other modules are untouched", has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Swing timers: on, 3 styled") and has(W.status(), "Cast bars: on, 5 styled"))
		local mark = #W.npLog
		W.npShow("nameplate20", { player = true, friend = false, class = "MAGE" })
		W.npOptions()
		W.flush()
		check("module stopped: later plates and passes are not touched", #NP.calls(W, nil, nil, true, mark) == 0)
		check("module stopped: no error reaches the client", #W.errors == 0 and #W.violations == 0)
	end

	-- 75t. A client that lacks something the additions use.
	do
		-- No hooksecurefunc at all.
		local W = NP.npWorld()
		W.env.hooksecurefunc = nil
		W.npAllow = true
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		check("no hooksecurefunc: the plate is styled once at the start, and nothing says that sizes can reset while nothing has changed them", NP.fillText(a) == "nil|nil|1,1,1,1" and NP.shownIcon(W, a)
			and #W.errors == 0 and #W.violations == 0)
		W.change("nameplates.nameSize", 150)
		check("no hooksecurefunc: a size changed makes the status say that sizes can reset, once", count(W.status(), "Nameplates: sizes can go back to the default when the game lays a nameplate out again.") == 1, W.status())
		check("no hooksecurefunc: and the rest goes on", near(a.namer.textHeight, 21) and not has(W.status(), "stopped"))

		-- A driver without UpdateNamePlateOptions.
		local U = NP.npWorld()
		U.npAllow = true
		local f = U.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, { quiet = true })
		U.env.NamePlateDriverFrame.UpdateNamePlateOptions = nil
		U.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
		U.change("nameplates.healthHeight", 150)
		U.flush()
		check("no UpdateNamePlateOptions on the driver: not followed, styled once, and the status says that sizes can reset", NP.hooksOn(U, f) == 0 and near(f.hcr.height, 19.5) and NP.shownIcon(U, f)
			and count(U.status(), "Nameplates: sizes can go back to the default when the game lays a nameplate out again.") == 1 and #U.errors == 0 and #U.violations == 0, U.status())
		U.change("nameplates.enabled", false)
		U.change("nameplates.enabled", true)
		check("no UpdateNamePlateOptions on the driver: switching the page keeps asking nothing more of it", NP.hooksOn(U, f) == 0 and #U.errors == 0)

		-- No UnitClassBase: no class icon and no error.
		local K = NP.npWorld(nil, { without = { "UnitClassBase" } })
		local k = K.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		K.change("nameplates.classSize", 22)
		K.fire("UNIT_NAME_UPDATE", "nameplate1")
		K.flush()
		check("no UnitClassBase: no class icon, the rest of the plate is styled and nothing stops", not NP.shownIcon(K, k) and NP.fillText(k) == "nil|nil|1,1,1,1" and near(k.textr.textHeight, 11.2)
			and #K.errors == 0 and #K.violations == 0 and not has(K.status(), "stopped") and not has(K.status(), "failed"), K.status())

		-- No C_Timer: what waits for the next frame is done at once, and nothing stops.
		local Q = NP.npWorld()
		Q.flush()
		Q.env.C_Timer = nil
		Q.npAllow = true
		local qa = Q.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local qb = Q.npShow("nameplate2", { player = true, friend = true, class = "PRIEST" })
		Q.units.target = qa.plate
		Q.fire("PLAYER_TARGET_CHANGED")
		check("no C_Timer: a target change is marked at once", ringOf(Q, qa.hb, 1, 1, 1, 1) and ringOf(Q, qb.hb, 1) and #Q.timers == 0 and #Q.errors == 0 and not has(Q.status(), "stopped"), Q.status())
		check("no C_Timer: a friendly player has no class icon until the faction changes", not NP.shownIcon(Q, qb))
		Q.npFaction(qb, false)
		check("no C_Timer: and has one at once when it does", NP.shownIcon(Q, qb) and #Q.errors == 0 and not has(Q.status(), "stopped"), Q.status())
		Q.options()["nameplates.healthFlat"] = false
		Q.fire("CVAR_UPDATE", "nameplateShowAll", "1")
		check("no C_Timer: a CVar lays the plates out at once", NP.fillText(qa) == NP.BAR_ATLAS .. "|nil|-" and #Q.errors == 0 and not has(Q.status(), "stopped"), NP.fillText(qa) .. Q.status())
		Q.fire("UNIT_AURA", "nameplate1")
		check("no C_Timer: an aura change raises nothing and stops nothing", #Q.errors == 0 and #Q.violations == 0 and not has(Q.status(), "stopped") and not has(Q.status(), "failed"), Q.status())

		-- A client that cannot say whether a value is withheld.
		local I = NP.npWorld()
		I.env.issecretvalue = nil
		I.npAllow = true
		local ip = I.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		I.change("nameplates.healthHeight", 150)
		I.change("nameplates.nameSize", 150)
		I.flush()
		check("no issecretvalue: everything is done as on any client", NP.shownIcon(I, ip) and near(ip.hcr.height, 19.5) and near(ip.namer.textHeight, 21) and NP.fillText(ip) == "nil|nil|1,1,1,1" and #I.errors == 0 and #I.violations == 0
			and not has(I.status(), "stopped"))

		-- A client without the table of name styles: the name is taken to be above the bar, in the outlined font.
		local C = NP.npWorld()
		C.change("nameplates.classFit", "Custom")
		C.change("nameplates.classGap", 3)
		local c = C.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		C.env.NamePlateConstants = nil
		C.change("nameplates.nameOutline", false)
		C.change("nameplates.nameOutline", true)
		C.change("nameplates.classPosition", "Above")
		check("no NamePlateConstants: the outlined font object comes back and the icon clears the name", NP.stateOf(c.namer) == NP.OUTLINED .. "/14" and NP.iconPlace(C, c) == "BOTTOM guide TOP 0,19 20x20 n1" and #C.errors == 0 and #C.violations == 0, NP.iconPlace(C, c))

		-- A client whose health bar lacks GetStatusBarColor, and one whose strings lack SetTextHeight.
		local B = NP.npWorld()
		local plates = {}
		for i = 1, 4 do
			plates[i] = B.npShow("nameplate" .. i, { player = true, friend = false, class = NP.CLASSES[i] })
		end
		for i = 1, 3 do
			plates[i].hbr.GetStatusBarColor = nil
		end
		B.change("nameplates.healthFlat", false)
		B.change("nameplates.healthFlat", true)
		B.flush()
