			count(B.status(), "Nameplates: bar fill stopped.") == 1 and not has(B.status(), "Nameplates: stopped") and #B.errors == 0, B.status())
		check("no GetStatusBarColor on three health bars: and the icons are still shown", NP.shownIcon(B, plates[1]) and NP.shownIcon(B, plates[4]))
		check("no GetStatusBarColor on three health bars: Blizzard's fill is back on the plates that had it flat", NP.fillText(plates[4]) == NP.BAR_ATLAS .. "|nil|-" and NP.fillText(plates[1]) == NP.BAR_ATLAS .. "|nil|-", NP.fillText(plates[1]) .. " " .. NP.fillText(plates[4]))

		-- No cast bar container, no level frame, no name string, no strings of the health text: the rest is styled.
		for _, variant in ipairs({
			{ "cast bar container", { remove = { "CastBarsContainer" } } },
			{ "level frame", { remove = { "PlayerLevelDiffFrame" } } },
			{ "name", { remove = { "name" } } },
			{ "health bar container", { remove = { "HealthBarsContainer" } } },
		}) do
