			V.npAllow = true
			V.change("nameplates.healthHeight", 150)
			V.change("nameplates.castHeight", 200)
			V.change("nameplates.classPosition", "Below")
			local ps = {}
			for i = 1, 4 do
				ps[i] = V.npShow("nameplate" .. i, { player = true, friend = false, class = NP.CLASSES[i] }, variant[2])
			end
			V.flush()
