				and has(V.status(), "Nameplates: on, 4 styled"), V.status())
		end
		local V2 = NP.npWorld()
		local nb = V2.npShow("nameplate1", { player = true, friend = false, class = "MAGE" }, { remove = { "HealthBarsContainer" } })
		check("a plate without its health bar container has no class icon, since the guide needs it", not NP.shownIcon(V2, nb) and NP.iconOf(V2, nb) == nil)
	end

	-- 75u. /flatui status for the module.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		check("status: a plate, styled, is one line", table.concat(NP.moduleLines(W), "|") == "Nameplates: on, 1 styled", table.concat(NP.moduleLines(W), "|"))
		W.npAllow = false
		W.change("nameplates.healthHeight", 150)
		W.npAtlases["classicon-warlock"], W.npAtlases["groupfinder-icon-class-warlock"] = nil, nil
		W.npShow("nameplate2", { player = true, friend = false, class = "WARLOCK" })
		W.npShow("nameplate3", { player = false, friend = false }, { remove = { "HealthBarsContainer" } })
		local lines = NP.moduleLines(W)
		local expected = {
			["Nameplates: on, 3 styled"] = true,
			["Bar height: the game does not allow nameplate bars to be resized."] = true,
			["Level box: the game does not allow this on nameplates."] = true,
			["Raid marker: the game does not allow this on nameplates."] = true,
			["Class icons: no class art was found for a class, so it has no icon."] = true,
			["Level box: its border could not follow the health bar and follows the default box."] = true,
		}
		local seen = {}
		for _, line in ipairs(lines) do
			seen[line] = (seen[line] or 0) + 1
		end
		local ok = #lines == 6 and lines[1] == "Nameplates: on, 3 styled"
		for line in pairs(expected) do
			ok = ok and seen[line] == 1
		end
		check("status: the module's line and one plain line for each thing that is wrong, each once", ok, table.concat(lines, "|"))
		check("status: the same lines come out of the /flatui status command", has(W.slash("status"), "Bar height: the game does not allow nameplate bars to be resized.") and has(W.slash("status"), "Nameplates: on, 3 styled"))
		local words = true
		for _, line in ipairs(lines) do
			words = words and (line:find("^Nameplates: on") ~= nil or (line:find("%.$") ~= nil and not line:lower():find("flat ui") and not line:lower():find("addon")))
		end
		check("status: each note is one sentence that says what is wrong and where, and none names the addon", words, table.concat(lines, "|"))
		W.change("nameplates.enabled", false)
		check("status: the page off", W.line("Nameplates") == "Nameplates: off")
		check("status: no error and no broken rule", #W.errors == 0 and #W.violations == 0)
	end


	-- 75v. The font object the name and the health text go back to is the one Blizzard's rule gives for the style.
	do
		local problems = {}
		for _, style in ipairs({ NP.STYLE.Modern, NP.STYLE.Thin, NP.STYLE.Block, NP.STYLE.HealthFocus, NP.STYLE.CastFocus, NP.STYLE.Legacy, NP.STYLE.Classic }) do
			for _, flag in ipairs({ true, false }) do
				local W = NP.npWorld(nil, { style = style })
				W.env.NamePlateSetupOptions.useOutlinedFontWhenAboveHealthBar = flag
				local a = W.npShow("nameplate1", { player = false, friend = false })
				local blizzard = a.namer.fontObject
				W.change("nameplates.nameSize", 150)
				W.change("nameplates.nameSize", 100)
				W.change("nameplates.healthTextSize", 150)
				W.change("nameplates.healthTextSize", 100)
				W.change("nameplates.healthTextOutline", false)
				W.change("nameplates.healthTextOutline", true)
				W.change("nameplates.nameOutline", false)
				W.change("nameplates.nameOutline", true)
				local names = { a.namer.fontObject, a.textr.fontObject, a.leftr.fontObject, a.rightr.fontObject }
				for _, name in ipairs(names) do
					if name ~= blizzard then
						problems[#problems + 1] = "style " .. style .. " flag " .. tostring(flag) .. ": " .. name .. " instead of " .. blizzard
						break
					end
				end
			end
		end
		check("font object: after a size or an outline has been changed and put back, every style and flag gives the font object Blizzard gave", #problems == 0, table.concat(problems, "; "))
		-- A style number the rule does not know gives the plain object, as Blizzard's does.
		local U = NP.npWorld()
		U.env.NamePlateSetupOptions.unitNameAnchorStyle = 9
		local u = U.npShow("nameplate1", { player = false, friend = false }, { quiet = true })
		U.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
		u.namer.fontObject = NP.PLAIN
		U.change("nameplates.nameSize", 150)
		U.change("nameplates.nameSize", 100)
		check("font object: a style the rule does not know gives the plain object back", u.namer.fontObject == NP.PLAIN, u.namer.fontObject)
	end

	-- 75w. What the addon made is registered as its own, and the class icon art fills its frame.
	do
		local W = NP.npWorld()
		local frames, textures = #W.addonFrames, #W.addonTextures
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		W.flush()
		local missing = 0
		for i = frames + 1, #W.addonFrames do
			missing = missing + (W.ns.Own[W.addonFrames[i]] and 0 or 1)
		end
		for i = textures + 1, #W.addonTextures do
			missing = missing + (W.ns.Own[W.addonTextures[i]] and 0 or 1)
		end
		check("own frames: every frame and texture made for a plate, the class icon and the level box included, is registered as the addon's", missing == 0 and #W.addonFrames - frames >= 6, missing .. " of " .. (#W.addonFrames - frames + #W.addonTextures - textures))
		local I = NP.iconOf(W, a)
		check("class icon: the art fills the icon frame", I.art.allPoints == I.icon and #I.art.points == 0)
		check("class icon: the border is around the icon frame, not the guide", W.look(I.icon) ~= nil and W.look(I.guide) == nil)
	end

	-- 75x. The Classic style reaches the bars through either of its two flags.
	do
		for _, flag in ipairs({ "useClassicHealthBar", "useClassicCastBar" }) do
			local W = NP.npWorld()
			W.npAllow = true
