			W.env.NamePlateSetupOptions[flag] = false
			W.npOptions()
			W.flush()
			check("bar heights with that flag gone: the percentages apply", near(a.hcr.height, 19.5) and near(a.castr.height, 12))
		end
		for _, variant in ipairs({ { "withheld", SECRET }, { "not a boolean", "yes" } }) do
			local W = NP.npWorld()
			W.npAllow = true
			local a = W.npShow("nameplate1", { player = false, friend = false })
