		end
	end

	-- 75y. Heights across two fights, and a height put back after a fight.
	do
		local W = NP.npWorld()
		local list = {}
		for i = 1, 3 do
			list[i] = W.npShow("nameplate" .. i, { player = false, friend = false })
		end
		W.change("nameplates.healthHeight", 150)
		check("heights across fights: out of combat the height is set", near(list[1].hcr.height, 19.5))
		W.combat = true
		W.change("nameplates.healthHeight", 100)
		check("heights across fights: put back to 100 in combat, Blizzard's height waits", near(list[1].hcr.height, 19.5))
		local mark = #W.npLog
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		local sets = 0
		for _, F in ipairs(list) do
			sets = sets + #NP.mine(W, F, mark, "HealthBarsContainer", "SetHeight")
		end
		check("heights across fights: when combat ends Blizzard's height is back on every plate, set once on each", near(list[1].hcr.height, 13) and near(list[2].hcr.height, 13) and near(list[3].hcr.height, 13) and sets == 3, sets)
		W.combat = true
		W.change("nameplates.castHeight", 200)
		check("heights across fights: a second fight holds the next height back too", near(list[1].castr.height, 6) and count(W.status(), "Bar height: nameplates that appear in combat get their height when combat ends.") == 1)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("heights across fights: and sets it when that one ends", near(list[1].castr.height, 12) and near(list[3].ccr.height, 22), g(list[1].castr.height))
		clean(W, "heights across fights")
	end

	-- 75z. The status says the driver was not followed when any one size the addon set can be reset.
	do
		local cases = {
			{ "bar height", { { "levelShape", "Game width" }, { "healthFlat", false }, { "healthTextSize", 100 }, { "healthHeight", 150 } } },
			{ "cast bar height", { { "levelShape", "Game width" }, { "healthFlat", false }, { "healthTextSize", 100 }, { "castHeight", 200 } } },
			{ "flat fill", { { "levelShape", "Game width" }, { "healthTextSize", 100 } } },
			{ "name size", { { "levelShape", "Game width" }, { "healthFlat", false }, { "healthTextSize", 100 }, { "nameSize", 150 } } },
			{ "health text size", { { "levelShape", "Game width" }, { "healthFlat", false } } },
			{ "level size", { { "levelShape", "Game width" }, { "healthFlat", false }, { "healthTextSize", 100 }, { "levelSize", 130 } } },
			{ "level box", { { "healthFlat", false }, { "healthTextSize", 100 } } },
		}
		for _, case in ipairs(cases) do
			local W = NP.npWorld()
			W.npAllow = true
			for _, s in ipairs(case[2]) do
				W.change("nameplates." .. s[1], s[2])
			end
			local f = W.npShow("nameplate1", { player = false, friend = false }, { quiet = true })
			W.env.NamePlateDriverFrame.UpdateNamePlateOptions = nil
			W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
			W.flush()
			check("no UpdateNamePlateOptions with only the " .. case[1] .. " changed: the status says that sizes can reset", count(W.status(), "Nameplates: sizes can go back to the default when the game lays a nameplate out again.") == 1, W.status())
		end
		local W = NP.npWorld()
		W.change("nameplates.healthFlat", false)
		W.change("nameplates.healthTextSize", 100)
		local f = W.npShow("nameplate1", { player = false, friend = false }, { quiet = true })
		W.env.NamePlateDriverFrame.UpdateNamePlateOptions = nil
		W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
		W.flush()
		check("no UpdateNamePlateOptions and nothing changed: the status does not say it", not has(W.status(), "layout function"), W.status())
	end

	-- 75za. Events that decide the class icon, one by one.
	do
		local W = NP.npWorld()
		local e = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local f = W.npShow("nameplate2", { player = true, friend = true, class = "ROGUE" })
		W.flush()
		-- UNIT_FACTION for the player alone: Blizzard has changed the plate's side, and the addon looks at every plate.
		f.info.friend = false
		W.blizzard(function() f.call("OnUnitFactionChanged") end)
		W.fire("UNIT_FACTION", "player")
		W.tick()
		check("class icon: UNIT_FACTION for the player alone makes the addon look at every plate", NP.shownIcon(W, f))
		-- UNIT_NAME_UPDATE of a unit that is a plate but not a plate unit.
		W.units.target = e.plate
		local calls0 = W.npClassCalls
		W.fire("UNIT_NAME_UPDATE", "target")
		W.fire("UNIT_FACTION", "target")
		W.tick()
		check("class icon: events for the unit 'target' are not events for its plate, even when the target has a plate", W.npClassCalls == calls0, W.npClassCalls - calls0)
		local other0 = W.npUnitCalls.nameplate2
		W.fire("UNIT_NAME_UPDATE", "nameplate1")
		W.tick()
		check("class icon: and an event for the plate's own unit is", W.npClassCalls > calls0)
		check("class icon: but only for that plate, not for the others", W.npUnitCalls.nameplate2 == other0, tostring(W.npUnitCalls.nameplate2) .. " " .. tostring(other0))
		-- A token the client gives that is empty.
		local E = NP.npWorld()
		local p = E.npShow("nameplate1", { player = true, friend = false, class = "" })
		E.flush()
		check("class icon: an empty class token gives no icon and no lookup of art", not NP.shownIcon(E, p) and NP.iconOf(E, p) == nil and #E.errors == 0 and #E.violations == 0 and not has(E.status(), "stopped")
			and not has(E.status(), "no class art") and E.npAtlasCalls["classicon-"] == nil, E.status())
		-- Many events in one frame set one timer, and an event after the timer sets another.
		local T = NP.npWorld()
		T.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		T.flush()
		T.fire("UNIT_NAME_UPDATE", "nameplate1")
		T.fire("UNIT_NAME_UPDATE", "nameplate1")
		T.fire("UNIT_FACTION", "nameplate1")
		check("class icon: events in one frame set one timer for the icons and one for the name-only comparison", #T.timers == 2, #T.timers)
		T.tick()
		T.fire("UNIT_NAME_UPDATE", "nameplate1")
		check("class icon: an event after that sets the next", #T.timers == 1)
	end

	-- 76. After the review: screen copy, the class icon place, the cast bar height range, calls that fail halfway, a part that stops, the name's colour.
	-- 76a. The nameplates page.
	do
		local W = NP.npWorld()
		local byKey = {}
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == "nameplates" or page.owner == "nameplates" then
				for _, item in ipairs(page) do
					if item.key then
						byKey[item.key] = item
					end
				end
			end
		end
		check("copy: the class icon switches have no tip, since a player's class is not withheld", byKey.classEnemy.tip == nil and byKey.classFriendly.tip == nil)
		check("copy: the three size tips say 100% is the game's own size", byKey.nameSize.tip == "100% is the game's own size." and byKey.healthTextSize.tip == "100% is the game's own size."
			and byKey.levelSize.tip == "100% is the game's own size.")
		check("copy: the two height tips say 100% is the game's own height", byKey.healthHeight.tip == "100% is the game's own height." and byKey.castHeight.tip == "100% is the game's own height.")
		check("copy: the level size is named for the number, the cast bar fill and the offsets in words", byKey.levelSize.label == "Level number size" and byKey.castFlat.label == "Flat nameplate cast bar"
			and byKey.classX.label == "Class icon horizontal offset" and byKey.classY.label == "Class icon vertical offset")
		check("copy: the health text tip says what unticking it does", byKey.healthText.tip == "Untick to hide the health number the game shows.", tostring(byKey.healthText.tip))
		local places = {}
		for _, choice in ipairs(byKey.classPosition.choices) do
			places[choice[1]] = choice[2]
		end
		check("class icon position: left by default, next to the bar, and right is still offered", byKey.classPosition.default == "left" and places.left == "Left"
			and places.right == "Right" and places.above == "Above" and places.below == "Below")
		check("cast bar height: stops at 200 percent in steps of 10", byKey.castHeight.max == 200 and byKey.castHeight.min == 50 and byKey.castHeight.step == 10)
		local S = NP.npWorld({ saved = { options = { ["nameplates.castHeight"] = 300, ["nameplates.classPosition"] = "left" } } })
		check("cast bar height: a saved 300 loads as 200, and a saved left position stays left", S.ns.Get("nameplates.castHeight") == 200 and S.ns.Get("nameplates.classPosition") == "left")
		local D = NP.npWorld({ saved = { options = { ["nameplates.castHeight"] = 250 } } })
		check("cast bar height: and a saved 250 as 200", D.ns.Get("nameplates.castHeight") == 200)
		clean(W, "nameplates copy")
	end

	-- 76b. The cast bar fill of the other part of the addon: asked for as off once its part has stopped.
	do
		local W = NP.npWorld(nil, { castFill = true })
		local a = W.npShow("nameplate1", { player = true, friend = false, class = "MAGE" })
		local b = W.npShow("nameplate2", { player = false, friend = false })
		W.flush()
		local function lastFlat(F)
			for i = #W.castFills, 1, -1 do
				if W.castFills[i].bar == F.cast then
					return W.castFills[i].flat
				end
			end
		end
		check("cast fill: both bars are asked for the flat fill while its part runs", lastFlat(a) == true and lastFlat(b) == true)
		for _ = 1, 3 do
			W.ns.EachPart("nameplates", "cast bar fill", function() error("cast fill failed", 0) end, {})
		end
		check("cast fill: three bars that fail stop the part, with a line in the status", W.ns.PartStopped("nameplates", "cast bar fill") and has(W.status(), "Nameplates: cast bar fill stopped. cast fill failed"), W.status())
		W.change("nameplates.castHeight", 150)
		check("cast fill: once the part has stopped every bar is asked for Blizzard's look", lastFlat(a) == false and lastFlat(b) == false)
		local c = W.npShow("nameplate3", { player = false, friend = false })
		W.flush()
		check("cast fill: and so is a bar that comes later", lastFlat(c) == false)
		check("cast fill: the rest of the module goes on", has(W.status(), "Nameplates: on, 3 styled") and NP.fillText(a) == "nil|nil|1,1,1,1" and NP.shownIcon(W, a) and near(a.castr.height, 9), W.status())
		-- A part that stops says so once in chat.
		check("cast fill stopped: one line in chat says so, no violations or errors", #W.violations == 0 and #W.errors == 0 and #W.out == 1
			and W.out[1] == "Flat UI: cast bar fill stopped in Nameplates. /flatui status shows why.", table.concat(W.violations, " | ") .. table.concat(W.errors, " | ") .. table.concat(W.out, " | "))
		-- A part of another name does not stop it.
		local V = NP.npWorld(nil, { castFill = true })
		local v = V.npShow("nameplate1", { player = false, friend = false })
		for _ = 1, 3 do
			V.ns.EachPart("nameplates", "text", function() error("text failed", 0) end, {})
		end
		V.change("nameplates.castHeight", 150)
		local flat
		for i = #V.castFills, 1, -1 do
			if V.castFills[i].bar == v.cast then
				flat = V.castFills[i].flat
				break
			end
		end
		check("cast fill: it stays on while another part is the one that stopped", flat == true)
	end

	-- 76c. A call that fails halfway: what it changed is still put back when the setting is.
	do
		local W = NP.npWorld()
		local f = W.npFrame()
		f.hbr.setColorFault = true
		W.npAdd(W.npPlate(), f, "nameplate1", { player = false, friend = false })
		W.flush()
		check("fill that fails halfway: the colour texture was made before the bar colour failed", NP.fillText(f) == "nil|nil|1,1,1,1", NP.fillText(f))
		W.change("nameplates.healthFlat", false)
		check("fill that fails halfway: switching the flat fill off gives Blizzard's fill back", NP.fillText(f) == NP.BAR_ATLAS .. "|nil|-", NP.fillText(f))
		check("fill that fails halfway: and no plate is counted failed", not has(W.status(), "failed"), W.status())

		local H = NP.npWorld()
		H.npAllow = true
		local h = H.npFrame()
		h.castr.heightFault = true
		H.npAdd(H.npPlate(), h, "nameplate1", { player = false, friend = false })
		H.change("nameplates.castHeight", 200)
		check("cast height that fails halfway: the container was resized before the bar failed", near(h.ccr.height, 22) and near(h.castr.height, 6), g(h.ccr.height) .. " " .. g(h.castr.height))
		H.change("nameplates.castHeight", 100)
		check("cast height that fails halfway: and the container goes back to Blizzard's height with the setting", near(h.ccr.height, 16), g(h.ccr.height))

		local T = NP.npWorld()
		local t = T.npFrame()
		t.rightr.textFault = true
		T.npAdd(T.npPlate(), t, "nameplate1", { player = false, friend = false })
		T.flush()
		check("text that fails halfway: the first two strings were resized before the third failed", near(t.textr.textHeight, 11.2) and near(t.leftr.textHeight, 11.2) and near(t.rightr.textHeight, 14),
			g(t.textr.textHeight) .. " " .. g(t.rightr.textHeight))
		T.change("nameplates.healthTextSize", 100)
		check("text that fails halfway: and they go back to Blizzard's height with the setting", near(t.textr.textHeight, 14) and near(t.leftr.textHeight, 14) and near(t.rightr.textHeight, 14),
			g(t.textr.textHeight) .. " " .. g(t.leftr.textHeight) .. " " .. g(t.rightr.textHeight))
		T.change("nameplates.healthTextOutline", false)
		check("text that fails halfway: the plain font object of the first two is set before the third fails", NP.stateOf(t.textr) == NP.PLAIN .. "/14" and NP.stateOf(t.leftr) == NP.PLAIN .. "/14",
			NP.stateOf(t.textr) .. " " .. NP.stateOf(t.leftr))
		T.change("nameplates.healthTextOutline", true)
		check("text that fails halfway: and Blizzard's font object is given back to them", NP.stateOf(t.textr) == NP.OUTLINED .. "/14" and NP.stateOf(t.leftr) == NP.OUTLINED .. "/14", NP.stateOf(t.textr) .. " " .. NP.stateOf(t.leftr))
	end

	-- 76d. The plate that stops a part goes back to Blizzard's look when its own layout returns, the others on the next frame.
	do
		local W = NP.npWorld()
		local p = {}
		for i = 1, 3 do
			p[i] = W.npShow("nameplate" .. i, { player = false, friend = false })
		end
		W.flush()
		for i = 1, 3 do
			p[i].hbr.setColorFault = true
		end
		W.npOptions()
		W.tick()
		local back = 0
		for i = 1, 3 do
			back = back + (NP.fillText(p[i]) == NP.BAR_ATLAS .. "|nil|-" and 1 or 0)
		end
		check("stopped part: the plate that stopped it is back to Blizzard's fill in the same pass", W.ns.PartStopped("nameplates", "bar fill") and back == 1, back)
		check("stopped part: and the other plates wait for the next frame", back == 1 and #W.timers == 1, back)
		W.tick()
		check("stopped part: when it comes they are back too", NP.fillText(p[1]) == NP.BAR_ATLAS .. "|nil|-" and NP.fillText(p[2]) == NP.BAR_ATLAS .. "|nil|-" and NP.fillText(p[3]) == NP.BAR_ATLAS .. "|nil|-", NP.fillText(p[1]))
		check("stopped part: with their bar colour as Blizzard gave it", NP.colourOf(p[1]) == "0.8,0.2,0.2,1" and NP.colourOf(p[3]) == "0.8,0.2,0.2,1")
		W.flush()
		check("stopped part: nothing is left waiting once the layout has run, since a stopped part queues no more", #W.timers == 0, #W.timers)
		W.npOptions()
		W.flush()
		check("stopped part: and Blizzard's later layouts queue nothing either", #W.timers == 0, #W.timers)
		-- A part that stops says so once in chat.
		check("stopped part: one line in chat says so, no violations or errors", #W.violations == 0 and #W.errors == 0 and #W.out == 1
			and W.out[1] == "Flat UI: bar fill stopped in Nameplates. /flatui status shows why.", table.concat(W.violations, " | ") .. table.concat(W.errors, " | ") .. table.concat(W.out, " | "))
	end

	-- 76e. The last line Blizzard runs on the name is the name's alone.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		W.flush()
		local mark = #W.npLog
		W.change("nameplates.healthTextSize", 120)
		W.change("nameplates.healthTextOutline", false)
		W.change("nameplates.levelSize", 130)
		W.change("nameplates.healthTextOutline", true)
		local extra = {}
		for _, part in ipairs({ "Text", "LeftText", "RightText", "LevelText" }) do
			for _ in ipairs(NP.mine(W, a, mark, part, "SetFontHeight")) do
				extra[#extra + 1] = part
			end
		end
		check("name: the health text and the level text are given no SetFontHeight", #extra == 0 and near(a.textr.textHeight, 16.8) and near(a.lTextr.textHeight, 13), table.concat(extra, " "))
		mark = #W.npLog
		W.change("nameplates.nameSize", 150)
		local list = NP.mine(W, a, mark, "name")
		check("name: SetFontHeight comes right after SetTextHeight, with the height the line height gives", NP.uniq(list) == "SetTextHeight(21) SetFontHeight(21)" and list[#list].call == "SetFontHeight" and near(list[#list][1], 21), NP.callsText(list))
		clean(W, "name last line")
	end

	-- 76f. The name keeps the colour Blizzard gave it when the addon sets its font object.
	do
		local function grey(W, F)
			-- A font object gives its string the object's own colour, which is white here. Blizzard colours the name again afterwards.
			local original = F.namer.SetFontObject
			F.namer.SetFontObject = function(self, object)
				original(self, object)
				F.namer.vertex = { 1, 1, 1, 1 }
			end
			W.blizzard(function() F.name:SetVertexColor(0.5, 0.5, 0.5) end)
		end
		local function vertex(F)
			return table.concat(F.namer.vertex, ",")
		end
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		grey(W, a)
		W.change("nameplates.nameOutline", false)
		check("name colour: with the outline off the plain font object is set and the grey is given back", NP.stateOf(a.namer) == NP.PLAIN .. "/14" and vertex(a) == "0.5,0.5,0.5,1", vertex(a))
		W.change("nameplates.nameOutline", true)
		check("name colour: and with the outline on again", NP.stateOf(a.namer) == NP.OUTLINED .. "/14" and vertex(a) == "0.5,0.5,0.5,1", vertex(a))
		local calls0 = a.namer.calls.SetVertexColor
		W.change("nameplates.nameSize", 150)
		W.change("nameplates.nameSize", 100)
		check("name colour: a size change sets no font object and so touches no colour", a.namer.calls.SetVertexColor == calls0, tostring(a.namer.calls.SetVertexColor) .. " " .. tostring(calls0))
		W.change("nameplates.healthTextOutline", false)
		W.change("nameplates.healthTextOutline", true)
		W.change("nameplates.nameOutline", false)
		check("name colour: the health text strings are never given a colour", a.textr.calls.SetVertexColor == nil and a.leftr.calls.SetVertexColor == nil and a.rightr.calls.SetVertexColor == nil)
		clean(W, "name colour")

		-- A colour the client withholds is passed on as it is.
		local S = NP.npWorld()
		local s = S.npShow("nameplate1", { player = false, friend = false })
		local given
		s.namer.GetVertexColor = function() return SECRET, SECRET, SECRET, SECRET end
		s.namer.SetVertexColor = function(_, ...) given = { n = select("#", ...), ... } end
		S.change("nameplates.nameOutline", false)
		check("name colour: a withheld colour is given back as four withheld values, and nothing is compared", given and given.n == 4 and rawequal(given[1], SECRET) and rawequal(given[4], SECRET)
			and NP.stateOf(s.namer) == NP.PLAIN .. "/14" and #S.errors == 0 and #S.violations == 0 and not has(S.status(), "stopped"), S.status())

		-- A colour that cannot be read: the font object is still set, and no colour is given.
		for _, how in ipairs({ "error", "none" }) do
			local E = NP.npWorld()
			local e = E.npShow("nameplate1", { player = false, friend = false })
			local set = 0
			e.namer.SetVertexColor = function() set = set + 1 end
			if how == "error" then
				e.namer.fault.vertex = "error"
			else
				e.namer.GetVertexColor = function() end
			end
			E.change("nameplates.nameOutline", false)
			E.change("nameplates.nameSize", 150)
			check("name colour: a colour that is " .. (how == "error" and "an error" or "nothing") .. " leaves the font object and size set and no colour given", NP.stateOf(e.namer) == NP.PLAIN .. "/21" and set == 0
				and #E.errors == 0 and #E.violations == 0 and not has(E.status(), "stopped") and not has(E.status(), "failed"), E.status())
		end
	end

	-- 77. Elite, rare and boss: the mark after the level, the border colour, and the fading row behind the name.
	-- What the checks read of a plate, as text: the mark ("+/1.00,0.82,0.00/10" while it is on screen), the health border
	-- ("r,g,b/pixels"), the line inside a Rare Elite's border and the row behind the name.
	function NP.markOf(W, F)
		for _, t in ipairs(W.addonFonts) do
			if t.owner == F.level then
				return t
			end
		end
	end
	function NP.mark(W, F)
		local t = NP.markOf(W, F)
		if not t then
			return "none"
		end
		if not (t.shown and F.levelr.shown) then
			return "hidden"
		end
		return ("%s/%.2f,%.2f,%.2f/%s"):format(t.text, t.textColour[1], t.textColour[2], t.textColour[3], g(t.textHeight))
	end
	function NP.border(W, F)
		local o = W.look(F.hb)
		return o and ("%.2f,%.2f,%.2f/%s"):format(o.r, o.g, o.b, g(o.thick)) or "none"
	end
	function NP.rim(W, F)
		local made = {}
		for _, f in ipairs(W.addonFrames) do
			if f.parent == F.hb then
				made[#made + 1] = f
			end
		end
		for _, f in ipairs(W.addonFrames) do
			if made[2] and f.parent == made[2] then
				local e = W.edgesOn(f)
				if #e == 4 then
					return e[1].shown and ("%.2f,%.2f,%.2f/%s"):format(e[1].color[1], e[1].color[2], e[1].color[3], g(e[1].height)) or "hidden"
				end
			end
		end
		return "none"
	end
	function NP.rowOf(W, F)
		for _, t in ipairs(W.addonTextures) do
			if t.owner == F.uf and t.layer == "BACKGROUND" then
				return t
			end
		end
	end
	function NP.row(W, F)
		local t = NP.rowOf(W, F)
		if not t then
			return "none"
		end
		if not t.shown then
			return "hidden"
		end
		local low, high = t.gradient[2], t.gradient[3]
		return ("%s %.3f,%.3f,%.3f,%.2f %.3f,%.3f,%.3f,%.2f"):format(t.gradient[1], low.r, low.g, low.b, low.a, high.r, high.g, high.b, high.a)
	end
	NP.GOLD, NP.SILVER, NP.RED, NP.NORMAL = "1.00,0.82,0.00", "0.78,0.80,0.84", "1.00,0.35,0.24", "0.00,0.00,0.00/1"

	-- 77a. Each kind of unit has its mark and border; a normal unit, a minus mob and a player have none.
	do
		local W = NP.npWorld()
		local kinds = {
			elite = W.npShow("nameplate1", { player = false, friend = false, classification = "elite" }),
			rare = W.npShow("nameplate2", { player = false, friend = false, classification = "rare" }),
			rareelite = W.npShow("nameplate3", { player = false, friend = false, classification = "rareelite" }),
			worldboss = W.npShow("nameplate4", { player = false, friend = false, classification = "worldboss", level = -1 }),
			bossmob = W.npShow("nameplate5", { player = false, friend = false, classification = "elite", boss = true }),
		}
		local plain = { W.npShow("nameplate6", { player = false, friend = false }), W.npShow("nameplate7", { player = false, friend = false, classification = "minus" }),
			W.npShow("nameplate8", { player = true, friend = false, class = "MAGE", classification = "normal" }) }
		W.flush()
		check("elite: a gold + after the level, in the level's font and size, and a gold border two pixels thick", NP.mark(W, kinds.elite) == "+/" .. NP.GOLD .. "/10"
			and NP.border(W, kinds.elite) == NP.GOLD .. "/2" and NP.markOf(W, kinds.elite).fontObject == "SystemFont_NamePlateLevel" and NP.rim(W, kinds.elite) == "none", NP.mark(W, kinds.elite) .. " " .. NP.border(W, kinds.elite))
		check("rare: a silver R and a silver border", NP.mark(W, kinds.rare) == "R/" .. NP.SILVER .. "/10" and NP.border(W, kinds.rare) == NP.SILVER .. "/2" and NP.rim(W, kinds.rare) == "none",
			NP.mark(W, kinds.rare) .. " " .. NP.border(W, kinds.rare))
		check("Rare Elite: a silver R+, a silver border, and a gold line one pixel thick over its inner pixel", NP.mark(W, kinds.rareelite) == "R+/" .. NP.SILVER .. "/10"
			and NP.border(W, kinds.rareelite) == NP.SILVER .. "/3" and NP.rim(W, kinds.rareelite) == NP.GOLD .. "/1", NP.mark(W, kinds.rareelite) .. " " .. NP.border(W, kinds.rareelite) .. " " .. NP.rim(W, kinds.rareelite))
		check("world boss: no mark and a red border", NP.mark(W, kinds.worldboss) == "none" and NP.border(W, kinds.worldboss) == NP.RED .. "/2" and NP.rim(W, kinds.worldboss) == "none", NP.border(W, kinds.worldboss))
		check("boss mob: no mark and a red border, whatever its classification", NP.mark(W, kinds.bossmob) == "none" and NP.border(W, kinds.bossmob) == NP.RED .. "/2", NP.border(W, kinds.bossmob))
		check("normal unit, minus mob and player: no mark, no line, the border every plate has", NP.mark(W, plain[1]) == "none" and NP.mark(W, plain[2]) == "none" and NP.mark(W, plain[3]) == "none"
			and NP.border(W, plain[1]) == NP.NORMAL and NP.border(W, plain[2]) == NP.NORMAL and NP.border(W, plain[3]) == NP.NORMAL and NP.rim(W, plain[1]) == "none")
		check("kinds: the mark hangs from the level number, just right of it, and the kind is read once for each plate", NP.markOf(W, kinds.elite).points[1][1] == "LEFT" and NP.markOf(W, kinds.elite).points[1][2] == kinds.elite.lText
			and NP.markOf(W, kinds.elite).points[1][3] == "RIGHT" and NP.markOf(W, kinds.elite).points[1][4] == 1 and #NP.markOf(W, kinds.elite).points == 1 and W.npKindCalls.UnitClassification == 8, W.npKindCalls.UnitClassification)
		clean(W, "kinds")

		-- The target and the focus keep their own colour, and the kind comes back when they move.
		W.units.target, W.units.focus = kinds.elite.plate, kinds.rareelite.plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.fire("PLAYER_FOCUS_CHANGED")
		W.flush()
		check("target and focus: the target border wins over the gold of an elite, and the focus border over the Rare Elite's, whose inner line goes",
			NP.border(W, kinds.elite) == "1.00,1.00,1.00/1" and NP.border(W, kinds.rareelite) == "1.00,0.60,0.00/1" and NP.rim(W, kinds.rareelite) == "hidden", NP.border(W, kinds.elite) .. " " .. NP.border(W, kinds.rareelite))
		W.units.target, W.units.focus = kinds.rare.plate, nil
		W.fire("PLAYER_TARGET_CHANGED")
		W.fire("PLAYER_FOCUS_CHANGED")
		W.flush()
		check("target and focus: the kind colour is back when the target and the focus change, and the mark was never touched", NP.border(W, kinds.elite) == NP.GOLD .. "/2"
			and NP.border(W, kinds.rareelite) == NP.SILVER .. "/3" and NP.rim(W, kinds.rareelite) == NP.GOLD .. "/1" and NP.border(W, kinds.rare) == "1.00,1.00,1.00/1" and NP.mark(W, kinds.elite) == "+/" .. NP.GOLD .. "/10",
			NP.border(W, kinds.elite) .. " " .. NP.border(W, kinds.rareelite) .. " " .. NP.border(W, kinds.rare))
		W.change("nameplates.target", false)
		W.flush()
		check("target and focus: with the target and focus border off the target has the colour of its kind", NP.border(W, kinds.rare) == NP.SILVER .. "/2", NP.border(W, kinds.rare))
		clean(W, "kinds, target")
	end

	-- 77b. The mark follows the level number: its shown state, its size, the Level box choices.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false, classification = "elite" })
		local b = W.npShow("nameplate2", { player = false, friend = false, classification = "elite", level = -1 })
		W.flush()
		check("mark and level: a unit whose level shows as a skull has no mark though it is an elite, and one whose number shows has", NP.mark(W, a) == "+/" .. NP.GOLD .. "/10" and NP.mark(W, b) == "none"
			and NP.border(W, b) == NP.GOLD .. "/2", NP.mark(W, a) .. " " .. NP.mark(W, b))
		a.lTextr.shown = false
		W.npOptions()
		W.flush()
		check("mark and level: the number hidden hides the mark with the next layout", NP.mark(W, a) == "hidden", NP.mark(W, a))
		a.lTextr.shown = true
		W.npOptions()
		W.flush()
		a.levelr.shown = false
		check("mark and level: shown again it is back, and it is hidden with the level frame, which is the frame it was made on", NP.mark(W, a) == "hidden" and NP.markOf(W, a).owner == a.level and NP.markOf(W, a).shown)
		a.levelr.shown = true
		check("mark and level: and visible again with it", NP.mark(W, a) == "+/" .. NP.GOLD .. "/10")
		W.change("nameplates.levelSize", 150)
		check("mark and level: the Level number size sizes the mark with the number", NP.mark(W, a) == "+/" .. NP.GOLD .. "/15" and near(a.lTextr.textHeight, 15), NP.mark(W, a) .. " " .. g(a.lTextr.textHeight))
		W.npOptions()
		W.npCVar("nameplateDebuffPadding", 3)
		W.flush()
		check("mark and level: and after Blizzard lays the plate out again", NP.mark(W, a) == "+/" .. NP.GOLD .. "/15" and NP.markOf(W, a).points[1][2] == a.lText)
		W.change("nameplates.levelSize", 100)
		local made = #W.addonFonts
		for _, choice in ipairs({ "Text only", "Default", "Thin border" }) do
			W.change("nameplates.level", choice)
			check("mark and level: with the Level box on " .. choice .. " the mark is there and is the same font string", NP.mark(W, a) == "+/" .. NP.GOLD .. "/10" and #W.addonFonts == made, NP.mark(W, a))
		end
		clean(W, "mark and level")
	end

	-- 77c. A plate that is released is clean, and a plate reused gets what its new unit has.
	do
		local W = NP.npWorld({ saved = { options = { ["nameplates.nameRow"] = true } } })
		local a = W.npShow("nameplate1", { player = false, friend = false, classification = "rareelite" })
		W.flush()
		local plate = a.plate
		check("released plate: before it goes it has the mark, the border, the line and the row", NP.mark(W, a) == "R+/" .. NP.SILVER .. "/10" and NP.border(W, a) == NP.SILVER .. "/3" and NP.rim(W, a) == NP.GOLD .. "/1"
			and NP.row(W, a):find("^VERTICAL") ~= nil, NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.row(W, a))
		W.npRemove(a)
		W.flush()
		check("released plate: it loses the mark, the colour, the line and the row", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.NORMAL and NP.rim(W, a) == "hidden" and NP.row(W, a) == "hidden",
			NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.rim(W, a) .. " " .. NP.row(W, a))
		W.npAdd(plate, a, "nameplate9", { player = false, friend = false })
		W.flush()
		check("reused plate: a normal unit in the unit frame has none of them but the row, which every plate has", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.NORMAL and NP.rim(W, a) == "hidden"
			and NP.row(W, a):find("^VERTICAL") ~= nil, NP.mark(W, a) .. " " .. NP.border(W, a))
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate10", { player = false, friend = false, classification = "elite" })
		W.flush()
		check("reused plate: an elite in it after that has them fresh, with the line gone", NP.mark(W, a) == "+/" .. NP.GOLD .. "/10" and NP.border(W, a) == NP.GOLD .. "/2" and NP.rim(W, a) == "hidden", NP.mark(W, a) .. " " .. NP.border(W, a))
		W.npRemove(a)
		W.npAdd(plate, a, "nameplate11", { player = false, friend = false })
		W.flush()
		check("reused plate: a normal unit that takes it from an elite has none of them", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.NORMAL, NP.mark(W, a) .. " " .. NP.border(W, a))
		clean(W, "released plate")
	end

	-- 77d. The game says the classification changed; nothing reads it otherwise.
	do
		local W = NP.npWorld()
		local a = W.npShow("nameplate1", { player = false, friend = false })
		local b = W.npShow("nameplate2", { player = false, friend = false })
		W.flush()
		local reads = W.npKindCalls.UnitClassification
		a.info.classification = "rare"
		b.info.classification = "elite"
		W.fire("UNIT_CLASSIFICATION_CHANGED", "nameplate1")
		W.flush()
		check("classification event: the plate of that unit shows its new kind and the other, which the game did not mention, is not read", NP.mark(W, a) == "R/" .. NP.SILVER .. "/10" and NP.border(W, a) == NP.SILVER .. "/2"
			and NP.mark(W, b) == "none" and W.npKindCalls.UnitClassification == reads + 1, NP.mark(W, a) .. " " .. NP.mark(W, b))
		reads = W.npKindCalls.UnitClassification
		W.fire("UNIT_CLASSIFICATION_CHANGED", "target")
		for _ = 1, 5 do
			W.advance(1)
			W.fire("PLAYER_TARGET_CHANGED")
			W.fire("UNIT_AURA", "nameplate1")
			W.flush()
		end
		check("classification event: an event for a unit that is not a plate unit and five frames of other events read no classification", W.npKindCalls.UnitClassification == reads, W.npKindCalls.UnitClassification - reads)
		W.fire("UNIT_CLASSIFICATION_CHANGED", SECRET)
		W.flush()
		check("classification event: one for a unit the client withholds reads every plate that has a unit", NP.mark(W, b) == "+/" .. NP.GOLD .. "/10" and W.npKindCalls.UnitClassification == reads + 2, NP.mark(W, b))
		a.info.classification = "normal"
		W.fire("UNIT_CLASSIFICATION_CHANGED", "nameplate1")
		W.flush()
		check("classification event: an elite that becomes normal loses its mark and its colour", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.NORMAL, NP.mark(W, a) .. " " .. NP.border(W, a))
		clean(W, "classification event")
	end

	-- 77e. A unit token or an answer the client withholds, raises, or does not have: a normal plate, and nothing raises.
	do
		local W = NP.npWorld()
		local list = {
			W.npShow("nameplate1", { player = false, friend = false, classification = "secret" }),
			W.npShow("nameplate2", { player = false, friend = false, classification = "error" }),
			W.npShow("nameplate3", { player = false, friend = false, classification = "elite", boss = "secret" }),
			W.npShow("nameplate4", { player = false, friend = false, classification = "elite", boss = "error" }),
			W.npShow("nameplate5", { player = false, friend = false, classification = "elite" }),
		}
		list[5].u.unit = SECRET
		W.fire("UNIT_CLASSIFICATION_CHANGED", "nameplate5")
		W.flush()
		check("withheld: a secret or failing classification gives a normal plate", NP.mark(W, list[1]) == "none" and NP.mark(W, list[2]) == "none" and NP.border(W, list[1]) == NP.NORMAL and NP.border(W, list[2]) == NP.NORMAL)
		check("withheld: a secret or failing boss answer leaves the classification to decide", NP.mark(W, list[3]) == "+/" .. NP.GOLD .. "/10" and NP.mark(W, list[4]) == "+/" .. NP.GOLD .. "/10")
		check("withheld: a unit token the client withholds gives a normal plate and nothing is asked", NP.mark(W, list[5]) == "hidden" and NP.border(W, list[5]) == NP.NORMAL and #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"))
		clean(W, "withheld")
		local S = NP.npWorld()
		S.secretType = "string"
		local text = S.npShow("nameplate1", { player = false, friend = false, classification = "secret", boss = true })
		S.flush()
		check("withheld: a classification that is a secret string gives a normal plate when the boss flag says boss", NP.mark(S, text) == "none" and NP.border(S, text) == NP.NORMAL, NP.mark(S, text))
		clean(S, "withheld string")
		local L = NP.npWorld(nil, { without = { "UnitClassification", "UnitIsBossMob" } })
		local l = L.npShow("nameplate1", { player = false, friend = false, classification = "elite" })
		L.flush()
		check("a client without the unit functions: a normal plate, no error", NP.mark(L, l) == "none" and NP.border(L, l) == NP.NORMAL and #L.errors == 0 and not has(L.status(), "stopped"), L.status())
		clean(L, "no unit functions")
	end

	-- 77f. The fading row behind the name.
	do
		local W = NP.npWorld({ saved = { options = { ["nameplates.nameRow"] = true } } })
		local a = W.npShow("nameplate1", { player = false, friend = false, colour = { 0.8, 0.2, 0.2, 1 } })
		local b = W.npShow("nameplate2", { player = false, friend = true, colour = { 0.1, 0.8, 0.1, 1 } })
		W.flush()
		local row = NP.rowOf(W, a)
		local p = row.points
		check("row: as wide as the health bar and one unit above and below the name text", #p == 4 and p[1][1] == "LEFT" and p[1][2] == a.hb and p[1][3] == "LEFT" and p[2][1] == "RIGHT" and p[2][2] == a.hb and p[2][3] == "RIGHT"
			and p[3][1] == "TOP" and p[3][2] == a.name and p[3][3] == "TOP" and p[3][5] == 1 and p[4][1] == "BOTTOM" and p[4][2] == a.name and p[4][3] == "BOTTOM" and p[4][5] == -1 and row.owner == a.uf and row.layer == "BACKGROUND")
		check("row: a vertical gradient from the bar colour at 70 percent brightness, opaque at the bottom and nearly clear above", NP.row(W, a) == "VERTICAL 0.560,0.140,0.140,0.95 0.560,0.140,0.140,0.05"
			and NP.row(W, b) == "VERTICAL 0.070,0.560,0.070,0.95 0.070,0.560,0.070,0.05", NP.row(W, a) .. " | " .. NP.row(W, b))
		a.hbr.barColor = { 0.2, 0.4, 0.8, 1 }
		W.fire("UNIT_FACTION", "nameplate1")
		W.flush()
		check("row: it takes the new colour when the faction changes", NP.row(W, a) == "VERTICAL 0.140,0.280,0.560,0.95 0.140,0.280,0.560,0.05", NP.row(W, a))
		a.hbr.barColor = { SECRET, SECRET, SECRET, 1 }
		W.npOptions()
		W.flush()
		check("row: a colour the client withholds means no row", NP.row(W, a) == "hidden" and #W.errors == 0 and #W.violations == 0, NP.row(W, a))
		W.change("nameplates.nameRow", false)
		check("row: off, it is gone from every plate", NP.row(W, b) == "hidden" and NP.row(W, a) == "hidden")
		W.change("nameplates.nameRow", true)
		check("row: and on again it is the same texture with the colour of the bar", NP.rowOf(W, b) ~= nil and NP.row(W, b) == "VERTICAL 0.070,0.560,0.070,0.95 0.070,0.560,0.070,0.05" and NP.rowOf(W, a) == row, NP.row(W, b))
		clean(W, "row")
		-- A client without CreateColor, without SetGradient, or whose SetGradient raises.
		for _, case in ipairs({ { "no CreateColor", nil, { without = { "CreateColor" } } }, { "no SetGradient", { noGradient = true } }, { "a SetGradient that raises", { gradientFault = true } } }) do
			local V = NP.npWorld(case[2], case[3])
			V.gradientFault = case[2] and case[2].gradientFault
			local v = V.npShow("nameplate1", { player = false, friend = false })
			V.change("nameplates.nameRow", true)
			V.flush()
			check("row: with " .. case[1] .. " no row is shown and nothing raises", (NP.row(V, v) == "none" or NP.row(V, v) == "hidden") and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "stopped"), NP.row(V, v))
			check("row: with " .. case[1] .. " the status says so, once", count(V.status(), "Name row: the game cannot draw a gradient, so no row is shown.") == 1, V.status())
		end
	end

	-- 77g. Each setting off alone removes only its part; the page off removes all three.
	do
		local W = NP.npWorld({ saved = { options = { ["nameplates.nameRow"] = true } } })
		local a = W.npShow("nameplate1", { player = false, friend = false, classification = "rareelite" })
		W.flush()
		local full = NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.rim(W, a) .. " " .. NP.row(W, a)
		W.change("nameplates.kindMark", false)
		W.flush()
		check("kindMark off: only the mark goes", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.SILVER .. "/3" and NP.rim(W, a) == NP.GOLD .. "/1" and NP.row(W, a):find("^VERTICAL") ~= nil)
		W.change("nameplates.kindMark", true)
		W.change("nameplates.kindBorder", false)
		W.flush()
		check("kindBorder off: only the colour and the line go", NP.mark(W, a) == "R+/" .. NP.SILVER .. "/10" and NP.border(W, a) == NP.NORMAL and NP.rim(W, a) == "hidden" and NP.row(W, a):find("^VERTICAL") ~= nil, NP.border(W, a))
		W.change("nameplates.kindBorder", true)
		W.change("nameplates.nameRow", false)
		W.flush()
		check("nameRow off: only the row goes", NP.mark(W, a) == "R+/" .. NP.SILVER .. "/10" and NP.border(W, a) == NP.SILVER .. "/3" and NP.rim(W, a) == NP.GOLD .. "/1" and NP.row(W, a) == "hidden")
		W.change("nameplates.nameRow", true)
		W.flush()
		check("the three on again: as at the start", NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.rim(W, a) .. " " .. NP.row(W, a) == full, full)
		W.change("nameplates.health", false)
		W.flush()
		check("health border off: the kind colour has no border to colour and the mark stays", NP.mark(W, a) == "R+/" .. NP.SILVER .. "/10" and W.state(a.hb) == "hb" and NP.rim(W, a) == "hidden")
		W.change("nameplates.health", true)
		W.change("nameplates.enabled", false)
		W.flush()
		check("page off: the mark, the colour, the line and the row are all gone", NP.mark(W, a) == "hidden" and NP.border(W, a) == NP.NORMAL and W.state(a.hb) == "hb" and NP.rim(W, a) == "hidden" and NP.row(W, a) == "hidden")
		clean(W, "settings")
	end

	-- 77h. A forbidden plate is left alone, and nothing is added to a protected frame in combat.
	do
		local W = NP.npWorld()
		local f = W.npShow("nameplate1", { player = false, friend = false, classification = "elite" }, { forbidden = true })
		W.fire("UNIT_CLASSIFICATION_CHANGED", "nameplate1")
		W.flush()
		check("forbidden plate: nothing is asked of its unit, nothing is made on it", W.npKindCalls.UnitClassification == nil and #W.addonFonts == 0 and #W.violations == 0 and NP.rowOf(W, f) == nil, table.concat(W.violations, "|"))
		local a = W.npShow("nameplate2", { player = false, friend = false })
		W.flush()
		local fonts = #W.addonFonts
		a.levelr.protected, a.hbr.protected, a.u.protected = true, true, true
		W.combat = true
		a.info.classification = "rareelite"
		W.fire("UNIT_CLASSIFICATION_CHANGED", "nameplate2")
		W.change("nameplates.nameRow", true)
		W.flush()
		check("combat: nothing is made on the protected level frame, health bar or unit frame, and the colour, which a texture takes, is set",
			#W.violations == 0 and #W.errors == 0 and #W.addonFonts == fonts and NP.rim(W, a) == "none" and NP.rowOf(W, a) == nil and NP.border(W, a) == NP.SILVER .. "/2", table.concat(W.violations, "|") .. NP.border(W, a))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: the mark, the line, the row and the thicker border are made", NP.mark(W, a) == "R+/" .. NP.SILVER .. "/10" and NP.rim(W, a) == NP.GOLD .. "/1" and NP.row(W, a):find("^VERTICAL") ~= nil
			and NP.border(W, a) == NP.SILVER .. "/3" and #W.violations == 0, NP.mark(W, a) .. " " .. NP.rim(W, a) .. " " .. NP.border(W, a))
		local C = NP.npWorld({ combat = true, saved = { options = { ["nameplates.nameRow"] = true } } })
		local c = C.npShow("nameplate1", { player = false, friend = false, classification = "rareelite" })
		C.flush()
		check("combat: frames that are not protected get all of it at once", NP.mark(C, c) == "R+/" .. NP.SILVER .. "/10" and NP.rim(C, c) == NP.GOLD .. "/1" and NP.row(C, c):find("^VERTICAL") ~= nil and #C.violations == 0)
		clean(W, "combat")
		clean(C, "combat, unprotected")
	end

	-- 77i. Borderless: the border of a kind has a colour of its own and stays, with the line inside a Rare Elite's; the plain border goes.
	do
		local W = NP.npWorld()
		local elite = W.npShow("nameplate1", { player = false, friend = false, classification = "elite" })
		local rareelite = W.npShow("nameplate2", { player = false, friend = false, classification = "rareelite" })
		local plain = W.npShow("nameplate3", { player = false, friend = false })
		W.flush()
		local was = W.state(plain.hb)
		W.change("general.borderless", true)
		W.flush()
		check("borderless: a plain plate loses its border and keeps its background; an elite keeps its gold border and a Rare Elite its silver border and the gold line inside it",
			W.state(plain.hb) == "hB" and W.state(elite.hb) == "SB" and NP.border(W, elite) == NP.GOLD .. "/2" and W.state(rareelite.hb) == "SB" and NP.border(W, rareelite) == NP.SILVER .. "/3"
			and NP.rim(W, rareelite) == NP.GOLD .. "/1", W.state(plain.hb) .. W.state(elite.hb) .. W.state(rareelite.hb) .. " " .. NP.rim(W, rareelite))
		local later = W.npShow("nameplate4", { player = false, friend = false, classification = "rareelite" })
		local fresh = W.npShow("nameplate5", { player = false, friend = false })
		W.flush()
		check("borderless: a plate that appears while it is on has the same: a Rare Elite its border and line, a plain plate none", W.state(later.hb) == "SB" and NP.border(W, later) == NP.SILVER .. "/3"
			and NP.rim(W, later) == NP.GOLD .. "/1" and W.state(fresh.hb) == "hB", W.state(later.hb) .. NP.rim(W, later) .. W.state(fresh.hb))
		W.units.target = plain.plate
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("borderless: the target has its own colour and keeps its border; when it moves on the plate has none again", W.state(plain.hb) == "SB" and NP.border(W, plain) == "1.00,1.00,1.00/1", NP.border(W, plain))
		W.units.target = nil
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("borderless: and the target's plate has none again once it is not the target", W.state(plain.hb) == "hB", W.state(plain.hb))
		W.change("nameplates.kindBorder", false)
		W.flush()
		check("borderless: with the kind border off an elite and a Rare Elite have no border and no line, and the marks stay", W.state(elite.hb) == "hB" and W.state(rareelite.hb) == "hB"
			and NP.rim(W, rareelite) == "hidden" and NP.mark(W, elite) == "+/" .. NP.GOLD .. "/10" and NP.mark(W, rareelite) == "R+/" .. NP.SILVER .. "/10", W.state(elite.hb) .. W.state(rareelite.hb) .. NP.rim(W, rareelite))
		W.change("nameplates.kindBorder", true)
		W.change("general.borderless", false)
		W.flush()
		check("borderless: off again, every plate has its border, and the kinds their colours and the line", W.state(plain.hb) == was and W.state(fresh.hb) == was and NP.border(W, plain) == NP.NORMAL
			and NP.border(W, elite) == NP.GOLD .. "/2" and NP.border(W, rareelite) == NP.SILVER .. "/3" and NP.rim(W, rareelite) == NP.GOLD .. "/1", W.state(plain.hb) .. NP.border(W, plain))
		clean(W, "borderless")
	end

	-- 77j. The kind settings of a profile are put on the plates that are up when the profile is switched to, copied, reset and imported.
	do
		local W = NP.npWorld({ saved = { profiles = { Default = { options = {}, movers = {} },
			Other = { options = { ["nameplates.kindMark"] = false, ["nameplates.kindBorder"] = false }, movers = {} } }, profileOf = {} } })
		local a = W.npShow("nameplate1", { player = false, friend = false, classification = "rareelite" })
		W.flush()
		local line = NP.npWorld({ saved = { options = { ["nameplates.kindMark"] = false, ["nameplates.kindBorder"] = false } } }).ns.ExportProfile()
		local seen = { NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.rim(W, a) }
		for _, step in ipairs({ function() W.ns.UseProfile("Other") end, function() W.ns.UseProfile("Default") end, function() W.ns.CopyProfile("Other") end,
			function() W.ns.ResetProfile() end, function() W.ns.ImportProfile(line) end }) do
			step()
			W.flush()
			seen[#seen + 1] = NP.mark(W, a) .. " " .. NP.border(W, a) .. " " .. NP.rim(W, a)
		end
		local plain, full = "hidden " .. NP.NORMAL .. " hidden", "R+/" .. NP.SILVER .. "/10 " .. NP.SILVER .. "/3 " .. NP.GOLD .. "/1"
		check("profiles: the mark and the border of a kind follow a switch of profile, a copy, a reset and an import", table.concat(seen, "|") == table.concat({ full, plain, full, plain, full, plain }, "|")
			and #W.errors == 0 and #W.violations == 0, table.concat(seen, "|"))
		clean(W, "profiles")
	end
end

-- Sections 75 to 100 are one block, so their helpers and constants are local to it: a function allows only 200 local variables.
do

	-- 75. Cooldowns: the simulated client. The spell functions, Cooldown frames and cooldown manager frames exist only in a world that asks for them.
	-- The cooldown icons are checked against the design (research/forever-cooldowns/design.json) and Blizzard's documentation of the calls they make.
	local SP = { KIDNEY = 408, BLIND = 2094, VANISH = 1856, KICK = 1766, SINISTER = 1752, DUAL = 674, EXPOSE1 = 8647, EXPOSE3 = 8650, PREP = 14185,
		CLOAK = 31224, SHIV = 5938, FUTURE = 11111, TRICKS = 57934, CHARGED = 100001 }
	local CD_SWEEP_PLAIN = "Interface\\ChatFrame\\ChatFrameBackground"
	local CD_SWEEP_ROUND = "Interface\\HUD\\UI-HUD-CoolDownManager-Icon-Swipe"
	local CD_NO_POSITION = "Cooldown icons: the personal resource display cannot be used, so the row is in the middle of the screen."
	local CD_NO_SWEEP = "Cooldown icons: the game hides cooldown times and has no other way to draw them, so icons dim without a sweep."
	local CD_NO_OVERLAY = "Cooldown manager icons: the default frame was not found and is still shown."
	local CD_NO_MASK = "Cooldown manager icons: the round mask was not found, so corners stay rounded."

	-- The spell book of a character: one spell of each kind the two lists have to tell apart.
	local function cdBook(W)
		W.addLine({ name = "General" })
		W.addLine({ name = "Subtlety", offSpecID = 261 })
		W.addLine({ name = "Hidden", shouldHide = true })
		W.addSpell(SP.KIDNEY, { name = "Kidney Shot", icon = 132298, base = 20000 })
		W.addSpell(SP.BLIND, { name = "Blind", icon = 136175, base = 120000 })
		W.addSpell(SP.VANISH, { name = "Vanish", icon = 132331, base = 180000 })
		W.addSpell(SP.KICK, { name = "Kick", icon = 132219, base = 10000 })
		W.addSpell(SP.SINISTER, { name = "Sinister Strike", icon = 136189, base = 0 })
		W.addSpell(SP.DUAL, { name = "Dual Wield", icon = 132147, passive = true, base = 0 })
		W.addSpell(SP.EXPOSE1, { name = "Expose Armor", icon = 132354, base = 5000, lowRank = true })
		W.addSpell(SP.EXPOSE3, { name = "Expose Armor", icon = 132354, base = 5000 })
		W.addSpell(SP.PREP, { name = "Preparation", icon = 136121, base = 480000, line = 2 })
		W.addSpell(SP.CLOAK, { name = "Cloak of Shadows", icon = 136177, base = 90000, line = 3 })
		W.addSpell(SP.SHIV, { name = "Shiv", icon = 135428, base = 1000, offSpec = true })
		W.addSpell(SP.FUTURE, { name = "Future Move", icon = 135999, base = 5000, itemType = "FutureSpell" })
		W.addSpell(SP.TRICKS, { name = "Tricks of the Trade", icon = 236283, base = 30000, known = false })
		W.addSpell(SP.CHARGED, { name = "Charged Strike", icon = 132333, base = 6000, charges = 3 })
	end

	-- A world with cooldown icons, the book above, a character who has picked `picked` (spell IDs), logged in.
	local function cdUp(options, picked, noBook)
		local o = {}
		for k, v in pairs(options or {}) do
			o[k] = v
		end
		o.cooldowns = o.cooldowns or true
		if picked and not o.char then
			o.char = { cooldowns = picked }
		end
		local W = newWorld(o)
		if not noBook then
			cdBook(W)
		end
		W.login()
		W.flush()
		return W
	end

	-- n more spells, all known with a cooldown, with the IDs 5001 on.
	local function cdMany(W, n)
		local ids = {}
		for i = 1, n do
			W.addSpell(5000 + i, { name = string.format("Test Spell %02d", i), icon = 200000 + i, base = 1000 })
			ids[i] = 5000 + i
		end
		return ids
	end

	local function cdHolder(W)
		for _, f in ipairs(W.addonFrames) do
			if f.parent == W.env.UIParent and f.scripts and f.scripts.OnUpdate then
				return f
			end
		end
	end

	-- The icons of the row in the order the addon made them, each with the parts the design lists.
	local function cdIcons(W)
		local holder, list = cdHolder(W), {}
		if not holder then
			return list
		end
		for _, f in ipairs(W.addonFrames) do
			if f.parent == holder then
				local rec = { frame = f }
				for _, r in ipairs(f.regions) do
					if r.layer == "ARTWORK" then
						rec.texture = r
					end
				end
				for _, child in ipairs(f.children) do
					if child.cd then
						rec.cooldown = child
					else
						for _, r in ipairs(child.regions) do
							if r.kind == "FontString" then
								rec.count, rec.top = r, child
							end
						end
					end
				end
				list[#list + 1] = rec
			end
		end
		return list
	end

	local function cdShown(W)
		local list = {}
		for _, rec in ipairs(cdIcons(W)) do
			if rec.frame.shown then
				list[#list + 1] = rec
			end
		end
		return list
	end

	-- The textures of the shown icons, in row order, as one string.
	local function cdRowIcons(W)
		local list = {}
		for _, rec in ipairs(cdShown(W)) do
			list[#list + 1] = rec.texture.file
		end
		return table.concat(list, ",")
	end

	-- Where icon i of k belongs, worked out from the design: the corner of the icon and the offsets from the middle of the holder.
	local function cdSlot(i, k, size, spacing, perRow, grow, rows)
		local step = size + spacing
		local column = (i - 1) % perRow
		local row = (i - 1 - column) / perRow
		local n = math.min(perRow, k - row * perRow)
		local x
		if grow == "right" then
			x = column * step
		elseif grow == "left" then
			x = -(column + 1) * size - column * spacing
		else
			x = column * step - (n * step - spacing) / 2
		end
		if rows == "up" then
			return "BOTTOMLEFT", x, row * step
		end
		return "TOPLEFT", x, -row * step
	end

	-- Empty when every shown icon is where the design puts it; else what is wrong.
	local function cdPlaced(W, size, spacing, perRow, grow, rows)
		local holder, shown = cdHolder(W), cdShown(W)
		local wrong = {}
		for i, rec in ipairs(shown) do
			local point, x, y = cdSlot(i, #shown, size, spacing, perRow, grow, rows)
			local p = rec.frame.points[1]
			if #rec.frame.points ~= 1 or not p or p[1] ~= point or p[2] ~= holder or p[3] ~= "CENTER" or not near(p[4], x) or not near(p[5], y)
				or rec.frame.width ~= size or rec.frame.height ~= size then
				wrong[#wrong + 1] = i .. ": " .. (p and (p[1] .. " " .. g(p[4]) .. "," .. g(p[5])) or "no point") .. " wants " .. point .. " " .. g(x) .. "," .. g(y) .. " size " .. tostring(rec.frame.width)
			end
		end
		return table.concat(wrong, "; ")
	end

	-- A number as text, with no sign on a zero (Lua 5.1 has a negative zero).
	local function cdNum(n)
		return n == 0 and "0" or g(n)
	end
	local function cdQuiet(W)
		return #W.violations == 0 and #W.errors == 0
	end
	local function cdTrouble(W)
		return (table.concat(W.violations, " | ") .. " || " .. table.concat(W.errors, " | ")):sub(1, 300)
	end
	local function cdSaved(W)
		return W.env.FlatUICharDB.cooldowns
	end
	local function cdList(t)
		local out = {}
		for i, v in ipairs(t or {}) do
			out[i] = tostring(v)
		end
		return table.concat(out, ",")
	end
	local function cdStatusLine(W)
		return W.line("Cooldowns")
	end
	local function cdSnapshot(W)
		local out = { #W.addonFrames, #W.addonTextures, #W.addonFonts }
		for _, rec in ipairs(cdIcons(W)) do
			local p = rec.frame.points[1]
			out[#out + 1] = tostring(rec.frame.shown) .. ":" .. (p and (p[1] .. g(p[4]) .. g(p[5])) or "-") .. ":" .. g(rec.frame.width)
		end
		local holder = cdHolder(W)
		if holder then
			local p = holder.points[1]
			out[#out + 1] = tostring(holder.shown) .. (p and (p[1] .. tostring(p[2] == W.env.UIParent) .. g(p[4]) .. g(p[5])) or "-")
		end
		return table.concat(out, "|")
	end

	-- 75a. The simulated client, as the client's documentation describes it.
	do
		local W = cdUp()
		local env = W.env
		local cd = env.CreateFrame("Cooldown", nil, env.UIParent, "CooldownFrameTemplate")
		check("simulation: a Cooldown frame from CooldownFrameTemplate starts hidden and takes all points of its parent", cd.shown == false and cd.allPoints == env.UIParent and cd.objectType == "Cooldown")
		local before = #W.violations
		local refused = not pcall(cd.SetCooldown, cd, SECRET, 10)
		check("simulation: SetCooldown refuses a withheld number", refused and #W.violations == before + 1)
		before = #W.violations
		check("simulation: and a withheld duration or rate", not pcall(cd.SetCooldown, cd, 5, SECRET) and not pcall(cd.SetCooldown, cd, 5, 10, SECRET) and #W.violations == before + 2)
		cd:SetCooldown(100, 30, 1)
		check("simulation: SetCooldown with plain numbers draws a sweep and shows the frame", cd.cd.sweep and cd.cd.sweep.kind == "numbers" and cd.shown == true)
		cd:Clear()
		check("simulation: Clear takes the sweep off and hides the frame", cd.cd.sweep == nil and cd.shown == false)
		W.setCooldown(SP.KIDNEY, "cooling")
		local duration = env.C_Spell.GetSpellCooldownDuration(SP.KIDNEY, true)
		cd:SetCooldownFromDurationObject(duration, true)
		check("simulation: SetCooldownFromDurationObject takes the object from GetSpellCooldownDuration, draws a sweep and shows the frame", cd.cd.sweep and cd.cd.sweep.kind == "object"
			and cd.cd.object == duration and cd.shown == true and #W.violations == before + 2)
		before = #W.violations
		check("simulation: it refuses a number and a withheld value in place of the object", not pcall(cd.SetCooldownFromDurationObject, cd, 30, true) and not pcall(cd.SetCooldownFromDurationObject, cd, SECRET, true)
			and #W.violations == before + 2)
		before = #W.violations
		check("simulation: a duration object cannot be read or written", not pcall(function() return duration.remaining end) and not pcall(function() duration.x = 1 end) and #W.violations == before + 2)
		W.setCooldown(SP.KIDNEY, "gcd")
		cd:SetCooldownFromDurationObject(env.C_Spell.GetSpellCooldownDuration(SP.KIDNEY, true), true)
		check("simulation: with the global cooldown left out, a spell that is only on it gives an empty duration and the frame clears", cd.cd.sweep == nil and cd.shown == false)
		cd:SetCooldownFromDurationObject(env.C_Spell.GetSpellCooldownDuration(SP.KIDNEY, false), true)
		check("simulation: with it left in, the same spell gives a sweep", cd.cd.sweep ~= nil and cd.shown == true)
		W.setCooldown(SP.KIDNEY, "ready")
		local info = env.C_Spell.GetSpellCooldown(SP.KIDNEY)
		check("simulation: a ready spell has isActive false, isOnGCD false and isEnabled true", info.isActive == false and info.isOnGCD == false and info.isEnabled == true and info.startTime == 0)
		W.sp.secretTimes = true
		W.setCooldown(SP.KIDNEY, "cooling")
		info = env.C_Spell.GetSpellCooldown(SP.KIDNEY)
		local charges = env.C_Spell.GetSpellCharges(SP.CHARGED)
		check("simulation: withheld times are withheld and isActive, isOnGCD, isEnabled and maxCharges are not", rawequal(info.startTime, SECRET) and rawequal(info.duration, SECRET) and rawequal(info.modRate, SECRET)
			and info.isActive == true and info.isOnGCD == false and info.isEnabled == true and rawequal(charges.currentCharges, SECRET) and charges.maxCharges == 3)
		check("simulation: a spell without charges has no charge info, and GetSpellCooldown of an unknown spell gives nothing", env.C_Spell.GetSpellCharges(SP.KIDNEY) == nil and env.C_Spell.GetSpellCooldown(999999) == nil)
		check("simulation: a spell name is found whatever its capitals, and gives the rank the character uses", env.C_Spell.GetSpellInfo("EXPOSE armor").spellID == SP.EXPOSE3 and env.C_Spell.GetSpellInfo("kidney shot").spellID == SP.KIDNEY
			and env.C_Spell.GetSpellInfo("no such spell") == nil)
		local lineTwo = env.C_SpellBook.GetSpellBookSkillLineInfo(2)
		local lineOne = env.C_SpellBook.GetSpellBookSkillLineInfo(1)
		check("simulation: skill lines run their slots one after the other, and the book says which are off spec or hidden", lineOne.itemIndexOffset == 0 and lineTwo.itemIndexOffset == lineOne.numSpellBookItems
			and lineTwo.offSpecID == 261 and lineOne.offSpecID == nil and env.C_SpellBook.GetSpellBookSkillLineInfo(3).shouldHide == true and env.C_SpellBook.GetNumSpellBookSkillLines() == 3)
		local item = env.C_SpellBook.GetSpellBookItemInfo(1, env.Enum.SpellBookSpellBank.Player)
		check("simulation: a spell book item has the fields of SpellBookItemInfo", item.itemType == env.Enum.SpellBookItemType.Spell and item.actionID == SP.KIDNEY and item.spellID == SP.KIDNEY and item.name == "Kidney Shot"
			and item.isPassive == false and item.isOffSpec == false and env.C_SpellBook.GetSpellBookItemInfo(1, env.Enum.SpellBookSpellBank.Pet) == nil)
		check("simulation: a lower rank is marked and a spell that is not in the book is not known", env.C_SpellBook.IsSpellBookItemLowRank(7, 0) == true and env.C_SpellBook.IsSpellBookItemLowRank(8, 0) == false
			and env.C_SpellBook.IsSpellKnownOrInSpellBook(SP.TRICKS) == false and env.C_SpellBook.IsSpellKnown(SP.KIDNEY) == true and env.GetSpellBaseCooldown(SP.KIDNEY) == 20000)
		local fs = W.addonFonts
		local top = env.CreateFrame("Frame", nil, env.UIParent)
		local text = top:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
		text:SetText("3")
		local fsText = text.text
		text:SetText(4)
		fsText = fsText .. text.text
		text:SetText(SECRET)
		check("simulation: a font string takes a string, a number as text and a withheld string, and not a table", fsText == "34" and rawequal(text.text, SECRET) and not pcall(text.SetText, text, {})
			and not pcall(top.CreateFontString, top, nil, "OVERLAY", "NoSuchFont") and #fs >= 1)
		W.violations = {}
		local plain = newWorld()
		plain.login()
		check("simulation: a world that does not ask for cooldowns has no Cooldown frame, no spell functions and no viewers", not pcall(plain.env.CreateFrame, "Cooldown", nil, plain.env.UIParent, "CooldownFrameTemplate")
			and plain.env.C_Spell == nil and plain.env.C_SpellBook == nil and plain.env.GetSpellBaseCooldown == nil and plain.env.EssentialCooldownViewer == nil and plain.cdm == nil)
		local blizzard, braw = W.B(nil, {}, { objectType = "Cooldown", cd = true, protected = true })
		W.combat = true
		check("simulation: a Cooldown frame that is protected refuses a sweep in combat", not pcall(blizzard.Clear, blizzard) and not pcall(braw.SetCooldown, braw, 1, 1))
		W.combat = false
		check("simulation: and a Blizzard frame takes no script from the addon", not pcall(W.prdFrame.SetScript, W.prdFrame, "OnUpdate", function() end) and not pcall(W.prdFrame.SetScript, W.prdFrame, "OnCooldownDone", function() end))
		check("simulation: a frame whose anchor has no rectangle has none, and GetLeft can be withheld or fail", (function()
			local a = env.CreateFrame("Frame", nil, env.UIParent)
			local b = env.CreateFrame("Frame", nil, env.UIParent)
			b:SetPoint("CENTER", a, "CENTER", 0, 0)
			local has = b:GetLeft() ~= nil
			a.noRect = true
			local lost = b:GetLeft() == nil
			a.noRect = false
			b.fault.rect = "secret"
			local secret = rawequal(b:GetLeft(), SECRET)
			b.fault.rect = "error"
			return has and lost and secret and not pcall(b.GetLeft, b)
		end)())
		W.violations = {}
	end

	-- 75b. The two dropdowns of the page are built each time their menu opens.
	do
		local W = cdUp(nil, { SP.KIDNEY })
		local first = W.menu("cooldowns.add")
		W.addSpell(7777, { name = "Aaa New Spell", base = 1000 })
		local second = W.menu("cooldowns.add")
		check("simulation: the menu calls the options function every time it opens, so a spell learned meanwhile is in the second list", #second == #first + 1 and second[2] == "Aaa New Spell"
			and W.control("cooldowns.add").menuOpens == 2)
		check("simulation: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	-- 76. The spell list: /flatui cooldown add, remove and list.
	do
		local W = cdUp()
		local seen = {}
		local real = W.env.C_Spell.GetSpellInfo
		W.env.C_Spell.GetSpellInfo = function(text, ...)
			seen[#seen + 1] = text
			return real(text, ...)
		end
		check("list add: by spell ID appends it and says so", W.slash("cooldown add 408") == "Added Kidney Shot." and cdList(cdSaved(W)) == "408", W.out[1])
		check("list add: by name keeps the capitals on the way to the game and appends the spell the game found", W.slash("cooldown add Blind") == "Added Blind." and seen[#seen] == "Blind" and cdList(cdSaved(W)) == "408,2094", seen[#seen])
		check("list add: by a name in lower case with spaces", W.slash("cooldown add   vanish  ") == "Added Vanish." and seen[#seen] == "vanish" and cdList(cdSaved(W)) == "408,2094,1856")
		check("list add: by a spell link from the spell book", W.slash("cooldown add |cff71d5ff|Hspell:1766:0|h[Kick]|h|r") == "Added Kick." and cdList(cdSaved(W)) == "408,2094,1856,1766")
		W.slash("cooldown remove 1766")
		check("list add: by the text spell:<id>", W.slash("cooldown add spell:1766") == "Added Kick." and cdList(cdSaved(W)) == "408,2094,1856,1766")
		check("list add: a spell that is picked changes nothing and says so", W.slash("cooldown add 408") == "Kidney Shot is already picked." and W.slash("cooldown add kidney shot") == "Kidney Shot is already picked."
			and cdList(cdSaved(W)) == "408,2094,1856,1766")
		check("list add: an unknown name says what was typed", W.slash("cooldown add kidny shot") == 'No spell found for "kidny shot".' and cdList(cdSaved(W)) == "408,2094,1856,1766")
		check("list add: an ID the game has no name for", W.slash("cooldown add 424242") == 'No spell found for "424242".' and cdList(cdSaved(W)) == "408,2094,1856,1766")
		check("list add: zero, a negative number and a fraction", W.slash("cooldown add 0") == 'No spell found for "0".'
			and W.slash("cooldown add -5") == 'No spell found for "-5".' and W.slash("cooldown add 1.5") == 'No spell found for "1.5".' and cdList(cdSaved(W)) == "408,2094,1856,1766")
		check("list add: a spell the character does not know can be added by its ID", W.slash("cooldown add 57934") == "Added Tricks of the Trade." and cdList(cdSaved(W)) == "408,2094,1856,1766,57934")
		check("list add: the command word and the verb in capitals", W.slash("COOLDOWN ADD 1752") == "Added Sinister Strike." and cdList(cdSaved(W)) == "408,2094,1856,1766,57934,1752")
		check("list remove: by ID", W.slash("cooldown remove 57934") == "Removed Tricks of the Trade." and cdList(cdSaved(W)) == "408,2094,1856,1766,1752")
		check("list remove: by name, in the order of the rest", W.slash("cooldown remove Blind") == "Removed Blind." and cdList(cdSaved(W)) == "408,1856,1766,1752")
		check("list remove: by link", W.slash("cooldown remove |cff71d5ff|Hspell:1752:0|h[Sinister Strike]|h|r") == "Removed Sinister Strike." and cdList(cdSaved(W)) == "408,1856,1766")
		check("list remove: a spell that is not picked changes nothing and says so", W.slash("cooldown remove 2094") == "Blind is not picked." and W.slash("cooldown remove blind") == "Blind is not picked."
			and cdList(cdSaved(W)) == "408,1856,1766")
		check("list remove: an ID nobody has a name for", has(W.slash("cooldown remove 999999"), "is not picked.") and W.slash("cooldown remove zzz") == 'No spell found for "zzz".' and cdList(cdSaved(W)) == "408,1856,1766")
		check("list: the list in row order", W.slash("cooldown list") == "1. Kidney Shot (408)\n2. Vanish (1856)\n3. Kick (1766)", W.slash("cooldown list"))
		W.sp.data[SP.VANISH].known = false
		W.sp.data[SP.VANISH].line = nil
		check("list: a spell the character no longer knows is marked", W.slash("cooldown list") == "1. Kidney Shot (408)\n2. Vanish (1856), not known\n3. Kick (1766)", W.slash("cooldown list"))
		check("list: and stays in the list", cdList(cdSaved(W)) == "408,1856,1766")
		check("list: an empty list", (function() W.slash("cooldown remove 408") W.slash("cooldown remove 1856") W.slash("cooldown remove 1766") return W.slash("cooldown list") end)() == "No spells picked.")
		local help = "/flatui cooldown add 2094 - a spell ID, a name or a shift-clicked spell\n/flatui cooldown remove 2094\n/flatui cooldown list"
		check("slash: cooldown alone prints the three help lines", W.slash("cooldown") == help, W.slash("cooldown"))
		check("slash: an unknown word after cooldown prints them too", W.slash("cooldown frobnicate 5") == help and W.slash("cooldown   ") == help)
		check("slash: the general help is the lines of the command and then the help of each module, whatever the word, and has the three cooldown lines", (function()
			local all = TOC.allHelp(W)
			return W.slash("help me") == all and W.slash("bogus") == all and has(all, help) and has(all, "own UI scale\n/flatui taint - the action button click path, checked for values an add-on changed\n/flatui cvar - each game setting row")
		end)())
		check("list: no violation or error", cdQuiet(W) and #W.out >= 0, cdTrouble(W))
	end

	do
		-- Forty spells at most.
		local W = cdUp()
		local ids = cdMany(W, 41)
		local worst = {}
		for i = 1, 40 do
			local said = W.slash("cooldown add " .. ids[i])
			if said ~= "Added " .. string.format("Test Spell %02d", i) .. "." then
				worst[#worst + 1] = i .. ": " .. said
			end
		end
		check("list add: forty spells are taken", #worst == 0 and #cdSaved(W) == 40, table.concat(worst, "; "))
		check("list add: the forty-first is refused and says so", W.slash("cooldown add " .. ids[41]) == "40 spells is the most." and #cdSaved(W) == 40 and cdSaved(W)[40] == ids[40])
		check("list add: by name too", W.slash("cooldown add Test Spell 41") == "40 spells is the most." and #cdSaved(W) == 40)
		check("list add: a spell that is picked still says so when the list is full", W.slash("cooldown add " .. ids[3]) == "Test Spell 03 is already picked." and #cdSaved(W) == 40)
		check("list remove: makes room for another", W.slash("cooldown remove " .. ids[1]) == "Removed Test Spell 01." and W.slash("cooldown add " .. ids[41]) == "Added Test Spell 41." and #cdSaved(W) == 40 and cdSaved(W)[40] == ids[41])
		check("list: the dropdown's pick has the same limit", (function()
			W.sp.data[SP.KICK].known = true
			local labels = W.menu("cooldowns.add")
			local at
			for i, label in ipairs(labels) do
				if label == "Kick" then
					at = i
				end
			end
			W.out = {}
			W.pickAt("cooldowns.add", at)
			return W.out[1] == "40 spells is the most." and #cdSaved(W) == 40
		end)())
		check("list add: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- What is saved is cleaned each time it is read.
		local messy = { 408, "2094", 0, -3, 1.5, 408, 1856, true, 1e12, 1766, 2 ^ 31, {}, 1752 }
		local W = cdUp({ char = { cooldowns = messy, other = 5 } })
		check("saved list: text, zero, negative numbers, fractions, repeats and things that are not numbers go; the order is kept", W.slash("cooldown list") == "1. Kidney Shot (408)\n2. Vanish (1856)\n3. Kick (1766)\n4. Sinister Strike (1752)", W.slash("cooldown list"))
		check("saved list: the cleaned list is what is saved, and other keys of the saved data are kept", cdList(cdSaved(W)) == "408,1856,1766,1752" and W.env.FlatUICharDB.other == 5)
		local long = {}
		for i = 1, 45 do
			long[i] = 5000 + i
		end
		local L = cdUp({ char = { cooldowns = long } })
		cdMany(L, 45)
		check("saved list: more than forty is cut to the first forty", L.slash("cooldown add 408") == "40 spells is the most." and #cdSaved(L) == 40 and cdSaved(L)[40] == 5040, #cdSaved(L))
		local N = cdUp({ char = { cooldowns = "408" } })
		check("saved list: a list that is not a table is replaced", N.slash("cooldown list") == "No spells picked." and type(cdSaved(N)) == "table" and #cdSaved(N) == 0)
		local M = cdUp({ char = { cooldowns = { 408, 1856 } } })
		local mine = cdSaved(M)
		M.slash("cooldown list")
		check("saved list: a clean list is used as it is and not copied", cdSaved(M) == mine)
		local missing = cdUp()
		check("FlatUICharDB: missing becomes a table", type(missing.env.FlatUICharDB) == "table" and type(missing.env.FlatUICharDB.cooldowns) == "table" and type(missing.env.FlatUICharDB.trackers) == "table"
			and (function()
				local n = 0
				for _ in pairs(missing.env.FlatUICharDB) do
					n = n + 1
				end
				return n == 2
			end)())
		local junk = cdUp({ char = "oops" })
		check("FlatUICharDB: not a table becomes a table, and the list works", type(junk.env.FlatUICharDB) == "table" and junk.slash("cooldown add 408") == "Added Kidney Shot." and cdList(cdSaved(junk)) == "408")
		local keep = cdUp({ char = { cooldowns = { 408 }, future = { 1, 2 } } })
		keep.slash("cooldown add 2094")
		check("FlatUICharDB: other keys are kept when the list changes", keep.env.FlatUICharDB.future[2] == 2 and cdList(cdSaved(keep)) == "408,2094")
		check("saved list: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- Working with the page off and in combat: the list is data, the row follows when it can.
		local W = cdUp({ saved = { options = { ["cooldowns.enabled"] = false } } }, { SP.KIDNEY })
		local frames = #W.addonFrames
		check("list with the page off: add and remove work and nothing is made", W.slash("cooldown add 2094") == "Added Blind." and W.slash("cooldown remove 408") == "Removed Kidney Shot." and cdList(cdSaved(W)) == "2094"
			and #W.addonFrames == frames and cdHolder(W) == nil, W.out[1])
		W.change("cooldowns.enabled", true)
		W.flush()
		check("list with the page off: and the row has what was picked when the page goes on", cdRowIcons(W) == "136175")
		local C = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		C.combat = true
		check("list in combat: add and remove work", C.slash("cooldown add 1856") == "Added Vanish." and C.slash("cooldown remove 2094") == "Removed Blind." and cdList(cdSaved(C)) == "408,1856")
		check("list in combat: the row is as it was, and nothing was made, shown, hidden or moved", cdRowIcons(C) == "132298,136175" and #cdIcons(C) == 2 and cdQuiet(C), cdTrouble(C))
		C.combat = false
		C.fire("PLAYER_REGEN_ENABLED")
		check("list in combat: the row changes when combat ends", cdRowIcons(C) == "132298,132331" and cdQuiet(C), cdRowIcons(C))
	end

	-- 77. The two dropdowns of the page, as a player uses them.
	do
		local W = cdUp()
		local add = W.menu("cooldowns.add")
		check("Add a spell: the first line, then the known, active, highest rank spells that have a cooldown, by name", table.concat(add, ",") == "Choose a spell,Blind,Charged Strike,Expose Armor,Kick,Kidney Shot,Vanish", table.concat(add, ","))
		check("Remove a spell: only the first line while nothing is picked", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell")
		check("the dropdowns show their first line", W.read("cooldowns.add") == "Choose a spell" and W.read("cooldowns.remove") == "Choose a spell")
		local picks, real = 0, W.ns.CooldownAdd
		W.ns.CooldownAdd = function(...)
			picks = picks + 1
			return real(...)
		end
		W.out = {}
		W.change("cooldowns.add", "Kick")
		W.flush()
		check("Add a spell: choosing a line calls ns.CooldownAdd once with the spell ID, adds the spell and says so", picks == 1 and cdList(cdSaved(W)) == "1766" and W.out[1] == "Added Kick." and #W.out == 1, W.out[1])
		check("Add a spell: and the dropdown goes back to its first line, the setting reads 0", W.read("cooldowns.add") == "Choose a spell" and W.setting("cooldowns.add"):GetValue() == 0 and W.shown("cooldowns.add") == 0)
		check("Add a spell: the spell just added is no longer offered", table.concat(W.menu("cooldowns.add"), ",") == "Choose a spell,Blind,Charged Strike,Expose Armor,Kidney Shot,Vanish")
		W.change("cooldowns.add", "Vanish")
		W.change("cooldowns.add", "Blind")
		W.flush()
		check("Remove a spell: lists what is picked in row order", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Kick,Vanish,Blind", table.concat(W.menu("cooldowns.remove"), ","))
		W.sp.data[SP.VANISH].known = false
		W.sp.data[SP.VANISH].line = nil
		check("Remove a spell: a spell the character does not know is marked", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Kick,Vanish (not known),Blind")
		W.out = {}
		W.change("cooldowns.remove", "Vanish (not known)")
		W.flush()
		check("Remove a spell: choosing a line removes that spell, says so, and the dropdown is back at its first line", cdList(cdSaved(W)) == "1766,2094" and W.out[1] == "Removed Vanish." and W.read("cooldowns.remove") == "Choose a spell"
			and W.setting("cooldowns.remove"):GetValue() == 0)
		W.out = {}
		W.pickAt("cooldowns.add", 1)
		W.pickAt("cooldowns.remove", 1)
		W.flush()
		check("the first line of either dropdown does nothing", #W.out == 0 and cdList(cdSaved(W)) == "1766,2094")
		check("Add a spell: a spell removed is offered again, with its name", table.concat(W.menu("cooldowns.add"), ",") == "Choose a spell,Charged Strike,Expose Armor,Kidney Shot,Vanish")
		check("the options function runs again each time a menu opens", W.control("cooldowns.add").menuOpens == 3 and W.control("cooldowns.remove").menuOpens >= 4, tostring(W.control("cooldowns.add").menuOpens))
		W.ns.Set("cooldowns.add", 408)
		W.ns.Set("cooldowns.remove", 1766)
		W.ns.Set("cooldowns.add", "x")
		check("a list setting saves nothing, and ns.Set on its path does nothing", W.options()["cooldowns.add"] == nil and W.options()["cooldowns.remove"] == nil and not W.ns.IsSet("cooldowns.add")
			and W.ns.Get("cooldowns.add") == 0 and W.ns.Get("cooldowns.remove") == 0 and cdList(cdSaved(W)) == "1766,2094")
		check("a list setting leaves no entry in the saved variable after the picks", (function()
			for path in pairs(W.options()) do
				if path:find("^cooldowns%.add") or path:find("^cooldowns%.remove") then
					return false
				end
			end
			return true
		end)())
		check("the dropdowns: no violation or error", cdQuiet(W), cdTrouble(W))

		local V = cdUp({ saved = { options = { ["cooldowns.add"] = 408, ["cooldowns.remove"] = 1856, ["cooldowns.size"] = 40 } } })
		check("a value saved under a list setting is dropped when the game loads, and the rest of the page is kept", V.options()["cooldowns.add"] == nil and V.options()["cooldowns.remove"] == nil
			and V.ns.Get("cooldowns.size") == 40 and cdList(cdSaved(V)) == "")

		local E = cdUp()
		check("the dropdowns are usable with the page switch on", E.enabled("cooldowns.add") and E.enabled("cooldowns.remove"))
		E.change("cooldowns.enabled", false)
		check("both dropdowns are greyed with the page switch off, and the switch is not", not E.enabled("cooldowns.add") and not E.enabled("cooldowns.remove") and E.enabled("cooldowns.enabled"))
		E.change("cooldowns.enabled", true)
		check("and usable again with it on", E.enabled("cooldowns.add") and E.enabled("cooldowns.remove"))
	end

	do
		-- Which spells are offered.
		local W = cdUp(nil, { SP.KIDNEY })
		W.addSpell(9001, { name = "beta spell", base = 1000 })
		W.addSpell(9002, { name = "Alpha spell", base = 1000 })
		W.addSpell(9003, { name = "Twin", base = 1000 })
		W.addSpell(9004, { name = "Twin", base = 1000 })
		local slots = W.sp.lines[1].slots
		slots[#slots + 1] = SP.KICK
		local labels = table.concat(W.menu("cooldowns.add"), ",")
		check("Add a spell: sorted by name without regard to capitals, spells of one name by ID, a spell in two slots once, and a picked spell not at all",
			labels == "Choose a spell,Alpha spell,beta spell,Blind,Charged Strike,Expose Armor,Kick,Twin,Twin,Vanish", labels)
		check("Add a spell: not the passive, the lower rank, the one without a cooldown, the off spec and hidden lines, the off spec item, the future spell or the one not in the book",
			not has(labels, "Dual Wield") and count(labels, "Expose Armor") == 1 and not has(labels, "Sinister") and not has(labels, "Preparation") and not has(labels, "Cloak") and not has(labels, "Shiv")
			and not has(labels, "Future") and not has(labels, "Tricks"))
		local ids = {}
		for _, entry in ipairs(W.control("cooldowns.add").data.options()) do
			ids[#ids + 1] = entry.value
		end
		check("Add a spell: each line carries its spell ID, the first carries 0", ids[1] == 0 and ids[2] == 9002 and ids[#ids] == SP.VANISH and table.concat(ids, ","):find("8650", 1, true) ~= nil and not table.concat(ids, ","):find("8647", 1, true))
		W.sp.data[SP.EXPOSE3].lowRank = true
		W.sp.data[SP.EXPOSE1].lowRank = false
		check("Add a spell: the rank the game calls the highest is the one offered", (function()
			for _, entry in ipairs(W.control("cooldowns.add").data.options()) do
				if entry.label == "Expose Armor" then
					return entry.value == SP.EXPOSE1
				end
			end
		end)())
		check("Add a spell: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- GetSpellBaseCooldown is not in Blizzard's documentation: without it, with it failing, withheld or odd, every spell that is not passive is offered.
		local all = "Choose a spell,Blind,Charged Strike,Expose Armor,Kick,Kidney Shot,Sinister Strike,Vanish"
		local cases = { { "missing", { without = { GetSpellBaseCooldown = true } } }, { "raising", false, "error" }, { "withheld", false, "secret" }, { "returning nothing", false, "nothing" }, { "returning text", false, "string" } }
		for _, case in ipairs(cases) do
			local o = case[2] or {}
			local W = newWorld({ cooldowns = true, without = o.without })
			cdBook(W)
			if case[3] then
				W.sp.fault.GetSpellBaseCooldown = case[3]
			end
			W.login()
			W.flush()
			local labels = table.concat(W.menu("cooldowns.add"), ",")
			check("Add a spell: GetSpellBaseCooldown " .. case[1] .. ", every spell that is not passive, off spec or a lower rank is offered", labels == all, labels)
			check("Add a spell: GetSpellBaseCooldown " .. case[1] .. ", no violation and no error", cdQuiet(W), cdTrouble(W))
		end
		local S = newWorld({ cooldowns = true, without = { C_SpellBook = true } })
		cdBook(S)
		S.login()
		S.flush()
		check("Add a spell: a client without the spell book functions offers only the first line", table.concat(S.menu("cooldowns.add"), ",") == "Choose a spell" and cdQuiet(S) and not has(S.status(), "stopped"), cdTrouble(S))
		local N = newWorld({ cooldowns = true, without = { ["Enum.SpellBookItemType"] = true } })
		cdBook(N)
		N.login()
		check("Add a spell: a client without the item type enum offers only the first line", table.concat(N.menu("cooldowns.add"), ",") == "Choose a spell" and cdQuiet(N), cdTrouble(N))
		local T = newWorld({ cooldowns = true, without = { C_Timer = true }, char = { cooldowns = {} } })
		cdBook(T)
		T.login()
		local ok = pcall(T.pickAt, "cooldowns.add", 2)
		check("Add a spell: on a client without C_Timer a pick still adds the spell and raises nothing", ok and cdList(cdSaved(T)) == "2094" and cdQuiet(T), cdList(cdSaved(T)))
	end

	-- 78. The row of icons.
	do
		local P = newWorld()
		P.login()
		local E = cdUp()
		check("row: with no spell picked nothing is made", #E.addonFrames == #P.addonFrames and #E.addonTextures == #P.addonTextures and #E.addonFonts == 0 and #E.cdFrames == 0 and cdHolder(E) == nil,
			#E.addonFrames .. "/" .. #P.addonFrames)
		check("row: and the status counts nothing", cdStatusLine(E) == "Cooldowns: on, 0 styled", cdStatusLine(E))
		local W = cdUp(nil, { SP.KIDNEY })
		local icons = cdIcons(W)
		local rec = icons[1]
		check("row: one known spell makes one icon frame with a texture, a Cooldown, a font string and a frame above the sweep for the count", #icons == 1 and rec and rec.texture and rec.cooldown and rec.count and rec.top)
		check("row: that is a holder, the icon, the sweep, the count frame and the outline's frame: five frames", #W.addonFrames - #P.addonFrames == 5, #W.addonFrames - #P.addonFrames)
		check("row: and six textures (the icon, the backdrop and four edges), one font string and one Cooldown", #W.addonTextures - #P.addonTextures == 6 and #W.addonFonts == 1 and #W.cdFrames == 1,
			(#W.addonTextures - #P.addonTextures) .. " " .. #W.addonFonts .. " " .. #W.cdFrames)
		local unowned = {}
		for _, list in ipairs({ W.addonFrames, W.addonTextures, W.addonFonts }) do
			for _, x in ipairs(list) do
				if not W.ns.Own[x] then
					unowned[#unowned + 1] = tostring(x.layer or x.objectType)
				end
			end
		end
		check("row: every frame, texture and font string it made is in ns.Own", #unowned == 0, table.concat(unowned, ","))
		local holder = cdHolder(W)
		check("row: the holder is a 1 x 1 frame on UIParent, with the script that rechecks and sweeps", holder.width == 1 and holder.height == 1 and holder.parent == W.env.UIParent and holder.shown and type(holder.scripts.OnUpdate) == "function")
		check("row: the icon is the spell's picture, cropped 8 percent, in a frame 36 units square", rec.texture.file == 132298 and rec.texture.allPoints == rec.frame and rec.texture.texCoord and near(rec.texture.texCoord[1], 0.08) and near(rec.texture.texCoord[2], 0.92)
			and near(rec.texture.texCoord[3], 0.08) and near(rec.texture.texCoord[4], 0.92) and rec.frame.width == 36 and rec.frame.height == 36)
		local cd = rec.cooldown.cd
		check("row: the Cooldown has all points of the icon, no edge and no flash, a dark sweep, and the numbers on", rec.cooldown.allPoints == rec.frame and cd.drawEdge == false and cd.drawBling == false and cd.swipeColour
			and cd.swipeColour[1] == 0 and cd.swipeColour[2] == 0 and cd.swipeColour[3] == 0 and cd.swipeColour[4] == 0.7 and cd.hideNumbers == false and cd.swipeFile == nil)
		check("row: it runs the icon's update when the game says a cooldown has ended", type(rec.cooldown.scripts.OnCooldownDone) == "function")
		local cp = rec.count.points[1]
		check("row: the count is at the bottom right of a frame over the icon, one level above the sweep", rec.top.allPoints == rec.frame and cp and cp[1] == "BOTTOMRIGHT" and cp[2] == rec.top and cp[3] == "BOTTOMRIGHT" and cp[4] == -2 and cp[5] == 2
			and rec.top.level == rec.cooldown.level + 1 and rec.count.layer == "OVERLAY")
		local outline
		for _, child in ipairs(rec.frame.children) do
			if #child.regions == 4 then
				outline = child
			end
		end
		check("row: the icon has the thin border of the addon and a backdrop", outline and ringed(W, outline, 1, 0, 0, 0) and (function()
			for _, r in ipairs(rec.frame.regions) do
				if r.layer == "BACKGROUND" then
					return r.shown and r.allPoints == rec.frame
				end
			end
		end)())
		check("row: the status counts the icon", cdStatusLine(W) == "Cooldowns: on, 1 styled", cdStatusLine(W))
		check("row: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- The row is in the order the spells were picked, and holds the spells the character knows.
		local W = cdUp(nil, { SP.VANISH, SP.KIDNEY, SP.BLIND })
		check("row: the icons are in the order the spells were picked", cdRowIcons(W) == "132331,132298,136175", cdRowIcons(W))
		W.sp.data[SP.KIDNEY].known = false
		W.sp.data[SP.KIDNEY].line = nil
		check("row: nothing changes until the game says the spells changed", cdRowIcons(W) == "132331,132298,136175")
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("row: a spell the character does not know leaves no icon and no gap", cdRowIcons(W) == "132331,136175" and #cdIcons(W) == 3 and cdPlaced(W, 36, 3, 12, "center", "down") == "", cdPlaced(W, 36, 3, 12, "center", "down"))
		check("row: and it stays in the saved list", cdList(cdSaved(W)) == "1856,408,2094")
		W.sp.data[SP.KIDNEY].known = true
		W.sp.data[SP.KIDNEY].line = 1
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("row: when the spell is known again and SPELLS_CHANGED comes, it is back in its place", cdRowIcons(W) == "132331,132298,136175" and cdPlaced(W, 36, 3, 12, "center", "down") == "")
		W.sp.data[SP.BLIND].known = false
		W.sp.data[SP.BLIND].line = nil
		W.fire("ACTIVE_TALENT_GROUP_CHANGED")
		W.flush()
		check("row: a change of talent set takes a lost spell out", cdRowIcons(W) == "132331,132298")
		W.sp.data[SP.BLIND].known = true
		W.sp.data[SP.BLIND].line = 1
		W.fire("PLAYER_TALENT_UPDATE")
		W.flush()
		check("row: and puts it back", cdRowIcons(W) == "132331,132298,136175")
		W.sp.data[SP.BLIND].known = false
		W.sp.data[SP.BLIND].lowRank = true
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("row: a lower rank the character still has counts as known", cdRowIcons(W) == "132331,132298,136175")
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		check("row: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- 13 spells at 12 per row make two rows. Every direction, both ways for the extra rows.
		local W
		local ids = {}
		for i = 1, 13 do
			ids[i] = 5000 + i
		end
		W = newWorld({ cooldowns = true, char = { cooldowns = ids } })
		cdBook(W)
		cdMany(W, 13)
		W.login()
		W.flush()
		check("row: 13 spells at 12 per row are 13 icons in two rows, from the middle and below", #cdShown(W) == 13 and cdPlaced(W, 36, 3, 12, "center", "down") == "", cdPlaced(W, 36, 3, 12, "center", "down"))
		local frames, textures = #W.addonFrames, #W.addonTextures
		local grows = { { "From the middle", "center" }, { "Left to right", "right" }, { "Right to left", "left" } }
		local rows = { { "Below", "down" }, { "Above", "up" } }
		for _, g1 in ipairs(grows) do
			for _, r1 in ipairs(rows) do
				W.change("cooldowns.grow", g1[1])
				W.change("cooldowns.rows", r1[1])
				W.flush()
				local wrong = cdPlaced(W, 36, 3, 12, g1[2], r1[2])
				check("row: 13 icons, " .. g1[1] .. ", extra rows " .. r1[1] .. ", each at the point the design gives", wrong == "", wrong)
			end
		end
		W.change("cooldowns.grow", "From the middle")
		W.change("cooldowns.rows", "Below")
		local sizes = { { 20, 0, 5 }, { 64, 20, 4 }, { 16, 1, 1 }, { 24, 7, 13 }, { 36, 3, 20 }, { 30, 2, 6 } }
		for _, s in ipairs(sizes) do
			W.change("cooldowns.size", s[1])
			W.change("cooldowns.spacing", s[2])
			W.change("cooldowns.perRow", s[3])
			for _, g1 in ipairs(grows) do
				for _, r1 in ipairs(rows) do
					W.change("cooldowns.grow", g1[1])
					W.change("cooldowns.rows", r1[1])
					W.flush()
					local wrong = cdPlaced(W, s[1], s[2], s[3], g1[2], r1[2])
					check("row: size " .. s[1] .. ", spacing " .. s[2] .. ", " .. s[3] .. " per row, " .. g1[1] .. ", " .. r1[1], wrong == "", wrong)
				end
			end
		end
		check("row: changing the size, spacing, per row, direction and rows moved the frames that were there and made no new ones", #W.addonFrames == frames and #W.addonTextures == textures and #cdIcons(W) == 13,
			#W.addonFrames .. "/" .. frames)
		W.change("cooldowns.size", 36)
		W.change("cooldowns.spacing", 3)
		W.change("cooldowns.perRow", 12)
		W.change("cooldowns.grow", "From the middle")
		W.change("cooldowns.rows", "Below")
		W.flush()
		W.slash("cooldown remove 5013")
		W.flush()
		check("row: removing a spell hides one frame and keeps it", #cdShown(W) == 12 and #cdIcons(W) == 13 and not cdIcons(W)[13].frame.shown and cdPlaced(W, 36, 3, 12, "center", "down") == "" and #W.addonFrames == frames)
		W.slash("cooldown add 5013")
		W.flush()
		check("row: adding it again shows the frame that was hidden, and makes no new one", #cdShown(W) == 13 and #W.addonFrames == frames and cdPlaced(W, 36, 3, 12, "center", "down") == "")
		check("row: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- Position.
		local W = cdUp(nil, { SP.KIDNEY })
		local holder = cdHolder(W)
		local function at() return holder.points[1] end
		local p = at()
		check("position: the middle of the screen by default: the holder's centre at the centre of the screen, 160 units down", #holder.points == 1 and p[1] == "CENTER" and p[2] == W.env.UIParent and p[3] == "CENTER" and p[4] == 0 and p[5] == -160,
			p and (p[1] .. " " .. g(p[4]) .. " " .. g(p[5])))
		W.change("cooldowns.x", 100)
		W.change("cooldowns.y", -100)
		W.flush()
		p = at()
		check("position: the offsets move it", #holder.points == 1 and p[2] == W.env.UIParent and p[4] == 100 and p[5] == -260)
		W.change("cooldowns.place", "Under the personal resource display")
		W.flush()
		p = at()
		check("position: under the personal resource display is the holder's centre at its bottom, 4 units down, and the offsets still apply", #holder.points == 1 and p[1] == "CENTER" and p[2] == W.prd.alt[1] and p[3] == "BOTTOM" and p[4] == 100 and p[5] == -104)
		W.change("cooldowns.x", -800)
		W.change("cooldowns.y", 800)
		W.flush()
		p = at()
		check("position: the largest offsets", p[4] == -800 and p[5] == 796)
		W.change("cooldowns.place", "Middle of the screen")
		W.flush()
		p = at()
		check("position: and back to the middle of the screen", p[2] == W.env.UIParent and p[3] == "CENTER" and p[4] == -800 and p[5] == 640)
		check("position: no violation or error, and no note", cdQuiet(W) and cdStatusLine(W) == "Cooldowns: on, 1 styled" and not has(W.status(), "personal resource display"), cdTrouble(W))
	end

	do
		-- The personal resource display is missing, forbidden or has no position: the row is in the middle of the screen, and the status says so.
		local cases = {
			{ "missing", { missing = { PersonalResourceDisplayFrame = true } } },
			{ "forbidden", { forbidden = { PersonalResourceDisplayFrame = true } } },
			-- The bars hang from the display, so a display with no position leaves them with none.
			{ "without a position", {}, function(W)
				W.prdInner.noRect = true
				W.blizzard(function() W.prdContainer:SetPoint("TOP", W.prdFrame, "TOP", 0, 0) end)
			end },
		}
		for _, case in ipairs(cases) do
			local o = case[2]
			o.cooldowns = true
			o.char = { cooldowns = { SP.KIDNEY } }
			o.saved = { options = { ["cooldowns.place"] = "resource" } }
			local W = newWorld(o)
			cdBook(W)
			if case[3] then
				case[3](W)
			end
			W.login()
			W.flush()
			local p = cdHolder(W).points[1]
			check("position: resource display " .. case[1] .. ", the row is in the middle of the screen", #cdHolder(W).points == 1 and p[2] == W.env.UIParent and p[1] == "CENTER" and p[3] == "CENTER" and p[4] == 0 and p[5] == -160,
				p and (tostring(p[2] == W.env.UIParent) .. " " .. g(p[5])))
			check("position: resource display " .. case[1] .. ", /flatui status says so once and the icons are still laid out", count(W.status(), CD_NO_POSITION) == 1 and cdPlaced(W, 36, 3, 12, "center", "down") == "", W.status())
			check("position: resource display " .. case[1] .. ", no violation, no error, nothing read of a forbidden frame", cdQuiet(W), cdTrouble(W))
			W.change("cooldowns.size", 38)
			check("position: resource display " .. case[1] .. ", the note is not repeated when the row is laid out again", count(W.status(), CD_NO_POSITION) == 1)
			W.change("cooldowns.place", "Middle of the screen")
			check("position: resource display " .. case[1] .. ", the note goes when the middle of the screen is the choice", not has(W.status(), CD_NO_POSITION))
			W.change("cooldowns.place", "Under the personal resource display")
			check("position: resource display " .. case[1] .. ", and comes back when it is the choice again", count(W.status(), CD_NO_POSITION) == 1)
			if case[1] == "without a position" then
				W.prdInner.noRect = false
				W.change("cooldowns.size", 36)
				local q = cdHolder(W).points[1]
				check("position: the display has a position later, the row is under it and the note goes", q[2] == W.prd.alt[1] and q[3] == "BOTTOM" and #cdHolder(W).points == 1 and not has(W.status(), CD_NO_POSITION))
			end
		end
		-- GetLeft that is withheld or fails says nothing about the position: the row stays under the display.
		for _, fault in ipairs({ "secret", "error" }) do
			local W = cdUp({ saved = { options = { ["cooldowns.place"] = "resource" } } }, { SP.KIDNEY })
			cdHolder(W).fault.rect = fault
			W.change("cooldowns.size", 38)
			local p = cdHolder(W).points[1]
			check("position: a rectangle that is " .. (fault == "secret" and "withheld" or "an error") .. " is taken to be there: the row stays under the display, no note, no violation",
				p[2] == W.prd.alt[1] and not has(W.status(), CD_NO_POSITION) and cdQuiet(W), cdTrouble(W))
		end
	end

	-- 79. Combat: nothing is created, shown, hidden, sized or anchored by the row until combat ends; the sweep, the numbers, the dimming and the count still change.
	do
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		local icons = cdIcons(W)
		local clears = icons[1].frame.calls.ClearAllPoints
		local snap = cdSnapshot(W)
		W.combat = true
		check("combat: add and remove still work", W.slash("cooldown add 1856") == "Added Vanish." and W.slash("cooldown remove 2094") == "Removed Blind." and cdList(cdSaved(W)) == "408,1856")
		W.change("cooldowns.size", 48)
		W.change("cooldowns.spacing", 6)
		W.change("cooldowns.perRow", 2)
		W.change("cooldowns.grow", "Left to right")
		W.change("cooldowns.rows", "Above")
		W.change("cooldowns.place", "Middle of the screen")
		W.change("cooldowns.x", 30)
		W.change("cooldowns.manager", false)
		W.fire("SPELLS_CHANGED")
		W.fire("PLAYER_TALENT_UPDATE")
		W.fire("ACTIVE_TALENT_GROUP_CHANGED")
		W.flush()
		check("combat: whatever changed, no frame is created, shown, hidden, sized or anchored", cdSnapshot(W) == snap and #cdIcons(W) == 2 and cdHolder(W).shown, cdSnapshot(W))
		check("combat: no violation, not even a read or a call on a protected frame", cdQuiet(W), cdTrouble(W))
		check("combat: the changes are kept", W.ns.Get("cooldowns.size") == 48 and W.ns.Get("cooldowns.perRow") == 2 and W.ns.Get("cooldowns.grow") == "right" and W.ns.Get("cooldowns.manager") == false)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: the row is laid out once for all the changes", icons[1].frame.calls.ClearAllPoints == clears + 1, icons[1].frame.calls.ClearAllPoints - clears)
		check("combat ends: with the new list, size, spacing, direction and position", cdRowIcons(W) == "132298,132331" and cdPlaced(W, 48, 6, 2, "right", "up") == "" and #cdIcons(W) == 2, cdPlaced(W, 48, 6, 2, "right", "up"))
		local p = cdHolder(W).points[1]
		check("combat ends: and the holder is in the middle of the screen with the offset", p[2] == W.env.UIParent and p[4] == 30 and p[5] == -160 and cdQuiet(W), cdTrouble(W))
		local before = icons[1].frame.calls.ClearAllPoints
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends again: nothing more happens", icons[1].frame.calls.ClearAllPoints == before)
	end

	do
		-- A new UI scale or a new Edit Mode layout in combat: the row is laid out again when combat ends.
		local W = cdUp(nil, { SP.KIDNEY })
