		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: and the row is laid out again, once", frame.calls.ClearAllPoints == clears + 1 and cdQuiet(W), frame.calls.ClearAllPoints - clears)
	end

	do
		-- A new icon is made and shown only after combat; one removed stays until then.
		local W = cdUp(nil, { SP.KIDNEY })
