		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: and is made then, once", #W.addonFrames == frames + 4 and #cdIcons(W) == 2 and cdRowIcons(W) == "132298,136175" and cdQuiet(W), #W.addonFrames - frames)
		W.combat = true
		W.slash("cooldown remove 408")
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("combat: a spell removed in combat stays in the row until combat ends", cdRowIcons(W) == "132298,136175")
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: and then it goes", cdRowIcons(W) == "136175" and #cdIcons(W) == 2 and cdQuiet(W))
	end

	do
		-- Login in combat.
		local W = newWorld({ cooldowns = true, combat = true, char = { cooldowns = { SP.KIDNEY, SP.BLIND } } })
		cdBook(W)
		W.login()
		W.flush()
		check("login in combat: no holder and no icon are made, and nothing is read or called on a protected frame", cdHolder(W) == nil and #W.cdFrames == 0 and cdQuiet(W), cdTrouble(W))
		check("login in combat: the status says the part is on", cdStatusLine(W) == "Cooldowns: on, 0 styled", cdStatusLine(W))
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELLS_CHANGED")
		check("login in combat: events change nothing", cdHolder(W) == nil and cdQuiet(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("login in combat: the row appears when combat ends", cdRowIcons(W) == "132298,136175" and cdPlaced(W, 36, 3, 12, "center", "down") == "" and cdQuiet(W), cdTrouble(W))
	end

	do
		-- What is allowed in combat: the sweep, the numbers, the dimming and the count.
		local W = cdUp(nil, { SP.KIDNEY, SP.CHARGED })
		local k, c = cdIcons(W)[1], cdIcons(W)[2]
		local frames, textures = #W.addonFrames, #W.addonTextures
		W.combat = true
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCharges(SP.CHARGED, 2, true)
