		W.fire("SPELL_UPDATE_CHARGES")
		check("combat: SPELL_UPDATE_COOLDOWN still draws the sweep and dims the icon", k.cooldown.cd.sweep and k.cooldown.cd.sweep.kind == "object" and k.texture.desaturated == true and near(k.texture.vertex[1], 0.6))
		check("combat: SPELL_UPDATE_CHARGES still sets the count and the recharge sweep", c.count.text == "2" and c.cooldown.cd.sweep and c.cooldown.cd.sweep.info.kind == "charge" and c.texture.desaturated == false)
		W.change("cooldowns.numbers", false)
		check("combat: Countdown numbers off reaches every icon at once", k.cooldown.cd.hideNumbers == true and c.cooldown.cd.hideNumbers == true)
		W.change("cooldowns.dim", false)
		check("combat: Dim on cooldown off gives the colour back at once", k.texture.desaturated == false and k.texture.vertex[1] == 1)
		W.change("cooldowns.dim", true)
		W.change("cooldowns.numbers", true)
		check("combat: and on again", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6) and k.cooldown.cd.hideNumbers == false)
		W.finishCooldown(SP.KIDNEY)
		check("combat: the end of a cooldown clears the dimming", k.texture.desaturated == false and k.texture.vertex[1] == 1)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.setCooldown(SP.KIDNEY, "ready")
		W.frameUpdate(0.2)
