		check("combat: and in all of it nothing is made and nothing breaks", #W.addonFrames == frames and #W.addonTextures == textures and cdQuiet(W), cdTrouble(W))
		W.change("cooldowns.enabled", false)
		check("combat: the page switched off in combat hides the row at once, and the layout waits", not cdHolder(W).shown and k.frame.shown and cdQuiet(W), cdTrouble(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: and hides it", not cdHolder(W).shown and cdQuiet(W))
	end

	-- 80. What an icon shows.
	do
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND, SP.CHARGED })
		local k, b, c = cdIcons(W)[1], cdIcons(W)[2], cdIcons(W)[3]
		check("icons: ready spells have no sweep, full colour and an empty count", k.cooldown.cd.sweep == nil and not k.cooldown.shown and k.texture.desaturated == false and k.texture.vertex[1] == 1 and k.count.text == ""
			and b.count.text == "" and c.count.text == "3")
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		local sweep = k.cooldown.cd.sweep
		check("cooldown: a spell on cooldown gets SetCooldownFromDurationObject with the object from GetSpellCooldownDuration(id, true), unread", sweep and sweep.kind == "object" and sweep.info.spell == SP.KIDNEY and sweep.info.ignoreGCD == true
			and sweep.info.kind == "cooldown" and W.durations[k.cooldown.cd.object] == sweep.info and k.cooldown.shown and k.cooldown.cd.calls.SetCooldown == nil)
		local made = false
		for _, object in ipairs(W.sp.made) do
			made = made or object == k.cooldown.cd.object
		end
		check("cooldown: it is the object the game made, not a copy", made)
		check("cooldown: the spell is dimmed", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6) and near(k.texture.vertex[2], 0.6) and near(k.texture.vertex[3], 0.6))
		check("cooldown: the other spells are not", b.texture.desaturated == false and b.texture.vertex[1] == 1 and b.cooldown.cd.sweep == nil)
		W.setCooldown(SP.BLIND, "gcd")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: a spell that is only on the global cooldown is not dimmed and has no sweep", b.texture.desaturated == false and b.texture.vertex[1] == 1 and b.cooldown.cd.sweep == nil and not b.cooldown.shown)
		W.setCooldown(SP.KIDNEY, "gcd")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: when its cooldown ends and the global cooldown runs, the dimming and the sweep go", k.texture.desaturated == false and k.cooldown.cd.sweep == nil)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.finishCooldown(SP.KIDNEY)
		check("cooldown: OnCooldownDone clears the dimming of a spell that has come off cooldown, with no event", k.texture.desaturated == false and k.texture.vertex[1] == 1 and k.cooldown.cd.sweep == nil)
		check("cooldown: no violation, nothing read of a duration object", cdQuiet(W), cdTrouble(W))
	end

	do
		-- The recheck of icons that are dimmed.
