		local k = cdIcons(W)[1]
		local calls = W.sp.calls.GetSpellCooldown
		W.frameUpdate(0.2)
		W.frameUpdate(0.5)
		check("recheck: when nothing is dimmed it asks the game for nothing", W.sp.calls.GetSpellCooldown == calls, W.sp.calls.GetSpellCooldown - calls)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
