		W.frameUpdate(0.1)
		check("recheck: a fifth of a second, only the dimmed icon is looked at, and its cooldown has ended, so it is updated and no longer dimmed", k.texture.desaturated == false and W.sp.calls.GetSpellCooldown == calls + 2, W.sp.calls.GetSpellCooldown - calls)
		W.frameUpdate(0.2)
		check("recheck: and once it is not dimmed it is not looked at again", W.sp.calls.GetSpellCooldown == calls + 2)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCooldown(SP.BLIND, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		calls = W.sp.calls.GetSpellCooldown
		W.frameUpdate(0.2)
		check("recheck: two dimmed icons, two looks", W.sp.calls.GetSpellCooldown == calls + 2)
		check("recheck: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- tkready: the sound when a cooldown on the icon row is over.
		local T = {}
		function T.up(on, kit)
			local W = cdUp(nil, { SP.KIDNEY, SP.BLIND })
			W.heard = {}
			W.env.PlaySound = function(id)
				W.heard[#W.heard + 1] = id
				return true, 1
			end
			if on ~= nil then
				W.change("cooldowns.readySound", on)
			end
			if kit then
				W.change("trackers.kit", kit)
			end
			return W
		end
		function T.cool(W, id)
			W.setCooldown(id, "cooling")
			W.fire("SPELL_UPDATE_COOLDOWN")
		end
		local W = T.up(nil)
		check("tkready: Sound when ready is off by default", W.env.FlatUICharDB.cooldowns.readySound == nil and #W.heard == 0)
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		W.frameUpdate(0.2)
		check("tkready: with the row off a cooldown that ends plays nothing", #W.heard == 0 and cdQuiet(W), cdTrouble(W))

		W = T.up(true)
		T.cool(W, SP.KIDNEY)
		W.frameUpdate(0.2)
		check("tkready: while the cooldown runs nothing plays", #W.heard == 0)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: OnCooldownDone plays one sound when the cooldown ends", #W.heard == 1 and W.heard[1] == 8959, #W.heard)
		W.frameUpdate(0.2)
		W.frameUpdate(0.2)
		check("tkready: and the recheck after it plays no second sound", #W.heard == 1, #W.heard)
		check("tkready: no violation or error", cdQuiet(W), cdTrouble(W))

		W = T.up(true)
		T.cool(W, SP.KIDNEY)
		W.setCooldown(SP.KIDNEY, "ready")
		W.frameUpdate(0.2)
		check("tkready: the recheck plays one sound when no script ran", #W.heard == 1, #W.heard)
		W.frameUpdate(0.2)
		check("tkready: and plays once only", #W.heard == 1, #W.heard)
		T.cool(W, SP.KIDNEY)
		check("tkready: a new cooldown plays nothing at its start", #W.heard == 1, #W.heard)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: and one more sound when it ends", #W.heard == 2, #W.heard)

		W = T.up(true)
		T.cool(W, SP.KIDNEY)
		W.setCooldown(SP.KIDNEY, "ready")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("tkready: an event that shows the end of the cooldown plays one sound", #W.heard == 1, #W.heard)

		W = T.up(true)
		W.setCooldown(SP.BLIND, "gcd")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.frameUpdate(0.2)
		W.setCooldown(SP.BLIND, "ready")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.frameUpdate(0.2)
		check("tkready: the global cooldown plays nothing", #W.heard == 0, #W.heard)
		T.cool(W, SP.KIDNEY)
		W.setCooldown(SP.KIDNEY, "gcd")
		W.frameUpdate(0.2)
		check("tkready: a cooldown that gives way to the global cooldown plays one sound", #W.heard == 1, #W.heard)

		W = T.up(true)
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: it uses the Raid warning kit by default", W.heard[1] == 8959)
		W = T.up(true, "Alarm")
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: and the kit chosen under Trackers, Sound", W.heard[1] == 12889, tostring(W.heard[1]))

		W = T.up(true)
		W.env.PlaySound = function() return false end
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: a game that plays no sound is one line in the status", select(2, W.status():gsub("the game played no sound, so Sound when ready is silent", "")) == 1, W.status())
		W = T.up(true)
		W.env.PlaySound = function() error("boom", 0) end
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: and a sound that raises raises nothing", has(W.status(), "Sound when ready is silent") and #W.errors == 0, cdTrouble(W))

		W = T.up(true)
		W.env.PlaySound = nil
		T.cool(W, SP.KIDNEY)
		W.finishCooldown(SP.KIDNEY)
		check("tkready: with no PlaySound at all nothing raises", #W.errors == 0, cdTrouble(W))

		W = T.up(true)
		W.env.C_Spell.GetSpellCooldown = function() return nil end
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.frameUpdate(0.2)
		check("tkready: a game that answers nothing about the cooldown plays nothing", #W.heard == 0 and #W.errors == 0, cdTrouble(W))

		W = T.up(true)
		T.cool(W, SP.KIDNEY)
		W.slash("cooldown remove " .. SP.KIDNEY)
		W.frameUpdate(0.2)
		check("tkready: a spell that moves into a dimmed slot plays nothing", #W.heard == 0 and #W.errors == 0, #W.heard)
	end

	do
		-- Cooldown numbers the game withholds: nothing compares, adds or formats them; the sweep, the numbers, the dimming and the count are all handed on.
		local W = cdUp({ cooldowns = { secretTimes = true } }, { SP.KIDNEY, SP.CHARGED })
		local k, c = cdIcons(W)[1], cdIcons(W)[2]
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCharges(SP.CHARGED, 1, true)
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELL_UPDATE_CHARGES")
		W.frameUpdate(0.2)
		check("secret numbers: the sweep is drawn from the duration object and SetCooldown is never called", k.cooldown.cd.sweep and k.cooldown.cd.sweep.kind == "object" and k.cooldown.cd.calls.SetCooldown == nil and c.cooldown.cd.calls.SetCooldown == nil)
		check("secret numbers: nothing was compared, added, indexed or formatted (the withheld value raises on each)", cdQuiet(W) and not has(W.status(), "failed"), cdTrouble(W))
		check("secret numbers: the icon is dimmed", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6))
		check("secret numbers: the charge count is the text the game gave, and the recharge is a sweep", c.count.text == "1" and c.cooldown.cd.sweep and c.cooldown.cd.sweep.info.kind == "charge")
		W.sp.secretCount = true
		W.fire("SPELL_UPDATE_CHARGES")
		check("secret numbers: a charge count that is withheld goes to the font string as it is", rawequal(c.count.text, SECRET) and cdQuiet(W), cdTrouble(W))
		W.sp.secretActive = true
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("secret numbers: isActive withheld goes to SetDesaturated untouched and the colour is left white", rawequal(k.texture.desaturatedArg, SECRET) and k.texture.vertex[1] == 1 and k.texture.vertex[3] == 1 and cdQuiet(W), cdTrouble(W))
		check("secret numbers: and the sweep is still drawn", k.cooldown.cd.sweep and k.cooldown.cd.sweep.kind == "object")
		W.sp.secretActive = false
		W.sp.secretCount = false
		W.sp.secretTimes = false
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("secret numbers: they stop being withheld and the icon is dimmed again", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6) and k.texture.desaturatedArg == true)
	end

	do
		-- Without a duration object the numbers are used when they are plain.
		local variants = { { "no GetSpellCooldownDuration", { without = { ["C_Spell.GetSpellCooldownDuration"] = true } } },
			{ "no SetCooldownFromDurationObject", { cooldowns = { noMethods = { SetCooldownFromDurationObject = true } } } } }
		for _, v in ipairs(variants) do
			local o = v[2]
			local W = cdUp(o, { SP.KIDNEY, SP.BLIND })
			local k, b = cdIcons(W)[1], cdIcons(W)[2]
			W.setCooldown(SP.KIDNEY, "cooling")
			W.fire("SPELL_UPDATE_COOLDOWN")
			local sweep = k.cooldown.cd.sweep
			check("cooldown, " .. v[1] .. ": plain numbers go to SetCooldown(start, duration, modRate)", sweep and sweep.kind == "numbers" and sweep.start == 100 and sweep.duration == 30 and sweep.rate == 1 and k.cooldown.shown and k.cooldown.cd.calls.SetCooldownFromDurationObject == nil)
			check("cooldown, " .. v[1] .. ": the spell is dimmed, a ready one is cleared", k.texture.desaturated == true and b.cooldown.cd.sweep == nil and b.texture.desaturated == false)
			W.setCooldown(SP.KIDNEY, "gcd")
			W.fire("SPELL_UPDATE_COOLDOWN")
			check("cooldown, " .. v[1] .. ": a spell on the global cooldown only is cleared, not dimmed", k.cooldown.cd.sweep == nil and k.texture.desaturated == false)
			check("cooldown, " .. v[1] .. ": no violation, no note about a missing sweep", cdQuiet(W) and not has(W.status(), CD_NO_SWEEP), cdTrouble(W))
			local S = cdUp({ cooldowns = { secretTimes = true, noMethods = o.cooldowns and o.cooldowns.noMethods }, without = o.without }, { SP.KIDNEY, SP.BLIND })
			local sk = cdIcons(S)[1]
			S.setCooldown(SP.KIDNEY, "cooling")
			S.fire("SPELL_UPDATE_COOLDOWN")
			S.fire("SPELL_UPDATE_COOLDOWN")
			S.frameUpdate(0.2)
			check("cooldown, " .. v[1] .. ", numbers withheld: the icon is dimmed and has no sweep, SetCooldown is not called with them", sk.texture.desaturated == true and sk.cooldown.cd.sweep == nil and sk.cooldown.cd.calls.SetCooldown == nil and cdQuiet(S), cdTrouble(S))
			check("cooldown, " .. v[1] .. ", numbers withheld: /flatui status says so, once", count(S.status(), CD_NO_SWEEP) == 1, S.status())
		end
	end

	do
		-- GetSpellCooldown returns nothing, raises, or says something other than a table.
		local W = cdUp(nil, { SP.KIDNEY })
		local k = cdIcons(W)[1]
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: a spell cooling has a sweep", k.cooldown.cd.sweep ~= nil)
		W.sp.fault.GetSpellCooldown = "nothing"
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: GetSpellCooldown returning nothing clears the sweep, counts nothing as failed and stops nothing", k.cooldown.cd.sweep == nil and not k.cooldown.shown and not has(W.status(), "failed") and not has(W.status(), "stopped") and cdQuiet(W))
		W.sp.fault.GetSpellCooldown = nil
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: and it is back when the game answers again", k.cooldown.cd.sweep ~= nil and k.texture.desaturated == true)
		W.sp.fault.GetSpellCooldown = "error"
		for _ = 1, 6 do
			W.fire("SPELL_UPDATE_COOLDOWN")
			W.frameUpdate(0.2)
		end
		check("cooldown: GetSpellCooldown raising clears the sweep", k.cooldown.cd.sweep == nil and not k.cooldown.shown)
		check("cooldown: and counts one failed icon, once however often it is tried, and does not stop the part", W.line("Cooldowns") == "Cooldowns: on, 1 styled, 1 failed. GetSpellCooldown failed", W.line("Cooldowns"))
		check("cooldown: no error reaches the player", #W.errors == 0 and #W.out == 0 and #W.violations == 0, cdTrouble(W))
		for _, fault in ipairs({ "secret", "string" }) do
			local V = cdUp(nil, { SP.KIDNEY })
			V.setCooldown(SP.KIDNEY, "cooling")
			V.sp.fault.GetSpellCooldown = fault
			V.fire("SPELL_UPDATE_COOLDOWN")
			local rec = cdIcons(V)[1]
			check("cooldown: GetSpellCooldown answering with " .. (fault == "secret" and "a withheld value" or "text") .. " clears the sweep and leaves the icon at full colour", rec.cooldown.cd.sweep == nil and rec.texture.desaturated == false and cdQuiet(V)
				and not has(V.status(), "failed"), cdTrouble(V))
		end
	end

	do
		-- Charges.
		local W = cdUp(nil, { SP.CHARGED, SP.KIDNEY })
		local c, k = cdIcons(W)[1], cdIcons(W)[2]
		check("charges: a spell with three charges shows the count the game formats", c.count.text == "3" and k.count.text == "")
		check("charges: and no sweep while all are there", c.cooldown.cd.sweep == nil and c.texture.desaturated == false)
		W.setCharges(SP.CHARGED, 2, true)
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: with charges left and one recharging, the sweep is the recharge, the count is 2 and the icon is not dimmed", c.cooldown.cd.sweep and c.cooldown.cd.sweep.info.kind == "charge" and c.count.text == "2"
			and c.texture.desaturated == false and c.texture.vertex[1] == 1)
		W.setCharges(SP.CHARGED, 0, true)
		W.setCooldown(SP.CHARGED, "cooling")
		W.fire("SPELL_UPDATE_CHARGES")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("charges: with no charge left the sweep is the spell's cooldown, the count 0 and the icon dimmed", c.cooldown.cd.sweep and c.cooldown.cd.sweep.info.kind == "cooldown" and c.count.text == "0" and c.texture.desaturated == true)
		W.setCooldown(SP.CHARGED, "ready")
		W.setCharges(SP.CHARGED, 3, false)
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: all back, no sweep, full colour", c.cooldown.cd.sweep == nil and c.count.text == "3" and c.texture.desaturated == false)
		W.sp.fault.GetSpellDisplayCount = "error"
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: a count the game cannot give is cleared", c.count.text == "" and cdQuiet(W) and not has(W.status(), "failed"), cdTrouble(W))
		W.sp.fault.GetSpellDisplayCount = "nothing"
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: and so is none", c.count.text == "" and cdQuiet(W))
		W.sp.fault.GetSpellDisplayCount = nil
		W.sp.fault.GetSpellCharges = "secret"
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: a charge table that is withheld is no charge info: no count", c.count.text == "" and cdQuiet(W))
		W.sp.fault.GetSpellCharges = "error"
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: and one that fails is none either", c.count.text == "" and cdQuiet(W) and not has(W.status(), "failed"))
		W.sp.fault.GetSpellCharges = nil
		W.sp.data[SP.CHARGED].charges.max = 1
		W.fire("SPELL_UPDATE_CHARGES")
		check("charges: a spell whose most is one has no count", c.count.text == "" and cdQuiet(W))
	end

	do
		-- Countdown numbers and dimming through their controls.
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		local k, b = cdIcons(W)[1], cdIcons(W)[2]
		check("numbers: on by default, every icon lets the game draw them", k.cooldown.cd.hideNumbers == false and b.cooldown.cd.hideNumbers == false)
		W.change("cooldowns.numbers", false)
		check("numbers: Countdown numbers off calls SetHideCountdownNumbers(true) on every icon", k.cooldown.cd.hideNumbers == true and b.cooldown.cd.hideNumbers == true)
		W.change("cooldowns.numbers", true)
		check("numbers: and on again calls it with false", k.cooldown.cd.hideNumbers == false and b.cooldown.cd.hideNumbers == false)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.change("cooldowns.dim", false)
		check("dim: Dim on cooldown off leaves the icon at full colour while it is on cooldown, the sweep stays", k.texture.desaturated == false and k.texture.vertex[1] == 1 and k.cooldown.cd.sweep ~= nil)
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.frameUpdate(0.2)
		check("dim: and stays so on the next event and the recheck", k.texture.desaturated == false and k.texture.vertex[1] == 1)
		W.change("cooldowns.dim", true)
		check("dim: on again dims it at once", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6))
		check("numbers and dim: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	-- 81. Every setting of the page through its control, and the page switch at login, later and off again.
	-- A world with the cooldown manager: two Essential items, two Utility items, a tracked buff item and one that its pool holds but has not handed out.
	local function cdViewerWorld(options, picked)
		local o = {}
		for k, v in pairs(options or {}) do
			o[k] = v
		end
		local copts = {}
		for k, v in pairs(type(o.cooldowns) == "table" and o.cooldowns or {}) do
			copts[k] = v
		end
		copts.viewers = copts.viewers or true
		o.cooldowns = copts
		if picked and not o.char then
			o.char = { cooldowns = picked }
		end
		local W = newWorld(o)
		cdBook(W)
		local items = {}
		if copts.viewers == true or (type(copts.viewers) == "table" and #copts.viewers > 0) then
			local function add(viewer, more)
				if W.cdm.viewers[viewer] then
					items[#items + 1] = W.addViewerItem(viewer, more)
				end
			end
			add("EssentialCooldownViewer")
			add("EssentialCooldownViewer")
			add("UtilityCooldownViewer")
			add("UtilityCooldownViewer")
			add("BuffIconCooldownViewer")
			add("BuffIconCooldownViewer", { inactive = true })
		end
		W.login()
		W.flush()
		return W, items
	end
	-- "Sb" when an item is styled (a border, no backdrop), "hb" when it was and is put back, "." when it never had an outline.
	local function cdItemState(W, rec)
		return W.state(rec.icon)
	end
	local function cdItemsPlain(W, items)
		local wrong = {}
		for i, rec in ipairs(items) do
			if W.cdm.look(rec) ~= rec.pristine then
				wrong[#wrong + 1] = i .. ": " .. W.cdm.look(rec)
			end
		end
		return table.concat(wrong, "; ")
	end
	local function cdOnScreen(W)
		local holder = cdHolder(W)
		return holder and holder.shown and #cdShown(W) or 0
	end

	do
		local function cdEdge(rec)
			for _, child in ipairs(rec.frame.children) do
				if #child.regions == 4 then
					return child.regions[1]
				end
			end
		end
		local function cdBind(rec)
			for _, r in ipairs(rec.top and rec.top.regions or {}) do
				if r.kind == "FontString" and r.template == "NumberFontNormalSmallGray" then
					return r
				end
			end
		end
		local function cdBindText(rec)
			local b = cdBind(rec)
			return b and b.text ~= "" and b.text or "none"
		end
		local function cdBindSize(rec)
			local b = cdBind(rec)
			local size = b and b.font and b.font[2] or 12
			return string.format("%.0f", size) == "24" and "double" or "base"
		end
		-- The calls a client answers for keys: the kidney shot is on the first button of the first extra bar, bound to Shift-1.
		local function cdKeys(W)
			W.env.C_ActionBar = { FindSpellActionButtons = function(id) return id == SP.KIDNEY and { 61 } or nil end }
			W.env.GetBindingKey = function(name) return name == "MULTIACTIONBAR1BUTTON1" and "SHIFT-1" or nil end
			W.env.GetBindingText = function(key) return (key:gsub("SHIFT%-", "S-")) end
		end
		local PROBES = {
			{ "cooldowns.enabled", false, function(W) return tostring(cdOnScreen(W)) end, "3", "0" },
			{ "cooldowns.size", 48, function(W) return g(cdShown(W)[1].frame.width) end, "36", "48" },
			{ "cooldowns.spacing", 6, function(W) return g(cdShown(W)[1].frame.points[1][4]) end, "-57", "-60" },
			{ "cooldowns.perRow", 2, function(W) return cdNum(cdShown(W)[3].frame.points[1][5]) end, "0", "-39" },
			{ "cooldowns.grow", "Left to right", function(W) return g(cdShown(W)[1].frame.points[1][4]) end, "-57", "0", from = "From the middle" },
			{ "cooldowns.grow", "Right to left", function(W) return g(cdShown(W)[1].frame.points[1][4]) end, "-57", "-36", from = "From the middle" },
			{ "cooldowns.rows", "Above", function(W) local p = cdShown(W)[3].frame.points[1] return p[1] .. " " .. g(p[5]) end, "TOPLEFT -39", "BOTTOMLEFT 39", from = "Below", pre = { { "cooldowns.perRow", 2 } } },
			{ "cooldowns.numbers", false, function(W) return tostring(cdShown(W)[1].cooldown.cd.hideNumbers) end, "false", "true" },
			{ "cooldowns.dim", false, function(W) return tostring(cdShown(W)[1].texture.desaturated) end, "true", "false", cooling = true },
			{ "cooldowns.readySound", true, function(W)
				-- Ends the cooldown the probe started, counts the sounds, and starts it again.
				local heard = 0
				W.env.PlaySound = function() heard = heard + 1 return true, 1 end
				W.finishCooldown(SP.KIDNEY)
				W.setCooldown(SP.KIDNEY, "cooling")
				W.fire("SPELL_UPDATE_COOLDOWN")
				return tostring(heard)
			end, "0", "1", cooling = true },
			{ "cooldowns.place", "Under the personal resource display", function(W) local p = cdHolder(W).points[1] return (p[2] == W.env.UIParent and "screen" or "display") .. " " .. g(p[5]) end, "screen -160", "display -4",
				from = "Middle of the screen" },
			{ "cooldowns.x", 100, function(W) return g(cdHolder(W).points[1][4]) end, "0", "100" },
			{ "cooldowns.y", -100, function(W) return g(cdHolder(W).points[1][5]) end, "-160", "-260" },
			{ "cooldowns.crop", 12, function(W) return g(cdShown(W)[1].texture.texCoord[1]) end, "0.08", "0.12" },
			{ "cooldowns.border", false, function(W)
				-- The edges and the background of the first icon: S and B when shown, h and b when hidden.
				local rec, edge, back = cdShown(W)[1]
				for _, child in ipairs(rec.frame.children) do
					if #child.regions == 4 then
						edge = child.regions[1]
					end
				end
				for _, r in ipairs(rec.frame.regions) do
					if r.layer == "BACKGROUND" then
						back = r
					end
				end
				return (edge.shown and "S" or "h") .. (back.shown and "B" or "b")
			end, "SB", "hb" },
			{ "cooldowns.trinkets", true, function(W) return tostring(#cdShown(W)) end, "3", "5",
				setup = function(W)
					local items = { [13] = 7001, [14] = 7002 }
					W.env.GetTime = function() return W.now end
					W.env.GetInventoryItemID = function(_, slot) return items[slot] end
					W.env.C_Item = {
						GetItemIconByID = function(id) return 900000 + id end,
						GetItemCooldown = function() return 0, 0, true end,
					}
				end },
			{ "cooldowns.dimDesat", false, function(W) return tostring(cdShown(W)[1].texture.desaturated) end, "true", "false", cooling = true },
			{ "cooldowns.dimDarkness", 80, function(W) return string.format("%.2f", cdShown(W)[1].texture.vertex[1]) end, "0.60", "0.20", cooling = true },
			{ "cooldowns.coolAlpha", 50, function(W) return g(cdShown(W)[1].frame.alpha) end, "1", "0.5", cooling = true },
			{ "cooldowns.readyAlpha", 0, function(W) return g(cdShown(W)[2].frame.alpha) end, "1", "0", cooling = true },
			{ "cooldowns.idleAlpha", 50, function(W) return g(cdHolder(W).alpha) end, "1", "0.5" },
			{ "cooldowns.borderState", true, function(W) return string.format("%.2f", cdEdge(cdShown(W)[1]).color[1]) end, "0.00", "0.85", cooling = true },
			{ "cooldowns.readyColour", "ff203040", function(W) return string.format("%.2f", cdEdge(cdShown(W)[2]).color[1]) end, "0.30", "0.13", pre = { { "cooldowns.borderState", true } }, cooling = true },
			{ "cooldowns.coolingColour", "ff203040", function(W) return string.format("%.2f", cdEdge(cdShown(W)[1]).color[1]) end, "0.85", "0.13", pre = { { "cooldowns.borderState", true } }, cooling = true },
			{ "cooldowns.flash", true, function(W)
				-- Ends the cooldown the probe started, counts the flashes it played, and starts it again.
				local before = W.cdGroups[1] and W.cdGroups[1].plays or 0
				W.finishCooldown(SP.KIDNEY)
				W.setCooldown(SP.KIDNEY, "cooling")
				W.fire("SPELL_UPDATE_COOLDOWN")
				return tostring((W.cdGroups[1] and W.cdGroups[1].plays or 0) - before)
			end, "0", "1", cooling = true },
			{ "cooldowns.numbersFont", "Large", function(W) return cdShown(W)[1].cooldown.cd.fsFont[1] end, "Fonts\\ARIALN.TTF", "Fonts\\NumberFontNormalLarge.TTF", from = "As the game has it" },
			{ "cooldowns.sweep", false, function(W) return tostring(cdShown(W)[1].cooldown.cd.drawSwipe ~= false) end, "true", "false" },
			{ "cooldowns.sweepAlpha", 30, function(W) return string.format("%.2f", cdShown(W)[1].cooldown.cd.swipeColour[4]) end, "0.70", "0.30" },
			{ "cooldowns.countSize", 200, function(W) local f = cdShown(W)[1].count.font return string.format("%.0f", f and f[2] or 12) end, "12", "24" },
			{ "cooldowns.keybind", true, function(W) return cdBindText(cdShown(W)[1]) end, "none", "S-1", setup = cdKeys },
			{ "cooldowns.keybindSize", 200, function(W) return cdBindSize(cdShown(W)[1]) end, "base", "double", pre = { { "cooldowns.keybind", true } }, setup = cdKeys },
			{ "cooldowns.manager", false, function(W) return W.cdm.look(W.cdProbeItem) == W.cdProbeItem.pristine and "plain" or "styled" end, "styled", "plain", viewers = true },
			{ "cooldowns.enabled", false, function(W) return (W.cdm.look(W.cdProbeItem) == W.cdProbeItem.pristine and "plain" or "styled") .. tostring(cdOnScreen(W)) end, "styled3", "plain0", viewers = true,
				name = "cooldowns.enabled with the manager" },
		}
		local covered = {}
		for _, P in ipairs(PROBES) do
			local path, to, read, base, changed = P[1], P[2], P[3], P[4], P[5]
			covered[path] = true
			local W, items
			if P.viewers then
				W, items = cdViewerWorld(nil, { SP.KIDNEY, SP.BLIND, SP.VANISH })
				W.cdProbeItem = items[1]
			else
				W = cdUp(nil, { SP.KIDNEY, SP.BLIND, SP.VANISH })
			end
			for _, pair in ipairs(P.pre or {}) do
				W.change(pair[1], pair[2])
			end
			if P.setup then
				P.setup(W)
			end
			if P.cooling then
				W.setCooldown(SP.KIDNEY, "cooling")
				W.fire("SPELL_UPDATE_COOLDOWN")
			end
			local row = ROW[path]
			local label = (P.name or path) .. (type(to) == "string" and (" " .. to) or "")
			check(label .. ": at the start", read(W) == base, read(W))
			W.change(path, to)
			W.flush()
			check(label .. ": through its control", read(W) == changed, read(W))
			W.change(path, P.from or row.default)
			W.flush()
			check(label .. ": and back", read(W) == base, read(W))
			W.change(path, to)
			W.flush()
			check(label .. ": and again", read(W) == changed, read(W))
			check(label .. ": no violation or error", cdQuiet(W), cdTrouble(W))
		end
		local missingProbe = {}
		for _, row in ipairs(ALL) do
			if row.page == "cooldowns" and row.kind ~= "list" and not covered[row.path] then
				missingProbe[#missingProbe + 1] = row.path
			end
		end
		check("probes: every setting of the page that holds a value has one", #missingProbe == 0, table.concat(missingProbe, " "))
	end

	do
		-- The page switch off at login: nothing of the part is made or changed. On later. Off again.
		local P = cdUp()
		local W, items = cdViewerWorld({ saved = { options = { ["cooldowns.enabled"] = false } } }, { SP.KIDNEY, SP.BLIND })
		check("page off at login: no frame, texture or font string is made and no Cooldown frame", #W.addonFrames == #P.addonFrames and #W.addonTextures == #P.addonTextures and #W.addonFonts == 0 and #W.cdFrames == 0 and cdHolder(W) == nil,
			#W.addonFrames .. "/" .. #P.addonFrames)
		check("page off at login: every item of the cooldown manager is as the game built it", cdItemsPlain(W, items) == "", cdItemsPlain(W, items))
		check("page off at login: nothing is hooked", W.hooks == P.hooks, W.hooks - P.hooks)
		check("page off at login: the status says off", W.line("Cooldowns") == "Cooldowns: off", W.line("Cooldowns"))
		W.setCooldown(SP.KIDNEY, "cooling")
		for _, event in ipairs({ "SPELL_UPDATE_COOLDOWN", "SPELL_UPDATE_CHARGES", "SPELLS_CHANGED", "PLAYER_TALENT_UPDATE", "ACTIVE_TALENT_GROUP_CHANGED", "PLAYER_ENTERING_WORLD", "COOLDOWN_VIEWER_DATA_LOADED",
			"EDIT_MODE_LAYOUTS_UPDATED" }) do
			W.fire(event)
		end
		W.frameUpdate(1)
		W.flush()
		local calls = W.sp.calls.GetSpellCooldown
		check("page off at login: events and time make nothing, ask the game nothing and change nothing", #W.addonFrames == #P.addonFrames and #W.addonTextures == #P.addonTextures and cdItemsPlain(W, items) == "" and (calls or 0) == 0
			and cdQuiet(W), cdTrouble(W))
		check("page off at login: add and remove still work and make nothing", W.slash("cooldown add 1856") == "Added Vanish." and W.slash("cooldown remove 408") == "Removed Kidney Shot." and #W.addonFrames == #P.addonFrames
			and cdHolder(W) == nil)
		W.slash("cooldown add 408")
		W.slash("cooldown remove 1856")
		W.change("cooldowns.enabled", true)
		W.flush()
		check("page on later: the row is made from the list, in the viewer world", cdOnScreen(W) == 2 and cdRowIcons(W) == "136175,132298", cdRowIcons(W))
		check("page on later: and the items of the cooldown manager are styled", W.look(items[1].icon).state == "Sb" and W.look(items[5].icon).state == "Sb" and W.look(items[6].icon) == nil, W.state(items[1].icon))
		check("page on later: the status counts the two icons and the five items in use", W.line("Cooldowns") == "Cooldowns: on, 7 styled", W.line("Cooldowns"))
		check("page on later: the sweep of the icon of the spell on cooldown is drawn", cdIcons(W)[2].cooldown.cd.sweep ~= nil and cdIcons(W)[2].texture.desaturated == true)
		local frames, textures = #W.addonFrames, #W.addonTextures
		W.change("cooldowns.enabled", false)
		W.flush()
		check("page off again: the holder and the row are hidden", cdOnScreen(W) == 0 and not cdHolder(W).shown)
		check("page off again: every item of the cooldown manager is exactly as the game built it, its outline hidden", cdItemsPlain(W, items) == "" and W.state(items[1].icon) == "hb", cdItemsPlain(W, items))
		check("page off again: the status says off, and nothing new was made", W.line("Cooldowns") == "Cooldowns: off" and #W.addonFrames == frames and #W.addonTextures == textures)
		W.setCooldown(SP.BLIND, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELLS_CHANGED")
		W.frameUpdate(1)
		W.addViewerItem("EssentialCooldownViewer")
		W.frameUpdate(1)
		W.flush()
		check("page off again: events and time do nothing, and an item the game makes later is left as it is", W.cdm.look(W.cdm.items[#W.cdm.items]) == W.cdm.items[#W.cdm.items].pristine and cdItemsPlain(W, items) == ""
			and #W.addonFrames == frames and cdQuiet(W), cdTrouble(W))
		W.change("cooldowns.enabled", true)
		W.flush()
		check("page on again: the row is back, the items are styled again, and the new item too", cdOnScreen(W) == 2 and W.state(items[1].icon) == "Sb" and W.state(W.cdm.items[#W.cdm.items].icon) == "Sb")
		check("page on again: nothing is made twice: only the new item has an outline of its own", #W.addonFrames == frames + 1 and #W.addonTextures == textures + 5, (#W.addonFrames - frames) .. " " .. (#W.addonTextures - textures))
		check("page lifecycle: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- Defaults on the open panel put every setting of the page back, and the row follows.
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		W.change("cooldowns.size", 50)
		W.change("cooldowns.spacing", 10)
		W.change("cooldowns.grow", "Left to right")
		W.change("cooldowns.numbers", false)
		W.change("cooldowns.place", "Under the personal resource display")
		W.defaults()
		W.flush()
		check("Defaults: the row has its default size, spacing, direction and position again", cdPlaced(W, 36, 3, 12, "center", "down") == "" and cdHolder(W).points[1][2] == W.env.UIParent
			and cdShown(W)[1].cooldown.cd.hideNumbers == false)
		check("Defaults: the lists are not touched", cdList(cdSaved(W)) == "408,2094" and cdQuiet(W), cdTrouble(W))
	end

	-- 82. The cooldown manager's icons.
	do
		local base = cdUp()
		local W, items = cdViewerWorld()
		local E1, E2, U1, U2, B1, B2 = items[1], items[2], items[3], items[4], items[5], items[6]
		local function style(rec)
			return W.cdm.look(rec)
		end
		local function expected(rec)
			return table.concat({ "icon TOPLEFT>item:TOPLEFT,2,-2;BOTTOMRIGHT>item:BOTTOMRIGHT,-2,2", "tc 0.08,0.92,0.08,0.92", "masks 0-", "overlay 0", "sweep " .. CD_SWEEP_PLAIN,
				"cooldown TOPLEFT>icon:TOPLEFT,0,0;BOTTOMRIGHT>icon:BOTTOMRIGHT,0,0", "range " .. (rec.rangeRaw and "TOPLEFT>icon:TOPLEFT,0,0;BOTTOMRIGHT>icon:BOTTOMRIGHT,0,0" or "-") }, " | ")
		end
		check("manager: an Essential item is styled: the icon two units in and cropped without its mask, the overlay transparent, the Cooldown and OutOfRange on the icon, the square sweep file", style(E1) == expected(E1), style(E1))
		check("manager: a Utility item likewise", style(U2) == expected(U2), style(U2))
		check("manager: a tracked buff item has no OutOfRange and is styled likewise", style(B1) == expected(B1) and B1.rangeRaw == nil, style(B1))
		check("manager: each active item has one thin border, with no backdrop", (function()
			for _, rec in ipairs({ E1, E2, U1, U2, B1 }) do
				local o = W.look(rec.icon)
				if not (o and o.state == "Sb" and ringed(W, o.anchor, 1, 0, 0, 0)) then
					return false
				end
			end
			return true
		end)())
		check("manager: the item the pool holds back is not touched", style(B2) == B2.pristine and W.look(B2.icon) == nil)
		check("manager: the status counts the five items and the holder that sweeps is there", W.line("Cooldowns") == "Cooldowns: on, 5 styled" and cdHolder(W) and cdHolder(W).shown, W.line("Cooldowns"))
		check("manager: five outlines and the holder were made: six frames and twenty-five textures", #W.addonFrames - #base.addonFrames == 6 and #W.addonTextures - #base.addonTextures == 25, (#W.addonFrames - #base.addonFrames) .. " " .. (#W.addonTextures - #base.addonTextures))
		check("manager: nothing is hooked and no field of the game's is written", W.hooks == base.hooks and cdQuiet(W), cdTrouble(W))
		local frames, textures, points = #W.addonFrames, #W.addonTextures, E1.iconRaw.calls.SetPoint
		W.frameUpdate(1)
		W.frameUpdate(1)
		W.frameUpdate(1)
		check("manager: an item that is styled is not styled again by later sweeps", #W.addonFrames == frames and #W.addonTextures == textures and E1.iconRaw.calls.SetPoint == points and E1.cdRaw.cd.calls.SetSwipeTexture == 1,
			tostring(E1.cdRaw.cd.calls.SetSwipeTexture))
		local C = W.addViewerItem("UtilityCooldownViewer")
		check("manager: a new item the game has made is not styled before the next look", style(C) == C.pristine)
		W.frameUpdate(0.5)
		check("manager: and not half a second later", style(C) == C.pristine)
		W.frameUpdate(0.5)
		check("manager: the sweep a second after the last one styles it", style(C) == expected(C) and W.state(C.icon) == "Sb", style(C))
		W.cdm.acquire(B2)
		W.frameUpdate(1)
		check("manager: an item the pool hands out is styled by the next sweep", style(B2) == expected(B2))
		local D = W.addViewerItem("EssentialCooldownViewer")
		W.fire("COOLDOWN_VIEWER_DATA_LOADED")
		check("manager: COOLDOWN_VIEWER_DATA_LOADED looks at the manager on the next frame, not in the same one", style(D) == D.pristine)
		W.tick()
		check("manager: and styles the new item then", style(D) == expected(D))
		local F = W.addViewerItem("BuffIconCooldownViewer")
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.tick()
		check("manager: so does EDIT_MODE_LAYOUTS_UPDATED", style(F) == expected(F))
		local G = W.addViewerItem("UtilityCooldownViewer")
		W.fire("SPELLS_CHANGED")
		W.tick()
		check("manager: so does SPELLS_CHANGED, which also lays the row out again", style(G) == expected(G))
		W.cdm.release(E2)
		W.cdm.release(U1)
		W.change("cooldowns.manager", false)
		W.flush()
		check("manager: Cooldown manager icons off puts every styled item back exactly, those back in the pool too", cdItemsPlain(W, W.cdm.items) == "", cdItemsPlain(W, W.cdm.items))
		check("manager: and hides their borders", W.state(E1.icon) == "hb" and W.state(E2.icon) == "hb" and W.state(B1.icon) == "hb" and W.state(G.icon) == "hb")
		local after = #W.addonTextures
		local H = W.addViewerItem("EssentialCooldownViewer")
		W.frameUpdate(1)
		W.frameUpdate(1)
		check("manager: with it off, a new item is left alone", style(H) == H.pristine and #W.addonTextures == after)
		check("manager: the status counts the items styled so far", W.line("Cooldowns") == "Cooldowns: on, 10 styled", W.line("Cooldowns"))
		W.cdm.acquire(E2)
		W.change("cooldowns.manager", true)
		W.flush()
		check("manager: on again, items are styled again, including the one handed out", style(E1) == expected(E1) and style(E2) == expected(E2) and style(H) == expected(H))
		check("manager: and the borders that were made are shown again, none made twice", W.state(E1.icon) == "Sb" and #W.addonTextures == after + 5, #W.addonTextures - after)
		check("manager: no violation or error", cdQuiet(W), cdTrouble(W))
	end

	do
		-- The icon may be found by the atlas of its mask, and an item may lack parts.
		local W, items = cdViewerWorld({ cooldowns = {} })
		local function add(more)
			local rec = W.addViewerItem("EssentialCooldownViewer", more)
			W.frameUpdate(1)
			return rec
		end
		local noOverlay = add({ noOverlay = true })
		check("manager: an item with no overlay found is still outlined and cropped, the status says which art was not found", W.state(noOverlay.icon) == "Sb" and noOverlay.iconRaw.texCoord and count(W.status(), CD_NO_OVERLAY) == 1 and not has(W.status(), CD_NO_MASK),
			W.status())
		local noMask = add({ noMask = true })
		check("manager: an item with no mask found is still outlined, and the status says so", W.state(noMask.icon) == "Sb" and #noMask.iconRaw.maskList == 0 and count(W.status(), CD_NO_MASK) == 1 and count(W.status(), CD_NO_OVERLAY) == 1)
		local third = add({ noOverlay = true, noMask = true })
		check("manager: each line is in the status once however many items lack the art", count(W.status(), CD_NO_OVERLAY) == 1 and count(W.status(), CD_NO_MASK) == 1 and W.state(third.icon) == "Sb")
		W.change("cooldowns.manager", false)
		W.flush()
		check("manager: an item that lacked art is put back as far as it had any", W.cdm.look(noOverlay) == noOverlay.pristine and W.cdm.look(noMask) == noMask.pristine and W.cdm.look(third) == third.pristine,
			W.cdm.look(noMask))
		check("manager: no violation or error for the missing art", cdQuiet(W), cdTrouble(W))
		for _, fault in ipairs({ "error", "secret" }) do
			local V = cdViewerWorld({ cooldowns = {} })
			local rec = V.addViewerItem("UtilityCooldownViewer", { maskFault = fault })
			V.frameUpdate(1)
			check("manager: GetMaskTexture " .. (fault == "error" and "failing" or "withheld") .. ", the mask is found by its atlas and removed", V.state(rec.icon) == "Sb" and #rec.iconRaw.maskList == 0 and not has(V.status(), CD_NO_MASK)
				and cdQuiet(V) and not has(V.status(), "failed"), cdTrouble(V))
			V.change("cooldowns.manager", false)
			check("manager: GetMaskTexture " .. (fault == "error" and "failing" or "withheld") .. ", and put back", V.cdm.look(rec) == rec.pristine, V.cdm.look(rec))
		end
		local N = cdViewerWorld({ cooldowns = {} })
		local rec = N.addViewerItem("EssentialCooldownViewer")
		rec.iconRaw.GetMaskTexture = nil
		N.frameUpdate(1)
		check("manager: an icon without GetMaskTexture has its mask found by the atlas", N.state(rec.icon) == "Sb" and #rec.iconRaw.maskList == 0 and cdQuiet(N))
		local O = cdViewerWorld({ cooldowns = {} })
		local nr = O.addViewerItem("BuffIconCooldownViewer", { noCooldown = true })
		local nr2 = O.addViewerItem("EssentialCooldownViewer", { noRange = true })
		O.frameUpdate(1)
		check("manager: an item with no Cooldown or no OutOfRange is styled as far as it goes", O.state(nr.icon) == "Sb" and nr.iconRaw.texCoord ~= nil and O.state(nr2.icon) == "Sb" and nr2.cdRaw.cd.swipeFile == CD_SWEEP_PLAIN and cdQuiet(O), cdTrouble(O))
	end

	do
		-- Frames the addon may not touch, and values the client withholds.
		local F, fitems = cdViewerWorld({ forbidden = { EssentialCooldownViewer = true } })
		check("manager: a viewer that is forbidden is skipped, nothing is read of it or its items", cdItemsPlain(F, { fitems[1], fitems[2] }) == "" and F.state(fitems[1].icon) == "." and F.state(fitems[3].icon) == "Sb" and F.state(fitems[5].icon) == "Sb" and cdQuiet(F),
			cdTrouble(F))
		local M, mitems = cdViewerWorld({ missing = { UtilityCooldownViewer = true } })
		check("manager: a viewer that does not exist is skipped, the others are styled", M.state(mitems[1].icon) == "Sb" and M.state(mitems[3].icon) == "." and cdItemsPlain(M, { mitems[3], mitems[4] }) == "" and cdQuiet(M), cdTrouble(M))
		local N = cdViewerWorld({ missing = { EssentialCooldownViewer = true, UtilityCooldownViewer = true, BuffIconCooldownViewer = true } })
		check("manager: no viewer at all, no holder and no error", cdHolder(N) == nil and cdQuiet(N) and N.line("Cooldowns") == "Cooldowns: on, 0 styled", N.line("Cooldowns"))
		local W = cdViewerWorld({ cooldowns = {} })
		local ok = W.addViewerItem("EssentialCooldownViewer")
		local forbidden = W.addViewerItem("EssentialCooldownViewer", { forbidden = true })
		local coolForbidden = W.addViewerItem("UtilityCooldownViewer", { cooldownForbidden = true })
		local secretIcon = W.addViewerItem("UtilityCooldownViewer", { iconSecret = true })
		local noIcon = W.addViewerItem("UtilityCooldownViewer", { noIcon = true })
		W.frameUpdate(1)
		check("manager: an item that is forbidden is skipped and nothing is read of it", W.cdm.look(forbidden) == forbidden.pristine and W.state(forbidden.icon) == "." and W.state(ok.icon) == "Sb" and cdQuiet(W), cdTrouble(W))
		check("manager: an item whose Cooldown is forbidden is styled without it", W.state(coolForbidden.icon) == "Sb" and coolForbidden.cdRaw.cd.swipeFile == CD_SWEEP_ROUND and #coolForbidden.cdRaw.points == 2
			and coolForbidden.cdRaw.points[1][2] == coolForbidden.item)
		check("manager: an item whose icon is withheld, or has none, is skipped", secretIcon.iconRaw.texCoord == nil and noIcon.iconRaw.texCoord == nil and W.state(noIcon.icon) == "." and not has(W.line("Cooldowns"), "failed"))
		W.change("cooldowns.manager", false)
		check("manager: the item whose Cooldown was forbidden is put back as far as it was reached", coolForbidden.iconRaw.points[1][4] == 0 and coolForbidden.iconRaw.texCoord[1] == 0 and #coolForbidden.iconRaw.maskList == 1 and cdQuiet(W))
		local viewer = W.cdm.viewers.EssentialCooldownViewer
		for _, case in ipairs({ { "withheld", SECRET }, { "text", "pool" }, { "a table without EnumerateActive", {} } }) do
			local P = cdViewerWorld({ cooldowns = {} })
			P.cdm.viewers.EssentialCooldownViewer.raw.itemFramePool = case[2]
			local item = P.addViewerItem("UtilityCooldownViewer")
			P.frameUpdate(1)
			check("manager: a pool that is " .. case[1] .. " is skipped, the other viewers are styled, nothing fails", P.state(item.icon) == "Sb" and cdQuiet(P) and not has(P.status(), "failed") and not has(P.status(), "stopped"), cdTrouble(P))
		end
		check("manager: nothing else", viewer ~= nil)
		local R = cdViewerWorld({ cooldowns = {} })
		R.cdm.viewers.UtilityCooldownViewer.poolRaw.errors = true
		local good = R.addViewerItem("EssentialCooldownViewer")
		for _ = 1, 4 do
			R.frameUpdate(1)
		end
		check("manager: a pool that raises costs that viewer only, however often it is tried", R.state(good.icon) == "Sb" and not has(R.status(), "cooldown manager icons stopped") and cdQuiet(R), R.status())
		R.cdm.viewers.EssentialCooldownViewer.poolRaw.errors = true
		R.cdm.viewers.BuffIconCooldownViewer.poolRaw.errors = true
		R.frameUpdate(1)
		check("manager: three pools that raise stop the cooldown manager icons and nothing else", has(R.status(), "Cooldowns: cooldown manager icons stopped. EnumerateActive failed") and not has(R.status(), "Cooldowns: stopped")
			and cdQuiet(R), R.status())
		R.frameUpdate(1)
		check("manager: and the items already styled are put back, at the next look", R.cdm.look(good) == good.pristine and R.state(good.icon) == "hb", R.cdm.look(good))
	end

	do
		-- Items that raise while they are styled: three of them stop that part alone.
		local W, items = cdViewerWorld(nil, { SP.KIDNEY, SP.BLIND })
		local bad = {}
		for i = 1, 3 do
			local rec = W.addViewerItem("EssentialCooldownViewer")
			local real = rec.iconRaw.SetPoint
			rec.broken = true
			rec.iconRaw.SetPoint = function(...)
				if rec.broken then
					error("SetPoint failed", 0)
				end
				return real(...)
			end
			bad[i] = rec
		end
		local before = W.line("Cooldowns")
		W.frameUpdate(1)
		check("manager: items that raise are skipped one by one, the others are styled", W.state(items[1].icon) == "Sb" and W.state(items[5].icon) == "Sb", W.status())
		check("manager: three items that raise stop the cooldown manager icons, and the status says so once", count(W.status(), "Cooldowns: cooldown manager icons stopped. SetPoint failed") == 1 and not has(W.status(), "Cooldowns: stopped"), W.status())
		for _, rec in ipairs(bad) do
			rec.broken = false
		end
		W.frameUpdate(1)
		W.flush()
		check("manager: the items that were styled, and those that failed half way, are put back exactly at the next look", cdItemsPlain(W, W.cdm.items) == "", cdItemsPlain(W, W.cdm.items))
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("manager: the row goes on: the sweep is drawn and the icon dimmed", cdIcons(W)[1].cooldown.cd.sweep ~= nil and cdIcons(W)[1].texture.desaturated == true and cdOnScreen(W) == 2 and cdQuiet(W), cdTrouble(W))
		local C = W.addViewerItem("UtilityCooldownViewer")
		W.frameUpdate(1)
		check("manager: a new item is not styled once the part has stopped", W.cdm.look(C) == C.pristine)
		W.change("cooldowns.manager", false)
		W.change("cooldowns.manager", true)
		W.frameUpdate(1)
		check("manager: and the option does not wake it", W.cdm.look(C) == C.pristine and cdItemsPlain(W, items) == "")
		check("manager: other modules are untouched", has(W.status(), "Nameplates: on") and has(W.status(), "Action bars: on, 118 styled") and not has(W.status(), "Cooldowns: stopped"), W.status())
	end

	-- 83. Values and answers the client may withhold, at every call the part makes.
	-- Everything a player can do with the part, with one answer of the game made to fail or be withheld.
	local CD_EVENTS = { "SPELL_UPDATE_COOLDOWN", "SPELL_UPDATE_CHARGES", "SPELLS_CHANGED", "PLAYER_TALENT_UPDATE", "ACTIVE_TALENT_GROUP_CHANGED", "PLAYER_ENTERING_WORLD", "COOLDOWN_VIEWER_DATA_LOADED",
		"EDIT_MODE_LAYOUTS_UPDATED" }
	local function cdExercise(W)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCharges(SP.CHARGED, 1, true)
		for _, event in ipairs(CD_EVENTS) do
			W.fire(event)
		end
		W.frameUpdate(0.2)
		W.frameUpdate(1)
		W.slash("cooldown add 2094")
		W.slash("cooldown add Blind")
		W.slash("cooldown add spell:1856")
		W.slash("cooldown remove 2094")
		W.slash("cooldown remove Vanish")
		W.slash("cooldown add 57934")
		W.slash("cooldown remove 57934")
		W.slash("cooldown list")
		W.slash("cooldown")
		W.menu("cooldowns.add")
		W.menu("cooldowns.remove")
		if #W.menu("cooldowns.add") >= 2 then
			W.pickAt("cooldowns.add", 2)
		end
		if #W.menu("cooldowns.remove") >= 2 then
			W.pickAt("cooldowns.remove", 2)
		end
		W.finishCooldown(SP.KIDNEY)
		W.setCooldown(SP.KIDNEY, "gcd")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.change("cooldowns.size", 40)
		W.change("cooldowns.numbers", false)
		W.change("cooldowns.dim", false)
		W.change("cooldowns.grow", "Left to right")
		W.change("cooldowns.place", "Middle of the screen")
		W.change("cooldowns.manager", false)
		W.change("cooldowns.manager", true)
		W.change("cooldowns.enabled", false)
		W.change("cooldowns.enabled", true)
		W.flush()
		W.frameUpdate(1)
		W.flush()
	end
	-- Whether the part is running: not stopped, no icon failed.
	local function cdRunning(W)
		local line = W.line("Cooldowns") or ""
		return not has(line, "stopped") and not has(line, "failed") and not has(W.status(), "cooldown manager icons stopped")
	end

	do
		local FUNCTIONS = { "GetSpellName", "GetSpellTexture", "GetSpellInfo", "GetSpellCooldown", "GetSpellCooldownDuration", "GetSpellCharges", "GetSpellChargeDuration", "GetSpellDisplayCount",
			"GetNumSpellBookSkillLines", "GetSpellBookSkillLineInfo", "GetSpellBookItemInfo", "IsSpellBookItemLowRank", "IsSpellKnownOrInSpellBook", "IsSpellKnown", "GetSpellBaseCooldown" }
		local FAULTS = { { "error", "raising" }, { "nothing", "returning nothing" }, { "secret", "withheld" }, { "string", "returning text" } }
		-- The two duration functions return an object the client documents; an answer that is withheld or text is not modelled.
		local OBJECTS = { GetSpellCooldownDuration = true, GetSpellChargeDuration = true }
		for _, name in ipairs(FUNCTIONS) do
			for _, fault in ipairs(FAULTS) do
			if not (OBJECTS[name] and (fault[1] == "secret" or fault[1] == "string")) then
				local W = newWorld({ cooldowns = { viewers = true }, char = { cooldowns = { SP.KIDNEY, SP.CHARGED } } })
				cdBook(W)
				W.addViewerItem("EssentialCooldownViewer")
				W.addViewerItem("BuffIconCooldownViewer")
				W.sp.fault[name] = fault[1]
				local ok, err = pcall(function()
					W.login()
					W.flush()
					cdExercise(W)
				end)
				local detail = (ok and "" or tostring(err)) .. " " .. cdTrouble(W) .. " " .. (W.line("Cooldowns") or "")
				local expectedFail = name == "GetSpellCooldown" and fault[1] == "error"
				check("answers: " .. name .. " " .. fault[2] .. ", nothing raises, nothing is read that is withheld, the part keeps running", ok and cdQuiet(W) and ((expectedFail and not has(W.line("Cooldowns") or "", "stopped")) or cdRunning(W)),
					detail)
			end
			end
		end
	end

	do
		-- A table with a withheld field.
		local function withheld(name, field, value)
			local W = newWorld({ cooldowns = { viewers = true }, char = { cooldowns = { SP.KIDNEY, SP.CHARGED } } })
			cdBook(W)
			W.addViewerItem("UtilityCooldownViewer")
			local api = W.env.C_SpellBook[name] or W.env.C_Spell[name]
			local owner = W.env.C_SpellBook[name] and W.env.C_SpellBook or W.env.C_Spell
			owner[name] = function(...)
				local answer = api(...)
				if type(answer) == "table" then
					local copy = {}
					for k, v in pairs(answer) do
						copy[k] = v
					end
					copy[field] = value
					return copy
				end
				return answer
			end
			local ok, err = pcall(function()
				W.login()
				W.flush()
				cdExercise(W)
			end)
			return W, ok, err
		end
		local cases = { { "GetSpellBookSkillLineInfo", "itemIndexOffset" }, { "GetSpellBookSkillLineInfo", "numSpellBookItems" }, { "GetSpellBookSkillLineInfo", "name" }, { "GetSpellBookItemInfo", "spellID" },
			{ "GetSpellBookItemInfo", "actionID" }, { "GetSpellBookItemInfo", "name" }, { "GetSpellBookItemInfo", "itemType" }, { "GetSpellCharges", "maxCharges" }, { "GetSpellCharges", "isActive" },
			{ "GetSpellCooldown", "isActive" }, { "GetSpellCooldown", "isOnGCD" }, { "GetSpellCooldown", "isEnabled" }, { "GetSpellCooldown", "startTime" }, { "GetSpellCooldown", "modRate" },
			{ "GetSpellInfo", "spellID" }, { "GetSpellInfo", "name" } }
		for _, case in ipairs(cases) do
			local W, ok, err = withheld(case[1], case[2], SECRET)
			check("answers: " .. case[1] .. " with " .. case[2] .. " withheld, nothing raises and the part keeps running", ok and cdQuiet(W) and cdRunning(W), tostring(err) .. " " .. cdTrouble(W) .. " " .. (W.line("Cooldowns") or ""))
		end
		-- The value a withheld number or boolean keeps its type, so type() says number or boolean.
		for _, kind in ipairs({ "number", "boolean", "string", "table" }) do
			local W = newWorld({ cooldowns = { secretTimes = true, viewers = true }, char = { cooldowns = { SP.KIDNEY, SP.CHARGED } } })
			cdBook(W)
			W.addViewerItem("EssentialCooldownViewer", { iconSecret = true })
			W.secretType = kind
			W.sp.secretActive = true
			W.sp.secretCount = true
			local ok, err = pcall(function()
				W.login()
				W.flush()
				cdExercise(W)
			end)
			check("answers: a withheld value that says type() is " .. kind .. ": nothing raises, nothing is compared, and the part keeps running", ok and cdQuiet(W) and cdRunning(W),
				tostring(err) .. " " .. cdTrouble(W) .. " " .. (W.line("Cooldowns") or ""))
		end
	end

	do
		-- The game's frames of the cooldown manager answering oddly.
		for _, fault in ipairs({ "secret", "garbage", "error", "string" }) do
			local W, items = cdViewerWorld({ cooldowns = {} })
			local first = items[1]
			W.rawOf[first.item].fault.regions = fault
			local other = W.addViewerItem("EssentialCooldownViewer")
			W.frameUpdate(1)
			check("manager: the regions of an item " .. fault .. ", nothing raises, the item is looked at once at most, the other items are styled", cdQuiet(W) and W.state(other.icon) == "Sb" and W.state(items[3].icon) == "Sb"
				and not has(W.status(), "Cooldowns: stopped"), cdTrouble(W) .. W.status())
		end
		local W, items = cdViewerWorld({ cooldowns = {} })
		local bad = W.addViewerItem("UtilityCooldownViewer", { regionsError = true })
		W.frameUpdate(1)
		W.frameUpdate(1)
		W.frameUpdate(1)
		check("manager: an item whose regions cannot be listed counts as one failed frame of the part however often it is tried", cdQuiet(W) and not has(W.status(), "cooldown manager icons stopped") and W.state(items[1].icon) == "Sb",
			W.status())
		for _, fault in ipairs({ "size", "name", "parent", "shown" }) do
			local V, vitems = cdViewerWorld({ cooldowns = {} })
			for _, rec in ipairs(vitems) do
				V.rawOf[rec.item].fault[fault] = "error"
			end
			V.frameUpdate(1)
			check("manager: items whose " .. fault .. " cannot be read are styled all the same, and nothing raises", V.state(vitems[1].icon) == "Sb" and cdQuiet(V), cdTrouble(V))
		end
	end

	-- 84. Failures: one bad icon is skipped and counted once, the part or the module stops as designed, other modules go on.
	do
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND, SP.VANISH })
		local icons = cdIcons(W)
		icons[2].cooldown.SetHideCountdownNumbers = function() error("sweep failed", 0) end
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCooldown(SP.BLIND, "cooling")
		for _ = 1, 6 do
			W.fire("SPELL_UPDATE_COOLDOWN")
			W.frameUpdate(0.2)
		end
		check("failure: one icon that raises is counted once however often it is tried, the status gives the first error", W.line("Cooldowns") == "Cooldowns: on, 3 styled, 1 failed. sweep failed", W.line("Cooldowns"))
		check("failure: the icons before and after it are updated", icons[1].cooldown.cd.sweep ~= nil and icons[1].texture.desaturated == true and #W.errors == 0 and #W.out == 0 and #W.violations == 0)
		check("failure: the module is still running and the row is where it was", not has(W.status(), "stopped") and cdPlaced(W, 36, 3, 12, "center", "down") == "")
	end

	do
		local ids = {}
		for i = 1, 5 do
			ids[i] = 5000 + i
		end
		local W = cdViewerWorld({ char = { cooldowns = ids } })
		cdMany(W, 5)
		W.fire("SPELLS_CHANGED")
		W.flush()
		local icons = cdIcons(W)
		check("failure: five icons are made", #icons == 5 and cdOnScreen(W) == 5)
		local item = W.cdm.items[1]
		check("failure: and the manager's items are styled", W.state(item.icon) == "Sb")
		W.out = {}
		for i = 1, 5 do
			icons[i].cooldown.SetHideCountdownNumbers = function() error("sweep failed", 0) end
		end
		W.setCooldown(5001, "cooling")
		for i = 1, 5 do
			W.setCooldown(5000 + i, "cooling")
		end
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("failure: five icons that raise stop the module, and the player is told once", W.out[1] == "Flat UI: Cooldowns stopped. /flatui status shows why. Type /reload if the look is left half changed." and #W.out == 1, table.concat(W.out, "|"))
		check("failure: the status gives the first error", W.line("Cooldowns") == "Cooldowns: stopped. sweep failed", W.line("Cooldowns"))
		check("failure: the row is hidden and the manager's items are as the game built them", cdOnScreen(W) == 0 and not cdHolder(W).shown and cdItemsPlain(W, W.cdm.items) == "" and W.state(item.icon) == "hb", cdItemsPlain(W, W.cdm.items))
		check("failure: other modules are untouched", has(W.status(), "Nameplates: on") and has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Cast bars: on, 5 styled") and not has(W.status(), "Windows: stopped"), W.status())
		W.out = {}
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELLS_CHANGED")
		W.frameUpdate(1)
		W.addViewerItem("EssentialCooldownViewer")
		W.frameUpdate(1)
		W.flush()
		check("failure: a stopped module does nothing: no event, no time, no new item changes anything", #W.out == 0 and cdOnScreen(W) == 0 and W.cdm.look(W.cdm.items[#W.cdm.items]) == W.cdm.items[#W.cdm.items].pristine and cdQuiet(W), cdTrouble(W))
		check("failure: add, remove and list still work, and do not raise", W.slash("cooldown add 2094") == "Added Blind." and W.slash("cooldown list"):find("Blind", 1, true) ~= nil and cdQuiet(W), cdTrouble(W))
		W.change("cooldowns.enabled", false)
		W.change("cooldowns.enabled", true)
		check("failure: the switch does not start it again", W.line("Cooldowns") == "Cooldowns: stopped. sweep failed" and cdOnScreen(W) == 0 and cdQuiet(W))
		check("failure: the dropdowns are greyed with the page off and usable with it on, whether or not the part runs", W.enabled("cooldowns.add") and W.enabled("cooldowns.remove"))
	end

	do
		-- A layout that raises stops the module as well.
		local W = newWorld({ cooldowns = true, char = { cooldowns = { SP.KIDNEY, SP.BLIND } } })
		cdBook(W)
		local real = W.env.CreateFrame
		local armed = false
		W.env.CreateFrame = function(kind, ...)
			if armed and kind == "Cooldown" then
				error("no cooldown frame", 0)
			end
			return real(kind, ...)
		end
		W.login()
		W.flush()
		check("layout failure: with nothing wrong, two icons", cdOnScreen(W) == 2)
		armed = true
		W.slash("cooldown add 1856")
		check("layout failure: a layout that raises stops the module, the status says why and the row is hidden", W.line("Cooldowns") == "Cooldowns: stopped. no cooldown frame" and cdOnScreen(W) == 0 and not cdHolder(W).shown, W.line("Cooldowns"))
		check("layout failure: nothing raised past the module", #W.errors == 0 and #W.violations == 0, cdTrouble(W))
		check("layout failure: other modules go on", has(W.status(), "Nameplates: on") and has(W.status(), "Action bars: on, 118 styled"))
	end

	do
		-- A slash command that raises is reported and does not raise past the slash handler.
		local W = cdUp(nil, { SP.KIDNEY })
		W.ns.CooldownAdd = function() error("add failed", 0) end
		local ok = pcall(W.slash, "cooldown add 2094")
		check("slash: a command that raises is reported to the error handler and the slash handler does not raise", ok and #W.errors == 1 and W.errors[1] == "add failed", table.concat(W.errors, "|"))
		W.errors = {}
		local keep = cdUp(nil, { SP.KIDNEY })
		keep.ns.Register("probe", { label = "Probe", slash = { cooldown = function() keep.errors[#keep.errors + 1] = "other" end } })
		check("slash: the first word picks the command", keep.slash("cooldown list") ~= nil and #keep.errors == 0)
	end

	-- 85. A client that lacks a global or a method the part uses.
	do
		local function without(...)
			local set = {}
			for _, name in ipairs({ ... }) do
				set[name] = true
			end
			return { without = set }
		end
		local LACKS = {
			{ "C_Spell", without("C_Spell") },
			{ "C_Spell.GetSpellName", without("C_Spell.GetSpellName") }, { "C_Spell.GetSpellInfo", without("C_Spell.GetSpellInfo") }, { "C_Spell.GetSpellTexture", without("C_Spell.GetSpellTexture") },
			{ "C_Spell.GetSpellCooldown", without("C_Spell.GetSpellCooldown") }, { "C_Spell.GetSpellCooldownDuration", without("C_Spell.GetSpellCooldownDuration") },
			{ "C_Spell.GetSpellCharges", without("C_Spell.GetSpellCharges") }, { "C_Spell.GetSpellChargeDuration", without("C_Spell.GetSpellChargeDuration") },
			{ "C_Spell.GetSpellDisplayCount", without("C_Spell.GetSpellDisplayCount") },
			{ "C_SpellBook", without("C_SpellBook") },
			{ "C_SpellBook.GetNumSpellBookSkillLines", without("C_SpellBook.GetNumSpellBookSkillLines") }, { "C_SpellBook.GetSpellBookSkillLineInfo", without("C_SpellBook.GetSpellBookSkillLineInfo") },
			{ "C_SpellBook.GetSpellBookItemInfo", without("C_SpellBook.GetSpellBookItemInfo") }, { "C_SpellBook.IsSpellBookItemLowRank", without("C_SpellBook.IsSpellBookItemLowRank") },
			{ "C_SpellBook.IsSpellKnownOrInSpellBook", without("C_SpellBook.IsSpellKnownOrInSpellBook") }, { "C_SpellBook.IsSpellKnown", without("C_SpellBook.IsSpellKnown") },
			{ "both known tests", without("C_SpellBook.IsSpellKnownOrInSpellBook", "C_SpellBook.IsSpellKnown") },
			{ "GetSpellBaseCooldown", without("GetSpellBaseCooldown") },
			{ "Enum", without("Enum") }, { "Enum.SpellBookSpellBank", without("Enum.SpellBookSpellBank") }, { "Enum.SpellBookItemType", without("Enum.SpellBookItemType") },
			{ "C_Timer", without("C_Timer") },
			{ "PersonalResourceDisplayFrame", { missing = { PersonalResourceDisplayFrame = true } } },
			{ "the three cooldown viewers", { missing = { EssentialCooldownViewer = true, UtilityCooldownViewer = true, BuffIconCooldownViewer = true } } },
			{ "Cooldown:SetCooldownFromDurationObject", { cooldowns = { noMethods = { SetCooldownFromDurationObject = true } } } },
			{ "Cooldown:SetHideCountdownNumbers", { cooldowns = { noMethods = { SetHideCountdownNumbers = true } } } },
			{ "Cooldown:SetSwipeTexture", { cooldowns = { noMethods = { SetSwipeTexture = true } } } },
			{ "the pool's EnumerateActive", { poolFn = function(W) for _, v in pairs(W.cdm.viewers) do v.poolRaw.EnumerateActive = nil end end } },
			{ "the pool itself", { poolFn = function(W) for _, v in pairs(W.cdm.viewers) do v.raw.itemFramePool = nil end end } },
			{ "GetMaskTexture and the mask", { itemMore = { maskFault = "error", noMask = true } } },
			{ "Texture:GetMaskTexture", { iconFn = function(rec) rec.iconRaw.GetMaskTexture = nil end } },
		}
		for _, lack in ipairs(LACKS) do
			local o = {}
			for k, v in pairs(lack[2]) do
				if k ~= "poolFn" and k ~= "iconFn" and k ~= "itemMore" then
					o[k] = v
				end
			end
			o.cooldowns = o.cooldowns or {}
			o.cooldowns.viewers = true
			o.char = { cooldowns = { SP.KIDNEY, SP.CHARGED } }
			local W = newWorld(o)
			cdBook(W)
			local recs = { W.addViewerItem("EssentialCooldownViewer", lack[2].itemMore), W.addViewerItem("BuffIconCooldownViewer", lack[2].itemMore) }
			if lack[2].poolFn then
				lack[2].poolFn(W)
			end
			if lack[2].iconFn then
				for _, rec in ipairs(recs) do
					lack[2].iconFn(rec)
				end
			end
			local ok, err = pcall(function()
				W.login()
				W.flush()
				cdExercise(W)
			end)
			check("lacking " .. lack[1] .. ": nothing raises and nothing is called that is not there", ok and cdQuiet(W), tostring(err) .. " " .. cdTrouble(W))
			check("lacking " .. lack[1] .. ": the part is not stopped and no icon fails", cdRunning(W), (W.line("Cooldowns") or "") .. " " .. W.status())
			check("lacking " .. lack[1] .. ": the other modules the part has no share in are untouched", has(W.status(), "Action bars: on, 118 styled") and has(W.status(), "Cast bars: on, 5 styled") and not has(W.status(), "Windows: stopped"))
		end
	end

	do
		-- What the part does without each piece, where the piece is the whole of a job.
		local N = newWorld({ cooldowns = true, without = { C_Spell = true }, char = { cooldowns = { SP.KIDNEY } } })
		cdBook(N)
		N.login()
		N.flush()
		check("lacking C_Spell: add says no spell was found, list still lists the saved IDs", N.slash("cooldown add 408") == 'No spell found for "408".' and has(N.slash("cooldown list"), "408"), N.slash("cooldown add 408"))
		local B = newWorld({ cooldowns = true, without = { C_SpellBook = true }, char = { cooldowns = { SP.KIDNEY } } })
		cdBook(B)
		B.login()
		B.flush()
		check("lacking C_SpellBook: every picked spell counts as known and has its icon", cdRowIcons(B) == "132298" and cdQuiet(B))
		local T = newWorld({ cooldowns = true, without = { C_Timer = true }, char = { cooldowns = { SP.KIDNEY } } })
		cdBook(T)
		T.login()
		T.flush()
		check("lacking C_Timer: the row is made", cdRowIcons(T) == "132298" and cdQuiet(T), cdTrouble(T))
		-- The design: a missing piece switches off only what needs it, with one line in /flatui status.
		local lines = {}
		for _, name in ipairs({ "C_Spell", "C_SpellBook", "C_Spell.GetSpellCooldown", "Enum" }) do
			local W = newWorld({ cooldowns = true, without = { [name] = true }, char = { cooldowns = { SP.KIDNEY } } })
			cdBook(W)
			W.login()
			W.flush()
			local status = W.status()
			local at = status:find("Cooldowns:", 1, true)
			local rest = status:sub(at):match("^[^\n]*\n(.-)\n?Windows:")
			if not rest or rest == "" then
				lines[#lines + 1] = name
			end
		end
		check("lacking a piece: /flatui status has a line about what is missing", #lines == 0, "no line for " .. table.concat(lines, ", "))
	end

	-- 86. /flatui status, saved settings of earlier versions, two characters.
	do
		local W = cdViewerWorld(nil, { SP.KIDNEY, SP.BLIND })
		check("status: Cooldowns after Cast bars and before Windows, counting the icons and the manager's items", W.status():match("Cast bars: on, %d+ styled\nCooldowns: on, 7 styled\nTrackers: on, 0 shown\nDefensives on you: on\nParty cooldowns: on\nEnemy cooldowns: on\nWindows: on") ~= nil, W.status())
		W.change("cooldowns.enabled", false)
		check("status: off", W.status():match("Cast bars: on, %d+ styled\nCooldowns: off\nTrackers: on, 0 shown\nDefensives on you: on\nParty cooldowns: on\nEnemy cooldowns: on\nWindows: on") ~= nil)
		W.change("cooldowns.enabled", true)
		W.sp.secretTimes = true
		local P = newWorld()
		P.login()
		local before = P.status()
		check("status: a world with no cooldown icons has the same lines as before, with the new one", before:match("Cooldowns: on, 0 styled") ~= nil)
	end

	do
		-- Settings saved by version 0.2.0 (the options table, no per-character data) and version 0.1.0 (switches on FlatUIDB itself).
		local saved020 = { options = { ["general.thickness"] = 2, ["general.border"] = "ff336699", ["nameplates.dim"] = true, ["actionbars.crop"] = 10, ["windows.opacity"] = 60, ["castbars.enabled"] = false } }
		local copy = {}
		for k, v in pairs(saved020.options) do
			copy[k] = v
		end
		local W = cdUp({ saved = saved020 }, nil, false)
		local same = true
		for k, v in pairs(copy) do
			same = same and W.options()[k] == v
		end
		local extra = 0
		for k in pairs(W.options()) do
			if copy[k] == nil then
				extra = extra + 1
			end
		end
		check("saved by 0.2.0: every option loads as it was and none is added or dropped", same and extra == 0, extra)
		check("saved by 0.2.0: the new page has its defaults and works", W.ns.Get("cooldowns.size") == 36 and W.ns.Get("cooldowns.enabled") == true and W.slash("cooldown add 408") == "Added Kidney Shot." and W.ns.Get("general.thickness") == 2)
		check("saved by 0.2.0: the per-character data is made, the account data holds no cooldown list", type(W.env.FlatUICharDB) == "table" and W.env.FlatUIDB.cooldowns == nil)
		check("saved by 0.2.0: status", has(W.status(), TOC.head(2)) and has(W.status(), "Cast bars: off") and has(W.status(), "Cooldowns: on, 1 styled"), W.status())
		local old = cdUp({ saved = { nameplates = false, actionbars = true, resource = false, swing = false, castbars = false, thickness = 2 } }, { SP.KIDNEY })
		local o = old.options()
		check("saved by 0.1.0: the switches and the thickness are migrated as before and the cooldown icons are on", o["nameplates.enabled"] == false and o["castbars.enabled"] == false and o["general.thickness"] == 2 and old.ns.Get("cooldowns.enabled") == true
			and old.env.FlatUIDB.cooldowns == nil and old.env.FlatUIDB.nameplates == nil)
		check("saved by 0.1.0: the row works", cdRowIcons(old) == "132298" and cdQuiet(old), cdTrouble(old))
	end

	do
		-- Two characters on one account: the options are shared, the lists are not.
		local A = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		A.change("cooldowns.size", 44)
		A.change("cooldowns.numbers", false)
		local account = A.env.FlatUIDB
		local B = cdUp({ saved = account, char = {} })
		check("two characters: the second sees the account's options", B.ns.Get("cooldowns.size") == 44 and B.ns.Get("cooldowns.numbers") == false and B.env.FlatUIDB == account)
		check("two characters: and starts with no spells", B.slash("cooldown list") == "No spells picked." and #cdIcons(B) == 0)
		B.slash("cooldown add 1856")
		B.change("cooldowns.spacing", 8)
		check("two characters: its list is its own", cdList(cdSaved(B)) == "1856" and cdList(cdSaved(A)) == "408,2094" and B.env.FlatUICharDB ~= A.env.FlatUICharDB)
		local A2 = cdUp({ saved = account, char = A.env.FlatUICharDB })
		check("two characters: the first comes back with its list and the options both changed", cdRowIcons(A2) == "132298,136175" and A2.ns.Get("cooldowns.spacing") == 8 and A2.ns.Get("cooldowns.size") == 44
			and cdPlaced(A2, 44, 8, 12, "center", "down") == "", cdPlaced(A2, 44, 8, 12, "center", "down"))
		check("two characters: no violation or error", cdQuiet(A) and cdQuiet(B) and cdQuiet(A2))
	end


	-- 87. Cases found by changing the addon on purpose: answers of the game that decide between two ways, and work that must not be done twice.
	do
		-- A spell the game gives no name keeps a stand-in, in the list and in the dropdown.
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		W.sp.fault.GetSpellName = "nothing"
		check("names: a spell the game has no name for is called Spell and its ID in the list", W.slash("cooldown list") == "1. Spell 408 (408)\n2. Spell 2094 (2094)", W.slash("cooldown list"))
		check("names: and in the Remove a spell dropdown", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Spell 408,Spell 2094")
		check("names: and it cannot be added, since the game does not know it", W.slash("cooldown add 1856") == 'No spell found for "1856".' and cdList(cdSaved(W)) == "408,2094")
	end

	do
		-- The tests for a known spell: two, and one when the other says nothing sensible.
		local N = cdUp({ without = { ["C_SpellBook.IsSpellKnownOrInSpellBook"] = true, ["C_SpellBook.IsSpellKnown"] = true } }, { SP.KIDNEY, SP.TRICKS })
		check("known: with no test for it a picked spell counts as known", cdRowIcons(N) == "132298,236283" and cdQuiet(N), cdRowIcons(N))
		check("known: and the list does not mark it", N.slash("cooldown list") == "1. Kidney Shot (408)\n2. Tricks of the Trade (57934)")
		for _, fault in ipairs({ "string", "nothing", "error", "secret" }) do
			local W = cdUp(nil, { SP.KIDNEY, SP.TRICKS })
			W.sp.fault.IsSpellKnownOrInSpellBook = fault
			W.fire("SPELLS_CHANGED")
			W.flush()
			check("known: the first test answering " .. fault .. ", the second decides: a spell it does not know has no icon", cdRowIcons(W) == "132298" and cdQuiet(W), cdRowIcons(W))
			W.sp.data[SP.TRICKS].known = true
			W.fire("SPELLS_CHANGED")
			W.flush()
			check("known: and one it knows has", cdRowIcons(W) == "132298,236283")
		end
		local W = cdUp(nil, { SP.KIDNEY, SP.TRICKS })
		W.sp.fault.IsSpellKnownOrInSpellBook = "nothing"
		W.sp.fault.IsSpellKnown = "string"
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("known: when neither gives a yes or no, the spell is taken as known", cdRowIcons(W) == "132298,236283", cdRowIcons(W))
	end

	do
		-- The rate of a cooldown: one when the game gives none.
		local W = cdUp({ without = { ["C_Spell.GetSpellCooldownDuration"] = true } }, { SP.KIDNEY })
		local real = W.env.C_Spell.GetSpellCooldown
		W.env.C_Spell.GetSpellCooldown = function(...)
			local info = real(...)
			if type(info) == "table" then
				info.modRate = nil
			end
			return info
		end
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		local sweep = cdIcons(W)[1].cooldown.cd.sweep
		check("cooldown: with no rate from the game the sweep runs at rate one", sweep and sweep.kind == "numbers" and sweep.rate == 1 and cdQuiet(W), cdTrouble(W))
	end

	do
		-- A spell with two charges has a count; a spell cooling when it is picked is dimmed at once.
		local W = newWorld({ cooldowns = true, char = { cooldowns = { 100002, SP.KIDNEY } } })
		cdBook(W)
		W.addSpell(100002, { name = "Twin Charge", icon = 132000, base = 5000, charges = 2 })
		W.login()
		W.flush()
		local rec = cdIcons(W)[1]
		check("charges: a spell with two charges shows the count", rec.count.text == "2", tostring(rec.count.text))
		W.setCooldown(SP.BLIND, "cooling")
		W.slash("cooldown add 2094")
		local blind = cdIcons(W)[3]
		check("a spell picked while it is on cooldown is dimmed and shows its sweep as soon as the row is laid out", blind.texture.desaturated == true and blind.cooldown.cd.sweep ~= nil and near(blind.texture.vertex[1], 0.6))
		-- A spell whose charges stop mattering loses its count.
		local C = cdUp(nil, { SP.CHARGED })
		check("charges: the count is shown", cdIcons(C)[1].count.text == "3")
		C.sp.data[SP.CHARGED].charges.max = 1
		C.fire("SPELL_UPDATE_CHARGES")
		check("charges: and goes when the spell no longer has more than one", cdIcons(C)[1].count.text == "")
	end

	do
		-- The Add a spell dropdown shows the name the spell book gives, and the game's name when the book gives none.
		local W = cdUp()
		W.addSpell(9101, { name = "Gouge", bookName = "Gouge (Rank 1)", base = 1000 })
		W.addSpell(9102, { name = "Sap", bookName = "", base = 1000 })
		local labels = table.concat(W.menu("cooldowns.add"), ",")
		check("Add a spell: the name is the spell book's, or the game's when the book has none", has(labels, ",Gouge (Rank 1),") and has(labels, ",Sap,") and not has(labels, ",Gouge,"), labels)
	end

	do
		-- The mask is found through the icon when the item does not list it.
		local W = cdViewerWorld({ cooldowns = {} })
		local rec = W.addViewerItem("EssentialCooldownViewer", { maskNotListed = true })
		W.frameUpdate(1)
		check("manager: a mask the item does not list is found through the icon and taken off", W.state(rec.icon) == "Sb" and #rec.iconRaw.maskList == 0 and not has(W.status(), CD_NO_MASK) and cdQuiet(W), W.status())
		W.change("cooldowns.manager", false)
		check("manager: and put back", W.cdm.look(rec) == rec.pristine, W.cdm.look(rec))
	end

	do
		-- Pools the addon may not or cannot read, on every viewer: nothing is tried, so nothing fails and the part is not stopped.
		for _, case in ipairs({ { "withheld", function(v) v.raw.itemFramePool = SECRET end }, { "text", function(v) v.raw.itemFramePool = "pool" end },
			{ "without EnumerateActive", function(v) v.poolRaw.EnumerateActive = nil end }, { "an empty table", function(v) v.raw.itemFramePool = {} end },
			{ "missing", function(v) v.raw.itemFramePool = nil end } }) do
			local W = cdViewerWorld({ cooldowns = {} })
			for _, v in pairs(W.cdm.viewers) do
				case[2](v)
			end
			W.addViewerItem("EssentialCooldownViewer")
			W.frameUpdate(1)
			W.frameUpdate(1)
			W.frameUpdate(1)
			check("manager: every pool " .. case[1] .. ", nothing is tried, so the part is not stopped and nothing raises", not has(W.status(), "cooldown manager icons stopped") and cdQuiet(W), W.status())
		end
	end

	do
		-- An item that became forbidden after it was styled is left alone.
		local W, items = cdViewerWorld({ cooldowns = {} })
		W.rawOf[items[1].item].forbidden = true
		W.rawOf[items[3].item].forbidden = true
		W.change("cooldowns.manager", false)
		W.frameUpdate(1)
		check("manager: an item that is forbidden by the time it is put back is skipped, nothing is read of it", cdQuiet(W) and W.cdm.look(items[2]) == items[2].pristine and W.cdm.look(items[4]) == items[4].pristine, cdTrouble(W))
	end

	do
		-- Work that is queued in combat is done once when combat ends.
		local W, items = cdViewerWorld({ cooldowns = {} }, { SP.KIDNEY })
		local looked = {}
		for name, v in pairs(W.cdm.viewers) do
			looked[name] = v.poolRaw.enumerated or 0
		end
		W.combat = true
		for _ = 1, 4 do
			W.fire("SPELLS_CHANGED")
			W.fire("COOLDOWN_VIEWER_DATA_LOADED")
			W.fire("EDIT_MODE_LAYOUTS_UPDATED")
			W.change("cooldowns.size", 40)
			W.change("cooldowns.size", 36)
			W.flush()
		end
		local during = true
		for name, v in pairs(W.cdm.viewers) do
			during = during and (v.poolRaw.enumerated or 0) == looked[name]
		end
		check("combat: the cooldown manager is not looked at in combat", during)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		local once = true
		for name, v in pairs(W.cdm.viewers) do
			once = once and (v.poolRaw.enumerated or 0) == looked[name] + 1
		end
		check("combat ends: and is looked at once, however many events asked for it", once)
	end

	do
		-- A module stopped in combat is put right when combat ends.
		local ids = {}
		for i = 1, 5 do
			ids[i] = 5000 + i
		end
		local W, items = cdViewerWorld({ char = { cooldowns = ids } })
		cdMany(W, 5)
		W.fire("SPELLS_CHANGED")
		W.flush()
		local icons = cdIcons(W)
		for i, icon in ipairs(icons) do
			icon.cooldown.SetHideCountdownNumbers = function() error("sweep failed", 0) end
			W.setCooldown(5000 + i, "cooling")
		end
		W.combat = true
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("combat: five icons that raise in combat stop the module", W.line("Cooldowns") == "Cooldowns: stopped. sweep failed", W.line("Cooldowns"))
		check("combat: the row is hidden at once, the items stay as they are until combat ends, and nothing raises", cdOnScreen(W) == 0 and W.state(items[1].icon) == "Sb" and cdQuiet(W), cdTrouble(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat ends: the row is hidden and the items are as the game built them", cdOnScreen(W) == 0 and cdItemsPlain(W, items) == "" and W.state(items[1].icon) == "hb" and cdQuiet(W), cdItemsPlain(W, items))
	end

	do
		-- Without C_Timer and without a cooldown manager nothing needs it.
		local W = newWorld({ cooldowns = true, without = { C_Timer = true }, char = { cooldowns = { SP.KIDNEY, SP.CHARGED } } })
		cdBook(W)
		W.login()
		W.setCooldown(SP.KIDNEY, "cooling")
		for _, event in ipairs(CD_EVENTS) do
			W.fire(event)
		end
		W.frameUpdate(1)
		W.slash("cooldown add 2094")
		check("lacking C_Timer and the cooldown manager: the row works, nothing raises and nothing is stopped", cdRunning(W) and cdQuiet(W) and cdOnScreen(W) == 3, cdTrouble(W) .. " " .. (W.line("Cooldowns") or ""))
	end

	-- 88. More cases found by changing the addon on purpose.
	do
		-- A picture that is not a number or text is no picture; text is a path and is kept.
		for _, case in ipairs({ { "nothing", "nothing" }, { "withheld", "secret" }, { "an error", "error" } }) do
			local W = cdUp(nil, { SP.KIDNEY })
			W.sp.fault.GetSpellTexture = case[2]
			W.fire("SPELLS_CHANGED")
			W.flush()
			check("picture: GetSpellTexture giving " .. case[1] .. ", the icon is the question mark", cdIcons(W)[1].texture.file == 134400 and cdQuiet(W), tostring(cdIcons(W)[1].texture.file))
		end
		local W = cdUp(nil, { SP.KIDNEY })
		W.env.C_Spell.GetSpellTexture = function() return "Interface\\Icons\\Spell_Nature_Bolt" end
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("picture: a path as text is kept", cdIcons(W)[1].texture.file == "Interface\\Icons\\Spell_Nature_Bolt")
		W.env.C_Spell.GetSpellTexture = function() return true end
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("picture: and an answer that is neither is the question mark", cdIcons(W)[1].texture.file == 134400)
	end

	do
		-- isOnGCD is optional: a spell cooling with no answer for it is cooling.
		local W = cdUp(nil, { SP.KIDNEY })
		local real = W.env.C_Spell.GetSpellCooldown
		W.env.C_Spell.GetSpellCooldown = function(...)
			local info = real(...)
			if type(info) == "table" then
				info.isOnGCD = nil
			end
			return info
		end
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: a spell cooling, with no answer for isOnGCD, is dimmed and has a sweep", cdIcons(W)[1].texture.desaturated == true and cdIcons(W)[1].cooldown.cd.sweep ~= nil and cdQuiet(W), cdTrouble(W))
		W.env.C_Spell.GetSpellCooldown = function(...)
			local info = real(...)
			if type(info) == "table" then
				info.isOnGCD = SECRET
			end
			return info
		end
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("cooldown: and with a withheld isOnGCD", cdIcons(W)[1].texture.desaturated == true and cdQuiet(W), cdTrouble(W))
	end

	do
		-- What is saved is cleaned: extra keys and holes go, and the list is replaced.
		local W = cdUp({ char = { cooldowns = { 408, 2094, junk = true } } })
		W.slash("cooldown list")
		check("saved list: a key that is not a position goes", cdSaved(W).junk == nil and cdList(cdSaved(W)) == "408,2094")
		local H = cdUp({ char = { cooldowns = { 408, [3] = 2094 } } })
		H.slash("cooldown list")
		check("saved list: a list with a hole is cut at the hole and replaced", cdList(cdSaved(H)) == "408" and cdSaved(H)[3] == nil, cdList(cdSaved(H)))
	end

	do
		-- The functions the dropdown and the slash command use, called with what they are not meant for.
		local W = cdUp(nil, { SP.KIDNEY })
		local ok, message = W.ns.CooldownAdd(424242)
		check("ns.CooldownAdd: an ID the game has no name for is refused", ok == false and message == 'No spell found for "424242".' and cdList(cdSaved(W)) == "408")
		check("ns.CooldownAdd: zero, a fraction, text and nothing are refused", W.ns.CooldownAdd(0) == false and W.ns.CooldownAdd(1.5) == false and W.ns.CooldownAdd("2094") == false and W.ns.CooldownAdd(nil) == false
			and cdList(cdSaved(W)) == "408")
		ok, message = W.ns.CooldownRemove(424242)
		check("ns.CooldownRemove: an ID that is not picked changes nothing", ok == false and message == "Spell 424242 is not picked." and cdList(cdSaved(W)) == "408")
		ok, message = W.ns.CooldownRemove(SP.KIDNEY)
		check("ns.CooldownRemove: one that is picked goes, and the message says which", ok == true and message == "Removed Kidney Shot." and cdList(cdSaved(W)) == "")
		ok, message = W.ns.CooldownAdd(SP.KIDNEY)
		check("ns.CooldownAdd: an ID the game names is added", ok == true and message == "Added Kidney Shot." and cdList(cdSaved(W)) == "408")
	end

	do
		-- A duration object that cannot be had clears the sweep that was there.
		for _, fault in ipairs({ "nothing", "error" }) do
			local W = cdUp(nil, { SP.KIDNEY })
			W.setCooldown(SP.KIDNEY, "cooling")
			W.fire("SPELL_UPDATE_COOLDOWN")
			local rec = cdIcons(W)[1]
			check("cooldown: a sweep is there while the game gives the duration", rec.cooldown.cd.sweep ~= nil)
			W.sp.fault.GetSpellCooldownDuration = fault
			W.fire("SPELL_UPDATE_COOLDOWN")
			check("cooldown: GetSpellCooldownDuration " .. (fault == "nothing" and "returning nothing" or "raising") .. " clears the sweep, the icon stays dimmed, nothing fails", rec.cooldown.cd.sweep == nil and not rec.cooldown.shown
				and rec.texture.desaturated == true and cdQuiet(W) and not has(W.status(), "failed"), cdTrouble(W))
		end
		-- With all charges back, the sweep that would be drawn is the spell's own, which is empty.
		local C = cdUp(nil, { SP.CHARGED })
		C.setCharges(SP.CHARGED, 3, false)
		C.fire("SPELL_UPDATE_CHARGES")
		local cd = cdIcons(C)[1].cooldown.cd
		check("charges: with every charge back no recharge sweep is asked for", cd.object and C.durations[cd.object].kind == "cooldown" and cd.sweep == nil)
		C.setCharges(SP.CHARGED, 2, true)
		C.fire("SPELL_UPDATE_CHARGES")
		check("charges: with one recharging the recharge sweep is", C.durations[cd.object].kind == "charge" and cd.sweep ~= nil)
	end

	do
		-- With the page off in combat, the end of a cooldown changes nothing.
		local W = cdUp(nil, { SP.KIDNEY })
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		local rec = cdIcons(W)[1]
		W.combat = true
		W.change("cooldowns.enabled", false)
		W.finishCooldown(SP.KIDNEY)
		check("page off in combat: the end of a cooldown does not update the icon", rec.texture.desaturated == true and cdQuiet(W), cdTrouble(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		-- Switching off asks the game for nothing more.
		local on = cdUp(nil, { SP.KIDNEY, SP.BLIND })
		local calls = on.sp.calls.GetSpellCooldown
		on.change("cooldowns.enabled", false)
		check("page off: the icons that were shown are not updated once the page is off", on.sp.calls.GetSpellCooldown == calls, on.sp.calls.GetSpellCooldown - calls)
	end

	do
		-- No spell, a cooldown manager and its option off: no holder on screen. On: it is there to look.
		local W = cdViewerWorld({ cooldowns = {} })
		check("manager: with no spell and the manager on, the holder is there", cdHolder(W) and cdHolder(W).shown)
		W.change("cooldowns.manager", false)
		check("manager: with no spell and the option off, the holder is hidden", not cdHolder(W).shown)
		W.change("cooldowns.manager", true)
		check("manager: and on again it is shown", cdHolder(W).shown)
	end

	do
		-- A spell the book gives under another ID, and spells of one name.
		local W = cdUp()
		W.addSpell(9201, { name = "Override", base = 1000, override = 9202 })
		W.addSpell(9202, { name = "Override", known = false })
		W.addSpell(9003, { name = "Twin", base = 1000 })
		W.addSpell(9004, { name = "Twin", base = 1000 })
		local values, twins = {}, {}
		for _, entry in ipairs(W.control("cooldowns.add").data.options()) do
			if entry.label == "Override" then
				values[#values + 1] = entry.value
			elseif entry.label == "Twin" then
				twins[#twins + 1] = entry.value
			end
		end
		check("Add a spell: a spell the book gives under its overriding ID is offered under that ID", #values == 1 and values[1] == 9202, table.concat(values, ","))
		check("Add a spell: spells of one name are in the order of their IDs", table.concat(twins, ",") == "9003,9004", table.concat(twins, ","))
	end

	do
		-- PLAYER_ENTERING_WORLD alone lays the row out and looks at the cooldown manager.
		local W = cdViewerWorld({ cooldowns = {} }, { SP.KIDNEY, SP.BLIND })
		W.sp.data[SP.BLIND].known = false
		W.sp.data[SP.BLIND].line = nil
		W.fire("SPELLS_CHANGED")
		W.flush()
		check("PLAYER_ENTERING_WORLD: the row has the spell that is known", cdRowIcons(W) == "132298")
		W.sp.data[SP.BLIND].known = true
		W.sp.data[SP.BLIND].line = 1
		local item = W.addViewerItem("EssentialCooldownViewer")
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		check("PLAYER_ENTERING_WORLD: the row is laid out at once", cdRowIcons(W) == "132298,136175")
		check("PLAYER_ENTERING_WORLD: and the cooldown manager is looked at on the next frame", W.cdm.look(item) == item.pristine)
		W.tick()
		check("PLAYER_ENTERING_WORLD: so the new item is styled then", W.state(item.icon) == "Sb" and cdQuiet(W), cdTrouble(W))
	end


	-- 89. Cooldown icons after the review. The arrows beside the two lists would pick the line after the selected one.
	do
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND, SP.VANISH })
		check("lists: Add a spell has no arrows beside it", W.arrows("cooldowns.add") == false)
		check("lists: Remove a spell has none either", W.arrows("cooldowns.remove") == false)
		check("lists: the dropdowns that hold a value keep theirs", W.arrows("cooldowns.place") and W.arrows("cooldowns.grow") and W.arrows("cooldowns.rows") and W.arrows("nameplates.level"))
		local before = cdList(cdSaved(W))
		for _, path in ipairs({ "cooldowns.remove", "cooldowns.add" }) do
			if W.arrows(path) then
				W.clickArrow(path, 1)
			end
		end
		check("lists: nothing is added or removed from the arrows", cdList(cdSaved(W)) == before and cdRowIcons(W) == "132298,136175,132331", cdList(cdSaved(W)))
		check("lists: no violation or error", cdQuiet(W), cdTrouble(W))
		local N = cdUp({ noReturn = true }, { SP.KIDNEY })
		check("lists: a client whose CreateDropdown returns nothing still gets both lists and raises nothing", N.control("cooldowns.add") ~= nil and N.control("cooldowns.remove") ~= nil and cdQuiet(N), cdTrouble(N))
	end

	-- 90. A sweep the game refuses, and a Cooldown frame that the call leaves hidden.
	local CD_SWEEP_REFUSED = "Cooldown icons: the game refused to draw cooldown sweeps, so icons dim without a sweep."
	do
		local W = cdUp(nil, { SP.KIDNEY, SP.BLIND, SP.VANISH, SP.KICK, SP.CHARGED, SP.CLOAK })
		local icons = cdIcons(W)
		local real = icons[1].cooldown.SetCooldownFromDurationObject
		for _, id in ipairs({ SP.KIDNEY, SP.BLIND, SP.VANISH, SP.KICK, SP.CLOAK }) do
			W.setCooldown(id, "cooling")
		end
		W.setCharges(SP.CHARGED, 2, true)
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELL_UPDATE_CHARGES")
		check("sweep refused: with the call accepted the sweeps are drawn", icons[1].cooldown.cd.sweep ~= nil and icons[5].cooldown.cd.sweep ~= nil and count(W.status(), CD_SWEEP_REFUSED) == 0)
		for _, rec in ipairs(icons) do
			rec.cooldown.SetCooldownFromDurationObject = function() error("refused", 0) end
		end
		for _ = 1, 6 do
			W.fire("SPELL_UPDATE_COOLDOWN")
			W.fire("SPELL_UPDATE_CHARGES")
			W.frameUpdate(0.2)
		end
		check("sweep refused: the icons dim all the same", icons[1].texture.desaturated == true and near(icons[1].texture.vertex[1], 0.6) and icons[5].texture.desaturated == false)
		check("sweep refused: the count and the numbers are still set", icons[5].count.text == "2" and icons[1].cooldown.cd.hideNumbers == false)
		check("sweep refused: the Cooldown frames are clear and hidden", icons[1].cooldown.cd.sweep == nil and not icons[1].cooldown.shown and icons[5].cooldown.cd.sweep == nil)
		check("sweep refused: no icon is counted as failed and the part is not stopped, however many are refused", W.line("Cooldowns") == "Cooldowns: on, 6 styled", W.line("Cooldowns"))
		check("sweep refused: the status says so once", count(W.status(), CD_SWEEP_REFUSED) == 1, W.status())
		check("sweep refused: nothing raises", cdQuiet(W), cdTrouble(W))
		icons[1].cooldown.SetCooldownFromDurationObject = real
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("sweep refused: when the game takes the call again the sweep is drawn", icons[1].cooldown.cd.sweep ~= nil and icons[1].cooldown.shown and icons[2].cooldown.cd.sweep == nil)
	end

	do
		-- The call may leave a frame the template hides as it was.
		local W = cdUp({ cooldowns = { objectNoShow = true } }, { SP.KIDNEY, SP.CHARGED, SP.BLIND })
		local k, c, b = cdIcons(W)[1], cdIcons(W)[2], cdIcons(W)[3]
		local shows = 0
		local realShow = k.cooldown.Show
		k.cooldown.Show = function(...)
			shows = shows + 1
			return realShow(...)
		end
		check("sweep shown: ready spells leave the Cooldown frames hidden and make no call to show them", not k.cooldown.shown and not c.cooldown.shown and shows == 0)
		W.setCooldown(SP.KIDNEY, "cooling")
		W.setCharges(SP.CHARGED, 2, true)
		W.setCooldown(SP.BLIND, "gcd")
		W.fire("SPELL_UPDATE_COOLDOWN")
		W.fire("SPELL_UPDATE_CHARGES")
		check("sweep shown: a spell on cooldown has its Cooldown frame shown with the sweep", k.cooldown.shown and k.cooldown.cd.sweep ~= nil and cdQuiet(W), cdTrouble(W))
		check("sweep shown: and a spell that recharges", c.cooldown.shown and c.cooldown.cd.sweep and c.cooldown.cd.sweep.info.kind == "charge")
		check("sweep shown: a spell on the global cooldown alone has nothing to show", not b.cooldown.shown and b.cooldown.cd.sweep == nil)
		W.finishCooldown(SP.KIDNEY)
		W.setCooldown(SP.KIDNEY, "ready")
		shows = 0
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("sweep shown: when the cooldown ends the frame is hidden and is not shown again", not k.cooldown.shown and shows == 0 and k.texture.desaturated == false)
		W.combat = true
		W.setCooldown(SP.KIDNEY, "cooling")
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("sweep shown: in combat too, which the addon's own frame allows", k.cooldown.shown and k.cooldown.cd.sweep ~= nil and cdQuiet(W), cdTrouble(W))
	end

	-- 91. Pieces the game lacks: /flatui status says what is missing, and an event does not need C_Timer.
	local CD_NO_COOLDOWNS = "Cooldown icons: the game has no spell cooldown information, so the row shows no cooldowns."
	local CD_NO_BOOK = "Cooldown icons: the game has no spell book information, so Add a spell lists nothing."
	do
		local CASES = {
			{ "C_Spell", CD_NO_COOLDOWNS }, { "C_Spell.GetSpellCooldown", CD_NO_COOLDOWNS },
			{ "C_SpellBook", CD_NO_BOOK }, { "C_SpellBook.GetNumSpellBookSkillLines", CD_NO_BOOK }, { "C_SpellBook.GetSpellBookSkillLineInfo", CD_NO_BOOK },
			{ "C_SpellBook.GetSpellBookItemInfo", CD_NO_BOOK }, { "Enum", CD_NO_BOOK }, { "Enum.SpellBookSpellBank", CD_NO_BOOK }, { "Enum.SpellBookItemType", CD_NO_BOOK },
		}
		for _, case in ipairs(CASES) do
			local W = newWorld({ cooldowns = true, without = { [case[1]] = true }, char = { cooldowns = { SP.KIDNEY } } })
			cdBook(W)
			W.login()
			W.flush()
			local other = case[2] == CD_NO_BOOK and CD_NO_COOLDOWNS or CD_NO_BOOK
			check("lacking " .. case[1] .. ": /flatui status says so, once, and says nothing about the other piece", count(W.status(), case[2]) == 1 and not has(W.status(), other), W.status())
			W.change("cooldowns.size", 38)
			check("lacking " .. case[1] .. ": and not again when the row is laid out again", count(W.status(), case[2]) == 1 and cdQuiet(W), cdTrouble(W))
		end
		local W = cdUp(nil, { SP.KIDNEY })
		check("lacking nothing: no such line", not has(W.status(), CD_NO_COOLDOWNS) and not has(W.status(), CD_NO_BOOK))
		local O = newWorld({ cooldowns = true, without = { C_Spell = true, C_SpellBook = true }, char = { cooldowns = { SP.KIDNEY } }, saved = { options = { ["cooldowns.enabled"] = false } } })
		cdBook(O)
		O.login()
		O.flush()
		check("lacking the spell functions with the page off: no line", not has(O.status(), CD_NO_COOLDOWNS) and not has(O.status(), CD_NO_BOOK), O.status())
		local E = newWorld({ cooldowns = true, without = { C_Spell = true, C_SpellBook = true } })
		cdBook(E)
		E.login()
		E.flush()
		check("lacking the spell functions with no spell picked: no row is wanted, so no line about the cooldown calls", not has(E.status(), CD_NO_COOLDOWNS), E.status())
		local T = cdViewerWorld({ without = { C_Timer = true } }, { SP.KIDNEY })
		local item = T.addViewerItem("EssentialCooldownViewer")
		T.fire("SPELLS_CHANGED")
		check("lacking C_Timer: an event looks at the cooldown manager at once, since nothing can wait for the next frame", T.state(item.icon) == "Sb" and cdRunning(T) and cdQuiet(T), cdTrouble(T) .. " " .. (T.line("Cooldowns") or ""))
	end

	-- 92. The two lists: a rank trained later and lines with the same name.
	do
		local W = cdUp(nil, { SP.EXPOSE1 })
		W.sp.data[SP.EXPOSE1].subtext = "Rank 1"
		W.sp.data[SP.EXPOSE3].subtext = "Rank 3"
		check("lists: a spell picked at a lower rank is not offered again at the rank trained since", table.concat(W.menu("cooldowns.add"), ",") == "Choose a spell,Blind,Charged Strike,Kick,Kidney Shot,Vanish", table.concat(W.menu("cooldowns.add"), ","))
		check("lists: and Remove a spell has it once", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Expose Armor")
		check("lists: both ranks can still be picked by ID, and then Remove a spell tells them apart by the text beside the name",
			W.slash("cooldown add 8650") == "Added Expose Armor." and table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Expose Armor (Rank 1),Expose Armor (Rank 3)", table.concat(W.menu("cooldowns.remove"), ","))
		W.sp.data[SP.EXPOSE1].subtext = ""
		W.sp.data[SP.EXPOSE3].subtext = nil
		check("lists: lines with the same name and no text beside it stay as they are", table.concat(W.menu("cooldowns.remove"), ",") == "Choose a spell,Expose Armor,Expose Armor")
		check("lists: no violation or error", cdQuiet(W), cdTrouble(W))
		local T = cdUp()
		T.addSpell(9003, { name = "Twin", base = 1000, subtext = "Rank 1" })
		T.addSpell(9004, { name = "Twin", base = 1000, subtext = "Rank 2" })
		check("lists: Add a spell tells two spells of one name apart", table.concat(T.menu("cooldowns.add"), ",") == "Choose a spell,Blind,Charged Strike,Expose Armor,Kick,Kidney Shot,Twin (Rank 1),Twin (Rank 2),Vanish", table.concat(T.menu("cooldowns.add"), ","))
		T.slash("cooldown add 9003")
		check("lists: a spell of the same name as one picked is not offered", table.concat(T.menu("cooldowns.add"), ",") == "Choose a spell,Blind,Charged Strike,Expose Armor,Kick,Kidney Shot,Vanish")
		for _, fault in ipairs({ "error", "nothing", "secret" }) do
			local F = cdUp(nil, { SP.EXPOSE1, SP.EXPOSE3 })
			F.sp.data[SP.EXPOSE1].subtext = "Rank 1"
			F.sp.fault.GetSpellSubtext = fault
			check("lists: text beside the name that the game answers with " .. fault .. " is left out", table.concat(F.menu("cooldowns.remove"), ",") == "Choose a spell,Expose Armor,Expose Armor" and cdQuiet(F), cdTrouble(F))
		end
		local L = newWorld({ cooldowns = true, without = { ["C_Spell.GetSpellSubtext"] = true }, char = { cooldowns = { SP.EXPOSE1, SP.EXPOSE3 } } })
		cdBook(L)
		L.login()
		L.flush()
		check("lacking C_Spell.GetSpellSubtext: the lines keep their plain names and nothing raises", table.concat(L.menu("cooldowns.remove"), ",") == "Choose a spell,Expose Armor,Expose Armor" and cdQuiet(L), cdTrouble(L))
		local B = cdUp(nil, { SP.KIDNEY })
