	do
		-- ms-cdi: the look, the states, the numbers, the keys and the trinkets of the cooldown icons.
		local MS = {}
		function MS.up(picked, options)
			return cdUp(options, picked or { SP.KIDNEY, SP.BLIND })
		end
		function MS.cool(W, id)
			W.setCooldown(id, "cooling")
			W.fire("SPELL_UPDATE_COOLDOWN")
		end
		function MS.set(W, path, value)
			W.change(path, value)
			W.flush()
		end
		-- The calls a client answers for equipped items: the trinkets by slot (13 and 14), their pictures and their cooldowns.
		function MS.gear(W, items)
			W.itemCd = {}
			W.env.GetTime = function() return W.now end
			W.env.GetInventoryItemID = function(_, slot) return items[slot] end
			W.env.C_Item = {
				GetItemIconByID = function(id) return 900000 + id end,
				GetItemCooldown = function(id)
					if W.itemSecret then
						return SECRET, SECRET, true
					end
					local c = W.itemCd[id]
					return c and c[1] or 0, c and c[2] or 0, true
				end,
			}
		end
		-- The calls a client answers for keys: the slots of a spell, the binding of a button and the text of a key.
		function MS.keys(W, slots, keys)
			W.asked = {}
			W.env.C_ActionBar = { FindSpellActionButtons = function(id) return slots[id] end }
			W.env.GetBindingKey = function(name)
				W.asked[#W.asked + 1] = name
				return keys[name]
			end
			W.env.GetBindingText = function(key) return (key:gsub("SHIFT%-", "S-")) end
		end
		-- The border of an icon: its edges, its background and the colour of the edges.
		function MS.look(rec)
			local outline, back
			for _, child in ipairs(rec.frame.children) do
				if #child.regions == 4 then
					outline = child
				end
			end
			for _, r in ipairs(rec.frame.regions) do
				if r.layer == "BACKGROUND" then
					back = r
				end
			end
			local edge = outline.regions[1]
			return { shown = edge.shown, back = back.shown, r = edge.color[1], g = edge.color[2], b = edge.color[3], state = (edge.shown and "S" or "h") .. (back.shown and "B" or "b") }
		end
		function MS.bind(rec)
			for _, r in ipairs(rec.top and rec.top.regions or {}) do
				if r.kind == "FontString" and r.template == "NumberFontNormalSmallGray" then
					return r
				end
			end
		end
		function MS.alphas(W)
			local out = {}
			for _, rec in ipairs(cdShown(W)) do
				out[#out + 1] = g(rec.frame.alpha)
			end
			return table.concat(out, ",")
		end

		do
			local W = MS.up()
			local k, b = cdShown(W)[1], cdShown(W)[2]
			MS.cool(W, SP.KIDNEY)
			check("ms-cdi: defaults leave the icons as they were: crop, border, sweep, numbers font, opacity, no flash and no key text",
				near(k.texture.texCoord[1], 0.08) and MS.look(k).state == "SB" and k.cooldown.cd.calls.SetDrawSwipe == nil and k.cooldown.cd.calls.SetCountdownFont == nil
				and k.cooldown.cd.swipeColour[4] == 0.7 and k.frame.alpha == 1 and cdHolder(W).alpha == 1 and #W.cdGroups == 0 and #W.addonFonts == 2 and MS.bind(k) == nil, cdTrouble(W))
			check("ms-cdi: defaults: a cooling icon is grey and 40 percent darker, a ready one is not", k.texture.desaturated == true and near(k.texture.vertex[1], 0.6) and b.texture.desaturated == false and b.texture.vertex[1] == 1)
			check("ms-cdi: defaults: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up()
			local k = cdShown(W)[1]
			MS.set(W, "cooldowns.crop", 0)
			check("ms-cdi: Icon crop 0 shows the whole picture", near(k.texture.texCoord[1], 0) and near(k.texture.texCoord[2], 1) and near(k.texture.texCoord[3], 0) and near(k.texture.texCoord[4], 1))
			MS.set(W, "cooldowns.crop", 15)
			check("ms-cdi: Icon crop 15 trims 15 percent", near(k.texture.texCoord[1], 0.15) and near(k.texture.texCoord[2], 0.85))
			W.ns.CooldownAdd(SP.VANISH)
			W.flush()
			local v = cdShown(W)[3]
			check("ms-cdi: Icon crop: an icon made later has the crop", v and near(v.texture.texCoord[1], 0.15) and near(v.texture.texCoord[4], 0.85))
			MS.set(W, "cooldowns.crop", 8)
			check("ms-cdi: Icon crop back to 8", near(k.texture.texCoord[1], 0.08) and near(v.texture.texCoord[1], 0.08))
			MS.set(W, "cooldowns.border", false)
			check("ms-cdi: Icon border off hides the edges and the background of every icon", MS.look(k).state == "hb" and MS.look(v).state == "hb")
			MS.set(W, "cooldowns.border", true)
			check("ms-cdi: Icon border on again", MS.look(k).state == "SB" and MS.look(v).state == "SB")
			check("ms-cdi: crop and border: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up()
			local k, b = cdShown(W)[1], cdShown(W)[2]
			MS.cool(W, SP.KIDNEY)
			MS.set(W, "cooldowns.dimDesat", false)
			check("ms-cdi: Grey out on cooldown off keeps the colour and still darkens", k.texture.desaturated == false and near(k.texture.vertex[1], 0.6))
			MS.set(W, "cooldowns.dimDarkness", 80)
			check("ms-cdi: Darkness on cooldown 80 percent", near(k.texture.vertex[1], 0.2) and near(k.texture.vertex[3], 0.2))
			MS.set(W, "cooldowns.dimDarkness", 0)
			MS.set(W, "cooldowns.dimDesat", true)
			check("ms-cdi: Darkness 0 and grey on: grey and not darker", k.texture.desaturated == true and k.texture.vertex[1] == 1)
			MS.set(W, "cooldowns.dimDarkness", 40)
			MS.set(W, "cooldowns.dim", false)
			check("ms-cdi: Dim on cooldown off leaves both settings unused", k.texture.desaturated == false and k.texture.vertex[1] == 1 and b.texture.vertex[1] == 1)
			MS.set(W, "cooldowns.dim", true)
			check("ms-cdi: dim settings: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up({ SP.KIDNEY, SP.BLIND, SP.VANISH })
			MS.cool(W, SP.KIDNEY)
			MS.set(W, "cooldowns.coolAlpha", 50)
			check("ms-cdi: Opacity on cooldown: only the icon on cooldown is dimmer", MS.alphas(W) == "0.5,1,1", MS.alphas(W))
			MS.set(W, "cooldowns.readyAlpha", 0)
			check("ms-cdi: Opacity when ready 0: ready icons are clear and keep their place", MS.alphas(W) == "0.5,0,0" and #cdShown(W) == 3 and cdPlaced(W, 36, 3, 12, "center", "down") == "", MS.alphas(W))
			W.setCooldown(SP.KIDNEY, "gcd")
			W.fire("SPELL_UPDATE_COOLDOWN")
			check("ms-cdi: the global cooldown is not a cooldown for the opacity", MS.alphas(W) == "0,0,0", MS.alphas(W))
			MS.cool(W, SP.KIDNEY)
			W.sp.secretActive = true
			W.secretTruth = true
			W.fire("SPELL_UPDATE_COOLDOWN")
			local k = cdShown(W)[1]
			check("ms-cdi: a withheld isActive goes to SetAlphaFromBoolean unread", k.frame.alphaFromBoolean and k.frame.alphaFromBoolean.secret == true and near(k.frame.alpha, 0.5) and cdQuiet(W), cdTrouble(W))
			W.sp.secretActive, W.secretTruth = false, nil
			MS.set(W, "cooldowns.coolAlpha", 100)
			MS.set(W, "cooldowns.readyAlpha", 100)
			W.fire("SPELL_UPDATE_COOLDOWN")
			check("ms-cdi: opacity back to 100 percent", MS.alphas(W) == "1,1,1", MS.alphas(W))
			local holder = cdHolder(W)
			MS.set(W, "cooldowns.idleAlpha", 50)
			check("ms-cdi: Row opacity out of combat 50 percent", near(holder.alpha, 0.5), holder.alpha)
			W.combat = true
			W.fire("PLAYER_REGEN_DISABLED")
			check("ms-cdi: Row opacity: full in combat", holder.alpha == 1)
			W.combat = false
			W.fire("PLAYER_REGEN_ENABLED")
			W.flush()
			check("ms-cdi: Row opacity: back when combat ends", near(holder.alpha, 0.5))
			MS.set(W, "cooldowns.idleAlpha", 100)
			check("ms-cdi: Row opacity 100 percent", holder.alpha == 1)
			check("ms-cdi: opacity settings: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up()
			local k, b = cdShown(W)[1], cdShown(W)[2]
			MS.cool(W, SP.KIDNEY)
			local was = MS.look(k)
			check("ms-cdi: Border colour by state is off at first: both icons have the general border colour", MS.look(b).r == was.r and near(was.r, 0))
			MS.set(W, "cooldowns.borderState", true)
			local cool, ready = MS.look(k), MS.look(b)
			check("ms-cdi: Border colour by state: red on cooldown, green when ready", near(cool.r, 0xd9 / 255) and near(cool.g, 0x40 / 255) and near(ready.r, 0x4d / 255) and near(ready.g, 0xbf / 255) and near(ready.b, 0x59 / 255),
				g(cool.r) .. " " .. g(ready.g))
			MS.set(W, "cooldowns.readyColour", "ff112233")
			ready = MS.look(b)
			check("ms-cdi: Ready border colour", near(ready.r, 0x11 / 255) and near(ready.g, 0x22 / 255) and near(ready.b, 0x33 / 255))
			W.finishCooldown(SP.KIDNEY)
			W.flush()
			cool = MS.look(k)
			check("ms-cdi: a cooldown that ends turns the border to the ready colour", near(cool.r, 0x11 / 255) and near(cool.b, 0x33 / 255))
			MS.set(W, "cooldowns.coolingColour", "ff010203")
			MS.cool(W, SP.KIDNEY)
			cool = MS.look(k)
			check("ms-cdi: On cooldown border colour", near(cool.r, 1 / 255) and near(cool.g, 2 / 255) and near(cool.b, 3 / 255))
			MS.set(W, "cooldowns.border", false)
			check("ms-cdi: Icon border off hides the coloured border too", MS.look(k).state == "hb")
			MS.set(W, "cooldowns.border", true)
			MS.set(W, "cooldowns.borderState", false)
			check("ms-cdi: Border colour by state off: the general colour is back", near(MS.look(k).r, 0) and near(MS.look(b).r, 0))
			check("ms-cdi: border colours: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up()
			MS.cool(W, SP.KIDNEY)
			check("ms-cdi: Flash when ready is off: no animation is made", #W.cdGroups == 0)
			MS.set(W, "cooldowns.flash", true)
			check("ms-cdi: Flash when ready on: nothing happens until a cooldown ends", #W.cdGroups == 0)
			W.finishCooldown(SP.KIDNEY)
			local group = W.cdGroups[1]
			local fade = group and group.anims[1]
			check("ms-cdi: a cooldown that ends plays one flash: opacity from 0.6 to none in 0.4 seconds", #W.cdGroups == 1 and group.plays == 1 and fade.kind == "Alpha" and near(fade.from, 0.6) and fade.to == 0 and near(fade.duration, 0.4)
				and group.owner.shown == true, #W.cdGroups)
			group.scripts.OnFinished()
			check("ms-cdi: the white square is hidden when the flash is over", group.owner.shown == false)
			MS.cool(W, SP.KIDNEY)
			W.finishCooldown(SP.KIDNEY)
			check("ms-cdi: the next end plays the same flash again", #W.cdGroups == 1 and group.plays == 2 and group.owner.shown == true)
			MS.set(W, "cooldowns.flash", false)
			MS.cool(W, SP.KIDNEY)
			W.finishCooldown(SP.KIDNEY)
			check("ms-cdi: Flash off: no more flashes", group.plays == 2)
			check("ms-cdi: flash: no violation or error", cdQuiet(W), cdTrouble(W))
			local N = MS.up({ SP.KIDNEY, SP.BLIND, SP.VANISH }, { cooldowns = { noAnimation = true } })
			MS.set(N, "cooldowns.flash", true)
			for _, id in ipairs({ SP.KIDNEY, SP.BLIND, SP.VANISH }) do
				MS.cool(N, id)
				N.finishCooldown(id)
			end
			check("ms-cdi: a client that cannot make an animation: the flash part stops with a line, the row goes on and nothing raises",
				has(N.status(), "Cooldowns: ready flash stopped.") and not has(N.status(), "Cooldowns stopped") and #cdShown(N) == 3 and cdQuiet(N), N.status())
		end

		do
			local W = MS.up()
			local k, b = cdShown(W)[1], cdShown(W)[2]
			MS.set(W, "cooldowns.numbersFont", "Normal")
			check("ms-cdi: Countdown number size Normal: the countdown font of every icon", k.cooldown.cd.font == "NumberFontNormal" and b.cooldown.cd.font == "NumberFontNormal" and k.cooldown.cd.calls.SetCountdownFont == 1)
			MS.set(W, "cooldowns.numbersFont", "Huge")
			check("ms-cdi: Countdown number size Huge", k.cooldown.cd.font == "NumberFontNormalHuge" and k.cooldown.cd.calls.SetCountdownFont == 2)
			MS.cool(W, SP.KIDNEY)
			check("ms-cdi: the font is not set again by each update", k.cooldown.cd.calls.SetCountdownFont == 2)
			MS.set(W, "cooldowns.numbersFont", "Large")
			MS.set(W, "cooldowns.numbersFont", "Small")
			check("ms-cdi: Countdown number size Large and Small", k.cooldown.cd.font == "NumberFontNormalSmall" and k.cooldown.cd.calls.SetCountdownFont == 4)
			MS.set(W, "cooldowns.numbersFont", "As the game has it")
			check("ms-cdi: As the game has it puts back the font that was read, once, and sets no other",
				k.cooldown.cd.fsFont[1] == "Fonts\\ARIALN.TTF" and k.cooldown.cd.fsFont[2] == 14 and k.cooldown.cd.fsFont[3] == "OUTLINE" and k.cooldown.cd.calls.SetFont == 1
				and b.cooldown.cd.fsFont[1] == "Fonts\\ARIALN.TTF" and k.cooldown.cd.calls.SetCountdownFont == 4, tostring(k.cooldown.cd.fsFont[1]))
			MS.set(W, "cooldowns.numbersFont", "Small")
			check("ms-cdi: a size chosen again after going back to the game's font is set", k.cooldown.cd.font == "NumberFontNormalSmall" and k.cooldown.cd.calls.SetCountdownFont == 5)
			MS.set(W, "cooldowns.numbersFont", "As the game has it")
			check("ms-cdi: going back a second time puts back the first font read, not the one the addon set", k.cooldown.cd.fsFont[1] == "Fonts\\ARIALN.TTF" and k.cooldown.cd.calls.SetFont == 2)
			MS.set(W, "cooldowns.numbers", false)
			check("ms-cdi: Countdown numbers off still hides the numbers", k.cooldown.cd.hideNumbers == true)
			check("ms-cdi: numbers font: no violation or error", cdQuiet(W), cdTrouble(W))
			local R = MS.up(nil, { cooldowns = { fontRefused = true } })
			MS.set(R, "cooldowns.numbersFont", "Large")
			check("ms-cdi: a refused countdown font: one line in the status and the row goes on", count(R.status(), "the game refused the countdown font, so Countdown number size is not applied.") == 1 and #cdShown(R) == 2 and cdQuiet(R), R.status())
		end

		do
			local W = MS.up({ SP.KIDNEY, SP.BLIND, SP.CHARGED })
			local k, c = cdShown(W)[1], cdShown(W)[3]
			MS.set(W, "cooldowns.sweep", false)
			check("ms-cdi: Cooldown sweep off: no sweep drawn on any icon, the numbers stay", k.cooldown.cd.drawSwipe == false and c.cooldown.cd.drawSwipe == false and k.cooldown.cd.hideNumbers == false)
			MS.set(W, "cooldowns.sweep", true)
			check("ms-cdi: Cooldown sweep on again", k.cooldown.cd.drawSwipe == true and k.cooldown.cd.calls.SetDrawSwipe == 2)
			MS.set(W, "cooldowns.sweepAlpha", 30)
			check("ms-cdi: Sweep opacity 30 percent on every icon", near(k.cooldown.cd.swipeColour[4], 0.3) and near(c.cooldown.cd.swipeColour[4], 0.3) and k.cooldown.cd.swipeColour[1] == 0)
			W.ns.CooldownAdd(SP.VANISH)
			W.flush()
			check("ms-cdi: Sweep opacity: an icon made later has it", near(cdShown(W)[4].cooldown.cd.swipeColour[4], 0.3))
			MS.set(W, "cooldowns.sweepAlpha", 70)
			check("ms-cdi: Sweep opacity back to 70 percent", near(k.cooldown.cd.swipeColour[4], 0.7))
			local font = c.count.font and c.count.font[2]
			MS.set(W, "cooldowns.countSize", 200)
			check("ms-cdi: Charge count size 200 percent doubles the count", c.count.font and near(c.count.font[2], 24) and k.count.font and near(k.count.font[2], 24), tostring(c.count.font and c.count.font[2]))
			MS.set(W, "cooldowns.countSize", 100)
			check("ms-cdi: Charge count size back to the game's size", c.count.font and near(c.count.font[2], 12), tostring(font))
			check("ms-cdi: sweep and count: no violation or error", cdQuiet(W), cdTrouble(W))
		end

		do
			local W = MS.up({ SP.KIDNEY, SP.BLIND, SP.VANISH })
			local keys = { MULTIACTIONBAR1BUTTON1 = "SHIFT-1", ACTIONBUTTON3 = "3" }
			MS.keys(W, { [SP.KIDNEY] = { 61 }, [SP.BLIND] = { 200, 3 } }, keys)
			check("ms-cdi: Keybind on icons is off at first: no font string and no question to the game", MS.bind(cdShown(W)[1]) == nil and #W.asked == 0 and #W.addonFonts == 3)
			MS.set(W, "cooldowns.keybind", true)
			local k, b, v = cdShown(W)[1], cdShown(W)[2], cdShown(W)[3]
			local kb = MS.bind(k)
			check("ms-cdi: Keybind on icons: the key of the first button that holds the spell, at the top right", kb and kb.text == "S-1" and MS.bind(b).text == "3" and MS.bind(v).text == "", kb and kb.text)
			local p = kb.points[1]
			check("ms-cdi: Keybind: the text sits at the top right of the frame over the icon", p and p[1] == "TOPRIGHT" and p[2] == k.top and p[3] == "TOPRIGHT" and kb.layer == "OVERLAY")
			keys.MULTIACTIONBAR1BUTTON1 = "CTRL-F"
			W.fire("UPDATE_BINDINGS")
			check("ms-cdi: UPDATE_BINDINGS writes the new key", kb.text == "CTRL-F", kb.text)
			keys.MULTIACTIONBAR1BUTTON1 = nil
			W.fire("UPDATE_BINDINGS")
			check("ms-cdi: a spell whose button has no key shows none", kb.text == "")
			W.env.C_ActionBar.FindSpellActionButtons = function(id) return id == SP.KIDNEY and { 3 } or nil end
			W.fire("ACTIONBAR_SLOT_CHANGED")
			check("ms-cdi: ACTIONBAR_SLOT_CHANGED looks the slots up again", kb.text == "3" and MS.bind(b).text == "", kb.text)
			MS.set(W, "cooldowns.keybindSize", 200)
			check("ms-cdi: Keybind size 200 percent", kb.font and near(kb.font[2], 24), tostring(kb.font and kb.font[2]))
			MS.set(W, "cooldowns.keybind", false)
			check("ms-cdi: Keybind on icons off clears the text", kb.text == "" and MS.bind(b).text == "")
			check("ms-cdi: keybind: no violation or error", cdQuiet(W), cdTrouble(W))
			local cases = { { 1, "ACTIONBUTTON1" }, { 12, "ACTIONBUTTON12" }, { 13, "ACTIONBUTTON1" }, { 24, "ACTIONBUTTON12" }, { 25, "MULTIACTIONBAR3BUTTON1" }, { 36, "MULTIACTIONBAR3BUTTON12" }, { 37, "MULTIACTIONBAR4BUTTON1" },
				{ 48, "MULTIACTIONBAR4BUTTON12" }, { 49, "MULTIACTIONBAR2BUTTON1" }, { 60, "MULTIACTIONBAR2BUTTON12" }, { 61, "MULTIACTIONBAR1BUTTON1" }, { 72, "MULTIACTIONBAR1BUTTON12" },
				{ 73, "ACTIONBUTTON1" }, { 132, "ACTIONBUTTON12" }, { 133 }, { 144 }, { 145, "MULTIACTIONBAR5BUTTON1" }, { 156, "MULTIACTIONBAR5BUTTON12" }, { 157, "MULTIACTIONBAR6BUTTON1" }, { 168, "MULTIACTIONBAR6BUTTON12" },
				{ 169, "MULTIACTIONBAR7BUTTON1" }, { 180, "MULTIACTIONBAR7BUTTON12" }, { 181 } }
			local S = MS.up({ SP.KIDNEY })
			local slot
			MS.keys(S, {}, setmetatable({}, { __index = function() return "K" end }))
			S.env.C_ActionBar.FindSpellActionButtons = function() return { slot } end
			MS.set(S, "cooldowns.keybind", true)
			local wrong = {}
			for _, case in ipairs(cases) do
				slot = case[1]
				S.asked = {}
				S.fire("ACTIONBAR_SLOT_CHANGED")
				if S.asked[1] ~= case[2] then
					wrong[#wrong + 1] = slot .. "=" .. tostring(S.asked[1])
				end
			end
			check("ms-cdi: Keybind: every slot of the action bars maps to the binding of its button (MultiActionBars.lua:1-9, Blizzard_Keybindings.lua:321-335, ActionBarController.lua:167-170)", #wrong == 0, table.concat(wrong, " "))
			S.env.GetBindingKey = nil
			S.fire("UPDATE_BINDINGS")
			check("ms-cdi: a client without the key calls: one line in the status, no text and no error", count(S.status(), "the game has no action bar key information, so Keybind on icons shows no keys.") == 1 and cdQuiet(S), S.status())
		end

		do
			local W = MS.up({ SP.KIDNEY, SP.BLIND })
			MS.set(W, "cooldowns.trinkets", true)
			check("ms-cdi: Equipped trinkets in a client without equipment calls: a line in the status, only the spells", has(W.status(), "the game has no equipment information, so Equipped trinkets shows nothing.") and #cdShown(W) == 2 and cdQuiet(W), W.status())
			local items = { [13] = 1001, [14] = 1002 }
			local E = MS.up({ SP.KIDNEY, SP.BLIND })
			MS.gear(E, items)
			check("ms-cdi: Equipped trinkets is off at first: only the picked spells", #cdShown(E) == 2)
			MS.set(E, "cooldowns.trinkets", true)
			check("ms-cdi: Equipped trinkets: two icons after the picked spells, with the item pictures", cdRowIcons(E) == "132298,136175,901001,901002", cdRowIcons(E))
			check("ms-cdi: Equipped trinkets: placed as the row places them", cdPlaced(E, 36, 3, 12, "center", "down") == "", cdPlaced(E, 36, 3, 12, "center", "down"))
			local t1, t2 = cdShown(E)[3], cdShown(E)[4]
			E.itemCd[1001] = { E.now, 60 }
			E.fire("BAG_UPDATE_COOLDOWN")
			local sweep = t1.cooldown.cd.sweep
			check("ms-cdi: a trinket on cooldown: the sweep from its start and duration, the icon dimmed", sweep and sweep.kind == "numbers" and sweep.start == E.now and sweep.duration == 60 and t1.texture.desaturated == true
				and near(t1.texture.vertex[1], 0.6) and t2.texture.desaturated == false and t2.cooldown.cd.sweep == nil, tostring(sweep))
			check("ms-cdi: a trinket has no count and no key", t1.count.text == "" and MS.bind(t1) == nil)
			MS.set(E, "cooldowns.coolAlpha", 50)
			check("ms-cdi: a trinket takes the opacity of its state", near(t1.frame.alpha, 0.5) and t2.frame.alpha == 1)
			MS.set(E, "cooldowns.coolAlpha", 100)
			E.now = E.now + 61
			E.frameUpdate(0.2)
			check("ms-cdi: when the trinket's cooldown ends the icon is plain again", t1.texture.desaturated == false and t1.cooldown.cd.sweep == nil, tostring(t1.cooldown.cd.sweep))
			items[14] = nil
			E.fire("PLAYER_EQUIPMENT_CHANGED")
			E.flush()
			check("ms-cdi: an empty trinket slot has no icon", cdRowIcons(E) == "132298,136175,901001", cdRowIcons(E))
			items[13] = 1003
			items[14] = 1004
			E.fire("PLAYER_EQUIPMENT_CHANGED")
			E.flush()
			check("ms-cdi: a new trinket changes the icon", cdRowIcons(E) == "132298,136175,901003,901004", cdRowIcons(E))
			E.itemSecret = true
			E.fire("BAG_UPDATE_COOLDOWN")
			check("ms-cdi: withheld trinket cooldowns: no sweep, one line in the status, nothing raises", cdShown(E)[3].cooldown.cd.sweep == nil and count(E.status(), "the game hides trinket cooldowns, so trinket icons show no sweep.") == 1 and cdQuiet(E), E.status())
			E.itemSecret = false
			MS.set(E, "cooldowns.trinkets", false)
			check("ms-cdi: Equipped trinkets off: the spells only", cdRowIcons(E) == "132298,136175", cdRowIcons(E))
			local O = MS.up({})
			MS.gear(O, { [13] = 1001 })
			MS.set(O, "cooldowns.trinkets", true)
			check("ms-cdi: Equipped trinkets with no spell picked: the row is the trinket", cdRowIcons(O) == "901001" and cdHolder(O).shown, cdRowIcons(O))
			local H = MS.up({ SP.KIDNEY })
			MS.gear(H, { [13] = 1001 })
			H.heard = 0
			H.env.PlaySound = function() H.heard = H.heard + 1 return true, 1 end
			MS.set(H, "cooldowns.readySound", true)
			MS.set(H, "cooldowns.trinkets", true)
			H.itemCd[1001] = { H.now, 60 }
			H.fire("BAG_UPDATE_COOLDOWN")
			H.now = H.now + 61
			H.frameUpdate(0.2)
			check("ms-cdi: Sound when ready plays once when a trinket's cooldown ends", H.heard == 1 and cdQuiet(H), H.heard)
		end
	end
end

-- 75. Status bar fills. The simulated client has the status bars when a world asks for them (fills = true): see "Status bar fills" in
-- newWorld for what is modelled. The helpers of sections 75 to 84 are fields of one table so that this file keeps its count of locals.
local FH = {}
-- A frame of the game's that takes HookScript, as the game's frames do: the functions hooked on each script are listed in raw.scriptHooks, and FH.script
-- runs them as the game does after its own code, with each run counted as the addon's code running inside the game's.
function FH.hookable(W, raw, script)
	raw.scriptHooks = {}
	raw.HookScript = function(_, which, fn)
		if type(which) ~= "string" or type(fn) ~= "function" then
			bad(W, "HookScript arguments")
		end
		if which ~= script then
			bad(W, "HookScript " .. which .. " on a frame that takes only " .. script)
		end
		raw.scriptHooks[which] = raw.scriptHooks[which] or {}
		table.insert(raw.scriptHooks[which], fn)
	end
end
-- hkunit: the game calls these methods from scripts of the frame (OnEvent, OnShow, OnValueChanged), and the addon follows the scripts with HookScript, never the methods.
-- A test that calls one of them as the game does (inside W.blizzard) stands for the script that calls it: when the outermost call ends, the hooks of that script run, and
-- the next frame is drawn. FH.follow names the event or script by method.
FH.follow = { CheckClassification = "UNIT_CLASSIFICATION_CHANGED", CheckFaction = "UNIT_FACTION", CheckLevel = "UNIT_LEVEL", CheckBattlePet = "TARGET",
	SetSmallSize = "TARGET", UpdateArt = "UNIT_CONNECTION", UpdateOnlineStatus = "GROUP_ROSTER_UPDATE", UpdateAuras = "AURA", Update = "UPDATE",
	InitializePartyMemberFrames = "OnShow", PartyMemberHealthCheck = "OnValueChanged" }
FH.depth = 0
function FH.after(W, frame, name)
	local raw = frame ~= nil and W.rawOf[frame]
	if not raw then
		return
	end
	local what, own = FH.follow[name], raw.name
	if what == "TARGET" or what == "AURA" or (what == "UPDATE" and (own == "TargetFrame" or own == "FocusFrame")) then
		what = own == "FocusFrame" and "PLAYER_FOCUS_CHANGED" or own == "TargetFrame" and "PLAYER_TARGET_CHANGED" or what == "AURA" and "UNIT_AURA" or "PLAYER_TARGET_CHANGED"
	elseif what == "UPDATE" then
		what = own == "TotemFrame" and "PLAYER_TOTEM_UPDATE" or own == "PetFrame" and "UNIT_PET" or nil
	end
	-- The hooks run, and then the next frame draws only what the unit frames asked for: the timers of no delay that its files set. Other timers keep waiting.
	if what == "OnShow" then
		W.hookRun(frame, "OnShow")
	elseif what == "OnValueChanged" then
		local box = raw.HealthBarContainer and W.rawOf[raw.HealthBarContainer]
		if box and box.HealthBar then
			W.hookRun(box.HealthBar, "OnValueChanged", 1)
		end
	elseif what then
		W.hookRun(frame, "OnEvent", what)
	else
		return
	end
	-- The timer of no delay that runs Later.run of UnitFrames.lua is found by the line its function is defined on.
	if FH.laterLine == nil then
		local number = 0
		for line in io.lines(ADDON_DIR .. "/UnitFrames.lua") do
			number = number + 1
			if line == "function Later.run()" then
				FH.laterLine = number
			end
		end
	end
	local mine, rest = {}, {}
	for _, timer in ipairs(W.timers) do
		local info = timer.delay == 0 and debug.getinfo(timer.fn, "S") or nil
		if info and info.short_src:find("UnitFrames.lua", 1, true) and info.linedefined == FH.laterLine then
			mine[#mine + 1] = timer
		else
			rest[#rest + 1] = timer
		end
	end
	W.timers = rest
	local was = W.inBlizzard
	W.inBlizzard = 0
	for _, timer in ipairs(mine) do
		timer.fn()
	end
	W.inBlizzard = was
end
function FH.wrap(W, name, fn)
	if not FH.follow[name] then
		return fn
	end
	return function(self, ...)
		FH.depth = FH.depth + 1
		local result = { pcall(fn, self, ...) }
		FH.depth = FH.depth - 1
		if not result[1] then
			error(result[2], 0)
		end
		if FH.depth == 0 and W.inBlizzard > 0 then
			FH.after(W, self, name)
		end
		return (table.unpack or unpack)(result, 2, #result)
	end
end
FH.SWING = { "SwingTimerMainHandFrame", "SwingTimerOffHandFrame", "SwingTimerRangedFrame" }
FH.SWING_HEX = { SwingTimerMainHandFrame = "ffd9a640", SwingTimerOffHandFrame = "ff5c9fd6", SwingTimerRangedFrame = "ff73b85c" }
FH.SWING_OPTION = { SwingTimerMainHandFrame = "swing.mainColour", SwingTimerOffHandFrame = "swing.offColour", SwingTimerRangedFrame = "swing.rangedColour" }
FH.CASTS = { "PlayerCastingBarFrame", "OverlayPlayerCastingBarFrame", "PetCastingBarFrame", "TargetFrameSpellBar", "FocusFrameSpellBar" }
FH.CAST_HEX = { cast = "ffe6b333", channel = "ff4dbf59", shield = "ff9a9a9a", interrupted = "ffd94040", craft = "ff4d99e6" }
FH.CAST_OPTION = { cast = "castbars.castColour", channel = "castbars.channelColour", shield = "castbars.shieldColour", interrupted = "castbars.interruptedColour",
	craft = "castbars.craftColour" }
FH.BAR_ATLAS = "UI-HUD-CoolDownManager-Bar"
FH.WARRIOR = "0.780,0.610,0.430"
function FH.rgb(c)
	return c and string.format("%.3f,%.3f,%.3f", c[1], c[2], c[3]) or "-"
end
-- "ffd9a640" as red, green and blue between 0 and 1.
function FH.hex(h)
	return string.format("%.3f,%.3f,%.3f", tonumber(h:sub(3, 4), 16) / 255, tonumber(h:sub(5, 6), 16) / 255, tonumber(h:sub(7, 8), 16) / 255)
end
-- A world with the status bars, logged in and drawn twice. before(W) runs between the world and the login.
function FH.world(opts, before)
	opts = opts or {}
	opts.fills = opts.fills or true
	local W = newWorld(opts)
	if before then
		before(W)
	end
	W.login()
	W.frame(2)
	return W
end
-- What the fill of a bar draws.
function FH.fill(W, bar)
	local r = W.rawOf[bar].fillRaw
	if not r then
		return "no fill"
	end
	return r.color and ("colour " .. FH.rgb(r.color)) or r.atlas and ("atlas " .. r.atlas) or r.file and ("file " .. r.file) or "empty"
end
-- How often the addon (not Blizzard) made a call on a bar.
function FH.n(W, bar, name)
	return W.rawOf[bar].byAddon[name] or 0
end
-- Every call of the addon that changes how a bar looks.
function FH.changes(W, bar)
	return FH.n(W, bar, "SetColorFill") + FH.n(W, bar, "SetStatusBarTexture") + FH.n(W, bar, "SetStatusBarColor")
end
-- The tint of a bar as red, green and blue.
function FH.tint(W, bar)
	return FH.rgb(W.rawOf[bar].tint)
end
function FH.polling(W)
	for _, frame in ipairs(W.eventFrames) do
		if frame.onUpdate and not frame.dividers then
			return true
		end
	end
	return false
end
-- The addon textures of a bar that are anchored to its fill region.
function FH.covers(W, bar)
	local list = {}
	local fill = W.rawOf[bar].fill
	for _, t in ipairs(W.addonTextures) do
		if t.owner == bar and fill ~= nil and t.points[1] and t.points[1][2] == fill then
			list[#list + 1] = t
		end
	end
	return list
end
function FH.cover(W, bar)
	return FH.covers(W, bar)[1]
end
-- All the addon textures anchored to any fill region.
function FH.allCovers(W)
	local n = 0
	for _, name in ipairs(FH.CASTS) do
		n = n + #FH.covers(W, W.fills.cast[name].bar)
	end
	return n
end
-- How the fill, the Pip and the label shadow of a swing timer look, as one line.
function FH.snap(W, s)
	local function one(r)
		return table.concat({ tostring(r.atlas), r.color and table.concat(r.color, ",") or "-", tostring(r.alpha), tostring(r.shown), #r.points, tostring(r.file) }, "/")
	end
	return one(s.fillRaw) .. " " .. one(s.pipRaw) .. " " .. one(s.shadowRaw) .. " " .. FH.tint(W, s.bar)
end
function FH.plain(W)
	return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and #W.partErrors == 0
end
function FH.why(W)
	return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. table.concat(W.partErrors, "|")
end

-- 75. Swing timers: the fill is a solid colour, set once, on the same region.
do
	local W = newWorld({ fills = true })
	local before, looks = {}, {}
	for _, name in ipairs(FH.SWING) do
		before[name] = W.fills.swing[name].bar:GetStatusBarTexture()
		looks[name] = FH.snap(W, W.fills.swing[name])
	end
	W.login()
	W.frame(2)
	local own, once, same, pips, other = true, true, true, true, true
	for _, name in ipairs(FH.SWING) do
		local s = W.fills.swing[name]
		own = own and FH.fill(W, s.bar) == "colour " .. FH.hex(FH.SWING_HEX[name]) and s.fillRaw.color[4] == 1
		once = once and FH.n(W, s.bar, "SetColorFill") == 1
		same = same and s.bar:GetStatusBarTexture() == before[name] and before[name] == s.fill
		pips = pips and s.pipRaw.calls.SetPoint == nil and s.pipRaw.calls.ClearAllPoints == nil and #s.pipRaw.points == 1 and s.pipRaw.points[1][2] == s.fill
		other = other and FH.n(W, s.bar, "SetStatusBarTexture") == 0 and FH.n(W, s.bar, "SetStatusBarColor") == 0 and FH.tint(W, s.bar) == "1.000,1.000,1.000"
	end
	check("swing fill: each timer's fill region is the colour of its hand", own)
	check("swing fill: set with one call on each bar", once)
	check("swing fill: the region the bar gives is the same object before and after the change", same)
	check("swing fill: the Pip stays anchored to the fill, with no call on its points", pips)
	check("swing fill: no texture is set and no tint is given", other)
	check("swing fill: the three timers are counted as styled", has(W.status(), "Swing timers: on, 3 styled") and not has(W.line("Swing timers"), "failed"), W.line("Swing timers"))
	local base = newWorld()
	base.login()
	check("swing fill: no hook is added to the game", W.hooks == base.hooks, W.hooks .. " " .. base.hooks)
	check("swing fill: no field is written on a timer or its bar, nothing is called that is the game's, nothing is printed", FH.plain(W), FH.why(W))
	-- The restore puts the same region back with the atlas it had.
	W.change("swing.flat", false)
	local back, atlases = true, true
	for _, name in ipairs(FH.SWING) do
		local s = W.fills.swing[name]
		back = back and s.bar:GetStatusBarTexture() == before[name]
		atlases = atlases and FH.fill(W, s.bar) == "atlas " .. s.atlas
	end
	check("swing fill: and after the restore", back)
	check("swing fill: the restore gives the atlas the game drew", atlases)
	local exact = true
	for _, name in ipairs(FH.SWING) do
		exact = exact and FH.snap(W, W.fills.swing[name]) == looks[name]
	end
	check("swing fill: the fill, Pip and label shadow look exactly as the game made them", exact)
end

-- 75b. A second Refresh with nothing changed makes no texture call; a changed colour makes one.
do
	local W = FH.world()
	local main, off = W.fills.swing.SwingTimerMainHandFrame, W.fills.swing.SwingTimerOffHandFrame
	W.change("swing.backdrop", false)
	W.change("swing.backdrop", true)
	W.change("general.thickness", 2)
	W.change("general.thickness", 1)
	W.ns.ResizeAll()
	W.flush()
	local quiet = true
	for _, name in ipairs(FH.SWING) do
		quiet = quiet and FH.changes(W, W.fills.swing[name].bar) == 1
	end
	check("swing fill: a Refresh with nothing changed makes no texture call", quiet)
	W.change("swing.mainColour", "ff336699")
	check("swing fill: a changed colour makes one SetColorFill on that timer", FH.n(W, main.bar, "SetColorFill") == 2 and FH.fill(W, main.bar) == "colour " .. FH.hex("ff336699")
		and FH.n(W, off.bar, "SetColorFill") == 1)
	check("swing fill: and no SetStatusBarTexture", FH.n(W, main.bar, "SetStatusBarTexture") == 0)
	W.change("swing.offColour", "ff102030")
	W.change("swing.rangedColour", "ff405060")
	check("swing fill: each hand has a setting of its own", FH.fill(W, off.bar) == "colour " .. FH.hex("ff102030") and FH.fill(W, W.fills.swing.SwingTimerRangedFrame.bar) == "colour " .. FH.hex("ff405060")
		and FH.fill(W, main.bar) == "colour " .. FH.hex("ff336699"))
	check("swing fill: colours are applied with the border switches on", FH.plain(W), FH.why(W))
end

-- 75c. Class colour.
do
	local W = FH.world()
	W.change("swing.classColour", true)
	local all = true
	for _, name in ipairs(FH.SWING) do
		all = all and FH.fill(W, W.fills.swing[name].bar) == "colour " .. FH.WARRIOR and FH.n(W, W.fills.swing[name].bar, "SetColorFill") == 2
	end
	check("swing class colour: all three timers have the player's class colour", all)
	W.change("swing.mainColour", "ff336699")
	check("swing class colour: a hand's own colour is not shown while it is on", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.WARRIOR
		and FH.n(W, W.fills.swing.SwingTimerMainHandFrame.bar, "SetColorFill") == 2)
	W.change("swing.classColour", false)
	check("swing class colour: off returns to the three colours", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ff336699")
		and FH.fill(W, W.fills.swing.SwingTimerOffHandFrame.bar) == "colour " .. FH.hex("ff5c9fd6") and FH.fill(W, W.fills.swing.SwingTimerRangedFrame.bar) == "colour " .. FH.hex("ff73b85c"))
	check("swing class colour: no violations", FH.plain(W), FH.why(W))

	-- A class the client does not give, or gives in a form that cannot be used, leaves the three colours.
	local cases = {
		{ "UnitClass answers nothing", function(X) X.fills.classFault = "nothing" end },
		{ "UnitClass is withheld", function(X) X.fills.classFault = "secret" end },
		{ "UnitClass fails", function(X) X.fills.classFault = "error" end },
		{ "the class has no colour", function(X) X.fills.class = "DEATHKNIGHT" end },
		{ "the class colour is withheld", function(X) X.env.RAID_CLASS_COLORS.WARRIOR = SECRET end },
		{ "the red of the class colour is withheld", function(X) X.env.RAID_CLASS_COLORS.WARRIOR.r = SECRET end },
		{ "the red of the class colour is a string", function(X) X.env.RAID_CLASS_COLORS.WARRIOR.r = "0.5" end },
		{ "the green of the class colour is a string", function(X) X.env.RAID_CLASS_COLORS.WARRIOR.g = "0.5" end },
		{ "the blue of the class colour is a string", function(X) X.env.RAID_CLASS_COLORS.WARRIOR.b = "0.5" end },
		{ "the class colour is not a table", function(X) X.env.RAID_CLASS_COLORS.WARRIOR = 5 end },
	}
	for _, case in ipairs(cases) do
		local X = FH.world({ saved = { options = { ["swing.classColour"] = true } } }, case[2])
		local ok = true
		for _, name in ipairs(FH.SWING) do
			ok = ok and FH.fill(X, X.fills.swing[name].bar) == "colour " .. FH.hex(FH.SWING_HEX[name])
		end
		check("swing class colour: " .. case[1] .. ", the three colours stay", ok and FH.plain(X) and not has(X.status(), "failed"), FH.why(X) .. X.status())
	end
	for _, case in ipairs({ { "no UnitClass", { noClass = true } } }) do
		local X = FH.world({ saved = { options = { ["swing.classColour"] = true } }, fills = case[2] })
		check("swing class colour: a client with " .. case[1] .. " and no RAID_CLASS_COLORS keeps the three colours", FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640")
			and FH.plain(X))
	end
	local Y = FH.world({ fills = { class = "MAGE" } })
	Y.change("swing.classColour", true)
	check("swing class colour: it is the colour of the player's own class", FH.fill(Y, Y.fills.swing.SwingTimerRangedFrame.bar) == "colour 0.410,0.800,0.940")
end

-- 75d. Flat fill off, the page off and the module stopped by an error each give the game's fill back, once.
do
	local function back(label, undo)
		local looks = {}
		local W = FH.world(nil, function(X)
			-- The atlas the fill draws is not the one in barTexture, so the one that was read is the one that is put back.
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].fillRaw.atlas = "drawn-" .. name
				looks[name] = FH.snap(X, X.fills.swing[name])
			end
		end)
		undo(W)
		W.flush()
		local once, atlas, colour = true, true, true
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			once = once and FH.n(W, s.bar, "SetStatusBarTexture") == 1
			atlas = atlas and FH.fill(W, s.bar) == "atlas drawn-" .. name and W.rawOf[s.bar].addonLog[#W.rawOf[s.bar].addonLog][2] == "drawn-" .. name
			colour = colour and s.fillRaw.color == nil
		end
		check("swing restore: " .. label .. " gives each timer one SetStatusBarTexture", once)
		check("swing restore: " .. label .. " uses the atlas that was read before the first change", atlas)
		check("swing restore: " .. label .. " leaves no colour on the fill", colour)
		local exact = true
		for _, name in ipairs(FH.SWING) do
			exact = exact and FH.snap(W, W.fills.swing[name]) == looks[name]
		end
		check("swing restore: " .. label .. " gives the fill, Pip and label shadow back exactly as the game had them", exact)
		check("swing restore: " .. label .. " puts back the spark and the label shadow", W.fills.swing.SwingTimerMainHandFrame.pipRaw.alpha == 1 and W.fills.swing.SwingTimerMainHandFrame.shadowRaw.alpha == 1)
		local m = W.fills.swing.SwingTimerMainHandFrame
		local alphas = (m.pipRaw.calls.SetAlpha or 0) + (m.shadowRaw.calls.SetAlpha or 0)
		W.change("swing.backdrop", false)
		W.change("swing.backdrop", true)
		W.change("general.thickness", 2)
		local again = true
		for _, name in ipairs(FH.SWING) do
			again = again and FH.n(W, W.fills.swing[name].bar, "SetStatusBarTexture") == 1 and FH.n(W, W.fills.swing[name].bar, "SetColorFill") == 1
		end
		check("swing restore: " .. label .. ", a Refresh after it makes no further call on a bar", again)
		check("swing restore: " .. label .. ", and none on the Pip or the label shadow", (m.pipRaw.calls.SetAlpha or 0) + (m.shadowRaw.calls.SetAlpha or 0) == alphas)
		return W
	end
	back("Flat fill off", function(W) W.change("swing.flat", false) end)
	back("the page off", function(W) W.change("swing.enabled", false) end)
	local W = back("a module stopped by an error", function(X) X.ns.Try("swing", function() error("probe", 0) end) end)
	check("swing restore: a stopped module is reported", has(W.status(), "Swing timers: stopped. probe"), W.status())
	check("swing restore: and the other modules run", has(W.status(), "Cast bars: on, 5 styled") and has(W.status(), "Personal resource display: on, 3 styled"))
end

-- 75e. When the fill does not say which atlas it draws.
do
	-- GetAtlas gives nothing, a withheld value, an error or a number: timer.barTexture is the atlas.
	for _, case in ipairs({ { "nothing", function(r) r.atlas = nil end }, { "a withheld value", function(r) r.fault.atlas = "secret" end },
		{ "an empty name", function(r) r.atlas = "" end }, { "a number", function(r) r.atlas = 5 end }, { "an error", function(r) r.fault.atlas = "error" end } }) do
		local W = FH.world(nil, function(X)
			for _, name in ipairs(FH.SWING) do
				case[2](X.fills.swing[name].fillRaw)
			end
		end)
		local s = W.fills.swing.SwingTimerOffHandFrame
		local flat = FH.fill(W, s.bar) == "colour " .. FH.hex("ff5c9fd6")
		-- The fill can be asked again only when it says so; make it readable and switch the fill off.
		for _, name in ipairs(FH.SWING) do
			W.fills.swing[name].fillRaw.fault.atlas = nil
		end
		W.change("swing.flat", false)
		check("swing fill: GetAtlas gives " .. case[1] .. ", timer.barTexture is used and the fill is solid", flat and FH.fill(W, s.bar) == "atlas " .. s.atlas, FH.fill(W, s.bar))
		check("swing fill: GetAtlas gives " .. case[1] .. ", nothing is wrong", FH.plain(W) and not has(W.status(), "failed"), FH.why(W))
	end
	-- A name the fill gives is the atlas to put back, whatever it is.
	do
		local W = FH.world(nil, function(X)
			X.fills.swing.SwingTimerMainHandFrame.fillRaw.fault.atlas = "string"
		end)
		W.fills.swing.SwingTimerMainHandFrame.fillRaw.fault.atlas = nil
		W.change("swing.flat", false)
		check("swing fill: a name from GetAtlas is the atlas that is put back", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "atlas x")
	end
	-- Neither source: the fill is left alone, and /flatui status says so.
	for _, case in ipairs({ { "no barTexture", nil }, { "a barTexture that is withheld", SECRET }, { "a barTexture that is a number", 7 }, { "an empty barTexture", false } }) do
		local W = FH.world(nil, function(X)
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].fillRaw.atlas = nil
				X.fills.swing[name].inner.barTexture = case[2]
			end
		end)
		local untouched = true
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			untouched = untouched and FH.changes(W, s.bar) == 0 and s.fillRaw.color == nil and s.pipRaw.alpha == 1 and s.shadowRaw.alpha == 1
		end
		check("swing fill: " .. case[1] .. " and no atlas, the fill, spark and shadow are left alone", untouched)
		check("swing fill: " .. case[1] .. ", /flatui status says the default fill could not be read, once",
			count(W.status(), "Swing timers: the default fill of a timer could not be read and is still shown.") == 1 and FH.plain(W) and not has(W.status(), "failed"), W.status())
	end
	-- The fill region is not there or cannot be read: the same, with no line.
	for _, case in ipairs({ { "nothing", "nothing" }, { "a withheld value", "secret" }, { "an error", "error" }, { "a string", "string" } }) do
		local W = FH.world(nil, function(X)
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].barRaw.fault.fillRegion = case[2]
			end
		end)
		local untouched = true
		for _, name in ipairs(FH.SWING) do
			untouched = untouched and FH.changes(W, W.fills.swing[name].bar) == 0
		end
		check("swing fill: GetStatusBarTexture gives " .. case[1] .. ", the bar is left alone without an error or a line in /flatui status", untouched and FH.plain(W) and not has(W.status(), "failed")
			and not has(W.status(), "could not be read"), FH.why(W) .. W.status())
	end
end

-- 75f. The spark (the Pip) and the label shadow.
do
	local W = FH.world()
	local s = W.fills.swing.SwingTimerMainHandFrame
	check("swing spark: at the defaults the Pip is shown and the label shadow is hidden", s.pipRaw.alpha == 1 and s.shadowRaw.alpha == 0)
	W.change("swing.spark", false)
	check("swing spark: off sets the Pip's alpha to 0 on all three", W.fills.swing.SwingTimerOffHandFrame.pipRaw.alpha == 0 and W.fills.swing.SwingTimerRangedFrame.pipRaw.alpha == 0 and s.pipRaw.alpha == 0)
	W.fills.swingStart("SwingTimerMainHandFrame")
	check("swing spark: the game showing the Pip leaves the alpha at 0", s.pipRaw.shown and s.pipRaw.alpha == 0)
	W.fills.swingClear("SwingTimerMainHandFrame")
	W.fills.swingStart("SwingTimerMainHandFrame")
	W.change("swing.backdrop", false)
	W.change("swing.backdrop", true)
	check("swing spark: and so does a Refresh", s.pipRaw.alpha == 0 and s.pipRaw.shown)
	W.change("swing.spark", true)
	check("swing spark: on sets it to 1", s.pipRaw.alpha == 1)
	W.change("swing.spark", false)
	W.change("swing.flat", false)
	check("swing spark: Flat fill off sets it to 1 whatever the Spark setting is", s.pipRaw.alpha == 1 and W.fills.swing.SwingTimerRangedFrame.pipRaw.alpha == 1)
	W.change("swing.flat", true)
	check("swing spark: Flat fill on again hides it again", s.pipRaw.alpha == 0)
	check("swing spark: the Pip's anchor was never touched", s.pipRaw.calls.SetPoint == nil and s.pipRaw.calls.ClearAllPoints == nil and s.pipRaw.points[1][2] == s.fill)
	W.change("swing.textShadow", true)
	check("swing shadow: on sets the label shadow's alpha to 1", s.shadowRaw.alpha == 1 and W.fills.swing.SwingTimerOffHandFrame.shadowRaw.alpha == 1)
	W.change("swing.textShadow", false)
	check("swing shadow: off sets it to 0", s.shadowRaw.alpha == 0)
	W.change("swing.flat", false)
	check("swing shadow: Flat fill off sets it to 1", s.shadowRaw.alpha == 1)
	W.change("swing.flat", true)
	W.change("swing.enabled", false)
	check("swing spark and shadow: the page off sets both to 1", s.pipRaw.alpha == 1 and s.shadowRaw.alpha == 1)
	W.change("swing.enabled", true)
	check("swing spark and shadow: and on again hides the Pip (Spark off) and the shadow (Text shadow off)", s.pipRaw.alpha == 0 and s.shadowRaw.alpha == 0)
	check("swing spark and shadow: only alpha is set, never visibility", s.pipRaw.calls.Hide == 1 and s.pipRaw.calls.Show == 2 and s.shadowRaw.calls.SetShown == nil and s.shadowRaw.calls.Hide == nil)
	clean(W, "swing spark")
end

-- 75g. The fill is applied with all three border switches off, and a timer is left alone when it is forbidden.
do
	local W = FH.world({ saved = { options = { ["swing.main"] = false, ["swing.off"] = false, ["swing.ranged"] = false } } })
	local all = true
	for _, name in ipairs(FH.SWING) do
		all = all and FH.fill(W, W.fills.swing[name].bar) == "colour " .. FH.hex(FH.SWING_HEX[name])
	end
	check("swing fill: with all three border switches off the fill is applied", all)
	check("swing fill: and the borders are left as the game has them", W.fills.swing.SwingTimerMainHandFrame.timer ~= nil and W.state(W.fills.swing.SwingTimerMainHandFrame.bar) == "." and FH.plain(W), FH.why(W))
	W.change("swing.main", true)
	W.change("swing.main", false)
	check("swing fill: border switches changed later leave the fill alone", FH.n(W, W.fills.swing.SwingTimerMainHandFrame.bar, "SetColorFill") == 1)

	local F2 = FH.world({ forbidden = { SwingTimerOffHandFrame = true, ["SwingTimerRangedFrame.StatusBar"] = true } })
	check("swing fill: a forbidden timer, and a timer whose bar is forbidden, are not touched or read", #F2.violations == 0 and #F2.errors == 0, FH.why(F2))
	check("swing fill: the other timer is", FH.fill(F2, F2.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640"))
	-- A timer whose bar is withheld, or has no Pip or shadow, does not stop the others.
	local V = FH.world(nil, function(X)
		X.fills.swing.SwingTimerOffHandFrame.barRaw.Pip = SECRET
		X.fills.swing.SwingTimerRangedFrame.barRaw.TypeLabelShadow = nil
		X.fills.swing.SwingTimerRangedFrame.barRaw.Pip = nil
		X.fills.swing.SwingTimerMainHandFrame.inner.StatusBar = SECRET
	end)
	check("swing fill: a withheld bar field, a withheld Pip and a bar with no Pip or shadow are skipped without an error",
		FH.fill(V, V.fills.swing.SwingTimerOffHandFrame.bar) == "colour " .. FH.hex("ff5c9fd6") and FH.fill(V, V.fills.swing.SwingTimerRangedFrame.bar) == "colour " .. FH.hex("ff73b85c")
		and FH.changes(V, V.fills.swing.SwingTimerMainHandFrame.bar) == 0 and #V.errors == 0 and #V.violations == 0 and not has(V.status(), "failed"), FH.why(V) .. V.status())
end

-- 75h. One bad timer is skipped and counted once.
do
	local W = FH.world(nil, function(X)
		X.fills.swing.SwingTimerOffHandFrame.inner.indexError = true
	end)
	for _ = 1, 3 do
		W.change("swing.spark", false)
		W.change("swing.spark", true)
	end
	check("swing fill: a timer that raises is counted once however often it is tried", has(W.line("Swing timers"), "2 styled, 1 failed."), W.line("Swing timers"))
	check("swing fill: the other timers are done", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.fill(W, W.fills.swing.SwingTimerRangedFrame.bar) == "colour " .. FH.hex("ff73b85c"))
	check("swing fill: and the module goes on", not W.ns.IsStopped("swing") and #W.out == 0)
	-- A bar that raises on a field is the same.
	local X = FH.world(nil, function(Y)
		Y.fills.swing.SwingTimerRangedFrame.barRaw.indexError = true
	end)
	check("swing fill: a bar that raises is counted once and the others are done", has(X.line("Swing timers"), "2 styled, 1 failed.") and FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640"),
		X.line("Swing timers"))
end

-- 75i. The page switch: off at login nothing is touched, on later the fill is made, off again it goes.
do
	local W = FH.world({ saved = { options = { ["swing.enabled"] = false } } })
	local touched = false
	for _, name in ipairs(FH.SWING) do
		local s = W.fills.swing[name]
		touched = touched or next(s.barRaw.byAddon) ~= nil or next(s.fillRaw.calls) ~= nil or next(s.pipRaw.calls) ~= nil or next(s.shadowRaw.calls) ~= nil
	end
	check("swing page: off at login, no bar, fill, Pip or shadow is called", not touched and #W.diff("swing") == 0, table.concat(W.diff("swing"), "; "))
	check("swing page: and the status says off", has(W.status(), "Swing timers: off") and FH.plain(W), W.status())
	W.change("swing.enabled", true)
	local on = true
	for _, name in ipairs(FH.SWING) do
		on = on and FH.fill(W, W.fills.swing[name].bar) == "colour " .. FH.hex(FH.SWING_HEX[name]) and FH.n(W, W.fills.swing[name].bar, "SetColorFill") == 1
	end
	check("swing page: on later makes the fill, once", on and has(W.status(), "Swing timers: on, 3 styled"), W.status())
	W.change("swing.enabled", false)
	check("swing page: off again gives the game's fill back", #W.diff("swing") == 0 and FH.n(W, W.fills.swing.SwingTimerMainHandFrame.bar, "SetStatusBarTexture") == 1, table.concat(W.diff("swing"), "; "))
	W.change("swing.enabled", true)
	check("swing page: and on again puts the fill back, with the same textures", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.n(W, W.fills.swing.SwingTimerMainHandFrame.bar, "SetColorFill") == 2)
	clean(W, "swing page")
end

-- 75j. Combat: the fill is a texture call, which is allowed.
do
	local W = FH.world({ combat = true })
	local all = true
	for _, name in ipairs(FH.SWING) do
		all = all and FH.fill(W, W.fills.swing[name].bar) == "colour " .. FH.hex(FH.SWING_HEX[name])
	end
	check("swing fill: a login in combat makes the fill", all and FH.plain(W), FH.why(W))
	local X = FH.world(nil, function(Y)
		for _, name in ipairs(FH.SWING) do
			Y.fills.swing[name].inner.protected = true
			Y.fills.swing[name].barRaw.protected = true
		end
	end)
	X.combat = true
	X.change("swing.mainColour", "ff336699")
	X.change("swing.spark", false)
	check("swing fill: on a protected timer in combat a changed colour and the Spark setting still apply", FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ff336699")
		and X.fills.swing.SwingTimerMainHandFrame.pipRaw.alpha == 0 and #X.violations == 0, FH.why(X))
	X.change("swing.flat", false)
	check("swing fill: and the restore", FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "atlas ui-swingtimerbar-filling-mainhand" and #X.violations == 0, FH.why(X))
end

-- 76. Personal resource display: the fill is white and solid, the game's tint shows through, and a custom colour is followed.
-- Cast bar fills are off in these worlds unless a check says otherwise, so that the one frame that follows colours is the resource display's.
FH.NOCAST = { ["castbars.flat"] = false }
function FH.res(extra, opts, before)
	local options = { ["castbars.flat"] = false }
	for k, v in pairs(extra or {}) do
		options[k] = v
	end
	opts = opts or {}
	opts.saved = { options = options }
	return FH.world(opts, before)
end
function FH.bars(W)
	return W.prd.health[1], W.prd.power[1], W.prd.alt[1]
end
FH.POWER_HEX = "ff3d7dd9"
FH.HEALTH_HEX = "ff2eb84d"
FH.MANA = "0.100,0.250,1.000"
FH.RAGE = "1.000,0.000,0.000"
FH.ENERGY = "1.000,1.000,0.000"

do
	local W = FH.res()
	local health, power, alt = FH.bars(W)
	check("resource fill: the health and power bars are white and solid", FH.fill(W, health) == "colour 1.000,1.000,1.000" and FH.fill(W, power) == "colour 1.000,1.000,1.000"
		and W.rawOf[health].fillRaw.color[4] == 1 and W.rawOf[power].fillRaw.color[4] == 1)
	check("resource fill: with one SetColorFill call each", FH.n(W, health, "SetColorFill") == 1 and FH.n(W, power, "SetColorFill") == 1)
	check("resource fill: the alternate bar keeps the game's fill until the display has been set up", FH.fill(W, alt) == "atlas " .. FH.BAR_ATLAS and FH.changes(W, alt) == 0)
	check("resource fill: no tint is given while both custom switches are off", FH.n(W, health, "SetStatusBarColor") == 0 and FH.n(W, power, "SetStatusBarColor") == 0
		and FH.n(W, alt, "SetStatusBarColor") == 0)
	check("resource fill: the tint stays the game's", FH.tint(W, power) == "0.000,0.000,1.000" and FH.tint(W, health) == "1.000,1.000,1.000")
	check("resource fill: nothing follows the colours", not FH.polling(W))
	check("resource fill: the region of each bar is the same object throughout", W.rawOf[power].fill == W.prd.power[2].regions[2] and W.prd.power[1]:GetStatusBarTexture() == W.prd.power[2].regions[2])
	check("resource fill: no value of a bar is read, no field is written, nothing is hooked that was not hooked before", FH.plain(W), FH.why(W))
	-- The game recolours the power bar; with nothing custom the addon leaves it.
	W.fills.setPower("RAGE")
	W.frame(5)
	check("resource fill: a colour the game sets is left as the game set it", FH.tint(W, power) == FH.RAGE and FH.n(W, power, "SetStatusBarColor") == 0 and not FH.polling(W))
	W.fills.showClassColour(true)
	W.frame(2)
	check("resource fill: so is the health colour of Show Class Colour", FH.tint(W, health) == FH.WARRIOR and FH.n(W, health, "SetStatusBarColor") == 0)
	local base = newWorld()
	base.login()
	check("resource fill: no hook is added to the game", W.hooks == base.hooks, W.hooks .. " " .. base.hooks)
	-- Flat fill off.
	W.change("resource.flat", false)
	check("resource fill: Flat fill off gives each flat bar one SetStatusBarTexture with the game's atlas",
		FH.n(W, health, "SetStatusBarTexture") == 1 and FH.n(W, power, "SetStatusBarTexture") == 1 and FH.fill(W, health) == "atlas " .. FH.BAR_ATLAS and FH.fill(W, power) == "atlas " .. FH.BAR_ATLAS
		and W.rawOf[power].addonLog[#W.rawOf[power].addonLog][2] == FH.BAR_ATLAS)
	check("resource fill: and makes no colour call", FH.n(W, health, "SetStatusBarColor") == 0 and FH.n(W, power, "SetStatusBarColor") == 0 and FH.n(W, alt, "SetStatusBarTexture") == 0)
	check("resource fill: the colours are the game's", FH.tint(W, power) == FH.RAGE and FH.tint(W, health) == FH.WARRIOR)
	W.change("resource.flat", true)
	check("resource fill: Flat fill on again is solid white again, with the same region", FH.fill(W, power) == "colour 1.000,1.000,1.000" and FH.n(W, power, "SetColorFill") == 2
		and W.rawOf[power].fill == W.prd.power[2].regions[2])
	clean(W, "resource fill")
end

-- 76b. A custom power colour is followed, and the game's colour is given back.
do
	local W = FH.res({ ["resource.powerOwn"] = true })
	local health, power = FH.bars(W)
	check("resource colour: Custom power colour sets the colour at once", FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.n(W, power, "SetStatusBarColor") == 1)
	check("resource colour: and leaves the health bar's", FH.tint(W, health) == "1.000,1.000,1.000" and FH.n(W, health, "SetStatusBarColor") == 0)
	check("resource colour: something follows it", FH.polling(W))
	W.frame(5)
	check("resource colour: frames in which the game set nothing make no call", FH.n(W, power, "SetStatusBarColor") == 1)
	W.fills.setPower("RAGE")
	check("resource colour: the game's change shows until the next frame", FH.tint(W, power) == FH.RAGE)
	W.frame(1)
	check("resource colour: and the next frame has the custom colour back with one call", FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.n(W, power, "SetStatusBarColor") == 2)
	W.frame(8)
	check("resource colour: and none on the frames after", FH.n(W, power, "SetStatusBarColor") == 2)
	W.fills.setPower("ENERGY")
	W.frame(1)
	W.frame(3)
	W.change("resource.powerOwn", false)
	check("resource colour: off after the game changed colour twice gives the last colour the game set", FH.tint(W, power) == FH.ENERGY and FH.n(W, power, "SetStatusBarColor") == 4, FH.tint(W, power))
	check("resource colour: and nothing follows any more", not FH.polling(W))
	W.fills.setPower("RAGE")
	W.frame(3)
	check("resource colour: the game's next colour is left alone", FH.tint(W, power) == FH.RAGE and FH.n(W, power, "SetStatusBarColor") == 4)
	W.change("resource.powerOwn", true)
	check("resource colour: on again sets the custom colour", FH.tint(W, power) == FH.hex(FH.POWER_HEX))
	W.change("resource.powerColour", "ff102030")
	check("resource colour: a changed colour is set at once", FH.tint(W, power) == FH.hex("ff102030"))
	W.frame(3)
	check("resource colour: and kept", FH.tint(W, power) == FH.hex("ff102030"))
	W.change("resource.powerOwn", false)
	check("resource colour: and the game's colour comes back, not the first custom colour", FH.tint(W, power) == FH.RAGE)
	clean(W, "resource colour")
end

do
	-- The stored colour is the game's, never the custom colour: off at once gives the colour it had.
	local W = FH.res({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true })
	local health, power = FH.bars(W)
	W.frame(10)
	check("resource colour: both custom colours are on at once", FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.tint(W, health) == FH.hex(FH.HEALTH_HEX))
	W.change("resource.powerOwn", false)
	check("resource colour: off at once gives the colour the game had set before", FH.tint(W, power) == "0.000,0.000,1.000" and FH.tint(W, health) == FH.hex(FH.HEALTH_HEX))
	check("resource colour: the other bar is still followed", FH.polling(W))
	W.fills.showClassColour(true)
	W.frame(1)
	check("resource colour: Show Class Colour on a bar with a custom health colour is overruled on the next frame", FH.tint(W, health) == FH.hex(FH.HEALTH_HEX))
	W.change("resource.healthColour", "ff112233")
	W.change("resource.healthOwn", false)
	check("resource colour: and the class colour is what the game last set", FH.tint(W, health) == FH.WARRIOR)
	check("resource colour: nothing is followed", not FH.polling(W))
end

do
	-- Flat fill off works with a custom colour: the colour does not depend on the texture.
	local W = FH.res({ ["resource.flat"] = false, ["resource.powerOwn"] = true })
	local _, power = FH.bars(W)
	check("resource colour: with Flat fill off the custom colour is set on the game's art", FH.fill(W, power) == "atlas " .. FH.BAR_ATLAS and FH.tint(W, power) == FH.hex(FH.POWER_HEX)
		and FH.n(W, power, "SetColorFill") == 0 and FH.n(W, power, "SetStatusBarTexture") == 0)
	W.change("resource.flat", true)
	check("resource colour: turning Flat fill on changes the texture and not the colour", FH.fill(W, power) == "colour 1.000,1.000,1.000" and FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.n(W, power, "SetStatusBarColor") == 1)
end

-- 76c. Withheld colours.
do
	for _, case in ipairs({ { "withheld", "secret" }, { "withheld in the first number", "secretFirst" }, { "a string", "string" }, { "an error", "error" }, { "nothing", "nothing" } }) do
		local W = FH.res({ ["resource.powerOwn"] = true }, nil, function(X)
			X.prd.power[2].fault.tint = case[2]
		end)
		local _, power = FH.bars(W)
		W.frame(3)
		check("resource colour: GetStatusBarColor gives " .. case[1] .. ", the custom colour is still applied", FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.n(W, power, "SetStatusBarColor") >= 1)
		check("resource colour: GetStatusBarColor gives " .. case[1] .. ", nothing is compared or stored", FH.plain(W) and not has(W.status(), "failed"), FH.why(W) .. W.status())
		W.change("resource.powerOwn", false)
		check("resource colour: GetStatusBarColor gives " .. case[1] .. ", off waits for the game's next colour instead of guessing", FH.tint(W, power) == FH.hex(FH.POWER_HEX)
			and FH.plain(W) and not has(W.status(), "failed"), FH.why(W) .. W.status())
		W.prd.power[2].fault.tint = nil
		W.fills.setPower("RAGE")
		check("resource colour: GetStatusBarColor gives " .. case[1] .. ", and the game's next colour shows", FH.tint(W, power) == FH.RAGE)
	end
	-- A colour that is withheld part of the time: the stored colour is not overwritten.
	local W = FH.res({ ["resource.powerOwn"] = true })
	local _, power = FH.bars(W)
	W.fills.setPower("RAGE")
	W.frame(1)
	W.prd.power[2].fault.tint = "secret"
	W.fills.setPower("ENERGY")
	W.frame(3)
	W.prd.power[2].fault.tint = nil
	W.change("resource.powerOwn", false)
	check("resource colour: a colour withheld for some frames does not overwrite the colour stored before", FH.tint(W, power) == FH.RAGE, FH.tint(W, power))
end

-- 76d. The alternate power bar waits for the display to be set up, and is flat from the hook the addon already has.
do
	local W = FH.res()
	local _, _, alt = FH.bars(W)
	W.layoutResource()
	W.change("resource.join", false)
	W.change("resource.join", true)
	check("resource alternate bar: before the display is set up it is not touched, by a Refresh or by the game's layout", FH.changes(W, alt) == 0 and FH.fill(W, alt) == "atlas " .. FH.BAR_ATLAS)
	W.prdInner.hasBeenSetup = false
	W.layoutResource()
	W.change("resource.join", false)
	check("resource alternate bar: hasBeenSetup false is not set up", FH.changes(W, alt) == 0)
	for _, value in ipairs({ "yes", 1, SECRET }) do
		W.prdInner.hasBeenSetup = value
		W.layoutResource()
		W.change("resource.join", true)
		W.change("resource.join", false)
	end
	check("resource alternate bar: and neither is anything but the boolean true", FH.changes(W, alt) == 0 and #W.violations == 0 and #W.errors == 0, FH.why(W))
	W.prdInner.hasBeenSetup = nil
	W.fills.setup()
	check("resource alternate bar: the game's Setup reads its atlas before the addon changes the bar", W.prd.alt[2].barTextureAtlas == FH.BAR_ATLAS, tostring(W.prd.alt[2].barTextureAtlas))
	check("resource alternate bar: and the pass after the game's script makes it flat", FH.fill(W, alt) == "colour 1.000,1.000,1.000" and FH.n(W, alt, "SetColorFill") == 1)
	W.layoutResource()
	W.layoutResource()
	check("resource alternate bar: the game's layout calls after that make no further call", FH.n(W, alt, "SetColorFill") == 1)
	check("resource alternate bar: the colour the game gave it is its own", FH.tint(W, alt) == FH.MANA and FH.n(W, alt, "SetStatusBarColor") == 0)
	W.change("resource.flat", false)
	check("resource alternate bar: Flat fill off puts the game's atlas back on it too", FH.fill(W, alt) == "atlas " .. FH.BAR_ATLAS and FH.n(W, alt, "SetStatusBarTexture") == 1)
	W.layoutResource()
	check("resource alternate bar: and the pass leaves it", FH.fill(W, alt) == "atlas " .. FH.BAR_ATLAS and FH.n(W, alt, "SetColorFill") == 1)
	clean(W, "resource alternate bar")

	-- A display that was set up before the addon started.
	local X = FH.res(nil, nil, function(Y)
		Y.fills.setup()
	end)
	check("resource alternate bar: set up before login, the first Refresh makes it flat", FH.fill(X, X.prd.alt[1]) == "colour 1.000,1.000,1.000" and X.prd.alt[2].barTextureAtlas == FH.BAR_ATLAS)
	-- The module off, or stopped: the hook leaves it.
	local Z = FH.res({ ["resource.enabled"] = false })
	Z.fills.setup()
	check("resource alternate bar: with the page off the game's Setup finds it as it was and the hook does nothing", Z.prd.alt[2].barTextureAtlas == FH.BAR_ATLAS and FH.changes(Z, Z.prd.alt[1]) == 0 and #Z.violations == 0)
	Z.change("resource.enabled", true)
	check("resource alternate bar: and on later it is flat", FH.fill(Z, Z.prd.alt[1]) == "colour 1.000,1.000,1.000")
end

-- 76e. The page off, the module stopped, a forbidden display.
do
	local function check_back(label, undo)
		local looks = {}
		local W = FH.res({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true }, nil, function(X)
			X.fills.setup()
			for key, pair in pairs(X.prd) do
				looks[key] = FH.fill(X, pair[1]) .. " " .. FH.tint(X, pair[1])
			end
		end)
		W.fills.setPower("RAGE")
		W.frame(2)
		W.fills.showClassColour(true)
		W.frame(2)
		local gameRage = FH.RAGE
		undo(W)
		W.frame(2)
		local health, power, alt = FH.bars(W)
		check("resource restore: " .. label .. " gives the texture back on all three bars", FH.fill(W, health) == "atlas " .. FH.BAR_ATLAS and FH.fill(W, power) == "atlas " .. FH.BAR_ATLAS
			and FH.fill(W, alt) == "atlas " .. FH.BAR_ATLAS)
		check("resource restore: " .. label .. " gives back the colours the game last set", FH.tint(W, power) == gameRage and FH.tint(W, health) == FH.WARRIOR)
		check("resource restore: " .. label .. " stops what followed the colours", not FH.polling(W))
		check("resource restore: " .. label .. " leaves the alternate bar as the game had it", FH.tint(W, alt) == FH.MANA and FH.n(W, alt, "SetStatusBarColor") == 0)
		return W
	end
	check_back("the page off", function(W) W.change("resource.enabled", false) end)
	local W = check_back("a module stopped by an error", function(X) X.ns.Try("resource", function() error("probe", 0) end) end)
	check("resource restore: a stopped module is reported, and the other modules run", has(W.status(), "Personal resource display: stopped. probe") and has(W.status(), "Swing timers: on, 3 styled"), W.status())
	local X = check_back("both custom switches and Flat fill off", function(Y)
		Y.change("resource.powerOwn", false)
		Y.change("resource.healthOwn", false)
		Y.change("resource.flat", false)
	end)
	-- Off at login: nothing is touched; on later; off again.
	local O = FH.res({ ["resource.enabled"] = false, ["resource.powerOwn"] = true })
	local touched = false
	for _, pair in pairs(O.prd) do
		touched = touched or next(O.rawOf[pair[1]].byAddon) ~= nil
	end
	check("resource page: off at login, no bar is called", not touched and not FH.polling(O) and FH.fill(O, O.prd.power[1]) == "atlas " .. FH.BAR_ATLAS)
	O.change("resource.enabled", true)
	check("resource page: on later makes the fill and sets the custom colour", FH.fill(O, O.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.tint(O, O.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.polling(O))
	O.change("resource.enabled", false)
	check("resource page: off again gives it all back", FH.fill(O, O.prd.power[1]) == "atlas " .. FH.BAR_ATLAS and FH.tint(O, O.prd.power[1]) == "0.000,0.000,1.000" and not FH.polling(O))
	O.change("resource.enabled", true)
	check("resource page: and on again", FH.fill(O, O.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.tint(O, O.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.polling(O))
	clean(O, "resource page")

	-- A display the addon may not touch.
	local F2 = FH.res({ ["resource.powerOwn"] = true }, { forbidden = { PersonalResourceDisplayFrame = true } })
	F2.frame(3)
	check("resource forbidden: a forbidden display is not touched or read", #F2.violations == 0 and #F2.errors == 0 and not FH.polling(F2), FH.why(F2))
	local F3 = FH.res({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true }, { forbidden = { ["PRD.power"] = true } })
	F3.frame(3)
	check("resource forbidden: a forbidden power bar is skipped, the health bar is done", FH.fill(F3, F3.prd.health[1]) == "colour 1.000,1.000,1.000" and FH.tint(F3, F3.prd.health[1]) == FH.hex(FH.HEALTH_HEX)
		and #F3.violations == 0, FH.why(F3))
	-- A bar that becomes forbidden while its colour is followed is not read again.
	local F4 = FH.res({ ["resource.powerOwn"] = true })
	F4.frame(2)
	F4.prd.power[2].forbidden = true
	F4.frame(3)
	check("resource forbidden: a bar that has become forbidden while its custom colour is followed is not read or called again", #F4.violations == 0, FH.why(F4))
end

-- 76f. Settings through their controls.
do
	local W = FH.res()
	local health, power = FH.bars(W)
	W.openPanel()
	check("resource controls: the two colours are greyed until their switches are on", not W.enabled("resource.healthColour") and not W.enabled("resource.powerColour")
		and W.enabled("resource.flat") and W.enabled("resource.healthOwn") and W.enabled("resource.powerOwn"))
	W.change("resource.powerOwn", true)
	check("resource controls: Custom power colour on makes its colour usable and not the health colour", W.enabled("resource.powerColour") and not W.enabled("resource.healthColour"))
	W.change("resource.healthOwn", true)
	check("resource controls: and Custom health colour on the other", W.enabled("resource.healthColour"))
	W.change("resource.healthColour", "ff445566")
	W.change("resource.powerColour", "ff778899")
	W.frame(2)
	check("resource controls: each colour shows on its bar", FH.tint(W, health) == FH.hex("ff445566") and FH.tint(W, power) == FH.hex("ff778899"))
	W.change("resource.flat", false)
	check("resource controls: Flat fill does not switch off a colour setting", W.enabled("resource.healthColour") and W.enabled("resource.powerColour") and FH.tint(W, power) == FH.hex("ff778899"))
	W.change("resource.flat", true)
	W.change("resource.enabled", false)
	check("resource controls: the page off greys the fill settings and not its own switch", not W.enabled("resource.flat") and not W.enabled("resource.healthColour") and not W.enabled("resource.powerOwn") and W.enabled("resource.enabled"))
	W.change("resource.enabled", true)
	check("resource controls: and on again", W.enabled("resource.flat") and W.enabled("resource.healthColour") and W.enabled("resource.powerColour") and FH.tint(W, power) == FH.hex("ff778899"))
	W.change("resource.healthOwn", false)
	W.change("resource.healthOwn", true)
	check("resource controls: a switch off and on gives the same", FH.tint(W, health) == FH.hex("ff445566"))
	clean(W, "resource controls")
end

-- 76g. Combat, a client without a method, a game that refuses.
do
	local W = FH.res({ ["resource.powerOwn"] = true }, { combat = true })
	local _, power = FH.bars(W)
	W.fills.setPower("RAGE")
	W.frame(2)
	check("resource combat: the fill and the colour are made and followed in combat", FH.fill(W, power) == "colour 1.000,1.000,1.000" and FH.tint(W, power) == FH.hex(FH.POWER_HEX) and #W.violations == 0, FH.why(W))
	W.change("resource.powerOwn", false)
	W.change("resource.flat", false)
	check("resource combat: and given back in combat", FH.fill(W, power) == "atlas " .. FH.BAR_ATLAS and FH.tint(W, power) == FH.RAGE and #W.violations == 0, FH.why(W))

	local function without(method, check_it, extra)
		local X = FH.res(extra or { ["resource.powerOwn"] = true }, { fills = { without = { method } } })
		X.frame(3)
		check_it(X)
		check("resource client without " .. method .. ": nothing is raised or printed", #X.violations == 0 and #X.errors == 0 and not has(X.status(), "failed") and not has(X.status(), "stopped"),
			FH.why(X) .. X.status())
	end
	without("GetStatusBarTexture", function(X)
		check("resource client without GetStatusBarTexture: the bars are left alone", FH.n(X, X.prd.power[1], "SetColorFill") == 0 and FH.n(X, X.prd.power[1], "SetStatusBarTexture") == 0 and FH.fill(X, X.prd.power[1]) == "atlas " .. FH.BAR_ATLAS)
	end)
	without("GetAtlas", function(X)
		check("resource client without GetAtlas: the fill is left and /flatui status says it could not be read", FH.fill(X, X.prd.power[1]) == "atlas " .. FH.BAR_ATLAS
			and has(X.status(), "Personal resource display: the default fill of a bar could not be read and is still shown."))
	end)
	without("SetColorFill", function(X)
		check("resource client without SetColorFill: the fill is left and the colour is applied", FH.fill(X, X.prd.power[1]) == "atlas " .. FH.BAR_ATLAS and FH.tint(X, X.prd.power[1]) == FH.hex(FH.POWER_HEX))
		check("resource client without SetColorFill: /flatui status says the game refused a flat fill", has(X.status(), "Personal resource display: the game refused a flat fill on a bar, which keeps its default fill."))
	end)
	without("SetStatusBarColor", function(X)
		check("resource client without SetStatusBarColor: nothing follows and the fill is flat", FH.tint(X, X.prd.power[1]) == "0.000,0.000,1.000" and not FH.polling(X) and FH.fill(X, X.prd.power[1]) == "colour 1.000,1.000,1.000")
	end)
	without("GetStatusBarColor", function(X)
		check("resource client without GetStatusBarColor: the custom colour is applied", FH.tint(X, X.prd.power[1]) == FH.hex(FH.POWER_HEX))
	end)
	without("SetStatusBarTexture", function(X)
		X.change("resource.flat", false)
		check("resource client without SetStatusBarTexture: the fill stays flat and /flatui status says the game refused", FH.fill(X, X.prd.power[1]) == "colour 1.000,1.000,1.000"
			and has(X.status(), "Personal resource display: the game refused to put back the default fill of a bar."))
	end)

	-- The game refuses to put the texture back: the record is kept, and the next Refresh tries again.
	local R = FH.res()
	local _, rp = FH.bars(R)
	R.prd.power[2].refuseTexture = true
	R.change("resource.flat", false)
	check("resource refusal: when SetStatusBarTexture returns false the fill is still flat and /flatui status says so once",
		FH.fill(R, rp) == "colour 1.000,1.000,1.000" and count(R.status(), "Personal resource display: the game refused to put back the default fill of a bar.") == 1, R.status())
	R.prd.power[2].refuseTexture = nil
	R.change("resource.join", false)
	check("resource refusal: the record is kept, so the next Refresh puts the fill back", FH.fill(R, rp) == "atlas " .. FH.BAR_ATLAS and FH.n(R, rp, "SetStatusBarTexture") == 2)
	-- A call the game answers with an error or a withheld answer.
	local E = FH.res()
	local _, ep = FH.bars(E)
	E.prd.power[2].fault.setTexture = "error"
	E.change("resource.flat", false)
	check("resource refusal: SetStatusBarTexture raising is the same as a refusal", FH.fill(E, ep) == "colour 1.000,1.000,1.000" and has(E.status(), "refused to put back") and not has(E.status(), "failed"))
	E.prd.power[2].fault.setTexture = nil
	E.prd.power[2].fault.setTextureResult = "secret"
	E.change("resource.join", false)
	check("resource refusal: a withheld answer counts as done", FH.fill(E, ep) == "atlas " .. FH.BAR_ATLAS)
	-- The fill that was made flat is drawn again by the game: the next Refresh makes it flat again.
	local D = FH.res()
	local _, dp = FH.bars(D)
	D.prd.power[2].fillRaw.atlas, D.prd.power[2].fillRaw.color = "drawn-again", nil
	D.change("resource.join", false)
	check("resource fill: an atlas found on a flat region means the game drew it again, and the next Refresh makes it flat again", FH.fill(D, dp) == "colour 1.000,1.000,1.000" and FH.n(D, dp, "SetColorFill") == 2)
	D.change("resource.flat", false)
	check("resource fill: the atlas that is put back is the one the game drew last", FH.fill(D, dp) == "atlas drawn-again")
	local S = FH.res()
	local _, sp = FH.bars(S)
	S.prd.power[2].fillRaw.atlas, S.prd.power[2].fillRaw.color = "drawn-again", nil
	S.prd.power[2].fillRaw.fault.atlas = "secret"
	S.change("resource.join", false)
	check("resource fill: a withheld atlas on a flat region is taken for the same", FH.fill(S, sp) == "colour 1.000,1.000,1.000" and FH.n(S, sp, "SetColorFill") == 2 and #S.errors == 0)
	-- A call that raises is counted once for the bar.
	local B3 = FH.res({ ["resource.powerOwn"] = true })
	B3.fills.setPower("RAGE")
	B3.prd.power[2].fault.setColor = "error"
	B3.frame(6)
	check("resource failure: a bar whose SetStatusBarColor raises is counted once however often it is followed", has(B3.line("Personal resource display"), "1 failed."), B3.line("Personal resource display"))
	check("resource failure: the other bars and modules go on", FH.fill(B3, B3.prd.health[1]) == "colour 1.000,1.000,1.000" and not B3.ns.IsStopped("resource"))
end

-- 77. Cast bars: a texture of the addon's lies over the fill the game draws, and is coloured by what the cast is doing.
-- Cast bars are hidden until a cast shows them (W.fills.castStart); a drawn frame (W.frame) is one run of the poll.
function FH.cast(extra, opts, before)
	opts = opts or {}
	if extra then
		opts.saved = { options = extra }
	end
	return FH.world(opts, before)
end
function FH.bar(W, name)
	return W.fills.cast[name].bar
end
-- The colour of the cover of a bar, as red, green and blue, or "-" when it is not shown.
function FH.shownColour(W, name)
	local cover = FH.cover(W, FH.bar(W, name))
	return cover and cover.shown and FH.rgb(cover.vertex) or "-"
end
FH.PLAYER = "PlayerCastingBarFrame"

do
	local W = FH.cast()
	check("cast fill: a bar that has not cast has no cover", FH.allCovers(W) == 0)
	check("cast fill: the poll runs while a bar wants a flat fill", FH.polling(W))
	local frames, textures = #W.addonFrames, #W.addonTextures
	local one, own, anchored, layered, white, coloured, shown = true, true, true, true, true, true, true
	for _, name in ipairs(FH.CASTS) do
		W.fills.castStart(name, "cast")
	end
	W.frame(1)
	for _, name in ipairs(FH.CASTS) do
		local bar = FH.bar(W, name)
		local covers = FH.covers(W, bar)
		one = one and #covers == 1
		local t = covers[1]
		if t then
			local fill = W.rawOf[bar].fill
			own = own and W.ns.Own[t] == true
			anchored = anchored and #t.points == 2 and t.points[1][1] == "TOPLEFT" and t.points[1][3] == "TOPLEFT" and t.points[2][1] == "BOTTOMRIGHT" and t.points[2][3] == "BOTTOMRIGHT"
				and t.points[1][2] == fill and t.points[2][2] == fill and t.points[1][4] == 0 and t.points[1][5] == 0 and t.points[2][4] == 0 and t.points[2][5] == 0
			layered = layered and t.layer == "ARTWORK" and t.sublevel == 1
			white = white and t.color and t.color[1] == 1 and t.color[2] == 1 and t.color[3] == 1 and t.color[4] == 1
			coloured = coloured and FH.rgb(t.vertex) == FH.hex(FH.CAST_HEX.cast) and t.vertex[4] == 1
			shown = shown and t.shown == true
		end
	end
	check("cast fill: starting a cast on each bar makes one texture of the addon's on each bar", one)
	check("cast fill: it is in ns.Own", own)
	check("cast fill: it is anchored to the fill region by both corners, with no offset", anchored)
	check("cast fill: it is on the fill's layer, one sublevel up", layered)
	check("cast fill: it is a white texture", white)
	check("cast fill: it has the cast colour and is shown", coloured and shown)
	check("cast fill: nothing else is made, no frame and no second texture", #W.addonFrames == frames and #W.addonTextures == textures + 5, (#W.addonTextures - textures) .. " " .. (#W.addonFrames - frames))
	W.frame(5)
	check("cast fill: the textures are made once", #W.addonTextures == textures + 5)
	-- Nothing is called on what the game draws.
	local fillCalls, barCalls, fillSame = 0, 0, true
	for _, name in ipairs(FH.CASTS) do
		local raw = W.rawOf[FH.bar(W, name)]
		for _ in pairs(raw.fillRaw.calls) do
			fillCalls = fillCalls + 1
		end
		barCalls = barCalls + FH.changes(W, FH.bar(W, name))
		fillSame = fillSame and FH.fill(W, FH.bar(W, name)) == "atlas ui-castingbar-filling-standard" and FH.tint(W, FH.bar(W, name)) == "1.000,1.000,1.000" and raw.fillRaw.alpha == 1
	end
	check("cast fill: no call is made on the game's fill region", fillCalls == 0, fillCalls)
	check("cast fill: SetStatusBarTexture, SetStatusBarColor and SetColorFill are never called on a cast bar", barCalls == 0, barCalls)
	check("cast fill: the game's fill, tint and alpha are as the game set them", fillSame)
	check("cast fill: no field is written, no hook, nothing printed", FH.plain(W), FH.why(W))
	check("cast fill: the five bars are counted as styled", has(W.status(), "Cast bars: on, 5 styled") and not has(W.line("Cast bars"), "failed") and #W.partErrors == 0, W.line("Cast bars"))
	local base = newWorld()
	base.login()
	check("cast fill: no hook is added to the game", W.hooks == base.hooks, W.hooks .. " " .. base.hooks)
end

-- 77b. The layer of the cover is the layer of the fill, read when it is made.
do
	for _, case in ipairs({ { "OVERLAY", 3, "OVERLAY", 4 }, { "ARTWORK", 7, "ARTWORK", 7 }, { "BORDER", -2, "BORDER", -1 }, { "BACKGROUND", 0, "BACKGROUND", 1 } }) do
		local W = FH.cast(nil, nil, function(X)
			X.fills.cast[FH.PLAYER].inner.fillRaw.layer, X.fills.cast[FH.PLAYER].inner.fillRaw.sublevel = case[1], case[2]
		end)
		W.fills.castStart(FH.PLAYER, "cast")
		W.frame(1)
		local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
		check("cast fill: a fill on " .. case[1] .. " " .. case[2] .. " gets a cover on " .. case[3] .. " " .. case[4], cover and cover.layer == case[3] and cover.sublevel == case[4] and FH.plain(W),
			cover and (cover.layer .. " " .. cover.sublevel) or "no cover")
	end
	for _, case in ipairs({ { "withheld", "secret" }, { "withheld in the layer only", "secretFirst" }, { "an error", "error" }, { "a string", "string" } }) do
		local W = FH.cast(nil, nil, function(X)
			X.fills.cast[FH.PLAYER].inner.fillRaw.fault.drawLayer = case[2]
		end)
		W.fills.castStart(FH.PLAYER, "cast")
		W.frame(1)
		local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
		check("cast fill: GetDrawLayer gives " .. case[1] .. ", the cover is on ARTWORK 1", cover and cover.layer == "ARTWORK" and cover.sublevel == 1 and FH.plain(W), FH.why(W))
	end
	local W = FH.cast(nil, { noDrawLayer = true })
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
	check("cast fill: a client without GetDrawLayer gets the cover on ARTWORK 1", cover and cover.layer == "ARTWORK" and cover.sublevel == 1 and FH.plain(W), FH.why(W))
end

-- 77c. The atlases and the colours.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local cases = {
		{ "ui-castingbar-filling-standard", "cast" }, { "ui-castingbar-full-standard", "cast" }, { "ui-castingbar-filling-channel", "channel" }, { "ui-castingbar-full-channel", "channel" },
		{ "ui-castingbar-uninterruptable", "shield" }, { "ui-castingbar-interrupted", "interrupted" }, { "ui-castingbar-filling-applyingcrafting", "craft" },
		{ "ui-castingbar-full-applyingcrafting", "craft" }, { "ui-castingbar-a-new-art", "cast" }, { "UI-CASTINGBAR-INTERRUPTED", "interrupted" }, { "Ui-CastingBar-Filling-Channel", "channel" },
	}
	for _, case in ipairs(cases) do
		W.blizzard(function() P:SetStatusBarTexture(case[1]) end)
		W.frame(1)
		check("cast fill: the atlas " .. case[1] .. " gives the " .. case[2] .. " colour on the next poll", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX[case[2]]), FH.shownColour(W, FH.PLAYER))
	end
	check("cast fill: the texture is called only when the colour changes", FH.cover(W, P).calls.SetVertexColor == 8, FH.cover(W, P).calls.SetVertexColor)
	check("cast fill: no violations", FH.plain(W), FH.why(W))
end

-- 77d. A cast, its end and the next cast keep the cover and change its colour.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local cover = FH.cover(W, P)
	check("cast fill: a cast shows the cover in the cast colour", cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and cover.calls.SetVertexColor == 1)
	W.frame(6)
	check("cast fill: frames in which nothing changes make no call", cover.calls.SetVertexColor == 1 and cover.calls.Show == 1 and cover.calls.Hide == 1)
	W.fills.castFinish(FH.PLAYER)
	W.frame(1)
	check("cast fill: a finished cast keeps the colour of its state, with no call", cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and cover.calls.SetVertexColor == 1)
	W.fills.castStart(FH.PLAYER, "channel")
	W.frame(1)
	check("cast fill: the next cast in a row changes only the colour", cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.channel) and cover.calls.SetVertexColor == 2 and cover.calls.Hide == 1 and cover.calls.Show == 1)
	W.fills.castInterrupt(FH.PLAYER)
	W.frame(1)
	check("cast fill: an interrupt gives the interrupted colour", cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.interrupted) and cover.calls.SetVertexColor == 3)
	W.fills.castStart(FH.PLAYER, "crafting")
	W.frame(1)
	check("cast fill: a crafting cast gives the crafting colour", FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.craft) and cover.calls.SetVertexColor == 4)
	W.fills.castStart(FH.PLAYER, "talents")
	W.frame(1)
	check("cast fill: applying talents uses the standard bar and the cast colour", FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and cover.calls.SetVertexColor == 5)
	W.fills.castInterruptible(FH.PLAYER, true)
	W.frame(1)
	check("cast fill: a cast that becomes uninterruptible gives the uninterruptible colour", FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.shield) and cover.calls.SetVertexColor == 6)
	W.fills.castInterruptible(FH.PLAYER, false)
	W.frame(1)
	check("cast fill: and back", FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and cover.calls.SetVertexColor == 7)
	check("cast fill: the cover was made once and shown once through all of it", #FH.covers(W, P) == 1 and cover.calls.Show == 1 and cover.calls.Hide == 1 and cover.calls.SetColorTexture == 1)
	clean(W, "cast sequence")
end

-- 77e. No cover for a fill that is hidden: empowered casts, no atlas, an empty atlas, a file.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "empowered")
	W.frame(1)
	check("cast fill: an empowered cast has the cover made and hidden", FH.cover(W, P) and FH.cover(W, P).shown == false and W.rawOf[P].reverseChanneling == true)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	check("cast fill: the next plain cast shows it", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	W.fills.castStart(FH.PLAYER, "empowered")
	W.frame(1)
	check("cast fill: an empowered cast hides it", FH.cover(W, P).shown == false and FH.cover(W, P).calls.Hide == 2)
	W.frame(4)
	check("cast fill: and it stays hidden without calls", FH.cover(W, P).calls.Hide == 2)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	W.blizzard(function() P:SetStatusBarTexture("") end)
	W.frame(1)
	check("cast fill: an empty atlas hides it", FH.shownColour(W, FH.PLAYER) == "-")
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	W.rawOf[P].fillRaw.atlas = ""
	W.frame(1)
	check("cast fill: an atlas that is the empty string hides it", FH.shownColour(W, FH.PLAYER) == "-")
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	W.blizzard(function() P:SetStatusBarTexture("Interface\\TargetingFrame\\UI-StatusBar") end)
	W.frame(1)
	check("cast fill: a file texture, as the game's classic style draws, hides it", FH.shownColour(W, FH.PLAYER) == "-" and W.rawOf[P].fillRaw.file ~= nil)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	check("cast fill: and the next plain cast shows it again", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	-- A fill drawn by a color texture has no atlas either.
	W.blizzard(function() P:SetColorFill(0.5, 0.5, 0.5, 1) end)
	W.frame(1)
	check("cast fill: a colour fill drawn by the game hides it", FH.shownColour(W, FH.PLAYER) == "-")
	clean(W, "cast hidden fill")
	-- reverseChanneling hides it whatever atlas the fill has.
	local R = FH.cast()
	R.fills.castStart(FH.PLAYER, "cast")
	R.frame(1)
	R.rawOf[FH.bar(R, FH.PLAYER)].reverseChanneling = true
	R.frame(1)
	check("cast fill: reverseChanneling true hides the cover although the fill has a plain atlas", FH.shownColour(R, FH.PLAYER) == "-" and R.rawOf[FH.bar(R, FH.PLAYER)].fillRaw.atlas == "ui-castingbar-filling-standard")
	R.rawOf[FH.bar(R, FH.PLAYER)].reverseChanneling = nil
	R.frame(1)
	check("cast fill: and nil shows it again", FH.shownColour(R, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	-- A withheld reverseChanneling does not hide it.
	local X = FH.cast()
	X.fills.castStart(FH.PLAYER, "cast")
	X.rawOf[FH.bar(X, FH.PLAYER)].reverseChanneling = SECRET
	X.frame(2)
	check("cast fill: a reverseChanneling that is withheld is not taken for true", FH.shownColour(X, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(X), FH.why(X))
end

-- 77f. The atlas is withheld: the state comes from the fields the game sets and from the spark and the shield.
do
	local function state(label, setup, wanted, after)
		local W = FH.cast()
		setup(W)
		W.frame(2)
		check("cast withheld: " .. label, FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX[wanted]) and FH.plain(W) and not has(W.status(), "failed"), FH.shownColour(W, FH.PLAYER) .. FH.why(W) .. W.status())
		if after then
			after(W)
		end
		return W
	end
	state("a cast is the cast colour", function(W) W.fills.castStart(FH.PLAYER, "cast", { secret = true }) end, "cast")
	state("a channel is the channel colour", function(W) W.fills.castStart(FH.PLAYER, "channel", { secret = true }) end, "channel", function(W)
		check("cast withheld: and no withheld value is passed to the texture", FH.cover(W, FH.bar(W, FH.PLAYER)).calls.SetVertexColorFromBoolean == nil)
	end)
	state("a cast that ended with the spark shown is interrupted", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true })
		W.frame(1)
		W.fills.castInterrupt(FH.PLAYER, true)
	end, "interrupted")
	state("a failed channel is interrupted too", function(W)
		W.fills.castStart(FH.PLAYER, "channel", { secret = true })
		W.frame(1)
		W.fills.castInterrupt(FH.PLAYER, true)
	end, "interrupted")
	state("a cast that finished, with the spark hidden, is the cast colour", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true })
		W.frame(1)
		W.fills.castFinish(FH.PLAYER, true)
	end, "cast")
	state("a shield that is plainly shown is the uninterruptible colour", function(W) W.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = true }) end, "shield")
	state("a shield that is plainly hidden is the cast colour", function(W) W.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = false }) end, "cast")
	state("a channel with the shield shown is the uninterruptible colour", function(W) W.fills.castStart(FH.PLAYER, "channel", { secret = true, notInterruptible = true }) end, "shield")
	state("a channel with the shield hidden is the channel colour", function(W) W.fills.castStart(FH.PLAYER, "channel", { secret = true }) end, "channel")
	state("a spark whose state is withheld is not taken for shown", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true })
		W.frame(1)
		W.fills.castFinish(FH.PLAYER, true)
		W.fills.cast[FH.PLAYER].sparkRaw.fault.shown = "secret"
	end, "cast")
	state("fields that are withheld are not compared", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true })
		W.rawOf[FH.bar(W, FH.PLAYER)].casting = SECRET
		W.rawOf[FH.bar(W, FH.PLAYER)].channeling = SECRET
	end, "cast")
	state("a bar without a spark or a shield is the cast colour", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true })
		W.rawOf[FH.bar(W, FH.PLAYER)].Spark = nil
		W.rawOf[FH.bar(W, FH.PLAYER)].BorderShield = nil
	end, "cast")
	state("a shield whose IsShown fails is the cast colour", function(W)
		W.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = true })
		W.fills.cast[FH.PLAYER].shieldRaw.fault.shown = "error"
	end, "cast")
	state("an atlas that fails to read is taken for withheld", function(W)
		W.fills.castStart(FH.PLAYER, "channel")
		W.rawOf[FH.bar(W, FH.PLAYER)].fillRaw.fault.atlas = "error"
	end, "channel")
end

-- 77g. The withheld shield is passed on untouched.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.secretTruth = true
	W.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = true, secretShield = true })
	W.frame(3)
	local cover = FH.cover(W, P)
	check("cast withheld: a shield that is withheld goes to SetVertexColorFromBoolean as it is", cover.fromBoolean and cover.fromBoolean.secret == true and cover.calls.SetVertexColorFromBoolean == 3
		and cover.calls.SetVertexColor == nil, tostring(cover.calls.SetVertexColorFromBoolean))
	check("cast withheld: with the uninterruptible colour and the cast colour as colour objects", cover.fromBoolean and FH.rgb({ cover.fromBoolean.yes.r, cover.fromBoolean.yes.g, cover.fromBoolean.yes.b }) == FH.hex(FH.CAST_HEX.shield)
		and FH.rgb({ cover.fromBoolean.no.r, cover.fromBoolean.no.g, cover.fromBoolean.no.b }) == FH.hex(FH.CAST_HEX.cast) and cover.fromBoolean.yes.a == 1)
	check("cast withheld: and the player sees the uninterruptible colour when the shield is shown", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.shield))
	W.secretTruth = false
	W.frame(1)
	check("cast withheld: and the cast colour when it is not", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	check("cast withheld: it is asked every frame and nothing compares it", cover.calls.SetVertexColorFromBoolean == 4 and FH.plain(W) and not has(W.status(), "failed"), FH.why(W))
	W.fills.castStart(FH.PLAYER, "channel", { secret = true, notInterruptible = true, secretShield = true })
	W.frame(1)
	check("cast withheld: for a channel the other colour is the channel colour", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.channel))
	W.change("castbars.shieldColour", "ff102030")
	W.change("castbars.channelColour", "ff405060")
	W.secretTruth = true
	W.frame(1)
	check("cast withheld: a changed colour is in the colour objects on the next frame", FH.shownColour(W, FH.PLAYER) == FH.hex("ff102030"))
	W.secretTruth = false
	W.frame(1)
	check("cast withheld: both of them", FH.shownColour(W, FH.PLAYER) == FH.hex("ff405060"))
	W.fills.castStart(FH.PLAYER, "cast", { secret = true })
	W.frame(1)
	check("cast withheld: a plain state after a withheld one is painted with SetVertexColor", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and cover.calls.SetVertexColor == 1)
	-- A client without CreateColor or SetVertexColorFromBoolean shows the cast colour.
	for _, case in ipairs({ { "CreateColor", { fills = { noCreateColor = true } } }, { "SetVertexColorFromBoolean", { noFromBoolean = true } } }) do
		local X = FH.cast(nil, case[2])
		X.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = true, secretShield = true })
		X.frame(3)
		check("cast withheld: a client without " .. case[1] .. " gets the cast colour", FH.shownColour(X, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(X) and not has(X.status(), "failed"), FH.why(X))
		X.fills.castStart(FH.PLAYER, "channel", { secret = true, notInterruptible = true, secretShield = true })
		X.frame(1)
		check("cast withheld: and a channel the channel colour", FH.shownColour(X, FH.PLAYER) == FH.hex(FH.CAST_HEX.channel))
	end
end

-- 77h. A bar that is hidden is not painted; a bar whose answer is withheld is.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local cover = FH.cover(W, P)
	W.fills.castHide(FH.PLAYER)
	W.frame(1)
	W.options()["castbars.castColour"] = "ff112233"
	W.frame(5)
	check("cast fill: a hidden bar gets no paint call", cover.calls.SetVertexColor == 1 and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast))
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	check("cast fill: it is painted when it shows again", cover.calls.SetVertexColor == 2 and FH.rgb(cover.vertex) == FH.hex("ff112233"))
	W.fills.castHide(FH.PLAYER)
	W.rawOf[P].fault.shown = "secret"
	W.frame(1)
	W.options()["castbars.castColour"] = "ff445566"
	W.frame(1)
	check("cast fill: a bar whose IsShown is withheld is painted", cover.calls.SetVertexColor == 3 and FH.rgb(cover.vertex) == FH.hex("ff445566") and FH.plain(W), FH.why(W))
	local X = FH.cast()
	X.rawOf[FH.bar(X, FH.PLAYER)].fault.shown = "secret"
	X.frame(2)
	check("cast fill: a bar never shown whose IsShown is withheld has its cover made", FH.cover(X, FH.bar(X, FH.PLAYER)) ~= nil and FH.plain(X), FH.why(X))
	local Y = FH.cast()
	Y.rawOf[FH.bar(Y, FH.PLAYER)].fault.shown = "error"
	Y.fills.castStart(FH.PLAYER, "cast")
	Y.frame(3)
	check("cast fill: a bar whose IsShown fails is skipped and stops neither the module nor the flat fill", not has(Y.line("Cast bars"), "failed") and not Y.ns.IsStopped("castbars") and not Y.ns.PartStopped("castbars", "flat fill")
		and FH.cover(Y, FH.bar(Y, "PetCastingBarFrame")) == nil and #Y.errors == 0, Y.line("Cast bars"))
end

-- 77i. A colour changed in the options is painted on the next poll with no Refresh.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	W.options()["castbars.castColour"] = "ff112233"
	W.frame(1)
	check("cast colours: a colour changed in the saved settings is painted on the next poll", FH.shownColour(W, FH.PLAYER) == FH.hex("ff112233"))
	local cover = FH.cover(W, P)
	for _, case in ipairs({ { "cast", "ff010203", "cast" }, { "channel", "ff0a0b0c", "channel" }, { "shield", "ff0d0e0f", "uninterruptable" }, { "interrupted", "ff101112", "interrupted" }, { "craft", "ff131415", "crafting" } }) do
		if case[3] == "uninterruptable" then
			W.fills.castStart(FH.PLAYER, "cast", { notInterruptible = true })
		elseif case[3] == "interrupted" then
			W.fills.castInterrupt(FH.PLAYER)
		else
			W.fills.castStart(FH.PLAYER, case[3])
		end
		W.change(FH.CAST_OPTION[case[1]], case[2])
		W.frame(1)
		check("cast colours: the " .. case[1] .. " colour setting changes the cover when that is the state", FH.shownColour(W, FH.PLAYER) == FH.hex(case[2]), FH.shownColour(W, FH.PLAYER))
	end
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	check("cast colours: and each setting is its own", FH.shownColour(W, FH.PLAYER) == FH.hex("ff010203"))
	clean(W, "cast colours")
end

-- 78. Cast bars: the covers go when the fill is switched off, the page is, or the module stops; nothing is made twice.
-- Starts a cast on every bar and draws a frame.
function FH.castAll(W)
	for _, name in ipairs(FH.CASTS) do
		W.fills.castStart(name, "cast")
	end
	W.frame(1)
end
-- How many covers are shown.
function FH.shownCovers(W)
	local n = 0
	for _, name in ipairs(FH.CASTS) do
		for _, t in ipairs(FH.covers(W, FH.bar(W, name))) do
			if t.shown then
				n = n + 1
			end
		end
	end
	return n
end
-- Calls made on the game's fill regions of the five bars.
function FH.fillCalls(W)
	local n = 0
	for _, name in ipairs(FH.CASTS) do
		for _ in pairs(W.rawOf[FH.bar(W, name)].fillRaw.calls) do
			n = n + 1
		end
	end
	return n
end

do
	local function hidden(label, undo)
		local W = FH.cast()
		FH.castAll(W)
		local textures = #W.addonTextures
		check("cast restore: " .. label .. ": five covers are shown before", FH.shownCovers(W) == 5)
		undo(W)
		W.frame(2)
		check("cast restore: " .. label .. " hides every cover", FH.shownCovers(W) == 0 and FH.allCovers(W) == 5)
		local quiet = true
		for _, name in ipairs(FH.CASTS) do
			local t = FH.cover(W, FH.bar(W, name))
			quiet = quiet and t.calls.SetVertexColor == 1 and t.calls.SetColorTexture == 1 and t.calls.Show == 1 and t.calls.Hide == 2 and t.calls.ClearAllPoints == nil
		end
		check("cast restore: " .. label .. " makes no other call on them", quiet)
		check("cast restore: " .. label .. " leaves what the game drew as it was", FH.fillCalls(W) == 0 and FH.fill(W, FH.bar(W, FH.PLAYER)) == "atlas ui-castingbar-filling-standard"
			and FH.tint(W, FH.bar(W, FH.PLAYER)) == "1.000,1.000,1.000")
		check("cast restore: " .. label .. " clears the poll when nothing else needs it", not FH.polling(W))
		W.fills.castStart(FH.PLAYER, "channel")
		W.frame(2)
		check("cast restore: " .. label .. ", a new cast then gets no paint and no new texture", FH.shownCovers(W) == 0 and #W.addonTextures == textures and FH.cover(W, FH.bar(W, FH.PLAYER)).calls.SetVertexColor == 1)
		return W
	end
	hidden("Flat fill off", function(W) W.change("castbars.flat", false) end)
	hidden("the page off", function(W) W.change("castbars.enabled", false) end)
	local W = hidden("a module stopped by an error", function(X) X.ns.Try("castbars", function() error("probe", 0) end) end)
	check("cast restore: a stopped module is reported and the others run", has(W.status(), "Cast bars: stopped. probe") and has(W.status(), "Swing timers: on, 3 styled") and has(W.status(), "Personal resource display: on, 3 styled"))
	check("cast restore: and the resource fill is still flat", FH.fill(W, W.prd.power[1]) == "colour 1.000,1.000,1.000")

	-- On again.
	local X = FH.cast()
	FH.castAll(X)
	local textures = #X.addonTextures
	X.change("castbars.flat", false)
	X.change("castbars.flat", true)
	X.frame(1)
	check("cast fill: Flat fill off and on again shows the covers again, nothing made twice", FH.shownCovers(X) == 5 and #X.addonTextures == textures)
	X.change("castbars.enabled", false)
	X.change("castbars.enabled", true)
	X.frame(1)
	check("cast fill: so does the page", FH.shownCovers(X) == 5 and #X.addonTextures == textures and FH.polling(X))
	-- A custom resource colour keeps the one frame that follows colours.
	local Y = FH.cast({ ["resource.powerOwn"] = true })
	FH.castAll(Y)
	Y.change("castbars.flat", false)
	check("cast fill: the poll stays while a custom resource colour needs it", FH.polling(Y))
	Y.change("resource.powerOwn", false)
	check("cast fill: and goes with it", not FH.polling(Y))
	Y.change("castbars.flat", true)
	check("cast fill: Flat fill on starts it again", FH.polling(Y))
end

-- 78b. The page switch.
do
	local W = FH.cast({ ["castbars.enabled"] = false })
	FH.castAll(W)
	W.frame(3)
	check("cast page: off at login, no cover is made, nothing polls, no bar is called", FH.allCovers(W) == 0 and not FH.polling(W) and FH.fillCalls(W) == 0 and #W.violations == 0)
	W.change("castbars.enabled", true)
	W.frame(1)
	check("cast page: on later, the bars that are casting get their covers on the next frame", FH.shownCovers(W) == 5 and FH.polling(W))
	W.change("castbars.enabled", false)
	check("cast page: off again hides them and stops the poll", FH.shownCovers(W) == 0 and not FH.polling(W))
	clean(W, "cast page")
end

-- 78c. A cover the game gives no anchor is hidden, noted once, and not tried again every frame.
do
	local W = FH.cast()
	W.refuse[FH.bar(W, FH.PLAYER)] = true
	local textures = #W.addonTextures
	FH.castAll(W)
	W.frame(6)
	local refused
	for _, t in ipairs(W.addonTextures) do
		if t.owner == FH.bar(W, FH.PLAYER) and t.layer == "ARTWORK" and t.sublevel == 1 then
			refused = t
		end
	end
	check("cast fill: a cover that took no anchor is hidden", refused and refused.shown == false and #refused.points == 0 and FH.shownCovers(W) == 4, tostring(FH.shownCovers(W)))
	check("cast fill: it is made once and not again", #W.addonTextures == textures + 5, #W.addonTextures - textures)
	check("cast fill: /flatui status says so once", count(W.status(), "Cast bars: the game refused a fill on one cast bar, which keeps its default fill.") == 1, W.status())
	check("cast fill: the other bars are done and nothing is counted as failed", FH.shownColour(W, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast) and not has(W.line("Cast bars"), "failed") and #W.errors == 0 and #W.partErrors == 0)
	-- A game that answers GetNumPoints with something unusable counts as anchored.
	for _, fault in ipairs({ "error", "secret", "string" }) do
		local X = FH.cast()
		X.numPointsFault = fault
		X.fills.castStart(FH.PLAYER, "cast")
		X.frame(2)
		check("cast fill: GetNumPoints gives " .. fault .. ", the cover is taken for anchored", FH.shownColour(X, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and not has(X.status(), "refused"), X.status())
	end
end

-- 78d. A bar with no fill region yet gets its cover on a later call.
do
	local W = FH.cast(nil, { fills = { smallBars = { PetCastingBarFrame = true } } })
	local pet = FH.bar(W, "PetCastingBarFrame")
	W.rawOf[pet].shown = true
	W.frame(4)
	check("cast fill: a bar shown before it has any fill is skipped without an error", FH.cover(W, pet) == nil and FH.plain(W) and not has(W.status(), "failed"), FH.why(W))
	W.fills.castStart("PetCastingBarFrame", "cast")
	W.frame(1)
	check("cast fill: and gets its cover on the frame after the game makes the fill", FH.shownColour(W, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast) and #FH.covers(W, pet) == 1)
	check("cast fill: the cover is anchored to the region the game made", FH.cover(W, pet).points[1][2] == W.rawOf[pet].fill)
	check("cast fill: and nothing is noted", not has(W.status(), "refused"))
end

-- 78e. A paint that raises is counted against the flat fill of the module that owns the bar, and stops that part alone.
do
	local W = FH.cast()
	FH.castAll(W)
	for _, name in ipairs({ FH.PLAYER, "PetCastingBarFrame" }) do
		FH.cover(W, FH.bar(W, name)).SetVertexColor = function() error("paint failed", 0) end
	end
	W.change("castbars.castColour", "ff102030")
	W.frame(5)
	check("cast failure: bars whose paint raises are counted once each however often it is tried", not W.ns.PartStopped("castbars", "flat fill") and not has(W.line("Cast bars"), "failed"), W.line("Cast bars"))
	check("cast failure: the other bars are painted and the module goes on", FH.shownColour(W, "TargetFrameSpellBar") == FH.hex("ff102030") and not W.ns.IsStopped("castbars"))
	for _, name in ipairs({ "TargetFrameSpellBar", "FocusFrameSpellBar", "OverlayPlayerCastingBarFrame" }) do
		FH.cover(W, FH.bar(W, name)).SetVertexColor = function() error("paint failed", 0) end
	end
	W.change("castbars.castColour", "ff405060")
	W.frame(2)
	check("cast failure: three bars that fail stop the flat fill, with the first error, and not the module", W.ns.PartStopped("castbars", "flat fill") and not W.ns.IsStopped("castbars")
		and has(W.status(), "Cast bars: flat fill stopped. paint failed") and not has(W.status(), "Cast bars: stopped"), W.status())
	check("cast failure: Blizzard's look is back: every cover is hidden and the poll is cleared", FH.shownCovers(W) == 0 and not FH.polling(W))
	check("cast failure: the other modules are not affected", has(W.status(), "Swing timers: on, 3 styled") and FH.fill(W, W.prd.power[1]) == "colour 1.000,1.000,1.000")
	-- A cover whose Show fails the same way.
	local X = FH.cast()
	X.fills.castStart(FH.PLAYER, "cast")
	X.frame(1)
	local cover = FH.cover(X, FH.bar(X, FH.PLAYER))
	cover.Hide = function() error("hide failed", 0) end
	X.fills.castStart(FH.PLAYER, "empowered")
	X.frame(3)
	check("cast failure: a Hide that raises is counted once for the bar", not X.ns.PartStopped("castbars", "flat fill") and not has(X.line("Cast bars"), "failed") and #X.errors == 0, X.line("Cast bars"))
end

-- 78f. Forbidden bars, protected bars, and combat.
do
	local W = FH.cast(nil, { forbidden = { TargetFrameSpellBar = true } })
	W.rawOf[FH.bar(W, "TargetFrameSpellBar")].shown = true
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(4)
	check("cast forbidden: a forbidden bar is never read or called and has no cover", #W.violations == 0 and #W.errors == 0 and FH.cover(W, FH.bar(W, "TargetFrameSpellBar")) == nil, FH.why(W))
	check("cast forbidden: the other bars are done", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	-- A bar that becomes forbidden after it has a cover is not read again.
	local X = FH.cast()
	X.fills.castStart(FH.PLAYER, "cast")
	X.frame(2)
	X.rawOf[FH.bar(X, FH.PLAYER)].forbidden = true
	X.frame(3)
	check("cast forbidden: a bar that has become forbidden is not read again", #X.violations == 0 and #X.errors == 0, FH.why(X))
	X.change("castbars.flat", false)
	check("cast forbidden: and switching the fill off does not touch it", #X.violations == 0 and #X.errors == 0, FH.why(X))

	-- A protected bar in combat: nothing is created on it until combat ends.
	local C = FH.cast()
	local P = FH.bar(C, FH.PLAYER)
	C.rawOf[P].protected = true
	C.combat = true
	local textures = #C.addonTextures
	C.fills.castStart(FH.PLAYER, "cast")
	C.frame(4)
	check("cast combat: nothing is created on a protected bar in combat", #C.addonTextures == textures and FH.cover(C, P) == nil and #C.violations == 0, FH.why(C))
	C.combat = false
	C.frame(1)
	check("cast combat: the cover is made on the first frame after combat", FH.shownColour(C, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and #C.violations == 0, FH.why(C))
	C.combat = true
	C.fills.castInterrupt(FH.PLAYER)
	C.frame(1)
	check("cast combat: what is allowed in combat still happens: the colour of the cover changes", FH.shownColour(C, FH.PLAYER) == FH.hex(FH.CAST_HEX.interrupted) and #C.violations == 0, FH.why(C))
	C.change("castbars.flat", false)
	check("cast combat: and so does hiding it", FH.shownColour(C, FH.PLAYER) == "-" and #C.violations == 0, FH.why(C))
	C.change("castbars.flat", true)
	C.frame(1)
	check("cast combat: and showing it", FH.shownColour(C, FH.PLAYER) == FH.hex(FH.CAST_HEX.interrupted) and #C.violations == 0, FH.why(C))
	-- A bar that is not protected has its cover made in combat.
	local U = FH.cast(nil, { combat = true })
	U.fills.castStart(FH.PLAYER, "cast")
	U.frame(1)
	check("cast combat: a bar that is not protected gets its cover in combat", FH.shownColour(U, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and #U.violations == 0, FH.why(U))
	-- A game that does not say whether the bar is protected counts as protected in combat.
	local Q = FH.cast()
	Q.rawOf[FH.bar(Q, FH.PLAYER)].fault.protected = "error"
	Q.combat = true
	Q.fills.castStart(FH.PLAYER, "cast")
	Q.frame(2)
	check("cast combat: a bar whose IsProtected fails is treated as protected in combat", FH.cover(Q, FH.bar(Q, FH.PLAYER)) == nil and #Q.violations == 0)
	Q.combat = false
	Q.frame(1)
	check("cast combat: and is done out of combat", FH.shownColour(Q, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
end

-- 79. Cast bars the nameplates make: ns.CastFill(key, bar, on) as the nameplate module calls it.
do
	-- Only the nameplate bar polls: the five bars have Flat fill off.
	local W = FH.cast({ ["castbars.flat"] = false })
	local bar = W.fills.newCastBar("Plate1CastBar")
	check("nameplate cast fill: a bar that has not been asked for is not registered, and nothing polls", not FH.polling(W) and FH.covers(W, bar)[1] == nil)
	W.ns.CastFill("nameplates", bar, false)
	check("nameplate cast fill: asking for off on a bar that was never on registers nothing", not FH.polling(W))
	W.ns.CastFill("nameplates", bar, true)
	check("nameplate cast fill: on starts the poll", FH.polling(W))
	W.fills.castStart("Plate1CastBar", "channel")
	W.frame(1)
	local cover = FH.cover(W, bar)
	check("nameplate cast fill: a cast on the plate's bar gets a cover in the colour of the Cast bars page", cover and cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.channel) and W.ns.Own[cover] == true)
	check("nameplate cast fill: anchored to the plate's fill, on its layer one sublevel up", cover.points[1][2] == W.rawOf[bar].fill and cover.points[2][2] == W.rawOf[bar].fill and cover.layer == "ARTWORK" and cover.sublevel == 1)
	local textures = #W.addonTextures
	W.ns.CastFill("nameplates", bar, false)
	check("nameplate cast fill: off hides the cover and stops the poll", cover.shown == false and not FH.polling(W))
	W.fills.castFinish("Plate1CastBar")
	W.frame(3)
	check("nameplate cast fill: and a hidden cover gets no paint", cover.shown == false and cover.calls.SetVertexColor == 1)
	W.ns.CastFill("nameplates", bar, true)
	W.frame(1)
	check("nameplate cast fill: on again shows it, nothing made twice", cover.shown and #W.addonTextures == textures and FH.polling(W))
	-- The Cast bars page is off: the plate's bar is still painted, with the colours of that page.
	W.change("castbars.enabled", false)
	W.options()["castbars.channelColour"] = "ff112233"
	W.fills.castStart("Plate1CastBar", "channel")
	W.frame(2)
	check("nameplate cast fill: with the Cast bars page off the plate's cover still follows the page's colours", cover.shown and FH.rgb(cover.vertex) == FH.hex("ff112233") and FH.polling(W), FH.rgb(cover.vertex))
	check("nameplate cast fill: and a colour changed with no Refresh is painted on the next poll", (function() W.options()["castbars.channelColour"] = "ff445566" W.frame(1) return FH.rgb(cover.vertex) == FH.hex("ff445566") end)())
	W.change("castbars.enabled", true)
	W.change("castbars.flat", true)
	W.change("castbars.flat", false)
	check("nameplate cast fill: Flat fill of the Cast bars page does not decide a plate's bar", cover.shown and FH.polling(W))
	-- The Cast bars module is stopped: the plate's bar belongs to the nameplates.
	W.ns.Try("castbars", function() error("probe", 0) end)
	W.options()["castbars.channelColour"] = "ff778899"
	W.frame(2)
	check("nameplate cast fill: with the Cast bars module stopped the plate's bar is not touched and is still painted", cover.shown and FH.rgb(cover.vertex) == FH.hex("ff778899") and FH.polling(W))
	check("nameplate cast fill: the five bars are not", FH.shownCovers(W) == 0)
	-- The module that asked for the bar answers for it.
	cover.SetVertexColor = function() error("paint failed", 0) end
	W.options()["castbars.channelColour"] = "ff102030"
	W.frame(4)
	check("nameplate cast fill: a paint that raises does not stop the nameplates", not has(W.line("Nameplates"), "failed") and not has(W.line("Cast bars"), "failed")
		and not W.ns.IsStopped("nameplates"), W.status())
	-- The nameplate module hides it when it stops, with the same call.
	W.ns.CastFill("nameplates", bar, false)
	check("nameplate cast fill: and hides it with CastFill when it puts Blizzard's look back", cover.shown == false)
end

-- 79a. The texture of a nameplate cast bar is the Cast bar texture row of the nameplates page, and not the row of the Cast bars page.
do
	local W = FH.cast({ ["general.barTexture"] = "soft", ["castbars.texture"] = "gloss", ["nameplates.castTexture"] = "stripes" })
	local plate = W.fills.newCastBar("Plate8CastBar")
	W.ns.CastFill("nameplates", plate, true)
	W.fills.castStart("PlayerCastingBarFrame", "cast")
	W.fills.castStart("Plate8CastBar", "cast")
	W.frame(2)
	local cover, own = FH.cover(W, plate), FH.cover(W, FH.bar(W, FH.PLAYER))
	check("plate cast texture: a plate cast has the file of its own row", cover and cover.shown and cover.file == W.ns.BarFile("stripes") and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and FH.plain(W), cover and tostring(cover.file))
	check("plate cast texture: the Cast bars keep the file of theirs", own and own.file == W.ns.BarFile("gloss"), own and tostring(own.file))
	W.change("nameplates.castTexture", "Same as the Flat UI page")
	W.frame(2)
	check("plate cast texture: Same as the Flat UI page has the page texture", cover.file == W.ns.BarFile("soft") and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast) and FH.plain(W), tostring(cover.file))
	W.change("general.barTexture", "Shaded")
	W.frame(2)
	check("plate cast texture: and follows a change of it", cover.file == W.ns.BarFile("shaded") and own.file == W.ns.BarFile("gloss"), tostring(cover.file))
	W.change("nameplates.castTexture", "Flat")
	W.frame(2)
	check("plate cast texture: Flat is a solid colour whatever the page chooses", cover.color and cover.color[1] == 1 and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast), tostring(cover.file) .. " " .. FH.rgb(cover.vertex))
end

do
	local W = FH.cast({ ["castbars.flat"] = false })
	-- Forbidden bars, bars that are not bars, and a bar with no GetStatusBarTexture.
	local forbidden = W.fills.newCastBar("Plate2CastBar", { forbidden = true })
	W.ns.CastFill("nameplates", forbidden, true)
	W.ns.CastFill("nameplates", nil, true)
	W.ns.CastFill("nameplates", 5, true)
	W.ns.CastFill("nameplates", SECRET, true)
	local plate = W.newPlate()
	W.ns.CastFill("nameplates", plate.castBar, true)
	W.frame(3)
	check("nameplate cast fill: a forbidden bar, a bar that is not a frame and a bar with no fill method are never registered", not FH.polling(W) and #W.violations == 0 and #W.errors == 0, FH.why(W))
	-- A bar that becomes forbidden while it is on.
	local bar, inner = W.fills.newCastBar("Plate3CastBar")
	W.ns.CastFill("nameplates", bar, true)
	W.fills.castStart("Plate3CastBar", "cast")
	W.frame(1)
	local cover = FH.cover(W, bar)
	inner.forbidden = true
	W.frame(3)
	W.ns.CastFill("nameplates", bar, false)
	check("nameplate cast fill: a bar that has become forbidden is not read again and not called", #W.violations == 0 and #W.errors == 0 and cover.shown == true, FH.why(W))
	-- A plate in the game's classic style: the fill is a file.
	local classic = W.fills.newCastBar("Plate4CastBar")
	W.ns.CastFill("nameplates", classic, true)
	W.blizzard(function() classic:SetStatusBarTexture("Interface\\TargetingFrame\\UI-StatusBar") end)
	W.rawOf[classic].shown = true
	W.frame(3)
	check("nameplate cast fill: a plate whose fill is a file keeps the game's fill and the cover stays hidden", (FH.cover(W, classic) == nil or FH.cover(W, classic).shown == false) and FH.plain(W), FH.why(W))
	-- A plate that is reused for another unit keeps its cover, and the state is read again.
	local reuse = W.fills.newCastBar("Plate5CastBar")
	W.ns.CastFill("nameplates", reuse, true)
	W.fills.castStart("Plate5CastBar", "cast")
	W.frame(1)
	W.fills.castHide("Plate5CastBar")
	W.fills.castStart("Plate5CastBar", "crafting")
	W.frame(1)
	check("nameplate cast fill: a reused plate keeps its cover and gets the new colour", #FH.covers(W, reuse) == 1 and FH.rgb(FH.cover(W, reuse).vertex) == FH.hex(FH.CAST_HEX.craft))
	-- In combat, a plate's bar that is protected gets its cover when combat ends.
	local guarded, ginner = W.fills.newCastBar("Plate6CastBar", { protected = true })
	W.ns.CastFill("nameplates", guarded, true)
	W.combat = true
	local textures = #W.addonTextures
	W.fills.castStart("Plate6CastBar", "cast")
	W.frame(3)
	check("nameplate cast fill: nothing is created on a protected plate bar in combat", #W.addonTextures == textures and #W.violations == 0, FH.why(W))
	W.combat = false
	W.frame(1)
	check("nameplate cast fill: and its cover is made when combat ends", FH.cover(W, guarded) and FH.cover(W, guarded).shown)
end

do
	-- A bar that has become forbidden is no longer wanted, however it is asked.
	local W = FH.cast({ ["castbars.flat"] = false })
	local bar, inner = W.fills.newCastBar("Plate7CastBar")
	W.ns.CastFill("nameplates", bar, true)
	check("nameplate cast fill: a plate bar that is on starts the poll", FH.polling(W))
	inner.forbidden = true
	W.ns.CastFill("nameplates", bar, true)
	check("nameplate cast fill: asked for on again after it became forbidden, the poll stops", not FH.polling(W) and #W.violations == 0 and #W.errors == 0, FH.why(W))
	inner.forbidden = false
	W.ns.CastFill("nameplates", bar, true)
	check("nameplate cast fill: and it is wanted again when it is not forbidden", FH.polling(W))
	-- A bar asked for by another module takes that module's name for its failures.
	W.fills.castStart("Plate7CastBar", "cast")
	W.frame(1)
	local cover = FH.cover(W, bar)
	cover.SetVertexColor = function() error("paint failed", 0) end
	W.options()["castbars.castColour"] = "ff102030"
	W.frame(2)
	W.ns.CastFill("castbars", bar, true)
	W.options()["castbars.castColour"] = "ff405060"
	W.frame(2)
	check("nameplate cast fill: a bar asked for again by another module is no failure of either module", not has(W.line("Cast bars"), "failed") and not has(W.line("Nameplates"), "failed")
		and not W.ns.IsStopped("nameplates") and not W.ns.IsStopped("castbars"), W.status())
end

-- 79b. Making the cover raises.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	local calls = 0
	W.rawOf[P].CreateTexture = function() calls = calls + 1 error("CreateTexture failed", 0) end
	W.fills.castStart(FH.PLAYER, "cast")
	W.fills.castStart("PetCastingBarFrame", "cast")
	W.frame(6)
	check("cast failure: a bar that cannot make its cover is tried once, counted once, and not every frame", calls == 1 and not W.ns.PartStopped("castbars", "flat fill") and not has(W.line("Cast bars"), "failed"), calls .. " " .. W.line("Cast bars"))
	check("cast failure: the other bars are done", FH.shownColour(W, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast))
	check("cast failure: the game's fill is as it was", FH.fill(W, P) == "atlas ui-castingbar-filling-standard" and FH.changes(W, P) == 0)
end

-- 79c. The border switches do not decide the fill.
do
	local W = FH.cast({ ["castbars.player"] = false, ["castbars.pet"] = false, ["castbars.target"] = false, ["castbars.focus"] = false })
	FH.castAll(W)
	check("cast fill: with all four border switches off the covers are made", FH.shownCovers(W) == 5 and FH.plain(W), FH.why(W))
	W.change("castbars.player", true)
	W.change("castbars.player", false)
	check("cast fill: a border switch changed later leaves them", FH.shownCovers(W) == 5)
	local X = FH.res({ ["resource.health"] = false, ["resource.power"] = false, ["resource.alt"] = false })
	check("resource fill: with all three border switches off the fill is made", FH.fill(X, X.prd.health[1]) == "colour 1.000,1.000,1.000" and FH.fill(X, X.prd.power[1]) == "colour 1.000,1.000,1.000")
end

-- 79d. Every setting of the three Fill sections, through its control: the dependencies are greyed and usable at the right times.
do
	local W = FH.world()
	W.openPanel()
	local function mismatches()
		local list = {}
		for _, row in ipairs(ALL) do
			if W.enabled(row.path) ~= usable(W, row) then
				list[#list + 1] = row.path .. (usable(W, row) and " should be usable" or " should be greyed")
			end
		end
		return table.concat(list, "; ")
	end
	check("fill controls: at the defaults everything is as the table says", mismatches() == "", mismatches())
	for _, case in ipairs({
		{ "swing.flat", { "swing.mainColour", "swing.offColour", "swing.rangedColour", "swing.classColour", "swing.spark", "swing.textShadow" } },
		{ "resource.healthOwn", { "resource.healthColour" } },
		{ "resource.powerOwn", { "resource.powerColour" } },
		-- The cast colours are on the first page and do not wait for the fill of the Cast bars page.
		{ "castbars.flat", {} },
	}) do
		local source = case[1]
		local was = W.ns.Get(source)
		W.change(source, not was)
		local want = not was
		local right = mismatches() == ""
		for _, path in ipairs(case[2]) do
			right = right and W.enabled(path) == want
		end
		check("fill controls: " .. source .. " " .. (want and "on" or "off") .. (want and " makes " or " greys ") .. #case[2] .. " settings " .. (want and "usable" or "unusable"), right, mismatches())
		W.change(source, was)
		right = mismatches() == ""
		for _, path in ipairs(case[2]) do
			right = right and W.enabled(path) == was
		end
		check("fill controls: " .. source .. " " .. (was and "on" or "off") .. " again", right, mismatches())
	end
	for _, area in ipairs({ "swing", "resource", "castbars" }) do
		W.change(area .. ".enabled", false)
		check("fill controls: " .. area .. " off greys the fill settings of its page and nothing else", mismatches() == "" and not W.enabled(area .. ".flat") and W.enabled(area .. ".enabled"), mismatches())
		W.change(area .. ".enabled", true)
		check("fill controls: " .. area .. " on makes them usable again", mismatches() == "" and W.enabled(area .. ".flat"), mismatches())
	end
	-- Each setting of the three sections, changed and changed back, leaves nothing raised.
	local paths = {}
	for _, row in ipairs(ALL) do
		if (row.page == "swing" and (row.path:find("Colour$") or row.path:find("%.spark$") or row.path:find("%.textShadow$") or row.path:find("%.flat$")))
			or (row.page == "resource" and (row.path:find("Own$") or row.path:find("Colour$") or row.path:find("%.flat$")))
			or (row.path:find("^castbars%.") and (row.path:find("Colour$") or row.path:find("%.flat$"))) then
			paths[#paths + 1] = row
		end
	end
	local perPage = { swing = 0, resource = 0, castbars = 0 }
	for _, row in ipairs(paths) do
		perPage[row.page] = (perPage[row.page] or 0) + 1
	end
	check("fill controls: each of the three sections has settings", perPage.swing > 0 and perPage.resource > 0 and perPage.castbars > 0, #paths)
	for _, row in ipairs(paths) do
		local was = W.ns.Get(row.path)
		local other
		if row.kind == "bool" then
			other = not was
		else
			other = was == "ff102030" and "ff405060" or "ff102030"
		end
		-- A colour picked in a row that is greyed out is dropped, so the switch it needs is on while it is picked.
		local needed = row.needs and W.ns.Get(row.needs) ~= true and row.needs
		if needed then
			W.change(needed, true)
		end
		W.change(row.path, other)
		W.frame(1)
		local changed = W.ns.Get(row.path) == other and W.read(row.path) == other
		W.change(row.path, was)
		W.change(row.path, other)
		W.change(row.path, was)
		W.frame(1)
		if needed then
			W.change(needed, false)
		end
		check("fill controls: " .. row.path .. " changed, on, off and on again, through its control", changed and W.ns.Get(row.path) == was and W.read(row.path) == was and #W.violations == 0 and #W.errors == 0, FH.why(W))
	end
	check("fill controls: everything the panel did raised nothing and printed nothing", FH.plain(W), FH.why(W))
end

-- 80. Every flat fill off: Blizzard's look is exactly as before, and nothing polls.
do
	local off = { ["swing.flat"] = false, ["resource.flat"] = false, ["castbars.flat"] = false }
	local looks = {}
	local W = FH.world({ saved = { options = off } }, function(X)
		for _, name in ipairs(FH.SWING) do
			looks[name] = FH.snap(X, X.fills.swing[name])
		end
		for key, pair in pairs(X.prd) do
			looks[key] = FH.fill(X, pair[1]) .. " " .. FH.tint(X, pair[1])
		end
		for _, name in ipairs(FH.CASTS) do
			looks[name] = FH.fill(X, FH.bar(X, name)) .. " " .. FH.tint(X, FH.bar(X, name))
		end
	end)
	FH.castAll(W)
	W.fills.castStart(FH.PLAYER, "channel")
	W.fills.swingStart("SwingTimerMainHandFrame")
	W.fills.setPower("RAGE")
	W.change("swing.mainColour", "ff336699")
	W.change("castbars.castColour", "ff336699")
	W.change("swing.classColour", true)
	W.frame(6)
	local calls, same = 0, true
	for _, name in ipairs(FH.SWING) do
		local s = W.fills.swing[name]
		for _ in pairs(s.barRaw.byAddon) do
			calls = calls + 1
		end
		for _ in pairs(s.fillRaw.calls) do
			calls = calls + 1
		end
		for _ in pairs(s.shadowRaw.calls) do
			calls = calls + 1
		end
		for k in pairs(s.pipRaw.calls) do
			calls = calls + (k == "Show" and 0 or 1)
		end
		same = same and FH.snap(W, s) == looks[name]
	end
	for _, pair in pairs(W.prd) do
		for _ in pairs(W.rawOf[pair[1]].byAddon) do
			calls = calls + 1
		end
	end
	for _, name in ipairs(FH.CASTS) do
		for _ in pairs(W.rawOf[FH.bar(W, name)].byAddon) do
			calls = calls + 1
		end
	end
	check("all fills off: the addon calls no status bar, fill, Pip or shadow", calls == 0, calls)
	check("all fills off: the game's fill, Pip, shadow and tint on a swing timer are exactly as the game made them", same and W.fills.swing.SwingTimerMainHandFrame.pipRaw.alpha == 1 and W.fills.swing.SwingTimerMainHandFrame.shadowRaw.alpha == 1)
	check("all fills off: the resource bars show the colours the game set", FH.fill(W, W.prd.power[1]) == "atlas " .. FH.BAR_ATLAS and FH.tint(W, W.prd.power[1]) == FH.RAGE and FH.fill(W, W.prd.health[1]) == "atlas " .. FH.BAR_ATLAS)
	check("all fills off: the cast bars have no cover and keep the game's fill", FH.allCovers(W) == 0 and FH.fillCalls(W) == 0 and FH.fill(W, FH.bar(W, FH.PLAYER)) == "atlas ui-castingbar-filling-channel")
	check("all fills off: nothing polls", not FH.polling(W))
	check("all fills off: no violation, no message, nothing failed", FH.plain(W) and not has(W.status(), "failed"), FH.why(W))
	check("all fills off: the borders are still made", W.state(W.prd.power[1]) == "SB" and W.state(W.fills.swing.SwingTimerMainHandFrame.bar) == "SB" and W.state(FH.bar(W, FH.PLAYER)) == "SB")
	-- Switched on one at a time.
	W.change("swing.flat", true)
	check("all fills off: Flat fill on for the swing timers alone makes only those", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.WARRIOR and FH.fill(W, W.prd.power[1]) == "atlas " .. FH.BAR_ATLAS
		and FH.allCovers(W) == 0 and not FH.polling(W))
	W.change("castbars.flat", true)
	W.frame(1)
	check("all fills off: and then the cast bars alone start the poll", FH.shownCovers(W) == 5 and FH.polling(W))
	W.change("resource.flat", true)
	check("all fills off: and then the resource bars", FH.fill(W, W.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.tint(W, W.prd.power[1]) == FH.RAGE)
end

-- 81. Settings saved by versions 0.1.0 and 0.2.0 load unchanged, and the fills are on.
do
	local W = FH.world({ saved = { nameplates = true, actionbars = true, resource = true, swing = false, castbars = true, thickness = 2 } })
	local options = W.options()
	local extra = {}
	for key in pairs(options) do
		if not (key:find("%.enabled$") or key == "general.thickness") then
			extra[#extra + 1] = key
		end
	end
	check("settings of 0.1.0: the switches and the thickness are kept", options["swing.enabled"] == false and options["resource.enabled"] == true and options["castbars.enabled"] == true and options["general.thickness"] == 2
		and W.env.FlatUIDB.swing == nil and W.env.FlatUIDB.thickness == nil)
	check("settings of 0.1.0: nothing for the fills is saved", #extra == 0 and options["castbars.flat"] == nil and options["resource.flat"] == nil, table.concat(extra, " "))
	FH.castAll(W)
	check("settings of 0.1.0: the fills of the pages that are on are made with their default colours", FH.fill(W, W.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	check("settings of 0.1.0: and the page that is off is not touched", FH.changes(W, W.fills.swing.SwingTimerMainHandFrame.bar) == 0 and FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "atlas ui-swingtimerbar-filling-mainhand")
	clean(W, "settings of 0.1.0")

	local saved = { ["general.thickness"] = 3, ["general.border"] = "ff336699", ["general.backdropAlpha"] = 60, ["swing.main"] = false, ["swing.outline"] = "frame", ["resource.join"] = false,
		["resource.alt"] = false, ["castbars.textPlate"] = true, ["castbars.pet"] = false, ["nameplates.level"] = "text", ["actionbars.crop"] = 5, ["windows.opacity"] = 60, ["resource.enabled"] = true }
	local copy = {}
	for k, v in pairs(saved) do
		copy[k] = v
	end
	local X = FH.world({ saved = { options = saved } })
	FH.castAll(X)
	local kept, added = true, {}
	for k, v in pairs(copy) do
		kept = kept and X.options()[k] == v
	end
	for k in pairs(X.options()) do
		if copy[k] == nil then
			added[#added + 1] = k
		end
	end
	check("settings of 0.2.0: every saved value is kept", kept)
	check("settings of 0.2.0: and nothing is added for the fills", #added == 0, table.concat(added, " "))
	check("settings of 0.2.0: the fills are on with their default colours", FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.fill(X, X.prd.health[1]) == "colour 1.000,1.000,1.000"
		and FH.shownColour(X, "TargetFrameSpellBar") == FH.hex(FH.CAST_HEX.cast))
	check("settings of 0.2.0: a border the player switched off does not stop the fill", FH.fill(X, X.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.shownColour(X, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast))
	check("settings of 0.2.0: the controls show the defaults of the new settings", X.read("swing.flat") == true and X.read("castbars.castColour") == "ffe6b333" and X.read("resource.powerOwn") == false)
	clean(X, "settings of 0.2.0")
	-- A value of the wrong type saved for a fill setting is repaired like any other.
	local odd = FH.world({ saved = { options = { ["swing.flat"] = "yes", ["swing.mainColour"] = "red", ["castbars.castColour"] = 5, ["resource.powerOwn"] = 1 } } })
	check("saved fill settings of the wrong type are dropped and the defaults used", odd.ns.Get("swing.flat") == true and odd.ns.Get("swing.mainColour") == "ffd9a640" and odd.ns.Get("castbars.castColour") == "ffe6b333"
		and odd.ns.Get("resource.powerOwn") == false and FH.fill(odd, odd.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640"))
end

-- 82. A client without what the fills use.
do
	local all = { SwingTimerMainHandFrame = true, SwingTimerOffHandFrame = true, SwingTimerRangedFrame = true }
	local W = FH.world({ missing = all })
	check("fills client: without the swing timers there is nothing to do and nothing wrong", has(W.status(), "Swing timers: on, 0 styled") and FH.plain(W), FH.why(W))
	local X = FH.res(nil, { missing = { PersonalResourceDisplayFrame = true } })
	X.change("resource.powerOwn", true)
	X.change("resource.flat", false)
	check("fills client: without the personal resource display the same", has(X.status(), "Personal resource display: on, 0 styled") and not FH.polling(X) and FH.plain(X), FH.why(X))
	local casts = {}
	for _, name in ipairs(FH.CASTS) do
		casts[name] = true
	end
	local Y = FH.world({ missing = casts })
	check("fills client: without the cast bars the poll is not needed", has(Y.status(), "Cast bars: on, 0 styled") and not FH.polling(Y) and FH.plain(Y), FH.why(Y))
	local Z = FH.world({ missing = { PlayerCastingBarFrame = true, OverlayPlayerCastingBarFrame = true, TargetFrameSpellBar = true, FocusFrameSpellBar = true } })
	FH.castAll(Z)
	check("fills client: with four of the cast bars missing the fifth is done", FH.shownCovers(Z) == 1 and FH.shownColour(Z, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast) and FH.plain(Z), FH.why(Z))
	-- Methods the cast bars use.
	local G = FH.cast(nil, { fills = { without = { "GetStatusBarTexture" } } })
	FH.castAll(G)
	check("fills client: cast bars without GetStatusBarTexture are not registered and nothing polls", not FH.polling(G) and FH.allCovers(G) == 0 and FH.plain(G), FH.why(G))
	local A = FH.cast(nil, { fills = { without = { "GetAtlas" } } })
	A.fills.castStart(FH.PLAYER, "cast")
	A.frame(1)
	local cast = FH.shownColour(A, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast)
	A.fills.castStart(FH.PLAYER, "channel")
	A.frame(1)
	local channel = FH.shownColour(A, FH.PLAYER) == FH.hex(FH.CAST_HEX.channel)
	A.fills.castInterrupt(FH.PLAYER)
	A.frame(1)
	local interrupted = FH.shownColour(A, FH.PLAYER) == FH.hex(FH.CAST_HEX.interrupted)
	A.fills.castStart(FH.PLAYER, "cast", { notInterruptible = true })
	A.frame(1)
	check("fills client: cast bars without GetAtlas are coloured from the fields, the spark and the shield", cast and channel and interrupted and FH.shownColour(A, FH.PLAYER) == FH.hex(FH.CAST_HEX.shield) and FH.plain(A),
		FH.why(A))
	local S = FH.cast(nil, { fills = { without = { "GetStatusBarTexture", "GetAtlas", "SetColorFill", "SetStatusBarTexture", "GetStatusBarColor", "SetStatusBarColor" } } })
	check("fills client: a client without any of the status bar methods raises nothing and changes nothing", FH.plain(S) and not has(S.status(), "failed") and not has(S.status(), "stopped"), FH.why(S) .. S.status())
	-- Globals the swing and resource fills use.
	local C = FH.world({ fills = { noClass = true, noCreateColor = true }, saved = { options = { ["swing.classColour"] = true } } })
	FH.castAll(C)
	check("fills client: without UnitClass, RAID_CLASS_COLORS and CreateColor the colours are the settings'", FH.fill(C, C.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.plain(C), FH.why(C))
end

-- 83. /flatui status.
do
	local W = FH.world()
	check("status: with the fills made the lines are the same as before, and none says stopped or failed", TOC.inOrder(TOC.lines(W.status()), { TOC.head(1), "Nameplates: on, 0 styled", "Combat text: on", "Numbers in front of nameplates: waiting for the first hit. The game's numbers show until then.", "Combat text for you: 0 shown.", "Action bars: on, 118 styled", "Personal resource display: on, 3 styled",
		"Swing timers: on, 3 styled", "Cast bars: on, 5 styled", "Cooldowns: on, 0 styled", "Cooldown icons: the game has no spell book information, so Add a spell lists nothing.",
		"Trackers: on, 0 shown", "Defensives on you: on", "Party cooldowns: on", "Enemy cooldowns: on", "Windows: on, 0 styled", W.line("Unit frames"), W.line("Minimap and buffs"), W.line("Minimap in cities"), W.line("Chat and tooltips"), "Movers: on, 0 moved", "Bar block: off", "Bar blocks: on", "Tooltip: off", "Fonts: off", "Fading: off", "Game settings: 16 of 16 rows not turned down so far" }) and not has(W.status(), "stopped") and not has(W.status(), "failed"), W.status())
	local X = FH.world(nil, function(Y)
		for _, name in ipairs(FH.SWING) do
			Y.fills.swing[name].fillRaw.atlas = nil
			Y.fills.swing[name].inner.barTexture = nil
		end
		Y.fills.setup()
		Y.prd.alt[2].fillRaw.atlas = nil
	end)
	local text = X.slash("status")
	check("status: a swing fill that cannot be read has its line under the Swing timers line", has(text, "Swing timers: on, 3 styled\nSwing timers: the default fill of a timer could not be read and is still shown.\nCast bars:"), text)
	check("status: so does a resource fill, once, under its line", has(text, "Personal resource display: on, 3 styled\nPersonal resource display: the default fill of a bar could not be read and is still shown.\nYour buffs:"), text)
	local Z = FH.cast()
	Z.refuse[FH.bar(Z, "TargetFrameSpellBar")] = true
	FH.castAll(Z)
	check("status: a cast bar cover without an anchor has its line under the Cast bars line", has(Z.slash("status"), "Cast bars: on, 5 styled\nCast bars: the game refused a fill on one cast bar, which keeps its default fill.\nCooldowns:"), Z.slash("status"))
	local H = FH.world()
	check("status: help is unchanged: the command lines and the help of each module", H.slash("what") == TOC.allHelp(H), H.slash("what"))
end

-- 84. Turning each page off and on leaves the same number of addon textures and frames.
do
	local W = FH.cast({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true })
	FH.castAll(W)
	W.fills.setup()
	W.frame(2)
	local frames, textures = #W.addonFrames, #W.addonTextures
	local pollFrames = 0
	for _, f in ipairs(W.eventFrames) do
		pollFrames = pollFrames + ((f.updateSets and not f.dividers) and 1 or 0)
	end
	for round = 1, 2 do
		for _, area in ipairs({ "swing", "resource", "castbars" }) do
			W.change(area .. ".enabled", false)
			W.frame(1)
			W.change(area .. ".enabled", true)
			W.frame(1)
		end
	end
	local nowPoll = 0
	for _, f in ipairs(W.eventFrames) do
		nowPoll = nowPoll + ((f.updateSets and not f.dividers) and 1 or 0)
	end
	check("all pages: each turned off and on again twice leaves the same number of addon frames and textures", #W.addonFrames == frames and #W.addonTextures == textures, (#W.addonFrames - frames) .. " " .. (#W.addonTextures - textures))
	check("all pages: and one frame that follows colours and casts", nowPoll == pollFrames and pollFrames == 1, nowPoll .. " " .. pollFrames)
	check("all pages: and the fills are as they were", FH.fill(W, W.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.tint(W, W.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.shownCovers(W) == 5
		and FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.fill(W, W.prd.alt[1]) == "colour 1.000,1.000,1.000")
	clean(W, "all pages")
end

-- 85. Reads of the cast bars that the client answers with something unusable.
do
	for _, case in ipairs({ { "nothing", "nothing" }, { "a withheld value", "secret" }, { "an error", "error" }, { "a string", "string" } }) do
		local W = FH.cast(nil, nil, function(X)
			for _, name in ipairs(FH.CASTS) do
				X.fills.cast[name].inner.fault.fillRegion = case[2]
			end
		end)
		FH.castAll(W)
		W.frame(3)
		check("cast fill: GetStatusBarTexture gives " .. case[1] .. ", no cover is made and nothing is raised", FH.allCovers(W) == 0 and FH.plain(W) and not has(W.status(), "failed"), FH.why(W) .. W.status())
		for _, name in ipairs(FH.CASTS) do
			W.fills.cast[name].inner.fault.fillRegion = nil
		end
		W.frame(1)
		check("cast fill: and the covers are made on a later frame when it answers", FH.shownCovers(W) == 5)
	end
	-- IsForbidden withheld on a bar that is polled: it is not read or painted.
	local W = FH.cast()
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
	W.rawOf[FH.bar(W, FH.PLAYER)].IsForbidden = function() return SECRET end
	W.options()["castbars.castColour"] = "ff112233"
	W.frame(3)
	check("cast fill: a bar whose IsForbidden is withheld is not painted and raises nothing", cover.calls.SetVertexColor == 1 and FH.plain(W) and not has(W.status(), "failed"), FH.why(W))
	-- IsProtected withheld in combat.
	local P = FH.cast()
	P.rawOf[FH.bar(P, FH.PLAYER)].fault.protected = "secret"
	P.combat = true
	P.fills.castStart(FH.PLAYER, "cast")
	P.frame(2)
	check("cast fill: a bar whose IsProtected is withheld is taken for protected in combat", FH.cover(P, FH.bar(P, FH.PLAYER)) == nil and #P.violations == 0)
	-- A client without IsProtected.
	local Q = FH.cast()
	Q.rawOf[FH.bar(Q, FH.PLAYER)].IsProtected = nil
	Q.combat = true
	Q.fills.castStart(FH.PLAYER, "cast")
	Q.frame(2)
	check("cast fill: a bar without IsProtected is taken for protected in combat", FH.cover(Q, FH.bar(Q, FH.PLAYER)) == nil and #Q.violations == 0)
	-- Globals one at a time.
	local U = FH.world({ saved = { options = { ["swing.classColour"] = true } } }, function(X)
		X.env.UnitClass = nil
	end)
	local R = FH.world({ saved = { options = { ["swing.classColour"] = true } } }, function(X)
		X.env.RAID_CLASS_COLORS = nil
	end)
	check("swing class colour: a client without UnitClass keeps the three colours", FH.fill(U, U.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.plain(U), FH.why(U))
	check("swing class colour: a client without RAID_CLASS_COLORS keeps the three colours", FH.fill(R, R.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.plain(R), FH.why(R))
	-- The alternate bar and the sound of the other bars when the game has no fill region for it.
	local A = FH.res(nil, nil, function(X)
		X.fills.setup()
		X.prd.alt[2].fault.fillRegion = "nothing"
	end)
	check("resource alternate bar: with no fill region it is left alone and the other bars are done", FH.changes(A, A.prd.alt[1]) == 0 and FH.fill(A, A.prd.power[1]) == "colour 1.000,1.000,1.000" and FH.plain(A), FH.why(A))
	-- A client where the spark or the shield cannot be asked.
	local M = FH.cast()
	M.fills.castStart(FH.PLAYER, "cast", { secret = true, notInterruptible = true })
	M.fills.cast[FH.PLAYER].shieldRaw.IsShown = nil
	M.frame(2)
	check("cast withheld: a shield that cannot be asked is not taken for shown", FH.shownColour(M, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(M), FH.why(M))
	M.fills.castInterrupt(FH.PLAYER, true)
	M.fills.cast[FH.PLAYER].sparkRaw.IsShown = nil
	M.frame(2)
	check("cast withheld: a spark that cannot be asked is not taken for shown", FH.shownColour(M, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(M), FH.why(M))
	-- One resource bar forbidden at a time.
	for _, key in ipairs({ "health", "power" }) do
		local F = FH.res({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true }, { forbidden = { ["PRD." .. key] = true } })
		F.frame(3)
		local other = key == "health" and "power" or "health"
		check("resource forbidden: with the " .. key .. " bar forbidden the " .. other .. " bar is done, and the forbidden one is not read", FH.fill(F, F.prd[other][1]) == "colour 1.000,1.000,1.000"
			and FH.tint(F, F.prd[other][1]) == FH.hex(other == "health" and FH.HEALTH_HEX or FH.POWER_HEX) and #F.violations == 0 and #F.errors == 0, FH.why(F))
	end
end

-- 86. Details the fills must get right: single channels, alpha, a Refresh after the custom colour is off, withheld values of each type.
do
	local function num(hex, i)
		return tonumber(hex:sub(i, i + 1), 16) / 255
	end
	-- A swing colour that changes in one channel only is a change.
	local W = FH.world()
	local main = W.fills.swing.SwingTimerMainHandFrame
	W.change("swing.mainColour", "ff336699")
	local n = FH.n(W, main.bar, "SetColorFill")
	for _, hex in ipairs({ "ff346699", "ff346799", "ff34679a", "ff336699" }) do
		W.change("swing.mainColour", hex)
		n = n + 1
		check("swing fill: a colour that differs in one channel only (" .. hex .. ") is set", FH.n(W, main.bar, "SetColorFill") == n and FH.fill(W, main.bar) == "colour " .. FH.hex(hex), FH.fill(W, main.bar))
	end
	-- A game colour that matches the custom colour in two channels is the game's.
	local hex = FH.POWER_HEX
	local cr, cg, cb = num(hex, 3), num(hex, 5), num(hex, 7)
	for _, case in ipairs({ { "red", { 0.1, cg, cb } }, { "green", { cr, 0.2, cb } }, { "blue", { cr, cg, 0.3 } } }) do
		local X = FH.res({ ["resource.powerOwn"] = true })
		local power = X.prd.power[1]
		X.blizzard(function() power:SetStatusBarColor(case[2][1], case[2][2], case[2][3]) end)
		X.frame(1)
		check("resource colour: a game colour that differs from the custom one in " .. case[1] .. " only is set over", FH.tint(X, power) == FH.hex(hex) and FH.n(X, power, "SetStatusBarColor") == 2, FH.tint(X, power))
		X.change("resource.powerOwn", false)
		check("resource colour: and is the one that comes back", FH.tint(X, power) == FH.rgb(case[2]), FH.tint(X, power))
	end
	-- The game's alpha comes back too.
	local A = FH.res({ ["resource.powerOwn"] = true })
	local apower = A.prd.power[1]
	A.blizzard(function() apower:SetStatusBarColor(0.9, 0.8, 0.7, 0.5) end)
	A.frame(1)
	A.change("resource.powerOwn", false)
	check("resource colour: the alpha the game gave comes back with the colour", FH.tint(A, apower) == "0.900,0.800,0.700" and A.rawOf[apower].tint[4] == 0.5, tostring(A.rawOf[apower].tint[4]))
	-- After the custom colour is off, a Refresh does not bring an older colour back.
	local S = FH.res({ ["resource.powerOwn"] = true })
	local spower = S.prd.power[1]
	S.fills.setPower("RAGE")
	S.frame(1)
	S.change("resource.powerOwn", false)
	S.fills.setPower("ENERGY")
	S.change("resource.join", false)
	S.change("resource.join", true)
	S.frame(2)
	check("resource colour: with the custom colour off a Refresh leaves the colour the game set after it", FH.tint(S, spower) == FH.ENERGY and FH.n(S, spower, "SetStatusBarColor") == 3, FH.tint(S, spower))
end

do
	-- Values that are withheld, with the type a withheld value has.
	for _, kind in ipairs({ "string", "number", "table" }) do
		local W = FH.world(nil, function(X)
			X.secretType = kind
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].fillRaw.fault.atlas = "secret"
			end
		end)
		for _, name in ipairs(FH.SWING) do
			W.fills.swing[name].fillRaw.fault.atlas = nil
		end
		W.change("swing.flat", false)
		check("swing fill: a withheld atlas that looks like a " .. kind .. " is not the atlas to put back", FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) == "atlas ui-swingtimerbar-filling-mainhand" and FH.plain(W) and not has(W.status(), "failed"),
			FH.fill(W, W.fills.swing.SwingTimerMainHandFrame.bar) .. FH.why(W))
		local V = FH.world(nil, function(X)
			X.secretType = kind
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].fillRaw.atlas = nil
				X.fills.swing[name].inner.barTexture = SECRET
			end
		end)
		check("swing fill: a withheld barTexture that looks like a " .. kind .. " is not used", FH.changes(V, V.fills.swing.SwingTimerMainHandFrame.bar) == 0 and FH.plain(V) and not has(V.status(), "failed"), FH.why(V))
		local C = FH.world({ saved = { options = { ["swing.classColour"] = true } } }, function(X)
			X.secretType = kind
			X.fills.classFault = "secret"
		end)
		check("swing class colour: a class that looks like a " .. kind .. " is not used", FH.fill(C, C.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.plain(C), FH.why(C))
		for _, channel in ipairs({ "r", "g", "b" }) do
			local D = FH.world({ saved = { options = { ["swing.classColour"] = true } } }, function(X)
				X.secretType = kind
				X.env.RAID_CLASS_COLORS.WARRIOR[channel] = SECRET
			end)
			check("swing class colour: a " .. channel .. " that looks like a " .. kind .. " is not used", FH.fill(D, D.fills.swing.SwingTimerMainHandFrame.bar) == "colour " .. FH.hex("ffd9a640") and FH.plain(D), FH.why(D))
		end
		for _, at in ipairs({ 1, 2, 3, 4 }) do
			local R = FH.res({ ["resource.powerOwn"] = true }, nil, function(X)
				X.secretType = kind
				local tint = { 0.1, 0.2, 0.3, 1 }
				tint[at] = SECRET
				X.prd.power[2].tint = tint
			end)
			check("resource colour: value " .. at .. " of the colour that looks like a " .. kind .. " is not compared", FH.tint(R, R.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.plain(R) and not has(R.status(), "failed"), FH.why(R) .. R.status())
		end
		-- The cast fill.
		local K = FH.cast(nil, nil, function(X)
			X.secretType = kind
		end)
		K.fills.castStart(FH.PLAYER, "channel", { secret = true, notInterruptible = true, secretShield = true })
		K.frame(2)
		check("cast withheld: values that look like a " .. kind .. " are not compared", FH.shownColour(K, FH.PLAYER) ~= "-" and FH.plain(K) and not has(K.status(), "failed"), FH.why(K) .. K.status())
	end
end

do
	-- The frame that follows colours and casts is set when the need changes and not otherwise.
	local W = FH.cast()
	local poll
	for _, frame in ipairs(W.eventFrames) do
		if frame.updateSets then
			poll = frame
		end
	end
	check("poll: one frame is made, and it runs a script because bars want a flat fill", poll ~= nil and poll.onUpdate ~= nil and poll.updateSets == 1)
	check("poll: it is in ns.Own", W.ns.Own[poll] == true)
	W.change("swing.backdrop", false)
	W.change("castbars.castColour", "ff336699")
	W.change("resource.powerColour", "ff336699")
	W.change("general.thickness", 2)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(3)
	check("poll: Refreshes that change nothing about what is needed leave the script alone", poll.updateSets == 1, poll.updateSets)
	W.change("castbars.flat", false)
	check("poll: Flat fill off clears it", poll.onUpdate == nil and poll.updateSets == 2)
	W.change("castbars.flat", true)
	check("poll: and on sets it again", poll.onUpdate ~= nil and poll.updateSets == 3)
	W.change("resource.powerOwn", true)
	W.change("resource.healthOwn", true)
	check("poll: a custom colour on while the cast bars need it changes nothing", poll.updateSets == 3)
	W.change("castbars.flat", false)
	check("poll: the cast bars off while a custom colour is on leaves it", poll.onUpdate ~= nil and poll.updateSets == 3)
	W.change("resource.powerOwn", false)
	check("poll: one custom colour of two off leaves it", poll.onUpdate ~= nil and poll.updateSets == 3)
	W.change("resource.healthOwn", false)
	check("poll: the last one off clears it", poll.onUpdate == nil and poll.updateSets == 4)
	check("poll: and nothing was ever called on a Blizzard frame to do it", #W.violations == 0)
end

-- 87. The fill helpers of Core, called as the modules call them.
do
	local W = FH.res(nil, { forbidden = { ["PRD.power"] = true } })
	local ns = W.ns
	local forbidden, health = W.prd.power[1], W.prd.health[1]
	check("fill helper: FillRegion gives nil for a forbidden bar without reading it", ns.FillRegion(forbidden) == nil and #W.violations == 0, FH.why(W))
	check("fill helper: FlatFill gives nil for a forbidden bar and RestoreFill has nothing to restore", ns.FlatFill(forbidden, 1, 0, 0) == nil and ns.RestoreFill(forbidden) == true and #W.violations == 0, FH.why(W))
	check("fill helper: FillRegion gives nil for what is not a frame", ns.FillRegion(nil) == nil and ns.FillRegion(5) == nil and ns.FillRegion("bar") == nil and ns.FillRegion(SECRET) == nil and ns.FillRegion({}) == nil)
	check("fill helper: FillRegion gives the region of a bar", ns.FillRegion(health) == W.prd.health[2].regions[2])
	-- A bar that is already flat: the same colour makes no call, another colour makes one.
	local before = FH.n(W, health, "SetColorFill")
	check("fill helper: FlatFill with the colour it has gives true and makes no call", ns.FlatFill(health, 1, 1, 1) == true and FH.n(W, health, "SetColorFill") == before)
	check("fill helper: FlatFill with another colour makes one call", ns.FlatFill(health, 0.2, 0.3, 0.4) == true and FH.n(W, health, "SetColorFill") == before + 1 and FH.fill(W, health) == "colour 0.200,0.300,0.400")
	check("fill helper: RestoreFill gives the atlas back and true", ns.RestoreFill(health) == true and FH.fill(W, health) == "atlas " .. FH.BAR_ATLAS and FH.n(W, health, "SetStatusBarTexture") == 1)
	check("fill helper: and a second RestoreFill does nothing", ns.RestoreFill(health) == true and FH.n(W, health, "SetStatusBarTexture") == 1)
	-- A bar whose fill does not say which atlas it draws needs the fallback.
	local alt = W.prd.alt[1]
	W.prd.alt[2].fillRaw.atlas = nil
	check("fill helper: with no atlas and no fallback FlatFill gives false and changes nothing", ns.FlatFill(alt, 1, 1, 1) == false and FH.changes(W, alt) == 0)
	check("fill helper: with a fallback it is flat", ns.FlatFill(alt, 1, 1, 1, "fallback-atlas") == true and FH.fill(W, alt) == "colour 1.000,1.000,1.000")
	ns.RestoreFill(alt)
	check("fill helper: and the fallback is what RestoreFill puts back", FH.fill(W, alt) == "atlas fallback-atlas")
	-- A fill region the game draws again with its own atlas is made flat again, and that atlas is the one put back.
	ns.FlatFill(alt, 1, 1, 1)
	W.prd.alt[2].fillRaw.atlas, W.prd.alt[2].fillRaw.color = "game-again", nil
	check("fill helper: an atlas found on a flat region gives a new SetColorFill with the same colour", ns.FlatFill(alt, 1, 1, 1) == true and FH.fill(W, alt) == "colour 1.000,1.000,1.000"
		and FH.n(W, alt, "SetColorFill") == 3, FH.n(W, alt, "SetColorFill"))
	ns.RestoreFill(alt)
	check("fill helper: and RestoreFill puts that atlas back", FH.fill(W, alt) == "atlas game-again")
	-- A refused restore keeps the record and gives false.
	ns.FlatFill(alt, 1, 1, 1)
	W.prd.alt[2].refuseTexture = true
	check("fill helper: RestoreFill gives false when the game refuses", ns.RestoreFill(alt) == false and FH.fill(W, alt) == "colour 1.000,1.000,1.000")
	W.prd.alt[2].refuseTexture = nil
	check("fill helper: and true when the game takes it", ns.RestoreFill(alt) == true and FH.fill(W, alt) == "atlas game-again")
	W.prd.alt[2].fault.setTexture = "error"
	ns.FlatFill(alt, 1, 1, 1)
	check("fill helper: RestoreFill gives false when the call raises", ns.RestoreFill(alt) == false)
	check("fill helper: nothing was written on a Blizzard object, nothing was printed", #W.violations == 0 and #W.errors == 0, FH.why(W))
	-- SetColorFill that raises.
	local X = FH.res()
	X.prd.health[2].fault.setColorFill = "error"
	check("fill helper: FlatFill gives false when SetColorFill raises, and the bar keeps its atlas", X.ns.FlatFill(X.prd.alt[1], 1, 0, 0) == true and X.ns.FlatFill(X.prd.health[1], 0.5, 0.5, 0.5) == false
		and FH.fill(X, X.prd.health[1]) == "colour 1.000,1.000,1.000")
end

-- 88. Withheld colours: where in the colour the withheld value is, and what the game gave that is not a number.
do
	local hex = FH.POWER_HEX
	local function num(i)
		return tonumber(hex:sub(i, i + 1), 16) / 255
	end
	local cr, cg, cb = num(3), num(5), num(7)
	for _, kind in ipairs({ "number", "string" }) do
		for at = 1, 4 do
			-- The channels before the withheld one match the custom colour, so that they are compared.
			local W = FH.res({ ["resource.powerOwn"] = true }, nil, function(X)
				X.secretType = kind
				local tint = { cr, cg, cb, 1 }
				tint[at] = SECRET
				X.prd.power[2].tint = tint
			end)
			W.frame(2)
			local power = W.prd.power[1]
			check("resource colour: value " .. at .. " withheld as a " .. kind .. " after matching channels is not compared, and the custom colour is set or kept", FH.plain(W) and not has(W.status(), "failed")
				and (at == 4 or FH.tint(W, power) == FH.hex(hex)), FH.why(W) .. W.status())
			W.change("resource.powerOwn", false)
			check("resource colour: value " .. at .. " withheld as a " .. kind .. ", nothing is stored, so nothing is given back and nothing is raised", FH.plain(W) and not has(W.status(), "failed")
				and (at == 4 or FH.tint(W, power) == FH.hex(hex)), FH.why(W) .. W.status())
		end
	end
	for at = 1, 4 do
		local W = FH.res({ ["resource.powerOwn"] = true }, nil, function(X)
			local tint = { cr, cg, cb, 1 }
			tint[at] = "0.5"
			X.prd.power[2].tint = tint
		end)
		W.frame(2)
		W.change("resource.powerOwn", false)
		check("resource colour: value " .. at .. " that is a string is not a colour", FH.plain(W) and not has(W.status(), "failed"), FH.why(W) .. W.status())
	end
end

-- 89. The withheld layer of a fill, the cover's colour objects, and a cover that cannot be hidden.
do
	for _, case in ipairs({
		{ "a layer that is withheld", "string", function() return SECRET, 0 end },
		{ "a sublevel that is withheld", "number", function() return "ARTWORK", SECRET end },
		{ "a layer that is a number", "table", function() return 5, 0 end },
		{ "a sublevel that is a string", "table", function() return "ARTWORK", "0" end },
		{ "a layer that is withheld and looks like a string", "string", function() return SECRET, 2 end },
	}) do
		local W = FH.cast(nil, nil, function(X)
			X.secretType = case[2]
			X.fills.cast[FH.PLAYER].inner.fillRaw.GetDrawLayer = case[3]
		end)
		W.fills.castStart(FH.PLAYER, "cast")
		W.frame(1)
		local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
		check("cast fill: GetDrawLayer gives " .. case[1] .. ", the cover is on ARTWORK 1", cover and cover.layer == "ARTWORK" and cover.sublevel == 1 and FH.plain(W), FH.why(W))
	end

	-- Colour objects are made again only when the colour changes.
	local W = FH.cast()
	W.secretTruth = true
	W.fills.castStart(FH.PLAYER, "channel", { secret = true, notInterruptible = true, secretShield = true })
	W.frame(1)
	local cover = FH.cover(W, FH.bar(W, FH.PLAYER))
	local yes, no = cover.fromBoolean.yes, cover.fromBoolean.no
	W.frame(3)
	check("cast withheld: the colour objects are the same objects on the next frames", cover.fromBoolean.yes == yes and cover.fromBoolean.no == no)
	W.change("castbars.shieldColour", "ff102030")
	W.frame(1)
	check("cast withheld: a changed colour makes a new object for that colour only", cover.fromBoolean.yes ~= yes and cover.fromBoolean.no == no)

	-- A state change with the same colour still paints, as the design says.
	local S = FH.cast({ ["castbars.channelColour"] = "ffe6b333" })
	S.fills.castStart(FH.PLAYER, "cast")
	S.frame(1)
	local c = FH.cover(S, FH.bar(S, FH.PLAYER))
	S.fills.castStart(FH.PLAYER, "channel")
	S.frame(1)
	check("cast fill: a change of state to a state with the same colour paints the cover", c.calls.SetVertexColor == 2 and FH.rgb(c.vertex) == FH.hex("ffe6b333"), tostring(c.calls.SetVertexColor))

	-- A cover that cannot be hidden when Flat fill goes off is counted for the bar and does not stop the module.
	local H = FH.cast()
	FH.castAll(H)
	FH.cover(H, FH.bar(H, FH.PLAYER)).Hide = function() error("hide failed", 0) end
	H.change("castbars.flat", false)
	check("cast failure: a cover that cannot be hidden is counted once, the module is not stopped and the other covers are hidden", has(H.line("Cast bars"), "1 failed. hide failed") and not H.ns.IsStopped("castbars")
		and FH.shownCovers(H) == 1, H.line("Cast bars"))

	-- A bar that is off is not painted, though the poll runs for something else.
	local P = FH.cast({ ["resource.powerOwn"] = true })
	FH.castAll(P)
	P.change("castbars.flat", false)
	P.fills.castInterrupt(FH.PLAYER)
	P.fills.castStart("PetCastingBarFrame", "channel")
	P.options()["castbars.castColour"] = "ff112233"
	P.frame(4)
	check("cast fill: with Flat fill off and the poll running for a custom colour the covers are not painted or shown", FH.shownCovers(P) == 0 and FH.cover(P, FH.bar(P, FH.PLAYER)).calls.SetVertexColor == 1
		and FH.cover(P, FH.bar(P, "PetCastingBarFrame")).calls.SetVertexColor == 1 and FH.polling(P))
	local N = FH.cast({ ["castbars.flat"] = false, ["resource.powerOwn"] = true })
	FH.castAll(N)
	N.frame(3)
	check("cast fill: and no cover is made for a bar that never had Flat fill on", FH.allCovers(N) == 0 and FH.polling(N))

	-- A spark that is gone and a bar that finished: the withheld cases that need the spark to exist.
	local F = FH.cast()
	F.fills.castStart(FH.PLAYER, "cast", { secret = true })
	F.frame(1)
	F.fills.castFinish(FH.PLAYER, true)
	F.rawOf[FH.bar(F, FH.PLAYER)].Spark = nil
	F.frame(2)
	check("cast withheld: a bar that finished and has no spark is the cast colour, with nothing raised", FH.shownColour(F, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(F) and not has(F.status(), "failed"), FH.why(F) .. F.status())
	F.fills.castInterrupt(FH.PLAYER, true)
	F.rawOf[FH.bar(F, FH.PLAYER)].Spark = F.fills.cast[FH.PLAYER].spark
	F.fills.cast[FH.PLAYER].sparkRaw.fault.shown = "error"
	F.frame(2)
	check("cast withheld: a spark whose IsShown fails is not taken for shown", FH.shownColour(F, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(F), FH.why(F))
end

-- 90. A swing timer the game refuses to put back, and bars with no fill region.
do
	local W = FH.world()
	local main = W.fills.swing.SwingTimerMainHandFrame
	main.barRaw.refuseTexture = true
	W.change("swing.flat", false)
	check("swing restore: when the game refuses, the fill stays and /flatui status says so once", FH.fill(W, main.bar) == "colour " .. FH.hex("ffd9a640")
		and count(W.status(), "Swing timers: the game refused to put back the default fill of a timer.") == 1 and main.pipRaw.alpha == 1, W.status())
	main.barRaw.refuseTexture = nil
	W.change("swing.backdrop", false)
	check("swing restore: and the next Refresh puts it back", FH.fill(W, main.bar) == "atlas " .. main.atlas)
	local X = FH.res(nil, nil, function(Y)
		for _, pair in pairs(Y.prd) do
			pair[2].fault.fillRegion = "nothing"
		end
	end)
	check("resource fill: bars with no fill region are left alone, with no line in /flatui status", not has(X.status(), "could not be read") and FH.plain(X) and not has(X.status(), "failed"), X.status())
	-- A swing bar that has become forbidden since it was made flat is not read, not restored and not noted.
	local G = FH.world()
	local gmain = G.fills.swing.SwingTimerMainHandFrame
	gmain.barRaw.forbidden = true
	G.change("swing.flat", false)
	G.change("swing.mainColour", "ff336699")
	check("swing restore: a bar that has become forbidden is left as it is, with no read and no line in /flatui status", #G.violations == 0 and #G.errors == 0 and not has(G.status(), "refused")
		and gmain.fillRaw.color ~= nil and FH.n(G, gmain.bar, "SetStatusBarTexture") == 0, FH.why(G) .. G.status())
	-- A resource bar that is not flat when the game gives it no fill, then does.
	local Z = FH.res(nil, nil, function(Y)
		Y.prd.power[2].fault.fillRegion = "nothing"
	end)
	Z.prd.power[2].fault.fillRegion = nil
	Z.change("resource.join", false)
	check("resource fill: and the fill is made on the Refresh after the game gives it", FH.fill(Z, Z.prd.power[1]) == "colour 1.000,1.000,1.000")
end

-- 91. Fixes made after the review of the fills.
-- 91a. An error in the flat fill of cast bars stops that fill and not the module the bars belong to.
do
	local W = FH.cast({ ["castbars.flat"] = false })
	local names, plates, covers = {}, {}, {}
	for i = 1, 5 do
		names[i] = "Plate" .. (20 + i) .. "CastBar"
		plates[i] = W.fills.newCastBar(names[i])
		W.ns.CastFill("nameplates", plates[i], true)
		W.fills.castStart(names[i], "cast")
	end
	W.frame(1)
	for i = 1, 5 do
		covers[i] = FH.cover(W, plates[i])
	end
	local function shown()
		local n = 0
		for i = 1, 5 do
			n = n + (covers[i].shown and 1 or 0)
		end
		return n
	end
	check("fill failure: five nameplate cast bars each have a cover", shown() == 5 and FH.polling(W))
	for i = 1, 2 do
		covers[i].SetVertexColor = function() error("paint failed", 0) end
	end
	W.options()["castbars.castColour"] = "ff102030"
	W.frame(4)
	check("fill failure: two bars that fail, however often they are tried, do not stop the cast bar fill and are given back", not W.ns.PartStopped("nameplates", "cast bar fill") and shown() == 3)
	for i = 3, 5 do
		covers[i].SetVertexColor = function() error("paint failed", 0) end
	end
	W.options()["castbars.castColour"] = "ff405060"
	W.frame(3)
	check("fill failure: the third bar that fails stops the cast bar fill of the nameplates, with the first error", W.ns.PartStopped("nameplates", "cast bar fill")
		and not W.ns.PartStopped("nameplates", "flat fill") and count(W.status(), "Nameplates: cast bar fill stopped. paint failed") == 1, W.status())
	check("fill failure: five bars that fail do not stop the nameplates, and one line is printed", not W.ns.IsStopped("nameplates") and #W.out == 1
		and W.out[1] == "Flat UI: cast bar fill stopped in Nameplates. /flatui status shows why." and has(W.status(), "Nameplates: on, 0 styled")
		and not has(W.line("Nameplates"), "failed"), W.status() .. table.concat(W.out, "|"))
	W.out = {}
	check("fill failure: the Cast bars are not touched by it", not W.ns.PartStopped("castbars", "flat fill") and not W.ns.IsStopped("castbars") and not has(W.status(), "Cast bars: flat fill"))
	check("fill failure: every cover is hidden and nothing polls", shown() == 0 and not FH.polling(W))
	W.ns.CastFill("nameplates", plates[1], true)
	W.fills.castStart(names[1], "channel")
	W.frame(3)
	check("fill failure: a bar asked for again gets no cover while the cast bar fill is stopped, and the poll does not stay set", shown() == 0 and not FH.polling(W))
	check("fill failure: no violation, no message", #W.violations == 0 and #W.errors == 0 and #W.out == 0, FH.why(W))

	-- The five cast bars: their borders stay.
	local X = FH.cast()
	FH.castAll(X)
	for _, name in ipairs(FH.CASTS) do
		FH.cover(X, FH.bar(X, name)).SetVertexColor = function() error("paint failed", 0) end
	end
	X.change("castbars.castColour", "ff102030")
	X.frame(3)
	check("fill failure: five cast bars that fail stop the flat fill and not the module, with the first error", X.ns.PartStopped("castbars", "flat fill") and not X.ns.IsStopped("castbars")
		and has(X.status(), "Cast bars: flat fill stopped. paint failed") and #X.out == 1 and X.out[1] == "Flat UI: flat fill stopped in Cast bars. /flatui status shows why.", X.status() .. table.concat(X.out, "|"))
	X.out = {}
	check("fill failure: so the borders of the cast bars stay", X.state(FH.bar(X, FH.PLAYER)) == "SB" and X.state(FH.bar(X, "FocusFrameSpellBar")) == "SB")
	check("fill failure: and every cover is hidden and nothing polls", FH.shownCovers(X) == 0 and not FH.polling(X))
	X.change("castbars.castColour", "ff405060")
	X.change("castbars.flat", false)
	X.change("castbars.flat", true)
	check("fill failure: Flat fill on again asks for no fill while it is stopped, so nothing polls", not FH.polling(X) and not X.ns.PartStopped("castbars", "cast bar fill"))
	X.frame(3)
	check("fill failure: Flat fill off and on again does not bring the stopped fill back", FH.shownCovers(X) == 0 and X.ns.PartStopped("castbars", "flat fill") and #X.violations == 0 and #X.errors == 0 and #X.out == 0, FH.why(X))
	check("fill failure: the resource and swing fills go on", FH.fill(X, X.prd.power[1]) == "colour 1.000,1.000,1.000" and not X.ns.IsStopped("swing"))

	-- Failures are charged to the module that asked for the bars.
	local Y = FH.cast({ ["castbars.flat"] = false })
	local ycovers = {}
	for i = 1, 3 do
		local name = "Plate" .. (30 + i) .. "CastBar"
		local bar = Y.fills.newCastBar(name)
		Y.ns.CastFill("castbars", bar, true)
		Y.fills.castStart(name, "cast")
		Y.frame(1)
		ycovers[i] = FH.cover(Y, bar)
		ycovers[i].SetVertexColor = function() error("paint failed", 0) end
	end
	Y.options()["castbars.castColour"] = "ff102030"
	Y.frame(2)
	check("fill failure: bars asked for by the Cast bars stop the flat fill of the Cast bars and not the nameplates", Y.ns.PartStopped("castbars", "flat fill") and not Y.ns.PartStopped("nameplates", "cast bar fill") and not Y.ns.PartStopped("nameplates", "flat fill")
		and has(Y.status(), "Cast bars: flat fill stopped. paint failed"), Y.status())
end

-- 91b. A module or a page that is off or stopped gives back the look of the cast bars it asked for, whether or not it did so itself.
do
	local W = FH.cast({ ["castbars.flat"] = false })
	local bar = W.fills.newCastBar("Plate40CastBar")
	W.ns.CastFill("nameplates", bar, true)
	W.fills.castStart("Plate40CastBar", "cast")
	W.frame(1)
	local cover = FH.cover(W, bar)
	check("cast fill: a nameplate bar has its cover shown while the nameplates are on", cover.shown and FH.polling(W))
	W.ns.Try("nameplates", function() error("probe", 0) end)
	W.frame(1)
	check("cast fill: a nameplates module that has stopped hides the cover on the next frame and the poll is cleared", cover.shown == false and not FH.polling(W))
	W.fills.castStart("Plate40CastBar", "channel")
	W.frame(3)
	check("cast fill: and a later cast on that bar gets no paint", cover.shown == false and cover.calls.SetVertexColor == 1 and #W.violations == 0 and #W.errors == 0 and not has(W.line("Nameplates"), "failed"), FH.why(W) .. W.status())

	local X = FH.cast({ ["castbars.flat"] = false })
	local bar2 = X.fills.newCastBar("Plate41CastBar")
	X.ns.CastFill("nameplates", bar2, true)
	X.fills.castStart("Plate41CastBar", "cast")
	X.frame(1)
	local cover2 = FH.cover(X, bar2)
	X.change("nameplates.enabled", false)
	X.frame(1)
	check("cast fill: the nameplates page off hides the cover on the next frame and the poll is cleared", cover2.shown == false and not FH.polling(X) and FH.plain(X), FH.why(X))
	X.ns.CastFill("nameplates", bar2, true)
	X.frame(3)
	check("cast fill: and a bar asked for while the page is off is not shown", cover2.shown == false and not FH.polling(X))

	-- A bar that is forbidden when it is dropped is not called.
	local Y = FH.cast({ ["castbars.flat"] = false })
	local bar3, inner3 = Y.fills.newCastBar("Plate42CastBar")
	Y.ns.CastFill("nameplates", bar3, true)
	Y.fills.castStart("Plate42CastBar", "cast")
	Y.frame(1)
	local cover3 = FH.cover(Y, bar3)
	inner3.forbidden = true
	Y.change("nameplates.enabled", false)
	Y.frame(2)
	check("cast fill: a bar that has become forbidden is not read or called when its module stops, and the poll is cleared", cover3.shown == true and #Y.violations == 0 and #Y.errors == 0 and not FH.polling(Y), FH.why(Y))
end

-- 91c. A withheld alpha is tested before it is compared. The simulated withheld value cannot raise on ==, so the order of the tests is what is
-- checked: the first value asked about after each read of the colour is the alpha.
do
	local log = {}
	local W = FH.res({ ["resource.powerOwn"] = true }, nil, function(X)
		X.prd.power[2].GetStatusBarColor = function()
			log[#log + 1] = "read"
			return 0.1, 0.2, 0.3, SECRET
		end
		local was = X.env.issecretvalue
		X.env.issecretvalue = function(v)
			log[#log + 1] = rawequal(v, SECRET) and "secret" or "plain"
			return was(v)
		end
	end)
	W.frame(3)
	local reads, first = 0, true
	for i, entry in ipairs(log) do
		if entry == "read" then
			reads = reads + 1
			first = first and log[i + 1] == "secret"
		end
	end
	check("resource colour: the withheld alpha is the first value tested after each read of the colour", reads >= 3 and first, reads .. " " .. tostring(first))
	check("resource colour: and the custom colour is still set", FH.tint(W, W.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.plain(W) and not has(W.status(), "failed"), FH.why(W) .. W.status())
	W.change("resource.powerOwn", false)
	check("resource colour: a colour with a withheld alpha is not the game's, so switching the custom colour off puts nothing back", FH.tint(W, W.prd.power[1]) == FH.hex(FH.POWER_HEX) and FH.plain(W), FH.why(W))
end

-- 91d. A resource bar the game makes forbidden is dropped from the follow without being read, and the other bar goes on.
do
	local W = FH.res({ ["resource.powerOwn"] = true, ["resource.healthOwn"] = true })
	local health, power = FH.bars(W)
	W.frame(2)
	W.prd.power[2].forbidden = true
	W.frame(3)
	check("resource forbidden: a bar that becomes forbidden is neither read nor called, and nothing is counted as failed", #W.violations == 0 and #W.errors == 0 and not has(W.status(), "failed"), FH.why(W) .. W.status())
	W.fills.showClassColour(true)
	W.frame(1)
	check("resource forbidden: the other bar is still followed", FH.polling(W) and FH.tint(W, health) == FH.hex(FH.HEALTH_HEX) and #W.violations == 0, FH.why(W))
	W.prd.health[2].forbidden = true
	W.frame(2)
	check("resource forbidden: the frame that follows colours is cleared with the last bar", not FH.polling(W) and #W.violations == 0, FH.why(W))
	W.prd.power[2].forbidden = false
	W.change("resource.join", false)
	W.change("resource.join", true)
	W.fills.setPower("RAGE")
	W.frame(2)
	check("resource forbidden: a bar that is allowed again is followed after the next Refresh", FH.tint(W, power) == FH.hex(FH.POWER_HEX) and FH.polling(W))
end

-- 91e. A channel that has ended keeps its colour while the bar fades, when the game withholds the name of the fill.
do
	local function ended(first, second)
		local W = FH.cast()
		W.fills.castStart(FH.PLAYER, first, { secret = true })
		W.frame(1)
		if second then
			second(W)
		end
		W.frame(2)
		return W
	end
	local W = ended("channel", function(X)
		X.fills.castFinish(FH.PLAYER, true)
	end)
	check("cast withheld: a channel that finished is still the channel colour", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.channel) and FH.plain(W), FH.shownColour(W, FH.PLAYER) .. FH.why(W))
	W.fills.castStart(FH.PLAYER, "cast", { secret = true })
	W.frame(1)
	check("cast withheld: the next cast is the cast colour", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	W.fills.castFinish(FH.PLAYER, true)
	W.frame(2)
	check("cast withheld: and a cast that finished after a channel is the cast colour", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	local X = ended("channel", function(Y)
		Y.fills.castInterrupt(FH.PLAYER, true)
	end)
	check("cast withheld: a channel that was interrupted is the interrupted colour", FH.shownColour(X, FH.PLAYER) == FH.hex(FH.CAST_HEX.interrupted))
	local Z = ended("channel", function(Y)
		Y.fills.castFinish(FH.PLAYER, true)
		Y.fills.castInterruptible(FH.PLAYER, true, true)
	end)
	check("cast withheld: a channel that finished and shows a shield is the uninterruptible colour", FH.shownColour(Z, FH.PLAYER) == FH.hex(FH.CAST_HEX.shield))
	-- A bar that never cast has no kind to remember.
	local N = FH.cast()
	N.fills.castStart(FH.PLAYER, "cast", { secret = true })
	N.fills.castFinish(FH.PLAYER, true)
	N.frame(2)
	check("cast withheld: a cast that finished before any frame saw it is the cast colour", FH.shownColour(N, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	-- Each bar remembers its own.
	local P = FH.cast()
	P.fills.castStart(FH.PLAYER, "channel", { secret = true })
	P.fills.castStart("PetCastingBarFrame", "cast", { secret = true })
	P.frame(1)
	P.fills.castFinish(FH.PLAYER, true)
	P.fills.castFinish("PetCastingBarFrame", true)
	P.frame(2)
	check("cast withheld: each bar keeps the kind of its own cast", FH.shownColour(P, FH.PLAYER) == FH.hex(FH.CAST_HEX.channel) and FH.shownColour(P, "PetCastingBarFrame") == FH.hex(FH.CAST_HEX.cast))
end

-- 91f. A cover is laid over the fill only while the fill is shown.
do
	local W = FH.cast()
	local P = FH.bar(W, FH.PLAYER)
	W.fills.castStart(FH.PLAYER, "cast")
	W.frame(1)
	local fill = W.rawOf[P].fillRaw
	local cover = FH.cover(W, P)
	check("cast fill: a cast shows the cover over a fill that is shown", cover.shown and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast))
	fill.shown = false
	W.frame(1)
	check("cast fill: a fill that the game has hidden has the cover hidden with it", cover.shown == false and FH.shownColour(W, FH.PLAYER) == "-")
	W.frame(4)
	check("cast fill: and no call is made on later frames", cover.calls.Hide == 2 and cover.calls.Show == 1 and cover.calls.SetVertexColor == 1)
	fill.shown = true
	W.frame(1)
	check("cast fill: the cover is shown again with the fill", FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast))
	for _, case in ipairs({ { "withheld", "secret" }, { "an error", "error" }, { "a string", "string" } }) do
