-- 75. Movers, tooltip position and cast bar size: the simulated client.
-- A world gets what these three parts need when it asks for it (opts.layout, or opts.layout = { ... }); every
-- section above runs on the world it ran on before. Added to the client:
--   rectangles worked out from the anchors, so GetRect answers what the engine would, for frames and regions;
--   widget calls of an addon's own frames: scripts, mouse, dragging, font strings, OnUpdate (W.update, W.run);
--   Edit Mode system frames whose SetPoint, ClearAllPoints, SetScale, Hide and SetShown are Lua overrides
--   (EditModeSystemMixin:OnSystemLoad), managed containers, plain Blizzard frames from the fixed list, windows
--   that the panel manager places and announces on EventRegistry, GetMouseFoci, keys, the cursor and GetTime;
--   GameTooltip with owner and anchor type, GameTooltip_SetDefaultAnchor as Blizzard writes it, the world
--   cursor event; the cast bars with Spark, Text and BorderMask, SetLook, and the two PlayerFrame globals.
-- Corrected in the client: regions answer IsForbidden (every widget does), and hooksecurefunc takes the form
-- hooksecurefunc("name", hook) that the game offers for a global function.
-- The helpers of the suite below that the sections after it use.
local suiteKit
-- >>> movers, tooltip and cast bar size (begin)
do
local function suite()

local FRAC = { TOPLEFT = { 0, 1 }, TOP = { 0.5, 1 }, TOPRIGHT = { 1, 1 }, LEFT = { 0, 0.5 }, CENTER = { 0.5, 0.5 }, RIGHT = { 1, 0.5 },
	BOTTOMLEFT = { 0, 0 }, BOTTOM = { 0.5, 0 }, BOTTOMRIGHT = { 1, 0 } }
local STRATA = { BACKGROUND = true, LOW = true, MEDIUM = true, HIGH = true, DIALOG = true, FULLSCREEN = true, FULLSCREEN_DIALOG = true, TOOLTIP = true }

-- A Lua method of Blizzard's: only Blizzard's own code may call it.
local function lua(W, name, fn)
	return function(...)
		if W.inBlizzard == 0 then
			bad(W, "the addon called the Blizzard method " .. name)
		end
		return fn(...)
	end
end

-- A read the client answers with an error, a withheld value or a value of the wrong type (f.fault[which]).
local function answer(f, which, ...)
	local fault = f.fault[which]
	if fault == "error" then
		error(which .. " failed", 0)
	elseif fault == "secret" then
		return SECRET
	elseif fault == "secretFirst" then
		return SECRET, select(2, ...)
	elseif fault == "string" then
		return "x"
	end
	return ...
end

-- The effective scale of a frame or region, worked out from the chain of parents.
local function effScale(W, obj)
	if obj.isRegion then
		local owner = obj.owner and W.rawOf[obj.owner]
		return owner and effScale(W, owner) or 1
	end
	if obj == W.uiInner then
		return obj.scale
	end
	if obj.ignoreParentScale then
		return obj.scale
	end
	local parent = obj.parent and W.rawOf[obj.parent]
	return obj.scale * (parent and effScale(W, parent) or W.uiInner.scale)
end

-- Left, bottom, width and height of a frame or region in screen units (those of GetCursorPosition), or nil when it has no place.
local function place(W, obj, depth)
	depth = depth or 0
	if obj == nil or depth > 80 then
		return nil
	end
	if obj == W.uiInner then
		return 0, 0, W.height * 16 / 9, W.height
	end
	if obj.allPoints then
		return place(W, W.rawOf[obj.allPoints], depth + 1)
	end
	if #obj.points == 0 then
		return nil
	end
	local e = effScale(W, obj)
	local xs, ys = {}, {}
	for _, p in ipairs(obj.points) do
		local l, b, w, h = place(W, W.rawOf[p[2]], depth + 1)
		if not l then
			return nil
		end
		local at, mine = FRAC[p[3] or p[1]], FRAC[p[1]]
		xs[#xs + 1] = { mine[1], l + w * at[1] + (p[4] or 0) * e }
		ys[#ys + 1] = { mine[2], b + h * at[2] + (p[5] or 0) * e }
	end
	local function axis(list, size)
		local first, second = list[1], nil
		for i = 2, #list do
			if list[i][1] ~= first[1] then
				second = list[i]
				break
			end
		end
		if second then
			local span = (second[2] - first[2]) / (second[1] - first[1])
			return first[2] - first[1] * span, span
		end
		return first[2] - first[1] * size, size
	end
	local left, width = axis(xs, (obj.width or 0) * e)
	local bottom, height = axis(ys, (obj.height or 0) * e)
	return left, bottom, width, height
end

local function visible(W, f)
	for _ = 1, 30 do
		if f == nil then
			return true
		end
		if f.shown == false then
			return false
		end
		f = f.parent and W.rawOf[f.parent]
	end
	return true
end

-- Widget calls a Blizzard frame has and an addon must never make on one. HookScript writes nothing on the frame
-- (EllesmereUIChat/EllesmereUIChat.lua:4410-4417), so FH.hookable frames take it, for the one script each is listed with, and every other frame never does.
local NEVER = { "Show", "Hide", "SetShown", "SetParent", "SetFrameStrata", "StartMoving", "StopMovingOrSizing", "SetMovable", "EnableMouse", "EnableMouseWheel",
	"RegisterForDrag", "SetClampedToScreen", "SetScript" }

-- The one script of each frame of the game's that the addon follows with HookScript: the size of the bags bar, the two status containers and the tracker
-- modules, and the event script of the buff frame and of the status bar manager.
local HOOKABLE = { BagsBar = "OnSizeChanged", MainStatusTrackingBarContainer = "OnSizeChanged", SecondaryStatusTrackingBarContainer = "OnSizeChanged",
	BuffFrame = "OnEvent", StatusTrackingBarManager = "OnEvent" }
for _, name in ipairs({ "ScenarioObjectiveTracker", "UIWidgetObjectiveTracker", "CampaignQuestObjectiveTracker", "QuestObjectiveTracker", "AdventureObjectiveTracker",
	"AchievementObjectiveTracker", "MonthlyActivitiesObjectiveTracker", "InitiativeTasksObjectiveTracker", "ProfessionsRecipeTracker", "BonusObjectiveTracker", "WorldQuestObjectiveTracker" }) do
	HOOKABLE[name] = "OnSizeChanged"
end

-- Counts what the addon calls on a frame or region of the game's, under raw.addon[name].
local function watch(W, raw, names)
	raw.addon = raw.addon or {}
	for _, name in ipairs(names) do
		local base = raw[name]
		raw[name] = function(...)
			if W.inBlizzard == 0 then
				raw.addon[name] = (raw.addon[name] or 0) + 1
			end
			return base(...)
		end
	end
end

local function extendRegion(W, r)
	function r.GetRect()
		local l, b, w, h = place(W, r)
		if not l then
			return nil
		end
		local e = effScale(W, r)
		return l / e, b / e, w / e, h / e
	end
	function r.IsForbidden()
		local o = r.owner and W.rawOf[r.owner]
		return o ~= nil and o.forbidden == true
	end
	-- Regions answer these too (SimpleScriptRegionAPI).
	function r.IsAnchoringRestricted() return false end
	function r.IsAnchoringSecret() return false end
	function r.IsProtected() return false, false end
	if r.kind == "FontString" then
		function r.SetText(_, text)
			if type(text) ~= "string" then
				bad(W, "SetText: a string is expected")
			end
			r.text = text
		end
		function r.GetText() return r.text end
		function r.SetJustifyH(_, v)
			if v ~= "LEFT" and v ~= "RIGHT" and v ~= "CENTER" then
				bad(W, "SetJustifyH: " .. tostring(v))
			end
			r.justify = v
		end
		function r.SetFontObject(_, o) r.fontObject = o end
	end
end

local function extendFrame(W, f, self)
	local blizz = f.group ~= nil
	f.scripts, f.fonts = {}, {}
	local createTexture = f.CreateTexture
	function f.CreateTexture(...)
		local t = createTexture(...)
		extendRegion(W, t)
		return t
	end
	function f.CreateFontString(_, name, layer, template)
		if name ~= nil or not LAYERS[layer] or (template ~= nil and type(template) ~= "string") then
			bad(W, "CreateFontString arguments")
		end
		local t = newRegion(W, self, { kind = "FontString", protected = f.protected })
		t.layer, t.addon, t.template = layer, true, template
		f.regions[#f.regions + 1] = t
		f.fonts[#f.fonts + 1] = t
		extendRegion(W, t)
		return t
	end
	function f.SetScript(_, which, fn)
		if type(which) ~= "string" or (fn ~= nil and type(fn) ~= "function") then
			bad(W, "SetScript arguments")
		end
		f.scripts[which] = fn
		if which == "OnEvent" then
			f.script = fn
		end
	end
	function f.GetScript(_, which) return answer(f, "getScript", f.scripts[which]) end
	-- Read-only, so a game frame answers them to the addon too: whether a script is set, and whether the frame takes mouse clicks (f.clicks).
	function f.HasScript(_, which) return answer(f, "hasScript", f.scripts[which] ~= nil) end
	function f.IsMouseClickEnabled() return answer(f, "clicks", f.clicks ~= false) end
	-- Region:IsMouseOver (WidgetAPI.lua:107): whether the cursor, at W.cursor in the units of UIParent, is inside the frame.
	function f.IsMouseOver()
		local l, b, w, h = W.rectOf(f)
		local x, y = W.cursor[1], W.cursor[2]
		return answer(f, "mouseOver", l ~= nil and x >= l and x <= l + w and y >= b and y <= b + h)
	end
	function f.HookScript(_, which, fn)
		if type(which) ~= "string" or type(fn) ~= "function" then
			bad(W, "HookScript arguments")
		end
		f.scripts[which .. ":hook"] = fn
		-- Every function hooked on a script is kept, for W.hookRun.
		f.hookScripts = f.hookScripts or {}
		f.hookScripts[which] = f.hookScripts[which] or {}
		table.insert(f.hookScripts[which], fn)
	end
	local function flag(name, key)
		f[name] = function(_, v)
			if type(v) ~= "boolean" then
				bad(W, name .. ": a boolean is expected")
			end
			f[key] = v
		end
	end
	flag("EnableMouse", "mouse")
	flag("EnableMouseWheel", "wheel")
	flag("SetMovable", "movable")
	flag("SetClampedToScreen", "clamped")
	-- The clamp the game gives its own system frames: f.clamped, and f.clampInsets = { left, right, top, bottom } (zero when unset).
	function f.IsClampedToScreen() return f.clamped == true end
	function f.GetClampRectInsets()
		local insets = f.clampInsets or { 0, 0, 0, 0 }
		return insets[1], insets[2], insets[3], insets[4]
	end
	function f.RegisterForDrag(_, ...) f.drag = { ... } end
	function f.SetFrameStrata(_, s)
		if not STRATA[s] then
			bad(W, "SetFrameStrata: " .. tostring(s))
		end
		f.strata = s
	end
	function f.GetFrameStrata() return f.strata or "MEDIUM" end
	function f.SetFrameLevel(_, level) f.level = level end
	function f.StartMoving()
		if f.movable then
			f.moving = true
		end
	end
	function f.StopMovingOrSizing() f.moving = false end
	function f.IsVisible() return visible(W, f) end
	function f.IsAnchoringRestricted() return answer(f, "restricted", f.restricted == true) end
	function f.IsAnchoringSecret() return answer(f, "anchoringSecret", f.anchoringSecret == true) end
	function f.IsProtected()
		local explicit = f.explicit
		if explicit == nil then
			explicit = f.protected == true
		end
		return answer(f, "protected", f.protected == true, explicit)
	end
	function f.GetScale() return answer(f, "scale", f.scale) end
	function f.GetRect()
		local fault = f.fault.rect
		if fault == "error" then
			error("GetRect failed", 0)
		end
		local l, b, w, h = place(W, f)
		if not l then
			return nil
		end
		local e = effScale(W, f)
		return answer(f, "rect", l / e, b / e, w / e, h / e)
	end
	function f.GetNumPoints()
		if W.numPointsFault == "error" then
			error("GetNumPoints failed", 0)
		elseif W.numPointsFault == "secret" then
			return SECRET
		end
		return answer(f, "numPoints", #f.points)
	end
	local getPoint = f.GetPoint
	function f.GetPoint(_, index)
		local fault = f.fault.point
		if fault == "error" then
			error("GetPoint failed", 0)
		end
		local point, relativeTo, relativePoint, x, y = getPoint(_, index)
		if point == nil then
			return nil
		end
		if fault == "secret" then
			return SECRET, SECRET, SECRET, SECRET, SECRET
		elseif fault == "secretPoint" then
			return SECRET, relativeTo, relativePoint, x, y
		elseif fault == "secretRelative" then
			return point, SECRET, relativePoint, x, y
		elseif fault == "secretX" then
			return point, relativeTo, relativePoint, SECRET, y
		elseif fault == "string" then
			return point, relativeTo, relativePoint, "x", y
		end
		return point, relativeTo, relativePoint, x, y
	end
	function f.GetName() return answer(f, "name", f.name) end
	function f.GetEffectiveScale()
		if f.fault.effScale == "error" then
			error("GetEffectiveScale failed", 0)
		elseif f.fault.effScale == "secret" then
			return SECRET
		elseif f.fault.effScale == "zero" then
			return 0
		end
		return effScale(W, f)
	end
	if blizz then
		for _, name in ipairs(NEVER) do
			local base = f[name]
			f[name] = function(_, which, ...)
				if W.inBlizzard == 0 and not (name == "HookScript" and HOOKABLE[f.name] == which) then
					bad(W, "the addon called " .. name .. " on a Blizzard frame " .. tostring(f.name))
				end
				if base then
					return base(_, which, ...)
				end
			end
		end
		-- HookScript writes nothing on the frame (the doctrine of EllesmereUI: HookScript, events and the game's own API are fine): the hooks are kept in
		-- f.scriptHooks, run by W.fireScript, and counted in W.scriptHooks.
		function f.HookScript(_, which, fn)
			if type(which) ~= "string" or type(fn) ~= "function" then
				bad(W, "HookScript arguments")
			end
			f.scriptHooks = f.scriptHooks or {}
			f.scriptHooks[which] = f.scriptHooks[which] or {}
			table.insert(f.scriptHooks[which], fn)
			f.hookScripts = f.hookScripts or {}
			f.hookScripts[which] = f.hookScripts[which] or {}
			table.insert(f.hookScripts[which], fn)
			W.scriptHooks = (W.scriptHooks or 0) + 1
		end
	end
end

local function mworld(opts)
	opts = opts or {}
	local layout = opts.layout
	if type(layout) ~= "table" then
		layout = {}
	end
	opts.layout = layout
	local W = newWorld(opts)
	-- The game laid its frames out before the player was in combat.
	local inCombat = W.combat
	W.combat = false
	local env, ui = W.env, W.env.UIParent
	W.updaters = {}
	W.cursor = { 0, 0 }
	W.keys = {}
	W.foci = {}

	-- The client -------------------------------------------------------------------------------------
	-- hooksecurefunc("name", hook) hooks the global function of that name. A hook is the addon's own code, so it runs
	-- outside Blizzard's, whoever called the function it follows.
	local hook = env.hooksecurefunc
	local function asAddon(fn)
		if type(fn) ~= "function" then
			return fn
		end
		return function(...)
			local was = W.inBlizzard
			W.inBlizzard = 0
			local ok, err = pcall(fn, ...)
			W.inBlizzard = was
			if not ok then
				error(err, 0)
			end
		end
	end
	env.hooksecurefunc = function(a, b, c)
		if type(a) == "string" then
			if type(b) ~= "function" then
				bad(W, "hooksecurefunc arguments")
			end
			return hook(env, a, asAddon(b))
		end
		return hook(a, b, asAddon(c))
	end
	local createFrame = env.CreateFrame
	-- The state of the mouse buttons: a script of an addon's frame for a press runs when the player presses, and one for a release when
	-- the player lets go, so the client says the button is down from the first until the second.
	W.mouse = { LeftButton = false, RightButton = false }
	env.CreateFrame = function(kind, name, parent, template)
		local frame = createFrame(kind, name, parent, template)
		extendFrame(W, W.rawOf[frame], frame)
		W.updaters[#W.updaters + 1] = W.rawOf[frame]
		local setScript = frame.SetScript
		frame.SetScript = function(self, which, fn)
			if (which == "OnMouseDown" or which == "OnMouseUp") and type(fn) == "function" then
				local inner = fn
				fn = function(me, button, ...)
					W.mouse[button] = which == "OnMouseDown"
					return inner(me, button, ...)
				end
			end
			return setScript(self, which, fn)
		end
		return frame
	end
	env.GetTime = function() return W.now end
	env.IsMouseButtonDown = function(button) return W.mouse[button] == true end
	-- What the cursor holds: nil, or the kind of thing (W.held).
	env.GetCursorInfo = function() return W.held end
	env.GetCursorPosition = function()
		if W.cursorFault == "secret" then
			return SECRET, SECRET
		elseif W.cursorFault == "error" then
			error("GetCursorPosition failed", 0)
		end
		return W.cursor[1], W.cursor[2]
	end
	env.IsShiftKeyDown = function() return W.keys.shift == true end
	env.IsAltKeyDown = function() return W.keys.alt == true end
	env.IsControlKeyDown = function() return W.keys.ctrl == true end
	env.GetMouseFoci = function()
		if W.fociFault == "error" then
			error("GetMouseFoci failed", 0)
		elseif W.fociFault == "secret" then
			return SECRET
		end
		-- With W.mouseBoxes a shown box that takes the mouse is the frame under the cursor, as in the client, where the frame on top of the
		-- frames that take the mouse gets it.
		if W.mouseBoxes then
			for _, f in ipairs(W.handles()) do
				local left, bottom, width, height = W.rectOf(f)
				if f.shown and f.mouse and left and W.cursor[1] >= left and W.cursor[1] <= left + width and W.cursor[2] >= bottom and W.cursor[2] <= bottom + height then
					return { f }
				end
			end
		end
		return W.foci
	end
	env.C_AddOns = { GetAddOnMetadata = W.addOnMetadata, IsAddOnLoaded = function(name)
		if type(name) ~= "string" then
			bad(W, "IsAddOnLoaded: a name is expected")
		end
		return W.loadedAddons[name] == true
	end }
	W.loadedAddons = {}
	env.UIPanelWindows = {}

	-- UIParent has the size of the screen in its own units.
	local uiSize = function()
		local e = ui.GetEffectiveScale()
		return W.height * 16 / 9 / e, W.height / e
	end
	function W.uiInner.GetSize()
		if W.uiSizeFault == "error" then
			error("GetSize failed", 0)
		elseif W.uiSizeFault == "secret" then
			return SECRET, SECRET
		elseif W.uiSizeFault == "zero" then
			return 0, 0
		end
		return uiSize()
	end
	function W.uiInner.GetWidth() return (uiSize()) end
	function W.uiInner.GetHeight() return (select(2, uiSize())) end
	local getScale = W.uiInner.GetScale
	extendFrame(W, W.uiInner, ui)
	W.uiInner.GetScale = getScale

	-- EventRegistry: the registrant is the first argument of the callback (CallbackRegistry.lua, TriggerEvent).
	local registry = { callbacks = {} }
	function registry:RegisterCallback(event, func, owner)
		if type(event) ~= "string" then
			error("CallbackRegistryMixin::RegisterCallback 'event' requires string type.", 0)
		elseif type(func) ~= "function" then
			error("CallbackRegistryMixin::RegisterCallback 'func' requires function type.", 0)
		elseif type(owner) == "number" then
			error("CallbackRegistryMixin:RegisterCallback 'owner' as number is reserved internally.", 0)
		end
		if registry.failRegister then
			error("RegisterCallback failed", 0)
		end
		owner = owner or {}
		local list = registry.callbacks[event] or {}
		registry.callbacks[event] = list
		for _, entry in ipairs(list) do
			if entry.owner == owner then
				entry.func = func
				return owner
			end
		end
		list[#list + 1] = { owner = owner, func = func }
		return owner
	end
	function registry:TriggerEvent(event, ...)
		for _, entry in ipairs(registry.callbacks[event] or {}) do
			local ok, err = pcall(entry.func, entry.owner, ...)
			if not ok then
				W.errors[#W.errors + 1] = tostring(err)
			end
		end
	end
	function W.registrants(event) return #(registry.callbacks[event] or {}) end
	if not layout.noEventRegistry then
		env.EventRegistry = registry
	end
	W.registry = registry

	-- Blizzard frames --------------------------------------------------------------------------------
	W.group = "movers"
	-- A Lua method of Blizzard's on a system frame: the engine's method is kept as <name>Base. It is secure code, which may lay out a
	-- protected frame in combat.
	local function makeSystem(raw, proxy)
		raw.system = layout.systemValue or 1
		-- What Edit Mode sets once it has applied a layout to the frame: the place and the settings of the layout (EditModeSystemTemplates.lua,
		-- ApplySystemAnchor reads anchorInfo; UpdateSettingMap reads settings, a list of setting and value).
		raw.systemInfo = { isInDefaultPosition = true, anchorInfo = { point = "CENTER", relativeTo = "UIParent", relativePoint = "CENTER", offsetX = 0, offsetY = 0 },
			settings = { { setting = 1, value = 100 } } }
		for _, name in ipairs({ "SetPoint", "ClearAllPoints", "SetScale", "Hide", "SetShown" }) do
			local base = raw[name]
			raw[name .. "Base"] = base
			raw[name] = lua(W, name, function(...)
				local protected = raw.protected
				raw.protected = false
				local ok, err = pcall(base, ...)
				raw.protected = protected
				if not ok then
					error(err, 0)
				end
			end)
		end
	end
	-- spec: parent, point = { point, relativeTo, relativePoint, x, y }, width, height, scale, hidden, protected, forbidden,
	-- system, fields, explicit (the second answer of IsProtected).
	local function bframe(name, spec)
		spec = spec or {}
		local parent = spec.parent or ui
		local proxy, raw = W.B(parent, spec.fields, { name = name, width = spec.width, height = spec.height, scale = spec.scale, hidden = spec.hidden,
			protected = spec.protected, forbidden = spec.forbidden })
		raw.fname = name
		raw.explicit = spec.explicit
		extendFrame(W, raw, proxy)
		local praw = W.rawOf[parent]
		if praw and praw.children then
			praw.children[#praw.children + 1] = proxy
		end
		if spec.point then
			W.blizzard(function() raw.SetPoint(proxy, unpack(spec.point)) end)
		end
		if spec.system then
			makeSystem(raw, proxy)
		end
		if name and not (layout.missing and layout.missing[name]) then
			env[name] = proxy
		end
		return proxy, raw
	end
	W.bframe = bframe
	-- A texture of a Blizzard frame, anchored to it.
	function W.btexture(owner, name, atlas)
		local proxy, raw = W.Rr(owner, atlas, { name = name })
		extendRegion(W, raw)
		return proxy, raw
	end

	local HUD = {
		{ "AlertFrame", "BOTTOM", 0, 128, 1, 1 },
		{ "UIErrorsFrame", "TOP", 0, -122, 512, 60 },
		{ "UIWidgetTopCenterContainerFrame", "TOP", 0, -15, 220, 60 },
		{ "ZoneTextFrame", "TOP", 0, -128, 512, 128, hidden = true },
		{ "SubZoneTextFrame", "BOTTOM", 0, 512, 512, 128, hidden = true },
		{ "EventToastManagerFrame", "TOP", 0, -190, 300, 100, hidden = true },
	}
	local WINDOWS = {
		{ "CharacterFrame", 338, 424 }, { "QuestFrame", 338, 496 }, { "GossipFrame", 338, 496 }, { "MerchantFrame", 338, 424 }, { "MailFrame", 338, 424 },
		{ "BankFrame", 386, 415 }, { "FriendsFrame", 338, 424 }, { "CommunitiesFrame", 814, 426 }, { "DressUpFrame", 334, 385 }, { "TaxiFrame", 508, 482 },
		{ "TradeFrame", 384, 512 }, { "AddonList", 500, 480 },
		-- The windows of Windows.lua that had no handle. The game opens the last two beside another window and not through the panel manager's table.
		{ "LFGParentFrame", 353, 424 }, { "SocialUIFrame", 410, 675, child = true }, { "ChannelFrame", 338, 424 }, { "RaidParentFrame", 338, 424 },
		{ "OpenMailFrame", 338, 424, child = true }, { "QuestLogPopupDetailFrame", 338, 496 }, { "ItemTextFrame", 338, 424 },
	}
	-- Windows that belong to an addon that loads when it is first needed.
	local DEMAND = { { "PlayerSpellsFrame", 600, 500 }, { "ClassTrainerFrame", 338, 424 }, { "AuctionHouseFrame", 800, 500 }, { "ProfessionsFrame", 900, 600 } }
	-- The windows that Windows.lua added later; only a world that asks for them (layout.later) has them.
	local LATER = { { "GuildRegistrarFrame", 338, 424 }, { "PetitionFrame", 338, 424 }, { "TabardFrame", 338, 424 }, { "GuildBankFrame", 793, 480 },
		{ "InspectFrame", 338, 424 }, { "MacroFrame", 338, 424 }, { "CollectionsJournal", 733, 500 }, { "PetStableFrame", 338, 424 },
		{ "ItemSocketingFrame", 338, 424 }, { "ClickBindingFrame", 338, 424 }, { "TimeManagerFrame", 200, 300 }, { "CooldownViewerSettings", 338, 424 } }
	local function window(entry)
		local proxy = bframe(entry[1], { point = { "TOPLEFT", ui, "TOPLEFT", 16, -116 }, width = entry[2], height = entry[3], hidden = true })
		if not entry.child then
			env.UIPanelWindows[entry[1]] = { area = "left", pushable = 1 }
		end
		return proxy
	end
	for _, e in ipairs(HUD) do
		bframe(e[1], { point = { e[2], ui, e[2], e[3], e[4] }, width = e[5], height = e[6], hidden = e.hidden })
	end
	for _, e in ipairs(WINDOWS) do
		window(e)
	end
	if layout.loaded then
		for _, e in ipairs(DEMAND) do
			window(e)
		end
	end
	if layout.later then
		for _, e in ipairs(LATER) do
			window(e)
		end
	end
	-- The addon that holds the load-on-demand windows loads: its frames appear, then ADDON_LOADED.
	function W.loadWindows()
		W.group = "movers"
		for _, e in ipairs(DEMAND) do
			if not env[e[1]] then
				window(e)
			end
		end
		W.group = "static"
		W.seal()
		W.fire("ADDON_LOADED", "Blizzard_PlayerSpells")
	end

	-- Edit Mode.
	-- layoutInfo.activeLayout is the number of the layout that is applied (EditModeManager.lua, GetActiveLayoutInfo).
	local manager = bframe("EditModeManagerFrame", { fields = { editModeActive = false, layoutInfo = { activeLayout = 1 } }, hidden = true })
	W.manager = W.rawOf[manager]
	function W.editMode(active)
		W.manager.editModeActive = active
		W.registry:TriggerEvent(active and "EditMode.Enter" or "EditMode.Exit")
	end
	-- A system frame, a child of one, and frames that are laid out by a container.
	W.minimap = bframe("MinimapCluster", { point = { "TOPRIGHT", ui, "TOPRIGHT", 0, 0 }, width = 192, height = 192, system = true })
	W.minimapChild = bframe("MinimapClusterChild", { parent = W.minimap, point = { "TOPRIGHT", W.minimap, "TOPRIGHT", -10, -10 }, width = 100, height = 100 })
	W.playerFrame = bframe("PlayerFrame", { point = { "TOPLEFT", ui, "TOPLEFT", 20, -20 }, width = 232, height = 100, system = true, protected = true })
	-- The pet frame hangs in the container under the player frame, and the game sets its scale in UpdatePetFrameScale
	-- (EditModeSystemTemplates.lua:2686-2697): the Frame Size of the pet frame divided by the scale of the player frame, then a layout of the container.
	if layout.pet then
		W.petMarks, W.petLayouts, W.petPct = 0, 0, layout.petPct or 100
		local box = bframe("PlayerBottomManagedFrameContainer", { parent = W.playerFrame, point = { "TOP", W.playerFrame, "BOTTOM", 30, 25 }, width = 120, height = 49,
			fields = { MarkDirty = function() W.petMarks = W.petMarks + 1 end, Layout = function() W.petLayouts = W.petLayouts + 1 end } })
		W.petBox = box
		bframe("PetFrame", { parent = layout.petFree and ui or box, point = { "TOP", box, "TOP", 0, 0 }, width = 120, height = 49, system = true, protected = true })
		function W.updatePetScale()
			W.blizzard(function()
				local pet, scale = env.PetFrame, W.petPct / 100
				if pet:GetParent() == box then
					scale = scale / env.PlayerFrame:GetScale()
				end
				pet:SetScale(scale)
				box:Layout()
			end)
			-- Edit Mode does this while it applies a layout and announces the layout; the addon sets its size one frame after the event.
			W.fire("EDIT_MODE_LAYOUTS_UPDATED")
			W.tick()
		end
	end
	W.buffFrame = bframe("BuffFrame", { point = { "TOPRIGHT", ui, "TOPRIGHT", -200, -10 }, width = 300, height = 60, system = true })
	-- The buff frame takes a hook on its event script, as the page of the buffs follows the weapon enchant events with it.
	FH.hookable(W, W.rawOf[W.buffFrame], "OnEvent")
	local box = bframe("TestLayoutBox", { point = { "CENTER", ui, "CENTER", 300, 0 }, width = 200, height = 200, fields = { Layout = function() end } })
	W.box = box
	bframe("TestLayoutChild", { parent = box, point = { "TOPLEFT", box, "TOPLEFT", 0, 0 }, width = 100, height = 30, fields = { layoutIndex = 2 } })
	local container = bframe("BottomManagedFrameContainer", { point = { "BOTTOM", ui, "BOTTOM", 0, 0 }, width = 400, height = 100, fields = { Layout = function() end } })
	W.container = container
	bframe("TestManagedFrame", { parent = container, point = { "BOTTOM", container, "BOTTOM", 0, 0 }, width = 100, height = 30, fields = { isManagedFrame = true, layoutParent = container } })
	bframe("TestPlaced", { parent = container, point = { "BOTTOM", container, "BOTTOM", 0, 0 }, width = 100, height = 30, fields = { layoutParent = container } })
	bframe("TotemFrame", { parent = container, point = { "BOTTOM", container, "BOTTOM", 0, 0 }, width = 100, height = 30 })
	bframe("ChatFrame2", { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 0, 100 }, width = 300, height = 100 })
	bframe("ContainerFrame3", { point = { "BOTTOMRIGHT", ui, "BOTTOMRIGHT", 0, 100 }, width = 300, height = 100, hidden = true })
	-- Frames the picker may take, and what is inside them.
	W.panel = bframe("TestPanel", { point = { "CENTER", ui, "CENTER", -300, 100 }, width = 120, height = 60 })
	W.inner = bframe("TestPanelInner", { parent = W.panel, point = { "TOPLEFT", W.panel, "TOPLEFT", 5, -5 }, width = 40, height = 20 })
	W.icon = W.btexture(W.inner, nil, "test-icon")
	W.blizzard(function() W.rawOf[W.icon].SetPoint(W.icon, "CENTER", W.inner, "CENTER", 0, 0) end)
	W.rawOf[W.icon].width, W.rawOf[W.icon].height = 10, 10
	-- A frame that is the child of a frame whose parent is not UIParent's chain: it cannot be reached.
	local lost = bframe("TestLost", { parent = ui, point = { "CENTER", ui, "CENTER", 0, -300 }, width = 80, height = 40 })
	W.lost = lost
	W.rawOf[lost].parent = nil
	W.rawOf[lost].lostParent = true
	W.group = "static"

	-- A panel manager that places a window and announces it. It is secure code, which may lay out a protected frame in combat.
	function W.openWindow(name)
		local frame = env[name]
		local raw = W.rawOf[frame]
		raw.shown = true
		-- The offsets are divided by the scale of the window (UIParentPanelManager.lua, UpdateUIPanelPositions).
		raw.points = { { "TOPLEFT", ui, "TOPLEFT", 16 / raw.scale, -116 / raw.scale } }
		-- Showing a frame runs the scripts hooked on its OnShow, after the game's own.
		if W.hookRun then
			W.hookRun(frame, "OnShow")
		end
		registry:TriggerEvent("UIParentPanelManager.ShowUIPanel", frame, false)
	end
	function W.closeWindow(name)
		local frame = env[name]
		W.rawOf[frame].shown = false
		registry:TriggerEvent("UIParentPanelManager.HideUIPanel", frame, false)
	end
	-- The panel manager places the panels with UpdateUIPanelPositions before it shows the window and announces it (UIParentPanelManager.lua, SetUIPanel).
	function W.openWindowEarly(name)
		local frame = env[name]
		if env.UpdateUIPanelPositions then
			W.blizzard(env.UpdateUIPanelPositions, frame)
		end
		W.openWindow(name)
	end
	-- The game writes the scale of a window as FrameUtil.UpdateScaleForFitSpecific does: 1, then the scale that fits.
	function W.gameScales(name, scale)
		W.blizzard(function() env[name]:SetScale(scale) end)
	end
	function W.fit(name, scale)
		W.blizzard(function()
			env[name]:SetScale(1)
			env[name]:SetScale(scale or 1)
		end)
	end
	-- The player presses a mouse button with the cursor at x, y, and leaf is the frame the client says is under it. A frame of the addon's
	-- that takes the mouse runs its OnMouseDown, then the game reports the press (GLOBAL_MOUSE_DOWN).
	-- With eventFirst the game reports the press before the frame's script runs; the order is not known.
	function W.pressAt(x, y, button, leaf, eventFirst)
		button = button or "LeftButton"
		W.cursor = { x, y }
		W.foci = leaf and { leaf } or {}
		W.mouse[button] = true
		W.downOn = leaf
		if eventFirst then
			W.fire("GLOBAL_MOUSE_DOWN", button)
		end
		local raw = leaf and W.rawOf[leaf]
		if raw and raw.group == nil and raw.mouse and raw.scripts and raw.scripts.OnMouseDown then
			raw.scripts.OnMouseDown(leaf, button)
		end
		if not eventFirst then
			W.fire("GLOBAL_MOUSE_DOWN", button)
		end
	end
	-- The frame the client says is under the point: of the frames that are shown and take the mouse and clicks, with the point inside their hit
	-- rectangle (their rectangle less the insets of SetHitRectInsets), the one in the highest strata, then at the highest level, then made last.
	-- A frame that has no strata of its own is in the strata of its parent.
	local RANK = { BACKGROUND = 1, LOW = 2, MEDIUM = 3, HIGH = 4, DIALOG = 5, FULLSCREEN = 6, FULLSCREEN_DIALOG = 7, TOOLTIP = 8 }
	local function strataOf(raw)
		for _ = 1, 30 do
			if raw == nil then
				return "MEDIUM"
			elseif raw.strata then
				return raw.strata
			end
			raw = raw.parent and W.rawOf[raw.parent]
		end
		return "MEDIUM"
	end
	function W.hitAt(x, y)
		local proxyOf, seen, best = {}, {}, nil
		for key, raw in pairs(W.rawOf) do
			if key ~= raw then
				proxyOf[raw] = key
			end
		end
		for _, raw in pairs(W.rawOf) do
			if not seen[raw] and raw.isFrame and raw.mouse == true and raw.clicks ~= false and not raw.forbidden and visible(W, raw) then
				seen[raw] = true
				local l, b, w, h = W.rectOf(raw)
				if l then
					local e, hit = effScale(W, raw) / W.uiInner.scale, raw.hit or { 0, 0, 0, 0 }
					if x >= l + hit[1] * e and x <= l + w - hit[2] * e and y >= b + hit[4] * e and y <= b + h - hit[3] * e then
						local rank, level, order = RANK[strataOf(raw)], raw.level or 0, raw.order or 0
						if not best or rank > best.rank or (rank == best.rank and (level > best.level or (level == best.level and order > best.order))) then
							best = { raw = raw, rank = rank, level = level, order = order }
						end
					end
				end
			end
		end
		return best and (proxyOf[best.raw] or best.raw)
	end
	-- The player presses a button where the client says a frame takes it: as W.pressAt, with the frame W.hitAt finds.
	function W.pressOn(x, y, button, eventFirst)
		W.pressAt(x, y, button, W.hitAt(x, y), eventFirst)
	end
	-- The player lets go: the frame of the addon's that took the press runs its OnMouseUp, then the game reports it.
	function W.releaseAt(button)
		button = button or "LeftButton"
		W.mouse[button] = false
		local leaf = W.downOn
		W.downOn = nil
		local raw = leaf and W.rawOf[leaf]
		if raw and raw.group == nil and raw.scripts and raw.scripts.OnMouseUp then
			raw.scripts.OnMouseUp(leaf, button)
		end
		W.fire("GLOBAL_MOUSE_UP", button)
	end
	-- The game puts a frame somewhere: its own SetPoint, the way its Lua does it.
	function W.gamePlaces(name, point, x, y, rel, relPoint)
		local frame = env[name]
		W.blizzard(function()
			frame:ClearAllPoints()
			frame:SetPoint(point, rel or ui, relPoint or point, x, y)
		end)
	end
	-- Where a frame is on the screen, in the units of UIParent: left, bottom, width, height.
	function W.rectOf(frame)
		local raw = W.rawOf[frame]
		local l, b, w, h = place(W, raw)
		local k = W.uiInner.scale
		return l and l / k, b and b / k, w and w / k, h and h / k
	end
	W.place = function(frame) return place(W, W.rawOf[frame]) end

	-- Frames of the addon's -------------------------------------------------------------------------
	-- One frame is drawn: every shown frame with an OnUpdate gets the time since the last.
	function W.update(dt)
		W.now = W.now + dt
		for _, f in ipairs(W.updaters) do
			local fn = f.scripts and f.scripts.OnUpdate
			if fn and visible(W, f) then
				fn(f, dt)
			end
		end
		W.tick()
	end
	function W.run(total, step)
		step = step or total
		local done = 0
		while done < total - 1e-9 do
			W.update(step)
			done = done + step
		end
	end
	-- The addon's handles: movable frames of its own, found by the text they show. The bar is movable too, but takes no wheel.
	function W.handles()
		local list = {}
		for _, f in ipairs(W.addonFrames) do
			-- The bar has three texts, a box that the game places is grey and says so, and the picker takes the mouse from every box.
			local text = f.fonts[1] and f.fonts[1].text
			if f.movable and #f.fonts == 1 and not (text and text:find("(placed by the game)", 1, true)) then
				list[#list + 1] = f
			end
		end
		return list
	end
	-- A box of a bar of the stacks ends with what the game does to it in combat.
	local MOVED_BACK = " (moved back by the game in combat)"
	function W.handle(label)
		for _, f in ipairs(W.handles()) do
			local text = f.fonts[1].text
			if text and text:sub(-#MOVED_BACK) == MOVED_BACK then
				text = text:sub(1, -#MOVED_BACK - 1)
			end
			if text == label or (text and text:match("^" .. label:gsub("%p", "%%%0") .. " %d+%%$")) then
				return f
			end
		end
	end
	function W.handleText(label)
		local f = W.handle(label)
		return f and f.fonts[1].text
	end
	function W.shownHandles()
		local names = {}
		for _, f in ipairs(W.handles()) do
			if f.shown then
				names[#names + 1] = f.fonts[1].text
			end
		end
		table.sort(names)
		return names
	end
	-- The user takes a handle a quarter of the way in from its bottom left corner and holds the button: the cursor is there.
	function W.dragStart(label)
		local f = W.handle(label)
		assert(f and f.shown and f.mouse, "no handle to drag: " .. tostring(label))
		local k = W.uiInner.scale
		local l, b, w, h = W.rectOf(f)
		W.grab = { f = f, dx = w / 4, dy = h / 4 }
		W.cursor = { (l + w / 4) * k, (b + h / 4) * k }
		W.mouse.LeftButton = true
		f.scripts.OnDragStart(f)
		return f
	end
	-- The user moves the cursor so that the bottom left corner of the handle would be at left, bottom (UIParent units), and a frame is drawn.
	-- A handle the engine moves is put there, held on the screen when it is clamped.
	function W.dragTo(left, bottom)
		local f, k = W.grab.f, W.uiInner.scale
		if f.moving then
			local w = f.width
			local h = f.height
			if f.clamped then
				local sw, sh = W.height * 16 / 9 / k, W.height / k
				left = math.max(0, math.min(left, sw - w))
				bottom = math.max(0, math.min(bottom, sh - h))
			end
			f.points = { { "BOTTOMLEFT", ui, "BOTTOMLEFT", left, bottom } }
		else
			W.cursor = { (left + W.grab.dx) * k, (bottom + W.grab.dy) * k }
			if f.scripts.OnUpdate then
				f.scripts.OnUpdate(f, 0.016)
			end
		end
	end
	-- The user lets go.
	function W.dragEnd()
		local f = W.grab.f
		W.grab = nil
		W.mouse.LeftButton = false
		f.scripts.OnDragStop(f)
	end
	-- The user drags a handle so that its bottom left corner is at left, bottom (UIParent units).
	function W.drag(label, left, bottom)
		W.dragStart(label)
		W.dragTo(left, bottom)
		W.dragEnd()
	end
	function W.wheel(label, delta)
		local f = W.handle(label)
		assert(f and f.shown and f.wheel, "no handle to scroll: " .. tostring(label))
		f.scripts.OnMouseWheel(f, delta)
	end
	function W.rightClick(label)
		local f = W.handle(label)
		assert(f and f.shown and f.mouse, "no handle to click: " .. tostring(label))
		f.scripts.OnMouseUp(f, "RightButton")
	end
	-- A frame of the addon's by what it shows.
	function W.textFrame(text)
		for _, f in ipairs(W.addonFrames) do
			for _, t in ipairs(f.fonts) do
				if t.text == text then
					return f, t
				end
			end
		end
	end
	function W.barButton(text)
		local f = W.textFrame(text)
		return f
	end
	function W.press(text)
		local f = W.barButton(text)
		assert(f and f.scripts.OnMouseUp, "no button: " .. text)
		f.scripts.OnMouseUp(f, "LeftButton")
	end
	function W.pickTag()
		for _, f in ipairs(W.addonFrames) do
			if f.strata == "TOOLTIP" and f.fonts[1] then
				return f, f.fonts[1]
			end
		end
	end
	function W.pickBox()
		for _, f in ipairs(W.addonFrames) do
			if f.strata == "HIGH" and not f.movable and #f.fonts == 0 and f.parent == ui and f.width ~= nil then
				return f
			end
		end
	end

	-- Tooltip ---------------------------------------------------------------------------------------
	if layout.tooltip then
		env.Enum = { WorldCursorAnchorType = { None = 0, Default = 1, Cursor = 2, Nameplate = 3 } }
		W.group = "movers"
		local container2 = bframe("GameTooltipDefaultContainer", { point = { "BOTTOMRIGHT", ui, "BOTTOMRIGHT", -9, 85 }, width = 250, height = 150, system = true, hidden = true })
		W.tooltipContainer = container2
		local tip, traw = bframe("GameTooltip", { width = 200, height = 100, hidden = true, forbidden = layout.tooltipForbidden })
		W.tooltip, W.tooltipRaw = tip, traw
		-- Where the engine puts a tooltip that has an owner: the corner of the tooltip and of the owner.
		local BESIDE = { ANCHOR_RIGHT = { "BOTTOMLEFT", "TOPRIGHT" }, ANCHOR_LEFT = { "BOTTOMRIGHT", "TOPLEFT" }, ANCHOR_TOP = { "BOTTOM", "TOP" },
			ANCHOR_BOTTOM = { "TOP", "BOTTOM" }, ANCHOR_TOPRIGHT = { "BOTTOMLEFT", "TOPRIGHT" }, ANCHOR_TOPLEFT = { "BOTTOMRIGHT", "TOPLEFT" },
			ANCHOR_BOTTOMRIGHT = { "TOPLEFT", "BOTTOMRIGHT" }, ANCHOR_BOTTOMLEFT = { "TOPRIGHT", "BOTTOMLEFT" } }
		local KNOWN = { ANCHOR_NONE = true, ANCHOR_CURSOR = true, ANCHOR_CURSOR_LEFT = true, ANCHOR_CURSOR_RIGHT = true, ANCHOR_PRESERVE = true }
		function traw.SetOwner(_, owner, anchor)
			if W.inBlizzard == 0 then
				bad(W, "the addon called SetOwner on the tooltip")
			end
			-- SetOwner clears the points: GameTooltip_SetDefaultAnchor calls SetPoint with a corner that changes with the box
			-- of Edit Mode and never ClearAllPoints, so the tooltip would collect corners otherwise.
			traw.owner, traw.anchorType, traw.points = owner, anchor, {}
			if BESIDE[anchor] then
				traw.points = { { BESIDE[anchor][1], owner, BESIDE[anchor][2], 0, 0 } }
			end
			traw.calls.SetOwner = (traw.calls.SetOwner or 0) + 1
		end
		function traw.GetOwner() return answer(traw, "owner", traw.owner) end
		function traw.GetAnchorType() return answer(traw, "anchorType", traw.anchorType) end
		function traw.SetAnchorType(_, anchor)
			if not (BESIDE[anchor] or KNOWN[anchor]) then
				bad(W, "SetAnchorType: " .. tostring(anchor))
			end
			if traw.fault.setAnchorType then
				error("SetAnchorType failed", 0)
			end
			traw.anchorType = anchor
			traw.calls.SetAnchorType = (traw.calls.SetAnchorType or 0) + 1
		end
		-- What the addon does to the tooltip, counted. The design says it never reads the geometry of the tooltip.
		traw.addon = {}
		for _, name in ipairs({ "SetPoint", "ClearAllPoints", "SetScale", "SetAnchorType" }) do
			local base = traw[name]
			traw[name] = function(...)
				if W.inBlizzard == 0 then
					traw.addon[name] = (traw.addon[name] or 0) + 1
				end
				return base(...)
			end
		end
		for _, name in ipairs({ "GetRect", "GetSize", "GetWidth", "GetHeight" }) do
			local base = traw[name]
			traw[name] = function(...)
				if W.inBlizzard == 0 then
					bad(W, "the addon read the geometry of the tooltip: " .. name)
				end
				return base(...)
			end
		end
		-- The addon may hide the tooltip when the game fades it out. The tooltip stays shown while it fades.
		local hide = traw.Hide
		traw.Hide = function(...)
			if W.inBlizzard == 0 then
				traw.addon.Hide = (traw.addon.Hide or 0) + 1
			end
			W.blizzard(hide, ...)
		end
		-- The scripts hooked with HookScript run after the game shows or hides the tooltip, as the addon's code. The game fades the tooltip out by
		-- lowering its alpha, and a shown tooltip has alpha 1.
		traw.hooks, traw.alpha = { OnShow = {}, OnHide = {} }, 1
		W.tipScriptHooks = 0
		function traw.HookScript(_, which, fn)
			if traw.hooks[which] == nil or type(fn) ~= "function" then
				bad(W, "HookScript arguments")
			end
			traw.hooks[which][#traw.hooks[which] + 1] = fn
			W.tipScriptHooks = W.tipScriptHooks + 1
		end
		function traw.GetAlpha() return traw.alpha end
		local function scripts(which)
			for _, fn in ipairs(traw.hooks[which]) do
				-- A script hook is the addon's own code, whoever shows the tooltip.
				local inside = W.inBlizzard
				W.inBlizzard, W.inHook = 0, (W.inHook or 0) + 1
				local ok, err = pcall(fn, tip)
				W.inBlizzard, W.inHook = inside, W.inHook - 1
				if not ok then
					error(err, 0)
				end
			end
		end
		local show, hideBase = traw.Show, traw.Hide
		traw.Show = function(...)
			local was = traw.shown
			traw.alpha = 1
			show(...)
			if not was then
				scripts("OnShow")
			end
		end
		traw.Hide = function(...)
			local was = traw.shown
			hideBase(...)
			if was then
				scripts("OnHide")
			end
		end
		traw.FadeOut = lua(W, "FadeOut", function() traw.fading, traw.alpha = true, 0.6 end)
		function W.fade()
			W.blizzard(function() tip:FadeOut() end)
		end
		function W.tipCalls(name) return traw.addon[name] or 0 end
		-- GameTooltip_SetDefaultAnchor (Blizzard_SharedXML/SharedTooltipTemplates.lua).
		env.GameTooltip_SetDefaultAnchor = function(tooltip, parent)
			W.blizzard(function()
				tooltip:SetOwner(parent, "ANCHOR_NONE")
				local point, _, _, offsetX, offsetY = container2:GetPoint(1)
				if not (point == "BOTTOMRIGHT" or point == "BOTTOMLEFT" or point == "TOPRIGHT" or point == "TOPLEFT") then
					if point == "TOP" or point == "BOTTOM" then
						point = offsetX > 0 and point .. "RIGHT" or point .. "LEFT"
					elseif point == "LEFT" or point == "RIGHT" then
						point = offsetY > 0 and "TOP" .. point or "BOTTOM" .. point
					else
						point = (offsetY > 0 and "TOP" or "BOTTOM") .. (offsetX > 0 and "RIGHT" or "LEFT")
					end
				end
				tooltip:SetPoint(point, container2)
			end)
		end
		-- GameTooltipDataMixin:SetWorldCursor.
		function W.worldCursor(kind, parent)
			W.blizzard(function()
				parent = parent or ui
				if kind == env.Enum.WorldCursorAnchorType.Default then
					env.GameTooltip_SetDefaultAnchor(tip, parent)
				elseif kind == env.Enum.WorldCursorAnchorType.Cursor then
					tip:SetOwner(ui, "ANCHOR_CURSOR")
				elseif kind == env.Enum.WorldCursorAnchorType.Nameplate then
					tip:SetOwner(parent, "ANCHOR_NONE")
					tip:ClearAllPoints()
					tip:SetPoint("BOTTOM", parent, "TOP", 0, 10)
				end
				if kind ~= env.Enum.WorldCursorAnchorType.None then
					tip:Show()
				end
			end)
			W.fire("WORLD_CURSOR_TOOLTIP_UPDATE", kind)
		end
		-- Hovering a unit frame or action button: OnEnter calls GameTooltip_SetDefaultAnchor, then fills the tooltip and shows it.
		function W.hover(owner)
			W.blizzard(function()
				env.GameTooltip_SetDefaultAnchor(tip, owner)
				tip:Show()
			end)
		end
		-- Hovering a button that sets its own anchor.
		function W.hoverAt(owner, anchor)
			W.blizzard(function()
				tip:SetOwner(owner, anchor)
				tip:Show()
			end)
		end
		function W.leave()
			W.blizzard(function() tip:Hide() end)
		end
		-- A tooltip's point on the screen, in the units of UIParent.
		function W.tipPoint(point)
			local l, b, w, h = place(W, traw)
			if not l then
				return nil
			end
			local k = W.uiInner.scale
			local f = FRAC[point]
			return (l + w * f[1]) / k, (b + h * f[2]) / k
		end
		bframe("ShoppingTooltip1", { point = { "TOPLEFT", tip, "TOPRIGHT", 0, 0 }, width = 200, height = 100, hidden = true })
		bframe("ItemRefTooltip", { point = { "CENTER", ui, "CENTER", 0, 200 }, width = 200, height = 100, hidden = true })
		W.group = "static"
	end

	-- Cast bars -------------------------------------------------------------------------------------
	if layout.casts then
		W.group = "castbars"
		local cast = layout.casts == true and {} or layout.casts
		local playerFrame = W.playerFrame
		local function bar(name, game, extra)
			local entry = W.cast[name]
			local raw = entry.inner
			raw.width, raw.height = game[1], game[2]
			raw.fname, raw.name = name, name
			extendFrame(W, raw, entry.bar)
			if extra and extra.protected ~= nil then
				raw.protected = extra.protected
			end
			watch(W, raw, { "SetWidth", "SetHeight" })
			return entry, raw
		end
		local function parts(entry, raw, withMask)
			-- Spark 8 by 20, centred; Text 185 by 16, TOP 0,-10; BorderMask 256 by 13, centred (CastingBarFrame.xml).
			local owner = entry.bar
			local p = raw.protected
			local spark = W.Rr(owner, "ui-castingbar-pip", {})
			W.rawOf[spark].width, W.rawOf[spark].height = 8, 20
			raw.Spark = spark
			raw.sparkRegion = spark
			local text = W.Rr(owner, nil, { kind = "FontString", protected = p })
			W.rawOf[text].width, W.rawOf[text].height = 185, 16
			raw.Text = text
			raw.textRegion = text
			for _, region in ipairs({ spark, text }) do
				extendRegion(W, W.rawOf[region])
			end
			if withMask then
				local mask = W.Rr(owner, "cast_standard_barmask", { kind = "MaskTexture" })
				W.rawOf[mask].width, W.rawOf[mask].height = 256, 13
				extendRegion(W, W.rawOf[mask])
				raw.BorderMask = mask
				raw.maskRegion = mask
			end
			raw.regions = { spark, text }
			watch(W, W.rawOf[spark], { "SetHeight" })
			watch(W, W.rawOf[text], { "SetPoint", "ClearAllPoints" })
			if withMask then
				watch(W, W.rawOf[raw.BorderMask], { "SetSize" })
			end
			W.blizzard(function()
				W.rawOf[spark].SetPoint(spark, "CENTER", owner, "CENTER", 0, 0)
				W.rawOf[text].SetPoint(text, "TOP", owner, "TOP", 0, -10)
			end)
		end
		local pe, praw = bar("PlayerCastingBarFrame", { 208, 11 }, { protected = cast.playerProtected })
		local pet, petraw = bar("PetCastingBarFrame", { 195, 13 }, { protected = cast.petProtected })
		local te, traw2 = bar("TargetFrameSpellBar", { 150, 10 }, { protected = not cast.targetUnprotected })
		local fe, fraw = bar("FocusFrameSpellBar", { 150, 10 }, { protected = not cast.targetUnprotected })
		-- Target and focus bars are children of protected unit frames. Their own answer is "not explicitly protected".
		traw2.explicit, fraw.explicit = false, false
		parts(pe, praw, not cast.noMask)
		parts(pet, petraw, false)
		praw.parent, petraw.parent, traw2.parent, fraw.parent = ui, ui, ui, ui
		praw.points, petraw.points = { { "BOTTOM", ui, "BOTTOM", 0, 250 } }, { { "BOTTOM", ui, "BOTTOM", 0, 280 } }
		traw2.points = { { "TOPLEFT", ui, "TOPLEFT", 300, -200 } }
		fraw.points = { { "TOPLEFT", ui, "TOPLEFT", 300, -300 } }
		-- The bars are system frames or children of unit frames: SetWidth and SetHeight are native.
		makeSystem(praw, pe.bar)
		if cast.petSystem then
			makeSystem(petraw, pet.bar)
		end
		-- CastingBarMixin:SetLook.
		local function setLook(entry, raw)
			return lua(W, "SetLook", function(_, look)
				raw.look = look
				local bar2 = entry.bar
				local text = raw.textRegion
				if look == "CLASSIC" then
					raw.SetWidth(bar2, 208)
					raw.SetHeight(bar2, 11)
					if text then
						local t = W.rawOf[text]
						t.ClearAllPoints()
						t.width, t.height = 185, 16
						t.SetPoint(text, "TOP", bar2, "TOP", 0, -10)
					end
				elseif look == "UNITFRAME" then
					raw.SetWidth(bar2, 150)
					raw.SetHeight(bar2, 10)
					if text then
						local t = W.rawOf[text]
						t.ClearAllPoints()
						t.width, t.height = 0, 16
						t.SetPoint(text, "TOPLEFT", bar2, "TOPLEFT", 0, 3)
						t.SetPoint(text, "TOPRIGHT", bar2, "TOPRIGHT", 0, 3)
					end
				end
			end)
		end
		praw.SetLook = setLook(pe, praw)
		petraw.SetLook = setLook(pet, petraw)
		praw.attachedToPlayerFrame = false
		-- PlayerFrame_AttachCastBar and PlayerFrame_DetachCastBar (Blizzard_UnitFrame/Shared/PlayerFrame.lua).
		local function attach()
			W.blizzard(function()
				pet.bar:SetLook("UNITFRAME")
				pet.bar:SetWidth(150)
				pet.bar:SetHeight(10)
				praw.attachedToPlayerFrame = true
				pe.bar:SetLook("UNITFRAME")
				praw.parent = playerFrame
				praw.points = { { "TOPRIGHT", playerFrame, "BOTTOMRIGHT", -24, 12 } }
			end)
			W.attaches = (W.attaches or 0) + 1
		end
		local function detach()
			W.blizzard(function()
				pet.bar:SetLook("CLASSIC")
				pet.bar:SetWidth(195)
				pet.bar:SetHeight(13)
				praw.attachedToPlayerFrame = false
				pe.bar:SetLook("CLASSIC")
				praw.parent = ui
			end)
			W.detaches = (W.detaches or 0) + 1
		end
		if not cast.noGlobals then
			env.PlayerFrame_AttachCastBar = attach
			env.PlayerFrame_DetachCastBar = detach
		end
		-- The game calls them by their global names, so the hooks of the addon run.
		W.attach = function() (env.PlayerFrame_AttachCastBar or attach)() end
		W.detach = function() (env.PlayerFrame_DetachCastBar or detach)() end
		if cast.locked then
			attach()
		end
		-- The bar and its regions in one line: width x height, and for the player bar the spark, the mask and the text anchors.
		function W.barSize(name)
			local r = W.cast[name].inner
			return g(r.width) .. "x" .. g(r.height)
		end
		function W.barParts(name)
			local r = W.cast[name].inner
			local spark = r.sparkRegion and W.rawOf[r.sparkRegion].height
			local mask = r.maskRegion and (g(W.rawOf[r.maskRegion].width) .. "x" .. g(W.rawOf[r.maskRegion].height))
			local parts2 = {}
			local text = r.textRegion and W.rawOf[r.textRegion]
			for _, p in ipairs(text and text.points or {}) do
				parts2[#parts2 + 1] = p[1] .. ">" .. p[3] .. " " .. g(p[4]) .. "," .. g(p[5])
			end
			return "spark " .. g(spark) .. " mask " .. tostring(mask) .. " text " .. table.concat(parts2, " | ")
		end
		W.group = "static"
	end

	-- More of Edit Mode's frames, for the movers that place them: a bar of the stacks and one that is not, a child of a bar, a frame a
	-- container lays out, and the loot window, which the panel manager places too. Edit Mode replaces the IsShown of a bar with Lua and
	-- keeps the engine's as IsShownBase.
	if layout.systems then
		W.group = "movers"
		local main, mainRaw = bframe("MainActionBar", { point = { "BOTTOM", ui, "BOTTOM", 0, 6 }, width = 454, height = 35, system = true, protected = true, explicit = false })
		mainRaw.IsShownBase = mainRaw.IsShown
		mainRaw.IsShown = lua(W, "IsShown", function(...) return mainRaw.IsShownBase(...) end)
		bframe("MultiBar5", { point = { "BOTTOM", ui, "BOTTOM", 0, 300 }, width = 454, height = 35, system = true, protected = true, explicit = false })
		-- The action bars are the system Enum.EditModeSystem.ActionBar.
		env.Enum = env.Enum or {}
		env.Enum.EditModeSystem = { ActionBar = 7 }
		W.rawOf[main].system, W.rawOf[env.MultiBar5].system = 7, 7
		bframe("MainMenuBarVehicleLeaveButton", { parent = main, point = { "BOTTOMLEFT", main, "BOTTOMLEFT", 0, 0 }, width = 32, height = 32, system = true })
		bframe("SwingTimerMainHandFrame", { parent = W.container, point = { "BOTTOM", W.container, "BOTTOM", 0, 40 }, width = 300, height = 20, system = true,
			fields = { isManagedFrame = true, layoutParent = W.container } })
		bframe("LootFrame", { point = { "TOPLEFT", ui, "TOPLEFT", 16, -116 }, width = 300, height = 300, hidden = true, system = true })
		env.UIPanelWindows.LootFrame = { area = "left", pushable = 0 }
		-- Every other frame Edit Mode owns on the client, each with a place of its own.
		for index, name in ipairs(layout.allSystems or {}) do
			if not env[name] then
				bframe(name, { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 10 + (index % 30) * 60, 10 + math.floor(index / 30) * 100 }, width = 50, height = 50, system = true })
			end
		end
		W.group = "static"
	end
	-- The bars of the bottom stack and the others, for the bar block (layout.bars, with systems): each is 562 by 45 (the side bars 45 by 562), with two button
	-- containers of 45 by 45, the second two units on (below, for a side bar). The game's bottom pass is W.gameStack. GetActionBarToggles answers for bars 2
	-- to 8 (layout.toggles); layout.restricted is the answer of C_RestrictedActions.CheckAllowProtectedFunctions.
	if layout.bars then
		W.group = "movers"
		local main = env.MainActionBar
		W.rawOf[main].width, W.rawOf[main].height = 562, 45
		W.rawOf[env.MultiBar5].width, W.rawOf[env.MultiBar5].height = 562, 45
		local micro = bframe("MicroMenuContainer", { point = { "BOTTOM", ui, "BOTTOM", 116.5, 6 }, width = 270, height = 40, system = true })
		W.gamePlaces("MainActionBar", "BOTTOMRIGHT", -4.5, -4, micro, "BOTTOMLEFT")
		local function bar(name, width, height)
			local proxy = env[name] or bframe(name, { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 0, 0 }, width = width, height = height, system = true, protected = true, explicit = false })
			W.rawOf[proxy].system = 7
			local vertical = width < height
			for index = 1, 2 do
				local at = (index - 1) * 47
				bframe(name .. "ButtonContainer" .. index, { parent = proxy, width = 45, height = 45,
					point = vertical and { "TOPLEFT", proxy, "TOPLEFT", 0, -at } or { "BOTTOMLEFT", proxy, "BOTTOMLEFT", at, 0 } })
			end
			return proxy
		end
		bar("MainActionBar", 562, 45)
		for _, name in ipairs({ "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBar6", "MultiBar7", "StanceBar", "PetActionBar", "PossessActionBar" }) do
			bar(name, 562, 45)
		end
		bar("MultiBar5", 562, 45)
		bar("MultiBarRight", 45, 562)
		bar("MultiBarLeft", 45, 562)
		bframe("MainStatusTrackingBarContainer", { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 0, 0 }, width = 562, height = 14, system = true })
		bframe("SecondaryStatusTrackingBarContainer", { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 0, 0 }, width = 562, height = 14, system = true })
		-- With layout.restricted true the client lets the addon place these bars in a fight.
		for _, name in ipairs({ "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBar5", "MultiBar6", "MultiBar7", "MultiBarRight", "MultiBarLeft",
			"StanceBar", "PetActionBar", "PossessActionBar" }) do
			if env[name] then
				W.rawOf[env[name]].combatOk = layout.restricted == true
			end
		end
		W.toggleCalls = 0
		if not layout.noToggles then
			env.GetActionBarToggles = function()
				W.toggleCalls = W.toggleCalls + 1
				local list = layout.toggles or { true, true, true, false, false, false, false }
				return list[1], list[2], list[3], list[4], list[5], list[6], list[7]
			end
		end
		if layout.restricted ~= nil then
			env.C_RestrictedActions = { CheckAllowProtectedFunctions = function() return layout.restricted end }
		end
		-- The bottom pass of Edit Mode (EditModeManager.lua, LayoutBottomActionBars): each shown bar of the stack that is in its default position goes
		-- to the bottom left of the main bar, one bar height and 4 above the one before.
		W.stack = { "SecondaryStatusTrackingBarContainer", "MainStatusTrackingBarContainer", "MultiBarBottomRight", "MultiBarBottomLeft", "StanceBar", "PetActionBar",
			"PossessActionBar" }
		function W.gameStack()
			-- A bar that is not in its default position is skipped (EditModeManager.lua:693).
			if W.rawOf[main].systemInfo.isInDefaultPosition then
				W.gamePlaces("MainActionBar", "BOTTOMRIGHT", -4.5, -4, micro, "BOTTOMLEFT")
			end
			local y = W.rawOf[main].height + 4
			for _, name in ipairs(W.stack) do
				local raw = W.rawOf[env[name]]
				if raw.shown ~= false and raw.systemInfo.isInDefaultPosition then
					W.gamePlaces(name, "BOTTOMLEFT", 0, y, main, "BOTTOMLEFT")
					y = y + raw.height + 4
				end
			end
		end
		W.gameStack()
		W.group = "static"
	end
	-- Edit Mode's saved layouts (layout.layouts, with systems and bars): GetLayouts and SaveLayouts of C_EditMode, EditModePresetLayoutManager with three
	-- presets (EditModeManager.lua UpdateLayoutInfo lists them first, and activeLayout counts from them), and the game's answer to a save: the layouts
	-- are applied again, each row to its frame as ApplySystemAnchor does (EditModeSystemTemplates.lua:350-382), the game's own pass runs for the bars that
	-- are in their default position, and EDIT_MODE_LAYOUTS_UPDATED is fired. layout.layouts is true or { active = the layout in use (4 is the first
	-- saved one), refuse = true to keep nothing of a save, fail = true for a save that raises, character = true for a second saved layout,
	-- characters = n for n saved layouts of the character type, flat = true for a saved character layout named Flat UI, badName = true for a name
	-- IsValidLayoutName does not take, stay = true for a game that keeps the layout in use when it is told to change it }.
	if layout.layouts then
		W.group = "movers"
		local spec = type(layout.layouts) == "table" and layout.layouts or {}
		local function copyTable(v)
			if type(v) ~= "table" then
				return v
			end
			local c = {}
			for k, x in pairs(v) do
				c[k] = copyTable(x)
			end
			return c
		end
		local NAMES = {}
		for _, name in ipairs({ "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBar5", "MultiBar6", "MultiBar7", "MultiBarRight", "MultiBarLeft",
			"StanceBar", "PetActionBar", "PossessActionBar", "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer", "SwingTimerMainHandFrame" }) do
			if env[name] then
				NAMES[#NAMES + 1] = name
				W.rawOf[env[name]].systemIndex = name == "SwingTimerMainHandFrame" and 99 or #NAMES
			end
		end
		local DEFAULT = { MainActionBar = { point = "BOTTOMRIGHT", relativeTo = "MicroMenuContainer", relativePoint = "BOTTOMLEFT", offsetX = -4.5, offsetY = -4 } }
		local function defaultAnchor(name)
			return copyTable(DEFAULT[name] or { point = "BOTTOMLEFT", relativeTo = "UIParent", relativePoint = "BOTTOMLEFT", offsetX = 0, offsetY = 0 })
		end
		local function rows()
			local list = {}
			for _, name in ipairs(NAMES) do
				local raw = W.rawOf[env[name]]
				list[#list + 1] = { system = raw.system, systemIndex = raw.systemIndex, anchorInfo = defaultAnchor(name), settings = {}, isInDefaultPosition = true }
			end
			return list
		end
		local presets = { { layoutName = "Modern", layoutType = 0, systems = rows() }, { layoutName = "Classic", layoutType = 0, systems = rows() },
			{ layoutName = "Gamepad", layoutType = 0, systems = rows(), interfaceStyle = 1 } }
		env.Enum = env.Enum or {}
		env.Enum.EditModeLayoutType = { Preset = 0, Account = 1, Character = 2, Override = 3 }
		env.Enum.InputDeviceInterfaceType = { Mkb = 0, Gamepad = 1 }
		W.em = { saves = 0, log = {}, calls = {}, payloads = {}, active = spec.active or 4, saved = { { layoutName = "Main", layoutType = 1, systems = rows() } }, presets = #presets }
		if spec.character then
			W.em.saved[2] = { layoutName = "Alt", layoutType = 2, systems = rows() }
		end
		for number = 1, spec.characters or 0 do
			W.em.saved[#W.em.saved + 1] = { layoutName = "Char" .. number, layoutType = 2, systems = rows() }
		end
		if spec.flat then
			W.em.saved[#W.em.saved + 1] = { layoutName = "Flat UI", layoutType = 2, systems = rows() }
		end
		local function nameOfRow(row)
			for _, name in ipairs(NAMES) do
				local raw = W.rawOf[env[name]]
				if raw.system == row.system and raw.systemIndex == row.systemIndex then
					return name
				end
			end
		end
		local function layouts()
			local all = copyTable(presets)
			for _, saved in ipairs(W.em.saved) do
				all[#all + 1] = copyTable(saved)
			end
			return all
		end
		-- The row of a frame in the layout in use, or in layout number `index`.
		function W.emRow(name, index)
			local current = layouts()[index or W.em.active]
			for _, row in ipairs(current and current.systems or {}) do
				if nameOfRow(row) == name then
					return row
				end
			end
		end
		-- The row of a frame as a saved layout holds it, to change what the game has saved by hand (a spot the player set in Edit Mode).
		function W.emSetRow(name, index, change)
			local current = W.em.saved[index - #presets]
			for _, row in ipairs(current.systems) do
				if nameOfRow(row) == name then
					change(row)
				end
			end
		end
		env.EditModePresetLayoutManager = {
			GetCopyOfPresetLayouts = function() return copyTable(presets) end,
			GetDefaultSystemAnchorInfo = function(_, system, systemIndex)
				for _, name in ipairs(NAMES) do
					local raw = W.rawOf[env[name]]
					if raw.system == system and raw.systemIndex == systemIndex then
						return defaultAnchor(name)
					end
				end
			end,
		}
		-- The game applies the layout in use: each row is the systemInfo of its frame and the frame is placed from it. A bar in its default position is
		-- left to the game's pass.
		function W.emApply()
			W.blizzard(function()
				local current = layouts()[W.em.active]
				for _, row in ipairs(current.systems) do
					local name = nameOfRow(row)
					local frame = env[name]
					local raw = W.rawOf[frame]
					raw.systemInfo = copyTable(row)
					frame:ClearAllPoints()
					if row.isInDefaultPosition and raw.system == 7 then
						frame:SetPoint("TOPLEFT", ui, "TOPLEFT", 0, 0)
					elseif not row.isInDefaultPosition then
						local a, scale = row.anchorInfo, frame:GetScale()
						frame:SetPoint(a.point, env[a.relativeTo] or ui, a.relativePoint, a.offsetX / scale, a.offsetY / scale)
					end
				end
				if W.gameStack then
					W.gameStack()
				end
			end)
			W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		end
		-- A layout pass of the game, which runs at each edge of a fight.
		function W.emPass()
			W.blizzard(function()
				if W.gameStack then
					W.gameStack()
				end
				-- The game puts the scale of a bar that is not in its default position at 1 (EditModeManager.lua:619).
				for _, name in ipairs({ "MultiBarRight", "MultiBarLeft" }) do
					local frame = env[name]
					if frame and not W.rawOf[frame].systemInfo.isInDefaultPosition then
						frame:SetScale(1)
					end
				end
			end)
		end
		-- A fight starts or ends: the event, the lockdown, and the game's pass.
		function W.fight(on)
			if on then
				W.fire("PLAYER_REGEN_DISABLED")
				W.combat = true
			else
				W.combat = false
				W.fire("PLAYER_REGEN_ENABLED")
			end
			W.emPass()
		end
		env.C_EditMode = {
			GetLayouts = function()
				return { activeLayout = W.em.active, layouts = copyTable(W.em.saved) }
			end,
			SaveLayouts = function(info)
				if not W.inReloadClick then
					bad(W, "SaveLayouts outside the Reload click")
				end
				W.em.log[#W.em.log + 1] = "save"
				W.em.calls[#W.em.calls + 1] = "save"
				if spec.fail then
					error("SaveLayouts failed", 0)
				end
				if W.inBlizzard == 0 and W.combat then
					bad(W, "SaveLayouts in a fight")
				end
				if W.manager.editModeActive then
					bad(W, "SaveLayouts while Edit Mode is open")
				end
				W.em.saves = W.em.saves + 1
				W.em.payloads[#W.em.payloads + 1] = copyTable(info)
				if not spec.refuse then
					local saved = {}
					for index = #presets + 1, #info.layouts do
						saved[#saved + 1] = copyTable(info.layouts[index])
					end
					W.em.saved = saved
				end
				if not spec.stay then
					W.em.active = info.activeLayout
				end
				env.C_Timer.After(0, W.emApply)
			end,
			SetActiveLayout = function(index)
				W.em.calls[#W.em.calls + 1] = "active:" .. tostring(index)
				if W.inBlizzard == 0 and W.combat then
					bad(W, "SetActiveLayout in a fight")
				end
				if W.manager.editModeActive then
					bad(W, "SetActiveLayout while Edit Mode is open")
				end
				if not spec.stay then
					W.em.active = index
				end
				env.C_Timer.After(0, W.emApply)
			end,
			IsValidLayoutName = function(name)
				return not spec.badName and type(name) == "string"
			end,
		}
		env.ReloadUI = function()
			W.reloads = (W.reloads or 0) + 1
			W.em.log[#W.em.log + 1] = "reload"
		end
		W.group = "static"
	end
	W.seal()
	W.combat = inCombat
	return W
end



-- Helpers ---------------------------------------------------------------------------------------------
-- The saved variables are the table the addon works on, so each world gets a copy.
local function deepcopy(v)
	if type(v) ~= "table" then
		return v
	end
	local c = {}
	for k, x in pairs(v) do
		c[k] = deepcopy(x)
	end
	return c
end
-- The handles open with Edit Mode only when the player asks for it, and most of what is tested here is what they do, so a world has
-- the setting on, as a saved option, unless the test says `defaults`.
local function withEditMode(opts)
	opts.saved = deepcopy(opts.saved)
	if not opts.defaults then
		opts.saved = opts.saved or {}
		opts.saved.options = opts.saved.options or {}
		if opts.saved.options["movers.editMode"] == nil then
			opts.saved.options["movers.editMode"] = true
		end
		-- The default of Positions and sizes sends a window back when it closes; most of these tests move a window and expect it to stay, unless the test says `keepDefault`.
		if not opts.keepDefault and opts.saved.options["movers.keepSpots"] == nil then
			opts.saved.options["movers.keepSpots"] = "kept"
		end
		-- The tooltip fade of the Tooltips page runs a frame while a tooltip is up; the worlds of the handles leave it to the game unless a test chooses.
		if opts.saved.options["chat.fadeOut"] == nil then
			opts.saved.options["chat.fadeOut"] = "game"
		end
		-- The page of the combat text has a handle of its own (Combat text: you), which the tests of the handles of the other frames leave out.
		if not opts.combatText and opts.saved.options["combattext.enabled"] == nil then
			opts.saved.options["combattext.enabled"] = false
		end
	end
end
-- A world that has logged in and settled. UI scale 1 unless the test says otherwise, so UIParent is 1920 by 1080.
local function mw(opts)
	opts = opts or {}
	withEditMode(opts)
	opts.uiScale = opts.uiScale or 1
	local W = mworld(opts)
	W.login()
	W.flush()
	return W
end
-- The same, but the test sets the world up between the build and the login.
local function mwBefore(opts, prep)
	opts = opts or {}
	withEditMode(opts)
	opts.uiScale = opts.uiScale or 1
	local W = mworld(opts)
	if prep then
		prep(W)
	end
	W.login()
	W.flush()
	return W
end
local function entry(W, name)
	return W.spots()[name]
end
local function nameOf(W, rel)
	if rel == W.env.UIParent then
		return "UIParent"
	end
	local raw = W.rawOf[rel]
	return raw and raw.fname or "?"
end
-- The points of a frame, and its scale, as text.
local function pts(W, frame)
	local raw = W.rawOf[frame]
	local out = {}
	for _, p in ipairs(raw.points) do
		out[#out + 1] = ("%s>%s:%s %s,%s"):format(p[1], nameOf(W, p[2]), tostring(p[3] or p[1]), g(p[4] or 0), g(p[5] or 0))
	end
	return table.concat(out, " | ") .. " @" .. g(raw.scale)
end
-- What the game gave a frame, to compare with later: the points as the frame holds them, and the scale.
local function snap(W, frame)
	local raw = W.rawOf[frame]
	local copy = { scale = raw.scale, points = {} }
	for i, p in ipairs(raw.points) do
		copy.points[i] = { p[1], p[2], p[3], p[4], p[5] }
	end
	return copy
end
local function sameAs(W, frame, was)
	local raw = W.rawOf[frame]
	if raw.scale ~= was.scale or #raw.points ~= #was.points then
		return false
	end
	for i, p in ipairs(raw.points) do
		local q = was.points[i]
		if p[1] ~= q[1] or p[2] ~= q[2] or p[3] ~= q[3] or p[4] ~= q[4] or p[5] ~= q[5] then
			return false
		end
	end
	return true
end
local function rect(W, name)
	local l, b, w, h = W.rectOf(W.env[name])
	return l, b, w, h
end
local function rectIs(W, name, l, b, w, h, eps)
	local rl, rb, rw, rh = rect(W, name)
	eps = eps or 1e-6
	return rl ~= nil and near(rl, l, eps) and near(rb, b, eps) and (w == nil or near(rw, w, eps)) and (h == nil or near(rh, h, eps))
end
local function rectText(W, name)
	local l, b, w, h = rect(W, name)
	return ("%s,%s %sx%s"):format(g(l), g(b), g(w), g(h))
end
local function allClean(W)
	return #W.violations == 0 and #W.errors == 0
end
local function problems(W)
	return table.concat(W.violations, " | "):sub(1, 300) .. " ## " .. table.concat(W.errors, " | "):sub(1, 300)
end
-- The number of calls the addon made on a frame of the game's.
local function calls(W, name, call)
	return W.rawOf[W.env[name]].calls[call] or 0
end
local function startsWith(text, head)
	return text:sub(1, #head) == head
end
local function outText(W)
	return table.concat(W.out, "\n")
end
-- Frames of the addon's that run something every frame, shown now.
local function runningFrames(W)
	local n = 0
	for _, f in ipairs(W.updaters) do
		if f.scripts and f.scripts.OnUpdate and f.shown and not f.dividers then
			n = n + 1
		end
	end
	return n
end
-- Frames that have an OnUpdate, shown or not.
local function updaterFrames(W)
	local n = 0
	for _, f in ipairs(W.updaters) do
		if f.scripts and f.scripts.OnUpdate and not f.dividers then
			n = n + 1
		end
	end
	return n
end
-- Saved settings with the options given.
local function opt(options, movers)
	return { options = options or {}, movers = movers }
end


-- Movers ----------------------------------------------------------------------------------------------

-- 75a. At login with nothing saved the module touches nothing and makes nothing.
do
	local off = mw({ saved = opt({ ["movers.enabled"] = false, ["tooltip.enabled"] = false }) })
	local W = mw()
	check("movers at login, nothing saved: no frame and no texture is made", #W.addonFrames == #off.addonFrames and #W.addonTextures == #off.addonTextures, #W.addonFrames .. " " .. #off.addonFrames)
	check("movers at login, nothing saved: nothing is hooked", W.hooks == off.hooks, W.hooks - off.hooks)
	check("movers at login, nothing saved: no frame of the addon's runs something each frame", runningFrames(W) == runningFrames(off) and updaterFrames(W) == updaterFrames(off))
	check("movers at login, nothing saved: the game's frames keep the places the game gave them", rectIs(W, "UIErrorsFrame", 704, 898, 512, 60) and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1")
	check("movers at login: the status line", W.line("Movers") == "Movers: on, 0 moved" and W.line("Tooltip") == "Tooltip: off", W.line("Movers"))
	check("movers at login: the saved table exists and is empty", type(W.spots()) == "table" and next(W.spots()) == nil)
	check("movers at login: the four callbacks of the game are watched once each, and the end of Edit Mode by the action bars as well, and the resource display of Bars.lua on Enter and Exit", W.registrants("EditMode.Enter") == 2 and W.registrants("EditMode.Exit") == 3
		and W.registrants("UIParentPanelManager.ShowUIPanel") == 1 and W.registrants("UIParentPanelManager.HideUIPanel") == 1)
	clean(W, "movers at login")
	check("movers at login: no violation", allClean(W), problems(W))
end

-- 75b. The handles: one for each listed frame that exists, none for one that does not, a window's only while it is open.
do
	local W = mw({ layout = { missing = { ZoneTextFrame = true, UIWidgetTopCenterContainerFrame = true } }, saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) })
	check("handles: none before the mover mode is opened", #W.handles() == 0)
	W.slash("move")
	check("handles: the handles of the frames that exist are shown", table.concat(W.shownHandles(), ",") == "Alerts,Buffs,Enemy cooldowns: focus,Enemy cooldowns: target,Error text,Minimap,Player frame,Tooltip", table.concat(W.shownHandles(), ","))
	check("handles: the bar is shown with its title and buttons", W.textFrame("Movers") ~= nil and W.textFrame("Pick a frame") ~= nil and W.textFrame("Reset all") ~= nil and W.textFrame("Done") ~= nil)
	check("handles: a frame that does not exist has none", W.handle("Zone text") == nil and W.handle("Top widgets") == nil)
	check("handles: a window has none while it is closed", W.handle("Character") == nil and W.handle("Quest") == nil)
	local h = W.handle("Error text")
	local l, b, w, hh = W.rectOf(h)
	check("handles: a handle covers its frame", near(l, 704) and near(b, 898) and near(w, 512) and near(hh, 60), rectText(W, "UIErrorsFrame"))
	local frame = W.rawOf[h]
	check("handles: a handle is a movable frame of the addon's on UIParent, clamped to the screen, over the game frames", frame.parent == W.env.UIParent and frame.movable and frame.clamped and frame.strata == "HIGH" and frame.mouse and frame.wheel
		and frame.drag and frame.drag[1] == "LeftButton")
	local al, ab, aw, ah = W.rectOf(W.handle("Alerts"))
	check("handles: a frame with no size to measure gets a handle of 200 by 40 with the same point", near(aw, 200) and near(ah, 40) and near(al + aw / 2, 960) and near(ab, 128), g(al) .. "," .. g(ab) .. " " .. g(aw) .. "x" .. g(ah))
	local tl, tb, tw, th = W.rectOf(W.handle("Tooltip"))
	check("handles: the tooltip handle is 250 by 150 at the spot the game puts the tooltip", near(tl, 1920 - 9 - 250) and near(tb, 85) and near(tw, 250) and near(th, 150), g(tl) .. "," .. g(tb))
	check("handles: a window opened while the handles are shown gets one", (function()
		W.openWindow("CharacterFrame")
		W.run(0.25)
		return W.handle("Character") ~= nil and W.handle("Character").shown
	end)())
	local cl, cb, cw, ch = W.rectOf(W.handle("Character"))
	check("handles: and it covers the window", near(cl, 16) and near(cb + ch, 1080 - 116) and near(cw, 338) and near(ch, 424), g(cl) .. "," .. g(cb))
	W.closeWindow("CharacterFrame")
	W.run(0.25)
	check("handles: and loses it when the window closes", not W.handle("Character").shown)
	check("handles: Done closes the handles and the bar", (function()
		W.press("Done")
		return #W.shownHandles() == 0 and not W.textFrame("Movers").shown
	end)())
	W.slash("move")
	check("handles: the slash command opens them again, without a second set of frames", #W.handles() == 9 and #W.shownHandles() == 8, #W.handles() .. " " .. #W.shownHandles())
	W.slash("move")
	check("handles: and closes them", #W.shownHandles() == 0)
	check("handles: no violation", allClean(W), problems(W))
end
do
	-- A frame whose rectangle the client withholds, and one that is too small, get a handle of the nominal size.
	local W = mwBefore({}, function(W)
		W.rawOf[W.env.UIErrorsFrame].fault.rect = "secret"
		W.rawOf[W.env.UIWidgetTopCenterContainerFrame].width = 10
		W.rawOf[W.env.UIWidgetTopCenterContainerFrame].height = 10
	end)
	W.slash("move")
	local l, b, w, h = W.rectOf(W.handle("Error text"))
	check("handles: a frame whose rectangle is withheld has a handle of 200 by 40 at its point, and nothing raises", near(w, 200) and near(h, 40) and near(l + w / 2, 960) and near(b + h, 1080), g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
	local tl, tb, tw, th = W.rectOf(W.handle("Top widgets"))
	check("handles: a frame under 16 units has the nominal handle too", near(tw, 200) and near(th, 40) and near(tl + tw / 2, 960) and near(tb + th, 1080 - 15), g(tl) .. "," .. g(tb))
	check("handles: no violation", allClean(W), problems(W))
end

-- 75c. Dragging a handle saves a point and offsets, and places the game frame.
do
	local W = mw({ saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) })
	W.slash("move")
	W.drag("Error text", 400, 700)
	local e = entry(W, "UIErrorsFrame")
	check("drag: the entry has the point of the list and the offsets from that point of UIParent", e and e.point == "TOP" and near(e.x, 656 - 960) and near(e.y, 760 - 1080) and e.kind == "hud" and e.scale == nil and e.label == nil,
		e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("drag: the game frame is on that spot, with one point on UIParent", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and rectIs(W, "UIErrorsFrame", 400, 700, 512, 60), pts(W, W.env.UIErrorsFrame))
	local l, b = W.rectOf(W.handle("Error text"))
	check("drag: and the handle covers it again", near(l, 400) and near(b, 700))
	check("drag: the status counts it", W.line("Movers") == "Movers: on, 1 moved", W.line("Movers"))
	W.drag("Error text", 100, 100)
	check("drag: dragged again, the entry is replaced and the frame follows", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -604,-920 @1" and rectIs(W, "UIErrorsFrame", 100, 100, 512, 60) and W.line("Movers") == "Movers: on, 1 moved")
	W.drag("Alerts", 1000, 500)
	local a = entry(W, "AlertFrame")
	check("drag: a frame with a handle of 200 by 40 is saved by the point of the list", a and a.point == "BOTTOM" and near(a.x, 1100 - 960) and near(a.y, 500), a and (a.point .. " " .. g(a.x) .. "," .. g(a.y)))
	check("drag: and the frame is put there", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 140,500 @1", pts(W, W.env.AlertFrame))
	W.drag("Tooltip", 50, 60)
	local t = entry(W, "FlatUITooltip")
	check("drag: the tooltip handle saves a spot and has no game frame to place", t and t.point == "BOTTOMRIGHT" and near(t.x, 300 - 1920) and near(t.y, 60) and W.env.FlatUITooltip == nil and W.line("Movers") == "Movers: on, 2 moved", W.line("Movers"))
	check("drag: a handle cannot be dropped off the screen", (function()
		W.drag("Error text", -500, 5000)
		local l2, b2 = W.rectOf(W.handle("Error text"))
		return near(l2, 0) and near(b2, 1080 - 60)
	end)())
	check("drag: the entry stays on the screen", (function()
		local e2 = entry(W, "UIErrorsFrame")
		return near(e2.x, -704) and near(e2.y, 0)
	end)())
	check("drag: no violation", allClean(W), problems(W))
	W.slash("move")
	check("drag: closing the handles leaves the frames where they were put", rectIs(W, "UIErrorsFrame", 0, 1020, 512, 60) and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 140,500 @1")
end
do
	-- A drag starts out of combat only.
	local W = mw()
	W.slash("move")
	local handle = W.handle("Error text")
	W.combat = true
	handle.scripts.OnDragStart(handle)
	check("drag: not started in combat", not handle.moving)
	W.combat = false
end

-- 75d. A saved position holds after a reload, after the game moves the frame, and when the game places it again.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" }, AlertFrame = { point = "BOTTOM", x = 140, y = 500, scale = 1.5, kind = "hud" } })
	local W = mw({ saved = saved })
	check("reload: the saved frames are where they were put at login", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5", pts(W, W.env.AlertFrame))
	check("reload: the scale is applied and the offset is divided by it, so the point stays where it was saved", rectIs(W, "AlertFrame", 1100 - 0.75, 500, 1.5, 1.5, 1e-4), rectText(W, "AlertFrame"))
	check("reload: the status counts both", W.line("Movers") == "Movers: on, 2 moved", W.line("Movers"))
	local kept = pts(W, W.env.UIErrorsFrame)
	-- The game moves the frame (the barber shop re-anchors the error text and restores the points it found).
	W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
	W.run(0.25)
	check("kept: not corrected before the half-second check", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1")
	W.run(0.25)
	check("kept: put back by the half-second check", pts(W, W.env.UIErrorsFrame) == kept, pts(W, W.env.UIErrorsFrame))
	check("kept: the check runs on a frame of the addon's own that is shown only because a saved frame is there", runningFrames(W) == 1)
	local sets, scaledSets = calls(W, "UIErrorsFrame", "SetPoint"), calls(W, "AlertFrame", "SetPoint")
	W.run(2, 0.5)
	check("kept: a frame that is in place is not touched again, scaled or not", calls(W, "UIErrorsFrame", "SetPoint") == sets and calls(W, "AlertFrame", "SetPoint") == scaledSets, calls(W, "AlertFrame", "SetPoint") - scaledSets)
	-- Events.
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.tick()
	check("kept: placed again on PLAYER_ENTERING_WORLD", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5", pts(W, W.env.AlertFrame))
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.fire("ADDON_LOADED", "Blizzard_SomethingElse")
	W.tick()
	check("kept: placed again when an addon loads", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5")
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.fire("UI_SCALE_CHANGED")
	W.flush()
	check("kept: placed again when the UI scale changes", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5")
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.fire("DISPLAY_SIZE_CHANGED")
	W.flush()
	check("kept: placed again when the display size changes", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5")
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.editMode(true)
	W.editMode(false)
	W.tick()
	check("kept: placed again when Edit Mode closes", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 93.3333,333.333 @1.5")
	check("kept: no violation", allClean(W), problems(W))
end
do
	-- The check ignores a frame that is hidden, and the option can turn it off.
	local saved = opt({}, { ZoneTextFrame = { point = "TOP", x = 50, y = -300, kind = "hud" } })
	local W = mw({ saved = saved })
	W.gamePlaces("ZoneTextFrame", "TOP", 0, -128)
	W.run(1)
	check("kept: a hidden frame is left alone by the check", pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 0,-128 @1")
	W.blizzard(function() W.env.ZoneTextFrame:Show() end)
	W.run(0.5)
	check("kept: and put back when it is shown", pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 50,-300 @1", pts(W, W.env.ZoneTextFrame))
	W.change("movers.keep", false)
	W.flush()
	check("kept: with the option off the check is not running", runningFrames(W) == 0)
	W.gamePlaces("ZoneTextFrame", "TOP", 0, -128)
	W.run(2)
	check("kept: with the option off the game's move stays", pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 0,-128 @1")
	W.change("movers.keep", true)
	W.run(0.5)
	check("kept: with the option on again it is put back", pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 50,-300 @1" and runningFrames(W) == 1, pts(W, W.env.ZoneTextFrame))
	check("kept: no violation", allClean(W), problems(W))
end
do
	-- A frame the game keeps moving is given up on after ten corrections in a minute.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } })
	local W = mw({ saved = saved })
	local corrections = 0
	for _ = 1, 14 do
		W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W.run(0.5)
		if pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 10,-200 @1" then
			corrections = corrections + 1
		end
	end
	check("kept: ten corrections and then the game wins", corrections == 10, corrections)
	check("kept: the status names the frame once", count(W.status(), "Error text is moved by the game again and again, so it is left where the game puts it.") == 1, W.status())
	check("kept: the module goes on", W.line("Movers"):sub(1, 10) == "Movers: on" and #W.errors == 0)
	-- A minute later it is tried again.
	local W2 = mw({ saved = saved })
	for _ = 1, 8 do
		W2.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W2.run(0.5)
	end
	W2.run(61)
	for _ = 1, 8 do
		W2.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W2.run(0.5)
	end
	check("kept: the count starts again after a minute", not has(W2.status(), "again and again") and pts(W2, W2.env.UIErrorsFrame) == "TOP>UIParent:TOP 10,-200 @1", W2.status())
end

-- 75e. Scale, nudge, reset.
do
	local W = mw({ saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) })
	W.slash("move")
	W.drag("Error text", 400, 700)
	W.keys.ctrl = true
	for _ = 1, 4 do
		W.wheel("Error text", 1)
	end
	check("scale: four steps up with Ctrl are 120 percent", near(entry(W, "UIErrorsFrame").scale, 1.2, 1e-9) and near(W.rawOf[W.env.UIErrorsFrame].scale, 1.2, 1e-9), g(entry(W, "UIErrorsFrame").scale))
	check("scale: the frame keeps its top centre where it was, and the offsets are divided by the scale", (function()
		local l, b, w, h = rect(W, "UIErrorsFrame")
		return near(l + w / 2, 656, 1e-6) and near(b + h, 760, 1e-6) and near(w, 512 * 1.2, 1e-6)
	end)(), rectText(W, "UIErrorsFrame"))
	check("scale: the handle says the percentage and covers the larger frame", W.handleText("Error text") == "Error text 120%" and (function()
		local l, b, w, h = W.rectOf(W.handle("Error text"))
		return near(w, 614.4, 1e-6)
	end)(), tostring(W.handleText("Error text")))
	for _ = 1, 40 do
		W.wheel("Error text", 1)
	end
	check("scale: up to 200 percent and no further", near(entry(W, "UIErrorsFrame").scale, 2, 1e-9) and near(W.rawOf[W.env.UIErrorsFrame].scale, 2, 1e-9))
	for _ = 1, 60 do
		W.wheel("Error text", -1)
	end
	check("scale: down to 50 percent and no further", near(entry(W, "UIErrorsFrame").scale, 0.5, 1e-9) and near(W.rawOf[W.env.UIErrorsFrame].scale, 0.5, 1e-9))
	W.wheel("Error text", 1)
	check("scale: in steps of 5 percent", near(entry(W, "UIErrorsFrame").scale, 0.55, 1e-9), g(entry(W, "UIErrorsFrame").scale))
	W.keys.ctrl = false
	local y0 = entry(W, "UIErrorsFrame").y
	W.wheel("Error text", 1)
	check("nudge: the wheel moves it up by one screen pixel", near(entry(W, "UIErrorsFrame").y - y0, 768 / 1080, 1e-9), g(entry(W, "UIErrorsFrame").y - y0))
	W.wheel("Error text", -1)
	W.wheel("Error text", -1)
	check("nudge: and down", near(entry(W, "UIErrorsFrame").y - y0, -768 / 1080, 1e-9))
	local x0 = entry(W, "UIErrorsFrame").x
	W.keys.shift = true
	W.wheel("Error text", 1)
	W.keys.shift = false
	check("nudge: with Shift it moves right by one pixel", near(entry(W, "UIErrorsFrame").x - x0, 768 / 1080, 1e-9) and near(entry(W, "UIErrorsFrame").y - y0, -768 / 1080, 1e-9))
	check("nudge: the frame follows", (function()
		local e = entry(W, "UIErrorsFrame")
		local k = W.rawOf[W.env.UIErrorsFrame].scale
		local p = W.rawOf[W.env.UIErrorsFrame].points[1]
		return near(p[4], e.x / k, 1e-9) and near(p[5], e.y / k, 1e-9)
	end)())
	-- The tooltip handle has no scale.
	W.drag("Tooltip", 50, 60)
	W.keys.ctrl = true
	W.wheel("Tooltip", 1)
	W.keys.ctrl = false
	check("scale: the tooltip handle takes no scale and does not nudge on Ctrl", entry(W, "FlatUITooltip").scale == nil and near(entry(W, "FlatUITooltip").y, 60))
	-- A wheel on a handle with no entry makes the entry from where the handle is.
	W.wheel("Alerts", 1)
	local a = entry(W, "AlertFrame")
	check("nudge: a wheel on a handle that was never dragged saves the spot and moves one pixel", a and a.point == "BOTTOM" and near(a.x, 0) and near(a.y, 128 + 768 / 1080, 1e-9), a and (g(a.x) .. "," .. g(a.y)))
	check("scale: no violation", allClean(W), problems(W))
end
do
	local W = mw()
	local before = { err = snap(W, W.env.UIErrorsFrame), alert = snap(W, W.env.AlertFrame), zone = snap(W, W.env.ZoneTextFrame) }
	W.slash("move")
	W.drag("Error text", 400, 700)
	W.keys.ctrl = true
	W.wheel("Error text", 1)
	W.wheel("Error text", 1)
	W.keys.ctrl = false
	W.drag("Alerts", 1000, 500)
	W.drag("Zone text", 10, 10)
	W.rightClick("Error text")
	check("reset: the frame has the points and the scale the game gave it, to the digit", sameAs(W, W.env.UIErrorsFrame, before.err), pts(W, W.env.UIErrorsFrame))
	check("reset: a frame that was put back is not said to come back after /reload", not has(outText(W), "after /reload"), outText(W))
	check("reset: the saved entry is gone and the other frames are left alone", entry(W, "UIErrorsFrame") == nil and entry(W, "AlertFrame") ~= nil and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 140,500 @1")
	check("reset: its handle is back over the game's place", (function()
		local l, b = W.rectOf(W.handle("Error text"))
		return W.handle("Error text").shown and near(l, 704) and near(b, 898) and W.handleText("Error text") == "Error text"
	end)())
	W.press("Reset all")
	W.press("Click again to reset")
	check("reset all: every frame is as the game had it", sameAs(W, W.env.AlertFrame, before.alert) and sameAs(W, W.env.ZoneTextFrame, before.zone))
	check("reset all: nothing is saved and the message is printed", next(W.spots()) == nil and has(outText(W), "Moved frames are back where the game has them."), outText(W))
	check("reset: no violation", allClean(W), problems(W))
end
do
	-- Reset from the slash command, with the handles closed.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, scale = 1.5, kind = "hud" }, AlertFrame = { point = "BOTTOM", x = 140, y = 500, kind = "hud" } })
	local W = mw({ saved = saved })
	check("reset by command: the frame is moved first", pts(W, W.env.UIErrorsFrame) ~= "TOP>UIParent:TOP 0,-122 @1")
	W.slash("move reset")
	check("reset by command: the game's place and scale are back, the table is empty", W.rawOf[W.env.UIErrorsFrame].scale == 1 and pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and next(W.spots()) == nil and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1")
	W.run(2)
	check("reset by command: and nothing puts them back", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1")
	check("reset by command: no handle is shown with the mover mode closed", #W.shownHandles() == 0, table.concat(W.shownHandles(), ","))
end
do
	-- A frame whose points the client would not give is not put back.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mwBefore({ saved = saved }, function(W)
		W.rawOf[W.env.UIErrorsFrame].fault.point = "secret"
	end)
	W.rawOf[W.env.UIErrorsFrame].fault.point = nil
	W.slash("move reset")
	check("reset: a frame whose points were withheld stays where it was put, and the player is told", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and has(outText(W), "Error text goes back to its place after /reload."), outText(W))
end


-- 75f. The picker: the frame under the mouse is found by walking up from it, and Alt takes it.
local function grabWorld(prep, opts)
	local W = mwBefore(opts or {}, prep)
	W.slash("grab")
	return W
end
-- The mouse is over `leaf` and a few frames are drawn.
local function lookAt(W, leaf)
	W.foci = { leaf }
	W.update(0.1)
end
local function tag(W)
	local _, text = W.pickTag()
	return text and text.text
end
local function press(W, key, down)
	W.keys[key] = down
	W.update(0.02)
end

do
	local W = grabWorld()
	check("picker: /flatui grab opens the handles, the tag and the message", #W.shownHandles() > 0 and W.pickTag() and W.pickTag().shown and has(outText(W), "Point at a frame and press Alt to take it. Shift picks the frame around it."), outText(W))
	check("picker: the tag is empty before the mouse is over anything", (tag(W) or "") == "")
	lookAt(W, W.icon)
	check("picker: from a texture it walks up to the first frame that passes, and shows its name", tag(W) == "TestPanelInner", tostring(tag(W)))
	local box = W.pickBox()
	check("picker: and draws a box over that frame", box and box.shown and (function()
		local l, b, w, h = W.rectOf(box)
		return near(l, 605) and near(b, 645) and near(w, 40) and near(h, 20)
	end)(), box and rectText(W, "TestPanelInner"))
	press(W, "shift", true)
	check("picker: Shift steps to the frame around it", tag(W) == "TestPanel", tostring(tag(W)))
	check("picker: and the box follows", (function()
		local l, b, w, h = W.rectOf(W.pickBox())
		return near(l, 600) and near(b, 610) and near(w, 120) and near(h, 60)
	end)())
	W.update(0.02)
	check("picker: a press steps once however long the key is held", tag(W) == "TestPanel", tostring(tag(W)))
	press(W, "shift", false)
	press(W, "shift", true)
	check("picker: another press goes round to the first again", tag(W) == "TestPanelInner", tostring(tag(W)))
	press(W, "shift", false)
	check("picker: nothing was taken or moved by looking", next(W.spots()) == nil and pts(W, W.inner) == "TOPLEFT>TestPanel:TOPLEFT 5,-5 @1")
	W.cursor = { 700, 500 }
	W.update(0.02)
	local tl, tb, _, th = W.rectOf(W.pickTag())
	check("picker: the tag follows the cursor, 14 units to the right and 8 below it", near(tl, 714) and near(tb + th, 492), g(tl) .. "," .. g(tb))
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	local e = entry(W, "TestPanelInner")
	check("picker: Alt takes the frame at its spot, by the third of the screen its centre is in", e and e.point == "LEFT" and near(e.x, 605) and near(e.y, 115) and e.kind == "hud" and e.label == "TestPanelInner" and e.scale == nil,
		e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("picker: the frame is on the same spot as before, now anchored to UIParent alone", pts(W, W.inner) == "LEFT>UIParent:LEFT 605,115 @1" and rectIs(W, "TestPanelInner", 605, 645, 40, 20), pts(W, W.inner))
	check("picker: the tag and the box are gone and the player is told", not W.pickTag().shown and not W.pickBox().shown and has(outText(W), "TestPanelInner can be moved now."), outText(W))
	check("picker: the frame has a handle named for it", W.handle("TestPanelInner") ~= nil and W.handle("TestPanelInner").shown and near((W.rectOf(W.handle("TestPanelInner"))), 605))
	check("picker: it is counted and kept in place", W.line("Movers") == "Movers: on, 1 moved" and runningFrames(W) >= 1)
	W.gamePlaces("TestPanelInner", "TOPLEFT", 5, -5, W.panel)
	W.run(0.5)
	check("picker: and the half-second check keeps it there", pts(W, W.inner) == "LEFT>UIParent:LEFT 605,115 @1", pts(W, W.inner))
	W.drag("TestPanelInner", 1500, 100)
	e = entry(W, "TestPanelInner")
	check("picker: a taken frame is dragged like a listed one, and its point follows the third its centre is in", e and e.point == "BOTTOMRIGHT" and near(e.x, 1540 - 1920) and near(e.y, 100), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	W.rightClick("TestPanelInner")
	check("picker: reset forgets it and puts it back, and the handle goes", entry(W, "TestPanelInner") == nil and pts(W, W.inner) == "TOPLEFT>TestPanel:TOPLEFT 5,-5 @1" and not W.handle("TestPanelInner").shown, pts(W, W.inner))
	check("picker: no violation", allClean(W), problems(W))
end

do
	-- What the picker walks past.
	local W = grabWorld(function(W)
		local ui = W.env.UIParent
		local function child(name, more)
			more = more or {}
			more.parent = W.panel
			more.point = more.point or { "CENTER", W.panel, "CENTER", 0, 0 }
			more.width, more.height = more.width or 30, more.height or 30
			return W.bframe(name, more)
		end
		child("TestForbiddenChild", { forbidden = true })
		local fparent = W.bframe("TestForbiddenParent", { point = { "CENTER", ui, "CENTER", 500, 0 }, width = 100, height = 100, forbidden = true })
		W.bframe("TestUnderForbidden", { parent = fparent, point = { "CENTER", ui, "CENTER", 500, 0 }, width = 30, height = 30 })
		child("TestOk")
		W.unnamed = child(nil)
		W.mismatch = child("TestMismatch")
		W.env.TestMismatch = W.panel
		child("TestRestricted")
		W.rawOf[W.env.TestRestricted].restricted = true
		child("TestAnchorSecret")
		W.rawOf[W.env.TestAnchorSecret].anchoringSecret = true
		child("TestRestrictedWithheld")
		W.rawOf[W.env.TestRestrictedWithheld].fault.restricted = "secret"
		child("TestAnchorSecretWithheld")
		W.rawOf[W.env.TestAnchorSecretWithheld].fault.anchoringSecret = "error"
		child("TestRectWithheld")
		W.rawOf[W.env.TestRectWithheld].fault.rect = "secret"
		child("TestRectError")
		W.rawOf[W.env.TestRectError].fault.rect = "error"
		child("TestProtected", { protected = true })
		child("TestProtectedByChild", { protected = true, explicit = false })
		child("TestProtectedWithheld", { protected = true })
		W.rawOf[W.env.TestProtectedWithheld].fault.protected = "secret"
		child("TestProtectedFirstWithheld")
		W.rawOf[W.env.TestProtectedFirstWithheld].fault.protected = "secretFirst"
		child("TestProtectedExplicitWithheld", { protected = true })
		W.rawOf[W.env.TestProtectedExplicitWithheld].fault.protected = "error"
		child("TestTwoPoints")
		W.blizzard(function() W.env.TestTwoPoints:SetPoint("TOP", W.panel, "TOP", 0, 0) end)
		child("TestNoPoint")
		W.rawOf[W.env.TestNoPoint].points = {}
		child("TestNoMethod")
		W.rawOf[W.env.TestNoMethod].IsAnchoringRestricted = nil
		child("TestTypeWithheld")
		W.rawOf[W.env.TestTypeWithheld].fault.objectType = "secret"
		child("TestNameWithheld")
		W.rawOf[W.env.TestNameWithheld].fault.name = "secret"
		child("TestParentWithheld")
		W.rawOf[W.env.TestParentWithheld].fault.parent = "secret"
		child("TestParentError")
		W.rawOf[W.env.TestParentError].fault.parent = "error"
		child("TestIndexOnly", { fields = { layoutIndex = 1 } })
		child("TestSystemBase", { fields = { SetPointBase = function() end } })
	end)
	local function over(name)
		lookAt(W, W.env[name])
		return tag(W)
	end
	check("picker: a frame that passes is offered itself", over("TestOk") == "TestOk", tostring(over("TestOk")))
	check("picker: a forbidden frame offers nothing, and nothing around it either", over("TestForbiddenChild") == "")
	check("picker: a frame under a forbidden one offers nothing", over("TestUnderForbidden") == "")
	check("picker: an unnamed frame hands over to the frame around it", (function()
		lookAt(W, W.unnamed)
		return tag(W) == "TestPanel"
	end)(), tostring(tag(W)))
	check("picker: a name that is not the global of that frame hands over", (function() lookAt(W, W.mismatch) return tag(W) end)() == "TestPanel", tostring(tag(W)))
	check("picker: restricted anchoring hands over", over("TestRestricted") == "TestPanel")
	check("picker: secret anchoring hands over", over("TestAnchorSecret") == "TestPanel")
	check("picker: an answer about restricted anchoring that is withheld hands over", over("TestRestrictedWithheld") == "TestPanel")
	check("picker: an answer about secret anchoring that fails hands over", over("TestAnchorSecretWithheld") == "TestPanel")
	check("picker: a rectangle that is withheld hands over", over("TestRectWithheld") == "TestPanel")
	check("picker: a rectangle that fails hands over", over("TestRectError") == "TestPanel")
	check("picker: a frame that is protected itself hands over", over("TestProtected") == "TestPanel")
	check("picker: a frame that is protected only through a child is offered", over("TestProtectedByChild") == "TestProtectedByChild")
	check("picker: an answer about protection that is withheld hands over", over("TestProtectedWithheld") == "TestPanel")
	check("picker: an answer about protection whose first value is withheld is judged by the second", over("TestProtectedFirstWithheld") == "TestProtectedFirstWithheld")
	check("picker: an answer about protection that fails hands over", over("TestProtectedExplicitWithheld") == "TestPanel")
	check("picker: a frame with two points hands over", over("TestTwoPoints") == "TestPanel")
	check("picker: a frame with no point hands over", over("TestNoPoint") == "TestPanel")
	check("picker: a client without the method hands over", over("TestNoMethod") == "TestPanel")
	check("picker: a type that is withheld hands over", over("TestTypeWithheld") == "TestPanel")
	check("picker: a name that is withheld hands over", over("TestNameWithheld") == "TestPanel")
	check("picker: a frame whose parent is withheld offers nothing", over("TestParentWithheld") == "")
	check("picker: a frame whose parent fails offers nothing", over("TestParentError") == "")
	check("picker: a layout index in a frame whose parent has no Layout is no sign of a container", over("TestIndexOnly") == "TestIndexOnly")
	check("picker: a frame that a container with Layout lays out by index hands over", over("TestLayoutChild") == "TestLayoutBox", tostring(tag(W)))
	check("picker: a frame with isManagedFrame in a refused container offers nothing", over("TestManagedFrame") == "")
	check("picker: a frame with only layoutParent in a refused container offers nothing", over("TestPlaced") == "")
	check("picker: a frame with SetPointBase that Edit Mode has not set up is left, and the frame around it is offered", over("TestSystemBase") == "TestPanel", tostring(tag(W)))
	check("picker: the frame a handle belongs to is not offered", (function()
		lookAt(W, W.handle("Error text"))
		return tag(W) == ""
	end)())
	check("picker: UIParent itself offers nothing", over("UIParent") == "")
	check("picker: a frame whose parents do not reach UIParent offers nothing", over("TestLost") == "")
	check("picker: no frame under the mouse offers nothing", (function()
		W.foci = {}
		W.update(0.1)
		return tag(W) == ""
	end)())
	-- Alt takes what is chosen, and only that.
	lookAt(W, W.env.TestRestricted)
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	check("picker: Alt takes the frame around when the one pointed at is refused", entry(W, "TestPanel") ~= nil and entry(W, "TestRestricted") == nil)
	check("picker: no violation", allClean(W), problems(W))
end

do
	-- Edit Mode's frames are offered by their own names, also the frame around a child of one.
	local art
	local W = grabWorld(function(W)
		art = W.btexture(W.minimapChild, nil, "test-art")
	end)
	check("picker: a system frame is offered", (function() lookAt(W, W.minimap) return tag(W) end)() == "MinimapCluster", tostring(tag(W)))
	check("picker: so is a protected system frame", (function() lookAt(W, W.playerFrame) return tag(W) end)() == "PlayerFrame", tostring(tag(W)))
	check("picker: a child of a system frame offers the system frame", (function() lookAt(W, W.minimapChild) return tag(W) end)() == "MinimapCluster", tostring(tag(W)))
	check("picker: a texture in a child of a system frame too", art ~= nil and (function() lookAt(W, art) return tag(W) end)() == "MinimapCluster", tostring(tag(W)))
	check("picker: a box is drawn over it", W.pickBox().shown)
	local before = { snap(W, W.playerFrame), snap(W, W.buffFrame) }
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	check("picker: Alt takes it, and the other system frames are not touched", entry(W, "MinimapCluster") ~= nil and entry(W, "PlayerFrame") == nil and entry(W, "BuffFrame") == nil
		and sameAs(W, W.playerFrame, before[1]) and sameAs(W, W.buffFrame, before[2]))
	check("picker: no violation, and no Lua method of a system frame was called", allClean(W), problems(W))
end

do
	-- Frames of the game that a container or a manager lays out, tooltips, and the rest of the list the picker refuses.
	local names = { "GameTooltip", "ShoppingTooltip1", "ShoppingTooltip2", "ItemRefTooltip", "RightManagedFrameContainer",
		"PlayerBottomManagedFrameContainer", "GroupLootContainer", "UIWidgetBelowMinimapContainerFrame", "UIWidgetPowerBarContainerFrame", "PlayerPowerBarAlt",
		"TargetFrameToT", "FocusFrameToT", "ContainerFrameCombinedBags", "GeneralDockManager", "WorldMapFrame", "SettingsPanel", "GameMenuFrame", "HelpFrame",
		"BarberShopFrame", "CompactRaidFrameManager", "TargetFrameSpellBar", "FocusFrameSpellBar", "ContainerFrame12", "ChatFrame7", "StaticPopup3", "Boss2TargetFrameSpellBar",
		"BottomManagedFrameContainer", "TotemFrame", "ChatFrame2", "ContainerFrame3" }
	local W = grabWorld(function(W)
		for _, name in ipairs(names) do
			if not W.env[name] or not W.rawOf[W.env[name]] then
				W.bframe(name, { point = { "CENTER", W.env.UIParent, "CENTER", 0, -400 }, width = 60, height = 30 })
			end
		end
		W.bframe("GameTooltipLike", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -400 }, width = 60, height = 30 })
		W.bframe("Boss12TargetFrameSpellBar", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -400 }, width = 60, height = 30 })
		W.bframe("ChatFrame", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -400 }, width = 60, height = 30 })
		W.bframe("MyContainerFrame2", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -400 }, width = 60, height = 30 })
	end, { layout = { tooltip = true, casts = true } })
	W.hover(W.panel)
	local offered = {}
	for _, name in ipairs(names) do
		lookAt(W, W.env[name])
		if tag(W) ~= "" then
			offered[#offered + 1] = name .. "=" .. tostring(tag(W))
		end
	end
	check("picker: none of the frames the design refuses is offered", #offered == 0, table.concat(offered, " "))
	local ok = {}
	for _, name in ipairs({ "GameTooltipLike", "Boss12TargetFrameSpellBar", "ChatFrame", "MyContainerFrame2" }) do
		lookAt(W, W.env[name])
		ok[#ok + 1] = tostring(tag(W) == name)
	end
	check("picker: the refusals are by whole name, and a name that only looks like one is offered", table.concat(ok, ",") == "true,true,true,true", table.concat(ok, ","))
	check("picker: no violation", allClean(W), problems(W))
end

do
	-- A window is saved as a window, and is placed again when the panel manager has opened it.
	local W = grabWorld(function(W) end)
	W.openWindow("CharacterFrame")
	lookAt(W, W.env.CharacterFrame)
	check("picker: an open window is offered", tag(W) == "CharacterFrame")
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	local e = entry(W, "CharacterFrame")
	check("picker: it is saved as a window", e and e.kind == "window" and e.point == "TOPLEFT" and near(e.x, 16) and near(e.y, -116), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	W.drag("Character", 500, 300)
	check("picker: dragged", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1", pts(W, W.env.CharacterFrame))
	W.closeWindow("CharacterFrame")
	W.openWindow("CharacterFrame")
	check("windows: the module places it as soon as the panel manager has, so it is never drawn at the default spot", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1", pts(W, W.env.CharacterFrame))
	local timers = #W.timers
	W.openWindow("CharacterFrame")
	check("windows: several panel events in one frame make one timer", #W.timers == timers, #W.timers .. " " .. timers)
	W.tick()
	check("windows: the module places it after the panel manager has, on the next frame", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1", pts(W, W.env.CharacterFrame))
	W.closeWindow("CharacterFrame")
	W.tick()
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	W.run(1)
	check("windows: a closed window is left alone by the half-second check", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1")
	check("windows: no violation", allClean(W), problems(W))
end


-- 75g. Combat: nothing is created or anchored on a protected frame, and what is allowed still happens.
do
	local saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" }, AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" },
		MailFrame = { point = "TOPLEFT", x = 400, y = -400, kind = "window" }, QuestFrame = { point = "TOPLEFT", x = 500, y = -500, kind = "window" },
		ZoneTextFrame = { point = "TOP", x = 0, y = -50, scale = 1.5, kind = "hud" } })
	local function build(movers)
		local queued = 0
		local W = mwBefore({ saved = movers and saved or opt({}), combat = true }, function(W)
			local orig = W.ns.OutOfCombat
			W.ns.OutOfCombat = function(fn)
				queued = queued + 1
				return orig(fn)
			end
			W.rawOf[W.env.CharacterFrame].protected = true
			W.rawOf[W.env.MailFrame].protected = true
			W.rawOf[W.env.MailFrame].explicit = false
			W.rawOf[W.env.QuestFrame].fault.protected = "secret"
			W.rawOf[W.env.QuestFrame].protected = false
		end)
		return W, function() return queued end
	end
	local control, controlQueued = build(false)
	local W, queued = build(true)
	local was = { snap(W, W.env.CharacterFrame), snap(W, W.env.MailFrame), snap(W, W.env.QuestFrame) }
	check("combat at login: a frame that is not protected is placed at once", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,300 @1" and pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 0,-33.3333 @1.5", pts(W, W.env.ZoneTextFrame))
	check("combat at login: a frame that is protected, one that is protected through a child, and one that will not say are not touched", sameAs(W, W.env.CharacterFrame, was[1]) and sameAs(W, W.env.MailFrame, was[2])
		and sameAs(W, W.env.QuestFrame, was[3]) and calls(W, "CharacterFrame", "ClearAllPoints") == 0 and calls(W, "MailFrame", "SetPoint") == 1 and calls(W, "QuestFrame", "SetScale") == 0)
	check("combat at login: no violation", allClean(W), problems(W))
	check("combat at login: each of the three waits once", queued() - controlQueued() == 3, queued() - controlQueued())
	local base = queued()
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.openWindow("CharacterFrame")
	W.tick()
	W.run(2)
	check("combat: events, a window opening and the check queue nothing more", queued() == base and allClean(W), queued() - base)
	check("combat: and the window the panel manager placed is not moved in combat", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1", pts(W, W.env.CharacterFrame))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("combat ends: the three are placed, once each", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-300 @1" and pts(W, W.env.MailFrame) == "TOPLEFT>UIParent:TOPLEFT 400,-400 @1"
		and pts(W, W.env.QuestFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-500 @1", pts(W, W.env.CharacterFrame))
	check("combat ends: with one ClearAllPoints each", calls(W, "CharacterFrame", "ClearAllPoints") == 1 and calls(W, "MailFrame", "ClearAllPoints") == 1, calls(W, "CharacterFrame", "ClearAllPoints"))
	check("combat ends: no violation", allClean(W), problems(W))
end
do
	-- The mover mode closes when combat starts and does not open in combat.
	local W = mw()
	W.slash("move")
	W.drag("Error text", 400, 700)
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	check("combat starts: the handles and the bar are closed, and the player is told", #W.shownHandles() == 0 and not W.textFrame("Movers").shown and outText(W) == "Every frame can be moved here. Drag a blue box or a window's title. Ctrl and scroll changes size. Right-click puts it back.\nHandles closed for combat.", outText(W))
	check("combat starts: the position that was saved stays", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1")
	W.out = {}
	W.slash("move")
	check("combat: /flatui move does not open them", #W.shownHandles() == 0 and outText(W) == "Movers open out of combat.", outText(W))
	W.out = {}
	W.slash("grab")
	check("combat: /flatui grab does not open them either, and says so once", #W.shownHandles() == 0 and outText(W) == "Movers open out of combat.", outText(W))
	W.out = {}
	W.editMode(true)
	check("combat: nor does Edit Mode", #W.shownHandles() == 0 and outText(W) == "Movers open out of combat.", outText(W))
	W.editMode(false)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.slash("move")
	check("combat ends: they open again", #W.shownHandles() == 9)
	W.fire("PLAYER_REGEN_DISABLED")
	W.out = {}
	W.fire("PLAYER_REGEN_DISABLED")
	check("combat: the event with the mover mode closed says nothing", #W.out == 0, outText(W))
	check("combat: no violation", allClean(W), problems(W))
end
do
	-- The picker stops with the mover mode.
	local W = mw()
	W.slash("grab")
	W.foci = { W.icon }
	W.update(0.1)
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	check("combat starts: the picker stops, its tag and box are hidden", not W.pickTag().shown and not W.pickBox().shown)
	W.keys.alt = true
	W.update(0.1)
	W.keys.alt = false
	check("combat: and Alt takes nothing", next(W.spots()) == nil and allClean(W), problems(W))
end
do
	-- Reset in combat: what is not protected goes back at once, what is protected when combat ends, and nothing is created.
	local saved = opt({}, { AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" }, CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" } })
	local W = mwBefore({ saved = saved }, function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end)
	local frames = #W.addonFrames
	W.combat = true
	W.slash("move reset")
	check("reset in combat: the frame that is not protected goes back at once", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1", pts(W, W.env.AlertFrame))
	check("reset in combat: the protected one waits", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-300 @1" and next(W.spots()) == nil)
	check("reset in combat: no frame is made on UIParent", #W.addonFrames == frames and #W.violations == 0, #W.addonFrames - frames .. " " .. problems(W))
	check("reset in combat: nothing failed", not has(W.status(), "failed") and not has(W.status(), "stopped"), W.status())
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("reset in combat: the protected one goes back when combat ends", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1", pts(W, W.env.CharacterFrame))
	W.run(2)
	check("reset in combat: and nothing puts them back", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1" and allClean(W), problems(W))
end

-- 75h. Saved entries that are not valid are dropped when the module starts.
do
	local nan, inf = 0 / 0, math.huge
	local good = { point = "TOP", x = -304, y = -320, kind = "hud" }
	local saved = opt({}, {
		UIErrorsFrame = good,
		AlertFrame = "text", ZoneTextFrame = 5, SubZoneTextFrame = true,
		EventToastManagerFrame = { point = "MIDDLE", x = 1, y = 1 },
		UIWidgetTopCenterContainerFrame = { point = "TOP", x = nan, y = 1 },
		CharacterFrame = { point = "TOP", x = 1, y = inf },
		QuestFrame = { point = "TOP", x = "5", y = 1 },
		GossipFrame = { point = "TOP", x = 1 },
		MerchantFrame = { x = 1, y = 1 },
		MailFrame = { point = {}, x = 1, y = 1 },
		BankFrame = { point = "TOPLEFT", x = 99999, y = -99999, scale = 5, kind = "weird", label = 12 },
		FriendsFrame = { point = "BOTTOMLEFT", x = -50, y = -50, scale = 0.1, kind = "window", label = "Friends" },
		DressUpFrame = { point = "CENTER", x = 20, y = 30, scale = "big" },
		TaxiFrame = { point = "CENTER", x = 20, y = 30, scale = 1.15 },
		AddonList = { point = "TOPRIGHT", x = -99999, y = 99999 },
		SubZoneTextFrame = { point = "BOTTOM", x = 0, y = 99999 },
		TradeFrame = { point = "TOP", x = -inf, y = 1 },
		NotAFrameAtAll = { point = "TOP", x = 10, y = -10 },
		[7] = { point = "TOP", x = 0, y = 0 },
	})
	local W = mw({ saved = saved })
	local m = W.spots()
	local kept = {}
	for name in pairs(m) do
		kept[#kept + 1] = tostring(name)
	end
	table.sort(kept)
	check("saved entries: only the valid ones are kept", table.concat(kept, ",") == "AddonList,BankFrame,DressUpFrame,FriendsFrame,NotAFrameAtAll,SubZoneTextFrame,TaxiFrame,UIErrorsFrame", table.concat(kept, ","))
	check("saved entries: a scale goes into its range, a kind to hud or window, a label to a string or nothing",
		m.BankFrame.scale == 2 and m.BankFrame.kind == "hud" and m.BankFrame.label == nil
		and m.FriendsFrame.scale == 0.5 and m.FriendsFrame.kind == "window" and m.FriendsFrame.label == "Friends"
		and m.DressUpFrame.scale == nil and m.DressUpFrame.x == 20, tostring(m.BankFrame.scale))
	check("saved entries: a spot past the edge of the screen is kept as it was saved", m.BankFrame.x == 99999 and m.BankFrame.y == -99999 and m.FriendsFrame.x == -50 and m.FriendsFrame.y == -50,
		tostring(m.BankFrame.x) .. "," .. tostring(m.BankFrame.y))
	local function placed(name)
		local p = W.rawOf[W.env[name]].points[1]
		return p and (g(p[4]) .. "," .. g(p[5]) .. " @" .. g(W.rawOf[W.env[name]].scale)) or "none"
	end
	-- Placed, the spot is cut to the screen: the offsets are in the units of the frame, which is scaled.
	-- 48 units of a frame stay on the screen: the bank, 772 wide at scale 2, has its top left corner 48 units inside the right and bottom edges, and the friends
	-- window, 169 wide at scale 0.5, is 50 units out at the left and top edges and keeps the rest of its width.
	check("saved entries: a spot past the edge of the screen is placed with 48 units of the frame on it", placed("BankFrame") == "936,-516 @2" and placed("FriendsFrame") == "-100,-100 @0.5"
		and W.rawOf[W.env.FriendsFrame].scale == 0.5, placed("BankFrame") .. " " .. placed("FriendsFrame"))
	check("saved entries: the valid ones are placed and the dropped ones are not", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and pts(W, W.env.MailFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1"
		and pts(W, W.env.QuestFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1" and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1")
	check("saved entries: a frame that does not exist is kept and costs nothing", m.NotAFrameAtAll ~= nil and allClean(W), problems(W))
	check("saved entries: and on every side, with the numbers saved left as they are", m.AddonList.x == -99999 and m.AddonList.y == 99999 and m.SubZoneTextFrame.y == 99999 and m.SubZoneTextFrame.x == 0
		and placed("AddonList") == "-1872,432 @1" and placed("SubZoneTextFrame") == "0,1032 @1", placed("AddonList") .. " " .. placed("SubZoneTextFrame"))
	check("saved entries: a scale is held to a multiple of 5 percent", near(m.TaxiFrame.scale, 1.15, 1e-9), tostring(m.TaxiFrame.scale))
	check("saved entries: the status counts what was placed", W.line("Movers") == "Movers: on, 7 moved", W.line("Movers"))
	local W2 = mw({ saved = { movers = "junk", options = {} } })
	check("saved entries: a table of movers that is not a table is made new", type(W2.spots()) == "table" and next(W2.spots()) == nil and allClean(W2))
end

-- 75i. Nothing is hooked on a moved frame, and nothing is written on one.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, scale = 1.5, kind = "hud" }, CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" } })
	local control = mw()
	local W = mwBefore({ saved = saved }, function(W)
		W.keysBefore = {}
		for _, name in ipairs({ "UIErrorsFrame", "CharacterFrame" }) do
			local keys = {}
			for key in pairs(W.rawOf[W.env[name]]) do
				keys[key] = true
			end
			W.keysBefore[name] = keys
		end
	end)
	W.slash("move")
	W.drag("Error text", 100, 100)
	W.keys.ctrl = true
	W.wheel("Error text", 1)
	W.keys.ctrl = false
	W.openWindow("CharacterFrame")
	W.run(1)
	W.slash("move reset")
	W.slash("move")
	check("no hook: the movers add none, whatever is moved", W.hooks == control.hooks, W.hooks - control.hooks)
	local extra = {}
	for _, name in ipairs({ "UIErrorsFrame", "CharacterFrame" }) do
		for key in pairs(W.rawOf[W.env[name]]) do
			if not W.keysBefore[name][key] then
				extra[#extra + 1] = name .. "." .. key
			end
		end
	end
	check("no field: a moved frame has no field it did not have", #extra == 0, table.concat(extra, " "))
	check("no script: a moved frame has none of the addon's", next(W.rawOf[W.env.UIErrorsFrame].scripts) == nil and next(W.rawOf[W.env.CharacterFrame].scripts) == nil)
	check("no call that is not allowed: the violations are empty", allClean(W), problems(W))
end

-- 75j. Edit Mode.
do
	local W = mw()
	W.editMode(true)
	check("Edit Mode: the handles and the bar show when it opens", #W.shownHandles() == 6 and W.textFrame("Movers").shown, #W.shownHandles())
	W.editMode(false)
	check("Edit Mode: and close when it closes", #W.shownHandles() == 0 and not W.textFrame("Movers").shown)
	W.slash("move")
	W.editMode(true)
	W.editMode(false)
	check("Edit Mode: handles opened by the player stay open when it closes", #W.shownHandles() == 9)
	W.slash("move")
	check("Edit Mode: and the command closes them", #W.shownHandles() == 0)
	W.change("movers.editMode", false)
	W.editMode(true)
	check("Edit Mode: with the option off it opens nothing", #W.shownHandles() == 0)
	W.editMode(false)
	W.change("movers.editMode", true)
	W.editMode(true)
	check("Edit Mode: with the option on again it does", #W.shownHandles() == 6)
	W.change("movers.editMode", false)
	check("Edit Mode: switching the option off while it is open leaves them until it closes", #W.shownHandles() == 6)
	W.editMode(false)
	check("Edit Mode: and they close then", #W.shownHandles() == 0)
	check("Edit Mode: no violation", allClean(W), problems(W))
end
do
	-- The game moves a frame while Edit Mode is open; the frame is put back when it closes.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mw({ saved = saved })
	W.editMode(true)
	W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
	W.editMode(false)
	check("Edit Mode: on closing the frames are placed on the next frame", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1")
	W.tick()
	check("Edit Mode: and are placed then", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1", pts(W, W.env.UIErrorsFrame))
	check("Edit Mode: several events make one pass", (function()
		local timers = #W.timers
		W.editMode(true)
		W.editMode(false)
		W.editMode(true)
		W.editMode(false)
		-- One for the frames, one for the action buttons and one for the resource display and swing timers.
		return #W.timers == timers + 3
	end)(), #W.timers)
end
do
	-- A game that has no EventRegistry, one that refuses the callbacks, and one that lacks the manager frame.
	local W = mw({ layout = { noEventRegistry = true } })
	W.slash("move")
	check("no EventRegistry: the commands work and nothing raises", #W.shownHandles() == 9 and allClean(W), problems(W))
	local W2 = mwBefore({}, function(W) W.registry.failRegister = true end)
	check("EventRegistry refuses: the module says so and goes on", has(W2.status(), "Movers: Edit Mode and the window panels could not be watched. RegisterCallback failed") and W2.line("Movers") == "Movers: on, 0 moved", W2.status())
	W2.slash("move")
	check("EventRegistry refuses: the commands still work", #W2.shownHandles() == 9 and allClean(W2), problems(W2))
	local W3 = mwBefore({}, function(W) W.env.EditModeManagerFrame = nil end)
	W3.editMode(true)
	check("no Edit Mode manager: nothing raises", allClean(W3), problems(W3))
end

-- 75k. Other addons that move frames.
for _, addon in ipairs({ "MoveAny", "MoveAnything", "BlizzMove", "EditModeExpanded", "TweaksForever" }) do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mwBefore({ saved = saved }, function(W) W.loadedAddons[addon] = true end)
	check(addon .. " loaded: no frame is moved and nothing is watched", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and W.registrants("EditMode.Enter") == 1 and runningFrames(W) == 0)
	check(addon .. " loaded: the status says why", has(W.status(), "Movers: " .. addon .. " is loaded, so frames are not moved.") and W.line("Movers") == "Movers: on, 0 moved", W.status())
	local said = { W.slash("move"), W.slash("grab"), W.slash("move reset") }
	local line = ("Movers are off while %s is loaded. A fixed tooltip stays at the bottom right."):format(addon)
	check(addon .. " loaded: the commands say so", said[1] == line and said[2] == line and said[3] == line and #W.shownHandles() == 0, table.concat(said, "|"))
	W.editMode(true)
	check(addon .. " loaded: Edit Mode opens nothing", #W.shownHandles() == 0 and allClean(W), problems(W))
end
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mwBefore({ saved = saved }, function(W)
		W.env.C_AddOns = nil
		W.env.IsAddOnLoaded = function(name) return W.loadedAddons[name] == true end
		W.loadedAddons.BlizzMove = true
	end)
	check("another mover loaded, on a client with the old function: the module does not start", has(W.status(), "Movers: BlizzMove is loaded") and pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1")
	local W2 = mwBefore({ saved = saved }, function(W) W.env.C_AddOns = nil end)
	check("a client with neither function: the module starts", pts(W2, W2.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and allClean(W2), problems(W2))
	local W3 = mwBefore({ saved = saved }, function(W) W.env.C_AddOns = { } end)
	check("a client whose C_AddOns has no IsAddOnLoaded: the module starts", pts(W3, W3.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and allClean(W3), problems(W3))
end

-- 75l. The page switch and the options, through their controls.
do
	local saved = opt({ ["movers.enabled"] = false }, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, scale = 1.5, kind = "hud" } })
	local off = mw({ saved = opt({ ["movers.enabled"] = false, ["tooltip.enabled"] = false }) })
	local W = mw({ saved = saved })
	local was = snap(W, W.env.UIErrorsFrame)
	check("switch off at login: nothing is placed, nothing watched, nothing made", sameAs(W, W.env.UIErrorsFrame, was) and pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and W.registrants("EditMode.Enter") == 1
		and #W.addonFrames == #off.addonFrames and runningFrames(W) == 0 and W.hooks == off.hooks, #W.addonFrames .. " " .. #off.addonFrames)
	check("switch off at login: the status says off", W.line("Movers") == "Movers: off", W.line("Movers"))
	local said = { W.slash("move"), W.slash("grab"), W.slash("move reset") }
	check("switch off at login: the commands say so", said[1] == "Movers are off in the options." and said[2] == said[1] and said[3] == said[1], table.concat(said, "|"))
	W.editMode(true)
	check("switch off at login: Edit Mode opens nothing", #W.shownHandles() == 0 and W.registrants("EditMode.Enter") == 1)
	W.run(2)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.flush()
	check("switch off at login: events and time change nothing", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and allClean(W), problems(W))
	W.change("movers.enabled", true)
	W.flush()
	check("switched on later: the module starts, the frame is placed and the status counts it", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -202.667,-213.333 @1.5" and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env.UIErrorsFrame))
	check("switched on later: the callbacks are watched, once each", W.registrants("EditMode.Enter") == 2 and W.registrants("UIParentPanelManager.HideUIPanel") == 1)
	-- Edit Mode is still open: the frame of the resource display looks at it every frame, besides the check of the movers.
	check("switched on later: the check runs", runningFrames(W) == 2)
	W.slash("move")
	check("switched on later: the commands work", #W.shownHandles() == 6)
	W.change("movers.enabled", false)
	W.flush()
	check("switched off again: the frame has the points and scale the game gave it", sameAs(W, W.env.UIErrorsFrame, was), pts(W, W.env.UIErrorsFrame))
	check("switched off again: the handles and the bar are closed and the check stopped", #W.shownHandles() == 0 and not W.textFrame("Movers").shown and runningFrames(W) == 1)
	check("switched off again: the status says off", W.line("Movers") == "Movers: off")
	W.gamePlaces("UIErrorsFrame", "TOP", 0, -100)
	W.run(2)
	W.editMode(true)
	check("switched off again: a move of the game stays and Edit Mode opens nothing", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-100 @1" and #W.shownHandles() == 0)
	W.editMode(false)
	W.change("movers.enabled", true)
	W.flush()
	check("switched on again: placed again, and the callbacks are not added twice", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -202.667,-213.333 @1.5" and W.registrants("EditMode.Enter") == 2 and W.registrants("UIParentPanelManager.ShowUIPanel") == 1, pts(W, W.env.UIErrorsFrame))
	check("switched on again: the saved position was kept through it all", entry(W, "UIErrorsFrame").x == -304 and entry(W, "UIErrorsFrame").scale == 1.5)
	check("switch: no violation", allClean(W), problems(W))
end
do
	-- The mover mode is open when the switch goes off.
	local W = mw()
	W.slash("grab")
	W.foci = { W.icon }
	W.update(0.1)
	W.change("movers.enabled", false)
	W.flush()
	check("switched off while open: the handles, the bar, the tag and the box are closed", #W.shownHandles() == 0 and not W.textFrame("Movers").shown and not W.pickTag().shown and not W.pickBox().shown)
	W.keys.alt = true
	W.update(0.1)
	W.keys.alt = false
	check("switched off while open: Alt takes nothing", next(W.spots()) == nil and allClean(W), problems(W))
end
do
	-- Dependencies: only the switch is usable when the page is off.
	local W = mw()
	W.openPanel()
	local wrong = {}
	local function agree()
		for _, row in ipairs(ALL) do
			if row.page == "movers" and W.enabled(row.path) ~= usable(W, row) then
				wrong[#wrong + 1] = row.path
			end
		end
	end
	agree()
	check("options: every control of the page is usable at the start", #wrong == 0 and W.enabled("movers.editMode") and W.enabled("movers.keep"), table.concat(wrong, " "))
	W.change("movers.enabled", false)
	agree()
	check("options: with the switch off the two others are greyed and the switch is not", #wrong == 0 and not W.enabled("movers.editMode") and not W.enabled("movers.keep") and W.enabled("movers.enabled"), table.concat(wrong, " "))
	W.change("movers.enabled", true)
	agree()
	check("options: and usable again with the switch on", #wrong == 0 and W.enabled("movers.editMode") and W.enabled("movers.keep"), table.concat(wrong, " "))
	W.defaults()
	check("options: Defaults leave the page on and the handles out of Edit Mode", W.ns.Get("movers.enabled") == true and W.ns.Get("movers.editMode") == false and W.ns.Get("movers.keep") == true)
end


-- 75m. Forbidden frames are skipped and never read.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" }, AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" },
		TestForbidden = { point = "CENTER", x = 0, y = 0, kind = "hud" }, CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" } })
	local W = mwBefore({ saved = saved }, function(W)
		W.rawOf[W.env.UIErrorsFrame].forbidden = true
		W.rawOf[W.env.CharacterFrame].forbidden = true
		W.bframe("TestForbidden", { point = { "CENTER", W.env.UIParent, "CENTER", 0, 0 }, width = 50, height = 50, forbidden = true })
	end)
	check("forbidden frames: the others are placed and the forbidden ones are not read", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,300 @1" and allClean(W), problems(W))
	W.slash("move")
	check("forbidden frames: a forbidden frame has no handle", W.handle("Error text") == nil and W.handle("Alerts") ~= nil and W.handle("Zone text") ~= nil and allClean(W), problems(W))
	W.openWindow("FriendsFrame")
	W.run(2)
	W.editMode(true)
	W.editMode(false)
	W.openWindow("CharacterFrame")
	W.tick()
	W.slash("grab")
	W.foci = { W.env.UIErrorsFrame }
	W.update(0.1)
	W.foci = { W.env.TestForbidden }
	W.update(0.1)
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	W.slash("move reset")
