	W.fire("PLAYER_REGEN_DISABLED")
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("forbidden frames: opening, picking, resetting, Edit Mode and combat read none of them", allClean(W), problems(W))
