end
do
	-- The tooltip handle needs no game frame.
	local W = mwBefore({ saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) }, function(W) W.rawOf[W.env.AlertFrame].forbidden = true end)
	W.slash("move")
	W.drag("Tooltip", 100, 100)
	check("forbidden frames: the tooltip handle works whatever else is forbidden", entry(W, "FlatUITooltip") ~= nil and allClean(W), problems(W))
end

-- 75n. Values the client withholds, at every read the movers make.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, scale = 1.25, kind = "hud" }, AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } })
	local faults = {
		{ "protection withheld", function(r) r.fault.protected = "secret" end },
		{ "protection, first answer withheld", function(r) r.fault.protected = "secretFirst" end },
		{ "shown withheld", function(r) r.fault.shown = "secret" end },
		{ "points withheld", function(r) r.fault.point = "secret" end },
		{ "relative frame withheld", function(r) r.fault.point = "secretRelative" end },
		{ "offset withheld", function(r) r.fault.point = "secretX" end },
		{ "offset a string", function(r) r.fault.point = "string" end },
		{ "points fail", function(r) r.fault.point = "error" end },
		{ "number of points withheld", function(r) r.fault.numPoints = "secret" end },
		{ "scale withheld", function(r) r.fault.scale = "secret" end },
		{ "effective scale withheld", function(r) r.fault.effScale = "secret" end },
		{ "effective scale zero", function(r) r.fault.effScale = "zero" end },
		{ "rectangle withheld", function(r) r.fault.rect = "secret" end },
		{ "rectangle fails", function(r) r.fault.rect = "error" end },
		{ "rectangle a string", function(r) r.fault.rect = "string" end },
		{ "name withheld", function(r) r.fault.name = "secret" end },
	}
	for _, f in ipairs(faults) do
		local W = mwBefore({ saved = saved }, function(W) f[2](W.rawOf[W.env.UIErrorsFrame]) end)
		W.run(1)
		W.slash("move")
		for _, label in ipairs({ "Error text" }) do
			local h = W.handle(label)
			if h and h.shown then
				pcall(W.drag, label, 300, 300)
				pcall(W.wheel, label, 1)
				W.keys.ctrl = true
				pcall(W.wheel, label, 1)
				W.keys.ctrl = false
			end
		end
		W.run(1)
		W.slash("grab")
		W.foci = { W.env.UIErrorsFrame }
		W.update(0.1)
		W.slash("move reset")
		W.slash("move")
		W.combat = true
		W.fire("PLAYER_REGEN_DISABLED")
		W.run(1)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("withheld, " .. f[1] .. ": no error, no violation, no frame counted as failed and the module goes on", allClean(W) and not has(W.status(), "Movers: stopped") and not has(W.line("Movers"), "failed"), problems(W) .. " " .. (W.line("Movers") or ""))
	end
	local others = {
		{ "the size of UIParent withheld", function(W) W.uiSizeFault = "secret" end },
		{ "the size of UIParent fails", function(W) W.uiSizeFault = "error" end },
		{ "the size of UIParent zero", function(W) W.uiSizeFault = "zero" end },
		{ "the scale of UIParent withheld", function(W) W.uiInner.fault.effScale = "secret" end },
		{ "the scale of UIParent zero", function(W) W.uiInner.fault.effScale = "zero" end },
		{ "the number of points withheld on every frame", function(W) W.numPointsFault = "secret" end },
		{ "the number of points failing on every frame", function(W) W.numPointsFault = "error" end },
		{ "the cursor withheld", function(W) W.cursorFault = "secret" end },
		{ "the frames under the mouse failing", function(W) W.fociFault = "error" end },
		{ "the frame under the mouse withheld", function(W) W.foci = { SECRET } end },
	}
	for _, f in ipairs(others) do
		local W = mwBefore({ saved = saved }, f[2])
		W.run(1)
		W.slash("grab")
		W.foci = W.foci[1] == SECRET and W.foci or { W.env.UIErrorsFrame }
		W.update(0.1)
		W.update(0.1)
		pcall(W.drag, "Alerts", 300, 300)
		pcall(W.wheel, "Alerts", 1)
		W.slash("move reset")
		W.slash("move")
		W.run(1)
		W.fire("UI_SCALE_CHANGED")
		W.flush()
		check("withheld, " .. f[1] .. ": no error, no violation, no frame counted as failed and the module goes on", allClean(W) and not has(W.status(), "Movers: stopped") and not has(W.line("Movers"), "failed"), problems(W) .. " " .. (W.line("Movers") or ""))
	end
end
do
	-- A frame whose points cannot be read is placed again every half second and given up on after ten.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mw({ saved = saved })
	W.rawOf[W.env.UIErrorsFrame].fault.point = "secret"
	W.run(8, 0.5)
	check("withheld points: the frame is put again at every check, ten times", calls(W, "UIErrorsFrame", "ClearAllPoints") == 11, calls(W, "UIErrorsFrame", "ClearAllPoints"))
	check("withheld points: and then given up on, with a line in the status", has(W.status(), "Error text is moved by the game again and again, so it is left where the game puts it.") and allClean(W), W.status())
end
do
	-- A secret answer from the game at the time of the first move: the points are not kept, and reset says so.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	for _, fault in ipairs({ "secret", "secretRelative", "secretX", "error", "string" }) do
		local W = mwBefore({ saved = saved }, function(W) W.rawOf[W.env.UIErrorsFrame].fault.point = fault end)
		W.rawOf[W.env.UIErrorsFrame].fault.point = nil
		W.slash("move reset")
		check("first move with points " .. fault .. ": reset leaves the frame and tells the player", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and has(outText(W), "Error text goes back to its place after /reload."), outText(W))
	end
	local W = mwBefore({ saved = saved }, function(W) W.numPointsFault = "error" end)
	W.numPointsFault = nil
	W.slash("move reset")
	check("first move with the number of points failing: the same", has(outText(W), "Error text goes back to its place after /reload.") and allClean(W), outText(W))
end

-- 75o. Failures: a frame that fails is skipped and counted once, five stop the module and give the game's places back.
do
	local saved = opt({}, { AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" }, UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" },
		ZoneTextFrame = { point = "TOP", x = 0, y = -50, kind = "hud" } })
	local W = mwBefore({ saved = saved }, function(W)
		W.rawOf[W.env.AlertFrame].ClearAllPoints = function() error("ClearAllPoints failed", 0) end
	end)
	check("one frame fails: the others are placed and the failure is counted", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP 0,-50 @1"
		and W.line("Movers") == "Movers: on, 2 moved, 1 failed. ClearAllPoints failed", W.line("Movers"))
	W.run(8)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.flush()
	check("one frame fails: however often it is tried it counts once", W.line("Movers"):match("^Movers: on, 2 moved, 1 failed%.") ~= nil, W.line("Movers"))
	check("one frame fails: the frame is left as the game has it and nothing else is touched", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1" and #W.violations == 0)
	W.slash("move")
	check("one frame fails: the handles open", #W.shownHandles() == 9)
end
do
	local names = { "AlertFrame", "UIErrorsFrame", "ZoneTextFrame", "SubZoneTextFrame", "MailFrame" }
	local movers = { UIWidgetTopCenterContainerFrame = { point = "TOP", x = 0, y = -50, kind = "hud" } }
	for _, name in ipairs(names) do
		movers[name] = { point = "TOP", x = 10, y = -200, kind = "hud" }
	end
	local control = mw()
	local W = mw({ saved = opt({}, movers) })
	check("movers moved: the good frame is moved first", pts(W, W.env.UIWidgetTopCenterContainerFrame) == "TOP>UIParent:TOP 0,-50 @1")
	W.slash("move")
	for _, name in ipairs(names) do
		W.rawOf[W.env[name]].shown = true
		W.gamePlaces(name, "TOP", 0, -100)
		W.rawOf[W.env[name]].ClearAllPoints = function() error("ClearAllPoints failed", 0) end
	end
	W.run(0.5)
	check("five frames fail: the module stops with the first reason", W.line("Movers") == "Movers: stopped. ClearAllPoints failed", W.line("Movers"))
	check("five frames fail: the player is told once", count(outText(W), "Flat UI: Movers stopped. /flatui status shows why. Type /reload if the look is left half changed.") == 1, outText(W))
	check("five frames fail: the frame that was moved is back where the game had it", pts(W, W.env.UIWidgetTopCenterContainerFrame) == "TOP>UIParent:TOP 0,-15 @1", pts(W, W.env.UIWidgetTopCenterContainerFrame))
	check("five frames fail: the handles and the bar are closed and the check has stopped", #W.shownHandles() == 0 and not W.textFrame("Movers").shown and runningFrames(W) == 0)
	check("five frames fail: the other modules are not affected", W.line("Cast bars") == control.line("Cast bars") and W.line("Windows") == control.line("Windows") and W.line("Tooltip") == control.line("Tooltip"))
	local said = W.slash("move")
	check("five frames fail: the commands say so", said == "Movers stopped. /flatui status shows why.", said)
	W.editMode(true)
	W.openWindow("CharacterFrame")
	W.run(2)
	check("five frames fail: Edit Mode, windows and time change nothing", #W.shownHandles() == 0 and #W.errors == 0 and W.line("Movers") == "Movers: stopped. ClearAllPoints failed", problems(W))
end

-- 75p. /flatui status, and settings saved by earlier versions.
do
	local W = mw({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } }) })
	local lines = {}
	for line in (W.status() .. "\n"):gmatch("([^\n]*)\n") do
		lines[#lines + 1] = line
	end
	check("status: one line for Movers and one for Tooltip, in the order of the areas", TOC.inOrder(lines, { "Movers: on, 1 moved", "Bar block: off", "Bar blocks: on", "Tooltip: off", "Fonts: off", "Fading: off", "Game settings: 16 of 16 rows not turned down so far" })
		and lines[#lines] == "Game settings: 16 of 16 rows not turned down so far", table.concat(lines, "|"))
	check("status: /flatui status prints the same lines", W.slash("status") == W.status(), W.slash("status"))
	local help = W.slash("help")
	check("help: the commands of the movers", has(help, "/flatui move - show or hide the handles that move frames") and has(help, "/flatui move reset - put every moved frame back where the game has it")
		and has(help, "/flatui move reset windows - put every window back to its default place and size") and has(help, "/flatui grab - pick the frame under the mouse and move it\n/flatui block facts - what the game says about the action bars and Edit Mode layouts\n/flatui blocks - the bars used as blocks"), help)
end
do
	-- Version 0.1.0 kept its switches in the table itself.
	local W = mw({ saved = { nameplates = false, thickness = 2, swing = true } })
	local db = W.env.FlatUIDB
	check("0.1.0: the old switches and thickness are read as before", W.ns.Get("nameplates.enabled") == false and W.ns.Get("swing.enabled") == true and W.ns.Get("general.thickness") == 2 and db.nameplates == nil and db.thickness == nil)
	check("0.1.0: the new pages start at their defaults and the table of movers is made", type(W.spots()) == "table" and next(W.spots()) == nil and W.ns.Get("movers.enabled") == true and W.ns.Get("tooltip.mode") == "cursor" and W.ns.Get("tooltip.enabled") == false
		and W.ns.Get("castbars.playerSize") == false and W.line("Movers") == "Movers: on, 0 moved")
	check("0.1.0: nothing is changed on screen", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and allClean(W), problems(W))
	-- Version 0.2.0 kept options only.
	local W2 = mw({ saved = { options = { ["windows.opacity"] = 55, ["nameplates.dim"] = true, ["castbars.target"] = false, ["general.scaleOn"] = false } } })
	local o = W2.options()
	check("0.2.0: the saved options are loaded unchanged", o["windows.opacity"] == 55 and o["nameplates.dim"] == true and o["castbars.target"] == false and W2.ns.Get("windows.opacity") == 55 and W2.ns.Get("castbars.target") == false)
	check("0.2.0: the settings it did not know are at their defaults and are not saved", W2.ns.Get("movers.keep") == true and W2.ns.Get("tooltip.scope") == "common" and o["movers.keep"] == nil and o["tooltip.mode"] == nil and o["castbars.playerWidth"] == nil)
	check("0.2.0: the table of movers is made empty", type(W2.spots()) == "table" and next(W2.spots()) == nil and allClean(W2), problems(W2))
	-- A table saved by this version loads as it is.
	local keep = { options = { ["movers.keep"] = false, ["tooltip.mode"] = "fixed", ["tooltip.point"] = "TOP", ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 300 },
		movers = { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } } }
	local W3 = mw({ saved = keep })
	check("0.3.0: its options and positions load as they were saved", W3.ns.Get("movers.keep") == false and W3.ns.Get("tooltip.mode") == "fixed" and W3.ns.Get("tooltip.point") == "TOP" and W3.ns.Get("castbars.playerWidth") == 300
		and entry(W3, "UIErrorsFrame").x == -304, tostring(W3.ns.Get("tooltip.mode")))
end

-- 75q. A client that lacks a global the movers use.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local function without(name, act)
		local W = mwBefore({ saved = saved }, function(W) W.env[name] = nil end)
		pcall(act, W)
		return W
	end
	local function stopped(W)
		return has(W.status(), "Movers: stopped") or #W.errors > 0
	end
	local W = without("GetTime", function(W)
		for _ = 1, 14 do
			W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
			W.run(0.5)
		end
	end)
	check("no GetTime: the movers work and still give up on a frame the game keeps moving", not stopped(W) and has(W.status(), "Error text is moved by the game again and again, so it is left where the game puts it."), problems(W))
	W = without("UIPanelWindows", function(W)
		W.slash("grab")
		W.foci = { W.env.CharacterFrame }
		W.openWindow("CharacterFrame")
		W.update(0.1)
		W.keys.alt = true
		W.update(0.02)
	end)
	check("no UIPanelWindows: a frame is taken as an ordinary one", not stopped(W) and entry(W, "CharacterFrame") and entry(W, "CharacterFrame").kind == "hud", problems(W))
	W = without("IsControlKeyDown", function(W)
		W.slash("move")
		W.wheel("Error text", 1)
	end)
	check("no IsControlKeyDown: a turn of the wheel does not stop the movers", not stopped(W), problems(W))
	W = without("IsShiftKeyDown", function(W)
		W.slash("move")
		W.wheel("Error text", 1)
		W.slash("grab")
	end)
	check("no IsShiftKeyDown: the wheel and the picker do not stop the movers", not stopped(W), problems(W))
	W = without("IsAltKeyDown", function(W)
		W.slash("grab")
		W.foci = { W.icon }
		W.update(0.1)
	end)
	check("no IsAltKeyDown: the picker does not stop the movers", not stopped(W), problems(W))
	W = without("GetCursorPosition", function(W)
		W.slash("grab")
		W.foci = { W.icon }
		W.update(0.1)
	end)
	check("no GetCursorPosition: the picker does not stop the movers", not stopped(W), problems(W))
	W = without("GetMouseFoci", function(W)
		W.slash("grab")
		W.update(0.1)
		W.update(0.1)
	end)
	check("no GetMouseFoci: the picker finds nothing and nothing raises", not stopped(W) and (W.pickTag() == nil or (W.pickTag().fonts[1].text or "") == ""), problems(W))
	W = without("EditModeManagerFrame", function(W)
		W.slash("move")
		W.editMode(true)
	end)
	check("no EditModeManagerFrame: the commands work", not stopped(W) and #W.shownHandles() == 9, problems(W))
end


-- Tooltip ---------------------------------------------------------------------------------------------

local TIP_POINTS = { "TOPLEFT", "TOP", "TOPRIGHT", "LEFT", "CENTER", "RIGHT", "BOTTOMLEFT", "BOTTOM", "BOTTOMRIGHT" }
local TIP_FRAC = { TOPLEFT = { 0, 1 }, TOP = { 0.5, 1 }, TOPRIGHT = { 1, 1 }, LEFT = { 0, 0.5 }, CENTER = { 0.5, 0.5 }, RIGHT = { 1, 0.5 },
	BOTTOMLEFT = { 0, 0 }, BOTTOM = { 0.5, 0 }, BOTTOMRIGHT = { 1, 0 } }
-- A world with the tooltip and the options the test gives.
local function tw(options, extra, prep)
	local o = extra or {}
	o.layout = o.layout or {}
	o.layout.tooltip = true
	o.saved = o.saved or opt(options or {})
	-- The switch of the page is off by default, so a world has it on unless the test says otherwise.
	o.saved.options = o.saved.options or {}
	if o.saved.options["tooltip.enabled"] == nil then
		o.saved.options["tooltip.enabled"] = true
	end
	return mwBefore(o, prep)
end
local function tipPts(W)
	return pts(W, W.tooltip)
end
local function tipAt(W, point)
	local x, y = W.tipPoint(point)
	return x, y
end
local function atSpot(W, point, x, y)
	local px, py = W.tipPoint(point)
	return px ~= nil and near(px, x, 1e-6) and near(py, y, 1e-6)
end
local function spot(W, point)
	local x, y = W.tipPoint(point)
	return x and (g(x) .. "," .. g(y)) or "none"
end
local CORNER = "BOTTOMRIGHT>GameTooltipDefaultContainer:BOTTOMRIGHT 0,0 @1"
-- The world with a tooltip and nothing changed, to compare with.
local CONTROL = mw({ layout = { tooltip = true } })

-- 75r. Off by default: the module does nothing at all.
do
	local control = CONTROL
	local W = mw({ layout = { tooltip = true } })
	check("tooltip off by default: nothing is hooked and no frame of the addon's runs each frame", W.hooks == control.hooks and runningFrames(W) == runningFrames(control) and updaterFrames(W) == updaterFrames(control))
	W.cursor = { 500, 400 }
	W.hover(W.panel)
	check("tooltip off by default: the tooltip is where the game anchored it, at the corner of Edit Mode's box", tipPts(W) == "BOTTOMRIGHT>GameTooltipDefaultContainer:BOTTOMRIGHT 0,0 @1" and W.tipCalls("SetPoint") == 0
		and W.tipCalls("ClearAllPoints") == 0, tipPts(W))
	W.worldCursor(1)
	W.worldCursor(2)
	W.worldCursor(3)
	W.hoverAt(W.panel, "ANCHOR_RIGHT")
	W.editMode(true)
	W.editMode(false)
	W.combat = true
	W.hover(W.panel)
	W.combat = false
	W.run(1, 0.1)
	W.change("tooltip.scope", "Every tooltip")
	W.hoverAt(W.panel, "ANCHOR_RIGHT")
	W.run(1, 0.1)
	W.change("tooltip.scope", "Unit frames, action bars and the world")
	W.change("tooltip.point", "Top right")
	W.change("tooltip.x", 30)
	check("tooltip off by default: whatever happens, the addon never calls SetPoint, ClearAllPoints, SetScale or SetAnchorType on the tooltip", W.tipCalls("SetPoint") == 0 and W.tipCalls("ClearAllPoints") == 0 and W.tipCalls("SetScale") == 0
		and W.tipCalls("SetAnchorType") == 0 and W.hooks == control.hooks)
	check("tooltip off by default: no violation", allClean(W), problems(W))
	check("tooltip off by default: the status line", W.line("Tooltip") == "Tooltip: off", W.line("Tooltip"))
end

-- 75s. At the cursor: each of the nine points, the offsets, the scales.
do
	local W = tw({ ["tooltip.mode"] = "cursor" })
	check("tooltip at the cursor: the one hook is on GameTooltip_SetDefaultAnchor, no method of GameTooltip is hooked, and one frame of the addon's runs each frame when a tooltip shows", W.hooks == CONTROL.hooks + 1
		and updaterFrames(W) == updaterFrames(CONTROL) + 1 and runningFrames(W) == runningFrames(CONTROL))
	W.cursor = { 960, 540 }
	W.hover(W.panel)
	check("tooltip at the cursor: placed at once, before it is drawn, with one point on UIParent", tipPts(W) == "BOTTOMLEFT>UIParent:BOTTOMLEFT 976,556 @1", tipPts(W))
	check("tooltip at the cursor: the bottom left corner is 16 up and 16 right of the cursor", atSpot(W, "BOTTOMLEFT", 976, 556))
	check("tooltip at the cursor: the box of Edit Mode and the owner were not touched", W.tipCalls("SetScale") == 0 and calls(W, "GameTooltipDefaultContainer", "SetPoint") == 1 and calls(W, "TestPanel", "SetPoint") == 1)
	check("tooltip at the cursor: the frame that follows the cursor runs while the tooltip shows", runningFrames(W) == 1)
	W.cursor = { 1000, 500 }
	W.update(1 / 60)
	check("tooltip at the cursor: it follows the cursor on the next frame", atSpot(W, "BOTTOMLEFT", 1016, 516), spot(W, "BOTTOMLEFT"))
	local sets = W.tipCalls("SetPoint")
	W.update(1 / 60)
	W.update(1 / 60)
	check("tooltip at the cursor: a cursor that has not moved costs no call", W.tipCalls("SetPoint") == sets)
	-- The game moves it back; the tooltip is placed again within a quarter of a second.
	W.blizzard(function()
		W.tooltip:ClearAllPoints()
		W.tooltip:SetPoint("BOTTOMRIGHT", W.tooltipContainer)
	end)
	W.run(0.3, 1 / 60)
	check("tooltip at the cursor: if the game moves it, it is placed again within a quarter of a second", tipPts(W) == "BOTTOMLEFT>UIParent:BOTTOMLEFT 1016,516 @1", tipPts(W))
	W.leave()
	W.update(1 / 60)
	check("tooltip at the cursor: when the tooltip is hidden the frame stops", runningFrames(W) == 0)
	W.cursor = { 300, 300 }
	W.update(1 / 60)
	check("tooltip at the cursor: and the cursor moving changes nothing", atSpot(W, "BOTTOMLEFT", 1016, 516))
	check("tooltip at the cursor: no violation", allClean(W), problems(W))
end
do
	-- Every point, with the scales: the point of the tooltip is at the cursor plus the offsets in the units of UIParent.
	local failures = {}
	for _, uiScale in ipairs({ 1, 0.64, 0.8 }) do
		for _, tipScale in ipairs({ 1, 1.25 }) do
			local W = tw({ ["tooltip.mode"] = "cursor", ["tooltip.x"] = 24, ["tooltip.y"] = -12 }, { uiScale = uiScale }, function(W)
				W.rawOf[W.tooltip].scale = tipScale
			end)
			W.cursor = { 777, 333 }
			for _, point in ipairs(TIP_POINTS) do
				W.ns.Set("tooltip.point", point)
				W.leave()
				W.update(1 / 60)
				W.hover(W.panel)
				local wantX, wantY = 777 / uiScale + 24, 333 / uiScale - 12
				if not atSpot(W, point, wantX, wantY) then
					failures[#failures + 1] = ("ui %s tip %s %s: %s want %s,%s"):format(g(uiScale), g(tipScale), point, spot(W, point), g(wantX), g(wantY))
				end
				local p = W.rawOf[W.tooltip].points[1]
				if #W.rawOf[W.tooltip].points ~= 1 or p[1] ~= point or p[2] ~= W.env.UIParent or p[3] ~= "BOTTOMLEFT" then
					failures[#failures + 1] = ("%s: anchored as %s"):format(point, tipPts(W))
				end
			end
		end
	end
	check("tooltip at the cursor: all nine points, offsets, UI scales and tooltip scales put the point where the cursor and offsets say", #failures == 0, table.concat(failures, "; "):sub(1, 400))
	-- The offsets change what a point is placed at.
	local W = tw({ ["tooltip.mode"] = "cursor", ["tooltip.x"] = -200, ["tooltip.y"] = 200 })
	W.cursor = { 100, 100 }
	W.hover(W.panel)
	check("tooltip at the cursor: negative and positive offsets", atSpot(W, "BOTTOMLEFT", -100, 300), spot(W, "BOTTOMLEFT"))
end

-- 75t. Fixed: the Tooltip handle of the movers.
do
	local W = tw({ ["tooltip.mode"] = "fixed" })
	W.cursor = { 10, 10 }
	W.hover(W.panel)
	check("tooltip fixed: with no spot saved it is at the corner the game uses, without the offsets", atSpot(W, "BOTTOMLEFT", 1920 - 9 - 250, 85) and tipPts(W) == "BOTTOMLEFT>UIParent:BOTTOMLEFT 1661,85 @1", tipPts(W))
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip fixed: the cursor does not matter", atSpot(W, "BOTTOMLEFT", 1661, 85))
	W.leave()
	W.update(1 / 60)
	W.slash("move")
	W.drag("Tooltip", 50, 60)
	W.slash("move")
	W.hover(W.panel)
	check("tooltip fixed: after the handle is dragged it is at the new spot", atSpot(W, "BOTTOMLEFT", 50, 60), spot(W, "BOTTOMLEFT"))
	W.change("tooltip.point", "Top right")
	W.update(1 / 60)
	check("tooltip fixed: the point chosen is put at the same point of the handle", atSpot(W, "TOPRIGHT", 50 + 250, 60 + 150), spot(W, "TOPRIGHT"))
	W.change("tooltip.point", "Centre")
	W.change("tooltip.x", -40)
	W.change("tooltip.y", 0)
	W.update(1 / 60)
	check("tooltip fixed: and so is the centre, whatever the offsets are", atSpot(W, "CENTER", 50 + 125, 60 + 75), spot(W, "CENTER"))
	check("tooltip fixed: no violation", allClean(W), problems(W))
end
do
	-- A spot saved by an earlier session, a spot that is not valid, and a UI scale that is not 1.
	local W = tw({ ["tooltip.mode"] = "fixed", ["tooltip.point"] = "BOTTOMRIGHT", ["tooltip.x"] = 0, ["tooltip.y"] = 0 }, { uiScale = 0.8, saved = opt({ ["tooltip.mode"] = "fixed", ["tooltip.point"] = "BOTTOMRIGHT", ["tooltip.x"] = 0, ["tooltip.y"] = 0 },
		{ FlatUITooltip = { point = "TOPLEFT", x = 100, y = -100, kind = "hud" } }) })
	W.hover(W.panel)
	check("tooltip fixed: a saved spot is read from the table, in the units of UIParent", atSpot(W, "BOTTOMRIGHT", 100 + 250, 1350 - 100 - 150), spot(W, "BOTTOMRIGHT"))
	local W2 = tw({ ["tooltip.mode"] = "fixed" }, { saved = opt({ ["tooltip.mode"] = "fixed" }, { FlatUITooltip = { point = "NOPE", x = 1, y = 1 } }) })
	W2.hover(W2.panel)
	check("tooltip fixed: a spot that is not valid was dropped at login, and the default one is used", atSpot(W2, "BOTTOMLEFT", 1661, 85) and W2.spots().FlatUITooltip == nil, spot(W2, "BOTTOMLEFT"))
	local W3 = tw({ ["tooltip.mode"] = "fixed", ["movers.enabled"] = false })
	W3.hover(W3.panel)
	check("tooltip fixed: it does not need the movers to be on", atSpot(W3, "BOTTOMLEFT", 1661, 85) and allClean(W3), spot(W3, "BOTTOMLEFT"))
	local W4 = tw({ ["tooltip.mode"] = "fixed" }, { saved = opt({ ["tooltip.mode"] = "fixed" }, { FlatUITooltip = { point = "BOTTOMRIGHT", x = -500, y = 500, kind = "hud" } }) }, function(W) W.loadedAddons.MoveAny = true end)
	W4.hover(W4.panel)
	check("tooltip fixed: nor does it care that another mover is loaded", atSpot(W4, "BOTTOMLEFT", 1170, 500) and allClean(W4), spot(W4, "BOTTOMLEFT"))
end

-- 75u. Forbidden tooltip or parent, Edit Mode, and the other conditions on which the tooltip is left to the game.
do
	local W = tw({ ["tooltip.mode"] = "cursor" }, nil, function(W)
		W.rawOf[W.panel].forbidden = true
		W.owner2 = W.bframe("TestOwner2", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -200 }, width = 50, height = 50 })
	end)
	W.cursor = { 500, 500 }
	W.hover(W.panel)
	check("tooltip, forbidden parent: it stays where the game put it and nothing is read", tipPts(W) == CORNER and allClean(W) and runningFrames(W) == 0, tipPts(W) .. problems(W))
	W.hover(W.owner2)
	check("tooltip, a parent that is not forbidden: it is placed", atSpot(W, "BOTTOMLEFT", 516, 516))
	W.hover(W.panel)
	W.update(1 / 60)
	check("tooltip, then a forbidden parent: the tooltip is not placed again, whatever it was before", tipPts(W) == CORNER, tipPts(W))
	W.leave()
	check("tooltip, forbidden: no violation", allClean(W), problems(W))
end
do
	-- A tooltip the addon may not touch: the hook runs, reads nothing and places nothing.
	local W = tw({ ["tooltip.mode"] = "cursor" }, { layout = { tooltipForbidden = true } }, function(W)
		W.env.GameTooltip_SetDefaultAnchor = function() end
	end)
	W.cursor = { 500, 500 }
	W.env.GameTooltip_SetDefaultAnchor(W.env.GameTooltip, W.panel)
	W.update(1 / 60)
	W.fire("WORLD_CURSOR_TOOLTIP_UPDATE", 2)
	check("tooltip, forbidden tooltip: nothing is read and nothing is placed", allClean(W) and runningFrames(W) == 0, problems(W))
	local W2 = tw({ ["tooltip.mode"] = "cursor", ["tooltip.scope"] = "all" }, { layout = { tooltipForbidden = true } })
	W2.update(1 / 60)
	W2.update(1 / 60)
	check("tooltip, forbidden tooltip with every tooltip: the frame reads nothing either", allClean(W2), problems(W2))
	local W3 = tw({ ["tooltip.mode"] = "cursor" }, nil, function(W) W.env.GameTooltip_SetDefaultAnchor = function() end end)
	W3.env.GameTooltip_SetDefaultAnchor(W3.env.GameTooltip, SECRET)
	W3.env.GameTooltip_SetDefaultAnchor(SECRET, W3.panel)
	W3.env.GameTooltip_SetDefaultAnchor(nil, W3.panel)
	W3.env.GameTooltip_SetDefaultAnchor(W3.panel, W3.panel)
	check("tooltip, a hook called with a withheld tooltip, a withheld parent, none, or another frame: nothing is placed and nothing raises", allClean(W3) and runningFrames(W3) == 0 and W3.tipCalls("SetPoint") == 0, problems(W3))
end
do
	local W = tw({ ["tooltip.mode"] = "cursor" })
