do
	-- Hidden, a different anchor type, a different owner, the world events: each lets go of it.
	local shared = tw({ ["tooltip.mode"] = "cursor" })
	shared.owner2 = shared.bframe("TestOwner2", { point = { "CENTER", shared.env.UIParent, "CENTER", 0, -200 }, width = 50, height = 50 })
	local function armed()
		local W = shared
		W.leave()
		W.update(1 / 60)
		W.rawOf[W.tooltip].fault = {}
		W.cursor = { 500, 500 }
		W.hover(W.panel)
		W.update(1 / 60)
		W.base = W.tipCalls("SetPoint")
		return W
	end
	local function follows(W)
		W.cursor = { W.cursor[1] + 100, W.cursor[2] + 50 }
		W.update(1 / 60)
		return atSpot(W, "BOTTOMLEFT", W.cursor[1] + 16, W.cursor[2] + 16)
	end
	local W = armed()
	check("tooltip armed: it follows the cursor", follows(W))
	W.leave()
	W.update(1 / 60)
	W.blizzard(function() W.tooltip:Show() end)
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip hidden and shown again without the game anchoring it: it is not followed", not atSpot(W, "BOTTOMLEFT", 916, 916) and runningFrames(W) == 0, spot(W, "BOTTOMLEFT"))
	W = armed()
	W.hoverAt(W.panel, "ANCHOR_RIGHT")
	local before = tipPts(W)
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip with another anchor type: it is left to the game", tipPts(W) == before and W.tipCalls("SetPoint") == W.base, tipPts(W))
	W = armed()
	W.blizzard(function() W.tooltip:SetOwner(W.owner2, "ANCHOR_NONE") end)
	local was = tipPts(W)
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip with another owner and no anchor type: it is left to the game", tipPts(W) == was and W.tipCalls("SetPoint") == W.base, tipPts(W))
	for _, kind in ipairs({ { 2, "Cursor" }, { 3, "Nameplate" }, { 0, "None" } }) do
		W = armed()
		W.worldCursor(kind[1])
		local pt = tipPts(W)
		W.cursor = { 900, 900 }
		W.update(1 / 60)
		check("tooltip, world tooltip of the type " .. kind[2] .. ": it is left to the game", tipPts(W) == pt and W.tipCalls("SetPoint") == W.base, tipPts(W))
	end
	W = armed()
	W.worldCursor(1)
	check("tooltip, world tooltip of the Default type: it is placed like a unit tooltip", atSpot(W, "BOTTOMLEFT", 516, 516), spot(W, "BOTTOMLEFT"))
	check("tooltip, world tooltip of the Default type: and it follows", follows(W))
	W = armed()
	W.fire("WORLD_CURSOR_TOOLTIP_UPDATE", SECRET)
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip, world event with a withheld type: it is left to the game", not atSpot(W, "BOTTOMLEFT", 916, 916))
	W = armed()
	W.fire("WORLD_CURSOR_TOOLTIP_UPDATE", 1)
	check("tooltip, world event with the Default type while armed: it goes on following", follows(W))
	W = tw({ ["tooltip.mode"] = "cursor" })
	W.fire("WORLD_CURSOR_TOOLTIP_UPDATE", 3)
	check("tooltip, world event with nothing armed: nothing happens", allClean(W) and W.tipCalls("SetPoint") == 0)
	-- The owner or the anchor type cannot be read: the tooltip stays armed.
	for _, fault in ipairs({ { "owner", "secret" }, { "owner", "error" }, { "anchorType", "secret" }, { "anchorType", "error" } }) do
		W = armed()
		W.rawOf[W.tooltip].fault[fault[1]] = fault[2]
		check("tooltip with its " .. fault[1] .. " " .. fault[2] .. ": it stays armed and follows", follows(W) and allClean(W), problems(W))
	end
	for _, fault in ipairs({ "secret", "error" }) do
		W = armed()
		W.rawOf[W.tooltip].fault.shown = fault
		check("tooltip whose shown state is " .. fault .. ": it stays armed", follows(W) and allClean(W), problems(W))
	end
	-- Five placements in a row that fail stop it until the next tooltip.
	W = armed()
	local tries = 0
	W.rawOf[W.tooltip].ClearAllPoints = function() tries = tries + 1 error("ClearAllPoints failed", 0) end
	for i = 1, 8 do
		W.cursor = { 500 + i * 10, 500 }
		W.update(1 / 60)
	end
	check("tooltip, placements that fail: five tries and no more", tries == 5, tries)
	check("tooltip, placements that fail: nothing raises and the module is not stopped", allClean(W) and W.line("Tooltip") == "Tooltip: on", problems(W) .. W.line("Tooltip"))
end

-- 75v. Every tooltip.
