	W.update(1 / 60)
	check("every tooltip: and it is taken when Edit Mode closes", W.tipCalls("SetAnchorType") == was + 1)
	W.leave()
	W.update(1 / 60)
	W.worldCursor(3)
	W.update(1 / 60)
	check("every tooltip: a world tooltip of the Nameplate type is left to the game", W.tooltipRaw.anchorType == "ANCHOR_NONE" and W.tipCalls("SetAnchorType") == was + 1)
	W.leave()
	W.rawOf[W.tooltip].fault.setAnchorType = true
	W.hoverAt(W.panel, "ANCHOR_RIGHT")
	W.update(1 / 60)
	W.update(1 / 60)
	check("every tooltip: a client that refuses SetAnchorType raises nothing and leaves the tooltip alone", allClean(W) and W.tooltipRaw.anchorType == "ANCHOR_RIGHT", problems(W))
	check("every tooltip: no violation", allClean(W), problems(W))
end
