		and atSpot(W, "BOTTOMLEFT", 516, 416) and W.tipCalls("SetAnchorType") == 1, W.tooltipRaw.anchorType .. " " .. spot(W, "BOTTOMLEFT"))
	W.cursor = { 600, 400 }
	W.update(1 / 60)
	check("tooltip owner, every tooltip: once shown it follows the cursor, and the anchor type was set once", atSpot(W, "BOTTOMLEFT", 616, 416) and W.tipCalls("SetAnchorType") == 1 and allClean(W), problems(W))
	for _, anchor in ipairs({ "ANCHOR_NONE", "ANCHOR_CURSOR" }) do
		W.leave()
		W.update(1 / 60)
		local sets, points = W.tipCalls("SetAnchorType"), W.tipCalls("SetPoint")
		W.blizzard(function() W.tooltip:SetOwner(W.panel, anchor) end)
		W.update(1 / 60)
		check("tooltip owner, every tooltip: " .. anchor .. " is left alone", W.tooltipRaw.anchorType == anchor and W.tipCalls("SetAnchorType") == sets and W.tipCalls("SetPoint") == points and runningFrames(W) == 1)
	end
	W.owner3 = W.bframe("TestOwner3", { point = { "CENTER", W.env.UIParent, "CENTER", 0, -250 }, width = 50, height = 50, forbidden = true })
	local sets = W.tipCalls("SetAnchorType")
	W.blizzard(function() W.tooltip:SetOwner(W.owner3, "ANCHOR_RIGHT") end)
	check("tooltip owner, every tooltip: a forbidden owner is left alone", W.tooltipRaw.anchorType == "ANCHOR_RIGHT" and W.tipCalls("SetAnchorType") == sets and allClean(W), problems(W))
	W.rawOf[W.tooltip].fault.anchorType = "secret"
	W.blizzard(function() W.tooltip:SetOwner(W.panel, "ANCHOR_RIGHT") end)
	check("tooltip owner, every tooltip: an anchor type the client withholds is left alone and raises nothing", W.tipCalls("SetAnchorType") == sets and allClean(W), problems(W))
	-- The hooks are put on once however often the module is switched.
	local every = W.hooks
	W = tw({ ["tooltip.mode"] = "cursor" })
	local common = W.hooks
	for _ = 1, 3 do
		W.change("tooltip.scope", "Every tooltip")
		W.change("tooltip.enabled", false)
		W.change("tooltip.enabled", true)
		W.change("tooltip.scope", "Unit frames, action bars and the world")
	end
	W.change("tooltip.scope", "Every tooltip")
	check("tooltip hooks: the module hooks GameTooltip_SetDefaultAnchor only, and the scripts of GameTooltip are hooked once every tooltip is chosen, and not again", common == CONTROL.hooks + 1 and every == CONTROL.hooks + 1 and W.hooks == every
		and W.tipScriptHooks == CONTROL.tipScriptHooks + 2, common - CONTROL.hooks .. " " .. every - CONTROL.hooks .. " " .. W.hooks - CONTROL.hooks .. " " .. W.tipScriptHooks)
end

