-- 75vd. tipfade: the Fade out row of the Tooltips page speeds up the fade the game starts on GameTooltip, with the Tooltip page on or off.
do
	local FRAME = 1 / 60
	local function prep(W)
		W.env.TooltipDataProcessor = { AllTypes = "ALL", AddTooltipPostCall = function(_, fn) W.post = fn end, AddLinePostCall = function() end }
	end
	-- A world with the row at mode, the Tooltip page on or off, and the addon's SetAlpha calls on GameTooltip counted.
	local function make(mode, page, where, extra)
		local options = { ["chat.fadeOut"] = mode, ["tooltip.enabled"] = page, ["tooltip.mode"] = where or "fixed" }
		for key, value in pairs(extra or {}) do
			options[key] = value
		end
		local W = tw(options, nil, prep)
		local raw = W.tooltipRaw
		local base = raw.SetAlpha
		raw.setAlphas = 0
		raw.SetAlpha = function(...)
			if W.inBlizzard == 0 then
				raw.setAlphas = raw.setAlphas + 1
			end
			return base(...)
		end
		return W
	end
	-- One frame of the game's fade, t seconds in: the alpha falls over 1.5 seconds, the tooltip is hidden at the end, then the addon's frames run.
	local function frame(W, t)
		local raw = W.tooltipRaw
		W.blizzard(function()
			if raw.shown then
				raw.alpha = math.max(0, 0.6 * (1 - t / 1.5))
				if raw.alpha <= 0 then
					W.tooltip:Hide()
				end
			end
		end)
		W.update(FRAME)
	end
	-- The game starts the fade and runs it to the end; the result is the seconds the tooltip was up.
	local function fade(W)
		local raw, t = W.tooltipRaw, 0
		W.fade()
		while raw.shown and t < 2.5 do
			t = t + FRAME
			frame(W, t)
		end
		return t
	end
	for _, page in ipairs({ true, false }) do
		local tag = "tipfade: page " .. (page and "on" or "off") .. ": "
		local W = make("game", page)
		W.hover(W.panel)
		local t = fade(W)
		check(tag .. "As the game has it: the game's fade runs to its end and the addon does not touch the tooltip", t > 1.4 and t < 1.6 and W.tipCalls("Hide") == 0 and W.tooltipRaw.setAlphas == 0 and allClean(W), t .. " " .. problems(W))
		W = make("fast", page)
		W.hover(W.panel)
		t = fade(W)
		check(tag .. "Fast: the tooltip is hidden in about 0.2 seconds", t > 0.18 and t < 0.25 and W.tooltipRaw.shown == false and W.tipCalls("Hide") == 1 and allClean(W), t .. " " .. problems(W))
		check(tag .. "Fast: the alpha is put back for the next tooltip", W.tooltipRaw.alpha == 1, tostring(W.tooltipRaw.alpha))
		W = make("fast", page)
		W.hover(W.panel)
		W.fade()
		for i = 1, 7 do
			frame(W, i * FRAME)
		end
		check(tag .. "Fast: the alpha is brought down faster than the game's and the tooltip is still up", W.tooltipRaw.shown == true and W.tooltipRaw.alpha < 0.5 and W.tooltipRaw.alpha > 0, tostring(W.tooltipRaw.alpha))
		W = make("now", page)
		W.hover(W.panel)
		W.fade()
		W.update(FRAME)
		check(tag .. "At once: the tooltip is hidden on the first frame of the fade", W.tooltipRaw.shown == false and W.tipCalls("Hide") >= 1 and W.tooltipRaw.alpha == 1 and allClean(W), problems(W))
		W = make("now", page)
		W.hover(W.panel)
		W.update(FRAME)
		W.update(FRAME)
		check(tag .. "At once: a tooltip that is not fading stays", W.tooltipRaw.shown == true and W.tipCalls("Hide") == 0 and W.tooltipRaw.setAlphas == 0)
	end
	-- Wherever the tooltip is placed.
	do
		local W = make("fast", true, "cursor")
		W.cursor = { 500, 400 }
		W.hover(W.panel)
		fade(W)
		check("tipfade: Fast at the cursor with the Tooltip page on: the tooltip is hidden", W.tooltipRaw.shown == false and allClean(W), problems(W))
		W = make("game", true, "cursor")
		W.cursor = { 500, 400 }
		W.hover(W.panel)
		W.fade()
		W.update(FRAME)
		check("tipfade: As the game has it at the cursor: the Tooltip page still hides it at once", W.tooltipRaw.shown == false and allClean(W), problems(W))
		W = make("fast", true, "fixed")
		W.hover(W.panel)
		check("tipfade: Fast at the fixed spot: the tooltip is placed there while it is up", atSpot(W, "BOTTOMLEFT", 1661, 85), spot(W, "BOTTOMLEFT"))
		W = make("fast", false)
		W.hoverAt(W.panel, "ANCHOR_RIGHT")
		local t = fade(W)
		check("tipfade: Fast on a tooltip beside its owner with the Tooltip page off: hidden as well", t > 0.18 and t < 0.25 and W.tooltipRaw.shown == false and allClean(W), t .. " " .. problems(W))
	end
	-- A tooltip shown again during the fade keeps showing.
	do
		local W = make("fast", false)
		W.hover(W.panel)
		W.fade()
		for i = 1, 5 do
			frame(W, i * FRAME)
		end
		-- The game builds the tooltip again for what is under the mouse: the alpha is full and the post calls run.
		W.blizzard(function() W.tooltipRaw.alpha = 1 end)
		W.post(W.tooltip, { type = 0 })
		for _ = 1, 60 do
			W.update(FRAME)
		end
		check("tipfade: built again during the fade: it keeps showing at full alpha", W.tooltipRaw.shown == true and W.tooltipRaw.alpha == 1 and W.tipCalls("Hide") == 0 and allClean(W), tostring(W.tooltipRaw.alpha))
		-- The post call alone puts the alpha back, when the game left it low.
		W = make("fast", false)
		W.hover(W.panel)
		W.fade()
		for i = 1, 5 do
			frame(W, i * FRAME)
		end
		W.post(W.tooltip, { type = 0 })
		check("tipfade: built again during the fade: the alpha the addon lowered is put back", W.tooltipRaw.alpha == 1 and W.tooltipRaw.shown == true, tostring(W.tooltipRaw.alpha))
		-- The game puts the alpha back without a build or a show.
		W = make("fast", false)
		W.hover(W.panel)
		W.fade()
		for i = 1, 5 do
			frame(W, i * FRAME)
		end
		W.blizzard(function() W.tooltipRaw.alpha = 1 end)
		for _ = 1, 60 do
			W.update(FRAME)
		end
		check("tipfade: the game puts the alpha back: it keeps showing", W.tooltipRaw.shown == true and W.tooltipRaw.alpha == 1 and W.tipCalls("Hide") == 0 and allClean(W), tostring(W.tooltipRaw.alpha))
	end
	-- A tooltip given another owner during the fade, with no build and no show.
	do
		local V = { W = make("fast", false) }
		V.W.hover(V.W.panel)
		V.W.fade()
		for i = 1, 5 do
			frame(V.W, i * FRAME)
		end
		V.W.blizzard(function() V.W.tooltipRaw.owner = V.W.tooltipContainer end)
		for _ = 1, 60 do
			V.W.update(FRAME)
		end
		check("tipfade: another owner during the fade: it keeps showing at full alpha", V.W.tooltipRaw.shown == true and V.W.tooltipRaw.alpha == 1 and V.W.tipCalls("Hide") == 0 and allClean(V.W), tostring(V.W.tooltipRaw.alpha))
		V.X = make("fast", false)
		V.X.hover(V.X.panel)
		V.X.tooltipRaw.fault.owner = "secret"
		V.t = fade(V.X)
		check("tipfade: an owner that cannot be read: the fade goes on and hides it", V.X.tooltipRaw.shown == false and allClean(V.X), problems(V.X))
	end
	for _, mode in ipairs({ "fast", "now" }) do
		local tag = "tipfade: " .. mode .. ": "
		local W = make(mode, false)
		W.hover(W.panel)
		W.fade()
		if mode == "fast" then
			for i = 1, 5 do
				frame(W, i * FRAME)
			end
		end
		-- Hidden and shown again during the fade.
		W.leave()
		W.hover(W.panel)
		for _ = 1, 60 do
			W.update(FRAME)
		end
		check(tag .. "shown again during the fade: it keeps showing", W.tooltipRaw.shown == true and W.tooltipRaw.alpha == 1 and allClean(W), tostring(W.tooltipRaw.alpha))
		W.fade()
		for _ = 1, 20 do
			W.update(FRAME)
		end
		check(tag .. "and the next fade is hidden as well", W.tooltipRaw.shown == false and allClean(W), problems(W))
	end
	-- Combat.
	do
		local W = make("fast", false)
		W.hover(W.panel)
		W.combat = true
		local t = fade(W)
		W.combat = false
		check("tipfade: in combat Fast hides the tooltip in about 0.2 seconds", t > 0.18 and t < 0.25 and W.tooltipRaw.shown == false and allClean(W), t .. " " .. problems(W))
		W = make("now", false)
		W.hover(W.panel)
		W.combat = true
		W.fade()
		W.update(FRAME)
		W.combat = false
		check("tipfade: in combat At once hides the tooltip on the first frame", W.tooltipRaw.shown == false and allClean(W), problems(W))
	end
	-- The row changed with a tooltip up, and the module off.
	do
		local W = make("game", false)
		W.hover(W.panel)
		check("tipfade: As the game has it makes no frame", runningFrames(W) == 0 and updaterFrames(W) == updaterFrames(CONTROL))
		W.change("chat.fadeOut", "Fast")
		check("tipfade: the row changed to Fast with a tooltip up: the frame runs", runningFrames(W) == 1)
		W.update(FRAME)
		local t = fade(W)
		check("tipfade: and the next fade is fast", t > 0.18 and t < 0.25 and allClean(W), t .. " " .. problems(W))
		check("tipfade: the frame stops when the tooltip is hidden", runningFrames(W) == 0)
		W.hover(W.panel)
		W.change("chat.fadeOut", "As the game has it")
		check("tipfade: changed back to As the game has it: the frame stops", runningFrames(W) == 0)
		local hides = W.tipCalls("Hide")
		W.fade()
		W.update(FRAME)
		check("tipfade: and the game's fade stays", W.tooltipRaw.shown == true and W.tipCalls("Hide") == hides)
		W = make("fast", false)
		W.change("chat.enabled", false)
		W.hover(W.panel)
		W.fade()
		W.update(FRAME)
		check("tipfade: with the chat and tooltips switch off nothing is done", W.tooltipRaw.shown == true and W.tipCalls("Hide") == 0 and runningFrames(W) == 0 and allClean(W), problems(W))
	end
	-- A forbidden GameTooltip is never read.
	do
		local W = tw({ ["chat.fadeOut"] = "fast", ["tooltip.enabled"] = false }, { layout = { tooltipForbidden = true } }, prep)
		W.rawOf[W.tooltip].shown = true
		W.update(FRAME)
		W.update(FRAME)
		check("tipfade: a forbidden tooltip is left alone and no frame runs", runningFrames(W) == 0 and allClean(W), problems(W))
	end
	-- No hook on a method of GameTooltip and no field written, with taintLog 0 and 2.
	for _, value in ipairs({ "0", "2" }) do
		local W = make("fast", true, "cursor")
		W.cvars.taintLog = value
		local tag = "tipfade: taintLog " .. value .. ": "
		W.hover(W.panel)
		W.fade()
		W.update(FRAME)
		local hooked = false
		for _, name in ipairs({ "FadeOut", "Hide", "Show", "SetAlpha", "SetOwner", "GetAlpha" }) do
			hooked = hooked or INSTHOOK.wrapped(W, W.tooltip, name)
		end
		check(tag .. "no method of GameTooltip has a hook written on it, no field is written, and the scripts are hooked", not hooked and allClean(W) and W.tipScriptHooks == CONTROL.tipScriptHooks, tostring(W.tipScriptHooks))
		check(tag .. "the fade is followed all the same", W.tooltipRaw.shown == false, problems(W))
	end
end

-- 75w. The options, changed through their controls.
do
	local base = CONTROL
	local W = tw({ ["tooltip.enabled"] = false })
