	W.change("tooltip.mode", "At the cursor")
	W.update(1 / 60)
	check("tooltip option position: and back to the cursor", atSpot(W, "BOTTOMLEFT", 516, 516) and W.hooks == base.hooks + 1)
	W.change("tooltip.point", "Top left")
