	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("tooltip option switch: off, the tooltip is let go and the frame stops", atSpot(W, "TOPLEFT", 470, 525) and runningFrames(W) == 0)
	W.leave()
	W.hover(W.panel)
	check("tooltip option switch: off, the next tooltip is the game's", tipPts(W) == CORNER, tipPts(W))
	check("tooltip option switch: off, the status says so", W.line("Tooltip") == "Tooltip: off")
	W.change("tooltip.enabled", true)
	W.leave()
	W.hover(W.panel)
	check("tooltip option switch: on again, the next tooltip is placed, and nothing was hooked twice", atSpot(W, "TOPLEFT", 870, 925) and W.hooks == base.hooks + 1, spot(W, "TOPLEFT"))
