	off.change("tooltip.enabled", true)
	off.cursor = { 300, 300 }
	off.leave()
	off.hover(off.panel)
	check("tooltip switched on later: the module starts and places", atSpot(off, "BOTTOMLEFT", 316, 316) and off.hooks == base.hooks + 1 and off.line("Tooltip") == "Tooltip: on", spot(off, "BOTTOMLEFT"))
	off.change("tooltip.enabled", false)
	off.cursor = { 700, 700 }
	off.update(1 / 60)
	check("tooltip switched off again: let go", atSpot(off, "BOTTOMLEFT", 316, 316) and runningFrames(off) == 0)
	check("tooltip switch: no violation", allClean(off), problems(off))
end
do
	-- Dependencies of the page.
	local W = mw({ layout = { tooltip = true } })
	W.openPanel()
	local wrong = {}
	local function agree()
		for _, row in ipairs(ALL) do
			if row.page == "tooltip" and W.enabled(row.path) ~= usable(W, row) then
				wrong[#wrong + 1] = row.path
			end
		end
	end
	local function usableCount()
		local n = 0
		for _, row in ipairs(ALL) do
			if row.page == "tooltip" and W.enabled(row.path) then
				n = n + 1
			end
		end
		return n
	end
	agree()
	check("tooltip options: the switch is off at the start, so only the switch is usable", #wrong == 0 and usableCount() == 1 and W.enabled("tooltip.enabled"), table.concat(wrong, " ") .. " " .. usableCount())
	W.change("tooltip.enabled", true)
	agree()
	check("tooltip options: with the switch on every control of the page is usable", #wrong == 0 and W.enabled("tooltip.mode") and W.enabled("tooltip.point") and W.enabled("tooltip.x") and W.enabled("tooltip.scope"), table.concat(wrong, " "))
	W.change("tooltip.enabled", false)
	agree()
	check("tooltip options: and off again only the switch", #wrong == 0 and usableCount() == 1, table.concat(wrong, " ") .. " " .. usableCount())
end

-- 75x. Combat, values the client withholds, and failures.
do
