		{ "the scale of the tooltip failing", function(W) W.rawOf[W.tooltip].fault.effScale = "error" end },
		{ "the scale of UIParent withheld", function(W) W.uiInner.fault.effScale = "secret" end },
		{ "the scale of UIParent zero", function(W) W.uiInner.fault.effScale = "zero" end },
