do
	-- A failure inside the module stops it, tells the player once, and the game's own placing goes on.
	local W = tw({ ["tooltip.mode"] = "cursor" })
	local cast = W.line("Cast bars")
	W.cursorFault = "error"
	W.cursor = { 500, 500 }
	W.hover(W.panel)
	check("tooltip, a failure: the module stops with the reason and the player is told once", W.line("Tooltip") == "Tooltip: stopped. GetCursorPosition failed" and count(outText(W), "Flat UI: Tooltip stopped.") == 1, W.line("Tooltip") .. outText(W))
	check("tooltip, a failure: the frame is stopped and the tooltip is the game's", runningFrames(W) == 0 and tipPts(W) == CORNER, tipPts(W))
	W.cursorFault = nil
	W.leave()
	W.hover(W.panel)
