-- 75aa. Each bar's width and height, through the controls, on, off and on again.
do
	local W = cw()
	local want = { player = "300x20", pet = "250x18", target = "200x16", focus = "180x14" }
	local width = { player = 300, pet = 250, target = 200, focus = 180 }
	local height = { player = 20, pet = 18, target = 16, focus = 14 }
	for _, key in ipairs(BAR_ORDER) do
		local was = sizes(W)
		W.change("castbars." .. key .. "Size", true)
		W.flush()
		check("cast bar size " .. key .. ": switched on, the bar keeps the width and height of the game until they are chosen", size(W, key) == W.ns.Get("castbars." .. key .. "Width") .. "x" .. W.ns.Get("castbars." .. key .. "Height"), size(W, key))
		W.change("castbars." .. key .. "Width", width[key])
		W.change("castbars." .. key .. "Height", height[key])
		W.flush()
		check("cast bar size " .. key .. ": width and height are applied", size(W, key) == want[key], size(W, key))
		for _, other in ipairs(BAR_ORDER) do
			if other ~= key then
				check("cast bar size " .. key .. ": the " .. other .. " bar is not touched", size(W, other) == (W.ns.Get("castbars." .. other .. "Size") and want[other] or GAME[other]), size(W, other))
			end
		end
		W.change("castbars." .. key .. "Size", false)
		W.flush()
		check("cast bar size " .. key .. ": switched off, the bar has the game's size again", size(W, key) == GAME[key], size(W, key))
		W.change("castbars." .. key .. "Size", true)
		W.flush()
		check("cast bar size " .. key .. ": switched on again, the chosen size", size(W, key) == want[key], size(W, key))
		local _ = was
	end
	check("cast bar size: all four at once", sizes(W) == "300x20 250x18 200x16 180x14", sizes(W))
	for _, key in ipairs(BAR_ORDER) do
		W.change("castbars." .. key .. "Size", false)
	end
	W.flush()
	check("cast bar size: all four off, the game's sizes exactly", sizes(W) == "208x11 195x13 150x10 150x10" and parts(W) == DEFAULT_PARTS, sizes(W) .. " " .. parts(W))
	check("cast bar size: no violation", allClean(W), problems(W))
	-- The ranges of the sliders.
	local ns = W.ns
	ns.Set("castbars.playerWidth", 50)
	ns.Set("castbars.playerHeight", 90)
	ns.Set("castbars.targetWidth", 500)
	ns.Set("castbars.targetHeight", 2)
	check("cast bar size: the sliders hold their ranges", ns.Get("castbars.playerWidth") == 100 and ns.Get("castbars.playerHeight") == 40 and ns.Get("castbars.targetWidth") == 300 and ns.Get("castbars.targetHeight") == 6)
end

