-- 75ad. The outline follows the new size.
do
	local W = cw()
	local function ringFits(key)
		local bar = W.env[BARS[key]]
		local o = W.look(bar)
		if not o then
			return false, "no outline"
		end
		local l, b, w, h = W.place(bar)
		local tl, tb, tw, th = W.place(o.top)
		local bl, bb, bw, bh = W.place(o.bottom)
		local ll, lb, lw, lh = W.place(o.left)
		local rl, rb, rw, rh = W.place(o.right)
		if not (l and tl and bl and ll and rl) then
			return false, "no place"
		end
		local eps = 1e-6
		local ok = near(tl, l - th, eps) and near(tw, w + 2 * th, eps) and near(tb, b + h, eps) and near(bb + bh, b, eps) and near(bw, w + 2 * bh, eps)
			and near(ll + lw, l, eps) and near(lh, h, eps) and near(lb, b, eps) and near(rl, l + w, eps) and near(rh, h, eps)
		return ok, ("bar %s,%s %sx%s top %s,%s %sx%s"):format(g(l), g(b), g(w), g(h), g(tl), g(tb), g(tw), g(th))
	end
	for _, key in ipairs(BAR_ORDER) do
		local ok, detail = ringFits(key)
		check("outline, " .. key .. " bar: around the game's size", ok, detail)
		W.change("castbars." .. key .. "Size", true)
		local small = key == "target" or key == "focus"
		W.change("castbars." .. key .. "Width", small and 250 or 330)
		W.change("castbars." .. key .. "Height", small and 20 or 24)
		W.flush()
		ok, detail = ringFits(key)
		check("outline, " .. key .. " bar: follows the new size", ok, detail)
		W.change("castbars." .. key .. "Size", false)
		W.flush()
		ok, detail = ringFits(key)
		check("outline, " .. key .. " bar: and the game's size again", ok, detail)
	end
	check("outline: no violation", allClean(W), problems(W))
end

