		W.ns.OutOfCombat = function(fn)
			queued = queued + 1
			return orig(fn)
		end
		W.rawOf[W.cast.PetCastingBarFrame.bar].fault.protected = "secret"
	end)
	W.combat = true
	local queuedBefore = queued
	for _, key in ipairs(BAR_ORDER) do
		W.change("castbars." .. key .. "Size", true)
