do
	local saved = { ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.playerHeight"] = 20 }
	local cases = {
		{ "the lock state withheld", function(W) W.cast.PlayerCastingBarFrame.inner.attachedToPlayerFrame = SECRET end },
		{ "the lock state a string", function(W) W.cast.PlayerCastingBarFrame.inner.attachedToPlayerFrame = "yes" end },
		{ "the spark withheld", function(W) W.cast.PlayerCastingBarFrame.inner.Spark = SECRET end },
		{ "the spark missing", function(W) W.cast.PlayerCastingBarFrame.inner.Spark = nil end },
		{ "the text withheld", function(W) W.cast.PlayerCastingBarFrame.inner.Text = SECRET end },
		{ "the text missing", function(W) W.cast.PlayerCastingBarFrame.inner.Text = nil end },
		{ "the mask withheld", function(W) W.cast.PlayerCastingBarFrame.inner.BorderMask = SECRET end },
		{ "the mask missing", function(W) W.cast.PlayerCastingBarFrame.inner.BorderMask = nil end },
		{ "the protection withheld", function(W) W.cast.PlayerCastingBarFrame.inner.fault.protected = "secret" end },
		{ "the protection failing", function(W) W.cast.PlayerCastingBarFrame.inner.fault.protected = "error" end },
	}
	for _, c in ipairs(cases) do
		local W = cw(saved, nil, c[2])
		W.attach()
		W.detach()
		W.change("castbars.playerText", "Inside the bar")
		W.change("castbars.playerSize", false)
		W.change("castbars.playerSize", true)
		W.combat = true
		W.change("castbars.playerWidth", 330)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("cast bar size, " .. c[1] .. ": nothing raises and the size is applied", allClean(W) and has(W.status(), "Cast bars: on") and size(W, "player") == "330x20", problems(W) .. " " .. size(W, "player"))
	end
	-- A lock state that is not true counts as unlocked.
	local Y = cw(saved, nil, function(W) W.cast.PlayerCastingBarFrame.inner.attachedToPlayerFrame = "yes" end)
	Y.change("castbars.playerSize", false)
	check("cast bar size, the lock state a string: the bar is given the unlocked size", size(Y, "player") == "208x11" and parts(Y) == DEFAULT_PARTS, size(Y, "player") .. " " .. parts(Y))
	-- The lock state withheld counts as unlocked.
	local W = cw(saved, nil, function(W) W.cast.PlayerCastingBarFrame.inner.attachedToPlayerFrame = SECRET end)
	W.change("castbars.playerSize", false)
	check("cast bar size, the lock state withheld: the bar is given the unlocked size", size(W, "player") == "208x11", size(W, "player"))
end
do
	-- Bars that are not there, and a client without the two functions.
	local saved = { ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210, ["castbars.focusSize"] = true, ["castbars.focusWidth"] = 200, ["castbars.petSize"] = true, ["castbars.petWidth"] = 250 }
	local W = cw(saved, { missing = { TargetFrameSpellBar = true, PetCastingBarFrame = true } })
	check("bars missing: the others are sized and nothing raises", size(W, "focus") == "200x10" and allClean(W) and has(W.status(), "Cast bars: on"), problems(W))
	local G = cw({ ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.petSize"] = true }, { layout = { casts = { noGlobals = true } } })
	check("no PlayerFrame functions: the bars are sized, nothing is hooked, nothing raises", size(G, "player") == "320x11" and G.hooks == mw().hooks and allClean(G), problems(G))
	local M = cw({ ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320 }, { layout = { casts = { noMask = true } } })
	M.attach()
	check("no mask on the player bar: the size is applied and nothing raises", size(M, "player") == "320x11" and allClean(M), problems(M))
end

-- 75ag. Parts: bars that fail, the part that stops, and the module.
do
	local saved = { ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.petSize"] = true, ["castbars.petWidth"] = 250, ["castbars.targetSize"] = true,
		["castbars.targetWidth"] = 210, ["castbars.focusSize"] = true, ["castbars.focusWidth"] = 200 }
	local control = cw()
	local W = cw(saved, nil, function(W)
		for _, name in ipairs({ "PetCastingBarFrame", "TargetFrameSpellBar", "FocusFrameSpellBar" }) do
			W.cast[name].inner.SetWidth = function() error("SetWidth failed", 0) end
		end
	end)
	check("part stops: three bars fail, the part stops and says so once", has(W.status(), "Cast bars: size stopped. SetWidth failed") and count(W.status(), "Cast bars: size stopped.") == 1, W.status())
	check("part stops: the bar that was sized has the game's size back", size(W, "player") == "208x11" and parts(W) == DEFAULT_PARTS, size(W, "player") .. " " .. parts(W))
	check("part stops: the module goes on, with its borders", W.line("Cast bars"):match("^Cast bars: on, %d+ styled") ~= nil and W.look(W.env.PlayerCastingBarFrame) ~= nil, W.line("Cast bars"))
	check("part stops: the part stays stopped for later changes", (function()
		W.change("castbars.playerWidth", 333)
		return size(W, "player") == "208x11"
	end)())
	check("part stops: no violation", allClean(W), problems(W))
	local _ = control
end
do
	-- One bar that fails is skipped and counted; the others are sized.
	local W = cw({ ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210, ["castbars.focusSize"] = true, ["castbars.focusWidth"] = 200 },
		nil, function(W) W.cast.TargetFrameSpellBar.inner.SetWidth = function() error("SetWidth failed", 0) end end)
	check("one bar fails: the others are sized and the part goes on", size(W, "player") == "320x11" and size(W, "focus") == "200x10" and not has(W.status(), "size stopped"), sizes(W))
	W.change("castbars.focusWidth", 190)
	W.change("castbars.focusWidth", 200)
	W.flush()
	check("one bar fails: and is counted once however often it is tried", not has(W.status(), "size stopped") and size(W, "focus") == "200x10")
end
do
	-- A height that fails after the width went through: the part stops and the width goes back.
	local saved = { ["castbars.petSize"] = true, ["castbars.petWidth"] = 250, ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210, ["castbars.focusSize"] = true, ["castbars.focusWidth"] = 200 }
	local W = cw(saved, nil, function(W)
		for _, name in ipairs({ "PetCastingBarFrame", "TargetFrameSpellBar", "FocusFrameSpellBar" }) do
			W.cast[name].inner.SetHeight = function() error("SetHeight failed", 0) end
		end
	end)
	check("height fails: three bars fail and the part stops", has(W.status(), "Cast bars: size stopped. SetHeight failed"), W.status())
	check("height fails: and the bars have the game's width again, not the chosen one", sizes(W) == "208x11 195x13 150x10 150x10", sizes(W))
end
do
	-- The module off at login with sizes saved: nothing is touched; on later; off again.
	local saved = { ["castbars.enabled"] = false, ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210 }
	local control = mw()
	local W = cw(saved)
	check("cast bars switch off at login: no bar is sized, nothing is hooked", sizes(W) == "208x11 195x13 150x10 150x10" and addonCalls(W, "player", "SetWidth") == 0 and addonCalls(W, "target", "SetWidth") == 0 and W.hooks == control.hooks - 0, sizes(W))
	W.attach()
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.flush()
	check("cast bars switch off at login: nor by Edit Mode's layout or a new world", sizes(W) == "150x10 195x13 150x10 150x10" or size(W, "player") == "150x10", sizes(W))
	W.detach()
	W.change("castbars.enabled", true)
	W.flush()
	check("cast bars switched on later: the sizes are applied and the functions hooked", size(W, "player") == "320x11" and size(W, "target") == "210x10" and W.hooks == control.hooks + 2, sizes(W) .. " " .. (W.hooks - control.hooks))
	W.change("castbars.enabled", false)
	W.flush()
	check("cast bars switched off again: the game's sizes exactly", sizes(W) == "208x11 195x13 150x10 150x10" and parts(W) == DEFAULT_PARTS, sizes(W) .. " " .. parts(W))
	W.attach()
	check("cast bars switched off again: the hooks leave the game's sizes alone", size(W, "player") == "150x10" and parts(W) == LOCKED_PARTS, sizes(W))
	W.detach()
	W.change("castbars.enabled", true)
	W.flush()
	check("cast bars switched on again: the sizes are applied", size(W, "player") == "320x11" and size(W, "target") == "210x10" and W.hooks == control.hooks + 2)
	check("cast bars switch: no violation", allClean(W), problems(W))
end
do
	-- The page's dependencies.
	local W = mw({ layout = { casts = true } })
	W.openPanel()
	local wrong = {}
	local function agree()
		for _, row in ipairs(ALL) do
			if row.page == "castbars" and W.enabled(row.path) ~= usable(W, row) then
				wrong[#wrong + 1] = row.path
			end
		end
	end
	agree()
	check("cast bar options: at the start the size settings are greyed and the switches are not", #wrong == 0 and not W.enabled("castbars.playerWidth") and not W.enabled("castbars.playerText") and W.enabled("castbars.playerSize")
		and not W.enabled("castbars.petHeight") and not W.enabled("castbars.targetWidth") and not W.enabled("castbars.focusHeight"), table.concat(wrong, " "))
	W.change("castbars.playerSize", true)
	agree()
	check("cast bar options: the player settings are usable with the size on, the others still greyed", #wrong == 0 and W.enabled("castbars.playerWidth") and W.enabled("castbars.playerHeight") and W.enabled("castbars.playerText") and not W.enabled("castbars.petWidth"), table.concat(wrong, " "))
	for _, key in ipairs({ "pet", "target", "focus" }) do
		W.change("castbars." .. key .. "Size", true)
	end
	agree()
	check("cast bar options: and so are the others", #wrong == 0 and W.enabled("castbars.petWidth") and W.enabled("castbars.targetHeight") and W.enabled("castbars.focusWidth"), table.concat(wrong, " "))
	W.change("castbars.enabled", false)
	agree()
	local usableCount = 0
	for _, row in ipairs(ALL) do
		if row.page == "castbars" and W.enabled(row.path) then
			usableCount = usableCount + 1
		end
	end
	check("cast bar options: with the page off only its switch is usable", #wrong == 0 and usableCount == 1, usableCount)
	W.change("castbars.enabled", true)
	W.change("castbars.playerSize", false)
	agree()
	check("cast bar options: on again, the size settings follow their switches", #wrong == 0 and not W.enabled("castbars.playerWidth") and W.enabled("castbars.petWidth"), table.concat(wrong, " "))
end

-- 75ah. A client that lacks a global the cast bar sizes use.
