-- 75r. The handles follow the game: a frame it moves, a new UI scale, the picker button.
do
	local W = mw()
	W.slash("move")
	W.gamePlaces("UIErrorsFrame", "TOP", 100, -300)
	W.run(0.25)
	local l, b = W.rectOf(W.handle("Error text"))
	local fl, fb = rect(W, "UIErrorsFrame")
	check("handles: a frame the game moves is followed by its handle within a quarter of a second", near(l, fl) and near(b, fb) and near(fl, 960 + 100 - 256), g(l) .. "," .. g(b))
	W.drag("Error text", 400, 700)
	W.gameScale(0.8)
	W.flush()
	local hl, hb, hw, hh = W.rectOf(W.handle("Error text"))
	local el, eb, ew, eh = rect(W, "UIErrorsFrame")
	check("handles: a new UI scale puts the handles over the frames again, in the new units", near(hl, el, 1e-4) and near(hb, eb, 1e-4) and near(hw, ew, 1e-4) and near(hh, eh, 1e-4), g(hl) .. "," .. g(hb) .. " " .. g(el) .. "," .. g(eb))
	check("handles: and the frame keeps its offsets from the top centre of UIParent, which are in the units of UIParent", near(el, 1200 - 304 - 256, 1e-4) and near(eb, 1350 - 320 - 60, 1e-4), g(el) .. "," .. g(eb))
	check("handles: no violation", allClean(W), problems(W))
end
do
	local W = mw()
	W.slash("move")
	W.press("Pick a frame")
	check("picker button: starts the picker", W.pickTag() and W.pickTag().shown and has(outText(W), "Point at a frame and press Alt to take it."), outText(W))
	W.press("Pick a frame")
	check("picker button: pressed again it stops it", not W.pickTag().shown and not W.pickBox().shown)
	W.press("Pick a frame")
	W.press("Done")
	check("picker button: Done stops it and closes the handles", not W.pickTag().shown and #W.shownHandles() == 0 and not W.textFrame("Movers").shown)
	W.slash("grab")
	W.slash("grab")
	check("picker: /flatui grab twice does not start a second picker", #W.shownHandles() == 9 and allClean(W), problems(W))
end
do
	-- The check runs only while something is there to keep or the handles are open.
	local W = mw({ saved = opt({}, { FlatUITooltip = { point = "BOTTOMRIGHT", x = -500, y = 100, kind = "hud" } }) })
	check("check: a saved tooltip spot alone has no frame of the game to keep, so nothing runs", runningFrames(W) == 0 and W.line("Movers") == "Movers: on, 0 moved", runningFrames(W))
	local V = mw({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } }) })
	check("check: a saved frame makes it run", runningFrames(V) == 1)
	V.slash("move")
	V.slash("move")
	check("check: and closing the handles leaves it running", runningFrames(V) == 1)
	V.slash("move reset")
	V.run(1)
	check("check: when the last saved frame is reset nothing is left to keep", runningFrames(V) == 0, runningFrames(V))
	local N = mw()
	N.slash("move")
	check("check: with nothing saved the handles make it run", runningFrames(N) == 1)
	N.slash("move")
	check("check: and closing them stops it", runningFrames(N) == 0)
	N.slash("move")
	N.drag("Error text", 400, 700)
	N.slash("move")
	check("check: a frame saved while the handles were open is kept after they close", runningFrames(N) == 1)
end
do
	-- A hidden frame can be moved too.
	local W = mw()
	W.slash("move")
	W.drag("Zone text", 500, 400)
	check("hidden frame: it is placed where the handle was dropped", pts(W, W.env.ZoneTextFrame) == "TOP>UIParent:TOP -204,-552 @1", pts(W, W.env.ZoneTextFrame))
end
do
	-- The picker refuses every one of these and takes none of them: nothing is touched.
	local W = grabWorld(nil, { layout = { tooltip = true, casts = true } })
	local watch = { "GameTooltip", "ShoppingTooltip1", "ItemRefTooltip", "TargetFrameSpellBar", "FocusFrameSpellBar", "BottomManagedFrameContainer", "TestManagedFrame", "TestPlaced", "ChatFrame2",
		"ContainerFrame3" }
	local before = {}
	for _, name in ipairs(watch) do
		before[name] = snap(W, W.env[name])
	end
	for _, name in ipairs(watch) do
		lookAt(W, W.env[name])
		W.keys.alt = true
		W.update(0.02)
		W.keys.alt = false
		W.update(0.02)
	end
	local moved = {}
	for _, name in ipairs(watch) do
		if not sameAs(W, W.env[name], before[name]) then
			moved[#moved + 1] = name
		end
	end
	check("picker: pressing Alt over each frame the design refuses takes nothing and touches none of them", next(W.spots()) == nil and #moved == 0 and allClean(W), table.concat(moved, " ") .. problems(W))
end
do
	-- The tooltip: a fixed spot with every tooltip, and a tooltip taken beside its owner.
	local W = tw({ ["tooltip.mode"] = "fixed", ["tooltip.scope"] = "all", ["tooltip.point"] = "TOPLEFT", ["tooltip.x"] = 0, ["tooltip.y"] = 0 })
	W.hoverAt(W.panel, "ANCHOR_BOTTOM")
	W.update(1 / 60)
	check("tooltip fixed with every tooltip: a tooltip beside its owner is moved to the fixed spot", atSpot(W, "TOPLEFT", 1661, 85 + 150), spot(W, "TOPLEFT"))
end
do
	-- A cast bar the game makes after login is sized on the next PLAYER_ENTERING_WORLD.
	local saved = { ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210, ["castbars.targetHeight"] = 12 }
	local W = cw(saved, nil, function(W) W.late = W.env.TargetFrameSpellBar W.env.TargetFrameSpellBar = nil end)
