	W.flush()
	check("a bar the game makes after login: sized on the next PLAYER_ENTERING_WORLD", size(W, "target") == "210x12" and allClean(W), size(W, "target"))
end

do
	-- Data edited by hand can name a frame Edit Mode owns, which is placed, and a tooltip, which is not.
	local saved = opt({}, { MinimapCluster = { point = "TOPRIGHT", x = -50, y = -50, scale = 1.2, kind = "hud" }, PlayerFrame = { point = "TOPLEFT", x = 50, y = -50, kind = "hud" },
		GameTooltip = { point = "CENTER", x = 0, y = 0, kind = "hud" } })
	local W = mw({ saved = saved, layout = { tooltip = true } })
