		and calls(W, "GameTooltip", "SetPoint") == 0 and allClean(W), pts(W, W.minimap) .. " " .. problems(W))
end

do
	-- A window the game scales, on a UI scale that is not 1: the units of the handle, the frame and UIParent agree.
	local function prep(W)
		W.rawOf[W.env.CharacterFrame].scale = 0.9
	end
	local W = mwBefore({ uiScale = 0.64 }, prep)
	W.openWindow("CharacterFrame")
	-- The game places the window with its offsets divided by its scale, so its top left corner is 16 units from the left of UIParent.
	local was = snap(W, W.env.CharacterFrame)
	W.slash("move")
	local hl, hb, hw, hh = W.rectOf(W.handle("Character"))
	check("scaled window: the handle covers the window in the units of UIParent", near(hl, 16, 1e-6) and near(hb, 1189.9, 1e-6) and near(hw, 304.2, 1e-6) and near(hh, 381.6, 1e-6), g(hl) .. "," .. g(hb) .. " " .. g(hw) .. "x" .. g(hh))
	W.drag("Character", 500, 300)
	local e = entry(W, "CharacterFrame")
	check("scaled window: the entry is in the units of UIParent", e and e.point == "TOPLEFT" and near(e.x, 500, 1e-6) and near(e.y, -1005.9, 1e-6) and e.scale == nil, e and (g(e.x) .. "," .. g(e.y)))
	check("scaled window: the window is where the handle was dropped, at the scale the game gave it", rectIs(W, "CharacterFrame", 500, 300, 304.2, 381.6, 1e-6) and W.rawOf[W.env.CharacterFrame].scale == 0.9, rectText(W, "CharacterFrame"))
	W.keys.ctrl = true
	W.wheel("Character", 1)
	W.wheel("Character", 1)
	W.keys.ctrl = false
	check("scaled window: Ctrl and the wheel scale it from the scale the game gave it", near(W.rawOf[W.env.CharacterFrame].scale, 0.99, 1e-9) and near(entry(W, "CharacterFrame").scale, 1.1, 1e-9), g(W.rawOf[W.env.CharacterFrame].scale))
	check("scaled window: and its top left corner stays where it was", rectIs(W, "CharacterFrame", 500, 300 + 381.6 - 424 * 0.99, 338 * 0.99, 424 * 0.99, 1e-6) and near(select(2, rect(W, "CharacterFrame")) + 424 * 0.99, 300 + 381.6, 1e-6), rectText(W, "CharacterFrame"))
	local saved = { movers = { CharacterFrame = { point = "TOPLEFT", x = 500, y = -1005.9, scale = 1.1, kind = "window" } } }
	local R = mwBefore({ uiScale = 0.64, saved = saved }, prep)
	R.openWindow("CharacterFrame")
	R.tick()
	check("scaled window: after a reload it is in the same place at the same scale", rectIs(R, "CharacterFrame", 500, 300 + 381.6 - 424 * 0.99, 338 * 0.99, 424 * 0.99, 1e-6), rectText(R, "CharacterFrame"))
	W.rightClick("Character")
	check("scaled window: reset gives back the scale and the points the game gave it, exactly", sameAs(W, W.env.CharacterFrame, was) or pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 17.7778,-128.889 @0.9", pts(W, W.env.CharacterFrame))
end
do
	-- A window of an addon that loads later is placed once it exists, and again when the panel manager opens it.
	local saved = { movers = { PlayerSpellsFrame = { point = "TOPLEFT", x = 600, y = -200, kind = "window" } } }
	local W = mw({ saved = saved })
	check("window of a later addon: nothing happens while it does not exist", W.env.PlayerSpellsFrame == nil and allClean(W) and W.line("Movers") == "Movers: on, 0 moved", W.line("Movers"))
	W.slash("move reset")
	check("window of a later addon: reset before it exists says nothing about /reload", not has(outText(W), "goes back to its place") and next(W.spots()) == nil, outText(W))
	W.spots().PlayerSpellsFrame = { point = "TOPLEFT", x = 600, y = -200, kind = "window" }
	W.loadWindows()
	W.tick()
	check("window of a later addon: it is placed when its addon has loaded", pts(W, W.env.PlayerSpellsFrame) == "TOPLEFT>UIParent:TOPLEFT 600,-200 @1" and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env.PlayerSpellsFrame))
	W.openWindow("PlayerSpellsFrame")
	check("window of a later addon: it is placed as soon as the panel manager has opened it", pts(W, W.env.PlayerSpellsFrame) == "TOPLEFT>UIParent:TOPLEFT 600,-200 @1", pts(W, W.env.PlayerSpellsFrame))
	W.tick()
	check("window of a later addon: and again on the next frame", pts(W, W.env.PlayerSpellsFrame) == "TOPLEFT>UIParent:TOPLEFT 600,-200 @1" and allClean(W), problems(W))
end


-- 75ai. Edge cases of the movers: the size of a miss, the minute, the sizes of a handle, the depth of a walk, the thirds of the screen.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } })
	local W = mw({ saved = saved })
	local function after(point, x, y, rel, relPoint)
		W.gamePlaces("UIErrorsFrame", point, x, y, rel, relPoint)
		W.run(0.5)
		return pts(W, W.env.UIErrorsFrame)
	end
	check("in place: 0.4 of a unit off is in place", after("TOP", 10.4, -200) == "TOP>UIParent:TOP 10.4,-200 @1")
	check("in place: half a unit off is in place", after("TOP", 10.5, -200) == "TOP>UIParent:TOP 10.5,-200 @1")
	check("in place: more than half a unit off is put back", after("TOP", 10.6, -200) == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: half a unit off in the other direction is in place", after("TOP", 9.5, -200) == "TOP>UIParent:TOP 9.5,-200 @1")
	check("in place: half a unit off up and down is in place too", after("TOP", 10, -200.5) == "TOP>UIParent:TOP 10,-200.5 @1" and after("TOP", 10, -199.5) == "TOP>UIParent:TOP 10,-199.5 @1")
	check("in place: more than half a unit off up is put back", after("TOP", 10, -200.6) == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: more than half a unit off down is put back", after("TOP", 10, -199.4) == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: the same offsets from another frame are put back", after("TOP", 10, -200, W.panel) == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: the same offsets from another point of UIParent are put back", after("TOP", 10, -200, nil, "BOTTOM") == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: another point of the frame is put back", after("TOPLEFT", 10, -200) == "TOP>UIParent:TOP 10,-200 @1")
	check("in place: another point of the frame on the right point of UIParent is put back", after("TOPLEFT", 10, -200, nil, "TOP") == "TOP>UIParent:TOP 10,-200 @1")
	W.blizzard(function() W.env.UIErrorsFrame:SetPoint("LEFT", W.env.UIParent, "LEFT", 0, 0) end)
	W.run(0.5)
	check("in place: a second point is put back to the one", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 10,-200 @1", pts(W, W.env.UIErrorsFrame))
	check("in place: no violation", allClean(W), problems(W))
end
do
	-- Ten corrections in a minute, counted from the first.
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } })
	local W = mw({ saved = saved })
	for _ = 1, 8 do
		W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W.run(0.5)
	end
	W.run(45)
	for _ = 1, 4 do
		W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W.run(0.5)
	end
	check("corrections: eight, then a gap of 45 seconds, then more: still the same minute, so it is given up on", has(W.status(), "Error text is moved by the game again and again, so it is left where the game puts it."), W.status())
	W.slash("move reset")
	W.slash("move")
	W.drag("Error text", 400, 700)
	W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
	W.run(0.5)
	check("corrections: a reset forgets that it was given up on", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1", pts(W, W.env.UIErrorsFrame))
end
do
	-- The sizes at which a handle is the size of the frame.
	local W = mwBefore({}, function(W)
		W.rawOf[W.env.UIWidgetTopCenterContainerFrame].width, W.rawOf[W.env.UIWidgetTopCenterContainerFrame].height = 16, 16
		W.rawOf[W.env.ZoneTextFrame].width, W.rawOf[W.env.ZoneTextFrame].height = 15.9, 60
		W.rawOf[W.env.UIErrorsFrame].width, W.rawOf[W.env.UIErrorsFrame].height = 100, 15.9
	end)
	W.slash("move")
	local _, _, w1, h1 = W.rectOf(W.handle("Top widgets"))
	local _, _, w2, h2 = W.rectOf(W.handle("Zone text"))
	local _, _, w3, h3 = W.rectOf(W.handle("Error text"))
	check("handle size: a frame of 16 by 16 has a handle of its own size", near(w1, 16) and near(h1, 16), g(w1) .. "x" .. g(h1))
	check("handle size: a frame under 16 wide has the nominal handle", near(w2, 200) and near(h2, 40), g(w2) .. "x" .. g(h2))
	check("handle size: a frame under 16 high has the nominal handle", near(w3, 200) and near(h3, 40), g(w3) .. "x" .. g(h3))
	local f = W.handle("Error text")
	local o = W.look(f)
	check("handle look: a gold border two pixels thick over a light blue fill the game shows through, on a frame that is not the game's", o and near(o.r, 1) and near(o.g, 0.82) and near(o.b, 0) and near(o.thick, 2 * 768 / 1080, 1e-6) and o.backShown
		and W.backdropOn(f).color[1] == 0.1 and W.backdropOn(f).color[2] == 0.35 and W.backdropOn(f).color[3] == 0.6 and W.backdropOn(f).color[4] == 0.25, o and g(o.thick))
	local bar = W.textFrame("Movers")
	check("the bar: above the handles, 440 by 156, near the bottom of the screen", bar.strata == "FULLSCREEN_DIALOG" and bar.width == 440 and bar.height == 156 and pts(W, bar) == "BOTTOM>UIParent:BOTTOM 0,220 @1" and bar.mouse == true, pts(W, bar))
	check("the bar: the hint and the line about every frame", W.textFrame("Drag to move. Scroll or Shift and scroll to nudge. Ctrl and scroll to scale. Right-click to reset.") ~= nil
		and W.textFrame("Every frame can be moved here. A grey box moves with the frame it hangs from. A hidden frame the game has not placed yet has no box.") ~= nil)
	local button = W.barButton("Reset all")
	button.scripts.OnMouseUp(button, "RightButton")
	button.scripts.OnMouseUp(button, "RightButton")
	check("the bar: a button answers the left button only", next(W.spots()) == nil and not has(outText(W), "Moved frames are back"))
	check("handle size: no violation", allClean(W), problems(W))
end
do
	-- The picker walks 40 frames up at most.
	local W = grabWorld(function(W)
		local prev = W.env.UIParent
		for i = 1, 39 do
			prev = W.bframe("TestDeepA" .. i, { parent = prev, point = { "CENTER", prev, "CENTER", 0, 0 }, width = 20, height = 20 })
		end
		prev = W.env.UIParent
		for i = 1, 40 do
			prev = W.bframe("TestDeepB" .. i, { parent = prev, point = { "CENTER", prev, "CENTER", 0, 0 }, width = 20, height = 20 })
		end
	end)
	lookAt(W, W.env.TestDeepA39)
	check("picker: a frame 39 frames below UIParent is reached", tag(W) == "TestDeepA39", tostring(tag(W)))
	lookAt(W, W.env.TestDeepB40)
	check("picker: one 40 frames below is not", tag(W) == "", tostring(tag(W)))
end
do
	-- The nine thirds of the screen, and the lines between them.
	local cases = {
		{ 200, 900, "TOPLEFT" }, { 960, 900, "TOP" }, { 1700, 900, "TOPRIGHT" }, { 200, 540, "LEFT" }, { 960, 540, "CENTER" }, { 1700, 540, "RIGHT" },
		{ 200, 200, "BOTTOMLEFT" }, { 960, 200, "BOTTOM" }, { 1700, 200, "BOTTOMRIGHT" },
		{ 640, 540, "CENTER" }, { 1280, 540, "CENTER" }, { 960, 360, "CENTER" }, { 960, 720, "CENTER" },
		{ 639.5, 540, "LEFT" }, { 1280.5, 540, "RIGHT" }, { 960, 359.5, "BOTTOM" }, { 960, 720.5, "TOP" },
	}
	local W = grabWorld(function(W)
		for i, c in ipairs(cases) do
			W.bframe("TestThird" .. i, { point = { "BOTTOMLEFT", W.env.UIParent, "BOTTOMLEFT", c[1] - 20, c[2] - 10 }, width = 40, height = 20 })
		end
	end)
	local wrong = {}
	for i, c in ipairs(cases) do
		local name = "TestThird" .. i
		W.slash("grab")
		lookAt(W, W.env[name])
		W.keys.alt = true
		W.update(0.02)
		W.keys.alt = false
		W.update(0.02)
		local e = entry(W, name)
		if not (e and e.point == c[3] and rectIs(W, name, c[1] - 20, c[2] - 10, 40, 20, 1e-6)) then
			wrong[#wrong + 1] = ("%s,%s wants %s got %s %s"):format(g(c[1]), g(c[2]), c[3], e and e.point or "nothing", rectText(W, name))
		end
	end
	check("picker: every third of the screen, and the lines between, give the point and keep the frame where it was", #wrong == 0, table.concat(wrong, "; "):sub(1, 400))
	check("picker: no violation", allClean(W), problems(W))
end
do
	-- Every listed frame: its label, its point and its kind.
	local HUD = { { "AlertFrame", "Alerts", "BOTTOM" }, { "UIErrorsFrame", "Error text", "TOP" }, { "UIWidgetTopCenterContainerFrame", "Top widgets", "TOP" },
		{ "ZoneTextFrame", "Zone text", "TOP" } }
	local WINDOWS = { { "CharacterFrame", "Character" }, { "PlayerSpellsFrame", "Spellbook and talents" }, { "QuestFrame", "Quest" }, { "GossipFrame", "Gossip" }, { "MerchantFrame", "Vendor" },
		{ "MailFrame", "Mail" }, { "BankFrame", "Bank" }, { "ClassTrainerFrame", "Trainer" }, { "AuctionHouseFrame", "Auction house" }, { "FriendsFrame", "Friends" },
		{ "CommunitiesFrame", "Guild" }, { "DressUpFrame", "Dressing room" }, { "TaxiFrame", "Flight paths" }, { "TradeFrame", "Trade" }, { "ProfessionsFrame", "Professions" },
		{ "LFGParentFrame", "Looking For Group" }, { "SocialUIFrame", "Social" }, { "ChannelFrame", "Channels" }, { "RaidParentFrame", "Raid" },
		{ "OpenMailFrame", "Open Mail" }, { "QuestLogPopupDetailFrame", "Quest Log" }, { "ItemTextFrame", "Book" } }
	local W = mw({ layout = { loaded = true }, saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) })
	for _, w in ipairs(WINDOWS) do
		W.openWindow(w[1])
	end
	W.openWindow("AddonList")
	W.slash("move")
	local wrong = {}
	check("listed frames: a handle for each of the 4 and the 3 of Edit Mode and the tooltip and the 22 windows and the 2 enemy cooldown bars, and none for the Addons window", #W.shownHandles() == 4 + 3 + 1 + 22 + 2
		and W.handle("Addons") == nil, #W.shownHandles())
	for i, h in ipairs(HUD) do
		pcall(W.drag, h[2], 100 + i * 20, 300)
		local e = entry(W, h[1])
		if not (e and e.point == h[3] and e.kind == "hud") then
			wrong[#wrong + 1] = h[1] .. " " .. tostring(e and e.point) .. " " .. tostring(e and e.kind)
		end
	end
	for i, w in ipairs(WINDOWS) do
		pcall(W.drag, w[2], 100 + i * 20, 300)
		local e = entry(W, w[1])
		if not (e and e.point == "TOPLEFT" and e.kind == "window") then
			wrong[#wrong + 1] = w[1] .. " " .. tostring(e and e.point) .. " " .. tostring(e and e.kind)
		end
	end
	pcall(W.drag, "Tooltip", 100, 300)
	check("listed frames: each has the label, the point and the kind of the list, and the tooltip handle its own point", #wrong == 0 and (entry(W, "FlatUITooltip") or {}).point == "BOTTOMRIGHT" and (entry(W, "FlatUITooltip") or {}).kind == "hud", table.concat(wrong, "; "))
	check("listed frames: no violation", allClean(W), problems(W))
end

-- 75aj. More of the same: labels, scale kept through a drag, the picker button states, the timing of the picker and the handles.
do
	local saved = opt({}, { TestPanel = { point = "CENTER", x = -300, y = 100, scale = 1.25, kind = "hud", label = "My panel" } })
	local W = mw({ saved = saved })
	W.slash("move")
	check("picked frame saved earlier: its handle carries the label it was saved with and the scale", W.handleText("My panel") == "My panel 125%", tostring(W.handleText("My panel")))
	W.drag("My panel", 800, 400)
	local e = entry(W, "TestPanel")
	check("picked frame: a drag keeps its label, its scale and its kind", e and e.label == "My panel" and near(e.scale, 1.25, 1e-9) and e.kind == "hud" and e.point == "CENTER", e and (tostring(e.label) .. " " .. tostring(e.scale) .. " " .. tostring(e.kind)))
	check("picked frame: and the frame follows with its scale", W.rawOf[W.panel].scale == 1.25 and rectIs(W, "TestPanel", 800, 400, 150, 75, 1e-6), rectText(W, "TestPanel"))
	local D = mw({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, scale = 1.2, kind = "hud" } }) })
	D.slash("move")
	D.drag("Error text", 100, 100)
	check("listed frame: a drag keeps its scale", near(entry(D, "UIErrorsFrame").scale, 1.2, 1e-9) and D.handleText("Error text") == "Error text 120%")
end
do
	-- Keys held when the picker starts do not count; the picker reads the mouse every tenth of a second.
	local W = mw()
	W.keys.alt = true
	W.slash("grab")
	lookAt(W, W.icon)
	W.update(0.02)
	check("picker: Alt held when the picker starts takes nothing", next(W.spots()) == nil and W.pickTag().shown)
	W.keys.alt = false
	W.update(0.02)
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	check("picker: and Alt pressed after it is let go does", entry(W, "TestPanelInner") ~= nil)
	local V = mw()
	V.keys.shift = true
	V.slash("grab")
	lookAt(V, V.icon)
	V.update(0.02)
	check("picker: Shift held when the picker starts does not step", tag(V) == "TestPanelInner", tostring(tag(V)))
	V.keys.shift = false
	local U = grabWorld()
	lookAt(U, U.icon)
	U.foci = { U.panel }
	U.update(0.05)
	check("picker: the mouse is not read before a tenth of a second has passed", tag(U) == "TestPanelInner", tostring(tag(U)))
	U.update(0.05)
	check("picker: and is read then", tag(U) == "TestPanel", tostring(tag(U)))
end
do
	-- The handles are laid out again every quarter of a second, not before.
	local W = mw()
	W.slash("move")
	W.gamePlaces("UIErrorsFrame", "TOP", 100, -300)
	W.run(0.2)
	local l0 = W.rectOf(W.handle("Error text"))
	W.run(0.05)
	local l1 = W.rectOf(W.handle("Error text"))
	check("handles: they follow the game after a quarter of a second and not before", near(l0, 704) and near(l1, 960 + 100 - 256), g(l0) .. " " .. g(l1))
end
do
	-- Windows: a hidden window is not placed by a panel event; with the module off the events do nothing.
	local saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" }, MailFrame = { point = "TOPLEFT", x = 400, y = -400, kind = "window" } })
	local W = mw({ saved = saved })
	W.gamePlaces("MailFrame", "TOPLEFT", 16, -116)
	W.openWindow("CharacterFrame")
	W.tick()
	check("windows: a panel event places the window that is shown and not the one that is hidden", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-300 @1" and pts(W, W.env.MailFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1", pts(W, W.env.MailFrame))
	local timers = #W.timers
	W.closeWindow("CharacterFrame")
	check("windows: closing one is also a panel event", #W.timers == timers + 1, #W.timers - timers)
	W.tick()
	W.change("movers.enabled", false)
	W.flush()
	timers = #W.timers
	W.openWindow("CharacterFrame")
	check("windows: with the movers off a panel event schedules nothing", #W.timers == timers)
	W.tick()
	check("windows: and the window is where the game put it", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1")
	W.fire("UI_SCALE_CHANGED")
	W.flush()
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.flush()
	W.editMode(true)
	W.editMode(false)
	W.flush()
	check("movers off: a change of scale, a new world and Edit Mode place nothing", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1" and pts(W, W.env.MailFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1" and allClean(W), problems(W))
end
do
	-- Combat: the half-second check leaves a protected frame alone; a frame that gives no answer about protection waits.
	local saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" } })
	local W = mwBefore({ saved = saved }, function(W) W.rawOf[W.env.CharacterFrame].protected = true end)
	W.openWindow("CharacterFrame")
	W.tick()
	W.combat = true
	W.rawOf[W.env.CharacterFrame].points = { { "TOPLEFT", W.env.UIParent, "TOPLEFT", 16, -116 } }
	local clears = calls(W, "CharacterFrame", "ClearAllPoints")
	W.run(2, 0.5)
	check("combat: the half-second check leaves a protected frame alone", calls(W, "CharacterFrame", "ClearAllPoints") == clears and pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1" and allClean(W), problems(W))
	local V = mwBefore({ saved = opt({}, { AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } }), combat = true }, function(W) W.rawOf[W.env.AlertFrame].IsProtected = function() end end)
	check("combat: a frame that gives no answer about protection is taken for protected, and waits", pts(V, V.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1" and allClean(V), pts(V, V.env.AlertFrame))
	V.combat = false
	V.fire("PLAYER_REGEN_ENABLED")
	V.flush()
	check("combat: and is placed when combat ends", pts(V, V.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,300 @1", pts(V, V.env.AlertFrame))
end
do
	-- Odd values from the game.
	local saved = opt({}, { AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } })
	local W = mwBefore({ saved = saved }, function(W) W.env.AlertFrame = "oops" end)
	check("a global that is not a frame: nothing is moved and nothing raises", allClean(W) and W.line("Movers") == "Movers: on, 0 moved", problems(W))
