	check("a global that is not a frame: it has no handle", W.handle("Alerts") == nil and allClean(W), problems(W))
	local Z = mwBefore({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } }) }, function(W) W.uiSizeFault = "zero" end)
	check("UIParent without a size: nothing is clamped and the frame is still placed", pts(Z, Z.env.UIErrorsFrame) == "TOP>UIParent:TOP 10,-200 @1" and allClean(Z), problems(Z))
	Z.slash("move")
	Z.drag("Error text", 400, 700)
