	local S = mwBefore({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } }) }, function(W) W.uiInner.fault.effScale = "zero" end)
	check("UIParent with a scale of zero: nothing is placed", pts(S, S.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and S.line("Movers") == "Movers: on, 0 moved" and allClean(S), pts(S, S.env.UIErrorsFrame))
	local T = tw({ ["tooltip.mode"] = "cursor" }, nil, function(W) W.manager.forbidden = true end)
	T.cursor = { 500, 500 }
	T.hover(T.panel)
	check("a manager of Edit Mode that is forbidden: the tooltip is placed and nothing is read", atSpot(T, "BOTTOMLEFT", 516, 516) and allClean(T), problems(T))
