do
	-- A system frame whose name is withheld; frames laid out by a container whose parent is an ordinary frame; a global with the name of the tooltip handle.
	local W = grabWorld(function(W)
		W.bframe("TestSystemNoName", { point = { "CENTER", W.env.UIParent, "CENTER", 400, -400 }, width = 30, height = 30, system = true })
		W.rawOf[W.env.TestSystemNoName].fault.name = "secret"
