		lookAt(W, W.env[n])
		offered[#offered + 1] = tostring(tag(W) == n)
	end
	check("picker: names that only start or end like a refused one are offered", table.concat(offered, ",") == "true,true,true,true", table.concat(offered, ","))
	local U = mwBefore({ saved = opt({}, { FlatUITooltip = { point = "BOTTOMRIGHT", x = -500, y = 100, kind = "hud" } }) }, function(W)
		W.bframe("FlatUITooltip", { point = { "CENTER", W.env.UIParent, "CENTER", 0, 0 }, width = 20, height = 20 })
	end)
	check("the tooltip handle: a game frame of the same name is not moved", pts(U, U.env.FlatUITooltip) == "CENTER>UIParent:CENTER 0,0 @1" and allClean(U), pts(U, U.env.FlatUITooltip))
end
do
	-- A frame placed by the addon when the movers are switched off in combat is not placed when combat ends; a frame that is restored waits.
