	check("command: the word reset is read in any case", next(W.spots()) == nil and pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1", pts(W, W.env.UIErrorsFrame))
	local V = mw({ saved = saved })
