	W.dragTo(50, 50)
	W.run(0.25)
	check("handles: one that is being dragged is not moved back by the refresh", f.points[1][4] == 50 and f.points[1][5] == 50 and f.scripts.OnUpdate ~= nil, f.points[1][4])
	W.dragEnd()
	check("handles: and is over the frame when it is dropped", entry(W, "UIErrorsFrame") ~= nil and allClean(W), problems(W))
	W.slash("move")
	local count = #W.handles()
	local shown = #W.shownHandles()
	W.fire("UI_SCALE_CHANGED")
	W.flush()
	W.run(1, 0.25)
	check("handles: a change of scale with the mover mode closed shows none", #W.shownHandles() == 0 and shown == 0 and #W.handles() == count, #W.shownHandles())
end
do
	-- The picker: answers that are not a plain false, steps that last, and the look of the box.
	local W = grabWorld(function(W)
		W.bframe("TestSilent", { parent = W.panel, point = { "CENTER", W.panel, "CENTER", 0, 0 }, width = 30, height = 30 })
		W.rawOf[W.env.TestSilent].IsAnchoringRestricted = function() end
		W.bframe("TestSilent2", { parent = W.panel, point = { "CENTER", W.panel, "CENTER", 0, 0 }, width = 30, height = 30 })
		W.rawOf[W.env.TestSilent2].IsAnchoringSecret = function() return nil end
	end)
	lookAt(W, W.env.TestSilent)
	check("picker: a frame that gives no answer about restricted anchoring hands over", tag(W) == "TestPanel", tostring(tag(W)))
	lookAt(W, W.env.TestSilent2)
	check("picker: a frame that answers nil about secret anchoring hands over", tag(W) == "TestPanel", tostring(tag(W)))
	lookAt(W, W.icon)
	press(W, "shift", true)
	press(W, "shift", false)
	W.update(0.1)
	W.update(0.1)
	check("picker: the frame stepped to is kept while the mouse stays over the same frame", tag(W) == "TestPanel", tostring(tag(W)))
	W.foci = { W.env.TestOk }
	W.foci = { W.panel }
	W.update(0.1)
	check("picker: and the step starts again when the mouse goes to another frame", tag(W) == "TestPanel")
	local box = W.pickBox()
	local o = W.look(box)
	check("picker: the box is a gold border of two pixels with no fill", o and near(o.r, 1) and near(o.g, 0.82) and near(o.b, 0) and near(o.thick, 2 * 768 / 1080, 1e-6) and not o.backShown, o and tostring(o.backShown))
	check("picker: the tag is a frame of 1 by 1 and the box is above the game's frames", W.pickTag().width == 1 and W.pickTag().height == 1 and box.strata == "HIGH" and W.pickTag().strata == "TOOLTIP")
	local bar = {}
	for _, label in ipairs({ "Pick a frame", "Reset all", "Done" }) do
		local b = W.barButton(label)
		bar[#bar + 1] = ("%s %sx%s"):format(label, g(b.width), g(b.height))
	end
	check("the bar: three buttons of 22 high and 110, 130 and 70 wide", table.concat(bar, ", ") == "Pick a frame 110x22, Reset all 130x22, Done 70x22", table.concat(bar, ", "))
end

-- 75al. Tooltip: the quarter of a second, and failures that are not in a row.
do
	local W = tw({ ["tooltip.mode"] = "cursor" })
	W.cursor = { 500, 500 }
	W.hover(W.panel)
	W.update(1 / 60)
	W.blizzard(function()
		W.tooltip:ClearAllPoints()
		W.tooltip:SetPoint("BOTTOMRIGHT", W.tooltipContainer)
	end)
	W.run(0.2, 0.05)
	check("tooltip: a tooltip the game moved is not placed again within 0.2 of a second", tipPts(W) == CORNER, tipPts(W))
	W.run(0.1, 0.05)
	check("tooltip: and is placed again within 0.3", atSpot(W, "BOTTOMLEFT", 516, 516), spot(W, "BOTTOMLEFT"))
end
do
	-- Failures that are not in a row do not stop it.
	local W = tw({ ["tooltip.mode"] = "cursor" })
	W.cursor = { 500, 500 }
	W.hover(W.panel)
	local raw = W.rawOf[W.tooltip]
	local real = raw.ClearAllPoints
	local failing = false
	raw.ClearAllPoints = function(...)
		if failing then
			error("ClearAllPoints failed", 0)
		end
		return real(...)
	end
	local x = 500
	local function frame(fail)
		failing = fail
		x = x + 10
		W.cursor = { x, 500 }
		W.update(1 / 60)
	end
	for _ = 1, 3 do
		for _ = 1, 3 do
			frame(true)
		end
		frame(false)
	end
	check("tooltip: three failures, a placement that works, and three again: it is still followed", atSpot(W, "BOTTOMLEFT", x + 16, 516), spot(W, "BOTTOMLEFT"))
end

