	local T = cw(saved, nil, function(W) W.cast.PlayerCastingBarFrame.inner.Text = SECRET end)
	check("player bar, text withheld: the spark and the mask are still fitted", has(parts(T), "spark 29") and has(parts(T), "mask " .. g(300 * 256 / 208)), parts(T))
