-- 75ar. A saved spot is applied only to a frame the game does not place itself.
do
	local names = { "MinimapClusterChild", "TestLayoutChild", "TestManagedFrame", "TestPlaced", "TotemFrame", "ChatFrame2", "GameTooltip", "EventToastManagerFrame" }
	local movers = { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } }
	for _, name in ipairs(names) do
		movers[name] = { point = "TOPRIGHT", x = -50, y = -50, scale = 1.2, kind = "hud" }
	end
	local control = mw({ layout = { tooltip = true } })
	local W = mw({ saved = opt({}, movers), layout = { tooltip = true } })
	local touched = {}
	for _, name in ipairs(names) do
		for _, call in ipairs({ "SetPoint", "ClearAllPoints", "SetScale" }) do
			if calls(W, name, call) ~= calls(control, name, call) then
				touched[#touched + 1] = name .. " " .. call
			end
		end
		if pts(W, W.env[name]) ~= pts(control, control.env[name]) then
			touched[#touched + 1] = name .. " moved"
		end
	end
	check("saved spots, frames the game places: the children of Edit Mode's frames, laid-out frames, the refuse list and the event toasts are not touched", #touched == 0 and allClean(W), table.concat(touched, ", ") .. problems(W))
	check("saved spots, frames the game places: the frame that can be moved is", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and W.line("Movers") == "Movers: on, 1 moved", W.line("Movers"))
	local status = W.status()
	check("saved spots, frames the game places: /flatui status names each one once", has(status, "MinimapClusterChild is placed by the game, so its saved spot is not used.") and has(status, "TestManagedFrame is placed by the game, so its saved spot is not used.")
		and has(status, "EventToastManagerFrame is placed by the game, so its saved spot is not used.") and count(status, "is placed by the game") == #names, status)
	local listed = {}
	for line in (status .. "\n"):gmatch("([^\n]*)\n") do
		if has(line, "is placed by the game") then
			listed[#listed + 1] = line
		end
	end
	local ordered = { unpack(listed) }
	table.sort(ordered)
	check("saved spots, frames the game places: the lines are in alphabetical order", #listed == #names and table.concat(ordered, "|") == table.concat(listed, "|"), table.concat(listed, "|"))
	for _ = 1, 14 do
		W.gamePlaces("MinimapClusterChild", "TOPRIGHT", -10, -10)
		W.gamePlaces("TestManagedFrame", "BOTTOM", 0, 20)
		W.run(0.5)
	end
	check("saved spots, frames the game places: the check leaves them alone for as long as the game moves them, and does not give up on them", not has(W.status(), "again and again")
		and pts(W, W.minimapChild) == "TOPRIGHT>UIParent:TOPRIGHT -10,-10 @1" and allClean(W), pts(W, W.minimapChild) .. " " .. problems(W))
	W.slash("move reset")
	check("saved spots, frames the game places: Reset all forgets them and says nothing about /reload, since nothing was moved", next(W.spots()) == nil and not has(W.status(), "is placed by the game")
		and not has(outText(W), "after /reload") and has(outText(W), "Moved frames are back where the game has them."), outText(W))
end
do
	-- A listed frame that becomes an Edit Mode frame later is left alone from then on.
	local W = mw({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } }) })
	check("saved spots: a listed frame is placed", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1")
	W.rawOf[W.env.UIErrorsFrame].system = 1
	local sets = calls(W, "UIErrorsFrame", "SetPoint")
	W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
	W.run(2)
	check("saved spots: when the game makes it an Edit Mode frame the check stops placing it", pts(W, W.env.UIErrorsFrame) == "TOP>UIParent:TOP 0,-122 @1" and calls(W, "UIErrorsFrame", "SetPoint") == sets + 1,
		pts(W, W.env.UIErrorsFrame))
end

