-- 75au2. ctlook: the handle Combat text: you, where the numbers for the player start.
do
	-- The font string a hit on the player shows, found among the font strings of every frame of the addon's.
	local function hit(W, event, amount)
		local known = {}
		for _, f in ipairs(W.addonFrames) do
			for _, t in ipairs(f.fonts or {}) do
				known[t] = t.calls.Show or 0
			end
		end
		W.fire("UNIT_COMBAT", "player", event or "HEAL", "", amount or 300, 1)
		for _, f in ipairs(W.addonFrames) do
			for _, t in ipairs(f.fonts or {}) do
				if (t.calls.Show or 0) > (known[t] or 0) then
					return t
				end
			end
		end
	end
	local function at(font)
		local p = font and font.points[1]
		return p and (g(p[4]) .. "," .. g(p[5])) or "none"
	end
	local function spot(W)
		local x, y = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
		return g(x) .. "," .. g(y)
	end
	local off = mw({ worldText = true })
	off.slash("move")
	local W = mw({ worldText = true, combatText = true, saved = opt({ ["combattext.where"] = "over" }) })
	W.slash("move")
	local handle = W.handle("Combat text: you")
	local l, b, w, h
	if handle then
		l, b, w, h = W.rectOf(handle)
	end
	check("ctlook: handle: Combat text: you shows with the others, a box 160 by 40 centred 170 left of and 30 below the middle of the screen", handle ~= nil and handle.shown and near(l, 710) and near(b, 490) and near(w, 160)
		and near(h, 40) and #W.shownHandles() == #off.shownHandles() + 1 and off.handle("Combat text: you") == nil, tostring(l) .. "," .. tostring(b))
	check("ctlook: handle: the middle of the box is where the first number starts", spot(W) == "790,510" and at(hit(W, "HEAL")) == "790,510", spot(W))
	W.run(2, 0.5)
	W.change("combattext.own", "Off")
	W.run(0.25)
	check("ctlook: handle: it goes within a quarter of a second of choosing Off", not handle.shown and off.handle("Combat text: you") == nil)
	W.change("combattext.own", "Damage and healing you take")
	W.run(0.25)
	check("ctlook: handle: and comes back with either of the other two", handle.shown)
	W.change("combattext.enabled", false)
	W.run(0.25)
	check("ctlook: handle: and goes with the page", not handle.shown)
	W.change("combattext.enabled", true)
	W.run(0.25)
	check("ctlook: handle: and comes back with it", handle.shown)
	W.change("tooltip.enabled", true)
	W.change("tooltip.mode", "Fixed")
	W.run(0.25)
	check("ctlook: handle: the Tooltip handle shows with Fixed and Combat text: you shows beside it", W.handle("Tooltip") ~= nil and W.handle("Tooltip").shown and handle.shown)
	W.change("tooltip.mode", "At the cursor")
	W.run(0.25)
	check("ctlook: handle: and with the cursor only Tooltip goes", not W.handle("Tooltip").shown and handle.shown)
	-- A drag.
	W.drag("Combat text: you", 100, 300)
	local e = entry(W, "FlatUICombatSelf")
	check("ctlook: handle: a drag saves point CENTER, kind hud and the offsets from the middle of the screen, with no label and no scale", e ~= nil and e.point == "CENTER" and near(e.x, 180 - 960) and near(e.y, 320 - 540)
		and e.kind == "hud" and e.scale == nil and e.label == nil and W.env.FlatUICombatSelf == nil, e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("ctlook: handle: MoverSpot gives the centre it was dropped on, and the next number starts there", spot(W) == "180,320" and at(hit(W, "HEAL")) == "180,320", spot(W))
	check("ctlook: handle: the spot of an own frame is not counted among the frames moved", W.line("Movers") == off.line("Movers") and allClean(W), W.line("Movers") .. " " .. problems(W))
	-- Reset and the wheel.
	W.run(2, 0.5)
	W.rightClick("Combat text: you")
	check("ctlook: handle: a right-click puts it back, and the next number is in the middle of the box again", entry(W, "FlatUICombatSelf") == nil and spot(W) == "790,510" and at(hit(W, "HEAL")) == "790,510", spot(W))
	W.run(2, 0.5)
	local _, y0 = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
	W.wheel("Combat text: you", 1)
	local _, y1 = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
	W.wheel("Combat text: you", -1)
	W.wheel("Combat text: you", -1)
	local _, y2 = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
	check("ctlook: handle: the wheel moves the spot one pixel up and down", near(y1 - y0, 768 / 1080, 1e-9) and near(y2 - y1, -2 * 768 / 1080, 1e-9), g(y0) .. " " .. g(y1) .. " " .. g(y2))
	W.keys.ctrl = true
	W.wheel("Combat text: you", 1)
	W.keys.ctrl = false
	local _, y3 = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
	check("ctlook: handle: Ctrl and the wheel change nothing, since the frame takes no scale", near(y3, y2, 1e-9) and entry(W, "FlatUICombatSelf").scale == nil and allClean(W), problems(W))
	-- Export, import and profiles.
	W.drag("Combat text: you", 100, 300)
	local text = W.ns.ExportProfile()
	W.ns.NewProfile("Other")
	local fresh = spot(W)
	W.ns.UseProfile("Default")
	local back = spot(W)
	W.ns.NewProfile("Third")
	local imported = W.ns.ImportProfile(text)
	check("ctlook: handle: the spot comes through an export and an import, and a new profile starts at the default", imported and spot(W) == "180,320" and fresh == "790,510" and back == "180,320", fresh .. " " .. back .. " " .. spot(W))
	W.ns.UseProfile("Other")
	W.run(2, 0.5)
	check("ctlook: handle: after a change of profile a number starts at the spot of the profile in use", at(hit(W, "HEAL")) == "790,510", at(nil))
	check("ctlook: handle: no violations or errors", allClean(W), problems(W))
	-- With the movers off the saved spot still applies, and there is no handle.
	local O = mw({ worldText = true, combatText = true, saved = opt({ ["movers.enabled"] = false, ["combattext.where"] = "over" }, { FlatUICombatSelf = { point = "CENTER", x = -300, y = 100, kind = "hud" } }) })
	O.slash("move")
	check("ctlook: handle: with the movers off in the options there is no handle and a saved spot still places the numbers", O.handle("Combat text: you") == nil and at(hit(O, "HEAL")) == "660,640" and allClean(O), problems(O))
	-- A spot that is not valid is dropped at login.
	local V = mw({ worldText = true, combatText = true, saved = opt({ ["combattext.where"] = "over" }, { FlatUICombatSelf = { point = "NOPE", x = 1, y = 1 } }) })
	check("ctlook: handle: a saved spot that is not valid is dropped, and the default one is used", at(hit(V, "HEAL")) == "790,510" and V.spots().FlatUICombatSelf == nil and allClean(V), problems(V))
	-- Another mover loaded: no handle, the spot still applies.
	local M = mwBefore({ worldText = true, combatText = true }, function(X)
		X.loadedAddons.MoveAny = true
	end)
	M.slash("move")
	check("ctlook: handle: with another mover addon loaded there is no handle, and the numbers start at the default spot", M.handle("Combat text: you") == nil and at(hit(M, "HEAL")) == "790,510" and allClean(M), problems(M))
	-- A gate that names no function of ns gives no handle.
	local N = mw({ worldText = true, combatText = true, saved = opt({ ["combattext.where"] = "over" }) })
	N.ns.CombatOwnShown = nil
	N.slash("move")
	check("ctlook: handle: when the function the gate names is missing there is no handle", N.handle("Combat text: you") == nil and allClean(N), problems(N))
	-- The default list of handles of a world with the page on.
	local D = mw({ worldText = true, combatText = true })
	D.slash("move")
	check("ctlook: handle: the list of handles of a world with the page on has Combat text: you and Combat text: your hits between Buffs and Enemy cooldowns", table.concat(D.shownHandles(), ","):find("Buffs,Combat text: you,Combat text: your hits,Enemy cooldowns: focus,Enemy cooldowns: target,Error text", 1, true) ~= nil, table.concat(D.shownHandles(), ","))
	local out = D.handle("Combat text: your hits")
	local ol, ob, ow, oh
	if out then
		ol, ob, ow, oh = D.rectOf(out)
	end
	check("scrolling: handle: Combat text: your hits is a box 160 by 40 centred 170 right of and 30 under the middle of the screen, and the Outgoing area starts at its middle",
		out ~= nil and out.shown and near(ol, 1050) and near(ob, 490) and near(ow, 160) and near(oh, 40) and select(1, D.ns.MoverSpot("FlatUICombatOut", "CENTER")) == 1130, tostring(ol) .. "," .. tostring(ob))
	local Ov = mw({ worldText = true, combatText = true, saved = opt({ ["combattext.where"] = "over" }) })
	Ov.slash("move")
	check("scrolling: handle: Combat text: your hits is not there with Over enemies, and Combat text: you is", Ov.handle("Combat text: your hits") == nil and Ov.handle("Combat text: you") ~= nil)
end

-- 75av. The bar: it can be dragged, it opens beside Edit Mode's panel, and Reset all asks once.
do
	local W = mw()
	W.slash("move")
	local bar = W.textFrame("Movers")
	check("the bar: it can be dragged and is held on the screen", bar.movable == true and bar.clamped == true and bar.drag and bar.drag[1] == "LeftButton" and bar.scripts.OnDragStart ~= nil)
	bar.scripts.OnDragStart(bar)
	check("the bar: a drag moves it", bar.moving == true)
	bar.points = { { "BOTTOMLEFT", W.env.UIParent, "BOTTOMLEFT", 100, 200 } }
	bar.scripts.OnDragStop(bar)
	check("the bar: the drag ends", bar.moving == false)
	W.slash("move")
	W.slash("move")
	check("the bar: it opens again where the player put it", pts(W, bar) == "BOTTOMLEFT>UIParent:BOTTOMLEFT 100,200 @1", pts(W, bar))
	W.slash("move")
	W.editMode(true)
	check("the bar: and also when Edit Mode opens it", pts(W, bar) == "BOTTOMLEFT>UIParent:BOTTOMLEFT 100,200 @1" and bar.shown, pts(W, bar))
end
do
	local function prep(W)
		local manager = W.rawOf[W.env.EditModeManagerFrame]
		manager.points = { { "TOP", W.env.UIParent, "TOP", 0, -100 } }
		manager.width, manager.height = 510, 200
	end
	local W = mwBefore({}, prep)
	W.editMode(true)
	local bar = W.textFrame("Movers")
	check("the bar: Edit Mode puts its panel at the top, and the bar opens beside it at the same height", bar.shown and pts(W, bar) == "TOPLEFT>UIParent:BOTTOMLEFT 1225,980 @1", pts(W, bar))
	W.editMode(false)
	W.slash("move")
	check("the bar: opened by the command it is at the bottom of the screen", pts(W, bar) == "BOTTOM>UIParent:BOTTOM 0,220 @1", pts(W, bar))
	local V = mwBefore({}, function(V)
		prep(V)
		V.rawOf[V.env.EditModeManagerFrame].fault.rect = "secret"
	end)
	V.editMode(true)
	check("the bar: when the panel of Edit Mode has no place the client will say, it opens at the bottom", pts(V, V.textFrame("Movers")) == "BOTTOM>UIParent:BOTTOM 0,220 @1" and allClean(V), pts(V, V.textFrame("Movers")))
end
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	local W = mw({ saved = saved })
	W.slash("move")
	W.press("Reset all")
	check("Reset all: the first click asks, and resets nothing", W.textFrame("Click again to reset") ~= nil and W.textFrame("Reset all") == nil and entry(W, "UIErrorsFrame") ~= nil
		and not has(outText(W), "Moved frames are back"), outText(W))
	W.run(3.5)
	check("Reset all: the question goes after three seconds, and nothing was reset", W.textFrame("Reset all") ~= nil and W.textFrame("Click again to reset") == nil and entry(W, "UIErrorsFrame") ~= nil)
	W.press("Reset all")
	W.run(2)
	W.press("Click again to reset")
	check("Reset all: a second click within three seconds resets, and the label is back", entry(W, "UIErrorsFrame") == nil and has(outText(W), "Moved frames are back where the game has them.")
		and W.textFrame("Reset all") ~= nil, outText(W))
	local V = mw({ saved = saved })
	V.slash("move")
	V.press("Reset all")
	V.run(1)
	V.press("Click again to reset")
	V.run(1)
	V.press("Reset all")
	V.run(1.5)
	check("Reset all: the timer of an earlier question does not cancel a later one", V.textFrame("Click again to reset") ~= nil)
	V.run(2)
	check("Reset all: the later question goes after its own three seconds", V.textFrame("Reset all") ~= nil and V.textFrame("Click again to reset") == nil)
	check("Reset all: no violation", allClean(W) and allClean(V), problems(W) .. problems(V))
end

-- 75aw. Windows are placed as soon as the panel manager is done, also after a pass it does not announce.
do
	local saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 500, y = -356, kind = "window" } })
	local base = mw({ saved = saved })
	local W = mwBefore({ saved = saved }, function(W)
		W.env.UpdateUIPanelPositions = function(frame)
			W.blizzard(function()
				frame:ClearAllPoints()
				frame:SetPoint("TOPLEFT", W.env.UIParent, "TOPLEFT", 16, -116)
			end)
		end
	end)
	check("windows: the layout pass that is not announced is followed with one hook", W.hooks == base.hooks + 1 and not has(W.status(), "could not be watched"), W.hooks - base.hooks)
	W.openWindow("CharacterFrame")
	W.env.UpdateUIPanelPositions(W.env.CharacterFrame)
	check("windows: after such a pass the window is back at its saved spot in the same moment", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1", pts(W, W.env.CharacterFrame))
	for _ = 1, 14 do
		W.env.UpdateUIPanelPositions(W.env.CharacterFrame)
		W.run(0.5)
	end
	check("windows: fourteen such passes in a minute are not corrections, so the window is not given up on", not has(W.status(), "again and again") and pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1"
		and allClean(W), problems(W))
	W.closeWindow("CharacterFrame")
	W.env.UpdateUIPanelPositions(W.env.CharacterFrame)
	check("windows: a window that is closed is left alone by such a pass", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 16,-116 @1", pts(W, W.env.CharacterFrame))
	check("windows: no hook is put on when the game has no such function, and nothing says the panels could not be watched", not has(base.status(), "could not be watched"), base.status())
	local N = mwBefore({ saved = saved }, function(N)
		N.env.UpdateUIPanelPositions = function() end
		N.env.hooksecurefunc = nil
	end)
	check("windows: nor when the client has no hooksecurefunc, and the movers go on", not has(N.status(), "Movers: stopped") and not has(N.status(), "could not be watched") and pts(N, N.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 500,-356 @1", N.status())
end

-- 75ax. What /flatui status and the messages say.
do
	local saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } })
	local W = mw({ saved = saved })
	for _ = 1, 14 do
		W.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
		W.run(0.5)
	end
	local lines = {}
	for line in (W.status() .. "\n"):gmatch("([^\n]*)\n") do
		lines[#lines + 1] = line
	end
	local moved
	for number, line in ipairs(lines) do
		if line == "Movers: on, 1 moved" then moved = number end
	end
	check("status: the line about a frame the game keeps moving follows the line of the movers", moved ~= nil and lines[moved + 1] == "Error text is moved by the game again and again, so it is left where the game puts it.", table.concat(lines, "|"))
	W.slash("move reset")
	check("status: and it is gone once the frame is reset", not has(W.status(), "again and again"), W.status())
	local G = mw({ saved = opt({}, { TestManagedFrame = { point = "TOPRIGHT", x = -50, y = -50, kind = "hud" } }) })
	check("status: a saved spot that is not used is named", has(G.status(), "TestManagedFrame is placed by the game, so its saved spot is not used."), G.status())
	G.change("movers.enabled", false)
	check("status: and is not named once the movers are off", not has(G.status(), "is placed by the game") and G.line("Movers") == "Movers: off", G.status())
	local T = tw({ ["tooltip.mode"] = "cursor" })
	check("status: the movers count what they moved, and the tooltip counts nothing", T.line("Movers") == "Movers: on, 0 moved" and T.line("Tooltip") == "Tooltip: on", T.line("Movers") .. " " .. T.line("Tooltip"))
	check("status: other areas still count what they styled", has(T.status(), "Cast bars: on, 5 styled") and has(T.status(), "Action bars: on, 118 styled"), T.status())
end
do
	local saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" } })
	local W = mwBefore({ saved = saved }, function(W) W.rawOf[W.env.CharacterFrame].fault.point = "secret" end)
	W.rawOf[W.env.CharacterFrame].fault.point = nil
	W.slash("move reset")
	check("reset: a window whose points could not be read says nothing about /reload, since the panel manager places it at its next opening", not has(outText(W), "after /reload")
		and has(outText(W), "Moved frames are back where the game has them."), outText(W))
end
do
	-- A frame that is forbidden was never moved, so a reset does not say it goes back.
	local W = mwBefore({ saved = opt({}, { UIErrorsFrame = { point = "TOP", x = 10, y = -200, kind = "hud" } }) }, function(W) W.rawOf[W.env.UIErrorsFrame].forbidden = true end)
	W.slash("move reset")
	check("reset: a forbidden frame was never moved, so nothing is said about /reload and nothing is read", not has(outText(W), "after /reload") and allClean(W), outText(W) .. problems(W))
end

-- 75ay. Keys and the cursor that the client cannot report.
do
	local function without(name, act)
		local W = mwBefore({}, function(W) W.env[name] = nil end)
		pcall(act, W)
		return W
	end
	local W = without("IsControlKeyDown", function(W)
		W.slash("move")
		W.drag("Error text", 400, 700)
		W.keys.ctrl = true
		W.wheel("Error text", 1)
	end)
	check("no IsControlKeyDown: the wheel nudges the frame and does not scale it", entry(W, "UIErrorsFrame").scale == nil and near(entry(W, "UIErrorsFrame").y, -320 + 768 / 1080, 1e-9) and allClean(W),
		g(entry(W, "UIErrorsFrame").y) .. " " .. problems(W))
	W = without("IsShiftKeyDown", function(W)
		W.slash("move")
		W.drag("Error text", 400, 700)
		W.keys.shift = true
		W.wheel("Error text", 1)
	end)
	check("no IsShiftKeyDown: the wheel nudges up and never sideways", near(entry(W, "UIErrorsFrame").x, -304) and near(entry(W, "UIErrorsFrame").y, -320 + 768 / 1080, 1e-9) and allClean(W),
		g(entry(W, "UIErrorsFrame").x) .. "," .. g(entry(W, "UIErrorsFrame").y) .. " " .. problems(W))
	W = without("IsAltKeyDown", function(W)
		W.slash("grab")
		W.foci = { W.env.TestPanel }
		W.update(0.1)
		W.keys.alt = true
		W.update(0.02)
	end)
	check("no IsAltKeyDown: the picker follows the mouse and takes nothing", next(W.spots()) == nil and W.pickBox().shown and allClean(W), problems(W))
	W = without("GetCursorPosition", function(W)
		W.slash("grab")
		W.foci = { W.env.TestPanel }
		W.update(0.1)
	end)
	check("no GetCursorPosition: the picker still marks the frame under the mouse", W.pickBox().shown and tag(W) == "TestPanel" and allClean(W), problems(W))
end

-- 75az. Tooltip: where the offsets apply, stale states, work in a frame, a client without the cursor.
do
	local W = tw({ ["tooltip.mode"] = "fixed", ["tooltip.x"] = 80, ["tooltip.y"] = -60 })
	W.cursor = { 10, 10 }
	W.hover(W.panel)
	check("tooltip fixed: the offsets are for the cursor, so the point is at the handle's corner exactly", atSpot(W, "BOTTOMLEFT", 1661, 85), spot(W, "BOTTOMLEFT"))
	W.change("tooltip.x", 120)
	W.update(1 / 60)
	check("tooltip fixed: and a change of an offset moves nothing", atSpot(W, "BOTTOMLEFT", 1661, 85))
	W.change("tooltip.mode", "At the cursor")
	W.update(1 / 60)
	check("tooltip fixed: at the cursor they apply", atSpot(W, "BOTTOMLEFT", 130, -50), spot(W, "BOTTOMLEFT"))
end
do
	-- A tooltip armed with no owner, then anchored again for an owner that cannot be touched: it is the game's.
	local W = tw({ ["tooltip.mode"] = "cursor" }, nil, function(W) W.rawOf[W.inner].forbidden = true end)
	W.cursor = { 500, 500 }
	W.hover(nil)
	W.update(1 / 60)
	check("tooltip: armed with no owner it follows the cursor", atSpot(W, "BOTTOMLEFT", 516, 516), spot(W, "BOTTOMLEFT"))
	W.hover(W.inner)
	W.cursor = { 900, 700 }
	W.update(1 / 60)
	check("tooltip: anchored again for an owner that is forbidden it is left to the game, and the frame stops", tipPts(W) == CORNER and runningFrames(W) == 0 and allClean(W), tipPts(W) .. " " .. problems(W))
end
do
	-- Anchored now and shown a frame later.
	local W = tw({ ["tooltip.mode"] = "cursor" })
	W.cursor = { 100, 100 }
	W.hover(W.panel)
	W.update(1 / 60)
	W.leave()
	W.update(1 / 60)
	W.cursor = { 300, 300 }
	W.blizzard(function() W.env.GameTooltip_SetDefaultAnchor(W.tooltip, W.panel) end)
	W.update(1 / 60)
	check("tooltip anchored now and shown a frame later: it is still held after the first frame, also after an earlier tooltip that was shown", runningFrames(W) == 1 and atSpot(W, "BOTTOMLEFT", 316, 316), spot(W, "BOTTOMLEFT"))
	W.cursor = { 900, 600 }
	W.blizzard(function() W.tooltip:Show() end)
	W.update(1 / 60)
	check("tooltip anchored now and shown a frame later: it follows the cursor once it is shown", atSpot(W, "BOTTOMLEFT", 916, 616), spot(W, "BOTTOMLEFT"))
	W.leave()
	W.update(1 / 60)
	check("tooltip anchored now and shown a frame later: and is let go when it is hidden", runningFrames(W) == 0)
end
do
	-- A tooltip is asked whether it is forbidden once, not in a frame.
	local W = tw({ ["tooltip.mode"] = "cursor" })
	W.cursor = { 500, 500 }
	local atStart = calls(W, "GameTooltip", "IsForbidden")
	W.hover(W.panel)
	local anchored = calls(W, "GameTooltip", "IsForbidden")
	W.run(1, 1 / 60)
	check("tooltip: GameTooltip is asked whether it is forbidden once when the hook is put on and once for an anchor, and never in a frame", atStart >= 1 and anchored == atStart + 1
		and calls(W, "GameTooltip", "IsForbidden") == anchored, atStart .. " " .. anchored .. " " .. calls(W, "GameTooltip", "IsForbidden"))
	local E = tw({ ["tooltip.mode"] = "cursor", ["tooltip.scope"] = "all" })
	local asked = 0
	local open = E.ns.EditModeOpen
	E.ns.EditModeOpen = function()
		asked = asked + 1
		return open()
	end
	E.run(1, 1 / 60)
	check("every tooltip: with no tooltip up, Edit Mode is not asked about in a frame", asked == 0 and E.tipCalls("SetAnchorType") == 0, asked)
	E.hoverAt(E.panel, "ANCHOR_RIGHT")
	E.update(1 / 60)
	check("every tooltip: a tooltip beside its owner is taken, with Edit Mode asked about", E.tipCalls("SetAnchorType") == 1 and asked >= 1, asked)
end
do
	local W = tw({ ["tooltip.mode"] = "cursor" }, nil, function(W) W.env.GetCursorPosition = nil end)
	W.hover(W.panel)
	W.update(1 / 60)
	check("no GetCursorPosition: at the cursor the tooltip is left where the game put it", tipPts(W) == CORNER and W.line("Tooltip") == "Tooltip: on" and allClean(W), tipPts(W) .. " " .. W.line("Tooltip"))
	local F = tw({ ["tooltip.mode"] = "fixed" }, nil, function(F) F.env.GetCursorPosition = nil end)
	F.hover(F.panel)
	check("no GetCursorPosition: a fixed spot does not need it", atSpot(F, "BOTTOMLEFT", 1661, 85) and allClean(F), spot(F, "BOTTOMLEFT"))
end

