suiteKit = suite()
end
-- <<< movers, tooltip and cast bar size (end)

-- The fixes of the integration review of 0.3.0. The helpers of the movers suite are the ones it hands on. The sections are one function, so that
-- their helpers and locals are not counted against the 200 locals of this file's main function.
do
local function fixes()
local mw, mwBefore, opt, entry, pts = suiteKit.mw, suiteKit.mwBefore, suiteKit.opt, suiteKit.entry, suiteKit.pts
local rectIs, rectText, allClean, problems = suiteKit.rectIs, suiteKit.rectText, suiteKit.allClean, suiteKit.problems
local outText, cw, size, sizes = suiteKit.outText, suiteKit.cw, suiteKit.size, suiteKit.sizes
-- A call of the world that raises when the handle or the button it works on is not there is a failed check, not a crash.
local function attempt(fn, ...)
	return (pcall(fn, ...))
end
-- The box of a handle in the units of UIParent, or zeros when there is none.
local function boxOf(W, label)
	local handle = W.handle(label)
	if handle then
		local l, b, w, h = W.rectOf(handle)
		if l then
			return l, b, w, h
		end
	end
	return 0, 0, 0, 0
end
-- Whether the control of a setting is usable; a setting with no control is not.
local function controlUsable(W, path)
	local ok, enabled = pcall(W.enabled, path)
	return ok and enabled == true
end
local function shownHandle(W, label)
	local handle = W.handle(label)
	return handle ~= nil and handle.shown == true
end


-- A world with the cooldown row (Kidney Shot and Blind picked), the movers and the tooltip, logged in.
local function rowWorld(options, movers, extra, prep)
	local o = { cooldowns = true, char = { cooldowns = { 408, 2094 } }, saved = opt(options, movers) }
	for key, value in pairs(extra or {}) do
		o[key] = value
	end
	return mwBefore(o, function(W)
		W.addLine({ name = "General" })
		W.addSpell(408, { name = "Kidney Shot", icon = 132298, base = 20000 })
		W.addSpell(2094, { name = "Blind", icon = 136175, base = 120000 })
		if prep then
			prep(W)
		end
	end)
end
-- The frame the icons of the row hang from.
local function rowHolder(W)
	for _, f in ipairs(W.addonFrames) do
		if f.parent == W.env.UIParent and f.scripts and f.scripts.OnUpdate then
			return f
		end
	end
end
-- The icons of the row on screen.
local function rowIcons(W)
	local holder, list = rowHolder(W), {}
	for _, f in ipairs(W.addonFrames) do
		if f.parent == holder and f.shown then
			list[#list + 1] = f
		end
	end
	return list
end
-- The box the shown icons cover: left, bottom, width, height in the units of UIParent.
local function rowBox(W)
	local left, bottom, right, top
	for _, f in ipairs(rowIcons(W)) do
		local l, b, w, h = W.rectOf(f)
		left, bottom = math.min(left or l, l), math.min(bottom or b, b)
		right, top = math.max(right or l + w, l + w), math.max(top or b + h, b + h)
	end
	if left then
		return left, bottom, right - left, top - bottom
	end
	return 0, 0, 0, 0
end
-- Where the middle of the holder is, in the units of UIParent from the bottom left.
local function rowCentre(W)
	local holder = rowHolder(W)
	local l, b, w, h = 0, 0, 0, 0
	if holder then
		l, b, w, h = W.rectOf(holder)
	end
	return (l or 0) + (w or 0) / 2, (b or 0) + (h or 0) / 2
end
local function same(a, b)
	return a ~= nil and b ~= nil and a.point == b.point and a.x == b.x and a.y == b.y and a.scale == b.scale and a.kind == b.kind
end

-- 1. A custom UI scale. UIParent has the game's scale until the custom one is set, and the screen is smaller then, so a spot saved under the custom
-- scale is past the edge of it. What is saved is never cut to the screen at that moment.
do
	local function spots(SW, SH)
		return {
			CharacterFrame = { point = "TOPLEFT", x = SW - 400, y = -(SH - 500), kind = "window" },
			AlertFrame = { point = "BOTTOM", x = SW / 2 - 150, y = SH - 250, kind = "hud" },
			UIErrorsFrame = { point = "TOP", x = -(SW / 2 - 300), y = -(SH - 150), kind = "hud" },
			ZoneTextFrame = { point = "TOP", x = SW / 2 - 400, y = -30, kind = "hud", scale = 1.5 },
			FlatUITooltip = { point = "BOTTOMRIGHT", x = -(SW - 400), y = SH - 300, kind = "hud" },
			FlatUICooldowns = { point = "CENTER", x = SW / 2 - 200, y = 120 - SH / 2, kind = "hud" },
		}
	end
	-- What is wrong with the saved numbers and with the places of the frames, as text.
	local function trouble(W, original, SW, SH)
		local wrong = {}
		local saved = W.spots()
		for name, want in pairs(original) do
			if not same(saved[name], want) then
				wrong[#wrong + 1] = ("%s saved %s,%s, was %s,%s"):format(name, g(saved[name] and saved[name].x), g(saved[name] and saved[name].y), g(want.x), g(want.y))
			end
		end
		local s = original
		local function at(name, l, b, w, h)
			if not rectIs(W, name, l, b, w, h) then
				wrong[#wrong + 1] = ("%s is at %s, wants %s,%s %sx%s"):format(name, rectText(W, name), g(l), g(b), g(w), g(h))
			end
		end
		at("CharacterFrame", s.CharacterFrame.x, SH + s.CharacterFrame.y - 424, 338, 424)
		at("AlertFrame", SW / 2 + s.AlertFrame.x - 0.5, s.AlertFrame.y, 1, 1)
		at("UIErrorsFrame", SW / 2 + s.UIErrorsFrame.x - 256, SH + s.UIErrorsFrame.y - 60, 512, 60)
		at("ZoneTextFrame", SW / 2 + s.ZoneTextFrame.x - 384, SH + s.ZoneTextFrame.y - 192, 768, 192)
		local tx, ty = W.ns.MoverSpot("FlatUITooltip", "BOTTOMRIGHT")
		if not (tx and near(tx, SW + s.FlatUITooltip.x, 1e-6) and near(ty, s.FlatUITooltip.y, 1e-6)) then
			wrong[#wrong + 1] = "tooltip spot " .. g(tx) .. "," .. g(ty)
		end
		local cx, cy = rowCentre(W)
		if not (near(cx, SW / 2 + s.FlatUICooldowns.x, 1e-6) and near(cy, SH / 2 + s.FlatUICooldowns.y, 1e-6)) then
			wrong[#wrong + 1] = "row at " .. g(cx) .. "," .. g(cy)
		end
		return table.concat(wrong, "; ")
	end
	local function world(percent, extra, prep)
		local SW, SH = 1920 / (percent / 100), 1080 / (percent / 100)
		local original = spots(SW, SH)
		local W = rowWorld({ ["general.scaleOn"] = true, ["general.scaleBelow"] = true, ["general.scaleSmall"] = percent, ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }, original, extra, prep)
		return W, original, SW, SH
	end
	for _, percent in ipairs({ 50, 35 }) do
		local label = "custom scale " .. percent .. "%"
		-- A login out of combat.
		local W, original, SW, SH = world(percent)
		check(label .. ": UIParent has the custom scale", near(W.scale(), percent / 100), g(W.scale()))
		check(label .. ": after login every saved number is as it was saved and every frame is at its spot", trouble(W, original, SW, SH) == "", trouble(W, original, SW, SH))
		W.slash("move")
		W.openWindow("CharacterFrame")
		W.run(3)
		check(label .. ": with the handles open and the check running nothing changes", trouble(W, original, SW, SH) == "", trouble(W, original, SW, SH))
		local hl, hb, hw, hh = boxOf(W, "Character")
		check(label .. ": and the handle of the window is over the window", near(hl, original.CharacterFrame.x, 1e-6) and near(hb, SH + original.CharacterFrame.y - 424, 1e-6) and near(hw, 338) and near(hh, 424),
			g(hl) .. "," .. g(hb))
		check(label .. ": no violation", allClean(W), problems(W))
		-- A login in combat: the scale waits, and so do the frames that are protected.
		local C, originalC, SWc, SHc = world(percent, { combat = true }, function(W)
			W.rawOf[W.env.CharacterFrame].protected = true
		end)
		check(label .. ": login in combat: the numbers saved are as they were", (function()
			for name, want in pairs(originalC) do
				if not same(C.spots()[name], want) then
					return false
				end
			end
			return true
		end)(), "")
		check(label .. ": login in combat: the scale waits", near(C.scale(), 1))
		C.run(2)
		C.combat = false
		C.fire("PLAYER_REGEN_ENABLED")
		C.flush()
		check(label .. ": and when combat ends the scale is set, nothing is cut, and every frame is at its spot", near(C.scale(), percent / 100) and trouble(C, originalC, SWc, SHc) == "", trouble(C, originalC, SWc, SHc))
		check(label .. ": login in combat: no violation", allClean(C), problems(C))
		-- The game puts its own scale back, and the custom one is set again.
		local G, originalG, SWg, SHg = world(percent)
		G.gameScale(1)
		G.flush()
		check(label .. ": the game puts its scale back: the custom one is set again, nothing is cut, and every frame is at its spot", near(G.scale(), percent / 100) and trouble(G, originalG, SWg, SHg) == "", trouble(G, originalG, SWg, SHg))
		G.gameScale(0.8, "DISPLAY_SIZE_CHANGED")
		G.flush()
		check(label .. ": and again after a change of the screen", near(G.scale(), percent / 100) and trouble(G, originalG, SWg, SHg) == "", trouble(G, originalG, SWg, SHg))
		-- The custom scale cannot be set for a while: the screen is the game's, the frames are cut to it where they are placed, and nothing saved changes.
		local H, originalH = world(percent)
		H.setScaleFault = true
		H.gameScale(1)
		H.slash("move")
		H.openWindow("CharacterFrame")
		H.run(8, 0.25)
		local saved = H.spots()
		local intact = true
		for name, want in pairs(originalH) do
			intact = intact and same(saved[name], want)
		end
		check(label .. ": while the game's scale stays, with the handles open and the check running, every saved number is as it was", intact)
		check(label .. ": and the frames have 48 units of them on the screen the game has", rectIs(H, "CharacterFrame", 1872, -376, 338, 424), rectText(H, "CharacterFrame"))
		check(label .. ": no frame is given up as moved by the game again and again", not has(H.status(), "again and again"), H.status())
		-- The handles are cut to that screen too: 48 units of the tooltip's are on it, and the alerts' (which have no size to measure, so are 200 by 40) are all in.
		local ol, ob, ow, oh = boxOf(H, "Tooltip")
		local al, ab, aw, ah = boxOf(H, "Alerts")
		check(label .. ": the handles of the tooltip and of the alerts are cut to it", near(ol, -202, 1e-6) and near(ob, 1032, 1e-6) and near(ow, 250) and near(oh, 150)
			and near(al, 1872, 1e-6) and near(ab, 1040, 1e-6) and near(aw, 200) and near(ah, 40), g(ol) .. "," .. g(ob) .. " " .. g(al) .. "," .. g(ab))
		local gx, gy = H.ns.MoverSpot("FlatUITooltip", "BOTTOMRIGHT")
		check(label .. ": the spot of the tooltip is cut to that screen", near(gx, 48, 1e-6) and near(gy, 1032, 1e-6), g(gx) .. "," .. g(gy))
		H.setScaleFault = false
		H.gameScale(1)
		H.flush()
		check(label .. ": and when the scale can be set again every frame is at its spot", near(H.scale(), percent / 100) and trouble(H, originalH, 1920 / (percent / 100), 1080 / (percent / 100)) == "",
			trouble(H, originalH, 1920 / (percent / 100), 1080 / (percent / 100)))
	end
end

-- The wheel at the game's own scale, with a spot saved under a custom one: Ctrl and scroll change the scale and nothing else, a nudge starts from where
-- the frame is on the screen now.
do
	local W = mw({ saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 3000, y = -1500, kind = "window" } }) })
	W.openWindow("CharacterFrame")
	W.slash("move")
	W.keys.ctrl = true
	attempt(W.wheel, "Character", 1)
	W.keys.ctrl = false
	local e = entry(W, "CharacterFrame")
	check("wheel: Ctrl and scroll change the scale and leave a spot past the edge of the screen as it was saved", e and near(e.scale, 1.05, 1e-9) and e.x == 3000 and e.y == -1500, e and (g(e.scale) .. " " .. g(e.x) .. "," .. g(e.y)))
	W.keys.shift = true
	attempt(W.wheel, "Character", -1)
	W.keys.shift = false
	e = entry(W, "CharacterFrame")
	check("wheel: a nudge starts from where the frame is on the screen and is saved from there", e and near(e.x, 1920 - 48 - 768 / 1080, 1e-9) and e.y == -1500, e and (g(e.x) .. "," .. g(e.y)))
	check("wheel: no violation", allClean(W), problems(W))
end


-- 2. Defaults. The flat health bar, the flat nameplate cast bar and the health text size depend on what the game does with a fill and with a text height,
-- so they are off until they are chosen. The handles do not open with Edit Mode until the player asks for it.
do
	local W = mw({ defaults = true })
	local ns = W.ns
	check("defaults: the flat health bar and the flat nameplate cast bar are on, the health text is at 80%", ns.Get("nameplates.healthFlat") == true and ns.Get("nameplates.castFlat") == true
		and ns.Get("nameplates.healthTextSize") == 80 and not ns.IsSet("nameplates.healthFlat") and not ns.IsSet("nameplates.castFlat") and not ns.IsSet("nameplates.healthTextSize"))
	check("defaults: the flat fills of the cast bars, the swing timers and the resource display stay on", ns.Get("castbars.flat") == true and ns.Get("swing.flat") == true and ns.Get("resource.flat") == true)
	check("defaults: the handles do not open with Edit Mode", ns.Get("movers.editMode") == false and not ns.IsSet("movers.editMode"))
	W.editMode(true)
	check("Edit Mode, at the defaults: no handle and no bar of the movers", #W.shownHandles() == 0 and W.textFrame("Movers") == nil and #W.handles() == 0, #W.shownHandles())
	W.editMode(false)
	W.slash("move")
	check("Edit Mode, at the defaults: /flatui move still opens the handles and the bar", #W.shownHandles() > 0 and (W.textFrame("Movers") or {}).shown, #W.shownHandles())
	W.slash("move")
	W.change("movers.editMode", true)
	W.editMode(true)
	check("Edit Mode, with the setting ticked: the handles and the bar open with it", #W.shownHandles() > 0 and (W.textFrame("Movers") or {}).shown, #W.shownHandles())
	W.editMode(false)
	check("Edit Mode, with the setting ticked: and close with it", #W.shownHandles() == 0 and not (W.textFrame("Movers") or {}).shown)
	check("defaults: no violation", allClean(W), problems(W))
end

-- 3. The five cast colours are used by the unit cast bars and by the nameplate cast bars, so they are on the first page with nothing greyed.
do
	local W = FH.cast()
	W.openPanel()
	local page, from
	for _, p in ipairs(W.ns.PAGES) do
		if p.key == "generalColours" then
			page = p
		end
	end
	for index, item in ipairs(page) do
		if item.section == "Cast colours" then
			from = index
		end
	end
	local want = { "castColour", "channelColour", "shieldColour", "interruptedColour", "craftColour" }
	local ok = from ~= nil and #page >= from + 5 and page[from + 6] ~= nil and page[from + 6].section == "Borders"
	for k, key in ipairs(want) do
		local item = from and page[from + k]
		ok = ok and item ~= nil and item.key == key and item.page == "castbars" and item.path == "castbars." .. key and item.kind == "colour" and item.needs == nil and item.needsPath == nil
	end
	check("cast colours: the Colours page under the first page has a section Cast colours with the five colours, saved as castbars.<key> and needing nothing", ok, tostring(from))
	local castPage
	for _, p in ipairs(W.ns.PAGES) do
		if p.key == "castbars" then
			castPage = p
		end
	end
	local rows = {}
	for _, item in ipairs(castPage) do
		rows[#rows + 1] = item.section or item.key
	end
	check("cast colours: the Cast bars page has none of them and keeps its Fill section with Flat fill", not table.concat(rows, ","):find("castColour", 1, true) and not table.concat(rows, ","):find("channelColour", 1, true)
		and not table.concat(rows, ","):find("shieldColour", 1, true) and not table.concat(rows, ","):find("interruptedColour", 1, true) and not table.concat(rows, ","):find("craftColour", 1, true) and table.concat(rows, ","):find("Fill,flat", 1, true) ~= nil and not table.concat(rows, ","):find("Size", 1, true), table.concat(rows, ","))
	local all, usableNow = true, true
	for _, key in ipairs(want) do
		local okControl, control = pcall(W.control, "castbars." .. key)
		all = all and W.setting("castbars." .. key) ~= nil and okControl and control ~= nil and #control.predicates == 0
		usableNow = usableNow and controlUsable(W, "castbars." .. key)
	end
	check("cast colours: each control has a setting of its own path, no predicate, and is usable", all and usableNow)
	-- Nothing on the first page is greyed by a switch of another page: a row its own switch greys is greyed at the start too.
	local greyed, usableAtStart = {}, {}
	for _, row in ipairs(ALL) do
		if row.page == "general" then
			usableAtStart[row.path] = controlUsable(W, row.path)
		end
	end
	for _, area in ipairs(AREAS) do
		W.change(area .. ".enabled", false)
		for _, row in ipairs(ALL) do
			if row.page == "general" and row.path ~= "general.scale" and usableAtStart[row.path] and not controlUsable(W, row.path) then
				greyed[#greyed + 1] = area .. " off greys " .. row.path
			end
		end
	end
	W.change("castbars.flat", false)
	for _, key in ipairs(want) do
		if not controlUsable(W, "castbars." .. key) then
			greyed[#greyed + 1] = "Flat fill off greys " .. key
		end
	end
	check("cast colours: no switch of another page greys anything on the first page, Flat fill of the Cast bars page included", #greyed == 0, table.concat(greyed, "; "))
	check("cast colours: no violation", allClean(W), problems(W))
end

-- 4. A change of a cast colour paints the unit cast bars and the nameplate cast bars, whatever the Cast bars page has on.
do
	local W = FH.cast()
	local plate = W.fills.newCastBar("Plate1CastBar")
	W.ns.CastFill("nameplates", plate, true)
	W.fills.castStart("PlayerCastingBarFrame", "cast")
	W.fills.castStart("Plate1CastBar", "cast")
	W.frame(2)
	local player = FH.bar(W, "PlayerCastingBarFrame")
	local function colours()
		local a, b = FH.cover(W, player), FH.cover(W, plate)
		return (a and a.shown and FH.rgb(a.vertex) or "-") .. " " .. (b and b.shown and FH.rgb(b.vertex) or "-")
	end
	check("cast colours: both bars start in the default cast colour", colours() == FH.hex(FH.CAST_HEX.cast) .. " " .. FH.hex(FH.CAST_HEX.cast), colours())
	W.openPanel()
	W.change("castbars.castColour", "ff112233")
	W.frame(2)
	check("cast colours: the control on the first page paints the unit cast bar and the nameplate cast bar", colours() == FH.hex("ff112233") .. " " .. FH.hex("ff112233"), colours())
	W.change("castbars.enabled", false)
	W.change("castbars.castColour", "ff445566")
	W.frame(2)
	local _, nameplate = colours():match("(%S+) (%S+)")
	check("cast colours: with the Cast bars page off the control still works and the nameplate cast bar follows it", controlUsable(W, "castbars.castColour") and nameplate == FH.hex("ff445566"), colours())
	W.change("castbars.enabled", true)
	W.change("castbars.flat", false)
	W.change("castbars.castColour", "ff778899")
	W.frame(2)
	_, nameplate = colours():match("(%S+) (%S+)")
	check("cast colours: and with the Flat fill of the Cast bars page off", controlUsable(W, "castbars.castColour") and nameplate == FH.hex("ff778899"), colours())
	check("cast colours: no violation", allClean(W), problems(W))
end

-- 5. With Move frames unticked and a fixed tooltip the command says where the tooltip stays.
do
	local fixed = { ["movers.enabled"] = false, ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }
	local W = mw({ saved = opt(fixed) })
	local line = "Movers are off in the options. A fixed tooltip stays at the bottom right."
	check("movers off, tooltip fixed: /flatui move says so and where the tooltip stays", W.slash("move") == line, W.slash("move"))
	check("movers off, tooltip fixed: so does /flatui grab", W.slash("grab") == line, W.slash("grab"))
	check("movers off, tooltip fixed: and no handle is shown", #W.shownHandles() == 0)
	local cursor = mw({ saved = opt({ ["movers.enabled"] = false, ["tooltip.enabled"] = true, ["tooltip.mode"] = "cursor" }) })
	check("movers off, tooltip at the cursor: the line says only that movers are off", cursor.slash("move") == "Movers are off in the options.", cursor.slash("move"))
	local off = mw({ saved = opt({ ["movers.enabled"] = false, ["tooltip.mode"] = "fixed" }) })
	check("movers off, tooltip not placed: the line says only that movers are off", off.slash("move") == "Movers are off in the options.", off.slash("move"))
	local on = mw({ saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }) })
	on.slash("move")
	check("movers on, tooltip fixed: the command opens the handles and says how to move things", #on.shownHandles() > 0 and on.out[2] == nil
		and on.out[1] == "Every frame can be moved here. Drag a blue box or a window's title. Ctrl and scroll changes size. Right-click puts it back.", #on.shownHandles())
	check("movers off: no violation", allClean(W) and allClean(cursor) and allClean(off), problems(W))
end


-- 6. One name for each window in the movers and in the window skins, and a handle for every window the skins restyle.
do
	local file = assert(io.open(ADDON_DIR .. "/Windows.lua", "rb"))
	local source = file:read("*a")
	file:close()
	-- The movers offer no handle for the bag window, the game menu, the options, the addons list, the legacy window and the colour picker, nor for the
	-- maps, the help page, the macro icons, name completion and the toasts.
	local UNMOVED = { ContainerFrameCombinedBags = true, GameMenuFrame = true, SettingsPanel = true, AddonList = true, LegacySystemFrame = true, ColorPickerFrame = true,
		WorldMapFrame = true, FlightMapFrame = true, HelpFrame = true, MacroPopupFrame = true, AutoCompleteBox = true, BNToastFrame = true, TimeAlertFrame = true,
		-- Boxes and pop-ups that open over the world or beside a slot, and windows that were added later.
		StackSplitFrame = true, EquipmentFlyoutFrame = true, ReadyCheckListenerFrame = true, RolePollPopup = true, LFGInvitePopup = true,
		AchievementFrame = true, CalendarFrame = true, ChatConfigFrame = true, PVPMatchScoreboard = true, PVPMatchResults = true, CompactRaidFrameManager = true }
	local titles, order = {}, {}
	for name, title in source:gmatch('name = "([%w_]+)", title = "([^"]+)"') do
		if not UNMOVED[name] then
			titles[name] = title
			order[#order + 1] = name
		end
	end
	check("window names: Windows.lua names thirty-four windows that the movers place", #order == 34, #order)
	local W = mw({ layout = { loaded = true, later = true } })
	for _, name in ipairs(order) do
		W.openWindow(name)
	end
	W.slash("move")
	local wrong = {}
	for _, name in ipairs(order) do
		local want = W.rawOf[W.env[name]]
		local l, b, w, h = boxOf(W, titles[name])
		if not (shownHandle(W, titles[name]) and near(w, want.width) and near(h, want.height)) then
			wrong[#wrong + 1] = name .. " (" .. titles[name] .. ") has no handle of its size"
		end
	end
	check("window names: each window the skins restyle has a handle that carries the name the skins give it", #wrong == 0, table.concat(wrong, "; "))
	check("window names: the handle of the friends window is Friends and the one of the vendor window is Vendor, not Social and Merchant", shownHandle(W, "Friends") and shownHandle(W, "Vendor")
		and W.handle("Merchant") == nil and shownHandle(W, "Social") and near(select(3, boxOf(W, "Social")), 410))
	-- The handle takes the window: dragging it saves a spot of the window, and the window follows.
	local moved = {}
	for i, name in ipairs(order) do
		attempt(W.drag, titles[name], 100 + 10 * i, 300)
		local e = entry(W, name)
		if not (e and e.point == "TOPLEFT" and e.kind == "window") then
			moved[#moved + 1] = name
		end
	end
	check("window names: and dragging it saves a spot for the window", #moved == 0, table.concat(moved, " "))
	check("window names: no violation", allClean(W), problems(W))
end

-- 7. Without a timer in the client the work is done at once.
do
	local movers = { CharacterFrame = { point = "TOPLEFT", x = 300, y = -300, kind = "window" }, AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } }
	local W = mwBefore({ saved = opt({}, movers) }, function(W)
		W.env.C_Timer = nil
	end)
	check("no timer: the saved spots are placed at login", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,300 @1" and allClean(W), problems(W))
	W.env.EventRegistry:TriggerEvent("EditMode.Exit")
	W.openWindow("CharacterFrame")
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	W.registry:TriggerEvent("UIParentPanelManager.ShowUIPanel", W.env.CharacterFrame, false)
	check("no timer: a window the panel manager placed is put at its spot at once, in the call that announced it", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-300 @1" and allClean(W), pts(W, W.env.CharacterFrame) .. " " .. problems(W))
	-- The game puts a frame back and the player enters the world again: the movers place it in that call.
	W.gamePlaces("AlertFrame", "BOTTOM", 0, 128)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	check("no timer: a frame the game moved is placed again in the call of the event that asks for it", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,300 @1" and allClean(W), pts(W, W.env.AlertFrame))
	W.slash("move")
	attempt(W.press, "Reset all")
	check("no timer: Reset all has nothing to end its question, so the first click resets", entry(W, "CharacterFrame") == nil and entry(W, "AlertFrame") == nil
		and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1" and W.textFrame("Reset all") ~= nil and W.textFrame("Click again to reset") == nil, outText(W))
	check("no timer: the movers did not stop", not has(W.status(), "stopped") and not has(W.status(), "could not") and allClean(W), W.status() .. problems(W))
	-- The scale of the settings is written at once, with no wait for the slider to stop.
	local S = mwBefore({ saved = opt({ ["general.scaleOn"] = true, ["general.scale"] = 80 }) }, function(S)
		S.env.C_Timer = nil
	end)
	check("no timer: nothing is written at login", S.scaleWrites() == 0 and near(S.scale(), 1), g(S.scale()))
	attempt(S.change, "general.scale", 70)
	check("no timer: a new custom scale is written in the call that changes it", near(S.scale(), 0.7) and S.cvars.uiscale == "0.7" and allClean(S), g(S.scale()) .. " " .. problems(S))
	attempt(S.change, "general.scaleOn", false)
	check("no timer: and the game's own values come back in the call that unticks it", S.cvars.useUiScale == "0" and allClean(S), tostring(S.cvars.uiscale) .. " " .. problems(S))
end

-- 8. The Cast bars module stops in combat: a bar that has a custom size gets the game's size when combat ends.
do
	local saved = { ["castbars.playerSize"] = true, ["castbars.playerWidth"] = 320, ["castbars.targetSize"] = true, ["castbars.targetWidth"] = 210, ["castbars.focusSize"] = true,
		["castbars.focusWidth"] = 200, ["castbars.petSize"] = true, ["castbars.petWidth"] = 250 }
	local W = cw(saved, { layout = { casts = { playerProtected = true } } })
	check("cast bar sizes, a module that stops in combat: the bars have their custom sizes before", sizes(W) == "320x11 250x13 210x10 200x10", sizes(W))
	W.combat = true
	W.ns.Try("castbars", function() error("stopped for the test", 0) end)
	check("cast bar sizes, a module that stops in combat: the protected bars wait, and the others have the game's size at once", size(W, "player") == "320x11" and size(W, "target") == "210x10" and size(W, "focus") == "200x10"
		and size(W, "pet") == "195x13", sizes(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("cast bar sizes, a module that stops in combat: when combat ends every bar has the size the game gave it", sizes(W) == "208x11 195x13 150x10 150x10", sizes(W))
	check("cast bar sizes, a module that stops in combat: the status says it stopped, once", count(W.status(), "Cast bars: stopped.") == 1 and #W.violations == 0, W.status())
end

-- 9. Ctrl and scroll on the handle of a window change its scale, so the lengths worked out in the units of the window are worked out again at once.
do
	local W = mw()
	local resized = 0
	local windows = W.ns.modules.windows
	local was = windows.Resized
	windows.Resized = function(...)
		resized = resized + 1
		return was(...)
	end
	W.openWindow("CharacterFrame")
	W.slash("move")
	W.keys.ctrl = true
	attempt(W.wheel, "Character", 1)
	W.keys.ctrl = false
	check("wheel: Ctrl and scroll on the handle of a window ask for the lengths to be worked out again, once", resized == 1 and near((entry(W, "CharacterFrame") or {}).scale, 1.05, 1e-9), resized)
	attempt(W.wheel, "Character", 1)
	W.keys.shift = true
	attempt(W.wheel, "Character", -1)
	W.keys.shift = false
	check("wheel: a nudge does not", resized == 1, resized)
	W.keys.ctrl = true
	for _ = 1, 40 do
		attempt(W.wheel, "Character", 1)
	end
	local reached = resized
	attempt(W.wheel, "Character", 1)
	W.keys.ctrl = false
	check("wheel: the largest scale of a window is 150%, and one more step changes nothing and asks for nothing", near((entry(W, "CharacterFrame") or {}).scale, 1.5, 1e-9) and resized == reached, resized .. " " .. reached)
	check("wheel: no violation", allClean(W), problems(W))
end

-- 10. The comment above ns.Register names every field of a module that Core reads.
do
	local file = assert(io.open(ADDON_DIR .. "/Core.lua", "rb"))
	local source = file:read("*a")
	file:close()
	local comment = source:match("(\n%-%- module: {.-\n)function ns%.Register")
	local fields, missing = {}, {}
	for field in source:gmatch("module%.(%w+)") do
		fields[field] = true
	end
	for field in source:gmatch("modules%[%w+%]%.(%w+)") do
		fields[field] = true
	end
	local count = 0
	for field in pairs(fields) do
		count = count + 1
		if not (comment and comment:find(field, 1, true)) then
			missing[#missing + 1] = field
		end
	end
	check("Core: the comment above ns.Register is found and Core reads ten fields of a module", comment ~= nil and count == 10, tostring(count))
	check("Core: and the comment names every one of them", #missing == 0, table.concat(missing, " "))
end

-- 11. The row of cooldown icons has a handle.
do
	local W = rowWorld()
	check("row handle: none while the handles are closed", W.handle("Cooldown icons") == nil and #W.shownHandles() == 0)
	W.slash("move")
	local handle = W.handle("Cooldown icons") or {}
	local bl, bb, bw, bh = rowBox(W)
	local hl, hb, hw, hh = boxOf(W, "Cooldown icons")
	check("row handle: it is named Cooldown icons and shown with the others", shownHandle(W, "Cooldown icons") and W.handleText("Cooldown icons") == "Cooldown icons", table.concat(W.shownHandles(), ","))
	check("row handle: it covers the icons of the row", near(hl, bl, 1e-6) and near(hb, bb, 1e-6) and near(hw, bw, 1e-6) and near(hh, bh, 1e-6) and near(bw, 75) and near(bh, 36), g(hl) .. "," .. g(hb) .. " " .. g(hw) .. "x" .. g(hh))
	check("row handle: and it is a movable frame of the addon's like the others", handle.parent == W.env.UIParent and handle.movable and handle.clamped and handle.strata == "HIGH" and handle.mouse and handle.wheel)
	-- It is there while the page is on and the row has an icon.
	W.change("cooldowns.enabled", false)
	W.run(0.25)
	check("row handle: gone when the Cooldowns page is switched off", W.handle("Cooldown icons") ~= nil and not shownHandle(W, "Cooldown icons"))
	W.change("cooldowns.enabled", true)
	W.run(0.25)
	check("row handle: and back when it is switched on", shownHandle(W, "Cooldown icons"))
	W.ns.CooldownRemove(408)
	W.ns.CooldownRemove(2094)
	W.run(0.25)
	check("row handle: gone when no spell is picked and the row has no icon", W.handle("Cooldown icons") ~= nil and not shownHandle(W, "Cooldown icons"))
	W.ns.CooldownAdd(2094)
	W.run(0.25)
	local nl, nb, nw, nh = boxOf(W, "Cooldown icons")
	check("row handle: back with the first spell, over the one icon", shownHandle(W, "Cooldown icons") and near(nw, 36) and near(nh, 36), g(nw))
	check("row handle: no violation", allClean(W), problems(W))
	-- The page is switched off in combat: the row is hidden at once, the layout waits, and the handle goes with the row.
	local C = rowWorld()
	C.slash("move")
	C.combat = true
	C.change("cooldowns.enabled", false)
	C.run(0.25)
	check("row handle: gone at once when the page is switched off in combat, though the layout waits", C.handle("Cooldown icons") ~= nil and not shownHandle(C, "Cooldown icons") and #C.violations == 0, problems(C))
	local none = rowWorld(nil, nil, { char = { cooldowns = {} } })
	none.slash("move")
	check("row handle: no spell picked at the start, no handle", not shownHandle(none, "Cooldown icons"), table.concat(none.shownHandles(), ","))
	local off = rowWorld({ ["cooldowns.enabled"] = false })
	off.slash("move")
	check("row handle: the page off at the start, no handle", not shownHandle(off, "Cooldown icons"), table.concat(off.shownHandles(), ","))
	off.change("cooldowns.enabled", true)
	off.run(0.25)
	check("row handle: and one when it is switched on while the handles are open", shownHandle(off, "Cooldown icons"))
end

-- 12. Dropping the handle saves the spot of the row, and the box of the icons ends where the handle was dropped, whichever way the row grows.
do
	-- The offsets are where the row hangs from: the middle of the top edge of the icons, the left end of it, the right end of it, the bottom edge.
	local cases = {
		{ "from the middle", {}, 500, 700, -422.5, 196 },
		{ "left to right", { ["cooldowns.grow"] = "right" }, 500, 700, -460, 196 },
		{ "right to left", { ["cooldowns.grow"] = "left" }, 500, 700, -385, 196 },
		{ "extra rows above", { ["cooldowns.rows"] = "up", ["cooldowns.perRow"] = 1 }, 500, 700, -442, 160 },
	}
	for _, case in ipairs(cases) do
		local W = rowWorld(case[2])
		W.slash("move")
		local before = { rowBox(W) }
		attempt(W.drag, "Cooldown icons", case[3], case[4])
		local l, b, w, h = rowBox(W)
		local e = entry(W, "FlatUICooldowns") or {}
		check("row handle, " .. case[1] .. ": the box of the icons is where the handle was dropped, the same size", near(l, case[3], 1e-6) and near(b, case[4], 1e-6) and near(w, before[3], 1e-6) and near(h, before[4], 1e-6),
			g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
		check("row handle, " .. case[1] .. ": the spot is where the row hangs from, saved from the middle of the screen", e.point == "CENTER" and e.kind == "hud" and e.scale == nil
			and near(e.x, case[5], 1e-6) and near(e.y, case[6], 1e-6), g(e.x) .. "," .. g(e.y))
		local hl, hb, hw, hh = boxOf(W, "Cooldown icons")
		check("row handle, " .. case[1] .. ": the handle stays over the icons", near(hl, l, 1e-6) and near(hb, b, 1e-6) and near(hw, w, 1e-6) and near(hh, h, 1e-6))
		check("row handle, " .. case[1] .. ": no violation", allClean(W), problems(W))
	end
end

-- 12b. The button on the handle of the row puts the box of the icons on the middle of the screen at the height it had, whichever way the row grows.
do
	local function buttonOf(W, label)
		for _, f in ipairs(W.addonFrames) do
			if f.parent == W.handle(label) then
				for _, t in ipairs(f.regions) do
					if t.width == 2 and t.height == 10 then
						return f
					end
				end
			end
		end
	end
	local cases = {
		{ "from the middle", {}, 0 },
		{ "left to right", { ["cooldowns.grow"] = "right" }, -37.5 },
		{ "right to left", { ["cooldowns.grow"] = "left" }, 37.5 },
		{ "extra rows above", { ["cooldowns.rows"] = "up", ["cooldowns.perRow"] = 1 }, 0 },
	}
	for _, case in ipairs(cases) do
		local W = rowWorld(case[2])
		W.slash("move")
		local before = { rowBox(W) }
		local button = buttonOf(W, "Cooldown icons")
		check("row centre, " .. case[1] .. ": the handle of the row has the button", button ~= nil and button.shown)
		if button then
			button.scripts.OnMouseUp(button, "LeftButton")
		end
		local l, b, w, h = rowBox(W)
		local e = entry(W, "FlatUICooldowns") or {}
		check("row centre, " .. case[1] .. ": the box of the icons is on the middle of the screen, at the height and the size it had", near(l + w / 2, 960, 1e-6) and near(b, before[2], 1e-6)
			and near(w, before[3], 1e-6) and near(h, before[4], 1e-6), g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
		check("row centre, " .. case[1] .. ": the spot is the point the row hangs from, across from the middle by the shift of the row", e.point == "CENTER" and e.kind == "hud" and e.scale == nil
			and (case[1] == "extra rows above" or near(e.x, case[3], 1e-6)), g(e.x))
		local hl, hb, hw, hh = boxOf(W, "Cooldown icons")
		check("row centre, " .. case[1] .. ": the handle stays over the icons, and no violation", near(hl, l, 1e-6) and near(hb, b, 1e-6) and near(hw, w, 1e-6) and near(hh, h, 1e-6)
			and allClean(W), problems(W))
	end
end

-- 13. With a spot the row is placed there and the position and the offsets are not used; the reset puts the row back to the Position setting.
do
	local function anchoredTo(W)
		local holder = rowHolder(W)
		return holder and holder.points[1] and holder.points[1][2]
	end
	local W = rowWorld({}, { FlatUICooldowns = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	local cx, cy = rowCentre(W)
	check("row spot: at login the row hangs from its spot", near(cx, 1160, 1e-6) and near(cy, 440, 1e-6), g(cx) .. "," .. g(cy))
	W.change("cooldowns.x", 300)
	W.change("cooldowns.place", "Under the personal resource display")
	cx, cy = rowCentre(W)
	check("row spot: and neither the position nor the offsets move it", near(cx, 1160, 1e-6) and near(cy, 440, 1e-6) and anchoredTo(W) == W.env.UIParent, g(cx) .. "," .. g(cy))
	W.change("cooldowns.x", 0)
	W.change("cooldowns.place", "Middle of the screen")
	W.slash("move")
	W.run(0.25)
	local l0, b0 = rowBox(W)
	attempt(W.wheel, "Cooldown icons", 1)
	local l1, b1 = rowBox(W)
	W.keys.shift = true
	attempt(W.wheel, "Cooldown icons", -1)
	W.keys.shift = false
	local l2, b2 = rowBox(W)
	local step = 768 / 1080
	check("row spot: scroll nudges the row up one pixel, Shift and scroll nudges it across", near(b1, b0 + step, 1e-6) and near(l1, l0, 1e-6) and near(l2, l1 - step, 1e-6) and near(b2, b1, 1e-6),
		g(b1 - b0) .. " " .. g(l2 - l1))
	W.keys.ctrl = true
	attempt(W.wheel, "Cooldown icons", 1)
	W.keys.ctrl = false
	local e = entry(W, "FlatUICooldowns") or {}
	local l3, b3 = rowBox(W)
	check("row spot: Ctrl and scroll do nothing, the row takes no scale", e.scale == nil and near(l3, l2, 1e-6) and near(b3, b2, 1e-6) and W.handleText("Cooldown icons") == "Cooldown icons")
	attempt(W.rightClick, "Cooldown icons")
	local rl, rb = rowBox(W)
	cx, cy = rowCentre(W)
	check("row spot: right-click on the handle forgets the spot and puts the row back in the middle of the screen", entry(W, "FlatUICooldowns") == nil and near(cx, 960, 1e-6) and near(cy, 380, 1e-6), g(cx) .. "," .. g(cy))
	local sl, sb, sw, sh = boxOf(W, "Cooldown icons")
	check("row spot: and its handle follows", near(sl, rl, 1e-6) and near(sb, rb, 1e-6) and near(sw, 75) and near(sh, 36))
	-- Reset, with the row set to hang under the display.
	local R = rowWorld({ ["cooldowns.place"] = "resource", ["cooldowns.x"] = 30 }, { FlatUICooldowns = { point = "CENTER", x = 200, y = -100, kind = "hud" }, AlertFrame = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } })
	R.slash("move")
	R.slash("move reset")
	local p = rowHolder(R) and rowHolder(R).points[1] or {}
	check("row spot: Reset puts the row back under the personal resource display with its offsets, and the other frames with it", entry(R, "FlatUICooldowns") == nil and entry(R, "AlertFrame") == nil
		and p[2] == R.prd.alt[1] and p[3] == "BOTTOM" and p[4] == 30 and pts(R, R.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,128 @1", tostring(p[3]) .. " " .. g(p[4]))
	local Q = rowWorld({}, { FlatUICooldowns = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	Q.slash("move")
	attempt(Q.press, "Reset all")
	attempt(Q.press, "Click again to reset")
	cx, cy = rowCentre(Q)
	check("row spot: and so does the Reset all button of the bar", entry(Q, "FlatUICooldowns") == nil and near(cx, 960, 1e-6) and near(cy, 380, 1e-6), g(cx) .. "," .. g(cy))
	check("row spot: no violation", allClean(W) and allClean(R) and allClean(Q), problems(W) .. problems(R) .. problems(Q))
end

-- 13b. The row of Trackers has a handle. A spot saved for it sets Place to Own position, the row hangs from the spot, and a reset puts it back.
do
	local function shield(id, name, spell)
		return { id = id, kind = "buff", name = name, names = { name }, spells = { spell } }
	end
	-- A world with two trackers and the movers, the buffs on, logged in.
	local function trackerWorld(options, movers, extra, prep)
		local o = { trackers = true, char = { trackers = { shield("shld01", "Lightning Shield", 905), shield("erth01", "Earth Shield", 974) } }, saved = opt(options, movers) }
		for key, value in pairs(extra or {}) do
			o[key] = value
		end
		return mwBefore(o, function(W)
			W.addLine({ name = "General" })
			W.addSpell(905, { name = "Lightning Shield", icon = 136051, base = 0 })
			W.addSpell(974, { name = "Earth Shield", icon = 136089, base = 0 })
			W.giveBuff(905, { applications = 3, remaining = 600 })
			W.giveBuff(974, { applications = 3, remaining = 600 })
			-- The display has a place on the screen, so a row that hangs from it has one.
			local container = W.rawOf[W.prdContainer]
			container.width, container.height = 200, 20
			container.points = { { "BOTTOM", W.env.UIParent, "BOTTOM", 0, 100 } }
			if prep then
				prep(W)
			end
		end)
	end
	-- The box the frames of the row cover, and the middle of the holder, in the units of UIParent.
	local function trackBox(W)
		local frames, holder = W.ns.TrackerRow()
		local left, bottom, right, top
		for _, f in ipairs(frames) do
			local l, b, w, h = W.rectOf(f)
			left, bottom = math.min(left or l, l), math.min(bottom or b, b)
			right, top = math.max(right or l + w, l + w), math.max(top or b + h, b + h)
		end
		local hl, hb, hw, hh = 0, 0, 0, 0
		if holder then
			hl, hb, hw, hh = W.rectOf(holder)
		end
		if left then
			return left, bottom, right - left, top - bottom, hl + hw / 2, hb + hh / 2
		end
		return 0, 0, 0, 0, hl + hw / 2, hb + hh / 2
	end
	local W = trackerWorld()
	check("trackers handle: none while the handles are closed", W.handle("Trackers") == nil)
	W.slash("move")
	local bl, bb, bw, bh = trackBox(W)
	local hl, hb, hw, hh = boxOf(W, "Trackers")
	check("trackers handle: one handle named Trackers, shown with the others", shownHandle(W, "Trackers") and W.handleText("Trackers") == "Trackers" and #W.handles() > 1, table.concat(W.shownHandles(), ","))
	check("trackers handle: it covers the row of icons", near(hl, bl, 1e-6) and near(hb, bb, 1e-6) and near(hw, bw, 1e-6) and near(hh, bh, 1e-6) and near(bw, 75) and near(bh, 36), g(hl) .. "," .. g(hb) .. " " .. g(hw) .. "x" .. g(hh))
	check("trackers handle: and it is a movable frame of the addon's like the others", W.handle("Trackers").parent == W.env.UIParent and W.handle("Trackers").movable and W.handle("Trackers").clamped and W.handle("Trackers").mouse)
	check("trackers merge: the handle named Trackers is listed once among the shown handles", (function()
		local n = 0
		for _, label in ipairs(W.shownHandles()) do
			if label == "Trackers" then
				n = n + 1
			end
		end
		return n == 1
	end)(), table.concat(W.shownHandles(), ","))
	W.change("trackers.enabled", false)
	W.run(0.25)
	check("trackers handle: gone when the page is switched off", W.handle("Trackers") ~= nil and not shownHandle(W, "Trackers"))
	W.change("trackers.enabled", true)
	W.run(0.25)
	check("trackers handle: and back when it is switched on", shownHandle(W, "Trackers"))
	W.slash("tracker remove 2")
	W.slash("tracker remove 1")
	W.run(0.25)
	check("trackers handle: gone when no tracker is on", not shownHandle(W, "Trackers"))
	W.ns.TrackerAddBuff(905)
	W.run(0.25)
	local nl, nb, nw = boxOf(W, "Trackers")
	check("trackers handle: back with the first tracker, over the one icon", shownHandle(W, "Trackers") and near(nw, 36), g(nw))
	check("trackers handle: no violation", allClean(W), problems(W))
	-- Dropping the handle saves the spot, the box ends where it was dropped, and Place is Own position.
	local D = trackerWorld()
	D.slash("move")
	local before = { trackBox(D) }
	check("trackers drag: before, Place is the personal resource display", D.ns.Get("trackers.place") == "resource" and D.read("trackers.place") == "Personal resource display")
	attempt(D.drag, "Trackers", 500, 700)
	local l, b, w, h = trackBox(D)
	local e = entry(D, "FlatUITrackers") or {}
	check("trackers drag: the box of the icons is where the handle was dropped, the same size", near(l, 500, 1e-6) and near(b, 700, 1e-6) and near(w, before[3], 1e-6) and near(h, before[4], 1e-6), g(l) .. "," .. g(b))
	check("trackers drag: the spot is where the row hangs from, saved from the middle of the screen", e.point == "CENTER" and e.kind == "hud" and e.scale == nil and near(e.x, 500 + 75 / 2 - 960, 1e-6) and near(e.y, 700 + 18 - 540, 1e-6), g(e.x) .. "," .. g(e.y))
	check("trackers drag: and Place is Own position", D.ns.Get("trackers.place") == "own" and D.read("trackers.place") == "Own position" and D.options()["trackers.place"] == "own", tostring(D.ns.Get("trackers.place")))
	local dl, db, dw, dh = boxOf(D, "Trackers")
	check("trackers drag: the handle stays over the icons", near(dl, l, 1e-6) and near(db, b, 1e-6) and near(dw, w, 1e-6) and near(dh, h, 1e-6))
	D.keys.ctrl = true
	attempt(D.wheel, "Trackers", 1)
	D.keys.ctrl = false
	local scaled = entry(D, "FlatUITrackers") or {}
	local sl2, sb2 = trackBox(D)
	check("trackers spot: Ctrl and scroll do nothing, the row takes no scale", scaled.scale == nil and near(sl2, l, 1e-6) and near(sb2, b, 1e-6) and D.handleText("Trackers") == "Trackers")
	-- X and Y are added to the spot.
	D.change("trackers.x", 30)
	D.change("trackers.y", -20)
	local ol, ob = trackBox(D)
	check("trackers spot: the offsets are added to it", near(ol, 530, 1e-6) and near(ob, 680, 1e-6), g(ol) .. "," .. g(ob))
	D.change("trackers.x", 0)
	D.change("trackers.y", 0)
	-- A right-click forgets the spot: Own position without a spot is beside the character.
	attempt(D.rightClick, "Trackers")
	local _, _, _, _, cx, cy = trackBox(D)
	check("trackers spot: right-click on the handle forgets the spot, and the row is beside the character", entry(D, "FlatUITrackers") == nil and D.ns.Get("trackers.place") == "own" and near(cx, 960 + 150 + 75 / 2, 1e-6) and near(cy, 540, 1e-6),
		g(cx) .. "," .. g(cy))
	local sl, sb, sw, sh = boxOf(D, "Trackers")
	local rl, rb = trackBox(D)
	check("trackers spot: and the handle follows", near(sl, rl, 1e-6) and near(sb, rb, 1e-6) and near(sw, 75) and near(sh, 36))
	-- A spot saved with Own position: at login the row hangs from it.
	local S = trackerWorld({ ["trackers.place"] = "own" }, { FlatUITrackers = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	local _, _, _, _, sx, sy = trackBox(S)
	check("trackers spot: at login with Own position the row hangs from its spot", near(sx, 1160, 1e-6) and near(sy, 440, 1e-6), g(sx) .. "," .. g(sy))
	-- A spot saved with another place: the place stays, and the row follows the setting until the handle is dragged.
	local P = trackerWorld({}, { FlatUITrackers = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	local _, _, _, _, px, py = trackBox(P)
	check("trackers spot: with another place the row does not hang from the spot", P.ns.Get("trackers.place") == "resource" and not (near(px, 1160, 1e-6) and near(py, 440, 1e-6)), g(px) .. "," .. g(py))
	P.change("trackers.place", "Beside the character")
	local _, _, _, _, bx2, by2 = trackBox(P)
	check("trackers spot: nor with Beside the character", near(bx2, 960 + 150 + 75 / 2, 1e-6) and near(by2, 540, 1e-6), g(bx2) .. "," .. g(by2))
	P.change("trackers.place", "Own position")
	local _, _, _, _, ox, oy = trackBox(P)
	check("trackers spot: and with Own position it does", near(ox, 1160, 1e-6) and near(oy, 440, 1e-6), g(ox) .. "," .. g(oy))
	-- Reset puts the row back where the Place setting says.
	local R = trackerWorld({ ["trackers.place"] = "own" }, { FlatUITrackers = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	R.slash("move")
	R.slash("move reset")
	local _, _, _, _, rx, ry = trackBox(R)
	check("trackers spot: Reset puts the row back, beside the character, with the place unchanged", entry(R, "FlatUITrackers") == nil and R.ns.Get("trackers.place") == "own" and near(rx, 960 + 150 + 75 / 2, 1e-6) and near(ry, 540, 1e-6), g(rx) .. "," .. g(ry))
	local Q = trackerWorld({ ["trackers.place"] = "own" }, { FlatUITrackers = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	Q.slash("move")
	attempt(Q.press, "Reset all")
	attempt(Q.press, "Click again to reset")
	local _, _, _, _, qx, qy = trackBox(Q)
	check("trackers spot: and so does the Reset all button of the bar", entry(Q, "FlatUITrackers") == nil and near(qx, 960 + 150 + 75 / 2, 1e-6) and near(qy, 540, 1e-6), g(qx) .. "," .. g(qy))
	-- In combat the drop is saved and the layout waits.
	local C = trackerWorld({ ["trackers.place"] = "own" }, { FlatUITrackers = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	C.slash("move")
	C.combat = true
	C.slash("move reset")
	local _, _, _, _, ccx, ccy = trackBox(C)
	check("trackers spot: a reset in combat waits, nothing is anchored", near(ccx, 1160, 1e-6) and near(ccy, 440, 1e-6) and #C.violations == 0, g(ccx) .. "," .. g(ccy))
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	C.flush()
	local _, _, _, _, ecx, ecy = trackBox(C)
	check("trackers spot: and when combat ends the row is back", near(ecx, 960 + 150 + 75 / 2, 1e-6) and near(ecy, 540, 1e-6) and allClean(C), g(ecx) .. "," .. g(ecy) .. problems(C))
	-- The row above the personal resource display.
	local B = trackerWorld(nil, nil, nil, function(X)
		local raw = X.rawOf[X.prdContainer]
		raw.width, raw.height = 200, 20
		raw.points = { { "BOTTOM", X.env.UIParent, "BOTTOM", 0, 100 } }
	end)
	local bx, by, bw2, bh2 = trackBox(B)
	check("trackers place: the bottom of the row is 4 units above the top of the highest bar of the display, and the row is centred on it", near(by, 124, 1e-6) and near(bh2, 36) and near(bx + bw2 / 2, 960, 1e-6), g(bx) .. "," .. g(by))
	check("trackers: no violation", allClean(B) and allClean(D) and allClean(S) and allClean(P) and allClean(R) and allClean(Q), problems(B) .. problems(D) .. problems(P))
	-- Locals: the main chunk of a file has at most 200.
	local function compiles(name)
		return loadfile(ADDON_DIR .. "/" .. name) ~= nil
	end
	check("Movers.lua and Trackers.lua compile: their main chunks have at most 200 locals", compiles("Movers.lua") and compiles("Trackers.lua"))
end

-- 14. In combat nothing of the row is laid out: a spot reset in combat takes effect when combat ends.
do
	local W = rowWorld({}, { FlatUICooldowns = { point = "CENTER", x = 200, y = -100, kind = "hud" } })
	W.slash("move")
	W.combat = true
	W.slash("move reset")
	local cx, cy = rowCentre(W)
	check("row spot: reset in combat waits, nothing is anchored", near(cx, 1160, 1e-6) and near(cy, 440, 1e-6) and #W.violations == 0, g(cx) .. "," .. g(cy))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	cx, cy = rowCentre(W)
	check("row spot: and when combat ends the row is back in the middle of the screen", near(cx, 960, 1e-6) and near(cy, 380, 1e-6) and allClean(W), g(cx) .. "," .. g(cy) .. problems(W))
end

-- 15. Under the personal resource display the row hangs from the lowest bar that is shown, with the same gap whether or not the bars are joined.
do
	local W = rowWorld({ ["cooldowns.place"] = "resource", ["cooldowns.x"] = 12, ["cooldowns.y"] = 5 })
	local function anchor(world)
		world = world or W
		local holder = rowHolder(world)
		local p = holder and holder.points[1] or {}
		local to = p[2] == world.prd.alt[1] and "alt" or p[2] == world.prd.power[1] and "power" or p[2] == world.prdContainer and "health" or p[2] == world.prdFrame and "display" or "?"
		return tostring(p[1]) .. " " .. to .. " " .. tostring(p[3]) .. " " .. g(p[4]) .. "," .. g(p[5]) .. " n" .. (holder and #holder.points or 0)
	end
	local function relayout(size)
		W.change("cooldowns.size", size)
	end
	check("lowest bar: with all three shown the row hangs from the alternate power bar, 4 units down, with the offsets", anchor() == "CENTER alt BOTTOM 12,1 n1", anchor())
	W.rawOf[W.prd.alt[1]].shown = false
	relayout(38)
	check("lowest bar: the alternate power bar hidden, from the power bar", anchor() == "CENTER power BOTTOM 12,1 n1", anchor())
	W.change("resource.join", false)
	relayout(36)
	check("lowest bar: and the same with Join bars off", anchor() == "CENTER power BOTTOM 12,1 n1", anchor())
	W.rawOf[W.prd.power[1]].shown = false
	relayout(38)
	check("lowest bar: the power bar hidden too, from the health bars", anchor() == "CENTER health BOTTOM 12,1 n1", anchor())
	W.change("resource.join", true)
	relayout(36)
	check("lowest bar: and the same with Join bars on", anchor() == "CENTER health BOTTOM 12,1 n1", anchor())
	W.rawOf[W.prdContainer].shown = false
	relayout(38)
	check("lowest bar: no bar shown, from the display itself", anchor() == "CENTER display BOTTOM 12,1 n1", anchor())
	W.rawOf[W.prd.alt[1]].shown = true
	relayout(36)
	check("lowest bar: the alternate power bar shown again, from it", anchor() == "CENTER alt BOTTOM 12,1 n1", anchor())
	check("lowest bar: no violation and no note", allClean(W) and not has(W.status(), "personal resource display cannot be used"), problems(W) .. W.status())
	-- A display whose fields raise when they are read is not hung from a bar, and the Cooldowns module goes on.
	local B = rowWorld({ ["cooldowns.place"] = "resource" }, nil, nil, function(B)
		B.prdInner.indexError = true
	end)
	check("lowest bar: a display whose fields cannot be read is hung from itself and nothing stops", anchor(B) == "CENTER display BOTTOM 0,-4 n1" and B.line("Cooldowns") == "Cooldowns: on, 2 styled", anchor(B) .. " " .. B.line("Cooldowns"))
end

end
fixes()
end

-- 101. Bar textures and bar text. A bar texture is an image file of the addon's own in place of the solid colour, on swing timers, the personal resource
-- display, cast bars and nameplate health bars. The names and numbers on the bars are sized with SetFont and hidden with alpha.
do
	-- The helpers of the movers suite that build the cast bars, and the four bars whose names are sized.
	local TX = { FONT = "Fonts\\FRIZQT__.TTF", CASTS = { "PlayerCastingBarFrame", "PetCastingBarFrame", "TargetFrameSpellBar", "FocusFrameSpellBar" } }
	TX.cw, TX.allClean, TX.problems = suiteKit.cw, suiteKit.allClean, suiteKit.problems
	TX.SOFT, TX.SHADED, TX.GLOSS = "Interface\\AddOns\\FlatUI\\Media\\Soft.tga", "Interface\\AddOns\\FlatUI\\Media\\Shaded.tga", "Interface\\AddOns\\FlatUI\\Media\\Gloss.tga"

	-- GetFont and SetFont on a label of the game's, which has the font its font object gives. raw.gameFont() is the game giving that font again.
	function TX.font(W, raw)
		raw.font, raw.sets, raw.gets = { TX.FONT, 10, "OUTLINE" }, 0, 0
		function raw.GetFont()
			raw.gets = raw.gets + 1
			if raw.fault.font == "error" then
				error("GetFont failed", 0)
			elseif raw.fault.font == "secret" then
				return SECRET, SECRET, SECRET
			end
			return raw.font[1], raw.font[2], raw.font[3]
		end
		function raw.SetFont(_, file, size, flags)
			if type(file) ~= "string" or not isnum(size) or size <= 0 or (flags ~= nil and type(flags) ~= "string") then
				bad(W, "SetFont: a file, a height and flags are expected")
			end
			raw.sets, raw.font = raw.sets + 1, { file, size, flags }
			return true
		end
		function raw.gameFont()
			raw.font = { TX.FONT, 10, "OUTLINE" }
		end
	end
	function TX.label(W, owner)
		local label, raw = W.Rr(owner, nil, { kind = "FontString" })
		TX.font(W, raw)
		return label, raw
	end
	-- The sizes and the alphas of a list of labels, as one line.
	function TX.sizes(list)
		local out = {}
		for i, raw in ipairs(list) do
			out[i] = g(raw.font[2])
		end
		return table.concat(out, ",")
	end
	function TX.alphas(list)
		local out = {}
		for i, raw in ipairs(list) do
			out[i] = g(raw.alpha)
		end
		return table.concat(out, ",")
	end
	-- A world with a name and a time on each swing timer and three strings on each resource bar: W.swingLabels and W.resourceLabels, in order.
	function TX.world(options, opts, prep)
		return FH.res(options, opts, function(W)
			W.swingLabels, W.resourceLabels = {}, {}
			for _, name in ipairs(FH.SWING) do
				for _, key in ipairs({ "TypeLabel", "TimeLabel" }) do
					local label, raw = TX.label(W, W.fills.swing[name].bar)
					W.fills.swing[name].barRaw[key] = label
					W.swingLabels[#W.swingLabels + 1] = raw
				end
			end
			for _, bar in ipairs({ "health", "power", "alt" }) do
				for _, key in ipairs({ "TextString", "LeftText", "RightText" }) do
					local label, raw = TX.label(W, W.prd[bar][1])
					W.prd[bar][2][key] = label
					W.resourceLabels[#W.resourceLabels + 1] = raw
				end
			end
			if prep then
				prep(W)
			end
		end)
	end
	-- A world with the cast bars, a spell name on each, and SetLook giving the player and pet names their font again: W.castTexts.
	function TX.castWorld(options, extra, prep)
		return TX.cw(options, extra, function(W)
			W.castTexts = {}
			for _, name in ipairs(TX.CASTS) do
				local entry = W.cast[name]
				local text = entry.inner.Text
				if text == nil then
					text = W.Rr(entry.bar, nil, { kind = "FontString" })
					entry.inner.Text = text
				end
				local raw = W.rawOf[text]
				TX.font(W, raw)
				W.castTexts[#W.castTexts + 1] = raw
				local setLook = entry.inner.SetLook
				if setLook then
					entry.inner.SetLook = function(...)
						local result = setLook(...)
						raw.gameFont()
						return result
					end
				end
			end
			if prep then
				prep(W)
			end
		end)
	end

	-- Swing timers: the file, the colour as the tint of the bar, the same fill region, and the spark where it was.
	do
		local W = FH.res({ ["general.barTexture"] = "soft" })
		local main = W.fills.swing.SwingTimerMainHandFrame
		local ok, same = true, true
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			ok = ok and FH.fill(W, s.bar) == "file " .. TX.SOFT and FH.n(W, s.bar, "SetStatusBarTexture") == 1 and FH.n(W, s.bar, "SetColorFill") == 0
				and FH.tint(W, s.bar) == FH.hex(FH.SWING_HEX[name]) and FH.n(W, s.bar, "SetStatusBarColor") == 1
			same = same and s.bar:GetStatusBarTexture() == s.fill and s.pipRaw.points[1][2] == s.fill and s.pipRaw.calls.SetPoint == nil
		end
		check("texture: Soft shade puts its file on each swing timer once, tinted with the colour of the hand, on the same fill region as before", ok and same)
		W.change("swing.mainColour", "ff336699")
		local calls = FH.changes(W, main.bar)
		W.change("swing.spark", false)
		check("texture: a changed colour is one tint and no texture, and a Refresh with nothing changed makes no call", FH.n(W, main.bar, "SetStatusBarTexture") == 1
			and FH.n(W, main.bar, "SetStatusBarColor") == 2 and FH.tint(W, main.bar) == FH.hex("ff336699") and FH.changes(W, main.bar) == calls)
		W.change("general.barTexture", "Gloss")
		local gloss = FH.fill(W, main.bar) == "file " .. TX.GLOSS and FH.n(W, main.bar, "SetStatusBarTexture") == 2 and FH.tint(W, main.bar) == FH.hex("ff336699")
		W.change("general.barTexture", "Flat")
		check("texture: another file keeps the colour, and Flat is the solid colour with a white tint so that the colour is not applied twice", gloss
			and FH.fill(W, main.bar) == "colour " .. FH.hex("ff336699") and FH.tint(W, main.bar) == "1.000,1.000,1.000" and FH.n(W, main.bar, "SetColorFill") == 1)
		W.change("general.barTexture", "Soft shade")
		W.change("swing.flat", false)
		local back = true
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			back = back and FH.fill(W, s.bar) == "atlas " .. s.atlas and FH.tint(W, s.bar) == "1.000,1.000,1.000" and s.bar:GetStatusBarTexture() == s.fill
		end
		check("texture: Flat fill off gives the game's fill and the white tint back on each timer", back)
		W.change("swing.flat", true)
		W.change("swing.enabled", false)
		check("texture: the page off does too, and no violation, error or message is left", FH.fill(W, main.bar) == "atlas " .. main.atlas and FH.tint(W, main.bar) == "1.000,1.000,1.000"
			and #W.diff("swing") == 0 and FH.plain(W), table.concat(W.diff("swing"), "; ") .. FH.why(W))
	end

	-- The personal resource display keeps the colour the game gives its bars.
	do
		local W = FH.res()
		local health, power = FH.bars(W)
		local fill, tints = W.rawOf[power].fill, FH.tint(W, health) .. FH.tint(W, power)
		W.change("general.barTexture", "Shaded")
		check("texture: a resource bar has the file and no colour of the addon's", FH.fill(W, health) == "file " .. TX.SHADED and FH.fill(W, power) == "file " .. TX.SHADED
			and FH.n(W, health, "SetStatusBarColor") == 0 and FH.n(W, power, "SetStatusBarColor") == 0 and FH.tint(W, health) .. FH.tint(W, power) == tints)
		W.fills.setPower("RAGE")
		local seen = FH.tint(W, power) == FH.RAGE and W.prd.power[1]:GetStatusBarTexture() == fill
		W.change("general.barTexture", "Flat")
		check("texture: the colour the game sets afterwards is the colour seen, with the file and with Flat", seen and FH.fill(W, power) == "colour 1.000,1.000,1.000"
			and FH.tint(W, power) == FH.RAGE and FH.n(W, power, "SetStatusBarColor") == 0)
		W.change("general.barTexture", "Gloss")
		W.change("resource.flat", false)
		check("texture: Flat fill off gives the game's fill back, and no violation, error or message is left", FH.fill(W, power) == "atlas " .. FH.BAR_ATLAS
			and FH.fill(W, health) == "atlas " .. FH.BAR_ATLAS and FH.n(W, power, "SetStatusBarColor") == 0 and FH.plain(W), FH.why(W))
	end

	-- Cast bars: the cover is the file, tinted by the state of the cast; the game's fill is never touched.
	do
		local W = FH.cast()
		FH.castAll(W)
		local cover, textures = FH.cover(W, FH.bar(W, FH.PLAYER)), #W.addonTextures
		-- The client may reset the tint of a texture when its picture changes.
		for _, name in ipairs(FH.CASTS) do
			local c = FH.cover(W, FH.bar(W, name))
			for _, method in ipairs({ "SetTexture", "SetColorTexture" }) do
				local original = c[method]
				c[method] = function(...)
					original(...)
					c.vertex = { 1, 1, 1, 1 }
				end
			end
		end
		local white = cover.color ~= nil and cover.color[1] == 1 and cover.file == nil
		W.change("general.barTexture", "Soft shade")
		W.frame(1)
		local all = true
		for _, name in ipairs(FH.CASTS) do
			local c = FH.cover(W, FH.bar(W, name))
			all = all and c.file == TX.SOFT and c.color == nil and FH.shownColour(W, name) == FH.hex(FH.CAST_HEX.cast) and #FH.covers(W, FH.bar(W, name)) == 1
		end
		check("texture: a white cover is the file on every cover at the next frame, in the colour of the cast, with no texture made again and the game's fill never called",
			white and all and #W.addonTextures == textures and FH.fillCalls(W) == 0)
		W.change("general.barTexture", "Flat")
		W.frame(1)
		check("texture: Flat is the white cover again with the same colour, and no violation, error or message is left", cover.calls.SetColorTexture == 2 and cover.calls.SetTexture == 1
			and cover.color ~= nil
			and FH.shownColour(W, FH.PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(W), FH.why(W))
		local X = FH.cast({ ["general.barTexture"] = "gloss" })
		FH.castAll(X)
		check("texture: a cover made after the choice starts with the file", FH.cover(X, FH.bar(X, FH.PLAYER)).file == TX.GLOSS and FH.cover(X, FH.bar(X, FH.PLAYER)).color == nil)
	end

	-- Nameplate health bars: the file, the colour Blizzard gives the bar, and the game's fill when the flat bar is off.
	do
		local W = FH.res()
		local plate = W.newPlate()
		local fill, fillRaw = W.Rr(plate.healthBar, "UI-HUD-CoolDownManager-Bar")
		local hb = plate.healthInner
		hb.barTexture, hb.tint = fill, { 0.2, 0.4, 0.6, 0.9 }
		function hb.GetStatusBarColor() return unpack(hb.tint) end
		function hb.SetStatusBarColor(_, r, g2, b, a) hb.tint = { r, g2, b, a } end
		W.showPlate("nameplate1", plate)
		W.flush()
		local function look()
			return (fillRaw.color and "colour" or fillRaw.file and ("file " .. fillRaw.file) or "atlas " .. tostring(fillRaw.atlas)) .. " " .. table.concat(hb.tint, ",")
		end
		local flat = look() == "colour 0.2,0.4,0.6,0.9"
		W.change("general.barTexture", "Shaded")
		check("texture: a flat health bar is white with Blizzard's colour, and Shaded is the file with the same colour", flat and look() == "file " .. TX.SHADED .. " 0.2,0.4,0.6,0.9", look())
		W.change("general.barTexture", "Flat")
		check("texture: Flat is white again", look() == "colour 0.2,0.4,0.6,0.9", look())
		W.change("general.barTexture", "Gloss")
		W.change("nameplates.healthFlat", false)
		check("texture: Flat health bar off gives the game's fill back whatever texture is chosen, with no violation or error", look() == "atlas " .. FH.BAR_ATLAS .. " 0.2,0.4,0.6,0.9"
			and #W.violations == 0 and #W.errors == 0, look() .. FH.why(W))
	end

	-- A change of the texture reaches every kind of bar at once.
	do
		local W = FH.cast()
		FH.castAll(W)
		local plate = W.newPlate()
		local fill, fillRaw = W.Rr(plate.healthBar, "UI-HUD-CoolDownManager-Bar")
		plate.healthInner.barTexture, plate.healthInner.GetStatusBarColor, plate.healthInner.SetStatusBarColor = fill, function() return 1, 1, 1, 1 end, function() end
		W.showPlate("nameplate1", plate)
		W.flush()
		W.change("general.barTexture", "Gloss")
		W.frame(1)
		check("texture: one change repaints a swing timer, a resource bar, a cast bar and a nameplate",
			FH.fill(W, W.fills.swing.SwingTimerRangedFrame.bar) == "file " .. TX.GLOSS and FH.fill(W, W.prd.power[1]) == "file " .. TX.GLOSS
			and FH.cover(W, FH.bar(W, "TargetFrameSpellBar")).file == TX.GLOSS and fillRaw.file == TX.GLOSS)
	end

	-- What the game refuses or withholds, and what a forbidden frame is.
	do
		local W = FH.res({ ["general.barTexture"] = "soft" }, nil, function(X)
			X.fills.swing.SwingTimerMainHandFrame.barRaw.refuseTexture = true
			X.fills.swing.SwingTimerOffHandFrame.barRaw.fault.setColor = "error"
			X.fills.swing.SwingTimerRangedFrame.barRaw.fault.fillRegion = "secret"
		end)
		local main, off, ranged = W.fills.swing.SwingTimerMainHandFrame, W.fills.swing.SwingTimerOffHandFrame, W.fills.swing.SwingTimerRangedFrame
		check("texture: a file the game refuses leaves the game's fill and says so, a tint it refuses takes the file back, and a withheld fill region is left alone",
			FH.fill(W, main.bar) == "atlas " .. main.atlas and FH.n(W, main.bar, "SetStatusBarColor") == 0 and has(W.status(), "Swing timers: the game refused a flat fill on a timer, which keeps its default fill.")
			and FH.fill(W, off.bar) == "atlas " .. off.atlas and FH.tint(W, off.bar) == "1.000,1.000,1.000" and FH.changes(W, ranged.bar) == 0, W.status())
		check("texture: and none of it stops the module or raises", not has(W.status(), "stopped") and #W.errors == 0 and #W.violations == 0, W.status() .. FH.why(W))
		local X = FH.res({ ["general.barTexture"] = "soft" }, { forbidden = { ["SwingTimerMainHandFrame.StatusBar"] = true, ["PRD.power"] = true } })
		check("texture: a forbidden bar is not touched and the others have the file", FH.plain(X) and FH.n(X, X.fills.swing.SwingTimerOffHandFrame.bar, "SetStatusBarTexture") == 1
			and FH.n(X, X.prd.health[1], "SetStatusBarTexture") == 1, FH.why(X))
		local Y = FH.res({ ["general.barTexture"] = "soft" }, { fills = { without = { "SetStatusBarTexture" } } })
		check("texture: a client without SetStatusBarTexture leaves the game's fill and raises nothing", FH.fill(Y, Y.fills.swing.SwingTimerMainHandFrame.bar) == "atlas " .. Y.fills.swing.SwingTimerMainHandFrame.atlas
			and FH.fill(Y, Y.prd.power[1]) == "atlas " .. FH.BAR_ATLAS and #Y.errors == 0 and #Y.violations == 0 and not has(Y.status(), "stopped"), Y.status() .. FH.why(Y))
	end

	-- Swing timer text.
	do
		local W = TX.world()
		local defaults = TX.sizes(W.swingLabels) == "10,10,10,10,10,10" and W.swingLabels[1].sets == 0 and W.swingLabels[1].gets == 0 and W.swingLabels[1].calls.SetAlpha == nil
		check("text: swing timers are not read or touched at the defaults", defaults)
		W.change("swing.textSize", 150)
		W.change("swing.spark", false)
		local one = true
		for _, raw in ipairs(W.swingLabels) do
			one = one and raw.sets == 1 and raw.font[1] == TX.FONT and raw.font[2] == 15 and raw.font[3] == "OUTLINE"
		end
		check("text: a size is the same font file and flags at a percent of the game's size, set once, and a Refresh with nothing changed sets no font", one, TX.sizes(W.swingLabels))
		W.change("swing.textSize", 60)
		local low = TX.sizes(W.swingLabels) == "6,6,6,6,6,6"
		W.change("swing.textSize", 200)
		local high = TX.sizes(W.swingLabels) == "20,20,20,20,20,20"
		W.change("swing.textSize", 100)
		check("text: the range is 6 to 20 and 100 is the game's size, font file and flags", low and high and TX.sizes(W.swingLabels) == "10,10,10,10,10,10" and W.swingLabels[1].font[3] == "OUTLINE")
		W.change("swing.textSize", 150)
		for _, raw in ipairs(W.swingLabels) do
			raw.gameFont()
		end
		W.change("swing.spark", true)
		check("text: a font the game sets again is sized from the game's size and not from the size set here", TX.sizes(W.swingLabels) == "15,15,15,15,15,15", TX.sizes(W.swingLabels))
		W.change("swing.name", false)
		local names = TX.alphas(W.swingLabels) == "0,1,0,1,0,1"
		W.change("swing.time", false)
		local both = TX.alphas(W.swingLabels) == "0,0,0,0,0,0"
		W.change("swing.name", true)
		W.change("swing.time", true)
		check("text: the timer name off hides only the names, the time left off the times too, and both on show them", names and both and TX.alphas(W.swingLabels) == "1,1,1,1,1,1")
		W.change("swing.name", false)
		W.change("swing.enabled", false)
		check("text: the page off gives the game's size and shows the labels, with no violation, error or message", TX.sizes(W.swingLabels) == "10,10,10,10,10,10"
			and TX.alphas(W.swingLabels) == "1,1,1,1,1,1" and FH.plain(W), FH.why(W))
		local X = TX.world({ ["swing.textSize"] = 150 }, { forbidden = { ["SwingTimerMainHandFrame.StatusBar"] = true } }, function(Y)
			Y.swingLabels[3].fault.font = "secret"
			Y.swingLabels[4].GetFont = nil
			Y.fills.swing.SwingTimerRangedFrame.barRaw.TypeLabel = SECRET
		end)
		check("text: a forbidden timer is not read, a label that is withheld, cannot be asked or is itself withheld keeps its size, and the status says so once",
			X.swingLabels[1].sets == 0 and X.swingLabels[2].sets == 0 and X.swingLabels[3].sets == 0 and X.swingLabels[4].sets == 0 and X.swingLabels[5].sets == 0 and X.swingLabels[6].sets == 1
			and count(X.status(), "Swing timers: the font of a label could not be changed, so it keeps its size.") == 1 and #X.violations == 0 and #X.errors == 0, X.status() .. FH.why(X))
	end

	-- Personal resource display text.
	do
		local W = TX.world({ ["resource.textSize"] = 150, ["resource.text"] = false })
		local hidden = TX.sizes(W.resourceLabels) == "15,15,15,15,15,15,15,15,15" and TX.alphas(W.resourceLabels) == "0,0,0,0,0,0,0,0,0"
		W.change("resource.text", true)
		check("text: the three strings of every resource bar are sized and hidden, and shown again", hidden and TX.alphas(W.resourceLabels) == "1,1,1,1,1,1,1,1,1")
		W.change("resource.enabled", false)
		check("text: the page off gives the game's size, with no violation, error or message", TX.sizes(W.resourceLabels) == "10,10,10,10,10,10,10,10,10" and FH.plain(W), FH.why(W))
		local X = TX.world({ ["resource.textSize"] = 150 }, { forbidden = { ["PRD.power"] = true } })
		check("text: a forbidden bar is not read, and the other bars are sized", TX.sizes(X.resourceLabels) == "15,15,15,10,10,10,15,15,15" and FH.plain(X), TX.sizes(X.resourceLabels) .. FH.why(X))
	end

	-- Cast bar text. The names of the player and pet bars get their font object again in SetLook.
	do
		local W = TX.castWorld({})
		local hooks = W.hooks
		local defaults = W.castTexts[1].sets == 0 and W.castTexts[3].sets == 0
		W.change("castbars.textSize", 150)
		check("text: cast bars are untouched at the defaults, then the player, pet, target and focus names are sized and the lock and unlock functions are followed",
			defaults and TX.sizes(W.castTexts) == "15,15,15,15" and W.hooks == hooks + 2, TX.sizes(W.castTexts) .. " " .. (W.hooks - hooks))
		W.attach()
		local locked = TX.sizes(W.castTexts) == "15,15,15,15"
		W.detach()
		check("text: locking or unlocking the player bar gives its name the font object again, and the size follows", locked and TX.sizes(W.castTexts) == "15,15,15,15", TX.sizes(W.castTexts))
		W.combat = true
		W.change("castbars.textSize", 120)
		local waiting = TX.sizes(W.castTexts) == "12,12,15,15"
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("text: in combat the bars of protected unit frames wait, and have the size when combat ends", waiting and TX.sizes(W.castTexts) == "12,12,12,12", TX.sizes(W.castTexts))
		W.change("castbars.enabled", false)
		check("text: the page off gives the game's size, with no violation, error or message", TX.sizes(W.castTexts) == "10,10,10,10" and TX.allClean(W) and #W.out == 0, TX.problems(W))
		local X = TX.castWorld({ ["castbars.textSize"] = 150 }, nil, function(Y)
			Y.env.hooksecurefunc = nil
		end)
		check("text: a client without hooksecurefunc still has the size, and raises nothing", TX.sizes(X.castTexts) == "15,15,15,15" and TX.allClean(X), TX.problems(X))
	end
end

-- The bags, spells and menus groups, the headers of the stat list, the Looking For Group fallback and /flatui windows.
do
	local function second(kind, extra)
		local o = { only = {}, second = kind or true }
		for key, value in pairs(extra or {}) do
			o[key] = value
		end
		return newWorld({ windows = o, combat = o.combat, without = o.without })
	end
	local function up(W)
		W.login()
		W.flush()
		return W, W.win.names
	end
	-- Makes Blizzard frames the way the game makes them after login.
	local function blizz(W, make)
		local was = W.group
		W.group = "windows"
		local made = { make() }
		W.group = was
		W.seal()
		return unpack(made)
	end
	local function coords(W, region)
		local tc = wraw(W, region).texCoord
		return tc and table.concat(tc, ",") or "-"
	end
	-- The words after each window name in the lines /flatui windows prints.
	local function states(text)
		local out, lines = {}, 0
		for name, state in text:gmatch("([%w_]+): ([%a ]+)") do
			out[name] = state
			lines = lines + 1
		end
		return out, lines
	end

	-- Bags and bank: a box, transparent art, a background that stays transparent, slots styled as the bag updates its items.
	do
		local W, n = up(second())
		local bag = n.ContainerFrame1
		local bg = wraw(W, bag).Bg
		local function flat()
			return g(wa(W, wraw(W, bg).BottomLeft)) .. g(wa(W, wraw(W, bg).BottomEdge)) .. g(wa(W, wraw(W, bg).TopSection))
		end
		check("bags: a bag window has a box, and the game's border and flat background are transparent",
			W.state(bag) == "SB" and wa(W, wraw(W, wraw(W, bag).NineSlice).TopEdge) == 0 and flat() == "000")
		W.blizzard(function() W.env.ContainerFrame_GenerateFrame(bag) end)
		W.flush()
		check("bags: the game sets the colour of the background each time a bag opens, and it is transparent again", flat() == "000")
		check("bags: the combined bag window and the bank have a box", W.state(n.ContainerFrameCombinedBags) == "SB" and W.state(n.BankFrame) == "SB")
		check("bags: a slot the bag has when it is swept has a box, and its icon keeps the empty slot picture uncropped", W.state(n.ContainerFrame1Item1) == "SB" and coords(W, wraw(W, n.ContainerFrame1Item1).icon) == "-")
		local plain, withheld, later = blizz(W, function()
			local a = W.win.itemButton(bag, nil, "FlatUITestPlainSlot")
			local b = W.win.addBagSlot(bag, 3)
			wraw(W, b).emptyBackgroundAtlas = SECRET
			return a, b, W.win.addBagSlot(bag, 2)
		end)
		check("bags: slots the bag makes later have no box until it updates its items", W.state(plain) == "." and W.state(withheld) == "." and W.state(later) == ".")
		W.blizzard(function() bag:UpdateItems() end)
		check("bags: and none inside the game's own update", W.state(later) == "." and W.state(plain) == ".")
		W.win.updateBags()
		check("bags: and have one afterwards; the empty slot picture stays uncropped, an icon alone is cropped, a withheld field counts as none",
			W.state(later) == "SB" and coords(W, wraw(W, later).icon) == "-" and W.state(plain) == "SB" and coords(W, wraw(W, plain).icon) == "0.08,0.92,0.08,0.92"
			and W.state(withheld) == "SB" and coords(W, wraw(W, withheld).icon) == "0.08,0.92,0.08,0.92")
		local panel = wraw(W, n.BankFrame).BankPanel
		check("bank: the picture behind the bank, the border of the panel and its shadows are transparent", wa(W, wraw(W, n.BankFrame).Background) == 0
			and wa(W, wraw(W, wraw(W, panel).NineSlice).TopEdge) == 0 and wa(W, wraw(W, wraw(W, panel).EdgeShadows).TopShadow) == 0)
		local tab, item = blizz(W, function()
			return W.win.sideTab(n.BankFrame, nil, nil, 1, "Interface/ICONS/INV_SideTab_Bank_c60"), W.win.itemButton(panel, nil, "FlatUITestBankSlot")
		end)
		check("bank: a page tab and a slot the game made have no box before the game announces a page", W.state(wraw(W, tab).Icon) == "." and W.state(item) == ".")
		W.blizzard(function() panel:GenerateItemSlotsForSelectedTab() end)
		check("bank: and none inside the game's own call", W.state(wraw(W, tab).Icon) == "." and W.state(item) == ".")
		W.flush()
		check("bank: a page tab and a slot have a box on the frame after the game announces a page", W.state(wraw(W, tab).Icon) == "SB" and W.state(item) == "SB")
		check("bags and bank: no violation, error or message", #W.violations == 0 and #W.errors == 0 and #W.out == 0, wvio(W))
	end

	-- Menus: a dialog keeps its border and its title plate in frames of their own, a pop-up its background in one frame.
	do
		local W = second()
		W.win.addOptions()
		local _, n = up(W)
		local menu, picker, settings = wraw(W, n.GameMenuFrame), wraw(W, n.ColorPickerFrame), wraw(W, n.SettingsPanel)
		check("menus: the game menu has a box, and its border, border background, title plate and buttons are done",
			W.state(n.GameMenuFrame) == "SB" and wa(W, wraw(W, menu.Border).TopLeftCorner) == 0 and wa(W, wraw(W, menu.Border).Bg) == 0
			and wa(W, wraw(W, menu.Header).LeftBG) == 0 and wa(W, wraw(W, menu.Header).CenterBG) == 0 and W.state(n.GameMenuButton1) == "SB")
		check("menus: the colour picker is done the same way", W.state(n.ColorPickerFrame) == "SB" and wa(W, wraw(W, picker.Border).BottomEdge) == 0
			and wa(W, wraw(W, picker.Header).RightBG) == 0 and W.state(wraw(W, picker.Footer).OkayButton) == "SB")
		check("menus: the options window loses its flat background, its border and the picture on top",
			W.state(n.SettingsPanel) == "SB" and wa(W, wraw(W, settings.Bg).TopSection) == 0 and wa(W, wraw(W, settings.NineSlice).TopEdge) == 0
			and wa(W, wregion(W, n.SettingsPanel, "Options_InnerFrame")) == 0)
		check("menus: the Close button of the options is a push button with a box, and the cross in its corner is a cross",
			W.state(settings.CloseButton) == "SB" and #wlines(W, settings.CloseButton) == 0 and #wlines(W, settings.ClosePanelButton, "OVERLAY") == 2)
		check("menus: the add-on list is a window with an inset", W.state(n.AddonList) == "SB" and wa(W, wraw(W, wraw(W, n.AddonList).Inset).Bg) == 0)
		local popup = n.StaticPopup1
		local button = wraw(W, popup).Button1
		local plates = wraw(W, button).states
		check("menus: a pop-up has a box and no background, and its buttons have a box and no plate in any state",
			W.state(popup) == "SB" and wa(W, wraw(W, wraw(W, popup).BG).Top) == 0 and wa(W, wraw(W, wraw(W, popup).BG).Bottom) == 0 and W.state(button) == "SB"
			and wa(W, plates.Normal) == 0 and wa(W, plates.Pushed) == 0 and wa(W, plates.Disabled) == 0 and wa(W, plates.Highlight) == 0)
		local more = blizz(W, function() return W.win.panelButton(popup, "Button2", nil, 100, 22) end)
		wraw(W, popup).shown = true
		W.blizzard(function() W.env.StaticPopup_Show("EXAMPLE") end)
		check("menus: a pop-up that is on screen is looked at again when another is shown", W.state(more) == "SB")
		check("menus: no violation, error or message", #W.violations == 0 and #W.errors == 0 and #W.out == 0, wvio(W))
	end

	-- Windows of load-on-demand addons are styled when their addon loads, and say so.
	do
		local W, n = up(second("demand"))
		check("spells: the windows of addons that are not loaded do not exist and are said to load later",
			n.PlayerSpellsFrame == nil and states(W.slash("windows")).PlayerSpellsFrame == "loads later" and states(W.slash("windows")).LegacySystemFrame == "loads later")
		W.win.loadSpells("Blizzard_PlayerSpells")
		W.flush()
		local spells = n.PlayerSpellsFrame
		check("spells: when the addon loads the window is styled, with its border and its side tab", W.state(spells) == "SB" and wa(W, wraw(W, wraw(W, spells).NineSlice).TopEdge) == 0
			and W.state(wraw(W, wraw(W, spells).Tab1).Icon) == "SB" and W.state(wraw(W, spells).ApplyButton) == "SB")
		check("spells: and the line for it says styled while the others still say they load later", states(W.slash("windows")).PlayerSpellsFrame == "styled" and states(W.slash("windows")).ProfessionsFrame == "loads later")
		W.change("windows.spells", false)
		check("spells: switched off, the box is hidden and the border is back", W.state(spells) == "hb" and wa(W, wraw(W, wraw(W, spells).NineSlice).TopEdge) == 1)
	end

	-- The headers of the stat list are styled after the scroll box has laid them out.
	do
		local C = newWorld({ windows = { only = { "CharacterFrame" } } })
		local list, target = blizz(C, function()
			local box = C.win.names.CharacterStatsPaneScrollBox
			local l = C.win.frame(box, "ScrollBox", {})
			C.win.watchable(l)
			return l, C.win.frame(l, "ScrollTarget", {})
		end)
		up(C)
		local header, row, withheld = blizz(C, function()
			local h = C.win.frame(target, nil, { width = 197, height = 40 })
			C.win.tex(h, "Background", "UI-Character-Info-Title")
			C.win.font(h, "Title")
			local r = C.win.frame(target, nil, { width = 187, height = 23 })
			C.win.tex(r, "Background", "UI-Character-Info-Line-Bounce2")
			C.win.font(r, "Label")
			local w = C.win.frame(target, nil, { width = 197, height = 40 })
			C.win.tex(w, "Background", "UI-Character-Info-Title")
			wraw(C, w).Title = SECRET
			return h, r, w
		end)
		C.blizzard(function() list:Update() end)
		C.flush()
		check("stat headers: a header the scroll box laid out has a box and no plate", #wboxes(C, header) == 1 and C.state(wboxes(C, header)[1]) == "SB" and wa(C, wraw(C, header).Background) == 0)
		check("stat headers: a row of the list is left as it is, and so is a frame whose title is withheld", #wboxes(C, row) == 0 and wa(C, wraw(C, row).Background) == 1 and #wboxes(C, withheld) == 0
			and wa(C, wraw(C, withheld).Background) == 1)
		C.change("windows.buttons", false)
		check("stat headers: with the buttons off the plate is back and the box is hidden", wa(C, wraw(C, header).Background) == 1 and C.state(wboxes(C, header)[1]) == "hb")
		check("stat headers: no violation, error or message", #C.violations == 0 and #C.errors == 0 and #C.out == 0, wvio(C))
	end

	-- A window the sweep after its addon loaded did not see is found by its name when it opens. A forbidden one is left alone.
	do
		local function lost(prep, hollow)
			local L = second(true, { hollowPanel = hollow })
			L.login()
			L.flush()
			local fire = L.fire
			L.fire = function(event, name, ...)
				if not (event == "ADDON_LOADED" and name == "Blizzard_GroupFinder_VanillaStyle") then
					return fire(event, name, ...)
				end
			end
			L.loadGroupFinder()
			L.fire = fire
			if prep then
				prep(L, L.win.names.LFGParentFrame)
			end
			return L, L.win.names.LFGParentFrame
		end
		local L, lfg = lost()
		check("looking for group: when the addon's load was not heard the window is not styled and the line says it is not open yet", L.state(lfg) == "." and states(L.slash("windows")).LFGParentFrame == "not open yet")
		L.showPanel(lfg)
		L.flush()
		check("looking for group: opening it styles it by its name, with its pages", L.state(lfg) == "SB" and wa(L, wraw(L, wraw(L, L.win.names.LFGListingFrame).NineSlice).TopEdge) == 0
			and states(L.slash("windows")).LFGParentFrame == "styled")
		local F, forbidden = lost(function(W, frame) wraw(W, frame).forbidden = true end, true)
		F.fire("ADDON_LOADED", "Blizzard_GroupFinder_VanillaStyle")
		F.showPanel(forbidden)
		F.flush()
		check("looking for group: a window the game forbids is not read, not styled when it opens, and the line says forbidden",
			#F.violations == 0 and #F.errors == 0 and F.state(forbidden) == "." and states(F.slash("windows")).LFGParentFrame == "forbidden", wvio(F))
	end

	-- /flatui windows: one line for each listed window.
	do
		local W = second("demand")
		wraw(W, W.win.names.ContainerFrame2).forbidden = true
		up(W)
		local at, lines = states(W.slash("windows"))
		check("windows command: one line for each of the 69 listed windows, each with its frame name, and one help line",
			lines == 69 and at.CharacterFrame == "not found" and at.StaticPopup4 == "styled" and has(W.slash("what"), "/flatui windows - each window and whether it is styled"))
		check("windows command: styled, forbidden, not found and loads later", at.ContainerFrame1 == "styled" and at.ContainerFrame2 == "forbidden" and at.ContainerFrame3 == "not found"
			and at.GameMenuFrame == "styled" and at.ClassTrainerFrame == "loads later" and at.PlayerSpellsFrame == "loads later")
		W.change("windows.bags", false)
		at = states(W.slash("windows"))
		check("windows command: a window of a group that is switched off says off, the others do not", at.ContainerFrame1 == "off" and at.BankFrame == "off" and at.GameMenuFrame == "styled")
		W.change("windows.enabled", false)
		at = states(W.slash("windows"))
		check("windows command: with the windows off every line says off", at.GameMenuFrame == "off" and at.PlayerSpellsFrame == "off" and at.LFGParentFrame == "off")
		local X = second()
		local real = X.env.hooksecurefunc
		X.env.hooksecurefunc = function(object, name, hook)
			if name == "ShowUIPanel" then
				error("hooksecurefunc failed", 0)
			end
			return real(object, name, hook)
		end
		up(X)
		check("windows command: a stopped module says stopped", states(X.slash("windows")).ContainerFrame1 == "stopped")
	end

	-- A client that lacks the globals the new windows use does nothing and raises nothing.
	do
		local W = second("demand")
		W.env.C_AddOns, W.env.StaticPopup_Show = nil, nil
		local _, n = up(W)
		check("no globals: without C_AddOns and StaticPopup_Show the windows are styled, the command works and a window that is not there loads later",
			W.state(n.ContainerFrame1) == "SB" and W.state(n.StaticPopup1) == "SB" and states(W.slash("windows")).PlayerSpellsFrame == "loads later" and #W.errors == 0 and #W.violations == 0, wvio(W))
		local H = second(true, { without = { hooksecurefunc = true } })
		local _, hn = up(H)
		H.blizzard(function() H.env.ContainerFrame_GenerateFrame(hn.ContainerFrame1) end)
		H.flush()
		check("no globals: without hooksecurefunc the bags are styled once and nothing raises", H.state(hn.ContainerFrame1) == "SB" and #H.errors == 0 and #H.violations == 0
			and not has(H.line("Windows"), "stopped"), wvio(H))
	end

	-- A protected bag window met in combat has its art faded at once and is given its box when combat ends.
	do
		local W = second(true, { combat = true })
		W.win.protect(W.win.names.ContainerFrame1, true)
		local _, n = up(W)
		local bag = n.ContainerFrame1
		check("combat: the art of a protected bag window is transparent at once, and nothing is made on it", wa(W, wraw(W, wraw(W, bag).NineSlice).TopEdge) == 0 and #wowned(W, bag) == 0
			and #W.violations == 0, wvio(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("combat: and the box is made when combat ends", W.state(bag) == "SB" and #W.violations == 0 and #W.errors == 0, wvio(W))
	end
end

-- Window titles: the title bar over the top of an open window drags it, and a right click puts it back. The sections are one function, so that
-- their helpers are not counted against the 200 locals of this file's main function.
do
-- Dragging and sizing a window from anywhere on it, the corner grip, and what the settings do. K holds the helpers of the section above.
local function drags(K)
local windowWorld, gripOf, cornerOf, pull, HOME = K.windowWorld, K.gripOf, K.cornerOf, K.pull, K.HOME
local entry, pts, allClean, problems, outText, opt = K.entry, K.pts, K.allClean, K.problems, K.outText, suiteKit.opt
local BODY, SMALL, MOVED = { 100, 700 }, { 100, 850 }, "TOPLEFT>UIParent:TOPLEFT 316,-316 @1"
local FROM, TITLE = "Anywhere on the window", "Title bar"
local RESET_TEXT = "Windows are back at their default place and size."

-- A frame of the game inside a window: spec.type is its object type, strata, clicks (false when it takes none), script a mouse script it
-- has, level, and x, y, w and h its place from the top left corner, or anchor = { point, x, y } its place from another corner.
local function child(W, parent, name, spec)
	spec = spec or {}
	local at = spec.anchor and { spec.anchor[1], parent, spec.anchor[1], spec.anchor[2], spec.anchor[3] } or { "TOPLEFT", parent, "TOPLEFT", spec.x or 20, spec.y or -60 }
	local proxy, raw = W.bframe(name, { parent = parent, point = at, width = spec.w or 40,
		height = spec.h or 40, fields = { objectType = spec.type or "Frame", strata = spec.strata, clicks = spec.clicks, mouse = true, level = spec.level } })
	if spec.script then
		raw.scripts[spec.script] = function() end
	end
	return proxy
end
-- The player presses the left button at `from` on `leaf`, moves the cursor to `to` for one frame, and lets go unless `hold`.
local function click(W, from, to, leaf, hold)
	local frames = #W.eventFrames
	W.pressAt(from[1], from[2], "LeftButton", leaf)
	if not W.carrier and #W.eventFrames > frames then
		W.carrier = W.eventFrames[frames + 1]
	end
	W.cursor = to
	W.update(1 / 60)
	if not hold then
		W.releaseAt("LeftButton")
	end
end
-- The left and the top of a window, in the units of UIParent.
local function topLeft(W, name)
	local l, b, _, h = W.rectOf(W.env[name])
	return l, b + h
end
local function scaleOf(W, name)
	return W.rawOf[W.env[name]].scale
end
-- The player drags the corner grip of a window out along the diagonal by t units across and t down.
local function grow(W, name, t)
	local l, b, w = W.rectOf(W.env[name])
	local x, y = l + w - 6, b + 6
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + t, y - t }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
end
-- A point six units in from the bottom right corner of a window, where the corner grip is.
local function cornerPoint(W, name)
	local l, b, w = W.rectOf(W.env[name])
	return l + w - 6, b + 6
end
local function alphas(W, corner)
	local out = {}
	for _, region in ipairs(W.rawOf[corner].regions) do
		out[#out + 1] = g(region.alpha)
	end
	return table.concat(out, ",")
end

-- The title bar and the corner grip lie above their window.
do
	local W = windowWorld(function(W)
		child(W, W.env.CharacterFrame, "TestLevelButton", { type = "Button" })
	end)
	W.openWindow("CharacterFrame")
	W.rawOf[W.env.ContainerFrame3].shown = true
	W.env.UpdateContainerFrameAnchors()
	local bag = W.rawOf[W.env.ContainerFrame3].level
	check("levels: the title bar of a window and of a bag lie two levels above it, and the corner grip one above its highest child", W.rawOf[gripOf(W, "CharacterFrame")].level == 9
		and W.rawOf[cornerOf(W, "CharacterFrame")].level == 9 and W.rawOf[gripOf(W, "ContainerFrame3")].level == bag + 2
		and W.rawOf[cornerOf(W, "ContainerFrame3")].level == bag + 1, tostring(bag))
	check("levels: the title bar is a child of the window", W.rawOf[gripOf(W, "CharacterFrame")].parent == W.env.CharacterFrame)
	check("levels: /flatui status gives no levels until a click has started no drag", not has(W.status(), "Window levels"), W.status())
	click(W, { 50, 880 }, { 350, 680 }, W.env.TestLevelButton)
	check("levels: then it gives the levels of both windows next to the line for that click", has(W.status(), "Last click on Character started no drag: on a control (TestLevelButton).")
		and has(W.status(), ("Window levels: Character 7, title bar 9, corner 9; Bag %d, title bar %d, corner %d"):format(bag, bag + 2, bag + 1)), W.status())
	check("levels: no violation", allClean(W), problems(W))
end

-- A press on an empty part of the window drags it from anywhere, or from the title bar only, as the setting says.
for _, from in ipairs({ FROM, TITLE }) do
	local W = windowWorld(function(W)
		W.rawOf[W.env.MerchantFrame].mouse = true
	end)
	W.change("movers.dragFrom", from)
	W.openWindow("MerchantFrame")
	click(W, BODY, { 400, 500 }, W.env.MerchantFrame)
	local e = entry(W, "MerchantFrame")
	if from == FROM then
		check("drag from anywhere: a press on the body moves the window with the cursor and saves the spot of a window", pts(W, W.env.MerchantFrame) == MOVED
			and e and e.kind == "window" and e.point == "TOPLEFT" and near(e.x, 316) and near(e.y, -316), pts(W, W.env.MerchantFrame))
	else
		check("drag from the title bar: a press on the body moves nothing, and /flatui status says why", pts(W, W.env.MerchantFrame) == HOME and e == nil
			and has(W.status(), "Last click on Vendor started no drag: outside the title bar."), W.status())
	end
	check("drag from: no violation", allClean(W), problems(W))
end

-- A window dragged by its title bar snaps to the middle of the screen as a handle does, and the middle line shows while it is dragged.
do
	local rectIs = suiteKit.rectIs
	local W = windowWorld()
	W.openWindow("CharacterFrame")
	local function line()
		for _, f in ipairs(W.addonFrames) do
			if f.parent == W.env.UIParent and #f.points == 2 and f.points[1][1] == "TOP" and f.points[2][1] == "BOTTOM" then
				return f
			end
		end
	end
	check("centre: with no window dragged the middle line is not made", line() == nil)
	pull(W, "CharacterFrame", { 200, 900 }, { 978, 700 }, false)
	check("centre: a window whose middle comes within 8 units of the middle of the screen snaps there while it is dragged", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 791,-316 @1",
		pts(W, W.env.CharacterFrame))
	check("centre: the middle line is shown while a window is dragged, and bright as it is snapped to it", line() ~= nil and line().shown == true and near(line().alpha, 1) and entry(W, "CharacterFrame") == nil)
	W.cursor = { 990, 700 }
	W.update(1 / 60)
	check("centre: and a window beyond 8 units is where the cursor takes it, and the line is dim", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 806,-316 @1" and near(line().alpha, 0.6),
		pts(W, W.env.CharacterFrame))
	W.cursor = { 982, 650 }
	W.update(1 / 60)
	check("centre: at 7 units it snaps again, at the height the cursor gives", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 791,-366 @1" and near(line().alpha, 1), pts(W, W.env.CharacterFrame))
	W.releaseAt("LeftButton")
	local e = entry(W, "CharacterFrame")
	check("centre: let go of, it is saved by TOP and the height of its top edge, as a window", e and e.point == "TOP" and e.x == 0 and near(e.y, -366) and e.kind == "window", e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("centre: it is in the middle with the size it had, and the line goes", pts(W, W.env.CharacterFrame) == "TOP>UIParent:TOP 0,-366 @1" and rectIs(W, "CharacterFrame", 791, 290, 338, 424)
		and line().shown == false, pts(W, W.env.CharacterFrame))
	W.run(2)
	check("centre: and it stays", pts(W, W.env.CharacterFrame) == "TOP>UIParent:TOP 0,-366 @1" and allClean(W), problems(W))
end
do
	-- With Snap while dragging off a window is where the cursor takes it.
	local W = windowWorld()
	W.change("movers.snap", "Off")
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 900 }, { 978, 700 }, true)
	local e = entry(W, "CharacterFrame")
	check("centre: with Snap while dragging off a window dragged to the middle is not snapped", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 794,-316 @1" and e and e.point == "TOPLEFT" and near(e.x, 794),
		pts(W, W.env.CharacterFrame))
end
do
	-- The line goes with the setting: Off shows none while a window is dragged, and Always shows it with the handles and not otherwise.
	local W = windowWorld()
	W.change("movers.middleLine", "Off")
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 900 }, { 978, 700 }, false)
	local shown = false
	for _, f in ipairs(W.addonFrames) do
		shown = shown or (f.parent == W.env.UIParent and #f.points == 2 and f.points[1][1] == "TOP" and f.points[2][1] == "BOTTOM" and f.shown == true)
	end
	W.releaseAt("LeftButton")
	check("centre: with the middle line off a window dragged to the middle still snaps and shows no line", not shown and entry(W, "CharacterFrame").point == "TOP")
	local A = windowWorld()
	A.change("movers.middleLine", "Always shown with the handles")
	A.openWindow("CharacterFrame")
	pull(A, "CharacterFrame", { 200, 900 }, { 400, 800 }, false)
	local seen = false
	for _, f in ipairs(A.addonFrames) do
		seen = seen or (f.parent == A.env.UIParent and #f.points == 2 and f.points[1][1] == "TOP" and f.points[2][1] == "BOTTOM" and f.shown == true)
	end
	A.releaseAt("LeftButton")
	check("centre: set to always, the line is not shown while a window is dragged and the handles are closed", not seen)
end
do
	-- Sizing a window by its corner grip snaps nothing and shows no line, and a window that was centred is saved by its corner when it is sized.
	local W = windowWorld()
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 900 }, { 978, 700 }, true)
	check("centre: a window that is centred is saved by TOP", entry(W, "CharacterFrame").point == "TOP")
	local l, b, w = W.rectOf(W.env.CharacterFrame)
	local x, y = l + w - 6, b + 6
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + 40, y - 40 }
	W.update(1 / 60)
	local shown = false
	for _, f in ipairs(W.addonFrames) do
		shown = shown or (f.parent == W.env.UIParent and #f.points == 2 and f.points[1][1] == "TOP" and f.points[2][1] == "BOTTOM" and f.shown == true)
	end
	W.releaseAt("LeftButton")
	check("centre: sizing a window shows no middle line", not shown and scaleOf(W, "CharacterFrame") > 1, tostring(scaleOf(W, "CharacterFrame")))
	check("centre: and a window that is sized is saved by its top left corner again, as the grip holds that corner", entry(W, "CharacterFrame").point == "TOPLEFT" and near(entry(W, "CharacterFrame").x, 791), (function()
		local e = entry(W, "CharacterFrame")
		return e.point .. " " .. g(e.x)
	end)())
end

do
	-- At another UI scale the middle is the middle of the wider screen, and the 8 units are units of UIParent, not pixels.
	local W = windowWorld(nil, { uiScale = 0.64 })
	local k = W.scale()
	local sw = 1080 * 16 / 9 / k
	local snapped = (sw - 338) / 2
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 500, 600 }, { 500 + (snapped + 5 - 16) * k, 600 - 100 * k }, false)
	local l = W.rectOf(W.env.CharacterFrame)
	check("centre: at UI scale 0.64 a window within 8 units of the middle of the wider screen snaps there", near(l, snapped, 1e-6), g(l) .. " " .. g(snapped))
	W.cursor = { 500 + (snapped + 9 - 16) * k, 600 - 100 * k }
	W.update(1 / 60)
	l = W.rectOf(W.env.CharacterFrame)
	check("centre: and not beyond 8 units, which are units of UIParent and not pixels", near(l, snapped + 9, 1e-6), g(l))
	W.cursor = { 500 + (snapped + 7 - 16) * k, 600 - 100 * k }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	local e = entry(W, "CharacterFrame")
	check("centre: dropped there it is saved by TOP with no offset across, at the height of its top edge", e and e.point == "TOP" and e.x == 0 and e.kind == "window" and near(e.y, -216, 1e-6)
		and near((W.rectOf(W.env.CharacterFrame)), snapped, 1e-6), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)) or "none")
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- The distance is measured on the window as it is on the screen: a window sized with the corner grip snaps by the middle of its size.
	local W = windowWorld()
	W.openWindow("CharacterFrame")
	grow(W, "CharacterFrame", 95.25)
	local l0, _, w0 = W.rectOf(W.env.CharacterFrame)
	local wanted = (1920 - w0) / 2
	pull(W, "CharacterFrame", { 200, 900 }, { 200 + (wanted + 6 - l0), 700 }, true)
	local l, _, w = W.rectOf(W.env.CharacterFrame)
	local e = entry(W, "CharacterFrame")
	check("centre: a window sized with the corner grip snaps by the middle of its size on the screen, and keeps the size", near(w0, 422.5, 1e-6) and near(l, wanted, 1e-6) and near(w, w0, 1e-6)
		and near(l + w / 2, 960, 1e-6) and e and e.point == "TOP" and e.x == 0 and near(e.scale, 1.25) and near(e.y, -316, 1e-6), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)) or "none")
	check("centre: no violation", allClean(W), problems(W))
end

