-- One press, one drag.
do
	local W = windowWorld()
	W.openWindow("MerchantFrame")
	click(W, BODY, { 150, 650 }, W.env.MerchantFrame)
	W.slash("move reset windows")
	local sets = 0
	local carrier = W.carrier
	local setScript = carrier.SetScript
	carrier.SetScript = function(self, which, fn)
		sets = sets + (which == "OnUpdate" and fn ~= nil and 1 or 0)
		return setScript(self, which, fn)
	end
	pull(W, "MerchantFrame", { 200, 950 }, { 500, 750 }, true)
	check("one press, one drag: a press on the title bar runs its script and the game reports it, and one drag is made and one spot saved", sets == 1
		and pts(W, W.env.MerchantFrame) == MOVED and W.line("Movers") == "Movers: on, 1 moved" and not has(W.status(), "started no drag"), sets .. " " .. pts(W, W.env.MerchantFrame))
	W.slash("move reset windows")
	W.pressAt(200, 950, "LeftButton", gripOf(W, "MerchantFrame"), true)
	W.cursor = { 500, 750 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("one press, one drag: so it is when the game reports the press before the script of the title bar runs", pts(W, W.env.MerchantFrame) == MOVED
		and not has(W.status(), "started no drag") and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env.MerchantFrame) .. " " .. W.status())
end

-- The key held while dragging.
for _, k in ipairs({ { "None" }, { "Shift", "shift" }, { "Alt", "alt" }, { "Ctrl", "ctrl" } }) do
	local label, key = k[1], k[2]
	local W = windowWorld()
	if key then
		W.change("movers.dragKey", label)
	end
	W.openWindow("MerchantFrame")
	local function body(keys)
		W.keys = keys
		click(W, BODY, { 400, 500 }, W.env.MerchantFrame)
		local moved = pts(W, W.env.MerchantFrame) ~= HOME
		W.keys = {}
		W.slash("move reset windows")
		return moved
	end
	local function bar(keys)
		W.keys = keys
		pull(W, "MerchantFrame", { 200, 950 }, { 500, 750 }, true)
		local moved = pts(W, W.env.MerchantFrame) ~= HOME
		W.keys = {}
		W.slash("move reset windows")
		return moved
	end
	if not key then
		check("key held, None: a press with no key and one with Shift held both drag", body({}) and body({ shift = true }) and bar({}) and bar({ shift = true }))
	else
		local other = key == "shift" and "alt" or "shift"
		local without, wrong = body({}), body({ [other] = true })
		local status = W.status()
		local right = body({ [key] = true })
		check("key held, " .. label .. ": the body drags only with the key held, and status says " .. label .. " is not held", not without and not wrong and right
			and has(status, "Last click on Vendor started no drag: " .. label .. " not held."), status)
		check("key held, " .. label .. ": the title bar obeys the key too", not bar({}) and not bar({ [other] = true }) and bar({ [key] = true }))
		W.keys = {}
		grow(W, "MerchantFrame", 76.2)
		check("key held, " .. label .. ": the corner grip ignores it", near(scaleOf(W, "MerchantFrame"), 1.2), scaleOf(W, "MerchantFrame"))
	end
	check("key held, " .. label .. ": no violation", allClean(W), problems(W))
end

