	local before = scaleOf(W, "TestWindow")
	W.pressOn(310, 770, "LeftButton")
	W.cursor = { 400, 680 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("corner grip, off: the frame is hidden and a press in the corner does nothing with dragging off too", not W.rawOf[corner].shown and scaleOf(W, "TestWindow") == before
		and entry(W, "TestWindow") == nil)
	W.change("movers.titles", true)
	W.change("movers.grip", "Shown on mouseover")
	check("corner grip: back on mouseover it is shown again", W.rawOf[corner].shown and allClean(W), problems(W))
end

-- A control in the corner of a window keeps its clicks. The corner grip takes the mouse only in its last four units until the game has reported a
-- press, and takes none after it; a press in the corner is the grip's where no control lies under it.
do
	local W = windowWorld()
	W.openWindow("QuestFrame")
	local raw = W.rawOf[cornerOf(W, "QuestFrame")]
	check("corner grip, before a press: it takes the mouse in its last four units only", raw.mouse == true and raw.hit and raw.hit[1] == 14 and raw.hit[2] == 0 and raw.hit[3] == 14 and raw.hit[4] == 0)
	W.pressAt(400, 500, "LeftButton", cornerOf(W, "QuestFrame"))
	W.releaseAt("LeftButton")
	check("corner grip: a press on a frame of the addon's is not a press on a game frame, so the grip still takes the mouse", raw.mouse == true)
	W.pressAt(400, 500, "LeftButton", W.env.QuestFrame)
	W.releaseAt("LeftButton")
	check("corner grip, after a press the game reported: it takes no mouse, and still shows", raw.mouse == false and raw.shown and allClean(W), problems(W))
	W.openWindow("MailFrame")
	check("corner grip: a window opened after that has a grip that takes no mouse either", W.rawOf[cornerOf(W, "MailFrame")].mouse == false)
end

for _, phase in ipairs({ "before a press is reported", "after it" }) do
	local W = windowWorld(function(W)
		child(W, W.env.MerchantFrame, "TestCornerButton", { type = "Button", anchor = { "BOTTOMRIGHT", -6, 4 }, w = 100, h = 22 })
		child(W, W.env.TestWindow, "TestBagSlot", { type = "Button", anchor = { "BOTTOMRIGHT", -7, 9 }, w = 37, h = 37 })
	end, { saved = opt({}, { TestWindow = { point = "TOPLEFT", x = 16, y = -116, scale = 1.25, kind = "window" } }) })
	W.openWindow("MerchantFrame")
	W.openWindow("TestWindow")
	if phase == "after it" then
		W.pressAt(900, 300, "LeftButton", W.env.MerchantFrame)
		W.releaseAt("LeftButton")
	end
	local l, b, w = W.rectOf(W.env.MerchantFrame)
	local x, y = l + w - 10, b + 10
	local leaf = W.hitAt(x, y)
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + 100, y - 100 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("controls in the corner, " .. phase .. ": a button at 6, 4 from the corner gets the press ten units in, and no size drag starts", leaf == W.env.TestCornerButton
		and near(scaleOf(W, "MerchantFrame"), 1) and entry(W, "MerchantFrame") == nil
		and has(W.status(), "Last click on Vendor started no drag: on a control (TestCornerButton)."), tostring(leaf) .. " " .. g(scaleOf(W, "MerchantFrame")))
	local sl, sb, sw = W.rectOf(W.env.TestBagSlot)
	local px, py = sl + sw - 2, sb + 2
	local slot = W.hitAt(px, py)
	W.pressOn(px, py, "RightButton")
	W.releaseAt("RightButton")
	check("controls in the corner, " .. phase .. ": an item slot at 7, 9 from the corner of a window at 125% gets a right click at its lower right corner, and the size stays",
		slot == W.env.TestBagSlot and near(scaleOf(W, "TestWindow"), 1.25) and near(entry(W, "TestWindow").scale, 1.25), tostring(slot) .. " " .. g(scaleOf(W, "TestWindow")))
	check("controls in the corner, " .. phase .. ": no violation", allClean(W), problems(W))
end

