-- The character window: its model fills the left pane and turns with the mouse, so a press there starts no drag, unless the key chosen for dragging is held.
do
	local function world(key)
		local W = windowWorld(function(W)
			W.rawOf[W.env.CharacterFrame].mouse = false
			child(W, W.env.CharacterFrame, "PaperDollFrame", { x = 0, y = 0, w = 338, h = 424, level = 7 })
			child(W, W.env.CharacterFrame, "CharacterModelScene", { type = "ModelScene", script = "OnMouseDown", x = 0, y = -20, w = 250, h = 404, level = 50 })
			child(W, W.env.CharacterFrame, "TestGearSlot", { type = "Button", x = 10, y = -40, w = 40, h = 40, level = 60 })
		end)
		if key then
			W.change("movers.dragKey", key)
		end
		W.openWindow("CharacterFrame")
		return W
	end
	local MODEL, STATS, SLOT = { 100, 700 }, { 300, 700 }, { 40, 900 }
	local W = world()
	local model, stats, slot = W.hitAt(MODEL[1], MODEL[2]), W.hitAt(STATS[1], STATS[2]), W.hitAt(SLOT[1], SLOT[2])
	check("character window: the model is under the left pane, the page frame under the right, and the equipment slot over the model",
		model == W.env.CharacterModelScene and stats == W.env.PaperDollFrame and slot == W.env.TestGearSlot)
	click(W, MODEL, { 400, 500 }, model)
	check("character window: a press on the model starts no drag, and status names the model", pts(W, W.env.CharacterFrame) == HOME and entry(W, "CharacterFrame") == nil
		and has(W.status(), "Last click on Character started no drag: on a control (CharacterModelScene)."), W.status())
	click(W, STATS, { 600, 500 }, stats)
	check("character window: a press on the right pane drags the window", pts(W, W.env.CharacterFrame) == MOVED and entry(W, "CharacterFrame") ~= nil, pts(W, W.env.CharacterFrame))
	W.slash("move reset windows")
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	check("character window: and so does the title bar", pts(W, W.env.CharacterFrame) == MOVED, pts(W, W.env.CharacterFrame))
	for _, key in ipairs({ { "Shift", "shift" }, { "Alt", "alt" }, { "Ctrl", "ctrl" } }) do
		local V = world(key[1])
		click(V, MODEL, { 400, 500 }, V.hitAt(MODEL[1], MODEL[2]))
		local without = pts(V, V.env.CharacterFrame) == HOME and has(V.status(), "started no drag: " .. key[1] .. " not held.")
		V.keys[key[2]] = true
		click(V, SLOT, { 400, 500 }, V.hitAt(SLOT[1], SLOT[2]))
		local button = pts(V, V.env.CharacterFrame) == HOME and has(V.status(), "started no drag: on a control (TestGearSlot).")
		click(V, MODEL, { 400, 500 }, V.hitAt(MODEL[1], MODEL[2]))
		check("character window, " .. key[1] .. ": the model gives the window to the key when it is held and not otherwise, and an equipment slot never does",
			without and button and pts(V, V.env.CharacterFrame) == MOVED and allClean(V), pts(V, V.env.CharacterFrame) .. " " .. V.status())
	end
end

