-- winsize: windows are sized by hooks. SetScale and OnShow only mark a window, and one hidden frame sizes the marked windows on the next frame.
do
	local W = windowWorld(nil, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }) })
	W.openWindow("QuestFrame")
	local quest, mail = W.env.QuestFrame, W.env.MailFrame
	local function runningFrames(W)
		local n = 0
		for _, f in ipairs(W.updaters) do
			if f.scripts and f.scripts.OnUpdate and f.shown and not f.dividers then
				n = n + 1
			end
		end
		return n
	end
	local function shows(frame)
		return #(W.rawOf[frame].hookScripts and W.rawOf[frame].hookScripts.OnShow or {})
	end
	check("winsize: a window sized under Every window together has a hook on SetScale and one on OnShow", INSTHOOK.wrapped(W, quest, "SetScale") and shows(quest) == 1, shows(quest))
	check("winsize: no window has a hook on SetWidth, SetHeight or SetSize", not INSTHOOK.wrapped(W, quest, "SetWidth") and not INSTHOOK.wrapped(W, quest, "SetHeight")
		and not INSTHOOK.wrapped(W, quest, "SetSize") and not INSTHOOK.wrapped(W, mail, "SetSize") and not INSTHOOK.wrapped(W, mail, "SetWidth"))
	check("winsize: every window the panel manager lists has the two hooks, one that is closed too", INSTHOOK.wrapped(W, mail, "SetScale") and shows(mail) == 1)
	W.openWindow("QuestFrame")
	W.openWindow("MailFrame")
	W.closeWindow("MailFrame")
	W.run(1, 0.25)
	check("winsize: a window is hooked once however often the windows are sized", shows(quest) == 1 and shows(mail) == 1, shows(quest) .. " " .. shows(mail))
	local idle = runningFrames(W)
	W.gameScales("QuestFrame", 1)
	check("winsize: the hook only marks: the scale the game wrote stays until the next frame", near(scaleOf(W, "QuestFrame"), 1) and runningFrames(W) == idle + 1,
		g(scaleOf(W, "QuestFrame")) .. " " .. runningFrames(W))
	W.update(1 / 60)
	check("winsize: the window is at 120% on the next frame, not after half a second, and the frame that sizes stops", near(scaleOf(W, "QuestFrame"), 1.2) and runningFrames(W) == idle,
		g(scaleOf(W, "QuestFrame")) .. " " .. runningFrames(W))
	W.fit("QuestFrame", 1)
	W.fit("QuestFrame", 1)
	W.update(1 / 60)
	check("winsize: two writes in one frame are one sizing", near(scaleOf(W, "QuestFrame"), 1.2) and allClean(W), g(scaleOf(W, "QuestFrame")) .. " " .. problems(W))
	W.rawOf[W.env.FriendsFrame].shown = true
	W.hookRun(W.env.FriendsFrame, "OnShow")
	check("winsize: a window shown without the panel manager's announcement is marked, and not sized in the call", near(scaleOf(W, "FriendsFrame"), 1), g(scaleOf(W, "FriendsFrame")))
	W.update(1 / 60)
	check("winsize: it is sized on the next frame", near(scaleOf(W, "FriendsFrame"), 1.2), g(scaleOf(W, "FriendsFrame")))
	W.run(1, 0.25)
	check("winsize: the sizes the addon writes do not mark a window again, so it keeps 120%", near(scaleOf(W, "QuestFrame"), 1.2) and near(scaleOf(W, "FriendsFrame"), 1.2) and allClean(W), problems(W))
end

-- A window the panel manager fits to the screen has the game's fit as its base.
do
	local W = windowWorld(function(W)
		W.env.UIPanelWindows.LegacySystemFrame.checkFit = 1
		W.rawOf[W.env.LegacySystemFrame].scale = 0.8
	end, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }) })
	W.openWindow("LegacySystemFrame")
	W.openWindow("QuestFrame")
	check("winsize: a fitted window first seen at the game's fit of 80% is at 120% of that", near(scaleOf(W, "LegacySystemFrame"), 0.96), g(scaleOf(W, "LegacySystemFrame")))
	W.run(1, 0.25)
	check("winsize: the scale the addon wrote is not taken for the game's fit, so the window does not grow each time it is sized", near(scaleOf(W, "LegacySystemFrame"), 0.96),
		g(scaleOf(W, "LegacySystemFrame")))
	W.fit("LegacySystemFrame", 0.5)
	W.update(1 / 60)
	check("winsize: the game fits it to 50%: it is at 120% of 50%", near(scaleOf(W, "LegacySystemFrame"), 0.6), g(scaleOf(W, "LegacySystemFrame")))
	W.fit("LegacySystemFrame", 1)
	W.update(1 / 60)
	check("winsize: the game fits it to 100% again: it is at 120% of 100%", near(scaleOf(W, "LegacySystemFrame"), 1.2), g(scaleOf(W, "LegacySystemFrame")))
	W.fit("LegacySystemFrame", 0.8)
	W.update(1 / 60)
	W.fit("LegacySystemFrame", 0.96)
	W.update(1 / 60)
	check("winsize: a fit that is the scale the addon wrote is still the game's: the window is at 120% of it", near(scaleOf(W, "LegacySystemFrame"), 1.152), g(scaleOf(W, "LegacySystemFrame")))
	W.fit("LegacySystemFrame", 1)
	W.update(1 / 60)
	W.gameScales("QuestFrame", 0.7)
	W.update(1 / 60)
	check("winsize: a window the game does not fit keeps the scale it had first: 120% of that, whatever the game wrote", near(scaleOf(W, "QuestFrame"), 1.2) and allClean(W),
		g(scaleOf(W, "QuestFrame")) .. " " .. problems(W))
end

-- Under Every window together a window with a spot is put at the shared size at its spot on the next frame.
do
	local W = windowWorld(nil, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 },
		{ FriendsFrame = { point = "TOPLEFT", x = 216, y = -216, scale = 0.8, kind = "window" } }) })
	W.openWindow("FriendsFrame")
	check("winsize: a window with a spot has its hooks", INSTHOOK.wrapped(W, W.env.FriendsFrame, "SetScale") and near(scaleOf(W, "FriendsFrame"), 1.2), g(scaleOf(W, "FriendsFrame")))
	W.fit("FriendsFrame", 1)
	check("winsize: the game gives it its own scale", near(scaleOf(W, "FriendsFrame"), 1), g(scaleOf(W, "FriendsFrame")))
	W.update(1 / 60)
	local l, top = topLeft(W, "FriendsFrame")
	check("winsize: it is at the shared size and at its spot on the next frame", near(scaleOf(W, "FriendsFrame"), 1.2) and near(l, 216) and near(top, 864) and allClean(W),
		g(scaleOf(W, "FriendsFrame")) .. " " .. g(l) .. "," .. g(top))
end

-- A protected window the game sizes in a fight is left alone in it, and put right when it is over. The game's own code may size it in a fight.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }, { CharacterFrame = { point = "TOPLEFT", x = 316, y = -316, scale = 0.8, kind = "window" } }) })
	W.openWindow("QuestFrame")
	W.openWindow("CharacterFrame")
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.rawOf[W.env.CharacterFrame].combatOk = true
	W.fit("CharacterFrame", 1)
	W.update(1 / 60)
	W.update(1 / 60)
	check("winsize: a protected window with a spot that the game sizes in a fight is not touched in it", near(scaleOf(W, "CharacterFrame"), 1) and allClean(W), g(scaleOf(W, "CharacterFrame")) .. " " .. problems(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	W.update(1 / 60)
	W.update(1 / 60)
	check("winsize: it is put at the shared size at its spot once the fight is over", near(scaleOf(W, "CharacterFrame"), 1.2) and allClean(W), g(scaleOf(W, "CharacterFrame")) .. " " .. problems(W))
end

-- What the hooks cannot see is left to the half-second check: a window whose hooks the game's taintLog refuses, and a window that does not exist yet.
do
	local W = windowWorld(function(W)
		W.cvars.taintLog = "1"
	end, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }) })
	W.openWindow("QuestFrame")
	W.flush()
	check("winsize: with taintLog on no hook is put on a window, and the window is sized by the event", not INSTHOOK.wrapped(W, W.env.QuestFrame, "SetScale") and near(scaleOf(W, "QuestFrame"), 1.2),
		g(scaleOf(W, "QuestFrame")))
	W.gameScales("QuestFrame", 1)
	W.update(1 / 60)
	check("winsize: a scale the game writes then waits for the half-second check", near(scaleOf(W, "QuestFrame"), 1), g(scaleOf(W, "QuestFrame")))
	W.run(0.6, 0.1)
	check("winsize: the check puts the window at 120%", near(scaleOf(W, "QuestFrame"), 1.2), g(scaleOf(W, "QuestFrame")))
end

do
	local late
	local W = windowWorld(function(W)
		late = W.env.TestWindow
		W.env.TestWindow = nil
	end, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }) })
	W.openWindow("QuestFrame")
	W.env.TestWindow = late
	W.rawOf[late].shown = true
	check("winsize: a window that has no frame yet has no hook", not INSTHOOK.wrapped(W, late, "SetScale"))
	W.run(0.6, 0.1)
	check("winsize: the half-second check hooks it once it exists, and sizes it", INSTHOOK.wrapped(W, late, "SetScale") and near(W.rawOf[late].scale, 1.2) and allClean(W), g(W.rawOf[late].scale))
	W.gameScales("TestWindow", 1)
	W.update(1 / 60)
	check("winsize: after that the hooks size it on the next frame", near(W.rawOf[late].scale, 1.2), g(W.rawOf[late].scale))
end

do
	local W = windowWorld()
	W.openWindow("QuestFrame")
	W.openWindow("FriendsFrame")
	check("winsize: with the size at 100% and no spot saved, no window is hooked", not INSTHOOK.wrapped(W, W.env.QuestFrame, "SetScale") and not INSTHOOK.wrapped(W, W.env.FriendsFrame, "SetScale")
		and allClean(W), problems(W))
