	grow(W, "TestWindow", 62.5)
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, false)
	local during = scaleOf(W, "TestWindow")
	W.releaseAt("LeftButton")
	check("drag: a window at 125% is at 125% while it is dragged and after", near(during, 1.25) and near(scaleOf(W, "TestWindow"), 1.25) and near(entry(W, "TestWindow").scale, 1.25), g(during))
end

-- The title bar drags nothing while Edit Mode is open or a frame is being picked.
do
	local W = windowWorld()
	W.openWindow("MerchantFrame")
	W.editMode(true)
	pull(W, "MerchantFrame", { 200, 950 }, { 500, 750 }, true)
