	W.editMode(false)
	W.slash("grab")
	pull(W, "MerchantFrame", { 200, 950 }, { 500, 750 }, true)
	check("edit mode and picker: the title bar drags nothing while Edit Mode is open or a frame is being picked", editing and pts(W, W.env.MerchantFrame) == HOME and allClean(W))
end

-- The title bar takes the press over a frame of the game that lies one level above the window.
do
	local W = windowWorld(function(W)
		child(W, W.env.MerchantFrame, "TestTitleText", { x = 0, y = 0, w = 300, h = 22 })
	end)
	W.openWindow("MerchantFrame")
	local leaf = W.hitAt(100, 953)
	W.pressOn(100, 953, "LeftButton")
	W.cursor = { 400, 753 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("title bar: it takes a press over a frame of the game one level above the window, and the press drags", leaf == gripOf(W, "MerchantFrame") and pts(W, W.env.MerchantFrame) == MOVED,
		tostring(leaf) .. " " .. pts(W, W.env.MerchantFrame))
end

-- A frame under the cursor that the client will not describe keeps its clicks, and so does a cursor that will not say what it holds.
do
	local faults = { { "objectType", "secret" }, { "objectType", "error" }, { "hasScript", "secret" }, { "hasScript", "error" }, { "getScript", "secret", "OnMouseDown" },
		{ "getScript", "error", "OnMouseDown" }, { "clicks", "secret" }, { "clicks", "error" } }
	local W = windowWorld(function(W)
		for i, fault in ipairs(faults) do
			child(W, W.env.MerchantFrame, "TestFault" .. i, { x = 20 * i, y = -60, w = 20, script = fault[3] })
		end
	end)
	W.openWindow("MerchantFrame")
	local bad = {}
	for i, fault in ipairs(faults) do
		W.rawOf[W.env["TestFault" .. i]].fault[fault[1]] = fault[2]
		click(W, BODY, { 400, 500 }, W.env["TestFault" .. i])
		if pts(W, W.env.MerchantFrame) ~= HOME or entry(W, "MerchantFrame") ~= nil then
			bad[#bad + 1] = fault[1] .. " " .. fault[2]
			W.slash("move reset windows")
		end
	end
	for _, how in ipairs({ "error", "secret" }) do
		W.env.GetCursorInfo = function()
			if how == "error" then
				error("boom", 0)
			end
			return SECRET
		end
		click(W, BODY, { 400, 500 }, W.env.MerchantFrame)
		if pts(W, W.env.MerchantFrame) ~= HOME or entry(W, "MerchantFrame") ~= nil then
			bad[#bad + 1] = "cursor " .. how
		end
	end
	check("withheld values: a frame whose type, scripts or click flag the client withholds, or a cursor that will not say what it holds, starts no drag", #bad == 0 and allClean(W),
		table.concat(bad, ", ") .. " " .. problems(W))
end

