	check("switches: turning dragging off during a drag ends it where the window was", pts(W, W.env.TestWindow) == "TOPLEFT>UIParent:TOPLEFT 216,-316 @1" and W.carrier.scripts.OnUpdate == nil
		and entry(W, "TestWindow") ~= nil, pts(W, W.env.TestWindow))
end

-- A right click on the title bar or the corner of a protected window in a fight changes nothing, says so, and says so again in the next fight.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end)
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	grow(W, "CharacterFrame", 95.25)
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.out = {}
	W.pressAt(200, 950, "RightButton", gripOf(W, "CharacterFrame"))
	W.releaseAt("RightButton")
	local x, y = cornerPoint(W, "CharacterFrame")
	W.pressOn(x, y, "RightButton")
	W.releaseAt("RightButton")
	local e = entry(W, "CharacterFrame")
	check("combat: a right click on the title bar or the corner of a protected window changes nothing and says so once for each", e and near(e.scale, 1.25) and near(e.x, 316)
		and outText(W) == "This window cannot be moved in combat.\nThis window cannot be sized in combat." and allClean(W), outText(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.out = {}
	grow(W, "CharacterFrame", 50)
	check("combat: and the line for a size is said again in the next fight", outText(W) == "This window cannot be sized in combat.", outText(W))
end

-- The game writes the scale of a window too.
do
	local W = windowWorld()
	W.openWindow("TestWindow")
	grow(W, "TestWindow", 62.5)
	local bad = 0
	for _ = 1, 10 do
		W.fit("TestWindow", 1)
		W.run(0.5, 0.5)
		local l, top = topLeft(W, "TestWindow")
		if not (near(scaleOf(W, "TestWindow"), 1.25) and near(l, 16) and near(top, 964)) then
			bad = bad + 1
		end
	end
	check("the game writes scale: a window sized to 125% is back at its size with its top left corner where it was after each check of half a second", bad == 0, bad)
	check("the game writes scale: after ten such resets status says so", has(W.status(), "TestWindow: the game set its size again 10 times."), W.status())
end

do
	local W = windowWorld(nil, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }) })
	W.openWindow("QuestFrame")
	local bad = 0
	for _ = 1, 10 do
		W.fit("QuestFrame", 1)
		W.gamePlaces("QuestFrame", "TOPLEFT", 16, -116)
		W.run(0.5, 0.5)
		local l, top = topLeft(W, "QuestFrame")
		if not (near(scaleOf(W, "QuestFrame"), 1.2) and near(l, 16) and near(top, 964)) then
			bad = bad + 1
		end
	end
	check("the game writes scale: a window with no spot under the shared size is back at it, at the game's place, after each check", bad == 0 and entry(W, "QuestFrame") == nil, bad)
	check("the game writes scale: and after ten such resets status says so", has(W.status(), "Quest: the game set its size again 10 times."), W.status())
	local V = windowWorld(nil, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 100 }) })
	V.openWindow("QuestFrame")
	for step = 1, 12 do
		V.change("movers.windowSize", step % 2 == 0 and 105 or 110)
	end
	check("the game writes scale: a change of the size by the player is not counted as the game's", not has(V.status(), "set its size again"), V.status())
end

-- The panel manager places a moved window again.
do
	local W = windowWorld(function(W)
		W.env.UpdateUIPanelPositions = function() end
	end)
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	W.openWindow("FriendsFrame")
	local at = pts(W, W.env.CharacterFrame)
	W.flush()
	check("panel manager: a second window opens, the game places the first one in its slot and announces it, and it is at its spot when the call returns and after the next frame",
		at == MOVED and pts(W, W.env.CharacterFrame) == MOVED, at)
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	W.run(0.5, 0.5)
	check("panel manager: a move the game does not announce is undone within half a second", pts(W, W.env.CharacterFrame) == MOVED, pts(W, W.env.CharacterFrame))
	W.change("movers.keep", false)
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	W.run(1, 0.5)
	check("panel manager: and left alone with Keep moved frames in place off", pts(W, W.env.CharacterFrame) == HOME, pts(W, W.env.CharacterFrame))
	W.change("movers.keep", true)
	local quest = pts(W, W.env.QuestFrame)
	W.env.UpdateUIPanelPositions(W.env.QuestFrame)
	W.openWindowEarly("MailFrame")
	check("panel manager: the layout call made while a window is still hidden changes nothing and raises nothing", pts(W, W.env.QuestFrame) == quest and pts(W, W.env.MailFrame) == HOME
		and allClean(W), problems(W))
end

