-- Combat.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end)
	W.openWindow("CharacterFrame")
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	local raw = W.rawOf[W.env.CharacterFrame]
	local was = (raw.calls.SetPoint or 0) + (raw.calls.ClearAllPoints or 0) + (raw.calls.SetScale or 0)
	W.out = {}
	click(W, BODY, { 400, 500 }, W.env.CharacterFrame)
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	for _ = 1, 2 do
		W.pressOn(345, 548, "LeftButton")
		W.cursor = { 445, 448 }
		W.update(1 / 60)
		W.releaseAt("LeftButton")
	end
	click(W, BODY, { 400, 500 }, W.env.CharacterFrame)
	check("combat: a press on the body, the title bar and the corner grip of a protected window, each moved a long way, calls nothing on the window", (raw.calls.SetPoint or 0)
		+ (raw.calls.ClearAllPoints or 0) + (raw.calls.SetScale or 0) == was and pts(W, W.env.CharacterFrame) == HOME and entry(W, "CharacterFrame") == nil and allClean(W), problems(W))
	check("combat: the player is told once that windows cannot be moved and once that they cannot be sized", outText(W) == "This window cannot be moved in combat.\nThis window cannot be sized in combat.", outText(W))
	W.out = {}
	click(W, BODY, { 402, 700 }, W.env.CharacterFrame)
	check("combat: a press that does not move prints nothing", #W.out == 0)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	check("combat ends: the same drag moves the window", pts(W, W.env.CharacterFrame) == MOVED, pts(W, W.env.CharacterFrame))
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.out = {}
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, true)
	check("the next fight: the line is printed again", outText(W) == "This window cannot be moved in combat.", outText(W))
end

do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end)
	W.openWindow("CharacterFrame")
	W.openWindow("FriendsFrame")
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	pull(W, "FriendsFrame", { 200, 950 }, { 500, 750 }, true)
	check("combat: a window that is not protected is dragged", pts(W, W.env.FriendsFrame) == MOVED and allClean(W), problems(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	-- A drag under way when a fight starts.
	W.openWindow("CharacterFrame")
	pull(W, "CharacterFrame", { 200, 950 }, { 500, 750 }, false)
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.cursor = { 700, 600 }
	W.update(1 / 60)
	local e = entry(W, "CharacterFrame")
	check("combat starts during a drag of a protected window: the drag ends and saves the last spot", e and near(e.x, 316) and near(e.y, -316) and pts(W, W.env.CharacterFrame) == MOVED
		and allClean(W), tostring(e and e.x))
	-- The game displaces the saved window in combat.
	local raw = W.rawOf[W.env.CharacterFrame]
	raw.protected = false
	W.gamePlaces("CharacterFrame", "TOPLEFT", 16, -116)
	raw.protected = true
	W.registry:TriggerEvent("UIParentPanelManager.ShowUIPanel", W.env.CharacterFrame, false)
	check("combat: a spot the game displaces in combat is not applied in combat", pts(W, W.env.CharacterFrame) == HOME and allClean(W), problems(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("combat ends: and it is applied", pts(W, W.env.CharacterFrame) == MOVED, pts(W, W.env.CharacterFrame))
end

do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end)
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.openWindow("CharacterFrame")
	check("combat: a protected window first opened in combat has no grips, and status says it waits", gripOf(W, "CharacterFrame") == nil and cornerOf(W, "CharacterFrame") == nil
		and has(W.status(), "Character cannot be dragged: it waits for the end of combat.") and allClean(W), W.status())
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("combat ends: it has both grips, and the line is gone", gripOf(W, "CharacterFrame") ~= nil and cornerOf(W, "CharacterFrame") ~= nil and not has(W.status(), "waits for the end"), W.status())
end

-- Positions and sizes kept, or back to default when the window closes.
do
	local W = windowWorld()
	W.openWindow("TestWindow")
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, true)
	grow(W, "TestWindow", 62.5)
	W.closeWindow("TestWindow")
	W.openWindow("TestWindow")
	check("kept: a moved and sized window closed and opened again is at its spot and its scale", entry(W, "TestWindow") ~= nil and near(scaleOf(W, "TestWindow"), 1.25)
		and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env.TestWindow))
end

do
	local W = windowWorld()
	W.change("movers.keepSpots", "Back to default when the window closes")
	W.change("movers.sizeScope", "Every window together")
	W.change("movers.windowSize", 120)
	W.change("movers.sizeScope", "Each window")
	W.openWindow("TestWindow")
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, true)
	grow(W, "TestWindow", 62.5)
	W.closeWindow("TestWindow")
	check("back to default, announced close: the spot is dropped, the game's points and scale are back and nothing counts as moved", entry(W, "TestWindow") == nil
		and pts(W, W.env.TestWindow) == HOME and W.line("Movers") == "Movers: on, 0 moved", pts(W, W.env.TestWindow))
	W.openWindow("TestWindow")
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, true)
	local grip = gripOf(W, "TestWindow")
	W.rawOf[W.env.TestWindow].shown = false
	W.rawOf[grip].scripts.OnHide(grip)
	check("back to default, plain Hide: the title bar's OnHide drops the spot too", entry(W, "TestWindow") == nil and pts(W, W.env.TestWindow) == HOME, pts(W, W.env.TestWindow))
	W.rawOf[W.env.TestWindow].shown = true
	W.openWindow("TestWindow")
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, true)
	W.rawOf[W.uiInner].shown = false
	W.rawOf[grip].scripts.OnHide(grip)
	W.rawOf[W.uiInner].shown = true
	check("back to default: hiding UIParent while the window stays shown drops nothing", entry(W, "TestWindow") ~= nil)
	check("back to default: the size of every window is a setting and stays", W.ns.Get("movers.windowSize") == 120 and allClean(W), problems(W))
end

do
	local W = windowWorld(nil, { saved = opt({}, { TestWindow = { point = "TOPLEFT", x = 116, y = -116, kind = "window" } }) })
	check("back to default: a spot of a closed window is kept under Kept", entry(W, "TestWindow") ~= nil)
	W.change("movers.keepSpots", "Back to default when the window closes")
	check("back to default: switching to it drops the spot of a window that is closed at once", entry(W, "TestWindow") == nil)
end

-- winreset: the default is Back to default when the window closes, and no setup profile sets it.
do
	local W = windowWorld(nil, { keepDefault = true })
	W.openWindow("TestWindow")
	pull(W, "TestWindow", { 200, 950 }, { 400, 750 }, true)
	W.closeWindow("TestWindow")
	W.openWindow("TestWindow")
	check("winreset: a window moved, closed and opened again is at its default place with no spot", W.ns.Get("movers.keepSpots") == "reset" and entry(W, "TestWindow") == nil
		and pts(W, W.env.TestWindow) == HOME, pts(W, W.env.TestWindow))
	local set = false
	for _, profile in ipairs(W.ns.SETUP_PROFILES or {}) do
		set = set or profile.values["movers.keepSpots"] ~= nil
	end
	check("winreset: no setup profile sets Positions and sizes", #(W.ns.SETUP_PROFILES or {}) > 0 and not set)
end

-- Reset windows.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }, {
		CharacterFrame = { point = "TOPLEFT", x = 316, y = -316, kind = "window" }, FriendsFrame = { point = "TOPLEFT", x = 216, y = -216, scale = 0.8, kind = "window" },
		UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } }) })
	W.openWindow("CharacterFrame")
	W.openWindow("FriendsFrame")
	W.openWindow("QuestFrame")
	local says = W.slash("move reset windows")
	check("reset windows: the command drops both window spots, keeps the one of the other frame, sets the size of every window to 100% and says so", says == RESET_TEXT and entry(W, "CharacterFrame") == nil
		and entry(W, "FriendsFrame") == nil and entry(W, "UIErrorsFrame") ~= nil and W.ns.Get("movers.windowSize") == 100, says)
	check("reset windows: open windows are at the game's points and scale", pts(W, W.env.CharacterFrame) == HOME and pts(W, W.env.FriendsFrame) == HOME and pts(W, W.env.QuestFrame) == HOME
		and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env.FriendsFrame))
	local lines = W.ns.WindowResetLines()
	check("reset windows: the row has one line with the id 1", #lines == 1 and lines[1][1] == 1 and lines[1][2] == "Every window to its default place and size")
	W.change("movers.sizeScope", "Every window together")
	W.change("movers.windowSize", 130)
	W.out = {}
	W.ns.WindowsReset(1)
	check("reset windows: choosing the row does the same", outText(W) == RESET_TEXT and W.ns.Get("movers.windowSize") == 100 and near(scaleOf(W, "QuestFrame"), 1), outText(W))
	W.change("movers.windowSize", 120)
	pull(W, "QuestFrame", { 200, 950 }, { 500, 750 }, true)
	W.out = {}
	W.ns.WindowsReset(2)
	check("reset windows: and no other id does anything: nothing is printed, the size of every window and the spot of a moved window stay", outText(W) == ""
		and W.ns.Get("movers.windowSize") == 120 and entry(W, "QuestFrame") ~= nil and pts(W, W.env.QuestFrame) ~= HOME and allClean(W), outText(W) .. " " .. pts(W, W.env.QuestFrame))
	check("reset: /flatui move reset puts every moved frame back and leaves the size of every window, and a frame that is not a window does not get it", W.slash("move reset") == "Moved frames are back where the game has them."
		and entry(W, "UIErrorsFrame") == nil and W.ns.Get("movers.windowSize") == 120 and near(scaleOf(W, "UIErrorsFrame"), 1) and near(scaleOf(W, "QuestFrame"), 1.2), g(scaleOf(W, "UIErrorsFrame")))
end

do
	local W = windowWorld(function(W)
		W.rawOf[W.env.CharacterFrame].protected = true
	end, { saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 316, y = -316, kind = "window" } }) })
	W.openWindow("CharacterFrame")
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	local says = W.slash("move reset windows")
	check("reset windows in combat: the spot is dropped and the protected window goes back after the fight, and the player is told", says == RESET_TEXT .. "\nSome windows go back after combat."
		and entry(W, "CharacterFrame") == nil and pts(W, W.env.CharacterFrame) == MOVED and allClean(W), says)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("reset windows in combat: it is at the game's place when the fight ends", pts(W, W.env.CharacterFrame) == HOME, pts(W, W.env.CharacterFrame))
end

do
	local W = windowWorld(function(W)
		W.loadedAddons.MoveAny = true
	end, { saved = opt({}, { CharacterFrame = { point = "TOPLEFT", x = 316, y = -316, kind = "window" } }) })
	local says, plain = W.slash("move reset windows"), W.slash("move reset")
	W.out = {}
	W.ns.WindowsReset(1)
	check("reset windows with another mover loaded: the command and the row print what /flatui move reset prints, and change nothing", says == plain and has(says, "MoveAny")
		and outText(W) == plain and entry(W, "CharacterFrame") ~= nil, says)
end

-- Profiles.
do
	local names = { "titles", "dragFrom", "dragKey", "grip", "keepSpots", "sizeScope", "windowSize" }
	local set = { ["movers.titles"] = false, ["movers.dragFrom"] = "title", ["movers.dragKey"] = "shift", ["movers.grip"] = "always", ["movers.keepSpots"] = "kept",
		["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }
	local W = windowWorld(nil, { saved = opt(set, { TestWindow = { point = "TOPLEFT", x = 116, y = -116, scale = 1.25, kind = "window" } }) })
	W.openWindow("TestWindow")
	W.openWindow("QuestFrame")
	check("profiles: profile A shows its window at its spot, and a window without a spot at the size of every window", near(scaleOf(W, "TestWindow"), 1.2) and near(scaleOf(W, "QuestFrame"), 1.2))
	local line = W.ns.ExportProfile()
	W.ns.NewProfile("Plain")
	check("profiles: a profile with neither puts every window at the game's place and scale", pts(W, W.env.TestWindow) == HOME and pts(W, W.env.QuestFrame) == HOME, pts(W, W.env.TestWindow))
	W.ns.UseProfile("Default")
	check("profiles: and the first one puts them back", near(scaleOf(W, "TestWindow"), 1.2) and near(scaleOf(W, "QuestFrame"), 1.2) and entry(W, "TestWindow") ~= nil)
	W.ns.NewProfile("Copy")
	W.ns.ImportProfile(line)
	local same, e = true, entry(W, "TestWindow")
	for _, key in ipairs(names) do
		same = same and W.ns.Get("movers." .. key) == set["movers." .. key]
	end
	check("profiles: an export of A imported into a new profile has the same spot, scale and seven settings", same and e and near(e.scale, 1.25) and near(e.x, 116) and allClean(W), problems(W))
	local old = windowWorld(nil, { saved = opt({ ["movers.titles"] = false }), keepDefault = true })
	local defaults = true
	for _, key in ipairs({ "dragFrom", "dragKey", "grip", "keepSpots", "sizeScope", "windowSize", "resetWindows" }) do
		defaults = defaults and not old.ns.IsSet("movers." .. key)
	end
	old.openWindow("TestWindow")
	check("profiles: a table saved by 0.4.0 with Window dragging off loads with dragging off and every new setting at its default",
		old.ns.Get("movers.titles") == false and old.ns.Get("movers.dragFrom") == "anywhere" and old.ns.Get("movers.dragKey") == "none" and old.ns.Get("movers.grip") == "hover"
		and old.ns.Get("movers.keepSpots") == "reset" and old.ns.Get("movers.sizeScope") == "each" and old.ns.Get("movers.windowSize") == 100 and defaults and not old.rawOf[gripOf(old, "TestWindow")].shown)
end

-- The switches.
do
	local W = windowWorld()
	W.change("movers.titles", false)
	W.openWindow("TestWindow")
	click(W, SMALL, { 400, 700 }, W.env.TestWindow)
	local still = pts(W, W.env.TestWindow) == HOME
	pull(W, "TestWindow", { 200, 950 }, { 500, 750 }, true)
	grow(W, "TestWindow", 62.5)
	W.pressOn(select(1, cornerPoint(W, "TestWindow")), select(2, cornerPoint(W, "TestWindow")), "RightButton")
	W.releaseAt("RightButton")
	local rightClick = near(scaleOf(W, "TestWindow"), 1)
	grow(W, "TestWindow", 62.5)
	local e = entry(W, "TestWindow")
	check("switches, dragging off: no press drags, the title bar is hidden, and the corner grip still sizes and resets with a right click", still and rightClick and e and near(e.x, 16) and near(e.y, -116) and near(e.scale, 1.25)
		and not W.rawOf[gripOf(W, "TestWindow")].shown and W.rawOf[cornerOf(W, "TestWindow")].shown and near(scaleOf(W, "TestWindow"), 1.25), pts(W, W.env.TestWindow))
	local V = windowWorld()
	V.change("movers.grip", "Off")
	V.openWindow("TestWindow")
	grow(V, "TestWindow", 62.5)
	check("switches, corner grip off: the corner is hidden and does not size, and a press there drags the window like a press anywhere", near(scaleOf(V, "TestWindow"), 1)
		and not V.rawOf[cornerOf(V, "TestWindow")].shown and pts(V, V.env.TestWindow) == "TOPLEFT>UIParent:TOPLEFT 78.5,-178.5 @1", pts(V, V.env.TestWindow))
	V.slash("move reset windows")
	click(V, SMALL, { 400, 750 }, V.env.TestWindow)
	check("switches, corner grip off: and windows still drag", pts(V, V.env.TestWindow) == "TOPLEFT>UIParent:TOPLEFT 316,-216 @1", pts(V, V.env.TestWindow))
	local U = windowWorld(nil, { saved = opt({ ["movers.sizeScope"] = "all", ["movers.windowSize"] = 120 }, { FriendsFrame = { point = "TOPLEFT", x = 216, y = -216, scale = 0.8, kind = "window" } }) })
	U.openWindow("TestWindow")
	U.openWindow("FriendsFrame")
	U.change("movers.enabled", false)
	click(U, SMALL, { 400, 750 }, U.env.TestWindow)
	check("switches, Move frames off: nothing drags, both grips are hidden and every size is undone", pts(U, U.env.TestWindow) == HOME and pts(U, U.env.FriendsFrame) == HOME
		and not U.rawOf[gripOf(U, "TestWindow")].shown and not U.rawOf[cornerOf(U, "TestWindow")].shown and allClean(U), pts(U, U.env.FriendsFrame))
	for _, windows in ipairs({ false, true }) do
		for _, handles in ipairs({ false, true }) do
			local S = windowWorld()
			if windows then
				S.change("windows.enabled", false)
			end
			S.openWindow("MerchantFrame")
			if handles then
				S.slash("move")
			end
			click(S, BODY, { 400, 500 }, S.env.MerchantFrame)
			check(("switches: with the windows page %s and the handles %s a press still drags"):format(windows and "off" or "on", handles and "open" or "closed"), pts(S, S.env.MerchantFrame) == MOVED, pts(S, S.env.MerchantFrame))
		end
	end
end

-- Windows that are left alone.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.QuestFrame].fault.restricted = "secret"
		W.rawOf[W.env.MailFrame].fault.rect = "secret"
	end)
	local moved = {}
	for _, name in ipairs({ "TestFullscreen", "HelpFrame", "MinimapCluster", "TestForbidden", "QuestFrame", "MailFrame", "GossipFrame" }) do
		W.openWindow(name)
		click(W, SMALL, { 400, 750 }, W.env[name])
		if pts(W, W.env[name]) ~= HOME then
			moved[#moved + 1] = name
		end
	end
	check("left alone: a whole-screen panel, Help, a frame Edit Mode owns, a forbidden one, one with restricted anchors and one with a withheld rectangle are not dragged, and a plain window is",
		table.concat(moved, ",") == "GossipFrame", table.concat(moved, ","))
	check("left alone: and nothing raises, and nothing is read of the forbidden one", allClean(W), problems(W))
	check("left alone: status says why a window cannot be dragged, and says nothing of a name the movers refuse", has(W.status(), "Quest cannot be dragged: its anchors are restricted.")
		and has(W.status(), "Mail cannot be dragged: its size is not readable.") and not has(W.status(), "HelpFrame cannot") and not has(W.status(), "Help cannot"), W.status())
end

-- The handles and the wheel.
do
