	W.keys = { ctrl = true }
	W.wheel("Vendor", 1)
	check("wheel: Ctrl and scroll on the handle of a window changes the scale of its spot under Each window", entry(W, "MerchantFrame") ~= nil and near(entry(W, "MerchantFrame").scale, 1.05)
		and W.ns.Get("movers.windowSize") == 100, tostring(entry(W, "MerchantFrame") and entry(W, "MerchantFrame").scale))
	W.change("movers.sizeScope", "Every window together")
	W.wheel("Vendor", 1)
	check("wheel: and the size of every window under Every window together", W.ns.Get("movers.windowSize") == 105 and near(entry(W, "MerchantFrame").scale, 1.05) and allClean(W), problems(W))
