-- A failure stays in its part.
do
	local W = windowWorld()
	W.change("movers.dragKey", "Shift")
	W.env.IsShiftKeyDown = function() error("boom", 0) end
	for _, name in ipairs({ "CharacterFrame", "FriendsFrame", "QuestFrame" }) do
		W.openWindow(name)
		pull(W, name, { 200, 950 }, { 500, 750 }, true)
	end
	W.openWindow("MailFrame")
	check("failure: three windows whose press raises stop the part of the module that drags windows, with a line for status, and the title bars are hidden", W.ns.IsStopped("movers") == false
		and has(W.status(), "Movers: window titles stopped.") and not W.rawOf[gripOf(W, "CharacterFrame")].shown, W.status())
	W.env.IsShiftKeyDown = nil
	W.slash("move")
	check("failure: the handles open and the part is not started again by a press", #W.shownHandles() > 0 and pts(W, W.env.CharacterFrame) == HOME, table.concat(W.shownHandles(), ","))
end

-- The words on screen.
do
	local W = windowWorld(function(W)
		W.rawOf[W.env.QuestFrame].fault.restricted = "secret"
	end)
	W.openWindow("QuestFrame")
	W.openWindow("MerchantFrame")
	W.change("movers.dragFrom", TITLE)
	click(W, BODY, { 400, 500 }, W.env.MerchantFrame)
	local texts = { W.slash("move reset windows"), "This window cannot be moved in combat.", "This window cannot be sized in combat.", "Some windows go back after combat.",
		"/flatui move reset windows - put every window back to its default place and size", "No handle is ticked. Tick the box on each handle, then press Centre ticked.",
		"Nothing was centred: the ticked handles are hidden or placed by the game.", "1 handle centred.", "2 handles centred.", "Click the button on a handle to centre it.",
		"Alt and click a handle to centre it.", "Click the button on a handle, or Alt and click it, to centre it.", "Tick the box on each handle, then press Centre ticked." }
	for line in (W.status() .. "\n"):gmatch("([^\n]*)\n") do
		for _, mark in ipairs({ "cannot be dragged", "No mouse press", "Last click", "Window levels", "set its size again" }) do
			if has(line, mark) then
				texts[#texts + 1] = line
			end
		end
	end
	local page
	for _, p in ipairs(W.ns.PAGES) do
		if p.key == "movers" then
			page = p
		end
	end
	local from
	for index, item in ipairs(page) do
		if item.section == "Centre" then
			from = index
		end
	end
	for index = from or 1, #page do
		local item = page[index]
		texts[#texts + 1] = item.section or item.label
		texts[#texts + 1] = item.tip
		texts[#texts + 1] = item.none
		for _, choice in ipairs(item.choices or {}) do
			texts[#texts + 1] = choice[2]
		end
	end
	for _, line in ipairs(W.ns.WindowResetLines()) do
		texts[#texts + 1] = line[2]
	end
	local BANNED = { "carries", "sits", "lives in", "lands", "runs through", "ensure", "simply", "easily", "leverage", "robust", "seamless", "delve", "flatui", "flat ui", "addon", "this build",
		"the system" }
	-- Words that keep a capital inside a sentence: the keys, the names of the options and the labels of the windows.
	local KEEP = { Shift = true, Alt = true, Ctrl = true, Every = true, Character = true, Vendor = true, Quest = true, Bag = true, Window = true, Movers = true, Centre = true }
	local bad = {}
	for _, text in ipairs(texts) do
		if type(text) == "string" and not text:find("^/flatui") then
			local low = text:lower()
			for _, word in ipairs(BANNED) do
				if low:find(word, 1, true) then
					bad[#bad + 1] = word .. " in " .. text:sub(1, 40)
				end
			end
			if text:find("[" .. string.char(128) .. "-" .. string.char(255) .. "]") then
				bad[#bad + 1] = "non-ASCII in " .. text:sub(1, 40)
			end
			local starts = true
			for word in text:gmatch("%S+") do
				local plain = word:gsub("[%p]", "")
				if not starts and plain:find("^%u%l") and not KEEP[plain] then
					bad[#bad + 1] = "capital " .. plain .. " in " .. text:sub(1, 40)
				end
				starts = word:find("[.:;]$") ~= nil
			end
		end
	end
	check("copy: every label, tip, choice, chat line and status line is in sentence case and free of the banned words", #bad == 0, table.concat(bad, "; "))
end

end
-- The Map & Quest Log window (WorldMapFrame): a window of the movers while it is small, the game's while it fills the screen and while the gamepad
-- interface is on. The world builds the map as the client does (Blizzard_WorldMap.xml, Blizzard_MapCanvas.xml, SharedUIPanelTemplates.xml,
-- QuestMapFrame.xml) and runs the game's own steps that size and place it as the game's: Minimize, Maximize and UpdateMaximizedSize
-- (Blizzard_WorldMap.lua), SetQuestLogPanelShown (QuestLogOwnerMixin.lua), the pass of the panel manager, MaximizeUIPanel and RestoreUIPanelArea
-- (UIParentPanelManager.lua). The values of the checks are in one table.
local function mapWindow(K)
local windowWorld, gripOf, cornerOf, pull, HOME = K.windowWorld, K.gripOf, K.cornerOf, K.pull, K.HOME
local entry, pts, allClean, problems, outText, opt = K.entry, K.pts, K.allClean, K.problems, K.outText, suiteKit.opt
local V = { MAP = "WorldMapFrame", FROM = "Anywhere on the window", TITLE = "Title bar", MOVED = "TOPLEFT>UIParent:TOPLEFT 316,-366 @1",
	FULL = "TOP>UIParent:TOP 0,0 @1", FILLS = "Map & Quest Log cannot be dragged: it fills the screen.",
	GAMEPAD = "Map & Quest Log cannot be dragged: the gamepad interface is on.", NOCOMBAT = "This window cannot be moved in combat.",
	SPOT = { point = "TOPLEFT", x = 316, y = -366, kind = "window" }, SPOT120 = { point = "TOPLEFT", x = 316, y = -366, scale = 1.2, kind = "window" },
	RESET = "Back to default when the window closes" }

-- The map before login: hidden, in the small size with the quest log pane, at the place of the panel manager's left slot.
local function mapWorld(prep, wopts)
	return windowWorld(function(W)
		local env, ui, registry = W.env, W.env.UIParent, W.registry
		-- A Lua method of Blizzard's: only the game may call it.
		local function game(name)
			return function()
				if W.inBlizzard == 0 then
					bad(W, "the addon called the Blizzard method " .. name)
				end
			end
		end
		local function part(name, parent, spec)
			spec.parent = parent
			return W.bframe(name, spec)
		end
		local map, mraw = W.bframe(V.MAP, { point = { "TOPLEFT", ui, "TOPLEFT", 16, -116 }, width = 1035, height = 534, hidden = true,
			fields = { isMaximized = false, mouse = true } })
		env.UIPanelWindows[V.MAP] = { area = "left", pushable = 0, xoffset = 0, yoffset = 0, whileDead = 1, minYOffset = 0, maximizePoint = "TOP", allowOtherPanels = 1 }
		-- The border covers the window in the strata above it; its children lie at the levels of the template, and it takes the mouse wheel only.
		local border, braw = part(nil, map, { point = { "TOPLEFT", map, "TOPLEFT", 0, 0 }, width = 1035, height = 534, fields = { strata = "HIGH" } })
		W.blizzard(function() braw.SetPoint(border, "BOTTOMRIGHT", map, "BOTTOMRIGHT", 0, 0) end)
		part(nil, border, { point = { "TOPLEFT", border, "TOPLEFT", 0, 0 }, width = 64, height = 64, fields = { level = 400, strata = "HIGH" } })
		part(nil, border, { point = { "TOPLEFT", border, "TOPLEFT", 0, 0 }, width = 100, height = 100, fields = { level = 500, strata = "HIGH" } })
		part(nil, border, { point = { "TOP", border, "TOP", 0, 0 }, width = 300, height = 22, fields = { level = 510, strata = "HIGH" } })
		part(nil, border, { point = { "TOPLEFT", border, "TOPLEFT", 0, 0 }, width = 20, height = 20, hidden = true, fields = { level = 515, strata = "HIGH" } })
		local close = part("TestMapClose", border, { point = { "TOPRIGHT", border, "TOPRIGHT", 5, 5 }, width = 24, height = 24,
			fields = { objectType = "Button", mouse = true, strata = "HIGH", level = 510 } })
		local maxmin = part(nil, border, { point = { "RIGHT", close, "LEFT", -1, 0 }, width = 24, height = 24, fields = { level = 510, strata = "HIGH" } })
		local maximize = part("TestMapMaximize", maxmin, { point = { "CENTER", maxmin, "CENTER", 0, 0 }, width = 24, height = 24,
			fields = { objectType = "Button", mouse = true, strata = "HIGH", level = 511 } })
		-- The black backdrop of the full-size map, over the whole screen at the lowest strata.
		local blackout, bkraw = part(nil, map, { point = { "TOPLEFT", ui, "TOPLEFT", 0, 0 }, width = 100, height = 100, hidden = true,
			fields = { strata = "LOW", mouse = true } })
		W.blizzard(function() bkraw.SetPoint(blackout, "BOTTOMRIGHT", ui, "BOTTOMRIGHT", 0, 0) end)
		-- The map itself: a scroll frame with mouse scripts, from the title strip to the bottom, and the button that shows the quest log.
		local scroll, sraw = part(nil, map, { point = { "TOPLEFT", map, "TOPLEFT", 2, -67 }, width = 100, height = 100,
			fields = { objectType = "ScrollFrame", mouse = true } })
		W.blizzard(function() sraw.SetPoint(scroll, "BOTTOMRIGHT", map, "BOTTOMRIGHT", -3, 2) end)
		sraw.scripts.OnMouseDown, sraw.scripts.OnMouseUp = function() end, function() end
		local toggle, traw = part("TestMapLogButton", map, { point = { "BOTTOMRIGHT", scroll, "BOTTOMRIGHT", -2, 1 }, width = 32, height = 32,
			fields = { objectType = "Button", mouse = true } })
		-- The quest log pane: a child of the map in the strata of the border, with the lower button of its scroll bar inside.
		local quest, qraw = part("QuestMapFrame", map, { point = { "TOPRIGHT", map, "TOPRIGHT", -3, -25 }, width = 330, height = 100, hidden = true,
			fields = { mouse = true, strata = "HIGH" } })
		W.blizzard(function() qraw.SetPoint(quest, "BOTTOMRIGHT", map, "BOTTOMRIGHT", -3, 3) end)
		local lower = part("TestMapScrollDown", quest, { point = { "BOTTOMRIGHT", map, "BOTTOMRIGHT", -9, 2 }, width = 8, height = 12,
			fields = { objectType = "Button", mouse = true, strata = "HIGH" } })
		mraw.BorderFrame, mraw.BlackoutFrame, mraw.ScrollContainer, mraw.QuestLog = border, blackout, scroll, quest
		for _, name in ipairs({ "IsMaximized", "Minimize", "Maximize", "SetDisplayState", "SetQuestLogPanelShown", "UpdateMaximizedSize" }) do
			mraw[name] = game(name)
		end
		W.map = { frame = map, raw = mraw, border = border, scroll = scroll, quest = quest, toggle = toggle, lower = lower, blackout = blackout, close = close, maximize = maximize }
		local function setLog(shown)
			mraw.width = shown and 1035 or 702
			qraw.shown, traw.shown = shown, not shown
			sraw.points[2] = { "BOTTOMRIGHT", map, "BOTTOMRIGHT", shown and -336 or -3, 2 }
		end
		-- The panel manager places the map in its left slot, divided by its scale (UpdateUIPanelPositions); it places nothing at full size.
		W.mapSlot = "left"
		env.UpdateUIPanelPositions = function()
			W.blizzard(function()
				if W.mapSlot == "left" and mraw.shown then
					mraw.points = { { "TOPLEFT", ui, "TOPLEFT", 16 / mraw.scale, -116 / mraw.scale } }
				end
			end)
		end
		local function pass()
			env.UpdateUIPanelPositions(map)
		end
		function W.mapLog(shown)
			W.blizzard(function() setLog(shown) end)
			pass()
		end
		-- ShowUIPanel: the map is shown and placed, and the panel manager says so. At full size the display state is Maximize.
		function W.mapOpen(log, full)
			W.blizzard(function()
				setLog(log and not full)
				W.mapSlot = "left"
				mraw.shown = true
			end)
			pass()
			if full then
				W.mapMaximize()
			end
			registry:TriggerEvent("UIParentPanelManager.ShowUIPanel", map, false)
		end
		function W.mapClose()
			W.blizzard(function() mraw.shown = false end)
			registry:TriggerEvent("UIParentPanelManager.HideUIPanel", map, false)
		end
		-- Maximize: the flag, the event, UpdateMaximizedSize (the size of the screen, in the units of the map, and a pass), MaximizeUIPanel (the slot
		-- of the full screen, the point TOP at 0, 0) and the backdrop. The callbacks of addons run as addon code.
		function W.mapMaximize(probe)
			if qraw.shown then
				W.mapLog(false)
			end
			W.blizzard(function() mraw.isMaximized = true end)
			registry:TriggerEvent("WorldMapMaximized")
			if probe then probe("event") end
			W.blizzard(function()
				local screenWidth, screenHeight = W.height * 16 / 9 / W.uiInner.scale, W.height / W.uiInner.scale
				local wide = ((screenHeight - 67) * 702) / (534 - 67)
				local clamped = math.min(screenWidth - 30, wide)
				mraw.width, mraw.height = math.floor(clamped), math.floor(((screenHeight - 67) * (clamped / wide)) + 67)
				sraw.points[2] = { "BOTTOMRIGHT", map, "BOTTOMRIGHT", -3, 2 }
			end)
			pass()
			if probe then probe("size") end
			W.blizzard(function()
				W.mapSlot = "fullscreen"
				mraw.points = { { "TOP", ui, "TOP", 0, 0 } }
				bkraw.shown = true
			end)
			if probe then probe("full") end
		end
		-- Minimize: the flag, the event, the size, a pass while the map is still in the slot of the full screen, then RestoreUIPanelArea.
		function W.mapMinimize(probe)
			W.blizzard(function() mraw.isMaximized = false end)
			registry:TriggerEvent("WorldMapMinimized")
			if probe then probe("event") end
			W.blizzard(function() mraw.width, mraw.height = qraw.shown and 1035 or 702, 534 end)
			pass()
			if probe then probe("pass") end
			W.blizzard(function()
				bkraw.shown = false
				W.mapSlot = "left"
			end)
			pass()
			if probe then probe("restore") end
		end
		if not (wopts and wopts.noInput) then
			env.Enum = env.Enum or {}
			env.Enum.InputDeviceInterfaceType = { Mkb = 0, Gamepad = 1 }
			env.C_InputInterfaceStyle = { GetCurrentStyle = function() return W.inputStyle or 0 end }
		end
		W.seal()
		if prep then
			prep(W)
		end
	end, wopts)
end
local function click(W, from, to, leaf, hold)
	local frames = #W.eventFrames
	W.pressAt(from[1], from[2], "LeftButton", leaf)
	if not W.carrier and #W.eventFrames > frames then
		W.carrier = W.eventFrames[frames + 1]
	end
	W.cursor = to
	W.update(1 / 60)
	if not hold then
		W.releaseAt("LeftButton")
	end
end
local function scaleOf(W)
	return W.rawOf[W.env[V.MAP]].scale
end
-- The left and the top of the map, in the units of UIParent.
local function topLeft(W)
	local l, b, _, h = W.rectOf(W.env[V.MAP])
	return l, b + h
end
-- The player presses the left button two units in from the bottom right corner of the map and pulls t units out along the diagonal.
local function grow(W, t)
	local l, b, w = W.rectOf(W.env[V.MAP])
	local x, y = l + w - 2, b + 2
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + t, y - t }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
end
-- The game reports a press on the map, so the corner grips take no mouse of their own from then on.
local function heard(W)
	W.pressAt(100, 100, "LeftButton", W.env[V.MAP])
	W.releaseAt("LeftButton")
end

-- The title bar and the corner grip of the small map, and where they lie.
do
	local W = mapWorld()
	W.mapOpen(true)
	local map, grip, corner = W.env[V.MAP], gripOf(W, V.MAP), cornerOf(W, V.MAP)
	check("mapwin: the small map has a title bar and a corner grip, frames of the addon's that are children of the map", grip ~= nil and corner ~= nil
		and W.rawOf[grip].parent == map and W.rawOf[corner].parent == map and W.rawOf[grip].shown and W.rawOf[corner].shown and allClean(W), problems(W))
	local mr, gr, cr = W.rawOf[map], W.rawOf[grip], W.rawOf[corner]
	check("mapwin: the title bar lies in the strata of the map two levels above it; the corner grip lies in the strata of the border, one level above its highest child",
		gr.level == mr.level + 2 and (gr.strata or "MEDIUM") == "MEDIUM" and cr.strata == "HIGH" and cr.level == 516, tostring(gr.level) .. " " .. tostring(cr.strata) .. " " .. tostring(cr.level))
	local l, b, w = W.rectOf(map)
	local x, y = l + w - 2, b + 2
	local leaf = W.hitAt(x, y)
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + 157, y - 157 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	local tl, tt = topLeft(W)
	check("mapwin: before the game reports a press, the corner grip takes a press in its last 4 units over the quest log, and sizes the map with the top left fixed",
		leaf == corner and near(scaleOf(W), 1.2) and near(entry(W, V.MAP).scale, 1.2) and near(tl, 16, 1e-6) and near(tt, 964, 1e-6), g(scaleOf(W)))
end

-- A pull on the title bar.
do
	local W = mapWorld()
	W.mapOpen(false)
	pull(W, V.MAP, { 200, 950 }, { 500, 700 }, true)
	local e = entry(W, V.MAP)
	check("mapwin: a pull on the title bar moves the map with the cursor and saves a window spot with the point TOPLEFT", pts(W, W.env[V.MAP]) == V.MOVED and e and e.kind == "window"
		and e.point == "TOPLEFT" and near(e.x, 316) and near(e.y, -366) and W.line("Movers") == "Movers: on, 1 moved", pts(W, W.env[V.MAP]))
	check("mapwin: no violation", allClean(W), problems(W))
end

-- Drag from anywhere, and from the title bar.
do
	local W = mapWorld()
	W.mapOpen(true)
	local pane = W.hitAt(900, 700)
	click(W, { 900, 700 }, { 1000, 600 }, pane)
	check("mapwin: drag from anywhere: a press on an empty part of the quest log moves the map", pane == W.env.QuestMapFrame and pts(W, W.env[V.MAP]) == "TOPLEFT>UIParent:TOPLEFT 116,-216 @1"
		and entry(W, V.MAP) ~= nil, tostring(pane) .. " " .. pts(W, W.env[V.MAP]))
	W.slash("move reset windows")
	click(W, { 300, 700 }, { 400, 600 }, W.hitAt(300, 700))
	check("mapwin: drag from anywhere: a press on the map itself moves nothing, and status says on a control", W.hitAt(300, 700) == W.map.scroll and pts(W, W.env[V.MAP]) == HOME
		and entry(W, V.MAP) == nil and has(W.status(), "Last click on Map & Quest Log started no drag: on a control (OnMouseDown)."), W.status())
	check("mapwin: and status gives the levels of the map, its title bar and its corner grip", has(W.status(), "Window levels: Map & Quest Log 2, title bar 4, corner 516"), W.status())
	local T = mapWorld()
	T.mapOpen(true)
	T.change("movers.dragFrom", V.TITLE)
	click(T, { 900, 700 }, { 1000, 600 }, T.hitAt(900, 700))
	check("mapwin: drag from the title bar: a press on the quest log moves nothing, and status says outside the title bar", pts(T, T.env[V.MAP]) == HOME and entry(T, V.MAP) == nil
		and has(T.status(), "Last click on Map & Quest Log started no drag: outside the title bar."), T.status())
	pull(T, V.MAP, { 200, 950 }, { 500, 700 }, true)
	check("mapwin: and the title bar drags it", pts(T, T.env[V.MAP]) == V.MOVED, pts(T, T.env[V.MAP]))
end

-- The corner with the quest log shown: the empty corner sizes the map, the lower button of the scroll bar keeps its click.
do
	local W = mapWorld()
	W.mapOpen(true)
	heard(W)
	local x, y = 1045, 436
	local leaf = W.hitAt(x, y)
	W.pressOn(x, y, "LeftButton")
	W.cursor = { x + 157, y - 157 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	local tl, tt = topLeft(W)
	check("mapwin: with the quest log shown a press on the empty corner sizes the map from 60% to 150% with the top left fixed", leaf == W.map.quest and near(scaleOf(W), 1.2)
		and near(tl, 16, 1e-6) and near(tt, 964, 1e-6), g(scaleOf(W)))
	local S = mapWorld()
	S.mapOpen(true)
	heard(S)
	local button = S.hitAt(1038, 438)
	S.pressOn(1038, 438, "LeftButton")
	S.cursor = { 1038 + 157, 438 - 157 }
	S.update(1 / 60)
	S.releaseAt("LeftButton")
	check("mapwin: the lower button of the scroll bar keeps its click, and status names it", button == S.map.lower and near(scaleOf(S), 1) and entry(S, V.MAP) == nil
		and has(S.status(), "Last click on Map & Quest Log started no drag: on a control (TestMapScrollDown)."), S.status())
	grow(S, 1000)
	check("mapwin: the size stops at 150%", near(scaleOf(S), 1.5), g(scaleOf(S)))
	grow(S, -1000)
	check("mapwin: and at 60%", near(scaleOf(S), 0.6), g(scaleOf(S)))
end

-- The corner with the quest log hidden: the button that shows it keeps its click, the rim beside it sizes the map.
do
	local W = mapWorld()
	W.mapOpen(false)
	heard(W)
	local button = W.hitAt(700, 440)
	W.pressOn(700, 440, "LeftButton")
	W.cursor = { 823, 317 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("mapwin: with the quest log hidden the quest log button keeps its click", button == W.map.toggle and near(scaleOf(W), 1) and entry(W, V.MAP) == nil
		and has(W.status(), "started no drag: on a control (TestMapLogButton)."), W.status())
	local rim = W.hitAt(716, 432)
	grow(W, 123.6)
	local tl, tt = topLeft(W)
	check("mapwin: a press on the window's rim in the corner sizes the map", rim == W.env[V.MAP] and near(scaleOf(W), 1.2) and near(tl, 16, 1e-6) and near(tt, 964, 1e-6), g(scaleOf(W)))
	local l, b, w = W.rectOf(W.env[V.MAP])
	W.pressOn(l + w - 2, b + 2, "RightButton")
	W.releaseAt("RightButton")
	check("mapwin: a right click on the corner gives 100%, and the spot stays", near(scaleOf(W), 1) and entry(W, V.MAP) ~= nil and entry(W, V.MAP).scale == nil, g(scaleOf(W)))
	pull(W, V.MAP, { 200, 950 }, { 500, 700 }, true)
	local grip = gripOf(W, V.MAP)
	local gl, gb = W.rectOf(grip)
	W.pressAt(gl + 50, gb + 10, "RightButton", grip)
	W.releaseAt("RightButton")
	check("mapwin: a right click on the title bar gives back the game's slot and scale", pts(W, W.env[V.MAP]) == HOME and entry(W, V.MAP) == nil and allClean(W), pts(W, W.env[V.MAP]))
end

-- The maximise and close buttons of the border lie over the end of the title bar, one level above the border's strata: they keep their clicks.
do
	local W = mapWorld()
	W.mapOpen(false)
	local told = {}
	for index, spot in ipairs({ { 680, 955, "TestMapMaximize" }, { 710, 955, "TestMapClose" } }) do
		local leaf = W.hitAt(spot[1], spot[2])
		click(W, { spot[1], spot[2] }, { spot[1] + 200, spot[2] - 200 }, leaf)
		told[index] = leaf == W.env[spot[3]] and has(W.status(), "started no drag: on a control (" .. spot[3] .. ").")
	end
	check("mapwin: a press on the maximise button or on the close button starts no drag, and status names the button", told[1] and told[2] and pts(W, W.env[V.MAP]) == HOME
		and entry(W, V.MAP) == nil and allClean(W), tostring(told[1]) .. " " .. tostring(told[2]) .. " " .. pts(W, W.env[V.MAP]))
end

-- The quest log opened and closed.
do
	local W = mapWorld(nil, { saved = opt({}, { [V.MAP] = V.SPOT120 }) })
	W.mapOpen(false)
	local l, b, w, h = W.rectOf(W.env[V.MAP])
	check("mapwin: the saved place and size apply when the map opens", near(l, 316, 1e-6) and near(b + h, 714, 1e-6) and near(w, 842.4, 1e-6) and near(scaleOf(W), 1.2), g(l) .. " " .. g(w))
	W.mapLog(true)
	local l2, b2, w2, h2 = W.rectOf(W.env[V.MAP])
	local cl, _, cw = W.rectOf(cornerOf(W, V.MAP))
	check("mapwin: the quest log opened: the map keeps its saved top left and size, and the corner grip follows the right edge", near(l2, 316, 1e-6) and near(b2 + h2, 714, 1e-6)
		and near(w2, 1242, 1e-6) and near(scaleOf(W), 1.2) and near(cl + cw, l2 + w2, 1e-6), g(l2) .. " " .. g(w2))
	W.mapLog(false)
	local l3, b3, w3, h3 = W.rectOf(W.env[V.MAP])
	local cl3, _, cw3 = W.rectOf(cornerOf(W, V.MAP))
	check("mapwin: and closed again", near(l3, 316, 1e-6) and near(b3 + h3, 714, 1e-6) and near(w3, 842.4, 1e-6) and near(cl3 + cw3, l3 + w3, 1e-6), g(l3) .. " " .. g(w3))
end

-- The game sets the scale of every open panel again when its UI scale changes (FrameUtil.UpdateScaleForFitSpecific, from the panel manager's own method and
-- not the global pass): the half-second check puts the chosen size back, and the top left with it.
do
	local W = mapWorld(nil, { saved = opt({}, { [V.MAP] = V.SPOT120 }) })
	W.mapOpen(false)
	W.fit(V.MAP, 1)
	local was = scaleOf(W)
	W.run(1, 0.5)
	local tl, tt = topLeft(W)
	check("mapwin: the game sets the scale again: the half-second check puts the chosen size and the top left back, and says nothing", near(was, 1) and near(scaleOf(W), 1.2)
		and near(tl, 316, 1e-6) and near(tt, 714, 1e-6) and not has(W.status(), "set its size again") and allClean(W), g(was) .. " " .. g(scaleOf(W)) .. " " .. g(tl) .. "," .. g(tt))
end

-- Full size.
do
	local W = mapWorld(nil, { saved = opt({}, { [V.MAP] = V.SPOT120 }) })
	W.mapOpen(false)
	local grip, corner = gripOf(W, V.MAP), cornerOf(W, V.MAP)
	local seen = {}
	W.mapMaximize(function(step)
		seen[step] = { scale = scaleOf(W), grips = W.rawOf[grip].shown or W.rawOf[corner].shown }
	end)
	check("mapwin: full size: the grips are hidden, the scale is 1, the map is at TOP>UIParent:TOP 0,0, and the spot stays in the profile", not W.rawOf[grip].shown and not W.rawOf[corner].shown
		and near(scaleOf(W), 1) and pts(W, W.env[V.MAP]) == V.FULL and entry(W, V.MAP) ~= nil and near(entry(W, V.MAP).scale, 1.2), pts(W, W.env[V.MAP]))
	check("mapwin: full size: the map is told before the game sizes it, so the scale is the game's when the size is set", seen.event and seen.event.scale == 1 and not seen.event.grips
		and seen.size.scale == 1, tostring(seen.event and seen.event.scale))
	local l, b, w, h = W.rectOf(W.env[V.MAP])
	check("mapwin: and it fills the screen the game sized it for", near(w, 1522, 1e-6) and near(h, 1080, 1e-6) and near(b, 0, 1e-6) and near(l, 199, 1e-6), g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
	W.run(6, 0.5)
	check("mapwin: full size: twelve half-second checks correct nothing, count no size written again and stop nothing", pts(W, W.env[V.MAP]) == V.FULL and near(scaleOf(W), 1)
		and not has(W.status(), "again and again") and not has(W.status(), "set its size again") and allClean(W), W.status())
	check("mapwin: full size: /flatui status says the map fills the screen", has(W.status(), V.FILLS), W.status())
	W.mapClose()
	check("mapwin: and once the map is closed it does not", not has(W.status(), "cannot be dragged"), W.status())
	-- Back to small.
	W.mapOpen(false, true)
	local steps = {}
	W.mapMinimize(function(step)
		local tl, tt = topLeft(W)
		steps[step] = near(tl, 316, 1e-6) and near(tt, 714, 1e-6) and near(scaleOf(W), 1.2) and W.rawOf[grip].shown and W.rawOf[corner].shown
	end)
	local _, _, mw = W.rectOf(W.env[V.MAP])
	check("mapwin: back to small: the saved place and size are on when the game says so, after its first pass and after its restore pass, and the grips are shown", steps.event and steps.pass
		and steps.restore and near(mw, 842.4, 1e-6) and not has(W.status(), "cannot be dragged"), tostring(steps.event) .. tostring(steps.pass) .. tostring(steps.restore))
end

-- Full size: a press on the title strip, on the corner or on the backdrop starts nothing and saves nothing.
do
	local W = mapWorld(nil, { saved = opt({}, { [V.MAP] = V.SPOT120 }) })
	W.mapOpen(false)
	W.mapMaximize()
	local was = entry(W, V.MAP).x .. "," .. entry(W, V.MAP).y .. "," .. entry(W, V.MAP).scale
	local l, b, w, h = W.rectOf(W.env[V.MAP])
	local rim = W.hitAt(l + w - 2, b + 2)
	W.pressOn(l + w - 2, b + 2, "LeftButton")
	W.cursor = { l + w + 100, b - 100 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	local strip = W.hitAt(500, b + h - 10)
	click(W, { 500, b + h - 10 }, { 700, 500 }, strip)
	local backdrop = W.hitAt(50, 500)
	click(W, { 50, 500 }, { 300, 300 }, backdrop)
	check("mapwin: full size: a press on the corner, on the map's title strip or on the black backdrop starts no drag and saves nothing", rim == W.env[V.MAP] and strip == W.env[V.MAP]
		and backdrop == W.map.blackout and pts(W, W.env[V.MAP]) == V.FULL and near(scaleOf(W), 1) and entry(W, V.MAP).x .. "," .. entry(W, V.MAP).y .. "," .. entry(W, V.MAP).scale == was
		and not has(W.status(), "Last click") and allClean(W), pts(W, W.env[V.MAP]))
end

-- A drag under way when the map goes to full size.
do
	local W = mapWorld()
	W.mapOpen(false)
	pull(W, V.MAP, { 200, 950 }, { 500, 700 }, false)
	W.mapMaximize()
	W.update(1 / 60)
	local e = entry(W, V.MAP)
	check("mapwin: a drag under way when the map goes to full size ends and saves the last small place", e and near(e.x, 316) and near(e.y, -366) and e.point == "TOPLEFT" and W.carrier.scripts.OnUpdate == nil
		and pts(W, W.env[V.MAP]) == V.FULL, pts(W, W.env[V.MAP]))
end

-- A size drag under way with Window dragging off when the map goes to full size: no title bar is hidden then, so the check on each step of the drag ends it.
do
	local W = mapWorld(nil, { saved = opt({ ["movers.titles"] = false }) })
	W.mapOpen(false)
	heard(W)
	local l, b, w = W.rectOf(W.env[V.MAP])
	local x, y = l + w - 2, b + 2
	click(W, { x, y }, { x + 123.6, y - 123.6 }, W.hitAt(x, y), true)
	local grown, going = scaleOf(W), W.carrier and W.carrier.scripts.OnUpdate ~= nil
	W.mapMaximize()
	W.update(1 / 60)
	local ended = W.carrier.scripts.OnUpdate == nil
	W.releaseAt("LeftButton")
	local e = entry(W, V.MAP)
	check("mapwin: a size drag under way with Window dragging off when the map goes to full size ends, saves the last small size, and the map has the game's scale",
		not W.rawOf[gripOf(W, V.MAP)].shown and near(grown, 1.2) and going and ended and e and near(e.scale, 1.2) and near(e.x, 16) and near(e.y, -116) and near(scaleOf(W), 1)
		and pts(W, W.env[V.MAP]) == V.FULL and allClean(W), g(grown) .. " " .. tostring(going) .. tostring(ended) .. " " .. pts(W, W.env[V.MAP]))
end

-- The map opened at full size first, then made small.
do
	local W = mapWorld(function(W)
		local raw, ui = W.map.raw, W.env.UIParent
		raw.isMaximized, raw.shown, raw.width, raw.height, raw.points = true, true, 1522, 1080, { { "TOP", ui, "TOP", 0, 0 } }
		W.rawOf[W.map.blackout].shown = true
		W.mapSlot = "fullscreen"
	end, { saved = opt({}, { [V.MAP] = V.SPOT120 }) })
	W.mapOpen(false, true)
	check("mapwin: opened at full size first: no grips are made, and status says the map fills the screen", gripOf(W, V.MAP) == nil and cornerOf(W, V.MAP) == nil and pts(W, W.env[V.MAP]) == V.FULL
		and has(W.status(), V.FILLS), W.status())
	W.mapMinimize()
	local tl, tt = topLeft(W)
	check("mapwin: and made small: the spot applies and the grips are made", near(tl, 316, 1e-6) and near(tt, 714, 1e-6) and near(scaleOf(W), 1.2) and gripOf(W, V.MAP) ~= nil and cornerOf(W, V.MAP) ~= nil
		and not has(W.status(), "cannot be dragged"), pts(W, W.env[V.MAP]))
	local grip = gripOf(W, V.MAP)
	local gl, gb = W.rectOf(grip)
	W.pressAt(gl + 50, gb + 10, "RightButton", grip)
	W.releaseAt("RightButton")
	local rl, rt = topLeft(W)
	check("mapwin: a right click on the title bar leaves the map where it is, never at the point of full size, and its top left corner stays where it was at the size of the game",
		entry(W, V.MAP) == nil and not has(pts(W, W.env[V.MAP]), "TOP>UIParent:TOP 0,0") and near(scaleOf(W), 1) and near(rl, tl, 1e-6) and near(rt, tt, 1e-6),
		pts(W, W.env[V.MAP]) .. " " .. g(rl) .. "," .. g(rt))
	W.env.UpdateUIPanelPositions(W.env[V.MAP])
	check("mapwin: and the game's next pass puts it in its slot", pts(W, W.env[V.MAP]) == HOME, pts(W, W.env[V.MAP]))
end

