-- A full-size flag the client withholds or fails to answer.
do
	local forms = {
		{ "withheld", function(W) W.map.raw.isMaximized = SECRET end },
		{ "raising", function(W)
			W.map.raw.isMaximized = nil
			setmetatable(W.map.raw, { __index = function(_, key)
				if key == "isMaximized" then
					error("isMaximized failed", 0)
				end
			end })
		end },
	}
	local wrong = {}
	for _, form in ipairs(forms) do
		local W = mapWorld(form[2])
		W.mapOpen(false)
		click(W, { 200, 700 }, { 400, 500 }, W.hitAt(200, 700))
		pull(W, V.MAP, { 200, 950 }, { 500, 700 }, true)
		if gripOf(W, V.MAP) ~= nil or cornerOf(W, V.MAP) ~= nil or pts(W, W.env[V.MAP]) ~= HOME or entry(W, V.MAP) ~= nil or not has(W.status(), V.FILLS) or not allClean(W) then
			wrong[#wrong + 1] = form[1]
		end
	end
	check("mapwin: an isMaximized the client withholds, or a read that raises, counts as full size: no grips, no drag, and nothing raises", #wrong == 0, table.concat(wrong, " "))
	local W = mapWorld(function(W) W.map.raw.isMaximized = nil end)
	W.mapOpen(false)
	check("mapwin: a map the game has not yet told its state is small", gripOf(W, V.MAP) ~= nil and cornerOf(W, V.MAP) ~= nil and not has(W.status(), "cannot be dragged"), W.status())
end

-- A border that is missing, withheld, forbidden or has no strata to read: the corner grip stays in the strata of the map and nothing raises.
do
	local forms = {
		{ "missing", function(W) W.map.raw.BorderFrame = nil end, true },
		{ "withheld", function(W) W.map.raw.BorderFrame = SECRET end, true },
		{ "forbidden", function(W) W.rawOf[W.map.border].forbidden = true end, true },
		{ "strata withheld", function(W) W.rawOf[W.map.border].GetFrameStrata = function() return SECRET end end },
		{ "strata raising", function(W) W.rawOf[W.map.border].GetFrameStrata = function() error("GetFrameStrata failed", 0) end end },
	}
	local wrong = {}
	for _, form in ipairs(forms) do
		local W = mapWorld(form[2])
		W.mapOpen(true)
		local corner = cornerOf(W, V.MAP)
		local raw = corner and W.rawOf[corner]
		-- With no layer to read, the corner lies one level above the highest child of the map, far below the 516 of the border's children.
		if not raw or (raw.strata or "MEDIUM") ~= "MEDIUM" or (form[3] and (raw.level or 0) >= 100) or not raw.shown or not allClean(W) then
			wrong[#wrong + 1] = form[1] .. ": " .. problems(W)
		end
		heard(W)
		grow(W, 123.6)
		if not allClean(W) then
			wrong[#wrong + 1] = form[1] .. " after a press: " .. problems(W)
		end
	end
	check("mapwin: a border that is missing, withheld, forbidden or has no readable strata: the corner grip is in the strata of the map, is not raised, and nothing raises", #wrong == 0, table.concat(wrong, " | "))
end

