local function titles()
local mwBefore, entry, pts = suiteKit.mwBefore, suiteKit.entry, suiteKit.pts
local allClean, problems, outText = suiteKit.allClean, suiteKit.problems, suiteKit.outText
local HOW = "Every frame can be moved here. Drag a blue box or a window's title. Ctrl and scroll changes size. Right-click puts it back."
local HOME = "TOPLEFT>UIParent:TOPLEFT 16,-116 @1"
-- The frames of the addon's that are children of a window: the title bar takes the mouse and is anchored at the top left, the corner grip is anchored at
-- the bottom right and is 18 units square (it takes the mouse only until the game reports a press).
local function frameAt(W, name, point)
	for _, f in ipairs(W.addonFrames) do
		local raw = W.rawOf[f]
		if raw.parent == W.env[name] and (raw.mouse or (raw.width == 18 and raw.height == 18)) and raw.points[1] and raw.points[1][1] == point then
			return f
		end
	end
end
local function gripOf(W, name)
	return frameAt(W, name, "TOPLEFT")
end
local function cornerOf(W, name)
	return frameAt(W, name, "BOTTOMRIGHT")
end
-- The player presses the left button on the title bar of a window, moves the cursor for one frame, and lets go when asked to. The first
-- press makes the frame that runs the drag, which is kept in W.carrier.
local function pull(W, name, from, to, release)
	local grip = gripOf(W, name)
	local frames = #W.eventFrames
	W.pressAt(from[1], from[2], "LeftButton", grip)
	if not W.carrier and #W.eventFrames > frames then
		W.carrier = W.eventFrames[frames + 1]
	end
	W.cursor = to
	W.update(1 / 60)
	if release then
		W.releaseAt("LeftButton")
	end
end
-- Windows of the panel manager that are not in the list of the movers, a window it gives the whole screen, one the movers refuse, one that
-- is forbidden, one Edit Mode owns, and the windows of the game that the list gained: bags, the game menu, the options and the legacy window.
local function windowWorld(prep, opts)
	return mwBefore(opts or {}, function(W)
		local ui = W.env.UIParent
		local function panel(name, width, height, spec, area)
			spec = spec or {}
			spec.point, spec.width, spec.height, spec.hidden = { "TOPLEFT", ui, "TOPLEFT", 16, -116 }, width, height, true
			W.bframe(name, spec)
			W.env.UIPanelWindows[name] = { area = area or "left" }
		end
		panel("TestWindow", 300, 200)
		panel("TestFullscreen", 300, 200, nil, "full")
		panel("HelpFrame", 300, 200)
		panel("TestForbidden", 300, 200, { forbidden = true })
		panel("LegacySystemFrame", 400, 300)
		panel("GameMenuFrame", 260, 300)
		panel("SettingsPanel", 920, 724)
		W.env.UIPanelWindows.MinimapCluster = { area = "left" }
		W.bframe("ContainerFrameCombinedBags", { point = { "BOTTOMRIGHT", ui, "BOTTOMRIGHT", 0, 100 }, width = 300, height = 100, hidden = true })
		W.rawOf[W.env.CharacterFrame].level = 7
		W.env.UpdateContainerFrameAnchors = function() end
		-- A window of the game takes the mouse, or a click on it would go through to the world.
		for name in pairs(W.env.UIPanelWindows) do
			if W.env[name] then
				W.rawOf[W.env[name]].mouse = true
			end
		end
		W.rawOf[W.env.ContainerFrame3].mouse = true
		W.rawOf[W.env.ContainerFrameCombinedBags].mouse = true
		if prep then
			prep(W)
		end
	end)
end

do
	local W = windowWorld()
	check("grips: a window that is closed has none", gripOf(W, "CharacterFrame") == nil and gripOf(W, "TestWindow") == nil)
	W.openWindow("CharacterFrame")
	local grip = gripOf(W, "CharacterFrame")
	local raw = grip and W.rawOf[grip]
	check("grips: an open window has one, a frame of the addon's that takes the mouse and cannot be moved", raw and raw.mouse and not raw.movable and not W.rawOf[W.env.CharacterFrame].movable)
	local l, b, w, h = W.rectOf(grip)
	check("grips: it covers the title from the left edge to short of the close button, 22 high", near(l, 16) and near(b, 942) and near(w, 310) and near(h, 22), g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
	check("grips: it lies two levels above the window, over what the game put in the title", raw.level == 9, raw.level)
	W.openWindow("CharacterFrame")
	local made = 0
	for _, f in ipairs(W.addonFrames) do
		made = made + (W.rawOf[f].parent == W.env.CharacterFrame and W.rawOf[f].mouse and 1 or 0)
	end
	check("grips: a window opened again keeps the two it has, a title bar and a corner grip", made == 2 and cornerOf(W, "CharacterFrame") ~= nil, made)
	pull(W, "CharacterFrame", { 200, 900 }, { 203, 899 }, true)
	check("drag: a click that moves the cursor less than four units moves nothing and saves nothing", entry(W, "CharacterFrame") == nil and pts(W, W.env.CharacterFrame) == HOME)
	pull(W, "CharacterFrame", { 200, 900 }, { 500, 700 }, false)
	check("drag: while the button is held the window follows the cursor and nothing is saved yet", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 316,-316 @1"
		and entry(W, "CharacterFrame") == nil, pts(W, W.env.CharacterFrame))
	W.cursor = { 600, 600 }
	W.update(1 / 60)
	check("drag: and goes on following it", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 416,-416 @1", pts(W, W.env.CharacterFrame))
	W.releaseAt("LeftButton")
	local e = entry(W, "CharacterFrame")
	check("drag: letting go saves the spot as that of a window", e and e.point == "TOPLEFT" and near(e.x, 416) and near(e.y, -416) and e.kind == "window", e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	W.cursor = { 900, 900 }
	W.update(1 / 60)
	check("drag: then the window stays, and nothing runs each frame for the drag", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 416,-416 @1" and W.carrier.scripts.OnUpdate == nil)
	check("drag: the module counts the window and keeps it in place", W.line("Movers") == "Movers: on, 1 moved" and #W.shownHandles() == 0, W.line("Movers"))
	W.closeWindow("CharacterFrame")
	W.openWindow("CharacterFrame")
	check("drag: the game places the window again when it opens, and it is put back at its spot", pts(W, W.env.CharacterFrame) == "TOPLEFT>UIParent:TOPLEFT 416,-416 @1", pts(W, W.env.CharacterFrame))
	W.pressAt(200, 900, "RightButton", grip)
	W.releaseAt("RightButton")
	check("right click: the window goes back to where the game has it and its spot is forgotten", pts(W, W.env.CharacterFrame) == HOME and entry(W, "CharacterFrame") == nil
		and W.line("Movers") == "Movers: on, 0 moved", pts(W, W.env.CharacterFrame))
	W.openWindow("TestWindow")
