	check("drag: a window of the panel manager that is not in the list is placed and saved under its name, as a window", e and e.kind == "window" and e.label == "TestWindow" and near(e.x, 216)
		and near(e.y, -216) and pts(W, W.env.TestWindow) == "TOPLEFT>UIParent:TOPLEFT 216,-216 @1", e and (g(e.x) .. "," .. g(e.y)))
	pull(W, "TestWindow", { 400, 800 }, { 600, 700 }, false)
