	check("drag: a window with a saved spot is not pulled back to it by the check while it is dragged", pts(W, W.env.TestWindow) == "TOPLEFT>UIParent:TOPLEFT 416,-316 @1", pts(W, W.env.TestWindow))
	W.releaseAt("LeftButton")
	local down = true
