do
-- Unit frames. The simulated client builds the frames the way Blizzard's XML does: protected unit buttons and bars,
-- fills drawn from an atlas under a mask, art that Blizzard only shows, hides and gives an atlas, and glows that
-- Blizzard colours. The game's own functions run inside W.blizzard and raise when the addon calls one.
local function ufWorld(opts)
	opts = opts or {}
	-- The checks written before Name room kept fixed rooms for the level and the PvP word: they run on Fixed space unless a check asks for opts.nameRoom = "fit".
	if opts.nameRoom ~= "fit" and (opts.saved == nil or type(opts.saved.options) == "table" or opts.saved.options == nil) then
		opts.saved = opts.saved or {}
		opts.saved.options = opts.saved.options or {}
		if opts.saved.options["unitframes.nameRoom"] == nil then
			opts.saved.options["unitframes.nameRoom"] = "fixed"
		end
	end
	local W = newWorld({ saved = opts.saved, combat = opts.combat, noGradient = opts.without and opts.without.SetGradient, fontReturn = opts.fontReturn })
	local env, B0, Rr = W.env, W.B, W.Rr
	-- A frame of the game is one of the children of its parent.
	local function B(parent, fields, more)
		local proxy, raw = B0(parent, fields, more)
		if parent ~= nil then
			local list = W.rawOf[parent].children
			list[#list + 1] = proxy
		end
		return proxy, raw
	end
	W.B = B
	W.uf = { threat = {}, power = {}, class = {}, icon = {}, highLevel = {}, reaction = {}, resting = false, fighting = false, tapped = {}, tint = {},
		health = {}, dead = {}, ghost = {}, offline = {}, debuff = {} }
	local U = W.uf
	-- Geometry and the calls of the name row and the corners. The client works out a rectangle from the anchors of a frame and of the frames
	-- it hangs from, in the units of the frame; U.without names calls this client lacks, U.refuseSlice a slice call it refuses.
	U.without, U.names, U.levels, U.levelColour = opts.without or {}, {}, {}, {}
	local FRAC = { TOPLEFT = { 0, 1 }, TOP = { 0.5, 1 }, TOPRIGHT = { 1, 1 }, LEFT = { 0, 0.5 }, CENTER = { 0.5, 0.5 }, RIGHT = { 1, 0.5 },
		BOTTOMLEFT = { 0, 0 }, BOTTOM = { 0.5, 0 }, BOTTOMRIGHT = { 1, 0 } }
	local function place(obj, depth)
		if obj == nil or depth > 60 then
			return nil
		end
		if obj == W.uiInner then
			return 0, 0, W.height * 16 / 9, W.height
		end
		-- U.hold: no rectangle until the next tick. A frame the addon placed or sized has none either until then (U.pendingOn).
		if obj.pending or U.hold then
			return nil
		end
		if obj.allPoints then
			return place(W.rawOf[obj.allPoints], depth + 1)
		end
		if #obj.points == 0 then
			return nil
		end
		local e = obj.GetEffectiveScale()
		local xs, ys = {}, {}
		for _, p in ipairs(obj.points) do
			local l, b, w, h = place(W.rawOf[p[2]], depth + 1)
			if not l then
				return nil
			end
			local at, mine = FRAC[p[3] or p[1]], FRAC[p[1]]
			xs[#xs + 1] = { mine[1], l + w * at[1] + (p[4] or 0) * e }
			ys[#ys + 1] = { mine[2], b + h * at[2] + (p[5] or 0) * e }
		end
		local function axis(list, size)
			local first, second = list[1], nil
			for i = 2, #list do
				if list[i][1] ~= first[1] then
					second = list[i]
					break
				end
			end
			if second then
				local span = (second[2] - first[2]) / (second[1] - first[1])
				return first[2] - first[1] * span, span
			end
			return first[2] - first[1] * size, size
		end
		local left, width = axis(xs, (obj.width or 0) * e)
		local bottom, height = axis(ys, (obj.height or 0) * e)
		-- U.zeroNoRect: a frame or region with no width or no height has no rectangle, and nothing anchored to it has one.
		if U.zeroNoRect and obj.kind ~= "FontString" and (width <= 0 or height <= 0) then
			return nil
		end
		return left, bottom, width, height
	end
	-- Left, bottom, width and height in the units of the frame or region, or nothing when it has no place.
	local function rectOf(raw, absolute)
		if U.rectFault == "error" then
			error("GetRect failed", 0)
		elseif U.rectFault == "secret" then
			return SECRET, SECRET, SECRET, SECRET
		end
		local fault = raw.fault.rect
		if fault == "error" then
			error("GetRect failed", 0)
		elseif fault == "secret" then
			return SECRET, SECRET, SECRET, SECRET
		end
		local l, b, w, h = place(raw, 0)
		if not l then
			return nil
		end
		if absolute then
			return l, b, w, h
		end
		local e = raw.GetEffectiveScale()
		return l / e, b / e, w / e, h / e
	end
	U.rect = rectOf
	-- The same rectangle in the units of the screen, to compare regions that have scales of their own.
	function U.abs(raw) return rectOf(raw, true) end
	-- The area of a texture that shows: its rectangle cut by the rectangle of each mask on it. A mask whose file did not load shows nothing.
	function U.area(tex)
		local l, b, w, h = rectOf(tex)
		if not l then
			return 0
		end
		for _, mask in ipairs(tex.maskList) do
			if mask.unloaded then
				return 0
			end
			local ml, mb, mw, mh = rectOf(mask)
			if not ml then
				return 0
			end
			local x1, y1 = math.max(l, ml), math.max(b, mb)
			local x2, y2 = math.min(l + w, ml + mw), math.min(b + h, mb + mh)
			if x2 <= x1 or y2 <= y1 then
				return 0
			end
			l, b, w, h = x1, y1, x2 - x1, y2 - y1
		end
		return w * h
	end
	-- Rectangles wait for the next tick while U.hold is set, and for a frame the addon placed while U.pendingOn is.
	U.hold, U.pendingOn, U.pendingList = false, false, {}
	-- A frame or region with no width or no height has no rectangle, and nothing anchored to it has one.
	U.zeroNoRect = true
	do
		local tick = W.tick
		function W.tick(...)
			if U.hold ~= "keep" then
				U.hold = false
			end
			for _, raw in ipairs(U.pendingList) do
				raw.pending = nil
			end
			U.pendingList = {}
			return tick(...)
		end
	end
	local function extendRegion(r)
		local getParent = r.GetParent
		function r.SetParent(_, parent) r.reparent = parent end
		function r.GetParent() return r.reparent or getParent() end
		function r.GetRect() return rectOf(r) end
		function r.GetLeft() return (rectOf(r)) end
		function r.IsRectValid() return rectOf(r) ~= nil end
		if r.kind == "FontString" then
			-- One alpha per region: SetAlpha writes it, and so does the fourth number of SetTextColor and SetVertexColor (1 when left out).
			-- GetAlpha and the fourth answer of GetTextColor and GetVertexColor read it.
			local setColour, getColour, setVertex, getVertex = r.SetTextColor, r.GetTextColor, r.SetVertexColor, r.GetVertexColor
			function r.SetTextColor(self, ...)
				setColour(self, ...)
				r.alpha = (select(4, ...)) or 1
			end
			function r.SetVertexColor(self, ...)
				setVertex(self, ...)
				r.alpha = (select(4, ...)) or 1
			end
			local function withAlpha(get)
				return function(...)
					local a, b, c, d = get(...)
					if isnum(d) then
						d = r.alpha
					end
					return a, b, c, d
				end
			end
			r.GetTextColor, r.GetVertexColor = withAlpha(getColour), withAlpha(getVertex)
			-- SetAlphaFromBoolean(value, alphaIfTrue, alphaIfFalse): the value may be withheld, and is then resolved with W.secretTruth.
			if not U.without.SetAlphaFromBoolean then
				function r.SetAlphaFromBoolean(_, value, yes, no)
					if type(value) ~= "boolean" and not rawequal(value, SECRET) then
						bad(W, "SetAlphaFromBoolean: a boolean is expected")
					end
					argn(W, "SetAlphaFromBoolean", yes, no)
					local pick = value
					if rawequal(value, SECRET) then
						pick = W.secretTruth == true
					end
					r.alpha = pick and yes or no
					r.fromBoolean = { secret = rawequal(value, SECRET), yes = yes, no = no }
				end
			end
			return
		end
		if not U.without.SetTextureSliceMargins then
			function r.SetTextureSliceMargins(_, ...)
				if U.refuseSlice then
					error("SetTextureSliceMargins failed", 0)
				end
				argn(W, "SetTextureSliceMargins", ...)
				r.slice = { ... }
			end
		end
		if not U.without.SetTextureSliceMode then
			function r.SetTextureSliceMode(_, mode)
				argn(W, "SetTextureSliceMode", mode)
				r.sliceMode = mode
			end
		end
		function r.ClearTextureSlice() r.slice, r.sliceMode = nil, nil end
		local setTexture = r.SetTexture
		function r.SetTexture(self, file, wrapH, wrapV)
			setTexture(self, file)
			r.wrap = { wrapH, wrapV }
			-- U.badTexture: the rounded files do not load, and a mask made from one clips everything it is on.
			r.unloaded = U.badTexture and type(file) == "string" and file:find("Round", 1, true) ~= nil or nil
		end
	end
	local function extendFrame(raw)
		raw.GetRect = function() return rectOf(raw) end
		raw.GetLeft = function() return (rectOf(raw)) end
		raw.IsRectValid = function() return rectOf(raw) ~= nil end
		for _, name in ipairs({ "SetPoint", "SetSize", "SetWidth", "SetHeight" }) do
			local original = raw[name]
			raw[name] = function(...)
				if name == "SetSize" and U.ignoreSize and raw.addonFrame then
					-- U.ignoreSize: a frame of the addon's that keeps no size and reads back 0.
					original(raw, 0, 0)
					return
				end
				original(...)
				if U.pendingOn and raw.addonFrame then
					raw.pending = true
					U.pendingList[#U.pendingList + 1] = raw
				end
			end
		end
		local size = raw.GetHeight
		raw.GetHeight = function()
			local _, _, _, h = rectOf(raw)
			return h or size()
		end
		raw.EnableMouse = function(_, v) raw.mouse = v end
		local texture, font, maskable = raw.CreateTexture, raw.CreateFontString, raw.CreateMaskTexture
		raw.CreateTexture = function(...)
			local t = texture(...)
			extendRegion(t)
			return t
		end
		raw.CreateFontString = function(...)
			local t = font(...)
			extendRegion(t)
			return t
		end
		if maskable then
			raw.CreateMaskTexture = function(...)
				local t = maskable(...)
				extendRegion(t)
				return t
			end
		end
	end
	-- A frame the addon makes can make masks, and every frame and region has a rectangle.
	local createFrame = env.CreateFrame
	-- A PlayerModel (FrameAPICharacterModelBaseDocumentation.lua, SimpleModelAPIDocumentation.lua): U.models lists the ones made, each keeps its calls in
	-- raw.mcalls and its unit in raw.unit. SetUnit raises while the sim says the identity is withheld (U.identity) or U.refuseUnit is set. Every frame answers
	-- GetEffectiveAlpha, and a region can be given another parent with SetParent.
	U.models = {}
	env.CreateFrame = function(kind, ...)
		local model = kind == "PlayerModel"
		local frame = createFrame(model and "Frame" or kind, ...)
		local raw = W.rawOf[frame]
		W.maskable(raw)
		raw.addonFrame = true
		extendFrame(raw)
		raw.GetEffectiveAlpha = function()
			local a, cur = 1, raw
			while cur do
				a = a * (cur.alpha or 1)
				cur = cur.parent and W.rawOf[cur.parent]
			end
			return a
		end
		if model then
			U.models[#U.models + 1] = raw
			raw.objectType, raw.mcalls, raw.shown, raw.model = "PlayerModel", {}, false, true
			local function call(name, ...)
				raw.mcalls[#raw.mcalls + 1] = { name, ... }
			end
			function raw.SetUnit(_, unit)
				call("SetUnit", unit)
				if type(unit) ~= "string" then
					bad(W, "SetUnit: a unit is expected")
				end
				if U.refuseUnit or U.identity == true or (type(U.identity) == "table" and U.identity[unit] == true) then
					error("SetUnit failed", 0)
				end
				raw.unit = unit
			end
			function raw.ClearModel() call("ClearModel") raw.unit = nil end
			for _, name in ipairs({ "SetPortraitZoom", "SetCamDistanceScale", "SetPosition", "SetRotation", "SetKeepModelOnHide", "SetDesaturation" }) do
				raw[name] = function(_, ...)
					if name == "SetRotation" then
						-- radians, then animate, a bool (FrameAPICharacterModelBaseDocumentation.lua:233-237)
						argn(W, name, (...))
						if select(2, ...) ~= nil and type((select(2, ...))) ~= "boolean" then
							bad(W, name .. ": argument 2 is not a bool")
						end
					else
						argn(W, name, ...)
					end
					call(name, ...)
					raw[name:sub(4)] = { ... }
				end
			end
			raw.SetKeepModelOnHide = function(_, v) call("SetKeepModelOnHide", v) raw.keep = v end
			local setAlpha = raw.SetAlpha
			raw.SetAlpha = function(self, ...) call("SetAlpha", ...) return setAlpha(self, ...) end
			raw.scripts = {}
			function raw.SetScript(_, which, fn)
				if which ~= "OnShow" or type(fn) ~= "function" then
					bad(W, "SetScript arguments")
				end
				raw.scripts[which] = fn
			end
			function raw.Show()
				local was = raw.shown
				raw.shown = true
				if not was and raw.scripts.OnShow then
					raw.scripts.OnShow(frame)
				end
			end
		end
		return frame
	end
	env.CreateColor = function(r, g, b, a)
		argn(W, "CreateColor", r, g, b)
		return setmetatable({ r = r, g = g, b = b, a = a or 1 }, COLOUR_MT)
	end
	env.QuestDifficultyColors = { impossible = { r = 1, g = 0.1, b = 0.1 } }
	env.UnitClass = function(unit) return "Warlock", "WARLOCK", 9 end
	env.RAID_CLASS_COLORS = { WARLOCK = setmetatable({ r = 0.58, g = 0.51, b = 0.79, a = 1 }, COLOUR_MT) }
	-- UnitName answers a first name and a surname; U.nameFault makes it withhold the name or raise. The game's way of showing a name
	-- (Camelot/NameUtil.lua:4-12, Mainline/UnitFrame.lua:153-167).
	U.surnames, U.regional, U.displaySurname = {}, false, true
	env.UnitName = function(unit)
		if U.nameFault == "error" then
			error("UnitName failed", 0)
		elseif U.nameFault == "secret" or U.secretName then
			return SECRET
		end
		return U.names[unit], U.surnames[unit]
	end
	env.UnitIsUnit = function(unit, other) return unit == other end
	env.RegionalUniqueNamesEnabled = function() return U.regional end
	env.C_PlayerInfo = { ShouldDisplaySurname = function() return U.displaySurname end }
	env.Constants = { CharacterNameSeparatorConsts = { CHARACTERNAME_SURNAME_SEPARATOR = "-" } }
	env.NameUtil = { GetUnitFirstName = function(unit) return (U.names[unit]) end }
	env.UnitEffectiveLevel = function(unit) return U.levels[unit] end
	-- The client says what the target and the focus are: U.class by the name of the frame ("normal", "elite", "rare", "rareelite", "worldboss", "minus"),
	-- and U.bossMob whether the unit is a boss mob. U.fault names a frame whose answers are withheld ("secret") or refused ("error"), and the same
	-- with "Boss" after the name only the boss answer and with "Class" only the classification. U.reads counts the calls.
	U.bossMob, U.fault, U.reads = {}, {}, { UnitClassification = 0, UnitIsBossMob = 0 }
	local FRAME_OF = { target = "TargetFrame", focus = "FocusFrame" }
	local function unitAnswer(name, answer)
		return function(unit)
			U.reads[name] = U.reads[name] + 1
			local frame = FRAME_OF[unit]
			local fault = frame and (U.fault[frame] or (name == "UnitIsBossMob" and U.fault[frame .. "Boss"]) or (name == "UnitClassification" and U.fault[frame .. "Class"]) or nil)
			if fault == "error" then
				error(name .. " failed", 0)
			elseif fault == "secret" then
				return SECRET
			end
			return answer(frame)
		end
	end
	env.UnitClassification = unitAnswer("UnitClassification", function(frame) return frame and U.class[frame] or "normal" end)
	env.UnitIsBossMob = unitAnswer("UnitIsBossMob", function(frame) return frame ~= nil and U.bossMob[frame] == true end)
	for name in pairs(opts.without or {}) do
		if name == "CreateColor" or name == "UnitClass" or name == "UnitClassification" or name == "UnitIsBossMob" then
			env[name] = nil
		end
	end

	local function blizz(name, fn)
		return FH.wrap(W, name, function(...)
			if W.inBlizzard == 0 or (W.inHook or 0) > 0 then
				bad(W, "the addon called the Blizzard function " .. name)
			end
			return fn(...)
		end)
	end
	local function put(parent, key, child)
		W.rawOf[parent][key] = child
		return child
	end
	local function region(owner, atlas, layer, sublevel, more)
		local o = { layer = layer or "ARTWORK", sublevel = sublevel or 0 }
		for k, v in pairs(more or {}) do
			o[k] = v
		end
		local made, raw = Rr(owner, atlas, o)
		local listed = W.rawOf[owner].regions
		listed[#listed + 1] = made
		-- Texture:IsDesaturated answers what SetDesaturated was given.
		function raw.IsDesaturated() return raw.desaturated == true end
		return made
	end
	-- A frame the addon makes textures on. A protected frame takes none in combat.
	local function owns(frame)
		local raw = W.rawOf[frame]
		local create = raw.CreateTexture
		raw.CreateTexture = function(self, ...)
			if raw.protected and W.combat then
				bad(W, "CreateTexture on a protected frame in combat")
			end
			return create(self, ...)
		end
		return frame
	end
	-- A font string of the game with the font the bars give their words, and the words on a bar: the centre, the left and the right.
	local function words(holder, keys, size)
		local list = {}
		for index, key in ipairs(keys) do
			local fs = region(holder, nil, "OVERLAY", 1, { kind = "FontString" })
			W.rawOf[fs].font = { "Fonts\\ARIALN.TTF", size or 12, "OUTLINE" }
			if string.sub(key, 1, 1) ~= "$" then
				put(holder, key, fs)
			end
			list[index] = fs
		end
		return list
	end
	U.words = words
	-- The circle mask the XML gives a portrait the game draws round, in the layer of the portrait.
	local function masked(owner, portrait, sublevel)
		local mask = put(owner, "PortraitMask", region(owner, "CircleMask", "BACKGROUND", sublevel, { kind = "MaskTexture" }))
		portrait:AddMaskTexture(mask)
		return mask
	end
	-- A status bar with a fill drawn from an atlas under a mask, and the calls the fills use.
	local function bar(parent, atlas, maskAtlas)
		local proxy, raw = B(parent, {}, { protected = true, objectType = "StatusBar" })
		W.maskable(raw)
		local fill = region(proxy, atlas)
		local fillRaw = W.rawOf[fill]
		local mask = region(proxy, maskAtlas, "OVERLAY", 2, { kind = "MaskTexture" })
		fill:AddMaskTexture(mask)
		raw.tint, raw.fill = { 1, 1, 1, 1 }, fill
		raw.GetStatusBarTexture = function() return fill end
		raw.SetStatusBarTexture = function(_, asset)
			fillRaw.color = nil
			if asset:find("[\\/]") then
				fillRaw.atlas, fillRaw.file = nil, asset
			else
				fillRaw.atlas, fillRaw.file = asset, nil
			end
			return true
		end
		raw.SetColorFill = function(_, r, g, b, a)
			if raw.refuseFill then
				error("SetColorFill failed", 0)
			end
			fillRaw.color, fillRaw.atlas, fillRaw.file = { r, g, b, a }, nil, nil
		end
		raw.SetStatusBarColor = function(_, r, g, b, a) raw.tint = { r, g, b, a or 1 } end
		raw.GetStatusBarColor = function() return unpack(raw.tint, 1, 4) end
		return proxy, raw, fill, mask
	end
	local function powerBar(parent, atlas, maskAtlas, token)
		local proxy, raw, fill, mask = bar(parent, atlas, maskAtlas)
		raw.powerToken = token or "MANA"
		U.power[proxy] = raw.powerToken
		return proxy, raw, fill, mask
	end

	-- The client draws the unit into a texture: every call is recorded, and U.refuse names the units it fails for (true for all).
	W.portraits = {}
	env.SetPortraitTexture = function(texture, unit, noMask)
		argt(W, "SetPortraitTexture", texture)
		if type(unit) ~= "string" or (noMask ~= nil and type(noMask) ~= "boolean") then
			bad(W, "SetPortraitTexture: a unit and a boolean are expected")
		end
		if (W.inBlizzard == 0 or (W.inHook or 0) > 0) and (U.refuse == true or (type(U.refuse) == "table" and U.refuse[unit])) then
			error("SetPortraitTexture failed", 0)
		end
		local raw = W.rawOf[texture]
		raw.file, raw.atlas, raw.color, raw.texCoord = nil, nil, nil, nil
		raw.portrait = unit
		W.portraits[#W.portraits + 1] = { texture = texture, unit = unit, noMask = noMask }
	end
	-- The game draws the portrait of a frame, or its class icon, each time the addon's hook is to see it.
	env.UnitFramePortrait_Update = blizz("UnitFramePortrait_Update", function(frame)
		if rawequal(frame, SECRET) or not frame.portrait or rawequal(frame.unit, SECRET) then
			return
		end
		if U.icon[frame] then
			frame.portrait:SetAtlas(U.icon[frame])
		else
			env.SetPortraitTexture(frame.portrait, frame.unit, frame.disablePortraitMask)
		end
	end)
	-- A frame of the game that has a portrait and says which unit it shows, as UnitFrame_Initialize does.
	local function unitFrame(frame, unit, portrait, noMask)
		local raw = W.rawOf[frame]
		raw.unit, raw.portrait, raw.disablePortraitMask = unit, portrait, noMask
	end

	-- The game's functions.
	env.PowerBarColor = { MANA = { r = 0, g = 0, b = 1 }, RAGE = { r = 1, g = 0, b = 0 }, ENERGY = { r = 1, g = 1, b = 0 } }
	env.UnitFrame_UpdateThreatIndicator = blizz("UnitFrame_UpdateThreatIndicator", function(indicator)
		if rawequal(indicator, SECRET) then
			return
		end
		local colour = U.threat[indicator]
		-- The game gives the colour with three numbers and the glow comes back at full alpha.
		if colour then
			indicator:SetVertexColor(colour[1], colour[2], colour[3])
			indicator:SetAlpha(1)
			indicator:Show()
		else
			indicator:Hide()
		end
	end)
	env.UnitFrameManaBar_UpdateType = blizz("UnitFrameManaBar_UpdateType", function(bar)
		if rawequal(bar, SECRET) then
			return
		end
		local token = U.power[bar]
		bar:SetStatusBarTexture("UI-HUD-UnitFrame-Player-PortraitOn-Bar-" .. token)
		bar:SetStatusBarColor(1, 1, 1)
		W.rawOf[bar].powerToken = token
	end)

	-- AuraUtil.SetAuraBorderColor gives the colour with four numbers, so the region comes back at full alpha (AuraUtil.lua:614-616).
	env.AuraUtil = { SetAuraBorderColor = blizz("AuraUtil.SetAuraBorderColor", function(border, dispelType)
		local c = ({ Magic = { 0.2, 0.6, 1 }, Curse = { 0.6, 0, 1 } })[dispelType] or { 0.8, 0, 0 }
		border:SetVertexColor(c[1], c[2], c[3], 1)
	end) }

	-- The player.
	W.group = "player"
	local player = B(nil, {}, { protected = true, objectType = "Button", name = "PlayerFrame" })
	env.PlayerFrame = player
	local container = owns(put(player, "PlayerFrameContainer", B(player, {}, {})))
	local content = put(player, "PlayerFrameContent", B(player, {}, { protected = true }))
	local main = put(content, "PlayerFrameContentMain", B(content, {}, { protected = true }))
	local context = put(content, "PlayerFrameContentContextual", B(content, {}, {}))
	local box = put(main, "HealthBarsContainer", B(main, {}, { protected = true }))
	local area = put(main, "ManaBarArea", B(main, {}, { protected = true }))
	local P = { frame = player }
	P.portrait = put(container, "PlayerPortrait", region(container, nil, "BACKGROUND", 1))
	P.portraitMask = put(container, "PlayerPortraitMask", region(container, "UI-HUD-UnitFrame-Player-Portrait-Mask", "BACKGROUND", 1, { kind = "MaskTexture" }))
	P.portrait:AddMaskTexture(P.portraitMask)
	P.art = { put(container, "FrameTexture", region(container, "UI-HUD-UnitFrame-Player-PortraitOn", "BACKGROUND", 2)),
		put(container, "VehicleFrameTexture", region(container, "UI-HUD-UnitFrame-Player-PortraitOn-Vehicle", "BACKGROUND", 2, { hidden = true })),
		put(container, "AlternatePowerFrameTexture", region(container, "UI-HUD-UnitFrame-Player-PortraitOn-ClassResource", "BACKGROUND", 2, { hidden = true })),
		put(context, "PlayerPortraitCornerIcon", region(context, "UI-HUD-UnitFrame-Player-PortraitOn-CornerEmbellishment", "OVERLAY", 1)) }
	P.flash = put(container, "FrameFlash", region(container, "UI-HUD-UnitFrame-Player-PortraitOn-InCombat", "OVERLAY", 0, { hidden = true }))
	P.status = put(main, "StatusTexture", region(main, "UI-HUD-UnitFrame-Player-PortraitOn-Status", "OVERLAY", 2, { hidden = true }))
	W.rawOf[P.status].width, W.rawOf[P.status].height = 190.4, 66
	W.rawOf[P.art[1]].width, W.rawOf[P.art[1]].height = 232, 100
	P.pvp = put(main, "PvpBackgroundCircle", region(main, "UI-HUD-UnitFrame-SmallCircle", "OVERLAY", 3, { hidden = true }))
	P.pvpIcon = put(main, "PvpBackgroundIcon", region(main, "UI-HUD-UnitFrame-SmallCircle-Alliance", "OVERLAY", 4, { hidden = true }))
	P.timer = region(main, nil, "OVERLAY", 4, { kind = "FontString", hidden = true })
	env.PlayerPVPTimerText = P.timer
	P.level = put(main, "LevelBackgroundCircle", region(main, "UI-HUD-UnitFrame-SmallCircle", "OVERLAY", 4))
	P.levelText = region(main, nil, "OVERLAY", 4, { kind = "FontString" })
	-- Camelot's PlayerFrame_OnLoad gives the number one point, on the level plate (Camelot/PlayerFrame.lua:6-7).
	P.levelText:SetPoint("CENTER", P.level, "CENTER", 0, -0.5)
	env.PlayerLevelText = P.levelText
	P.nameText = region(main, nil, "OVERLAY", 1, { kind = "FontString" })
	W.rawOf[P.nameText].font, W.rawOf[P.nameText].textColour = { "Fonts\\FRIZQT__.TTF", 10, "" }, { 1, 0.82, 0, 1 }
	env.PlayerName = P.nameText
	U.nameOf = { [player] = P.nameText }
	-- The resting animation is a frame in the contextual frame, shown and hidden by PlayerFrame_UpdateStatus (Mainline/PlayerFrame.xml:395-409).
	P.restLoop = put(context, "PlayerRestLoop", B(context, {}, { hidden = true }))
	P.rest = put(P.restLoop, "RestTexture", region(P.restLoop, "UI-HUD-UnitFrame-Player-Rest-Flipbook", "ARTWORK", 0))
	unitFrame(player, "player", P.portrait, true)
	-- The red bar for the health just lost is made before the health bar, and both fills are in BACKGROUND at sublevel 0.
	P.loss, _, P.lossFill = bar(box, "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Health", "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Health-Mask")
	put(box, "PlayerFrameHealthBarAnimatedLoss", P.loss)
	P.health, _, P.healthFill, P.healthMask = bar(box, "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Health", "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Health-Mask")
	put(box, "HealthBar", P.health)
	put(box, "HealthBarMask", P.healthMask)
	for _, fill in ipairs({ P.lossFill, P.healthFill }) do
		W.rawOf[fill].layer, W.rawOf[fill].sublevel = "BACKGROUND", 0
	end
	P.power, _, P.powerFill, P.powerMask = powerBar(area, "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Mana", "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Mana-Mask")
	put(area, "ManaBar", P.power)
	put(P.power, "ManaBarMask", P.powerMask)
	P.healthWords = words(box, { "HealthBarText", "LeftText", "RightText" })
	P.powerWords = words(P.power, { "ManaBarText", "LeftText", "RightText" })
	P.box, P.container, P.content, P.main, P.context, P.area = box, container, content, main, context, area
	W.player = P
	-- The art functions place the power bar from secure code, which the game may do in combat (Mainline/PlayerFrame.lua:621, 727). U.powerY: where they put it.
	W.rawOf[P.power].combatOk = true
	env.PlayerFrame_ToPlayerArt = blizz("PlayerFrame_ToPlayerArt", function()
		P.art[1]:SetAtlas("UI-HUD-UnitFrame-Player-PortraitOn")
		P.art[1]:Show()
		P.art[2]:Hide()
		P.status:SetAtlas("UI-HUD-UnitFrame-Player-PortraitOn-Status", true)
		W.rawOf[P.power].SetPoint(P.power, "TOPLEFT", P.main, "TOPLEFT", 85, U.powerY or -61)
	end)
	env.PlayerFrame_ToVehicleArt = blizz("PlayerFrame_ToVehicleArt", function()
		P.art[1]:Hide()
		P.art[2]:Show()
		W.rawOf[P.power].SetPoint(P.power, "TOPLEFT", P.main, "TOPLEFT", 91, U.powerY or -61)
		P.status:SetAtlas("UI-HUD-UnitFrame-Player-PortraitOn-Vehicle-Status", true)
	end)
	-- A role icon takes the place of the level number.
	env.PlayerFrame_UpdateRolesAssigned = blizz("PlayerFrame_UpdateRolesAssigned", function()
		P.levelText:SetShown(not U.roleIcon)
	end)
	env.PlayerFrame_UpdateStatus = blizz("PlayerFrame_UpdateStatus", function()
		P.restLoop:SetShown(U.resting == true)
