		T.W.flush()
		check("insthook: hud xp fill, taintLog 2: with Flat fill off the game's fill stays", exp.fillRaw.atlas == EXP and exp.fillRaw.color == nil)
		T.W.change("hud.xpFill", true)
		T.W.blizzard(function() exp.status:SetBarTexture("ui-hud-experiencebar-fill-somethingnew") end)
		T.W.fire("PLAYER_LEVEL_UP")
		T.W.flush()
		check("insthook: hud xp fill: a level up is seen on the next frame and again after the animation", exp.fillRaw.color and near(exp.fillRaw.color[1], 0.5))
	end
	-- hkhud: no method of a frame the page styles is hooked, with taintLog 0 and 2. The bag buttons, the bags bar, the aura buttons and the experience
	-- container are looked at again on the next frame after the game's events and after the size of a bar changes; the minimap mask after its variable changes.
	for _, tl in ipairs({ "0", "2" }) do
		local T = hudWorld()
		local TW = T.W
		TW.login()
		TW.flush()
		TW.cvars.taintLog = tl
		local back, debuff = T.bags.MainMenuBarBackpackButton, T.debuff
		local frames = { { back.btn, "UpdateTextures" }, { T.bagBar, "UpdateDividers" }, { T.xp, "UpdateDividers" }, { debuff.btn, "Update" }, { T.map, "SetMaskTexture" },
			{ T.exp.frame, "Update" }, { T.rep.frame, "Update" } }
		local written = 0
		for _, entry in ipairs(frames) do
			if INSTHOOK.wrapped(TW, entry[1], entry[2]) then
				written = written + 1
			end
		end
		check("hkhud: hud, taintLog " .. tl .. ": no method of a bag button, the bags bar, an aura button, the experience container or the minimap has a hook written on it", written == 0, written)
		local kinds = 0
		for _ in pairs(T.bagBarRaw.scriptHooks) do
			kinds = kinds + 1
		end
		check("hkhud: hud, taintLog " .. tl .. ": the bags bar and the experience container take a hook on their size, and nothing else is hooked on them",
			#(T.bagBarRaw.scriptHooks.OnSizeChanged or {}) == 1 and #(TW.rawOf[T.xp].scriptHooks.OnSizeChanged or {}) == 1 and kinds == 1)
		-- Bags: the game's texture update shows the highlight again, and the next frame after its event hides it.
		TW.blizzard(function() back.btn:UpdateTextures() end)
		local shown = back.highlight.alpha == 0.4
		TW.fire("BAG_UPDATE")
		local waits = back.highlight.alpha == 0.4
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": a bag button the game drew again is flat again on the next frame after the event, not before", shown and waits and back.highlight.alpha == 0 and TW.state(back.btn) == "SB")
		TW.blizzard(function() back.btn:UpdateTextures() end)
		TW.fire("PLAYER_EQUIPMENT_CHANGED", 20, false)
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": an equipment change styles the buttons again too", back.highlight.alpha == 0)
		-- Dividers: a divider the game makes when it lays out the bar is transparent on the next frame after the size of the bar changes.
		TW.blizzard(function() T.bagBar:UpdateDividers() end)
		local made = #T.barsPool.items
		local before = T.barsPool.items[made].alpha
		FH.script(TW, T.bagBar, "OnSizeChanged")
		local waiting = T.barsPool.items[made].alpha
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": a new divider of the bags bar is transparent on the next frame after the size changes", before == 1 and waiting == 1 and T.barsPool.items[made].alpha == 0, before)
		TW.blizzard(function() T.xp:UpdateDividers() end)
		FH.script(TW, T.xp, "OnSizeChanged")
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": and so is a new divider of the experience container", T.xpPool.items[#T.xpPool.items].alpha == 0)
		-- Auras: the game's update sets the type of the debuff, and the colour follows on the next frame after the event of the player's auras.
		TW.blizzard(function() debuff.btn:Update({ auraType = "Debuff", debuffType = "Poison" }) end)
		local old = colour(TW.look(debuff.icon), 0.2, 0.6, 1)
		TW.fire("UNIT_AURA", "target")
		TW.flush()
		local target = colour(TW.look(debuff.icon), 0.2, 0.6, 1)
		TW.fire("UNIT_AURA", "player")
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": the colour of a debuff follows the game's update on the next frame after the player's aura event, and an aura event of another unit changes nothing",
			old and target and colour(TW.look(debuff.icon), 0, 0.6, 0))
		TW.change("hud.auras", false)
		TW.blizzard(function() debuff.btn:Update({ auraType = "Debuff", debuffType = "Curse" }) end)
		TW.fire("UNIT_AURA", "player")
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": with the border off the aura event styles nothing", TW.state(debuff.icon) == "hb" and debuff.debuffBorder.alpha == 1)
		TW.fire("WEAPON_ENCHANT_CHANGED")
		FH.script(TW, T.buffFrame, "OnEvent", "WEAPON_ENCHANT_CHANGED")
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": with the border and the sizes at the game's, the buff frame's event styles nothing", TW.state(debuff.icon) == "hb" and debuff.debuffBorder.alpha == 1)
		TW.change("hud.auras", true)
		TW.blizzard(function() debuff.btn:Update({ auraType = "Debuff", debuffType = "Poison" }) end)
		FH.script(TW, T.buffFrame, "OnEvent", "WEAPON_ENCHANT_CHANGED")
		local waitsEnchant = colour(TW.look(debuff.icon), 0, 0.6, 0)
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": the buff frame's event for a weapon enchant styles the buttons the game handed out on the next frame, not before",
			not waitsEnchant and colour(TW.look(debuff.icon), 0, 0.6, 0) and #(TW.rawOf[T.buffFrame].scriptHooks.OnEvent or {}) == 1)
		-- The minimap mask: put on again after the variable of the game's own mask changes, and not for another variable.
		TW.change("hud.shape", "Square")
		local calls = T.maskCalls
		TW.blizzard(function() T.map:SetMaskTexture(MAP_MASK) end)
		TW.fire("CVAR_UPDATE", "rotateMinimap", "1")
		TW.flush()
		local after = T.maskCalls
		TW.blizzard(function() T.map:SetMaskTexture(MAP_MASK) end)
		TW.fire("CVAR_UPDATE", "somethingElse", "1")
		TW.flush()
		check("hkhud: hud, taintLog " .. tl .. ": the square mask goes on again after the rotateMinimap variable changes and for no other variable", after == calls + 2 and T.maskCalls == after + 1, calls .. " " .. after .. " " .. T.maskCalls)
		check("hkhud: hud, taintLog " .. tl .. ": nothing raised and nothing written in the game's frames", #TW.errors == 0 and #TW.violations == 0, table.concat(TW.violations, "|"))
	end
	do
		local modes = H.modes
		check("hud minimap buttons: the plate of the tracking button is transparent and the button has a thin border and a background",
			H.plate.alpha == 0 and W.state(H.tracking) == "SB" and ringOf(W, H.tracking, 1, 0, 0, 0))
		check("hud minimap buttons: each picture of the banner has a transparent background and border and a thin border and background of its own",
			every(MODES, function(key) return modes[key].back.alpha == 0 and modes[key].border.alpha == 0 and W.state(modes[key].frame) == "SB" end))
		check("hud minimap buttons: the glyphs are not touched, nor is what the game shows and hides",
			H.glyph.alpha == 1 and H.glyph.calls.SetAlpha == nil and every(MODES, function(key) return modes[key].glyph.alpha == 1 and modes[key].glyph.calls.SetAlpha == nil end)
				and H.tracking.shown == false and modes.Default.frame.shown and not modes.Guild.frame.shown and not modes.ChallengeMode.frame.shown
				and W.rawOf[H.tracking].calls.Show == nil and W.rawOf[H.tracking].calls.Hide == nil)
		W.change("general.border", "ff336699")
		W.change("general.thickness", 2)
		W.flush()
		check("hud minimap buttons: the colour and thickness of the general page reach them", colour(W.look(H.tracking), 0.2, 0.4, 0.6) and W.look(H.tracking).thick == 2
			and colour(W.look(modes.Guild.frame), 0.2, 0.4, 0.6))
		W.change("general.border", "ff000000")
		W.change("general.thickness", 1)
		W.change("hud.minimapBorder", false)
		check("hud minimap buttons: border off hides the borders and leaves the art transparent", W.state(H.tracking) == "hb" and H.plate.alpha == 0
			and every(MODES, function(key) return W.state(modes[key].frame) == "hb" and modes[key].back.alpha == 0 end))
		W.change("hud.minimapBorder", true)
		W.change("hud.minimapArt", false)
		check("hud minimap buttons: art off gives the plate and the banner back and leaves the borders", H.plate.alpha == 1 and W.state(H.tracking) == "SB"
			and every(MODES, function(key) return modes[key].back.alpha == 1 and modes[key].border.alpha == 1 and W.state(modes[key].frame) == "SB" end))
		W.change("hud.minimapArt", true)
		check("hud minimap buttons: art on again, nothing is made twice", H.plate.alpha == 0 and #W.edgesOn(W.holderOn(H.tracking)) == 4 and every(MODES, function(key) return modes[key].border.alpha == 0 end))
	end
	do
		local cm = H.micro.CharacterMicroButton
		check("hud micro menu: each button has a thin border and a background in place of its plate, and the menu frame is transparent",
			every(MICRO, function(n) return W.state(H.micro[n].btn) == "SB" and H.micro[n].plate.alpha == 0 and H.micro[n].pushed.alpha == 0 end)
				and H.menu.BorderArt.alpha == 0 and H.menu.BackgroundArt.alpha == 0)
		W.change("hud.micro", false)
		check("hud micro menu: off gives the plates and the menu frame back", W.state(cm.btn) == "hb" and cm.plate.alpha == 1 and cm.pushed.alpha == 1 and H.menu.BorderArt.alpha == 1)
		W.change("hud.micro", true)
		check("hud: no violation, error or message, and the status counts the ring, the header, the tracking button, 3 banner pictures, 7 bag buttons, 4 aura buttons, 2 bars and 3 micro buttons",
			#W.violations == 0 and #W.errors == 0 and #W.out == 0 and has(W.status(), "Minimap and buffs: on, 22 styled"), W.line("Minimap and buffs"))
	end

	-- Off for the whole page: the game's art exactly, and every outline hidden.
	do
		W.change("hud.enabled", false)
		local targets = { H.header, H.tracking, H.modes.Default.frame, H.modes.Guild.frame, H.modes.ChallengeMode.frame, H.buff.icon, H.debuff.icon, H.enchant.icon, H.deadly.icon, H.exp.status, H.rep.status }
		for _, name in ipairs(BAGS) do
			targets[#targets + 1] = H.bags[name].btn
		end
		for _, name in ipairs(MICRO) do
			targets[#targets + 1] = H.micro[name].btn
		end
		local diff = W.diff("hud")
		check("hud: the page switch off puts back everything the game drew and hides every border and the disc",
			#diff == 0 and every(targets, function(target) return W.state(target):sub(1, 1) == "h" end) and not ringFrame(W).regions[1].shown, table.concat(diff, "; "):sub(1, 300))
	end

	-- Switches that are off at login, and the page off at login, leave the frames alone.
	do
		local D = login({ saved = { options = { ["hud.bags"] = false, ["hud.auras"] = false, ["hud.xpFrame"] = false, ["hud.xpFill"] = false, ["hud.micro"] = false } } })
		check("hud: a part that is off at login touches nothing of its own, the others work",
			D.W.look(D.bags.KeyRingButton.btn) == nil and D.bags.KeyRingButton.normal.alpha == 1 and D.W.look(D.buff.icon) == nil and D.exp.back.alpha == 1 and D.exp.fillRaw.atlas == EXP
				and D.micro.CharacterMicroButton.plate.alpha == 1 and D.xp.BarFrameTexture.alpha == 1 and D.compass.alpha == 0 and D.W.state(D.header) == "SB")
		local O = login({ saved = { options = { ["hud.enabled"] = false } } })
		check("hud: the page off at login touches nothing", #O.W.diff("hud") == 0 and ringFrame(O.W) == nil and #O.W.addonMasks == 0 and O.W.look(O.header) == nil and O.W.look(O.tracking) == nil
			and O.W.line("Minimap and buffs") == "Minimap and buffs: off")
	end

	-- Frames the addon may not touch, and values the client withholds.
	do
		local F = login({ cluster = true, bag = "CharacterBag1Slot" })
		local G = login({ forbidMode = true })
		check("hud: a forbidden banner picture is not touched and the others are", #G.W.violations == 0 and #G.W.errors == 0 and G.W.look(G.modes.Guild.frame) == nil and G.modes.Guild.back.alpha == 1
			and G.W.state(G.modes.Default.frame) == "SB" and G.modes.Default.back.alpha == 0)
		check("hud: a forbidden cluster and a forbidden bag button are not touched, and the rest is styled",
			#F.W.violations == 0 and #F.W.errors == 0 and F.header.TopEdge.alpha == 1 and F.dielBorder.alpha == 1 and ringFrame(F.W) == nil and F.compass.alpha == 0
				and F.W.look(F.bags.CharacterBag1Slot.btn) == nil and F.W.state(F.bags.CharacterBag2Slot.btn) == "SB", table.concat(F.W.violations, "|"))
		local T2 = login({ secret = { tracking = true, modes = true } })
		check("hud: a tracking button and a list of banner pictures that hold a withheld value are skipped, and the rest is styled", #T2.W.violations == 0 and #T2.W.errors == 0
			and T2.W.look(T2.tracking) == nil and T2.plate.alpha == 1 and T2.W.look(T2.modes.Default.frame) == nil and T2.modes.Default.back.alpha == 1 and T2.W.state(T2.header) == "SB"
			and not has(T2.W.status(), "failed"), T2.W.status())
		local S = login({ secret = { header = true, icon = true, list = true, status = true } })
		check("hud: a header, an aura list, an icon and a status bar that hold a withheld value are skipped, and the rest is styled",
			#S.W.violations == 0 and #S.W.errors == 0 and not has(S.W.status(), "failed") and S.header.TopEdge.alpha == 1 and S.W.look(S.buff.icon) == nil and S.W.look(S.deadly.icon) == nil
				and S.W.look(S.exp.status) == nil and S.W.state(S.rep.status) == "SB" and S.W.state(S.debuff.icon) == "Sb" and ringFrame(S.W) ~= nil, S.W.status())
	end

	-- Frames the game may protect get nothing made on them in combat; the module looks again when combat ends.
	do
		local C = hudWorld({ combat = true, protect = "bags" })
		C.W.login()
		C.W.flush()
		local during = #C.W.violations == 0 and C.W.look(C.bags.KeyRingButton.btn) == nil and C.bags.KeyRingButton.normal.alpha == 1 and C.W.state(C.exp.status) == "SB"
		C.W.combat = false
		C.W.fire("PLAYER_REGEN_ENABLED")
		C.W.flush()
		check("hud: in combat a protected bag button has nothing made on it and the rest is styled; when combat ends the button is styled",
			during and #C.W.violations == 0 and C.W.state(C.bags.KeyRingButton.btn) == "SB" and C.bags.KeyRingButton.normal.alpha == 0, table.concat(C.W.violations, "|"))
		local P = hudWorld({ combat = true, protect = "auras" })
		P.W.login()
		check("hud: in combat a protected aura button has no border", P.W.look(P.buff.icon) == nil and #P.W.violations == 0 and P.buff.debuffBorder.alpha == 1)
	end

	-- A part that keeps failing is stopped alone and gives its art back.
	do
		local K = login({ broken = true })
		check("hud: three bag buttons that cannot take a texture stop the bags alone, and the bags that were styled are put back",
			has(K.W.status(), "Minimap and buffs: bags stopped. CreateTexture failed") and K.W.state(K.bags.MainMenuBarBackpackButton.btn) == "hb" and K.bags.MainMenuBarBackpackButton.normal.alpha == 1
				and K.bags.CharacterBag2Slot.highlight.alpha == 0.4 and K.W.state(K.exp.status) == "SB" and K.W.state(K.buff.icon) == "Sb" and #K.W.errors == 0, K.W.status())
	end

	-- Minimap in cities. In some cities the game loads Blizzard_HybridMinimap and shows its city map over the whole square of the minimap
	-- (Minimap.lua:226-232, Blizzard_HybridMinimap.xml:5-10). The default is a cover of the addon's own over the corners, with the border round the circle.
	do
		local K = { ORDER = { BACKGROUND = 1, LOW = 2, MEDIUM = 3 }, FILE = "Interface\\AddOns\\FlatUI\\Media\\Cover.tga",
			RING = "Game's ring while the city map shows", COVER = "Flat round cover", LEAVE = "Leave as is",
			NOT = "Minimap in cities: city map not shown, game asks for it: unknown.",
			WITHHELD = "Minimap in cities: off, the game does not say whether the city map is shown, game asks for it: unknown.",
			NOLOAD = "Minimap in cities: city map not loaded, game asks for it: unknown.", NOREAD = "Minimap in cities: city map cannot be read, game asks for it: unknown.",
			BLOCKED = "Minimap in cities: city map shown (BACKGROUND 100, game's mask set), no cover (the game does not let the minimap be read), game asks for it: unknown." }
		-- The status line while the city map is shown: where the game puts the city map and whether its mask is set, then the cover with its strata
		-- and level, which are the minimap's, or no cover.
		function K.shown(H, cover)
			return "Minimap in cities: city map shown (BACKGROUND 100, game's mask set), "
				.. (cover and ("cover shown (LOW " .. H.W.rawOf[H.map].level .. ")") or "no cover") .. ", game asks for it: unknown."
		end
		-- The game loads the addon, which fires ADDON_LOADED, and then shows the map.
		function K.load(H, shown)
			makeCity(H, false)
			H.W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			if shown then
				H.W.blizzard(function() H.city:Show() end)
			end
			H.W.flush()
		end
		function K.set(H, shown)
			H.W.blizzard(function() H.city:SetShown(shown) end)
			H.W.flush()
		end
		-- The cover is the one frame of the addon's own on the minimap itself. The border disc is on its container.
		function K.cover(W)
			for _, frame in ipairs(W.addonFrames) do
				if frame.parent == W.env.Minimap then
					return frame
				end
			end
		end
		-- Whether a frame is seen: it and every frame it hangs from is shown.
		function K.visible(W, frame)
			local raw = W.rawOf[frame]
			while raw do
				if raw.shown == false then
					return false
				end
				raw = raw.parent and W.rawOf[raw.parent]
			end
			return true
		end
		function K.rim(W, cover)
			for _, frame in ipairs(W.addonFrames) do
				if frame.parent == cover then
					return frame
				end
			end
		end
		function K.tint(texture, r, g, b)
			local v = texture.vertex
			return near(v[1], r, 1e-6) and near(v[2], g, 1e-6) and near(v[3], b, 1e-6) and v[4] == 1
		end
		function K.clean(W)
			return #W.violations == 0 and #W.errors == 0 and #W.out == 0
		end
		K.BACKDROP = 15 / 255

		-- The default, Flat round cover.
		do
			local H = login()
			local W = H.W
			K.before = K.cover(W) == nil and W.env.HybridMinimap == nil and W.line("Minimap in cities") == K.NOLOAD and #W.addonMasks == 1
			K.load(H, false)
			local raw = H.cityRaw
			check("city: before the game loads the city map nothing of it is made and the status says it is not loaded", K.before)
			check("city: the game loads the city map hidden: one hook on its OnShow and one on its OnHide, no cover, and the status says it is not shown",
				#raw.hooks.OnShow == 1 and #raw.hooks.OnHide == 1 and K.cover(W) == nil and W.line("Minimap in cities") == K.NOT
					and H.compass.alpha == 0, W.status())
			-- The border disc under the map is placed on every look at the minimap, so its anchor calls count the looks.
			local disc, looks = ringFrame(W).regions[1], ringFrame(W).regions[1].calls.SetPoint
			W.fire("ADDON_LOADED", "Blizzard_SomethingElse")
			K.other = disc.calls.SetPoint == looks
			W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			check("city: another addon loading does not make the minimap look again, and the loading of the city map does", K.other and disc.calls.SetPoint > looks
				and #raw.hooks.OnShow == 1 and #raw.hooks.OnHide == 1)
			local frames, textures = #W.addonFrames, #W.addonTextures
			K.set(H, true)
			local cover = K.cover(W)
			local rim = cover and K.rim(W, cover)
			local back, face = cover and cover.regions[1], rim and rim.regions[1]
			local mapRaw = W.rawOf[H.map]
			check("city: the city map shown: the cover is a frame of the addon's own on the minimap itself, which takes the strata of the minimap and has its level, so it is over the city map, with the size of the minimap",
				cover and cover.parent == H.map and cover.strata == nil and cover.GetFrameStrata() == mapRaw.strata and K.ORDER[cover.GetFrameStrata()] > K.ORDER[raw.strata]
					and cover.level == mapRaw.level and cover.allPoints == H.map and cover.shown and cover.calls.SetSize == nil and cover.calls.SetWidth == nil and cover.clips == true
					and cover.fixedStrata == nil and cover.fixedLevel == nil and #W.addonFrames == frames + 2, cover and tostring(cover.level))
			check("city: the border frame is on the cover, in the same strata and at the same level, so the zoom buttons and the ring, which are one level above the minimap, are over both",
				rim and rim.parent == cover and rim.strata == nil and rim.GetFrameStrata() == mapRaw.strata and rim.level == cover.level and rim.fixedStrata == nil and rim.fixedLevel == nil)
			check("city: the cover is two pictures of the circle: the border colour over the square, and the background colour on a frame a border thickness larger on every side, both opaque",
				back and face and back.file == K.FILE and back.allPoints == cover and face.file == K.FILE and face.allPoints == rim and rim.shown and K.tint(back, 0, 0, 0)
					and back.snap == false and face.snap == false and back.bias == 0 and face.bias == 0
					and K.tint(face, K.BACKDROP, K.BACKDROP, K.BACKDROP) and #rim.points == 2 and rim.points[1][1] == "TOPLEFT" and rim.points[1][2] == cover and near(rim.points[1][4], -T)
					and near(rim.points[1][5], T) and rim.points[2][1] == "BOTTOMRIGHT" and near(rim.points[2][4], T) and near(rim.points[2][5], -T) and #W.addonTextures == textures + 2)
			check("city: the ring stays transparent with the cover, the border disc under the map is as it was, and the status counts the cover and says the city map is shown",
				H.compass.alpha == 0 and H.underlay.alpha == 0 and ringFrame(W).regions[1].shown and W.line("Minimap in cities") == K.shown(H, true)
					and has(W.status(), "Minimap and buffs: on, 23 styled"), W.status())
			check("city: the cover, its border frame and both pictures are marked as the addon's own", W.ns.Own[cover] == true and W.ns.Own[rim] == true and W.ns.Own[back] == true
				and W.ns.Own[face] == true)
			K.set(H, false)
			check("city: the city map hidden: the cover is hidden and not unmade", cover.shown == false and #W.addonFrames == frames + 2 and #W.addonTextures == textures + 2
				and W.line("Minimap in cities") == K.NOT)
			K.set(H, true)
			check("city: shown again: the same cover shows, and nothing is made twice or hooked twice", cover.shown and #W.addonFrames == frames + 2 and #W.addonTextures == textures + 2
				and #raw.hooks.OnShow == 1 and #raw.hooks.OnHide == 1 and K.cover(W) == cover)
			-- The player hides the minimap with the key binding for it (Minimap.lua:144-156): the city map is still shown, the minimap and what hangs from it are gone.
			mapRaw.shown = false
			K.gone = not K.visible(W, cover) and not K.visible(W, rim) and cover.shown
			mapRaw.shown = true
			check("city: the cover goes with the minimap when the player hides it, though the city map is still shown, and comes back with it", K.gone and K.visible(W, cover) and K.visible(W, rim))
			-- The city map hides itself while the minimap is hidden, and its own hooks do not run. The minimap showing again is looked at.
			check("city: one hook on the minimap's OnShow, made once", #H.mapHooks.OnShow == 1 and #H.mapHooks.OnHide == 0)
			mapRaw.shown = false
			H.cityRaw.shown = false
			mapRaw.shown = true
			K.stale = cover.shown
			for _, fn in ipairs(H.mapHooks.OnShow) do
				H.W.inHook = (H.W.inHook or 0) + 1
				pcall(fn, H.map)
				H.W.inHook = H.W.inHook - 1
			end
			H.W.flush()
			check("city: the city map gone while the minimap was hidden: the minimap showing again looks at it, the cover is hidden and the status says the city map is not shown",
				K.stale and cover.shown == false and W.line("Minimap in cities") == K.NOT, W.status())
			K.set(H, true)
			-- A border colour, a thickness and a UI scale that change while the city map is hidden are in place when it shows again.
			K.set(H, false)
			W.change("general.thickness", 2)
			W.change("general.border", "ff336699")
			W.gameScale(0.5)
			W.flush()
			K.held = cover.shown == false and K.tint(back, 0.2, 0.4, 0.6) and near(rim.points[1][4], -2 * PX / 0.5) and near(rim.points[2][5], -2 * PX / 0.5)
			K.set(H, true)
			check("city: a thickness, a border colour and a UI scale changed while the city map is hidden are in place when it shows again, and the same cover shows",
				K.held and cover.shown and K.cover(W) == cover and K.tint(back, 0.2, 0.4, 0.6) and near(rim.points[1][4], -2 * PX / 0.5) and near(rim.points[2][5], -2 * PX / 0.5))
			W.gameScale(0.64)
			W.change("general.border", "ff000000")
			W.change("general.thickness", 1)
			W.flush()
			W.change("general.border", "ff336699")
			W.change("general.backdrop", "ff102030")
			W.change("general.thickness", 3)
			W.flush()
			K.colours = K.tint(back, 0.2, 0.4, 0.6) and K.tint(face, 16 / 255, 32 / 255, 48 / 255) and near(rim.points[1][4], -3 * T) and near(rim.points[2][5], -3 * T)
			W.gameScale(0.5)
			W.flush()
			check("city: the border colour, the background colour and the thickness of the Flat UI page reach the cover, and a new UI scale its border",
				K.colours and near(rim.points[1][4], -3 * PX / 0.5) and near(rim.points[2][4], 3 * PX / 0.5))
			W.gameScale(0.64)
			W.flush()
			W.change("general.borderless", true)
			K.borderless = not rim.shown and K.tint(back, 16 / 255, 32 / 255, 48 / 255) and cover.shown
			W.change("general.borderless", false)
			check("city: Borderless leaves the cover in the background colour with no border, and the border comes back with it off",
				K.borderless and rim.shown and K.tint(back, 0.2, 0.4, 0.6) and K.tint(face, 16 / 255, 32 / 255, 48 / 255))
			W.change("hud.minimapBorder", false)
			K.noBorder = not rim.shown and K.tint(back, 16 / 255, 32 / 255, 48 / 255) and cover.shown and not ringFrame(W).regions[1].shown
			W.change("hud.minimapBorder", true)
			check("city: the Minimap border switch off leaves the cover without its border, and on brings it back", K.noBorder and rim.shown and K.tint(back, 0.2, 0.4, 0.6))
			W.change("general.border", "ff000000")
			W.change("general.backdrop", "ff0f0f0f")
			W.change("general.thickness", 1)
			W.rawOf[H.map].width, W.rawOf[H.map].height = 250, 250
			W.flush()
			check("city: the cover follows the size of the minimap through its anchors, and the addon sets no size on it",
				cover.allPoints == H.map and rim.parent == cover and cover.calls.SetSize == nil and rim.calls.SetSize == nil and back.calls.SetSize == nil and face.calls.SetSize == nil
					and cover.calls.SetAllPoints == 1)
			check("city: no violation, error or message", K.clean(W), table.concat(W.violations, "|"))
			-- The page off takes everything away: the art of the game exactly, the cover hidden.
			W.change("hud.enabled", false)
			K.diff = W.diff("hud")
			check("city: the page switch off hides the cover, gives the ring back and leaves the city map as it is",
				cover.shown == false and H.compass.alpha == 1 and #K.diff == 0 and H.cityRaw.shown == true and not has(W.status(), "Minimap in cities"), table.concat(K.diff, "; "):sub(1, 300))
			local offLooks = disc.calls.SetPoint
			K.set(H, false)
			K.set(H, true)
			check("city: with the page off the city map shows and hides, the cover stays hidden and the minimap is not looked at", cover.shown == false and #W.addonFrames == frames + 2 and K.clean(W)
				and disc.calls.SetPoint == offLooks)
			W.change("hud.enabled", true)
			check("city: the page on again shows the cover that is made, and nothing is made twice or hooked twice",
				cover.shown and H.compass.alpha == 0 and #W.addonFrames == frames + 2 and #raw.hooks.OnShow == 1 and #raw.hooks.OnHide == 1 and K.cover(W) == cover)
			-- The setting changes with the city map up.
			W.change("hud.cityMap", K.RING)
			check("city: the ring choice while the city map shows: the cover goes and the ring and its underlay come back, the rest of the header art stays transparent",
				cover.shown == false and H.compass.alpha == 1 and H.underlay.alpha == 1 and H.header.TopEdge.alpha == 0 and H.dielBorder.alpha == 0 and H.plate.alpha == 0)
			K.set(H, false)
			check("city: the ring choice after the city map is gone: the ring is transparent again", H.compass.alpha == 0 and H.underlay.alpha == 0 and cover.shown == false)
			K.set(H, true)
			W.change("hud.cityMap", K.LEAVE)
			check("city: Leave as is while the city map shows: no cover and a transparent ring", cover.shown == false and H.compass.alpha == 0 and H.underlay.alpha == 0)
			W.change("hud.cityMap", K.COVER)
			check("city: the cover choice again shows the same cover and the ring is transparent", cover.shown and H.compass.alpha == 0 and K.cover(W) == cover and #W.addonFrames == frames + 2)
			W.change("hud.minimapArt", false)
			W.change("hud.cityMap", K.RING)
			K.artOff = H.compass.alpha == 1
			K.set(H, false)
			check("city: with the ring not hidden the game's ring is there with the city map shown or not", K.artOff and H.compass.alpha == 1 and K.clean(W))
			W.change("hud.minimapArt", true)
			W.change("hud.cityMap", K.COVER)
			K.set(H, false)
			W.ns.Set("hud.cityMap", "round")
			check("city: a value that is not a choice changes nothing", W.ns.Get("hud.cityMap") == "cover" and cover.shown == false)
		end

		-- The status line has what the cover depends on, and leaves out what the game will not say.
		do
			local H = login()
			local W = H.W
			K.load(H, true)
			local cover = K.cover(W)
			local at = "cover shown (LOW " .. W.rawOf[H.map].level .. "), game asks for it: unknown."
			-- The line for the facts that are given. What the status raised is not a line: a withheld value read as if it were plain raises there.
			local function says(facts)
				return "Minimap in cities: city map shown" .. (facts and (" (" .. facts .. ")") or "") .. ", " .. at
			end
			local function line()
				local ok, text = pcall(W.line, "Minimap in cities")
				return ok and text or ("raised: " .. tostring(text))
			end
			check("city: the status line has the strata and level of the city map, that the game's mask is set on it, and the strata and level of the cover, which are the minimap's",
				line() == says("BACKGROUND 100, game's mask set") and line() == K.shown(H, true), W.status())
			-- With the minimap hidden the cover is not on the screen, and the line says so.
			W.rawOf[H.map].shown = false
			K.hidden = line() == says("BACKGROUND 100, game's mask set"):gsub(", game asks", ", not visible, game asks", 1)
			W.rawOf[H.map].shown = true
			check("city: the status line says the cover is not visible while the minimap is hidden, and not after", K.hidden and line() == K.shown(H, true), W.status())
			H.canvasRaw.useMaskTexture = false
			K.off = line() == says("BACKGROUND 100, game's mask not set")
			H.canvasRaw.useMaskTexture, H.canvasRaw.maskTexture = true, nil
			check("city: a map canvas whose mask is not in use, or has none, is said to have the game's mask not set", K.off and line() == says("BACKGROUND 100, game's mask not set"))
			H.canvasRaw.maskTexture = true
			-- A withheld value keeps the type of what it hides, so the test of the type does not turn it away.
			W.secretType = "string"
			H.cityRaw.fault.strata = "secret"
			K.strata = line() == says("game's mask set")
			H.cityRaw.fault.strata = nil
			W.secretType = "number"
			H.cityRaw.fault.level = "secret"
			K.level = line() == says("game's mask set")
			H.cityRaw.fault.level = nil
			W.secretType = nil
			check("city: a city map whose strata, or whose level, the game withholds (a withheld string and a withheld number) has neither in the line", K.strata and K.level)
			H.cityRaw.fault.level = "string"
			K.string = line() == says("game's mask set")
			H.cityRaw.fault.level = nil
			check("city: a level that is not a number is left out of the line", K.string and line() == says("BACKGROUND 100, game's mask set"))
			H.canvasRaw.useMaskTexture = SECRET
			K.secret = line() == says("BACKGROUND 100")
			H.canvasRaw.useMaskTexture = true
			check("city: a mask flag the game withholds is left out of the line", K.secret and line() == says("BACKGROUND 100, game's mask set"))
			H.cityRaw.MapCanvas = nil
			check("city: a city map with no map canvas has no word about the mask", line() == says("BACKGROUND 100"))
			H.cityRaw.MapCanvas = H.canvas
			-- A city map the game will not say is shown or not: the cover is off, and the line says that and not that the city map is hidden.
			W.secretType = "boolean"
			H.cityRaw.fault.shown = "secret"
			K.withheld = line() == K.WITHHELD
			W.ns.modules.hud.Refresh()
			K.covered = cover.shown == false and H.compass.alpha == 0
			W.secretType = nil
			H.cityRaw.fault.shown = "error"
			K.err = line() == K.WITHHELD
			H.cityRaw.fault.shown = "string"
			K.str = line() == K.WITHHELD
			H.cityRaw.fault.shown = nil
			check("city: a city map whose shown state the game withholds, raises on or gives as something other than true or false: the cover is hidden and the line says it is off for that reason",
				K.withheld and K.covered and K.err and K.str and #W.errors == 0 and #W.violations == 0, W.status())
			W.ns.modules.hud.Refresh()
			check("city: and when the game says again the cover is back", cover.shown and line() == says("BACKGROUND 100, game's mask set") and K.cover(W) == cover)
			W.change("hud.cityMap", K.RING)
			check("city: with the ring choice the line says there is no cover", W.line("Minimap in cities") == K.shown(H, false))
			check("city: no violation, error or message", K.clean(W), table.concat(W.violations, "|"))
		end

		-- The name of the addon the game loaded is withheld: it is not compared, and the minimap is not looked at again for it.
		do
			local H = login()
			local W = H.W
			makeCity(H, false)
			local was = W.env.issecretvalue
			W.env.issecretvalue = function(v) return v == "Blizzard_HybridMinimap" or was(v) end
			W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			W.flush()
			K.skipped = #H.cityRaw.hooks.OnShow == 0 and #H.cityRaw.hooks.OnHide == 0
			W.env.issecretvalue = was
			W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			W.flush()
			check("city: an addon name the game withholds is not compared, and the name of the city map's addon is when it is plain",
				K.skipped and #H.cityRaw.hooks.OnShow == 1 and #H.cityRaw.hooks.OnHide == 1 and #W.errors == 0 and #W.violations == 0)
		end

		-- The status line says what the game answers to C_Minimap.ShouldUseHybridMinimap (MinimapDocumentation.lua:245), before the city map is loaded
		-- and while it is shown, and says unknown when the call is missing, raises, is withheld or does not answer true or false.
		do
			local H = login()
			local W = H.W
			local function asked(answer)
				W.env.C_Minimap = { ShouldUseHybridMinimap = answer }
				return W.line("Minimap in cities")
			end
			K.yes = asked(function() return true end) == "Minimap in cities: city map not loaded, game asks for it: yes."
			K.no = asked(function() return false end) == "Minimap in cities: city map not loaded, game asks for it: no."
			K.load(H, true)
			K.shownYes = asked(function() return true end) == K.shown(H, true):gsub("unknown%.$", "yes.")
			K.shownNo = asked(function() return false end) == K.shown(H, true):gsub("unknown%.$", "no.")
			W.secretType = "boolean"
			K.secret = asked(function() return SECRET end) == K.shown(H, true)
			W.secretType = nil
			K.raises = asked(function() error("no answer", 0) end) == K.shown(H, true)
			K.word = asked(function() return "yes" end) == K.shown(H, true)
			W.env.C_Minimap = {}
			K.missing = W.line("Minimap in cities") == K.shown(H, true)
			W.env.C_Minimap = nil
			check("city: the status line says that the game asks for the city map, before it is loaded and while it is shown", K.yes and K.no and K.shownYes and K.shownNo, W.status())
			check("city: a call that is withheld, raises, answers with a word or is missing is said as unknown", K.secret and K.raises and K.word and K.missing and K.clean(W), W.status())
		end

		-- A stopped minimap part gives the game's look back, the cover with it, and leaves the city map alone.
		do
			local H = login({ city = "shown" })
			local W = H.W
			local cover = K.cover(W)
			K.up = cover ~= nil and cover.shown and H.compass.alpha == 0
			for i = 1, 3 do
				W.ns.EachPart("hud", "minimap", function() error("part failed", 0) end, "frame" .. i)
			end
			W.ns.modules.hud.Refresh()
			check("city: the minimap part stopped: the cover is hidden, the ring is back and the city map is as it was",
				K.up and cover.shown == false and H.compass.alpha == 1 and H.cityRaw.shown == true and #W.violations == 0 and #W.errors == 0)
			K.set(H, false)
			K.set(H, true)
			check("city: and the cover stays hidden while the city map hides and shows", cover.shown == false and H.compass.alpha == 1 and #W.violations == 0 and #W.errors == 0)
		end

		-- The ring choice at login, and Leave as is: no cover is ever made.
		do
			local R = hudWorld({ saved = { options = { ["hud.cityMap"] = "ring" } }, city = "shown" })
			R.W.login()
			R.W.flush()
			local frames = #R.W.addonFrames
			R.W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			R.W.flush()
			check("city: the ring choice with the city map up at login: the ring and its underlay show, the other header art is transparent, and no cover is made",
				R.compass.alpha == 1 and R.underlay.alpha == 1 and R.header.TopEdge.alpha == 0 and K.cover(R.W) == nil and #R.W.addonFrames == frames and #R.cityRaw.hooks.OnShow == 1)
			K.set(R, false)
			K.set(R, true)
			check("city: the ring choice: the ring goes with the city map and returns with it, and no cover is made", R.compass.alpha == 1 and K.cover(R.W) == nil and K.clean(R.W))
			K.set(R, false)
			check("city: the ring choice: with the city map hidden the ring is transparent", R.compass.alpha == 0 and R.underlay.alpha == 0)
			local L = login({ saved = { options = { ["hud.cityMap"] = "leave" } } })
			local before = #L.W.addonFrames
			K.load(L, true)
			K.set(L, false)
			K.set(L, true)
			check("city: Leave as is changes nothing: no cover, the ring transparent as before, the same frames", K.cover(L.W) == nil and L.compass.alpha == 0 and #L.W.addonFrames == before
				and L.W.line("Minimap in cities") == K.shown(L, false) and K.clean(L.W))
		end

		-- Combat: nothing is made or placed in combat, and the module looks again when combat ends.
		do
			local C = hudWorld({ combat = true, city = "shown" })
			C.W.login()
			C.W.flush()
			check("city: login in combat with the city map up: no cover is made and the city map is hooked", K.cover(C.W) == nil and #C.cityRaw.hooks.OnShow == 1 and #C.W.violations == 0)
			C.W.combat = false
			C.W.fire("PLAYER_REGEN_ENABLED")
			C.W.flush()
			local cover = K.cover(C.W)
			check("city: when combat ends the cover is made and shown, with its border placed", cover and cover.shown and cover.allPoints == C.map and K.rim(C.W, cover).points[1][1] == "TOPLEFT"
				and #C.W.violations == 0, table.concat(C.W.violations, "|"))
			local frames = #C.W.addonFrames
			C.W.combat = true
			K.set(C, false)
			K.hidden = cover.shown == false
			K.set(C, true)
			check("city: in combat the cover hides and shows with the city map", K.hidden and cover.shown and #C.W.addonFrames == frames, tostring(#C.W.addonFrames - frames))
			local rim = K.rim(C.W, cover)
			local calls = rim.calls.SetPoint
			C.W.change("general.thickness", 3)
			C.W.flush()
			K.held = rim.calls.SetPoint == calls and near(rim.points[1][4], -T)
			C.W.combat = false
			C.W.fire("PLAYER_REGEN_ENABLED")
			C.W.flush()
			check("city: a thicker border in combat is not placed until combat ends", K.held and near(rim.points[1][4], -3 * T) and #C.W.violations == 0 and #C.W.errors == 0)
			-- A cover that was made with no border and gets one in combat waits for the end of combat to place it.
			local B = hudWorld({ city = "shown", saved = { options = { ["general.borderless"] = true } } })
			B.W.login()
			B.W.flush()
			local bare, bareRim = K.cover(B.W), nil
			bareRim = K.rim(B.W, bare)
			K.bare = bare.shown and not bareRim.shown and #bareRim.points == 0 and K.tint(bare.regions[1], K.BACKDROP, K.BACKDROP, K.BACKDROP)
			B.W.combat = true
			B.W.change("general.borderless", false)
			B.W.flush()
			K.waits = not bareRim.shown and #bareRim.points == 0 and K.tint(bare.regions[1], K.BACKDROP, K.BACKDROP, K.BACKDROP) and bare.shown
			B.W.combat = false
			B.W.fire("PLAYER_REGEN_ENABLED")
			B.W.flush()
			check("city: a cover made with no border gets one in combat: the corners stay covered and the border is placed and shown when combat ends",
				K.bare and K.waits and bareRim.shown and near(bareRim.points[1][4], -T) and K.tint(bare.regions[1], 0, 0, 0) and #B.W.violations == 0)
			-- The minimap may be a frame the game protects (Minimap.xml names no protection, but no source says it is not): nothing is made on it in combat.
			local M = hudWorld({ combat = true, protect = "minimap", city = "shown" })
			M.W.login()
			M.W.flush()
			K.none = K.cover(M.W) == nil and #M.W.violations == 0 and #M.W.errors == 0 and M.compass.alpha == 0
			M.W.combat = false
			M.W.fire("PLAYER_REGEN_ENABLED")
			M.W.flush()
			local mcover = K.cover(M.W)
			M.W.combat = true
			K.set(M, false)
			K.hid = mcover ~= nil and mcover.shown == false
			K.set(M, true)
			check("city: a protected minimap has no cover made on it in combat, gets one when combat ends, and the cover hides and shows with the city map in combat",
				K.none and K.hid and mcover.shown and mcover.parent == M.map and #M.W.violations == 0 and #M.W.errors == 0, table.concat(M.W.violations, "|"))
			local D = hudWorld({ combat = true })
			D.W.login()
			D.W.flush()
			makeCity(D, false)
			D.W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			D.W.blizzard(function() D.city:Show() end)
			check("city: the city map shown in combat for the first time: no cover is made, the ring stays transparent", K.cover(D.W) == nil and D.compass.alpha == 0 and #D.W.violations == 0)
			D.W.combat = false
			D.W.fire("PLAYER_REGEN_ENABLED")
			D.W.flush()
			check("city: and when combat ends it is made", K.cover(D.W) ~= nil and K.cover(D.W).shown and #D.W.violations == 0)
		end

		-- The page off at login, a client with no hook on a script, and a client with no minimap.
		do
			local O = hudWorld({ saved = { options = { ["hud.enabled"] = false } }, city = "shown" })
			O.W.login()
			O.W.fire("ADDON_LOADED", "Blizzard_HybridMinimap")
			O.W.flush()
			check("city: the page off at login: no hook, no cover, no line in the status and the ring as the game has it",
				#O.cityRaw.hooks.OnShow == 0 and #O.cityRaw.hooks.OnHide == 0 and K.cover(O.W) == nil and O.compass.alpha == 1 and not has(O.W.status(), "Minimap in cities"))
			O.W.change("hud.enabled", true)
			check("city: the page switched on with the city map up: hooked once and covered", #O.cityRaw.hooks.OnShow == 1 and #O.cityRaw.hooks.OnHide == 1 and K.cover(O.W) ~= nil and K.cover(O.W).shown
				and O.compass.alpha == 0)
			local N = hudWorld({ city = "shown" })
			N.cityRaw.HookScript = nil
			N.W.login()
			N.W.flush()
			check("city: a client whose city map takes no hook is not stopped, and the cover shows", #N.W.errors == 0 and not has(N.W.status(), "stopped")
				and not has(N.W.status(), "failed") and K.cover(N.W) ~= nil and K.cover(N.W).shown == true, N.W.status())
			local G = hudWorld({ city = "shown", none = { Minimap = true } })
			G.W.login()
			G.W.flush()
			check("city: a client without the minimap frame makes no cover", K.cover(G.W) == nil and #G.W.violations == 0 and #G.W.errors == 0)
			local P = hudWorld({ city = "shown", minimap = true })
			P.W.login()
			P.W.flush()
			check("city: a minimap the addon may not touch gets no cover and is not read, and the status says the game does not let it be read",
				K.cover(P.W) == nil and ringFrame(P.W) == nil and #P.W.violations == 0 and #P.W.errors == 0 and P.W.line("Minimap in cities") == K.BLOCKED, table.concat(P.W.violations, "|"))
			-- The cover is made on the minimap, so it needs the level of the minimap: without it there is no cover.
			for _, fault in ipairs({ "secret", "string", "error" }) do
				local V = hudWorld({ city = "shown" })
				V.W.rawOf[V.map].fault.level = fault
				V.W.secretType = "number"
				V.W.login()
				V.W.flush()
				K.said = V.W.line("Minimap in cities") == K.BLOCKED
				V.W.change("hud.cityMap", K.RING)
				check("city: a minimap whose level the game " .. (fault == "secret" and "withholds" or fault == "string" and "gives as a word" or "raises on")
					.. " gets no cover, nothing is raised, and the status says the game does not let the minimap be read, but only for the cover choice",
					K.cover(V.W) == nil and K.said and V.W.line("Minimap in cities") == K.shown(V, false) and #V.W.errors == 0 and #V.W.violations == 0, V.W.status())
			end
			local F = hudWorld({ city = "shown" })
			F.cityRaw.forbidden = true
			F.W.login()
			F.W.flush()
			check("city: a city map the addon may not touch is not hooked, read or covered, and the status says it cannot be read",
				K.cover(F.W) == nil and #F.cityRaw.hooks.OnShow == 0 and F.W.line("Minimap in cities") == K.NOREAD and #F.W.violations == 0 and #F.W.errors == 0, table.concat(F.W.violations, "|"))
			local S = hudWorld({ city = "shown" })
			S.cityRaw.fault.shown = "secret"
			S.W.secretType = "boolean"
			S.W.login()
			S.W.flush()
			check("city: a city map that will not say whether it is shown: no cover, and the status says the setting is off because the game does not say, not that the city map is hidden",
				K.cover(S.W) == nil and S.W.line("Minimap in cities") == K.WITHHELD and #S.W.errors == 0 and #S.W.violations == 0, S.W.status())
			local A = login({ saved = { options = { ["hud.minimapArt"] = false } } })
			K.load(A, true)
			K.set(A, false)
			check("city: with the ring not hidden the game's ring is never touched, with the city map shown or hidden", A.compass.calls.SetAlpha == nil and A.underlay.calls.SetAlpha == nil
				and K.cover(A.W) ~= nil)
		end
	end

	-- A client without any of these frames.
	do
		local gone = {}
		for _, name in ipairs({ "MinimapCompassTexture", "MinimapCompassTextureUnderlay", "MinimapCluster", "Minimap", "BagsBar", "BuffFrame", "DebuffFrame", "DeadlyDebuffFrame",
			"MainStatusTrackingBarContainer", "MicroMenu" }) do
			gone[name] = true
		end
		for _, name in ipairs(BAGS) do
			gone[name] = true
		end
		for _, name in ipairs(MICRO) do
			gone[name] = true
		end
		local N = login({ none = gone })
		check("hud: a client without these frames does nothing and says only its own line",
			N.W.line("Minimap and buffs") == "Minimap and buffs: on, 0 styled" and select(2, N.W.status():gsub("Minimap and buffs", "")) == 1 and ringFrame(N.W) == nil
				and #N.W.violations == 0 and #N.W.errors == 0 and #N.W.out == 0, N.W.status())
	end
end

-- 60b. The micro menu and the bag bar keep the Flat UI look while Leave the game's action bars alone is on. Every label starts "microbags:".
-- The frames are the ones the XML makes: MicroMenu with BorderArt and BackgroundArt (Blizzard_MicroMenu/Camelot/MainMenuBarMicroMenu.xml:3-17), buttons with
-- Background and PushedBackground (Blizzard_MicroMenu/Mainline/MainMenuBarMicroButtons.xml:20-29), BagsBar with BorderArt and dividers that are frames of
-- nine-slice pieces (Blizzard_MainMenuBarBagButtons/Camelot/MainMenuBarBagButtons.xml:58-67, Blizzard_ActionBar/Mainline/MainActionBar.xml:10-27).
-- Every call of the addon's own code on one of those frames, or on the container of the menu, that sets a place, a size, a scale, a parent, an alpha, a
-- shown state or an attribute is counted (the game's own calls, inside W.blizzard, are not).
do
	local NAMES = { "CharacterMicroButton", "SpellbookMicroButton", "MainMenuMicroButton" }
	local BAGLIST = { "MainMenuBarBackpackButton", "CharacterBag0Slot", "CharacterBag1Slot", "CharacterBag2Slot", "CharacterBag3Slot", "CharacterReagentBag0Slot", "KeyRingButton" }
	local FORBIDDEN = { "SetPoint", "ClearAllPoints", "SetSize", "SetWidth", "SetHeight", "SetScale", "SetParent", "SetAlpha", "Show", "Hide", "SetShown", "SetAttribute" }
	local function world(handsOff)
		local watch = { n = 0, log = {} }
		local H = FH.hudLogin({ handsOff = handsOff, extra = function(H, set, W)
			local function count(frame, label)
				local raw = W.rawOf[frame]
				for _, call in ipairs(FORBIDDEN) do
					local base = raw[call]
					if type(base) == "function" then
						raw[call] = function(...)
							if W.inBlizzard == 0 then
								watch.n = watch.n + 1
								watch.log[#watch.log + 1] = label .. "." .. call
							end
							return base(...)
						end
					end
				end
			end
			local function divider()
				local item = W.B(nil, {})
				local piece = W.R(nil, "ui-hud-actionbar-frame-divider")
				W.rawOf[item].regions = { piece }
				count(item, "Divider")
				return { frame = item, piece = piece }
			end
			H.container = W.B(nil, {})
			set("MicroMenuContainer", H.container)
			count(H.container, "MicroMenuContainer")
			count(H.menu, "MicroMenu")
			count(H.bagBar, "BagsBar")
			for _, name in ipairs(NAMES) do
				count(H.micro[name].btn, name)
			end
			for _, name in ipairs(BAGLIST) do
				count(H.bags[name].btn, name)
			end
			H.div, H.spare = divider(), divider()
			H.barsPool.items[1] = H.div.frame
		end })
		H.watch = watch
		return H
	end
	local function microOn(H, on)
		local good = true
		for _, name in ipairs(NAMES) do
			local part = H.micro[name]
			good = good and H.W.state(part.btn) == (on and "SB" or "hb") and part.plate.alpha == (on and 0 or 1) and part.pushed.alpha == (on and 0 or 1)
				and part.shadow.alpha == (on and 0 or 1) and part.pshadow.alpha == (on and 0 or 1)
		end
		return good and H.menu.BorderArt.alpha == (on and 0 or 1) and H.menu.BackgroundArt.alpha == (on and 0 or 1)
	end
	local function bagsOn(H, on)
		local good = true
		for _, name in ipairs(BAGLIST) do
			local part = H.bags[name]
			good = good and H.W.state(part.btn) == (on and "SB" or "hb") and part.normal.alpha == (on and 0 or 1) and part.pushed.alpha == (on and 0 or 1)
				and part.highlight.alpha == (on and 0 or 0.4) and part.slot.alpha == (on and 0 or 1)
		end
		return good and H.bagBar.BorderArt.alpha == (on and 0 or 1) and H.div.piece.alpha == (on and 0 or 1)
	end
	local function rowTip(ns, page, key)
		for _, p in ipairs(ns.PAGES) do
			if p.key == page then
				for _, row in ipairs(p) do
					if row.key == key then
						return row.tip
					end
				end
			end
		end
	end

	local H = world(true)
	local W = H.W
	check("microbags: with the row on, each micro button has Flat UI's outline and background, its plate and pushed plate are hidden, and the menu art is hidden", microOn(H, true))
	check("microbags: with the row on, each bag button has Flat UI's outline and its border art and highlight hidden, and the bag bar art and the pieces of a divider are hidden",
		bagsOn(H, true))
	check("microbags: with the row on, the frames of a divider, the bag bar, the micro menu and its container keep their alpha", W.rawOf[H.div.frame].alpha == 1
		and W.rawOf[H.bagBar].alpha == 1 and W.rawOf[H.menu].alpha == 1 and W.rawOf[H.container].alpha == 1)
	check("microbags: with the row on, 0 calls of " .. #FORBIDDEN .. " kinds (place, clear places, size, scale, parent, alpha, show, hide, attribute) on the menu, its container, the bag bar, a divider "
		.. "or any of the " .. (#NAMES + #BAGLIST) .. " buttons, and no violation", H.watch.n == 0 and #W.violations == 0 and #W.errors == 0 and #W.out == 0,
		H.watch.n .. " " .. table.concat(H.watch.log, ","):sub(1, 200) .. table.concat(W.violations, "|"))
	-- The game makes a divider in its layout pass and the bar's size changes: the hook only queues a look for the next frame.
	W.blizzard(function() table.insert(H.barsPool.items, H.spare.frame) end)
	FH.script(W, H.bagBar, "OnSizeChanged")
	check("microbags: a divider made in the game's layout pass is not touched inside it", H.spare.piece.alpha == 1 and H.watch.n == 0)
	W.flush()
	check("microbags: the next frame fades its pieces, with no call on the frame", H.spare.piece.alpha == 0 and H.watch.n == 0 and #W.violations == 0,
		H.watch.n .. " " .. table.concat(H.watch.log, ","):sub(1, 200))
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	W.fire("BAG_UPDATE")
	W.flush()
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("microbags: after a fight and a bag update still 0 calls and the look is unchanged", H.watch.n == 0 and #W.violations == 0 and microOn(H, true) and bagsOn(H, true),
		H.watch.n .. " " .. table.concat(H.watch.log, ","):sub(1, 200))
	W.ns.Set("hud.micro", false)
	W.ns.Set("hud.bags", false)
	W.flush()
	check("microbags: each row off gives the game's art back and hides Flat UI's outline, with 0 calls", microOn(H, false) and bagsOn(H, false) and H.spare.piece.alpha == 1 and H.watch.n == 0,
		H.watch.n .. " " .. table.concat(H.watch.log, ","):sub(1, 200))
	W.ns.Set("hud.micro", true)
	W.ns.Set("hud.bags", true)
	W.flush()
	check("microbags: each row on again styles them again, with 0 calls", microOn(H, true) and bagsOn(H, true) and H.watch.n == 0 and #W.violations == 0)

	-- A bag that is open shows the game's frame again over the icon (the slot highlight, shown with SetShown and given an atlas), and the look still hides it.
	W.blizzard(function()
		H.bags.CharacterBag0Slot.slot:SetShown(true)
		H.bags.CharacterBag0Slot.slot:SetAtlas("ui-hud-actionbar-iconframe-bags")
	end)
	W.fire("BAG_UPDATE")
	W.flush()
	check("microbags: a bag that is open has its slot highlight hidden with the row on,", H.bags.CharacterBag0Slot.slot.alpha == 0 and H.watch.n == 0, tostring(H.bags.CharacterBag0Slot.slot.alpha))

	-- A divider is three pieces made by CreateTexture, and the row changes without a reload.
	do
		local pieces = { W.R(nil, "ui-hud-actionbar-frame-divider"), W.R(nil, "ui-hud-actionbar-frame-divider"), W.R(nil, "ui-hud-actionbar-frame-divider") }
		local item = W.B(nil, {})
		W.rawOf[item].regions = pieces
		W.blizzard(function() table.insert(H.barsPool.items, item) end)
		FH.script(W, H.bagBar, "OnSizeChanged")
		W.flush()
		check("microbags: the three pieces of a divider are all hidden with the row on, and its frame keeps its alpha", pieces[1].alpha == 0 and pieces[2].alpha == 0 and pieces[3].alpha == 0 and W.rawOf[item].alpha == 1)
		W.ns.Set("general.handsOff", false)
		FH.script(W, H.bagBar, "OnSizeChanged")
		W.flush()
		check("microbags: with the row turned off without a reload, a refresh fades the frame of a divider and gives its pieces back", W.rawOf[item].alpha == 0 and pieces[1].alpha == 1
			and pieces[2].alpha == 1 and pieces[3].alpha == 1 and H.div.piece.alpha == 1, W.rawOf[item].alpha .. pieces[1].alpha .. pieces[3].alpha .. H.div.piece.alpha)
		W.ns.Set("hud.bags", false)
		W.flush()
		check("microbags: with the row off and the bag row off, the frame and the pieces of a divider are visible", W.rawOf[item].alpha == 1 and pieces[1].alpha == 1 and H.div.piece.alpha == 1)
		W.ns.Set("hud.bags", true)
		W.flush()
		W.ns.Set("general.handsOff", true)
		FH.script(W, H.bagBar, "OnSizeChanged")
		W.flush()
		check("microbags: with the row turned on again without a reload, the frame of a divider is given back and the pieces are hidden", W.rawOf[item].alpha == 1 and pieces[1].alpha == 0
			and pieces[3].alpha == 0 and H.div.piece.alpha == 0)
	end

	-- With the row off the bars are as they were before the row: the dividers fade through their own frames and the micro menu is styled.
	local O = world(false)
	check("microbags: with the row off the micro menu and the buttons are styled as before, and a divider fades through its own frame", microOn(O, true) and O.W.state(O.bags.KeyRingButton.btn) == "SB"
		and O.W.rawOf[O.div.frame].alpha == 0 and O.div.piece.alpha == 1 and O.bagBar.BorderArt.alpha == 0 and #O.W.violations == 0)

	local micro, bags, fade = rowTip(W.ns, "hudBars", "micro"), rowTip(W.ns, "hudBars", "bags"), rowTip(W.ns, "fade", "micro")
	check("microbags: the tips of the micro menu and bag bar look rows no longer say they are not applied, and the fade rows still do", micro ~= nil and bags ~= nil and fade ~= nil
		and not micro:find("Not applied", 1, true) and not bags:find("not restyled", 1, true) and not bags:find("Not applied", 1, true)
		and fade:find("Not applied while Leave the game's action bars alone is on.", 1, true) ~= nil and rowTip(W.ns, "fade", "bags"):find("Not applied", 1, true) ~= nil,
		tostring(micro) .. " | " .. tostring(bags))
end

-- 110. Chat and tooltips: the chat windows with their tabs and input boxes, the tooltips, and the health bar under a unit tooltip.
do
(function()
local PIECES = { "TopLeftCorner", "TopRightCorner", "BottomLeftCorner", "BottomRightCorner", "TopEdge", "BottomEdge", "LeftEdge", "RightEdge", "Center" }
local BORDER = { "TopLeftTexture", "BottomLeftTexture", "TopRightTexture", "BottomRightTexture", "LeftTexture", "RightTexture", "BottomTexture", "TopTexture" }
local TIPS = { "GameTooltip", "ItemRefTooltip", "ShoppingTooltip1", "ShoppingTooltip2", "ItemRefShoppingTooltip1", "ItemRefShoppingTooltip2" }
local FOCUS = { "focusLeft", "focusMid", "focusRight" }
local TAB_ART = { "Left", "Middle", "Right", "ActiveLeft", "ActiveMiddle", "ActiveRight" }
local TAB_LIGHT = { "HighlightLeft", "HighlightMiddle", "HighlightRight" }
local BAR_FILE = "Interface\\TargetingFrame\\UI-TargetingFrame-BarFill"
local ACCENT = 217 / 255

-- A client with two chat windows (a tab, an input box and a button frame each), the tooltips of the game, and the functions the addon follows.
-- spec: saved, combat, windows, noChat, noRegistry (no EventRegistry), noTips, bareTips (tooltips with no NineSlice), noBar, noData, noHook, forbidden = { name = true },
-- noCreateColor (no CreateColor), noGradient (textures without SetGradient), clearedBy (the texture call that takes a gradient off).
local function world(spec)
	spec = spec or {}
	local W = newWorld({ saved = spec.saved, combat = spec.combat, noGradient = spec.noGradient, clearedBy = spec.clearedBy })
	local env, ui, rawOf = W.env, W.env.UIParent, W.rawOf
	W.group = "chat"
	if not spec.noCreateColor then
		env.CreateColor = function(r, g, b, a)
			argn(W, "CreateColor", r, g, b)
			return setmetatable({ r = r, g = g, b = b, a = a or 1 }, COLOUR_MT)
		end
	end
	local hook = env.hooksecurefunc
	-- A hook is the addon's code even when the game's call runs inside W.blizzard.
	local function asAddon(fn)
		return function(...)
			local was = W.inBlizzard
			W.inBlizzard = 0
			local ok, err = pcall(fn, ...)
			W.inBlizzard = was
			if not ok then
				error(err, 0)
			end
		end
	end
	env.hooksecurefunc = function(a, b, c)
		if type(a) == "string" then
			return hook(env, a, asAddon(b))
		end
		return hook(a, b, asAddon(c))
	end
	if spec.noHook then
		env.hooksecurefunc = nil
	end
	-- hkchat: EventRegistry (CallbackRegistry.lua): the registrant is the first argument of the callback, and a callback is the addon's code.
	-- W.registry.owners counts the registrations per event; a second registration of an owner for an event replaces the first.
	if not spec.noRegistry then
		local registry = { calls = {} }
		function registry:RegisterCallback(event, fn, owner)
			if type(event) ~= "string" or type(fn) ~= "function" then
				error("CallbackRegistryMixin::RegisterCallback needs an event and a function", 0)
			end
			registry.calls[event] = registry.calls[event] or {}
			registry.calls[event][owner or fn] = fn
			return owner
		end
		function registry:TriggerEvent(event, ...)
			for owner, fn in pairs(registry.calls[event] or {}) do
				local inside = W.inBlizzard
				W.inBlizzard = 0
				local ok, err = pcall(fn, owner, ...)
				W.inBlizzard = inside
				if not ok then
					error(err, 0)
				end
			end
		end
		env.EventRegistry = registry
		W.registry = registry
	end
	-- A Lua function of Blizzard's: only the game may call it.
	local function lua(name, fn)
		return function(...)
			if W.inBlizzard == 0 then
				bad(W, "the addon called the Blizzard function " .. name)
			end
			return fn(...)
		end
	end
	local function frame(parent, name, more)
		more = more or {}
		more.name = name
		more.forbidden = name ~= nil and spec.forbidden ~= nil and spec.forbidden[name] or nil
		local proxy, r = W.B(parent, nil, more)
		r.fname = name or "?"
		if name then
			env[name] = proxy
		end
		return proxy, r
	end
	local function region(owner, name, key, more)
		more = more or {}
		more.name = name
		local proxy, r = W.Rr(owner, more.atlas, more)
		local o = rawOf[owner]
		o.regions[#o.regions + 1] = proxy
		if key then
			o[key] = proxy
		end
		if name then
			env[name] = proxy
		end
		return proxy, r
	end

	W.windows = {}
	local function window(i)
		local name = "ChatFrame" .. i
		local f, fr = frame(ui, name, { width = 430, height = 120 })
		local w = { name = name, frame = f, raw = fr, art = {}, plates = {} }
		w.bg, w.bgRaw = region(f, name .. "Background", "Background")
		w.bgRaw.alpha = 0.25
		w.art[1] = w.bg
		for _, part in ipairs(BORDER) do
			local r, rr = region(f, name .. part)
			rr.alpha = 0.25
			w.art[#w.art + 1] = r
		end
		local bf, bfr = frame(f, name .. "ButtonFrame")
		bfr.alpha = 0.2
		fr.buttonFrame = bf
		local plate, plateRaw = region(bf, name .. "ButtonFrameBackground", "Background")
		plateRaw.alpha = 0.25
		w.plates[1] = plate
		for _, part in ipairs(BORDER) do
			local r, rr = region(bf, name .. "ButtonFrame" .. part)
			rr.alpha = 0.25
			w.plates[#w.plates + 1] = r
		end
		w.minimize = frame(bf, name .. "ButtonFrameMinimizeButton", { objectType = "Button" })
		w.tab, w.tabRaw = frame(ui, name .. "Tab", { objectType = "Button" })
		w.tabRaw.alpha = 0.4
		for _, key in ipairs(TAB_ART) do
			region(w.tab, nil, key, { hidden = key:find("^Active") ~= nil })
		end
		for _, key in ipairs(TAB_LIGHT) do
			region(w.tab, nil, key)
		end
		region(w.tab, nil, "glow", { hidden = true })
		w.label = region(w.tab, nil, "label", { kind = "FontString" })
		w.tabRaw.GetFontString = function() return w.label end
		w.box, w.boxRaw = frame(ui, name .. "EditBox", { objectType = "EditBox", hidden = true })
		fr.editBox = w.box
		w.boxArt = {}
		for _, suffix in ipairs({ "Left", "Mid", "Right" }) do
			w.boxArt[#w.boxArt + 1] = region(w.box, name .. "EditBox" .. suffix)
		end
		for _, key in ipairs(FOCUS) do
			region(w.box, nil, key, { hidden = true })
		end
		local br = w.boxRaw
		br.SetFocusRegionsShown = lua("SetFocusRegionsShown", function(_, shown)
			for _, key in ipairs(FOCUS) do
				br[key]:SetShown(shown)
			end
		end)
		-- The colour call is made worse than the game's: it gives the region its alpha back.
		br.SetFocusRegionVertexColors = lua("SetFocusRegionVertexColors", function(_, colour)
			if rawequal(colour, SECRET) then
				return
			end
			for _, key in ipairs(FOCUS) do
				br[key]:SetVertexColor(colour.r, colour.g, colour.b)
				rawOf[br[key]].alpha = 1
			end
		end)
		W.windows[i] = w
		return w
	end
	if not spec.noChat then
		env.CHAT_FRAMES = {}
		for i = 1, spec.windows or 2 do
			env.CHAT_FRAMES[i] = window(i).name
		end
		env.FCF_FadeInChatFrame = lua("FCF_FadeInChatFrame", function() end)
		env.FCF_FadeOutChatFrame = lua("FCF_FadeOutChatFrame", function() end)
		-- The selected pieces are shown and tinted; the tint call gives their alpha back.
		env.FCFTab_UpdateColors = lua("FCFTab_UpdateColors", function(tab, selected)
			local t = rawOf[tab]
			for _, key in ipairs({ "ActiveLeft", "ActiveMiddle", "ActiveRight" }) do
				t[key]:SetShown(selected)
				t[key]:SetVertexColor(1, 0.5, 0.25)
				rawOf[t[key]].alpha = 1
			end
			for _, key in ipairs(TAB_LIGHT) do
				t[key]:SetVertexColor(1, 0.5, 0.25)
			end
		end)
		-- The tab alerts: ChatFrameUtil answers IsTabAlerting, and SetTabAlphas is counted (the addon must never call it).
		W.alerting, W.setTabAlphas = {}, 0
		env.ChatFrameUtil = {
			IsTabAlerting = function(tab) return W.alerting[tab] == true end,
			SetTabAlphas = function() W.setTabAlphas = W.setTabAlphas + 1 end,
		}
		for _, name in ipairs({ "FCF_StartAlertFlash", "FCF_StopAlertFlash" }) do
			env[name] = lua(name, function(frame) W.alerting[env[frame:GetName() .. "Tab"]] = name == "FCF_StartAlertFlash" end)
		end
		env.FCF_OpenTemporaryWindow = lua("FCF_OpenTemporaryWindow", function()
			local w = window(#W.windows + 1)
			env.CHAT_FRAMES[#env.CHAT_FRAMES + 1] = w.name
			env.FCFTab_UpdateColors(w.tab, false)
			return w.frame
		end)
		for i, w in ipairs(W.windows) do
			W.blizzard(function() env.FCFTab_UpdateColors(w.tab, i == 1) end)
		end
	end

	W.tips = {}
	if not spec.noTips then
		for _, name in ipairs(TIPS) do
			local t, tr = frame(ui, name, { hidden = true, width = 200, height = 100 })
			if name == "GameTooltip" then
				-- HookScript: the scripts run after the game's call, as the addon's code. hkchat: W.tipHooks counts the hooks put on the scripts.
				tr.hooks, W.tipHooks = { OnShow = {}, OnHide = {} }, 0
				function tr.HookScript(_, which, fn)
					if tr.hooks[which] == nil or type(fn) ~= "function" then
						bad(W, "HookScript arguments")
					end
					tr.hooks[which][#tr.hooks[which] + 1] = fn
					W.tipHooks = W.tipHooks + 1
				end
				local show = tr.Show
				function tr.Show(...)
					local was = tr.shown
					show(...)
					if not was then
						for _, fn in ipairs(tr.hooks.OnShow) do
							local inside = W.inBlizzard
							W.inBlizzard = 0
							local ok, err = pcall(fn, t)
							W.inBlizzard = inside
							if not ok then
								error(err, 0)
							end
						end
					end
				end
			end
			local line, lr = region(t, name .. "TextLeft1", "TextLeft1", { kind = "FontString" })
			lr.textColour = { 1, 1, 1 }
			function lr.GetTextColor()
				if lr.textFault then
					return SECRET, SECRET, SECRET
				end
				return unpack(lr.textColour)
			end
			local rec = { frame = t, raw = tr, name = name, line = line, lineRaw = lr, pieces = {}, lines = {} }
			-- The lines of the tooltip: the game's, then the addon's. rec.fault makes NumLines or AddLine raise.
			function tr.NumLines()
				if rec.fault == "NumLines" then
					error("NumLines failed", 0)
				end
				return #rec.lines
			end
			function tr.AddLine(_, text, r, g, b, wrap)
				if rec.fault == "AddLine" then
					error("AddLine failed", 0)
				end
				if type(text) ~= "string" or (r ~= nil and not isnum(r)) or (g ~= nil and not isnum(g)) or (b ~= nil and not isnum(b)) or wrap ~= nil then
					bad(W, "AddLine: a text and a colour are expected")
				end
				rec.lines[#rec.lines + 1] = { text = text, r = r, g = g, b = b }
			end
			if not spec.bareTips then
				local slice = frame(t, nil)
				tr.NineSlice = slice
				for _, key in ipairs(PIECES) do
					rec.pieces[#rec.pieces + 1] = region(slice, nil, key)
				end
				if name:find("Shopping") then
					local header = frame(t, nil, { hidden = true })
					tr.CompareHeader = header
					rec.plate = region(header, nil, nil, { atlas = "tooltip-compare-label" })
					region(header, nil, "Label", { kind = "FontString" })
					rec.header = header
				end
			end
			if name == "GameTooltip" and not spec.noBar then
				local bar, br = frame(t, "GameTooltipStatusBar", { objectType = "StatusBar", hidden = true, height = 8 })
				tr.StatusBar = bar
				local fill, fr = region(bar, nil, nil, { layer = "ARTWORK" })
				fr.file = BAR_FILE
				br.tint = { 0, 1, 0, 1 }
				function br.GetStatusBarTexture() return fill end
				function br.SetStatusBarTexture(_, asset)
					if type(asset) ~= "string" then
						bad(W, "SetStatusBarTexture: an asset name is expected")
					end
					fr.color = nil
					if asset:find("[\\/]") then
						fr.atlas, fr.file = nil, asset
					else
						fr.atlas, fr.file = asset, nil
					end
					return true
				end
				function br.SetColorFill(_, r, g, b, a)
					fr.color, fr.atlas, fr.file = { r, g, b, a }, nil, nil
				end
				function br.SetStatusBarColor(_, r, g, b) br.tint = { r, g, b, 1 } end
				function br.GetStatusBarColor() return unpack(br.tint) end
				rec.bar, rec.barRaw, rec.fill, rec.fillRaw = bar, br, fill, fr
			end
			W.tips[name] = rec
		end
		if not spec.bareTips then
			-- SetCenterColor(r, g, b, 1) gives the centre its alpha back.
			env.SharedTooltip_SetBackdropStyle = lua("SharedTooltip_SetBackdropStyle", function(tooltip)
				local slice = rawOf[tooltip].NineSlice
				slice:Show()
				rawOf[rawOf[slice].Center].alpha = 1
			end)
		end
		if not spec.noData then
			W.postCalls = {}
			W.lineCalls = {}
			env.TooltipDataProcessor = { AllTypes = "ALL", AddTooltipPostCall = function(kind, fn) W.postCalls[#W.postCalls + 1] = { kind, fn } end,
				AddLinePostCall = function(kind, fn) W.lineCalls[#W.lineCalls + 1] = { kind, fn } end }
			env.Enum = { TooltipDataType = { Item = 0, Spell = 1, Unit = 2 }, TooltipDataLineType = { UnitName = 17 } }
		end
		-- W.mob(guid, class, more) makes a unit the client knows: more.token, more.class and more.boss are what the three functions give for it,
		-- and a value of SECRET is a value the client withholds. more.fails makes UnitClassification raise for it.
		W.mobs, W.tokens = {}, {}
		local made = 0
		function W.mob(guid, class, more)
			made = made + 1
			local mob = { token = "nameplate" .. made, class = class, boss = false }
			for k, v in pairs(more or {}) do
				mob[k] = v
			end
			W.mobs[guid] = mob
			if type(mob.token) == "string" then
				W.tokens[mob.token] = mob
			end
			return guid
		end
		local function known(fn, unit)
			if type(unit) ~= "string" then
				bad(W, fn .. ": a unit token is expected")
			end
			return W.tokens[unit]
		end
		env.UnitTokenFromGUID = function(guid)
			if type(guid) ~= "string" then
				bad(W, "UnitTokenFromGUID: a guid is expected")
			end
			local mob = W.mobs[guid]
			return mob and mob.token
		end
		env.UnitClassification = function(unit)
			local mob = known("UnitClassification", unit)
			if mob and mob.fails then
				error("UnitClassification failed", 0)
			end
			return mob and mob.class or "normal"
		end
		env.UnitIsBossMob = function(unit)
			local mob = known("UnitIsBossMob", unit)
			return mob and mob.boss or false
		end
	end
	W.group = "static"
	W.seal()

	function W.game(name, ...)
		local args, n = { ... }, select("#", ...)
		W.blizzard(function() env[name](unpack(args, 1, n)) end)
	end
	-- The game fills a tooltip from data: it clears the lines and adds its own (two, or as many as `lines` says), the first line gets its colour,
	-- then the post calls run as the addon's code.
	function W.fill(name, kind, colour, data, lines)
		local rec = W.tips[name]
		rec.lineRaw.textColour = colour or { 1, 1, 1 }
		rec.lines = {}
		for i = 1, lines or 2 do
			rec.lines[i] = { text = "Line " .. i }
		end
		W.again(name, kind, data)
	end
	-- The post calls run again for the build the tooltip has.
	function W.again(name, kind, data)
		local rec = W.tips[name]
		local was = W.inBlizzard
		W.inBlizzard = 0
		for _, call in ipairs(W.postCalls) do
			call[2](rec.frame, data == nil and { type = kind } or data)
		end
		W.inBlizzard = was
	end
	function W.hideTip(name)
		W.game("SharedTooltip_SetBackdropStyle", W.tips[name].frame, nil, false)
	end
	function W.endCombat()
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
	end
	return W
end

local function started(spec)
	local W = world(spec)
	W.login()
	W.flush()
	return W
end
FH.chatStarted = started
FH.chatWorld = world
local function alphaOf(W, list)
	local out = {}
	for _, r in ipairs(list) do
		out[#out + 1] = g(W.rawOf[r].alpha)
	end
	return table.concat(out, ",")
end
local function shownOf(W, list)
	local out = {}
	for _, r in ipairs(list) do
		out[#out + 1] = W.rawOf[r].shown and "1" or "0"
	end
	return table.concat(out)
end
local function keyed(W, owner, keys)
	local out = {}
	for _, key in ipairs(keys) do
		out[#out + 1] = W.rawOf[owner][key]
	end
	return out
end
local function backAlpha(W, target)
	local back = W.backdropOn(target)
	return back and back.color and back.color[4]
end
local function edge(W, target)
	local o = W.look(target)
	return o and (string.format("%.2f,%.2f,%.2f", o.r, o.g, o.b)) or "none"
end
-- The frame of the addon's own that hangs from a frame.
local function childOf(W, parent)
	for _, f in ipairs(W.addonFrames) do
		if f.parent == parent then
			return f
		end
	end
end
local PLAIN = "0.00,0.00,0.00"
local ACCENT_EDGE = string.format("%.2f,%.2f,%.2f", ACCENT, ACCENT, ACCENT)
local QUARTER = "0.25,0.25,0.25,0.25,0.25,0.25,0.25,0.25,0.25"
local OPAQUE = "1,1,1,1,1,1,1,1,1"
local FADED = "0,0,0,0,0,0,0,0,0"

-- The background of a tooltip: a colour, an opacity and a shading of its own, on the box behind every tooltip the addon styles.
do
	local T = {
		names = { "Near black", "Black", "Dark blue", "Dark brown" },
		-- Red, green and blue of each colour in 255ths, written out here and not read from Chat.lua.
		colours = { ["Near black"] = { 15, 15, 15 }, ["Black"] = { 0, 0, 0 }, ["Dark blue"] = { 10, 20, 46 }, ["Dark brown"] = { 32, 22, 14 } },
		shadings = { "Flat", "Lighter at the top", "Darker at the bottom" },
		note = "the game cannot draw a gradient, so the tooltip background stays one colour",
	}
	function T.s(r, g, b, a)
		return string.format("%.3f,%.3f,%.3f,%.2f", r, g, b, a)
	end
	-- The box a colour, a shading and an opacity should give: one colour, or the colour at the top and at the bottom of a vertical gradient.
	-- Lighter at the top is the colour at the bottom and 12 percent of the way to white at the top. Darker at the bottom is the colour at the
	-- top and 30 percent of it at the bottom; a colour whose brightest channel is under 20 in 255ths (Black, Near black) has too little to lose
	-- for that to show, so its top is 8 percent of the way to white.
	function T.want(name, shading, alpha)
		local c = T.colours[name]
		local r, g, b = c[1] / 255, c[2] / 255, c[3] / 255
		local top, bottom = T.s(r, g, b, alpha), T.s(r, g, b, alpha)
		if shading == "Lighter at the top" then
			top = T.s(r + (1 - r) * 0.12, g + (1 - g) * 0.12, b + (1 - b) * 0.12, alpha)
		elseif shading == "Darker at the bottom" then
			if math.max(c[1], c[2], c[3]) < 20 then
				top = T.s(r + (1 - r) * 0.08, g + (1 - g) * 0.08, b + (1 - b) * 0.08, alpha)
			end
			bottom = T.s(r * 0.3, g * 0.3, b * 0.3, alpha)
		end
		if top == bottom then
			return "flat " .. top
		end
		return "top " .. top .. " bottom " .. bottom
	end
	-- What the box on a frame is. A gradient has to be vertical on a white base to count, and a gradient of one colour is one colour. A vertex
	-- colour that is not white would tint what is drawn.
	function T.has(W, target)
		local back = W.backdropOn(target)
		if not back or not back.color then
			return "none"
		end
		local v = back.vertex
		if v and (v[1] ~= 1 or v[2] ~= 1 or v[3] ~= 1 or v[4] ~= 1) then
			return "tinted " .. T.s(v[1], v[2], v[3], v[4])
		end
		local grad = back.gradient
		if not grad then
			return "flat " .. T.s(back.color[1], back.color[2], back.color[3], back.color[4])
		end
		local low, high = grad[2], grad[3]
		if grad[1] ~= "VERTICAL" or back.color[1] ~= 1 or back.color[2] ~= 1 or back.color[3] ~= 1 or back.color[4] ~= 1 then
			return "gradient " .. tostring(grad[1]) .. " on " .. T.s(back.color[1], back.color[2], back.color[3], back.color[4])
		end
		if low.r == high.r and low.g == high.g and low.b == high.b and low.a == high.a then
			return "flat " .. T.s(low.r, low.g, low.b, low.a)
		end
		return "top " .. T.s(high.r, high.g, high.b, high.a) .. " bottom " .. T.s(low.r, low.g, low.b, low.a)
	end
	-- The tooltips that do not have what is wanted, as "name: what they have".
	function T.wrong(W, want)
		local list = {}
		for _, name in ipairs(TIPS) do
			if T.has(W, W.tips[name].frame) ~= want then
				list[#list + 1] = name .. ": " .. T.has(W, W.tips[name].frame)
			end
		end
		return list
	end

	-- Every colour with every shading at the opacities given, on all six tooltips: the tooltips that are not as wanted, as text.
	function T.matrix(W, alphas)
		local list = {}
		for _, alpha in ipairs(alphas) do
			W.change("chat.tipOpacity", alpha)
			for _, colour in ipairs(T.names) do
				W.change("chat.tipBackground", colour)
				for _, shading in ipairs(T.shadings) do
					W.change("chat.tipShading", shading)
					for _, line in ipairs(T.wrong(W, T.want(colour, shading, alpha / 100))) do
						list[#list + 1] = alpha .. " " .. colour .. " " .. shading .. " " .. line
					end
				end
			end
		end
		return table.concat(list, "; ")
	end
	-- The top and the bottom of the gradient on a tooltip's box as { r, g, b } lists, or nil for one colour.
	function T.ends(W, target)
		local grad = W.backdropOn(target).gradient
		if not grad then
			return nil
		end
		return { grad[3].r, grad[3].g, grad[3].b }, { grad[2].r, grad[2].g, grad[2].b }
	end

	local W = started()
	local game, shop = W.tips.GameTooltip, W.tips.ShoppingTooltip1
	local plain = true
	for _, name in ipairs(TIPS) do
		plain = plain and W.backdropOn(W.tips[name].frame).gradient == nil
	end
	check("tipbg: every tooltip starts with the near black background at 70 percent opacity in one colour, which is no gradient, and the border is the plain one", #T.wrong(W, T.want("Near black", "Flat", 0.7)) == 0
		and plain and edge(W, game.frame) == PLAIN and W.look(game.frame).backShown, table.concat(T.wrong(W, T.want("Near black", "Flat", 0.7)), "; "))

	-- The three settings as the options list them: after the switch and before the item quality row, each needing the switch.
	local defs, order = {}, {}
	for _, page in ipairs(W.ns.PAGES) do
		for _, item in ipairs((page.key == "chat" or page.owner == "chat") and page or {}) do
			if item.key == "tooltips" or item.key == "quality" or (item.key and item.key:find("^tip[BOS][ahp]")) then
				order[#order + 1] = item.key
			end
			if item.key and item.key:find("^tip[BOS][ahp]") then
				local choices = {}
				for _, c in ipairs(item.choices or {}) do
					choices[#choices + 1] = c[1] .. "=" .. c[2]
				end
				defs[#defs + 1] = table.concat({ item.key, item.kind, tostring(item.default), item.label, tostring(item.needs), tostring(item.min), tostring(item.max), tostring(item.step),
					tostring(item.unit), tostring(item.tip), table.concat(choices, ",") }, "|")
			end
		end
	end
	check("tipbg: the page lists the background, the opacity and the shading after the switch, with their choices, range, unit and default, each needing the switch",
		table.concat(order, ",") == "tooltips,tipBackground,tipOpacity,tipShading,quality" and table.concat(defs, ";") ==
		"tipBackground|choice|nearblack|Tooltip background|tooltips|nil|nil|nil|nil|nil|nearblack=Near black,black=Black,darkblue=Dark blue,darkbrown=Dark brown;"
		.. "tipOpacity|number|70|Tooltip opacity|tooltips|40|100|5|%|nil|;"
		.. "tipShading|choice|flat|Tooltip shading|tooltips|nil|nil|nil|nil|nil|flat=Flat,lighter=Lighter at the top,darker=Darker at the bottom", table.concat(order, ",") .. " " .. table.concat(defs, ";"))

	local list = {}
	for _, name in ipairs(T.names) do
		W.change("chat.tipBackground", name)
		for _, line in ipairs(T.wrong(W, T.want(name, "Flat", 0.7))) do
			list[#list + 1] = name .. " " .. line
		end
	end
	check("tipbg: each background choice gives its colour to all six tooltips", #list == 0, table.concat(list, "; "))

	list = {}
	W.change("chat.tipBackground", "Near black")
	for _, alpha in ipairs({ 40, 55, 100, 70 }) do
		W.change("chat.tipOpacity", alpha)
		for _, line in ipairs(T.wrong(W, T.want("Near black", "Flat", alpha / 100))) do
			list[#list + 1] = alpha .. " " .. line
		end
	end
	check("tipbg: the opacity chosen is the alpha of the colour on all six tooltips, from 40 to 100 percent", #list == 0, table.concat(list, "; "))

	local matrix = T.matrix(W, { 85, 40 })
	check("tipbg: each shading of each colour at each opacity is Flat in one colour, a vertical gradient that is lighter at the top, or one that is darker at the bottom, on all six tooltips",
		matrix == "", matrix:sub(1, 400))
	-- Both shadings show on every colour, Black and Near black included: the top is lighter than the bottom in every channel, and by at least
	-- 7 percent of the range in the brightest. The two shadings are told apart on every colour: the top or the bottom of one is at least 9 in
	-- 255ths from that of the other in a channel.
	list = {}
	local apart = {}
	for _, colour in ipairs(T.names) do
		W.change("chat.tipBackground", colour)
		local ends = {}
		for _, shading in ipairs({ "Lighter at the top", "Darker at the bottom" }) do
			W.change("chat.tipShading", shading)
			local top, bottom = T.ends(W, game.frame)
			local widest, ordered = 0, false
			if top then
				widest = math.max(top[1] - bottom[1], top[2] - bottom[2], top[3] - bottom[3])
				ordered = top[1] > bottom[1] and top[2] > bottom[2] and top[3] > bottom[3]
			end
			if not (ordered and widest >= 0.07) then
				list[#list + 1] = colour .. " " .. shading .. " " .. string.format("%.3f", widest)
			end
			ends[#ends + 1] = { top = top, bottom = bottom }
		end
		local farthest = 0
		if ends[1].top and ends[2].top then
			for i = 1, 3 do
				farthest = math.max(farthest, math.abs(ends[1].top[i] - ends[2].top[i]), math.abs(ends[1].bottom[i] - ends[2].bottom[i]))
			end
		end
		if farthest < 9 / 255 then
			apart[#apart + 1] = colour .. " " .. string.format("%.3f", farthest)
		end
	end
	check("tipbg: Lighter at the top and Darker at the bottom both show on every colour, also on Black and Near black: the top is lighter than the bottom in every channel by 7 percent or more",
		#list == 0, table.concat(list, "; "))
	check("tipbg: Lighter at the top and Darker at the bottom are not the same box on any colour: the top or the bottom of one is 9 in 255ths or more from the other's in a channel",
		#apart == 0, table.concat(apart, "; "))
	check("tipbg: the border and the box's visibility are left alone by the shading", edge(W, game.frame) == PLAIN and W.state(game.frame) == "SB" and W.state(shop.frame) == "SB")

	-- A tooltip that is up has the new background at once, with no redraw by the game.
	W.change("chat.tipBackground", "Near black")
	W.change("chat.tipOpacity", 70)
	W.change("chat.tipShading", "Flat")
	W.fill("GameTooltip", 0, { 1, 1, 1 })
	W.rawOf[game.frame].shown = true
	W.change("chat.tipShading", "Lighter at the top")
	local lighter = T.has(W, game.frame) == T.want("Near black", "Lighter at the top", 0.7)
	W.change("chat.tipBackground", "Dark brown")
	local brown = T.has(W, game.frame) == T.want("Dark brown", "Lighter at the top", 0.7)
	W.change("chat.tipOpacity", 45)
	local faint = T.has(W, game.frame) == T.want("Dark brown", "Lighter at the top", 0.45)
	W.change("chat.tipShading", "Flat")
	check("tipbg: a tooltip that is up follows each change at once: the shading, the colour, the opacity, and Flat again", lighter and brown and faint
		and T.has(W, game.frame) == T.want("Dark brown", "Flat", 0.45), T.has(W, game.frame))

	-- The game draws its own art again, and a general setting repaints every box: the background chosen stays.
	W.change("chat.tipShading", "Darker at the bottom")
	W.game("SharedTooltip_SetBackdropStyle", game.frame, nil, false)
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	local redrawn = T.has(W, game.frame) == T.want("Dark brown", "Darker at the bottom", 0.45)
	W.change("general.backdrop", "ff804020")
	W.change("general.backdropAlpha", 20)
	W.change("general.thickness", 2)
	check("tipbg: the game's redraw and the general background, opacity and thickness leave the tooltip background as chosen", redrawn
		and #T.wrong(W, T.want("Dark brown", "Darker at the bottom", 0.45)) == 0 and edge(W, game.frame) ~= "none", T.has(W, game.frame))
	W.change("general.thickness", 1)
	W.change("general.backdrop", "ff0f0f0f")
	W.change("general.backdropAlpha", 85)

	-- The label above a comparison tooltip is one colour at the same opacity, whatever the shading.
	check("tipbg: the label above a comparison tooltip has the colour and the opacity chosen and no gradient, and the other tooltips have no label",
		T.has(W, shop.header) == T.want("Dark brown", "Flat", 0.45) and W.backdropOn(shop.header).gradient == nil and game.header == nil and W.backdropOn(W.tips.ItemRefTooltip.frame) ~= nil,
		T.has(W, shop.header))

	-- Nothing is made and no layout is touched while a tooltip is up in combat.
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.combat = true
	W.change("chat.tipBackground", "Dark blue")
	W.change("chat.tipOpacity", 90)
	W.change("chat.tipShading", "Lighter at the top")
	local combat = #T.wrong(W, T.want("Dark blue", "Lighter at the top", 0.9)) == 0
	W.change("chat.tipShading", "Flat")
	combat = combat and #T.wrong(W, T.want("Dark blue", "Flat", 0.9)) == 0
	W.combat = false
	check("tipbg: in combat each change reaches every tooltip with texture calls only, and nothing is made", combat and #W.addonFrames == frames and #W.addonTextures == textures
		and #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"))

	-- Off: the game's art is back and the box is hidden; on again: the background chosen is back, shaded as before.
	W.change("chat.tipShading", "Darker at the bottom")
	W.change("chat.tooltips", false)
	local hidden = true
	for _, name in ipairs(TIPS) do
		hidden = hidden and W.state(W.tips[name].frame) == "hb" and alphaOf(W, W.tips[name].pieces) == OPAQUE
	end
	hidden = hidden and W.state(shop.header) == "hb"
	W.change("chat.tooltips", true)
	check("tipbg: with the tooltip switch off every box and label is hidden and the game's art is back, and on again the background is shaded as chosen",
		hidden and #T.wrong(W, T.want("Dark blue", "Darker at the bottom", 0.9)) == 0 and T.has(W, shop.header) == T.want("Dark blue", "Flat", 0.9)
		and W.state(game.frame) == "SB" and alphaOf(W, game.pieces) == FADED)
	W.change("chat.enabled", false)
	local part = W.state(game.frame) == "hb" and W.state(shop.frame) == "hb" and alphaOf(W, game.pieces) == OPAQUE and not W.backdropOn(game.frame).shown
	W.change("chat.enabled", true)
	check("tipbg: with Restyle chat and tooltips off the boxes are hidden and the game's art is back, and on again the background is as chosen", part
		and #T.wrong(W, T.want("Dark blue", "Darker at the bottom", 0.9)) == 0 and W.backdropOn(game.frame).shown)

	-- A shading back to Flat leaves one colour, also on a client where SetColorTexture does not clear a gradient.
	W.change("chat.tipShading", "Lighter at the top")
	W.change("chat.tipShading", "Flat")
	check("tipbg: Flat after a shading is one colour again", #T.wrong(W, T.want("Dark blue", "Flat", 0.9)) == 0, T.has(W, game.frame))

	-- A colour, an opacity and a shading chosen while the tooltips are off are the background when they are on again.
	W.change("chat.tooltips", false)
	W.change("chat.tipBackground", "Dark brown")
	W.change("chat.tipOpacity", 60)
	W.change("chat.tipShading", "Lighter at the top")
	W.change("chat.tooltips", true)
	check("tipbg: what was chosen while the tooltips were off is the background when they are on again, and the label above a comparison tooltip has the colour and the opacity",
		#T.wrong(W, T.want("Dark brown", "Lighter at the top", 0.6)) == 0 and T.has(W, shop.header) == T.want("Dark brown", "Flat", 0.6), T.has(W, game.frame))
	clean(W, "tooltip background")

	-- Saved settings are used when a tooltip is made after combat.
	local L = started({ combat = true, saved = { options = { ["chat.tipBackground"] = "darkblue", ["chat.tipOpacity"] = 90, ["chat.tipShading"] = "darker" } } })
	local early = #wowned(L, L.tips.GameTooltip.frame) == 0
	L.endCombat()
	L.flush()
	check("tipbg: a tooltip made after combat has the saved colour, opacity and shading", early and #T.wrong(L, T.want("Dark blue", "Darker at the bottom", 0.9)) == 0, T.has(L, L.tips.GameTooltip.frame))
	local V = started({ saved = { options = { ["chat.tipBackground"] = "purple", ["chat.tipOpacity"] = 5, ["chat.tipShading"] = "sideways" } } })
	check("tipbg: saved values that are not a choice or are out of range give the nearest value or the default", #T.wrong(V, T.want("Near black", "Flat", 0.4)) == 0, T.has(V, V.tips.GameTooltip.frame))

	-- A client that cannot draw a gradient shows one colour and says so once, in the status.
	local lines = {}
	for _, case in ipairs({ { "no SetGradient", { noGradient = true } }, { "no CreateColor", { noCreateColor = true } } }) do
		local N = started({ noGradient = case[2].noGradient, noCreateColor = case[2].noCreateColor, saved = { options = { ["chat.tipShading"] = "lighter", ["chat.tipBackground"] = "black" } } })
		local flat = #T.wrong(N, T.want("Black", "Flat", 0.7)) == 0
		local said = count(N.status(), T.note) == 1
		N.change("chat.tooltips", false)
		local off = not has(N.status(), T.note)
		N.change("chat.tooltips", true)
		N.change("chat.tipShading", "Darker at the bottom")
		local again = count(N.status(), T.note) == 1 and #T.wrong(N, T.want("Black", "Flat", 0.7)) == 0
		N.change("chat.tipShading", "Flat")
		if not (flat and said and off and again and not has(N.status(), T.note) and #N.errors == 0 and #N.violations == 0) then
			lines[#lines + 1] = case[1]
		end
	end
	check("tipbg: a client without SetGradient or without CreateColor draws one colour at the opacity chosen and says so once, says nothing while the tooltips are off, and Flat takes the line back", #lines == 0, table.concat(lines, ","))
	local F = started()
	F.gradientFault = true
	F.change("chat.tipShading", "Lighter at the top")
	local refused = #T.wrong(F, T.want("Near black", "Flat", 0.7)) == 0 and count(F.status(), T.note) == 1 and #F.errors == 0
	F.gradientFault = nil
	F.change("chat.tipShading", "Darker at the bottom")
	check("tipbg: a SetGradient that raises gives one colour and the line, and the next shading is drawn and takes the line back", refused
		and #T.wrong(F, T.want("Near black", "Darker at the bottom", 0.7)) == 0 and not has(F.status(), T.note) and #F.errors == 0, F.status())
	check("tipbg: the shaded tooltips count as before in the status", F.line("Chat and tooltips") == "Chat and tooltips: on, 13 styled", F.line("Chat and tooltips"))

	-- The documentation does not say which call takes a gradient off a texture. Where SetColorTexture does, a box that is made white and then
	-- given its gradient has it, and Flat after a shade is one colour.
	local C = started({ clearedBy = "SetColorTexture" })
	local cleared = T.matrix(C, { 70, 100 })
	C.change("chat.tipShading", "Lighter at the top")
	C.change("chat.tipShading", "Flat")
	check("tipbg: on a client where SetColorTexture takes a gradient off, each colour and shading at 70 and 100 percent is as wanted, and Flat after a shade is one colour",
		cleared == "" and #T.wrong(C, T.want("Dark brown", "Flat", 1)) == 0 and #C.errors == 0 and #C.violations == 0, cleared:sub(1, 400))

	-- A shade that was drawn and is then refused: one colour and the line, also where no call but SetVertexColor takes the gradient off.
	-- Flat while the client refuses is one colour without the line, and a shade that is drawn again takes the line back.
	local steps = {}
	for _, case in ipairs({ { "no call", nil }, { "SetColorTexture", "SetColorTexture" }, { "SetVertexColor", "SetVertexColor" } }) do
		local R = started({ clearedBy = case[2] })
		R.change("chat.tipBackground", "Dark blue")
		R.change("chat.tipShading", "Lighter at the top")
		local drawn = #T.wrong(R, T.want("Dark blue", "Lighter at the top", 0.7)) == 0 and not has(R.status(), T.note)
		R.gradientFault = true
		R.change("chat.tipShading", "Darker at the bottom")
		local said = count(R.status(), T.note) == 1
		-- Where no call takes a gradient off the texture the old one cannot be told from a new one, so the box is read only on the others.
		local one = case[2] == nil or #T.wrong(R, T.want("Dark blue", "Flat", 0.7)) == 0
		R.change("chat.tipShading", "Flat")
		local flat = not has(R.status(), T.note) and (case[2] == nil or #T.wrong(R, T.want("Dark blue", "Flat", 0.7)) == 0)
		R.change("chat.tipShading", "Lighter at the top")
		local again = count(R.status(), T.note) == 1
		R.gradientFault = nil
		R.change("chat.tipShading", "Darker at the bottom")
		local back = #T.wrong(R, T.want("Dark blue", "Darker at the bottom", 0.7)) == 0 and not has(R.status(), T.note)
		if not (drawn and said and one and flat and again and back and #R.errors == 0 and #R.violations == 0) then
			steps[#steps + 1] = case[1] .. ": " .. table.concat({ tostring(drawn), tostring(said), tostring(one), tostring(flat), tostring(again), tostring(back) }, "/")
		end
	end
	check("tipbg: a shade that was drawn and is then refused gives one colour and the line, Flat gives one colour without the line, and a shade that is drawn again takes the line back",
		#steps == 0, table.concat(steps, "; "))

	-- The client refuses the shade on one tooltip and draws it on the others: the line stays while there is one that is refused.
	local P = started()
	local refusing = P.tips.GameTooltip.frame
	P.gradientFault = function(region) return region == P.backdropOn(refusing) end
	P.change("chat.tipShading", "Lighter at the top")
	local others = true
	for _, name in ipairs(TIPS) do
		if name ~= "GameTooltip" then
			others = others and T.has(P, P.tips[name].frame) == T.want("Near black", "Lighter at the top", 0.7)
		end
	end
	local stays = count(P.status(), T.note) == 1 and T.has(P, refusing) == T.want("Near black", "Flat", 0.7)
	P.gradientFault = nil
	P.change("chat.tipShading", "Darker at the bottom")
	check("tipbg: the line stays while one tooltip refuses the shade and the others draw it, and goes when every tooltip has it", others and stays and not has(P.status(), T.note)
		and #T.wrong(P, T.want("Near black", "Darker at the bottom", 0.7)) == 0 and #P.errors == 0 and #P.violations == 0, P.status())
	P.gradientFault = function(region) return region == P.backdropOn(refusing) end
	P.change("chat.tipShading", "Lighter at the top")
	P.change("chat.tipShading", "Flat")
	check("tipbg: a tooltip that refused the shade and is then Flat takes the line back", not has(P.status(), T.note))

	-- The background of a profile is put on the tooltips that are up when the profile is switched to, copied, reset and imported.
	local function chosen()
		return { ["chat.tipBackground"] = "darkblue", ["chat.tipOpacity"] = 90, ["chat.tipShading"] = "darker" }
	end
	local exported = started({ saved = { options = chosen() } }).ns.ExportProfile()
	local Q = started({ saved = { profiles = { Default = { options = {}, movers = {} }, Other = { options = chosen(), movers = {} } }, profileOf = {} } })
	local seen = { T.has(Q, Q.tips.GameTooltip.frame) .. " " .. T.has(Q, Q.tips.ShoppingTooltip1.header) }
	for _, step in ipairs({ function() Q.ns.UseProfile("Other") end, function() Q.ns.UseProfile("Default") end, function() Q.ns.CopyProfile("Other") end,
		function() Q.ns.ResetProfile() end, function() Q.ns.ImportProfile(exported) end }) do
		step()
		Q.flush()
		seen[#seen + 1] = T.has(Q, Q.tips.GameTooltip.frame) .. " " .. T.has(Q, Q.tips.ShoppingTooltip1.header)
	end
	local standard = T.want("Near black", "Flat", 0.7) .. " " .. T.want("Near black", "Flat", 0.7)
	local picked = T.want("Dark blue", "Darker at the bottom", 0.9) .. " " .. T.want("Dark blue", "Flat", 0.9)
	check("tipbg: the colour, opacity and shading of a profile follow a switch of profile, a copy, a reset and an import, on the tooltips and the label above a comparison tooltip",
		table.concat(seen, "|") == table.concat({ standard, picked, standard, picked, standard, picked }, "|") and #Q.errors == 0 and #Q.violations == 0, table.concat(seen, "|"))

	-- A shaded tooltip with the border of a kind keeps its shade when the game redraws it and when it hides it.
	local K = started()
	K.mob("Creature-elite", "elite")
	K.mob("Creature-boss", "worldboss")
	K.change("chat.tipShading", "Lighter at the top")
	local kinds = {}
	for _, case in ipairs({ { "Creature-elite", "1.00,0.82,0.00" }, { "Creature-boss", "1.00,0.35,0.24" } }) do
		K.fill("GameTooltip", 2, nil, { type = 2, guid = case[1] })
		local bordered = edge(K, K.tips.GameTooltip.frame) == case[2]
		local shaded = T.has(K, K.tips.GameTooltip.frame) == T.want("Near black", "Lighter at the top", 0.7)
		K.hideTip("GameTooltip")
		if not (bordered and shaded and edge(K, K.tips.GameTooltip.frame) == PLAIN and T.has(K, K.tips.GameTooltip.frame) == T.want("Near black", "Lighter at the top", 0.7)) then
			kinds[#kinds + 1] = case[1]
		end
	end
	check("tipbg: a shaded tooltip with the border of an Elite or a Boss keeps its shade, and keeps it when the game hides the tooltip and the plain border is back",
		#kinds == 0 and #K.errors == 0 and #K.violations == 0, table.concat(kinds, ","))
end

-- Chat windows: one flat panel in place of the background and the border, the plates behind the buttons hidden, and the game's rule for the mouse.
do
	local W = started()
	local one, two = W.windows[1], W.windows[2]
	local c = W.backdropOn(one.bg).color
	check("chat window: a panel with a thin border replaces the background and the border, at 60% of the background colour, and the game's pieces keep their alpha",
		W.state(one.bg) == "SB" and W.state(two.bg) == "SB" and near(c[1], 15 / 255, 1e-3) and near(c[4], 0.6) and shownOf(W, one.art) == "000000000" and alphaOf(W, one.art) == QUARTER,
		W.state(one.bg))
	check("chat window: the plates behind the buttons are hidden with their alpha kept, and the buttons are left alone", shownOf(W, one.plates) == "000000000" and shownOf(W, two.plates) == "000000000"
		and alphaOf(W, one.plates) == QUARTER and W.rawOf[one.minimize].shown and W.rawOf[W.rawOf[one.frame].buttonFrame].alpha == 0.2)
	check("chat windows: the status counts a window, a tab and an input box each, and the tooltips", W.line("Chat and tooltips") == "Chat and tooltips: on, 13 styled", W.line("Chat and tooltips"))
	W.change("chat.opacity", 10)
	local rest = near(backAlpha(W, one.bg), 0.1) and near(backAlpha(W, two.bg), 0.1)
	W.game("FCF_FadeInChatFrame", one.frame)
	local over = near(backAlpha(W, one.bg), 0.25) and near(backAlpha(W, two.bg), 0.1)
	W.game("FCF_FadeOutChatFrame", one.frame)
	check("chat window mouse: the panel has the opacity chosen at rest, a quarter under the mouse, and the opacity chosen again after", rest and over and near(backAlpha(W, one.bg), 0.1))
	W.change("chat.opacity", 0)
	local none = W.state(one.bg) == "hb"
	W.game("FCF_FadeInChatFrame", one.frame)
	local shown = W.state(one.bg) == "SB" and near(backAlpha(W, one.bg), 0.25)
	W.game("FCF_FadeOutChatFrame", one.frame)
	W.change("chat.opacity", 60)
	W.game("FCF_FadeInChatFrame", one.frame)
	check("chat window mouse: no opacity shows nothing at rest and a quarter under the mouse, and a window above a quarter keeps its opacity", none and shown and near(backAlpha(W, one.bg), 0.6))
	W.change("chat.buttons", false)
	local plates = shownOf(W, one.plates) == "111111111" and alphaOf(W, one.plates) == QUARTER and shownOf(W, one.art) == "000000000"
	W.change("chat.frames", false)
	local frames = shownOf(W, one.art) == "111111111" and W.state(one.bg) == "hb" and alphaOf(W, one.art) == QUARTER
	W.change("chat.frames", true)
	W.change("chat.buttons", true)
	check("chat window switches: each part gives the game's art back with its alpha, and takes it again", plates and frames and shownOf(W, one.art) == "000000000"
		and shownOf(W, one.plates) == "000000000" and W.state(one.bg) == "SB")
	clean(W, "chat windows")
	local F = started()
	F.change("chat.enabled", false)
	local left = F.diff("chat")
	check("chat and tooltips off: everything the game drew has its alpha, visibility and fill back as it was", #left == 0 and F.state(F.windows[1].bg) == "hb"
		and F.state(F.tips.GameTooltip.frame) == "hb", table.concat(left, "; "):sub(1, 300))
	F.change("chat.enabled", true)
	check("chat and tooltips on again: styled as before, with nothing made twice", F.state(F.windows[1].bg) == "SB" and F.state(F.tips.GameTooltip.frame) == "SB"
		and F.line("Chat and tooltips") == "Chat and tooltips: on, 13 styled", F.line("Chat and tooltips"))
end

-- A window the game opens later, a window without a background, and frames the addon may not touch.
do
	local W = started()
	W.game("FCF_OpenTemporaryWindow")
	W.flush()
	local three = W.windows[3]
	check("temporary chat window: the panel, the plates, the tab and the input box are styled when the game opens it", W.state(three.bg) == "SB" and shownOf(W, three.plates) == "000000000"
		and childOf(W, three.tab) ~= nil and #wowned(W, three.box) == 5, W.state(three.bg))
	clean(W, "temporary chat window")
	local N = started({ forbidden = { ChatFrame2 = true, ItemRefTooltip = true } })
	check("forbidden frames are skipped whole and never read: a chat window with its tab and input box, and a tooltip", N.state(N.windows[1].bg) == "SB" and N.state(N.windows[2].bg) == "."
		and N.rawOf[N.windows[2].bgRaw].shown == true and childOf(N, N.windows[2].tab) == nil and N.state(N.tips.ItemRefTooltip.frame) == "." and N.state(N.tips.GameTooltip.frame) == "SB"
		and #N.violations == 0, table.concat(N.violations, "|"))
	local G = started({ forbidden = { GameTooltip = true } })
	check("a forbidden game tooltip is skipped with its health bar, and the other tooltips are styled", G.state(G.tips.GameTooltip.frame) == "." and G.state(G.tips.GameTooltip.bar) == "."
		and G.state(G.tips.ShoppingTooltip1.frame) == "SB" and #G.violations == 0, table.concat(G.violations, "|"))
	local M = world()
	M.env.ChatFrame1Background = nil
	M.login()
	M.flush()
	check("a chat window whose background is missing gets no panel, and the others are styled", M.state(M.windows[1].bg) == "." and M.state(M.windows[2].bg) == "SB" and #M.violations == 0 and #M.errors == 0)
end

-- Tabs: flat, with a box behind the label, and the selected tab marked by its border.
do
	local W = started()
	local one, two = W.windows[1], W.windows[2]
	local plate, plateTwo = childOf(W, one.tab), childOf(W, two.tab)
	check("chat tabs: the game's pieces are transparent, the highlight is hidden, the game still fades the tab, and a box with a thin border sits behind the label on the tab itself",
		alphaOf(W, keyed(W, one.tab, TAB_ART)) == "0,0,0,0,0,0" and shownOf(W, keyed(W, one.tab, TAB_LIGHT)) == "000" and W.rawOf[one.tab].alpha == 0.4
		and W.state(plate) == "SB" and plate.height == 22 and #wowned(W, one.tab) == 6)
	local first = edge(W, plate) == ACCENT_EDGE and edge(W, plateTwo) == PLAIN
	W.game("FCFTab_UpdateColors", one.tab, false)
	W.game("FCFTab_UpdateColors", two.tab, true)
	check("chat tabs: the selected tab has the highlight colour for its border, the border follows the game's selection, and the selected pieces stay transparent",
		first and edge(W, plate) == PLAIN and edge(W, plateTwo) == ACCENT_EDGE and alphaOf(W, keyed(W, two.tab, TAB_ART)) == "0,0,0,0,0,0", edge(W, plateTwo))
	W.rawOf[two.tab].selectedColorTable = { r = 1, g = 0.5, b = 1 }
	W.game("FCFTab_UpdateColors", two.tab, true)
	local whisper = edge(W, plateTwo) == "1.00,0.50,1.00"
	W.rawOf[two.tab].selectedColorTable = SECRET
	W.game("FCFTab_UpdateColors", two.tab, true)
	check("chat tabs: a whisper tab keeps the colour the game gave it, and a colour the game withholds gives the highlight colour", whisper and edge(W, plateTwo) == ACCENT_EDGE and #W.errors == 0)
	local hover
	for _, t in ipairs(wowned(W, one.tab)) do
		if t.layer == "HIGHLIGHT" then
			hover = t
		end
	end
	check("chat tabs: the mouse over a tab tints it with the highlight colour", hover ~= nil and hover.shown and hover.allPoints == plate and near(hover.color[1], ACCENT, 1e-3) and near(hover.color[4], 0.25))
	W.change("chat.tabs", false)
	W.game("FCFTab_UpdateColors", one.tab, true)
	check("chat tabs off: the pieces are back, the box and the tint are hidden, and a tab the game colours later stays as the game draws it", alphaOf(W, keyed(W, one.tab, TAB_ART)) == "1,1,1,1,1,1"
		and shownOf(W, keyed(W, one.tab, TAB_LIGHT)) == "111" and W.state(plate) == "hb" and not hover.shown)
	clean(W, "chat tabs")
	local S = world()
	S.rawOf[S.rawOf[S.windows[1].tab].ActiveMiddle].fault.shown = "secret"
	S.login()
	S.flush()
	check("chat tabs: whether a tab is selected can be withheld, and the tab is styled without a mark", S.state(childOf(S, S.windows[1].tab)) == "SB" and edge(S, childOf(S, S.windows[1].tab)) == PLAIN and #S.errors == 0)
end

-- Chat tab opacity: the label and the flat box take their own alpha; the game's alpha for the tab and its stored pair are left alone.
do
	local T = {}
	function T.look(W, w)
		local function one(r) return (r.ignoreParentAlpha and "i" or "-") .. string.format("%.1f", r.alpha or 1) end
		local out = one(W.rawOf[w.label])
		for _, t in ipairs(wowned(W, w.tab)) do
			if t.layer ~= "HIGHLIGHT" and one(t) ~= out then
				return "mixed " .. out .. " " .. one(t)
			end
		end
		return out
	end
	function T.both(W) return T.look(W, W.windows[1]) .. " " .. T.look(W, W.windows[2]) end
	local W = started()
	local one, two = W.windows[1], W.windows[2]
	check("chat tab opacity: by default the selected tab is at 1.0 and the other at 0.6, with the game's alpha ignored", T.both(W) == "i1.0 i0.6", T.both(W))
	W.game("FCF_StartAlertFlash", two.frame)
	local alert = T.look(W, two)
	W.game("FCF_StopAlertFlash", two.frame)
	check("chat tab opacity: a tab that flashes is at 1.0 and goes back to 0.6 when the flash stops", alert == "i1.0" and T.look(W, two) == "i0.6", alert .. " " .. T.look(W, two))
	W.game("FCFTab_UpdateColors", one.tab, false)
	W.game("FCFTab_UpdateColors", two.tab, true)
	check("chat tab opacity: the alpha follows the selected tab", T.both(W) == "i0.6 i1.0", T.both(W))
	W.change("chat.tabOpacity", "All 100%")
	check("chat tab opacity: All 100% puts every tab at 1.0", T.both(W) == "i1.0 i1.0", T.both(W))
	W.change("chat.tabOpacity", "As the game has it")
	check("chat tab opacity: As the game has it gives back the game's alpha, and the game's own tab alpha is the one it set", T.both(W) == "-1.0 -1.0" and W.rawOf[one.tab].alpha == 0.4,
		T.both(W) .. " " .. tostring(W.rawOf[one.tab].alpha))
	W.change("chat.tabOpacity", "Selected 100%, others 60%")
	W.change("chat.tabs", false)
	local off = T.both(W)
	W.game("FCF_StartAlertFlash", one.frame)
	check("chat tab opacity: with Chat tabs off the alpha is the game's, and a flash writes nothing", off == "-1.0 -1.0" and T.both(W) == "-1.0 -1.0", off .. " " .. T.both(W))
	check("chat tab opacity: the row needs Chat tabs and starts on Selected 100%, others 60%", W.ns.Def("chat.tabOpacity").needs == "tabs" and W.ns.Def("chat.tabOpacity").default == "clear")
	check("chat tab opacity: ChatFrameUtil.SetTabAlphas is never called", W.setTabAlphas == 0, W.setTabAlphas)
	clean(W, "chat tab opacity")
	local N = started({ saved = { options = { ["chat.tabs"] = false } } })
	local writes = 0
	for _, w in ipairs(N.windows) do
		writes = writes + (N.rawOf[w.label].calls.SetAlpha or 0) + (N.rawOf[w.label].ignoreParentAlpha ~= nil and 1 or 0)
	end
	check("chat tab opacity: with Chat tabs off from the start nothing is written to a label", writes == 0 and #N.errors == 0, writes)
	local B = started()
	local lab = B.rawOf[B.windows[2].label]
	lab.SetIgnoreParentAlpha = function() error("withheld") end
	local before = lab.calls.SetAlpha or 0
	B.change("chat.tabOpacity", "All 100%")
	check("chat tab opacity: a label whose ignore call fails gets no alpha, and the box behind it still changes",
		(lab.calls.SetAlpha or 0) == before and lab.alpha ~= 1 and #B.errors == 0 and #B.violations == 0 and T.look(B, B.windows[2]):find("mixed", 1, true) ~= nil, T.look(B, B.windows[2]))
	local F = started({ forbidden = { ChatFrame2 = true } })
	check("chat tab opacity: a forbidden window is skipped and the other tab is styled", T.look(F, F.windows[1]) == "i1.0" and F.rawOf[F.windows[2].label].ignoreParentAlpha == nil
		and #F.violations == 0 and #F.errors == 0)
end

-- The input box: the game's art is transparent, a flat box is drawn on the box itself, and its border takes the colour of the focus art.
do
	local W = started()
	local one, two = W.windows[1], W.windows[2]
	check("chat input box: its art is transparent, and a box with a thin border is drawn on it, so it shows and hides with it, with no frame made on it",
		alphaOf(W, one.boxArt) == "0,0,0" and alphaOf(W, keyed(W, one.box, FOCUS)) == "0,0,0" and W.state(one.box) == "SB" and #wowned(W, one.box) == 5 and #W.rawOf[one.box].children == 0)
	W.blizzard(function() one.box:SetFocusRegionsShown(true) end)
	W.blizzard(function() one.box:SetFocusRegionVertexColors({ r = 0.5, g = 0.8, b = 1 }) end)
	W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusGained", one.box)
	W.flush()
	local typing = edge(W, one.box) == "0.50,0.80,1.00" and alphaOf(W, keyed(W, one.box, FOCUS)) == "0,0,0" and edge(W, two.box) == PLAIN
	W.blizzard(function() one.box:SetFocusRegionsShown(false) end)
	W.blizzard(function() one.box:SetFocusRegionVertexColors({ r = 1, g = 1, b = 1 }) end)
	W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", one.box)
	W.flush()
	check("chat input box: typing gives the border the colour of the chat type and the focus pieces stay transparent; when it ends the plain border is back", typing and edge(W, one.box) == PLAIN
		and alphaOf(W, keyed(W, one.box, FOCUS)) == "0,0,0")
	W.blizzard(function() one.box:SetFocusRegionsShown(true) end)
	local artRaw = W.rawOf[one.boxRaw.focusLeft]
	local getColour = artRaw.GetVertexColor
	artRaw.GetVertexColor = function() return SECRET, SECRET, SECRET, SECRET end
	W.blizzard(function() one.box:SetFocusRegionVertexColors({ r = 1, g = 1, b = 1 }) end)
	W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusGained", one.box)
	W.flush()
	check("chat input box: a colour the game withholds gives the plain border", edge(W, one.box) == PLAIN and #W.errors == 0)
	artRaw.GetVertexColor = getColour
	W.change("chat.editbox", false)
	W.blizzard(function() one.box:SetFocusRegionVertexColors({ r = 0.5, g = 0.8, b = 1 }) end)
	check("chat input box off: the pieces are back, the box is hidden, and what the game sets later changes nothing", alphaOf(W, one.boxArt) == "1,1,1" and W.state(one.box) == "hb"
		and alphaOf(W, keyed(W, one.box, FOCUS)) == "1,1,1" and edge(W, one.box) == PLAIN)
	clean(W, "chat input box")
end

-- Tooltips: the nine pieces are transparent, one flat box replaces them, and the game's own redraw is followed.
do
	local W = started()
	local game, shop = W.tips.GameTooltip, W.tips.ShoppingTooltip1
	local all = true
	for _, name in ipairs(TIPS) do
		local rec = W.tips[name]
		all = all and W.state(rec.frame) == "SB" and alphaOf(W, rec.pieces) == FADED
	end
	check("tooltips: the game tooltip, the item link tooltip and the comparison tooltips have transparent art and a box with a thin border made of textures on the tooltip, with no frame",
		all and #wowned(W, game.frame) == 5 and childOf(W, game.frame) == nil)
	W.game("SharedTooltip_SetBackdropStyle", game.frame, nil, false)
	check("tooltips: the game draws its centre again when it sets the backdrop style, and it is transparent again at once", alphaOf(W, game.pieces) == FADED)
	check("comparison tooltips: the label above them loses its picture and gets a thin border, and the other tooltips have none", alphaOf(W, { shop.plate }) == "0" and W.state(shop.header) == "SB"
		and game.header == nil)
	W.fill("GameTooltip", 0, { 0.12, 1, 0 })
	local item = edge(W, game.frame) == "0.12,1.00,0.00"
	W.fill("ShoppingTooltip1", 0, { 0.64, 0.21, 0.93 })
	local own = edge(W, shop.frame) == "0.64,0.21,0.93" and edge(W, game.frame) == "0.12,1.00,0.00"
	W.fill("GameTooltip", 0, { 0.62, 0.62, 0.62 })
	local grey = edge(W, game.frame) == PLAIN
	W.fill("GameTooltip", 0, { 0, 0.44, 0.87 })
	W.fill("GameTooltip", 1, { 1, 0.82, 0 })
	check("tooltip quality: an item takes the colour of its name for the border, each tooltip its own, grey names and anything that is not an item the plain border",
		item and own and grey and edge(W, game.frame) == PLAIN, edge(W, game.frame))
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	W.hideTip("GameTooltip")
	check("tooltip quality: hiding the tooltip clears the style and the border with it", edge(W, game.frame) == PLAIN and edge(W, shop.frame) == "0.64,0.21,0.93")
	W.fill("GameTooltip", 0, { 1, 0.5, 0 }, SECRET)
	local data = edge(W, game.frame) == PLAIN
	W.rawOf[game.line].textFault = true
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	check("tooltip quality: data the game withholds, or a name colour it withholds, gives the plain border", data and edge(W, game.frame) == PLAIN and #W.errors == 0)
	W.rawOf[game.line].textFault = nil
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	W.change("chat.quality", false)
	local plain = edge(W, game.frame) == PLAIN
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	check("tooltip quality off: the border is plain, and an item filled later changes nothing", plain and edge(W, game.frame) == PLAIN and W.state(game.frame) == "SB")
	W.change("chat.tooltips", false)
	W.game("SharedTooltip_SetBackdropStyle", game.frame, nil, false)
	check("tooltips off: the pieces have their alpha, the boxes are hidden, and the game's redraw is not followed", alphaOf(W, game.pieces) == OPAQUE and W.state(game.frame) == "hb"
		and W.state(shop.header) == "hb" and alphaOf(W, { shop.plate }) == "1")
	clean(W, "tooltips")
end

-- The kind of a unit on a tooltip: a line with the word at the end and a border in the same colour, each with a setting of its own.
do
	local W = started()
	local game = W.tips.GameTooltip
	local G = {}
	for guid, class in pairs({ elite = "elite", rare = "rare", rareelite = "rareelite", worldboss = "worldboss", normal = "normal", minus = "minus", trivial = "trivial" }) do
		G[guid] = W.mob("Creature-" .. guid, class)
	end
	G.boss = W.mob("Creature-boss", "elite", { boss = true })
	G.player = W.mob("Player-1", "normal")
	-- The game fills the tooltip with a unit, and the last line it has as "Word r,g,b" (a line of the game's is its text alone).
	local function show(guid, name, data, lines)
		W.fill(name or "GameTooltip", 2, nil, data or { type = 2, guid = guid }, lines)
	end
	local function last(name)
		local all = W.tips[name or "GameTooltip"].lines
		local l = all[#all]
		return l.r and string.format("%s %.2f,%.2f,%.2f", l.text, l.r, l.g, l.b) or l.text
	end
	local function lines(name)
		return #W.tips[name or "GameTooltip"].lines
	end
	local GOLD, SILVER, RED = "1.00,0.82,0.00", "0.78,0.80,0.84", "1.00,0.35,0.24"
	local function says(word, colour)
		return last() == word .. " " .. colour and lines() == 3 and edge(W, game.frame) == colour
	end
	local function nothing()
		return last() == "Line 2" and lines() == 2 and edge(W, game.frame) == PLAIN
	end

	show(G.elite)
	check("tooltip kind: an elite has the line Elite in gold at the end of the tooltip and a gold border", says("Elite", GOLD), last() .. " " .. edge(W, game.frame))
	show(G.rare)
	check("tooltip kind: a rare has the line Rare in silver and a silver border", says("Rare", SILVER), last() .. " " .. edge(W, game.frame))
	show(G.rareelite)
	check("tooltip kind: a rare elite has the line Rare Elite in silver and a silver border", says("Rare Elite", SILVER), last() .. " " .. edge(W, game.frame))
	show(G.worldboss)
	check("tooltip kind: a world boss has the line Boss in red and a red border", says("Boss", RED), last() .. " " .. edge(W, game.frame))
	show(G.boss)
	check("tooltip kind: a boss mob the game classes as an elite is a boss, not an elite", says("Boss", RED), last() .. " " .. edge(W, game.frame))
	show(G.normal)
	local normal = nothing()
	show(G.elite)
	show(G.minus)
	local minus = nothing()
	show(G.elite)
	show(G.trivial)
	check("tooltip kind: a normal unit, a minus mob and a trivial one get no line, and the border an elite had is plain again", normal and minus and nothing(), last() .. " " .. edge(W, game.frame))
	show(G.elite)
	show(G.player)
	check("tooltip kind: a player gets no line and a plain border", nothing(), last() .. " " .. edge(W, game.frame))
	show(G.elite)
	W.fill("GameTooltip", 0, { 0.12, 1, 0 })
	check("tooltip kind: an item gets no line, and takes its quality border in place of the gold", last() == "Line 2" and lines() == 2 and edge(W, game.frame) == "0.12,1.00,0.00", edge(W, game.frame))

	-- One line for a build: a second call for the same data adds none, a new build adds it again.
	local data = { type = 2, guid = G.elite }
	show(nil, nil, data)
	W.again("GameTooltip", 2, data)
	check("tooltip kind: the callback run twice for one build adds the line once", lines() == 3 and last() == "Elite " .. GOLD, lines())
	show(nil, nil, { type = 2, guid = G.elite })
	local rebuilt = lines() == 3 and last() == "Elite " .. GOLD
	show(nil, nil, data)
	show(nil, nil, data)
	check("tooltip kind: a rebuilt tooltip gets the line again, whether the game fetched new data or kept the old", rebuilt and lines() == 3 and last() == "Elite " .. GOLD, lines())
	show(nil, nil, { type = 2, guid = G.elite })
	show(nil, nil, { type = 2, guid = G.elite }, 3)
	check("tooltip kind: a build with a line more than the last one still gets its line", lines() == 4 and last() == "Elite " .. GOLD, lines())

	-- What the client withholds or refuses adds nothing and raises nothing.
	show(W.mob("Creature-hidden", "elite", { token = SECRET }))
	local token = nothing()
	show(nil, nil, { type = 2, guid = SECRET })
	local guid = nothing()
	show(nil, nil, { type = 2 })
	local none = nothing()
	show("Creature-unknown")
	check("tooltip kind: a unit the client does not name, or a guid it withholds or the data does not have, adds no line and keeps the plain border", token and guid and none and nothing(), last())
	show(W.mob("Creature-class", SECRET, { boss = true }))
	local class = nothing()
	W.secretType = "string"
	show(W.mob("Creature-classText", SECRET, { boss = true }))
	local text = nothing()
	W.secretType = nil
	show(W.mob("Creature-fails", "elite", { fails = true }))
	local fails = nothing()
	local classification = W.env.UnitClassification
	W.env.UnitClassification = nil
	show(G.elite)
	local missing = nothing()
	W.env.UnitClassification = classification
	check("tooltip kind: a classification the client withholds, as a secret string too, or refuses, or a client without UnitClassification, adds no line even for a boss flag", class and text and fails and missing and not W.ns.IsStopped("chat")
		and #W.errors == 0 and #W.violations == 0, last())
	show(W.mob("Creature-bossSecret", "elite", { boss = SECRET }))
	local flag = last() == "Elite " .. GOLD
	local isBoss = W.env.UnitIsBossMob
	W.env.UnitIsBossMob = nil
	show(G.elite)
	local elite = last() == "Elite " .. GOLD
	show(G.worldboss)
	W.env.UnitIsBossMob = isBoss
	check("tooltip kind: a boss flag the client withholds, or a client without UnitIsBossMob, leaves the classification to say what the unit is", flag and elite and last() == "Boss " .. RED and edge(W, game.frame) == RED, last())
	game.fault = "AddLine"
	show(G.elite)
	local refused = last() == "Line 2" and lines() == 2 and edge(W, game.frame) == GOLD
	game.fault = "NumLines"
	show(G.elite)
	local counted = lines() == 2
	game.fault = nil
	show(G.elite)
	check("tooltip kind: a tooltip that refuses the line, or cannot count its lines, raises nothing and keeps the border, and the next build has its line", refused and counted and says("Elite", GOLD)
		and #W.errors == 0 and #W.violations == 0 and not W.ns.IsStopped("chat"), last())

	-- Each setting alone, and the tooltip a player was looking at is right at its next build.
	W.change("chat.kindWord", false)
	show(G.elite)
	local border = lines() == 2 and edge(W, game.frame) == GOLD
	W.change("chat.kindWord", true)
	W.change("chat.kindBorder", false)
	show(G.elite)
	local word = last() == "Elite " .. GOLD and lines() == 3 and edge(W, game.frame) == PLAIN
	W.fill("GameTooltip", 0, { 0.12, 1, 0 })
	check("tooltip kind: with the line off the border stays, with the border off the line stays, and an item keeps its quality border either way", border and word
		and edge(W, game.frame) == "0.12,1.00,0.00" and lines() == 2)
	W.change("chat.kindBorder", true)
	W.change("chat.quality", false)
	show(G.worldboss)
	local apart = says("Boss", RED)
	W.fill("GameTooltip", 0, { 0.12, 1, 0 })
	check("tooltip kind: the item quality setting off leaves the kind of a unit alone, and an item then has the plain border", apart and edge(W, game.frame) == PLAIN)
	W.change("chat.quality", true)
	W.change("chat.kindWord", false)
	W.change("chat.kindBorder", false)
	show(G.elite)
	local off = nothing()
	W.fill("GameTooltip", 0, { 0.12, 1, 0 })
	check("tooltip kind: both settings off, a unit is left as the game made it and an item keeps its quality border", off and edge(W, game.frame) == "0.12,1.00,0.00")
	W.change("chat.kindWord", true)
	W.change("chat.kindBorder", true)
	W.change("chat.tooltips", false)
	show(G.elite)
	local tipsOff = nothing()
	W.change("chat.tooltips", true)
	W.change("chat.enabled", false)
	show(G.elite)
	local pageOff = nothing()
	W.change("chat.enabled", true)
	check("tooltip kind: with the tooltip look off or the whole page off, nothing is added", tipsOff and pageOff)
	show(G.elite)
	local shown = says("Elite", GOLD)
	W.change("chat.kindBorder", false)
	local cleared = edge(W, game.frame) == PLAIN and lines() == 3
	W.change("chat.kindBorder", true)
	W.change("chat.kindWord", false)
	local kept = lines() == 3
	show(G.elite)
	W.change("chat.kindWord", true)
	check("tooltip kind: a tooltip already shown loses its border when that setting goes off and keeps its line until the game builds it again, which has the settings",
		shown and cleared and kept and lines() == 2 and edge(W, game.frame) == GOLD)

	-- The plain border comes back when the game hides the tooltip, and a tooltip that is not a unit has the plain one.
	show(G.elite)
	W.hideTip("GameTooltip")
	check("tooltip kind: hiding the tooltip puts the plain border back", edge(W, game.frame) == PLAIN)
	show(G.rare)
	W.fill("GameTooltip", 1, { 1, 0.82, 0 })
	check("tooltip kind: a tooltip that is not a unit has no line and the plain border", nothing())

	-- Tooltips the addon may not touch, and one the game is using in combat.
	W.rawOf[W.tips.ShoppingTooltip1.frame].forbidden = true
	show(G.elite, "ShoppingTooltip1")
	local forbidden = lines("ShoppingTooltip1") == 2 and #W.violations == 0
	show(G.elite)
	check("tooltip kind: a tooltip that became forbidden is not touched, and the others still get the line", forbidden and says("Elite", GOLD) and #W.violations == 0, table.concat(W.violations, "|"))
	W.combat = true
	show(G.rare)
	W.combat = false
	check("tooltip kind: a styled tooltip gets the line in combat too", says("Rare", SILVER))
	clean(W, "tooltip kind")
	local F = started({ forbidden = { GameTooltip = true } })
	F.mob("Creature-elite", "elite")
	F.fill("GameTooltip", 2, nil, { type = 2, guid = "Creature-elite" })
	F.fill("ItemRefTooltip", 2, nil, { type = 2, guid = "Creature-elite" })
	check("tooltip kind: a forbidden game tooltip is left alone, and another tooltip is not held back by it", F.tips.GameTooltip.lines[3] == nil and #F.violations == 0
		and F.tips.ItemRefTooltip.lines[3] ~= nil and F.tips.ItemRefTooltip.lines[3].text == "Elite", table.concat(F.violations, "|"))
end

-- Tooltips are used by secure code: nothing is created on one in combat, and the game keeps its art until then.
do
	local W = started({ combat = true })
	local game = W.tips.GameTooltip
	local early = W.state(W.windows[1].bg) == "SB" and W.state(game.frame) == "." and alphaOf(W, game.pieces) == OPAQUE and #wowned(W, game.frame) == 0 and W.state(game.bar) == "."
	W.game("SharedTooltip_SetBackdropStyle", game.frame, nil, false)
	W.fill("GameTooltip", 0, { 1, 0.5, 0 })
	check("tooltips in combat: the chat windows are styled, a tooltip keeps the game's art and gets nothing made on it, and its hooks leave it alone", early and alphaOf(W, game.pieces) == OPAQUE
		and #W.errors == 0 and #W.violations == 0)
	W.endCombat()
	W.flush()
	check("tooltips after combat: the boxes are made, the art is transparent, and the health bar has its box", W.state(game.frame) == "SB" and alphaOf(W, game.pieces) == FADED
		and W.state(game.bar) == "SB" and W.line("Chat and tooltips") == "Chat and tooltips: on, 13 styled", W.line("Chat and tooltips"))
end

-- The health bar under a unit tooltip: a thin border, and a solid fill that the game's colour tints.
do
	local W = started()
	local game = W.tips.GameTooltip
	local frames, textures = #W.addonFrames, #W.addonTextures
	local fill = game.fillRaw
	check("tooltip health bar: a thin border with a box behind it, and a solid white fill so the game's green shows", W.state(game.bar) == "SB" and childOf(W, game.bar) ~= nil and fill.color
		and fill.color[1] == 1 and fill.color[2] == 1 and fill.color[3] == 1 and game.barRaw.tint[2] == 1)
	W.blizzard(function() game.bar:SetStatusBarColor(1, 0.5, 0) end)
	check("tooltip health bar: the colour the game sets later tints the same fill", fill.color[1] == 1 and game.barRaw.tint[2] == 0.5 and fill.file == nil)
	W.change("chat.health", false)
	local off = fill.file == BAR_FILE and fill.color == nil and W.state(game.bar) == "hb"
	W.change("chat.health", true)
	check("tooltip health bar: switched off it has the game's fill back and no box, and on again it is flat with nothing made twice", off and fill.color ~= nil and W.state(game.bar) == "SB"
		and #W.addonFrames == frames and #W.addonTextures == textures)
	clean(W, "tooltip health bar")
end

-- A client without the pieces: the module prints only its status line and touches nothing.
do
	local plain = newWorld()
	plain.login()
	local W = started({ noChat = true, noTips = true })
	check("a client without chat windows or tooltips: the status line says nothing was styled, with no line under it, and nothing is printed", W.line("Chat and tooltips") == "Chat and tooltips: on, 0 styled"
		and W.status() == plain.status() and #W.out == 0)
	local B = started({ bareTips = true, noChat = true })
	check("tooltips that have no nine-slice art are left alone, and the health bar is still styled", B.state(B.tips.GameTooltip.frame) == "." and #wowned(B, B.tips.GameTooltip.frame) == 0
		and B.line("Chat and tooltips") == "Chat and tooltips: on, 1 styled" and #B.violations == 0, B.line("Chat and tooltips"))
	local H = started({ noHook = true, noData = true, noBar = true })
	check("a client without hooksecurefunc, the tooltip data calls or a health bar: the windows and the tooltips are styled, and nothing stops", H.state(H.windows[1].bg) == "SB"
		and H.state(H.tips.GameTooltip.frame) == "SB" and edge(H, H.tips.GameTooltip.frame) == PLAIN and not has(H.status(), "stopped") and #H.errors == 0)
end

-- The hooks: seven on functions of the game, none on an input box or a tooltip, none twice.
do
	local control = started({ noChat = true, noTips = true })
	local W = started()
	local expected = control.hooks + 7
	W.change("chat.frames", false)
	W.change("chat.frames", true)
	W.change("general.thickness", 2)
	check("hooks: seven functions of the game, none made twice and none on an input box or a tooltip, and one call registered for the tooltip data", W.hooks == expected
		and #W.postCalls == 1 and W.postCalls[1][1] == "ALL", W.hooks .. " " .. expected)
	check("a general setting reaches the panel and the tooltip box: the border thickness", near(W.look(W.windows[1].bg).thick, 2) and W.look(W.tips.GameTooltip.frame).thick > 1.5)
	clean(W, "hooks")
end

-- hkchat: no method of an input box or of GameTooltip is hooked, with taintLog 0 and 2. The focus art, the idle opacity, the held tooltip and the
-- temporary window follow the game by EventRegistry, HookScript and the next frame.
do
	local TINT = { r = 0.5, g = 0.8, b = 1 }
	local function box(W, w)
		local br = w.boxRaw
		function br.Deactivate()
			br.alpha, br.focus = 0.35, false
		end
		function br.HasFocus() return br.focus == true end
		br.alpha = 0.35
	end
	-- The game opens the box: focus, art shown, tint of the chat type; the callback comes from the game's OnEditFocusGained.
	local function open(W, w, tint)
		w.boxRaw.focus = true
		W.blizzard(function()
			w.box:SetFocusRegionsShown(true)
			w.box:SetFocusRegionVertexColors(tint or TINT)
		end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusGained", w.box)
	end
	for _, value in ipairs({ "0", "2" }) do
		local tag = "hkchat: taintLog " .. value .. ": "
		local W = FH.chatWorld()
		W.cvars.taintLog = value
		for _, w in ipairs(W.windows) do
			box(W, w)
		end
		W.login()
		W.flush()
		local one, two = W.windows[1], W.windows[2]
		local written = false
		for _, w in ipairs(W.windows) do
			for _, name in ipairs({ "SetFocusRegionsShown", "SetFocusRegionVertexColors", "Deactivate" }) do
				written = written or INSTHOOK.wrapped(W, w.box, name)
			end
		end
		check(tag .. "no method of an input box has a hook written on it, and GameTooltip has none on Show or Hide", not written and not INSTHOOK.wrapped(W, W.tips.GameTooltip.frame, "Show")
			and not INSTHOOK.wrapped(W, W.tips.GameTooltip.frame, "Hide") and W.tipHooks == 2, tostring(W.tipHooks))
		open(W, one)
		check(tag .. "the border does not change inside the game's call", edge(W, one.box) == PLAIN)
		W.flush()
		check(tag .. "the border has the colour of the chat type on the next frame, and the focus art stays transparent", edge(W, one.box) == "0.50,0.80,1.00" and edge(W, two.box) == PLAIN
			and alphaOf(W, keyed(W, one.box, FOCUS)) == "0,0,0", edge(W, one.box))
		W.blizzard(function() one.box:SetFocusRegionVertexColors({ r = 1, g = 0.5, b = 0.25 }) end)
		W.frame(8)
		check(tag .. "a chat type that changes while the box has the focus changes the border with no moment of the game's", edge(W, one.box) == "1.00,0.50,0.25", edge(W, one.box))
		W.change("chat.inputFocus", "Highlight colour")
		local ar, ag, ab = W.ns.Colour("windows.accent")
		check(tag .. "Highlight colour takes the highlight colour", edge(W, one.box) == ("%.2f,%.2f,%.2f"):format(ar, ag, ab), edge(W, one.box))
		W.change("chat.inputFocus", "Plain border")
		check(tag .. "Plain border takes the general border", edge(W, one.box) == PLAIN, edge(W, one.box))
		W.change("chat.inputFocus", "Chat type colour")
		check(tag .. "and Chat type colour takes it back", edge(W, one.box) == "1.00,0.50,0.25")
		W.change("chat.inputIdle", 60)
		W.blizzard(function() one.box:Deactivate() end)
		W.blizzard(function()
			one.box:SetFocusRegionsShown(false)
		end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", one.box)
		check(tag .. "the game's opacity of a closed box stands inside the game's call", one.boxRaw.alpha == 0.35)
		W.flush()
		check(tag .. "the opacity of Input box opacity when idle is set on the next frame, and the border is plain", one.boxRaw.alpha == 0.6 and edge(W, one.box) == PLAIN, tostring(one.boxRaw.alpha))
		W.frame(8)
		check(tag .. "a box that lost the focus is not read again", W.registry ~= nil and #W.errors == 0)
		W.change("chat.editbox", false)
		open(W, two, { r = 0.2, g = 0.4, b = 0.6 })
		W.flush()
		check(tag .. "Chat input box off: what the game does to the box changes nothing", alphaOf(W, two.boxArt) == "1,1,1" and edge(W, two.box) == PLAIN)
		-- A tooltip the game shows in combat.
		local game = W.tips.GameTooltip
		local raw = W.rawOf[game.frame]
		W.change("chat.combat", "Hide every tooltip")
		W.combat = true
		raw.shown = false
		W.blizzard(function() game.frame:Show() end)
		check(tag .. "Tooltips in combat: Hide every tooltip hides a tooltip the game shows at once", raw.shown == false)
		W.change("chat.combat", "Show as usual")
		W.combat = false
		raw.shown = false
		W.blizzard(function() game.frame:Show() end)
		check(tag .. "Show as usual leaves it up", raw.shown == true)
		W.change("chat.combat", "Hide every tooltip")
		W.combat = true
		raw.shown = false
		W.blizzard(function() game.frame:Show() end)
		check(tag .. "and again each time the game shows it", raw.shown == false)
		W.combat = false
		-- A temporary window.
		W.change("chat.editbox", true)
		W.game("FCF_OpenTemporaryWindow")
		W.game("FCF_OpenTemporaryWindow")
		check(tag .. "a window the game opens is not styled inside the game's call, and two in one frame are one pass", W.state(W.windows[3].bg) ~= "SB" and #W.timers == 1, tostring(#W.timers))
		W.flush()
		check(tag .. "it is styled on the next frame, with its tab and input box", W.state(W.windows[3].bg) == "SB" and W.state(W.windows[4].bg) == "SB" and childOf(W, W.windows[3].tab) ~= nil
			and #wowned(W, W.windows[3].box) == 5, W.state(W.windows[3].bg) .. " " .. tostring(W.windows[4] and W.state(W.windows[4].bg)) .. " " .. #wowned(W, W.windows[3].box))
		-- With taintLog on, Reload makes its named box, which this world has no frame type for.
		local own = {}
		for _, v in ipairs(W.violations) do
			if v ~= "CreateFrame arguments" then
				own[#own + 1] = v
			end
		end
		check(tag .. "no violation and no error", #W.errors == 0 and #own == 0, table.concat(own, "|") .. " " .. table.concat(W.errors, "|"))
	end
	-- Chat input box off from login: the idle opacity still follows the game's Deactivate.
	do
		local W = FH.chatWorld()
		for _, w in ipairs(W.windows) do
			box(W, w)
		end
		W.cvars.taintLog = "0"
		W.login()
		W.change("chat.editbox", false)
		W.change("chat.inputIdle", 60)
		W.flush()
		local one = W.windows[1]
		open(W, one)
		W.flush()
		W.blizzard(function() one.box:Deactivate() end)
		W.blizzard(function() one.box:SetFocusRegionsShown(false) end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", one.box)
		W.flush()
		check("hkchat: Chat input box off from the start: a closed box has the opacity of Input box opacity when idle", one.boxRaw.alpha == 0.6 and #W.errors == 0, tostring(one.boxRaw.alpha))
	end
	-- Focus lost with text in the box: the game leaves the box open, so the idle opacity is not set.
	do
		local W = FH.chatWorld()
		for _, w in ipairs(W.windows) do
			box(W, w)
		end
		W.login()
		W.change("chat.inputIdle", 60)
		W.flush()
		local one = W.windows[1]
		open(W, one)
		one.boxRaw.shown = true
		W.flush()
		one.boxRaw.focus, one.boxRaw.alpha = false, 1
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", one.box)
		W.flush()
		check("hkchat: focus lost with text in the box: the box keeps the opacity the game gave it", one.boxRaw.alpha == 1, tostring(one.boxRaw.alpha))
		W.blizzard(function() one.box:Deactivate() end)
		W.blizzard(function() one.box:SetFocusRegionsShown(false) end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", one.box)
		W.flush()
		check("hkchat: and when the game closes it, the idle opacity is set", one.boxRaw.alpha == 0.6, tostring(one.boxRaw.alpha))
	end
	-- A box that has the focus when the module starts is read at once.
	do
		local W = FH.chatWorld()
		for _, w in ipairs(W.windows) do
			box(W, w)
		end
		open(W, W.windows[1])
		W.login()
		W.flush()
		check("hkchat: a box that has the focus when the module starts has the border of its chat type", edge(W, W.windows[1].box) == "0.50,0.80,1.00" and edge(W, W.windows[2].box) == PLAIN, edge(W, W.windows[1].box))
	end
	-- A client without EventRegistry and without a hook on scripts.
	do
		local W = FH.chatStarted({ noRegistry = true })
		W.blizzard(function() W.windows[1].box:SetFocusRegionsShown(true) end)
		W.flush()
		check("hkchat: a client with no EventRegistry makes no error, and the box keeps the plain border", #W.errors == 0 and #W.violations == 0 and edge(W, W.windows[1].box) == PLAIN)
	end
end

end)()
end

-- Movers place the frames Edit Mode owns with the engine's own SetPointBase, ClearAllPointsBase and SetScaleBase, never with the Lua that
-- replaces SetPoint, ClearAllPoints, SetScale, Hide and SetShown, and leave them to Edit Mode while it is open. The world of `systems` has a
-- bar of the stacks, a bar that is not, a child of a bar, a frame a container lays out and the loot window besides the three the other worlds have.
do
local function systems()
local mw, mwBefore, opt, entry, pts = suiteKit.mw, suiteKit.mwBefore, suiteKit.opt, suiteKit.entry, suiteKit.pts
local rectIs, rectText, allClean, problems, outText = suiteKit.rectIs, suiteKit.rectText, suiteKit.allClean, suiteKit.problems, suiteKit.outText
local LAYOUT = { systems = true }
-- A shown handle by the text it shows, whether it takes the mouse or not.
local function box(W, text)
	for _, f in ipairs(W.addonFrames) do
		if f.movable and f.shown and f.fonts[1] and f.fonts[1].text == text then
			return f
		end
	end
end
local function raw(W, name)
	return W.rawOf[W.env[name]]
end
local function look(W, leaf)
	W.foci = { leaf }
	W.update(0.1)
end
local function tagOf(W)
	local _, text = W.pickTag()
	return text and text.text
end
local function alt(W)
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
end
local function shownList(W)
	return table.concat(W.shownHandles(), ",")
end
local SPOT = { MinimapCluster = { point = "CENTER", x = 136, y = 56, kind = "hud" } }

do
	local W = mw({ layout = LAYOUT })
	W.slash("move")
	local shown = shownList(W)
	check("system frames: a handle for each one that exists, also the loot window, which is not shown", has(shown, "Minimap") and has(shown, "Player frame") and has(shown, "Buffs") and has(shown, "Action bar 6")
		and has(shown, "Loot window") and box(W, "Cast bar") == nil, shown)
	local main, leave, timer = box(W, "Main action bar (moved back by the game in combat)"), box(W, "Leave vehicle button (placed by the game)"), box(W, "Main hand swing timer (moved back by the game in combat)")
	check("system frames: a child of a bar has a grey box that takes no mouse; a bar of the stacks and a frame a container lays out have boxes that do", main and leave and timer
		and not leave.mouse and not leave.wheel and main.mouse == true and main.wheel == true and timer.mouse == true and timer.wheel == true)
	check("system frames: the others take the mouse and the wheel", box(W, "Minimap").mouse == true and box(W, "Minimap").wheel == true and box(W, "Action bar 6 (moved back by the game in combat)").mouse == true)

	W.drag("Minimap", 1000, 500)
	local e = entry(W, "MinimapCluster")
	check("a system frame is dragged: the spot is saved by the third of the screen", e and e.point == "CENTER" and near(e.x, 136) and near(e.y, 56) and e.kind == "hud", e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("it is placed with the engine's calls and counted, and the Lua of Edit Mode is not called", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1" and W.line("Movers") == "Movers: on, 1 moved" and allClean(W),
		pts(W, W.minimap) .. W.line("Movers") .. problems(W))
	W.keys.ctrl = true
	W.wheel("Minimap", 1)
	W.keys.ctrl = false
	check("Ctrl and the wheel scale it with SetScaleBase, about the same spot", raw(W, "MinimapCluster").scale == 1.05 and rectIs(W, "MinimapCluster", 995.2, 495.2, 201.6, 201.6, 1e-6) and allClean(W), rectText(W, "MinimapCluster"))
	W.rightClick("Minimap")
	check("a right-click puts the points and the scale back", pts(W, W.minimap) == "TOPRIGHT>UIParent:TOPRIGHT 0,0 @1" and next(W.spots()) == nil, pts(W, W.minimap))
	check("and says that /reload gives it back to Edit Mode fully", has(outText(W), "Minimap is back where it was, and /reload gives it back to Edit Mode fully."), outText(W))
end

do
	-- Edit Mode lays its frames out again at login, with a layout, with a specialisation and when it closes; and is left alone while it is open.
	local W = mw({ saved = opt({}, SPOT), layout = LAYOUT })
	W.gamePlaces("MinimapCluster", "TOPRIGHT", 0, 0)
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	check("a layout applied: the frame is placed again on the next frame", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1", pts(W, W.minimap))
	W.gamePlaces("MinimapCluster", "TOPRIGHT", 0, 0)
	W.fire("PLAYER_SPECIALIZATION_CHANGED", "player")
	W.flush()
	check("a specialisation change: the same", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1", pts(W, W.minimap))
	W.gamePlaces("MinimapCluster", "TOPRIGHT", 0, 0)
	W.run(0.6)
	check("the check twice a second covers the rest", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1", pts(W, W.minimap))
	W.slash("move")
	W.editMode(true)
	W.run(0.3)
	check("Edit Mode open: the handles of its frames are hidden and the others stay", not has(shownList(W), "Minimap") and not has(shownList(W), "Player frame") and has(shownList(W), "Alerts"), shownList(W))
	W.gamePlaces("MinimapCluster", "TOPLEFT", 50, -50)
	W.run(2)
	check("Edit Mode open: its frame is left where it put it", pts(W, W.minimap) == "TOPLEFT>UIParent:TOPLEFT 50,-50 @1" and allClean(W), pts(W, W.minimap))
	W.editMode(false)
	W.flush()
	check("Edit Mode closed: the frame is placed again on the next frame", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1", pts(W, W.minimap))
	local control = mw({ layout = LAYOUT })
	check("nothing is hooked", W.hooks == control.hooks, W.hooks - control.hooks)
end

do
	-- A protected frame is placed out of combat only.
	local W = mw({ saved = opt({}, { PlayerFrame = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } }), layout = LAYOUT })
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	-- Edit Mode is secure code, which may lay out a protected frame in combat.
	raw(W, "PlayerFrame").points = { { "TOPLEFT", W.env.UIParent, "TOPLEFT", 20, -20 } }
	W.run(2)
	check("in combat it is left where the game put it, and nothing is refused", pts(W, W.playerFrame) == "TOPLEFT>UIParent:TOPLEFT 20,-20 @1" and allClean(W) and not has(W.status(), "blocked"), pts(W, W.playerFrame) .. problems(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.run(0.6)
	check("when combat ends it is placed again", pts(W, W.playerFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-200 @1" and allClean(W), pts(W, W.playerFrame))
end

do
	-- A bar of the stacks and a frame a container lays out are placed; a child of a bar is left to the game, and the status says so.
	local saved = opt({}, { MainActionBar = { point = "BOTTOM", x = 0, y = 200, kind = "hud" }, MultiBar5 = { point = "BOTTOM", x = 0, y = 200, kind = "hud" },
		SwingTimerMainHandFrame = { point = "BOTTOM", x = 0, y = 500, kind = "hud" }, MainMenuBarVehicleLeaveButton = { point = "BOTTOM", x = 0, y = 600, kind = "hud" } })
	local W = mw({ saved = saved, layout = LAYOUT })
	W.run(2)
	check("a bar of the stacks in its default position is placed, and its IsShown is not called", pts(W, W.env.MainActionBar) == "BOTTOM>UIParent:BOTTOM 0,200 @1" and allClean(W), pts(W, W.env.MainActionBar) .. problems(W))
	check("a bar that is in no stack is placed", pts(W, W.env.MultiBar5) == "BOTTOM>UIParent:BOTTOM 0,200 @1", pts(W, W.env.MultiBar5))
	check("a frame a container lays out is placed, and the three are counted", pts(W, W.env.SwingTimerMainHandFrame) == "BOTTOM>UIParent:BOTTOM 0,500 @1" and W.line("Movers") == "Movers: on, 3 moved",
		pts(W, W.env.SwingTimerMainHandFrame) .. W.line("Movers"))
	check("a child of a bar is left to the game", pts(W, W.env.MainMenuBarVehicleLeaveButton) == "BOTTOMLEFT>MainActionBar:BOTTOMLEFT 0,0 @1", pts(W, W.env.MainMenuBarVehicleLeaveButton))
	check("the status names the child alone", has(W.status(), "Leave vehicle button is placed by the game, so its saved spot is not used.") and not has(W.status(), "Main action bar is placed")
		and not has(W.status(), "Main hand swing timer is placed"), W.status())
	raw(W, "MainActionBar").systemInfo.isInDefaultPosition = false
	raw(W, "SwingTimerMainHandFrame").ignoreFramePositionManager = true
	raw(W, "SwingTimerMainHandFrame").parent = W.env.UIParent
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	check("a bar the player has moved in Edit Mode is still placed", pts(W, W.env.MainActionBar) == "BOTTOM>UIParent:BOTTOM 0,200 @1", pts(W, W.env.MainActionBar))
	check("so is a frame Edit Mode has taken out of its container", pts(W, W.env.SwingTimerMainHandFrame) == "BOTTOM>UIParent:BOTTOM 0,500 @1" and has(W.status(), "Leave vehicle button is placed") and allClean(W),
		W.status() .. problems(W))
end

do
	-- Edit Mode has not set a frame up yet: nothing is placed, and the frame is placed once it has.
	local saved = opt({}, { MultiBar5 = { point = "BOTTOM", x = 0, y = 200, kind = "hud" } })
	local W = mwBefore({ saved = saved, layout = LAYOUT }, function(W)
		raw(W, "MultiBar5").systemInfo = nil
	end)
	check("a system frame Edit Mode has not set up is not placed", pts(W, W.env.MultiBar5) == "BOTTOM>UIParent:BOTTOM 0,300 @1" and allClean(W), pts(W, W.env.MultiBar5) .. problems(W))
	raw(W, "MultiBar5").systemInfo = { isInDefaultPosition = true }
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	check("it is placed on the next frame after the layout is applied", pts(W, W.env.MultiBar5) == "BOTTOM>UIParent:BOTTOM 0,200 @1" and not has(W.status(), "Action bar 6 is placed"), pts(W, W.env.MultiBar5) .. W.status())
end

do
	-- The setting for the game's own frames.
	local W = mw({ saved = opt({}, SPOT), layout = LAYOUT })
	W.change("movers.systems", false)
	check("off: the frame goes back, its spot is kept and it is not counted", pts(W, W.minimap) == "TOPRIGHT>UIParent:TOPRIGHT 0,0 @1" and entry(W, "MinimapCluster") ~= nil and W.line("Movers") == "Movers: on, 0 moved",
		pts(W, W.minimap) .. W.line("Movers"))
	W.slash("move")
	check("off: no handle for it", box(W, "Minimap") == nil and has(shownList(W), "Alerts"), shownList(W))
	W.gamePlaces("MinimapCluster", "TOPLEFT", 50, -50)
	W.run(2)
	check("off: the check leaves it where the game puts it", pts(W, W.minimap) == "TOPLEFT>UIParent:TOPLEFT 50,-50 @1", pts(W, W.minimap))
	W.change("movers.systems", true)
	check("on again: it is placed and counted", pts(W, W.minimap) == "CENTER>UIParent:CENTER 136,56 @1" and W.line("Movers") == "Movers: on, 1 moved" and allClean(W), pts(W, W.minimap) .. W.line("Movers"))
	W.slash("move reset")
	check("reset all says it once and names /reload once", has(outText(W), "Moved frames are back where the game has them.") and has(outText(W), "/reload gives the game's own frames back to Edit Mode fully.")
		and not has(outText(W), "is back where it was"), outText(W))
end

do
	-- The picker says which of the game's own frames it leaves, and offers a bar of the stacks and a frame a container lays out.
	local W = mwBefore({ layout = LAYOUT }, function(W)
		raw(W, "MultiBar5").systemInfo = nil
	end)
	W.slash("grab")
	look(W, W.env.MultiBar5)
	alt(W)
	check("picker: a frame Edit Mode has not set up says the game places it, and Alt takes nothing", tagOf(W) == "Action bar 6 is placed by the game." and next(W.spots()) == nil and allClean(W),
		tostring(tagOf(W)) .. problems(W))
	local before = W.hooks
	look(W, W.env.MainMenuBarVehicleLeaveButton)
	local child = tagOf(W)
	alt(W)
	check("picker: the child of a bar hands over to the bar, which Alt takes, with no hook", child == "MainActionBar" and entry(W, "MainActionBar") ~= nil and W.hooks - before == 0 and allClean(W),
		tostring(child) .. problems(W))
	W.slash("grab")
	look(W, W.env.SwingTimerMainHandFrame)
	local member = tagOf(W)
	alt(W)
	check("picker: a frame a container lays out is offered and taken, with no hook", member == "SwingTimerMainHandFrame" and entry(W, "SwingTimerMainHandFrame") ~= nil and W.hooks - before == 0 and allClean(W),
		tostring(member) .. problems(W))
end

do
	-- Every frame Edit Mode owns on the client has a handle with its plain name.
	local NAMES = { "PlayerFrame", "TargetFrame", "FocusFrame", "PetFrame", "PartyFrame", "CompactRaidFrameContainer", "BossTargetFrameContainer", "MainActionBar",
		"MultiBarBottomLeft", "MultiBarBottomRight", "MultiBarRight", "MultiBarLeft", "MultiBar5", "MultiBar6", "MultiBar7", "StanceBar", "PetActionBar", "PossessActionBar",
		"MultiCastActionBarFrame", "MainMenuBarVehicleLeaveButton", "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer", "MicroMenuContainer", "BagsBar",
		"MinimapCluster", "QueueStatusButton", "ChatFrame1", "BuffFrame", "DebuffFrame", "ExternalDefensivesFrame", "PlayerCastingBarFrame", "PersonalResourceDisplayFrame",
		"SwingTimerMainHandFrame", "SwingTimerOffHandFrame", "SwingTimerRangedFrame", "ObjectiveTrackerFrame", "LootFrame", "GameTooltipDefaultContainer", "EncounterBar",
		"ExtraAbilityContainer", "TalkingHeadFrame", "DurabilityFrame", "MirrorTimerContainer", "VehicleSeatIndicator", "ArcheologyDigsiteProgressBar", "EssentialCooldownViewer",
		"UtilityCooldownViewer", "BuffIconCooldownViewer", "BuffBarCooldownViewer", "DamageMeter", "RaidWarningFrame", "LossOfControlFrame" }
	local LABELS = "Action bar 2,Action bar 3,Action bar 4,Action bar 5,Action bar 6,Action bar 7,Action bar 8,Alerts,Archaeology bar,Bag bar,Boss frames,Buffs,Cast bar,Chat,Damage meter,Debuffs,"
		.. "Durability,Encounter bar,Enemy cooldowns: focus,Enemy cooldowns: target,Error text,Essential cooldowns,Game's experience bar,External defensives,Extra abilities,Focus frame,Group finder,Leave vehicle button,Loot window,Main action bar,"
		.. "Main hand swing timer,Micro menu,Minimap,Objective tracker,Off hand swing timer,Party frames,Personal resource display,Pet bar,Pet frame,Player frame,Possess bar,Raid frames,Raid warning,"
		.. "Ranged swing timer,Game's second status bar,Stance bar,Talking head,Target frame,Timer bars,Top widgets,Totem bar,Tracked buff bars,Tracked buffs,Tooltip,Utility cooldowns,Vehicle seats,Zone text,"
		.. "Loss of control"
	-- The client has these four before the world adds Edit Mode's frames, with no place, so they are made again.
	local W = mw({ missing = { PlayerCastingBarFrame = true, PersonalResourceDisplayFrame = true, SwingTimerOffHandFrame = true, SwingTimerRangedFrame = true },
		layout = { systems = true, tooltip = true, allSystems = NAMES } })
	-- The loot window is hidden unless something is being looted.
	W.rawOf[W.env.LootFrame].shown = true
	W.slash("move")
	local texts = {}
	for _, f in ipairs(W.addonFrames) do
		local label = f.movable and f.shown and f.drag and f.fonts[1] and f.fonts[1].text
		if label and label ~= "Movers" then
			texts[#texts + 1] = (label:gsub(" %(moved back by the game in combat%)$", ""):gsub(" %(placed by the game%)$", ""):gsub(" %d+%%$", ""))
		end
	end
	table.sort(texts)
	local wanted = {}
	for label in LABELS:gmatch("[^,]+") do
		wanted[#wanted + 1] = label
	end
	table.sort(wanted)
	check("every frame Edit Mode owns has a handle with a plain name", table.concat(texts, ",") == table.concat(wanted, ","), table.concat(texts, ","))
	local W2 = mw({ layout = { systems = true, tooltip = true }, saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "cursor" }) })
	W2.slash("move")
	check("the tooltip box of Edit Mode has no handle while the tooltip is placed by this addon", box(W2, "Tooltip") == nil and allClean(W2), problems(W2))
end

end
systems()
end

do
-- Unit frames, second part: boss, party pet and raid frames, totem buttons, the level and PvP plates, the strip behind the name of a target
-- and aura icons. The world is built here the way Blizzard's XML builds these frames; the game's own functions run inside W.blizzard.
local function xWorld(opts)
	opts = opts or {}
	-- The checks of these frames were written for the fixed rooms of the name row.
	local W = newWorld({ combat = opts.combat, saved = { options = { ["unitframes.nameRoom"] = "fixed" } } })
	local env, B, Rr = W.env, W.B, W.Rr
	local X = { W = W, targeted = {}, threat = {}, reaction = { 0.9, 0.1, 0.1 }, types = { Magic = { 0.2, 0.6, 1 }, Curse = { 0.6, 0, 1 }, None = { 0.8, 0, 0 } }, class = "normal" }
	env.SetPortraitTexture = function(texture) argt(W, "SetPortraitTexture", texture) end
	-- The client says what the target is: X.class.
	env.UnitClassification = function(unit) return unit == "target" and X.class or "normal" end
	local function blizz(name, fn)
		return FH.wrap(W, name, function(...)
			if W.inBlizzard == 0 or (W.inHook or 0) > 0 then
				bad(W, "the addon called the Blizzard function " .. name)
			end
			return fn(...)
		end)
	end
	local function put(parent, key, child)
		W.rawOf[parent][key] = child
		return child
	end
	local function region(owner, atlas, layer, sublevel, more)
		local o = { layer = layer or "ARTWORK", sublevel = sublevel or 0 }
		for k, v in pairs(more or {}) do
			o[k] = v
		end
		return (Rr(owner, atlas, o))
	end
	-- A status bar with a fill drawn from an atlas, under a mask when it has one.
	local function bar(parent, atlas, maskAtlas, token)
		local proxy, raw = B(parent, {}, { protected = true, objectType = "StatusBar" })
		W.maskable(raw)
		local fill = region(proxy, atlas)
		local fillRaw = W.rawOf[fill]
		local mask
		if maskAtlas then
			mask = region(proxy, maskAtlas, "OVERLAY", 2, { kind = "MaskTexture" })
			fill:AddMaskTexture(mask)
		end
		raw.tint, raw.powerToken = { 1, 1, 1, 1 }, token
		raw.GetStatusBarTexture = function() return fill end
		-- A path names an image file, anything else an atlas.
		raw.SetStatusBarTexture = function(_, asset)
			fillRaw.color = nil
			if asset:find("[\\/]") then
				fillRaw.atlas, fillRaw.file = nil, asset
			else
				fillRaw.atlas, fillRaw.file = asset, nil
			end
			return true
		end
		raw.SetColorFill = function(_, r, g, b, a) fillRaw.color, fillRaw.atlas, fillRaw.file = { r, g, b, a }, nil, nil end
		raw.SetStatusBarColor = function(_, r, g, b, a) raw.tint = { r, g, b, a or 1 } end
		raw.GetStatusBarColor = function() return unpack(raw.tint, 1, 4) end
		return proxy, fill, mask
	end
	env.PowerBarColor = { MANA = { r = 0, g = 0, b = 1 } }

	-- A target frame, or a boss frame, which is the same frame without its portrait.
	local function targetLike(name, boss)
		W.group = name
		local frame = B(nil, {}, { protected = true, objectType = "Button", name = name })
		env[name] = frame
		local T = { frame = frame }
		local container = put(frame, "TargetFrameContainer", B(frame, {}, {}))
		if not boss then
			T.portrait = put(container, "Portrait", region(container, nil, "BACKGROUND", 1))
			T.boss = put(container, "BossPortraitFrameTexture", region(container, "UI-HUD-UnitFrame-Target-PortraitOn-Boss-Gold", "ARTWORK", 2, { hidden = true }))
		end
		T.art = put(container, "FrameTexture", region(container, "UI-HUD-UnitFrame-Target-PortraitOn", "BACKGROUND", 2))
		T.flash = put(container, "Flash", region(container, "UI-HUD-UnitFrame-Target-PortraitOn-InCombat", "ARTWORK", 1, { hidden = true }))
		local content = put(frame, "TargetFrameContent", B(frame, {}, { protected = true }))
		local main = put(content, "TargetFrameContentMain", B(content, {}, { protected = true }))
		T.level = put(main, "LevelBackgroundCircle", region(main, "UI-HUD-UnitFrame-SmallCircle", "OVERLAY", 0))
		T.levelText = put(main, "LevelText", region(main, nil, "OVERLAY", 0, { kind = "FontString" }))
		T.strip = put(main, "ReputationColor", region(main, "UI-HUD-UnitFrame-Target-PortraitOn-Type", "BACKGROUND", 0))
		-- Camelot's OnLoad gives the number one point, on the level plate (Camelot/TargetFrame.lua:9-11). The boss frame's OnLoad adds a second,
		-- on the reputation bar (Mainline/TargetFrame.lua:987), so its number is as large as the rectangle between the two.
		T.levelText:SetPoint("CENTER", T.level, "CENTER", 0, -0.5)
		if boss then
			T.levelText:SetPoint("TOPLEFT", T.strip, "TOPRIGHT", -83, -2)
		end
		T.box = put(main, "HealthBarsContainer", B(main, {}, { protected = true }))
		T.health, T.healthFill, T.healthMask = bar(T.box, "UI-HUD-UnitFrame-Target-PortraitOn-Bar-Health", "UI-HUD-UnitFrame-Party-PortraitOff-Bar-Health-Mask")
		put(T.box, "HealthBar", T.health)
		put(T.box, "HealthBarMask", T.healthMask)
		T.power, T.powerFill, T.powerMask = bar(main, "UI-HUD-UnitFrame-Player-PortraitOn-Bar-Mana", "UI-HUD-UnitFrame-Party-PortraitOff-Bar-Mana-Mask", "MANA")
		put(main, "ManaBar", T.power)
		put(T.power, "ManaBarMask", T.powerMask)
		local context = put(content, "TargetFrameContentContextual", B(content, {}, {}))
		T.pvp = put(context, "PvpBackgroundCircle", region(context, "UI-HUD-UnitFrame-SmallCircle", "OVERLAY", -1, { hidden = true }))
		T.high = put(context, "HighLevelTexture", region(context, "UI-HUD-UnitFrame-Target-HighLevelTarget_Icon", "OVERLAY", 1, { hidden = true }))
		T.strip:SetVertexColor(0.2, 0.8, 0.4)
		if boss then
			-- The name of a boss frame is a text of the target frame's template, and the game gives the frame its unit.
			T.nameText = put(main, "Name", region(main, nil, "OVERLAY", 0, { kind = "FontString" }))
			W.rawOf[T.nameText].text, W.rawOf[T.nameText].font = "Boss One", { "Fonts\\FRIZQT__.TTF", 10, "" }
			W.rawOf[frame].unit = "boss1"
		end
		W.rawOf[frame].CheckClassification = blizz("CheckClassification", function() end)
		W.rawOf[frame].CheckBattlePet = blizz("CheckBattlePet", function() T.level:Hide() T.levelText:Hide() end)
		-- The number, or the skull for a level the game cannot tell, and the colour of the strip behind the name.
		W.rawOf[frame].CheckLevel = blizz("CheckLevel", function()
			T.levelText:SetShown(not X.skull)
			T.high:SetShown(X.skull == true)
		end)
		W.rawOf[frame].CheckFaction = blizz("CheckFaction", function() T.strip:SetVertexColor(X.reaction[1], X.reaction[2], X.reaction[3]) end)
		if not boss then
			-- The aura container and its buttons, with the icon and the borders the XML names. The buff can be stolen once its border shows.
			T.auras = put(context, "Auras", B(context, {}, { objectType = "Frame", forbidden = opts.auraBox }))
			W.rawOf[frame].UpdateAuras = blizz("UpdateAuras", function() end)
			T.buttons = {}
			for index, buff in ipairs({ false, true }) do
				local button = B(T.auras, {}, { objectType = "Button", forbidden = opts.auraButtons })
				local b = { button = button, icon = put(button, "Icon", region(button, nil, "BACKGROUND", 0)) }
				if buff then
					b.stealable = put(button, "StealableBorder", region(button, nil, "OVERLAY", 0, { hidden = true }))
				else
					b.dispel = put(button, "DispelBorder", region(button, nil, "OVERLAY", 0))
					b.dispel:SetVertexColor(0.6, 0, 1, 1)
				end
				table.insert(W.rawOf[T.auras].children, button)
				T.buttons[index] = b
			end
		end
		return T
	end
	X.boss = targetLike("Boss1TargetFrame", true)
	X.target = targetLike("TargetFrame")

	-- The debuff icons of the target of target frame, and the game's function that colours their borders. It gives the colour with
	-- four numbers, so the border comes back at full alpha.
	W.group = "tot"
	X.debuffs = {}
	for index = 1, 4 do
		local name = "TargetFrameToTDebuff" .. index
		local frame = B(nil, {}, { objectType = "Frame", name = name, hidden = true })
		env[name] = frame
		local D = { frame = frame, icon = region(frame, nil, "ARTWORK", 0), border = region(frame, nil, "OVERLAY", 0) }
		env[name .. "Icon"], env[name .. "Border"] = D.icon, D.border
		X.debuffs[index] = D
	end
	env.AuraUtil = { SetAuraBorderColor = blizz("AuraUtil.SetAuraBorderColor", function(border, dispelType)
		local c = X.types[dispelType] or X.types.None
		border:SetVertexColor(c[1], c[2], c[3], 1)
		border:SetAlpha(1)
	end) }

	-- The game tints a health bar green with each update unless the bar locks its colour, and the bar of a party pet does not
	-- (Mainline/UnitFrame.lua:834-836, PartyFrameTemplates.xml:48-59).
	env.UnitFrameHealthBar_Update = blizz("UnitFrameHealthBar_Update", function(bar) bar:SetStatusBarColor(0, 1, 0) end)
	-- The game writes the name of a unit in UnitFrame_Update, with the text X.nameWrite, on the frames of X.names (a frame to its name text).
	X.names = {}
	env.UnitFrame_Update = blizz("UnitFrame_Update", function(frame)
		local text = X.names[frame]
		if text ~= nil and X.nameWrite ~= nil then
			text:SetText(X.nameWrite)
		end
	end)

	-- The party frame makes a member with a pet frame when it first shows.
	W.group = "partypet"
	local party = B(nil, {}, { objectType = "Frame", name = "PartyFrame" })
	env.PartyFrame = party
	local pool, poolRaw = newPool(W, "pool")
	put(party, "PartyMemberFramePool", pool)
	local member = B(party, {}, { protected = true, objectType = "Button", name = "MemberFrame1" })
	local pet = put(member, "PetFrame", B(member, {}, { protected = true, objectType = "Button" }))
	X.pet = { frame = pet }
	X.pet.portrait = put(pet, "Portrait", region(pet, nil, "BACKGROUND", 0))
	X.pet.art = put(pet, "Texture", region(pet, "ui-hud-unitframe-party-portraiton", "ARTWORK", 0))
	X.pet.flash = put(pet, "Flash", region(pet, "ui-hud-unitframe-party-portraiton-incombat", "ARTWORK", 0, { hidden = true }))
	X.pet.health, X.pet.healthFill = bar(pet, "ui-hud-unitframe-party-portraiton-bar-health")
	put(pet, "HealthBar", X.pet.health)
	W.rawOf[party].InitializePartyMemberFrames = blizz("InitializePartyMemberFrames", function() poolRaw.items[1] = member end)

	-- The totem frame gets a button when a totem is placed.
	W.group = "totem"
	local totems = B(nil, {}, { objectType = "Frame", name = "TotemFrame", forbidden = opts.totemFrame })
	env.TotemFrame = totems
	local tpool, tpoolRaw = newPool(W, "pool")
	put(totems, "totemPool", tpool)
	local button = B(totems, {}, { objectType = "Button" })
	X.totem = { button = button, border = put(button, "Border", region(button, "UI-HUD-UnitFrame-TotemFrame", "OVERLAY", 0)) }
	X.totem.icon = put(button, "Icon", B(button, {}, {}))
	X.totem.texture = put(X.totem.icon, "Texture", region(X.totem.icon, nil, "BACKGROUND", 2))
	X.totem.mask = put(X.totem.icon, "TextureMask", region(X.totem.icon, "CircleMask", "BACKGROUND", 2, { kind = "MaskTexture" }))
	X.totem.texture:AddMaskTexture(X.totem.mask)
	W.rawOf[totems].Update = blizz("Update", function() tpoolRaw.items[1] = button end)

	-- The functions of the game that colour a compact unit frame. The target outline and the threat outline come back at full alpha.
	-- The anchors the game gives a cell in DefaultCompactUnitFrameSetup (CompactUnitFrame.lua:1892-1908), for a frame that has a power bar.
	X.offline, X.dead, X.player = {}, {}, {}
	local function gameSetup(frame)
		local power = W.rawOf[frame].powerBar
		if power ~= nil then
			local shown = X.powerOn[frame] ~= false
			if shown then
				power:SetPoint("TOPLEFT", W.rawOf[frame].healthBar, "BOTTOMLEFT", 0, 0)
				power:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -1, 1)
			end
			power:SetShown(shown)
			local used = shown and 8 or 0
			W.rawOf[frame].powerBarUsedHeight = used
			W.rawOf[frame].healthBar:SetPoint("TOPLEFT", frame, "TOPLEFT", 1, -1)
			W.rawOf[frame].healthBar:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -1, 1 + used)
		end
	end
	X.powerOn = {}
	-- The game's own code may move a protected frame in combat, which the simulated protection does not tell apart from an addon's call.
	local function gameCall(frame)
		local combat = W.combat
		W.combat = false
		gameSetup(frame)
		W.combat = combat
	end
	env.CompactUnitFrame_SetUpFrame = blizz("CompactUnitFrame_SetUpFrame", gameCall)
	env.CompactUnitFrame_UpdateAll = blizz("CompactUnitFrame_UpdateAll", gameCall)
	env.CompactUnitFrame_UpdatePowerColor = blizz("CompactUnitFrame_UpdatePowerColor", function(frame)
		local power = W.rawOf[frame].powerBar
		if power ~= nil then
			power:SetStatusBarColor(0, 0, 1)
		end
	end)
	env.UnitIsConnected = function(unit) return X.offline[unit] ~= true end
	env.UnitIsDead = function(unit) return X.dead[unit] == true end
	env.CompactUnitFrame_UpdateSelectionHighlight = blizz("CompactUnitFrame_UpdateSelectionHighlight", function(frame)
		if X.targeted[frame] then
			frame.selectionHighlight:SetVertexColor(1, 1, 1)
			frame.selectionHighlight:SetAlpha(1)
			frame.selectionHighlight:Show()
		else
			frame.selectionHighlight:Hide()
		end
	end)
	env.CompactUnitFrame_UpdateAggroHighlight = blizz("CompactUnitFrame_UpdateAggroHighlight", function(frame)
		local colour = X.threat[frame]
		if colour then
			frame.aggroHighlight:SetVertexColor(colour[1], colour[2], colour[3])
			frame.aggroHighlight:SetAlpha(1)
		end
		frame.aggroHighlight:SetShown(colour ~= nil)
	end)
	env.CompactUnitFrame_UpdateHealthColor = blizz("CompactUnitFrame_UpdateHealthColor", function(frame)
		frame.background:SetVertexColor(0.08, 0.08, 0.08)
		frame.background:SetAlpha(1)
		local unit = frame.unit
		if unit ~= nil and (X.offline[unit] or (X.dead[unit] and not X.player[unit])) then
			frame.healthBar:SetStatusBarColor(0.5, 0.5, 0.5)
		else
			frame.healthBar:SetStatusBarColor(0.78, 0.61, 0.43)
		end
	end)
	-- A compact unit frame as the game makes it, once the group needs it.
	function X.raidFrame(name, group, forbidden, cell)
		W.group = group
		local frame = B(nil, {}, { protected = true, objectType = "Button", name = name, forbidden = forbidden })
		env[name] = frame
		local R = { frame = frame }
		R.background = put(frame, "background", region(frame, "raidframe-hp-bg-white", "BACKGROUND", 0))
		R.select = put(frame, "selectionHighlight", region(frame, "RaidFrame-TargetFrame", "OVERLAY", 0, { hidden = true }))
		R.aggro = put(frame, "aggroHighlight", region(frame, "RaidFrame-AgroFrame", "ARTWORK", 0, { hidden = true }))
		R.health, R.healthFill = bar(frame, "RaidFrame-Hp-Fill")
		put(frame, "healthBar", R.health)
		-- cell: { unit = the unit of the frame, power = false for a frame the game shows no power bar on }
		if cell then
			put(frame, "unit", cell.unit)
			R.power, R.powerFill = bar(frame, "RaidFrame-Power-Fill")
			put(frame, "powerBar", R.power)
			X.powerOn[frame] = cell.power
			gameSetup(frame)
		end
		W.seal()
		return R
	end
	function X.update(R)
		W.blizzard(function()
			env.CompactUnitFrame_UpdateHealthColor(R.frame)
			env.CompactUnitFrame_UpdateSelectionHighlight(R.frame)
			env.CompactUnitFrame_UpdateAggroHighlight(R.frame)
		end)
	end
	if opts.prep then
		opts.prep(X)
	end
	W.seal()
	W.login()
	W.flush()
	return X
end
-- The world of the raid frames, the boss frame and the totem buttons, for the checks of ms-ufpart.
FH.xWorld = xWorld
check("ms-ufpart: the world that has the raid frames, the boss frame and the totem buttons is built by a function the checks of the parts use", type(FH.xWorld) == "function")

local function rgb(c) return c and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) or "-" end
local function colourOf(W, target)
	local o = W.look(target)
	return o and string.format("%.2f,%.2f,%.2f", o.r or -1, o.g or -1, o.b or -1) or "none"
end
local function masks(W, region) return #W.rawOf[region].maskList end
local function alphaOf(W, region) return g(W.rawOf[region].alpha) end
local function quiet(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "stopped") and not has(W.status(), "failed") end
-- The frame the border of a power bar follows: the bar, or the frame of the addon's own that spans the part of a wide bar that shows.
local function visible(W, power)
	if W.holderOn(power) then
		return power
	end
	for _, f in ipairs(W.addonFrames) do
		for _, p in ipairs(f.points) do
			if p[2] == power and W.holderOn(f) then
				return f
			end
		end
	end
	-- With the width of the health bar the span hangs from two corner frames, which hang from the bar.
	for _, f in ipairs(W.addonFrames) do
		for _, p in ipairs(f.points) do
			for _, corner in ipairs(W.addonFrames) do
				for _, q in ipairs(corner.points) do
					if p[2] == corner and q[2] == power and W.holderOn(f) then
						return f
					end
				end
			end
		end
	end
end
local function why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. tostring(W.line("Unit frames")) end
-- The frame of the addon's own that is the picture beside the bars of a portrait: the one on the frame the portrait is on that has a texture.
local function overlay(W, portrait)
	local owner = W.rawOf[portrait].owner
	for _, f in ipairs(W.addonFrames) do
		if f.parent == owner then
			for _, t in ipairs(f.regions) do
				if t.layer == "ARTWORK" and t.addon then
					return f
				end
			end
		end
	end
end
-- The textures of the addon's that are on the frame a portrait is on.
local function onFrameOf(W, portrait)
	local count = 0
	for _, t in ipairs(W.addonTextures) do
		if t.owner == W.rawOf[portrait].owner then
			count = count + 1
		end
	end
	return count
end
local PLAIN, GREEN, BLUE, WHITE, THREAT, PANEL, MUTED = "0.00,0.00,0.00", "0.18,0.72,0.30", "0.00,0.00,1.00", "1.00,1.00,1.00", "1.00,0.50,0.00", "0.06,0.06,0.06", "0.55,0.55,0.55"
local CURSE, MAGIC = "0.60,0.00,1.00", "0.20,0.60,1.00"
local STRIP, LEVEL = "UI-HUD-UnitFrame-Target-PortraitOn-Type", "UI-HUD-UnitFrame-SmallCircle"

-- Boss frames. The slot of the health bar is outlined because the bar frame is larger, and the mask stays on its fill.
do
	local X = xWorld()
	local W, S = X.W, X.boss
	check("boss: the frame art and the threat glow are transparent; the slot of the health bar and the power bar have a border and a background, and the bar frame has none",
		alphaOf(W, S.art) == "0" and alphaOf(W, S.flash) == "0" and ringOf(W, S.box, 1) and W.state(S.box) == "SB" and ringOf(W, S.power, 1) and W.state(S.power) == "SB"
		and W.state(S.health) == ".", why(W))
	check("boss: the fills are one colour, green for health and the colour of the power type for power; the power mask is off and the health mask stays",
		rgb(W.rawOf[S.healthFill].color) == GREEN and rgb(W.rawOf[S.powerFill].color) == BLUE and masks(W, S.healthFill) == 1 and masks(W, S.powerFill) == 0)
	-- The number of a boss frame has two points, which make it as large as the rectangle between them (Mainline/TargetFrame.lua:987).
	local boxed = false
	for _, f in ipairs(W.addonFrames) do
		if f.points[1] and f.points[1][2] == S.levelText then
			boxed = true
		end
	end
	check("boss: a level number with two points has no box, and its round plate is transparent under the row as a target's is", not boxed and #W.rawOf[S.levelText].points == 2 and alphaOf(W, S.level) == "0"
		and alphaOf(W, X.target.level) == "0", tostring(boxed))
	W.change("unitframes.boss", false)
	W.flush()
	local textures = #W.addonTextures
	check("boss: its switch puts the game's look back exactly and leaves the target frame styled", #W.diff("Boss1TargetFrame") == 0 and W.state(S.box) == "hb" and W.state(visible(W, X.target.power)) == "SB",
		table.concat(W.diff("Boss1TargetFrame"), "; "):sub(1, 200))
	W.change("unitframes.boss", true)
	check("boss: on again it is styled as before and nothing is made twice", W.state(S.box) == "SB" and alphaOf(W, S.art) == "0" and #W.addonTextures == textures and quiet(W), why(W))
end

-- Name rows on boss frames, which have no picture, and on party pet frames.
do
	local X = xWorld()
	local W, S, Z = X.W, X.boss, {}
	-- The name row of a frame: its frame, its layers and its five font strings.
	function Z.row(frame)
		for _, f in ipairs(W.addonFrames) do
			if f.parent == frame then
				local row, texts = { frame = f }, {}
				for _, r in ipairs(f.regions) do
					if r.kind == "FontString" then
						texts[#texts + 1] = r
					elseif r.layer == "BACKGROUND" and r.sublevel == 0 then
						row[row.grad and "fill" or "grad"] = r
					elseif r.layer == "ARTWORK" and r.sublevel == 0 then
						row.mark = r
					end
				end
				if #texts == 5 then
					row.level, row.name, row.kindMark, row.kindWord, row.flag = texts[1], texts[2], texts[3], texts[4], texts[5]
					return row
				end
			end
		end
	end
	function Z.shown(frame)
		local row = Z.row(frame)
		return row ~= nil and row.name.shown == true
	end
	W.rawOf[S.levelText].text = "63"
	W.blizzard(function() S.frame:CheckLevel() end)
	Z.row1 = Z.row(S.frame)
	check("small row: a boss frame has a row of 13 units on its health bar with the game's name, the level at its end, and the game's name and level transparent",
		Z.row1 ~= nil and Z.row1.name.shown and Z.row1.name.text == "Boss One" and Z.row1.frame.height == 13 and Z.row1.frame.points[1][2] == S.box
		and alphaOf(W, S.nameText) == "0" and Z.row1.level.shown and Z.row1.level.text == "63" and alphaOf(W, S.levelText) == "0", tostring(Z.row1 and Z.row1.name.text))
	Z.ends = {}
	for _, p in ipairs(Z.row1.name.points) do
		if p[1] == "RIGHT" then
			Z.ends[#Z.ends + 1] = g(p[4])
		end
	end
	check("small row: the name of a boss row leaves 20 units at the right end for the level, and the game's boss name keeps its size", table.concat(Z.ends, ",") == "-24" and W.rawOf[S.nameText].font[2] == 10,
		table.concat(Z.ends, ",") .. " " .. tostring(W.rawOf[S.nameText].font[2]))
	-- With Only what the texts need the name of a boss ends 2 units before its level.
	W.change("unitframes.nameRoom", "Only what the texts need")
	W.flush()
	Z.fit = {}
	for _, p in ipairs(Z.row1.name.points) do
		if p[1] == "RIGHT" then
			Z.fit[#Z.fit + 1] = p[3] .. g(p[4])
		end
	end
	W.change("unitframes.nameRoom", "Fixed space")
	W.flush()
	check("small row: with Only what the texts need the name of a boss row ends 2 units before the level", table.concat(Z.fit, ",") == "LEFT-2", table.concat(Z.fit, ","))
	Z.status = W.status()
	check("small row: the status has the boss frame's name, level, row size and colour",
		has(Z.status, "Boss 1 name: shown, the game's text") and has(Z.status, "Boss 1 level: end of the name row") and has(Z.status, "Boss 1 row: ") and has(Z.status, " x 13")
		and has(Z.status, "Boss 1 name row colour: the game's colour"), (Z.status:gsub("%s+", " ")))
	check("small row: the boss row has the colour of the strip the game gives the frame, at 70% brightness", rgb(Z.row1.fill.color) == "0.14,0.56,0.28" and Z.row1.fill.color[4] == 0.95, rgb(Z.row1.fill.color))
	-- Only Name row turns it off: not square portraits and not Name row on small frames.
	W.change("unitframes.squarePortrait", false)
	Z.noSquare = Z.shown(S.frame)
	W.change("unitframes.squarePortrait", true)
	W.change("unitframes.smallRow", false)
	Z.noSmall = Z.shown(S.frame)
	W.change("unitframes.smallRow", true)
	W.change("unitframes.strip", false)
	Z.noStrip = Z.shown(S.frame)
	Z.back = alphaOf(W, S.nameText)
	W.change("unitframes.strip", true)
	check("small row: a boss row follows Square portraits and Name row, not Name row on small frames, and the game's name is back with it off", not Z.noSquare and Z.noSmall and not Z.noStrip and Z.back == "1" and Z.shown(S.frame), tostring(Z.noSquare) .. tostring(Z.noSmall) .. tostring(Z.noStrip) .. Z.back)
	-- The game empties the name for a moment between units: the row keeps its name.
	X.names[S.frame] = S.nameText
	X.nameWrite = ""
	W.blizzard(W.env.UnitFrame_Update, S.frame)
	Z.kept = Z.row1.name.text
	X.nameWrite = "Boss Two"
	W.blizzard(W.env.UnitFrame_Update, S.frame)
	check("small row: a boss row keeps its name across an empty text and takes the next", Z.kept == "Boss One" and Z.row1.name.text == "Boss Two", tostring(Z.kept) .. tostring(Z.row1.name.text))
	-- A boss whose level the game cannot tell shows two question marks.
	X.skull = true
	W.blizzard(function() S.frame:CheckLevel() end)
	Z.skull = Z.row1.level.text == "??" and Z.row1.level.shown
	X.skull = false
	W.blizzard(function() S.frame:CheckLevel() end)
	check("small row: a boss level the game shows as a skull is two question marks in the row, and the number is back", Z.skull and Z.row1.level.text == "63", tostring(Z.row1.level.text))
	-- With the strip hidden the row takes the reaction colour of the unit, and none when the client gives none.
	W.env.UnitSelectionColor = function(unit) return unit == "boss1" and 0.9 or nil, 0.1, 0.1, 1 end
	W.blizzard(function() S.strip:Hide() end)
	W.blizzard(function() S.frame:CheckFaction() end)
	Z.reaction = rgb(Z.row1.fill.color)
	W.env.UnitSelectionColor = function() return nil end
	W.blizzard(function() S.frame:CheckFaction() end)
	Z.dark = Z.row1.fill.color and rgb(Z.row1.fill.color)
	check("small row: a boss row with no strip shown has the reaction colour of boss1, and the dark row when the client gives none", Z.reaction == "0.63,0.07,0.07" and Z.dark == "0.06,0.06,0.06" and not Z.row1.mark.shown,
		tostring(Z.reaction) .. " " .. tostring(Z.dark))
	-- The party pet frame: the colour of its owner's class, the picture from the top of the row, and the row's height in the picture.
	local pet = X.pet
	W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
	W.rawOf[W.rawOf[pet.frame].parent].layoutIndex = 1
	W.env.UnitClass = function(unit) return unit == "party1" and "Priest" or nil, unit == "party1" and "PRIEST" or nil, 5 end
	W.env.RAID_CLASS_COLORS = { PRIEST = setmetatable({ r = 0.8, g = 0.9, b = 1, a = 1 }, COLOUR_MT) }
	W.change("unitframes.smallRow", false)
	Z.noPetRow = not Z.shown(pet.frame)
	Z.flatTop, Z.flatSide = overlay(W, pet.portrait).points[1][5], overlay(W, pet.portrait).height
	W.change("unitframes.smallRow", true)
	Z.petRow = Z.row(pet.frame)
	Z.rowTop, Z.rowSide = overlay(W, pet.portrait).points[1][5], overlay(W, pet.portrait).height
	check("small row: a party pet frame has a row in the class colour of its owner, which Name row on small frames turns off", Z.noPetRow and Z.petRow ~= nil and Z.petRow.name.shown and rgb(Z.petRow.fill.color) == "0.56,0.63,0.70"
		and Z.petRow.frame.height == 13, Z.petRow and rgb(Z.petRow.fill.color) or "none")
	check("small row: the picture of a party pet starts at the top of the row and is 13 units taller, ending at its health bar", Z.rowTop == 13 and Z.flatTop == 0 and Z.rowSide - Z.flatSide == 13, tostring(Z.rowTop) .. " " .. tostring(Z.flatTop) .. " " .. tostring(Z.rowSide) .. " " .. tostring(Z.flatSide))
end

-- The level and PvP plates, the strip and the name of a target: the name row covers them.
do
	local X = xWorld()
	local W, T = X.W, X.target
	-- The name row of the target frame: its layers and its five font strings.
	local function rowOf(world, frame)
		for _, f in ipairs(world.addonFrames) do
			if f.parent == frame then
				local row = { frame = f, text = {} }
				for _, r in ipairs(f.regions) do
					if r.kind == "FontString" then
						row.text[#row.text + 1] = r
					elseif r.layer == "BACKGROUND" and r.sublevel == -8 then
						row.base = r
					elseif r.layer == "BACKGROUND" then
						row[row.grad and "fill" or "grad"] = r
					elseif r.layer == "ARTWORK" and r.sublevel == 1 then
						row.line = r
					elseif r.layer == "ARTWORK" then
						row.mark = r
					end
				end
				if #row.text == 5 then
					row.level, row.name, row.kindMark, row.kindWord, row.flag = row.text[1], row.text[2], row.text[3], row.text[4], row.text[5]
					return row
				end
			end
		end
	end
	-- The four edges of the thicker border of the picture over a portrait.
	local function rimOf(world, portrait)
		local frame = overlay(world, portrait)
		for _, f in ipairs(world.addonFrames) do
			if f.allPoints == frame then
				return world.edgesOn(f)
			end
		end
	end
	local row = rowOf(W, T.frame)
	check("badges: the level plate, the level number and the strip are transparent and keep the game's atlas, the PvP plate is not, and with no CreateColor the row is flat in the strip's colour at 70 percent",
		alphaOf(W, T.level) == "0" and alphaOf(W, T.pvp) == "1" and alphaOf(W, T.levelText) == "0" and alphaOf(W, T.strip) == "0" and W.rawOf[T.level].atlas == LEVEL and W.rawOf[T.pvp].atlas == LEVEL
		and W.rawOf[T.strip].atlas == STRIP and W.rawOf[T.level].color == nil and row.grad.shown == false and row.fill.shown == true and rgb(row.fill.color) == "0.14,0.56,0.28"
		and row.fill.color[4] == 0.95 and #W.edgesOn(row.frame) == 0, tostring(row.fill.shown) .. tostring(row.fill.color and rgb(row.fill.color)) .. table.concat({ alphaOf(W, T.level), alphaOf(W, T.pvp), alphaOf(W, T.levelText), alphaOf(W, T.strip), tostring(W.rawOf[T.level].atlas == LEVEL), tostring(W.rawOf[T.pvp].atlas == LEVEL), tostring(W.rawOf[T.strip].atlas == STRIP), tostring(W.rawOf[T.level].color) }, ","))
	local boxed = false
	for _, f in ipairs(W.addonFrames) do
		boxed = boxed or (f.points[1] ~= nil and f.points[1][2] == T.levelText)
	end
	check("badges: no frame of the addon's is anchored to the level number, so there is no box behind it", not boxed)
	X.reaction = { 1, 0.2, 0.4 }
	W.blizzard(function() T.frame:CheckFaction() end)
	check("badges: a colour the game gives the strip later is the colour of the row, and the strip stays transparent", rgb(row.fill.color) == "0.70,0.14,0.28" and alphaOf(W, T.strip) == "0")
	X.skull = true
	W.blizzard(function() T.frame:CheckLevel() end)
	local skull = row.level.text == "??" and row.level.shown and alphaOf(W, T.level) == "0" and alphaOf(W, T.high) == "0"
	X.skull = false
	W.blizzard(function() T.frame:CheckLevel() end)
	check("badges: a level the game hides for a skull is two question marks in the row, and the number is back with it", skull and row.level.shown and alphaOf(W, T.level) == "0")
	W.blizzard(function() T.frame:CheckBattlePet() end)
	local pet = not row.level.shown
	T.levelText:Show()
	W.blizzard(function() T.frame:CheckClassification() end)
	check("badges: a level number the game hides for a battle pet leaves the row without a level, and the level is back when the game shows it", pet and row.level.shown)
	T.boss:SetAtlas("UI-HUD-UnitFrame-Target-PortraitOn-Boss-Gold")
	T.boss:Show()
	X.class = "elite"
	W.fire("PLAYER_TARGET_CHANGED")
	local gold = rgb(rimOf(W, T.portrait)[1].color)
	T.boss:SetAtlas("UI-HUD-UnitFrame-Target-PortraitOn-Boss-Rare-Silver-Winged")
	X.class = "rare"
	W.fire("PLAYER_TARGET_CHANGED")
	check("badges: an elite target has a gold border on the picture, a rare one silver, the row has no border, and the dragon is transparent", gold == "1.00,0.82,0.00"
		and rgb(rimOf(W, T.portrait)[1].color) == "0.78,0.80,0.84" and #W.edgesOn(row.frame) == 0 and alphaOf(W, T.boss) == "0")
	W.change("unitframes.stripColour", "Dark with a colour mark")
	W.change("general.backdrop", "ff336699")
	check("badges: the dark row follows the background colour", rgb(row.fill.color) == "0.20,0.40,0.60" and row.mark.shown)
	W.change("general.backdrop", "ff0f0f0f")
	W.change("unitframes.stripColour", "Class or reaction colour")
	W.change("unitframes.levelPosition", "Hidden")
	check("badges: with the level hidden the plates and the number stay transparent and keep the game's atlas, the PvP plate is as it was, the row has no level, and the strip stays transparent", alphaOf(W, T.level) == "0" and alphaOf(W, T.pvp) == "1"
		and alphaOf(W, T.levelText) == "0" and W.rawOf[T.level].atlas == LEVEL and not row.level.shown and row.fill.shown and alphaOf(W, T.strip) == "0")
	W.change("unitframes.strip", false)
	check("badges: and with the name row off the strip has the alpha the game gave it, with the colour the game gave it, and the row shows nothing", alphaOf(W, T.strip) == "1"
		and W.rawOf[T.strip].atlas == STRIP and W.rawOf[T.strip].color == nil and rgb(W.rawOf[T.strip].vertex) == "1.00,0.20,0.40" and not row.fill.shown and not row.name.shown)
	local textures, frames = #W.addonTextures, #W.addonFrames
	W.change("unitframes.levelPosition", "End of the name row")
	W.change("unitframes.strip", true)
	check("badges: on again they are drawn as before and nothing is made twice", alphaOf(W, T.level) == "0" and row.fill.shown and row.level.shown and #W.addonTextures == textures
		and #W.addonFrames == frames and quiet(W), why(W))

	local N = xWorld({ prep = function(Y) Y.W.rawOf[Y.target.strip].fault.vertex = "secret" end })
	local nr = rowOf(N.W, N.target.frame)
	check("badges: a strip whose colour the game withholds gives the dark row without a mark, the strip is transparent, and the plates are still transparent",
		alphaOf(N.W, N.target.strip) == "0" and nr.fill.shown and not nr.mark.shown and alphaOf(N.W, N.target.level) == "0" and quiet(N.W), why(N.W))
end

-- Party pets: the pet frame of a party member, made when the party frame first shows.
do
	local X = xWorld()
	local W, P = X.W, X.pet
	W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
	check("party pet: the frame art and the threat glow are transparent, the health bar has a border and a background, its fill is one colour, and nothing is drawn on the portrait's frame",
		alphaOf(W, P.art) == "0" and alphaOf(W, P.flash) == "0" and W.state(P.health) == "SB" and ringOf(W, P.health, 1) and rgb(W.rawOf[P.healthFill].color) == GREEN
		and onFrameOf(W, P.portrait) == 0, why(W))
	local textures = #W.addonTextures
	W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
	check("party pet: the party frame showing again makes nothing twice", #W.addonTextures == textures and quiet(W), why(W))
	-- The switch of the party pet frames hides the game's portrait of that frame, and the switch of another kind of frame does not.
	do
		local Q = { game = W.rawOf[P.portrait] }
		Q.on = Q.game.shown
		W.change("unitframes.portraitTarget", false)
		Q.other = Q.game.shown
		W.change("unitframes.portraitTarget", true)
		W.change("unitframes.portraitPartypet", false)
		Q.off = Q.game.shown
		W.change("unitframes.portraitPartypet", true)
		check("portrait look: the switch of the party pet frames hides the portrait of that frame and no other switch does", Q.on == true and Q.other == true and Q.off == false and Q.game.shown == true and quiet(W),
			tostring(Q.on) .. tostring(Q.other) .. tostring(Q.off) .. why(W))
		-- Its border is the class of its owner.
		W.rawOf[P.frame].unit = "partypet1"
		W.env.UnitClass = function(unit) return "Mage", unit == "party1" and "MAGE" or "WARLOCK", 8 end
		W.env.RAID_CLASS_COLORS = { MAGE = setmetatable({ r = 0.25, g = 0.78, b = 0.92, a = 1 }, COLOUR_MT), WARLOCK = setmetatable({ r = 0.58, g = 0.51, b = 0.79, a = 1 }, COLOUR_MT) }
		W.change("unitframes.portraitBorder", "Class or reaction colour")
		Q.edges = W.edgesOn(overlay(W, P.portrait))
		check("portrait look: the border of a party pet is the class colour of its owner", #Q.edges == 4 and rgb(Q.edges[1].color) == "0.25,0.78,0.92" and quiet(W), tostring(Q.edges[1] and rgb(Q.edges[1].color)) .. why(W))
		W.change("unitframes.portraitBorder", "Thin")
	end
	W.blizzard(function() W.env.UnitFrameHealthBar_Update(P.health) end)
	local solid = table.concat(W.rawOf[P.health].tint, ",")
	W.change("general.barTexture", "Soft shade")
	W.blizzard(function() W.env.UnitFrameHealthBar_Update(P.health) end)
	local image = rgb(W.rawOf[P.health].tint)
	W.change("general.barTexture", "Flat")
	W.blizzard(function() W.env.UnitFrameHealthBar_Update(P.health) end)
	check("party pet: the green tint the game gives the health bar with each update is white under a solid fill and the health colour under an image", solid == "1,1,1,1" and image == GREEN
		and table.concat(W.rawOf[P.health].tint, ",") == "1,1,1,1", solid .. " " .. image)
	W.change("unitframes.partypet", false)
	check("party pet: with its switch off the bar has the game's tint again", table.concat(W.rawOf[P.health].tint, ",") == "0,1,0,1", table.concat(W.rawOf[P.health].tint, ","))
	W.change("unitframes.partypet", true)
	W.change("unitframes.partypet", false)
	check("party pet: its switch puts the game's look back exactly", #W.diff("partypet") == 0 and W.state(P.health) == "hb", table.concat(W.diff("partypet"), "; "):sub(1, 200))
end

-- Raid frames, and the party frames in raid style.
do
	local X = xWorld()
	local W = X.W
	local R = X.raidFrame("CompactRaidGroup1Member1", "raid")
	local pets = X.raidFrame("CompactPartyFramePet1", "raidpet")
	local plate = X.raidFrame("NamePlate1UnitFrame", "plate")
	local locked = X.raidFrame("CompactRaidGroup2Member1", "locked", true)
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(plate.frame) end)
	X.update(plate)
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(locked.frame) end)
	check("raid: a frame that is not a raid frame, and a forbidden one, are not touched", #W.addonFrames == frames and #W.addonTextures == textures and alphaOf(W, plate.background) == "1"
		and W.state(plate.health) == "." and quiet(W), why(W))
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(R.frame) end)
	X.update(R)
	check("raid: the background and the outlines of the game are transparent, even after the game gives them their alpha again", alphaOf(W, R.background) == "0" and alphaOf(W, R.select) == "0"
		and alphaOf(W, R.aggro) == "0")
	check("raid: the health bar has a thin border and a background, and its fill is white, so the colour the game gives the bar is the colour seen", W.state(R.health) == "SB" and ringOf(W, R.health, 1)
		and rgb(W.rawOf[R.healthFill].color) == WHITE and table.concat(W.rawOf[R.health].tint, ",") == "0.78,0.61,0.43,1")
	X.targeted[R.frame] = true
	X.update(R)
	local target = colourOf(W, R.health)
	X.threat[R.frame] = { 1, 0.5, 0 }
	X.update(R)
	local both = colourOf(W, R.health)
	X.targeted[R.frame] = false
	X.update(R)
	local threat = colourOf(W, R.health)
	X.threat[R.frame] = nil
	X.update(R)
	check("raid: target is a white border, threat the colour of the game's outline, target over threat, and neither a plain border; the outlines stay transparent",
		target == WHITE and both == WHITE and threat == THREAT and colourOf(W, R.health) == PLAIN and alphaOf(W, R.select) == "0" and alphaOf(W, R.aggro) == "0", target .. " " .. both .. " " .. threat)
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(pets.frame) end)
	check("raid: the pet frames of raid-style party frames are styled the same way, and the status says the buffs and debuffs are the game's", W.state(pets.health) == "SB" and alphaOf(W, pets.background) == "0"
		and has(W.status(), "Unit frames: the buffs and debuffs on raid frames are drawn by the game and keep their default look.") and has(W.line("Unit frames"), ", 11 styled") == false)
	textures = #W.addonTextures
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(R.frame) end)
	X.update(R)
	check("raid: setting a frame up again makes nothing twice", #W.addonTextures == textures and quiet(W), why(W))
	W.change("unitframes.raid", false)
	W.flush()
	check("raid: its switch puts the game's look back: the outlines and the background are visible, the fill is the game's, and the borders are hidden", alphaOf(W, R.background) == "1"
		and alphaOf(W, R.select) == "1" and W.rawOf[R.healthFill].atlas == "RaidFrame-Hp-Fill" and W.rawOf[R.healthFill].color == nil and W.state(R.health) == "hb"
		and #W.diff("raidpet") == 0, table.concat(W.diff("raidpet"), "; "):sub(1, 200))
	W.change("unitframes.raid", true)
	check("raid: on again the frames are styled as before", W.state(R.health) == "SB" and alphaOf(W, R.background) == "0" and rgb(W.rawOf[R.healthFill].color) == WHITE and #W.addonTextures == textures)

	local C = xWorld({ combat = true })
	local Rc = C.raidFrame("CompactRaidGroup1Member1", "raid")
	local frames = #C.W.addonFrames
	C.W.blizzard(function() C.W.env.CompactUnitFrame_SetUpFrame(Rc.frame) end)
	check("combat: a raid frame set up in combat and the aura icons at login keep the game's look, and nothing is made", #C.W.addonFrames == frames and alphaOf(C.W, Rc.background) == "1"
		and C.W.state(Rc.health) == "." and C.W.state(C.debuffs[1].icon) == "." and alphaOf(C.W, C.debuffs[1].border) == "1" and quiet(C.W), why(C.W))
	C.W.combat = false
	C.W.fire("PLAYER_REGEN_ENABLED")
	C.W.flush()
	check("combat: when combat ends they are styled", C.W.state(Rc.health) == "SB" and alphaOf(C.W, Rc.background) == "0" and C.W.state(C.debuffs[1].icon) == "Sb"
		and alphaOf(C.W, C.debuffs[1].border) == "0" and quiet(C.W), why(C.W))
end

-- Raid cells: a thin power bar with its own border, and grey for a unit that is dead or offline.
do
	local Q = { X = xWorld() }
	local W, X = Q.X.W, Q.X
	-- The y offset of the bottom right point of a bar, as the client keeps it.
	function Q.bottom(bar)
		for _, p in ipairs(W.rawOf[bar].points) do
			if p[1] == "BOTTOMRIGHT" then
				return p[5]
			end
		end
	end
	-- The plain fields of a frame of the game.
	function Q.fields(frame)
		local out = {}
		for k, v in pairs(W.rawOf[frame]) do
			if type(v) == "number" or type(v) == "string" or type(v) == "boolean" then
				out[k] = v
			end
		end
		return out
	end
	function Q.same(a, b)
		for k, v in pairs(a) do
			if b[k] ~= v then
				return false, k
			end
		end
		for k in pairs(b) do
			if a[k] == nil then
				return false, k
			end
		end
		return true
	end
	function Q.set(R)
		W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(R.frame) end)
		W.blizzard(function() W.env.CompactUnitFrame_UpdatePowerColor(R.frame) end)
		X.update(R)
	end
	Q.A = X.raidFrame("CompactRaidGroup1Member1", "raid", nil, { unit = "raid1" })
	Q.H = X.raidFrame("CompactRaidGroup1Member2", "raid", nil, { unit = "raid2", power = false })
	Q.N = X.raidFrame("CompactRaidGroup1Member3", "raid")
	local A, H, N = Q.A, Q.H, Q.N
	Q.set(A)
	Q.set(H)
	Q.set(N)
	check("raid cell: the power bar has a thin border and a background, and its fill is white under the colour the game gives it", W.state(A.power) == "SB" and ringOf(W, A.power, 1)
		and rgb(W.rawOf[A.powerFill].color) == WHITE and rgb(W.rawOf[A.power].tint) == BLUE, W.state(A.power) .. " " .. rgb(W.rawOf[A.powerFill].color) .. " " .. rgb(W.rawOf[A.power].tint))
	check("raid cell: the health bar ends 1 and 4 units above the bottom when the power bar shows, and the power bar keeps the game's anchors", Q.bottom(A.health) == 5
		and Q.bottom(A.power) == 1 and W.rawOf[A.power].points[1][2] == A.health, tostring(Q.bottom(A.health)) .. " " .. tostring(Q.bottom(A.power)))
	check("raid cell: a cell whose power bar is hidden is not moved", Q.bottom(H.health) == 1 and W.rawOf[H.power].shown == false and Q.bottom(N.health) == nil
		and quiet(W), tostring(Q.bottom(H.health)) .. " " .. why(W))
	Q.fields0 = Q.fields(A.frame)
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(A.frame) end)
	check("raid cell: the game setting the cell up again with each full update puts the thin bar back", Q.bottom(A.health) == 5 and Q.bottom(A.power) == 1, tostring(Q.bottom(A.health)))
	W.blizzard(function() W.env.CompactUnitFrame_SetUpFrame(A.frame) end)
	check("raid cell: the game setting the frame up puts the thin bar back", Q.bottom(A.health) == 5, tostring(Q.bottom(A.health)))
	W.blizzard(function() W.env.CompactUnitFrame_UpdatePowerColor(A.frame) end)
	check("raid cell: the game drawing the power colour again keeps the fill white and the colour the game's", rgb(W.rawOf[A.powerFill].color) == WHITE and rgb(W.rawOf[A.power].tint) == BLUE)
	-- The bar shows in a cell that had none.
	X.powerOn[H.frame] = true
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(H.frame) end)
	check("raid cell: a power bar the game shows later is thin as well, and its border shows", Q.bottom(H.health) == 5 and W.rawOf[H.power].shown == true and ringOf(W, H.power, 1), tostring(Q.bottom(H.health)))
	X.powerOn[H.frame] = false
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(H.frame) end)
	check("raid cell: when the power bar goes the health bar is the game's again", Q.bottom(H.health) == 1 and W.rawOf[H.power].shown == false and quiet(W), tostring(Q.bottom(H.health)))
	check("raid cell: no field of the game's frame is written", select(1, Q.same(Q.fields0, Q.fields(A.frame))) and W.rawOf[A.frame].powerBarUsedHeight == 8, select(2, Q.same(Q.fields0, Q.fields(A.frame))))
	check("raid cell: the status counts the frames that are thin", has(W.status(), "Raid cells: thin power bar on 1 of 3 frames") and not has(W.status(), "waiting for combat"), W.status():sub(-200))

	-- Combat: the cells stay as the game laid them until combat ends.
	W.combat = true
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(A.frame) end)
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(A.frame) end)
	check("raid cell: nothing is moved in combat, and the status says one cell waits", Q.bottom(A.health) == 9 and quiet(W) and has(W.status(), "Raid cells: thin power bar on 0 of 3 frames, waiting for combat on 1"),
		tostring(Q.bottom(A.health)) .. " " .. why(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("raid cell: when combat ends the thin bar is made once", Q.bottom(A.health) == 5 and quiet(W) and has(W.status(), "Raid cells: thin power bar on 1 of 3 frames") and not has(W.status(), "waiting for combat"),
		tostring(Q.bottom(A.health)) .. " " .. why(W))

	-- Grey.
	Q.unit = "raid1"
	function Q.tint() return rgb(W.rawOf[A.health].tint) end
	X.update(A)
	Q.alive = Q.tint()
	X.dead[Q.unit], X.player[Q.unit] = true, true
	X.update(A)
	Q.deadPlayer = Q.tint()
	X.player[Q.unit] = false
	X.update(A)
	Q.deadNpc = Q.tint()
	X.dead[Q.unit] = false
	X.offline[Q.unit] = true
	X.update(A)
	Q.offline = Q.tint()
	X.offline[Q.unit] = false
	X.update(A)
	check("raid cell: an alive unit keeps the colour the game gives", Q.alive == "0.78,0.61,0.43", Q.alive)
	check("raid cell: a dead player, a dead non-player and an offline unit are grey, and the colour comes back with the game's next update", Q.deadPlayer == "0.50,0.50,0.50" and Q.deadNpc == "0.50,0.50,0.50"
		and Q.offline == "0.50,0.50,0.50" and Q.tint() == Q.alive, Q.deadPlayer .. " " .. Q.deadNpc .. " " .. Q.offline .. " " .. Q.tint())
	-- A dead player is grey only with the look on.
	W.change("unitframes.raidCells", false)
	X.dead[Q.unit], X.player[Q.unit] = true, true
	X.update(A)
	Q.offDead = Q.tint()
	X.dead[Q.unit], X.player[Q.unit] = false, false
	check("raid cell: with the look off a dead player keeps the game's colour, the cell has the game's 8 units of power bar, and the power border is hidden", Q.offDead == Q.alive and Q.bottom(A.health) == 9
		and W.state(A.power) == "hb" and W.rawOf[A.powerFill].color == nil and W.state(A.health) == "SB" and has(W.status(), "Raid cells: off"),
		Q.offDead .. " " .. tostring(Q.bottom(A.health)) .. " " .. W.state(A.power))
	W.blizzard(function() W.env.CompactUnitFrame_UpdateAll(A.frame) end)
	check("raid cell: with the look off the game's set-up is left alone", Q.bottom(A.health) == 9 and Q.bottom(A.power) == 1 and quiet(W), tostring(Q.bottom(A.health)))
	W.change("unitframes.raidCells", true)
	check("raid cell: on again the bar is thin and styled as before", Q.bottom(A.health) == 5 and W.state(A.power) == "SB" and rgb(W.rawOf[A.powerFill].color) == WHITE and quiet(W), tostring(Q.bottom(A.health)))
	W.change("unitframes.raid", false)
	W.flush()
	check("raid cell: the raid switch puts the game's 8 units back, and the power border and fill are the game's", Q.bottom(A.health) == 9 and W.state(A.power) == "hb" and W.rawOf[A.powerFill].color == nil
		and W.state(A.health) == "hb", tostring(Q.bottom(A.health)) .. " " .. W.state(A.power))
	W.change("unitframes.raid", true)
	check("raid cell: with the raid switch on again the bar is thin", Q.bottom(A.health) == 5 and W.state(A.power) == "SB" and quiet(W), tostring(Q.bottom(A.health)))

	-- A client with no answer for the unit.
	W.env.UnitIsDead = nil
	X.dead[Q.unit], X.player[Q.unit] = true, true
	X.update(A)
	check("raid cell: a client with no UnitIsDead leaves the colour alone and raises nothing", Q.tint() == Q.alive and quiet(W), Q.tint())
	W.env.UnitIsDead = function() return X.dead[Q.unit] == true end
	X.dead[Q.unit] = false
	W.rawOf[A.frame].unit = nil
	X.offline[Q.unit] = true
	X.update(A)
	check("raid cell: a frame with no unit is not grey", Q.tint() == Q.alive and quiet(W), Q.tint())

	-- Bar looks leave a raid frame to the game: its fill is white under the colour the game gives, and it has no shadow.
	for _, key in ipairs({ "lookClassHealth", "lookLostColour", "lookMuted", "lookShadow" }) do
		W.change("unitframes." .. key, true)
	end
	X.update(A)
	Q.shadows = 0
	for _, t in ipairs(W.addonTextures) do
		Q.shadows = Q.shadows + (t.file and t.file:find("Shadow.tga", 1, true) and t.owner ~= nil and W.rawOf[t.owner].parent == A.frame and 1 or 0)
	end
	Q.looks = rgb(W.rawOf[A.healthFill].color) .. " " .. rgb(W.rawOf[A.health].tint)
	for _, key in ipairs({ "lookClassHealth", "lookLostColour", "lookMuted", "lookShadow" }) do
		W.change("unitframes." .. key, false)
	end
	check("bar looks: a raid frame keeps the colour of the game and has no shadow", Q.shadows == 0 and Q.looks == WHITE .. " 0.78,0.61,0.43" and quiet(W), tostring(Q.shadows) .. " " .. tostring(Q.looks) .. why(W))
end

-- Bar overlap: the power bar of the player frame hangs from the bottom of the health bar, in a secure snippet.
do
	local Q = {}
	local W = FH.ufWorld()
	local P, T = W.player, W.target
	local env = W.env
	-- The TOPLEFT point of a bar, as the client keeps it.
	function Q.top(bar)
		for _, p in ipairs(W.rawOf[bar].points) do
			if p[1] == "TOPLEFT" then
				return p
			end
		end
	end
	function Q.at(bar, relative, relativePoint, x, y)
		local p = Q.top(bar)
		return p ~= nil and p[2] == relative and p[3] == relativePoint and p[4] == x and math.abs(p[5] - y) < 0.001
	end
	function Q.show(bar)
		local p = Q.top(bar)
		return p and ("%s %s %s %s"):format(tostring(p[3]), tostring(p[4]), tostring(p[5]), p[2] == P.health and "health" or p[2] == P.main and "main" or "?") or "none"
	end
	-- The points and size of a bar, written out.
	function Q.layout(bar)
		local out = { tostring(W.rawOf[bar].width), tostring(W.rawOf[bar].height) }
		for _, p in ipairs(W.rawOf[bar].points) do
			out[#out + 1] = table.concat({ p[1], tostring(W.rawOf[p[2]] and W.rawOf[p[2]].name or p[2]), tostring(p[3]), tostring(p[4]), tostring(p[5]) }, "/")
		end
		return table.concat(out, " ")
	end
	function Q.game() return Q.at(P.power, P.main, "TOPLEFT", 85, -61) end
	function Q.gap() return math.max(1, W.ns.Pixels(P.power, 2)) end
	function Q.say() local gap = Q.gap() return math.abs(gap - 1) < 0.05 and "1 unit" or ("%.1f units"):format(gap) end
	function Q.hung() return Q.at(P.power, P.health, "BOTTOMLEFT", 0, -Q.gap()) end
	Q.status = W.status()
	check("bar overlap: the player's power bar hangs under the health bar by the two edges of the borders at border thickness 1, at least the game's 1 unit", Q.hung() and has(Q.status, "Player bars: " .. Q.say() .. " apart") and not has(Q.status, "overlapping"), Q.show(P.power) .. " " .. Q.status:sub(-200))
	Q.edge = W.ns.Pixels(P.power, 1)
	check("bar overlap: below 1 pixel per unit the gap is at least the two edges of the borders, so neither edge covers the other bar's fill", Q.edge > 1 and Q.gap() >= 2 * Q.edge - 1e-6 and Q.hung(), Q.show(P.power) .. " " .. tostring(Q.edge))
	Q.sizes = { power = Q.layout(P.power), health = Q.layout(P.health), box = Q.layout(P.box), area = Q.layout(P.area) }
	Q.others = {}
	W.blizzard(function() env.PartyFrame:InitializePartyMemberFrames() end)
	for _, bar in ipairs({ T.power, W.focus.power, W.pet.power, W.members[1].power }) do
		Q.others[bar] = Q.layout(bar)
	end
	-- Every SetPoint the addon's own code calls on the power bar is counted: the game's calls run in its functions, the snippet's in secure code.
	Q.direct = 0
	do
		local raw = W.rawOf[P.power]
		local setPoint = raw.SetPoint
		raw.SetPoint = function(...)
			if not W.inSecure and (W.inBlizzard == 0 or (W.inHook or 0) > 0) then
				Q.direct = Q.direct + 1
			end
			return setPoint(...)
		end
	end
	Q.ran = W.executed or 0
	W.change("general.thickness", 3)
	W.flush()
	Q.six = W.ns.Pixels(P.power, 6)
	check("bar overlap: the bar is moved in a secure snippet and Flat UI's code never calls its SetPoint", Q.direct == 0 and (W.executed or 0) > Q.ran and quiet(W), tostring(Q.direct) .. " " .. tostring(W.executed) .. " " .. why(W))
	check("bar overlap: at border thickness 3 the bars are 6 pixels apart", Q.at(P.power, P.health, "BOTTOMLEFT", 0, -Q.six) and Q.six > 1, Q.show(P.power) .. " " .. tostring(Q.six))
	W.change("general.thickness", 1)
	W.flush()
	W.blizzard(env.PlayerFrame_ToPlayerArt)
	W.flush()
	check("bar overlap: the game laying the frame out again puts the bar back under the health bar", Q.hung() and Q.direct == 0 and quiet(W), Q.show(P.power))
	W.blizzard(env.PlayerFrame_ToVehicleArt)
	W.flush()
	Q.vehicle = Q.hung()
	W.change("unitframes.player", false)
	Q.vehicleOff = Q.at(P.power, P.main, "TOPLEFT", 91, -61)
	check("bar overlap: vehicle art keeps the bar under the health bar at x 0, and the look off gives back 91,-61", Q.vehicle and Q.vehicleOff and quiet(W), Q.show(P.power))
	W.blizzard(env.PlayerFrame_ToPlayerArt)
	W.flush()
	check("bar overlap: with the look off the power bar goes back to the game's point", Q.game() and has(W.status(), "Player bars: the game's layout") and Q.direct == 0, Q.show(P.power) .. " " .. W.status():sub(-200))
	W.change("unitframes.player", true)
	W.flush()
	check("bar overlap: the bar's height and width and the health bar's points are unchanged", Q.hung() and Q.layout(P.health) == Q.sizes.health and Q.layout(P.box) == Q.sizes.box and Q.layout(P.area) == Q.sizes.area
		and W.rawOf[P.power].width == 124 and W.rawOf[P.power].height == 10, Q.layout(P.health) .. " | " .. Q.sizes.health)
	-- Combat: the game's point stays until combat ends.
	W.combat = true
	W.blizzard(env.PlayerFrame_ToPlayerArt)
	W.flush()
	Q.inCombat = Q.game() and has(W.status(), "Player bars: waiting for the end of combat")
	Q.quiet = quiet(W)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("bar overlap: in combat nothing is written, and the bar moves when combat ends", Q.inCombat and Q.quiet and Q.direct == 0 and Q.hung() and quiet(W), Q.show(P.power) .. " " .. why(W))
	check("bar overlap: target, focus, pet and party power bars keep the game's anchors", Q.layout(T.power) == Q.others[T.power] and Q.layout(W.focus.power) == Q.others[W.focus.power]
		and Q.layout(W.pet.power) == Q.others[W.pet.power] and Q.layout(W.members[1].power) == Q.others[W.members[1].power], Q.layout(T.power))
	-- The game's own layout overlaps by 2 units here: the status says so.
	W.uf.powerY = -58
	W.blizzard(env.PlayerFrame_ToPlayerArt)
	W.flush()
	check("bar overlap: the status line says the gap and the game's overlap", Q.hung() and has(W.status(), "Player bars: " .. Q.say() .. " apart. The game's layout had them overlapping by 2.0 units"), W.status():sub(-200))
end

-- Unit menu: a right-click on the target frame opens its menu at the cursor.
do
	local Q = { cursor = { 400, 300 } }
	local W = FH.ufWorld()
	local P, T = W.player, W.target
	local env = W.env
	local menu = W.B(nil, {}, {})
	local raw = W.rawOf[menu]
	-- What the game does: UnitPopup_OpenMenu opens the menu at the cursor, and TargetFrame_OpenMenu moves it beside the frame (Mainline/TargetFrame.lua:670-673).
	function Q.open(beside)
		Q.menu = menu
		W.blizzard(function()
			raw.ClearAllPoints(menu)
			raw.SetPoint(menu, "TOPLEFT", env.UIParent, "BOTTOMLEFT", Q.cursor[1], Q.cursor[2])
			raw.ClearAllPoints(menu)
			raw.SetPoint(menu, "LEFT", beside or T.frame, "RIGHT")
		end)
	end
	env.Menu = { GetManager = function() return { GetOpenMenu = function() return Q.menu end } end }
	env.InputUtil = { IsGamepadUIEnabled = function() return Q.gamepad == true end,
		AnchorRegionToCursor = function(region, point)
			W.blizzard(function()
				W.rawOf[region].ClearAllPoints(region)
				W.rawOf[region].SetPoint(region, point, env.UIParent, "BOTTOMLEFT", Q.cursor[1], Q.cursor[2])
			end)
		end }
	function Q.point()
		local p = raw.points[1]
		return p and ("%s %s %s %s %s"):format(p[1], p[2] == T.frame and "target" or p[2] == env.UIParent and "UIParent" or "other", tostring(p[3]), tostring(p[4]), tostring(p[5])) or "none"
	end
	function Q.click(button, down)
		W.hookRun(T.frame, "PostClick", button, down)
	end
	function Q.fields(frame)
		local out = {}
		for k, v in pairs(W.rawOf[frame]) do
			if type(v) == "number" or type(v) == "string" or type(v) == "boolean" then
				out[#out + 1] = k .. "=" .. tostring(v)
			end
		end
		table.sort(out)
		return table.concat(out, ",")
	end
	-- The scripts a frame has hooks on, leaving PostClick out.
	function Q.hooksOther(frame)
		local out = {}
		for which in pairs(W.rawOf[frame].hookScripts or {}) do
			if which ~= "PostClick" then
				out[#out + 1] = which
			end
		end
		table.sort(out)
		return table.concat(out, ",")
	end
	Q.before = Q.fields(T.frame)
	Q.open()
	Q.click("RightButton", false)
	check("unit menu: a right-click on the target frame opens its menu at the cursor", Q.point() == "TOPLEFT UIParent BOTTOMLEFT 400 300" and quiet(W), Q.point() .. " " .. why(W))
	Q.open()
	Q.click("LeftButton", false)
	Q.left = Q.point()
	Q.click("RightButton", true)
	check("unit menu: a left-click moves no menu", Q.left == "LEFT target RIGHT nil nil" and Q.point() == Q.left, Q.left .. " | " .. Q.point())
	W.combat = true
	Q.open()
	Q.click("RightButton", false)
	check("unit menu: in combat the menu keeps the game's point beside the frame and nothing is blocked", Q.point() == "LEFT target RIGHT nil nil" and quiet(W), Q.point() .. " " .. why(W))
	W.combat = false
	Q.gamepad = true
	Q.open()
	Q.click("RightButton", false)
	check("unit menu: with the gamepad interface the menu keeps the game's point", Q.point() == "LEFT target RIGHT nil nil", Q.point())
	Q.gamepad = false
	Q.open(P.frame)
	Q.click("RightButton", false)
	check("unit menu: a menu that is not anchored to the target frame is left alone", Q.point() == "LEFT other RIGHT nil nil", Q.point())
	Q.open()
	Q.click("RightButton", false)
	Q.again = Q.point()
	check("unit menu: the target frame's attributes and click script are the game's, and the only hook is PostClick", Q.fields(T.frame) == Q.before and Q.again == "TOPLEFT UIParent BOTTOMLEFT 400 300"
		and W.rawOf[T.frame].hookScripts ~= nil and #W.rawOf[T.frame].hookScripts.PostClick == 1 and Q.hooksOther(T.frame) == Q.hooksOther(W.focus.frame) and W.rawOf[T.frame].script == nil
		and next(W.rawOf[T.frame].attributes or {}) == nil, tostring(Q.fields(T.frame) == Q.before) .. tostring(Q.again) .. tostring(W.rawOf[T.frame].script) .. tostring(next(W.rawOf[T.frame].attributes or {})) .. tostring(#W.rawOf[T.frame].hookScripts.PostClick))
	check("unit menu: the player and focus frames get no hook", (W.rawOf[P.frame].hookScripts or {}).PostClick == nil and (W.rawOf[W.focus.frame].hookScripts or {}).PostClick == nil)
	W.change("unitframes.target", false)
	W.flush()
	Q.open()
	Q.click("RightButton", false)
	check("unit menu: with the unit frames look off the menu opens beside the frame as the game puts it", Q.point() == "LEFT target RIGHT nil nil" and quiet(W), Q.point() .. " " .. why(W))
end

-- Totem buttons: the ring is transparent and the round icon is a square with a thin border.
do
