	W.blizzard(function() W.env.TotemFrame:Update() end)
	check("totem: the ring is transparent, the icon has no mask, and the icon has a border and a background", alphaOf(W, T.border) == "0" and masks(W, T.texture) == 0 and W.state(T.icon) == "SB" and ringOf(W, T.icon, 1), why(W))
	local frames, textures = #W.addonFrames, #W.addonTextures
	W.blizzard(function() W.env.TotemFrame:Update() end)
