	local textures = #W.addonTextures
	W.blizzard(function() X.target.frame:UpdateAuras() end)
	W.change("unitframes.auras", false)
	local back = near(W.rawOf[D.icon].texCoord[2], 1) and alphaOf(W, D.border) == "1" and W.state(D.icon) == "hb" and alphaOf(W, buff.stealable) == "1" and W.state(buff.icon) == "hb"
	W.change("unitframes.auras", true)
	check("auras: the switch gives the game's icons back, and on again they are styled as before with nothing made twice", back and W.state(D.icon) == "Sb" and colourOf(W, debuff.icon) == CURSE
		and #W.addonTextures == textures and quiet(W), why(W))

	local A = xWorld({ auraBox = true })
	check("auras: a container the addon may not touch is left alone, with a note", has(A.W.status(), "Unit frames: the game blocks addons from the aura icons on the target and focus frames. They keep their default look.")
		and A.W.state(A.debuffs[1].icon) == "Sb" and quiet(A.W), why(A.W))
	local K = xWorld({ auraButtons = true })
	check("auras: buttons the addon may not touch are left alone, with the same note, and the other icons are still styled", has(K.W.status(), "They keep their default look.")
		and K.W.state(K.debuffs[1].icon) == "Sb" and #K.W.violations == 0 and #K.W.errors == 0, why(K.W))
end

