-- 111. Tracker, loot, alerts, timers, queue panel, damage meter and zone event bars (Hud.lua), in a world built here.
do
(function()
local NINE = { "TopLeftCorner", "TopRightCorner", "BottomLeftCorner", "BottomRightCorner", "TopEdge", "BottomEdge", "LeftEdge", "RightEdge", "Center" }
local BAR_FILE = "Interface\\TargetingFrame\\UI-StatusBar"
local ROLL_FILE = "Interface\\PaperDollInfoFrame\\UI-Character-Skills-Bar"
local STRIPES = "Interface\\AddOns\\FlatUI\\Media\\Stripes.tga"
local GREEN, BLUE = { 0.12, 0.75, 0.12 }, { 0, 0.44, 0.87 }
local ALL = { "trackerHeaders", "trackerBars", "trackerItems", "lootWindow", "lootRolls", "alerts", "mirror", "countdown", "queue", "meter", "zoneBars" }
local BAR_ART = { "BorderLeft", "BorderRight", "BorderMid" }
local WIDGET_ART = { "BorderLeft", "BorderRight", "BorderCenter", "BGLeft", "BGRight", "BGCenter" }

-- more.saved, more.combat; more.forbidden: the queue panel is forbidden; more.protected: it is protected; more.secret: the quest module's bars are withheld;
-- more.faulty: bars the client cannot put a texture on.
local function world(more)
	more = more or {}
	local W = newWorld({ hud = true, saved = more.saved, combat = more.combat })
	local env, B, R, Rr, rawOf = W.env, W.B, W.R, W.Rr, W.rawOf
	local X = { W = W, bars = {}, rows = {} }
	W.group = "other"
	local hook = env.hooksecurefunc
	env.hooksecurefunc = function(a, b, c)
		if type(a) == "string" then
			return hook(env, a, b)
		end
		return hook(a, b, c)
	end
	local function set(name, value)
		env[name] = value
		return value
	end
	local function parts(list)
		local out = {}
		for _, key in ipairs(list) do
			out[key] = R(nil, "x-" .. key)
		end
		return out
	end
	-- A status bar with a fill the game draws from a file or an atlas, and the colour the game gives the bar.
	local function bar(file, atlas, fields, name, tint)
		local fill, fillRaw = Rr(nil, atlas)
		fillRaw.file = file
		local status, raw = B(nil, fields or {}, { name = name })
		raw.tint = tint or { 1, 1, 1, 1 }
		raw.GetStatusBarTexture = function() return fill end
		raw.SetStatusBarTexture = function(_, asset)
			fillRaw.color = nil
			if asset:find("[\\/]") then
				fillRaw.atlas, fillRaw.file = nil, asset
			else
				fillRaw.atlas, fillRaw.file = asset, nil
			end
			return true
		end
		raw.SetColorFill = function(_, r, g, b, a) fillRaw.color, fillRaw.atlas, fillRaw.file = { r, g, b, a }, nil, nil end
		raw.SetStatusBarColor = function(_, r, g, b, a) raw.tint = { r, g, b, a or 1 } end
		return status, raw, fill
	end

	-- Objective tracker: a header, the quest module with its header, a progress bar, a timer bar and two buttons.
	X.trackerBack = R(nil, "ui-questtracker-primary-objective-header")
	X.tracker = set("ObjectiveTrackerFrame", B(nil, { Header = B(nil, { Background = X.trackerBack }) }))
	X.mod = { Background = R(nil, "UI-QuestTracker-Secondary-Objective-Header"), Shine = R(nil, "UI-QuestTracker-OBJFX-Shine"),
		Glow = R(nil, "UI-QuestTracker-OBJFX-BarGlow"), AddAnim = {} }
	X.modHeader = B(nil, X.mod)
	function X.trackerBar(bonus)
		local art = bonus and { BarFrame = R(nil, "bonusobjectives-bar-frame-5"), IconBG = R(nil, "bonusobjectives-bar-ring") } or parts(BAR_ART)
		local status, raw, fill = bar(BAR_FILE, nil, art, nil, { 0.26, 0.42, 1, 1 })
		local entry = { holder = B(nil, { Bar = status }), bar = status, raw = raw, fill = fill, art = art }
		if more.faulty then
			rawOf[entry.holder].fault.createTexture = true
		end
		X.bars[#X.bars + 1] = entry
		return entry
	end
	X.first, X.timer = X.trackerBar(), X.trackerBar()
	X.quest = set("QuestObjectiveTracker", B(nil, { Header = X.modHeader, usedProgressBars = more.secret and SECRET or { line1 = X.first.holder },
		usedTimerBars = { line1 = X.timer.holder }, usedRightEdgeFrames = {} }))
	local questRaw = rawOf[X.quest]
	FH.hookable(W, questRaw, "OnSizeChanged")
	questRaw.GetProgressBar = function(_, key)
		local used = questRaw.usedProgressBars
		used[key] = used[key] or X.trackerBar(key == "bonus").holder
		return used[key]
	end
	questRaw.GetTimerBar = function(_, key)
		questRaw.usedTimerBars[key] = questRaw.usedTimerBars[key] or X.trackerBar().holder
		return questRaw.usedTimerBars[key]
	end
	function X.itemButton()
		local normal, pushed = R(nil, "UI-QuestTrackerButton-QuestItem-Frame"), R(nil, "UI-QuestTrackerButton-QuestItem-Frame")
		return B(nil, { NormalTexture = normal, GlowAnim = {}, GetPushedTexture = function() return pushed end, icon = R(nil, nil) }), normal, pushed
	end
	X.item, X.itemNormal, X.itemPushed = X.itemButton()
	X.find = B(nil, { NormalTexture = R(nil, "x") })
	questRaw.usedRightEdgeFrames.item, questRaw.usedRightEdgeFrames.find = X.item, X.find
	X.itemMixin = set("QuestObjectiveItemButtonMixin", { SetUp = function() end })

	-- Loot window with a card for an uncommon item. The game copies the mixin onto the cards it makes, and sets the colour of a card in Init.
	X.rowMixin = set("LootFrameElementMixin", { Init = function(self)
		local colour = rawOf[self].quality
		rawOf[rawOf[self].NameFrame].vertex = { colour[1], colour[2], colour[3], 1 }
	end })
	function X.row(colour)
		local art = parts({ "NormalTexture", "PushedTexture", "IconBorder" })
		art.icon = R(nil, nil)
		local name, border = R(nil, "looting_itemcard_bg"), R(nil, "looting_itemcard_stroke_normal")
		rawOf[name].vertex = { colour[1], colour[2], colour[3], 1 }
		local item = B(nil, art)
		local frame, raw = B(nil, { Item = item, NameFrame = name, BorderFrame = border })
		raw.Init, raw.quality = X.rowMixin.Init, colour
		local entry = { frame = frame, item = item, art = art, name = name, border = border }
		X.rows[#X.rows + 1] = entry
		return entry
	end
	X.card = X.row(GREEN)
	X.nine = parts({ "TopLeftCorner", "TopRightCorner", "BottomLeftCorner", "BottomRightCorner", "TopEdge", "BottomEdge", "LeftEdge", "RightEdge" })
	X.fill = parts({ "BottomLeft", "BottomRight", "BottomEdge", "TopSection" })
	X.target = B(nil, {})
	rawOf[X.target].children = { X.card.frame }
	X.loot = set("LootFrame", B(nil, { NineSlice = B(nil, X.nine), Bg = B(nil, X.fill), ScrollBox = B(nil, { ScrollTarget = X.target }) }))

	-- A roll: the border the game colours by quality, the ring round the icon and a timer bar. The game's call also gives the border its alpha back.
	X.rollBorder, X.ring = R(nil, "x-border"), R(nil, "loottoast-itemborder-green")
	rawOf[X.rollBorder].vertex = { GREEN[1], GREEN[2], GREEN[3], 1 }
	X.rollTimer, X.rollTimerRaw, X.rollFill = bar(ROLL_FILE, nil, nil, nil, { 1, 1, 0, 1 })
	X.roll = set("GroupLootFrame1", B(nil, { Border = X.rollBorder, IconFrame = B(nil, { Border = X.ring, Icon = R(nil, nil) }), Timer = X.rollTimer }))
	set("GroupLootFrame_SetupItemDisplay", function(self)
		self.Border:SetVertexColor(BLUE[1], BLUE[2], BLUE[3])
		self.Border:SetAlpha(1)
	end)

	-- Alerts: a loot toast in the pool, and a system that hands out toasts for money.
	function X.toast(coin)
		local art = coin and { Background = R(nil, "x"), IconBorder = R(nil, "x") }
			or { Background = R(nil, "x"), PvPBackground = R(nil, "x"), RatedPvPBackground = R(nil, "x"), BGAtlas = R(nil, "x") }
		return B(nil, art), art
	end
	local lootPool, lootRaw = newPool(W)
	local coinPool, coinRaw = newPool(W)
	X.lootItems, X.coinItems = lootRaw.items, coinRaw.items
	X.lootSystem = set("LootAlertSystem", { alertFramePool = lootPool, ShowAlert = function() end })
	X.coinSystem = set("MoneyWonAlertSystem", { alertFramePool = coinPool, ShowAlert = function() end })
	X.toastFrame, X.toastArt = X.toast()
	lootRaw.items[1] = X.toastFrame

	-- Breath timers: the game draws a picture in the fill each time one starts. A countdown timer is made when the first one starts.
	local function mirror()
		local status, raw, fill = bar(nil, "ui-castingbar-filling-standard")
		local art = { StatusBar = status, Border = R(nil, "ui-castingbar-frame"), TextBorder = R(nil, "ui-castingbar-textbox") }
		local frame, frameRaw = B(nil, art)
		local back = R(nil, "ui-castingbar-background")
		frameRaw.regions[1] = back
		frameRaw.Setup = function(_, atlas) raw.SetStatusBarTexture(nil, atlas) end
		return { frame = frame, fill = fill, art = art, back = back, bar = status }
	end
	X.m1, X.m2 = mirror(), mirror()
	set("MirrorTimerContainer", B(nil, { mirrorTimers = { X.m1.frame, X.m2.frame } }))
	local countBar, _, countFill = bar(BAR_FILE, nil, nil, "TimerTrackerTimer1StatusBar", { 1, 0, 0, 1 })
	X.count = { bar = countBar, fill = countFill, border = set("TimerTrackerTimer1StatusBarBorder", R(nil, "x-countborder")) }
	local countList = { B(nil, { bar = countBar }) }
	X.counter = set("TimerTracker", B(nil, { timerList = countList }))
	set("TimerTracker_StartTimerOfType", function()
		local late, _, lateFill = bar(BAR_FILE, nil, nil, "TimerTrackerTimer2StatusBar", { 1, 0, 0, 1 })
		X.late = { bar = late, fill = lateFill, border = set("TimerTrackerTimer2StatusBarBorder", R(nil, "x-lateborder")) }
		countList[#countList + 1] = B(nil, { bar = late })
	end)

	-- The queue panel, a damage meter with one window, and a zone bar widget next to a widget with two bars.
	X.queueNine = parts(NINE)
	X.queue = set("QueueStatusFrame", B(nil, { NineSlice = B(nil, X.queueNine) }, { forbidden = more.forbidden, protected = more.protected }))
	X.header = R(nil, "ui-damagemeters-header-bar")
	X.window1 = set("DamageMeterSessionWindow1", B(nil, { Header = X.header }))
	X.meter = set("DamageMeter", B(nil, { SetupSessionWindow = function() end }))
	function X.widget()
		local art = parts({ "BorderLeft", "BorderRight", "BorderCenter", "BGLeft", "BGRight", "BGCenter", "Spark" })
		local status = bar(nil, "widgetstatusbar-fill-white", art)
		return B(nil, { Bar = status }), art, status
	end
	X.zone, X.zoneArt, X.zoneBar = X.widget()
	X.double = B(nil, { LeftBar = B(nil, parts({ "BorderLeft" })), RightBar = B(nil, parts({ "BorderLeft" })) })
	X.fillUp = B(nil, { Bar = B(nil, parts({ "Fill" })) })
	set("UIWidgetTopCenterContainerFrame", B(nil, { widgetFrames = { X.zone, X.double, X.fillUp } }))
	X.widgetMixin = set("UIWidgetTemplateStatusBarMixin", { Setup = function() end })

	W.group = "static"
	W.seal()
	return X
end
local function login(more)
	local X = world(more)
	X.W.login()
	X.W.flush()
	return X
end
local function alphas(list)
	local out = {}
	for _, region in ipairs(list) do
		out[#out + 1] = g(region.alpha)
	end
	return table.concat(out, ",")
end
local function pick(art, keys)
	local list = {}
	for _, key in ipairs(keys) do
		list[#list + 1] = art[key]
	end
	return list
end
local function edgeIs(W, target, c)
	local o = W.look(target)
	return o ~= nil and near(o.r, c[1], 1e-6) and near(o.g, c[2], 1e-6) and near(o.b, c[3], 1e-6)
end
local function solid(fill, r, g, b)
	return fill.color ~= nil and fill.atlas == nil and fill.file == nil and near(fill.color[1], r, 1e-3) and near(fill.color[2], g, 1e-3) and near(fill.color[3], b, 1e-3)
end
local function allSwitches(W, value)
	for _, key in ipairs(ALL) do
		W.change("hud." .. key, value)
	end
end
local CAST, CRAFT = { 0xe6 / 255, 0xb3 / 255, 0x33 / 255 }, { 0x4d / 255, 0x99 / 255, 0xe6 / 255 }

local X = login()
local W = X.W

