	X.first.fill.file == STRIPES and X.first.raw.tint[2] == 0.42 and X.m2.fill.file == STRIPES and near(W.rawOf[X.m2.bar].tint[1], CAST[1], 1e-3))
W.change("general.barTexture", "Flat")
W.change("hud.lootRolls", false)
check("loot rolls off: the roll has its frame, ring and timer fill back and no border; the other parts are as they were",
	X.rollBorder.alpha == 1 and X.ring.alpha == 1 and X.rollFill.file == ROLL_FILE and X.rollFill.color == nil and W.state(X.roll) == "hb" and W.state(X.roll.IconFrame) == "hb"
		and W.state(X.item) == "SB" and card.border.alpha == 0)
W.blizzard(function() W.env.GroupLootFrame_SetupItemDisplay(X.roll) end)
check("loot rolls off: the game's next roll is not styled", X.rollBorder.alpha == 1 and W.state(X.roll) == "hb")
