W.change("hud.mirror", true)

-- Everything off and on again: the same frames, nothing made twice, no new hook.
local hooks, madeFrames, madeTextures = W.hooks, #W.addonFrames, #W.addonTextures
allSwitches(W, false)
check("all off: the frames and fills the game gave later are back as they were, and the cards' icons are whole",
	late.border.alpha == 1 and W.state(late.frame) == "hb" and near(late.art.icon.texCoord[2], 1) and line2.fill.file == BAR_FILE and alphas(pick(bonus.art, { "BarFrame", "IconBG" })) == "1,1"
		and toastArt.Background.alpha == 1 and coinArt.IconBorder.alpha == 1 and X.late.border.alpha == 1 and header2.alpha == 1 and zoneArt.BorderLeft.alpha == 1
		and X.mod.Background.shown and X.mod.Shine.shown and X.trackerBack.alpha == 1 and X.itemPushed.alpha == 1 and X.queueNine.Center.alpha == 1)
