	W.state(late.frame) == "Sb" and W.state(bonus.bar) == "SB" and solid(line2.fill, 1, 1, 1) and X.mod.Background.shown == false and W.hooks == hooks and #W.addonFrames == madeFrames
		and #W.addonTextures == madeTextures, W.hooks .. " " .. hooks .. " " .. #W.addonFrames .. " " .. madeFrames)
check("status: the frames styled are counted once each", has(W.status(), "Minimap and buffs: on, 25 styled"), W.line("Minimap and buffs"))
clean(W, "tracker, loot, alerts, timers and the rest")

-- The game's art exactly, when everything is off in a fresh world and when it is off at login.
do
	local D = login()
	D.W.change("hud.enabled", false)
	check("page off: Blizzard's art is exactly as it was drawn", #D.W.diff("other") == 0 and D.W.state(D.tracker.Header) == "hb", table.concat(D.W.diff("other"), "; "):sub(1, 300))
	local N = newWorld({ hud = true })
	N.login()
	N.flush()
	check("a client without these frames: the status line alone, and nothing printed", N.line("Minimap and buffs") == "Minimap and buffs: on, 0 styled" and #N.out == 0
		and #N.violations == 0 and #N.errors == 0)
	local saved = { options = {} }
	for _, key in ipairs(ALL) do
		saved.options["hud." .. key] = false
	end
	local O = login({ saved = saved })
	check("off at login: nothing is made and nothing is touched, and the other frames of the client are the same as without these frames",
		#O.W.addonFrames == #N.addonFrames and #O.W.addonTextures == #N.addonTextures and #O.W.diff("other") == 0 and #O.W.violations == 0,
		#O.W.addonFrames .. " " .. #N.addonFrames .. " " .. #O.W.addonTextures .. " " .. #N.addonTextures)
