-- Frames the addon may not touch, values the client withholds, a part that keeps failing, and combat.
do
	local F = login({ forbidden = true, secret = true })
	check("forbidden and withheld: a forbidden panel is not read, a withheld table of bars is skipped, and the rest is styled",
		#F.W.violations == 0 and #F.W.errors == 0 and F.W.look(F.queue) == nil and F.queueNine.TopEdge.alpha == 1 and F.W.state(F.first.bar) == "." and F.W.state(F.timer.bar) == "SB"
			and F.W.state(F.tracker.Header) == "SB" and not has(F.W.status(), "stopped"), table.concat(F.W.violations, "|"))
	local P = login()
	local good = P.trackerBar
	P.trackerBar = function(bonus)
		local entry = good(bonus)
		P.W.rawOf[entry.holder].fault.createTexture = true
		return entry
	end
	P.W.blizzard(function()
		P.quest:GetProgressBar("a")
		P.quest:GetProgressBar("b")
		P.quest:GetProgressBar("c")
