	SB.click(W, "ContainerFrame2")
	SB.click(W, "ContainerFrame3")
	check("sortbags: three buttons whose click raises stop the part, hide every button and say so once", has(W.status(), "Windows: clean up bags stopped. boom") and SB.shown(W) == 0
		and table.concat(W.out, "|") == "Flat UI: clean up bags stopped in Windows. /flatui status shows why.", W.status())
	check("sortbags: and the rest of the Windows page goes on", not has(W.status(), "Windows: stopped") and W.ns.IsStopped("windows") == false)
end

-- 5. The command.
do
