	check("sortbags: not case sensitive either", SB.asked(W) == "SortBank 0")
	W.rawOf[W.bankPanel].bankType = 2
	W.slash("sort bank")
	check("sortbags: the account tab too", SB.asked(W) == "SortBank 2")
	said = W.slash("sort banks")
	check("sortbags: any other word prints the two help lines", SB.asked(W) == "" and said == SB.help, said)
	said = W.slash("sort   ")
	check("sortbags: spaces after it are nothing", SB.asked(W) == "SortBags" and said == "")
	W.combat = true
	said = W.slash("sort")
	check("sortbags: in combat the command sorts as it does out of combat", SB.asked(W) == "SortBags" and said == "", said)
	said = W.slash("sort bank")
	check("sortbags: and so does the bank command", SB.asked(W) == "SortBank 2" and said == "", said)
	W.combat = false
	W.held = "item"
	said = W.slash("sort")
	check("sortbags: with an item on the cursor the command says so in one line", SB.asked(W) == "" and said == SB.cursor, said)
	W.held = nil
	W.rawOf[W.env.BankFrame].shown = false
	W.ns.Set("windows.enabled", false)
	W.flush()
	said = W.slash("sort")
	check("sortbags: the command works with the Windows page off", SB.asked(W) == "SortBags" and said == "", said)
	check("sortbags: the help of the general command lists both lines, after the line for windows", has(W.slash("what"), "/flatui windows - each window and whether it is styled\n" .. SB.help .. "\n/flatui art"))
	check("sortbags: the command raises nothing", allClean(W), problems(W))
	local Y = SB.world(nil, function(X) X.env.BankFrame = nil end)
	check("sortbags: with no bank window the command says it is not open", Y.slash("sort bank") == SB.closed and SB.asked(Y) == "")
end

-- 6. The place of the button.
do
	local W = SB.world({ saved = { options = { ["windows.sortButton"] = "slots" } } })
	check("sortbags: Under the slots hangs a bag button just under its window, in the middle, and lies in the strip under the bank's slots", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots), SB.lines(W))
	W.rawOf[W.env.ContainerFrame2].shown = true
	local l, b = W.rectOf(SB.buttons(W, "ContainerFrame2")[1])
	check("sortbags: on a bag with nothing under it that is 2 units under the window and 8 left of the middle of its bottom edge", near(l, 1762) and near(b, 82), g(l) .. "," .. g(b))
	local button = SB.buttons(W, "ContainerFrame2")[1]
	W.rawOf[button].scripts.OnEnter(button)
	check("sortbags: the tooltip of a bag opens below the button", W.tip.anchor == "ANCHOR_BOTTOM")
	local bank = SB.buttons(W, "BankFrame")[1]
	W.rawOf[bank].scripts.OnEnter(bank)
	check("sortbags: the tooltip of the bank opens above it", W.tip.anchor == "ANCHOR_TOP")
	local before = SB.made(W)
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: the choice moves the buttons that are there, and makes none", SB.lines(W) == SB.rows(SB.title, SB.title) and SB.made(W) == before and SB.buttons(W, "ContainerFrame2")[1] == button, SB.lines(W))
	W.rawOf[button].scripts.OnEnter(button)
	check("sortbags: and the tooltip follows", W.tip.anchor == "ANCHOR_TOP")
	W.ns.Set("windows.sortButton", "slots")
	check("sortbags: and back", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots) and SB.made(W) == before)
	W.ns.Set("windows.sortButton", "none")
	check("sortbags: None hides them all and makes none", SB.lines(W) == SB.rows("TOP/0,-2/hidden", "BOTTOMLEFT/10,6/hidden") and SB.made(W) == before, SB.lines(W))
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: the choice after it shows the same buttons again", SB.lines(W) == SB.rows(SB.title, SB.title) and SB.made(W) == before and SB.buttons(W, "ContainerFrame2")[1] == button)
	local bars, hover = 0, wtints(W, button, "OVERLAY")
	for index = 2, 4 do
		bars = bars + (hover[index].shown and 1 or 0)
	end
	check("sortbags: and with the box, its edges and its three bars shown, and the patch under the cursor not", W.state(button) == "SB" and bars == 3 and not hover[1].shown)
	check("sortbags: the edges lie one level above the button, over the title bar of the movers", W.rawOf[W.holderOn(button)].level == W.rawOf[button].level + 1)
	W.ns.Set("windows.opacity", 70)
	check("sortbags: a button that has not moved is not anchored again", W.rawOf[button].calls.ClearAllPoints == 4, tostring(W.rawOf[button].calls.ClearAllPoints))
	check("sortbags: none of it raised or wrote on a Blizzard frame", allClean(W) and #W.out == 0, problems(W))
	local N = SB.world({ saved = { options = { ["windows.sortButton"] = "none" } } })
	check("sortbags: with None from the start no button is made at all", SB.made(N) == 0 and allClean(N))
	N.ns.Set("windows.sortButton", "title")
	check("sortbags: and the choice after it makes them", SB.lines(N) == SB.rows(SB.title, SB.title) and SB.made(N) == 9)
	local X = SB.world({ saved = { options = { ["windows.sortButton"] = "nonsense" } } })
	check("sortbags: a saved choice that is not one of the three is the default", X.ns.Get("windows.sortButton") == "title" and SB.lines(X) == SB.rows(SB.title, SB.title))
end

-- 6b. Under the slots, a bag with another bag under it has no button: the game stacks the bags 8 units apart, each on the top right corner
-- of the one under it (ContainerFrame.lua:1402), and a button hanging under a bag would lie over the title bar of the bag below. A button
-- that goes is hidden where it was, so the reading of a hidden one is its place when it went.
do
	local S, H, A = SB.slots, "TOP/0,-2/hidden", SB.away
	local function expect(combined, one, two, three, four)
		return table.concat({ combined, one, two, three, four, S, S, S }, "|") .. "|" .. SB.bankSlots
	end
	local W = SB.world({ saved = { options = { ["windows.sortButton"] = "slots" } } })
	local env = W.env
	local hooks = W.hooks
	-- The game's layout of three bags: the second on the screen, the third on its top right corner and the fourth on that of the third.
	local function stack()
		W.gamePlaces("ContainerFrame2", "BOTTOMRIGHT", 0, 100)
		W.gamePlaces("ContainerFrame3", "BOTTOMRIGHT", 0, 8, env.ContainerFrame2, "TOPRIGHT")
		W.gamePlaces("ContainerFrame4", "BOTTOMRIGHT", 0, 8, env.ContainerFrame3, "TOPRIGHT")
		env.UpdateContainerFrameAnchors()
	end
	-- Two changes of a setting that the buttons do not depend on make the Windows page lay them out again, as the layout of the game does.
	local function again()
		W.ns.Set("windows.sortBank", false)
		W.ns.Set("windows.sortBank", true)
	end
	-- The buttons that are shown and lie over a bag window.
	local function touching()
		local found = {}
		for _, name in ipairs(SB.bags) do
			for _, button in ipairs(SB.buttons(W, name)) do
				if W.rawOf[button].shown then
					local bl, bb, bw, bh = W.rectOf(button)
					for _, other in ipairs({ "ContainerFrame2", "ContainerFrame3", "ContainerFrame4" }) do
						local l, b, w, h = W.rectOf(env[other])
						if bl < l + w and bl + bw > l and bb < b + h and bb + bh > b then
							found[#found + 1] = name .. " over " .. other
						end
					end
				end
			end
		end
		return table.concat(found, ",")
	end
	check("sortbags: bags that are not stacked have a button each under the slots", SB.lines(W) == SB.rows(S, SB.bankSlots), SB.lines(W))
	stack()
	check("sortbags: the buttons follow the layout of the game on the next frame, not in the call", SB.lines(W) == SB.rows(S, SB.bankSlots), SB.lines(W))
	W.flush()
	check("sortbags: a bag with a bag under it loses its button, the lowest of the stack and the others keep theirs", SB.lines(W) == expect(S, S, S, H, H), SB.lines(W))
	check("sortbags: and no button lies over a bag window", touching() == "", touching())
	check("sortbags: nothing was made again for it", SB.made(W) == 9 and allClean(W), problems(W))
	W.gamePlaces("ContainerFrame3", "BOTTOMRIGHT", 0, 100)
	env.UpdateContainerFrameAnchors()
	W.flush()
	check("sortbags: the bag that was lowest closes and the next one is the lowest, with its button back", SB.lines(W) == expect(S, S, S, S, H), SB.lines(W))
	W.gamePlaces("ContainerFrame4", "BOTTOMRIGHT", -11, 0, env.ContainerFrame3, "BOTTOMLEFT")
	env.UpdateContainerFrameAnchors()
	W.flush()
	check("sortbags: a bag that starts a new column has its button", SB.lines(W) == expect(S, S, S, S, S), SB.lines(W))
	W.gamePlaces("ContainerFrame4", "BOTTOMRIGHT", 0, 8, env.BankFrame, "TOPRIGHT")
	env.UpdateContainerFrameAnchors()
	W.flush()
	check("sortbags: a bag on the top right corner of a window that is not a bag has its button", SB.lines(W) == expect(S, S, S, S, S), SB.lines(W))
	stack()
	W.flush()
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: in the title bar a stack has a button on every bag", SB.lines(W) == SB.rows(SB.title, SB.title), SB.lines(W))
	W.ns.Set("windows.sortButton", "slots")
	check("sortbags: and under the slots again the stacked bags have none", SB.lines(W) == expect(S, S, S, A, A), SB.lines(W))
	for _, fault in ipairs({ "error", "secret", "secretRelative" }) do
		W.rawOf[env.ContainerFrame2].fault.point = fault
		again()
		W.rawOf[env.ContainerFrame2].fault.point = nil
		check("sortbags: a bag that cannot say where it lies counts as stacked when its answer is " .. fault, SB.lines(W) == expect(S, S, H, A, A), SB.lines(W))
		again()
	end
	-- A bag whose anchor point on the other window is withheld.
	local get = W.rawOf[env.ContainerFrame2].GetPoint
	W.rawOf[env.ContainerFrame2].GetPoint = function() return "BOTTOMRIGHT", env.UIParent, SECRET, 0, 0 end
	again()
	W.rawOf[env.ContainerFrame2].GetPoint = get
	check("sortbags: a bag whose anchor point is withheld counts as stacked", SB.lines(W) == expect(S, S, H, A, A), SB.lines(W))
	again()
	check("sortbags: and has its button back when it can again", SB.lines(W) == expect(S, S, S, A, A), SB.lines(W))
	W.rawOf[env.ContainerFrame3].points = {}
	again()
	check("sortbags: a bag with no anchor is not stacked", SB.lines(W) == expect(S, S, S, S, A), SB.lines(W))
	W.gamePlaces("ContainerFrame3", "BOTTOMRIGHT", 0, 100)
	W.ns.Set("windows.sortButton", "none")
	env.UpdateContainerFrameAnchors()
	W.flush()
	check("sortbags: with None the layout of the game shows nothing", SB.shown(W) == 0, SB.lines(W))
	check("sortbags: none of it was said", #W.out == 0, table.concat(W.out, "|"))
	check("sortbags: the layout of the game is followed with the one hook made at login, however often the page is applied", W.hooks == hooks, tostring(W.hooks - hooks))

	-- In combat a button that has to go is hidden at once, and one that may come back waits for the end of combat.
	local C = SB.world({ saved = { options = { ["windows.sortButton"] = "slots" } } })
	C.combat = true
	C.gamePlaces("ContainerFrame3", "BOTTOMRIGHT", 0, 8, C.env.ContainerFrame2, "TOPRIGHT")
	C.gamePlaces("ContainerFrame4", "BOTTOMRIGHT", 0, 8, C.env.ContainerFrame3, "TOPRIGHT")
	C.env.UpdateContainerFrameAnchors()
	C.flush()
	check("sortbags: bags stacked in combat lose their buttons at once", SB.lines(C) == expect(S, S, S, H, H) and allClean(C), SB.lines(C) .. problems(C))
	C.gamePlaces("ContainerFrame3", "BOTTOMRIGHT", 0, 100)
	C.env.UpdateContainerFrameAnchors()
	C.flush()
	check("sortbags: and a bag that is the lowest again gets its button back only when combat ends", SB.lines(C) == expect(S, S, S, H, H), SB.lines(C))
	SB.over(C)
	check("sortbags: combat ends and it has", SB.lines(C) == expect(S, S, S, S, H) and allClean(C), SB.lines(C) .. problems(C))
end

-- 6c. Under the gamepad interface the game has no clean up button and its action lies in a menu (ContainerFrame.lua:735-742 and 1132-1136), and a
-- button here could not be clicked: none is made.
do
	local function pad(opts, answer)
		return SB.world(opts, function(X)
			X.gamepad = answer
			X.env.InputUtil = { IsGamepadUIEnabled = function() return X.gamepad end }
		end)
	end
	local W = pad(nil, true)
	check("sortbags: under the gamepad interface no button is made", SB.made(W) == 0 and allClean(W), problems(W))
	W.gamepad = false
	W.ns.Set("windows.sortButton", "slots")
	check("sortbags: the next pass after the interface changed makes them all", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots) and SB.made(W) == 9, SB.lines(W))
	W.gamepad = true
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: and the gamepad interface again hides every one of them", SB.shown(W) == 0 and SB.made(W) == 9 and allClean(W), SB.lines(W))
	local P = pad({ saved = { options = { ["windows.sortButton"] = "slots" } } }, true)
	check("sortbags: under the slots none is made either", SB.made(P) == 0)
	P.gamepad = false
	P.env.UpdateContainerFrameAnchors()
	P.flush()
	check("sortbags: and a bag that opens after the interface changed gets them", SB.lines(P) == SB.rows(SB.slots, SB.bankSlots) and SB.made(P) == 9, SB.lines(P))
	P.gamepad = true
	P.env.UpdateContainerFrameAnchors()
	P.flush()
	check("sortbags: and loses them when it changes back", SB.shown(P) == 0 and allClean(P), SB.lines(P))
	for _, fault in ipairs({ "error", "secret", "text" }) do
		local X = SB.world(nil, function(Y)
			Y.secretType = "boolean"
			Y.env.InputUtil = { IsGamepadUIEnabled = function()
				if fault == "error" then
					error("boom", 0)
				elseif fault == "secret" then
					return SECRET
				end
				return "yes"
			end }
		end)
		check("sortbags: an answer about the interface that is " .. fault .. " is no gamepad interface", SB.made(X) == 9 and SB.shown(X) == 9 and allClean(X), problems(X))
	end
	local X = SB.world(nil, function(Y) Y.env.InputUtil = SECRET end)
	check("sortbags: a table of the game's that is withheld is not read", SB.made(X) == 9 and allClean(X), problems(X))
	X = SB.world(nil, function(Y) Y.env.InputUtil = {} end)
	check("sortbags: and a client without the call has no gamepad interface", SB.made(X) == 9 and allClean(X), problems(X))
end

-- 6d. The interface style changes while the game runs (INPUT_DEVICE_INTERFACE_TRANSITION, InputDocumentation.lua:319-331): the buttons go
-- or come back at once, with no other event.
do
	local function pad(opts, answer)
		return SB.world(opts, function(X)
			X.gamepad = answer
			X.env.InputUtil = { IsGamepadUIEnabled = function() return X.gamepad end }
		end)
	end
	local W = pad(nil, false)
	check("sortbags: the buttons are shown under the mouse interface", SB.shown(W) == 9 and SB.made(W) == 9, SB.lines(W))
	W.gamepad = true
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 2, 0)
	check("sortbags: a change to the gamepad interface hides every button at once, in the title bar", SB.shown(W) == 0 and allClean(W), SB.lines(W))
	W.gamepad = false
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 0, 2)
	check("sortbags: and a change back shows them where the settings put them", SB.lines(W) == SB.rows(SB.title, SB.title) and SB.shown(W) == 9 and allClean(W), SB.lines(W))
	W.ns.Set("windows.sortButton", "slots")
	W.gamepad = true
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 2, 0)
	check("sortbags: under the slots a change to the gamepad interface hides them as well", SB.shown(W) == 0 and allClean(W), SB.lines(W))
	W.gamepad = false
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 0, 2)
	check("sortbags: and a change back puts them under the slots", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots) and SB.shown(W) == 9 and allClean(W), SB.lines(W))
	W.gamepad = true
	W.combat = true
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 2, 0)
	check("sortbags: in combat the button that has to go is hidden at once", SB.shown(W) == 0 and allClean(W), SB.lines(W))
	W.gamepad = false
	W.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 0, 2)
	check("sortbags: and what comes back waits for the end of combat", SB.shown(W) == 0 and allClean(W), SB.lines(W))
	SB.over(W)
	check("sortbags: the end of combat shows them", SB.shown(W) == 9 and allClean(W), SB.lines(W))
	local X = pad({ unknownEvents = { INPUT_DEVICE_INTERFACE_TRANSITION = true } }, false)
	check("sortbags: a client that has no such event still has its buttons and no part stopped", SB.shown(X) == 9 and not has(X.status(), "clean up bags stopped") and allClean(X), SB.lines(X))
	local N = pad({ saved = { options = { ["windows.sortButton"] = "none" } } }, false)
	N.gamepad = true
	N.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 2, 0)
	N.gamepad = false
	N.fire("INPUT_DEVICE_INTERFACE_TRANSITION", 0, 2)
	check("sortbags: with None chosen the event makes no button", SB.made(N) == 0 and allClean(N), problems(N))
end

-- 7. The bank.
do
	local W = SB.world({ saved = { options = { ["windows.sortBank"] = false } } })
	check("sortbags: with Also on the bank off the bags have a button and the bank has none", SB.lines(W) == SB.rows(SB.title, "none") and SB.made(W) == 8, SB.lines(W))
	W.ns.Set("windows.sortBank", true)
	check("sortbags: and the bank has one when it goes on", SB.lines(W) == SB.rows(SB.title, SB.title) and SB.made(W) == 9)
	W.ns.Set("windows.sortBank", false)
	check("sortbags: and it is hidden when the setting goes off, while the bags keep theirs", SB.lines(W) == SB.rows(SB.title, SB.away) and SB.made(W) == 9)
	W.ns.Set("windows.sortButton", "slots")
	check("sortbags: Under the slots with the bank off leaves the bank hidden", SB.lines(W) == SB.rows(SB.slots, SB.away))
	W.openPanel()
	local on = W.enabled("windows.sortBank")
	W.change("windows.sortButton", "None")
	local off = W.enabled("windows.sortBank")
	W.change("windows.sortButton", "Under the slots")
	check("sortbags: Also on the bank is usable with a button, and not with None", on and not off and W.enabled("windows.sortBank"))
	local labels, from = W.menu("windows.sortButton"), W.menu("windows.sortFrom")
	check("sortbags: the page offers the choices with their words, at the defaults of the pick", table.concat(labels, ",") == "In the title bar,Under the slots,None" and table.concat(from, ",") == "As the game sorts,From the other end"
		and W.read("windows.sortFrom") == "As the game sorts" and W.read("windows.sortBank") == false)
	local rows = {}
	for _, page in ipairs(W.ns.PAGES) do
		for _, item in ipairs((page.key == "windows" or page.owner == "windows") and page or {}) do
			if item.key == "sortButton" or item.key == "sortBank" or item.key == "sortFrom" then
				local choices = {}
				for _, choice in ipairs(item.choices or {}) do
					choices[#choices + 1] = choice[1] .. "=" .. choice[2]
				end
				rows[#rows + 1] = table.concat({ item.key, item.kind, tostring(item.default), item.label, tostring(item.tip), tostring(item.needs), table.concat(item.needsIn or {}, "+"),
					table.concat(choices, "+") }, "|")
			end
		end
	end
	check("sortbags: the three settings have their kind, default, label, tip, what each needs and the words of each choice", table.concat(rows, "\n") ==
		"sortButton|choice|title|Clean up bags button|" .. SB.stack .. "|nil||title=In the title bar+slots=Under the slots+none=None\n"
		.. "sortBank|bool|true|Also on the bank|nil|sortButton|title+slots|\n"
		.. "sortFrom|choice|game|Items gather|Also applies to the game's own clean up.|nil||game=As the game sorts+other=From the other end", table.concat(rows, " / "))
	check("sortbags: none of it raised", allClean(W) and #W.out == 0, problems(W))
end

-- 8. Items gather.
do
	local W = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } })
	local db = W.env.FlatUICharDB
	check("sortbags: From the other end writes the opposite of the game's value, once, and remembers the game's", W.sort.rtl == true and table.concat(W.sort.calls, ",") == "Set true"
		and db.sortDirection and db.sortDirection.game == false and db.sortDirection.wrote == true, table.concat(W.sort.calls, ","))
	W.sort.calls = {}
	SB.click(W, "ContainerFrame1")
	check("sortbags: a click then sorts, and writes nothing, since the value is in place", SB.asked(W) == "SortBags" and W.sort.rtl == true)
	W.ns.Set("windows.sortFrom", "game")
	check("sortbags: As the game sorts puts the game's value back and forgets it", W.sort.rtl == false and table.concat(W.sort.calls, ",") == "Set false" and db.sortDirection == nil, table.concat(W.sort.calls, ","))
	W.sort.calls = {}
	W.ns.Set("windows.sortButton", "slots")
	W.ns.Set("windows.sortBank", false)
	SB.click(W, "ContainerFrame1")
	check("sortbags: at As the game sorts the game's value is never written, by a setting or a click", SB.asked(W) == "SortBags" and W.sort.rtl == false)
	W.ns.Set("windows.sortFrom", "other")
	W.ns.Set("windows.enabled", false)
	check("sortbags: the page going off puts the value back", W.sort.rtl == false and db.sortDirection == nil and SB.made(W) == 9)
	W.ns.Set("windows.enabled", true)
	check("sortbags: and on writes it again", W.sort.rtl == true and db.sortDirection.game == false and db.sortDirection.wrote == true)
	W.sort.calls = {}
	W.fire("PLAYER_LOGOUT")
	check("sortbags: at logout the value goes back, and the record stays for the next login", W.sort.rtl == false and table.concat(W.sort.calls, ",") == "Set false" and db.sortDirection.game == false and db.sortDirection.wrote == true,
		table.concat(W.sort.calls, ","))
	W.sort.calls = {}
	W.fire("PLAYER_LOGOUT")
	check("sortbags: a second logout writes nothing", #W.sort.calls == 0)
	check("sortbags: none of it raised", allClean(W) and #W.out == 0, problems(W))

	local T = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X) X.sort.rtl = true end)
	check("sortbags: when the game's value is true the opposite is false", T.sort.rtl == false and T.env.FlatUICharDB.sortDirection.game == true and T.env.FlatUICharDB.sortDirection.wrote == false)
	T.ns.Set("windows.sortFrom", "game")
	check("sortbags: and true is put back", T.sort.rtl == true and T.env.FlatUICharDB.sortDirection == nil)

	local N = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = { game = false, wrote = true } } })
	check("sortbags: the next login finds the game at the player's value and writes the opposite again", N.sort.rtl == true and N.env.FlatUICharDB.sortDirection.game == false and N.env.FlatUICharDB.sortDirection.wrote == true)
	local C = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = { game = false, wrote = true } } }, function(X) X.sort.rtl = true end)
	check("sortbags: a value left in place with its record is kept, and the player's value stays remembered", C.sort.rtl == true and #C.sort.calls == 0 and C.env.FlatUICharDB.sortDirection.game == false)
	local H = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } })
	H.sort.rtl = false
	H.sort.calls = {}
	SB.click(H, "ContainerFrame1")
	check("sortbags: a value the player set since is taken for the game's own and the opposite is written before the sort", H.sort.rtl == true and SB.asked(H) == "Set true,SortBags")
	H.ns.Set("windows.sortFrom", "game")
	check("sortbags: and the game's value is put back after it", H.sort.rtl == false and H.env.FlatUICharDB.sortDirection == nil)
	local O = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = false, wrote = true } } }, function(X) X.sort.rtl = true end)
	check("sortbags: with the page off at login the value left in place is put back and the record goes", O.sort.rtl == false and O.env.FlatUICharDB.sortDirection == nil and SB.made(O) == 0)
	local P = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = false, wrote = true } } })
	check("sortbags: a value that is not the one written is left alone and the record goes", P.sort.rtl == false and #P.sort.calls == 0 and P.env.FlatUICharDB.sortDirection == nil)
	local Q = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = true, wrote = false } } }, function(X) X.sort.rtl = false end)
	check("sortbags: the value is put back whichever way it was written", Q.sort.rtl == true and Q.env.FlatUICharDB.sortDirection == nil)
	local R = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = "junk" } })
	check("sortbags: a record that is text is dropped and the choice works", R.sort.rtl == true and R.env.FlatUICharDB.sortDirection.game == false)
	local R1 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = 5 } })
	check("sortbags: and so is a record that is a number", R1.sort.rtl == true and R1.env.FlatUICharDB.sortDirection.game == false and allClean(R1) and not has(R1.status(), "stopped"), R1.status())
	local R2 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = { game = "no", wrote = true } } })
	check("sortbags: a record whose value is not true or false is dropped", R2.sort.rtl == true and R2.env.FlatUICharDB.sortDirection.game == false)
	local R4 = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = "no", wrote = true } } }, function(X) X.sort.rtl = true end)
	check("sortbags: a record whose value is not true or false puts nothing back at login and is dropped", R4.sort.rtl == true and #R4.sort.calls == 0 and R4.env.FlatUICharDB.sortDirection == nil and allClean(R4), problems(R4))
	local R3 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } }, char = { sortDirection = { game = false, wrote = 3 } } })
	check("sortbags: and so is one whose written value is not", R3.sort.rtl == true and R3.env.FlatUICharDB.sortDirection.wrote == true)
	local F = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X) X.sort.refuse = true end)
	check("sortbags: a write the game does not take is not recorded as written", F.sort.rtl == false and F.env.FlatUICharDB.sortDirection.wrote == nil and allClean(F), problems(F))
	F.sort.refuse = false
	F.sort.calls = {}
	SB.click(F, "ContainerFrame1")
	check("sortbags: and is made again before the next sort", F.sort.rtl == true and F.env.FlatUICharDB.sortDirection.wrote == true and SB.asked(F) == "Set true,SortBags")
	for _, fault in ipairs({ "secret", "error", "number" }) do
		local V = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X)
			X.sort.fault = fault
			-- A withheld boolean says it is a boolean, as it does in the client.
			X.secretType = "boolean"
		end)
		V.sort.calls = {}
		SB.click(V, "ContainerFrame1")
		check("sortbags: a direction that is " .. fault .. " is never written, the sort still goes and nothing raises", SB.asked(V) == "SortBags" and V.env.FlatUICharDB.sortDirection == nil
			and allClean(V) and not has(V.status(), SB.note), problems(V))
	end
	local M = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X)
		X.env.C_Container.GetSortBagsRightToLeft, X.env.C_Container.SetSortBagsRightToLeft = nil, nil
	end)
	SB.click(M, "ContainerFrame1")
	check("sortbags: a client with no sort direction says so on the status page, sorts, and raises nothing", has(M.status(), SB.note) and SB.asked(M) == "SortBags" and allClean(M) and M.env.FlatUICharDB.sortDirection == nil, M.status())
	M.ns.Set("windows.sortFrom", "game")
	check("sortbags: and the line goes when the choice does", not has(M.status(), SB.note))
	local S = SB.world({}, function(X)
		X.env.C_Container.GetSortBagsRightToLeft, X.env.C_Container.SetSortBagsRightToLeft = nil, nil
	end)
	check("sortbags: at As the game sorts there is no line about the direction", not has(S.status(), SB.note))
	local B = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X) X.env.C_Container.SetSortBagsRightToLeft = nil end)
	check("sortbags: a client that can read the direction and not write it says so too", has(B.status(), SB.note) and allClean(B), B.status())
	local L0 = SB.world()
	L0.fire("PLAYER_LOGOUT")
	check("sortbags: a logout with no record writes nothing and raises nothing", #L0.sort.calls == 0 and allClean(L0) and not has(L0.status(), "stopped"), L0.status())
	local Pf = SB.world()
	Pf.ns.NewProfile("Two")
	Pf.ns.Set("windows.sortFrom", "other")
	local onTwo = Pf.sort.rtl
	Pf.ns.UseProfile("Default")
	check("sortbags: a profile with From the other end writes the direction, and another profile puts it back", onTwo == true and Pf.sort.rtl == false and Pf.env.FlatUICharDB.sortDirection == nil)
	Pf.ns.UseProfile("Two")
	check("sortbags: and the profile again writes it", Pf.sort.rtl == true and Pf.env.FlatUICharDB.sortDirection.game == false)
	local Z = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = false, wrote = false } } })
	check("sortbags: a record whose written value is the player's own is dropped and nothing is written", #Z.sort.calls == 0 and Z.env.FlatUICharDB.sortDirection == nil)
	local Z2 = SB.world()
	Z2.env.FlatUICharDB.sortDirection = { game = false, wrote = false }
	Z2.fire("PLAYER_LOGOUT")
	check("sortbags: and at logout too", #Z2.sort.calls == 0)
	local Z3 = SB.world()
	Z3.env.FlatUICharDB.sortDirection = { game = false }
	Z3.sort.fault = "error"
	Z3.fire("PLAYER_LOGOUT")
	check("sortbags: a record with nothing written is left alone at logout, whatever the game says", #Z3.sort.calls == 0)
	-- Two characters of one account. The source does not say whether the game keeps the direction for the character or for the account, so
	-- each character has a record of its own and neither loses its own value.
	local A1 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } })
	A1.fire("PLAYER_LOGOUT")
	check("sortbags: the first character has its own value back at logout and keeps its record", A1.sort.rtl == false and A1.env.FlatUICharDB.sortDirection.game == false and A1.env.FlatUIDB.sortDirection == nil)
	local A2 = SB.world({ saved = A1.env.FlatUIDB }, function(X) X.sort.rtl = true end)
	check("sortbags: a second character on the same account whose own value is the other one writes the opposite of its own value and remembers it",
		A2.sort.rtl == false and A2.env.FlatUICharDB.sortDirection.game == true and A2.env.FlatUICharDB.sortDirection.wrote == false and A1.env.FlatUICharDB.sortDirection.game == false)
	A2.fire("PLAYER_LOGOUT")
	check("sortbags: and has its own value back at its logout", A2.sort.rtl == true and A2.env.FlatUICharDB.sortDirection.game == true)

	-- The reader missing while the writer is there.
	local M2 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X) X.env.C_Container.GetSortBagsRightToLeft = nil end)
	check("sortbags: a client that can write the direction and not read it says so too, and writes nothing", has(M2.status(), SB.note) and #M2.sort.calls == 0 and allClean(M2), M2.status())

	-- A write the game refused, and then the player sets the game's value by hand: that value is the player's own.
	local F2 = SB.world({ saved = { options = { ["windows.sortFrom"] = "other" } } }, function(X) X.sort.refuse = true end)
	F2.sort.refuse = false
	F2.sort.rtl = true
	F2.sort.calls = {}
	SB.click(F2, "ContainerFrame1")
	check("sortbags: a value set by the player after a refused write is taken for the player's own, and the opposite is written before the sort",
		SB.asked(F2) == "Set false,SortBags" and F2.sort.rtl == false and F2.env.FlatUICharDB.sortDirection.game == true and F2.env.FlatUICharDB.sortDirection.wrote == false)

	-- A record whose written value is the player's own, with the game holding the other value: nothing is put back.
	local Z4 = SB.world({ saved = { options = { ["windows.enabled"] = false } }, char = { sortDirection = { game = false, wrote = false } } }, function(X) X.sort.rtl = true end)
	check("sortbags: a value that is not the one written is left alone, whatever it is next to the player's own", #Z4.sort.calls == 0 and Z4.sort.rtl == true and Z4.env.FlatUICharDB.sortDirection == nil)
end

-- 9. Combat.
do
	local W = SB.world({ protect = true })
	W.combat = true
	W.ns.Set("windows.sortButton", "none")
	check("sortbags: a button is hidden at once in combat", SB.lines(W) == SB.rows(SB.away, SB.away) and allClean(W), SB.lines(W))
	W.ns.Set("windows.sortButton", "slots")
	check("sortbags: and shown again, moved and made only when combat ends", SB.lines(W) == SB.rows(SB.away, SB.away) and SB.made(W) == 9 and allClean(W), SB.lines(W))
	SB.over(W)
	check("sortbags: combat ends and the buttons are where the choice puts them", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots) and allClean(W), SB.lines(W))
	W.combat = true
	W.ns.Set("windows.sortButton", "title")
	W.ns.Set("windows.sortButton", "slots")
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: a choice made in combat moves nothing in combat", SB.lines(W) == SB.rows(SB.slots, SB.bankSlots), SB.lines(W))
	SB.over(W)
	check("sortbags: and the last choice is the one that is applied once combat ends", SB.lines(W) == SB.rows(SB.title, SB.title) and allClean(W), SB.lines(W))
	W.combat = true
	W.ns.Set("windows.enabled", false)
	check("sortbags: the Windows page going off hides the buttons in combat", SB.lines(W) == SB.rows(SB.away, SB.away), SB.lines(W))
	W.ns.Set("windows.enabled", true)
	check("sortbags: and on shows none in combat", SB.shown(W) == 0)
	SB.over(W)
	check("sortbags: they are shown after it", SB.lines(W) == SB.rows(SB.title, SB.title) and allClean(W), SB.lines(W))
	local N = SB.world({ protect = true, saved = { options = { ["windows.sortButton"] = "none" } } })
	N.combat = true
	N.ns.Set("windows.sortButton", "title")
	check("sortbags: nothing is made on a protected window in combat", SB.made(N) == 0 and allClean(N), problems(N))
	SB.over(N)
	check("sortbags: the buttons are made when combat ends, one for each window", SB.lines(N) == SB.rows(SB.title, SB.title) and SB.made(N) == 9 and allClean(N), problems(N))
	local L = SB.world({ protect = true, combat = true })
	check("sortbags: a login in combat makes no button", SB.made(L) == 0 and allClean(L), problems(L))
	SB.over(L)
	check("sortbags: they are made when combat ends", SB.lines(L) == SB.rows(SB.title, SB.title) and allClean(L), problems(L))
	local O = SB.world({ protect = true, saved = { options = { ["windows.sortFrom"] = "other" } } })
	O.sort.calls = {}
	O.combat = true
	O.ns.Set("windows.sortFrom", "game")
	check("sortbags: the sort direction waits for the end of combat too", O.sort.rtl == true and #O.sort.calls == 0)
	SB.over(O)
	check("sortbags: and is put back then", O.sort.rtl == false and O.env.FlatUICharDB.sortDirection == nil)
end

-- 7b. A type of bank that the game withholds is not read.
do
	local W = SB.world()
	W.secretType = "number"
	W.rawOf[W.bankPanel].bankType = SECRET
	SB.click(W, "BankFrame")
	check("sortbags: a type of bank that is withheld is no bank type: nothing is sorted and the line says to open the bank", SB.asked(W) == "" and SB.said(W) == SB.kind and allClean(W), problems(W))
end

-- 10. The page off, a part that fails, windows that are missing.
do
	local W = SB.world()
	local button = SB.buttons(W, "ContainerFrame1")[1]
	W.ns.Set("windows.enabled", false)
	check("sortbags: the Windows page off hides every button", SB.lines(W) == SB.rows(SB.away, SB.away), SB.lines(W))
	local drawn = wtints(W, button, "OVERLAY")
	check("sortbags: and what it drew: the box and its edges, the bars and the patch", W.state(button) == "hb" and not drawn[1].shown and not drawn[2].shown and not drawn[3].shown and not drawn[4].shown, W.state(button))
	W.ns.Set("windows.enabled", true)
	check("sortbags: and on shows the same ones, and makes none", SB.lines(W) == SB.rows(SB.title, SB.title) and SB.made(W) == 9 and SB.buttons(W, "ContainerFrame1")[1] == button)
	local made = #W.addonFrames
	W.ns.Set("windows.bags", false)
	W.ns.Set("windows.buttons", false)
	W.flush()
	check("sortbags: the button does not depend on the switches of the windows", SB.lines(W) == SB.rows(SB.title, SB.title) and #W.addonFrames == made)
	check("sortbags: none of it raised", allClean(W) and #W.out == 0, problems(W))

	local F = SB.world({ saved = { options = { ["windows.sortButton"] = "none" } } })
	local outline = F.ns.Outline
	F.ns.Outline = function() error("boom", 0) end
	F.out = {}
	F.ns.Set("windows.sortButton", "title")
	check("sortbags: three windows whose button cannot be built stop the part, with a line for status", has(F.status(), "Windows: clean up bags stopped. boom") and not has(F.status(), "Windows: stopped"), F.status())
	check("sortbags: the player is told once", table.concat(F.out, "|") == "Flat UI: clean up bags stopped in Windows. /flatui status shows why.", table.concat(F.out, "|"))
	check("sortbags: the three buttons that failed are hidden, and no other is tried", SB.made(F) == 3 and SB.shown(F) == 0 and F.ns.IsStopped("windows") == false, SB.lines(F))
	local hidden = true
	for _, name in ipairs({ "ContainerFrameCombinedBags", "ContainerFrame1", "ContainerFrame2" }) do
		local failed = SB.buttons(F, name)[1]
		hidden = hidden and failed ~= nil and F.rawOf[failed].shown == false
	end
	check("sortbags: each frame of a button that failed is hidden at once, with no pass after it", hidden)
	local G = SB.world({ saved = { options = { ["windows.sortButton"] = "none" } } })
	local real, tries = G.ns.Outline, 0
	G.ns.Outline = function(...)
		tries = tries + 1
		if tries == 1 then
			error("boom", 0)
		end
		return real(...)
	end
	G.ns.Set("windows.sortButton", "title")
	local lone = SB.buttons(G, "ContainerFrameCombinedBags")[1]
	check("sortbags: a button that failed once is hidden while the others are shown and the part goes on", lone ~= nil and G.rawOf[lone].shown == false and SB.shown(G) == 8 and not has(G.status(), "clean up bags stopped"), SB.lines(G))
	F.ns.Outline = outline
	F.ns.Set("windows.enabled", false)
	F.ns.Set("windows.enabled", true)
	check("sortbags: the page off and on starts the part again; a window that failed stays without", SB.made(F) == 9 and SB.shown(F) == 6 and not has(F.status(), "clean up bags stopped"), SB.lines(F))
	F.sort.calls = {}
	SB.click(F, "ContainerFrame3")
	check("sortbags: and the buttons made then sort", SB.asked(F) == "SortBags")
	local K = SB.world({ saved = { options = { ["windows.sortButton"] = "none" } } })
	K.ns.Outline = function() return nil end
	K.ns.Set("windows.sortButton", "title")
	check("sortbags: a button whose outline is not made counts as a failure", has(K.status(), "Windows: clean up bags stopped. no outline") and SB.shown(K) == 0, K.status())
	local E = SB.world({ saved = { options = { ["windows.sortFrom"] = "other", ["windows.sortButton"] = "none" } } })
	E.ns.Outline = function() error("boom", 0) end
	check("sortbags: before the part stops the direction is written", E.sort.rtl == true)
	E.ns.Set("windows.sortButton", "slots")
	check("sortbags: a part that stopped gives the direction back", has(E.status(), "clean up bags stopped") and E.sort.rtl == false and E.env.FlatUICharDB.sortDirection == nil, E.status())

	local Y = SB.world(nil, function(X)
		X.rawOf[X.env.ContainerFrame4].forbidden = true
		X.env.ContainerFrame5 = nil
		X.env.BankFrame = nil
	end)
	check("sortbags: a window the client does not have, a forbidden one, and a missing bank are skipped without a word", SB.made(Y) == 6 and #SB.buttons(Y, "ContainerFrame4") == 0 and allClean(Y) and #Y.out == 0, problems(Y))
end

-- 11. The movers.
do
	local W = SB.world()
	W.rawOf[W.env.ContainerFrame3].shown = true
	W.env.UpdateContainerFrameAnchors()
	local grip
	for _, f in ipairs(W.addonFrames) do
		local raw = W.rawOf[f]
		if raw.parent == W.env.ContainerFrame3 and raw.mouse and raw.points[1] and raw.points[1][1] == "TOPLEFT" then
			grip = f
		end
	end
	local button = SB.buttons(W, "ContainerFrame3")[1]
	check("sortbags: the bag has the title bar of the movers, two levels above it, and the button lies one level above that", grip and W.rawOf[grip].level == W.rawOf[W.env.ContainerFrame3].level + 2
		and W.rawOf[button].level == W.rawOf[grip].level + 1)
	local l, b, w, h = W.rectOf(button)
	check("sortbags: a press at the middle of the button goes to the button, and not to the title bar", W.hitAt(l + w / 2, b + h / 2) == button)
	local function spot()
		local p = W.rawOf[W.env.ContainerFrame3].points[1]
		return p[1] .. g(p[4]) .. g(p[5])
	end
	local before = spot()
	W.pressAt(l + w / 2, b + h / 2, "LeftButton", button)
	W.cursor = { l - 300, b - 200 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("sortbags: a press on the button that is let go far away does not drag the bag and is no click", SB.asked(W) == "" and before == spot(), before .. " " .. spot())
	SB.click(W, "ContainerFrame3")
	check("sortbags: a click on the button sorts and does not drag the bag", SB.asked(W) == "SortBags" and before == spot(), before .. " " .. spot())
	check("sortbags: the title bar still takes a press beside the button", W.hitAt(1670, 190) == grip)
	W.rawOf[W.env.ContainerFrame3].level = 9
	W.ns.Set("windows.sortButton", "slots")
	W.ns.Set("windows.sortButton", "title")
	check("sortbags: the level follows the window", W.rawOf[button].level == 12)
	check("sortbags: and the edges of the button follow its level", W.rawOf[W.holderOn(button)].level == 13, tostring(W.rawOf[W.holderOn(button)].level))
	check("sortbags: none of it raised", allClean(W), problems(W))
end

-- 11b. The same for the bank, which has the title bar of the movers too.
do
	local W = SB.world()
	local bank = W.env.BankFrame
	W.openWindow("BankFrame")
	local grip
	for _, f in ipairs(W.addonFrames) do
		local raw = W.rawOf[f]
		if raw.parent == bank and raw.mouse and raw.points[1] and raw.points[1][1] == "TOPLEFT" then
			grip = f
		end
	end
	local button = SB.buttons(W, "BankFrame")[1]
	local l, b, w, h = W.rectOf(button)
	local function spot()
		local p = W.rawOf[bank].points[1]
		return p[1] .. g(p[4]) .. g(p[5])
	end
	check("sortbags: the bank has the title bar of the movers, and the button lies above it", grip ~= nil and W.rawOf[button].level > W.rawOf[grip].level)
	check("sortbags: a press at the middle of the button goes to the button, and the title bar takes a press beside it", W.hitAt(l + w / 2, b + h / 2) == button and W.hitAt(l - 20, b + h / 2) == grip)
	local before = spot()
	W.pressAt(l + w / 2, b + h / 2, "LeftButton", button)
	W.cursor = { l - 300, b - 200 }
	W.update(1 / 60)
	W.releaseAt("LeftButton")
	check("sortbags: a press on the button of the bank that is let go far away does not drag the bank and is no click", SB.asked(W) == "" and before == spot(), before .. " " .. spot())
	SB.click(W, "BankFrame")
	check("sortbags: a click on it sorts the bank and does not drag it", SB.asked(W) == "SortBank 0" and before == spot(), before .. " " .. spot())
	check("sortbags: none of it raised", allClean(W), problems(W))
end

-- 12. The words.
do
	local W = SB.world()
	local texts = { SB.cursor, SB.closed, SB.kind, SB.tabs, SB.missing, SB.note }
	for line in (SB.help .. "\n"):gmatch("([^\n]*)\n") do
		texts[#texts + 1] = line
	end
	for _, p in ipairs(W.ns.PAGES) do
		if p.key == "windows" then
			local on
			for _, item in ipairs(p) do
				on = item.section == "Clean up bags" or (on and not item.section)
				if on then
					texts[#texts + 1] = item.section or item.label
					texts[#texts + 1] = item.tip
					for _, choice in ipairs(item.choices or {}) do
						texts[#texts + 1] = choice[2]
					end
				end
			end
		end
	end
	local BANNED = { "carries", "sits", "lives in", "lands", "runs through", "ensure", "simply", "easily", "leverage", "robust", "seamless", "delve", "addon", "this build", "the system", "nothing is" }
	local bad = {}
	for _, text in ipairs(texts) do
		if type(text) == "string" and not text:find("^/flatui") then
			local low = text:lower()
			for _, word in ipairs(BANNED) do
				if low:find(word, 1, true) then
					bad[#bad + 1] = word .. " in " .. text:sub(1, 40)
				end
			end
			if text:find("[" .. string.char(128) .. "-" .. string.char(255) .. "]") then
				bad[#bad + 1] = "non-ASCII in " .. text:sub(1, 40)
			end
			local starts = true
			for word in text:gmatch("%S+") do
				local plain = word:gsub("[%p]", "")
				if not starts and plain:find("^%u%l") then
					bad[#bad + 1] = "capital " .. plain .. " in " .. text:sub(1, 40)
				end
				starts = word:find("[.:;]$") ~= nil
			end
		end
	end
	check("sortbags: every label, tip, choice, chat line and status line is in sentence case and free of the banned words", #bad == 0 and #texts > 18, table.concat(bad, "; ") .. " " .. #texts)
end
end
-- <<< clean up bags (end)

-- >>> centring (begin)
-- Centring a handle on the horizontal middle of the screen: the snap, the button, Alt and click, the middle line, and the handles that are
-- ticked. The helpers of the movers suite are the ones it hands on. The sections are one function, so that their locals are not counted
-- against the 200 locals of this file's main function.
do
local function centring()
local mw, opt, entry, pts = suiteKit.mw, suiteKit.opt, suiteKit.entry, suiteKit.pts
local rectIs, rectText, allClean, problems, outText = suiteKit.rectIs, suiteKit.rectText, suiteKit.allClean, suiteKit.problems, suiteKit.outText
-- The values the sections share. A world at UI scale 1 is 1920 by 1080 units, so its middle is 960. Error text is 512 wide, and Alerts 200.
local K = { middle = 960, snap = 8, errorHalf = 256, alertHalf = 100, pixel = 768 / 1080 }

-- The frames of the addon's that hang from a handle.
local function kids(W, label)
	local list = {}
	for _, f in ipairs(W.addonFrames) do
		if f.parent == W.handle(label) then
			list[#list + 1] = f
		end
	end
	return list
end
-- The one that has a bar of the given size in its picture: the centre button has a bar 2 by 10 down its middle and the tick box a mark 8 by 8.
local function part(W, label, width, height)
	for _, f in ipairs(kids(W, label)) do
		for _, t in ipairs(f.regions) do
			if t.width == width and t.height == height then
				return f
			end
		end
	end
end
local function button(W, label)
	return part(W, label, 2, 10)
end
local function box(W, label)
	return part(W, label, 8, 8)
end
local function click(f)
	f.scripts.OnMouseUp(f, "LeftButton")
end
-- The mark in a tick box, the one texture that is 8 by 8.
local function mark(f)
	for _, t in ipairs(f.regions) do
		if t.width == 8 and t.height == 8 then
			return t
		end
	end
end
-- The middle line: the one frame of the addon's that hangs from both the top and the bottom of UIParent.
local function lineOf(W)
	for _, f in ipairs(W.addonFrames) do
		if f.parent == W.env.UIParent and #f.points == 2 and f.points[1][1] == "TOP" and f.points[2][1] == "BOTTOM" then
			return f
		end
	end
end
local function lineShown(W)
	local line = lineOf(W)
	return line ~= nil and line.shown == true
end
-- A fresh world with the handles open.
local function open(options, extra)
	local o = { saved = opt(options or {}) }
	for key, value in pairs(extra or {}) do
		o[key] = value
	end
	local W = mw(o)
	W.slash("move")
	return W
end
local function calls(W, name, call)
	return W.rawOf[W.env[name]].calls[call] or 0
end
local function middleOf(W, label)
	local l, _, w = W.rectOf(W.handle(label))
	return l + w / 2
end

-- Snap while dragging.
do
	local W = open()
	local f = W.dragStart("Error text")
	-- Drags the handle so that its middle is d units right of the middle of the screen, and says where its left edge is.
	local function at(d, bottom)
		W.dragTo(K.middle + d - K.errorHalf, bottom or 700)
		local l, b = W.rectOf(f)
		return l, b
	end
	local l, b = at(K.snap - 0.1)
	check("centre: a handle whose middle comes within 8 units of the middle of the screen snaps there", near(l, 704), g(l))
	check("centre: and keeps its height", near(b, 700), g(b))
	check("centre: at exactly 8 units it snaps", near(at(K.snap), 704))
	check("centre: at 8.1 units it does not", near(at(K.snap + 0.1), 712.1), g(at(K.snap + 0.1)))
	check("centre: it snaps on the other side as well", near(at(-K.snap + 0.1), 704) and near(at(-K.snap), 704), g(at(-K.snap)))
	check("centre: and does not beyond 8 units there", near(at(-K.snap - 0.1), 695.9), g(at(-K.snap - 0.1)))
	check("centre: the height is the cursor's whether it snaps or not", near(select(2, at(0, 640)), 640) and near(select(2, at(30, 333)), 333))
	W.dragTo(5000, -300)
	local rl, rb = W.rectOf(f)
	check("centre: the handle is held on the screen at the right and at the bottom", near(rl, 1920 - 512) and near(rb, 0), g(rl) .. "," .. g(rb))
	W.dragTo(-500, 5000)
	rl, rb = W.rectOf(f)
	check("centre: and at the left and at the top", near(rl, 0) and near(rb, 1080 - 60), g(rl) .. "," .. g(rb))
	W.dragTo(300, 400)
	local sets = f.calls.SetPoint
	f.scripts.OnUpdate(f, 0.016)
	f.scripts.OnUpdate(f, 0.016)
	check("centre: a frame drawn with the cursor where it was anchors the handle again no more", f.calls.SetPoint == sets, f.calls.SetPoint - sets)
	check("centre: away from the middle the handle is where the cursor takes it", rectIs(W, "UIErrorsFrame", 704, 898, 512, 60) and (function()
		local x, y = W.rectOf(f)
		return near(x, 300) and near(y, 400)
	end)())
	W.dragEnd()
	check("centre: dropped there it is saved where it was left, by the point of its row", (function()
		local e = entry(W, "UIErrorsFrame")
		return e and e.point == "TOP" and near(e.x, 300 + K.errorHalf - K.middle) and near(e.y, 460 - 1080)
	end)())
	-- The distance is measured from the middle of the handle, whatever its width.
	local a = W.dragStart("Alerts")
	W.dragTo(K.middle - K.alertHalf + 7, 500)
	check("centre: a narrow handle snaps by its middle too", near((W.rectOf(a)), 860), g((W.rectOf(a))))
	W.dragTo(K.middle - K.alertHalf + 9, 500)
	check("centre: and not beyond 8 units", near((W.rectOf(a)), 869), g((W.rectOf(a))))
	W.dragTo(K.middle - K.alertHalf + 7, 500)
	W.dragEnd()
	check("centre: a handle dropped on the middle is saved in the middle column, with no offset across", (function()
		local e = entry(W, "AlertFrame")
		return e and e.point == "BOTTOM" and e.x == 0 and near(e.y, 500)
	end)(), tostring(entry(W, "AlertFrame") and entry(W, "AlertFrame").x))
	check("centre: and its frame is on the middle", pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,500 @1" and near(middleOf(W, "Alerts"), K.middle), pts(W, W.env.AlertFrame))
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- A frame saved by a point at a side is saved by the point in the middle column on the same row.
	local W = open()
	W.openWindow("CharacterFrame")
	W.run(0.25)
	W.drag("Character", 791 + 5, 300)
	local e = entry(W, "CharacterFrame")
	check("centre: a window that snaps is saved by TOP and the height of its top edge", e and e.point == "TOP" and e.x == 0 and near(e.y, 300 + 424 - 1080) and e.kind == "window", e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("centre: and is in the middle with the same size", rectIs(W, "CharacterFrame", 791, 300, 338, 424), rectText(W, "CharacterFrame"))
	W.drag("Player frame", 844 + 3, 300)
	e = entry(W, "PlayerFrame")
	check("centre: a frame with no point of its own is saved by the row of the third it is in", e and e.point == "BOTTOM" and e.x == 0 and near(e.y, 300) and rectIs(W, "PlayerFrame", 844, 300, 232, 100), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
end
do
	-- Off: nothing snaps.
	local W = open({ ["movers.snap"] = "off" })
	local f = W.dragStart("Error text")
	W.dragTo(704 + 3, 700)
	check("centre: with Snap while dragging off the handle stays where the cursor takes it", near((W.rectOf(f)), 707), g((W.rectOf(f))))
	W.dragEnd()
	local e = entry(W, "UIErrorsFrame")
	check("centre: and is saved there, by the point of the list", e and e.point == "TOP" and near(e.x, 3) and rectIs(W, "UIErrorsFrame", 707, 700, 512, 60), e and (e.point .. " " .. g(e.x)))
	W.change("movers.snap", "To the middle of the screen")
	W.drag("Error text", 704 + 3, 700)
	check("centre: and on again it snaps", rectIs(W, "UIErrorsFrame", 704, 700, 512, 60))
end
do
	-- The drag follows the cursor from the place the handle was taken, and the engine does not move it.
	local W = open()
	local f = W.dragStart("Error text")
	check("centre: a drag runs a script each frame and does not start the engine's move", type(f.scripts.OnUpdate) == "function" and not f.moving)
	W.dragTo(500, 600)
	local l, b = W.rectOf(f)
	check("centre: the handle keeps the grip it was taken with", near(l, 500) and near(b, 600), g(l) .. "," .. g(b))
	W.dragEnd()
	check("centre: the script is gone with the drop", f.scripts.OnUpdate == nil)
	W.dragStart("Error text")
	W.dragTo(400, 450)
	W.mouse.LeftButton = false
	W.dragTo(300, 300)
	local dropped = entry(W, "UIErrorsFrame")
	check("centre: a button let go of away from the handle ends the drag", f.scripts.OnUpdate == nil and not lineShown(W), tostring(f.scripts.OnUpdate))
	check("centre: and saves the spot where the handle was last drawn, not the one before and not where the cursor is now", dropped and dropped.point == "TOP" and near(dropped.x, 400 + K.errorHalf - K.middle)
		and near(dropped.y, 450 + 60 - 1080) and rectIs(W, "UIErrorsFrame", 400, 450, 512, 60), dropped and (dropped.point .. " " .. g(dropped.x) .. "," .. g(dropped.y)))
	W.grab = nil
	f.scripts.OnDragStop(f)
	check("centre: and a drop the handle hears afterwards changes nothing", rectIs(W, "UIErrorsFrame", 400, 450, 512, 60), rectText(W, "UIErrorsFrame"))
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- A cursor the client will not give: the engine moves the handle, and the drop snaps it.
	local W = open()
	W.cursorFault = "secret"
	local f = W.dragStart("Error text")
	check("centre: with no cursor to read the engine moves the handle", f.moving == true and f.scripts.OnUpdate == nil)
	W.dragTo(704 + 5, 700)
	W.dragEnd()
	check("centre: and the drop snaps it", rectIs(W, "UIErrorsFrame", 704, 700, 512, 60) and entry(W, "UIErrorsFrame").x == 0, rectText(W, "UIErrorsFrame"))
	W.dragStart("Error text")
	W.dragTo(704 + 20, 650)
	W.dragEnd()
	check("centre: beyond 8 units it does not", rectIs(W, "UIErrorsFrame", 724, 650, 512, 60) and near(entry(W, "UIErrorsFrame").x, 20), rectText(W, "UIErrorsFrame"))
	W.cursorFault = nil
end
do
	-- The distance is in the units of UIParent: at a smaller UI scale the screen is wider in units, and the middle is the middle of that.
	local W = mw({ uiScale = 0.64 })
	W.slash("move")
	local sw = 1080 * 16 / 9 / 0.64
	local f = W.dragStart("Error text")
	W.dragTo(sw / 2 - 256 + 7, 600)
	check("centre: at another UI scale the middle is the middle of the wider screen", near((W.rectOf(f)), sw / 2 - 256), g((W.rectOf(f))))
	W.dragTo(sw / 2 - 256 + 9, 600)
	check("centre: and the distance is the same in units", near((W.rectOf(f)), sw / 2 - 256 + 9))
	W.dragEnd()
end

-- The row of the point a centred frame is saved by is the row of the point it had, or of the third its middle is in.
do
	local W = open()
	local rows = { { 50, "BOTTOM" }, { 450, "CENTER" }, { 800, "TOP" } }
	local good = true
	local seen = {}
	for _, row in ipairs(rows) do
		W.drag("Minimap", 50, row[1])
		click(button(W, "Minimap"))
		local e = entry(W, "MinimapCluster")
		good = good and e ~= nil and e.point == row[2] and e.x == 0 and rectIs(W, "MinimapCluster", 864, row[1], 192, 192)
		seen[#seen + 1] = e and (e.point .. " " .. g(e.x)) or "none"
	end
	check("centre: a frame in the bottom, middle and top third is saved by BOTTOM, CENTER and TOP", good, table.concat(seen, ", "))
	W.drag("Alerts", 300, 500)
	click(button(W, "Alerts"))
	check("centre: a frame listed with a point keeps the row of that point", entry(W, "AlertFrame").point == "BOTTOM" and pts(W, W.env.AlertFrame) == "BOTTOM>UIParent:BOTTOM 0,500 @1", pts(W, W.env.AlertFrame))
end

-- The button on a handle.
do
	local W = open()
	local names = { "Alerts", "Buffs", "Error text", "Minimap", "Player frame", "Top widgets" }
	local both = true
	for _, label in ipairs(names) do
		local b, t = button(W, label), box(W, label)
		both = both and b ~= nil and t ~= nil and b.shown and t.shown and b.mouse == true and t.mouse == true and #kids(W, label) == 2
	end
	check("centre: by default every handle has a button in its top right corner and a tick box in its top left corner", both)
	local b = button(W, "Buffs")
	local bp, tp = b.points[1], box(W, "Buffs").points[1]
	check("centre: the button is 14 units square, 2 units in from the top right corner, and the tick box 2 in from the top left", b.width == 14 and b.height == 14 and #b.points == 1
		and bp[1] == "TOPRIGHT" and bp[2] == W.handle("Buffs") and bp[3] == "TOPRIGHT" and bp[4] == -2 and bp[5] == -2
		and tp[1] == "TOPLEFT" and tp[2] == W.handle("Buffs") and tp[3] == "TOPLEFT" and tp[4] == 2 and tp[5] == -2)
	check("centre: a button is not a handle", #W.handles() == 9 and W.handle("Buffs") ~= nil)
	local was = pts(W, W.env.BuffFrame)
	check("centre: before the click the frame is at the right of the screen", rectIs(W, "BuffFrame", 1420, 1010, 300, 60), rectText(W, "BuffFrame"))
	click(b)
	check("centre: the button puts the frame on the middle at the height it had, with the size it had", rectIs(W, "BuffFrame", 810, 1010, 300, 60), rectText(W, "BuffFrame"))
	check("centre: the handle goes with it", near(middleOf(W, "Buffs"), K.middle) and (select(2, W.rectOf(W.handle("Buffs")))) == 1010)
	local e = entry(W, "BuffFrame")
	check("centre: it is saved as a move is, by the point in the middle column of its third", e and e.point == "TOP" and e.x == 0 and near(e.y, -10) and e.kind == "hud" and e.label == nil, e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("centre: the frame has the one point on UIParent", pts(W, W.env.BuffFrame) == "TOP>UIParent:TOP 0,-10 @1", pts(W, W.env.BuffFrame))
	check("centre: the status counts it", W.line("Movers") == "Movers: on, 1 moved", W.line("Movers"))
	W.run(2)
	check("centre: it stays", rectIs(W, "BuffFrame", 810, 1010, 300, 60))
	W.rightClick("Buffs")
	check("centre: a right click puts it back where the game had it", pts(W, W.env.BuffFrame) == was and entry(W, "BuffFrame") == nil, pts(W, W.env.BuffFrame))
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- Windows, system frames that are protected, the tooltip, a frame taken with the picker, a frame with a size of its own.
	local W = open({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" })
	W.openWindow("CharacterFrame")
	W.run(0.25)
	click(button(W, "Character"))
	check("centre: a window goes to the middle with its top where it was", rectIs(W, "CharacterFrame", 791, 1080 - 116 - 424, 338, 424), rectText(W, "CharacterFrame"))
	check("centre: and is saved by TOP", entry(W, "CharacterFrame").point == "TOP" and entry(W, "CharacterFrame").x == 0 and entry(W, "CharacterFrame").kind == "window")
	click(button(W, "Player frame"))
	check("centre: a frame the game protects is centred out of combat", rectIs(W, "PlayerFrame", 844, 960, 232, 100), rectText(W, "PlayerFrame"))
	click(button(W, "Minimap"))
	check("centre: the minimap too, which hangs from the corner", rectIs(W, "MinimapCluster", 864, 888, 192, 192), rectText(W, "MinimapCluster"))
	click(button(W, "Tooltip"))
	local e = entry(W, "FlatUITooltip")
	check("centre: the tooltip handle has no game frame, and its spot is centred", e and e.point == "BOTTOM" and e.x == 0 and near(e.y, 85) and near(middleOf(W, "Tooltip"), K.middle), e and (e.point .. " " .. g(e.x) .. "," .. g(e.y)))
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- A frame with a scale of its own keeps it, and its middle is the middle.
	local W = open(nil, nil)
	W.keys.ctrl = true
	W.wheel("Buffs", 1)
	W.wheel("Buffs", 1)
	W.keys.ctrl = false
	local scale = entry(W, "BuffFrame").scale
	click(button(W, "Buffs"))
	local l, b, w, h = W.rectOf(W.env.BuffFrame)
	check("centre: a scaled frame keeps its scale and its middle is the middle", near(entry(W, "BuffFrame").scale, scale) and near(l + w / 2, K.middle, 1e-6) and near(w, 330, 1e-6) and near(b + h, 1070, 1e-6), g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
end
do
	-- A frame taken with the picker has a name for a label, and keeps it.
	local W = mw()
	W.slash("grab")
	W.foci = { W.panel }
	W.update(0.1)
	W.keys.alt = true
	W.update(0.02)
	W.keys.alt = false
	click(button(W, "TestPanel"))
	local e = entry(W, "TestPanel")
	check("centre: a frame taken with the picker is centred and keeps its label", e and e.label == "TestPanel" and e.x == 0 and near(middleOf(W, "TestPanel"), K.middle) and rectIs(W, "TestPanel", 900, 610, 120, 60), e and (e.point .. " " .. g(e.x)) .. rectText(W, "TestPanel"))
end

-- Alt and click.
do
	local W = open({ ["movers.centreWith"] = "alt" })
	local h = W.handle("Buffs")
	check("centre: with Alt and click only, no handle has a button", button(W, "Buffs") == nil and button(W, "Error text") == nil)
	h.scripts.OnMouseUp(h, "LeftButton")
	check("centre: a click without Alt does nothing", rectIs(W, "BuffFrame", 1420, 1010, 300, 60) and entry(W, "BuffFrame") == nil)
	W.keys.alt = true
	h.scripts.OnMouseUp(h, "RightButton")
	check("centre: Alt and a right click does not centre", rectIs(W, "BuffFrame", 1420, 1010, 300, 60) and entry(W, "BuffFrame") == nil)
	h.scripts.OnMouseUp(h, "LeftButton")
	W.keys.alt = false
	check("centre: Alt and a click centres the frame, keeping its height", rectIs(W, "BuffFrame", 810, 1010, 300, 60) and entry(W, "BuffFrame").x == 0, rectText(W, "BuffFrame"))
	check("centre: and the handle", near(middleOf(W, "Buffs"), K.middle))
	-- A drag with Alt held is not a click.
	W.keys.alt = true
	W.drag("Minimap", 100, 300)
	local m = W.handle("Minimap")
	m.scripts.OnMouseUp(m, "LeftButton")
	check("centre: the release that ends a drag is not a click, so a drag with Alt held centres nothing", rectIs(W, "MinimapCluster", 100, 300, 192, 192), rectText(W, "MinimapCluster"))
	m.scripts.OnMouseUp(m, "LeftButton")
	check("centre: and it is the only one: the next release with Alt held centres", rectIs(W, "MinimapCluster", 864, 300, 192, 192), rectText(W, "MinimapCluster"))
	W.drag("Player frame", 100, 300)
	local p = W.handle("Player frame")
	p.scripts.OnMouseDown(p, "LeftButton")
	p.scripts.OnMouseUp(p, "LeftButton")
	W.keys.alt = false
	check("centre: a press clears the drag before it, so a click that follows a drag with no release heard centres", rectIs(W, "PlayerFrame", 844, 300, 232, 100), rectText(W, "PlayerFrame"))
	W.change("movers.centreWith", "A button on the handle")
	W.flush()
	local made = button(W, "Error text")
	check("centre: and changed to the button, one is made in the corner of the handle", made ~= nil and made.shown and #made.points == 1 and made.points[1][1] == "TOPRIGHT" and made.points[1][2] == W.handle("Error text"))
	check("centre: no violation", allClean(W), problems(W))
end
do
	local W = open({ ["movers.centreWith"] = "button" })
	local h = W.handle("Buffs")
	W.keys.alt = true
	h.scripts.OnMouseUp(h, "LeftButton")
	W.keys.alt = false
	check("centre: with the button only, Alt and a click does nothing", rectIs(W, "BuffFrame", 1420, 1010, 300, 60) and button(W, "Buffs").shown)
end
do
	local W = open({ ["movers.centreWith"] = "both" })
	local h = W.handle("Buffs")
	check("centre: with both, there is a button", button(W, "Buffs") ~= nil and button(W, "Buffs").shown)
	W.keys.alt = true
	h.scripts.OnMouseUp(h, "LeftButton")
	W.keys.alt = false
	check("centre: and Alt and a click works", rectIs(W, "BuffFrame", 810, 1010, 300, 60))
	click(button(W, "Minimap"))
	check("centre: and so does the button", rectIs(W, "MinimapCluster", 864, 888, 192, 192))
end
do
	-- The setting changes with the handles open.
	local W = open()
	local frames = #W.addonFrames
	W.change("movers.centreWith", "Alt and click")
	W.flush()
	check("centre: changed to Alt and click, the buttons go", not button(W, "Buffs").shown and not button(W, "Error text").shown)
	W.change("movers.centreWith", "A button on the handle")
	W.flush()
	check("centre: and back, they return without new frames", button(W, "Buffs").shown and #W.addonFrames == frames, #W.addonFrames - frames)
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- Handles with no button: a handle the game places, and one that is too small.
	local W = mw({ layout = { systems = true }, saved = opt({ ["movers.centreAll"] = "none", ["movers.centreWith"] = "both" }) })
	W.rawOf[W.env.UIWidgetTopCenterContainerFrame].width = 27
	W.rawOf[W.env.UIWidgetTopCenterContainerFrame].height = 60
	W.rawOf[W.env.BuffFrame].width = 28
	W.rawOf[W.env.PlayerFrame].height = 17
	W.rawOf[W.env.PlayerFrame].width = 232
	W.slash("move")
	local grey
	for _, f in ipairs(W.addonFrames) do
		local text = f.movable and f.fonts[1] and f.fonts[1].text
		if text and text:find("(placed by the game)", 1, true) then
			grey = f
		end
	end
	check("centre: a handle the game places has no button and no tick box", grey ~= nil and not grey.mouse and #(function()
		local list = {}
		for _, f in ipairs(W.addonFrames) do
			if f.parent == grey then
				list[#list + 1] = f
			end
		end
		return list
	end)() == 0)
	local small = W.handle("Top widgets")
	local function at(label)
		local b = button(W, label)
		return b and b.points[1], b
	end
	local inside, buffs = at("Buffs")
	check("centre: a handle 28 units wide holds the button, in its top right corner", inside and buffs.shown and inside[1] == "TOPRIGHT" and inside[2] == W.handle("Buffs") and inside[3] == "TOPRIGHT"
		and inside[4] == -2 and inside[5] == -2)
	local below, hung = at("Top widgets")
	check("centre: one 27 wide is too small for it, so the button is under the handle, right of its middle, as the handle is at the top of the screen", small ~= nil and small.width == 27
		and below and hung.shown and below[1] == "TOPLEFT" and below[2] == small and below[3] == "BOTTOM" and below[4] == 1 and below[5] == -2 and #hung.points == 1)
	local above, lifted = at("Player frame")
	check("centre: one 17 high is too small for it too, so the button is over the handle, right of its middle", W.handle("Player frame").height == 17
		and above and lifted.shown and above[1] == "BOTTOMLEFT" and above[2] == W.handle("Player frame") and above[3] == "TOP" and above[4] == 1 and above[5] == 2 and #lifted.points == 1)
	check("centre: and a small handle has the button only, as the setting says, and no tick box", box(W, "Top widgets") == nil and box(W, "Player frame") == nil)
	W.keys.alt = true
	small.scripts.OnMouseUp(small, "LeftButton")
	W.keys.alt = false
	check("centre: Alt and a click centres a small handle", near(middleOf(W, "Top widgets"), K.middle) and entry(W, "UIWidgetTopCenterContainerFrame") ~= nil)
	check("centre: before the click the frame is at the left of the screen", rectIs(W, "PlayerFrame", 20, 1043, 232, 17), rectText(W, "PlayerFrame"))
	click(lifted)
	check("centre: and its button, which lies outside it, centres the frame", rectIs(W, "PlayerFrame", 844, 1043, 232, 17), rectText(W, "PlayerFrame"))
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- A handle too small for the button and the tick box has them in a pair beside its middle: over it, and under it where the screen ends over it.
	local W = mw()
	for _, name in ipairs({ "PlayerFrame", "BuffFrame" }) do
		W.rawOf[W.env[name]].width, W.rawOf[W.env[name]].height = 20, 20
	end
	W.slash("move")
	local frames = #W.addonFrames
	local pb, pt = button(W, "Player frame"), box(W, "Player frame")
	local bl, bb, bw, bh = W.rectOf(pb)
	local tl, tb, tw, th = W.rectOf(pt)
	check("centre: a handle 20 units square has its button over it, right of its middle, and its tick box left of the middle",
		pb ~= nil and pt ~= nil and pb.shown and pt.shown and near(bl, 31) and near(bb, 1062) and near(bw, 14) and near(bh, 14) and near(tl, 15) and near(tb, 1062) and near(tw, 14) and near(th, 14),
		g(bl) .. "," .. g(bb) .. " " .. g(tl) .. "," .. g(tb))
	local ub, ut = button(W, "Buffs"), box(W, "Buffs")
	bl, bb = W.rectOf(ub)
	tl, tb = W.rectOf(ut)
	check("centre: at the top of the screen they are under the handle, with a gap of 2 units", ub ~= nil and ut ~= nil and near(bl, 1711) and near(bb, 1034) and near(tl, 1695) and near(tb, 1034), g(bl) .. "," .. g(bb) .. " " .. g(tl) .. "," .. g(tb))
	check("centre: a button outside its handle takes the mouse", pb.mouse == true and pt.mouse == true and ub.mouse == true and ut.mouse == true)
	local sets = { pb.calls.SetPoint, pt.calls.SetPoint, ub.calls.SetPoint, ut.calls.SetPoint }
	W.run(1)
	check("centre: a pair that is in place is not anchored again", pb.calls.SetPoint == sets[1] and pt.calls.SetPoint == sets[2] and ub.calls.SetPoint == sets[3] and ut.calls.SetPoint == sets[4],
		pb.calls.SetPoint - sets[1])
	click(pb)
	check("centre: its button centres the frame", rectIs(W, "PlayerFrame", 950, 1040, 20, 20), rectText(W, "PlayerFrame"))
	check("centre: and the pair goes with the handle", near((W.rectOf(pb)), 961) and near((W.rectOf(pt)), 945) and near(select(2, W.rectOf(pb)), 1062))
	click(pt)
	click(ut)
	check("centre: the tick boxes there tick", mark(pt).shown and mark(ut).shown)
	W.press("Centre ticked")
	check("centre: and Centre ticked centres the handle it ticked, which is under the handle", rectIs(W, "BuffFrame", 950, 1050, 20, 20) and not mark(pt).shown and not mark(ut).shown, rectText(W, "BuffFrame"))
	W.rawOf[W.env.PlayerFrame].width, W.rawOf[W.env.PlayerFrame].height = 232, 100
	W.run(0.5)
	local back = pb.points[1]
	check("centre: a handle that grows to hold them takes them into its corners, with no new frame", #pb.points == 1 and back[1] == "TOPRIGHT" and back[3] == "TOPRIGHT" and back[4] == -2 and back[5] == -2
		and #pt.points == 1 and pt.points[1][1] == "TOPLEFT" and #W.addonFrames == frames, #W.addonFrames - frames)
	check("centre: no violation", allClean(W), problems(W))
end

-- The middle line.
do
	local W = mw()
	check("centre: at login the line is not made", lineOf(W) == nil)
	W.slash("move")
	check("centre: by default it is not shown with the handles", not lineShown(W))
	local f = W.dragStart("Error text")
	local line = lineOf(W)
	check("centre: it is shown while a handle is dragged", line ~= nil and line.shown == true)
	W.dragTo(300, 300)
	local l, b, w, h = W.rectOf(line)
	check("centre: it is a thin line down the screen, at the middle of it, over the handles", near(l + w / 2, K.middle) and near(b, 0) and near(h, 1080) and near(w, K.pixel, 1e-6)
		and line.strata == "FULLSCREEN_DIALOG" and line.mouse ~= true, g(l) .. "," .. g(b) .. " " .. g(w) .. "x" .. g(h))
	check("centre: it is dim away from the middle", near(line.alpha, 0.6))
	check("centre: and gold, the colour of the handles", line.regions[1].color and near(line.regions[1].color[1], 1) and near(line.regions[1].color[2], 0.82) and near(line.regions[1].color[3], 0))
	W.dragTo(K.middle - 256 + 3, 300)
	check("centre: and bright while the handle is snapped to it", near(line.alpha, 1))
	W.dragTo(K.middle - 256 + 30, 300)
	check("centre: dim again when the handle leaves", near(line.alpha, 0.6))
	local texture
	for _, t in ipairs(line.regions) do
		texture = t
	end
	check("centre: it is a plain colour, as the edges of the outlines are, not pulled to a pixel", texture and texture.color and texture.snap == false and texture.bias == 0)
	W.dragEnd()
	check("centre: it goes with the drop", not line.shown)
	check("centre: no violation", allClean(W), problems(W))
end
do
	local W = open({ ["movers.middleLine"] = "always" })
	local line = lineOf(W)
	check("centre: set to always, the line is shown with the handles", line ~= nil and line.shown == true)
	W.dragStart("Error text")
	W.dragTo(704 + 3, 700)
	check("centre: and is bright while a handle is snapped to it", near(line.alpha, 1))
	W.dragEnd()
	check("centre: and stays after a drag, dim again", line.shown == true and near(line.alpha, 0.6), tostring(line.alpha))
	W.slash("move")
	check("centre: and goes when the handles close", not line.shown)
	W.slash("move")
	check("centre: and returns when they open", line.shown == true)
	W.change("movers.middleLine", "Off")
	W.flush()
	check("centre: set to Off with the handles open, it goes", not line.shown)
	W.dragStart("Error text")
	check("centre: and a drag does not show it", not line.shown)
	W.dragEnd()
	W.change("movers.middleLine", "Shown while dragging")
	W.flush()
	check("centre: set to shown while dragging with the handles open, it is not shown", not line.shown)
end
do
	local W = open({ ["movers.middleLine"] = "off" })
	W.dragStart("Error text")
	W.dragEnd()
	check("centre: set to Off from the start, the line is never made", lineOf(W) == nil)
end
do
	-- At another UI scale the line is as thin on the screen, and in the middle of it.
	local W = mw({ uiScale = 0.64, saved = opt({ ["movers.middleLine"] = "always" }) })
	W.slash("move")
	local l, _, w = W.rectOf(lineOf(W))
	check("centre: at UI scale 0.64 the line is in the middle of the wider screen and one pixel wide", near(l + w / 2, 1080 * 16 / 9 / 0.64 / 2) and near(w, K.pixel / 0.64, 1e-6), g(l) .. " " .. g(w))
	W.change("general.scaleOn", true)
	W.change("general.scale", 70)
	W.advance(0.3)
	W.run(0.5)
	l, _, w = W.rectOf(lineOf(W))
	check("centre: and the custom scale moves nothing: it is in the middle and one pixel wide at 70 percent", near(W.scale(), 0.7) and near(l + w / 2, 1080 * 16 / 9 / 0.7 / 2) and near(w, K.pixel / 0.7, 1e-6), W.scale() .. " " .. g(l) .. " " .. g(w))
end

-- Centre everything.
do
	local W = open()
	local panel = W.textFrame("Centre ticked")
	check("centre: the Movers panel has a Centre ticked button by default", panel ~= nil and panel.shown == true and panel.width == 82)
	check("centre: it is 8 units from Reset all and 8 from Done, as the other buttons are", (function()
		local reset, done = W.textFrame("Reset all"), W.textFrame("Done")
		local pl, _, pw = W.rectOf(panel)
		local rl, _, rw = W.rectOf(reset)
		local dl = W.rectOf(done)
		return near(pl, rl + rw + 8) and near(pl + pw + 8, dl)
	end)())
	local bt, mt = box(W, "Buffs"), box(W, "Minimap")
	check("centre: a tick box shows no mark until it is ticked", not mark(bt).shown and not mark(mt).shown)
	click(bt)
	click(mt)
	check("centre: ticking shows the mark", mark(bt).shown and mark(mt).shown and not mark(box(W, "Alerts")).shown)
	click(bt)
	check("centre: a second click clears it", not mark(bt).shown)
	click(bt)
	local before = pts(W, W.env.AlertFrame) .. pts(W, W.env.UIErrorsFrame)
	W.press("Centre ticked")
	check("centre: the button centres the ticked handles", rectIs(W, "BuffFrame", 810, 1010, 300, 60) and rectIs(W, "MinimapCluster", 864, 888, 192, 192), rectText(W, "BuffFrame") .. " " .. rectText(W, "MinimapCluster"))
	check("centre: and nothing else", before == pts(W, W.env.AlertFrame) .. pts(W, W.env.UIErrorsFrame) and entry(W, "AlertFrame") == nil and entry(W, "PlayerFrame") == nil and W.line("Movers") == "Movers: on, 2 moved", W.line("Movers"))
	check("centre: the ticks are cleared", not mark(bt).shown and not mark(mt).shown)
	check("centre: it says how many", has(outText(W), "2 handles centred."), outText(W))
	W.out = {}
	W.press("Centre ticked")
	check("centre: with nothing ticked it says so, with the next step, and moves nothing", has(outText(W), "No handle is ticked. Tick the box on each handle, then press Centre ticked.") and W.line("Movers") == "Movers: on, 2 moved", outText(W))
	click(box(W, "Alerts"))
	W.out = {}
	W.press("Centre ticked")
	check("centre: one handle is one handle", has(outText(W), "1 handle centred."), outText(W))
	click(bt)
	W.slash("move")
	check("centre: the button of the panel goes with the panel", not panel.shown)
	W.slash("move")
	check("centre: closing the handles clears the ticks, and opening them shows the button again", not mark(box(W, "Buffs")).shown and panel.shown)
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- A handle that is not shown when the button is pressed is left.
	local W = open()
	W.openWindow("CharacterFrame")
	W.run(0.25)
	click(box(W, "Character"))
	W.closeWindow("CharacterFrame")
	W.run(0.25)
	W.out = {}
	W.press("Centre ticked")
	check("centre: a handle that is hidden is not centred, and the line says why", entry(W, "CharacterFrame") == nil and has(outText(W), "Nothing was centred: the ticked handles are hidden or placed by the game."), outText(W))
end
do
	local W = open({ ["movers.centreAll"] = "none" })
	check("centre: with No such button the panel has no Centre ticked button and no handle has a tick box", not W.textFrame("Centre ticked").shown and box(W, "Buffs") == nil and box(W, "Error text") == nil and button(W, "Buffs") ~= nil)
	W.change("movers.centreAll", "A button in the Movers panel")
	W.flush()
	check("centre: and turned on with the handles open, both appear, the box in the corner of its handle", W.textFrame("Centre ticked").shown and box(W, "Buffs") ~= nil and box(W, "Buffs").shown
		and #box(W, "Buffs").points == 1 and box(W, "Buffs").points[1][1] == "TOPLEFT")
	click(box(W, "Buffs"))
	W.change("movers.centreAll", "No such button")
	W.flush()
	check("centre: and off again, they go", not W.textFrame("Centre ticked").shown and not box(W, "Buffs").shown)
	W.change("movers.centreAll", "A button in the Movers panel")
	W.flush()
	check("centre: a tick left from before still shows", mark(box(W, "Buffs")).shown)
	check("centre: no violation", allClean(W), problems(W))
end
do
	-- With every choice off nothing is made on the handles.
	local W = open({ ["movers.centreAll"] = "none", ["movers.centreWith"] = "alt", ["movers.middleLine"] = "off" })
	local hung = 0
	for _, label in ipairs({ "Alerts", "Buffs", "Error text", "Minimap", "Player frame", "Top widgets" }) do
		hung = hung + #kids(W, label)
	end
	check("centre: with the three choices off no frame hangs from a handle and no line is made", hung == 0 and lineOf(W) == nil)
end

-- In combat. The handles close when a fight starts, so the game gives no click in a fight: these are guards for a click that comes as a fight starts.
do
	local W = open()
	W.combat = true
	local was, sets = pts(W, W.env.PlayerFrame), calls(W, "PlayerFrame", "SetPoint")
	click(button(W, "Player frame"))
	check("centre guard: in combat a frame the game protects is not touched", pts(W, W.env.PlayerFrame) == was and calls(W, "PlayerFrame", "SetPoint") == sets and #W.violations == 0, problems(W))
	check("centre guard: but its spot is saved", entry(W, "PlayerFrame") ~= nil and entry(W, "PlayerFrame").x == 0, tostring(entry(W, "PlayerFrame")))
	click(button(W, "Buffs"))
	check("centre guard: a frame that is not protected goes at once", rectIs(W, "BuffFrame", 810, 1010, 300, 60), rectText(W, "BuffFrame"))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("centre guard: the protected frame goes when combat ends, once", rectIs(W, "PlayerFrame", 844, 960, 232, 100) and calls(W, "PlayerFrame", "SetPoint") == sets + 1, rectText(W, "PlayerFrame"))
	check("centre: no violation", allClean(W), problems(W))
end
do
	local W = open()
	click(box(W, "Player frame"))
	click(box(W, "Buffs"))
	W.combat = true
	W.out = {}
	W.press("Centre ticked")
	check("centre guard: Centre ticked in combat saves both and moves the one that is not protected", rectIs(W, "BuffFrame", 810, 1010, 300, 60) and rectIs(W, "PlayerFrame", 20, 960, 232, 100)
		and has(outText(W), "2 handles centred.") and not has(outText(W), "after combat"), outText(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("centre guard: and the other follows when combat ends", rectIs(W, "PlayerFrame", 844, 960, 232, 100) and allClean(W), problems(W))
end
do
	-- A drag does not start in combat, and ends with the handles when a fight starts.
	local W = open()
	W.combat = true
	local h = W.handle("Error text")
	h.scripts.OnDragStart(h)
	check("centre: a drag does not start in combat", h.scripts.OnUpdate == nil and not h.moving)
	W.combat = false
	local f = W.dragStart("Error text")
	W.combat = true
	W.fire("PLAYER_REGEN_DISABLED")
	check("centre: a fight during a drag ends it, hides the line and saves nothing", f.scripts.OnUpdate == nil and not lineShown(W) and entry(W, "UIErrorsFrame") == nil and #W.shownHandles() == 0)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
end

-- Reset, the picker, Edit Mode.
do
	local W = open()
	local was = { pts(W, W.env.BuffFrame), pts(W, W.env.MinimapCluster) }
	click(button(W, "Buffs"))
	click(button(W, "Minimap"))
	W.press("Reset all")
	W.press("Click again to reset")
	check("centre: Reset all puts centred frames back as the game had them", pts(W, W.env.BuffFrame) == was[1] and pts(W, W.env.MinimapCluster) == was[2] and next(W.spots()) == nil, pts(W, W.env.BuffFrame))
	check("centre: and their handles are over them again", near((W.rectOf(W.handle("Buffs"))), 1420))
	click(button(W, "Buffs"))
	W.slash("move reset")
	check("centre: so does /flatui move reset", pts(W, W.env.BuffFrame) == was[1] and next(W.spots()) == nil)
end
do
	-- The picker takes the mouse from the handles, and from what hangs from them.
	local W = open()
	W.slash("grab")
	check("centre: while a frame is picked the buttons and the tick boxes take no mouse", button(W, "Buffs").mouse == false and box(W, "Buffs").mouse == false)
	W.press("Pick a frame")
	check("centre: and give it back", button(W, "Buffs").mouse == true and box(W, "Buffs").mouse == true)
end
do
	-- A handle made while a frame is being picked is made without the mouse.
	local W = mw()
	W.slash("grab")
	W.openWindow("CharacterFrame")
	W.run(0.25)
	local b = button(W, "Character")
	check("centre: a button made while a frame is picked takes no mouse", b ~= nil and b.mouse == false)
end
do
	-- The words of the settings are the ones in the settings, and the tip says the distance.
	local W = mw()
	local tip
	for _, page in ipairs(W.ns.PAGES) do
		for _, item in ipairs(page) do
			if item.key == "snap" and page.key == "movers" then
				tip = item.tip
			end
		end
	end
	check("centre: the tip of Snap while dragging gives the distance that is used", tip == "A handle or a window snaps when its middle is within " .. K.snap .. " units of the middle of the screen.", tostring(tip))
	local long = {}
	for _, page in ipairs(W.ns.PAGES) do
		for _, item in ipairs(page.key == "movers" and page or {}) do
			if item.key == "snap" or item.key == "centreWith" or item.key == "middleLine" or item.key == "centreAll" then
				for _, choice in ipairs(item.choices) do
					if #choice[2] > 32 then
						long[#long + 1] = choice[2]
					end
				end
			end
		end
	end
	check("centre: every choice is short enough for the dropdown, which shows 198 units of text when closed", #long == 0, table.concat(long, ", "))
	check("centre: the defaults are the picks", W.ns.Get("movers.snap") == "middle" and W.ns.Get("movers.centreWith") == "button" and W.ns.Get("movers.middleLine") == "dragging" and W.ns.Get("movers.centreAll") == "button")
end
do
	-- A custom UI scale: the centred frame stays in the middle of the screen, whatever the scale becomes.
	local W = mw({ saved = opt({ ["general.scaleOn"] = true, ["general.scale"] = 70 }) })
	W.advance(0.3)
	W.slash("move")
	click(button(W, "Buffs"))
	local function centred()
		local l, _, w = W.rectOf(W.env.BuffFrame)
		return near(l + w / 2, 1080 * 16 / 9 / W.scale() / 2, 1e-6)
	end
	W.change("general.scale", 65)
	W.advance(0.3)
	W.run(0.5)
	check("centre: at a custom scale of 65 percent the frame is in the middle of the wider screen", near(W.scale(), 0.65) and centred(), W.scale())
	W.change("general.scale", 90)
	W.advance(0.3)
	W.run(0.5)
	check("centre: and after a change to 90 percent it still is", near(W.scale(), 0.9) and centred() and near(middleOf(W, "Buffs"), 1080 * 16 / 9 / 0.9 / 2, 1e-6), W.scale())
	W.change("general.scaleOn", false)
	W.advance(0.3)
	W.run(0.5)
	check("centre: and after the game's scale returns", near(W.scale(), 1) and centred())
	check("centre: no violation", allClean(W), problems(W))
end
-- The tooltip hangs from the middle of its row once its handle is centred, so a tooltip narrower than the handle is in the middle too.
do
	local spots = nil
	local function tooltipWorld(movers)
		return mw({ layout = { tooltip = true }, saved = opt({ ["tooltip.enabled"] = true, ["tooltip.mode"] = "fixed" }, movers) })
	end
	local W = tooltipWorld(spots)
	W.slash("move")
	click(button(W, "Tooltip"))
	W.slash("move")
	W.hover(W.panel)
	local x, y = W.tipPoint("BOTTOM")
	check("centre: the tooltip is 200 wide and its handle 250, and it hangs from the middle of its bottom edge, so it is in the middle of the screen", x ~= nil and near(x, K.middle, 1e-6) and near(y, 85, 1e-6)
		and pts(W, W.tooltip) == "BOTTOM>UIParent:BOTTOMLEFT 960,85 @1", pts(W, W.tooltip))
	local cases = { { "Top right", "TOP", 235 }, { "Left", "CENTER", 160 }, { "Bottom right", "BOTTOM", 85 }, { "Centre", "CENTER", 160 }, { "Top", "TOP", 235 } }
	local wrong = {}
	for _, case in ipairs(cases) do
		W.change("tooltip.point", case[1])
		W.update(1 / 60)
		local px, py = W.tipPoint(case[2])
		if not (px and near(px, K.middle, 1e-6) and near(py, case[3], 1e-6)) then
			wrong[#wrong + 1] = case[1] .. " " .. g(px) .. "," .. g(py)
		end
	end
	check("centre: whichever point of the tooltip is chosen it hangs from the middle of the same row of the handle", #wrong == 0, table.concat(wrong, "; "))
	check("centre: no violation", allClean(W), problems(W))
	-- A spot that is not a centred one keeps the corner: an offset across, and a point at the side with no offset.
	local A = tooltipWorld({ FlatUITooltip = { point = "BOTTOM", x = 100, y = 85, kind = "hud" } })
	A.hover(A.panel)
	local ax, ay = A.tipPoint("BOTTOMLEFT")
	check("centre: a spot in the middle column with an offset across is not centred, so the tooltip hangs from the corner it was given", ax ~= nil and near(ax, K.middle + 100 - 125, 1e-6) and near(ay, 85, 1e-6), g(ax))
	local B = tooltipWorld({ FlatUITooltip = { point = "TOPLEFT", x = 0, y = -300, kind = "hud" } })
	B.hover(B.panel)
	local bx, by = B.tipPoint("BOTTOMLEFT")
	check("centre: a spot at the left edge with no offset is not centred either", bx ~= nil and near(bx, 0, 1e-6) and near(by, 1080 - 300 - 150, 1e-6), g(bx) .. "," .. g(by))
end

-- A ticked handle that turns grey is left by Centre ticked.
do
	local W = open()
	local was = pts(W, W.env.MinimapCluster)
	click(box(W, "Minimap"))
	W.rawOf[W.env.MinimapCluster].systemInfo = nil
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	W.run(0.5)
	check("centre: a handle whose frame the game places turns grey and loses its button and tick box", W.handle("Minimap") == nil and W.shownHandles()[1] ~= nil)
	W.out = {}
	W.press("Centre ticked")
	check("centre: Centre ticked leaves a ticked handle that turned grey, and says so", entry(W, "MinimapCluster") == nil and pts(W, W.env.MinimapCluster) == was and W.line("Movers") == "Movers: on, 0 moved"
		and has(outText(W), "Nothing was centred: the ticked handles are hidden or placed by the game."), outText(W) .. W.line("Movers"))
end

-- A frame that hangs over the top of the screen keeps its height when it is centred, though the engine holds its handle on the screen.
do
