	end
	click(button(W, "Buffs"))
	local e = entry(W, "BuffFrame")
	check("centre: a frame over the top edge of the screen keeps its height when it is centred, whatever the handle that is held on the screen says", rectIs(W, "BuffFrame", 810, 1030, 300, 60)
		and e and e.point == "TOP" and e.x == 0 and near(e.y, 10), rectText(W, "BuffFrame"))
end

