	local tl, tb = W.rectOf(lt)
	check("centre: a handle 20 square at the left edge has its pair over it, moved 5 units in so that the tick box starts at the edge", bl and tl and near(bl, 16) and near(bb, 522) and near(tl, 0) and near(tb, 522),
		g(bl) .. "," .. g(bb) .. " " .. g(tl) .. "," .. g(tb))
	bl = W.rectOf(rb)
	tl = W.rectOf(rt)
