-- Combat text: you, a frame of the addon's own, centred by the button and by Centre ticked.
do
	local function hit(W)
		local known = {}
		for _, f in ipairs(W.addonFrames) do
			for _, t in ipairs(f.fonts or {}) do
				known[t] = t.calls.Show or 0
			end
		end
		W.fire("UNIT_COMBAT", "player", "HEAL", "", 300, 1)
		for _, f in ipairs(W.addonFrames) do
			for _, t in ipairs(f.fonts or {}) do
				if (t.calls.Show or 0) > (known[t] or 0) then
					return t
				end
			end
		end
	end
	local function at(font)
		local p = font and font.points[1]
		return p and (g(p[4]) .. "," .. g(p[5])) or "none"
	end
	local function spot(W)
		local x, y = W.ns.MoverSpot("FlatUICombatSelf", "CENTER")
		return g(x) .. "," .. g(y)
	end
	local function saved(W)
		local e = entry(W, "FlatUICombatSelf")
		return e ~= nil and e.point == "CENTER" and e.x == 0 and near(e.y, -30) and e.kind == "hud"
	end
	local W = open({}, { worldText = true, combatText = true })
	check("centre: combat text you: before it is centred its spot is left of the middle", spot(W) == "790,510", spot(W))
	click(button(W, "Combat text: you"))
	W.run(2, 0.5)
	check("centre: combat text you: the button saves point CENTER with x 0 and the same height", saved(W), tostring(entry(W, "FlatUICombatSelf") and entry(W, "FlatUICombatSelf").x))
	check("centre: combat text you: its spot is half the screen width", spot(W) == "960,510", spot(W))
	check("centre: combat text you: and the next number is drawn there", at(hit(W)) == "960,510")
	W.rightClick("Combat text: you")
	W.run(2, 0.5)
	check("centre: combat text you: a right-click puts it back", entry(W, "FlatUICombatSelf") == nil and spot(W) == "790,510", spot(W))
	click(box(W, "Combat text: you"))
	W.press("Centre ticked")
	W.run(2, 0.5)
	check("centre: combat text you: Centre ticked saves the same spot", saved(W) and spot(W) == "960,510" and at(hit(W)) == "960,510", spot(W))
	check("centre: combat text you: no violation", allClean(W), problems(W))
end

-- The rule for a frame whose width is odd: it is saved with x 0. This records the rule and says nothing of the screen.
do
