	check("own buffs: Under the swing timer without a swing timer hangs under the bars", OB.mod(N).holder.points[1][2] == N.env.PersonalResourceDisplayFrame.PowerBar and OB.mod(N).holder.points[1][5] == -4 and N.ns.OwnBuffsHolder("below") == OB.mod(N).holder)
	local R = OB.up({ noResource = true })
	check("own buffs: with no personal resource display it hangs above the player frame, nothing hangs from it, and the status says so", OB.mod(R).holder.points[1][2] == R.env.PlayerFrame and OB.mod(R).holder.points[1][5] == 70 and R.ns.OwnBuffsHolder("above") == nil
		and has(R.status(), "Your buffs: the personal resource display has no position, so the row is above the player frame."))
	-- Off: the holder is hidden, the groups are off, and no other row hangs from it.
