do
	local W = newWorld()
	local ns = W.ns
	local A = ns.ABILITIES
	local by = {}
	for index, a in ipairs(A) do
		by[a.key] = { a = a, index = index }
	end
	local function whole(v)
		return type(v) == "number" and v == math.floor(v) and v > 0
	end
	local function applies(a)
		if a.class ~= "ALL" then
			return { a.class }
		end
		return a.classes or { "ALL" }
	end
	check("cdata: the file loads and has the list, the nine kinds and the three maps", type(A) == "table" and #A == 176 and #ns.COOLDOWN_KINDS == 9 and type(ns.ABILITY_BY_CAST) == "table"
		and type(ns.ABILITY_BY_BUFF) == "table" and type(ns.ABILITIES_BY_CLASS) == "table" and loadfile(ADDON_DIR .. "/CooldownData.lua") ~= nil, #A)
	local wrong = {}
	for _, a in ipairs(A) do
		for _, list in ipairs({ a.casts, a.buffs, a.triggers or {} }) do
			for _, id in ipairs(list) do
				if not whole(id) then
					wrong[#wrong + 1] = a.key .. " " .. tostring(id)
				end
			end
		end
		for _, field in ipairs({ "cd", "secs", "cat" }) do
			if type(a[field]) ~= "number" or a[field] < 0 or a[field] ~= math.floor(a[field] * 10) / 10 then
				wrong[#wrong + 1] = a.key .. " " .. field
			end
		end
		if #a.casts == 0 then
			wrong[#wrong + 1] = a.key .. " has no cast ID"
		end
	end
	for class, ids in pairs(ns.ABILITY_BY_CAST) do
		for id, index in pairs(ids) do
			if not whole(id) or not A[index] then
