			end
		end
	end
	check("cdata: every ID is a whole number and every ability has a cast ID", #wrong == 0, table.concat(wrong, "; "):sub(1, 300))
	local kinds, kindsUsed = true, {}
	for _, a in ipairs(A) do
		kinds = kinds and a.kind >= 1 and a.kind <= 9 and a.kind == math.floor(a.kind)
		kindsUsed[a.kind] = true
	end
	check("cdata: kinds are 1 to 9, and all nine are used", kinds and #kindsUsed == 9)
	local clash, mapped = {}, true
	for index, a in ipairs(A) do
		for _, class in ipairs(applies(a)) do
			for _, id in ipairs(a.casts) do
				local found = ns.ABILITY_BY_CAST[class] and ns.ABILITY_BY_CAST[class][id]
				if found ~= index then
					clash[#clash + 1] = class .. " " .. id .. " " .. a.key
				end
			end
			for _, id in ipairs(a.buffs) do
				local list = ns.ABILITY_BY_BUFF[class] and ns.ABILITY_BY_BUFF[class][id]
