do
	local up = TOC.df.iconWorld
	local function probes(W)
		local ns = W.ns
		return { ns.AurasReadable(), ns.CastLevel(5), ns.CanSeeCasts("target"), ns.MessagesOpen() }
	end
	local function none(list)
		for i = 1, 4 do
			if list[i] ~= nil then
				return false
			end
		end
		return true
	end
	local W = up()
	local plain = probes(W)
	check("cdtrack: the probes answer what the game says when it answers plainly", plain[1] == true and plain[2] == 2 and plain[3] == true and plain[4] == true, tostring(plain[1]) .. tostring(plain[2]) .. tostring(plain[3]) .. tostring(plain[4]))
	W.au.hidden, W.au.castsHidden, W.au.chat.lockdown, W.au.castSecrecy[5] = true, true, true, 0
	local hidden = probes(W)
	check("cdtrack: and what it says when it hides: buffs not readable, casts not seen, messages blocked, the level of a spell", hidden[1] == false and hidden[2] == 0 and hidden[3] == false and hidden[4] == false)
	check("cdtrack: Open is plainly false only while buffs are readable, and it asks every time", W.ns.Tracking.Open() == false and (function() W.au.hidden = false return W.ns.Tracking.Open() end)() == true)
	local missing = up({ without = { C_Secrets = true, C_ChatInfo = true } })
	check("cdtrack: with C_Secrets and C_ChatInfo missing every probe gives nil and nothing raises", none(probes(missing)) and TOC.df.ok(missing) and missing.ns.Tracking.Open() == true, TOC.df.why(missing))
	for _, how in ipairs({ "error", "secret", "string" }) do
		local R = up()
		for _, name in ipairs({ "ShouldAurasBeSecret", "GetSpellCastSecrecy", "ShouldUnitSpellCastingBeSecret", "InChatMessagingLockdown" }) do
			R.au.fault[name] = how
		end
		check("cdtrack: with the calls " .. (how == "error" and "raising" or (how == "secret" and "answering a withheld value" or "answering text")) .. " every probe gives nil and nothing raises", none(probes(R)) and TOC.df.ok(R), TOC.df.why(R))
	end
	check("cdtrack: Open is false when the call raises or answers a withheld value, and does not guess", (function()
		local R = up()
		R.au.fault.ShouldAurasBeSecret = "error"
		local a = R.ns.Tracking.Open()
		R.au.fault.ShouldAurasBeSecret = "secret"
		return a == false and R.ns.Tracking.Open() == false
	end)())
	check("cdtrack: without the call, Open is true out of combat and false in combat", (function()
		local R = up({ without = { ["C_Secrets.ShouldAurasBeSecret"] = true } })
		local out = R.ns.Tracking.Open()
		R.combat = true
		return out == true and R.ns.Tracking.Open() == false
	end)())

	-- A buff of a unit.
	local B = up()
	B.giveBuff(17, { remaining = 30, duration = 30 })
	local aura, why = B.ns.UnitBuff("player", 17)
	local absent, whyAbsent = B.ns.UnitBuff("player", 18)
	check("cdtrack: UnitBuff gives the table of a buff that is there, and nil with none for one that is not", aura ~= nil and aura.spellId == 17 and absent == nil and whyAbsent == "none" and why == nil)
	B.au.secretFields = true
	local fields, whyFields = B.ns.UnitBuff("player", 17)
	B.au.secretFields = false
	B.au.fault.GetUnitAuraBySpellID = "secret"
	local hiddenAura, whyHidden = B.ns.UnitBuff("player", 17)
	B.au.fault.GetUnitAuraBySpellID = "error"
	local raising, whyRaising = B.ns.UnitBuff("player", 17)
	B.au.fault.GetUnitAuraBySpellID = nil
	check("cdtrack: and nil with hidden for withheld fields or a withheld answer, nil with refused for a getter that raises, and none of it raises", fields == nil and whyFields == "hidden" and hiddenAura == nil and whyHidden == "hidden" and raising == nil and whyRaising == "refused" and TOC.df.ok(B))
	local clientless = up({ without = { C_UnitAuras = true } })
	local nothing, whyNothing = clientless.ns.UnitBuff("player", 17)
	check("cdtrack: a client without C_UnitAuras, and arguments that are not a unit and an ID, give nil with refused", nothing == nil and whyNothing == "refused" and select(2, B.ns.UnitBuff(nil, 17)) == "refused" and select(2, B.ns.UnitBuff("player", "x")) == "refused"
		and select(2, B.ns.UnitBuff(SECRET, 17)) == "refused")
	B.au.unitAuras.target = { [11958] = { name = "Ice Block", duration = 10, expires = 10, source = "target" } }
	B.au.unit.target = { guid = "Player-1-0002", player = true, class = "MAGE", race = "Human", name = "Other", attack = true }
	local other = B.ns.UnitBuff("target", 11958)
	check("cdtrack: and the buff of another unit is read the same way", other ~= nil and other.sourceUnit == "target")

end
