-- Defensives on you: the module, its container, its places, the reading path, the test and the check.
do
	local DF = TOC.df
	local asked, late = DF.asked, DF.late

	-- A world with trackers that has not asked for the module has it switched off in the client: nothing is made.
	local base = DF.up({ trackers = true })
	local off = DF.up({ saved = { options = { ["defensives.enabled"] = false } } })
	check("defensives: with the page off no frame is made and no call is made to the game", #off.addonFrames == #base.addonFrames and #off.ac.containers == 0 and asked(off) == asked(base) and DF.mod(off).holder == nil
		and has(off.status(), "Defensives on you: off") and DF.ok(off), DF.why(off))
	check("defensives: and its words check and test still work", has(off.slash("check"), "Place: open world.") and has(off.slash("test"), "three sample icons for 8 seconds.") and #off.ac.containers == 0 and DF.ok(off), off.slash("test"))
	local plain = newWorld()
	plain.login()
	plain.flush()
	check("defensives: a client with no information about buffs makes nothing and the module goes on", #plain.violations == 0 and #plain.errors == 0 and has(plain.status(), "Defensives on you: on") and plain.slash("test"):match("^[^\n]*") == "Defensives on you: the game gives no buff information." and plain.ns.DefensivesModule.holder == nil, plain.status())

	-- On: the container, its two groups and the parts of every button.
	local W = DF.up()
	local D = DF.mod(W)
	local c = W.ac.containers[1]
	local listed, external = DF.group(W, "listed"), DF.group(W, "external")
	local count = 0
	for _ in pairs(listed.include) do
		count = count + 1
	end
	check("defensives: on, one container is made for the player on the holder, with the template of the game, no name and no edit mode preview", #W.ac.containers == 1 and c.ac.unit == "player" and c.ac.template == "CustomAuraContainerTemplate"
		and c.ac.name == nil and c.ac.preview == false and c.parent == D.holder and c.points[1][1] == "BOTTOMLEFT" and c.points[1][2] == D.holder and c.points[1][3] == "BOTTOMLEFT" and DF.ok(W), DF.why(W))
	check("defensives: it has two groups, each with its own filter string, and the 56 listed buff IDs are the includeSpellIDs of one and the excludeSpellIDs of the other", listed and external and listed.filter == "HELPFUL|!PLAYER" and external.filter == "HELPFUL|EXTERNAL_DEFENSIVE"
		and count == 56 and listed.included == true and next(listed.exclude) == nil and external.included == false and next(external.exclude) ~= nil and external.exclude[17] == true and listed.include[17] == true and listed.include[1044] == true, count)
	check("defensives: the groups show six and four icons at most, three units apart, and make ten buttons each at once", listed.max == 6 and external.max == 4 and listed.layout.elementSpacing == 3 and listed.layout.elementWidth == 32 and #listed.slots == 10 and #external.slots == 10 and c.ac.adds == 3)
	local parts = {}
	for _, group in ipairs({ listed, external, DF.group(W, "own") }) do
		for _, slot in ipairs(group.slots) do
			local b = slot.braw
			parts[#parts + 1] = (b.icon and b.icon.kind == "Texture" and "i" or "-") .. (b.durationCooldown and b.durationCooldown.objectType == "Cooldown" and "c" or "-") .. (b.applicationCount and "n" or "-") .. (b.durationText and "t" or "-")
				.. (b.casterName and "w" or "-") .. (b.mouse == false and "m" or "-") .. (b.hideTooltip == true and "h" or "-")
		end
	end
	local same = true
	for _, text in ipairs(parts) do
		same = same and text == "icntwmh"
	end
	check("defensives: each button gets an icon, a cooldown, a count, a time left, a caster's name, no mouse and no tooltip in a fight, all of them descendants of the button", #parts == 30 and same, parts[1])
	local edges = 0
	local fine = true
	for _, entry in ipairs(D.list) do
		edges = edges + #entry.edges
		fine = fine and #entry.edges == 4 and entry.top ~= nil
		for _, edge in ipairs(entry.edges) do
			fine = fine and W.rawOf[edge].kind == "Texture" and W.rawOf[edge].owner == W.rawOf[entry.top] and W.rawOf[entry.top].parent == entry.button
		end
	end
	check("defensives: the picture of each icon is cropped by 0.08 on every side, and the border is the colour of the general border", (function()
		local texture = listed.slots[1].braw.icon.texCoord
		local edge = W.rawOf[D.list[1].edges[1]].color
		local r, g, b = W.ns.Colour("general.border")
		return texture and near(texture[1], 0.08) and near(texture[2], 0.92) and near(texture[3], 0.08) and near(texture[4], 0.92) and edge and near(edge[1], r) and near(edge[2], g) and near(edge[3], b) and edge[4] == 1
	end)())
	check("defensives: and four edges for a thin border, on a frame that is a child of the button", #D.list == 30 and edges == 120 and fine)
	check("defensives: the sweep has no edge, no flash of its own and a dark swipe, and the numbers are the game's time text, not the sweep's", (function()
		local sweep = listed.slots[1].braw.durationCooldown.cd
		return sweep.drawEdge == false and sweep.drawBling == false and sweep.swipeColour[4] == 0.7 and sweep.hideNumbers == true
	end)())
	local why = {}
	for name in pairs(D.refused) do
		why[#why + 1] = name
	end
	check("defensives: everything was made inside initializeFrame, before the game closed the button, and no part was refused", late(W) == 0 and next(D.refused) == nil and not has(W.status(), "refused"), table.concat(why, ",") .. " " .. tostring(D.failure) .. " " .. late(W))

	-- Buffs on the player.
	DF.shield(W)
	local first = listed.slots[1].braw
	check("defensives: a shield another player cast on you is drawn by the game in the first button of the list, with its picture, its time left and the caster's name", first.shown == true and first.icon.file ~= 134400 and first.durationText.font.text == "30s"
		and first.casterName.font.text == "Healer" and first.casterName.font.shown == true and listed.slots[2].braw.shown == false and external.slots[1].braw.shown == false, tostring(first.shown))
	W.giveBuff(17, { name = "Power Word: Shield", remaining = 30, duration = 30, fromPlayer = true })
	check("defensives: a shield you cast yourself is not drawn", listed.slots[1].braw.shown == false)
	W.takeBuff(17)
	W.giveBuff(974, { name = "Earth Shield", remaining = 600, duration = 600, caster = "Shaman", source = "party2", applications = 6 })
	W.giveBuff(5555, { name = "Pain Suppression", remaining = 8, duration = 8, external = true, caster = "Priest" })
	check("defensives: a listed buff shows with its charges, and an external defensive the lists do not name shows in the second group", listed.slots[1].braw.shown and listed.slots[1].braw.applicationCount.font.text == "6" and external.slots[1].braw.shown and external.slots[1].braw.casterName.font.text == "Priest"
		and listed.slots[2].braw.shown == false)
	W.giveBuff(17, { name = "Power Word: Shield", remaining = 30, duration = 30, external = true, source = "party1", caster = "Healer" })
	check("defensives: a listed buff that is also an external defensive is in the first group only", listed.slots[1].braw.shown and listed.slots[2].braw.shown and external.slots[2].braw.shown == false and external.slots[1].braw.shown)
	for _, id in ipairs({ 17, 974, 5555 }) do
		W.takeBuff(id)
	end
	check("defensives: and the buttons are empty again when the buffs are gone", listed.slots[1].braw.shown == false and external.slots[1].braw.shown == false and DF.ok(W))

	local K0 = DF.up({ saved = { options = { ["defensives.caster"] = false } } })
	local K0l = DF.group(K0, "listed")
	local hiddenNames = true
	for _, entry in ipairs(DF.mod(K0).list) do
		hiddenNames = hiddenNames and entry.name ~= nil and K0.rawOf[entry.name].shown == false
	end
	check("defensives: with Caster's name off at the start no name is registered on any button and the font strings are hidden, and turning it on later registers it everywhere", K0l.slots[1].braw.casterName == nil and DF.group(K0, "external").slots[10].braw.casterName == nil
		and hiddenNames and late(K0) == 0 and (function()
		K0.change("defensives.caster", true)
		return K0l.slots[1].braw.casterName ~= nil and DF.group(K0, "external").slots[10].braw.casterName ~= nil and DF.ok(K0)
	end)())

	-- Hidden buffs: the buttons are closed.
	local before, closed = #W.violations, TOC.closed or 0
	local calls = late(W)
	W.hideAuras()
	W.change("defensives.caster", false)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.flush()
	check("defensives: after W.hideAuras() a change of a setting and the events that ask for a look make no call on a button and record no violation, and the container is still told what it may be", late(W) == calls and #W.violations == before and (TOC.closed or 0) == closed
		and listed.slots[1].braw.casterName ~= nil and D.pending.caster == true, DF.why(W))
	W.showAuras()
	W.restriction("Combat", "Inactive")
	check("defensives: the change of Caster's name waits for the game to say the restrictions are over, and then the name is cleared on every button and its font string is hidden", listed.slots[1].braw.casterName == nil and external.slots[10].braw.casterName == nil
		and listed.slots[1].braw.casterName == nil and D.pending.caster == nil and W.rawOf[D.list[1].name].shown == false and late(W) > calls and DF.ok(W), tostring(D.pending.caster))
	W.change("defensives.caster", true)
	check("defensives: and Caster's name on again registers it on every button", listed.slots[1].braw.casterName ~= nil and external.slots[10].braw.casterName ~= nil and listed.slots[1].braw.casterName.classColours == true and DF.ok(W))

end
