	samples[1].cooldown.scripts.OnCooldownDone(samples[1].cooldown)
	S.advance(2)
	samples[2].cooldown.scripts.OnCooldownDone(samples[2].cooldown)
	S.advance(3.9)
	check("defensives: the samples are still there just before the 8 seconds are over", samples[1].frame.shown and samples[3].frame.shown)
	S.out = {}
	samples[3].cooldown.scripts.OnCooldownDone(samples[3].cooldown)
	S.advance(0.2)
	check("defensives: and hidden after them, and the test says on how many icons the sweep ended and whether the sound played", not samples[1].frame.shown and not samples[3].frame.shown and S.out[#S.out] == "Test: the sweep ended on 3 of 3 icons. Sound: played." and #S.au.played == 3, table.concat(S.out, "|"))
	local C = DF.up()
	C.combat = true
	local refused = C.slash("test")
	check("defensives: /flatui test in combat shows nothing and says so in one line", refused:match("^[^\n]*") == "Defensives on you: the test shows out of combat only." and DF.mod(C).sample == nil and DF.ok(C), refused)
	local Q = DF.up()
	Q.au.fault.PlaySound = "false"
	Q.slash("test")
	for _, s in ipairs(DF.mod(Q).sample) do
		s.cooldown.scripts.OnCooldownDone(s.cooldown)
	end
	Q.out = {}
	Q.advance(8.1)
	check("defensives: a test where the game plays no sound says so, and the module notes it once", Q.out[#Q.out] == "Test: the sweep ended on 3 of 3 icons. Sound: the game played no sound." and count(Q.status(), "the game plays no sound") == 1, table.concat(Q.out, "|"))
	local Z = DF.up({ without = { PlaySound = true } })
	Z.slash("test")
	Z.advance(8.1)
	check("defensives: and a test without any sweep ending says it was not tried", Z.out[#Z.out] == "Test: the sweep ended on 0 of 3 icons. Sound: not tried." and DF.ok(Z), table.concat(Z.out, "|"))

end
do
	local DF = TOC.df
	local late = DF.late
	-- /flatui check.
	local K = DF.up()
	check("defensives: /flatui check last before any check says there is none", K.slash("check last") == "No check yet. Type /flatui check.")
	local lines = K.slash("check")
	K.advance(2)
	local last = K.slash("check last")
	check("defensives: /flatui check prints the lines, and /flatui check last the kept lines, with the answer to the test message that came after", has(lines, "Place: open world.") and has(lines, "Defensives on you: the game's own icon row.") and has(last, "Test message came back: yes, sender name matches your name.")
		and has(last, "Place: open world.") and count(K.slash("check last"), "Test message came back") == 1, lines)
	check("defensives: and the line about a listed buff on you reads what the game shows right now", (function()
		DF.shield(K)
		local seen = K.slash("check")
		K.hideAuras()
		local hidden = K.slash("check")
		return has(seen, "A listed buff on you: seen readable.") and has(hidden, "A listed buff on you: hidden by the game right now.")
	end)())
	check("defensives: the words of the module read the help lines, and the three lines are in the general help after the trackers", (function()
		local help = K.slash("help me")
		return has(help, "/flatui check - what the game shows and hides where you stand") and has(help, "/flatui check last - the lines of the last check") and has(help, "/flatui test - three sample icons for Defensives on you")
	end)())
	check("defensives: the module is in the order of the modules after the trackers, with its page, and its TOC files load after TrackerSlots.lua and before Windows.lua in their order", (function()
		local at = {}
		for i, file in ipairs(FILES) do
			at[file] = i
		end
		local order = table.concat(K.ns.MODULE_ORDER, ",")
		return order:find("trackers,defensives,partycd,enemycd,windows", 1, true) ~= nil and at["CooldownData.lua"] == at["TrackerSlots.lua"] + 1 and at["IconRow.lua"] == at["CooldownData.lua"] + 1 and at["Tracking.lua"] == at["IconRow.lua"] + 1
			and at["Defensives.lua"] == at["Tracking.lua"] + 1 and at["Windows.lua"] > at["Defensives.lua"] and K.setting("defensives.place") ~= nil
	end)())
	check("defensives: the page has the switch, Place with its four choices, and Caster's name, all on by default but the choice, which starts above the player frame", K.ns.Get("defensives.enabled") == true and K.ns.Get("defensives.place") == "player" and K.ns.Get("defensives.caster") == true)
	check("defensives: the main chunks of the four new files compile, so each has at most 200 locals and 60 upvalues in each function", loadfile(ADDON_DIR .. "/Defensives.lua") ~= nil and loadfile(ADDON_DIR .. "/Tracking.lua") ~= nil and loadfile(ADDON_DIR .. "/IconRow.lua") ~= nil and loadfile(ADDON_DIR .. "/CooldownData.lua") ~= nil)
	check("defensives: no call on a closed button was recorded in any world of this section", (TOC.closed or 0) == 0, tostring(TOC.closed))
end
-- >>> module (end)
-- >>> deflists (begin)
-- Defensives on you: Your own defensives and the lists of buffs.
do
	local DF = TOC.df
	local late = DF.late
	local V = {}
	local function mapSize(map)
		local n = 0
		for _ in pairs(map) do
			n = n + 1
		end
		return n
	end
	local function mage()
		return DF.up({ setup = function(X)
			X.au.unit.player.class = "MAGE"
			X.addSpell(11426, { name = "Ice Barrier", subtext = "Rank 1" })
			for _, id in ipairs({ 17, 592, 600 }) do
				X.addSpell(id, { name = "Power Word: Shield" })
			end
			X.addSpell(555001, { name = "Hand of Test" })
			X.addSpell(555002, { name = "Ward of Test", subtext = "Rank 2" })
			X.addSpell(555003, { name = "Ward of Test", subtext = "Rank 1" })
		end })
	end

	-- The page.
	do
		local P = DF.up()
		local rows = {}
		for _, page in ipairs(P.ns.PAGES) do
			if page.key == "defensives" then
				for _, item in ipairs(page) do
					rows[item.key or item.section] = item
				end
			end
		end
		local function row(key, kind, default, label)
			local item = rows[key]
			return item ~= nil and item.kind == kind and item.default == default and item.label == label
		end
		check("deflists: page: Your own defensives is off, with its tip", row("own", "bool", false, "Your own defensives") and rows.own.tip == "Shield Wall, Ice Barrier and the like that you cast on yourself.")
		check("deflists: page: Add a spell and Remove a spell are lists that pick from the lists of Defensives.lua", row("add", "list", 0, "Add a spell") and row("remove", "list", 0, "Remove a spell")
			and rows.add.items == "DefensiveCandidates" and rows.add.pick == "DefensiveAdd" and rows.remove.items == "DefensiveListed" and rows.remove.pick == "DefensiveRemove"
			and rows.add.tip == "For a buff that is not listed, type /flatui defensives add and its spell ID." and rows.Spells ~= nil)
	end

	-- The third group.
	do
		local W = mage()
		V[#V + 1] = W
		local c = W.ac.containers[1]
		local listed, external, own = DF.group(W, "listed"), DF.group(W, "external"), DF.group(W, "own")
		check("deflists: the container has a third group, HELPFUL|PLAYER, four icons at most, ten buttons made at once, off while Your own defensives is off", own ~= nil and own.filter == "HELPFUL|PLAYER" and own.max == 4
			and #own.slots == 10 and own.enabled == false and c.ac.adds == 3 and DF.ok(W), DF.why(W))
		check("deflists: its include map holds the buff IDs of the self-cast defensives and immunities of the class, and not those of another class", own.included == true and own.include[11426] == true and own.include[11958] == true
			and own.include[1463] == true and own.include[17] == nil and own.include[8178] == nil and own.include[20594] == true and next(own.exclude) == nil)
		check("deflists: the first two groups keep their filter strings, and the third adds ten buttons to each of theirs", listed.filter == "HELPFUL|!PLAYER" and external.filter == "HELPFUL|EXTERNAL_DEFENSIVE" and #listed.slots == 10 and #external.slots == 10 and #DF.mod(W).list == 30)
		W.giveBuff(11426, { name = "Ice Barrier", remaining = 60, duration = 60, fromPlayer = true, source = "player" })
		check("deflists: with Your own defensives off a defensive you cast on yourself shows in no group", own.slots[1].braw.shown == false and listed.slots[1].braw.shown == false and external.slots[1].braw.shown == false)
		local filterBefore = listed.filter
		W.change("defensives.own", true)
		check("deflists: Your own defensives on turns the third group on, and it draws the buff with its time left", own.enabled == true and own.slots[1].braw.shown == true and own.slots[1].braw.durationText.font.text == "60s"
			and own.slots[2].braw.shown == false and listed.filter == filterBefore and listed.enabled == true and external.enabled == true and DF.ok(W), DF.why(W))
		W.giveBuff(17, { name = "Power Word: Shield", remaining = 30, duration = 30, fromPlayer = true, source = "player" })
		check("deflists: and a listed buff you cast yourself is still not in the other two groups", listed.slots[1].braw.shown == false and own.slots[2].braw.shown == false)
		W.takeBuff(17)
		W.takeBuff(11426)
		W.change("defensives.own", false)
		check("deflists: Your own defensives off turns it off again, and the filter strings are the same", own.enabled == false and listed.filter == filterBefore and own.filter == "HELPFUL|PLAYER" and DF.ok(W))
		W.change("defensives.own", true)
		W.change("defensives.place", "Off")
		check("deflists: Place Off turns all three groups off, and Place back on leaves the third on", own.enabled == false and listed.enabled == false and external.enabled == false and (function()
			W.change("defensives.place", "Above the player frame")
			return own.enabled == true and listed.enabled == true
		end)())
		check("deflists: with Your own defensives on at the start the third group is on after the login", (function()
			local S = DF.up({ saved = { options = { ["defensives.own"] = true } } })
			return DF.group(S, "own").enabled == true and DF.group(S, "own").include[8178] == true and #S.ac.containers == 1 and DF.ok(S)
		end)())
	end

	-- Adding.
	do
		local A = mage()
		V[#V + 1] = A
		local alist, aext = DF.group(A, "listed"), DF.group(A, "external")
		local ok, message = A.ns.DefensiveAdd(555001)
		check("deflists: add: an added ID is told, and is in the include map of the first group and out of the exclude map of the second", ok == true and message == "Added Hand of Test." and alist.include[555001] == true and aext.exclude[555001] == true
			and alist.include[17] == true and mapSize(alist.include) == 57, message .. " " .. mapSize(alist.include))
		check("deflists: and it is kept for the account as a map by spell ID", A.env.FlatUIDB.abilities.defensives.added[555001] == true and next(A.env.FlatUIDB.abilities.defensives.removed) == nil)
		A.giveBuff(555001, { name = "Hand of Test", remaining = 10, duration = 10, caster = "Healer", source = "party1" })
		check("deflists: and a buff added shows in the first group when another player casts it on you", alist.slots[1].braw.shown == true and alist.slots[1].braw.casterName.font.text == "Healer" and aext.slots[1].braw.shown == false)
		A.takeBuff(555001)
		local again, sameMessage = A.ns.DefensiveAdd(555001)
		check("deflists: add: the same ID again says it is listed, and one the game has no name for says no spell", again == false and sameMessage == "Hand of Test is already listed." and select(2, A.ns.DefensiveAdd(999999)) == 'No spell found for "999999".'
			and select(2, A.ns.DefensiveAdd("x")) == 'No spell found for "x".')
		local R = DF.up({ saved = A.env.FlatUIDB, setup = function(X)
			X.au.unit.player.class = "MAGE"
			X.addSpell(555001, { name = "Hand of Test" })
		end })
		check("deflists: an added ID survives a reload: it is in the include map after the login", DF.group(R, "listed").include[555001] == true and DF.group(R, "external").exclude[555001] == true and DF.ok(R), DF.why(R))
	end

	-- In a fight the saved change is made at once and the container hears of it after combat.
	do
		local F = mage()
		local flist = DF.group(F, "listed")
		F.beginFight()
		local fOk = F.ns.DefensiveAdd(555001)
		local during = flist.include[555001]
		F.endFight()
		F.flush()
		check("deflists: in combat an added ID is saved at once and is in the include map after combat ends", fOk == true and during == nil and F.env.FlatUIDB.abilities.defensives.added[555001] == true and flist.include[555001] == true and DF.ok(F), DF.why(F))
	end

	-- Removing.
	do
		local B = mage()
		V[#V + 1] = B
		local blist, bext = DF.group(B, "listed"), DF.group(B, "external")
		local rOk, rMessage = B.ns.DefensiveRemove(11958)
		check("deflists: remove: an ID that is not listed says so", rOk == false and rMessage == "Spell 11958 is not listed.", rMessage)
		local gone, goneMessage = B.ns.DefensiveRemove(17)
		check("deflists: remove: a removed ID is out of the include map and stays in the exclude map of the second group, and told", gone == true and goneMessage == "Removed Power Word: Shield." and blist.include[17] == nil and bext.exclude[17] == true and blist.include[592] == true
			and B.env.FlatUIDB.abilities.defensives.removed[17] == true and next(B.env.FlatUIDB.abilities.defensives.added) == nil, goneMessage)
		B.giveBuff(17, { name = "Power Word: Shield", remaining = 30, duration = 30, caster = "Healer", source = "party1" })
		check("deflists: and a removed buff no longer shows in the first group", blist.slots[1].braw.shown == false)
		B.takeBuff(17)
		B.giveBuff(17, { name = "Power Word: Shield", remaining = 30, duration = 30, caster = "Healer", external = true, source = "party1" })
		check("deflists: and a removed buff the game flags as an external defensive shows in neither group", bext.slots[1].braw.shown == false)
		B.takeBuff(17)
		local RB = DF.up({ saved = B.env.FlatUIDB, setup = function(X)
			X.au.unit.player.class = "MAGE"
		end })
		check("deflists: a removed ID stays out after a reload", DF.group(RB, "listed").include[17] == nil and DF.group(RB, "listed").include[592] == true and DF.group(RB, "external").exclude[17] == true)
		local back, backMessage = B.ns.DefensiveAdd(17)
		check("deflists: adding a removed ID back drops its removal, and does not count against the added ones", back == true and backMessage == "Added Power Word: Shield." and blist.include[17] == true and next(B.env.FlatUIDB.abilities.defensives.removed) == nil
			and next(B.env.FlatUIDB.abilities.defensives.added) == nil)
		B.ns.DefensiveAdd(555001)
		B.ns.DefensiveRemove(555001)
		check("deflists: removing an added ID forgets it", blist.include[555001] == nil and next(B.env.FlatUIDB.abilities.defensives.added) == nil and next(B.env.FlatUIDB.abilities.defensives.removed) == nil)
	end

	-- The most.
	do
		local M = mage()
		local most = true
		for index = 1, 41 do
			M.addSpell(600000 + index, { name = "Test " .. index })
			local done = M.ns.DefensiveAdd(600000 + index)
			most = most and (done == (index <= 40))
		end
		check("deflists: 40 added spells are taken", most)
		check("deflists: and the 41st is told that 40 is the most", select(2, M.ns.DefensiveAdd(600041)) == "40 added spells is the most.", select(2, M.ns.DefensiveAdd(600041)))
	end

	-- The lists of the page.
	do
		local C = mage()
		V[#V + 1] = C
		local rows = C.ns.DefensiveCandidates()
		local names, ids = {}, {}
		for _, line in ipairs(rows) do
			names[#names + 1] = line[2]
			ids[line[1]] = true
		end
		check("deflists: Add a spell offers the buffs of the game's list that are not on the list, by name, and not those on it", ids[11426] == nil and ids[426490] == true and ids[17] == nil and ids[974] == nil and #rows > 20)
		local sorted = true
		for index = 2, #rows do
			sorted = sorted and rows[index - 1][2]:lower() <= rows[index][2]:lower()
		end
		check("deflists: and they are in the order of their names", sorted)
		C.addSpell(20707, { name = "Soulstone Resurrection", subtext = "Rank 1" })
		C.addSpell(20762, { name = "Soulstone Resurrection", subtext = "Rank 2" })
		local named = {}
		for _, line in ipairs(C.ns.DefensiveCandidates()) do
			if line[1] == 20707 or line[1] == 20762 then
				named[#named + 1] = line[2]
			end
		end
		check("deflists: two ranks with one name get the rank beside it", #named == 2 and named[1]:find("Soulstone Resurrection (", 1, true) == 1 and named[2]:find("Soulstone Resurrection (", 1, true) == 1 and named[1] ~= named[2], table.concat(named, "|"))
		local listedRows = C.ns.DefensiveListed()
		local has17 = false
		for _, line in ipairs(listedRows) do
			has17 = has17 or line[1] == 17
		end
		check("deflists: Remove a spell lists what is on the list now, with what was added", has17 and #listedRows == 56 and (function()
			C.addSpell(426490, { name = "Rallying Cry" })
			C.ns.DefensiveAdd(426490)
			return #C.ns.DefensiveListed() == 57 and #C.ns.DefensiveCandidates() == #rows - 1
		end)())
	end

	-- The words.
	do
		local S = mage()
		V[#V + 1] = S
		S.addSpell(555004, { name = "Blessing of Test" })
		local slist = DF.group(S, "listed")
		check("deflists: /flatui defensives add takes a spell ID", S.slash("defensives add 555001") == "Added Hand of Test." and slist.include[555001] == true, S.slash("defensives add 555001"))
		check("deflists: and a shift-clicked spell", S.slash("defensives add |cff71d5ff|Hspell:555004:0|h[Blessing of Test]|h|r") == "Added Blessing of Test." and slist.include[555004] == true)
		check("deflists: and a word that is not an ID says no spell found", S.slash("defensives add Blessing of Test") == 'No spell found for "Blessing of Test".')
		check("deflists: remove takes a spell ID, or a name in any capitals", S.slash("defensives remove 555001") == "Removed Hand of Test." and slist.include[555001] == nil and S.slash("defensives remove BLESSING of test") == "Removed Blessing of Test."
			and slist.include[555004] == nil)
		check("deflists: and a name on no line is no spell", S.slash("defensives remove Nothing here") == 'No spell found for "Nothing here".' and S.slash("defensives remove 555001") == "Hand of Test is not listed.")
		S.ns.DefensiveAdd(555001)
		local listOut = S.slash("defensives list")
		check("deflists: list prints each buff by name with its IDs, the added one among them, and an empty list says so", has(listOut, "Hand of Test (555001)") and has(listOut, "Power Word: Shield (17, 592, 600") and (function()
			local E = mage()
			for _, line in ipairs(E.ns.DefensiveListed()) do
				E.ns.DefensiveRemove(line[1])
			end
			return E.slash("defensives list") == "No buffs listed." and mapSize(DF.group(E, "listed").include) == 0
		end)(), listOut)
		check("deflists: a word with nothing after it or no word prints the three lines", S.slash("defensives") == "/flatui defensives add 10060 - the spell ID of a buff, or a shift-clicked spell\n/flatui defensives remove 17 - a spell ID or a name\n/flatui defensives list"
			and S.slash("defensives add") == S.slash("defensives"))
		check("deflists: the three lines of the words are in the general help after the lines of check and test", (function()
			local help = S.slash("help me")
			return has(help, "/flatui test - three sample icons for Defensives on you\n/flatui defensives add 10060 - the spell ID of a buff, or a shift-clicked spell\n/flatui defensives remove 17 - a spell ID or a name\n/flatui defensives list")
		end)())
	end

	-- The list of buffs the game hides.
	do
		local H = mage()
		local hlist = DF.group(H, "listed")
		local beforeViolations, closed, calls = #H.violations, TOC.closed or 0, late(H)
		H.hideAuras()
		local hOk = H.ns.DefensiveAdd(555001)
		H.ns.DefensiveRemove(17)
		H.flush()
		check("deflists: while the game hides buffs a list change is made on the container alone: no call on a button, no violation", hOk == true and hlist.include[555001] == true and hlist.include[17] == nil and late(H) == calls
			and #H.violations == beforeViolations and (TOC.closed or 0) == closed and DF.ok(H), DF.why(H))
		H.showAuras()
	end

	-- Saved lists that are damaged: only whole numbers set to true count.
	do
		local J = DF.up({ saved = { abilities = { defensives = { added = { [555001] = true, x = true, [-5] = true, [555002] = false, [1.5] = true }, removed = "junk" } } }, setup = function(X)
			X.au.unit.player.class = "MAGE"
		end })
		local jlist = DF.group(J, "listed")
		check("deflists: a damaged saved list keeps only the whole numbers set to true, and the module goes on", jlist.include[555001] == true and jlist.include[-5] == nil and jlist.include[555002] == nil and jlist.include[1.5] == nil and mapSize(jlist.include) == 57
			and type(J.env.FlatUIDB.abilities.defensives.removed) == "table" and J.env.FlatUIDB.abilities.defensives.added.x == nil and DF.ok(J), DF.why(J))
	end

	-- The page off.
	do
		local O = DF.up({ saved = { options = { ["defensives.enabled"] = false } } })
		local offOk = O.ns.DefensiveRemove(17)
		check("deflists: with the page off a remove still works on what is saved, and makes no frame", offOk == true and #O.ac.containers == 0 and O.env.FlatUIDB.abilities.defensives.removed[17] == true and DF.ok(O), DF.why(O))
	end

	-- The reading path.
	do
		local N = DF.up({ noContainer = true, setup = function(X)
			X.au.unit.player.class = "MAGE"
			X.addSpell(555001, { name = "Hand of Test" })
			X.au.unit.party1 = { guid = "Player-1-0003", player = true, class = "PRIEST", race = "Human", name = "Healer" }
		end })
		local Nd = DF.mod(N)
		V[#V + 1] = N
		N.giveBuff(555001, { name = "Hand of Test", remaining = 10, duration = 10, caster = "Healer", source = "party1" })
		N.auraChanged()
		N.advance(0.3)
		local shownBefore = Nd.icons[1] and Nd.icons[1].frame.shown
		N.ns.DefensiveAdd(555001)
		N.advance(0.3)
		check("deflists: without the container an added buff shows after the next read, which a change of the list asks for", shownBefore ~= true and Nd.icons[1] ~= nil and Nd.icons[1].frame.shown == true and DF.ok(N), DF.why(N))
		N.ns.DefensiveRemove(555001)
		N.advance(0.3)
		check("deflists: and a removed one is gone after it", Nd.icons[1].frame.shown == false)
		N.change("defensives.own", true)
		check("deflists: without the container Your own defensives says in one line that it is off here, and nothing when it is off", count(N.status(), "Your own defensives is off here, since the game made no icon row.") == 1
			and count(DF.up({ noContainer = true }).status(), "Your own defensives is off here") == 0)
	end


	check("deflists: no violation, no error and no call on a closed button in any world of this section", (function()
		local bad = 0
		for _, X in ipairs(V) do
			bad = bad + #X.violations + #X.errors
		end
		return bad == 0 and (TOC.closed or 0) == 0
	end)())
end
-- >>> deflists (end)
-- >>> defensives (end)
-- >>> bar looks (begin)
-- Bar looks: the eight switches of the Looks section of the Unit frames page. Every check sets its switches through W.change. The values are kept in one table: the main
-- function of this file has a limit on the locals alive at once.
do
	local LK = { BASE = "0.18,0.72,0.30", SOFT = "Interface\\AddOns\\FlatUI\\Media\\Soft.tga", SHADOW = "Interface\\AddOns\\FlatUI\\Media\\Shadow.tga", MADE = 8,
		KEYS = { "lookClassHealth", "lookLostColour", "lookMuted", "lookWhiteNames", "lookLightText", "lookNoPowerText", "lookSoftShade", "lookShadow" },
		LABELS = { "Health in class and reaction colour", "Dark health bar, colour shows what is lost", "Muted colours", "White names", "Smaller, lighter bar text",
			"No text on the power bar", "Soft shade on bars", "Shadow behind each frame" } }
	-- A world with the functions the game has for a unit that is a player or not: LK.who[unit] is { player, class, reaction, secret }.
	function LK.world(opts)
		local W = FH.ufWorld(opts)
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local U, env = W.uf, W.env
		U.who = { player = { player = true, class = "WARLOCK" }, target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } },
			focus = { player = true, class = "ROGUE" }, party1 = { player = true, class = "PRIEST" } }
		env.RAID_CLASS_COLORS = { WARLOCK = setmetatable({ r = 0.58, g = 0.51, b = 0.79, a = 1 }, COLOUR_MT), ROGUE = setmetatable({ r = 1, g = 0.96, b = 0.41, a = 1 }, COLOUR_MT),
			MAGE = setmetatable({ r = 0.25, g = 0.78, b = 0.92, a = 1 }, COLOUR_MT), PRIEST = setmetatable({ r = 1, g = 1, b = 1, a = 1 }, COLOUR_MT),
			WARRIOR = setmetatable({ r = 0.78, g = 0.61, b = 0.43, a = 1 }, COLOUR_MT) }
		env.UnitIsPlayer = function(unit) return U.who[unit] ~= nil and U.who[unit].player end
		env.UnitClass = function(unit)
			local who = U.who[unit]
			if who == nil then
				return "Warlock", "WARLOCK", 9
			elseif who.secret then
				return SECRET, SECRET, SECRET
			end
			return who.class:sub(1, 1) .. who.class:sub(2):lower(), who.class, 1
		end
		env.UnitSelectionColor = function(unit)
			local c = U.who[unit] and U.who[unit].reaction or { 1, 1, 0 }
			return c[1], c[2], c[3], 1
		end
		W.flush()
		return W
	end
	-- Turns the looks named by their keys on, and every other look off.
	function LK.set(W, ...)
		local on = {}
		for _, key in ipairs({ ... }) do
			on[key] = true
		end
		for _, key in ipairs(LK.KEYS) do
			W.change("unitframes." .. key, on[key] == true)
		end
	end
	function LK.rgb(c) return c and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) or "-" end
	-- The colour of the solid fill of a bar.
	function LK.fill(W, fill) return LK.rgb(W.rawOf[fill].color) end
	-- The colour of the background behind a bar, from the outline of its slot, with its opacity.
	function LK.back(W, slot)
		local o = W.look(slot)
		return o and o.backdrop and o.backdrop.color and LK.rgb(o.backdrop.color) .. "," .. string.format("%.2f", o.backdrop.color[4]) or "none"
	end
	function LK.update(W, frame) W.blizzard(function() W.env.UnitFrame_Update(frame) end) end
	-- The font string of the name row that shows a name.
	function LK.name(W, text)
		for _, font in ipairs(W.addonFonts) do
			if font.text == text then
				return font
			end
		end
	end
	function LK.col(font) return font and font.textColour and LK.rgb(font.textColour) or "none" end
	function LK.font(W, word) local f = W.rawOf[word].font return f[1] .. "|" .. string.format("%.2f", f[2]) .. "|" .. tostring(f[3]) end
	function LK.alpha(W, word) return W.rawOf[word].alpha or 1 end
	-- The textures of the addon that draw the shadow file.
	function LK.shadows(W)
		local list = {}
		for _, t in ipairs(W.addonTextures) do
			if t.file == LK.SHADOW then
				list[#list + 1] = t
			end
		end
		return list
	end
	function LK.count(text, needle)
		local n, from = 0, 1
		while true do
			local at = text:find(needle, from, true)
			if not at then
				return n
			end
			n, from = n + 1, at + 1
		end
	end
	-- Whether a shown texture of the addon has the colour, at the opacity of the name row.
	function LK.painted(W, r, g, b)
		for _, t in ipairs(W.addonTextures) do
			local c = t.color
			if t.shown and c and math.abs(c[1] - r) < 0.006 and math.abs(c[2] - g) < 0.006 and math.abs(c[3] - b) < 0.006 and math.abs((c[4] or 0) - 0.95) < 0.001 then
				return true
			end
		end
		return false
	end
	function LK.why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") end
	LK.W = LK.world()
	local W = LK.W
	local P, T, F, M = W.player, W.target, W.focus, W.members[1]
	local who = W.uf.who

	-- The page.
	LK.page = true
	for index, key in ipairs(LK.KEYS) do
		local control = W.control("unitframes." .. key)
		LK.page = LK.page and control ~= nil and control.data.setting:GetValue() == false and control.data.name == LK.LABELS[index]
	end
	check("bar looks: the Looks section has the eight switches with their labels, all off", LK.page)
	W.change("unitframes.flat", false)
	check("bar looks: the three looks that need flat bars are not usable with Flat bars off, the others are", W.enabled("unitframes.lookClassHealth") == false
		and W.enabled("unitframes.lookLostColour") == false and W.enabled("unitframes.lookSoftShade") == false and W.enabled("unitframes.lookMuted") == true
		and W.enabled("unitframes.lookShadow") == true)
	W.change("unitframes.flat", true)

	-- Every look off: the frames are as in 0.4.x.
	LK.off = { health = LK.fill(W, P.healthFill), power = LK.fill(W, P.powerFill), fontH = LK.font(W, P.healthWords[1]), fontP = LK.font(W, P.powerWords[1]),
		back = LK.back(W, P.health), name = LK.col(LK.name(W, "Dxml Bozo")), alpha = LK.alpha(W, P.powerWords[1]) }
	check("bar looks: with every look off the fills, the words, the name and the background are the usual ones, no frame has a shadow and the status has no Looks line",
		LK.off.health == LK.BASE and LK.off.power == "0.00,0.00,1.00" and LK.off.fontH == "Fonts\\ARIALN.TTF|12.00|OUTLINE" and LK.off.fontP == "Fonts\\ARIALN.TTF|10.20|OUTLINE"
		and LK.off.alpha == 1 and LK.off.name == "1.00,0.82,0.00" and #LK.shadows(W) == 0 and not has(W.status(), "Looks:") and #W.violations == 0 and #W.errors == 0,
		table.concat({ LK.off.health, LK.off.power, LK.off.fontH, LK.off.fontP, LK.off.name }, " ") .. LK.why(W))

	-- Health in class and reaction colour.
	LK.set(W, "lookClassHealth")
	LK.r = { player = LK.fill(W, P.healthFill), hostile = LK.fill(W, T.healthFill), party = LK.fill(W, M.healthFill), focus = LK.fill(W, F.healthFill) }
	check("bar looks: the health of a player is the class colour, of a hostile unit the reaction colour, and of a member of the group the class colour of the member",
		LK.r.player == "0.58,0.51,0.79" and LK.r.hostile == "0.90,0.10,0.10" and LK.r.party == "1.00,1.00,1.00" and LK.r.focus == "1.00,0.96,0.41",
		table.concat({ LK.r.player, LK.r.hostile, LK.r.party, LK.r.focus }, " "))
	who.target.reaction = { 0.2, 0.9, 0.2 }
	LK.update(W, T.frame)
	LK.friendly = LK.fill(W, T.healthFill)
	who.target.reaction = { 0.5, 0.5, 0.5 }
	LK.update(W, T.frame)
	LK.tapped = LK.fill(W, T.healthFill)
	check("bar looks: a friendly unit is green and a tapped unit grey, as the game gives them, and a name update puts the new colour on the bar", LK.friendly == "0.20,0.90,0.20"
		and LK.tapped == "0.50,0.50,0.50", LK.friendly .. " " .. LK.tapped)
	who.target = { player = true, class = "MAGE" }
	W.fire("PLAYER_TARGET_CHANGED")
	LK.mage = LK.fill(W, T.healthFill)
	who.target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } }
	W.fire("UNIT_TARGET", "target")
	LK.again = LK.fill(W, T.healthFill)
	who.focus = { player = true, class = "MAGE" }
	W.fire("PLAYER_FOCUS_CHANGED")
	LK.focus2 = LK.fill(W, F.healthFill)
	who.party1 = { player = true, class = "MAGE" }
	W.fire("GROUP_ROSTER_UPDATE")
	LK.party2 = LK.fill(W, M.healthFill)
	who.target.reaction = { 0.2, 0.2, 0.9 }
	W.fire("UNIT_FACTION", "target")
	LK.faction = LK.fill(W, T.healthFill)
	check("bar looks: a new target, a new focus, a change of the group and a change of faction each put the colour of the unit on the bar without a name update", LK.mage == "0.25,0.78,0.92"
		and LK.again == "0.90,0.10,0.10" and LK.focus2 == "0.25,0.78,0.92" and LK.party2 == "0.25,0.78,0.92" and LK.faction == "0.20,0.20,0.90",
		table.concat({ LK.mage, LK.again, LK.focus2, LK.party2, LK.faction }, " "))
	who.target.reaction = { 0.9, 0.1, 0.1 }
	who.party1 = { player = true, class = "PRIEST" }
	who.focus = { player = true, class = "ROGUE" }
	LK.update(W, T.frame)

	-- A class the client withholds.
	who.focus.secret, who.player.secret = true, true
	LK.update(W, F.frame)
	LK.update(W, F.frame)
	W.change("unitframes.lookClassHealth", false)
	W.change("unitframes.lookClassHealth", true)
	LK.status = W.status()
	check("bar looks: a class the client withholds leaves the Health colour on the bar and the status says so once for each frame", LK.fill(W, F.healthFill) == LK.BASE
		and LK.fill(W, P.healthFill) == LK.BASE and LK.count(LK.status, "Looks: Health in class and reaction colour: class withheld on focus frame") == 1
		and LK.count(LK.status, "Looks: Health in class and reaction colour: class withheld on player frame") == 1, LK.fill(W, F.healthFill) .. " " .. LK.status:sub(-300))
	who.focus.secret, who.player.secret = nil, nil
	LK.update(W, F.frame)
	W.change("unitframes.lookClassHealth", false)
	W.change("unitframes.lookClassHealth", true)
	check("bar looks: the line goes when the client gives the class again", LK.fill(W, F.healthFill) == "1.00,0.96,0.41" and not has(W.status(), "Looks:"), W.status():sub(-200))
	LK.set(W)
	check("bar looks: with the look off every bar has the Health colour again", LK.fill(W, P.healthFill) == LK.BASE and LK.fill(W, T.healthFill) == LK.BASE
		and LK.fill(W, M.healthFill) == LK.BASE and not has(W.status(), "Looks:"))

	-- Dark health bar, colour shows what is lost.
	LK.set(W, "lookLostColour")
	LK.lost = { fill = LK.fill(W, P.healthFill), back = LK.back(W, P.health) }
	LK.set(W, "lookLostColour", "lookClassHealth")
	LK.lost2 = { fill = LK.fill(W, P.healthFill), back = LK.back(W, P.health), target = LK.back(W, T.box) }
	who.target = { player = true, class = "MAGE" }
	W.fire("PLAYER_TARGET_CHANGED")
	LK.lost2.mage = LK.back(W, T.box)
	who.target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } }
	W.fire("PLAYER_TARGET_CHANGED")
	LK.set(W)
	check("bar looks: the dark health bar has the Health colour behind it where health is lost, and the colour of the unit with the class look", LK.lost.fill == "0.10,0.10,0.10"
		and LK.lost.back == LK.BASE .. ",1.00" and LK.lost2.fill == "0.10,0.10,0.10" and LK.lost2.back == "0.58,0.51,0.79,1.00" and LK.lost2.target == "0.90,0.10,0.10,1.00",
		table.concat({ LK.lost.back, LK.lost2.back, LK.lost2.target }, " "))
	check("bar looks: a new target puts its colour behind the dark bar", LK.lost2.mage == "0.25,0.78,0.92,1.00", LK.lost2.mage)
	check("bar looks: with the look off the fill is the Health colour and the background behind the bar is the general one again", LK.fill(W, P.healthFill) == LK.BASE
		and LK.back(W, P.health) == LK.off.back and LK.back(W, T.box) == LK.off.back, LK.back(W, P.health) .. " " .. LK.off.back)
	LK.set(W, "lookLostColour")
	W.change("unitframes.flat", false)
	LK.flatOff = LK.back(W, P.health)
	W.change("unitframes.flat", true)
	W.change("unitframes.backdrop", false)
	LK.noBack, LK.noBackStatus = LK.fill(W, P.healthFill), W.status()
	W.change("unitframes.backdrop", true)
	check("bar looks: with Flat bars off the background is the general one, and with Bar background off the bar stays in the Health colour and the status says why",
		LK.flatOff == LK.off.back and LK.noBack == LK.BASE and has(LK.noBackStatus, "Looks: Dark health bar, colour shows what is lost: needs Bar background")
		and LK.fill(W, P.healthFill) == "0.10,0.10,0.10" and not has(W.status(), "Looks:"), LK.noBackStatus:sub(-200))
	LK.set(W)

	-- Muted colours.
	LK.set(W, "lookMuted", "lookClassHealth")
	LK.muted = { health = LK.fill(W, P.healthFill), power = LK.fill(W, P.powerFill) }
	LK.set(W, "lookMuted")
	LK.muted.base = LK.fill(W, P.healthFill)
	LK.set(W)
	check("bar looks: muted colours keep 65% of the colour and 90% of the brightness, on the class colour, the Health colour and the colour of the power", LK.muted.health == "0.52,0.48,0.64"
		and LK.muted.power == "0.03,0.03,0.62" and LK.muted.base == "0.27,0.58,0.34" and LK.fill(W, P.healthFill) == LK.BASE and LK.fill(W, P.powerFill) == "0.00,0.00,1.00",
		table.concat({ LK.muted.health, LK.muted.power, LK.muted.base }, " "))
	W.change("unitframes.stripColour", "Class or reaction colour")
	LK.rowOff = LK.painted(W, 0.58 * 0.7, 0.51 * 0.7, 0.79 * 0.7)
	LK.set(W, "lookMuted")
	LK.rowOn = { muted = LK.painted(W, 0.51627 * 0.7, 0.47532 * 0.7, 0.63912 * 0.7), plain = LK.painted(W, 0.58 * 0.7, 0.51 * 0.7, 0.79 * 0.7) }
	LK.set(W)
	W.change("unitframes.stripColour", "Class or reaction colour, fading upward")
	check("bar looks: the name row is muted with the same numbers, and not while the look is off", LK.rowOff and LK.rowOn.muted and not LK.rowOn.plain, tostring(LK.rowOff) .. tostring(LK.rowOn.muted) .. tostring(LK.rowOn.plain))

	-- The border of the picture by class, muted with the rest.
	function LK.border(portrait)
		local owner, frame = W.rawOf[portrait].owner, nil
		for _, f in ipairs(W.addonFrames) do
			if not frame and f.parent == owner then
				for _, tx in ipairs(f.regions) do
					if tx.layer == "ARTWORK" and tx.addon then
						frame = f
					end
				end
			end
		end
		local edges = frame and W.edgesOn(frame) or {}
		return edges[1] and LK.rgb(edges[1].color) or "none"
	end
	W.change("unitframes.portraitBorder", "Class or reaction colour")
	LK.border1 = LK.border(P.portrait)
	LK.set(W, "lookMuted")
	LK.border2 = LK.border(P.portrait)
	LK.set(W)
	LK.border3 = LK.border(P.portrait)
	W.change("unitframes.portraitBorder", "Thin")
	check("bar looks: the class colour of the border of the picture is muted with the look, and the same colour without it", LK.border1 == "0.58,0.51,0.79" and LK.border2 == "0.52,0.48,0.64"
		and LK.border3 == "0.58,0.51,0.79", table.concat({ LK.border1, LK.border2, LK.border3 }, " "))

	-- White names.
	LK.set(W, "lookWhiteNames")
	LK.white = { player = LK.col(LK.name(W, "Dxml Bozo")), target = LK.col(LK.name(W, "Target")) }
	LK.update(W, P.frame)
	LK.white.again = LK.col(LK.name(W, "Dxml Bozo"))
	W.change("unitframes.levelColour", "Same as the name")
	LK.white.level = LK.col(LK.name(W, "60"))
	W.change("unitframes.levelColour", "By difficulty")
	W.change("unitframes.strip", false)
	LK.white.noRow = LK.rgb(W.rawOf[P.nameText].textColour)
	W.change("unitframes.strip", true)
	LK.set(W)
	LK.white.off = LK.col(LK.name(W, "Dxml Bozo"))
	check("bar looks: white names are white on the rows, and again after the game writes the name", LK.white.player == "1.00,1.00,1.00" and LK.white.target == "1.00,1.00,1.00"
		and LK.white.again == "1.00,1.00,1.00", table.concat({ LK.white.player, LK.white.target, LK.white.again }, " "))
	check("bar looks: a level that follows the name is white too, a frame without a row keeps the game's name colour, and with the look off the name has the game's colour again",
		LK.white.level == "1.00,1.00,1.00" and LK.white.noRow == "1.00,0.82,0.00" and LK.white.off == "1.00,0.82,0.00", table.concat({ LK.white.level, LK.white.noRow, LK.white.off }, " "))

	-- Smaller, lighter bar text.
	LK.set(W, "lookLightText")
	LK.light = { health = LK.font(W, P.healthWords[1]), power = LK.font(W, P.powerWords[1]), target = LK.font(W, T.healthWords[2]) }
	W.fire("PLAYER_ENTERING_WORLD")
	LK.set(W)
	check("bar looks: smaller, lighter bar text is 85% of the size with no outline", LK.light.health == "Fonts\\ARIALN.TTF|10.20|" and LK.light.power == "Fonts\\ARIALN.TTF|8.67|"
		and LK.light.target == "Fonts\\ARIALN.TTF|10.20|", table.concat({ LK.light.health, LK.light.power, LK.light.target }, " "))
	check("bar looks: with the look off the words have the game's size and flags again", LK.font(W, P.healthWords[1]) == LK.off.fontH and LK.font(W, P.powerWords[1]) == LK.off.fontP
		and LK.font(W, T.healthWords[2]) == "Fonts\\ARIALN.TTF|12.00|OUTLINE", LK.font(W, P.healthWords[1]) .. " " .. LK.font(W, P.powerWords[1]))

	-- No text on the power bar.
	LK.set(W, "lookNoPowerText")
	LK.power = { hidden = LK.alpha(W, P.powerWords[1]) + LK.alpha(W, P.powerWords[2]) + LK.alpha(W, P.powerWords[3]), health = LK.alpha(W, P.healthWords[1]),
		target = LK.alpha(W, T.powerWords[1]) }
	LK.set(W)
	check("bar looks: no text on the power bar makes the three words of the power bar transparent and leaves the health text", LK.power.hidden == 0 and LK.power.health == 1 and LK.power.target == 0,
		table.concat({ LK.power.hidden, LK.power.health, LK.power.target }, " "))
	check("bar looks: with the look off the words of the power bar are opaque again", LK.alpha(W, P.powerWords[1]) == 1 and LK.alpha(W, P.powerWords[3]) == 1 and LK.alpha(W, T.powerWords[1]) == 1)

	-- Soft shade on bars.
	LK.set(W, "lookSoftShade")
	LK.soft = { health = W.rawOf[P.healthFill].file, tint = LK.rgb(W.rawOf[P.health].tint), power = W.rawOf[P.powerFill].file, ptint = LK.rgb(W.rawOf[P.power].tint) }
	W.change("general.barTexture", "Gloss")
	LK.soft.gloss = W.rawOf[P.healthFill].file
	LK.set(W)
	LK.soft.off = W.rawOf[P.healthFill].file
	W.change("general.barTexture", "Flat")
	check("bar looks: the soft shade is the soft file on the health and the power bar, in the colour of the bar, whatever bar texture the Flat UI page has", LK.soft.health == LK.SOFT and LK.soft.power == LK.SOFT
		and LK.soft.tint == LK.BASE and LK.soft.ptint == "0.00,0.00,1.00" and LK.soft.gloss == LK.SOFT, table.concat({ tostring(LK.soft.health), tostring(LK.soft.power), LK.soft.tint, LK.soft.ptint }, " "))
	check("bar looks: with the look off the bar has the texture of the Flat UI page again", LK.soft.off == "Interface\\AddOns\\FlatUI\\Media\\Gloss.tga" and LK.fill(W, P.healthFill) == LK.BASE
		and W.rawOf[P.healthFill].file == nil, tostring(LK.soft.off))
	LK.set(W, "lookSoftShade", "lookClassHealth", "lookMuted")
	LK.softClass = LK.rgb(W.rawOf[P.health].tint)
	LK.set(W)
	check("bar looks: the soft shade takes the class colour and the muted colour as the colour of the bar", LK.softClass == "0.52,0.48,0.64", LK.softClass)

	-- The shadow.
	LK.set(W, "lookShadow")
	LK.shadow = LK.shadows(W)
	LK.box = LK.shadow[1] and LK.shadow[1].owner
	LK.pts = LK.box and W.rawOf[LK.box].points or {}
	check("bar looks: the shadow is a texture of the shadow file on a frame of its own on each frame but the raid frames, sliced with margins of 16 and drawn in black at 55%", #LK.shadow == LK.MADE
		and LK.shadow[1].slice and LK.shadow[1].slice[1] == 16 and LK.shadow[1].slice[2] == 16 and LK.shadow[1].slice[3] == 16 and LK.shadow[1].slice[4] == 16 and LK.shadow[1].sliceMode == 0
		and LK.shadow[1].vertex[1] == 0 and LK.shadow[1].vertex[2] == 0 and LK.shadow[1].vertex[3] == 0 and LK.shadow[1].vertex[4] == 0.55 and LK.shadow[1].layer == "BACKGROUND"
		and LK.shadow[1].sublevel == -8 and LK.shadow[1].shown, tostring(#LK.shadow))
	LK.big = nil
	for _, t in ipairs(LK.shadow) do
		local box = W.rawOf[t.owner]
		if box.parent == P.frame then
			LK.big = box
		end
	end
	LK.tex = LK.big and LK.shadow[1]
	check("bar looks: the shadow of the player frame is 8 units outside a box that is on the player frame and spans from the picture and the name row to the health slot and the power bar",
		LK.big ~= nil and #LK.big.points == 4 and LK.big.points[1][1] == "LEFT" and LK.big.points[1][2] ~= P.health and LK.big.points[2][1] == "RIGHT" and LK.big.points[2][2] == P.health
		and LK.big.points[3][1] == "TOP" and LK.big.points[3][2] ~= P.health and LK.big.points[4][1] == "BOTTOM" and LK.big.points[4][2] == P.power and LK.big.shown,
		LK.big and (tostring(#LK.big.points) .. tostring(LK.big.points[1] and LK.big.points[1][1])) or "no box")
	LK.edges = {}
	for _, t in ipairs(LK.shadow) do
		if W.rawOf[t.owner].parent == P.frame then
			LK.edges = t.points
		end
	end
	check("bar looks: the shadow texture is 8 units outside its box on every side", #LK.edges == 2 and LK.edges[1][1] == "TOPLEFT" and LK.edges[1][4] == -8 and LK.edges[1][5] == 8 and LK.edges[2][1] == "BOTTOMRIGHT"
		and LK.edges[2][4] == 8 and LK.edges[2][5] == -8, tostring(#LK.edges))
	LK.tga = assert(io.open("FlatUI/Media/Shadow.tga", "rb"))
	LK.bytes = LK.tga:read("*a")
	LK.tga:close()
	-- 18 byte header, then 64 rows of 64 pixels of 4 bytes (B, G, R, A); the middle rows are 32 from the top, and the alpha is the 4th byte of a pixel.
	LK.texAlpha = function(x) return LK.bytes:byte(18 + (32 * 64 + x) * 4 + 4) end
	check("bar looks: Shadow.tga has alpha 100 to 155 at the edge of its rectangle (pixel 8), 255 in its core and under 10 at its outer edge", LK.texAlpha(8) >= 100 and LK.texAlpha(8) <= 155 and LK.texAlpha(32) == 255 and LK.texAlpha(0) < 10,
		tostring(LK.texAlpha(0)) .. " " .. tostring(LK.texAlpha(8)) .. " " .. tostring(LK.texAlpha(32)))
	LK.calls = 0
	LK.keep = W.ns.UnitFrameExtra.unitsChanged
	W.ns.UnitFrameExtra.unitsChanged = function(...) LK.calls = LK.calls + 1 return LK.keep(...) end
	for _, unit in ipairs({ "nameplate1", "player", "arena1", "raid3" }) do
		W.fire("UNIT_FACTION", unit)
	end
	LK.none = LK.calls
	for _, unit in ipairs({ "target", "focus", "targettarget", "focustarget", "party2", "partypet1", "boss3" }) do
		W.fire("UNIT_FACTION", unit)
	end
	LK.some = LK.calls - LK.none
	W.ns.UnitFrameExtra.unitsChanged = LK.keep
	check("bar looks: UNIT_FACTION for a nameplate, the player, an arena unit or a raid unit changes no frame colour, and for a target, focus, their targets, party, party pet or boss does",
		LK.none == 0 and LK.some == 7, LK.none .. " " .. LK.some)
	W.change("unitframes.squarePortrait", false)
	LK.noPic = LK.big.points[1][2] == P.health
	LK.noPicTop = LK.big.points[3][2] == P.health
	W.change("unitframes.squarePortrait", true)
	check("bar looks: with no picture and no name row the shadow starts at the slot of the health bar", LK.noPic and LK.noPicTop)
	LK.shown = LK.big.shown
	LK.set(W)
	check("bar looks: the shadow is hidden when the look goes and shown again with it", LK.shown and not LK.big.shown and #LK.shadows(W) == LK.MADE)
	LK.set(W, "lookShadow")
	check("bar looks: it is shown again with the look, and nothing is made twice", LK.big.shown and #LK.shadows(W) == LK.MADE)
	LK.set(W)

	-- Every look on and off again: the frames are as before.
	LK.set(W, "lookClassHealth", "lookLostColour", "lookMuted", "lookWhiteNames", "lookLightText", "lookNoPowerText", "lookSoftShade", "lookShadow")
	LK.all = { fill = W.rawOf[P.healthFill].file, quiet = #W.violations == 0 and #W.errors == 0 }
	LK.set(W)
	check("bar looks: with every look on and then off again the fills, the words, the name and the background are as before", LK.all.quiet and LK.fill(W, P.healthFill) == LK.off.health
		and LK.fill(W, P.powerFill) == LK.off.power and LK.font(W, P.healthWords[1]) == LK.off.fontH and LK.font(W, P.powerWords[1]) == LK.off.fontP and LK.back(W, P.health) == LK.off.back
		and LK.col(LK.name(W, "Dxml Bozo")) == LK.off.name and LK.alpha(W, P.powerWords[1]) == 1 and not LK.big.shown and not has(W.status(), "Looks:"), LK.why(W))
	W.change("unitframes.flat", false)
	LK.set(W, "lookClassHealth", "lookSoftShade", "lookLostColour")
	LK.flat = { fill = W.rawOf[P.healthFill].color, back = LK.back(W, P.health) }
	W.change("unitframes.flat", true)
	LK.set(W)
	check("bar looks: with Flat bars off the fill, the shade and the background are the game's", LK.flat.fill == nil and LK.flat.back == LK.off.back and LK.fill(W, P.healthFill) == LK.BASE)

	-- Nothing is made in combat, and a look that goes in combat still hides what it made.
	LK.C = LK.world({ combat = true })
	LK.C.change("unitframes.lookShadow", true)
	LK.combat = #LK.shadows(LK.C)
	LK.C.combat = false
	LK.C.fire("PLAYER_REGEN_ENABLED")
	LK.C.flush()
	LK.after = #LK.shadows(LK.C)
	check("bar looks: no shadow is made in combat, and each is made when combat ends", LK.combat == 0 and LK.after == LK.MADE and #LK.C.violations == 0 and #LK.C.errors == 0, tostring(LK.combat) .. " " .. tostring(LK.after) .. LK.why(LK.C))
	LK.C.combat = true
	LK.C.change("unitframes.lookShadow", false)
	LK.hid = true
	for _, t in ipairs(LK.shadows(LK.C)) do
		LK.hid = LK.hid and not LK.C.rawOf[t.owner].shown
	end
	LK.C.change("unitframes.lookShadow", true)
	LK.shownAgain = true
	for _, t in ipairs(LK.shadows(LK.C)) do
		LK.shownAgain = LK.shownAgain and LK.C.rawOf[t.owner].shown == true
	end
	check("bar looks: a shadow is hidden and shown in combat", LK.hid and LK.shownAgain and #LK.C.violations == 0 and #LK.C.errors == 0, LK.why(LK.C))

	-- A client that refuses the slice: no shadow, one line.
	LK.R = LK.world()
	LK.R.uf.refuseSlice = true
	LK.R.change("unitframes.lookShadow", true)
	LK.refused = LK.R.status()
	check("bar looks: a texture the game refuses gives no shadow and one line on the status", LK.count(LK.refused, "Looks: Shadow behind each frame: the game refused the texture") == 1
		and LK.shadows(LK.R)[1] ~= nil and not LK.R.rawOf[LK.shadows(LK.R)[1].owner].shown, LK.refused:sub(-200))

	-- The game's own colours and callers that pass no new argument.
	LK.N = newWorld()
	LK.N.login()
	LK.frame = LK.N.env.CreateFrame("Frame")
	LK.label = LK.frame:CreateFontString(nil, "ARTWORK")
	LK.N.rawOf[LK.label].font = { "Fonts\\ARIALN.TTF", 12, "OUTLINE" }
	LK.sizes = { LK.N.ns.TextSize(LK.label, 50), LK.font(LK.N, LK.label), LK.N.ns.TextSize(LK.label, 100), LK.font(LK.N, LK.label) }
	LK.flags = { LK.N.ns.TextSize(LK.label, 100, ""), LK.font(LK.N, LK.label), LK.N.ns.TextSize(LK.label, 100, ""), 0, LK.N.ns.TextSize(LK.label, 100), LK.font(LK.N, LK.label) }
	check("bar looks: ns.TextSize with two arguments sets the size and keeps the flags, a string for the flags replaces them, and nil puts the game's flags back", LK.sizes[1] == true
		and LK.sizes[2] == "Fonts\\ARIALN.TTF|6.00|OUTLINE" and LK.sizes[3] == true and LK.sizes[4] == "Fonts\\ARIALN.TTF|12.00|OUTLINE" and LK.flags[1] == true and LK.flags[2] == "Fonts\\ARIALN.TTF|12.00|"
		and LK.flags[3] == true and LK.flags[5] == true and LK.flags[6] == "Fonts\\ARIALN.TTF|12.00|OUTLINE", table.concat({ tostring(LK.sizes[2]), tostring(LK.flags[2]), tostring(LK.flags[6]) }, " "))
	LK.calls = LK.N.rawOf[LK.label].calls.SetFont
	LK.N.ns.TextSize(LK.label, 100, nil)
	LK.N.ns.TextSize(LK.label, 100, nil)
	check("bar looks: ns.TextSize does not set a font that already has the size and flags asked for", LK.N.rawOf[LK.label].calls.SetFont == LK.calls, tostring(LK.calls) .. " " .. tostring(LK.N.rawOf[LK.label].calls.SetFont))
	check("bar looks: ns.BarFile gives the file of a bar texture by its name and nothing for a name it has not", W.ns.BarFile("soft") == LK.SOFT and W.ns.BarFile("none") == nil)

	-- Mana bar colour: the fill of the power bar of the player frame for a class colour and a few settings.
	LK.SKY, LK.GAME = "0.35,0.85,1.00", "0.00,0.00,1.00"
	function LK.mana(o)
		local M = LK.world()
		M.env.RAID_CLASS_COLORS.SHAMAN = setmetatable({ r = o.shaman or 0, g = o.shamanG or 0.44, b = o.shamanB or 0.87, a = 1 }, COLOUR_MT)
		M.env.RAID_CLASS_COLORS.REDDISH = setmetatable({ r = 1, g = 0.1, b = 0.1, a = 1 }, COLOUR_MT)
		M.uf.who.player = { player = true, class = o.class or "SHAMAN", secret = o.secret }
		if o.rage then
			M.rawOf[M.player.power].powerToken = "RAGE"
		end
		if o.stop then
			M.ns.PartStopped = function(key, part) return key == "unitframes" and part == "Looks" end
		end
		if o.curve then
			local colour = { GetRGB = function() return 1, 0, 0 end }
			M.env.CreateColor = function() return colour end
			M.env.C_CurveUtil = { CreateColorCurve = function() return { AddPoint = function() end } end }
			M.env.UnitHealthPercent = function() return colour end
		end
		if o.stopHealth then
			M.ns.PartStopped = function(key, part) return key == "unitframes" and part == "health curve" end
		end
		for _, set in ipairs(o.set or {}) do
			M.change(set[1], set[2])
		end
		if o.plain then
			M.change("unitframes.lookMuted", true)
			M.change("unitframes.lookMuted", false)
		else
			M.change("unitframes.lookClassHealth", true)
		end
		return LK.fill(M, M.player.powerFill)
	end
	LK.m = { shaman = LK.mana({}), game = LK.mana({ set = { { "unitframes.manaColour", "As the game has it" } } }), warlock = LK.mana({ class = "WARLOCK" }),
		mage = LK.mana({ class = "MAGE" }), health = LK.mana({ plain = true }) }
	check("mana colour: a Shaman health bar next to the mana bar makes the mana sky blue, a Warlock, a Mage and the Health colour leave it the game's blue, and As the game has it leaves it too",
		LK.m.shaman == LK.SKY and LK.m.game == LK.GAME and LK.m.warlock == LK.GAME and LK.m.mage == LK.GAME and LK.m.health == LK.GAME,
		table.concat({ LK.m.shaman, LK.m.game, LK.m.warlock, LK.m.mage, LK.m.health }, " "))
	LK.o = { own = LK.mana({ set = { { "general.powerOwn", true } } }), sky = LK.mana({ set = { { "general.powerOwn", true }, { "general.powerMana", "ff59d9ff" },
		{ "unitframes.manaColour", "As the game has it" } } }), red = LK.mana({ set = { { "general.powerOwn", true }, { "general.powerMana", "ffff0000" } } }) }
	check("mana colour: Custom power colours reaches the power bar of the frame, sky blue next to a Shaman with the Mana colour left blue, and the colour set as it is with As the game has it",
		LK.o.own == LK.SKY and LK.o.sky == "0.35,0.85,1.00" and LK.o.red == "1.00,0.00,0.00", table.concat({ LK.o.own, LK.o.sky, LK.o.red }, " "))
	LK.n = { dark = LK.mana({ set = { { "unitframes.lookLostColour", true } } }), secret = LK.mana({ secret = true }), rage = LK.mana({ class = "REDDISH", rage = true }),
		near = LK.mana({ shaman = 0.15, shamanG = 0.45, shamanB = 1 }) }
	check("mana colour: a dark health bar, a class colour the client withholds, a Rage bar and a unit colour near sky blue as well leave the bar as it was",
		LK.n.dark == LK.GAME and LK.n.secret == LK.GAME and LK.n.rage == "1.00,0.00,0.00" and LK.n.near == LK.GAME, table.concat({ LK.n.dark, LK.n.secret, LK.n.rage, LK.n.near }, " "))
	LK.q = { keep = LK.mana({ set = { { "unitframes.lookLostColour", true }, { "unitframes.backdrop", false } } }), stop = LK.mana({ stop = true }),
		reaction = LK.mana({ set = { { "unitframes.playerHealthBy", "Reaction" } }, plain = true }), left = LK.mana({ curve = true, set = { { "unitframes.healthByLeft", true } } }),
		leftStopped = LK.mana({ curve = true, stopHealth = true, set = { { "unitframes.healthByLeft", true } } }) }
	check("mana colour: a dark health bar with Bar background off keeps its class colour so the mana turns sky blue, a stopped Looks part, a Reaction health colour and Colour health bars by health left leave the bar as it was",
		LK.q.keep == LK.SKY and LK.q.stop == LK.GAME and LK.q.reaction == LK.GAME and LK.q.left == LK.GAME, table.concat({ LK.q.keep, LK.q.stop, LK.q.reaction, LK.q.left }, " "))
	check("mana colour: Colour health bars by health left with the health curve part stopped leaves the health bar its class colour so the mana turns sky blue", LK.q.leftStopped == LK.SKY, LK.q.leftStopped)
	LK.p = LK.world()
	LK.p.env.RAID_CLASS_COLORS.SHAMAN = setmetatable({ r = 0, g = 0.44, b = 0.87, a = 1 }, COLOUR_MT)
	LK.p.uf.who.player.class = "SHAMAN"
	LK.p.change("unitframes.lookClassHealth", true)
	LK.p.change("unitframes.manaColour", "As the game has it")
	LK.m.back = LK.fill(LK.p, LK.p.player.powerFill)
	LK.p.change("unitframes.manaColour", "Sky blue next to a blue health bar")
	check("mana colour: the choice is on the bars page, Sky blue next to a blue health bar by default, and changing it changes the bar at once", LK.p.control("unitframes.manaColour") ~= nil
		and LK.p.control("unitframes.manaColour").data.name == "Mana bar colour" and LK.m.back == LK.GAME and LK.fill(LK.p, LK.p.player.powerFill) == LK.SKY and LK.m.shaman == LK.SKY)
end
-- >>> bar looks (end)
-- >>> ms-10 unit frame looks (begin)
-- Picture, level, resting animation, health colour, bar textures, name background brightness and aura icons of the unit frames, on the pages of each frame and on
-- All frames. Every label starts "ms-uf1:". The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local MU = { BASE = "0.18,0.72,0.30", SOFT = "Interface\\AddOns\\FlatUI\\Media\\Soft.tga", GLOSS = "Interface\\AddOns\\FlatUI\\Media\\Gloss.tga" }
	function MU.world(opts)
		local W = FH.ufWorld(opts)
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local U, env = W.uf, W.env
		U.who = { player = { player = true, class = "WARLOCK" }, target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } },
			focus = { player = true, class = "ROGUE" }, party1 = { player = true, class = "PRIEST" }, pet = { player = false, class = "WARRIOR", reaction = { 0.2, 0.9, 0.2 } } }
		env.RAID_CLASS_COLORS = { WARLOCK = setmetatable({ r = 0.58, g = 0.51, b = 0.79, a = 1 }, COLOUR_MT), ROGUE = setmetatable({ r = 1, g = 0.96, b = 0.41, a = 1 }, COLOUR_MT),
			MAGE = setmetatable({ r = 0.25, g = 0.78, b = 0.92, a = 1 }, COLOUR_MT), PRIEST = setmetatable({ r = 1, g = 1, b = 1, a = 1 }, COLOUR_MT),
			WARRIOR = setmetatable({ r = 0.78, g = 0.61, b = 0.43, a = 1 }, COLOUR_MT) }
		env.UnitIsPlayer = function(unit) return U.who[unit] ~= nil and U.who[unit].player end
		env.UnitClass = function(unit)
			local who = U.who[unit]
			if who == nil then
				return "Warlock", "WARLOCK", 9
			end
			return who.class:sub(1, 1) .. who.class:sub(2):lower(), who.class, 1
		end
		env.GetClassAtlas = function(class) return "classicon-" .. class:lower() end
		env.UnitSelectionColor = function(unit)
			local c = U.who[unit] and U.who[unit].reaction or { 1, 1, 0 }
			return c[1], c[2], c[3], 1
		end
		W.flush()
		return W
	end
	-- The picture of the addon's own beside the bars of a portrait's frame, and whether it and its border are shown or hidden.
	function MU.pic(W, portrait)
		local owner, frame = W.rawOf[portrait].owner, nil
		for _, f in ipairs(W.addonFrames) do
			if not frame and f.parent == owner then
				for _, t in ipairs(f.regions) do
					if t.layer == "ARTWORK" and t.addon then
						frame = f
					end
				end
			end
		end
		if not frame then
			return {}
		end
		local P = { edges = W.edgesOn(frame), back = W.backdropOn(frame) }
		for _, t in ipairs(frame.regions) do
			if t.layer == "ARTWORK" and t.sublevel ~= 7 then
				P.texture = t
			end
		end
		P.shown = #P.edges == 4 and P.edges[1].shown and P.back ~= nil and P.back.shown and P.texture ~= nil and P.texture.shown
		P.hidden = #P.edges == 4 and not P.edges[1].shown and not P.back.shown and not P.texture.shown
		return P
	end
	function MU.silent(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "failed") and not has(W.status(), "stopped") end
	function MU.why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. tostring(W.line("Unit frames")) end
	function MU.rgb(c) return c and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) or "-" end
	function MU.fill(W, fill) return MU.rgb(W.rawOf[fill].color) end
	function MU.painted(W, r, g, b)
		for _, t in ipairs(W.addonTextures) do
			local c = t.color
			if t.shown and c and math.abs(c[1] - r) < 0.006 and math.abs(c[2] - g) < 0.006 and math.abs(c[3] - b) < 0.006 and math.abs((c[4] or 0) - 0.95) < 0.001 then
				return true
			end
		end
		return false
	end

	local W = MU.world()
	local P, T, F, Pet, Tot, M = W.player, W.target, W.focus, W.pet, W.tot, W.members[1]

	-- The rows: the pages, the defaults and the choices.
	do
		local want = { playerPicture = "auto", targetPicture = "auto", focusPicture = "auto", petPicture = "auto", totPicture = "auto", partyPicture = "auto", partypetPicture = "auto",
			playerLevel = true, targetLevel = true, focusLevel = true, bossLevel = true, restAnimation = "auto", playerHealthBy = "custom", targetHealthBy = "custom",
			focusHealthBy = "custom", petHealthBy = "custom", totHealthBy = "class", partyHealthBy = "custom", bossHealthBy = "custom", stripBrightness = 70, healthTexture = "default",
			powerTexture = "default", auraCrop = 8, auraTypeColours = true, auraCountSize = 100, auraNumbers = false }
		local wrong = {}
		for key, default in pairs(want) do
			if W.ns.Get("unitframes." .. key) ~= default or W.control("unitframes." .. key) == nil then
				wrong[#wrong + 1] = key
			end
		end
		check("ms-uf1: the 26 rows are on the pages with their defaults", #wrong == 0, table.concat(wrong, " "))
		local byKey = {}
		for _, page in ipairs(W.ns.PAGES) do
			for _, item in ipairs(page) do
				if item.key then
					byKey[item.key] = page.key
				end
			end
		end
		local pages = { playerPicture = "unitframesPlayer", restAnimation = "unitframesPlayer", targetHealthBy = "unitframesTarget", focusLevel = "unitframesFocus", petPicture = "unitframesPet",
			totPicture = "unitframesTot", partypetPicture = "unitframesParty", bossLevel = "unitframesBoss", stripBrightness = "unitframesBars", powerTexture = "unitframesBars",
			auraCrop = "unitframesIcons", auraNumbers = "unitframesIcons" }
		wrong = {}
		for key, page in pairs(pages) do
			if byKey[key] ~= page then
				wrong[#wrong + 1] = key .. "@" .. tostring(byKey[key])
			end
		end
		check("ms-uf1: each row is on the page of its frame or of All frames", #wrong == 0, table.concat(wrong, " "))
	end

	-- Target of target health bar colour: Class by default, like the author's target frame.
	do
		local v = { by = W.ns.Get("unitframes.totHealthBy") }
		check("tot health colour: Health bar colour of the target of target frame is Class by default", v.by == "class", tostring(v.by))
		check("tot health colour: the other frames keep Health colour", W.ns.Get("unitframes.petHealthBy") == "custom" and W.ns.Get("unitframes.partyHealthBy") == "custom")
	end

	-- Untouched: the frames are as before.
	MU.off = { health = MU.fill(W, P.healthFill), power = MU.fill(W, P.powerFill), thealth = MU.fill(W, T.healthFill), shownP = MU.pic(W, P.portrait).shown, shownT = MU.pic(W, T.portrait).shown,
		gamePortrait = W.rawOf[P.portrait].shown, plate = W.rawOf[P.level].alpha, number = W.rawOf[P.levelText].alpha, rest = W.rawOf[P.rest].alpha }
	check("ms-uf1: with every row at its default the fills, the pictures, the level and the resting animation are as they were", MU.off.health == MU.BASE and MU.off.power == "0.00,0.00,1.00"
		and MU.off.thealth == MU.BASE and MU.off.shownP and MU.off.shownT and not MU.off.gamePortrait and MU.off.plate == 0 and MU.off.number == 0 and MU.off.rest == 0 and MU.silent(W), MU.why(W))

	-- Picture.
	W.change("unitframes.playerPicture", "Game portrait")
	MU.game = { pic = MU.pic(W, P.portrait).hidden, portrait = W.rawOf[P.portrait].shown, status = W.status(), other = MU.pic(W, T.portrait).shown }
	check("ms-uf1: Game portrait hides the picture and its border and shows the game's portrait on that frame only, and the status says so", MU.game.pic and MU.game.portrait and MU.game.other
		and has(MU.game.status, "Player portrait: off, the game's portrait shown") and MU.silent(W), MU.game.status:sub(1, 200))
	W.change("unitframes.playerPicture", "None")
	check("ms-uf1: None hides the picture and the game's portrait and leaves the slot empty", MU.pic(W, P.portrait).hidden and not W.rawOf[P.portrait].shown and has(W.status(), "Player portrait: off, no portrait"), W.status():sub(1, 200))
	W.change("unitframes.playerPicture", "As Square portraits")
	check("ms-uf1: As Square portraits is the picture again", MU.pic(W, P.portrait).shown and not W.rawOf[P.portrait].shown and MU.silent(W), MU.why(W))
	W.change("unitframes.portraitStyle", "None")
	check("ms-uf1: with Portrait style None the frames have no picture", MU.pic(W, P.portrait).hidden and MU.pic(W, T.portrait).hidden)
	W.change("unitframes.targetPicture", "Square picture")
	W.change("unitframes.playerPicture", "Class icon")
	check("ms-uf1: Square picture and Class icon draw the picture of their own frame whatever Portrait style says", MU.pic(W, T.portrait).shown and MU.pic(W, P.portrait).shown and MU.pic(W, F.portrait).hidden
		and W.rawOf[MU.pic(W, P.portrait).texture].atlas == "classicon-warlock", tostring(W.rawOf[MU.pic(W, P.portrait).texture].atlas))
	W.change("unitframes.portraitStyle", "Class icon")
	W.change("unitframes.targetPicture", "Class icon")
	check("ms-uf1: Class icon on a target that is no player keeps the face", MU.pic(W, T.portrait).shown and W.rawOf[MU.pic(W, T.portrait).texture].atlas == nil, tostring(W.rawOf[MU.pic(W, T.portrait).texture].atlas))
	W.change("unitframes.playerPicture", "Square picture")
	W.change("unitframes.targetPicture", "As Square portraits")
	check("ms-uf1: Square picture shows the face where Portrait style says Class icon", W.rawOf[MU.pic(W, P.portrait).texture].atlas == nil and W.rawOf[MU.pic(W, F.portrait).texture].atlas == "classicon-rogue")
	W.change("unitframes.portraitStyle", "Picture")
	W.change("unitframes.playerPicture", "As Square portraits")
	W.change("unitframes.partyPicture", "None")
	W.change("unitframes.partypetPicture", "Game portrait")
	check("ms-uf1: the party row and the party pet row are separate", MU.pic(W, M.portrait).hidden and not W.rawOf[M.portrait].shown and MU.pic(W, T.portrait).shown, MU.why(W))
	W.change("unitframes.partyPicture", "As Square portraits")
	W.change("unitframes.partypetPicture", "As Square portraits")
	W.change("unitframes.petPicture", "None")
	check("ms-uf1: the pet picture row hides the pet's picture", MU.pic(W, Pet.portrait).hidden and MU.pic(W, P.portrait).shown)
	W.change("unitframes.petPicture", "As Square portraits")
	W.change("unitframes.squarePortrait", false)
	W.change("unitframes.playerPicture", "Square picture")
	check("ms-uf1: with Square portraits off the game's portraits stay whatever the rows say", W.rawOf[P.portrait].shown and MU.pic(W, P.portrait).hidden)
	W.change("unitframes.squarePortrait", true)
	W.change("unitframes.playerPicture", "As Square portraits")

	-- Level.
	W.change("unitframes.targetLevel", false)
	MU.lv = { target = FH.kindRow(W, T.frame).level.shown, player = FH.kindRow(W, P.frame).level.shown, plate = W.rawOf[T.level].alpha, number = W.rawOf[T.levelText].alpha }
	check("ms-uf1: Level off shows no level on the target and leaves the player's", not MU.lv.target and MU.lv.player and MU.lv.plate == 0 and MU.lv.number == 0 and MU.silent(W), MU.why(W))
	W.change("unitframes.strip", false)
	check("ms-uf1: with Level off and no name row the game's plate and number of that frame are transparent and the others are the game's", W.rawOf[T.level].alpha == 0 and W.rawOf[T.levelText].alpha == 0
		and W.rawOf[P.level].alpha == 1 and W.rawOf[P.levelText].alpha == 1)
	W.change("unitframes.targetLevel", true)
	check("ms-uf1: Level on again gives the game's plate and number back with no name row", W.rawOf[T.level].alpha == 1 and W.rawOf[T.levelText].alpha == 1)
	W.change("unitframes.strip", true)
	check("ms-uf1: and the row's level is back", FH.kindRow(W, T.frame).level.shown)

	-- Resting animation.
	W.change("unitframes.restAnimation", "Shown")
	MU.rest = W.rawOf[P.rest].alpha
	W.change("unitframes.restAnimation", "Hidden")
	MU.rest2 = W.rawOf[P.rest].alpha
	W.change("unitframes.status", false)
	MU.rest3 = W.rawOf[P.rest].alpha
	W.change("unitframes.restAnimation", "Hidden with the resting colour")
	MU.rest4 = W.rawOf[P.rest].alpha
	W.change("unitframes.restAnimation", "Shown")
	MU.rest5 = W.rawOf[P.rest].alpha
	W.change("unitframes.status", true)
	W.change("unitframes.restAnimation", "Hidden with the resting colour")
	check("ms-uf1: Shown never hides the resting animation, Hidden always does, and the default hides it with the resting colour", MU.rest == 1 and MU.rest2 == 0 and MU.rest3 == 0 and MU.rest4 == 1
		and MU.rest5 == 1 and W.rawOf[P.rest].alpha == 0, table.concat({ MU.rest, MU.rest2, MU.rest3, MU.rest4, MU.rest5 }, " "))

	-- Health bar colour.
	W.change("unitframes.playerHealthBy", "Class")
	W.change("unitframes.targetHealthBy", "Class")
	W.change("unitframes.focusHealthBy", "Reaction")
	W.change("unitframes.partyHealthBy", "Class")
	W.change("unitframes.petHealthBy", "Reaction")
	MU.by = { MU.fill(W, P.healthFill), MU.fill(W, T.healthFill), MU.fill(W, F.healthFill), MU.fill(W, M.healthFill), MU.fill(W, Pet.healthFill) }
	check("ms-uf1: Class colours a player by class and a unit that is no player by reaction, Reaction colours by reaction, each frame by its own row", MU.by[1] == "0.58,0.51,0.79"
		and MU.by[2] == "0.90,0.10,0.10" and MU.by[3] == "1.00,1.00,0.00" and MU.by[4] == "1.00,1.00,1.00" and MU.by[5] == "0.20,0.90,0.20", table.concat(MU.by, " "))
	W.change("unitframes.totHealthBy", "Health colour")
	check("ms-uf1: a frame whose row says Health colour keeps it", MU.fill(W, Tot.healthFill) == MU.BASE)
	W.uf.who.target = { player = true, class = "MAGE" }
	W.fire("PLAYER_TARGET_CHANGED")
	MU.mage = MU.fill(W, T.healthFill)
	W.uf.who.target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } }
	W.fire("PLAYER_TARGET_CHANGED")
	check("ms-uf1: a new target puts its colour on the bar", MU.mage == "0.25,0.78,0.92" and MU.fill(W, T.healthFill) == "0.90,0.10,0.10", MU.mage)
	W.change("unitframes.lookMuted", true)
	check("ms-uf1: Muted colours mutes it", MU.fill(W, P.healthFill) ~= "0.58,0.51,0.79")
	W.change("unitframes.lookMuted", false)
	W.change("unitframes.flat", false)
	check("ms-uf1: with Flat bars off the rows of the health colour are not usable", not W.enabled("unitframes.playerHealthBy") and not W.enabled("unitframes.healthTexture"))
	W.change("unitframes.flat", true)
	for _, frame in ipairs({ "player", "target", "focus", "party", "pet" }) do
		W.change("unitframes." .. frame .. "HealthBy", "Health colour")
	end
	check("ms-uf1: Health colour on every row gives the Health colour on every bar", MU.fill(W, P.healthFill) == MU.BASE and MU.fill(W, T.healthFill) == MU.BASE and MU.fill(W, F.healthFill) == MU.BASE
		and MU.fill(W, M.healthFill) == MU.BASE and MU.silent(W), MU.why(W))
	W.change("unitframes.lookClassHealth", true)
	check("ms-uf1: a row at Health colour still follows Health in class and reaction colour", MU.fill(W, P.healthFill) == "0.58,0.51,0.79")
	W.change("unitframes.targetHealthBy", "Reaction")
	W.change("unitframes.lookClassHealth", false)
	check("ms-uf1: the look off, a row that says Reaction keeps its colour and the others go back", MU.fill(W, T.healthFill) == "0.90,0.10,0.10" and MU.fill(W, P.healthFill) == MU.BASE)
	W.change("unitframes.targetHealthBy", "Health colour")

	-- Name background brightness.
	W.change("unitframes.stripColour", "Class or reaction colour")
	MU.row70 = MU.painted(W, 0.58 * 0.7, 0.51 * 0.7, 0.79 * 0.7)
	W.change("unitframes.stripBrightness", 100)
	MU.row100 = MU.painted(W, 0.58, 0.51, 0.79)
	W.change("unitframes.stripBrightness", 40)
	MU.row40 = MU.painted(W, 0.58 * 0.4, 0.51 * 0.4, 0.79 * 0.4)
	W.change("unitframes.stripBrightness", 70)
	W.change("unitframes.stripColour", "Class or reaction colour, fading upward")
	check("ms-uf1: the name row has 70% of the colour by default, and the setting changes it", MU.row70 and MU.row100 and MU.row40, tostring(MU.row70) .. tostring(MU.row100) .. tostring(MU.row40))

	-- Bar textures.
	W.change("unitframes.healthTexture", "Soft shade")
	MU.tex = { health = W.rawOf[P.healthFill].file, power = W.rawOf[P.powerFill].file }
	W.change("unitframes.powerTexture", "Gloss")
	MU.tex.power2 = W.rawOf[P.powerFill].file
	W.change("general.barTexture", "Gloss")
	W.change("unitframes.healthTexture", "Flat")
	MU.tex.flat = W.rawOf[P.healthFill].file
	W.change("unitframes.healthTexture", "Same as the Flat UI page")
	MU.tex.page = W.rawOf[P.healthFill].file
	W.change("unitframes.powerTexture", "Same as the Flat UI page")
	W.change("general.barTexture", "Flat")
	check("ms-uf1: the health row and the power row each choose their texture, Flat gives a solid fill over the page's texture and the default follows the page", MU.tex.health == MU.SOFT
		and MU.tex.power == nil and MU.tex.power2 == MU.GLOSS and MU.tex.flat == nil and MU.tex.page == MU.GLOSS and W.rawOf[P.healthFill].file == nil, table.concat({ tostring(MU.tex.health), tostring(MU.tex.power),
		tostring(MU.tex.power2), tostring(MU.tex.flat), tostring(MU.tex.page) }, " "))
	W.change("unitframes.lookSoftShade", true)
	W.change("unitframes.powerTexture", "Gloss")
	MU.soft = { W.rawOf[P.healthFill].file, W.rawOf[P.powerFill].file }
	W.change("unitframes.powerTexture", "Same as the Flat UI page")
	W.change("unitframes.lookSoftShade", false)
	check("ms-uf1: the soft shade look still applies where the row follows the page, and a row of its own wins over it", MU.soft[1] == MU.SOFT and MU.soft[2] == MU.GLOSS, tostring(MU.soft[1]) .. tostring(MU.soft[2]))

	-- Aura icons.
	MU.btn = M.auras[1]
	W.uf.debuff[M.frame] = { "Magic" }
	W.blizzard(function() M.frame:UpdateAuras() end)
	MU.crop0 = table.concat(W.rawOf[MU.btn.icon].texCoord or {}, ",")
	W.change("unitframes.auraCrop", 12)
	MU.crop12 = W.rawOf[MU.btn.icon].texCoord
	W.change("unitframes.auraCrop", 0)
	MU.crop00 = W.rawOf[MU.btn.icon].texCoord
	W.change("unitframes.auraCrop", 8)
	check("ms-uf1: the icons are cut 8% at each edge by default, and a changed crop reaches icons already styled", MU.crop0 == "0.08,0.92,0.08,0.92" and near(MU.crop12[1], 0.12) and near(MU.crop12[2], 0.88)
		and near(MU.crop00[1], 0) and near(MU.crop00[4], 1), MU.crop0)
	W.change("unitframes.auraTypeColours", false)
	W.change("unitframes.auraTypeColours", true)
	check("ms-uf1: Border colour by debuff type off and on again raises no error", MU.silent(W), MU.why(W))
	W.change("unitframes.auraCountSize", 150)
	MU.count150 = W.rawOf[MU.btn.count].font[2]
	W.change("unitframes.auraCountSize", 100)
	MU.count100 = W.rawOf[MU.btn.count].font[2]
	check("ms-uf1: Stack number size makes the stack number of a party debuff larger and the default gives the game's size back", near(MU.count150, 18) and near(MU.count100, 12), tostring(MU.count150) .. " " .. tostring(MU.count100))
	check("ms-uf1: at the defaults the countdown numbers of the cooldown are not touched", #MU.btn.hides == 0, #MU.btn.hides)
	W.change("unitframes.auraNumbers", true)
	MU.n1 = MU.btn.hides[#MU.btn.hides]
	W.change("unitframes.auraNumbers", false)
	MU.n2 = MU.btn.hides[#MU.btn.hides]
	MU.nCalls = #MU.btn.hides
	W.change("unitframes.auraNumbers", false)
	check("ms-uf1: Countdown numbers shows them on a party debuff, off hides them again and nothing is called twice", MU.n1 == false and MU.n2 == true and #MU.btn.hides == MU.nCalls and MU.silent(W), tostring(MU.n1) .. tostring(MU.n2))
	W.change("unitframes.auras", false)
	W.change("unitframes.auraCountSize", 150)
	check("ms-uf1: Stack number size does not need Aura icon borders", near(W.rawOf[MU.btn.count].font[2], 18))
	W.change("unitframes.auraCountSize", 100)
	W.change("unitframes.auras", true)
end
-- >>> ms-10 unit frame looks (end)
-- >>> ms-13 unit frame parts (begin)
-- Icons, dead text, power bars, party range, heal prediction and shields, the parts of a raid frame, raid range and the timers of the totem buttons. Every label
-- starts "ms-ufpart:". The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local MP = {}
	function MP.silent(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "failed") and not has(W.status(), "stopped") end
	function MP.why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. tostring(W.line("Unit frames")) end
	function MP.a(W, region) return W.rawOf[region].alpha end
	function MP.n(W, region) return W.rawOf[region].calls.SetAlpha or 0 end
	-- The regions each part switches, made as the XML makes them, with the game's opacity of 1 unless one is given.
	function MP.world()
		local x = { p = {}, t = {}, f = {}, m = {}, pet = {}, tot = {}, seg = {} }
		MP.x = x
		local W = FH.ufWorld({ prep = function(Y)
			local U, env = Y.uf, Y.env
			Y.group = "extras"
			local function add(owner, key, kind, alpha)
				local made = U.region(owner, nil, "OVERLAY", 1, { kind = kind, alpha = alpha })
				Y.rawOf[owner][key] = made
				return made
			end
			local function frame(parent, key, name)
				local made = Y.B(parent, {}, { objectType = "Frame", name = name })
				if key then
					Y.rawOf[parent][key] = made
				end
				return made
			end
			local pc = env.PlayerFrame.PlayerFrameContent.PlayerFrameContentContextual
			x.p = { leader = add(pc, "LeaderIcon"), guide = add(pc, "GuideIcon"), attack = add(pc, "AttackIcon"), pvp = add(pc, "PVPIcon"), prestige = add(pc, "PrestigePortrait"),
				badge = add(pc, "PrestigeBadge"), role = add(pc, "RoleIcon") }
			local tc = env.TargetFrame.TargetFrameContent.TargetFrameContentContextual
			local box = env.TargetFrame.TargetFrameContent.TargetFrameContentMain.HealthBarsContainer
			x.t = { leader = add(tc, "LeaderIcon"), marker = add(tc, "RaidTargetIcon"), prestige = add(tc, "PrestigePortrait"), dead = add(box, "DeadText", "FontString", 0.2),
				unconscious = add(box, "UnconsciousText", "FontString") }
			local fc = env.FocusFrame.TargetFrameContent.TargetFrameContentContextual
			x.f = { leader = add(fc, "LeaderIcon"), marker = add(fc, "RaidTargetIcon") }
			x.tot = { dead = add(Y.tot.health, "DeadText", "FontString"), unconscious = add(Y.tot.health, "UnconsciousText", "FontString") }
			x.pet.happy = frame(nil, nil, "PetFrameHappiness")
			env.PetFrameHappiness = x.pet.happy
			-- Segments of the health bars: the unit frames' hang from the bar, the pet's are globals.
			for _, bar in ipairs({ { "player", Y.player.health }, { "target", Y.target.health } }) do
				local list = {}
				for _, key in ipairs({ "MyHealPredictionBar", "OtherHealPredictionBar", "HealAbsorbBar", "TotalAbsorbBar" }) do
					list[key] = frame(bar[2], key)
				end
				list.OverAbsorbGlow, list.OverHealAbsorbGlow = add(bar[2], "OverAbsorbGlow"), add(bar[2], "OverHealAbsorbGlow")
				x.seg[bar[1]] = list
			end
			x.seg.pet = {}
			for _, key in ipairs({ "MyHealPredictionBar", "OtherHealPredictionBar", "HealAbsorbBar", "TotalAbsorbBar" }) do
				x.seg.pet[key] = frame(nil, nil, "PetFrame" .. key)
				env["PetFrame" .. key] = x.seg.pet[key]
			end
			for _, key in ipairs({ "OverAbsorbGlow", "OverHealAbsorbGlow" }) do
				x.seg.pet[key] = U.region(Y.pet.frame, nil, "OVERLAY", 1, {})
				env["PetFrame" .. key] = x.seg.pet[key]
			end
		end })
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local M = W.members[1]
		local function add(owner, key)
			local made = W.uf.region(owner, nil, "OVERLAY", 1, {})
			W.rawOf[owner][key] = made
			return made
		end
		x.m = { leader = add(M.overlay, "LeaderIcon"), guide = add(M.overlay, "GuideIcon"), role = add(M.overlay, "RoleIcon") }
		W.uf.inRange = {}
		W.env.UnitInRange = function(unit) return W.uf.inRange[unit] end
		W.flush()
		return W
	end
	-- How many regions of the world are transparent.
	function MP.faded(W)
		local out, groups = 0, { MP.x.p, MP.x.t, MP.x.f, MP.x.m, MP.x.tot, MP.x.pet, MP.x.seg.player, MP.x.seg.target, MP.x.seg.pet }
		for _, group in ipairs(groups) do
			for _, region in pairs(group) do
				if W.rawOf[region].alpha == 0 then
					out = out + 1
				end
			end
		end
		return out
	end
	function MP.calls(W)
		local out, groups = 0, { MP.x.p, MP.x.t, MP.x.f, MP.x.m, MP.x.tot, MP.x.pet, MP.x.seg.player, MP.x.seg.target, MP.x.seg.pet }
		for _, group in ipairs(groups) do
			for _, region in pairs(group) do
				out = out + MP.n(W, region)
			end
		end
		return out
	end
	function MP.page(W, key)
		for _, page in ipairs(W.ns.PAGES) do
			for _, item in ipairs(page.key:sub(1, 10) == "unitframes" and page or {}) do
				if item.key == key then
					return page.key
				end
			end
		end
	end

	local W = MP.world()
	local x = MP.x
	local P, T, F, Pet, Tot, M = W.player, W.target, W.focus, W.pet, W.tot, W.members[1]

	-- The rows: the pages, the defaults and the choices.
	do
		local want = { leaderIcon = { true, "unitframesIcons" }, roleIcon = { true, "unitframesIcons" }, pvpIcon = { true, "unitframesIcons" }, raidMarker = { true, "unitframesIcons" },
			deadText = { true, "unitframesIcons" }, totemTimer = { true, "unitframesIcons" }, totemSwipe = { true, "unitframesIcons" }, combatIcon = { true, "unitframesPlayer" },
			petHappiness = { true, "unitframesPet" }, playerPowerBar = { true, "unitframesPlayer" }, targetPowerBar = { true, "unitframesTarget" }, focusPowerBar = { true, "unitframesFocus" },
			petPowerBar = { true, "unitframesPet" }, totPowerBar = { true, "unitframesTot" }, partyPowerBar = { true, "unitframesParty" }, bossPowerBar = { true, "unitframesBoss" },
			partyRangeDim = { false, "unitframesParty" }, partyRangeAlpha = { 50, "unitframesParty" }, raidRangeAlpha = { 50, "unitframesRaid" }, raidRoleIcon = { true, "unitframesRaid" },
			raidName = { true, "unitframesRaid" }, raidStatusText = { true, "unitframesRaid" }, healPrediction = { true, "unitframesBars" }, absorbShield = { true, "unitframesBars" },
			healAbsorb = { true, "unitframesBars" } }
		local wrong, count = {}, 0
		for key, pick in pairs(want) do
			count = count + 1
			if W.ns.Get("unitframes." .. key) ~= pick[1] or W.control("unitframes." .. key) == nil or MP.page(W, key) ~= pick[2] then
				wrong[#wrong + 1] = key .. "@" .. tostring(MP.page(W, key))
			end
		end
		check("ms-ufpart: the 25 rows are on their pages with their defaults", #wrong == 0 and count == 25, table.concat(wrong, " ") .. count)
		check("ms-ufpart: Out of range dimming needs the dimming row and Out of range opacity needs nothing", not W.enabled("unitframes.partyRangeAlpha") and W.enabled("unitframes.raidRangeAlpha"))
		local raid = {}
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == "unitframesRaid" then
				raid = page
			end
		end
		check("ms-ufpart: the raid page belongs to Unit frames and is called Raid frames", raid.parent == "unitframes" and raid.owner == "unitframes" and raid.label == "Raid frames")
	end

	-- Untouched: every row at its default makes no call on any region of the game.
	MP.bars = { P.power, T.power, F.power, Pet.power, Tot.power, M.power }
	MP.barCalls = 0
	for _, bar in ipairs(MP.bars) do
		MP.barCalls = MP.barCalls + MP.n(W, bar)
	end
	check("ms-ufpart: with every row at its default no icon, segment, bar or text of the game is touched and nothing is added", MP.calls(W) == 0 and MP.barCalls == 0 and MP.faded(W) == 0
		and MP.silent(W) and not has(W.status(), "Party range"), MP.calls(W) .. " " .. MP.why(W))

	-- Icons.
	W.change("unitframes.leaderIcon", false)
	check("ms-ufpart: Leader icon off makes the leader and guide icons of the player, target, focus and party frames transparent", MP.a(W, x.p.leader) == 0 and MP.a(W, x.p.guide) == 0
		and MP.a(W, x.t.leader) == 0 and MP.a(W, x.f.leader) == 0 and MP.a(W, x.m.leader) == 0 and MP.a(W, x.m.guide) == 0 and MP.faded(W) == 6, MP.faded(W))
	W.change("unitframes.leaderIcon", true)
	check("ms-ufpart: and it gives them their opacity back", MP.a(W, x.p.leader) == 1 and MP.a(W, x.m.guide) == 1 and MP.faded(W) == 0 and MP.silent(W), MP.why(W))
	W.change("unitframes.roleIcon", false)
	check("ms-ufpart: Role icon on party frames off makes the role icon of a party member transparent and no other", MP.a(W, x.m.role) == 0 and MP.a(W, x.p.role) == 1 and MP.faded(W) == 1)
	W.change("unitframes.roleIcon", true)
	W.change("unitframes.raidMarker", false)
	check("ms-ufpart: Raid marker off makes the marker of the target and focus frames transparent and no other icon", MP.a(W, x.t.marker) == 0 and MP.a(W, x.f.marker) == 0 and MP.faded(W) == 2)
	W.change("unitframes.raidMarker", true)
	W.change("unitframes.combatIcon", false)
	check("ms-ufpart: Combat icon off makes the attack icon of the player transparent", MP.a(W, x.p.attack) == 0 and MP.faded(W) == 1)
	W.change("unitframes.combatIcon", true)
	W.change("unitframes.petHappiness", false)
	check("ms-ufpart: Happiness face off makes the face of the pet transparent", MP.a(W, x.pet.happy) == 0 and MP.faded(W) == 1)
	W.change("unitframes.petHappiness", true)
	check("ms-ufpart: Happiness face on again gives it back", MP.a(W, x.pet.happy) == 1 and MP.faded(W) == 0)
	W.change("unitframes.deadText", false)
	check("ms-ufpart: Dead text off makes the dead and unconscious texts of the target and of the target of target transparent", MP.a(W, x.t.dead) == 0 and MP.a(W, x.t.unconscious) == 0
		and MP.a(W, x.tot.dead) == 0 and MP.a(W, x.tot.unconscious) == 0 and MP.faded(W) == 4, MP.faded(W))
	W.change("unitframes.deadText", true)
	check("ms-ufpart: Dead text on again gives each text the opacity the game had put on it", MP.a(W, x.t.dead) == 0.2 and MP.a(W, x.t.unconscious) == 1 and MP.a(W, x.tot.dead) == 1)
	W.change("unitframes.pvpIcon", false)
	check("ms-ufpart: PvP icon off makes the PvP icon and the prestige art of the player and target frames transparent", MP.a(W, x.p.pvp) == 0 and MP.a(W, x.p.prestige) == 0
		and MP.a(W, x.p.badge) == 0 and MP.a(W, x.t.prestige) == 0 and MP.faded(W) == 4, MP.faded(W))
	W.change("unitframes.pvpIcon", true)
	check("ms-ufpart: and it gives them back", MP.faded(W) == 0 and MP.silent(W), MP.why(W))
	-- Power bars.
	MP.power = { { "playerPowerBar", P.power }, { "targetPowerBar", T.power }, { "focusPowerBar", F.power }, { "petPowerBar", Pet.power }, { "totPowerBar", Tot.power },
		{ "partyPowerBar", M.power } }
	-- The frame the border of a bar follows: the bar, or the frame of the addon's own that spans the part that shows.
	function MP.st(bar)
		local frame = bar
		if not W.holderOn(bar) then
			for _, f in ipairs(W.addonFrames) do
				for _, p in ipairs(f.points) do
					if p[2] == bar and W.holderOn(f) then
						frame = f
					end
					-- With the width of the health bar the span hangs from corner frames, which hang from the bar.
					for _, corner in ipairs(W.addonFrames) do
						for _, q in ipairs(corner.points) do
							if p[2] == corner and q[2] == bar and W.holderOn(f) then
								frame = f
							end
						end
					end
				end
			end
		end
		return W.state(frame)
	end
	check("ms-ufpart: the power bars have a border and a background by default", MP.st(P.power) == "SB" and MP.st(T.power) == "SB" and MP.st(M.power) == "SB", MP.st(P.power) .. MP.st(M.power))
	for _, row in ipairs(MP.power) do
		W.change("unitframes." .. row[1], false)
		MP.off = { MP.a(W, row[2]), MP.st(row[2]) }
		MP.others = 0
		for _, other in ipairs(MP.power) do
			if other[2] ~= row[2] and (MP.a(W, other[2]) ~= 1 or MP.st(other[2]) ~= "SB") then
				MP.others = MP.others + 1
			end
		end
		W.change("unitframes." .. row[1], true)
		check("ms-ufpart: " .. row[1] .. " off makes that bar transparent with no border and no background and leaves the other bars, and on gives them back",
			MP.off[1] == 0 and MP.off[2] == "hb" and MP.others == 0 and MP.a(W, row[2]) == 1 and MP.st(row[2]) == "SB" and MP.silent(W), row[1] .. " " .. tostring(MP.off[1]) .. MP.off[2] .. MP.others .. MP.why(W))
	end
	W.change("unitframes.petPowerBar", false)
	W.change("unitframes.pet", false)
	MP.pet = MP.a(W, Pet.power)
	W.change("unitframes.pet", true)
	check("ms-ufpart: a frame that is not restyled keeps its power bar, and it goes when the frame is restyled again", MP.pet == 1 and MP.a(W, Pet.power) == 0, tostring(MP.pet) .. tostring(MP.a(W, Pet.power)))
	W.change("unitframes.petPowerBar", true)

	-- Hide empty power bar: a plain maximum of 0 makes the bar transparent with no border and no background, a withheld maximum leaves it.
	do
		local E = { max = {} }
		W.env.UnitPowerMax = function(unit)
			local v = E.max[unit]
			if v == nil then
				return 100
			end
			return v
		end
		function E.shown(bar) return MP.a(W, bar) == 1 and MP.st(bar) == "SB" end
		function E.hidden(bar) return MP.a(W, bar) == 0 and MP.st(bar) == "hb" end
		W.fire("UNIT_MAXPOWER", "target")
		check("empty power: the setting is On by default and a unit with power keeps its bar", W.ns.Get("unitframes.hideEmptyPower") == true and E.shown(T.power) and E.shown(Tot.power) and MP.silent(W), MP.why(W))
		E.max.target = 0
		W.fire("UNIT_MAXPOWER", "target")
		check("empty power: a plain maximum of 0 hides the fill, the border and the background of that bar and no other", E.hidden(T.power) and E.shown(Tot.power) and E.shown(P.power) and MP.silent(W), MP.a(W, T.power) .. MP.st(T.power) .. MP.why(W))
		E.max.target = 100
		W.fire("UNIT_MAXPOWER", "target")
		check("empty power: a later maximum above 0 shows them again", E.shown(T.power) and MP.silent(W), MP.a(W, T.power) .. MP.st(T.power))
		E.max.target = SECRET
		W.fire("UNIT_MAXPOWER", "target")
		check("empty power: a withheld maximum keeps the bar shown", E.shown(T.power) and MP.silent(W), MP.a(W, T.power) .. MP.st(T.power) .. MP.why(W))
		E.max.target = 0
		W.fire("UNIT_MAXPOWER", SECRET)
		check("empty power: an event for a withheld unit looks at every frame", E.hidden(T.power) and E.shown(Tot.power), MP.a(W, T.power) .. MP.st(T.power))
		W.change("unitframes.hideEmptyPower", false)
		check("empty power: with the setting Off an empty bar shows", E.shown(T.power) and MP.silent(W), MP.a(W, T.power) .. MP.st(T.power))
		W.change("unitframes.hideEmptyPower", true)
		check("empty power: and On again it hides", E.hidden(T.power), MP.a(W, T.power) .. MP.st(T.power))
		E.max.target = nil
		E.max.targettarget = 0
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("empty power: a new target looks at every frame, so the target of target bar hides and the target bar shows", E.hidden(Tot.power) and E.shown(T.power) and MP.silent(W), MP.a(W, Tot.power) .. MP.st(Tot.power) .. MP.why(W))
		E.max.targettarget = nil
		W.fire("UNIT_MAXPOWER", "targettarget")
		W.change("unitframes.totPowerBar", false)
		W.change("unitframes.totPowerBar", true)
		check("empty power: Power bar off then on leaves a bar with power shown", E.shown(Tot.power), MP.a(W, Tot.power) .. MP.st(Tot.power))
		W.env.UnitPowerMax = nil
	end

	-- Heal prediction and shields.
	for _, row in ipairs({ { "healPrediction", "MyHealPredictionBar", "OtherHealPredictionBar" }, { "absorbShield", "TotalAbsorbBar", "OverAbsorbGlow" },
		{ "healAbsorb", "HealAbsorbBar", "OverHealAbsorbGlow" } }) do
		W.change("unitframes." .. row[1], false)
		MP.wrong, MP.count = 0, 0
		for _, kind in ipairs({ "player", "target", "pet" }) do
			for key, region in pairs(x.seg[kind]) do
				local mine = key == row[2] or key == row[3]
				MP.count = MP.count + (mine and 1 or 0)
				if (W.rawOf[region].alpha == 0) ~= mine then
					MP.wrong = MP.wrong + 1
				end
			end
		end
		W.change("unitframes." .. row[1], true)
		check("ms-ufpart: " .. row[1] .. " off makes its segments and glow transparent on the player, target and pet frames and no other segment, and on gives them back",
			MP.wrong == 0 and MP.count == 6 and MP.faded(W) == 0 and MP.silent(W), row[1] .. " " .. MP.wrong .. " " .. MP.count .. MP.why(W))
	end

	-- The PvP flag: the icon goes and the word stays.
	W.uf.pvp.player, W.uf.pvp.target, W.uf.pvp.party1 = "faction", "faction", "faction"
	W.blizzard(W.env.PlayerFrame_UpdatePvPStatus)
	W.blizzard(function() T.frame:CheckFaction() end)
	W.blizzard(function() M.frame:UpdatePvPStatus() end)
	MP.row = FH.kindRow(W, P.frame)
	check("ms-ufpart: with every row at its default the plate and the icon are the game's and the word is in the row", MP.a(W, P.pvp) == 1 and MP.a(W, P.pvpIcon) == 1 and MP.a(W, M.pvpIcon) == 1
		and MP.row.flag.shown, tostring(MP.a(W, P.pvp)))
	W.change("unitframes.pvpIcon", false)
	check("ms-ufpart: PvP icon off with the flag Both makes the plate and the icon of the player, target and party frames transparent and keeps the word", MP.a(W, P.pvp) == 0
		and MP.a(W, P.pvpIcon) == 0 and MP.a(W, T.pvpIcon) == 0 and MP.a(W, M.pvpIcon) == 0 and MP.row.flag.shown and MP.row.flag.text == "PvP", tostring(MP.row.flag.text))
	FH.pvp(W, "unitframes.pvpFlag", "icon")
	check("ms-ufpart: and with the flag Icon on the portrait it leaves nothing", MP.a(W, P.pvp) == 0 and MP.a(W, P.pvpIcon) == 0 and not MP.row.flag.shown)
	FH.pvp(W, "unitframes.pvpFlag", "word")
	check("ms-ufpart: and with the flag Word in the name row it is the word alone, as before", MP.a(W, P.pvp) == 0 and MP.row.flag.shown)
	FH.pvp(W, "unitframes.pvpFlag", "off")
	check("ms-ufpart: and Off is off", MP.a(W, P.pvp) == 0 and not MP.row.flag.shown and MP.a(W, M.pvpIcon) == 0)
	FH.pvp(W, "unitframes.pvpFlag", "both")
	W.change("unitframes.pvpIcon", true)
	check("ms-ufpart: PvP icon on again gives the game's plate, icon and the word", MP.a(W, P.pvp) == 1 and MP.a(W, P.pvpIcon) == 1 and MP.a(W, M.pvpIcon) == 1 and MP.row.flag.shown and MP.silent(W), MP.why(W))
	W.change("unitframes.pvpIcon", false)
	W.change("unitframes.target", false)
	check("ms-ufpart: a frame that is not restyled keeps the game's PvP icon whatever the row says", MP.a(W, T.pvpIcon) == 1 and MP.a(W, P.pvpIcon) == 0, tostring(MP.a(W, T.pvpIcon)))
	W.change("unitframes.target", true)
	W.change("unitframes.pvpIcon", true)
	W.change("unitframes.squarePortrait", false)
	W.change("unitframes.pvpIcon", false)
	check("ms-ufpart: PvP icon off hides the game's icon on a frame that shows the game's portrait as well", MP.a(W, P.pvp) == 0 and MP.a(W, P.pvpIcon) == 0)
	W.change("unitframes.pvpIcon", true)
	W.change("unitframes.squarePortrait", true)
	check("ms-ufpart: and gives it back", MP.a(W, P.pvp) == 1 and MP.a(W, P.pvpIcon) == 1)
	W.uf.pvp.player, W.uf.pvp.target, W.uf.pvp.party1 = nil, nil, nil
	W.blizzard(W.env.PlayerFrame_UpdatePvPStatus)

	-- Party range: a layer of the addon's own, darkened by the game's answer about range.
	function MP.layer()
		for _, f in ipairs(W.addonFrames) do
			if f.parent == M.frame and f.onUpdate then
				return f
			end
		end
	end
	W.change("unitframes.partyRangeDim", true)
	MP.box = MP.layer()
	MP.shade = MP.box and MP.box.regions[1]
	check("ms-ufpart: Dim members out of range makes a frame of the addon's own over the member with one black texture and a timer, and the status says what it dims",
		MP.box ~= nil and MP.box.shown and #MP.box.regions == 1 and MP.shade.kind == "Texture" and table.concat(MP.shade.color or {}, ",") == "0,0,0,1" and has(W.status(), "Party range: a member out of range and a member whose range the game does not report are both dimmed"),
		tostring(MP.box) .. W.status():sub(-300))
	check("ms-ufpart: a client whose textures cannot set an opacity from an answer dims nothing and says so", MP.shade.alpha == 0 and has(W.status(), "Party range: this client cannot set an opacity from an answer about range"), tostring(MP.shade.alpha))
	W.change("unitframes.partyRangeDim", false)
	check("ms-ufpart: with the row off the line about a client that cannot dim goes too", not has(W.status(), "Party range"), W.status():sub(-300))
	W.change("unitframes.partyRangeDim", true)
	MP.shade.SetAlphaFromBoolean = function(_, value, yes, no)
		MP.handed = value
		local pick = value
		if rawequal(value, SECRET) then
			pick = W.secretTruth == true
		end
		MP.shade.alpha = pick and yes or no
	end
	function MP.look(answer, secret)
		W.uf.inRange.party1 = answer
		W.secretTruth = secret
		MP.box.onUpdate(MP.box, 0.1)
		MP.box.onUpdate(MP.box, 0.2)
		W.secretTruth = false
		return MP.shade.alpha
	end
	check("ms-ufpart: a member in range has a clear layer and a member out of range a layer half dark", MP.look(true) == 0 and MP.look(false) == 0.5, tostring(MP.shade.alpha))
	MP.waited = MP.shade.alpha
	MP.box.onUpdate(MP.box, 0.1)
	W.uf.inRange.party1 = true
	MP.box.onUpdate(MP.box, 0.1)
	check("ms-ufpart: the layer looks at range every quarter of a second and not between", MP.shade.alpha == MP.waited, tostring(MP.shade.alpha))
	W.change("unitframes.partyRangeAlpha", 70)
	check("ms-ufpart: Out of range dimming sets how dark the layer is", MP.look(false) == 0.7, tostring(MP.shade.alpha))
	W.change("unitframes.partyRangeAlpha", 50)
	check("ms-ufpart: a withheld answer is handed on and never tested: the layer is as dark as the game's answer says", MP.look(SECRET, true) == 0 and rawequal(MP.handed, SECRET) and MP.look(SECRET, false) == 0.5, tostring(MP.shade.alpha))
	check("ms-ufpart: a unit that answers nothing is not dimmed", MP.look(nil) == 0)
	W.change("unitframes.partyRangeDim", false)
	check("ms-ufpart: Dim members out of range off hides the layer and the status line goes", not MP.box.shown and not has(W.status(), "Party range") and MP.silent(W), W.status():sub(-200))
	W.change("unitframes.partyRangeDim", true)
	check("ms-ufpart: and on again shows the same layer, not another", MP.box.shown and MP.layer() == MP.box and has(W.status(), "Party range"))
	W.change("unitframes.partyRangeDim", false)
	-- The layer of a party member is made out of combat.
	do
		local N = MP.world()
		local member = N.members[1]
		function MP.layers()
			local out = 0
			for _, f in ipairs(N.addonFrames) do
				if f.parent == member.frame and f.onUpdate then
					out = out + 1
				end
			end
			return out
		end
		N.combat = true
		N.change("unitframes.partyRangeDim", true)
		MP.during = MP.layers()
		N.combat = false
		N.fire("PLAYER_REGEN_ENABLED")
		N.flush()
		check("ms-ufpart: the layer of a party member waits for the end of combat and is made once", MP.during == 0 and MP.layers() == 1 and #N.violations == 0 and #N.errors == 0, MP.during .. " " .. MP.layers() .. table.concat(N.violations, "|"))
	end

	-- A refused change of opacity stops the part, gives back what it changed and says so, with no error.
	do
		local N = MP.world()
		local nx = MP.x
		N.rawOf[nx.p.guide].SetAlpha = function() error("refused", 0) end
		N.change("unitframes.combatIcon", false)
		MP.before = N.rawOf[nx.p.attack].alpha
		N.change("unitframes.leaderIcon", false)
		MP.after = MP.faded(N)
		N.change("unitframes.raidMarker", false)
		check("ms-ufpart: a region that refuses a change of opacity stops the part: what it had made transparent is back, later rows do nothing, the status says so and nothing raises",
			MP.before == 0 and MP.after == 0 and MP.faded(N) == 0 and #N.errors == 0 and #N.violations == 0 and has(N.status(), "Unit frames: Frame icons stopped. The game refused a change of opacity"),
			tostring(MP.before) .. " " .. MP.after .. " " .. MP.faded(N) .. table.concat(N.errors, "|") .. N.status():sub(-300))
		N.change("unitframes.playerPowerBar", false)
		check("ms-ufpart: the other parts go on", N.rawOf[N.player.power].alpha == 0)
	end

	-- Raid frames, the boss frame and the totem buttons, in the world that has them.
	do
		MP.X = FH.xWorld({ prep = function(Y)
			local env, V = Y.W.env, Y.W
			V.group = "extras"
			-- The game gives a raid frame its opacity from its answer about range, and draws its parts again with its updates (CompactUnitFrame.lua:1519, 1066).
			env.CompactUnitFrame_UpdateCenterStatusIcon = function(frame)
				local out = frame.outOfRange
				if rawequal(out, SECRET) then
					out = V.secretTruth == true
				end
				frame:SetAlpha(out and 0.5 or 1)
			end
			env.CompactUnitFrame_UpdateName = function(frame) frame.name:SetAlpha(1) end
			env.CompactUnitFrame_UpdateStatusText = function(frame) frame.statusText:SetAlpha(1) end
			env.CompactUnitFrame_UpdateRoleIcon = function(frame) frame.roleIcon:SetAlpha(1) end
			env.CompactUnitFrame_UpdateHealPrediction = function(frame)
				for _, key in ipairs({ "myHealPrediction", "otherHealPrediction", "totalAbsorb", "totalAbsorbOverlay", "overAbsorbGlow", "myHealAbsorb", "myHealAbsorbLeftShadow",
					"myHealAbsorbRightShadow", "overHealAbsorbGlow" }) do
					frame[key]:SetAlpha(1)
				end
			end
			-- The time left on a totem and its swipe.
			MP.duration = V.Rr(Y.totem.button, nil, { layer = "OVERLAY", sublevel = 0, kind = "FontString" })
			V.rawOf[Y.totem.button].Duration = MP.duration
			-- TotemButtonMixin:OnUpdate calls AuraButtonMixin.UpdateDuration, which colours the time with three numbers (Blizzard_BuffFrame/BuffFrame.lua:1387-1400).
			MP.totemButton = Y.totem.button
			env.AuraButtonMixin = { UpdateDuration = function(button) button.Duration:SetVertexColor(1, 1, 1) end }
			MP.swipe = V.B(Y.totem.icon, {}, { objectType = "Frame" })
			V.rawOf[Y.totem.icon].Cooldown = MP.swipe
		end })
		local X = MP.X
		local V = X.W
		local R = X.raidFrame("CompactRaidGroup1Member1", "raid", nil, { unit = "raid1" })
		local function part(key, kind, alpha)
			local made = V.Rr(R.frame, nil, { layer = "OVERLAY", sublevel = 0, kind = kind, alpha = alpha })
			V.rawOf[R.frame][key] = made
			return made
		end
		R.role, R.name, R.status = part("roleIcon"), part("name", "FontString"), part("statusText", "FontString")
		R.seg = {}
		for _, key in ipairs({ "myHealPrediction", "otherHealPrediction", "totalAbsorb", "totalAbsorbOverlay", "overAbsorbGlow", "myHealAbsorb", "myHealAbsorbOverlay", "myHealAbsorbLeftShadow",
			"myHealAbsorbRightShadow", "overHealAbsorbGlow" }) do
			R.seg[key] = part(key, nil, key == "myHealAbsorbOverlay" and 0.2 or nil)
		end
		MP.fb = {}
		V.rawOf[R.frame].SetAlphaFromBoolean = function(_, value, yes, no)
			MP.fb[#MP.fb + 1] = value
			if MP.refuse then
				error("refused", 0)
			end
			local pick = value
			if rawequal(value, SECRET) then
				pick = V.secretTruth == true
			end
			V.rawOf[R.frame].alpha = pick and yes or no
		end
		V.blizzard(function() V.env.CompactUnitFrame_SetUpFrame(R.frame) end)
		X.update(R)
		function MP.game(name) V.blizzard(function() V.env[name](R.frame) end) end
		function MP.calls2()
			local out = 0
			for _, region in ipairs({ R.role, R.name, R.status }) do
				out = out + (V.rawOf[region].calls.SetAlpha or 0)
			end
			for _, region in pairs(R.seg) do
				out = out + (V.rawOf[region].calls.SetAlpha or 0)
			end
			return out
		end
		function MP.fadedRaid()
			local out = 0
			for _, region in ipairs({ R.role, R.name, R.status }) do
				out = out + (V.rawOf[region].alpha == 0 and 1 or 0)
			end
			for _, region in pairs(R.seg) do
				out = out + (V.rawOf[region].alpha == 0 and 1 or 0)
			end
			return out
		end
		function MP.alpha() return V.rawOf[R.frame].alpha end
		MP.game("CompactUnitFrame_UpdateName")
		MP.game("CompactUnitFrame_UpdateHealPrediction")
		-- The game's own calls are not counted: only the ones the addon makes while the game sets the frame up and updates it again.
		for _, region in ipairs({ R.role, R.name, R.status }) do
			V.rawOf[region].calls.SetAlpha = nil
		end
		for _, region in pairs(R.seg) do
			V.rawOf[region].calls.SetAlpha = nil
		end
		V.blizzard(function() V.env.CompactUnitFrame_SetUpFrame(R.frame) end)
		V.blizzard(function() V.env.CompactUnitFrame_UpdateAll(R.frame) end)
		X.update(R)
		MP.base = MP.calls2()
		check("ms-ufpart: a raid frame at its defaults has no part, segment or opacity touched", MP.base == 0 and #MP.fb == 0 and MP.fadedRaid() == 0 and MP.silent(V), MP.base .. " " .. #MP.fb .. MP.why(V))

		V.change("unitframes.raidRoleIcon", false)
		check("ms-ufpart: Role icon off makes the role icon of a raid frame transparent", V.rawOf[R.role].alpha == 0 and MP.fadedRaid() == 1)
		V.change("unitframes.raidRoleIcon", true)
		V.change("unitframes.raidName", false)
		check("ms-ufpart: Name off makes the name of a raid frame transparent", V.rawOf[R.name].alpha == 0 and MP.fadedRaid() == 1)
		V.change("unitframes.raidName", true)
		V.change("unitframes.raidStatusText", false)
		check("ms-ufpart: Status text off makes the status text of a raid frame transparent", V.rawOf[R.status].alpha == 0 and MP.fadedRaid() == 1)
		V.change("unitframes.raidRoleIcon", false)
		V.change("unitframes.raidName", false)
		check("ms-ufpart: all three off make all three transparent", V.rawOf[R.role].alpha == 0 and V.rawOf[R.name].alpha == 0 and V.rawOf[R.status].alpha == 0 and MP.fadedRaid() == 3)
		MP.game("CompactUnitFrame_UpdateName")
		MP.game("CompactUnitFrame_UpdateStatusText")
		MP.game("CompactUnitFrame_UpdateRoleIcon")
		check("ms-ufpart: the game drawing them again does not bring them back", V.rawOf[R.role].alpha == 0 and V.rawOf[R.name].alpha == 0 and V.rawOf[R.status].alpha == 0, MP.fadedRaid())
		V.blizzard(function() V.env.CompactUnitFrame_UpdateAll(R.frame) end)
		check("ms-ufpart: nor does a full update", MP.fadedRaid() == 3 and MP.silent(V), MP.why(V))
		V.change("unitframes.raidRoleIcon", true)
		V.change("unitframes.raidName", true)
		V.change("unitframes.raidStatusText", true)
		check("ms-ufpart: all three on again give them back", MP.fadedRaid() == 0 and V.rawOf[R.name].alpha == 1)

		V.change("unitframes.healPrediction", false)
		MP.game("CompactUnitFrame_UpdateHealPrediction")
		check("ms-ufpart: Incoming heals off makes the two prediction textures of a raid frame transparent, also after the game draws them", V.rawOf[R.seg.myHealPrediction].alpha == 0
			and V.rawOf[R.seg.otherHealPrediction].alpha == 0 and MP.fadedRaid() == 2, MP.fadedRaid())
		V.change("unitframes.healPrediction", true)
		V.change("unitframes.absorbShield", false)
		check("ms-ufpart: Absorb shields off makes the shield, its overlay and its glow transparent", V.rawOf[R.seg.totalAbsorb].alpha == 0 and V.rawOf[R.seg.totalAbsorbOverlay].alpha == 0
			and V.rawOf[R.seg.overAbsorbGlow].alpha == 0 and MP.fadedRaid() == 3, MP.fadedRaid())
		V.change("unitframes.absorbShield", true)
		V.change("unitframes.healAbsorb", false)
		check("ms-ufpart: Heal absorbs off makes the heal absorb, its overlay, its two shadows and its glow transparent", V.rawOf[R.seg.myHealAbsorb].alpha == 0 and V.rawOf[R.seg.myHealAbsorbOverlay].alpha == 0
			and V.rawOf[R.seg.myHealAbsorbLeftShadow].alpha == 0 and V.rawOf[R.seg.myHealAbsorbRightShadow].alpha == 0 and V.rawOf[R.seg.overHealAbsorbGlow].alpha == 0 and MP.fadedRaid() == 5, MP.fadedRaid())
		V.change("unitframes.healAbsorb", true)
		check("ms-ufpart: and on again gives each the opacity it had, the overlay's 0.2 included", MP.fadedRaid() == 0 and V.rawOf[R.seg.myHealAbsorbOverlay].alpha == 0.2 and V.rawOf[R.seg.myHealAbsorb].alpha == 1)

		-- Range.
		V.rawOf[R.frame].outOfRange = true
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		check("ms-ufpart: at 50% the game's own opacity is untouched and nothing is called", MP.alpha() == 0.5 and #MP.fb == 0, MP.alpha() .. " " .. #MP.fb)
		V.change("unitframes.raidRangeAlpha", 30)
		check("ms-ufpart: Out of range opacity gives a frame out of range that opacity, set from the game's answer", MP.alpha() == 0.3 and MP.fb[#MP.fb] == true, tostring(MP.alpha()))
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		check("ms-ufpart: and the game setting the opacity again does not change it", MP.alpha() == 0.3)
		V.rawOf[R.frame].outOfRange = false
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		check("ms-ufpart: a frame in range is at 100%", MP.alpha() == 1)
		V.rawOf[R.frame].outOfRange = SECRET
		V.secretTruth = true
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		V.secretTruth = false
		check("ms-ufpart: a withheld answer is handed on as it is and the frame has the opacity it says", rawequal(MP.fb[#MP.fb], SECRET) and MP.alpha() == 0.3, tostring(MP.alpha()))
		V.rawOf[R.frame].outOfRange = nil
		MP.count = #MP.fb
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		check("ms-ufpart: a frame the game has not asked about range is not touched", #MP.fb == MP.count and MP.alpha() == 1, #MP.fb .. " " .. MP.count)
		V.rawOf[R.frame].outOfRange = true
		V.change("unitframes.raidRangeAlpha", 100)
		check("ms-ufpart: 100% keeps a frame out of range fully visible", MP.alpha() == 1, tostring(MP.alpha()))
		V.change("unitframes.raidRangeAlpha", 50)
		check("ms-ufpart: back at 50% a frame out of range has the game's 50% again, from the same answer", MP.alpha() == 0.5, tostring(MP.alpha()))
		V.change("unitframes.raidRangeAlpha", 30)
		V.change("unitframes.raid", false)
		MP.off = MP.alpha()
		V.change("unitframes.raid", true)
		check("ms-ufpart: a raid frame that is not restyled has the game's opacity, and the row's again when it is restyled", MP.off == 0.5 and MP.alpha() == 0.3, tostring(MP.off) .. " " .. tostring(MP.alpha()))
		V.change("unitframes.raidRangeAlpha", 50)
		MP.count = #MP.fb
		MP.game("CompactUnitFrame_UpdateCenterStatusIcon")
		V.change("unitframes.raidRangeAlpha", 50)
		check("ms-ufpart: and then nothing is called again", #MP.fb == MP.count and MP.silent(V), #MP.fb .. " " .. MP.count)
		MP.refuse = true
		V.change("unitframes.raidRangeAlpha", 30)
		MP.refuse = false
		check("ms-ufpart: a game that refuses to set the opacity from the answer says so and raises nothing", has(V.status(), "Unit frames: Raid range: the game refused to set the opacity of a raid frame") and #V.errors == 0 and #V.violations == 0,
			V.status():sub(-300))
		V.change("unitframes.raidRangeAlpha", 50)

		-- Totem buttons.
		V.blizzard(function() V.env.TotemFrame:Update() end)
		MP.dur, MP.cool = V.rawOf[MP.duration], V.rawOf[MP.swipe]
		check("ms-ufpart: the time left and the swipe of a totem are untouched at the defaults", (MP.dur.calls.SetAlpha or 0) == 0 and (MP.cool.calls.SetAlpha or 0) == 0 and MP.silent(V))
		V.change("unitframes.totemTimer", false)
		check("ms-ufpart: Totem time left off makes the time transparent and leaves the swipe", MP.dur.alpha == 0 and (MP.cool.calls.SetAlpha or 0) == 0, tostring(MP.dur.alpha))
		MP.dur.alpha = 1
		V.blizzard(function() V.env.AuraButtonMixin.UpdateDuration(MP.totemButton, 5) end)
		check("ms-ufpart: the game colouring the time again on its tick does not bring it back", MP.dur.alpha == 0, tostring(MP.dur.alpha))
		V.change("unitframes.totemTimer", true)
		MP.dur.alpha = 0.6
		V.blizzard(function() V.env.AuraButtonMixin.UpdateDuration(MP.totemButton, 5) end)
		check("hkunit: totem timer: no hook on the text of the time or on the button, and the function of AuraButtonMixin is followed", not INSTHOOK.wrapped(V, MP.duration, "SetVertexColor")
			and not INSTHOOK.wrapped(V, MP.totemButton, "Update") and INSTHOOK.wrapped(V, V.env.AuraButtonMixin, "UpdateDuration") and MP.silent(V))
		check("ms-ufpart: Totem time left on gives it back and the colouring no longer changes it", MP.dur.alpha == 0.6 or MP.dur.alpha == 1, tostring(MP.dur.alpha))
		V.change("unitframes.totemSwipe", false)
		check("ms-ufpart: Totem cooldown swipe off makes the swipe transparent", MP.cool.alpha == 0 and MP.dur.alpha ~= 0, tostring(MP.cool.alpha))
		MP.cool.alpha = 1
		V.blizzard(function() V.env.TotemFrame:Update() end)
		check("ms-ufpart: the game updating the totems again does not bring the swipe back", MP.cool.alpha == 0, tostring(MP.cool.alpha))
		V.env.TotemFrame.totemPool.items[1] = nil
		V.change("unitframes.totemSwipe", true)
		check("ms-ufpart: Totem cooldown swipe on gives it back, on a button the game has released as well", MP.cool.alpha == 1 and MP.silent(V), tostring(MP.cool.alpha))

		-- The boss frame has its own power bar row.
		V.change("unitframes.bossPowerBar", false)
		check("ms-ufpart: Power bar off on the boss frames makes the bar transparent and not the target's", V.rawOf[X.boss.power].alpha == 0 and (V.rawOf[X.target.power].calls.SetAlpha or 0) == 0)
		V.change("unitframes.bossPowerBar", true)
		check("ms-ufpart: and on gives it back", V.rawOf[X.boss.power].alpha == 1 and MP.silent(V))
	end
end
-- >>> ms-13 unit frame parts (end)
-- >>> partycd (begin)
-- Party cooldowns and the timers, listeners and counters of Tracking.lua that it uses. The helpers are on TOC.pc, so that this file gains no local.
do
	local PC = {}
	TOC.pc = PC
	PC.guid = { "Player-1-0011", "Player-1-0012", "Player-1-0013", "Player-1-0014" }
	-- A world with trackers, the party frames of the game and a party: o.party is a list of { class, race }, o.opts is added to the options of the
	-- world, o.setup(W) runs before the login. W.pc.frames are the member buttons (protected, as the game's are).
	function PC.world(o)
		o = o or {}
		local opts = { trackers = { partycd = true } }
		for k, v in pairs(o.opts or {}) do
			opts[k] = v
		end
		local W = newWorld(opts)
		W.au.unit.player = { guid = "Player-1-0001", player = true, class = o.class or "SHAMAN", race = "Troll", name = "Mine" }
		W.au.group = o.group ~= false
		local frames = {}
		for index, who in ipairs(o.party or { { "MAGE", "Human" }, { "WARRIOR", "Dwarf" }, { "PRIEST", "Human" } }) do
			local unit = "party" .. index
			W.au.unit[unit] = { guid = PC.guid[index], player = true, class = who[1], race = who[2], name = "Mate" .. index }
			frames[index] = (W.B(nil, { unit = unit }, { protected = true, objectType = "Button", name = "PartyMemberFrame" .. index, width = 120, height = 53 }))
		end
		-- The game makes four member frames whatever the size of the party and hides those with no member (PartyFrame.lua:54-65).
		for index = 1, 4 do
			if not frames[index] then
				frames[index] = (W.B(nil, { unit = "party" .. index }, { protected = true, objectType = "Button", name = "PartyMemberFrame" .. index, width = 120, height = 53 }))
			end
			W.rawOf[frames[index]].shown = W.au.unit["party" .. index] ~= nil
		end
		W.pc = { frames = frames }
		W.env.PartyFrame = { PartyMemberFramePool = { EnumerateActive = function()
			local index, list = 0, W.pc.frames
			return function()
				index = index + 1
				return list[index]
			end
		end } }
		if o.setup then
			o.setup(W)
		end
		W.login()
		W.flush()
		return W
	end
	function PC.mod(W)
		return W.ns.PartyCooldownsModule
	end
	-- The hooks a world of the same kind has with the module off.
	function PC.baseHooks()
		local B = PC.world({ opts = { saved = { options = { ["partycd.enabled"] = false } } } })
		return B.hooks
	end
	function PC.row(W, owner)
		return PC.mod(W).assigned[owner]
	end
	-- The keys of the abilities a row shows, in its slots.
	function PC.keys(W, row)
		local out = {}
		for _, icon in ipairs(row and row.icons or {}) do
			if W.rawOf[icon.frame].shown == true and icon.key then
				out[#out + 1] = icon.key
			end
		end
		return table.concat(out, ",")
	end
	function PC.sweep(W, row, slot)
		return W.rawOf[row.icons[slot].cooldown].cd.sweep
	end
	function PC.ok(W)
		return #W.violations == 0 and #W.errors == 0 and not has(W.status(), "stopped")
	end
	function PC.why(W)
		return table.concat(W.violations, " | "):sub(1, 200) .. " || " .. table.concat(W.errors, " | "):sub(1, 200) .. " || " .. W.status():sub(1, 300)
	end
	function PC.cast(W, unit, spell)
		W.fireUnit("UNIT_SPELLCAST_SUCCEEDED", unit, "Cast-3-1-1-" .. spell, spell)
	end
	function PC.point(W, holder)
		local p = W.rawOf[holder].points[1]
		return p and (p[1] .. ">" .. tostring(p[3]) .. ":" .. tostring(p[4]) .. "," .. tostring(p[5])) or "none"
	end
end
do
	local PC = TOC.pc
	-- The timers, the 1 second rule, categories, resets and the cap of players.
	local W = PC.world()
	local T = W.ns.Tracking
	local MAGE, WARRIOR = PC.guid[1], PC.guid[2]
	local t0 = W.now
	PC.cast(W, "party1", 2139)
	local start, length = T.Timer(MAGE, "MAGE:Counterspell")
	check("cdtrack: a plain cast of a party member starts the timer of its ability, in the numbers of GetTime", start == t0 and length == 30, tostring(start) .. " " .. tostring(length))
	W.advance(0.5)
	PC.cast(W, "party1", 2139)
	check("cdtrack: a use reported twice within a second is one timer", T.Timer(MAGE, "MAGE:Counterspell") == t0)
	W.advance(1)
	PC.cast(W, "party1", 2139)
	check("cdtrack: a use reported after a second is a new use", T.Timer(MAGE, "MAGE:Counterspell") == t0 + 1.5)
	PC.cast(W, "party2", 6552)
	local bashStart, bashLength = T.Timer(WARRIOR, "WARRIOR:Shield Bash")
	check("cdtrack: a shared category starts the timers of the abilities that share it, with the length of the category", T.Timer(WARRIOR, "WARRIOR:Pummel") == t0 + 1.5
		and bashStart == t0 + 1.5 and bashLength == 10, tostring(bashStart) .. " " .. tostring(bashLength))
	PC.cast(W, "party1", 11958)
	check("cdtrack: Ice Block is a timer of the mage", T.Timer(MAGE, "MAGE:Ice Block") ~= nil and T.Seen(MAGE, "MAGE:Ice Block"))
	W.advance(2)
	PC.cast(W, "party1", 12472)
	check("cdtrack: a reset clears the timers its ability names, and starts its own", T.Timer(MAGE, "MAGE:Ice Block") == nil and T.Timer(MAGE, "MAGE:Cold Snap") ~= nil and T.Seen(MAGE, "MAGE:Ice Block"))
	check("cdtrack: a spell that is none of the list starts nothing and an ability of another class starts nothing", (function()
		PC.cast(W, "party1", 6552)
		PC.cast(W, "party1", 1)
		return T.Timer(MAGE, "WARRIOR:Pummel") == nil and T.Timer(MAGE, "MAGE:Counterspell") ~= nil
	end)())
	W.advance(31)
	check("cdtrack: an ended timer is gone on lookup", T.Timer(MAGE, "MAGE:Counterspell") == nil and T.Book(MAGE).timers["MAGE:Counterspell"] == nil)
	check("cdtrack: looking a timer up makes no book for a player who has none", T.Timer("Player-9-9999", "MAGE:Counterspell") == nil and T.Book("Player-9-9999") == nil)
	local ability = W.ns.ABILITIES[103]
	for index = 1, 101 do
		T.Use("Cap-" .. index, "MAGE", ability, W.now)
	end
	check("cdtrack: 101 players keep 100, the oldest dropped", #T.order == 100 and T.Book("Cap-1") == nil and T.Book("Cap-2") ~= nil and T.Book("Cap-101") ~= nil, #T.order)
	local frame = W.pc.frames[1]
	check("cdtrack: a unit frame is an owner of timers when the GUID is hidden, and a hidden owner is none", T.Use(frame, "MAGE", ability, W.now) == true and T.Timer(frame, "MAGE:Counterspell") ~= nil
		and T.Book(SECRET, true) == nil and T.Use(SECRET, "MAGE", ability, W.now) == false)
	T.Clear()
	check("cdtrack: the timers are cleared at once", T.Timer(frame, "MAGE:Counterspell") == nil and #T.order == 0)
	W.au.instance = "party"
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	T.Use(MAGE, "MAGE", ability, W.now)
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	check("cdtrack: entering the world again in the same place keeps the timers", T.Timer(MAGE, "MAGE:Counterspell") ~= nil)
	W.au.instance = nil
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	check("cdtrack: leaving an instance clears the timers", T.Timer(MAGE, "MAGE:Counterspell") == nil)
	check("cdtrack: nothing in this section broke a rule of the client", PC.ok(W), PC.why(W))
end
do
	local PC = TOC.pc
	-- A cast with a cooldown of its own, and the cast of a category mate that is not in the list.
	local W = PC.world({ party = { { "HUNTER", "Orc" }, { "SHAMAN", "Tauren" } } })
	local T = W.ns.Tracking
	local HUNTER = PC.guid[1]
	local t0 = W.now
	PC.cast(W, "party1", 14311)
	local start, length = T.Timer(HUNTER, "HUNTER:Freezing Trap")
	check("cdtrack: a cast of a rank of an ability starts the timer of the ability with its cooldown", start == t0 and length == 30, tostring(length))
	W.advance(2)
	PC.cast(W, "party1", 27753)
	local again, shorter = T.Timer(HUNTER, "HUNTER:Freezing Trap")
	check("cdtrack: a cast that has a cooldown of its own starts the timer with that one", again == t0 + 2 and shorter == 15, tostring(again) .. " " .. tostring(shorter))
	T.Clear()
	PC.cast(W, "party1", 13809)
	local mate, seconds = T.Timer(HUNTER, "HUNTER:Freezing Trap")
	check("cdtrack: a cast of a category mate that is not in the list starts the timer of the ability, with the length of the category", mate == W.now and seconds == 30 and not T.Seen(HUNTER, "HUNTER:Freezing Trap"), tostring(seconds))
	PC.cast(W, "party2", 8042)
	check("cdtrack: a cast of the class of another member starts nothing for him", T.Timer(PC.guid[2], "SHAMAN:Earth Shock") ~= nil and T.Timer(HUNTER, "SHAMAN:Earth Shock") == nil and PC.ok(W), PC.why(W))
end
do
	local PC = TOC.pc
	-- Casts of units the game hides, and the counters.
	local W = PC.world()
	local T = W.ns.Tracking
	local before = T.counts.castHidden
	W.unitEvent("UNIT_SPELLCAST_SUCCEEDED", "party1", "party1", "Cast-1", SECRET)
	W.unitEvent("UNIT_SPELLCAST_SUCCEEDED", "party1", SECRET, "Cast-2", 2139)
	check("cdtrack: a hidden spell ID, and a hidden unit, add to the hidden counter and to nothing else", T.counts.castHidden == before + 2 and T.Book(PC.guid[1]) == nil and next(T.frames) == nil and PC.ok(W), PC.why(W))
	PC.cast(W, "party1", 2139)
	PC.cast(W, "party1", 6552)
	check("cdtrack: plain casts add to the readable counter, also for a spell that is none of the list", T.counts.castRead == 2 and T.counts.castHidden == before + 2, T.counts.castRead)
	local lines = table.concat(W.ns.CheckLines(), "\n")
	check("cdtrack: the check says how many party casts were seen, readable and hidden", has(lines, "Party casts seen: 2 readable, 2 hidden."), lines)
	check("cdtrack: and how many party buffs were read and what is known of the caster of one", has(lines, "Party buffs read: 0 readable, 0 hidden.") and has(lines, "Caster of a party buff: none seen yet."), lines)
	-- Buffs: one pass for each unit in 0.2 seconds, one call for the list.
	local calls, unitCalls = W.au.listCalls or 0, W.au.unitCalls or 0
	W.au.unitAuras.party1 = { [11958] = { duration = 10, expires = W.now + 8, source = "party1" } }
	local at = W.now
	for _ = 1, 5 do
		W.fireUnit("UNIT_AURA", "party1")
	end
	W.advance(0.1)
	check("cdtrack: a burst of buff events waits 0.2 seconds and makes no call before", (W.au.listCalls or 0) == calls)
	W.advance(0.2)
	check("cdtrack: and then one pass makes one call for the list of buffs, and none by spell ID", (W.au.listCalls or 0) == calls + 1 and (W.au.unitCalls or 0) == unitCalls and T.counts.auraRead == 1, tostring(W.au.listCalls))
	local start, length = T.Timer(PC.guid[1], "MAGE:Ice Block")
	check("cdtrack: a readable buff starts a timer at expirationTime minus duration, with the cooldown of the ability", start == at - 2 + 0 and length == 300 and has(table.concat(W.ns.CheckLines(), "\n"), "Caster of a party buff: readable."), tostring(start) .. " " .. tostring(length))
	W.au.unitAuras.party1 = { [11958] = { duration = 10, expires = W.now + 8 } }
	W.fireUnit("UNIT_AURA", "party1")
	W.advance(0.3)
	check("cdtrack: the same buff seen again is the same use", T.Timer(PC.guid[1], "MAGE:Ice Block") == start)
	W.au.unitAuras.party1 = { [12733] = { duration = 30, expires = W.now + 30 }, [999999] = { duration = 5, expires = W.now + 5 } }
	W.fireUnit("UNIT_AURA", "party1")
	W.advance(0.3)
	check("cdtrack: a buff with no caster is the unit's own, and a buff that is none of the list starts nothing", T.Timer(PC.guid[1], "ALL:Glimmering Mithril Insignia") ~= nil and T.Timer(PC.guid[1], "MAGE:Ice Block") == start
		and has(table.concat(W.ns.CheckLines(), "\n"), "Caster of a party buff: empty."))
	-- A defensive cast on another member goes to its caster.
	W.au.unitAuras.party1 = { [6346] = { duration = 180, expires = W.now + 170, source = "party3" } }
	W.fireUnit("UNIT_AURA", "party1")
	W.advance(0.3)
	check("cdtrack: a defensive cast on another goes to its caster, by the class of the caster", T.Timer(PC.guid[3], "PRIEST:Fear Ward") ~= nil and T.Timer(PC.guid[1], "PRIEST:Fear Ward") == nil)
	-- Buffs the game hides.
	W.au.unitAuras.party1 = { [11958] = { duration = 10, expires = W.now + 8, source = "party1" } }
	calls = W.au.listCalls
	W.au.hidden = true
	W.fireUnit("UNIT_AURA", "party1")
	W.advance(0.3)
	check("cdtrack: while the game hides buffs a pass makes no call, and counts a hidden read", W.au.listCalls == calls and T.counts.auraHidden == 1, tostring(T.counts.auraHidden))
	W.au.hidden = false
	-- The restrictions.
	local rec = T.units.party1
	local function events()
		return W.rawOf[rec.frame].events.UNIT_AURA == true, W.rawOf[rec.frame].events.UNIT_SPELLCAST_SUCCEEDED == true
	end
	check("cdtrack: a unit has a frame of its own, registered for that unit alone", events() and W.rawOf[rec.frame].unitEvents.UNIT_AURA[1] == "party1" and W.rawOf[rec.frame].unitEvents.UNIT_SPELLCAST_SUCCEEDED[1] == "party1")
	W.restriction("Combat", "Activating")
	local aura, cast = events()
	check("cdtrack: a restriction that starts, with no buff of the list that is never hidden, unregisters the buff event and keeps the cast event", aura == false and cast == true)
	W.restriction("Combat", "Inactive")
	aura, cast = events()
	check("cdtrack: and the end of the restriction registers it again", aura == true and cast == true and W.rawOf[rec.frame].unitEvents.UNIT_AURA[1] == "party1")
	W.au.secrecy[11958] = 0
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	W.restriction("Encounter", "Activating")
	aura = events()
	check("cdtrack: with a buff of the list that is never hidden the buff event stays", aura == true)
	W.restriction("Encounter", "Inactive")
	W.au.secrecy[11958] = nil
	W.au.hidden = true
	W.au.secrecy[11958] = 0
	calls = W.au.listCalls
	W.fireUnit("UNIT_AURA", "party1")
	W.advance(0.3)
	check("cdtrack: and a pass while the game hides buffs reads the list for it, passing on that buff alone", W.au.listCalls == calls and PC.ok(W) or W.au.listCalls == calls + 1)
	check("cdtrack: nothing in this section broke a rule of the client", PC.ok(W), PC.why(W))
end
do
	local PC = TOC.pc
	-- The rows: where they hang, what they show.
	local W = PC.world()
	local P = PC.mod(W)
	local R1, R2, R3 = PC.row(W, PC.guid[1]), PC.row(W, PC.guid[2]), PC.row(W, PC.guid[3])
	check("partycd: a row is made for each member of the party, with the 6 icons the setting allows, 24 units wide, 2 apart", R1 and R2 and R3 and #R1.icons == 6 and W.rawOf[R1.icons[1].frame].width == 24 and W.rawOf[R1.icons[2].frame].points[1][4] == 26,
		tostring(R1))
	check("partycd: the rows are frames of the addon's under UIParent, and none is a child of a member button", W.rawOf[R1.holder].parent == W.env.UIParent and W.rawOf[R2.holder].parent == W.env.UIParent and (function()
		for _, frame in ipairs(W.pc.frames) do
			for _, child in ipairs(W.rawOf[frame].children) do
				return false
			end
		end
		return true
	end)())
	check("partycd: Right of each frame hangs the left of the row from the right of the frame, 4 units out", PC.point(W, R1.holder) == "LEFT>RIGHT:4,0" and W.rawOf[R1.holder].points[1][2] == W.pc.frames[1] and W.rawOf[R2.holder].points[1][2] == W.pc.frames[2], PC.point(W, R1.holder))
	check("partycd: a mage shows Counterspell first, then the defensives he has without a talent, ready and bright", PC.keys(W, R1):find("^MAGE:Counterspell,") ~= nil and not PC.keys(W, R1):find("Ice Block", 1, true)
