	check("partycd: an ability above his level shows once it was seen used", PC.keys(W, warrior):find("WARRIOR:Pummel", 1, true) ~= nil, PC.keys(W, warrior))
	local mage = PC.row(W, PC.guid[1])
	check("partycd: a member whose level the game does not give shows his abilities whatever their level", PC.keys(W, mage):find("^MAGE:Counterspell") ~= nil and PC.ok(W), PC.keys(W, mage))
	local B = PC.world({ opts = { saved = { options = { ["partycd.ownRow"] = true, ["partycd.side"] = "below" } } } })
	local own, first = PC.row(B, "Player-1-0001"), PC.row(B, PC.guid[1])
	local point = B.rawOf[own.holder].points[1]
	check("partycd: with the icons below each frame the own row hangs from the top left of the first member's frame, not over it", point[1] == "BOTTOMLEFT" and point[2] == B.pc.frames[1] and point[3] == "TOPLEFT" and point[5] == 2 and PC.ok(B), PC.point(B, own.holder))
	local N = PC.world({ group = false })
	local before = #N.out
	N.ns.PartyTest()
	check("partycd: the test out of a party says where it shows", N.out[#N.out] == "Party cooldowns: the test shows in a party, out of combat." and #N.out == before + 1, tostring(N.out[#N.out]))
	local Off = PC.world({ group = false, opts = { saved = { options = { ["partycd.enabled"] = false } } } })
	before = #Off.out
	Off.ns.PartyTest()
	check("partycd: and with the page off the test says nothing", #Off.out == before, tostring(Off.out[#Off.out]))
end
-- >>> partycd (end)
-- >>> sharing (begin)
-- Party cooldowns shared between players who run Flat UI (PartySync.lua). The helpers are on TOC.pc, so that this file gains no local.
do
	local PC = TOC.pc
	-- A world of a warrior in a party of a mage, a warrior and a priest, whose game gives plain cooldown lengths: PC.cd.duration is the one it gives.
	function TOC.pcshare(o)
		o = o or {}
		local cd = { duration = 10, calls = 0 }
		PC.cd = cd
		return PC.world({ class = "WARRIOR", group = o.group, opts = o.opts, setup = function(S)
			S.au.chat.echo = false
			S.env.C_SpellBook = { IsSpellKnownOrInSpellBook = function(id)
				return id == 12975 or id == 871
			end }
			S.env.C_Spell.GetSpellCooldown = function()
				cd.calls = cd.calls + 1
				return { startTime = S.now, duration = cd.duration, isEnabled = true, modRate = 1, isActive = true, isOnGCD = false }
			end
			if o.setup then
				o.setup(S)
			end
		end })
	end
	-- The messages sent with the prefix, whose text starts with the kind.
	function TOC.pcsent(W, kind)
		local out = {}
		for _, m in ipairs(W.au.chat.sent) do
			if m.prefix == "FlatUI" and (kind == nil or m.message:sub(1, #kind + 2) == "1 " .. kind) then
				out[#out + 1] = m.message
			end
		end
		return out
	end
	-- A message from a member of the party.
	function TOC.pchear(W, text, who, prefix)
		W.fire("CHAT_MSG_ADDON", prefix or "FlatUI", text, "PARTY", who or "Mate2", "", 0, 0, "", 0)
	end
end
do
