	local wallStart, wallSeconds = T.Timer(WARRIOR, "WARRIOR:Shield Wall")
	check("sharing: with no seconds the timer has the length of the table, and the sender may carry a realm", wallStart == t0 and wallSeconds == 900, tostring(wallSeconds))
	local row = PC.row(W, WARRIOR)
	check("sharing: the row of the member shows the used icons dark", PC.keys(W, row):find("WARRIOR:Pummel", 1, true) ~= nil and W.rawOf[row.icons[1].texture].desaturated == true, PC.keys(W, row))
	check("sharing: a C for an ability of another class starts nothing for him", (function()
		TOC.pchear(W, "1 C 2139", "Mate2")
		return T.Timer(WARRIOR, "MAGE:Counterspell") == nil and T.Timer(WARRIOR, "WARRIOR:Pummel") == start
	end)())
	local function kept()
		local book, n = T.Book(WARRIOR), 0
		for _ in pairs(book.timers) do
			n = n + 1
		end
		return n, book.seen["WARRIOR:Last Stand"] == true
	end
	local timers = kept()
	local broken = { "1 C abc", "1 C 12809 0", "1 C 12809 99999", "1 C 12809 1.5", "1 C", "1 C 12809 7 8", "2 C 12809 7", "C 12809 7", "1 C -12809", "1 X 12809", "1H 12809",
		"1 C 99999999", "1 S 12809", "1 S 12809:0", "1 S x:5", "1 H", "1 H bad!guid 12975", "1 H - 12975 y", "", ("1 C 12809 7 "):rep(40), "1 C 12809 7" .. string.char(10) .. "1 C 1719 7",
		"1 C 12809 12345678" }
	for _, text in ipairs(broken) do
		TOC.pchear(W, text, "Mate2")
	end
	local after, seenLast = kept()
	check("sharing: broken text starts nothing and marks nothing, in any of its forms", after == timers and not seenLast and PC.ok(W), PC.why(W) .. " " .. after .. " " .. timers)
	TOC.pchear(W, "1 C 12809 7", "Stranger")
	TOC.pchear(W, "1 C 12809 7", "Mate2", "Other")
	TOC.pchear(W, "1 C 12809 7", "Mate2", "FlatUIx")
	TOC.pchear(W, "1 C 871 7", "Mine")
	check("sharing: a name that is not in the party, another prefix and the player's own message are ignored without error", kept() == timers and T.Book(PC.guid[1]) == nil and PC.ok(W), PC.why(W))
	W.fire("CHAT_MSG_ADDON", "FlatUI", "1 C 6552 7", "PARTY", SECRET, "", 0, 0, "", 0)
	W.fire("CHAT_MSG_ADDON", "FlatUI", SECRET, "PARTY", "Mate2", "", 0, 0, "", 0)
	W.fire("CHAT_MSG_ADDON", SECRET, "1 C 6552 7", "PARTY", "Mate2", "", 0, 0, "", 0)
	check("sharing: a withheld prefix, text or sender is ignored without error", PC.ok(W), PC.why(W))
	TOC.pchear(W, "1 S 12975:40 23920:90 1:20", "Mate2")
	local sStart, sSeconds = T.Timer(WARRIOR, "WARRIOR:Last Stand")
	local reflection = select(2, T.Timer(WARRIOR, "WARRIOR:Spell Reflection"))
	check("sharing: an S starts the timers it names with the seconds left, and skips a spell that is none of the list", sStart == W.now and sSeconds == 40 and reflection == 90 and T.Seen(WARRIOR, "WARRIOR:Last Stand"), tostring(sSeconds))
end
