	local at = W.now
	W.fireUnit("UNIT_AURA", "nameplate1")
	W.advance(0.3)
	local start, length = T.Timer(EC.guid[1], "MAGE:Ice Block")
	check("enemycd: a buff seen out of combat starts the timer from its start time, expirationTime minus duration, with the cooldown of the ability", start == at - 2 and length == 300 and (W.au.listCalls or 0) > calls
		and EC.keys(W, EC.row(W, mage)) == "MAGE:Ice Block" and EC.sweep(W, EC.row(W, mage), 1).start == at - 2, tostring(start) .. " " .. tostring(length))
	W.au.unitAuras.nameplate3 = { [6346] = { duration = 180, expires = W.now + 170, source = "nameplate2" } }
	W.fireUnit("UNIT_AURA", "nameplate3")
	W.advance(0.3)
	check("enemycd: a buff cast on another goes to its caster when the caster is a plate: Fear Ward on a warrior is the priest's", T.Timer(EC.guid[2], "PRIEST:Fear Ward") ~= nil and T.Timer(EC.guid[3], "PRIEST:Fear Ward") == nil
		and EC.keys(W, EC.row(W, priest)) == "PRIEST:Fear Ward", EC.keys(W, EC.row(W, priest)))
	T.Clear()
	W.au.unitAuras.nameplate3 = { [6346] = { duration = 180, expires = W.now + 170, source = SECRET } }
	W.fireUnit("UNIT_AURA", "nameplate3")
	W.advance(0.3)
	W.au.unitAuras.nameplate3 = { [6346] = { duration = 180, expires = W.now + 170 } }
	W.fireUnit("UNIT_AURA", "nameplate3")
	W.advance(0.3)
	W.au.unitAuras.nameplate3 = { [6346] = { duration = 180, expires = W.now + 170, source = "target" } }
	W.fireUnit("UNIT_AURA", "nameplate3")
	W.advance(0.3)
	check("enemycd: when the caster is hidden, empty or no plate, no timer is made", T.Timer(EC.guid[2], "PRIEST:Fear Ward") == nil and T.Timer(EC.guid[3], "PRIEST:Fear Ward") == nil and next(T.books) == nil and EC.ok(W), EC.why(W))
	W.au.unit.target = { guid = EC.guid[2], player = true, attack = true, class = "PRIEST", race = "Human", name = "Enemy2" }
	W.fireUnit("UNIT_AURA", "nameplate3")
	W.advance(0.3)
	check("enemycd: a caster named by a token whose GUID is a plate's is that plate's player", T.Timer(EC.guid[2], "PRIEST:Fear Ward") ~= nil)
	T.Clear()
	calls = W.au.listCalls or 0
	local hidden = T.enemyCounts.auraHidden
	W.au.hidden = true
	W.au.unitAuras.nameplate1 = { [11958] = { duration = 10, expires = W.now + 8 } }
	W.fireUnit("UNIT_AURA", "nameplate1")
	W.advance(0.3)
	check("enemycd: while the game hides buffs a pass makes no call for spells that are not never hidden, and counts a hidden read", (W.au.listCalls or 0) == calls and T.enemyCounts.auraHidden == hidden + 1 and T.Timer(EC.guid[1], "MAGE:Ice Block") == nil, tostring(W.au.listCalls))
	W.au.hidden = false
	check("enemycd: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC = TOC.ec
	-- A plate that goes and comes back, and unit frames the game reuses.
	local W = EC.world()
	local T = W.ns.Tracking
	local mage, unit = EC.enemy(W, 1, { class = "MAGE" })
	local t0 = W.now
	EC.cast(W, unit, 2139)
	W.advance(10)
	local row = EC.row(W, mage)
	EC.leave(W, unit)
	check("enemycd: the plate goes: its icons are taken away on the next frame and the timer stays with the player", EC.keys(W, row) == "" and T.Timer(EC.guid[1], "MAGE:Counterspell") == t0 and W.rawOf[row.holder].shown == false, EC.keys(W, row))
	local other = W.newPlate()
	W.au.unit.nameplate2 = { guid = EC.guid[1], player = true, attack = true, class = "MAGE", race = "Human", name = "Enemy1" }
	W.showPlate("nameplate2", other)
	local row2 = EC.row(W, other)
	local sweep = EC.sweep(W, row2, 1)
	check("enemycd: the same player added on another unit frame shows the icon with the time left", sweep ~= nil and sweep.start == t0 and sweep.duration == 30 and EC.keys(W, row2) == "MAGE:Counterspell", EC.keys(W, row2))
	EC.leave(W, "nameplate2")
	W.au.unit.nameplate3 = { guid = EC.guid[3], player = true, attack = true, class = "ROGUE", race = "Human", name = "Enemy3" }
	W.units.nameplate3 = other
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate3")
	check("enemycd: the same unit frame added for another player shows no icon of the first", EC.keys(W, row2) == "" and EC.sweep(W, row2, 1) == nil and W.rawOf[row2.holder].shown == false, EC.keys(W, row2))
	W.units.nameplate3 = nil
	W.units.nameplate4 = mage
	W.au.unit.nameplate4 = { guid = EC.guid[4], player = true, attack = false, class = "ROGUE", race = "Human", name = "Friend" }
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate4")
	check("enemycd: and a unit frame given to a friendly player has no listener and no icon", T.units.nameplate4 == nil and EC.keys(W, row) == "" and EC.ok(W), EC.why(W))
end
do
	local EC = TOC.ec
	-- The GUID of the unit is hidden: timers go by unit frame and are lost with the plate.
	local W = EC.world()
	local T = W.ns.Tracking
	W.au.identityHidden = true
	local plate, unit = EC.enemy(W, 1, { class = "MAGE" })
