-- >>> partyraid (begin)
-- Party cooldowns on raid-style party frames and in a raid group, with the Add and Hide lists and /flatui party. The helpers are on TOC.pc.
do
	local PC = TOC.pc
	-- The game's raid-style party frames: CompactPartyFrameMember1 to 5 hold the members in `order` (a list of unit tokens, nil for no member), the
	-- member buttons of the standard frames are hidden (PartyFrame.lua:47-49, 54-65). With `displayed` the frames name their unit only in
	-- displayedUnit.
	function TOC.pcstyle(W, order, displayed)
		for _, frame in ipairs(W.pc.frames) do
			W.rawOf[frame].shown = false
		end
		W.env.CompactPartyFrame = (W.B(nil, {}, { protected = true, name = "CompactPartyFrame" }))
		W.rawOf[W.env.CompactPartyFrame].shown = true
		W.pc.compact = {}
		for index = 1, 5 do
			local unit = order[index]
			local fields = unit and (displayed and { displayedUnit = unit } or { unit = unit, displayedUnit = unit }) or {}
			local frame = (W.B(nil, fields, { protected = true, objectType = "Button", name = "CompactPartyFrameMember" .. index, width = 80, height = 36 }))
			W.rawOf[frame].shown = unit ~= nil
			W.env["CompactPartyFrameMember" .. index] = frame
			W.pc.compact[index] = frame
		end
	end
	-- Back to the standard frames.
	function TOC.pcunstyle(W)
		for index, frame in ipairs(W.pc.frames) do
			W.rawOf[frame].shown = W.au.unit["party" .. index] ~= nil
		end
		W.rawOf[W.env.CompactPartyFrame].shown = false
		for _, frame in ipairs(W.pc.compact) do
			W.rawOf[frame].shown = false
		end
	end
	-- Where the holder of a row hangs: the frame it is anchored to.
	function TOC.pcon(W, row)
		return row and W.rawOf[row.holder].points[1][2]
	end
	function TOC.pcat(W, row)
		local p = W.rawOf[row.holder].points[1]
		return p[1] .. ">" .. p[3] .. ":" .. tostring(p[4]) .. "," .. tostring(p[5])
	end
	function TOC.pcraid(opts, more, party)
		local o = { party = party, opts = { saved = { options = opts or {} } }, setup = function(S)
			S.au.raid = true
			if more then
				more(S)
			end
		end }
		return PC.world(o)
	end
end
-- Raid-style party frames.
do
	local PC = TOC.pc
	local OWN = "Player-1-0001"
	local S = PC.world({ opts = { saved = { options = { ["partycd.ownRow"] = true } } }, setup = function(X)
		TOC.pcstyle(X, { "party2", "party1", "player", "party3" })
	end })
	local C = S.pc.compact
	local warrior, mage, priest, own = PC.row(S, PC.guid[2]), PC.row(S, PC.guid[1]), PC.row(S, PC.guid[3]), PC.row(S, OWN)
	check("partyraid: the party frame index and the party index differ and each row follows its unit: the warrior of party2 is on the first frame, the mage of party1 on the second",
		warrior ~= nil and mage ~= nil and priest ~= nil and TOC.pcon(S, warrior) == C[1] and TOC.pcon(S, mage) == C[2] and TOC.pcon(S, priest) == C[4], tostring(TOC.pcon(S, warrior)))
	check("partyraid: the rows are made of the addon's own under UIParent, hang from the right of each frame like the standard ones, and no button of the game has a child of ours",
		S.rawOf[warrior.holder].parent == S.env.UIParent and TOC.pcat(S, warrior) == "LEFT>RIGHT:4,0" and TOC.pcat(S, priest) == "LEFT>RIGHT:4,0" and (function()
			for _, frame in ipairs(C) do
				if #S.rawOf[frame].children > 0 then
					return false
				end
			end
			return true
		end)(), TOC.pcat(S, warrior))
	check("partyraid: your own row is on your own frame there, beside it like the others, and not above the first row", own ~= nil and own.own == true and TOC.pcon(S, own) == C[3] and TOC.pcat(S, own) == "LEFT>RIGHT:4,0", tostring(TOC.pcon(S, own)))
	check("partyraid: the abilities and the casts follow the unit, not the frame: a cast of party2 darkens the first frame's row", (function()
		PC.cast(S, "party2", 6552)
		return PC.sweep(S, warrior, 1) ~= nil and PC.sweep(S, mage, 1) == nil and PC.keys(S, warrior):find("^WARRIOR:Pummel") ~= nil
	end)(), PC.keys(S, warrior))
	check("partyraid: the three members are listened to and your own unit once", #S.ns.Tracking.Heard("partycd") == 5 and S.ns.Tracking.units.player ~= nil, table.concat(S.ns.Tracking.Heard("partycd"), ","))
	check("partyraid: the line about the standard party frames is gone and the status has no line for these frames", not has(S.status(), "standard party frames") and has(S.status(), "Party cooldowns: on") and PC.ok(S), S.status())
	check("partyraid: the list prints the members of the party and not you, with the raid-style frames too", (function()
		local list = S.slash("party list")
		return has(list, "Mate1: does not share cooldowns") and has(list, "Mate3: does not share cooldowns") and not has(list, "Mine")
	end)(), S.slash("party list"))
	-- With the own row off your frame among them gets none, and your casts are not listened to.
	local Q = PC.world({ opts = { saved = { options = { ["partycd.share"] = false } } }, setup = function(X)
		TOC.pcstyle(X, { "player", "party1", "party2" })
	end })
	check("partyraid: with Your own row off the frame of the player has no row and the others have theirs", PC.row(Q, OWN) == nil and PC.row(Q, PC.guid[1]) ~= nil and TOC.pcon(Q, PC.row(Q, PC.guid[1])) == Q.pc.compact[2] and PC.ok(Q), PC.why(Q))
	check("partyraid: and his casts are not listened to, only his buffs", Q.rawOf[Q.ns.Tracking.units.player.frame].events.UNIT_SPELLCAST_SUCCEEDED ~= true and Q.ns.Tracking.units.pet == nil, tostring(Q.rawOf[Q.ns.Tracking.units.player.frame].events.UNIT_SPELLCAST_SUCCEEDED) .. " " .. tostring(Q.ns.Tracking.units.pet) .. table.concat(Q.ns.Tracking.Heard("partycd"), ","))
	-- A unit with two frames has one row, on the first.
	local Dup = PC.world({ setup = function(X)
		TOC.pcstyle(X, { "party1", "party1", "party2" })
	end })
	check("partyraid: a unit that two frames name has one row, on the first of them", TOC.pcon(Dup, PC.row(Dup, PC.guid[1])) == Dup.pc.compact[1] and PC.row(Dup, PC.guid[2]) ~= nil and PC.ok(Dup), PC.why(Dup))
	-- With no frame of your own among them the own row is above the first row.
	local A = PC.world({ opts = { saved = { options = { ["partycd.ownRow"] = true } } }, setup = function(X)
		TOC.pcstyle(X, { "party1", "party2" })
	end })
	local first, mine = PC.row(A, PC.guid[1]), PC.row(A, OWN)
	check("partyraid: with no frame of yours the own row is one row above the first member's", mine ~= nil and TOC.pcon(A, mine) == first.holder and A.rawOf[mine.holder].points[1][1] == "BOTTOMLEFT", TOC.pcat(A, mine or first))
	-- Frames that give the unit in displayedUnit only.
	local D = PC.world({ setup = function(X)
		TOC.pcstyle(X, { "party1", "party2", "party3" }, true)
	end })
	check("partyraid: a frame that names its unit in displayedUnit only is followed too", TOC.pcon(D, PC.row(D, PC.guid[2])) == D.pc.compact[2] and PC.row(D, PC.guid[3]) ~= nil and PC.ok(D), PC.why(D))
	-- A frame whose unit is a creature or a hidden value gets no row.
	local V = PC.world({ setup = function(X)
		TOC.pcstyle(X, { "party1", "boss1", "party3" })
	end })
	check("partyraid: a frame of a unit that is not the player or a party member gets no row", PC.row(V, PC.guid[1]) ~= nil and PC.row(V, PC.guid[3]) ~= nil and PC.row(V, PC.guid[2]) == nil and PC.ok(V), PC.why(V))
	-- Switching between the two styles moves the rows when combat is over.
	local W = PC.world()
	local row = PC.row(W, PC.guid[2])
	local frames = #W.addonFrames
	local before = TOC.pcon(W, row)
	W.combat = true
	TOC.pcstyle(W, { "party1", "party2", "party3" })
	W.fire("EDIT_MODE_LAYOUTS_UPDATED")
	W.advance(1)
	check("partyraid: in combat a switch to the raid-style frames moves nothing and makes no frame", TOC.pcon(W, PC.row(W, PC.guid[2])) == before and #W.addonFrames == frames and PC.ok(W), PC.why(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("partyraid: and the rows are on the new frames when combat ends", TOC.pcon(W, PC.row(W, PC.guid[2])) == W.pc.compact[2] and TOC.pcon(W, PC.row(W, PC.guid[1])) == W.pc.compact[1] and PC.keys(W, PC.row(W, PC.guid[2])) ~= "" and PC.ok(W), PC.why(W))
	W.combat = true
	TOC.pcunstyle(W)
	W.advance(1)
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	check("partyraid: a switch back to the standard frames in combat is answered the same way: the rows are on the member buttons after it", TOC.pcon(W, PC.row(W, PC.guid[2])) == W.pc.frames[2] and TOC.pcon(W, PC.row(W, PC.guid[1])) == W.pc.frames[1] and PC.ok(W), PC.why(W))
	TOC.pcstyle(W, { "party1", "party2", "party3" })
	W.advance(0.6)
	check("partyraid: out of combat the next look moves them without an event", TOC.pcon(W, PC.row(W, PC.guid[3])) == W.pc.compact[3], tostring(TOC.pcon(W, PC.row(W, PC.guid[3]))))
	check("partyraid: nothing in this section broke a rule of the client", PC.ok(S) and PC.ok(A) and PC.ok(D) and PC.ok(V) and PC.ok(W), PC.why(W))
end
-- A raid group.
do
	local PC = TOC.pc
	local OWN = "Player-1-0001"
	local R = TOC.pcraid({ ["partycd.ownRow"] = true }, function(X)
		X.addSpell(8042, { name = "Earth Shock", icon = 136026, base = 6000 })
	end, { { "MAGE", "Human" }, { "WARRIOR", "Dwarf" }, { "PRIEST", "Human" }, { "ROGUE", "Gnome" } })
	local P = PC.mod(R)
	local stack = P.stack
	local own, r1, r2, r3, r4 = PC.row(R, OWN), PC.row(R, PC.guid[1]), PC.row(R, PC.guid[2]), PC.row(R, PC.guid[3]), PC.row(R, PC.guid[4])
	local function slot(row)
		local p = R.rawOf[row.holder].points[1]
		return p[1] .. ">" .. tostring(p[2] == stack) .. ">" .. p[3] .. ":" .. p[4] .. "," .. (p[5] == 0 and 0 or p[5])
	end
	check("partyraid: in a raid group your own row and the rows of party1 to party4 are one holder of the addon's own under UIParent, one under the other", stack ~= nil and R.rawOf[stack].parent == R.env.UIParent
		and own and r1 and r2 and r3 and r4 and slot(own) == "TOPLEFT>true>TOPLEFT:70,0" and slot(r1) == "TOPLEFT>true>TOPLEFT:70,-26" and slot(r2) == "TOPLEFT>true>TOPLEFT:70,-52" and slot(r3) == "TOPLEFT>true>TOPLEFT:70,-78"
		and slot(r4) == "TOPLEFT>true>TOPLEFT:70,-104",
		tostring(own and slot(own)) .. " " .. tostring(r1 and slot(r1)))
	check("partyraid: each row has the member's name to its left in small text", own and R.rawOf[own.label].text == "Mine" and R.rawOf[r1.label].text == "Mate1" and R.rawOf[r4.label].text == "Mate4"
		and R.rawOf[r1.label].points[1][1] == "RIGHT" and R.rawOf[r1.label].points[1][2] == r1.holder and R.rawOf[r1.label].points[1][3] == "LEFT", tostring(own and R.rawOf[own.label].text))
	local x, y = R.ns.MoverSpot("FlatUIPartyRaid", "TOPLEFT")
	local top = R.rawOf[stack].points[1]
	check("partyraid: the holder hangs by its top left from the spot of its handle, which starts 420 left of the middle of the screen", top[1] == "TOPLEFT" and top[2] == R.env.UIParent and top[3] == "BOTTOMLEFT" and top[4] == x and top[5] == y
		and (function()
			local cx, cy = R.ns.MoverSpot("FlatUIPartyRaid", "CENTER")
			return x == cx - 110 and y == cy + 75 and cx - R.rawOf[R.env.UIParent].width / 2 == -420
		end)(), tostring(x) .. " " .. tostring(y))
	check("partyraid: the rows show the abilities of the members, and your own row what is in your book", PC.keys(R, r1):find("^MAGE:Counterspell") ~= nil and PC.keys(R, r2):find("^WARRIOR:Pummel") ~= nil and PC.keys(R, own):find("^SHAMAN:Earth Shock") ~= nil
		and #r1.icons == 6 and PC.keys(R, r4):find("^ROGUE:Kick") ~= nil, PC.keys(R, r1))
	check("partyraid: the icons of a row in the stack run to the right, 2 units apart", R.rawOf[r1.icons[2].frame].points[1][4] == 26 and R.rawOf[r1.icons[2].frame].points[1][1] ~= "BOTTOMRIGHT",
		tostring(R.rawOf[r1.icons[2].frame].points[1][1]) .. tostring(R.rawOf[r1.icons[2].frame].points[1][4]))
	check("partyraid: the member frames of the game hold no row and the old line is gone", not has(R.status(), "off in a raid group") and not has(R.status(), "standard party frames") and PC.ok(R), R.status())
	PC.cast(R, "party2", 6552)
	check("partyraid: a cast of a member darkens his icon in the stack, with the sweep", PC.sweep(R, r2, 1) ~= nil and PC.sweep(R, r2, 1).duration == 10 and PC.sweep(R, r1, 1) == nil, PC.keys(R, r2))
	check("partyraid: the party members are listened to", #R.ns.Tracking.Heard("partycd") == 6 and R.rawOf[R.ns.Tracking.units.party2.frame].events.UNIT_SPELLCAST_SUCCEEDED == true, table.concat(R.ns.Tracking.Heard("partycd"), ","))
	check("partyraid: the handle is offered while the player is in a raid group and the page is on", R.ns.PartyRaidShown() == true)
	-- Out of the raid the rows go back to the member buttons and the handle goes.
	R.au.raid = false
	R.fire("GROUP_ROSTER_UPDATE")
	R.advance(0.6)
	check("partyraid: leaving the raid group puts the rows back on the member frames and hides the holder, and there is no handle", TOC.pcon(R, PC.row(R, PC.guid[1])) == R.pc.frames[1] and R.rawOf[stack].shown == false and R.ns.PartyRaidShown() == false
		and R.rawOf[r1.label].shown == false and R.rawOf[own.label].shown == false and PC.ok(R), PC.why(R))
	R.au.raid = true
	R.fire("GROUP_ROSTER_UPDATE")
	R.advance(0.6)
	check("partyraid: and a raid group again stacks them again in the same holder", R.rawOf[stack].shown == true and TOC.pcon(R, PC.row(R, PC.guid[1])) == stack and slot(PC.row(R, PC.guid[2])) == "TOPLEFT>true>TOPLEFT:70,-52" and PC.ok(R), PC.why(R))
	-- A new icon size lays the stack out again.
	R.change("partycd.size", 30)
	R.advance(0.6)
	check("partyraid: Icon size changes the room between the rows of the stack: 32 units for 30 and 2", slot(PC.row(R, PC.guid[1])) == "TOPLEFT>true>TOPLEFT:70,-32" and slot(PC.row(R, PC.guid[4])) == "TOPLEFT>true>TOPLEFT:70,-128" and PC.ok(R), tostring(slot(PC.row(R, PC.guid[1]))))
	R.change("partycd.size", 24)
	R.advance(0.6)
	-- Moved by the handle: the holder follows.
	R.spots().FlatUIPartyRaid = { point = "CENTER", x = 100, y = 50, kind = "hud" }
	R.ns.PartyRaidMoved()
	R.advance(0.1)
	local moved = R.rawOf[stack].points[1]
	check("partyraid: a spot saved by the handle moves the holder, box 220 by 150: its top left is 110 left of the spot and 75 above it", moved[4] == x + 520 and moved[5] == select(2, R.ns.MoverSpot("FlatUIPartyRaid", "TOPLEFT")) and moved[5] ~= y, tostring(moved[4]) .. " " .. tostring(moved[5]))
	-- Without your own row.
	local N = TOC.pcraid()
	check("partyraid: with Your own row off the stack has the members only, three rows, the first at the top", PC.row(N, OWN) == nil and N.rawOf[PC.row(N, PC.guid[1]).holder].points[1][5] == 0 and N.rawOf[PC.row(N, PC.guid[3]).holder].points[1][5] == -52 and PC.ok(N), PC.why(N))
	-- In combat.
	local F = PC.world({ opts = { saved = { options = { ["partycd.ownRow"] = true } } } })
	local frames = #F.addonFrames
	F.combat = true
	F.au.raid = true
	F.fire("GROUP_ROSTER_UPDATE")
	F.advance(1)
	check("partyraid: a raid group joined in combat makes no frame: the holder is made when combat ends", PC.mod(F).stack == nil and #F.addonFrames == frames and PC.ok(F), PC.why(F))
	F.combat = false
	F.fire("PLAYER_REGEN_ENABLED")
	check("partyraid: and then the rows are in it", PC.mod(F).stack ~= nil and TOC.pcon(F, PC.row(F, PC.guid[1])) == PC.mod(F).stack and PC.ok(F), PC.why(F))
	check("partyraid: /flatui check says the group is a raid", has(table.concat(F.ns.CheckLines(), "\n"), "Group: raid."), table.concat(F.ns.CheckLines(), "\n"))
	-- Hidden identities: a member whose GUID the game withholds has no row; your own row has one whatever the game says.
	local H = TOC.pcraid({ ["partycd.ownRow"] = true }, function(X)
		X.au.identityHidden = { player = true, party2 = true }
	end)
	check("partyraid: a member whose GUID is hidden has no row in the stack, and the rows after him close up", PC.row(H, PC.guid[2]) == nil and PC.row(H, "player") ~= nil and H.rawOf[PC.row(H, "player").holder].points[1][5] == 0
		and H.rawOf[PC.row(H, PC.guid[1]).holder].points[1][5] == -26 and H.rawOf[PC.row(H, PC.guid[3]).holder].points[1][5] == -52 and PC.ok(H), PC.why(H))
	-- In a raid group with In a raid group off.
	local O = TOC.pcraid({ ["partycd.raid"] = "off" })
	check("partyraid: In a raid group set to Off: no row, no holder, nothing listened to, no handle and no line", next(PC.mod(O).assigned) == nil and PC.mod(O).stack == nil and #O.ns.Tracking.Heard("partycd") == 0 and O.ns.PartyRaidShown() == false
		and not has(O.status(), "raid") and PC.ok(O), O.status())
	O.change("partycd.raid", "Own position")
	O.advance(0.6)
	check("partyraid: and set to Own position the rows are there and the handle is offered", PC.row(O, PC.guid[1]) ~= nil and PC.mod(O).stack ~= nil and O.ns.PartyRaidShown() == true and PC.ok(O), PC.why(O))
	local gone = PC.row(O, PC.guid[1])
	O.change("partycd.enabled", false)
	O.advance(0.6)
	check("partyraid: with the page off the rows, their names and the holder go and the handle with them", next(PC.mod(O).assigned) == nil and O.rawOf[PC.mod(O).stack].shown == false and O.rawOf[gone.label].shown == false and O.ns.PartyRaidShown() == false and PC.ok(O), PC.why(O))
	-- The test command shows on the stack.
	local T = TOC.pcraid({ ["partycd.ownRow"] = true })
	T.ns.PartyTest()
	check("partyraid: /flatui test shows its sample icons on the rows of the stack", T.out[#T.out] == "Party cooldowns: sample icons on each row for 8 seconds." and PC.sweep(T, PC.row(T, PC.guid[2]), 3) ~= nil and PC.ok(T), tostring(T.out[#T.out]))
	check("partyraid: nothing in this section broke a rule of the client", PC.ok(R) and PC.ok(N) and PC.ok(F) and PC.ok(O) and PC.ok(T), PC.why(R))
end
-- A raid group where the party tokens name no one: the subgroup comes from the roster.
do
	local PC = TOC.pc
	local R = PC.world({ party = {}, setup = function(X)
		X.au.raid = true
		X.au.roster = { { name = "Mine-Realm", subgroup = 2 }, { name = "Alpha", subgroup = 1, class = "MAGE" }, { name = "Bravo-Realm", subgroup = 2, class = "WARRIOR" },
			{ name = "Charlie", subgroup = 2, class = "ROGUE" }, { name = "Delta", subgroup = 3, class = "PRIEST" } }
		for index, who in ipairs({ { "Alpha", "MAGE", "Player-1-0021" }, { "Bravo", "WARRIOR", "Player-1-0022" }, { "Charlie", "ROGUE", "Player-1-0023" }, { "Delta", "PRIEST", "Player-1-0024" } }) do
			X.au.unit["raid" .. (index + 1)] = { guid = who[3], player = true, class = who[2], race = "Human", name = who[1] }
		end
	end, opts = { saved = { options = { ["partycd.ownRow"] = true } } } })
	local bravo, charlie, alpha, delta = PC.row(R, "Player-1-0022"), PC.row(R, "Player-1-0023"), PC.row(R, "Player-1-0021"), PC.row(R, "Player-1-0024")
	check("partyraid: with no party token in the raid the members of your subgroup come from the roster: Bravo and Charlie, with your own row first", bravo ~= nil and charlie ~= nil and alpha == nil and delta == nil and PC.row(R, "Player-1-0001") ~= nil
		and PC.mod(R).via == "roster" and R.rawOf[bravo.holder].points[1][5] == -26 and R.rawOf[charlie.holder].points[1][5] == -52, tostring(PC.mod(R).via))
	check("partyraid: each is labelled with his name and his raid token is listened to", R.rawOf[bravo.label].text == "Bravo" and R.rawOf[charlie.label].text == "Charlie" and table.concat(R.ns.Tracking.Heard("partycd"), ",") == "pet,player,raid3,raid4",
		table.concat(R.ns.Tracking.Heard("partycd"), ","))
	check("partyraid: and a cast of his token is his", (function()
		PC.cast(R, "raid3", 6552)
		return PC.sweep(R, bravo, 1) ~= nil and PC.sweep(R, charlie, 1) == nil
	end)(), PC.keys(R, bravo))
	check("partyraid: the status says once that the subgroup is read from the roster", count(R.status(), "Party cooldowns: your subgroup is read from the raid roster here.") == 1, R.status())
	check("partyraid: a raid with party tokens does not say so", not has(TOC.pcraid().status(), "raid roster"))
	R.au.raid = false
	R.fire("GROUP_ROSTER_UPDATE")
	R.advance(0.6)
	check("partyraid: out of the raid the line is gone", not has(R.status(), "raid roster") and next(PC.mod(R).assigned) == nil and PC.ok(R), R.status())
	local Five = PC.world({ party = {}, setup = function(X)
		X.au.raid = true
		X.au.roster = { { name = "Mine", subgroup = 1 } }
		for index = 2, 6 do
			X.au.roster[index] = { name = "Other" .. index, subgroup = 1 }
			X.au.unit["raid" .. index] = { guid = ("Player-1-01%02d"):format(index), player = true, class = "MAGE", race = "Human", name = "Other" .. index }
		end
	end })
	check("partyraid: five others in your subgroup make four rows, the first four of the roster", PC.row(Five, "Player-1-0102") ~= nil and PC.row(Five, "Player-1-0105") ~= nil and PC.row(Five, "Player-1-0106") == nil and PC.ok(Five), PC.why(Five))
	local Q = PC.world({ party = {}, setup = function(X)
		X.au.raid = true
		X.au.roster = { { name = "Mine", subgroup = 1 }, { name = "Alpha", subgroup = 2 } }
	end })
	check("partyraid: a roster with no one else in your subgroup makes no row and no error", next(PC.mod(Q).assigned) == nil and PC.ok(Q), PC.why(Q))
	local G = PC.world({ party = {}, setup = function(X)
		X.au.raid = true
		X.env.GetRaidRosterInfo = nil
		X.env.GetNumGroupMembers = nil
	end })
	check("partyraid: a client without the roster calls makes no row and raises nothing", next(PC.mod(G).assigned) == nil and PC.ok(G), PC.why(G))
	check("partyraid: nothing in this section broke a rule of the client", PC.ok(R) and PC.ok(Q), PC.why(R))
end
-- The lists.
do
	local PC = TOC.pc
	local function row(W, name)
		local page
		for _, p in ipairs(W.ns.PAGES) do
			if p.key == "partycd" then
				page = p
			end
		end
		for _, item in ipairs(page) do
			if item.key == name then
				return item
			end
		end
	end
	local W = PC.world({ opts = { saved = { options = { ["partycd.count"] = 8 } } }, setup = function(X)
		X.addSpell(555001, { name = "Hand of Test" })
	end })
	local warrior = PC.row(W, PC.guid[2])
	local add, hide, raid = row(W, "add"), row(W, "hide"), row(W, "raid")
	check("partyraid: the page has In a raid group with Own position at first and Off, and the two lists with their tip", raid and raid.kind == "choice" and raid.default == "own" and #raid.choices == 2 and raid.choices[2][2] == "Off"
		and add and add.kind == "list" and add.label == "Add an ability" and add.none == "Choose an ability" and add.items == "PartyAbilityCandidates" and add.pick == "PartyAbilityAdd"
		and add.tip == "For a spell that is not listed, type /flatui party add, its spell ID and its cooldown in seconds." and hide and hide.kind == "list" and hide.label == "Hide an ability" and hide.items == "PartyAbilityShown" and hide.pick == "PartyAbilityHide")
	local function names(lines)
		local out = {}
		for _, line in ipairs(lines) do
			out[#out + 1] = line[2]
		end
		return table.concat(out, "|")
	end
	local candidates, shown = names(W.ns.PartyAbilityCandidates()), names(W.ns.PartyAbilityShown())
	check("partyraid: Add an ability offers what the switches leave out, by name with the class, and not what is shown", candidates:find("Intimidating Shout (Warrior)", 1, true) ~= nil and candidates:find("Rallying Cry (Warrior)", 1, true) ~= nil
		and not candidates:find("Pummel", 1, true) and not candidates:find("Polymorph", 1, true), candidates:sub(1, 200))
	check("partyraid: Hide an ability lists what is shown, and a racial has no class beside it", shown:find("Pummel (Warrior)", 1, true) ~= nil and shown:find("Stoneform", 1, true) ~= nil and not shown:find("Stoneform (", 1, true) and not shown:find("Intimidating Shout", 1, true), shown:sub(1, 200))
	check("partyraid: the lines are in the order of their names and a key for the pick", (function()
		local lines = W.ns.PartyAbilityCandidates()
		for index = 2, #lines do
			if lines[index - 1][2]:lower() > lines[index][2]:lower() then
				return false
			end
		end
		return type(lines[1][1]) == "string" and lines[1][1]:find(":", 1, true) ~= nil
	end)())
	check("partyraid: two abilities with one name are told apart by a spell ID beside the name", candidates:find("Insignia of the Alliance or Horde, spell 5579", 1, true) ~= nil and candidates:find("Insignia of the Alliance or Horde, spell 23277", 1, true) ~= nil
		and candidates:find("Intimidating Shout (Warrior), spell", 1, true) == nil, candidates:sub(1, 100))
	-- Add from the page.
	local ok, message = W.ns.PartyAbilityAdd("WARRIOR:Intimidating Shout")
	check("partyraid: a pick of Add an ability says it is added, and the ability is the first in the row of the member", ok == true and message == "Added Intimidating Shout (Warrior)." and PC.keys(W, warrior):find("^WARRIOR:Intimidating Shout,WARRIOR:Pummel") ~= nil, message .. " " .. PC.keys(W, warrior))
	check("partyraid: and it is kept for the account, and no longer offered", W.env.FlatUIDB.abilities.party.added["WARRIOR:Intimidating Shout"] == true and not names(W.ns.PartyAbilityCandidates()):find("Intimidating Shout", 1, true) and names(W.ns.PartyAbilityShown()):find("Intimidating Shout (Warrior)", 1, true) ~= nil)
	local again, againMessage = W.ns.PartyAbilityAdd("WARRIOR:Intimidating Shout")
	check("partyraid: the same pick again says it is shown and changes nothing", again == false and againMessage == "Intimidating Shout (Warrior) is already shown." and (select(2, W.ns.PartyAbilityAdd("nonsense"))) == 'No ability found for "nonsense".')
	check("partyraid: an ability added for a class shows for that class only: the mage has none of it", not PC.keys(W, PC.row(W, PC.guid[1])):find("Intimidating", 1, true))
	-- Hide from the page.
	local hid, hidMessage = W.ns.PartyAbilityHide("WARRIOR:Shield Wall")
	check("partyraid: a pick of Hide an ability says it is hidden, and the ability is gone from the row though its switch is on", hid == true and hidMessage == "Hid Shield Wall (Warrior)." and not PC.keys(W, warrior):find("Shield Wall", 1, true)
		and W.env.FlatUIDB.abilities.party.hidden["WARRIOR:Shield Wall"] == true, hidMessage .. " " .. PC.keys(W, warrior))
	check("partyraid: it is offered by Add an ability then, and not by Hide an ability", names(W.ns.PartyAbilityCandidates()):find("Shield Wall (Warrior)", 1, true) ~= nil and not names(W.ns.PartyAbilityShown()):find("Shield Wall (Warrior)", 1, true))
	check("partyraid: hiding it again says so, and so does hiding what no switch shows", select(2, W.ns.PartyAbilityHide("WARRIOR:Shield Wall")) == "Shield Wall (Warrior) is already hidden." and select(2, W.ns.PartyAbilityHide("WARRIOR:Rallying Cry")) == "Rallying Cry (Warrior) is not shown.")
	W.ns.PartyAbilityAdd("WARRIOR:Shield Wall")
	check("partyraid: adding a hidden ability shows it again", PC.keys(W, warrior):find("WARRIOR:Shield Wall", 1, true) ~= nil and W.env.FlatUIDB.abilities.party.hidden["WARRIOR:Shield Wall"] == nil)
	-- Both survive a reload.
	W.ns.PartyAbilityHide("WARRIOR:Pummel")
	local R = PC.world({ opts = { saved = W.env.FlatUIDB }, setup = function(X)
		X.addSpell(555001, { name = "Hand of Test" })
	end })
	local rw = PC.row(R, PC.guid[2])
	check("partyraid: what was added and what was hidden are still so after a reload", rw ~= nil and PC.keys(R, rw):find("^WARRIOR:Shield Wall,WARRIOR:Intimidating Shout,WARRIOR:Shield Bash") ~= nil and not PC.keys(R, rw):find("Pummel", 1, true), PC.keys(R, rw))
	-- The words.
	local S = PC.world({ opts = { saved = { options = { ["partycd.count"] = 8 } } }, setup = function(X)
		X.addSpell(555001, { name = "Hand of Test" })
		X.addSpell(555002, { name = "Test Strike" })
	end })
	local sw, sm = PC.row(S, PC.guid[2]), PC.row(S, PC.guid[1])
	check("partyraid: add takes a name in any capitals", S.slash("party add intimidating SHOUT") == "Added Intimidating Shout (Warrior)." and PC.keys(S, sw):find("^WARRIOR:Intimidating Shout") ~= nil, S.slash("party add intimidating shout"))
	check("partyraid: a name that is already shown says so", S.slash("party add Shield Bash") == "Shield Bash (Warrior) is already shown.")
	check("partyraid: a spell ID of the data takes the ability it casts", S.slash("party add 11578") == "Added Charge (Warrior)." and S.env.FlatUIDB.abilities.party.added["WARRIOR:Charge"] == true)
	check("partyraid: so does a shift-clicked spell", S.slash("party add |cff71d5ff|Hspell:426490:0|h[Rallying Cry]|h|r") == "Added Rallying Cry (Warrior)." and S.env.FlatUIDB.abilities.party.added["WARRIOR:Rallying Cry"] == true)
	check("partyraid: an ability with no timer is told so", S.slash("party add Polymorph") == "Polymorph (Mage) has no cooldown to show.")
	check("partyraid: an ability with a name that two classes have prints both entries and changes nothing", (function()
		local before = S.env.FlatUIDB.abilities.party.added["WARRIOR:Intercept"]
		local text = S.slash("party add Intercept")
		return text:find("Intercept (Warrior)", 1, true) ~= nil and text:find("Intercept (Warlock)", 1, true) ~= nil and S.env.FlatUIDB.abilities.party.added["WARRIOR:Intercept"] == before
			and S.env.FlatUIDB.abilities.party.added["WARLOCK:Intercept"] == nil
	end)(), S.slash("party add Intercept"))
	check("partyraid: with the class in brackets the name is one ability", S.slash("party add Intercept (Warrior)") == "Added Intercept (Warrior)." and S.env.FlatUIDB.abilities.party.added["WARRIOR:Intercept"] == true)
	check("partyraid: a name nobody has says so", S.slash("party add Nothing Here") == 'No ability found for "Nothing Here".' and S.slash("party hide Nothing Here") == 'No ability found for "Nothing Here".')
	check("partyraid: a spell ID that is not listed asks for its cooldown", S.slash("party add 555001") == "Spell 555001 is not listed. Type its cooldown in seconds after the ID.")
	check("partyraid: with its cooldown it is added by the name the game has for it", S.slash("party add 555001 45") == "Added Hand of Test, 45 seconds." and S.env.FlatUIDB.abilities.party.custom[555001].seconds == 45
		and S.env.FlatUIDB.abilities.party.custom[555001].name == "Hand of Test")
	check("partyraid: a spell the game has no name for is no spell", S.slash("party add 999999 30") == 'No spell found for "999999".' and S.env.FlatUIDB.abilities.party.custom[999999] == nil)
	check("partyraid: a cooldown that is none is refused", S.slash("party add 555002 0") == "A cooldown is 1 to 86400 seconds." and S.slash("party add 555002 99999999") == "A cooldown is 1 to 86400 seconds.")
