	S.slash("party add 555001 60")
	PC.cast(S, "party1", 555001)
	check("partyraid: a new cooldown for it is the one used from the next cast", PC.sweep(S, sm, 1) ~= nil and PC.sweep(S, sm, 1).duration == 60 and S.env.FlatUIDB.abilities.party.custom[555001].seconds == 60, tostring(PC.sweep(S, sm, 1) and PC.sweep(S, sm, 1).duration))
	S.slash("party add Pummel 12")
	PC.cast(S, "party2", 6552)
	local start, length = S.ns.Tracking.Timer(PC.guid[2], "WARRIOR:Pummel")
	local _, mate = S.ns.Tracking.Timer(PC.guid[2], "WARRIOR:Shield Bash")
	check("partyraid: a cooldown typed for an ability of the data is the length of its timer, and the category mate keeps the category's", start ~= nil and length == 12 and mate == 10 and S.env.FlatUIDB.abilities.party.seconds["WARRIOR:Pummel"] == 12,
		tostring(length) .. " " .. tostring(mate))
	check("partyraid: the same cooldown typed again is nothing new, and another one is", S.slash("party add Pummel 12") == "Pummel (Warrior) is already shown." and S.slash("party add Pummel 10") == "Added Pummel (Warrior), 10 seconds."
		and S.env.FlatUIDB.abilities.party.seconds["WARRIOR:Pummel"] == 10)
	check("partyraid: a cooldown typed for an ability already shown does not add it to the list", S.env.FlatUIDB.abilities.party.added["WARRIOR:Pummel"] == nil)
	check("partyraid: a cooldown typed for a buff is the length of its timer too", (function()
		S.slash("party add Ice Block 100")
		S.au.unitAuras.party1 = { [11958] = { duration = 10, expires = S.now + 8, source = "party1" } }
		S.fireUnit("UNIT_AURA", "party1")
		S.advance(0.3)
		local _, ice = S.ns.Tracking.Timer(PC.guid[1], "MAGE:Ice Block")
		return ice == 100
	end)())
	check("partyraid: a spell given as spell: and its ID, or as a link, takes the cooldown after it", S.slash("party add spell:555002 20") == "Added Test Strike, 20 seconds." and S.slash("party add |cff71d5ff|Hspell:555002:0|h[Test Strike]|h|r 25") == "Added Test Strike, 25 seconds."
		and S.env.FlatUIDB.abilities.party.custom[555002].seconds == 25)
	check("partyraid: a cooldown of a day is taken and a second more is not", S.slash("party add 555002 86400") == "Added Test Strike, 86400 seconds." and S.slash("party add 555002 86401") == "A cooldown is 1 to 86400 seconds.")
	check("partyraid: hide takes an ability by name or by spell ID", S.slash("party hide Shield Wall") == "Hid Shield Wall (Warrior)." and S.slash("party hide 6552") == "Hid Pummel (Warrior)." and not PC.keys(S, sw):find("Pummel", 1, true) and not PC.keys(S, sw):find("Shield Wall", 1, true))
	check("partyraid: hiding an ability that was added takes it off the added ones", S.slash("party hide Intimidating Shout") == "Hid Intimidating Shout (Warrior)." and S.env.FlatUIDB.abilities.party.added["WARRIOR:Intimidating Shout"] == nil
		and S.env.FlatUIDB.abilities.party.hidden["WARRIOR:Intimidating Shout"] == true and S.slash("party hide Intimidating Shout") == "Intimidating Shout (Warrior) is already hidden.")
	PC.cast(S, "party2", 555002)
	check("partyraid: hiding a spell added by ID removes it", S.slash("party hide 555001") == "Removed Hand of Test." and S.env.FlatUIDB.abilities.party.custom[555001] == nil and not PC.keys(S, sw):find("custom:555001", 1, true) and PC.keys(S, sw):find("custom:555002", 1, true) ~= nil and S.slash("party add 555001 45") == "Added Hand of Test, 45 seconds." and PC.keys(S, sw):find("custom:555001", 1, true) ~= nil, PC.keys(S, sw))
	check("partyraid: add with nothing after it, hide with nothing after it and a word that is none print the three lines", (function()
		local help = "/flatui party add Pummel 12 - an ability, a spell ID or a shift-clicked spell, and its cooldown in seconds\n/flatui party hide 6552 - an ability or a spell ID\n/flatui party list - the abilities shown and who shares cooldowns"
		return S.slash("party") == help and S.slash("party add") == help and S.slash("party hide") == help and S.slash("party frobnicate") == help
	end)(), S.slash("party"))
	check("partyraid: the three lines are in the general help after the lines of the defensives", (function()
		local all = S.slash("help me")
