		local three = all:find("/flatui party add Pummel 12 - an ability, a spell ID or a shift-clicked spell, and its cooldown in seconds\n/flatui party hide 6552 - an ability or a spell ID\n/flatui party list - the abilities shown and who shares cooldowns", 1, true)
		return after ~= nil and three ~= nil and after < three
	end)())
	-- The list.
	TOC.pchear(S, "1 C 6552 7", "Mate2")
	local list = S.slash("party list")
	check("partyraid: list prints the abilities shown, a line for each class, and the abilities added by spell ID", has(list, "Warrior: ") and has(list, "Mage: ") and has(list, "Counterspell") and has(list, "Added by spell ID: Hand of Test, Test Strike") and has(list, "Any class: ") and not has(list, "Pummel"), list:sub(1, 300))
	check("partyraid: and for each member whether he shares cooldowns: Mate2 does after his message, the others do not", has(list, "Mate2: shares cooldowns") and has(list, "Mate1: does not share cooldowns") and has(list, "Mate3: does not share cooldowns") and not has(list, "Mine"), list:sub(-200))
	check("partyraid: out of a party list says so after the abilities", has(PC.world({ group = false }).slash("party list"), "Not in a party."))
	check("partyraid: with every ability hidden or off list says so", (function()
		local E = PC.world({ opts = { saved = { options = { ["partycd.interrupts"] = false, ["partycd.defensives"] = false, ["partycd.externals"] = false } } } })
		for _, line in ipairs(E.ns.PartyAbilityShown()) do
			E.ns.PartyAbilityHide(line[1])
		end
		return has(E.slash("party list"), "No abilities shown.")
	end)())
	-- A fight and the page off.
	local F = PC.world({ setup = function(X)
		X.addSpell(555001, { name = "Hand of Test" })
	end })
	F.beginFight()
	local frames = #F.addonFrames
	local fok = F.ns.PartyAbilityAdd("WARRIOR:Intimidating Shout")
	F.slash("party add 555001 30")
	check("partyraid: in a fight a change is saved and drawn at once, and no frame is made", fok == true and F.env.FlatUIDB.abilities.party.added["WARRIOR:Intimidating Shout"] == true and PC.keys(F, PC.row(F, PC.guid[2])):find("^WARRIOR:Intimidating Shout") ~= nil
		and #F.addonFrames == frames and PC.ok(F), PC.why(F))
	F.endFight()
	local Off = PC.world({ opts = { saved = { options = { ["partycd.enabled"] = false } } } })
	check("partyraid: with the page off the words and the lines still work and change what is saved", Off.slash("party add Intimidating Shout") == "Added Intimidating Shout (Warrior)." and Off.env.FlatUIDB.abilities.party.added["WARRIOR:Intimidating Shout"] == true and PC.ok(Off), PC.why(Off))
	-- Saved lists that are damaged.
	local D = PC.world({ opts = { saved = { options = {}, abilities = { party = { added = { ["WARRIOR:Intimidating Shout"] = true, [5] = true, ["x"] = "yes", ["WARRIOR:Charge"] = false },
		hidden = "none", seconds = { ["WARRIOR:Pummel"] = 0, ["WARRIOR:Shield Bash"] = 20, ["MAGE:Blink"] = "ten", ["MAGE:Frost Nova"] = 7.5 },
		custom = { [555001] = { seconds = 30, name = "Hand of Test" }, [0] = { seconds = 30, name = "Zero" }, [555002] = { seconds = "x", name = "Bad" }, [555003] = "no", [555004] = { seconds = 30, name = "" } } } } } }, setup = function(X)
		X.addSpell(555001, { name = "Hand of Test" })
	end })
	local saved = D.ns.Account().abilities.party
	check("partyraid: saved lists that are damaged lose the damaged entries only", saved.added["WARRIOR:Intimidating Shout"] == true and saved.added[5] == nil and saved.added.x == nil and saved.added["WARRIOR:Charge"] == nil and next(saved.hidden) == nil
		and saved.seconds["WARRIOR:Pummel"] == nil and saved.seconds["WARRIOR:Shield Bash"] == 20 and saved.seconds["MAGE:Blink"] == nil and saved.seconds["MAGE:Frost Nova"] == nil and saved.custom[555004] == nil and saved.custom[555001] ~= nil and saved.custom[0] == nil and saved.custom[555002] == nil and saved.custom[555003] == nil and PC.ok(D), PC.why(D))
	check("partyraid: and the rows use what is left", PC.keys(D, PC.row(D, PC.guid[2])):find("^WARRIOR:Intimidating Shout,WARRIOR:Pummel") ~= nil and not PC.keys(D, PC.row(D, PC.guid[2])):find("custom:555001", 1, true), PC.keys(D, PC.row(D, PC.guid[2])))
	-- The most.
	local M = PC.world({ setup = function(X)
		for id = 700001, 700031 do
			X.addSpell(id, { name = "Test Spell " .. id })
		end
	end })
	for id = 700001, 700030 do
		M.slash("party add " .. id .. " 30")
	end
	check("partyraid: thirty added abilities are taken, and the next is told that thirty is the most", M.slash("party add 700031 30") == "30 added abilities is the most." and M.env.FlatUIDB.abilities.party.custom[700031] == nil and M.slash("party add Intimidating Shout") == "30 added abilities is the most.")
	check("partyraid: nothing in this section broke a rule of the client", PC.ok(W) and PC.ok(R) and PC.ok(S) and PC.ok(F) and PC.ok(D) and PC.ok(M), PC.why(S))
end
do
	-- A client without the calls, and the file under Lua 5.1 rules.
	local PC = TOC.pc
	local W = PC.world({ setup = function(X)
		X.env.C_Spell.GetSpellName = nil
	end })
	check("partyraid: a client with no spell names adds no spell by ID and raises nothing", W.slash("party add 12345 30") == 'No spell found for "12345".' and PC.ok(W), PC.why(W))
	local N = PC.world({ setup = function(X)
		X.env.FlatUIDB = nil
	end })
	check("partyraid: the file has at most 120 locals, so that nothing needs a second file", loadfile(ADDON_DIR .. "/PartyCooldowns.lua") ~= nil)
	check("partyraid: nothing in this section broke a rule of the client", PC.ok(W) and PC.ok(N), PC.why(W))
end
