-- >>> ms-help (begin)
-- Colours page and shared helpers (ms-02): the twelve rows, the bar texture list, the colour helpers, the text style, the font list, the hook helpers
-- and the outline helpers. The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local M = { BASE = "Interface\\TargetingFrame\\UI-StatusBar" }
	-- A font string that records every call, for ns.TextStyle: M.font(file, size, flags) is one at that font.
	function M.font(file, size, flags, opts)
		opts = opts or {}
		local f = { file = file, size = size, flags = flags, colour = { 1, 1, 0.5, 1 }, shadow = { 1, -1 }, calls = {} }
		function f.GetFont(_)
			if opts.getFont == "error" then
				error("GetFont failed", 0)
			end
			return f.file, f.size, f.flags
		end
		function f.SetFont(_, a, b, c)
			f.calls[#f.calls + 1] = "SetFont"
			if opts.setFont == "error" then
				error("SetFont failed", 0)
			end
			if opts.setFont == "false" then
				return false
			end
			f.file, f.size, f.flags = a, b, c
			return true
		end
		function f.GetTextColor(_)
			if opts.getColour == "error" then
				error("GetTextColor failed", 0)
			end
			return f.colour[1], f.colour[2], f.colour[3], f.colour[4]
		end
		function f.SetTextColor(_, r, g, b, a)
			f.calls[#f.calls + 1] = "SetTextColor"
			f.colour = { r, g, b, a }
		end
		function f.GetShadowOffset(_)
			return f.shadow[1], f.shadow[2]
		end
		function f.SetShadowOffset(_, x, y)
			f.calls[#f.calls + 1] = "SetShadowOffset"
			f.shadow = { x, y }
		end
		return f
	end
	function M.look(f)
		return ("%s %s %s %s,%s %s,%s"):format(f.file, tostring(f.size), tostring(f.flags), f.colour[1], f.colour[3], f.shadow[1], f.shadow[2])
	end
	function M.rgb(r, g, b)
		return r and ("%.2f,%.2f,%.2f"):format(r, g, b) or "nil"
	end

	-- The rows of the Colours page, at their defaults, and the bar texture list.
	do
		local W = newWorld({})
		W.login()
		local ns = W.ns
		local rows = { { "borderMode", "custom" }, { "reactionOwn", false }, { "reactionHostile", "ffff0000" }, { "reactionNeutral", "ffffff00" },
			{ "reactionFriendly", "ff00ff00" }, { "reactionTapped", "ff808080" }, { "powerOwn", false }, { "powerMana", "ff0000ff" }, { "powerRage", "ffff0000" },
			{ "powerEnergy", "ffffff00" }, { "powerFocus", "ffff8040" }, { "powerRunic", "ff00d1ff" } }
		local wrong = {}
		for _, row in ipairs(rows) do
			if ns.Get("general." .. row[1]) ~= row[2] then
				wrong[#wrong + 1] = row[1]
			end
		end
		check("ms-help: the twelve rows of the Colours page are at their defaults", #wrong == 0 and ns.Get("general.reactionOwn") == false, table.concat(wrong, ","))
		W.change("general.borderMode", "Your faction colour")
		ns.Set("general.borderMode", "nowhere")
		local kept = ns.Get("general.borderMode")
		ns.Set("general.reactionHostile", "ff112233")
		ns.Set("general.powerRunic", "zzz")
		check("ms-help: a choice outside its list and a colour that is no colour are refused, a valid one is kept",
			kept == "faction" and ns.Get("general.reactionHostile") == "ff112233" and ns.Get("general.powerRunic") == "ff00d1ff", kept .. ns.Get("general.reactionHostile") .. ns.Get("general.powerRunic"))
		local ids = {}
		for _, choice in ipairs(ns.BarChoices()) do
			ids[#ids + 1] = choice[1]
		end
		local withDefault = ns.BarChoices(true)
		local viaRow = ns.Choices({ choices = "BarChoices" })
		local viaDefault = ns.Choices({ choices = "BarChoicesDefault" })
		check("ms-help: the bar texture list is ten lines, a first line 'default' only when asked, and the row names the function",
			table.concat(ids, ",") == "flat,soft,shaded,gloss,stripes,edge,fade,game,skills,targeting" and #withDefault == 11 and withDefault[1][1] == "default"
			and #viaRow == 10 and viaRow[1][1] == "flat" and #viaDefault == 11, table.concat(ids, ","))
		check("ms-help: the three added textures have their names", ns.BarChoices()[8][2] == "Game status bar" and ns.BarChoices()[9][2] == "Skills bar" and ns.BarChoices()[10][2] == "Targeting bar")
		local before = ns.BarTexture()
		W.change("general.barTexture", "Game status bar")
		local game = ns.BarTexture()
		local skills, targeting = ns.BarTexture("skills"), ns.BarTexture("targeting")
		local own = ns.BarTexture("soft")
		W.change("general.barTexture", "Targeting bar")
		local followed = ns.BarTexture("default") == ns.BarTexture() and ns.BarTexture(nil) ~= skills
		check("ms-help: a bar texture is its file: none for flat, the page's with no id or 'default', the id's own otherwise, none for an id it does not know",
			before == nil and game == M.BASE and skills == "Interface\\PaperDollInfoFrame\\UI-Character-Skills-Bar" and targeting == "Interface\\TargetingFrame\\UI-TargetingFrame-BarFill"
			and own:find("Soft.tga", 1, true) and followed and ns.BarTexture("default") == targeting and ns.BarTexture("nope") == nil and ns.BarFile("game") == M.BASE,
			tostring(game) .. tostring(skills))
		W.change("general.barTexture", "Skills bar")
		check("ms-help: the choice is saved and a bar of the addon takes the file", ns.Get("general.barTexture") == "skills" and ns.BarTexture() == skills)
	end

	-- Reaction colours.
	do
		local W = newWorld({})
		W.login()
		local ns, env = W.ns, W.env
		local unit = { selection = { 0.9, 0.2, 0.1 }, reaction = 2, denied = false, controlled = false }
		env.UnitSelectionColor = function() return unit.selection[1], unit.selection[2], unit.selection[3] end
		env.UnitReaction = function(u, other) return unit.reaction end
		env.UnitIsTapDenied = function() return unit.denied end
		env.UnitPlayerControlled = function() return unit.controlled end
		local off = M.rgb(ns.ReactionColour("target"))
		W.change("general.reactionOwn", true)
		local hostile = M.rgb(ns.ReactionColour("target"))
		unit.reaction = 3
		local three = M.rgb(ns.ReactionColour("target"))
		unit.reaction = 4
		local neutral = M.rgb(ns.ReactionColour("target"))
		unit.reaction = 5
		local five = M.rgb(ns.ReactionColour("target"))
		unit.reaction = 8
		local eight = M.rgb(ns.ReactionColour("target"))
		check("ms-help: with the switch off the game's colour; with it on 3 and below is hostile, 4 neutral, 5 and above friendly", off == "0.90,0.20,0.10" and hostile == "1.00,0.00,0.00"
			and three == hostile and neutral == "1.00,1.00,0.00" and five == "0.00,1.00,0.00" and eight == five, off .. hostile .. neutral .. five)
		W.change("general.reactionFriendly", "ff0080ff")
		check("ms-help: a colour changed on the page is the colour returned", M.rgb(ns.ReactionColour("target")) == "0.00,0.50,1.00", M.rgb(ns.ReactionColour("target")))
		unit.denied = true
		local tapped = M.rgb(ns.ReactionColour("target"))
		unit.controlled = true
		local controlled = M.rgb(ns.ReactionColour("target"))
		W.change("general.reactionOwn", false)
		local game = M.rgb(ns.ReactionColour("target"))
		check("ms-help: a unit another player tapped has the tapped colour, a tapped unit a player controls does not, and with the switch off the game's colour",
			tapped == "0.50,0.50,0.50" and controlled == "0.00,0.50,1.00" and game == "0.90,0.20,0.10", tapped .. controlled .. game)
		W.change("general.reactionOwn", true)
		unit.controlled = false
		unit.denied = false
		unit.reaction = SECRET
		local fallback = M.rgb(ns.ReactionColour("target"))
		unit.reaction = 2
		unit.denied = SECRET
		local noTap = M.rgb(ns.ReactionColour("target"))
		unit.denied = false
		unit.selection = { SECRET, 0, 0 }
		unit.reaction = nil
		local none = M.rgb(ns.ReactionColour("target"))
		check("ms-help: a withheld reaction falls back to the game's colour, a withheld tap answer is no tap, and a withheld colour is nil", fallback == "0.90,0.20,0.10"
			and noTap == "1.00,0.00,0.00" and none == "nil", fallback .. noTap .. none)
		env.UnitReaction = function() error("UnitReaction failed", 0) end
		unit.selection = { 0.1, 0.2, 0.3 }
		local okRaise, raised = pcall(function() return M.rgb(ns.ReactionColour("target")) end)
		env.UnitReaction, env.UnitSelectionColor = nil, nil
		local okNone, nothing = pcall(function() return M.rgb(ns.ReactionColour("target")) end)
		check("ms-help: a call that raises or a client without the calls gives the game's colour or nil and no error", okRaise and raised == "0.10,0.20,0.30" and okNone and nothing == "nil" and ns.ReactionColour(nil) == nil,
			tostring(raised) .. tostring(nothing))
	end

	-- Power colours.
	do
		local W = newWorld({})
		W.login()
		local ns, env = W.ns, W.env
		env.PowerBarColor = { MANA = { r = 0, g = 0, b = 1 }, RAGE = { r = 1, g = 0, b = 0 }, FURY = { r = 0.79, g = 0.26, b = 0.99 }, BAD = { r = SECRET, g = 0, b = 0 } }
		local off = M.rgb(ns.PowerColour("MANA")) .. M.rgb(ns.PowerColour("RAGE"))
		W.change("general.powerOwn", true)
		W.change("general.powerMana", "ff336699")
		W.change("general.powerRunic", "ff00ffff")
		local mana, runic, focus = M.rgb(ns.PowerColour("MANA")), M.rgb(ns.PowerColour("RUNIC_POWER")), M.rgb(ns.PowerColour("FOCUS"))
		local fury, unknown, bad = M.rgb(ns.PowerColour("FURY")), M.rgb(ns.PowerColour("NOTHING")), M.rgb(ns.PowerColour("BAD"))
		check("ms-help: a power colour is the game's with the switch off and the row's with it on; a power with no row keeps the game's colour", off == "0.00,0.00,1.001.00,0.00,0.00"
			and mana == "0.20,0.40,0.60" and runic == "0.00,1.00,1.00" and focus == "1.00,0.50,0.25" and fury == "0.79,0.26,0.99", off .. mana .. runic .. focus .. fury)
		check("ms-help: a power the game does not colour, a withheld colour and a token that is not text are nil", unknown == "nil" and bad == "nil" and ns.PowerColour(nil) == nil and ns.PowerColour(SECRET) == nil
			and ns.PowerColour(7) == nil)
		env.PowerBarColor = nil
		W.change("general.powerOwn", false)
		check("ms-help: without the game's table and with the switch off a power colour is nil", ns.PowerColour("MANA") == nil and #W.violations == 0)
	end

	-- Class atlas.
	do
		local W = newWorld({})
		W.login()
		local ns, env = W.ns, W.env
		local asked = {}
		env.C_Texture = { GetAtlasExists = function(name) asked[#asked + 1] = name return name == "classicon-warrior" or name == "groupfinder-icon-class-mage" end }
		local warrior, mage, ghost = ns.ClassAtlas("WARRIOR"), ns.ClassAtlas("MAGE"), ns.ClassAtlas("GHOST")
		local again = ns.ClassAtlas("WARRIOR")
		local calls = #asked
		ns.ClassAtlas("WARRIOR")
		check("ms-help: the class atlas is the first name the game has, each class is asked once, and a class with none is nil", warrior == "classicon-warrior" and mage == "groupfinder-icon-class-mage"
			and ghost == nil and again == warrior and calls == #asked, tostring(warrior) .. tostring(mage) .. tostring(ghost))
		check("ms-help: the status names a class without art", has(W.status(), "Class icons: no class art for GHOST."), W.status())
		env.C_Texture = { GetAtlasInfo = function(name) return name == "classicon-priest" and {} or nil end }
		check("ms-help: a client with only GetAtlasInfo is asked that way", ns.ClassAtlas("PRIEST") == "classicon-priest")
		env.C_Texture = nil
		check("ms-help: a client without the atlas calls has no class atlas, a token that is not text is nil", ns.ClassAtlas("DRUID") == nil and ns.ClassAtlas(nil) == nil and ns.ClassAtlas(SECRET) == nil)
	end

	-- The border colour source, and the outline helpers.
	do
		local W = newWorld({})
		W.login()
		local ns, env = W.ns, W.env
		env.UnitClass = function() return "Warrior", "WARRIOR", 1 end
		env.RAID_CLASS_COLORS = { WARRIOR = { r = 0.78, g = 0.61, b = 0.43 } }
		env.UnitFactionGroup = function() return "Alliance" end
		W.change("general.border", "ff336699")
		local frame = W.B(nil, {})
		local o = ns.Outline(frame, frame)
		local custom = M.rgb(ns.BorderRGB())
		local look = W.look(frame)
		local paintedCustom = M.rgb(look.r, look.g, look.b)
		W.change("general.borderMode", "Your class colour")
		look = W.look(frame)
		local paintedClass = M.rgb(look.r, look.g, look.b)
		W.change("general.borderMode", "Your faction colour")
		look = W.look(frame)
		local paintedAlliance = M.rgb(look.r, look.g, look.b)
		env.UnitFactionGroup = function() return "Horde" end
		W.change("general.borderMode", "Border colour on the Flat UI page")
		W.change("general.borderMode", "Your faction colour")
		local horde = M.rgb(ns.BorderRGB())
		check("ms-help: the default source gives the Border colour, as before, and the edges are painted with it", custom == "0.20,0.40,0.60" and paintedCustom == custom, custom .. paintedCustom)
		check("ms-help: the class source gives the class colour of the player, the faction source the colour of Alliance or Horde, and the edges take them at once",
			paintedClass == "0.78,0.61,0.43" and paintedAlliance == "0.29,0.33,0.91" and horde == "0.90,0.05,0.07", paintedClass .. paintedAlliance .. horde)
		env.UnitFactionGroup = function() return SECRET end
		local secretFaction = M.rgb(ns.BorderRGB())
		env.UnitFactionGroup = function() return nil end
		local noFaction = M.rgb(ns.BorderRGB())
		env.UnitFactionGroup = nil
		local noCall = M.rgb(ns.BorderRGB())
		W.change("general.borderMode", "Your class colour")
		env.UnitClass = function() return SECRET, SECRET, SECRET end
		local noClass = M.rgb(ns.BorderRGB())
		check("ms-help: an unknown or withheld faction or class gives the Border colour", secretFaction == "0.20,0.40,0.60" and noFaction == secretFaction and noCall == secretFaction and noClass == secretFaction,
			secretFaction .. noFaction .. noCall .. noClass)
		W.change("general.borderMode", "Border colour on the Flat UI page")
		W.change("general.borderless", true)
		check("ms-help: Borderless still hides the edges whatever the source", W.look(frame).hidden)
		W.change("general.borderless", false)
		ns.SetOutlineEdges(o, false)
		local hidden = W.state(frame)
		ns.SetOutlineEdges(o, true)
		local shown = W.state(frame)
		ns.SetOutlineEdges(nil, false)
		check("ms-help: an outline's edges go off and on alone, the backdrop stays, and nil is no error", hidden == "hB" and shown == "SB" and #W.violations == 0, hidden .. shown)
		ns.SetOutlineAlpha(o, 0.4, 0.25)
		look = W.look(frame)
		check("ms-help: an outline's own opacity is on its edges and on a backdrop with no fill of its own", near(look.edges[1].color[4], 0.4) and near(look.backdrop.color[4], 0.25),
			tostring(look.edges[1].color[4]) .. tostring(look.backdrop.color[4]))
		ns.SetOutlineFill(o, 0.1, 0.1, 0.1, 0.9)
		look = W.look(frame)
		local ownFill = near(look.backdrop.color[4], 0.9)
		ns.SetOutlineFill(o, nil, nil, nil, nil)
		ns.SetOutlineAlpha(o, nil, nil)
		look = W.look(frame)
		check("ms-help: a fill of its own keeps its opacity, and with none given the outline is full edges and the general opacity again", ownFill and near(look.edges[1].color[4], 1)
			and near(look.backdrop.color[4], ns.Get("general.backdropAlpha") / 100), tostring(look.backdrop.color[4]))
	end

	-- The text style.
	do
		local W = newWorld({})
		W.login()
		local ns = W.ns
		local f = M.font("Fonts\\FRIZQT__.TTF", 12, "OUTLINE")
		check("ms-help: a style of nothing makes no call, and a value that is no font string is nil", ns.TextStyle(f, {}) == true and ns.TextStyle(f) == true and #f.calls == 0
			and ns.TextStyle(nil, {}) == nil and ns.TextStyle(SECRET, {}) == nil and ns.TextStyle(5, {}) == nil)
		local set = ns.TextStyle(f, { percent = 150, face = "Fonts\\ARIALN.TTF", flags = "", r = 1, g = 0, b = 0, a = 0.5, shadow = true })
		check("ms-help: a size, a face, flags, a colour and a shadow are set in one call each", set == true and f.file == "Fonts\\ARIALN.TTF" and f.size == 18 and f.flags == "" and f.colour[1] == 1
			and f.colour[2] == 0 and f.colour[4] == 0.5 and f.shadow[1] == 0 and f.shadow[2] == 0 and #f.calls == 3, M.look(f))
		check("ms-help: nothing is called again for the same style", ns.TextStyle(f, { percent = 150, face = "Fonts\\ARIALN.TTF", flags = "", r = 1, g = 0, b = 0, a = 0.5, shadow = true }) == true and #f.calls == 3,
			table.concat(f.calls, ","))
		check("ms-help: a part passed as nil goes back, the others stay", ns.TextStyle(f, { percent = 150, face = "Fonts\\ARIALN.TTF", flags = "", shadow = true }) == true and f.colour[1] == 1 and f.colour[2] == 1
			and f.colour[3] == 0.5 and f.shadow[1] == 0 and f.size == 18, M.look(f))
		check("ms-help: an empty style puts everything back", ns.TextStyle(f, {}) == true and f.file == "Fonts\\FRIZQT__.TTF" and f.size == 12 and f.flags == "OUTLINE" and f.colour[1] == 1 and f.colour[3] == 0.5
			and f.shadow[1] == 1 and f.shadow[2] == -1, M.look(f))
		local g = M.font("Fonts\\FRIZQT__.TTF", 10, "")
		ns.TextStyle(g, { percent = 200 })
		g.file, g.size = "Fonts\\SKURRI.TTF", 14
		ns.TextStyle(g, { percent = 100, face = "Fonts\\ARIALN.TTF" })
		check("ms-help: a font the game set again is the new base", g.file == "Fonts\\ARIALN.TTF" and g.size == 14, M.look(g))
		ns.TextStyle(g, {})
		check("ms-help: and goes back to that base, not to the first", g.file == "Fonts\\SKURRI.TTF" and g.size == 14, M.look(g))
		local k = M.font("Fonts\\FRIZQT__.TTF", 10, "")
		ns.TextStyle(k, { face = "Fonts\\ARIALN.TTF" })
		k.file = "Fonts\\SKURRI.TTF"
		ns.TextStyle(k, { face = "Fonts\\ARIALN.TTF" })
		local again = k.file
		ns.TextStyle(k, {})
		check("ms-help: a face set here that the game replaced by another at the same size is set again, and the game's file is the base", again == "Fonts\\ARIALN.TTF" and k.file == "Fonts\\SKURRI.TTF" and k.size == 10, again .. k.file)
		local h = M.font("Fonts\\FRIZQT__.TTF", 10, "")
		ns.TextSize(h, 150)
		local sized = h.size
		ns.TextSize(h, 100)
		ns.TextSize(h, 120, "OUTLINE")
		local flagged = h.flags
		ns.TextSize(h, 100, nil)
		check("ms-help: ns.TextSize is a style of a size and flags, as it was", sized == 15 and h.size == 10 and flagged == "OUTLINE" and h.flags == "" and ns.TextSize(M.font("a", 10, ""), 100) == true)
		local e1 = M.font("Fonts\\FRIZQT__.TTF", 10, "", { setFont = "error" })
		local e2 = M.font("Fonts\\FRIZQT__.TTF", 10, "", { setFont = "false" })
		local e3 = M.font("Fonts\\FRIZQT__.TTF", 10, "", { getFont = "error" })
		local e4 = M.font("Fonts\\FRIZQT__.TTF", 10, "", { getColour = "error" })
		local noRaise = pcall(function() ns.TextStyle(e1, { percent = 150 }) end)
		check("ms-help: a SetFont that raises, a face the game answers false to and a font that cannot be read are false and no error", noRaise and ns.TextStyle(e1, { percent = 150 }) == false
			and ns.TextStyle(e2, { face = "Fonts\\MISSING.TTF" }) == false and e2.file == "Fonts\\FRIZQT__.TTF" and ns.TextStyle(e3, { percent = 150 }) == false)
		check("ms-help: a size the game answers false to is not a refusal, and a colour that cannot be read stops before anything is set", ns.TextStyle(e2, { percent = 150 }) == true
			and ns.TextStyle(e4, { percent = 150, r = 1, g = 1, b = 1 }) == false and #e4.calls == 0, table.concat(e4.calls, ","))
	end

	-- The font list.
	do
		local W = newWorld({})
		W.fontReturn = "true"
		W.login()
		local ns = W.ns
		local before = W.status()
		local list = ns.FontChoices()
		local ids = {}
		for _, choice in ipairs(list) do
			ids[#ids + 1] = choice[1]
		end
		check("ms-help: the font list is 'default' and the four faces the client loads, with their files", table.concat(ids, ",") == "default,friz,arial,morpheus,skurri" and ns.FontFile("friz") == "Fonts\\FRIZQT__.TTF"
			and ns.FontFile("arial") == "Fonts\\ARIALN.TTF" and ns.FontFile("morpheus") == "Fonts\\MORPHEUS.TTF" and ns.FontFile("skurri") == "Fonts\\SKURRI.TTF" and ns.FontFile("default") == nil
			and ns.FontFile("comic") == nil and #W.violations == 0, table.concat(ids, ",") .. table.concat(W.violations, "|"))
		check("ms-help: the status lists the faces once they were tried, and not before", not has(before, "Fonts offered") and has(W.status(), "Fonts offered: friz, arial, morpheus, skurri"), W.status())
		local N = newWorld({})
		N.fontReturn = "false"
		N.login()
		check("ms-help: a client that says no to every face offers only the default and says so", #N.ns.FontChoices() == 1 and N.ns.FontFile("friz") == nil and has(N.status(), "Fonts offered: none"), N.status())
		local R = newWorld({})
		R.fontReturn = "error"
		R.login()
		local okR, listR = pcall(R.ns.FontChoices)
		check("ms-help: a client that raises on a face is no error and offers none", okR and #listR == 1 and R.ns.FontFile("skurri") == nil)
	end

	-- Own text, and the hooks.
	do
		local W = newWorld({})
		W.login()
		local ns, env = W.ns, W.env
		local parent, forbidden = W.B(nil, {}), W.B(nil, {}, { forbidden = true })
		local text = ns.OwnText(parent, "OVERLAY", "GameFontNormal")
		local plain = ns.OwnText(parent)
		check("ms-help: an own font string on a frame, in the layer and font given or in OVERLAY with none; none on a frame the addon may not touch", text ~= nil and plain ~= nil and ns.OwnText(forbidden) == nil
			and ns.OwnText(nil) == nil and #W.violations == 0, table.concat(W.violations, "|"))
		local seen, errors = {}, {}
		env.geterrorhandler = function() return function(e) errors[#errors + 1] = tostring(e) end end
		local source = { run = function() return "result" end }
		local hooked = 0
		local real = env.hooksecurefunc
		env.hooksecurefunc = function(...)
			hooked = hooked + 1
			return real(...)
		end
		local function one(...) seen[#seen + 1] = "one:" .. table.concat({ ... }, ",") end
		local function two(...) seen[#seen + 1] = "two:" .. table.concat({ ... }, ",") end
		local a, b, c = ns.FollowTable(source, "run", one), ns.FollowTable(source, "run", two), ns.FollowTable(source, "run", one)
		local result = source.run(1, 2)
		check("ms-help: a call is hooked once for any number of functions, each runs after it with its arguments, and the same function is not added twice", a == true and b == true and c == true and hooked == 1
			and result == "result" and table.concat(seen, " ") == "one:1,2 two:1,2", table.concat(seen, " ") .. hooked)
		ns.FollowTable(source, "run", function() error("follower failed", 0) end)
		seen = {}
		source.run(3)
		check("ms-help: a follower that fails goes to the error handler and the others still run", table.concat(seen, " ") == "one:3 two:3" and #errors == 1 and errors[1]:find("follower failed", 1, true), table.concat(errors, "|"))
		env.FlatUIGlobalCall = function() end
		local g = ns.FollowGlobal("FlatUIGlobalCall", function(...) seen[#seen + 1] = "global" end)
		env.FlatUIGlobalCall()
		local frameOk = ns.Follow(parent, "Show", function() end)
		check("ms-help: a global function is followed by name, a frame method on a frame the addon may touch", g == true and seen[#seen] == "global" and frameOk == true and #W.violations == 0, tostring(frameOk) .. table.concat(W.violations, "|"))
		check("ms-help: nothing to follow gives nil: a missing global, a missing method, a forbidden frame, a secret or non-table source, a method that is no name", ns.FollowGlobal("FlatUINoSuchCall", one) == nil
			and ns.FollowTable(source, "none", one) == nil and ns.Follow(forbidden, "Show", one) == nil and ns.FollowTable(SECRET, "run", one) == nil and ns.FollowTable(5, "run", one) == nil
			and ns.Follow(parent, 7, one) == nil)
		local before = hooked
		check("ms-help: a follower that is no function is false and hooks nothing", ns.FollowTable(source, "run", "no") == false and ns.FollowGlobal("FlatUIGlobalCall", nil) == false and hooked == before)
		env.hooksecurefunc = nil
		local later = { other = function() end }
		check("ms-help: without hooksecurefunc nothing is hooked and nothing raises", ns.FollowTable(later, "other", one) == false and ns.FollowGlobal("FlatUIGlobalCall", two) == true)
		env.hooksecurefunc = function() error("hook refused", 0) end
		check("ms-help: a hook the game refuses is false and not an error", ns.FollowTable({ x = function() end }, "x", one) == false)
	end

	-- Events added to a module.
	do
		local W = newWorld({})
		W.login()
		local ns = W.ns
		local ran = {}
		local handlers = { PING = function(...) ran[#ran + 1] = "own:" .. table.concat({ ... }, ",") end }
		ns.Register("mshelp", { label = "Test module", events = handlers, filters = { PING = function(a) return a ~= "skip" end } })
		local added = ns.AddEvent("mshelp", "PING", function(...) ran[#ran + 1] = "added:" .. table.concat({ ... }, ",") end)
		local filtered = ns.AddEvent("mshelp", "PING", function(...) ran[#ran + 1] = "only:" .. table.concat({ ... }, ",") end, function(a) return a == "only" end)
		local events = handlers.PING
		check("ms-help: a handler is added to a module that has one, the module's own stays first", added == true and filtered == true and type(events) == "function", tostring(added))
		events("go", 1)
		local order = table.concat(ran, " ")
		ran = {}
		events("only")
		local onlyOrder = table.concat(ran, " ")
		check("ms-help: every handler runs in order with the arguments of the event, and a handler's filter says when it runs", order == "own:go,1 added:go,1" and onlyOrder == "own:only added:only only:only", order .. "|" .. onlyOrder)
		local newEvent = ns.AddEvent("mshelp", "PONG", function() ran[#ran + 1] = "pong" end)
		check("ms-help: an event the module did not have is added, an unknown module or a bad call is false", newEvent == true and type(handlers.PONG) == "function" and ns.AddEvent("nobody", "PING", function() end) == false
			and ns.AddEvent("mshelp", "PING", nil) == false and ns.AddEvent("mshelp", 7, function() end) == false)
		ran = {}
		ns.AddEvent("mshelp", "FAIL", function() ran[#ran + 1] = "first" error("handler failed", 0) end)
		ns.AddEvent("mshelp", "FAIL", function() ran[#ran + 1] = "second" end)
		local ok, err = pcall(handlers.FAIL)
		check("ms-help: a handler that fails does not stop the ones after it, and its error is raised after them", not ok and err == "handler failed" and table.concat(ran, " ") == "first second", tostring(err) .. table.concat(ran, " "))
	end
end
-- >>> ms-help (end)
-- >>> ms-uftext (begin)
-- Name, level and bar text style of the unit frames (ms-11): the name rows of the All frames: text page, the Name switch of each frame page and the bar text rows. Every
-- label starts "ms-uftext:". The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local MX = { OUT = "OUTLINE, THICK" }
	function MX.world()
		local W = FH.ufWorld({ fontReturn = "true" })
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local U, env = W.uf, W.env
		U.who = { player = { player = true, class = "WARLOCK" }, target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } },
			focus = { player = true, class = "ROGUE" }, party1 = { player = true, class = "PRIEST" } }
		env.RAID_CLASS_COLORS = { WARLOCK = setmetatable({ r = 0.58, g = 0.51, b = 0.79, a = 1 }, COLOUR_MT), ROGUE = setmetatable({ r = 1, g = 0.96, b = 0.41, a = 1 }, COLOUR_MT),
			PRIEST = setmetatable({ r = 1, g = 1, b = 1, a = 1 }, COLOUR_MT), WARRIOR = setmetatable({ r = 0.78, g = 0.61, b = 0.43, a = 1 }, COLOUR_MT) }
		env.UnitIsPlayer = function(unit) return U.who[unit] ~= nil and U.who[unit].player end
		env.UnitClass = function(unit)
			local who = U.who[unit]
			if who == nil then
				return "Warlock", "WARLOCK", 9
			end
			return who.class:sub(1, 1) .. who.class:sub(2):lower(), who.class, 1
		end
		env.UnitSelectionColor = function(unit)
			local c = U.who[unit] and U.who[unit].reaction or { 1, 1, 0 }
			return c[1], c[2], c[3], 1
		end
		-- The pet has a name: the game writes it with the call it makes for each unit.
		U.names.pet = "Rex"
		for frame, fs in pairs(U.nameOf) do
			if fs == W.pet.nameText then
				W.blizzard(function() env.UnitFrame_Update(frame) end)
			end
		end
		W.flush()
		return W
	end
	function MX.row(W, text)
		for _, font in ipairs(W.addonFonts) do
			if font.text == text then
				return font
			end
		end
	end
	function MX.pet(W) return MX.row(W, W.rawOf[W.pet.nameText].text) end
	function MX.font(raw) local f = raw.font or { "Fonts\\FRIZQT__.TTF", 12, "" } return f[1] .. "|" .. string.format("%.2f", f[2]) .. "|" .. tostring(f[3]) end
	function MX.rgb(font) local c = font and font.textColour return c and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) or "none" end
	function MX.silent(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "failed") and not has(W.status(), "stopped") end
	function MX.why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. tostring(W.line("Unit frames")) end
	function MX.snap(W)
		local P, T, Pet, F = W.player, W.target, W.pet, W.focus
		return table.concat({ MX.font(MX.row(W, "Dxml Bozo")), MX.rgb(MX.row(W, "Dxml Bozo")), MX.font(MX.pet(W)), MX.rgb(MX.pet(W)), MX.font(W.rawOf[Pet.nameText]),
			MX.font(W.rawOf[P.healthWords[1]]), MX.font(W.rawOf[P.powerWords[1]]), MX.font(W.rawOf[T.healthWords[1]]), MX.font(W.rawOf[F.healthWords[1]]),
			tostring(MX.row(W, "Dxml Bozo").shown), tostring(W.rawOf[Pet.nameText].alpha) }, " ; ")
	end

	local W = MX.world()
	local P, T, Pet, F = W.player, W.target, W.pet, W.focus

	-- The rows: pages and defaults.
	do
		local want = { nameFace = "default", nameSize = 100, nameOutline = "game", nameColour = "game", nameCustom = "ffffd100", barTextFace = "default", barTextOutline = "game",
			barTextColourOwn = false, barTextColour = "ffffffff", playerName = true, targetName = true, focusName = true, petName = true, totName = true, partyName = true, bossName = true }
		local wrong, byKey = {}, {}
		for key, default in pairs(want) do
			if W.ns.Get("unitframes." .. key) ~= default or W.control("unitframes." .. key) == nil then
				wrong[#wrong + 1] = key
			end
		end
		check("ms-uftext: the sixteen rows are there with their defaults", #wrong == 0 and #W.ns.PAGES > 0, table.concat(wrong, " "))
		for _, page in ipairs(W.ns.PAGES) do
			for _, item in ipairs(page) do
				if item.key then
					byKey[item.key] = page.key
				end
			end
		end
		local pages = { nameFace = "unitframesText", nameCustom = "unitframesText", barTextColour = "unitframesText", playerName = "unitframesPlayer", targetName = "unitframesTarget",
			focusName = "unitframesFocus", petName = "unitframesPet", totName = "unitframesTot", partyName = "unitframesParty", bossName = "unitframesBoss" }
		wrong = {}
		for key, page in pairs(pages) do
			if byKey[key] ~= page then
				wrong[#wrong + 1] = key .. "@" .. tostring(byKey[key])
			end
		end
		check("ms-uftext: each row is on its page", #wrong == 0, table.concat(wrong, " "))
		check("ms-uftext: Level colour and Level size are not given a second row", byKey.levelColour == "unitframes" and byKey.levelSize == "unitframes" and byKey.levelCustom == nil)
	end

	-- Every row at its default: the frames are as the game and the earlier rows leave them.
	MX.off = MX.snap(W)
	local names0 = MX.row(W, "Dxml Bozo")
	check("ms-uftext: with every row at its default the name, its colour, the bar text and the name of a small frame are the usual ones",
		names0 ~= nil and MX.font(W.rawOf[P.nameText]) == "Fonts\\FRIZQT__.TTF|10.00|" and MX.rgb(names0) == "1.00,0.82,0.00" and MX.font(W.rawOf[Pet.nameText]) == "Fonts\\FRIZQT__.TTF|7.00|" and MX.pet(W) ~= nil
		and MX.silent(W), MX.off .. " " .. MX.why(W))

	-- Font, size and outline of the name.
	W.change("unitframes.nameFace", "Arial Narrow")
	check("ms-uftext: Name font sets the face of the name row, and not the game's own text under the row", MX.font(MX.row(W, "Dxml Bozo")) == "Fonts\\ARIALN.TTF|10.00|"
		and MX.font(MX.pet(W)) == "Fonts\\ARIALN.TTF|7.00|" and MX.font(W.rawOf[Pet.nameText]) == "Fonts\\FRIZQT__.TTF|7.00|" and MX.font(W.rawOf[P.nameText]) == "Fonts\\FRIZQT__.TTF|10.00|" and MX.silent(W), MX.snap(W) .. MX.why(W))
	W.change("unitframes.nameSize", 150)
	check("ms-uftext: Name size is a share of the size the row has, and on a small frame of the size Small frame text size gives", MX.font(MX.row(W, "Dxml Bozo")) == "Fonts\\ARIALN.TTF|15.00|"
		and MX.font(MX.pet(W)) == "Fonts\\ARIALN.TTF|10.50|", MX.snap(W))
	W.change("unitframes.nameOutline", "Thick")
	check("ms-uftext: Name outline thick sets the flags on the row and on a small frame", MX.font(MX.row(W, "Dxml Bozo")) == "Fonts\\ARIALN.TTF|15.00|" .. MX.OUT
		and MX.font(MX.pet(W)) == "Fonts\\ARIALN.TTF|10.50|" .. MX.OUT, MX.snap(W))
	W.change("unitframes.nameOutline", "None")
	check("ms-uftext: Name outline none sets empty flags", MX.font(MX.row(W, "Dxml Bozo")):sub(-1) == "|" and MX.font(MX.pet(W)):sub(-1) == "|", MX.snap(W))
	W.change("unitframes.nameFace", "Game font")
	W.change("unitframes.nameSize", 100)
	W.change("unitframes.nameOutline", "As the game has it")
	check("ms-uftext: the three rows at their defaults again put the game's font back, and the game's text was never set", MX.snap(W) == MX.off and MX.silent(W), MX.snap(W) .. " / " .. MX.off)

	-- Colour of the name.
	W.change("unitframes.nameColour", "Custom")
	W.change("unitframes.nameCustom", "ff336699")
	check("ms-uftext: Custom name colour is the colour of the row's name and of a small frame's name", MX.rgb(MX.row(W, "Dxml Bozo")) == "0.20,0.40,0.60" and MX.rgb(MX.pet(W)) == "0.20,0.40,0.60", MX.snap(W))
	W.change("unitframes.nameColour", "Class")
	check("ms-uftext: Class colours a player's name with the class colour and a unit that is no player with its reaction colour", MX.rgb(MX.row(W, "Dxml Bozo")) == "0.58,0.51,0.79"
		and MX.rgb(MX.row(W, "Target")) == "0.90,0.10,0.10", MX.rgb(MX.row(W, "Dxml Bozo")) .. " " .. MX.rgb(MX.row(W, "Target")))
	W.change("unitframes.nameColour", "Reaction")
	check("ms-uftext: Reaction colours the name by how the unit stands to the player", MX.rgb(MX.row(W, "Target")) == "0.90,0.10,0.10" and MX.rgb(MX.row(W, "Dxml Bozo")) == "1.00,1.00,0.00", MX.rgb(MX.row(W, "Dxml Bozo")))
	W.change("unitframes.nameColour", "Class")
	W.change("unitframes.levelColour", "Same as the name")
	check("ms-uftext: a level that follows the name has the name's colour", MX.rgb(MX.row(W, "60")) == "0.58,0.51,0.79", MX.rgb(MX.row(W, "60")))
	W.change("unitframes.levelColour", "By difficulty")
	W.change("unitframes.lookWhiteNames", true)
	check("ms-uftext: a name colour other than the game's wins over White names", MX.rgb(MX.row(W, "Dxml Bozo")) == "0.58,0.51,0.79", MX.rgb(MX.row(W, "Dxml Bozo")))
	W.change("unitframes.nameColour", "As the game has it")
	W.change("unitframes.lookWhiteNames", false)
	W.change("unitframes.lookWhiteNames", true)
	check("ms-uftext: As the game has it leaves White names to make the name white", MX.rgb(MX.row(W, "Dxml Bozo")) == "1.00,1.00,1.00", MX.rgb(MX.row(W, "Dxml Bozo")))
	W.change("unitframes.lookWhiteNames", false)
	check("ms-uftext: and with that off the name has the game's colour again", MX.snap(W) == MX.off and MX.silent(W), MX.snap(W))

	-- A new target: the colour follows the unit.
	W.change("unitframes.nameColour", "Class")
	W.uf.who.target = { player = true, class = "ROGUE" }
	W.blizzard(function() W.env.UnitFrame_Update(T.frame) end)
	check("ms-uftext: a new unit on a frame has the colour of its own class", MX.rgb(MX.row(W, "Target")) == "1.00,0.96,0.41", MX.rgb(MX.row(W, "Target")))
	W.change("unitframes.nameColour", "As the game has it")

	-- The Name switch.
	W.change("unitframes.playerName", false)
	W.change("unitframes.petName", false)
	check("ms-uftext: Name off hides the name in the row of that frame only", MX.row(W, "Dxml Bozo").shown == false and MX.pet(W).shown == false and MX.row(W, "Target").shown == true and MX.silent(W),
		tostring(MX.row(W, "Dxml Bozo").shown) .. tostring(MX.pet(W).shown))
	W.change("unitframes.playerName", true)
	W.change("unitframes.petName", true)
	check("ms-uftext: Name on shows them again as before", MX.snap(W) == MX.off, MX.snap(W))
	W.change("unitframes.playerName", false)
	W.blizzard(W.env.PlayerFrame_UpdateLevel)
	check("ms-uftext: Name off stays off when the game updates the level of the player frame", MX.row(W, "Dxml Bozo").shown == false, tostring(MX.row(W, "Dxml Bozo").shown))
	W.change("unitframes.playerName", true)

	-- Frames without a name row: the game's own name text takes the rows.
	W.change("unitframes.smallRow", false)
	W.change("unitframes.strip", false)
	MX.plain = MX.snap(W)
	W.change("unitframes.nameFace", "Arial Narrow")
	W.change("unitframes.nameSize", 150)
	W.change("unitframes.nameColour", "Custom")
	check("ms-uftext: without a name row the face, the size and the colour are set on the game's name text, on a large frame and on a small one", MX.font(W.rawOf[P.nameText]) == "Fonts\\ARIALN.TTF|15.00|"
		and MX.font(W.rawOf[Pet.nameText]) == "Fonts\\ARIALN.TTF|10.50|" and MX.rgb(W.rawOf[P.nameText]) == "0.20,0.40,0.60" and MX.rgb(W.rawOf[Pet.nameText]) == "0.20,0.40,0.60" and MX.silent(W),
		MX.font(W.rawOf[P.nameText]) .. " " .. MX.font(W.rawOf[Pet.nameText]) .. " " .. MX.why(W))
	W.change("unitframes.playerName", false)
	W.change("unitframes.petName", false)
	check("ms-uftext: and Name off makes that text transparent", W.rawOf[P.nameText].alpha == 0 and W.rawOf[Pet.nameText].alpha == 0 and W.rawOf[T.nameText].alpha ~= 0, tostring(W.rawOf[P.nameText].alpha))
	W.change("unitframes.playerName", true)
	W.change("unitframes.petName", true)
	W.change("unitframes.nameFace", "Game font")
	W.change("unitframes.nameSize", 100)
	W.change("unitframes.nameColour", "As the game has it")
	check("ms-uftext: with the rows as the game has them the text is the game's again", MX.snap(W) == MX.plain and MX.silent(W), MX.snap(W) .. " / " .. MX.plain)
	W.change("unitframes.smallRow", true)
	W.change("unitframes.strip", true)
	check("ms-uftext: and with the rows back the frames are as at the start", MX.snap(W) == MX.off, MX.snap(W))
	W.change("unitframes.strip", false)
	W.change("unitframes.nameSize", 150)
	W.change("unitframes.nameColour", "Custom")
	W.change("unitframes.strip", true)
	W.change("unitframes.nameSize", 100)
	W.change("unitframes.nameColour", "As the game has it")
	check("ms-uftext: styling set on the game's name text while the row was off is gone when the row is back and the rows are at their defaults", MX.snap(W) == MX.off, MX.snap(W) .. " / " .. MX.off)

	-- Bar text.
	W.change("unitframes.barTextFace", "Morpheus")
	check("ms-uftext: Bar text font sets the face on the health and power words of every frame and keeps their sizes", MX.font(W.rawOf[P.healthWords[1]]):find("^Fonts\\MORPHEUS.TTF|12.00") ~= nil
		and MX.font(W.rawOf[P.powerWords[1]]):find("^Fonts\\MORPHEUS.TTF|10.20") ~= nil and MX.font(W.rawOf[T.healthWords[1]]):find("^Fonts\\MORPHEUS.TTF") ~= nil and MX.silent(W), MX.snap(W))
	W.change("unitframes.barTextOutline", "Thick")
	check("ms-uftext: Bar text outline sets the flags", MX.font(W.rawOf[P.healthWords[1]]):sub(-#MX.OUT) == MX.OUT, MX.snap(W))
	W.change("unitframes.lookLightText", true)
	check("ms-uftext: a chosen outline wins over the outline Smaller, lighter bar text removes", MX.font(W.rawOf[P.healthWords[1]]):sub(-#MX.OUT) == MX.OUT, MX.snap(W))
	W.change("unitframes.barTextOutline", "As the game has it")
	check("ms-uftext: with the outline as the game has it Smaller, lighter bar text removes it again", MX.font(W.rawOf[P.healthWords[1]]):sub(-1) == "|", MX.snap(W))
	W.change("unitframes.lookLightText", false)
	W.change("unitframes.barTextColourOwn", true)
	W.change("unitframes.barTextColour", "ff336699")
	check("ms-uftext: Own bar text colour sets the colour of the words", MX.rgb(W.rawOf[P.healthWords[1]]) == "0.20,0.40,0.60", MX.rgb(W.rawOf[P.healthWords[1]]))
	W.blizzard(function() F.frame:SetSmallSize() end)
	check("ms-uftext: when the game swaps the font of the words on the focus frame the rows are set again", MX.font(W.rawOf[F.healthWords[1]]):find("^Fonts\\MORPHEUS.TTF") ~= nil
		and MX.rgb(W.rawOf[F.healthWords[1]]) == "0.20,0.40,0.60", MX.font(W.rawOf[F.healthWords[1]]))
	W.change("unitframes.barTextFace", "Game font")
	W.change("unitframes.barTextColourOwn", false)
	check("ms-uftext: the three rows off put the game's words back", MX.font(W.rawOf[P.healthWords[1]]) == "Fonts\\ARIALN.TTF|12.00|OUTLINE" and MX.font(W.rawOf[P.powerWords[1]]) == "Fonts\\ARIALN.TTF|10.20|OUTLINE"
		and MX.rgb(W.rawOf[P.healthWords[1]]) ~= "0.20,0.40,0.60" and MX.silent(W), MX.snap(W))

	-- A client that refuses.
	W.fontReturn = "error"
	W.change("unitframes.nameOutline", "Thick")
	check("ms-uftext: a client that refuses the font says so in one line and nothing fails", has(W.status(), "Text style: the client refused a name font or outline") and #W.errors == 0 and #W.violations == 0, W.status():sub(1, 300))
	W.fontReturn = "true"
	W.change("unitframes.nameOutline", "As the game has it")
	check("ms-uftext: and the line goes when the rows are as the game has them", not has(W.status(), "Text style:"), W.status():sub(1, 300))
	check("ms-uftext: the new file loads under Lua 5.1 rules", loadfile(ADDON_DIR .. "/UnitText.lua") ~= nil)
end
