-- >>> totnamefit (begin)
-- Long names on the target of target. Labels start "tot name fit:". A stand-in for the name string answers width and room; the hooks are called the way the unit frames file calls them.
do
	local TF = {}
	function TF.fake(need, room)
		local f = { scale = 1, calls = 0 }
		f.SetTextScale = function(self, v) self.scale = v self.calls = self.calls + 1 end
		f.GetUnboundedStringWidth = function(self) return self.need end
		f.GetWidth = function(self) return self.room end
		f.need, f.room = need, room
		return f
	end
	function TF.setup(W, kind, need, room)
		local rec = kind == "tot" and W.ns.UnitFrameExtra.records[W.tot.frame] or W.ns.UnitFrameExtra.records[W.pet.frame]
		rec.row.name = TF.fake(need, room)
		return rec, rec.row.name
	end
	function TF.hooks(W, rec, which)
		for _, hook in ipairs(W.ns.UnitFrameExtra.after[which]) do
			if hook.part == "Long names" then
				hook.fn(rec, nil, true)
			end
		end
	end
	local W = FH.ufWorld({ fontReturn = "true" })
	W.change("unitframes.smallRow", true)
	W.flush()
	local rec, fs = TF.setup(W, "tot", 120, 100)
	check("tot name fit: the row is Smaller text by default", W.ns.Get("unitframes.totNameFit") == "shrink" and W.control("unitframes.totNameFit") ~= nil and W.ns.UnitFrameExtra.rowOn(rec) == true)
	TF.hooks(W, rec, "rowText")
	check("tot name fit: shrink with a long plain name lowers the scale to room over need", math.abs(fs.scale - 100 / 120) < 0.0001, tostring(fs.scale))
	fs.need = 200
	TF.hooks(W, rec, "rowText")
	check("tot name fit: shrink never goes under 75 percent", fs.scale == 0.75, tostring(fs.scale))
	fs.need = 60
	TF.hooks(W, rec, "rowText")
	check("tot name fit: a shorter name after a long one gives the scale 1 back", fs.scale == 1, tostring(fs.scale))
	fs.need = 130
	TF.hooks(W, rec, "layout")
	check("tot name fit: the layout hook measures again", math.abs(fs.scale - 100 / 130) < 0.0001, tostring(fs.scale))
	W.change("unitframes.totNameFit", "Cut with dots")
	TF.hooks(W, rec, "rowText")
	check("tot name fit: cut leaves the scale at 1", fs.scale == 1, tostring(fs.scale))
	W.change("unitframes.totNameFit", "Smaller text")
	for _, case in ipairs({ { "a room of 0", 120, 0 }, { "a width that is not a number", "x", 100 }, { "a room that is not a number", 120, "x" }, { "a secret width", SECRET, 100 }, { "a secret room", 120, SECRET } }) do
		local r2, f2 = TF.setup(W, "tot", case[2], case[3])
		TF.hooks(W, r2, "rowText")
		check("tot name fit: " .. case[1] .. " keeps the scale 1", f2.scale == 1, tostring(f2.scale))
	end
	local notes = function() local n = 0 for _, l in ipairs(W.ns.StatusLines and W.ns.StatusLines() or {}) do if tostring(l):find("Long names", 1, true) then n = n + 1 end end return n end
	local r4, f4 = TF.setup(W, "tot", SECRET, 100)
	TF.hooks(W, r4, "rowText")
	TF.hooks(W, r4, "rowText")
	TF.noteCount = notes()
	f4.need = 60
	TF.hooks(W, r4, "rowText")
	check("tot name fit: a failed measure writes one status line and a good one clears it", TF.noteCount == 1 and notes() == 0, tostring(TF.noteCount) .. "/" .. tostring(notes()))
	local r5, f5 = TF.setup(W, "tot", SECRET, 100)
	TF.hooks(W, r5, "rowText")
	TF.noteCount = notes()
	W.change("unitframes.totNameFit", "Cut with dots")
	TF.hooks(W, r5, "rowText")
	check("tot name fit: Cut with dots clears the status line", TF.noteCount == 1 and notes() == 0, tostring(TF.noteCount) .. "/" .. tostring(notes()))
	W.change("unitframes.totNameFit", "Smaller text")
	TF.hooks(W, r5, "rowText")
	TF.noteCount = notes()
	W.change("unitframes.smallRow", false)
	TF.hooks(W, r5, "rowText")
	check("tot name fit: a row that is off clears the status line", TF.noteCount == 1 and notes() == 0, tostring(TF.noteCount) .. "/" .. tostring(notes()))
	W.change("unitframes.smallRow", true)
	-- The drawing of the setup step: the name of the target of target in the mock frames.
	local D = newWorld({ trackers = true, fontReturn = "true" })
	D.au.unit.player = { guid = "Player-1-0001", player = true, class = "SHAMAN", race = "Troll", name = "Mine" }
	D.login()
	D.flush()
	TF.draw = function(fit, size, width)
		D.change("unitframes.totNameFit", fit)
		D.change("unitframes.nameSize", size)
		local stage = D.env.CreateFrame("Frame", nil, D.env.UIParent)
		local at = #D.addonFonts
		D.ns.SetupDrawings["mock-unit-frames"].build(stage)
		for i = at + 1, #D.addonFonts do
			local r = D.rawOf[D.addonFonts[i]] or D.addonFonts[i]
			if width then r.GetStringWidth = function() return width end end
		end
		D.ns.SetupDrawings["mock-unit-frames"].draw(stage)
		local h = {}
		for i = at + 1, #D.addonFonts do
			local r = D.rawOf[D.addonFonts[i]] or D.addonFonts[i]
			if r.text == "Defias Pillager Captain" then
				h[#h + 1] = select(2, r:GetFont())
			end
		end
		return h
	end
	local cutBig, fitBig, cutSmall, fitSmall = TF.draw("Cut with dots", 100), TF.draw("Smaller text", 100), TF.draw("Cut with dots", 100, 10), TF.draw("Smaller text", 100, 10)
	check("tot name fit: the drawing finds the name", #cutBig > 0 and #cutBig == #fitBig, tostring(#cutBig) .. "/" .. tostring(#fitBig))
	TF.ratio = fitBig[#fitBig] / cutBig[#cutBig]
	check("tot name fit: the drawing sets a long name smaller, not under 75 percent", TF.ratio < 1 and TF.ratio >= 0.7499, tostring(TF.ratio))
	check("tot name fit: the drawing leaves a name that fits alone", fitSmall[#fitSmall] == cutSmall[#cutSmall], tostring(fitSmall[#fitSmall]) .. "/" .. tostring(cutSmall[#cutSmall]))
	local r3, f3 = TF.setup(W, "pet", 200, 100)
	TF.hooks(W, r3, "rowText")
	check("tot name fit: the pet frame is untouched", f3.calls == 0 and f3.scale == 1, tostring(f3.calls))
end
-- >>> totnamefit (end)
-- >>> ms-uffmt (begin)
-- Health and power text formats of the unit frames (ms-12): the Health text and Power text row of each frame page, Number style, Show and the two positions. Every label starts
-- "ms-uffmt:". The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local MX = { calls = 0, amount = { health = 12345, healthMax = 20000, power = 400, powerMax = 1000 }, gone = {}, dead = {}, over = true }
	function MX.world(secret)
		local W = FH.ufWorld({ fontReturn = "true" })
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local env = W.env
		MX.calls, MX.gone, MX.dead, MX.refuse, MX.secret = 0, {}, {}, false, secret == true
		local function value(number)
			MX.calls = MX.calls + 1
			if MX.refuse then
				error("the client refused the call", 0)
			end
			return MX.secret and SECRET or number
		end
		local function plain(v) return rawequal(v, SECRET) and SECRET or v end
		env.CurveConstants = { ScaleTo100 = "curve100" }
		env.AbbreviateNumbers = function(v)
			if rawequal(v, SECRET) then
				return SECRET
			end
			return v >= 1000 and string.format("%.1fk", v / 1000) or tostring(v)
		end
		env.BreakUpLargeNumbers = function(v)
			if rawequal(v, SECRET) then
				return SECRET
			end
			local text = tostring(v):reverse():gsub("(%d%d%d)", "%1,"):reverse()
			return (text:gsub("^,", ""))
		end
		env.C_StringUtil = { TruncateWhenZero = function(v)
			if rawequal(v, SECRET) then
				return SECRET
			end
			return v == 0 and "" or tostring(v)
		end }
		env.UnitHealth = function() return value(MX.amount.health) end
		env.UnitHealthMax = function() return value(MX.amount.healthMax) end
		env.UnitHealthPercent = function(_, predicted, curve)
			assert(predicted == true and curve == "curve100", "UnitHealthPercent: usePredicted and the curve are expected")
			return value(MX.amount.health * 100 / MX.amount.healthMax)
		end
		env.UnitHealthMissing = function() return value(MX.amount.healthMax - MX.amount.health) end
		env.UnitPower = function() return value(MX.amount.power) end
		env.UnitPowerMax = function() return value(MX.amount.powerMax) end
		env.UnitPowerPercent = function(_, powerType, unmodified, curve)
			assert(powerType == nil and unmodified == false and curve == "curve100", "UnitPowerPercent: the type, the flag and the curve are expected")
			return value(MX.amount.power * 100 / MX.amount.powerMax)
		end
		env.UnitPowerMissing = function() return value(MX.amount.powerMax - MX.amount.power) end
		env.UnitExists = function(unit) return not MX.gone[unit] end
		env.UnitIsDeadOrGhost = function(unit) return MX.dead[unit] == true end
		for _, frame in ipairs({ W.player.frame, W.target.frame, W.focus.frame, W.pet.frame }) do
			W.rawOf[frame].IsMouseOver = function() return MX.over end
		end
		W.rawOf[W.player.frame].IsMouseOver = function() return MX.over end
		W.flush()
		return W
	end
	-- The addon's own font string over a bar, or nil.
	function MX.own(W, bar)
		for _, font in ipairs(W.addonFonts) do
			local frame = font.template == "TextStatusBarText" and W.rawOf[font.owner]
			if frame and rawequal(frame.parent, bar) then
				return font
			end
		end
	end
	function MX.text(W, bar)
		local font = MX.own(W, bar)
		return font and (rawequal(font.text, SECRET) and "<secret>" or tostring(font.text)) or "none"
	end
	function MX.alphas(words)
		local list = {}
		for _, fs in ipairs(words) do
			list[#list + 1] = MX.W.rawOf[fs].alpha
		end
		return table.concat(list, ",")
	end
	function MX.updating(W)
		local n = 0
		for _, frame in ipairs(W.eventFrames) do
			if frame.onUpdate ~= nil and not frame.dividers then
				n = n + 1
			end
		end
		return n
	end
	function MX.silent(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "health and power text") end
	function MX.why(W) return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|") .. tostring(W.line("Unit frames")) end
	function MX.shown(W, bar)
		local font = MX.own(W, bar)
		return font ~= nil and W.rawOf[font.owner].shown == true
	end

	local W = MX.world()
	MX.W = W
	local P, T, F, Pet = W.player, W.target, W.focus, W.pet
	local M1 = W.members[1]
	MX.base = MX.updating(W)

	-- The rows: pages and defaults.
	do
		local want = { playerHealthText = "game", playerPowerText = "game", targetHealthText = "game", targetPowerText = "game", focusHealthText = "game", focusPowerText = "game",
			petHealthText = "game", petPowerText = "game", partyHealthText = "game", partyPowerText = "game", bossHealthText = "game", numberStyle = "short", ownTextWhen = "always",
			healthTextPos = "centre", powerTextPos = "centre" }
		local wrong, n = {}, 0
		for key, default in pairs(want) do
			n = n + 1
			if W.ns.Get("unitframes." .. key) ~= default or W.control("unitframes." .. key) == nil then
				wrong[#wrong + 1] = key
			end
		end
		check("ms-uffmt: the fifteen rows are there with their defaults", #wrong == 0 and n == 15, table.concat(wrong, " "))
		check("ms-uffmt: Power text is on every frame page but the boss frames", ROW["unitframes.bossPowerText"] == nil and ROW["unitframes.totHealthText"] == nil
			and ROW["unitframes.partypetHealthText"] == nil and ROW["unitframes.partyPowerText"] ~= nil)
	end

	-- At the defaults nothing is made, nothing is asked of the client and no driver runs.
	W.frame(30)
	check("ms-uffmt: at the defaults the game's words are untouched, no string is made, no value is asked for and no frame runs", MX.alphas(P.healthWords) == "1,1,1" and MX.alphas(P.powerWords) == "1,1,1"
		and MX.own(W, P.health) == nil and MX.calls == 0 and MX.updating(W) == MX.base and MX.silent(W), MX.alphas(P.healthWords) .. " " .. MX.calls .. " " .. MX.updating(W))

	-- A format: the game's words are transparent and the string has the text.
	W.change("unitframes.playerHealthText", "Current")
	check("ms-uffmt: Current writes the shortened number, the game's three words on that bar are transparent and the power bar and the other frames are untouched", MX.text(W, P.health) == "12.3k"
		and MX.alphas(P.healthWords) == "0,0,0" and MX.alphas(P.powerWords) == "1,1,1" and MX.alphas(T.healthWords) == "1,1,1" and MX.own(W, P.power) == nil and MX.own(W, T.health) == nil
		and MX.silent(W), MX.text(W, P.health) .. " " .. MX.alphas(P.healthWords) .. " " .. MX.why(W))
	check("ms-uffmt: the string is shown, over the bar, in the game's bar text font", MX.shown(W, P.health) and MX.own(W, P.health).template == "TextStatusBarText"
		and MX.updating(W) == MX.base + 1, tostring(MX.updating(W)))
	W.change("unitframes.playerHealthText", "Current / max")
	check("ms-uffmt: Current / max writes both numbers", MX.text(W, P.health) == "12.3k / 20.0k", MX.text(W, P.health))
	W.change("unitframes.playerHealthText", "Percent")
	check("ms-uffmt: Percent writes the percent with the game's curve and no decimals", MX.text(W, P.health) == "62%", MX.text(W, P.health))
	W.change("unitframes.playerHealthText", "Current and percent")
	check("ms-uffmt: Current and percent writes both", MX.text(W, P.health) == "12.3k (62%)", MX.text(W, P.health))
	W.change("unitframes.playerHealthText", "Missing")
	check("ms-uffmt: Missing writes what the game says is missing", MX.text(W, P.health) == "7655", MX.text(W, P.health))
	W.change("unitframes.playerHealthText", "Current")
	W.change("unitframes.numberStyle", "12,345")
	check("ms-uffmt: Number style 12,345 breaks the number up", MX.text(W, P.health) == "12,345", MX.text(W, P.health))
	W.change("unitframes.numberStyle", "12.3k")
	check("ms-uffmt: and 12.3k shortens it again", MX.text(W, P.health) == "12.3k", MX.text(W, P.health))

	-- Power text, and the places.
	W.change("unitframes.playerPowerText", "Current / max")
	check("ms-uffmt: Power text writes the power of the power bar with its own calls", MX.text(W, P.power) == "400 / 1.0k" and MX.alphas(P.powerWords) == "0,0,0" and MX.text(W, P.health) == "12.3k", MX.text(W, P.power))
	W.change("unitframes.playerPowerText", "Percent")
	check("ms-uffmt: Power text Percent", MX.text(W, P.power) == "40%", MX.text(W, P.power))
	W.change("unitframes.playerPowerText", "Missing")
	check("ms-uffmt: Power text Missing", MX.text(W, P.power) == "600", MX.text(W, P.power))
	local own, ownPower = MX.own(W, P.health), MX.own(W, P.power)
	check("ms-uffmt: the strings are centred by default", own.justify == "CENTER" and ownPower.justify == "CENTER", tostring(own.justify) .. tostring(ownPower.justify))
	W.change("unitframes.healthTextPos", "Right")
	check("ms-uffmt: Health text position Right anchors it to the right of the bar and leaves the power text", own.justify == "RIGHT" and own.points[#own.points] ~= nil and own.points[#own.points][1] == "RIGHT"
		and ownPower.justify == "CENTER", tostring(own.justify))
	W.change("unitframes.healthTextPos", "Left")
	check("ms-uffmt: and Left to the left", own.justify == "LEFT" and own.points[#own.points][1] == "LEFT", tostring(own.justify))
	W.change("unitframes.healthTextPos", "Centre")
	W.change("unitframes.powerTextPos", "Right")
	check("ms-uffmt: the power row has a position of its own", own.justify == "CENTER" and ownPower.justify == "RIGHT" and ownPower.points[#ownPower.points][1] == "RIGHT", tostring(own.justify) .. tostring(ownPower.justify))
	W.change("unitframes.powerTextPos", "Centre")
	W.change("unitframes.playerPowerText", "As the game has it")

	-- Hidden: only the game's words go.
	W.change("unitframes.targetHealthText", "Hidden")
	check("ms-uffmt: Hidden makes the game's words transparent and writes nothing", MX.alphas(T.healthWords) == "0,0,0" and MX.own(W, T.health) == nil and MX.silent(W), MX.alphas(T.healthWords))
	W.change("unitframes.targetHealthText", "As the game has it")
	check("ms-uffmt: and the game's words are back with As the game has it", MX.alphas(T.healthWords) == "1,1,1" and MX.silent(W), MX.alphas(T.healthWords))

	-- The text follows the unit every tenth of a second, and only then.
	MX.amount.health = 4000
	MX.calls = 0
	W.frame(3)
	check("ms-uffmt: the text is not written again before a tenth of a second", MX.text(W, P.health) == "12.3k" and MX.calls == 0, MX.text(W, P.health))
	W.frame(6)
	check("ms-uffmt: the driver writes it again after a tenth of a second", MX.text(W, P.health) == "4.0k" and MX.calls > 0, MX.text(W, P.health))
	-- A unit that is gone or dead has no text.
	MX.gone.player = true
	W.frame(8)
	check("ms-uffmt: a unit that does not exist has an empty string", MX.text(W, P.health) == "", MX.text(W, P.health))
	MX.gone.player = nil
	MX.dead.player = true
	W.frame(8)
	check("ms-uffmt: a dead unit has an empty string", MX.text(W, P.health) == "", MX.text(W, P.health))
	MX.dead.player = nil
	W.frame(8)
	check("ms-uffmt: and the text is back with the unit", MX.text(W, P.health) == "4.0k", MX.text(W, P.health))
	-- Under the mouse.
	W.change("unitframes.ownTextWhen", "Under the mouse")
	MX.over = false
	W.frame(8)
	check("ms-uffmt: Under the mouse shows nothing while the cursor is away", MX.text(W, P.health) == "", MX.text(W, P.health))
	MX.over = true
	W.frame(8)
	check("ms-uffmt: and the text while it is over the frame", MX.text(W, P.health) == "4.0k", MX.text(W, P.health))
	W.change("unitframes.ownTextWhen", "Always")
	MX.over = false
	W.frame(8)
	check("ms-uffmt: Always shows it with the cursor away", MX.text(W, P.health) == "4.0k", MX.text(W, P.health))
	MX.over = true

	-- The look: the size and colour rows reach the string.
	W.change("unitframes.barTextColourOwn", true)
	W.change("unitframes.barTextColour", "ff336699")
	local c = MX.own(W, P.health).textColour
	check("ms-uffmt: Own bar text colour reaches the string", c ~= nil and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) == "0.20,0.40,0.60", tostring(c))
	W.change("unitframes.barTextColourOwn", false)

	-- No text on the power bar wins over a power format.
	W.change("unitframes.playerPowerText", "Current")
	W.change("unitframes.lookNoPowerText", true)
	W.frame(8)
	check("ms-uffmt: No text on the power bar leaves the power bar without text whatever the format", MX.text(W, P.power) == "" and MX.alphas(P.powerWords) == "0,0,0", MX.text(W, P.power))
	W.change("unitframes.playerPowerText", "As the game has it")
	check("ms-uffmt: and a format given up under it leaves the words transparent", MX.alphas(P.powerWords) == "0,0,0" and MX.text(W, P.power) == "", MX.alphas(P.powerWords))
	W.change("unitframes.playerPowerText", "Current")
	W.change("unitframes.lookNoPowerText", false)
	W.frame(8)
	check("ms-uffmt: and with it off the format shows", MX.text(W, P.power) == "400" and MX.alphas(P.powerWords) == "0,0,0", MX.text(W, P.power))
	W.change("unitframes.playerPowerText", "As the game has it")
	check("ms-uffmt: a power bar back to the game's has its words again", MX.alphas(P.powerWords) == "1,1,1" and MX.text(W, P.power) == "", MX.alphas(P.powerWords))

	-- Other frames.
	MX.amount.health = 12345
	W.change("unitframes.targetHealthText", "Percent")
	W.change("unitframes.petHealthText", "Current")
	W.change("unitframes.partyHealthText", "Current / max")
	W.change("unitframes.partyPowerText", "Percent")
	check("ms-uffmt: the target, pet and party frames take their own rows", MX.text(W, T.health) == "62%" and MX.text(W, Pet.health) == "12.3k" and MX.text(W, M1.health) == "12.3k / 20.0k"
		and MX.text(W, M1.power) == "40%" and MX.silent(W), MX.text(W, T.health) .. " " .. MX.text(W, Pet.health) .. " " .. MX.text(W, M1.health) .. " " .. MX.why(W))
	check("ms-uffmt: the focus frame is untouched", MX.alphas(F.healthWords) == "1,1,1" and MX.own(W, F.health) == nil)

	-- A frame style that is off gives the game's words back.
	W.change("unitframes.target", false)
	check("ms-uffmt: a kind of frame that is switched off has the game's words and no text", MX.alphas(T.healthWords) == "1,1,1" and MX.text(W, T.health) == "", MX.alphas(T.healthWords))
	W.change("unitframes.target", true)
	check("ms-uffmt: and switched on again has the format", MX.text(W, T.health) == "62%" and MX.alphas(T.healthWords) == "0,0,0", MX.text(W, T.health))

	-- Combat: the string is made after combat, the game's words stay until then.
	W.combat = true
	W.change("unitframes.focusPowerText", "Current")
	check("ms-uffmt: in combat a bar that has no string yet keeps the game's words and nothing is made on the protected frame", MX.alphas(F.powerWords) == "1,1,1" and MX.own(W, F.power) == nil
		and #W.violations == 0 and #W.errors == 0, MX.alphas(F.powerWords) .. " " .. MX.why(W))
	W.combat = false
	W.fire("PLAYER_REGEN_ENABLED")
	W.flush()
	check("ms-uffmt: after combat the string is made and the words go", MX.text(W, F.power) == "400" and MX.alphas(F.powerWords) == "0,0,0" and #W.violations == 0, MX.text(W, F.power))
	W.change("unitframes.focusPowerText", "As the game has it")

	-- Back to the game's: everything as at the start, and the driver goes.
	for _, key in ipairs({ "playerHealthText", "targetHealthText", "petHealthText", "partyHealthText", "partyPowerText" }) do
		W.change("unitframes." .. key, "As the game has it")
	end
	W.frame(8)
	check("ms-uffmt: with every row at the game's the words are back, every string is empty and hidden and no driver runs", MX.alphas(P.healthWords) == "1,1,1" and MX.alphas(T.healthWords) == "1,1,1"
		and MX.alphas(Pet.healthWords) == "1,1,1" and MX.alphas(M1.healthWords) == "1,1,1" and MX.text(W, P.health) == "" and not MX.shown(W, P.health) and MX.updating(W) == MX.base
		and MX.silent(W), MX.alphas(P.healthWords) .. " " .. MX.updating(W) .. " " .. MX.base)
	MX.calls = 0
	W.frame(30)
	check("ms-uffmt: and nothing is asked of the client any more", MX.calls == 0, MX.calls)

	-- A client that refuses a value: three failures stop the part and the game's words return.
	W.change("unitframes.playerHealthText", "Current")
	W.change("unitframes.playerPowerText", "Current")
	MX.refuse = true
	W.frame(30)
	check("ms-uffmt: a refused call stops the part with a line on the status, the game's words are back and nothing raises", has(W.status(), "health and power text stopped") and MX.alphas(P.healthWords) == "1,1,1"
		and MX.alphas(P.powerWords) == "1,1,1" and MX.text(W, P.health) == "" and #W.errors == 0 and #W.violations == 0 and MX.updating(W) == MX.base, W.status():sub(1, 400) .. " " .. MX.alphas(P.healthWords))
	MX.refuse = false
	W.frame(30)
	check("ms-uffmt: a stopped part stays off", MX.text(W, P.health) == "" and MX.alphas(P.healthWords) == "1,1,1", MX.text(W, P.health))

	-- A client that withholds the values: they go through and nothing is compared.
	local S = MX.world(true)
	MX.W = S
	local SP = S.player
	S.change("unitframes.playerHealthText", "Current")
	check("ms-uffmt: a withheld value goes to SetText as it is", MX.text(S, SP.health) == "<secret>" and MX.silent(S), MX.text(S, SP.health) .. " " .. MX.why(S))
	S.change("unitframes.playerHealthText", "Current / max")
	check("ms-uffmt: two withheld values go to SetFormattedText as they are", MX.text(S, SP.health) == "<withheld> / <withheld>" and MX.silent(S), MX.text(S, SP.health))
	S.change("unitframes.playerHealthText", "Percent")
	S.change("unitframes.playerPowerText", "Current and percent")
	S.frame(8)
	check("ms-uffmt: so do the percent and the number with its percent", MX.text(S, SP.health) == "<withheld>%" and MX.text(S, SP.power) == "<withheld> (<withheld>%)" and MX.silent(S),
		MX.text(S, SP.health) .. " " .. MX.text(S, SP.power))
	S.change("unitframes.playerPowerText", "Missing")
	check("ms-uffmt: Missing with a withheld value", MX.text(S, SP.power) == "<secret>" and MX.silent(S), MX.text(S, SP.power))
	check("ms-uffmt: the new code loads under Lua 5.1 rules", loadfile(ADDON_DIR .. "/UnitText.lua") ~= nil)
end
-- >>> ms-uffmt (end)
-- >>> ms-fonts (begin)
-- Fonts page (ms-16): the module that replaces the game's font objects. The values are kept in one table: the main function of this file has a limit
-- on the locals alive at once.
do
	local T = {}
	-- A font object of the game: answers GetObjectType "Font", GetFont, GetShadowOffset, and records each call in W.fontCalls.
	function T.font(W, name, file, size, flags, opts)
		opts = opts or {}
		local f = { name = name, file = file, size = size, flags = flags, shadow = { 1, -1 } }
		function f.GetObjectType() return opts.kind or "Font" end
		function f.GetFont()
			if opts.getFont == "error" then
				error("GetFont failed", 0)
			elseif opts.getFont == "secret" then
				return SECRET, SECRET, SECRET
			end
			return f.file, f.size, f.flags
		end
		function f.SetFont(_, a, b, c)
			W.fontCalls[#W.fontCalls + 1] = name
			if opts.setFont == "error" then
				error("SetFont refused", 0)
			elseif opts.setFont == "false" then
				return false
			end
			f.file, f.size, f.flags = a, b, c
			return true
		end
		function f.GetShadowOffset() return f.shadow[1], f.shadow[2] end
		function f.SetShadowOffset(_, x, y)
			W.shadowCalls[#W.shadowCalls + 1] = name
			f.shadow = { x, y }
		end
		W.env[name] = f
		W.gameFonts[name] = f
		return f
	end
	-- A world with game fonts: a body, a number and a title one, a small one, one of another face, the skipped ones, and things that are no font.
	function T.world(opts)
		local W = newWorld(opts or {})
		W.fontReturn = "true"
		W.fontCalls, W.shadowCalls, W.gameFonts = {}, {}, {}
		T.font(W, "GameFontNormal", "Fonts\\FRIZQT__.TTF", 12, "")
		T.font(W, "GameFontSmall", "Fonts\\FRIZQT__.TTF", 9, "OUTLINE")
		T.font(W, "NumberFontNormal", "Fonts\\ARIALN.TTF", 14, "OUTLINE")
		T.font(W, "QuestTitleFont", "Fonts\\MORPHEUS.ttf", 18, "")
		T.font(W, "DamageFont", "Fonts\\SKURRI.TTF", 20, "")
		T.font(W, "ChatFontNormal", "Fonts\\FRIZQT__.TTF", 14, "")
		T.font(W, "SystemFont_NamePlate", "Fonts\\FRIZQT__.TTF", 9, "OUTLINE")
		T.font(W, "SystemFont_NamePlate_Outlined", "Fonts\\FRIZQT__.TTF", 9, "OUTLINE")
		T.font(W, "FlatUIOwnFont", "Fonts\\FRIZQT__.TTF", 11, "")
		T.font(W, "NotAFont", "Fonts\\FRIZQT__.TTF", 10, "", { kind = "Frame" })
		W.env.NotATable = "Fonts\\FRIZQT__.TTF"
		W.env.RaisingType = { GetObjectType = function() error("no type", 0) end }
		W.login()
		return W
	end
	function T.look(W, name)
		local f = W.gameFonts[name]
		return ("%s %g %s %s,%s"):format(f.file, f.size, f.flags, f.shadow[1], f.shadow[2])
	end
	function T.on(W)
		W.ns.Set("fonts.enabled", true)
	end
	-- The game's EventRegistry, for the end of Edit Mode (EditModeManager.lua:124): the registrant is the first argument of the callback.
	function T.registry(W)
		local registry = { callbacks = {} }
		function registry:RegisterCallback(event, func, owner)
			registry.callbacks[event] = registry.callbacks[event] or {}
			table.insert(registry.callbacks[event], { owner = owner, func = func })
			return owner
		end
		function registry:TriggerEvent(event, ...)
			for _, entry in ipairs(registry.callbacks[event] or {}) do
				entry.func(entry.owner, ...)
			end
		end
		W.env.EventRegistry = registry
		W.registry = registry
		function W.registrants(event) return #(registry.callbacks[event] or {}) end
	end
	T.GAME = { GameFontNormal = "Fonts\\FRIZQT__.TTF 12  1,-1", GameFontSmall = "Fonts\\FRIZQT__.TTF 9 OUTLINE 1,-1", NumberFontNormal = "Fonts\\ARIALN.TTF 14 OUTLINE 1,-1",
		QuestTitleFont = "Fonts\\MORPHEUS.ttf 18  1,-1", DamageFont = "Fonts\\SKURRI.TTF 20  1,-1", ChatFontNormal = "Fonts\\FRIZQT__.TTF 14  1,-1",
		SystemFont_NamePlate = "Fonts\\FRIZQT__.TTF 9 OUTLINE 1,-1", SystemFont_NamePlate_Outlined = "Fonts\\FRIZQT__.TTF 9 OUTLINE 1,-1", FlatUIOwnFont = "Fonts\\FRIZQT__.TTF 11  1,-1" }
	function T.diff(W)
		local bad = {}
		for name, want in pairs(T.GAME) do
			if T.look(W, name) ~= want then
				bad[#bad + 1] = name .. "=" .. T.look(W, name)
			end
		end
		table.sort(bad)
		return table.concat(bad, "; ")
	end

	-- The rows, at their defaults, and the helpers.
	do
		local W = T.world()
		local ns = W.ns
		local ids = {}
		for _, choice in ipairs(ns.OutlineChoices()) do
			ids[#ids + 1] = choice[1]
		end
		local viaRow = ns.Choices({ choices = "OutlineChoices" })
		check("ms-fonts: the eight rows are at their defaults, the module is off, and the rows add nothing to the saved settings",
			ns.Get("fonts.enabled") == false and ns.Get("fonts.body") == "default" and ns.Get("fonts.numbers") == "default" and ns.Get("fonts.titles") == "default"
			and ns.Get("fonts.outline") == "game" and ns.Get("fonts.shadow") == true and ns.Get("fonts.size") == 100 and ns.Get("fonts.minimum") == 0
			and W.options()["fonts.enabled"] == nil)
		check("ms-fonts: the outline row names a function and has four lines, game first", table.concat(ids, ",") == "game,none,outline,thick" and #viaRow == 4 and viaRow[1][1] == "game")
		check("ms-fonts: a line of the outline row is the flags of the font call, the game's line is none", ns.OutlineFlags("none") == "" and ns.OutlineFlags("outline") == "OUTLINE"
			and ns.OutlineFlags("thick") == "THICKOUTLINE" and ns.OutlineFlags("game") == nil and ns.OutlineFlags("nowhere") == nil)
		ns.Set("fonts.size", 200)
		ns.Set("fonts.outline", "nowhere")
		ns.Set("fonts.minimum", 99)
		check("ms-fonts: a value outside its range or its list is refused or held to the range", ns.Get("fonts.size") == 130 and ns.Get("fonts.outline") == "game" and ns.Get("fonts.minimum") == 14,
			ns.Get("fonts.size") .. ns.Get("fonts.outline") .. ns.Get("fonts.minimum"))
		check("ms-fonts: with the module off no font is read or set", #W.fontCalls == 0 and #W.shadowCalls == 0 and T.diff(W) == "" and #W.violations == 0 and #W.errors == 0)
		check("ms-fonts: the status says Fonts is off", W.status():find("Fonts: off", 1, true) ~= nil, W.status())
	end

	-- On with every row at the game's value: no call.
	do
		local W = T.world()
		T.on(W)
		check("ms-fonts: on with every row at the game's value makes no call", #W.fontCalls == 0 and #W.shadowCalls == 0 and T.diff(W) == "" and W.ns.Enabled("fonts"), table.concat(W.fontCalls, ","))
		check("ms-fonts: the status says Fonts is on and names no font changed", W.status():find("Fonts: on", 1, true) ~= nil and W.status():find("font objects changed", 1, true) == nil, W.status())
	end

	-- The three faces.
	do
		local W = T.world()
		local ns = W.ns
		T.on(W)
		ns.Set("fonts.body", "arial")
		check("ms-fonts: the Interface font sets the objects that use the body face and no others",
			T.look(W, "GameFontNormal") == "Fonts\\ARIALN.TTF 12  1,-1" and T.look(W, "GameFontSmall") == "Fonts\\ARIALN.TTF 9 OUTLINE 1,-1"
			and T.look(W, "NumberFontNormal") == T.GAME.NumberFontNormal and T.look(W, "QuestTitleFont") == T.GAME.QuestTitleFont and T.look(W, "DamageFont") == T.GAME.DamageFont,
			T.look(W, "GameFontNormal"))
		ns.Set("fonts.numbers", "morpheus")
		ns.Set("fonts.titles", "skurri")
		check("ms-fonts: the Number font and the Title font set theirs", T.look(W, "NumberFontNormal") == "Fonts\\MORPHEUS.TTF 14 OUTLINE 1,-1"
			and T.look(W, "QuestTitleFont") == "Fonts\\SKURRI.TTF 18  1,-1", T.look(W, "NumberFontNormal") .. T.look(W, "QuestTitleFont"))
		check("ms-fonts: the chat fonts, the nameplate fonts, the addon's own, a table that is no font, a global that is no table and one that raises are left alone",
			T.look(W, "ChatFontNormal") == T.GAME.ChatFontNormal and T.look(W, "SystemFont_NamePlate") == T.GAME.SystemFont_NamePlate
			and T.look(W, "SystemFont_NamePlate_Outlined") == T.GAME.SystemFont_NamePlate_Outlined and T.look(W, "FlatUIOwnFont") == T.GAME.FlatUIOwnFont
			and T.look(W, "NotAFont") == "Fonts\\FRIZQT__.TTF 10  1,-1" and #W.errors == 0 and #W.violations == 0)
		local calls = #W.fontCalls
		ns.Set("fonts.body", "arial")
		check("ms-fonts: a row set to what it was makes no call", #W.fontCalls == calls)
		ns.Set("fonts.body", "default")
		check("ms-fonts: the face back at the game's puts the game's file back and leaves the others", T.look(W, "GameFontNormal") == T.GAME.GameFontNormal
			and T.look(W, "NumberFontNormal") == "Fonts\\MORPHEUS.TTF 14 OUTLINE 1,-1", T.look(W, "GameFontNormal"))
	end

	-- Outline, shadow, size and smallest text.
	do
		local W = T.world()
		local ns = W.ns
		T.on(W)
		ns.Set("fonts.outline", "thick")
		check("ms-fonts: Text outline thick sets the flags of every object, the skipped ones aside", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12 THICKOUTLINE 1,-1"
			and T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 20 THICKOUTLINE 1,-1" and T.look(W, "ChatFontNormal") == T.GAME.ChatFontNormal, T.look(W, "GameFontNormal"))
		ns.Set("fonts.outline", "none")
		check("ms-fonts: Text outline none empties the flags", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 9  1,-1" and T.look(W, "NumberFontNormal") == "Fonts\\ARIALN.TTF 14  1,-1", T.look(W, "GameFontSmall"))
		ns.Set("fonts.outline", "game")
		check("ms-fonts: Text outline game puts the game's flags back", T.diff(W) == "", T.diff(W))
		local fontCalls = #W.fontCalls
		ns.Set("fonts.shadow", false)
		check("ms-fonts: Text shadow off sets the offset to 0, 0 and nothing else", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12  0,0" and T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 20  0,0"
			and T.look(W, "ChatFontNormal") == T.GAME.ChatFontNormal and #W.fontCalls == fontCalls, T.look(W, "GameFontNormal"))
		local shadows = #W.shadowCalls
		ns.Set("fonts.size", 130)
		check("ms-fonts: a second pass does not set the shadow again", #W.shadowCalls == shadows, #W.shadowCalls .. " " .. shadows)
		ns.Set("fonts.shadow", true)
		check("ms-fonts: Text shadow on puts the game's offset back", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 15.6  1,-1", T.look(W, "GameFontNormal"))
		check("ms-fonts: Text size 130 is 130 percent of each height, and the others keep theirs", T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 26  1,-1" and T.look(W, "NumberFontNormal") == "Fonts\\ARIALN.TTF 18.2 OUTLINE 1,-1"
			and T.look(W, "ChatFontNormal") == T.GAME.ChatFontNormal, T.look(W, "DamageFont"))
		ns.Set("fonts.size", 80)
		ns.Set("fonts.minimum", 10)
		check("ms-fonts: Smallest text raises a height below it and leaves the others at their size", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 10 OUTLINE 1,-1"
			and T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 10  1,-1" and T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 16  1,-1", T.look(W, "GameFontNormal"))
		ns.Set("fonts.size", 100)
		check("ms-fonts: Smallest text at 100 percent raises only what is below it", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 10 OUTLINE 1,-1" and T.look(W, "GameFontNormal") == T.GAME.GameFontNormal
			and T.look(W, "DamageFont") == T.GAME.DamageFont, T.look(W, "GameFontSmall"))
		ns.Set("fonts.minimum", 0)
		check("ms-fonts: every row back at the game's value sets every object back", T.diff(W) == "", T.diff(W))
	end

	-- Off puts everything back.
	do
		local W = T.world()
		local ns = W.ns
		T.on(W)
		ns.Set("fonts.body", "arial")
		ns.Set("fonts.outline", "thick")
		ns.Set("fonts.shadow", false)
		ns.Set("fonts.size", 125)
		check("ms-fonts: with several rows changed the status counts the objects changed", W.status():find("Fonts: 5 font objects changed.", 1, true) ~= nil, W.status())
		ns.Set("fonts.enabled", false)
		check("ms-fonts: switching it off puts every font back as the game had it", T.diff(W) == "" and W.status():find("Fonts: off", 1, true) ~= nil, T.diff(W))
		local calls = #W.fontCalls
		ns.Set("fonts.size", 110)
		check("ms-fonts: a row changed while it is off makes no call", #W.fontCalls == calls and T.diff(W) == "")
		ns.Set("fonts.enabled", true)
		check("ms-fonts: switching it on again applies the rows", T.look(W, "GameFontNormal") == "Fonts\\ARIALN.TTF 13.2 THICKOUTLINE 0,0", T.look(W, "GameFontNormal"))
	end

	-- The game sets the objects again.
	do
		local W = T.world()
		local ns = W.ns
		-- The game's text size manager sets the height of each user-scaled font (TextSizeManager.lua:52-61).
		local base = { GameFontNormal = 12, DamageFont = 20 }
		W.env.TextSizeManager = { SetTextScale = function(_, scale)
			for name, height in pairs(base) do
				W.gameFonts[name].size = height * scale
			end
		end }
		W.env.ObjectiveTrackerManager = { SetTextSize = function(_, size)
			W.gameFonts.GameFontSmall.size = size
		end }
		T.registry(W)
		T.on(W)
		ns.Set("fonts.size", 130)
		W.env.TextSizeManager:SetTextScale(1.5)
		W.fire("CVAR_UPDATE", "userFontScale", "1.5")
		W.tick()
		check("ms-fonts: after the game sets the heights again the size applies to the new height", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 23.4  1,-1" and T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 39  1,-1",
			T.look(W, "GameFontNormal"))
		W.env.ObjectiveTrackerManager:SetTextSize(14)
		W.registry:TriggerEvent("EditMode.Exit")
		W.tick()
		check("ms-fonts: after the tracker text size is set the pass runs again", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 18.2 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
		ns.Set("fonts.enabled", false)
		check("ms-fonts: off puts back what the game set last, not what it set first", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 18  1,-1" and T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 14 OUTLINE 1,-1",
			T.look(W, "GameFontNormal") .. T.look(W, "GameFontSmall"))
		local before = #W.fontCalls
		W.env.TextSizeManager:SetTextScale(1)
		check("ms-fonts: with the module off the game's calls make none of its own", #W.fontCalls == before and T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12  1,-1")
	end

	-- SetFontHeight changes the height alone: the faces and flags Flat UI set are not the game's.
	do
		local W = T.world()
		local ns = W.ns
		W.env.TextSizeManager = { SetTextScale = function(_, scale)
			W.gameFonts.GameFontNormal.size = 12 * scale
		end }
		T.on(W)
		ns.Set("fonts.body", "arial")
		ns.Set("fonts.outline", "thick")
		W.env.TextSizeManager:SetTextScale(1.5)
		W.fire("CVAR_UPDATE", "userFontScale", "1.5")
		W.tick()
		ns.Set("fonts.enabled", false)
		check("ms-fonts: after the game sets the height alone, off puts the game's face and flags back", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 18  1,-1", T.look(W, "GameFontNormal"))
		ns.Set("fonts.enabled", true)
		W.env.TextSizeManager:SetTextScale(1.25)
		W.fire("CVAR_UPDATE", "userFontScale", "1.25")
		W.tick()
		ns.Set("fonts.outline", "game")
		check("ms-fonts: the outline back at the game's after a size change gives the game's flags", T.look(W, "GameFontNormal") == "Fonts\\ARIALN.TTF 15  1,-1", T.look(W, "GameFontNormal"))
		W.env.TextSizeManager:SetTextScale(1.05)
		W.fire("CVAR_UPDATE", "userFontScale", "1.05")
		W.tick()
		ns.Set("fonts.size", 100)
		ns.Set("fonts.body", "default")
		check("ms-fonts: a small font scaled by the game is not taken for Flat UI's own height", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12.6  1,-1", T.look(W, "GameFontNormal"))
	end

	-- hkfont: the game's text size and the tracker text size are followed by events, with taintLog 0 and 2; no method of TextSizeManager or
	-- ObjectiveTrackerManager is hooked.
	do
		for _, value in ipairs({ "0", "2" }) do
			local tag = "hkfont: taintLog " .. value .. ": "
			local W = T.world()
			local ns = W.ns
			W.cvars.taintLog = value
			local base = { GameFontNormal = 12, DamageFont = 20 }
			W.env.TextSizeManager = { SetTextScale = function(_, scale)
				for name, height in pairs(base) do
					W.gameFonts[name].size = height * scale
				end
			end }
			W.env.ObjectiveTrackerManager = { SetTextSize = function(_, size)
				W.gameFonts.GameFontSmall.size = size
			end }
			T.registry(W)
			local hooks = W.hooks
			T.on(W)
			ns.Set("fonts.size", 130)
			check(tag .. "SetTextScale and SetTextSize are not hooked, and nothing else is", not INSTHOOK.wrapped(W, W.env.TextSizeManager, "SetTextScale")
				and not INSTHOOK.wrapped(W, W.env.ObjectiveTrackerManager, "SetTextSize") and W.hooks == hooks, W.hooks - hooks)
			check(tag .. "the end of Edit Mode is watched once", W.registrants("EditMode.Exit") == 1, W.registrants("EditMode.Exit"))
			W.env.TextSizeManager:SetTextScale(1.5)
			check(tag .. "the game's own call changes nothing of Flat UI's before its event", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 18  1,-1", T.look(W, "GameFontNormal"))
			W.fire("CVAR_UPDATE", "userFontScale", "1.5")
			check(tag .. "the event alone does not set a font inside the game's pass", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 18  1,-1", T.look(W, "GameFontNormal"))
			W.tick()
			check(tag .. "on the next frame the size applies to the new heights", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 23.4  1,-1" and T.look(W, "DamageFont") == "Fonts\\SKURRI.TTF 39  1,-1",
				T.look(W, "GameFontNormal"))
			local calls = #W.fontCalls
			W.fire("CVAR_UPDATE", "nameplateMaxDistance", "60")
			W.fire("CVAR_UPDATE", SECRET)
			W.fire("CVAR_UPDATE", nil)
			W.tick()
			check(tag .. "another variable and a withheld name make no call", #W.fontCalls == calls and #W.errors == 0 and #W.violations == 0, #W.fontCalls - calls)
			W.fire("CVAR_UPDATE", "userFontScale", "1.5")
			W.fire("CVAR_UPDATE", "userFontScale", "1.5")
			check(tag .. "two events in a frame wait for one pass", #W.timers == 1, #W.timers)
			W.tick()
			W.env.ObjectiveTrackerManager:SetTextSize(14)
			W.registry:TriggerEvent("EditMode.Exit")
			check(tag .. "the end of Edit Mode does not set a font inside the game's exit", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 14 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.tick()
			check(tag .. "on the next frame the tracker's height has the size", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 18.2 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.env.ObjectiveTrackerManager:SetTextSize(16)
			W.fire("EDIT_MODE_LAYOUTS_UPDATED")
			W.tick()
			check(tag .. "a layout the game applies sets it again", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 20.8 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.env.ObjectiveTrackerManager:SetTextSize(12)
			W.fire("PLAYER_SPECIALIZATION_CHANGED", "party1")
			W.fire("PLAYER_SPECIALIZATION_CHANGED", SECRET)
			W.tick()
			check("hkfont: another unit's specialization change makes no pass (taintLog " .. value .. ")", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 12 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.fire("PLAYER_SPECIALIZATION_CHANGED", "player")
			check("hkfont: a specialization change does not set a font inside the game's pass (taintLog " .. value .. ")", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 12 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.tick()
			check("hkfont: on the next frame a specialization change sets the tracker's height (taintLog " .. value .. ")", T.look(W, "GameFontSmall") == "Fonts\\FRIZQT__.TTF 15.6 OUTLINE 1,-1", T.look(W, "GameFontSmall"))
			W.env.TextSizeManager:SetTextScale(1.5)
			W.fire("VARIABLES_LOADED")
			W.tick()
			check("hkfont: the variables loading sets the new heights (taintLog " .. value .. ")", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 23.4  1,-1", T.look(W, "GameFontNormal"))
			W.fire("CVAR_UPDATE", "userFontScale", "1.5")
			ns.Set("fonts.enabled", false)
			W.env.TextSizeManager:SetTextScale(1)
			calls = #W.fontCalls
			W.tick()
			check(tag .. "an event waiting when the module goes off makes no call", #W.fontCalls == calls and T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12  1,-1", T.look(W, "GameFontNormal"))
			W.fire("CVAR_UPDATE", "userFontScale", "1")
			W.registry:TriggerEvent("EditMode.Exit")
			W.tick()
			check(tag .. "with the module off the events make no call", #W.fontCalls == calls and T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 12  1,-1", T.look(W, "GameFontNormal"))
			check(tag .. "no violation", #W.errors == 0 and #W.violations == 0)
		end
	end

	-- Combat, a game addon that loads later.
	do
		local W = T.world()
		local ns = W.ns
		W.combat = true
		T.on(W)
		ns.Set("fonts.size", 120)
		check("ms-fonts: in combat nothing is set", #W.fontCalls == 0 and T.diff(W) == "")
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("ms-fonts: when combat ends the rows apply", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 14.4  1,-1", T.look(W, "GameFontNormal"))
		T.font(W, "LateFont", "Fonts\\FRIZQT__.TTF", 10, "")
		W.fire("ADDON_LOADED", "SomeOtherAddon")
		check("ms-fonts: an addon that is not the game's does not walk the globals again", T.look(W, "LateFont") == "Fonts\\FRIZQT__.TTF 10  1,-1")
		W.fire("ADDON_LOADED", "Blizzard_Communities")
		check("ms-fonts: a game addon that loads is walked and its font is set", T.look(W, "LateFont") == "Fonts\\FRIZQT__.TTF 12  1,-1", T.look(W, "LateFont"))
	end

	-- The language, and a font that cannot be read.
	do
		local W = newWorld({})
		W.fontReturn = "true"
		W.fontCalls, W.shadowCalls, W.gameFonts = {}, {}, {}
		T.font(W, "GameFontNormal", "Fonts\\FRIZQT__.TTF", 12, "")
		T.font(W, "BadFont", "Fonts\\FRIZQT__.TTF", 12, "", { getFont = "error" })
		T.font(W, "SecretFont", "Fonts\\FRIZQT__.TTF", 12, "", { getFont = "secret" })
		W.env.GetLocale = function() return "koKR" end
		W.login()
		W.ns.Set("fonts.enabled", true)
		W.ns.Set("fonts.body", "arial")
		W.ns.Set("fonts.size", 110)
		check("ms-fonts: on a client that is not Latin the face is not changed, the size is", T.look(W, "GameFontNormal") == "Fonts\\FRIZQT__.TTF 13.2  1,-1", T.look(W, "GameFontNormal"))
		check("ms-fonts: and the status says so in one line", W.status():find("Fonts: faces stay the game's on a client whose language is not Latin.", 1, true) ~= nil, W.status())
		check("ms-fonts: a font that raises or answers with a withheld value is skipped, with no error", #W.fontCalls == 1 and #W.errors == 0 and #W.violations == 0, table.concat(W.fontCalls, ","))
	end

	-- A refused call stops the part.
	do
		local W = newWorld({})
		W.fontReturn = "true"
		W.fontCalls, W.shadowCalls, W.gameFonts = {}, {}, {}
		for index = 1, 8 do
			T.font(W, "RefusingFont" .. index, "Fonts\\FRIZQT__.TTF", 12, "", { setFont = index % 2 == 0 and "error" or "false" })
		end
		T.font(W, "GoodFont", "Fonts\\FRIZQT__.TTF", 12, "")
		W.login()
		W.ns.Set("fonts.enabled", true)
		W.ns.Set("fonts.size", 120)
		check("ms-fonts: when the game refuses SetFont on enough objects the part stops, with a line in the status and no error",
			W.ns.PartStopped("fonts", "font") and W.status():find("Fonts: font stopped.", 1, true) ~= nil and #W.errors == 0 and #W.violations == 0, W.status())
		local fontCalls = #W.fontCalls
		W.ns.Set("fonts.size", 130)
		check("ms-fonts: a stopped part makes no more calls, and the font it had set is back", #W.fontCalls == fontCalls + 0 and T.look(W, "GoodFont") == "Fonts\\FRIZQT__.TTF 12  1,-1", T.look(W, "GoodFont"))
		W.ns.Set("fonts.shadow", false)
		check("ms-fonts: the shadow part goes on alone", T.look(W, "GoodFont") == "Fonts\\FRIZQT__.TTF 12  0,0", T.look(W, "GoodFont"))
	end

	-- The page and the files.
	do
		local W = T.world()
		local ns = W.ns
		local keys = {}
		for _, page in ipairs(ns.PAGES) do
			if page.key == "fonts" then
				for _, item in ipairs(page) do
					keys[#keys + 1] = item.key or ("[" .. item.section .. "]")
				end
			end
		end
		check("ms-fonts: the page has the switch, Typefaces, Style and the game setting, in order", table.concat(keys, ",") == "enabled,[Typefaces],body,numbers,titles,[Style],outline,shadow,size,minimum,[Game setting],gameTextSize", table.concat(keys, ","))
		check("ms-fonts: the new file loads under Lua 5.1 rules", loadfile(ADDON_DIR .. "/Fonts.lua") ~= nil)
		local faces = ns.FontChoices()
		check("ms-fonts: the face rows offer the game's font first and the faces the client loads", #faces == 5 and faces[1][1] == "default" and faces[2][1] == "friz", #faces)
	end
end
-- >>> ms-fonts (end)
-- >>> ms-chat (begin)
-- Tooltips, chat input and chat text (ms-18): the 23 rows, the border of a tooltip, the colours of a unit tooltip, the size and the text of a tooltip,
-- the health bar, the tooltips held back in combat, the extra lines, the chat window border, the input box and the text of the chat windows.
-- The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local T = {}
	function T.rgb(o)
		return o and o.r and ("%.2f,%.2f,%.2f"):format(o.r, o.g, o.b) or "none"
	end
	function T.edge(W, frame)
		return T.rgb(W.look(frame))
	end
	-- The globals the code asks of a client: units, class colours, keys, the item count and the font objects of the tooltips.
	function T.env(W)
		T.units, T.keys, T.fontCalls = {}, {}, 0
		W.env.UnitIsPlayer = function(token) return T.units[token] == "player" end
		W.env.UnitClass = function(token)
			if T.units[token] ~= nil then
				return "Warrior", "WARRIOR", 1
			end
		end
		W.env.RAID_CLASS_COLORS = { WARRIOR = { r = 0.78, g = 0.61, b = 0.43 } }
		W.env.IsShiftKeyDown = function() return T.keys.shift == true end
		W.env.IsControlKeyDown = function() return T.keys.ctrl == true end
		W.env.IsAltKeyDown = function() return T.keys.alt == true end
		W.env.C_Item = { GetItemCount = function(_, bank) return bank and 9 or 4 end }
		T.fonts = {}
		for name, height in pairs({ GameTooltipHeaderText = 14, GameTooltipText = 12, GameTooltipTextSmall = 10 }) do
			local o = { height = height, base = height }
			function o.GetObjectType() return "Font" end
			function o.GetFont() return "Fonts\\FRIZQT__.TTF", o.height, "" end
			function o.SetFont(_, _, h)
				o.height = h
				return true
			end
			function o.SetFontHeight(_, h)
				T.fontCalls = T.fontCalls + 1
				if o.refuse then
					error("SetFontHeight refused", 0)
				end
				o.height = h
			end
			W.env[name] = o
			T.fonts[name] = o
		end
	end
	-- The game adds the name line of a unit and then fills the tooltip from the data.
	function T.line(W, name, lineData)
		local was = W.inBlizzard
		W.inBlizzard = 0
		for _, call in ipairs(W.lineCalls) do
			call[2](W.tips[name].frame, lineData)
		end
		W.inBlizzard = was
	end
	function T.unit(W, name, token, colour, data)
		local rec = W.tips[name]
		rec.lineRaw.textColour = { 1, 1, 1 }
		rec.lines = { { text = "Line 1" }, { text = "Line 2" } }
		T.line(W, name, { type = 17, unitToken = token, leftColor = colour })
		W.again(name, 2, data)
	end
	function T.lines(W, name)
		local out = {}
		for _, line in ipairs(W.tips[name].lines) do
			out[#out + 1] = line.text
		end
		return table.concat(out, "|")
	end
	-- Chat windows that answer the calls of the text part, and log each one.
	function T.text(W)
		T.calls = {}
		for _, w in ipairs(W.windows) do
			local fr = w.raw
			local function log(text)
				T.calls[#T.calls + 1] = w.name .. " " .. text
			end
			fr.fontData, fr.shadowData, fr.maxLines, fr.fading, fr.visible = { "Fonts\\FRIZQT__.TTF", 14, "" }, { 1, -1 }, 128, true, 120
			function fr.GetFont() return unpack(fr.fontData, 1, 3) end
			function fr.SetFont(_, file, size, flags)
				log("SetFont " .. file .. " " .. size .. " " .. flags)
				if fr.refuse then
					return false
				end
				fr.fontData = { file, size, flags }
				return true
			end
			function fr.GetShadowOffset() return fr.shadowData[1], fr.shadowData[2] end
			function fr.SetShadowOffset(_, x, y) log("SetShadowOffset " .. x .. " " .. y) fr.shadowData = { x, y } end
			function fr.GetMaxLines() return fr.maxLines end
			function fr.SetMaxLines(_, n) log("SetMaxLines " .. n) fr.maxLines = n end
			function fr.GetFading() return fr.fading end
			function fr.SetFading(_, v) log("SetFading " .. tostring(v)) fr.fading = v end
			function fr.GetTimeVisible() return fr.visible end
			function fr.SetTimeVisible(_, v) log("SetTimeVisible " .. v) fr.visible = v end
		end
	end
	function T.said(W)
		local text = table.concat(T.calls, "|")
		T.calls = {}
		return text
	end
	function T.state(W, i)
		local fr = W.windows[i].raw
		return ("%s %s %s %s,%s %s %s %s"):format(fr.fontData[1], fr.fontData[2], fr.fontData[3], fr.shadowData[1], fr.shadowData[2], fr.maxLines, tostring(fr.fading), fr.visible)
	end
	T.GAME = "Fonts\\FRIZQT__.TTF 14  1,-1 128 true 120"

	-- The rows.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		local defaults = { tipOwn = false, tipBorder = "ff000000", unitBorder = "plain", nameClass = false, tipScale = 100, tipTitleSize = 100, tipTextSize = 100, barHide = false,
			barHeight = 8, frameBorder = true, inputPlace = "below", inputIdle = 35, inputFocus = "type", combat = "show", combatKey = "none", ids = false, count = false, fadeOut = "fast",
			font = "default", outline = "game", shadow = true, history = 128, fade = true, fadeAfter = 120 }
		local wrong, n = {}, 0
		for key, value in pairs(defaults) do
			n = n + 1
			if ns.Get("chat." .. key) ~= value then
				wrong[#wrong + 1] = key .. "=" .. tostring(ns.Get("chat." .. key))
			end
		end
		check("ms-chat: the 24 rows are at their stand-in defaults", n == 24 and #wrong == 0, table.concat(wrong, ","))
		ns.Set("chat.tipScale", 500)
		ns.Set("chat.tipTextSize", 5)
		ns.Set("chat.barHeight", 40)
		ns.Set("chat.inputIdle", 400)
		ns.Set("chat.history", 9000)
		ns.Set("chat.fadeAfter", 1)
		ns.Set("chat.tipBorder", "zzz")
		ns.Set("chat.combat", "sometimes")
		check("ms-chat: a number is kept to the range of its row, a choice and a colour that are none are refused",
			ns.Get("chat.tipScale") == 200 and ns.Get("chat.tipTextSize") == 70 and ns.Get("chat.barHeight") == 16 and ns.Get("chat.inputIdle") == 100
			and ns.Get("chat.history") == 2048 and ns.Get("chat.fadeAfter") == 10 and ns.Get("chat.tipBorder") == "ff000000" and ns.Get("chat.combat") == "show",
			ns.Get("chat.tipScale") .. " " .. ns.Get("chat.history"))
	end

	-- The border of a tooltip is its own, and the window, the box and the bar keep the page's.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local game, shop = W.tips.GameTooltip, W.tips.ShoppingTooltip1
		W.change("general.border", "ff336699")
		local plain = T.edge(W, game.frame)
		check("ms-chat: with the row off a tooltip has the general border", plain == "0.20,0.40,0.60" and T.edge(W, shop.frame) == plain, plain)
		ns.Set("chat.tipOwn", true)
		ns.Set("chat.tipBorder", "ff112233")
		check("ms-chat: with the row on every tooltip and the label above a comparison tooltip take the colour of the row", T.edge(W, game.frame) == "0.07,0.13,0.20"
			and T.edge(W, W.tips.ItemRefTooltip.frame) == "0.07,0.13,0.20" and T.edge(W, shop.header) == "0.07,0.13,0.20", T.edge(W, game.frame) .. " " .. T.edge(W, shop.header))
		check("ms-chat: the chat window, the input box and the health bar keep the general border", T.edge(W, W.windows[1].bg) == plain and T.edge(W, W.windows[1].box) == plain
			and T.edge(W, game.bar) == plain, T.edge(W, W.windows[1].bg) .. " " .. T.edge(W, game.bar))
		W.fill("GameTooltip", 0, { 0.12, 1, 0 })
		check("ms-chat: the colour of an item still comes first", T.edge(W, game.frame) == "0.12,1.00,0.00", T.edge(W, game.frame))
		W.fill("GameTooltip", 0, { 1, 1, 1 })
		check("ms-chat: a white item name leaves the colour of the row", T.edge(W, game.frame) == "0.07,0.13,0.20", T.edge(W, game.frame))
		ns.Set("chat.tipBorder", "ff445566")
		check("ms-chat: a changed colour repaints at once", T.edge(W, game.frame) == "0.27,0.33,0.40", T.edge(W, game.frame))
		ns.Set("chat.tipOwn", false)
		check("ms-chat: with the row off again the general border is back", T.edge(W, game.frame) == plain, T.edge(W, game.frame))
		-- An outline made while the row is on reads no background row of its own.
		ns.Set("chat.tipOwn", true)
		local frame = W.B(nil, {})
		local o
		ns.Try("chat", function() o = ns.Outline(frame, frame, nil, "tip") end)
		local look = W.look(frame)
		check("ms-chat: an outline of the tip prefix with the row on has the border of the row and the general background, and no error", o ~= nil and T.rgb(look) == "0.27,0.33,0.40"
			and near(look.backdrop.color[4], 0.85) and #W.errors == 0 and #W.violations == 0, T.rgb(look))
	end

	-- The border of a unit tooltip.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local game = W.tips.GameTooltip
		W.change("general.border", "ff336699")
		T.units.mouseover, T.units.target = "player", "mob"
		local red = { r = 1, g = 0, b = 0 }
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: plain leaves the general border on a unit tooltip", T.edge(W, game.frame) == "0.20,0.40,0.60")
		ns.Set("chat.unitBorder", "reaction")
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: reaction takes the colour the game gave the name line", T.edge(W, game.frame) == "1.00,0.00,0.00", T.edge(W, game.frame))
		ns.Set("chat.unitBorder", "class")
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: class takes the class colour of a player", T.edge(W, game.frame) == "0.78,0.61,0.43", T.edge(W, game.frame))
		T.unit(W, "GameTooltip", "target", { r = 0, g = 1, b = 0 })
		check("ms-chat: class takes the reaction colour of a unit that is not a player", T.edge(W, game.frame) == "0.00,1.00,0.00", T.edge(W, game.frame))
		W.env.RAID_CLASS_COLORS.WARRIOR = SECRET
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: a class colour the client withholds falls back to the reaction colour", T.edge(W, game.frame) == "1.00,0.00,0.00", T.edge(W, game.frame))
		W.env.RAID_CLASS_COLORS.WARRIOR = { r = 0.78, g = 0.61, b = 0.43 }
		T.unit(W, "GameTooltip", "target", nil)
		check("ms-chat: a name line with no colour gives no reaction colour", T.edge(W, game.frame) == "0.20,0.40,0.60", T.edge(W, game.frame))
		T.line(W, "GameTooltip", { type = 17, unitToken = SECRET, leftColor = red })
		W.fill("GameTooltip", 2, { 1, 1, 1 })
		check("ms-chat: a token the client withholds changes nothing", T.edge(W, game.frame) == "0.20,0.40,0.60", T.edge(W, game.frame))
		T.unit(W, "GameTooltip", "mouseover", red)
		W.fill("GameTooltip", 0, { 1, 1, 1 })
		check("ms-chat: the colour of a unit is not kept for a tooltip of an item", T.edge(W, game.frame) == "0.20,0.40,0.60", T.edge(W, game.frame))
		ns.Set("chat.unitBorder", "reaction")
		T.unit(W, "GameTooltip", "target", red)
		ns.Set("chat.unitBorder", "plain")
		check("ms-chat: back to plain the general border is back at once", T.edge(W, game.frame) == "0.20,0.40,0.60", T.edge(W, game.frame))
		-- Class colour on names.
		local name = W.tips.GameTooltip.lineRaw
		name.textColour = { 1, 1, 1 }
		ns.Set("chat.unitBorder", "class")
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: the name is not coloured with the row off", name.textColour[1] == 1 and name.textColour[2] == 1)
		ns.Set("chat.unitBorder", "plain")
		ns.Set("chat.nameClass", true)
		T.unit(W, "GameTooltip", "mouseover", red)
		check("ms-chat: with the row on the first line of a player has the class colour", near(name.textColour[1], 0.78) and near(name.textColour[2], 0.61), tostring(name.textColour[1]))
		name.textColour = { 1, 0, 0 }
		T.unit(W, "GameTooltip", "target", red)
		check("ms-chat: the name of a unit that is not a player is left alone", name.textColour[1] == 1 and name.textColour[2] == 1 and name.textColour[3] == 1)
		check("ms-chat: the class colour of a name leaves the border plain", T.edge(W, game.frame) == "0.20,0.40,0.60", T.edge(W, game.frame))
		-- An elite keeps its gold border until a unit colour is chosen.
		ns.Set("chat.nameClass", false)
		T.unit(W, "GameTooltip", "mouseover", red, { type = 2, guid = W.mob("Creature-1", "elite") })
		T.line(W, "GameTooltip", { type = 17, unitToken = "nameplate1", leftColor = red })
		local mob = W.mob("Creature-2", "elite")
		T.units.nameplate1 = "mob"
		W.fill("GameTooltip", 2, { 1, 1, 1 }, { type = 2, guid = mob })
		local gold = T.edge(W, game.frame)
		ns.Set("chat.unitBorder", "reaction")
		T.line(W, "GameTooltip", { type = 17, unitToken = "nameplate1", leftColor = red })
		W.fill("GameTooltip", 2, { 1, 1, 1 }, { type = 2, guid = mob })
		check("ms-chat: an elite has its gold border with plain, and the reaction colour when that is chosen", gold ~= "0.20,0.40,0.60" and gold ~= "1.00,0.00,0.00" and T.edge(W, game.frame) == "1.00,0.00,0.00",
			gold .. " " .. T.edge(W, game.frame))
		check("ms-chat: the unit colour rows make no error", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|"))
	end

	-- The size of a tooltip and of its text.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local sets = 0
		W.tips.ItemRefTooltip.raw.scale = 0.9
		local base = {}
		for name, rec in pairs(W.tips) do
			base[name] = rec.raw.scale
		end
		for _, rec in pairs(W.tips) do
			local set = rec.raw.SetScale
			rec.raw.SetScale = function(...)
				sets = sets + 1
				return set(...)
			end
		end
		W.fire("UPDATE_CHAT_WINDOWS")
		ns.Set("chat.tipOwn", false)
		check("ms-chat: at the default no tooltip or font object is set", sets == 0 and T.fontCalls == 0, sets .. " " .. T.fontCalls)
		ns.Set("chat.tipScale", 150)
		local all = true
		for _, rec in pairs(W.tips) do
			all = all and near(rec.raw.scale, 1.5)
		end
		check("ms-chat: the size sets the scale of every tooltip", all and sets == 6, tostring(sets))
		ns.Set("chat.tipScale", 100)
		all = true
		for name, rec in pairs(W.tips) do
			all = all and near(rec.raw.scale, base[name])
		end
		check("ms-chat: 100 puts the scale the game gave back", all and sets == 12, tostring(sets))
		ns.Set("chat.tipScale", 100)
		check("ms-chat: and a row at 100 sets nothing again", sets == 12)
		W.combat = true
		ns.Set("chat.tipScale", 75)
		local held = near(W.tips.GameTooltip.raw.scale, 1)
		W.endCombat()
		check("ms-chat: in combat the scale waits, and is set when combat ends", held and near(W.tips.GameTooltip.raw.scale, 0.75) and #W.violations == 0)
		W.tips.ItemRefTooltip.raw.scale = 0.75
		W.tips.ItemRefTooltip.raw.forbidden = true
		ns.Set("chat.tipScale", 120)
		check("ms-chat: a tooltip the addon may not touch is left alone", near(W.tips.ItemRefTooltip.raw.scale, 0.75) and near(W.tips.GameTooltip.raw.scale, 1.2) and #W.violations == 0)
		W.tips.ItemRefTooltip.raw.forbidden = nil
		W.tips.ItemRefTooltip.raw.scale = base.ItemRefTooltip
		ns.Set("chat.enabled", false)
		all = true
		for name, rec in pairs(W.tips) do
			all = all and near(rec.raw.scale, base[name])
		end
		check("ms-chat: with the module off every scale is back", all)
		ns.Set("chat.enabled", true)
		check("ms-chat: and on again the size of the row is set again", near(W.tips.GameTooltip.raw.scale, 1.2))
		ns.Set("chat.tipScale", 100)
		-- Text.
		local f = T.fonts
		ns.Set("chat.tipTitleSize", 150)
		check("ms-chat: the title size sets the height of the title font only", near(f.GameTooltipHeaderText.height, 21) and f.GameTooltipText.height == 12 and f.GameTooltipTextSmall.height == 10,
			f.GameTooltipHeaderText.height)
		ns.Set("chat.tipTextSize", 130)
		check("ms-chat: the text size sets the height of the two text fonts", near(f.GameTooltipText.height, 15.6) and near(f.GameTooltipTextSmall.height, 13) and near(f.GameTooltipHeaderText.height, 21),
			f.GameTooltipText.height)
		f.GameTooltipText.height = 20
		ns.Set("chat.tipTextSize", 100)
		check("ms-chat: a height the game set since is the one it keeps at 100", f.GameTooltipText.height == 20 and near(f.GameTooltipTextSmall.height, 10), f.GameTooltipText.height)
		ns.Set("chat.tipTextSize", 150)
		check("ms-chat: and the one the share is taken of", near(f.GameTooltipText.height, 30) and near(f.GameTooltipTextSmall.height, 15), f.GameTooltipText.height)
		ns.Set("chat.tipTextSize", 100)
		ns.Set("chat.tipTitleSize", 100)
		check("ms-chat: back at 100 every font object has the height it had", f.GameTooltipText.height == 20 and f.GameTooltipTextSmall.height == 10 and f.GameTooltipHeaderText.height == 14)
		ns.Set("chat.tipTitleSize", 140)
		ns.Set("chat.enabled", false)
		check("ms-chat: with the module off the title is back too", f.GameTooltipHeaderText.height == 14)
		ns.Set("chat.enabled", true)
		ns.Set("chat.tipTitleSize", 100)
		ns.Set("chat.tipTextSize", 100)
		-- A refusal stops the part, puts the heights back and says so.
		for _, o in pairs(f) do
			o.refuse = true
		end
		ns.Set("chat.tipTitleSize", 120)
		ns.Set("chat.tipTextSize", 120)
		ns.Set("chat.tipTextSize", 110)
		local status = W.status()
		for _, o in pairs(f) do
			o.refuse = nil
		end
		check("ms-chat: a refused height stops the part with a line for the status", status:find("tooltip text size stopped", 1, true) ~= nil and #W.errors == 0, status)
		ns.Set("chat.tipTextSize", 100)
		ns.Set("chat.tipTitleSize", 100)
		check("ms-chat: and the heights are the game's", f.GameTooltipText.height == 20 and f.GameTooltipTextSmall.height == 10 and f.GameTooltipHeaderText.height == 14)
	end

	-- With the Fonts module on, one module writes the tooltip fonts: a change elsewhere does not grow them again.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local f = T.fonts
		ns.Set("fonts.enabled", true)
		ns.Set("fonts.size", 110)
		ns.Set("chat.tipTextSize", 150)
		ns.Set("general.thickness", 2)
		ns.Set("general.thickness", 3)
		check("ms-chat: with Fonts on and both rows set, a change on the General page leaves the tooltip text at the product of the two", near(f.GameTooltipText.height, 19.8, 0.01), f.GameTooltipText.height)
		ns.Set("fonts.enabled", false)
		ns.Set("chat.enabled", false)
		check("ms-chat: with both modules off the tooltip text is the game's again", near(f.GameTooltipText.height, 12, 0.01), f.GameTooltipText.height)
	end

	-- The health bar of the tooltip.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local bar = W.tips.GameTooltip.bar
		local raw = W.rawOf[bar]
		local heights = 0
		local setHeight = raw.SetHeight
		raw.SetHeight = function(...)
			heights = heights + 1
			return setHeight(...)
		end
		W.fire("UPDATE_CHAT_WINDOWS")
		ns.Set("chat.tipScale", 100)
		check("ms-chat: at the defaults the bar is as the game made it", heights == 0 and raw.height == 8 and (raw.alpha or 1) == 1 and W.look(bar).shown, tostring(heights))
		ns.Set("chat.barHide", true)
		check("ms-chat: Hide the health bar fades the bar and hides its border", raw.alpha == 0 and W.look(bar).hidden, tostring(raw.alpha))
		ns.Set("chat.barHide", false)
		check("ms-chat: and shows them again", raw.alpha == 1 and W.look(bar).shown)
		ns.Set("chat.barHide", true)
		ns.Set("chat.enabled", false)
		check("ms-chat: with the module off the bar is shown", raw.alpha == 1)
		ns.Set("chat.enabled", true)
		check("ms-chat: and on again it is hidden", raw.alpha == 0)
		ns.Set("chat.barHide", false)
		ns.Set("chat.barHeight", 12)
		check("ms-chat: the height row sets the height of the bar", raw.height == 12 and heights == 1, tostring(raw.height))
		ns.Set("chat.barHeight", 8)
		check("ms-chat: 8 puts the height of the XML back", raw.height == 8 and heights == 2)
		ns.Set("chat.barHeight", 8)
		check("ms-chat: a row at 8 sets nothing again", heights == 2)
		W.combat = true
		ns.Set("chat.barHeight", 5)
		local held = raw.height == 8
		W.endCombat()
		check("ms-chat: in combat the height waits and is set when combat ends", held and raw.height == 5 and #W.violations == 0)
		ns.Set("chat.enabled", false)
		check("ms-chat: with the module off the height is back", raw.height == 8)
		ns.Set("chat.enabled", true)
		ns.Set("chat.barHeight", 8)
	end

	-- Tooltips held back in combat.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local game = W.tips.GameTooltip
		local raw = W.rawOf[game.frame]
		local red = { r = 1, g = 0, b = 0 }
		T.units.mouseover = "mob"
		local function shown() return raw.shown == true end
		local function up(unit)
			raw.shown = true
			if unit then
				T.unit(W, "GameTooltip", "mouseover", red)
			else
				W.fill("GameTooltip", 0, { 1, 1, 1 })
			end
			return shown()
		end
		W.combat = true
		check("ms-chat: with the row at Show as usual nothing is held back in combat", up(true) and up(false))
		ns.Set("chat.combat", "units")
		check("ms-chat: out of combat nothing is held back", (function() W.combat = false local r = up(true) W.combat = true return r end)())
		check("ms-chat: Hide unit tooltips hides a unit tooltip in combat", not up(true))
		raw.GetOwner = function() return W.env.UIParent end
		check("ms-chat: and a tooltip the game owns by the screen itself", not up(false))
		raw.GetOwner = function() return W.windows[1].frame end
		check("ms-chat: but not the tooltip of an item on a window", up(false))
		ns.Set("chat.combatKey", "shift")
		check("ms-chat: a unit tooltip stays while the chosen key is held", (function() T.keys.shift = true local r = up(true) T.keys.shift = nil return r end)())
		check("ms-chat: and goes without it", not up(true))
		T.keys.ctrl = true
		check("ms-chat: another key does not keep it", not up(true))
		T.keys.ctrl = nil
		ns.Set("chat.combat", "all")
		check("ms-chat: Hide every tooltip hides the tooltip of an item", not up(false))
		ns.Set("chat.combatKey", "alt")
		check("ms-chat: the chosen key keeps every tooltip", (function() T.keys.alt = true local r = up(false) T.keys.alt = nil return r end)())
		-- The game shows it.
		raw.shown = false
		W.blizzard(function() game.frame:Show() end)
		W.flush()
		check("ms-chat: a tooltip the game shows in combat is hidden at once", not shown())
		W.combat = false
		W.blizzard(function() game.frame:Show() end)
		W.flush()
		check("ms-chat: and shown out of combat", shown())
		W.combat = true
		ns.Set("chat.combat", "show")
		raw.shown = false
		W.blizzard(function() game.frame:Show() end)
		W.flush()
		check("ms-chat: back to Show as usual the tooltip is shown in combat", shown())
		W.combat = false
		check("ms-chat: the rows make no error", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|"))
	end

	-- The status line of Tooltips in combat.
	do
		local V = { W = FH.chatStarted() }
		V.ns = V.W.ns
		check("ms-chat status: the line says Show as usual by default", V.W.line("Tooltips in combat") == "Tooltips in combat: Show as usual", tostring((V.W.line("Tooltips in combat"))))
		V.ns.Set("chat.combatKey", "shift")
		check("ms-chat status: a key with Show as usual is not named", V.W.line("Tooltips in combat") == "Tooltips in combat: Show as usual")
		V.ns.Set("chat.combat", "units")
		check("ms-chat status: Hide unit tooltips and the key", V.W.line("Tooltips in combat") == "Tooltips in combat: Hide unit tooltips, shown while you hold Shift", tostring((V.W.line("Tooltips in combat"))))
		V.ns.Set("chat.combatKey", "none")
		check("ms-chat status: Hide unit tooltips with no key", V.W.line("Tooltips in combat") == "Tooltips in combat: Hide unit tooltips")
		V.ns.Set("chat.combat", "all")
		check("ms-chat status: Hide every tooltip", V.W.line("Tooltips in combat") == "Tooltips in combat: Hide every tooltip")
		V.ns.Set("chat.enabled", false)
		check("ms-chat status: no line with the module off", V.W.line("Tooltips in combat") == nil)
		V.ns.Set("chat.enabled", true)
		V.ns.Set("chat.combat", "show")
	end

	-- Hide unit tooltips: a tooltip of text after a unit tooltip.
	do
		local V = { W = FH.chatStarted() }
		V.ns, V.game = V.W.ns, V.W.tips.GameTooltip
		V.raw = V.W.rawOf[V.game.frame]
		T.env(V.W)
		T.units.mouseover = "mob"
		V.unitOwner, V.barOwner = V.W.windows[1].frame, V.W.env.CreateFrame("Frame")
		V.raw.GetOwner = function() return V.owner end
		V.ns.Set("chat.combat", "units")
		V.W.combat = true
		V.owner = V.unitOwner
		V.raw.shown = true
		T.unit(V.W, "GameTooltip", "mouseover", { r = 1, g = 0, b = 0 })
		check("ms-chat stale: a unit tooltip is hidden in combat", V.raw.shown ~= true)
		V.owner = V.barOwner
		V.raw.shown = false
		V.game.frame:Show()
		check("ms-chat stale: a tooltip of text of another owner after a unit tooltip shows in combat", V.raw.shown == true)
		V.owner = V.unitOwner
		V.raw.shown = true
		T.unit(V.W, "GameTooltip", "mouseover", { r = 1, g = 0, b = 0 })
		check("ms-chat stale: the next unit tooltip is hidden again", V.raw.shown ~= true)
		V.raw.shown = true
		T.unit(V.W, "GameTooltip", "mouseover", { r = 1, g = 0, b = 0 })
		V.raw.shown = false
		V.game.frame:Show()
		check("ms-chat stale: a unit tooltip built again and shown is hidden", V.raw.shown ~= true)
		V.raw.GetOwner = function() return SECRET end
		V.raw.shown = true
		T.unit(V.W, "GameTooltip", "mouseover", { r = 1, g = 0, b = 0 })
		V.raw.GetOwner = function() return V.barOwner end
		V.raw.shown = false
		V.game.frame:Show()
		check("ms-chat stale: with a withheld owner at the build, a later tooltip is held back as before", V.raw.shown ~= true)
		V.raw.GetOwner = function() return V.unitOwner end
		V.raw.shown = true
		T.unit(V.W, "GameTooltip", "mouseover", { r = 1, g = 0, b = 0 })
		V.raw.GetOwner = function() return nil end
		V.raw.shown = false
		V.game.frame:Show()
		V.raw.shown = false
		V.game.frame:Show()
		check("ms-chat stale: a unit tooltip shown again with no owner read stays hidden", V.raw.shown ~= true)
		V.W.combat = false
		check("ms-chat stale: nothing raises", #V.W.errors == 0 and #V.W.violations == 0, table.concat(V.W.violations, "|"))
	end

	-- The lines for IDs and counts.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local item = { type = 0, id = 1234 }
		W.fill("GameTooltip", 0, { 1, 1, 1 }, item)
		check("ms-chat: with both rows off an item tooltip gets no line", T.lines(W, "GameTooltip") == "Line 1|Line 2")
		ns.Set("chat.ids", true)
		W.fill("GameTooltip", 0, { 1, 1, 1 }, item)
		check("ms-chat: Item and spell IDs adds the ID of an item", T.lines(W, "GameTooltip") == "Line 1|Line 2|Item ID: 1234", T.lines(W, "GameTooltip"))
		W.again("GameTooltip", 0, item)
		check("ms-chat: the same build is not given the line twice", T.lines(W, "GameTooltip") == "Line 1|Line 2|Item ID: 1234", T.lines(W, "GameTooltip"))
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: a new build has the line again", T.lines(W, "GameTooltip") == "Line 1|Line 2|Item ID: 1234")
		W.fill("GameTooltip", 1, { 1, 1, 1 }, { type = 1, id = 77 })
		check("ms-chat: and the ID of a spell", T.lines(W, "GameTooltip") == "Line 1|Line 2|Spell ID: 77", T.lines(W, "GameTooltip"))
		W.fill("GameTooltip", 2, { 1, 1, 1 }, { type = 2, id = 5 })
		check("ms-chat: a unit tooltip gets none", T.lines(W, "GameTooltip") == "Line 1|Line 2")
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = SECRET })
		check("ms-chat: an ID the client withholds adds nothing", T.lines(W, "GameTooltip") == "Line 1|Line 2")
		ns.Set("chat.count", true)
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: Item count in bags and bank adds the count after the ID, and the bank when it has more", T.lines(W, "GameTooltip") == "Line 1|Line 2|Item ID: 1234|Count: 4 in bags, 9 with bank",
			T.lines(W, "GameTooltip"))
		ns.Set("chat.ids", false)
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: the count alone", T.lines(W, "GameTooltip") == "Line 1|Line 2|Count: 4 in bags, 9 with bank", T.lines(W, "GameTooltip"))
		W.fill("GameTooltip", 1, { 1, 1, 1 }, { type = 1, id = 77 })
		check("ms-chat: a spell has no count", T.lines(W, "GameTooltip") == "Line 1|Line 2")
		W.env.C_Item.GetItemCount = function(_, bank) return 3 end
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: a bank with no more is not named", T.lines(W, "GameTooltip") == "Line 1|Line 2|Count: 3 in bags", T.lines(W, "GameTooltip"))
		W.env.C_Item.GetItemCount = function() return SECRET end
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: a count the client withholds adds nothing", T.lines(W, "GameTooltip") == "Line 1|Line 2")
		W.env.C_Item = nil
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		check("ms-chat: a client with no item count adds nothing and makes no error", T.lines(W, "GameTooltip") == "Line 1|Line 2" and #W.errors == 0 and #W.violations == 0)
		ns.Set("chat.ids", true)
		local tip = W.tips.GameTooltip
		tip.fault = "AddLine"
		W.fill("GameTooltip", 0, { 1, 1, 1 }, { type = 0, id = 1234 })
		tip.fault = nil
		check("ms-chat: a tooltip that refuses a line is left as it is", T.lines(W, "GameTooltip") == "Line 1|Line 2" and #W.errors == 0)
	end

	-- The border of the chat window, and the input box.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local w1, w2 = W.windows[1], W.windows[2]
		check("ms-chat: at the default the chat windows have their borders", W.look(w1.bg).shown and W.look(w2.bg).shown)
		ns.Set("chat.frameBorder", false)
		check("ms-chat: Chat window border off hides the edges of every window and keeps the background", W.look(w1.bg).hidden and W.look(w1.bg).backShown and W.look(w2.bg).hidden)
		ns.Set("chat.frameBorder", true)
		check("ms-chat: and on shows them again", W.look(w1.bg).shown)
		ns.Set("chat.frameBorder", false)
		ns.Set("chat.frames", false)
		check("ms-chat: with the window background off the window has no outline of its own", W.look(w1.bg).hidden and not W.look(w1.bg).backShown)
		ns.Set("chat.frames", true)
		ns.Set("chat.frameBorder", true)
		-- Input box: the points of the game, the focus art and the colour.
		for _, w in ipairs(W.windows) do
			w.box:SetPoint("TOPLEFT", w.frame, "BOTTOMLEFT", -5, -2)
			w.box:SetPoint("RIGHT", w.tab, "RIGHT", 8, 0)
			local br = w.boxRaw
			br.alpha = 0.35
			function br.Deactivate()
				br.alpha, br.focus = 0.35, false
			end
			function br.HasFocus() return br.focus == true end
		end
		local function points(w)
			local out = {}
			for _, p in ipairs(W.rawOf[w.box].points) do
				out[#out + 1] = ("%s>%s %s %s %s"):format(p[1], p[2] == w.frame and "window" or "other", p[3], p[4], p[5])
			end
			return table.concat(out, "|")
		end
		local CALLS, ALPHAS = 0, 0
		local setAlpha = w1.boxRaw.SetAlpha
		w1.boxRaw.SetAlpha = function(...)
			ALPHAS = ALPHAS + 1
			return setAlpha(...)
		end
		local clear = W.rawOf[w1.box].ClearAllPoints
		W.rawOf[w1.box].ClearAllPoints = function(...)
			CALLS = CALLS + 1
			return clear(...)
		end
		W.fire("UPDATE_CHAT_WINDOWS")
		ns.Set("chat.tipOwn", false)
		check("ms-chat: at the defaults the box keeps its points and its opacity", CALLS == 0 and ALPHAS == 0 and points(w1) == "TOPLEFT>window BOTTOMLEFT -5 -2|RIGHT>other RIGHT 8 0" and w1.boxRaw.alpha == 0.35)
		ns.Set("chat.inputPlace", "above")
		check("ms-chat: above puts the left corner on the top left of the window and keeps the point on the right",
			points(w1) == "BOTTOMLEFT>window TOPLEFT -5 2|RIGHT>other RIGHT 8 0" and points(w2) == "BOTTOMLEFT>window TOPLEFT -5 2|RIGHT>other RIGHT 8 0", points(w1))
		ns.Set("chat.inputPlace", "above")
		check("ms-chat: and a row that is already above does it once", CALLS == 1, tostring(CALLS))
		ns.Set("chat.inputPlace", "below")
		check("ms-chat: below puts the two points the game gave back", points(w1) == "TOPLEFT>window BOTTOMLEFT -5 -2|RIGHT>other RIGHT 8 0" and points(w2) == points(w1), points(w1))
		ns.Set("chat.inputPlace", "above")
		ns.Set("chat.enabled", false)
		check("ms-chat: with the module off the points are back", points(w1) == "TOPLEFT>window BOTTOMLEFT -5 -2|RIGHT>other RIGHT 8 0")
		ns.Set("chat.enabled", true)
		check("ms-chat: and on again the box is above", points(w1) == "BOTTOMLEFT>window TOPLEFT -5 2|RIGHT>other RIGHT 8 0")
		ns.Set("chat.inputPlace", "below")
		-- Idle opacity.
		ns.Set("chat.inputIdle", 60)
		check("ms-chat: an idle box has the opacity of the row", w1.boxRaw.alpha == 0.6 and w2.boxRaw.alpha == 0.6, tostring(w1.boxRaw.alpha))
		w1.boxRaw.alpha, w1.boxRaw.focus = 1, true
		ns.Set("chat.inputIdle", 80)
		check("ms-chat: a box with the focus keeps the opacity the game gave it", w1.boxRaw.alpha == 1 and w2.boxRaw.alpha == 0.8)
		W.blizzard(function() w1.box:Deactivate() end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", w1.box)
		W.flush()
		check("ms-chat: the game sets 0.35 when it closes and the row sets its opacity on the next frame", w1.boxRaw.alpha == 0.8, tostring(w1.boxRaw.alpha))
		ns.Set("chat.inputIdle", 35)
		check("ms-chat: 35 puts the game's opacity back", w1.boxRaw.alpha == 0.35 and w2.boxRaw.alpha == 0.35)
		W.blizzard(function() w1.box:Deactivate() end)
		W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusLost", w1.box)
		W.flush()
		check("ms-chat: and the box is then the game's", w1.boxRaw.alpha == 0.35)
		w1.boxRaw.isGM = true
		w1.boxRaw.alpha = 1
		ns.Set("chat.inputIdle", 10)
		check("ms-chat: a box of the game masters is left alone", w1.boxRaw.alpha == 1 and w2.boxRaw.alpha == 0.1)
		w1.boxRaw.isGM = nil
		ns.Set("chat.inputIdle", 35)
		-- The colour of the border while typing.
		for _, w in ipairs(W.windows) do
			W.blizzard(function()
				w.box:SetFocusRegionsShown(true)
				w.box:SetFocusRegionVertexColors({ r = 1, g = 0.5, b = 0.25 })
			end)
			W.registry:TriggerEvent("ChatFrame.OnEditBoxFocusGained", w.box)
		end
		W.flush()
		check("ms-chat: the border while typing has the colour of the chat type", T.edge(W, w1.box) == "1.00,0.50,0.25", T.edge(W, w1.box))
		ns.Set("chat.inputFocus", "accent")
		local ar, ag, ab = ns.Colour("windows.accent")
		check("ms-chat: Highlight colour takes the highlight colour", T.edge(W, w1.box) == ("%.2f,%.2f,%.2f"):format(ar, ag, ab), T.edge(W, w1.box))
		ns.Set("chat.inputFocus", "plain")
		local br, bg, bb = ns.BorderRGB()
		check("ms-chat: Plain border takes the general border", T.edge(W, w1.box) == ("%.2f,%.2f,%.2f"):format(br, bg, bb), T.edge(W, w1.box))
		ns.Set("chat.inputFocus", "type")
		check("ms-chat: and back to the chat type colour", T.edge(W, w1.box) == "1.00,0.50,0.25")
		check("ms-chat: the rows of the box make no error", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|"))
	end

	-- The input box refuses.
	do
		local W = FH.chatStarted()
		local ns = W.ns
		T.env(W)
		local w1 = W.windows[1]
		w1.box:SetPoint("TOPLEFT", w1.frame, "BOTTOMLEFT", -5, -2)
		w1.box:SetPoint("BOTTOMRIGHT", w1.tab, "BOTTOMRIGHT", 8, 0)
		w1.boxRaw.GetPoint = function() return "TOPLEFT", w1.frame, "BOTTOMLEFT", SECRET, -2 end
		ns.Set("chat.inputPlace", "above")
		check("ms-chat: a point the client withholds leaves the box where it is, without an error", #W.errors == 0 and #W.violations == 0 and #W.rawOf[w1.box].points == 2)
		local w2 = W.windows[2]
		w2.box:SetPoint("TOPLEFT", w2.frame, "BOTTOMLEFT", -5, -2)
		w2.box:SetPoint("TOP", w2.tab, "TOP", 8, 0)
		ns.Set("chat.inputPlace", "below")
		ns.Set("chat.inputPlace", "above")
		check("ms-chat: a box with no point on its right stays where it is", #W.rawOf[w2.box].points == 2 and W.rawOf[w2.box].points[1][1] == "TOPLEFT")
	end

	-- The text of the chat windows.
	do
		local W = FH.chatStarted({ windows = 3 })
		local ns = W.ns
		T.env(W)
		T.text(W)
		W.fontReturn = "true"
		W.fire("UPDATE_CHAT_WINDOWS")
		W.fire("PLAYER_ENTERING_WORLD")
		check("ms-chat: at the defaults no chat window is set", T.said(W) == "")
		ns.Set("chat.font", "arial")
		local face = T.said(W)
		check("ms-chat: a font sets the face of every window and keeps the size and the outline", face == "ChatFrame1 SetFont Fonts\\ARIALN.TTF 14 |ChatFrame2 SetFont Fonts\\ARIALN.TTF 14 |ChatFrame3 SetFont Fonts\\ARIALN.TTF 14 ",
			face)
		ns.Set("chat.outline", "thick")
		check("ms-chat: an outline keeps the face", T.said(W) ~= "" and T.state(W, 1) == "Fonts\\ARIALN.TTF 14 THICKOUTLINE 1,-1 128 true 120", T.state(W, 1))
		for _, w in ipairs(W.windows) do
			local fr = w.raw
			fr.SetFont(nil, (fr.GetFont()), 18, select(3, fr.GetFont()))
		end
		T.said(W)
		W.fire("UPDATE_CHAT_WINDOWS")
		check("ms-chat: a size the game set since is kept, and the face and the outline stay without a call", T.said(W) == "" and T.state(W, 2) == "Fonts\\ARIALN.TTF 18 THICKOUTLINE 1,-1 128 true 120", T.state(W, 2))
		ns.Set("chat.outline", "none")
		check("ms-chat: none takes the outline off", T.state(W, 3) == "Fonts\\ARIALN.TTF 18  1,-1 128 true 120", T.state(W, 3))
		ns.Set("chat.font", "default")
		ns.Set("chat.outline", "game")
		check("ms-chat: the game's face and outline come back at the size the game has now", T.state(W, 1) == "Fonts\\FRIZQT__.TTF 18  1,-1 128 true 120", T.state(W, 1))
		T.said(W)
		ns.Set("chat.shadow", false)
		check("ms-chat: shadow off sets the offset to nothing", T.said(W) == "ChatFrame1 SetShadowOffset 0 0|ChatFrame2 SetShadowOffset 0 0|ChatFrame3 SetShadowOffset 0 0" and T.state(W, 1):find(" 0,0 ", 1, true) ~= nil)
		ns.Set("chat.shadow", true)
		check("ms-chat: and on puts the offset of the game back", T.state(W, 3):find(" 1,-1 ", 1, true) ~= nil)
		T.said(W)
		ns.Set("chat.history", 512)
		check("ms-chat: Lines kept sets the lines of every window", T.said(W) == "ChatFrame1 SetMaxLines 512|ChatFrame2 SetMaxLines 512|ChatFrame3 SetMaxLines 512" and W.windows[2].raw.maxLines == 512)
		ns.Set("chat.history", 128)
		check("ms-chat: and 128 puts the game's back", W.windows[2].raw.maxLines == 128)
		T.said(W)
		ns.Set("chat.fade", false)
		check("ms-chat: Fade old messages off turns the fading off", T.said(W) == "ChatFrame1 SetFading false|ChatFrame2 SetFading false|ChatFrame3 SetFading false" and W.windows[1].raw.fading == false)
		ns.Set("chat.fade", true)
		check("ms-chat: and on turns it on again", W.windows[1].raw.fading == true)
		T.said(W)
		ns.Set("chat.fadeAfter", 300)
		check("ms-chat: Fade after sets the time", T.said(W) == "ChatFrame1 SetTimeVisible 300|ChatFrame2 SetTimeVisible 300|ChatFrame3 SetTimeVisible 300" and W.windows[3].raw.visible == 300)
		ns.Set("chat.fade", false)
		check("ms-chat: with the fading off the time is the game's", W.windows[3].raw.visible == 120 and W.windows[3].raw.fading == false)
		ns.Set("chat.fade", true)
		check("ms-chat: and with it on again the time of the row is back", W.windows[3].raw.visible == 300 and W.windows[3].raw.fading == true)
		ns.Set("chat.fadeAfter", 120)
		check("ms-chat: 120 puts the game's time back", W.windows[3].raw.visible == 120)
		-- A window the game makes later is styled when it tells the addon.
		local listed = W.env.CHAT_FRAMES[3]
		W.env.CHAT_FRAMES[3] = nil
		ns.Set("chat.history", 320)
		local late = W.windows[3].raw.maxLines
		W.env.CHAT_FRAMES[3] = listed
		W.fire("UPDATE_CHAT_WINDOWS")
		local viaUpdate = W.windows[3].raw.maxLines
		W.env.CHAT_FRAMES[3] = nil
		ns.Set("chat.history", 384)
		W.env.CHAT_FRAMES[3] = listed
		W.fire("PLAYER_ENTERING_WORLD")
		check("ms-chat: a window that is not listed yet has the game's value, and is set at UPDATE_CHAT_WINDOWS and at PLAYER_ENTERING_WORLD", late == 128 and viaUpdate == 320
			and W.windows[3].raw.maxLines == 384, tostring(late) .. " " .. tostring(viaUpdate))
		ns.Set("chat.history", 128)
		-- The module off puts every value back.
		ns.Set("chat.font", "arial")
		ns.Set("chat.outline", "outline")
		ns.Set("chat.shadow", false)
		ns.Set("chat.history", 1024)
		ns.Set("chat.fade", false)
		ns.Set("chat.fadeAfter", 200)
		local changed = T.state(W, 2)
		ns.Set("chat.enabled", false)
		check("ms-chat: with the module off every window has the values the game gave it, at the size it has now",
			changed ~= T.state(W, 2) and T.state(W, 2) == "Fonts\\FRIZQT__.TTF 18  1,-1 128 true 120" and T.state(W, 1) == T.state(W, 3), T.state(W, 2))
		ns.Set("chat.enabled", true)
		check("ms-chat: and on again the rows are set again", T.state(W, 2):find("ARIALN", 1, true) ~= nil and W.windows[2].raw.maxLines == 1024 and W.windows[2].raw.fading == false)
		check("ms-chat: the chat text rows make no error", #W.errors == 0 and #W.violations == 0, table.concat(W.violations, "|"))
	end

	-- A window that refuses stops the part.
	do
		local W = FH.chatStarted({ windows = 3 })
		local ns = W.ns
		T.env(W)
		T.text(W)
		W.fontReturn = "true"
		for _, w in ipairs(W.windows) do
			w.raw.refuse = true
		end
		ns.Set("chat.font", "arial")
		local status = W.status()
		check("ms-chat: a font the windows refuse stops the part with a line for the status, and no error", status:find("chat font stopped", 1, true) ~= nil and #W.errors == 0, status)
		check("ms-chat: the windows keep the face the game gave", T.state(W, 1) == T.GAME and T.state(W, 3) == T.GAME)
		for _, w in ipairs(W.windows) do
			w.raw.refuse = nil
		end
		ns.Set("chat.history", 256)
		check("ms-chat: the other parts go on", W.windows[1].raw.maxLines == 256)
		ns.Set("chat.font", "default")
		check("ms-chat: the stopped part sets nothing when the row goes back", T.state(W, 1):find("FRIZQT", 1, true) ~= nil)
	end

	-- A client without the calls, and the files.
	do
		local W = FH.chatStarted({ noChat = true })
		T.env(W)
		W.ns.Set("chat.font", "arial")
		W.ns.Set("chat.tipScale", 150)
		check("ms-chat: a client with no chat windows makes no error", #W.errors == 0 and #W.violations == 0)
		local V = FH.chatStarted({ noData = true, noTips = true })
		T.env(V)
		V.ns.Set("chat.unitBorder", "class")
		V.ns.Set("chat.combat", "all")
		V.ns.Set("chat.ids", true)
		check("ms-chat: a client with no tooltip data or tooltips makes no error", #V.errors == 0 and #V.violations == 0, table.concat(V.errors, "|"))
		check("ms-chat: the new file loads under Lua 5.1 rules", loadfile(ADDON_DIR .. "/ChatText.lua") ~= nil)
	end
end
-- >>> ms-chat (end)
-- >>> ms-fade (begin)
-- Fading (Fade.lua): the frames go to a low opacity while nothing asks for them. The values are kept in one table M.
do
	local K = suiteKit
	local M = { spot = { FlatUIBarBlock = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } }, away = { 1000, 900 },
		made = { "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBarRight", "MultiBarLeft", "MultiBar5", "MultiBar6", "MultiBar7", "StanceBar",
			"PetActionBar", "MicroMenuContainer", "BagsBar", "PetFrame", "GameTimeFrame", "TimeManagerClockButton",
			"AddonCompartmentFrame" },
		rows = { main = { "MainActionBar" }, bar2 = { "MultiBarBottomLeft" }, bar3 = { "MultiBarBottomRight" }, bar4 = { "MultiBarRight" }, bar5 = { "MultiBarLeft" },
			bar6 = { "MultiBar5" }, bar7 = { "MultiBar6" }, bar8 = { "MultiBar7" }, stance = { "StanceBar" }, pet = { "PetActionBar" }, micro = { "MicroMenuContainer" },
			bags = { "BagsBar" }, playerFrame = { "FadeBox", "FadeInner" }, petFrame = { "PetFrame" },
			minimapButtons = { "FadeTracking", "FadeIndicator", "GameTimeFrame", "TimeManagerClockButton", "AddonCompartmentFrame" } } }
	-- A world with Fade on and the options given. Every frame the page names answers GetAlpha; the main bar starts at 0.8, the rest at 1. A frame the layout
	-- does not make is made here, in a row at the bottom of the screen, and the two frames of the minimap cluster inside it.
	function M.world(options, prep, skip)
		local saved = { ["fade.enabled"] = true }
		for key, value in pairs(options or {}) do
			saved[key] = value
		end
		return K.mwBefore({ layout = { systems = true, bars = true }, saved = K.opt(saved, M.spot) }, function(W)
			local ui, x = W.env.UIParent, 60
			for _, name in ipairs(M.made) do
				if not W.env[name] and not (skip and skip[name]) then
					W.bframe(name, { point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", x, 120 }, width = 90, height = 40 })
					x = x + 130
				end
			end
			for index, key in ipairs({ "Tracking", "IndicatorFrame" }) do
				local child = W.bframe("Fade" .. (key == "Tracking" and key or "Indicator"), { parent = W.env.MinimapCluster,
					point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 1740, 900 + 30 * index }, width = 40, height = 20 })
				W.rawOf[W.env.MinimapCluster][key] = child
			end
			-- PlayerFrameContainer and PlayerFrameContent are parentKeys of PlayerFrame with no global name (PlayerFrame.xml:23, :68).
			for index, pair in ipairs({ { "PlayerFrameContainer", "FadeBox" }, { "PlayerFrameContent", "FadeInner" } }) do
				local child = W.bframe(pair[2], { parent = W.env.PlayerFrame, point = { "BOTTOMLEFT", ui, "BOTTOMLEFT", 1500, 400 + 30 * index }, width = 40, height = 20 })
				W.rawOf[W.env.PlayerFrame][pair[1]] = child
			end
			for _, list in pairs(M.rows) do
				for _, name in ipairs(list) do
					local frame = W.env[name] and W.rawOf[W.env[name]]
					if frame then
						frame.alpha = name == "MainActionBar" and 0.8 or 1
						frame.GetAlpha = function()
							return frame.alpha
						end
					end
				end
			end
			W.env.UnitExists = function()
				return W.target == true
			end
			W.env.UnitAffectingCombat = function()
				return W.engaged == true
			end
			W.cursor = { M.away[1], M.away[2] }
			if prep then
				prep(W)
			end
		end)
	end
	function M.raw(W, name)
		return W.rawOf[W.env[name]]
	end
	function M.alpha(W, name)
		return M.raw(W, name).alpha
	end
	function M.writes(W, name)
		return M.raw(W, name).calls.SetAlpha or 0
	end
	function M.adv(W, seconds)
		W.run(seconds, 0.05)
	end
	function M.over(W, name)
		local l, b, w, h = W.rectOf(W.env[name])
		W.cursor = { l + w / 2, b + h / 2 }
	end
	function M.updaters(W)
		local n = 0
		for _, f in ipairs(W.updaters) do
			if f.scripts and f.scripts.OnUpdate and f.shown and not f.dividers then
				n = n + 1
			end
		end
		return n
	end
	-- The alpha of every frame of a row, as text.
	function M.row(W, row)
		local parts = {}
		for _, name in ipairs(M.rows[row]) do
			parts[#parts + 1] = name:sub(1, 8) .. "=" .. tostring(M.alpha(W, name))
		end
		return table.concat(parts, " ")
	end
	function M.rowAt(W, row, value)
		for _, name in ipairs(M.rows[row]) do
			if math.abs(M.alpha(W, name) - value) > 1e-9 then
				return false
			end
		end
		return true
	end
	do
		-- Off, and on with no row ticked: nothing is written and the frames keep their alpha.
		local O = M.world({ ["fade.enabled"] = false, ["fade.main"] = true })
		M.adv(O, 2)
		check("ms-fade: off: no frame is written and the status says off", M.writes(O, "MainActionBar") == 0 and M.alpha(O, "MainActionBar") == 0.8 and O.line("Fading") == "Fading: off" and K.allClean(O), K.problems(O))
		local N = M.world({})
		M.adv(N, 2)
		local count = 0
		for _, list in pairs(M.rows) do
			for _, name in ipairs(list) do
				count = count + M.writes(N, name)
			end
		end
		check("ms-fade: on with no row ticked: no frame is written", count == 0 and M.alpha(N, "MainActionBar") == 0.8 and K.allClean(N), count)
		check("ms-fade: on runs one frame of its own more than off", M.updaters(N) == M.updaters(O) + 1, M.updaters(N) .. " " .. M.updaters(O))
	end
	do
		-- Wait before fading, the ease, and a frame that is not written again once it has its value.
		local W = M.world({ ["fade.main"] = true })
		M.adv(W, 0.3)
		check("ms-fade: wait: nothing is written before Wait before fading has passed", M.writes(W, "MainActionBar") == 0 and M.alpha(W, "MainActionBar") == 0.8, M.alpha(W, "MainActionBar"))
		M.adv(W, 0.3)
		local mid = M.alpha(W, "MainActionBar")
		check("ms-fade: fade: it then eases down, so a moment later it is between the two", mid < 0.8 and mid > 0.25, mid)
		M.adv(W, 0.8)
		local writes = M.writes(W, "MainActionBar")
		check("ms-fade: fade: it ends at Faded opacity, 25%", M.alpha(W, "MainActionBar") == 0.25 and writes >= 2 and writes <= 6, M.alpha(W, "MainActionBar") .. " " .. writes)
		M.adv(W, 2)
		check("ms-fade: fade: once there it is not written again", M.writes(W, "MainActionBar") == writes, M.writes(W, "MainActionBar") .. " " .. writes)
		check("ms-fade: only the ticked row is touched", M.writes(W, "MultiBarBottomLeft") == 0 and M.alpha(W, "MultiBarBottomLeft") == 1 and M.writes(W, "StanceBar") == 0, M.row(W, "bar2"))
		check("ms-fade: status: one frame held and faded", W.line("Fading") == "Fading: on" and W.status():find("Fading: 1 frame, 1 faded", 1, true) ~= nil, W.status())
		check("ms-fade: no violation or error", K.allClean(W), K.problems(W))
	end
	do
		-- The mouse over the frame gives full opacity; away again, the wait and then the fade.
		local W = M.world({ ["fade.main"] = true })
		M.adv(W, 1.5)
		M.over(W, "MainActionBar")
		M.adv(W, 0.5)
		check("ms-fade: mouse: over the frame it is back at full opacity, not at the 0.8 it had", M.alpha(W, "MainActionBar") == 1, M.alpha(W, "MainActionBar"))
		W.cursor = { M.away[1], M.away[2] }
		M.adv(W, 0.3)
		check("ms-fade: mouse: away again it stays at full while the wait runs", M.alpha(W, "MainActionBar") == 1, M.alpha(W, "MainActionBar"))
		M.adv(W, 1.2)
		check("ms-fade: mouse: and then fades", M.alpha(W, "MainActionBar") == 0.25, M.alpha(W, "MainActionBar"))
		local V = M.world({ ["fade.main"] = true, ["fade.delay"] = 0, ["fade.time"] = 100 })
		M.adv(V, 0.5)
		check("ms-fade: times: with no wait and the shortest time it is faded in half a second", M.alpha(V, "MainActionBar") == 0.25, M.alpha(V, "MainActionBar"))
		local S = M.world({ ["fade.main"] = true, ["fade.delay"] = 3000, ["fade.time"] = 2000 })
		M.adv(S, 2.5)
		check("ms-fade: times: with the longest wait nothing has been written after 2.5 seconds", M.writes(S, "MainActionBar") == 0, M.writes(S, "MainActionBar"))
		M.adv(S, 1.5)
		local slow = M.alpha(S, "MainActionBar")
		check("ms-fade: times: with the longest time it is still easing at 4 seconds", slow < 0.8 and slow > 0.25, slow)
		M.adv(S, 3)
		check("ms-fade: times: it has ended by 7 seconds", M.alpha(S, "MainActionBar") == 0.25, M.alpha(S, "MainActionBar"))
		local Z = M.world({ ["fade.main"] = true, ["fade.alpha"] = 0 })
		M.adv(Z, 1.5)
		check("ms-fade: opacity: 0% fades the frame out, and it is not taken for a frame something else holds hidden", M.alpha(Z, "MainActionBar") == 0 and K.allClean(Z), M.alpha(Z, "MainActionBar"))
		M.over(Z, "MainActionBar")
		M.adv(Z, 1)
		check("ms-fade: opacity: and the mouse brings it back to 1", M.alpha(Z, "MainActionBar") == 1, M.alpha(Z, "MainActionBar"))
	end
	do
		-- Combat.
		local W = M.world({ ["fade.main"] = true })
		M.adv(W, 1.5)
		W.combat = true
		W.fire("PLAYER_REGEN_DISABLED")
		check("ms-fade: combat: the start of a fight sets full opacity at once, before any frame has run", M.alpha(W, "MainActionBar") == 1 and K.allClean(W), M.alpha(W, "MainActionBar") .. K.problems(W))
		M.adv(W, 2)
		check("ms-fade: combat: and it stays there in the fight", M.alpha(W, "MainActionBar") == 1, M.alpha(W, "MainActionBar"))
		W.combat = false
		M.adv(W, 0.3)
		check("ms-fade: combat: the fight over, the wait runs first", M.alpha(W, "MainActionBar") == 1, M.alpha(W, "MainActionBar"))
		M.adv(W, 1.5)
		check("ms-fade: combat: and then it fades", M.alpha(W, "MainActionBar") == 0.25, M.alpha(W, "MainActionBar"))
		local E = M.world({ ["fade.main"] = true })
		M.adv(E, 1.5)
		E.engaged = true
		M.adv(E, 0.5)
		check("ms-fade: combat: a player the game says is in combat without a lockdown counts too", M.alpha(E, "MainActionBar") == 1, M.alpha(E, "MainActionBar"))
		local N = M.world({ ["fade.main"] = true, ["fade.combat"] = false })
		M.adv(N, 1.5)
		N.combat = true
		N.fire("PLAYER_REGEN_DISABLED")
		M.adv(N, 2)
		check("ms-fade: combat: with In combat off the frame stays faded in a fight", M.alpha(N, "MainActionBar") == 0.25 and M.writes(N, "MainActionBar") >= 2, M.alpha(N, "MainActionBar"))
		local L = M.world({ ["fade.main"] = true }, function(X)
			X.combat = true
		end)
		M.adv(L, 2)
		check("ms-fade: combat: logged in during a fight the frame goes to full opacity", M.alpha(L, "MainActionBar") == 1, M.alpha(L, "MainActionBar"))
	end
	do
		-- A target, something on the cursor, the spell flyout and Edit Mode.
		local W = M.world({ ["fade.main"] = true, ["fade.target"] = true })
		M.adv(W, 1.5)
		W.target = true
		M.adv(W, 0.5)
		check("ms-fade: target: with a target and With a target ticked the frame is at full opacity", M.alpha(W, "MainActionBar") == 1, M.alpha(W, "MainActionBar"))
		W.target = false
		M.adv(W, 2)
		check("ms-fade: target: and it fades when the target goes", M.alpha(W, "MainActionBar") == 0.25, M.alpha(W, "MainActionBar"))
		local N = M.world({ ["fade.main"] = true })
		N.target = true
		M.adv(N, 1.5)
		check("ms-fade: target: with With a target off, a target does not keep it shown", M.alpha(N, "MainActionBar") == 0.25, M.alpha(N, "MainActionBar"))
		local H = M.world({ ["fade.main"] = true })
		M.adv(H, 1.5)
		H.held = "spell"
		M.adv(H, 0.5)
		check("ms-fade: cursor: something on the cursor gives full opacity", M.alpha(H, "MainActionBar") == 1, M.alpha(H, "MainActionBar"))
		H.held = nil
		M.adv(H, 2)
		check("ms-fade: cursor: and the frame fades when it is put down", M.alpha(H, "MainActionBar") == 0.25, M.alpha(H, "MainActionBar"))
		local F = M.world({ ["fade.main"] = true })
		local flyout = F.env.CreateFrame("Frame")
		flyout:Hide()
		F.env.SpellFlyout = flyout
		M.adv(F, 1.5)
		flyout:Show()
		M.adv(F, 0.5)
		check("ms-fade: flyout: an open spell flyout gives full opacity", M.alpha(F, "MainActionBar") == 1, M.alpha(F, "MainActionBar"))
		flyout:Hide()
		M.adv(F, 2)
		check("ms-fade: flyout: and the frame fades when it closes", M.alpha(F, "MainActionBar") == 0.25, M.alpha(F, "MainActionBar"))
		F.rawOf[flyout].fault.shown = "secret"
		M.adv(F, 0.5)
		check("ms-fade: flyout: a withheld answer counts as open, and raises nothing", M.alpha(F, "MainActionBar") == 1 and K.allClean(F), M.alpha(F, "MainActionBar") .. K.problems(F))
		local E = M.world({ ["fade.main"] = true })
		M.adv(E, 1.5)
		E.editMode(true)
		M.adv(E, 0.5)
		check("ms-fade: edit mode: Edit Mode gives full opacity", M.alpha(E, "MainActionBar") == 1, M.alpha(E, "MainActionBar"))
		E.editMode(false)
		M.adv(E, 2)
		check("ms-fade: edit mode: and the frame fades when it closes", M.alpha(E, "MainActionBar") == 0.25 and K.allClean(E), M.alpha(E, "MainActionBar") .. K.problems(E))
		local S = M.world({ ["fade.main"] = true, ["fade.target"] = true }, function(X)
			X.env.GetCursorInfo = function()
				return SECRET
			end
		end)
		M.adv(S, 1.5)
		check("ms-fade: a withheld answer about the cursor counts as something held, and raises nothing", M.alpha(S, "MainActionBar") == 1 and K.allClean(S), M.alpha(S, "MainActionBar") .. K.problems(S))
		local T = M.world({ ["fade.main"] = true, ["fade.target"] = true }, function(X)
			X.env.UnitExists = function()
				return SECRET
			end
		end)
		M.adv(T, 1.5)
		check("ms-fade: a withheld answer about the target counts as a target, and raises nothing", M.alpha(T, "MainActionBar") == 1 and K.allClean(T), M.alpha(T, "MainActionBar") .. K.problems(T))
		local R = M.world({ ["fade.main"] = true }, function(X)
			X.env.GetCursorInfo = function()
				error("GetCursorInfo failed", 0)
			end
		end)
		M.adv(R, 1.5)
		check("ms-fade: a cursor call that fails does not keep the frame shown, and raises nothing", M.alpha(R, "MainActionBar") == 0.25 and K.allClean(R), M.alpha(R, "MainActionBar") .. K.problems(R))
	end
	do
		-- The player frame, the minimap buttons and the rows of one frame each.
		local W = M.world({ ["fade.playerFrame"] = true, ["fade.minimapButtons"] = true, ["fade.petFrame"] = true, ["fade.bags"] = true })
		M.adv(W, 1.5)
		check("ms-fade: rows: the two player frames, the pet frame, the bag bar and the five minimap frames are faded", M.rowAt(W, "playerFrame", 0.25) and M.rowAt(W, "minimapButtons", 0.25)
			and M.rowAt(W, "petFrame", 0.25) and M.rowAt(W, "bags", 0.25), M.row(W, "playerFrame") .. " | " .. M.row(W, "minimapButtons"))
		check("ms-fade: rows: the two player frames are children of PlayerFrame with no global name, and the row reaches them", W.env.PlayerFrameContainer == nil and W.env.PlayerFrameContent == nil
			and W.env.PlayerFrame.PlayerFrameContainer ~= nil and W.env.PlayerFrame.PlayerFrameContent ~= nil, tostring(W.env.PlayerFrameContainer))
		check("ms-fade: rows: the player frame itself and the main bar are not written", M.writes(W, "PlayerFrame") == 0 and M.writes(W, "MainActionBar") == 0, M.writes(W, "PlayerFrame"))
		M.over(W, "PlayerFrame")
		M.adv(W, 0.5)
		check("ms-fade: rows: the mouse over the player frame gives both of its parts full opacity, though it is not over them", M.rowAt(W, "playerFrame", 1) and M.rowAt(W, "minimapButtons", 0.25), M.row(W, "playerFrame"))
		M.over(W, "MinimapCluster")
		M.adv(W, 0.5)
		check("ms-fade: rows: the mouse over the minimap gives the five minimap frames full opacity", M.rowAt(W, "minimapButtons", 1), M.row(W, "minimapButtons"))
		M.adv(W, 1.5)
		check("ms-fade: rows: the player frame fades again after the wait and the minimap frames stay", M.rowAt(W, "playerFrame", 0.25) and M.rowAt(W, "minimapButtons", 1), M.row(W, "playerFrame"))
		local A = M.world({ ["fade.bar2"] = true, ["fade.bar3"] = true, ["fade.bar4"] = true, ["fade.bar5"] = true, ["fade.bar6"] = true, ["fade.bar7"] = true, ["fade.bar8"] = true,
			["fade.stance"] = true, ["fade.pet"] = true, ["fade.micro"] = true })
		M.adv(A, 1.5)
		local all = true
		for _, row in ipairs({ "bar2", "bar3", "bar4", "bar5", "bar6", "bar7", "bar8", "stance", "pet", "micro" }) do
			all = all and M.rowAt(A, row, 0.25)
		end
		check("ms-fade: rows: bars 2 to 8, the stance bar, the pet bar and the micro menu each have their own switch", all and M.alpha(A, "MainActionBar") == 0.8 and M.writes(A, "MainActionBar") == 0, M.row(A, "bar2"))
	end
	do
		-- A row off, the module off: the alpha the frame had comes back.
		local W = M.world({ ["fade.main"] = true, ["fade.bar2"] = true })
		M.adv(W, 1.5)
		W.change("fade.main", false)
		W.flush()
		check("ms-fade: restore: a row switched off puts its frame back at the alpha it had, 0.8, and leaves the other row", M.alpha(W, "MainActionBar") == 0.8 and M.alpha(W, "MultiBarBottomLeft") == 0.25, M.alpha(W, "MainActionBar"))
		M.adv(W, 1)
		check("ms-fade: restore: and it stays there", M.alpha(W, "MainActionBar") == 0.8, M.alpha(W, "MainActionBar"))
		W.change("fade.main", true)
		W.change("fade.enabled", false)
		W.flush()
		check("ms-fade: restore: the page switched off puts every frame back", M.alpha(W, "MainActionBar") == 0.8 and M.alpha(W, "MultiBarBottomLeft") == 1 and W.line("Fading") == "Fading: off", M.alpha(W, "MultiBarBottomLeft"))
		M.adv(W, 1)
		check("ms-fade: restore: and nothing runs for it", M.alpha(W, "MainActionBar") == 0.8 and M.updaters(W) == M.updaters(M.world({ ["fade.enabled"] = false })), M.updaters(W))
		W.change("fade.enabled", true)
		W.flush()
		M.adv(W, 1.5)
		check("ms-fade: restore: switched on again it fades again", M.alpha(W, "MainActionBar") == 0.25 and M.alpha(W, "MultiBarBottomLeft") == 0.25 and K.allClean(W), K.problems(W))
		W.change("fade.alpha", 50)
		W.flush()
		M.adv(W, 1)
		check("ms-fade: restore: a new Faded opacity is followed", M.alpha(W, "MainActionBar") == 0.5, M.alpha(W, "MainActionBar"))
	end
	do
		-- A frame something else holds at 0 is left alone, and one that something else hides later is let go.
		local W = M.world({ ["fade.main"] = true }, function(X)
			M.raw(X, "MainActionBar").alpha = 0
		end)
		M.adv(W, 2)
		check("ms-fade: hidden by another: a frame at alpha 0 from the start is never written", M.writes(W, "MainActionBar") == 0 and M.alpha(W, "MainActionBar") == 0, M.alpha(W, "MainActionBar"))
		M.raw(W, "MainActionBar").alpha = 0.6
		M.adv(W, 2)
		check("ms-fade: hidden by another: when it comes back it is taken up with the alpha it has", M.alpha(W, "MainActionBar") == 0.25, M.alpha(W, "MainActionBar"))
		local writes = M.writes(W, "MainActionBar")
		M.raw(W, "MainActionBar").alpha = 0
		M.adv(W, 2)
		check("ms-fade: hidden by another: and let go when something else sets it to 0, with no write of ours", M.alpha(W, "MainActionBar") == 0 and M.writes(W, "MainActionBar") == writes and K.allClean(W), M.alpha(W, "MainActionBar"))
		M.raw(W, "MainActionBar").alpha = 0.9
		M.adv(W, 0.1)
		M.raw(W, "MainActionBar").alpha = 0.5
		W.change("fade.main", false)
		W.flush()
		check("ms-fade: hidden by another: a frame whose alpha another has set is not put back over it", M.alpha(W, "MainActionBar") == 0.5, M.alpha(W, "MainActionBar"))
	end
	do
		-- The action bar block's own fade has the bars it holds.
		local function block(options, prep)
			local all = { ["barblock.enabled"] = true, ["fade.main"] = true }
			for key, value in pairs(options or {}) do
				all[key] = value
			end
			return M.world(all, prep)
		end
		local W = block({ ["barblock.fade"] = true })
		M.adv(W, 2)
		check("ms-fade: block: a bar of a block with Fade the block on is faded by the block, to its 30%, and Fade writes nothing on it", M.alpha(W, "MainActionBar") == 0.3 and W.ns.BarBlockFades("MainActionBar") == true and K.allClean(W),
			M.alpha(W, "MainActionBar") .. K.problems(W))
		local O = block({})
		M.adv(O, 2)
		check("ms-fade: block: with Fade the block off the bar fades with Fade", O.ns.BarBlockFades("MainActionBar") == false and M.alpha(O, "MainActionBar") == 0.25, M.alpha(O, "MainActionBar"))
		O.change("barblock.fade", true)
		O.flush()
		M.adv(O, 2)
		check("ms-fade: block: Fade the block switched on takes the bar over", M.alpha(O, "MainActionBar") == 0.3, M.alpha(O, "MainActionBar"))
		O.change("fade.main", false)
		O.change("barblock.fade", false)
		O.flush()
		M.adv(O, 1)
		check("ms-fade: block: and when both are off the bar has the alpha it had at the start, 0.8", M.alpha(O, "MainActionBar") == 0.8 and K.allClean(O), M.alpha(O, "MainActionBar") .. K.problems(O))
		local X = M.world({ ["fade.main"] = true })
		check("ms-fade: block: with no block the question is answered no", X.ns.BarBlockFades("MainActionBar") == false and X.ns.BarBlockFades("StanceBar") == false)
	end
	do
		-- A frame the game does not have, one that cannot be read, a refused call.
		local W = M.world({ ["fade.bags"] = true, ["fade.main"] = true }, nil, { BagsBar = true })
		M.adv(W, 1.5)
		check("ms-fade: missing: a row with no frame is named in the status and the other rows go on", W.status():find("Fading: no frame found for Bag bar", 1, true) ~= nil and M.alpha(W, "MainActionBar") == 0.25 and K.allClean(W), W.status())
		local R = M.world({ ["fade.main"] = true, ["fade.bar2"] = true, ["fade.bar6"] = true, ["fade.bar7"] = true, ["fade.bar8"] = true }, function(X)
			for _, name in ipairs({ "MultiBar5", "MultiBar6", "MultiBar7" }) do
				M.raw(X, name).SetAlpha = function()
					error("refused", 0)
				end
			end
		end)
		M.adv(R, 1.5)
		check("ms-fade: refused: three frames the game will not write stop the part, with a line in the status and a word in the chat, and no error", R.status():find("Fading: fade stopped. refused", 1, true) ~= nil
			and R.out[#R.out]:find("fade stopped in Fading", 1, true) ~= nil and K.allClean(R), R.status() .. " | " .. tostring(R.out[#R.out]))
		check("ms-fade: refused: the frames it could write are put back when the part stops", M.alpha(R, "MultiBarBottomLeft") == 1 and M.alpha(R, "MainActionBar") == 0.8 and M.writes(R, "MainActionBar") >= 2,
			M.alpha(R, "MultiBarBottomLeft") .. " " .. M.alpha(R, "MainActionBar"))
		local before = M.writes(R, "MultiBarBottomLeft")
		M.adv(R, 1)
		check("ms-fade: refused: and nothing more is written", M.writes(R, "MultiBarBottomLeft") == before, M.writes(R, "MultiBarBottomLeft") .. " " .. before)
		local G = M.world({ ["fade.main"] = true }, function(X)
			M.raw(X, "MainActionBar").GetAlpha = function()
				return SECRET
			end
		end)
		M.adv(G, 1.5)
		check("ms-fade: a withheld alpha is taken as 1, and the frame is faded from it", M.alpha(G, "MainActionBar") == 0.25 and K.allClean(G), M.alpha(G, "MainActionBar"))
		local Q = M.world({ ["fade.main"] = true }, function(X)
			M.raw(X, "MainActionBar").fault.mouseOver = "secret"
		end)
		M.adv(Q, 1.5)
		check("ms-fade: a withheld mouse answer counts as under the mouse, and raises nothing", M.alpha(Q, "MainActionBar") == 1 and K.allClean(Q), M.alpha(Q, "MainActionBar") .. K.problems(Q))
		local U = M.world({ ["fade.main"] = true })
		U.run(1.5, 0.01)
		check("ms-fade: the check runs every twentieth of a second, not every frame", M.alpha(U, "MainActionBar") == 0.25 and M.writes(U, "MainActionBar") <= 6, M.alpha(U, "MainActionBar") .. " " .. M.writes(U, "MainActionBar"))
		local P = M.world({ ["fade.main"] = true }, function(X)
			M.raw(X, "MainActionBar").IsMouseOver = function()
				error("IsMouseOver failed", 0)
			end
		end)
		M.adv(P, 1.5)
		check("ms-fade: a mouse test that fails does not keep the frame shown, and raises nothing", M.alpha(P, "MainActionBar") == 0.25 and K.allClean(P), M.alpha(P, "MainActionBar") .. K.problems(P))
	end
	do
		-- The page, the file and the status line.
		local W = M.world({})
		check("ms-fade: page: Fading has the defaults of the plan", W.ns.Get("fade.enabled") == true and W.ns.Get("fade.main") == false and W.ns.Get("fade.alpha") == 25 and W.ns.Get("fade.delay") == 500
			and W.ns.Get("fade.time") == 300 and W.ns.Get("fade.combat") == true and W.ns.Get("fade.target") == false and W.ns.Get("fade.minimapButtons") == false and W.ns.Get("fade.playerFrame") == false)
		check("ms-fade: page: Faded opacity runs 0 to 90, Wait before fading 0 to 3000, Fade time 100 to 2000", (function()
			local found = {}
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "fade" then
					for _, row in ipairs(page) do
						found[row.key or row.section] = row
					end
				end
			end
			return found.alpha.min == 0 and found.alpha.max == 90 and found.alpha.step == 5 and found.delay.min == 0 and found.delay.max == 3000 and found.delay.step == 100
				and found.time.min == 100 and found.time.max == 2000 and found.time.step == 100 and found["What fades"] and found.Fade and found["Stay visible"]
		end)())
		check("ms-fade: file: Fade.lua loads under Lua 5.1 rules", loadfile(ADDON_DIR .. "/Fade.lua") ~= nil)
		check("ms-fade: status: on with no row ticked says on and holds no frame", W.line("Fading") == "Fading: on" and W.status():find("Fading: 0 frames, 0 faded", 1, true) ~= nil, W.status())
	end
end
-- >>> ms-fade (end)
-- >>> mp-proc-triggers (begin)
-- Proc triggers without a readable buff (proctrig:). The helpers sit in the table X.
do
	local X = { TRANCE_ICON = 136183, ICON = 136197 }
	-- A proc tracker as the addon saves it, on a trigger, with the fields of more over it.
	function X.make(base, more)
		local e = { id = "ptr001", kind = "proc", name = "Shadow Trance", names = { "Shadow Trance" }, spells = { 17941 }, lights = { 686, 25307 }, trigger = "aura",
			time = 10, size = 48, show = "always" }
		for k, v in pairs(base) do
			e[k] = v
		end
		for k, v in pairs(more or {}) do
			e[k] = v
		end
		return e
	end
	function X.entry(trigger, more)
		return X.make({ trigger = trigger }, more)
	end
	function X.fel(more)
		return X.make({ id = "ptr003", trigger = "cast", name = "Fel Domination", names = { "Fel Domination" }, spells = { 18708 }, lights = { 688, 697 }, time = 15 }, more)
	end
	function X.mongoose(more)
		return X.make({ id = "ptr002", trigger = "usable", name = "Mongoose Bite", names = { "Mongoose Bite" }, spells = { 1310726 }, lights = { 1495, 14269 }, time = 5 }, more)
	end
	function X.decimation(more)
		return X.make({ id = "ptr004", trigger = "casttime", name = "Decimation", names = { "Decimation" }, spells = { 440873 }, lights = { 6353, 17924 }, kind2 = "shorter" }, more)
	end
	-- A world of a warlock (or o.class) with trackers: o.list the saved list, o.set(W) what the game has before the login.
	function X.world(o)
		o = o or {}
		local W = newWorld({ trackers = true, char = { trackers = o.list or {} } })
		W.ns.TrackerSlots = nil
		W.addLine({ name = "General" })
		W.addSpell(686, { name = "Shadow Bolt", icon = X.ICON, base = 0, lowRank = true })
		W.addSpell(25307, { name = "Shadow Bolt", icon = X.ICON, base = 0 })
		W.addSpell(6353, { name = "Soul Fire", icon = 135808, base = 0 })
		W.addSpell(17924, { name = "Soul Fire", icon = 135808, base = 0, known = false })
		W.addSpell(17941, { name = "Shadow Trance", icon = X.TRANCE_ICON, base = 0, known = false })
		W.addSpell(440873, { name = "Decimation", icon = 135994, base = 0, known = false })
		W.addSpell(18708, { name = "Fel Domination", icon = 136082, base = 0, known = false })
		W.addSpell(688, { name = "Summon Imp", icon = 136218, base = 0 })
		W.addSpell(697, { name = "Summon Voidwalker", icon = 136221, base = 0 })
		W.addSpell(99001, { name = "Summon Imp", icon = 136218, base = 0, known = false })
		W.addSpell(702, { name = "Curse of Weakness", icon = 136138, base = 0 })
		W.addSpell(1495, { name = "Mongoose Bite", icon = 132277, base = 0 })
		W.addSpell(19306, { name = "Counterattack", icon = 132336, base = 0 })
		W.addSpell(1310726, { name = "Expose Prey", icon = 132277, base = 0, known = false })
		W.sp.castTimes[686], W.sp.castTimes[25307], W.sp.castTimes[6353] = 2500, 2500, 3000
		W.au.unit.player = { class = o.class or "WARLOCK", guid = "Player-1" }
		if o.set then
			o.set(W)
		end
		return W
	end
	function X.step(W, seconds)
		W.advance(seconds)
		W.advance(0)
	end
	function X.run(W, seconds)
		for _ = 1, math.floor(seconds * 4 + 0.5) do
			X.step(W, 0.25)
		end
	end
	-- Logged in and past the quiet seconds, then a fight in which the buffs are hidden when fight is true.
	function X.up(o, fight)
		local W = X.world(o)
		W.login()
		W.flush()
		X.step(W, 5)
		if fight then
			W.beginFight()
			X.step(W, 0.3)
		end
		return W
	end
	function X.list(W)
		return W.env.FlatUICharDB.trackers
	end
	function X.alpha(W, index)
		return W.ns.TrackerFrame(X.list(W)[index or 1]).alpha
	end
	function X.ok(W)
		return #W.violations == 0 and #W.errors == 0 and not has(W.status(), "stopped")
	end
	function X.why(W)
		return table.concat(W.violations, " | "):sub(1, 200) .. " || " .. table.concat(W.errors, " | "):sub(1, 200) .. " || " .. W.line("Trackers")
	end
	-- The cast time of a spell changes (in milliseconds) and the game says so with a ping of UNIT_AURA.
	function X.cast_time(W, id, ms)
		W.sp.castTimes[id] = ms
		W.auraChanged()
		X.step(W, 0.3)
	end
	function X.usable(W, id, usable, power)
		W.sp.usable[id] = { usable, power }
		W.fire("SPELL_UPDATE_USABLE")
		X.step(W, 0.3)
	end
	-- How many frames hear an event.
	function X.hearing(W, event)
		local n = 0
		for _, frame in ipairs(W.eventFrames) do
			if frame.events[event] and frame.events.SPELLS_CHANGED then
				n = n + 1
			end
		end
		return n
	end
	-- The number of a proc in the class data of the warlock.
	function X.row(W, name)
		for number, row in ipairs(W.ns.ProcData.WARLOCK) do
			if row.name == name then
				return number
			end
		end
	end
	function X.names(W)
		local labels = {}
		for _, row in ipairs(W.ns.ProcCandidates()) do
			labels[#labels + 1] = row[2]
		end
		return table.concat(labels, ",")
	end

	-- 1. The cast time that becomes instant.
	do
		local W = X.up({ list = { X.entry("casttime") } }, true)
		check("proctrig: casttime: the cast time is at rest: nothing is shown in the fight", X.alpha(W) == 0 and #W.au.played == 0 and X.ok(W), X.why(W))
		X.cast_time(W, 686, 0)
		check("proctrig: casttime: the spell it is for is instant: the alert is up with one sound", X.alpha(W) == 1 and #W.au.played == 1, X.alpha(W))
		X.cast_time(W, 686, 0)
		check("proctrig: casttime: another ping while it is instant plays nothing more", X.alpha(W) == 1 and #W.au.played == 1)
		X.cast_time(W, 686, 2500)
		check("proctrig: casttime: the cast time at rest again ends the alert", X.alpha(W) == 0 and #W.au.played == 1 and X.ok(W), X.alpha(W))
		X.cast_time(W, 686, 0)
		X.run(W, 10.5)
		check("proctrig: casttime: the time of the proc ends the alert while the cast time is still 0", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		X.run(W, 3)
		check("proctrig: casttime: and it does not start again until the cast time has been at rest", X.alpha(W) == 0 and #W.au.played == 2, #W.au.played)
		X.cast_time(W, 686, 2500)
		X.cast_time(W, 686, 0)
		check("proctrig: casttime: the next one starts again with a sound", X.alpha(W) == 1 and #W.au.played == 3, #W.au.played)
		W.sp.castTimes[686] = 2500
		W.cast(686)
		X.step(W, 0.3)
		check("proctrig: casttime: a cast of the spell ends it, and the cast time is looked at after the cast", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		local text = W.slash("tracker check")
		check("proctrig: casttime: the check names the trigger and the cast times", has(text, "Trigger: cast time.") and has(text, "Spell it is for: Shadow Bolt, now 2.5 s, at rest 2.5 s."), text)
		X.cast_time(W, 686, 0)
		check("proctrig: casttime: and the cast time now", has(W.slash("tracker check"), "Spell it is for: Shadow Bolt, now 0 s, at rest 2.5 s."), W.slash("tracker check"))
	end

	-- 2. A cast time that becomes clearly shorter.
	do
		local W = X.up({ list = { X.decimation() } }, true)
		X.cast_time(W, 6353, 1900)
		check("proctrig: casttime shorter: 1.9 s of 3 s is not clearly shorter", X.alpha(W) == 0 and #W.au.played == 0, X.alpha(W))
		X.cast_time(W, 6353, 1800)
		check("proctrig: casttime shorter: 60 percent of the cast time at rest starts the alert", X.alpha(W) == 1 and #W.au.played == 1, X.alpha(W))
		X.cast_time(W, 6353, 1900)
		check("proctrig: casttime shorter: back above 60 percent ends it", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		X.cast_time(W, 6353, 0)
		check("proctrig: casttime shorter: an instant cast is shorter too", X.alpha(W) == 1 and #W.au.played == 2, X.alpha(W))
		local I = X.up({ list = { X.decimation({ kind2 = false }) } }, true)
		X.cast_time(I, 6353, 1800)
		check("proctrig: casttime instant: a shorter cast time that is not 0 starts nothing", X.alpha(I) == 0 and X.list(I)[1].kind2 == nil and X.ok(I), X.alpha(I))
		X.cast_time(I, 6353, 0)
		check("proctrig: casttime instant: and 0 starts it", X.alpha(I) == 1)
	end

	-- 3. The cast time at rest: out of combat, with the buff off.
	do
		local W = X.world({ list = { X.entry("casttime") }, set = function(Q)
			Q.sp.castTimes[686] = 0
			Q.giveBuff(17941, { remaining = 600, icon = X.TRANCE_ICON })
		end })
		W.login()
		W.flush()
		X.step(W, 5)
		W.beginFight()
		X.step(W, 0.3)
		X.cast_time(W, 686, 0)
		check("proctrig: rest: a cast time of 0 seen with the buff on is not the one at rest, so there is nothing to compare", X.alpha(W) == 0 and has(W.slash("tracker check"), "at rest not known"), W.slash("tracker check"))
		W.endFight()
		W.takeBuff(17941)
		W.auraChanged()
		W.sp.castTimes[686] = 2500
		W.fire("SPELLS_CHANGED")
		X.step(W, 0.5)
		check("proctrig: rest: out of combat with the buff off the cast time at rest is kept when the spells change", has(W.slash("tracker check"), "at rest 2.5 s"), W.slash("tracker check"))
		W.beginFight()
		X.step(W, 0.3)
		X.cast_time(W, 686, 0)
		check("proctrig: rest: and then an instant cast is the alert", X.alpha(W) == 1 and X.ok(W), X.alpha(W))
		W.sp.castTimes[686] = 1000
		W.endFight()
		X.step(W, 0.5)
		check("proctrig: rest: the end of a fight looks at it again, here 1 s", has(W.slash("tracker check"), "at rest 1 s"), W.slash("tracker check"))
		-- A shorter cast time with the buff on is not the one at rest either.
		local D = X.world({ list = { X.decimation() }, set = function(Q)
			Q.sp.castTimes[6353] = 1800
			Q.giveBuff(440873, { remaining = 600, icon = 135994 })
		end })
		D.login()
		D.flush()
		X.step(D, 5)
		check("proctrig: rest: 1.8 s with the buff on is not the cast time at rest", has(D.slash("tracker check"), "at rest not known"), D.slash("tracker check"))
		-- A spell that is instant with no buff on is instant at rest: nothing to compare.
		local Z0 = X.up({ list = { X.entry("casttime") }, set = function(Q) Q.sp.castTimes[686] = 0 end }, true)
		X.cast_time(Z0, 686, 0)
		check("proctrig: rest: a spell that is instant at rest is never an alert", X.alpha(Z0) == 0 and has(Z0.slash("tracker check"), "at rest not known") and X.ok(Z0), Z0.slash("tracker check"))
		-- The game changes the cast time a moment after its ping: the second look sees it.
		local L = X.up({ list = { X.entry("casttime") } }, true)
		L.auraChanged()
		X.step(L, 0.1)
		L.sp.castTimes[686] = 0
		X.step(L, 0.3)
		check("proctrig: rest: a cast time that changes 0.1 s after the ping is seen by the second look", X.alpha(L) == 1 and X.ok(L), X.alpha(L))
	end

	-- 4. An ability that becomes usable.
	do
		local W = X.up({ class = "HUNTER", list = { X.mongoose() }, set = function(Q) Q.sp.usable[1495] = { false, false } end }, true)
		W.fire("SPELL_UPDATE_USABLE")
		X.step(W, 0.3)
		check("proctrig: usable: not usable: nothing is shown", X.alpha(W) == 0 and #W.au.played == 0 and X.ok(W), X.alpha(W))
		X.usable(W, 1495, true, false)
		check("proctrig: usable: it becomes usable: the alert is up with one sound", X.alpha(W) == 1 and #W.au.played == 1, X.alpha(W))
		X.usable(W, 1495, true, false)
		check("proctrig: usable: another event while it is usable plays nothing more", X.alpha(W) == 1 and #W.au.played == 1)
		X.usable(W, 1495, false, false)
		check("proctrig: usable: not usable again ends it", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		X.usable(W, 1495, false, true)
		X.usable(W, 1495, true, false)
		check("proctrig: usable: power that comes back alone starts nothing", X.alpha(W) == 0 and #W.au.played == 1, X.alpha(W))
		X.usable(W, 1495, false, false)
		X.usable(W, 1495, true, false)
		check("proctrig: usable: the next time it becomes usable it starts again", X.alpha(W) == 1 and #W.au.played == 2, #W.au.played)
		X.usable(W, 1495, false, true)
		check("proctrig: usable: power gone while it is up does not end it", X.alpha(W) == 1)
		X.run(W, 5.5)
		check("proctrig: usable: the time of 5 seconds ends it", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		check("proctrig: usable: the check names the trigger and says whether the spell is usable", has(W.slash("tracker check"), "Trigger: usable.") and has(W.slash("tracker check"), "Spell it is for: Mongoose Bite, usable now: no, not enough power."), W.slash("tracker check"))
		local N = X.up({ class = "HUNTER", list = { X.mongoose() }, set = function(Q) Q.sp.usable[1495] = { true, false } end }, true)
		N.fire("SPELL_UPDATE_USABLE")
		X.step(N, 0.3)
		check("proctrig: usable: a spell that is usable at the first look is not an alert, since when is not known", X.alpha(N) == 0 and #N.au.played == 0, X.alpha(N))
	end

	-- 5. Your own cast.
	do
		local W = X.up({ list = { X.fel() } }, true)
		W.cast(5000)
		X.step(W, 0.3)
		check("proctrig: cast: a cast of another spell starts nothing", X.alpha(W) == 0 and #W.au.played == 0)
		local T0 = X.up({ list = { X.fel({ time = false }) } }, true)
		T0.cast(18708)
		X.step(T0, 0.3)
		check("proctrig: cast: an entry with no time is never started by a cast", X.alpha(T0) == 0 and X.ok(T0), X.alpha(T0))
		W.cast(18708)
		X.step(W, 0.3)
		check("proctrig: cast: a cast of the proc's spell starts the alert, with one sound", X.alpha(W) == 1 and #W.au.played == 1 and X.ok(W), X.alpha(W))
		local text = W.slash("tracker check")
		check("proctrig: cast: the check names the trigger, the time and the casts it noticed", has(text, "Trigger: your cast.") and has(text, "Time: 15 seconds.") and has(text, "Your casts noticed: 2, 1 for this proc."), text)
		W.cast(688)
		X.step(W, 0.3)
		check("proctrig: cast: a cast of a spell it is for ends it", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		W.cast(18708)
		X.step(W, 0.3)
		W.cast(99001)
		X.step(W, 0.3)
		check("proctrig: cast: so does a cast of a spell with the name of one of them, by another ID", X.alpha(W) == 0 and #W.au.played == 2, X.alpha(W))
		W.cast(18708)
		X.step(W, 0.3)
		X.run(W, 14)
		check("proctrig: cast: before its time is up it is still there", X.alpha(W) == 1)
		X.run(W, 1.5)
		check("proctrig: cast: its time of 15 seconds ends it", X.alpha(W) == 0 and X.ok(W), X.alpha(W))
		W.cast(SECRET)
		W.cast(18708.5)
		X.step(W, 0.3)
		check("proctrig: cast: a spell ID that is withheld or not whole starts nothing", X.alpha(W) == 0 and #W.au.played == 3 and X.ok(W), X.alpha(W))
		W.unitEvent("UNIT_SPELLCAST_SUCCEEDED", "target", "target", "guid", 18708)
		X.step(W, 0.3)
		check("proctrig: cast: a cast of another unit is not sent to a frame that asked for the player's", X.alpha(W) == 0 and X.ok(W))
		local F = X.up({ list = { X.fel() }, set = function(Q) Q.au.fault.RegisterUnitEvent = "false" end }, true)
		F.fire("UNIT_SPELLCAST_SUCCEEDED", "target", "guid", 18708)
		X.step(F, 0.3)
		check("proctrig: cast: where the frame hears every unit a cast of another unit starts nothing", X.alpha(F) == 0 and X.ok(F), X.alpha(F))
		F.fire("UNIT_SPELLCAST_SUCCEEDED", SECRET, "guid", 18708)
		X.step(F, 0.3)
		check("proctrig: cast: and a unit that is withheld cannot be told, so it starts nothing", X.alpha(F) == 0 and X.ok(F), X.alpha(F))
		F.fire("UNIT_SPELLCAST_SUCCEEDED", "player", "guid", 18708)
		X.step(F, 0.3)
		check("proctrig: cast: and the player's own cast does", X.alpha(F) == 1 and X.ok(F), X.alpha(F))
		local B = X.up({ list = { X.fel() } })
		B.cast(18708)
		X.step(B, 0.3)
		check("proctrig: cast: out of a fight the buff is read, and it is not there in this world, so no alert is shown", X.alpha(B) == 0 and X.ok(B), X.alpha(B))
		B.beginFight()
		X.step(B, 0.3)
		check("proctrig: cast: a fight begins and the cast heard before it is the alert", X.alpha(B) == 1 and X.ok(B), X.alpha(B))
	end

	-- 6. Values that are not plain.
	do
		local W = X.up({ list = { X.entry("casttime"), X.mongoose() } }, true)
		X.cast_time(W, 686, SECRET)
		X.usable(W, 1495, SECRET, false)
		check("proctrig: a cast time that is withheld and a usable that is withheld start nothing and raise nothing", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 0 and X.ok(W), X.why(W))
		X.cast_time(W, 686, "0")
		X.usable(W, 1495, "yes", false)
		check("proctrig: a cast time or a usable of the wrong type is ignored", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 0 and X.ok(W), X.why(W))
		W.sp.fault.GetSpellInfo = "error"
		W.au.fault.IsSpellUsable = "error"
		X.cast_time(W, 686, 0)
		X.usable(W, 1495, true, false)
		check("proctrig: a call of the game that fails is ignored", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 0 and X.ok(W), X.why(W))
		W.sp.fault.GetSpellInfo = nil
		W.au.fault.IsSpellUsable = nil
		X.cast_time(W, 686, 0)
		check("proctrig: and the next plain answer is used", X.alpha(W, 1) == 1 and X.ok(W), X.alpha(W, 1))
	end

	-- 7. Several entries, each on its own.
	do
		local W = X.up({ class = "HUNTER", list = { X.entry("casttime"), X.mongoose(), X.fel() }, set = function(Q) Q.sp.usable[1495] = { false, false } end }, true)
		W.fire("SPELL_UPDATE_USABLE")
		X.step(W, 0.3)
		W.cast(18708)
		X.step(W, 0.3)
		check("proctrig: several: the cast starts its entry alone", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 0 and X.alpha(W, 3) == 1 and #W.au.played == 1, X.alpha(W, 3))
		X.usable(W, 1495, true, false)
		check("proctrig: several: the usable spell starts its entry alone", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 1 and X.alpha(W, 3) == 1 and #W.au.played == 2)
		X.cast_time(W, 686, 0)
		check("proctrig: several: the cast time starts its entry alone, and all three are up", X.alpha(W, 1) == 1 and X.alpha(W, 2) == 1 and X.alpha(W, 3) == 1 and #W.au.played == 3 and X.ok(W), #W.au.played)
		X.cast_time(W, 686, 2500)
		check("proctrig: several: the cast time at rest ends its entry and leaves the others", X.alpha(W, 1) == 0 and X.alpha(W, 2) == 1 and X.alpha(W, 3) == 1)
		check("proctrig: several: one frame hears the events of all three", X.hearing(W, "SPELL_UPDATE_USABLE") == 1, X.hearing(W, "SPELL_UPDATE_USABLE"))
	end

	-- 8. No frame and no timer when no proc needs them.
	do
		local E = X.up({ list = {} })
		check("proctrig: no proc in the list: no frame hears the events of the triggers, and nothing is waiting", X.hearing(E, "SPELL_UPDATE_USABLE") == 0 and #E.timers == 0 and X.ok(E), X.hearing(E, "SPELL_UPDATE_USABLE") .. " " .. #E.timers)
		E.fire("SPELL_UPDATE_USABLE")
		E.auraChanged()
		E.cast(18708)
		local waits = 0
		for _, tm in ipairs(E.timers) do
			if tm.delay ~= 0 then
				waits = waits + 1
			end
		end
		check("proctrig: and the events start no timer", waits == 0, #E.timers)
		local A = X.up({ list = { X.entry("aura") } })
		check("proctrig: a proc on the aura trigger needs no frame", X.hearing(A, "SPELL_UPDATE_USABLE") == 0 and X.ok(A))
		local O = X.up({ list = { X.entry("overlay") } })
		check("proctrig: nor does the overlay trigger", X.hearing(O, "SPELL_UPDATE_USABLE") == 0 and X.ok(O))
		local W = X.up({ list = { X.entry("casttime") } })
		check("proctrig: a proc on a trigger of this file has one frame", X.hearing(W, "SPELL_UPDATE_USABLE") == 1 and X.ok(W), X.hearing(W, "SPELL_UPDATE_USABLE"))
		local found = 0
		for _, frame in ipairs(W.eventFrames) do
			if frame.events.SPELL_UPDATE_USABLE and frame.unitEvents and frame.unitEvents.UNIT_AURA and frame.unitEvents.UNIT_SPELLCAST_SUCCEEDED
				and frame.unitEvents.UNIT_AURA[1] == "player" and frame.unitEvents.UNIT_SPELLCAST_SUCCEEDED[1] == "player" then
				found = found + 1
			end
		end
		check("proctrig: and it hears the aura ping and the casts of the player alone", found == 1, found)
		for _ = 1, 3 do
			W.fire("SPELL_UPDATE_USABLE")
			W.auraChanged()
		end
		check("proctrig: events that come together ask for two looks, not for one each", #W.timers <= 4, #W.timers)
	end

	-- 9. Adding: the list, the data, the refusals.
	do
		local W = X.up({ list = {} })
		check("proctrig: add: the proc is listed with its trigger after its name", X.names(W) == "Amplify Curse, your cast,Decimation, cast time,Fel Domination, your cast,Shadow Trance, cast time", X.names(W))
		check("proctrig: add: Fel Domination is a cast trigger with the time of its buff", W.ns.ProcAdd(X.row(W, "Fel Domination")) == true and X.list(W)[1].trigger == "cast" and X.list(W)[1].time == 15 and X.list(W)[1].kind2 == nil, X.list(W)[1] and X.list(W)[1].trigger)
		check("proctrig: add: Decimation is a cast time trigger of kind shorter", W.ns.ProcAdd(X.row(W, "Decimation")) == true and X.list(W)[2].trigger == "casttime" and X.list(W)[2].kind2 == "shorter" and X.list(W)[2].time == 10)
		check("proctrig: add: the frame is made for them", X.hearing(W, "SPELL_UPDATE_USABLE") == 1 and X.ok(W), X.hearing(W, "SPELL_UPDATE_USABLE"))
		local I = X.up({ list = {}, set = function(Q) Q.sp.castTimes[6353] = 0 end })
		local ok, message = I.ns.ProcAdd(X.row(I, "Decimation"))
		check("proctrig: add: a spell that is instant at rest is refused with a note, and nothing is added", ok == false and message == "Soul Fire is instant already." and #X.list(I) == 0, tostring(message))
		local H = X.up({ class = "HUNTER", list = {} })
		check("proctrig: add: a hunter's reactive procs are listed as usable", X.names(H) == "Counterattack, usable,Mongoose Bite, usable", X.names(H))
		local S = X.up({ list = {} })
		S.beginFight()
		X.step(S, 0.3)
		check("proctrig: add: in a fight a proc is added, and no frame is made for it before the fight is over", S.ns.ProcAdd(X.row(S, "Fel Domination")) == true and X.hearing(S, "SPELL_UPDATE_USABLE") == 0 and X.ok(S), X.hearing(S, "SPELL_UPDATE_USABLE"))
		S.endFight()
		X.step(S, 0.5)
		check("proctrig: add: and when it is over the frame is made, and nothing protected was called", X.hearing(S, "SPELL_UPDATE_USABLE") == 1 and X.ok(S), X.why(S))
	end

	-- 10. The command: proc trigger.
	do
		local W = X.up({ list = { X.entry("aura"), X.entry("aura", { id = "ptr002", name = "Decimation", names = { "Decimation" }, spells = { 440873 }, lights = { 6353 }, time = false }) } })
		check("proctrig: command: cast time is accepted, and the frame is made for it", W.slash("tracker proc trigger 1 casttime") == "Proc 1: trigger is casttime." and X.list(W)[1].trigger == "casttime"
			and X.hearing(W, "SPELL_UPDATE_USABLE") == 1, W.slash("tracker proc trigger 1 casttime"))
		check("proctrig: command: cast with no time is refused with what to do", has(W.slash("tracker proc trigger 2 cast"), "needs a time above 0 seconds") and X.list(W)[2].trigger == "aura", W.slash("tracker proc trigger 2 cast"))
		W.slash("tracker proc time 2 8")
		check("proctrig: command: and with a time it is accepted", W.slash("tracker proc trigger 2 cast") == "Proc 2: trigger is cast." and X.list(W)[2].trigger == "cast")
		check("proctrig: command: usable is accepted for a proc with a spell it is for", W.slash("tracker proc trigger 2 usable") == "Proc 2: trigger is usable." and X.list(W)[2].trigger == "usable")
		X.list(W)[2].lights = {}
		check("proctrig: command: with no spell it is for neither a cast time nor a usable trigger is accepted", has(W.slash("tracker proc trigger 2 casttime"), "has no spell it is for") and has(W.slash("tracker proc trigger 2 usable"), "has no spell it is for"))
		check("proctrig: command: back to aura", W.slash("tracker proc trigger 1 aura") == "Proc 1: trigger is aura." and X.ok(W), X.why(W))
		local I = X.up({ list = { X.entry("aura") }, set = function(Q) Q.sp.castTimes[686] = 0 end })
		check("proctrig: command: a spell that is instant at rest is refused, and the trigger stays", I.slash("tracker proc trigger 1 casttime") == "Shadow Bolt is instant already." and X.list(I)[1].trigger == "aura", I.slash("tracker proc trigger 1 casttime"))
		local N = X.up({ list = { X.entry("aura") }, set = function(Q)
			Q.env.C_Spell.IsSpellUsable = nil
			Q.env.C_Spell.GetSpellInfo = nil
		end })
		check("proctrig: command: a client that gives no cast time or no usable says so in one line", N.slash("tracker proc trigger 1 casttime") == "This client does not give a spell's cast time."
			and N.slash("tracker proc trigger 1 usable") == "This client does not say when a spell is usable." and X.ok(N), N.slash("tracker proc trigger 1 usable"))
	end

	-- 11. Cleaning and the saved list.
	do
		local W = X.up({ list = { X.decimation(), X.entry("casttime", { id = "ptr005", kind2 = "other" }), X.entry("usable", { id = "ptr006", kind2 = 5 }) } })
		local list = X.list(W)
		check("proctrig: clean: the three triggers are kept, kind2 shorter is kept and any other kind2 is taken away", list[1].trigger == "casttime" and list[1].kind2 == "shorter" and list[2].trigger == "casttime" and list[2].kind2 == nil
			and list[3].trigger == "usable" and list[3].kind2 == nil, tostring(list[2].kind2))
		check("proctrig: clean: no violation", X.ok(W), X.why(W))
	end

	-- 12. The page switched off.
	do
		local W = X.up({ list = { X.entry("casttime") } }, true)
		X.cast_time(W, 686, 0)
		check("proctrig: page: the alert is up", X.alpha(W) == 1)
		W.change("trackers.enabled", false)
		X.step(W, 0.5)
		W.auraChanged()
		W.cast(686)
		X.step(W, 0.5)
		check("proctrig: page: switched off, the events do nothing and raise nothing", X.ok(W) and #W.ns.TrackerRow() == 0, X.why(W))
	end

	-- 13. The files.
	do
		check("proctrig: the file compiles, and the TOC loads it after Procs.lua, ProcArt.lua and ProcGlow.lua", loadfile(ADDON_DIR .. "/ProcTriggers.lua") ~= nil and (function()
			local order = {}
			for line in io.open(ADDON_DIR .. "/FlatUI.toc", "rb"):read("*a"):gmatch("[^\r\n]+") do
				if line:match("%.lua$") then
					order[#order + 1] = line
				end
			end
			for i, file in ipairs(order) do
				if file == "Procs.lua" then
					return order[i + 1] == "ProcArt.lua" and order[i + 2] == "ProcGlow.lua" and order[i + 3] == "ButtonEffects.lua" and order[i + 4] == "ProcTriggers.lua"
				end
			end
			return false
		end)())
		local text = io.open(ADDON_DIR .. "/ProcTriggers.lua", "rb"):read("*a")
		local banned = {}
		for _, word in ipairs({ "\226\128\148", "delve", "leverage", "robust", "seamless" }) do
			if text:find(word, 1, true) then
				banned[#banned + 1] = word
			end
		end
		check("proctrig: the file has none of the banned words and no em dash", #banned == 0, table.concat(banned, ","))
	end
end
-- >>> mp-proc-triggers (end)
-- >>> ms-hud (begin)
-- Minimap, buffs, experience bars, tracker and loot (Hud.lua): the 27 rows of build ms-19. The values are kept in one table M: the main function of this file
-- has a limit on the locals alive at once. The world is the one of section 60 (FH.hudLogin) with M.extra adding what the new rows need.
do
	local M = { SQUARE = "Interface\\ChatFrame\\ChatFrameBackground", MASK = "ui-hud-minimap-frame-generic-mask", GAME = "Fonts\\FRIZQT__.TTF",
		STRIPES = "Interface\\AddOns\\FlatUI\\Media\\Stripes.tga", NAMES = { "Tracking", "IndicatorFrame", "GameTimeFrame", "TimeManagerClockButton", "AddonCompartmentFrame" },
		DEFAULT = "Same as the Flat UI page" }
	-- A font string of the game's. It answers IsForbidden as every widget of the client does.
	function M.text(W, text)
		local fs, raw = W.Rr(nil, nil, { kind = "FontString" })
		raw.IsForbidden = function() return false end
		if text then
			raw.text = text
		end
		return fs, raw
	end
	-- A button of the minimap cluster that takes the mouse; EnableMouse on a protected frame in combat is a violation.
	function M.button(W, more)
		local frame, raw = W.B(nil, {}, more)
		raw.mouse = true
		raw.mouseSets = 0
		raw.GetAlpha = function() return raw.alpha end
		raw.EnableMouse = function(_, on)
			if raw.protected and W.combat then
				bad(W, "EnableMouse on a protected frame in combat")
			end
			raw.mouse, raw.mouseSets = on, raw.mouseSets + 1
		end
		raw.IsMouseEnabled = function() return raw.mouse end
		return frame, raw
	end
	-- A status bar with a fill the game draws from a file, and the colour the game gives it.
	function M.bar(W, file)
		local fill, fillRaw = W.Rr(nil, nil)
		fillRaw.file = file
		local status, raw = W.B(nil, { BorderLeft = W.R(nil, "x"), BorderRight = W.R(nil, "x"), BorderMid = W.R(nil, "x") })
		raw.tint = { 1, 1, 1, 1 }
		raw.GetStatusBarTexture = function() return fill end
		raw.SetStatusBarTexture = function(_, asset)
			fillRaw.color = nil
			if asset:find("[\\/]") then
				fillRaw.atlas, fillRaw.file = nil, asset
			else
				fillRaw.atlas, fillRaw.file = asset, nil
			end
			return true
		end
		raw.SetColorFill = function(_, r, g, b, a) fillRaw.color, fillRaw.atlas, fillRaw.file = { r, g, b, a }, nil, nil end
		raw.SetStatusBarColor = function(_, r, g, b, a) raw.tint = { r, g, b, a or 1 } end
		return status, raw, fillRaw
	end
	-- What the new rows act on, added to the world of section 60 before it is sealed.
	function M.extra(H, set, W, more)
		local env, B, R, Rr, raw = W.env, W.B, W.R, W.Rr, W.rawOf
		env.GetTime = function() return W.now end
		env.UnitFactionGroup = function() return "Horde" end
		-- The minimap: the mask, the zoom (0 is the widest), the mouse and the zone name.
		local mr = raw[H.map]
		H.masks, H.zoom, H.zoomSets, H.over = {}, 0, 0, false
		mr.SetMaskTexture = function(_, file) H.masks[#H.masks + 1] = file end
		mr.GetZoom = function()
			if H.zoomRead == "secret" then
				return SECRET
			end
			return H.zoom
		end
		mr.SetZoom = function(_, zoom) H.zoom, H.zoomSets = zoom, H.zoomSets + 1 end
		mr.IsMouseOver = function() return H.over end
		H.zone, H.zoneRaw = M.text(W)
		set("MinimapZoneText", H.zone)
		H.diel = raw[H.cluster].DielFrame
		H.btn = {}
		H.btn.Tracking = H.tracking
		-- The game's Tracking and IndicatorFrame take no mouse themselves: their children do (Minimap.xml:74-93, 105, 160).
		raw[H.tracking].GetAlpha = function() return raw[H.tracking].alpha end
		local function mouseOn(frame)
			local fr = raw[frame]
			fr.mouse, fr.mouseSets = true, 0
			fr.EnableMouse = function(_, on) fr.mouse, fr.mouseSets = on, fr.mouseSets + 1 end
			fr.IsMouseEnabled = function() return fr.mouse end
			return frame
		end
		H.mice = { Tracking = { mouseOn(raw[H.tracking].Button) } }
		local mail, crafting = M.button(W), M.button(W)
		H.btn.IndicatorFrame = W.B(nil, { MailFrame = mail, CraftingOrderFrame = crafting })
		raw[H.btn.IndicatorFrame].GetAlpha = function() return raw[H.btn.IndicatorFrame].alpha end
		H.mice.IndicatorFrame = { mail, crafting }
		raw[H.cluster].IndicatorFrame = H.btn.IndicatorFrame
		for _, name in ipairs({ "GameTimeFrame", "TimeManagerClockButton", "AddonCompartmentFrame" }) do
			H.btn[name] = M.button(W, { protected = more.protect == name })
			set(name, H.btn[name])
			H.mice[name] = { H.btn[name] }
		end
		-- Duration and count text on the aura buttons; the game's Update gives the font back.
		for _, part in ipairs({ H.buff, H.debuff }) do
			local duration, durationRaw = M.text(W)
			raw[part.btn].Duration = duration
			part.duration, part.durationRaw = duration, durationRaw
			part.countRaw = raw[raw[part.btn].Count]
			local update = raw[part.btn].Update
			raw[part.btn].Update = function(self, info)
				durationRaw.font, part.countRaw.font = { M.GAME, 12, "" }, { M.GAME, 12, "" }
				return update(self, info)
			end
		end
		-- Experience and reputation: the text, the numbers the game keeps on the bar and the Update that sets them after the text, as ReputationBar.lua:152-163 does.
		for _, part in ipairs({ H.exp, H.rep }) do
			local text, textRaw = M.text(W)
			local frameRaw = raw[part.frame]
			frameRaw.OverlayFrame = B(nil, { Text = text })
			frameRaw.SetBarText = function(_, line) text:SetText(line) end
			part.text, part.textRaw, part.frameRaw = text, textRaw, frameRaw
		end
		H.exp.frameRaw.currXP, H.exp.frameRaw.maxBar = 450, 1000
		H.exp.frameRaw.Update = function(self) H.exp.frameRaw.next = nil self:SetBarText(("%d/%d"):format(H.exp.frameRaw.currXP, H.exp.frameRaw.maxBar)) end
		H.exp.textRaw.text = "450/1000"
		H.rep.frameRaw.name, H.rep.frameRaw.value, H.rep.frameRaw.max = "Honor Hold %d / %d", 300, 3000
		H.rep.frameRaw.Update = function(self)
			local n = H.rep.frameRaw.next or { "Honor Hold %d / %d", 300, 3000 }
			self:SetBarText(n[1]:find("%d", 1, true) and n[1]:format(n[2], n[3]) or n[1])
			H.rep.frameRaw.name, H.rep.frameRaw.value, H.rep.frameRaw.max = n[1], n[2], n[3]
		end
		H.rep.textRaw.text = "Honor Hold 300 / 3000"
		-- The objective tracker: a nine slice, a header with text, the quest module with a header and a progress bar.
		local headerText, headerRaw = M.text(W)
		H.nine = B(nil, {})
		H.tracker = B(nil, { NineSlice = H.nine, Header = B(nil, { Text = headerText }) })
		set("ObjectiveTrackerFrame", H.tracker)
		H.headerText, H.headerRaw = headerText, headerRaw
		raw[H.tracker].GetAlpha = function() return raw[H.tracker].alpha end
		local modText, modRaw = M.text(W)
		H.modText, H.modRaw = modText, modRaw
		local status, statusRaw, fillRaw = M.bar(W, "Interface\\TargetingFrame\\UI-StatusBar")
		H.trackerBar, H.trackerFill, H.trackerBarRaw = status, fillRaw, statusRaw
		H.quest = B(nil, { Header = B(nil, { Text = modText }), usedProgressBars = { line1 = B(nil, { Bar = status }) }, usedTimerBars = {}, usedRightEdgeFrames = {} })
		set("QuestObjectiveTracker", H.quest)
		FH.hookable(W, raw[H.quest], "OnSizeChanged")
		-- The loot window with a card: the game sets the word for the quality in Init and leaves whether it shows alone.
		H.rowMixin = { Init = function() end }
		set("LootFrameElementMixin", H.rowMixin)
		local quality, qualityRaw = M.text(W, "Uncommon")
		local art = { NormalTexture = R(nil, "x"), PushedTexture = R(nil, "x"), IconBorder = R(nil, "x"), icon = R(nil, nil) }
		local name = R(nil, "looting_itemcard_bg")
		raw[name].vertex = { 0.12, 0.75, 0.12, 1 }
		local item = B(nil, art)
		local card, cardRaw = B(nil, { Item = item, NameFrame = name, BorderFrame = R(nil, "x"), QualityText = quality })
		cardRaw.Init = H.rowMixin.Init
		H.card, H.cardIcon, H.quality, H.qualityRaw = card, art.icon, quality, qualityRaw
		local target = B(nil, {})
		raw[target].children = { card }
		set("LootFrame", B(nil, { ScrollBox = B(nil, { ScrollTarget = target }) }))
	end
	function M.login(more)
		more = more or {}
		local saved = more.saved
		return FH.hudLogin({ saved = saved, combat = more.combat, city = more.city, extra = function(H, set, W) M.extra(H, set, W, more) end })
	end
	-- The frames of the addon's own that run a function every frame while they are shown, and the time passing by dt for them.
	function M.tick(W, dt)
		W.advance(dt)
		for _, f in ipairs(W.eventFrames) do
			if f.onUpdate and f.shown then
				f.onUpdate(f, dt)
			end
		end
	end
	function M.updaters(W)
		local n = 0
		for _, f in ipairs(W.eventFrames) do
			if f.onUpdate and f.shown then
				n = n + 1
			end
		end
		return n
	end
	-- The outline of the minimap itself: a frame of the addon's on the map with four edges, and the texture behind them.
	function M.outline(W, H)
		for _, frame in ipairs(W.addonFrames) do
			if frame.parent == H.map and frame.allPoints == H.map then
				local edges, shown = W.edgesOn(frame), 0
				for _, e in ipairs(edges) do
					shown = shown + (e.shown and 1 or 0)
				end
				local back
				for _, t in ipairs(W.addonTextures) do
					if t.allPoints == H.map and t.layer == "BACKGROUND" then
						back = t
					end
				end
				return { n = #edges, shown = shown, back = back and back.shown, color = edges[1] and edges[1].color }
			end
		end
	end
	function M.disc(W)
		for _, frame in ipairs(W.addonFrames) do
			if frame.strata == "BACKGROUND" then
				return frame.regions[1]
			end
		end
	end
	-- The game masks the minimap again from its callback of the rotateMinimap variable, and the event of the variable comes with it.
	function M.remask(W, map)
		W.blizzard(function() map:SetMaskTexture(M.MASK) end)
		W.fire("CVAR_UPDATE", "rotateMinimap", "1")
		W.flush()
	end
	function M.size(raw) return raw.font and raw.font[2] end
	function M.colour(o, r, g, b) return o and near(o.r, r, 1e-6) and near(o.g, g, 1e-6) and near(o.b, b, 1e-6) end
	function M.clean(W) return #W.violations == 0 and #W.errors == 0 end

	-- True when every frame that takes the mouse for a button has the wanted state, and the sets made on them.
	function M.mouseIs(H, name, want)
		for _, frame in ipairs(H.mice[name]) do
			if H.W.rawOf[frame].mouse ~= want then
				return false
			end
		end
		return true
	end
	function M.mouseSets(H, name)
		return H.W.rawOf[H.mice[name][1]].mouseSets
	end

	-- Every row at its default: the game is left exactly as it is, and no call is made that the game did not make.
	do
		local H = M.login()
		local W, raw = H.W, H.W.rawOf
		local still = true
		for _, name in ipairs(M.NAMES) do
			local frame = H.btn[name]
			still = still and raw[frame].calls.SetAlpha == nil and M.mouseSets(H, name) == 0 and M.mouseIs(H, name, true)
		end
		check("ms-hud: defaults: the minimap keeps the game's mask, zone name, medallion and buttons",
			#H.masks == 0 and H.zoneRaw.calls.SetAlpha == nil and H.zoneRaw.calls.SetFont == nil and raw[H.diel].calls.SetAlpha == nil and still and M.outline(W, H) == nil and M.disc(W) and M.disc(W).shown and H.compass.alpha == 0 and M.clean(W), #H.masks .. " " .. tostring(M.updaters(W)))
		check("ms-hud: defaults: the aura text, the experience text, the tracker and the loot cards are left alone",
			H.buff.durationRaw.calls.SetFont == nil and H.buff.countRaw.calls.SetFont == nil and H.exp.textRaw.text == "450/1000" and H.rep.textRaw.text == "Honor Hold 300 / 3000"
				and H.exp.textRaw.calls.SetFont == nil and raw[H.tracker].calls.SetAlpha == nil and H.headerRaw.calls.SetFont == nil and H.modRaw.calls.SetFont == nil
				and W.look(H.nine) == nil and H.qualityRaw.calls.SetShown == nil and H.qualityRaw.shown and H.cardIcon.texCoord and near(H.cardIcon.texCoord[1], 0.08)
				and near(H.buff.icon.texCoord[1], 0.08), tostring(H.cardIcon.texCoord))
		check("ms-hud: defaults: the status has no new line", not has(W.status(), "refused") and not has(W.status(), "zoom"), W.status())
	end

	-- Minimap shape.
	do
		local H = M.login()
		local W, raw = H.W, H.W.rawOf
		W.change("hud.shape", "Square")
		local disc = M.disc(W)
		local edge = M.outline(W, H)
		check("ms-hud: shape: Square puts the plain mask on the minimap, hides the disc and draws the outline of the map without a background",
			#H.masks == 1 and H.masks[1] == M.SQUARE and not disc.shown and edge and edge.n == 4 and edge.shown == 4 and edge.back == false and M.colour({ r = edge.color[1], g = edge.color[2], b = edge.color[3] }, 0, 0, 0)
				and M.clean(W), tostring(#H.masks) .. " " .. tostring(H.masks[1]))
		W.change("hud.minimapArt", false)
		check("ms-hud: shape: the ring and the pointer stay off a square map when Hide minimap ring and header is off", H.compass.alpha == 0 and H.underlay.alpha == 0)
		W.change("hud.minimapArt", true)
		M.remask(W, H.map)
		check("ms-hud: shape: the game masks the minimap again, and the square mask goes on once more without a loop",
			#H.masks == 3 and H.masks[2] == M.MASK and H.masks[3] == M.SQUARE, table.concat(H.masks, ","))
		W.change("hud.minimapBorder", false)
		local off = M.outline(W, H)
		W.change("hud.minimapBorder", true)
		check("ms-hud: shape: Minimap border off hides the outline of the square map", off and off.shown == 0 and not M.disc(W).shown and M.outline(W, H).shown == 4)
		W.change("general.border", "ff336699")
		W.flush()
		local blue = M.outline(W, H)
		W.change("general.border", "ff000000")
		W.flush()
		check("ms-hud: shape: the outline takes the border colour", blue and near(blue.color[1], 0.2, 1e-6) and near(blue.color[3], 0.6, 1e-6))
		W.change("general.borderMode", "Your faction colour")
		W.flush()
		local faction = M.outline(W, H)
		W.change("hud.shape", "Round")
		check("ms-hud: shape: the border colour source reaches the outline of a square map and the disc of a round one",
			faction and near(faction.color[1], 0.9, 1e-6) and near(faction.color[2], 0.05, 1e-6) and M.disc(W).shown and near(M.disc(W).color[1], 0.9, 1e-6)
				and near(M.disc(W).color[3], 0.07, 1e-6))
		W.change("general.borderMode", "Border colour on the Flat UI page")
		check("ms-hud: shape: Round puts the game's mask back, shows the disc, hides the outline and brings the ring back",
			#H.masks == 4 and H.masks[4] == M.MASK and M.disc(W).shown and M.outline(W, H).shown == 0 and H.compass.alpha == 0 and M.clean(W), table.concat(H.masks, ","))
		M.remask(W, H.map)
		check("ms-hud: shape: the game's own mask is left alone once the map is round again", #H.masks == 5 and H.masks[5] == M.MASK)
		-- A square map at login, and the page off.
		local S = M.login({ saved = { options = { ["hud.shape"] = "square" } } })
		check("ms-hud: shape: square at login: the plain mask, no disc, the outline", #S.masks == 1 and S.masks[1] == M.SQUARE and M.disc(S.W) == nil and M.outline(S.W, S).shown == 4 and M.clean(S.W))
		S.W.change("hud.enabled", false)
		S.W.flush()
		check("ms-hud: shape: the page off gives the round mask back and hides the outline", #S.masks == 2 and S.masks[2] == M.MASK and M.outline(S.W, S).shown == 0 and S.compass.alpha == 1, table.concat(S.masks, ","))
		M.remask(S.W, S.map)
		check("ms-hud: shape: a game that masks again with the page off is left alone", #S.masks == 3)
		-- The city map keeps its round mask: no round cover over a square map.
		local C = M.login({ city = "shown" })
		local before = has(C.W.status(), "cover shown")
		C.W.change("general.borderMode", "Your faction colour")
		C.W.flush()
		local pictures = {}
		for _, texture in ipairs(C.W.addonTextures) do
			if texture.file == "Interface\\AddOns\\FlatUI\\Media\\Cover.tga" then
				pictures[#pictures + 1] = texture
			end
		end
		check("ms-hud: shape: the ring of the city map cover takes the border colour source", #pictures == 2 and near(pictures[1].vertex[1], 0.9, 1e-6) and near(pictures[1].vertex[3], 0.07, 1e-6))
		C.W.change("general.borderMode", "Border colour on the Flat UI page")
		C.W.change("hud.shape", "Square")
		local square = has(C.W.status(), "no cover")
		C.W.change("hud.shape", "Round")
		check("ms-hud: shape: the round cover is drawn over the city map of a round minimap and not over a square one",
			before and square and has(C.W.status(), "cover shown"), C.W.status())
		-- A mask the game refuses: the map stays round and the status says so.
		local R = M.login()
		R.W.rawOf[R.map].SetMaskTexture = function() error("refused", 0) end
		R.W.change("hud.shape", "Square")
		check("ms-hud: shape: a mask the game refuses is said in the status, the map stays round and nothing is raised",
			has(R.W.status(), "the game refused the square mask, so the minimap stays round") and M.disc(R.W).shown and R.compass.alpha == 0 and M.clean(R.W), R.W.status())
	end

	-- Zoom out after.
	do
		local H = M.login()
		local W = H.W
		local base = M.updaters(W)
		W.change("hud.zoomReset", 10)
		check("ms-hud: zoom: a map at its widest zoom starts no count", M.updaters(W) == base and H.zoomSets == 0)
		H.zoom = 3
		W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(W, 5)
		check("ms-hud: zoom: five seconds after the zoom changed nothing happens", M.updaters(W) == base + 1 and H.zoomSets == 0 and H.zoom == 3)
		M.tick(W, 5)
		check("ms-hud: zoom: after ten seconds the map zooms out once and the counting stops", H.zoomSets == 1 and H.zoom == 0 and M.updaters(W) == base)
		M.tick(W, 20)
		check("ms-hud: zoom: and no more calls follow", H.zoomSets == 1)
		H.zoom = 2
		H.over = true
		W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(W, 12)
		local held = H.zoomSets == 1
		H.over = false
		M.tick(W, 0.5)
		check("ms-hud: zoom: with the mouse over the map nothing is done, and the map zooms out when the mouse leaves", held and H.zoomSets == 2 and H.zoom == 0)
		H.zoom = 3
		W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(W, 6)
		H.zoom = 4
		W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(W, 6)
		local again = H.zoomSets == 2
		M.tick(W, 5)
		check("ms-hud: zoom: a change of the zoom starts the count again", again and H.zoomSets == 3 and H.zoom == 0)
		H.zoom = 3
		W.fire("MINIMAP_UPDATE_ZOOM")
		W.change("hud.zoomReset", 0)
		M.tick(W, 100)
		check("ms-hud: zoom: 0 is off, and a count that was running stops", H.zoomSets == 3 and M.updaters(W) == base)
		W.change("hud.zoomReset", 5)
		M.tick(W, 5)
		check("ms-hud: zoom: a row turned on while the map is zoomed starts the count", H.zoomSets == 4 and H.zoom == 0)
		H.zoomRead = "secret"
		H.zoom = 3
		W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(W, 100)
		check("ms-hud: zoom: a zoom the game does not say is never reset, and the status says so",
			H.zoomSets == 4 and has(W.status(), "Minimap zoom out: off, the game does not say the zoom level."), W.status())
		H.zoomRead = nil
		W.fire("MINIMAP_UPDATE_ZOOM")
		W.change("hud.enabled", false)
		M.tick(W, 100)
		check("ms-hud: zoom: with the page off nothing counts and the status line is gone", H.zoomSets == 4 and not has(W.status(), "Minimap zoom out") and M.clean(W))
		local R = M.login()
		R.W.rawOf[R.map].SetZoom = function() error("refused", 0) end
		R.W.change("hud.zoomReset", 5)
		R.zoom = 3
		R.W.fire("MINIMAP_UPDATE_ZOOM")
		M.tick(R.W, 6)
		check("ms-hud: zoom: a zoom the game refuses is said in the status and raises nothing", has(R.W.status(), "the game refused to zoom the minimap out") and M.clean(R.W), R.W.status())
	end

	-- Day and night icon, zone name, buttons.
	do
		local H = M.login()
		local W, raw = H.W, H.W.rawOf
		W.change("hud.dayNight", false)
		local night = raw[H.diel].alpha == 0
		W.change("hud.dayNight", true)
		check("ms-hud: icon: the day and night icon goes and comes back", night and raw[H.diel].alpha == 1 and raw[H.diel].calls.SetAlpha == 2)
		W.change("hud.zoneText", false)
		local gone = H.zoneRaw.alpha == 0
		W.change("hud.zoneText", true)
		check("ms-hud: zone: the zone name goes and comes back", gone and H.zoneRaw.alpha == 1)
		W.change("hud.zoneSize", 150)
		local big = M.size(H.zoneRaw) == 18
		W.change("hud.zoneSize", 100)
		check("ms-hud: zone: the size is a percent of the game's size and 100 gives it back", big and M.size(H.zoneRaw) == 12 and H.zoneRaw.font[1] == M.GAME)
		raw[H.btn.GameTimeFrame].alpha = 0.4
		raw[H.btn.TimeManagerClockButton].mouse = false
		local rows = { Tracking = "hud.btnTracking", IndicatorFrame = "hud.btnMail", GameTimeFrame = "hud.btnCalendar", TimeManagerClockButton = "hud.btnClock", AddonCompartmentFrame = "hud.btnAddons" }
		local alone, why = true, nil
		for _, name in ipairs(M.NAMES) do
			W.change(rows[name], false)
			for _, other in ipairs(M.NAMES) do
				if other ~= name and raw[H.btn[other]].alpha == 0 then
					alone = false
					why = (why or "") .. name .. " took " .. other .. "; "
				end
			end
			if not (raw[H.btn[name]].alpha == 0 and M.mouseIs(H, name, false)) then
				alone = false
				why = (why or "") .. name .. " alpha " .. tostring(raw[H.btn[name]].alpha) .. " mouse " .. tostring(M.mouseIs(H, name, false)) .. "; "
			end
			W.change(rows[name], true)
		end
		check("ms-hud: buttons: each button goes off alone, with no opacity and no mouse", alone and M.clean(W), tostring(why))
		check("ms-hud: buttons: and comes back with the opacity and the mouse state the game had",
			raw[H.btn.GameTimeFrame].alpha == 0.4 and raw[H.btn.TimeManagerClockButton].mouse == false and raw[H.btn.Tracking].alpha == 1 and M.mouseIs(H, "Tracking", true)
				and M.mouseIs(H, "IndicatorFrame", true) and raw[H.btn.AddonCompartmentFrame].alpha == 1,
			table.concat({ raw[H.btn.GameTimeFrame].alpha, tostring(raw[H.btn.TimeManagerClockButton].mouse), raw[H.btn.Tracking].alpha, tostring(M.mouseIs(H, "Tracking", true)),
				tostring(M.mouseIs(H, "IndicatorFrame", true)), raw[H.btn.AddonCompartmentFrame].alpha }, " "))
		W.change("hud.btnTracking", false)
		W.change("hud.zoneSize", 105)
		W.change("hud.zoneSize", 100)
		check("ms-hud: buttons: a button that is off is not set again by the looks that follow", raw[H.btn.Tracking].calls.SetAlpha == 3 and M.mouseSets(H, "Tracking") == 3,
			tostring(raw[H.btn.Tracking].calls.SetAlpha) .. " " .. tostring(M.mouseSets(H, "Tracking")))
		W.change("hud.enabled", false)
		check("ms-hud: buttons: the page off gives every button back", raw[H.btn.Tracking].alpha == 1 and M.mouseIs(H, "Tracking", true) and M.mouseIs(H, "IndicatorFrame", true))
		-- A button that may be protected waits for the end of combat for its mouse.
		local P = M.login({ protect = "TimeManagerClockButton" })
		local pr = P.W.rawOf[P.btn.TimeManagerClockButton]
		P.W.combat = true
		P.W.change("hud.btnClock", false)
		local waiting = pr.alpha == 0 and pr.mouse == true and #P.W.violations == 0
		P.W.combat = false
		P.W.fire("PLAYER_REGEN_ENABLED")
		P.W.flush()
		check("ms-hud: buttons: a protected clock loses its opacity in combat and its mouse after combat", waiting and pr.mouse == false and M.clean(P.W), tostring(pr.mouse))
		-- The clock is made when the game loads its time manager.
		local L = M.login({ saved = { options = { ["hud.btnClock"] = false } } })
		local clock = L.W.rawOf[L.btn.TimeManagerClockButton]
		check("ms-hud: buttons: off at login: the five frames are looked up again when the player enters the world and when the time manager loads",
			clock.alpha == 0 and clock.mouse == false and L.W.rawOf[L.btn.Tracking].alpha == 1, tostring(clock.alpha) .. " " .. tostring(clock.mouse) .. " " .. tostring(L.W.rawOf[L.btn.Tracking].alpha) .. " " .. L.W.status())
		-- The game makes the clock again when it loads the time manager.
		local made, madeRaw = M.button(L.W)
		L.W.env.TimeManagerClockButton = made
		L.W.fire("ADDON_LOADED", "Blizzard_TimeManager")
		local loaded = madeRaw.alpha == 0 and madeRaw.mouse == false
		local later, laterRaw = M.button(L.W)
		L.W.env.TimeManagerClockButton = later
		L.W.fire("PLAYER_ENTERING_WORLD", false, false)
		check("ms-hud: buttons: the time manager loading and entering the world each look at the buttons", loaded and laterRaw.alpha == 0 and laterRaw.mouse == false)
		-- A button off stays off whatever Fading does.
		local F = M.login({ saved = { options = { ["hud.btnTracking"] = false, ["fade.enabled"] = true, ["fade.minimapButtons"] = true } } })
		for _ = 1, 30 do
			M.tick(F.W, 0.1)
		end
		local calendar = F.W.rawOf[F.btn.GameTimeFrame]
		check("ms-hud: buttons: a button that is off stays off with Fading on, and the buttons that are on fade", F.W.rawOf[F.btn.Tracking].alpha == 0 and calendar.alpha < 1, tostring(calendar.alpha))
		-- Fading on at 25%, a button switched off then on, then Fading off: the opacity the game had comes back.
		local G = M.login({ saved = { options = { ["fade.enabled"] = true, ["fade.minimapButtons"] = true } } })
		for _ = 1, 40 do
			M.tick(G.W, 0.1)
		end
		local cal = G.W.rawOf[G.btn.GameTimeFrame]
		G.W.change("hud.btnCalendar", false)
		M.tick(G.W, 0.1)
		G.W.change("hud.btnCalendar", true)
		for _ = 1, 40 do
			M.tick(G.W, 0.1)
		end
		G.W.change("fade.enabled", false)
		for _ = 1, 10 do
			M.tick(G.W, 0.1)
		end
		check("ms-hud: buttons: Fading on, a button off then on, then Fading off: the opacity returns to 1", near(cal.alpha, 1, 0.01), tostring(cal.alpha))
		-- Faded opacity 0 and the mouse over the minimap: a button that is off stays at 0.
		local Z = M.login({ saved = { options = { ["fade.enabled"] = true, ["fade.minimapButtons"] = true, ["fade.alpha"] = 0 } } })
		for _ = 1, 40 do
			M.tick(Z.W, 0.1)
		end
		Z.W.change("hud.btnCalendar", false)
		Z.W.rawOf[Z.cluster].IsMouseOver = function() return true end
		for _ = 1, 40 do
			M.tick(Z.W, 0.1)
		end
		check("ms-hud: buttons: a button that is off stays at 0 with the faded opacity 0 and the mouse over the cluster", Z.W.rawOf[Z.btn.GameTimeFrame].alpha == 0, tostring(Z.W.rawOf[Z.btn.GameTimeFrame].alpha))
	end

	-- Buffs and debuffs.
	do
		local H = M.login()
		local W, raw = H.W, H.W.rawOf
		W.change("hud.crop", 12)
		local back = H.bags.MainMenuBarBackpackButton
		check("ms-hud: crop: Icon crop reaches the buff, the bag and the loot icons", near(H.buff.icon.texCoord[1], 0.12) and near(H.buff.icon.texCoord[2], 0.88) and near(back.icon.texCoord[1], 0.12)
			and near(back.icon.texCoord[4], 0.88) and near(H.cardIcon.texCoord[1], 0.12) and near(H.debuff.icon.texCoord[3], 0.12), tostring(H.cardIcon.texCoord and H.cardIcon.texCoord[1]))
		W.change("hud.crop", 0)
		check("ms-hud: crop: 0 shows the whole icon", near(H.buff.icon.texCoord[1], 0) and near(H.buff.icon.texCoord[2], 1) and near(back.icon.texCoord[1], 0))
		W.change("hud.crop", 8)
		check("ms-hud: crop: 8 is the game's trim as before", near(H.buff.icon.texCoord[1], 0.08) and near(back.icon.texCoord[1], 0.08) and near(H.cardIcon.texCoord[1], 0.08))
		W.change("hud.auras", false)
		W.change("hud.crop", 12)
		check("ms-hud: crop: with the borders off the icon keeps the game's picture", near(H.buff.icon.texCoord[1], 0) and near(H.buff.icon.texCoord[2], 1))
		W.change("hud.auras", true)
		W.change("hud.crop", 8)
		W.change("hud.colourMagic", "ff336699")
		check("ms-hud: colours: a colour chosen for Magic reaches the border of a magic debuff and no other",
			M.colour(W.look(H.debuff.icon), 0.2, 0.4, 0.6) and M.colour(W.look(H.deadly.icon), 0.6, 0, 1) and M.colour(W.look(H.enchant.icon), 0.64, 0.21, 0.93))
		W.change("hud.colourCurse", "ff112233")
		W.change("hud.colourDisease", "ff223344")
		W.change("hud.colourPoison", "ff334455")
		FH.auraUpdate(W, H.debuff.btn, { auraType = "Debuff", debuffType = "Disease" })
		local disease = M.colour(W.look(H.debuff.icon), 34 / 255, 51 / 255, 68 / 255)
		FH.auraUpdate(W, H.debuff.btn, { auraType = "Debuff", debuffType = "Poison" })
		local poison = M.colour(W.look(H.debuff.icon), 51 / 255, 68 / 255, 85 / 255)
		FH.auraUpdate(W, H.debuff.btn, { auraType = "Debuff", debuffType = "Bleed" })
		local bleed = M.colour(W.look(H.debuff.icon), 0.8, 0, 0)
		check("ms-hud: colours: the Curse, Disease and Poison rows each colour their own type, and a bleed has the Other colour", M.colour(W.look(H.deadly.icon), 17 / 255, 34 / 255, 51 / 255) and disease and poison and bleed)
		W.change("hud.colourOther", "ff00ff00")
		local bled = M.colour(W.look(H.debuff.icon), 0, 1, 0)
		FH.auraUpdate(W, H.debuff.btn, { auraType = "Debuff" })
		check("ms-hud: colours: Other debuffs colours a bleed and a debuff with no type", bled and M.colour(W.look(H.debuff.icon), 0, 1, 0))
		FH.auraUpdate(W, H.debuff.btn, { auraType = "Debuff", debuffType = "Magic" })
		W.change("hud.auraTypes", false)
		check("ms-hud: colours: with Border colour by debuff type off every debuff takes the Other colour",
			M.colour(W.look(H.debuff.icon), 0, 1, 0) and M.colour(W.look(H.deadly.icon), 0, 1, 0) and M.colour(W.look(H.enchant.icon), 0.64, 0.21, 0.93))
		W.change("hud.auraTypes", true)
		check("ms-hud: colours: and on again gives each type its colour", M.colour(W.look(H.debuff.icon), 0.2, 0.4, 0.6) and M.colour(W.look(H.deadly.icon), 17 / 255, 34 / 255, 51 / 255))
		-- Text sizes.
		W.change("hud.countSize", 50)
		check("ms-hud: text: the stack count has a percent of the game's size and the duration keeps it",
			M.size(H.buff.countRaw) == 6 and M.size(H.debuff.countRaw) == 6 and H.buff.durationRaw.calls.SetFont == nil)
		W.change("hud.durationSize", 150)
		check("ms-hud: text: the duration has a percent of the game's size, on each button",
			M.size(H.buff.durationRaw) == 18 and M.size(H.buff.countRaw) == 6 and M.size(H.debuff.durationRaw) == 18 and M.size(H.debuff.countRaw) == 6)
		FH.auraUpdate(W, H.buff.btn, { auraType = "Buff" })
		check("ms-hud: text: the game's update gives the font back and the size is set again after it", M.size(H.buff.durationRaw) == 18 and M.size(H.buff.countRaw) == 6)
		W.change("hud.auras", false)
		FH.auraUpdate(W, H.buff.btn, { auraType = "Buff" })
		check("ms-hud: text: the sizes do not depend on the borders", M.size(H.buff.durationRaw) == 18 and M.size(H.buff.countRaw) == 6)
		W.change("hud.auras", true)
		W.change("hud.durationSize", 100)
		W.change("hud.countSize", 100)
		check("ms-hud: text: 100 gives the game's size back", M.size(H.buff.durationRaw) == 12 and M.size(H.buff.countRaw) == 12 and H.buff.durationRaw.font[1] == M.GAME and M.clean(W))
		W.fontReturn = "error"
		W.change("hud.durationSize", 150)
		check("ms-hud: text: a size the game refuses is said in the status", has(W.status(), "the game refused a new size for the duration of a buff") and M.clean(W), W.status())
		W.fontReturn = nil
		-- Sizes with the borders off at login: the game's update still gives the font back and the size follows it.
		local B = M.login({ saved = { options = { ["hud.auras"] = false, ["hud.durationSize"] = 150 } } })
		local first = M.size(B.buff.durationRaw) == 18
		FH.auraUpdate(B.W, B.buff.btn, { auraType = "Buff" })
		check("ms-hud: text: with the borders off at login the size is set and follows the game's update", first and M.size(B.buff.durationRaw) == 18 and B.W.state(B.buff.icon) == "." and M.clean(B.W))
	end

	-- Experience and reputation bars.
	do
		local H = M.login()
		local W = H.W
		local exp, rep = H.exp, H.rep
		-- The game sets the text in its calls, and the events that lead to them make the pass one frame later.
		local function seen(event)
			W.fire(event or "PLAYER_XP_UPDATE")
			W.flush()
		end
		W.change("hud.xpText", "Percent")
		W.change("hud.xpText", "As the game has it")
		check("ms-hud: xp: a text changed before the game sets one again is given back as it was", exp.textRaw.text == "450/1000" and rep.textRaw.text == "Honor Hold 300 / 3000", exp.textRaw.text .. " " .. rep.textRaw.text)
		W.change("hud.xpText", "Percent")
		check("ms-hud: xp: Percent shows the share, and the reputation bar keeps its name", exp.textRaw.text == "45%" and rep.textRaw.text == "Honor Hold 10%", exp.textRaw.text .. " " .. rep.textRaw.text)
		W.change("hud.xpText", "Value and percent")
		check("ms-hud: xp: Value and percent", exp.textRaw.text == "450 / 1000 (45%)" and rep.textRaw.text == "Honor Hold 300 / 3000 (10%)", exp.textRaw.text .. " " .. rep.textRaw.text)
		W.change("hud.xpText", "Amount to go")
		check("ms-hud: xp: Amount to go", exp.textRaw.text == "550 to go" and rep.textRaw.text == "Honor Hold 2700 to go", exp.textRaw.text .. " " .. rep.textRaw.text)
		W.change("hud.xpText", "Hidden")
		check("xpown: hud: Hidden on the game's bar empties the text of both bars", exp.textRaw.text == "" and rep.textRaw.text == "", exp.textRaw.text .. "|" .. rep.textRaw.text)
		W.blizzard(function() exp.frame:Update() end)
		seen()
		check("xpown: hud: and the game setting its text again does not bring it back", exp.textRaw.text == "" and M.clean(W))
		W.change("hud.xpText", "Amount to go")
		check("xpown: hud: another mode gives a line again", exp.textRaw.text == "550 to go" and rep.textRaw.text == "Honor Hold 2700 to go", exp.textRaw.text .. "|" .. rep.textRaw.text)
		W.blizzard(function() exp.frame:Update() end)
		seen()
		check("ms-hud: xp: the game setting its text again is followed by ours", exp.textRaw.text == "550 to go")
		W.blizzard(function() exp.frame:SetBarText("450/1000") end)
		seen()
		check("ms-hud: xp: and so is the call that sets the text alone", exp.textRaw.text == "550 to go")
		exp.frameRaw.currXP = 500
		W.blizzard(function() exp.frame:Update() end)
		seen()
		check("ms-hud: xp: a new number reaches the text", exp.textRaw.text == "500 to go")
		W.change("hud.xpText", "Percent")
		exp.frameRaw.currXP = 455
		W.blizzard(function() exp.frame:Update() end)
		seen()
		check("ms-hud: xp: the percent is rounded down", exp.textRaw.text == "45%", exp.textRaw.text)
		W.change("hud.xpText", "Amount to go")
		rep.frameRaw.next = { "Honor Hold %d / %d", 600, 3000 }
		W.blizzard(function() rep.frame:Update() end)
		seen("UPDATE_FACTION")
		check("ms-hud: xp: a reputation bar shows its new numbers and not the ones before the update", rep.textRaw.text == "Honor Hold 2400 to go", rep.textRaw.text)
		rep.frameRaw.next = { "Exalted", 1, 1 }
		W.blizzard(function() rep.frame:Update() end)
		seen("UPDATE_FACTION")
		check("ms-hud: xp: a reputation at its top rank shows a name only and is left alone", rep.textRaw.text == "Exalted", rep.textRaw.text)
		rep.frameRaw.next = { "Honor Hold %d / %d", 600, 3000 }
		W.blizzard(function() rep.frame:Update() end)
		seen("UPDATE_FACTION")
		exp.frameRaw.currXP = SECRET
		W.blizzard(function() exp.frame:SetBarText("withheld") end)
		seen()
		check("ms-hud: xp: a withheld number leaves the game's text", exp.textRaw.text == "withheld" and M.clean(W), exp.textRaw.text)
		exp.frameRaw.currXP = 450
		W.change("hud.xpText", "As the game has it")
		check("ms-hud: xp: As the game has it gives the text the game set last", exp.textRaw.text == "withheld" and rep.textRaw.text == "Honor Hold 600 / 3000", exp.textRaw.text .. " " .. rep.textRaw.text)
		W.blizzard(function() exp.frame:Update() end)
		seen()
		check("ms-hud: xp: and the game's later text is left alone", exp.textRaw.text == "450/1000")
		W.change("hud.xpTextSize", 150)
		local big = M.size(exp.textRaw) == 18 and M.size(rep.textRaw) == 18
		W.change("hud.xpTextSize", 100)
		check("ms-hud: xp: Bar text size is a percent of the game's size", big and M.size(exp.textRaw) == 12 and M.size(rep.textRaw) == 12)
		-- Bar texture.
		W.change("hud.xpTexture", "Stripes")
		check("ms-hud: xp: a texture of its own for the experience and reputation bars while the Flat UI page has Flat", exp.fillRaw.file == M.STRIPES and rep.fillRaw.file == M.STRIPES)
		W.change("hud.xpTexture", M.DEFAULT)
		check("ms-hud: xp: the Flat UI page's texture again", exp.fillRaw.file == nil and exp.fillRaw.color ~= nil)
		W.change("general.barTexture", "Stripes")
		check("ms-hud: xp: the Flat UI page's texture is what follows", exp.fillRaw.file == M.STRIPES)
		W.change("hud.xpTexture", "Flat")
		check("ms-hud: xp: Flat is a solid colour while the Flat UI page has Stripes", exp.fillRaw.file == nil and exp.fillRaw.color ~= nil and near(exp.fillRaw.color[1], 0.58) and rep.fillRaw.file == nil)
		W.change("hud.xpFill", false)
		check("ms-hud: xp: Flat fill off gives the game's picture whatever the texture", exp.fillRaw.color == nil and exp.fillRaw.file == nil and M.clean(W))
	end

	-- hkhud: the text of the experience and reputation bars and the mask of the minimap follow the game's events, with taintLog 0 and 2, and no method of those
	-- frames is hooked.
	for _, tl in ipairs({ "0", "2" }) do
		local H = M.login()
		local W = H.W
		W.cvars.taintLog = tl
		local exp, rep = H.exp, H.rep
		local written = 0
		for _, entry in ipairs({ { exp.frame, "SetBarText" }, { exp.frame, "Update" }, { rep.frame, "SetBarText" }, { rep.frame, "Update" }, { H.map, "SetMaskTexture" } }) do
			if INSTHOOK.wrapped(W, entry[1], entry[2]) then
				written = written + 1
			end
		end
		check("hkhud: hud text and mask, taintLog " .. tl .. ": no method of the bars or of the minimap has a hook written on it", written == 0, written)
		W.change("hud.xpText", "Percent")
		W.blizzard(function() exp.frame:Update() end)
		local game = exp.textRaw.text == "450/1000"
		W.fire("UPDATE_EXHAUSTION")
		local waits = exp.textRaw.text == "450/1000"
		W.flush()
		check("hkhud: hud text and mask, taintLog " .. tl .. ": the text the game sets is ours on the next frame after the event of the bar, not before", game and waits and exp.textRaw.text == "45%" and rep.textRaw.text == "Honor Hold 10%", exp.textRaw.text)
		exp.frameRaw.currXP = 600
		W.blizzard(function() exp.frame:Update() end)
		W.fire("PLAYER_XP_UPDATE")
		W.flush()
		check("hkhud: hud text and mask, taintLog " .. tl .. ": a new number reaches the text", exp.textRaw.text == "60%", exp.textRaw.text)
		-- A zone change: the manager updates every shown bar, which sets the game's text again.
		W.blizzard(function() exp.frame:Update() end)
		local gameAgain = exp.textRaw.text == "600/1000"
		W.blizzard(function() FH.script(W, H.manager, "OnEvent", "ZONE_CHANGED") end)
		local zoneWaits = exp.textRaw.text == "600/1000"
		W.flush()
		check("hkhud: hud text and mask, taintLog " .. tl .. ": the manager's zone change event puts our text back on the next frame, not before", gameAgain and zoneWaits and exp.textRaw.text == "60%" and #(W.rawOf[H.manager].scriptHooks.OnEvent or {}) == 1, exp.textRaw.text)
		W.change("hud.xpText", "As the game has it")
		check("hkhud: hud text and mask, taintLog " .. tl .. ": As the game has it gives back the game's last text, which the bar showed under ours", exp.textRaw.text == "600/1000", exp.textRaw.text)
		W.blizzard(function() exp.frame:Update() end)
		W.fire("PLAYER_XP_UPDATE")
		W.flush()
		check("hkhud: hud text and mask, taintLog " .. tl .. ": and the game's later text is left alone", exp.textRaw.text == "600/1000" and M.clean(W), exp.textRaw.text)
		-- The mask.
		W.change("hud.shape", "Square")
		local before = #H.masks
		W.blizzard(function() H.map:SetMaskTexture(M.MASK) end)
		W.fire("CVAR_UPDATE", "rotateMinimap", "1")
		local waiting = #H.masks == before + 1
		W.flush()
		local after = #H.masks
		W.blizzard(function() H.map:SetMaskTexture(M.MASK) end)
		W.fire("CVAR_UPDATE", "somethingElse", "1")
		W.flush()
		check("hkhud: hud text and mask, taintLog " .. tl .. ": the square mask goes on again on the next frame after the rotateMinimap variable changes, and not after another variable",
			waiting and after == before + 2 and H.masks[after] == M.SQUARE and #H.masks == after + 1 and M.clean(W), table.concat(H.masks, ","))
	end

	-- Objective tracker.
	do
		local H = M.login()
		local W, raw = H.W, H.W.rawOf
		W.change("hud.trackerPanel", true)
		check("ms-hud: tracker: Tracker background draws a panel with a border round the nine slice", W.state(H.nine) == "SB" and M.clean(W), W.state(H.nine))
		W.change("hud.trackerPanel", false)
		check("ms-hud: tracker: and takes it away", W.state(H.nine) == "hb")
		W.change("hud.trackerHeaderSize", 150)
		check("ms-hud: tracker: Heading size reaches the heading of the tracker and of the quest module", M.size(H.headerRaw) == 18 and M.size(H.modRaw) == 18)
		W.change("hud.trackerHeaderSize", 100)
		check("ms-hud: tracker: and 100 gives it back", M.size(H.headerRaw) == 12 and M.size(H.modRaw) == 12)
		W.change("hud.trackerTexture", "Stripes")
		check("ms-hud: tracker: Tracker bar texture is a file on the progress bar, with the colour the game gives the bar", H.trackerFill.file == M.STRIPES and H.trackerBarRaw.tint[1] == 1)
		W.change("hud.trackerTexture", M.DEFAULT)
		check("ms-hud: tracker: the Flat UI page's texture again is a solid colour", H.trackerFill.file == nil and H.trackerFill.color ~= nil)
		W.change("general.barTexture", "Stripes")
		W.change("hud.trackerTexture", "Flat")
		check("ms-hud: tracker: Flat is a solid colour while the Flat UI page has Stripes", H.trackerFill.file == nil and H.trackerFill.color ~= nil)
		W.change("general.barTexture", "Flat")
		W.change("hud.trackerTexture", M.DEFAULT)
		-- Opacity in combat.
		raw[H.tracker].alpha = 0.7
		W.change("hud.trackerCombat", 40)
		check("ms-hud: tracker: Opacity in combat changes nothing out of combat", raw[H.tracker].calls.SetAlpha == nil and raw[H.tracker].alpha == 0.7)
		W.combat = true
		W.fire("PLAYER_REGEN_DISABLED")
		local low = near(raw[H.tracker].alpha, 0.4)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("ms-hud: tracker: the tracker has the lower opacity while the fight lasts and what the game had after it", low and raw[H.tracker].alpha == 0.7 and M.clean(W), tostring(raw[H.tracker].alpha))
		W.combat = true
		W.change("hud.trackerCombat", 100)
		check("ms-hud: tracker: a change in a fight reaches the tracker at once", raw[H.tracker].alpha == 0.7)
		W.change("hud.trackerCombat", 20)
		local fight = near(raw[H.tracker].alpha, 0.2)
		W.change("hud.enabled", false)
		W.combat = false
		check("ms-hud: tracker: the page off gives the opacity back", fight and raw[H.tracker].alpha == 0.7)
		W.fire("PLAYER_REGEN_DISABLED")
		check("ms-hud: tracker: with the page off a fight changes nothing", raw[H.tracker].alpha == 0.7)
	end

	-- Loot.
	do
		local H = M.login()
		local W = H.W
		W.change("hud.lootQualityText", false)
		check("ms-hud: loot: Quality word on loot off hides the word on each card", H.qualityRaw.shown == false and M.clean(W))
		W.blizzard(function() H.rowMixin.Init(H.card) end)
		check("ms-hud: loot: the game starting the card again leaves it hidden", H.qualityRaw.shown == false)
		W.change("hud.lootQualityText", true)
		check("ms-hud: loot: and on shows it again", H.qualityRaw.shown == true)
		W.change("hud.lootQualityText", false)
		W.change("hud.lootWindow", false)
		check("ms-hud: loot: with Loot window off the word shows whatever the row says", H.qualityRaw.shown == true)
		W.change("hud.lootWindow", true)
		check("ms-hud: loot: and the row is followed again with the loot window on", H.qualityRaw.shown == false)
	end
end
-- >>> ms-hud (end)

-- >>> enemybars (begin)
-- Enemy cooldowns: the bars above the target and focus frames. The helpers are on TOC.eb, so that this file gains no local.
do
	local EC = TOC.ec
	local EB = {}
	TOC.eb = EB
	-- A world with a target frame and a focus frame of the game's, so that the bars have something to hang from.
	function EB.world(o)
		o = o or {}
		local W = EC.world({ opts = o.opts or {}, setup = function(W)
			if not o.noFrames then
				W.env.TargetFrame = (W.B(nil, {}))
				W.env.FocusFrame = (W.B(nil, {}))
			end
			if o.setup then
				o.setup(W)
			end
		end })
		return W
	end
	-- Makes `unit` ("target" or "focus") an enemy player of a class, with a GUID, and says so as the game does.
	function EB.pick(W, unit, who)
		W.au.unit[unit] = { guid = who.guid, player = who.player ~= false, attack = who.attack ~= false, class = who.class, race = "Human", name = "Pick" }
		W.fire(unit == "focus" and "PLAYER_FOCUS_CHANGED" or "PLAYER_TARGET_CHANGED")
		W.flush()
	end
	function EB.bar(W, unit)
		local M = EC.mod(W)
		return M.rows[M.bars[unit]]
	end
	-- The holder's first point, as { point, relative to, relative point, x, y }.
	function EB.point(W, row)
		return W.rawOf[row.holder].points[1]
	end
	function EB.used(W, guid, spell, class)
		W.ns.Tracking.Cast(guid, class, spell, W.now)
	end
	EB.A, EB.B = "Player-2-0101", "Player-2-0102"
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- A target change draws the bar from that player's timers; a creature and a friendly player have none.
	local W = EB.world()
	check("enemybars: Place starts on Both", W.ns.Get("enemycd.place") == "both")
	EB.used(W, EB.A, 2139, "MAGE")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local row = EB.bar(W, "target")
	check("enemybars: a target that is an enemy player shows his timers on the bar", row ~= nil and EC.keys(W, row) == "MAGE:Counterspell" and W.rawOf[row.holder].shown == true, EC.keys(W, row))
	check("enemybars: the target is listened to for casts and buffs", (function()
		local cast, aura = EC.heard(W, "target")
		return cast == true and aura == true
	end)())
	EB.pick(W, "target", { guid = EB.B, class = "ROGUE" })
	check("enemybars: another target rebuilds the bar from his timers, which are none", EC.keys(W, row) == "" and W.rawOf[row.holder].shown == false)
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("enemybars: and the first target again has his timers back", EC.keys(W, row) == "MAGE:Counterspell")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE", attack = false })
	local cast, aura = EC.heard(W, "target")
	check("enemybars: a friendly player hides the bar and is not listened to", EC.keys(W, row) == "" and W.rawOf[row.holder].shown == false and cast == false and aura == false)
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	EB.pick(W, "target", { guid = EB.A, class = "MAGE", player = false })
	check("enemybars: a creature hides it too", EC.keys(W, row) == "" and W.rawOf[row.holder].shown == false)
	W.au.unit.target = nil
	W.fire("PLAYER_TARGET_CHANGED")
	check("enemybars: and no target leaves no icon", EC.keys(W, row) == "" and EC.ok(W), EC.why(W))
	-- The focus has a bar of its own.
	EB.used(W, EB.B, 1766, "ROGUE")
	EB.pick(W, "focus", { guid = EB.B, class = "ROGUE" })
	local focus = EB.bar(W, "focus")
	check("enemybars: the focus has its own bar", focus ~= nil and focus ~= row and EC.keys(W, focus) == "ROGUE:Kick" and EC.keys(W, row) == "", EC.keys(W, focus))
	check("enemybars: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- A cast seen through the target and through its plate is one use.
	local W = EB.world()
	local T = W.ns.Tracking
	local plate = EC.enemy(W, 1, { class = "MAGE", guid = EB.A })
	W.units.target = plate
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local t0 = W.now
	EC.cast(W, "target", 2139)
	local row = EB.bar(W, "target")
	check("enemybars: a cast of the target starts his timer and shows on the bar", T.Timer(EB.A, "MAGE:Counterspell") == t0 and EC.keys(W, row) == "MAGE:Counterspell", EC.keys(W, row))
	W.advance(0.5)
	EC.cast(W, "nameplate1", 2139)
	local start = T.Timer(EB.A, "MAGE:Counterspell")
	check("enemybars: the same cast through his plate half a second later is one use", start == t0 and EC.keys(W, EC.row(W, plate)) == "MAGE:Counterspell", tostring(start))
	W.advance(1.5)
	EC.cast(W, "nameplate1", 2139)
	check("enemybars: and one 2 seconds later is another use", T.Timer(EB.A, "MAGE:Counterspell") == t0 + 2, tostring(T.Timer(EB.A, "MAGE:Counterspell")))
	check("enemybars: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- A target whose GUID is withheld takes the record of his plate.
	local W = EB.world()
	local plate = EC.enemy(W, 1, { class = "MAGE", guid = EB.A })
	W.units.target = plate
	EB.used(W, EB.A, 2139, "MAGE")
	W.au.identityHidden = { target = true }
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local row = EB.bar(W, "target")
	local M = EC.mod(W)
	check("enemybars: a target with a withheld GUID shows the timers of the record of his plate", EC.keys(W, row) == "MAGE:Counterspell" and M.bars.target.owner == EB.A, EC.keys(W, row))
	check("enemybars: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- Every GUID withheld: the plate keeps its timers by unit frame, and the bar of the same player shares them.
	local W = EB.world({ setup = function(W)
		W.au.identityHidden = true
	end })
	local plate = EC.enemy(W, 1, { class = "MAGE", guid = EB.A })
	W.units.target = plate
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local M = EC.mod(W)
	local row = EB.bar(W, "target")
	local owner = M.bars.target.owner
	check("enemybars: with every GUID withheld, the bar and the plate share the timers kept by unit frame", type(owner) == "table" and owner == M.plates.nameplate1.owner and row == nil, tostring(owner))
	W.ns.Tracking.Book(owner, true).timers["MAGE:Counterspell"] = { start = W.now, seconds = 24 }
	W.ns.EnemyRender()
	row = EB.bar(W, "target")
	check("enemybars: a timer kept by unit frame shows on the bar and on the plate", row ~= nil and EC.keys(W, row) == "MAGE:Counterspell" and EC.keys(W, EC.row(W, plate)) == "MAGE:Counterspell", EC.keys(W, row))
	EC.leave(W, "nameplate1")
	check("enemybars: the bar has nothing once the plate has gone, and waits for a plate", EC.keys(W, row) == "" and M.bars.target.owner == nil and M.bars.target.pending == true and EC.ok(W), EC.why(W))
	check("enemybars: a bar that waits for a plate says so in one line", tostring(W.status()):find("a bar waits for the nameplate", 1, true) ~= nil, tostring(W.status()))
	W.units.nameplate1 = plate
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
	check("enemybars: a plate that comes back is found by the bar, with the timers kept by its unit frame lost", type(M.bars.target.owner) == "table" and EC.keys(W, row) == "" and EC.ok(W), tostring(M.bars.target.owner))
	W.combat = true
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("enemybars: a target change in combat builds and places the bar and breaks no rule of the client", EC.ok(W), EC.why(W))
	W.combat = false
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- Place: which rows show, and which handles are offered.
	local W = EB.world()
	local plate = EC.enemy(W, 1, { class = "MAGE", guid = EB.A })
	W.units.target = plate
	EB.used(W, EB.A, 2139, "MAGE")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
	local bar, own = EB.bar(W, "target"), EC.row(W, plate)
	check("enemybars: Both shows the plate and the bar, and offers both handles", EC.keys(W, own) == "MAGE:Counterspell" and EC.keys(W, bar) == "MAGE:Counterspell" and W.ns.EnemyTargetBarShown() == true and W.ns.EnemyFocusBarShown() == true)
	W.change("enemycd.place", "On enemy nameplates")
	local cast = EC.heard(W, "target")
	check("enemybars: On enemy nameplates shows the plate alone, offers no handle and does not listen to the target", EC.keys(W, own) == "MAGE:Counterspell" and EC.keys(W, bar) == "" and W.ns.EnemyTargetBarShown() == false and W.ns.EnemyFocusBarShown() == false and cast == false, EC.keys(W, bar))
	W.change("enemycd.place", "Bars for target and focus")
	cast = EC.heard(W, "target")
	check("enemybars: Bars for target and focus shows the bar alone, with both handles, and listens to the target", EC.keys(W, own) == "" and EC.keys(W, bar) == "MAGE:Counterspell" and W.ns.EnemyTargetBarShown() == true and W.ns.EnemyFocusBarShown() == true and cast == true, EC.keys(W, own))
	W.change("enemycd.place", "Both")
	check("enemybars: Both again shows them both", EC.keys(W, own) == "MAGE:Counterspell" and EC.keys(W, bar) == "MAGE:Counterspell")
	W.change("enemycd.enabled", false)
	check("enemybars: with the page off there is no bar, no handle and no listener", EC.keys(W, bar) == "" and W.ns.EnemyTargetBarShown() == false and EC.heard(W, "target") == false)
	W.change("enemycd.enabled", true)
	check("enemybars: and on again the bar is back", EC.keys(W, bar) == "MAGE:Counterspell" and EC.ok(W), EC.why(W))
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- The handles in /flatui move: a box of 200 by 30 with no icon shown, for each bar, while the gate is true.
	local mw, opt, entry, allClean, problems = suiteKit.mw, suiteKit.opt, suiteKit.entry, suiteKit.allClean, suiteKit.problems
	local W = mw()
	W.slash("move")
	local t, f = W.handle("Enemy cooldowns: target"), W.handle("Enemy cooldowns: focus")
	check("enemybars: each bar has a handle named for it, with no icon shown", t ~= nil and f ~= nil and t.shown and f.shown and #W.shownHandles() == 9 and next(EC.mod(W).rows) == nil, table.concat(W.shownHandles(), ","))
	local _, _, w, h = W.rectOf(t)
	local _, _, fw, fh = W.rectOf(f)
	local tl, tb, _ = W.rectOf(t)
	local fl, fb = W.rectOf(f)
	check("enemybars: the two handles start in different places, not on top of each other", not (tl < fl + fw and fl < tl + w and tb < fb + fh and fb < tb + h), tl .. " " .. tb .. " " .. fl .. " " .. fb)
	check("enemybars: the box is 200 by 30, for each bar", near(w, 200) and near(h, 30) and near(fw, 200) and near(fh, 30), tostring(w) .. " " .. tostring(h))
	W.slash("move")
	W.change("enemycd.place", "On enemy nameplates")
	W.slash("move")
	check("enemybars: On enemy nameplates offers neither", not (W.handle("Enemy cooldowns: target") or {}).shown and not (W.handle("Enemy cooldowns: focus") or {}).shown and #W.shownHandles() == 7, table.concat(W.shownHandles(), ","))
	W.slash("move")
	W.change("enemycd.place", "Bars for target and focus")
	W.slash("move")
	check("enemybars: Bars for target and focus offers both again", (W.handle("Enemy cooldowns: target") or {}).shown and (W.handle("Enemy cooldowns: focus") or {}).shown and #W.shownHandles() == 9, table.concat(W.shownHandles(), ","))
	W.slash("move")
	W.change("enemycd.enabled", false)
	W.slash("move")
	check("enemybars: with the page off there is none", #W.shownHandles() == 7 and allClean(W), problems(W))
	W.slash("move")
	-- Reset drops a saved spot and tells the bars.
	local R = mw({ saved = opt({}, { FlatUIEnemyTarget = { point = "TOPLEFT", x = 100, y = -200, kind = "hud" }, FlatUIEnemyFocus = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } }) })
	local told = 0
	local was = R.ns.EnemyBarsMoved
	R.ns.EnemyBarsMoved = function(...)
		told = told + 1
		return was(...)
	end
	check("enemybars: a spot saved for a bar is read back", entry(R, "FlatUIEnemyTarget") ~= nil and entry(R, "FlatUIEnemyTarget").x == 100)
	R.slash("move reset")
	check("enemybars: Reset drops both spots and tells the bars once for each", entry(R, "FlatUIEnemyTarget") == nil and entry(R, "FlatUIEnemyFocus") == nil and told == 2 and allClean(R), problems(R) .. told)
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- Where a bar hangs: above its frame until a spot is saved, then at the spot; Reset puts it back.
	local W = EB.world()
	EB.used(W, EB.A, 2139, "MAGE")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local row = EB.bar(W, "target")
	local p = EB.point(W, row)
	check("enemybars: a bar hangs from the top left corner of the target frame, the icon size and 4 units above it", p[1] == "TOPLEFT" and p[2] == W.env.TargetFrame and p[3] == "TOPLEFT" and p[4] == 0 and p[5] == 28, tostring(p[1]) .. " " .. tostring(p[5]))
	EB.used(W, EB.B, 1766, "ROGUE")
	EB.pick(W, "focus", { guid = EB.B, class = "ROGUE" })
	local q = EB.point(W, EB.bar(W, "focus"))
	check("enemybars: the focus bar hangs from the focus frame", q[2] == W.env.FocusFrame and q[3] == "TOPLEFT" and q[5] == 28)
	W.change("enemycd.size", 30)
	check("enemybars: Icon size moves the bar up with it", EB.point(W, row)[5] == 34, tostring(EB.point(W, row)[5]))
	W.change("enemycd.size", 24)
	local S = EB.world({ opts = { saved = { options = {}, movers = { FlatUIEnemyTarget = { point = "TOPLEFT", x = 100, y = -200, kind = "hud" } } } } })
	EB.used(S, EB.A, 2139, "MAGE")
	EB.pick(S, "target", { guid = EB.A, class = "MAGE" })
	local x, y = S.ns.MoverSpot("FlatUIEnemyTarget", "TOPLEFT")
	local sp = EB.point(S, EB.bar(S, "target"))
	check("enemybars: a saved spot wins over the frame: the top left of the bar is the top left of the box of the handle", sp[1] == "TOPLEFT" and sp[2] == S.env.UIParent and sp[3] == "BOTTOMLEFT" and near(sp[4], x) and near(sp[5], y) and x ~= nil, tostring(sp[4]) .. " " .. tostring(x))
	EB.used(S, EB.B, 1766, "ROGUE")
	EB.pick(S, "focus", { guid = EB.B, class = "ROGUE" })
	check("enemybars: and the focus bar, with no spot of its own, stays above its frame", EB.point(S, EB.bar(S, "focus"))[2] == S.env.FocusFrame)
	S.ns.Spots().FlatUIEnemyTarget = nil
	S.ns.EnemyBarsMoved()
	local rp = EB.point(S, EB.bar(S, "target"))
	check("enemybars: with the spot gone the bar is above its frame again", rp[2] == S.env.TargetFrame and rp[3] == "TOPLEFT" and rp[5] == 28 and S.ns.Spots().FlatUIEnemyTarget == nil, tostring(rp[2]) .. " " .. tostring(rp[5]))
	local N = EB.world({ noFrames = true })
	EB.used(N, EB.A, 2139, "MAGE")
	EB.pick(N, "target", { guid = EB.A, class = "MAGE" })
	local np = EB.point(N, EB.bar(N, "target"))
	local X = EB.world({ opts = { saved = { options = {}, movers = { FlatUIEnemyTarget = { point = "NOWHERE", x = 1, y = 2 } } } } })
	EB.used(X, EB.A, 2139, "MAGE")
	EB.pick(X, "target", { guid = EB.A, class = "MAGE" })
	check("enemybars: a saved spot the movers reject leaves the bar above its frame", EB.point(X, EB.bar(X, "target"))[2] == X.env.TargetFrame, tostring(EB.point(X, EB.bar(X, "target"))[2]))
	check("enemybars: with no target frame the bar hangs from the middle of the screen, and nothing raises", np[1] == "CENTER" and np[2] == N.env.UIParent and EC.ok(N), EC.why(N))
	check("enemybars: nothing in this section broke a rule of the client", EC.ok(W) and EC.ok(S), EC.why(W) .. EC.why(S))
end
do
	local EC, EB = TOC.ec, TOC.eb
	-- A bar has eight icons at most; a plate has four.
	local W = EB.world()
	for _, name in ipairs({ "interrupts", "defensives", "breaks", "wards", "mobility", "offensive" }) do
		W.change("enemycd." .. name, true)
	end
	local M = EC.mod(W)
	local book = W.ns.Tracking.Book(EB.A, true)
	local made = 0
	for _, a in ipairs(W.ns.ABILITIES) do
		if made < 10 and M.Rank(a) then
			book.timers[a.key] = { start = W.now, seconds = 60 }
			made = made + 1
		end
	end
	local plate = EC.enemy(W, 1, { class = "MAGE", guid = EB.A })
	W.units.target = plate
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local row = EB.bar(W, "target")
	local shown = 0
	for _, icon in ipairs(row.icons) do
		shown = shown + (W.rawOf[icon.frame].shown == true and 1 or 0)
	end
	check("enemybars: ten timers make eight icons on the bar and not a ninth", made == 10 and #row.icons == 8 and shown == 8, made .. " " .. #row.icons .. " " .. shown)
	check("enemybars: the plate of the same player still has four", #EC.row(W, plate).icons == 4)
	check("enemybars: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB = TOC.ec, TOC.eb
