-- >>> arena (begin)
-- The crowd control break of an arena opponent on the target and focus bars. The helpers are on TOC.ar, so that this file gains no local.
do
	local EC, EB = TOC.ec, TOC.eb
	local AR = {}
	TOC.ar = AR
	-- A world in an arena (o.arena = false for none): C_PvP.GetArenaCrowdControlDuration answers an opaque object that reads nothing,
	-- o.raise makes it raise, o.noCall leaves it out. The target is arena2 and the focus arena1 (st.opponent). st counts the calls.
	function AR.world(o)
		o = o or {}
		local st = { calls = {}, same = 0, objects = {}, textures = {}, reads = 0 }
		local W = EB.world({ opts = o.opts, setup = function(W)
			W.au.arena = o.arena ~= false
			W.env.C_PvP = { IsArena = o.isArena and function() return true end or nil }
			if not o.noCall then
				W.env.C_PvP.GetArenaCrowdControlDuration = function(unit)
					st.calls[#st.calls + 1] = unit
					if o.raise then
						error("refused", 0)
					end
					if not st.objects[unit] then
						local object = setmetatable({}, { __index = function() st.reads = st.reads + 1 end })
						W.durations[object] = { kind = "arena", unit = unit }
						st.objects[unit] = object
					end
					return st.objects[unit]
				end
			end
			if o.setup then
				o.setup(W)
			end
		end })
		st.opponent = { target = "arena2", focus = "arena1" }
		W.env.UnitIsUnit = function(a, b)
			if type(b) == "string" and b:find("^arena") then
				st.same = st.same + 1
			end
			if W.sameFault == "secret" then
				return SECRET
			end
			return st.opponent[a] == b
		end
		local picture = W.env.C_Spell.GetSpellTexture
		W.env.C_Spell.GetSpellTexture = function(id)
			st.textures[#st.textures + 1] = id
			if id == 11111 then
				return 4242
			end
			return picture(id)
		end
		AR.st = st
		return W, st
	end
	-- The shown state of the slot of a bar's row, and its sweep.
	function AR.slot(W, unit, slot)
		local row = EB.bar(W, unit)
		local icon = row and row.icons[slot]
		return icon and W.rawOf[icon.frame].shown == true, icon and W.rawOf[icon.cooldown].cd.sweep, icon
	end
	function AR.shown(W, unit)
		local row = EB.bar(W, unit)
		for slot = 1, row and #row.icons or 0 do
			if W.rawOf[row.icons[slot].frame].shown == true then
				return true
			end
		end
		return false
	end
	function AR.check(W)
		return table.concat(W.ns.CheckLines(), "\n")
	end
end
do
	local EC, EB, AR = TOC.ec, TOC.eb, TOC.ar
	-- In an arena the target that is an opponent has the break on its bar.
	local W, st = AR.world()
	check("arena: the setting starts on, and is in the page", W.ns.Get("enemycd.arenaBreak") == true and W.control("enemycd.arenaBreak") ~= nil)
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local shown, sweep = AR.slot(W, "target", 1)
	check("arena: the target that is arena2 has one icon on its bar, with the sweep set from the game's duration object, passed on unread",
		shown == true and sweep ~= nil and sweep.kind == "object" and sweep.object == st.objects.arena2 and st.calls[1] == "arena2" and st.reads == 0 and EC.ok(W), EC.why(W))
	local _, _, icon = AR.slot(W, "target", 1)
	check("arena: it has no border by kind and no ready alert", icon.look.kind == nil and icon.look.flash == nil and icon.look.sound == nil and icon.key == nil)
	local row = EB.bar(W, "target")
	check("arena: the icon is of the bar's own pool, the second slot is not made", #row.icons == 1 and EC.keys(W, row) == "")
	-- The picture is the one of the spell ID the game names, handed on unread.
	W.fire("ARENA_CROWD_CONTROL_SPELL_UPDATE", "arena2", 11111)
	check("arena: the spell ID goes unread to C_Spell.GetSpellTexture and its answer is the picture of the icon", st.textures[#st.textures] == 11111
		and W.rawOf[icon.texture].file == 4242 and EC.ok(W), tostring(W.rawOf[icon.texture].file))
	check("arena: a picture for another opponent leaves this icon's picture as it was", (function()
		W.fire("ARENA_CROWD_CONTROL_SPELL_UPDATE", "arena3", 22222)
		return W.rawOf[icon.texture].file == 4242
	end)())
	-- With timers, the break is the slot after them.
	EB.used(W, EB.A, 2139, "MAGE")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	local second = AR.slot(W, "target", 2)
	check("arena: with a cooldown on the bar the break is the icon after it", EC.keys(W, row) == "MAGE:Counterspell" and second == true and select(2, AR.slot(W, "target", 2)).object == st.objects.arena2)
	-- The focus bar: opponent arena1.
	EB.pick(W, "focus", { guid = EB.B, class = "ROGUE" })
	local fshown, fsweep = AR.slot(W, "focus", 1)
	check("arena: the focus bar shows the break of arena1", fshown == true and fsweep ~= nil and fsweep.object == st.objects.arena1)
	check("arena: the check says Arena: yes and the break is shown", has(AR.check(W), "Arena: yes.") and has(AR.check(W), "Arena crowd control break: shown."), AR.check(W))
	-- A target that is not an opponent has none.
	st.opponent.target = nil
	EB.pick(W, "target", { guid = EB.B, class = "ROGUE" })
	check("arena: a target that is no opponent has no break and the bar has only its own icons", EC.keys(W, row) == "" and AR.shown(W, "target") == false)
	-- The setting off, and on again.
	st.opponent.target = "arena2"
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: the opponent again shows it", AR.slot(W, "target", 2) == true)
	W.change("enemycd.arenaBreak", false)
	check("arena: with the setting off the break is gone from both bars and the check says off", AR.slot(W, "target", 2) == false and AR.shown(W, "focus") == false
		and EC.keys(W, row) == "MAGE:Counterspell" and has(AR.check(W), "Arena crowd control break: off."), AR.check(W))
	local before = #st.calls
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: and the game is not asked for a duration", #st.calls == before)
	W.change("enemycd.arenaBreak", true)
	check("arena: turned on it shows again", AR.slot(W, "target", 2) == true and EC.ok(W), EC.why(W))
	W.change("enemycd.place", "On enemy nameplates")
	check("arena: with Place on enemy nameplates only there is no bar and so no break", AR.shown(W, "target") == false and EC.ok(W), EC.why(W))
	W.change("enemycd.place", "Both")
	check("arena: and Both brings it back", AR.slot(W, "target", 2) == true, EC.keys(W, row))
	-- Leaving the arena takes it away.
	W.au.arena = false
	W.fire("ZONE_CHANGED_NEW_AREA")
	check("arena: leaving the arena hides the icon on both bars and the check says Arena: no", AR.slot(W, "target", 2) == false and AR.shown(W, "focus") == false
		and has(AR.check(W), "Arena: no.") and not has(AR.check(W), "Arena crowd control break"), AR.check(W))
	local calls, same = #st.calls, st.same
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	W.fire("ARENA_COOLDOWNS_UPDATE")
	W.fire("ARENA_CROWD_CONTROL_SPELL_UPDATE", "arena2", 11111)
	check("arena: outside an arena no call is made for the duration and no opponent is looked up", #st.calls == calls and st.same == same and AR.shown(W, "target") == false and AR.shown(W, "focus") == false, #st.calls .. " " .. calls .. " " .. st.same .. " " .. same)
	W.au.arena = true
	EB.used(W, EB.A, 2139, "MAGE")
	W.fire("ARENA_OPPONENT_UPDATE")
	check("arena: a new opponent list in an arena shows it again", AR.slot(W, "target", 2) == true, EC.keys(W, row))
	check("arena: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB, AR = TOC.ec, TOC.eb, TOC.ar
	-- The game's call raises: no icon, one line.
	local W, st = AR.world({ raise = true })
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: a raising GetArenaCrowdControlDuration leaves the icon out", AR.shown(W, "target") == false and #st.calls >= 1 and EC.ok(W), EC.why(W))
	check("arena: and the status has the one line", select(2, W.status():gsub("Crowd control break in arenas: the game refused the arena call%.", "")) == 1, W.status())
	check("arena: and the check says refused by the game", has(AR.check(W), "Arena crowd control break: refused by the game."), AR.check(W))
	-- A client without the call.
	local N = AR.world({ noCall = true })
	EB.pick(N, "target", { guid = EB.A, class = "MAGE" })
	check("arena: without the call the feature is off and the check says Arena: yes with no break line", AR.shown(N, "target") == false and not has(N.status(), "Crowd control break in arenas") and not has(AR.check(N), "Arena crowd control break"))
	-- A raising arena call.
	local R = AR.world({ arena = false, setup = function(R)
		R.env.IsActiveBattlefieldArena = function() error("refused", 0) end
	end })
	check("arena: a raising IsActiveBattlefieldArena is told in the status and shows no icon", has(R.status(), "Crowd control break in arenas: the game refused the arena call.") and AR.shown(R, "target") == false)
	-- C_PvP.IsArena alone is enough.
	local P = AR.world({ arena = false, isArena = true })
	EB.pick(P, "target", { guid = EB.A, class = "MAGE" })
	check("arena: C_PvP.IsArena answering true turns it on and the check says so", AR.slot(P, "target", 1) == true and has(AR.check(P), "Arena: yes."), AR.check(P))
	check("arena: nothing in this section broke a rule of the client", EC.ok(W) and EC.ok(N) and EC.ok(P), EC.why(P))
end
do
	local EC, EB, AR = TOC.ec, TOC.eb, TOC.ar
	-- A withheld UnitIsUnit answer maps nothing.
	local W, st = AR.world({ setup = function(W)
		W.sameFault = "secret"
	end })
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: a withheld UnitIsUnit answer maps the bar to no opponent: no icon, no duration asked", AR.shown(W, "target") == false and #st.calls == 0 and EC.ok(W), EC.why(W))
	check("arena: and the check says the opponent is not known", has(AR.check(W), "Arena crowd control break: opponent not known."), AR.check(W))
	W.sameFault = nil
	W.fire("ARENA_OPPONENT_UPDATE")
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: answered again, it shows", AR.slot(W, "target", 1) == true)
	-- No opponent targeted in an arena.
	st.opponent.target, st.opponent.focus = nil, nil
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	EB.pick(W, "focus", { guid = EB.B, class = "ROGUE" })
	check("arena: a target that is no opponent says so in the check", has(AR.check(W), "Arena crowd control break: no opponent targeted."), AR.check(W))
	check("arena: nothing in this section broke a rule of the client", EC.ok(W), EC.why(W))
end
do
	local EC, EB, AR = TOC.ec, TOC.eb, TOC.ar
	-- Combat, and the page off.
	local W, st = AR.world()
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	W.beginFight()
	W.fire("ARENA_COOLDOWNS_UPDATE")
	W.fire("ARENA_CROWD_CONTROL_SPELL_UPDATE", "arena2", 11111)
	local shown, sweep, icon = AR.slot(W, "target", 1)
	check("arena: in combat the break is drawn again from the new duration object with no rule broken", shown == true and sweep.object == st.objects.arena2 and W.rawOf[icon.texture].file == 4242 and EC.ok(W), EC.why(W))
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: and a change of target in combat keeps it", AR.slot(W, "target", 1) == true)
	W.endFight()
	W.change("enemycd.enabled", false)
	check("arena: with the page off nothing of it is shown", AR.shown(W, "target") == false and AR.shown(W, "focus") == false and EC.ok(W), EC.why(W))
	W.change("enemycd.enabled", true)
	EB.pick(W, "target", { guid = EB.A, class = "MAGE" })
	check("arena: turned on again it is back", AR.slot(W, "target", 1) == true and EC.ok(W), EC.why(W))
	-- A reload: the world is made again in the arena, nothing is kept.
	local V = AR.world()
	EB.pick(V, "target", { guid = EB.A, class = "MAGE" })
	check("arena: after a reload in an arena the target's bar has it", AR.slot(V, "target", 1) == true and EC.ok(V), EC.why(V))
end
-- >>> arena (end)
-- >>> ms-plates (begin)
-- Nameplate bars, width, friendly plates, raid marker and aura icons (ms-04). Every label starts "ms-plates:". The values are kept in one table: the
-- main function of this file has a limit on the locals alive at once. The plates are those of the older world, with the parts these rows touch
-- added: the heal and absorb art, the behind-you arrow, the raid marker, the game's anchors for the cast container and the marker, a fill.
do
	local M = {}
	M.ARTS = { "myHealPrediction", "otherHealPrediction", "totalAbsorb", "totalAbsorbOverlay", "overAbsorbGlow", "myHealAbsorb", "myHealAbsorbLeftShadow",
		"myHealAbsorbRightShadow", "overHealAbsorbGlow" }
	function M.world(options, setup)
		local W = newWorld({ saved = options and { options = options } or nil })
		setup = setup or {}
		W.env.NamePlateSetupOptions = { horizontalScale = 1, verticalScale = 1, insetWidth = 12, healthBarHeight = 13, castBarHeight = 6, castIconHeight = 10,
			useClassicHealthBar = setup.classic or false, useClassicCastBar = setup.classic or false }
		W.env.NamePlateConstants = { NAME_PLATE_WIDTH = 190 }
		if setup.base then
			W.env.NamePlateDriverFrame = { baseNamePlateWidth = setup.base }
		end
		W.login()
		return W
	end
	-- o.friend: isFriend of the unit frame. o.unit. The calls the addon makes on the cast container and the marker are in plate.calls.
	function M.plate(W, o)
		o = o or {}
		local plate = W.newPlate()
		W.group = "nameplate"
		local inner, hb, uf = plate.inner, plate.healthInner, plate.UnitFrame
		plate.art = {}
		for _, key in ipairs(M.ARTS) do
			local proxy, raw = W.Rr(nil, nil)
			hb[key] = proxy
			plate.art[key] = raw
		end
		local fill, fillRaw = W.Rr(nil, nil)
		hb.barTexture, plate.fill = fill, fillRaw
		hb.GetStatusBarColor = function() return 0.2, 0.4, 0.6, 1 end
		hb.SetStatusBarColor = function() end
		local camera, cameraRaw = W.Rr(nil, nil)
		local icon, iconRaw = W.Rr(nil, nil)
		local marker, markerRaw = W.B(nil, { RaidTargetIcon = icon }, { width = 22, height = 22 })
		inner.behindCameraIcon, inner.RaidTargetFrame = camera, marker
		inner.unit, inner.isFriend, inner.isTarget = o.unit or "nameplate1", o.friend, o.target
		plate.camera, plate.icon, plate.marker = cameraRaw, iconRaw, markerRaw
		local cc, hc = uf.CastBarsContainer, uf.HealthBarsContainer
		local ccRaw = W.rawOf[cc]
		plate.cc, plate.calls = ccRaw, {}
		for _, pair in ipairs({ { ccRaw, "cast" }, { markerRaw, "marker" } }) do
			for _, name in ipairs({ "SetPoint", "SetSize" }) do
				local original = pair[1][name]
				pair[1][name] = function(self, ...)
					if W.inBlizzard == 0 or (W.inHook or 0) > 0 then
						plate.calls[#plate.calls + 1] = { part = pair[2], call = name, combat = W.combat, n = select("#", ...), ... }
						if plate.fault and plate.fault[pair[2] .. name] then
							error(name .. " failed", 0)
						end
					end
					return original(self, ...)
				end
			end
		end
		-- The game's own anchors, as UpdateAnchors sets them.
		local function game()
			ccRaw.ClearAllPoints(cc)
			ccRaw.SetPoint(cc, "BOTTOMLEFT", uf, "BOTTOMLEFT", 12, 0)
			ccRaw.SetPoint(cc, "BOTTOMRIGHT", uf, "BOTTOMRIGHT", -12, 0)
			markerRaw.ClearAllPoints(marker)
			if inner.showOnlyName then
				markerRaw.SetPoint(marker, "BOTTOM", plate.healthBar, "TOP", 0, 10)
			else
				markerRaw.SetPoint(marker, "RIGHT", hc, "LEFT", 0, 0)
			end
		end
		W.blizzard(game)
		inner.UpdateAnchors = function() W.blizzard(game) end
		function plate.update()
			W.gameOptions()
			W.flush()
		end
		function plate.cast()
			return ccRaw.points[1][4] .. "/" .. ccRaw.points[2][4]
		end
		function plate.mine(part)
			local n = 0
			for _, c in ipairs(plate.calls) do
				if part == nil or c.part == part then
					n = n + 1
				end
			end
			return n
		end
		W.group = "static"
		W.seal()
		return plate
	end
	function M.aura(W, plate)
		local rec = W.addAura(plate)
		W.group = "nameplate"
		local cdProxy, cd = W.B(nil, {})
		cd.hide, cd.sets = false, 0
		cd.SetHideCountdownNumbers = function(_, value) cd.hide, cd.sets = value, cd.sets + 1 end
		cd.GetHideCountdownNumbers = function() return cd.hide end
		local countProxy, count = W.Rr(nil, nil)
		local frameProxy = W.B(nil, { Count = countProxy })
		rec.inner.Cooldown, rec.inner.CountFrame = cdProxy, frameProxy
		rec.cd, rec.count = cd, count
		W.group = "static"
		W.seal()
		return rec
	end
	function M.art(plate, keys)
		local out = {}
		for _, key in ipairs(keys) do
			out[#out + 1] = g(plate.art[key].alpha)
		end
		return table.concat(out, ",")
	end
	function M.shown(W, unit, o)
		o = o or {}
		o.unit = unit or o.unit
		local plate = M.plate(W, o)
		W.showPlate(o.unit or "nameplate1", plate)
		W.flush()
		return plate
	end
	-- The art alphas of a plate the addon never styled.
	M.NEVER = "bg=1 sel=1 over=1 | lvl=1,1 | cast=1,1 | H:. L:. C:."

	-- The rows: the saved paths, the defaults, which row needs which, and the choices.
	do
		local W = M.world()
		local want = { friendly = true, healthTexture = "default", barWidth = 100, dimAmount = 100, healPrediction = true, absorbs = true, healAbsorbs = true,
			castTexture = "default", raidMarker = true, raidMarkerSize = 22, raidMarkerX = 0, raidMarkerY = 0, offscreenIcon = true, auraCrop = 8, auraBorderOwn = false,
			auraBorderColour = "ff000000", auraTimers = true, auraStacks = true, auraOpacity = 100, aurasWhen = "always" }
		local bad = {}
		for key, value in pairs(want) do
			if W.ns.Get("nameplates." .. key) ~= value then
				bad[#bad + 1] = key .. "=" .. tostring(W.ns.Get("nameplates." .. key))
			end
		end
		table.sort(bad)
		check("ms-plates: every new row starts at the game's own look", #bad == 0, table.concat(bad, " "))
		local rows = {}
		for _, page in ipairs(W.ns.PAGES) do
			for _, row in ipairs(page) do
				if row.key then
					rows[page.key .. "." .. row.key] = row
				end
			end
		end
		check("ms-plates: the rows that need another name it", rows["nameplatesHealth.healthTexture"].needs == "healthFlat" and rows["nameplatesHealth.dimAmount"].needs == "dim"
			and rows["nameplatesCast.castTexture"].needs == "castFlat" and rows["nameplatesAuras.auraCrop"].needs == "auras" and rows["nameplatesAuras.auraBorderOwn"].needs == "auras"
			and rows["nameplatesAuras.auraBorderColour"].needs == "auraBorderOwn" and rows["nameplates.friendly"].needs == nil and rows["nameplatesHealth.barWidth"].needs == nil)
		check("ms-plates: the ranges", rows["nameplatesHealth.barWidth"].min == 50 and rows["nameplatesHealth.barWidth"].max == 100 and rows["nameplatesHealth.barWidth"].step == 5
			and rows["nameplatesHealth.dimAmount"].min == 10 and rows["nameplatesHealth.dimAmount"].max == 100 and rows["nameplatesHealth.dimAmount"].step == 10
			and rows["nameplatesMarks.raidMarkerSize"].min == 8 and rows["nameplatesMarks.raidMarkerSize"].max == 48 and rows["nameplatesMarks.raidMarkerX"].min == -40
			and rows["nameplatesMarks.raidMarkerY"].max == 40 and rows["nameplatesAuras.auraCrop"].min == 0 and rows["nameplatesAuras.auraCrop"].max == 15
			and rows["nameplatesAuras.auraOpacity"].min == 10 and rows["nameplatesAuras.auraOpacity"].step == 10)
		check("ms-plates: the texture rows offer the Flat UI page's texture first, and Show auras two choices", W.ns.Choices(rows["nameplatesHealth.healthTexture"])[1][1] == "default"
			and #W.ns.Choices(rows["nameplatesCast.castTexture"]) == 11 and #rows["nameplatesAuras.aurasWhen"].choices == 2 and rows["nameplatesAuras.aurasWhen"].choices[2][1] == "target")
		check("ms-plates: the cast bar texture row reaches the same texture function as the Flat UI page", W.ns.BarTexture(W.ns.Get("nameplates.castTexture")) == W.ns.BarTexture()
			and W.ns.BarTexture("soft") == W.ns.BarFile("soft"))
		clean(W, "ms-plates rows")
	end

	-- The defaults make no call on any plate, and a plate with its rows at the defaults is as the game has it.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		local rec = M.aura(W, a)
		W.fire("UNIT_AURA", "nameplate1")
		W.flush()
		local fades = 0
		for _, key in ipairs(M.ARTS) do
			fades = fades + (a.art[key].calls.SetAlpha or 0)
		end
		check("ms-plates: at the defaults nothing is called on the art, the arrow, the marker, the container, the aura frame or the aura parts",
			fades == 0 and (a.camera.calls.SetAlpha or 0) == 0 and (a.icon.calls.SetAlpha or 0) == 0 and #a.calls == 0 and a.marker.width == 22 and a.marker.height == 22
			and (a.aurasInner.calls.SetAlpha or 0) == 0 and rec.cd.sets == 0 and (rec.count.calls.SetAlpha or 0) == 0, tostring(fades) .. " " .. #a.calls)
		check("ms-plates: and the plate is styled as before, with the overlay faded", plateLine(W, a) == ON and auraLine(rec) == AURA_ON, plateLine(W, a))
		clean(W, "ms-plates defaults")
	end

	-- Heal prediction, absorbs, heal absorbs, the arrow and the raid marker: each switch fades its own regions and no other.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		local groups = { healPrediction = { "myHealPrediction", "otherHealPrediction" }, absorbs = { "totalAbsorb", "totalAbsorbOverlay", "overAbsorbGlow" },
			healAbsorbs = { "myHealAbsorb", "myHealAbsorbLeftShadow", "myHealAbsorbRightShadow", "overHealAbsorbGlow" } }
		local order = { "healPrediction", "absorbs", "healAbsorbs" }
		for _, key in ipairs(order) do
			W.change("nameplates." .. key, false)
			W.flush()
			local faded, others = M.art(a, groups[key]), {}
			for _, other in ipairs(order) do
				if other ~= key then
					others[#others + 1] = M.art(a, groups[other])
				end
			end
			check("ms-plates: " .. key .. " off fades its regions only", not faded:find("1") and not table.concat(others, ","):find("0"), faded .. " | " .. table.concat(others, " "))
			W.change("nameplates." .. key, true)
			W.flush()
			check("ms-plates: " .. key .. " on again brings them back", not M.art(a, groups[key]):find("0"), M.art(a, groups[key]))
		end
		W.change("nameplates.offscreenIcon", false)
		check("ms-plates: Arrow for nameplates behind you off fades the arrow", a.camera.alpha == 0 and a.icon.alpha == 1)
		W.change("nameplates.offscreenIcon", true)
		W.change("nameplates.raidMarker", false)
		check("ms-plates: Raid marker off fades the marker's icon, and the arrow is back", a.icon.alpha == 0 and a.camera.alpha == 1 and a.marker.alpha == 1)
		W.change("nameplates.raidMarker", true)
		check("ms-plates: and the marker on again", a.icon.alpha == 1)
		-- The module off or stopped puts every one back.
		for _, key in ipairs({ "healPrediction", "absorbs", "healAbsorbs", "offscreenIcon", "raidMarker" }) do
			W.change("nameplates." .. key, false)
		end
		W.change("nameplates.enabled", false)
		W.flush()
		local all = {}
		for _, key in ipairs(M.ARTS) do
			all[#all + 1] = g(a.art[key].alpha)
		end
		check("ms-plates: with the page off every region is back as the game has it", not table.concat(all, ","):find("0") and a.camera.alpha == 1 and a.icon.alpha == 1, table.concat(all, ","))
		W.change("nameplates.enabled", true)
		W.flush()
		check("ms-plates: and the page on again fades them again", a.camera.alpha == 0 and a.icon.alpha == 0 and M.art(a, groups.absorbs) == "0,0,0")
		clean(W, "ms-plates art")
	end

	-- Dim strength.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		local over = a.healthBar.deselectedOverlay
		check("ms-plates: the overlay is faded while Dim other nameplates is off, whatever Dim strength says", over.alpha == 0)
		W.change("nameplates.dimAmount", 40)
		check("ms-plates: Dim strength alone changes nothing", over.alpha == 0)
		W.change("nameplates.dim", true)
		check("ms-plates: Dim other nameplates on at 40 percent: the overlay is 0.4", near(over.alpha, 0.4), over.alpha)
		W.change("nameplates.dimAmount", 100)
		check("ms-plates: at 100 percent it is the game's own, fully shown", over.alpha == 1)
		W.change("nameplates.dimAmount", 70)
		W.change("nameplates.health", false)
		check("ms-plates: with the border off the overlay is the game's, whatever the strength", over.alpha == 1)
		W.change("nameplates.health", true)
		W.change("nameplates.dim", false)
		check("ms-plates: Dim other nameplates off again fades it", over.alpha == 0)
		clean(W, "ms-plates dim")
	end

	-- Health bar texture: the file of the chosen texture, the Flat UI page's by default.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		check("ms-plates: the default texture is the Flat UI page's, a plain colour for Flat", a.fill.color ~= nil and a.fill.file == nil, tostring(a.fill.file))
		W.change("nameplates.healthTexture", "Soft shade")
		check("ms-plates: Health bar texture Soft shade sets that file", a.fill.file == W.ns.BarFile("soft"), tostring(a.fill.file))
		W.change("general.barTexture", "Gloss")
		check("ms-plates: the row wins over the Flat UI page", a.fill.file == W.ns.BarFile("soft"), tostring(a.fill.file))
		W.change("nameplates.healthTexture", "Same as the Flat UI page")
		check("ms-plates: and back to the Flat UI page's texture", a.fill.file == W.ns.BarFile("gloss"), tostring(a.fill.file))
		clean(W, "ms-plates texture")
	end

	-- Bar width.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		W.change("nameplates.barWidth", 70)
		W.flush()
		check("ms-plates: Bar width 70 moves both sides of the cast container in by 24.9 beyond the game's 12", near(a.cc.points[1][4], 36.9, 1e-6) and near(a.cc.points[2][4], -36.9, 1e-6)
			and a.cc.points[1][2] == a.UnitFrame and a.cc.points[1][1] == "BOTTOMLEFT" and a.cc.points[2][1] == "BOTTOMRIGHT" and a.cc.points[1][5] == 0, a.cast())
		a.update()
		check("ms-plates: when the game lays the plate out again the width is set again after it", near(a.cc.points[1][4], 36.9, 1e-6) and near(a.cc.points[2][4], -36.9, 1e-6), a.cast())
		W.change("nameplates.barWidth", 50)
		check("ms-plates: Bar width 50 is 12 plus 41.5 on each side", near(a.cc.points[1][4], 53.5, 1e-6), a.cast())
		local before = a.mine("cast")
		W.change("nameplates.barWidth", 100)
		check("ms-plates: back at 100 the game's two anchors are set once", a.cast() == "12/-12" and a.mine("cast") == before + 2, a.cast() .. " " .. (a.mine("cast") - before))
		before = a.mine("cast")
		a.update()
		W.change("nameplates.healthFlat", false)
		W.change("nameplates.healthFlat", true)
		check("ms-plates: at 100 no pass of the game or change of another row sets an anchor", a.mine("cast") == before and a.cast() == "12/-12", a.mine("cast") - before)
		clean(W, "ms-plates width")

		-- The driver's own width, when it has one.
		local D = M.world(nil, { base = 200 })
		local d = M.shown(D, "nameplate1", { friend = false })
		D.change("nameplates.barWidth", 70)
		check("ms-plates: with a width of its own the driver's number is used: 200 gives 12 plus 26.4", near(d.cc.points[1][4], 38.4, 1e-6), d.cast())
		clean(D, "ms-plates width driver")

		-- The Classic style is left alone.
		local K = M.world({ ["nameplates.barWidth"] = 60 }, { classic = true })
		local k = M.shown(K, "nameplate1", { friend = false })
		check("ms-plates: in the Classic style the width is not changed", k.mine("cast") == 0 and k.cast() == "12/-12")
		clean(K, "ms-plates width classic")

		-- In combat the width waits for the end of it.
		local C = M.world()
		local c = M.shown(C, "nameplate1", { friend = false })
		C.combat = true
		C.change("nameplates.barWidth", 80)
		C.flush()
		check("ms-plates: in combat no anchor is set, and the status says the plates wait", c.cast() == "12/-12" and c.mine("cast") == 0 and has(C.status(), "Bar width: nameplates that appear in combat get it when combat ends"), C.status())
		C.combat = false
		C.fire("PLAYER_REGEN_ENABLED")
		C.flush()
		check("ms-plates: when combat ends the width is set", near(c.cc.points[1][4], 12 + 0.1 * 166, 1e-6) and c.calls[#c.calls].combat == false, c.cast())
		clean(C, "ms-plates width combat")

		-- A refused call stops the part, puts the game's width back and says so.
		local F = M.world({ ["nameplates.barWidth"] = 70 })
		local plates = {}
		for i = 1, 4 do
			plates[i] = M.plate(F, { friend = false, unit = "nameplate" .. i })
			plates[i].fault = { castSetPoint = i <= 3 }
		end
		for i = 1, 4 do
			F.showPlate("nameplate" .. i, plates[i])
		end
		F.flush()
		check("ms-plates: a width that cannot be set on three plates stops that part, and the status says so", has(F.status(), "bar width stopped"), F.status())
		plates[4].fault = nil
		check("ms-plates: and the fourth plate is put back to the game's width", plates[4].cast() == "12/-12", plates[4].cast())
		check("ms-plates: the other parts go on", plateLine(F, plates[4]) == ON and #F.errors == 0 and #F.violations == 0, plateLine(F, plates[4]))
	end

	-- Raid marker: size and offsets.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		W.change("nameplates.raidMarkerSize", 30)
		check("ms-plates: Raid marker size 30 sets the marker's size", a.marker.width == 30 and a.marker.height == 30 and a.mine("marker") == 1)
		check("ms-plates: and not its place", a.marker.points[1][1] == "RIGHT" and a.marker.points[1][4] == 0 and a.mine("marker") == 1)
		W.change("nameplates.raidMarkerX", 6)
		W.change("nameplates.raidMarkerY", -4)
		local p = a.marker.points[1]
		check("ms-plates: the offsets are added to the game's anchor: right of the health bar's left side, 6 and -4", #a.marker.points == 1 and p[1] == "RIGHT" and p[3] == "LEFT" and p[4] == 6 and p[5] == -4
			and p[2] == a.UnitFrame.HealthBarsContainer, tostring(p[4]) .. "," .. tostring(p[5]))
		a.update()
		p = a.marker.points[1]
		check("ms-plates: when the game lays the plate out again they are added again, and not twice", p[4] == 6 and p[5] == -4 and a.marker.width == 30, tostring(p[4]) .. "," .. tostring(p[5]))
		a.inner.showOnlyName = true
		a.update()
		p = a.marker.points[1]
		check("ms-plates: in name-only mode the game's anchor above the name is left alone", p[1] == "BOTTOM" and p[4] == 0 and p[5] == 10, p[1] .. tostring(p[4]) .. "," .. tostring(p[5]))
		a.inner.showOnlyName = nil
		a.update()
		W.change("nameplates.raidMarkerX", 0)
		W.change("nameplates.raidMarkerY", 0)
		W.change("nameplates.raidMarkerSize", 22)
		p = a.marker.points[1]
		check("ms-plates: back at the defaults the size and the anchor are the game's", a.marker.width == 22 and a.marker.height == 22 and p[1] == "RIGHT" and p[4] == 0 and p[5] == 0 and #a.marker.points == 1,
			tostring(p[4]) .. "," .. tostring(p[5]))
		local before = a.mine("marker")
		a.update()
		W.change("nameplates.raidMarker", false)
		W.change("nameplates.raidMarker", true)
		check("ms-plates: and from then on nothing is called on the marker", a.mine("marker") == before, a.mine("marker") - before)
		-- In combat the marker waits.
		local C = M.world({ ["nameplates.raidMarkerSize"] = 30, ["nameplates.raidMarkerX"] = 5 })
		C.combat = true
		local c = M.shown(C, "nameplate1", { friend = false })
		check("ms-plates: a plate that appears in combat has its marker as the game made it", c.mine("marker") == 0 and c.marker.width == 22 and c.marker.points[1][4] == 0)
		C.combat = false
		C.fire("PLAYER_REGEN_ENABLED")
		C.flush()
		check("ms-plates: and gets the size and the offset when combat ends", c.marker.width == 30 and c.marker.points[1][4] == 5, c.marker.width)
		clean(C, "ms-plates marker combat")
		check("ms-plates: a marker waiting for combat is named in the status", has(C.status(), "Raid marker: nameplates that appear in combat get it when combat ends") and not has(C.status(), "Bar height"), C.status())
		do
			local R = M.world({ ["nameplates.raidMarkerX"] = 5 })
			local r = M.shown(R, "nameplate1", { friend = false })
			check("ms-plates: a plate with an offset shown out of combat has it", r.marker.points[1][4] == 5, r.marker.points[1][4])
			R.combat = true
			r.update()
			R.combat = false
			R.fire("PLAYER_REGEN_ENABLED")
			R.flush()
			check("ms-plates: the game laying it out again in combat does not lose the offset when combat ends", r.marker.points[1][4] == 5, r.marker.points[1][4])
		end
		-- A marker call that fails stops the part and puts the marker back.
		local F = M.world({ ["nameplates.raidMarkerSize"] = 30 })
		local plates = {}
		for i = 1, 3 do
			plates[i] = M.plate(F, { friend = false, unit = "nameplate" .. i })
			plates[i].fault = { markerSetSize = true }
			F.showPlate("nameplate" .. i, plates[i])
		end
		F.flush()
		check("ms-plates: a marker size that cannot be set stops that part and says so", has(F.status(), "raid marker stopped"), F.status())
		clean(W, "ms-plates marker")
	end

	-- Friendly plates.
	do
		local W = M.world({ ["nameplates.friendly"] = false })
		local enemy = M.shown(W, "nameplate1", { friend = false })
		local friend = M.shown(W, "nameplate2", { friend = true, unit = "nameplate2" })
		check("ms-plates: with Restyle friendly nameplates off an enemy plate is styled and a friendly plate is the game's", plateLine(W, enemy) == ON and plateLine(W, friend) == M.NEVER, plateLine(W, friend))
		check("ms-plates: and the friendly plate's fill, size and anchors are the game's", friend.fill.color == nil and friend.mine() == 0)
		W.change("nameplates.friendly", true)
		W.flush()
		check("ms-plates: on again, both are styled", plateLine(W, friend) == ON and plateLine(W, enemy) == ON, plateLine(W, friend))
		W.change("nameplates.friendly", false)
		W.flush()
		check("ms-plates: off again, the friendly plate is back as the game has it", plateLine(W, friend) == OFF and plateLine(W, enemy) == ON, plateLine(W, friend))
		-- isFriend settles after the plate is shown.
		local late = M.plate(W, { unit = "nameplate3" })
		W.showPlate("nameplate3", late)
		W.flush()
		check("ms-plates: a plate whose side is not known yet is styled", plateLine(W, late) == ON)
		late.inner.isFriend = true
		W.fire("UNIT_FACTION", "nameplate3")
		W.flush()
		check("ms-plates: and put back once the game says it is friendly", plateLine(W, late) == OFF, plateLine(W, late))
		late.inner.isFriend = false
		W.fire("UNIT_FACTION", "nameplate3")
		W.flush()
		check("ms-plates: and styled again when it is not", plateLine(W, late) == ON, plateLine(W, late))
		-- Auras on a friendly plate are the game's.
		local aura = M.aura(W, friend)
		W.fire("UNIT_AURA", "nameplate2")
		W.flush()
		check("ms-plates: the aura icons of a friendly plate are the game's", auraLine(aura) == AURA_PLAIN, auraLine(aura))
		clean(W, "ms-plates friendly")
		-- A world with the default: nothing about friendly plates is queued again.
		local D = M.world()
		local d = M.shown(D, "nameplate1", { friend = true })
		local stamps = #D.timers
		D.fire("UNIT_FACTION", "nameplate1")
		check("ms-plates: with the default a faction change styles nothing again", plateLine(D, d) == ON and #D.timers <= stamps + 2)
		clean(D, "ms-plates friendly default")
	end

	-- Aura icons.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		local one = M.aura(W, a)
		W.fire("UNIT_AURA", "nameplate1")
		W.flush()
		W.change("nameplates.auraCrop", 12)
		check("ms-plates: Aura icon crop 12 sets the crop to 0.12", texcoord(one.icon) == "0.12,0.88,0.12,0.88", texcoord(one.icon))
		W.change("nameplates.auraCrop", 0)
		check("ms-plates: and 0 shows the whole icon", texcoord(one.icon) == "0,1,0,1", texcoord(one.icon))
		W.change("nameplates.auraCrop", 8)
		local o = W.look(one.item)
		check("ms-plates: the border has the general colour until Own aura border colour is on", o and rgb(o) == "0.00,0.00,0.00", rgb(o))
		W.change("nameplates.auraBorderOwn", true)
		check("ms-plates: Own aura border colour on gives the border its colour, black until one is chosen", rgb(W.look(one.item)) == "0.00,0.00,0.00")
		W.change("nameplates.auraBorderColour", "ffff8000")
		check("ms-plates: and the colour chosen is the border's", rgb(W.look(one.item)) == "1.00,0.50,0.00", rgb(W.look(one.item)))
		W.change("nameplates.auraBorderColour", "ff00ff00")
		check("ms-plates: and a change of colour follows", rgb(W.look(one.item)) == "0.00,1.00,0.00")
		W.change("nameplates.auraBorderOwn", false)
		check("ms-plates: and off gives the general colour back", rgb(W.look(one.item)) == "0.00,0.00,0.00")
		W.change("nameplates.auraTimers", false)
		check("ms-plates: Countdown numbers off hides the numbers", one.cd.hide == true)
		-- The game sets them on each refresh and the next frame hides them again.
		one.cd.hide = false
		W.fire("UNIT_AURA", "nameplate1")
		W.flush()
		check("ms-plates: the game's own refresh of an aura is followed by hiding them again", one.cd.hide == true)
		W.change("nameplates.auraTimers", true)
		check("ms-plates: Countdown numbers on gives back what the game had set", one.cd.hide == false)
		one.cd.hide = true
		W.fire("UNIT_AURA", "nameplate1")
		W.flush()
		check("ms-plates: and an aura the game hides the numbers of stays as the game has it", one.cd.hide == true)
		one.cd.hide = false
		W.change("nameplates.auras", false)
		W.change("nameplates.auraTimers", false)
		check("ms-plates: Countdown numbers are hidden with the aura border off too, and the icon is the game's", one.cd.hide == true and auraLine(one) == AURA_OFF, auraLine(one))
		W.change("nameplates.auraTimers", true)
		W.change("nameplates.auras", true)
		check("ms-plates: and with both back the border is back and the numbers are the game's", one.cd.hide == false and auraLine(one) == AURA_ON, auraLine(one))
		W.change("nameplates.auraStacks", false)
		check("ms-plates: Stack count off fades the count", one.count.alpha == 0)
		W.change("nameplates.auraStacks", true)
		check("ms-plates: and on brings it back", one.count.alpha == 1)
		W.change("nameplates.auraOpacity", 50)
		W.flush()
		check("ms-plates: Aura opacity 50 sets the aura frame to half", near(a.aurasInner.alpha, 0.5), a.aurasInner.alpha)
		W.change("nameplates.auraOpacity", 100)
		W.flush()
		check("ms-plates: and 100 sets it back to full", a.aurasInner.alpha == 1)
		-- Show auras: only the target.
		local two = M.shown(W, "nameplate2", { friend = false, unit = "nameplate2" })
		W.change("nameplates.aurasWhen", "Only on the target")
		W.flush()
		check("ms-plates: Show auras on the target only hides the auras of every plate that is not the target", a.aurasInner.alpha == 0 and two.aurasInner.alpha == 0, a.aurasInner.alpha)
		a.inner.isTarget = true
		W.units.target = a
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-plates: and the plate that becomes the target shows its auras", a.aurasInner.alpha == 1 and two.aurasInner.alpha == 0, a.aurasInner.alpha)
		a.inner.isTarget = false
		two.inner.isTarget = true
		W.units.target = two
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-plates: and loses them when the target moves on", a.aurasInner.alpha == 0 and two.aurasInner.alpha == 1, a.aurasInner.alpha)
		W.change("nameplates.auraOpacity", 60)
		W.flush()
		check("ms-plates: the opacity applies to the target's auras", near(two.aurasInner.alpha, 0.6) and a.aurasInner.alpha == 0)
		W.change("nameplates.aurasWhen", "On every nameplate")
		W.change("nameplates.auraOpacity", 100)
		W.flush()
		check("ms-plates: Show auras on every nameplate gives every plate its auras again", a.aurasInner.alpha == 1 and two.aurasInner.alpha == 1)
		W.change("nameplates.enabled", false)
		W.change("nameplates.aurasWhen", "Only on the target")
		W.change("nameplates.auraTimers", false)
		W.flush()
		check("ms-plates: with the page off every plate shows its auras whatever the rows say", a.aurasInner.alpha == 1 and two.aurasInner.alpha == 1 and auraLine(one) == AURA_OFF, auraLine(one))
		clean(W, "ms-plates auras")
	end

	-- The parts other files add to the plates, the plates with a unit, and the border colour a plate has of its own.
	do
		local W = M.world()
		local ns = W.ns
		local log = {}
		local function add(kind, label)
			ns.PlateExtra[kind][#ns.PlateExtra[kind] + 1] = function(unitFrame, own)
				log[#log + 1] = label .. ":" .. tostring(unitFrame ~= nil) .. ":" .. tostring(own ~= nil)
			end
		end
		add("show", "show")
		add("layout", "layout")
		add("leave", "leave")
		add("refresh", "refresh")
		ns.PlateExtra.layout[#ns.PlateExtra.layout + 1] = function() error("an added part fails", 0) end
		add("layout", "after")
		local a = M.shown(W, "nameplate1", { friend = false })
		local show, layout, after = 0, 0, 0
		for _, line in ipairs(log) do
			show = show + (line == "show:true:true" and 1 or 0)
			layout = layout + (line == "layout:true:true" and 1 or 0)
			after = after + (line == "after:true:true" and 1 or 0)
		end
		check("ms-plates: a part added for show is called with the unit frame and what the file keeps of it", show == 1, table.concat(log, " "))
		check("ms-plates: a part added for layout is called on each layout, and one that fails does not stop the next", layout >= 1 and layout == after and has(W.status(), "a part added to the plates failed"), layout .. " " .. after)
		local seen = #log
		W.change("nameplates.healthFlat", false)
		local refreshed = 0
		for i = seen + 1, #log do
			refreshed = refreshed + (log[i]:find("^refresh:false:false") and 1 or 0)
		end
		check("ms-plates: a part added for refresh is called with nothing, once for each refresh", refreshed == 1, table.concat(log, " ", seen + 1))
		a.inner.unit = nil
		W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		W.flush()
		check("ms-plates: a part added for leave is called when the game takes the plate back", table.concat(log, " "):find("leave:true:true", 1, true) ~= nil, table.concat(log, " "))
		a.inner.unit = "nameplate1"
		W.showPlate("nameplate1", a)
		W.flush()
		check("ms-plates: IsPlate is true for a plate the addon styled, false for anything else", ns.IsPlate(a.UnitFrame) == true and ns.IsPlate(W.env.UIParent) == false and ns.IsPlate(nil) == false
			and ns.IsPlate(SECRET) == false and ns.IsPlate(5) == false)
		check("ms-plates: PlateUnitFrame is the unit frame of a nameplate unit", ns.PlateUnitFrame("nameplate1") == a.UnitFrame and ns.PlateUnitFrame("nameplate9") == nil)
		local b = M.shown(W, "nameplate2", { friend = false, unit = "nameplate2" })
		local each = {}
		ns.EachPlate(function(unitFrame, tag) each[#each + 1] = tag .. tostring(unitFrame == a.UnitFrame or unitFrame == b.UnitFrame) end, "x")
		check("ms-plates: EachPlate calls a function for every plate that has a unit, with the arguments", #each == 2 and each[1] == "xtrue" and each[2] == "xtrue", table.concat(each, ","))
		ns.EachPlate(function() error("one fails", 0) end)
		-- A colour of its own.
		local before = rgb(W.look(a.healthBar))
		check("ms-plates: PlateBorder gives true for a styled plate and false for another frame", ns.PlateBorder(a.UnitFrame, 1, 0, 0) == true and ns.PlateBorder(W.env.UIParent, 1, 0, 0) == false
			and ns.PlateBorder(nil, 1, 0, 0) == false)
		W.flush()
		check("ms-plates: the colour given is the border colour of a plate that is neither target nor focus", rgb(W.look(a.healthBar)) == "1.00,0.00,0.00" and rgb(W.look(b.healthBar)) == before,
			rgb(W.look(a.healthBar)) .. " " .. before)
		check("ms-plates: and the level box keeps the general colour", rgb(W.look(a.level)) == before)
		W.units.target = a
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-plates: the target's own colour wins over it", rgb(W.look(a.healthBar)) == "1.00,1.00,1.00", rgb(W.look(a.healthBar)))
		W.units.target = nil
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-plates: and it returns when the plate is not the target", rgb(W.look(a.healthBar)) == "1.00,0.00,0.00", rgb(W.look(a.healthBar)))
		ns.PlateBorder(a.UnitFrame, nil)
		W.flush()
		check("ms-plates: no colour puts the default back", rgb(W.look(a.healthBar)) == before, rgb(W.look(a.healthBar)))
		ns.PlateBorder(a.UnitFrame, 0.5, 0.5, 0.5, 3)
		W.flush()
		check("ms-plates: a thickness may be given with it", W.look(a.healthBar).thick == 3 and rgb(W.look(a.healthBar)) == "0.50,0.50,0.50", tostring(W.look(a.healthBar).thick))
		local given = ns.PlateBorder(a.UnitFrame, "red", 0, 0)
		W.flush()
		check("ms-plates: a colour that is not a number is none", given == true and rgb(W.look(a.healthBar)) == before, rgb(W.look(a.healthBar)))
		clean(W, "ms-plates exports")
	end

	-- Nameplate colours, threat, the colours of the kinds and the mouseover border (ms-05). Every label starts "ms-pcol:". The world is the one above with
	-- the unit calls these rows ask, kept on T: attack, threat (a number, "error" or the secret value), player, reaction, sel (a colour), role, class and
	-- bossMob. The game's call is a function of the world that sets the bar to plate.game when it differs from the bar, as the game's own does.
	do
		local P = {}
		function P.world(o)
			o = o or {}
			local W = newWorld({})
			local T = { attack = {}, threat = {}, player = {}, reaction = {}, sel = {}, role = "NONE", class = {}, bossMob = {}, byFrame = {}, calls = 0 }
			W.T = T
			local env = W.env
			env.NamePlateSetupOptions = { horizontalScale = 1, verticalScale = 1, insetWidth = 12, healthBarHeight = 13, castBarHeight = 6, castIconHeight = 10,
				useClassicHealthBar = false, useClassicCastBar = false }
			env.NamePlateConstants = { NAME_PLATE_WIDTH = 190 }
			env.UnitCanAttack = function(_, unit) return T.attack[unit] == true end
			env.UnitThreatSituation = function(_, unit)
				if T.threat[unit] == "error" then
					error("UnitThreatSituation failed", 0)
				end
				return T.threat[unit]
			end
			env.UnitGroupRolesAssigned = function() return T.role end
			T.tapped, T.dead, T.offline = {}, {}, {}
			env.UnitIsTapDenied = function(unit) return T.tapped[unit] == true end
			env.UnitPlayerControlled = function() return false end
			env.UnitIsConnected = function(unit) return T.offline[unit] ~= true end
			env.UnitIsDead = function(unit) return T.dead[unit] == true end
			env.UnitIsPlayer = function(unit) return T.player[unit] == true end
			env.UnitReaction = function(unit) return T.reaction[unit] end
			env.UnitSelectionColor = function(unit)
				local c = T.sel[unit] or { 1, 0, 0 }
				if rawequal(c, SECRET) then
					return SECRET, SECRET, SECRET
				end
				return c[1], c[2], c[3]
			end
			env.UnitClassification = function(unit) return T.class[unit] or "normal" end
			env.UnitIsBossMob = function(unit) return T.bossMob[unit] == true end
			if not o.noGame then
				env.CompactUnitFrame_UpdateHealthColor = function(frame)
					local p = T.byFrame[frame]
					if p then
						T.calls = T.calls + 1
						local c, now = p.game, p.colour
						if c[1] ~= now[1] or c[2] ~= now[2] or c[3] ~= now[3] then
							p.colour = { c[1], c[2], c[3], 1 }
							p.gameSets = p.gameSets + 1
						end
					end
				end
			end
			W.login()
			return W
		end
		-- A plate with a unit: o.friend, o.attack, o.player, o.reaction, o.sel, o.class, o.threat.
		function P.plate(W, unit, o)
			o = o or {}
			local T = W.T
			local plate = M.plate(W, { unit = unit, friend = o.friend })
			plate.colour, plate.game, plate.sets, plate.gets, plate.gameSets = { 0.2, 0.4, 0.6, 1 }, { 0.2, 0.4, 0.6, 1 }, 0, 0, 0
			local hb = plate.healthInner
			hb.GetStatusBarColor = function()
				plate.gets = plate.gets + 1
				return plate.colour[1], plate.colour[2], plate.colour[3], plate.colour[4]
			end
			hb.SetStatusBarColor = function(_, r, g, b, a)
				if plate.fault then
					error("SetStatusBarColor failed", 0)
				end
				plate.sets = plate.sets + 1
				plate.colour = { r, g, b, a }
			end
			T.byFrame[plate.UnitFrame] = plate
			T.attack[unit], T.player[unit], T.reaction[unit], T.sel[unit], T.class[unit], T.threat[unit] = o.attack, o.player, o.reaction, o.sel, o.class, o.threat
			W.showPlate(unit, plate)
			W.flush()
			return plate
		end
		-- The game runs its colour call on the plate.
		function P.game(W, plate)
			W.env.CompactUnitFrame_UpdateHealthColor(plate.UnitFrame)
		end
		function P.set(W, path, value)
			W.ns.Set(path, value)
			W.flush()
		end
		function P.c(plate)
			return ("%.2f,%.2f,%.2f"):format(plate.colour[1], plate.colour[2], plate.colour[3])
		end
		function P.border(W, plate)
			return rgb(W.look(plate.healthBar))
		end
		-- The colour of the line inside a Rare Elite's border, as text.
		function P.rim(W, plate)
			local made = {}
			for _, f in ipairs(W.addonFrames) do
				if f.parent == plate.healthBar then
					made[#made + 1] = f
				end
			end
			for _, f in ipairs(W.addonFrames) do
				if made[2] and f.parent == made[2] then
					local e = W.edgesOn(f)
					if #e == 4 then
						return e[1].shown and ("%.2f,%.2f,%.2f"):format(e[1].color[1], e[1].color[2], e[1].color[3]) or "hidden"
					end
				end
			end
			return "none"
		end
		-- The roles of the group change and the plates are looked at again.
		function P.roles(W, role)
			W.T.role = role
			W.fire("PLAYER_ROLES_ASSIGNED")
			W.flush()
		end
		P.GAME, P.HOSTILE, P.HALF = "0.20,0.40,0.60", "0.90,0.10,0.10", "0.50,0.50,0.50"
		P.GOOD, P.CHANGE, P.BAD = "0.30,0.75,0.35", "0.90,0.76,0.20", "0.85,0.25,0.25"

		-- The rows: where they are saved, their defaults, what they need and their choices.
		do
			local W = P.world()
			local want = { colours = false, colourPlayers = "game", targetBar = false, targetBarColour = "ff66b3ff", threat = false, threatRole = "auto", threatGood = "ff4dbf59",
				threatTransition = "ffe6c133", threatBad = "ffd94040", hover = false, hoverColour = "ffd9d9d9", eliteColour = "ffffd100", rareColour = "ffc7ccd6", bossColour = "ffff593d" }
			local bad = {}
			for key, value in pairs(want) do
				if W.ns.Get("nameplates." .. key) ~= value then
					bad[#bad + 1] = key .. "=" .. tostring(W.ns.Get("nameplates." .. key))
				end
			end
			table.sort(bad)
			check("ms-pcol: the fourteen rows start at their stand-in defaults", #bad == 0, table.concat(bad, " "))
			local rows, order = {}, {}
			for _, page in ipairs(W.ns.PAGES) do
				for _, row in ipairs(page) do
					if row.key then
						rows[page.key .. "." .. row.key] = row
						if page.key == "nameplatesColours" then
							order[#order + 1] = row.key
						end
					end
				end
			end
			check("ms-pcol: the page Colours and threat holds fifteen rows in order",
				table.concat(order, ",") == "colours,colourPlayers,targetBar,targetBarColour,threat,threatRole,threatGood,threatTransition,threatBad,hover,hoverColour,healthByLeft,lowHealth,lowHealthAt,lowHealthColour", table.concat(order, ","))
			check("ms-pcol: the rows that need another name it", rows["nameplatesColours.colourPlayers"].needs == "colours" and rows["nameplatesColours.targetBarColour"].needs == "targetBar"
				and rows["nameplatesColours.threatRole"].needs == "threat" and rows["nameplatesColours.threatBad"].needs == "threat" and rows["nameplatesColours.hoverColour"].needs == "hover"
				and rows["nameplatesMarks.eliteColour"].needs == "kindBorder" and rows["nameplatesMarks.rareColour"].needs == "kindBorder" and rows["nameplatesMarks.bossColour"].needs == "kindBorder"
				and rows["nameplatesColours.colours"].needs == nil and rows["nameplatesColours.threat"].needs == nil and rows["nameplatesColours.hover"].needs == "health")
			check("ms-pcol: the choices", #rows["nameplatesColours.colourPlayers"].choices == 2 and rows["nameplatesColours.colourPlayers"].choices[2][1] == "reaction"
				and #rows["nameplatesColours.threatRole"].choices == 3 and rows["nameplatesColours.threatRole"].choices[2][1] == "tank" and rows["nameplatesColours.threatRole"].choices[3][1] == "damage")
			W.ns.Set("nameplates.threatRole", "healer")
			W.ns.Set("nameplates.hoverColour", "red")
			check("ms-pcol: a choice outside its list and a colour that is no colour are refused", W.ns.Get("nameplates.threatRole") == "auto" and W.ns.Get("nameplates.hoverColour") == "ffd9d9d9")
			clean(W, "ms-pcol rows")
		end

		-- At the defaults nothing is hooked, read or set, and no timer runs.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, threat = 3, class = "elite" })
			local d = P.plate(W, "nameplate2", { friend = false, attack = true })
			local hooks, gets, sets, border, plain = W.hooks, a.gets, a.sets, P.border(W, a), P.border(W, d)
			W.units.target, W.units.mouseover = a, d
			W.fire("PLAYER_TARGET_CHANGED")
			W.fire("PLAYER_ROLES_ASSIGNED")
			W.fire("UPDATE_MOUSEOVER_UNIT")
			a.game = { 0.5, 0.5, 0.5, 1 }
			P.game(W, a)
			W.flush()
			check("ms-pcol: at the defaults the game's call is not followed and the addon never reads or sets the bar's colour", W.hooks == hooks and a.gets == gets and a.sets == sets and P.c(a) == P.HALF,
				W.hooks .. " " .. hooks .. " " .. a.gets .. " " .. gets .. " " .. a.sets .. " " .. sets)
			check("ms-pcol: the mouseover starts no timer and the plates keep their borders", #W.timers == 0 and border == "1.00,0.82,0.00" and P.border(W, a) == "1.00,1.00,1.00" and P.border(W, d) == plain,
				border .. " " .. P.border(W, a) .. " " .. P.border(W, d))
			check("ms-pcol: /flatui status has no line about threat or colours", not has(W.status(), "Nameplate threat") and not has(W.status(), "Plate colours"), W.status())
			clean(W, "ms-pcol defaults")
		end

		-- Reaction colours.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 } })
			local b = P.plate(W, "nameplate2", { friend = false, attack = true, player = true, reaction = 2, sel = { 0, 0, 1 } })
			P.set(W, "nameplates.colours", true)
			check("ms-pcol: Reaction colours on paints a plate in the colour the game gives its unit's reaction", P.c(a) == P.HOSTILE, P.c(a))
			check("ms-pcol: a player keeps the game's colour while Players is As the game has it", P.c(b) == P.GAME, P.c(b))
			P.set(W, "nameplates.colourPlayers", "reaction")
			check("ms-pcol: and has the reaction colour when Players is By reaction", P.c(b) == "0.00,0.00,1.00", P.c(b))
			P.set(W, "nameplates.colourPlayers", "game")
			check("ms-pcol: Players back to As the game has it gives the player the game's colour again", P.c(b) == P.GAME, P.c(b))
			local c = P.plate(W, "nameplate3", { friend = false, attack = true, reaction = 2, sel = { 0.1, 0.9, 0.1 } })
			check("ms-pcol: a plate that appears after the row is switched on is painted", P.c(c) == "0.10,0.90,0.10", P.c(c))
			a.game = { 0.5, 0.5, 0.5, 1 }
			P.game(W, a)
			check("ms-pcol: when the game sets its colour again the hook answers in the same call, so the bar ends in the reaction colour", P.c(a) == P.HOSTILE and a.gameSets == 1, P.c(a) .. " " .. a.gameSets)
			a.game = { 0.3, 0.3, 0.3, 1 }
			P.set(W, "nameplates.colours", false)
			check("ms-pcol: switched off the bar has the colour the game set last, with its alpha", P.c(a) == P.HALF and a.colour[4] == 1, P.c(a) .. " " .. tostring(a.colour[4]))
			P.game(W, a)
			check("ms-pcol: and the next call of the game is its own", P.c(a) == "0.30,0.30,0.30", P.c(a))
			W.T.reaction.nameplate1 = 5
			P.set(W, "general.reactionOwn", true)
			P.set(W, "general.reactionFriendly", "ff112233")
			P.set(W, "nameplates.colours", true)
			check("ms-pcol: the colours of Custom reaction colours on the Colours page are the colours used", P.c(a) == "0.07,0.13,0.20", P.c(a))
			W.T.sel.nameplate1 = SECRET
			P.set(W, "general.reactionOwn", false)
			check("ms-pcol: a colour the client withholds leaves the game's colour", P.c(a) == "0.30,0.30,0.30", P.c(a))
			P.set(W, "nameplates.enabled", false)
			check("ms-pcol: with the page off the plates have the game's colours", P.c(a) == "0.30,0.30,0.30" and P.c(b) == P.GAME, P.c(a) .. " " .. P.c(b))
			P.set(W, "nameplates.enabled", true)
			P.set(W, "nameplates.colours", true)
			W.T.sel.nameplate1 = { 0.9, 0.1, 0.1 }
			a.game = { 0.6, 0.6, 0.6, 1 }
			W.T.tapped.nameplate1 = true
			P.game(W, a)
			check("ms-pcol: a tapped plate with Custom reaction colours off keeps the game's colour", P.c(a) == "0.60,0.60,0.60", P.c(a))
			P.set(W, "general.reactionOwn", true)
			P.game(W, a)
			check("ms-pcol: and with it on takes the tapped colour", P.c(a) == string.format("%.2f,%.2f,%.2f", W.ns.Colour("general.reactionTapped")), P.c(a))
			P.set(W, "general.reactionOwn", false)
			W.T.tapped.nameplate1 = nil
			W.T.dead.nameplate1 = true
			a.game = { 0.4, 0.4, 0.4, 1 }
			P.game(W, a)
			check("ms-pcol: a dead NPC keeps the game's grey", P.c(a) == "0.40,0.40,0.40", P.c(a))
			W.T.dead.nameplate1 = nil
			W.T.offline.nameplate1 = true
			a.game = { 0.45, 0.45, 0.45, 1 }
			P.game(W, a)
			check("ms-pcol: a disconnected unit keeps the game's grey", P.c(a) == "0.45,0.45,0.45", P.c(a))
			clean(W, "ms-pcol reaction")
		end

		-- The target's colour, and the order of the three.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 }, threat = 3 })
			local b = P.plate(W, "nameplate2", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 }, threat = 0 })
			P.set(W, "nameplates.targetBar", true)
			check("ms-pcol: with no target no plate is painted", P.c(a) == P.GAME and P.c(b) == P.GAME)
			W.units.target = a
			W.fire("PLAYER_TARGET_CHANGED")
			W.flush()
			check("ms-pcol: the target's bar takes its colour at once, though the game runs no call on a change of target", P.c(a) == "0.40,0.70,1.00" and P.c(b) == P.GAME and W.T.calls == 0, P.c(a))
			W.units.target = b
			W.fire("PLAYER_TARGET_CHANGED")
			W.flush()
			check("ms-pcol: and the colour moves with the target", P.c(b) == "0.40,0.70,1.00" and P.c(a) == P.GAME, P.c(a) .. " " .. P.c(b))
			P.set(W, "nameplates.targetBarColour", "ff00ff00")
			check("ms-pcol: a changed colour applies at once", P.c(b) == "0.00,1.00,0.00", P.c(b))
			P.set(W, "nameplates.colours", true)
			P.set(W, "nameplates.threat", true)
			P.roles(W, "TANK")
			check("ms-pcol: the target's colour wins over threat and reaction, a threat colour over reaction", P.c(b) == "0.00,1.00,0.00" and P.c(a) == P.GOOD, P.c(a) .. " " .. P.c(b))
			P.set(W, "nameplates.targetBar", false)
			check("ms-pcol: with Colour the target's health bar off the target has its threat colour", P.c(b) == P.BAD, P.c(b))
			clean(W, "ms-pcol target")
		end

		-- Threat.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 } })
			local function at(value)
				W.T.threat.nameplate1 = value
				P.game(W, a)
				return P.c(a)
			end
			P.set(W, "nameplates.threat", true)
			P.set(W, "nameplates.threatRole", "tank")
			local t3, t2, t1, t0 = at(3), at(2), at(1), at(0)
			check("ms-pcol: a tank wants 3, has 2 as changing hands and 0 or 1 as unwanted", t3 == P.GOOD and t2 == P.CHANGE and t1 == P.BAD and t0 == P.BAD, t3 .. " " .. t2 .. " " .. t1 .. " " .. t0)
			P.set(W, "nameplates.threatRole", "damage")
			t0, t1, t2, t3 = at(0), at(1), at(2), at(3)
			check("ms-pcol: another role wants 0, has 1 and 2 as changing hands and 3 as unwanted", t0 == P.GOOD and t1 == P.CHANGE and t2 == P.CHANGE and t3 == P.BAD, t0 .. " " .. t1 .. " " .. t2 .. " " .. t3)
			at(1)
			P.set(W, "nameplates.threatRole", "auto")
			local calls = W.T.calls
			P.roles(W, "TANK")
			local asTank = P.c(a)
			P.roles(W, "HEALER")
			check("ms-pcol: From your group role is a tank for a role of TANK and not for another, and a change of roles applies without a call of the game",
				asTank == P.BAD and P.c(a) == P.CHANGE and W.T.calls == calls, asTank .. " " .. P.c(a))
			a.game = { 0.5, 0.5, 0.5, 1 }
			check("ms-pcol: no threat at all leaves the game's colour", at(nil) == P.HALF, at(nil))
			P.set(W, "nameplates.colours", true)
			check("ms-pcol: and the reaction colour when Reaction colours is on", P.c(a) == P.HOSTILE, P.c(a))
			local secret, failed = at(SECRET), at("error")
			check("ms-pcol: a plate with no threat answer is in neither count of the status line", not has(W.status(), "plates read 1") and has(W.status(), "without an answer 1"), W.status())
			at(nil)
			check("ms-pcol: a plain nil is no refusal and is not counted as one", has(W.status(), "plates read 0, without an answer 0"), W.status())
			check("ms-pcol: an answer the client withholds or refuses falls through the same way", secret == P.HOSTILE and failed == P.HOSTILE, secret .. " " .. failed)
			P.set(W, "nameplates.colours", false)
			check("ms-pcol: and to the game's colour with reaction colours off", at(SECRET) == P.HALF, at(SECRET))
			W.T.attack.nameplate1 = false
			check("ms-pcol: a unit the player cannot attack has no threat colour", at(3) == P.HALF, at(3))
			W.T.attack.nameplate1 = true
			at(3)
			P.set(W, "nameplates.threatGood", "ff0000ff")
			P.set(W, "nameplates.threatRole", "damage")
			check("ms-pcol: a threat colour changed on the page applies at once", at(0) == "0.00,0.00,1.00", at(0))
			P.set(W, "nameplates.threat", false)
			check("ms-pcol: Threat colours off gives the game's colour back", P.c(a) == P.HALF, P.c(a))
			clean(W, "ms-pcol threat")
		end

		-- The status line of threat, friendly plates, plates the game forbids.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, threat = 2 })
			local b = P.plate(W, "nameplate2", { friend = false, attack = true, reaction = 2, threat = SECRET })
			local f = P.plate(W, "nameplate3", { friend = true, attack = false, reaction = 5, sel = { 0, 1, 0 } })
			P.set(W, "nameplates.threat", true)
			P.set(W, "nameplates.colours", true)
			P.game(W, f)
			check("ms-pcol: /flatui status says how many plates read threat and how many gave no answer", has(W.status(), "Nameplate threat: plates read 1, without an answer 1."), W.status())
			check("ms-pcol: a friendly plate takes the reaction colour", P.c(f) == "0.00,1.00,0.00", P.c(f))
			P.set(W, "nameplates.friendly", false)
			f.game = { 0.5, 0.5, 0.5, 1 }
			P.game(W, f)
			check("ms-pcol: with Restyle friendly nameplates off it keeps the game's colour", P.c(f) == P.HALF, P.c(f))
			P.set(W, "nameplates.friendly", true)
			W.units.nameplate8 = W.newPlate({ forbidden = true })
			W.fire("NAME_PLATE_UNIT_ADDED", "nameplate8")
			P.roles(W, "TANK")
			check("ms-pcol: a plate the game forbids is skipped without a message", W.ns.IsPlate(W.units.nameplate8.UnitFrame) == false and #W.errors == 0 and #W.violations == 0,
				tostring(W.ns.IsPlate(W.units.nameplate8.UnitFrame)) .. " " .. table.concat(W.errors, "|") .. " " .. table.concat(W.violations, "|"))
			a.inner.unit = nil
			W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
			W.flush()
			check("ms-pcol: a plate the game takes back is not counted", has(W.status(), "Nameplate threat: plates read 0, without an answer 1"), W.status())
			P.set(W, "nameplates.threat", false)
			check("ms-pcol: with threat off the line is gone", not has(W.status(), "Nameplate threat"), W.status())
			clean(W, "ms-pcol status")
		end

		-- The border of the plate under the mouse.
		do
			local W = P.world()
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, class = "elite" })
			local b = P.plate(W, "nameplate2", { friend = false, attack = true })
			local before, kind = P.border(W, b), P.border(W, a)
			P.set(W, "nameplates.hover", true)
			W.units.mouseover = a
			W.fire("UPDATE_MOUSEOVER_UNIT")
			W.flush()
			check("ms-pcol: the plate under the mouse has the mouseover colour in place of its kind's", P.border(W, a) == "0.85,0.85,0.85" and P.border(W, b) == before and kind == "1.00,0.82,0.00", P.border(W, a) .. " " .. kind)
			W.units.mouseover = b
			W.fire("UPDATE_MOUSEOVER_UNIT")
			W.flush()
			check("ms-pcol: it moves to the next plate and leaves the first", P.border(W, b) == "0.85,0.85,0.85" and P.border(W, a) == kind, P.border(W, a) .. " " .. P.border(W, b))
			W.units.mouseover = nil
			W.advance(0.05)
			W.advance(0)
			local early = P.border(W, b)
			W.advance(0.05)
			W.advance(0)
			check("ms-pcol: a ticker sees the mouse leave within 0.1 s, since the game says nothing, and the plate has its own border again", early == "0.85,0.85,0.85" and P.border(W, b) == before, early .. " " .. P.border(W, b))
			W.flush()
			check("ms-pcol: and no timer is left", P.border(W, a) == kind and #W.timers == 0, #W.timers)
			W.units.mouseover = SECRET
			W.fire("UPDATE_MOUSEOVER_UNIT")
			W.flush()
			check("ms-pcol: a mouseover the client withholds colours nothing", P.border(W, b) == before and #W.timers == 0)
			W.units.mouseover = a
			W.units.target = a
			W.fire("PLAYER_TARGET_CHANGED")
			W.fire("UPDATE_MOUSEOVER_UNIT")
			W.flush()
			check("ms-pcol: the target keeps its own colour over the mouseover colour", P.border(W, a) == "1.00,1.00,1.00", P.border(W, a))
			W.units.target, W.units.focus = nil, a
			W.fire("PLAYER_TARGET_CHANGED")
			W.fire("PLAYER_FOCUS_CHANGED")
			W.flush()
			check("ms-pcol: and the focus keeps its own", P.border(W, a) == "1.00,0.60,0.00", P.border(W, a))
			W.units.focus = nil
			W.fire("PLAYER_FOCUS_CHANGED")
			P.set(W, "nameplates.hoverColour", "ff0000ff")
			check("ms-pcol: a changed mouseover colour applies at once", P.border(W, a) == "0.00,0.00,1.00", P.border(W, a))
			P.set(W, "nameplates.hover", false)
			check("ms-pcol: Mouseover border off gives the kind's border back and stops the ticker", P.border(W, a) == kind and #W.timers == 0, P.border(W, a) .. " " .. #W.timers)
			clean(W, "ms-pcol mouseover")
		end

		-- The colours of the kinds.
		do
			local W = P.world()
			local e = P.plate(W, "nameplate1", { friend = false, attack = true, class = "elite" })
			local r = P.plate(W, "nameplate2", { friend = false, attack = true, class = "rare" })
			local re = P.plate(W, "nameplate3", { friend = false, attack = true, class = "rareelite" })
			local boss = P.plate(W, "nameplate4", { friend = false, attack = true, class = "worldboss" })
			local n = P.plate(W, "nameplate5", { friend = false, attack = true })
			local was = { P.border(W, e), P.border(W, r), P.border(W, re), P.border(W, boss), P.border(W, n) }
			check("ms-pcol: at the defaults the borders are exactly the game's gold, silver, silver and red", was[1] == "1.00,0.82,0.00" and was[2] == "0.78,0.80,0.84" and was[3] == "0.78,0.80,0.84"
				and was[4] == "1.00,0.35,0.24", table.concat(was, " "))
			local exact = W.look(e.healthBar)
			check("ms-pcol: and they are the very numbers of the game's colours, not rounded ones", exact.g == 0.82 and exact.b == 0 and W.look(r.healthBar).r == 0.78 and W.look(boss.healthBar).g == 0.35, tostring(exact.g))
			check("ms-pcol: the line inside a Rare Elite's border is gold", P.rim(W, re) == "1.00,0.82,0.00", P.rim(W, re))
			P.set(W, "nameplates.eliteColour", "ff00ff00")
			check("ms-pcol: the Elite colour changes the line inside a Rare Elite's border", P.rim(W, re) == "0.00,1.00,0.00", P.rim(W, re))
			check("ms-pcol: the Elite colour changes the border of an elite and no other", P.border(W, e) == "0.00,1.00,0.00" and P.border(W, r) == was[2] and P.border(W, boss) == was[4]
				and P.border(W, n) == was[5], P.border(W, e))
			P.set(W, "nameplates.rareColour", "ff0000ff")
			check("ms-pcol: the Rare colour changes a rare and the outer border of a Rare Elite", P.border(W, r) == "0.00,0.00,1.00" and P.border(W, re) == "0.00,0.00,1.00" and P.border(W, e) == "0.00,1.00,0.00")
			P.set(W, "nameplates.bossColour", "ffff00ff")
			check("ms-pcol: the Boss colour changes a boss", P.border(W, boss) == "1.00,0.00,1.00" and P.border(W, e) == "0.00,1.00,0.00")
			W.units.target = e
			W.fire("PLAYER_TARGET_CHANGED")
			W.flush()
			check("ms-pcol: the target keeps its colour over its kind's", P.border(W, e) == "1.00,1.00,1.00")
			P.set(W, "nameplates.kindBorder", false)
			check("ms-pcol: Border colour for Elite and Rare off gives every plate its general border", P.border(W, r) == was[5] and P.border(W, boss) == was[5], P.border(W, r))
			clean(W, "ms-pcol kinds")
		end

		-- A game without the colour call, a refused call, and a part that stops.
		do
			local W = P.world({ noGame = true })
			local a = P.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 } })
			P.set(W, "nameplates.colours", true)
			check("ms-pcol: a game without the health colour call keeps its colours, with a line in /flatui status", P.c(a) == P.GAME
				and has(W.status(), "Plate colours: the game's health colour call was not found"), P.c(a) .. " " .. W.status():gsub("[\n]", " | "))
			clean(W, "ms-pcol no call")
			local X = P.world()
			local plates = {}
			for i = 1, 4 do
				plates[i] = P.plate(X, "nameplate" .. i, { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 } })
			end
			P.set(X, "nameplates.colours", true)
			check("ms-pcol: four plates are painted", P.c(plates[4]) == P.HOSTILE and P.c(plates[1]) == P.HOSTILE)
			for i = 1, 4 do
				plates[i].fault = true
			end
			for i = 1, 3 do
				plates[i].game = { 0.5, 0.5, 0.5, 1 }
				P.game(X, plates[i])
			end
			check("ms-pcol: a refused call on three plates stops the part, with a line that names it and says why", has(X.status(), "plate colours stopped") and has(X.status(), "SetStatusBarColor failed"), X.status())
			plates[4].fault = nil
			P.game(X, plates[4])
			check("ms-pcol: a stopped part colours no more plates", P.c(plates[4]) == P.GAME, P.c(plates[4]))
		end
	end
end
-- >>> ms-plates (end)
-- >>> ms-ptext (begin)
-- Nameplate text, cast bar parts and clickable area (ms-06). Every label starts "ms-ptext:". The values are kept in one table: the main function of this
-- file has a limit on the locals alive at once. The plates are those of the older world with the parts these rows touch added: the name, the three
-- health strings, the cast bar's text, icon, spark and shield, and the plate's hit-test methods. The game's own functions the addon follows
-- (CompactUnitFrame_UpdateName and CompactUnitFrame_UpdateHealth) and the health calls are in the world.
do
	local M = {}
	M.GAME = { 0.9, 0.1, 0.1, 1 }
	function M.world(options, setup)
		setup = setup or {}
		local W = newWorld({ saved = options and { options = options } or nil, beforeLoad = function(_, loadEnv)
			-- The colour the game gives the name, as CompactUnitFrame_UpdateName does after its text.
			loadEnv.CompactUnitFrame_UpdateName = function(frame)
				frame.name:SetVertexColor(M.GAME[1], M.GAME[2], M.GAME[3], M.GAME[4])
			end
			loadEnv.CompactUnitFrame_UpdateHealth = function(frame)
				loadEnv.CompactUnitFrame_UpdateName(frame)
			end
		end })
		local env = W.env
		env.NamePlateSetupOptions = { horizontalScale = 1, verticalScale = 1, insetWidth = 12, healthBarHeight = 13, castBarHeight = 6, castIconWidth = 10, castIconHeight = 10,
			useClassicHealthBar = false, useClassicCastBar = false, unitNameAnchorStyle = setup.above and 2 or 1 }
		env.NamePlateConstants = { NAME_PLATE_WIDTH = 190, NAME_ANCHOR_STYLES = { InsideHealthBar = 1, AboveHealthBar = 2 } }
		W.hp = { health = 12500, percent = 85, missing = 2500 }
		local function health(what, answer)
			return function(unit)
				if type(unit) ~= "string" then
					bad(W, what .. ": a unit token is expected")
				end
				if W.hp.fault == "error" then
					error(what .. " failed", 0)
				elseif W.hp.secret then
					return SECRET
				end
				return answer()
			end
		end
		env.UnitHealth = health("UnitHealth", function() return W.hp.health end)
		env.UnitHealthMissing = health("UnitHealthMissing", function() return W.hp.missing end)
		env.CurveConstants = { ScaleTo100 = {} }
		env.UnitHealthPercent = function(unit, predicted, curve)
			if curve ~= env.CurveConstants.ScaleTo100 or predicted ~= true then
				bad(W, "UnitHealthPercent: the predicted flag and the curve of the game are expected")
			end
			return health("UnitHealthPercent", function() return W.hp.percent end)(unit)
		end
		env.AbbreviateNumbers = function(value)
			if rawequal(value, SECRET) then
				return SECRET
			end
			return value >= 1000 and ("%.1fK"):format(value / 1000) or tostring(value)
		end
		env.UnitSelectionColor = env.UnitSelectionColor or function() return 0.2, 0.8, 0.3, 1 end
		W.login()
		return W
	end
	-- o.friend, o.unit, o.target, o.refuse. plate.hits are the calls on the hit area, with who made them.
	function M.plate(W, o)
		o = o or {}
		local plate = W.newPlate()
		W.group = "nameplate"
		local inner, hb, uf = plate.inner, plate.healthInner, plate.UnitFrame
		local function text(label)
			local proxy, raw = W.Rr(nil, nil, { kind = "FontString" })
			plate[label] = raw
			return proxy
		end
		local function texture(label)
			local proxy, raw = W.Rr(nil, nil)
			plate[label] = raw
			return proxy
		end
		inner.name = text("name")
		hb.Text, hb.LeftText, hb.RightText = text("text"), text("left"), text("right")
		for _, key in ipairs({ "text", "left", "right" }) do
			plate[key].textColour = { 0.8, 0.8, 0.8, 1 }
		end
		local cast = W.rawOf[plate.castBar]
		cast.Text, cast.CastTargetNameText = text("castText"), text("castTarget")
		cast.Icon, cast.Spark, cast.BorderShield = texture("icon"), texture("spark"), texture("shield")
		plate.castText.font, plate.castText.textColour = { "Fonts\\FRIZQT__.TTF", 10, "OUTLINE" }, { 0.9, 0.9, 0.9, 1 }
		plate.castTarget.font = { "Fonts\\FRIZQT__.TTF", 10, "OUTLINE" }
		plate.icon.width, plate.icon.height = 10, 10
		inner.unit, inner.isFriend, inner.isTarget = o.unit or "nameplate1", o.friend or false, o.target
		plate.hits, plate.points, plate.refuse = {}, nil, o.refuse
		local function record(kind)
			plate.hits[#plate.hits + 1] = { kind = kind, addon = W.inBlizzard == 0 or (W.inHook or 0) > 0 }
		end
		function plate.CanChangeHitTestPoints() return not plate.refuse end
		function plate.SetHitTestPoints(_, anchors)
			record("set")
			plate.points = anchors
		end
		function plate.ClearAllHitTestPoints()
			record("clear")
			plate.points = nil
		end
		-- UpdateHitTestArea, Blizzard_NamePlateUnitFrame.lua:589-612.
		inner.UpdateHitTestArea = function(self, options)
			if inner.showOnlyName or inner.widgetsOnlyMode then
				plate:ClearAllHitTestPoints()
			elseif options.unitNameAnchorStyle == 1 then
				plate:SetHitTestPoints({ { point = "TOPLEFT", relativeTo = plate.healthBar, relativePoint = "TOPLEFT", offsetX = -10, offsetY = options.healthBarHeight / 2 },
					{ point = "BOTTOMRIGHT", relativeTo = plate.healthBar, relativePoint = "BOTTOMRIGHT", offsetX = 10, offsetY = -options.healthBarHeight / 2 } })
			else
				plate:SetHitTestPoints({ { point = "TOPLEFT", relativeTo = self.name, relativePoint = "TOPLEFT", offsetX = -14, offsetY = 0 },
					{ point = "BOTTOMRIGHT", relativeTo = plate.healthBar, relativePoint = "BOTTOMRIGHT", offsetX = 10, offsetY = -options.healthBarHeight / 2 } })
			end
		end
		function plate.hit()
			W.blizzard(function() uf.UpdateHitTestArea(uf, W.env.NamePlateSetupOptions) end)
		end
		-- UpdateAnchors: the game's pass that the addon follows to lay its parts out again.
		inner.UpdateAnchors = function() end
		function plate.update()
			W.gameOptions()
			W.flush()
		end
		function plate.addonHits()
			local n = 0
			for _, hit in ipairs(plate.hits) do
				n = n + (hit.addon and 1 or 0)
			end
			return n
		end
		function plate.updateName()
			W.blizzard(function() W.env.CompactUnitFrame_UpdateName(uf) end)
		end
		function plate.updateHealth()
			W.blizzard(function() W.env.CompactUnitFrame_UpdateHealth(uf) end)
		end
		W.group = "static"
		W.seal()
		return plate
	end
	function M.shown(W, unit, o)
		o = o or {}
		o.unit = unit or o.unit
		local plate = M.plate(W, o)
		W.showPlate(o.unit or "nameplate1", plate)
		W.flush()
		return plate
	end
	function M.colour(raw)
		local c = raw.textColour
		return c and ("%.2f,%.2f,%.2f"):format(c[1], c[2], c[3]) or "-"
	end
	function M.vertex(raw)
		return ("%.2f,%.2f,%.2f"):format(raw.vertex[1], raw.vertex[2], raw.vertex[3])
	end
	function M.alphas(a)
		return ("%s,%s,%s"):format(g(a.text.alpha), g(a.left.alpha), g(a.right.alpha))
	end
	-- The font string of the addon's own that draws the health text.
	function M.own(W)
		for _, fontString in ipairs(W.addonFonts) do
			if fontString.template == "SystemFont_NamePlate" then
				return fontString
			end
		end
	end

	-- The rows: saved paths, defaults, ranges, choices, and which row needs which.
	do
		local W = M.world()
		local want = { nameShow = true, nameColour = "game", nameCustomColour = "ffffffff", healthTextColour = "ffffffff", healthTextWhen = "always", healthFormat = "game",
			castTextSize = 100, castTextOutline = true, castTextColour = "ffffffff", castIconSize = 100, castSpark = true, castShield = true,
			clickThroughFriendly = false, clickThroughEnemy = false, clickExtraX = 0, clickExtraY = 0 }
		local bad = {}
		for key, value in pairs(want) do
			if W.ns.Get("nameplates." .. key) ~= value then
				bad[#bad + 1] = key .. "=" .. tostring(W.ns.Get("nameplates." .. key))
			end
		end
		table.sort(bad)
		check("ms-ptext: every new row starts at the game's own look", #bad == 0, table.concat(bad, " "))
		local rows = {}
		for _, page in ipairs(W.ns.PAGES) do
			for _, row in ipairs(page) do
				if row.key then
					rows[page.key .. "." .. row.key] = row
				end
			end
		end
		local function ids(row)
			local list = {}
			for _, choice in ipairs(W.ns.Choices(row)) do
				list[#list + 1] = choice[1]
			end
			return table.concat(list, ",")
		end
		check("ms-ptext: the rows are on the pages the spec names", rows["nameplatesText.nameShow"] and rows["nameplatesText.nameColour"] and rows["nameplatesText.nameCustomColour"]
			and rows["nameplatesText.healthTextColour"] and rows["nameplatesText.healthTextWhen"] and rows["nameplatesText.healthFormat"] and rows["nameplatesCast.castTextSize"]
			and rows["nameplatesCast.castTextOutline"] and rows["nameplatesCast.castTextColour"] and rows["nameplatesCast.castIconSize"] and rows["nameplatesCast.castSpark"]
			and rows["nameplatesCast.castShield"] and rows["nameplates.clickThroughFriendly"] and rows["nameplates.clickThroughEnemy"] and rows["nameplates.clickExtraX"]
			and rows["nameplates.clickExtraY"])
		check("ms-ptext: the health rows need Health text, the custom colour needs Custom", rows["nameplatesText.healthTextColour"].needs == "healthText"
			and rows["nameplatesText.healthTextWhen"].needs == "healthText" and rows["nameplatesText.healthFormat"].needs == "healthText"
			and rows["nameplatesText.nameCustomColour"].needs == "nameColour" and rows["nameplatesText.nameCustomColour"].needsIn[1] == "custom"
			and rows["nameplatesText.nameShow"].needs == nil and rows["nameplatesCast.castIconSize"].needs == nil)
		check("ms-ptext: the ranges", rows["nameplatesCast.castTextSize"].min == 50 and rows["nameplatesCast.castTextSize"].max == 200 and rows["nameplatesCast.castTextSize"].step == 5
			and rows["nameplatesCast.castIconSize"].min == 50 and rows["nameplatesCast.castIconSize"].max == 200 and rows["nameplatesCast.castIconSize"].step == 5
			and rows["nameplates.clickExtraX"].min == -10 and rows["nameplates.clickExtraX"].max == 30 and rows["nameplates.clickExtraX"].step == 1
			and rows["nameplates.clickExtraY"].min == -10 and rows["nameplates.clickExtraY"].max == 20 and rows["nameplates.clickExtraY"].step == 1)
		check("ms-ptext: the choices", ids(rows["nameplatesText.nameColour"]) == "game,white,reaction,custom" and ids(rows["nameplatesText.healthTextWhen"]) == "always,target"
			and ids(rows["nameplatesText.healthFormat"]) == "game,percent,value,both,missing")
		check("ms-ptext: the enemy click row has its tip", rows["nameplates.clickThroughEnemy"].tip == "Target with Tab or a key binding.")
		clean(W, "ms-ptext rows")
	end

	-- At the defaults the addon makes no call on any of these parts.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1")
		a.hit()
		a.update()
		a.updateName()
		a.updateHealth()
		local function count(raw, ...)
			local n = 0
			for _, name in ipairs({ ... }) do
				n = n + (raw.calls[name] or 0)
			end
			return n
		end
		check("ms-ptext: at the defaults the name has no alpha set and the game's colour", count(a.name, "SetAlpha") == 0 and a.name.alpha == 1 and M.vertex(a.name) == "0.90,0.10,0.10")
		check("ms-ptext: nor the health text strings", count(a.text, "SetAlpha", "SetTextColor") + count(a.left, "SetAlpha", "SetTextColor") + count(a.right, "SetAlpha", "SetTextColor") == 0)
		check("ms-ptext: nor the cast bar text, icon, spark or shield", count(a.castText, "SetFont", "SetTextColor") + count(a.castTarget, "SetFont", "SetTextColor") == 0
			and count(a.icon, "SetSize") == 0 and count(a.spark, "SetAlpha") == 0 and count(a.shield, "SetAlpha") == 0)
		check("ms-ptext: no health text of the addon's own is made", M.own(W) == nil)
		check("ms-ptext: and the hit area is the game's alone", a.addonHits() == 0 and a.points[1].offsetX == -10 and a.points[1].offsetY == 6.5, a.addonHits())
		clean(W, "ms-ptext defaults")
	end

	-- Show name and Name colour.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1")
		a.updateName()
		W.change("nameplates.nameShow", false)
		check("ms-ptext: Show name off fades the name and leaves it shown for the game", a.name.alpha == 0 and a.name.shown == true)
		a.updateName()
		check("ms-ptext: and the game's update of the name does not show it", a.name.alpha == 0)
		W.change("nameplates.nameShow", true)
		check("ms-ptext: Show name on again puts the alpha back", a.name.alpha == 1)
		W.change("nameplates.nameColour", "White")
		check("ms-ptext: Name colour White", M.vertex(a.name) == "1.00,1.00,1.00")
		a.updateName()
		check("ms-ptext: the colour is set over again after each update of the game's", M.vertex(a.name) == "1.00,1.00,1.00")
		W.change("nameplates.nameColour", "Custom")
		W.change("nameplates.nameCustomColour", "ff00ff00")
		check("ms-ptext: Name colour Custom is the colour of the row", M.vertex(a.name) == "0.00,1.00,0.00", M.vertex(a.name))
		W.change("nameplates.nameColour", "By reaction")
		check("ms-ptext: Name colour By reaction is the game's colour for the unit", M.vertex(a.name) == "0.20,0.80,0.30", M.vertex(a.name))
		W.change("nameplates.nameColour", "As the game has it")
		check("ms-ptext: and As the game has it gives back the colour the game had set", M.vertex(a.name) == "0.90,0.10,0.10", M.vertex(a.name))
		local before = a.name.calls.SetVertexColor
		a.update()
		check("ms-ptext: back at the game's colour a pass of the game sets no colour", a.name.calls.SetVertexColor == before, tostring(a.name.calls.SetVertexColor) .. " " .. tostring(before))
		W.change("nameplates.nameColour", "White")
		W.change("nameplates.enabled", false)
		check("ms-ptext: with the page off the name has the game's colour", M.vertex(a.name) == "0.90,0.10,0.10" and a.name.alpha == 1, M.vertex(a.name))
		clean(W, "ms-ptext name")

		-- A friendly plate that is not restyled is left alone.
		local F = M.world({ ["nameplates.friendly"] = false })
		local f = M.shown(F, "nameplate1", { friend = true })
		F.change("nameplates.nameShow", false)
		F.change("nameplates.nameColour", "White")
		f.updateName()
		check("ms-ptext: a friendly plate is left as the game has it while friendly plates are not restyled", f.name.alpha == 1 and M.vertex(f.name) == "0.90,0.10,0.10")
		clean(F, "ms-ptext name friendly")
	end

	-- Health text colour and visibility.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1")
		W.change("nameplates.healthTextColour", "ffff0000")
		check("ms-ptext: the colour of the health text is on all three strings", M.colour(a.text) == "1.00,0.00,0.00" and M.colour(a.left) == "1.00,0.00,0.00" and M.colour(a.right) == "1.00,0.00,0.00")
		a.text.textColour = { 0.8, 0.8, 0.8, 1 }
		W.gameOptions()
		W.flush()
		check("ms-ptext: the game resets the colour with its font object and it is set again", M.colour(a.text) == "1.00,0.00,0.00")
		W.change("nameplates.healthTextColour", "ffffffff")
		check("ms-ptext: white puts back the colour the game gave", M.colour(a.text) == "0.80,0.80,0.80" and M.colour(a.right) == "0.80,0.80,0.80")
		local before = a.text.calls.SetTextColor
		a.update()
		check("ms-ptext: and then no colour is set", a.text.calls.SetTextColor == before)
		W.change("nameplates.healthTextWhen", "Only on the target")
		check("ms-ptext: Only on the target fades the strings of a plate that is not the target", M.alphas(a) == "0,0,0", M.alphas(a))
		a.inner.isTarget = true
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-ptext: and shows them when the plate becomes the target", M.alphas(a) == "1,1,1", M.alphas(a))
		a.inner.isTarget = nil
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-ptext: and fades them again when it stops being the target", M.alphas(a) == "0,0,0", M.alphas(a))
		a.inner.isTarget = true
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		W.change("nameplates.healthText", false)
		check("ms-ptext: Health text off keeps them faded on the target", M.alphas(a) == "0,0,0", M.alphas(a))
		W.change("nameplates.healthText", true)
		W.change("nameplates.healthTextWhen", "Always")
		check("ms-ptext: Always shows them on every plate", M.alphas(a) == "1,1,1", M.alphas(a))
		clean(W, "ms-ptext health text")

		-- isTarget comes from a unit comparison the client can withhold.
		local T = M.world()
		local t = M.shown(T, "nameplate1")
		T.change("nameplates.healthTextWhen", "Only on the target")
		T.change("nameplates.healthFormat", "Percent")
		t.inner.isTarget = SECRET
		T.fire("PLAYER_TARGET_CHANGED")
		T.flush()
		check("ms-ptext: a withheld isTarget with Only on the target raises no error and stops no part", #T.errors == 0 and #T.violations == 0 and not has(T.status(), "stopped"), table.concat(T.errors, "|") .. " " .. T.status())
		check("ms-ptext: and the plate counts as not the target", M.alphas(t) == "0,0,0", M.alphas(t))
	end

	-- Health text format.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1")
		W.change("nameplates.healthFormat", "Percent")
		local own = M.own(W)
		check("ms-ptext: a format of the addon's own makes one font string, and fades the game's three", own ~= nil and M.alphas(a) == "0,0,0" and own.shown == true, tostring(own))
		check("ms-ptext: Percent is the health percent", own.text == "85%", tostring(own.text))
		W.hp.percent = 40
		a.updateHealth()
		check("ms-ptext: it follows the game's health update", own.text == "40%", tostring(own.text))
		W.change("nameplates.healthFormat", "Health")
		check("ms-ptext: Health is the health value, abbreviated", own.text == "12.5K", tostring(own.text))
		W.change("nameplates.healthFormat", "Health and percent")
		check("ms-ptext: Health and percent are in one text", own.text == "12.5K  40%", tostring(own.text))
		W.change("nameplates.healthFormat", "Health missing")
		check("ms-ptext: Health missing is the health the unit lacks", own.text == "2.5K", tostring(own.text))
		check("ms-ptext: the own text sits at the right end of the health bar", own.points[1][1] == "RIGHT" and own.points[1][4] == -4 and own.points[1][2] == a.healthBar)
		W.change("nameplates.healthTextColour", "ff00ff00")
		check("ms-ptext: it has the health text colour", M.colour(own) == "0.00,1.00,0.00", M.colour(own))
		a.text.shown, a.left.shown, a.right.shown = false, false, false
		a.updateHealth()
		check("ms-ptext: it is hidden while the game's health text is hidden", own.shown == false)
		a.text.shown = true
		a.updateHealth()
		check("ms-ptext: and shown with it", own.shown == true)
		W.hp.secret = true
		a.updateHealth()
		check("ms-ptext: a health the client withholds is drawn without being read", rawequal(own.text, SECRET) and #W.errors == 0, tostring(#W.errors))
		W.hp.secret = false
		W.change("nameplates.healthFormat", "As the game has it")
		check("ms-ptext: As the game has it empties and hides the own text and shows the game's three", own.text == "" and own.shown == false and M.alphas(a) == "1,1,1", M.alphas(a))
		W.change("nameplates.healthFormat", "Percent")
		a.inner.unit = nil
		W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		W.flush()
		check("ms-ptext: the own text is cleared when the plate loses its unit", own.text == "", tostring(own.text))
		clean(W, "ms-ptext format")

		-- The part stops alone when the client answers with errors, and the game's text comes back.
		local F = M.world({ ["nameplates.healthFormat"] = "percent" })
		F.hp.fault = "error"
		local plates = {}
		for i = 1, 3 do
			plates[i] = M.plate(F, { unit = "nameplate" .. i })
			F.showPlate("nameplate" .. i, plates[i])
		end
		F.flush()
		check("ms-ptext: a format that fails on three plates stops that part and the status says so", has(F.status(), "health text format stopped"), F.status())
		check("ms-ptext: the game's three strings are shown again on every plate", M.alphas(plates[1]) == "1,1,1" and M.alphas(plates[3]) == "1,1,1", M.alphas(plates[1]))
		check("ms-ptext: and the other parts go on without an error", #F.errors == 0 and #F.violations == 0, table.concat(F.errors, "|") .. table.concat(F.violations, "|"))
	end

	-- Cast bar text, icon, spark and shield.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1")
		W.change("nameplates.castTextSize", 150)
		check("ms-ptext: Spell name size is a percent of the game's size, on both strings", a.castText.font[2] == 15 and a.castTarget.font[2] == 15 and a.castText.font[3] == "OUTLINE", tostring(a.castText.font[2]))
		W.change("nameplates.castTextOutline", false)
		check("ms-ptext: Spell name outline off takes the outline from both", a.castText.font[3] == "" and a.castTarget.font[3] == "")
		W.change("nameplates.castTextColour", "ffff0000")
		check("ms-ptext: Spell name colour is on the spell name and not on the target name", M.colour(a.castText) == "1.00,0.00,0.00" and M.colour(a.castTarget) == "-", M.colour(a.castTarget))
		W.change("nameplates.castTextColour", "ffffffff")
		W.change("nameplates.castTextOutline", true)
		W.change("nameplates.castTextSize", 100)
		check("ms-ptext: at the defaults the game's font and colour are back", a.castText.font[2] == 10 and a.castText.font[3] == "OUTLINE" and M.colour(a.castText) == "0.90,0.90,0.90"
			and a.castTarget.font[2] == 10, tostring(a.castText.font[2]) .. tostring(a.castText.font[3]) .. M.colour(a.castText))
		W.change("nameplates.castIconSize", 150)
		check("ms-ptext: Spell icon size is a percent of the game's icon size", a.icon.width == 15 and a.icon.height == 15, tostring(a.icon.width))
		a.icon.width, a.icon.height = 10, 10
		W.gameOptions()
		W.flush()
		check("ms-ptext: the game sets the icon size again and the addon sets it after", a.icon.width == 15)
		W.change("nameplates.castIconSize", 100)
		check("ms-ptext: at 100 percent the game's size is set back", a.icon.width == 10 and a.icon.height == 10)
		local before = a.icon.calls.SetSize
		a.update()
		W.change("nameplates.castSpark", false)
		W.change("nameplates.castSpark", true)
		check("ms-ptext: and nothing sets it again", a.icon.calls.SetSize == before)
		W.change("nameplates.castSpark", false)
		check("ms-ptext: Spark off fades the spark and not the shield", a.spark.alpha == 0 and a.shield.alpha == 1)
		W.change("nameplates.castShield", false)
		check("ms-ptext: Shield off fades the shield", a.shield.alpha == 0 and a.spark.alpha == 0)
		W.change("nameplates.castSpark", true)
		W.change("nameplates.castShield", true)
		check("ms-ptext: both on put the alpha back", a.spark.alpha == 1 and a.shield.alpha == 1)
		W.change("nameplates.castIconSize", 150)
		W.change("nameplates.castSpark", false)
		W.change("nameplates.castTextSize", 120)
		W.change("nameplates.enabled", false)
		check("ms-ptext: with the page off the icon, spark and font are the game's", a.icon.width == 10 and a.spark.alpha == 1 and a.castText.font[2] == 10, tostring(a.icon.width))
		W.change("nameplates.enabled", true)
		check("ms-ptext: and with it on again they are set again", a.icon.width == 15 and a.spark.alpha == 0 and a.castText.font[2] == 12)
		clean(W, "ms-ptext cast")

		-- In combat the game does not take a size from addon code; it is set when combat ends.
		local C = M.world()
		local c = M.shown(C, "nameplate1")
		C.combat = true
		C.change("nameplates.castIconSize", 150)
		C.flush()
		check("ms-ptext: in combat the icon size is not set", c.icon.width == 10)
		C.combat = false
		C.fire("PLAYER_REGEN_ENABLED")
		C.flush()
		check("ms-ptext: when combat ends it is set", c.icon.width == 15, tostring(c.icon.width))
		clean(C, "ms-ptext cast combat")
	end

	-- The clickable area: set for a kind of plate with the insets, out of combat; the plate is never resized (the game anchors its bars to the plate size); nothing is hooked on a plate.
	do
		local W = M.world()
		local a = M.shown(W, "nameplate1", { friend = false })
		local k = W.click
		local function insets(kind)
			return table.concat(k.insets[kind], ",")
		end
		check("insthook: at the defaults no call is made on the area or the plate size", #k.calls == 0 and insets(1) == "0,0,0,0" and #k.sizeCalls == 0)
		W.change("nameplates.clickExtraX", 5)
		W.change("nameplates.clickExtraY", 2)
		check("insthook: the extra width and height grow the area of enemy plates by that much on each side, and the plate keeps the game's size", insets(1) == "-5,-5,-2,-2" and k.size[1] == 140 and k.size[2] == 50 and #k.sizeCalls == 0,
			insets(1) .. " " .. k.size[1] .. "x" .. k.size[2])
		check("insthook: friendly plates are widened too, as their plates are styled", insets(0) == "-5,-5,-2,-2")
		check("insthook: the game's per-plate area is not touched and UpdateHitTestArea is not hooked", a.addonHits() == 0 and not INSTHOOK.wrapped(W, a.inner, "UpdateHitTestArea") and #a.hits == 0)
		a.hit()
		check("insthook: the game's own call sets its area, and nothing follows it", a.addonHits() == 0 and a.points ~= nil and a.points[1].offsetX == -10)
		check("insthook: the calls come out of combat", #k.calls >= 2 and k.calls[1].combat == false and #W.violations == 0, #k.calls)
		W.gameOptions()
		W.flush()
		check("insthook: when the game sets its own plate size again, the insets stay and no call is made", k.size[1] == 140 and k.size[2] == 50 and insets(1) == "-5,-5,-2,-2" and #k.sizeCalls == 0, k.size[1] .. "x" .. k.size[2])
		local before = #k.calls
		W.flush()
		W.change("nameplates.healthFlat", false)
		check("ms-ptext: a setting that is not the click area makes no call on it", #k.calls == before)
		W.change("nameplates.clickExtraX", -10)
		check("ms-ptext: a negative width narrows the area, and the plate keeps the game's size", insets(1) == "10,10,-2,-2" and k.size[1] == 140 and k.size[2] == 50, insets(1) .. " " .. k.size[1])
		W.change("nameplates.clickExtraX", 0)
		W.change("nameplates.clickExtraY", 0)
		check("ms-ptext: at 0 and 0 the game's area is set back", insets(1) == "0,0,0,0" and k.size[1] == 140 and k.size[2] == 50, insets(1) .. " " .. k.size[1] .. "x" .. k.size[2])
		before = #k.calls
		W.change("nameplates.healthFlat", true)
		check("ms-ptext: and then no call is made", #k.calls == before)
		W.change("nameplates.clickThroughEnemy", true)
		check("ms-ptext: Click through enemy nameplates leaves nothing to click on enemy plates", insets(1) == "10000,10000,10000,10000" and insets(0) == "0,0,0,0", insets(1))
		W.change("nameplates.clickThroughFriendly", true)
		check("ms-ptext: Click through friendly nameplates leaves nothing to click on friendly plates", insets(0) == "10000,10000,10000,10000" and insets(1) == "10000,10000,10000,10000", insets(0))
		W.change("nameplates.friendly", false)
		check("ms-ptext: with friendly plates left to the game it does nothing to them", insets(0) == "0,0,0,0" and insets(1) == "10000,10000,10000,10000", insets(0))
		W.change("nameplates.friendly", true)
		W.change("nameplates.clickThroughEnemy", false)
		W.change("nameplates.clickThroughFriendly", false)
		check("ms-ptext: both off give the game's area back", insets(0) == "0,0,0,0" and insets(1) == "0,0,0,0")
		W.change("nameplates.clickExtraX", 7)
		W.change("nameplates.clickExtraY", 4)
		check("ms-ptext: the extra reaches both kinds, and the plate size is not changed", insets(0) == "-7,-7,-4,-4" and insets(1) == "-7,-7,-4,-4" and k.size[1] == 140 and k.size[2] == 50 and #k.sizeCalls == 0)
		W.change("nameplates.clickThroughEnemy", true)
		check("ms-ptext: a kind that clicks through keeps its own insets", insets(1) == "10000,10000,10000,10000" and insets(0) == "-7,-7,-4,-4" and k.size[1] == 140)
		W.change("nameplates.clickThroughEnemy", false)
		W.change("nameplates.enabled", false)
		check("ms-ptext: with the page off the game's area is back", insets(0) == "0,0,0,0" and insets(1) == "0,0,0,0" and k.size[1] == 140 and k.size[2] == 50, insets(1) .. " " .. k.size[1])
		W.change("nameplates.enabled", true)
		check("ms-ptext: and with it on they are set again", insets(1) == "-7,-7,-4,-4" and k.size[1] == 140)
		-- Combat: the game does not take either call from addon code.
		W.change("nameplates.clickExtraX", 3)
		W.combat = true
		W.change("nameplates.clickExtraX", 9)
		W.flush()
		check("ms-ptext: in combat no call is made", insets(1) == "-3,-3,-4,-4" and #W.violations == 0, insets(1))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("ms-ptext: when combat ends it is set", insets(1) == "-9,-9,-4,-4" and k.size[1] == 140, insets(1) .. " " .. k.size[1])
		clean(W, "ms-ptext click")

		-- Plates shown later have the area without any call on them.
		local S = M.world({ ["nameplates.clickExtraX"] = 6 })
		local s = M.shown(S, "nameplate1", { friend = false })
		S.flush()
		check("ms-ptext: with an extra width set at login the area is set once, before any plate", S.click.insets[1][1] == -6 and s.addonHits() == 0, #S.click.calls)
		clean(S, "ms-ptext click login")

		-- taintLog on: nothing is hooked on a method, and the area is set all the same.
		local T = M.world()
		T.cvars.taintLog = "2"
		local t = M.shown(T, "nameplate1", { friend = false })
		T.change("nameplates.clickExtraX", 6)
		T.flush()
		check("insthook: with taintLog 2 the area is set all the same", T.click.insets[1][1] == -6 and T.click.size[1] == 140 and t.addonHits() == 0, T.click.insets[1][1])
		clean(T, "ms-ptext click taintlog")

		-- The plate size is never set by the addon, whatever the game does with its options.
		local Z = M.world({ ["nameplates.clickExtraX"] = 5, ["nameplates.clickExtraY"] = 3 })
		M.shown(Z, "nameplate1", { friend = false })
		Z.flush()
		Z.gameOptions()
		Z.flush()
		Z.change("nameplates.clickExtraX", 8)
		Z.flush()
		check("insthook: the plate size is never set from the addon", #Z.click.sizeCalls == 0 and Z.click.size[1] == 140 and Z.click.size[2] == 50 and Z.click.insets[1][1] == -8, #Z.click.sizeCalls)

		-- The game refuses the call, or has none.
		local R = M.world({ ["nameplates.clickExtraX"] = 6 })
		R.env.C_NamePlateManager.SetNamePlateHitTestInsets = function() error("refused", 0) end
		M.shown(R, "nameplate1", { friend = false })
		R.change("nameplates.clickExtraX", 8)
		check("ms-ptext: a call the game refuses is said in the status and the game's area stays", has(R.status(), "Nameplate click area: the game refused the change"), R.status())
		check("ms-ptext: and no error reaches the player", #R.errors == 0 and #R.violations == 0, table.concat(R.errors, "|"))
		local N = M.world({ ["nameplates.clickExtraX"] = 6 })
		N.env.C_NamePlateManager = nil
		N.change("nameplates.clickExtraX", 9)
		check("ms-ptext: a client without the call says so", has(N.status(), "Nameplate click area: the game has no call to set it") and #N.errors == 0, N.status())
	end
end
-- >>> ms-ptext (end)
-- >>> ms-cast (begin)
-- Cast bars, personal resource display and swing timers (ms-09): the parts, the text and icon, the colours, the marks of the player bar, the
-- bar textures, and the swing timer's range, direction and idle look. The values are kept in one table: the main function of this file has
-- a limit on the locals a scope may hold.
do
	local M = { PX = {} }
	local PLAYER, PET, TARGET, FOCUS = "PlayerCastingBarFrame", "PetCastingBarFrame", "TargetFrameSpellBar", "FocusFrameSpellBar"
	-- The simulated game: spell texts and icons on every cast bar, the cast API of the player, and the methods of a swing timer.
	function M.dress(W)
		W.msInfo, W.msWorld = {}, 100
		local env = W.env
		env.UnitCastingInfo = function(unit)
			local c = W.msInfo[unit]
			if c and c.kind == "cast" then
				if c.secret then
					return SECRET, SECRET, SECRET, SECRET, SECRET
				end
				return c.name, "", c.icon, c.start, c.stop
			end
		end
		env.UnitChannelInfo = function(unit)
			local c = W.msInfo[unit]
			if c and c.kind == "channel" then
				return c.name, "", c.icon, c.start, c.stop
			end
		end
		env.GetNetStats = function() return 0, 0, 30, W.msWorld end
		env.PlayerFrame_AttachCastBar = function() end
		for _, name in ipairs(FH.CASTS) do
			local c = W.fills.cast[name]
			local protected = name == TARGET or name == FOCUS
			c.inner.width, c.inner.height = 208, 11
			c.inner.protected = protected or nil
			local text, textRaw = W.Rr(c.bar, nil, { kind = "FontString", protected = protected })
			local icon, iconRaw = W.Rr(c.bar, nil, { protected = protected })
			iconRaw.points = { { "RIGHT", c.bar, "LEFT", -5, 0 } }
			textRaw.justify = protected and "LEFT" or "CENTER"
			c.inner.Text, c.inner.Icon = text, icon
			c.text, c.textRaw, c.icon, c.iconRaw = text, textRaw, icon, iconRaw
		end
		-- The text of the personal resource display.
		W.msRes = {}
		for key, pair in pairs(W.prd) do
			for _, label in ipairs({ "TextString", "LeftText", "RightText" }) do
				local region, raw = W.Rr(pair[1], nil, { kind = "FontString" })
				pair[2][label] = region
				W.msRes[key .. label] = raw
			end
		end
		-- Swing timers: the labels, the direction of the fill, and the methods the game calls (Blizzard_SwingTimer.lua:257-268, 302-346, 408-431).
		W.msSwing = {}
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			local typeLabel, typeRaw = W.Rr(s.bar, nil, { kind = "FontString" })
			local timeLabel, timeRaw = W.Rr(s.bar, nil, { kind = "FontString" })
			typeRaw.textColour, timeRaw.textColour = { 1, 1, 1, 1 }, { 1, 1, 1, 1 }
			s.barRaw.TypeLabel, s.barRaw.TimeLabel = typeLabel, timeLabel
			s.barRaw.reverse = false
			s.barRaw.SetReverseFill = function(_, v)
				if type(v) ~= "boolean" then
					error("SetReverseFill: a boolean is expected", 0)
				end
				s.barRaw.reverse = v
				s.barRaw.reverseCalls = (s.barRaw.reverseCalls or 0) + 1
			end
			s.barRaw.GetReverseFill = function() return s.barRaw.reverse end
			local timer = s.timer
			local inner = s.inner
			local function colour(out) return out and { 1, 0.1, 0.1 } or { 1, 1, 1 } end
			inner.ApplyRangePresentation = function(self)
				local out = inner.isOutOfRange == true
				s.bar:SetAlpha(out and 0.4 or 1)
				local c = colour(out)
				typeLabel:SetTextColor(c[1], c[2], c[3])
				timeLabel:SetTextColor(c[1], c[2], c[3])
			end
			inner.ClearSwingTimer = function(self)
				inner.swingEndTime = nil
				s.pip:Hide()
			end
			inner.ResetSwingTimer = function(self, duration)
				inner.swingEndTime = W.now + duration
				s.pip:Show()
			end
			inner.InitializeBarPresentation = function(self)
				s.pipRaw.points = { { "RIGHT", s.fill, "RIGHT", 0, 0 } }
			end
			W.msSwing[name] = { s = s, typeRaw = typeRaw, timeRaw = timeRaw, timer = timer, inner = inner }
		end
	end
	function M.world(options, opts)
		-- The checks of the sizes were written for the width of the game, not the width of the personal resource display.
		options = options or {}
		options["castbars.playerMatch"] = options["castbars.playerMatch"] or "own"
		return FH.cast(options, opts, M.dress)
	end
	-- The colour of the edges of the outline of a bar.
	function M.edge(W, name)
		local look = W.look(W.fills.cast[name].bar)
		return look and FH.rgb(look.edges[1].color) or "no outline"
	end
	-- The textures of the addon's own on a bar that are not its cover: the spell icon and the latency zone.
	function M.marks(W, name)
		local list = {}
		local bar, fill = W.fills.cast[name].bar, W.rawOf[W.fills.cast[name].bar].fill
		for _, t in ipairs(W.addonTextures) do
			if t.owner == bar and not (t.points[1] and t.points[1][2] == fill) and t.layer == "OVERLAY" and (t.sublevel == 0 or t.sublevel == 1) and t.points[1] and t.points[1][2] == bar then
				list[#list + 1] = t
			end
		end
		return list
	end
	function M.start(W, kind, o)
		for _, name in ipairs(FH.CASTS) do
			W.fills.castStart(name, kind or "cast", o)
		end
		W.frame(2)
	end

	-- A world with every row at its default makes no call the game did not make.
	do
		local W = M.world()
		local base = FH.cast({ ["castbars.playerMatch"] = "own" })
		local textures = #W.addonTextures
		M.start(W, "cast")
		local calm = true
		for _, name in ipairs(FH.CASTS) do
			local c = W.fills.cast[name]
			calm = calm and c.sparkRaw.alpha == 1 and c.shieldRaw.alpha == 1 and c.textRaw.alpha == 1 and c.iconRaw.alpha == 1 and c.textRaw.calls.SetJustifyH == nil
				and c.textRaw.calls.SetTextColor == nil and c.textRaw.calls.SetAlpha == nil and c.iconRaw.calls.SetPoint == nil and c.iconRaw.calls.ClearAllPoints == nil
				and c.iconRaw.calls.SetAlpha == nil and c.sparkRaw.calls.SetAlpha == nil and c.shieldRaw.calls.SetAlpha == nil
		end
		check("ms-cast: at the defaults the spark, shield, spell name and icon are left as the game has them", calm)
		check("ms-cast: nothing is made but the five covers, and no hook is added", #W.addonTextures == textures + 5 and W.hooks == base.hooks and FH.plain(W), #W.addonTextures - textures .. " " .. FH.why(W))
		for _, name in ipairs(FH.CASTS) do
			W.fills.castInterrupt(name)
		end
		W.frame(2)
		check("ms-cast: the interrupted state is still seen", FH.shownColour(W, PLAYER) == FH.hex(FH.CAST_HEX.interrupted))
	end

	-- Spark and shield.
	do
		local W = M.world({ ["castbars.spark"] = false })
		local sparks, shields = true, true
		for _, name in ipairs(FH.CASTS) do
			sparks = sparks and W.fills.cast[name].sparkRaw.alpha == 0
			shields = shields and W.fills.cast[name].shieldRaw.alpha == 1
		end
		check("ms-cast: Spark off fades the spark of every bar and not the shield", sparks and shields)
		M.start(W, "cast", { notInterruptible = true })
		check("ms-cast: a shield state is still seen with the spark faded", FH.shownColour(W, PLAYER) == FH.hex(FH.CAST_HEX.shield) and FH.plain(W), FH.why(W))
		W.change("castbars.spark", true)
		W.change("castbars.shield", false)
		local back, gone = true, true
		for _, name in ipairs(FH.CASTS) do
			back = back and W.fills.cast[name].sparkRaw.alpha == 1
			gone = gone and W.fills.cast[name].shieldRaw.alpha == 0
		end
		check("ms-cast: Spark on again gives the alpha back, Uninterruptible shield icon off fades the shield", back and gone)
		W.change("castbars.enabled", false)
		check("ms-cast: the module off puts both back", W.fills.cast[PLAYER].shieldRaw.alpha == 1 and W.fills.cast[TARGET].shieldRaw.alpha == 1)
		W.change("castbars.enabled", true)
		check("ms-cast: and on again fades the shield again", W.fills.cast[PLAYER].shieldRaw.alpha == 0 and FH.plain(W), FH.why(W))
	end

	-- Spell name: shown, aligned, coloured.
	do
		local W = M.world({ ["castbars.textShow"] = false, ["castbars.textAlign"] = "right", ["castbars.textOwn"] = true, ["castbars.textColour"] = "ff336699" })
		local alpha, align, colour = true, true, true
		for _, name in ipairs(FH.CASTS) do
			local t = W.fills.cast[name].textRaw
			alpha = alpha and t.alpha == 0
			align = align and t.justify == "RIGHT"
			colour = colour and FH.rgb(t.textColour) == FH.hex("ff336699")
		end
		check("ms-cast: the spell name is faded, right aligned and coloured on every bar", alpha and align and colour and FH.plain(W), FH.why(W))
		local t, c = W.fills.cast[TARGET].textRaw, W.fills.cast[TARGET]
		W.change("castbars.textAlign", "Left")
		check("ms-cast: Left is set", t.justify == "LEFT")
		W.change("castbars.textAlign", "As the game has it")
		check("ms-cast: As the game has it puts the game's alignment back, read before the first change", t.justify == "LEFT" and W.fills.cast[PLAYER].textRaw.justify == "CENTER")
		W.change("castbars.textOwn", false)
		W.change("castbars.textShow", true)
		check("ms-cast: the game's colour is back and the name is shown", FH.rgb(t.textColour) == "1.000,1.000,1.000" and t.alpha == 1)
		-- The game gives the string a new font object when it lays the bar out.
		W.change("castbars.textAlign", "Centre")
		W.change("castbars.textOwn", true)
		local p = W.fills.cast[PLAYER].textRaw
		W.blizzard(function()
			p.justify = "LEFT"
			p.textColour = { 1, 0.8, 0, 1 }
			W.env.PlayerFrame_AttachCastBar()
		end)
		check("ms-cast: after the game lays the player bar out the alignment and colour are set again", p.justify == "CENTER" and FH.rgb(p.textColour) == FH.hex("ff336699"), p.justify .. " " .. FH.rgb(p.textColour))
		W.change("castbars.textOwn", false)
		check("ms-cast: and the colour the game gave the new font object is put back", FH.rgb(p.textColour) == "1.000,0.800,0.000" and FH.plain(W), FH.why(W))
		W.change("castbars.enabled", false)
		check("ms-cast: the module off gives every spell name its own look", W.fills.cast[PLAYER].textRaw.justify == "LEFT" and W.fills.cast[TARGET].textRaw.justify == "LEFT" and W.fills.cast[PLAYER].textRaw.alpha == 1, FH.plain(W), W.fills.cast[PLAYER].textRaw.justify)
	end

	-- Target and focus bar icon.
	do
		local W = M.world({ ["castbars.iconPos"] = "right" })
		local right = true
		for _, name in ipairs({ TARGET, FOCUS }) do
			local p = W.fills.cast[name].iconRaw.points[1]
			right = right and #W.fills.cast[name].iconRaw.points == 1 and p[1] == "LEFT" and p[2] == W.fills.cast[name].bar and p[3] == "RIGHT" and p[4] == 5 and p[5] == 0
		end
		check("ms-cast: Right of the bar anchors the icon of the target and focus bars to the right edge", right)
		check("ms-cast: the icon of the player and pet bars is not moved", W.fills.cast[PLAYER].iconRaw.calls.SetPoint == nil and W.fills.cast[PET].iconRaw.calls.ClearAllPoints == nil)
		W.change("castbars.iconPos", "Hidden")
		check("ms-cast: Hidden fades the icon and puts the game's anchor back", W.fills.cast[TARGET].iconRaw.alpha == 0 and W.fills.cast[TARGET].iconRaw.points[1][1] == "RIGHT"
			and W.fills.cast[TARGET].iconRaw.points[1][4] == -5 and W.fills.cast[PLAYER].iconRaw.alpha == 1)
		W.change("castbars.iconPos", "Left of the bar")
		check("ms-cast: Left of the bar shows it again", W.fills.cast[TARGET].iconRaw.alpha == 1 and W.fills.cast[FOCUS].iconRaw.points[1][1] == "RIGHT" and FH.plain(W), FH.why(W))
		W.combat = true
		W.change("castbars.iconPos", "Right of the bar")
		check("ms-cast: in combat the icon keeps its place", W.fills.cast[TARGET].iconRaw.points[1][1] == "RIGHT" and #W.violations == 0, table.concat(W.violations, "|"))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("ms-cast: and moves when the fight ends", W.fills.cast[TARGET].iconRaw.points[1][1] == "LEFT" and W.fills.cast[FOCUS].iconRaw.points[1][1] == "LEFT" and #W.violations == 0, table.concat(W.violations, "|"))
		W.combat = true
		W.change("castbars.iconPos", "Hidden")
		check("ms-cast: the icon fades in combat", W.fills.cast[TARGET].iconRaw.alpha == 0 and #W.violations == 0, table.concat(W.violations, "|"))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		check("ms-cast: and the anchor of the game is back at the end of it", W.fills.cast[TARGET].iconRaw.points[1][1] == "RIGHT" and FH.plain(W), FH.why(W))
	end

	-- Colours: the class colour of the player bar, the own colours of the target and focus bars.
	do
		local W = M.world({ ["castbars.playerClass"] = true, ["castbars.targetOwn"] = true, ["castbars.targetCast"] = "ff336699" })
		M.start(W, "cast")
		check("ms-cast: the player bar casts in the class colour, the pet bar in the cast colour", FH.shownColour(W, PLAYER) == FH.WARRIOR and FH.shownColour(W, "OverlayPlayerCastingBarFrame") == FH.WARRIOR
			and FH.shownColour(W, PET) == FH.hex(FH.CAST_HEX.cast))
		check("ms-cast: the target and focus bars cast in their own colour", FH.shownColour(W, TARGET) == FH.hex("ff336699") and FH.shownColour(W, FOCUS) == FH.hex("ff336699"))
		M.start(W, "channel")
		check("ms-cast: a channel is the class colour on the player bar and the own channel colour on target and focus", FH.shownColour(W, PLAYER) == FH.WARRIOR
			and FH.shownColour(W, TARGET) == FH.hex("ff4dbf59") and FH.shownColour(W, PET) == FH.hex(FH.CAST_HEX.channel))
		M.start(W, "cast", { notInterruptible = true })
		check("ms-cast: the shield state keeps its own colour on every bar", FH.shownColour(W, PLAYER) == FH.hex(FH.CAST_HEX.shield) and FH.shownColour(W, TARGET) == FH.hex(FH.CAST_HEX.shield))
		for _, name in ipairs(FH.CASTS) do
			W.fills.castInterrupt(name)
		end
		W.frame(2)
		check("ms-cast: so does the interrupted state", FH.shownColour(W, PLAYER) == FH.hex(FH.CAST_HEX.interrupted) and FH.shownColour(W, TARGET) == FH.hex(FH.CAST_HEX.interrupted))
		W.change("castbars.playerClass", false)
		M.start(W, "cast")
		check("ms-cast: Class colour off gives the cast colour back at once", FH.shownColour(W, PLAYER) == FH.hex(FH.CAST_HEX.cast))
		W.change("castbars.targetChannel", "ff102030")
		M.start(W, "channel")
		check("ms-cast: the own channel colour is the one set", FH.shownColour(W, FOCUS) == FH.hex("ff102030") and FH.plain(W), FH.why(W))
		W.change("castbars.targetOwn", false)
		M.start(W, "cast")
		check("ms-cast: Own colours off gives the Flat UI colours back", FH.shownColour(W, TARGET) == FH.hex(FH.CAST_HEX.cast))
		-- The colour is not known while the game withholds the state: the choice of the bar is the same.
		local X = M.world({ ["castbars.playerClass"] = true })
		X.fills.castStart(PLAYER, "cast", { secret = true, secretShield = true })
		X.frame(2)
		local cover = FH.cover(X, FH.bar(X, PLAYER))
		check("ms-cast: a withheld state of the player bar still takes the class colour for a cast", cover and cover.shown and FH.rgb(cover.vertex) == FH.WARRIOR and FH.plain(X), FH.why(X))
		local Y = M.world({ ["castbars.playerClass"] = true }, { fills = { class = "MAGE" } })
		Y.fills.castStart(PLAYER, "channel")
		Y.frame(2)
		check("ms-cast: the class is the player's own", FH.shownColour(Y, PLAYER) == FH.hex("ff69ccf0") or FH.shownColour(Y, PLAYER) == "0.410,0.800,0.940", FH.shownColour(Y, PLAYER))
		local Z = M.world({ ["castbars.playerClass"] = true }, { fills = { noClass = true } })
		Z.fills.castStart(PLAYER, "cast")
		Z.frame(2)
		check("ms-cast: a client that gives no class colour keeps the cast colour", FH.shownColour(Z, PLAYER) == FH.hex(FH.CAST_HEX.cast) and FH.plain(Z), FH.why(Z))
	end

	-- The border takes the colour of the cast.
	do
		local W = M.world({ ["castbars.stateBorder"] = true })
		check("ms-cast: before a cast the border has the Flat UI colour", M.edge(W, PLAYER) == "0.000,0.000,0.000" and M.edge(W, TARGET) == "0.000,0.000,0.000", M.edge(W, PLAYER))
		M.start(W, "cast")
		check("ms-cast: a cast gives the border the cast colour on every bar", M.edge(W, PLAYER) == FH.hex(FH.CAST_HEX.cast) and M.edge(W, TARGET) == FH.hex(FH.CAST_HEX.cast)
			and M.edge(W, PET) == FH.hex(FH.CAST_HEX.cast), M.edge(W, PLAYER))
		M.start(W, "channel")
		check("ms-cast: a channel the channel colour", M.edge(W, PLAYER) == FH.hex(FH.CAST_HEX.channel))
		M.start(W, "cast", { notInterruptible = true })
		check("ms-cast: a shield the shield colour", M.edge(W, FOCUS) == FH.hex(FH.CAST_HEX.shield))
		for _, name in ipairs(FH.CASTS) do
			W.fills.castHide(name)
		end
		W.frame(2)
		check("ms-cast: a bar the game hides has the Flat UI colour on its border again", M.edge(W, PLAYER) == "0.000,0.000,0.000" and M.edge(W, TARGET) == "0.000,0.000,0.000")
		M.start(W, "cast")
		W.change("castbars.stateBorder", false)
		W.frame(2)
		check("ms-cast: Border takes the cast colour off gives it back in a cast", M.edge(W, PLAYER) == "0.000,0.000,0.000")
		W.change("castbars.stateBorder", true)
		W.frame(2)
		check("ms-cast: and on again at once", M.edge(W, PLAYER) == FH.hex(FH.CAST_HEX.cast))
		W.fills.castStart(PLAYER, "cast", { secret = true, secretShield = true })
		W.frame(2)
		check("ms-cast: while the state is withheld the border keeps the Flat UI colour", M.edge(W, PLAYER) == "0.000,0.000,0.000" and FH.plain(W), M.edge(W, PLAYER) .. FH.why(W))
		W.change("castbars.flat", false)
		check("ms-cast: with the flat fill off the border has the Flat UI colour", M.edge(W, TARGET) == "0.000,0.000,0.000" and FH.plain(W), FH.why(W))
	end

	-- Bar textures.
	do
		local W = M.world({ ["general.barTexture"] = "soft", ["castbars.texture"] = "gloss" })
		M.start(W, "cast")
		local cover = FH.cover(W, FH.bar(W, PLAYER))
		check("ms-cast: the cast bars take the texture of their own row", cover and cover.file == W.ns.BarFile("gloss") and FH.plain(W), cover and tostring(cover.file))
		W.change("castbars.texture", "Flat")
		W.frame(2)
		cover = FH.cover(W, FH.bar(W, PLAYER))
		check("ms-cast: Flat is a solid colour whatever the Flat UI page chooses", cover.color and cover.color[1] == 1 and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast), tostring(cover.file) .. " " .. tostring(cover.color and table.concat(cover.color, ",")) .. " " .. FH.rgb(cover.vertex))
		W.change("castbars.texture", "Same as the Flat UI page")
		W.frame(2)
		check("ms-cast: Same as the Flat UI page follows it", cover.file == W.ns.BarFile("soft") and FH.rgb(cover.vertex) == FH.hex(FH.CAST_HEX.cast))
		W.change("general.barTexture", "Shaded")
		W.frame(2)
		check("ms-cast: and follows a change of it", cover.file == W.ns.BarFile("shaded"))
		local R = FH.res({ ["general.barTexture"] = "soft", ["resource.texture"] = "gloss" }, nil, M.dress)
		local health, power = FH.bars(R)
		check("ms-cast: the personal resource display takes the texture of its own row", FH.fill(R, health) == "file " .. R.ns.BarFile("gloss") and FH.fill(R, power) == "file " .. R.ns.BarFile("gloss") and FH.plain(R), FH.fill(R, health))
		R.change("resource.texture", "Flat")
		check("ms-cast: Flat is solid white on the resource bars whatever the Flat UI page chooses", FH.fill(R, health) == "colour 1.000,1.000,1.000")
		R.change("resource.texture", "Same as the Flat UI page")
		check("ms-cast: Same as the Flat UI page follows it", FH.fill(R, health) == "file " .. R.ns.BarFile("soft"))
		local S = FH.world({ saved = { options = { ["general.barTexture"] = "soft", ["swing.texture"] = "gloss", ["castbars.flat"] = false } } }, M.dress)
		local main = S.fills.swing.SwingTimerMainHandFrame
		check("ms-cast: swing timers take the texture of their own row", FH.fill(S, main.bar) == "file " .. S.ns.BarFile("gloss") and FH.plain(S), FH.fill(S, main.bar))
		S.change("swing.texture", "Flat")
		check("ms-cast: Flat is the solid colour of the timer", FH.fill(S, main.bar) == "colour " .. FH.hex(FH.SWING_HEX.SwingTimerMainHandFrame))
		S.change("swing.texture", "Same as the Flat UI page")
		check("ms-cast: Same as the Flat UI page follows it", FH.fill(S, main.bar) == "file " .. S.ns.BarFile("soft"))
	end

	-- The icon and the latency zone of the player bar.
	do
		local W = M.world({ ["castbars.playerIcon"] = true, ["castbars.latency"] = true })
		W.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		W.msInfo.pet = { kind = "cast", name = "Bite", icon = 132195, start = 1000, stop = 2000 }
		W.fills.castStart(PLAYER, "cast")
		W.fills.castStart(PET, "cast")
		W.fills.castStart(TARGET, "cast")
		W.frame(2)
		local player, pet, target = M.marks(W, PLAYER), M.marks(W, PET), M.marks(W, TARGET)
		local icon, zone
		for _, t in ipairs(player) do
			if t.file == 135812 then icon = t end
			if t.color and t.color[1] == 1 and t.color[2] == 0 and t.color[4] == 0.6 then zone = t end
		end
		check("ms-cast: the player bar has the spell icon, square at the height of the bar, left of it", icon and icon.shown and icon.width == 11 and icon.height == 11
			and icon.points[1][1] == "RIGHT" and icon.points[1][2] == W.fills.cast[PLAYER].bar and icon.points[1][3] == "LEFT" and W.ns.Own[icon] == true, icon and tostring(icon.width))
		check("ms-cast: the latency zone is at the right end of a cast, as wide as the delay of the cast, red at 0.6", zone and zone.shown and math.abs(zone.width - 100 / 2000 * 208) < 0.001
			and zone.points[1][1] == "TOPRIGHT" and zone.points[2][1] == "BOTTOMRIGHT" and W.ns.Own[zone] == true, zone and tostring(zone.width))
		check("ms-cast: the pet bar has an icon and no latency zone, the target bar has neither", #pet == 1 and pet[1].file == 132195 and #target == 0, #pet .. " " .. #target)
		W.msWorld = 5000
		W.frame(2)
		check("ms-cast: a delay longer than the cast fills the bar", math.abs(zone.width - 208) < 0.001)
		W.fills.castFinish(PLAYER)
		W.msInfo.player = { kind = "channel", name = "Drain", icon = 136169, start = 0, stop = 4000 }
		W.msWorld = 100
		W.fills.castStart(PLAYER, "channel")
		W.frame(2)
		local after = M.marks(W, PLAYER)
		local channelZone
		for _, t in ipairs(after) do
			if t.color and t.color[4] == 0.6 then channelZone = t end
		end
		check("ms-cast: a channel has it at the left end, with the icon of the channel", channelZone and channelZone.points[1][1] == "TOPLEFT" and icon.file == 136169 and #after == 2
			and math.abs(channelZone.width - 100 / 4000 * 208) < 0.001, channelZone and channelZone.points[1][1] or "none")
		W.fills.castInterrupt(PLAYER)
		W.frame(2)
		check("ms-cast: an interrupted bar shows neither", not icon.shown and not channelZone.shown)
		W.fills.castHide(PLAYER)
		W.msInfo.player = { kind = "cast", secret = true }
		W.fills.castStart(PLAYER, "cast")
		W.frame(2)
		check("ms-cast: withheld numbers hide both and raise nothing", not icon.shown and not channelZone.shown and FH.plain(W), FH.why(W))
		W.msInfo.player = nil
		W.frame(2)
		check("ms-cast: so does a bar that is shown with no cast", not icon.shown and not channelZone.shown)
		W.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		W.frame(2)
		W.change("castbars.latency", false)
		W.frame(2)
		check("ms-cast: Latency zone off hides the zone and keeps the icon", icon.shown and not channelZone.shown)
		W.change("castbars.playerIcon", false)
		W.frame(2)
		check("ms-cast: Spell icon off hides it", not icon.shown and FH.plain(W), FH.why(W))
		local nets = newWorld({ fills = true })
		check("ms-cast: nothing is made for a cast bar at the defaults", #M.marks(nets, PLAYER) == 0)
	end

	-- The marks in a client that withholds or lacks what they need.
	do
		local W = M.world({ ["castbars.playerIcon"] = true, ["castbars.latency"] = true })
		W.env.GetNetStats = nil
		W.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		W.fills.castStart(PLAYER, "cast")
		W.frame(2)
		local list = M.marks(W, PLAYER)
		check("ms-cast: without GetNetStats the icon shows and there is no zone", #list == 1 and list[1].file == 135812 and FH.plain(W), #list .. FH.why(W))
		local X = M.world({ ["castbars.playerIcon"] = true })
		X.env.UnitCastingInfo = function() error("UnitCastingInfo failed", 0) end
		X.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		M.start(X, "cast")
		X.frame(4)
		check("ms-cast: marks that fail on three bars stop with one line, and the cover goes on", has(X.status(), "Cast bars: cast marks stopped. ") and FH.shownColour(X, PLAYER) == FH.hex(FH.CAST_HEX.cast)
			and #X.out == 1 and #X.violations == 0 and #M.marks(X, PLAYER) == 0, X.status() .. table.concat(X.out, "|"))
	end

	-- Personal resource display: the text.
	do
		local W = FH.res(nil, nil, M.dress)
		local calm = true
		for _, raw in pairs(W.msRes) do
			calm = calm and raw.alpha == 1 and raw.calls.SetTextColor == nil and raw.calls.SetAlpha == nil
		end
		check("ms-cast: the text of the resource bars is left alone at the defaults", calm and FH.plain(W), FH.why(W))
		W.change("resource.percent", false)
		check("ms-cast: Percentage text off fades the left text only", W.msRes.healthLeftText.alpha == 0 and W.msRes.powerLeftText.alpha == 0 and W.msRes.healthRightText.alpha == 1
			and W.msRes.healthTextString.alpha == 1)
		W.change("resource.value", false)
		check("ms-cast: Value text off fades the right text and the whole string", W.msRes.healthRightText.alpha == 0 and W.msRes.powerTextString.alpha == 0)
		W.change("resource.percent", true)
		check("ms-cast: Percentage text on shows the left text again", W.msRes.altLeftText.alpha == 1 and W.msRes.altRightText.alpha == 0)
		W.change("resource.value", true)
		W.change("resource.text", false)
		check("ms-cast: Health and power numbers off still fades all of them", W.msRes.healthLeftText.alpha == 0 and W.msRes.healthRightText.alpha == 0 and W.msRes.healthTextString.alpha == 0)
		W.change("resource.text", true)
		W.change("resource.textOwn", true)
		W.change("resource.textColour", "ff336699")
		check("ms-cast: Own text colour sets the colour of the three texts of each bar", FH.rgb(W.msRes.healthLeftText.textColour) == FH.hex("ff336699") and FH.rgb(W.msRes.powerRightText.textColour) == FH.hex("ff336699")
			and FH.rgb(W.msRes.altTextString.textColour) == FH.hex("ff336699"))
		W.change("resource.textSize", 150)
		check("ms-cast: a text size keeps the colour", FH.rgb(W.msRes.healthLeftText.textColour) == FH.hex("ff336699"))
		W.change("resource.textOwn", false)
		check("ms-cast: Own text colour off gives the game's colour back", FH.rgb(W.msRes.healthLeftText.textColour) == "1.000,1.000,1.000" and FH.plain(W), FH.why(W))
	end

	-- What the game does to a swing timer, and what it tells the addon: the call, then the event, and the next frame.
	function M.swRange(W, m, out)
		W.blizzard(function() m.inner.isOutOfRange = out m.timer:ApplyRangePresentation() end)
		W.fire("PLAYER_SWING_RANGE_UPDATE", 0, not out, true)
		W.tick()
	end
	function M.swStart(W, m, duration)
		W.blizzard(function() m.timer:ResetSwingTimer(duration) end)
		W.fire("PLAYER_SWING", duration, 0)
		W.tick()
	end
	function M.swStop(W, m)
		W.blizzard(function() m.timer:ClearSwingTimer() end)
		W.frame(1)
	end
	function M.hears(W, event)
		for _, frame in ipairs(W.eventFrames) do
			if frame.events[event] then
				return true
			end
		end
		return false
	end

	-- Swing timers: range, direction and idle.
	do
		local W = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.idle"] = "show", ["swing.width"] = "game", ["castbars.playerMatch"] = "own" } } }, M.dress)
		local base = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.idle"] = "show", ["swing.width"] = "game", ["castbars.playerMatch"] = "own" } } })
		local name = FH.SWING[1]
		local m = W.msSwing[name]
		check("ms-cast: at Always no hook is added to a swing timer and nothing is set", W.hooks == base.hooks and m.s.barRaw.reverseCalls == nil and m.typeRaw.calls.SetTextColor == nil and FH.plain(W), FH.why(W))
		M.swRange(W, m, true)
		check("ms-cast: out of range the game's own look stays", m.s.barRaw.alpha == 0.4 and FH.rgb(m.typeRaw.textColour) == "1.000,0.100,0.100")
		M.swRange(W, m, false)
		local hooks = W.hooks
		check("ms-cast: at the defaults the range events are not heard", not M.hears(W, "PLAYER_SWING_RANGE_UPDATE"))
		W.change("swing.rangeAlpha", 70)
		check("ms-cast: Out of range opacity is followed once it is not the game's, from events and not from a hook", M.hears(W, "PLAYER_SWING_RANGE_UPDATE") and W.hooks == hooks)
		M.swRange(W, m, true)
		check("ms-cast: out of range the bar has the opacity of the row", math.abs(m.s.barRaw.alpha - 0.7) < 0.0001, m.s.barRaw.alpha)
		W.change("swing.rangeAlpha", 100)
		check("ms-cast: 100 percent is full opacity while out of range", m.s.barRaw.alpha == 1)
		W.change("swing.rangeAlpha", 40)
		check("ms-cast: 40 percent is the game's own value again at once", math.abs(m.s.barRaw.alpha - 0.4) < 0.0001)
		M.swRange(W, m, false)
		check("ms-cast: back in range the game's alpha is 1", m.s.barRaw.alpha == 1 and FH.plain(W), FH.why(W))
		W.change("swing.textOwn", true)
		W.change("swing.textColour", "ff336699")
		W.change("swing.rangeTextColour", "ff102030")
		check("ms-cast: Own text colour sets both labels in range", FH.rgb(m.typeRaw.textColour) == FH.hex("ff336699") and FH.rgb(m.timeRaw.textColour) == FH.hex("ff336699"))
		M.swRange(W, m, true)
		check("ms-cast: and the other colour out of range, after the game set its own", FH.rgb(m.typeRaw.textColour) == FH.hex("ff102030") and FH.rgb(m.timeRaw.textColour) == FH.hex("ff102030"))
		W.change("swing.textOwn", false)
		check("ms-cast: Own text colour off gives the game's red out of range", FH.rgb(m.typeRaw.textColour) == "1.000,0.100,0.100")
		M.swRange(W, m, false)
		check("ms-cast: and the game sets white in range", FH.rgb(m.typeRaw.textColour) == "1.000,1.000,1.000")
		-- Direction.
		W.change("swing.reverse", true)
		check("ms-cast: Fill from the right reverses the fill and anchors the spark to the left of it", m.s.barRaw.reverse == true and m.s.pipRaw.points[1][1] == "LEFT" and m.s.pipRaw.points[1][3] == "LEFT"
			and m.s.pipRaw.points[1][2] == m.s.fill and #m.s.pipRaw.points == 1)
		W.blizzard(function() m.timer:InitializeBarPresentation() end)
		W.fire("WEAPON_SLOT_CHANGED")
		W.tick()
		check("ms-cast: when the game anchors the spark again it follows on the next frame after an event", m.s.pipRaw.points[1][1] == "LEFT" and m.s.barRaw.reverse == true)
		W.change("swing.reverse", false)
		check("ms-cast: off puts the direction and the anchor back", m.s.barRaw.reverse == false and m.s.pipRaw.points[1][1] == "RIGHT" and m.s.pipRaw.points[1][3] == "RIGHT" and FH.plain(W), FH.why(W))
		-- Idle.
		M.swStart(W, m, 2)
		W.change("swing.idle", "Only while swinging")
		check("ms-cast: a timer that is swinging keeps its bar", m.s.barRaw.shown == true)
		M.swStop(W, m)
		check("ms-cast: the bar of a timer that stopped swinging is hidden", m.s.barRaw.shown == false)
		M.swStart(W, m, 2)
		check("ms-cast: and shown when a swing starts", m.s.barRaw.shown == true)
		M.swStop(W, m)
		W.change("swing.idle", "Always")
		check("ms-cast: Always shows the bar at once", m.s.barRaw.shown == true and FH.plain(W), FH.why(W))
		W.change("swing.idle", "Only while swinging")
		W.change("swing.enabled", false)
		check("ms-cast: the module off shows it", m.s.barRaw.shown == true)
		W.change("swing.enabled", true)
		check("ms-cast: and on again hides it", m.s.barRaw.shown == false and FH.plain(W), FH.why(W))
	end
	-- Rows with their own values, in a world that lacks what a row needs.
	do
		local W = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.reverse"] = true, ["swing.idle"] = "hide" } } }, function(X)
			M.dress(X)
			for _, name in ipairs(FH.SWING) do
				X.fills.swing[name].barRaw.SetReverseFill = function() error("refused", 0) end
			end
		end)
		check("ms-cast: a refused direction says so in one line and raises nothing", has(W.status(), "refused to fill a timer from the right") and #W.errors == 0, W.status())
	end
	-- More: what the game sets again, what stops, and the bars in a fight.
	do
		-- A game that sets the alignment and colour of the spell name itself, with no layout hook run.
		local W = M.world({ ["castbars.textAlign"] = "right", ["castbars.textOwn"] = true, ["castbars.textColour"] = "ff336699" })
		local p = W.fills.cast[PLAYER].textRaw
		W.blizzard(function() p.justify = "LEFT" p.textColour = { 1, 0.8, 0, 1 } end)
		W.change("castbars.textAlign", "As the game has it")
		W.change("castbars.textOwn", false)
		check("ms-cast: what the game set itself is left as it is when a row goes back to the game's", p.justify == "LEFT" and FH.rgb(p.textColour) == "1.000,0.800,0.000", p.justify .. " " .. FH.rgb(p.textColour))
		local X = M.world({ ["castbars.textAlign"] = "right" })
		local t = X.fills.cast[PLAYER].textRaw
		X.blizzard(function() t.justify = "LEFT" X.env.PlayerFrame_AttachCastBar() end)
		check("ms-cast: after the layout hook the row is set again", t.justify == "RIGHT")
		X.change("castbars.textAlign", "As the game has it")
		check("ms-cast: and the game's alignment is the one it had at the last layout", t.justify == "LEFT", t.justify)
		-- The icon anchor of the game is read once.
		local I = M.world({ ["castbars.iconPos"] = "right" })
		I.change("castbars.textSize", 110)
		I.change("castbars.iconPos", "Left of the bar")
		check("ms-cast: the anchor of the game is the one read before the icon moved", I.fills.cast[TARGET].iconRaw.points[1][1] == "RIGHT" and I.fills.cast[TARGET].iconRaw.points[1][4] == -5)
		-- A colour changed during a cast.
		local C = M.world({ ["castbars.targetOwn"] = true })
		C.fills.castStart(TARGET, "cast")
		C.frame(2)
		C.change("castbars.targetCast", "ff112233")
		C.frame(2)
		check("ms-cast: a colour changed in the middle of a cast shows at once", FH.shownColour(C, TARGET) == FH.hex("ff112233"))
		local V = M.world({ ["castbars.playerClass"] = true })
		V.fills.castStart(PLAYER, "cast", { secret = true, secretShield = true })
		V.frame(2)
		V.change("castbars.castColour", "ff336699")
		V.change("castbars.playerClass", false)
		V.frame(2)
		local cover = FH.cover(V, FH.bar(V, PLAYER))
		check("ms-cast: a colour changed while the state is withheld shows too", cover and FH.rgb(cover.vertex) == FH.hex("ff336699"), cover and FH.rgb(cover.vertex))
		-- An empowered cast has no cover, a hidden or stopped bar has no marks.
		local E = M.world({ ["castbars.stateBorder"] = true, ["castbars.playerIcon"] = true, ["castbars.latency"] = true })
		E.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		E.fills.castStart(PLAYER, "cast")
		E.frame(2)
		local marks = M.marks(E, PLAYER)
		check("ms-cast: marks are there before the cast changes", #marks == 2 and marks[1].shown and marks[2].shown and M.edge(E, PLAYER) == FH.hex(FH.CAST_HEX.cast))
		E.fills.cast[PLAYER].inner.height = 20
		E.frame(2)
		local icon
		for _, m in ipairs(marks) do if m.file == 135812 then icon = m end end
		check("ms-cast: the icon is as high as the bar", icon.height == 20 and icon.width == 20, icon.height)
		E.fills.castStart(PLAYER, "empowered")
		E.frame(2)
		check("ms-cast: a cast with no cover has neither marks nor a coloured border", not marks[1].shown and not marks[2].shown and M.edge(E, PLAYER) == "0.000,0.000,0.000", M.edge(E, PLAYER))
		E.fills.castStart(PLAYER, "cast")
		E.frame(2)
		E.fills.castHide(PLAYER)
		E.frame(2)
		check("ms-cast: a bar the game hides has no marks", not marks[1].shown and not marks[2].shown)
		E.fills.castStart(PLAYER, "cast")
		E.frame(2)
		E.change("castbars.flat", false)
		check("ms-cast: the flat fill off takes the marks away", not marks[1].shown and not marks[2].shown and FH.plain(E), FH.why(E))
		-- Marks that stop hide.
		local S = M.world({ ["castbars.playerIcon"] = true })
		S.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		M.start(S, "cast")
		local shown = M.marks(S, PLAYER)
		S.env.UnitCastingInfo = function() error("UnitCastingInfo failed", 0) end
		S.frame(4)
		check("ms-cast: marks that were shown are hidden when the part stops", #shown == 1 and not shown[1].shown and has(S.status(), "cast marks stopped"))
		-- A protected bar in a fight gets no mark until it ends.
		local Q = M.world({ ["castbars.playerIcon"] = true })
		Q.msInfo.player = { kind = "cast", name = "Fireball", icon = 135812, start = 1000, stop = 3000 }
		Q.fills.cast[PLAYER].inner.protected = true
		Q.combat = true
		Q.fills.castStart(PLAYER, "cast")
		Q.frame(2)
		check("ms-cast: no mark is made on a protected bar in a fight", #M.marks(Q, PLAYER) == 0 and #Q.violations == 0, table.concat(Q.violations, "|"))
		Q.combat = false
		Q.frame(2)
		check("ms-cast: and it is made when the fight ends", #M.marks(Q, PLAYER) == 1 and #Q.violations == 0, table.concat(Q.violations, "|"))
		-- Swing timers: Edit Mode, the whole outline, the game's own colours.
		local T = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.rangeAlpha"] = 70 } } }, M.dress)
		local m = T.msSwing[FH.SWING[1]]
		m.inner.isInEditMode = true
		M.swRange(T, m, true)
		check("ms-cast: a timer in Edit Mode is in range and keeps the game's alpha", m.s.barRaw.alpha == 0.4, m.s.barRaw.alpha)
		local G = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.textOwn"] = true } } }, function(Y)
			M.dress(Y)
			Y.env.RED_FONT_COLOR = { GetRGB = function() return 1, 0, 0 end }
			Y.env.HIGHLIGHT_FONT_COLOR = { GetRGB = function() return 0.9, 0.9, 0.9 end }
		end)
		local g = G.msSwing[FH.SWING[1]]
		G.change("swing.textOwn", false)
		check("ms-cast: the game's colour in range is its highlight colour", FH.rgb(g.typeRaw.textColour) == "0.900,0.900,0.900", FH.rgb(g.typeRaw.textColour))
		local O = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.outline"] = "frame", ["swing.idle"] = "hide" } } }, M.dress)
		local o = O.msSwing[FH.SWING[1]]
		local look = O.look(o.timer)
		check("ms-cast: the outline of the whole timer is hidden while it is idle", look and not look.edges[1].shown, look and tostring(look.edges[1].shown))
		M.swStart(O, o, 2)
		check("ms-cast: and shown while it swings", O.look(o.timer).edges[1].shown == true)
	end
	-- Show the timer: In combat.
	do
		local fight, shown = { on = false }, function(m) return m.s.barRaw.shown end
		local function world(options)
			options["castbars.flat"] = false
			return FH.world({ saved = { options = options } }, function(X)
				M.dress(X)
				X.env.UnitAffectingCombat = function() return fight.on end
			end)
		end
		local function turn(W, on)
			fight.on = on
			W.fire("PLAYER_IN_COMBAT_CHANGED", on)
			W.tick()
		end
		fight.on = false
		local W = world({})
		local m = W.msSwing[FH.SWING[1]]
		check("swing idle: In combat is the default and hides the bar out of combat", shown(m) == false and FH.plain(W), FH.why(W))
		turn(W, true)
		check("swing idle: it shows the bar after the combat event", shown(m) == true and FH.plain(W), FH.why(W))
		check("swing idle: the events are heard for In combat", M.hears(W, "PLAYER_IN_COMBAT_CHANGED") and M.hears(W, "PLAYER_SWING"))
		M.swStart(W, m, 2)
		M.swStop(W, m)
		check("swing idle: in a fight the empty bar stays between swings", shown(m) == true)
		turn(W, false)
		check("swing idle: and goes when the fight ends", shown(m) == false)
		m.inner.isInEditMode = true
		turn(W, false)
		check("swing idle: Edit Mode open shows it", shown(m) == true)
		m.inner.isInEditMode = false
		turn(W, false)
		W.change("swing.idle", "Always")
		check("swing idle: Always shows it out of combat", shown(m) == true)
		W.change("swing.idle", "In combat")
		check("swing idle: and In combat hides it again", shown(m) == false)
		fight.on = false
		local H = world({ ["swing.idle"] = "hide" })
		local h = H.msSwing[FH.SWING[1]]
		turn(H, true)
		check("swing idle: Only while swinging hides the bar in a fight when no swing runs", shown(h) == false)
		M.swStart(H, h, 2)
		check("swing idle: and shows it while a swing runs", shown(h) == true)
		fight.on = false
		local S = world({ ["swing.idle"] = "show" })
		check("swing idle: a saved Always stays Always", shown(S.msSwing[FH.SWING[1]]) == true)
	end
end
-- >>> ms-cast (end)
-- Frame scale rows and the pixel-perfect scale.
do
	local K = { mw = suiteKit.mw, mwBefore = suiteKit.mwBefore, opt = suiteKit.opt, entry = suiteKit.entry, allClean = suiteKit.allClean,
		problems = suiteKit.problems, outText = suiteKit.outText, layout = { systems = true, allSystems = { "TargetFrame", "FocusFrame", "PartyFrame", "BossTargetFrameContainer", "CompactRaidFrameContainer", "PetFrame" } } }
	K.world = function(options, spots)
		return K.mwBefore({ layout = K.layout, saved = K.opt(options or {}, spots) }, function(W)
			W.told = {}
			local original = W.env.Settings.NotifyUpdate
			W.env.Settings.NotifyUpdate = function(variable)
				W.told[#W.told + 1] = variable
				return original(variable)
			end
		end)
	end
	K.heard = function(W, variable)
		for _, v in ipairs(W.told) do
			if v == variable then
				return true
			end
		end
		return false
	end
	local W = K.world()
	local ns = W.ns
	check("ms-scale: six frame rows, from 50% to 200%, and no row for the pet frame, whose size is its own setting", ns.Get("unitframes.playerScale") == 100 and ns.Get("unitframes.targetScale") == 100
		and ns.Get("unitframes.focusScale") == 100 and ns.Get("unitframes.partyScale") == 100 and ns.Get("unitframes.bossScale") == 100 and ns.Get("unitframes.raidScale") == 100
		and ns.Get("unitframes.petScale") == nil)
	check("ms-scale: a row at 100 makes no spot and no call", K.entry(W, "PlayerFrame") == nil and K.allClean(W), K.problems(W))
	local resizes, resizeAll = 0, ns.ResizeAll
	ns.ResizeAll = function(...)
		resizes = resizes + 1
		return resizeAll(...)
	end
	ns.Set("unitframes.playerScale", 150)
	check("ms-scale: a change of scale asks for the lengths in the units of a frame again, once", resizes == 1, resizes)
	check("ms-scale: the player frame row sets its scale and saves its place", K.entry(W, "PlayerFrame") ~= nil and near(K.entry(W, "PlayerFrame").scale, 1.5)
		and near(W.env.PlayerFrame:GetScale(), 1.5) and ns.Get("unitframes.playerScale") == 150 and K.allClean(W), K.problems(W))
	check("ms-scale: the row keeps no value in the profile", not ns.IsSet("unitframes.playerScale"))
	ns.Set("unitframes.playerScale", 300)
	check("ms-scale: a value past the end of the range is cut to 200", ns.Get("unitframes.playerScale") == 200 and near(K.entry(W, "PlayerFrame").scale, 2), ns.Get("unitframes.playerScale"))
	ns.Set("unitframes.playerScale", 70)
	check("ms-scale: below 100 the frame shrinks", near(W.env.PlayerFrame:GetScale(), 0.7) and ns.Get("unitframes.playerScale") == 70, W.env.PlayerFrame:GetScale())
	ns.Set("unitframes.playerScale", 100)
	check("ms-scale: 100 gives the game's scale back and keeps the place", K.entry(W, "PlayerFrame") ~= nil and K.entry(W, "PlayerFrame").scale == nil and near(W.env.PlayerFrame:GetScale(), 1)
		and ns.Get("unitframes.playerScale") == 100 and K.allClean(W), K.problems(W))
	W.slash("move")
	W.keys.ctrl = true
	W.wheel("Player frame", 1)
	W.wheel("Player frame", 1)
	check("ms-scale: Ctrl and scroll on the handle moves the row, and the game is asked to read it again", ns.Get("unitframes.playerScale") == 110 and K.heard(W, "FLATUI_UNITFRAMES_PLAYERSCALE")
		and near(W.env.PlayerFrame:GetScale(), 1.1), table.concat(W.told, ","))
	W.keys.ctrl = false
	W.told = {}
	W.rightClick("Player frame")
	check("ms-scale: putting the frame back puts the row back and tells the game", ns.Get("unitframes.playerScale") == 100 and K.entry(W, "PlayerFrame") == nil and near(W.env.PlayerFrame:GetScale(), 1)
		and K.heard(W, "FLATUI_UNITFRAMES_PLAYERSCALE"), ns.Get("unitframes.playerScale"))
	local each, wrong = { { "target", "Target frame", "TargetFrame" }, { "focus", "Focus frame", "FocusFrame" }, { "party", "Party frames", "PartyFrame" },
		{ "boss", "Boss frames", "BossTargetFrameContainer" }, { "raid", "Raid frames", "CompactRaidFrameContainer" } }, {}
	W.keys.ctrl = true
	for _, one in ipairs(each) do
		local path = "unitframes." .. one[1] .. "Scale"
		W.told = {}
		ns.Set(path, 120)
		local viaRow = near(W.env[one[3]]:GetScale(), 1.2) and K.entry(W, one[3]) ~= nil and ns.Get(path) == 120
		W.told = {}
		local turned = pcall(W.wheel, one[2], 1)
		if not (turned and viaRow and ns.Get(path) == 125 and K.heard(W, "FLATUI_" .. path:upper():gsub("%.", "_")) and near(W.env[one[3]]:GetScale(), 1.25)) then
			wrong[#wrong + 1] = one[1]
		end
	end
	W.keys.ctrl = false
	check("ms-scale: each of the other five rows sets its frame and follows Ctrl and scroll on its handle", #wrong == 0 and K.allClean(W), table.concat(wrong, ",") .. " " .. table.concat(W.shownHandles(), ",") .. K.problems(W))
	W.ns.SetMoverScale({ frame = "PetFrame" }, 150)
	check("ms-scale: the pet frame takes no scale here, its size is its own setting", K.entry(W, "PetFrame") == nil and near(W.env.PetFrame:GetScale(), 1) and K.allClean(W))
	local none = K.world({ ["movers.enabled"] = false })
	none.ns.Set("unitframes.playerScale", 150)
	check("ms-scale: with Move frames off nothing is set, and the line says so", K.entry(none, "PlayerFrame") == nil and K.outText(none):find("Move frames", 1, true) ~= nil, K.outText(none))
	none.told = {}
	none.ns.Set("unitframes.playerScale", 120)
	none.ns.Set("unitframes.playerScale", 130)
	none.advance(0.1)
	local lines = 0
	for _ in K.outText(none):gmatch("Move frames") do
		lines = lines + 1
	end
	check("ms-scale: a refused slider says it once and the row goes back to the applied scale", lines == 1 and K.heard(none, "FLATUI_UNITFRAMES_PLAYERSCALE") and none.ns.Get("unitframes.playerScale") == 100, lines .. " " .. table.concat(none.told, ","))
	local off = K.world({ ["movers.systems"] = false })
	off.ns.Set("unitframes.targetScale", 150)
	check("ms-scale: with Move the game's own frames off nothing is set, and the line says what to switch on", K.entry(off, "TargetFrame") == nil and near(off.env.TargetFrame:GetScale(), 1)
		and K.outText(off):find("Move the game's own frames", 1, true) ~= nil and K.allClean(off), K.outText(off) .. K.problems(off))
	local saved = K.world({}, { FocusFrame = { point = "CENTER", x = 40, y = 20, kind = "hud", scale = 1.25 } })
	check("ms-scale: a saved scale shows in the row at login", saved.ns.Get("unitframes.focusScale") == 125 and near(saved.env.FocusFrame:GetScale(), 1.25))
	saved.ns.Set("unitframes.focusScale", 90)
	check("ms-scale: a frame with a saved place keeps it when its scale changes", near(K.entry(saved, "FocusFrame").x, 40) and near(K.entry(saved, "FocusFrame").y, 20) and near(K.entry(saved, "FocusFrame").scale, 0.9))
end
do
	local W = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.pixelPerfect"] = true, ["general.scale"] = 72 } } })
	W.login()
	W.advance(0.3)
	check("ms-scale: a login writes nothing", W.scaleWrites() == 0 and near(W.scale(), 0.64) and W.setScaleCalls == 0, W.scale())
	W.change("general.pixelPerfect", false)
	W.change("general.pixelPerfect", true)
	W.advance(0.3)
	check("ms-scale: pixel-perfect on a 1080 line screen is 768 over 1080 with one pixel per unit", near(W.scale(), 768 / 1080) and W.setScaleCalls == 0, W.scale())
	check("ms-scale: and the status line says so", has(W.status(), "Pixel-perfect scale: 1 px per unit, 71%."), W.status())
	W.change("general.pixelSize", 2)
	W.advance(0.3)
	check("ms-scale: two pixels per unit at 1080 lines is 142%, outside the range, so nothing is applied and the game's values are back", W.cvars.useUiScale == "0" and W.cvars.uiscale == "0.64"
		and has(W.status(), "gives 142%, outside 35% to 115%, so it is not applied"), W.cvars.uiscale .. W.status())
	W.height = 2160
	W.fire("DISPLAY_SIZE_CHANGED")
	W.advance(0.3)
	check("ms-scale: on a taller screen the same two pixels fit and are written", near(W.scale(), 2 * 768 / 2160) and W.setScaleCalls == 0, W.scale())
	W.height = 1440
	W.change("general.pixelSize", 1)
	W.advance(0.3)
	check("ms-scale: one pixel per unit at 1440 lines is 53%, under the game's 65%, so it is not applied", W.cvars.useUiScale == "0" and W.setScaleCalls == 0
		and has(W.status(), "Pixel-perfect scale: 1 px per unit needs 53%, under the game's 65%, so it is not applied."), W.status())
	W.height = 2400
	W.fire("DISPLAY_SIZE_CHANGED")
	W.advance(0.3)
	check("ms-scale: one pixel per unit at 2400 lines is 32%, under the range, so nothing is applied", W.cvars.useUiScale == "0" and W.setScaleCalls == 0 and has(W.status(), "gives 32%, outside 35% to 115%, so it is not applied"), W.status())
	W.height = 0
	W.fire("DISPLAY_SIZE_CHANGED")
	W.advance(0.3)
	check("ms-scale: a screen height of zero is not known", has(W.status(), "The screen height is not known") and W.cvars.useUiScale == "0" and W.setScaleCalls == 0, W.status())
	W.height = 1080
	W.change("general.pixelPerfect", false)
	W.advance(0.3)
	check("ms-scale: pixel-perfect off goes back to the custom scale", near(W.scale(), 0.72) and W.setScaleCalls == 0, W.scale())
	local S = newWorld({ saved = { options = { ["general.scaleOn"] = true, ["general.pixelPerfect"] = true } } })
	S.heightFault = "secret"
	S.login()
	S.advance(0.3)
	check("ms-scale: a screen height the client withholds applies nothing, and the status says why", has(S.status(), "The screen height is not known") and #S.errors == 0 and #S.violations == 0, S.status())
end

-- >>> ms-area (begin)
-- Border and background per page (ms-17): the twenty rows, the page an outline belongs to, and the paint. The values are kept in one table.
do
	local A = { PAGES = { "nameplates", "actionbars", "unitframes", "hud", "chat" } }
	function A.rgb(r, g, b)
		return r and ("%.2f,%.2f,%.2f"):format(r, g, b) or "nil"
	end
	function A.back(look)
		return A.rgb(look.backdrop.color[1], look.backdrop.color[2], look.backdrop.color[3])
	end
	function A.make(W, key, how)
		local frame = W.B(nil, {})
		local o
		local function build()
			o = W.ns.Outline(frame, frame)
		end
		if how == "each" then
			W.ns.Each(key, build, frame)
		elseif how == "part" then
			W.ns.EachPart(key, "part", build, frame)
		elseif how == "none" then
			build()
		else
			W.ns.Try(key, build)
		end
		return frame, o
	end

	do
		local W = newWorld({})
		W.login()
		local ns = W.ns
		local wrong = {}
		for _, page in ipairs(A.PAGES) do
			for _, row in ipairs({ { "lookOwn", false }, { "lookBorder", "ff000000" }, { "lookBack", "ff0f0f0f" }, { "lookBackAlpha", 85 } }) do
				if ns.Get(page .. "." .. row[1]) ~= row[2] then
					wrong[#wrong + 1] = page .. "." .. row[1]
				end
			end
		end
		check("ms-area: the twenty rows of the five pages are at their stand-in defaults", #wrong == 0, table.concat(wrong, ","))
		ns.Set("chat.lookBackAlpha", 500)
		local capped = ns.Get("chat.lookBackAlpha")
		ns.Set("chat.lookBorder", "zzz")
		check("ms-area: an opacity is kept to the range of its row and a colour that is no colour is refused", capped == 100 and ns.Get("chat.lookBorder") == "ff000000", tostring(capped) .. tostring(ns.Get("chat.lookBorder")))
	end

	do
		local W = newWorld({})
		W.login()
		W.change("general.border", "ff336699")
		local frame, o = A.make(W, "nameplates")
		local flat = W.look(frame)
		local flatBorder = A.rgb(flat.r, flat.g, flat.b)
		check("ms-area: with the row off an outline made in a module has the Flat UI page's border and background", flatBorder == "0.20,0.40,0.60" and near(flat.backdrop.color[4], 0.85), flatBorder)
		W.change("nameplates.lookOwn", true)
		local look = W.look(frame)
		check("ms-area: with the row on, the outline takes the page's border colour, background colour and opacity", A.rgb(look.r, look.g, look.b) == "0.00,0.00,0.00"
			and A.back(look) == "0.06,0.06,0.06" and near(look.backdrop.color[4], 0.85), A.rgb(look.r, look.g, look.b) .. A.back(look))
		W.change("nameplates.lookBorder", "ff112233")
		W.change("nameplates.lookBack", "ff445566")
		W.change("nameplates.lookBackAlpha", 40)
		look = W.look(frame)
		check("ms-area: a changed colour or opacity repaints at once", A.rgb(look.r, look.g, look.b) == "0.07,0.13,0.20" and A.back(look) == "0.27,0.33,0.40" and near(look.backdrop.color[4], 0.4),
			A.rgb(look.r, look.g, look.b) .. tostring(look.backdrop.color[4]))
		local other, otherOutline = A.make(W, "chat")
		local ol = W.look(other)
		check("ms-area: another page's outline keeps the Flat UI values", A.rgb(ol.r, ol.g, ol.b) == flatBorder and near(ol.backdrop.color[4], 0.85) and otherOutline.area == "chat", A.rgb(ol.r, ol.g, ol.b))
		W.change("general.border", "ff999999")
		look = W.look(frame)
		check("ms-area: the Flat UI border colour does not change an outline with its page's own", A.rgb(look.r, look.g, look.b) == "0.07,0.13,0.20", A.rgb(look.r, look.g, look.b))
		W.change("nameplates.lookOwn", false)
		look = W.look(frame)
		check("ms-area: switching the row off puts the Flat UI values back", A.rgb(look.r, look.g, look.b) == "0.60,0.60,0.60" and near(look.backdrop.color[4], 0.85), A.rgb(look.r, look.g, look.b))
		check("ms-area: an outline made in ns.Try knows its page", o.area == "nameplates" and o.prefix == "look")
	end

	do
		local W = newWorld({})
		W.login()
		local ns = W.ns
		for _, page in ipairs(A.PAGES) do
			W.change(page .. ".lookOwn", true)
			W.change(page .. ".lookBorder", "ff102030")
		end
		local fEach, oEach = A.make(W, "actionbars", "each")
		local fPart, oPart = A.make(W, "unitframes", "part")
		local fNone, oNone = A.make(W, "hud", "none")
		local lookEach, lookPart, lookNone = W.look(fEach), W.look(fPart), W.look(fNone)
		check("ms-area: ns.Each and ns.EachPart give the page too", oEach.area == "actionbars" and oPart.area == "unitframes" and A.rgb(lookEach.r, lookEach.g, lookEach.b) == "0.06,0.13,0.19"
			and A.rgb(lookPart.r, lookPart.g, lookPart.b) == "0.06,0.13,0.19", tostring(oEach.area) .. tostring(oPart.area))
		check("ms-area: an outline made outside them has no page and follows the Flat UI page", oNone.area == nil and A.rgb(lookNone.r, lookNone.g, lookNone.b) ~= "0.06,0.13,0.19", tostring(oNone.area))
		ns.SetOutlineArea(oNone, "hud")
		lookNone = W.look(fNone)
		check("ms-area: ns.SetOutlineArea names the page and repaints", oNone.area == "hud" and A.rgb(lookNone.r, lookNone.g, lookNone.b) == "0.06,0.13,0.19" and ns.SetOutlineArea(nil, "hud") == nil)
		-- A module run inside another, a module that fails, and the key put back after each.
		local inner, outer
		local fa, fb, fc = W.B(nil, {}), W.B(nil, {}), W.B(nil, {})
		ns.Try("chat", function()
			ns.Try("hud", function() inner = ns.Outline(fa, fa) end)
			outer = ns.Outline(fb, fb)
		end)
		ns.Try("nameplates", function() error("fails", 0) end)
		local after = ns.Outline(fc, fc)
		check("ms-area: the page of a module run inside another is put back, and a failing module leaves none running", inner.area == "hud" and outer.area == "chat" and after.area == nil,
			tostring(inner.area) .. tostring(outer.area) .. tostring(after.area))
		local cast, castOutline = A.make(W, "castbars")
		local castLook = W.look(cast)
		check("ms-area: a module with no border and background rows keeps the Flat UI values", castOutline.area == "castbars" and A.rgb(castLook.r, castLook.g, castLook.b) == A.rgb(ns.BorderRGB()))
		-- Colours set for a reason, a fill of its own and an opacity of its own still win.
		local f1, o1 = A.make(W, "chat")
		ns.SetOutlineColour(o1, 1, 0, 0)
		ns.SetOutlineAlpha(o1, nil, 0.3)
		local l1 = W.look(f1)
		check("ms-area: a colour of its own and an opacity of its own win over the page", A.rgb(l1.r, l1.g, l1.b) == "1.00,0.00,0.00" and near(l1.backdrop.color[4], 0.3))
		ns.SetOutlineFill(o1, 0.5, 0.5, 0.5, 0.7)
		l1 = W.look(f1)
		check("ms-area: a fill of its own wins over the page", A.back(l1) == "0.50,0.50,0.50" and near(l1.backdrop.color[4], 0.7))
		W.change("general.borderless", true)
		check("ms-area: Borderless still hides the edges of an outline with its page's own", W.look(fEach).hidden)
		W.change("general.borderless", false)
		-- A row prefix with no rows leaves the outline on the Flat UI page.
		local fp = W.B(nil, {})
		local op
		ns.Try("chat", function() op = ns.Outline(fp, fp, nil, "tip") end)
		local lp = W.look(fp)
		check("ms-area: a row prefix with no rows follows the Flat UI page, without an error", op.prefix == "tip" and A.rgb(lp.r, lp.g, lp.b) == A.rgb(ns.BorderRGB()) and #W.violations == 0)
	end

	-- The aura icons of a nameplate are made in a call that no wrapper of the module covers.
	do
		local W = newWorld({})
		W.login()
		W.change("nameplates.lookOwn", true)
		W.change("nameplates.lookBorder", "ff102030")
		local plate = W.newPlate()
		local aura = W.addAura(plate)
		W.showPlate("nameplate1", plate)
		W.tick()
		local look = W.look(aura.item)
		check("ms-area: the border of an aura icon on a nameplate is the Nameplates page's own", look ~= nil and A.rgb(look.r, look.g, look.b) == "0.06,0.13,0.19", look and A.rgb(look.r, look.g, look.b) or "no outline")
	end
end
-- >>> ms-area (end)

-- >>> mp-marks (begin)
-- Marks on action buttons: the registry in ActionBars.lua (btnreg:) and the marks of the trackers (bmarks:). The helpers sit in the table M.
do
	local M = { RED = { 0.851, 0.251, 0.251 } }
	-- What each button holds: the action number is the button's own, and GetActionInfo answers from W.mp.info.
	M.held = {
		ActionButton1 = { "spell", 905 }, ActionButton2 = { "spell", 325 }, ActionButton3 = { "item", 929 }, ActionButton4 = { "macro", 5 },
		ActionButton5 = { "spell", 974 }, ActionButton6 = { "flyout", 7 }, MultiBarBottomLeftButton1 = { "macro", 324, "spell" },
	}
	M.shield = { id = "shld01", kind = "buff", name = "Lightning Shield", names = { "Lightning Shield" }, spells = { 324, 325, 905 } }
	M.potion = { id = "pot001", kind = "item", name = "Healing Potion", items = { 929 } }
	function M.copy(t)
		local c = {}
		for k, v in pairs(t) do
			c[k] = v
		end
		return c
	end
	function M.number(name)
		local group, index = name:match("^(%a+)(%d+)$")
		return (group == "ActionButton" and 0 or 60) + tonumber(index)
	end
	-- A world with trackers and the buttons holding what M.held says. o.list the saved list, o.options the settings, o.prep(W) what the game has.
	function M.world(o)
		o = o or {}
		local opts = { trackers = true }
		if o.list then
			opts.char = { trackers = o.list }
		end
		if o.options then
			opts.saved = { options = o.options }
		end
		local W = newWorld(opts)
		W.ns.TrackerSlots = nil
		W.addLine({ name = "General" })
		W.addSpell(324, { name = "Lightning Shield", icon = 136051, lowRank = true, base = 0 })
		W.addSpell(325, { name = "Lightning Shield", icon = 136051, lowRank = true, base = 0 })
		W.addSpell(905, { name = "Lightning Shield", icon = 136051, base = 0 })
		W.addSpell(974, { name = "Earth Shield", icon = 136089, base = 0 })
		-- The spells a macro with no spell and a flyout hold an ID of, so that taking them for spells would find a name.
		W.addSpell(5, { name = "Fireball", icon = 135812, base = 0 })
		W.addSpell(7, { name = "Frost Nova", icon = 135848, base = 0 })
		W.mp = { info = {} }
		for name, held in pairs(M.held) do
			W.mp.info[M.number(name)] = held
			W.buttons[name].inner.action = M.number(name)
		end
		W.env.GetActionInfo = function(action)
			local held = W.mp.info[action]
			if held then
				return held[1], held[2], held[3]
			end
		end
		W.au.itemCount[929] = 0
		W.au.itemIcon[929] = 133771
		if o.prep then
			o.prep(W)
		end
		W.login()
		W.flush()
		M.step(W, 0.3)
		return W
	end
	function M.step(W, seconds)
		W.advance(seconds)
		W.advance(0)
	end
	function M.icon(W, name)
		return W.buttons[name].parts.icon
	end
	-- The ring of a button: its colour and thickness in screen pixels, or nil without an outline.
	function M.ring(W, name)
		local o = W.look(M.icon(W, name))
		return o and { r = o.r, g = o.g, b = o.b, thick = o.thick, state = o.state }
	end
	function M.marked(W, name)
		local ring = M.ring(W, name)
		return ring ~= nil and near(ring.r, M.RED[1]) and near(ring.g, M.RED[2]) and near(ring.b, M.RED[3]) and near(ring.thick, 2)
	end
	function M.plain(W, name)
		return (ringOf(W, M.icon(W, name), 1, 0, 0, 0))
	end
	-- The names of the buttons in a list, in order of name.
	function M.names(W, list)
		local names = {}
		for _, button in ipairs(list) do
			for name, entry in pairs(W.buttons) do
				if entry.button == button then
					names[#names + 1] = name
				end
			end
		end
		table.sort(names)
		return table.concat(names, ",")
	end
	-- A slash command prints its lines, so they are taken from W.out again for the checks of no messages.
	function M.slash(W, text)
		local out = W.slash(text)
		W.out = {}
		return out
	end
	function M.quiet(W)
		return #W.violations == 0 and #W.errors == 0 and #W.out == 0
	end
	function M.trouble(W)
		return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|")
	end

	-- The registry.
	do
		local W = M.world()
		local ns, b = W.ns, function(name) return W.buttons[name].button end
		local list = ns.ActionButtons()
		check("btnreg: ActionButtons lists the 118 restyled buttons, bar by bar", #list == 118 and list[1] == b("ActionButton1") and list[13] == b("MultiBarBottomLeftButton1") and list[118] == b("PossessButton2"), #list)
		local function action(name)
			local kind, id, label = ns.ButtonAction(b(name))
			return tostring(kind) .. "," .. tostring(id) .. "," .. tostring(label)
		end
		check("btnreg: a spell is its kind, ID and name", action("ActionButton1") == "spell,905,Lightning Shield", action("ActionButton1"))
		check("btnreg: a macro that casts a spell is that spell", action("MultiBarBottomLeftButton1") == "spell,324,Lightning Shield", action("MultiBarBottomLeftButton1"))
		check("btnreg: an item is its kind and ID", action("ActionButton3") == "item,929,nil", action("ActionButton3"))
		check("btnreg: a macro that casts no spell, a flyout and a button with no action are nothing", action("ActionButton4") == "nil,nil,nil" and action("ActionButton6") == "nil,nil,nil"
			and action("ActionButton7") == "nil,nil,nil" and action("PetActionButton1") == "nil,nil,nil")
		check("btnreg: ButtonsFor finds a spell by its name in lower case, every rank and the macro",
			M.names(W, ns.ButtonsFor("spell", "lightning shield")) == "ActionButton1,ActionButton2,MultiBarBottomLeftButton1", M.names(W, ns.ButtonsFor("spell", "lightning shield")))
		check("btnreg: the buttons come in bar order", ns.ButtonsFor("spell", "lightning shield")[1] == b("ActionButton1") and ns.ButtonsFor("spell", "lightning shield")[3] == b("MultiBarBottomLeftButton1"))
		check("btnreg: and an item by its ID", M.names(W, ns.ButtonsFor("item", 929)) == "ActionButton3" and M.names(W, ns.ButtonsFor("spell", "earth shield")) == "ActionButton5")
		check("btnreg: a name or kind that nothing holds is an empty array, never nil", type(ns.ButtonsFor("spell", "nothing")) == "table" and #ns.ButtonsFor("spell", "nothing") == 0
			and #ns.ButtonsFor("item", 1) == 0 and #ns.ButtonsFor("bogus", "x") == 0 and #ns.ButtonsFor(nil, nil) == 0 and #ns.ButtonsFor("spell", "Lightning Shield") == 0)
		local copy = ns.ButtonsFor("item", 929)
		copy[2] = "x"
		check("btnreg: the array is the caller's own", #ns.ButtonsFor("item", 929) == 1)
		-- The map is kept until a button changes.
		W.mp.info[M.number("ActionButton2")] = { "spell", 974 }
		check("btnreg: the map is kept: a change in the game is not seen before its event", M.names(W, ns.ButtonsFor("spell", "lightning shield")) == "ActionButton1,ActionButton2,MultiBarBottomLeftButton1")
		W.fire("ACTIONBAR_PAGE_CHANGED")
		check("btnreg: a page change makes the map again", M.names(W, ns.ButtonsFor("spell", "lightning shield")) == "ActionButton1,MultiBarBottomLeftButton1"
			and M.names(W, ns.ButtonsFor("spell", "earth shield")) == "ActionButton2,ActionButton5", M.names(W, ns.ButtonsFor("spell", "earth shield")))
		local events = {}
		for _, event in ipairs({ "ACTIONBAR_SLOT_CHANGED", "ACTIONBAR_PAGE_CHANGED", "UPDATE_BONUS_ACTIONBAR", "SPELLS_CHANGED", "PLAYER_ENTERING_WORLD" }) do
			W.mp.info[M.number("ActionButton2")] = { "spell", 325 }
			W.fire("SPELLS_CHANGED")
			ns.ButtonsFor("spell", "x")
			W.mp.info[M.number("ActionButton2")] = { "spell", 974 }
			W.fire(event)
			events[#events + 1] = M.names(W, ns.ButtonsFor("spell", "earth shield")) == "ActionButton2,ActionButton5" and "" or event
		end
		check("btnreg: each of the five events makes the map again", table.concat(events) == "", table.concat(events, ","))
		M.step(W, 0.1)
		-- The listeners hear of a change once per frame, and one that fails does not stop the others.
		local heard = 0
		ns.OnButtonsChanged(function()
			error("a listener that fails", 0)
		end)
		ns.OnButtonsChanged(function()
			heard = heard + 1
		end)
		ns.OnButtonsChanged("not a function")
		W.fire("ACTIONBAR_SLOT_CHANGED")
		W.fire("ACTIONBAR_SLOT_CHANGED")
		W.fire("SPELLS_CHANGED")
		check("btnreg: a listener is not called before the frame ends", heard == 0)
		M.step(W, 0)
		check("btnreg: and once for any number of changes, and one that fails does not stop the next", heard == 1 and M.quiet(W), heard .. M.trouble(W))
		W.update("ActionButton1")
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		M.step(W, 0)
		M.step(W, 0)
		check("btnreg: the layout of a button is a change too", heard == 2, heard)
		clean(W, "btnreg")
	end
	-- A button the game withholds, or that fails.
	do
		local W = M.world({ prep = function(P)
			P.buttons.ActionButton6.inner.action = SECRET
			P.buttons.ActionButton7.inner.action = M.number("ActionButton7")
			P.mp.info[M.number("ActionButton7")] = { SECRET, 905 }
			P.buttons.ActionButton8.inner.action = M.number("ActionButton8")
			P.mp.info[M.number("ActionButton8")] = { "spell", SECRET }
			P.buttons.ActionButton9.inner.action = M.number("ActionButton9")
			P.mp.info[M.number("ActionButton9")] = { "macro", 905, SECRET }
			P.buttons.ActionButton10.inner.action = M.number("ActionButton10")
			P.mp.info[M.number("ActionButton10")] = { "spell", "x" }
		end })
		local ns = W.ns
		local shown = {}
		for _, name in ipairs({ "ActionButton6", "ActionButton7", "ActionButton8", "ActionButton9", "ActionButton10" }) do
			shown[#shown + 1] = tostring((ns.ButtonAction(W.buttons[name].button)))
		end
		check("btnreg: a withheld action, kind, ID or sub-kind, and an ID that is no number, are skipped with no error", table.concat(shown, ",") == "nil,nil,nil,nil,nil" and M.quiet(W), table.concat(shown, ",") .. M.trouble(W))
		W.env.GetActionInfo = function()
			error("GetActionInfo failed", 0)
		end
		W.fire("ACTIONBAR_SLOT_CHANGED")
		check("btnreg: a GetActionInfo that fails gives an empty map and no error", #ns.ButtonsFor("spell", "lightning shield") == 0 and #ns.ButtonsFor("item", 929) == 0 and M.quiet(W), M.trouble(W))
		W.env.GetActionInfo = nil
		W.fire("ACTIONBAR_SLOT_CHANGED")
		check("btnreg: a client without GetActionInfo gives an empty map and no error", #ns.ButtonsFor("item", 929) == 0 and M.quiet(W), M.trouble(W))
		W.env.GetActionInfo = function() return "spell", 905 end
		W.env.C_Spell.GetSpellName = function() return SECRET end
		W.fire("ACTIONBAR_SLOT_CHANGED")
		check("btnreg: a withheld spell name is skipped", #ns.ButtonsFor("spell", "lightning shield") == 0 and M.quiet(W), M.trouble(W))
	end
	-- The marks of a button.
	do
		local W = M.world()
		local ns = W.ns
		local b = W.buttons.ActionButton1.button
		check("btnreg: a button with no mark has the general outline", M.plain(W, "ActionButton1") and W.state(M.icon(W, "ActionButton1")) == "SB")
		check("bmarks: SetButtonMark draws the mark and says so", ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251) == true and M.marked(W, "ActionButton1"), tostring(M.ring(W, "ActionButton1") and M.ring(W, "ActionButton1").thick))
		check("bmarks: another button is not touched", M.plain(W, "ActionButton2"))
		check("bmarks: a proc is drawn over a missing mark", ns.SetButtonMark(b, "proc", 0.2, 0.8, 0.2) == true and near(M.ring(W, "ActionButton1").g, 0.8) and near(M.ring(W, "ActionButton1").r, 0.2))
		check("bmarks: a missing mark set while a proc is up does not show", ns.SetButtonMark(b, "missing", 1, 1, 0) == true and near(M.ring(W, "ActionButton1").g, 0.8))
		ns.SetButtonMark(b, "proc", nil)
		check("bmarks: with the proc gone the missing mark shows again", near(M.ring(W, "ActionButton1").r, 1) and near(M.ring(W, "ActionButton1").g, 1) and near(M.ring(W, "ActionButton1").b, 0))
		ns.SetButtonMark(b, "missing", nil)
		check("bmarks: with no source left the outline is exactly as it was: the general colour and thickness", M.plain(W, "ActionButton1") and W.state(M.icon(W, "ActionButton1")) == "SB")
		check("bmarks: taking away a mark that was never set changes nothing, and with no button or a source that is none it says false", ns.SetButtonMark(b, "missing", nil) == false and M.plain(W, "ActionButton1")
			and ns.SetButtonMark(nil, "missing", 1, 0, 0) == false and ns.SetButtonMark(b, "other", 1, 0, 0) == false and M.plain(W, "ActionButton1"))
		ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251)
		W.update("ActionButton1")
		check("bmarks: the mark stays through the game's art update, and the status counts it", M.marked(W, "ActionButton1") and has(W.status(), "Action bars: 1 marked"), W.status())
		-- A colour of its own is drawn with Borderless on, and the other edges are not.
		W.change("general.borderless", true)
		check("bmarks: Borderless on: the marked edges are shown, the unmarked are hidden", W.state(M.icon(W, "ActionButton1")) == "SB" and W.state(M.icon(W, "ActionButton2")) == "hB",
			W.state(M.icon(W, "ActionButton1")) .. W.state(M.icon(W, "ActionButton2")))
		W.change("general.borderless", false)
		check("bmarks: Borderless off: the unmarked edges are shown again", W.state(M.icon(W, "ActionButton2")) == "SB" and M.marked(W, "ActionButton1"))
		-- A group that is off has no outline shown; its mark waits.
		W.change("actionbars.main", false)
		check("bmarks: a group that is off: the mark is kept and not drawn, and SetButtonMark says false", ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251) == false and W.state(M.icon(W, "ActionButton1")) == "hb"
			and not has(W.status(), "marked"), W.state(M.icon(W, "ActionButton1")))
		W.change("actionbars.main", true)
		check("bmarks: and it is drawn when the group is switched on", M.marked(W, "ActionButton1") and W.state(M.icon(W, "ActionButton1")) == "SB")
		ns.SetButtonMark(b, "missing", nil)
		-- Combat: the colour and thickness of an outline that exists.
		local before = {}
		for k, v in pairs(W.buttons.ActionButton1.inner.calls) do
			before[k] = v
		end
		local outlineOf = W.look(M.icon(W, "ActionButton1"))
		local edgeCalls = function()
			local counted = {}
			for _, side in ipairs({ "top", "bottom", "left", "right" }) do
				for k, v in pairs(outlineOf[side].calls) do
					counted[side .. "." .. k] = v
				end
			end
			return counted
		end
		local edgesBefore = edgeCalls()
		W.combat = true
		local drawn = ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251)
		local inFight = near(M.ring(W, "ActionButton1").r, 0.851)
		local edgesAfter = edgeCalls()
		local onlyColour = true
		for k, v in pairs(edgesAfter) do
			if edgesBefore[k] ~= v then
				onlyColour = onlyColour and (k:find("SetColorTexture", 1, true) ~= nil or k:find("SetShown", 1, true) ~= nil)
			end
		end
		ns.SetButtonMark(b, "missing", nil)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		local same = true
		for k, v in pairs(W.buttons.ActionButton1.inner.calls) do
			same = same and before[k] == v
		end
		check("bmarks: in combat the mark is drawn and taken away with no call on the button and no violation", drawn == true and inFight and same and M.plain(W, "ActionButton1") and M.quiet(W), M.trouble(W))
		check("bmarks: in combat only SetColorTexture and SetShown are called on the outline's edges", onlyColour)
		W.combat = true
		ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251)
		local thinInFight = M.ring(W, "ActionButton1").thick ~= 2
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("bmarks: the thickness reaches 2 px when the fight ends", thinInFight and M.ring(W, "ActionButton1").thick == 2, tostring(M.ring(W, "ActionButton1").thick))
		ns.SetButtonMark(b, "missing", nil)
		clean(W, "bmarks")
	end
	-- Restyle action bars off.
	do
		local W = M.world({ options = { ["actionbars.enabled"] = false } })
		local ns = W.ns
		local b = W.buttons.ActionButton1.button
		check("btnreg: with Restyle action bars off there is no restyled button and no button for a spell", #ns.ActionButtons() == 0 and #ns.ButtonsFor("spell", "lightning shield") == 0 and M.quiet(W), M.trouble(W))
		check("bmarks: SetButtonMark says false, makes no outline and raises nothing", ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251) == false and W.look(M.icon(W, "ActionButton1")) == nil and M.quiet(W), M.trouble(W))
		W.change("actionbars.enabled", true)
		local ring = M.ring(W, "ActionButton1")
		check("bmarks: switched on, the kept mark is drawn", M.marked(W, "ActionButton1"), ring and (tostring(ring.r) .. " " .. tostring(ring.thick) .. " " .. ring.state) or "no ring")
	end
	-- The trackers.
	do
		local W = M.world({ list = { M.copy(M.shield), M.copy(M.potion) } })
		local ns = W.ns
		local row
		for _, page in ipairs(ns.PAGES) do
			for _, item in ipairs(page) do
				if item.path == "trackers.mark" then
					row = item
				end
			end
		end
		check("bmarks: the Trackers page has Mark action buttons, a switch that starts off", row ~= nil and row.kind == "bool" and row.default == false and row.label == "Mark action buttons" and ns.Get("trackers.mark") == false)
		check("bmarks: with the row off nothing is marked, a missing buff and a missing item", not M.marked(W, "ActionButton1") and not M.marked(W, "ActionButton3") and M.plain(W, "ActionButton3"))
		check("bmarks: the check says Marks: off", has(M.slash(W, "tracker check"), "Marks: off."), M.slash(W, "tracker check"))
		W.change("trackers.mark", true)
		M.step(W, 0.3)
		check("bmarks: with the row on, a missing buff marks every button that holds one of its spells, every rank, and no other",
			M.marked(W, "ActionButton1") and M.marked(W, "ActionButton2") and M.marked(W, "MultiBarBottomLeftButton1") and M.plain(W, "ActionButton5") and M.plain(W, "ActionButton4"))
		check("bmarks: and a missing item marks the button that uses it", M.marked(W, "ActionButton3"))
		local text = M.slash(W, "tracker check")
		check("bmarks: the check counts the buttons of each tracker", has(text, "Marks: 3 buttons.") and has(text, "Marks: 1 button."), text)
		check("bmarks: the status counts the marked buttons", has(W.status(), "Action bars: 4 marked"), W.status())
		W.giveBuff(905, { remaining = 600, fromPlayer = true })
		W.auraChanged()
		M.step(W, 0.3)
		check("bmarks: the buff is up: its buttons go back to the general outline, the item's stays", M.plain(W, "ActionButton1") and M.plain(W, "ActionButton2") and M.plain(W, "MultiBarBottomLeftButton1") and M.marked(W, "ActionButton3"), M.trouble(W))
		W.au.itemCount[929] = 5
		W.fire("BAG_UPDATE_DELAYED")
		M.step(W, 0.3)
		check("bmarks: the item is in the bags: its button goes back too", M.plain(W, "ActionButton3") and not has(W.status(), "marked"))
		W.au.itemCount[929] = 0
		W.fire("BAG_UPDATE_DELAYED")
		W.takeBuff(905)
		W.auraChanged()
		M.step(W, 0.3)
		check("bmarks: both missing again: marked again", M.marked(W, "ActionButton1") and M.marked(W, "ActionButton3"))
		-- The game moves a spell to another button.
		W.mp.info[M.number("ActionButton2")] = { "spell", 974 }
		W.mp.info[M.number("ActionButton9")] = { "spell", 905 }
		W.buttons.ActionButton9.inner.action = M.number("ActionButton9")
		W.fire("ACTIONBAR_SLOT_CHANGED")
		M.step(W, 0.1)
		check("bmarks: when buttons change the marks follow the spell", M.plain(W, "ActionButton2") and M.marked(W, "ActionButton9") and M.marked(W, "ActionButton1") and M.marked(W, "MultiBarBottomLeftButton1"), M.trouble(W))
		-- The tracker is off, removed, or the row is off.
		ns.TrackerSet(1, "on", "off")
		M.step(W, 0.3)
		check("bmarks: a tracker that is off marks nothing", M.plain(W, "ActionButton1") and M.plain(W, "ActionButton9") and M.marked(W, "ActionButton3"))
		ns.TrackerSet(1, "on", "on")
		M.step(W, 0.3)
		check("bmarks: and marks again when it is on", M.marked(W, "ActionButton1"))
		ns.TrackerRemove(2)
		M.step(W, 0.3)
		check("bmarks: a tracker that is removed marks nothing", M.plain(W, "ActionButton3") and M.marked(W, "ActionButton1"))
		W.change("trackers.mark", false)
		M.step(W, 0.3)
		check("bmarks: the row off takes every mark away", M.plain(W, "ActionButton1") and M.plain(W, "ActionButton9") and not has(W.status(), "marked"))
		W.change("trackers.mark", true)
		M.step(W, 0.3)
		W.change("trackers.enabled", false)
		M.step(W, 0.3)
		check("bmarks: the Trackers page off takes every mark away", M.plain(W, "ActionButton1") and M.plain(W, "ActionButton9"))
		W.change("trackers.enabled", true)
		M.step(W, 0.3)
		check("bmarks: and on again marks", M.marked(W, "ActionButton1"))
		clean(W, "bmarks")
	end
	-- The tracker's own value, and a state that is not read.
	do
		local own = M.copy(M.shield)
		own.mark = true
		local W = M.world({ list = { own, M.copy(M.potion) } })
		local ns = W.ns
		check("bmarks: a tracker's own mark is on while the row is off", M.marked(W, "ActionButton1") and M.plain(W, "ActionButton3"))
		check("bmarks: and the check names it", has(M.slash(W, "tracker check"), "Marks: 3 buttons.") and has(M.slash(W, "tracker check"), "Own settings: mark on."), M.slash(W, "tracker check"))
		W.change("trackers.mark", true)
		W.env.FlatUICharDB.trackers[1].mark = false
		W.fire("SPELLS_CHANGED")
		M.step(W, 0.3)
		check("bmarks: an own off beats the row on", M.plain(W, "ActionButton1") and M.marked(W, "ActionButton3"))
		W.env.FlatUICharDB.trackers[1].mark = "yes"
		W.fire("SPELLS_CHANGED")
		M.step(W, 0.3)
		check("bmarks: an own value that is not a boolean is taken away when the list is read", W.env.FlatUICharDB.trackers[1].mark == nil and M.marked(W, "ActionButton1"))
		-- A fight: the buff is not read, so it is not marked.
		W.beginFight()
		M.step(W, 0.3)
		check("bmarks: in a fight a buff the game withholds is not marked, and a mark from before is taken away", M.plain(W, "ActionButton1") and M.plain(W, "ActionButton2"))
		check("bmarks: and an item, which is read, stays marked", M.marked(W, "ActionButton3") and M.quiet(W), M.trouble(W))
		W.endFight()
		M.step(W, 0.3)
		check("bmarks: the fight over, the buff is marked again", M.marked(W, "ActionButton1"))
		clean(W, "bmarks")
	end
	-- A tracker with nothing on the bars, and the spells that fix a tracker.
	do
		local earth = { id = "erth01", kind = "buff", name = "Earth Shield", names = { "Earth Shield" }, spells = { 974 }, mark = true, apply = { 905 } }
		local lonely = { id = "lone01", kind = "buff", name = "Water Shield", names = { "Water Shield" }, spells = { 52127 }, mark = true }
		local W = M.world({ list = { earth, lonely }, prep = function(P)
			P.addSpell(52127, { name = "Water Shield", icon = 132315, base = 0 })
		end })
		check("bmarks: entry.apply names more spells that fix a tracker: Earth Shield with 905 marks its own button and the Lightning Shield buttons",
			M.marked(W, "ActionButton5") and M.marked(W, "ActionButton1") and M.marked(W, "ActionButton2"))
		local text = M.slash(W, "tracker check")
		check("bmarks: a tracker no button holds says so", has(text, "Marks: no button holds it."), text)
		W.change("actionbars.enabled", false)
		M.step(W, 0.3)
		check("bmarks: Restyle action bars off: the check says why and nothing is marked", has(M.slash(W, "tracker check"), "Marks: Restyle action bars is off.") and W.state(M.icon(W, "ActionButton1")) == "hb" and not has(W.status(), "marked"), W.state(M.icon(W, "ActionButton1")))
		W.change("actionbars.enabled", true)
		M.step(W, 0.3)
		check("bmarks: Restyle action bars on again: marked again", M.marked(W, "ActionButton5"))
		clean(W, "bmarks")
	end
	-- Low marks as missing does, and a list of spells that is too long is cut.
	do
		local potion = M.copy(M.potion)
		potion.low = 3
		potion.mark = true
		local W = M.world({ list = { potion }, prep = function(P)
			P.au.itemCount[929] = 2
		end })
		check("bmarks: a low item marks its button", M.marked(W, "ActionButton3"), M.slash(W, "tracker check"))
		W.au.itemCount[929] = 4
		W.fire("BAG_UPDATE_DELAYED")
		M.step(W, 0.3)
		check("bmarks: and one that is not low does not", M.plain(W, "ActionButton3"))
		local long = { id = "long01", kind = "buff", name = "Earth Shield", names = { "Earth Shield" }, spells = { 974 }, mark = true, apply = {} }
		for id = 100, 139 do
			long.apply[#long.apply + 1] = id
		end
		long.apply[41] = 905
		local X = M.world({ list = { long } })
		check("bmarks: only the first 40 spells of a list are used, and the buff's own are", M.marked(X, "ActionButton5") and M.plain(X, "ActionButton1"), M.slash(X, "tracker check"))
		clean(W, "bmarks")
		clean(X, "bmarks")
	end
	-- The row on a tracker's own page, and the files.
	do
		local W = M.world()
		local modulesBefore = #W.ns.MODULE_ORDER
		local calls = {}
		W.ns.TrackerEditorRow = function(key, kind)
			calls[#calls + 1] = key .. "," .. kind
			return true
		end
		loadWithEnv(ADDON_DIR .. "/TrackerMarks.lua", W.env)("FlatUI", W.ns)
		check("bmarks: the editor is asked for the row mark, a boolean, once", #calls == 1 and calls[1] == "mark,bool", table.concat(calls, ";"))
		W.ns.TrackerEditorRow = nil
		check("bmarks: no editor, no error", pcall(loadWithEnv(ADDON_DIR .. "/TrackerMarks.lua", W.env), "FlatUI", W.ns))
		check("bmarks: the files compile, so each has at most 200 locals", loadfile(ADDON_DIR .. "/TrackerMarks.lua") ~= nil and loadfile(ADDON_DIR .. "/ActionBars.lua") ~= nil and loadfile(ADDON_DIR .. "/Trackers.lua") ~= nil)
		check("bmarks: TrackerMarks.lua is loaded after TrackerKinds.lua, and after ActionBars.lua", (function()
			local at = {}
			for i, file in ipairs(FILES) do
				at[file] = i
			end
			return at["TrackerMarks.lua"] == at["TrackerKinds.lua"] + 1 and at["TrackerMarks.lua"] > at["ActionBars.lua"]
		end)())
		check("bmarks: it is no module", #W.ns.MODULE_ORDER == modulesBefore)
	end
end
-- >>> mp-marks (end)
-- >>> mp-procs (begin)
-- Proc alerts (procs:). The helpers sit in the table Z.
do
	local Z = { TRANCE = 17941, BOLT = 686, BOLT_TOP = 25307, SOUL_FIRE = 6353, ICON = 136197, TRANCE_ICON = 136183 }
	Z.NO_SOUND = "Trackers: the game played no sound, so proc alerts are silent."
	local function count(text, needle)
		local n, at = 0, 1
		while true do
			local found = text:find(needle, at, true)
			if not found then
				return n
			end
			n, at = n + 1, found + #needle
		end
	end
	-- A Shadow Trance tracker as the addon saves it.
	function Z.entry(more)
		local e = { id = "prc001", kind = "proc", name = "Shadow Trance", names = { "Shadow Trance" }, spells = { 17941 }, lights = { 686, 25307 }, trigger = "aura",
			time = 10, size = 48, show = "always" }
		for k, v in pairs(more or {}) do
			e[k] = v
		end
		return e
	end
	-- A world of a warlock with trackers: o.list the saved list, o.options the settings, o.real keeps the game's own icons, o.set(W) what the game has.
	function Z.world(o)
		o = o or {}
		local opts = { trackers = true, char = { trackers = o.list or {} } }
		if o.options then
			opts.saved = { options = o.options }
		end
		local W = newWorld(opts)
		if not o.real then
			W.ns.TrackerSlots = nil
		end
		W.addLine({ name = "General" })
		W.addSpell(686, { name = "Shadow Bolt", icon = Z.ICON, base = 0, lowRank = true })
		W.addSpell(25307, { name = "Shadow Bolt", icon = Z.ICON, base = 0 })
		W.addSpell(6353, { name = "Soul Fire", icon = 135808, base = 0 })
		W.addSpell(17941, { name = "Shadow Trance", icon = Z.TRANCE_ICON, base = 0, known = false })
		W.addSpell(440873, { name = "Decimation", icon = 135994, base = 0, known = false })
		W.sp.castTimes[686], W.sp.castTimes[25307], W.sp.castTimes[6353] = 2500, 2500, 3000
		W.au.unit.player = { class = o.class or "WARLOCK", guid = "Player-1" }
		W.env.Enum.ScreenLocationType = { Center = 0, Left = 1, Right = 2, Top = 3, Bottom = 4, TopLeft = 5, TopRight = 6, LeftOutside = 7, RightOutside = 8, LeftRight = 9,
			TopBottom = 10, LeftRightOutside = 11 }
		if o.set then
			o.set(W)
		end
		return W
	end
	function Z.step(W, seconds)
		W.advance(seconds)
		W.advance(0)
	end
	-- Time passes in steps of a quarter second, so that what a pass sets for a later one is seen: the passes of one long step all see its end.
	function Z.run(W, seconds)
		for _ = 1, math.floor(seconds * 4 + 0.5) do
			Z.step(W, 0.25)
		end
	end
	-- Logged in, and past the two quiet seconds unless o.quiet.
	function Z.up(o)
		local W = Z.world(o)
		W.login()
		W.flush()
		if not (o and o.quiet) then
			Z.step(W, 5)
		end
		return W
	end
	function Z.list(W)
		return W.env.FlatUICharDB.trackers
	end
	function Z.ok(W)
		return #W.violations == 0 and #W.errors == 0 and not has(W.status(), "stopped")
	end
	function Z.why(W)
		return table.concat(W.violations, " | "):sub(1, 200) .. " || " .. table.concat(W.errors, " | "):sub(1, 200) .. " || " .. W.line("Trackers")
	end
	function Z.frame(W, index)
		return W.ns.TrackerFrame(Z.list(W)[index or 1])
	end
	function Z.alpha(W, index)
		return Z.frame(W, index).alpha
	end
	-- The parts of a tracker's frame: the icon, the sweep, the four edges of the rim.
	function Z.parts(W, index)
		local frame = Z.frame(W, index)
		local p = { frame = frame, rim = {} }
		for _, r in ipairs(frame.regions) do
			if r.layer == "ARTWORK" then
				p.icon = r
			end
		end
		for _, child in ipairs(frame.children) do
			if child.cd then
				p.cooldown = child
			else
				local edges, text = {}, false
				for _, r in ipairs(child.regions) do
					if r.kind == "Texture" then
						edges[#edges + 1] = r
					elseif r.kind == "FontString" then
						text = true
					end
				end
				-- The rim is the four textures of the frame that has the count and the word.
				if text then
					p.rim = edges
				end
			end
		end
		return p
	end
	function Z.rim(p)
		local n = 0
		for _, r in ipairs(p.rim) do
			if r.shown then
				n = n + 1
			end
		end
		return n
	end
	-- The game's own icons as a stand-in that records what it is asked: S.live[id] is true while the icon is ready.
	function Z.slots(W, live)
		local S = { calls = {}, live = live or {}, shown = {}, synced = {} }
		W.ns.TrackerSlots = {
			Sync = function(entries)
				S.calls[#S.calls + 1] = "Sync:" .. #entries
				S.synced = {}
				for _, e in ipairs(entries) do
					S.synced[#S.synced + 1] = e.id
				end
			end,
			Show = function(entry, on) S.shown[entry.id] = on end,
			Live = function(entry) return S.live[entry.id] == true end,
			Flush = function() end,
			Lines = function() return {} end,
			FightLines = function() return {} end,
			Probe = function() end,
			LowTest = function() end,
		}
		return S
	end
	-- The art and glow functions of the next builds as stand-ins that record their calls.
	function Z.hooks(W)
		local H = { art = {}, hide = {}, glow = {}, stop = {} }
		W.ns.ProcArtShow = function(entry, data) H.art[#H.art + 1] = { entry = entry, data = data } end
		W.ns.ProcArtHide = function(entry) H.hide[#H.hide + 1] = entry end
		W.ns.ProcGlowStart = function(entry) H.glow[#H.glow + 1] = entry end
		W.ns.ProcGlowStop = function(entry) H.stop[#H.stop + 1] = entry end
		return H
	end
	-- The buff is on and the tracker has looked.
	function Z.give(W, remaining)
		W.giveBuff(17941, { remaining = remaining or 600, icon = Z.TRANCE_ICON })
		W.auraChanged()
		Z.step(W, 0.3)
	end
	function Z.take(W)
		W.takeBuff(17941)
		W.auraChanged()
		Z.step(W, 0.3)
	end

	-- 1. The class data.
	do
		local data = loadfile(ADDON_DIR .. "/ProcData.lua")
		local ns = {}
		check("procs: ProcData.lua compiles and fills ns.ProcData", data ~= nil and (function()
			data(nil, ns)
			return type(ns.ProcData) == "table"
		end)())
		local classes, bad, rows = 0, {}, 0
		local KINDS = { proc = true, stack = true, activated = true, reactive = true }
		local function whole(list)
			for _, id in ipairs(list) do
				if type(id) ~= "number" or id < 1 or id ~= math.floor(id) then
					return false
				end
			end
			return true
		end
		for class, list in pairs(ns.ProcData or {}) do
			classes = classes + 1
			for _, row in ipairs(list) do
				rows = rows + 1
				local ok = type(row.name) == "string" and KINDS[row.kind] and (row.watch == "aura" or row.watch == "usable") and type(row.buffs) == "table" and #row.buffs >= 1 and whole(row.buffs)
					and type(row.lights) == "table" and whole(row.lights) and (row.seconds == nil or type(row.seconds) == "number") and (row.art == nil or type(row.art.file) == "number")
				if not ok then
					bad[#bad + 1] = class .. " " .. tostring(row.name)
				end
			end
		end
		check("procs: the nine classes have rows, each with a name, one of four kinds, aura or usable, buffs and lights of whole numbers", classes == 9 and rows == 48 and #bad == 0, classes .. " " .. rows .. " " .. table.concat(bad, ", "))
		local trance
		for _, row in ipairs(ns.ProcData and ns.ProcData.WARLOCK or {}) do
			if row.name == "Shadow Trance" then
				trance = row
			end
		end
		check("procs: Shadow Trance is a proc of 10 seconds with its buff, the ranks of Shadow Bolt and its art", trance ~= nil and trance.kind == "proc" and trance.watch == "aura" and trance.seconds == 10 and trance.buffs[1] == 17941
			and #trance.buffs == 1 and #trance.lights == 10 and trance.lights[1] == 686 and trance.lights[10] == 25307 and trance.art.file == 449492 and trance.art.location == "LeftRight")
		local sorted, rowsOf = true, ns.ProcData and ns.ProcData.WARLOCK or {}
		for _, row in ipairs(rowsOf) do
			sorted = sorted and row.kind ~= "stat" and row.kind ~= "target" and row.kind ~= "blocker" and row.watch ~= "target aura" and row.watch ~= "target health"
		end
		check("procs: the stat, target and blocker procs and the ones read from the target are left out", sorted and #rowsOf == 5)
		local handle = assert(io.open(ADDON_DIR .. "/ProcData.lua", "rb"))
		local text = handle:read("*a")
		handle:close()
		local longest = 0
		for line in (text .. "\n"):gmatch("([^\n]*)\n") do
			longest = math.max(longest, #line)
		end
		check("procs: the file says it is generated and by which command, lists what it left out, and has no line of 2,000 characters", has(text, "Generated by python tools/make_procdata.py") and has(text, "-- Left out: WARRIOR Execute (reactive, target health)")
			and longest < 2000 and not text:find("\r", 1, true), longest)
	end

	-- 2. Cleaning an entry.
	do
		local many = {}
		for id = 1, 45 do
			many[#many + 1] = 1000 + id
		end
		local W = Z.up({ list = {
			Z.entry({ id = "prc001", spells = { 17941, -1, 17941, "x", 5.5, 440873 }, lights = many, time = 200, colour = "zz", sound = true, size = 20, trigger = "bogus" }),
			Z.entry({ id = "prc002", name = "Decimation", names = { "Decimation" }, spells = { 440873 }, time = 0, colour = "ffd94040", sound = false, size = 24, trigger = "overlay" }),
			Z.entry({ id = "prc003", name = "Fel Domination", names = { "Fel Domination" }, spells = { 18708 }, sound = 8959, size = 64, time = 120, lights = {} }),
			{ id = "prc004", kind = "proc" },
			Z.entry({ id = "prc005", spells = {}, name = false }),
			Z.entry({ id = "prc006", sound = 12345, size = 47, time = -1 }),
		} })
		local list = Z.list(W)
		local a, b, c = list[1], list[2], list[3]
		check("procs: clean: the buff IDs are whole numbers listed once, the lights at most 40, a time over 120, a bad colour, a sound that is true and a size that is not even 24 to 64 are taken away",
			table.concat(a.spells, ",") == "17941,440873" and #a.lights == 40 and a.lights[40] == 1040 and a.time == nil and a.colour == nil and a.sound == nil and a.size == nil, table.concat(a.spells, ",") .. " " .. #a.lights)
		check("procs: clean: a trigger that is not registered is aura, overlay is kept", a.trigger == "aura" and b.trigger == "overlay")
		check("procs: clean: a time of 0, a colour, the sound false, a size of 24 are kept", b.time == 0 and b.colour == "ffd94040" and b.sound == false and b.size == 24)
		check("procs: clean: a kit of the list, 64 and 120 are kept, and an empty lights list stays a list", c.sound == 8959 and c.size == 64 and c.time == 120 and type(c.lights) == "table" and #c.lights == 0)
		check("procs: clean: an entry with no buff and no name is dropped, and one with a name and no spell stays", #list == 4 and list[4].id == "prc006" and list[3].id == "prc003", #list)
		check("procs: clean: a sound that is no kit of the list, a size of 47 and a time under 0 are taken away", list[4].sound == nil and list[4].size == nil and list[4].time == nil)
		check("procs: clean: the entry is kind proc with its names, and a missing lights list is a list", a.kind == "proc" and a.names[1] == "Shadow Trance" and type(list[4].lights) == "table", a.kind)
		check("procs: clean: no violation", Z.ok(W), Z.why(W))
	end

	-- 3. A buff that is up: the icon, the sound once, the end.
	do
		local W = Z.up({ list = { Z.entry() }, options = { ["trackers.sound"] = true } })
		Z.step(W, 0.3)
		local p = Z.parts(W)
		check("procs: no buff: the frame is clear, the icon has alpha 0 and no rim, and no sound", Z.alpha(W) == 0 and p.icon.alpha == 0 and Z.rim(p) == 0 and #W.au.played == 0 and Z.ok(W), Z.alpha(W) .. " " .. tostring(p.icon.alpha) .. " " .. Z.rim(p) .. " " .. #W.au.played .. Z.why(W))
		Z.give(W, 8)
		p = Z.parts(W)
		check("procs: the buff comes: the frame has alpha 1, the icon is the buff's, white, and a rim of the proc colour", Z.alpha(W) == 1 and p.icon.alpha == 1 and p.icon.file == Z.TRANCE_ICON and p.icon.vertex[1] == 1 and Z.rim(p) == 4
			and p.rim[1].color[1] == 1 and near(p.rim[1].color[2], 209 / 255) and p.rim[1].color[3] == 0, Z.alpha(W) .. " " .. tostring(p.icon.alpha) .. " " .. tostring(p.icon.file) .. " " .. tostring(p.icon.vertex and p.icon.vertex[1]) .. " " .. Z.rim(p) .. " " .. tostring(p.rim[1].color and p.rim[1].color[1]))
		check("procs: and the sound of the page plays once, the Spell alert", #W.au.played == 1 and W.au.played[1] == 23287, table.concat(W.au.played, ","))
		check("procs: and the sweep runs for the time left", p.cooldown.cd.sweep ~= nil and p.cooldown.cd.sweep.duration > 7 and p.cooldown.cd.sweep.duration <= 10, p.cooldown.cd.sweep and p.cooldown.cd.sweep.duration)
		Z.step(W, 0.5)
		Z.step(W, 0.5)
		check("procs: more passes play nothing more", #W.au.played == 1 and Z.alpha(W) == 1)
		Z.take(W)
		Z.step(W, 0.5)
		p = Z.parts(W)
		check("procs: the buff ends: the frame is clear again, and there is no sound for a drop, though Sound when it drops is on", Z.alpha(W) == 0 and p.icon.alpha == 0 and Z.rim(p) == 0 and #W.au.played == 1, #W.au.played)
		Z.give(W, 8)
		check("procs: the next proc plays the sound again", #W.au.played == 2 and Z.alpha(W) == 1, #W.au.played)
		check("procs: no violation", Z.ok(W), Z.why(W))
	end

	-- 4. The end of an alert: the spell it is for, its time.
	do
		local W = Z.up({ list = { Z.entry() } })
		Z.give(W, 600)
		check("procs: a buff of 600 seconds: the alert is up with one sound", Z.alpha(W) == 1 and #W.au.played == 1, #W.au.played)
		W.cast(686)
		Z.step(W, 0.3)
		check("procs: the spell it is for is cast: the alert ends though the buff is still on", Z.alpha(W) == 0 and Z.parts(W).icon.alpha == 0 and #W.au.played == 1 and Z.ok(W), Z.alpha(W))
		Z.step(W, 1)
		check("procs: and it does not come back while the same buff stays", Z.alpha(W) == 0 and #W.au.played == 1)
		W.cast(5000)
		Z.step(W, 0.3)
		Z.take(W)
		Z.give(W, 600)
		check("procs: the next proc is an alert again, with a sound", Z.alpha(W) == 1 and #W.au.played == 2, #W.au.played)
		W.cast(5000)
		Z.step(W, 0.3)
		check("procs: a cast of another spell ends nothing", Z.alpha(W) == 1)
		Z.run(W, 10.5)
		check("procs: its time of 10 seconds is up: the alert ends with no event, the buff still on", Z.alpha(W) == 0 and Z.parts(W).icon.alpha == 0 and #W.au.played == 2 and Z.ok(W), Z.alpha(W))
		Z.run(W, 3)
		check("procs: and it stays ended", Z.alpha(W) == 0 and #W.au.played == 2)
		local N = Z.up({ list = { Z.entry({ time = false }) } })
		Z.give(N, 30)
		Z.run(N, 20)
		check("procs: with no time the alert follows the buff, 30 seconds", Z.alpha(N) == 1, Z.alpha(N))
		Z.take(N)
		check("procs: and ends with it", Z.alpha(N) == 0)
		local S = Z.up({ list = { Z.entry({ time = 5 }) } })
		Z.give(S, 600)
		local sweep = Z.parts(S).cooldown.cd.sweep
		check("procs: a time shorter than the buff's gives the sweep its length", sweep ~= nil and sweep.duration == 5, sweep and sweep.duration)
	end

	-- 5. In a fight: the game's own icon, or nothing.
	do
		local W = Z.up({ list = { Z.entry() } })
		local S = Z.slots(W, { prc001 = true })
		Z.give(W, 600)
		W.beginFight()
		Z.step(W, 0.3)
		local p = Z.parts(W)
		check("procs: the game hides the buff and has its own icon: the frame has alpha 1, the icon of the tracker is clear, and the game's icon is shown", Z.alpha(W) == 1 and p.icon.alpha == 0 and Z.rim(p) == 0 and S.shown.prc001 == true and Z.ok(W), Z.alpha(W) .. " " .. tostring(S.shown.prc001) .. Z.why(W))
		check("procs: and no sound is played for that", #W.au.played == 1, #W.au.played)
		S.live.prc001 = false
		Z.step(W, 0.5)
		W.auraChanged()
		Z.step(W, 0.3)
		check("procs: the game hides the buff and has no icon: nothing, and what was known last is not shown", Z.alpha(W) == 0 and Z.parts(W).icon.alpha == 0 and S.shown.prc001 == false and Z.ok(W), Z.alpha(W))
		W.endFight()
		Z.step(W, 0.5)
		check("procs: the fight ends and the buff is read again: the alert is up", Z.alpha(W) == 1 and Z.parts(W).icon.alpha == 1 and #W.au.played == 1, Z.alpha(W))
		W.takeBuff(17941)
		S.live.prc001 = true
		W.beginFight()
		Z.step(W, 0.3)
		check("procs: a fight begins with the buff off and the game's icon ready: the frame has alpha 1 for the game's icon, which shows nothing, and the tracker's own icon is clear", Z.alpha(W) == 1 and S.shown.prc001 == true
			and Z.parts(W).icon.alpha == 0, Z.alpha(W))
		W.endFight()
		Z.step(W, 0.5)
		-- A buff the game never hides is read in a fight like any other.
		local N = Z.up({ list = { Z.entry() }, set = function(X) X.au.secrecy[17941] = 0 end })
		Z.give(N, 600)
		N.beginFight()
		Z.step(N, 0.3)
		check("procs: a buff flagged as never hidden is read in a fight, and the alert is up with the real time", Z.alpha(N) == 1 and Z.parts(N).icon.alpha == 1 and Z.rim(Z.parts(N)) == 4 and #N.au.played == 1 and Z.ok(N), Z.alpha(N))
		-- Only the buff's own hiding sets 'none' for a proc.
		local H = Z.up({ list = { Z.entry() } })
		H.beginFight()
		Z.step(H, 0.3)
		check("procs: a fight with no buff and no game icon: the frame is clear and nothing is played", Z.alpha(H) == 0 and #H.au.played == 0 and Z.ok(H), Z.alpha(H))
	end

	-- 6. The sound: the page's choice, the entry's own, the quiet seconds, a refused kit.
	do
		local KITS = { none = false, spell = 23287, chimes = 316736, bell = 316773, warhorn = 316723, raid = 8959, alarm = 12889, whisper = 37666 }
		local ok, got = true, {}
		for word, kit in pairs(KITS) do
			local W = Z.up({ list = { Z.entry() }, options = { ["trackers.procSound"] = word } })
			Z.give(W)
			got[#got + 1] = word .. "=" .. table.concat(W.au.played, ",")
			if kit == false then
				ok = ok and #W.au.played == 0
			else
				ok = ok and #W.au.played == 1 and W.au.played[1] == kit
			end
		end
		table.sort(got)
		check("procs: Sound: None plays nothing, and each of the others plays its kit once", ok, table.concat(got, " "))
		local sounds = loadfile(ADDON_DIR .. "/IconRow.lua") ~= nil
		local R = Z.up({ list = {} })
		check("procs: the first five kits of the Sound row are the five of ns.SOUNDS, in its order", sounds and R.ns.SOUNDS[1][1] == 23287 and R.ns.SOUNDS[2][1] == 316736 and R.ns.SOUNDS[3][1] == 316773 and R.ns.SOUNDS[4][1] == 316723 and R.ns.SOUNDS[5][1] == 8959
			and table.concat(R.menu("trackers.procSound"), ",") == "None,Spell alert,Chimes,Bell,Warhorn,Raid warning,Alarm,Whisper warning", table.concat(R.menu("trackers.procSound"), ","))
		local F = Z.up({ list = { Z.entry({ sound = false }) } })
		Z.give(F)
		local O = Z.up({ list = { Z.entry({ sound = 12889 }) } })
		Z.give(O)
		check("procs: an entry with sound false is silent, and one with a kit plays it, whatever the page says", #F.au.played == 0 and #O.au.played == 1 and O.au.played[1] == 12889, #F.au.played .. " " .. table.concat(O.au.played, ","))
		-- Nothing is played in the two seconds after login.
		local Q = Z.up({ list = { Z.entry() }, quiet = true })
		Z.give(Q)
		check("procs: a proc that is up in the first two seconds after login plays nothing", #Q.au.played == 0 and Z.alpha(Q) == 1, #Q.au.played)
		Z.step(Q, 3)
		check("procs: and plays nothing later for the same buff", #Q.au.played == 0)
		-- A kit that the game refuses.
		local A = Z.up({ list = { Z.entry() }, set = function(X) X.au.refuse[23287] = true end })
		Z.give(A)
		Z.take(A)
		Z.give(A)
		check("procs: the Spell alert refused: nothing is played, there is one note however many alerts, and the game was asked once for each", #A.au.played == 0 and count(A.status(), Z.NO_SOUND) == 1 and A.au.refused == 2, count(A.status(), Z.NO_SOUND) .. " " .. tostring(A.au.refused))
		local B = Z.up({ list = { Z.entry({ sound = 8959 }) }, set = function(X) X.au.refuse[8959] = true end })
		Z.give(B)
		check("procs: a kit refused is tried once as the Spell alert, which plays, with no note", #B.au.played == 1 and B.au.played[1] == 23287 and not has(B.status(), Z.NO_SOUND) and B.au.refused == 1, table.concat(B.au.played, ",") .. " " .. tostring(B.au.refused))
		local C = Z.up({ list = { Z.entry({ sound = 8959 }) }, set = function(X) X.au.refuse[8959], X.au.refuse[23287] = true, true end })
		Z.give(C)
		Z.take(C)
		Z.give(C)
		check("procs: both refused: silence, with one note", #C.au.played == 0 and count(C.status(), Z.NO_SOUND) == 1 and C.au.refused == 4, count(C.status(), Z.NO_SOUND) .. " " .. tostring(C.au.refused))
		check("procs: and the check says the sound failed", has(C.slash("tracker check"), "Sound: failed."), C.slash("tracker check"))
		check("procs: no violation", Z.ok(A) and Z.ok(B) and Z.ok(C), Z.why(C))
	end

	-- 7. The game's overlay: four events and IsSpellOverlayed. The overlay is read where the buff is hidden, so these worlds are in a fight.
	do
		local SHOW, HIDE, GLOW, GLOW_OFF = "SPELL_ACTIVATION_OVERLAY_SHOW", "SPELL_ACTIVATION_OVERLAY_HIDE", "SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", "SPELL_ACTIVATION_OVERLAY_GLOW_HIDE"
		local function fight(o)
			local W = Z.up(o)
			W.beginFight()
			Z.step(W, 0.3)
			return W
		end
		local W = fight({ list = { Z.entry({ trigger = "overlay", time = 8 }) } })
		local H = Z.hooks(W)
		local heard = {}
		for _, event in ipairs({ SHOW, HIDE, GLOW, GLOW_OFF }) do
			heard[event] = 0
			for _, f in ipairs(W.eventFrames) do
				if f.events[event] then
					heard[event] = heard[event] + 1
				end
			end
		end
		check("procs: the watcher of the trackers hears the four events of the game's overlay", heard[SHOW] == 1 and heard[HIDE] == 1 and heard[GLOW] == 1 and heard[GLOW_OFF] == 1, heard[SHOW] .. heard[HIDE] .. heard[GLOW] .. heard[GLOW_OFF])
		check("procs: overlay: before any event nothing is known, the frame is clear", Z.alpha(W) == 0 and has(W.slash("tracker check"), "Up now: not known."), Z.alpha(W))
		W.fire(SHOW, 17941, 449492, 9, 1, 1, 1, 1)
		Z.step(W, 0.3)
		check("procs: an overlay event for the buff starts the alert: the frame, the icon of the spell and one sound", Z.alpha(W) == 1 and Z.parts(W).icon.alpha == 1 and Z.parts(W).icon.file == Z.TRANCE_ICON and #W.au.played == 1, Z.alpha(W))
		check("procs: the art is given the payload of the game, with the location by its name, and the glow starts once", #H.art == 1 and H.art[1].data.file == 449492 and H.art[1].data.location == "LeftRight" and H.art[1].data.scale == 1
			and H.art[1].data.r == 1 and H.art[1].data.g == 1 and H.art[1].data.b == 1 and #H.glow == 1 and H.art[1].entry.id == "prc001", #H.art)
		check("procs: and the check says it is up", has(W.slash("tracker check"), "Up now: yes."), W.slash("tracker check"))
		W.fire(HIDE)
		Z.step(W, 0.3)
		check("procs: a hide event with no spell ends all: the frame is clear, the art and the glow stop once", Z.alpha(W) == 0 and #H.hide == 1 and #H.stop == 1 and H.hide[1].id == "prc001", Z.alpha(W))
		check("procs: and with the events seen the proc is known to be down", has(W.slash("tracker check"), "Up now: no."), W.slash("tracker check"))
		W.fire(SHOW, SECRET, 449492, 9, 1, 1, 1, 1)
		Z.step(W, 0.3)
		check("procs: an event with a spell that is withheld is counted and starts nothing", Z.alpha(W) == 0 and #H.art == 1 and Z.ok(W), Z.alpha(W))
		W.fire(SHOW, 440873, 449492, 9, 1, 1, 1, 1)
		Z.step(W, 0.3)
		check("procs: an event for another spell starts nothing", Z.alpha(W) == 0 and #H.art == 1)
		W.fire(SHOW, 17941, 449492, 9, 1, 1, 1, 1)
		Z.step(W, 0.3)
		W.fire(HIDE, 440873)
		Z.step(W, 0.3)
		check("procs: a hide event for another spell ends nothing", Z.alpha(W) == 1 and #H.hide == 1)
		W.fire(HIDE, 17941)
		Z.step(W, 0.3)
		check("procs: and one for the spell ends it", Z.alpha(W) == 0 and #H.hide == 2 and #H.stop == 2, Z.alpha(W))
		W.fire(SHOW, 17941, 449492, 9, 1, 1, 1, 1)
		Z.run(W, 9)
		check("procs: no hide event: the time of 8 seconds ends the alert", Z.alpha(W) == 0 and #H.hide == 3, Z.alpha(W))
		check("procs: the check counts what was seen, 5 shows, 3 hides, none glowing", has(W.slash("tracker check"), "Game signal: seen 8 times this session (show 5, hide 3, glow 0)."), W.slash("tracker check"))
		check("procs: no violation", Z.ok(W), Z.why(W))
		-- The glow events are for the spells the proc is for.
		local G = fight({ list = { Z.entry({ trigger = "overlay", time = 8 }) } })
		G.fire(GLOW, 999)
		Z.step(G, 0.3)
		check("procs: a glow event for a spell the proc is not for starts nothing", Z.alpha(G) == 0)
		G.fire(GLOW, 25307)
		Z.step(G, 0.3)
		check("procs: a glow event for a spell it is for starts the alert", Z.alpha(G) == 1 and #G.au.played == 1, Z.alpha(G))
		G.fire(GLOW_OFF, 25307)
		Z.step(G, 0.3)
		check("procs: and its hide event ends it", Z.alpha(G) == 0)
		G.fire(GLOW, 686)
		Z.step(G, 0.3)
		G.cast(686)
		Z.step(G, 0.3)
		check("procs: the cast of the spell it is for ends an alert the overlay started", Z.alpha(G) == 0, Z.alpha(G))
		check("procs: the check counts glow events: 4 of them, none of the others", has(G.slash("tracker check"), "Game signal: seen 4 times this session (show 0, hide 0, glow 4)."), G.slash("tracker check"))
		-- The alert of an overlay with no time is not shown, and an entry that is not on the overlay trigger ignores the events.
		local N = fight({ list = { Z.entry({ trigger = "overlay", time = false }), Z.entry({ id = "prc002", trigger = "aura", name = "Decimation", names = { "Decimation" }, spells = { 440873 } }) } })
		N.fire(SHOW, 17941, 449492, 9, 1, 1, 1, 1)
		N.fire(SHOW, 440873, 449492, 9, 1, 1, 1, 1)
		Z.step(N, 0.3)
		check("procs: an overlay signal with no time is not shown, and an entry on the aura trigger ignores the overlay", Z.alpha(N, 1) == 0 and Z.alpha(N, 2) == 0 and Z.ok(N), Z.alpha(N, 1) .. Z.alpha(N, 2))
		-- Where the buff is readable the overlay is not asked.
		local R = Z.up({ list = { Z.entry({ trigger = "overlay", time = 8 }) } })
		R.fire(SHOW, 17941, 449492, 9, 1, 1, 1, 1)
		Z.step(R, 0.3)
		check("procs: where the buff can be read the buff decides: an overlay event with no buff is no alert", Z.alpha(R) == 0 and has(R.slash("tracker check"), "Up now: no."), Z.alpha(R))
		-- IsSpellOverlayed at login and when the spells change.
		-- The wait of a flush runs every timer, a time of the alert's included, so this world is logged in and given a second.
		local L = Z.world({ list = { Z.entry({ trigger = "overlay", time = 60 }) }, set = function(X) X.au.hidden = true X.au.overlayed[25307] = true end })
		L.login()
		Z.step(L, 1)
		check("procs: a spell the game says is overlaid at login starts the alert, and the game was asked", Z.alpha(L) == 1 and (L.au.calls.IsSpellOverlayed or 0) >= 1, Z.alpha(L))
		local C = Z.up({ list = { Z.entry({ trigger = "overlay", time = 8 }) }, set = function(X) X.au.hidden = true end })
		C.au.overlayed[686] = true
		C.fire("SPELLS_CHANGED")
		Z.step(C, 0.3)
		check("procs: and when the spells change", Z.alpha(C) == 1, Z.alpha(C))
		local M = Z.up({ list = { Z.entry({ trigger = "overlay", time = 8 }) }, set = function(X) X.au.hidden = true X.au.overlayed[686] = true end })
		check("procs: the answer of IsSpellOverlayed is not an event: the counts stay 0", has(M.slash("tracker check"), "Game signal: seen 0 times this session (show 0, hide 0, glow 0)."), M.slash("tracker check"))
		local Off = Z.up({ list = { Z.entry({ trigger = "overlay", time = 8 }) }, set = function(X) X.au.hidden = true X.env.C_SpellActivationOverlay = nil end })
		check("procs: a game with no IsSpellOverlayed: nothing is asked, nothing raises", Z.alpha(Off) == 0 and Z.ok(Off), Z.why(Off))
	end

	-- 8. Adding and removing: the page, the commands.
	do
		local BUFF = { id = "bff001", kind = "buff", name = "Demon Armor", names = { "Demon Armor" }, spells = { 706 } }
		local W = Z.up({ list = { BUFF } })
		check("procs: add: the row lists the procs of the class that the player knows a spell for, by name and trigger, after Choose a proc", table.concat(W.menu("trackers.addProc"), ",") == "Choose a proc,Decimation, cast time,Shadow Trance, cast time", table.concat(W.menu("trackers.addProc"), ","))
		W.pickAt("trackers.addProc", 3)
		local list = Z.list(W)
		local e = list[2]
		check("procs: add: choosing one adds it and says so", W.out[#W.out] == "Added Shadow Trance." and #list == 2 and e.kind == "proc" and e.name == "Shadow Trance" and e.names[1] == "Shadow Trance" and #e.id == 6, tostring(W.out[#W.out]))
		check("procs: add: its buff, the spells it is for that the player knows, the cast time trigger, the time of the data, the icon size 48 and Show Always", e.spells[1] == 17941 and #e.spells == 1 and table.concat(e.lights, ",") == "686,25307"
			and e.trigger == "casttime" and e.kind2 == nil and e.time == 10 and e.size == 48 and e.show == "always" and e.sound == nil and e.colour == nil, table.concat(e.lights, ","))
		check("procs: add: the row now lists the other one, and the row is back on Choose a proc", table.concat(W.menu("trackers.addProc"), ",") == "Choose a proc,Decimation, cast time" and W.read("trackers.addProc") == "Choose a proc")
		W.pickAt("trackers.addProc", 2)
		check("procs: add: the second has its own lights and time", Z.list(W)[3].name == "Decimation" and table.concat(Z.list(W)[3].lights, ",") == "6353" and Z.list(W)[3].time == 10, table.concat(Z.list(W)[3].lights, ","))
		check("procs: add: none is left to add, and the page's row shows Choose a proc alone", table.concat(W.menu("trackers.addProc"), ",") == "Choose a proc")
		check("procs: add: the row of the page lists the procs after the buff, in list order", table.concat(W.menu("trackers.removeProc"), ",") == "Choose a proc,Shadow Trance,Decimation", table.concat(W.menu("trackers.removeProc"), ","))
		check("procs: add: ProcAdd of a number that is no row says Not added.", select(2, W.ns.ProcAdd(99)) == "Not added." and select(2, W.ns.ProcAdd("x")) == "Not added.")
		check("procs: add: no violation", Z.ok(W), Z.why(W))
		W.pickAt("trackers.removeProc", 2)
		check("procs: remove: choosing one removes it, with its number among all the trackers, and says so", W.out[#W.out] == "Removed Shadow Trance." and #Z.list(W) == 2 and Z.list(W)[2].name == "Decimation", tostring(W.out[#W.out]))
		check("procs: remove: a number that is a buff is not a proc, and nothing goes", select(2, W.ns.ProcRemove(1)) == "No proc numbered 1." and #Z.list(W) == 2 and select(2, W.ns.ProcRemove(7)) == "No proc numbered 7.")
		check("procs: remove: the proc it removed is a candidate again", table.concat(W.menu("trackers.addProc"), ",") == "Choose a proc,Shadow Trance, cast time")
		-- A class with no list, and no spell known.
		local D = Z.up({ list = {}, class = "DEATHKNIGHT" })
		check("procs: a class with no list has no rows to add", table.concat(D.menu("trackers.addProc"), ",") == "Choose a proc" and #D.ns.ProcCandidates() == 0)
		local K = Z.up({ list = {}, set = function(X) X.sp.data[686].known, X.sp.data[686].line = false, nil X.sp.data[25307].known, X.sp.data[25307].line = false, nil
			X.sp.data[6353].known, X.sp.data[6353].line = false, nil end })
		check("procs: no spell of a proc known: no row", #K.ns.ProcCandidates() == 0, #K.ns.ProcCandidates())
		local S = Z.up({ list = {}, set = function(X) X.au.unit.player = { class = "WARLOCK", guid = "Player-1" } X.au.identityHidden = true end })
		check("procs: a class the game withholds gives no rows, and raises nothing", #S.ns.ProcCandidates() == 0 and Z.ok(S), Z.why(S))

		-- The commands.
		local C = Z.up({ list = { BUFF } })
		check("procs: add proc with a spell it is for: the buff and every rank of the spell, from the spell book", C.slash("tracker add proc Shadow Trance for Shadow Bolt") == "Added Shadow Trance." and #Z.list(C) == 2, C.slash("tracker list"))
		local c = Z.list(C)[2]
		check("procs: add proc: spells, names, the lights with the spell's own ID first, no time, the aura trigger, Show Always, size 48", c.kind == "proc" and c.name == "Shadow Trance" and c.spells[1] == 17941 and #c.spells == 1 and c.lights[1] == 25307 and c.lights[2] == 686
			and #c.lights == 2 and c.time == nil and c.trigger == "aura" and c.show == "always" and c.size == 48, table.concat(c.lights, ","))
		check("procs: add proc: the same again is already tracked, with any capitals", C.slash("tracker add proc Shadow Trance for Shadow Bolt") == "Already tracked." and C.slash("tracker add PROC Shadow Trance") == "Already tracked." and #Z.list(C) == 2)
		check("procs: add proc with no spell it is for: the lights list is empty, and it alerts only", C.slash("tracker add proc Decimation") == "Added Decimation." and #Z.list(C)[3].lights == 0 and Z.list(C)[3].spells[1] == 440873)
		check("procs: add proc by spell IDs, and the word for in capitals", C.slash("tracker add proc 17941 FOR 686") == "Already tracked.")
		local E = Z.up({ list = {} })
		check("procs: add proc by IDs: the buff and the spell", E.slash("tracker add proc 17941 for 686") == "Added Shadow Trance." and Z.list(E)[1].lights[1] == 686 and #Z.list(E)[1].lights == 2)
		check("procs: add proc: a buff that is not a spell, and a spell it is for that is not one, say which", C.slash("tracker add proc Nonsense for Shadow Bolt") == 'No spell found for "Nonsense".' and C.slash("tracker add proc Decimation for Nonsense") == 'No spell found for "Nonsense".'
			and #Z.list(C) == 3)
		check("procs: add proc alone asks which, and nothing is added", has(C.slash("tracker add proc"), "Which proc?") and #Z.list(C) == 3)
		check("procs: the list names a proc with its kind", has(C.slash("tracker list"), "2. Shadow Trance, proc alert, place Personal resource display, 2 own settings\n3. Decimation, proc alert, place Personal resource display, 2 own settings"), C.slash("tracker list"))
		-- tracker proc colour, time and trigger.
		check("procs: proc colour sets the entry's colour, by its number or its name, with or without #", C.slash("tracker proc colour 2 4d99e6") == "Proc 2: colour is 4d99e6." and Z.list(C)[2].colour == "ff4d99e6"
			and C.slash("tracker proc colour Decimation #d94040") == "Proc 3: colour is d94040." and Z.list(C)[3].colour == "ffd94040", C.slash("tracker proc colour 2 zz"))
		check("procs: proc colour: eight digits are taken as they are, and a bad one changes nothing", C.slash("tracker proc colour 2 80d94040") == "Proc 2: colour is d94040." and Z.list(C)[2].colour == "80d94040" and C.slash("tracker proc colour 2 zz") == "Proc 2: zz is not a colour. Six or eight digits, such as ffd100."
			and Z.list(C)[2].colour == "80d94040")
		check("procs: proc time sets seconds, 0 is no limit, over 120 is refused", C.slash("tracker proc time 2 30") == "Proc 2: time is 30 seconds." and Z.list(C)[2].time == 30 and C.slash("tracker proc time 2 0") == "Proc 2: no time limit." and Z.list(C)[2].time == 0
			and C.slash("tracker proc time 2 200") == "Proc 2: time is 0 to 120 seconds." and Z.list(C)[2].time == 0 and C.slash("tracker proc time 2 x") == "Proc 2: time is 0 to 120 seconds.")
		check("procs: proc trigger sets a trigger that is registered and refuses another", C.slash("tracker proc trigger 2 overlay") == "Proc 2: trigger is overlay." and Z.list(C)[2].trigger == "overlay" and C.slash("tracker proc trigger 2 bogus") == 'Proc 2: "bogus" is not a trigger.'
			and Z.list(C)[2].trigger == "overlay")
		check("procs: a time with a fraction is kept, and the check of the overlay trigger names it", C.slash("tracker proc time 2 7.5") == "Proc 2: time is 7.5 seconds." and Z.list(C)[2].time == 7.5 and has(C.slash("tracker check"), "Time: 7.5 seconds."), C.slash("tracker check"))
		C.ns.ProcTrigger("never", { Valid = function() return false, "Proc 2: no." end })
		check("procs: a trigger whose Valid says no is refused with its message", C.slash("tracker proc trigger 2 never") == "Proc 2: no." and Z.list(C)[2].trigger == "overlay")
		check("procs: proc with a word that is none, or no proc, or no word prints the usage", C.slash("tracker proc") == "Usage: /flatui tracker proc colour 1 ffd100, proc time 1 10 or proc trigger 1 aura." and C.slash("tracker proc colour 9 ffd100") == 'No proc found for "9".'
			and C.slash("tracker proc size 2 40") == "Usage: /flatui tracker proc colour 1 ffd100, proc time 1 10 or proc trigger 1 aura." and C.slash("tracker proc colour 1 ffd100") == 'No proc found for "1".')
		check("procs: set sound off makes it silent, on is not a value, size follows the kinds' own rule", C.slash("tracker set 2 sound off") == "Tracker 2: sound is off." and Z.list(C)[2].sound == false and C.slash("tracker set 2 sound on") == 'Tracker 2: "on" is not a value for sound.'
			and C.slash("tracker set 2 size 52") == "Tracker 2: size is 52." and Z.list(C)[2].size == 52 and C.slash("tracker set 2 size 20") == 'Tracker 2: "20" is not a value for size.' and Z.list(C)[2].size == 52, C.slash("tracker set 2 sound off"))
		check("procs: a proc's colour and time are read at the next pass: the rim is the new colour", (function()
			local X = Z.up({ list = { Z.entry() } })
			X.slash("tracker proc colour 1 d94040")
			Z.give(X, 600)
			local p = Z.parts(X)
			return Z.rim(p) == 4 and near(p.rim[1].color[1], 217 / 255) and near(p.rim[1].color[2], 64 / 255) and Z.ok(X)
		end)())
		-- In a fight.
		local F = Z.up({ list = { BUFF } })
		local frames = #F.addonFrames
		F.beginFight()
		Z.step(F, 0.3)
		check("procs: in a fight a proc is added, and no frame is made until the fight is over", F.slash("tracker add proc Decimation") == "Added Decimation." and #F.addonFrames == frames and Z.ok(F), #F.addonFrames .. " " .. frames)
		F.endFight()
		Z.step(F, 0.5)
		check("procs: and then it has its frame", #F.addonFrames > frames and Z.frame(F, 2) ~= nil and Z.ok(F), #F.addonFrames .. " " .. frames)
	end

	-- 9. A trigger of another build, and the hooks.
	do
		local W = Z.up({ list = { Z.entry({ trigger = "yours" }) } })
		check("procs: an entry with a trigger no build registered is aura", Z.list(W)[1].trigger == "aura")
		local up = false
		W.ns.ProcTrigger("yours", { Text = "your cast", Read = function() return up and { state = "fine", hidden = false, expires = nil, length = nil } or nil end,
			Lines = function() return { "Yours: seen." } end })
		Z.list(W)[1].trigger = "yours"
		W.beginFight()
		Z.step(W, 0.3)
		check("procs: a trigger of another build gives its reading when the aura is hidden: nothing while it says nothing", Z.alpha(W) == 0 and Z.ok(W), Z.alpha(W))
		up = true
		W.auraChanged()
		Z.step(W, 0.3)
		check("procs: and the alert while it says fine, with the sound", Z.alpha(W) == 1 and #W.au.played == 1, Z.alpha(W))
		check("procs: and its lines are in the check", has(W.slash("tracker check"), "Trigger: yours.") and has(W.slash("tracker check"), "Yours: seen."), W.slash("tracker check"))
		check("procs: ns.ProcTrigger refuses a name that is not text and a definition that is not a table", W.ns.ProcTrigger(7, {}) == false and W.ns.ProcTrigger("x", 7) == false and W.ns.ProcTrigger("x", {}) == true)
		-- A trigger whose Read raises is read as nothing.
		local R = Z.up({ list = { Z.entry({ trigger = "boom" }) } })
		R.ns.ProcTrigger("boom", { Read = function() error("Read failed", 0) end })
		Z.list(R)[1].trigger = "boom"
		R.beginFight()
		Z.step(R, 0.3)
		check("procs: a trigger whose Read raises is read as unknown, and nothing stops", Z.alpha(R) == 0 and Z.ok(R), Z.why(R))
	end

	-- 10. The check.
	do
		local W = Z.up({ list = { Z.entry() } })
		local text = W.slash("tracker check")
		check("procs: check: the first lines are the name and kind, the reading, and nothing drawn while the proc is down", has(text, "1. Shadow Trance, proc alert\n   Now: missing.\n   Shown as: nothing.\n"), text:sub(1, 300))
		check("procs: check: the trigger, the level of the buff, whether it is up, the signals, the overlay frame, the display, the sound", has(text, "   Trigger: aura.\n   Aura level: hidden in fights.\n   Sound in fights: none while the game hides the buff.\n   Up now: no.\n   Game signal: seen 0 times this session (show 0, hide 0, glow 0).\n   Overlay frame: the game has none.\n   Personal resource display: enabled yes.\n   Sound: not played yet.\n"), text)
		Z.give(W, 600)
		text = W.slash("tracker check")
		check("procs: check: with the buff on the proc is up and the sound is said to have played", has(text, "Up now: yes.") and has(text, "Sound: played.") and has(text, "Now: on, no charges, "), text)
		W.beginFight()
		Z.step(W, 0.3)
		check("procs: check: in a fight with the buff hidden, whether it is up is not known", has(W.slash("tracker check"), "Up now: not known.") and has(W.slash("tracker check"), "Shown as: nothing."))
		local levels = { { 0, "never hidden" }, { 1, "always hidden" }, { 2, "hidden in fights" } }
		local said = {}
		for _, case in ipairs(levels) do
			local L = Z.up({ list = { Z.entry() }, set = function(X) X.au.secrecy[17941] = case[1] end })
			said[#said + 1] = has(L.slash("tracker check"), "Aura level: " .. case[2] .. ".")
		end
		check("procs: check: the level of the buff, by what the game says", said[1] and said[2] and said[3], tostring(said[1]) .. tostring(said[2]) .. tostring(said[3]))
		local M = Z.up({ list = { Z.entry({ spells = { 17941, 440873 } }) }, set = function(X) X.au.secrecy[440873] = 1 end })
		check("procs: check: IDs that disagree say mixed", has(M.slash("tracker check"), "Aura level: mixed."), M.slash("tracker check"))
		local N = Z.up({ list = { Z.entry() }, set = function(X) X.env.C_Secrets.GetSpellAuraSecrecy = nil end })
		check("procs: check: a game with no question of the level says not known", has(N.slash("tracker check"), "Aura level: not known."))
		local O = Z.up({ list = { Z.entry() }, set = function(X) X.env.SpellActivationOverlayFrame = {} X.au.prd = false end })
		check("procs: check: an overlay frame that exists, and a personal resource display that is off", has(O.slash("tracker check"), "Overlay frame: exists.") and has(O.slash("tracker check"), "Personal resource display: enabled no."))
		local P = Z.up({ list = { Z.entry() }, set = function(X) X.env.C_GameRules = nil end })
		check("procs: check: a game with no such question says not known", has(P.slash("tracker check"), "Personal resource display: enabled not known."))
		local Q = Z.up({ list = { Z.entry({ sound = false }) } })
		check("procs: check: with the sound none the line says none", has(Q.slash("tracker check"), "Sound: none."))
		local R = Z.up({ list = { Z.entry() } })
		R.ns.ProcArtLine = function() return "Art: arc." end
		R.ns.ProcGlowLine = function() return nil end
		check("procs: check: the lines of the art and the glow are added when the files are there, and an empty one adds none", has(R.slash("tracker check"), "   Art: arc.\n") and not has(R.slash("tracker check"), "Glow:"))
		local banned = { "carries", "sits", "lives in", "lands", "runs through", "ensure", "simply", "easily", "secret", "instance", "read path", "game-drawn", "Flat UI", "addon" }
		local texts, words = { R.slash("tracker check"), W.slash("tracker test"), table.concat(W.out, "\n") }, {}
		for _, t in ipairs(texts) do
			for line in (t .. "\n"):gmatch("([^\n]*)\n") do
				for _, word in ipairs(banned) do
					if line:lower():find(word:lower(), 1, true) then
						words[#words + 1] = word .. ": " .. line
					end
				end
				if line:find("\226") then
					words[#words + 1] = "dash: " .. line
				end
			end
		end
		check("procs: check: none of the banned words in the lines, and no dash", #words == 0, table.concat(words, " | "))
	end

	-- 11. The test.
	do
		local BUFF = { id = "bff001", kind = "buff", name = "Demon Armor", names = { "Demon Armor" }, spells = { 706 } }
		local W = Z.up({ list = { Z.entry() } })
		local H = Z.hooks(W)
		local out = W.slash("tracker test")
		local p = Z.parts(W)
		check("procs: test: a proc shows its icon in the row, plays its sound once and says so, with the art and the glow started", out == "Test: the icon and the sound of each proc. 5 seconds.\nSound: played." and Z.alpha(W) == 1 and p.icon.alpha == 1 and Z.rim(p) == 4
			and #W.au.played == 1 and W.au.played[1] == 23287 and #H.art == 1 and #H.glow == 1 and H.art[1].data.file == 449492, out)
		Z.step(W, 4)
		check("procs: test: it is still shown after 4 seconds", Z.alpha(W) == 1 and #H.hide == 0)
		Z.step(W, 1.2)
		check("procs: test: after 5 seconds it is back to the real state, nothing, and the art and the glow stop", Z.alpha(W) == 0 and Z.parts(W).icon.alpha == 0 and #H.hide == 1 and #H.stop == 1 and Z.ok(W), Z.alpha(W))
		check("procs: test: the real state is read again, so a proc that is up shows after the test", (function()
			Z.give(W, 600)
			W.slash("tracker test")
			Z.step(W, 6)
			return Z.alpha(W) == 1 and Z.parts(W).icon.alpha == 1
		end)())
		local M = Z.up({ list = { BUFF, Z.entry() } })
		local both = M.slash("tracker test")
		check("procs: test: a buff and a proc together: the buff's three looks and the proc's five seconds, each in its own lines", has(both, "Test: fine, low, missing, then the game's own look. 3 seconds each.") and has(both, "Test: the icon and the sound of each proc. 5 seconds.\nSound: played."), both)
		Z.run(M, 12)
		check("procs: test: both are over after 12 seconds, and nothing is stuck", Z.alpha(M, 2) == 0 and Z.ok(M), Z.alpha(M, 2))
		local N = Z.up({ list = { BUFF, Z.entry() } })
		check("procs: test: a number picks one: the proc alone, and the buff alone", N.slash("tracker test 2") == "Test: the icon and the sound of each proc. 5 seconds.\nSound: played." and N.slash("tracker test 1") == "Test: fine, low, missing, then the game's own look. 3 seconds each.")
		check("procs: test: a number that is nothing says so", N.slash("tracker test 9") == "No tracker numbered 9.")
		local S = Z.up({ list = { Z.entry({ sound = false }) } })
		check("procs: test: the sound none says none", S.slash("tracker test") == "Test: the icon and the sound of each proc. 5 seconds.\nSound: none." and #S.au.played == 0)
		local F = Z.up({ list = { Z.entry() }, set = function(X) X.au.refuse[23287] = true end })
		check("procs: test: a sound the game refuses says failed", F.slash("tracker test") == "Test: the icon and the sound of each proc. 5 seconds.\nSound: failed.")
		local C = Z.up({ list = { Z.entry() } })
		C.beginFight()
		check("procs: test: in a fight it runs out of combat", C.slash("tracker test") == "The test runs out of combat.")
		local T = Z.up({ list = { Z.entry() } })
		local TH = Z.hooks(T)
		T.slash("tracker test")
		Z.step(T, 2)
		T.slash("tracker test")
		Z.step(T, 3.5)
		check("procs: test: a second test starts the five seconds again, and the first one's end does not cut it", Z.alpha(T) == 1 and #TH.art == 2 and Z.ok(T), Z.alpha(T) .. " " .. #TH.art)
		Z.step(T, 2)
		check("procs: test: and it ends five seconds after the second", Z.alpha(T) == 0)
	end

	-- 12. What the engine gives a kind: the slot spec, the hooks, the word, the order.
	do
		local BUFF = { id = "bff001", kind = "buff", name = "Demon Armor", names = { "Demon Armor" }, spells = { 706 } }
		local fine, missing = { state = "fine", hidden = false, icon = Z.ICON }, { state = "missing", hidden = false }
		-- A kind of the test: the reading it gives is X.now, and it writes what the engine tells it into X.log.
		local function kind(X, name, more)
			local spec = { Read = function() return X.now end, Clean = function(entry) return type(entry.id) == "string" end, what = name, Label = function() return name end }
			for k, v in pairs(more or {}) do
				spec[k] = v
			end
			X.ns.TrackerKind(name, spec)
		end
		local function zz(id, more)
			local e = { id = id, kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } }
			for k, v in pairs(more or {}) do
				e[k] = v
			end
			return e
		end
		-- ns.TrackerSlotSpec.
		local W = Z.up({ list = { BUFF, Z.entry(), { id = "wpn001", kind = "weapon", slot = "main" } }, set = function(X) kind(X, "zzslot", { slot = { unit = "target", filter = "HARMFUL|PLAYER" } }) kind(X, "zzplain") end })
		local buff, proc, weapon = Z.list(W)[1], Z.list(W)[2], Z.list(W)[3]
		local spec = W.ns.TrackerSlotSpec(buff)
		check("procs: slot spec: a buff is the player and HELPFUL, so is an entry with no kind and a proc", spec.unit == "player" and spec.filter == "HELPFUL" and W.ns.TrackerSlotSpec({ id = "x" }).filter == "HELPFUL"
			and W.ns.TrackerSlotSpec(proc).unit == "player" and W.ns.TrackerSlotSpec(proc).filter == "HELPFUL")
		check("procs: slot spec: a kind that names a slot gives it, and a kind that does not gives nothing", W.ns.TrackerSlotSpec({ id = "y", kind = "zzslot" }).unit == "target" and W.ns.TrackerSlotSpec({ id = "y", kind = "zzslot" }).filter == "HARMFUL|PLAYER"
			and W.ns.TrackerSlotSpec(weapon) == nil and W.ns.TrackerSlotSpec({ id = "y", kind = "zzplain" }) == nil and W.ns.TrackerSlotSpec({ id = "y", kind = "nobody" }) == nil and W.ns.TrackerSlotSpec(7) == nil)
		local S = Z.slots(W)
		W.ns.TrackerSlots.Sync = W.ns.TrackerSlots.Sync
		W.advance(0)
		W.slash("tracker add proc Decimation")
		Z.step(W, 0.5)
		check("procs: slot spec: the game's own icons are given the buffs and the procs, and no other kind", S.calls[#S.calls] == "Sync:3" and table.concat(S.synced, ",") == "bff001,prc001," .. Z.list(W)[4].id, table.concat(S.synced, ","))
		-- The real icons: the slot of a proc is made for the player and HELPFUL, that of a kind with a slot for its unit and filter.
		local R = Z.up({ real = true, list = { Z.entry(), zz("zzs001", { kind = "zzslot" }) }, set = function(X) kind(X, "zzslot", { slot = { unit = "target", filter = "HARMFUL|PLAYER" } }) end })
		Z.give(R, 600)
		local log = table.concat(R.ac.log, "\n")
		check("procs: the real icon of a proc: the container watches the player and the slot takes HELPFUL", has(log, "container:SetUnit:player") and has(log, "container:AddAuraSlot:tracker,HELPFUL,table"), log:sub(1, 400))
		check("procs: and a kind with a slot of its own: its unit and its filter", has(log, "container:SetUnit:target") and has(log, "container:AddAuraSlot:tracker,HARMFUL|PLAYER,table") and Z.ok(R), Z.why(R))
		-- Cleaning a buff for a kind, the word.
		local entry = { spells = { 5, 5, -1 }, name = "Aa" }
		check("procs: ns.TrackerCleanBuff cleans spells and names for a kind, takes the kind's name, and leaves the common fields when no list of taken IDs is given", W.ns.TrackerCleanBuff(entry, nil, "zzkind") == true and entry.kind == "zzkind" and #entry.spells == 1 and entry.names[1] == "Aa" and entry.id == nil)
		local taken, other = {}, { spells = { 5 } }
		check("procs: and with the list the id is made too, and an entry with nothing is dropped", W.ns.TrackerCleanBuff(other, taken, "zzkind") == true and #other.id == 6 and taken[other.id] == true and W.ns.TrackerCleanBuff({ spells = {} }, {}, "zzkind") == false)
		check("procs: ns.TrackerWord adds a word to /flatui tracker, prints what the word gives, ignores one that raises, and refuses what is not a word", W.ns.TrackerWord("zzw", function(text) return "heard " .. text end) == true
			and W.slash("tracker zzw one two") == "heard one two" and W.ns.TrackerWord("zzr", function() error("zzr failed", 0) end) == true and W.slash("tracker zzr") == ""
			and W.ns.TrackerWord("", print) == false and W.ns.TrackerWord("zz", 7) == false, W.slash("tracker zzw one two"))
		check("procs: the words that were there still work", W.slash("tracker add pet") == "Added Pet." and has(W.slash("tracker list"), "Pet, pet"))
	end

	-- 13. The hooks of a kind: Changed, Wanted, Hide, noLast, noDrop, last, Gone, World, Test, Rim, own, part.
	do
		-- A world with one tracker of the kind zzkind. rec is the table the hooks write to; the world is rec.W.
		local function world(more, o, rec)
			local X = rec or {}
			X.now, X.changes, X.gone, X.world, X.tests = { state = "missing", hidden = false }, {}, {}, 0, {}
			local spec = { Read = function() return X.now end, Clean = function(entry) return type(entry.id) == "string" end, what = "zz", Label = function() return "Zz" end }
			for k, v in pairs(more or {}) do
				spec[k] = v
			end
			local opts = o or {}
			opts.set = function(W)
				X.W = W
				W.ns.TrackerKind("zzkind", spec)
			end
			opts.list = opts.list or { { id = "zzk001", kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } } }
			X.W = Z.up(opts)
			return X
		end
		local function frameOf(X, id)
			return X.W.ns.TrackerFrame({ id = id or "zzk001" })
		end
		-- Changed: once for each change of the state that was kept, not for unknown.
		local X = {}
		world({ Changed = function(entry, before, after) X.changes[#X.changes + 1] = tostring(before) .. ">" .. after .. ":" .. entry.id end }, nil, X)
		local function look(state, hidden)
			X.now = { state = state, hidden = hidden or false }
			X.W.auraChanged()
			Z.step(X.W, 0.3)
		end
		look("fine")
		look("fine")
		look("missing")
		look("unknown", true)
		look("missing")
		look("fine")
		check("procs: hook Changed: called with the entry, the state kept and the new one, once for each change, not for unknown, and the first is from nil", table.concat(X.changes, ",") == "nil>missing:zzk001,missing>fine:zzk001,fine>missing:zzk001,missing>fine:zzk001", table.concat(X.changes, ","))
		local R = world({ Changed = function() error("Changed failed", 0) end })
		R.now = { state = "fine", hidden = false }
		R.W.auraChanged()
		Z.step(R.W, 0.3)
		R.now = { state = "missing", hidden = false }
		R.W.auraChanged()
		Z.step(R.W, 0.3)
		check("procs: hook Changed: a call that raises is counted for the part and stops nothing", #R.W.errors == 0 and not has(R.W.status(), "stopped") and frameOf(R, "zzk001") ~= nil, R.W.line("Trackers"))
		-- Wanted.
		for _, case in ipairs({ { 0, "combat", 0 }, { 1, "combat", 1 }, { false, "combat", 0 }, { 7, "combat", 0 }, { 0, "always", 0 }, { 1, "always", 1 }, { false, "always", 1 } }) do
			local V = world({ Wanted = function() return case[1] ~= false and case[1] or nil end }, { options = { ["trackers.show"] = case[2] } })
			V.now = { state = "fine", hidden = false }
			V.W.auraChanged()
			Z.step(V.W, 0.3)
			check(("procs: hook Wanted: answer %s with Show %s gives alpha %s"):format(tostring(case[1]), case[2], tostring(case[3])), frameOf(V).alpha == case[3], frameOf(V).alpha)
		end
		local Args = { n = 0 }
		local A = world({ Wanted = function(entry, state, how) Args.entry, Args.state, Args.how = entry.id, state, how Args.n = Args.n + 1 end })
		A.now = { state = "fine", hidden = false }
		A.W.auraChanged()
		Z.step(A.W, 0.3)
		check("procs: hook Wanted: is given the entry, the state and how it is shown", Args.entry == "zzk001" and Args.state == "fine" and Args.how == "live" and Args.n > 0)
		-- Hide.
		local H = world({ Hide = function(_, reading) return reading.state == "fine" end })
		H.now = { state = "fine", hidden = false, expires = nil }
		H.W.auraChanged()
		Z.step(H.W, 0.3)
		local hp = Z.parts(H.W)
		check("procs: hook Hide: true draws nothing, the icon has alpha 0, no rim, and the sweep is cleared", hp.icon.alpha == 0 and Z.rim(hp) == 0 and hp.cooldown.cd.sweep == nil, tostring(hp.icon.alpha))
		H.now = { state = "missing", hidden = false }
		H.W.auraChanged()
		Z.step(H.W, 0.3)
		check("procs: hook Hide: false draws the look: the red missing icon", Z.parts(H.W).icon.alpha == 1 and Z.rim(Z.parts(H.W)) == 4)
		local B = world({ Hide = function() error("Hide failed", 0) end })
		B.now = { state = "fine", hidden = false }
		B.W.auraChanged()
		Z.step(B.W, 0.3)
		check("procs: hook Hide: one that raises draws the look", Z.parts(B.W).icon.alpha == 1 and #B.W.errors == 0)
		-- noLast.
		local L, P = world({ noLast = true }), world({})
		for _, K in ipairs({ L, P }) do
			K.now = { state = "fine", hidden = false, icon = Z.ICON }
			K.W.auraChanged()
			Z.step(K.W, 0.3)
			K.now = { state = "unknown", hidden = true }
			K.W.beginFight()
			Z.step(K.W, 0.3)
		end
		check("procs: hook noLast: an unknown reading with no game icon is a grey icon, not the last reading; a kind without it keeps the last", (Z.parts(L.W).icon.vertex[1] == 0.6 and Z.parts(P.W).icon.vertex[1] == 1),
			tostring(Z.parts(L.W).icon.vertex[1]) .. " " .. tostring(Z.parts(P.W).icon.vertex[1]))
		-- noDrop.
		local D, E = world({ noDrop = true }, { options = { ["trackers.sound"] = true } }), world({}, { options = { ["trackers.sound"] = true } })
		for _, K in ipairs({ D, E }) do
			K.now = { state = "fine", hidden = false }
			K.W.auraChanged()
			Z.step(K.W, 0.3)
			K.now = { state = "missing", hidden = false }
			K.W.auraChanged()
			Z.run(K.W, 1)
		end
		check("procs: hook noDrop: no sound for a drop of this kind, and one for a kind without it", #D.W.au.played == 0 and #E.W.au.played == 1, #D.W.au.played .. " " .. #E.W.au.played)
		-- last: the kinds that say last go after the others, in list order.
		local O = world({ last = true }, { list = { { id = "zzk001", kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } }, { id = "bff001", kind = "buff", name = "Demon Armor", names = { "Demon Armor" }, spells = { 706 } },
			{ id = "zzk002", kind = "zzkind", name = "Zz", spells = { 1235 }, names = { "Zz" } }, { id = "bff002", kind = "buff", name = "Fel Armor", names = { "Fel Armor" }, spells = { 707 } } } })
		local function at(id)
			return O.W.ns.TrackerFrame({ id = id }).points[1][4]
		end
		check("procs: hook last: the entries of the kind are after the buffs in the row, and in list order among themselves", at("bff001") < at("bff002") and at("bff002") < at("zzk001") and at("zzk001") < at("zzk002"), at("bff001") .. " " .. at("bff002") .. " " .. at("zzk001") .. " " .. at("zzk002"))
		check("procs: and the numbers of the list are not changed by it", O.W.slash("tracker list"):find("1. Zz", 1, true) == 1 and has(O.W.slash("tracker list"), "2. Demon Armor"), O.W.slash("tracker list"))
		-- Gone and World.
		local G = {}
		world({ Gone = function(id) G.gone[#G.gone + 1] = id end, World = function() G.world = G.world + 1 end }, nil, G)
		check("procs: hook World: called when the player enters the world", G.world >= 1, G.world)
		local before = G.world
		G.W.fire("SPELLS_CHANGED")
		check("procs: hook World: and when the spells change", G.world == before + 1, G.world .. " " .. before)
		G.W.slash("tracker remove 1")
		Z.step(G.W, 0.5)
		check("procs: hook Gone: called with the id of a tracker that is removed", table.concat(G.gone, ",") == "zzk001", table.concat(G.gone, ","))
		local Pg = {}
		world({ Gone = function(id) Pg.gone[#Pg.gone + 1] = id end }, nil, Pg)
		Pg.W.change("trackers.enabled", false)
		Pg.W.flush()
		Z.step(Pg.W, 0.5)
		check("procs: hook Gone: and when the page is switched off, for the trackers that were on", table.concat(Pg.gone, ",") == "zzk001", table.concat(Pg.gone, ","))
		local Sw = {}
		world({ Gone = function(id) Sw.gone[#Sw.gone + 1] = id end }, nil, Sw)
		Sw.W.slash("tracker set 1 on off")
		Z.step(Sw.W, 0.5)
		check("procs: hook Gone: and when the tracker is switched off alone", table.concat(Sw.gone, ",") == "zzk001", table.concat(Sw.gone, ","))
		-- Test.
		local T = {}
		world({ Test = function(entry, on) T.tests[#T.tests + 1] = (on and "on:" or "off:") .. entry.id return on and "Zz test." or nil end }, nil, T)
		local said = T.W.slash("tracker test")
		check("procs: hook Test: a kind with a Test is tested for 5 seconds, with its line printed, and not with the three looks", said == "Test: the icon and the sound of each proc. 5 seconds.\nZz test." and table.concat(T.tests, ",") == "on:zzk001", said)
		Z.step(T.W, 5.2)
		check("procs: hook Test: and ended after 5 seconds", table.concat(T.tests, ",") == "on:zzk001,off:zzk001", table.concat(T.tests, ","))
		-- Rim.
		local Rm = world({ Rim = function() return 0.2, 0.4, 0.6 end })
		Rm.now = { state = "fine", hidden = false }
		Rm.W.auraChanged()
		Z.step(Rm.W, 0.3)
		local rp = Z.parts(Rm.W)
		check("procs: hook Rim: the rim of a tracker that is up has the colour the kind gives", Z.rim(rp) == 4 and near(rp.rim[1].color[1], 0.2) and near(rp.rim[1].color[2], 0.4) and near(rp.rim[1].color[3], 0.6), tostring(rp.rim[1].color and rp.rim[1].color[1]))
		Rm.now = { state = "missing", hidden = false }
		Rm.W.auraChanged()
		Z.step(Rm.W, 0.3)
		rp = Z.parts(Rm.W)
		check("procs: hook Rim: and the red of a missing one when the kind's colour is not used", Z.rim(rp) == 4 and near(rp.rim[1].color[1], 0.851, 1e-3), tostring(rp.rim[1].color[1]))
		-- own.
		local Ow = world({ own = { sound = function(value) return value == 7 end } })
		Ow.W.slash("tracker set 1 sound off")
		check("procs: hook own: a kind's own test of a value stands in place of the one of the page: off is not 7", Z.list(Ow.W)[1].sound == nil, tostring(Z.list(Ow.W)[1].sound))
		Z.list(Ow.W)[1].sound = 7
		Z.list(Ow.W)
		check("procs: hook own: and 7 is kept", Z.list(Ow.W)[1].sound == 7)
		-- part.
		local Pt = world({ part = "zzpart", Read = function() error("Read failed", 0) end }, { list = { { id = "zzk001", kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } }, { id = "zzk002", kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } },
			{ id = "zzk003", kind = "zzkind", name = "Zz", spells = { 1234 }, names = { "Zz" } }, { id = "bff001", kind = "buff", name = "Shadow Trance", names = { "Shadow Trance" }, spells = { 17941 } } } })
		Pt.W.giveBuff(17941, { remaining = 600 })
		Pt.W.auraChanged()
		Z.step(Pt.W, 0.5)
		check("procs: hook part: a kind that raises on three trackers stops its part alone, named in the status, and the buff tracker goes on", has(Pt.W.status(), "zzpart stopped") and Z.parts(Pt.W, 4).icon.alpha == 1 and Z.parts(Pt.W, 4).icon.vertex[1] == 1, Pt.W.line("Trackers"))
	end

	-- 14. The row, the page, the files, a part that raises.
	do
		local BUFF = { id = "bff001", kind = "buff", name = "Demon Armor", names = { "Demon Armor" }, spells = { 706 } }
		local BUFF2 = { id = "bff002", kind = "buff", name = "Fel Armor", names = { "Fel Armor" }, spells = { 707 } }
		local function x(W, index)
			return Z.frame(W, index).points[1][4]
		end
		local W = Z.up({ list = { Z.entry(), BUFF, Z.entry({ id = "prc002", name = "Decimation", names = { "Decimation" }, spells = { 440873 } }), BUFF2 } })
		check("procs: layout: the buffs are first in the row, then the procs, each in list order", x(W, 2) < x(W, 4) and x(W, 4) < x(W, 1) and x(W, 1) < x(W, 3), x(W, 2) .. " " .. x(W, 4) .. " " .. x(W, 1) .. " " .. x(W, 3))
		check("procs: layout: the numbers of the list keep the saved order", has(W.slash("tracker list"), "1. Shadow Trance, proc alert") and has(W.slash("tracker list"), "2. Demon Armor, buff on you") and has(W.slash("tracker list"), "3. Decimation, proc alert"), W.slash("tracker list"))
		check("procs: layout: a proc that is down is clear and keeps its place, so the others do not move when it comes", (function()
			local before = x(W, 4)
			Z.give(W, 600)
			return x(W, 4) == before and Z.alpha(W, 1) == 1 and Z.alpha(W, 3) == 0
		end)())
		check("procs: layout: no violation", Z.ok(W), Z.why(W))
		-- In a fight nothing is made or changed on a frame that is protected, and a proc that is added waits.
		local F = Z.up({ list = { Z.entry() } })
		F.beginFight()
		Z.step(F, 0.3)
		F.slash("tracker add proc Decimation")
		F.slash("tracker proc time 1 20")
		F.slash("tracker proc colour 1 4d99e6")
		F.pickAt("trackers.removeProc", 3)
		Z.step(F, 0.3)
		check("procs: in a fight adding, removing and setting a proc raise nothing and call nothing protected", Z.ok(F), Z.why(F))
		F.endFight()
		Z.step(F, 0.5)
		check("procs: and when the fight is over the row has the one that is left", #Z.list(F) == 1 and Z.list(F)[1].time == 20 and Z.list(F)[1].colour == "ff4d99e6" and Z.frame(F, 1) ~= nil and Z.ok(F), #Z.list(F))
		-- The page off hides everything and ends the alert; on again, the alert starts again.
		local O = Z.up({ list = { Z.entry() } })
		local H = Z.hooks(O)
		Z.give(O, 600)
		check("procs: page: an alert is up with its art and glow", Z.alpha(O) == 1 and #H.art == 1 and #H.glow == 1 and #O.au.played == 1)
		O.change("trackers.enabled", false)
		Z.step(O, 0.5)
		check("procs: page: switched off, the row is gone and the art and the glow stop", #O.ns.TrackerRow() == 0 and #H.hide == 1 and #H.stop == 1 and has(O.status(), "Trackers: off"), #H.hide .. " " .. #H.stop)
		O.change("trackers.enabled", true)
		Z.step(O, 0.5)
		check("procs: page: switched on again, the proc that is up starts again with its art, glow and sound", Z.alpha(O) == 1 and #H.art == 2 and #H.glow == 2 and #O.au.played == 2 and Z.ok(O), Z.alpha(O) .. " " .. #H.art .. " " .. #H.glow .. " " .. #O.au.played .. " " .. Z.why(O))
		-- A tracker switched off alone, and removed.
		O.slash("tracker set 1 on off")
		Z.step(O, 0.5)
		check("procs: a proc switched off ends its alert", #H.hide == 2 and #H.stop == 2, #H.hide)
		O.slash("tracker set 1 on on")
		Z.step(O, 0.5)
		O.slash("tracker remove 1")
		Z.step(O, 0.5)
		check("procs: and one that is removed ends it too, with no frame left for it", #H.hide == 3 and #H.stop == 3 and #Z.list(O) == 0 and Z.ok(O), #H.hide)
		-- Procs.lua raising stops its part alone.
		local R = Z.up({ list = { Z.entry(), Z.entry({ id = "prc002", name = "Decimation", names = { "Decimation" }, spells = { 440873 } }), Z.entry({ id = "prc003", name = "Fel Domination", names = { "Fel Domination" }, spells = { 18708 } }), BUFF } })
		local real = R.ns.AuraReading
		R.ns.AuraReading = function(entry)
			if entry.kind == "proc" then
				error("AuraReading failed", 0)
			end
			return real(entry)
		end
		R.giveBuff(706, { remaining = 600, applications = 3 })
		R.auraChanged()
		Z.step(R, 0.5)
		check("procs: a proc part that raises on three trackers is stopped alone, named in the status", has(R.status(), "procs stopped") and not has(R.status(), "Trackers: stopped"), R.line("Trackers"))
		check("procs: and the buff tracker goes on: its icon is the buff, white", Z.parts(R, 4).icon.alpha == 1 and Z.parts(R, 4).icon.vertex[1] == 1 and Z.alpha(R, 4) == 1, tostring(Z.parts(R, 4).icon.alpha))
		-- The files.
		check("procs: the files compile, so each has at most 200 locals", loadfile(ADDON_DIR .. "/Procs.lua") ~= nil and loadfile(ADDON_DIR .. "/ProcData.lua") ~= nil and loadfile(ADDON_DIR .. "/Trackers.lua") ~= nil and loadfile(ADDON_DIR .. "/TrackerSlots.lua") ~= nil)
		check("procs: the TOC loads ProcData.lua and then Procs.lua right after TrackerMarks.lua", (function()
			local at = {}
			for i, name in ipairs(FILES) do
				at[name] = i
			end
			return at["ProcData.lua"] == at["TrackerMarks.lua"] + 1 and at["Procs.lua"] == at["ProcData.lua"] + 1
		end)())
		check("procs: the page has the defaults of its four rows", W.ns.Get("trackers.procColour") == "ffffd100" and W.ns.Get("trackers.procSound") == "spell" and W.read("trackers.addProc") == "Choose a proc" and W.read("trackers.removeProc") == "Choose a proc")
		check("procs: the rows are on the Trackers page after In fights, under Proc alerts, and the lists have their functions", (function()
			local rows, seen = {}, false
			for _, page in ipairs(W.ns.PAGES) do
				if page.key == "trackers" then
					for _, item in ipairs(page) do
						seen = seen or item.section == "Proc alerts"
						if seen and item.key then
							rows[#rows + 1] = item.key
						end
					end
				end
			end
			return table.concat(rows, ",") == "addProc,removeProc,procColour,procSound,art,artSize,artAlpha,artY,glow" and type(W.ns.ProcCandidates) == "function" and type(W.ns.ProcAdd) == "function" and type(W.ns.ProcPicked) == "function"
				and type(W.ns.ProcRemove) == "function"
		end)())
		-- ns.ProcColour.
		local C = Z.up({ list = { Z.entry({ colour = "ff4d99e6" }), Z.entry({ id = "prc002", colour = "zz" }) } })
		local r, g, b = C.ns.ProcColour(Z.list(C)[1])
		local pr, pg, pb = C.ns.ProcColour(Z.list(C)[2])
		check("procs: ns.ProcColour is the entry's colour, else the page's, else ffd100", near(r, 0.302, 1e-3) and near(g, 0.6, 1e-3) and near(b, 0.902, 1e-3) and pr == 1 and near(pg, 209 / 255) and pb == 0
			and select(1, C.ns.ProcColour(nil)) == 1)
		C.change("trackers.procColour", "ff336699")
		local qr, qg, qb = C.ns.ProcColour(Z.list(C)[2])
		check("procs: and the page's colour is used when the entry has none", near(qr, 0.2, 1e-3) and near(qg, 0.4, 1e-3) and near(qb, 0.6, 1e-3))
	end
end
-- >>> mp-procs (end)
-- >>> procart (begin)
-- Art beside the character (ProcArt.lua). The file is loaded here on its own, in a world of plain frames that record every call: the holder,
-- the pieces, their points, sizes, texture coordinates and colours, and the animation groups with their animations. The values are kept in
-- one table: the main function of this file has a limit on the locals alive at once.
do
	local PA = { SECRET = {}, L = 204.8, S = 102.4, ART = "Interface\\AddOns\\FlatUI\\Media\\ProcArc.tga" }
	PA.GEO = {
		Center = { "CENTER", "CENTER", 0, 0, PA.L, PA.L, { 0, 1, 0, 1 } },
		Left = { "RIGHT", "LEFT", 0, 0, PA.S, PA.L, { 0, 1, 0, 1 } },
		Right = { "LEFT", "RIGHT", 0, 0, PA.S, PA.L, { 1, 0, 0, 1 } },
		Top = { "BOTTOM", "TOP", 0, 0, PA.L, PA.S, { 0, 1, 0, 1 } },
		Bottom = { "TOP", "BOTTOM", 0, 0, PA.L, PA.S, { 0, 1, 1, 0 } },
		TopRight = { "BOTTOMLEFT", "TOPRIGHT", 0, 0, PA.S, PA.S, { 0, 1, 0, 1 } },
		TopLeft = { "BOTTOMRIGHT", "TOPLEFT", 0, 0, PA.S, PA.S, { 0, 1, 0, 1 } },
		LeftOutside = { "RIGHT", "LEFT", -PA.S, 0, PA.S, PA.L, { 0, 1, 0, 1 } },
		RightOutside = { "LEFT", "RIGHT", PA.S, 0, PA.S, PA.L, { 1, 0, 0, 1 } },
	}
	PA.ORDER = { "Center", "Left", "Right", "Top", "Bottom", "TopRight", "TopLeft", "LeftOutside", "RightOutside" }

	-- A world: the frames made, the settings, the combat state and the calls queued for when combat ends.
	function PA.up(opts)
		opts = opts or {}
		local W = { frames = {}, combat = opts.combat == true, queue = {}, protected = 0, uiparent = { name = "UIParent" },
			vals = { ["trackers.art"] = true, ["trackers.artSize"] = 100, ["trackers.artAlpha"] = 65, ["trackers.artY"] = 0 } }
		for key, value in pairs(opts.vals or {}) do
			W.vals[key] = value
		end
		local function group(owner)
			local grp = { owner = owner, anims = {}, scripts = {}, plays = 0, stops = 0, pauses = 0, playing = false }
			function grp.CreateAnimation(_, kind)
				local anim = { kind = kind }
				for _, name in ipairs({ "SetFromAlpha", "SetToAlpha", "SetDuration", "SetScaleFrom", "SetScaleTo", "SetSmoothing", "SetOrder" }) do
					anim[name] = function(_, x, y)
						anim[name:sub(4)] = x
						anim[name:sub(4) .. "Y"] = y
					end
				end
				grp.anims[#grp.anims + 1] = anim
				return anim
			end
			function grp.SetLooping(_, value) grp.looping = value end
			function grp.SetScript(_, name, fn) grp.scripts[name] = fn end
			function grp.Play()
				grp.playing = true
				grp.plays = grp.plays + 1
				if grp.scripts.OnPlay then
					grp.scripts.OnPlay(grp)
				end
			end
			function grp.Stop() grp.playing = false grp.stops = grp.stops + 1 end
			function grp.Pause() grp.playing = false grp.pauses = grp.pauses + 1 end
			function grp.finish()
				grp.playing = false
				if grp.scripts.OnFinished then
					grp.scripts.OnFinished(grp)
				end
			end
			return grp
		end
		local function frame(kind, parent, template)
			if template then
				W.protected = W.protected + 1
			end
			local f = { kind = kind, parent = parent, shown = false, alpha = 1, points = {}, groups = {} }
			function f.SetSize(_, w, h) f.w, f.h = w, h end
			function f.SetPoint(_, ...) f.points[#f.points + 1] = { ... } end
			function f.ClearAllPoints() f.points = {} end
			function f.Show() f.shown = true end
			function f.Hide() f.shown = false end
			function f.IsShown() return f.shown end
			function f.SetAlpha(_, alpha) f.alpha = alpha end
			function f.CreateAnimationGroup()
				local grp = group(f)
				f.groups[#f.groups + 1] = grp
				return grp
			end
			function f.CreateTexture()
				local t = { parent = f }
				function t.SetAllPoints() t.all = true end
				function t.SetTexCoord(_, l, r, top, bottom) t.coord = { l, r, top, bottom } end
				function t.SetTexture(_, file)
					if W.refuse then
						error("SetTexture refused", 0)
					end
					t.file = file
				end
				function t.SetVertexColor(_, r, g, b) t.colour = { r, g, b } end
				return t
			end
			W.frames[#W.frames + 1] = f
			return f
		end
		local env = setmetatable({
			CreateFrame = function(kind, _, parent, template)
				if parent == nil and template == nil then
					-- The login frame: kept apart from the frames that draw.
					local b = { events = {}, scripts = {} }
					function b.RegisterEvent(_, name) b.events[name] = true end
					function b.UnregisterEvent(_, name) b.events[name] = nil end
					function b.SetScript(_, name, fn) b.scripts[name] = fn end
					W.boot = b
					return b
				end
				return frame(kind, parent, template)
			end,
			UIParent = W.uiparent,
			InCombatLockdown = function() return W.combat end,
		}, { __index = _G })
		local ns = {
			Own = {}, IsSecret = function(value) return rawequal(value, PA.SECRET) end,
			Get = function(path) return W.vals[path] end,
			OutOfCombat = function(fn)
				if W.combat then
					W.queue[#W.queue + 1] = fn
				else
					fn()
				end
			end,
		}
		if opts.colour then
			ns.ProcColour = function() return opts.colour[1], opts.colour[2], opts.colour[3] end
		end
		loadWithEnv(ADDON_DIR .. "/ProcArt.lua", env)("FlatUI", ns)
		W.ns = ns
		function W.endCombat()
			W.combat = false
			local queue = W.queue
			W.queue = {}
			for _, fn in ipairs(queue) do
				fn()
			end
		end
		-- The holder, and the pieces shown with a file.
		function W.holder()
			for _, f in ipairs(W.frames) do
				if f.parent == W.uiparent then
					return f
				end
			end
		end
		function W.live(file)
			local list = {}
			for _, f in ipairs(W.frames) do
				if f.parent == W.holder() and f.shown and f.tex and f.tex.file == file then
					list[#list + 1] = f
				end
			end
			return list
		end
		function W.shown()
			local n = 0
			for _, f in ipairs(W.frames) do
				if f.parent == W.holder() and f.shown then
					n = n + 1
				end
			end
			return n
		end
		function W.playing()
			local n = 0
			for _, f in ipairs(W.frames) do
				for _, grp in ipairs(f.groups) do
					if grp.playing then
						n = n + 1
					end
				end
			end
			return n
		end
		-- The piece of a location among the shown pieces of a file, found by its point on the holder and, for the outside pieces, its offset.
		function W.piece(file, name)
			for _, f in ipairs(W.live(file)) do
				local p = f.points[1]
				if p and p[1] == PA.GEO[name][1] and p[3] == PA.GEO[name][2] then
					return f
				end
			end
		end
		return W
	end

	-- Whether a piece is where the game puts the location, at a size factor, with an extra offset.
	function PA.is(W, piece, name, k, dx, dy)
		local e, p = PA.GEO[name], piece and piece.points[1]
		return p ~= nil and #piece.points == 1 and p[1] == e[1] and p[2] == W.holder() and p[3] == e[2] and near(p[4], e[3] + (dx or 0), 1e-6) and near(p[5], e[4] + (dy or 0), 1e-6)
			and near(piece.w, e[5] * k, 1e-6) and near(piece.h, e[6] * k, 1e-6)
			and piece.tex.coord[1] == e[7][1] and piece.tex.coord[2] == e[7][2] and piece.tex.coord[3] == e[7][3] and piece.tex.coord[4] == e[7][4]
	end
	function PA.at(piece)
		if not piece then
			return "no piece"
		end
		local p = piece.points[1]
		return string.format("%s>%s %g,%g %gx%g", p[1], p[3], p[4], p[5], piece.w, piece.h)
	end
	function PA.entry(id) return { id = id, name = "Proc " .. id, lights = { 1 } } end

	-- Nothing is made, drawn or called while no proc is up.
	do
		local W = PA.up()
		check("procart: loading the file makes no frame", #W.frames == 0 and type(W.ns.ProcArtShow) == "function" and type(W.ns.ProcArtHide) == "function" and type(W.ns.ProcArtChanged) == "function" and type(W.ns.ProcArtLine) == "function")
		check("procart: ending a proc that is not up does nothing", W.ns.ProcArtHide(PA.entry("a")) == false and W.ns.ProcArtChanged() == nil and W.ns.ProcArtReset() == nil and #W.frames == 0)
		check("procart: no proc up says so in the check", W.ns.ProcArtLine(PA.entry("a")) == "Art: not drawn yet", W.ns.ProcArtLine(PA.entry("a")))
		check("procart: a call with no table makes no frame", W.ns.ProcArtShow(nil, {}) == false and #W.frames == 0)
	end

	-- The geometry of every location at size 100, with the game's numbers.
	for _, name in ipairs(PA.ORDER) do
		local W = PA.up()
		check("procart: " .. name .. " is made", W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = name, scale = 1 }) == true)
		local live = W.live(449492)
		check("procart: " .. name .. " at size 100 is the game's piece", #live == 1 and PA.is(W, live[1], name, 1), PA.at(live[1]))
	end
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Right", scale = 1 })
		local piece = W.live(449492)[1]
		check("procart: the right piece is the left one mirrored across", piece.tex.coord[1] == 1 and piece.tex.coord[2] == 0 and piece.tex.coord[3] == 0 and piece.tex.coord[4] == 1)
		W.ns.ProcArtShow(PA.entry("b"), { file = 449489, location = "Bottom", scale = 1 })
		local bottom = W.live(449489)[1]
		check("procart: the bottom piece is the top one turned over", bottom.tex.coord[1] == 0 and bottom.tex.coord[2] == 1 and bottom.tex.coord[3] == 1 and bottom.tex.coord[4] == 0)
		check("procart: the holder is the game's square at the middle of the screen", (function()
			local h = W.holder()
			local p = h.points[1]
			return near(h.w, 204.8) and near(h.h, 204.8) and p[1] == "CENTER" and p[2] == W.uiparent and p[3] == "CENTER" and p[4] == 0 and p[5] == 0 and h.shown
		end)())
		check("procart: the pieces hang on the holder and the texture fills the piece", piece.parent == W.holder() and piece.tex.all == true and piece.tex.file == 449492)
	end

	-- Two pieces: the location that stands for two.
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1 })
		check("procart: Left and Right make the left and the right piece", #W.live(449492) == 2 and PA.is(W, W.piece(449492, "Left"), "Left", 1) and PA.is(W, W.piece(449492, "Right"), "Right", 1))
		W.ns.ProcArtShow(PA.entry("b"), { file = 449493, location = "TopBottom", scale = 1 })
		check("procart: Top and Bottom make the top and the bottom piece", #W.live(449493) == 2 and PA.is(W, W.piece(449493, "Top"), "Top", 1) and PA.is(W, W.piece(449493, "Bottom"), "Bottom", 1))
		W.ns.ProcArtShow(PA.entry("c"), { file = 449494, location = "LeftRightOutside", scale = 1 })
		check("procart: Left and Right outside make the two outside pieces, a short side out", #W.live(449494) == 2 and PA.is(W, W.piece(449494, "LeftOutside"), "LeftOutside", 1) and PA.is(W, W.piece(449494, "RightOutside"), "RightOutside", 1))
		local N = PA.up()
		N.ns.ProcArtShow(PA.entry("d"), { file = 449490, location = 9, scale = 1 })
		check("procart: a location given as its number is the same location", #N.live(449490) == 2 and PA.is(N, N.piece(449490, "Right"), "Right", 1), #N.live(449490))
	end

	-- Size: the size row and the scale of the proc multiply the piece, the outside offset is the game's.
	for _, name in ipairs(PA.ORDER) do
		local W = PA.up({ vals = { ["trackers.artSize"] = 150 } })
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = name, scale = 1.2 })
		local live = W.live(449492)
		check("procart: " .. name .. " at size 150 and scale 1.2 is 1.8 times the piece", #live == 1 and PA.is(W, live[1], name, 1.8), PA.at(live[1]))
	end
	do
		local W = PA.up({ vals = { ["trackers.artSize"] = 50 } })
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		check("procart: size 50 halves the piece", PA.is(W, W.live(449492)[1], "Left", 0.5))
		local V = PA.up()
		V.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 0 })
		check("procart: a scale of 0 is 1", PA.is(V, V.live(449492)[1], "Left", 1))
		V.ns.ProcArtShow(PA.entry("b"), { file = 449493, location = "Top", scale = PA.SECRET })
		check("procart: a withheld scale is 1", PA.is(V, V.live(449493)[1], "Top", 1))
		V.ns.ProcArtShow(PA.entry("c"), { file = 449494, location = "Bottom", scale = 99 })
		check("procart: a scale is held at 5", PA.is(V, V.live(449494)[1], "Bottom", 5))
	end

	-- The holder's height and opacity.
	do
		local W = PA.up({ vals = { ["trackers.artY"] = 40, ["trackers.artAlpha"] = 50 } })
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		local h = W.holder()
		check("procart: Art height moves the holder up and Art opacity clears it", h.points[1][5] == 40 and near(h.alpha, 0.5) and #h.points == 1, h.points[1][5])
		W.vals["trackers.artY"], W.vals["trackers.artAlpha"], W.vals["trackers.artSize"] = -25, 80, 200
		W.ns.ProcArtChanged()
		check("procart: a changed row moves the holder and sizes the pieces at once", h.points[1][5] == -25 and near(h.alpha, 0.8) and PA.is(W, W.live(449492)[1], "Left", 2), PA.at(W.live(449492)[1]))
		local D = PA.up()
		D.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		check("procart: the opacity is 65 percent and the height 0 until a row says otherwise", near(D.holder().alpha, 0.65) and D.holder().points[1][5] == 0)
		local E = PA.up({ vals = { ["trackers.artAlpha"] = PA.SECRET, ["trackers.artY"] = "x" } })
		E.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		check("procart: a value that is not a number is the default", near(E.holder().alpha, 0.65) and E.holder().points[1][5] == 0)
	end

	-- The animations the game plays.
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		local piece = W.live(449492)[1]
		local gin, gout, pulse = piece.groups[1], piece.groups[2], piece.groups[3]
		check("procart: it fades in over 0.2 s from clear to full", gin.anims[1].kind == "Alpha" and gin.anims[1].FromAlpha == 0 and gin.anims[1].ToAlpha == 1 and gin.anims[1].Duration == 0.2 and gin.playing and piece.alpha == 0)
		check("procart: it fades out over 0.1 s from full to clear", gout.anims[1].kind == "Alpha" and gout.anims[1].FromAlpha == 1 and gout.anims[1].ToAlpha == 0 and gout.anims[1].Duration == 0.1 and not gout.playing)
		check("procart: the pulse loops, 1.08 then 0.9259, half a second each, eased at both ends", pulse.looping == "REPEAT" and #pulse.anims == 2
			and pulse.anims[1].kind == "Scale" and pulse.anims[1].ScaleFrom == 1 and pulse.anims[1].ScaleTo == 1.08 and pulse.anims[1].ScaleToY == 1.08 and pulse.anims[1].Duration == 0.5 and pulse.anims[1].Smoothing == "IN_OUT" and pulse.anims[1].Order == 1
			and pulse.anims[2].ScaleTo == 0.9259 and pulse.anims[2].ScaleToY == 0.9259 and pulse.anims[2].Duration == 0.5 and pulse.anims[2].Smoothing == "IN_OUT" and pulse.anims[2].Order == 2)
		check("procart: the pulse waits for the fade in", not pulse.playing)
		gin.finish()
		check("procart: when the fade in ends the piece is full and the pulse runs", piece.alpha == 1 and pulse.playing)
		check("procart: it makes no animation beyond the three", #piece.groups == 3 and W.playing() == 1)
		W.ns.ProcArtHide(PA.entry("a"))
		check("procart: when the proc ends the pulse stops and the fade out runs", not pulse.playing and pulse.pauses == 1 and gout.playing and piece.shown)
		gout.finish()
		check("procart: when the fade out ends the piece is hidden and every animation is stopped", not piece.shown and not gin.playing and not gout.playing and not pulse.playing and #W.live(449492) == 0 and W.shown() == 0)
		W.ns.ProcArtShow(PA.entry("b"), { file = 449493, location = "Left", scale = 1 })
		local again = W.live(449493)[1]
		check("procart: the next proc takes the piece again from a stopped state", again == piece and gin.playing and not gout.playing and not pulse.playing and piece.alpha == 0 and #W.frames == 1 + 12)
		W.ns.ProcArtHide(PA.entry("b"))
		W.ns.ProcArtShow(PA.entry("c"), { file = 449494, location = "Left", scale = 1 })
		check("procart: a proc that comes up while another fades out has a piece of its own", #W.live(449494) == 1 and W.live(449494)[1] ~= piece)
		piece.groups[2].finish()
		check("procart: the one that finished fading is hidden and the other stays", W.shown() == 1 and #W.live(449494) == 1)
	end

	-- Up to three at once, and their places.
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		W.ns.ProcArtShow(PA.entry("b"), { file = 1002, location = "Left", scale = 1 })
		W.ns.ProcArtShow(PA.entry("c"), { file = 1003, location = "Left", scale = 1 })
		check("procart: the first proc has the game's place", PA.is(W, W.live(1001)[1], "Left", 1), PA.at(W.live(1001)[1]))
		check("procart: the second moves out by a piece width", PA.is(W, W.live(1002)[1], "Left", 1, -PA.S, 0), PA.at(W.live(1002)[1]))
		check("procart: the third goes above", PA.is(W, W.live(1003)[1], "Left", 1, 0, PA.L), PA.at(W.live(1003)[1]))
		check("procart: a fourth is not drawn", W.ns.ProcArtShow(PA.entry("d"), { file = 1004, location = "Left", scale = 1 }) == false and #W.live(1004) == 0 and W.shown() == 3)
		W.ns.ProcArtHide(PA.entry("a"))
		W.live(1001)[1].groups[2].finish()
		check("procart: when the first ends the others keep their places", PA.is(W, W.live(1002)[1], "Left", 1, -PA.S, 0) and PA.is(W, W.live(1003)[1], "Left", 1, 0, PA.L))
		W.ns.ProcArtShow(PA.entry("e"), { file = 1005, location = "Left", scale = 1 })
		check("procart: the next one takes the place that is free", PA.is(W, W.live(1005)[1], "Left", 1), PA.at(W.live(1005)[1]))
		W.ns.ProcArtShow(PA.entry("b"), { file = 1006, location = "Left", scale = 1 })
		check("procart: a proc that is up already keeps its place when its art changes", PA.is(W, W.live(1006)[1], "Left", 1, -PA.S, 0) and #W.live(1002) == 0 and W.shown() == 3, W.shown())
	end
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Right", scale = 1 })
		W.ns.ProcArtShow(PA.entry("b"), { file = 1002, location = "Right", scale = 1 })
		check("procart: a second proc on the right moves out to the right", PA.is(W, W.live(1002)[1], "Right", 1, PA.S, 0), PA.at(W.live(1002)[1]))
		local T = PA.up()
		T.ns.ProcArtShow(PA.entry("c"), { file = 1003, location = "Top", scale = 1 })
		T.ns.ProcArtShow(PA.entry("d"), { file = 1004, location = "Top", scale = 1 })
		check("procart: the first proc on top has the game's place and the second goes up a piece height", PA.is(T, T.live(1003)[1], "Top", 1) and PA.is(T, T.live(1004)[1], "Top", 1, 0, PA.S), PA.at(T.live(1004)[1]))
		T.ns.ProcArtShow(PA.entry("e"), { file = 1005, location = "Top", scale = 1 })
		check("procart: the third on top goes up two piece heights", PA.is(T, T.live(1005)[1], "Top", 1, 0, PA.S * 2), PA.at(T.live(1005)[1]))
	end
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		W.ns.ProcArtShow(PA.entry("b"), { file = 1002, location = "Top", scale = 1 })
		W.ns.ProcArtShow(PA.entry("c"), { file = 1003, location = "LeftRight", scale = 1 })
		check("procart: procs with pieces in different places each have the game's place", PA.is(W, W.live(1001)[1], "Left", 1) and PA.is(W, W.live(1002)[1], "Top", 1), PA.at(W.live(1001)[1]))
		check("procart: a proc that shares a place with one and not the other moves out", PA.is(W, W.piece(1003, "Left"), "Left", 1, -PA.S, 0) and PA.is(W, W.piece(1003, "Right"), "Right", 1, PA.S, 0))
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		check("procart: a proc shown again does not draw a second set", #W.live(1001) == 1 and W.shown() == 4)
	end
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "LeftRight", scale = 1 })
		W.ns.ProcArtShow({ id = "a" }, { file = 1001, location = "Top", scale = 1 })
		check("procart: an entry is known by its id, and a changed location takes the old pieces away", #W.live(1001) == 1 and PA.is(W, W.live(1001)[1], "Top", 1) and W.shown() == 1, W.shown())
		check("procart: ending it by the id of another table ends it", W.ns.ProcArtHide({ id = "a" }) == true and W.ns.ProcArtHide({ id = "a" }) == false)
	end

	-- Off, and everything back.
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "LeftRight", scale = 1 })
		W.ns.ProcArtShow(PA.entry("b"), { file = 1002, location = "Top", scale = 1 })
		W.live(1001)[1].groups[1].finish()
		W.vals["trackers.art"] = false
		W.ns.ProcArtChanged()
		check("procart: with the art off every piece is hidden and no animation runs", W.shown() == 0 and W.playing() == 0, W.shown())
		check("procart: with the art off no proc is up and a proc that comes up is not drawn", W.ns.ProcArtHide(PA.entry("a")) == false and W.ns.ProcArtShow(PA.entry("c"), { file = 1003, location = "Left", scale = 1 }) == false and W.shown() == 0)
		check("procart: with the art off the check says off", W.ns.ProcArtLine(PA.entry("a")) == "Art: off")
		W.vals["trackers.art"] = true
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		check("procart: with the art on again the places start from the first", PA.is(W, W.live(1001)[1], "Left", 1) and W.shown() == 1)
		W.ns.ProcArtReset()
		check("procart: a reset puts every piece back with its animations stopped", W.shown() == 0 and W.playing() == 0 and W.ns.ProcArtHide(PA.entry("a")) == false)
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		W.ns.ProcArtHide(PA.entry("a"))
		W.ns.ProcArtReset()
		check("procart: a reset also takes in the pieces that are fading out", W.shown() == 0 and W.playing() == 0)
		W.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 })
		W.ns.ProcArtHide(PA.entry("a"), true)
		check("procart: ending a proc at once hides it with no fade", W.shown() == 0 and W.playing() == 0 and W.live(1001)[1] == nil)
		local F = PA.up({ vals = { ["trackers.art"] = false } })
		check("procart: with the art off from the start no frame is ever made", F.ns.ProcArtShow(PA.entry("a"), { file = 1001, location = "Left", scale = 1 }) == false and #F.frames == 0)
	end

	-- A proc with no art of its own, and what the game says.
	do
		local W = PA.up()
		W.ns.ProcArtShow(PA.entry("a"), nil)
		check("procart: a proc with no art draws the arc on the left and the right", #W.live(PA.ART) == 2 and PA.is(W, W.piece(PA.ART, "Left"), "Left", 1) and PA.is(W, W.piece(PA.ART, "Right"), "Right", 1))
		W.ns.ProcArtShow(PA.entry("b"), { location = "Top", scale = 1 })
		check("procart: a location with no file is the arc on the left and the right too", #W.live(PA.ART) == 4 and W.piece(PA.ART, "Top") == nil)
		local V = PA.up()
		V.ns.ProcArtShow(PA.entry("a"), { file = PA.SECRET, location = PA.SECRET, scale = PA.SECRET, r = PA.SECRET, g = 0, b = 0 })
		check("procart: a withheld payload is the arc at size 1 in gold", #V.live(PA.ART) == 2 and PA.is(V, V.piece(PA.ART, "Left"), "Left", 1) and V.live(PA.ART)[1].tex.colour[1] == 1)
		local X = PA.up()
		X.ns.ProcArtShow(PA.entry("a"), { file = 449492, scale = 1 })
		check("procart: a file with no location is drawn on the left and the right", #X.live(449492) == 2 and PA.is(X, X.piece(449492, "Right"), "Right", 1))
		local G = PA.up()
		G.ns.ProcArtShow(PA.entry("a"), { file = 450915, location = "Top", scale = 1, r = 0.3, g = 0.6, b = 0.9 })
		check("procart: a proc the game signals draws the art of the payload", #G.live(450915) == 1 and PA.is(G, G.live(450915)[1], "Top", 1))
		check("procart: the line of that proc names the file and the place", G.ns.ProcArtLine(PA.entry("a")):find("^Art: file 450915, Top, drew yes") ~= nil, G.ns.ProcArtLine(PA.entry("a")))
		check("procart: the line of the arc says arc", W.ns.ProcArtLine(PA.entry("a")):find("^Art: file arc, Left and Right, drew yes") ~= nil, W.ns.ProcArtLine(PA.entry("a")))
		local N = PA.up()
		N.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1 })
		check("procart: the line says Left and Right and where to look for a green block", N.ns.ProcArtLine(PA.entry("a")) == "Art: file 449492, Left and Right, drew yes. A file that does not draw is a green block: look at /flatui tracker test.", N.ns.ProcArtLine(PA.entry("a")))
		local R = PA.up()
		R.refuse = true
		R.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1 })
		check("procart: a file the game refuses says drew no and breaks nothing", R.ns.ProcArtLine(PA.entry("a")):find("^Art: file 449492, Left and Right, drew no") ~= nil, R.ns.ProcArtLine(PA.entry("a")))
	end

	-- The colour.
	do
		local W = PA.up({ colour = { 0.2, 0.4, 0.6 } })
		W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1, r = 1, g = 0, b = 0 })
		local c = W.live(449492)[1].tex.colour
		check("procart: the colour of the entry tints both pieces", near(c[1], 0.2) and near(c[2], 0.4) and near(c[3], 0.6) and W.live(449492)[2].tex.colour[2] == c[2])
		local V = PA.up()
		V.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1, r = 1, g = 0, b = 0.5 })
		c = V.live(449492)[1].tex.colour
		check("procart: with no colour of the entry the colour of the payload tints the art", c[1] == 1 and c[2] == 0 and c[3] == 0.5)
		V.ns.ProcArtShow(PA.entry("b"), { file = 449493, location = "Left", scale = 1 })
		c = V.live(449493)[1].tex.colour
		check("procart: with neither it is gold", c[1] == 1 and near(c[2], 209 / 255) and c[3] == 0)
		V.ns.ProcArtShow(PA.entry("c"), { file = 449494, location = "Top", scale = 1, r = 3, g = -1, b = 0.5 })
		c = V.live(449494)[1].tex.colour
		check("procart: a colour outside 0 to 1 is held to it", c[1] == 1 and c[2] == 0 and c[3] == 0.5)
	end

	-- Combat.
	do
		local B = PA.up()
		check("procart: login is the event that makes the holder", B.boot and B.boot.events.PLAYER_LOGIN == true and #B.frames == 0)
		B.boot.scripts.OnEvent(B.boot)
		check("procart: at login out of combat the holder and its pieces are made and the event is dropped", B.holder() ~= nil and #B.frames == 1 + 12 and next(B.boot.events) == nil)
		B.combat = true
		check("procart: a proc in combat after login draws at once with nothing queued", B.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1 }) == true and #B.live(449492) == 2 and #B.queue == 0)
		local L = PA.up({ combat = true })
		L.boot.scripts.OnEvent(L.boot)
		check("procart: a login in combat makes nothing and queues the holder", #L.frames == 0 and #L.queue == 1)
		L.endCombat()
		check("procart: when combat ends after that login the holder is made", L.holder() ~= nil and #L.frames == 1 + 12)
		local W = PA.up({ combat = true })
		check("procart: a proc in combat before anything is made is accepted", W.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "LeftRight", scale = 1 }) == true)
		check("procart: nothing is made in combat", #W.frames == 0 and #W.queue == 1)
		W.endCombat()
		check("procart: when combat ends the holder and the pieces are made and drawn", #W.live(449492) == 2 and W.holder() ~= nil and PA.is(W, W.piece(449492, "Left"), "Left", 1))
		W.combat = true
		W.ns.ProcArtShow(PA.entry("b"), { file = 449493, location = "Top", scale = 1 })
		W.ns.ProcArtHide(PA.entry("a"))
		W.vals["trackers.artY"] = 30
		W.ns.ProcArtChanged()
		check("procart: in combat a proc comes up and ends and a row changes, all on the frames already made", #W.live(449493) == 1 and W.holder().points[1][5] == 30 and W.protected == 0 and #W.frames == 1 + 12)
		W.ns.ProcArtShow(PA.entry("c"), { file = 449494, location = "Left", scale = 1 })
		W.ns.ProcArtHide(PA.entry("c"))
		check("procart: no frame is made with a template, so no protected call is made", W.protected == 0)
		local Q = PA.up({ combat = true })
		Q.ns.ProcArtShow(PA.entry("a"), { file = 449492, location = "Left", scale = 1 })
		Q.ns.ProcArtHide(PA.entry("a"))
		Q.endCombat()
		check("procart: a proc that ended in combat before it was drawn is not drawn", #Q.live(449492) == 0 and Q.shown() == 0)
	end

	-- The files.
	do
		check("procart: ProcArt.lua is loaded after Procs.lua", (function()
			local at = {}
			for i, name in ipairs(FILES) do
				at[name] = i
			end
			return at["ProcArt.lua"] ~= nil and at["Procs.lua"] ~= nil and at["ProcArt.lua"] == at["Procs.lua"] + 1
		end)())
		check("procart: ProcArt.lua compiles, so it has at most 200 locals", loadfile(ADDON_DIR .. "/ProcArt.lua") ~= nil)
		local f = assert(io.open(ADDON_DIR .. "/Media/ProcArc.tga", "rb"))
		local data = f:read("*a")
		f:close()
		check("procart: ProcArc.tga is a 32-bit 64 by 128 picture", #data == 18 + 64 * 128 * 4 and data:byte(3) == 2 and data:byte(13) + data:byte(14) * 256 == 64 and data:byte(15) + data:byte(16) * 256 == 128 and data:byte(17) == 32, #data)
	end
end
-- >>> procart (end)
-- >>> mp-proc-glow (begin)
-- Glow on the action button while a proc is up (procglow:): the border through ns.SetButtonMark, the game's flipbook on a frame of the addon's own.
do
	local G = { ATLAS = "UI-HUD-ActionBar-Proc-Loop-Flipbook", GOLD = { 1, 0.82, 0 }, ALL = { "ActionButton1", "ActionButton2", "MultiBarBottomLeftButton1" } }
	G.held = {
		ActionButton1 = { "spell", 905 }, ActionButton2 = { "spell", 325 }, ActionButton5 = { "spell", 974 }, MultiBarBottomLeftButton1 = { "macro", 324, "spell" },
	}
	G.one = { id = "pg0001", name = "Lightning Shield proc", lights = { 905 } }
	G.two = { id = "pg0002", name = "Earth Shield proc", lights = { 974 } }
	G.three = { id = "pg0003", name = "Lightning Shield again", lights = { 325 } }
	G.none = { id = "pg0004", name = "Shadow Bolt", lights = { 5 } }
	function G.number(name)
		local group, index = name:match("^(%a+)(%d+)$")
		return (group == "ActionButton" and 0 or 60) + tonumber(index)
	end
	-- o.atlas: false (no entry for the flipbook) or "error" (the question fails); o.options the saved settings; o.alerts the game's alert manager.
	function G.world(o)
		o = o or {}
		local opts = { trackers = true }
		if o.options then
			opts.saved = { options = o.options }
		end
		local W = newWorld(opts)
		W.ns.TrackerSlots = nil
		W.addLine({ name = "General" })
		W.addSpell(324, { name = "Lightning Shield", icon = 136051, lowRank = true, base = 0 })
		W.addSpell(325, { name = "Lightning Shield", icon = 136051, lowRank = true, base = 0 })
		W.addSpell(905, { name = "Lightning Shield", icon = 136051, base = 0 })
		W.addSpell(974, { name = "Earth Shield", icon = 136089, base = 0 })
		W.addSpell(5, { name = "Fireball", icon = 135812, base = 0 })
		W.gl = { info = {} }
		for name, held in pairs(G.held) do
			W.gl.info[G.number(name)] = held
			W.buttons[name].inner.action = G.number(name)
		end
		W.env.GetActionInfo = function(action)
			local held = W.gl.info[action]
			if held then
				return held[1], held[2], held[3]
			end
		end
		W.env.C_Texture = { GetAtlasInfo = function(name)
			if o.atlas == "error" then
				error("GetAtlasInfo failed", 0)
			end
			if o.atlas ~= false and name == G.ATLAS then
				return { width = 150, height = 150 }
			end
		end }
		if o.alerts then
			local manager = { activeAlerts = {} }
			function manager:ShowAlert(button) self.activeAlerts[button] = 1 end
			function manager:HideAlert(button) self.activeAlerts[button] = nil end
			function manager:HasAlert(button) local has = self.activeAlerts[button] ~= nil return has, has and 0 or nil end
			W.env.ActionButtonSpellAlertManager = manager
			W.gl.manager = manager
		end
		W.login()
		W.flush()
		W.advance(0.3)
		W.advance(0)
		return W
	end
	function G.step(W)
		W.advance(0.1)
		W.advance(0)
	end
	function G.icon(W, name)
		return W.buttons[name].parts.icon
	end
	function G.border(W, name, c)
		local o = W.look(G.icon(W, name))
		return o ~= nil and near(o.r, c[1], 1e-3) and near(o.g, c[2], 1e-3) and near(o.b, c[3], 1e-3) and near(o.thick, 2)
	end
	-- The colour of the border alone: in a fight the thickness waits for the end of it.
	function G.tint(W, name, c)
		local o = W.look(G.icon(W, name))
		return o ~= nil and near(o.r, c[1], 1e-3) and near(o.g, c[2], 1e-3) and near(o.b, c[3], 1e-3)
	end
	function G.plain(W, name)
		return (ringOf(W, G.icon(W, name), 1, 0, 0, 0))
	end
	-- The glow frame the addon made for a button: the frame of the addon's own that is anchored to it in the centre, with its texture.
	function G.glow(W, name)
		local button, frame, n = W.buttons[name].button, nil, 0
		for _, candidate in ipairs(W.addonFrames) do
			local raw = W.rawOf[candidate]
			local point = raw and raw.points and raw.points[1]
			if point ~= nil and point[1] == "CENTER" and W.rawOf[point[2]] == W.buttons[name].inner then
				frame, n = raw, n + 1
			end
		end
		G.count = n
		if frame == nil then
			return nil
		end
		local made = { frame = frame, button = button }
		for _, region in ipairs(frame.regions) do
			made.texture = region
		end
		made.playing = frame.onUpdate ~= nil
		made.sets = frame.updateSets or 0
		return made
	end
	-- Plays and stops of a glow, counted from the OnUpdate sets of its frame: a play sets the script, a stop clears it.
	function G.plays(made)
		return ((made.frame.updateSets or 0) + (made.frame.onUpdate ~= nil and 1 or 0)) / 2
	end
	function G.stops(made)
		return ((made.frame.updateSets or 0) - (made.frame.onUpdate ~= nil and 1 or 0)) / 2
	end
	function G.frames(W)
		return #W.addonFrames
	end
	function G.playing(W, name)
		local made = G.glow(W, name)
		return made ~= nil and made.playing and made.frame.alpha == 1
	end
	function G.idle(W, name)
		local made = G.glow(W, name)
		return made ~= nil and made.frame.alpha == 0 and not made.playing
	end
	function G.trouble(W)
		return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|")
	end
	function G.quiet(W)
		return #W.violations == 0 and #W.errors == 0 and #W.out == 0
	end
	-- Every one of the three buttons that hold Lightning Shield passes the test.
	function G.all(W, test, c)
		for _, name in ipairs(G.ALL) do
			if not test(W, name, c) then
				return false
			end
		end
		return true
	end

	-- The row.
	do
		local W = G.world()
		local row, section
		for _, page in ipairs(W.ns.PAGES) do
			local last
			for _, item in ipairs(page) do
				if item.section then
					last = item.section
				end
				if item.path == "trackers.glow" then
					row, section = item, last
				end
			end
		end
		check("procglow: the Trackers page has Glow on the action button, a switch that starts on, in Proc alerts", row ~= nil and row.kind == "bool" and row.default == true
			and row.label == "Glow on the action button" and section == "Proc alerts" and W.ns.Get("trackers.glow") == true)
		check("procglow: the row has a tip that names Restyle action bars", row ~= nil and type(row.tip) == "string" and row.tip:find("Restyle action bars", 1, true) ~= nil)
		check("procglow: the row calls ProcGlowChanged, which exists", row ~= nil and row.changed == "ProcGlowChanged" and type(W.ns.ProcGlowChanged) == "function")
		check("procglow: it is no module, and the file loads after ProcArt.lua", #W.ns.MODULE_ORDER == 22 and (function()
			local at = {}
			for i, file in ipairs(FILES) do
				at[file] = i
			end
			return at["ProcGlow.lua"] == at["ProcArt.lua"] + 1 and at["ProcGlow.lua"] > at["TrackerMarks.lua"] and at["ProcGlow.lua"] > at["ActionBars.lua"]
		end)())
		check("procglow: ProcGlow.lua compiles", loadfile(ADDON_DIR .. "/ProcGlow.lua") ~= nil)
		clean(W, "procglow")
	end

	-- A proc comes up and goes.
	do
		local W = G.world()
		local ns = W.ns
		local before = G.frames(W)
		ns.ProcGlowStart(G.one)
		check("procglow: every button that holds the spell, every rank and the macro, has the border, and no other", G.all(W, G.border, G.GOLD) and G.plain(W, "ActionButton5"))
		check("procglow: each of the three has a frame of the addon's own, the others none", G.frames(W) == before + 3 and G.glow(W, "ActionButton5") == nil and G.glow(W, "ActionButton1") ~= nil)
		local made = G.glow(W, "ActionButton1")
		check("procglow: the glow hangs from the button's parent, not the button, anchored to the button, 1.4 times its size, in the centre", made ~= nil and made.frame.parent ~= W.buttons.ActionButton1.button
			and W.rawOf[made.frame.points[1][2]] == W.buttons.ActionButton1.inner and made.frame.level == W.buttons.ActionButton1.inner.level + 10
			and near(made.frame.width, W.buttons.ActionButton1.inner.width * 1.4) and near(made.frame.height, W.buttons.ActionButton1.inner.height * 1.4)
			and made.frame.points[1] ~= nil and made.frame.points[1][1] == "CENTER", made and (tostring(made.frame.width) .. " " .. tostring(W.buttons.ActionButton1.inner.width)))
		check("procglow: it has one texture, the game's flipbook atlas", made ~= nil and made.texture ~= nil and made.texture.atlas == G.ATLAS and #made.frame.regions == 1)
		check("procglow: no animation group is made for it: the flipbook is stepped from the frame's own OnUpdate", made ~= nil and #W.au.groups == 0 and type(made.frame.onUpdate) == "function")
		check("procglow: it plays at full opacity on all three, and stays off the others", G.all(W, G.playing) and G.glow(W, "ActionButton5") == nil)
		ns.ProcGlowStart(G.one)
		check("procglow: a second start of the same proc makes no frame and plays once", G.frames(W) == before + 3 and G.plays(made) == 1, G.plays(made))
		ns.ProcGlowStop(G.one)
		check("procglow: stopped, the animation stops and the glow is clear, the border is the general one", G.all(W, G.idle) and G.all(W, G.plain) and G.stops(made) == 1, G.trouble(W))
		ns.ProcGlowStart(G.one)
		check("procglow: started again, the same frame plays again, none is made", G.frames(W) == before + 3 and G.all(W, G.playing) and G.all(W, G.border, G.GOLD) and G.plays(made) == 2)
		ns.ProcGlowStop(G.one)
		ns.ProcGlowStop(G.one)
		ns.ProcGlowStop({ id = "never" })
		ns.ProcGlowStart(nil)
		ns.ProcGlowStart({ name = "no id" })
		ns.ProcGlowStop(nil)
		check("procglow: a stop twice, a stop of a proc never started and a start of nothing change nothing", G.all(W, G.plain) and G.stops(made) == 2 and G.quiet(W), G.trouble(W))
		clean(W, "procglow")
	end

	-- The proc mark beats the missing mark and gives it back.
	do
		local W = G.world()
		local ns = W.ns
		local RED = { 0.851, 0.251, 0.251 }
		local b = W.buttons.ActionButton1.button
		ns.SetButtonMark(b, "missing", RED[1], RED[2], RED[3])
		ns.ProcGlowStart(G.one)
		check("procglow: the proc border is drawn over the missing mark", G.border(W, "ActionButton1", G.GOLD))
		ns.ProcGlowStop(G.one)
		check("procglow: with the proc gone the missing mark is back, exactly", G.border(W, "ActionButton1", RED) and G.plain(W, "ActionButton2"))
		ns.SetButtonMark(b, "missing", nil)
		check("procglow: and with that gone the outline is the general one", G.plain(W, "ActionButton1"))
		ns.ProcColour = function(entry)
			return entry.col[1], entry.col[2], entry.col[3]
		end
		local blue = { id = "pgblue", name = "x", lights = { 974 }, col = { 0.2, 0.4, 0.9 } }
		ns.ProcGlowStart(blue)
		check("procglow: the colour is the one ProcColour gives", G.border(W, "ActionButton5", blue.col))
		ns.ProcGlowStop(blue)
		ns.ProcColour = function() return SECRET, 0.5, 0.5 end
		ns.ProcGlowStart(blue)
		check("procglow: a withheld colour is the gold, and no error", G.border(W, "ActionButton5", G.GOLD) and G.quiet(W), G.trouble(W))
		ns.ProcGlowStop(blue)
		ns.ProcColour = function() error("ProcColour failed", 0) end
		ns.ProcGlowStart(blue)
		check("procglow: a ProcColour that fails gives the gold", G.border(W, "ActionButton5", G.GOLD) and G.quiet(W), G.trouble(W))
		ns.ProcGlowStop(blue)
		clean(W, "procglow")
	end

	-- Two procs for one spell.
	do
		local W = G.world()
		local ns = W.ns
		ns.ProcColour = function(entry)
			if entry.id == "pg0003" then
				return 0.1, 0.9, 0.1
			end
			return 0.9, 0.1, 0.1
		end
		ns.ProcGlowStart(G.one)
		ns.ProcGlowStart(G.three)
		local made = G.glow(W, "ActionButton1")
		check("procglow: two procs for one spell: the one that came up first has the border, one frame, one play", G.border(W, "ActionButton1", { 0.9, 0.1, 0.1 }) and G.plays(made) == 1
			and G.count == 1)
		ns.ProcGlowStop(G.one)
		check("procglow: the first ends: the other still has the border in its colour and the glow goes on", G.border(W, "ActionButton1", { 0.1, 0.9, 0.1 }) and G.playing(W, "ActionButton1") and G.stops(made) == 0)
		ns.ProcGlowStop(G.three)
		check("procglow: the second ends: everything is back", G.all(W, G.plain) and G.all(W, G.idle) and G.stops(made) == 1)
		ns.ProcGlowStart(G.three)
		ns.ProcGlowStart(G.one)
		ns.ProcGlowStop(G.three)
		check("procglow: ending the earlier one leaves the later one's border", G.border(W, "ActionButton2", { 0.9, 0.1, 0.1 }) and G.playing(W, "ActionButton2"))
		ns.ProcGlowStop(G.one)
		clean(W, "procglow")
	end

	-- A fight.
	do
		local W = G.world()
		local ns = W.ns
		W.combat = true
		local before = G.frames(W)
		ns.ProcGlowStart(G.one)
		check("procglow: in a fight the border is drawn at once and no frame is made", G.all(W, G.tint, G.GOLD) and G.frames(W) == before and G.quiet(W), G.trouble(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("procglow: at the end of the fight the frames are made and play", G.frames(W) == before + 3 and G.all(W, G.playing) and G.all(W, G.border, G.GOLD) and G.quiet(W), G.trouble(W))
		ns.ProcGlowStop(G.one)
		-- Frames that exist: only SetAlpha, Play and Stop in a fight.
		local made = G.glow(W, "ActionButton1")
		local function snapshot()
			local calls = {}
			for k, v in pairs(made.frame.calls) do
				calls[k] = v
			end
			for k, v in pairs(made.texture.calls) do
				calls["t." .. k] = v
			end
			return calls
		end
		local first = snapshot()
		local plays, stops = G.plays(made), G.stops(made)
		W.combat = true
		ns.ProcGlowStart(G.one)
		local middle = snapshot()
		ns.ProcGlowStop(G.one)
		local last = snapshot()
		W.combat = false
		local others = true
		for _, calls in ipairs({ middle, last }) do
			for k, v in pairs(calls) do
				if k ~= "SetAlpha" and first[k] ~= v then
					others = false
				end
			end
		end
		check("procglow: with frames made, a start and a stop in a fight call only SetAlpha and SetScript, and make no frame", others and G.frames(W) == before + 3
			and G.plays(made) == plays + 1 and G.stops(made) == stops + 1 and middle.SetAlpha == first.SetAlpha + 1 and G.quiet(W), G.trouble(W))
		check("procglow: and the border came and went with them", G.all(W, G.plain))
		-- A proc that ends in the fight before any frame exists.
		local X = G.world()
		X.combat = true
		local count = G.frames(X)
		X.ns.ProcGlowStart(G.one)
		X.ns.ProcGlowStop(G.one)
		X.combat = false
		X.fire("PLAYER_REGEN_ENABLED")
		check("procglow: a proc that ends in the fight before any frame exists: the frames are made after it and stay idle", G.frames(X) == count + 3 and G.all(X, G.idle) and G.all(X, G.plain) and G.quiet(X), G.trouble(X))
		clean(W, "procglow")
	end

	-- The flipbook is not in the game, or a call is refused.
	do
		local W = G.world({ atlas = false })
		local ns = W.ns
		ns.ProcGlowStart(G.one)
		local made = G.glow(W, "ActionButton1")
		check("procglow: no atlas entry: the border and no texture, no animation", G.all(W, G.border, G.GOLD) and made ~= nil and made.texture == nil and made.frame.alpha == 0 and G.quiet(W), G.trouble(W))
		check("procglow: and the check says border yes, animation no", ns.ProcGlowLine(G.one) == "Glow: 3 buttons, border yes, animation no", ns.ProcGlowLine(G.one))
		ns.ProcGlowStop(G.one)
		check("procglow: stopped, it is plain", G.all(W, G.plain) and G.quiet(W), G.trouble(W))
		local E = G.world({ atlas = "error" })
		E.ns.ProcGlowStart(G.one)
		check("procglow: GetAtlasInfo that fails: the border only, no error", G.all(E, G.border, G.GOLD) and G.glow(E, "ActionButton1").texture == nil and G.quiet(E), G.trouble(E))
		local N = G.world()
		N.env.C_Texture = nil
		N.ns.ProcGlowStart(G.one)
		check("procglow: a client without C_Texture: the border only", G.all(N, G.border, G.GOLD) and G.glow(N, "ActionButton1").texture == nil and G.quiet(N), G.trouble(N))
		-- A call the game refuses in a fight.
		local R = G.world()
		R.ns.ProcGlowStart(G.one)
		R.ns.ProcGlowStop(G.one)
		local frame = G.glow(R, "ActionButton1").frame
		frame.SetAlpha = function() error("refused", 0) end
		R.combat = true
		R.ns.ProcGlowStart(G.one)
		R.combat = false
		local lines = {}
		for line in R.status():gmatch("[^\n]+") do
			if line:find("Proc glow:", 1, true) then
				lines[#lines + 1] = line
			end
		end
		check("procglow: a call the game refuses in a fight leaves the border and puts one line in the status", G.tint(R, "ActionButton1", G.GOLD) and #lines == 1 and G.quiet(R), table.concat(lines, "|") .. G.trouble(R))
		clean(W, "procglow")
	end

	-- A button the game glows itself.
	do
		local W = G.world({ alerts = true })
		local ns = W.ns
		local manager = W.gl.manager
		local one, two = W.buttons.ActionButton1.button, W.buttons.ActionButton2.button
		manager:ShowAlert(one)
		G.step(W)
		ns.ProcGlowStart(G.one)
		check("procglow: a button the game already glows gets the border and no glow", G.border(W, "ActionButton1", G.GOLD) and G.glow(W, "ActionButton1") == nil and G.playing(W, "ActionButton2") and G.playing(W, "MultiBarBottomLeftButton1"))
		manager:ShowAlert(two)
		G.step(W)
		check("procglow: the game starts its own glow on another: ours stops there", G.idle(W, "ActionButton2") and G.border(W, "ActionButton2", G.GOLD) and G.playing(W, "MultiBarBottomLeftButton1"), G.trouble(W))
		manager:HideAlert(one)
		G.step(W)
		check("procglow: the game's glow goes: ours starts", G.playing(W, "ActionButton1") and G.idle(W, "ActionButton2"))
		manager:HideAlert(two)
		G.step(W)
		check("procglow: both gone: all three play", G.all(W, G.playing))
		check("procglow: the addon never wrote button.SpellActivationAlert and never asked for an alert", W.buttons.ActionButton1.inner.SpellActivationAlert == nil and next(manager.activeAlerts) == nil)
		ns.ProcGlowStop(G.one)
		manager:ShowAlert(one)
		manager:HideAlert(one)
		G.step(W)
		check("procglow: with no proc up, the game's alerts change nothing", G.all(W, G.plain) and G.quiet(W), G.trouble(W))
		local hooks = W.hooks
		ns.ProcGlowStart(G.one)
		ns.ProcGlowStart(G.two)
		manager:ShowAlert(one)
		G.step(W)
		check("procglow: the hooks are made once, not at every start", W.hooks == hooks and G.idle(W, "ActionButton1"), W.hooks .. " " .. hooks)
		clean(W, "procglow")
		-- A game that has no alert manager, or one that fails.
		local X = G.world()
		X.ns.ProcGlowStart(G.one)
		check("procglow: no alert manager: the glow plays", G.all(X, G.playing) and G.quiet(X), G.trouble(X))
		local F = G.world({ alerts = true })
		F.gl.manager.HasAlert = function() error("HasAlert failed", 0) end
		F.ns.ProcGlowStart(G.one)
		check("procglow: HasAlert that fails: the glow plays, no error", G.all(F, G.playing) and G.quiet(F), G.trouble(F))
	end

	-- The setting and the page.
	do
		local W = G.world()
		local ns = W.ns
		ns.ProcGlowStart(G.one)
		W.change("trackers.glow", false)
		check("procglow: Glow on the action button off puts the border and the glow back at once", G.all(W, G.plain) and G.all(W, G.idle) and G.quiet(W), G.trouble(W))
		ns.ProcGlowStart(G.two)
		check("procglow: and with it off a proc that comes up draws nothing", G.plain(W, "ActionButton5") and G.glow(W, "ActionButton5") == nil)
		check("procglow: the check says Glow: off", ns.ProcGlowLine(G.one) == "Glow: off", ns.ProcGlowLine(G.one))
		W.change("trackers.glow", true)
		check("procglow: switched on again the procs that are up have both, the second too", G.all(W, G.border, G.GOLD) and G.all(W, G.playing) and G.border(W, "ActionButton5", G.GOLD) and G.playing(W, "ActionButton5"), G.trouble(W))
		W.change("trackers.enabled", false)
		W.fire("ACTIONBAR_SLOT_CHANGED")
		G.step(W)
		check("procglow: the Trackers page off: the buttons are put back when they next change", G.all(W, G.plain) and G.all(W, G.idle) and G.plain(W, "ActionButton5") and G.quiet(W), G.trouble(W))
		W.change("trackers.enabled", true)
		W.fire("ACTIONBAR_SLOT_CHANGED")
		G.step(W)
		check("procglow: and on again, the procs still up come back", G.all(W, G.playing) and G.border(W, "ActionButton5", G.GOLD))
		ns.ProcGlowStop(G.one)
		ns.ProcGlowStop(G.two)
		clean(W, "procglow")
		local O = G.world({ options = { ["actionbars.enabled"] = false } })
		local count = G.frames(O)
		O.ns.ProcGlowStart(G.one)
		check("procglow: Restyle action bars off: no button, no frame, no error", G.frames(O) == count and G.quiet(O) and O.ns.ProcGlowLine(G.one) == "Glow: Restyle action bars is off", O.ns.ProcGlowLine(G.one) .. G.trouble(O))
		O.change("actionbars.enabled", true)
		G.step(O)
		check("procglow: switched on, the proc that is up has both", G.border(O, "ActionButton1", G.GOLD) and G.playing(O, "ActionButton1"), G.trouble(O))
		clean(O, "procglow")
	end

	-- A button remapped while a proc is up.
	do
		local W = G.world()
		local ns = W.ns
		ns.ProcGlowStart(G.one)
		W.gl.info[G.number("ActionButton2")] = { "spell", 974 }
		W.fire("ACTIONBAR_SLOT_CHANGED")
		G.step(W)
		check("procglow: a button that no longer holds the spell is put back", G.plain(W, "ActionButton2") and G.idle(W, "ActionButton2") and G.playing(W, "ActionButton1") and G.playing(W, "MultiBarBottomLeftButton1"), G.trouble(W))
		W.gl.info[G.number("ActionButton9")] = { "spell", 905 }
		W.buttons.ActionButton9.inner.action = G.number("ActionButton9")
		W.combat = true
		local count = G.frames(W)
		W.fire("ACTIONBAR_SLOT_CHANGED")
		G.step(W)
		check("procglow: a spell moved onto a button in a fight: the border at once, the frame not made", G.tint(W, "ActionButton9", G.GOLD) and G.frames(W) == count and G.quiet(W), G.trouble(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("procglow: after the fight it has the frame and the glow", G.border(W, "ActionButton9", G.GOLD) and G.playing(W, "ActionButton9") and G.frames(W) == count + 1 and G.quiet(W), G.trouble(W))
		ns.ProcGlowStop(G.one)
		check("procglow: the proc ends: every button of the map is plain, the moved one too", G.all(W, G.plain) and G.plain(W, "ActionButton9") and G.idle(W, "ActionButton9"))
		W.gl.info[G.number("ActionButton2")] = { "spell", 325 }
		W.fire("ACTIONBAR_SLOT_CHANGED")
		G.step(W)
		check("procglow: a button that holds the spell again with no proc up is untouched", G.plain(W, "ActionButton2") and G.idle(W, "ActionButton2") and G.quiet(W), G.trouble(W))
		clean(W, "procglow")
	end

	-- The check line.
	do
		local W = G.world()
		local ns = W.ns
		local bare = { id = "pgx", name = "Shadow Bolt", lights = {} }
		check("procglow: no button holds the spell: the check names it", ns.ProcGlowLine(G.none) == "Glow: no button holds Fireball", ns.ProcGlowLine(G.none))
		check("procglow: a proc with no light names itself", ns.ProcGlowLine(bare) == "Glow: no button holds Shadow Bolt", ns.ProcGlowLine(bare))
		ns.ProcGlowStart(G.two)
		check("procglow: one button is called button", ns.ProcGlowLine(G.two) == "Glow: 1 button, border yes, animation yes", ns.ProcGlowLine(G.two))
		ns.ProcGlowStart(G.one)
		check("procglow: the check counts buttons, the border and the animation", ns.ProcGlowLine(G.one) == "Glow: 3 buttons, border yes, animation yes", ns.ProcGlowLine(G.one))
		ns.ProcGlowStop(G.one)
		ns.ProcGlowStop(G.two)
		check("procglow: before the proc is up the check counts the buttons that hold it, border no", ns.ProcGlowLine(G.one) == "Glow: 3 buttons, border no, animation yes", ns.ProcGlowLine(G.one))
		local longer = { id = "pgl", name = "long", lights = {} }
		for index = 1, 45 do
			longer.lights[index] = 5
		end
		longer.lights[41] = 905
		ns.ProcGlowStart(longer)
		check("procglow: only the first 40 lights are read", G.plain(W, "ActionButton1") and G.quiet(W), G.trouble(W))
		ns.ProcGlowStop(longer)
		ns.ProcGlowStart({ id = "pgbad", name = "bad", lights = "x" })
		ns.ProcGlowStart({ id = "pgbad2", name = "bad", lights = { SECRET, "x", -1 } })
		check("procglow: lights that are no list, a withheld ID and an ID that is no number are skipped", G.all(W, G.plain) and G.quiet(W), G.trouble(W))
		clean(W, "procglow")
	end

	-- hkglow: the game's alert is followed on the manager table, never on a button, with taintLog 0 and 2, and the answer waits for the next frame.
	for _, value in ipairs({ "0", "2" }) do
		do
			local W = G.world({ alerts = true })
			W.cvars.taintLog = value
			local ns = W.ns
			local manager = W.gl.manager
			local one, two = W.buttons.ActionButton1.button, W.buttons.ActionButton2.button
			local tag = "hkglow: taintLog " .. value .. ": "
			local before = W.hooks
			ns.ProcGlowStart(G.one)
			check(tag .. "the manager is followed, and no button has a hook of the addon's", INSTHOOK.wrapped(W, manager, "ShowAlert") and INSTHOOK.wrapped(W, manager, "HideAlert")
				and not INSTHOOK.wrapped(W, W.buttons.ActionButton1.inner, "SetAlpha") and not INSTHOOK.wrapped(W, W.buttons.ActionButton1.inner, "Show") and W.hooks == before + 2, W.hooks .. " " .. before)
			manager:ShowAlert(one)
			check(tag .. "inside the game's call nothing changes", G.playing(W, "ActionButton1") and G.quiet(W), G.trouble(W))
			G.step(W)
			check(tag .. "on the next frame the button the game glows is left to the game, the border stays", G.idle(W, "ActionButton1") and G.border(W, "ActionButton1", G.GOLD) and G.playing(W, "ActionButton2"), G.trouble(W))
			manager:HideAlert(one)
			manager:ShowAlert(two)
			manager:ShowAlert(two)
			G.step(W)
			check(tag .. "two calls on one button and a hide on another are all answered in the one pass", G.playing(W, "ActionButton1") and G.idle(W, "ActionButton2") and #W.timers == 0, G.trouble(W))
			ns.ProcGlowStop(G.one)
			W.change("trackers.glow", false)
			ns.ProcGlowStart(G.one)
			manager:HideAlert(two)
			G.step(W)
			check(tag .. "with Glow on the action button off a game alert changes nothing", G.all(W, G.plain) and G.quiet(W), G.trouble(W))
			W.change("trackers.glow", true)
			check(tag .. "switched on, the proc has the border and the glow again", G.border(W, "ActionButton1", G.GOLD) and G.playing(W, "ActionButton1"), G.trouble(W))
			clean(W, "hkglow")
		end
	end
	-- The glow is not added under a protected button, runs no animation group on a game frame, and follows the shown state of its button.
	do
		local W = G.world()
		local ns = W.ns
		local inner = W.buttons.ActionButton1.inner
		local kids = #inner.children
		local groups = #W.au.groups
		ns.ProcGlowStart(G.one)
		local made = G.glow(W, "ActionButton1")
		check("useaction: glow: no frame is added under a protected action button, and no animation group is made", made ~= nil and #inner.children == kids and #W.au.groups == groups and G.count == 1, #inner.children .. " " .. kids)
		W.frameUpdate(0.1)
		local first = made.texture.texCoord and { unpack(made.texture.texCoord) }
		W.frameUpdate(0.31)
		local second = made.texture.texCoord
		check("useaction: glow: the flipbook is stepped from OnUpdate, one cell of the 5 by 6 grid at a time, and the cell moves",
			first ~= nil and second ~= nil and near(second[2] - second[1], 0.2, 1e-6) and near(second[4] - second[3], 1 / 6, 1e-6) and (first[1] ~= second[1] or first[3] ~= second[3]) and G.quiet(W),
			tostring(first and first[1]) .. " " .. tostring(second and second[1]))
		local held = { second[1], second[3] }
		W.frameUpdate(1)
		check("useaction: glow: the flipbook loops: a second later it shows the same cell", near(made.texture.texCoord[1], held[1], 1e-6) and near(made.texture.texCoord[3], held[2], 1e-6), tostring(made.texture.texCoord[1]))
		inner.shown = false
		W.frameUpdate(0.1)
		check("useaction: glow: while the button is hidden the glow is clear, though its container is shown", made.frame.alpha == 0 and made.frame.onUpdate ~= nil, tostring(made.frame.alpha))
		inner.shown = true
		W.frameUpdate(0.1)
		check("useaction: glow: when the button shows again the glow comes back", made.frame.alpha == 1 and G.quiet(W), tostring(made.frame.alpha))
		ns.ProcGlowStop(G.one)
		check("useaction: glow: stopped, the script is cleared and the glow is clear", made.frame.onUpdate == nil and made.frame.alpha == 0)
	end

	-- A proc, a fight and a layout pass never run Update, UpdateAction, SetAttribute or Show on a stock action button (SecureTemplates.lua:806 reads
	-- pressAndHoldAction, which only the game's Update writes, ActionButton.lua:521-532).
	do
		local W = G.world()
		local ns = W.ns
		local touched = {}
		for name, entry in pairs(W.buttons) do
			for _, call in ipairs({ "Update", "UpdateAction", "SetAttribute", "Show", "UpdateButtonArt" }) do
				local base = entry.inner[call]
				if base then
					entry.inner[call] = function(...)
						touched[#touched + 1] = name .. "." .. call
						return base(...)
					end
				end
			end
		end
		ns.ProcGlowStart(G.one)
		G.step(W)
		W.combat = true
		W.fire("PLAYER_REGEN_DISABLED")
		ns.ProcGlowStop(G.one)
		ns.ProcGlowStart(G.one)
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.advance(1)
		ns.ProcGlowStop(G.one)
		check("useaction: stock buttons: a proc, a fight and a layout pass run no Update, UpdateAction, SetAttribute or Show on an action button", #touched == 0 and G.quiet(W), table.concat(touched, ","):sub(1, 200))
	end
end
-- >>> mp-proc-glow (end)
-- >>> enemyready (begin)
-- Enemy cooldowns: Always, the ready alerts and the lists. The helpers are on TOC.er, so that this file gains no local.
do
	local EC, EB = TOC.ec, TOC.eb
	local ER = {}
	TOC.er = ER
	-- A world with the options of the table `options` (by path) and, when `saved` is given, that saved table as the account's.
	function ER.world(options, saved, setup)
		return EB.world({ opts = { saved = saved or { options = options or {} } }, setup = setup })
	end
	-- Casts and buffs of other units are withheld.
	function ER.hide(W)
		W.au.castsHidden, W.au.hidden = true, true
	end
	-- Makes `unit` an enemy player of a class and level, as the game says, with no wait for the timers (EB.pick lets them run).
	function ER.pick(W, unit, who)
		W.au.unit[unit] = { guid = who.guid, player = true, attack = true, class = who.class, race = who.race or "Human", level = who.level, name = "Pick" }
		W.fire(unit == "focus" and "PLAYER_FOCUS_CHANGED" or "PLAYER_TARGET_CHANGED")
	end
	function ER.icon(W, row, key)
		for _, icon in ipairs(row and row.icons or {}) do
			if icon.key == key and W.rawOf[icon.frame].shown == true then
				return icon
			end
		end
		return nil
	end
	function ER.dark(W, icon)
		local raw = W.rawOf[icon.texture]
		return raw.desaturated == true and raw.vertex[1] == 0.6
	end
	function ER.bright(W, icon)
		local raw = W.rawOf[icon.texture]
		return raw.desaturated == false and raw.vertex[1] == 1
	end
	-- The game says the sweep of an icon is done.
	function ER.done(W, icon)
		local raw = W.rawOf[icon.cooldown] or icon.cooldown
		raw.scripts.OnCooldownDone(icon.cooldown)
	end
	function ER.addSpells(W)
		W.addSpell(999001, { name = "Odd Strike" })
		W.addSpell(999002, { name = "Odd Ward" })
	end
	-- The rows of a page by key.
	function ER.page(W, key)
		local rows = {}
		for _, page in ipairs(W.ns.PAGES) do
			if page.key == key then
				for _, row in ipairs(page) do
					if row.key then
						rows[row.key] = row
					end
				end
			end
		end
		return rows
	end
end

