-- >>> enemyready (end)
-- >>> ms-late (begin)
-- Colour by health left, low health border and cast time (ms-22). Every label starts "ms-late:". The values are kept in one table L: the main function of this
-- file has a limit on the locals alive at once. The client's curve calls are made here: a colour curve and a step curve with Evaluate, UnitHealthPercent
-- (the share of health left in W.L.health by unit, through the curve it is given), duration objects and a duration text binding. W.L.fault names a call that raises.
do
	local L = {}
	L.FULL, L.HALF, L.LOW = "0.18,0.72,0.30", "0.90,0.76,0.18", "0.85,0.23,0.19"
	L.rgb = function(r, g, b) return ("%.2f,%.2f,%.2f"):format(r, g, b) end
	-- The calls of the client these parts use, on the environment of a world.
	function L.fakes(W)
		local env, T = W.env, { health = {}, calls = {}, fault = {}, exists = {}, bindings = {}, casts = {}, channels = {}, made = 0 }
		W.L = T
		env.Enum = env.Enum or {}
		env.Enum.LuaCurveType = { Linear = 0, Step = 1, Cosine = 2, Cubic = 3 }
		env.CreateColor = env.CreateColor or function(r, g, b, a) return { r = r, g = g, b = b, a = a or 1 } end
		local function curve(color)
			local c = { points = {}, kind = 0, color = color }
			function c.AddPoint(_, x, y)
				if T.fault.AddPoint then error("AddPoint failed", 0) end
				c.points[#c.points + 1] = { x, y }
				table.sort(c.points, function(a, b) return a[1] < b[1] end)
			end
			function c.SetType(_, kind)
				if T.fault.SetType then error("SetType failed", 0) end
				c.kind = kind
			end
			function c.Evaluate(_, x)
				local lo, hi
				for _, p in ipairs(c.points) do
					if p[1] <= x then lo = p end
					if p[1] >= x and not hi then hi = p end
				end
				if c.kind == 1 then
					return (lo or c.points[1])[2]
				end
				lo, hi = lo or hi, hi or lo
				local t = hi[1] == lo[1] and 0 or (x - lo[1]) / (hi[1] - lo[1])
				if not color then
					return lo[2] + (hi[2] - lo[2]) * t
				end
				local a, b = lo[2], hi[2]
				return a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t
			end
			return c
		end
		env.C_CurveUtil = { CreateColorCurve = function()
			T.made = T.made + 1
			if T.fault.CreateColorCurve then error("CreateColorCurve failed", 0) end
			return curve(true)
		end, CreateCurve = function()
			if T.fault.CreateCurve then error("CreateCurve failed", 0) end
			return curve(false)
		end }
		env.UnitHealthPercent = function(unit, predicted, c)
			T.calls[#T.calls + 1] = unit
			if T.fault.UnitHealthPercent then error("UnitHealthPercent failed", 0) end
			if type(unit) ~= "string" or predicted ~= true or type(c) ~= "table" or not c.Evaluate then error("UnitHealthPercent: a unit, true and a curve", 0) end
			local share = T.health[unit] or 1
			if T.secret then
				return c.color and { GetRGB = function() return SECRET, SECRET, SECRET end } or SECRET
			end
			if c.color then
				local r, g, b = c:Evaluate(share)
				return { GetRGB = function() return r, g, b end }
			end
			return c:Evaluate(share)
		end
		env.UnitExists = function(unit) return T.exists[unit] ~= false end
		-- The hidden status bar of the feature test: the base world makes frames only, so a bar is a frame that takes the colour.
		local create = env.CreateFrame
		env.CreateFrame = function(kind, name, parent, template)
			if kind == "StatusBar" and name == nil and parent == nil and template == nil then
				local frame = create("Frame")
				W.rawOf[frame].SetStatusBarColor = function(_, r, g, b) T.probed = { r, g, b } end
				return frame
			end
			local frame = create(kind, name, parent, template)
			-- SetAlpha takes a withheld value from addon code (SimpleFrameAPIDocumentation.lua:1133-1142).
			local raw = W.rawOf[frame]
			local setAlpha = raw.SetAlpha
			raw.SetAlpha = function(self, alpha)
				if rawequal(alpha, SECRET) then
					raw.alpha = alpha
				else
					return setAlpha(self, alpha)
				end
			end
			return frame
		end
		-- Casts: T.casts[unit] and T.channels[unit] are the seconds left. The duration object answers GetRemainingDuration.
		local function duration(list, unit) return { GetRemainingDuration = function() if T.fault.Remaining then error("GetRemainingDuration failed", 0) end return list[unit] end } end
		env.UnitCastingDuration = function(unit)
			T.asked = (T.asked or 0) + 1
			if T.fault.UnitCastingDuration then error("UnitCastingDuration failed", 0) end
			return T.casts[unit] and duration(T.casts, unit) or nil
		end
		env.UnitChannelDuration = function(unit)
			T.asked = (T.asked or 0) + 1
			if T.fault.UnitChannelDuration then error("UnitChannelDuration failed", 0) end
			return T.channels[unit] and duration(T.channels, unit) or nil
		end
		env.C_StringUtil = { CreateSecondsFormatter = function()
			if T.fault.Formatter then error("CreateSecondsFormatter failed", 0) end
			return { seconds = true }
		end }
		env.C_DurationUtil = { CreateDurationTextBinding = function()
			if T.fault.Binding then error("CreateDurationTextBinding failed", 0) end
			local b = { enabled = false, sets = 0 }
			T.bindings[#T.bindings + 1] = b
			function b.SetFontString(_, fs) if T.fault.SetFontString then error("SetFontString failed", 0) end b.font = fs end
			function b.SetFormatter(_, f) b.formatter = f end
			function b.SetDuration(_, d)
				if T.fault.SetDuration then error("SetDuration failed", 0) end
				b.duration, b.sets = d, b.sets + 1
			end
			function b.SetEnabled(_, on) b.enabled = on end
			return b
		end }
		return T
	end
	-- One look of the frame the part runs every 0.1 s: every shown frame with an OnUpdate gets 0.1 s.
	function L.step(W, times, dt)
		for _ = 1, times or 1 do
			W.now = W.now + (dt or 0.1)
			for _, f in ipairs(W.eventFrames) do
				if f.onUpdate and f.shown ~= false then
					f.onUpdate(f, dt or 0.1)
				end
			end
			W.tick()
		end
	end
	-- The frames of the addon that run an OnUpdate and are shown.
	function L.running(W)
		local n = 0
		for _, f in ipairs(W.eventFrames) do
			if f.onUpdate and f.shown ~= false and not f.dividers then
				n = n + 1
			end
		end
		return n
	end
	function L.silent(W)
		return #W.violations == 0 and #W.errors == 0 and #W.out == 0
	end
	function L.why(W)
		return table.concat(W.violations, "|") .. table.concat(W.errors, "|") .. table.concat(W.out, "|")
	end

	-- The rows --------------------------------------------------------------------------------------------
	do
		local W = newWorld()
		local rows = {}
		for _, page in ipairs(W.ns.PAGES) do
			for _, row in ipairs(page) do
				if row.key then
					rows[page.key .. "." .. row.key] = row
				end
			end
		end
		local want = { { "general.healthFull", "ff2eb84d", "generalColours" }, { "general.healthHalf", "ffe6c12e", "generalColours" },
			{ "general.healthLow", "ffd93a30", "generalColours" }, { "unitframes.healthByLeft", false, "unitframesBars" }, { "nameplates.healthByLeft", false, "nameplatesColours" },
			{ "nameplates.lowHealth", false, "nameplatesColours" }, { "nameplates.lowHealthAt", 20, "nameplatesColours" },
			{ "nameplates.lowHealthColour", "ffff3333", "nameplatesColours" }, { "resource.healthByLeft", false, "resource" }, { "castbars.ownTime", false, "castbarsText" },
			{ "nameplates.castTime", false, "nameplatesCast" } }
		local bad, wrong = {}, {}
		for _, entry in ipairs(want) do
			if W.ns.Get(entry[1]) ~= entry[2] then
				bad[#bad + 1] = entry[1] .. "=" .. tostring(W.ns.Get(entry[1]))
			end
			if not rows[entry[3] .. "." .. entry[1]:match("%.(.+)$")] then
				wrong[#wrong + 1] = entry[1] .. "@" .. entry[3]
			end
		end
		check("ms-late: the eleven rows start at their stand-in defaults", #bad == 0, table.concat(bad, " "))
		check("ms-late: each row is on the page named for it", #wrong == 0, table.concat(wrong, " "))
		local at = rows["nameplatesColours.lowHealthAt"]
		check("ms-late: Low health below runs from 5 to 50 percent in steps of 5, and it and its colour need Low health border", at.min == 5 and at.max == 50 and at.step == 5
			and at.unit == "%" and at.needs == "lowHealth" and rows["nameplatesColours.lowHealthColour"].needs == "lowHealth" and rows["nameplatesColours.lowHealth"].needs == nil
			and rows["nameplatesColours.healthByLeft"].needs == nil)
		check("ms-late: the unit frame and resource rows need Flat bars and Flat fill, and the cast time rows need nothing", rows["unitframesBars.healthByLeft"].needs == "flat"
			and rows["resource.healthByLeft"].needs == "flat" and rows["castbarsText.ownTime"].needs == nil and rows["nameplatesCast.castTime"].needs == nil)
		check("ms-late: the tips", rows["unitframesBars.healthByLeft"].tip == "In the three colours of the Colours page. Not raid frames."
			and rows["castbarsText.ownTime"].tip == "Seconds left, at the right end of the bar." and rows["nameplatesCast.castTime"].tip == "Seconds left, at the right end of the bar.")
		W.ns.Set("nameplates.lowHealthAt", 22)
		local off = W.ns.Get("nameplates.lowHealthAt")
		W.ns.Set("nameplates.lowHealthAt", 60)
		W.ns.Set("general.healthLow", "red")
		check("ms-late: a limit off its range and a colour that is no colour are refused", W.ns.Get("nameplates.lowHealthAt") ~= 60 and off ~= 60 and W.ns.Get("general.healthLow") == "ffd93a30",
			tostring(W.ns.Get("nameplates.lowHealthAt")) .. " " .. tostring(W.ns.Get("general.healthLow")))
		clean(W, "ms-late rows")
	end

	-- The plates ------------------------------------------------------------------------------------------
	L.UNITS = { "attack", "player", "reaction", "sel", "class", "threat" }
	function L.hex(hex)
		return tonumber(hex:sub(3, 4), 16) / 255, tonumber(hex:sub(5, 6), 16) / 255, tonumber(hex:sub(7, 8), 16) / 255
	end
	-- True when a colour table {r, g, b} is the colour given, to a hundredth.
	function L.is(c, r, g, b)
		return type(c[1]) == "number" and math.abs(c[1] - r) < 0.006 and math.abs(c[2] - g) < 0.006 and math.abs(c[3] - b) < 0.006
	end
	function L.show(c)
		return type(c[1]) == "number" and L.rgb(c[1], c[2], c[3]) or "withheld"
	end
	-- A world with plates: the unit calls the colour part asks, and the game's colour call, which sets the bar to plate.game when it differs.
	function L.pworld(options)
		local opts = { ["nameplates.healthFlat"] = false, ["nameplates.castFlat"] = false }
		for key, value in pairs(options or {}) do
			opts[key] = value
		end
		local W = newWorld({ saved = { options = opts } })
		local T = L.fakes(W)
		T.byFrame, T.attack, T.player, T.reaction, T.sel, T.class, T.threat = {}, {}, {}, {}, {}, {}, {}
		local env = W.env
		env.NamePlateSetupOptions = { horizontalScale = 1, verticalScale = 1, insetWidth = 12, healthBarHeight = 13, castBarHeight = 6, castIconHeight = 10,
			useClassicHealthBar = false, useClassicCastBar = false }
		env.NamePlateConstants = { NAME_PLATE_WIDTH = 190 }
		env.UnitCanAttack = function(_, unit) return T.attack[unit] == true end
		env.UnitThreatSituation = function(_, unit) return T.threat[unit] end
		env.UnitGroupRolesAssigned = function() return "NONE" end
		env.UnitIsPlayer = function(unit) return T.player[unit] == true end
		env.UnitReaction = function(unit) return T.reaction[unit] end
		env.UnitSelectionColor = function(unit)
			local c = T.sel[unit] or { 1, 0, 0 }
			return c[1], c[2], c[3]
		end
		env.UnitClassification = function(unit) return T.class[unit] or "normal" end
		env.UnitIsBossMob = function() return false end
		env.CompactUnitFrame_UpdateHealthColor = function(frame)
			local p = T.byFrame[frame]
			if p then
				local c, now = p.game, p.colour
				if c[1] ~= now[1] or c[2] ~= now[2] or c[3] ~= now[3] then
					p.colour = { c[1], c[2], c[3], 1 }
					p.gameSets = p.gameSets + 1
				end
			end
		end
		W.login()
		return W
	end
	-- A plate with a unit. plate.colour is what the bar shows, plate.game what the game last chose for it, plate.sets the calls made on the bar.
	function L.plate(W, unit, o)
		o = o or {}
		local T = W.L
		local plate = W.newPlate()
		plate.inner.unit, plate.inner.isFriend = unit, o.friend
		plate.colour, plate.game, plate.sets, plate.gameSets = { 0.2, 0.4, 0.6, 1 }, { 0.2, 0.4, 0.6, 1 }, 0, 0
		local hb = plate.healthInner
		hb.GetStatusBarColor = function() return plate.colour[1], plate.colour[2], plate.colour[3], plate.colour[4] end
		hb.SetStatusBarColor = function(_, r, g, b, a)
			plate.sets = plate.sets + 1
			plate.colour = { r, g, b, a }
		end
		T.byFrame[plate.UnitFrame] = plate
		T.attack[unit], T.player[unit], T.reaction[unit], T.sel[unit], T.class[unit], T.threat[unit] = o.attack, o.player, o.reaction, o.sel, o.class, o.threat
		T.health[unit] = o.health
		W.showPlate(unit, plate)
		W.flush()
		return plate
	end
	function L.game(W, plate)
		W.env.CompactUnitFrame_UpdateHealthColor(plate.UnitFrame)
		W.flush()
	end
	function L.set(W, path, value)
		W.ns.Set(path, value)
		W.flush()
	end
	-- The frames of the addon made on the health bar of a plate, the first being the low health border's frame and the second the frame of its edges.
	function L.border(W, plate)
		local made = {}
		for _, f in ipairs(W.addonFrames) do
			if f.parent == plate.healthBar then
				made[#made + 1] = f
			end
		end
		-- The first frame on the bar is the plate's own border; the second is the low health border's, and its edges are on a frame inside it.
		local edges = {}
		for _, f in ipairs(W.addonFrames) do
			if made[2] and f.parent == made[2] and #W.edgesOn(f) == 4 then
				edges = W.edgesOn(f)
			end
		end
		return made[2], #edges == 4 and edges[1] or nil
	end

	-- At the defaults nothing is made, hooked or called.
	do
		local W = L.pworld()
		local T = W.L
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		local hooks, sets, frames = W.hooks, a.sets, #W.addonFrames
		L.game(W, a)
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-late: at the defaults the game's call is not followed, no curve is made, no health is asked for and the bar is never set", W.hooks == hooks and #T.calls == 0 and T.made == 0
			and a.sets == sets and L.is(a.colour, 0.2, 0.4, 0.6) and L.running(W) == 0, W.hooks .. " " .. hooks .. " " .. #T.calls .. " " .. T.made .. " " .. a.sets)
		check("ms-late: and /flatui status has no line about the curve or cast time", not has(W.status(), "Health curve") and not has(W.status(), "Cast time"), W.status())
		clean(W, "ms-late defaults")
	end

	-- Colour health bars by health left, on a plate.
	do
		local W = L.pworld()
		local T = W.L
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		local fr, fg, fb = L.hex("ff2eb84d")
		local hr, hg, hb = L.hex("ffe6c12e")
		local lr, lg, lb = L.hex("ffd93a30")
		L.set(W, "nameplates.healthByLeft", true)
		check("ms-late: the first try goes through the curve on the player's health, and a plate at half health has the colour at half health", T.calls[1] == "player"
			and L.is(a.colour, hr, hg, hb) and has(W.status(), "Health curve: works"), L.show(a.colour) .. " " .. tostring(T.calls[1]) .. W.status())
		T.health.nameplate1 = 1
		L.game(W, a)
		check("ms-late: the game's call answers with the colour at full health, in the same call", L.is(a.colour, fr, fg, fb) and a.gameSets == 1, L.show(a.colour) .. " " .. a.gameSets)
		T.health.nameplate1 = 0
		L.game(W, a)
		check("ms-late: and at no health with the colour at low health", L.is(a.colour, lr, lg, lb), L.show(a.colour))
		T.health.nameplate1 = 0.25
		L.game(W, a)
		check("ms-late: between the points the curve gives the share between the two colours", L.is(a.colour, (lr + hr) / 2, (lg + hg) / 2, (lb + hb) / 2), L.show(a.colour))
		L.set(W, "general.healthFull", "ff112233")
		W.advance(0.3)
		T.health.nameplate1 = 1
		L.game(W, a)
		check("ms-late: a colour changed on the Colours page is the colour used at once", L.is(a.colour, 0x11 / 255, 0x22 / 255, 0x33 / 255), L.show(a.colour))
		L.set(W, "general.healthFull", "ff2eb84d")
		a.game = { 0.3, 0.3, 0.3, 1 }
		L.set(W, "nameplates.healthByLeft", false)
		check("ms-late: switched off the bar has the colour the game set last", L.is(a.colour, 0.2, 0.4, 0.6) or L.is(a.colour, 0.3, 0.3, 0.3), L.show(a.colour))
		local sets = a.sets
		T.health.nameplate1 = 0.5
		L.game(W, a)
		check("ms-late: and the game's next call is its own", L.is(a.colour, 0.3, 0.3, 0.3) and a.sets == sets, L.show(a.colour))
		clean(W, "ms-late plate colour")
	end

	-- A colour of PlateColours.lua on the plate wins over the colour of the health left, and gives it back when it goes.
	do
		local W = L.pworld()
		local a = L.plate(W, "nameplate1", { friend = false, attack = true, reaction = 2, sel = { 0.9, 0.1, 0.1 }, health = 0.5 })
		local hr, hg, hb = L.hex("ffe6c12e")
		L.set(W, "nameplates.healthByLeft", true)
		L.set(W, "nameplates.colours", true)
		check("ms-late: a reaction colour on the plate wins over the colour of the health left", L.is(a.colour, 0.9, 0.1, 0.1), L.show(a.colour))
		L.game(W, a)
		check("ms-late: and still does when the game sets its colour again", L.is(a.colour, 0.9, 0.1, 0.1), L.show(a.colour))
		L.set(W, "nameplates.colours", false)
		L.game(W, a)
		check("ms-late: with the reaction colour off the health left has the bar again", L.is(a.colour, hr, hg, hb), L.show(a.colour))
		L.set(W, "nameplates.targetBar", true)
		W.units.target = a
		W.fire("PLAYER_TARGET_CHANGED")
		W.flush()
		check("ms-late: the target's own colour wins too", L.is(a.colour, L.hex("ff66b3ff")), L.show(a.colour))
		clean(W, "ms-late plate override")
	end

	-- A friendly plate that is not restyled keeps the game's colour.
	do
		local W = L.pworld()
		local a = L.plate(W, "nameplate1", { friend = true, health = 0.5 })
		local b = L.plate(W, "nameplate2", { friend = false, health = 0.5 })
		L.set(W, "nameplates.friendly", false)
		L.set(W, "nameplates.healthByLeft", true)
		check("ms-late: a friendly plate with Restyle friendly nameplates off keeps the game's colour and an enemy plate does not", L.is(a.colour, 0.2, 0.4, 0.6) and L.is(b.colour, L.hex("ffe6c12e")),
			L.show(a.colour) .. " " .. L.show(b.colour))
		L.set(W, "nameplates.friendly", true)
		check("ms-late: and with it on the friendly plate has the colour", L.is(a.colour, L.hex("ffe6c12e")), L.show(a.colour))
		L.set(W, "nameplates.enabled", false)
		check("ms-late: with the Nameplates page off the plates have the game's colour", L.is(a.colour, 0.2, 0.4, 0.6) and L.is(b.colour, 0.2, 0.4, 0.6), L.show(a.colour) .. " " .. L.show(b.colour))
		clean(W, "ms-late plate friendly")
	end

	-- A plate that goes: what was painted is forgotten and the game colours it again for the next unit.
	do
		local W = L.pworld()
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		L.set(W, "nameplates.healthByLeft", true)
		L.set(W, "nameplates.lowHealth", true)
		a.inner.unit = nil
		W.units.nameplate1 = nil
		W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		W.flush()
		local holder = L.border(W, a)
		check("ms-late: a plate the game takes back loses its low health border", holder ~= nil and W.rawOf[holder].shown == false, tostring(holder and W.rawOf[holder].shown))
		a.game = { 0.3, 0.3, 0.3, 1 }
		L.game(W, a)
		check("ms-late: and the game's next colour for it is its own", L.is(a.colour, 0.3, 0.3, 0.3), L.show(a.colour))
		a.inner.unit = "nameplate1"
		W.units.nameplate1 = a
		W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
		W.flush()
		check("ms-late: the plate that comes back with a unit has the colour and the border again", L.is(a.colour, L.hex("ffe6c12e")) and W.rawOf[L.border(W, a)].shown == true, L.show(a.colour))
		clean(W, "ms-late plate leave")
	end

	-- A client that refuses the curve: the rows change nothing, and /flatui status says so.
	do
		for _, fault in ipairs({ "UnitHealthPercent", "CreateColorCurve", "AddPoint" }) do
			local W = L.pworld()
			W.L.fault[fault] = true
			local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
			L.set(W, "nameplates.healthByLeft", true)
			L.set(W, "nameplates.lowHealth", true)
			check("ms-late: a client that refuses " .. fault .. " leaves the plate's colour and has no border, and the status says refused", L.is(a.colour, 0.2, 0.4, 0.6) and a.sets == 0
				and L.border(W, a) == nil and has(W.status(), "Health curve: refused") and L.silent(W), L.show(a.colour) .. " " .. W.status() .. L.why(W))
		end
		local W = L.pworld()
		W.L.fault.UnitHealthPercent = true
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		L.set(W, "nameplates.healthByLeft", true)
		W.L.fault.UnitHealthPercent = nil
		L.set(W, "nameplates.healthByLeft", false)
		L.set(W, "nameplates.healthByLeft", true)
		check("ms-late: and when the client accepts it later the next change of a row tries again", L.is(a.colour, L.hex("ffe6c12e")) and has(W.status(), "Health curve: works"), L.show(a.colour) .. W.status())
		-- Three plates fail after the test passed: the part stops and every plate has the game's colour.
		local V = L.pworld()
		local list = {}
		for i = 1, 4 do
			list[i] = L.plate(V, "nameplate" .. i, { friend = false, health = 0.5 })
		end
		L.set(V, "nameplates.healthByLeft", true)
		V.L.fault.UnitHealthPercent = true
		for i = 1, 3 do
			L.game(V, list[i])
		end
		local back = true
		for i = 1, 4 do
			back = back and L.is(list[i].colour, 0.2, 0.4, 0.6)
		end
		check("ms-late: a call that raises on three plates stops the part, says so, and gives every plate the game's colour", back and has(V.status(), "health curve stopped"), V.status())
		V.L.fault.UnitHealthPercent = nil
		L.game(V, list[4])
		check("ms-late: and the part stays stopped", L.is(list[4].colour, 0.2, 0.4, 0.6))
	end

	-- A health colour the client withholds goes to the bar and nowhere else.
	do
		local W = L.pworld()
		W.L.secret = true
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		L.set(W, "nameplates.healthByLeft", true)
		L.set(W, "nameplates.lowHealth", true)
		check("ms-late: a withheld colour is set on the bar as it is and a withheld alpha on the border, with no error and no violation", rawequal(a.colour[1], SECRET) and L.silent(W)
			and has(W.status(), "Health curve: works"), L.why(W))
		W.L.secret = nil
		L.game(W, a)
		check("ms-late: and a colour the client gives is used again", L.is(a.colour, L.hex("ffe6c12e")), L.show(a.colour))
		clean(W, "ms-late plate secret")
	end

	-- The low health border.
	do
		local W = L.pworld()
		local T = W.L
		local a = L.plate(W, "nameplate1", { friend = false, health = 0.5 })
		local b = L.plate(W, "nameplate2", { friend = false, health = 0.1 })
		local frames = #W.addonFrames
		L.set(W, "nameplates.lowHealth", true)
		local ha, ea = L.border(W, a)
		local hb2 = L.border(W, b)
		check("ms-late: Low health border puts a frame of the addon's over the health bar of each plate, with edges in the colour of the row", ha ~= nil and hb2 ~= nil and ea ~= nil
			and L.is(ea.color, L.hex("ffff3333")), tostring(ha) .. " " .. tostring(ea))
		check("ms-late: a plate at half health shows it at no opacity and a plate under the limit at full opacity", W.rawOf[ha].alpha == 0 and W.rawOf[hb2].alpha == 1,
			tostring(W.rawOf[ha].alpha) .. " " .. tostring(W.rawOf[hb2].alpha))
		T.health.nameplate1 = 0.19
		L.game(W, a)
		check("ms-late: the plate's own health moves the border with each call of the game", W.rawOf[ha].alpha == 1, tostring(W.rawOf[ha].alpha))
		T.health.nameplate1 = 0.2
		L.game(W, a)
		check("ms-late: at the limit it is gone again", W.rawOf[ha].alpha == 0, tostring(W.rawOf[ha].alpha))
		L.set(W, "nameplates.lowHealthAt", 30)
		T.health.nameplate1 = 0.25
		L.game(W, a)
		check("ms-late: Low health below moves the limit", W.rawOf[ha].alpha == 1, tostring(W.rawOf[ha].alpha))
		L.set(W, "nameplates.lowHealthColour", "ff00ff00")
		local _, e2 = L.border(W, a)
		check("ms-late: and the colour of the row is the colour of the edges", L.is(e2.color, 0, 1, 0), tostring(e2.color and e2.color[1]))
		check("ms-late: the colour of the bar is the game's while only the border is on", L.is(a.colour, 0.2, 0.4, 0.6) and a.sets == 0, L.show(a.colour))
		L.set(W, "nameplates.lowHealth", false)
		check("ms-late: switched off the border is hidden", W.rawOf[ha].shown == false, tostring(W.rawOf[ha].shown))
		local made = #W.addonFrames
		L.set(W, "nameplates.lowHealth", true)
		check("ms-late: and switched on again it is the same frame", #W.addonFrames == made and W.rawOf[ha].shown == true and L.border(W, a) == ha)
		clean(W, "ms-late border")
	end

	-- Unit frames.
	do
		local W = FH.ufWorld()
		local T = L.fakes(W)
		W.flush()
		local P, Tg = W.player, W.target
		local env = W.env
		local function tint(bar) return W.rawOf[bar].tint end
		local function fill(bar) return W.rawOf[W.rawOf[bar].fill] end
		local before = L.running(W)
		check("ms-late: unit frames at the default have the flat fill, a white tint, no curve and no call for health", fill(P.health).color ~= nil and L.is(tint(P.health), 1, 1, 1) and #T.calls == 0
			and T.made == 0, #T.calls .. " " .. T.made)
		T.health.player, T.health.target = 0.5, 0.25
		W.change("unitframes.healthByLeft", true)
		local f = fill(P.health)
		check("ms-late: Colour health bars by health left makes the fill an image in white", f.file == "Interface\\Buttons\\WHITE8X8" and f.color == nil and L.is(tint(P.health), 1, 1, 1)
			or (f.file ~= nil and f.color == nil), tostring(f.file) .. " " .. L.show(tint(P.health)))
		L.step(W, 1)
		check("ms-late: and one look later the frames have the colour of their health left: half on the player, between low and half on the target", L.is(tint(P.health), L.hex("ffe6c12e"))
			and L.is(tint(Tg.health), (L.hex("ffd93a30") + L.hex("ffe6c12e")) / 2, (select(2, L.hex("ffd93a30")) + select(2, L.hex("ffe6c12e"))) / 2,
				(select(3, L.hex("ffd93a30")) + select(3, L.hex("ffe6c12e"))) / 2), L.show(tint(P.health)) .. " " .. L.show(tint(Tg.health)))
		check("ms-late: the frame that does it is one of the addon's own and runs while a row is on", L.running(W) == before + 1 and has(W.status(), "Health curve: works"), L.running(W) .. " " .. before)
		T.health.player = 1
		L.step(W, 1)
		check("ms-late: more health is the colour at full health", L.is(tint(P.health), L.hex("ff2eb84d")), L.show(tint(P.health)))
		local calls = #T.calls
		L.step(W, 1, 0.04)
		check("ms-late: a frame shorter than a tenth of a second asks nothing", #T.calls == calls)
		W.change("general.healthFull", "ff112233")
		T.health.player = 1
		L.step(W, 1)
		check("ms-late: a colour changed on the Colours page is used on the next look", L.is(tint(P.health), 0x11 / 255, 0x22 / 255, 0x33 / 255), L.show(tint(P.health)))
		W.change("general.healthFull", "ff2eb84d")
		W.change("unitframes.healthByLeft", false)
		local g = fill(P.health)
		check("ms-late: switched off the fill is flat in the colour of the health row again, with a white tint", g.color ~= nil and L.is(g.color, 0.18, 0.72, 0.30) and L.is(tint(P.health), 1, 1, 1),
			tostring(g.color and L.show(g.color)) .. " " .. L.show(tint(P.health)))
		calls = #T.calls
		L.step(W, 2)
		check("ms-late: and nothing asks for health or paints after that", #T.calls == calls and L.running(W) == before, #T.calls .. " " .. calls .. " " .. L.running(W))
		W.change("unitframes.healthByLeft", true)
		L.step(W, 1)
		W.change("unitframes.flat", false)
		L.step(W, 1)
		check("ms-late: with Flat bars off the game's fill is back and the frames are left alone", fill(P.health).atlas ~= nil and L.is(tint(P.health), 1, 1, 1), L.show(tint(P.health)))
		W.change("unitframes.flat", true)
		L.step(W, 1)
		check("ms-late: and on again they have the colour", L.is(tint(P.health), L.hex("ff2eb84d")), L.show(tint(P.health)))
		W.change("unitframes.healthTexture", "Soft shade")
		check("ms-late: the bar texture of the row is the image", fill(P.health).file == "Interface\\AddOns\\FlatUI\\Media\\Soft.tga", tostring(fill(P.health).file))
		W.change("unitframes.healthTexture", "Same as the Flat UI page")
		clean(W, "ms-late unit frames")
	end

	-- A client that refuses the curve for unit frames, and a call that raises on three bars.
	do
		local W = FH.ufWorld()
		local T = L.fakes(W)
		T.fault.UnitHealthPercent = true
		W.flush()
		W.change("unitframes.healthByLeft", true)
		L.step(W, 2)
		check("ms-late: a client that refuses the curve leaves the frames with their flat fill and the status says refused", W.rawOf[W.rawOf[W.player.health].fill].color ~= nil
			and has(W.status(), "Health curve: refused") and L.silent(W), W.status() .. L.why(W))
		local V = FH.ufWorld()
		local U = L.fakes(V)
		V.flush()
		V.change("unitframes.healthByLeft", true)
		L.step(V, 1)
		U.fault.UnitHealthPercent = true
		L.step(V, 1)
		check("ms-late: a call that raises on three bars stops the part, says so, and the frames have their own colour again", has(V.status(), "health curve stopped")
			and V.rawOf[V.rawOf[V.player.health].fill].color ~= nil and L.is(V.rawOf[V.rawOf[V.player.health].fill].color, 0.18, 0.72, 0.30), V.status())
	end

	-- The personal resource display.
	do
		local W = FH.world(nil, L.fakes)
		local T = W.L
		local raw = W.rawOf[W.prd.health[1]]
		local display = W.prdInner
		T.health.player = 0.5
		check("ms-late: the resource display at the default has its tint and no curve", L.is(raw.tint, 1, 1, 1) and #T.calls == 0 and T.made == 0, #T.calls .. " " .. T.made)
		W.change("resource.healthByLeft", true)
		L.step(W, 1)
		check("ms-late: Colour health by health left tints the health bar in the colour of the health left", L.is(raw.tint, L.hex("ffe6c12e")), L.show(raw.tint))
		W.blizzard(function() W.prdFrame:UpdateHealthColor() end)
		check("ms-late: the game colours it again", L.is(raw.tint, 0.18, 0.72, 0.3), L.show(raw.tint))
		L.step(W, 1)
		check("ms-late: and the next look has the colour of the health left again", L.is(raw.tint, L.hex("ffe6c12e")), L.show(raw.tint))
		T.health.player = 1
		L.step(W, 1)
		check("ms-late: full health is the colour at full health", L.is(raw.tint, L.hex("ff2eb84d")), L.show(raw.tint))
		W.change("resource.healthOwn", true)
		W.change("resource.healthColour", "ff112233")
		L.step(W, 2)
		check("ms-late: Custom health colour does not take the bar from it", L.is(raw.tint, L.hex("ff2eb84d")), L.show(raw.tint))
		T.health.player = 0.5
		L.step(W, 1)
		W.change("resource.healthByLeft", false)
		L.step(W, 2)
		check("ms-late: and with the row off the custom colour is the bar's", L.is(raw.tint, 0x11 / 255, 0x22 / 255, 0x33 / 255), L.show(raw.tint))
		W.change("resource.healthOwn", false)
		check("ms-late: and without it the game's colour", L.is(raw.tint, 1, 1, 1) or L.is(raw.tint, 0.18, 0.72, 0.3), L.show(raw.tint))
		W.change("resource.healthByLeft", true)
		L.step(W, 1)
		W.change("resource.flat", false)
		L.step(W, 1)
		check("ms-late: with Flat fill off the bar has the colour it had before", not L.is(raw.tint, L.hex("ff2eb84d")), L.show(raw.tint))
		clean(W, "ms-late resource")
	end

	-- Cast time. The binding and the poll are the two ways the part writes the seconds; T.asked counts the durations asked for.
	function L.cworld()
		local W = newWorld()
		local T = L.fakes(W)
		W.login()
		W.flush()
		W.bars = { target = W.cast.TargetFrameSpellBar, focus = W.cast.FocusFrameSpellBar }
		return W, T
	end
	-- The text a bar's font string shows, through the first binding made (or nil).
	function L.text(W, binding)
		return binding and binding.font and W.rawOf[binding.font].text
	end
	-- A cast on a bar: the game's fields and the seconds the client reports.
	function L.cast(W, name, seconds, o)
		o = o or {}
		local inner = W.bars[name].inner
		inner.casting, inner.channeling, inner.castID = not o.channel and true or nil, o.channel and true or nil, o.id
		W.L[o.channel and "channels" or "casts"][name] = seconds
	end
	function L.endCast(W, name)
		local inner = W.bars[name].inner
		inner.casting, inner.channeling, inner.castID = nil, nil, nil
		W.L.casts[name], W.L.channels[name] = nil, nil
	end

	do
		local W, T = L.cworld()
		local before, fonts = L.running(W), #W.addonFonts
		L.cast(W, "target", 2.5)
		L.step(W, 2)
		check("ms-late: at the default no duration is asked for, no font string is made on a bar, no binding is made and no frame runs", (T.asked or 0) == 0 and #T.bindings == 0
			and #W.addonFonts == fonts and L.running(W) == before and not has(W.status(), "Cast time"), tostring(T.asked) .. " " .. #T.bindings .. " " .. #W.addonFonts .. " " .. fonts)
		W.change("castbars.ownTime", true)
		L.step(W, 1)
		local b = T.bindings[1]
		local fs = b and b.font
		local point = fs and W.rawOf[fs].points[1]
		check("ms-late: Cast time on target and focus bars gives a cast a binding on a font string at the right end of its bar, with the seconds formatter, and it is on", b ~= nil
			and b.enabled == true and b.sets == 1 and b.formatter ~= nil and b.formatter.seconds and point ~= nil and point[1] == "RIGHT" and point[2] == W.bars.target.bar,
			tostring(b) .. " " .. tostring(point and point[1]))
		check("ms-late: and /flatui status says it works", has(W.status(), "Cast time: works") and L.silent(W), W.status() .. L.why(W))
		local asked = T.asked
		L.step(W, 3)
		check("ms-late: the binding is made once and the cast is asked for once however many looks it lasts", T.asked == asked and #T.bindings == 1 and b.sets == 1, tostring(T.asked) .. " " .. asked)
		L.endCast(W, "target")
		L.step(W, 1)
		check("ms-late: when the cast ends the binding is off and the text is empty", b.enabled == false and L.text(W, b) == "", tostring(b.enabled) .. tostring(L.text(W, b)))
		L.cast(W, "target", 3, { channel = true })
		L.step(W, 1)
		check("ms-late: a channel is asked for as a channel and uses the same binding", #T.bindings == 1 and b.enabled == true and b.sets == 2 and T.asked == asked + 1,
			#T.bindings .. " " .. b.sets .. " " .. tostring(T.asked))
		L.cast(W, "target", 2, { id = "one" })
		L.step(W, 1)
		local sets = b.sets
		L.cast(W, "target", 1.5, { id = "two" })
		L.step(W, 1)
		check("ms-late: a new cast in place of the one on the bar starts again", b.sets == sets + 1 and b.enabled == true, b.sets .. " " .. sets)
		L.cast(W, "focus", 4)
		L.step(W, 1)
		check("ms-late: the focus bar has a binding of its own", #T.bindings == 2 and T.bindings[2].enabled == true and T.bindings[2].font ~= b.font, #T.bindings)
		W.bars.target.inner.casting = SECRET
		W.bars.target.inner.channeling = SECRET
		L.step(W, 1)
		check("ms-late: a cast field the client withholds is no cast, and nothing raises", b.enabled == false and L.silent(W), L.why(W))
		L.endCast(W, "target")
		L.endCast(W, "focus")
		L.cast(W, "target", 2)
		L.step(W, 1)
		W.change("castbars.ownTime", false)
		L.step(W, 1)
		check("ms-late: with the row off the text is cleared and the frame stops", b.enabled == false and L.text(W, b) == "" and L.running(W) == before, tostring(L.running(W)) .. " " .. before)
		W.change("castbars.ownTime", true)
		L.step(W, 1)
		W.change("castbars.enabled", false)
		L.step(W, 1)
		check("ms-late: and with the Cast bars page off", b.enabled == false and L.running(W) == before, tostring(L.running(W)))
		clean(W, "ms-late cast time")
	end

	-- The second way: the poll, when the binding is refused.
	do
		local W, T = L.cworld()
		W.change("castbars.ownTime", true)
		T.fault.SetDuration = true
		L.cast(W, "target", 2.5)
		L.step(W, 1)
		local fs = T.bindings[1] and T.bindings[1].font
		local text = W.addonFonts[#W.addonFonts]
		check("ms-late: a binding that raises leaves the poll, which writes the seconds left to a tenth", text.text == "2.5" and has(W.status(), "Cast time: works") and L.silent(W), tostring(text.text) .. L.why(W))
		T.casts.target = 1.25
		L.step(W, 1)
		check("ms-late: and on each look", text.text == "1.2" or text.text == "1.3", tostring(text.text))
		L.endCast(W, "target")
		L.step(W, 1)
		check("ms-late: and is empty when the cast ends", text.text == "", tostring(text.text))
		local V, U = L.cworld()
		V.change("castbars.ownTime", true)
		U.fault.Binding = true
		L.cast(V, "target", 2)
		L.step(V, 1)
		check("ms-late: a binding that cannot be made does the same", V.addonFonts[#V.addonFonts].text == "2.0", tostring(V.addonFonts[#V.addonFonts].text))
		T.fault.SetDuration = true
		T.fault.Remaining = true
		L.endCast(W, "target")
		L.step(W, 1)
		L.cast(W, "target", 2)
		L.step(W, 4)
		check("ms-late: a cast that both ways fail on is counted once however many looks it lasts", has(W.status(), "Cast time: works") and not has(W.status(), "refused"), W.status())
		L.endCast(W, "target")
		L.step(W, 1)
		for i = 1, 2 do
			L.cast(W, "target", 2)
			L.step(W, 2)
			L.endCast(W, "target")
			L.step(W, 1)
		end
		local asked = T.asked
		check("ms-late: three casts both ways fail on stop the part for the session, and the status says so", has(W.status(), "Cast time: refused") and text.text == "", W.status())
		L.cast(W, "target", 2)
		L.step(W, 3)
		check("ms-late: after that no duration is asked for and no frame runs", T.asked == asked and L.running(W) == 0, tostring(T.asked) .. " " .. asked .. " " .. L.running(W))
		check("ms-late cast poll: no violations or errors, and one line to the chat for the stop", #W.violations == 0 and #W.errors == 0 and #W.out == 1 and has(W.out[1], "Cast time stopped"),
			L.why(W))
	end

	-- A cast that fails and then works, a duration the client does not give, and a call that raises.
	do
		local W, T = L.cworld()
		W.change("castbars.ownTime", true)
		T.fault.SetDuration, T.fault.Remaining = true, true
		L.cast(W, "target", 2)
		L.step(W, 2)
		T.fault.SetDuration, T.fault.Remaining = nil, nil
		L.endCast(W, "target")
		L.step(W, 1)
		L.cast(W, "target", 2)
		L.step(W, 1)
		check("ms-late: a cast that failed does not stop the next one", T.bindings[1] and T.bindings[1].enabled == true and has(W.status(), "Cast time: works"), W.status())
		local V, U = L.cworld()
		V.change("castbars.ownTime", true)
		V.bars.target.inner.casting = true
		L.step(V, 5)
		check("ms-late: a cast the client gives no duration for is no failure and is asked for again", has(V.status(), "Cast time: no cast seen yet") and U.asked == 5 and L.silent(V),
			V.status() .. tostring(U.asked))
		U.fault.UnitCastingDuration = true
		U.casts.target = 2
		L.endCast(V, "target")
		for i = 1, 3 do
			L.cast(V, "target", 2)
			L.step(V, 2)
			L.endCast(V, "target")
			L.step(V, 1)
		end
		check("ms-late: a duration call that raises on three casts stops the part", has(V.status(), "Cast time: refused") and #V.violations == 0 and #V.errors == 0, (V.status():gsub(string.char(10), "|")))
	end

	-- Cast time on nameplates.
	do
		local W = L.pworld()
		local T = W.L
		local a = L.plate(W, "nameplate1", { friend = false })
		local bar = W.rawOf[a.castBar]
		local fonts = #W.addonFonts
		bar.casting = true
		T.casts.nameplate1 = 2
		L.step(W, 2)
		check("ms-late: at the default nameplate cast bars have no font string and no duration is asked for", #W.addonFonts == fonts and #T.bindings == 0, #W.addonFonts .. " " .. fonts)
		L.set(W, "nameplates.castTime", true)
		check("ms-late: the font string is made in the plate's cast bar as soon as the row is on", #W.addonFonts == fonts + 1, #W.addonFonts .. " " .. fonts)
		L.step(W, 1)
		local b = T.bindings[1]
		local point = b and b.font and W.rawOf[b.font].points[1]
		check("ms-late: Cast time on a plate gives its cast a binding at the right end of the plate's cast bar", b ~= nil and b.enabled == true and point ~= nil and point[1] == "RIGHT"
			and point[2] == a.castBar, tostring(b))
		a.inner.unit = nil
		W.units.nameplate1 = nil
		W.fire("NAME_PLATE_UNIT_REMOVED", "nameplate1")
		W.flush()
		check("ms-late: a plate the game takes back has its text cleared", b.enabled == false and L.text(W, b) == "", tostring(b.enabled))
		bar.casting = nil
		a.inner.unit = "nameplate1"
		W.units.nameplate1 = a
		W.fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
		W.flush()
		L.step(W, 1)
		check("ms-late: the plate that comes back with no cast shows nothing", b.enabled == false and L.silent(W), L.why(W))
		bar.casting = true
		L.step(W, 1)
		check("ms-late: and shows the next one", b.enabled == true, tostring(b.enabled))
		L.set(W, "nameplates.friendly", false)
		local c = L.plate(W, "nameplate2", { friend = true })
		W.rawOf[c.castBar].casting = true
		T.casts.nameplate2 = 3
		L.step(W, 1)
		check("ms-late: a friendly plate that is not restyled has none", #T.bindings == 1, #T.bindings)
		L.set(W, "nameplates.castTime", false)
		L.step(W, 1)
		check("ms-late: switched off the text is cleared and the frame stops", b.enabled == false and L.running(W) == 0, L.running(W))
		clean(W, "ms-late plate cast time")
	end

	-- Unit frames that are off, whose unit is gone, or that follow the Flat UI page's texture.
	function L.count(T, unit)
		local n = 0
		for _, called in ipairs(T.calls) do
			if called == unit then
				n = n + 1
			end
		end
		return n
	end
	do
		local W = FH.ufWorld()
		local T = L.fakes(W)
		W.flush()
		local P, Tg = W.player, W.target
		local function tint(bar) return W.rawOf[bar].tint end
		T.health.player, T.health.target = 0.5, 0.25
		W.change("unitframes.healthByLeft", true)
		L.step(W, 1)
		T.exists.target = false
		W.rawOf[Tg.health].tint = { 1, 1, 1, 1 }
		local asked = L.count(T, "target")
		L.step(W, 2)
		check("ms-late: a frame whose unit is not there is not asked about, and the one that is there is", L.count(T, "target") == asked and L.is(tint(Tg.health), 1, 1, 1)
			and L.is(tint(P.health), L.hex("ffe6c12e")), L.count(T, "target") .. " " .. asked)
		T.exists.target = nil
		W.ns.Set("unitframes.player", false)
		W.flush()
		local before = L.count(T, "player")
		L.step(W, 2)
		check("ms-late: a frame switched off on the Unit frames page is given back and not asked about, and the others still have the colour", L.count(T, "player") == before
			and L.is(tint(P.health), 1, 1, 1) and L.is(tint(Tg.health), (L.hex("ffd93a30") + L.hex("ffe6c12e")) / 2, (select(2, L.hex("ffd93a30")) + select(2, L.hex("ffe6c12e"))) / 2,
				(select(3, L.hex("ffd93a30")) + select(3, L.hex("ffe6c12e"))) / 2), L.show(tint(P.health)) .. " " .. L.show(tint(Tg.health)))
		W.ns.Set("unitframes.player", true)
		W.flush()
		W.ns.Set("unitframes.enabled", false)
		W.flush()
		local all = #T.calls
		L.step(W, 2)
		check("ms-late: with the Unit frames page off nothing is asked and the bars are the game's", #T.calls == all and L.is(tint(P.health), 1, 1, 1) and L.is(tint(Tg.health), 1, 1, 1),
			#T.calls .. " " .. all .. " " .. L.show(tint(Tg.health)))
		clean(W, "ms-late unit frames off")
	end
	do
		local W = FH.ufWorld()
		local T = L.fakes(W)
		W.flush()
		local P = W.player
		T.health.player = 0.5
		W.ns.Set("general.barTexture", "soft")
		W.ns.Set("unitframes.healthColour", "ffffffff")
		W.flush()
		W.ns.Set("unitframes.healthByLeft", true)
		W.flush()
		L.step(W, 1)
		local f = W.rawOf[W.rawOf[P.health].fill]
		check("ms-late: the bar texture of the Flat UI page is the image, tinted by the health left", f.file == "Interface\\AddOns\\FlatUI\\Media\\Soft.tga" and L.is(W.rawOf[P.health].tint, L.hex("ffe6c12e")),
			tostring(f.file) .. " " .. L.show(W.rawOf[P.health].tint))
		W.ns.Set("unitframes.healthByLeft", false)
		W.flush()
		check("ms-late: switched off with a white health colour and the same texture the tint is white again", L.is(W.rawOf[P.health].tint, 1, 1, 1), L.show(W.rawOf[P.health].tint))
		clean(W, "ms-late unit frames texture")
	end

	-- The resource display: what the game had is given back, a refusal is tried again, and three failed looks stop the part.
	do
		local W = FH.world(nil, L.fakes)
		local T = W.L
		local raw = W.rawOf[W.prd.health[1]]
		T.health.player = 0.5
		local game = { raw.tint[1], raw.tint[2], raw.tint[3] }
		W.change("resource.healthByLeft", true)
		L.step(W, 1)
		check("ms-late: the resource bar has the colour of the health left", L.is(raw.tint, L.hex("ffe6c12e")), L.show(raw.tint))
		W.change("resource.healthByLeft", false)
		L.step(W, 1)
		check("ms-late: switched off it has the colour it had before the first paint", L.is(raw.tint, game[1], game[2], game[3]), L.show(raw.tint))
		local asked = #T.calls
		L.step(W, 3)
		check("ms-late: and nothing asks for health after that", #T.calls == asked and not has(W.status(), "Health curve"), #T.calls .. " " .. asked)
		W.change("resource.healthByLeft", true)
		L.step(W, 1)
		T.fault.UnitHealthPercent = true
		L.step(W, 3)
		check("ms-late: three failed looks stop the part, say so, and give the bar its colour back", has(W.status(), "health curve stopped") and L.is(raw.tint, game[1], game[2], game[3]), L.show(raw.tint))
		check("ms-late resource stop: no violations or errors, and one line to the chat for the stop", #W.violations == 0 and #W.errors == 0 and #W.out == 1 and has(W.out[1], "health curve stopped"),
			L.why(W))
		local V = FH.world(nil, function(X) L.fakes(X).fault.UnitHealthPercent = true end)
		local vraw = V.rawOf[V.prd.health[1]]
		V.change("resource.healthByLeft", true)
		L.step(V, 2)
		check("ms-late: a client that refuses the curve leaves the resource bar alone and the status says refused", L.is(vraw.tint, 1, 1, 1) and has(V.status(), "Health curve: refused") and L.silent(V),
			V.status() .. L.why(V))
		V.L.fault.UnitHealthPercent = nil
		V.change("resource.healthByLeft", false)
		V.change("resource.healthByLeft", true)
		V.L.health.player = 0.5
		L.step(V, 1)
		check("ms-late: and when the client accepts it later the next change of the row tries again", L.is(vraw.tint, L.hex("ffe6c12e")), L.show(vraw.tint))
	end

	-- A channel that takes the place of a cast on the bar.
	do
		local W, T = L.cworld()
		W.change("castbars.ownTime", true)
		L.cast(W, "target", 2)
		L.step(W, 1)
		local b = T.bindings[1]
		local sets, asked = b.sets, T.asked
		W.bars.target.inner.casting, W.bars.target.inner.channeling = nil, true
		T.channels.target = 4
		L.step(W, 1)
		check("ms-late: a channel in place of a cast is asked for as a channel and starts again", b.sets == sets + 1 and T.asked == asked + 1 and b.enabled == true, b.sets .. " " .. sets)
	end
end
-- >>> ms-late (end)
-- >>> hkbars (begin)
-- hkbars: the personal resource display and the swing timers are followed with no hook on a method of a frame. Scripts hooked with HookScript, events and
-- the start and end of Edit Mode say when the game has changed them; each pass runs on the next frame, and the setting still does what it did.
do
	local HB = {}
	function HB.registry(W)
		local registry = { callbacks = {} }
		function registry:RegisterCallback(event, func, owner)
			registry.callbacks[event] = registry.callbacks[event] or {}
			table.insert(registry.callbacks[event], { owner = owner, func = func })
			return owner
		end
		function registry:TriggerEvent(event, ...)
			for _, entry in ipairs(registry.callbacks[event] or {}) do
				local ok, err = pcall(entry.func, entry.owner, ...)
				if not ok then
					W.errors[#W.errors + 1] = tostring(err)
				end
			end
		end
		W.env.EventRegistry = registry
		return registry
	end
	-- The methods of a swing timer as the game has them (Blizzard_SwingTimer.lua:257-268, 302-346, 408-431), with the registry of Edit Mode.
	function HB.dress(W)
		W.hbRegistry = HB.registry(W)
		-- Frame:RegisterUnitEvent for the frames of the addon (SimpleFrameAPIDocumentation.lua), which this world does not give them.
		local create = W.env.CreateFrame
		W.env.CreateFrame = function(...)
			local frame = create(...)
			if type(frame) == "table" and frame.RegisterUnitEvent == nil then
				frame.RegisterUnitEvent = function(self, event) self:RegisterEvent(event) return true end
			end
			return frame
		end
		W.hbSwing = {}
		for _, name in ipairs(FH.SWING) do
			local s = W.fills.swing[name]
			local typeLabel, typeRaw = W.Rr(s.bar, nil, { kind = "FontString" })
			local timeLabel, timeRaw = W.Rr(s.bar, nil, { kind = "FontString" })
			typeRaw.textColour, timeRaw.textColour = { 1, 1, 1, 1 }, { 1, 1, 1, 1 }
			s.barRaw.TypeLabel, s.barRaw.TimeLabel = typeLabel, timeLabel
			s.barRaw.reverse = false
			s.barRaw.SetReverseFill = function(_, v) s.barRaw.reverse = v end
			s.barRaw.GetReverseFill = function() return s.barRaw.reverse end
			local inner = s.inner
			inner.ApplyRangePresentation = function()
				s.bar:SetAlpha(inner.isOutOfRange == true and 0.4 or 1)
			end
			inner.ClearSwingTimer = function()
				inner.swingEndTime = nil
				s.pip:Hide()
			end
			inner.ResetSwingTimer = function(_, duration)
				inner.swingEndTime = W.now + duration
				s.pip:Show()
			end
			inner.InitializeBarPresentation = function()
				s.pipRaw.points = { { "RIGHT", s.fill, "RIGHT", 0, 0 } }
			end
			W.hbSwing[name] = { s = s, timer = s.timer, inner = inner }
		end
	end
	function HB.wrapped(W, object, names)
		for _, name in ipairs(names) do
			if INSTHOOK.wrapped(W, object, name) then
				return true
			end
		end
		return false
	end
	-- With taintLog on, the box that offers to turn it off makes a frame the simulated client does not take arguments for; that is the only violation let through.
	function HB.quiet(W)
		for _, violation in ipairs(W.violations) do
			if violation ~= "CreateFrame arguments" then
				return false
			end
		end
		return #W.errors == 0
	end
	function HB.tail(W, event, ...)
		W.hbRegistry:TriggerEvent(event, ...)
		W.tick()
	end
	function HB.hears(W, event)
		for _, frame in ipairs(W.eventFrames) do
			if frame.events[event] == true then
				return true
			end
		end
		return false
	end

	for _, value in ipairs({ "0", "2" }) do
		local W = newWorld()
		W.hbRegistry = HB.registry(W)
		W.cvars.taintLog = value
		W.prdInner.hasBeenSetup = true
		W.login()
		local display = W.prdFrame
		check("hkbars: resource display, taintLog " .. value .. ": no method of the display is hooked", W.hooks == 0 and not HB.wrapped(W, display, { "UpdatePowerBarAnchor", "UpdateAdditionalBarAnchors" }), W.hooks)
		check("hkbars: resource display, taintLog " .. value .. ": the scripts of the display, the alternate bar and the class frame container are followed once each",
			#W.prdHooks.display.OnShow == 1 and #W.prdHooks.alt.OnShow == 1 and #W.prdHooks.alt.OnHide == 1 and #W.prdHooks.class.OnShow == 1 and #W.prdHooks.class.OnHide == 1)
		check("hkbars: resource display, taintLog " .. value .. ": at login the bars are joined", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
		W.prdPadding = 12
		W.blizzard(function()
			display:UpdatePowerBarAnchor()
			display:UpdateAdditionalBarAnchors()
		end)
		check("hkbars: resource display, taintLog " .. value .. ": the game's call is not followed by anything", near(W.gap("power"), 12) and near(W.gap("alt"), 12), W.gap("power"))
		W.prdScript("alt", "OnShow")
		check("hkbars: resource display, taintLog " .. value .. ": the script of the bar changes nothing before the next frame", near(W.gap("power"), 12) and #W.errors == 0)
		W.tick()
		check("hkbars: resource display, taintLog " .. value .. ": on the next frame the bars are joined again", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1))
		W.change("resource.join", false)
		check("hkbars: resource display, taintLog " .. value .. ": Join bars off gives the game's gap", near(W.gap("power"), 12) and near(W.gap("alt"), 12))
		W.change("resource.join", true)
		W.prdPadding = 4
		W.blizzard(function()
			display:UpdatePowerBarAnchor()
			display:UpdateAdditionalBarAnchors()
		end)
		W.prdScript("class", "OnHide")
		W.prdScript("display", "OnShow")
		W.tick()
		check("hkbars: resource display, taintLog " .. value .. ": the class frame container and the display scripts join them too", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1) and #W.timers == 0)
		-- Edit Mode: its settings change with no event, so the bars are looked at every frame while it is open.
		HB.tail(W, "EditMode.Enter")
		check("hkbars: resource display, taintLog " .. value .. ": Edit Mode open: a frame runs", FH.polling(W))
		W.prdPadding = 9
		W.blizzard(function()
			display:UpdatePowerBarAnchor()
			display:UpdateAdditionalBarAnchors()
		end)
		W.frame(1)
		check("hkbars: resource display, taintLog " .. value .. ": Edit Mode open: a change of padding is joined on the next frame", near(W.gapPixels("power"), 1) and near(W.gapPixels("alt"), 1), W.gap("power"))
		HB.tail(W, "EditMode.Exit")
		check("hkbars: resource display, taintLog " .. value .. ": Edit Mode closed: nothing runs every frame", not FH.polling(W))
		W.prdPadding = 7
		W.blizzard(function() display:UpdatePowerBarAnchor() end)
		HB.tail(W, "EditMode.RefreshPersonalResourceDisplay", true)
		check("hkbars: resource display, taintLog " .. value .. ": the display shown in Edit Mode is looked at", near(W.gapPixels("power"), 1))
		check("hkbars: resource display, taintLog " .. value .. ": nothing was hooked on the way", W.hooks == 0 and HB.quiet(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end

	do
		-- The game's Setup sets scripts on the alternate bar and the class frame container, once, which clears a hook made before it.
		local W = newWorld()
		W.hbRegistry = HB.registry(W)
		W.login()
		check("hkbars: resource display, set up late: the two bars are not hooked before the game's Setup", #(W.prdHooks.alt.OnShow or {}) == 0 and #(W.prdHooks.class.OnShow or {}) == 0)
		W.prdInner.hasBeenSetup = true
		W.prdScript("display", "OnShow")
		W.tick()
		check("hkbars: resource display, set up late: after Setup the pass hooks them once each", #W.prdHooks.alt.OnShow == 1 and #W.prdHooks.alt.OnHide == 1 and #W.prdHooks.class.OnShow == 1 and #W.prdHooks.class.OnHide == 1)
		W.prdScript("display", "OnShow")
		W.tick()
		check("hkbars: resource display, set up late: and not again", #W.prdHooks.alt.OnShow == 1 and W.hooks == 0 and HB.quiet(W))
	end

	for _, value in ipairs({ "0", "2" }) do
		local options = { ["castbars.flat"] = false, ["swing.rangeAlpha"] = 70, ["swing.idle"] = "hide", ["swing.reverse"] = true }
		local base = FH.world({ saved = { options = { ["castbars.flat"] = false, ["swing.idle"] = "show" } } }, HB.dress)
		local W = FH.world({ saved = { options = options } }, function(Y)
			HB.dress(Y)
			Y.cvars.taintLog = value
		end)
		local m = W.hbSwing[FH.SWING[1]]
		check("hkbars: swing timers, taintLog " .. value .. ": no method of a timer is hooked", W.hooks == base.hooks and not HB.wrapped(W, m.timer, { "ApplyRangePresentation", "ClearSwingTimer", "ResetSwingTimer", "InitializeBarPresentation" }), W.hooks - base.hooks)
		check("hkbars: swing timers, taintLog " .. value .. ": the events are heard for a setting that is not the game's, and not at Always", HB.hears(W, "PLAYER_SWING") and HB.hears(W, "PLAYER_SWING_RANGE_UPDATE")
			and not HB.hears(base, "PLAYER_SWING") and not HB.hears(base, "PLAYER_SWING_RANGE_UPDATE") and not FH.polling(W))
		-- Range.
		W.blizzard(function() m.inner.isOutOfRange = true m.timer:ApplyRangePresentation() end)
		check("hkbars: swing timers, taintLog " .. value .. ": the game's call alone leaves its own opacity", near(m.s.barRaw.alpha, 0.4), m.s.barRaw.alpha)
		W.fire("PLAYER_SWING_RANGE_UPDATE", 0, false, true)
		check("hkbars: swing timers, taintLog " .. value .. ": the event alone changes nothing before the next frame", near(m.s.barRaw.alpha, 0.4))
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": on the next frame the opacity is the row's", near(m.s.barRaw.alpha, 0.7), m.s.barRaw.alpha)
		W.change("swing.rangeAlpha", 40)
		check("hkbars: swing timers, taintLog " .. value .. ": 40 percent is the game's own value again", near(m.s.barRaw.alpha, 0.4))
		W.change("swing.rangeAlpha", 70)
		-- Combat starts or ends and the game sets the range again (Blizzard_SwingTimer.lua:146-147, 270-274, 398-423).
		W.blizzard(function() m.inner.isOutOfRange = false m.timer:ApplyRangePresentation() end)
		W.tick()
		W.blizzard(function() m.inner.isOutOfRange = true m.timer:ApplyRangePresentation() end)
		check("hkbars: swing timers, taintLog " .. value .. ": combat change: the game's call alone leaves its own opacity", near(m.s.barRaw.alpha, 0.4), m.s.barRaw.alpha)
		W.fire("PLAYER_IN_COMBAT_CHANGED", true)
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": combat change: on the next frame the opacity is the row's", near(m.s.barRaw.alpha, 0.7), m.s.barRaw.alpha)
		W.blizzard(function() m.inner.isOutOfRange = true m.timer:ApplyRangePresentation() end)
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": attack speed is heard for the player", HB.hears(W, "UNIT_ATTACK_SPEED") and not HB.hears(base, "UNIT_ATTACK_SPEED"))
		-- Idle: the end of a swing has no event, a frame that looks sees it.
		W.blizzard(function() m.timer:ResetSwingTimer(2) end)
		W.fire("PLAYER_SWING", 2, 0)
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": a swing starts: the bar is shown and a frame looks for its end", m.s.barRaw.shown == true and FH.polling(W))
		W.blizzard(function() m.timer:ClearSwingTimer() end)
		W.frame(1)
		check("hkbars: swing timers, taintLog " .. value .. ": the swing ends: the bar is hidden on the next frame", m.s.barRaw.shown == false)
		check("hkbars: swing timers, taintLog " .. value .. ": and nothing runs every frame any more", not FH.polling(W))
		W.blizzard(function() m.timer:ResetSwingTimer(2) end)
		W.fire("PLAYER_SWING", 2, 0)
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": the next swing shows it again", m.s.barRaw.shown == true)
		W.blizzard(function() m.timer:ClearSwingTimer() end)
		W.frame(1)
		-- Direction: the game's own anchor again.
		W.blizzard(function() m.timer:InitializeBarPresentation() end)
		W.fire("WEAPON_SLOT_CHANGED")
		W.tick()
		check("hkbars: swing timers, taintLog " .. value .. ": the direction stays after the game anchors the spark again", m.s.pipRaw.points[1][1] == "LEFT" and m.s.barRaw.reverse == true)
		-- Edit Mode: the swing timer checkbox changes the timers with no event.
		HB.tail(W, "EditMode.Enter")
		check("hkbars: swing timers, taintLog " .. value .. ": Edit Mode open: a frame runs", FH.polling(W))
		m.inner.isInEditMode = true
		W.blizzard(function() m.timer:ApplyRangePresentation() end)
		W.frame(1)
		check("hkbars: swing timers, taintLog " .. value .. ": Edit Mode open: a timer in Edit Mode keeps the game's opacity", near(m.s.barRaw.alpha, 0.4), m.s.barRaw.alpha)
		m.inner.isInEditMode = false
		W.blizzard(function() m.inner.isOutOfRange = true m.timer:ApplyRangePresentation() end)
		W.frame(1)
		check("hkbars: swing timers, taintLog " .. value .. ": Edit Mode open: out of range after the checkbox is cleared it has the row's opacity", near(m.s.barRaw.alpha, 0.7), m.s.barRaw.alpha)
		HB.tail(W, "EditMode.Exit")
		check("hkbars: swing timers, taintLog " .. value .. ": Edit Mode closed: nothing runs every frame", not FH.polling(W))
		W.change("swing.enabled", false)
		check("hkbars: swing timers, taintLog " .. value .. ": the module off gives the game's look back", near(m.s.barRaw.alpha, 0.4) and m.s.barRaw.shown == true)
		check("hkbars: swing timers, taintLog " .. value .. ": nothing was hooked on the way", W.hooks == base.hooks and HB.quiet(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end
end
-- >>> hkbars (end)

-- >>> hkwin (begin)
-- hkwin: the windows module follows the game without hooking a method of a Blizzard frame, with taintLog 0 and 2. Scripts are followed with HookScript, the
-- game's own functions and registries and its events are listened to, and each pass runs a frame after the call, never inside the game's pass.
do
	local HK = {}
	-- The functions stored on frames and regions that are the wrapper the simulated hooksecurefunc makes: a hook written on a Blizzard frame.
	function HK.fields(W)
		local out = {}
		for _, r in pairs(W.rawOf) do
			if type(r) == "table" then
				for key, value in pairs(r) do
					if type(value) == "function" and W.wrappers and W.wrappers[value] then
						out[#out + 1] = tostring(r.fname) .. "." .. tostring(key)
					end
				end
			end
		end
		table.sort(out)
		return table.concat(out, ",")
	end
	function HK.world(value, extra, options)
		local W = newWorld({ windows = extra, saved = { options = options or {} } })
		W.cvars.taintLog = value
		if value ~= "0" then
			-- The reminder box of taintLog is a named frame with buttons of the addon's, which this simulated world does not allow.
			W.ns.TaintReminder = function() end
		end
		return W
	end
	function HK.up(W)
		W.login()
		W.flush()
		return W, W.win.names
	end
	-- Frames the game makes after login.
	function HK.made(W, make)
		local was = W.group
		W.group = "windows"
		local made = { make() }
		W.group = was
		W.seal()
		return unpack(made)
	end

	for _, value in ipairs({ "0", "2" }) do

		-- Bags, the bank, the character window and its tabs.
		do
			local W, n = HK.up(HK.world(value, { second = true }))
			local cf = n.CharacterFrame
			check("hkwin: taintLog " .. value .. ": the windows are styled, their scripts are followed, and no frame has a hook of the addon's", (W.scriptHooks or 0) > 0 and HK.fields(W) == "" and W.state(cf) == "SB", HK.fields(W))
			local function marked(name) return wtints(W, n[name], "OVERLAY")[1].shown end
			W.blizzard(function() cf:SetSelectedModeTabByFrame(3) end)
			W.fireScript(n.CharacterFrameModeTab3, "OnMouseUp")
			check("hkwin: taintLog " .. value .. ": a mode tab the game chooses is not marked before the next frame", marked("CharacterFrameModeTab1") and not marked("CharacterFrameModeTab3"))
			W.flush()
			check("hkwin: taintLog " .. value .. ": and is marked on the next frame, and the tab that was left is not", marked("CharacterFrameModeTab3") and not marked("CharacterFrameModeTab1"))
			local icon = wraw(W, n.CharacterFrameModeTab1).Icon
			W.blizzard(function() cf:UpdateCharacterModeTabPortrait() end)
			W.fire("PORTRAITS_UPDATED")
			check("hkwin: taintLog " .. value .. ": the portrait the game draws is cropped again not before the next frame", wtc(W, icon) == "0.03125,0.96875,0.03125,0.96875", wtc(W, icon))
			W.flush()
			check("hkwin: taintLog " .. value .. ": and is cropped on the next frame", wtc(W, icon) == "0.10625,0.89375,0.10625,0.89375", wtc(W, icon))
			W.blizzard(function() cf:UpdateCharacterModeTabPortrait() end)
			W.fire("UNIT_PORTRAIT_UPDATE", "player")
			W.flush()
			check("hkwin: taintLog " .. value .. ": the unit portrait event of the player does the same", wtc(W, icon) == "0.10625,0.89375,0.10625,0.89375", wtc(W, icon))
			W.blizzard(function() cf:UpdateCharacterModeTabPortrait() end)
			W.fire("UNIT_PORTRAIT_UPDATE", "target")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and the portrait of another unit does not", wtc(W, icon) == "0.03125,0.96875,0.03125,0.96875", wtc(W, icon))

			local toggle = n.CharacterFrameRightPaneToggleButton
			check("hkwin: taintLog " .. value .. ": the pane toggle points left while the pane is shown", wsegments(wlines(W, toggle, "OVERLAY")) == LEFT_SHAPE)
			W.blizzard(function() cf:SetRightPaneCollapsed(true) end)
			local paneIcon = wraw(W, n.CharacterFrameModeTab2.Icon)
			check("hkwin: taintLog " .. value .. ": the side tab icons are 50 inside the game's call", paneIcon.width == 50, paneIcon.width)
			check("hkwin: taintLog " .. value .. ": collapsing the pane leaves the chevron alone inside the game's call", wsegments(wlines(W, toggle, "OVERLAY")) == LEFT_SHAPE)
			W.flush()
			check("hkwin: taintLog " .. value .. ": and it points right on the next frame", wsegments(wlines(W, toggle, "OVERLAY")) == RIGHT_SHAPE)
			check("hkwin: taintLog " .. value .. ": and the side tab icons are 30 on the next frame", paneIcon.width == 30, paneIcon.width)
			W.blizzard(function() cf:SetRightPaneCollapsed(false) end)
			W.flush()
			check("hkwin: taintLog " .. value .. ": and left again when the pane is back", wsegments(wlines(W, toggle, "OVERLAY")) == LEFT_SHAPE)

			local bag = n.ContainerFrame1
			local later = HK.made(W, function() return W.win.addBagSlot(bag, 2) end)
			W.blizzard(function() W.env.ContainerFrame_UpdateAll() end)
			check("hkwin: taintLog " .. value .. ": a bag slot the game made is not styled inside the game's update", W.state(later) == ".")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and is styled on the next frame", W.state(later) == "SB")
			local third = HK.made(W, function() return W.win.addBagSlot(bag, 3) end)
			W.blizzard(function() W.env.ContainerFrame_GenerateFrame(bag) end)
			W.flush()
			check("hkwin: taintLog " .. value .. ": a bag the game opens is looked at on the next frame as well", W.state(third) == "SB")
			-- BAG_UPDATE and BAG_NEW_ITEMS_UPDATED update a bag without ContainerFrame_UpdateAll or ContainerFrame_GenerateFrame (ContainerFrame.lua:597-612).
			local fourth = HK.made(W, function() return W.win.addBagSlot(bag, 4) end)
			W.fire("BAG_UPDATE", 1)
			W.flush()
			check("hkwin: taintLog " .. value .. ": a bag slot made by BAG_UPDATE alone is not styled by that event", W.state(fourth) == ".")
			W.fire("BAG_UPDATE_DELAYED")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and is styled on the frame after BAG_UPDATE_DELAYED", W.state(fourth) == "SB")
			local fifth = HK.made(W, function() return W.win.addBagSlot(bag, 5) end)
			W.fire("BAG_NEW_ITEMS_UPDATED")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and after BAG_NEW_ITEMS_UPDATED", W.state(fifth) == "SB")
			-- A mode tab is a Frame with no GetChecked: its tint follows the SelectedTexture.
			check("hkwin: taintLog " .. value .. ": a mode tab has no GetChecked and no OnClick, as the template", wraw(W, n.CharacterFrameModeTab1).GetChecked == nil)

			local panel = wraw(W, n.BankFrame).BankPanel
			local slot = HK.made(W, function() return W.win.itemButton(panel, nil, "HkwinBankSlot") end)
			W.blizzard(function() panel:GenerateItemSlotsForSelectedTab() end)
			check("hkwin: taintLog " .. value .. ": a bank slot the game made is not styled inside the game's page", W.state(slot) == ".")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and is styled on the next frame", W.state(slot) == "SB")
			local tab = HK.made(W, function() return W.win.sideTab(n.BankFrame, nil, nil, 1, "Interface/ICONS/INV_SideTab_Bank_c60") end)
			W.blizzard(function() tab:SetChecked(true) end)
			W.win.bankPage()
			check("hkwin: taintLog " .. value .. ": a bank page tab has its box after the page is announced", W.state(wraw(W, tab).Icon) == "SB")
			local second = HK.made(W, function() return W.win.sideTab(n.BankFrame, nil, nil, 2, "Interface/ICONS/INV_SideTab_Bank_c60") end)
			W.fire("BANK_TABS_CHANGED", 1)
			W.flush()
			check("hkwin: taintLog " .. value .. ": a bank page tab the game made when the tabs changed has its box after the event", W.state(wraw(W, second).Icon) == "SB")
			check("hkwin: taintLog " .. value .. ": no frame has a hook of the addon's after the windows were used", HK.fields(W) == "" and #W.violations == 0 and #W.errors == 0, HK.fields(W) .. table.concat(W.violations, "|"))
		end

		-- The title colour of a window the game colours again.
		do
			local W = HK.world(value, { second = true }, { ["windows.titleOwn"] = true, ["windows.titleColour"] = "ff336699" })
			local frame = W.win.names.CharacterFrame
			wraw(W, frame).SetTitleColor = function(self, colour) self.TitleContainer.TitleText:SetTextColor(colour[1], colour[2], colour[3], 1) end
			HK.up(W)
			local title = wraw(W, wraw(W, wraw(W, frame).TitleContainer).TitleText)
			local function colour()
				local c = title.textColour or { 1, 1, 1 }
				return string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3])
			end
			check("hkwin: taintLog " .. value .. ": an own title colour is set, and SetTitleColor of the window is not hooked", colour() == "0.20,0.40,0.60" and HK.fields(W) == "", colour() .. HK.fields(W))
			W.blizzard(function() frame:SetTitleColor({ 1, 1, 1 }) end)
			check("hkwin: taintLog " .. value .. ": the game's colour stays inside its own call", colour() == "1.00,1.00,1.00", colour())
			W.fireScript(frame, "OnShow")
			W.flush()
			check("hkwin: taintLog " .. value .. ": and the own colour is back on the next frame after the window is shown", colour() == "0.20,0.40,0.60", colour())
			W.blizzard(function() frame:SetTitleColor({ 1, 1, 1 }) end)
			W.fire("UNIT_NAME_UPDATE", "player")
			W.flush()
			check("hkwin: taintLog " .. value .. ": the name event of the player does the same", colour() == "0.20,0.40,0.60", colour())
			W.change("windows.titleOwn", false)
			W.blizzard(function() frame:SetTitleColor({ 0.5, 0.5, 0.5 }) end)
			W.fireScript(frame, "OnShow")
			W.flush()
			check("hkwin: taintLog " .. value .. ": with the own colour off the game's colour stays", colour() == "0.50,0.50,0.50" and #W.errors == 0 and #W.violations == 0, colour())
		end

		-- The item level of a bank slot the game refreshes.
		do
			local B = HK.world(value, { second = true }, { ["windows.ilvlBags"] = true })
			local panel = wraw(B, B.win.names.BankFrame).BankPanel
			local button, r = HK.made(B, function() return B.win.itemButton(panel, nil, "HkwinLevelSlot") end)
			r.GetBankTabID, r.GetContainerSlotID = function() return 6 end, function() return 2 end
			r.Refresh = function() B.env.SetItemButtonQuality(button, 4) end
			B.items.bag["6:2"] = { hyperlink = "item:sword", quality = 4, hasNoValue = false }
			B.items.class["item:sword"], B.items.level["item:sword"], B.items.quality["item:sword"] = 2, 215, 4
			HK.up(B)
			B.blizzard(function() panel:GenerateItemSlotsForSelectedTab() end)
			B.flush()
			local function level()
				for _, t in ipairs(B.addonFonts) do
					if t.owner == button then
						return t.text
					end
				end
			end
			check("hkwin: taintLog " .. value .. ": a bank slot has its level, and Refresh of the slot is not hooked", level() == "215" and HK.fields(B) == "", tostring(level()) .. HK.fields(B))
			-- The first refresh gives the slot its quality colour, which the game's colour functions follow; the next one changes the item alone.
			B.blizzard(function() button:Refresh() end)
			B.flush()
			B.items.bag["6:2"] = { hyperlink = "item:axe", quality = 4, hasNoValue = false }
			B.items.class["item:axe"], B.items.level["item:axe"] = 4, 99
			B.blizzard(function() button:Refresh() end)
			check("hkwin: taintLog " .. value .. ": the level stays inside the game's refresh", level() == "215", tostring(level()))
			B.flush()
			check("hkwin: taintLog " .. value .. ": and follows the slot on the next frame", level() == "99" and #B.errors == 0 and #B.violations == 0, tostring(level()))
		end

		-- Scroll lists.
		do
			local L = HK.world(value, { more = true })
			HK.up(L)
			local list = L.win.categories
			L.win.updateList(list, 3)
			local lines = wraw(L, wraw(L, list).ScrollTarget).children
			check("hkwin: taintLog " .. value .. ": the rows of a list are styled, and Update of the list is not hooked", wa(L, wraw(L, lines[1]).states.Normal) == 0 and HK.fields(L) == "" and (L.boxCallbacks or 0) > 0, HK.fields(L))
			wraw(L, list).want = 5
			L.blizzard(function() list:Update() end)
			lines = wraw(L, wraw(L, list).ScrollTarget).children
			check("hkwin: taintLog " .. value .. ": a row the list makes is not styled inside its update", #lines == 5 and wa(L, wraw(L, lines[5]).states.Normal) == 1)
			L.flush()
			check("hkwin: taintLog " .. value .. ": and is styled on the next frame", wa(L, wraw(L, lines[5]).states.Normal) == 0 and #L.errors == 0 and #L.violations == 0)
		end

		-- The headers of the stat list.
		do
			local C = HK.world(value, { only = { "CharacterFrame" } })
			local list, target = HK.made(C, function()
				local l = C.win.frame(C.win.names.CharacterStatsPaneScrollBox, "ScrollBox", {})
				C.win.watchable(l)
				return l, C.win.frame(l, "ScrollTarget", {})
			end)
			HK.up(C)
			local header = HK.made(C, function()
				local h = C.win.frame(target, nil, { width = 197, height = 40 })
				C.win.tex(h, "Background", "UI-Character-Info-Title")
				C.win.font(h, "Title")
				return h
			end)
			C.blizzard(function() list:Update() end)
			check("hkwin: taintLog " .. value .. ": a header the scroll box laid out is not styled inside its update", wa(C, wraw(C, header).Background) == 1)
			C.flush()
			check("hkwin: taintLog " .. value .. ": and is styled on the next frame, with no hook on Update of the list", wa(C, wraw(C, header).Background) == 0 and HK.fields(C) == "" and #C.errors == 0 and #C.violations == 0, HK.fields(C))
		end
	end
end
-- >>> hkwin (end)

-- >>> hkunit (begin)
-- hkunit: no method of a frame the game owns is hooked in the unit frames. The scripts of the frames are followed with HookScript and the work waits for the next frame,
-- so each setting changes what it did with taintLog 0 and 2. A call of a game method made here has no script behind it (FH.depth), and W.hookRun runs the hooks of the script.
do
	local H = {}
	function H.game(W, frame, method, ...)
		FH.depth = FH.depth + 1
		local ok, err = pcall(W.blizzard, function(...) frame[method](frame, ...) end, ...)
		FH.depth = FH.depth - 1
		if not ok then
			error(err, 0)
		end
	end
	function H.rgb(c) return c and string.format("%.2f,%.2f,%.2f", c[1], c[2], c[3]) or "-" end
	function H.look(W, target)
		local o = W.look(target)
		return o and string.format("%.2f,%.2f,%.2f", o.r or -1, o.g or -1, o.b or -1) or "none"
	end
	-- No new violation and no error since the world was set up (W.hkBase). With taintLog on the box that offers to turn it off is made at login, with a call
	-- the simulated client refuses, and its line in the chat is expected, so what the world held at the start is not counted.
	function H.quiet(W)
		return #W.violations == (W.hkBase or 0) and #W.errors == 0 and not has(W.status(), "stopped") and not has(W.status(), "failed")
	end
	function H.wrapped(W, list)
		local found = {}
		for _, pair in ipairs(list) do
			for _, method in ipairs(pair[2]) do
				if INSTHOOK.wrapped(W, pair[1], method) then
					found[#found + 1] = tostring(W.rawOf[pair[1]] and W.rawOf[pair[1]].name or "?") .. ":" .. method
				end
			end
		end
		return table.concat(found, ",")
	end
	-- The picture of the addon's that is on the frame a portrait is on: its first region in ARTWORK.
	function H.picture(W, portrait)
		local owner = W.rawOf[portrait].owner
		for _, f in ipairs(W.addonFrames) do
			if f.parent == owner then
				for _, t in ipairs(f.regions) do
					if t.layer == "ARTWORK" and t.addon and t.sublevel ~= 7 then
						return t
					end
				end
			end
		end
	end
	function H.hasScript(W, frame, which)
		local raw = W.rawOf[frame]
		return raw ~= nil and raw.hookScripts ~= nil and raw.hookScripts[which] ~= nil and #raw.hookScripts[which] == 1
	end
	local CHECKS = { "CheckClassification", "CheckBattlePet", "CheckFaction", "CheckLevel", "SetSmallSize", "Update", "UpdateAuras" }
	local TEXT = { "SetText", "SetFormattedText" }
	for _, value in ipairs({ "0", "2" }) do
		local W = FH.ufWorld({ prep = function(Y) Y.cvars.taintLog = value end })
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		W.flush()
		W.hkBase = #W.violations
		local T, M, Pet, P = W.target, W.members[1], W.pet, W.player
		local list = { { T.frame, CHECKS }, { W.focus.frame, CHECKS }, { M.frame, { "UpdateArt", "UpdateAuras", "PartyMemberHealthCheck", "UpdateOnlineStatus" } },
			{ W.env.PartyFrame, { "InitializePartyMemberFrames" } }, { Pet.frame, { "Update", "UpdateAuras", "SetScale" } }, { P.nameText, TEXT }, { T.nameText, TEXT },
			{ M.nameText, TEXT }, { Pet.nameText, TEXT }, { P.timer, { "SetFormattedText" } } }
		check("hkunit: taintLog " .. value .. ": no method of the target, focus, party or pet frame, and no text of a name or of the flag timer, is hooked", H.wrapped(W, list) == "", H.wrapped(W, list))
		check("hkunit: taintLog " .. value .. ": the scripts are followed instead: OnEvent of the target and the member, OnValueChanged of the member's health bar, OnShow of the party frame, OnEvent and OnShow of the pet frame, OnUpdate of the player frame",
			H.hasScript(W, T.frame, "OnEvent") and H.hasScript(W, M.frame, "OnEvent") and H.hasScript(W, M.health, "OnValueChanged") and H.hasScript(W, W.env.PartyFrame, "OnShow")
			and H.hasScript(W, Pet.frame, "OnEvent") and H.hasScript(W, Pet.frame, "OnShow") and H.hasScript(W, P.frame, "OnUpdate"))
		-- The game draws the classification of the target again from UNIT_CLASSIFICATION_CHANGED: its fill replaces the flat one until the next frame.
		W.uf.class.TargetFrame = "elite"
		local before = H.rgb(W.rawOf[T.healthFill].color)
		H.game(W, T.frame, "CheckClassification")
		local drawn = W.rawOf[T.healthFill].color == nil
		W.hookRun(T.frame, "OnEvent", "UNIT_CLASSIFICATION_CHANGED")
		local waiting = W.rawOf[T.healthFill].color == nil and #W.timers >= 1
		W.frame(1)
		check("hkunit: taintLog " .. value .. ": the target frame drawn again by the game: the fill is the game's until the next frame, and flat again then", before == "0.18,0.72,0.30" and drawn and waiting
			and H.rgb(W.rawOf[T.healthFill].color) == "0.18,0.72,0.30" and H.quiet(W), before .. " " .. tostring(drawn) .. tostring(waiting) .. H.rgb(W.rawOf[T.healthFill].color))
		-- An event that leads to none of these methods is not followed.
		local timers = #W.timers
		W.hookRun(T.frame, "OnEvent", "UNIT_HEALTH")
		check("hkunit: taintLog " .. value .. ": an event of the frame that calls none of these methods sets no work", #W.timers == timers)
		-- A party member's portrait takes the tint the game gives it when the health bar changes.
		local picture = H.picture(W, M.portrait)
		local white = table.concat(picture.vertex, ",")
		W.uf.health[M.frame] = 0.1
		H.game(W, M.frame, "PartyMemberHealthCheck")
		W.hookRun(M.health, "OnValueChanged", 1)
		local early = table.concat(picture.vertex, ",")
		W.frame(1)
		check("hkunit: taintLog " .. value .. ": the tint of a party member: the picture has it after the next frame and not before", white == "1,1,1,1" and early == white and table.concat(picture.vertex, ",") == "1,0,0,1" and H.quiet(W),
			white .. " " .. early .. " " .. table.concat(picture.vertex, ","))
		-- The party frame sets its members up in its OnShow.
		local Z = FH.ufWorld({ prep = function(Y) Y.cvars.taintLog = value end })
		Z.hkBase = #Z.violations
		H.game(Z, Z.env.PartyFrame, "InitializePartyMemberFrames")
		local unstyled = Z.state(Z.members[1].health) == "."
		Z.hookRun(Z.env.PartyFrame, "OnShow")
		local waiting2 = Z.state(Z.members[1].health) == "."
		Z.frame(1)
		-- With the unit frames off the world skips the same number of methods, so none of the skipped ones is a method of the unit frames.
		local control = FH.ufWorld({ saved = { options = { ["unitframes.enabled"] = false } }, prep = function(Y) Y.cvars.taintLog = value end })
		check("hkunit: taintLog " .. value .. ": the party frame shown: the members the game made are styled on the next frame, and the unit frames leave no method unfollowed", unstyled and waiting2
			and Z.state(Z.members[1].health) == "SB" and Z.state(Z.members[2].health) == "SB" and Z.ns.TaintSkipped() == control.ns.TaintSkipped() and H.quiet(Z),
			Z.state(Z.members[1].health) .. " " .. tostring(Z.ns.TaintSkipped()) .. " " .. tostring(control.ns.TaintSkipped()))
	end
	-- Auras of the target, the party pet and the totem buttons, in the world of the raid frames and the totems.
	for _, value in ipairs({ "0", "2" }) do
		local X = FH.xWorld({ prep = function(Y) Y.W.cvars.taintLog = value end })
		local W, T = X.W, X.target
		W.hkBase = #W.violations
		local list = { { T.frame, CHECKS }, { X.boss.frame, CHECKS }, { W.env.PartyFrame, { "InitializePartyMemberFrames" } }, { W.env.TotemFrame, { "Update" } } }
		check("hkunit: taintLog " .. value .. ": no method of the target frame, the boss frame, the party frame or the totem frame is hooked, and AuraUtil, a table of functions, is", H.wrapped(W, list) == ""
			and INSTHOOK.wrapped(W, W.env.AuraUtil, "SetAuraBorderColor") and H.hasScript(W, T.frame, "OnEvent") and H.hasScript(W, X.boss.frame, "OnEvent")
			and H.hasScript(W, W.env.TotemFrame, "OnEvent") and H.hasScript(W, W.env.PartyFrame, "OnShow"), H.wrapped(W, list))
		local buff = T.buttons[2]
		buff.stealable:Show()
		H.game(W, T.frame, "UpdateAuras")
		local plain = H.look(W, buff.icon) ~= "0.20,0.60,1.00"
		W.hookRun(T.frame, "OnEvent", "PLAYER_TARGET_CHANGED")
		local waiting = H.look(W, buff.icon) ~= "0.20,0.60,1.00"
		W.frame(1)
		check("hkunit: taintLog " .. value .. ": a buff that can be stolen gets its border on the frame after a new target", plain and waiting and H.look(W, buff.icon) == "0.20,0.60,1.00" and H.quiet(W), H.look(W, buff.icon))
		-- The totem frame lays its buttons out in its OnEvent.
		H.game(W, W.env.TotemFrame, "Update")
		local first = W.state(X.totem.icon)
		W.hookRun(W.env.TotemFrame, "OnEvent", "PLAYER_TOTEM_UPDATE")
		local second = W.state(X.totem.icon)
		W.frame(1)
		check("hkunit: taintLog " .. value .. ": a totem button is styled on the frame after the totem frame's OnEvent", first == "." and second == "." and W.state(X.totem.icon) == "SB" and H.quiet(W), first .. second .. W.state(X.totem.icon))
		-- The party pet frame is styled after the party frame's OnShow.
		H.game(W, W.env.PartyFrame, "InitializePartyMemberFrames")
		local early = g(W.rawOf[X.pet.art].alpha)
		W.hookRun(W.env.PartyFrame, "OnShow")
		local early2 = g(W.rawOf[X.pet.art].alpha)
		W.frame(1)
		check("hkunit: taintLog " .. value .. ": a party pet frame is styled on the frame after the party frame's OnShow", early == "1" and early2 == "1" and g(W.rawOf[X.pet.art].alpha) == "0" and H.quiet(W),
			early .. early2 .. g(W.rawOf[X.pet.art].alpha))
	end
end
-- >>> hkunit (end)

-- >>> sdlook (begin)
-- Setup drawings of the Look area: mock-scale (step Scale) and mock-text (step Fonts).
do
	local K = {}
	-- Every region and frame under a root, in a fixed order, and a line for each: its kind, whether it is shown, its size, scale, alpha, points, colour, file, vertex
	-- colour, text, font, shadow and text colour. A point names what it hangs from by its place in the list.
	function K.nodes(W, root)
		local list, seen = {}, {}
		local function visit(object)
			if seen[object] then return end
			seen[object] = #list + 1
			list[#list + 1] = object
			local raw = W.rawOf[object] or object
			for _, region in ipairs(raw.regions or {}) do visit(region) end
			for _, child in ipairs(raw.children or {}) do visit(child) end
		end
		visit(root)
		return list, seen
	end
	function K.num(v)
		return type(v) == "number" and ("%.4f"):format(v) or tostring(v)
	end
	function K.list(t)
		local out = {}
		for i, v in ipairs(t or {}) do out[i] = K.num(v) end
		return table.concat(out, ",")
	end
	function K.fingerprint(W, root)
		local nodes, seen = K.nodes(W, root)
		local lines = {}
		for i, object in ipairs(nodes) do
			local r = W.rawOf[object] or object
			local points = {}
			for _, p in ipairs(r.points or {}) do
				points[#points + 1] = ("%s>%s.%s:%s,%s"):format(p[1], tostring(seen[p[2]] or "ext"), p[3], K.num(p[4]), K.num(p[5]))
			end
			lines[i] = table.concat({ i, r.kind or "frame", tostring(r.shown), K.num(r.width), K.num(r.height), K.num(r.scale), K.num(r.alpha), table.concat(points, ";"),
				K.list(r.color), tostring(r.file), K.list(r.vertex), tostring(r.text), r.font and (r.font[1] .. " " .. K.num(r.font[2]) .. " [" .. tostring(r.font[3]) .. "]") or "-",
				K.list(r.shadow), K.list(r.textColour), tostring(r.allPoints and seen[r.allPoints]) }, "|")
		end
		return table.concat(lines, "\n")
	end
	-- A world, a stage frame under UIParent, and both drawings built on it. The font strings take the shadow calls the simulated client lacks.
	function K.world(opts)
		local W = newWorld(opts)
		W.login()
		local ns, env = W.ns, W.env
		-- The game's default scale for the screen: a client call the simulated one lacks.
		W.defaultScale = 0.64
		env.GetDefaultScale = function() return W.defaultScale end
		local stage = env.CreateFrame("Frame", nil, env.UIParent)
		stage:SetSize(658, 204)
		ns.Own[stage] = true
		local D = { W = W, ns = ns, stage = stage }
		D.scale, D.text = ns.SetupDrawings["mock-scale"], ns.SetupDrawings["mock-text"]
		D.scale.build(stage)
		D.text.build(stage)
		for _, fs in ipairs(W.addonFonts) do
			fs.SetShadowOffset = function(_, x, y) fs.shadow = { x, y } end
			fs.SetShadowColor = function(_, r, g, b, a) fs.shadowColour = { r, g, b, a } end
		end
		return D
	end
	function K.drawn(D, drawing)
		drawing.draw(D.stage)
		return K.fingerprint(D.W, drawing.root)
	end

	local D = K.world({ fontReturn = "true", height = 1440 })
	local W, ns = D.W, D.ns
	check("sdlook: both drawings are registered with build, draw and parts", type(D.scale) == "table" and type(D.text) == "table" and type(D.scale.build) == "function" and type(D.scale.draw) == "function"
		and type(D.text.build) == "function" and type(D.text.draw) == "function" and type(D.scale.parts) == "table" and type(D.text.parts) == "table")
	check("sdlook: SetupDrawLook.lua is listed in the TOC after Panel.lua", (function()
		local at = {}
		for i, name in ipairs(FILES) do at[name] = i end
		return at["SetupDrawLook.lua"] ~= nil and at["Panel.lua"] ~= nil and at["SetupDrawLook.lua"] > at["Panel.lua"]
	end)())

	-- The drawn settings of the two steps (groups.json), the drawing each is on, what must be on first, and a value that is not the default.
	local CASES = {
		{ "mock-scale", "general.scaleOn", {}, true },
		{ "mock-scale", "general.scale", { { "general.scaleOn", true } }, 100 },
		{ "mock-scale", "general.pixelPerfect", { { "general.scaleOn", true } }, true },
		{ "mock-scale", "general.pixelSize", { { "general.scaleOn", true }, { "general.pixelPerfect", true } }, 2 },
		{ "mock-scale", "general.scaleBelow", { { "general.scaleOn", true } }, true },
		{ "mock-scale", "general.scaleSmall", { { "general.scaleOn", true }, { "general.scaleBelow", true } }, 40 },
		{ "mock-text", "fonts.enabled", { { "fonts.size", 120 } }, true },
		{ "mock-text", "fonts.body", { { "fonts.enabled", true } }, "arial" },
		{ "mock-text", "fonts.numbers", { { "fonts.enabled", true } }, "friz" },
		{ "mock-text", "fonts.titles", { { "fonts.enabled", true } }, "skurri" },
		{ "mock-text", "fonts.outline", { { "fonts.enabled", true } }, "thick" },
		{ "mock-text", "fonts.shadow", { { "fonts.enabled", true } }, false },
		{ "mock-text", "fonts.size", { { "fonts.enabled", true } }, 120 },
		{ "mock-text", "fonts.minimum", { { "fonts.enabled", true } }, 12 },
		{ "mock-text", "fonts.gameTextSize", {}, 130 },
	}
	local changed, failing = 0, {}
	for _, case in ipairs(CASES) do
		local drawing = case[1] == "mock-scale" and D.scale or D.text
		local path = case[2]
		local before = {}
		for _, set in ipairs(case[3]) do before[#before + 1] = { set[1], ns.Get(set[1]) } end
		before[#before + 1] = { path, ns.Get(path) }
		for _, set in ipairs(case[3]) do ns.Set(set[1], set[2]) end
		local one = K.drawn(D, drawing)
		ns.Set(path, case[4])
		local two = K.drawn(D, drawing)
		local again = K.drawn(D, drawing)
		check("sdlook: " .. path .. " is a setting of its step and a part of " .. case[1], ns.Get(path) ~= nil and drawing.parts[path] ~= nil, tostring(ns.Get(path)))
		check("sdlook: " .. path .. " set to " .. tostring(case[4]) .. " gives the same drawing when drawn twice", two == again)
		if one ~= two then
			changed = changed + 1
		else
			failing[#failing + 1] = path
		end
		check("sdlook: " .. path .. " set to " .. tostring(case[4]) .. " changes the drawing " .. case[1], one ~= two, path)
		for i = #before, 1, -1 do ns.Set(before[i][1], before[i][2]) end
	end
	check("sdlook: coverage: all 15 drawn settings of Scale and Fonts change their drawing", changed == 15 and #failing == 0, table.concat(failing, ","))

	-- What is drawn.
	local chosen, game = D.scale.chosen, D.scale.game
	local function raw(object) return W.rawOf[object] or object end
	ns.Set("general.scaleOn", false)
	K.drawn(D, D.scale)
	check("sdlook: scale off: both frames are the same size and both say Game scale", near(chosen:GetScale(), game:GetScale()) and raw(D.scale.gameLabel).text == "Game scale" and raw(D.scale.chosenLabel).text == "Game scale",
		tostring(chosen:GetScale()) .. " " .. tostring(game:GetScale()))
	ns.Set("general.scaleOn", true)
	ns.Set("general.scale", 100)
	K.drawn(D, D.scale)
	check("sdlook: custom scale 100 with the game at 0.64: the chosen frame is 100/64 of the game frame and says so", near(chosen:GetScale() / game:GetScale(), 1 / 0.64, 1e-6)
		and raw(D.scale.chosenLabel).text == "Custom scale 100%" and raw(D.scale.grid).shown == false, tostring(chosen:GetScale() / game:GetScale()))
	ns.Set("general.scale", 65)
	K.drawn(D, D.scale)
	check("sdlook: custom scale 65: the chosen frame is a little larger than the game's 64", near(chosen:GetScale() / game:GetScale(), 0.65 / 0.64, 1e-6))
	ns.Set("general.scaleBelow", true)
	ns.Set("general.scaleSmall", 35)
	K.drawn(D, D.scale)
	check("sdlook: small scale 35: the chosen frame is smaller than the game's and says Small scale", near(chosen:GetScale() / game:GetScale(), 0.35 / 0.64, 1e-6) and raw(D.scale.chosenLabel).text == "Small scale 35%",
		tostring(raw(D.scale.chosenLabel).text))
	ns.Set("general.pixelPerfect", true)
	K.drawn(D, D.scale)
	check("sdlook: pixel-perfect at 1440 lines high with 1 pixel per unit: the scale is 768/1440, the grid shows and the custom scale is ignored",
		near(chosen:GetScale() / game:GetScale(), (768 / 1440) / 0.64, 1e-6) and raw(D.scale.grid).shown == true and raw(D.scale.chosenLabel).text == "Pixel-perfect, 1 px per unit",
		tostring(chosen:GetScale() / game:GetScale()) .. " " .. tostring(raw(D.scale.chosenLabel).text))
	ns.Set("general.pixelSize", 4)
	K.drawn(D, D.scale)
	check("sdlook: pixel-perfect with a scale that does not fit: the game's scale stays, and it says so", near(chosen:GetScale(), game:GetScale()) and raw(D.scale.grid).shown == false
		and has(raw(D.scale.chosenLabel).text, "does not fit"), tostring(raw(D.scale.chosenLabel).text))
	ns.Set("general.scaleBelow", false)
	ns.Set("general.pixelSize", 1)
	K.drawn(D, D.scale)
	check("sdlook: pixel-perfect under the game's 65 percent without Scale below 65%: the game's scale stays", near(chosen:GetScale(), game:GetScale()) and raw(D.scale.grid).shown == false
		and has(raw(D.scale.chosenLabel).text, "does not fit"), tostring(raw(D.scale.chosenLabel).text))
	ns.Set("general.pixelPerfect", false)
	-- A pair that would not fit the area is drawn smaller together, so the ratio between the two frames is kept.
	ns.Set("general.scale", 115)
	W.defaultScale = 0.35
	K.drawn(D, D.scale)
	check("sdlook: a pair too wide for the area is drawn smaller, with the ratio kept", chosen:GetScale() * 150 <= 280 + 1e-6 and near(chosen:GetScale() / game:GetScale(), 1.15 / 0.35, 1e-6),
		tostring(chosen:GetScale() * 150))
	W.defaultScale = 0.64
	W.cvars.useUiScale, W.cvars.uiscale = "1", "0.8"
	K.drawn(D, D.scale)
	check("sdlook: with the game's UI scale on, its own scale is the one drawn, whatever Flat UI sets on UIParent", near(chosen:GetScale() / game:GetScale(), 1.15 / 0.8, 1e-6), tostring(chosen:GetScale() / game:GetScale()))
	W.cvars.useUiScale, W.cvars.uiscale = "0", "0.64"
	ns.Set("general.scaleOn", false)
	ns.Set("general.scale", 65)
	local thin = K.drawn(D, D.scale)
	ns.Set("general.thickness", 3)
	check("sdlook: the border thickness of the draft reaches the sample frames", K.drawn(D, D.scale) ~= thin)
	ns.Set("general.thickness", 1)
	-- The border, the background and the bar texture of the draft reach the sample frame.
	local outline = chosen.outline
	ns.Set("general.borderless", true)
	ns.Set("general.border", "ff112233")
	ns.Set("general.backdrop", "ff445566")
	ns.Set("general.backdropAlpha", 40)
	ns.Set("general.barTexture", "soft")
	K.drawn(D, D.scale)
	local edge, back, fill = raw(outline.top), raw(outline.backdrop), raw(chosen.sample.health.fill)
	check("sdlook: borderless hides the edges of the sample frame and keeps its background", edge.shown == false and back.shown == true, tostring(edge.shown) .. tostring(back.shown))
	ns.Set("general.borderless", false)
	K.drawn(D, D.scale)
	check("sdlook: the border colour, the background colour and its opacity of the draft are on the sample frame", edge.shown == true and near(edge.color[1], 0x11 / 255) and near(edge.color[3], 0x33 / 255)
		and near(back.color[1], 0x44 / 255) and near(back.color[3], 0x66 / 255) and near(back.color[4], 0.4), K.list(edge.color) .. " " .. K.list(back.color))
	check("sdlook: the bar texture of the draft is the file of the health fill, tinted, and a solid colour when there is none", fill.file == ns.BarFile("soft") and fill.vertex ~= nil and fill.color == nil, tostring(fill.file))
	ns.Set("general.borderless", false)
	ns.Set("general.border", ns.Get("general.border"))
	-- The game's scale: the UI scale it is set to only while that is on, else the default scale for the screen, else what UIParent has.
	W.cvars.useUiScale, W.cvars.uiscale = "0", "0.8"
	ns.Set("general.scaleOn", true)
	ns.Set("general.scale", 100)
	K.drawn(D, D.scale)
	check("sdlook: with the game's UI scale off its uiscale value is not used", near(chosen:GetScale() / game:GetScale(), 1 / 0.64, 1e-6), tostring(chosen:GetScale() / game:GetScale()))
	local defaultScale = W.env.GetDefaultScale
	W.env.GetDefaultScale = nil
	ns.Set("general.scaleOn", false)
	W.gameScale(0.5)
	ns.Set("general.scaleOn", true)
	K.drawn(D, D.scale)
	check("sdlook: a client without GetDefaultScale draws against the scale UIParent has", near(chosen:GetScale() / game:GetScale(), 2, 1e-6), tostring(chosen:GetScale() / game:GetScale()) .. " " .. tostring(W.scale()))
	W.env.GetDefaultScale = defaultScale
	ns.Set("general.scaleOn", false)
	W.gameScale(0.64)
	W.cvars.useUiScale, W.cvars.uiscale = "0", "0.64"
	ns.Set("general.scaleOn", false)
	ns.Set("general.scale", 65)

	-- Text.
	local function font(key) return raw(D.text.lines[key]).font end
	local function shadow(key) return raw(D.text.lines[key]).shadow end
	D.text.draw()
	check("sdlook: fonts off: the game's faces, sizes 15, 12, 12 and 8, no flags", font("title")[1] == "Fonts\\MORPHEUS.TTF" and font("title")[2] == 15 and font("body")[1] == "Fonts\\FRIZQT__.TTF"
		and font("body")[2] == 12 and font("number")[1] == "Fonts\\ARIALN.TTF" and font("number")[2] == 12 and font("small")[2] == 8 and font("title")[3] == "", tostring(font("title")[1]))
	ns.Set("fonts.enabled", true)
	ns.Set("fonts.size", 125)
	ns.Set("fonts.body", "arial")
	ns.Set("fonts.titles", "skurri")
	ns.Set("fonts.numbers", "friz")
	ns.Set("fonts.outline", "outline")
	ns.Set("fonts.shadow", false)
	D.text.draw()
	check("sdlook: fonts on: each role takes its own face, the size is a percent of the sample size, the outline is the flag and the shadow is off",
		font("title")[1] == "Fonts\\SKURRI.TTF" and font("body")[1] == "Fonts\\ARIALN.TTF" and font("number")[1] == "Fonts\\FRIZQT__.TTF" and near(font("title")[2], 18.75) and near(font("small")[2], 10)
		and font("body")[3] == "OUTLINE" and shadow("body")[1] == 0 and shadow("body")[2] == 0, tostring(font("title")[1]) .. " " .. tostring(font("title")[2]))
	ns.Set("fonts.minimum", 11)
	D.text.draw()
	check("sdlook: the smallest text raises the small print and leaves larger text alone", near(font("small")[2], 11) and near(font("body")[2], 15), tostring(font("small")[2]))
	ns.Set("fonts.enabled", false)
	D.text.draw()
	check("sdlook: fonts off again puts the game's faces, sizes and shadow back whatever the other rows say", font("title")[1] == "Fonts\\MORPHEUS.TTF" and font("small")[2] == 8 and shadow("body")[1] == 1)
	ns.Set("fonts.gameTextSize", 150)
	D.text.draw()
	check("sdlook: game text size 150 draws the pop-up line at 16.5 and does not depend on the fonts switch", near(raw(D.text.gameLine).font[2], 16.5), tostring(raw(D.text.gameLine).font[2]))
	ns.Set("fonts.gameTextSize", 100)
	-- A face the client refuses falls back to the game's file.
	ns.Set("fonts.enabled", true)
	ns.Set("fonts.body", "arial")
	local rawBody = raw(D.text.lines.body)
	local setFont = rawBody.SetFont
	rawBody.SetFont = function(self, file, ...)
		if file == "Fonts\\ARIALN.TTF" then error("Invalid font asset", 0) end
		return setFont(self, file, ...)
	end
	D.text.draw()
	check("sdlook: a face the client refuses gives the game's face for that role", rawBody.font[1] == "Fonts\\FRIZQT__.TTF", tostring(rawBody.font[1]))
	rawBody.SetFont = setFont
	ns.Set("fonts.enabled", false)
	ns.Set("fonts.body", "default")
	ns.Set("fonts.titles", "default")
	ns.Set("fonts.numbers", "default")
	ns.Set("fonts.outline", "game")
	ns.Set("fonts.shadow", true)
	ns.Set("fonts.size", 100)
	ns.Set("fonts.minimum", 0)

	-- The parts the smallest text and the faces name.
	check("sdlook: fonts.minimum is the small print line and fonts.body the body line", D.text.parts["fonts.minimum"] == D.text.lines.small and D.text.parts["fonts.body"] == D.text.lines.body
		and D.text.parts["fonts.minimum"] ~= D.text.parts["fonts.body"])
	-- Pixel-perfect below 0.5: 1 pixel per unit at 2000 lines high is 0.384, which is applied. An unknown height is its own mode.
	ns.Set("general.scaleOn", true)
	ns.Set("general.pixelPerfect", true)
	ns.Set("general.pixelSize", 1)
	ns.Set("general.scaleBelow", true)
	W.height = 2000
	K.drawn(D, D.scale)
	check("sdlook: pixel-perfect at 2000 lines high gives 768/2000, under 0.5, and is drawn as pixel", near(chosen:GetScale() / game:GetScale(), (768 / 2000) / 0.64, 1e-6)
		and raw(D.scale.grid).shown == true, tostring(chosen:GetScale() / game:GetScale()))
	W.height = 1440
	W.heightFault = "secret"
	K.drawn(D, D.scale)
	check("sdlook: pixel-perfect with no known screen height keeps the game's scale and says the height is not known", near(chosen:GetScale(), game:GetScale()) and raw(D.scale.grid).shown == false
		and has(raw(D.scale.chosenLabel).text, "height is not known") and not has(raw(D.scale.chosenLabel).text, "does not fit"), tostring(raw(D.scale.chosenLabel).text))
	W.heightFault = nil
	ns.Set("general.pixelPerfect", false)
	ns.Set("general.scaleBelow", false)
	ns.Set("general.scaleOn", false)
	-- The sample bars are cropped, not stretched, so 70 percent shows 70 percent of the image.
	check("sdlook: the sample bars crop the image to the share they show", (function()
		local c = raw(chosen.sample.health.fill).texCoord
		return c ~= nil and near(c[2], 0.7) and near(c[4], 1)
	end)())

	-- A client whose language is not Latin keeps the game's faces: the drawing does too.
	do
		local R = K.world({ fontReturn = "true", height = 1440 })
		R.W.env.GetLocale = function() return "ruRU" end
		R.W.env.GameFontHighlightSmall = { GetFont = function() return "Fonts\\2002.TTF", 10, "" end }
		local rn = R.ns
		local function look() return K.drawn(R, R.text) end
		rn.Set("fonts.enabled", true)
		local plain = look()
		rn.Set("fonts.body", "arial")
		rn.Set("fonts.titles", "skurri")
		rn.Set("fonts.numbers", "friz")
		check("sdlook: on a ruRU client the faces chosen draw the same as the default faces", look() == plain)
		rn.Set("fonts.size", 130)
		check("sdlook: on a ruRU client the size still changes the drawing", look() ~= plain)
		local face = R.W.rawOf[R.text.lines.body].font[1]
		check("sdlook: on a ruRU client the face is the file the game's own font object has", face == "Fonts\\2002.TTF", tostring(face))
		check("sdlook: no violation and no error on a ruRU client", #R.W.violations == 0 and #R.W.errors == 0)
	end

	-- Every frame and region made is the addon's own, and nothing was reported.
	local nodes = K.nodes(W, D.stage)
	local loose = 0
	for i = 2, #nodes do
		if not ns.Own[nodes[i]] then loose = loose + 1 end
	end
	check("sdlook: every frame, texture and font string of the drawings is marked ns.Own", #nodes > 40 and loose == 0, #nodes .. " " .. loose)
	check("sdlook: no violation and no error from building or drawing", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
end
