		{ "nameplates.rareColour", "mock-nameplate-marks", "ff12ab34", { { "nameplates.health", true }, { "nameplates.kindBorder", true } } },
		{ "nameplates.bossColour", "mock-nameplate-marks", "ff12ab34", { { "nameplates.health", true }, { "nameplates.kindBorder", true } } },
		{ "nameplates.raidMarker", "mock-nameplate-marks", false, {} },
