		{ "nameplates.size", "mock-nameplate-stack", 5, {} },
		{ "nameplates.overlapH", "mock-nameplate-stack", 150, {} },
		{ "nameplates.overlapV", "mock-nameplate-stack", 300, {} },
		{ "nameplates.selectedScale", "mock-nameplate-stack", 200, {} },
		{ "nameplates.minScale", "mock-nameplate-stack", 100, {} },
		{ "nameplates.minAlpha", "mock-nameplate-stack", 100, {} },
		{ "nameplates.notSelectedAlpha", "mock-nameplate-stack", 10, {} },
	}
	SD.DRAWINGS = { "mock-nameplate", "mock-nameplate-cast", "mock-nameplate-auras", "mock-nameplate-marks", "mock-nameplate-stack" }
	function SD.world(hud)
		local W = newWorld({ cooldowns = true, hud = hud })
		local env = W.env
		env.C_Texture = { GetAtlasExists = function() return true end }
		env.UnitClass = function() return "Mage", "MAGE", 8 end
		env.UnitName = function() return "Brennan" end
		env.RAID_CLASS_COLORS = { MAGE = { r = 0.25, g = 0.78, b = 0.92 } }
		W.login()
		return W
	end
	function SD.stage(W, width, height)
		local stage = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		stage:SetSize(width or 658, height or 204)
		return stage
	end
	-- Every frame and region under a stage, in the order they were made, as lines of text.
	function SD.fingerprint(W, stage)
		local order, list = {}, {}
		local function Number(value)
			return type(value) == "number" and ("%.3f"):format(value) or tostring(value)
		end
		local function Collect(frame)
			if not order[frame] then
				list[#list + 1] = frame
				order[frame] = #list
			end
			for _, region in ipairs(frame.regions or {}) do
				list[#list + 1] = region
				order[region] = #list
			end
			for _, child in ipairs(frame.children or {}) do
				Collect(W.rawOf[child] or child)
			end
		end
		Collect(W.rawOf[stage])
		local lines = {}
		for index, item in ipairs(list) do
			local parts = { index, item.isRegion and (item.kind or "region") or "frame", tostring(item.shown), Number(item.alpha), Number(item.width), Number(item.height) }
			for _, point in ipairs(item.points or {}) do
				local relative = W.rawOf[point[2]]
				parts[#parts + 1] = ("%s>%s>%s>%s>%s"):format(point[1], tostring(relative and order[relative]), point[3], Number(point[4]), Number(point[5]))
			end
			if item.isRegion then
				parts[#parts + 1] = item.color and table.concat(item.color, ",") or "-"
				parts[#parts + 1] = tostring(item.atlas) .. "|" .. tostring(item.file) .. "|" .. (item.vertex and table.concat(item.vertex, ",") or "-")
				parts[#parts + 1] = item.texCoord and table.concat(item.texCoord, ",") or "-"
				parts[#parts + 1] = tostring(item.text) .. "|" .. (item.font and (tostring(item.font[1]) .. "," .. Number(item.font[2]) .. "," .. tostring(item.font[3])) or "-")
				parts[#parts + 1] = item.textColour and table.concat(item.textColour, ",") or "-"
				parts[#parts + 1] = tostring(item.blend) .. "|" .. tostring(item.fontObject)
			else
				parts[#parts + 1] = Number(item.scale)
				parts[#parts + 1] = item.cd and (tostring(item.cd.hideNumbers) .. "|" .. tostring(item.cd.sweep ~= nil)) or "-"
			end
			lines[#lines + 1] = table.concat(parts, ";")
		end
		return table.concat(lines, "\n"), #list
	end
	function SD.draw(W, id, stage)
		local drawing = W.ns.SetupDrawings[id]
		drawing.build(stage)
		drawing.draw(stage)
		W.tick()
		return drawing
	end

	-- The five drawings are registered, built and drawn without an error or a violation.
	do
		local W = SD.world()
		local have = {}
		for _, id in ipairs(SD.DRAWINGS) do
			local drawing = W.ns.SetupDrawings[id]
			have[#have + 1] = (drawing and type(drawing.build) == "function" and type(drawing.draw) == "function" and type(drawing.parts) == "table") and id or ("missing " .. id)
		end
		check("sdplate: the five nameplate drawings are in ns.SetupDrawings, each with build, draw and parts", table.concat(have, " ") == table.concat(SD.DRAWINGS, " "), table.concat(have, " "))
		local failed, counts = {}, {}
		for _, id in ipairs(SD.DRAWINGS) do
			local stage = SD.stage(W)
			local ok, err = pcall(SD.draw, W, id, stage)
			if not ok then
				failed[#failed + 1] = id .. ": " .. tostring(err)
			end
			local _, count = SD.fingerprint(W, stage)
			counts[#counts + 1] = count
		end
		check("sdplate: every drawing builds and draws on a stage with no error", #failed == 0, table.concat(failed, " | "))
		check("sdplate: and with no violation and no error of the addon in the world", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | ") .. table.concat(W.errors, " | "))
		local many = true
		for _, count in ipairs(counts) do
			many = many and count > 20
		end
		check("sdplate: every drawing makes frames and regions of its own", many, table.concat(counts, " "))
	end

	function SD.show(W, id, width, height)
		local stage = SD.stage(W, width, height)
		SD.draw(W, id, stage)
		return stage, W.ns.SetupDrawPlates.states[stage]
	end
	function SD.near(a, b)
		return type(a) == "number" and type(b) == "number" and math.abs(a - b) < 0.01
	end

	-- Sizes follow the style and the size of the game, and the percent rows of the page.
	do
		local W = SD.world()
		local ns = W.ns
		local _, S = SD.show(W, "mock-nameplate")
		local m = S.plates.enemy.m
		check("sdplate: size 1 in the thin style: the bar is 124.5 wide and 10.4 high, the level box a square 10.4 wide, the name above the bar, no dark band",
			SD.near(m.BW, 124.5) and SD.near(m.HH, 10.4) and SD.near(m.LW, 10.4) and SD.near(m.LH, 10.4) and m.nameAbove == true and W.rawOf[S.plates.enemy.band].shown == false,
			("%s %s %s %s"):format(m.BW, m.HH, m.LW, tostring(m.nameAbove)))
		ns.Set("nameplates.size", 5)
		ns.Set("nameplates.style", "modern")
		_, S = SD.show(W, "mock-nameplate")
		m = S.plates.enemy.m
		check("sdplate: size 5 in the modern style: the bar is 265.6 wide and 32 high and the name is inside it",
			ns.Get("nameplates.size") == 5 and SD.near(m.BW, 265.6) and SD.near(m.HH, 32) and m.nameAbove == false, ("%s %s %s"):format(m.BW, m.HH, tostring(m.nameAbove)))
		ns.Set("nameplates.healthHeight", 50)
		ns.Set("nameplates.barWidth", 50)
		_, S = SD.show(W, "mock-nameplate")
		m = S.plates.enemy.m
		check("sdplate: Health bar height and Bar width of the page are percents of those sizes", SD.near(m.BW, 132.8) and SD.near(m.HH, 16), ("%s %s"):format(m.BW, m.HH))
		ns.Set("nameplates.healthHeight", 100)
		ns.Set("nameplates.barWidth", 100)
		ns.Set("nameplates.style", "block")
		ns.Set("nameplates.size", 2)
		_, S = SD.show(W, "mock-nameplate-cast")
		m = S.plates.cast.m
		check("sdplate: the block style has a 16 high cast bar with the spell name inside it",
			SD.near(m.CB, 16) and m.style.spellInside == true and SD.near(m.CC, 16), ("%s %s"):format(m.CB, m.CC))
		ns.Set("nameplates.style", "thin")
		_, S = SD.show(W, "mock-nameplate-cast")
		m = S.plates.cast.m
		check("sdplate: the thin style has a 6 high cast bar over the icon, and the health bar above the container",
			SD.near(m.CB, 6) and SD.near(m.CC, 16) and SD.near(m.healthY, 18), ("%s %s %s"):format(m.CB, m.CC, m.healthY))
	end

	-- Texts and colours.
	do
		local W = SD.world()
		local ns = W.ns
		local function R(x) return W.rawOf[x] end
		local _, S = SD.show(W, "mock-nameplate")
		local want = { game = "70%", percent = "70%", value = "7.0K", both = "7.0K  70%", missing = "3.0K" }
		local bad = {}
		for format, text in pairs(want) do
			ns.Set("nameplates.healthFormat", format)
			_, S = SD.show(W, "mock-nameplate")
			if R(S.plates.enemy.htext).text ~= text then
				bad[#bad + 1] = format .. "=" .. tostring(R(S.plates.enemy.htext).text)
			end
		end
		check("sdplate: the health text is 70% by default and in the formats of the row 7.0K, 7.0K  70% and 3.0K", #bad == 0, table.concat(bad, " "))
		check("sdplate: the format strings are the ones the health text of the plates writes with", ns.PLATE_HEALTH_FORMATS.percent == "%.0f%%" and ns.PLATE_HEALTH_FORMATS.both == "%s  %.0f%%")
		local elite, enemy = S.plates.elite, S.plates.enemy
		check("sdplate: the elite plate has + after its level 20, the plain enemy no mark",
			R(elite.mark).text == "+" and R(elite.mark).shown and R(elite.lvlText).text == "20" and not R(enemy.mark).shown, tostring(R(elite.mark).text))
		ns.Set("nameplates.kindMark", false)
		_, S = SD.show(W, "mock-nameplate")
		check("sdplate: Mark after the level off takes the + away", not R(S.plates.elite.mark).shown)
		ns.Set("nameplates.targetBar", true)
		ns.Set("nameplates.threat", true)
		ns.Set("nameplates.hover", true)
		ns.Set("nameplates.lowHealth", true)
		_, S = SD.show(W, "mock-nameplate")
		local r, g, b = ns.Colour("nameplates.targetBarColour")
		local fill = R(S.plates.target.fill).color
		check("sdplate: with Colour the target's health bar there is a Target plate in that colour", SD.near(fill[1], r) and SD.near(fill[2], g) and SD.near(fill[3], b) and R(S.plates.target.f).shown)
		local chips = {}
		for index, row in ipairs({ "threatGood", "threatTransition", "threatBad" }) do
			local cr, cg, cb = ns.Colour("nameplates." .. row)
			local color = R(S.plates.threat.chips.list[index].fill).color
			chips[#chips + 1] = (SD.near(color[1], cr) and SD.near(color[2], cg) and SD.near(color[3], cb)) and "ok" or row
		end
		check("sdplate: Threat colours shows the three colours of the rows as three bars", table.concat(chips, " ") == "ok ok ok", table.concat(chips, " "))
		local hr, hg, hb = ns.Colour("nameplates.hoverColour")
		local edge = R(S.plates.hover.outline.top).color
		check("sdplate: Mouseover border shows a plate with the border in the mouseover colour", SD.near(edge[1], hr) and SD.near(edge[2], hg) and SD.near(edge[3], hb), table.concat(edge, ","))
		check("sdplate: Low health border is shown on the plate at 18% and not on the one at 70%", R(S.plates.low.lowFrame).alpha == 1 and R(S.plates.enemy.lowFrame).alpha == 0,
			tostring(R(S.plates.low.lowFrame).alpha) .. " " .. tostring(R(S.plates.enemy.lowFrame).alpha))
		ns.Set("nameplates.lowHealthAt", 15)
		_, S = SD.show(W, "mock-nameplate")
		check("sdplate: and not at all when the limit is under that", R(S.plates.low.lowFrame).alpha == 0)
		local boxes = {}
		for _, style in ipairs({ "box", "text", "default" }) do
			ns.Set("nameplates.level", style)
			_, S = SD.show(W, "mock-nameplate")
			boxes[#boxes + 1] = tostring(R(S.plates.enemy.lvlOutline.top).shown) .. "/" .. tostring(R(S.plates.enemy.lvlArt).shown)
		end
		check("sdplate: Level box: a thin border with the box, the number alone with Text only, the game's art with Default", table.concat(boxes, " ") == "true/false false/false false/true", table.concat(boxes, " "))
		ns.Set("general.reactionOwn", true)
		ns.Set("general.reactionHostile", "ff3366ff")
		ns.Set("nameplates.colours", true)
		ns.Set("nameplates.colourPlayers", "reaction")
		_, S = SD.show(W, "mock-nameplate")
		local hostile = R(S.plates.enemy.fill).color
		local player = R(S.plates.player.fill).color
		check("sdplate: Reaction colours on health bars takes the hostile colour of the Colours page, for players too with By reaction",
			SD.near(hostile[1], 0.2) and SD.near(hostile[3], 1) and SD.near(player[1], 0.2) and SD.near(player[3], 1), table.concat(hostile, ",") .. " " .. table.concat(player, ","))
		ns.Set("nameplates.colourPlayers", "game")
		_, S = SD.show(W, "mock-nameplate")
		player = R(S.plates.player.fill).color
		check("sdplate: and with As the game has it a player keeps the class colour", SD.near(player[1], 0.25) and SD.near(player[2], 0.78), table.concat(player, ","))
		ns.Set("general.reactionFriendly", "ffff00ff")
		_, S = SD.show(W, "mock-nameplate")
		local friendFill = R(S.plates.friend.fill).color
		check("sdplate: with As the game has it the friendly player plate keeps the game colour, not the custom friendly colour", not (SD.near(friendFill[1], 1) and SD.near(friendFill[3], 1)), table.concat(friendFill, ","))
		ns.Set("nameplates.colourPlayers", "reaction")
		_, S = SD.show(W, "mock-nameplate")
		friendFill = R(S.plates.friend.fill).color
		check("sdplate: and with By reaction it takes the custom friendly colour", SD.near(friendFill[1], 1) and SD.near(friendFill[3], 1), table.concat(friendFill, ","))
		ns.Set("nameplates.colourPlayers", "game")
		ns.Set("nameplates.colours", false)
		ns.Set("nameplates.healthByLeft", true)
		_, S = SD.show(W, "mock-nameplate")
		local lr, lg, lb = ns.HealthLeftColour(0.7)
		local left = R(S.plates.enemy.fill).color
		check("sdplate: Colour health bars by health left takes the colour of 70% of the health left", SD.near(left[1], lr) and SD.near(left[2], lg) and SD.near(left[3], lb))
		local low = { ns.HealthLeftColour(0) }
		local half = { ns.HealthLeftColour(0.5) }
		local full = { ns.HealthLeftColour(1) }
		local mid = { ns.HealthLeftColour(0.75) }
		local lr1, lg1, lb1 = ns.Colour("general.healthLow")
		local hr1, hg1, hb1 = ns.Colour("general.healthHalf")
		local fr1, fg1, fb1 = ns.Colour("general.healthFull")
		check("sdplate: the colour by health left is the low colour at 0, the half colour at 0.5, the full colour at 1 and the middle of the last two at 0.75",
			SD.near(low[1], lr1) and SD.near(low[2], lg1) and SD.near(low[3], lb1) and SD.near(half[1], hr1) and SD.near(half[2], hg1) and SD.near(half[3], hb1)
			and SD.near(full[1], fr1) and SD.near(full[2], fg1) and SD.near(full[3], fb1)
			and SD.near(mid[1], (hr1 + fr1) / 2) and SD.near(mid[2], (hg1 + fg1) / 2) and SD.near(mid[3], (hb1 + fb1) / 2), table.concat(mid, ","))
	end

	-- Class icons, the raid marker, borders by kind, the cast bar, auras and the stack.
	do
		local W = SD.world()
		local ns = W.ns
		local function R(x) return W.rawOf[x] end
		local _, S = SD.show(W, "mock-nameplate-marks")
		local player, friend = S.plates.player, S.plates.friend
		local point = R(player.iconFrame).points[1]
		check("sdplate: an enemy player has the class icon at the left of the row, flush with it, the height of the bar",
			R(player.iconFrame).shown and point[1] == "RIGHT" and SD.near(point[4], 0) and SD.near(R(player.iconFrame).width, player.m.HH)
			and not R(friend.iconFrame).shown, tostring(point and point[1]))
		local atlas = R(player.iconArt).atlas
		check("sdplate: and it draws the class art of the game's atlas", atlas == "classicon-mage", tostring(atlas))
		-- Class icon shape: the card has the circle mask on the art and a disc at Round, and neither at Square.
		do
			local H = SD.world(true)
			local function discOf(art)
				for _, t in ipairs(H.addonTextures) do
					local r = H.rawOf[t] or t
					local owner = H.rawOf[r.owner] or r.owner
					for m in pairs(r.masks) do
						-- On the frame of the art or on a frame of its own under it, and of this drawing.
						if r ~= art and (H.rawOf[m] or m).allPoints == r and (owner == H.rawOf[art.owner] or (owner and H.rawOf[owner.parent] == H.rawOf[art.owner])) then
							return r
						end
					end
				end
			end
			local function card(shape)
				H.ns.Set("nameplates.classShape", shape)
				local _, state = SD.show(H, "mock-nameplate-marks")
				local art = H.rawOf[state.plates.player.iconArt]
				return art, discOf(art)
			end
			local square, squareDisc = card("square")
			check("sdplate: Class icon shape Square: the card art has no mask and no disc", next(square.masks) == nil and squareDisc == nil)
			local round, roundDisc = card("round")
			local mask = next(round.masks)
			check("sdplate: Class icon shape Round: the card art has the circle mask and the disc shows", mask ~= nil and (H.rawOf[mask] or mask).atlas == "CircleMaskScalable" and roundDisc ~= nil and roundDisc.shown,
				tostring(mask) .. " " .. tostring(roundDisc))
			square, squareDisc = card("square")
			check("sdplate: and Square again draws it with no mask and no disc", next(square.masks) == nil and squareDisc == nil)
			check("sdplate: the cards are drawn without a violation or an error", #H.violations == 0 and #H.errors == 0, table.concat(H.violations, "|") .. table.concat(H.errors, "|"))
		end
		local places = { left = "RIGHT", above = "BOTTOM", below = "TOP", right = "LEFT" }
		local bad = {}
		for position, anchor in pairs(places) do
			ns.Set("nameplates.classPosition", position)
			_, S = SD.show(W, "mock-nameplate-marks")
			if R(S.plates.player.iconFrame).points[1][1] ~= anchor then
				bad[#bad + 1] = position
			end
		end
		check("sdplate: Class icon position moves the icon to the left, right, above and below the row", #bad == 0, table.concat(bad, " "))
		ns.Set("nameplates.classFit", "own")
		ns.Set("nameplates.classGap", 3)
		local m = player.m
		local want = { right = { "LEFT", m.BW + 3, m.center }, left = { "RIGHT", -3, m.center }, above = { "BOTTOM", m.BW / 2, m.healthY + m.HH + m.sp + m.NH + 3 }, below = { "TOP", m.BW / 2, -3 } }
		local off = {}
		for position, place in pairs(want) do
			ns.Set("nameplates.classPosition", position)
			_, S = SD.show(W, "mock-nameplate-marks")
			local at = R(S.plates.player.iconFrame).points[1]
			if not (at[1] == place[1] and SD.near(at[4], place[2]) and SD.near(at[5], place[3])) then
				off[#off + 1] = position .. " " .. at[1] .. " " .. at[4] .. " " .. at[5]
			end
		end
		check("sdplate: and the icon is 3 units from the row, in the middle of the side or of the row", #off == 0, table.concat(off, " | "))
		ns.Set("nameplates.classFriendly", true)
		ns.Set("nameplates.classPosition", "right")
		_, S = SD.show(W, "mock-nameplate-marks")
		check("sdplate: Class icon on friendly players shows the icon on the friendly plate", R(S.plates.friend.iconFrame).shown)
		local mark = R(S.plates.marked.marker)
		check("sdplate: the raid marker is the skull cell of the game's marker image, 22 units, at the left of the row",
			mark.shown and SD.near(mark.texCoord[1], 0.75) and SD.near(mark.texCoord[3], 0.25) and SD.near(mark.width, 22) and mark.points[1][1] == "RIGHT", tostring(mark.texCoord and mark.texCoord[1]))
		ns.Set("nameplates.targetThickness", 3)
		_, S = SD.show(W, "mock-nameplate-marks")
		check("sdplate: Target and focus border thickness is the thickness of the target's and the focus's border and not of the others",
			S.plates.target.outline.px == 3 and S.plates.focus.outline.px == 3 and S.plates.marked.outline.px == nil)
		local tr, tg, tb = ns.Colour("nameplates.targetColour")
		local fr, fg, fb = ns.Colour("nameplates.focusColour")
		local top = R(S.plates.target.outline.top).color
		local topFocus = R(S.plates.focus.outline.top).color
		check("sdplate: the target has the target colour round the bar and the focus the focus colour",
			SD.near(top[1], tr) and SD.near(top[2], tg) and SD.near(top[3], tb) and SD.near(topFocus[1], fr) and SD.near(topFocus[2], fg) and SD.near(topFocus[3], fb))
		check("sdplate: with Target and focus border on the game's own marker round the bar is not shown", not R(S.plates.target.edges[1]).shown and not R(S.plates.focus.edges[1]).shown)
		ns.Set("nameplates.target", false)
		_, S = SD.show(W, "mock-nameplate-marks")
		check("sdplate: with Target and focus border off the game's own marker round the bar is shown instead", R(S.plates.target.edges[1]).shown and not R(S.plates.marked.edges[1]).shown)
		local kinds = { elite = ns.KINDS.elite.colour, rare = ns.KINDS.rare.colour, boss = ns.KINDS.boss.colour }
		local seen = {}
		for kind, colour in pairs(kinds) do
			local edgeColour = R(S.plates[kind].outline.top).color
			seen[#seen + 1] = (SD.near(edgeColour[1], colour[1]) and SD.near(edgeColour[2], colour[2]) and SD.near(edgeColour[3], colour[3])) and "ok" or kind
		end
		check("sdplate: an elite, a rare and a boss have the border of the game's colour of their kind", table.concat(seen, " ") == "ok ok ok", table.concat(seen, " "))
		check("sdplate: and a rare has R after its level, a boss no mark", R(S.plates.rare.mark).text == "R" and not R(S.plates.boss.mark).shown)
		check("sdplate: the border of a kind is 2 pixels, and the plate of no kind has the general thickness", S.plates.elite.outline.px == 2 and S.plates.boss.outline.px == 2 and S.plates.marked.outline.px == nil)

		_, S = SD.show(W, "mock-nameplate-cast")
		local cast, locked = S.plates.cast, S.plates.locked
		check("sdplate: the cast bar fills 60% of its width, and the spell name and the icon are in the cast container",
			SD.near(R(cast.cfill).width, cast.m.BW * 0.6) and R(cast.ctext).text == "Shadow Bolt" and R(cast.cicon).shown and not R(cast.shield).shown, tostring(R(cast.cfill).width))
		check("sdplate: a cast that cannot be interrupted shows the shield and no icon, in the grey of the Colours page",
			R(locked.shield).shown and not R(locked.cicon).shown and SD.near(R(locked.cfill).color[1], 0x9a / 255), tostring(R(locked.cfill).color and R(locked.cfill).color[1]))
		check("sdplate: Cast time is off to begin with and the time is 1.2 when it is on", not R(cast.ctime).shown and R(cast.ctime).text == "1.2")
		check("sdplate: the spark is at the end of the fill and the bar is over the icon", SD.near(R(cast.spark).points[1][4], cast.m.BW * 0.6) and SD.near(R(cast.cbar).points[1][5], cast.m.CI),
			tostring(R(cast.spark).points[1][4]) .. " " .. tostring(R(cast.cbar).points[1][5]))
		ns.Set("nameplates.castTime", true)
		_, S = SD.show(W, "mock-nameplate-cast")
		check("sdplate: Cast time shows the seconds left at the right end of the bar", R(S.plates.cast.ctime).shown and R(S.plates.cast.ctime).points[1][1] == "RIGHT")
		ns.Set("nameplates.castHeight", 200)
		_, S = SD.show(W, "mock-nameplate-cast")
		check("sdplate: Nameplate cast bar height is a percent of the game's: 9.6 at 200% and size 1", SD.near(S.plates.cast.m.CB, 9.6), tostring(S.plates.cast.m.CB))

		_, S = SD.show(W, "mock-nameplate-auras")
		local auras = S.plates.auras
		local shownIcons, counts, timers = 0, 0, 0
		for _, icon in ipairs(auras.icons) do
			if R(icon.frame).shown then shownIcons = shownIcons + 1 end
			if R(icon.count).shown then counts = counts + 1 end
			if R(icon.timer).shown then timers = timers + 1 end
		end
		check("sdplate: five aura icons, each with 12 as its time and a 3 on two of them", shownIcons == 5 and timers == 5 and counts == 2 and R(auras.icons[1].timer).text == "12" and R(auras.icons[2].count).text == "3",
			shownIcons .. " " .. timers .. " " .. counts)
		check("sdplate: the aura icons are 18.75 units at size 1, cropped 8% by default",
			SD.near(R(auras.icons[1].frame).width, 18.75) and SD.near(R(auras.icons[1].texture).texCoord[1], 0.08), tostring(R(auras.icons[1].texture).texCoord and R(auras.icons[1].texture).texCoord[1]))
		ns.Set("nameplates.auraTimers", false)
		ns.Set("nameplates.auraStacks", false)
		ns.Set("nameplates.auraOpacity", 40)
		ns.Set("nameplates.auraCrop", 15)
		_, S = SD.show(W, "mock-nameplate-auras")
		check("sdplate: Countdown numbers, Stack count, Aura opacity and Aura icon crop each change the icons",
			not R(S.plates.auras.icons[1].timer).shown and not R(S.plates.auras.icons[2].count).shown and SD.near(R(S.plates.auras.auras).alpha, 0.4)
			and SD.near(R(S.plates.auras.icons[1].texture).texCoord[1], 0.15))

		ns.Set("nameplates.auras", false)
		_, S = SD.show(W, "mock-nameplate-auras")
		check("sdplate: with Aura icon border off the icons are not cropped and have no thin border", SD.near(R(S.plates.auras.icons[1].texture).texCoord[1], 0) and not R(S.plates.auras.icons[1].outline.top).shown)
		ns.Set("nameplates.size", 2)
		_, S = SD.show(W, "mock-nameplate-stack")
		local far, near, target = S.plates.far, S.plates.near, S.plates.target
		check("sdplate: the target plate is scaled to 120%, the far plate to 80% at 60% opacity, the near plate is full size and opacity",
			SD.near(R(target.f).scale, 1.2) and SD.near(R(far.f).scale, 0.8) and SD.near(R(far.f).alpha, 0.6) and SD.near(R(near.f).scale, 1) and SD.near(R(near.f).alpha, 1),
			R(target.f).scale .. " " .. R(far.f).scale .. " " .. R(far.f).alpha)
		ns.Set("nameplates.notSelectedAlpha", 50)
		ns.Set("nameplates.overlapH", 150)
		ns.Set("nameplates.overlapV", 300)
		_, S = SD.show(W, "mock-nameplate-stack")
		far, near, target = S.plates.far, S.plates.near, S.plates.target
		check("sdplate: Opacity of other nameplates with a target fades the near and the far plate and not the target",
			SD.near(R(near.f).alpha, 0.5) and SD.near(R(far.f).alpha, 0.3) and SD.near(R(target.f).alpha, 1))
		local farPoint, nearPoint, targetPoint = R(far.f).points[1], R(near.f).points[1], R(target.f).points[1]
		local BW, H0 = target.m.BW, target.m.top
		local across = (targetPoint[4] * 1.2 + BW / 2 * 1.2) - (farPoint[4] * 0.8 + BW / 2 * 0.8)
		local up = nearPoint[5] - targetPoint[5] * 1.2
		check("sdplate: Horizontal overlap and Vertical overlap are the steps between plates: the far plate is 1.5 plate widths from the target, the near plate 3 plate heights above it",
			SD.near(across, BW * 1.5) and SD.near(up, H0 * 3), ("%s %s | %s %s"):format(across, BW * 1.5, up, H0 * 3))
		ns.Set("nameplates.showCastBars", false)
		_, S = SD.show(W, "mock-nameplate-stack")
		check("sdplate: Cast bars on nameplates off takes the cast bar off the target plate", not R(S.plates.target.cast).shown)
		ns.Set("nameplates.dim", true)
		ns.Set("nameplates.dimAmount", 100)
		_, S = SD.show(W, "mock-nameplate-stack")
		check("sdplate: Dim other nameplates darkens the plates that are not the target and not the target", R(S.plates.near.over).shown and R(S.plates.far.over).shown and not R(S.plates.target.over).shown
			and SD.near(R(S.plates.near.over).color[4], 0.5), tostring(R(S.plates.near.over).color and R(S.plates.near.over).color[4]))
	end

	-- A stage smaller than the canvas, huge plates, and two stages of one drawing.
	do
		local W = SD.world()
		local ns = W.ns
		local function R(x) return W.rawOf[x] end
		local stage, S = SD.show(W, "mock-nameplate", 329, 102)
		check("sdplate: a stage half the size of the canvas draws it at half scale", SD.near(R(S.root).scale, 0.5) and SD.near(S.fit, 1), tostring(R(S.root).scale))
		ns.Set("nameplates.size", 5)
		ns.Set("nameplates.style", "modern")
