		local second, S2 = SD.show(W, "mock-nameplate")
		check("sdplate: two stages of one drawing have frames of their own", S1 ~= S2 and S1.root ~= S2.root and S1.plates.enemy.f ~= S2.plates.enemy.f)
		ns.Set("nameplates.nameSize", 200)
		ns.SetupDrawings["mock-nameplate"].draw(first)
		ns.SetupDrawings["mock-nameplate"].draw(second)
		check("sdplate: and each is drawn again from the rows", SD.near(S1.plates.enemy.m.NH, 22.4) and SD.near(S2.plates.enemy.m.NH, 22.4))
		check("sdplate: the parts of a drawing are its own for each stage, and the first stage keeps its own",
			ns.SetupDrawings["mock-nameplate"].partsOf(first)["nameplates.nameSize"] == S1.plates.enemy.name and ns.SetupDrawings["mock-nameplate"].partsOf(second)["nameplates.nameSize"] == S2.plates.enemy.name)
		ns.Set("nameplates.enabled", false)
		ns.SetupDrawings["mock-nameplate"].draw(first)
		local game = S1.plates.enemy
		check("sdplate: with Restyle nameplates off a plate has the game's own look: no thin border, its dark band, the level box art, no + after the level",
			R(game.band).shown == true and R(game.outline.top).shown == false and R(game.lvlArt).shown and not R(game.mark).shown and not R(S1.plates.elite.mark).shown and R(game.name).font[3] == "OUTLINE")
	end

	-- The view a stage names reaches every outline of the drawing, where the client of this build has the functions.
	do
		local W = SD.world()
		local ns = W.ns
		local seen, repainted = {}, 0
		ns.SetOutlineView = function(_, view) seen[#seen + 1] = view end
		ns.RepaintOutline = function() repainted = repainted + 1 end
		local stage = SD.stage(W)
		local view = {}
		stage.view = view
		SD.draw(W, "mock-nameplate-cast", stage)
		local first = #seen
		local count = repainted
		check("sdplate: every outline of a drawing follows the view its stage names, and is painted again on each draw", first >= 10 and seen[1] == view and seen[first] == view and count == first, first .. " " .. count)
		local other = {}
		stage.view = other
		SD.draw(W, "mock-nameplate-cast", stage)
		check("sdplate: and a view the stage names later reaches them all", #seen == 2 * first and seen[#seen] == other and repainted == 2 * count, #seen .. " " .. repainted)
	end

	-- The level box as a square, the class icon at the bar height and the marker moved out past it, as the preview draws them.
	do
		local W = SD.world()
		local ns = W.ns
		local function R(x) return W.rawOf[x] end
		local T = {}
		local _, S = SD.show(W, "mock-nameplate")
		local m = S.plates.enemy.m
		check("squared: sdplate: under Square the level box is as wide as the bar is high and the bar ends before it", SD.near(m.LW, m.HH) and SD.near(m.LH, m.HH) and SD.near(m.HW, m.BW - m.HH - 0),
			("%s %s %s"):format(m.LW, m.HH, m.HW))
		ns.Set("nameplates.levelGap", 3)
		_, S = SD.show(W, "mock-nameplate")
		m = S.plates.enemy.m
		T.lvl = R(S.plates.enemy.lvl).points[1]
		check("squared: sdplate: the gap is kept between the bar and the box, and the box ends where the plate does", SD.near(m.HW, m.BW - (m.HH + 3)) and SD.near(T.lvl[4] + m.LW, m.BW), ("%s %s"):format(m.HW, T.lvl[4]))
		ns.Set("nameplates.levelShape", "game")
		_, S = SD.show(W, "mock-nameplate")
		m = S.plates.enemy.m
		check("squared: sdplate: Game width keeps the game's box and its gap of 5, whatever the gap is", SD.near(m.LW, 22.4) and SD.near(m.HW, m.BW - (22.4 + 5)), ("%s %s"):format(m.LW, m.HW))
		ns.Set("nameplates.levelShape", "square")
		ns.Set("nameplates.level", "default")
		_, S = SD.show(W, "mock-nameplate")
		m = S.plates.enemy.m
		check("squared: sdplate: the Default box is the game's whatever the shape is", SD.near(m.LW, 22.4) and SD.near(m.HW, m.BW - (22.4 + 5)), ("%s %s"):format(m.LW, m.HW))
		ns.Set("nameplates.level", "box")
		ns.Set("nameplates.levelGap", 0)

		-- The class icon: the bar height or Custom, and the gap on each side.
		_, S = SD.show(W, "mock-nameplate-marks")
		local player, friend = S.plates.player, S.plates.friend
		m = player.m
		T.at = R(player.iconFrame).points[1]
		check("squared: sdplate: the class icon is the bar height by default, on the left, flush with the row", SD.near(R(player.iconFrame).width, m.HH) and T.at[1] == "RIGHT" and SD.near(T.at[4], 0), ("%s %s"):format(R(player.iconFrame).width, T.at[4]))
		ns.Set("nameplates.classGap", 2)
		_, S = SD.show(W, "mock-nameplate-marks")
		T.at = R(S.plates.player.iconFrame).points[1]
		check("squared: sdplate: the gap moves the left icon out", SD.near(T.at[4], -2), tostring(T.at[4]))
		ns.Set("nameplates.classFit", "own")
		ns.Set("nameplates.classSize", 30)
		_, S = SD.show(W, "mock-nameplate-marks")
		check("squared: sdplate: Custom gives the size set", SD.near(R(S.plates.player.iconFrame).width, 30))
		ns.Set("nameplates.classFit", "bar")

		-- The marker of a friendly player with the icon on moves out past the icon and its gap, and the flag and the buffs of an enemy player with it.
		ns.Set("nameplates.classFriendly", true)
		_, S = SD.show(W, "mock-nameplate-marks")
		friend, player = S.plates.friend, S.plates.player
		m = friend.m
		T.mark = R(friend.marker).points[1]
		check("squared: sdplate: the marker of a friendly player with the icon on the left moves out past the icon and its gap", SD.near(T.mark[4], -(m.HH + 2)), tostring(T.mark[4]))
		T.flag, T.buff = R(player.flag).points[1], R(player.buffA).points[1]
		check("squared: sdplate: the flag of an enemy player starts at the left edge of the icon and the buffs follow it", R(player.flag).shown and SD.near(T.flag[4], -(m.HH + 2)) and SD.near(T.buff[4], -(m.HH + 2) - 25)
			and R(player.buffB).shown, ("%s %s"):format(T.flag[4], T.buff[4]))
		ns.Set("nameplates.raidMarkerX", 5)
		_, S = SD.show(W, "mock-nameplate-marks")
		T.mark = R(S.plates.friend.marker).points[1]
		check("squared: sdplate: the marker's own offset adds to the move", SD.near(T.mark[4], 5 - (m.HH + 2)), tostring(T.mark[4]))
		ns.Set("nameplates.raidMarkerX", 0)
		ns.Set("nameplates.classPosition", "right")
		_, S = SD.show(W, "mock-nameplate-marks")
		T.mark, T.flag = R(S.plates.friend.marker).points[1], R(S.plates.player.flag).points[1]
		check("squared: sdplate: with the icon on the right the marker and the flag start at the row", SD.near(T.mark[4], 0) and SD.near(T.flag[4], 0), ("%s %s"):format(T.mark[4], T.flag[4]))
		T.at = R(S.plates.player.iconFrame).points[1]
		check("squared: sdplate: the right icon is a gap after the row", T.at[1] == "LEFT" and SD.near(T.at[4], S.plates.player.m.BW + 2), tostring(T.at[4]))
		ns.Set("nameplates.classPosition", "left")
		ns.Set("nameplates.classEnemy", false)
		_, S = SD.show(W, "mock-nameplate-marks")
		T.flag = R(S.plates.player.flag).points[1]
		check("squared: sdplate: with no icon the flag starts at the row", SD.near(T.flag[4], 0), tostring(T.flag[4]))
	end

	-- A drawn setting changes the drawing.
	do
		local W = SD.world()
		local stages, base = {}, {}
		for _, id in ipairs(SD.DRAWINGS) do
			stages[id] = SD.stage(W)
			SD.draw(W, id, stages[id])
			base[id] = SD.fingerprint(W, stages[id])
		end
		local steady = true
		for _, id in ipairs(SD.DRAWINGS) do
			W.ns.SetupDrawings[id].draw(stages[id])
			steady = steady and SD.fingerprint(W, stages[id]) == base[id]
		end
		check("sdplate: drawing again with no change leaves every frame and region as it was", steady)
		local tried, misses, partsMissing, errors = 0, {}, {}, {}
		for _, row in ipairs(SD.ROWS) do
			local path, id, alt, pre = row[1], row[2], row[3], row[4]
			local W2 = SD.world()
			local stage = SD.stage(W2)
			local drawing = W2.ns.SetupDrawings[id]
			for _, set in ipairs(pre) do
				W2.ns.Set(set[1], set[2])
			end
			local ok, err = pcall(SD.draw, W2, id, stage)
			local before = ok and SD.fingerprint(W2, stage)
			if ok then
				W2.ns.Set(path, alt)
				ok, err = pcall(SD.draw, W2, id, stage)
			end
			if not ok then
				errors[#errors + 1] = path .. ": " .. tostring(err)
			else
				if SD.fingerprint(W2, stage) == before then
					misses[#misses + 1] = path
				end
				if (drawing.partsOf(stage))[path] == nil then
					partsMissing[#partsMissing + 1] = path
				end
			end
			tried = tried + 1
		end
		check("sdplate: the 96 drawn settings of steps 5 to 11 were tried", tried == 96, tried)
		check("sdplate: no drawn setting raises an error while its drawing is drawn", #errors == 0, table.concat(errors, " | "))
		check("sdplate: every drawn setting changes its drawing", #misses == 0, table.concat(misses, ", "))
		check("sdplate: every drawn setting names the region it changes", #partsMissing == 0, table.concat(partsMissing, ", "))
	end
end
-- >>> sdplate (end)

-- >>> sdbars (begin)
-- Setup drawings of the action bar steps (FlatUI/SetupDrawBars.lua): mock-action-row, mock-bar-block, mock-block-places and mock-fade. Every label starts "sdbars".
-- Each drawn setting of steps 12, 48, 49 and 50 (research/flatui-wizard/groups.json) is written with ns.Set and its drawing must come out different: every
-- frame and texture of the drawing is fingerprinted (shown, size, points, alpha, colour, file, texture coordinates, tint, text, font). The gates of a row
-- are on first, and PRE has what a row needs to show anything (a bar picked before its position, a gap or an own border that is not the one in use).
do
	local S = { DRAW = { actionbars = "mock-action-row", barblock = "mock-bar-block", blocks = "mock-block-places", fade = "mock-fade" } }
	S.PRE = { ["actionbars.lookOwn"] = { ["actionbars.lookBorder"] = "ff336699" }, ["barblock.ownGap"] = { ["barblock.barGap"] = 12 }, ["blocks.classPlace"] = { ["blocks.classBar"] = "bar3" },
		["blocks.buffsPlace"] = { ["blocks.buffsBar"] = "bar4" }, ["blocks.consumablesPlace"] = { ["blocks.consumablesBar"] = "bar5" },
		["blocks.gap"] = { ["blocks.classBar"] = "bar3", ["blocks.classPlace"] = "aboveLeft" } }
	S.CASES = {
		{ "actionbars.enabled", false, {} },
		{ "actionbars.main", false, { "actionbars.enabled" } },
		{ "actionbars.extra", false, { "actionbars.enabled" } },
		{ "actionbars.pet", false, { "actionbars.enabled" } },
		{ "actionbars.stance", false, { "actionbars.enabled" } },
		{ "actionbars.backdrop", false, { "actionbars.enabled" } },
		{ "actionbars.crop", 15, { "actionbars.enabled" } },
		{ "actionbars.square", false, { "actionbars.enabled" } },
		{ "actionbars.tints", false, { "actionbars.enabled" } },
		{ "actionbars.frame", false, { "actionbars.enabled" } },
		{ "actionbars.caps", false, { "actionbars.enabled" } },
		{ "actionbars.dividers", false, { "actionbars.enabled" } },
		{ "actionbars.lookOwn", true, { "actionbars.enabled" } },
		{ "actionbars.lookBorder", "ffff0000", { "actionbars.lookOwn", "actionbars.enabled" } },
		{ "actionbars.lookBack", "ff00ff00", { "actionbars.lookOwn", "actionbars.enabled" } },
		{ "actionbars.lookBackAlpha", 35, { "actionbars.lookOwn", "actionbars.enabled" } },
		{ "barblock.enabled", true, {} },
		{ "barblock.slot1", "bar5", { "barblock.enabled" } },
		{ "barblock.slot2", "bar4", { "barblock.enabled" } },
		{ "barblock.slot3", "bar6", { "barblock.enabled" } },
		{ "barblock.slot4", "bar7", { "barblock.enabled" } },
		{ "barblock.slot5", "bar8", { "barblock.enabled" } },
		{ "barblock.slot6", "bar5", { "barblock.enabled" } },
		{ "barblock.direction", "down", { "barblock.enabled" } },
		{ "barblock.align", "left", { "barblock.enabled" } },
		{ "barblock.ownGap", true, { "barblock.enabled" } },
		{ "barblock.barGap", 12, { "barblock.ownGap", "barblock.enabled" } },
		{ "barblock.others", "game", { "barblock.enabled" } },
		{ "barblock.background", true, { "barblock.enabled" } },
		{ "barblock.backgroundPad", 16, { "barblock.background", "barblock.enabled" } },
		{ "barblock.fade", true, { "barblock.enabled" } },
		{ "barblock.fadeTo", 60, { "barblock.fade", "barblock.enabled" } },
		{ "blocks.enabled", false, {} },
		{ "blocks.classBar", "bar3", { "blocks.enabled" } },
		{ "blocks.buffsBar", "bar4", { "blocks.enabled" } },
		{ "blocks.consumablesBar", "bar5", { "blocks.enabled" } },
		{ "blocks.from", "bar4", { "blocks.enabled" } },
		{ "blocks.classPlace", "aboveLeft", { "blocks.enabled" } },
		{ "blocks.buffsPlace", "belowRight", { "blocks.enabled" } },
		{ "blocks.consumablesPlace", "rightTop", { "blocks.enabled" } },
		{ "blocks.gap", 16, { "blocks.enabled" } },
		{ "blocks.petPlace", "aboveRight", { "blocks.enabled" } },
		{ "fade.enabled", true, {} },
		{ "fade.main", true, { "fade.enabled" } },
		{ "fade.bar2", true, { "fade.enabled" } },
		{ "fade.bar3", true, { "fade.enabled" } },
		{ "fade.bar4", true, { "fade.enabled" } },
		{ "fade.bar5", true, { "fade.enabled" } },
		{ "fade.bar6", true, { "fade.enabled" } },
		{ "fade.bar7", true, { "fade.enabled" } },
		{ "fade.bar8", true, { "fade.enabled" } },
		{ "fade.stance", true, { "fade.enabled" } },
		{ "fade.pet", true, { "fade.enabled" } },
		{ "fade.micro", true, { "fade.enabled" } },
		{ "fade.bags", true, { "fade.enabled" } },
		{ "fade.playerFrame", true, { "fade.enabled" } },
		{ "fade.petFrame", true, { "fade.enabled" } },
		{ "fade.minimapButtons", true, { "fade.enabled" } },
		{ "fade.alpha", 60, { "fade.enabled" } },
	}
	local function num(v)
		return type(v) == "number" and ("%.3f"):format(v) or tostring(v)
	end
	local function list(t)
		local out = {}
		for index = 1, t and #t or 0 do
			out[index] = num(t[index])
		end
		return table.concat(out, ",")
	end
	function S.points(raw)
		local out = {}
		for _, p in ipairs(raw.points or {}) do
			out[#out + 1] = ("%s>%s:%s:%s"):format(p[1], tostring(p[3]), num(p[4]), num(p[5]))
		end
		return table.concat(out, "|") .. (raw.allPoints and "+all" or "")
	end
	function S.reg(r)
		return table.concat({ r.kind or "?", tostring(r.shown), num(r.width), num(r.height), S.points(r), num(r.alpha), list(r.color), tostring(r.file), list(r.texCoord),
			list(r.vertex), tostring(r.text), tostring(r.fontObject) }, ";")
	end
	function S.fp(raw, out)
		out[#out + 1] = table.concat({ "frame", tostring(raw.shown), num(raw.width), num(raw.height), S.points(raw), num(raw.alpha), num(raw.scale) }, ";")
		for _, r in ipairs(raw.regions or {}) do
			out[#out + 1] = S.reg(r)
		end
		for _, child in ipairs(raw.children or {}) do
			S.fp(child, out)
		end
		return out
	end
	function S.print(raw)
		return table.concat(S.fp(raw, {}), "\n")
	end
	-- The first point of a frame: its x and y in the box it hangs from.
	function S.at(frame)
		local p = frame.points[1]
		return p[4], p[5]
	end
	local W = newWorld({})
	W.login()
	local ns = W.ns
	local drawings = ns.SetupDrawings or {}
	local shaped = true
	for _, id in pairs(S.DRAW) do
		local d = drawings[id]
		shaped = shaped and type(d) == "table" and type(d.build) == "function" and type(d.draw) == "function" and type(d.parts) == "table"
	end
	check("sdbars: the four drawings are registered, each with build, draw and parts", shaped)
	local stage = {}
	for key, id in pairs(S.DRAW) do
		local root = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		root:SetSize(658, 204)
		stage[key] = root
		drawings[id].build(root)
		drawings[id].draw(root)
	end
	local changed, failed = 0, {}
	for _, case in ipairs(S.CASES) do
		local path, alt, gates = case[1], case[2], case[3]
		local key = path:match("^(%w+)%.")
		local d, root = drawings[S.DRAW[key]], stage[key]
		local touch, saved = { path }, {}
		for _, gate in ipairs(gates) do
			touch[#touch + 1] = gate
		end
		for p in pairs(S.PRE[path] or {}) do
			touch[#touch + 1] = p
		end
		for _, p in ipairs(touch) do
			saved[p] = ns.Get(p)
		end
		for _, gate in ipairs(gates) do
			ns.Set(gate, true)
		end
		for p, v in pairs(S.PRE[path] or {}) do
			ns.Set(p, v)
		end
		d.draw(root)
		local before = S.print(root)
		ns.Set(path, alt)
		d.draw(root)
		local after = S.print(root)
		local took = ns.Get(path) == alt
		if before ~= after and took then
			changed = changed + 1
		else
			failed[#failed + 1] = path
		end
		check("sdbars: " .. path .. " changes its drawing", before ~= after and took, took and "same drawing" or "the setting was refused")
		for _, p in ipairs(touch) do
			ns.Set(p, saved[p])
		end
		d.draw(root)
	end
	check("sdbars: " .. #S.CASES .. " of " .. #S.CASES .. " drawn settings change their drawing", changed == #S.CASES and #S.CASES == 59, table.concat(failed, ","))
	-- The same drawing made again from the same settings is the same drawing.
	for key, id in pairs(S.DRAW) do
		local first = S.print(stage[key])
		drawings[id].draw(stage[key])
		check("sdbars: " .. id .. " drawn twice from the same settings is the same drawing", S.print(stage[key]) == first)
	end
	-- Every drawn path has a region to bracket.
	local missing = {}
	for _, case in ipairs(S.CASES) do
		local d = drawings[S.DRAW[case[1]:match("^(%w+)%.")]]
		if type(d.parts[case[1]]) ~= "table" then
			missing[#missing + 1] = case[1]
		end
	end
