	-- Action buttons: what the page switches.
	do
		local d = drawings["mock-action-row"]
		local inst = d.built[stage.actionbars]
		local main = inst.rows[1]
		check("sdbars action: the game's bar art, end caps and dividers are gone, as the page's defaults say",
			main.art.shown == false and main.capLeft.shown == false and main.dividers[1].frame.shown == false)
		ns.Set("actionbars.frame", false)
		ns.Set("actionbars.caps", false)
		ns.Set("actionbars.dividers", false)
		d.draw(stage.actionbars)
		check("sdbars action: with Hide bar frame, Hide end caps and Hide dividers off the art, caps and dividers are drawn",
			main.art.shown == true and main.capLeft.shown == true and main.capRight.shown == true and main.dividers[2].frame.shown == true)
		ns.Set("actionbars.frame", true)
		ns.Set("actionbars.caps", true)
		ns.Set("actionbars.dividers", true)
		local hover = main.buttons[3]
		d.draw(stage.actionbars)
		check("sdbars action: a hovered button has the flat white tint and a cooling button a sweep with its number",
			hover.tint.shown == true and list(hover.tint.color) == "1.000,1.000,1.000,0.200" and main.buttons[8].sweep.shown == true and main.buttons[8].sweepText.text == "8"
			and main.buttons[1].sweep.shown == false, list(hover.tint.color))
		ns.Set("actionbars.tints", false)
		d.draw(stage.actionbars)
		check("sdbars action: with Flat highlights off the tint is the game's own, grey where the client has no atlas for it", list(hover.tint.color) == "0.800,0.800,0.800,0.350", list(hover.tint.color))
		ns.Set("actionbars.tints", true)
		W.env.KEY_BUTTON4, W.env.KEY_NUMPAD1 = "Mouse Button 4", "Num Pad 1"
		ns.Set("actionbars.hotkeyText", "short")
		d.draw(stage.actionbars)
		local extra = inst.rows[2].buttons
		check("sdbars action: Hotkey text short shows M4 and N1 on the second bar, in a box of the button's width less 8 that does not wrap",
			extra[9].key.text == "M4" and extra[10].key.text == "N1" and d.parts["actionbars.hotkeyText"] == extra[9].frame
			and extra[9].key.width == extra[9].frame.width - 8 and extra[9].key.height == 10 and extra[9].key.wordWrap == false and extra[9].key.justify == "RIGHT", tostring(extra[9].key.text) .. " " .. tostring(extra[9].key.width))
		ns.Set("actionbars.hotkeyText", "game")
		d.draw(stage.actionbars)
		check("sdbars action: Hotkey text game shows the long names", extra[9].key.text == "Mouse Button 4" and extra[10].key.text == "Num Pad 1", tostring(extra[9].key.text))
		ns.Set("actionbars.hotkeyText", "short")
		ns.Set("actionbars.square", false)
		d.draw(stage.actionbars)
		check("sdbars action: with Square icons off the icon is inset and the sweep keeps the button's size",
			#main.buttons[1].icon.points == 2 and main.buttons[8].sweep.allPoints == main.buttons[8].frame)
		ns.Set("actionbars.square", true)
		ns.Set("actionbars.crop", 15)
		d.draw(stage.actionbars)
