		ns.Set("actionbars.pet", true)
		d.draw(stage.actionbars)
		-- Rows: sizes, pitch and the key of a small button are the game's (ActionButtonTemplate.xml:15-16, 20 and 198-204).
		local extra, pet, stance = inst.rows[2], inst.rows[3], inst.rows[4]
		check("sdbars action: the pet and stance buttons are 30 units square and the main and extra buttons 45",
			pet.buttons[1].frame.width == 30 and pet.buttons[1].frame.height == 30 and stance.buttons[10].frame.width == 30 and pet.holder.height == 30
			and stance.holder.height == 30 and main.buttons[1].frame.width == 45 and extra.buttons[1].frame.height == 45 and main.holder.height == 45,
			("%s %s"):format(num(pet.buttons[1].frame.width), num(pet.holder.height)))
		local _, mainY = S.at(main.holder)
		local _, extraY = S.at(extra.holder)
		local _, petY = S.at(pet.holder)
		local _, stanceY = S.at(stance.holder)
		check("sdbars action: the rows are 10 units apart whatever their button size", mainY - extraY == 45 + 10 and extraY - petY == 30 + 10 and petY - stanceY == 30 + 10,
			("%s %s %s"):format(num(mainY - extraY), num(extraY - petY), num(petY - stanceY)))
		local kp, ks = main.buttons[1].key.points[1], pet.buttons[1].key.points[1]
		check("sdbars action: the key sits at -4, -5 on a button and -3, -4 on a small one", kp[4] == -4 and kp[5] == -5 and ks[4] == -3 and ks[5] == -4, ("%s %s"):format(num(ks[4]), num(ks[5])))
		check("sdbars action: the main bar has a divider between every two buttons", #main.dividers == 11 and S.at(main.dividers[11].frame) == 11 * (45 + 2) - 2, tostring(#main.dividers))
		check("sdbars action: with every group restyled and the game's art off no Game look label is shown", inst.gameLabel.shown == false)
