		check("sdbars action: with Restyle action bars off the end caps are drawn", main.capLeft.shown == true and main.capRight.shown == true)
		check("sdbars action: with Restyle action bars off the dividers are drawn", main.dividers[1].frame.shown == true and main.dividers[11].frame.shown == true)
		check("sdbars action: where the client has no atlas the game's art is plain grey, with one Game look label",
			inst.gameLabel.shown == true and inst.gameLabel.text == "Game look" and list(main.art.color) == "0.300,0.300,0.300,1.000"
			and list(main.capLeft.color) == "0.420,0.420,0.420,1.000" and list(main.buttons[1].slot.color) == "0.500,0.500,0.500,1.000", list(main.art.color))
		ns.Set("actionbars.enabled", true)
