			ns.Set("actionbars." .. key, true)
			d.draw(stage.actionbars)
		end
		-- A client that answers for the atlases: the game's art is drawn with them and no label is shown.
		local A = newWorld({})
		local known = {}
		for _, name in ipairs({ "ui-hud-actionbar-iconframe-slot", "UI-HUD-ActionBar-Frame", "ui-hud-actionbar-gryphon-left", "ui-hud-actionbar-gryphon-right",
			"UI-HUD-ActionBar-Frame-Divider-ThreeSlice-EdgeTop", "_UI-HUD-ActionBar-Frame-Divider-Threeslice-Center", "UI-HUD-ActionBar-Frame-Divider-ThreeSlice-EdgeBottom",
			"UI-HUD-ActionBar-IconFrame-Down", "UI-HUD-ActionBar-IconFrame-Mouseover", "UI-HUD-ActionBar-IconFrame-Flash" }) do
			known[name] = true
		end
		A.env.C_Texture = { GetAtlasInfo = function(name) return known[name] and { width = 64, height = 64 } or nil end }
		A.login()
		local aroot = A.env.CreateFrame("Frame", nil, A.env.UIParent)
		aroot:SetSize(658, 204)
		local ad = A.ns.SetupDrawings["mock-action-row"]
		ad.build(aroot)
		A.ns.Set("actionbars.enabled", false)
		ad.draw(aroot)
		local am = ad.built[aroot].rows[1]
		check("sdbars action: where the client answers the bar art, caps and slot are the game's atlases",
			am.art.atlas == "UI-HUD-ActionBar-Frame" and am.capLeft.atlas == "ui-hud-actionbar-gryphon-left" and am.capRight.atlas == "ui-hud-actionbar-gryphon-right"
			and am.buttons[1].slot.atlas == "ui-hud-actionbar-iconframe-slot", tostring(am.art.atlas))
		check("sdbars action: where the client answers a divider is the three slices and a hovered button the game's highlight",
			am.dividers[1].top.atlas == "UI-HUD-ActionBar-Frame-Divider-ThreeSlice-EdgeTop" and am.dividers[1].bottom.atlas == "UI-HUD-ActionBar-Frame-Divider-ThreeSlice-EdgeBottom"
			and am.buttons[3].tint.atlas == "UI-HUD-ActionBar-IconFrame-Mouseover" and am.buttons[2].tint.atlas == "UI-HUD-ActionBar-IconFrame-Down", tostring(am.buttons[3].tint.atlas))
		check("sdbars action: where the client answers every atlas there is no Game look label and no violation",
			ad.built[aroot].gameLabel.shown == false and #A.violations == 0 and #A.errors == 0, tostring(A.violations[1] or A.errors[1] or ""))
	end
	-- Bar block: rows, gap, alignment, direction, bars above, panel and fade.
	do
		-- The two status bars of this drawing are the game's here; the xpown block checks Flat UI's own bar in it.
		ns.Set("hud.xpOwn", "game")
		local d = drawings["mock-bar-block"]
		local inst = d.built[stage.barblock]
		local function tags()
			local out = {}
			for _, bar in ipairs(inst.pool.bar) do
				if bar.frame.shown then
					out[#out + 1] = bar.text.text
				end
			end
			return table.concat(out, ",")
		end
		d.draw(stage.barblock)
		check("sdbars block: the block off shows the three bars in the game's stack", tags() == "Main action bar,Action bar 2,Action bar 3", tags())
		ns.Set("barblock.enabled", true)
		d.draw(stage.barblock)
		check("sdbars block: the block on shows the bars of the rows in order", tags() == "Main action bar,Action bar 2,Action bar 3", tags())
		local x1, y1 = S.at(d.parts["barblock.slot1"])
		local x2, y2 = S.at(d.parts["barblock.slot2"])
		local x3 = S.at(d.parts["barblock.slot3"])
		check("sdbars block: upward, the second bar is a button and the gap above the first, and Centre centres the narrower bars",
			y2 - y1 == 45 + 2 and x2 - x1 == 1 * (45 + 2) and x3 - x1 == 2 * (45 + 2), ("%s %s %s"):format(num(y2 - y1), num(x2 - x1), num(x3 - x1)))
		ns.Set("barblock.direction", "down")
		d.draw(stage.barblock)
		local _, down1 = S.at(d.parts["barblock.slot1"])
		local _, down2 = S.at(d.parts["barblock.slot2"])
		check("sdbars block: downward, the second bar is below the first", down2 < down1)
		ns.Set("barblock.direction", "up")
		ns.Set("barblock.align", "left")
		d.draw(stage.barblock)
		local lx1 = S.at(d.parts["barblock.slot1"])
		local lx3 = S.at(d.parts["barblock.slot3"])
		ns.Set("barblock.align", "right")
		d.draw(stage.barblock)
		local rx1 = S.at(d.parts["barblock.slot1"])
		local rx3 = S.at(d.parts["barblock.slot3"])
		check("sdbars block: Left puts the narrower bar at the left edge and Right at the right edge", lx3 == lx1 and rx3 - rx1 == 4 * (45 + 2), ("%s %s"):format(num(rx3 - rx1), num(lx3 - lx1)))
		ns.Set("barblock.align", "center")
		ns.Set("barblock.ownGap", true)
		ns.Set("barblock.barGap", 12)
