		local _, g1 = S.at(d.parts["barblock.slot1"])
		local _, g2 = S.at(d.parts["barblock.slot2"])
		check("sdbars block: an own gap is the number of units between the bars", g2 - g1 == 45 + 12, num(g2 - g1))
		ns.Set("barblock.ownGap", false)
		ns.Set("barblock.background", true)
		ns.Set("barblock.backgroundPad", 10)
		d.draw(stage.barblock)
		check("sdbars block: the background panel is the block and the padding on every side", inst.pool.panel.shown == true and inst.pool.panel.width == 12 * 45 + 11 * 2 + 20
			and inst.pool.panel.height == 3 * 45 + 2 * 2 + 20, ("%s %s"):format(num(inst.pool.panel.width), num(inst.pool.panel.height)))
		ns.Set("barblock.fade", true)
		ns.Set("barblock.fadeTo", 60)
		d.draw(stage.barblock)
