			elseif xp.label.text == "Status bar 2" then
				xpDown = xp
			end
		end
		check("sdbars block: each experience bar has its name", xpUp ~= nil and xpDown ~= nil and xpUp.label.shown == true)
		check("sdbars block: the two experience bars are one unit closer than touching, the second over the first",
