				ownUp = xp
			elseif xp.label.text == "Status bar 2" then
				ownDown = xp
			end
		end
		check("xpown: setup: with Flat UI's bar the two status bars of the Bar block drawing are 35% of the game's width and 8 high, with the space of the row between them",
			ownUp ~= nil and ownDown ~= nil and math.abs(ownUp.frame.width - 417.2) < 1e-6 and ownUp.frame.height == 8 and ownDown.frame.height == 8
				and select(2, S.at(ownUp.frame)) - (select(2, S.at(ownDown.frame)) + 8) == 2, ownUp and tostring(ownUp.frame.width))
		ns.Set("hud.xpOwn", "game")
		d.draw(stage.barblock)
		ns.Set("barblock.others", "game")
		d.draw(stage.barblock)
		check("sdbars block: bars left to the game are drawn dim beside the block, not faded", inst.pool.xp[1].frame.alpha == 0.5 and inst.pool.small[1].frame.alpha == 0.5)
		check("sdbars block: the dim column is named Left to the game", inst.pool.column.shown == true and inst.pool.column.text == "Left to the game")
		ns.Set("barblock.others", "above")
		ns.Set("barblock.fade", false)
		ns.Set("barblock.background", false)
		ns.Set("barblock.enabled", false)
		d.draw(stage.barblock)
	end
	-- Class, buffs and consumables bars: the positions round the reference.
	do
		local d = drawings["mock-block-places"]
		local inst = d.built[stage.blocks]
		d.draw(stage.blocks)
		local mx, my = S.at(inst.pool.bar[1].frame)
		ns.Set("blocks.classBar", "bar3")
		ns.Set("blocks.classPlace", "aboveLeft")
		ns.Set("blocks.buffsBar", "bar4")
		ns.Set("blocks.buffsPlace", "aboveLeft")
		ns.Set("blocks.consumablesBar", "bar5")
		ns.Set("blocks.consumablesPlace", "belowRight")
		d.draw(stage.blocks)
		local main = inst.pool.bar[1].frame
		mx, my = S.at(main)
		local cx, cy = S.at(d.parts["blocks.classBar"])
		local bx, by = S.at(d.parts["blocks.buffsBar"])
		local ox, oy = S.at(d.parts["blocks.consumablesBar"])
		check("sdbars places: above, left puts the bar over the reference at its left edge with the gap between, and a second bar there stacks outward",
			cx == mx and cy == my + 45 + 4 and bx == mx and by == cy + 45 + 4, ("%s %s %s %s"):format(num(cx - mx), num(cy - my), num(bx - mx), num(by - cy)))
		check("sdbars places: below, right puts the bar under the reference at its right edge", ox + 6 * 45 + 5 * 2 == mx + 12 * 45 + 11 * 2 and oy == my - 4 - 45, ("%s %s"):format(num(ox - mx), num(oy - my)))
		ns.Set("blocks.consumablesPlace", "rightTop")
		ns.Set("blocks.buffsPlace", "leftBottom")
		d.draw(stage.blocks)
		mx, my = S.at(main)
		local rx, ry = S.at(d.parts["blocks.consumablesBar"])
		local lx, ly = S.at(d.parts["blocks.buffsBar"])
		check("sdbars places: right, top starts a gap past the right edge at the top, and left, bottom ends a gap before the left edge at the bottom",
			rx == mx + 12 * 45 + 11 * 2 + 4 and ry == my and lx + 6 * 45 + 5 * 2 + 4 == mx and ly == my, ("%s %s %s %s"):format(num(rx - mx), num(ry - my), num(lx - mx), num(ly - my)))
		ns.Set("blocks.classPlace", "free")
		d.draw(stage.blocks)
		local fx = S.at(d.parts["blocks.classBar"])
		check("sdbars places: a bar that stays where its handle is has a dim place of its own beside the rest", fx > mx + 12 * 45 and d.parts["blocks.classBar"].alpha == 0.5)
		ns.Set("blocks.classBar", "bar2")
		ns.Set("blocks.from", "bar2")
		d.draw(stage.blocks)
		check("sdbars places: the bar the blocks hang from is the reference and is not placed again", d.parts["blocks.classBar"] == inst.box)
		-- A bar of the block is not placed again, a place over the block clears the bars above it, and a bar chosen twice is placed once.
		local keep = {}
		local names = { "barblock.enabled", "barblock.slot1", "barblock.slot2", "barblock.slot3", "barblock.slot4", "barblock.slot5", "barblock.slot6", "barblock.others",
			"blocks.enabled", "blocks.gap", "blocks.classBar", "blocks.classPlace", "blocks.buffsBar", "blocks.buffsPlace", "blocks.consumablesBar" }
		for _, p in ipairs(names) do
			keep[p] = ns.Get(p)
		end
		local function shownBars()
			local n = 0
			for _, bar in ipairs(inst.pool.bar) do
				n = n + (bar.frame.shown and 1 or 0)
			end
			return n
		end
		ns.Set("barblock.enabled", true)
		ns.Set("barblock.slot1", "main")
		ns.Set("barblock.slot2", "bar3")
		for index = 3, 6 do
			ns.Set("barblock.slot" .. index, "none")
		end
		ns.Set("barblock.others", "above")
		ns.Set("blocks.enabled", true)
		ns.Set("blocks.gap", 6)
		ns.Set("blocks.buffsBar", "none")
		ns.Set("blocks.consumablesBar", "none")
		ns.Set("blocks.classBar", "bar3")
		ns.Set("blocks.classPlace", "aboveLeft")
		d.draw(stage.blocks)
		check("sdbars places: a bar that is a row of the Bar block is not placed again", d.parts["blocks.classBar"] == inst.box and shownBars() == 2, tostring(shownBars()))
		ns.Set("blocks.classBar", "bar4")
		d.draw(stage.blocks)
		local bx0, by0 = S.at(inst.pool.bar[1].frame)
		local stx, sty = S.at(inst.pool.small[1].frame)
		local kx, ky = S.at(d.parts["blocks.classBar"])
		check("sdbars places: above the block a bar starts one gap over the stance and pet row, at the left edge of the block", ky == sty + 30 + 6 and kx == bx0 and ky > by0 + 2 * 45,
			("%s %s %s"):format(num(ky - sty), num(kx - bx0), num(ky - by0)))
		ns.Set("blocks.buffsBar", "bar4")
		ns.Set("blocks.buffsPlace", "belowRight")
		d.draw(stage.blocks)
		check("sdbars places: a bar chosen for two places is placed once, at the first", shownBars() == 3 and d.parts["blocks.buffsBar"] == inst.box and d.parts["blocks.classBar"] ~= inst.box, tostring(shownBars()))
		for _, p in ipairs(names) do
			ns.Set(p, keep[p])
		end
		for _, p in ipairs({ "classBar", "classPlace", "buffsBar", "buffsPlace", "consumablesBar", "consumablesPlace", "from" }) do
			ns.Set("blocks." .. p, p == "from" and "main" or (p:find("Place") and "free" or "none"))
		end
		ns.Set("blocks.enabled", false)
		d.draw(stage.blocks)
	end
	-- Fading.
	do
		local d = drawings["mock-fade"]
		local inst = d.built[stage.fade]
		d.draw(stage.fade)
		check("sdbars fade: with fading off every part is at full opacity", inst.tiles[1].body.alpha == 1 and inst.samples[2].holder.alpha == 1)
		ns.Set("fade.enabled", true)
		ns.Set("fade.bar2", true)
		ns.Set("fade.alpha", 40)
		d.draw(stage.fade)
		check("sdbars fade: a part that fades is at the faded opacity, the others and the full sample at full", inst.tiles[2].body.alpha == 0.4 and inst.tiles[1].body.alpha == 1
			and inst.samples[1].holder.alpha == 1 and inst.samples[2].holder.alpha == 0.4)
		check("sdbars fade: the faded sample names the opacity", inst.samples[2].label.text == "Faded opacity 40%", inst.samples[2].label.text)
		ns.Set("fade.enabled", false)
		d.draw(stage.fade)
		check("sdbars fade: a part marked to fade is at full opacity while fading is off", inst.tiles[2].body.alpha == 1 and inst.samples[2].holder.alpha == 1)
		ns.Set("fade.enabled", true)
		ns.Set("actionbars.main", false)
		d.draw(stage.fade)
		check("sdbars fade: the sample buttons follow the Main bar switch of the Action bars page", inst.samples[1].button.slot.shown == true and inst.gameLabel.shown == true)
		ns.Set("actionbars.main", true)
		d.draw(stage.fade)
		check("sdbars fade: the sample buttons are the flat ones with the group on", inst.samples[1].button.slot.shown == false and inst.gameLabel.shown == false)
		ns.Set("fade.bar2", false)
		ns.Set("fade.enabled", false)
		ns.Set("fade.alpha", 25)
		d.draw(stage.fade)
	end
	check("sdbars: the drawings made no violation and raised no error", #W.violations == 0 and #W.errors == 0, tostring(W.violations[1] or W.errors[1] or ""))
end
-- >>> sdbars (end)

-- >>> sdunit (begin)
-- The drawings of the unit frame steps (FlatUI/SetupDrawUnits.lua): mock-unit-frame, mock-unit-frames, mock-party-frames and mock-raid-cells. Every drawn setting of the
-- steps is written to another value with ns.Set, the drawing is drawn again, and what it paints must differ. The helpers are on one table.
do
	local SU = {}
	local SD = {
		["mock-unit-frames"] = { "enabled", "player", "target", "focus", "pet", "tot", "party", "partypet", "boss", "raid", "totem", "petSize", "petSizeBasis", "petSizePct", "playerScale", "targetScale", "focusScale", "partyScale", "bossScale", "raidScale" },
		["mock-unit-frame"] = { "portraitStyle", "portraitSize", "portraitBorder", "portraitFade", "portraitPlayer", "portraitTarget", "portraitFocus", "portraitPet", "portraitTot", "portraitParty", "portraitPartypet", "squarePortrait", "corners", "elite", "backdrop", "flat", "healthColour", "healthTexture", "powerTexture", "healthByLeft", "status", "threat", "healPrediction", "absorbShield", "healAbsorb", "lookOwn", "lookBorder", "lookBack", "lookBackAlpha", "smallRow", "levelPosition", "levelColour", "levelSize", "strip", "stripColour", "stripFade", "stripBrightness", "kindMark", "kindWord", "kindLine", "nameFace", "nameSize", "nameOutline", "nameColour", "nameCustom", "healthTextSize", "powerTextSize", "smallTextSize", "barTextFace", "barTextOutline", "barTextColourOwn", "barTextColour", "lookClassHealth", "lookLostColour", "lookMuted", "lookWhiteNames", "lookLightText", "lookNoPowerText", "lookSoftShade", "lookShadow", "numberStyle", "ownTextWhen", "healthTextPos", "powerTextPos", "auras", "auraCrop", "auraTypeColours", "auraCountSize", "auraNumbers", "pvpFlag", "pvpCorner", "pvpTimer", "leaderIcon", "roleIcon", "pvpIcon", "raidMarker", "deadText", "totemTimer", "totemSwipe", "playerPicture", "playerName", "playerLevel", "restAnimation", "playerHealthBy", "playerHealthText", "playerPowerText", "combatIcon", "playerPowerBar", "targetPicture", "targetName", "targetLevel", "targetHealthBy", "targetHealthText", "targetPowerText", "targetPowerBar", "focusPicture", "focusName", "focusLevel", "focusHealthBy", "focusHealthText", "focusPowerText", "focusPowerBar", "petPicture", "petName", "petHealthBy", "petHealthText", "petPowerText", "petHappiness", "petPowerBar", "totPicture", "totName", "totHealthBy", "totPowerBar", "bossName", "bossLevel", "bossHealthBy", "bossHealthText", "bossPowerBar" },
		["mock-raid-cells"] = { "raidCells", "raidRangeAlpha", "raidRoleIcon", "raidName", "raidStatusText" },
		["mock-party-frames"] = { "partyPicture", "partypetPicture", "partyName", "partyHealthBy", "partyHealthText", "partyPowerText", "partyPowerBar", "partyRangeDim", "partyRangeAlpha" },
	}
	SU.SD = SD
	SU.order = { "mock-unit-frames", "mock-unit-frame", "mock-party-frames", "mock-raid-cells" }
	-- Rows that change the drawing only after another setting is set: a format other than the game's on the bars, or a Flat UI page border that is not the Unit
	-- frames page's.
	-- The game's own words are off by default (statusText is "0"), so a row of the words themselves needs a format first.
	local formats = { ["unitframes.playerHealthText"] = "curmax", ["unitframes.playerPowerText"] = "curmax" }
	SU.extra = { numberStyle = formats, ownTextWhen = formats, healthTextPos = formats, powerTextPos = formats,
		healthTextSize = formats, powerTextSize = formats, smallTextSize = { ["unitframes.petHealthText"] = "curmax", ["unitframes.petPowerText"] = "curmax", ["unitframes.partyHealthText"] = "curmax" }, barTextFace = formats, barTextOutline = formats, barTextColourOwn = formats,
		barTextColour = formats, lookLightText = formats, lookNoPowerText = formats,
		lookOwn = { ["general.border"] = "ff336699", ["general.backdrop"] = "ff224466" },
		petSize = { ["unitframes.petSizePct"] = 150 }, petSizeBasis = { ["unitframes.petSizePct"] = 150 } }
	-- Draft values for rows the game holds (a frame scale), which ns.Set cannot write here.
	SU.draft = { petSizeBasis = { ["unitframes.playerScale"] = 150 } }
	-- A world with trackers (it has the cooldown frames of the icons and the fonts of the game), logged in, in which the client loads every face.
	function SU.world()
		local W = newWorld({ trackers = true, fontReturn = "true" })
		W.au.unit.player = { guid = "Player-1-0001", player = true, class = "SHAMAN", race = "Troll", name = "Mine" }
		W.login()
		W.flush()
		return W
	end
	-- The rows of the options, by saved path. The name of the table is joined from two strings so that a slice of the test for this prefix does not keep the blocks
	-- that name the same field for their own reasons.
	function SU.def(ns, path)
		for _, page in ipairs(ns["PA" .. "GES"]) do
			for _, item in ipairs(page) do
				if item.path == path then
					return item
				end
			end
		end
	end
	function SU.num(v)
		return type(v) == "number" and string.format("%.4g", v) or tostring(v)
	end
	function SU.col(c)
		if type(c) ~= "table" then
			return "-"
		end
		if c.r then
			return SU.num(c.r) .. "," .. SU.num(c.g) .. "," .. SU.num(c.b) .. "," .. SU.num(c.a)
		end
		local parts = {}
		for i = 1, 4 do
			parts[i] = SU.num(c[i])
		end
		return table.concat(parts, ",")
	end
	-- What each region of a drawing paints: shown, size, points, colour, texture, text, font, alpha.
	function SU.print(W, mark)
		local names, out = {}, {}
		local lists = { { "f", W.addonFrames, mark.f }, { "t", W.addonTextures, mark.t }, { "s", W.addonFonts, mark.s } }
		for _, list in ipairs(lists) do
			for i = list[3] + 1, #list[2] do
				names[W.rawOf[list[2][i]] or list[2][i]] = list[1] .. i
			end
		end
		local function name(x)
			return names[W.rawOf[x] or x] or "x"
		end
		local function points(r)
			local list = {}
			for _, p in ipairs(r.points or {}) do
				list[#list + 1] = p[1] .. ">" .. name(p[2]) .. ":" .. p[3] .. ":" .. SU.num(p[4]) .. ":" .. SU.num(p[5])
			end
			return table.concat(list, ";")
		end
		for _, list in ipairs(lists) do
			for i = list[3] + 1, #list[2] do
				local r = W.rawOf[list[2][i]] or list[2][i]
				local line = { list[1] .. i, r.shown and "1" or "0", SU.num(r.alpha), SU.num(r.width), SU.num(r.height), points(r) }
				if list[1] == "f" then
					line[#line + 1] = "scale " .. SU.num(r.scale)
				else
					line[#line + 1] = "v " .. SU.col(r.vertex)
					line[#line + 1] = "c " .. SU.col(r.color)
					line[#line + 1] = "file " .. tostring(r.file) .. " atlas " .. tostring(r.atlas)
					line[#line + 1] = "tc " .. SU.col(r.texCoord)
					line[#line + 1] = r.gradient and ("g " .. r.gradient[1] .. SU.col(r.gradient[2]) .. SU.col(r.gradient[3])) or "g -"
					if list[1] == "s" then
						local font = r.font or {}
						line[#line + 1] = "text " .. tostring(r.text) .. " font " .. tostring(font[1]) .. " " .. SU.num(font[2]) .. " " .. tostring(font[3]) .. " tc " .. SU.col(r.textColour) .. " j " .. tostring(r.justify)
					end
				end
				out[#out + 1] = table.concat(line, "|")
			end
		end
		return table.concat(out, "\n")
	end
	function SU.build(W, id)
		local stage = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		local mark = { f = #W.addonFrames, t = #W.addonTextures, s = #W.addonFonts }
		local drawing = W.ns.SetupDrawings[id]
		drawing.build(stage)
		return { W = W, ns = W.ns, id = id, drawing = drawing, stage = stage, mark = mark }
	end
	function SU.draw(S)
		return S.drawing.draw(S.stage)
	end
	function SU.shot(S)
		SU.draw(S)
		return SU.print(S.W, S.mark)
	end
	-- Sets what the switches of a row need; the paths set are kept to be put back.
	function SU.satisfy(S, def, touched)
		local ns = S.ns
		if def.needsPath then
			SU.satisfy(S, SU.def(ns, def.needsPath), touched)
			local now = ns.Get(def.needsPath)
			if def.needsIn then
				local found = false
				for _, v in ipairs(def.needsIn) do
					found = found or v == now
				end
				if not found then
					ns.Set(def.needsPath, def.needsIn[1])
					touched[#touched + 1] = def.needsPath
				end
			elseif not now then
				ns.Set(def.needsPath, true)
				touched[#touched + 1] = def.needsPath
			end
		end
	end
	function SU.candidates(ns, def)
		local now, list = ns.Get(def.path), {}
		if def.kind == "bool" then
			list[1] = not now
		elseif def.kind == "choice" then
			for _, line in ipairs(ns.Choices(def)) do
				if line[1] ~= now then
					list[#list + 1] = line[1]
				end
			end
		elseif def.kind == "number" then
			for _, v in ipairs({ def.min, def.max, now + def.step, now - def.step }) do
				if v ~= now and v >= def.min and v <= def.max then
					list[#list + 1] = v
				end
			end
		elseif def.kind == "colour" then
			list = { "ffd13a9b", "ff102030" }
		end
		return list
	end
	-- Writes each other value of a row in turn and draws again. Returns the value that changed the drawing, or nil. A row the game holds (a frame scale) is given to
	-- ns.Get as a draft value, as the setup does.
	function SU.change(S, path)
		local ns = S.ns
		local def = SU.def(ns, "unitframes." .. path)
		local touched, view, base = {}, {}, ns.Get
		for p, v in pairs(SU.draft[path] or {}) do
			view[p] = v
		end
		SU.satisfy(S, def, touched)
		for p, v in pairs(SU.extra[path] or {}) do
			ns.Set(p, v)
			touched[#touched + 1] = p
		end
		if def.get or next(view) ~= nil then
			ns.Get = function(p)
				if view[p] ~= nil then
					return view[p]
				end
				return base(p)
			end
		end
		local before = SU.shot(S)
		local found
		for _, value in ipairs(SU.candidates(ns, def)) do
			if def.get then
				view[def.path] = value
			else
				ns.Set(def.path, value)
			end
			if SU.shot(S) ~= before then
				found = value
				break
			end
		end
		ns.Get = base
		ns.Set(def.path, def.default)
		for _, p in ipairs(touched) do
			ns.Set(p, SU.def(ns, p).default)
		end
		SU.draw(S)
		return found
	end
	-- With SDUNIT_DUMP set to a folder, each drawing is written there as a page of boxes (a way to look at the layout); SDUNIT_SET names rows to set first.
	function SU.dump(S, folder)
		local W, ns = S.W, S.ns
		local stage = S.stage
		local rawStage = W.rawOf[stage]
		rawStage.points, rawStage.allPoints = {}, nil
		stage:SetPoint("TOPLEFT", W.env.UIParent, "TOPLEFT", 0, 0)
		local width, height = SU.draw(S)
		local cache = {}
		local FX = { LEFT = 0, TOPLEFT = 0, BOTTOMLEFT = 0, CENTER = 0.5, TOP = 0.5, BOTTOM = 0.5, RIGHT = 1, TOPRIGHT = 1, BOTTOMRIGHT = 1 }
		local FY = { TOP = 0, TOPLEFT = 0, TOPRIGHT = 0, CENTER = 0.5, LEFT = 0.5, RIGHT = 0.5, BOTTOM = 1, BOTTOMLEFT = 1, BOTTOMRIGHT = 1 }
		local eff
		local function owner(raw)
			return raw.owner and W.rawOf[raw.owner] or (raw.parent and W.rawOf[raw.parent]) or nil
		end
		function eff(raw)
			if raw.isFrame then
				local up = raw.parent and W.rawOf[raw.parent]
				return (raw.scale or 1) * (up and eff(up) or 1)
			end
			local o = owner(raw)
			return o and eff(o) or 1
		end
		local function shownChain(raw)
			while raw do
				if raw.shown == false then
					return false
				end
				raw = owner(raw)
			end
			return true
		end
		local rect
		function rect(raw)
			if cache[raw] then
				return cache[raw]
			end
			if raw == W.rawOf[W.env.UIParent] then
				cache[raw] = { x = 0, y = 0, w = 1920, h = 1080 }
				return cache[raw]
			end
			cache[raw] = { x = 0, y = 0, w = 0, h = 0 }
			local sc = eff(raw)
			local R
			if raw.allPoints then
				local t = rect(W.rawOf[raw.allPoints])
				R = { x = t.x, y = t.y, w = t.w, h = t.h }
			else
				local pts = {}
				for _, p in ipairs(raw.points or {}) do
					local rel = rect(W.rawOf[p[2]] or W.rawOf[W.env.UIParent])
					pts[#pts + 1] = { p[1], rel.x + FX[p[3]] * rel.w + (p[4] or 0) * sc, rel.y + FY[p[3]] * rel.h - (p[5] or 0) * sc }
				end
				local w, h = (raw.width or 0) * sc, (raw.height or 0) * sc
				if raw.kind == "FontString" and raw.text and (raw.width or 0) == 0 then
					w = #raw.text * ((raw.font and raw.font[2]) or 12) * 0.5 * sc
					h = ((raw.font and raw.font[2]) or 12) * sc
				end
				local left, right, top, bottom
				for _, p in ipairs(pts) do
					local fx, fy = FX[p[1]], FY[p[1]]
					if p[1]:find("LEFT") or p[1] == "LEFT" then left = p[2] elseif p[1]:find("RIGHT") then right = p[2] end
					if p[1]:find("TOP") then top = p[3] elseif p[1]:find("BOTTOM") then bottom = p[3] end
					if p[1] == "CENTER" or p[1] == "TOP" or p[1] == "BOTTOM" then left = left or p[2] - w / 2 end
					if p[1] == "CENTER" or p[1] == "LEFT" or p[1] == "RIGHT" then top = top or p[3] - h / 2 end
				end
				local x = left or (right and right - w) or 0
				local y = top or (bottom and bottom - h) or 0
				local ww = (left and right) and (right - left) or w
				local hh = (top and bottom) and (bottom - top) or h
				R = { x = x, y = y, w = ww, h = hh }
			end
			cache[raw] = R
			return R
		end
		local out, ids = {}, {}
		local lists = { { "f", W.addonFrames, S.mark.f }, { "t", W.addonTextures, S.mark.t }, { "s", W.addonFonts, S.mark.s } }
		local order = {}
		for _, list in ipairs(lists) do
			for i = list[3] + 1, #list[2] do
				order[#order + 1] = { list[1], W.rawOf[list[2][i]] or list[2][i], i }
			end
		end
		local base = rect(rawStage)
		local function css(c, a)
			return string.format("rgba(%d,%d,%d,%.3f)", (c[1] or 1) * 255, (c[2] or 1) * 255, (c[3] or 1) * 255, (c[4] or 1) * (a or 1))
		end
		for _, item in ipairs(order) do
			local kind, raw = item[1], item[2]
			if shownChain(raw) then
				local r = rect(raw)
				local style = string.format("left:%.1fpx;top:%.1fpx;width:%.1fpx;height:%.1fpx;", r.x - base.x, r.y - base.y, r.w, r.h)
				if kind == "f" then
					out[#out + 1] = string.format('<div class="f" style="%s"></div>', style)
				elseif kind == "t" then
					local bg = "transparent"
					local v = raw.vertex or { 1, 1, 1, 1 }
					if raw.gradient then
						local lo, hi = raw.gradient[2], raw.gradient[3]
						bg = string.format("linear-gradient(to top,%s,%s)", css({ lo.r, lo.g, lo.b, lo.a }, v[4]), css({ hi.r, hi.g, hi.b, hi.a }, v[4]))
					elseif raw.color then
						bg = css(raw.color, (raw.alpha or 1))
					elseif raw.file or raw.atlas then
						bg = css({ v[1] * 0.7, v[2] * 0.7, v[3] * 0.7, (v[4] or 1) * 0.8 })
					end
					out[#out + 1] = string.format('<div class="t" style="%sbackground:%s;opacity:%.2f" title="%s"></div>', style, bg, raw.alpha or 1, tostring(raw.file or raw.atlas or ""))
				else
					local font = raw.font or { "", 12, "" }
					local c = raw.textColour or { 1, 1, 1, 1 }
					out[#out + 1] = string.format('<div class="s" style="%sfont-size:%.1fpx;color:%s;text-align:%s;font-weight:%s">%s</div>', style, font[2] * eff(raw), css(c),
						(raw.justify or "LEFT"):lower(), tostring(font[3] or ""):find("OUTLINE") and "bold" or "normal", tostring(raw.text or ""))
				end
			end
		end
		local file = assert(io.open(folder .. "/" .. S.id .. ".html", "w"))
		file:write('<html><body style="background:#202428;margin:20px;zoom:2.2"><style>div{position:absolute;box-sizing:border-box}.f{border:1px dotted rgba(255,255,255,.12)}.s{font-family:Arial;line-height:1;white-space:nowrap;overflow:visible}</style><div style="position:relative;left:0;top:0;width:',
			string.format("%d", math.max(width or 100, 100)), "px;height:", string.format("%d", math.max(height or 100, 100)), "px\">", table.concat(out, "\n"), "</div></body></html>")
		file:close()
	end
	SU.worlds = {}
	for _, id in ipairs(SU.order) do
		SU.worlds[id] = SU.build(SU.world(), id)
	end
	local folder = os.getenv("SDUNIT_DUMP")
	if folder then
		for _, id in ipairs(SU.order) do
			local S = SU.worlds[id]
			for pair in (os.getenv("SDUNIT_SET") or ""):gmatch("[^,]+") do
				local path, value = pair:match("^(.-)=(.*)$")
				local set = tonumber(value) or value
				if value == "true" then
					set = true
				elseif value == "false" then
					set = false
				end
				S.ns.Set(path, set)
			end
			SU.dump(S, folder)
		end
		if os.getenv("SDUNIT_ONLY") then
			os.exit(0)
		end
	end
	for _, id in ipairs(SU.order) do
		local S = SU.worlds[id]
		local W = S.W
		local d = S.drawing
		check("sdunit: " .. id .. " is registered with build, draw and a table of parts", type(d) == "table" and type(d.build) == "function" and type(d.draw) == "function" and type(d.parts) == "table")
		local width, height = SU.draw(S)
		check("sdunit: " .. id .. " draws a size", type(width) == "number" and type(height) == "number" and width > 0 and height > 0, tostring(width) .. " " .. tostring(height))
		local unowned = 0
		local lists = { { W.addonFrames, S.mark.f }, { W.addonTextures, S.mark.t }, { W.addonFonts, S.mark.s } }
		for _, list in ipairs(lists) do
			for i = list[2] + 1, #list[1] do
				if not W.ns.Own[list[1][i]] then
					unowned = unowned + 1
				end
			end
		end
		check("sdunit: " .. id .. " makes every frame, texture and text in ns.Own", unowned == 0, unowned)
		local first = SU.shot(S)
		check("sdunit: " .. id .. " draws the same thing twice", SU.shot(S) == first)
		check("sdunit: " .. id .. " is drawn without a violation or an error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "):sub(1, 300) .. table.concat(W.errors, " | "):sub(1, 300))
		for _, path in ipairs(SU.SD[id]) do
			check("sdunit: " .. id .. " marks a region for unitframes." .. path, d.parts[path] ~= nil)
			local changed = SU.change(S, path)
			check("sdunit: " .. id .. " draws unitframes." .. path .. " differently when it is set to another value", changed ~= nil)
		end
		check("sdunit: " .. id .. " is still without a violation or an error after every row", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "):sub(1, 300) .. table.concat(W.errors, " | "):sub(1, 300))
	end
	-- Class icon shape on the player picture of the card: Round cuts the class icon and its fade to the circle, shows the disc and hides the rounded line of Corners Soft.
	do
		local H = newWorld({ trackers = true, fontReturn = "true", hud = true })
		H.env.C_Texture = { GetAtlasExists = function() return true end }
		H.au.unit.player = { guid = "Player-1-0001", player = true, class = "SHAMAN", race = "Troll", name = "Mine" }
		H.login()
		H.flush()
		local S = SU.build(H, "mock-unit-frames")
		S.ns.Set("unitframes.portraitStyle", "icon")
		S.ns.Set("unitframes.corners", "soft")
		local function raw(x) return H.rawOf[x] or x end
		local function pictures()
			SU.draw(S)
			local faces = {}
			for _, t in ipairs(H.addonTextures) do
				local r = raw(t)
				if r.atlas and tostring(r.atlas):find("^classicon") and r.shown then
					local P = { face = r, masked = next(r.masks) ~= nil, line = false }
					for _, o in ipairs(H.addonTextures) do
						local q = raw(o)
						if raw(q.owner) == raw(r.owner) then
							if q.layer == "BACKGROUND" and q.sublevel == -7 and q.shown then
								P.disc = q
							elseif q.layer == "OVERLAY" and q.sublevel == 7 and q.file and q.shown then
								P.line = true
							end
						end
					end
					faces[#faces + 1] = P
				end
			end
			return faces
		end
		local function all(faces, test)
			for _, P in ipairs(faces) do
				if not test(P) then
					return false
				end
			end
			return #faces > 0
		end
		local square = pictures()
		check("sdunit: Class icon shape Square: the class icon of the card has no mask and no disc, and the rounded line shows with Corners Soft",
			all(square, function(P) return not P.masked and P.disc == nil and P.line end), #square)
		S.ns.Set("unitframes.classShape", "round")
		local round = pictures()
		check("sdunit: Class icon shape Round: the class icon of the card has the circle mask and the disc shows, and the rounded line is hidden",
			all(round, function(P) return P.masked and P.disc ~= nil and not P.line and (raw(next(P.face.masks)).atlas == "CircleMaskScalable") end), #round)
		S.ns.Set("unitframes.classShape", "square")
		square = pictures()
		check("sdunit: and Square again takes the mask and the disc off and the rounded line is back", all(square, function(P) return not P.masked and P.disc == nil and P.line end), #square)
		check("sdunit: the card is drawn without a violation or an error", #H.violations == 0 and #H.errors == 0, table.concat(H.violations, "|"):sub(1, 300) .. table.concat(H.errors, "|"):sub(1, 300))
	end
end
-- >>> sdunit (end)

