		{ 26, "resource.text", true, false },
		{ 26, "resource.percent", true, false, "resource.text" },
		{ 26, "resource.value", true, false, "resource.text" },
		{ 26, "resource.textOwn", false, true },
		{ 26, "resource.textColour", "ffffffff", "ffff00ff", "resource.textOwn" },
		{ 27, "swing.enabled", true, false },
		{ 27, "swing.main", true, false },
		{ 27, "swing.off", true, false },
		{ 27, "swing.ranged", true, false },
		{ 27, "swing.width", "resource", "game" },
		{ 27, "swing.outline", "bar", "frame" },
		{ 27, "swing.backdrop", true, false },
		{ 27, "swing.flat", true, false },
		{ 27, "swing.texture", "default", "soft", "swing.flat" },
		{ 27, "swing.mainColour", "ffd9a640", "ffff00ff", "swing.flat" },
		{ 27, "swing.offColour", "ff5c9fd6", "ffff00ff", "swing.flat" },
		{ 27, "swing.rangedColour", "ff73b85c", "ffff00ff", "swing.flat" },
		{ 27, "swing.classColour", false, true, "swing.flat" },
		{ 27, "swing.spark", true, false, "swing.flat" },
		{ 27, "swing.textShadow", false, true, "swing.flat" },
		{ 27, "swing.reverse", false, true },
		{ 27, "swing.rangeAlpha", 40, 100 },
		{ 27, "swing.idle", "combat", "show" },
		{ 27, "swing.textSize", 100, 200 },
		{ 27, "swing.name", true, false },
		{ 27, "swing.time", true, false },
		{ 27, "swing.textOwn", false, true },
		{ 27, "swing.textColour", "ffffffff", "ffff00ff", "swing.textOwn" },
		{ 27, "swing.rangeTextColour", "ffff1a1a", "ffff00ff", "swing.textOwn" },
	}
	L.DRAWING = { [23] = "mock-cast-bar", [24] = "mock-cast-bar", [25] = "mock-cast-bar", [26] = "mock-resource", [27] = "mock-swing" }
	-- Rows that change nothing alone until a sibling row differs from what the game draws: a size at the game's own size, own colours equal to the cast
	-- colours, an own text colour equal to the game's white. The sibling is set first.
	L.PRE = {
		["castbars.playerSize"] = { { "castbars.playerWidth", 300 } },
		["castbars.playerWidth"] = { { "castbars.playerMatch", "own" } },
		["castbars.petSize"] = { { "castbars.petWidth", 300 } },
		["castbars.targetSize"] = { { "castbars.targetWidth", 250 } },
		["castbars.focusSize"] = { { "castbars.focusWidth", 250 } },
		["castbars.targetOwn"] = { { "castbars.castColour", "ff112233" }, { "castbars.channelColour", "ff332211" } },
		["castbars.textOwn"] = { { "castbars.textColour", "ff00ff00" } },
		["resource.textOwn"] = { { "resource.textColour", "ff00ff00" } },
		["swing.textOwn"] = { { "swing.textColour", "ff00ff00" } },
	}
	function L.rgb(c)
		return c and ("%.3f,%.3f,%.3f"):format(c[1], c[2], c[3]) or "-"
	end
	function L.hex(h)
		return ("%.3f,%.3f,%.3f"):format(tonumber(h:sub(3, 4), 16) / 255, tonumber(h:sub(5, 6), 16) / 255, tonumber(h:sub(7, 8), 16) / 255)
	end
	-- A world, a stage and the drawing, once per drawing id.
	function L.setup(id)
		L.worlds = L.worlds or {}
		local w = L.worlds[id]
		if not w then
			local W = newWorld({})
			W.login()
			W.flush()
			local stage = W.env.CreateFrame("Frame", nil, W.env.UIParent)
			stage:SetSize(658, 204)
			w = { W = W, stage = stage, drawing = W.ns.SetupDrawings[id] }
			L.worlds[id] = w
			w.drawing.build(stage)
			w.drawing.draw(stage)
		end
		return w
	end
	-- Every frame and region under a frame, depth first.
	function L.walk(W, frame, list)
		local raw = W.rawOf[frame]
		for _, region in ipairs(raw.regions) do
			list[#list + 1] = region
		end
		for _, child in ipairs(raw.children) do
			list[#list + 1] = child
			L.walk(W, child, list)
		end
		return list
	end
	function L.num(v)
		return v == nil and "-" or type(v) == "number" and ("%.4g"):format(v) or tostring(v)
	end
	function L.list(t)
		local out = {}
		for i, v in ipairs(t or {}) do
			out[i] = L.num(v)
		end
		return table.concat(out, ",")
	end
	-- What the client shows of every region under the stage, as one text, and the regions.
	function L.fingerprint(w)
		local list = L.walk(w.W, w.stage, {})
		local ids = { [w.stage] = 0 }
		for i, item in ipairs(list) do
			ids[item] = i
		end
		local out = {}
		for i, o in ipairs(list) do
			local line = { i, o.isFrame and "F" or o.kind, tostring(o.shown), L.num(o.alpha), L.num(o.width), L.num(o.height) }
			for _, p in ipairs(o.points) do
				line[#line + 1] = p[1] .. ">" .. tostring(ids[p[2]] or "?") .. p[3] .. L.num(p[4]) .. "," .. L.num(p[5])
			end
			if o.allPoints then
				line[#line + 1] = "all" .. tostring(ids[o.allPoints] or "?")
			end
			if o.isRegion then
				if o.color then
					line[#line + 1] = "c" .. L.list(o.color)
				else
					line[#line + 1] = "f" .. tostring(o.file) .. L.list(o.texCoord) .. "a" .. tostring(o.atlas)
				end
				line[#line + 1] = "v" .. L.list(o.vertex)
				if o.kind == "FontString" then
					local file, size, flags = o.GetFont()
					line[#line + 1] = "t" .. tostring(o.text) .. "/" .. tostring(file) .. L.num(size) .. tostring(flags) .. "/" .. L.list({ o.GetTextColor() }) .. "/" .. tostring(o.justify)
				end
			end
			out[i] = table.concat(line, " ")
		end
		return table.concat(out, "\n"), list
	end
	-- Where two fingerprints first differ, for a failing check.
	function L.diff(a, b)
		local la, lb = TOC.lines(a), TOC.lines(b)
		for i = 1, math.max(#la, #lb) do
			if la[i] ~= lb[i] then
				return tostring(la[i]) .. "  /  " .. tostring(lb[i])
			end
		end
		return "same"
	end

	-- The three drawings are registered with the three parts of a drawing.
	do
		local W = L.setup("mock-cast-bar").W
		for _, id in ipairs({ "mock-cast-bar", "mock-resource", "mock-swing" }) do
			local d = W.ns.SetupDrawings[id]
			check("sdcast: " .. id .. " is registered with build, draw and parts", type(d) == "table" and type(d.build) == "function" and type(d.draw) == "function" and type(d.parts) == "table")
		end
	end

	-- One world per drawing: every drawn setting of its steps changes what the drawing shows, and putting it back draws what it drew before.
	L.changed, L.total = 0, 0
	L.base = {}
	for _, id in ipairs({ "mock-cast-bar", "mock-resource", "mock-swing" }) do
		local w = L.setup(id)
		local W, ns = w.W, w.W.ns
		L.base[id] = L.fingerprint(w)
		local walked = {}
		for _, item in ipairs(select(2, L.fingerprint(w))) do
			walked[item] = true
		end
		for _, s in ipairs(L.SETTINGS) do
			if L.DRAWING[s[1]] == id then
				local path, default, alt, need = s[2], s[3], s[4], s[5]
				L.total = L.total + 1
				local saved = {}
				local function put(p, v)
					if saved[p] == nil then
						saved[p] = { ns.Get(p) }
					end
					ns.Set(p, v)
				end
				check("sdcast: " .. path .. " has the default the wizard lists", ns.Get(path) == default, tostring(ns.Get(path)))
				if need and not ns.Get(need) then
					put(need, true)
				end
				for _, pre in ipairs(L.PRE[path] or {}) do
					put(pre[1], pre[2])
				end
				w.drawing.draw(w.stage)
				local before = L.fingerprint(w)
				put(path, alt)
				w.drawing.draw(w.stage)
				local after = L.fingerprint(w)
				local part = w.drawing.parts[path]
				check("sdcast: " .. path .. " changes the drawing", before ~= after, L.diff(before, after))
				if before ~= after then
					L.changed = L.changed + 1
				end
				check("sdcast: " .. path .. " has a part of the drawing to mark", part ~= nil and (walked[part] or part == W.rawOf[w.stage].children[1]), tostring(part))
				for p, v in pairs(saved) do
					ns.Set(p, v[1])
				end
				w.drawing.draw(w.stage)
				local again = L.fingerprint(w)
				check("sdcast: " .. path .. " put back draws what it drew before", again == L.base[id], L.diff(L.base[id], again))
			end
		end
		check("sdcast: " .. id .. " has no violation, error or message", #W.violations == 0 and #W.errors == 0 and #W.out == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end
	check("sdcast: 82 drawn settings in steps 23 to 27 and each changes its drawing", L.total == 82 and L.changed == 82, L.changed .. " of " .. L.total)

	-- Every frame, texture and text the drawings made is the addon's own.
	for _, id in ipairs({ "mock-cast-bar", "mock-resource", "mock-swing" }) do
		local w = L.setup(id)
		local own, total = 0, 0
		for _, item in ipairs(select(2, L.fingerprint(w))) do
			total = total + 1
			if w.W.ns.Own[item] then
				own = own + 1
			end
		end
		check("sdcast: " .. id .. " has only frames and regions marked as the addon's own", total > 20 and own == total, own .. " of " .. total)
	end

	-- A build is made once for a stage; a second stage has its own.
	do
		local w = L.setup("mock-swing")
		local W = w.W
		local frames = #W.addonFrames
		w.drawing.build(w.stage)
		w.drawing.build(w.stage)
		check("sdcast: building again on the same stage makes nothing", #W.addonFrames == frames, #W.addonFrames - frames)
		local other = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		w.drawing.build(other)
		check("sdcast: another stage gets its own frames", #W.addonFrames > frames + 5 and #W.rawOf[other].children == 1)
	end

	-- The cast bars: what each row of the first steps does to the picture.
	do
		local w = L.setup("mock-cast-bar")
		local W, ns, d, stage = w.W, w.W.ns, w.drawing, w.stage
		local rgb, hex = L.rgb, L.hex
		local function fill() return d.parts["castbars.flat"] end
		d.draw(stage)
		check("sdcast: the player cast bar fill is the cast colour of the Flat UI page", rgb(fill().color) == hex("ffe6b333"), rgb(fill().color))
		local outline = d.outlines[1]
		check("sdcast: the player cast bar has its border and background by default", outline.shown and outline.backdropOn and outline.top.shown and outline.backdrop.shown)
		ns.Set("castbars.player", false)
		d.draw(stage)
		check("sdcast: with its border off the player bar shows the game's own frame and no thin border", not outline.top.shown and not outline.backdrop.shown and d.parts["castbars.player"] ~= nil)
		ns.Set("castbars.player", true)
		-- Class colour.
		W.env.UnitClass = function() return "Mage", "MAGE", 8 end
		W.env.RAID_CLASS_COLORS = { MAGE = { r = 0.41, g = 0.8, b = 0.94 } }
		ns.Set("castbars.playerClass", true)
		d.draw(stage)
		check("sdcast: the class colour is on the player bar fill and not on the target bar", rgb(fill().color) == "0.410,0.800,0.940" and rgb(d.parts["castbars.targetOwn"].color) == hex("ffe6b333"), rgb(fill().color))
		ns.Set("castbars.playerClass", false)
		-- Border takes the cast colour.
		ns.Set("castbars.stateBorder", true)
		d.draw(stage)
		check("sdcast: with Border takes the cast colour the edges are the colour of the cast", rgb(outline.top.color) == hex("ffe6b333"), rgb(outline.top.color))
		ns.Set("castbars.stateBorder", false)
		-- Sizes: a size of its own sets the bar, and the drawing is as big as its widest bar.
		local root = W.rawOf[stage].children[1]
		local wide = d.size(stage)
		local bar = d.parts["castbars.playerWidth"]
		check("sdcast: stack widths: the player cast bar is 200 wide, the width of the personal resource display, and 11 high", bar.width == 200 and bar.height == 11, tostring(bar.width) .. " " .. tostring(bar.height))
		ns.Set("castbars.playerSize", true)
		ns.Set("castbars.playerWidth", 400)
		ns.Set("castbars.playerHeight", 30)
		d.draw(stage)
		check("sdcast: stack widths: with a custom size the match keeps the width of the display and takes the chosen height", bar.width == 200 and bar.height == 30, tostring(bar.width) .. " " .. tostring(bar.height))
		ns.Set("castbars.playerMatch", "own")
		d.draw(stage)
		check("sdcast: the player cast bar has the width and height of its rows", bar.width == 400 and bar.height == 30, tostring(bar.width) .. " " .. tostring(bar.height))
		check("sdcast: the drawing grows with its widest bar", d.size(stage) > wide and root.width == d.size(stage), tostring(d.size(stage)) .. " " .. tostring(wide))
		-- Text below and inside the player bar.
		local text = d.parts["castbars.playerText"]
		ns.Set("castbars.playerText", "below")
		d.draw(stage)
		local below = text.points[1][3]
		ns.Set("castbars.playerText", "inside")
		d.draw(stage)
		check("sdcast: the player spell name is below the bar or inside it", below == "BOTTOM" and text.points[1][3] == "CENTER" and text.points[1][1] == "CENTER" and text.width == 185, below)
		ns.Set("castbars.playerSize", false)
		ns.Set("castbars.playerText", "game")
		-- Text size and alignment.
		ns.Set("castbars.textSize", 150)
		ns.Set("castbars.textAlign", "right")
		d.draw(stage)
		local _, size = text.GetFont()
		check("sdcast: the spell name is 150 percent of the game's size and aligned right", math.abs(size - 18) < 0.01 and text.justify == "RIGHT", tostring(size) .. " " .. tostring(text.justify))
		ns.Set("castbars.textSize", 100)
		ns.Set("castbars.textAlign", "game")
		-- Icons: target icon left, right, hidden.
		local icon = d.parts["castbars.iconPos"]
		d.draw(stage)
		check("sdcast: the target icon is left of its bar by default", icon.shown and icon.points[1][1] == "RIGHT" and icon.points[1][3] == "LEFT" and icon.width == 20)
		ns.Set("castbars.iconPos", "right")
		d.draw(stage)
		check("sdcast: the target icon is right of its bar", icon.shown and icon.points[1][1] == "LEFT" and icon.points[1][3] == "RIGHT")
		ns.Set("castbars.iconPos", "game")
		-- Restyle cast bars off gives the game's look everywhere.
		ns.Set("castbars.enabled", false)
		d.draw(stage)
		local allBack = true
		for _, o in ipairs(d.outlines) do
			allBack = allBack and not o.top.shown and not o.backdrop.shown
		end
		check("sdcast: with Restyle cast bars off no bar has a thin border and the fill is the game's", allBack and fill().file ~= nil, tostring(fill().file))
		ns.Set("castbars.enabled", true)
	end

	-- The personal resource display.
	do
		local w = L.setup("mock-resource")
		local W, ns, d, stage = w.W, w.W.ns, w.drawing, w.stage
		local rgb, hex = L.rgb, L.hex
		local health, power, alt = d.parts["resource.health"], d.parts["resource.power"], d.parts["resource.alt"]
		d.draw(stage)
		local joined = power.points[1][5] - health.points[1][5]
		local joinedAt, healthAt = power.points[1][5], health.points[1][5]
		ns.Set("resource.join", false)
		d.draw(stage)
		local apart = power.points[1][5] - health.points[1][5]
		local thick = ns.Pixels(power, ns.Get("general.thickness"))
		check("sdcast: joined bars are closer than the game's gap by the thickness of the border", apart < joined and math.abs((joined - apart) - (4 - thick)) < 0.01,
			tostring(joined) .. " " .. tostring(apart))
		-- The lower bar's top edge is drawn outside the bar, one thickness above it, so it falls on the upper bar's bottom edge, which is drawn one thickness below.
		check("sdcast: joined bars share one border strip", thick > 0 and math.abs(joinedAt - (healthAt - health.height - thick)) < 0.01,
			tostring(joinedAt) .. " " .. tostring(healthAt))
		ns.Set("resource.join", true)
		ns.Set("resource.power", false)
		d.draw(stage)
		local third = alt.points[1][5] - power.points[1][5]
		ns.Set("resource.power", true)
		d.draw(stage)
		check("sdcast: bars join only while both have a border", alt.points[1][5] - power.points[1][5] > third)
		ns.Set("resource.healthOwn", true)
		ns.Set("resource.healthColour", "ff112233")
		d.draw(stage)
		local fill = d.parts["resource.flat"]
		check("sdcast: the custom health colour is the health fill", rgb(fill.color) == hex("ff112233"), rgb(fill.color))
		ns.Set("resource.healthByLeft", true)
		d.draw(stage)
		local r1, g1, b1 = ns.Colour("general.healthHalf")
		local r2, g2, b2 = ns.Colour("general.healthFull")
		check("sdcast: colour by health left puts 70 percent between the half and full colours", rgb(fill.color) == ("%.3f,%.3f,%.3f"):format(r1 + (r2 - r1) * 0.4, g1 + (g2 - g1) * 0.4, b1 + (b2 - b1) * 0.4), rgb(fill.color))
		ns.Set("resource.healthOwn", false)
		ns.Set("resource.healthByLeft", false)
		ns.Set("resource.texture", "soft")
		d.draw(stage)
		check("sdcast: a bar texture is the image file of that texture in the colour", fill.file == "Interface\\AddOns\\FlatUI\\Media\\Soft.tga" and fill.color == nil, tostring(fill.file))
		ns.Set("resource.texture", "default")
		-- Numbers.
		local percentText, valueText = d.parts["resource.percent"], d.parts["resource.value"]
		d.draw(stage)
		check("sdcast: the bars show 70% and 7,000", percentText.text == "70%" and valueText.text == "7,000" and percentText.shown and valueText.shown)
		ns.Set("resource.percent", false)
		d.draw(stage)
		check("sdcast: Percentage text off hides the percentage and keeps the value", not percentText.shown and valueText.shown)
		ns.Set("resource.percent", true)
		ns.Set("resource.text", false)
		d.draw(stage)
		check("sdcast: Health and power numbers off hides both", not percentText.shown and not valueText.shown)
		ns.Set("resource.text", true)
		-- Restyle off: the game's look.
		ns.Set("resource.enabled", false)
		ns.Set("resource.healthOwn", true)
		d.draw(stage)
		check("sdcast: with Restyle the personal resource display off nothing is custom", not d.outlines[1].top.shown and fill.file ~= nil and rgb(fill.vertex) ~= hex("ff2eb84d") and percentText.shown)
		ns.Set("resource.healthOwn", false)
		ns.Set("resource.enabled", true)
		d.draw(stage)
	end

	-- The swing timers.
	do
		local w = L.setup("mock-swing")
		local W, ns, d, stage = w.W, w.W.ns, w.drawing, w.stage
		local rgb, hex = L.rgb, L.hex
		local root = W.rawOf[stage].children[1]
		d.draw(stage)
		local main, off, ranged = d.parts["swing.mainColour"], d.parts["swing.offColour"], d.parts["swing.rangedColour"]
		check("sdcast: the three timers are in the three hand colours", rgb(main.color) == hex("ffd9a640") and rgb(off.color) == hex("ff5c9fd6") and rgb(ranged.color) == hex("ff73b85c"),
			rgb(main.color) .. " " .. rgb(off.color) .. " " .. rgb(ranged.color))
		check("sdcast: the timers have run 64, 40 and 80 percent of 190 units", math.abs(main.width - 121.6) < 0.01 and math.abs(off.width - 76) < 0.01 and math.abs(ranged.width - 152) < 0.01,
			main.width .. " " .. off.width .. " " .. ranged.width)
		ns.Set("swing.width", "game")
		d.draw(stage)
		check("sdcast: stack widths: Width set in Edit Mode draws the timers 190 wide with bars of 180", math.abs(main.width - 115.2) < 0.01 and W.rawOf[d.parts["swing.width"]].width == 190,
			main.width .. " " .. tostring(W.rawOf[d.parts["swing.width"]].width))
		ns.Set("swing.width", "resource")
		d.draw(stage)
		check("sdcast: stack widths: the width of the personal resource display draws the timers 200 wide", W.rawOf[d.parts["swing.width"]].width == 200, tostring(W.rawOf[d.parts["swing.width"]].width))
		-- Moving: the fill grows with the sample clock and the time left falls.
		local timeText = d.parts["swing.time"]
		local first = main.width
		local was = timeText.text
		root.onUpdate(root, 0.5)
		check("sdcast: the timers move on sample times and the time left falls", main.width > first and tonumber(timeText.text) < tonumber(was), main.width .. " " .. first .. " " .. tostring(timeText.text) .. " " .. tostring(was))
		root.onUpdate(root, 100)
		check("sdcast: the time left is always between 0 and the swing time", tonumber(timeText.text) >= 0 and tonumber(timeText.text) <= 2.6, tostring(timeText.text))
		-- Out of range and idle.
		local outBar = d.parts["swing.rangeAlpha"]
		d.draw(stage)
		check("sdcast: the out of range timer has the game's 40 percent", math.abs(outBar.alpha - 0.4) < 1e-9)
		ns.Set("swing.rangeAlpha", 70)
		d.draw(stage)
		check("sdcast: the out of range opacity row sets that timer's opacity", math.abs(outBar.alpha - 0.7) < 1e-9)
		ns.Set("swing.rangeAlpha", 40)
		local idleTimer = d.parts["swing.idle"]
		local idleBar = nil
		for _, child in ipairs(W.rawOf[idleTimer].children) do
			idleBar = idleBar or child
		end
		ns.Set("swing.idle", "hide")
		d.draw(stage)
		check("sdcast: Show the timer, Only while swinging hides the idle bar", idleBar.shown == false)
		ns.Set("swing.idle", "show")
		d.draw(stage)
		local idleRegions = W.rawOf[idleBar].regions
		check("sdcast: an idle timer has no fill, no spark and 0.0 left, and the others have a spark", idleRegions[1].shown == false and idleRegions[3].shown == false and idleRegions[6].text == "0.0"
			and d.parts["swing.spark"].shown == true, tostring(idleRegions[1].shown) .. " " .. tostring(idleRegions[3].shown))
		ns.Set("swing.idle", "hide")
		ns.Set("swing.idle", "show")
		d.draw(stage)
		check("sdcast: Show the timer, Always shows the idle bar", idleBar.shown == true)
		ns.Set("swing.idle", "combat")
		d.draw(stage)
		check("sdcast: Show the timer, In combat hides the idle sample bar", idleBar.shown == false)
		ns.Set("swing.idle", "show")
		d.draw(stage)
		-- The border around the bar or the whole timer.
		local o = d.outlines
		check("sdcast: the border is around the bar by default", o[1].top.shown and not o[2].top.shown)
		ns.Set("swing.outline", "frame")
		d.draw(stage)
		check("sdcast: the border is around the whole timer with Border around: Whole timer", not o[1].top.shown and o[2].top.shown)
		ns.Set("swing.outline", "bar")
		-- Class colour and reverse.
		W.env.UnitClass = function() return "Mage", "MAGE", 8 end
		W.env.RAID_CLASS_COLORS = { MAGE = { r = 0.41, g = 0.8, b = 0.94 } }
		ns.Set("swing.classColour", true)
		d.draw(stage)
		check("sdcast: the class colour is on all three timers", rgb(main.color) == "0.410,0.800,0.940" and rgb(off.color) == "0.410,0.800,0.940" and rgb(ranged.color) == "0.410,0.800,0.940", rgb(main.color))
		ns.Set("swing.classColour", false)
		ns.Set("swing.reverse", true)
		d.draw(stage)
		check("sdcast: Fill from the right anchors the fill to the right end", main.points[1][1] == "TOPRIGHT" and main.points[2][1] == "BOTTOMRIGHT", main.points[1][1])
		ns.Set("swing.reverse", false)
		-- Out of range text colour is red as the game has it, and the row's colour when it is on.
		local outText = d.parts["swing.rangeTextColour"]
		d.draw(stage)
		check("sdcast: out of range text is red by default and white in range", rgb({ outText.GetTextColor() }) == "1.000,0.100,0.100" and rgb({ d.parts["swing.name"].GetTextColor() }) == "1.000,1.000,1.000",
			rgb({ outText.GetTextColor() }))
		ns.Set("swing.textOwn", true)
		ns.Set("swing.rangeTextColour", "ff0000ff")
		d.draw(stage)
		check("sdcast: the out of range text colour row colours that timer's text", rgb({ outText.GetTextColor() }) == "0.000,0.000,1.000", rgb({ outText.GetTextColor() }))
		ns.Set("swing.textOwn", false)
		ns.Set("swing.rangeTextColour", "ffff1a1a")
		-- Restyle off.
		ns.Set("swing.enabled", false)
		d.draw(stage)
		check("sdcast: with Restyle swing timers off there is no thin border and the out of range timer has 40 percent", not o[1].top.shown and not o[2].top.shown and math.abs(outBar.alpha - 0.4) < 1e-9 and main.file ~= nil)
		ns.Set("swing.enabled", true)
		d.draw(stage)
		check("sdcast: swing drawing ends with no violation, error or message", #W.violations == 0 and #W.errors == 0 and #W.out == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
	end
	-- Parts the game draws: its atlas when the client answers for it, else grey with a Game look label.
	do
		local function label(W, stage)
			for _, o in ipairs(L.walk(W, stage, {})) do
				if o.kind == "FontString" and o.text == "Game look" then
					return o
				end
			end
		end
		for _, id in ipairs({ "mock-cast-bar", "mock-resource", "mock-swing" }) do
			local w = L.setup(id)
			w.drawing.draw(w.stage)
			local l = label(w.W, w.stage)
			check("sdcast: " .. id .. " shows Game look while the client has no atlas for a part", l ~= nil and l.shown == true and w.drawing.gameLook(w.stage) == true)
		end
		local w = L.setup("mock-cast-bar")
		w.W.ns.Set("castbars.enabled", false)
		w.drawing.draw(w.stage)
		local fill = w.drawing.parts["castbars.flat"]
		check("sdcast: without an atlas the game's cast fill is grey and not an invented colour", fill.atlas == nil and L.rgb(fill.vertex) == "0.720,0.720,0.720", L.rgb(fill.vertex))
		w.W.ns.Set("castbars.enabled", true)
		-- A client that has the atlases.
		local W = newWorld({})
		W.env.C_Texture = { GetAtlasInfo = function() return { width = 64, height = 64 } end }
		W.login()
		W.flush()
		local ns = W.ns
		local stages = {}
		for _, id in ipairs({ "mock-cast-bar", "mock-resource", "mock-swing" }) do
			stages[id] = W.env.CreateFrame("Frame", nil, W.env.UIParent)
			stages[id]:SetSize(658, 204)
		end
		W.env.SWING_TIMER_MAIN_HAND, W.env.SWING_TIMER_OFF_HAND, W.env.SWING_TIMER_RANGED = "Hauptwaffe", "Nebenwaffe", "Fernkampf"
		for id, stage in pairs(stages) do
			ns.SetupDrawings[id].build(stage)
		end
		ns.Set("castbars.enabled", false)
		ns.Set("swing.enabled", false)
		for id, stage in pairs(stages) do
			ns.SetupDrawings[id].draw(stage)
		end
		local cast, swing = ns.SetupDrawings["mock-cast-bar"], ns.SetupDrawings["mock-swing"]
		check("sdcast: the game's cast fill is the atlas of its state", cast.parts["castbars.flat"].atlas == "ui-castingbar-filling-standard" and cast.parts["castbars.targetChannel"].atlas == "ui-castingbar-filling-channel",
			tostring(cast.parts["castbars.flat"].atlas) .. " " .. tostring(cast.parts["castbars.targetChannel"].atlas))
		check("sdcast: the game's plate, shield and spark are atlases", cast.parts["castbars.textPlate"].atlas == "ui-castingbar-textbox" and cast.parts["castbars.shield"].atlas == "ui-castingbar-shield" and cast.parts["castbars.spark"].atlas == "ui-castingbar-pip")
		check("sdcast: with every atlas answering, cast bars have no Game look label", label(W, stages["mock-cast-bar"]).shown == false and cast.gameLook(stages["mock-cast-bar"]) == false)
		check("sdcast: the game's swing fill, pip and shadow are atlases", swing.parts["swing.flat"].atlas == "ui-swingtimerbar-filling-mainhand" and swing.parts["swing.offColour"].atlas == "ui-swingtimerbar-filling-offhand"
			and swing.parts["swing.spark"].atlas == "ui-swingtimerbar-pip" and swing.parts["swing.textShadow"].atlas == "ui-swingtimerbar-textshadow-left", tostring(swing.parts["swing.flat"].atlas))
		check("sdcast: with every atlas answering, swing timers have no Game look label", label(W, stages["mock-swing"]).shown == false)
		check("sdcast: the personal resource display keeps its Game look label, the client has no atlas for it", label(W, stages["mock-resource"]).shown == true)
		-- The atlas names the cast bar drawing asks the client for are names the client has (AtlasInfo.lua; CastingBarFrame.lua:70-72 for the uninterruptible fill).
		do
			local NC = newWorld({})
			local known = { ["ui-castingbar-filling-standard"] = true, ["ui-castingbar-filling-channel"] = true, ["ui-castingbar-uninterruptable"] = true,
				["ui-castingbar-textbox"] = true, ["ui-castingbar-shield"] = true, ["ui-castingbar-pip"] = true, ["ui-castingbar-frame"] = true, ["ui-castingbar-background"] = true }
			local asked = {}
			NC.env.C_Texture = { GetAtlasExists = function(name) asked[#asked + 1] = name return known[name:lower()] == true end }
			NC.login()
			NC.flush()
			local st = NC.env.CreateFrame("Frame", nil, NC.env.UIParent)
			st:SetSize(658, 204)
			NC.ns.SetupDrawings["mock-cast-bar"].build(st)
			NC.ns.Set("castbars.enabled", false)
			NC.ns.SetupDrawings["mock-cast-bar"].draw(st)
			local unknown, sawShield = {}, false
			for _, name in ipairs(asked) do
				sawShield = sawShield or name == "ui-castingbar-uninterruptable"
				if not known[name:lower()] then
					unknown[#unknown + 1] = name
				end
			end
			check("name check: the uninterruptible cast fill asks for the client's atlas name", sawShield)
			check("name check: every atlas the cast bar drawing asks for is a name the client has", #asked > 0 and #unknown == 0, table.concat(unknown, " "))
		end
		check("sdcast: the swing names are the client's words", swing.parts["swing.name"].text == "Hauptwaffe", tostring(swing.parts["swing.name"].text))
		ns.Set("swing.enabled", true)
		swing.draw(stages["mock-swing"])
		local pip = swing.parts["swing.spark"]
		check("sdcast: the pip is anchored by its side to the end of the fill", pip.points[1][1] == "RIGHT" and pip.points[1][3] == "RIGHT" and pip.points[1][2] == swing.parts["swing.flat"], tostring(pip.points[1][1]))
		ns.Set("swing.reverse", true)
		swing.draw(stages["mock-swing"])
		check("sdcast: a reversed fill has its pip on the left side of the fill", pip.points[1][1] == "LEFT" and pip.points[1][3] == "LEFT")
		-- Another stage does not take over the marked parts of the first.
		local other = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		other:SetSize(200, 100)
		cast.build(other)
		cast.draw(other)
		check("sdcast: parts of another stage are asked with partsOf and do not replace the first stage's", cast.parts == cast.partsOf(stages["mock-cast-bar"]) and cast.partsOf(other) ~= cast.parts
			and cast.outlines == cast.outlinesOf(stages["mock-cast-bar"]) and cast.outlinesOf(other) ~= cast.outlines)
	end
end
