-- >>> sdhud (begin)
-- The setup wizard drawings of steps 28 to 31 (SetupDrawHud.lua): minimap, buffs, experience bar and micro menu, objective tracker, loot.
-- Each drawn setting of those steps, written in the profile, must change what its drawing shows.
TOC.sdhud = {}
function TOC.sdhud.world()
	local W = TOC.df.iconWorld({ hud = true })
	-- These drawings are checked with the game's experience bar; the xpown block checks Flat UI's own.
	W.ns.Set("hud.xpOwn", "game")
	local stage = W.env.CreateFrame("Frame", nil, W.env.UIParent)
	return W, stage
end
-- The client gives a status bar made by an addon a fill region and SetColorFill; the simulated bar of this world has neither, so they are added here.
function TOC.sdhud.fills(W, raw)
	local function visit(f)
		if f.objectType == "StatusBar" and f.bar and not f.GetStatusBarTexture then
			local region = newRegion(W, f, { kind = "Texture" })
			region.addon, region.layer, region.sublevel = true, "ARTWORK", 0
			f.regions[#f.regions + 1] = region
			local set = f.SetStatusBarTexture
			function f.GetStatusBarTexture() return region end
			function f.SetStatusBarTexture(self, asset)
				local ok = set(self, asset)
				region.color = nil
				if asset:find("[\\/]") then
					region.file, region.atlas = asset, nil
				else
					region.atlas, region.file = asset, nil
				end
				return ok
			end
			function f.SetColorFill(_, ...)
				region.color, region.atlas, region.file = { ... }, nil, nil
			end
			f.SetStatusBarTexture(f, f.bar.texture)
		end
		for _, child in ipairs(f.children or {}) do
			visit(W.rawOf[child] or child)
		end
	end
	visit(raw)
end
-- Everything a drawing shows, as one text: each frame and region with its shown flag, size, points, colour, texture, text, font and alpha.
function TOC.sdhud.print(W, raw)
	local out = {}
	local function n(v)
		return type(v) == "number" and string.format("%.3f", v) or tostring(v)
	end
	local function points(o)
		local list = {}
		for _, p in ipairs(o.points or {}) do
			list[#list + 1] = tostring(p[1]) .. tostring(p[3]) .. n(p[4]) .. n(p[5])
		end
		return table.concat(list, ",") .. (o.allPoints and "all" or "")
	end
	local function visit(f, depth)
		local line = { depth, "F", tostring(f.shown), n(f.alpha), n(f.width), n(f.height), points(f) }
		if f.bar then
			line[#line + 1] = table.concat(f.bar.tint or { 1, 1, 1, 1 }, ",")
		end
		out[#out + 1] = table.concat(line, "|")
		for _, r in ipairs(f.regions or {}) do
			local c = r.color and table.concat(r.color, ",") or "-"
			local font = "-"
			if r.kind == "FontString" then
				local file, size, flags = r.GetFont()
				font = tostring(file) .. n(size) .. tostring(flags or "")
			end
			local tc = r.textColour and table.concat(r.textColour, ",") or "-"
			local v = r.vertex and table.concat(r.vertex, ",") or "-"
			local coord = r.texCoord and table.concat(r.texCoord, ",") or "-"
			local grad = r.gradient and "g" or "-"
			out[#out + 1] = table.concat({ depth, "R", r.kind, tostring(r.shown), n(r.alpha), n(r.width), n(r.height), points(r), c, tostring(r.file), tostring(r.atlas),
				coord, v, tostring(r.text), font, tc, #(r.maskList or {}), grad }, "|")
		end
		for _, child in ipairs(f.children or {}) do
			visit(W.rawOf[child] or child, depth + 1)
		end
	end
	visit(raw, 0)
	return table.concat(out, "\n")
end
-- The drawn settings of steps 28 to 31: path, drawing, a value that differs from the default, and the rows it needs.
TOC.sdhud.rows = {
	{ "hud.enabled", "mock-minimap", false }, { "hud.lookOwn", "mock-minimap", true, nil, { "general.border", "ff3366cc" } },
	{ "hud.lookBorder", "mock-minimap", "ffff0000", { "hud.lookOwn", true } }, { "hud.lookBack", "mock-minimap", "ff203040", { "hud.lookOwn", true } },
	{ "hud.lookBackAlpha", "mock-minimap", 40, { "hud.lookOwn", true } }, { "hud.minimapArt", "mock-minimap", false },
	{ "hud.minimapBorder", "mock-minimap", false }, { "hud.shape", "mock-minimap", "square" }, { "hud.dayNight", "mock-minimap", false },
	{ "hud.zoneText", "mock-minimap", false }, { "hud.zoneSize", "mock-minimap", 150 }, { "hud.btnTracking", "mock-minimap", false },
	{ "hud.btnMail", "mock-minimap", false }, { "hud.btnCalendar", "mock-minimap", false }, { "hud.btnClock", "mock-minimap", false },
	{ "hud.btnAddons", "mock-minimap", false },
