	{ "hud.colourPoison", "mock-buff-row", "ffff00ff" }, { "hud.colourOther", "mock-buff-row", "ff00ff00" }, { "hud.durationSize", "mock-buff-row", 150 },
	{ "hud.countSize", "mock-buff-row", 150 },
	{ "hud.bags", "mock-xp-micro", false }, { "hud.xpFrame", "mock-xp-micro", false }, { "hud.xpFill", "mock-xp-micro", false },
	{ "hud.xpDividers", "mock-xp-micro", false }, { "hud.xpText", "mock-xp-micro", "percent" }, { "hud.xpTextSize", "mock-xp-micro", 150 },
	{ "hud.xpTexture", "mock-xp-micro", "soft" }, { "hud.micro", "mock-xp-micro", false },
	{ "hud.trackerHeaders", "mock-objective", false }, { "hud.trackerBars", "mock-objective", false }, { "hud.trackerItems", "mock-objective", false },
	{ "hud.trackerTexture", "mock-objective", "soft" }, { "hud.trackerPanel", "mock-objective", true }, { "hud.trackerHeaderSize", "mock-objective", 150 },
	{ "hud.trackerCombat", "mock-objective", 50 },
	{ "hud.lootWindow", "mock-loot", false }, { "hud.lootRolls", "mock-loot", false }, { "hud.lootQualityText", "mock-loot", false },
	{ "hud.alerts", "mock-loot", false },
	{ "hud.mirror", "mock-xp-micro", false }, { "hud.countdown", "mock-xp-micro", false }, { "hud.queue", "mock-xp-micro", false },
	{ "hud.meter", "mock-xp-micro", false }, { "hud.zoneBars", "mock-xp-micro", false },
