do
	local H = TOC.sdhud
	local W, stage = H.world()
	local ns = W.ns
	local ids = { "mock-minimap", "mock-buff-row", "mock-xp-micro", "mock-objective", "mock-loot" }
	local registered = true
	for _, id in ipairs(ids) do
		local d = ns.SetupDrawings and ns.SetupDrawings[id]
		registered = registered and type(d) == "table" and type(d.build) == "function" and type(d.draw) == "function" and type(d.parts) == "table"
	end
	check("sdhud: the five drawings are registered with build, draw and parts", registered)
	local frames, textures, fonts, masks = #W.addonFrames, #W.addonTextures, #W.addonFonts, #W.addonMasks
	local roots = {}
	for _, id in ipairs(ids) do
		roots[id] = ns.SetupDrawings[id].build(stage)
		H.fills(W, W.rawOf[roots[id]])
	end
	local own, loose = true, nil
	for _, list in ipairs({ { W.addonFrames, frames }, { W.addonTextures, textures }, { W.addonFonts, fonts }, { W.addonMasks, masks } }) do
		for i = list[2] + 1, #list[1] do
			if ns.Own[list[1][i]] ~= true then
				own, loose = false, loose or i
			end
		end
	end
	check("sdhud: every frame, texture, font string and mask the drawings make is in ns.Own", own and #W.addonFrames > frames and #W.addonTextures > textures and #W.addonMasks > masks,
		tostring(loose))
	local again = true
	local before = #W.addonFrames
	for _, id in ipairs(ids) do
		again = again and ns.SetupDrawings[id].build(stage) == roots[id]
	end
	check("sdhud: a second build on the same stage returns the same frames and makes no new one", again and #W.addonFrames == before)
	local missing
	for _, row in ipairs(H.rows) do
		local region = ns.SetupDrawings[row[2]].parts[row[1]]
		if type(region) ~= "table" and not missing then
			missing = row[1]
		end
	end
	check("sdhud: every drawn setting of the four steps has a part to mark", missing == nil, missing)
	check("sdhud: there are 50 drawn settings in the four steps", #H.rows == 50, #H.rows)
	-- One setting after another: it is written, the drawing is drawn again and must differ, and the old value then draws the first picture again.
	local changed, same = 0, {}
	for _, row in ipairs(H.rows) do
		local path, id, value, needs, pre = row[1], row[2], row[3], row[4], row[5]
		local drawing = ns.SetupDrawings[id]
		local old, oldNeeds, oldPre = ns.Get(path), needs and ns.Get(needs[1]), pre and ns.Get(pre[1])
		drawing.draw(stage)
		local pristine = H.print(W, W.rawOf[roots[id]])
		if needs then
			ns.Set(needs[1], needs[2])
		end
		if pre then
			ns.Set(pre[1], pre[2])
		end
		drawing.draw(stage)
		local first = H.print(W, W.rawOf[roots[id]])
		ns.Set(path, value)
		drawing.draw(stage)
		local second = H.print(W, W.rawOf[roots[id]])
		check("sdhud: " .. path .. " changes " .. id, first ~= second, path)
		if first ~= second then
			changed = changed + 1
		else
			same[#same + 1] = path
		end
		ns.Set(path, old)
		if needs then
			ns.Set(needs[1], oldNeeds)
		end
		if pre then
			ns.Set(pre[1], oldPre)
		end
		drawing.draw(stage)
		check("sdhud: " .. path .. " set back draws " .. id .. " as before", H.print(W, W.rawOf[roots[id]]) == pristine, path)
	end
	check("sdhud: 50 of 50 drawn settings change their drawing", changed == 50, table.concat(same, " "))
	check("sdhud: no violation or error in the world of the drawings", #W.violations == 0 and #W.errors == 0,
		table.concat(W.violations, " | "):sub(1, 400) .. " || " .. table.concat(W.errors, " | "):sub(1, 400))
end
