		m.zone.font and m.zone.font[2])
	ns.Set("hud.lookOwn", true)
	ns.Set("hud.lookBorder", "ffff0000")
	ns.Set("hud.lookBack", "ff00ff00")
	ns.Set("hud.lookBackAlpha", 40)
	m = draw("mock-minimap")
	local o = m.header.outline
	check("sdhud: Own border and background put its colours and opacity on the zone band outline", near(o.r, 1) and near(o.g, 0) and near(o.fg, 1) and near(o.fa, 0.4),
		tostring(o.r) .. " " .. tostring(o.fa))
	ns.Set("hud.enabled", false)
	m = draw("mock-minimap")
	check("sdhud: with the page off the drawing says Game look and every part is grey", m.label.shown == true and m.header.rim.shown == true and m.disc.shown == false
		and m.ringTexture.shown == true and near(m.zone.font[2], 12, 0.01))
	ns.Set("hud.enabled", true)
	m = draw("mock-minimap")
	check("sdhud: with the page on the Game look text is off", m.label.shown == false)

	local b = draw("mock-buff-row")
	ns.Set("hud.crop", 15)
	b = draw("mock-buff-row")
	check("sdhud: Icon crop 15 trims 15 percent from every side of the buff icons", near(b.buffs[1].icon.texture.texCoord[1], 0.15) and near(b.buffs[1].icon.texture.texCoord[2], 0.85))
	ns.Set("hud.auras", false)
	b = draw("mock-buff-row")
	check("sdhud: with Buff and debuff borders off the icons are uncropped with the game's borders behind them", b.buffs[1].icon.texture.texCoord[1] == 0 and b.buffs[1].rim.shown == false and b.debuffs[1].rim.shown == true
		and b.debuffs[1].icon.outline.shown == false)
	ns.Set("hud.auras", true)
	ns.Set("hud.colourMagic", "ff00ff00")
	b = draw("mock-buff-row")
	local magic, other = b.debuffs[1].icon.outline, b.debuffs[5].icon.outline
	check("sdhud: the Magic debuff has the Magic colour and the bleed has the Other colour", near(magic.g, 1) and near(magic.r, 0) and near(other.r, 0.8) and near(other.g, 0),
		tostring(magic.g))
	ns.Set("hud.auraTypes", false)
	b = draw("mock-buff-row")
	check("sdhud: with Border colour by debuff type off every debuff has the Other colour", near(b.debuffs[1].icon.outline.r, 0.8) and near(b.debuffs[3].icon.outline.r, 0.8))
	ns.Set("hud.durationSize", 150)
	ns.Set("hud.countSize", 50)
	b = draw("mock-buff-row")
	check("sdhud: Duration size and Stack count size set the two texts to their percent", near(b.buffs[1].time.font[2], 18, 0.01) and near(b.buffs[2].count.font[2], 6, 0.01))
	check("sdhud: the samples are 3 stacks on the second buff and on the fourth debuff and 12 s on the first", b.buffs[2].count.text == "3" and b.debuffs[4].count.text == "3"
		and b.buffs[1].time.text == "12 s")

	local x = draw("mock-xp-micro")
	check("sdhud: the game text of the bars is the value and the total", x.xp.words.text == "3700 / 10000" and x.rep.words.text == "Stormwind 6000 / 12000", x.xp.words.text)
	for _, case in ipairs({ { "percent", "37%", "Stormwind 50%" }, { "both", "3700 / 10000 (37%)", "Stormwind 6000 / 12000 (50%)" },
		{ "togo", "6300 to go", "Stormwind 6000 to go" } }) do
		ns.Set("hud.xpText", case[1])
		x = draw("mock-xp-micro")
		check("sdhud: Bar text " .. case[1] .. " reads " .. case[2], x.xp.words.text == case[2] and x.rep.words.text == case[3], x.xp.words.text .. " | " .. x.rep.words.text)
	end
	ns.Set("hud.xpText", "game")
	local fill = last(x.xp.bar)
	check("sdhud: the experience fill is the flat colour of an experience bar", fill.color ~= nil and near(fill.color[1], 0.58) and near(fill.color[3], 0.55),
		fill.color and fill.color[1])
	ns.Set("hud.xpTexture", "soft")
	x = draw("mock-xp-micro")
	check("sdhud: Bar texture soft puts the Soft image on the fill", tostring(fill.file):find("Soft.tga", 1, true) ~= nil, tostring(fill.file))
	ns.Set("hud.xpFill", false)
	x = draw("mock-xp-micro")
	check("sdhud: with Flat fill off the fill has the gloss image", tostring(fill.file):find("Gloss.tga", 1, true) ~= nil, tostring(fill.file))
	ns.Set("hud.xpFill", true)
	x = draw("mock-xp-micro")
	check("sdhud: Hide bar dividers on hides the nine dividers of each bar", x.xp.lines[1].shown == false and x.rep.lines[9].shown == false)
	ns.Set("hud.xpDividers", false)
	x = draw("mock-xp-micro")
	check("sdhud: Hide bar dividers off shows them", x.xp.lines[1].shown == true and x.rep.lines[9].shown == true)
	ns.Set("hud.xpDividers", true)
	ns.Set("hud.xpFrame", false)
	x = draw("mock-xp-micro")
	check("sdhud: with Bar border off the bars have the grey game look and no outline", x.xp.rim.shown == true and x.rep.rim.shown == true and x.xp.outline.shown == false)
	ns.Set("hud.xpFrame", true)
	ns.Set("hud.micro", false)
	ns.Set("hud.bags", false)
	x = draw("mock-xp-micro")
	check("sdhud: Micro menu buttons and Bag bar buttons off give the grey game look and an uncropped icon", x.micro[1].rim.shown == true and x.micro[1].outline.shown == false
		and x.bags[1].rim.shown == true and x.bags[1].icon.texCoord[1] == 0)
	ns.Set("hud.micro", true)
	ns.Set("hud.bags", true)
	for _, path in ipairs({ "hud.mirror", "hud.countdown", "hud.queue", "hud.meter", "hud.zoneBars" }) do
		ns.Set(path, false)
	end
	x = draw("mock-xp-micro")
	check("sdhud: the five timer and panel parts off have the grey game look", x.mirror.rim.shown and x.countdown.rim.shown and x.queue.rim.shown and x.meter.rim.shown
		and x.zoneBar.rim.shown)
	for _, path in ipairs({ "hud.mirror", "hud.countdown", "hud.queue", "hud.meter", "hud.zoneBars" }) do
		ns.Set(path, true)
	end
	ns.Set("castbars.castColour", "ff102030")
	x = draw("mock-xp-micro")
	local mirror = last(x.mirror.bar)
	check("sdhud: the breath timer is filled in the cast colour", mirror.color ~= nil and near(mirror.color[1], 16 / 255, 0.01) and near(mirror.color[3], 48 / 255, 0.01),
		mirror.color and mirror.color[1])

	local t = draw("mock-objective")
	check("sdhud: the tracker has no panel until Tracker background is on", t.panel.frame.shown == false and near(t.root.alpha, 1))
	ns.Set("hud.trackerPanel", true)
	ns.Set("hud.trackerCombat", 50)
	t = draw("mock-objective")
	check("sdhud: Tracker background shows the panel and Opacity in combat sets the whole tracker's opacity", t.panel.frame.shown == true and near(t.root.alpha, 0.5),
		tostring(t.root.alpha))
	ns.Set("hud.trackerHeaderSize", 200)
	t = draw("mock-objective")
	check("sdhud: Heading size 200 doubles the heading text", near(t.title.font[2], 24, 0.01))
	ns.Set("hud.trackerBars", false)
	t = draw("mock-objective")
	local tfill = last(t.bar.bar)
	check("sdhud: with Tracker bars off the bar has the game's status bar picture and the grey look", tostring(tfill.file):find("UI-StatusBar", 1, true) ~= nil
		and t.bar.rim.shown == true, tostring(tfill.file))
	ns.Set("hud.trackerBars", true)
	ns.Set("hud.trackerTexture", "stripes")
	t = draw("mock-objective")
	check("sdhud: Tracker bar texture stripes puts the Stripes image on the bar", tostring(tfill.file):find("Stripes.tga", 1, true) ~= nil, tostring(tfill.file))

	do
		-- Parts the game's module never changes stay as they are whatever the rows say.
		ns.Set("hud.crop", 20)
		ns.Set("hud.trackerItems", true)
		ns.Set("hud.alerts", true)
		ns.Set("hud.zoneBars", true)
		local xo, to, lo = draw("mock-xp-micro"), draw("mock-objective"), draw("mock-loot")
		local zoneOn, itemOn = last(xo.zoneBar.bar), to.item.icon.texCoord
		ns.Set("hud.trackerItems", false)
		ns.Set("hud.alerts", false)
		ns.Set("hud.zoneBars", false)
		xo, to, lo = draw("mock-xp-micro"), draw("mock-objective"), draw("mock-loot")
		check("sdhud: zone event bars keep one fill and the tracker item and alert icons have no crop and no outline of their own",
			last(xo.zoneBar.bar) == zoneOn and (itemOn == nil or itemOn[1] == 0) and (to.item.icon.texCoord == nil or to.item.icon.texCoord[1] == 0)
			and lo.alertIcon.outline == nil)
		ns.Set("hud.crop", 15)
		ns.Set("hud.trackerItems", true)
		ns.Set("hud.alerts", true)
		ns.Set("hud.zoneBars", true)
	end
	local l = draw("mock-loot")
	check("sdhud: loot cards and slots have the colour of their quality and the quality words show", near(l.cards[2].outline.b, 0.87) and near(l.cards[3].slot.outline.r, 0.64)
		and l.cards[1].words.shown == true)
	ns.Set("hud.lootQualityText", false)
	l = draw("mock-loot")
	check("sdhud: Quality word on loot off hides the three words", l.cards[1].words.shown == false and l.cards[3].words.shown == false)
	ns.Set("hud.lootWindow", false)
	l = draw("mock-loot")
	check("sdhud: with Loot window off the window, cards and slots have the grey game look and the words show again", l.window.rim.shown == true and l.cards[1].rim.shown == true
		and l.cards[1].slot.rim.shown == true and l.cards[1].words.shown == true)
	ns.Set("hud.lootRolls", false)
	l = draw("mock-loot")
	local timer = last(l.timer)
	check("sdhud: with Loot rolls off the roll timer has the skills bar picture", tostring(timer.file):find("Skills-Bar", 1, true) ~= nil and l.roll.rim.shown == true,
		tostring(timer.file))
	check("sdhud: no violation or error in the world of the choices", #W.violations == 0 and #W.errors == 0,
		table.concat(W.violations, " | "):sub(1, 400) .. " || " .. table.concat(W.errors, " | "):sub(1, 400))
end
-- >>> sdhud (end)

-- >>> sdwin (begin)
-- Setup drawings of the windows steps (steps 32 to 35: mock-window, mock-window-set, mock-bag-slots). Every label starts "sdwin:". Each drawn setting is written to another
-- value and the drawing must look different; a setting that needs another row on first gets it in the third field. The values are kept in one table D: the main function of
-- this file has a limit on the locals alive at once.
do
	local D = {}
	D.W = newWorld({})
	D.W.login()
	D.W.tick()
	D.ns = D.W.ns
	D.count = 0
	local NL = string.char(10)
	function D.n(v) return type(v) == "number" and ("%.3f"):format(v) or tostring(v) end
	function D.join(t, from, to)
		local out = {}
		for i = from or 1, to or #t do out[#out + 1] = D.n(t[i]) end
		return table.concat(out, ",")
	end
	-- What a region or a frame shows: shown, size, points, colour, texture, text, font, alpha.
	function D.node(r)
		if r.shown == false then return (r.kind or r.objectType or "?") .. "|hidden" end
		local out = { r.kind or r.objectType or "?", tostring(r.shown), D.n(r.width), D.n(r.height), D.n(r.alpha), tostring(r.allPoints) }
		for _, p in ipairs(r.points or {}) do out[#out + 1] = p[1] .. ">" .. tostring(p[2]) .. ">" .. tostring(p[3]) .. ">" .. D.n(p[4]) .. ">" .. D.n(p[5]) end
		out[#out + 1] = r.color and D.join(r.color) or "-"
		out[#out + 1] = tostring(r.file) .. "/" .. tostring(r.atlas)
		out[#out + 1] = r.vertex and D.join(r.vertex) or "-"
		out[#out + 1] = tostring(r.text)
		local font = r.font or { "Fonts\\FRIZQT__.TTF", 12, "" }
		out[#out + 1] = r.kind == "FontString" and (tostring(font[1]) .. ":" .. D.n(font[2]) .. ":" .. tostring(font[3])) or "-"
		out[#out + 1] = r.kind == "FontString" and D.join(r.textColour or { 1, 1, 1, 1 }) or "-"
		out[#out + 1] = r.texCoord and D.join(r.texCoord) or "-"
		out[#out + 1] = r.start and (r.start[1] .. D.n(r.start[3]) .. D.n(r.start[4])) or "-"
		out[#out + 1] = r.stop and (r.stop[1] .. D.n(r.stop[3]) .. D.n(r.stop[4])) or "-"
		out[#out + 1] = D.n(r.thickness) .. D.n(r.scale)
		return table.concat(out, "|")
	end
	function D.walk(root, out, own)
		local r = D.W.rawOf[root] or root
		out[#out + 1] = D.node(r)
		if own and not D.ns.Own[root] and not D.ns.Own[r] then own.missing = (own.missing or 0) + 1 end
		for _, region in ipairs(r.regions or {}) do
			out[#out + 1] = D.node(region)
			if own and not D.ns.Own[region] then own.missing = (own.missing or 0) + 1 end
		end
		for _, child in ipairs(r.children or {}) do D.walk(child, out, own) end
		return out
	end
	function D.print(root, own) return table.concat(D.walk(root, {}, own), "\n") end
	function D.make(id)
		local drawing = D.ns.SetupDrawings[id]
		local stage = D.W.env.CreateFrame("Frame", nil, D.W.env.UIParent)
		stage:SetSize(658, 204)
		drawing.build(stage)
		drawing.draw(stage)
		return { drawing = drawing, stage = stage, id = id }
	end
	function D.draw(X) X.drawing.draw(X.stage) end
	-- Writes `alt` to `path` (after `pre`), draws, and says whether the picture changed and came back; then puts everything back.
	function D.changes(X, path, alt, pre)
		local was = {}
		for _, row in ipairs(pre or {}) do was[#was + 1] = { row[1], D.ns.Get(row[1]) } D.ns.Set(row[1], row[2]) end
		D.draw(X)
		local before = D.print(X.stage)
		local old = D.ns.Get(path)
		D.ns.Set(path, alt)
		D.draw(X)
		local after = D.print(X.stage)
		D.ns.Set(path, old)
		for i = #was, 1, -1 do D.ns.Set(was[i][1], was[i][2]) end
		D.draw(X)
		return before ~= after
	end
	-- Step 32 (Which windows), 33 (Window look and controls), 34 (Bags and items), 35 (Window backdrops): path, another value, rows to set first.
	D.rows = {
		["mock-window-set"] = { { "windows.enabled", false },
			{ "windows.character", false }, { "windows.groupfinder", false }, { "windows.social", false }, { "windows.npc", false }, { "windows.bags", false },
			{ "windows.spells", false }, { "windows.menus", false }, { "windows.auction", false }, { "windows.guild", false }, { "windows.inspect", false },
			{ "windows.macros", false }, { "windows.maps", false }, { "windows.more", false } },
		["mock-window"] = { { "windows.opacity", 40 }, { "windows.panel", "ff804020" }, { "windows.accent", "ff3366cc" }, { "windows.crop", 15 }, { "windows.portrait", true },
			{ "windows.buttons", false }, { "windows.tabs", false }, { "windows.sideTabs", false }, { "windows.squareTabs", false }, { "windows.sideTabSize", "large" },
			{ "windows.scroll", false }, { "windows.checks", false }, { "windows.inputs", false }, { "windows.bars", false }, { "windows.popupMenus", false },
			{ "windows.nameList", false }, { "windows.toasts", false }, { "windows.rows", false }, { "windows.titleSize", 150 }, { "windows.titleOwn", true },
			{ "windows.titleColour", "ff00ff00", { { "windows.titleOwn", true } } },
			{ "windows.raceArt", true }, { "windows.bookArt", true }, { "windows.eye", true }, { "windows.roleArt", true } },
		["mock-bag-slots"] = { { "windows.slots", false }, { "windows.quality", false }, { "windows.slotTints", false }, { "windows.qualityMin", "epic" },
			{ "windows.countSize", 150 }, { "windows.ilvlBags", true }, { "windows.ilvlCharacter", true },
			{ "windows.ilvlSize", 16, { { "windows.ilvlBags", true } } }, { "windows.ilvlColour", "gold", { { "windows.ilvlBags", true } } },
			{ "windows.newGlow", false }, { "windows.junkDim", true }, { "windows.combinedBags", true }, { "windows.sortButton", "slots" } },
	}
	D.drawn = 0
	for _, id in ipairs({ "mock-window-set", "mock-window", "mock-bag-slots" }) do
		local drawing = D.ns.SetupDrawings and D.ns.SetupDrawings[id]
		check("sdwin: " .. id .. " is registered with build, draw and parts", drawing ~= nil and type(drawing.build) == "function" and type(drawing.draw) == "function"
			and type(drawing.parts) == "table")
		if drawing then
			local X = D.make(id)
			local own = {}
			local first = D.print(X.stage)
			for _, child in ipairs(D.W.rawOf[X.stage].children) do D.walk(child, {}, own) end
			check("sdwin: " .. id .. " marks every frame, texture and text it makes ns.Own", (own.missing or 0) == 0, own.missing)
			D.draw(X)
			check("sdwin: " .. id .. " drawn again looks the same", D.print(X.stage) == first)
			for _, row in ipairs(D.rows[id]) do
				local changed = D.changes(X, row[1], row[2], row[3])
				D.drawn = D.drawn + 1
				if changed then D.count = D.count + 1 end
				check("sdwin: " .. row[1] .. " changes " .. id, changed)
				check("sdwin: " .. row[1] .. " has a part in " .. id, drawing.parts[row[1]] ~= nil)
			end
			local last, why = D.print(X.stage), nil
			if last ~= first then
				local a, b = {}, {}
				for line in (first .. NL):gmatch("([^" .. NL .. "]*)" .. NL) do a[#a + 1] = line end
				for line in (last .. NL):gmatch("([^" .. NL .. "]*)" .. NL) do b[#b + 1] = line end
				for i = 1, math.max(#a, #b) do if a[i] ~= b[i] then why = i .. " " .. tostring(a[i]) .. "  =>  " .. tostring(b[i]) break end end
			end
			check("sdwin: " .. id .. " looks as it did at first when every row is put back", last == first, why)
		end
	end
	check("sdwin: 52 drawn settings in steps 32 to 35, all change their drawing", D.drawn == 52 and D.count == 52, D.count .. " of " .. D.drawn)
	-- One kind of window at a time in Which windows.
	do
		local X = D.make("mock-window-set")
		local parts = X.drawing.parts
		local names = { "character", "groupfinder", "social", "npc", "bags", "spells", "menus", "auction", "guild", "inspect", "macros", "maps", "more" }
		local only = true
		for _, key in ipairs(names) do
			local before = {}
			for _, other in ipairs(names) do before[other] = D.print(parts["windows." .. other]) end
			D.ns.Set("windows." .. key, false)
			D.draw(X)
			for _, other in ipairs(names) do
				local changed = D.print(parts["windows." .. other]) ~= before[other]
				if changed ~= (other == key) then only = false end
			end
			D.ns.Set("windows." .. key, true)
			D.draw(X)
		end
		check("sdwin: switching one window off in Which windows changes that window's drawing and no other", only)
		local before = {}
		for _, key in ipairs(names) do before[key] = D.print(parts["windows." .. key]) end
		D.ns.Set("windows.enabled", false)
		D.draw(X)
		local all = true
		for _, key in ipairs(names) do all = all and D.print(parts["windows." .. key]) ~= before[key] end
		D.ns.Set("windows.enabled", true)
		check("sdwin: Restyle windows off changes every window of the set", all)
	end
	-- Bags: the border colour of a quality, the lowest quality that gets one, item level text, stack count size and the sort button.
	do
		local X = D.make("mock-bag-slots")
		local parts = X.drawing.parts
		local function edge(frame) return D.W.rawOf[D.ns.Outline(frame, frame).edges[1]].color end
		local uncommon, epic = parts["windows.qualityMin"], parts["windows.quality"]
		check("sdwin: a quality border has the colour of its quality", D.join(edge(uncommon)) == "0.120,1.000,0.000,1.000" and D.join(edge(epic)) == "0.640,0.210,0.930,1.000",
			D.join(edge(uncommon)) .. " " .. D.join(edge(epic)))
		D.ns.Set("windows.qualityMin", "epic")
		D.draw(X)
		check("sdwin: Quality border from epic takes the border off a green item and keeps it on an epic one", D.join(edge(uncommon)) ~= "0.120,1.000,0.000,1.000"
			and D.join(edge(epic)) == "0.640,0.210,0.930,1.000", D.join(edge(uncommon)))
		D.ns.Set("windows.qualityMin", "all")
		D.ns.Set("windows.quality", false)
		D.draw(X)
		check("sdwin: Quality colour off leaves the general border colour on every slot", D.join(edge(epic)) == D.join(edge(uncommon)), D.join(edge(epic)))
		D.ns.Set("windows.quality", true)
		local text = parts["windows.ilvlBags"]
		D.draw(X)
		check("sdwin: no item level shows while both Item level rows are off", D.W.rawOf[text].shown == false)
		D.ns.Set("windows.ilvlBags", true)
		D.ns.Set("windows.ilvlSize", 16)
		D.draw(X)
		local raw = D.W.rawOf[text]
		check("sdwin: Item level in bags and bank shows the level of a weapon or armour at the chosen size and in the quality colour", raw.shown == true and raw.text == "23"
			and raw.font and raw.font[2] == 16 and D.join(raw.textColour) == "0.120,1.000,0.000,1.000", tostring(raw.text) .. " " .. (raw.font and raw.font[2] or "-"))
		D.ns.Set("windows.ilvlColour", "white")
		D.draw(X)
		check("sdwin: Item level colour white", D.join(D.W.rawOf[text].textColour) == "1.000,1.000,1.000,1.000")
		D.ns.Set("windows.ilvlBags", false)
		D.ns.Set("windows.ilvlSize", 12)
		D.ns.Set("windows.ilvlColour", "quality")
		local count = D.W.rawOf[parts["windows.countSize"]]
		D.draw(X)
		local size = count.font and count.font[2] or 12
		D.ns.Set("windows.countSize", 200)
		D.draw(X)
		check("sdwin: Stack count size 200 percent doubles the font of a count", count.font and count.font[2] == size * 2, count.font and count.font[2])
		D.ns.Set("windows.countSize", 100)
		D.draw(X)
		local sort = D.W.rawOf[parts["windows.sortButton"]]
		check("sdwin: the clean up bags button is in the title bar by default", sort.shown == true and sort.points[1][1] == "TOPRIGHT")
		D.ns.Set("windows.sortButton", "slots")
		D.draw(X)
		check("sdwin: Clean up bags button under the slots hangs below the window", sort.points[1][1] == "TOP" and sort.points[1][3] == "BOTTOM")
		D.ns.Set("windows.sortButton", "none")
		D.draw(X)
		check("sdwin: Clean up bags button none hides it", sort.shown == false)
		-- Every clean up button of the drawing, by its size: the windows' own and none other is 16 by 16.
		local function sorts()
			local list = {}
			local function visit(frame)
				local r = D.W.rawOf[frame] or frame
				if r.width == 16 and r.height == 16 and r.objectType == "Frame" then list[#list + 1] = r end
				for _, child in ipairs(r.children or {}) do visit(child) end
			end
			visit(X.stage)
			return list
		end
		local function shownSorts()
			local n = 0
			for _, r in ipairs(sorts()) do if r.shown ~= false then n = n + 1 end end
			return n
		end
		check("sdwin: the drawing has the clean up buttons of three windows", #sorts() == 3, #sorts())
		for _, together in ipairs({ false, true }) do
			D.ns.Set("windows.combinedBags", together)
			D.ns.Set("windows.sortButton", "none")
			D.draw(X)
			check("sdwin: Clean up bags button none leaves no clean up button in any bag window, combined " .. tostring(together), shownSorts() == 0, shownSorts())
			D.ns.Set("windows.sortButton", "slots")
			D.draw(X)
			check("sdwin: Clean up bags button under the slots shows one button, combined " .. tostring(together), shownSorts() == 1, shownSorts())
			D.ns.Set("windows.sortButton", "title")
			D.draw(X)
			check("sdwin: Clean up bags button in the title bar shows one per bag window, combined " .. tostring(together), shownSorts() == (together and 1 or 2), shownSorts())
		end
		D.ns.Set("windows.combinedBags", false)
		D.ns.Set("windows.sortButton", "title")
		D.ns.Set("windows.combinedBags", true)
		D.draw(X)
		local combined = D.W.rawOf[parts["windows.combinedBags"]]
		check("sdwin: Combine bags puts the slots in one window", combined.width == 220 and combined.height == 170, tostring(combined.width))
		D.ns.Set("windows.combinedBags", false)
		D.draw(X)
		check("sdwin: and takes them out into separate bags again", combined.width == 152, tostring(combined.width))
		local function dim(frame)
			for _, region in ipairs(D.W.rawOf[frame].regions) do
				if region.color and D.join(region.color) == "0.000,0.000,0.000,0.500" then return region.shown end
			end
		end
		D.ns.Set("windows.junkDim", true)
		D.draw(X)
		check("sdwin: Dim grey items dims a poor item with a vendor price and no other", dim(parts["windows.junkDim"]) == true and dim(parts["windows.newGlow"]) == false,
			tostring(dim(parts["windows.junkDim"])) .. " " .. tostring(dim(parts["windows.newGlow"])))
		D.ns.Set("windows.junkDim", false)
		D.ns.Set("windows.enabled", false)
		D.draw(X)
		check("sdwin: Restyle windows off leaves no Flat UI clean up button and no item border colour", sort.shown == false and D.join(edge(epic)) == D.join(edge(uncommon)))
		D.ns.Set("windows.enabled", true)
	end
	-- Icon crop: the slot pictures of a window and of a bag, and the hover colour of a button.
	do
		local function icon(frame)
			for _, region in ipairs(D.W.rawOf[frame].regions or {}) do
				if region.texCoord then return D.join(region.texCoord) end
			end
		end
		local X = D.make("mock-window")
		local crop = D.W.rawOf[X.drawing.parts["windows.crop"]]
		D.ns.Set("windows.crop", 15)
		D.draw(X)
		check("sdwin: Icon crop 15 trims 0.15 off each side of a slot picture in the window", D.join(crop.texCoord) == "0.150,0.850,0.150,0.850", D.join(crop.texCoord))
		D.ns.Set("windows.slots", false)
		D.draw(X)
		check("sdwin: and leaves the slot picture whole when the slots are left to the game", D.join(crop.texCoord) == "0.000,1.000,0.000,1.000", D.join(crop.texCoord))
		D.ns.Set("windows.slots", true)
		D.ns.Set("windows.crop", 8)
		local Y = D.make("mock-bag-slots")
		local slot = Y.drawing.parts["windows.slots"]
		D.ns.Set("windows.crop", 15)
		D.draw(Y)
		check("sdwin: Icon crop 15 trims 0.15 off each side of a bag slot picture", icon(slot) == "0.150,0.850,0.150,0.850", tostring(icon(slot)))
		D.ns.Set("windows.slots", false)
		D.draw(Y)
		check("sdwin: and a bag slot picture is whole with the slots left to the game", icon(slot) == "0.000,1.000,0.000,1.000", tostring(icon(slot)))
		D.ns.Set("windows.slots", true)
		D.ns.Set("windows.crop", 8)
		D.ns.Set("windows.accent", "ff3366cc")
		D.draw(X)
		local hover
		for _, region in ipairs(D.W.rawOf[X.drawing.parts["windows.accent"]].regions or {}) do
			if region.color and D.join(region.color) == "0.200,0.400,0.800,0.250" and region.shown ~= false then hover = region end
		end
		check("sdwin: the hover over the Accept button has the highlight colour", hover ~= nil)
		D.ns.Set("windows.accent", "ffffd100")
	end
	-- Game look: one label for a drawing with a part in the game's look, plain grey parts, the atlas when the client answers.
	do
		local function find(root, wanted, out)
			local r = D.W.rawOf[root] or root
			for _, region in ipairs(r.regions or {}) do
				if wanted(region) then out[#out + 1] = region end
			end
			for _, child in ipairs(r.children or {}) do find(child, wanted, out) end
			return out
		end
		local function label(X)
			local list = find(X.stage, function(r) return r.text == "Game look" end, {})
			return #list == 1 and list[1].shown ~= false, #list
		end
		for _, id in ipairs({ "mock-window", "mock-window-set", "mock-bag-slots" }) do
			local X = D.make(id)
			local shown, n = label(X)
			check("sdwin: " .. id .. " has one Game look label and shows none while every part is restyled", n == 1 and shown == false, tostring(n))
			D.ns.Set("windows.enabled", false)
			D.draw(X)
			shown, n = label(X)
			check("sdwin: " .. id .. " shows one Game look label while Restyle windows is off", n == 1 and shown == true, tostring(n))
			local tan = find(X.stage, function(r) return r.color and r.shown ~= false and r.color[1] > r.color[3] + 0.05 and not (r.color[1] == 1 and r.color[2] > 0.8) end, {})
			local why = {} for _, r in ipairs(tan) do why[#why + 1] = D.join(r.color) end check("sdwin: " .. id .. " draws the game's look in plain grey, with no tan or brown", #tan == 0, table.concat(why, " "))
			D.ns.Set("windows.enabled", true)
		end
		local X = D.make("mock-window")
		D.ns.Set("windows.npc", false)
		D.draw(X)
		local shown = label(X)
		local before = D.print(X.stage)
		D.ns.Set("windows.npc", true)
		D.draw(X)
		check("sdwin: the Mail window follows the vendor, mail, quest, trade and trainer switch", shown == true and D.print(X.stage) ~= before)
		D.ns.Set("windows.buttons", false)
		D.W.env.C_Texture = D.W.env.C_Texture or {}
		local asked = D.W.env.C_Texture.GetAtlasInfo
		D.W.env.C_Texture.GetAtlasInfo = function(name) if name == "RedButton-Exit" then return { width = 24, height = 24 } end end
		D.draw(X)
		local atlas = find(X.stage, function(r) return r.atlas == "RedButton-Exit" and r.shown ~= false end, {})
		check("sdwin: a part in the game's look shows its atlas when the client answers for it", #atlas == 1, #atlas)
		D.W.env.C_Texture.GetAtlasInfo = asked
		D.ns.Set("windows.buttons", true)
	end
	-- Title size and colour.
	do
		local X = D.make("mock-window")
		local title = D.W.rawOf[X.drawing.parts["windows.titleSize"]]
		D.draw(X)
		local base = title.font and title.font[2] or 12
		D.ns.Set("windows.titleSize", 150)
		D.draw(X)
		check("sdwin: Title size 150 percent is one and a half times the size at 100", title.font and title.font[2] == base * 1.5, title.font and title.font[2])
		D.ns.Set("windows.titleSize", 100)
		D.ns.Set("windows.titleOwn", true)
		D.ns.Set("windows.titleColour", "ff00ff00")
		D.draw(X)
		check("sdwin: Own title colour gives the title the colour chosen", title.textColour and D.join(title.textColour) == "0.000,1.000,0.000,1.000", title.textColour and D.join(title.textColour))
		D.ns.Set("windows.titleOwn", false)
		D.ns.Set("windows.titleColour", "ffffd100")
		D.draw(X)
		check("sdwin: and the game's colour comes back when the row is off", title.textColour and D.join(title.textColour) ~= "0.000,1.000,0.000,1.000")
	end
	check("sdwin: the drawings made no violation or error", #D.W.violations == 0 and #D.W.errors == 0, table.concat(D.W.violations, "|") .. table.concat(D.W.errors, "|"))
end
-- >>> sdwin (end)

-- >>> sdchat (begin)
-- The setup drawings of chat, tooltips and combat text (SetupDrawChat.lua): each drawn setting of the steps changes the drawing, the frames are
-- the addon's own, and the sample text is the fixed text.
do
	local D = {}
	-- A world with a stage frame. The client's font strings take a shadow and its status bars have a fill region, which this client does not model.
	function D.world()
		local W = newWorld({ trackers = true, fontReturn = "true" })
		W.au.unit.player = { guid = "Player-1-0001", player = true, class = "SHAMAN", race = "Troll", name = "Mine" }
		local base = W.env.CreateFrame
		W.env.CreateFrame = function(kind, name, parent, template)
			local f = base(kind, name, parent, template)
			local raw = W.rawOf[f]
			local make = raw.CreateFontString
			raw.CreateFontString = function(self, ...)
				local fs = make(self, ...)
				fs.SetShadowOffset = function(_, x, y) fs.shadowOff = { x, y } end
				fs.SetShadowColor = function(_, r, g, b, a) fs.shadowAlpha = a end
				return fs
			end
			if kind == "StatusBar" then
				local fill = newRegion(W, f, {})
				raw.GetStatusBarTexture = function() return fill end
				raw.SetColorFill = function(_, r, g, b, a) raw.bar.fillColour = { r, g, b, a } end
				local set = raw.SetStatusBarTexture
				raw.SetStatusBarTexture = function(self, asset)
					raw.bar.fillColour = nil
					return set(self, asset)
				end
			end
			return f
		end
		W.login()
		W.flush()
		return W
	end
	function D.num(v)
		return type(v) == "number" and ("%.3f"):format(v) or tostring(v)
	end
	function D.list(t)
		local out = {}
		for i = 1, 5 do
			out[#out + 1] = t and D.num(t[i]) or "-"
		end
		return table.concat(out, ",")
	end
	-- Everything the drawing shows, as one text: every frame and region made since the world began (shown, size, points, colours, textures,
	-- text, font, alpha).
	function D.fp(W, from)
		local index, rows = {}, {}
		for i = from + 1, #W.addonFrames do
			index[W.rawOf[W.addonFrames[i]]] = i
		end
		local function ref(o)
			return o and tostring(index[W.rawOf[o] or o] or "x") or "-"
		end
		local function points(raw)
			local out = {}
			for _, p in ipairs(raw.points or {}) do
				out[#out + 1] = p[1] .. ">" .. ref(p[2]) .. ">" .. tostring(p[3]) .. ">" .. D.num(p[4]) .. ">" .. D.num(p[5])
			end
			return table.concat(out, ";") .. "|" .. ref(raw.allPoints)
		end
		for i = from + 1, #W.addonFrames do
			local raw = W.rawOf[W.addonFrames[i]]
			local bar = raw.bar
			rows[#rows + 1] = table.concat({ "F" .. i, tostring(raw.shown), D.num(raw.width), D.num(raw.height), D.num(raw.alpha), D.num(raw.scale), points(raw),
				bar and (tostring(bar.texture) .. D.list(bar.tint) .. D.list(bar.fillColour) .. D.num(bar.value)) or "-" }, " ")
			for n, r in ipairs(raw.regions or {}) do
				if r.addon and r.shown == false then
					rows[#rows + 1] = "R" .. i .. "." .. n .. " hidden"
				elseif r.addon then
					local g = r.gradient
					-- A gradient of one colour is that colour.
					local flat = g and g[2].r == g[3].r and g[2].g == g[3].g and g[2].b == g[3].b and g[2].a == g[3].a
					local colour = flat and { g[2].r, g[2].g, g[2].b, g[2].a } or r.color
					rows[#rows + 1] = table.concat({ "R" .. i .. "." .. n, tostring(r.shown), D.num(r.width), D.num(r.height), D.num(r.alpha), points(r),
						D.list(colour), tostring(r.file), tostring(r.atlas), D.list(r.vertex), g and not flat and (g[1] .. D.num(g[2].r) .. D.num(g[2].g) .. D.num(g[2].a) .. D.num(g[3].r) .. D.num(g[3].g) .. D.num(g[3].a)) or "-",
						tostring(r.text), r.font and (r.font[1] .. D.num(r.font[2]) .. tostring(r.font[3])) or "-", D.list(r.textColour), D.list(r.shadowOff), D.num(r.shadowAlpha) }, " ")
				end
			end
		end
		return table.concat(rows, "\n")
	end
	-- The text of the font strings that are shown, one line each.
	function D.texts(W, from)
		local out = {}
		for i = from + 1, #W.addonFrames do
			for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				if r.kind == "FontString" and r.text and r.shown ~= false then
					out[#out + 1] = r.text
				end
			end
		end
		return table.concat(out, "\n")
	end
	-- The font string with exactly this text.
	function D.font(W, from, text)
		for i = from + 1, #W.addonFrames do
			for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				if r.kind == "FontString" and r.text == text then
					return r
				end
			end
		end
	end
	-- How many shown textures have this colour.
	function D.shown(W, from, r, g, b, a)
		local n = 0
		for i = from + 1, #W.addonFrames do
			for _, t in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				local c = t.color
				if t.kind == "Texture" and t.shown ~= false and c and math.abs(c[1] - r) < 1e-6 and math.abs(c[2] - g) < 1e-6 and math.abs(c[3] - b) < 1e-6 and math.abs(c[4] - a) < 1e-6 then
					n = n + 1
				end
			end
		end
		return n
	end
	-- The top edge of the outline on a frame (a region whose colour and shown the outline sets).
	function D.edge(W, from, frame)
		for i = from + 1, #W.addonFrames do
			local raw = W.rawOf[W.addonFrames[i]]
			if raw.parent == frame and raw.allPoints == frame then
				return raw.regions[1]
			end
		end
	end
	function D.same(c, r, g, b)
		return c ~= nil and math.abs(c[1] - r) < 1e-6 and math.abs(c[2] - g) < 1e-6 and math.abs(c[3] - b) < 1e-6
	end
	-- The first line that differs between two pictures.
	function D.diff(one, two)
		local a, b, nl = {}, {}, string.char(10)
		for line in (one .. nl):gmatch("([^" .. nl .. "]*)" .. nl) do a[#a + 1] = line end
		for line in (two .. nl):gmatch("([^" .. nl .. "]*)" .. nl) do b[#b + 1] = line end
		for i = 1, math.max(#a, #b) do
			if a[i] ~= b[i] then
				return tostring(a[i]) .. "  =>  " .. tostring(b[i])
			end
		end
	end
	-- One drawing in a world of its own: the checks of a drawing and the settings that change it.
	function D.run(id, settings)
		local W = D.world()
		local ns = W.ns
		-- The faces the client loads are found once, with a font string of the addon's own.
		ns.FontFile("friz")
		local from = #W.addonFrames
		local drawing = ns.SetupDrawings[id]
		check("sdchat: " .. id .. ": it is registered with build, draw and parts", type(drawing) == "table" and type(drawing.build) == "function" and type(drawing.draw) == "function" and type(drawing.parts) == "table")
		local stage = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		stage:SetSize(658, 204)
		local made = #W.addonFrames
		drawing.build(stage)
		local frames, textures, fonts = #W.addonFrames, #W.addonTextures, #W.addonFonts
		local own = true
		for i = made + 1, #W.addonFrames do
			own = own and ns.Own[W.addonFrames[i]] == true
		end
		for _, t in ipairs(W.addonTextures) do
			own = own and ns.Own[t] == true
		end
		for _, t in ipairs(W.addonFonts) do
			own = own and ns.Own[t] == true
		end
		check("sdchat: " .. id .. ": every frame, texture and font string it makes is in ns.Own", own and #W.addonFrames > made)
		local parts = true
		for _, part in pairs(drawing.parts) do
			parts = parts and type(part) == "table"
		end
		check("sdchat: " .. id .. ": every part is a frame or a region", parts and next(drawing.parts) ~= nil)
		drawing.draw(stage)
		check("sdchat: " .. id .. ": drawing makes nothing more", #W.addonFrames == frames and #W.addonTextures == textures and #W.addonFonts == fonts, #W.addonFrames .. " " .. frames .. " " .. #W.addonTextures .. " " .. textures .. " " .. #W.addonFonts .. " " .. fonts)
		local first = D.fp(W, from)
		drawing.draw(stage)
		check("sdchat: " .. id .. ": drawing twice gives the same picture", D.fp(W, from) == first)
		check("sdchat: " .. id .. ": no violation and no error while it builds and draws", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | ") .. table.concat(W.errors, " | "))
		local changed = 0
		for _, row in ipairs(settings) do
			local path, alt, before = row[1], row[2], row[3] or {}
			local saved = {}
			for key in pairs(before) do
				saved[key] = ns.Get(key)
			end
			saved[path] = ns.Get(path)
			for key, value in pairs(before) do
				ns.Set(key, value)
			end
			drawing.draw(stage)
			local one = D.fp(W, from)
			ns.Set(path, alt)
			drawing.draw(stage)
			local two = D.fp(W, from)
			if one ~= two then
				changed = changed + 1
			end
			check("sdchat: " .. id .. ": " .. path .. " changes the drawing", one ~= two)
			for key, value in pairs(saved) do
				ns.Set(key, value)
			end
			drawing.draw(stage)
		end
		check("sdchat: " .. id .. ": all " .. #settings .. " settings change the drawing", changed == #settings, changed)
		check("sdchat: " .. id .. ": back at the defaults it draws the first picture", D.fp(W, from) == first, D.diff(first, D.fp(W, from)))
		check("sdchat: " .. id .. ": no violation and no error after every change", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | ") .. table.concat(W.errors, " | "))
		return W, ns, drawing, stage, from
	end

	-- Chat: windows and input (step 36) and chat text (step 37).
	do
		local W, ns, drawing, stage, from = D.run("mock-chat", {
			{ "chat.enabled", false }, { "chat.frames", false }, { "chat.opacity", 20 }, { "chat.tabs", false }, { "chat.buttons", false },
			{ "chat.frameBorder", false }, { "chat.editbox", false }, { "chat.inputPlace", "above" }, { "chat.inputIdle", 80 }, { "chat.inputFocus", "accent" },
			{ "chat.lookOwn", true, { ["chat.lookBorder"] = "ffff0000", ["chat.lookBack"] = "ff304050", ["chat.lookBackAlpha"] = 40 } },
			{ "chat.lookBorder", "ff00ff00", { ["chat.lookOwn"] = true } }, { "chat.lookBack", "ff804020", { ["chat.lookOwn"] = true } },
			{ "chat.lookBackAlpha", 30, { ["chat.lookOwn"] = true } },
			{ "chat.timestamps", "hhmmss" }, { "chat.classColour", "never" }, { "chat.font", "friz" }, { "chat.outline", "thick" }, { "chat.shadow", false },
		})
		local function lines() return D.texts(W, from) end
		check("sdchat: chat: lines have no timestamp and every name has its class colour at the defaults", not lines():find("03:27", 1, true) and lines():find("[1. General] |cff", 1, true) ~= nil
			and lines():find("[Party] |cff", 1, true) ~= nil and lines():find("[Guild] |cff", 1, true) ~= nil, lines())
		ns.Set("chat.timestamps", "hhmmssAm")
		drawing.draw(stage)
		check("sdchat: chat: a timestamp is written as the choice writes it, before the channel", lines():find("03:27:32 PM [1. General]", 1, true) ~= nil and lines():find("03:27:32 PM You receive loot", 1, true) ~= nil, lines())
		ns.Set("chat.timestamps", "hhmm24")
		drawing.draw(stage)
		check("sdchat: chat: 24 hour time", lines():find("15:27 [Party]", 1, true) ~= nil, lines())
		ns.Set("chat.timestamps", "none")
		ns.Set("chat.classColour", "never")
		drawing.draw(stage)
		check("sdchat: chat: never colours no name by class", not lines():find("|cff", 1, true), lines())
		ns.Set("chat.classColour", "channel")
		drawing.draw(stage)
		check("sdchat: chat: per channel colours the party and guild names and leaves the general name", lines():find("[1. General] Hunterly", 1, true) ~= nil
			and lines():find("[Party] |cff", 1, true) ~= nil and lines():find("[Guild] |cff", 1, true) ~= nil, lines())
		ns.Set("chat.classColour", "always")
		drawing.draw(stage)
		local general = "[1. General] |cffabd473Hunterly|r: any healer for Deadmines?"
		local line = D.font(W, from, general)
		check("sdchat: chat: the game's chat font is Arial Narrow 14 with no outline and a shadow, and a line has its channel colour", line and line.font[1] == "Fonts\\ARIALN.TTF" and line.font[2] == 14 and line.font[3] == ""
			and line.textColour[1] == 1 and line.textColour[2] == 0.75 and line.shadowOff[1] == 1 and line.shadowOff[2] == -1, line and (line.font[1] .. " " .. line.font[2]))
		ns.Set("chat.font", "morpheus")
		ns.Set("chat.outline", "outline")
		ns.Set("chat.shadow", false)
		drawing.draw(stage)
		line = D.font(W, from, general)
		check("sdchat: chat: a chosen face, outline and no shadow reach every line", line and line.font[1] == "Fonts\\MORPHEUS.TTF" and line.font[3] == "OUTLINE" and line.shadowOff[1] == 0 and line.shadowOff[2] == 0,
			line and (line.font[1] .. " " .. tostring(line.font[3])))
		ns.Set("chat.enabled", false)
		drawing.draw(stage)
		line = D.font(W, from, general)
		check("sdchat: chat: with Restyle chat and tooltips off the text is in the game's face again", line and line.font[1] == "Fonts\\ARIALN.TTF" and line.font[3] == "" and line.shadowOff[1] == 1, line and line.font[1])
		ns.Set("chat.enabled", true)
		ns.Set("chat.font", "default")
		ns.Set("chat.outline", "game")
		ns.Set("chat.shadow", true)
		drawing.draw(stage)
		-- The input box is under the window, above the tabs with Above, and its opacity is the row's.
		local box, window = drawing.parts.input, drawing.parts.window
		local function y(frame) return W.rawOf[frame].points[1][5] end
		check("sdchat: chat: the input box is under the window", y(box) < y(window), y(box) .. " " .. y(window))
		ns.Set("chat.inputPlace", "above")
		drawing.draw(stage)
		check("sdchat: chat: above, it is over the window and its tabs", y(box) > y(drawing.parts.tabs) and y(box) > y(window), y(box) .. " " .. y(window))
		ns.Set("chat.inputPlace", "below")
		drawing.draw(stage)
		check("sdchat: chat: the idle box has the opacity of the game, 35 percent", math.abs(W.rawOf[box].alpha - 0.35) < 1e-6, W.rawOf[box].alpha)
		ns.Set("chat.inputIdle", 80)
		drawing.draw(stage)
		check("sdchat: chat: and 80 percent when the row says 80, while the box being typed in stays whole", math.abs(W.rawOf[box].alpha - 0.8) < 1e-6 and math.abs(W.rawOf[drawing.parts.typing].alpha - 1) < 1e-6, W.rawOf[box].alpha)
		ns.Set("chat.inputIdle", 35)
		drawing.draw(stage)
		-- With the module off the input box stays where the game has it and idles at the game's opacity.
		ns.Set("chat.enabled", false)
		ns.Set("chat.inputPlace", "above")
		ns.Set("chat.inputIdle", 80)
		drawing.draw(stage)
		check("sdchat: chat: with Restyle chat and tooltips off the box stays under the window at 35 percent", y(box) < y(window) and math.abs(W.rawOf[box].alpha - 0.35) < 1e-6, y(box) .. " " .. y(window) .. " " .. W.rawOf[box].alpha)
		ns.Set("chat.enabled", true)
		ns.Set("chat.inputPlace", "below")
		ns.Set("chat.inputIdle", 35)
		-- The window border and fill are shown at 60 percent and not at 0, the tab of the window has the highlight colour, the box being typed in
		-- has the colour of the chat type, the highlight colour or the plain border, and the tabs follow each other.
		drawing.draw(stage)
		local top = D.edge(W, from, window)
		check("sdchat: chat: the thin border of the window shows at 60 percent opacity", top.shown == true)
		ns.Set("chat.opacity", 0)
		drawing.draw(stage)
		check("sdchat: chat: and nothing of the window shows at 0 percent", top.shown == false)
		ns.Set("chat.opacity", 60)
		drawing.draw(stage)
		local ar, ag, ab = ns.Colour("windows.accent")
		check("sdchat: chat: the selected tab has the highlight colour", D.same(D.edge(W, from, drawing.parts.tabs).color, ar, ag, ab), D.list(D.edge(W, from, drawing.parts.tabs).color))
		local typing = drawing.parts.typing
		check("sdchat: chat: the box being typed in has the colour of the party channel", D.same(D.edge(W, from, typing).color, 0.67, 0.67, 1), D.list(D.edge(W, from, typing).color))
		ns.Set("chat.inputFocus", "accent")
		drawing.draw(stage)
		check("sdchat: chat: or the highlight colour", D.same(D.edge(W, from, typing).color, ar, ag, ab))
		ns.Set("chat.inputFocus", "plain")
		drawing.draw(stage)
		check("sdchat: chat: or the border of the other boxes", D.same(D.edge(W, from, typing).color, 0, 0, 0) and D.same(D.edge(W, from, box).color, 0, 0, 0), D.list(D.edge(W, from, typing).color))
		ns.Set("chat.inputFocus", "type")
		drawing.draw(stage)
		local tabs = {}
		for i = from + 1, #W.addonFrames do
			local raw = W.rawOf[W.addonFrames[i]]
			if raw.width and raw.height == 22 and raw.points[1] and raw.points[1][2] == W.rawOf[window].parent then
				tabs[#tabs + 1] = raw
			end
		end
		check("sdchat: chat: three tabs of 76, 88 and 68 stand 2 apart", #tabs == 3 and tabs[2].points[1][4] - tabs[1].points[1][4] == 78 and tabs[3].points[1][4] - tabs[2].points[1][4] == 90, #tabs)
		do
			local function label() local r = D.font(W, from, "Game look") return r and r.shown ~= false end
			ns.Set("chat.enabled", true); drawing.draw(stage)
			check("sdchat: chat: with every plate the addon draws, no Game look label shows", not label())
			ns.Set("chat.enabled", false); drawing.draw(stage)
			check("sdchat: chat: with Restyle chat and tooltips off, Game look is written under the window", label() == true)
			ns.Set("chat.enabled", true); drawing.draw(stage)
		end
		check("sdchat: chat: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "))
	end

	-- Tooltips (step 38).
	do
		local W, ns, drawing, stage, from = D.run("mock-tooltip", {
			{ "chat.enabled", false }, { "chat.tooltips", false }, { "chat.tipBackground", "darkblue" }, { "chat.tipOpacity", 100 }, { "chat.tipShading", "lighter" },
			{ "chat.quality", false }, { "chat.kindWord", false }, { "chat.kindBorder", false },
			{ "chat.tipOwn", true, { ["chat.tipBorder"] = "ffff0000" } }, { "chat.tipBorder", "ff00ff00", { ["chat.tipOwn"] = true } },
			{ "chat.unitBorder", "reaction" }, { "chat.nameClass", true }, { "chat.tipScale", 150 }, { "chat.tipTitleSize", 150 }, { "chat.tipTextSize", 150 },
			{ "chat.health", false }, { "chat.barHide", true }, { "chat.barHeight", 14 }, { "chat.ids", true }, { "chat.count", true },
		})
		-- The colour of the top edge of the outline on a frame.
		local function edge(frame) return D.edge(W, from, frame).color end
		local item, mob, player = drawing.parts.item, drawing.parts.unit, drawing.parts.player
		local same = D.same
		check("sdchat: tooltip: the item has its quality border, the rare unit the silver of a Rare Elite and the player the plain border",
			same(edge(item), 0.64, 0.21, 0.93) and same(edge(mob), 0.78, 0.80, 0.84) and same(edge(player), 0, 0, 0), D.list(edge(item)) .. " " .. D.list(edge(mob)) .. " " .. D.list(edge(player)))
		check("sdchat: tooltip: the unit shows Rare Elite and the item has no extra lines", D.texts(W, from):find("Rare Elite", 1, true) ~= nil and not D.texts(W, from):find("Item ID", 1, true) and not D.texts(W, from):find("Count:", 1, true), D.texts(W, from))
		ns.Set("chat.ids", true)
		ns.Set("chat.count", true)
		ns.Set("chat.unitBorder", "reaction")
		drawing.draw(stage)
		check("sdchat: tooltip: the id and the count are lines of the item, and a reaction border is the colour of the name", D.texts(W, from):find("Item ID: 873", 1, true) ~= nil
			and D.texts(W, from):find("Count: 3 in bags", 1, true) ~= nil and same(edge(mob), 0.8, 0.3, 0.22) and same(edge(player), 1, 1, 1), D.list(edge(mob)))
		ns.Set("chat.unitBorder", "class")
		drawing.draw(stage)
		check("sdchat: tooltip: a class border on a player is the class colour, and on an enemy the reaction colour", not same(edge(player), 0, 0, 0) and same(edge(mob), 0.8, 0.3, 0.22), D.list(edge(player)))
		ns.Set("chat.unitBorder", "plain")
		ns.Set("chat.ids", false)
		ns.Set("chat.count", false)
		drawing.draw(stage)
		check("sdchat: tooltip: the box is the near black at 70 percent and no plain plate shows", D.shown(W, from, 15 / 255, 15 / 255, 15 / 255, 0.7) == 0 and D.shown(W, from, 0.06, 0.06, 0.12, 0.9) == 0)
		ns.Set("chat.tooltips", false)
		drawing.draw(stage)
		check("sdchat: tooltip: with the border and background off each box is the game's plain plate", D.shown(W, from, 0.06, 0.06, 0.12, 0.9) == 3)
		do
			local n = 0
			for k = from + 1, #W.addonFrames do
				for _, r in ipairs(W.rawOf[W.addonFrames[k]].regions or {}) do
					if r.kind == "FontString" and r.text == "Game look" and r.shown ~= false then n = n + 1 end
				end
			end
			check("sdchat: tooltip: each of the three plain plates has a Game look label", n == 3, n)
		end
		ns.Set("chat.tooltips", true)
		local top = W.rawOf[item]
		check("sdchat: tooltip: the frame is 190 wide at 100 percent", math.abs(top.width - 190) < 1e-6, top.width)
		local title, text = D.font(W, from, "Staff of Jordan"), D.font(W, from, "Binds when equipped")
		check("sdchat: tooltip: the title is 14 and the lines 12, the sizes of the game's tooltip fonts", title.font[2] == 14 and text.font[2] == 12, title.font[2] .. " " .. text.font[2])
		local bar = W.rawOf[drawing.parts["chat.health"]]
		check("sdchat: tooltip: the health bar of an enemy is red, 8 high, and takes the width of the box inside its margin", D.same(bar.bar.tint, 0.8, 0.3, 0.22) and bar.height == 8 and bar.width == 174,
			D.list(bar.bar.tint) .. " " .. tostring(bar.height) .. " " .. tostring(bar.width))
		ns.Set("chat.barHeight", 14)
		drawing.draw(stage)
		check("sdchat: tooltip: Health bar height sets the height of the bar", bar.height == 14, bar.height)
		ns.Set("chat.barHeight", 8)
		ns.Set("chat.enabled", false)
		ns.Set("chat.tipScale", 150)
		ns.Set("chat.tipTitleSize", 150)
		drawing.draw(stage)
		check("sdchat: tooltip: with Restyle chat and tooltips off the size, the title size and the bar are the game's", math.abs(top.width - 190) < 1e-6 and D.font(W, from, "Staff of Jordan").font[2] == 14
			and bar.height == 8 and D.texts(W, from):find("Rare Elite", 1, true) == nil, top.width)
		ns.Set("chat.enabled", true)
		ns.Set("chat.tipTitleSize", 100)
		ns.Set("chat.tipScale", 100)
		drawing.draw(stage)
		ns.Set("chat.tipScale", 150)
		drawing.draw(stage)
		check("sdchat: tooltip: size 150 percent makes the frame one and a half times as wide", math.abs(top.width - 285) < 1e-6, top.width)
		ns.Set("chat.tipScale", 100)
		drawing.draw(stage)
		check("sdchat: tooltip: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "))
	end

	-- Combat text (step 47).
	do
		local W, ns, drawing, stage, from = D.run("mock-combat-text", {
			{ "combattext.font", "arial" }, { "combattext.outline", "thick" }, { "combattext.shadow", true }, { "combattext.pop", "plain" },
			{ "combattext.height", 90 }, { "combattext.crit", "higher" }, { "combattext.size", 100 }, { "combattext.spread", "tight" },
			{ "combattext.movement", "up" }, { "combattext.partial", "off" }, { "combattext.school", true },
			{ "combattext.inStyle", "straight" }, { "combattext.ownSize", 60 },
		})
		-- The run puts every row back at its default, Burst now; this block is about the pop of Rise and fall.
		ns.Set("combattext.movement", "fall")
		drawing.draw(stage)
		local function fs(text) return D.font(W, from, text) end
		local crit, plain = fs("824"), fs("412")
		check("sdchat: combat: a critical hit in its pop is larger than another number", crit and plain and crit.font[2] > plain.font[2], crit and (crit.font[2] .. " " .. plain.font[2]))
		ns.Set("combattext.pop", "plain")
		drawing.draw(stage)
		check("sdchat: combat: plainly, a critical hit has its settled height, 1.2 times the number", math.abs(fs("824").font[2] - 25 * 1.4 * 1.2) < 1e-6, fs("824").font[2])
		ns.Set("combattext.pop", "pop")
		ns.Set("combattext.partial", "word")
		drawing.draw(stage)
		check("sdchat: combat: the kind of hit in parentheses follows the amount", fs("412 (Glancing)") ~= nil)
		ns.Set("combattext.partial", "off")
		drawing.draw(stage)
		check("sdchat: combat: and is left out when the row is off", fs("412 (Glancing)") == nil and fs("412") ~= nil)
		ns.Set("combattext.partial", "word")
		local off = fs("510").textColour
		ns.Set("combattext.school", true)
		drawing.draw(stage)
		local on = fs("510").textColour
		ns.Set("combattext.school", false)
		drawing.draw(stage)
		check("sdchat: combat: the fire hit is yellow, and orange with Colour by school of magic", off[1] == 1 and off[2] == 1 and off[3] == 0 and on[1] == 1 and on[2] == 0.5 and on[3] == 0)
		check("sdchat: combat: the critical hit in its pop is 64 high at a size of 140 percent and the oldest number has faded to 40 percent", fs("824").font[2] == 64 and math.abs(fs("412").alpha - 0.4) < 1e-6,
			fs("824").font[2] .. " " .. fs("412").alpha)
		local sideways
		for i = from + 1, #W.addonFrames do
			for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				if r.kind == "FontString" and r.text == "(Dodge)" and r.points[1][2] == drawing.parts.own.owner.parent then
					sideways = r.points[1][4]
				end
			end
		end
		check("sdchat: combat: the dodge and the gain for you move to the left by Incoming style, 0.35 and 0.1 seconds in, in the arc of Arc width Wide", near(sideways, 440 - 42 * math.sin(math.pi * 0.35 / 2.2), 1e-9) and near(fs("+20").points[1][4], 440 - 42 * math.sin(math.pi * 0.1 / 2.2), 1e-9), tostring(sideways))
		ns.Set("combattext.arcWidth", "narrow")
		drawing.draw(stage)
		local narrow
		for i = from + 1, #W.addonFrames do
			for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				if r.kind == "FontString" and r.text == "(Dodge)" and r.points[1][2] == drawing.parts.own.owner.parent then
					narrow = r.points[1][4]
				end
			end
		end
		check("msbt arc: the setup drawing uses the chosen arc width", near(narrow, 440 - 24 * math.sin(math.pi * 0.35 / 2.2), 1e-9), tostring(narrow))
		ns.Set("combattext.arcWidth", "wide")
		ns.Set("combattext.friendWords", true)
		ns.Set("combattext.friend", "both")
		drawing.draw(stage)
		check("msbt paren: the setup samples show (Dodge) and (Miss)", fs("(Dodge)") ~= nil and fs("(Miss)") ~= nil and fs("Dodge") == nil and fs("Miss") == nil)
		ns.Set("combattext.friendWords", false)
		-- Incoming style, Speed and Smaller number only reach the drawing.
		do
			local function spot(text)
				local r = fs(text)
				return g(r.points[1][4]) .. "," .. g(r.points[1][5])
			end
			local function heightsOf(text)
				local out = {}
				for i = from + 1, #W.addonFrames do
					for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
						if r.kind == "FontString" and r.text == text then
							out[#out + 1] = g(r.font[2])
						end
					end
				end
				return table.concat(out, ",")
			end
			ns.Set("combattext.inStyle", "static")
			drawing.draw(stage)
			local still = spot("+20")
			ns.Set("combattext.inStyle", "straight")
			drawing.draw(stage)
			local down = spot("+20")
			ns.Set("combattext.inStyle", "horizontal")
			ns.Set("combattext.speed", "fast")
			drawing.draw(stage)
			local fast = fs("+20").points[1][4]
			ns.Set("combattext.speed", "normal")
			ns.Set("combattext.partial", "smaller")
			drawing.draw(stage)
			local small = heightsOf("412")
			ns.Set("combattext.partial", "word")
			drawing.draw(stage)
			check("scrolling: sdchat: Static keeps a number at its start, row 5 is 4 lines under it, Straight moves it down by its age, and Fast moves a Horizontal number further", still == "440,46" and down ~= still
				and near(fast, 440 - 72 * 0.1 / 1.6, 1e-9), still .. " " .. down .. " " .. tostring(fast))
			check("scrolling: sdchat: Smaller number only draws the glancing hit at 75 percent with no word", small == "35,26.25" or small == "26.25,35", small)
		end
		check("sdchat: combat: the healing is green and the dodge white", fs("215").textColour[2] == 1 and fs("215").textColour[1] == 0 and fs("(Dodge)").textColour[3] == 1)
		ns.Set("combattext.own", "take")
		drawing.draw(stage)
		local count = 0
		for i = from + 1, #W.addonFrames do
			for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
				if r.kind == "FontString" and r.shown ~= false and (r.text == "(Dodge)" or r.text == "+20") then
					count = count + 1
				end
			end
		end
		check("sdchat: combat: for you, Damage and healing you take shows neither the dodge nor the gain", count == 1, count)
		ns.Set("combattext.own", "off")
		drawing.draw(stage)
		check("sdchat: combat: Off shows no number for you", fs("-412").shown == false and fs("+300").shown == false)
		ns.Set("combattext.own", "more")
		drawing.draw(stage)
		local plate = W.rawOf[drawing.parts.plate].level
		local front = W.rawOf[drawing.parts.enemy.owner].level
		check("sdchat: combat: the numbers are in front of the nameplate", front > plate, front .. " " .. plate)
		ns.Set("combattext.source", "game")
		drawing.draw(stage)
		check("sdchat: combat: As the game has them puts the numbers under the nameplate", W.rawOf[drawing.parts.enemy.owner].level < plate, W.rawOf[drawing.parts.enemy.owner].level .. " " .. plate)
		-- With the game's own numbers, the font, the kind of hit and the school colours reach the numbers over you and not the enemy ones.
		do
			local function rows(texts)
				local out = {}
				for _, text in ipairs(texts) do
					local r = fs(text)
					out[#out + 1] = r and (table.concat({ tostring(r.text), tostring(r.font[1]), tostring(r.font[2]), tostring(r.font[3]), tostring(r.shadowOff and r.shadowOff[1]),
						tostring(r.textColour and r.textColour[1]), tostring(r.textColour and r.textColour[2]), tostring(r.textColour and r.textColour[3]), tostring(r.alpha),
						tostring(r.shown) }, ",")) or "none"
				end
				return table.concat(out, ";")
			end
			local enemy, mine = { "412", "412 (Glancing)", "215", "510", "Dodge", "824" }, { "-412", "-824", "+300", "+20" }
			ns.Set("combattext.font", "friz"); ns.Set("combattext.outline", "none"); ns.Set("combattext.shadow", false)
			ns.Set("combattext.partial", "off"); ns.Set("combattext.school", false)
			drawing.draw(stage)
			local e1, o1 = rows(enemy), rows(mine)
			ns.Set("combattext.font", "morpheus"); ns.Set("combattext.outline", "thick"); ns.Set("combattext.shadow", true)
			ns.Set("combattext.partial", "word"); ns.Set("combattext.school", true)
			drawing.draw(stage)
			check("sdchat: combat: with As the game has them, Font, Outline, Shadow, Kind of hit and Colour by school leave the enemy numbers as they were", rows(enemy) == e1, e1 .. " => " .. rows(enemy))
			check("sdchat: combat: with As the game has them, those rows still change the numbers over you", rows(mine) ~= o1)
			check("sdchat: combat: with As the game has them, the enemy numbers are in the game's face and have no kind of hit", fs("412").font[1] == "Fonts\\FRIZQT__.TTF" and fs("412 (Glancing)") == nil, tostring(fs("412").font[1]))
		end
		ns.Set("combattext.source", "front")
		drawing.draw(stage)
		check("sdchat: combat: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "))
	end

	-- Burst over enemies in the combat text picture: the critical sample is drawn 0.03 seconds old, 62 high (2.06 times its settled 30), so the
	-- slam shows. Every other sample rises and falls. With Plainly there is no burst and the critical sample is drawn as a Rise and fall one.
	do
		local B = { runs = {} }
		for _, spec in ipairs({ { "fall", "pop", "fall" }, { "burst", "pop", "burst" }, { "fall", "plain", "fallPlain" }, { "burst", "plain", "burstPlain" },
			{ "fall", "pop", "fallApart", "apart" }, { "burst", "pop", "burstApart", "apart" } }) do
			local W, ns, drawing, stage, from = D.run("mock-combat-text", {})
			for key, value in pairs({ movement = spec[1], overlap = spec[4] or "turn", size = 100, pop = spec[2], crit = "same", friend = "both", friendUnits = "all", friendDamage = true,
				spread = "loose", spreadWidth = 100 }) do
				ns.Set("combattext." .. key, value)
			end
			local real, last = ns.CombatChoose, nil
			ns.CombatChoose = function(olds, spec2)
				local seen = {}
				for index, old in ipairs(olds) do
					seen[index] = old.movement .. "@" .. string.format("%.2f", old.age)
				end
				last = spec2.movement .. ":" .. table.concat(seen, ",")
				return real(olds, spec2)
			end
			drawing.draw(stage)
			ns.CombatChoose = real
			local function fs(text) return D.font(W, from, text) end
			local run = { last = last, crit = fs("824"), plain = fs("412"), friend = fs("-350") }
			run.out = { run.crit.font[2], run.crit.points[1][5], run.plain.points[1][5], run.friend.points[1][5], run.crit.points[1][4], run.plain.points[1][4] }
			ns.Set("combattext.source", "game")
			drawing.draw(stage)
			run.game = fs("824").points[1][5]
			ns.Set("combattext.source", "front")
			ns.Set("combattext.style", "classic")
			drawing.draw(stage)
			run.classic = fs("824").font[2]
			B.runs[spec[3]] = run
		end
		B.f, B.b, B.fp, B.bp, B.fa, B.ba = B.runs.fall, B.runs.burst, B.runs.fallPlain, B.runs.burstPlain, B.runs.fallApart, B.runs.burstApart
		check("burst: the picture shows the critical sample at 62, 2.06 times its settled 30, under Burst, and in the older pop (46) under Rise and fall", B.b.out[1] == 62 and B.f.out[1] == 46, B.b.out[1] .. " " .. B.f.out[1])
		check("burst: the picture lifts the critical sample 1.8 units at 0.03 seconds under Burst and 10.85 at 0.12 under Rise and fall", math.abs(B.b.out[2] - B.f.out[2] + 10.848 - 1.8) < 1e-3, B.b.out[2] .. " " .. B.f.out[2])
		check("burst: the picture moves the other numbers as before, the game's own numbers too, and the friendly ones", B.b.out[3] == B.f.out[3] and B.b.out[4] == B.f.out[4] and B.b.game == B.f.game, B.b.out[3] .. " " .. B.f.out[3])
		check("burst: the Classic picture has no burst", B.b.classic == B.f.classic, B.b.classic .. " " .. B.f.classic)
		check("burst: with Plainly the picture draws the critical sample at 30 and 10.85 units up, as Rise and fall does", B.bp.out[1] == 30 and B.bp.out[1] == B.fp.out[1] and B.bp.out[2] == B.fp.out[2], B.bp.out[1] .. " " .. B.fp.out[1] .. " " .. B.bp.out[2] .. " " .. B.fp.out[2])
		check("burst: with Keep apart the critical sample is placed by a burst, and the samples before it by a fall at their age measured from its 0.03 seconds",
			B.ba.last == "burst:fall@1.27,fall@1.02,fall@0.77,fall@0.57,fall@0.37" and B.fa.last == "fall:fall@1.18,fall@0.93,fall@0.68,fall@0.48,fall@0.28", tostring(B.ba.last) .. " | " .. tostring(B.fa.last))
		check("burst: with Keep apart the other samples are placed as Rise and fall places them", B.ba.out[3] == B.fa.out[3] and B.ba.out[6] == B.fa.out[6], B.ba.out[3] .. " " .. B.fa.out[3] .. " " .. B.ba.out[6] .. " " .. B.fa.out[6])
	end

	-- ctspread: the sample numbers of the combat text picture follow Spread width, Overlapping numbers and the size.
	do
		local W, ns, drawing, stage, from = D.run("mock-combat-text", {
			{ "combattext.spreadWidth", 200 }, { "combattext.overlap", "turn" }, { "combattext.rows", 2 },
		})
		local function fs(text) return D.font(W, from, text) end
		local texts = { "412", "412 (Glancing)", "215", "510", "(Dodge)", "824" }
		local function spots()
			local out = {}
			for _, text in ipairs(texts) do
				out[#out + 1] = ("%.1f,%.1f"):format(fs(text).points[1][4], fs(text).points[1][5])
			end
			return table.concat(out, " ")
		end
		ns.Set("combattext.pop", "plain")
		ns.Set("combattext.size", 100)
		ns.Set("combattext.partial", "word")
		ns.Set("combattext.movement", "fall")
		ns.Set("combattext.spread", "loose")
		ns.Set("combattext.spreadWidth", 100)
		ns.Set("combattext.overlap", "turn")
		drawing.draw(stage)
		check("ctspread: sdchat: Stay in turn at a width of 100 puts the third sample in lane -20 and the fourth in lane 40, each drifted by its age",
			math.abs(fs("215").points[1][4] - (-20 - 20 * 0.75 * 0.8)) < 1e-6 and math.abs(fs("510").points[1][4] - (40 + 40 * 0.75 * 0.6)) < 1e-6, spots())
		local turned = spots()
		ns.Set("combattext.spreadWidth", 300)
		drawing.draw(stage)
		check("ctspread: sdchat: a width of 300 puts the sixth sample in lane 60 where a width of 100 had it in lane 0", math.abs(fs("824").points[1][4] - (60 + 30 * 0.12)) < 1e-6 and turned ~= spots(), spots())
		ns.Set("combattext.spread", "tight")
		drawing.draw(stage)
		check("ctspread: sdchat: Tight puts every sample in lane 0 at any width", math.abs(fs("824").points[1][4]) < 1e-6 and math.abs(fs("510").points[1][4]) < 1e-6 and math.abs(fs("215").points[1][4]) < 1e-6, spots())
		ns.Set("combattext.spread", "loose")
		ns.Set("combattext.spreadWidth", 100)
		ns.Set("combattext.overlap", "apart")
		drawing.draw(stage)
		check("ctspread: sdchat: Keep apart places the samples elsewhere than Stay in turn does", spots() ~= turned, spots())
		ns.Set("combattext.size", 400)
		ns.Set("combattext.height", 100)
		ns.Set("combattext.overlap", "turn")
		drawing.draw(stage)
		local top = true
		for _, text in ipairs(texts) do
			top = top and fs(text).points[1][5] <= 204 - 44 - fs(text).font[2] / 2 + 1e-6
		end
		check("ctspread: sdchat: at a size of 400 no sample goes above the top of the stage", top, spots())
		check("ctspread: sdchat: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | ") .. table.concat(W.errors, " | "))
	end

	-- Combat text in the Classic style.
	do
		local W, ns, drawing, stage, from = D.run("mock-combat-text", { { "combattext.style", "classic" }, { "combattext.pop", "plain" } })
		local function all(text)
			local out = {}
			for i = from + 1, #W.addonFrames do
				for _, r in ipairs(W.rawOf[W.addonFrames[i]].regions or {}) do
					if r.kind == "FontString" and r.text == text then
						out[#out + 1] = r
					end
				end
			end
			return out
		end
		ns.Set("combattext.style", "classic")
		ns.Set("combattext.pop", "plain")
		ns.Set("combattext.partial", "smaller")
		drawing.draw(stage)
		local function colour(r) return r and table.concat(r.textColour, ",") or "none" end
		local function xy(r) return r and (r.points[1][4] .. "," .. r.points[1][5]) or "none" end
		local both = all("412")
		check("ctclassic: drawing: with Smaller number only the glancing hit has no word and is 75 percent of the size", #both == 2 and both[1].font[2] == 35 and both[2].font[2] == 26.25 and #all("412 (Glancing)") == 0,
			#both .. " " .. (both[2] and both[2].font[2] or "none"))
		local ys, xs = {}, {}
		for _, text in ipairs({ "412", "215", "510", "(Dodge)", "824" }) do
			local r = all(text)[1]
			ys[#ys + 1], xs[#xs + 1] = r.points[1][5], r.points[1][4]
		end
		check("ctclassic: drawing: the older a number the higher it is, and the fifth and sixth go to the next column, 112 units to the right", both[1].points[1][5] > both[2].points[1][5] and both[2].points[1][5] > ys[2] and ys[2] > ys[3]
			and xs[1] == 0 and xs[2] == 0 and xs[3] == 0 and xs[4] == 112 and xs[5] == 112, table.concat(ys, ",") .. " | " .. table.concat(xs, ","))
		check("ctclassic: drawing: a critical hit pops although How a number appears is Plainly", all("824")[1].font[2] == 64, all("824")[1].font[2])
		check("ctclassic: drawing: White and yellow, then the heal green 0", colour(all("510")[1]) == "1,1,0" and colour(all("215")[1]) == "0,1,0", colour(all("510")[1]) .. " " .. colour(all("215")[1]))
		local base = xy(all("412")[1])
		ns.Set("combattext.classicColour", "game")
		drawing.draw(stage)
		check("ctclassic: drawing: Red and purple colours physical hits red, magic purple and a heal green 0.1, 1, 0.1", colour(all("412")[1]) == "1,0.1,0.1" and colour(all("510")[1]) == "0.79,0.3,0.85" and colour(all("215")[1]) == "0.1,1,0.1",
			colour(all("412")[1]) .. " " .. colour(all("510")[1]) .. " " .. colour(all("215")[1]))
		ns.Set("combattext.classicColour", "portrait")
		ns.Set("combattext.classicSigns", true)
		drawing.draw(stage)
		check("ctclassic: drawing: signs put - before a hit and + before a heal, and none before a word (the character has its own -412, -824 and Dodge)", #all("-412") == 3 and #all("+215") == 1 and #all("-510") == 1 and #all("(Dodge)") == 2 and #all("-824") == 2,
			#all("-412") .. #all("+215") .. #all("-510") .. #all("(Dodge)") .. #all("-824"))
		ns.Set("combattext.classicSigns", false)
		ns.Set("combattext.partial", "word")
		drawing.draw(stage)
		check("ctclassic: drawing: with Word after the number the glancing hit has its word and the whole size", #all("412 (Glancing)") == 1 and all("412 (Glancing)")[1].font[2] == 35)
		ns.Set("combattext.partial", "smaller")
		ns.Set("combattext.classicRise", 200)
		drawing.draw(stage)
		check("ctclassic: drawing: Rise distance moves the numbers", xy(all("412")[1]) ~= base, xy(all("412")[1]) .. " " .. base)
		ns.Set("combattext.classicRise", 100)
		ns.Set("combattext.classicTime", 50)
		drawing.draw(stage)
		check("ctclassic: drawing: at 50 percent the oldest number, 1.3 seconds old, is gone and the newest still shows", all("412")[1].alpha == 0 and all("824")[1].alpha == 1, all("412")[1].alpha .. " " .. all("824")[1].alpha)
		ns.Set("combattext.classicTime", 100)
		ns.Set("combattext.classicStack", "down")
		drawing.draw(stage)
		check("ctclassic: drawing: with New numbers start lower the newer a number the lower it is", all("215")[1].points[1][5] < all("412")[1].points[1][5] and xy(all("412")[1]) ~= base, xy(all("412")[1]))
		ns.Set("combattext.classicStack", "up")
		local held = xy(all("824")[1])
		ns.Set("combattext.classicCrit", false)
		drawing.draw(stage)
		check("ctclassic: drawing: a critical hit that does not stay in place rises", xy(all("824")[1]) ~= held, xy(all("824")[1]) .. " " .. held)
		ns.Set("combattext.classicCrit", true)
		ns.Set("combattext.style", "flat")
		ns.Set("combattext.partial", "word")
		drawing.draw(stage)
		check("ctclassic: drawing: Flat UI style has the word, the pop and the lanes of before", #all("412 (Glancing)") == 1 and all("824")[1].font[2] == 42 and all("412")[1].points[1][4] == 0, tostring(all("824")[1].font[2]))
		ns.Set("combattext.style", "classic")
		ns.Set("combattext.source", "game")
		drawing.draw(stage)
		check("ctclassic: drawing: with As the game has them the numbers over enemies are not Classic", #all("412 (Glancing)") == 0 and #all("412") == 2 and #all("-412") == 1 and colour(all("510")[1]) == "1,1,0" and all("412")[2].font[2] == 35,
			#all("412") .. " " .. colour(all("510")[1]) .. " " .. tostring(all("412")[2] and all("412")[2].font[2]) .. " " .. #all("412 (Glancing)") .. #all("-412"))
		ns.Set("combattext.source", "front")
		drawing.draw(stage)
		check("ctclassic: drawing: no violation or error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "))
	end
end
-- >>> sdchat (end)

-- >>> sdtrack (begin)
-- The setup drawings of the tracker, proc, cooldown, party cooldown and enemy cooldown steps (SetupDrawTrackers.lua): each is built on a stage frame, every
-- region is of the addon's own, and a drawn setting written to another value draws another picture.
do
	local up = TOC.df.iconWorld
	local ids = { "mock-tracker", "mock-tracker-states", "mock-proc", "mock-cooldown-row", "mock-party-cooldowns", "mock-enemy-cooldowns" }
	local function stageOf(W)
		local frame = W.env.CreateFrame("Frame", nil, W.env.UIParent)
		W.ns.Own[frame] = true
		return frame
	end
	-- Everything a picture says: the shown state, size, points, colours, textures, texts, fonts and alphas of every frame and region under a frame, the
	-- sweep and the bar of each, written as one text.
	local function ser(value)
		if type(value) == "number" then
			return ("%.3f"):format(value)
		elseif type(value) == "table" then
			local parts = {}
			for _, item in ipairs(value) do
				parts[#parts + 1] = ser(item)
			end
			return "{" .. table.concat(parts, ",") .. "}"
		end
		return tostring(value)
	end
	local function points(object)
		local out = {}
		for _, p in ipairs(object.points or {}) do
			out[#out + 1] = p[1] .. ">" .. tostring(p[3]) .. ":" .. ser(p[4]) .. ":" .. ser(p[5])
		end
		return table.concat(out, ";") .. (object.allPoints and "+all" or "")
	end
	local function fingerprint(frame, out, hidden)
		out = out or {}
		hidden = hidden or frame.shown == false
		if hidden then
			-- Under a frame that is not shown nothing is drawn: what the frames and regions keep from earlier is not part of the picture.
			out[#out + 1] = "F|false"
			for _ in ipairs(frame.regions or {}) do
				out[#out + 1] = "R|false"
			end
			for _, child in ipairs(frame.children or {}) do
				fingerprint(child, out, true)
			end
			return out
		end
		local cd, bar = frame.cd, frame.bar
		out[#out + 1] = table.concat({ "F", ser(frame.shown), ser(frame.alpha), ser(frame.width), ser(frame.height), ser(frame.scale), points(frame),
			cd and ser(cd.sweep and { cd.sweep.start, cd.sweep.duration }) or "", cd and ser({ cd.swipeColour, cd.hideNumbers, cd.drawSwipe, cd.fsFont and cd.fsFont[1], cd.fsFont and cd.fsFont[2], cd.fsFont and cd.fsFont[3] }) or "",
			bar and ser({ bar.value, bar.tint, bar.texture }) or "" }, "|")
		for _, region in ipairs(frame.regions or {}) do
			out[#out + 1] = table.concat({ "R", ser(region.shown), ser(region.alpha), ser(region.width), ser(region.height), points(region), ser(region.color),
				ser(region.vertex), ser(region.file), ser(region.atlas), ser(region.texCoord), ser(region.desaturated == true), ser(region.text), ser(region.fontObject),
				ser(region.textHeight), ser(region.textColour), ser(region.font) }, "|")
		end
		for _, child in ipairs(frame.children or {}) do
			fingerprint(child, out)
		end
		return out
	end
	-- A frame or region that is not shown draws nothing, so what it keeps from earlier is not part of the picture. A text keeps the size it was last set to,
	-- which is compared when two settings are drawn but not when the same settings are drawn again after others.
	local function printed(frame, loose)
		local lines = fingerprint(frame)
		for index, line in ipairs(lines) do
			if line:match("^%a|false|") then
				lines[index] = line:sub(1, 1) .. "|false"
			elseif loose and line:sub(1, 1) == "R" then
				lines[index] = line:gsub("|[^|]*$", "")
			end
		end
		return table.concat(lines, "\n")
	end
	-- One world and one stage for each drawing.
	local worlds = {}
	local function worldOf(id)
		local entry = worlds[id]
		if not entry then
			local W = up()
			local ns = W.ns
			local stage = stageOf(W)
			local frames, textures, fonts = #W.addonFrames, #W.addonTextures, #W.addonFonts
			local ok, err = xpcall(function() ns.SetupDrawings[id].draw(stage) end, debug.traceback)
			entry = { W = W, ns = ns, stage = stage, drawing = ns.SetupDrawings[id], ok = ok, err = err, frames = frames, textures = textures, fonts = fonts }
			worlds[id] = entry
		end
		return entry
	end
	local registered = true
	for _, id in ipairs(ids) do
		local d = worldOf(id).ns.SetupDrawings[id]
		registered = registered and type(d) == "table" and type(d.build) == "function" and type(d.draw) == "function" and type(d.parts) == "table" and type(d.extent) == "function"
	end
	check("sdtrack: the six drawings are registered, each a table with build, draw, parts and extent", registered)
	for _, id in ipairs(ids) do
		local E = worldOf(id)
		local W, ns = E.W, E.ns
		local own = true
		for index = E.frames + 1, #W.addonFrames do
			own = own and (W.addonFrames[index] == E.stage or ns.Own[W.addonFrames[index]] == true)
		end
		for index = E.textures + 1, #W.addonTextures do
			own = own and ns.Own[W.addonTextures[index]] == true
		end
		for index = E.fonts + 1, #W.addonFonts do
			own = own and ns.Own[W.addonFonts[index]] == true
		end
		local w, h = E.drawing.extent(E.stage)
		check("sdtrack: " .. id .. " builds and draws on a stage, every frame, texture and text of the addon's own, no violation, no error", E.ok and own and #W.violations == 0
			and #W.errors == 0 and #W.addonFrames > E.frames and #W.addonTextures > E.textures, tostring(E.err) .. " " .. table.concat(W.violations, " | "))
		check("sdtrack: " .. id .. " says its size in units, a whole width and height above 1", type(w) == "number" and type(h) == "number" and w > 1 and h > 1 and w == math.floor(w) and h == math.floor(h),
			tostring(w) .. " by " .. tostring(h))
		local again = printed(E.stage)
		E.drawing.draw(E.stage)
		check("sdtrack: " .. id .. " drawn again with the same settings gives the same picture", printed(E.stage) == again)
	end
	-- Every drawn setting of the steps: the drawing, the path, the value it is written to, and the settings it needs first.
	local cases = {
		{ "mock-tracker", "trackers.enabled", false }, { "mock-tracker", "trackers.shape", "bar" }, { "mock-tracker", "trackers.size", 48 },
		{ "mock-tracker", "trackers.barWidth", 200 }, { "mock-tracker", "trackers.barHeight", 20 }, { "mock-tracker", "trackers.barFill", "time" },
		{ "mock-tracker", "trackers.colour", "ffe64d4d" }, { "mock-tracker", "trackers.counts", false }, { "mock-tracker", "trackers.names", false },
		{ "mock-tracker", "trackers.numbers", false }, { "mock-tracker", "trackers.grow", "right" }, { "mock-tracker", "trackers.spacing", 12 },
		{ "mock-tracker", "defensives.enabled", false }, { "mock-tracker", "defensives.place", "resource" }, { "mock-tracker", "defensives.caster", false },
		{ "mock-tracker-states", "trackers.low", 2 }, { "mock-tracker-states", "trackers.lowTime", 60 }, { "mock-tracker-states", "trackers.missing", "word" },
		{ "mock-proc", "trackers.procColour", "ff3399ff" }, { "mock-proc", "trackers.art", false }, { "mock-proc", "trackers.artSize", 150 },
		{ "mock-proc", "trackers.artAlpha", 30 }, { "mock-proc", "trackers.artY", 60 }, { "mock-proc", "trackers.glow", false },
		{ "mock-cooldown-row", "cooldowns.enabled", false }, { "mock-cooldown-row", "cooldowns.trinkets", true }, { "mock-cooldown-row", "cooldowns.size", 48 },
		{ "mock-cooldown-row", "cooldowns.spacing", 10 }, { "mock-cooldown-row", "cooldowns.perRow", 4 }, { "mock-cooldown-row", "cooldowns.grow", "right" },
		{ "mock-cooldown-row", "cooldowns.rows", "up" }, { "mock-cooldown-row", "cooldowns.crop", 0 }, { "mock-cooldown-row", "cooldowns.border", false },
		{ "mock-cooldown-row", "cooldowns.numbers", false }, { "mock-cooldown-row", "cooldowns.dim", false }, { "mock-cooldown-row", "cooldowns.manager", false },
		{ "mock-cooldown-row", "cooldowns.dimDesat", false }, { "mock-cooldown-row", "cooldowns.dimDarkness", 70 }, { "mock-cooldown-row", "cooldowns.coolAlpha", 50 },
		{ "mock-cooldown-row", "cooldowns.readyAlpha", 50 }, { "mock-cooldown-row", "cooldowns.idleAlpha", 50 }, { "mock-cooldown-row", "cooldowns.borderState", true },
		{ "mock-cooldown-row", "cooldowns.readyColour", "ff3366ff", { { "cooldowns.borderState", true } } },
		{ "mock-cooldown-row", "cooldowns.coolingColour", "ff33ccff", { { "cooldowns.borderState", true } } }, { "mock-cooldown-row", "cooldowns.flash", true },
		{ "mock-cooldown-row", "cooldowns.numbersFont", "large" }, { "mock-cooldown-row", "cooldowns.sweep", false }, { "mock-cooldown-row", "cooldowns.sweepAlpha", 30 },
		{ "mock-cooldown-row", "cooldowns.countSize", 150 }, { "mock-cooldown-row", "cooldowns.keybind", true },
		{ "mock-cooldown-row", "cooldowns.keybindSize", 150, { { "cooldowns.keybind", true } } },
		{ "mock-party-cooldowns", "partycd.enabled", false }, { "mock-party-cooldowns", "partycd.side", "left" }, { "mock-party-cooldowns", "partycd.ownRow", true },
		{ "mock-party-cooldowns", "partycd.count", 3 }, { "mock-party-cooldowns", "partycd.size", 32 }, { "mock-party-cooldowns", "partycd.interrupts", false },
		{ "mock-party-cooldowns", "partycd.defensives", false }, { "mock-party-cooldowns", "partycd.externals", false }, { "mock-party-cooldowns", "partycd.breaks", true },
		{ "mock-party-cooldowns", "partycd.group", true },
		{ "mock-enemy-cooldowns", "enemycd.enabled", false }, { "mock-enemy-cooldowns", "enemycd.interrupts", false }, { "mock-enemy-cooldowns", "enemycd.defensives", false },
		{ "mock-enemy-cooldowns", "enemycd.breaks", false }, { "mock-enemy-cooldowns", "enemycd.wards", false }, { "mock-enemy-cooldowns", "enemycd.mobility", true },
		{ "mock-enemy-cooldowns", "enemycd.offensive", true }, { "mock-enemy-cooldowns", "enemycd.place", "plates" }, { "mock-enemy-cooldowns", "enemycd.seconds", false },
		{ "mock-enemy-cooldowns", "enemycd.kindBorder", false }, { "mock-enemy-cooldowns", "enemycd.size", 32 }, { "mock-enemy-cooldowns", "enemycd.ready", "flash" },
	}
	-- Other choices of the same rows, each from the default and back.
	local more = {
		{ "mock-tracker-states", "trackers.missing", "pulse" }, { "mock-tracker", "trackers.grow", "left" }, { "mock-cooldown-row", "cooldowns.grow", "left" },
		{ "mock-cooldown-row", "cooldowns.grow", "right" }, { "mock-party-cooldowns", "partycd.side", "below" }, { "mock-enemy-cooldowns", "enemycd.place", "bars" },
	}
	local base73 = #cases
	for _, case in ipairs(more) do
		cases[#cases + 1] = case
	end
	local changed = 0
	for _, case in ipairs(cases) do
		local id, path, alt, needs = case[1], case[2], case[3], case[4] or {}
		local E = worldOf(id)
		local ns, drawing = E.ns, E.drawing
		local saved = {}
		for _, need in ipairs(needs) do
			saved[#saved + 1] = { need[1], ns.Get(need[1]) }
			ns.Set(need[1], need[2])
		end
		drawing.draw(E.stage)
		local before = printed(E.stage)
		local beforeLoose = printed(E.stage, true)
		local base = ns.Get(path)
		ns.Set(path, alt)
		drawing.draw(E.stage)
		local after = printed(E.stage)
		local differs = after ~= before and ns.Get(path) == alt
		if differs then
			changed = changed + 1
		end
		ns.Set(path, base)
		drawing.draw(E.stage)
		local restored = printed(E.stage, true) == beforeLoose
		for index = #saved, 1, -1 do
			ns.Set(saved[index][1], saved[index][2])
		end
		drawing.draw(E.stage)
		check("sdtrack: " .. path .. " restored to its first value draws the first picture again in " .. id, restored, path)
		check("sdtrack: " .. path .. " written to another value draws another picture in " .. id, differs and ns.Get(path) == base, path)
		check("sdtrack: " .. path .. " has a part in " .. id .. " to bracket", type(drawing.parts[path]) == "table", path)
	end
	check("sdtrack: 73 drawn settings in six drawings, all of them change the drawing", base73 == 73 and changed == #cases, #cases .. " " .. changed)
	-- A stage can ask for one part of mock-tracker, two stages keep their own parts, and drawing asks the game for nothing and works in combat.
	do
		local E = worldOf("mock-tracker")
		local ns, W = E.ns, E.W
		local drawing = ns.SetupDrawings["mock-tracker"]
		local one, two = stageOf(W), stageOf(W)
		one.section, two.section = "defensives", "trackers"
		drawing.draw(one)
		drawing.draw(two)
		local a, b = drawing.partsOf(one), drawing.partsOf(two)
		check("sdtrack: a stage with section defensives shows the defensives and no trackers, one with section trackers the other way round",
			a["trackers.enabled"].shown == false and a["defensives.enabled"].shown == true and b["trackers.enabled"].shown == true and b["defensives.enabled"].shown == false)
		check("sdtrack: two stages have their own frames, and the extent of a part alone is smaller than of both", a["trackers.size"] ~= b["trackers.size"]
			and select(1, drawing.extent(one)) < select(1, drawing.extent(E.stage)) and select(1, drawing.extent(two)) < select(1, drawing.extent(E.stage)))
		local C = up()
		local asked = TOC.df.asked(C)
		C.combat = true
		local stage = stageOf(C)
		local ok, err = true, nil
		for _, id in ipairs(ids) do
			local done, why = xpcall(function() C.ns.SetupDrawings[id].draw(stage) end, debug.traceback)
			ok, err = ok and done, err or (not done and why or nil)
		end
		local afterDraw = TOC.df.asked(C)
		C.ns.Set("trackers.shape", "bar")
		C.ns.Set("cooldowns.perRow", 5)
		for _, id in ipairs(ids) do
			local done, why = xpcall(function() C.ns.SetupDrawings[id].draw(stage) end, debug.traceback)
			ok, err = ok and done, err or (not done and why or nil)
		end
		check("sdtrack: the six drawings are built and drawn in combat with no violation and no error", ok and #C.violations == 0 and #C.errors == 0, tostring(err) .. table.concat(C.violations, " | "))
		check("sdtrack: drawing asks the game for no unit, aura or spell value", afterDraw == asked, afterDraw .. " " .. asked)
		local tracker, party, states = printed(worldOf("mock-tracker").stage), printed(worldOf("mock-party-cooldowns").stage), printed(worldOf("mock-tracker-states").stage)
		check("sdtrack: the samples are fixed text: Lightning Shield with 9:01 left, the party by name, the three states by name",
			has(tracker, "Lightning Shield") and has(tracker, "9:01") and has(party, "Alari") and has(party, "Leaf") and has(states, "Fine") and has(states, "Low") and has(states, "Missing"))
	end
	for _, id in ipairs(ids) do
		local E = worldOf(id)
		check("sdtrack: " .. id .. " took all the writes with no violation and no error", #E.W.violations == 0 and #E.W.errors == 0,
			table.concat(E.W.violations, " | ") .. table.concat(E.W.errors, " | "))
	end

end
-- >>> sdtrack (end)

-- >>> sdmove (start)
local sdmoveWords = {}
-- The setup drawing of the movers steps: mock-screen, with the tooltip, trackers and cooldown icon positions.
do
	local W = newWorld({ uiScale = 1, uiSize = true, cooldowns = true })
	W.login()
	W.flush()
	local ns, env = W.ns, W.env
	local function allClean(w) return #w.violations == 0 and #w.errors == 0 end
	local function problems(w) return table.concat(w.violations, " | "):sub(1, 300) .. " ## " .. table.concat(w.errors, " | "):sub(1, 300) end
	local D = ns.SetupDrawings and ns.SetupDrawings["mock-screen"]
	check("sdmove: mock-screen is registered with build, draw and parts", type(D) == "table" and type(D.build) == "function" and type(D.draw) == "function" and type(D.parts) == "table")
	local stage = env.CreateFrame("Frame", nil, env.UIParent)
	local root, width, height = D.build(stage)
	check("sdmove: build makes one root frame, once, and answers its size", root ~= nil and width > 300 and height > 100 and (D.build(stage)) == root, tostring(width))
	local K = 204 / 1080
	local UW = 1080 * 16 / 9
	local function f3(n) return ("%.3f"):format(n) end
	-- A line for a frame or region: shown, size, points, colour, texture, text, font and alpha.
	local function line(raw)
		local out = { raw.isRegion and "R" or "F", tostring(raw.shown), f3(raw.alpha or 1), f3(raw.width or 0) .. "x" .. f3(raw.height or 0) }
		for _, p in ipairs(raw.points or {}) do
			local rel = W.rawOf[p[2]] or p[2]
			out[#out + 1] = ("%s>%s:%s %s,%s"):format(p[1], tostring(type(rel) == "table" and (rel.order or rel.id) or rel), tostring(p[3]), f3(p[4] or 0), f3(p[5] or 0))
		end
		if raw.color then out[#out + 1] = "c" .. table.concat(raw.color, ",") end
		if raw.vertex then out[#out + 1] = "v" .. table.concat(raw.vertex, ",") end
		if raw.file then out[#out + 1] = "f" .. tostring(raw.file) end
		if raw.text then out[#out + 1] = "t" .. raw.text end
		if raw.font then out[#out + 1] = "z" .. tostring(raw.font[2]) end
		return table.concat(out, " ")
	end
	local function walk(raw, out)
		out[#out + 1] = line(raw)
		for _, region in ipairs(raw.regions or {}) do
			out[#out + 1] = line(region)
		end
		for _, child in ipairs(raw.children or {}) do
			local childRaw = W.rawOf[child]
			if childRaw then walk(childRaw, out) end
		end
		return out
	end
	local function fingerprint()
		return table.concat(walk(W.rawOf[root], {}), "\n")
	end
	local function draw(focus)
		stage.focus = focus
		D.draw(stage)
		return fingerprint()
	end
	local function pointOf(frame, point)
		for _, p in ipairs(W.rawOf[frame].points) do
			if p[1] == (point or p[1]) then return p end
		end
	end
	local function shown(frame) return W.rawOf[frame].shown end
	local base = draw()
	check("sdmove: a second draw changes nothing and answers the size", select(2, D.draw(stage)) == height and fingerprint() == base)
	check("sdmove: no violation and no error after building and drawing", allClean(W), problems(W))

	-- Every drawn setting of the steps: write another value, draw again, and the drawing differs.
	local SETTINGS = {
		{ "movers.snap", { "off" } },
		{ "movers.centreWith", { "alt", "both" } },
		{ "movers.middleLine", { "always", "off" } },
		{ "movers.centreAll", { "none" } },
		{ "tooltip.enabled", { true } },
		{ "tooltip.mode", { "fixed" }, { ["tooltip.enabled"] = true } },
		{ "tooltip.point", { "TOPLEFT", "TOP", "TOPRIGHT", "LEFT", "CENTER", "RIGHT", "BOTTOM", "BOTTOMRIGHT" }, { ["tooltip.enabled"] = true } },
		{ "tooltip.x", { 60 }, { ["tooltip.enabled"] = true } },
		{ "tooltip.y", { 60 }, { ["tooltip.enabled"] = true } },
		{ "trackers.place", { "character" } },
		{ "trackers.side", { "below" } },
		{ "trackers.x", { 100 } },
		{ "trackers.y", { 100 } },
		{ "cooldowns.place", { "resource" } },
		{ "cooldowns.x", { 100 } },
		{ "cooldowns.y", { 100 } },
	}
	local changed, notChanged = 0, {}
	for _, row in ipairs(SETTINGS) do
		local path, values, needs = row[1], row[2], row[3]
		local was = {}
		for gate, value in pairs(needs or {}) do
			was[gate] = ns.Get(gate)
			ns.Set(gate, value)
		end
		local start = draw()
		local default = ns.Get(path)
		local all = true
		for _, value in ipairs(values) do
			ns.Set(path, value)
			local now = draw()
			all = all and now ~= start
			check("sdmove: " .. path .. " set to " .. tostring(value) .. " changes the drawing", now ~= start, path)
		end
		ns.Set(path, default)
		check("sdmove: " .. path .. " put back draws the first drawing again", draw() == start, path)
		for gate, value in pairs(was) do
			ns.Set(gate, value)
		end
		if all then changed = changed + 1 else notChanged[#notChanged + 1] = path end
		check("sdmove: " .. path .. " has a part to mark", D.parts[path] ~= nil, path)
	end
	check("sdmove: every drawn setting of the movers steps changes the drawing (" .. changed .. " of " .. #SETTINGS .. ")", changed == #SETTINGS, table.concat(notChanged, ","))
	check("sdmove: the settings are back at their defaults after the loop", draw() == base)

	-- The drawing reads the settings only through ns.Get, so a draft that answers there is drawn without a write.
	do
		local real = ns.Get
		local draft = { ["movers.snap"] = "off", ["trackers.place"] = "character" }
		ns.Get = function(path)
			if draft[path] ~= nil then return draft[path] end
			return real(path)
		end
		local viewed = draw()
		ns.Get = real
		check("sdmove: ns.Get alone decides the drawing: a draft answered there changes it", viewed ~= base and draw() == base and real("movers.snap") == "middle")
	end

	-- Handles, the dragged bar and the middle line.
	do
		local barW = 0.36 * UW
		local at = pointOf(D.parts["movers.snap"], "BOTTOMLEFT")
		check("sdmove: with Snap on the dragged action bar is on the middle of the screen", near(at[4], (UW - barW) / 2 * K, 1e-6), at[4])
		ns.Set("movers.snap", "off")
		draw()
		at = pointOf(D.parts["movers.snap"], "BOTTOMLEFT")
		check("sdmove: with Snap off it is 7 units to the right of the middle", near(at[4], ((UW - barW) / 2 + 7) * K, 1e-6), at[4])
		local lineRaw = W.rawOf[D.parts["movers.middleLine"]]
		check("sdmove: the middle line is dimmer when nothing is snapped", near(lineRaw.alpha, 0.6, 1e-6), lineRaw.alpha)
		ns.Set("movers.snap", "middle")
		draw()
		check("sdmove: and full while the bar is snapped", near(lineRaw.alpha, 1, 1e-6) and lineRaw.shown == true)
		ns.Set("movers.middleLine", "off")
		draw()
		check("sdmove: Middle line off hides the line", lineRaw.shown == false)
		ns.Set("movers.middleLine", "dragging")
		draw()
		check("sdmove: the drawing's frames are marked Own", ns.Own[D.parts["movers.middleLine"]] == true and ns.Own[root] == true and ns.Own[D.parts["tooltip.point"]] == true)
		check("sdmove: the bar has the centre button and the tick box by default", shown(D.parts["movers.centreWith"]) == true and shown(D.parts["movers.centreAll"]) == true)
		ns.Set("movers.centreWith", "alt")
		ns.Set("movers.centreAll", "none")
		draw()
		check("sdmove: Alt only and no tick boxes remove both squares", shown(D.parts["movers.centreWith"]) == false and shown(D.parts["movers.centreAll"]) == false)
		ns.Set("movers.centreWith", "button")
		ns.Set("movers.centreAll", "button")
		draw()
	end

	-- The line of the Movers panel about centring, as the drawing says it for each pair of settings. The Movers panel is compared with it below.
	do
		for _, how in ipairs({ "button", "alt", "both" }) do
			for _, ticks in ipairs({ "none", "button" }) do
				ns.Set("movers.centreWith", how)
				ns.Set("movers.centreAll", ticks)
				draw()
				local found = {}
				for _, font in ipairs(W.addonFonts) do
					if font.text and font.text:find("centre it%.") and font.shown ~= false then
						found[font.text] = true
					end
				end
				local list = {}
				for text in pairs(found) do list[#list + 1] = text end
				table.sort(list)
				sdmoveWords[how .. "," .. ticks] = list[1]
			end
		end
		ns.Set("movers.centreWith", "button")
		ns.Set("movers.centreAll", "button")
		draw()
		check("sdmove: the drawing has one line about centring for each pair of settings", sdmoveWords["button,none"] and sdmoveWords["alt,none"] and sdmoveWords["both,none"] and sdmoveWords["button,button"] and sdmoveWords["alt,button"] and sdmoveWords["both,button"] and sdmoveWords["alt,none"] ~= sdmoveWords["both,none"])
	end

	-- The tooltip.
	do
		local tip = D.parts["tooltip.point"]
		local p = pointOf(tip)
		check("sdmove: Place the tooltip off draws it at the game's corner: bottom right 9 units in and 85 up", p[1] == "BOTTOMRIGHT" and near(p[4], (UW - 9) * K, 1e-6) and near(p[5], 85 * K, 1e-6), p[1] .. " " .. tostring(p[4]))
		ns.Set("tooltip.enabled", true)
		draw()
		p = pointOf(tip)
		check("sdmove: At the cursor draws the chosen point at the sample cursor with both offsets added", p[1] == "BOTTOMLEFT" and near(p[4], (UW * 0.6 + 16) * K, 1e-6) and near(p[5], (1080 * 0.42 + 16) * K, 1e-6), tostring(p[4]) .. " " .. tostring(p[5]))
		ns.Set("tooltip.point", "TOPRIGHT")
		ns.Set("tooltip.x", -20)
		ns.Set("tooltip.y", 30)
		draw()
		p = pointOf(tip)
		check("sdmove: the point and the offsets move the tooltip", p[1] == "TOPRIGHT" and near(p[4], (UW * 0.6 - 20) * K, 1e-6) and near(p[5], (1080 * 0.42 + 30) * K, 1e-6), tostring(p[4]))
		ns.Set("tooltip.mode", "fixed")
		draw()
		p = pointOf(tip)
		local sx, sy = ns.MoverSpot("FlatUITooltip", "TOPRIGHT")
		check("sdmove: Fixed hangs the chosen point from the same point of the Tooltip handle and ignores the offsets", p[1] == "TOPRIGHT" and near(p[4], sx * K, 1e-6) and near(p[5], sy * K, 1e-6), tostring(p[4]) .. " " .. tostring(sx))
		ns.Set("tooltip.enabled", false)
		ns.Set("tooltip.mode", "cursor")
		ns.Set("tooltip.point", "BOTTOMLEFT")
		ns.Set("tooltip.x", 16)
		ns.Set("tooltip.y", 16)
		check("sdmove: the tooltip settings are back", draw() == base)
	end

	-- The rows of icons.
	do
		local tr, cd = D.parts["trackers.place"], D.parts["cooldowns.place"]
		local function centreOf(frame)
			local p = pointOf(frame, "CENTER")
			return p[4] / K, p[5] / K
		end
		local x, y = centreOf(cd)
		check("sdmove: the Cooldown icons row is low on the middle of the screen by default", near(x, UW / 2, 1e-6) and near(y, 540 - 160, 1e-6), x .. " " .. y)
		ns.Set("cooldowns.x", 50)
		ns.Set("cooldowns.y", -20)
		draw()
		x, y = centreOf(cd)
		check("sdmove: its offsets move it", near(x, UW / 2 + 50, 1e-6) and near(y, 540 - 160 - 20, 1e-6), x .. " " .. y)
		ns.Set("cooldowns.place", "resource")
		draw()
		local bottom = 0.38 * 1080
		x, y = centreOf(cd)
		check("sdmove: under the personal resource display it hangs from the bottom bar less 4 units", near(x, UW / 2 + 50, 1e-6) and near(y, bottom - 20 - 4, 1e-6), x .. " " .. y)
		ns.Set("cooldowns.x", 0)
		ns.Set("cooldowns.y", 0)
		ns.Set("cooldowns.place", "screen")
		draw()
		x, y = centreOf(tr)
		local top = bottom + 12 + 18
		check("sdmove: the Trackers row is above the personal resource display by default, 4 units and half an icon over the top bar", near(x, UW / 2, 1e-6) and near(y, top + 4 + 18, 1e-6), x .. " " .. y)
		ns.Set("trackers.side", "below")
		draw()
		x, y = centreOf(tr)
		check("sdmove: Below puts it under the bottom bar", near(y, bottom - 4 - 18, 1e-6), y)
		ns.Set("cooldowns.place", "resource")
		draw()
		x, y = centreOf(tr)
		check("sdmove: and under the Cooldown icons row when that hangs from the display too", near(y, bottom - 4 - 36 - 4 - 18, 1e-6), y)
		ns.Set("cooldowns.place", "screen")
		ns.Set("trackers.side", "above")
		ns.Set("trackers.place", "character")
		ns.Set("trackers.x", 10)
		ns.Set("trackers.y", 5)
		draw()
		x, y = centreOf(tr)
		check("sdmove: Beside the character is 150 units right of the middle, from the middle of the row, with the offsets", near(x, UW / 2 + 150 + 57 + 10, 1e-6) and near(y, 540 + 5, 1e-6), x .. " " .. y)
		ns.Set("trackers.grow", "right")
		draw()
		x = centreOf(tr)
		check("sdmove: the row direction decides which end of the row is at that place", near(x, UW / 2 + 150 + 10, 1e-6), x)
		ns.Set("trackers.grow", "middle")
		ns.Set("trackers.place", "own")
		draw()
		x, y = centreOf(tr)
		check("sdmove: Own position with no spot saved is beside the character as well", near(x, UW / 2 + 150 + 57 + 10, 1e-6), x)
		ns.Set("trackers.place", "resource")
		ns.Set("trackers.x", 0)
		ns.Set("trackers.y", 0)
		check("sdmove: the rows' settings are back", draw() == base)
		check("sdmove: each row has three icons made by IconNew", #W.rawOf[tr].children >= 3 and #W.rawOf[cd].children >= 3)
	end

	-- The focus of a step picks what is drawn.
	do
		draw("tooltip")
		check("sdmove: the Tooltip step shows the tooltip and neither row nor the middle line", shown(D.parts["tooltip.point"]) and not shown(D.parts["trackers.place"]) and not shown(D.parts["cooldowns.place"]) and not shown(D.parts["movers.middleLine"]))
		draw("trackers")
		check("sdmove: the Trackers step shows the Trackers row alone", shown(D.parts["trackers.place"]) and not shown(D.parts["tooltip.point"]) and not shown(D.parts["cooldowns.place"]) and not shown(D.parts["movers.middleLine"]))
		draw("cooldowns")
		check("sdmove: the Cooldown icons step shows that row alone", shown(D.parts["cooldowns.place"]) and not shown(D.parts["trackers.place"]))
		draw("movers")
		check("sdmove: the Movers step shows the line and no row and no tooltip", shown(D.parts["movers.middleLine"]) and not shown(D.parts["trackers.place"]) and not shown(D.parts["tooltip.point"]))
		stage.focus = nil
		stage.step = "tip-place"
		D.draw(stage)
		check("sdmove: the id of the step picks the focus when none is given", shown(D.parts["tooltip.point"]) and not shown(D.parts["trackers.place"]))
		stage.step = nil
		check("sdmove: with no focus everything is drawn", draw() == base)
	end

	-- The Movers panel: its buttons do not overlap and its texts are above them.
	do
		local function panelRaw()
			for _, child in ipairs(W.rawOf[root].children) do
				local raw = W.rawOf[child]
				if raw and raw.width == 270 then return raw end
			end
		end
		local function span(raw, panel)
			local p = raw.points[1]
			local rel = W.rawOf[p[2]]
			local relLeft = rel == panel and 0 or span(rel, panel)
			local anchor = relLeft + (p[3]:find("RIGHT") and rel.width or p[3]:find("LEFT") and 0 or rel.width / 2)
			local left = anchor + (p[4] or 0) - (p[1]:find("RIGHT") and raw.width or p[1]:find("LEFT") and 0 or raw.width / 2)
			return left, left + raw.width
		end
		local heights = {}
		for _, how in ipairs({ "button", "both" }) do
			for _, ticks in ipairs({ "none", "button" }) do
				ns.Set("movers.centreWith", how)
				ns.Set("movers.centreAll", ticks)
				D.draw(stage)
				local panel = panelRaw()
				local buttons = {}
				for _, child in ipairs(panel.children) do
					local raw = W.rawOf[child]
					if raw.height == 18 and raw.shown ~= false then
						local l, r = span(raw, panel)
						buttons[#buttons + 1] = { l, r }
					end
				end
				table.sort(buttons, function(a, b) return a[1] < b[1] end)
				local clear = #buttons >= 3 and buttons[1][1] >= 0 and buttons[#buttons][2] <= panel.width
				for i = 2, #buttons do
					clear = clear and buttons[i - 1][2] <= buttons[i][1]
				end
				check("sdmove: " .. how .. " and " .. ticks .. ": no two buttons of the Movers panel overlap and all are inside it", clear, tostring(#buttons) .. " " .. (buttons[1] and buttons[1][1] or "") .. " " .. (buttons[#buttons] and buttons[#buttons][2] or ""))
				heights[how .. "," .. ticks] = panel.height
			end
		end
		check("sdmove: the panel is taller for a longer line about centring", heights["both,button"] > heights["button,none"] and heights["button,none"] >= 112, heights["both,button"] .. " " .. heights["button,none"])
		ns.Set("movers.centreWith", "button")
		ns.Set("movers.centreAll", "button")
		check("sdmove: the panel is back", draw() == base)
	end

	-- Trackers below the display go under the Cooldown icons only while Cooldowns is on.
	do
		local tr = D.parts["trackers.place"]
		ns.Set("trackers.side", "below")
		ns.Set("cooldowns.place", "resource")
		ns.Set("cooldowns.enabled", true)
		draw()
		local on = pointOf(tr, "CENTER")[5] / K
		ns.Set("cooldowns.enabled", false)
		draw()
		local off = pointOf(tr, "CENTER")[5] / K
		check("sdmove: with Cooldowns off the Trackers row is under the display and not under the Cooldown icons", near(off, 0.38 * 1080 - 4 - 18, 1e-6) and on < off, on .. " " .. off)
		ns.Set("cooldowns.enabled", true)
		ns.Set("cooldowns.place", "screen")
		ns.Set("trackers.side", "above")
		check("sdmove: the Cooldowns and Trackers settings are back", draw() == base)
	end

	-- A second stage has frames of its own.
	do
		local other = env.CreateFrame("Frame", nil, env.UIParent)
		local otherRoot = D.build(other)
		D.draw(other)
		check("sdmove: a second stage gets its own frames", otherRoot ~= root and #W.rawOf[W.rawOf[otherRoot].children[1]].children > 5)
		local mark = D.parts["tooltip.point"]
		check("sdmove: the parts are those of the stage built last", mark == D.parts["tooltip.x"] and W.rawOf[mark].parent ~= nil)
		check("sdmove: building the first stage again keeps its frames and points the parts at them", (D.build(stage)) == root and D.parts["tooltip.point"] ~= mark)
	end
	check("sdmove: no violation and no error after every drawing", allClean(W), problems(W))
end
-- A screen that is not 16 by 9: the drawing keeps its proportions and puts each spot where the game puts it.
do
	local sizes = 0
	for _, size in ipairs({ { 1728, 1080 }, { 1820, 768 }, { 1024, 1024 } }) do
		local uw, uh = size[1], size[2]
		local W = newWorld({ uiScale = 1, uiSize = true, cooldowns = true })
		W.uiInner.width, W.uiInner.height = uw, uh
		W.login()
		W.flush()
		local ns, env = W.ns, W.env
		local D = ns.SetupDrawings["mock-screen"]
		local stage = env.CreateFrame("Frame", nil, env.UIParent)
		local root, width = D.build(stage)
		local label = "sdmove " .. uw .. "x" .. uh .. ": "
		local k = math.min(204 / uh, 376 / uw)
		local function points(frame, point)
			for _, p in ipairs(W.rawOf[frame].points) do
				if p[1] == (point or p[1]) then return p end
			end
		end
		local function draw() stage.focus = nil D.draw(stage) end
		draw()
		local screen = W.rawOf[W.rawOf[root].children[1]]
		check(label .. "the screen box has the proportions of UIParent and fits the area", near(screen.width / screen.height, uw / uh, 1e-6) and screen.width <= 376 + 1e-6 and screen.height <= 204 + 1e-6, screen.width .. "x" .. screen.height)
		check(label .. "the root frame is as wide as the screen box, the gap and the panel", near(W.rawOf[root].width, screen.width + 12 + 270, 1e-6) and near(width, W.rawOf[root].width, 1e-6) and width <= 658 + 1e-6, W.rawOf[root].width)
		local tip = D.parts["tooltip.point"]
		local free = points(tip)
		check(label .. "Place the tooltip off draws it at the game's corner, 9 units in from the right", free[1] == "BOTTOMRIGHT" and near(free[4], (uw - 9) * k, 1e-6) and near(free[5], 85 * k, 1e-6), tostring(free[4]))
		ns.Set("tooltip.enabled", true)
		ns.Set("tooltip.mode", "fixed")
		ns.Set("tooltip.point", "BOTTOMRIGHT")
		draw()
		local fixed = points(tip)
		check(label .. "Fixed with no saved spot is drawn where the not placed tooltip is", fixed[1] == free[1] and near(fixed[4], free[4], 1e-6) and near(fixed[5], free[5], 1e-6), tostring(fixed[4]) .. " " .. tostring(free[4]))
		local box
		for _, child in ipairs(screen.children) do
			local raw = W.rawOf[child]
			for _, region in ipairs(raw.regions or {}) do
				if region.text == "Tooltip" then box = raw end
			end
		end
		local at = box and box.points[1]
		check(label .. "its handle is shown and inside the screen box", box ~= nil and box.shown == true and at[4] >= -1e-6 and at[4] + box.width <= screen.width + 1e-6, tostring(at and at[4]) .. " " .. tostring(box and box.width))
		ns.Set("cooldowns.x", 0)
		draw()
		local cd = points(D.parts["cooldowns.place"], "CENTER")
		check(label .. "a centred row is on the middle line of the screen box", near(cd[4], uw / 2 * k, 1e-6), tostring(cd[4]))
		check(label .. "no violation and no error", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, " | "):sub(1, 300) .. " ## " .. table.concat(W.errors, " | "):sub(1, 300))
		sizes = sizes + 1
	end
	check("sdmove: three screens that are not 16 by 9 were drawn", sizes == 3)
end
-- The line about centring in the drawing of the movers steps is the line of the Movers panel.
do
	local mw = suiteKit.mw
	for _, how in ipairs({ "button", "alt", "both" }) do
		for _, ticks in ipairs({ "none", "button" }) do
			local W = mw({ saved = { options = { ["movers.centreWith"] = how, ["movers.centreAll"] = ticks } } })
			W.slash("move")
			W.flush()
			local want = sdmoveWords[how .. "," .. ticks]
			local found = want ~= nil and W.textFrame(want) ~= nil
			check("sdmove words: " .. how .. " and " .. ticks .. ": the Movers panel says what the drawing says", want ~= nil and found, tostring(want))
		end
	end
end
-- >>> sdmove (end)
-- >>> useaction (begin)
-- The click on an action button ended in a refused UseAction that named Flat UI. A protected frame is placed in a secure snippet and never with a call of
-- the addon's, Reload is the game's secure /reload from the first press on Forever, and the proc glow is not a child of a button. Every label starts "useaction:".
do
	local K = suiteKit
	local SPOT = { point = "BOTTOM", x = 0, y = 200, kind = "hud" }
	local PROTECTED = { "MainActionBar", "MultiBar5", "PlayerFrame" }
	-- A world whose protected frames count each call of the engine's own placement that is not made inside a secure snippet.
	local function world(saved)
		return K.mwBefore({ saved = K.opt({}, saved), layout = { systems = true } }, function(W)
			W.direct, W.directLog = 0, {}
			for _, name in ipairs(PROTECTED) do
				local raw = W.rawOf[W.env[name]]
				for _, call in ipairs({ "SetPointBase", "ClearAllPointsBase", "SetScaleBase" }) do
					local base = raw[call]
					raw[call] = function(...)
						if not W.inSecure then
							W.direct = W.direct + 1
							W.directLog[#W.directLog + 1] = name .. "." .. call
						end
						return base(...)
					end
				end
			end
		end)
	end
	do
		local W = world({ MainActionBar = SPOT, MultiBar5 = { point = "BOTTOM", x = 0, y = 260, kind = "hud" }, PlayerFrame = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } })
		W.run(1)
		check("useaction: movers: the protected bars and frames are placed where they were saved",
			K.pts(W, W.env.MainActionBar) == "BOTTOM>UIParent:BOTTOM 0,200 @1" and K.pts(W, W.env.MultiBar5) == "BOTTOM>UIParent:BOTTOM 0,260 @1" and K.pts(W, W.env.PlayerFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-200 @1",
			K.pts(W, W.env.MainActionBar) .. " " .. K.pts(W, W.env.PlayerFrame))
		check("useaction: movers: no SetPointBase, ClearAllPointsBase or SetScaleBase of the addon's own reaches a protected frame, and each placement ran in a secure snippet",
			W.direct == 0 and (W.executed or 0) >= 3 and #W.handlers == 1 and K.allClean(W), W.direct .. " " .. table.concat(W.directLog, ","):sub(1, 160) .. " " .. tostring(W.executed))
		check("useaction: movers: the secure frame is the addon's own and hangs from UIParent", W.handlers and W.handlers[1] and W.ns.Own[W.handlers[1]] == true and W.rawOf[W.handlers[1]].parent == W.env.UIParent)
		local runs = W.executed
		W.run(2)
		check("useaction: movers: frames already in place run no snippet in the check twice a second", W.executed == runs, tostring(W.executed) .. " " .. tostring(runs))
		W.slash("move")
		W.keys.ctrl = true
		W.wheel("Player frame", 1)
		W.keys.ctrl = false
		check("useaction: movers: a scale set with Ctrl and the wheel is set in a snippet too", W.rawOf[W.env.PlayerFrame].scale == 1.05 and W.direct == 0 and K.allClean(W), tostring(W.rawOf[W.env.PlayerFrame].scale) .. " " .. W.direct)
		W.rightClick("Player frame")
		check("useaction: movers: and the way back, which sets the points the game gave, makes no call of the addon's on it", W.direct == 0 and K.allClean(W), table.concat(W.directLog, ","):sub(1, 160))
	end
	do
		-- In a fight nothing is placed, and no snippet runs.
		local W = world({ PlayerFrame = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } })
		W.run(1)
		local runs = W.executed
		W.combat = true
		W.fire("PLAYER_REGEN_DISABLED")
		W.rawOf[W.env.PlayerFrame].points = { { "TOPLEFT", W.env.UIParent, "TOPLEFT", 20, -20 } }
		W.run(2)
		check("useaction: movers: in a fight no snippet runs and no call is refused", W.executed == runs and W.direct == 0 and K.allClean(W), tostring(W.executed))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.run(1)
		check("useaction: movers: when the fight ends the frame is placed again, in a snippet", K.pts(W, W.env.PlayerFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-200 @1" and W.executed > runs and W.direct == 0 and K.allClean(W))
		-- A client that will not make the secure frame leaves the frame where the game put it, with no call of the addon's.
		local X = K.mwBefore({ saved = K.opt({}, { PlayerFrame = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } }), layout = { systems = true } }, function(Y)
			local create = Y.env.CreateFrame
			Y.env.CreateFrame = function(kind, name, parent, template)
				if template == "SecureHandlerBaseTemplate" then
					Y.handlerTries = (Y.handlerTries or 0) + 1
					error("no secure handler", 0)
				end
				return create(kind, name, parent, template)
			end
		end)
		X.run(1)
		check("useaction: movers: with no secure frame the protected frame stays where the game put it and nothing errors", K.pts(X, X.env.PlayerFrame) == "TOPLEFT>UIParent:TOPLEFT 20,-20 @1" and K.allClean(X), K.pts(X, X.env.PlayerFrame))
		X.run(2)
		check("useaction: movers: and the secure frame that could not be made is asked for once, not at every check", X.handlerTries == 1, tostring(X.handlerTries))
	end
	do
		-- Flat UI writes four globals, all named for it; a source scan with luac lists them.
		local luac = os.getenv("FLATUI_LUAC")
		if not luac then
			for _, name in ipairs({ "luac5.4", "luac" }) do
				local probe = io.popen(('%s -v 2>&1'):format(name))
				local says = probe and probe:read("*a") or ""
				if probe then probe:close() end
				if says:find("Lua 5", 1, true) then
					luac = name
					break
				end
			end
		end
		luac = luac or "luac5.4"
		local allowed = { FlatUICharDB = true, FlatUIDB = true, SLASH_FLATUI1 = true, FlatUI_OnAddonCompartmentClick = true }
		local extra, scanned = {}, 0
		for _, file in ipairs(FILES) do
			local pipe = io.popen(('%s -l -p "%s/%s" 2>&1'):format(luac, ADDON_DIR, file))
			if pipe then
				for line in pipe:lines() do
					local name = line:match('SETTABUP.-; _ENV "([^"]+)"')
					if name and not allowed[name] then
						extra[#extra + 1] = file .. ":" .. name
					end
					scanned = scanned + 1
				end
				pipe:close()
			end
		end
		check("useaction: globals: the only globals the addon writes are FlatUICharDB, FlatUIDB, SLASH_FLATUI1 and FlatUI_OnAddonCompartmentClick", scanned > 1000 and #extra == 0, table.concat(extra, ","):sub(1, 200) .. " " .. scanned)
		-- The Settings registry is only registered into, through Settings.Register..., and no field of it is written.
		local writes = {}
		for _, file in ipairs(FILES) do
			local handle = io.open(ADDON_DIR .. "/" .. file, "rb")
			local text = handle and handle:read("*a") or ""
			if handle then handle:close() end
			for line in text:gmatch("[^\n]+") do
				if not line:match("^%s*%-%-") and (line:match("%f[%w_]Settings%.[%w_]+%s*=[^=]") or line:match("%f[%w_]Settings%[[^%]]+%]%s*=[^=]") or line:find("RegisterCVarSetting", 1, true) or line:find("RegisterAddOnSetting", 1, true)) then
					writes[#writes + 1] = file .. ": " .. line:sub(1, 60)
				end
			end
		end
		check("useaction: settings registry: no field of Settings is written, and no CVar or add-on setting object is built in the addon's own call", #writes == 0, table.concat(writes, " | "):sub(1, 200))
	end
	-- Leave the game's action bars alone (general.handsOff). Every label starts "useaction:".
	-- The bars the click on an action button reads, and what the addon did to them: every call on one from the addon's own code (a placement in a secure
	-- snippet included) and every alpha it wrote. The game's own passes run as the game's code (W.blizzard) and are not counted.
	do
		local BARS = { "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBarRight", "MultiBarLeft", "MultiBar5", "MultiBar6", "MultiBar7", "StanceBar",
			"PetActionBar", "PossessActionBar", "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer", "MicroMenuContainer", "BagsBar",
			"MainMenuBarVehicleLeaveButton" }
		local XP = "MainStatusTrackingBarContainer"
		local function spots(extra)
			local list = { PlayerFrame = { point = "TOPLEFT", x = 300, y = -200, kind = "hud" } }
			for index, name in ipairs(BARS) do
				list[name] = { point = "BOTTOM", x = 0, y = 100 + 40 * index, kind = "hud" }
			end
			for name, spot in pairs(extra or {}) do
				list[name] = spot
			end
			return list
		end
		local function hworld(options, spotList, more)
			more = more or {}
			return K.mwBefore({ handsOff = more.handsOff ~= false, saved = K.opt(options or {}, spotList), layout = more.layout or { systems = true, bars = true } }, function(W)
				W.touched, W.touchLog = 0, {}
				local wrapped = {}
				local function watch()
					for _, name in ipairs(BARS) do
						local raw = W.env[name] ~= nil and not wrapped[name] and W.rawOf[W.env[name]] or nil
						if raw then
							wrapped[name] = true
							for _, call in ipairs({ "SetPointBase", "ClearAllPointsBase", "SetScaleBase", "SetPoint", "ClearAllPoints", "SetScale", "SetAlpha", "SetParent", "SetSize", "SetWidth",
								"SetHeight", "Show", "Hide", "SetAttribute", "HookScript" }) do
								local base = raw[call]
								if type(base) == "function" then
									raw[call] = function(...)
										if W.inBlizzard == 0 then
											W.touched = W.touched + 1
											W.touchLog[#W.touchLog + 1] = name .. "." .. call
										end
										return base(...)
									end
								end
							end
						end
					end
				end
				watch()
				if more.prep then
					more.prep(W)
				end
				watch()
			end)
		end
		local function pass(W)
			W.blizzard(function()
				W.gameStack()
			end)
			W.registry:TriggerEvent("EditModeManager.UpdateBottomActionBarPositions")
		end
		local function log(W)
			return table.concat(W.touchLog, ","):sub(1, 200) .. " " .. K.problems(W)
		end

		-- Moved bars after a login, a pass of the game over the bottom bars and a fight.
		do
			local W = hworld({}, spots())
			W.run(1)
			local control = hworld({}, nil)
			check("useaction: handsoff: a bar with a saved spot is not placed, and the frames that are not bars still are",
				K.pts(W, W.env.MainActionBar) == K.pts(control, control.env.MainActionBar) and K.pts(W, W.env.MultiBar5) == K.pts(control, control.env.MultiBar5)
				and K.pts(W, W.env[XP]) == K.pts(control, control.env[XP]) and K.pts(W, W.env.StanceBar) == K.pts(control, control.env.StanceBar)
				and K.pts(W, W.env.PlayerFrame) == "TOPLEFT>UIParent:TOPLEFT 300,-200 @1", K.pts(W, W.env.MainActionBar) .. " " .. K.pts(W, W.env.PlayerFrame))
			check("useaction: handsoff: after login the addon made no call, in a snippet or outside one, on any action bar or status bar", W.touched == 0 and K.allClean(W), W.touched .. " " .. log(W))
			check("useaction: handsoff: the game's bottom bar pass is not watched", W.registrants("EditModeManager.UpdateBottomActionBarPositions") == 0
				and control.registrants("EditModeManager.UpdateBottomActionBarPositions") == 0)
			pass(W)
			pass(control)
			W.run(2)
			check("useaction: handsoff: after the game's bottom bar pass nothing places the bars again, and they stand where the game put them",
				W.touched == 0 and K.pts(W, W.env.MultiBarBottomLeft) == K.pts(control, control.env.MultiBarBottomLeft) and K.pts(W, W.env[XP]) == K.pts(control, control.env[XP]), W.touched .. " " .. log(W))
			W.combat = true
			W.fire("PLAYER_REGEN_DISABLED")
			W.run(1)
			W.combat = false
			W.fire("PLAYER_REGEN_ENABLED")
			W.run(2)
			pass(W)
			W.run(1)
			check("useaction: handsoff: after a fight and another pass still no call on a bar", W.touched == 0 and K.allClean(W), W.touched .. " " .. log(W))
			check("useaction: handsoff: the status counts the one frame moved, lists the saved bar spots as not used and names no click path write",
				W.line("Movers") == "Movers: on, 1 moved" and W.status():find("Saved spots not used while Leave the game's action bars alone is on: ", 1, true) ~= nil
				and W.status():find("Click path:", 1, true) == nil, W.line("Movers") or "")
			W.slash("move")
			W.flush()
			check("useaction: handsoff: the handles show Player frame and none of the bars", W.textFrame("Player frame") ~= nil and W.textFrame("Main action bar") == nil
				and W.textFrame("Action bar 3") == nil and W.textFrame("Experience bar") == nil)
			check("useaction: handsoff: the flag reads true by default and the movers know the bars", W.ns.Get("general.handsOff") == true and W.ns.MoverHandsOff("MainActionBar") == true
				and W.ns.MoverHandsOff("PlayerFrame") == false)
		end

		-- The bar block and the bar blocks with the bars picked, a fade and a background.
		do
			local options = { ["barblock.enabled"] = true, ["barblock.fade"] = true, ["barblock.background"] = true, ["barblock.uniform"] = true, ["blocks.enabled"] = true,
				["blocks.classBar"] = "bar4", ["blocks.petPlace"] = "aboveRight", ["fade.enabled"] = true, ["fade.main"] = true, ["fade.bar2"] = true }
			local W = hworld(options, spots(), { layout = { systems = true, bars = true, layouts = { active = 4 } } })
			W.run(2)
			pass(W)
			W.run(2)
			local control = hworld({}, nil, { layout = { systems = true, bars = true, layouts = { active = 4 } } })
			pass(control)
			check("useaction: handsoff: with the bar block, bar blocks, moved bars and a fade on, no bar is touched and none is held", W.touched == 0 and W.ns.MoverHeld("MainActionBar").held == false
				and W.ns.MoverHeld("MultiBarBottomLeft").held == false and K.pts(W, W.env.MainActionBar) == K.pts(control, control.env.MainActionBar), W.touched .. " " .. log(W))
			check("useaction: handsoff: the layout is not saved and the button writer has nothing pending", W.em.saves == 0 and W.ns.LayoutSpots.WriterState("buttons") == nil and K.allClean(W),
				tostring(W.em.saves) .. " " .. tostring(W.ns.LayoutSpots.WriterState("buttons")))
			check("useaction: handsoff: the status says the block and the blocks are not applied",
				W.status():find("Action bar block: not applied while Leave the game's action bars alone is on.", 1, true) ~= nil
				and W.status():find("Bar blocks: not applied while Leave the game's action bars alone is on.", 1, true) ~= nil, W.status():sub(1, 300))
		end

		-- The same world with the setting off still moves the bars, and the status names them.
		do
			local W = hworld({}, spots({ MainActionBar = { point = "BOTTOM", x = 0, y = 200, kind = "hud" } }), { handsOff = false })
			W.run(1)
			check("useaction: handsoff off: the bar is placed as before", K.pts(W, W.env.MainActionBar) == "BOTTOM>UIParent:BOTTOM 0,200 @1" and W.touched > 0 and W.ns.MoverHandsOff("MainActionBar") == false,
				K.pts(W, W.env.MainActionBar))
			check("useaction: handsoff off: /flatui status names the bars the addon placed", W.status():find("Click path: Flat UI placed ", 1, true) ~= nil
				and W.status():find("Main action bar", 1, true) ~= nil, W.status():sub(-400))
		end

		-- Fading: the micro menu still fades, the bars do not, and a bar faded before the setting went on is given its alpha back.
		do
			local function fworld(handsOff)
				return hworld({ ["fade.enabled"] = true, ["fade.main"] = true, ["fade.pet"] = true, ["fade.micro"] = true }, nil, { handsOff = handsOff, prep = function(W)
					W.bframe("MicroMenuContainer", { point = { "BOTTOMLEFT", W.env.UIParent, "BOTTOMLEFT", 60, 120 }, width = 90, height = 40 })
					for _, name in ipairs({ "MainActionBar", "PetActionBar", "MicroMenuContainer" }) do
						local raw = W.rawOf[W.env[name]]
						raw.alpha = 1
						raw.GetAlpha = function() return raw.alpha end
					end
					W.cursor = { 1000, 900 }
				end })
			end
			local function alpha(W, name)
				return W.rawOf[W.env[name]].alpha
			end
			local W = fworld(true)
			W.run(3)
			check("useaction: fade: with the bars left alone the micro menu, the main bar and the pet bar keep full opacity", alpha(W, "MicroMenuContainer") == 1
				and alpha(W, "MainActionBar") == 1 and alpha(W, "PetActionBar") == 1, alpha(W, "MicroMenuContainer") .. " " .. alpha(W, "MainActionBar"))
			check("useaction: fade: and no alpha was written on a bar or on the micro menu", W.touched == 0 and K.allClean(W), W.touched .. " " .. log(W))
			local O = fworld(false)
			O.run(3)
			check("useaction: fade: with the setting off the bars and the micro menu fade as before", alpha(O, "MainActionBar") < 1 and alpha(O, "PetActionBar") < 1
				and alpha(O, "MicroMenuContainer") < 1, alpha(O, "MainActionBar") .. "")
			O.ns.HandsOff = function() return true end
			O.run(1)
			check("useaction: fade: a bar faded before the setting went on gets its alpha back and is left alone after", alpha(O, "MainActionBar") == 1 and alpha(O, "PetActionBar") == 1
				and alpha(O, "MicroMenuContainer") == 1, alpha(O, "MainActionBar") .. "")
			O.run(3)
			check("useaction: fade: and stays at full opacity", alpha(O, "MainActionBar") == 1)
		end

		-- The experience bar: no hook on its size or on the manager's events, and no write on its dividers.
		do
			local function hooks(W, name)
				local raw = W.rawOf[W.env[name]]
				local n = 0
				for _, list in pairs(raw.hookScripts or {}) do
					n = n + #list
				end
				return n
			end
			local function world(handsOff)
				return hworld({}, nil, { handsOff = handsOff, prep = function(W)
					W.bframe("StatusTrackingBarManager", { point = { "BOTTOMLEFT", W.env.UIParent, "BOTTOMLEFT", 10, 10 }, width = 10, height = 10 })
					local divider = W.bframe("XpDivider", { point = { "BOTTOMLEFT", W.env.UIParent, "BOTTOMLEFT", 20, 10 }, width = 2, height = 10 })
					W.divider = W.rawOf[divider]
					W.divider.alpha = 1
					W.rawOf[W.env[XP]].HorizontalDividersPool = { EnumerateActive = function()
						local done = false
						return function()
							if not done then
								done = true
								return divider
							end
						end
					end }
				end })
			end
			local W, O = world(true), world(false)
			for _, X in ipairs({ W, O }) do
				X.fire("PLAYER_ENTERING_WORLD", false, true)
				X.fire("UPDATE_EXHAUSTION")
				X.flush()
				X.run(4)
			end
			check("useaction: hud: with the bars left alone no script of the experience bar or of the status bar manager is hooked, and with the setting off both are",
				hooks(W, XP) == 0 and hooks(W, "StatusTrackingBarManager") == 0 and hooks(O, XP) > 0 and hooks(O, "StatusTrackingBarManager") > 0,
				hooks(W, XP) .. " " .. hooks(W, "StatusTrackingBarManager") .. " " .. hooks(O, XP) .. " " .. hooks(O, "StatusTrackingBarManager"))
			check("useaction: hud: the dividers of the experience bar keep the game's alpha, through a login and the events that start a pass, and with the setting off they are hidden",
				W.divider.alpha == 1 and O.divider.alpha == 0, W.divider.alpha .. " " .. O.divider.alpha)
			check("useaction: hud: the status names no restyle of the experience bar with the bars left alone, and names it with the setting off", W.status():find("Click path: Flat UI restyled", 1, true) == nil
				and O.status():find("Click path: Flat UI restyled the experience bar.", 1, true) ~= nil and W.touched == 0, W.status():sub(-200))
		end

		-- The game's settings registry: one canvas category, no setting of Flat UI's in it.
		do
			local W = K.mw({ handsOff = true })
			check("useaction: options: with the bars left alone one canvas category is registered and nothing else", W.registered ~= nil and W.canvas ~= nil and W.canvas[W.registered] ~= nil
				and #W.categories == 1 and #W.controls == 0 and next(W.settings) == nil and #W.layouts[W.registered] == 0, #W.categories .. " " .. #W.controls)
			check("useaction: options: and the game's Options page opens on it", W.ns.OpenOptions() == true and W.opened == W.registered:GetID())
			local button = W.textFrame("Open Flat UI")
			local panelOpened = 0
			W.ns.OpenPanel = function() panelOpened = panelOpened + 1 end
			local raw = button and (W.rawOf[button] or button)
			local click = raw and raw.scripts and raw.scripts.OnMouseUp
			if type(click) == "function" then
				click(button, "LeftButton")
			end
			check("useaction: options: it has a button that opens Flat UI's own window", button ~= nil and type(click) == "function" and panelOpened == 1,
				tostring(button) .. " " .. tostring(click) .. " " .. panelOpened .. " " .. K.problems(W))
			check("useaction: options: no error, no violation, and the status names no setting in the registry", #W.errors == 0 and #W.violations == 0 and W.status():find("in the game's settings registry", 1, true) == nil,
				K.problems(W))
			local O = K.mw({ saved = K.opt({ ["general.handsOff"] = false }) })
			check("useaction: options: with the setting off the pages are registered as before and the status names how many settings", #O.controls > 100 and O.status():find("Flat UI settings are in the game's settings registry.", 1, true) ~= nil,
				tostring(#O.controls))
		end

		-- Hooks and registrations on the game's action button code wait for Restyle action bars.
		do
			local function world(handsOff, enabled)
				local W = newWorld({ handsOff = handsOff, saved = { options = { ["actionbars.enabled"] = enabled } } })
				W.env.ActionButton_UpdateRangeIndicator = function() end
				W.env.ActionButton_ApplyCooldown = function() end
				W.env.ActionButtonSpellAlertManager = { ShowAlert = function() end, HideAlert = function() end }
				W.followed = {}
				local base = W.env.hooksecurefunc
				W.env.hooksecurefunc = function(object, name, hook)
					W.followed[#W.followed + 1] = type(object) == "string" and object or tostring(name)
					return base(object, name, hook)
				end
				W.login()
				W.flush()
				-- A tracker proc that starts a glow asks for the hook on the alert code as well.
				pcall(W.ns.ProcGlowStart, { id = "t1" })
				W.flush()
				return W
			end
			local W, O, R = world(true, false), world(false, false), world(true, true)
			check("useaction: hooks: with Restyle action bars off and the bars left alone nothing is hooked on the game's range, cooldown or alert code", #W.followed == 0 and #O.followed >= 4,
				table.concat(W.followed, ",") .. " | " .. table.concat(O.followed, ","))
			check("useaction: hooks: with Restyle action bars on they are hooked as before", #R.followed == #O.followed and #R.errors == 0 and #R.violations == 0, #R.followed .. " " .. #O.followed)
		end

		-- The rows that do nothing say so.
		do
			local W = newWorld({ handsOff = true })
			local want = "Not applied while Leave the game's action bars alone is on."
			local missing = {}
			for _, path in ipairs({ "barblock.enabled", "blocks.enabled", "fade.main", "fade.bar2", "fade.bar8", "fade.stance", "fade.pet", "fade.micro", "fade.bags", "hud.xpFrame", "hud.xpFill", "hud.xpDividers", "hud.xpText",
				"hud.xpTextSize", "hud.xpTexture" }) do
				local row
				for _, page in ipairs(W.ns.PAGES) do
					for _, item in ipairs(page) do
						if item.path == path then
							row = item
						end
					end
				end
				-- The rows that apply to Flat UI's own experience bar as well say it for the game's bar only.
				local short = path == "hud.xpFrame" or path == "hud.xpText" or path == "hud.xpTextSize" or path == "hud.xpTexture"
				local line = short and want:sub(2) or want
				if not (row and type(row.tip) == "string" and row.tip:sub(-#line) == line) then
					missing[#missing + 1] = path
				end
			end
			check("useaction: rows: each row that does nothing to the game's bars says so in its tip", #missing == 0, table.concat(missing, ","))
		end
	end
end
-- >>> useaction (end)

-- >>> procfight (begin)
-- Proc art on the game's own icon (procfight:). A warlock with a Shadow Trance proc tracker, with the game's own icons: the aura container closes
-- its button to addon code while the game hides auras, and a piece of art made on the button is shown by the game exactly while the buff is up.
do
	local F = { ICON = 136183, FILE = 449492 }
	function F.entry(more)
		local e = { id = "prc001", kind = "proc", name = "Shadow Trance", names = { "Shadow Trance" }, spells = { 17941 }, lights = { 686, 25307 }, trigger = "aura",
			time = 10, size = 48, show = "always" }
		for k, v in pairs(more or {}) do
			e[k] = v
		end
		return e
	end
	function F.world(o)
		o = o or {}
		local opts = { trackers = true, char = { trackers = o.list or { F.entry() } } }
		if o.options then
			opts.saved = { options = o.options }
		end
		local W = newWorld(opts)
		W.addLine({ name = "General" })
		W.addSpell(686, { name = "Shadow Bolt", icon = 135808, base = 0, lowRank = true })
		W.addSpell(25307, { name = "Shadow Bolt", icon = 135808, base = 0 })
		W.addSpell(17941, { name = "Shadow Trance", icon = F.ICON, base = 0, known = false })
		W.au.unit.player = { class = "WARLOCK", guid = "Player-1" }
		W.env.Enum.ScreenLocationType = { Center = 0, Left = 1, Right = 2, Top = 3, Bottom = 4, TopLeft = 5, TopRight = 6, LeftOutside = 7, RightOutside = 8,
			LeftRight = 9, TopBottom = 10, LeftRightOutside = 11 }
		-- A frame of the simulated client makes no animation group (only a texture does); the pieces of the holder need one, so a frame gets a plain one.
		local make = W.env.CreateFrame
		W.env.CreateFrame = function(...)
			local frame = make(...)
			if type(frame) == "table" and frame.CreateAnimationGroup == nil then
				frame.CreateAnimationGroup = function()
					local group = {}
					for _, name in ipairs({ "SetLooping", "SetScript", "Play", "Stop", "Pause" }) do
						group[name] = function() end
					end
					group.CreateAnimation = function()
						local step = {}
						for _, name in ipairs({ "SetFromAlpha", "SetToAlpha", "SetDuration", "SetScaleFrom", "SetScaleTo", "SetSmoothing", "SetOrder" }) do
							step[name] = function() end
						end
						return step
					end
					return group
				end
			end
			return frame
		end
		if o.set then
			o.set(W)
		end
		return W
	end
	function F.up(o)
		local W = F.world(o)
		W.login()
		W.flush()
		W.advance(5)
		W.advance(0)
		return W
	end
	function F.step(W, seconds)
		W.advance(seconds)
		W.advance(0)
	end
	function F.list(W)
		return W.env.FlatUICharDB.trackers
	end
	-- The container, the button and the pieces of art made on the button, of a tracker.
	function F.of(W, entry)
		local p = { frame = W.ns.TrackerFrame(entry), pieces = {} }
		for _, child in ipairs(p.frame and p.frame.children or {}) do
			if child.ac then
				p.container = child
			end
		end
		local state = p.container and p.container.ac
		p.slot = state and (state.slots.tracker2 or state.slots.tracker)
		p.button = p.slot and p.slot.braw
		for _, r in ipairs(p.button and p.button.regions or {}) do
			if r.file == F.FILE and r.kind == "Texture" then
				p.pieces[#p.pieces + 1] = r
			end
		end
		return p
	end
	function F.ok(W)
		return #W.violations == 0 and #W.errors == 0
	end
	function F.late(W)
		local n = 0
		for _, e in ipairs(W.ac.log) do
			if (e:find("^button:late:") or e:find("^child:late:")) and not e:find(":IsVisible:", 1, true) then
				n = n + 1
			end
		end
		return n
	end
	function F.count(W, prefix)
		local n = 0
		for _, e in ipairs(W.ac.log) do
			if e:sub(1, #prefix) == prefix then
				n = n + 1
			end
		end
		return n
	end
	function F.lines(W, entry)
		return table.concat(W.ns.TrackerSlots.Lines(entry) or {}, "\n")
	end
	-- The textures of the art on the holder (not on the button).
	function F.own(W, entry)
		local mine, found = {}, {}
		for _, r in ipairs(F.of(W, entry).pieces) do
			mine[r] = true
		end
		for _, r in ipairs(W.addonTextures) do
			if r.file == F.FILE and not mine[r] and r.kind == "Texture" then
				found[#found + 1] = r
			end
		end
		return found
	end
	local NOTE_ART = "Trackers: the game refused art on its own icon, so in fights proc art follows only the proc's other triggers."
	local function at(r)
		local pt = r.points[1]
		return pt and (pt[1] .. "," .. pt[3] .. "," .. g(pt[4]) .. "," .. g(pt[5])) or "none"
	end
	local function side(p, point)
		for _, r in ipairs(p.pieces) do
			if r.points[1] and r.points[1][1] == point then
				return r
			end
		end
	end
	local function artLine(W, e)
		return F.lines(W, e):match("Art in fights[^%c]*")
	end
	local function gameShown(W, e)
		local out = {}
		for _, r in ipairs(F.own(W, e)) do
			out[#out + 1] = r.owner.shown
		end
		return out
	end
	local function fightWith(W)
		W.beginFight()
		W.giveBuff(17941, { applications = 1, remaining = 10 })
		W.auraChanged()
		F.step(W, 0.5)
	end
	local CLOSED_AT_START = TOC.closed or 0

	-- The pieces are made inside initializeFrame, one texture each of the two sides, on the button, with the settings in force.
	do
		local W = F.up()
		local e = F.list(W)[1]
		local p = F.of(W, e)
		local left, right = side(p, "RIGHT"), side(p, "LEFT")
		check("procfight: the registry has a function for the kind proc, ProcArtParts", type(W.ns.TrackerSlotParts) == "table" and type(W.ns.TrackerSlotParts.proc) == "function"
			and type(W.ns.ProcArtParts) == "function")
		check("procfight: two textures are made on the button inside initializeFrame, and no call reaches the button afterwards", #p.pieces == 2 and F.count(W, "button:init:CreateTexture") == 2
			and F.count(W, "button:late:") == 0 and F.late(W) == 0 and (TOC.closed or 0) == CLOSED_AT_START, tostring(#p.pieces) .. " " .. F.late(W))
		check("procfight: the left piece is the game's 102.4 by 204.8, hung on the middle of the screen 102.4 to the left", left and at(left) == "RIGHT,CENTER,-102.4,0" and near(left.width, 102.4) and near(left.height, 204.8), left and at(left))
		check("procfight: the right piece is on the other side and mirrored", right and at(right) == "LEFT,CENTER,102.4,0" and right.texCoord and right.texCoord[1] == 1 and right.texCoord[2] == 0)
		check("procfight: the pieces have the art file, Art opacity and the colour of the proc", left and left.file == F.FILE and near(left.alpha, 0.65) and near(left.vertex[1], 1) and near(left.vertex[2], 0.82, 0.01) and near(left.vertex[3], 0))
		check("procfight: they are anchored to a frame of the screen", left and left.points[1][2] ~= nil and left.points[1][2] ~= p.button)
		check("procfight: the game's icon is ready and the line says art in fights is ready", artLine(W, e) == "Art in fights: ready." and W.ns.TrackerSlots.InUse(e) == false, tostring(artLine(W, e)))
		check("procfight: no violation, no error and no note", F.ok(W) and not has(W.status(), NOTE_ART), table.concat(W.violations, " | "))
	end

	-- A fight: the game's icon is on show, the pieces on the holder are hidden, and they come back when the icon goes.
	do
		local W = F.up()
		local e = F.list(W)[1]
		W.ns.ProcArtShow(e, { file = F.FILE, location = "LeftRight" })
		F.step(W, 0.1)
		local before = gameShown(W, e)
		check("procfight: out of a fight the pieces of the holder are shown and the game's icon is not", #before == 2 and before[1] == true and before[2] == true and F.of(W, e).container.alpha == 0, tostring(#before))
		fightWith(W)
		local mid = gameShown(W, e)
		check("procfight: in a fight with the game's icon on show, the pieces of the holder are hidden, so the art is not drawn twice", #mid == 2 and mid[1] == false and mid[2] == false
			and F.of(W, e).container.alpha == 1 and W.ns.TrackerSlots.InUse(e) == true, tostring(mid[1]))
		check("procfight: the pieces on the button are still the same two, and nothing reached the closed button", #F.of(W, e).pieces == 2 and F.late(W) == 0 and (TOC.closed or 0) == CLOSED_AT_START and F.ok(W), F.late(W))
		local pool0 = W.ns.ProcArtCounts()
		W.ns.ProcArtHide(e)
		local pooled, fading = W.ns.ProcArtCounts()
		check("procfight: a proc that ends in a fight with the game's icon in use gives its pieces back at once, none left fading", pooled == pool0 + 2 and fading == 0, tostring(pooled) .. " " .. tostring(fading))
		W.ns.ProcArtShow(e, { file = F.FILE, location = "LeftRight" })
		F.step(W, 0.1)
		local pooled2 = W.ns.ProcArtCounts()
		check("procfight: the next proc takes the pieces from the pool, no new ones", pooled2 == pool0, tostring(pooled2))
		W.endFight()
		F.step(W, 0.5)
		local after = gameShown(W, e)
		check("procfight: when the fight ends the pieces of the holder show again", #after == 2 and after[1] == true and after[2] == true and F.of(W, e).container.alpha == 0, tostring(after[1]))
	end

	-- A change while the game hides buffs waits, and goes out when buffs are open.
	do
		local W = F.up()
		local e = F.list(W)[1]
		fightWith(W)
		W.ns.Set("trackers.artSize", 150)
		W.ns.Set("trackers.artAlpha", 40)
		W.ns.Set("trackers.artY", 30)
		W.ns.ProcArtChanged()
		local p = F.of(W, e)
		local left = side(p, "RIGHT")
		check("procfight: a size, opacity and height change in a fight reaches no piece and no call reaches the button", near(left.width, 102.4) and near(left.alpha, 0.65) and at(left) == "RIGHT,CENTER,-102.4,0"
			and F.late(W) == 0 and (TOC.closed or 0) == CLOSED_AT_START and F.ok(W), at(left))
		check("procfight: the line says a change waits for the end of the fight", artLine(W, e) == "Art in fights: a change waits for the end of the fight.", tostring(artLine(W, e)))
		W.endFight()
		F.step(W, 0.5)
		check("procfight: at the end of the fight the pieces take the size, opacity and height", near(left.width, 153.6) and near(left.height, 307.2) and near(left.alpha, 0.4) and at(left) == "RIGHT,CENTER,-102.4,30", at(left))
		check("procfight: and the line says ready again", artLine(W, e) == "Art in fights: ready.", tostring(artLine(W, e)))
		-- With buffs open a change goes out at once.
		W.ns.Set("trackers.artSize", 50)
		W.ns.ProcArtChanged()
		check("procfight: with buffs open a size change reaches the pieces at once", near(left.width, 51.2) and F.ok(W), g(left.width))
		-- The colour of the proc.
		F.list(W)[1].colour = "ff0000ff"
		W.ns.ProcArtChanged()
		check("procfight: a new colour of the proc reaches the pieces", near(left.vertex[1], 0) and near(left.vertex[3], 1), left.vertex[1] .. " " .. left.vertex[3])
	end

	-- The row off: the pieces are clear, and clear again on when the row is turned on.
	do
		local W = F.up({ options = { ["trackers.art"] = false } })
		local e = F.list(W)[1]
		local left = side(F.of(W, e), "RIGHT")
		check("procfight: Art beside the character off makes the pieces clear", left and near(left.alpha, 0), left and left.alpha)
		check("procfight: the line says art in fights is off with the row off", artLine(W, e) == "Art in fights: off, Art beside the character is off.", tostring(artLine(W, e)))
		W.ns.Set("trackers.art", true)
		W.ns.ProcArtChanged()
		check("procfight: and on takes the opacity", near(left.alpha, 0.65), left.alpha)
	end

	-- Two procs are at places of their own.
	do
		local W = F.up({ list = { F.entry(), F.entry({ id = "prc002" }) } })
		local first, second = side(F.of(W, F.list(W)[1]), "RIGHT"), side(F.of(W, F.list(W)[2]), "RIGHT")
		check("procfight: two procs with the same location are not on one place", first and second and at(first) == "RIGHT,CENTER,-102.4,0" and at(second) == "RIGHT,CENTER,-204.8,0", (first and at(first) or "?") .. " " .. (second and at(second) or "?"))
	end

	-- The game refuses a texture: the icon is ready, art in fights is refused, one note, and the own-frame art stays.
	do
		local W = F.up({ set = function(X) X.au.fault["button.CreateTexture"] = "error" end })
		local e = F.list(W)[1]
		local p = F.of(W, e)
		W.ns.ProcArtShow(e, { file = F.FILE, location = "LeftRight" })
		F.step(W, 0.1)
		fightWith(W)
		check("procfight: a refused texture leaves no piece on the button, and the game's icon is ready all the same", #p.pieces == 0 and W.ns.TrackerSlots.Live(e) == true, tostring(#p.pieces))
		check("procfight: the line says art in fights is refused by the game", artLine(W, e) == "Art in fights: refused by the game.", tostring(artLine(W, e)))
		local _, notes = W.status():gsub(NOTE_ART:gsub("%p", "%%%0"), "")
		check("procfight: one note says so", notes == 1, W.status():sub(1, 300))
		local own = gameShown(W, e)
		check("procfight: the pieces of the holder stay shown with the game's icon in use", #own == 2 and own[1] == true and own[2] == true and W.ns.TrackerSlots.InUse(e) == false, tostring(own[1]))
	end

	-- The game's icon waits: out of a fight the build is tried again and the line follows.
	do
		local W = F.up({ set = function(X) X.au.hidden = true X.au.fault["container.AddAuraSlot"] = "error" end })
		local e = F.list(W)[1]
		check("procfight: a slot the game refused while hiding buffs says art waits for the game's own icon", artLine(W, e) == "Art in fights: waits for the game's own icon.", tostring(artLine(W, e)))
		W.au.fault["container.AddAuraSlot"] = nil
		W.showAuras()
		W.ns.TrackerSlots.Flush()
		local p = F.of(W, e)
		check("procfight: when buffs are open the slot is built again with the pieces and the line is ready", #p.pieces == 2 and artLine(W, e) == "Art in fights: ready.", tostring(artLine(W, e)))
	end

	-- Logged in while the game hides buffs (a reload in a fight): the pieces are made inside initializeFrame all the same.
	do
		local W = F.up({ set = function(X) X.au.hidden = true end })
		local e = F.list(W)[1]
		local p = F.of(W, e)
		check("procfight: a login while the game hides buffs makes the pieces inside initializeFrame, and nothing late", #p.pieces == 2 and F.late(W) == 0 and artLine(W, e) == "Art in fights: ready." and F.ok(W), tostring(#p.pieces))
	end
end
-- >>> procfight (end)
-- >>> bbimport (begin)
-- The Flat UI layout as Edit Mode import text (LayoutText.lua): LayoutText.lua is loaded alone in a small environment with a recording CreateFrame, and
-- a few checks run in the movers world for the row, the refusals and the saves.
do
	local TEXT = "FlatUI-import-text-0123"
	local ENTRY = { layoutName = "Flat UI", layoutType = 1, systems = { { system = 1, anchorInfo = { point = "BOTTOM", x = 0, y = 200 } } } }
	local WANT = "The game would not make import text."
	local function outText(W)
		return table.concat(W.out, " | ")
	end
	local function same(a, b)
		if type(a) ~= "table" or type(b) ~= "table" then
			return a == b
		end
		for k, v in pairs(a) do
			if not same(v, b[k]) then
				return false
			end
		end
		for k in pairs(b) do
			if a[k] == nil then
				return false
			end
		end
		return true
	end
	local function lone(opts)
		opts = opts or {}
		local L = { out = {}, made = {}, fonts = {}, timers = {}, converted = {}, saves = 0, actives = 0, combat = opts.combat == true, editOpen = opts.editOpen == true, asked = 0 }
		local env = setmetatable({}, { __index = _G })
		local function object(kind)
			local o = { kind = kind, calls = {}, shown = true, scripts = {}, points = {} }
			return setmetatable(o, { __index = function(_, name)
				return function(self, ...)
					self.calls[name] = (self.calls[name] or 0) + 1
					if name == "SetText" then
						self.text = ...
					elseif name == "Hide" then
						self.shown = false
					elseif name == "Show" then
						self.shown = true
					elseif name == "SetFocus" then
						self.focused = true
					elseif name == "HighlightText" then
						self.selected = true
					elseif name == "SetFrameStrata" then
						self.strata = ...
					elseif name == "SetScript" then
						self.scripts[(...)] = select(2, ...)
					elseif name == "CreateFontString" then
						local font = object("FontString")
						L.fonts[#L.fonts + 1] = font
						return font
					end
				end
			end })
		end
		env.UIParent = object("UIParent")
		env.UISpecialFrames = {}
		env.InCombatLockdown = function()
			return L.combat
		end
		env.print = function(text)
			L.out[#L.out + 1] = text
		end
		env.CreateFrame = function(kind, name, parent)
			local o = object(kind)
			o.name, o.parent = name, parent
			L.made[#L.made + 1] = o
			return o
		end
		env.C_Timer = { After = function(_, fn)
			L.timers[#L.timers + 1] = fn
		end }
		if opts.noConvert then
			env.C_EditMode = {}
		else
			env.C_EditMode = { ConvertLayoutInfoToString = function(entry)
				L.converted[#L.converted + 1] = entry
				if opts.fail then
					error("ConvertLayoutInfoToString failed", 0)
				end
				if opts.answer ~= nil then
					return opts.answer
				end
				if opts.nothing then
					return nil
				end
				return TEXT
			end, SaveLayouts = function()
				L.saves = L.saves + 1
			end, SetActiveLayout = function()
				L.actives = L.actives + 1
			end }
		end
		local ns = { Own = {}, Outline = function() return {} end, SetOutlineFill = function() end,
			EditModeOpen = function() return L.editOpen end, IsSecret = function(v) return rawequal(v, SECRET) end }
		if not opts.noSpots then
			ns.LayoutSpots = { FlatEntry = function()
				L.asked = L.asked + 1
				if opts.entry == false then
					return nil, "unavailable"
				end
				return ENTRY
			end }
		end
		loadWithEnv(ADDON_DIR .. "/LayoutText.lua", env)("FlatUI", ns)
		L.ns, L.env = ns, env
		function L.run()
			local list = L.timers
			L.timers = {}
			for _, fn in ipairs(list) do
				fn()
			end
		end
		function L.said(text)
			for _, font in ipairs(L.fonts) do
				if font.text == text then
					return true
				end
			end
			return false
		end
		return L
	end
	do
		local L = lone()
		local lines = L.ns.LayoutTextLines()
		check("bbimport: the row has one line with the id 1", #lines == 1 and lines[1][1] == 1 and lines[1][2] == "Show as import text")
		check("bbimport: loading the file makes no frame and prints nothing", #L.made == 0 and #L.out == 0 and L.asked == 0)
		L.ns.LayoutTextShow()
		local frame, scroll, edit, button = L.made[1], L.made[2], L.made[3], L.made[4]
		check("bbimport: the table handed to the game is the layout of the layout build, deep equal", #L.converted == 1 and same(L.converted[1], ENTRY) and L.asked == 1)
		check("bbimport: nothing is saved or made active on this path", L.saves == 0 and L.actives == 0 and #L.out == 0)
		check("bbimport: the window is a frame of the addon's own on UIParent, in the dialog strata", #L.made == 4 and frame.parent == L.env.UIParent and frame.strata == "DIALOG" and L.ns.Own[frame] and L.ns.Own[edit]
			and L.ns.Own[scroll] and L.ns.Own[button])
		check("bbimport: the window shows the returned text in a multi-line box in a scroll frame", edit.text == TEXT and frame.shown == true and edit.calls.SetMultiLine == 1 and scroll.calls.SetScrollChild == 1)
		check("bbimport: the window has its title and its line", L.said("Flat UI layout") and L.said("Copy this, open Edit Mode, choose Import in the layout list, paste it and name it Flat UI."))
		check("bbimport: the text is selected on a short timer, not at once", edit.selected ~= true and #L.timers == 1)
		L.run()
		check("bbimport: and then it has focus and is highlighted", edit.focused == true and edit.selected == true and edit.calls.HighlightText == 1)
		edit.scripts.OnEscapePressed()
		check("bbimport: Escape in the box hides the window", frame.shown == false)
		L.ns.LayoutTextShow()
		check("bbimport: shown again it is the same window with the text set again and selected again", #L.made == 4 and frame.shown == true and edit.calls.SetText == 2 and #L.timers == 1 and L.saves == 0)
		L.run()
		button.scripts.OnMouseUp(button, "RightButton")
		check("bbimport: a right click on Close does nothing", frame.shown == true)
		button.scripts.OnMouseUp(button, "LeftButton")
		check("bbimport: Close hides the window", frame.shown == false)
		check("bbimport: the window is in the Escape list", L.env.UISpecialFrames[1] == "FlatUILayoutText" and #L.env.UISpecialFrames == 1)
	end
	do
		local L = lone()
		L.ns.LayoutTextPick(2)
		check("bbimport: pick: another id does nothing", #L.converted == 0 and #L.made == 0 and #L.out == 0)
		L.ns.LayoutTextPick(1)
		check("bbimport: pick: the id 1 shows the window", #L.converted == 1 and L.made[1] ~= nil and L.made[1].shown == true)
	end
	do
		local N = lone({ entry = false })
		N.ns.LayoutTextShow()
		check("bbimport: no layout: the line is printed, the game is not asked and no window is made", N.out[1] == "No layout to show." and #N.out == 1 and #N.converted == 0 and #N.made == 0)
		local M = lone({ noSpots = true })
		M.ns.LayoutTextShow()
		check("bbimport: no layout build: the same line and no error", M.out[1] == "No layout to show." and #M.made == 0)
		local nothing = lone({ nothing = true })
		nothing.ns.LayoutTextShow()
		check("bbimport: a nil answer prints the line and makes no window", nothing.out[1] == WANT and #nothing.out == 1 and #nothing.made == 0 and #nothing.converted == 1)
		local err = lone({ fail = true })
		err.ns.LayoutTextShow()
		check("bbimport: an error prints the line and makes no window", err.out[1] == WANT and #err.out == 1 and #err.made == 0)
		local secret = lone({ answer = SECRET })
		secret.ns.LayoutTextShow()
		check("bbimport: a withheld answer prints the line and makes no window", secret.out[1] == WANT and #secret.out == 1 and #secret.made == 0)
		local number = lone({ answer = 12 })
		number.ns.LayoutTextShow()
		check("bbimport: an answer that is not a string prints the line and makes no window", number.out[1] == WANT and #number.made == 0)
		check("bbimport: none of these saves or makes a layout active", nothing.saves + err.saves + secret.saves + number.saves + nothing.actives + err.actives + secret.actives + number.actives == 0)
		local fight = lone({ combat = true })
		fight.ns.LayoutTextShow()
		check("bbimport: in combat: the line is printed, the game is not asked and no window is made", fight.out[1] == "The layout text is made after combat." and #fight.out == 1 and #fight.converted == 0 and #fight.made == 0 and fight.asked == 0)
		local editing = lone({ editOpen = true })
		editing.ns.LayoutTextShow()
		check("bbimport: with Edit Mode open: the line is printed and nothing else happens", editing.out[1] == "Close Edit Mode first." and #editing.out == 1 and #editing.converted == 0 and #editing.made == 0 and editing.asked == 0)
		local none = lone({ noConvert = true })
		none.ns.LayoutTextShow()
		check("bbimport: without ConvertLayoutInfoToString: the line is printed and the layout is not read", none.out[1] == "Edit Mode cannot make import text here." and #none.out == 1 and #none.made == 0 and none.asked == 0)
		local later = lone()
		later.combat = true
		later.ns.LayoutTextShow()
		later.combat = false
		later.ns.LayoutTextShow()
		check("bbimport: the fight over, the same call shows the window", #later.out == 1 and later.made[1] ~= nil and later.made[1].shown == true)
	end
	do
		-- The movers world: the row is in the page, the refusals print one line and nothing is made or saved.
		local W = suiteKit.mw()
		local FLAT = { layoutName = "Flat UI", layoutType = 1, systems = {} }
		if W.ns.LayoutSpots.FlatEntry == nil or W.ns.LayoutSpots.FlatEntry() == nil then
			W.ns.LayoutSpots.FlatEntry = function()
				return FLAT
			end
		end
		local lines = W.ns.LayoutTextLines()
		check("bbimport: world: the row lines and the pick are functions of the addon", type(W.ns.LayoutTextShow) == "function" and type(W.ns.LayoutTextPick) == "function" and #lines == 1)
		local config = io.open(ADDON_DIR .. "/Config.lua", "rb"):read("*a")
		local row = '{ key = "layoutText", kind = "list", default = 0, label = "Edit Mode layout as text", none = "Choose", items = "LayoutTextLines", pick = "LayoutTextPick" }'
		local after = config:find('key = "systems"', 1, true)
		local at = after and config:find(row, after, true)
		check("bbimport: world: the row is on the Movers page after Move the game's own frames", at ~= nil and at - after < 800)
		local made = W.made
		local function again()
			made = W.made
		end
		W.out = {}
		W.combat = true
		W.ns.LayoutTextPick(1)
		check("bbimport: world: in a fight the row prints one line and makes no frame", outText(W) == "The layout text is made after combat." and W.made == made, outText(W))
		W.combat = false
		W.editMode(true)
		again()
		W.out = {}
		W.ns.LayoutTextPick(1)
		check("bbimport: world: with Edit Mode open the row prints one line", outText(W) == "Close Edit Mode first." and W.made == made, outText(W))
		W.editMode(false)
		again()
		W.out = {}
		W.env.C_EditMode = W.env.C_EditMode or {}
		local convert = W.env.C_EditMode.ConvertLayoutInfoToString
		W.env.C_EditMode.ConvertLayoutInfoToString = nil
		W.ns.LayoutTextPick(1)
		check("bbimport: world: without the call the row prints one line", outText(W) == "Edit Mode cannot make import text here." and W.made == made, outText(W))
		for _, answer in ipairs({ SECRET, 5 }) do
			W.env.C_EditMode.ConvertLayoutInfoToString = function()
				return answer
			end
			again()
			W.out = {}
			W.ns.LayoutTextPick(1)
			check("bbimport: world: a withheld or odd answer prints one line, makes no frame and saves nothing", outText(W) == WANT and W.made == made and #W.violations == 0 and #W.errors == 0, outText(W))
		end
		W.env.C_EditMode.ConvertLayoutInfoToString = convert
	end
end
-- >>> bbimport (end)

-- >>> bbuniform (start)
-- Button size and spacing of the bar block (FlatUI/BarBlockButtons.lua): Write and Wanted on layout tables, the turning off, and the two checks at login.
do
	local BU = { SECRET = {} }
	BU.ENUM = { Orientation = 0, NumRows = 1, NumIcons = 2, IconSize = 3, IconPadding = 4, VisibleSetting = 5, HideBarArt = 6, DeprecatedSnapToSide = 7,
		HideBarScrolling = 8, AlwaysShowButtons = 9 }
	-- The bars a row can hold: choice, frame, system index in the layout.
	BU.BARS = { { "main", "MainActionBar", 1 }, { "bar2", "MultiBarBottomLeft", 2 }, { "bar3", "MultiBarBottomRight", 3 }, { "bar4", "MultiBarRight", 4 },
		{ "bar5", "MultiBarLeft", 5 }, { "bar6", "MultiBar5", 6 }, { "bar7", "MultiBar6", 7 }, { "bar8", "MultiBar7", 8 } }
	BU.DEFAULTS = { ["barblock.enabled"] = true, ["barblock.uniform"] = true, ["barblock.size"] = 100, ["barblock.spacing"] = 2, ["barblock.perRow"] = "12",
		["barblock.showEmpty"] = true, ["barblock.slot1"] = "main", ["barblock.slot2"] = "bar2", ["barblock.slot3"] = "bar3", ["barblock.slot4"] = "bar4",
		["barblock.slot5"] = "bar5", ["barblock.slot6"] = "none" }
	BU.UNTOUCHED = "0=0,3=2,5=0,6=1,8=1"

	-- A layout of the bars: each bar a row with the settings Edit Mode keeps, the stance, pet and possess bars too.
	function BU.layout()
		local rows = {}
		local function row(index, orient)
			rows[#rows + 1] = { system = 1, systemIndex = index, settings = { { setting = 6, value = 1 }, { setting = 8, value = 1 }, { setting = 5, value = 0 },
				{ setting = 0, value = orient }, { setting = 3, value = 2 } } }
		end
		for index = 1, 8 do
			row(index, index == 4 and 1 or 0)
		end
		for index = 11, 13 do
			row(index, 0)
		end
		return { layoutName = "Mine", systems = rows }
	end
	function BU.row(layout, index)
		for _, r in ipairs(layout.systems) do
			if r.systemIndex == index then
				return r
			end
		end
	end
	function BU.val(layout, index, setting)
		for _, item in ipairs(BU.row(layout, index).settings) do
			if item.setting == setting then
				return item.value
			end
		end
	end
	function BU.dump(layout, index)
		local list = {}
		for _, item in ipairs(BU.row(layout, index).settings) do
			list[#list + 1] = item.setting .. "=" .. tostring(item.value)
		end
		table.sort(list)
		return table.concat(list, ",")
	end

	-- A world: the file loaded with a stand-in ns. opts.vals overrides settings, opts.noAdd leaves AddWriter out, opts.noLS leaves LayoutSpots out,
	-- opts.enum = false leaves the enum out, opts.scale is the scale of every button container.
	function BU.up(opts)
		opts = opts or {}
		local W = { vals = {}, notes = {}, timers = {}, combat = false, unwrites = {}, rechecks = 0, scales = {}, setScales = 0, noLayout = opts.noLayout }
		for k, v in pairs(BU.DEFAULTS) do
			W.vals[k] = v
		end
		for k, v in pairs(opts.vals or {}) do
			W.vals[k] = v
		end
		local env = setmetatable({
			CreateFrame = function()
				local b = { events = {}, scripts = {} }
				function b.RegisterEvent(_, name) b.events[name] = true end
				function b.SetScript(_, name, fn) b.scripts[name] = fn end
				W.boot = b
				return b
			end,
			InCombatLockdown = function() return W.combat end,
			C_Timer = { After = function(_, fn) W.timers[#W.timers + 1] = fn end },
		}, { __index = _G })
		env._G = env
		if opts.enum ~= false then
			env.Enum = { EditModeActionBarSetting = BU.ENUM }
		end
		env.StanceBar, env.PetActionBar, env.PossessActionBar = { system = 1, systemIndex = 11 }, { system = 1, systemIndex = 12 }, { system = 1, systemIndex = 13 }
		local barFrames = {}
		for _, b in ipairs(BU.BARS) do
			local frameName = b[2]
			barFrames[b[1]] = { frame = frameName, label = b[1] }
			env[frameName] = { system = 1, systemIndex = b[3] }
			local container = {}
			function container.GetScale()
				if W.scaleFault == "error" then
					error("GetScale failed", 0)
				elseif W.scaleFault == "secret" then
					return BU.SECRET
				end
				return W.scales[frameName] or opts.scale or 1
			end
			function container.SetScale() W.setScales = W.setScales + 1 end
			env[frameName .. "ButtonContainer1"] = container
		end
		local LS = {
			Entry = function(layout, frame)
				if type(layout.systems) ~= "table" then
					return nil
				end
				for _, r in ipairs(layout.systems) do
					if r.system == frame.system and r.systemIndex == frame.systemIndex then
						return r
					end
				end
			end,
			Unwrite = function(id) W.unwrites[#W.unwrites + 1] = id end,
			Recheck = function() W.rechecks = W.rechecks + 1 end,
			WriterState = function() return W.writerState end,
			Resolve = function()
				if W.inUse then
					return {}, W.inUse
				end
				return nil, W.noLayout or "unavailable"
			end,
		}
		if not opts.noAdd then
			LS.AddWriter = function(id, writer)
				W.writers = W.writers or {}
				W.writers[id] = writer
			end
		end
		local ns = {
			Get = function(path) return W.vals[path] end,
			Enabled = function(key) return W.vals[key .. ".enabled"] == true end,
			HandsOff = function() return W.vals["general.handsOff"] == true end,
			IsSecret = function(value) return rawequal(value, BU.SECRET) end,
			Note = function(key, line) W.notes[#W.notes + 1] = key .. "|" .. line end,
			BarFrames = barFrames,
			LayoutSpots = (not opts.noLS) and LS or nil,
		}
		loadWithEnv(ADDON_DIR .. "/BarBlockButtons.lua", env)("FlatUI", ns)
		W.ns, W.env = ns, env
		W.writer = W.writers and W.writers.buttons
		-- The layout in use: by default one that holds the values this world writes. opts.inUse is another layout; false is none (a preset or no layout).
		if opts.inUse == nil and W.writer then
			W.inUse = BU.layout()
			W.writer.Write(W.inUse)
		else
			W.inUse = opts.inUse or nil
		end
		function W.flush()
			while #W.timers > 0 do
				local list = W.timers
				W.timers = {}
				for _, fn in ipairs(list) do
					fn()
				end
			end
		end
		function W.event(name)
			W.boot.scripts.OnEvent(W.boot, name)
			W.flush()
		end
		-- The world entered, then the game's first layout update.
		function W.enter()
			W.event("PLAYER_ENTERING_WORLD")
			W.event("EDIT_MODE_LAYOUTS_UPDATED")
		end
		function W.write(layout, calls)
			return W.writer.Write(layout, function(name, _, setting, before)
				calls[#calls + 1] = name .. ":" .. setting .. ":" .. tostring(before)
			end)
		end
		return W
	end

	-- Registration.
	do
		local W = BU.up()
		check("bbuniform: registration: the writer is added with its id, its label and its two functions", W.writer ~= nil and W.writer.label == "Button size and spacing"
			and type(W.writer.Wanted) == "function" and type(W.writer.Write) == "function")
		local N = BU.up({ noAdd = true })
		check("bbuniform: registration: without AddWriter the file loads and registers nothing", N.writers == nil and N.writer == nil)
		local L = BU.up({ noLS = true })
		check("bbuniform: registration: without LayoutSpots the file loads and BarButtonsChanged raises nothing", pcall(L.ns.BarButtonsChanged) and #L.unwrites == 0 and L.rechecks == 0)
		check("bbuniform: registration: the file makes one login frame and listens for three events", W.boot.events.PLAYER_ENTERING_WORLD == true and W.boot.events.PLAYER_REGEN_ENABLED == true
			and W.boot.events.EDIT_MODE_LAYOUTS_UPDATED == true)
	end

	-- With Leave the game's action bars alone on, nothing is wanted and nothing is written into the layout.
	do
		local W = BU.up()
		local wanted = W.writer.Wanted(BU.layout())
		W.vals["general.handsOff"] = true
		local calls = {}
		check("useaction: bbuniform: with the bars left alone the writer wants nothing and writes nothing", wanted == true and W.writer.Wanted(BU.layout()) == false
			and W.write(BU.layout(), calls) == false and #calls == 0, tostring(wanted))
		W.vals["barblock.uniform"] = false
		local before = #W.unwrites
		W.ns.BarButtonsChanged()
		check("useaction: bbuniform: and a change of a row of the block asks for no release of an earlier write", #W.unwrites == before, #W.unwrites .. " " .. before)
	end

	-- The values written for 100 percent, 2 px, 12 to a row.
	do
		local W = BU.up()
		local layout = BU.layout()
		check("bbuniform: wanted: a layout without the values wants them", W.writer.Wanted(layout) == true)
		local calls = {}
		local changed = W.write(layout, calls)
		check("bbuniform: write: it answers true when it changed something", changed == true)
		for _, index in ipairs({ 1, 2, 3, 4, 5 }) do
			check("bbuniform: write: bar " .. index .. " has Orientation 0, NumRows 1, NumIcons 12, IconSize 5, IconPadding 2 and Always show buttons 1",
				BU.val(layout, index, 0) == 0 and BU.val(layout, index, 1) == 1 and BU.val(layout, index, 2) == 12 and BU.val(layout, index, 3) == 5
				and BU.val(layout, index, 4) == 2 and BU.val(layout, index, 9) == 1, BU.dump(layout, index))
			check("bbuniform: write: bar " .. index .. " keeps Hide bar art, Hide bar scrolling and Visible setting", BU.val(layout, index, 6) == 1 and BU.val(layout, index, 8) == 1
				and BU.val(layout, index, 5) == 0, BU.dump(layout, index))
		end
		check("bbuniform: write: a bar outside the block (bars 6 to 8) is not touched", BU.dump(layout, 6) == BU.UNTOUCHED and BU.dump(layout, 7) == BU.UNTOUCHED
			and BU.dump(layout, 8) == BU.UNTOUCHED, BU.dump(layout, 6))
		check("bbuniform: write: the stance, pet and possess rows are not touched", BU.dump(layout, 11) == BU.UNTOUCHED and BU.dump(layout, 12) == BU.UNTOUCHED
			and BU.dump(layout, 13) == BU.UNTOUCHED, BU.dump(layout, 11))
		check("bbuniform: write: Action bar 4, which was vertical, is horizontal", BU.val(layout, 4, 0) == 0, BU.dump(layout, 4))
		local seen, joined = {}, table.concat(calls, " ")
		for _, c in ipairs(calls) do
			seen[c] = true
		end
		check("bbuniform: note: it is called with each earlier value (IconSize 2, Orientation 1) and nil for a setting that was missing", seen["MultiBarRight:3:2"] == true
			and seen["MultiBarRight:0:1"] == true and seen["MainActionBar:1:nil"] == true and seen["MainActionBar:2:nil"] == true and seen["MainActionBar:0:0"] == nil, joined)
		check("bbuniform: note: nothing is noted for a bar outside the block", not joined:find("MultiBar5") and not joined:find("StanceBar"), joined)
		check("bbuniform: wanted: false after Write", W.writer.Wanted(layout) == false)
		local again = {}
		check("bbuniform: write: a second Write changes nothing, answers false and notes nothing", W.write(layout, again) == false and #again == 0)
		check("bbuniform: write: it never sets a scale or a size on a frame", W.setScales == 0)
		local part = BU.layout()
		W.write(part, {})
		BU.row(part, 3).settings[1].value = 99
		for _, item in ipairs(BU.row(part, 3).settings) do
			if item.setting == 3 then
				item.value = 4
			end
		end
		local third = {}
		check("bbuniform: wanted: one bar with one value off is wanted again and only that value is written", W.writer.Wanted(part) == true and W.write(part, third) == true and #third == 1
			and third[1] == "MultiBarBottomRight:3:4", table.concat(third, " "))
	end

	-- Each setting changes what it should.
	do
		local function layoutFor(vals)
			local W = BU.up({ vals = vals })
			local layout = BU.layout()
			W.write(layout, {})
			return layout
		end
		local L = layoutFor({ ["barblock.size"] = 80 })
		check("bbuniform: size: 80 percent is raw 3", BU.val(L, 1, 3) == 3, BU.dump(L, 1))
		L = layoutFor({ ["barblock.size"] = 50 })
		check("bbuniform: size: 50 percent is raw 0", BU.val(L, 1, 3) == 0, BU.dump(L, 1))
		L = layoutFor({ ["barblock.size"] = 200 })
		check("bbuniform: size: 200 percent is raw 15", BU.val(L, 1, 3) == 15, BU.dump(L, 1))
		L = layoutFor({ ["barblock.size"] = 400 })
		check("bbuniform: size: a value past the slider is held at 200 percent", BU.val(L, 1, 3) == 15, BU.dump(L, 1))
		L = layoutFor({ ["barblock.size"] = 10 })
		check("bbuniform: size: a value under the slider is held at 50 percent", BU.val(L, 1, 3) == 0, BU.dump(L, 1))
		L = layoutFor({ ["barblock.spacing"] = 7 })
		check("bbuniform: spacing: 7 px is kept as 7", BU.val(L, 1, 4) == 7, BU.dump(L, 1))
		L = layoutFor({ ["barblock.spacing"] = 10 })
		check("bbuniform: spacing: 10 px is kept as 10", BU.val(L, 1, 4) == 10, BU.dump(L, 1))
		L = layoutFor({ ["barblock.spacing"] = 1 })
		check("bbuniform: spacing: 1 px is held at the slider's 2", BU.val(L, 1, 4) == 2, BU.dump(L, 1))
		L = layoutFor({ ["barblock.spacing"] = 0 })
		check("bbuniform: spacing: 0 px is held at the slider's 2", BU.val(L, 1, 4) == 2, BU.dump(L, 1))
		L = layoutFor({ ["barblock.spacing"] = 30 })
		check("bbuniform: spacing: 30 px is held at the slider's 10", BU.val(L, 1, 4) == 10, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = "6" })
		check("bbuniform: perRow: 6 to a row is 2 rows of 12 icons", BU.val(L, 1, 1) == 2 and BU.val(L, 1, 2) == 12, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = "4" })
		check("bbuniform: perRow: 4 to a row is 3 rows", BU.val(L, 1, 1) == 3 and BU.val(L, 1, 2) == 12, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = "3" })
		check("bbuniform: perRow: 3 to a row is 4 rows", BU.val(L, 1, 1) == 4 and BU.val(L, 1, 2) == 12, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = "12" })
		check("bbuniform: perRow: 12 to a row is 1 row", BU.val(L, 1, 1) == 1, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = "7" })
		check("bbuniform: perRow: a value that is not a choice is 12 to a row", BU.val(L, 1, 1) == 1, BU.dump(L, 1))
		L = layoutFor({ ["barblock.perRow"] = 6 })
		check("bbuniform: perRow: a number 6 is the same as the choice 6", BU.val(L, 1, 1) == 2, BU.dump(L, 1))
		L = layoutFor({ ["barblock.showEmpty"] = false })
		check("bbuniform: showEmpty: off is Always show buttons 0", BU.val(L, 1, 9) == 0, BU.dump(L, 1))
		L = layoutFor({ ["barblock.showEmpty"] = true })
		check("bbuniform: showEmpty: on is Always show buttons 1", BU.val(L, 1, 9) == 1, BU.dump(L, 1))
		L = layoutFor({ ["barblock.slot6"] = "bar6" })
		check("bbuniform: slots: a bar picked in the sixth row is written too", BU.val(L, 6, 3) == 5 and BU.val(L, 7, 3) == 2, BU.dump(L, 6))
		L = layoutFor({ ["barblock.slot2"] = "main" })
		check("bbuniform: slots: a bar picked twice is written once", BU.val(L, 1, 3) == 5 and BU.val(L, 2, 3) == 2 and BU.val(L, 3, 3) == 5, BU.dump(L, 2))
	end

	-- Nothing is written while the feature or the block is off.
	do
		local layout = BU.layout()
		local W = BU.up({ vals = { ["barblock.uniform"] = false } })
		check("bbuniform: off: with the setting off nothing is wanted and nothing is written", W.writer.Wanted(layout) == false and W.write(layout, {}) == false and BU.dump(layout, 1) == "0=0,3=2,5=0,6=1,8=1")
		local B = BU.up({ vals = { ["barblock.enabled"] = false } })
		check("bbuniform: off: with the block off nothing is wanted and nothing is written", B.writer.Wanted(layout) == false and B.write(layout, {}) == false)
		local S = BU.up()
		S.ns.BarFrames = nil
		check("bbuniform: off: with no bar table nothing is wanted", S.writer.Wanted(BU.layout()) == false)
		local U = BU.up()
		local fresh = BU.layout()
		fresh.systems = nil
		check("bbuniform: off: a layout with no rows is not wanted and not written", U.writer.Wanted(fresh) == false and U.write(fresh, {}) == false)
		local odd = BU.layout()
		BU.row(odd, 1).settings = nil
		check("bbuniform: write: a row with no settings gets them", BU.up().write(odd, {}) == true and BU.val(odd, 1, 3) == 5)
		check("bbuniform: wanted: a frame that has no row in the layout is skipped", BU.up().writer.Wanted({ systems = { { system = 9, systemIndex = 9, settings = {} } } }) == false)
	end

	-- Turning off: the earlier values are put back at the next Reload, and the Reload notice is asked for.
	do
		local W = BU.up()
		W.ns.BarButtonsChanged("barblock.size")
		check("bbuniform: changed: a setting that stays on asks for the Reload notice and puts nothing back", W.rechecks == 1 and #W.unwrites == 0)
		W.vals["barblock.uniform"] = false
		W.ns.BarButtonsChanged("barblock.uniform")
		check("bbuniform: changed: turned off, Unwrite is asked for every time (it does nothing when nothing is recorded) and so is the notice", #W.unwrites == 1 and W.rechecks == 2)
		local O = BU.up()
		local layout = BU.layout()
		O.write(layout, {})
		O.vals["barblock.uniform"] = false
		O.ns.BarButtonsChanged("barblock.uniform")
		check("bbuniform: changed: after values were written, off calls Unwrite for the writer", #O.unwrites == 1 and O.unwrites[1] == "buttons" and O.rechecks == 1)
		O.ns.BarButtonsChanged("barblock.uniform")
		check("bbuniform: changed: a second call asks again, since the record may be from an earlier session", #O.unwrites == 2 and O.rechecks == 2)
		local later = BU.up({ vals = { ["barblock.uniform"] = false } })
		later.writerState = nil
		later.ns.BarButtonsChanged("barblock.uniform")
		check("bbuniform: changed: a later session, where the writer has no state, still calls Unwrite", #later.unwrites == 1 and later.unwrites[1] == "buttons" and later.rechecks == 1)
		local R = BU.up()
		R.writerState = "kept"
		R.vals["barblock.uniform"] = false
		R.ns.BarButtonsChanged("barblock.uniform")
		check("bbuniform: changed: after a reload, where only the writer's record is left, off calls Unwrite", #R.unwrites == 1)
		local K = BU.up()
		K.writerState = "kept"
		K.vals["barblock.enabled"] = false
		K.event("PLAYER_ENTERING_WORLD")
		check("bbuniform: changed: with the block off at login, Unwrite is called and the notice asked for", #K.unwrites == 1 and K.rechecks == 1)
		local calm = BU.up({ vals = { ["barblock.uniform"] = false } })
		calm.event("PLAYER_ENTERING_WORLD")
		check("bbuniform: changed: with the setting off at login Unwrite is called every session", #calm.unwrites == 1 and calm.rechecks == 1)
	end

	-- The checks at login.
	do
		local function login(opts)
			local W = BU.up(opts)
			W.enter()
			return W
		end
		local OK = login({ scale = 1 })
		check("bbuniform: check: a container scale equal to the size gives no line", #OK.notes == 0 and OK.writer.Wanted(BU.layout()) == true)
		local close = login({ scale = 1.005 })
		check("bbuniform: check: a scale within 0.01 of the size gives no line", #close.notes == 0)
		local off = login({ scale = 0.8 })
		check("bbuniform: check: a container scale that differs from the size gives the line", #off.notes == 1 and off.notes[1] == "barblock|Button size and spacing: Edit Mode did not keep them.",
			table.concat(off.notes, " | "))
		check("bbuniform: check: and the feature is off: nothing is wanted or written", off.writer.Wanted(BU.layout()) == false and off.write(BU.layout(), {}) == false)
		check("bbuniform: check: and the values are taken out of the layout and the notice asked for", #off.unwrites == 1 and off.unwrites[1] == "buttons" and off.rechecks == 1)
		local rounded = login({ scale = 0.8, vals = { ["barblock.size"] = 83 } })
		check("bbuniform: check: a size of 83 is held at the step of 80, so scale 0.8 gives no line", #rounded.notes == 0 and #rounded.unwrites == 0)
		local big = login({ scale = 1.5, vals = { ["barblock.size"] = 150 } })
		check("bbuniform: check: 150 percent is scale 1.5 and gives no line", #big.notes == 0)
		local one = BU.up()
		one.scales.MultiBarLeft = 0.5
		one.enter()
		check("bbuniform: check: one bar of the block that differs is enough", #one.notes == 1)
		local outside = BU.up()
		outside.scales.MultiBar7 = 0.5
		outside.enter()
		check("bbuniform: check: a bar outside the block is not read", #outside.notes == 0)
		local secret = BU.up()
		secret.scaleFault = "secret"
		secret.enter()
		check("bbuniform: check: a withheld scale is unknown and says nothing", #secret.notes == 0 and secret.writer.Wanted(BU.layout()) == true)
		local bad = BU.up()
		bad.scaleFault = "error"
		bad.enter()
		check("bbuniform: check: a failing read is unknown and says nothing", #bad.notes == 0 and bad.writer.Wanted(BU.layout()) == true)
		local gone = BU.up({ scale = 0.8 })
		for _, b in ipairs(BU.BARS) do
			gone.env[b[2] .. "ButtonContainer1"] = nil
		end
		gone.enter()
		check("bbuniform: check: a bar with no container is unknown and says nothing", #gone.notes == 0)
		local fight = BU.up({ scale = 0.8 })
		fight.combat = true
		fight.enter()
		check("bbuniform: combat: in a fight at login nothing is read and nothing is said", #fight.notes == 0 and fight.writer.Wanted(BU.layout()) == true)
		local late = BU.up({ scale = 0.8 })
		late.combat = true
		late.enter()
		late.event("PLAYER_REGEN_ENABLED")
		check("bbuniform: combat: while the fight goes on the check keeps waiting", #late.notes == 0)
		late.combat = false
		late.event("PLAYER_REGEN_ENABLED")
		check("bbuniform: combat: the end of the fight runs the check once", #late.notes == 1)
		late.event("PLAYER_REGEN_ENABLED")
		late.enter()
		check("bbuniform: combat: a later zone change or fight says nothing more", #late.notes == 1)
		local bare = BU.up({ scale = 0.8, inUse = BU.layout() })
		bare.enter()
		check("bbuniform: check: a layout without the values and scale 0.8 gives no line, and the notice stays", #bare.notes == 0 and #bare.unwrites == 0
			and bare.writer.Wanted(bare.inUse) == true)
		local preset = BU.up({ scale = 0.8, inUse = false, noLayout = "preset" })
		preset.enter()
		check("bbuniform: check: a preset layout gives no line", #preset.notes == 0 and #preset.unwrites == 0 and preset.writer.Wanted(BU.layout()) == true)
		local none = BU.up({ scale = 0.8, inUse = false })
		none.enter()
		check("bbuniform: check: no layout resolved gives no line", #none.notes == 0 and #none.unwrites == 0 and none.writer.Wanted(BU.layout()) == true)
		local early = BU.up({ scale = 0.8 })
		early.event("PLAYER_ENTERING_WORLD")
		check("bbuniform: check: the world entered alone does not read the scale", #early.notes == 0)
		early.event("EDIT_MODE_LAYOUTS_UPDATED")
		check("bbuniform: check: the first layout update runs the check", #early.notes == 1)
		early.event("EDIT_MODE_LAYOUTS_UPDATED")
		check("bbuniform: check: a later layout update does not run it again", #early.notes == 1 and #early.unwrites == 1)
		local old = BU.up({ scale = 1, noAdd = true })
		old.enter()
		check("bbuniform: check: without the layout writer one line says the feature is not available", #old.notes == 1 and old.notes[1] == "barblock|Button size and spacing: not available in this build.")
		check("bbuniform: check: no check sets a scale", OK.setScales == 0 and off.setScales == 0 and late.setScales == 0)
		local reg = BU.up({ scale = 0.8 })
		reg.event("PLAYER_REGEN_ENABLED")
		check("bbuniform: combat: the end of a fight does not start the check before the world is entered", #reg.notes == 0)
		local noUniform = login({ scale = 0.8, vals = { ["barblock.uniform"] = false } })
		check("bbuniform: check: with the setting off the scale is not read", #noUniform.notes == 0)
		local noBlock = login({ scale = 0.8, vals = { ["barblock.enabled"] = false } })
		check("bbuniform: check: with the block off the scale is not read", #noBlock.notes == 0)
	end

	-- The writer's own bookkeeping.
	do
		local refused = BU.up({ scale = 1 })
		refused.writerState = "refused"
		refused.enter()
		check("bbuniform: kept: a refused writer gives the line and puts the feature off", #refused.notes == 1
			and refused.notes[1] == "barblock|Button size and spacing: Edit Mode did not take it." and refused.writer.Wanted(BU.layout()) == false, table.concat(refused.notes, " | "))
		local pending = BU.up({ scale = 0.8 })
		pending.writerState = "pending"
		pending.enter()
		check("bbuniform: kept: values that still wait for the Reload click say nothing and the feature stays on", #pending.notes == 0 and pending.writer.Wanted(BU.layout()) == true)
		local kept = BU.up({ scale = 1 })
		kept.writerState = "kept"
		kept.enter()
		check("bbuniform: kept: values Edit Mode kept and applied say nothing", #kept.notes == 0 and kept.writer.Wanted(BU.layout()) == true)
		local wrong = BU.up({ scale = 0.8 })
		wrong.writerState = "kept"
		wrong.enter()
		check("bbuniform: kept: values kept in the layout but not applied by the game give the scale line", #wrong.notes == 1 and wrong.notes[1]:find("did not keep") ~= nil)
	end

	-- A reload with the values already in the layout, and the enum.
	do
		local layout = BU.layout()
		BU.up().write(layout, {})
		local R = BU.up()
		check("bbuniform: reload: a layout that already holds the values is not wanted and not written again", R.writer.Wanted(layout) == false and R.write(layout, {}) == false)
		local E = BU.up({ enum = false })
		local plain = BU.layout()
		E.write(plain, {})
		check("bbuniform: enum: without the game's enum the documented numbers are used", BU.val(plain, 1, 3) == 5 and BU.val(plain, 1, 1) == 1 and BU.val(plain, 1, 4) == 2
			and BU.val(plain, 1, 9) == 1)
		local custom = BU.up()
		custom.env.Enum.EditModeActionBarSetting = { Orientation = 10, NumRows = 11, NumIcons = 12, IconSize = 13, IconPadding = 14, AlwaysShowButtons = 19 }
		local moved = BU.layout()
		custom.write(moved, {})
		check("bbuniform: enum: the numbers of the game's own enum are the ones written", BU.val(moved, 1, 13) == 5 and BU.val(moved, 1, 11) == 1 and BU.val(moved, 1, 14) == 2
			and BU.val(moved, 1, 19) == 1 and BU.val(moved, 1, 3) == 2)
	end
end
-- >>> bbuniform (end)

-- >>> ablook (begin)
-- Action bars, build ablook: the button border, empty buttons, highlight colours, bar backgrounds and the totem bar and extra action button.
do
	local A = {}
	local function alphaOf(W, name)
		local o = W.look(W.buttons[name].parts.icon)
		return o and o.top.color and o.top.color[4]
	end
	local function edgesShown(W, name)
		local o = W.look(W.buttons[name].parts.icon)
		return o ~= nil and o.shown
	end
	local function edgesHidden(W, name)
		local o = W.look(W.buttons[name].parts.icon)
		return o ~= nil and o.hidden
	end
	-- A world whose action slots are filled as held says (action number = slot).
	function A.world(options, held, more)
		local o = { saved = { options = options or {} } }
		for k, v in pairs(more or {}) do
			o[k] = v
		end
		local W = newWorld(o)
		for index = 1, 12 do
			W.buttons["ActionButton" .. index].inner.action = index
			W.buttons["MultiBarBottomLeftButton" .. index].inner.action = 12 + index
		end
		W.held = held or { [1] = true, [2] = true }
		W.env.C_ActionBar = { HasAction = function(action) return W.held[action] == true end }
		W.login()
		W.flush()
		return W
	end
	function A.step(W)
		W.advance(0)
		W.flush()
	end
	function A.quiet(W)
		return #W.violations == 0 and #W.errors == 0
	end

	-- Border.
	do
		local W = A.world({ ["actionbars.border"] = false })
		check("ablook: border off hides the four edges of every button and keeps the backdrop", edgesHidden(W, "ActionButton1") and edgesHidden(W, "MultiBarLeftButton3") and W.look(W.buttons.ActionButton1.parts.icon).backShown)
		local b = W.buttons.ActionButton1.button
		check("ablook: a mark shows its colour and thickness with the border off", W.ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251) == true and edgesShown(W, "ActionButton1")
			and near(W.look(W.buttons.ActionButton1.parts.icon).thick, 2))
		W.ns.SetButtonMark(b, "missing", nil)
		check("ablook: and takes the edges away again when the mark goes", edgesHidden(W, "ActionButton1"))
		W.change("actionbars.border", true)
		A.step(W)
		check("ablook: border on shows the edges again", edgesShown(W, "ActionButton1"))
		local D = A.world()
		check("ablook: the default draws the border", edgesShown(D, "ActionButton1") and edgesShown(D, "PetActionButton1") and A.quiet(D))
	end

	-- Empty buttons.
	do
		local W = A.world({ ["actionbars.empty"] = "faint" })
		check("ablook: faint: a filled button keeps full edges, an empty one the faint opacity", near(alphaOf(W, "ActionButton1"), 1) and near(alphaOf(W, "ActionButton5"), 0.3), tostring(alphaOf(W, "ActionButton5")))
		check("ablook: faint: the extra bars follow too", near(alphaOf(W, "MultiBarBottomLeftButton1"), 0.3), tostring(alphaOf(W, "MultiBarBottomLeftButton1")))
		check("ablook: faint: the pet bar is left alone", near(alphaOf(W, "PetActionButton1"), 1))
		W.held[5] = true
		W.fire("ACTIONBAR_SLOT_CHANGED")
		check("ablook: an event alone changes nothing before the frame ends", near(alphaOf(W, "ActionButton5"), 0.3))
		A.step(W)
		check("ablook: a slot filled shows full edges again after the event and a frame", near(alphaOf(W, "ActionButton5"), 1), tostring(alphaOf(W, "ActionButton5")))
		W.held[1] = nil
		W.fire("ACTIONBAR_SHOWGRID")
		A.step(W)
		check("ablook: a slot emptied is faint after the grid shows", near(alphaOf(W, "ActionButton1"), 0.3))
		W.change("actionbars.emptyAlpha", 50)
		A.step(W)
		check("ablook: the faint opacity is a setting", near(alphaOf(W, "ActionButton1"), 0.5), tostring(alphaOf(W, "ActionButton1")))
		W.change("actionbars.empty", "Hidden")
		A.step(W)
		check("ablook: hidden: an empty button has no edges showing", near(alphaOf(W, "ActionButton1"), 0) and near(alphaOf(W, "ActionButton6"), 0) and near(alphaOf(W, "ActionButton2"), 1))
		check("ablook: hidden also hides the backdrop", W.backdropOn(W.buttons.ActionButton6.parts.icon).color[4] == 0)
		W.change("actionbars.empty", "Normal")
		A.step(W)
		check("ablook: Normal puts every opacity back", near(alphaOf(W, "ActionButton1"), 1) and near(alphaOf(W, "ActionButton6"), 1) and near(alphaOf(W, "MultiBarBottomLeftButton1"), 1))
		W.change("actionbars.empty", "Faint")
		W.held[1] = true
		W.fire("ACTIONBAR_HIDEGRID")
		W.combat = true
		A.step(W)
		W.held[1] = nil
		W.fire("ACTIONBAR_PAGE_CHANGED")
		A.step(W)
		check("ablook: the opacity follows in combat, an outline of the addon's own", near(alphaOf(W, "ActionButton1"), 0.5) and A.quiet(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		check("ablook: no status line while the answers are plain", not has(W.status(), "withholds"), W.status())
		check("ablook: nothing is hooked", W.hooks == 0, W.hooks)
	end
	do
		local W = A.world({ ["actionbars.empty"] = "hidden" })
		W.env.C_ActionBar.HasAction = function() return SECRET end
		W.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(W)
		check("ablook: a withheld HasAction answer leaves the button as it was", near(alphaOf(W, "ActionButton5"), 1) and near(alphaOf(W, "ActionButton1"), 1) and A.quiet(W))
		check("ablook: and gives the status line", has(W.status(), "Empty buttons: the game withholds which buttons are empty, so they look normal."), W.status())
		W.env.C_ActionBar.HasAction = function() error("HasAction failed", 0) end
		W.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(W)
		check("ablook: a HasAction that fails is a withheld answer too", near(alphaOf(W, "ActionButton5"), 1) and has(W.status(), "Empty buttons: the game withholds") and A.quiet(W))
		W.env.C_ActionBar.HasAction = function(action) return W.held[action] == true end
		W.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(W)
		check("ablook: a plain answer again takes the line away and acts", near(alphaOf(W, "ActionButton5"), 0) and not has(W.status(), "withholds"), W.status())
		local N = A.world({ ["actionbars.empty"] = "hidden" })
		N.env.C_ActionBar = nil
		N.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(N)
		check("ablook: a client with no C_ActionBar leaves buttons normal and says so in one line", near(alphaOf(N, "ActionButton5"), 1) and not has(N.status(), "withholds")
			and has(N.status(), "Empty buttons: the game does not say which buttons are empty, so they look normal.") and A.quiet(N), N.status())
		local Q = A.world()
		Q.env.C_ActionBar = nil
		Q.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(Q)
		check("ablook: no line while Empty buttons is on Show", not has(Q.status(), "Empty buttons:"), Q.status())
		local S = A.world({ ["actionbars.empty"] = "hidden" })
		S.buttons.ActionButton5.inner.action = SECRET
		S.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(S)
		check("ablook: a withheld action number is a withheld answer", near(alphaOf(S, "ActionButton5"), 1) and has(S.status(), "withholds"))
	end

	-- Tints.
	do
		local W = A.world()
		local p = W.buttons.ActionButton3.parts
		local function colour(region) return region.color and string.format("%.2f,%.2f,%.2f,%.2f", region.color[1], region.color[2], region.color[3], region.color[4]) end
		check("ablook: the defaults leave every texture colour as before", colour(p.HighlightTexture) == "1.00,1.00,1.00,0.20" and colour(p.PushedTexture) == "1.00,1.00,1.00,0.25"
			and colour(p.CheckedTexture) == "1.00,0.82,0.00,0.30" and colour(p.Border) == "1.00,1.00,1.00,0.35" and colour(p.Flash) == "1.00,0.00,0.00,0.30"
			and colour(p.NewActionTexture) == "1.00,1.00,1.00,0.25" and colour(p.SpellHighlightTexture) == "1.00,0.82,0.00,0.50", colour(p.CheckedTexture))
		W.change("actionbars.hoverColour", "ff00ff00")
		W.change("actionbars.pressedColour", "ff0000ff")
		W.change("actionbars.checkedColour", "ffff0000")
		A.step(W)
		check("ablook: the three colours come from the rows, at the old opacities", colour(p.HighlightTexture) == "0.00,1.00,0.00,0.20" and colour(p.PushedTexture) == "0.00,0.00,1.00,0.25"
			and colour(p.CheckedTexture) == "1.00,0.00,0.00,0.30", colour(p.HighlightTexture) .. " " .. colour(p.PushedTexture) .. " " .. colour(p.CheckedTexture))
		check("ablook: a colour change keeps the tints over the icon", p.HighlightTexture.allPoints == p.icon and p.CheckedTexture.allPoints == p.icon)
		W.update("ActionButton3")
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		A.step(W)
		check("ablook: an art update gives the pressed texture the chosen colour again", colour(p.PushedTexture) == "0.00,0.00,1.00,0.25", colour(p.PushedTexture))
		check("ablook: the other tints stay", colour(p.Border) == "1.00,1.00,1.00,0.35" and A.quiet(W))
	end

	-- Bar backgrounds.
	do
		local bars = { "MultiBarBottomLeft", "MultiBarLeft", "StanceBar" }
		local function plateOf(W, name)
			local bar = W.env[name]
			for _, f in ipairs(W.addonFrames) do
				local raw = W.rawOf[f]
				local pt = raw and raw.points and raw.points[1]
				if pt and (pt[2] == bar or pt[2] == W.rawOf[bar]) and pt[1] == "TOPLEFT" and pt[4] == -4 and pt[5] == 4 then
					return f
				end
			end
		end
		local W = A.world({ ["barblock.background"] = true }, nil, { bars = bars })
		check("ablook: plate off makes no frame", plateOf(W, "MainActionBar") == nil and plateOf(W, "MultiBarBottomLeft") == nil)
		W.ns.MoverHeld = function(name) return { held = name == "MultiBarLeft" } end
		W.combat = true
		W.change("actionbars.plate", true)
		A.step(W)
		check("ablook: no plate is made in combat", plateOf(W, "MainActionBar") == nil and plateOf(W, "MultiBarBottomLeft") == nil and A.quiet(W))
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		A.step(W)
		local main, left = plateOf(W, "MainActionBar"), plateOf(W, "MultiBarBottomLeft")
		check("ablook: made when the fight ends, one frame for each bar", main ~= nil and left ~= nil and main ~= left and A.quiet(W))
		local look = main and W.look(main)
		local back = main and W.backdropOn(main)
		check("ablook: the plate takes the colour and opacity of the rows", back ~= nil and near(back.color[1], 15 / 255, 0.002) and near(back.color[4], 0.6) and look ~= nil)
		check("ablook: a bar that is shown has its plate shown", main:IsShown() and left:IsShown())
		W.env.MultiBarBottomLeft:Hide()
		A.step(W)
		W.fire("PLAYER_ENTERING_WORLD")
		A.step(W)
		check("ablook: a bar that is hidden has its plate hidden at the next pass", not left:IsShown() and main:IsShown())
		W.env.MultiBarBottomLeft:Show()
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		A.step(W)
		check("ablook: and shown again with the bar", left:IsShown())
		check("ablook: a bar the bar block holds with Background panel on is skipped, and one it does not hold keeps its plate", plateOf(W, "MultiBarLeft") == nil and left:IsShown())
		W.change("barblock.background", false)
		A.step(W)
		check("ablook: with Background panel off the block's bar gets a plate", plateOf(W, "MultiBarLeft") ~= nil)
		W.change("actionbars.plateAlpha", 20)
		W.change("actionbars.plateColour", "ff102030")
		A.step(W)
		back = W.backdropOn(main)
		check("ablook: plate opacity and colour follow the rows", near(back.color[4], 0.2) and near(back.color[1], 16 / 255, 0.002) and near(back.color[3], 48 / 255, 0.002))
		W.change("actionbars.plate", false)
		A.step(W)
		check("ablook: plate off hides every plate", not main:IsShown() and not left:IsShown() and not plateOf(W, "MultiBarLeft"):IsShown())
		W.change("actionbars.plate", true)
		A.step(W)
		check("ablook: plate on again shows them", main:IsShown() and left:IsShown())
		W.change("actionbars.enabled", false)
		A.step(W)
		check("ablook: the module off hides every plate", not main:IsShown() and not left:IsShown() and A.quiet(W))
		local F = A.world({ ["actionbars.plate"] = true, ["actionbars.extra"] = false }, nil, { bars = bars })
		check("ablook: a group that is off has no plate for its bars", plateOf(F, "MultiBarBottomLeft") == nil and plateOf(F, "MainActionBar") ~= nil)
	end

	-- Bar backgrounds follow the bars without an event of the module's own.
	do
		local bars = { "PetActionBar", "MultiBarBottomLeft" }
		local function plateOf(W, name)
			local bar = W.env[name]
			for _, f in ipairs(W.addonFrames) do
				local raw = W.rawOf[f]
				local pt = raw and raw.points and raw.points[1]
				if pt and (pt[2] == bar or pt[2] == W.rawOf[bar]) and pt[1] == "TOPLEFT" and pt[4] == -4 and pt[5] == 4 then
					return f
				end
			end
		end
		local W = A.world({ ["actionbars.plate"] = true }, nil, { bars = bars })
		local pet, left = plateOf(W, "PetActionBar"), plateOf(W, "MultiBarBottomLeft")
		local petRaw = W.rawOf[W.env.PetActionBar]
		petRaw.alpha, petRaw.combatOk = 1, true
		petRaw.GetAlpha = function() return petRaw.alpha end
		check("ablook: both bars have a plate, shown", pet ~= nil and left ~= nil and pet:IsShown() and left:IsShown())
		W.blizzard(function() W.env.PetActionBar:Hide() end)
		check("ablook: no module event has run, so the plate is still shown", pet:IsShown())
		W.frame(20)
		check("ablook: a bar the game hides with no module event has its plate hidden within 0.3 s", not pet:IsShown() and left:IsShown() and A.quiet(W))
		W.blizzard(function() W.env.PetActionBar:Show() end)
		W.frame(20)
		check("ablook: and shown again with the bar", pet:IsShown() and A.quiet(W))
		petRaw.alpha = 0.2
		W.frame(20)
		check("ablook: a faded bar has its plate as faint", near(W.rawOf[pet].alpha, 0.2) and near(W.rawOf[left].alpha or 1, 1), tostring(W.rawOf[pet].alpha))
		petRaw.alpha, petRaw.combatOk = 1, true
		W.combat = true
		W.blizzard(function() W.env.PetActionBar:Hide() end)
		petRaw.alpha = 0.5
		W.frame(20)
		check("ablook: in combat as well, the plate is hidden and as faint as the bar", not pet:IsShown() and near(W.rawOf[pet].alpha, 0.5) and A.quiet(W), tostring(W.rawOf[pet].alpha))
		W.blizzard(function() W.env.PetActionBar:Show() end)
		petRaw.alpha, petRaw.combatOk = 1, true
		W.frame(20)
		check("ablook: and back in combat", pet:IsShown() and near(W.rawOf[pet].alpha, 1) and A.quiet(W))
		petRaw.GetAlpha = function() return SECRET end
		petRaw.alpha = 0.3
		W.frame(20)
		check("ablook: a withheld alpha leaves the plate as it was", near(W.rawOf[pet].alpha, 1) and A.quiet(W))
		W.combat = false
		check("ablook: the watcher hooks nothing", W.hooks == 0)

		-- A bar the bar block starts or stops holding.
		local B = A.world({ ["actionbars.plate"] = true, ["barblock.background"] = true }, nil, { bars = bars })
		local held = false
		B.ns.MoverHeld = function(name) return { held = held and name == "MultiBarBottomLeft" } end
		B.fire("PLAYER_ENTERING_WORLD")
		A.step(B)
		local bl = plateOf(B, "MultiBarBottomLeft")
		check("ablook: a bar the block does not hold has a plate", bl ~= nil and bl:IsShown())
		held = true
		B.frame(20)
		check("ablook: a bar the block starts to hold loses its plate with no other event", not bl:IsShown() and A.quiet(B))
		held = false
		B.frame(20)
		check("ablook: and gets it back when the block lets it go", bl:IsShown() and A.quiet(B))

		-- Bar background off: nothing is made.
		local O = A.world({ ["actionbars.plate"] = false }, nil, { bars = bars })
		O.frame(20)
		check("ablook: with Bar background off no plate is made", plateOf(O, "PetActionBar") == nil and A.quiet(O))

		-- A creation that fails is tried again.
		local F = A.world({}, nil, { bars = bars })
		local real, fail = F.env.CreateFrame, true
		F.env.CreateFrame = function(...)
			if fail and select(3, ...) == F.env.UIParent then
				error("CreateFrame failed", 0)
			end
			return real(...)
		end
		F.change("actionbars.plate", true)
		A.step(F)
		check("ablook: a plate whose creation failed is not there", plateOf(F, "PetActionBar") == nil and plateOf(F, "MultiBarBottomLeft") == nil and has(F.status(), "Bar background: a panel could not be made."), F.status())
		fail = false
		F.errors = {}
		F.fire("ACTIONBAR_SLOT_CHANGED")
		A.step(F)
		check("ablook: the next pass makes it and the line goes", plateOf(F, "PetActionBar") ~= nil and plateOf(F, "MultiBarBottomLeft") ~= nil and not has(F.status(), "could not be made"), F.status())
	end

	-- Faint empty buttons never have a backdrop darker than the filled ones.
	do
		local W = A.world({ ["actionbars.empty"] = "faint", ["general.backdropAlpha"] = 20 })
		local filled, empty = W.backdropOn(W.buttons.ActionButton1.parts.icon).color[4], W.backdropOn(W.buttons.ActionButton5.parts.icon).color[4]
		check("ablook: faint: the backdrop of an empty button is the faint share of the backdrop of a filled one", near(filled, 0.2) and near(empty, 0.06), filled .. " " .. empty)
		check("ablook: and never darker than a filled button's", empty <= filled)
	end

	-- Totem bar and extra action button.
	do
		local W = A.world({ ["actionbars.totem"] = true, ["actionbars.ability"] = true }, nil, { special = true })
		check("ablook: the element ring of a totem button and the style art of the extra button are faded", W.buttons.MultiCastActionButton1.parts.overlayTex.alpha == 0
			and W.buttons.MultiCastActionButton12.parts.overlayTex.alpha == 0 and W.buttons.ExtraActionButton1.parts.style.alpha == 0)
		W.change("actionbars.totem", false)
		W.change("actionbars.ability", false)
		A.step(W)
		check("ablook: and given back with the groups off", W.buttons.MultiCastActionButton1.parts.overlayTex.alpha == 1 and W.buttons.ExtraActionButton1.parts.style.alpha == 1 and A.quiet(W))
	end

	-- Totem bar and extra action button, in the flat look.
	do
		local W = A.world({ ["actionbars.totem"] = true, ["actionbars.ability"] = true }, nil, { special = true })
		local p1, p2 = W.buttons.MultiCastActionButton1.parts, W.buttons.ExtraActionButton1.parts
		check("ablook: the totem buttons and the extra button are in the flat look", W.state(p1.icon) == "SB" and W.state(W.buttons.MultiCastActionButton12.parts.icon) == "SB" and W.state(p2.icon) == "SB"
			and p1.NormalTexture.alpha == 0 and p2.NormalTexture.alpha == 0 and has(W.status(), "Action bars: on, 131 styled"), W.status())
		check("ablook: they are in the group list", W.ns.ActionButtonGroup(W.buttons.MultiCastActionButton1.button) == "totem" and W.ns.ActionButtonGroup(W.buttons.ExtraActionButton1.button) == "ability")
		check("ablook: and no line says the game lacks them", not has(W.status(), "has no totem bar") and not has(W.status(), "has no extra action button") and A.quiet(W))
		local D = A.world({}, nil, { special = true })
		check("ablook: both groups are off by default", D.ns.ActionButtonGroup(D.buttons.ActionButton1.button) == "main" and D.state(D.buttons.MultiCastActionButton1.parts.icon) == "." and D.state(D.buttons.ExtraActionButton1.parts.icon) == ".")
		local N = A.world({ ["actionbars.totem"] = true, ["actionbars.ability"] = true })
		check("ablook: with the frames missing there is one line each", has(N.status(), "Totem bar buttons: the game has no totem bar.") and has(N.status(), "Extra action button: the game has no extra action button.") and A.quiet(N), N.status())
		local O = A.world({ ["actionbars.totem"] = true }, nil, { special = "ability" })
		check("ablook: only the missing one gives a line", has(O.status(), "Totem bar buttons: the game has no totem bar.") and not has(O.status(), "Extra action button:"))
		local E = A.world({ ["actionbars.ability"] = true }, nil, { special = "totem" })
		check("ablook: and the other way", has(E.status(), "Extra action button: the game has no extra action button.") and not has(E.status(), "Totem bar buttons:"))
		local Z = A.world()
		check("ablook: the lines are not given while the options are off", not has(Z.status(), "has no totem") and not has(Z.status(), "has no extra"), Z.status())
	end

	-- Marks and the contract.
	do
		local W = A.world()
		local ns = W.ns
		local b = W.buttons.ActionButton1.button
		local function ring() local o = W.look(W.buttons.ActionButton1.parts.icon) return o.r, o.g, o.b end
		check("ablook: an alert mark is drawn", ns.SetButtonMark(b, "alert", 0, 1, 0) == true and near(select(2, ring()), 1))
		check("ablook: a missing mark under an alert does not show", ns.SetButtonMark(b, "missing", 1, 0, 0) == true and near(select(2, ring()), 1) and near(select(1, ring()), 0))
		check("ablook: a proc is drawn over an alert", ns.SetButtonMark(b, "proc", 0, 0, 1) == true and near(select(3, ring()), 1))
		ns.SetButtonMark(b, "proc", nil)
		check("ablook: without the proc the alert shows again", near(select(2, ring()), 1) and near(select(3, ring()), 0))
		ns.SetButtonMark(b, "alert", nil)
		check("ablook: without the alert the missing mark shows", near(select(1, ring()), 1) and near(select(2, ring()), 0))
		ns.SetButtonMark(b, "missing", nil)
		check("ablook: with none left the outline is the general one", W.look(W.buttons.ActionButton1.parts.icon).state == "SB" and ns.SetButtonMark(b, "other", 1, 1, 1) == false)
		check("ablook: ActionButtonGroup knows main, extra, pet and stance buttons and nothing else", ns.ActionButtonGroup(b) == "main" and ns.ActionButtonGroup(W.buttons.MultiBarLeftButton1.button) == "extra"
			and ns.ActionButtonGroup(W.buttons.PetActionButton1.button) == "pet" and ns.ActionButtonGroup(W.buttons.StanceButton1.button) == "stance" and ns.ActionButtonGroup({}) == nil and ns.ActionButtonGroup(nil) == nil)
	end

	-- Nothing is hooked.
	do
		local W = A.world({ ["actionbars.plate"] = true, ["actionbars.empty"] = "faint", ["actionbars.totem"] = true, ["actionbars.ability"] = true }, nil, { special = true })
		W.fire("ACTIONBAR_SLOT_CHANGED")
		W.fire("ACTIONBAR_SHOWGRID")
		A.step(W)
		check("ablook: no hook is made with every part on", W.hooks == 0, W.hooks)
		local handle = io.open(ADDON_DIR .. "/ActionBars.lua", "r")
		local text = handle and handle:read("*a") or ""
		if handle then handle:close() end
		check("ablook: ActionBars.lua has no hooksecurefunc and no ns.Follow", text ~= "" and not text:find("hooksecurefunc", 1, true) and not text:find("ns.Follow", 1, true))
		check("ablook: and compiles", loadfile(ADDON_DIR .. "/ActionBars.lua") ~= nil)
	end
end
-- >>> ablook (end)
-- >>> abtext (begin)
-- Hotkeys, macro names and counts on action buttons (ButtonText.lua). The world gives each button the three font strings the game's template makes.
do
	local AT = { DOT = "\226\151\143" }
	AT.main, AT.side, AT.other = { "ActionButton1", "ActionButton5" }, { "MultiBarBottomLeftButton1", "MultiBar7Button3" }, { "PetActionButton1", "StanceButton1", "PossessButton1" }
	-- o.options: saved settings. o.prep(W): before login. A dot is the hotkey of ActionButton12 and MultiBarBottomLeftButton12.
	function AT.world(o)
		o = o or {}
		local W = newWorld({ saved = o.options and { options = o.options } or nil })
		W.env.RANGE_INDICATOR = AT.DOT
		W.env.ACTIONBAR_HOTKEY_FONT_COLOR = { GetRGB = function() return 0.6, 0.6, 0.6 end }
		W.env.RED_FONT_COLOR = { GetRGB = function() return 1, 0.1, 0.1 end }
		local was = W.group
		W.group = "actionbar"
		for name, b in pairs(W.buttons) do
			b.inner.name = name
			b.fs = {}
			for _, key in ipairs({ "HotKey", "Name", "Count" }) do
				local proxy, raw = W.Rr(b.button, nil, { kind = "FontString", protected = true })
				b.inner[key] = proxy
				b.fs[key] = raw
				raw.text = key == "HotKey" and "1" or key == "Name" and "Macro" or "3"
			end
		end
		W.group = was
		W.buttons.ActionButton12.fs.HotKey.text = AT.DOT
		W.buttons.MultiBarBottomLeftButton12.fs.HotKey.text = AT.DOT
		-- The game's range indicator: the colour of the hotkey of a button (ActionButton.lua:1289-1307). A withheld answer cannot be compared.
		W.env.ActionButton_UpdateRangeIndicator = function(self, checksRange, inRange)
			local hotkey = self.HotKey
			if rawequal(checksRange, SECRET) or rawequal(inRange, SECRET) then
				return
			end
			if checksRange and not inRange then
				hotkey:SetVertexColor(1, 0.1, 0.1)
			else
				hotkey:SetVertexColor(0.6, 0.6, 0.6)
			end
		end
		if o.prep then
			o.prep(W)
		end
		W.login()
		W.flush()
		return W
	end
	function AT.alpha(W, name, key) return W.buttons[name].fs[key].alpha end
	function AT.calls(W, name, key, call) return W.buttons[name].fs[key].calls[call] end
	function AT.set(W, path, value)
		W.ns.Set("actionbars." .. path, value)
		W.flush()
	end
	-- The calls the addon made on every font string, by name: the sum over all buttons.
	function AT.total(W, call)
		local n = 0
		for _, b in pairs(W.buttons) do
			for _, raw in pairs(b.fs) do
				n = n + (raw.calls[call] or 0)
			end
		end
		return n
	end
	-- How many of the buttons have the font string faded.
	function AT.faded(W, names, key)
		local n = 0
		for _, name in ipairs(names) do
			if AT.alpha(W, name, key) == 0 then n = n + 1 end
		end
		return n
	end
	function AT.point(W, name)
		local p = W.buttons[name].fs.HotKey.points
		return #p, p[1] and p[1][1], p[1] and p[1][4], p[1] and p[1][5]
	end

	-- The page and its rows.
	do
		local W = AT.world()
		local pages, at = W.ns.PAGES, nil
		for index, page in ipairs(pages) do
			if page.key == "actionbarsText" then at = index end
		end
		local page = at and pages[at]
		check("abtext: the Button text page is the one after Action bars, under it, with its settings in actionbars", page ~= nil and pages[at - 1].key == "actionbars" and page.parent == "actionbars" and page.owner == "actionbars"
			and page.label == "Button text")
		local rows, changed = {}, true
		for _, item in ipairs(page or {}) do
			if item.key then
				rows[item.key] = item
				changed = changed and item.changed == "ButtonTextChanged"
			end
		end
		check("abtext: every row calls ButtonTextChanged, and the function is there", changed and type(W.ns.ButtonTextChanged) == "function")
		check("abtext: the stand-in defaults", W.ns.Get("actionbars.hotkeyShow") == "all" and W.ns.Get("actionbars.hotkeySize") == 100 and W.ns.Get("actionbars.hotkeyOwn") == false
			and W.ns.Get("actionbars.hotkeyColour") == "ff999999" and W.ns.Get("actionbars.hotkeyPoint") == "topright" and W.ns.Get("actionbars.hotkeyX") == 0 and W.ns.Get("actionbars.hotkeyY") == 0
			and W.ns.Get("actionbars.nameShow") == "all" and W.ns.Get("actionbars.nameSize") == 100 and W.ns.Get("actionbars.countSize") == 100 and W.ns.Get("actionbars.textOutline") == "game")
		check("abtext: the bounds", rows.hotkeySize.min == 50 and rows.hotkeySize.max == 200 and rows.countSize.max == 250 and rows.hotkeyX.min == -20 and rows.hotkeyY.max == 20 and rows.hotkeyColour.needs == "hotkeyOwn"
			and rows.textOutline.choices == "OutlineChoices")
		local stepFound
		for index, step in ipairs(W.ns.SETUP_STEPS) do
			if step.id == "ab-text" then stepFound = { index = index, step = step } end
		end
		local listed = {}
		for _, row in ipairs(stepFound and stepFound.step.rows or {}) do
			listed[row[1]] = true
		end
		local all = true
		for key in pairs(rows) do
			all = all and listed["actionbars." .. key] == true
		end
		check("abtext: the wizard step Button text is built, right after Action buttons, and holds every row", stepFound ~= nil and stepFound.step.built == true and W.ns.SETUP_STEPS[stepFound.index - 1].id == "ab-bars" and all
			and stepFound.step.title == "Button text")
		local order = {}
		for line in io.lines(ADDON_DIR .. "/FlatUI.toc") do
			if line:match("%.lua%s*$") then order[#order + 1] = (line:gsub("%s+$", "")) end
		end
		local pos = {}
		for index, file in ipairs(order) do pos[file] = index end
		check("abtext: ButtonText.lua loads right after ActionBars.lua and the two files of Flat UI's own buttons", pos["ButtonText.lua"] ~= nil and pos["ButtonText.lua"] == (pos["OwnPaint.lua"] or pos["ActionBars.lua"]) + 1)
	end

	-- The defaults make no call on any font string, and nothing is hooked on a button.
	do
		local W = AT.world()
		local sum = 0
		for _, call in ipairs({ "SetFont", "SetAlpha", "SetPoint", "ClearAllPoints", "SetVertexColor", "SetTextColor", "SetShadowOffset", "SetFontObject", "SetTextHeight", "Hide", "Show", "SetShown" }) do
			sum = sum + AT.total(W, call)
		end
		check("abtext: at the defaults no call is made on any hotkey, name or count", sum == 0 and #W.ns.ActionButtons() == 118, sum)
		local hooked = 0
		for _, b in pairs(W.buttons) do
			for _, raw in pairs({ b.inner, b.fs.HotKey, b.fs.Name, b.fs.Count }) do
				for _, value in pairs(raw) do
					if type(value) == "function" and W.wrappers and W.wrappers[value] then hooked = hooked + 1 end
				end
			end
		end
		check("abtext: no method of a button or its text is hooked, and the range function is", hooked == 0 and W.wrappers[W.env.ActionButton_UpdateRangeIndicator] == true and #W.violations == 0 and #W.errors == 0,
			hooked .. " " .. table.concat(W.violations, "|"):sub(1, 200) .. table.concat(W.errors, "|"):sub(1, 200))
	end

	-- Hotkey text: mouse button, wheel and number pad keys short (ButtonText.lua ns.HotkeyText).
	do
		local T = {
			globals = { ALT_KEY_TEXT_ABBR = "a", CTRL_KEY_TEXT_ABBR = "c", META_KEY_TEXT_ABBR = "m", SHIFT_KEY_TEXT_ABBR = "s", KEY_BUTTON1 = "Left Mouse", KEY_BUTTON3 = "Middle Mouse", KEY_BUTTON4 = "Mouse Button 4",
				KEY_BUTTON31 = "Mouse Button 31", KEY_MOUSEWHEELUP = "Mouse Wheel Up", KEY_MOUSEWHEELDOWN = "Mouse Wheel Down", KEY_NUMPAD0 = "Num Pad 0", KEY_NUMPAD1 = "Num Pad 1", KEY_NUMPAD9 = "Num Pad 9",
				KEY_NUMPADPLUS = "Num Pad +", KEY_NUMPADMINUS = "Num Pad -", KEY_NUMPADMULTIPLY = "Num Pad *", KEY_NUMPADDIVIDE = "Num Pad /", KEY_NUMPADDECIMAL = "Num Pad .", KEY_PAGEUP = "Page Up",
				KEY_PAGEDOWN = "Page Down", KEY_MINUS = "-" },
			pairs = { { "Left Mouse", "M1" }, { "Middle Mouse", "M3" }, { "Mouse Button 4", "M4" }, { "Mouse Button 31", "M31" }, { "Mouse Wheel Up", "WU" }, { "Mouse Wheel Down", "WD" }, { "Num Pad 0", "N0" },
				{ "Num Pad 1", "N1" }, { "Num Pad 9", "N9" }, { "Num Pad +", "N+" }, { "Num Pad -", "N-" }, { "Num Pad *", "N*" }, { "Num Pad /", "N/" }, { "Num Pad .", "N." }, { "Page Up", "PU" }, { "Page Down", "PD" } },
			same = { "s--", "-", "s-X", "s-1", "6", "Num Pad Foo", "Mouse Button 4x", "s-", "BUTTON4", "F5", "c-s-=", "x-Num Pad 1" },
			texts = { ActionButton1 = "Mouse Button 4", ActionButton2 = "s-Num Pad 1", ActionButton3 = "s--", ActionButton4 = "Num Pad Foo", ActionButton5 = "Mouse Wheel Up", MultiBarBottomLeftButton1 = "c-s-Mouse Wheel Down" },
		}
		local function world(options)
			return AT.world({ options = options, prep = function(W)
				for key, value in pairs(T.globals) do W.env[key] = value end
				for name, text in pairs(T.texts) do W.buttons[name].fs.HotKey.text = text end
				W.env.ChangeMultiCastActionPage = function() end
			end })
		end
		local function text(W, name) return W.buttons[name].fs.HotKey.text end
		local W = world()
		local ns = W.ns
		local words, prefixed, two = true, true, true
		for _, pair in ipairs(T.pairs) do
			words = words and ns.HotkeyText(pair[1]) == pair[2]
			prefixed = prefixed and ns.HotkeyText("s-" .. pair[1]) == "s-" .. pair[2]
			two = two and ns.HotkeyText("c-s-" .. pair[1]) == "c-s-" .. pair[2]
		end
		check("hotkey text: every mapped key name is short with no modifier", words)
		check("hotkey text: and with one modifier and with two", prefixed and two)
		local same = true
		for _, one in ipairs(T.same) do same = same and ns.HotkeyText(one) == one end
		check("hotkey text: s--, a lone minus, s-X, an unmapped key and a near miss are unchanged", same)
		check("hotkey text: the default is short and the stand-in default is the row's", W.ns.Get("actionbars.hotkeyText") == "short")
		check("hotkey text: at the default the game's long texts are short", text(W, "ActionButton1") == "M4" and text(W, "ActionButton2") == "s-N1" and text(W, "ActionButton5") == "WU"
			and text(W, "MultiBarBottomLeftButton1") == "c-s-WD", text(W, "ActionButton1") .. " " .. text(W, "ActionButton2"))
		check("hotkey text: an unmapped key, s-- and the range dot are not touched", text(W, "ActionButton3") == "s--" and text(W, "ActionButton4") == "Num Pad Foo" and text(W, "ActionButton12") == AT.DOT)
		AT.set(W, "hotkeyText", "game")
		check("hotkey text: game puts the long text back", text(W, "ActionButton1") == "Mouse Button 4" and text(W, "ActionButton2") == "s-Num Pad 1" and text(W, "MultiBarBottomLeftButton1") == "c-s-Mouse Wheel Down")
		AT.set(W, "hotkeyText", "short")
		check("hotkey text: and short again", text(W, "ActionButton1") == "M4" and text(W, "ActionButton5") == "WU")
		W.buttons.ActionButton1.fs.HotKey.text = "Mouse Wheel Down"
		W.fire("UPDATE_BINDINGS")
		W.flush()
		check("hotkey text: text the game writes after a binding change is made short again", text(W, "ActionButton1") == "WD", text(W, "ActionButton1"))
		local V = world({ ["actionbars.hotkeyText"] = "game" })
		check("hotkey text: with game the long texts stay and no SetText is made", text(V, "ActionButton1") == "Mouse Button 4" and AT.total(V, "SetText") == 0, AT.total(V, "SetText"))
		local U = world({ ["actionbars.hotkeyShow"] = "side" })
		check("hotkey text: a hotkey that is hidden is not changed", text(U, "ActionButton1") == "Mouse Button 4" and text(U, "MultiBarBottomLeftButton1") == "c-s-WD")
		check("hotkey text: nothing was raised", #W.errors == 0 and #W.violations == 0 and #V.errors == 0 and #V.violations == 0 and #U.errors == 0 and #U.violations == 0, table.concat(W.errors, "|"))
		check("hotkey text: a secret text is returned as it is and nothing is raised", rawequal(ns.HotkeyText(SECRET), SECRET) and rawequal(ns.HotkeyText(SECRET, W.buttons.ActionButton1), SECRET) and #W.errors == 0)
		-- A plain string that the client calls secret is returned as it is (the table SECRET is returned by the type test alone).
		local was = W.env.issecretvalue
		W.env.issecretvalue = function(v) return v == "s-Num Pad 1" or was(v) end
		check("hotkey text: a string the client calls secret is returned as it is", ns.HotkeyText("s-Num Pad 1") == "s-Num Pad 1" and ns.HotkeyText("Num Pad 1") == "N1")
		W.env.issecretvalue = was
		do
			local X = world()
			local gets, get = 0, X.ns.Get
			X.ns.Get = function(path, ...)
				if debug.traceback():find("ButtonText", 1, true) then gets = gets + 1 end
				return get(path, ...)
			end
			X.fire("ACTIONBAR_SLOT_CHANGED")
			X.flush()
			X.ns.Get = get
			check("hotkey text: at the defaults a slot change makes no Get call from Button text", gets == 0, gets)
			X.ns.Set("actionbars.totem", true)
			X.buttons.ActionButton1.fs.HotKey.text = "Mouse Button 4"
			X.ns.ButtonTextRefresh()
			X.flush()
			check("hotkey text: turning on Totem bar buttons makes the text again", text(X, "ActionButton1") == "M4", text(X, "ActionButton1"))
			X.ns.Set("actionbars.totem", false)
			X.ns.Set("actionbars.ability", true)
			X.buttons.ActionButton1.fs.HotKey.text = "Mouse Button 4"
			X.ns.ButtonTextRefresh()
			X.flush()
			check("hotkey text: turning on Extra action button makes the text again", text(X, "ActionButton1") == "M4", text(X, "ActionButton1"))
			X.buttons.ActionButton1.fs.HotKey.text = "Mouse Button 4"
			X.blizzard(function() X.env.ChangeMultiCastActionPage(2) end)
			X.flush()
			check("hotkey text: a totem bar page change makes the text short again", text(X, "ActionButton1") == "M4" and #X.errors == 0 and #X.violations == 0, text(X, "ActionButton1"))
		end
		W.buttons.ActionButton1.fs.HotKey.text = "Mouse Button 4"
		W.fire("UPDATE_MULTI_CAST_ACTIONBAR")
		W.flush()
		check("hotkey text: text the game writes on a totem bar update is made short again", text(W, "ActionButton1") == "M4", text(W, "ActionButton1"))
		local page
		for _, one in ipairs(W.ns.PAGES) do if one.key == "actionbarsText" then page = one end end
		local row
		for _, item in ipairs(page or {}) do if item.key == "hotkeyText" then row = item end end
		check("hotkey text: the row is a choice of game or short, calls ButtonTextChanged and has the label Hotkey text", row ~= nil and row.default == "short" and row.changed == "ButtonTextChanged" and #row.choices == 2
			and row.choices[1][1] == "game" and row.choices[2][1] == "short" and row.label == "Hotkey text")
	end

	-- Which buttons show their hotkeys and macro names for each choice. The pet, stance and possess bars follow All bars only.
	do
		local expect = {
			all = { main = 0, side = 0, other = 0 },
			side = { main = 2, side = 0, other = 3 },
			main = { main = 0, side = 2, other = 3 },
			none = { main = 2, side = 2, other = 3 },
		}
		for _, choice in ipairs({ "side", "main", "none", "all" }) do
			local W = AT.world()
			AT.set(W, "hotkeyShow", choice)
			local want = expect[choice]
			local a, b, c = AT.faded(W, AT.main, "HotKey"), AT.faded(W, AT.side, "HotKey"), AT.faded(W, AT.other, "HotKey")
			check("abtext: Hotkeys on " .. choice .. " fades the right bars' hotkeys", a == want.main and b == want.side and c == want.other, a .. " " .. b .. " " .. c)
			check("abtext: Hotkeys on " .. choice .. " leaves macro names alone", AT.faded(W, AT.main, "Name") + AT.faded(W, AT.side, "Name") + AT.faded(W, AT.other, "Name") == 0)
			AT.set(W, "nameShow", choice)
			a, b, c = AT.faded(W, AT.main, "Name"), AT.faded(W, AT.side, "Name"), AT.faded(W, AT.other, "Name")
			check("abtext: Macro names on " .. choice .. " fades the right bars' names", a == want.main and b == want.side and c == want.other, a .. " " .. b .. " " .. c)
			check("abtext: counts are never faded", AT.faded(W, AT.main, "Count") + AT.faded(W, AT.side, "Count") + AT.faded(W, AT.other, "Count") == 0)
		end
		local W = AT.world()
		AT.set(W, "hotkeyShow", "none")
		AT.set(W, "hotkeyShow", "all")
		check("abtext: all again shows every hotkey", AT.faded(W, AT.main, "HotKey") + AT.faded(W, AT.side, "HotKey") + AT.faded(W, AT.other, "HotKey") == 0 and AT.alpha(W, "ActionButton1", "HotKey") == 1)
		-- The group comes from the contract function when ablook provides it, and from the name when it says nothing.
		local V = AT.world({ prep = function(P)
			P.ns.ActionButtonGroup = function() return nil end
		end })
		AT.set(V, "hotkeyShow", "side")
		check("abtext: a contract function with no answer leaves the name rule", AT.alpha(V, "MultiBarBottomLeftButton1", "HotKey") == 1 and AT.alpha(V, "ActionButton1", "HotKey") == 0)
		local U = AT.world({ prep = function(P)
			P.ns.ActionButtonGroup = function(button)
				for name, b in pairs(P.buttons) do
					if b.button == button then
						return name:find("^ActionButton") and "main" or name:find("^MultiBar") and "extra" or name:find("^Pet") and "pet" or "stance"
					end
				end
			end
		end })
		AT.set(U, "hotkeyShow", "side")
		check("abtext: the contract function's groups are used: extra is a side bar, pet and stance are other", AT.alpha(U, "MultiBar7Button3", "HotKey") == 1 and AT.alpha(U, "ActionButton1", "HotKey") == 0
			and AT.alpha(U, "PetActionButton1", "HotKey") == 0 and AT.alpha(U, "StanceButton1", "HotKey") == 0)
	end

	-- A hotkey that is the range dot is never touched.
	do
		local W = AT.world()
		AT.set(W, "hotkeyShow", "none")
		AT.set(W, "hotkeySize", 150)
		AT.set(W, "hotkeyOwn", true)
		AT.set(W, "hotkeyPoint", "center")
		AT.set(W, "textOutline", "thick")
		local touched = 0
		for _, name in ipairs({ "ActionButton12", "MultiBarBottomLeftButton12" }) do
			for call in pairs(W.buttons[name].fs.HotKey.calls) do
				if call ~= "SetText" then touched = touched + 1 end
			end
		end
		check("abtext: a hotkey that is the range dot gets no call for hiding, size, outline, colour or position", touched == 0, touched)
		AT.set(W, "hotkeyShow", "all")
		check("abtext: the other hotkeys did change", AT.calls(W, "ActionButton1", "HotKey", "SetFont") ~= nil and AT.calls(W, "ActionButton1", "HotKey", "SetPoint") ~= nil)
		-- A dot that came after the hotkey was faded gets its alpha back, as the game shows the dot itself.
		local V = AT.world()
		AT.set(V, "hotkeyShow", "none")
		V.buttons.ActionButton2.fs.HotKey.text = AT.DOT
		V.fire("UPDATE_BINDINGS")
		V.flush()
		check("abtext: a hotkey that became the range dot is shown again", AT.alpha(V, "ActionButton2", "HotKey") == 1 and AT.alpha(V, "ActionButton3", "HotKey") == 0)
	end

	-- Sizes and outline go through TextStyle, and going back puts the recorded font back.
	do
		local W = AT.world()
		local function font(name, key) return W.buttons[name].fs[key].font end
		AT.set(W, "hotkeySize", 150)
		check("abtext: Hotkey size 150 sets the hotkey font to 18 and leaves names and counts", font("ActionButton1", "HotKey") and font("ActionButton1", "HotKey")[2] == 18 and font("ActionButton1", "Name") == nil and font("ActionButton1", "Count") == nil,
			tostring(font("ActionButton1", "HotKey") and font("ActionButton1", "HotKey")[2]))
		AT.set(W, "nameSize", 50)
		AT.set(W, "countSize", 250)
		check("abtext: Macro name size 50 and Count size 250", font("ActionButton1", "Name")[2] == 6 and font("ActionButton1", "Count")[2] == 30 and font("PetActionButton1", "Count")[2] == 30 and font("PetActionButton1", "Name")[2] == 6)
		AT.set(W, "textOutline", "thick")
		check("abtext: Button text outline thick reaches the three texts", font("ActionButton1", "HotKey")[3] == "THICKOUTLINE" and font("ActionButton1", "Name")[3] == "THICKOUTLINE" and font("ActionButton1", "Count")[3] == "THICKOUTLINE")
		AT.set(W, "textOutline", "none")
		check("abtext: outline None sets empty flags", font("ActionButton1", "HotKey")[3] == "")
		AT.set(W, "hotkeySize", 100)
		AT.set(W, "nameSize", 100)
		AT.set(W, "countSize", 100)
		AT.set(W, "textOutline", "game")
		local back = font("ActionButton1", "HotKey")
		check("abtext: going back to 100 and the game's outline puts the recorded font back", back[1] == "Fonts\\FRIZQT__.TTF" and back[2] == 12 and back[3] == "" and font("ActionButton1", "Name")[2] == 12 and font("ActionButton1", "Count")[2] == 12
			and font("ActionButton1", "Count")[3] == "", back[2] .. " " .. tostring(back[3]))
		AT.set(W, "hotkeySize", 150)
		AT.set(W, "hotkeyShow", "none")
		check("abtext: a hidden group has its hotkey font put back", font("ActionButton1", "HotKey")[2] == 12)
		local calls = AT.total(W, "SetFont")
		W.fire("ACTIONBAR_SLOT_CHANGED", 1)
		W.flush()
		check("abtext: a pass with nothing changed sets no font again", AT.total(W, "SetFont") == calls)
	end

	-- Position: out of combat only, again a frame after the binding update, and back to the game's.
	do
		local W = AT.world()
		AT.set(W, "hotkeyPoint", "center")
		local n, point, x, y = AT.point(W, "ActionButton1")
		check("abtext: Hotkey position Centre anchors the hotkey at the middle of the button", n == 1 and point == "CENTER" and x == 0 and y == 0, n .. " " .. tostring(point))
		check("abtext: the hotkey of every bar moved, and the range dot one did not", AT.point(W, "MultiBar7Button3") == 1 and AT.point(W, "PetActionButton1") == 1 and #W.buttons.ActionButton12.fs.HotKey.points == 0)
		AT.set(W, "hotkeyX", 5)
		AT.set(W, "hotkeyY", -3)
		n, point, x, y = AT.point(W, "ActionButton1")
		check("abtext: the offsets are used", n == 1 and point == "CENTER" and x == 5 and y == -3, tostring(x) .. " " .. tostring(y))
		-- The game anchors the hotkey at the top right again when bindings change.
		W.blizzard(function()
			W.buttons.ActionButton1.fs.HotKey:SetPoint("TOPRIGHT", W.buttons.ActionButton1.button, "TOPRIGHT", 0, 0)
		end)
		W.fire("UPDATE_BINDINGS")
		check("abtext: after UPDATE_BINDINGS the position waits for a frame", #W.buttons.ActionButton1.fs.HotKey.points == 2)
		W.flush()
		n, point, x, y = AT.point(W, "ActionButton1")
		check("abtext: a frame after UPDATE_BINDINGS the hotkey is placed again", n == 1 and point == "CENTER" and x == 5 and y == -3, n .. " " .. tostring(point))
		AT.set(W, "hotkeyPoint", "topright")
		AT.set(W, "hotkeyX", 0)
		AT.set(W, "hotkeyY", 0)
		n, point, x, y = AT.point(W, "ActionButton1")
		check("abtext: the defaults again put the hotkey at TOPRIGHT 0, 0", n == 1 and point == "TOPRIGHT" and x == 0 and y == 0, n .. " " .. tostring(point) .. " " .. tostring(x))
		local clears = AT.total(W, "ClearAllPoints")
		W.fire("UPDATE_BINDINGS")
		W.flush()
		check("abtext: at the defaults a binding update makes no placement call", AT.total(W, "ClearAllPoints") == clears)
		-- In combat nothing is placed, and the status says why.
		local before = AT.total(W, "SetPoint")
		W.combat = true
		AT.set(W, "hotkeyPoint", "top")
		check("abtext: in combat the hotkey is not placed", AT.total(W, "SetPoint") == before and #W.violations == 0, table.concat(W.violations, "|"):sub(1, 200))
		check("abtext: in combat the status says the position waits for the end of the fight", has(W.status(), "Hotkey position: waits for the end of the fight."), W.status())
		W.combat = false
		W.fire("PLAYER_REGEN_ENABLED")
		W.flush()
		n, point = AT.point(W, "ActionButton1")
		check("abtext: after the fight the hotkey is placed and the line is gone", n == 1 and point == "TOP" and not has(W.status(), "Hotkey position"), W.status())
		-- The game's own offsets are read before the first change and put back.
		local V = AT.world({ prep = function(P)
			P.buttons.ActionButton1.inner.hotkeyTextKeyboardX = -2
			P.buttons.ActionButton1.inner.hotkeyTextKeyboardY = 3
		end })
		AT.set(V, "hotkeyPoint", "bottom")
		AT.set(V, "hotkeyPoint", "topright")
		local n2, point2, x2, y2 = AT.point(V, "ActionButton1")
		check("abtext: the game's own offsets of the hotkey are put back", n2 == 1 and point2 == "TOPRIGHT" and x2 == -2 and y2 == 3, tostring(x2) .. " " .. tostring(y2))
		local C = AT.world({ options = { ["actionbars.hotkeyPoint"] = "bottomleft" } })
		check("abtext: a saved position is placed at login", AT.point(C, "ActionButton1") == 1 and select(2, AT.point(C, "ActionButton1")) == "BOTTOMLEFT")
		-- A login in combat waits for the end of the fight.
		local D = AT.world({ options = { ["actionbars.hotkeyPoint"] = "bottomleft" }, prep = function(P) P.combat = true end })
		check("abtext: a login in combat places nothing", #D.buttons.ActionButton1.fs.HotKey.points == 0 and #D.violations == 0)
		D.combat = false
		D.fire("PLAYER_REGEN_ENABLED")
		D.flush()
		check("abtext: the fight ends and the hotkey is placed", AT.point(D, "ActionButton1") == 1 and #D.violations == 0)
	end

	-- Colour.
	do
		local W = AT.world()
		local function vertex(name) local v = W.buttons[name].fs.HotKey.vertex return ("%.2f,%.2f,%.2f"):format(v[1], v[2], v[3]) end
		local function range(name, checks, inRange)
			W.blizzard(function() W.env.ActionButton_UpdateRangeIndicator(W.buttons[name].button, checks, inRange) end)
		end
		check("abtext: with no own colour no colour is set", AT.total(W, "SetVertexColor") == 0)
		AT.set(W, "hotkeyColour", "ff3366cc")
		AT.set(W, "hotkeyOwn", true)
		check("abtext: Own hotkey colour colours every hotkey", vertex("ActionButton1") == "0.20,0.40,0.80" and vertex("MultiBar7Button3") == "0.20,0.40,0.80" and vertex("PetActionButton1") == "0.20,0.40,0.80")
		range("ActionButton1", true, false)
		W.flush()
		check("abtext: out of range the game's red is kept", vertex("ActionButton1") == "1.00,0.10,0.10" and vertex("ActionButton2") == "0.20,0.40,0.80", vertex("ActionButton1"))
		range("ActionButton1", true, true)
		check("abtext: back in range the game's grey shows until the next frame", vertex("ActionButton1") == "0.60,0.60,0.60")
		W.flush()
		check("abtext: a frame later the own colour is back", vertex("ActionButton1") == "0.20,0.40,0.80", vertex("ActionButton1"))
		range("ActionButton3", false, nil)
		W.flush()
		check("abtext: a button that checks no range keeps the own colour", vertex("ActionButton3") == "0.20,0.40,0.80")
		range("ActionButton1", true, false)
		W.flush()
		AT.set(W, "hotkeyColour", "ff00ff00")
		check("abtext: a new colour reaches the hotkeys in range and not the one out of range", vertex("ActionButton2") == "0.00,1.00,0.00" and vertex("ActionButton1") == "1.00,0.10,0.10", vertex("ActionButton2") .. " " .. vertex("ActionButton1"))
		-- A withheld answer: the game's colour stays, and the status says why, once.
		W.blizzard(function() W.buttons.ActionButton2.fs.HotKey:SetVertexColor(1, 0.1, 0.1) end)
		range("ActionButton2", SECRET, SECRET)
		range("ActionButton4", true, SECRET)
		W.flush()
		check("abtext: a withheld range keeps the game's colour on that button only", vertex("ActionButton2") == "1.00,0.10,0.10" and vertex("ActionButton5") == "0.00,1.00,0.00", vertex("ActionButton2"))
		check("abtext: a withheld range gives the line, once", count(W.status(), "Hotkey colour: the game withholds the range, so those hotkeys keep the game's colour.") == 1, W.status())
		AT.set(W, "hotkeyColour", "ff0000ff")
		check("abtext: a button with a withheld range stays with the game after a new colour", vertex("ActionButton2") == "1.00,0.10,0.10" and vertex("ActionButton4") ~= "0.00,0.00,1.00" and vertex("ActionButton5") == "0.00,0.00,1.00", vertex("ActionButton4"))
		range("ActionButton2", true, true)
		W.flush()
		check("abtext: a plain answer after a withheld one gives the button the own colour", vertex("ActionButton2") == "0.00,0.00,1.00", vertex("ActionButton2"))
		AT.set(W, "hotkeyOwn", false)
		check("abtext: own colour off gives the game's colour back to the buttons in range", vertex("ActionButton5") == "0.60,0.60,0.60" and vertex("ActionButton1") == "1.00,0.10,0.10", vertex("ActionButton5") .. " " .. vertex("ActionButton1"))
		local V = AT.world()
		AT.set(V, "hotkeyShow", "main")
		AT.set(V, "hotkeyOwn", true)
		check("abtext: only the shown group is coloured", V.buttons.MultiBar7Button3.fs.HotKey.calls.SetVertexColor == nil and V.buttons.ActionButton1.fs.HotKey.calls.SetVertexColor ~= nil)
		check("abtext: no violation and no error", #W.violations == 0 and #W.errors == 0 and #V.violations == 0 and #V.errors == 0, table.concat(W.violations, "|"):sub(1, 200) .. table.concat(W.errors, "|"):sub(1, 200))
	end

	-- Restyle action bars off, a bar group off, and on again: the game's text goes back and comes again.
	do
		local W = AT.world()
		local function hot(name) return W.buttons[name].fs.HotKey end
		AT.set(W, "hotkeyShow", "main")
		AT.set(W, "hotkeySize", 150)
		AT.set(W, "hotkeyOwn", true)
		AT.set(W, "hotkeyPoint", "center")
		AT.set(W, "nameShow", "none")
		AT.set(W, "countSize", 200)
		check("abtext: module off, the settings are in place first", AT.alpha(W, "MultiBar7Button3", "HotKey") == 0 and hot("ActionButton1").font[2] == 18 and AT.point(W, "ActionButton1") == 1)
		W.ns.Set("actionbars.enabled", false)
		W.flush()
		local ok = AT.alpha(W, "ActionButton1", "HotKey") == 1 and AT.alpha(W, "MultiBar7Button3", "HotKey") == 1 and AT.alpha(W, "PetActionButton1", "HotKey") == 1
		check("abtext: Restyle action bars off shows every hotkey and name again", ok and AT.alpha(W, "ActionButton1", "Name") == 1 and AT.alpha(W, "StanceButton1", "Name") == 1)
		check("abtext: Restyle action bars off puts the hotkey, name and count font back", hot("ActionButton1").font[2] == 12 and W.buttons.ActionButton1.fs.Count.font[2] == 12 , tostring(hot("ActionButton1").font[2]))
		local n, point, x, y = AT.point(W, "ActionButton1")
		check("abtext: Restyle action bars off puts the hotkey back at TOPRIGHT", n == 1 and point == "TOPRIGHT" and x == 0 and y == 0, n .. " " .. tostring(point))
		local v = hot("ActionButton1").vertex
		check("abtext: Restyle action bars off gives the game's colour back", ("%.2f"):format(v[1]) == "0.60", tostring(v[1]))
		W.ns.Set("actionbars.enabled", true)
		W.flush()
		check("abtext: Restyle action bars on again brings the settings back", AT.alpha(W, "MultiBar7Button3", "HotKey") == 0 and hot("ActionButton1").font[2] == 18 and select(2, AT.point(W, "ActionButton1")) == "CENTER" and W.buttons.ActionButton1.fs.Count.font[2] == 24)
		-- One group off.
		W.ns.Set("actionbars.main", false)
		W.flush()
		check("abtext: a bar group off has its hotkeys and names back, the others keep the look", AT.alpha(W, "ActionButton1", "HotKey") == 1 and AT.alpha(W, "ActionButton1", "Name") == 1 and AT.alpha(W, "MultiBar7Button3", "Name") == 0
			and hot("ActionButton1").font[2] == 12 and select(2, AT.point(W, "ActionButton1")) == "TOPRIGHT" and select(2, AT.point(W, "MultiBar7Button3")) == "CENTER" and W.buttons.ActionButton1.fs.Count.font[2] == 12)
		check("abtext: no violation and no error with the switches", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|"):sub(1, 200) .. table.concat(W.errors, "|"):sub(1, 200))
	end

	-- A profile change applies the new values, the position too.
	do
		local W = AT.world()
		W.ns.NewProfile("Text")
		AT.set(W, "hotkeyShow", "none")
		AT.set(W, "hotkeyPoint", "center")
		W.ns.UseProfile("Default")
		W.flush()
		check("abtext: a profile at the defaults shows the hotkeys at the game's place", AT.alpha(W, "ActionButton1", "HotKey") == 1 and select(2, AT.point(W, "ActionButton1")) == "TOPRIGHT")
		W.ns.UseProfile("Text")
		W.flush()
		check("abtext: changing to a profile with Hotkeys on none and position Centre applies both", AT.alpha(W, "ActionButton1", "HotKey") == 0 and select(2, AT.point(W, "ActionButton1")) == "CENTER", tostring(AT.alpha(W, "ActionButton1", "HotKey")) .. " " .. tostring(select(2, AT.point(W, "ActionButton1"))))
		W.ns.UseProfile("Default")
		W.flush()
		check("abtext: and back to the defaults puts both back", AT.alpha(W, "ActionButton1", "HotKey") == 1 and select(2, AT.point(W, "ActionButton1")) == "TOPRIGHT")
		W.ns.UseProfile("Text")
		W.ns.ResetProfile()
		W.flush()
		check("abtext: a reset puts both back", AT.alpha(W, "ActionButton1", "HotKey") == 1 and select(2, AT.point(W, "ActionButton1")) == "TOPRIGHT")
		check("abtext: no violation and no error with the profiles", #W.violations == 0 and #W.errors == 0, table.concat(W.errors, "|"):sub(1, 200))
	end

	-- A range answer costs one button, not a pass over all of them.
	do
		local W = AT.world()
		AT.set(W, "hotkeyOwn", true)
		AT.set(W, "hotkeyColour", "ff3366cc")
		local function range(name, checks, inRange)
			W.blizzard(function() W.env.ActionButton_UpdateRangeIndicator(W.buttons[name].button, checks, inRange) end)
		end
		local function vertex(name) local c = W.buttons[name].fs.HotKey.vertex return ("%.2f,%.2f,%.2f"):format(c[1], c[2], c[3]) end
		local fonts, vertexes = AT.total(W, "SetFont"), AT.total(W, "SetVertexColor")
		range("ActionButton1", true, true)
		range("ActionButton3", true, true)
		W.flush()
		check("abtext: a range answer makes no SetFont call", AT.total(W, "SetFont") == fonts)
		check("abtext: a range answer colours only the buttons that asked", AT.total(W, "SetVertexColor") == vertexes + 4 and vertex("ActionButton1") == "0.20,0.40,0.80" and vertex("ActionButton3") == "0.20,0.40,0.80", AT.total(W, "SetVertexColor") - vertexes)
		-- A pet button is coloured at once, with nothing queued.
		local pets = AT.total(W, "SetVertexColor")
		range("PetActionButton2", true, true)
		check("abtext: a pet hotkey has the own colour at once, no frame of the game's grey", vertex("PetActionButton2") == "0.20,0.40,0.80" and AT.total(W, "SetVertexColor") == pets + 2, vertex("PetActionButton2"))
		fonts = AT.total(W, "SetFont")
		local mainBefore = W.buttons.ActionButton5.fs.HotKey.calls.SetVertexColor
		for _ = 1, 10 do
			for index = 1, 10 do range("PetActionButton" .. index, true, true) end
			W.flush()
		end
		check("abtext: a hundred pet range answers make no SetFont call", AT.total(W, "SetFont") == fonts)
		check("abtext: the main bar hotkeys are not touched by them", W.buttons.ActionButton5.fs.HotKey.calls.SetVertexColor == mainBefore, tostring(W.buttons.ActionButton5.fs.HotKey.calls.SetVertexColor))
		-- With own colour off the status has no line about the range.
		local V = AT.world()
		V.blizzard(function() V.env.ActionButton_UpdateRangeIndicator(V.buttons.ActionButton2.button, true, SECRET) end)
		V.flush()
		check("abtext: a withheld range gives no line while Own hotkey colour is off", not has(V.status(), "withholds the range"), V.status())
		AT.set(V, "hotkeyOwn", true)
		check("abtext: and the line when it is on", has(V.status(), "withholds the range"), V.status())
		AT.set(V, "hotkeyOwn", false)
		check("abtext: and gone when it is off again", not has(V.status(), "withholds the range"), V.status())
	end

	-- A change of the gamepad puts the position again, a frame later.
	do
		local W = AT.world()
		AT.set(W, "hotkeyPoint", "center")
		W.blizzard(function()
			W.buttons.ActionButton1.fs.HotKey:SetPoint("TOPRIGHT", W.buttons.ActionButton1.button, "TOPRIGHT", 0, 0)
		end)
		W.fire("GAME_PAD_ACTIVE_CHANGED")
		W.flush()
		check("abtext: GAME_PAD_ACTIVE_CHANGED places the hotkey again", AT.point(W, "ActionButton1") == 1 and select(2, AT.point(W, "ActionButton1")) == "CENTER")
	end

	-- The saved settings are there again after a reload.
	do
		local W = AT.world({ options = { ["actionbars.hotkeyShow"] = "side", ["actionbars.nameShow"] = "main", ["actionbars.hotkeySize"] = 150, ["actionbars.textOutline"] = "outline",
			["actionbars.hotkeyOwn"] = true, ["actionbars.hotkeyColour"] = "ff112233" } })
		local v = W.buttons.MultiBar7Button3.fs.HotKey.vertex
		check("abtext: a reload gives the saved choices at once", AT.alpha(W, "ActionButton1", "HotKey") == 0 and AT.alpha(W, "MultiBar7Button3", "HotKey") == 1 and AT.alpha(W, "MultiBar7Button3", "Name") == 0
			and AT.alpha(W, "ActionButton1", "Name") == 1 and W.buttons.MultiBar7Button3.fs.HotKey.font[2] == 18 and W.buttons.MultiBar7Button3.fs.HotKey.font[3] == "OUTLINE"
			and W.buttons.ActionButton1.fs.Name.font[3] == "OUTLINE" and math.abs(v[1] - 0x11 / 255) < 1e-6 and AT.calls(W, "ActionButton1", "HotKey", "SetVertexColor") == nil)
	end
end
-- >>> abtext (end)

-- >>> abstate (begin)
-- Button colours and cooldowns (FlatUI/ButtonStates.lua, page Colours and cooldowns). Every label starts "abstate:".
do
	local K = {}
	local function near(a, b) return type(a) == "number" and math.abs(a - b) < 0.003 end
	-- A world with the bars, a game that answers IsUsableAction from W.usable[action] ({ usable, noMana }, "secret" or nothing for usable), the two
	-- global calls, a spy on every hook, and a Cooldown stand-in on each button that records the three calls and takes the button for its parent.
	function K.world(o)
		o = o or {}
		local W = newWorld(o.opts or {})
		W.usable = {}
		W.hooked = {}
		W.spy = {}
		if not o.noApi then
			W.env.C_ActionBar = { IsUsableAction = function(action)
				local held = W.usable[action]
				if held == nil then return true, false end
				if held == "secret" then return SECRET, SECRET end
				return held[1], held[2]
			end }
		end
		W.env.ActionButton_UpdateRangeIndicator = function() end
		W.env.ActionButton_ApplyCooldown = function() end
		local base = W.env.hooksecurefunc
		W.env.hooksecurefunc = function(object, name, hook)
			W.hooked[#W.hooked + 1] = (type(object) == "string" and object) or (object == W.env and name) or ("method:" .. tostring(name))
			return base(object, name, hook)
		end
		W.number = {}
		local count = 0
		local names = {}
		for name in pairs(W.buttons) do names[#names + 1] = name end
		table.sort(names)
		for _, name in ipairs(names) do
			count = count + 1
			W.number[name] = count
			W.buttons[name].inner.action = count
			local cd = W.rawOf[W.buttons[name].parts.cooldown]
			local spy = { calls = {} }
			W.spy[name] = spy
			local button = W.buttons[name].button
			cd.GetParent = function() return button end
			for _, method in ipairs({ "SetDrawSwipe", "SetSwipeColor", "SetCountdownFont" }) do
				cd[method] = function(_, ...)
					spy.calls[#spy.calls + 1] = { method, ... }
					if spy.refuse == method then error("refused", 0) end
				end
			end
		end
		if o.prep then o.prep(W) end
		W.login()
		K.step(W)
		return W
	end
	function K.step(W)
		W.advance(0)
		W.advance(0)
	end
	function K.btn(W, name) return W.buttons[name].button end
	function K.icon(W, name) return W.rawOf[W.buttons[name].parts.icon] end
	function K.colour(W, name)
		local v = K.icon(W, name).vertex
		return { v[1], v[2], v[3] }
	end
	function K.is(c, r, g, b) return near(c[1], r) and near(c[2], g) and near(c[3], b) end
	function K.range(W, name, checks, inRange)
		W.blizzard(function() W.env.ActionButton_UpdateRangeIndicator(K.btn(W, name), checks, inRange) end)
	end
	function K.cool(W, name, info)
		W.blizzard(function() W.env.ActionButton_ApplyCooldown(W.buttons[name].parts.cooldown, info) end)
	end
	function K.total(W)
		local n = 0
		for _, spy in pairs(W.spy) do n = n + #spy.calls end
		return n
	end
	function K.line(W, text)
		return W.status():find(text, 1, true) ~= nil
	end
	function K.lines(W, text)
		local n, at = 0, 1
		local status = W.status()
		while true do
			local from, to = status:find(text, at, true)
			if not from then break end
			n = n + 1
			at = to + 1
		end
		return n
	end
	function K.quiet(W) return #W.violations == 0 and #W.errors == 0 end
	local HEX = { mana = { 128 / 255, 128 / 255, 1 }, unusable = { 0.4, 0.4, 0.4 }, range = { 163 / 255, 38 / 255, 38 / 255 } }

	check("abstate: ButtonStates.lua is in the TOC right after Cooldowns.lua and is not a module", (function()
		for index, name in ipairs(FILES) do
			if name == "Cooldowns.lua" then return FILES[index + 1] == "ButtonStates.lua" end
		end
		return false
	end)() and loadfile(ADDON_DIR .. "/ButtonStates.lua") ~= nil)
	-- Defaults and the page.
	do
		local W = K.world()
		local defaults = { usableOwn = false, manaColour = "ff8080ff", unusableColour = "ff666666", rangeTint = false, rangeColour = "ffa32626", sweep = true, sweepOwn = false, sweepAlpha = 65, cdFont = "game", cdGrey = false }
		local wrong = {}
		for key, value in pairs(defaults) do
			if W.ns.Get("actionbars." .. key) ~= value then wrong[#wrong + 1] = key end
		end
		check("abstate: the ten settings have their stand-in defaults", #wrong == 0, table.concat(wrong, " "))
		local page
		for _, p in ipairs(W.ns.PAGES) do if p.key == "actionbarsColours" then page = p end end
		check("abstate: the page is Colours and cooldowns under Action bars and every row calls ButtonStatesChanged", page ~= nil and page.parent == "actionbars" and page.owner == "actionbars" and page.label == "Colours and cooldowns"
			and (function() for _, item in ipairs(page) do if item.key and item.changed ~= "ButtonStatesChanged" then return false end end return type(W.ns.ButtonStatesChanged) == "function" end)())
		-- Defaults make no call.
		for _, name in ipairs({ "ActionButton1", "MultiBarBottomLeftButton3" }) do
			K.range(W, name, true, false)
			K.cool(W, name, { isActive = true, isOnGCD = false })
		end
		W.fire("ACTION_USABLE_CHANGED", { { slot = 1, usable = false, noMana = true } })
		W.fire("SPELL_UPDATE_USABLE")
		K.step(W)
		local untouched = true
		for name in pairs(W.buttons) do
			if K.icon(W, name).desaturatedArg ~= nil or (K.icon(W, name).calls.SetVertexColor or 0) > 0 then untouched = false end
		end
		check("abstate: at the defaults no icon colour or desaturation is set and no cooldown call is made", untouched and K.total(W) == 0 and K.quiet(W), K.total(W))
		local globals, methods = {}, 0
		for _, name in ipairs(W.hooked) do
			if name:find("^method:") then methods = methods + 1 else globals[name] = (globals[name] or 0) + 1 end
		end
		check("abstate: the two hooks are on global functions, once each, and no method is hooked", globals.ActionButton_UpdateRangeIndicator == 1 and globals.ActionButton_ApplyCooldown == 1 and methods == 0, table.concat(W.hooked, ","))
	end

	-- Usability colours.
	do
		local W = K.world()
		W.usable[W.number.ActionButton1], W.usable[W.number.ActionButton2], W.usable[W.number.ActionButton3] = { true, false }, { false, true }, { false, false }
		W.ns.Set("actionbars.usableOwn", true)
		W.fire("ACTION_USABLE_CHANGED", { { slot = 1 } })
		K.step(W)
		local a, b, c = K.colour(W, "ActionButton1"), K.colour(W, "ActionButton2"), K.colour(W, "ActionButton3")
		check("abstate: own usability colours: usable is white, not enough power and cannot use take the rows' colours", K.is(a, 1, 1, 1) and K.is(b, HEX.mana[1], HEX.mana[2], HEX.mana[3]) and K.is(c, 0.4, 0.4, 0.4), b[1] .. " " .. c[1])
		W.usable[W.number.ActionButton1] = { false, true }
		local before = K.icon(W, "ActionButton1").calls.SetVertexColor
		W.fire("ACTION_USABLE_CHANGED", { { slot = 1, usable = false, noMana = true } })
		check("abstate: nothing is painted inside the event, only a frame later", K.icon(W, "ActionButton1").calls.SetVertexColor == before)
		K.step(W)
		check("abstate: after the frame the button has the not enough power colour", K.is(K.colour(W, "ActionButton1"), HEX.mana[1], HEX.mana[2], HEX.mana[3]))
		W.ns.Set("actionbars.manaColour", "ff00ff00")
		K.step(W)
		check("abstate: a changed colour row repaints", K.is(K.colour(W, "ActionButton1"), 0, 1, 0) and K.is(K.colour(W, "ActionButton2"), 0, 1, 0))
		W.ns.Set("actionbars.usableOwn", false)
		K.step(W)
		check("abstate: switched off again, the game's own colours are put back", K.is(K.colour(W, "ActionButton1"), 0.5, 0.5, 1) and K.is(K.colour(W, "ActionButton3"), 0.4, 0.4, 0.4) and K.is(K.colour(W, "ActionButton2"), 0.5, 0.5, 1))
		W.ns.Set("actionbars.usableOwn", true)
		for _, name in ipairs({ "ActionButton1", "ActionButton2", "ActionButton3" }) do W.usable[W.number[name]] = "secret" end
		K.icon(W, "ActionButton1").vertex = { 0.9, 0.8, 0.7, 1 }
		local calls = K.icon(W, "ActionButton1").calls.SetVertexColor
		W.fire("ACTION_USABLE_CHANGED", { { slot = 1 } })
		K.step(W)
		check("abstate: a withheld usable answer leaves the game's colour and gives its line once", K.is(K.colour(W, "ActionButton1"), 0.9, 0.8, 0.7) and K.icon(W, "ActionButton1").calls.SetVertexColor == calls
			and K.lines(W, "Own usability colours: the game withholds whether an action can be used, so those buttons keep the game's colours.") == 1, W.status())
		check("abstate: a withheld answer is not read as false: the button is not painted cannot-use", not K.is(K.colour(W, "ActionButton1"), 0.4, 0.4, 0.4))
		local N = K.world({ noApi = true })
		N.ns.Set("actionbars.usableOwn", true)
		K.step(N)
		check("abstate: without IsUsableAction the buttons keep the game's colours and the line is given", K.line(N, "Own usability colours: the game withholds") and K.quiet(N))
	end

	-- Range tint.
	do
		local W = K.world()
		W.usable[W.number.ActionButton2] = { false, true }
		W.ns.Set("actionbars.usableOwn", true)
		W.ns.Set("actionbars.rangeTint", true)
		K.step(W)
		K.range(W, "ActionButton1", true, false)
		K.range(W, "ActionButton2", true, false)
		check("abstate: nothing is painted inside the game's range call", K.is(K.colour(W, "ActionButton1"), 1, 1, 1))
		K.step(W)
		check("abstate: out of range paints the range colour, and it wins over not enough power", K.is(K.colour(W, "ActionButton1"), HEX.range[1], HEX.range[2], HEX.range[3]) and K.is(K.colour(W, "ActionButton2"), HEX.range[1], HEX.range[2], HEX.range[3]))
		K.range(W, "ActionButton2", true, true)
		K.range(W, "ActionButton1", false, false)
		K.step(W)
		check("abstate: back in range, or a spell that checks no range, goes back to the usable colour", K.is(K.colour(W, "ActionButton1"), 1, 1, 1) and K.is(K.colour(W, "ActionButton2"), HEX.mana[1], HEX.mana[2], HEX.mana[3]))
		W.ns.Set("actionbars.rangeColour", "ff00ff00")
		K.range(W, "ActionButton1", true, false)
		K.step(W)
		check("abstate: the range colour row changes the tint", K.is(K.colour(W, "ActionButton1"), 0, 1, 0))
		W.ns.Set("actionbars.usableOwn", false)
		K.step(W)
		K.icon(W, "ActionButton3").vertex = { 0.9, 0.8, 0.7, 1 }
		local calls = K.icon(W, "ActionButton3").calls.SetVertexColor or 0
		K.range(W, "ActionButton3", true, SECRET)
		K.range(W, "ActionButton3", SECRET, SECRET)
		K.step(W)
		check("abstate: a withheld range answer leaves the colour and gives its line", K.is(K.colour(W, "ActionButton3"), 0.9, 0.8, 0.7) and (K.icon(W, "ActionButton3").calls.SetVertexColor or 0) == calls
			and K.lines(W, "Tint icon when out of range: the game withholds the range, so those icons keep their colour.") == 1, W.status())
		W.ns.Set("actionbars.rangeTint", false)
		K.step(W)
		check("abstate: the tint off puts the usable colour back", K.is(K.colour(W, "ActionButton1"), 1, 1, 1))
	end

	-- Buttons the file leaves alone.
	do
		local W = K.world()
		W.ns.Set("actionbars.usableOwn", true)
		W.ns.Set("actionbars.rangeTint", true)
		W.ns.Set("actionbars.sweep", false)
		W.ns.Set("actionbars.cdGrey", true)
		for _, name in ipairs({ "PetActionButton1", "StanceButton1", "PossessButton1" }) do
			W.usable[W.number[name]] = { false, false }
			K.range(W, name, true, false)
			K.cool(W, name, { isActive = true, isOnGCD = false })
		end
		W.fire("ACTION_USABLE_CHANGED", { { slot = 1 } })
		K.step(W)
		local calm = true
		for _, name in ipairs({ "PetActionButton1", "StanceButton1", "PossessButton1" }) do
			if (K.icon(W, name).calls.SetVertexColor or 0) > 0 or K.icon(W, name).desaturatedArg ~= nil or #W.spy[name].calls > 0 then calm = false end
		end
		check("abstate: pet, stance and possess buttons keep the game's colours and cooldowns", calm and K.quiet(W))
		-- A flyout button calls the same globals with a frame that is not on the bars.
		local flyout = {}
		local ok = pcall(function()
			W.blizzard(function()
				W.env.ActionButton_UpdateRangeIndicator(flyout, true, false)
				W.env.ActionButton_ApplyCooldown({ GetParent = function() return flyout end }, { isActive = true })
			end)
		end)
		K.step(W)
		check("abstate: flyout buttons are ignored", ok and K.quiet(W))
		check("abstate: main and extra buttons are painted", #W.spy.ActionButton1.calls > 0 and #W.spy.MultiBar7Button12.calls > 0)
	end

	-- The cooldown.
	do
		local W = K.world()
		local spy = W.spy.ActionButton1
		W.ns.Set("actionbars.sweep", false)
		K.step(W)
		local off = 0
		for _, call in ipairs(spy.calls) do if call[1] == "SetDrawSwipe" and call[2] == false then off = off + 1 end end
		check("abstate: Cooldown sweep off hides the swipe of every main and extra button", off >= 1 and #W.spy.MultiBarRightButton4.calls >= 1 and #W.spy.PetActionButton2.calls == 0)
		spy.calls = {}
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.step(W)
		check("abstate: the game's own cooldown call is answered with the swipe off again", spy.calls[1] and spy.calls[1][1] == "SetDrawSwipe" and spy.calls[1][2] == false, #spy.calls)
		W.ns.Set("actionbars.sweep", true)
		K.step(W)
		local last
		for _, call in ipairs(spy.calls) do if call[1] == "SetDrawSwipe" then last = call[2] end end
		check("abstate: the sweep on again draws it again", last == true)
		spy.calls = {}
		W.ns.Set("actionbars.sweepOwn", true)
		K.step(W)
		local alpha
		for _, call in ipairs(spy.calls) do if call[1] == "SetSwipeColor" then alpha = call end end
		check("abstate: Own sweep opacity sets the swipe colour to black at the row's percent over 100", alpha and alpha[2] == 0 and alpha[3] == 0 and alpha[4] == 0 and near(alpha[5], 0.65), alpha and tostring(alpha[5]))
		W.ns.Set("actionbars.sweepAlpha", 20)
		K.step(W)
		for _, call in ipairs(spy.calls) do if call[1] == "SetSwipeColor" then alpha = call end end
		check("abstate: the opacity row changes it", near(alpha[5], 0.2))
		W.ns.Set("actionbars.sweepOwn", false)
		K.step(W)
		for _, call in ipairs(spy.calls) do if call[1] == "SetSwipeColor" then alpha = call end end
		check("abstate: Own sweep opacity off puts the game's opacity back", near(alpha[5], 1))
		local names = { small = "NumberFontNormalSmall", normal = "NumberFontNormal", large = "NumberFontNormalLarge", huge = "NumberFontNormalHuge" }
		local bad = {}
		for choice, font in pairs(names) do
			spy.calls = {}
			W.ns.Set("actionbars.cdFont", choice)
			K.step(W)
			local got
			for _, call in ipairs(spy.calls) do if call[1] == "SetCountdownFont" then got = call[2] end end
			if got ~= font then bad[#bad + 1] = choice end
		end
		check("abstate: Cooldown number size sets the game's font object of each size", #bad == 0, table.concat(bad, " "))
		spy.calls = {}
		W.ns.Set("actionbars.cdFont", "game")
		K.step(W)
		check("abstate: back to As the game has it makes no call and says it applies after a reload", #spy.calls == 0 and K.line(W, "Cooldown number size: As the game has it applies after /reload."))
	end

	-- Grey icon on cooldown.
	do
		local W = K.world()
		W.ns.Set("actionbars.cdGrey", true)
		K.step(W)
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.cool(W, "ActionButton2", { isActive = true, isOnGCD = true })
		K.cool(W, "ActionButton3", { isActive = false, isOnGCD = false })
		K.step(W)
		check("abstate: an icon on a cooldown that is not the global cooldown is grey", K.icon(W, "ActionButton1").desaturated == true)
		check("abstate: the global cooldown and no cooldown do not grey an icon", not K.icon(W, "ActionButton2").desaturated and not K.icon(W, "ActionButton3").desaturated)
		K.cool(W, "ActionButton1", { isActive = false, isOnGCD = false })
		K.step(W)
		check("abstate: the colour comes back when the cooldown ends", K.icon(W, "ActionButton1").desaturated == false)
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.step(W)
		K.cool(W, "ActionButton4", { isActive = SECRET, isOnGCD = SECRET })
		K.cool(W, "ActionButton5", { isActive = true, isOnGCD = SECRET })
		K.step(W)
		check("abstate: withheld cooldown fields change nothing and give the line once", K.icon(W, "ActionButton4").desaturatedArg == nil and K.icon(W, "ActionButton5").desaturatedArg == nil
			and K.lines(W, "Grey out icon on cooldown: the game hides cooldowns in fights, so icons stay coloured there.") == 1, W.status())
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.step(W)
		K.cool(W, "ActionButton1", { isActive = SECRET, isOnGCD = SECRET })
		K.step(W)
		check("abstate: a withheld cooldown takes the grey off", K.icon(W, "ActionButton1").desaturated == false)
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.step(W)
		K.cool(W, "ActionButton1", nil)
		K.step(W)
		check("abstate: a cooldown call with no info takes the grey off", K.icon(W, "ActionButton1").desaturated == false)
		K.cool(W, "ActionButton1", { isActive = true, isOnGCD = false })
		K.step(W)
		W.ns.Set("actionbars.cdGrey", false)
		K.step(W)
		check("abstate: the row off puts a greyed icon back", K.icon(W, "ActionButton1").desaturated == false)
	end

	-- A cast animation, a refused call, combat and reload.
	do
		local W = K.world()
		W.ns.Set("actionbars.sweep", false)
		K.step(W)
		W.spy.ActionButton1.calls = {}
		W.spy.ActionButton2.calls = {}
		W.buttons.ActionButton1.inner.actionButtonCastType = 1
		K.cool(W, "ActionButton1", { isActive = true })
		K.cool(W, "ActionButton2", { isActive = true })
		K.step(W)
		check("abstate: a button in a cast animation is skipped, the next one is not", #W.spy.ActionButton1.calls == 0 and #W.spy.ActionButton2.calls >= 1)
		local R = K.world()
		R.spy.ActionButton1.refuse = "SetDrawSwipe"
		R.ns.Set("actionbars.sweep", false)
		K.step(R)
		local n = #R.spy.ActionButton1.calls
		K.cool(R, "ActionButton1", { isActive = true })
		K.step(R)
		check("abstate: a refused sweep call turns the row off with its line and is not made again", K.line(R, "Cooldown sweep: the game refused the change.") and #R.spy.ActionButton1.calls == n and K.quiet(R), n .. " " .. #R.spy.ActionButton1.calls)
		local Q = K.world()
		Q.spy.ActionButton1.refuse = "SetSwipeColor"
		Q.ns.Set("actionbars.sweepOwn", true)
		K.step(Q)
		K.cool(Q, "ActionButton1", { isActive = true })
		K.step(Q)
		check("abstate: a refused sweep colour names Own sweep opacity", K.line(Q, "Own sweep opacity: the game refused the change."), Q.status())
		local C = K.world()
		C.ns.Set("actionbars.usableOwn", true)
		C.usable[C.number.ActionButton1] = { false, true }
		C.combat = true
		C.fire("ACTION_USABLE_CHANGED", { { slot = 1 } })
		K.step(C)
		check("abstate: the pass runs in combat and paints", K.is(K.colour(C, "ActionButton1"), HEX.mana[1], HEX.mana[2], HEX.mana[3]) and K.quiet(C))
		local L = K.world({ opts = { saved = { options = { ["actionbars.usableOwn"] = true, ["actionbars.sweep"] = false } } }, prep = function(W) W.usable[W.number.ActionButton1] = { false, false } end })
		check("abstate: after a reload the saved rows are in force at once", K.is(K.colour(L, "ActionButton1"), 0.4, 0.4, 0.4) and #L.spy.ActionButton1.calls >= 1 and K.quiet(L))
		local G = K.world({ opts = { saved = { options = { ["actionbars.enabled"] = false, ["actionbars.sweep"] = false } } } })
		K.step(G)
		check("abstate: with Restyle action bars off nothing is touched", K.total(G) == 0 and K.quiet(G))
	end
end
-- >>> abstate (end)

-- >>> abfx (begin)
-- Glows and animations on action buttons (abfx:): proc glow, rotation helper, cast fill, interrupt flash and extra button artwork, done a frame after the game's call.
do
	local X = { ALL = { "ActionButton1", "ActionButton2", "MultiBarBottomLeftButton1" } }
	X.NO_ASSIST = "Rotation helper highlight: the game has no rotation helper."
	X.NO_EXTRA = "Extra button artwork: the game has no extra action button."
	X.REFUSED = "Proc glow: the game refused the change."
	function X.region(refuse)
		local r = { alpha = 1, sets = 0 }
		function r.SetAlpha(self, a)
			if refuse then
				error("SetAlpha refused", 0)
			end
			self.alpha = a
			self.sets = self.sets + 1
		end
		return r
	end
	-- o.options saved settings; o.manager false for no manager, "half" for one without HideAlert; o.refuse the alert frames refuse SetAlpha; o.registry a registry;
	-- o.assist C_AssistedCombat present; o.extra an ExtraActionButton1 with a style, an ExtraActionBarFrame and a ZoneAbilityFrame.
	function X.world(o)
		o = o or {}
		local opts = { trackers = true }
		if o.options then
			opts.saved = { options = o.options }
		end
		local W = newWorld(opts)
		W.ns.TrackerSlots = nil
		W.x = { alerts = {}, cast = {}, interrupt = {}, marks = {} }
		for _, name in ipairs(X.ALL) do
			local inner = W.buttons[name].inner
			W.x.alerts[name] = X.region(o.refuse)
			W.x.cast[name], W.x.interrupt[name] = X.region(), X.region()
			inner.SpellActivationAlert, inner.SpellCastAnimFrame, inner.InterruptDisplay = W.x.alerts[name], W.x.cast[name], W.x.interrupt[name]
		end
		if o.manager ~= false then
			local manager = { activeAlerts = {}, SpellAlertType = { Default = 1, AssistedCombatRotation = 2 } }
			function manager:ShowAlert(button, kind) if button then self.activeAlerts[button] = kind or 1 end end
			function manager:HideAlert(button) if button then self.activeAlerts[button] = nil end end
			if o.manager == "half" then
				manager.HideAlert = nil
			end
			W.env.ActionButtonSpellAlertManager = manager
			W.x.manager = manager
		end
		if o.registry then
			local registry = { callbacks = {} }
			function registry:RegisterCallback(event, func, owner)
				registry.callbacks[event] = registry.callbacks[event] or {}
				table.insert(registry.callbacks[event], { owner = owner, func = func })
				return owner
			end
			function registry:TriggerEvent(event, ...)
				for _, entry in ipairs(registry.callbacks[event] or {}) do
					entry.func(entry.owner, ...)
				end
			end
			W.env.EventRegistry = registry
			W.x.registry = registry
		end
		if o.assist then
			W.env.C_AssistedCombat = {}
			W.env.AssistedCombatManager = {}
		end
		if o.extra then
			W.x.style, W.x.frame = X.region(), X.region()
			W.env.ExtraActionButton1 = { style = W.x.style }
			W.env.ExtraActionBarFrame = W.x.frame
			W.env.ZoneAbilityFrame = { Style = X.region() }
			W.x.zone = W.env.ZoneAbilityFrame.Style
		end
		W.login()
		W.flush()
		W.advance(0.3)
		W.advance(0)
		W.x.log = {}
		local ns = W.ns
		local real = ns.SetButtonMark
		ns.SetButtonMark = function(button, source, r, g, b)
			W.x.log[#W.x.log + 1] = { button = button, source = source, r = r, g = g, b = b }
			return real(button, source, r, g, b)
		end
		return W
	end
	function X.button(W, name)
		return W.buttons[name].button
	end
	function X.marks(W, name)
		local list = {}
		for _, entry in ipairs(W.x.log) do
			if entry.button == X.button(W, name) and entry.source == "alert" then
				list[#list + 1] = entry
			end
		end
		return list
	end
	function X.all(W, group, want)
		for _, name in ipairs(X.ALL) do
			if W.x[group][name].alpha ~= want then
				return false
			end
		end
		return true
	end
	function X.count(W, line)
		local n = 0
		for _ in W.status():gmatch((line:gsub("%p", "%%%0"))) do
			n = n + 1
		end
		return n
	end

	-- The page and the step.
	do
		local W = X.world()
		local rows, at, section = {}, {}, {}
		local page
		for index, p in ipairs(W.ns.PAGES) do
			if p.key == "actionbarsEffects" then
				page = p
				at.effects = index
				local last
				for _, item in ipairs(p) do
					if item.section then
						last = item.section
					end
					if item.path then
						rows[item.path] = item
						section[item.path] = last
					end
				end
			elseif p.key == "swing" then
				at.swing = index
			end
		end
		check("abfx: the page Glows and animations is under Action bars, right after Swing timers", page ~= nil and page.parent == "actionbars" and page.owner == "actionbars" and page.label == "Glows and animations" and at.effects == at.swing + 1)
		local proc = rows["actionbars.proc"]
		check("abfx: Proc glow is a choice of Game glow, Coloured border and None that starts on Game glow", proc ~= nil and proc.kind == "choice" and proc.default == "game" and proc.label == "Proc glow"
			and #proc.choices == 3 and proc.choices[1][1] == "game" and proc.choices[1][2] == "Game glow" and proc.choices[2][1] == "border" and proc.choices[2][2] == "Coloured border"
			and proc.choices[3][1] == "off" and proc.choices[3][2] == "None" and section["actionbars.proc"] == "Glows and animations")
		local colour = rows["actionbars.procColour"]
		check("abfx: Proc border colour is ffd100 and applies only to Coloured border", colour ~= nil and colour.kind == "colour" and colour.default == "ffffd100" and colour.label == "Proc border colour"
			and colour.needs == "proc" and colour.needsIn ~= nil and colour.needsIn[1] == "border" and #colour.needsIn == 1)
		local ok = true
		for path, label in pairs({ ["actionbars.assist"] = "Rotation helper highlight", ["actionbars.castAnim"] = "Cast fill animation", ["actionbars.interruptAnim"] = "Interrupt flash",
			["actionbars.abilityArt"] = "Extra button artwork" }) do
			local row = rows[path]
			ok = ok and row ~= nil and row.kind == "bool" and row.default == true and row.label == label
		end
		check("abfx: the four switches start on and have their names", ok)
		local allChanged = true
		for _, row in pairs(rows) do
			allChanged = allChanged and row.changed == "ButtonEffectsChanged"
		end
		check("abfx: Extra button artwork is under Extra action button, and every row calls ButtonEffectsChanged, which exists", section["actionbars.abilityArt"] == "Extra action button"
			and allChanged and type(W.ns.ButtonEffectsChanged) == "function")
		local steps, found = W.ns.SETUP_STEPS, nil
		for number, step in ipairs(steps) do
			if step.id == "ab-effects" then
				found = number
			end
		end
		check("abfx: the wizard has the step Glows and animations right after Button colours and cooldowns, built, with the six settings", found ~= nil and steps[found - 1].id == "ab-colours" and steps[found].title == "Glows and animations"
			and steps[found].area == "Action bars" and steps[found].built == true and #steps[found].rows == 6, tostring(found))
		check("abfx: it is no module", #W.ns.MODULE_ORDER == 22)
		local toc = {}
		for line in io.open(ADDON_DIR .. "/FlatUI.toc", "rb"):read("*a"):gmatch("[^\r\n]+") do
			if line:match("%.lua$") then
				toc[#toc + 1] = line
			end
		end
		local glow
		for i, file in ipairs(toc) do
			if file == "ProcGlow.lua" then
				glow = i
			end
		end
		check("abfx: ButtonEffects.lua compiles, and the TOC lists it right after ProcGlow.lua", loadfile(ADDON_DIR .. "/ButtonEffects.lua") ~= nil and glow ~= nil and toc[glow + 1] == "ButtonEffects.lua")
	end

	-- Game glow leaves the alert alone.
	do
		local W = X.world()
		local b = X.button(W, "ActionButton1")
		W.x.manager:ShowAlert(b)
		W.tick()
		check("abfx: Game glow: the alert keeps its alpha and no mark is asked for", W.x.alerts.ActionButton1.alpha == 1 and W.x.alerts.ActionButton1.sets == 0 and #X.marks(W, "ActionButton1") == 0)
		local control = X.world({ manager = false })
		check("abfx: the hooks are two more than without a manager, both on the manager table", W.hooks == control.hooks + 2 and W.wrappers[W.x.manager.ShowAlert] and W.wrappers[W.x.manager.HideAlert], W.hooks .. " " .. control.hooks)
	end

	-- None and Coloured border.
	for _, mode in ipairs({ "off", "border" }) do
		local W = X.world({ options = { ["actionbars.proc"] = mode, ["actionbars.procColour"] = "ff3366cc" } })
		local b = X.button(W, "ActionButton1")
		local label = mode == "off" and "None" or "Coloured border"
		local sets = W.x.alerts.ActionButton1.sets
		W.x.manager:ShowAlert(b)
		check("abfx: " .. label .. ": inside the game's call nothing is changed, the pass waits a frame", W.x.alerts.ActionButton1.sets == sets and #X.marks(W, "ActionButton1") == 0)
		W.tick()
		check("abfx: " .. label .. ": a frame later the game's alert is at alpha 0", W.x.alerts.ActionButton1.alpha == 0)
		local m = X.marks(W, "ActionButton1")
		if mode == "border" then
			check("abfx: Coloured border: the mark is asked for with source alert and the colour of the row", #m == 1 and near(m[1].r, 0.2, 1e-3) and near(m[1].g, 0.4, 1e-3) and near(m[1].b, 0.8, 1e-3), #m)
		else
			check("abfx: None: no mark is asked for", #m == 0)
		end
		check("abfx: " .. label .. ": an alert frame that is there already is at alpha 0 too, with no mark for a button that was not alerted", W.x.alerts.ActionButton2.alpha == 0 and #X.marks(W, "ActionButton2") == 0)
		W.x.manager:HideAlert(b)
		W.tick()
		m = X.marks(W, "ActionButton1")
		if mode == "border" then
			check("abfx: Coloured border: HideAlert takes the mark away", #m == 2 and m[2].r == nil)
		else
			check("abfx: None: HideAlert asks for nothing", #m == 0)
		end
		W.x.manager:ShowAlert(b)
		W.tick()
		W.ns.Set("actionbars.proc", "game")
		W.tick()
		check("abfx: " .. label .. ": switching to Game glow puts alpha 1 back", W.x.alerts.ActionButton1.alpha == 1)
		m = X.marks(W, "ActionButton1")
		check("abfx: " .. label .. ": and takes the mark away", (mode == "off" and #m == 0) or (mode == "border" and m[#m].r == nil), #m)
		clean(W, "abfx " .. mode)
	end

	-- A switch while an alert is up.
	do
		local W = X.world()
		local b = X.button(W, "ActionButton2")
		W.x.manager:ShowAlert(b)
		W.tick()
		W.ns.Set("actionbars.proc", "border")
		W.tick()
		local m = X.marks(W, "ActionButton2")
		check("abfx: switching to Coloured border while an alert is up draws the mark and fades the alert", #m == 1 and m[1].r ~= nil and W.x.alerts.ActionButton2.alpha == 0)
		W.ns.Set("actionbars.proc", "off")
		W.tick()
		m = X.marks(W, "ActionButton2")
		check("abfx: from Coloured border to None the mark goes and the alert stays at 0", m[#m].r == nil and W.x.alerts.ActionButton2.alpha == 0)
	end

	-- Buttons outside the list.
	do
		local W = X.world({ options = { ["actionbars.proc"] = "border" } })
		local fly = { SpellActivationAlert = X.region(), action = 1 }
		W.x.manager:ShowAlert(fly)
		W.x.manager:ShowAlert(nil)
		W.tick()
		local touched = false
		for _, entry in ipairs(W.x.log) do
			touched = touched or entry.button == fly
		end
		check("abfx: a button that is not one of the restyled action buttons is not touched", fly.SpellActivationAlert.sets == 0 and not touched)
		clean(W, "abfx outside")
	end

	-- Cast fill and interrupt flash.
	do
		local W = X.world({ options = { ["actionbars.castAnim"] = false, ["actionbars.interruptAnim"] = false } })
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.tick()
		check("abfx: Cast fill animation off and Interrupt flash off put the two frames at alpha 0 on every button", X.all(W, "cast", 0) and X.all(W, "interrupt", 0) and X.all(W, "alerts", 1))
		W.ns.Set("actionbars.castAnim", true)
		W.tick()
		check("abfx: Cast fill animation back on puts alpha 1 back, the flash stays off", X.all(W, "cast", 1) and X.all(W, "interrupt", 0))
		W.ns.Set("actionbars.interruptAnim", true)
		W.tick()
		check("abfx: Interrupt flash back on puts alpha 1 back", X.all(W, "interrupt", 1))
		-- the game gives a button its frames later
		local late = X.region()
		W.ns.Set("actionbars.castAnim", false)
		W.tick()
		W.buttons.ActionButton1.inner.SpellCastAnimFrame = late
		W.fire("UNIT_SPELLCAST_START", "player")
		check("abfx: UNIT_SPELLCAST_START changes nothing inside the event", late.alpha == 1)
		W.tick()
		check("abfx: a frame later the cast frame made after the switch is at alpha 0", late.alpha == 0)
		W.ns.Set("actionbars.interruptAnim", false)
		W.tick()
		local fresh = X.region()
		W.buttons.ActionButton2.inner.InterruptDisplay = fresh
		W.fire("UNIT_SPELLCAST_INTERRUPTED", "player")
		W.tick()
		check("abfx: UNIT_SPELLCAST_INTERRUPTED: a new interrupt frame is at alpha 0", fresh.alpha == 0)
		local slot = X.region()
		W.buttons.MultiBarBottomLeftButton1.inner.SpellCastAnimFrame = slot
		W.fire("ACTIONBAR_SLOT_CHANGED", 5)
		W.tick()
		check("abfx: ACTIONBAR_SLOT_CHANGED: a new cast frame is at alpha 0", slot.alpha == 0)
		clean(W, "abfx cast")
	end

	-- Rotation helper highlight.
	do
		local W = X.world({ registry = true, assist = true, options = { ["actionbars.assist"] = false } })
		local registry = W.x.registry
		local ev1, ev2 = registry.callbacks["AssistedCombatManager.RotationSpellsUpdated"], registry.callbacks["AssistedCombatManager.OnSetUseAssistedHighlight"]
		check("abfx: both callbacks of the assisted combat manager are registered, with one owner table of the addon", ev1 ~= nil and ev2 ~= nil and #ev1 == 1 and #ev2 == 1 and type(ev1[1].owner) == "table"
			and ev1[1].owner == ev2[1].owner)
		local frame = X.region()
		W.buttons.ActionButton1.inner.AssistedCombatRotationFrame = frame
		registry:TriggerEvent("AssistedCombatManager.RotationSpellsUpdated")
		check("abfx: the callback itself changes nothing", frame.alpha == 1)
		W.tick()
		check("abfx: Rotation helper highlight off: a frame later the rotation frame is at alpha 0", frame.alpha == 0)
		W.ns.Set("actionbars.assist", true)
		W.tick()
		check("abfx: Rotation helper highlight on again puts alpha 1 back", frame.alpha == 1)
		W.ns.Set("actionbars.assist", false)
		W.tick()
		local frame2 = X.region()
		W.buttons.ActionButton2.inner.AssistedCombatRotationFrame = frame2
		registry:TriggerEvent("AssistedCombatManager.OnSetUseAssistedHighlight")
		W.tick()
		check("abfx: OnSetUseAssistedHighlight: a second rotation frame is at alpha 0 too", frame2.alpha == 0 and frame.alpha == 0)
		check("abfx: no line when the game has a rotation helper", X.count(W, X.NO_ASSIST) == 0)
		local high = X.region()
		W.buttons.ActionButton1.inner.AssistedCombatHighlightFrame = high
		check("abfx: the highlight frame is registered for OnAssistedHighlightSpellChange with the same owner", #(registry.callbacks["AssistedCombatManager.OnAssistedHighlightSpellChange"] or {}) == 1
			and registry.callbacks["AssistedCombatManager.OnAssistedHighlightSpellChange"][1].owner == ev1[1].owner)
		registry:TriggerEvent("AssistedCombatManager.OnAssistedHighlightSpellChange")
		check("abfx: highlight: the callback itself changes nothing", high.alpha == 1)
		W.tick()
		check("abfx: highlight: Rotation helper highlight off puts the next spell highlight at alpha 0 a frame later", high.alpha == 0)
		W.ns.Set("actionbars.assist", true)
		W.tick()
		check("abfx: highlight: Rotation helper highlight on again puts it back at alpha 1", high.alpha == 1)
		clean(W, "abfx assist")
	end

	-- The lines.
	do
		local W = X.world({ options = { ["actionbars.assist"] = false, ["actionbars.abilityArt"] = false } })
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.tick()
		W.fire("ACTIONBAR_SLOT_CHANGED", 1)
		W.tick()
		check("abfx: Rotation helper highlight off with no frame and no C_AssistedCombat gives its line once", X.count(W, X.NO_ASSIST) == 1, W.status())
		check("abfx: Extra button artwork off with no extra action button gives its line once", X.count(W, X.NO_EXTRA) == 1, W.status())
		W.ns.Set("actionbars.assist", true)
		W.ns.Set("actionbars.abilityArt", true)
		W.tick()
		check("abfx: with the rows on again the two lines go", X.count(W, X.NO_ASSIST) == 0 and X.count(W, X.NO_EXTRA) == 0)
		local V = X.world({ assist = true, extra = true, options = { ["actionbars.assist"] = false, ["actionbars.abilityArt"] = false } })
		V.fire("PLAYER_ENTERING_WORLD", false, false)
		V.tick()
		check("abfx: with C_AssistedCombat and an extra action button there is no line", X.count(V, X.NO_ASSIST) == 0 and X.count(V, X.NO_EXTRA) == 0)
		local U = X.world()
		U.fire("PLAYER_ENTERING_WORLD", false, false)
		U.tick()
		check("abfx: at the defaults there is no line", X.count(U, X.NO_ASSIST) == 0 and X.count(U, X.NO_EXTRA) == 0)
	end

	-- The extra button's artwork.
	do
		local W = X.world({ extra = true, options = { ["actionbars.abilityArt"] = false } })
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.tick()
		check("abfx: Extra button artwork off puts the style of the extra button and of the zone ability at alpha 0", W.x.style.alpha == 0 and W.x.zone.alpha == 0)
		check("abfx: and never touches the alpha of ExtraActionBarFrame", W.x.frame.alpha == 1 and W.x.frame.sets == 0)
		W.ns.Set("actionbars.abilityArt", true)
		W.tick()
		check("abfx: Extra button artwork on again puts the styles back at alpha 1, the frame still untouched", W.x.style.alpha == 1 and W.x.zone.alpha == 1 and W.x.frame.sets == 0)
		local Z = X.world({ extra = true })
		Z.fire("PLAYER_ENTERING_WORLD", false, false)
		Z.tick()
		check("abfx: at the default the style is never touched", Z.x.style.sets == 0 and Z.x.zone.sets == 0 and Z.x.frame.sets == 0)
	end

	-- The probes.
	do
		local W = X.world({ manager = false })
		local V = X.world({ manager = "half", options = { ["actionbars.proc"] = "off" } })
		check("abfx: a manager without HideAlert: nothing is hooked and the alerts stay", V.hooks == W.hooks and X.all(V, "alerts", 1), V.hooks .. " " .. W.hooks)
		check("abfx: with no manager the alerts stay too", X.all(X.world({ manager = false, options = { ["actionbars.proc"] = "off" } }), "alerts", 1))
		local R = X.world({ refuse = true, options = { ["actionbars.proc"] = "border" } })
		local b = X.button(R, "ActionButton1")
		R.x.manager:ShowAlert(b)
		R.tick()
		check("abfx: a refused SetAlpha gives Proc glow: the game refused the change, once", X.count(R, X.REFUSED) == 1, R.status())
		local m = X.marks(R, "ActionButton1")
		check("abfx: and the border is not drawn, as with Game glow", #m == 0 or m[#m].r == nil)
		clean(R, "abfx refused")
	end

	-- A rotation alert is not given a border.
	do
		local W = X.world({ options = { ["actionbars.proc"] = "border" } })
		local b1, b2 = X.button(W, "ActionButton1"), X.button(W, "ActionButton2")
		W.x.manager:ShowAlert(b1, 2)
		W.x.manager:ShowAlert(b2)
		W.tick()
		check("abfx: abfx rotation alert: no border on a button whose alert is the rotation one, a border on the plain one", #X.marks(W, "ActionButton1") == 0 and #X.marks(W, "ActionButton2") == 1)
		clean(W, "abfx rotation alert")
	end

	-- Combat and reload.
	do
		local W = X.world({ options = { ["actionbars.proc"] = "border", ["actionbars.castAnim"] = false } })
		W.combat = true
		W.x.manager:ShowAlert(X.button(W, "ActionButton1"))
		W.tick()
		check("abfx: in a fight the alert is faded and the mark asked for, and the cast frame is at 0", W.x.alerts.ActionButton1.alpha == 0 and #X.marks(W, "ActionButton1") == 1 and X.all(W, "cast", 0))
		W.combat = false
		clean(W, "abfx combat")
		local V = X.world({ options = { ["actionbars.proc"] = "off" } })
		V.x.manager:ShowAlert(X.button(V, "ActionButton1"))
		V.tick()
		check("abfx: after a reload the saved row is applied", V.x.alerts.ActionButton1.alpha == 0)
	end
end
-- >>> abfx (end)
-- >>> taintscan (begin)
-- The scan of the click path after a call the game refused (taintscan:, TaintScan.lua). The simulated issecurevariable names the add-on marked per table and key.
do
	local X = { marks = setmetatable({}, { __mode = "k" }) }
	function X.mark(owner, key, addon)
		X.marks[owner] = X.marks[owner] or {}
		X.marks[owner][key] = addon
	end
	-- The game tables of the click path, plain, with a counter on every read through a missing key and every new key written.
	function X.world()
		local W = newWorld()
		local env = W.env
		X.marks = setmetatable({}, { __mode = "k" })
		W.touch = { reads = 0, writes = 0 }
		local function watched(t)
			return setmetatable(t, { __index = function() W.touch.reads = W.touch.reads + 1 end, __newindex = function(self, k, v) W.touch.writes = W.touch.writes + 1; rawset(self, k, v) end })
		end
		W.game = {
			bar = watched({ actionButtons = {}, Show = function() end, Hide = function() end }),
			mixin = watched({ OnClick = function() end, CalculateAction = function() end, Extra = function() end }),
			derived = watched({ OnPostClick = function() end }),
			settings = watched({ a = 1, b = 2, c = 3 }),
			globals = { ActionButtonDown = function() end, ActionButtonUp = function() end, ACTION_HIGHLIGHT_MARKS = {} },
		}
		env.MainActionBar = W.game.bar
		env.ActionBarActionButtonMixin = W.game.mixin
		env.ActionBarActionButtonDerivedMixin = W.game.derived
		env.SettingsPanel = { settings = W.game.settings }
		W.game.Settings = watched({ GetValue = function() end })
		W.game.C_ActionBar = watched({ IsAutoCastPetAction = function() end })
		env.Settings, env.C_ActionBar = W.game.Settings, W.game.C_ActionBar
		env.IsModifiedClick, env.SecureButton_GetModifiedAttribute = function() end, function() end
		for name, value in pairs(W.game.globals) do
			env[name] = value
		end
		env.issecurevariable = function(owner, key)
			local by = X.marks[owner] and X.marks[owner][key]
			if by then
				return false, by
			end
			return true, nil
		end
		env.time = function() return 1000 + math.floor(W.now) end
		env.date = function(format) return format == "%Y-%m-%d %H:%M:%S" and "2026-10-13 12:00:00" or "12:00:00" end
		env.GetTime = function() return W.now end
		env.GetMouseFoci = function() return {} end
		W.login()
		return W
	end
	-- The event is raised from inside the refused call; the scan runs on the next frame.
	function X.fire(W, event, addon, call)
		W.fire(event, addon, call)
		W.tick()
	end
	function X.tainted(W)
		local out = {}
		for line in W.status():gmatch("[^\n]+") do
			local name = line:match("^Tainted: (.+)$")
			if name then
				out[#out + 1] = name
			end
		end
		table.sort(out)
		return table.concat(out, "|")
	end
	function X.snapshot(W)
		local parts = {}
		for _, t in ipairs({ W.game.bar, W.game.mixin, W.game.derived, W.game.settings, W.game.Settings, W.game.C_ActionBar }) do
			local keys = {}
			for k, v in next, t do
				keys[#keys + 1] = tostring(k) .. "=" .. tostring(v)
			end
			table.sort(keys)
			parts[#parts + 1] = table.concat(keys, ",")
		end
		return table.concat(parts, ";")
	end
	function X.saved(W)
		return W.env.FlatUIDB.taintScans or {}
	end

	-- Nothing marked: every button is checked and the scan says so.
	do
		local W = X.world()
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		local status = W.status()
		check("taintscan: nothing tainted says so, after the blocked line", has(status, "Blocked by the game: UseAction() (forbidden)\nUseAction() forbidden at 2026-10-13 12:00:00\nNo tainted value found.\nChecked: 96 buttons, 1 bar, 30 globals, 2 mixins, 3 settings."), status)
		check("taintscan: and no Tainted line", X.tainted(W) == "")
		clean(W, "taintscan none")
	end

	-- Exactly the marked values are named, with the add-on.
	do
		local W = X.world()
		local b1, b3 = W.env.ActionButton1, W.env.ActionButton3
		X.mark(b1, "bar", "FlatUI")
		X.mark(b3, "OnClick", "OtherAddon")
		X.mark(b3, "popup", "FlatUI")
		X.mark(W.game.bar, "Show", "OtherAddon")
		X.mark(W.env, "ActionButtonDown", "OtherAddon")
		X.mark(W.game.mixin, "Extra", "Third")
		X.mark(W.game.derived, "OnPostClick", "FlatUI")
		X.mark(W.game.settings, "a", "FlatUI")
		X.mark(W.game.settings, "c", "Foo")
		X.mark(b1, "NotInTheList", "FlatUI")
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: the scan names exactly the marked values and the add-on that changed each",
			X.tainted(W) == "ActionBarActionButtonDerivedMixin.OnPostClick by FlatUI|ActionBarActionButtonMixin.Extra by Third|ActionButton1.bar by FlatUI|ActionButton3.OnClick by OtherAddon|ActionButton3.popup by FlatUI|ActionButtonDown by OtherAddon|MainActionBar.Show by OtherAddon|SettingsPanel.settings (2 of 3 keys) by FlatUI, Foo", X.tainted(W))
		check("taintscan: a value outside the lists is not checked", not has(W.status(), "NotInTheList"))
		check("taintscan: a tainted value with no add-on named is unknown", (function()
			local V = X.world()
			V.env.issecurevariable = function(_, key) if key == "bar" then return false, nil end return true end
			X.fire(V, "ADDON_ACTION_BLOCKED", "FlatUI", "SetPoint()")
			return has(V.status(), "Tainted: ActionButton1.bar by unknown") and has(V.status(), "SetPoint() blocked at 2026-10-13 12:00:00")
		end)())
		local saved = X.saved(W)[1]
		check("taintscan: the result is saved with the time, the function, the kind and each name with its add-on", #X.saved(W) == 1 and saved.at == 1000 and saved.call == "UseAction()" and saved.kind == "forbidden"
			and #saved.tainted == 8 and type(saved.tainted[1].name) == "string" and type(saved.tainted[1].by) == "string" and saved.settingsTainted == 2 and saved.settings == 3)
		clean(W, "taintscan marked")
	end

	-- The listed values of every button, and every key of the button under the cursor, found through its child too.
	do
		local W = X.world()
		local b1, b2 = W.env.ActionButton1, W.env.ActionButton2
		X.mark(b1, "bar", "FlatUI")
		X.mark(b2, "popup", "FlatUI")
		rawset(b1, "Spare", 1)
		rawset(b2, "Spare", 1)
		X.mark(b1, "Spare", "Other")
		X.mark(b2, "Spare", "Other")
		W.env.GetMouseFoci = function() return { b2 } end
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: with a button under the cursor its every key is checked and the listed values of the other buttons are too", X.tainted(W) == "ActionButton1.bar by FlatUI|ActionButton2.Spare by Other|ActionButton2.popup by FlatUI"
			and has(W.status(), "Checked: 96 buttons, ActionButton2 under the cursor with "), X.tainted(W))
		check("taintscan: and the key count of that button is kept", type(X.saved(W)[1].keys) == "number" and X.saved(W)[1].keys >= 1 and X.saved(W)[1].buttons == 96)
		local child = { GetParent = function() return b1 end }
		W.advance(10)
		W.env.GetMouseFoci = function() return { child } end
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: a frame on the button leads to the button", X.saved(W)[2].clicked == "ActionButton1" and X.saved(W)[2].buttons == 96)
		W.advance(10)
		W.env.GetMouseFoci = function() return { { GetParent = function() return nil end } } end
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: a frame that is no button leaves the listed values of every button checked and no key", X.saved(W)[3].clicked == nil and X.saved(W)[3].buttons == 96
			and X.saved(W)[3].keys == 0 and (function()
				local names = {}
				for _, item in ipairs(X.saved(W)[3].tainted) do
					names[#names + 1] = item.name
				end
				table.sort(names)
				return table.concat(names, "|") == "ActionButton1.bar|ActionButton2.popup"
			end)())
		-- The mouse rests on another button than the one named by the refused call's neighbours: the scan keeps all 96 and reads the hovered one's keys.
		local V = X.world()
		X.mark(V.env.MultiBarLeftButton7, "popup", "FlatUI")
		V.env.GetMouseFoci = function() return { V.env.ActionButton1 } end
		X.fire(V, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: a key press with the mouse on another button still checks the buttons of every bar", X.tainted(V) == "MultiBarLeftButton7.popup by FlatUI", X.tainted(V))
	end

	-- The scan waits for the next frame, and the button under the cursor is read when the event comes.
	do
		local W = X.world()
		local b1, b2 = W.env.ActionButton1, W.env.ActionButton2
		rawset(b1, "Spare", 1)
		rawset(b2, "Spare", 1)
		X.mark(b1, "Spare", "Other")
		X.mark(b2, "Spare", "Other")
		W.env.GetMouseFoci = function() return { b1 } end
		W.fire("ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		W.env.GetMouseFoci = function() return { b2 } end
		check("taintscan: nothing is scanned inside the refused call", #X.saved(W) == 0 and not has(W.status(), " at 2026-"))
		W.fire("ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		W.tick()
		check("taintscan: the next frame scans once, for the button that was under the cursor then", #X.saved(W) == 1 and X.saved(W)[1].clicked == "ActionButton1" and X.tainted(W) == "ActionButton1.Spare by Other", X.tainted(W))
		local V = X.world()
		V.env.C_Timer = nil
		X.fire(V, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: without C_Timer the scan is made at once", #X.saved(V) == 1)
	end

	-- A value the path reads by name in the game's own code is marked: Settings, IsModifiedClick, SecureButton_GetModifiedAttribute and the keys the path calls.
	do
		local W = X.world()
		X.mark(W.env, "Settings", "A")
		X.mark(W.env, "IsModifiedClick", "B")
		X.mark(W.env, "SecureButton_GetModifiedAttribute", "C")
		X.mark(W.game.Settings, "GetValue", "D")
		X.mark(W.game.C_ActionBar, "IsAutoCastPetAction", "E")
		X.mark(W.env, "UseAction", "F")
		X.mark(W.env, "GetCursorInfo", "G")
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: Settings, IsModifiedClick, SecureButton_GetModifiedAttribute, UseAction, GetCursorInfo and the keys GetValue and IsAutoCastPetAction are named",
			X.tainted(W) == "C_ActionBar.IsAutoCastPetAction by E|GetCursorInfo by G|IsModifiedClick by B|SecureButton_GetModifiedAttribute by C|Settings by A|Settings.GetValue by D|UseAction by F", X.tainted(W))
		check("taintscan: every global of the mouse path is in the list", (function()
			local V = X.world()
			local names = { "KeybindFrames_InQuickKeybindMode", "C_ActionBar", "Settings", "IsModifiedClick", "GetCursorInfo", "SecureButton_GetModifiedAttribute",
				"SecureButton_GetModifierPrefix", "SecureButton_GetButtonSuffix", "ATTRIBUTE_NOOP", "SecureButton_GetAttribute", "SecureActionButton_ShouldUseOnKeyDown",
				"GetCVarBool", "securecallfunction", "GetActionInfo", "UseAction" }
			for _, name in ipairs(names) do
				X.mark(V.env, name, "Z")
			end
			X.fire(V, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
			return #X.saved(V)[1].tainted == #names, #X.saved(V)[1].tainted
		end)())
	end

	-- The last three, and a repeat of the same call within seconds.
	do
		local W = X.world()
		for index = 1, 4 do
			X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "Call" .. index .. "()")
		end
		local saved = X.saved(W)
		check("taintscan: three results are kept, the oldest dropped", #saved == 3 and saved[1].call == "Call2()" and saved[3].call == "Call4()", #saved)
		check("taintscan: the status shows all three", has(W.status(), "Call2() forbidden at") and has(W.status(), "Call3() forbidden at") and has(W.status(), "Call4() forbidden at") and not has(W.status(), "Call1() forbidden at"))
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "Call4()")
		check("taintscan: the same call again at once is counted and not scanned again", #X.saved(W) == 3 and X.saved(W)[3].call == "Call4()" and W.ns.BlockedTotal() == 5 and X.saved(W)[2].call == "Call3()")
		W.advance(6)
		X.fire(W, "ADDON_ACTION_BLOCKED", "FlatUI", "Call4()")
		check("taintscan: and scanned again after a few seconds, a blocked call kept as blocked", #X.saved(W) == 3 and X.saved(W)[3].kind == "blocked" and X.saved(W)[2].call == "Call4()" and X.saved(W)[2].kind == "forbidden")
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "SomeOtherAddon", "Other()")
		check("taintscan: a call of another add-on is not scanned", #X.saved(W) == 3 and X.saved(W)[3].call == "Call4()")
		local many = X.world()
		for index = 1, 12 do
			X.mark(many.env["ActionButton" .. index], "popup", "A")
		end
		for index = 1, 3 do
			X.mark(many.env["MultiBarLeftButton" .. index], "popup", "A")
		end
		X.fire(many, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		local lines = 0
		for _ in many.status():gmatch("Tainted: ") do
			lines = lines + 1
		end
		check("taintscan: a long result shows twelve lines and the count of the rest", lines == 12 and has(many.status(), "3 more tainted values."), lines)
	end

	-- Every value the click path reads is checked, by name, on a button, its bar, the globals and the mixins.
	do
		local W = X.world()
		local mixed = { OnClick = 1 }
		W.env.SecureActionButtonMixin = setmetatable(mixed, { __index = function() W.touch.reads = W.touch.reads + 1 end })
		local button, expected = W.env.ActionButton1, {}
		local function mark(label, owner, names, by)
			for _, name in ipairs(names) do
				X.mark(owner, name, by)
				expected[#expected + 1] = label .. "." .. name .. " by " .. by
			end
		end
		mark("ActionButton1", button, { "popup", "bar", "isExtra", "buttonType", "action", "NewActionTexture", "flashing" }, "A")
		mark("ActionButton1", button, { "GetID", "CalculateAction", "GetAttribute", "GetButtonState", "SetButtonState", "UpdateState", "UpdateHighlightMark", "Update",
			"UpdateAction", "UpdateFlyout", "UpdatePressAndHoldAction", "OnClick" }, "A")
		mark("MainActionBar", W.game.bar, { "actionButtons", "shownButtonContainers", "isShownExternal", "showAllButtons", "flyoutDirection", "GetAttribute",
			"UpdateShownButtons", "UpdateDividers", "Show", "Hide", "SetShown", "IsShown", "ShowBase", "HideBase", "SetShownBase" }, "B")
		for _, name in ipairs({ "ActionButtonDown", "ActionButtonUp", "MultiActionButtonDown", "MultiActionButtonUp", "TryUseActionButton", "GetActionButtonForID",
			"SecureActionButton_OnClick", "SpellFlyout", "OverrideActionBar", "PetBattleFrame", "ACTION_HIGHLIGHT_MARKS", "ON_BAR_HIGHLIGHT_MARKS", "MacroFrame_SaveMacro",
			"ActionBarActionButtonDerivedMixin_OnClick", "KeybindFrames_InQuickKeybindMode", "C_ActionBar", "Settings", "IsModifiedClick", "GetCursorInfo",
			"SecureButton_GetModifiedAttribute", "SecureButton_GetModifierPrefix", "SecureButton_GetButtonSuffix", "ATTRIBUTE_NOOP", "SecureButton_GetAttribute",
			"SecureActionButton_ShouldUseOnKeyDown", "GetCVarBool", "securecallfunction", "SaveMacro", "GetActionInfo", "UseAction" }) do
			X.mark(W.env, name, "C")
			expected[#expected + 1] = name .. " by C"
		end
		mark("C_ActionBar", W.game.C_ActionBar, { "IsAutoCastPetAction" }, "G")
		mark("Settings", W.game.Settings, { "GetValue" }, "G")
		-- Every key of the button under the cursor, the listed ones aside.
		local hovered = W.env.ActionButton5
		rawset(hovered, "KeyOne", 1)
		rawset(hovered, 7, 1)
		mark("ActionButton5", hovered, { "KeyOne", 7 }, "H")
		W.env.GetMouseFoci = function() return { hovered } end
		mark("ActionBarActionButtonMixin", W.game.mixin, { "OnClick", "CalculateAction", "GetID", "GetAttribute", "GetButtonState", "SetButtonState", "UpdateState",
			"UpdateHighlightMark", "Update", "UpdateAction", "UpdateFlyout", "UpdatePressAndHoldAction", "TriggerSecureClick" }, "D")
		mark("ActionBarActionButtonDerivedMixin", W.game.derived, { "OnClick", "TriggerSecureClick" }, "E")
		mark("SecureActionButtonMixin", mixed, { "OnClick", "CalculateAction" }, "F")
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		local got = {}
		for _, item in ipairs(X.saved(W)[1].tainted) do
			got[#got + 1] = item.name .. " by " .. item.by
		end
		table.sort(got)
		table.sort(expected)
		check("taintscan: every field, method, global and mixin key the press reads is checked, and nothing else is named", table.concat(got, "|") == table.concat(expected, "|"), #got .. " of " .. #expected)
		check("taintscan: and the three mixins are counted", X.saved(W)[1].mixins == 3)
	end

	-- The command prints the same scan and keeps nothing.
	do
		local W = X.world()
		X.mark(W.env.ActionButton1, "bar", "FlatUI")
		local out = W.slash("taint")
		check("taintscan: /flatui taint prints the scan", has(out, "Click path now:\nTainted: ActionButton1.bar by FlatUI\nChecked: 96 buttons"), out)
		check("taintscan: and keeps nothing", #X.saved(W) == 0 and not has(W.status(), " at 2026-"))
		check("taintscan: and with nothing marked says so", (function()
			local V = X.world()
			return has(V.slash("taint"), "Click path now:\nNo tainted value found.")
		end)())
		check("taintscan: the help lists the command", has(W.slash("help"), "/flatui taint"))
	end

	-- No game table is touched.
	do
		local W = X.world()
		X.mark(W.game.bar, "Show", "FlatUI")
		X.mark(W.game.settings, "a", "FlatUI")
		local before = X.snapshot(W)
		W.touch.reads, W.touch.writes = 0, 0
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		W.slash("taint")
		check("taintscan: no game table is written, and none is read for a value", X.snapshot(W) == before and W.touch.writes == 0 and W.touch.reads == 0, W.touch.reads .. "/" .. W.touch.writes)
	end

	-- Missing and failing APIs.
	do
		local W = X.world()
		W.env.issecurevariable = nil
		X.fire(W, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: without issecurevariable nothing is kept and the status has no scan line", #X.saved(W) == 0 and not has(W.status(), " at 2026-") and has(W.status(), "Blocked by the game: UseAction() (forbidden)"))
		check("taintscan: and the command says the game has none", has(W.slash("taint"), "Taint scan: this game has no issecurevariable."))
		check("taintscan: with no error", #W.errors == 0 and #W.violations == 0)
		local V = X.world()
		V.env.GetMouseFoci, V.env.GetTime, V.env.time, V.env.date, V.env.SettingsPanel = nil, nil, nil, nil, nil
		V.env.ActionBarActionButtonMixin, V.env.MainActionBar, V.env.ActionButtonDown = nil, nil, nil
		X.mark(V.env.ActionButton1, "bar", "FlatUI")
		X.fire(V, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: without the mouse, the clock, the settings panel, a mixin or a bar the rest is still scanned", X.tainted(V) == "ActionButton1.bar by FlatUI" and #X.saved(V) == 1 and X.saved(V)[1].at == 0
			and has(V.status(), "UseAction() forbidden at unknown time") and has(V.status(), "Checked: 96 buttons, 0 bars, 30 globals, 1 mixin."), V.status())
		local U = X.world()
		U.env.issecurevariable = function() error("refused", 0) end
		U.env.GetMouseFoci = function() error("refused", 0) end
		X.fire(U, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: calls that raise find nothing and raise nothing", X.tainted(U) == "" and #X.saved(U) == 1 and #U.errors == 0 and #U.violations == 0, tostring(#U.errors))
		local Q = X.world()
		Q.env.GetMouseFoci = function() return SECRET end
		Q.env.issecurevariable = function() return SECRET, SECRET end
		X.fire(Q, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: secret answers count as nothing", X.tainted(Q) == "" and #Q.errors == 0 and #X.saved(Q) == 1)
		local R = newWorld()
		R.login()
		X.fire(R, "ADDON_ACTION_FORBIDDEN", "FlatUI", "UseAction()")
		check("taintscan: a world without any of it keeps the old status", #X.saved(R) == 0 and has(R.status(), "Blocked by the game: UseAction() (forbidden)") and R.status():match("Blocked by the game[^\n]*$") ~= nil and #R.errors == 0)
	end
end
