-- >>> ownsim (begin)
-- The simulated client layer of Flat UI's own action buttons (ownsim:, TOC.own). These tests prove the harness: a click is refused after an insecure write
-- on the path and accepted on a clean button, drivers, watchers, bindings, the game's bars and the cooldown rules behave as the client files say.
do
	local function world() return newWorld({ own = true }) end
	-- A button made by hand: a header sets its attributes as secure code and the mouse fires on release.
	local function hand(W, name, slot, clean)
		local env = W.env
		local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
		local button = env.CreateFrame("Button", name, env.UIParent, "SecureActionButtonTemplate")
		header:SetFrameRef("b", button)
		header:Execute(("local b = self:GetFrameRef('b') b:SetAttribute('type', 'action') b:SetAttribute('action', %d) %s"):format(slot, clean and "b:SetAttribute('useOnKeyDown', false)" or ""))
		button:RegisterForClicks("AnyUp")
		return button, header
	end

	-- The world: eight game bars, a container and a button each, all shown.
	do
		local W = world()
		local env = W.env
		check("ownsim: eight game bars, twelve containers and twelve buttons each", #W.gameBarList == 8 and #W.gameBars.MultiBar7.containers == 12 and #W.gameBars.MainActionBar.twins == 12)
		check("ownsim: a button's parent is its container, and the container's is the bar", W.rawOf[env.ActionButton3].parent == W.gameBars.MainActionBar.containers[3]
			and W.rawOf[W.gameBars.MainActionBar.containers[3]].parent == env.MainActionBar and W.rawOf[env.ActionButton3].container == W.gameBars.MainActionBar.containers[3])
		check("ownsim: every game bar is shown and the override bar is not", env.MultiBar6:IsShown() and env.MainActionBar:IsShown() and not env.OverrideActionBar:IsShown())
		check("ownsim: the twins' slots are those of the bars", W.rawOf[env.ActionButton3].action == 3 and W.rawOf[env.MultiBarBottomLeftButton1].action == 61 and W.rawOf[env.MultiBarRightButton12].action == 36
			and W.rawOf[env.MultiBar7Button12].action == 180, tostring(W.rawOf[env.MultiBar7Button12].action))
		check("ownsim: nothing is recorded as an add-on's write at the start", #W.gameWritesByAddon() == 0 and #W.used == 0 and #W.refused == 0 and #W.violations == 0)
	end

	-- A hand-made secure button: the mouse fires on release only with useOnKeyDown off, and a clean field casts.
	do
		local W = world()
		local b = hand(W, "OwnSimHand", 5, true)
		check("ownsim: a clean secure button casts its slot on a click", W.click("OwnSimHand") == true and #W.used == 1 and W.used[1].slot == 5 and W.used[1].button == "LeftButton" and W.used[1].frame == "OwnSimHand")
		check("ownsim: a mouse click is not a key press", W.used[1].isKeyPress == nil and #W.refused == 0)
		hand(W, "OwnSimKeyDown", 6, false)
		check("ownsim: with the key-down option and clicks on release only, nothing casts", W.click("OwnSimKeyDown") == false and #W.used == 1)
		W.ownCVars.ActionButtonUseKeyDown = false
		check("ownsim: with that option off the same button casts on release", W.click("OwnSimKeyDown") == true and W.used[2].slot == 6)
		b:RegisterForClicks("AnyDown")
		W.click("OwnSimHand")
		check("ownsim: with useOnKeyDown off a button registered for the down edge only never fires", #W.used == 2 and #W.refused == 0, #W.used)
		b:RegisterForClicks("AnyDown", "AnyUp")
		W.click("OwnSimHand")
		check("ownsim: registered for both edges it fires once, on the release", #W.used == 3 and #W.refused == 0, #W.used)
		check("ownsim: a hidden button and a button with the mouse off take no click", (function()
			b:Hide()
			local hidden = W.click("OwnSimHand")
			b:Show()
			W.runSecure(function() b:EnableMouse(false) end)
			local off, why = W.click("OwnSimHand")
			return hidden == false and off == false and why == "mouse off" and #W.used == 3
		end)())
	end

	-- The same button after an insecure write of a field the click reads.
	do
		local W = world()
		local b = hand(W, "OwnSimTaint", 7, true)
		check("ownsim: before the write the field is secure", select(1, W.env.issecurevariable(b, "popup")) == true)
		b.popup = W.env.CreateFrame("Frame")
		check("ownsim: the write is listed with its key and as not secure", W.fieldWrites[#W.fieldWrites].key == "popup" and W.fieldWrites[#W.fieldWrites].secure == false
			and W.fieldWrites[#W.fieldWrites].button == "OwnSimTaint" and W.fieldWrites[#W.fieldWrites].by == "addon")
		local secure, by = W.env.issecurevariable(b, "popup")
		check("ownsim: issecurevariable names the add-on", secure == false and by == "FlatUI")
		check("ownsim: a click that read the written field is refused, not used", W.click("OwnSimTaint") == false and #W.used == 0 and #W.refused == 1 and W.refused[1].slot == 7
			and W.refused[1].reason:find("popup", 1, true) ~= nil, tostring(W.refused[1] and W.refused[1].reason))
		check("ownsim: the refused call raises the game's event for the add-on", (function()
			local seen
			local frame = W.env.CreateFrame("Frame")
			frame:RegisterEvent("ADDON_ACTION_FORBIDDEN")
			frame:SetScript("OnEvent", function(_, _, addon, call) seen = addon .. "/" .. call end)
			W.click("OwnSimTaint")
			return seen == "FlatUI/UseAction()"
		end)())
		W.runSecure(function() b.popup = nil end)
		check("ownsim: the same field written by secure code is clean again and the click casts", select(1, W.env.issecurevariable(b, "popup")) == true and W.click("OwnSimTaint") == true and #W.used == 1)
		b.isExtra = true
		check("ownsim: isExtra, buttonType and bar count the same", W.click("OwnSimTaint") == false)
		W.runSecure(function() b.isExtra = nil end)
		b.bar = {}
		b.bar = nil
		b.bar = {}
		check("ownsim: a field written twice is recorded twice", (function()
			local n = 0
			for _, w in ipairs(W.fieldWrites) do
				if w.key == "bar" then n = n + 1 end
			end
			return n == 3
		end)())
		check("ownsim: a call into UseAction outside a click is refused", (function() W.env.UseAction(3) return W.refused[#W.refused].reason == "called from outside a click" end)())
		check("ownsim: Click() from add-on code is a tainted click", (function()
			W.runSecure(function() b.bar = nil end)
			local used, refused = #W.used, #W.refused
			b:Click("LeftButton", false)
			return #W.used == used and #W.refused == refused + 1 and W.refused[#W.refused].reason == "the click was started by add-on code"
		end)())
	end

	-- A button of the game's template: the OnLoad writes popup under the caller's taint, a secure type resets it.
	do
		local W = world()
		local env = W.env
		W.slots[1].flyout = 9
		local b = env.CreateFrame("CheckButton", "OwnSimFlat1", env.UIParent, "ActionButtonTemplate, SecureActionButtonTemplate")
		check("ownsim: the template string is kept and the ID is 0", b.templateString == "ActionButtonTemplate, SecureActionButtonTemplate" and b:GetID() == 0 and W.own.OwnSimFlat1 == b and W.own[1] == b)
		check("ownsim: its regions are the template's, by key", b.icon and b.Count and b.Name and b.HotKey and b.Border and b.SlotArt and b.SlotBackground and b.NormalTexture and b.PushedTexture
			and b.HighlightTexture and b.CheckedTexture and b.cooldown and b.chargeCooldown and b.lossOfControlCooldown and b.SpellCastAnimFrame and b.InterruptDisplay and b.HotKey:GetObjectType() == "FontString")
		check("ownsim: its OnClick is the secure one", b:GetScript("OnClick") == env.SecureActionButton_OnClick)
		local secure, by = env.issecurevariable(b, "popup")
		check("ownsim: slot 1 holding a flyout leaves popup written by the add-on's CreateFrame", b.popup == env.SpellFlyout and secure == false and by == "FlatUI")
		check("ownsim: the template's write is listed as the template's, not the add-on's", (function()
			for _, w in ipairs(W.fieldWrites) do
				if w.by == "addon" then return false end
			end
			return W.fieldWrites[1].key == "popup" and W.fieldWrites[1].by == "template" and W.fieldWrites[1].secure == false
		end)(), (function() local o = {} for _, w in ipairs(W.fieldWrites) do o[#o + 1] = w.key .. "/" .. w.by end return table.concat(o, ",") end)())
		local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
		header:SetFrameRef("b", b)
		header:Execute("local b = self:GetFrameRef('b') b:SetAttribute('type', 'none') b:SetAttribute('useOnKeyDown', false) b:SetAttribute('action', 4) b:SetAttribute('type', 'action')")
		b:RegisterForClicks("AnyUp")
		check("ownsim: a secure type reset clears popup, written by secure code", b.popup == nil and select(1, env.issecurevariable(b, "popup")) == true)
		check("ownsim: its attribute writes are all secure and in order", (function()
			local keys = {}
			for _, w in ipairs(W.attributeWrites) do
				if w.button == "OwnSimFlat1" then
					if not w.secure then return false end
					keys[#keys + 1] = w.key .. "=" .. tostring(w.value)
				end
			end
			return table.concat(keys, " ") == "type=none useOnKeyDown=false action=4 type=action"
		end)())
		check("ownsim: the button then casts its slot", W.click("OwnSimFlat1") and W.used[1].slot == 4 and #W.refused == 0)
		W.slots[4].flyout = 12
		header:Execute("local b = self:GetFrameRef('b') b:SetAttribute('action', 4) b:SetAttribute('action', 5) b:SetAttribute('action', 4)")
		check("ownsim: a flyout slot toggles the spell flyout on the button and calls no UseAction", (function()
			local used = #W.used
			W.click("OwnSimFlat1")
			return #W.used == used and W.flyoutOn() == "OwnSimFlat1" and W.flyouts[#W.flyouts].flyoutId == 12 and W.rawOf[env.SpellFlyout].parent == b
		end)())
		check("ownsim: the flyout follows a slot that holds one, through the attribute change", b.popup == env.SpellFlyout and select(1, env.issecurevariable(b, "popup")) == true)
		check("ownsim: a second click closes it", (function() W.click("OwnSimFlat1") return W.flyoutOn() == nil end)())
		check("ownsim: ActionBarButtonTemplate is a violation", (function()
			local ok = pcall(env.CreateFrame, "CheckButton", "OwnSimBad", env.UIParent, "ActionBarButtonTemplate, SecureActionButtonTemplate")
			return not ok and W.violations[#W.violations]:find("ActionBarButtonTemplate", 1, true) ~= nil
		end)())
		check("ownsim: a script on a secure frame and a hook on OnShow are violations", (function()
			local a = pcall(b.SetScript, b, "OnClick", function() end)
			local c = pcall(b.HookScript, b, "OnShow", function() end)
			local d = pcall(b.HookScript, b, "PostClick", function() end)
			return not a and not c and d
		end)())
	end
end
-- >>> ownsim (end)
-- >>> ownsim bars (begin)
-- The game's bars, drivers, watchers, bindings, wrap scripts, the cursor, the cooldown rules and the engine of the simulated client layer (ownsim:).
do
	local function world() return newWorld({ own = true }) end
	local function hand(W, name, slot)
		local env = W.env
		local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
		local button = env.CreateFrame("Button", name, env.UIParent, "SecureActionButtonTemplate")
		header:SetFrameRef("b", button)
		header:Execute(("local b = self:GetFrameRef('b') b:SetAttribute('type', 'action') b:SetAttribute('action', %d) b:SetAttribute('useOnKeyDown', false)"):format(slot))
		button:RegisterForClicks("AnyUp")
		return button, header
	end
	local function shown(W, first, last)
		local out = {}
		for index = first, last do
			out[#out + 1] = W.gameBarList[index].raw.shown and "1" or "0"
		end
		return table.concat(out)
	end

	-- A state driver runs its snippet when its value changes, and not without a change.
	do
		local W = world()
		local env = W.env
		local bar = env.CreateFrame("Frame", "OwnSimBar", env.UIParent, "SecureHandlerStateTemplate")
		bar:SetAttribute("_onstate-page", "self:SetAttribute('seen', (self:GetAttribute('seen') or 0) + 1) self:SetAttribute('page', newstate)")
		env.RegisterStateDriver(bar, "page", "[bar:2] 2; [bonusbar:1] b1; 1")
		check("ownsim: a driver sets its state at once and the snippet runs once", bar:GetAttribute("seen") == 1 and bar:GetAttribute("state-page") == 1 and bar:GetAttribute("page") == 1)
		W.setBarState({ page = 2 })
		check("ownsim: a state change runs the snippet with the new value", bar:GetAttribute("seen") == 2 and bar:GetAttribute("page") == 2)
		W.setBarState({ page = 2 })
		W.setBarState({ bonus = 1 })
		check("ownsim: a change that leaves the parsed value as it was runs nothing", bar:GetAttribute("seen") == 2 and bar:GetAttribute("page") == 2)
		W.setBarState({ page = 1 })
		check("ownsim: the conditions are parsed in order", bar:GetAttribute("seen") == 3 and bar:GetAttribute("page") == "b1", tostring(bar:GetAttribute("page")))
		W.setCombat(true)
		W.setBarState({ bonus = 0 })
		check("ownsim: in combat a driver still runs its snippet, secure, with no violation", bar:GetAttribute("seen") == 4 and bar:GetAttribute("page") == 1 and #W.violations == 0 and #W.snippetErrors == 0)
		check("ownsim: its attribute writes from the driver are secure", (function()
			for _, w in ipairs(W.attributeWrites) do
				if (w.key == "state-page" or w.key == "page" or w.key == "seen") and not w.secure then return false end
			end
			return true
		end)())
		check("ownsim: an insecure attribute write in combat is refused", (function()
			local ok = pcall(bar.SetAttribute, bar, "x", 1)
			return not ok and W.violations[#W.violations]:find("in combat", 1, true) ~= nil
		end)())
		W.setCombat(false)
		W.macroConditionsMissing.overridebar = true
		env.RegisterStateDriver(bar, "other", "[overridebar] a; b")
		check("ownsim: a condition the client does not parse gives no state", bar:GetAttribute("state-other") == nil)
		W.macroConditionsMissing.overridebar = nil
		env.RegisterStateDriver(bar, "none", "[bar:6] six")
		check("ownsim: a string that matches no clause gives no state", bar:GetAttribute("state-none") == nil)
		env.RegisterStateDriver(bar, "num", "[bar:1] 7; nil")
		check("own fix: a state that is a number is passed as one", bar:GetAttribute("state-num") == 7)
		W.setBarState({ page = 2 })
		check("own fix: and the text nil clears it", bar:GetAttribute("state-num") == nil)
		W.setBarState({ page = 1 })
	end

	-- A watcher under a hidden parent runs _onshow when the parent shows, and _onhide when it hides.
	do
		local W = world()
		local env = W.env
		local container = W.gameBars.MultiBarRight.containers[1]
		local watcher = env.CreateFrame("Frame", nil, container, "SecureHandlerShowHideTemplate")
		watcher:SetAttribute("_onshow", "self:SetAttribute('shows', (self:GetAttribute('shows') or 0) + 1)")
		watcher:SetAttribute("_onhide", "self:SetAttribute('hides', (self:GetAttribute('hides') or 0) + 1)")
		check("ownsim: a watcher runs nothing while its visibility is as it was", watcher:GetAttribute("shows") == nil and watcher:GetAttribute("hides") == nil)
		W.setBar("MultiBarRight", { switch = false })
		check("ownsim: the bar switch off hides the bar and the watcher runs _onhide once", shown(W, 4, 4) == "0" and watcher:GetAttribute("hides") == 1 and watcher:GetAttribute("shows") == nil)
		W.setBar("MultiBarRight", { switch = true })
		check("ownsim: the switch on shows it again and the watcher runs _onshow once", shown(W, 4, 4) == "1" and watcher:GetAttribute("shows") == 1 and watcher:GetAttribute("hides") == 1)
		W.setBar("MultiBarRight", { numButtonsShowable = 0 })
		check("ownsim: a container hidden by the button count hides the watcher too", watcher:GetAttribute("hides") == 2)
		check("ownsim: a watcher's own Show and Hide while its parent is shown run the snippets", (function()
			W.setBar("MultiBarRight", { numButtonsShowable = 12 })
			local was = watcher:GetAttribute("hides")
			watcher:Hide()
			local mid = watcher:GetAttribute("hides")
			watcher:Show()
			return mid == was + 1 and watcher:GetAttribute("shows") == 3
		end)())
		check("ownsim: none of it is a violation", #W.violations == 0 and #W.snippetErrors == 0)
	end

	-- An override click binding takes the key from the twin, and ClearBinding gives it back.
	do
		local W = world()
		local env = W.env
		hand(W, "OwnSimKey", 5)
		local bar = env.CreateFrame("Frame", "OwnSimBinder", env.UIParent, "SecureHandlerStateTemplate")
		bar:SetFrameRef("b", env.OwnSimKey)
		W.press("ACTIONBUTTON", 3)
		check("ownsim: a key with no binding fires the twin's slot as a key press, once", #W.used == 1 and W.used[1].slot == 3 and W.used[1].frame == "ActionButton3" and W.used[1].isKeyPress == true, #W.used)
		bar:Execute("self:SetBindingClick(true, '3', 'OwnSimKey', 'LeftButton')")
		check("ownsim: the binding is listed by owner and key", W.bindings.OwnSimBinder["3"].button == "OwnSimKey" and W.bindings.OwnSimBinder["3"].mouseButton == "LeftButton")
		check("ownsim: GetBindingAction names the click", env.GetBindingAction("3", true) == "CLICK OwnSimKey:LeftButton" and env.GetBindingAction("3") == "ACTIONBUTTON3")
		W.press("ACTIONBUTTON", 3)
		check("ownsim: the key now clicks the button, not the twin", #W.used == 2 and W.used[2].frame == "OwnSimKey" and W.used[2].slot == 5 and W.used[2].isKeyPress == nil, W.used[2] and W.used[2].frame)
		bar:Execute("self:ClearBinding('3')")
		W.press("ACTIONBUTTON", 3)
		check("ownsim: after ClearBinding the twin has the key back", #W.used == 3 and W.used[3].frame == "ActionButton3" and W.used[3].isKeyPress == true)
		check("ownsim: a key of another bar goes to that bar's twin", (function()
			W.press("MULTIACTIONBAR1BUTTON", 5)
			return W.used[4].frame == "MultiBarBottomLeftButton5" and W.used[4].slot == 65
		end)())
		check("ownsim: half a press pushes the twin and the other half lets it go", (function()
			W.press("ACTIONBUTTON", 2, "down")
			local down = env.ActionButton2:GetButtonState()
			W.press("ACTIONBUTTON", 2, "up")
			return down == "PUSHED" and env.ActionButton2:GetButtonState() == "NORMAL"
		end)())
		check("ownsim: a twin the add-on tainted is refused a key press as a button is a click", (function()
			W.markTainted(env.ActionButton4, "popup")
			local refused = #W.refused
			W.press("ACTIONBUTTON", 4)
			return #W.refused == refused + 1 and select(1, env.issecurevariable(env.ActionButton4, "popup")) == false
		end)())
	end

	-- The page the twins use follows the state, as the controller sets it.
	do
		local W = world()
		local env = W.env
		local function slotOfKey()
			local before = #W.used
			W.press("ACTIONBUTTON", 3)
			return #W.used == before + 1 and W.used[#W.used].slot
		end
		check("ownsim: page 1", slotOfKey() == 3)
		W.setBarState({ page = 2 })
		check("ownsim: page 2", slotOfKey() == 15 and W.gameBars.MainActionBar.raw.attributes.actionpage == 2)
		W.setBarState({ page = 1, bonus = 1 })
		check("ownsim: a bonus bar with page 1", slotOfKey() == 75 and W.gameBars.MainActionBar.raw.attributes.actionpage == 7)
		W.setBarState({ page = 3 })
		check("ownsim: a bonus bar with another page changes nothing", slotOfKey() == 27)
		W.setBarState({ page = 1, bonus = 0, tempShape = true })
		check("ownsim: a temporary shapeshift bar", slotOfKey() == 195)
		W.setBarState({ tempShape = false, vehicle = true })
		check("ownsim: an unskinned vehicle keeps the main bar shown on the vehicle page", slotOfKey() == 183 and env.MainActionBar:IsShown() and not env.OverrideActionBar:IsShown())
		W.setBarState({ vehicle = false, override = true })
		check("ownsim: an unskinned override bar", slotOfKey() == 207 and env.MainActionBar:IsShown())
		W.setBarState({ override = false, possess = true })
		check("ownsim: a possess bar is the fifth bonus bar", slotOfKey() == 123 and W.gameBars.MainActionBar.raw.attributes.actionpage == 11, tostring(W.used[#W.used].slot))
		check("ownsim: the events the game raises reach an add-on's frame", (function()
			local seen = {}
			local frame = env.CreateFrame("Frame", nil, env.UIParent)
			for _, e in ipairs({ "ACTIONBAR_PAGE_CHANGED", "UPDATE_BONUS_ACTIONBAR", "UPDATE_VEHICLE_ACTIONBAR" }) do frame:RegisterEvent(e) end
			frame:SetScript("OnEvent", function(_, event) seen[#seen + 1] = event end)
			W.setBarState({ page = 4, possess = false, bonus = 0, vehicle = true })
			return table.concat(seen, ",") == "ACTIONBAR_PAGE_CHANGED,UPDATE_BONUS_ACTIONBAR,UPDATE_VEHICLE_ACTIONBAR"
		end)(), "events")
	end

	-- A skinned vehicle hides the main bar and bars 2 to 8; leaving shows them at once and the override bar hides after the slide.
	do
		local W = world()
		local env = W.env
		W.setBarState({ vehicle = "skinned" })
		check("ownsim: a skinned vehicle hides the main bar and the seven others and shows the override bar", shown(W, 1, 8) == "00000000" and env.OverrideActionBar:IsShown())
		check("ownsim: the override bar slides for 0.4 s", W.rawOf[env.OverrideActionBar].slideOut:IsPlaying() == true)
		W.advance(0.4)
		check("ownsim: after the slide it is still the override state", shown(W, 1, 8) == "00000000" and env.OverrideActionBar:IsShown() and not W.rawOf[env.OverrideActionBar].slideOut:IsPlaying())
		check("ownsim: while the override bar is shown the key functions use its buttons", env.GetActionButtonForID(2) == env.OverrideActionBarButton2 and env.GetActionButtonForID(7) == nil)
		W.setBarState({ vehicle = false })
		check("ownsim: leaving shows the main bar and the seven at once, before the override bar hides", shown(W, 1, 8) == "11111111" and env.OverrideActionBar:IsShown())
		W.advance(0.4)
		check("ownsim: the override bar hides when its slide ends", not env.OverrideActionBar:IsShown() and shown(W, 1, 8) == "11111111" and env.GetActionButtonForID(2) == env.ActionButton2)
		W.setBarState({ override = "skinned" })
		W.advance(0.4)
		check("ownsim: a skinned override bar is the same", shown(W, 1, 8) == "00000000" and env.OverrideActionBar:IsShown())
		W.setBarState({ override = false })
		W.advance(0.4)
		check("ownsim: and leaves the same", shown(W, 1, 8) == "11111111" and not env.OverrideActionBar:IsShown())
		check("ownsim: the override buttons take a key while the bar is shown", (function()
			W.setBarState({ vehicle = "skinned" })
			W.advance(0.4)
			local before = #W.used
			W.press("ACTIONBUTTON", 2)
			return #W.used == before + 1 and W.used[#W.used].frame == "OverrideActionBarButton2" and W.used[#W.used].slot == 182
		end)())
	end

	-- Visibility by Edit Mode's rules, the layout and the grid.
	do
		local W = world()
		local env = W.env
		W.setBar("MultiBarBottomRight", { visibility = "InCombat" })
		check("ownsim: In combat visibility hides the bar out of combat and shows it in combat", shown(W, 3, 3) == "0" and (function() W.setCombat(true) return shown(W, 3, 3) == "1" end)())
		W.setCombat(false)
		check("ownsim: and hides it again after combat", shown(W, 3, 3) == "0")
		W.setBar("MultiBarBottomRight", { visibility = "OutOfCombat" })
		check("ownsim: Out of combat visibility is the opposite", shown(W, 3, 3) == "1" and (function() W.setCombat(true) return shown(W, 3, 3) == "0" end)())
		W.setCombat(false)
		W.setBar("MultiBarLeft", { visibility = "Hidden" })
		check("ownsim: Hidden hides the bar", shown(W, 5, 5) == "0")
		W.setCursor({ type = "spell", id = 1 })
		check("ownsim: it shows while an action is dragged", shown(W, 5, 5) == "1")
		W.setCursor(nil)
		check("ownsim: and hides when the drag ends", shown(W, 5, 5) == "0")
		W.setBar("MultiBarLeft", { alwaysShow = true })
		check("ownsim: Always show buttons shows it", shown(W, 5, 5) == "1")
		W.setBar("MultiBarLeft", { alwaysShow = false })
		W.setEditMode(true)
		check("ownsim: Edit Mode shows every bar its rules hide", shown(W, 5, 5) == "1" and env.EditModeManagerFrame:IsEditModeActive())
		W.setEditMode(false)
		W.setBar("MultiBarLeft", { switch = false })
		check("ownsim: a bar switched off stays hidden whatever its visibility", shown(W, 5, 5) == "0")

		local main = W.gameBars.MainActionBar
		W.setBar("MainActionBar", { rect = { 100, 50 }, iconSize = 80 })
		local c1, c2 = main.containers[1], main.containers[2]
		local l1, b1, w1, h1 = c1:GetRect()
		local l2 = c2:GetRect()
		check("ownsim: a container is 45 wide in its own units, at the icon scale, from the bar's rectangle", w1 == 45 and h1 == 45 and near(l1, 125, 1e-6) and near(b1, 62.5, 1e-6) and near(l2, 172.5, 1e-6), tostring(l2))
		check("ownsim: the container's scale is the icon size", near(c1:GetScale(), 0.8, 1e-9) and near(c1:GetEffectiveScale(), 0.8 * W.uiInner.scale, 1e-9))
		check("ownsim: a button is at its container's place", (function()
			local tl, tb, tw, th = env.ActionButton1:GetRect()
			return near(tl, l1, 1e-6) and near(tb, b1, 1e-6) and tw == 45 and th == 45
		end)())
		check("ownsim: the bar's rectangle follows the count of buttons", (function()
			W.setBar("MainActionBar", { numButtonsShowable = 6, iconSize = 100 })
			local bl, bb, bw, bh = env.MainActionBar:GetRect()
			return bl == 100 and bb == 50 and bw == 6 * 45 + 5 * 2 and bh == 45 and main.containers[7].raw == nil and W.rawOf[main.containers[7]].shown == false and W.rawOf[main.containers[6]].shown == true
		end)())
		W.setBar("MainActionBar", { numButtonsShowable = 12 })
		W.slots[2] = {}
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		check("ownsim: an empty slot hides its button and keeps its container", env.ActionButton2:IsShown() == false and W.rawOf[main.containers[2]].shown == true and main.containers[2]:GetRect() ~= nil)
		W.setCursor({ type = "spell", id = 1 })
		check("ownsim: holding something shows the empty buttons", env.ActionButton2:IsShown() == true)
		W.setCursor(nil)
		check("ownsim: and letting go hides them", env.ActionButton2:IsShown() == false)
		check("ownsim: Always show buttons shows them too", (function() W.setBar("MainActionBar", { alwaysShow = true }) return env.ActionButton2:IsShown() == true end)())
	end

	-- Calls on the game's frames: recorded, protected in combat, and refused on a frame that has no handle.
	do
		local W = world()
		local env = W.env
		local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
		header:SetFrameRef("bar", env.MainActionBar)
		header:SetFrameRef("twin", env.ActionButton1)
		header:SetFrameRef("up", env.MainActionBar.ActionBarPageNumber.UpButton)
		header:Execute("local bar, twin = self:GetFrameRef('bar'), self:GetFrameRef('twin') bar:SetAlpha(0) bar:EnableMouse(false) twin:EnableMouse(false)")
		check("ownsim: a snippet parks a bar and a button through their handles", env.MainActionBar:GetAlpha() == 0 and env.MainActionBar:IsMouseEnabled() == false and env.ActionButton1:IsMouseEnabled() == false)
		check("ownsim: those calls are listed as secure add-on calls", (function()
			local list = W.gameWritesByAddon()
			return #list == 3 and list[1].frame == "MainActionBar" and list[1].method == "SetAlpha" and list[1].secure == true and list[3].frame == "ActionButton1" and list[3].method == "EnableMouse"
		end)())
		check("ownsim: a button with the mouse off takes no click", W.click("ActionButton1") == false)
		check("ownsim: a handle of a frame that is not protected has no methods", (function()
			local ok = pcall(header.Execute, header, "self:GetFrameRef('up'):EnableMouse(false)")
			return ok and #W.snippetErrors == 1 and W.violations[#W.violations]:find("not protected", 1, true) ~= nil
		end)())
		env.MainActionBar.ActionBarPageNumber.UpButton:EnableMouse(false)
		check("ownsim: a plain call does it out of combat", env.MainActionBar.ActionBarPageNumber.UpButton:IsMouseEnabled() == false)
		env.MultiBarRight:SetAlpha(0)
		env.MainMenuBarVehicleLeaveButton:SetIgnoreParentAlpha(true)
		check("ownsim: alpha and the vehicle button's alpha rule are calls of the add-on's, listed", (function()
			local last = W.gameWritesByAddon()
			return last[#last].method == "SetIgnoreParentAlpha" and last[#last].args[1] == true and env.MainMenuBarVehicleLeaveButton:IsIgnoringParentAlpha() == true
				and env.MainMenuBarVehicleLeaveButton:GetEffectiveAlpha() == 1
		end)())
		W.setCombat(true)
		local ok1 = pcall(env.ActionButton2.EnableMouse, env.ActionButton2, false)
		local ok2 = pcall(header.Execute, header, "local twin = self:GetFrameRef('twin') twin:EnableMouse(true)")
		local ok3 = pcall(env.ActionButton2.SetPoint, env.ActionButton2, "CENTER", env.UIParent)
		local ok4 = pcall(env.MainActionBar.SetAlpha, env.MainActionBar, 0.5)
		check("ownsim: in combat a plain mouse call and a plain placement on a protected frame are refused, Execute is refused, alpha is not", not ok1 and not ok2 and not ok3 and ok4)
		check("ownsim: a field written on a game frame is a violation", (function()
			local ok = pcall(function() env.ActionButton1.mine = 1 end)
			return not ok
		end)())
		check("ownsim: hooksecurefunc is listed with its target", (function()
			env.hooksecurefunc(env.MainActionBar, "Show", function() end)
			env.hooksecurefunc("ActionButtonDown", function() end)
			local a, b = W.hookCalls[#W.hookCalls - 1], W.hookCalls[#W.hookCalls]
			return a.target == "MainActionBar" and a.name == "Show" and b.target == "_G" and b.name == "ActionButtonDown"
		end)())
	end

	-- Wrap scripts: the pre-body decides, a pickup goes through PickupAction as secure code.
	do
		local W = world()
		local env = W.env
		local button, header = hand(W, "OwnSimDrag", 9)
		header:SetAttribute("locked", false)
		env.SecureHandlerWrapScript(button, "OnDragStart", header, "if control:GetAttribute('locked') and not IsModifiedClick('PICKUPACTION') then return false end return 'action', self:GetAttribute('action')")
		env.SecureHandlerWrapScript(button, "OnReceiveDrag", header, "return 'action', self:GetAttribute('action')")
		W.drag("OwnSimDrag")
		check("ownsim: an unlocked drag picks the slot up", W.cursor and W.cursor.type == "spell" and W.slots[9].kind == nil and W.picked[1].kind == "action" and W.picked[1].target == 9 and env.GetCursorInfo() == "spell")
		W.drag("OwnSimDrag", "OnReceiveDrag")
		check("ownsim: a drop on the button puts it back", W.cursor == nil and W.slots[9].kind == "spell")
		header:SetAttribute("locked", true)
		W.drag("OwnSimDrag")
		check("ownsim: locked, the pre-body returns false and nothing is picked up", W.cursor == nil and W.slots[9].kind == "spell" and #W.picked == 2)
		W.modifiedClicks.PICKUPACTION = true
		W.drag("OwnSimDrag")
		check("ownsim: locked with the modifier it picks up", W.cursor ~= nil and #W.picked == 3)
		check("ownsim: a wrap in combat is refused, a wrapped script on a frame that is not protected too", (function()
			W.setCombat(true)
			local ok = pcall(env.SecureHandlerWrapScript, button, "OnEnter", header, "return")
			W.setCombat(false)
			local plain = env.CreateFrame("Frame", nil, env.UIParent)
			local ok2 = pcall(env.SecureHandlerWrapScript, plain, "OnEnter", header, "return")
			return not ok and not ok2
		end)())
		check("ownsim: nothing in it was a violation but those", #W.violations == 2, #W.violations)
	end

	-- Duration objects and secret values.
	do
		local W = world()
		local env = W.env
		local b = env.CreateFrame("CheckButton", "OwnSimCd", env.UIParent, "ActionButtonTemplate, SecureActionButtonTemplate")
		W.slots[3].cd = { active = true, start = 10, duration = 5 }
		W.slots[3].count = 4
		local plain = env.C_ActionBar.GetActionCooldown(3)
		check("ownsim: cooldown numbers are plain while cooldowns are not secret", plain.startTime == 10 and plain.duration == 5 and plain.isActive == true and env.C_ActionBar.GetActionDisplayCount(3) == "4")
		W.secretCooldowns = true
		local cd = env.C_ActionBar.GetActionCooldown(3)
		check("ownsim: while they are, the numbers are secret and isActive is not", env.issecretvalue(cd.startTime) and env.issecretvalue(cd.duration) and cd.isActive == true and env.issecretvalue(env.C_ActionBar.GetActionDisplayCount(3))
			and env.issecretvalue(env.C_ActionBar.GetActionCharges(3).currentCharges) and env.C_ActionBar.GetActionCharges(3).isActive == false)
		check("ownsim: SetCooldown with a secret value is a violation", (function()
			local ok = pcall(b.cooldown.SetCooldown, b.cooldown, cd.startTime, cd.duration)
			return not ok and W.violations[#W.violations]:find("secret", 1, true) ~= nil
		end)())
		check("ownsim: a duration object sets the sweep and a zero one clears it", (function()
			b.cooldown:SetCooldownFromDurationObject(env.C_ActionBar.GetActionCooldownDuration(3))
			local on = b.cooldown.shown == true and b.cooldown.cd.calls.SetCooldownFromDurationObject == 1
			b.cooldown:SetCooldownFromDurationObject(env.C_ActionBar.GetActionCooldownDuration(4))
			return on and b.cooldown.shown == false and b.cooldown.cd.sweep == nil
		end)())
		check("ownsim: Clear and plain numbers work", (function()
			W.secretCooldowns = false
			b.chargeCooldown:SetCooldown(5, 2)
			local on = b.chargeCooldown.shown == true
			b.chargeCooldown:Clear()
			return on and b.chargeCooldown.shown == false
		end)())
		check("ownsim: something that is not a duration object is refused", not pcall(b.cooldown.SetCooldownFromDurationObject, b.cooldown, {}))
	end

	-- The engine: frames with a parent hear events, W.tick runs every OnUpdate once.
	do
		local W = world()
		local env = W.env
		local heard, frames = 0, 0
		local child = env.CreateFrame("Frame", nil, env.UIParent)
		child:RegisterEvent("UPDATE_BINDINGS")
		child:SetScript("OnEvent", function() heard = heard + 1 end)
		local loose = env.CreateFrame("Frame")
		loose:SetScript("OnUpdate", function() frames = frames + 1 end)
		W.fire("UPDATE_BINDINGS")
		check("ownsim: an event reaches a frame that has a parent", heard == 1)
		W.tick()
		check("ownsim: one tick is one OnUpdate pass", frames == 1)
		W.frame(2)
		check("ownsim: W.frame(2) is two passes", frames == 3)
		check("ownsim: an add-on's code in a hook runs as insecure code", (function()
			local b = env.CreateFrame("CheckButton", "OwnSimHook", env.UIParent, "ActionButtonTemplate, SecureActionButtonTemplate")
			local seen
			b:HookScript("PostClick", function() seen = W.inSecure end)
			b:HookScript("OnEnter", function() seen = seen or "enter" end)
			local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
			header:SetFrameRef("b", b)
			header:Execute("local b = self:GetFrameRef('b') b:SetAttribute('type', 'none') b:SetAttribute('useOnKeyDown', false)")
			b:RegisterForClicks("AnyUp")
			W.click("OwnSimHook")
			return seen == false
		end)())
		check("ownsim: IsSpellOverlayed follows the overlay of the slot holding the spell", (function()
			W.slots[3].overlay = true
			return env.C_SpellActivationOverlay.IsSpellOverlayed(503) == true and env.C_SpellActivationOverlay.IsSpellOverlayed(504) == false
		end)())
		check("ownsim: GetBindingText gives a key with short modifiers", env.GetBindingText("SHIFT-1", "KEY_", true) == "s-1" and env.GetBindingText("CTRL-2") == "CTRL-2")
		check("ownsim: nothing here broke the world", #W.errors == 0)
	end
end
-- >>> ownsim bars (end)
-- >>> ownsim login (begin)
-- The addon runs in a world with the layer, as it does in one without.
do
	local W = newWorld({ own = true })
	W.login()
	W.frame(3)
	check("ownsim: the addon logs in over the layer with no error and no violation", #W.errors == 0 and #W.violations == 0, table.concat(W.errors, "|") .. "/" .. table.concat(W.violations, "|"))
	local H = newWorld({ own = true, handsOff = true })
	H.login()
	H.flush()
	check("ownsim: and with the game's bars left alone", #H.errors == 0 and #H.violations == 0, table.concat(H.errors, "|") .. "/" .. table.concat(H.violations, "|"))
	local C = newWorld({ own = true, combat = true })
	check("ownsim: a world made in combat has its bars and refuses an add-on's secure frame", C.gameBars.MainActionBar.raw.shown == true and not pcall(C.env.CreateFrame, "Frame", nil, C.env.UIParent, "SecureHandlerBaseTemplate"))
	C.setCombat(false)
	check("ownsim: and makes it when combat ends", pcall(C.env.CreateFrame, "Frame", nil, C.env.UIParent, "SecureHandlerBaseTemplate"))
	check("ownsim: the game's list of buttons holds the 96 twins and refuses a write", #C.env.ActionBarButtonEventsFrame.frames == 96 and C.env.ActionBarButtonEventsFrame.frames[1] == C.env.ActionButton1
		and not pcall(function() C.env.ActionBarButtonEventsFrame.frames[97] = {} end))
end
-- >>> ownsim login (end)
-- >>> ownbars (begin)
-- Flat UI's own action buttons, piece B (ownbars:, FlatUI/OwnBars.lua): the bars, the buttons, the paging, the parking, the layout and the flyout keys.
-- The setting actionbars.own is the Action buttons row; a world starts on its default, Flat UI's.
do
	local T = {
		BASE = { 0, 60, 48, 24, 36, 144, 156, 168 },
		GAME = { "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBarRight", "MultiBarLeft", "MultiBar5", "MultiBar6", "MultiBar7" },
		TWIN = { "ActionButton", "MultiBarBottomLeftButton", "MultiBarBottomRightButton", "MultiBarRightButton", "MultiBarLeftButton", "MultiBar5Button", "MultiBar6Button", "MultiBar7Button" },
		STATES = { { page = 2 }, { page = 3 }, { page = 4 }, { page = 5 }, { page = 6 }, { bonus = 1 }, { bonus = 2 }, { bonus = 3 }, { bonus = 4 }, { bonus = 1, page = 3 },
			{ tempShape = true }, { override = true }, { vehicle = true }, { possess = true } },
		RESET = { page = 1, bonus = 0, tempShape = false, override = false, vehicle = false, possess = false },
	}
	function T.world(opts, mode)
		opts = opts or {}
		opts.own, opts.handsOff = true, true
		if mode and mode ~= "flat" then
			opts.saved = { options = { ["actionbars.own"] = mode } }
		end
		return newWorld(opts)
	end
	function T.login(W)
		W.login()
		W.frame(3)
		return W
	end
	function T.flyout(W, slot, id)
		W.slots[slot] = { kind = "flyout", id = id or 7, flyout = id or 7, texture = 777 }
	end
	function T.btn(W, n, i) return W.env["FlatUIBar" .. n .. "Button" .. i] end
	function T.sane(W) return #W.errors == 0 and #W.violations == 0 end
	function T.units(W, frame)
		return W.ownState.screenRect(W.rawOf[frame])
	end
	function T.same(a, b)
		return a ~= nil and b ~= nil and math.abs(a - b) < 0.05
	end

	-- 1. The template, the click handler, the id and the game's list.
	do
		local W = T.login(T.world())
		local env = W.env
		local b = T.btn(W, 1, 1)
		check("ownbars: login builds 96 buttons on 8 bars with no error or violation", W.ns.OwnOn() == true and #W.ns.OwnButtons() == 96 and #W.own == 96 and T.sane(W),
			table.concat(W.errors, "|") .. table.concat(W.violations, "|"))
		check("ownbars: the template string is exactly the barebones pair", W.rawOf[b].templateString == "ActionButtonTemplate, SecureActionButtonTemplate"
			and W.rawOf[T.btn(W, 8, 12)].templateString == "ActionButtonTemplate, SecureActionButtonTemplate")
		check("ownbars: a button's OnClick is the secure one and its id is 0", b:GetScript("OnClick") == env.SecureActionButton_OnClick and b:GetID() == 0)
		check("ownbars: the buttons are named by bar and index, in order", W.own[1] == b and W.own[13] == T.btn(W, 2, 1) and W.own[96] == T.btn(W, 8, 12)
			and W.ns.OwnBarFrame(3) == env.FlatUIBar3 and select(2, W.ns.OwnBar(T.btn(W, 4, 7))) == 7 and W.ns.OwnBar(env.UIParent) == nil)
		local joined = false
		for index = 1, #env.ActionBarButtonEventsFrame.frames do
			local f = env.ActionBarButtonEventsFrame.frames[index]
			joined = joined or (W.rawOf[f].name and W.rawOf[f].name:find("FlatUI", 1, true) ~= nil)
		end
		check("ownbars: no Flat UI button is in the game's list of buttons", #env.ActionBarButtonEventsFrame.frames == 96 and not joined)
		check("ownbars: a button's twin and key command", W.ns.OwnTwin(T.btn(W, 1, 3)) == env.ActionButton3 and W.ns.OwnTwin(T.btn(W, 4, 5)) == env.MultiBarRightButton5
			and W.ns.OwnCommand(T.btn(W, 1, 3)) == "ACTIONBUTTON3" and W.ns.OwnCommand(T.btn(W, 8, 12)) == "MULTIACTIONBAR7BUTTON12"
			and W.ns.OwnSlot(T.btn(W, 3, 2)) == 50 and W.ns.OwnSlot(env.UIParent) == nil)
	end

	-- 2. Every attribute is set by secure code, in the order that clears the popup; no field is written by the add-on.
	do
		local W = T.world()
		T.flyout(W, 1)
		T.login(W)
		local first, secureAll, order, tainted, byAddon = {}, true, true, false, 0
		for _, w in ipairs(W.attributeWrites) do
			if w.button:match("^FlatUIBar%d+Button%d+$") then
				secureAll = secureAll and w.secure == true
				if w.key == "type" and w.value == "none" and not first[w.button] then
					first[w.button] = "none"
				elseif w.key == "action" and not first[w.button] then
					order = false
				end
			end
		end
		for _, w in ipairs(W.fieldWrites) do
			tainted = tainted or (w.key == "popup" and w.by == "template" and w.secure == false)
			if w.by == "addon" then
				byAddon = byAddon + 1
			end
		end
		check("ownbars: every attribute write on a button is secure", secureAll == true and #W.attributeWrites > 96)
		check("ownbars: type goes to a value that is not an action before the action is set", order == true and first.FlatUIBar1Button1 == "none" and first.FlatUIBar8Button12 == "none")
		check("ownbars: Flat UI writes no field on its buttons", byAddon == 0, tostring(byAddon))
		check("ownbars: the template's popup written under Flat UI's taint at creation is secure afterwards", tainted == true
			and select(1, W.env.issecurevariable(T.btn(W, 1, 1), "popup")) == true and W.rawOf[T.btn(W, 1, 1)].shadow.popup == W.env.SpellFlyout)
		check("ownbars: a button's type is action, with the self cast checks and the key-up option", T.btn(W, 2, 4):GetAttribute("type") == "action" and T.btn(W, 2, 4):GetAttribute("action") == 64
			and T.btn(W, 2, 4):GetAttribute("useOnKeyDown") == false and T.btn(W, 2, 4):GetAttribute("checkmouseovercast") == true)
		check("ownbars: nothing broke", T.sane(W))
	end

	-- 3. A click on each bar casts its slot; a flyout slot opens the flyout on the button and casts nothing.
	do
		local W = T.world()
		T.flyout(W, 7)
		T.login(W)
		local ok = true
		for n = 1, 8 do
			local before = #W.used
			W.click("FlatUIBar" .. n .. "Button5")
			local rec = W.used[#W.used]
			ok = ok and #W.used == before + 1 and rec.slot == T.BASE[n] + 5 and rec.isKeyPress == nil and rec.frame == "FlatUIBar" .. n .. "Button5"
		end
		check("ownbars: a click on a button of each bar casts the bar's slot and nothing is refused", ok and #W.refused == 0, tostring(#W.refused))
		local before = #W.used
		W.click("FlatUIBar1Button7")
		check("ownbars: a click on a flyout slot opens the flyout on the Flat UI button and calls no UseAction", #W.used == before and W.flyoutOn() == "FlatUIBar1Button7" and #W.refused == 0)
	end

	-- 4. Paging: bar 1's slots and page follow the game's controller in every state, in combat too.
	do
		local W = T.login(T.world())
		local env = W.env
		for _, combat in ipairs({ false, true }) do
			W.setCombat(combat)
			for index, state in ipairs(T.STATES) do
				W.setBarState(state)
				local flat, game = W.ns.OwnPage()
				local slots = true
				for i = 1, 12 do
					slots = slots and T.btn(W, 1, i):GetAttribute("action") == (game - 1) * 12 + i
				end
				local label = (combat and "in combat " or "") .. "state " .. index
				check("ownbars: paging " .. label .. " gives the game's page and slots", flat == game and slots, tostring(flat) .. "/" .. tostring(game))
				W.setBarState(T.RESET)
			end
		end
		W.setCombat(false)
		check("ownbars: paging made no violation and no error", T.sane(W), table.concat(W.violations, "|"))
		W.setBarState({ bonus = 1 })
		W.setBarState({ page = 3 })
		local direct, same = W.ns.OwnPage()
		check("ownbars: a page change under a bonus bar is followed at once", direct == 3 and same == 3 and T.btn(W, 1, 5):GetAttribute("action") == 29, tostring(direct) .. "/" .. tostring(same))
		W.setBarState(T.RESET)
		local flat, game = W.ns.OwnPage()
		check("ownbars: back on page 1 the slots are 1 to 12", flat == 1 and game == 1 and T.btn(W, 1, 12):GetAttribute("action") == 12 and env.FlatUIBar1:GetAttribute("flatui-page") == 1)
	end

	-- 5. Visibility follows the game's bars: skinned vehicle, unskinned vehicle, pet battle.
	do
		for _, combat in ipairs({ false, true }) do
			local W = T.login(T.world())
			local env = W.env
			local function shown()
				for n = 1, 8 do
					if not env["FlatUIBar" .. n]:IsShown() then
						return false
					end
				end
				return true
			end
			local function hidden()
				for n = 1, 8 do
					if env["FlatUIBar" .. n]:IsShown() then
						return false
					end
				end
				return true
			end
			local tag = combat and "in combat " or ""
			check("ownbars: " .. tag .. "all eight bars are shown at the start", shown())
			W.setCombat(combat)
			W.setBarState({ vehicle = "skinned" })
			check("ownbars: " .. tag .. "a skinned vehicle hides all eight bars with the game's", hidden() and not env.MainActionBar:IsShown())
			W.advance(0.5)
			W.setBarState({ vehicle = false })
			check("ownbars: " .. tag .. "leaving shows them before the override bar has slid out", shown() and env.OverrideActionBar:IsShown())
			W.advance(0.4)
			check("ownbars: " .. tag .. "and they stay when the override bar hides", shown() and not env.OverrideActionBar:IsShown())
			W.setBarState({ vehicle = true })
			check("ownbars: " .. tag .. "an unskinned vehicle keeps the bars with the vehicle page", shown() and T.btn(W, 1, 2):GetAttribute("action") == 15 * 12 + 2)
			W.setBarState({ vehicle = false })
			W.setBarState({ petbattle = true })
			check("ownbars: " .. tag .. "a pet battle hides all eight", hidden())
			W.setBarState({ petbattle = false })
			check("ownbars: " .. tag .. "and they come back after", shown())
			W.setBarState({ override = "skinned" })
			W.advance(0.5)
			check("ownbars: " .. tag .. "a skinned override hides them", hidden())
			W.setBarState({ override = false })
			check("ownbars: " .. tag .. "and they are back at once", shown() and T.sane(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
		end
	end

	-- 6. Parking: alpha 0 and the mouse off, and no other call on a game frame.
	do
		local W = T.login(T.world())
		local env = W.env
		local alphas, mouse = true, env.MainActionBar:IsMouseEnabled() == false
		for n = 1, 8 do
			alphas = alphas and env[T.GAME[n]]:GetAlpha() == 0
			for i = 1, 12 do
				mouse = mouse and env[T.TWIN[n] .. i]:IsMouseEnabled() == false
			end
		end
		check("ownbars: the eight game bars are at alpha 0", alphas)
		check("ownbars: the main bar, the pager buttons and the 96 buttons have the mouse off", mouse and env.MainActionBar.ActionBarPageNumber.UpButton:IsMouseEnabled() == false
			and env.MainActionBar.ActionBarPageNumber.DownButton:IsMouseEnabled() == false)
		local craw = W.rawOf[W.gameBars.MultiBarRight.containers[1]]
		check("ownbars: a container keeps its mouse and alpha", craw.alpha == 1 and craw.mouse ~= false)
		local allowed, odd = { SetAlpha = true, EnableMouse = true, SetIgnoreParentAlpha = true }, {}
		for _, w in ipairs(W.gameWritesByAddon()) do
			local good = allowed[w.method]
			if w.method == "SetAlpha" then
				good = w.args[1] == 0
			elseif w.method == "EnableMouse" then
				good = w.args[1] == false
			elseif w.method == "SetIgnoreParentAlpha" then
				good = w.args[1] == true and w.frame == "MainMenuBarVehicleLeaveButton"
			end
			if not good then
				odd[#odd + 1] = w.frame .. ":" .. w.method
			end
		end
		check("ownbars: the only writes on a game frame are the alphas, the mouse flags and the leave button's alpha", #odd == 0 and #W.gameWritesByAddon() > 90, table.concat(odd, ","))
		local hooked = {}
		for _, h in ipairs(W.hookCalls) do
			local t = tostring(h.target)
			if t:find("Action", 1, true) or t:find("MultiBar", 1, true) or tostring(h.name):find("Action", 1, true) then
				hooked[#hooked + 1] = t .. ":" .. tostring(h.name)
			end
		end
		check("ownbars: nothing is hooked on a game bar, a button or an action function", #hooked == 0, table.concat(hooked, ","))
		local fine = #W.ownState.watchers == 8
		for n = 1, 8 do
			local w = W.ownState.watchers[n]
			fine = fine and w and w.name == nil and w.secure == true and W.rawOf[w.parent] == W.rawOf[W.gameBars[T.GAME[n]].containers[1]] and w.width == 1 and w.height == 1
		end
		check("ownbars: eight watchers of Flat UI's, each under the first container of a game bar", fine)
		check("ownbars: the leave button ignores its parent's alpha, and the status lines say so", env.MainMenuBarVehicleLeaveButton:IsIgnoringParentAlpha() == true
			and W.ns.OwnStatus("leave") == "Vehicle leave button: shown without the main bar." and W.ns.OwnStatus("parked") == "Game bars 1 to 8: hidden.")
		local G = T.login(T.world(nil, "game"))
		check("ownbars: with the game's buttons nothing is made and no call is made on any game frame", #G.gameWritesByAddon() == 0 and #G.own == 0 and G.env.FlatUIBar1 == nil
			and G.env.FlatUIOwnHeader == nil and #G.ownState.watchers == 0 and not G.ns.OwnOn() and G.ns.OwnStatus("buttons") == "Action buttons: the game's."
			and G.ns.OwnStatus("page") == nil and T.sane(G))
	end

	-- 7. Upkeep: an alpha the game puts back is taken again at once, a mouse after combat.
	do
		local W = T.login(T.world())
		local env = W.env
		W.gameBars.MultiBarRight.raw.alpha = 1
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		check("ownbars: alpha 1 put back by the game is 0 again after the layout event", env.MultiBarRight:GetAlpha() == 0)
		W.setCombat(true)
		W.rawOf[env.MultiBarRightButton3].mouse = true
		W.gameBars.MultiBar5.raw.alpha = 1
		W.fire("UPDATE_BONUS_ACTIONBAR")
		W.frame(3)
		check("ownbars: in combat the alpha is taken again and the mouse is not", env.MultiBar5:GetAlpha() == 0 and env.MultiBarRightButton3:IsMouseEnabled() == true)
		W.setCombat(false)
		W.frame(2)
		check("ownbars: after combat the mouse is off again", env.MultiBarRightButton3:IsMouseEnabled() == false and T.sane(W))
		check("ownbars: the status line counts what the game put back", (W.ns.OwnStatus("parked") or ""):find("The game showed them again 3 times this session.", 1, true) ~= nil,
			tostring(W.ns.OwnStatus("parked")))
		W.rawOf[env.MainMenuBarVehicleLeaveButton].ignoreParentAlpha = false
		W.fire("UPDATE_VEHICLE_ACTIONBAR")
		W.frame(2)
		check("ownbars: the leave button's setting is put back too", env.MainMenuBarVehicleLeaveButton:IsIgnoringParentAlpha() == true)
	end

	-- 8. Layout copied from the game's bars, containers and counts.
	do
		local W = T.login(T.world())
		local env = W.env
		local function matches(n)
			local bar = W.gameBars[T.GAME[n]]
			local count = bar.numButtonsShowable
			local gl, gb, gw, gh = T.units(W, bar.frame)
			local fl, fb, fw, fh = T.units(W, env["FlatUIBar" .. n])
			local ok = T.same(gl, fl) and T.same(gb, fb) and T.same(gw, fw) and T.same(gh, fh)
			for i = 1, 12 do
				local button = T.btn(W, n, i)
				if i <= count then
					local cl, cb, cw, ch = T.units(W, bar.containers[i])
					local bl, bb, bw, bh = T.units(W, button)
					ok = ok and T.same(cl, bl) and T.same(cb, bb) and T.same(cw, bw) and T.same(ch, bh) and button:IsShown()
				else
					ok = ok and not button:IsShown()
				end
			end
			return ok
		end
		local ok = true
		for n = 1, 8 do
			ok = ok and matches(n)
		end
		check("ownbars: every button is at its container's place and size", ok)
		W.slots[61] = {}
		W.setBar("MultiBarLeft", { iconSize = 80 })
		W.setBar(2, { numButtonsShowable = 8 })
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.frame(2)
		check("ownbars: an empty slot, an icon size of 80 and a count of 8 are copied", matches(5) and matches(2) and not T.btn(W, 2, 9):IsShown() and T.btn(W, 2, 8):IsShown())
		W.setCombat(true)
		W.setBar(3, { rect = { 500, 300 } })
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.frame(3)
		check("ownbars: a change in combat is not laid out in combat", not matches(3))
		local before = W.executed
		W.setCombat(false)
		W.frame(2)
		check("ownbars: it is laid out once after combat", matches(3) and W.executed - before <= 1 and T.sane(W), tostring(W.executed - before))
		W.setEditMode(true)
		W.setBar(4, { rect = { 1000, 400 } })
		W.advance(0.1)
		check("ownbars: while Edit Mode is active a moved game bar moves its Flat UI bar on the next poll", matches(4))
		W.setBar(4, { rect = { 1100, 500 } })
		W.setEditMode(false)
		W.advance(0.1)
		check("ownbars: and once when Edit Mode closes", matches(4))
		local still = W.executed
		W.advance(0.3)
		check("ownbars: with Edit Mode closed nothing is laid out again", W.executed == still)
		check("ownbars: a flyout opens up from the bottom bar and toward the middle from the side bars", T.btn(W, 1, 1):GetAttribute("flyoutDirection") == "UP"
			and T.btn(W, 4, 1):GetAttribute("flyoutDirection") == "RIGHT" and T.btn(W, 5, 1):GetAttribute("flyoutDirection") == "LEFT")
	end

	-- 9. Visibility rules of the game's bars.
	do
		local W = T.login(T.world())
		local env = W.env
		W.setBar("MultiBarRight", { switch = false })
		check("ownbars: a bar switched off in the game is hidden here", not env.FlatUIBar4:IsShown() and env.FlatUIBar3:IsShown() and env.FlatUIBar1:IsShown())
		W.setBar(3, { visibility = "InCombat" })
		check("ownbars: In combat visibility hides bar 3 out of combat", not env.FlatUIBar3:IsShown())
		W.setCombat(true)
		check("ownbars: and shows it in combat", env.FlatUIBar3:IsShown())
		W.setCombat(false)
		check("ownbars: and hides it after", not env.FlatUIBar3:IsShown())
		W.setBar(5, { visibility = "Hidden" })
		check("ownbars: Hidden visibility hides bar 5", not env.FlatUIBar5:IsShown())
		W.setCursor({ type = "spell", id = 1 })
		check("ownbars: and an action on the cursor shows it", env.FlatUIBar5:IsShown())
		W.setCursor(nil)
		check("ownbars: and it hides again", not env.FlatUIBar5:IsShown() and T.sane(W))
	end

	-- 10. Drag and drop through the wraps.
	do
		local W = T.login(T.world())
		local function drag()
			local before = #W.picked
			W.drag("FlatUIBar1Button3")
			local pick = W.picked[#W.picked]
			W.slots[3] = nil
			W.setCursor(nil)
			return #W.picked > before and pick or false
		end
		local pick = drag()
		check("ownbars: unlocked, a drag picks up the button's slot", pick and pick.kind == "action" and pick.target == 3)
		W.ownCVars.lockActionBars = true
		W.fire("CVAR_UPDATE", "lockActionBars", "1")
		W.frame(1)
		check("ownbars: locked, a drag without the pickup key picks up nothing", drag() == false)
		W.modifiedClicks.PICKUPACTION = true
		pick = drag()
		check("ownbars: locked, with the pickup key it picks up the slot", pick and pick.target == 3)
		W.modifiedClicks.PICKUPACTION = nil
		local before = #W.picked
		W.runScript(T.btn(W, 2, 4), "OnReceiveDrag")
		check("ownbars: a drop puts down on the button's slot, locked or not", #W.picked == before + 1 and W.picked[#W.picked].kind == "action" and W.picked[#W.picked].target == 64)
		W.setCursor(nil)
		W.ownCVars.lockActionBars = false
		W.fire("CVAR_UPDATE", "lockActionBars", "0")
		W.frame(1)
		W.setCombat(true)
		pick = drag()
		check("ownbars: a drag works in combat with no violation", pick and pick.target == 3 and T.sane(W))
	end

	-- 11. Login in combat: nothing until combat ends, then all of it once.
	do
		local W = T.world({ combat = true })
		W.login()
		W.frame(3)
		check("ownbars: login in combat makes and parks nothing", not W.ns.OwnOn() and #W.own == 0 and #W.gameWritesByAddon() == 0 and W.env.FlatUIOwnHeader == nil and #W.ownState.watchers == 0)
		check("ownbars: and says so once", table.concat(W.out, "|"):find("Action buttons are built when combat ends.", 1, true) ~= nil
			and W.ns.OwnStatus("waiting") == "Action buttons: Flat UI's buttons are built when combat ends.")
		W.setCombat(false)
		W.frame(2)
		check("ownbars: when combat ends all of it is made", W.ns.OwnOn() and #W.own == 96 and #W.ownState.watchers == 8 and W.env.MainActionBar:GetAlpha() == 0
			and W.ns.OwnStatus("buttons") == "Action buttons: Flat UI's, 96 on 8 bars.")
		W.fire("PLAYER_REGEN_ENABLED")
		W.frame(2)
		check("ownbars: and once", #W.own == 96 and #W.ownState.watchers == 8 and #W.errors == 0 and #W.violations == 0)
	end

	-- 12. Switching back: what was parked is put back once.
	do
		local W = T.login(T.world())
		local env = W.env
		W.ns.Set("actionbars.own", "game")
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.frame(2)
		local alphas, mouse = true, env.MainActionBar:IsMouseEnabled()
		for n = 1, 8 do
			alphas = alphas and env[T.GAME[n]]:GetAlpha() == 1
			for i = 1, 12 do
				mouse = mouse and env[T.TWIN[n] .. i]:IsMouseEnabled()
			end
		end
		check("ownbars: back to the game's buttons the bars have alpha 1 and the mouse on", alphas and mouse and env.MainActionBar.ActionBarPageNumber.UpButton:IsMouseEnabled())
		check("ownbars: and the leave button follows its parent's alpha again", env.MainMenuBarVehicleLeaveButton:IsIgnoringParentAlpha() == false)
		local writes = #W.gameWritesByAddon()
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.setBarState({ page = 2 })
		W.frame(2)
		check("ownbars: and nothing more is written", #W.gameWritesByAddon() == writes and T.sane(W))
		check("ownbars: and the status lines say the game's", W.ns.OwnStatus("page") == nil and W.ns.OwnStatus("buttons") == "Action buttons: the game's.")
	end

	-- Fixes after the review of 0.4.58.
	do
		local W = T.login(T.world())
		local env = W.env
		check("own fix: the pager is read from the main bar, not a global", rawget(env, "ActionBarPageNumber") == nil and env.MainActionBar.ActionBarPageNumber ~= nil)
		local flat = true
		for _, list in pairs(W.bindings) do
			for _, b in pairs(list) do
				flat = flat and b.priority == true
			end
		end
		check("own fix: every key routed to a button is a priority binding", flat)
		local W2 = T.world()
		T.flyout(W2, 3)
		T.flyout(W2, 29)
		W2.keys.MULTIACTIONBAR3BUTTON5 = "ALT-5"
		T.login(W2)
		local routed, plain = 0, true
		for _, list in pairs(W2.bindings) do
			for _, b in pairs(list) do
				routed = routed + 1
				plain = plain and b.priority == true
			end
		end
		check("own fix: keys on flyout slots are routed, all with priority", routed >= 1 and plain, tostring(routed))
		check("own fix: a pet battle hides the bars from the number the driver passes", (function()
			W.setBarState({ petbattle = true })
			local hid = not env.FlatUIBar1:IsShown() and env.FlatUIBar1:GetAttribute("state-petbattle") == 1
			W.setBarState({ petbattle = false })
			return hid and env.FlatUIBar1:IsShown() and env.FlatUIBar1:GetAttribute("state-petbattle") == 0
		end)())
	end
	do
		local W = T.world()
		T.flyout(W, 3)
		local env = W.env
		env.ActionButton_UpdateRangeIndicator = function() end
		local cf = env.CreateFrame
		env.CreateFrame = function(kind, name, ...)
			local f = cf(kind, name, ...)
			if name == "FlatUIBar8Button12" then
				W.rawOf[f].protected = false
			end
			return f
		end
		local wrap = env.SecureHandlerWrapScript
		env.SecureHandlerWrapScript = function(frame, ...)
			local raw = W.rawOf[frame]
			local before = raw.protected
			raw.protected = true
			local r = wrap(frame, ...)
			raw.protected = before
			return r
		end
		T.login(W)
		check("own fix: a build whose snippet failed says so and is not built", not W.ns.OwnOn() and (W.ns.OwnStatus("buttons") or ""):find("FlatUIBar8Button12 has no action", 1, true) ~= nil, tostring(W.ns.OwnStatus("buttons")))
		local alphas = true
		for n = 1, 8 do
			alphas = alphas and env[T.GAME[n]]:GetAlpha() == 1
		end
		check("own fix: and the game's bars are put back", alphas and env.MainActionBar:IsMouseEnabled() and env.MainActionBar.ActionBarPageNumber.UpButton:IsMouseEnabled())
		local down = true
		for n = 1, 8 do
			down = down and not env["FlatUIBar" .. n]:IsShown()
		end
		check("own fix: a failed build hides Flat UI's eight bars", down)
		check("own fix: a failed build leaves no key bindings on Flat UI's bars", next(W.bindings) == nil or (function()
			for _, list in pairs(W.bindings) do
				if next(list) ~= nil then
					return false
				end
			end
			return true
		end)())
		local page = env.FlatUIBar1:GetAttribute("state-page")
		W.setBarState({ page = 3 })
		W.frame(2)
		check("own fix: a failed build takes the page driver off", env.FlatUIBar1:GetAttribute("state-page") == page and env.FlatUIBar1:GetAttribute("flatui-page") == 1, tostring(page))
		env.FlatUIBar2:SetAttribute("flatui-game", false)
		W.setBarState({ petbattle = true })
		local pb = env.FlatUIBar1:GetAttribute("state-petbattle")
		W.setBarState({ petbattle = false })
		check("own fix: a failed build takes the pet battle driver off", pb == 0, tostring(pb))
		env.MultiBarBottomLeft:Hide()
		env.MultiBarBottomLeft:Show()
		W.frame(2)
		local back = false
		for n = 1, 8 do
			back = back or env["FlatUIBar" .. n]:IsShown()
		end
		check("own fix: and the game's bars showing again does not show Flat UI's", not back)
		check("own fix: a failed build at login leaves the game's buttons on the range hook", W.wrappers and W.wrappers[env.ActionButton_UpdateRangeIndicator] == true, tostring(W.hooks))
		check("own fix: a build that failed after a login in a fight puts the game's buttons on the range hook", (function()
			local V = T.world()
			local venv = V.env
			venv.ActionButton_UpdateRangeIndicator = function() end
			local make = venv.CreateFrame
			venv.CreateFrame = function(kind, name, ...)
				local f = make(kind, name, ...)
				if name == "FlatUIBar8Button12" then
					V.rawOf[f].protected = false
				end
				return f
			end
			local wrap = venv.SecureHandlerWrapScript
			venv.SecureHandlerWrapScript = function(frame, ...)
				local raw = V.rawOf[frame]
				local before = raw.protected
				raw.protected = true
				local r = wrap(frame, ...)
				raw.protected = before
				return r
			end
			V.setCombat(true)
			T.login(V)
			V.setCombat(false)
			V.fire("PLAYER_REGEN_ENABLED")
			V.frame(3)
			return V.ns.OwnStatus("buttons"):find("stopped", 1, true) ~= nil and V.wrappers and V.wrappers[venv.ActionButton_UpdateRangeIndicator] == true
		end)())
	end
	do
		local W = T.login(T.world())
		check("own fix: a finished build is missing nothing", W.ns.OwnMissing() == nil, tostring(W.ns.OwnMissing()))
		local env = W.env
		local last = env.FlatUIBar8Button12
		last:SetAttribute("action", 7)
		check("own fix: a wrong action number is told", (W.ns.OwnMissing() or ""):find("has no action", 1, true) ~= nil)
		last:SetAttribute("action", 180)
		check("own fix: the right action number is not told", W.ns.OwnMissing() == nil, tostring(W.ns.OwnMissing()))
		env.FlatUIBar1:SetAttribute("flatui-page", nil)
		check("own fix: a missing page is told", (W.ns.OwnMissing() or ""):find("has no page", 1, true) ~= nil)
		env.FlatUIBar1:SetAttribute("flatui-page", 1)
		env.FlatUIBar8:SetAttribute("flatui-routed", nil)
		check("own fix: keys not routed are told", (W.ns.OwnMissing() or ""):find("no key routing", 1, true) ~= nil)
		env.FlatUIBar8:SetAttribute("flatui-routed", 0)
		env.FlatUIOwnHeader:SetAttribute("flatui-locked", nil)
		check("own fix: a lock state not set is told", (W.ns.OwnMissing() or ""):find("lock state", 1, true) ~= nil)
	end
	do
		local W = T.login(T.world())
		W.ns.Set("actionbars.own", "game")
		W.fire("PLAYER_ENTERING_WORLD", false, false)
		W.frame(2)
		local secure = 0
		for _, w in ipairs(W.gameWritesByAddon()) do
			if w.method == "SetAlpha" and w.args[1] == 1 and w.secure == true then
				secure = secure + 1
			end
		end
		check("own fix: the game's bars are put back through the header, not by plain calls", secure == 8, secure)
	end

	-- 13. A native key reaches the twin's slot, which is Flat UI's slot in every state.
	do
		local W = T.login(T.world())
		local ok = true
		for _, combat in ipairs({ false, true }) do
			W.setCombat(combat)
			for _, state in ipairs(T.STATES) do
				W.setBarState(state)
				local before = #W.used
				W.press("ACTIONBUTTON", 3)
				local rec = W.used[#W.used]
				ok = ok and #W.used == before + 1 and rec.slot == T.btn(W, 1, 3):GetAttribute("action") and rec.frame == "ActionButton3" and rec.isKeyPress == true
				W.setBarState(T.RESET)
			end
		end
		W.setCombat(false)
		check("ownbars: a key press casts the twin's slot, equal to Flat UI's in every state", ok and #W.refused == 0 and T.sane(W))
	end

	-- 14. Keys on flyout slots go to Flat UI's button as clicks.
	do
		local W = T.world()
		T.flyout(W, 3)
		T.login(W)
		check("ownbars: a key on a flyout slot of the main bar is a click binding on the Flat UI button", W.bindings.FlatUIBar1 and W.bindings.FlatUIBar1["3"]
			and W.bindings.FlatUIBar1["3"].button == "FlatUIBar1Button3" and W.ns.OwnStatus("flyoutkeys") == "Keys on flyout slots: sent to Flat UI's buttons, 1 key.")
		local used = #W.used
		W.press("ACTIONBUTTON", 3)
		check("ownbars: the key opens the flyout on the Flat UI button and not on the twin", W.flyoutOn() == "FlatUIBar1Button3" and #W.used == used)
		local twin = false
		for _, f in ipairs(W.flyouts) do
			twin = twin or f.button == "ActionButton3"
		end
		check("ownbars: the flyout was never opened on a twin", not twin)
		W.press("ACTIONBUTTON", 3)
		W.setCombat(true)
		W.setBarState({ bonus = 1 })
		check("ownbars: in combat a bonus page with a spell on slot 3 clears the binding", W.bindings.FlatUIBar1["3"] == nil)
		W.press("ACTIONBUTTON", 3)
		check("ownbars: and the key casts through the twin", W.used[#W.used].slot == 75 and W.used[#W.used].frame == "ActionButton3")
		W.setBarState({ bonus = 0 })
		check("ownbars: back on page 1 the binding returns", W.bindings.FlatUIBar1["3"] and W.bindings.FlatUIBar1["3"].button == "FlatUIBar1Button3")
		W.setCombat(false)
		W.frame(1)
		W.keys.MULTIACTIONBAR3BUTTON5 = "ALT-5"
		T.flyout(W, 29)
		W.fire("ACTIONBAR_SLOT_CHANGED", 29)
		W.frame(2)
		check("ownbars: a flyout on a bar 4 slot routes that bar's key after the slot changed out of combat", W.bindings.FlatUIBar4 and W.bindings.FlatUIBar4["ALT-5"]
			and W.bindings.FlatUIBar4["ALT-5"].button == "FlatUIBar4Button5")
		W.press("MULTIACTIONBAR3BUTTON", 5)
		check("ownbars: and the key opens it on the Flat UI button", W.flyoutOn() == "FlatUIBar4Button5")
		W.press("MULTIACTIONBAR3BUTTON", 5)
		W.keys.MULTIACTIONBAR3BUTTON6 = "ALT-6"
		W.setCombat(true)
		T.flyout(W, 30)
		W.fire("ACTIONBAR_SLOT_CHANGED", 30)
		W.frame(3)
		check("ownbars: a flyout placed in combat is not routed in combat", not (W.bindings.FlatUIBar4 and W.bindings.FlatUIBar4["ALT-6"]))
		local before = W.executed
		W.setCombat(false)
		W.frame(3)
		check("ownbars: it is routed once after combat", W.bindings.FlatUIBar4["ALT-6"] and W.bindings.FlatUIBar4["ALT-6"].button == "FlatUIBar4Button6" and W.executed - before == 1,
			tostring(W.executed - before))
		W.slots[29] = nil
		W.fire("ACTIONBAR_SLOT_CHANGED", 29)
		W.frame(2)
		check("ownbars: a flyout taken off the slot gives its key back", W.bindings.FlatUIBar4["ALT-5"] == nil and T.sane(W))
	end

	-- 15. The slot watch and the status.
	do
		local W = T.login(T.world())
		local heard = 0
		W.ns.OnOwnSlots(function() heard = heard + 1 end)
		W.advance(0.2)
		check("ownbars: the slot watch hears nothing while the slots stand", heard == 0)
		W.setBarState({ bonus = 1 })
		W.advance(0.1)
		check("ownbars: a page change is heard within one watch", heard == 1)
		W.advance(0.3)
		check("ownbars: and once", heard == 1)
		local built = 0
		W.ns.OnOwnBuilt(function() built = built + 1 end)
		check("ownbars: a listener for the build runs at once when it is built", built == 1)
		check("ownbars: the page and key lines", W.ns.OwnStatus("page") == "Main bar page: 7, the game's 7." and W.ns.OwnStatus("keys") == "Key presses: through the game's buttons."
			and W.ns.OwnStatus("flyoutkeys") == nil and W.ns.OwnStatus("error") == nil)
		W.setCombat(true)
		check("ownbars: no page line in combat", W.ns.OwnStatus("page") == nil)
		W.setCombat(false)
		local B = T.world({ combat = true })
		local late = 0
		B.ns.OnOwnBuilt(function() late = late + 1 end)
		B.login()
		B.setCombat(false)
		B.frame(2)
		check("ownbars: a listener made before the build runs when it is built, once", late == 1)
	end
end
-- >>> ownbars (end)
-- >>> ownpaint (begin)
-- The paint of Flat UI's own action buttons (ownpaint:, FlatUI/OwnPaint.lua). The buttons, the slot watch and the bar numbers are OwnBars.lua's; here they are
-- stubs of the contract (ns.OwnOn, OwnButtons, OwnBar, OwnSlot, OwnCommand, OwnTwin, OnOwnSlots), made by hand on the simulated client layer.
do
	local OP = {}
	-- A world with twelve buttons on bar 1 and two on bar 2, made as OwnBars.lua makes them, and the stubs of the contract.
	function OP.world(opts)
		opts = opts or {}
		local W = newWorld({ own = true, saved = { options = { ["actionbars.own"] = "game" } } })
		local env, ns = W.env, W.ns
		-- The other modules hear the same events: the combat numbers read the clock.
		env.GetTime = function() return W.now end
		local header = env.CreateFrame("Frame", nil, env.UIParent, "SecureHandlerBaseTemplate")
		local list, info, subs = {}, setmetatable({}, { __mode = "k" }), {}
		local commands = { [1] = "ACTIONBUTTON", [2] = "MULTIACTIONBAR1BUTTON" }
		local twins = { [1] = "ActionButton", [2] = "MultiBarBottomLeftButton" }
		for bar, count in ipairs({ 12, 2 }) do
			for index = 1, count do
				local name = "FlatUIBar" .. bar .. "Button" .. index
				local button = env.CreateFrame("CheckButton", name, env.UIParent, "ActionButtonTemplate, SecureActionButtonTemplate")
				header:SetFrameRef("b", button)
				header:Execute(("local b = self:GetFrameRef('b') b:SetAttribute('type', 'none') b:SetAttribute('useOnKeyDown', false) b:SetAttribute('action', %d) b:SetAttribute('type', 'action')")
					:format(bar == 1 and index or 60 + index))
				button:RegisterForClicks("AnyUp")
				list[#list + 1] = button
				info[button] = { bar = bar, index = index }
			end
		end
		OP.on = opts.off ~= true
		ns.OwnOn = function() return OP.on end
		ns.OwnButtons = function() return list end
		ns.OwnBar = function(button) local x = info[button] if x then return x.bar, x.index end end
		ns.OwnSlot = function(button) return button:GetAttribute("action") end
		ns.OwnCommand = function(button) local x = info[button] return x and (commands[x.bar] .. x.index) end
		ns.OwnTwin = function(button) local x = info[button] return x and env[twins[x.bar] .. x.index] end
		ns.OnOwnSlots = function(fn) subs[#subs + 1] = fn end
		-- The slot watch of OwnBars.lua: one look at the slots, the subscribers told when one moved.
		local seen = {}
		function OP.watch()
			local moved = false
			for _, button in ipairs(list) do
				local slot = button:GetAttribute("action")
				if seen[button] ~= slot then
					moved = moved or seen[button] ~= nil
					seen[button] = slot
				end
			end
			if moved then
				for _, fn in ipairs(subs) do fn() end
			end
		end
		OP.watch()
		return W, list, env, ns
	end
	-- The region and the frame behind a proxy.
	function OP.raw(W, x) return W.rawOf[x] or x end
	function OP.login(W)
		W.login()
		W.frame(2)
	end
	function OP.tip(W)
		local tip = { sets = {}, hides = 0 }
		function tip:SetOwner(owner, anchor) self.owner, self.anchor = owner, anchor end
		function tip:GetOwner() return self.owner end
		function tip:SetAction(slot) self.sets[#self.sets + 1] = slot return true end
		function tip:Hide() self.owner = nil self.hides = self.hides + 1 end
		W.env.GameTooltip = tip
		W.env.GameTooltip_SetDefaultAnchor = function(t, owner) t:SetOwner(owner, "ANCHOR_NONE") end
		W.env.GameTooltipDefaultContainer = { GetPoint = function() return "BOTTOMRIGHT", W.env.UIParent, "BOTTOMRIGHT", -9, 85 end }
		return tip
	end
	function OP.colour(r, rr, gg, bb)
		local v = r.vertex or {}
		local function same(a, b) return a ~= nil and math.abs(a - b) < 1e-6 end
		return same(v[1], rr) and same(v[2], gg) and same(v[3], bb)
	end
	function OP.clean(W, ns, label)
		check("ownpaint: " .. label .. " raised nothing, broke nothing and failed nowhere", #W.errors == 0 and #W.violations == 0 and #W.snippetErrors == 0 and select(1, ns.OwnPaintError()) == 0,
			table.concat(W.errors, "|") .. "/" .. table.concat(W.violations, "|") .. "/" .. tostring(select(2, ns.OwnPaintError())))
	end

	-- 1. Icon, count, macro name and hotkey of a slot.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		W.slots[3] = { texture = 4242, kind = "macro", id = 77, text = "Blast", count = 7, usable = true, noMana = false, inRange = true, checksRange = true }
		W.slots[4] = {}
		W.keys.ACTIONBUTTON5, W.keys.ACTIONBUTTON6, W.keys.ACTIONBUTTON7 = nil, nil, nil
		W.keys["CLICK FlatUIBar1Button5:LeftButton"] = "F5"
		W.slots[7].checksRange = false
		OP.login(W)
		local b3, b4, b5, b6, b7 = list[3], list[4], list[5], list[6], list[7]
		check("ownpaint: the icon shows the slot's texture", R(b3.icon).file == 4242 and R(b3.icon).shown == true and R(list[1].icon).file == 100001)
		check("ownpaint: the count and the macro name are the slot's", R(b3.Count).text == "7" and R(b3.Name).text == "Blast" and R(list[1].Name).text == "")
		check("ownpaint: an empty slot hides the icon and clears the texts", R(b4.icon).shown == false and R(b4.Count).text == "" and R(b4.Name).text == "")
		check("ownpaint: the hotkey is the key of the twin's command", R(b3.HotKey).text == "3" and R(b3.HotKey).shown == true and ns.OwnState(b3).hotkey == "3")
		check("ownpaint: with none, the key of a click on the button is the hotkey", R(b5.HotKey).text == "F5" and ns.OwnState(b5).hotkey == "F5")
		check("ownpaint: with no key the range dot shows while the slot checks range", ns.OwnState(b6).hotkey == "" and R(b6.HotKey).text ~= "" and R(b6.HotKey).shown == true)
		check("ownpaint: and hides when the slot checks no range", R(b7.HotKey).shown == false and ns.OwnState(b7).checksRange == false)
		W.keys.MULTIACTIONBAR1BUTTON2 = "CTRL-2"
		W.fire("UPDATE_BINDINGS")
		check("ownpaint: the hotkey of a second bar is its command's", R(list[14].HotKey).text == "CTRL-2")
		W.keys["CLICK FlatUIBar1Button6:LeftButton"] = "F6"
		W.fire("UPDATE_BINDINGS")
		check("ownpaint: a new binding changes the text", R(b6.HotKey).text == "F6")
		check("ownpaint: the state holds the slot, the texture and the flags", (function()
			local st = ns.OwnState(b3)
			return st.slot == 3 and st.has == true and st.texture == 4242 and st.empty == false and st.grid == false and st.checked == false and st.equipped == false and st.proc == false
				and ns.OwnState(b4).empty == true and ns.OwnState(b4).has == false
		end)())
		check("ownpaint: a frame that is not a button has no state", ns.OwnState(env.UIParent) == nil and ns.OwnState(env.ActionButton1) == nil)
		check("ownpaint: no field is written on a button by Flat UI", (function()
			for _, w in ipairs(W.fieldWrites) do
				if w.by == "addon" then return false end
			end
			return #W.gameWritesByAddon() == 0
		end)())
		OP.clean(W, ns, "slot, texts and keys")
	end

	-- Hotkey text on Flat UI's own buttons.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		for key, value in pairs({ KEY_BUTTON4 = "Mouse Button 4", KEY_NUMPAD1 = "Num Pad 1", SHIFT_KEY_TEXT_ABBR = "s" }) do env[key] = value end
		env.GetBindingText = function(key) return (key:gsub("SHIFT%-", "s-"):gsub("^BUTTON4$", "Mouse Button 4")) end
		W.keys.ACTIONBUTTON3, W.keys.ACTIONBUTTON4 = "BUTTON4", "SHIFT-Num Pad 1"
		OP.login(W)
		check("hotkey text: an own button shows the short text", R(list[3].HotKey).text == "M4" and R(list[4].HotKey).text == "s-N1" and ns.OwnState(list[3]).hotkey == "M4", tostring(R(list[3].HotKey).text))
		ns.Set("actionbars.hotkeyText", "game")
		W.flush()
		check("hotkey text: game repaints an own button with the long text", R(list[3].HotKey).text == "Mouse Button 4", tostring(R(list[3].HotKey).text))
		ns.Set("actionbars.hotkeyText", "short")
		W.flush()
		W.fire("UPDATE_BINDINGS")
		check("hotkey text: a repaint after a binding change keeps the short text", R(list[3].HotKey).text == "M4" and R(list[1].HotKey).text == "1")
		OP.clean(W, ns, "hotkey text")
	end

	-- 2. Cooldown, charges and loss of control.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		local cab = env.C_ActionBar
		local baseCooldown = cab.GetActionCooldown
		cab.GetActionCooldown = function(n) local info = baseCooldown(n) info.isOnGCD = W.slots[n].gcd == true return info end
		OP.login(W)
		local function calls(frame) return R(frame).cd.calls end
		check("ownpaint: no cooldown shows nothing", calls(list[8].cooldown).SetCooldownFromDurationObject == nil and (calls(list[8].cooldown).Clear or 0) >= 1 and R(list[8].cooldown).shown == false)
		W.slots[8].cd = { active = true, start = 10, duration = 30 }
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		check("ownpaint: an active cooldown is a duration object on the cooldown", calls(list[8].cooldown).SetCooldownFromDurationObject == 1 and R(list[8].cooldown).cd.sweep.kind == "object"
			and R(list[8].cooldown).cd.sweep.info.kind == "cooldown" and R(list[8].cooldown).cd.sweep.info.slot == 8 and ns.OwnState(list[8]).cdActive == true)
		check("ownpaint: and the other buttons are not swept", calls(list[9].cooldown).SetCooldownFromDurationObject == nil and ns.OwnState(list[9]).cdActive == false)
		W.slots[8].cd = { active = false }
		W.fire("SPELL_UPDATE_COOLDOWN")
		check("ownpaint: when it ends the cooldown is cleared", R(list[8].cooldown).shown == false and R(list[8].cooldown).cd.sweep == nil and ns.OwnState(list[8]).cdActive == false)
		W.slots[8].gcd, W.slots[8].cd = true, { active = true, start = 1, duration = 1.5 }
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		check("ownpaint: the state says whether the cooldown is the global one", ns.OwnState(list[8]).cdOnGCD == true and ns.OwnState(list[9]).cdOnGCD == false)
		W.slots[9].charges = { active = true, max = 2, current = 1, start = 1, duration = 8 }
		W.fire("SPELL_UPDATE_CHARGES")
		check("ownpaint: a recharging action sweeps its charge cooldown", R(list[9].chargeCooldown).cd.sweep.info.kind == "charges" and calls(list[9].chargeCooldown).SetCooldownFromDurationObject == 1
			and calls(list[9].cooldown).SetCooldownFromDurationObject == nil)
		W.slots[10].loc = { active = true }
		W.fire("LOSS_OF_CONTROL_ADDED")
		check("ownpaint: loss of control sweeps its cooldown, by the duration when the game gives no plain answer", R(list[10].lossOfControlCooldown).cd.sweep ~= nil
			and R(list[10].lossOfControlCooldown).cd.sweep.info.kind == "loc" and R(list[11].lossOfControlCooldown).cd.sweep == nil)
		cab.GetActionLossOfControlCooldownInfo = function(n)
			local loc = W.slots[n].loc or {}
			return { startTime = 0, duration = 0, modRate = 1, isActive = loc.active == true, shouldReplaceNormalCooldown = loc.replace == true }
		end
		W.slots[10].loc = { active = false }
		W.fire("LOSS_OF_CONTROL_UPDATE")
		check("ownpaint: with a plain answer an ended loss of control is cleared", R(list[10].lossOfControlCooldown).cd.sweep == nil)
		W.slots[8].loc = { active = true, replace = true }
		W.fire("LOSS_OF_CONTROL_UPDATE")
		check("ownpaint: a loss of control that replaces the cooldown leaves the normal one clear", R(list[8].cooldown).cd.sweep == nil and R(list[8].lossOfControlCooldown).cd.sweep ~= nil)
		-- A fight with the cooldowns withheld.
		W.slots[8].loc = nil
		W.secretCooldowns = true
		W.setCombat(true)
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		W.fire("SPELL_UPDATE_CHARGES")
		W.fire("LOSS_OF_CONTROL_UPDATE")
		W.fire("ACTIONBAR_SLOT_CHANGED", 9)
		check("ownpaint: with withheld cooldowns no number is set and a plain flag still decides", (function()
			for _, button in ipairs(list) do
				for _, key in ipairs({ "cooldown", "chargeCooldown", "lossOfControlCooldown" }) do
					if calls(button[key]).SetCooldown ~= nil then return false end
				end
			end
			return R(list[9].chargeCooldown).cd.sweep ~= nil and R(list[8].cooldown).cd.sweep ~= nil and ns.OwnState(list[8]).cdActive == true
		end)())
		check("ownpaint: and a withheld display count is passed on as it is", rawequal(R(list[9].Count).text, SECRET))
		W.setCombat(false)
		OP.clean(W, ns, "cooldowns in a fight")
	end

	-- 3. Usable and range colours, and the painters.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		OP.login(W)
		W.fire("ACTION_USABLE_CHANGED", { { slot = 11, usable = false, noMana = false } })
		check("ownpaint: an action that cannot be used is grey", OP.colour(R(list[11].icon), 0.4, 0.4, 0.4) and ns.OwnState(list[11]).usable == false)
		W.fire("ACTION_USABLE_CHANGED", { { slot = 11, usable = false, noMana = true } })
		check("ownpaint: one short of power is blue", OP.colour(R(list[11].icon), 0.5, 0.5, 1) and ns.OwnState(list[11]).noMana == true)
		W.fire("ACTION_USABLE_CHANGED", { { slot = 11, usable = true, noMana = false } })
		check("ownpaint: a usable one is white", OP.colour(R(list[11].icon), 1, 1, 1) and OP.colour(R(list[1].icon), 1, 1, 1))
		W.slots[2].usable, W.slots[2].noMana = false, false
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		check("ownpaint: a slot change asks the game again", OP.colour(R(list[2].icon), 0.4, 0.4, 0.4))
		W.slots[2].usable = true
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		W.fire("ACTION_RANGE_CHECK_UPDATE", 12, false, true)
		check("ownpaint: out of range the hotkey is red", OP.colour(R(list[12].HotKey), 1, 0.1, 0.1) and ns.OwnState(list[12]).inRange == false and ns.OwnState(list[12]).checksRange == true)
		check("ownpaint: and the icon keeps its colour without a tint", OP.colour(R(list[12].icon), 1, 1, 1))
		W.fire("ACTION_RANGE_CHECK_UPDATE", 12, true, true)
		check("ownpaint: back in range it is the game's grey", OP.colour(R(list[12].HotKey), 0.6, 0.6, 0.6))
		W.slots[12].inRange = false
		W.fire("PLAYER_TARGET_CHANGED")
		check("ownpaint: a new target asks for the range of every slot", OP.colour(R(list[12].HotKey), 1, 0.1, 0.1) and ns.OwnState(list[12]).inRange == false and ns.OwnState(list[1]).inRange == true)
		W.slots[12].inRange = true
		W.fire("PLAYER_TARGET_CHANGED")
		local seen = {}
		check("ownpaint: a painter is taken", ns.OwnPainter("icon", function(button, st)
			seen[#seen + 1] = st
			if st.inRange == false then return 1, 0.3, 0.3 end
			if st.cdActive then return 0.5, 0.5, 0.5, 0.9 end
			return nil
		end) == true)
		W.fire("ACTION_RANGE_CHECK_UPDATE", 12, false, true)
		check("ownpaint: a painter's colour tints the icon out of range", OP.colour(R(list[12].icon), 1, 0.3, 0.3) and OP.colour(R(list[1].icon), 1, 1, 1))
		W.fire("ACTION_RANGE_CHECK_UPDATE", 12, true, true)
		check("ownpaint: and nil from the painter leaves the game's colour", OP.colour(R(list[12].icon), 1, 1, 1))
		check("ownpaint: the painter is given the state of the button", (function()
			local st = ns.OwnState(list[12])
			for _, given in ipairs(seen) do
				if given == st then return true end
			end
			return false
		end)())
		W.slots[8].cd = { active = true, start = 1, duration = 20 }
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		check("ownpaint: a painter sees a cooldown, and may give an opacity", OP.colour(R(list[8].icon), 0.5, 0.5, 0.5) and R(list[8].icon).vertex[4] == 0.9)
		W.slots[8].cd = { active = false }
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		ns.OwnPainter("hotkey", function(button, st) if st.hotkey == "3" then return 0, 1, 0 end end)
		check("ownpaint: a hotkey painter colours the text", OP.colour(R(list[3].HotKey), 0, 1, 0) and OP.colour(R(list[4].HotKey), 0.6, 0.6, 0.6))
		W.fire("ACTION_RANGE_CHECK_UPDATE", 3, false, true)
		check("ownpaint: and wins over the red", OP.colour(R(list[3].HotKey), 0, 1, 0))
		check("ownpaint: only the three parts take a painter", ns.OwnPainter("proc", function() end) == false and ns.OwnPainter("icon", "x") == false)
		OP.clean(W, ns, "colours and painters")
	end

	-- 4. Checked, equipped, and the repaint after a click.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		OP.login(W)
		W.slots[1].current = true
		W.fire("ACTIONBAR_UPDATE_STATE")
		check("ownpaint: the current action is checked", R(list[1]).checked == true and ns.OwnState(list[1]).checked == true and R(list[2]).checked == false)
		W.slots[1].current = false
		W.slots[2].autoRepeat = true
		W.fire("START_AUTOREPEAT_SPELL")
		check("ownpaint: so is one on auto repeat, and the first one is not", R(list[1]).checked == false and R(list[2]).checked == true)
		W.slots[2].autoRepeat = false
		W.fire("STOP_AUTOREPEAT_SPELL")
		W.slots[2].equipped = true
		W.fire("UPDATE_INVENTORY_ALERTS")
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		check("ownpaint: an equipped item has the green border", R(list[2].Border).shown == true and OP.colour(R(list[2].Border), 0, 1, 0) and R(list[2].Border).vertex[4] == 0.5
			and ns.OwnState(list[2]).equipped == true)
		W.slots[2].equipped = false
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		check("ownpaint: and it goes with the item", R(list[2].Border).shown == false and ns.OwnState(list[2]).equipped == false)
		check("ownpaint: a click is handled", W.click("FlatUIBar1Button1") == true)
		check("ownpaint: the click's flip stays until the next frame", R(list[1]).checked == true)
		W.tick()
		check("ownpaint: the next frame paints the button again", R(list[1]).checked == false)
		OP.clean(W, ns, "checked and equipped")
	end

	-- 5. Tooltip.
	do
		local W, list, env, ns = OP.world()
		OP.login(W)
		local tip = OP.tip(W)
		W.enter("FlatUIBar1Button3")
		check("ownpaint: the tooltip is that of the slot in the attribute, with the game's anchor", #tip.sets == 1 and tip.sets[1] == 3 and tip.owner == list[3] and tip.anchor == "ANCHOR_NONE")
		check("ownpaint: the button has no action field to read", list[3].action == nil)
		W.leave("FlatUIBar1Button3")
		check("ownpaint: leaving hides it", tip.owner == nil and tip.hides == 1)
		W.ownCVars.UberTooltips = false
		W.enter("FlatUIBar1Button4")
		check("ownpaint: without the large tooltips it anchors to the right of the button", tip.owner == list[4] and tip.anchor == "ANCHOR_RIGHT" and tip.sets[2] == 4)
		tip.owner = env.UIParent
		W.leave("FlatUIBar1Button4")
		check("ownpaint: and does not hide another owner's tooltip", tip.owner == env.UIParent and tip.hides == 1)
		OP.clean(W, ns, "tooltips")
	end

	-- 5b. Tooltip when the game withholds the box point, the slot or the owner, or its anchor raises.
	do
		local V = {}
		V.W, V.list, V.env, V.ns = OP.world()
		OP.login(V.W)
		V.tip = OP.tip(V.W)
		V.calls = 0
		V.anchor = function(t, owner) V.calls = V.calls + 1 t:SetOwner(owner, "ANCHOR_NONE") end
		V.env.GameTooltip_SetDefaultAnchor = V.anchor
		V.plain = V.env.GameTooltipDefaultContainer.GetPoint
		V.W.enter("FlatUIBar1Button3")
		check("ownpaint tooltip: a plain box point uses the game's anchor", V.calls == 1 and V.tip.anchor == "ANCHOR_NONE" and V.tip.owner == V.list[3] and V.tip.sets[1] == 3)
		V.W.leave("FlatUIBar1Button3")
		V.env.GameTooltipDefaultContainer.GetPoint = function() return SECRET, SECRET, SECRET, SECRET, SECRET end
		V.W.enter("FlatUIBar1Button3")
		check("ownpaint tooltip: a withheld box point skips the game's anchor and shows the tooltip right of the button", V.calls == 1 and V.tip.anchor == "ANCHOR_RIGHT" and V.tip.owner == V.list[3] and V.tip.sets[2] == 3)
		V.W.leave("FlatUIBar1Button3")
		V.env.GameTooltipDefaultContainer.GetPoint = V.plain
		V.env.GameTooltip_SetDefaultAnchor = function(t, owner) t:SetOwner(owner, "ANCHOR_NONE") error("attempt to compare a secret value", 0) end
		V.W.enter("FlatUIBar1Button4")
		check("ownpaint tooltip: an anchor that raises leaves the tooltip right of the button, counted as a failure", V.tip.anchor == "ANCHOR_RIGHT" and V.tip.sets[3] == 4
			and #V.W.errors == 0 and select(1, V.ns.OwnPaintError()) == 1, tostring(select(2, V.ns.OwnPaintError())))
		V.W.leave("FlatUIBar1Button4")
		V.env.GameTooltip_SetDefaultAnchor = V.anchor
		V.slotOf = V.ns.OwnSlot
		V.ns.OwnSlot = function() return SECRET end
		V.W.enter("FlatUIBar1Button5")
		check("ownpaint tooltip: a withheld slot shows the slot of the last paint", V.tip.sets[4] == 5 and V.tip.owner == V.list[5])
		V.ns.OwnSlot = V.slotOf
		V.hides = V.tip.hides
		V.tip.GetOwner = function() return SECRET end
		V.W.leave("FlatUIBar1Button5")
		check("ownpaint tooltip: a withheld owner on leave hides nothing and raises nothing", V.tip.hides == V.hides and #V.W.errors == 0 and #V.W.violations == 0)
	end

	-- 6. Paging: the buttons take the slots of the new page within one tick of the slot watch.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		local bar = env.CreateFrame("Frame", "OwnPaintBar", env.UIParent, "SecureHandlerStateTemplate")
		for index = 1, 12 do
			bar:SetFrameRef("b" .. index, list[index])
		end
		bar:SetAttribute("_onstate-page", [[
			local page = GetActionBarPage()
			if HasBonusActionBar() and page == 1 then page = GetBonusBarIndex() end
			for i = 1, 12 do self:GetFrameRef("b" .. i):SetAttribute("action", (page - 1) * 12 + i) end
		]])
		env.RegisterStateDriver(bar, "page", "[bonusbar:1] b1; 1")
		W.slots[75].texture = 5075
		OP.login(W)
		check("ownpaint: on page 1 the textures are those of slots 1 to 12", R(list[1].icon).file == 100001 and R(list[12].icon).file == 100012)
		W.setBarState({ bonus = 1 })
		check("ownpaint: until the slot watch looks nothing has moved", R(list[1].icon).file == 100001 and list[1]:GetAttribute("action") == 73)
		OP.watch()
		check("ownpaint: after the watch bar 1 shows the textures of slots 73 to 84", (function()
			for index = 1, 12 do
				if R(list[index].icon).file ~= W.slots[72 + index].texture or ns.OwnState(list[index]).slot ~= 72 + index then return false end
			end
			return R(list[3].icon).file == 5075
		end)())
		check("ownpaint: the hotkeys stay with the position and the second bar is untouched", R(list[3].HotKey).text == "3" and ns.OwnState(list[13]).slot == 61)
		W.setCombat(true)
		W.setBarState({ bonus = 0 })
		OP.watch()
		check("ownpaint: the same in a fight, back to page 1", R(list[1].icon).file == 100001 and R(list[3].icon).file == 100003 and ns.OwnState(list[12]).slot == 12)
		W.setCombat(false)
		OP.clean(W, ns, "paging")
	end

	-- 7. Proc.
	do
		local W, list, env, ns = OP.world()
		OP.login(W)
		local heard = {}
		ns.OnOwnProc(function(button, on) heard[#heard + 1] = { button, on } end)
		ns.OnOwnProc(function() error("a handler that fails") end)
		W.slots[1].overlay = true
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 501)
		check("ownpaint: a glow on the slot's spell tells the handlers, true", #heard == 1 and heard[1][1] == list[1] and heard[1][2] == true and ns.OwnState(list[1]).proc == true)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 501)
		check("ownpaint: and says nothing twice", #heard == 1)
		W.slots[1].overlay = false
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_HIDE", 501)
		check("ownpaint: the glow going tells them, false", #heard == 2 and heard[2][2] == false and ns.OwnState(list[1]).proc == false and ns.OwnState(list[2]).proc == false)
		W.slots[2] = { texture = 9, kind = "macro", id = 620, sub = "spell", usable = true, noMana = false, inRange = true, checksRange = true, count = 0 }
		W.fire("ACTIONBAR_SLOT_CHANGED", 2)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 620)
		check("ownpaint: a macro's spell counts", #heard == 3 and heard[3][1] == list[2] and heard[3][2] == true)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_HIDE", 620)
		W.slots[3] = { texture = 9, kind = "spell", id = 1, flyout = 44, usable = true, noMana = false, inRange = true, checksRange = true, count = 0 }
		env.FlyoutHasSpell = function(id, spell) return id == 44 and spell == 777 end
		W.fire("ACTIONBAR_SLOT_CHANGED", 3)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 888)
		check("ownpaint: a spell that is not in the flyout does nothing", #heard == 4 and ns.OwnState(list[3]).proc == false)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 777)
		check("ownpaint: a flyout's spell counts", #heard == 5 and heard[5][1] == list[3] and heard[5][2] == true)
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_HIDE", 777)
		check("ownpaint: and goes with the glow", #heard == 6 and heard[6][2] == false)
		W.slots[5].overlay = true
		ns.OwnRepaint(list[5])
		check("ownpaint: a full paint finds a glow that was already up", ns.OwnState(list[5]).proc == true and #heard == 7 and heard[7][1] == list[5])
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 99999)
		check("ownpaint: a glow on no button here changes nothing", #heard == 7)
		check("ownpaint: a handler that fails is counted, not raised", #W.errors == 0 and select(1, ns.OwnPaintError()) >= 1)
	end

	-- 8. Pressed look, from the twin's state.
	do
		local W, list, env, ns = OP.world()
		OP.login(W)
		local hooksBefore, hookCalls = #W.hookCalls, 0
		local base = env.hooksecurefunc
		env.hooksecurefunc = function(...) hookCalls = hookCalls + 1 return base(...) end
		W.press("ACTIONBUTTON", 2, "down")
		check("ownpaint: the twin is pushed by the key", env.ActionButton2:GetButtonState() == "PUSHED" and list[2]:GetButtonState() == "NORMAL")
		W.tick()
		check("ownpaint: the button is pushed on the next frame", list[2]:GetButtonState() == "PUSHED" and list[3]:GetButtonState() == "NORMAL")
		W.press("ACTIONBUTTON", 2, "up")
		W.tick()
		check("ownpaint: and let go when the key is", list[2]:GetButtonState() == "NORMAL")
		W.press("MULTIACTIONBAR1BUTTON", 1, "down")
		W.tick()
		check("ownpaint: a key of another bar pushes that bar's button", list[13]:GetButtonState() == "PUSHED" and list[2]:GetButtonState() == "NORMAL")
		W.press("MULTIACTIONBAR1BUTTON", 1, "up")
		W.tick()
		check("ownpaint: and releases it", list[13]:GetButtonState() == "NORMAL")
		list[4]:SetButtonState("PUSHED")
		W.tick()
		check("ownpaint: a button pushed by something else is left alone", list[4]:GetButtonState() == "PUSHED")
		list[4]:SetButtonState("NORMAL")
		list[6]:SetButtonState("PUSHED")
		W.press("ACTIONBUTTON", 6, "down")
		W.tick()
		W.press("ACTIONBUTTON", 6, "up")
		W.tick()
		check("ownpaint: a button already held is not let go by the release of a key", list[6]:GetButtonState() == "PUSHED")
		list[6]:SetButtonState("NORMAL")
		W.setBarState({ override = "skinned" })
		W.press("ACTIONBUTTON", 2, "down")
		W.tick()
		check("ownpaint: while the override bar is shown no button is pushed", list[2]:GetButtonState() == "NORMAL" and env.ActionButton2:GetButtonState() == "NORMAL")
		W.press("ACTIONBUTTON", 2, "up")
		W.setBarState({ override = false })
		W.advance(0.5)
		W.advance(0.5)
		W.press("ACTIONBUTTON", 5, "down")
		W.tick()
		local pushed = list[5]:GetButtonState() == "PUSHED"
		W.setBarState({ override = "skinned" })
		W.tick()
		check("ownpaint: a button pushed by a key is let go when the override bar comes up", pushed and list[5]:GetButtonState() == "NORMAL")
		W.setBarState({ override = false })
		W.advance(0.5)
		W.advance(0.5)
		W.press("ACTIONBUTTON", 5, "up")
		check("ownpaint: no function of the game is hooked while this runs", hookCalls == 0 and #W.hookCalls == hooksBefore, hookCalls .. "/" .. (#W.hookCalls - hooksBefore))
		env.hooksecurefunc = base
		OP.clean(W, ns, "pressed look")
	end

	-- 9. Empty buttons.
	do
		local W, list, env, ns = OP.world()
		local R = function(x) return OP.raw(W, x) end
		W.slots[4] = {}
		W.slots[9] = {}
		local mode = nil
		ns.OwnPainter("empty", function(button, st) return mode end)
		OP.login(W)
		check("ownpaint: with no opinion an empty button is drawn normal", R(list[4]).alpha == 1 and R(list[9]).alpha == 1 and R(list[1]).alpha == 1)
		mode = 0.3
		ns.OwnRepaint()
		check("ownpaint: faint is the painter's opacity, on the empty buttons only", R(list[4]).alpha == 0.3 and R(list[9]).alpha == 0.3 and R(list[1]).alpha == 1)
		mode = 0
		ns.OwnRepaint(list[4])
		check("ownpaint: hidden is alpha 0", R(list[4]).alpha == 0 and R(list[9]).alpha == 0.3)
		ns.OwnRepaint()
		W.setCursor({ type = "spell", id = 5 })
		check("ownpaint: while an action is on the cursor every empty button shows", R(list[4]).alpha == 1 and R(list[9]).alpha == 1 and ns.OwnState(list[4]).grid == true)
		W.setCursor(nil)
		check("ownpaint: and goes again when it is put down", R(list[4]).alpha == 0 and R(list[9]).alpha == 0 and ns.OwnState(list[4]).grid == false)
		W.slots[4] = { texture = 31, kind = "spell", id = 31, usable = true, noMana = false, inRange = true, checksRange = true, count = 0 }
		W.fire("ACTIONBAR_SLOT_CHANGED", 4)
		check("ownpaint: a button that gets an action is drawn normal at once", R(list[4]).alpha == 1 and R(list[4].icon).file == 31)
		W.setCombat(true)
		mode = 0.5
		W.slots[4] = {}
		W.fire("ACTIONBAR_SLOT_CHANGED", 4)
		W.setCursor({ type = "spell", id = 5 })
		check("ownpaint: in a fight a button shows at once while an action is dragged", R(list[4]).alpha == 1)
		W.setCursor(nil)
		check("ownpaint: and an empty button takes its opacity with nothing refused", R(list[4]).alpha == 0.5 and #W.violations == 0)
		W.setCombat(false)
		OP.clean(W, ns, "empty buttons")
		-- A painter may answer with a colour and the opacity last.
		local W2, list2, _, ns2 = OP.world()
		W2.slots[4] = {}
		ns2.OwnPainter("empty", function() return 1, 1, 1, 0.25 end)
		OP.login(W2)
		check("ownpaint: an opacity given as the fourth value of a colour is taken", OP.raw(W2, list2[4]).alpha == 0.25 and OP.raw(W2, list2[1]).alpha == 1)
	end

	-- 10. The calls this file never makes.
	do
		local W, list, env, ns = OP.world()
		local never = {}
		local function spy(name) return function() never[#never + 1] = name end end
		env.C_ActionBar.RegisterActionUIButton = spy("RegisterActionUIButton")
		env.C_ActionBar.EnableActionRangeCheck = spy("EnableActionRangeCheck")
		env.ActionButtonSpellAlertManager = { ShowAlert = spy("ShowAlert"), HideAlert = spy("HideAlert") }
		env.EnableActionRangeCheck = spy("EnableActionRangeCheck")
		OP.login(W)
		OP.tip(W)
		W.enter("FlatUIBar1Button1")
		for _, event in ipairs({ "ACTIONBAR_SLOT_CHANGED", "ACTIONBAR_UPDATE_STATE", "ACTIONBAR_UPDATE_COOLDOWN", "SPELL_UPDATE_COOLDOWN", "SPELL_UPDATE_CHARGES", "SPELL_UPDATE_ICON",
			"UPDATE_BINDINGS", "UPDATE_SHAPESHIFT_FORM", "PLAYER_MOUNT_DISPLAY_CHANGED", "PLAYER_TARGET_CHANGED", "ACTIONBAR_SHOWGRID", "ACTIONBAR_HIDEGRID", "PLAYER_ENTERING_WORLD" }) do
			W.fire(event)
		end
		W.fire("SPELL_ACTIVATION_OVERLAY_GLOW_SHOW", 501)
		W.click("FlatUIBar1Button1")
		W.tick()
		check("ownpaint: no registration, no alert and no range switch", #never == 0, table.concat(never, ","))
		check("ownpaint: nothing is written on a game frame, a twin or a bar", #W.gameWritesByAddon() == 0)
		check("ownpaint: no method of the game's mixin is named in the file", (function()
			local text = io.open(ADDON_DIR .. "/OwnPaint.lua", "rb"):read("*a")
			local code = text:gsub("%-%-[^\n]*", "")
			for _, word in ipairs({ ":Update(", ":UpdateAction(", ":UpdateFlyout(", ":SetShowGrid(", "RegisterActionUIButton", "ShowAlert", "EnableActionRangeCheck", "hooksecurefunc" }) do
				if code:find(word, 1, true) then return false, word end
			end
			return true
		end)())
		OP.clean(W, ns, "the never list")
	end

	-- 11. A world where the buttons are not in use, and one where they come later.
	do
		local W, list, env, ns = OP.world({ off = true })
		local R = function(x) return OP.raw(W, x) end
		OP.login(W)
		W.fire("ACTIONBAR_SLOT_CHANGED", 3)
		W.fire("ACTIONBAR_UPDATE_COOLDOWN")
		W.frame(3)
		check("ownpaint: with the buttons not in use nothing is painted and nothing is hooked", R(list[3].icon).file == nil and R(list[3]).hooks.OnEnter == nil and R(list[3]).alpha == 1, tostring(R(list[3].icon).file) .. "/" .. tostring(R(list[3]).hooks.OnEnter) .. "/" .. tostring(R(list[3]).alpha))
		check("ownpaint: a repaint that is asked for is refused", ns.OwnRepaint() == nil and R(list[3].icon).file == nil)
		OP.on = true
		W.fire("PLAYER_REGEN_ENABLED")
		check("ownpaint: when they come into use, the next first event paints them", R(list[3].icon).file == 100003 and R(list[3]).hooks.OnEnter ~= nil and #R(list[3]).hooks.PostClick == 1)
		OP.on = false
		W.slots[3].texture = 1
		W.fire("ACTIONBAR_SLOT_CHANGED", 3)
		check("ownpaint: and when they go out of use it stops", R(list[3].icon).file == 100003)
		OP.clean(W, ns, "a world with no buttons in use")
	end
end
-- >>> ownpaint (end)
-- >>> ownlook (begin)
-- Flat UI's look modules on its own action buttons (ownlook:): ActionBars.lua, ButtonText.lua, ButtonStates.lua, ButtonEffects.lua, ProcGlow.lua and
-- TaintScan.lua. OwnBars.lua and OwnPaint.lua are not in this tree, so the contract of design section 10 is stubbed here: ns.OwnOn, OwnButtons, OwnBar,
-- OwnSlot, OwnTwin, OnOwnSlots (B) and OwnPainter, OwnState, OwnRepaint, OnOwnProc (C). Two bars are made as B makes them: FlatUIBar1 and FlatUIBar2 with twelve
-- buttons each, `type` and `action` set through a header. Remove the stubs once B and C are merged; the checks then run against the real pieces.
do
	local L = { bars = { { "FlatUIBar1", "ActionButton" }, { "FlatUIBar2", "MultiBarBottomLeftButton" } } }
	local function near(a, b) return type(a) == "number" and math.abs(a - b) < 0.003 end
	local function same(c, r, g, b) return c ~= nil and near(c[1], r) and near(c[2], g) and near(c[3], b) end
	function L.stubs(W, S)
		local ns, env = W.ns, W.env
		ns.OwnOn = function() return S.on end
		ns.OwnButtons = function() return S.list end
		ns.OwnBar = function(button) local at = S.at[button] if at then return at[1], at[2] end end
		ns.OwnSlot = function(button) return button:GetAttribute("action") end
		ns.OwnTwin = function(button) local at = S.at[button] return at and env[L.bars[at[1]][2] .. at[2]] end
		ns.OwnPainter = function(part, fn) S.painters[part] = fn S.painterCalls = S.painterCalls + 1 end
		ns.OwnRepaint = function() S.repaints = S.repaints + 1 end
		ns.OwnState = function(button) return S.states[button] or {} end
		ns.OnOwnProc = function(fn) S.proc = fn end
		local heard = {}
		S.slotsFn = function() for _, fn in ipairs(heard) do fn() end end
		ns.OnOwnSlots = function(fn) heard[#heard + 1] = fn end
	end
	function L.state()
		return { on = true, list = {}, at = setmetatable({}, { __mode = "k" }), painters = {}, painterCalls = 0, repaints = 0, states = {} }
	end
	-- options: saved settings; more: world options; held: a function that runs before login. A world with the layer, the stubs and the two bars built.
	function L.world(options, more, held)
		local o = { own = true, saved = { options = options or {} } }
		if o.saved.options["actionbars.own"] == nil then
			o.saved.options["actionbars.own"] = "game"
		end
		for k, v in pairs(more or {}) do o[k] = v end
		local W = newWorld(o)
		local env = W.env
		local S = L.state()
		W.S = S
		L.stubs(W, S)
		local header = env.CreateFrame("Frame", "FlatUIOwnHeader", env.UIParent, "SecureHandlerBaseTemplate")
		for n, bar in ipairs(L.bars) do
			local frame = env.CreateFrame("Frame", bar[1], env.UIParent, "SecureHandlerStateTemplate")
			frame:SetSize(500, 40)
			frame:SetPoint("BOTTOM", env.UIParent, "BOTTOM", 0, 100 * n)
			for index = 1, 12 do
				local button = env.CreateFrame("CheckButton", bar[1] .. "Button" .. index, frame, "ActionButtonTemplate, SecureActionButtonTemplate")
				button:RegisterForClicks("AnyUp")
				button:SetSize(36, 36)
				button:SetPoint("LEFT", frame, "LEFT", (index - 1) * 40, 0)
				header:SetFrameRef("b", button)
				header:Execute(("local b = self:GetFrameRef('b') b:SetAttribute('type', 'none') b:SetAttribute('action', %d) b:SetAttribute('type', 'action')"):format((n == 1 and 0 or 60) + index))
				S.list[#S.list + 1] = button
				S.at[button] = { n, index }
			end
		end
		if held then held(W) end
		W.login()
		W.flush()
		W.advance(0)
		W.flush()
		return W
	end
	function L.button(W, bar, index) return W.env["FlatUIBar" .. bar .. "Button" .. index] end
	function L.quiet(W) return #W.violations == 0 and #W.errors == 0 end
	function L.listed(W, button)
		for _, found in ipairs(W.ns.ActionButtons()) do
			if found == button then return true end
		end
		return false
	end
	-- Only Flat UI's buttons are styled: the game's other bars are off.
	L.OWN = { ["actionbars.pet"] = false, ["actionbars.stance"] = false, ["actionbars.totem"] = false, ["actionbars.ability"] = false }
	function L.alone(extra)
		local options = {}
		for k, v in pairs(L.OWN) do options[k] = v end
		for k, v in pairs(extra or {}) do options[k] = v end
		return options
	end
	-- The hooks a world makes on the game's functions and tables, by name.
	function L.spy(W)
		W.hooked = {}
		local base = W.env.hooksecurefunc
		W.env.hooksecurefunc = function(object, name, hook)
			W.hooked[#W.hooked + 1] = (type(object) == "string" and object) or (object == W.env and name) or ("method:" .. tostring(name))
			return base(object, name, hook)
		end
		W.env.ActionButton_UpdateRangeIndicator = function() end
		W.env.ActionButton_ApplyCooldown = function() end
		local manager = { activeAlerts = {} }
		function manager:ShowAlert(button) self.activeAlerts[button] = 1 end
		function manager:HideAlert(button) self.activeAlerts[button] = nil end
		function manager:HasAlert(button) local has = self.activeAlerts[button] ~= nil return has, has and 0 or nil end
		W.env.ActionButtonSpellAlertManager = manager
	end
	function L.hooks(W)
		local n = 0
		for _, name in ipairs(W.hooked) do
			if name == "ActionButton_UpdateRangeIndicator" or name == "ActionButton_ApplyCooldown" or name == "method:ShowAlert" or name == "method:HideAlert" then n = n + 1 end
		end
		return n
	end

	-- The list, the groups and the slot.
	do
		local W = L.world(nil, nil, function(W)
			W.slots[7] = { kind = "item", id = 777, texture = 1, usable = true, count = 0 }
			W.slots[62] = { kind = "item", id = 888, texture = 2, usable = true, count = 0 }
		end)
		local b1, b2 = L.button(W, 1, 3), L.button(W, 2, 2)
		check("ownlook: ns.ActionButtons lists the buttons Flat UI built, once styled", L.listed(W, b1) and L.listed(W, b2) and L.listed(W, L.button(W, 2, 12)), #W.ns.ActionButtons())
		local twin = false
		for _, button in ipairs(W.ns.ActionButtons()) do
			if button == W.env.ActionButton3 or button == W.env.MultiBarBottomLeftButton2 then twin = true end
		end
		check("ownlook: and not the twins of the game's bars 1 to 8", not twin)
		check("ownlook: bar 1 is the main group and the other bars the extra group", W.ns.ActionButtonGroup(b1) == "main" and W.ns.ActionButtonGroup(b2) == "extra")
		check("ownlook: a button is styled with an outline like the game's", W.look(b1.icon) ~= nil and W.look(b2.icon) ~= nil)
		check("ownlook: the game's frame art is faded as on the game's buttons", W.rawOf[b1.NormalTexture].alpha == 0 and W.rawOf[b1.SlotArt].alpha == 0 and W.rawOf[b1.SlotBackground].alpha == 0)
		local seven = L.button(W, 1, 7)
		local kind, id = W.ns.ButtonAction(seven)
		check("ownlook: ButtonAction reads the slot of the action attribute, not a field", seven.action == nil and kind == "item" and id == 777, tostring(kind) .. tostring(id))
		local found = W.ns.ButtonsFor("item", 888)
		check("ownlook: ButtonsFor finds the button of a slot on bar 2", #found == 1 and found[1] == L.button(W, 2, 2), #found)
		check("ownlook: the module listens for a page or slot change", type(W.S.slotsFn) == "function" and #W.ns.ButtonsFor("item", 777) == 1)
		W.slots[7] = { kind = "item", id = 999, texture = 1, usable = true, count = 0 }
		W.S.slotsFn()
		check("ownlook: and the map of the buttons is made again when it comes", #W.ns.ButtonsFor("item", 777) == 0 and #W.ns.ButtonsFor("item", 999) == 1, #W.ns.ButtonsFor("item", 777) .. "/" .. #W.ns.ButtonsFor("item", 999))
		check("ownlook: nothing here raised a violation", L.quiet(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
		check("ownlook: no field was written on a button by the add-on", (function()
			for _, w in ipairs(W.fieldWrites) do if w.by == "addon" then return false end end
			return true
		end)())
	end

	-- Restyle action bars off: the game's look.
	do
		local W = L.world({ ["actionbars.enabled"] = false })
		local b = L.button(W, 1, 1)
		local normal, pushed = W.rawOf[b.NormalTexture], W.rawOf[b.PushedTexture]
		check("ownlook: with Restyle action bars off a button is not listed or outlined", not L.listed(W, b) and W.look(b.icon) == nil)
		check("ownlook: and wears the game's frame at 46 by 45", normal.atlas == "UI-HUD-ActionBar-IconFrame" and normal.width == 46 and normal.height == 45, tostring(normal.atlas) .. tostring(normal.width))
		check("ownlook: and the pushed frame", pushed.atlas == "UI-HUD-ActionBar-IconFrame-Down" and pushed.width == 46)
		check("ownlook: and the slot art, without the slot background", W.rawOf[b.SlotArt].shown == true and W.rawOf[b.SlotBackground].shown == false)
		check("ownlook: and the art is not faded", normal.alpha ~= 0)
		check("ownlook: and this is quiet", L.quiet(W))
	end

	-- Empty buttons.
	do
		local W = L.world({ ["actionbars.empty"] = "faint", ["actionbars.emptyAlpha"] = 40 }, nil, function(W) W.slots[1] = {} end)
		local b = L.button(W, 1, 1)
		local paint = W.S.painters.empty
		check("ownlook: the empty painter is given to OwnPaint", type(paint) == "function" and W.S.painterCalls >= 1)
		local r, g, bl, a = paint(b, { empty = true })
		check("ownlook: faint gives an empty button the opacity as the fourth value", r == 1 and g == 1 and bl == 1 and near(a, 0.4), tostring(a))
		check("ownlook: a button with a spell is left as it is", paint(b, { empty = false }) == nil)
		check("ownlook: and while an action is dragged", paint(b, { empty = true, grid = true }) == nil)
		W.env.ActionButton1:Show()
		check("ownlook: and while the game shows the twin of an empty slot (Always show buttons)", paint(b, { empty = true }) == nil)
		W.env.ActionButton1:Hide()
		check("ownlook: and the twin hidden again gives the faint look", near(select(4, paint(b, { empty = true })), 0.4))
		W.ns.Set("actionbars.empty", "hidden")
		check("ownlook: hidden gives alpha 0", select(4, paint(b, { empty = true })) == 0)
		W.ns.Set("actionbars.empty", "show")
		check("ownlook: Normal leaves the game's look", paint(b, { empty = true }) == nil)
		W.ns.Set("actionbars.empty", "hidden")
		W.ns.Set("actionbars.extra", false)
		check("ownlook: a bar group switched off is not painted", paint(L.button(W, 2, 1), { empty = true }) == nil and select(4, paint(b, { empty = true })) == 0)
		check("ownlook: the empty buttons of the game's own bars are not looked at for an own button", L.quiet(W))
	end

	-- Hotkey colour.
	do
		local W = L.world({ ["actionbars.hotkeyOwn"] = true, ["actionbars.hotkeyColour"] = "ff336699" })
		local b = L.button(W, 1, 1)
		local paint = W.S.painters.hotkey
		check("ownlook: the hotkey painter is given to OwnPaint", type(paint) == "function")
		check("ownlook: the own colour in range", same({ paint(b, { checksRange = true, inRange = true }) }, 0.2, 0.4, 0.6))
		check("ownlook: and when the button checks no range", same({ paint(b, { checksRange = false }) }, 0.2, 0.4, 0.6))
		check("ownlook: out of range leaves the game's red", paint(b, { checksRange = true, inRange = false }) == nil)
		W.ns.Set("actionbars.hotkeyShow", "side")
		check("ownlook: a bar group that shows no hotkeys is left to the game's look", paint(b, {}) == nil and same({ paint(L.button(W, 2, 1), {}) }, 0.2, 0.4, 0.6))
		W.ns.Set("actionbars.hotkeyShow", "all")
		W.ns.Set("actionbars.hotkeyOwn", false)
		check("ownlook: and with Own colour off", paint(b, {}) == nil)
	end
	do
		local W = L.world(nil)
		local before = W.S.repaints
		W.ns.Set("actionbars.hotkeyOwn", true)
		W.ns.ButtonTextChanged("actionbars.hotkeyOwn")
		check("ownlook: a change of the hotkey colour asks OwnPaint to paint again", W.S.repaints > before)
		local after = W.S.repaints
		W.ns.ButtonTextChanged("actionbars.hotkeySize")
		check("ownlook: and a size does not", W.S.repaints == after)
	end

	-- Icon colours and cooldowns.
	do
		local W = L.world({ ["actionbars.usableOwn"] = true, ["actionbars.rangeTint"] = true, ["actionbars.cdGrey"] = true })
		local b = L.button(W, 1, 1)
		local paint = W.S.painters.icon
		check("ownlook: the icon painter is given to OwnPaint", type(paint) == "function")
		check("ownlook: a usable spell keeps the game's look", paint(b, { has = true, usable = true, noMana = false, checksRange = true, inRange = true }) == nil)
		check("ownlook: not usable takes the own colour", same({ paint(b, { has = true, usable = false, noMana = false }) }, W.ns.Colour("actionbars.unusableColour")))
		check("ownlook: not enough power takes the power colour", same({ paint(b, { has = true, usable = false, noMana = true }) }, W.ns.Colour("actionbars.manaColour")))
		check("ownlook: out of range wins over usability", same({ paint(b, { has = true, usable = false, checksRange = true, inRange = false }) }, W.ns.Colour("actionbars.rangeColour")))
		check("ownlook: a button that checks no range is not tinted", paint(b, { has = true, usable = true, checksRange = false, inRange = false }) == nil)
		local icon = W.rawOf[b.icon]
		paint(b, { has = true, usable = true, cdActive = true, cdOnGCD = false })
		check("ownlook: a cooldown greys the icon", icon.desaturated == true, tostring(icon.desaturated))
		paint(b, { has = true, usable = true, cdActive = true, cdOnGCD = true })
		check("ownlook: the global cooldown does not", icon.desaturated == false)
		paint(b, { has = true, usable = true, cdActive = true, cdOnGCD = false })
		W.ns.Set("actionbars.cdGrey", false)
		paint(b, { has = true, usable = true, cdActive = true, cdOnGCD = false })
		check("ownlook: and with Grey out icon on cooldown off the icon is given back", icon.desaturated == false)
		W.ns.Set("actionbars.enabled", false)
		check("ownlook: with Restyle action bars off the icon painter gives the game's look", paint(b, { has = true, usable = false, noMana = false }) == nil)
		check("ownlook: the icon painter raised nothing", L.quiet(W))
		check("ownlook: a withheld usability says so in the status", (function()
			W.ns.Set("actionbars.enabled", true)
			paint(b, { has = true, usable = nil })
			return W.status():find("game withholds whether an action can be used", 1, true) ~= nil
		end)())
	end
	do
		local W = L.world({ ["actionbars.sweep"] = false, ["actionbars.sweepOwn"] = true, ["actionbars.sweepAlpha"] = 50, ["actionbars.cdFont"] = "large" })
		local cd = W.rawOf[L.button(W, 1, 1).cooldown].cd
		check("ownlook: the sweep rows are set on the cooldown of a button of Flat UI's own", cd.drawSwipe == false and cd.swipeColour ~= nil and near(cd.swipeColour[4], 0.5) and cd.font == "NumberFontNormalLarge",
			tostring(cd.drawSwipe) .. tostring(cd.font))
		check("ownlook: on a button of bar 2 too", W.rawOf[L.button(W, 2, 5).cooldown].cd.drawSwipe == false)
		check("ownlook: the buttons are painted again after a change of those rows", W.S.repaints >= 1)
		local before = W.S.repaints
		W.ns.ButtonStatesChanged("actionbars.sweep")
		W.advance(0)
		check("ownlook: and again on the next change", W.S.repaints > before)
	end

	-- Nothing of the game's button code is followed while only Flat UI's buttons are styled.
	do
		local W = L.world(L.alone(), nil, L.spy)
		W.ns.ProcGlowStart({ id = "ol0001", name = "x", lights = { 5 } })
		W.advance(0.3)
		check("ownlook: only Flat UI's buttons styled: no hook on the range or cooldown function or the alert manager", L.hooks(W) == 0, table.concat(W.hooked, ","))
		check("ownlook: and OwnLookOnly says so", W.ns.OwnLookOnly() == true)
		local X = L.world(nil, nil, L.spy)
		check("ownlook: with the pet bar styled too the hooks are made", L.hooks(X) > 0 and X.ns.OwnLookOnly() == false, #X.hooked)
	end

	-- Chosen but not built yet (a login in a fight): the hooks are not made either.
	do
		local W = L.world(L.alone(), nil, function(W)
			W.S.on = false
			W.ns.OwnWanted = function() return true end
			L.spy(W)
		end)
		check("own fix: with Flat UI's buttons chosen and not built yet no hook is made", L.hooks(W) == 0 and W.ns.OwnLookOnly() == true, table.concat(W.hooked, ","))
		local X = L.world(L.alone(), nil, function(X)
			X.S.on = false
			X.ns.OwnWanted = function() return false end
			L.spy(X)
		end)
		check("own fix: and with the game's buttons chosen they are", L.hooks(X) > 0 and X.ns.OwnLookOnly() == false)
	end

	-- Proc: the game's glow, the border or nothing, and one glow frame.
	do
		local function glowFrames(W, button)
			local n, last = 0, nil
			for _, candidate in ipairs(W.addonFrames) do
				local raw = W.rawOf[candidate]
				local point = raw and raw.points and raw.points[1]
				if point ~= nil and point[1] == "CENTER" and W.rawOf[point[2]] == W.rawOf[button] then
					n, last = n + 1, raw
				end
			end
			return n, last
		end
		local function world(options)
			return L.world(L.alone(options), { trackers = true }, function(W)
				W.ns.TrackerSlots = nil
				W.addLine({ name = "General" })
				W.addSpell(905, { name = "Lightning Shield", icon = 136051, base = 0 })
				W.slots[3] = { kind = "spell", id = 905, texture = 3, usable = true, count = 0 }
				W.env.C_Texture = { GetAtlasInfo = function(name) if name == "UI-HUD-ActionBar-Proc-Loop-Flipbook" then return { width = 150, height = 150 } end end }
			end)
		end
		local W = world()
		local b = L.button(W, 1, 3)
		check("ownlook: the proc handler is given to OwnPaint", type(W.S.proc) == "function")
		W.S.proc(b, true)
		W.advance(0.3)
		W.advance(0)
		local n, frame = glowFrames(W, b)
		check("ownlook: Game glow draws the game's flipbook on a frame of the add-on, next to the button", n == 1 and frame ~= nil and frame.onUpdate ~= nil, n)
		check("ownlook: the frame hangs from the bar, not from the button", frame ~= nil and W.rawOf[frame.parent] == W.rawOf[W.env.FlatUIBar1])
		W.S.proc(b, false)
		W.advance(0)
		check("ownlook: and stops when the glow ends", frame ~= nil and frame.onUpdate == nil)
		-- Both sources on one button.
		local entry = { id = "ol0002", name = "Lightning Shield proc", lights = { 905 } }
		W.S.proc(b, true)
		W.advance(0.1)
		W.advance(0)
		W.ns.ProcGlowStart(entry)
		W.advance(0.1)
		W.advance(0)
		local count = glowFrames(W, b)
		check("ownlook: the tracker glow and the proc row share one glow frame on a button", count == 1 and frame.onUpdate ~= nil, count)
		W.ns.ProcGlowStop(entry)
		W.advance(0.1)
		W.advance(0)
		check("ownlook: the glow stays while the proc row still wants it", frame.onUpdate ~= nil)
		W.S.proc(b, false)
		W.advance(0.1)
		W.advance(0)
		check("ownlook: and goes when both are done", frame.onUpdate == nil)
		check("ownlook: no violation from any of it", L.quiet(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
		-- Border.
		local B = world({ ["actionbars.proc"] = "border", ["actionbars.procColour"] = "ff00ff00" })
		local bb = L.button(B, 1, 3)
		B.S.proc(bb, true)
		B.advance(0.1)
		B.advance(0)
		local look = B.look(bb.icon)
		check("ownlook: Coloured border marks the outline of the button", look ~= nil and near(look.g, 1) and near(look.r, 0) and near(look.thick, 2), look and (look.r .. "," .. look.g .. "," .. tostring(look.thick)))
		check("ownlook: and draws no flipbook", (glowFrames(B, bb)) == 0)
		B.S.proc(bb, false)
		B.advance(0.1)
		B.advance(0)
		look = B.look(bb.icon)
		check("ownlook: and takes the border away", look ~= nil and not near(look.g, 1))
		local N = world({ ["actionbars.proc"] = "off" })
		local nb = L.button(N, 1, 3)
		N.S.proc(nb, true)
		N.advance(0.1)
		N.advance(0)
		check("ownlook: None draws nothing", (glowFrames(N, nb)) == 0 and not (N.look(nb.icon) and near(N.look(nb.icon).thick, 2)))
		-- The state of OwnPaint is read when no call came.
		local R = world()
		local rb = L.button(R, 1, 3)
		R.S.states[rb] = { proc = true }
		R.ns.ButtonEffectsChanged()
		R.advance(0.3)
		R.advance(0)
		check("ownlook: a proc already up when the button is first looked at is drawn", (glowFrames(R, rb)) == 1)
	end

	-- Marks on an own button.
	do
		local W = L.world(nil)
		local b = L.button(W, 2, 4)
		check("ownlook: a mark on an own button draws on its outline", W.ns.SetButtonMark(b, "missing", 0.851, 0.251, 0.251) == true and near(W.look(b.icon).r, 0.851))
		W.ns.SetButtonMark(b, "missing", nil)
		check("ownlook: and goes with the mark", not near(W.look(b.icon).r, 0.851))
	end

	-- A button built after login (a reload in a fight): remembered and styled when the fight ends.
	do
		local W = newWorld({ own = true })
		local S = L.state()
		W.S = S
		L.stubs(W, S)
		W.login()
		W.flush()
		local frame = W.env.CreateFrame("Frame", "FlatUIBar1", W.env.UIParent, "SecureHandlerStateTemplate")
		local button = W.env.CreateFrame("CheckButton", "FlatUIBar1Button1", frame, "ActionButtonTemplate, SecureActionButtonTemplate")
		button:SetSize(36, 36)
		button:SetPoint("LEFT", frame, "LEFT", 0, 0)
		S.list[1], S.at[button] = button, { 1, 1 }
		check("ownlook: a button built after login is not listed before its turn", not L.listed(W, button))
		W.fire("PLAYER_REGEN_ENABLED")
		W.advance(0)
		W.flush()
		check("ownlook: it is remembered and styled when the fight ends", L.listed(W, button) and W.look(button.icon) ~= nil and W.ns.ActionButtonGroup(button) == "main")
	end

	-- The taint scan.
	do
		local W = L.world(nil)
		local b = L.button(W, 1, 5)
		local scan = W.slash("taint")
		check("ownlook: the scan counts Flat UI's buttons and its bars", scan:find("No tainted value found.", 1, true) ~= nil and scan:find("Checked: 120 buttons", 1, true) ~= nil, scan)
		check("ownlook: and the line for the status is empty while all is clean", W.ns.TaintOwnLine() == nil)
		W.markTainted(b, "popup", "SomeAddon")
		scan = W.slash("taint")
		check("ownlook: the scan names a field written on a Flat UI button", scan:find("Tainted: FlatUIBar1Button5.popup by SomeAddon", 1, true) ~= nil, scan)
		check("ownlook: and the status line names the button and the field", W.ns.TaintOwnLine() == "Flat UI's buttons: popup on FlatUIBar1Button5 written outside secure code.", tostring(W.ns.TaintOwnLine()))
		W.clearTaint(b, "popup")
		check("ownlook: and clears when the field is clean again", W.ns.TaintOwnLine() == nil)
		check("ownlook: a button whose click handler is not the template's is named", (function()
			local raw = W.rawOf[L.button(W, 2, 1)]
			local old = raw.scripts.OnClick
			raw.scripts.OnClick = function() end
			local text = W.slash("taint")
			raw.scripts.OnClick = old
			return text:find("Tainted: FlatUIBar2Button1.OnClick by not SecureActionButton_OnClick", 1, true) ~= nil
		end)())
		check("ownlook: the scan raised nothing", L.quiet(W))
	end
end
-- >>> ownlook (end)
-- >>> ownset (begin)
-- Settings, status lines and text of Flat UI's own action buttons (ownset:).
do
	local V = { lines = { buttons = "Action buttons: Flat UI's, 96 on 8 bars.", waiting = "Action buttons: Flat UI's buttons are built when combat ends.",
		page = "Main bar page: 7, the game's 7.", keys = "Key presses: through the game's buttons.", flyoutkeys = "Keys on flyout slots: sent to Flat UI's buttons, 2 keys.",
		parked = "Game bars 1 to 8: hidden.", leave = "Vehicle leave button: shown without the main bar.",
		taint = "Flat UI's buttons: popup on FlatUIBar1Button5 written outside secure code.",
		totem = "Totem and extra action buttons are the game's. A click on them can still be refused." },
		ids = { "buttons", "waiting", "page", "keys", "flyoutkeys", "parked", "leave", "taint", "totem" },
		reload = "Flat UI: Action buttons applies after /reload." }
	local function slurp(name)
		local handle = io.open(ADDON_DIR .. "/../" .. name, "rb")
		local text = handle and handle:read("*a") or ""
		if handle then
			handle:close()
		end
		return text
	end
	local function said(world)
		local n = 0
		for _, line in ipairs(world.out) do
			if line == V.reload then
				n = n + 1
			end
		end
		return n
	end
	local W = newWorld({ ownDefault = true })
	local page, step
	for _, each in ipairs(W.ns.PAGES) do
		if each.key == "actionbars" then
			page = each
		end
	end
	for _, each in ipairs(W.ns.SETUP_STEPS) do
		if each.id == "ab-bars" then
			step = each
		end
	end
	local rows, first, firstSection, enabledAt, ownAt, sectionOf = {}, nil, nil, nil, nil, nil
	do
		local last
		for index, item in ipairs(page or {}) do
			if item.section then
				last = item.section
			end
			if item.path then
				rows[item.path] = item
				if first == nil then
					first, firstSection = item, last
				end
				if item.path == "actionbars.enabled" then
					enabledAt = index
				elseif item.path == "actionbars.own" then
					ownAt, sectionOf = index, last
				end
			end
		end
	end
	local own = rows["actionbars.own"]
	check("ownset: Action buttons is a choice of Flat UI's and The game's that starts on Flat UI's", own ~= nil and own.kind == "choice" and own.default == "flat" and own.label == "Action buttons"
		and #own.choices == 2 and own.choices[1][1] == "flat" and own.choices[1][2] == "Flat UI's" and own.choices[2][1] == "game" and own.choices[2][2] == "The game's")
	check("ownset: it is the first row of Action bars, in the section Buttons, above Restyle action bars", first == own and firstSection == "Buttons" and sectionOf == "Buttons"
		and ownAt ~= nil and enabledAt ~= nil and ownAt < enabledAt)
	check("ownset: its tip says where clicks go and that a reload applies it", own ~= nil and own.tip == "Mouse clicks go to Flat UI's buttons, laid out like the game's bars. Applies after a reload.")
	check("ownset: a new profile reads Flat UI's", W.ns.Get("actionbars.own") == "flat")
	local tipsOk = true
	for _, path in ipairs({ "actionbars.frame", "actionbars.caps", "actionbars.dividers" }) do
		tipsOk = tipsOk and rows[path] ~= nil and rows[path].tip == "Applies with the game's buttons."
	end
	check("ownset: Hide bar frame, Hide end caps and Hide dividers say they apply with the game's buttons", tipsOk)
	local effects, hands = {}, nil
	for _, each in ipairs(W.ns.PAGES) do
		for _, item in ipairs(each) do
			if item.path and each.key == "actionbarsEffects" then
				effects[item.path] = item
			elseif item.path == "general.handsOff" then
				hands = item
			end
		end
	end
	local effectsOk = true
	for _, path in ipairs({ "actionbars.assist", "actionbars.castAnim", "actionbars.interruptAnim" }) do
		effectsOk = effectsOk and effects[path] ~= nil and effects[path].tip == "Shows on the game's buttons only."
	end
	check("ownset: Rotation helper highlight, Cast fill animation and Interrupt flash say they show on the game's buttons only", effectsOk)
	check("ownset: Leave the game's action bars alone names the bars it covers and leaves bars 1 to 8 to Action buttons", hands ~= nil
		and hands.tip == "Flat UI does not move, group or fade the game's micro menu, bag bar, stance and pet bars, or the game's experience bar while Experience bar is The game's, and the game's Options page has one button that opens Flat UI. Applies after a reload.")
	local firstRow = step and step.rows[1]
	check("ownset: the Action buttons step of setup starts with the new row as a main choice with its sentence", firstRow ~= nil and firstRow[1] == "actionbars.own" and firstRow[2] == "c" and firstRow[3] == "behaviour"
		and firstRow[4] == "Mouse clicks go to Flat UI's buttons. Keys go through the game's buttons.")
	local handsRow
	for _, row in ipairs(step and step.rows or {}) do
		if row[1] == "general.handsOff" then
			handsRow = row
		end
	end
	check("ownset: the step's sentence for Leave the game's action bars alone leaves out bars 1 to 8", handsRow ~= nil and handsRow[4] == "Flat UI does not move, group or fade the game's stance and pet bars, or the game's experience bar while Experience bar is The game's.")
	local owners = 0
	for _, each in ipairs(W.ns.SETUP_STEPS) do
		for _, row in ipairs(each.rows) do
			if row[1] == "actionbars.own" then
				owners = owners + 1
			end
		end
	end
	check("ownset: the new row is in exactly one step", owners == 1)

	-- The reload line.
	do
		local R = newWorld({ ownDefault = true })
		R.login()
		R.ns.Set("actionbars.own", "game")
		check("ownset: choosing The game's says once in chat that a reload applies it", said(R) == 1 and R.ns.Get("actionbars.own") == "game")
		R.ns.Set("actionbars.own", "game")
		check("ownset: and does not say it again for the same choice", said(R) == 1)
		R.ns.Set("actionbars.own", "flat")
		check("ownset: going back to Flat UI's says it too", said(R) == 2)
	end

	-- The status lines.
	do
		local S = newWorld({ ownDefault = true })
		local asked = {}
		S.ns.OwnStatus = function(id) asked[#asked + 1] = id return V.lines[id] end
		local text = S.status()
		local order, last = true, 0
		for _, id in ipairs(V.ids) do
			local at = text:find(V.lines[id], 1, true)
			order = order and at ~= nil and at > last
			last = at or last
		end
		check("ownset: /flatui status has each of the nine lines of Flat UI's buttons, in the order of the design", order, text)
		local seen = {}
		for _, id in ipairs(asked) do
			seen[id] = (seen[id] or 0) + 1
		end
		local once = true
		for _, id in ipairs(V.ids) do
			once = once and seen[id] == 1
		end
		check("ownset: each line is asked for once, by its id", once and #asked == 9)
		local longest, bad = 0, nil
		for _, id in ipairs(V.ids) do
			local line = V.lines[id]
			longest = math.max(longest, #line)
			if line:find("\226\128\148", 1, true) or line:find("\226\128\147", 1, true) or line:find("[Tt]he system") or line:find("which means") then
				bad = line
			end
		end
		check("ownset: every line fits 255 characters and has no banned wording", longest <= 255 and bad == nil, tostring(bad))
		local G = newWorld({ ownDefault = true })
		G.login()
		G.ns.OwnStatus = function() return nil end
		G.ns.Set("actionbars.own", "game")
		local gtext = G.status()
		check("ownset: with the game's buttons chosen, one line says so", gtext:find("Action buttons: the game's.", 1, true) ~= nil and not gtext:find("96 on 8 bars", 1, true))
		local N = newWorld({ ownDefault = true })
		N.ns.OwnStatus = function() return nil end
		check("ownset: with Flat UI's buttons chosen and no line to give there is none", not N.status():find("Action buttons:", 1, true))
		local F = newWorld({ ownDefault = true })
		F.ns.OwnStatus = function(id) if id == "page" then return V.lines.page end end
		local ftext = F.status()
		check("ownset: a state that gives one line shows only that line", ftext:find(V.lines.page, 1, true) ~= nil and not ftext:find("Keys on flyout slots", 1, true) and not ftext:find("Game bars 1 to 8", 1, true))
		local E = newWorld({ ownDefault = true })
		E.ns.OwnStatus = function() error("no", 0) end
		check("ownset: a line that raises is left out and the status still shows", pcall(E.status) and #E.errors == 0)
	end

	-- The files.
	do
		local at = {}
		for index, file in ipairs(FILES) do
			at[file] = index
		end
		check("ownset: the TOC loads OwnBars.lua then OwnPaint.lua right after ActionBars.lua", at["ActionBars.lua"] ~= nil and at["OwnBars.lua"] == at["ActionBars.lua"] + 1 and at["OwnPaint.lua"] == at["OwnBars.lua"] + 1)
		local changelog, description = slurp("FlatUI_release/changelog.md"), slurp("FlatUI_release/description.md")
		local top = changelog:match("\n## 0%.4%.58\n(.-)\n## ") or changelog
		check("ownset: the changelog entry of the build that added Action buttons says what Action buttons does and what it does not yet do",
			top:find("**Action buttons**", 1, true) ~= nil and top:find("Key presses still go through the game's buttons", 1, true) ~= nil
			and top:find("Edit Mode still places bars 1 to 8", 1, true) ~= nil and top:find("totem and extra action buttons are still the game's", 1, true) ~= nil
			and top:find("**Cast fill animation**", 1, true) ~= nil and top:find("game's buttons only", 1, true) ~= nil)
		check("ownset: the description has the row, the art rows and the glow rows with the same limits", description:find("**Action buttons:**", 1, true) ~= nil
			and description:find("They apply with **The game's** buttons.", 1, true) ~= nil and description:find("show on the game's buttons only", 1, true) ~= nil
			and description:find("Action bars 1 to 8 follow **Action buttons**", 1, true) ~= nil)
		check("ownset: the release text has no em dash", not top:find("\226\128\148", 1, true) and not description:find("\226\128\148", 1, true))
		local json = slurp("FlatUI_release/settings.json")
		check("ownset: the settings dump has the new row and its choices", json:find("Action buttons", 1, true) ~= nil and json:find("Flat UI's", 1, true) ~= nil and json:find("The game's", 1, true) ~= nil)
	end
	check("ownset: nothing here broke the world", #W.errors == 0)
end
-- >>> ownset (end)
-- >>> ownflow (begin)
-- Flat UI's own action buttons with the real pieces together (ownflow:): OwnBars.lua, OwnPaint.lua and the look modules in one world, no stubs of the contract.
do
	local F = {}
	function F.world(mode)
		local o = { own = true, handsOff = true }
		if mode == "game" then
			o.saved = { options = { ["actionbars.own"] = "game" } }
		end
		local W = newWorld(o)
		W.login()
		W.frame(3)
		return W
	end
	function F.clean(W) return #W.errors == 0 and #W.violations == 0 and #W.refused == 0 and #W.snippetErrors == 0 end
	function F.raw(W, x) return W.rawOf[x] or x end

	-- 1. A click on each of the 96 buttons ends in UseAction, out of combat and in combat.
	do
		local W = F.world()
		local clicked, refused = 0, 0
		for n = 1, 8 do
			for i = 1, 12 do
				local ok = W.click("FlatUIBar" .. n .. "Button" .. i)
				clicked, refused = clicked + (ok and 1 or 0), refused + (ok and 0 or 1)
			end
		end
		check("ownflow: a click on each of the 96 buttons ends in UseAction", clicked == 96 and refused == 0 and #W.used == 96 and F.clean(W), clicked .. "/" .. refused .. "/" .. #W.used .. "/" .. #W.refused)
		check("ownflow: and the button's slot is the one used", W.used[1].slot == 1 and W.used[13].slot == 61 and W.used[96].slot == 180)
		W.setCombat(true)
		W.frame(2)
		local before = #W.used
		local ok = W.click("FlatUIBar1Button5") and W.click("FlatUIBar3Button2")
		check("ownflow: and in combat", ok and #W.used == before + 2 and F.clean(W))
		check("ownflow: no field is written on a button by Flat UI", (function()
			for _, w in ipairs(W.fieldWrites) do
				if w.by == "addon" then return false end
			end
			return true
		end)())
	end

	-- 2. The look: icon, hotkey and styling on the real buttons.
	do
		local W = F.world()
		local b3 = W.env.FlatUIBar1Button3
		check("ownflow: the icon shows the slot's texture", F.raw(W, b3.icon).file == 100003 and F.raw(W, W.env.FlatUIBar2Button1.icon).file == 100061)
		check("ownflow: the hotkey is the key of the twin's command", F.raw(W, b3.HotKey).text == "3" and F.raw(W, W.env.FlatUIBar2Button2.HotKey).text == "SHIFT-2", tostring(F.raw(W, b3.HotKey).text) .. "/" .. tostring(F.raw(W, W.env.FlatUIBar2Button2.HotKey).text))
		local listed, twin = 0, false
		for _, button in ipairs(W.ns.ActionButtons()) do
			if W.ns.OwnBar(button) then listed = listed + 1 end
			twin = twin or button == W.env.ActionButton3
		end
		check("ownflow: the look modules list and style the 96 buttons and not the game's twins", listed == 96 and not twin and W.look(b3.icon) ~= nil, listed)
		check("ownflow: after a login with Flat UI's buttons no twin is remembered, on or styled", (function()
			for n = 1, 8 do
				local name = ({ "ActionButton", "MultiBarBottomLeftButton", "MultiBarBottomRightButton", "MultiBarRightButton", "MultiBarLeftButton", "MultiBar5Button", "MultiBar6Button", "MultiBar7Button" })[n]
				for i = 1, 12 do
					local twin = W.env[name .. i]
					if W.ns.ActionButtonGroup(twin) ~= nil or W.ns.ButtonIsOn(twin) or W.look(twin.icon) ~= nil then
						return false, name .. i
					end
				end
			end
			return true
		end)())
		check("ownflow: the status lines say the buttons are Flat UI's", W.ns.OwnStatus("buttons") == "Action buttons: Flat UI's, 96 on 8 bars.")
		check("ownflow: the scan names nothing", W.ns.TaintOwnLine() == nil, tostring(W.ns.TaintOwnLine()))
	end

	-- 3. Paging: the real buttons follow the bonus bar, and so do the paint and the keys.
	do
		local W = F.world()
		W.setBarState({ bonus = 1 })
		W.frame(8)
		local b3 = W.env.FlatUIBar1Button3
		check("ownflow: bar 1 shows slots 73 to 84 on a bonus bar", b3:GetAttribute("action") == 75 and F.raw(W, b3.icon).file == 100075, tostring(b3:GetAttribute("action")) .. "/" .. tostring(F.raw(W, b3.icon).file))
		local before = #W.used
		W.click("FlatUIBar1Button3")
		W.press("ACTIONBUTTON", 3)
		check("ownflow: a click and a key use slot 75", #W.used >= before + 2 and W.used[before + 1].slot == 75 and W.used[#W.used].slot == 75 and F.clean(W))
		W.setBarState({ bonus = 0 })
		W.frame(8)
		check("ownflow: and back on page 1", b3:GetAttribute("action") == 3 and F.raw(W, b3.icon).file == 100003)
	end

	-- 4. With the game's buttons nothing of Flat UI's is made and the game's buttons are styled as before.
	do
		local W = F.world("game")
		check("ownflow: the game's buttons set builds none and paints none", #W.own == 0 and not W.ns.OwnOn() and #W.ns.OwnButtons() == 0 and W.env.FlatUIBar1 == nil and F.clean(W))
		check("ownflow: and the look modules list the game's buttons", #W.ns.ActionButtons() > 0 and W.ns.ActionButtons()[1] == W.env.ActionButton1 and W.ns.OwnStatus("buttons") == "Action buttons: the game's.")
		check("ownflow: and its twins are remembered and styled as before", W.ns.ActionButtonGroup(W.env.ActionButton3) == "main" and W.ns.ActionButtonGroup(W.env.MultiBarLeftButton5) == "extra"
			and W.look(W.env.ActionButton3.icon) ~= nil)
	end

	-- 5. The status lines of the real file answer the ids of Core: one line each, and one that the build failed.
	do
		local W = F.world()
		local text = W.status()
		check("ownflow: /flatui status shows the buttons, key, parked lines of the real file", text:find("Action buttons: Flat UI's, 96 on 8 bars.", 1, true) ~= nil
			and text:find("Key presses: through the game's buttons.", 1, true) ~= nil and text:find("Game bars 1 to 8: hidden.", 1, true) ~= nil, text)
		check("ownflow: no line for waiting or flyout keys while none applies, and the vehicle line follows the alpha rule", W.ns.OwnStatus("waiting") == nil and W.ns.OwnStatus("flyoutkeys") == nil
			and W.ns.OwnStatus("error") == nil and W.ns.OwnStatus("leave") == "Vehicle leave button: shown without the main bar.")
	end
end
-- >>> ownflow (end)
-- >>> xpown (begin)
-- Flat UI's own experience and reputation bar (FlatUI/XpBar.lua, research/xp-bar/design.md). Every label starts "xpown:". The game's status bars are parked by
-- the alpha of their manager and the mouse of their bars, and nothing else of the game's is written. The stand-ins are the frames the XML makes
-- (StatusTrackingBar.xml:35-57) and the calls the game's bar reads (ExpBar.lua, ReputationBar.lua).
do
	local K = suiteKit
	local T = { calls = { "SetSize", "SetScale", "SetPoint", "ClearAllPoints", "SetParent", "Hide", "Show", "UnregisterEvent", "UnregisterAllEvents", "HookScript",
		"SetWidth", "SetHeight", "SetShown" } }
	local C = { GREEN = { 0, 0.6, 0.1 }, ORANGE = { 0.75, 0.27, 0 }, RED = { 0.8, 0.3, 0.22 }, YELLOW = { 0.9, 0.7, 0 }, BLUE = { 0, 0.39, 0.88 } }

	-- The calls the game's bar reads, from the values in X. rep is the table C_Reputation.GetWatchedFactionData answers.
	local function stubs(env, X)
		env.UnitXP = function() return X.secret and SECRET or X.xp end
		env.UnitXPMax = function() return X.max end
		env.GetXPExhaustion = function() return X.exh end
		env.GetRestState = function() return X.rest, "Rested", 2 end
		env.IsResting = function() return false end
		env.IsXPUserDisabled = function() return X.off end
		env.GameRulesUtil = { CanShowExperienceBar = function() return not X.atMax and not X.off end }
		env.C_Reputation = { GetWatchedFactionData = function() return X.faction end }
		if X.calls then
			env.C_Reputation.IsFactionParagonForCurrentPlayer = function() return X.paragon == true end
			env.C_Reputation.GetFactionParagonInfo = function() return X.paragonValue or 0, X.paragonThreshold or 1, 0, false end
			env.C_Reputation.IsMajorFaction = function() return X.major == true end
			env.C_MajorFactions = { GetMajorFactionData = function() return { renownLevelThreshold = 2500, renownReputationEarned = 500, renownLevel = 3 } end,
				GetRenownLevels = function() return { { level = 1 }, { level = 20 } } end }
			env.C_GossipInfo = { GetFriendshipReputation = function() return X.friend or { friendshipFactionID = 0 } end,
				GetFriendshipReputationRanks = function() return { currentLevel = X.friendLevel or 1, maxLevel = X.friendMax or 8 } end }
		end
		env.XP_STATUS_BAR_TEXT = "XP: %s/%s"
		env.XP_TEXT = "Experience: %s/%s (%s%%)"
		env.EXHAUST_TOOLTIP1 = "You are %s. (%d%% of normal experience)"
		X.tip = { lines = {} }
		if X.noTip then
			return
		end
		env.GameTooltip = { SetOwner = function(_, owner) X.tip.owner, X.tip.lines = owner, {} end, GetOwner = function() return X.tip.owner end,
			SetText = function(_, text) X.tip.lines[#X.tip.lines + 1] = text end, AddLine = function(_, text) X.tip.lines[#X.tip.lines + 1] = text end,
			Show = function() X.tip.shown = true end, Hide = function() X.tip.shown, X.tip.owner = false, nil end }
	end

	-- A hud world with the game's two status containers, the experience bar's pip, a mouse that is on, and each call of the addon's own that sets a size, a
	-- place, a scale, a parent, a shown state or a hook on the manager, the containers, the bars or the frame picture counted in X.n.
	local function world(o)
		o = o or {}
		local X = { xp = 300, max = 1000, rest = 2, calls = o.calls ~= false, n = 0, log = {} }
		for key, value in pairs(o.X or {}) do
			X[key] = value
		end
		local H = FH.hudLogin({ xpown = true, handsOff = o.handsOff ~= false, combat = o.combat, saved = o.options and { options = o.options } or nil,
			extra = function(H, set, W)
				stubs(W.env, X)
				local second = W.B(nil, { bars = {} })
				set("SecondaryStatusTrackingBarContainer", second)
				H.second = second
				local tick = W.B(nil, {})
				W.rawOf[H.exp.frame].ExhaustionTick = tick
				local function count(frame, label)
					local raw = W.rawOf[frame] or frame
					for _, call in ipairs(T.calls) do
						local base = raw[call]
						if type(base) == "function" then
							raw[call] = function(...)
								if W.inBlizzard == 0 then
									X.n = X.n + 1
									X.log[#X.log + 1] = label .. "." .. call
								end
								return base(...)
							end
						end
					end
				end
				local function mouse(frame)
					local raw = W.rawOf[frame]
					raw.mouse = true
					raw.mouseWrites = 0
					raw.EnableMouse = function(_, value)
						raw.mouse = value
						raw.mouseWrites = raw.mouseWrites + 1
					end
					raw.IsMouseEnabled = function() return raw.mouse end
				end
				count(H.manager, "manager")
				count(H.xp, "container")
				count(second, "second")
				count(H.exp.frame, "bar")
				count(H.rep.frame, "bar")
				count(tick, "tick")
				count(W.rawOf[H.xp].BarFrameTexture, "frame")
				for _, frame in ipairs({ H.exp.frame, H.rep.frame, tick }) do
					mouse(frame)
				end
				H.tick = tick
				W.rawOf[H.manager].IsTextLocked = function() return X.locked == true end
				W.rawOf[H.manager].GetAlpha = function() return W.rawOf[H.manager].alpha end
				if o.protect then
					W.rawOf[H.manager].protected = true
				end
				if o.extra then
					o.extra(H, set, W, X)
				end
			end })
		H.X = X
		H.W.flush()
		return H
	end
	local function bars(H)
		local raw = H.W.rawOf[H.W.env.FlatUIXpBar]
		return raw, raw and raw.children[1], raw and raw.children[2]
	end
	local function rawOf(H, frame)
		return H.W.rawOf[frame]
	end
	local function fill(H, which)
		local _, xp, rep = bars(H)
		local frame = which == "rep" and rep or xp
		return frame and rawOf(H, frame).bar
	end
	local function stretch(H)
		local _, xp = bars(H)
		for _, region in ipairs(rawOf(H, xp).regions) do
			if region.layer == "BACKGROUND" and region.sublevel == 1 then
				return region
			end
		end
	end
	-- The child of a bar that holds its text and dividers.
	local function overOf(H, frame)
		for _, child in ipairs(rawOf(H, frame).children) do
			for _, region in ipairs(rawOf(H, child).regions) do
				if region.kind == "FontString" then
					return child
				end
			end
		end
	end
	local function words(H, which)
		local _, xp, rep = bars(H)
		local over = overOf(H, which == "rep" and rep or xp)
		for _, region in ipairs(rawOf(H, over).regions) do
			if region.kind == "FontString" then
				return region
			end
		end
	end
	local function colourIs(tint, rgb)
		return tint ~= nil and math.abs(tint[1] - rgb[1]) < 1e-6 and math.abs(tint[2] - rgb[2]) < 1e-6 and math.abs(tint[3] - rgb[3]) < 1e-6
	end
	local function alpha(H, name) return H.W.rawOf[H.W.env[name]].alpha end
	local function event(H, name, ...)
		H.W.fire(name, ...)
		H.W.flush()
	end
	local function setOpt(H, path, value)
		H.W.ns.Set(path, value)
		H.W.flush()
	end
	local function clean(H) return #H.W.violations == 0 and #H.W.errors == 0 end
	local FACTION = { name = "Honor Hold", factionID = 946, reaction = 5, currentReactionThreshold = 3000, nextReactionThreshold = 9000, currentStanding = 4500 }

	-- 1. Defaults and 2. parking.
	do
		local H = world()
		local W = H.W
		local root, xp = bars(H)
		check("xpown: defaults: the frame FlatUIXpBar is on UIParent in the strata LOW, 417.2 by 8 with one bar, not protected and anchored to UIParent alone",
			root ~= nil and root.parent == W.env.UIParent and root.strata == "LOW" and math.abs(root.width - 417.2) < 1e-6 and root.height == 8 and not root.protected and #root.points == 1
			and root.points[1][2] == W.env.UIParent, root and (tostring(root.width) .. "x" .. tostring(root.height)))
		check("xpown: parking: the manager has alpha 0 after the login and the containers keep theirs", alpha(H, "StatusTrackingBarManager") == 0 and rawOf(H, H.xp).alpha == 1
			and rawOf(H, H.second).alpha == 1)
		check("xpown: parking: the mouse is off on both bars and on the pip", rawOf(H, H.exp.frame).mouse == false and rawOf(H, H.rep.frame).mouse == false and rawOf(H, H.tick).mouse == false)
		check("xpown: parking: no size, scale, place, parent, shown state, hook or unregistering of the addon's own on the manager, the containers, the bars, the pip or the frame picture",
			H.X.n == 0 and clean(H), H.X.n .. " " .. table.concat(H.X.log, ","):sub(1, 200))
		local text = ""
		local handle = io.open(ADDON_DIR .. "/XpBar.lua", "rb")
		if handle then
			text = handle:read("*a")
			handle:close()
		end
		local found = {}
		for _, word in ipairs({ "hooksecurefunc", "HookScript", "UnregisterEvent", "UnregisterAllEvents", "SetParent" }) do
			if text:find(word, 1, true) then
				found[#found + 1] = word
			end
		end
		check("xpown: parking: XpBar.lua never names a hook, an unregistering or a new parent", #found == 0 and text ~= "", table.concat(found, ","))
		check("xpown: status: the status line says the bar is Flat UI's and the game's is not drawn", W.status():find("Experience bar: Flat UI's. The game's bar is not drawn.", 1, true) ~= nil,
			W.status():sub(-200))
		-- 20. A session that starts on the game's bar writes nothing, and a session on Flat UI's with the bars not left alone hooks neither the manager nor the containers.
		local G = world({ options = { ["hud.xpOwn"] = "game" }, handsOff = false })
		local hooks = 0
		for _, frame in ipairs({ G.manager, G.xp }) do
			for _, list in pairs(rawOf(G, frame).scriptHooks or {}) do
				hooks = hooks + #list
			end
		end
		check("xpown: session: a session that starts on the game's bar writes no alpha and no mouse on its frames and has no frame of its own", alpha(G, "StatusTrackingBarManager") == 1
			and rawOf(G, G.exp.frame).mouseWrites == 0 and rawOf(G, G.tick).mouseWrites == 0 and G.W.env.FlatUIXpBar == nil and rawOf(G, G.manager).calls.SetAlpha == nil)
		check("xpown: session: with the game's bar the manager and the container are hooked as before", hooks > 0, hooks)
		local F = world({ handsOff = false })
		local before = 0
		for _, frame in ipairs({ F.manager, F.xp }) do
			for _, list in pairs(rawOf(F, frame).scriptHooks or {}) do
				before = before + #list
			end
		end
		setOpt(F, "hud.xpOwn", "game")
		local after = 0
		for _, frame in ipairs({ F.manager, F.xp }) do
			for _, list in pairs(rawOf(F, frame).scriptHooks or {}) do
				after = after + #list
			end
		end
		setOpt(F, "hud.xpOwn", "flat")
		setOpt(F, "hud.xpOwn", "game")
		local again = 0
		for _, frame in ipairs({ F.manager, F.xp }) do
			for _, list in pairs(rawOf(F, frame).scriptHooks or {}) do
				again = again + #list
			end
		end
		check("xpown: session: a session on Flat UI's bar with the bars not left alone hooks nothing, and the first switch to the game's bar hooks once", before == 0 and after > 0 and again == after,
			before .. " " .. after .. " " .. again)
	end

	-- 3. Login in combat, 4. upkeep, 21. an alpha that cannot be written in a fight.
	do
		local H = world({ combat = true })
		local W = H.W
		check("xpown: combat: a login in a fight writes the alpha at once and queues the mouse", alpha(H, "StatusTrackingBarManager") == 0 and rawOf(H, H.exp.frame).mouse == true
			and rawOf(H, H.exp.frame).mouseWrites == 0 and W.env.FlatUIXpBar ~= nil)
		W.combat = false
		event(H, "PLAYER_REGEN_ENABLED")
		check("xpown: combat: at the end of the fight the mouse is turned off", rawOf(H, H.exp.frame).mouse == false and rawOf(H, H.rep.frame).mouse == false and rawOf(H, H.tick).mouse == false)
		local U = world()
		U.W.blizzard(function() U.manager:SetAlpha(1) end)
		event(U, "PLAYER_XP_UPDATE", "player")
		check("xpown: upkeep: the game putting the alpha back is undone at the next event and counted", alpha(U, "StatusTrackingBarManager") == 0 and U.W.status():find("made its bars visible or clickable again 1 time.", 1, true) ~= nil,
			alpha(U, "StatusTrackingBarManager") .. " calls " .. tostring(U.W.rawOf[U.manager].calls.SetAlpha) .. " put " .. tostring(U.W.status():find("put its", 1, true)) .. " " .. tostring(U.W.status():find("Flat UI's. The game", 1, true)))
		rawOf(U, U.exp.frame).mouse = true
		event(U, "PLAYER_REGEN_ENABLED")
		check("xpown: upkeep: a bar the game gave the mouse again has it taken off at the end of the fight and counted", rawOf(U, U.exp.frame).mouse == false
			and U.W.status():find("made its bars visible or clickable again 2 times", 1, true) ~= nil, U.W.status():sub(-200))
		local P = world({ protect = true, combat = true })
		check("xpown: combat: a protected manager in a fight gets no alpha write, the write waits and the status says so", alpha(P, "StatusTrackingBarManager") == 1
			and P.W.status():find("is hidden after the fight", 1, true) ~= nil, P.W.status():sub(-200))
		P.W.combat = false
		event(P, "PLAYER_REGEN_ENABLED")
		check("xpown: combat: and it is written at the end of the fight", alpha(P, "StatusTrackingBarManager") == 0)
	end

	-- 5. Switching to the game's bar and back.
	do
		local H = world({ handsOff = false })
		local W = H.W
		local function framePicture() return rawOf(H, H.xp).BarFrameTexture.alpha end
		local picture = W.rawOf[H.xp].BarFrameTexture
		local own = W.rawOf[picture] or picture
		check("xpown: switch: with Flat UI's bar and the bars not left alone the game's frame picture is not restyled", (own.alpha or 1) == 1)
		setOpt(H, "hud.xpOwn", "game")
		check("xpown: switch: to the game's bar out of combat gives alpha 1 and the mouse back, hides the own frame and restyles the game's bar", alpha(H, "StatusTrackingBarManager") == 1
			and rawOf(H, H.exp.frame).mouse == true and rawOf(H, H.tick).mouse == true and rawOf(H, W.env.FlatUIXpBar).shown == false and own.alpha == 0, tostring(own.alpha))
		setOpt(H, "hud.xpOwn", "flat")
		check("xpown: switch: and back to Flat UI's parks again and shows the frame", alpha(H, "StatusTrackingBarManager") == 0 and rawOf(H, H.exp.frame).mouse == false
			and rawOf(H, W.env.FlatUIXpBar).shown == true)
		W.combat = true
		setOpt(H, "hud.xpOwn", "game")
		check("xpown: switch: in a fight the switch waits and the status says so", alpha(H, "StatusTrackingBarManager") == 0 and W.status():find("Experience bar: changes after the fight.", 1, true) ~= nil,
			W.status():sub(-200))
		W.combat = false
		event(H, "PLAYER_REGEN_ENABLED")
		check("xpown: switch: and it is made at the end of the fight", alpha(H, "StatusTrackingBarManager") == 1 and rawOf(H, H.exp.frame).mouse == true)
		-- A switch made and taken back in one fight leaves nothing waiting.
		setOpt(H, "hud.xpOwn", "flat")
		W.combat = true
		setOpt(H, "hud.xpOwn", "game")
		setOpt(H, "hud.xpOwn", "flat")
		W.combat = false
		event(H, "PLAYER_REGEN_ENABLED")
		check("xpown: switch: made and taken back in one fight leaves no waiting line", W.status():find("changes after the fight.", 1, true) == nil, W.status():sub(-200))
		-- With the bars left alone nothing of the game's bar is restyled whichever bar is chosen.
		local S = world()
		setOpt(S, "hud.xpOwn", "game")
		check("xpown: switch: with the bars left alone the game's bar is given back and not restyled", alpha(S, "StatusTrackingBarManager") == 1 and S.X.n == 0, S.X.n)
	end

	-- 6. Values, 7. what shows when.
	do
		local H = world()
		local W = H.W
		local f = fill(H, "xp")
		check("xpown: values: 300 of 1000 fills 0.3 in the experience colour", f.value == 0.3 and colourIs(f.tint, { 0.58, 0, 0.55 }) == false and f.tint[1] > 0.57 and f.tint[1] < 0.59 and f.tint[3] > 0.54
			and f.tint[3] < 0.56 and f.tint[2] == 0, tostring(f.value))
		check("xpown: values: no rested experience shows no stretch", stretch(H).shown == false)
		H.X.exh = 200
		event(H, "UPDATE_EXHAUSTION")
		check("xpown: values: 200 rested experience runs the stretch to half of the bar", stretch(H).shown == true and math.abs(stretch(H).width - 208.6) < 1e-6, tostring(stretch(H).width))
		H.X.exh = 900
		event(H, "UPDATE_EXHAUSTION")
		check("xpown: values: 900 is clamped to the end of the bar", stretch(H).shown == true and math.abs(stretch(H).width - 417.2) < 1e-6, tostring(stretch(H).width))
		setOpt(H, "hud.xpRested", false)
		check("xpown: values: Rested experience off hides the stretch", stretch(H).shown == false)
		setOpt(H, "hud.xpRested", true)
		H.X.exh = nil
		event(H, "UPDATE_EXHAUSTION")
		check("xpown: values: no exhaustion hides it again", stretch(H).shown == false)
		H.X.rest = 1
		event(H, "UPDATE_EXHAUSTION")
		check("xpown: values: the rest state 1 gives the fill the rested colour", fill(H, "xp").tint[1] == 0 and math.abs(fill(H, "xp").tint[3] - 224 / 255) < 1e-6, tostring(fill(H, "xp").tint[3]))
		H.X.rest = 2
		H.X.xp = 750
		event(H, "PLAYER_XP_UPDATE", "player")
		check("xpown: values: new experience moves the fill", fill(H, "xp").value == 0.75)
		local root = bars(H)
		H.X.atMax = true
		event(H, "PLAYER_LEVEL_UP")
		check("xpown: visibility: at the effective maximum level the experience bar is hidden and the frame with it", root.shown == false and rawOf(H, select(2, bars(H))).shown == false)
		H.X.atMax = false
		H.X.off = true
		event(H, "DISABLE_XP_GAIN")
		check("xpown: visibility: experience turned off hides it", root.shown == false)
		H.X.off = false
		event(H, "ENABLE_XP_GAIN")
		check("xpown: visibility: and on again shows it", root.shown == true)
		H.X.atMax = true
		event(H, "UPDATE_EXPANSION_LEVEL")
		check("xpown: visibility: a new maximum level from the expansion is read again", root.shown == false)
		H.X.atMax = false
		event(H, "PLAYER_MAX_LEVEL_UPDATE")
		H.X.faction = FACTION
		event(H, "UPDATE_FACTION")
		check("xpown: visibility: a watched faction shows the reputation bar", rawOf(H, select(3, bars(H))).shown == true and root.height == 18, tostring(root.height))
		for _, bad in ipairs({ { name = "", factionID = 946 }, { name = "Honor Hold", factionID = 0 } }) do
			H.X.faction = bad
			event(H, "UPDATE_FACTION")
			check("xpown: visibility: a watched faction with " .. (bad.name == "" and "no name" or "faction 0") .. " shows no reputation bar", rawOf(H, select(3, bars(H))).shown == false and root.height == 8)
		end
		H.X.faction = nil
		event(H, "UPDATE_FACTION")
		check("xpown: visibility: no watched faction shows no reputation bar", rawOf(H, select(3, bars(H))).shown == false)
		H.X.atMax = true
		event(H, "PLAYER_LEVEL_UP")
		check("xpown: visibility: with no bar to show the frame is hidden", root.shown == false and clean(H))
	end

	-- 8. Reputation.
	do
		local H = world()
		local function standing(reaction)
			local data = {}
			for key, value in pairs(FACTION) do
				data[key] = value
			end
			data.reaction = reaction
			H.X.faction = data
			event(H, "UPDATE_FACTION")
			return fill(H, "rep")
		end
		local want = { C.RED, C.RED, C.ORANGE, C.YELLOW, C.GREEN, C.GREEN, C.GREEN, C.GREEN }
		local bad = {}
		for reaction = 1, 8 do
			if not colourIs(standing(reaction).tint, want[reaction]) then
				bad[#bad + 1] = reaction
			end
		end
		check("xpown: reputation: reaction 1 to 8 give red, red, orange, yellow and four greens", #bad == 0, table.concat(bad, ","))
		check("xpown: reputation: 4500 between 3000 and 9000 fills 0.25", math.abs(standing(5).value - 0.25) < 1e-9, tostring(standing(5).value))
		setOpt(H, "hud.xpRepMode", "one")
		setOpt(H, "hud.xpRepColour", "ff3366cc")
		check("xpown: reputation: One colour uses the colour of the row", colourIs(fill(H, "rep").tint, { 0.2, 0.4, 0.8 }), tostring(fill(H, "rep").tint[1]))
		setOpt(H, "hud.xpRepMode", "standing")
		H.X.friend = { friendshipFactionID = 11, reactionThreshold = 0, nextThreshold = 400, standing = 100, reaction = "Buddy" }
		standing(1)
		check("xpown: reputation: a friendship takes its own thresholds and the colour of reaction 5", math.abs(fill(H, "rep").value - 0.25) < 1e-9 and colourIs(fill(H, "rep").tint, C.GREEN), tostring(fill(H, "rep").value))
		H.X.friend = { friendshipFactionID = 11, standing = 900, reaction = "Best friend" }
		H.X.friendLevel, H.X.friendMax = 8, 8
		standing(1)
		check("xpown: reputation: the last friendship rank is a full bar", fill(H, "rep").value == 1, tostring(fill(H, "rep").value))
		H.X.friend = nil
		H.X.major = true
		FACTION.currentStanding = 1500
		standing(5)
		check("xpown: reputation: a renown faction takes the renown thresholds and the blue", colourIs(fill(H, "rep").tint, C.BLUE) and math.abs(fill(H, "rep").value - 1500 / 2500) < 1e-9, tostring(fill(H, "rep").value))
		FACTION.currentStanding = 4500
		H.X.major = false
		H.X.paragon, H.X.paragonValue, H.X.paragonThreshold = true, 15500, 10000
		standing(5)
		check("xpown: reputation: a paragon bar shows the rest of the value over the threshold", math.abs(fill(H, "rep").value - 0.55) < 1e-9, tostring(fill(H, "rep").value))
		H.X.paragon = false
		local N = world({ calls = false })
		N.X.faction = FACTION
		event(N, "UPDATE_FACTION")
		check("xpown: reputation: with the friendship, renown and paragon calls absent the reaction thresholds are used and nothing raises", math.abs(fill(N, "rep").value - 0.25) < 1e-9 and clean(N))
	end

	-- 9. Layout.
	do
		local H = world({ X = { faction = FACTION } })
		local root, xp, rep = bars(H)
		check("xpown: layout: both bars with a gap of 2 make a frame 18 high, experience on top", root.height == 18 and rawOf(H, xp).points[1][5] == 0 and rawOf(H, rep).points[1][5] == -10,
			tostring(root.height) .. " " .. tostring(rawOf(H, xp).points[1][5]) .. " " .. tostring(rawOf(H, rep).points[1][5]))
		setOpt(H, "hud.xpOrder", "rep")
		check("xpown: layout: Top bar Reputation puts it first", rawOf(H, rep).points[1][5] == 0 and rawOf(H, xp).points[1][5] == -10)
		setOpt(H, "hud.xpGap", 4)
		setOpt(H, "hud.xpHeight", 10)
		check("xpown: layout: the gap and the height change the frame at once", root.height == 24 and rawOf(H, xp).height == 10, tostring(root.height))
		setOpt(H, "hud.xpShow", "rep")
		check("xpown: layout: Reputation only shows one bar", root.height == 10 and rawOf(H, xp).shown == false and rawOf(H, rep).shown == true)
		setOpt(H, "hud.xpShow", "xp")
		check("xpown: layout: Experience only shows the other", root.height == 10 and rawOf(H, xp).shown == true and rawOf(H, rep).shown == false)
	end

	-- 10. Text.
	do
		local H = world({ X = { faction = FACTION } })
		local W = H.W
		local function line(which) return words(H, which).text end
		setOpt(H, "hud.xpTextWhen", "always")
		check("xpown: text: As the game has it gives the game's words for each bar", line("xp") == "XP: 300/1000" and line("rep") == "Honor Hold 1500 / 6000", tostring(line("xp")) .. "|" .. tostring(line("rep")))
		setOpt(H, "hud.xpText", "percent")
		check("xpown: text: Percent", line("xp") == "30%" and line("rep") == "Honor Hold 25%", tostring(line("rep")))
		setOpt(H, "hud.xpText", "both")
		check("xpown: text: Value and percent", line("xp") == "300 / 1000 (30%)" and line("rep") == "Honor Hold 1500 / 6000 (25%)", tostring(line("rep")))
		setOpt(H, "hud.xpText", "togo")
		check("xpown: text: Amount to go", line("xp") == "700 to go" and line("rep") == "Honor Hold 4500 to go", tostring(line("rep")))
		setOpt(H, "hud.xpText", "hide")
		check("xpown: text: Hidden shows no text", words(H, "xp").shown == false and words(H, "rep").shown == false)
		setOpt(H, "hud.xpText", "game")
		setOpt(H, "hud.xpTextWhen", "hover")
		local _, xp = bars(H)
		check("xpown: text: on mouse-over the text is hidden until the cursor is over the bar", words(H, "xp").shown == false)
		rawOf(H, xp).scripts.OnEnter(rawOf(H, xp))
		check("xpown: text: the cursor over the bar shows it", words(H, "xp").shown == true and words(H, "rep").shown == false)
		rawOf(H, xp).scripts.OnLeave(rawOf(H, xp))
		check("xpown: text: and off the bar hides it", words(H, "xp").shown == false)
		setOpt(H, "hud.xpTextWhen", "game")
		check("xpown: text: As the game has it hides the text while the xpBarText CVar is off", words(H, "xp").shown == false)
		W.setCVarByPlayer("xpBarText", "1")
		W.flush()
		check("xpown: text: and shows it when the CVar is on", words(H, "xp").shown == true)
		W.setCVarByPlayer("xpBarText", "0")
		W.flush()
		H.X.locked = true
		event(H, "PLAYER_XP_UPDATE", "player")
		check("xpown: text: and while the game locks its text, as it does with the character window open", words(H, "xp").shown == true)
		H.X.locked = false
		event(H, "PLAYER_XP_UPDATE", "player")
		setOpt(H, "hud.xpTextWhen", "always")
		local function place() local p = words(H, "xp").points[1] return p[1] .. ">" .. p[3] end
		check("xpown: text: Bar text place On the bar is the middle of the bar", place() == "CENTER>CENTER", place())
		setOpt(H, "hud.xpTextPlace", "above")
		check("xpown: text: Above the bar hangs the text from the top of the bar", place() == "BOTTOM>TOP", place())
		setOpt(H, "hud.xpTextPlace", "right")
		check("xpown: text: Right of the bar puts it at the right edge", place() == "LEFT>RIGHT", place())
	end

	-- 11. Withheld values, 12. size changes in a fight.
	do
		local H = world()
		local W = H.W
		W.combat = true
		H.X.secret = true
		event(H, "PLAYER_XP_UPDATE", "player")
		check("xpown: withheld: a withheld experience in a fight keeps the last fill and raises nothing", fill(H, "xp").value == 0.3 and clean(H) and not H.W.ns.IsStopped("hud"))
		H.X.secret = false
		H.X.xp = 500
		W.combat = false
		event(H, "PLAYER_REGEN_ENABLED")
		check("xpown: withheld: and it is read again at the end of the fight", fill(H, "xp").value == 0.5)
		W.combat = true
		setOpt(H, "hud.xpWidth", 20)
		setOpt(H, "hud.xpHeight", 12)
		local root = bars(H)
		check("xpown: combat: the width and the height changed in a fight apply at once", math.abs(root.width - 238.4) < 1e-6 and root.height == 12 and clean(H), tostring(root.width))
		W.combat = false
	end

	-- 15. The mouse and the tooltip, 16. the status.
	do
		local H = world({ X = { faction = FACTION, exh = 200 } })
		local _, xp, rep = bars(H)
		check("xpown: mouse: the bars take the mouse with the tooltip on", rawOf(H, xp).mouse == true and rawOf(H, rep).mouse == true)
		setOpt(H, "hud.xpTooltip", false)
		check("xpown: mouse: with the tooltip off and the text on mouse-over they still do", rawOf(H, xp).mouse == true)
		setOpt(H, "hud.xpTextWhen", "always")
		check("xpown: mouse: with the tooltip off and the text always they do not", rawOf(H, xp).mouse == false and rawOf(H, rep).mouse == false)
		setOpt(H, "hud.xpTooltip", true)
		rawOf(H, xp).scripts.OnEnter(rawOf(H, xp))
		local lines = table.concat(H.X.tip.lines, "|")
		check("xpown: tooltip: the experience tooltip has the numbers, the rest state and the rested amount", lines:find("Experience: 300/1000 (30%)", 1, true) ~= nil and lines:find("You are Rested. (200% of normal experience)", 1, true) ~= nil
			and lines:find("Rested: 200", 1, true) ~= nil and H.X.tip.shown == true, lines)
		rawOf(H, xp).scripts.OnLeave(rawOf(H, xp))
		check("xpown: tooltip: leaving the bar hides it", H.X.tip.shown == false)
		rawOf(H, rep).scripts.OnEnter(rawOf(H, rep))
		lines = table.concat(H.X.tip.lines, "|")
		check("xpown: tooltip: the reputation tooltip has the faction, the numbers", lines:find("Honor Hold", 1, true) ~= nil and lines:find("1500 / 6000", 1, true) ~= nil, lines)
	end

	-- 17. Config chains through a choice.
	do
		local W = newWorld({ xpown = true })
		W.login()
		local function open(path)
			local def = W.ns.Def(path)
			for _, needed in ipairs({ def.needsPath, def.needsPath and W.ns.Needs(def.needsPath), def.needsPath and W.ns.Needs(def.needsPath) and W.ns.Needs(W.ns.Needs(def.needsPath)) }) do
				if needed and not W.ns.NeedMet(def, needed) then
					return false
				end
			end
			return true
		end
		check("xpown: config: with Flat UI's bar the rows of the own bar are open and the two rows of the game's bar are not", open("hud.xpWidth") and open("hud.xpShow") and open("hud.xpTooltip")
			and not open("hud.xpFill") and not open("hud.xpDividers"))
		check("xpown: config: Rested colour is open with the own bar and Rested experience on, and Reputation colour only with One colour", open("hud.xpRestedColour") and not open("hud.xpRepColour"))
		W.ns.Set("hud.xpRested", false)
		check("xpown: config: Rested colour is closed with Rested experience off", not open("hud.xpRestedColour"))
		W.ns.Set("hud.xpRested", true)
		W.ns.Set("hud.xpRepMode", "one")
		check("xpown: config: Reputation colour is open with One colour", open("hud.xpRepColour"))
		W.ns.Set("hud.xpOwn", "game")
		check("xpown: config: with the game's bar the own rows are closed, Rested colour and Reputation colour through their choices too, and Flat fill and Hide bar dividers are open",
			not open("hud.xpWidth") and not open("hud.xpRestedColour") and not open("hud.xpRepColour") and open("hud.xpFill") and open("hud.xpDividers") and open("hud.xpTexture") and open("hud.xpFrame"))
		check("xpown: config: a chain of bool rows is met as before", W.ns.NeedMet(W.ns.Def("hud.colourMagic"), "hud.auraTypes") == true and W.ns.NeedMet(W.ns.Def("hud.colourMagic"), "hud.auras") == true)
		W.ns.Set("hud.auras", false)
		check("xpown: config: and not met with the first row off", W.ns.NeedMet(W.ns.Def("hud.colourMagic"), "hud.auras") == false)
	end

	-- 19. Words on the screen.
	do
		local W = newWorld({ xpown = true })
		local want = { { "hud.xpOwn", "Experience bar", "The game's bar stays in place and is not drawn." }, { "hud.xpWidth", "Width", "100% is the game's bar at full width." },
			{ "hud.xpHeight", "Height" }, { "hud.xpShow", "Bars shown", "Reputation shows for the faction you watch." }, { "hud.xpRepMode", "Reputation fill" }, { "hud.xpRepColour", "Reputation colour" },
			{ "hud.xpTooltip", "Tooltip", "Experience, rested and standing on mouse-over." }, { "general.handsOff", "Leave the game's action bars alone",
				"Flat UI does not move, group or fade the game's micro menu, bag bar, stance and pet bars, or the game's experience bar while Experience bar is The game's, and the game's Options page has one button that opens Flat UI. Applies after a reload." } }
		local missing = {}
		for _, entry in ipairs(want) do
			local row = W.ns.Def(entry[1])
			if not (row and row.label == entry[2] and (entry[3] == nil or row.tip == entry[3])) then
				missing[#missing + 1] = entry[1]
			end
		end
		check("xpown: writing: the labels and the tips of the new rows and of the bars-left-alone row are the ones the design gives", #missing == 0, table.concat(missing, ","))
		local labels = {}
		for _, path in ipairs({ "hud.xpOwn", "hud.xpWidth", "hud.xpHeight", "hud.xpShow", "hud.xpOrder", "hud.xpGap", "hud.xpTicks", "hud.xpColour", "hud.xpRested", "hud.xpRestedColour",
			"hud.xpRepMode", "hud.xpRepColour", "hud.xpTextWhen", "hud.xpTextPlace", "hud.xpTooltip" }) do
			local row = W.ns.Def(path)
			labels[#labels + 1] = row.label .. " " .. (row.tip or "")
		end
		local text = table.concat(labels, " ")
		check("xpown: writing: no em dash, no semicolon chain and no process word in the labels and tips", not text:find("\226\128\148", 1, true) and not text:find(";", 1, true)
			and not text:lower():find("the system", 1, true) and not text:lower():find("held ", 1, true), text:sub(1, 120))
	end

	-- 22. Edit Mode opens, 23. gamepad width.
	do
		local H = world()
		local W = H.W
		W.rawOf[H.xp].isInEditMode = true
		W.rawOf[H.xp].shown = true
		event(H, "EDIT_MODE_LAYOUTS_UPDATED")
		local root = bars(H)
		check("xpown: edit mode: with the game's container shown in Edit Mode the manager stays at alpha 0, the own frame is unchanged and nothing is written on the game's frames",
			alpha(H, "StatusTrackingBarManager") == 0 and math.abs(root.width - 417.2) < 1e-6 and root.height == 8 and H.X.n == 0 and clean(H))
		W.rawOf[H.manager].GetExpectedWidth = function() return 596 end
		event(H, "UI_SCALE_CHANGED")
		check("xpown: width: with the gamepad style's width of 596 the 35% is still 417.2", math.abs(bars(H).width - 417.2) < 1e-6)
	end

	-- The look: border, dividers, texture and colours.
	do
		local H = world({ X = { faction = FACTION } })
		local W = H.W
		local _, xp, rep = bars(H)
		local function ticks(frame)
			local over = overOf(H, frame)
			local n, first = 0, nil
			for _, region in ipairs(rawOf(H, over).regions) do
				if region.layer == "ARTWORK" and region.sublevel == 2 and region.shown then
					n = n + 1
					first = first or region
				end
			end
			return n, first
		end
		check("xpown: look: each bar has Flat UI's border and background, and no dividers", W.state(xp) == "SB" and W.state(rep) == "SB" and ticks(xp) == 0)
		setOpt(H, "hud.xpFrame", false)
		check("xpown: look: Bar border off keeps the background and hides the edges", W.state(xp) == "hB" and W.state(rep) == "hB", W.state(xp))
		setOpt(H, "hud.xpFrame", true)
		setOpt(H, "hud.xpTicks", "4")
		local n, first = ticks(xp)
		check("xpown: look: Dividers 4 draws three lines, the first a quarter of the way along", n == 3 and first.points[1][4] == 417.2 / 4 - 0.5 and first.points[1][3] == "TOPLEFT", tostring(n))
		setOpt(H, "hud.xpTicks", "10")
		check("xpown: look: Dividers 10 draws nine on each bar", ticks(xp) == 9 and ticks(rep) == 9)
		setOpt(H, "hud.xpTicks", "none")
		check("xpown: look: None hides them", ticks(xp) == 0)
		setOpt(H, "hud.xpTexture", "soft")
		check("xpown: look: a Bar texture row picks the image of the fill", rawOf(H, xp).bar.texture == W.ns.BarFile("soft") and rawOf(H, rep).bar.texture == W.ns.BarFile("soft"), tostring(rawOf(H, xp).bar.texture))
		setOpt(H, "hud.xpTexture", "default")
		check("xpown: look: and the default follows the Flat UI page", rawOf(H, xp).bar.texture == (W.ns.BarTexture() or "Interface\\Buttons\\WHITE8X8"))
		setOpt(H, "hud.xpColour", "ff3366cc")
		check("xpown: look: Experience colour sets the fill", colourIs(fill(H, "xp").tint, { 0.2, 0.4, 0.8 }), tostring(fill(H, "xp").tint[1]))
		setOpt(H, "hud.xpRestedColour", "ff102030")
		H.X.exh = 100
		event(H, "UPDATE_EXHAUSTION")
		local rested = stretch(H)
		check("xpown: look: Rested colour sets the stretch at 40% opacity", rested.vertex ~= nil and math.abs(rested.vertex[1] - 16 / 255) < 1e-6 and math.abs(rested.vertex[4] - 0.4) < 1e-6, tostring(rested.vertex and rested.vertex[4]))
		-- The page off gives the game's bar back.
		setOpt(H, "hud.enabled", false)
		check("xpown: look: the page switched off gives the game's bars their alpha and mouse back and hides the frame", alpha(H, "StatusTrackingBarManager") == 1 and rawOf(H, H.exp.frame).mouse == true
			and rawOf(H, W.env.FlatUIXpBar).shown == false)
	end

	-- 13. Movers.
	do
		local LAYOUT = { systems = true, bars = true }
		local XP, XP2, OWN = "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer", "FlatUIXpBar"
		local function mworld(handsOff, xpOwn, spots)
			local X = { xp = 300, max = 1000, rest = 2, noTip = true, calls = true }
			local W = K.mwBefore({ xpown = true, handsOff = handsOff, layout = LAYOUT, saved = K.opt({ ["hud.xpOwn"] = xpOwn }, spots) }, function(W)
				stubs(W.env, X)
			end)
			W.X = X
			return W
		end
		local function centre(W, name)
			local l, b, w, h = W.rectOf(W.env[name])
			return l + w / 2, b + h / 2, l, b, w, h
		end
		local saved = { [XP] = { point = "BOTTOMLEFT", x = 40, y = 90, kind = "hud" }, [XP2] = { point = "BOTTOMLEFT", x = 40, y = 110, kind = "hud" } }
		for _, handsOff in ipairs({ true, false }) do
			local tag = handsOff and "with the bars left alone" or "with the bars not left alone"
			local W = mworld(handsOff, "flat", saved)
			W.slash("move")
			W.flush()
			check("xpown: movers: " .. tag .. " the bar has a handle named Experience bar and the two game bars have none", W.handle("Experience bar") ~= nil and W.handle("Experience bar").shown
				and W.handle("Game's experience bar") == nil and W.handle("Game's second status bar") == nil, table.concat(W.shownHandles(), ","))
			check("xpown: movers: " .. tag .. " the spots saved for the game's bars are unchanged and the game's bars are not placed", K.entry(W, XP).x == 40 and K.entry(W, XP).y == 90 and K.entry(W, XP2).y == 110
				and not W.ns.MoverHeld(XP).held and not W.ns.MoverHeld(XP2).held and K.allClean(W), K.problems(W))
		end
		local W = mworld(true, "flat")
		W.slash("move")
		W.flush()
		local cx, cy = centre(W, OWN)
		local mx = centre(W, "MainActionBar")
		local low, high
		for _, name in ipairs({ XP, XP2 }) do
			local _, _, _, cb, _, ch = centre(W, name)
			low, high = math.min(low or cb, cb), math.max(high or cb + ch, cb + ch)
		end
		check("xpown: movers: with no spot the bar is centred over the main action bar and in the room the game's status bars take", math.abs(cx - mx) < 1e-6 and math.abs(cy - (low + high) / 2) < 1e-6,
			("%s %s | %s %s"):format(cx, cy, mx, (low + high) / 2))
		W.rawOf[W.env.MainActionBar].width = 300
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.flush()
		local nx = centre(W, OWN)
		local newMain = centre(W, "MainActionBar")
		check("xpown: movers: and it follows the bar when the layout changes, until the handle is dragged", math.abs(nx - newMain) < 1e-6 and math.abs(nx - cx) > 1, ("%s %s %s"):format(nx, newMain, cx))
		W.drag("Experience bar", 400, 300)
		local dl, db = select(3, centre(W, OWN))
		check("xpown: movers: dragging the handle saves a spot and the bar goes there", K.entry(W, OWN) ~= nil and math.abs(dl - 400) < 1e-6 and math.abs(db - 300) < 1e-6, ("%s %s"):format(dl, db))
		W.fire("EDIT_MODE_LAYOUTS_UPDATED")
		W.flush()
		check("xpown: movers: a layout change leaves the saved spot", math.abs(select(3, centre(W, OWN)) - 400) < 1e-6)
		W.rightClick("Experience bar")
		W.flush()
		local rx = centre(W, OWN)
		check("xpown: movers: putting the handle back sends the bar to its place over the main bar", K.entry(W, OWN) == nil and math.abs(rx - centre(W, "MainActionBar")) < 1e-6, tostring(rx))
		local G = mworld(false, "game", saved)
		G.slash("move")
		G.flush()
		check("xpown: movers: with the game's bar and the bars not left alone the game's bars have their handles and the own bar has none", G.env.FlatUIXpBar == nil and G.handle("Experience bar") == nil
			and G.handle("Game's experience bar") ~= nil, table.concat(G.shownHandles(), ","))
	end

	-- 14. The action bar block.
	do
		local T = { layout = { systems = true, bars = true }, spot = { FlatUIBarBlock = { point = "BOTTOM", x = 0, y = 300, kind = "hud" } } }
		local function world(handsOff)
			local X = { xp = 300, max = 1000, rest = 2, noTip = true, calls = true }
			local W = K.mwBefore({ xpown = true, handsOff = handsOff, layout = T.layout, saved = K.opt({ ["barblock.enabled"] = true }, T.spot) }, function(W)
				stubs(W.env, X)
				for name, size in pairs({ StanceBar = { 200, 30 }, PetActionBar = { 150, 40 }, PossessActionBar = { 120, 35 }, MainMenuBarVehicleLeaveButton = { 32, 32 } }) do
					local frame = W.rawOf[W.env[name]]
					frame.width, frame.height = size[1], size[2]
				end
			end)
			return W
		end
		local W = world(false)
		local XP, XP2 = "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer"
		check("xpown: block: the bar takes the place of the two status bars over the block, one bar 8 high in the middle of it", K.rectIs(W, "FlatUIXpBar", 751.4, 441, 417.2, 8, 1e-6)
			and K.rectIs(W, "StanceBar", 679, 451, 200, 30, 1e-6) and K.rectIs(W, "PetActionBar", 1091, 451, 150, 40, 1e-6), K.rectText(W, "FlatUIXpBar") .. " | " .. K.rectText(W, "StanceBar"))
		check("xpown: block: the game's two status bars are not held and not placed by the block", not W.ns.MoverHeld(XP).held and not W.ns.MoverHeld(XP2).held and K.allClean(W), K.problems(W))
		local O = world(true)
		check("xpown: block: with the bars left alone the block places nothing and the bar keeps the place the Movers rules give", O.ns.MainBlock() == nil and not K.rectIs(O, "FlatUIXpBar", 751.4, 441, 417.2, 8, 1e-6))
		W.ns.Set("hud.xpOwn", "game")
		W.run(0.6)
		W.flush()
		check("xpown: block: with the game's bar the two status bars are over the block again", W.ns.MoverHeld(XP).held and W.ns.MoverHeld(XP2).held and K.rectIs(W, XP2, 679, 441, 562, 14, 1e-6), K.rectText(W, XP2))
	end

	-- 18. The setup drawing: 35% is 105 pixels of its 300.
	do
		local W, stage = TOC.sdhud.world()
		local ns = W.ns
		ns.Set("hud.xpOwn", "flat")
		local d = ns.SetupDrawings["mock-xp-micro"]
		d.build(stage)
		d.draw(stage)
		local s = d.state
		local xp = W.rawOf[s.xp.frame]
		check("xpown: setup: the drawing of Flat UI's bar is 105 of its 300 pixels wide and 7 high at 35% and 8 units, with the floor of 50% marked", math.abs(xp.width - 105) < 1e-6 and xp.height == 7
			and s.floor.shown ~= false and math.abs(W.rawOf[s.floor].width - 150) < 1e-6, tostring(xp.width) .. " " .. tostring(xp.height))
		check("xpown: setup: the parts map has the rows of the own bar", d.parts["hud.xpWidth"] == s.xp.frame and d.parts["hud.xpOwn"] == s.xp.frame and d.parts["hud.xpTextWhen"] == s.xp.words
			and d.parts["hud.xpColour"] == s.xp.bar and d.parts["hud.xpRepColour"] == s.rep.bar)
		ns.Set("hud.xpWidth", 50)
		d.draw(stage)
		check("xpown: setup: 50% is 150 pixels", math.abs(W.rawOf[s.xp.frame].width - 150) < 1e-6)
		ns.Set("hud.xpOwn", "game")
		d.draw(stage)
		check("xpown: setup: the game's bar is drawn as before, 300 pixels, and the floor is not drawn", math.abs(W.rawOf[s.xp.frame].width - 300) < 1e-6 and W.rawOf[s.floor].shown == false)
	end
end
