-- >>> eyes (begin)
-- The queue eye is put back by hooks, and the eye in the Looking For Group window has its mouse off and fades with its animated frames. Every label starts "eyes:".
do
	local KEYS = { "EyeInitial", "EyeSearchingLoop", "EyeMouseOver", "EyePokeInitial", "EyePokeLoop", "EyePokeEnd" }
	-- The eye button, its picture and its six animated frames: the alphas of all of them and the button's mouse.
	local function eyeState(W)
		local eye = W.win.names.LFGParentFramePortrait
		local r = wraw(W, eye)
		local out = { g(r.alpha), g(wa(W, r.texture)) }
		for _, key in ipairs(KEYS) do
			out[#out + 1] = g(wa(W, r[key]))
		end
		return table.concat(out, ","), tostring(r.mouse)
	end
	local function scene(saved, prep)
		return wscene(saved, nil, prep).W
	end
	local W = scene({})
	local alphas, mouse = eyeState(W)
	check("eyes: Show the eye off: the button, its picture and its six animated frames are transparent", alphas == "0,0,0,0,0,0,0,0", alphas)
	check("eyes: and the eye button takes no mouse", mouse == "false", mouse)
	W.change("windows.eye", true)
	W.flush()
	alphas, mouse = eyeState(W)
	check("eyes: Show the eye on: all of them are back at the alpha they had, and the mouse is on", alphas == "1,1,1,1,1,1,1,1" and mouse == "true", alphas .. " " .. mouse)
	W.change("windows.eye", false)
	W.flush()
	alphas, mouse = eyeState(W)
	check("eyes: off again: transparent and no mouse", alphas == "0,0,0,0,0,0,0,0" and mouse == "false", alphas .. " " .. mouse)
	-- The game shows a frame of the eye for an animation: it stays transparent.
	W.blizzard(function() wraw(W, W.win.names.LFGParentFramePortrait).EyeSearchingLoop:Show() end)
	W.flush()
	alphas = eyeState(W)
	check("eyes: a frame of the eye the game shows stays transparent", alphas == "0,0,0,0,0,0,0,0", alphas)
	check("eyes: no violation", #W.violations == 0 and #W.errors == 0, table.concat(W.violations, "|") .. table.concat(W.errors, "|"))
end
do
	-- A mouse the game had turned off stays off when the eye is shown again, and a half-faded child keeps its own alpha.
	local W = wscene({}, nil, function(W)
		local r = wraw(W, W.win.names.LFGParentFramePortrait)
		r.mouse = false
		wraw(W, r.EyeMouseOver).alpha = 0.4
	end).W
	W.change("windows.eye", true)
	W.flush()
	local eye = wraw(W, W.win.names.LFGParentFramePortrait)
	check("eyes: a mouse the game had off stays off, and a child's own alpha comes back", eye.mouse == false and g(wa(W, eye.EyeMouseOver)) == "0.4" and g(eye.alpha) == "1", tostring(eye.mouse) .. " " .. g(wa(W, eye.EyeMouseOver)))
end
do
	-- The queue eye: the game's UpdateDefaultAnchor and the minimap's SetEditModeScale put it back in the frame they run, not 0.5 seconds later.
	local K = suiteKit
	local mwBefore, opt, pts, allClean, problems = K.mwBefore, K.opt, K.pts, K.allClean, K.problems
	local function calls(W, name, call) return W.rawOf[W.env[name]].calls[call] or 0 end
	-- Frames of the addon's with an OnUpdate that are shown now.
	local function runningFrames(W)
		local n = 0
		for _, f in ipairs(W.updaters) do
			if f.scripts and f.scripts.OnUpdate and f.shown and not f.dividers then
				n = n + 1
			end
		end
		return n
	end
	local SPOT = { QueueStatusButton = { point = "TOPRIGHT", x = -200, y = -300, kind = "hud" } }
	local function world(saved, noScale)
		return mwBefore({ saved = opt({}, saved) }, function(W)
			W.bframe("QueueStatusButton", { point = { "CENTER", W.minimap, "CENTER", -68, -68 }, width = 45, height = 45, system = true,
				fields = { UpdateDefaultAnchor = function(self)
					self:ClearAllPoints()
					self:SetPoint("CENTER", W.minimap, "CENTER", -68, -68)
				end } })
			if not noScale then
				W.rawOf[W.minimap].SetEditModeScale = function(_, scale) W.rawOf[W.minimap].scaleSet = scale end
			end
		end)
	end
	local W = world(SPOT)
	local kept = pts(W, W.env.QueueStatusButton)
	check("eyes: queue eye: placed at its saved spot at login", kept == "TOPRIGHT>UIParent:TOPRIGHT -200,-300 @1", kept)
	W.blizzard(function() W.env.QueueStatusButton:UpdateDefaultAnchor() end)
	check("eyes: queue eye: the hook writes nothing inside the game's call", pts(W, W.env.QueueStatusButton) == "CENTER>MinimapCluster:CENTER -68,-68 @1", pts(W, W.env.QueueStatusButton))
	W.update(0.016)
	check("eyes: queue eye: UpdateDefaultAnchor: put back in the next OnUpdate, in the same frame", pts(W, W.env.QueueStatusButton) == kept, pts(W, W.env.QueueStatusButton))
	W.blizzard(function() W.env.MinimapCluster:SetEditModeScale(1.2) W.env.QueueStatusButton:UpdateDefaultAnchor() end)
	W.update(0.016)
	check("eyes: queue eye: the minimap's scale change: put back in the same frame", pts(W, W.env.QueueStatusButton) == kept, pts(W, W.env.QueueStatusButton))
	W.blizzard(function() W.env.MinimapCluster:SetEditModeScale(1.2) end)
	W.rawOf[W.env.QueueStatusButton].points = { { "CENTER", W.minimap, "CENTER", -68, -68 } }
	W.update(0.016)
	check("eyes: queue eye: the scale change alone, with the eye moved by the callback the hook cannot see, is put back too", pts(W, W.env.QueueStatusButton) == kept, pts(W, W.env.QueueStatusButton))
	check("eyes: queue eye: the half-second check is not running for it", runningFrames(W) == 0)
	local sets = calls(W, "QueueStatusButton", "SetPointBase")
	W.run(2, 0.5)
	check("eyes: queue eye: a frame in place is not touched again", calls(W, "QueueStatusButton", "SetPointBase") == sets)
	W.gamePlaces("QueueStatusButton", "CENTER", -68, -68, W.minimap)
	W.run(1, 0.5)
	check("eyes: queue eye: a move the two hooks do not see is not looked for every half second", pts(W, W.env.QueueStatusButton) == "CENTER>MinimapCluster:CENTER -68,-68 @1", pts(W, W.env.QueueStatusButton))
	W.blizzard(function() W.env.QueueStatusButton:UpdateDefaultAnchor() end)
	W.update(0.016)
	for _ = 1, 30 do
		W.blizzard(function() W.env.QueueStatusButton:UpdateDefaultAnchor() end)
		W.update(0.016)
	end
	check("eyes: queue eye: thirty returns in a row are all placed, none is given up on", pts(W, W.env.QueueStatusButton) == kept and not W.line("Movers"):find("stopped", 1, true), W.line("Movers"))
	W.change("movers.keep", false)
	W.flush()
	W.blizzard(function() W.env.QueueStatusButton:UpdateDefaultAnchor() end)
	W.update(0.016)
	check("eyes: queue eye: with Keep moved frames in place off it stays where the game put it", pts(W, W.env.QueueStatusButton) == "CENTER>MinimapCluster:CENTER -68,-68 @1", pts(W, W.env.QueueStatusButton))
	check("eyes: queue eye: no violation", allClean(W), problems(W))
	-- The game moves the eye while it is hidden (no queue up); showing it puts it back, in the same drawn frame.
	local H = world(SPOT)
	local hkept = pts(H, H.env.QueueStatusButton)
	H.blizzard(function() H.env.QueueStatusButton:Hide() H.env.QueueStatusButton:UpdateDefaultAnchor() end)
	H.update(0.016)
	H.blizzard(function() H.env.QueueStatusButton:Show() end)
	H.hookRun(H.env.QueueStatusButton, "OnShow")
	H.update(0.016)
	check("eyes: queue eye: moved by the game while hidden, it is put back when it is shown", pts(H, H.env.QueueStatusButton) == hkept, pts(H, H.env.QueueStatusButton))
	H.run(2, 0.5)
	check("eyes: queue eye: hidden, moved and shown: it stays there and runs no half-second check", pts(H, H.env.QueueStatusButton) == hkept and runningFrames(H) == 0, pts(H, H.env.QueueStatusButton))
	-- With the movers off the hook shows nothing.
	W.change("movers.enabled", false)
	W.flush()
	W.blizzard(function() W.env.QueueStatusButton:UpdateDefaultAnchor() end)
	check("eyes: queue eye: with the movers off a call of the game starts no frame", runningFrames(W) == 0)
	-- Another saved frame keeps the half-second check running, and it leaves the hooked eye alone.
	local B = world({ QueueStatusButton = SPOT.QueueStatusButton, UIErrorsFrame = { point = "TOP", x = -304, y = -320, kind = "hud" } })
	B.gamePlaces("QueueStatusButton", "CENTER", -68, -68, B.minimap)
	B.gamePlaces("UIErrorsFrame", "TOP", 0, -122)
	B.run(1, 0.5)
	check("eyes: queue eye: the check puts the other frame back and not the hooked eye", pts(B, B.env.UIErrorsFrame) == "TOP>UIParent:TOP -304,-320 @1" and pts(B, B.env.QueueStatusButton) == "CENTER>MinimapCluster:CENTER -68,-68 @1", pts(B, B.env.QueueStatusButton))
	-- Without the minimap's method nothing is hooked and the half-second check still keeps the eye.
	local N = world(SPOT, true)
	N.gamePlaces("QueueStatusButton", "CENTER", -68, -68, N.minimap)
	N.run(0.5)
	check("eyes: queue eye: a client without SetEditModeScale: the half-second check puts it back", pts(N, N.env.QueueStatusButton) == "TOPRIGHT>UIParent:TOPRIGHT -200,-300 @1" and runningFrames(N) == 1, pts(N, N.env.QueueStatusButton))
end
-- >>> eyes (end)
-- >>> menubtn (begin)
-- The Flat UI button in the game menu (FlatUI/Panel.lua): the hook on InitButtons places it, and its click opens setup or the options. Every label starts "game menu button:".
do
	local M = { made = 0, hid = 0, writes = 0, blizz = false }
	-- A button of the game's menu: the addon may read it and never write it.
	local function add(list, text, gap)
		local data = { layoutIndex = #list + 1, topPadding = gap and 20 or nil, text = text, enabled = true }
		data.GetText = function() return data.text end
		list[#list + 1] = setmetatable({}, { __index = data, __newindex = function() M.writes = M.writes + 1 end })
	end
	local function snap(list)
		local out = {}
		for _, b in ipairs(list) do
			out[#out + 1] = table.concat({ b:GetText(), b.layoutIndex, tostring(b.topPadding), tostring(b.enabled) }, ",")
		end
		return table.concat(out, "|")
	end
	-- The game's InitButtons: the order of GameMenuFrame.lua with the gaps as top padding on the next button.
	function M.build(menu)
		M.blizz = true
		local list = {}
		if menu.external then
			add(list, "Event")
		end
		add(list, "Options", menu.external)
		if menu.shop then
			add(list, "Shop")
		end
		add(list, "AddOns", true)
		add(list, "Edit Mode")
		add(list, "Support")
		add(list, "Macros")
		add(list, "Log Out", true)
		add(list, "Exit Game")
		add(list, "Return to Game", true)
		rawset(menu, "buttons", list)
		rawset(menu, "built", snap(list))
		M.blizz = false
	end
	local function world(shop, external, saved)
		M.made, M.hid, M.writes, M.flat = 0, 0, 0, nil
		local menu
		local W = newWorld({ saved = saved, beforeLoad = function(_, env)
			env.GAMEMENU_OPTIONS = "Options"
			menu = setmetatable({ shop = shop, external = external, buttons = {} }, { __newindex = function(t, k, v) M.writes = M.writes + 1 rawset(t, k, v) end })
			rawset(menu, "InitButtons", M.build)
			env.GameMenuFrame = menu
			env.HideUIPanel = function(frame) M.hid = M.hid + 1 M.hidden = frame end
			local base = env.CreateFrame
			env.CreateFrame = function(kind, name, parent, template)
				if template ~= "MainMenuFrameButtonTemplate" then
					return base(kind, name, parent, template)
				end
				M.made = M.made + 1
				local f = base("Frame", nil, parent)
				f.text, f.enabled, M.flat = "", true, f
				f.SetText = function(_, text) f.text = text end
				f.GetText = function() return f.text end
				f.SetEnabled = function(_, on) f.enabled = on end
				local set = f.SetScript
				f.SetScript = function(self, which, fn)
					if which == "OnClick" then
						f.onClick = fn
					else
						set(self, which, fn)
					end
				end
				return f
			end
		end })
		W.login()
		return W, menu
	end
	local function lay(f) return table.concat({ tostring(f.layoutIndex), tostring(f.topPadding), tostring(f.bottomPadding) }, ",") end

	-- 1. Place: below the gap under Options and Shop, directly above AddOns.
	local W, menu = world(true, false)
	menu:InitButtons()
	local f = M.flat
	check("game menu button: after the game builds its buttons a button Flat UI is shown", f ~= nil and f.shown ~= false and f.text == "Flat UI", f and f.text)
	check("game menu button: it comes right before AddOns, with the gap above it and the gap of AddOns cancelled", lay(f) == "2.5,20,-20", f and lay(f))
	check("game menu button: no button of the game changes, none is written, and none is added", M.writes == 0 and snap(menu.buttons) == menu.built and #menu.buttons == 9, M.writes .. " " .. #menu.buttons)
	check("game menu button: it hears both ends of combat", f.events.PLAYER_REGEN_DISABLED == true and f.events.PLAYER_REGEN_ENABLED == true)
	menu:InitButtons()
	menu:InitButtons()
	check("game menu button: three builds of the menu make one frame", M.made == 1 and M.flat == f, M.made)
	check("game menu button: and it keeps its place", lay(f) == "2.5,20,-20", lay(f))
	local W2, menu2 = world(false, false)
	menu2:InitButtons()
	check("game menu button: with no Shop it is still right before AddOns", lay(M.flat) == "1.5,20,-20", lay(M.flat))
	local W3, menu3 = world(true, true)
	menu3:InitButtons()
	check("game menu button: with a button of an event and its gap first it is still below the gap after Options", lay(M.flat) == "3.5,20,-20", lay(M.flat))

	-- 2. The setting.
	local W4, menu4 = world(true, false)
	menu4:InitButtons()
	local g4 = M.flat
	W4.change("general.menuButton", false)
	menu4:InitButtons()
	check("game menu button: Flat UI button in the game menu off: it is hidden and has no place", g4.shown == false and g4.layoutIndex == nil, tostring(g4.shown) .. " " .. tostring(g4.layoutIndex))
	W4.change("general.menuButton", true)
	menu4:InitButtons()
	check("game menu button: on again: it is back", g4.shown ~= false and lay(g4) == "2.5,20,-20" and M.made == 1, lay(g4))

	local rows = {}
	for _, page in ipairs(W.ns.PAGES) do
		for _, item in ipairs(page) do
			if page.key == "general" and (item.key == "menuButton" or item.key == "menuOpens") then
				rows[item.key] = item
			end
		end
	end
	check("game menu button: Flat UI button in the game menu starts on, and Flat UI button opens starts at Flat UI setup and needs it",
		rows.menuButton and rows.menuButton.default == true and rows.menuOpens and rows.menuOpens.default == "setup" and rows.menuOpens.needs == "menuButton")

	-- 3. The click.
	local W5, menu5 = world(true, false)
	local opened, shown = 0, false
	W5.ns.OpenSetup = function() opened = opened + 1 end
	W5.ns.PanelShown = function() return shown end
	W5.ns.OpenPanel = function() shown = not shown return shown end
	menu5:InitButtons()
	local g5 = M.flat
	g5.onClick()
	check("game menu button: a click with Flat UI setup closes the menu and opens setup, not the options", M.hid == 1 and M.hidden == menu5 and opened == 1 and not shown, M.hid .. " " .. opened)
	W5.change("general.menuOpens", "Options window")
	g5.onClick()
	check("game menu button: a click with Options window closes the menu and shows the options", M.hid == 2 and opened == 1 and shown, M.hid .. " " .. opened)
	g5.onClick()
	check("game menu button: a click while the options show leaves them shown", M.hid == 3 and shown)

	-- 4. Combat.
	g5.script(g5, "PLAYER_REGEN_DISABLED")
	W5.combat = true
	check("game menu button: combat starts: the button is off, though the lockdown starts after the event", g5.enabled == false)
	g5.onClick()
	check("game menu button: a click in combat does nothing", M.hid == 3 and opened == 1)
	W5.combat = false
	g5.script(g5, "PLAYER_REGEN_ENABLED")
	check("game menu button: combat ends: the button is on", g5.enabled == true)
	W5.combat = true
	menu5:InitButtons()
	check("game menu button: the menu builds in combat: the button is off", g5.enabled == false)
	W5.combat = false

	-- 5. A client without the menu's builder, and an error in the open.
	local made = 0
	local N = newWorld({ beforeLoad = function(_, env)
		env.GameMenuFrame = {}
		local base = env.CreateFrame
		env.CreateFrame = function(kind, name, parent, template)
			made = made + (template == "MainMenuFrameButtonTemplate" and 1 or 0)
			return base(kind, name, parent, template)
		end
	end })
	N.login()
	check("game menu button: a menu with no InitButtons: the addon loads with no error and makes no button", made == 0 and #N.errors == 0 and #N.violations == 0, #N.errors)
	local W6, menu6 = world(true, false)
	W6.ns.OpenSetup = function() error("boom", 0) end
	menu6:InitButtons()
	M.flat.onClick()
	check("game menu button: an error in the open goes to the error handler and the menu is closed", M.hid == 1 and W6.errors[1] == "boom", M.hid .. " " .. tostring(W6.errors[1]))
	check("game menu button: no violation in any world", #W.violations == 0 and #W2.violations == 0 and #W3.violations == 0 and #W4.violations == 0 and #W5.violations == 0 and #W6.violations == 0, table.concat(W.violations, " | "))
end
-- >>> menubtn (end)
-- >>> round class icons on unit frames (begin)
-- Pictures that show a class icon can be round. Every label starts "round class icon". The values are kept in one table: the main function of this file has a limit on the locals alive at once.
do
	local RU = {}
	function RU.world()
		local W = FH.ufWorld()
		W.blizzard(function() W.env.PartyFrame:InitializePartyMemberFrames() end)
		local U, env = W.uf, W.env
		U.who = { player = { player = true, class = "WARLOCK" }, target = { player = false, class = "WARRIOR", reaction = { 0.9, 0.1, 0.1 } },
			focus = { player = true, class = "ROGUE" }, party1 = { player = true, class = "PRIEST" } }
		env.UnitIsPlayer = function(unit) return U.who[unit] ~= nil and U.who[unit].player end
		env.UnitClass = function(unit)
			local who = U.who[unit]
			if who == nil then
				return "Warlock", "WARLOCK", 9
			end
			return who.class:sub(1, 1) .. who.class:sub(2):lower(), who.class, 1
		end
		env.GetClassAtlas = function(class) return "classicon-" .. class:lower() end
		env.C_Texture = env.C_Texture or { GetAtlasExists = function(name) return name == "CircleMaskScalable" end }
		W.change("unitframes.portraitStyle", "Class icon")
		W.flush()
		return W
	end
	-- The picture of the addon's own on the frame of a portrait: its frame, texture, fade texture, the disc under it and the rounded line of soft corners.
	function RU.pic(W, portrait)
		local owner, frame = W.rawOf[portrait].owner, nil
		for _, f in ipairs(W.addonFrames) do
			if not frame and f.parent == owner then
				for _, t in ipairs(f.regions) do
					if t.layer == "ARTWORK" and t.addon then
						frame = f
					end
				end
			end
		end
		local P = { frame = frame }
		for _, t in ipairs(frame and frame.regions or {}) do
			if t.layer == "ARTWORK" and t.sublevel == 7 then
				P.fade = t
			elseif t.layer == "ARTWORK" then
				P.texture = t
			elseif t.layer == "BACKGROUND" and t.sublevel == -7 then
				P.disc = t
			elseif t.layer == "OVERLAY" and t.file then
				P.line = t
			end
		end
		P.look = W.look(frame)
		return P
	end
	function RU.silent(W) return #W.violations == 0 and #W.errors == 0 and #W.out == 0 and not has(W.status(), "stopped") end

	local W = RU.world()
	local P, T = W.player, W.target
	local a = RU.pic(W, P.portrait)
	check("round class icon, unit frames: square at the defaults, with no mask and no disc", a.disc == nil and a.texture ~= nil and next(a.texture.masks) == nil and a.look.state == "SB" and W.ns.Get("unitframes.classShape") == "square",
		tostring(a.disc) .. " " .. tostring(a.texture) .. " " .. a.look.state .. " " .. tostring(W.ns.Get("unitframes.classShape")))
	RU.square = RU.pic(W, T.portrait).look.state
	W.change("unitframes.classShape", "Round")
	W.flush()
	a = RU.pic(W, P.portrait)
	RU.mask = next(a.texture.masks)
	check("round class icon, unit frames: the picture and the fade have the circle mask, the disc the other one", a.disc ~= nil and RU.mask ~= nil and RU.mask.atlas == "CircleMaskScalable" and RU.mask.allPoints == a.texture
		and a.fade.masks[RU.mask] == true and next(a.disc.masks) ~= nil and next(a.disc.masks) ~= RU.mask and next(a.disc.masks).allPoints == a.disc, W.status():sub(1, 200))
	check("round class icon, unit frames: the edges and the backdrop are hidden and the disc shows in the outline colour", a.look.state == "hb" and a.disc.shown and a.disc.color ~= nil
		and near(a.disc.color[1], a.look.r) and near(a.disc.color[2], a.look.g) and near(a.disc.color[3], a.look.b), a.look.state)
	W.change("unitframes.portraitBorder", "None")
	check("round class icon, unit frames: Portrait border None hides the disc", not RU.pic(W, P.portrait).disc.shown)
	W.change("unitframes.portraitBorder", "Thin")
	check("round class icon, unit frames: and Thin shows it again", RU.pic(W, P.portrait).disc.shown, tostring(W.ns.Get("unitframes.portraitBorder")))
	RU.t = RU.pic(W, T.portrait)
	check("round class icon, unit frames: a target that is no player keeps its face, square, with the edges it had and no mask", (RU.t.disc == nil or not RU.t.disc.shown) and RU.t.look.state == RU.square
		and next(RU.t.texture.masks) == nil, RU.t.look.state .. " " .. tostring(W.ns.Get("unitframes.portraitBorder")) .. " " .. tostring(RU.t.texture.shown) .. " " .. tostring(RU.t.disc))
	W.change("unitframes.corners", "Soft")
	W.flush()
	a, RU.t = RU.pic(W, P.portrait), RU.pic(W, T.portrait)
	check("round class icon, unit frames: with Corners Soft the rounded line is hidden while the picture is round", a.disc.shown and a.look.state == "hb"
		and (a.line == nil or not a.line.shown), a.look.state .. " " .. tostring(a.line and a.line.shown))
	W.change("unitframes.classShape", "Square")
	W.flush()
	a = RU.pic(W, P.portrait)
	check("round class icon, unit frames: back to square, the masks are off, the disc is hidden, the edges and the rounded line show", next(a.texture.masks) == nil and next(a.fade.masks) == nil
		and not a.disc.shown and a.line ~= nil and a.line.shown, a.look.state)
	W.change("unitframes.corners", "Square")
	W.change("unitframes.classShape", "Round")
	W.flush()
	check("round class icon, unit frames: a picture set to Square picture is not a class icon and stays square", (function()
		W.change("unitframes.playerPicture", "Square picture")
		W.flush()
		local b = RU.pic(W, P.portrait)
		return b.look.state == "SB" and next(b.texture.masks) == nil and not b.disc.shown
	end)())
	W.change("unitframes.playerPicture", "As Square portraits")
	-- The game's own icon on a portrait is not a class icon of the addon: Portrait style Picture shows it square, and a unit that is no player keeps it square in Class icon style.
	W.change("unitframes.portraitStyle", "Picture")
	W.uf.icon[P.frame] = "classicon-warrior"
	W.blizzard(W.env.UnitFramePortrait_Update, P.frame)
	W.flush()
	a = RU.pic(W, P.portrait)
	check("round class icon, unit frames: the game's own icon under Portrait style Picture stays square, with no mask and the square edges", a.texture.atlas == "classicon-warrior" and next(a.texture.masks) == nil
		and not (a.disc and a.disc.shown) and a.look.state == "SB", tostring(a.texture.atlas) .. " " .. a.look.state)
	W.uf.icon[P.frame] = nil
	W.blizzard(W.env.UnitFramePortrait_Update, P.frame)
	W.change("unitframes.portraitStyle", "Class icon")
	W.uf.icon[T.frame] = "classicon-warrior"
	W.blizzard(W.env.UnitFramePortrait_Update, T.frame)
	W.flush()
	RU.t = RU.pic(W, T.portrait)
	check("round class icon, unit frames: the game's own icon on a unit that is no player stays square in Class icon style", RU.t.texture.atlas == "classicon-warrior" and next(RU.t.texture.masks) == nil
		and not (RU.t.disc and RU.t.disc.shown) and RU.t.look.state == RU.square, tostring(RU.t.texture.atlas) .. " " .. RU.t.look.state)
	W.uf.icon[T.frame] = nil
	W.blizzard(W.env.UnitFramePortrait_Update, T.frame)
	-- Under Portrait border Class or reaction colour the ring is in the class colour.
	local before = { RU.pic(W, P.portrait).disc.color[1], RU.pic(W, P.portrait).disc.color[2], RU.pic(W, P.portrait).disc.color[3] }
	W.change("unitframes.portraitBorder", "Class or reaction colour")
	W.flush()
	a = RU.pic(W, P.portrait)
	check("round class icon, unit frames: Portrait border Class or reaction colour puts the ring in the colour of the outline, which changed from the thin border", a.disc.shown and near(a.disc.color[1], a.look.r) and near(a.disc.color[2], a.look.g)
		and near(a.disc.color[3], a.look.b) and not (near(before[1], a.look.r) and near(before[2], a.look.g) and near(before[3], a.look.b)), a.look.state .. " " .. tostring(a.look.r))
	W.change("unitframes.portraitBorder", "Thin")
	check("round class icon, unit frames: nothing failed", RU.silent(W), table.concat(W.violations, "|") .. table.concat(W.errors, "|"))

	-- The first round picture in combat is made after combat.
	local C = RU.world()
	RU.n = #C.addonMasks
	C.combat = true
	C.fire("PLAYER_REGEN_DISABLED")
	C.change("unitframes.classShape", "Round")
	C.flush()
	RU.c = RU.pic(C, C.player.portrait)
	check("round class icon, unit frames: a first round picture in combat stays square and makes nothing", RU.c.disc == nil and next(RU.c.texture.masks) == nil and #C.addonMasks == RU.n and RU.silent(C), tostring(RU.c.disc) .. " " .. #C.addonMasks .. " " .. table.concat(C.violations, "|") .. table.concat(C.errors, "|"))
	C.combat = false
	C.fire("PLAYER_REGEN_ENABLED")
	C.flush()
	RU.c = RU.pic(C, C.player.portrait)
	check("round class icon, unit frames: after combat it is round", RU.c.disc ~= nil and next(RU.c.texture.masks) ~= nil and RU.c.look.state == "hb" and #C.addonMasks > RU.n and RU.silent(C),
		tostring(RU.c.disc) .. " " .. tostring(RU.c.texture and next(RU.c.texture.masks)) .. " " .. RU.c.look.state .. " " .. #C.addonMasks .. "/" .. RU.n .. " " .. table.concat(C.violations, "|") .. table.concat(C.errors, "|") .. table.concat(C.out, "|"))
end
-- >>> round class icons on unit frames (end)

-- >>> auratime (begin)
-- The time text of aura buttons: no space, white, and the size of the totem times. Every label starts "aura time:".
do
	local K = suiteKit
	local T = { fmt = "hud.durationFormat", colour = "hud.durationColour", size = "unitframes.totemTimeSize", gold = "1,0.82,0,1", gameFmt = "As the game has it (8 m)", tightFmt = "No space (8m)", gameColour = "As the game has it (gold, white under 90 s)", whiteColour = "White" }
	-- The game's UpdateDuration and SecondsToTimeAbbrev (BuffFrame.lua:1387-1401, TimeUtil.lua:463-483), and the strings of enUS.
	function T.game(W, space)
		local env = W.env
		env.COOLDOWN_DURATION_MIN = space and "%d m" or "%dm"
		env.SECOND_ONELETTER_ABBR, env.MINUTE_ONELETTER_ABBR, env.HOUR_ONELETTER_ABBR, env.DAY_ONELETTER_ABBR = "%d s", "%d m", "%d h", "%d d"
		env.SecondsToTimeAbbrev = function(seconds)
			if seconds >= 129600 then return env.DAY_ONELETTER_ABBR, math.ceil(seconds / 86400) end
			if seconds >= 5400 then return env.HOUR_ONELETTER_ABBR, math.ceil(seconds / 3600) end
			if seconds >= 90 then return env.MINUTE_ONELETTER_ABBR, math.ceil(seconds / 60) end
			return env.SECOND_ONELETTER_ABBR, seconds
		end
		env.AuraButtonMixin = { UpdateDuration = function(self, timeLeft)
			if rawequal(timeLeft, SECRET) then
				self.Duration:SetText("withheld")
				self.Duration:SetVertexColor(1, 0.82, 0)
				return
			end
			self.Duration:SetShown(timeLeft ~= nil)
			if timeLeft ~= nil then
				self.Duration:SetFormattedText(env.SecondsToTimeAbbrev(timeLeft))
				if timeLeft < 90 then self.Duration:SetVertexColor(1, 1, 1) else self.Duration:SetVertexColor(1, 0.82, 0) end
			end
		end }
	end
	-- A button with its time text: with the game's own copy of the function, or without one for a totem button, which calls the mixin by table.
	function T.button(W, parent, copy)
		local button, raw = W.bframe(nil, { parent = parent, fields = copy and { UpdateDuration = W.env.AuraButtonMixin.UpdateDuration } or nil })
		local text = W.Rr(button, nil, { layer = "OVERLAY", sublevel = 0, kind = "FontString" })
		raw.Duration = text
		return button, W.rawOf[text]
	end
	function T.world(saved, space)
		return K.mwBefore({ saved = K.opt(saved or {}) }, function(W)
			T.game(W, space)
			local buff = W.bframe("BuffFrame")
			local one, two = T.button(W, buff, true), T.button(W, buff, true)
			W.rawOf[buff].auraFrames = { one, two }
			T.totem = T.button(W, W.bframe("TotemFrame"), false)
		end)
	end
	function T.tick(W, button, seconds)
		W.blizzard(function() button.UpdateDuration(button, seconds) end)
	end
	function T.totemTick(W, button, seconds)
		W.blizzard(function() W.env.AuraButtonMixin.UpdateDuration(button, seconds) end)
	end
	function T.colourOf(raw) return table.concat(raw.vertex, ",") end

	local W = T.world()
	local buff = W.env.BuffFrame
	local first, second = W.rawOf[buff].auraFrames[1], W.rawOf[buff].auraFrames[2]
	local raw = W.rawOf[W.rawOf[first].Duration]
	T.tick(W, first, 480)
	check("aura time: 8 m becomes 8m and the gold becomes white", raw.text == "8m" and T.colourOf(raw) == "1,1,1,1", tostring(raw.text) .. " " .. T.colourOf(raw))
	T.tick(W, first, 480)
	check("aura time: a second tick keeps it", raw.text == "8m" and T.colourOf(raw) == "1,1,1,1", tostring(raw.text))
	T.tick(W, first, 45)
	check("aura time: 45 s becomes 45s", raw.text == "45s", tostring(raw.text))
	T.tick(W, first, 7200)
	check("aura time: hours lose the space too", raw.text == "2h", tostring(raw.text))
	check("aura time: the game and one hook wrote the text of each tick, not two hooks", (raw.calls.SetFormattedText or 0) == 4 * 2, tostring(raw.calls.SetFormattedText))
	-- A button the game makes after the file loads copies the followed function and is not followed again.
	local late = T.button(W, buff, false)
	W.rawOf[late].UpdateDuration = W.env.AuraButtonMixin.UpdateDuration
	local list = W.rawOf[buff].auraFrames
	list[#list + 1] = late
	W.fire("PLAYER_ENTERING_WORLD", false, false)
	T.tick(W, late, 480)
	local lateRaw = W.rawOf[W.rawOf[late].Duration]
	check("aura time: a button made later is followed once by the mixin and a second pass adds no hook", lateRaw.text == "8m" and (lateRaw.calls.SetFormattedText or 0) == 2, tostring(lateRaw.text) .. " " .. tostring(lateRaw.calls.SetFormattedText))
	local mixinFn = W.env.AuraButtonMixin.UpdateDuration
	check("aura time: a button made before is hooked itself, and one made later keeps the function of the mixin", INSTHOOK.wrapped(W, first, "UpdateDuration") and INSTHOOK.wrapped(W, second, "UpdateDuration")
		and rawget(first, "UpdateDuration") ~= mixinFn and W.rawOf[late].UpdateDuration == mixinFn and rawget(late, "UpdateDuration") == nil)
	-- The game's look.
	W.change(T.fmt, T.gameFmt)
	T.tick(W, first, 480)
	check("aura time: Duration format as the game has it writes nothing", raw.text == "8 m", tostring(raw.text))
	local before = raw.calls.SetVertexColor
	W.change(T.colour, T.gameColour)
	T.tick(W, first, 480)
	check("aura time: Duration colour as the game has it leaves the gold", T.colourOf(raw) == T.gold and raw.calls.SetVertexColor == before + 1, T.colourOf(raw) .. " " .. tostring(raw.calls.SetVertexColor))
	W.change(T.fmt, T.tightFmt)
	W.change(T.colour, T.whiteColour)
	-- A page that is off.
	W.change("hud.enabled", false)
	T.tick(W, first, 480)
	check("aura time: with the Minimap and buffs page off the game's look stays", raw.text == "8 m" and T.colourOf(raw) == T.gold, tostring(raw.text) .. " " .. T.colourOf(raw))
	W.change("hud.enabled", true)
	-- A button with no time is hidden and left alone.
	T.tick(W, first, nil)
	check("aura time: a button with no time is left alone", raw.shown == false and raw.text == "8 m" and T.colourOf(raw) == T.gold, tostring(raw.shown) .. " " .. tostring(raw.text) .. " " .. T.colourOf(raw))
	-- An example button in the window is left alone, and a withheld time on a buff says nothing in the status.
	W.rawOf[first].isExample = true
	T.tick(W, first, 480)
	W.rawOf[first].isExample = nil
	check("aura time: an example button keeps the game's look", raw.text == "8 m" and T.colourOf(raw) == T.gold, tostring(raw.text) .. " " .. T.colourOf(raw))
	T.tick(W, first, SECRET)
	check("aura time: a withheld time on a buff has no status line", not has(W.status(), "Duration format"), W.status())
	check("aura time: no violation", K.allClean(W), K.problems(W))

	-- A locale that keeps the space in its cooldown form keeps it here.
	local S = T.world(nil, true)
	local sButton = S.rawOf[S.env.BuffFrame].auraFrames[1]
	local sRaw = S.rawOf[S.rawOf[sButton].Duration]
	T.tick(S, sButton, 480)
	check("aura time: a locale with a space in its cooldown form keeps 8 m and still gets the white", sRaw.text == "8 m" and T.colourOf(sRaw) == "1,1,1,1", tostring(sRaw.text))

	-- Totems: the time size is set once, 100 gives the font back, and a page that is off gives it back too.
	local U = T.world({ ["hud.enabled"] = false })
	local totem = T.totem
	local tRaw = U.rawOf[U.rawOf[totem].Duration]
	local gets = 0
	local getFont = tRaw.GetFont
	tRaw.GetFont = function(...) gets = gets + 1 return getFont(...) end
	T.totemTick(U, totem, 480)
	check("aura time: a totem time is 80% of the game's size, white and tight, with the Minimap and buffs page off", tRaw.font ~= nil and math.abs(tRaw.font[2] - 9.6) < 0.01 and tRaw.text == "8m" and T.colourOf(tRaw) == "1,1,1,1",
		tostring(tRaw.font and tRaw.font[2]) .. " " .. tostring(tRaw.text))
	T.totemTick(U, totem, 479)
	T.totemTick(U, totem, 478)
	check("aura time: the size of a totem time is set once and not looked at on each tick", gets == 1, tostring(gets))
	U.change(T.size, 100)
	T.totemTick(U, totem, 477)
	check("aura time: a totem time size of 100 gives the game's font back", math.abs(tRaw.font[2] - 12) < 0.01, tostring(tRaw.font[2]))
	U.change(T.size, 60)
	T.totemTick(U, totem, 476)
	check("aura time: a totem time size of 60 sets 7.2", math.abs(tRaw.font[2] - 7.2) < 0.01, tostring(tRaw.font[2]))
	U.change("unitframes.enabled", false)
	T.totemTick(U, totem, 475)
	check("aura time: with the Unit frames page off the size is back and the text is the game's", math.abs(tRaw.font[2] - 12) < 0.01 and tRaw.text == "8 m", tostring(tRaw.font[2]) .. " " .. tostring(tRaw.text))
	U.change("unitframes.enabled", true)
	-- A withheld totem time: the format is skipped, the colour is set, and the status says so.
	U.change(T.size, 80)
	T.totemTick(U, totem, SECRET)
	check("aura time: a withheld totem time keeps the game's text, takes the white and the status says so", tRaw.text == "withheld" and T.colourOf(tRaw) == "1,1,1,1"
		and has(U.status(), "Duration format: the game withholds totem times in fights, and they keep the game's format."), tostring(tRaw.text))
	U.change("unitframes.totemTimer", false)
	local greyed = U.enabled(T.size)
	local colours = tRaw.calls.SetVertexColor
	T.totemTick(U, totem, 474)
	check("aura time: a totem time that Totem time left hides is not coloured, so its opacity stays 0 (only the game's own call runs)", tRaw.calls.SetVertexColor == colours + 1, tostring(tRaw.calls.SetVertexColor) .. " " .. tostring(colours))
	-- The join with UnitExtras.lua (the opacity itself is checked in the ms-ufpart block): a Totems part that has stopped hides nothing, so it takes the white.
	for _ = 1, 5 do U.ns.UnitFrameExtra.run("Totem timers", function() error("test") end) end
	T.totemTick(U, totem, 473)
	check("aura time: with the Totems part stopped the totem time takes the white", tRaw.calls.SetVertexColor == colours + 3 and T.colourOf(tRaw) == "1,1,1,1", tostring(tRaw.calls.SetVertexColor) .. " " .. tostring(colours))
	U.change("unitframes.totemTimer", true)
	check("aura time: Totem time size is greyed while Totem time left is off", greyed == false and U.enabled(T.size) == true, tostring(greyed))
	check("aura time: no violation with a totem", K.allClean(U), K.problems(U))
	-- Both pages off at login: turning one on follows the buttons without a loading screen.
	local L = T.world({ ["hud.enabled"] = false, ["unitframes.enabled"] = false })
	local lFirst = L.rawOf[L.env.BuffFrame].auraFrames[1]
	local lRaw = L.rawOf[L.rawOf[lFirst].Duration]
	T.tick(L, lFirst, 480)
	local before = lRaw.text
	L.change("hud.enabled", true)
	T.tick(L, lFirst, 480)
	check("aura time: a page turned on after login formats at once", before == "8 m" and lRaw.text == "8m", tostring(before) .. " " .. tostring(lRaw.text))
	-- Unit frames alone turned on after login follows the totem times too.
	local M = T.world({ ["hud.enabled"] = false, ["unitframes.enabled"] = false })
	local mRaw = M.rawOf[M.rawOf[T.totem].Duration]
	T.totemTick(M, T.totem, 480)
	local mBefore = mRaw.text
	M.change("unitframes.enabled", true)
	T.totemTick(M, T.totem, 480)
	check("aura time: Unit frames turned on after login formats a totem time at once", mBefore == "8 m" and mRaw.text == "8m", tostring(mBefore) .. " " .. tostring(mRaw.text))
end
-- >>> auratime (end)

-- Round buttons that addons put on the minimap (MapButtons.lua): frames named LibDBIcon10_ that are children of Minimap.
do
	local MB = {}
	-- A minimap of 176 by 174 centred at cx, with the screen centre at 1000, and buttons of 22 by 22 at the left edge. names: the button names.
	function MB.world(cx, names, scale)
		local W = newWorld({})
		W.login()
		W.flush()
		local map, mraw = W.B(nil, {}, { name = "Minimap", width = 176, height = 174 })
		mraw.GetCenter = function() return cx, 500 end
		W.rawOf[W.env.UIParent].GetCenter = function() return 1000, 500 end
		-- The effective scale of the map is 1 unless the call gives one (Edit Mode size); the screen's is 1.
		mraw.GetEffectiveScale = function() return scale or 1 end
		W.rawOf[W.env.UIParent].GetEffectiveScale = function() return 1 end
		W.env.Minimap = map
		-- C_Timer.NewTicker(seconds, fn): fn every seconds until the ticker's Cancel; W.ticker is the last one made.
		W.env.C_Timer.NewTicker = function(delay, fn)
			if not isnum(delay) or delay <= 0 or type(fn) ~= "function" then
				bad(W, "C_Timer.NewTicker arguments")
			end
			local ticker = { stopped = false }
			function ticker.Cancel() ticker.stopped = true end
			local function step()
				if not ticker.stopped then
					W.seq = W.seq + 1
					W.timers[#W.timers + 1] = { due = W.now + delay, seq = W.seq, fn = step, delay = delay }
					fn()
				end
			end
			W.seq = W.seq + 1
			W.timers[#W.timers + 1] = { due = W.now + delay, seq = W.seq, fn = step, delay = delay }
			W.ticker = ticker
			return ticker
		end
		W.mb = { map = map, mraw = mraw, buttons = {}, log = {} }
		for _, name in ipairs(names) do
			MB.add(W, name)
		end
		return W
	end
	function MB.add(W, name, more)
		local o = { name = name, width = 22, height = 22, objectType = "Button" }
		for k, v in pairs(more or {}) do o[k] = v end
		local button, raw = W.B(W.mb.map, {}, o)
		raw.points = { { "LEFT", W.mb.map, "LEFT", 5, 6 } }
		raw.minimapPos = { angle = 45 }
		for k, v in pairs(more and more.fault or {}) do raw.fault[k] = v end
		local clear, set = raw.ClearAllPoints, raw.SetPoint
		raw.ClearAllPoints = function(...) W.mb.log[#W.mb.log + 1] = "clear"; return clear(...) end
		raw.SetPoint = function(...) W.mb.log[#W.mb.log + 1] = "set"; return set(...) end
		W.mb.mraw.children[#W.mb.mraw.children + 1] = button
		W.mb.buttons[name] = raw
		return raw
	end
	-- "dx,dy" of the one CENTER point of a button, or the number of its points when it is not so.
	function MB.at(raw)
		local p = raw.points[1]
		if #raw.points == 1 and p[1] == "CENTER" then
			return ("%g,%g"):format(p[4], p[5])
		end
		return #raw.points
	end
	function MB.pass(W) W.advance(1) end
	function MB.names(n)
		local list = {}
		for i = 1, n do list[i] = "LibDBIcon10_" .. string.char(64 + i) end
		return list
	end

	do
		local W = MB.world(1894, MB.names(3))
		check("addon buttons: the row is a choice with the default Column beside the map, and its callback is there", W.ns.Get("hud.addonButtons") == "edge" and type(W.ns.MapButtonsChanged) == "function")
		local order = {}
		for line in io.lines(ADDON_DIR .. "/FlatUI.toc") do
			if line:match("%.lua%s*$") then order[#order + 1] = (line:gsub("%s+$", "")) end
		end
		local pos = {}
		for index, file in ipairs(order) do pos[file] = index end
		check("addon buttons: MapButtons.lua loads right after Hud.lua", pos["MapButtons.lua"] == pos["Hud.lua"] + 1)
		check("addon buttons: before the first pass the buttons stay where the library put them", MB.at(W.mb.buttons.LibDBIcon10_A) == 1)
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local a, b, c = W.mb.buttons.LibDBIcon10_A, W.mb.buttons.LibDBIcon10_B, W.mb.buttons.LibDBIcon10_C
		check("addon buttons: edge puts the buttons in a column on the left for a map right of the screen centre, in the order of their names", MB.at(a) == "-102,76" and MB.at(b) == "-102,52"
			and MB.at(c) == "-102,28", MB.at(a) .. " " .. MB.at(b) .. " " .. MB.at(c))
		check("addon buttons: each point is on the centre of the map", a.points[1][2] == W.mb.map and a.points[1][3] == "CENTER")
		local order2 = table.concat(W.mb.log, ",")
		check("addon buttons: ClearAllPoints comes before each SetPoint", order2 == "clear,set,clear,set,clear,set", order2)
		MB.pass(W)
		check("addon buttons: a pass that finds the buttons in place makes no call", #W.mb.log == 6, #W.mb.log)
		check("addon buttons: no error and the saved data of the button is unchanged", #W.errors == 0 and a.minimapPos.angle == 45 and a.minimapPos.hide == nil)
		a.points = { { "LEFT", W.mb.map, "LEFT", 5, 6 } }
		MB.pass(W)
		check("addon buttons: a button the library places again is placed on the next pass", MB.at(a) == "-102,76")
		MB.add(W, "LibDBIcon10_D")
		MB.pass(W)
		check("addon buttons: a button made after login is placed on the next pass", MB.at(W.mb.buttons.LibDBIcon10_D) == "-102,4", MB.at(W.mb.buttons.LibDBIcon10_D))
		W.change("hud.addonButtons", "Row under the map")
		W.flush()
		check("addon buttons: bar starts below the coordinate text, at the left of the map", MB.at(a) == "-77,-122" and MB.at(b) == "-53,-122" and MB.at(c) == "-29,-122", MB.at(a) .. " " .. MB.at(b) .. " " .. MB.at(c))
		W.change("hud.addonButtons", "Where each addon puts them")
		W.flush()
		check("addon buttons: leave gives back the recorded points", #a.points == 1 and a.points[1][1] == "LEFT" and a.points[1][2] == W.mb.map and a.points[1][4] == 5 and a.points[1][5] == 6
			and #W.mb.buttons.LibDBIcon10_D.points == 1 and W.mb.buttons.LibDBIcon10_D.points[1][1] == "LEFT")
		check("addon buttons: leave stops the ticker", W.ticker ~= nil and W.ticker.stopped == true)
		local n = #W.mb.log
		W.advance(1)
		W.advance(1)
		W.advance(1)
		check("addon buttons: with leave no pass touches a button", #W.mb.log == n and #W.errors == 0)
	end

	-- A map left of the screen centre puts the column on the right.
	do
		local W = MB.world(500, MB.names(2))
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		check("addon buttons: edge puts the column on the right for a map left of the screen centre", MB.at(W.mb.buttons.LibDBIcon10_A) == "102,76" and MB.at(W.mb.buttons.LibDBIcon10_B) == "102,52",
			MB.at(W.mb.buttons.LibDBIcon10_A))
	end

	-- A map with no button of the library sets no timer, and a button made later is found when an addon loads.
	do
		local W = MB.world(1894, {})
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		check("addon buttons: a map with no button of the library sets no timer", #W.timers == 0 and W.ticker == nil and #W.errors == 0)
		local late = MB.add(W, "LibDBIcon10_A")
		W.fire("ADDON_LOADED", "SomeAddon")
		W.advance(0)
		check("addon buttons: a button made later is placed when an addon loads", MB.at(late) == "-102,76" and W.ticker ~= nil and W.ticker.stopped == false)
	end

	-- The order is the order of the names, not the order the buttons were made in.
	do
		local W = MB.world(1894, { "LibDBIcon10_C", "LibDBIcon10_A", "LibDBIcon10_B" })
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local B = W.mb.buttons
		check("addon buttons: the order of the column is the order of the names, whatever order the buttons were made in", MB.at(B.LibDBIcon10_A) == "-102,76" and MB.at(B.LibDBIcon10_B) == "-102,52"
			and MB.at(B.LibDBIcon10_C) == "-102,28")
	end

	-- A full column starts the next one, and a full row starts the next one.
	do
		local W = MB.world(1894, MB.names(9))
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local B = W.mb.buttons
		check("addon buttons: a column holds seven, and the eighth starts a second column a button width plus 2 further out", MB.at(B.LibDBIcon10_G) == "-102,-68" and MB.at(B.LibDBIcon10_H) == "-126,76"
			and MB.at(B.LibDBIcon10_I) == "-126,52", MB.at(B.LibDBIcon10_G) .. " " .. MB.at(B.LibDBIcon10_H))
		W.change("hud.addonButtons", "Row under the map")
		W.flush()
		check("addon buttons: bar wraps at the width of the map", MB.at(B.LibDBIcon10_G) == "67,-122" and MB.at(B.LibDBIcon10_H) == "-77,-146" and MB.at(B.LibDBIcon10_I) == "-53,-146",
			MB.at(B.LibDBIcon10_G) .. " " .. MB.at(B.LibDBIcon10_H))
	end

	-- Buttons that are not touched, and answers that are withheld.
	do
		local W = MB.world(1894, { "LibDBIcon10_A" })
		MB.add(W, "LibDBIcon10_B", { protected = true })
		MB.add(W, "MyOwnButton")
		MB.add(W, "LibDBIcon10_C", { fault = { name = "secret" } })
		MB.add(W, "LibDBIcon10_D", { hidden = true })
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local B = W.mb.buttons
		check("addon buttons: a protected button, a button with another name, one with a secret name and a hidden one are skipped with no error", MB.at(B.LibDBIcon10_A) == "-102,76"
			and #B.LibDBIcon10_B.points == 1 and B.LibDBIcon10_B.points[1][1] == "LEFT" and B.MyOwnButton.points[1][1] == "LEFT" and B.LibDBIcon10_C.points[1][1] == "LEFT"
			and B.LibDBIcon10_D.points[1][1] == "LEFT" and #W.errors == 0, #W.errors)
		check("addon buttons: nothing is called on a protected button", B.LibDBIcon10_B.calls.ClearAllPoints == nil and B.LibDBIcon10_B.calls.SetPoint == nil)
		W.change("hud.addonButtons", "Where each addon puts them")
		W.flush()
		W.mb.mraw.fault.children = "secret"
		W.change("hud.addonButtons", "Column beside the map")
		W.flush()
		check("addon buttons: a withheld list of children stops the pass with no error", MB.at(B.LibDBIcon10_A) == 1 and #W.errors == 0)
		W.mb.mraw.fault.children = nil
		W.mb.mraw.fault.size = "secret"
		MB.pass(W)
		check("addon buttons: a withheld size of the map stops the pass with no error", MB.at(B.LibDBIcon10_A) == 1 and #W.errors == 0)
		W.mb.mraw.fault.size = nil
		MB.pass(W)
		check("addon buttons: the pass runs again when the answers are plain", MB.at(B.LibDBIcon10_A) == "-102,76")
	end

	-- Edit Mode size: the centres are compared in screen units.
	do
		local W = MB.world(600, MB.names(2), 2)
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		check("addon buttons: a map at scale 2 with centre 600 is right of the screen centre, so the column is on the left", MB.at(W.mb.buttons.LibDBIcon10_A) == "-102,76", MB.at(W.mb.buttons.LibDBIcon10_A))
		local W2 = MB.world(1894, MB.names(1), 0.25)
		W2.fire("PLAYER_ENTERING_WORLD")
		W2.flush()
		check("addon buttons: a map at scale 0.25 with centre 1894 is left of the screen centre, so the column is on the right", MB.at(W2.mb.buttons.LibDBIcon10_A) == "102,76", MB.at(W2.mb.buttons.LibDBIcon10_A))
		local W3 = MB.world(1894, MB.names(1))
		W3.mb.mraw.GetEffectiveScale = function() return SECRET end
		W3.fire("PLAYER_ENTERING_WORLD")
		W3.flush()
		check("addon buttons: a missing scale of the map stops the pass with no error", MB.at(W3.mb.buttons.LibDBIcon10_A) == 1 and #W3.errors == 0)
	end

	-- The row follows the part switch and a change of profile.
	do
		local W = MB.world(1894, MB.names(2))
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local a = W.mb.buttons.LibDBIcon10_A
		W.change("hud.enabled", false)
		W.flush()
		check("addon buttons: the part off gives the recorded points back and stops the ticker", MB.at(a) == 1 and a.points[1][1] == "LEFT" and W.ticker.stopped == true and #W.errors == 0, MB.at(a) .. " " .. #W.errors)
		W.change("hud.enabled", true)
		W.flush()
		check("addon buttons: the part on again places the buttons and starts the ticker", MB.at(a) == "-102,76" and W.ticker.stopped == false and #W.errors == 0, MB.at(a) .. " " .. #W.errors)
		W.ns.NewProfile("Quiet")
		W.ns.Set("hud.addonButtons", "leave")
		W.flush()
		check("addon buttons: a profile with leave gives the points back", MB.at(a) == 1)
		W.ns.UseProfile("Default")
		W.flush()
		check("addon buttons: a change back to a profile with edge places the buttons at once", MB.at(a) == "-102,76" and W.ticker.stopped == false and #W.errors == 0, MB.at(a))
		W.ns.UseProfile("Quiet")
		W.flush()
		check("addon buttons: a change to a profile with leave gives the points back at once", MB.at(a) == 1 and W.ticker.stopped == true)
	end

	-- A column that fits exactly does not wrap: a map 166 high holds seven buttons 22 high with 2 between.
	do
		local W = MB.world(1894, MB.names(8))
		W.mb.mraw.height = 166
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		local B = W.mb.buttons
		check("addon buttons: seven buttons fill a column exactly and the eighth starts the next", MB.at(B.LibDBIcon10_G) == "-102,-72" and MB.at(B.LibDBIcon10_H) == "-126,72",
			MB.at(B.LibDBIcon10_G) .. " " .. MB.at(B.LibDBIcon10_H))
	end

	-- Guards: a forbidden button, a button that becomes protected, a secret size of a button, a secret or forbidden map.
	do
		local W = MB.world(1894, { "LibDBIcon10_A" })
		MB.add(W, "LibDBIcon10_B", { forbidden = true })
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		check("addon buttons: a forbidden button is skipped with no error and no violation", MB.at(W.mb.buttons.LibDBIcon10_A) == "-102,76" and W.mb.buttons.LibDBIcon10_B.points[1][1] == "LEFT" and #W.errors == 0 and #W.violations == 0, #W.errors)
		local a = W.mb.buttons.LibDBIcon10_A
		a.protected = true
		W.change("hud.addonButtons", "Where each addon puts them")
		W.flush()
		check("addon buttons: leave makes no call on a button that has become protected", MB.at(a) == "-102,76" and a.calls.ClearAllPoints == 1 and #W.errors == 0, tostring(a.calls.ClearAllPoints))
	end
	do
		local W = MB.world(1894, { "LibDBIcon10_A", "LibDBIcon10_B" })
		W.mb.buttons.LibDBIcon10_B.fault.size = "secret"
		W.fire("PLAYER_ENTERING_WORLD")
		W.flush()
		W.advance(1)
		W.advance(1)
		check("addon buttons: a secret size of a button stops the pass with no error, every second", #W.errors == 0 and MB.at(W.mb.buttons.LibDBIcon10_B) == 1, #W.errors)
		local W2 = MB.world(1894, { "LibDBIcon10_A" })
		W2.mb.mraw.forbidden = true
		W2.fire("PLAYER_ENTERING_WORLD")
		W2.flush()
		check("addon buttons: a forbidden map stops the pass with no error", MB.at(W2.mb.buttons.LibDBIcon10_A) == 1 and #W2.errors == 0, #W2.errors)
	end
end
io.write(("%d passed, %d failed\n"):format(passed, failed))
if rawget(_G, "ADDON_DIR_OVERRIDE") then
	return failed
end
os.exit(failed == 0 and 0 or 1)
